INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'No princípio, Deus criou os céus e a terra. A terra era sem forma e vazia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Havia escuridão sobre a face do abismo, e o Espírito de Deus Se movia sobre a superfície das águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Deus disse: \"Haja luz\". E houve luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'E Deus viu que a luz era boa; então, separou a luz da escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Deus chamou a luz dia e chamou a escuridão noite. Houve manhã e anoitecer, o primeiro dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'E Deus disse: \"Que haja firmamento entre as águas, e haja separação entre águas e águas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'E Deus fez o firmamento e separou as águas que estavam debaixo do firmamento das águas que estavam em cima do firmamento. E assim aconteceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'E Deus chamou o firmamento de céus. Houve manhã e anoitecer, o segundo dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'E Deus disse: \"Ajuntem-se as águas debaixo do céu, num só lugar, e apareça porção seca\". E assim aconteceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Deus chamou a porção seca de terra e, ao ajuntamento das águas, de mares. E Deus viu que isso era bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'E Deus disse: \"Produza a terra vegetação, plantas que deem sementes e árvores frutíferas que deem frutos, conforme a sua espécie, cuja semente esteja no fruto\". E assim aconteceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'A terra produziu vegetação, plantas que davam semente, segundo a sua espécie, e árvores frutíferas cuja semente estava no seu fruto. E Deus viu que isso era bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Houve manhã e anoitecer, o terceiro dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Deus disse: \"Haja luzeiros no firmamento dos céus para separar o dia da noite; que sirvam como sinais para estações, dias e anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Que sejam luzeiros no firmamento dos céus para iluminar a terra\". E assim aconteceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Deus fez dois grandes luzeiros: o maior para governar o dia e o menor para governar a noite. Também fez as estrelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Deus os colocou no firmamento dos céus para iluminar a terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'para governar o dia e a noite e separar a luz da escuridão. E Deus viu que isso era bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Houve manhã e anoitecer, o quarto dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Deus disse: \"Que haja multidões de criaturas vivas nas águas, e que as aves voem por cima da terra, abaixo do firmamento dos céus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Deus criou os grandes animais marinhos e todos os seres viventes que se movem e que povoam as águas, segundo as suas espécies; e todas as aves, segundo as suas espécieis. E Deus viu que isso era bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'E Deus os abençoou, dizendo: \"Sede frutíferos, multiplicai-vos e enchei as águas dos mares. Que as aves multipliquem-se na terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Houve manhã e anoitecer, o quinto dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'E Deus disse: \"Que a terra produza seres viventes, cada um de acordo com sua própria espécie: animais domésticos, animais selvagens e os demais seres vivos da terra; cada um de acordo com a sua própria espécie. E assim aconteceu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Deus fez os animais selvagens da terra, conforme a sua espécie, os animais de criação, conforme a sua espécie, e os demais seres vivos da terra, conforme a sua espécie. Ele viu que isso era bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'E disse Deus: \"Façamos o homem à Nossa imagem, conforme a Nossa semelhança. Que ele exerça domínio sobre os peixes do mar, sobre as aves dos céus, sobre todos os animais de criação, sobre toda a terra e sobre todos os seres vivos que rastejam sobre a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Deus criou, então, o homem a Sua imagem, à imagem de Deus o criou; macho e fêmea Deus os criou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Deus os abençoou e lhes disse: \"Sede frutíferos e multiplicai-vos, enchei a terra e subjugai-a. Dominai sobre todos os peixes do mar, sobre as aves dos céus e sobre todo ser vivente que rasteja pela terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Deus disse: \"Eis que vos tenho dado todas as plantas que dão semente que estão sobre a face de toda a terra e todas as árvores que dão frutos com semente; elas vos servirão de alimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Para todos os animais selvagens da terra, para todas as aves dos céus, para todos os seres vivos que rastejam pela terra, e para todas as criaturas que têm fôlego de vida, toda planta verde lhes será por alimento\". E assim aconteceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'E viu Deus tudo quanto fizera, e eis que isso era muito bom. Houve manhã e anoitecer, o sexto dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Assim foram concluídos os céus e a terra e tudo que neles há.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'No sétimo dia, Deus terminou o trabalho que tinha feito e, naquele dia, Ele descansou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'E Deus abençoou o sétimo dia e o santificou, porque nele descansou de toda a obra que havia criado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'São essas as origens dos céus e da terra, quando foram criados. Quando Deus Yahweh fez os céus e a terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'ainda não havia nenhum arbusto no campo e nenhuma planta havia brotado, porque Deus Yahweh não havia feito chover sobre a terra e não havia nenhum homem para trabalhar no solo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Mas uma neblina subia da terra e regava toda a superfície do solo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Então, Deus Yahweh formou o homem do pó da terra, soprou-lhe nas narinas o fôlego de vida e o homem se tornou um ser vivente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Deus Yahweh plantou um jardim na direção do oriente, no Éden, e lá colocou o homem que Ele havia formado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Do solo, Deus Yahweh fez brotar todo tipo de árvores agradáveis à vista e boa para o alimento. Isso incluía a árvore da vida, que estava no meio do jardim, e a árvore do conhecimento do bem e do mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Um rio saía do Éden, regava o jardim e dali se dividia e se transformava em quatro rios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'O nome do primeiro é Pisom. Esse é o que rodeia a terra de Havilá, onde há ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'O ouro dessa terra é bom. Ali existe também bdélio e a pedra de ônix.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'O nome do segundo rio é Giom. Esse percorre toda a terra de Cuxe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'O nome do terceiro rio é Tigre. Esse é o que corre pelo oriente da Assíria. O quarto rio é o Eufrates.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Deus Yahweh tomou o homem e o colocou dentro do jardim do Éden para que ele o guardasse e o cultivasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Deus Yahweh ordenou ao homem, dizendo: \"De toda árvore deste jardim, tu poderás comer livremente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Mas, da árvore do conhecimento do bem e do mal, tu não poderás comer, porque, no dia em que dela comeres, certamente morrerás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Então, Deus Yahweh disse: \"Não é bom que o homem esteja só. Far-lhe-ei uma auxiliadora que lhe seja idônea\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Havendo, pois, Deus Yahweh formado da terra todos os animais do campo e todas as aves dos céus, então, Ele os trouxe ao homem para ver como lhes chamaria. E o nome que o homem desse a cada ser vivo, esse seria seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'O homem deu nome para todos os animais domésticos, para todos os pássaros dos céus, para todas as feras do campo. Mas, para o homem, não se achava uma auxiliadora que lhe fosse idônea.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Deus Yahweh fez cair um sono profundo sobre o homem, e ele adormeceu. Deus Yahweh pegou uma de suas costelas e fechou o lugar com carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Com a costela que Deus Yahweh havia tirado do homem, Ele fez a mulher e a levou a Adão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'E o homem disse: \"Esta agora é osso dos meus ossos, e carne da minha carne. Ela será chamada \'mulher\', porque do homem foi tirada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Por isso, deixará o homem seu pai e sua mãe, e se unirá à sua mulher, e eles serão uma só carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Os dois estavam nus, o homem e sua mulher, mas não se envergonhavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Ora, a serpente era mais astuta que qualquer outro animal que Yahweh Deus criou. E ela perguntou à mulher: \"Deus realmente disse: \'Vós não devereis comer de nenhuma árvore do jardim?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'A mulher disse para a serpente: \"Podemos comer do fruto das árvores do jardim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'mas não podemos comer o fruto da árvore que está no meio do jardim; pois Deus disse: \'Não deveis comer dele, não deveis tocar nele, ou morrereis\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'A serpente disse para a mulher: \"Certamente, não morrereis,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'porque Deus sabe que, no dia em que dele comerdes, vossos olhos se abrirão, e sereis como Deus, conhecendo o bem e o mal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Quando a mulher viu que aquela árvore era boa para comer, agradável aos olhos e desejável para dar conhecimento, pegou o fruto, comeu-o, deu ao seu marido e ele comeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Os olhos dos dois se abriram e eles perceberam que estavam nus; costuraram folhas de figueira e fizeram vestimentas para si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Eles ouviram a voz de Yahweh Deus, que estava caminhando pelo jardim no frescor do dia. Então, o homem e sua mulher se esconderam da presença de Yahweh Deus entre as árvores do jardim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Yahweh Deus chamou o homem e lhe disse: \"Onde tu estás?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'E o homem disse: \"Ouvi a Tua voz no jardim e fiquei com medo, porque eu estava nu; então, me escondi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Deus disse: \"Quem te disse que estavas nu? Comeste da árvore que Eu disse que não deverias comer?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'O homem respondeu: \"A mulher que Tu me deste me deu do fruto da árvore e eu comi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Yahweh Deus disse para a mulher: \"Que fizeste?\". A mulher respondeu: \"A serpente me enganou e eu comi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Yahweh Deus disse à serpente: \"Porque fizeste isso, tu serás maldita entre todos os animais domésticos e todos os animais selvagens. Rastejarás sobre teu ventre e comerás poeira pelo resto da tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Porei inimizade entre ti e a mulher e entre teu descendente e o descendente dela. Ele ferirá tua cabeça e tu ferirás seu calcanhar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'E à mulher disse: \"Multiplicarei grandemente tua dor ao dar à luz; é na dor que tu irás ter filhos. Teu desejo será para teu marido, mas ele governará sobre ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'E, ao homem, disse: \"Porque ouviste a voz da tua mulher e comeste do fruto da árvore que te ordenei, dizendo: \'Não comerás dela\', a terra será amaldiçoada por tua causa, trabalharás duramente para poder comer dela, todos os dias de tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Ela produzirá espinhos e ervas daninhas e tu comerás das plantas do campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Do suor da tua face, comerás o pão, até retornares à terra de onde tu foste tirado. Porque tu és pó e ao pó retornarás\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'O homem chamou a sua mulher de Eva, porque ela era a mãe de todos os seres vivos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Yahweh Deus fez vestimentas de peles para Adão e sua esposa e os vestiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Yahweh Deus disse: \"Agora o homem se tornou como um de nós, conhecendo o bem e o mal. Não permitirei que ele tome da árvore da vida e dela coma e viva para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Por isso, Yahweh Deus o lançou fora do jardim do Éden, para cultivar a terra da qual foi tirado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Então, Deus expulsou o homem, pôs os querubins a leste do jardim do Éden e uma espada flamejante que se revolvia por todos os lados, a fim de proteger o caminho da árvore da vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Adão teve relações com Eva, sua mulher. Ela concebeu e deu à luz Caim. Ela disse: \"Eu tive um filho homem com ajuda de Deus Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Então, ela deu à luz seu irmão Abel. Abel tornou-se um pastor de ovelhas, mas Caim lavrava a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Passado algum tempo, Caim trouxe alguns frutos da terra e os ofereceu a Deus Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'E Abel trouxe as primícias e gorduras do seu rebanho. Yahweh Se agradou de Abel e de sua oferta,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'mas Ele não se agradou de Caim e da sua oferta. Assim, Caim ficou muito furioso e com o semblante caído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Yahweh disse para Caim: \"Por que tu estás furioso e por que teu semblante está caído?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Se tu procederes como é correto, não serás aceito? Porém, se tu não procederes como é correto, o pecado espreita à porta e deseja te controlar, mas precisas dominá-lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Caim falou para Abel, seu irmão: \"Vamos ao campo\". Enquanto eles estavam no campo, Caim levantou-se contra Abel, seu irmão, e o matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Então, Yahweh disse para Caim: \"Onde está Abel, teu irmão?\". Ele disse: \"Eu não sei. Sou eu o guardador do meu irmão?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Yahweh disse: \"O que fizeste? Do solo, a voz do sangue do teu irmão está clamando a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Agora és maldito pelo solo que escancarou a sua boca para receber o sangue do teu irmão que está em tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Quando tu trabalhares, o solo não vai produzir. Serás um fugitivo e errante pela terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Caim disse a Yahweh: \"Minha punição é maior do que eu posso suportar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'De fato, hoje Tu me expulsas deste solo e eu ficarei afastado da Tua presença. Eu serei um fugitivo e errante pela terra; e quem comigo encontrar, poderá matar-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'E disse-lhe Yahweh: \"Qualquer que matar Caim será vingado sete vezes\". Então, Yahweh colocou um sinal sobre Caim, para que não fosse morto por quem o encontrasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Retirou-se Caim da presença de Yahweh e viveu na terra de Node, a leste do Éden.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Caim conheceu sua mulher, que concebeu e deu à luz Enoque. Caim edificou uma cidade e pôs o nome de seu filho Enoque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'De Enoque, nasceu Irade. Irade gerou Meujael. Meujael gerou Metusael. Metusael gerou Lameque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lameque tomou para si duas esposas: o nome de uma era Ada e o nome da outra era Zila.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Ada deu à luz Jabal. Ele foi o pai daqueles que habitam em tendas e possuem gado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Seu irmão chamava-se Jubal. Ele foi o pai daqueles que tocam harpa e flauta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Zila também teve um filho, Tubal-Caim, fabricante de ferramentas de bronze e ferro. A irmã de Tubal-Caim era Naamá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Lameque disse para suas esposas: \"Ada e Zila, escutai a minha voz, mulheres de Lameque; ouvi as minhas palavras, pois eu matei um homem por ferir-me, um jovem rapaz por pisar-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Se Caim é vingado sete vezes, Lameque será vingado setenta e sete vezes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Tornou Adão a ter relações com sua mulher e ela gerou outro filho, a quem pôs o nome de Sete; e ela disse: \"Deus me deu outro filho no lugar de Abel, pois Caim o matou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'De Sete, também nasceu um filho e ele lhe deu o nome de Enos. Foi nesse tempo em que as pessoas começaram a invocar o nome de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Este é o registro dos descendentes de Adão. No dia em que Deus criou o homem, Ele os fez à Sua própria semelhança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Ele criou o homem e a mulher, abençoou-os e os chamou de humanos quando foram criados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Adão viveu cento e trinta anos, gerou um filho à sua semelhança, conforme a sua imagem e o chamou de Sete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Depois que Adão teve Sete, viveu oitocentos anos e gerou filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Adão viveu novecentos e trinta anos; e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Sete viveu cento e cinco anos e gerou Enos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Depois que teve Enos, Sete viveu oitocentos e sete anos e gerou filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Sete viveu novecentos e doze anos; e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enos viveu noventa anos e gerou Quenã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Depois que teve Quenã, Enos viveu oitocentos e quinze anos e gerou filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Enos viveu novecentos e cinco anos; e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Quenã viveu Setenta anos e gerou Maalalel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Depois que teve Maalalel, Quenã viveu oitocentos e quarenta anos e gerou filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Quenã viveu novecentos e dez anos; e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Maalalel viveu sessenta e cinco anos e gerou Jarede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Depois que teve Jarede, Maalalel viveu oitocentos e trinta anos e gerou filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Maalalel viveu oitocentos e noventa e cinco anos; e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Jarede viveu cento e sessenta e dois anos e gerou Enoque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Depois que teve Enoque, Jarede viveu oitocentos anos e gerou filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Jarede viveu novecentos e sessenta e dois anos; e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Enoque viveu sessenta e cinco anos e gerou Matusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Enoque andou com Deus. Depois que teve Matusalém, Enoque viveu trezentos anos e gerou filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Enoque viveu trezentos e sessenta e cinco anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Andou Enoque com Deus e desapareceu da terra, porque Deus o tomou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Matusalém viveu cento e oitenta e sete anos e gerou Lameque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Depois que teve Lameque, Matusalém viveu setecentos e oitenta e dois anos e gerou filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Matusalém viveu novecentos e sessenta e nove anos; e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lameque viveu cento e oitenta e dois anos e gerou um filho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'a quem chamou Noé, dizendo: \"Este nos consolará de nossas obras e do penoso trabalho de nossas mãos, causado pela terra que Yahweh amaldiçoou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Lameque viveu quinhentos e noventa e cinco anos depois que gerou Noé e gerou filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Lameque viveu setecentos e setenta e sete anos; e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Noé viveu quinhentos anos e gerou Sem, Cam e Jafé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'E aconteceu que, quando os homens começaram a se multiplicar sobre a terra e nasceram suas filhas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'os filhos de Deus viram que as filhas dos homens eram atraentes e tomaram para si como esposas todas que lhes agradaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'E Yahweh disse: \"Meu espírito não permanecerá para sempre no homem, pois é carne, e os seus dias serão cento e vinte anos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Gigantes estavam na terra, naqueles dias e também depois. Isso aconteceu porque os filhos de Deus casaram com as filhas dos homens, e eles tiveram filhos com elas, os quais foram homens valentes, homens de renome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Yahweh viu que grande maldade havia nos homens sobre a terra e que toda inclinação dos pensamentos de seus corações era continuamente má.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'E Yahweh Se lamentou por ter feito o homem na terra e isso entristeceu Seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Então, Yahweh disse: \"Eu vou extinguir da face da terra o homem que criei; tanto a humanidade, quanto os animais maiores, as coisas rastejantes e as aves dos céus, pois lamento de tê-los criado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Mas Noé encontrou favor aos olhos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Estes são os eventos concernentes a Noé. Ele era um homem justo, íntegro entre as pessoas da sua época e andava com Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Noé se tornou pai de três filhos: Sem, Cam e Jafé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'A terra estava corrompida perante Deus e estava cheia de violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Deus viu a terra e ela estava corrompida, toda a carne havia corrompido o seu caminho sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Deus disse a Noé: \"Eu vejo que é tempo de pôr um fim em toda a carne, pois a terra está cheia da violência dos homens. De fato, vou destruí-los juntamente com a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Faze para ti mesmo uma arca de madeira de cipreste. Faze compartimentos na arca e reveste-a com piche por dentro e por fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Esta é a forma com que irás fazer: o comprimento da arca será de trezentos côvados, a sua largura de cinquenta côvados e sua altura de trinta côvados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Farás um teto para a arca e finalizarás com um côvado do topo da lateral. Porás uma porta na lateral da arca. Farás pavimentos: um embaixo, um segundo e um terceiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Ouve: Eu trarei um dilúvio sobre a terra, para destruir toda carne que tem fôlego de vida debaixo do céu. Tudo o que está na terra morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mas eu firmarei uma aliança contigo. Tu irás para dentro da arca, teus filhos, tua esposa e as esposas de teus filhos contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'De toda criatura viva, de toda carne, tu deves trazer para dentro da arca dois de cada espécie, macho e fêmea, para mantê-los vivos contigo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'das aves conforme suas espécies, dos animais maiores conforme suas espécies, de cada coisa rastejante do chão conforme suas espécies, dois de cada tipo virão a ti, para mantê-los vivos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Armazena todo tipo de comida, pois servirá de sustento para ti e para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Então, Noé fez dessa forma. De acordo com tudo o que Deus mandou, ele fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Yahweh disse a Noé: \"Vai para a arca, tu e toda a tua família, porque Eu vi que és justo diante de Mim nesta geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'De cada animal puro, trarás contigo sete machos e sete fêmeas; e, dos animais que não são puros, um casal, o macho e sua fêmea.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Também, das aves do céu, trarás sete machos e sete fêmeas, para preservar a sua espécie sobre toda a face da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Porque, em sete dias, farei chover sobre toda a terra quarenta dias e quarenta noites. Destruirei da superfície da terra todas as coisas vivas que criei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Noé fez tudo o que Yahweh havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noé tinha seiscentos anos quando o dilúvio veio sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Noé entrou na arca com seus filhos e sua mulher e as mulheres de seus filhos, por causa das águas do dilúvio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Os animais puros e os impuros, as aves, e tudo que rasteja sobre a terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'de dois em dois, macho e fêmea, foram a Noé e entraram na arca, como Deus havia ordenado a Noé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Sucedeu que, depois de sete dias, as águas inundaram a superfície da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Quando Noé tinha seiscentos anos, aos dezessete dias do segundo mês, romperam-se todas as fontes do grande abismo, e as comportas do céu se abriram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'A chuva começou a cair e encheu a terra por quarenta dias e quarenta noites.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Nesse mesmo dia, entrou na arca Noé e seus filhos Sem, Cam e Jafé, a esposa de Noé e as três mulheres de seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'E, com eles, todo animal selvagem, segundo a sua espécie, todo animal de criação, segundo a sua espécie, todo animal que rasteja sobre a terra, toda ave, conforme a sua espécie, toda criatura que tem asa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Dois de cada carne que tem o sopro de vida vieram para Noé e entraram na arca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Os animais que entraram eram macho e fêmea; e entraram como Deus havia ordenado. Então, Yahweh fechou a porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'E veio o dilúvio sobre a terra, por quarenta dias, e as águas aumentaram e levantaram a arca da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'As águas cobriram completamente a terra, e a arca flutuou sobre a superfície das águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'As águas se avolumaram mais e mais sobre a terra e cobriram completamente até as montanhas mais altas que havia debaixo do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'As águas sobressaíram quinze côvados acima do topo das montanhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Todos os seres vivos que se moviam sobre a terra morreram: os pássaros, os animais domésticos, os animais selvagens, tudo que rasteja sobre a terra, e toda a humanidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Todos os seres cujas narinas respiravam o sopro de vida e todos em terra seca morreram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Então, todos os seres vivos sobre a superfície da terra foram extintos, desde os humanos até os animais maiores, os rastejantes e os pássaros no céu. Todos eles foram extintos da terra. E restaram somente Noé e aqueles que com ele estavam dentro da arca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'As águas prevaleceram sobre a terra por cento e cinquenta dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Deus lembrou-se de Noé, de todos os animais selvagens e de todos os animais domésticos que estavam com ele na arca. Deus fez soprar um vento sobre a terra, e as águas começaram a recuar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'As fontes do abismo e as comportas do céu fecharam-se, e parou de chover.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'As águas recuavam continuamente sobre a terra. Depois de cento e cinquenta dias, as águas tinham diminuído consideravelmente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'A arca parou no sétimo mês, no décimo sétimo dia, sobre as montanhas de Ararate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'As águas continuaram a recuar até o décimo mês. No primeiro dia do décimo mês, os picos das montanhas apareceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Sucedeu que, ao final de quarenta dias, Noé abriu a janela da arca que ele havia feito');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'e soltou o corvo, que ia e voltava, até que as águas se secaram sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Então, ele enviou uma pomba para ver se as águas haviam recuado sobre a face da terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'mas a pomba não encontrou lugar onde pousar. Então, ela retornou para Noé na arca, porque as águas ainda cobriam toda a terra. Ele estendeu sua mão, segurou-a e a trouxe para dentro da arca com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Ele esperou outros sete dias e novamente soltou a pomba para fora da arca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'A pomba retornou para ele ao entardecer, e eis que ela trazia no bico uma folha de oliveira recém colhida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Assim, Noé soube que as águas tinham diminuído sobre a terra. Ele esperou ainda outros sete dias e soltou a pomba novamente. Ela não retornou mais para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Sucedeu que, no primeiro dia do primeiro mês do ano seiscentos e um, as águas secaram sobre a terra. Noé removeu a cobertura da arca, olhou para fora e eis que a face da terra estava seca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'No segundo mês, no vigésimo sétimo dia, a terra estava seca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Deus disse a Noé:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '\"Sai da arca, tu e tua mulher, teus filhos e as mulheres de teus filhos contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Faz sair toda criatura viva de toda carne, tanto aves como animais de criação e todo animal rastejante que se arrasta sobre a terra, para que eles possam se reproduzir, frutificar e multiplicar sobre a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Então, Noé saiu com seus filhos, sua mulher e as mulheres de seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Todas as criaturas vivas: as aves, os animais de criação, os animais selvagens e todo animal rastejante, conforme as suas famílias, deixaram a arca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Noé construiu um altar para Yahweh. Ele tomou alguns dos animais limpos e alguns passáros limpos e ofereceu holocaustos sobre o altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Yahweh sentiu o aroma suave e disse em Seu coração: \"Eu não tornarei a amaldiçoar a terra por causa do homem, apesar das intenções do seu coração serem más desde a infância, e nem tornarei a destruir todo vivente, como Eu acabo de fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Enquanto a terra permanecer, semeadura e colheita, frio e calor, verão e inverno, dia e noite não cessarão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'E Deus abençoou Noé e seus filhos e lhes disse: \"Frutificai, multiplicai-vos e enchei a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'O pavor e o medo de vós estarão sobre todo animal vivente da terra, sobre toda ave do céu, sobre tudo o que rasteja pelo chão e sobre todos os peixes do mar. Todos foram entregues a vossa mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Tudo quanto se move e vive vos servirá de alimento. Assim como vos dei os vegetais, agora vos dou todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Contudo, não comereis carne com a vida nela, ou seja, com o sangue dentro dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Certamente, Eu requererei o vosso sangue, o sangue da vossa vida; Eu o requererei de cada animal. Também da mão de cada homem que assassinou seu irmão, Eu requererei pela vida do homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Qualquer que derramar sangue de um homem terá seu sangue derramado pelo homem, porque Deus fez o homem à Sua imagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Quanto a vós, sede fecundos e multiplicai-vos; povoai a terra e multiplicai-vos nela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Então, Deus falou com Noé e seus filhos, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '\"Eis que Eu estabelecerei a Minha aliança convosco, com a vossa descendência depois de vós');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'e com cada ser vivente que estiver convosco: tanto as aves, os animais de criação e os animais selvagens que saíram da arca, como todo ser vivente da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Estabelecerei Minha aliança convosco, que nunca mais será destruída toda carne por águas de dilúvio. Nunca mais haverá dilúvio para destruir a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Deus disse: \"Este é o sinal da Minha aliança que faço entre Mim e vós e todos os seres viventes que estão convosco, para as futuras gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Eu coloquei o Meu arco nas nuvens e este será o sinal da aliança entre Mim e a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'E acontecerá que, quando Eu trouxer nuvens sobre a terra e nelas aparecer o arco,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'recordarei da Minha aliança firmada entre Mim e vós e todos os seres viventes de toda carne. E não haverá mais as águas de dilúvio para destruir toda carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'O arco estará nas nuvens e Eu o verei e Me lembrarei da aliança entre Deus e todos os seres viventes de toda carne que há sobre a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Depois, Deus disse a Noé: \"Este é o símbolo da aliança que Eu estabeleci, entre Eu e todas as criaturas na terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Os filhos de Noé que saíram da arca eram Sem, Cam e Jafé. Cam era o pai de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'São eles os três filhos de Noé e deles toda a terra foi povoada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Nóe começou a cultivar a terra e plantou uma vinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Bebeu vinho e se embriagou. Ele ficou nu em sua tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Cam, o pai de Canaã, viu a nudez de seu pai e saiu para contar aos seus dois irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Então, Sem e Jafé pegaram uma capa e colocaram-na sobre os próprios ombros e, andando de costas, cobriram a nudez de seu pai. Seus rostos estavam voltados para trás, para que não vissem a nudez de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Quando Noé despertou de sua embriaguez, soube o que seu filho mais novo havia feito a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Então, disse: \"Maldito seja Canaã. Ele será servo dos servos de seus irmãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'E também disse: \"Que Yahweh, o Deus de Sem, seja bendito, e Canaã seja seu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Que Deus engrandeça Jafé e habite ele nas tendas de Sem. E que Canaã seja seu servo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Depois do dilúvio, Noé viveu trezentos e cinquenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Todos os dias de Noé foram novecentos e cinquenta anos, depois ele morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Estas são as gerações dos filhos de Noé: Sem, Cam e Jafé; seus filhos nasceram depois do dilúvio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Os filhos de Jafé foram: Gomer, Magogue, Madai, Javã, Tubal, Meseque e Tiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Os filhos de Gomer foram: Asquenaz, Rifate e Togarma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Os filhos de Javã foram: Elisá, Társis, Quitim e Dodanim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Os descendentes de Javã repartiram entre si as terras do litoral, e, então, ocuparam-nas segundo a sua própria língua, de acordo com as suas famílias e nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Os filhos de Cam foram: Cuxe, Mizraim, Pute e Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Os filhos de Cuxe foram: Seba, Havilá, Sabtá, Raamá e Sabtecá. Os filhos de Raamã foram: Sabá e Dedã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Cuxe gerou a Ninrode, o qual foi o primeiro a ser poderoso na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Ele foi um poderoso caçador diante de Yahweh. Por isso que é dito: \"Como Ninrode, um poderoso caçador diante de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'As principais cidades do seu reino foram Babel, Ereque, Acade e Calné, na terra de Sinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Daquela terra, ele partiu para a Assíria e edificou Nínive, Reobote-Ir, Calá');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'e Resém entre Nínive e Calá. Essa era uma grande cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Mizraim gerou a Ludim, a Anamim, a Leabim, a Naftuim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'a Patrusim, a Casluim (de onde saíram os filisteus) e a Caftorim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Canaã gerou Sidom, seu primogênito, e Hete,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'também gerou o jebuseu, o amorreu, o girgaseu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'o heveu, o arqueu, o sineu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'o arvadeu, o zemareu e o hamateu. Depois, as famílias dos cananeus se espalharam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'O território dos cananeus era de Sidom, em direção a Gerar, até Gaza; indo em direção a Sodoma, Gomorra, Admã e Zeboim, até Lasa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Esses foram os descendentes de Cam com suas famílias, suas línguas, e em suas terras e suas nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Sem, antepassado de todos os filhos de Héber e irmão mais velho de Jafé, também gerou filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Os filhos de Sem foram: Elão, Assur, Arfaxade, Lude e Arã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Os filhos de Arã foram: Uz, Hul, Geter e Más.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arfaxade gerou a Selá; e Selá gerou Éber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Éber gerou dois filhos. O nome do primeiro foi Pelegue, porque nesses dias a terra foi dividida. O nome de seu irmão foi Joctã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Joctã gerou Almodá, Selefe, Hazarmavé, Jerá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadorão, Uzal, Dicla,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obal, Abimael, Sabá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ofir, Havilá e Jobabe. Todos esses foram os filhos de Joctã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'O território deles ia desde Messa até Sefar, incluindo montanhas ao Leste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Esses foram os descendentes de Sem, segundo as suas famílias e suas línguas, em suas terras, e suas nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Essas são as famílias dos descendentes de Noé, segundo as suas genealogias, com suas nações. A partir dessas famílias, foram formaradas as nações e se dispersaram sobre toda a terra, depois do dilúvio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'O mundo tinha uma só língua e uma só maneira de falar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Partindo eles do oriente, acharam uma planície na terra de Sinar e se estabeleceram ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'E disseram uns aos outros: \"Vinde, façamos tijolos e queimemo-los completamente\". Eles usaram tijolos em vez de pedras, e o piche como argamassa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'E disseram: \"Vinde, construamos uma cidade para nós, uma torre cujo topo alcance o céu, e façamos para nós um nome, a fim de que não nos espalhemos sobre a superfície da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'E desceu Yahweh para ver a cidade e a torre que os filhos dos homens edificaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Yahweh disse: \"Eis que todos são um só povo e falam uma só língua. Isso é o que começaram a fazer; agora não haverá restrição alguma para tudo o que intentarem fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Vinde, desçamos e confundamos ali a sua língua, para que não entendam uns aos outros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'E Yahweh os espalhou dali sobre toda a superfície da terra; e pararam de edificar a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Por isso, foi chamada Babel, porque foi ali que Yahweh confundiu a língua de toda a terra e os espalhou sobre toda a face da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Estas são as gerações de Sem. Ele tinha cem anos de idade, quando gerou Arfaxade, dois anos depois do dilúvio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Sem viveu quinhentos anos depois que gerou Arfaxade; também gerou outros filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arfaxade tinha trinta e cinco anos, quando gerou Selá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Depois que gerou Selá, Arfaxade viveu quatrocentos e três anos; também gerou outros filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Selá tinha trinta anos quando gerou Éber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Selá viveu quatrocentos e três anos depois que gerou Éber; também gerou outros filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Éber tinha trinta e quatro anos quando gerou Pelegue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Éber viveu quatrocentos e trinta anos depois que gerou Pelegue; também gerou outros filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Pelegue tinha trinta anos, quando gerou Reú.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Pelegue viveu duzentos e nove anos depois que gerou Reú; também gerou outros filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Reú tinha trinta e dois anos quando gerou Serugue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Reú viveu duzentos e sete anos depois que gerou Serugue; também gerou outros filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Serugue tinha trinta anos quando gerou Naor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Serugue viveu duzentos anos depois que gerou Naor; também gerou outros filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Naor tinha vinte e nove anos quando gerou Terá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Naor viveu cento e dezenove anos depois que gerou Terá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Terá tinha setenta anos quando gerou Abrão, Naor e Harã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Estes são os descendentes de Terá. Terá gerou Abrão, Naor e Harã; e Harã gerou Ló.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Harã morreu na presença do seu pai Terá, na terra de seu nascimento, em Ur dos caldeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Abrão e Naor tomaram mulheres para si. O nome da mulher de Abrão era Sarai e o nome da mulher de Naor era Milca; esta era filha de Harã, que foi pai de Milca e de Iscá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Sarai era estéril: não tinha filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Terá tomou seu filho Abrão e Ló, filho de seu filho, e a Sarai, sua nora, mulher de seu filho Abrão. E juntos deixaram Ur dos caldeus para ir à terra de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Foram até Harã e se estabeleceram ali. Terá viveu duzentos e cinco anos e depois morreu em Harã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Então, Yahweh disse a Abrão: \"Sai da tua terra, e do meio dos teus parentes, e da casa de teu pai, para a terra que Eu te mostrarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'E farei de ti uma grande nação, te abençoarei, farei teu nome grande e tu serás uma bênção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Eu abençoarei os que te abençoarem e amaldiçoarei os que te amaldiçoarem. Através de ti, todas as famílias da terra serão abençoadas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'E foi Abrão como Yahweh havia lhe dito que fizesse, e Ló foi com ele. Abrão tinha setenta e cinco anos quando partiu de Harã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Levou consigo Sarai, sua mulher, e Ló, filho de seu irmão, e toda sua riqueza e as pessoas que havia adquirido em Harã. Eles saíram para a terra de Canaã e lá chegaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Abrão atravessou a terra até Siquém para o carvalho de Moré. Naquele tempo, os cananeus habitavam na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Yahweh apareceu para Abrão e disse: \"Eu darei esta terra para os teus descendentes\". Então, Abrão edificou um altar para Yahweh, Aquele que lhe havia aparecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'De lá, ele mudou-se para a montanha ao leste de Betel, onde armou sua tenda; estando Betel ao oeste e Ai, ao leste. Lá ele edificou um altar para Yahweh e invocou pelo Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Então, Abrão partiu dali em direção ao Neguebe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'E houve fome na terra. Então, Abrão desceu até o Egito para ali ficar, pois a fome era severa na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'E aconteceu que, quando ele estava se aproximando do Egito, disse para Sarai, sua mulher: \"Vê, eu sei que tu és mulher formosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Quando os egípcios te virem, dirão: \'Esta é a mulher dele\'; irão matar-me e te manterão viva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Dize, pois, que és minha irmã e assim estarei bem, graças a ti, e minha vida será poupada por tua causa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Aconteceu que, quando Abrão entrou no Egito, os egípcios viram que Sarai era mulher muito formosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Os oficiais do Faraó a viram, elogiaram-na diante do Faraó e a mulher foi levada para a casa do Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Ele tratou bem a Abrão por causa dela e lhes deu ovelhas, bois, jumentos, servos e servas, jumentas e camelos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Então, Yahweh afligiu a Faraó e a sua casa com grandes pragas, por causa de Sarai, mulher de Abrão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Faraó chamou Abrão e disse: \"O que é isto que fizeste? Por que não me relataste que ela é tua mulher?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Por que me disseste que ela é tua irmã, de modo que a tomei para ser minha mulher? Agora, pois, aqui está a tua mulher, toma-a e segue teu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Então, Faraó deu ordens a seus homens a respeito dele, e levaram-no embora, junto com sua esposa e com tudo o que possuía\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Então, Abrão subiu do Egito para o Neguebe. Ele, sua mulher e tudo o que tinha. Ló também foi com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abrão era muito rico: possuía gado, prata e ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Ele continuou sua jornada de Neguebe para Betel, até o lugar onde sua tenda já esteve antes, entre Betel e Ai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Esse é o lugar onde estava o altar que ele havia construído anteriormente, e ali Abrão invocou o nome de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Nessa época, Ló, que acompanhava Abrão, também possuía rebanhos e tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'A terra não era suficiente para sustentá-los, pois os seus bens eram muitos, de modo que não podiam viver juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Houve contenda entre os pastores dos rebanhos de Abrão e os pastores dos rebanhos de Ló. Nesse tempo, os cananeus e os ferezeus habitavam essa terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Disse Abrão a Ló: \"Que não haja contenda entre mim e ti, nem entre os meus pastores e os teus pastores, pois somos irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Não está diante de ti toda a terra? Peço-te que te apartes de mim. Se fores para a esquerda, então, irei para a direita. Ou se fores para a direita, irei para a esquerda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Então, Ló olhou ao redor e viu que todo o vale do Jordão era bem irrigado por todo o caminho até Zoar; era como o jardim de Yahweh, como a terra do Egito. Isso foi antes de Yahweh destruir Sodoma e Gomorra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Assim, Ló escolheu para si todo o vale do Jordão e partiu para o Oriente, e se separaram um do outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abrão habitou na terra de Canaã, e Ló, nas cidades do vale, armando suas tendas até Sodoma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Ora, os homens de Sodoma eram extremamente maus e grandes pecadores contra Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Yahweh disse a Abrão, após Ló ter se separado dele: \"Ergue os teus olhos e olha desde o lugar onde estás para o norte, para o sul, para o oriente e para o ocidente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Toda esta terra que vês, Eu darei a ti e aos teus descendentes para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'E farei tua descendência tão numerosa quanto o pó da terra, de modo que, se alguém pudesse contar o pó da terra, então, tua descendência também poderia ser contada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Levanta-te, percorre esta terra no seu comprimento e largura, pois para ti a darei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Então, Abrão desarmou suas tendas e habitou perto dos carvalhos de Manre, situados no Hebrom, onde edificou um altar a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Nos dias de Anrafel, rei de Sinar, de Arioque, rei de Elasar, de Quedorlaomer, rei de Elão e de Tidal, rei de Goim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'estes fizeram uma guerra contra Bera, rei de Sodoma, Birsa, rei de Gomorra, Sinabe, rei de Admá, Semeber, rei de Zeboim e o rei de Belá (também chamada de Zoar).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Esses últimos cinco reis ajuntaram-se no vale de Sidim (também chamado de Mar Salgado).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Durante doze anos, haviam servido Quedorlaomer, mas, no décimo terceiro ano, rebelaram-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Depois do décimo quarto ano, Quedorlaomer e os reis que estavam com ele foram e atacaram os refains em Asterote-Carnaim, os zuzins em Hão, os emins em Savé-Quiriataim');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'e os horeus de seu monte Seir até El-Parã, próximo ao deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Depois eles retornaram e foram para En-Mispate (também chamado de Cades), e conquistaram a terra dos amalequitas e também dos amorreus, que viviam em Hazazom-Tamar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Em seguida, o rei de Sodoma, o rei de Gomorra, o rei de Admá, o rei de Zeboim e o rei de Belá (também chamado de Zoar) deslocaram-se e prepararam-se para a batalha no vale de Sidim');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'contra Quedorlaomer, rei de Elão, Tidal, rei de Goim, Anrafel, rei de Sinar, Arioque, rei de Elasar: quatro reis contra cinco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'O vale de Sidim estava cheio de poços de piche, e os reis de Sodoma e Gomorra fugiram e caíram lá. Aqueles que estavam à esquerda fugiram para as montanhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Então, os inimigos tomaram todos os bens e provisões de Sodoma e Gomorra e se foram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Eles tomaram também Ló, juntamente com suas posses. Ló era filho do irmão de Abrão e vivia em Sodoma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Um que havia escapado foi e contou a Abrão, o hebreu; este estava habitando junto aos carvalhos que pertenciam a Manre, o amorreu, irmão de Escol e de Aner, os quais eram todos aliados de Abrão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Quando Abrão ouviu que seus inimigos haviam capturado seu parente, liderou seus trezentos e dezoito homens treinados, nascidos em sua casa, e os perseguiu até Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Ele dividiu seus homens e atacou os inimigos à noite, perseguindo-os até Hobá, ao norte de Damasco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Assim, ele trouxe de volta todas as suas posses e também trouxe de volta seu parente Ló e seus bens, assim como as mulheres e as outras pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Depois que Abrão retornou do ataque a Quedorlaomer e aos reis que estavam com ele, o rei de Sodoma saiu para encontrá-lo no vale de Savé (também chamado de Vale do Rei).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Melquisedeque, rei de Salém, trouxe pão e vinho. Ele era sacerdote do Deus Altíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Ele abençoou Abrão, dizendo: \"Bendito seja Abrão pelo Deus Altíssimo, Criador dos céus e da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Bendito seja o Deus Altíssimo, que entregou os teus inimigos em tuas mãos\". Então, Abrão deu-lhe um décimo de tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'O rei de Sodoma disse a Abrão: \"Dá-me o povo e toma os bens para ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Abrão disse ao rei de Sodoma: \"Eu levanto minhas mãos a Yahweh, Deus Altíssimo, Criador dos céus e da terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'que eu não tomarei nem uma linha, uma correia de sandália ou qualquer coisa que te pertença, para que nunca possas dizer: \'Eu enriqueci a Abrão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Eu não levarei nada, exceto o que esses jovens já comeram. E, quanto à parte dos homens que vieram comigo, Aner, Escol e Manre, que eles peguem as suas porções\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Depois disso, falou Yahweh a Abrão, numa visão, dizendo: \"Não temas, Abrão! Eu Sou teu escudo e tua recompensa será grande\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Abrão respondeu: \"Senhor Yahweh, o que me darás, pois continuo sem filho, e o meu herdeiro será Eliézer de Damasco?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'E acrescentou Abrão: \"Tu não me deste descendente e o mordomo da minha casa será o meu herdeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Então, veio a ele a palavra de Yahweh, dizendo: \"Esse não será o teu herdeiro, mas aquele que será gerado por ti será o teu herdeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'E o Senhor o conduziu para fora e disse: \"Olha para o céu e conta as estrelas, se puderes\". E lhe disse: \"Assim será a tua descendência\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Abrão creu em Yahweh e isso lhe foi atribuído como justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'E disse Yahweh: \"Eu Sou Yahweh, que te fez sair de Ur dos caldeus, para te dar esta terra por herança\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Perguntou-lhe Abrão: \"Senhor Yahweh, como vou saber que a herdarei?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Respondeu-lhe: \"Traz-Me uma novilha, uma cabra e um carneiro, cada um com três anos de idade, um pombo e uma rolinha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Ele trouxe os animais, cortou-os ao meio e colocou cada parte em frente à outra, porém não cortou as aves.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'As aves de rapina desciam sobre as carcaças e Abrão as afugentava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Quando o sol se pôs, caiu um sono profundo sobre Abrão, pavor e grande escuridão o cercaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Então, disse Yahweh a Abrão: \"Sabes, com certeza, que teus descendentes serão peregrinos em uma terra que não lhes pertence. Serão escravizados e oprimidos por quatrocentos anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mas Eu julgarei a nação à qual haverão de servir; depois sairão com abundantes riquezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Tu, porém, irás em paz aos teus pais e serás sepultado em boa velhice.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Na quarta geração, eles voltarão para cá, porque a iniquidade dos amorreus ainda não atingiu seu limite\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Depois que o sol se pôs e já estava escuro, uma fornalha fumegante e uma tocha de fogo passaram por entre as metades dos animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Naquele dia, Yahweh fez uma aliança com Abrão, dizendo: \"À tua descendência dei esta terra, desde o rio do Egito até ao grande rio Eufrates:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'o queneu, o quenezeu, o cadmoneu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'o heteu, o perizeu, os refains,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'o amorreu, o cananeu, o girgaseu e o jebuseu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'No entanto, Sarai, esposa de Abrão, não gerou nenhum filho para ele, mas ela tinha uma escrava egípcia, cujo nome era Agar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Então, disse Sarai a Abrão: \"Eis que Yahweh tem me impedido de ter filhos. Dorme com a minha escrava. Pode ser que eu tenha filhos através dela\". Abrão deu ouvidos à palavra de Sarai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Então, Sarai, a esposa de Abrão, deu a sua escrava egípcia, Agar, como mulher ao seu marido. Isso aconteceu dez anos depois de Abrão ter habitado na terra de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Ele teve relação sexual com Agar, e ela concebeu; e quando percebeu que estava grávida, olhou com desprezo sua senhora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Então, Sarai disse a Abrão: \"Essa injúria sobre mim é por tua causa. Eu dei minha escrava em tuas mãos e, quando se viu grávida, ela me tratou com desprezo. Deixa Yahweh julgar entre mim e ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Mas Abrão disse a Sarai: \"Eis que tua escrava está sob teu poder, faze a ela o que te parecer melhor\". Assim, Sarai a tratou com dureza e Agar fugiu de sua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'O Anjo de Yahweh a encontrou junto a uma fonte de águas no deserto, no caminho de Sur.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Ele disse: \"Agar, escrava de Sarai, de onde vens e para onde vais?\". E ela disse: \"Eu estou fugindo de minha senhora, Sarai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'O Anjo de Yahweh lhe disse: \"Retorna para a tua senhora e humilha-te à sua autoridade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Disse mais o Anjo de Yahweh: \"Eu multiplicarei grandemente a tua descendência, e será tão numerosa, que não poderão contá-la\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'O Anjo de Yahweh também lhe disse: Eis que estás grávida e darás à luz um filho, a quem chamarás de Ismael, pois Yahweh te ouviu na tua aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Ele será, entre os homens, como um jumento selvagem. Ele será hostil a todos, e todo homem lhe será hostil; e como oponente viverá diante dos seus irmãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Então, Agar chamou de Yahweh Aquele que falara com ela: \"Tu És o Deus que me vê\", pois ela disse: \"Teria eu realmente visto aqui Aquele que me vê?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Por isso, chamou o poço de Beer-Laai-Roi, que está entre Cades e Berede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Agar deu um filho a Abrão e Abrão chamou de Ismael ao filho que Agar lhe dera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Tinha Abrão oitenta e seis anos quando Agar deu à luz Ismael.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Quando Abrão tinha noventa e nove anos, Yahweh apareceu a Abrão e lhe falou: \"Eu sou O Deus Onipotente. Anda na Minha presença e sê perfeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Então, Eu confirmarei Minha aliança contigo e te multiplicarei grandemente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Abrão prostou-se com o rosto em terra e Deus falou-lhe, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '\"Quanto a Mim, esta é a Aliança que faço contigo: Tu serás pai de muitas nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Não mais te chamarás Abrão, mas teu nome será Abraão — porque te constituí para ser pai de uma multidão de nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Farei que sejas extraordinariamente fecundo, de ti farei nações e reis descenderão de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Estabelecerei Minha aliança entre Mim e ti e com a tua descendência, a qual perdurará através de todas as gerações como aliança eterna, para que Eu seja o teu Deus e O de toda a tua descendência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'A ti e a tua descendência darei a terra onde tu tens peregrinado, toda a terra de Canaã como uma posse eterna e Eu serei vosso Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Ainda disse Deus a Abraão: \"Quanto a ti, guarda Minha aliança, tu e a tua descendência por todas as gerações vindouras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Esta é a Minha aliança, a qual tens que manter entre Mim e ti e a tua descendência: Todo homem dentre vós deve ser circuncidado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Circuncidarás a carne do vosso prepúcio e este será o sinal da aliança entre Mim e vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Todo homem entre vós, da idade de oito dias, deve ser circuncidado, por todas as vossas gerações. Isso inclui todo aquele que é nascido em vossa casa, aquele que é comprado e qualquer estrangeiro que não for dos vossos descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Aquele que for nascido em vossa casa e que for comprado com vosso dinheiro deverá ser circuncidado. Assim, Minha aliança estará marcada em vossa carne como aliança eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Qualquer incircunciso que não for circuncidado na carne de seu prepúcio será eliminado de vosso povo, pois ele quebrou Minha aliança\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Deus disse a Abraão: \"Quanto a Sarai, tua mulher, não a chame mais de Sarai. Em vez disso, seu nome será Sara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Eu a abençoarei e te darei um filho por meio dela. Eu a abençoarei e ela se tornará a mãe de nações. Reis de povos virão por meio dela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Então, Abraão se prostrou com o rosto em terra, riu e disse em seu coração: \"Pode uma criança nascer de um homem de cem anos? Como pode Sara, que tem noventa anos gerar um filho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Abraão disse para Deus: \"Que Ismael viva diante de ti!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Disse Deus: \"Não, porém Sara, tua mulher, te dará um filho, e tu o chamarás Isaque. Estabelecerei Minha aliança com ele, como aliança perpétua e com a sua descendência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Quanto a Ismael, Eu tenho te escutado. Eis que Eu o abençoarei, farei ele fecundo e o multiplicarei abundantemente. Ele será pai de doze líderes de tribos, e Eu farei dele uma grande nação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Porém Minha aliança estabelecerei com Isaque, aquele o qual Sara dará a ti nesta mesma época do próximo ano\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Quando terminou de falar com ele, Deus retirou-se da presença de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Então, Abraão tomou seu filho Ismael e todos aqueles que nasceram em sua casa, todo homem entre os homens da casa de Abraão e os circuncidou na carne do prepúcio no mesmo dia, como Deus lhe havia dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abraão tinha noventa e nove anos, quando lhe foi circuncidada a carne do prepúcio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'E Ismael, seu filho, tinha treze anos quando lhe foi circuncidada a carne do prepúcio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'No mesmo dia, Abraão e seu filho Ismael foram circuncidados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Todos os homens da sua casa foram circuncidados com ele, incluindo aqueles que nasceram em sua casa e aqueles estrangeiros que foram comprados com dinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Yahweh apareceu a Abraão nos carvalhais de Manre, quando ele estava sentado à entrada da tenda, no maior calor do dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Eis que Abraão olhou para cima e viu três homens de pé, à sua frente. Quando os avistou, correu de onde estava para encontrá-los e prostou-se em terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Ele disse: \"Senhor, se encontrei favor aos Teus olhos, não passes de Teu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Mandarei trazer um pouco de água; lavai os pés e descansai debaixo da árvore.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Trarei um pouco de pão; refazei as vossas forças, porque chegaste até o vosso servo e depois seguireis adiante\". E responderam: \"Faz como disseste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Então, Abraão rapidamente entrou na tenda e falou com Sara: \"Apressa-te, pega três medidas de farinha fina, amassa-as e faz bolos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Então, Abraão correu ao seu rebanho, pegou um bezerro novo e bom e entregou-o a seu servo, que se apressou em prepará-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Pegou coalhada, leite e o bezerro que havia sido preparado, serviu-lhes e permaneceu em pé diante deles, enquanto comiam debaixo da árvore.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Eles perguntaram a Abraão: \"Onde está tua mulher, Sara?\" Ele respondeu: \"Está ali na tenda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'E disse: \"Certamente voltarei a ti em um ano, e tua mulher, Sara, terá um filho\". Sara estava escutando à entrada da tenda, atrás dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Abraão e Sara estavam velhos, com a idade bem avançada; além disso, Sara já havia passado da idade de gerar filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Então, Sara riu e falou para si mesma: \"Terei eu prazer depois de idosa, sendo meu senhor também já velho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Yahweh disse a Abraão: \"Por qual motivo Sara ri e diz: \'Poderei eu ter um filho, sendo idosa?\';');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Haveria alguma coisa difícil demais para Yahweh? Daqui a um ano, no tempo determinado, retornarei a ti e Sara terá um filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Então, Sara negou e disse: \"Eu não ri\", pois ela teve medo. Ele retrucou: \"Não! Tu riste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Então, os homens levantaram-se dali e olharam na direção de Sodoma. Abraão foi junto com eles para encaminhá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'E Yahweh disse: \"Eu Esconderei de Abraão o que estou prestes a fazer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'visto que ele será uma grande e poderosa nação, e todas as nações da terra serão abençoadas nele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Porque Eu o escolhi para que ordene seus filhos e sua descedência a permanecerem nos caminhos de Yahweh, para praticarem a justiça e o juízo, e para que Yahweh cumpra o que disse a Abraão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Então, Yahweh disse: \"O clamor de Sodoma e Gomorra tornou-se grande, e a transgressão deles se agravou muito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'descerei agora e verei se, de fato, tudo o que têm feito corresponde ao clamor que tem chegado a Mim. Caso contrário, saberei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Então, os homens viraram e foram em direção a Sodoma, mas Abraão permaneceu perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Abraão se aproximou e disse: \"Acaso destruirás o justo com o corrupto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Se houver cinquenta justos na cidade, destruirás e não pouparás o lugar por causa dos cinquenta justos que estão ali?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Longe de Ti fazer tal coisa, matar o justo com o corrupto, como se o justo fosse igual ao corrupto. Longe de Ti! Acaso o Juiz de toda terra não fará o que é justo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Yahweh disse: \"Se Eu encontrar em Sodoma cinquenta justos, pouparei a cidade toda por causa deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'E respondeu Abraão: \"Eis que me atrevo a falar ao Senhor, embora seja somente pó e cinza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'E, se de cinquenta justos faltarem cinco, destruirás a cidade inteira por causa dos cinco?\". E disse: \"Não destruirei, se ali encontrar quarenta e cinco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Abraão disse novamente: \"O que acontecerá se encontrares quarenta ali?\". Ele respondeu: \"Não o farei por causa dos quarenta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Ele disse: \"Por favor, não fiques bravo o Senhor por eu falar novamente. E se forem encontrados trinta, ali?\". Ele disse: \"Não o farei, se encontrar trinta ali\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'E disse: \"Não fiques bravo o Senhor, falarei ainda esta vez. E se forem encontrados vinte, ali?\". Ele respondeu: \"Não destruirei por causa dos vinte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'E disse: \"Por favor, não fiques bravo o Senhor, falarei ainda esta vez. E se forem encontrados dez ali?\". Ele respondeu: \"Não os destruirei por causa dos dez\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Yahweh continuou Seu caminho assim que terminou de falar com Abraão, e este retornou para sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Os dois anjos vieram para Sodoma à noite, enquanto Ló estava sentado no portão de Sodoma. Ló os viu, levantou-se, foi ao encontro deles e se prostrou com seu rosto voltado para o chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Ele disse: \"Por favor, meus senhores, eu insisto que entreis na casa do vosso servo, para passar a noite e lavar vossos pés. Então, podereis levantar cedo e seguir o vosso caminho\". Eles disseram: \"Não, nós passaremos a noite na praça da cidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Mas ele insistiu com eles fortemente, então, eles foram com ele e entraram em sua casa. Ele preparou a comida, assou pães sem fermento e eles comeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Mas, antes que eles se deitassem, todos os homens de Sodoma cercaram a casa, desde os jovens até os velhos, toda a população, até o último.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Eles chamaram Ló e lhe disseram: \"Onde estão os homens que vieram a ti esta noite? Trazei-os até nós para que possamos dormir com eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Então, Ló saiu e fechou a porta atrás de si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Ele disse: \"Eu imploro, meus irmãos, que não vos porteis de maneira tão perversa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Vede, eu tenho duas filhas que nunca dormiram com homem algum. Eu as trarei para fora e vós fareis com elas o que bem quiserdes. Mas a esses homens nada façais porque eles estão sob a sombra da minha casa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Eles disseram: \"Sai daí!\". Disseram também: \"Este veio para viver aqui como estrangeiro e agora se tornou nosso juiz! Agora nós iremos fazer mais mal a ti do que a eles!\". Eles pressionaram fortemente contra o homem, contra Ló, e se aproximaram para derrubar a porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Mas os visitantes estenderam as mãos, alcançaram Ló e o trouxeram para dentro da casa e fecharam a porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Quanto aos homens que estavam do lado de fora da casa, os hóspedes de Ló, os atacaram deixando-os cegos, do menor ao maior, de modo que eles ficaram exaustos de tanto procurar a entrada da casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Então, os dois homens disseram a Ló: \"Há mais alguém aqui? Genros, filhos, filhas e qualquer um que tu conheças aqui na cidade, tire-os daqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Porque vamos destruir este lugar, pois as acusações contra este lugar têm chegado como um grito diante de Yahweh e Ele nos enviou para destruí-lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Ló saiu e falou com os seus genros, os homens que tinham prometido casar com as suas filhas e lhes disse: \"Rápido, saí desse lugar pois Yahweh está prestes a destruir a cidade\". Mas, para os seus genros, ele parecia estar brincando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Ao amanhecer, os anjos apressaram Ló dizendo: \"Vai, toma a tua mulher e as tuas filhas que estão aqui para que não pereças no castigo da cidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Porém, como ele se demorava, os homens o pegaram pela mão, bem como sua mulher e suas filhas, porque Yahweh foi misericordioso para com ele. Eles os trouxeram para fora e os colocaram fora da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'E aconteceu que, enquanto eles os traziam para fora, um dos homens disse: \"Foge pela tua vida! Não olhes para trás, nem te detenhas em qualquer lugar na planície. Foge para as montanhas, para que não pereças\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Ló disse-lhe: \"Não, por favor, meus senhores!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Eis que teu servo tem achado graça aos vossos olhos e vós tendes me mostrado grande misericórdia ao salvar a minha vida, mas eu não posso escapar para as montanhas porque a destruição vai me alcançar e eu morrerei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Eis que a cidade ali é perto o suficiente e é pequena. Por favor, permite que eu fuja para lá, (ela não é pequena?) e minha vida estará a salvo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Ele lhe disse: \"Certo, eu estou concedendo esse pedido também, que eu não destruirei a cidade que tu mencionaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Apressa-te! Foge para lá, porque não posso fazer nada até que chegues lá\". Portanto, a cidade foi chamada Zoar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'O sol já havia nascido sobre a terra quando Ló alcançou Zoar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Então, Yahweh fez chover do céu enxofre e fogo sobre Sodoma e Gomorra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Yahweh destruiu aquelas cidades, toda a planície, todos os habitantes das cidades e as plantas que cresciam no solo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Mas a mulher de Ló, que estava atrás dele, olhou para trás e transformou-se em uma estátua de sal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Abraão levantou-se cedo pela manhã e foi ao lugar onde havia estado antes com Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Ele olhou para Sodoma e Gomorra e para toda a terra da planície. Olhou e contemplou e viu uma fumaça subindo da terra como uma fumaça de uma fornalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Então, quando Deus destruiu as cidades de toda a planície, lembrou-se de Abraão e tirou Ló do meio da destruição, quando destruiu as cidades em que Ló havia habitado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Mas Ló subiu de Zoar, para viver nas montanhas com suas filhas, porque estava com medo de viver em Zoar. Então, viveu em uma caverna, ele e as suas filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'A primogênita disse para a mais nova: \"Nosso pai está velho e não há nenhum homem por perto para dormir conosco de acordo como o costume de toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Vem, deixa-me fazer nosso pai beber vinho e assim teremos relações com ele para que possamos conservar a sua descendência\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Elas deram vinho para o pai naquela noite. Então, a primogênita foi e teve relações com o pai; ele não sabia quando ela havia deitado nem levantado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'No dia seguinte, a primogênita disse à irmã mais nova: \"Eis que, na noite passada, eu tive relações com o meu pai. Vamos lhe dar vinho esta noite também, e tu vai e tenha relações com ele, para que possamos conservar a sua descendência\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Então, elas deram vinho para o pai naquele noite e a filha mais nova foi e teve relações com ele. Ele não soube quando ela se deitou, nem quando se levantou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Então, as duas filhas de Ló ficaram grávidas do seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'A primogênita deu à luz um menino, a quem chamou Moabe. Ele se tornou o ancestral dos moabitas de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'A mais nova também deu à luz um menino, a quem chamou Ben-Ami. Ele se tornou o ancestral dos amonitas de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Abraão partiu dali para a terra do Neguebe e viveu entre Cades e Sur. Ele era um estrangeiro vivendo em Gerar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Abraão disse a respeito de sua mulher Sara: \"Ela é minha irmã\". Então, Abimeleque, o rei de Gerar mandou seus homens buscar Sara e a tomou para si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Mas Deus veio a Abimeleque num sonho, à noite, e lhe disse: \"Tu és um homem morto por causa da mulher que tomaste, porque ela tem marido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Ora, Abimeleque, que não havia tocado nela, disse: \"Senhor, matarás também uma nação justa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Não foi ele quem me disse: \'Ela é minha irmã?\'. E ela também me disse: \'Ele é o meu irmão\'. Fiz isso com integridade no meu coração e na inocência de minhas mãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Então, Deus lhe respondeu no sonho: \"Sim, Eu sei que fizestes isso na integridade do teu coração e também te impedi de pecar contra Mim, por isso, não permiti que tu a tocasses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Agora, devolva a mulher ao marido dela, pois ele é um profeta e orará por ti e tu viverás. Mas, se tu não a devolveres, morrerás tu e todos os teus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Abimeleque levantou-se cedo e chamou todos os servos. Ele contou todas essas coisas aos homens, que ficaram com muito medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Então, Abimeleque chamou Abraão e lhe disse: \"O que fizeste a nós? Em que pequei contra ti, para que trouxesses grande pecado sobre mim e meu reino? Fizeste a mim coisa que não se deve fazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Disse mais Abimeleque a Abraão: \"O que te levou a fazer tais coisas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraão respondeu: \"Porque eu dizia comigo mesmo: \'Certamente não há o temor de Deus neste lugar e eles me matarão por causa da minha mulher\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Além disso, ela é de fato minha irmã, filha do meu pai, mas não é filha da minha mãe; e veio a ser minha mulher.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Quando Deus me fez sair errante da casa de meu pai, eu disse a Sara: \'Tu deves me mostrar lealdade como minha mulher: Em todo lugar onde formos, dirás sobre mim: Ele é meu irmão\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Então, Abimeleque pegou ovelhas e gados; escravos e escravas e os deu a Abraão. E lhe devolveu Sara, mulher de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Abimeleque disse: \"Eis que a minha terra está diante de ti. Habite onde te agradares\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'E disse para Sara: \"Eis que dei ao teu irmão mil moedas de prata, para reparação da ofensa contra ti, diante de todos os teus; assim, estais completamente justificada perante todos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'E Abraão orou a Deus e Deus curou Abimeleque, sua mulher e suas concubinas, para que pudessem ter filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Porque Yahweh havia tornado estéreis todas as mulheres da casa de Abimeleque, por causa de Sara, mulher de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Yahweh atentou para Sara, como Ele disse que faria, e fez por ela exatamente como havia prometido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Sara concebeu e deu à luz um filho para Abraão em sua velhice, no tempo determinado que Deus havia falado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Abraão chamou seu filho recém-nascido, a quem Sara dera à luz, com o nome de Isaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Abraão circuncidou seu filho Isaque aos oito dias de idade, como Deus havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abraão tinha cem anos de idade quando seu filho Isaque nasceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Sara disse: \"Deus me fez rir; todos quantos ouvirem rirão comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'E acrescentou: \"Quem diria a Abraão que Sara amamentaria filhos? Dei a ele um filho na sua velhice!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'A criança cresceu e foi desmamada, e Abraão fez um grande banquete no dia em que Isaque foi desmamado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Sara viu o filho de Agar, a egípcia que ela havia dado a Abraão, zombando de Isaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Então, ela disse a Abraão: \"Expulsa essa escrava e seu filho, pois o filho dessa escrava não será herdeiro com meu filho Isaque\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Essa palavra desagradou muito a Abraão por causa de seu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Porém, Deus disse a Abraão: \"Não fiques triste por causa do rapaz e por causa de sua serva. Escuta as palavras de Sara em tudo o que te diz sobre esse assunto, porque é por meio de Isaque que a tua descendência será chamada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Eu também farei do filho da serva uma nação, porque ele é teu descendente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Abraão se levantou cedo pela madrugada, pegou pão e um odre de água e o deu a Agar, colocando-o em seu ombro. Ele entregou-lhe o menino e despediu-a. Ela partiu e vagou pelo deserto de Berseba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Quando a água do odre acabou, ela abandonou o menino debaixo de um arbusto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Então, ela foi e se sentou à distância de um tiro de arco, porque disse: \"Não verei a morte do menino\". Ela sentou adiante dele, ergueu a voz e chorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Deus ouviu a voz do rapaz, e o Anjo de Deus chamou Agar desde o céu e lhe disse: \"Que tens, Agar? Não tenhas medo, pois Deus ouviu a voz do rapaz de onde ele está.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Levanta-te, ergue o rapaz e segura-o pela mão, pois farei dele uma grande nação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Então, Deus abriu seus olhos, e ela viu um poço. Ela foi, encheu o odre de água e deu de beber ao rapaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Deus era com o rapaz; ele cresceu, viveu no deserto e tornou-se um flecheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Ele viveu no deserto de Parã, e sua mãe tomou para ele uma mulher da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Naquele tempo, Abimeleque e Ficol, o capitão do seu exército, falaram a Abraão, dizendo: \"Deus é contigo em tudo o que fazes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Agora, portanto, promete-me aqui, por Deus, que não irás tratar falsamente a mim, nem a meu filho, nem a meu neto. Mostra a mim e à terra em que tens estado a mesma benevolência que tenho mostrado a ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Abraão disse: \"Eu prometo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'E Abraão reclamou a Abimeleque por causa de um poço de água do qual os servos de Abimeleque tinham se apropriado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Abimeleque disse: \"Eu não sei quem fez isso. E também não me contaste isso antes; nunca ouvi falar disso até hoje\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Então, Abraão tomou ovelhas e um boi e os deu a Abimeleque, e os dois homens fizeram um acordo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Pôs Abraão à parte sete cordeiras do rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Abimeleque disse a Abraão: \"Qual é o significado dessas cordeiras que tu colocaste à parte?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Ele respondeu: \"Estas sete cordeiras receberás da minha mão para que possam ser um testemunho de que cavei este poço\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Então, ele chamou aquele lugar de Berseba, porque ambos fizeram um juramento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Eles fizeram um acordo em Berseba, e Abimeleque e Ficol, o capitão do seu exército, retornaram à terra dos filisteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Abraão plantou uma tamargueira em Berseba e ali invocou o nome de Yahweh, o eterno Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Abraão permaneceu como um peregrino na terra dos filisteus por muitos dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Aconteceu que, depois dessas coisas, Deus provou Abraão e disse: \"Abraão!\" Ele respondeu: \"Aqui estou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'E disse Deus: \"Toma teu filho, teu único filho, a quem amas, Isaque, e vai para a terra de Moriá; e oferece-o ali em holocausto, sobre uma das montanhas que Eu te mostrarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'E Abraão se levantou cedo pela manhã, selou seu jumento, tomou dois de seus jovens com ele, juntamente com Isaque, seu filho, e cortou a madeira para o holocausto. Então, partiu em seu jumento para o lugar que Deus havia falado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Ao terceiro dia, Abraão ergueu os olhos e viu o lugar de longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Abraão disse para seus jovens: \"Ficai aqui com o jumento, e eu e o rapaz iremos até lá. Nós adoraremos e voltaremos a vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Então, Abraão pegou a madeira para o holocausto e a colocou sobre Isaque, seu filho. Tomou o fogo e a faca em suas próprias mãos e seguiram juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'E Isaque disse a seu pai, Abraão: \"Meu pai!\". Respondeu ele: \"Aqui estou eu, meu filho\". E disse ele: \"Eis aqui o fogo e a madeira, mas onde está o cordeiro para o holocausto?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraão disse: \"Deus proverá para Si o cordeiro para o holocausto, meu filho\". E seguiram juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Quando chegaram ao lugar que Deus havia mostrado, Abraão construiu ali o altar e colocou a madeira sobre ele; amarrou Isaque, seu filho, e o colocou sobre o altar, em cima da madeira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'E, estendendo a mão, pegou a faca para sacrificar seu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Então, o Anjo de Yahweh o chamou do céu e disse: \"Abraão, Abraão!\". E ele respondeu: \"Aqui estou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'E o Anjo disse: \"Não estendas a mão sobre o rapaz, nem lhe faças mal algum, pois agora sei que temes a Deus, porque não Me negaste teu filho, teu único filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Abraão olhou para cima e viu atrás de si um carneiro preso nos arbustos pelos chifres. Abraão foi, pegou o carneiro e o ofereceu em holocausto no lugar de seu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Abraão chamou aquele lugar: \"Yahweh Proverá\", sobre o qual se diz até o dia de hoje, \"No Monte de Yahweh, haverá provisão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'O Anjo de Yahweh chamou Abraão uma segunda vez, desde o céu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'e disse: \"Por Mim jurei, diz Yahweh, porque fizeste assim e não negaste o teu filho, teu único filho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'certamente abençoarei e multiplicarei a tua descendência como as estrelas dos céus e como a areia na praia do mar; e teus descendentes dominarão a cidade de teus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Em tua descendência, serão benditas todas as nações da terra, pois tu obedeceste a Minha voz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Então, Abraão retornou aos seus jovens, eles partiram e foram juntos a Berseba. E ele viveu em Berseba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'E aconteceu que, depois dessas coisas, disseram a Abraão: \"Milca também deu à luz filhos ao teu irmão Naor:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Uz, seu primogênito; Buz, seu irmão; Quemuel, pai de Arão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Quesede; Hazo; Pildas; Jidlafe e Betuel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Betuel gerou a Rebeca. Milca deu à luz esses oito filhos de Naor, irmão de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'A concubina de Naor, cujo nome era Reumá, também deu à luz Teba, Gaão, Taás e Maacá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Sara viveu cento e vinte e sete anos. Esses foram os anos da vida de Sara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Sara morreu em Quiriate-Arba, que é Hebrom, na terra de Canaã. Abraão lamentou e chorou por Sara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Então, Abraão se levantou, afastou-se do corpo de sua falecida mulher e falou com os descendentes de Hete, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '\"Eu sou um estrangeiro entre vós. Por favor, permiti-me adquirir uma área para sepulcro entre vós, para que eu possa sepultar minha falecida mulher\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Os descendentes de Hete responderam a Abraão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '\"Ouve-nos, meu senhor. Tu és um príncipe de Deus entre nós. Sepulta tua mulher na melhor de nossas sepulturas. Nenhum de nós te recusará uma sepultura, para que possas sepultar tua mulher\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Abraão se levantou, curvou-se diante do povo da terra, os descendentes de Hete,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'e lhes falou dizendo: \"Se vós concordardes que eu sepulte minha mulher em vossa terra, então, falai por mim a Efrom, filho de Zoar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Pedi a ele que me venda a gruta de Macpela, que lhe pertence, a qual está na extremidade de seu campo; que me conceda pelo devido preço, em herança de sepulcro no meio de vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Então, o heteu Efrom, que estava sentado entre os descendentes de Hete, respondeu a Abraão, de modo que ouvissem tanto os heteus como aqueles que haviam vindo pelo portão de sua cidade, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, '\"Não, meu senhor, ouve-me. Dou-te o campo e a gruta que nele está. Concedo-te na presença dos filhos do meu povo para que sepultes tua mulher\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Então, Abraão se inclinou diante das pessoas daquela terra');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'e falou a Efrom, aos ouvidos de todas aquelas pessoas, dizendo: \"Se estás de acordo, peço-te que me ouças. Pagarei o preço do campo; recebe-o de mim, e ali sepultarei minha mulher\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Efrom respondeu a Abraão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '\"Por favor, meu senhor, ouve-me. Um pedaço de campo vale quatrocentos siclos de prata. O que é isso entre mim e ti? Sepulta tua falecida mulher\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Abraão ouviu a Efrom e pesou para ele a quantidade de prata que havia falado aos ouvidos dos descendentes de Hete, quatrocentos siclos de prata, moeda corrente entre os mercadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Assim, o campo de Efrom, que estava em Macpela, próximo de Manre, isto é, o campo, a gruta e as árvores que estavam nele e todo o limite ao redor foram transferidos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'a Abraão na presença dos descendentes de Hete e diante de todos que entraram pelo portão de sua cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Depois disso, Abraão sepultou Sara, sua mulher, na gruta do campo de Macpela, próximo de Manre, que é Hebrom, na terra de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Assim, o campo e a gruta foram transferidos a Abraão pelos descendentes de Hete como propriedade de sepultura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraão estava velho, com idade bem avançada, e Yahweh abençoou Abraão em todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Abraão disse ao seu servo, o mais velho de sua casa e encarregado de tudo o que ele tinha: \"Coloca tua mão sob minha coxa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'e eu te farei jurar por Yahweh, o Deus do céu e o Deus da terra, que tu não tomarás mulher para meu filho das filhas dos cananeus, dentre os quais eu habito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Mas tu irás para minha terra e para meus parentes e tomarás uma mulher para meu filho Isaque\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'O servo lhe disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, '\"E se a mulher não estiver disposta a me seguir até esta terra? Devo levar teu filho de volta à terra da qual ele veio?\". Abraão lhe disse: \"Certifica-te de que tu não leves meu filho de volta!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Yahweh, o Deus do céu, que me levou da casa do meu pai e da terra dos meus parentes e que me prometeu com um juramento dizendo: \'Para tua descendência, darei esta terra\', Ele enviará Seu Anjo antes de ti, e tu tomarás uma mulher para o meu filho lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Mas, se a mulher não quiser te seguir, então, tu estarás livre deste meu juramento. Só não deves levar meu filho de volta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Então, o servo colocou sua mão sob a coxa de Abraão, seu senhor, e jurou a ele sobre esse assunto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'O servo pegou dez dos camelos do seu senhor e partiu. Ele também levou consigo todos os tipos de presentes do seu senhor. Levantou-se e partiu para a Mesopotâmia, para a cidade de Naor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Ele fez os camelos se ajoelharem fora da cidade, perto do poço de água, ao entardecer, quando as moças saem para pegar água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'E disse: \"Yahweh, Deus do meu senhor Abraão, dá-me hoje bom êxito e faze benevolência para com meu senhor Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Eis que aqui estou, na fonte de água, e as filhas dos homens da cidade estão vindo tirar água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Que aconteça assim. Quando eu disser para uma jovem mulher: \'Por favor, abaixa teu cântaro para que eu possa beber\', e ela me disser: \'Bebe, e eu darei de beber aos teus camelos também\', então, ela será a que o Senhor designou ao Teu servo Isaque. Assim, saberei que mostraste Tua benevolência para com meu senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'E aconteceu que, antes mesmo de ele ter terminado de falar, Rebeca veio com seu cântaro de água em seu ombro. Rebeca era filha de Betuel, filho de Milca, mulher de Naor, irmão de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'A jovem era de boa aparência, virgem, a quem nenhum homem havia conhecido. Ela foi à fonte, encheu seu cântaro e subiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Então, o servo correu para encontrá-la e disse: \"Por favor, dá-me um pouco de água do teu cântaro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Ela disse: \"Bebe, meu senhor\" e rapidamente abaixou seu cântaro em sua mão e o deu de beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Quando ela havia acabado de dar-lhe de beber, disse: \"Eu darei água a teus camelos também, até que eles tenham terminado de beber\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Então, ela se apressou, esvaziou completamente seu cântaro no bebedouro, correu novamente ao poço para tirar água e tirou água para todos camelos dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'O homem observava em silêncio para ver se Yahweh havia tornado próspera sua jornada ou não.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'E aconteceu que, quando os camelos terminaram de beber, o homem pegou um pendente de ouro, pesando meio siclo, e duas pulseiras para seus braços, pesando dez siclos de ouro');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'e perguntou: \"Tu és filha de quem? Dize-me, por favor, há local na casa do teu pai para passarmos a noite?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Ela lhe disse: \"Sou filha de Betuel, filho de Milca, que ela deu a Naor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Ela também lhe disse: \"Temos bastante palha e alimento e também local para que possas passar a noite\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Então, o homem se curvou e adorou a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Ele disse: \"Abençoado seja Yahweh, o Deus do meu senhor Abraão, que não abandonou Sua benevolência e Sua confiabilidade para com meu senhor. Quanto a mim, Yahweh me levou diretamente à casa dos parentes de meu senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Então, a moça correu e disse à família de sua mãe sobre todas essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Ora, Rebeca tinha um irmão, e seu nome era Labão. E correu Labão até o homem que estava na estrada, próximo à fonte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Quando ele viu o pendente de ouro e as pulseiras nos braços de sua irmã e tendo ouvido também as palavras de sua irmã Rebeca: \"Foi isso que o homem me disse\", ele foi até o homem, e este estava próximo aos camelos, na fonte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'E Labão disse: \"Vem, abençoado de Yahweh. Por que estás aí fora? Eu preparei a casa e um lugar para os camelos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Então, o homem foi até a casa e desatou os camelos. Palha e alimento foram dados aos camelos, e água foi providenciada para lavar os pés dele e os pés dos homens que estavam com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Serviram-lhe comida, mas ele disse: \"Não comerei até que eu tenha dito o que tenho para dizer\". Então, Labão disse: \"Fala\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Ele disse: \"Eu sou servo de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Yahweh abençoou muito o meu senhor, e ele tem prosperado. Ele deu-lhe ovelhas e bois, prata e ouro, escravos e escravas, camelos e jumentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Sara, a mulher de meu senhor, já era velha quando gerou um filho para ele. E ele lhe deu tudo o que possuía.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Meu senhor me fez jurar, dizendo: \'Não tomarás mulher para meu filho das filhas dos cananeus, dentre os quais eu habito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Em vez disso, tu irás para minha terra e para meus parentes e tomarás uma mulher para meu filho\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Eu disse ao meu senhor: \'Talvez a mulher não me siga\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Mas ele me disse: \'Yahweh, diante de quem eu caminho, enviará Seu Anjo contigo, e Ele fará prosperar teu caminho, para que tomes uma mulher para meu filho dentre a minha família e dentre a casa de meu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Mas serás liberto do meu juramento se fores à minha família e eles se recusarem a entregá-la para ti. Só então, serás livre do meu juramento\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Então, hoje cheguei junto à fonte e disse: \'Ó Yahweh, Deus do meu senhor Abraão, se assim desejares, dá-me hoje bom êxito na missão que vou fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Aqui estou eu, próximo à fonte de água. Faz com que a moça que vier pegar água, aquela a quem eu disser: \'Por favor, dá-me um pouco de água do teu cântaro para que eu beba\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'e a moça disser-me: \'Bebe, e irei também pegar água para teus camelos\', que seja a moça que Tu, Yahweh, escolheste para o filho do meu senhor\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Mesmo antes de eu terminar de falar no meu coração, Rebeca veio com seu cântaro em seu ombro e desceu à fonte para tirar água. Então, eu lhe disse: \'Por favor, dá-me de beber\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Ela rapidamente abaixou cântaro do seu ombro e disse: \'Bebe e também darei água aos teus camelos\'. Então, eu bebi e ela deu de beber aos meus camelos também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Eu lhe perguntei, dizendo: \'És filha de quem?\'. Ela disse: \'Sou filha de Betuel, filho de Naor e Milca\'. Então, eu coloquei um pendente em seu nariz e as pulseiras em seus braços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Então, curvei-me e adorei a Yahweh, e bendisse a Yahweh, o Deus do meu senhor Abraão, que me conduziu pelo caminho correto para encontrar a filha dos parentes do meu senhor para seu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Entretanto, se estais preparados para tratar meu senhor como família, fielmente e confiavelmente, dizei-me. Mas senão, dizei-me, para que eu possa tomar o caminho da direita ou da esquerda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Então, Labão e Betuel responderam, dizendo: \"Isso vem de Yahweh; não podemos falar-te mal ou bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Eis que Rebeca está diante de ti. Leva-a e vai, para que ela possa ser a mulher do filho do teu senhor, como Yahweh disse\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Quando o servo de Abraão ouviu-lhes, prostrou-se ao chão perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'O servo trouxe peças de prata e ouro e vestimentas e os deu a Rebeca. Ele também deu presentes preciosos para seu irmão e sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Comeram e beberam ele e os homens que estavam com ele. Passaram a noite lá e, quando se levantaram de manhã, ele disse: \"Deixai-me ir para o meu senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Seu irmão e sua mãe disseram: \"Deixa a jovem permanecer conosco por ao menos dez dias. Depois ela pode partir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Mas ele lhes disse: \"Não me impeçais, já que Yahweh fez meu caminho prosperar. Deixai-me no meu caminho para que eu possa ir até meu senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Eles disseram: \"Chamaremos a jovem e lhe perguntaremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Então, eles chamaram Rebeca e perguntaram: \"Irás com este homem?\". Ela respondeu: \"Irei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Então, enviaram sua irmã Rebeca junto com sua ama-de-leite, em sua jornada, com o servo de Abraão e seus homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Eles abençoaram Rebeca e disseram-lhe: \"Nossa irmã, que sejas mãe de milhares de dezenas de milhares e que teus descendentes possuam o portão daqueles que os odeiam\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Então, Rebeca se levantou e, junto às suas servas, montou os camelos e seguiu o homem. Logo o servo levou Rebeca e seguiu o seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Ora, Isaque morava no Neguebe e havia acabado de retornar de Beer-Laai-Roi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Isaque foi meditar no campo, ao anoitecer. Quando ele olhou para cima, viu que havia camelos vindo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Rebeca olhou e, quando viu Isaque, saltou do camelo e');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'disse ao servo: \"Quem é aquele homem que está caminhando no campo para encontrar-nos?\". O servo disse: \"É o meu senhor\". Então, ela tomou seu véu e se cobriu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'O servo contou a Isaque todas as coisas que havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Então, Isaque conduziu-a até a tenda de sua mãe, Sara, e tomou a Rebeca, que se tornou sua mulher, e ele a amou. Então, Isaque foi consolado após a morte de sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraão tomou outra mulher; seu nome era Quetura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Ela deu à luz Zinrã, Jocsã, Medã, Midiã, Isbaque e Suá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Jocsã tornou-se pai de Seba e Dedã. Os povos Assurim, Letusim e Leumim eram descendentes de Dedã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Os filhos de Midiã foram Efá, Efer, Hanoque, Abidá e Eldá. Todos esses eram descendentes de Quetura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Abraão deu tudo o que possuía a Isaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'No entanto, enquanto era vivo, deu presentes aos filhos de suas concubinas e lhes enviou para a terra ao leste, distante de Isaque, seu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Estes são os dias dos anos da vida de Abraão: cento e setenta e cinco anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Abraão expirou e morreu em boa velhice, idoso com uma vida plena, e foi reunido ao seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Isaque e Ismael, seus filhos, enterraram-no na caverna de Macpela, no campo de Efrom, filho de Zoar, o heteu, perto de Manre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Abraão havia comprado esse campo dos filhos dos heteus. Ele fora enterrado juntamente com Sara, sua esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Logo após sua morte, Deus abençoou Isaque, seu filho, e Isaque viveu perto de Beer-Laai-Roi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Estes são os descendentes de Ismael, filho de Abraão, o qual Agar, a egípcia, serva de Sara, concedeu a Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Estes foram os nomes dos filhos de Ismael, de acordo com a ordem de nascimento: Nebaiote, o primogênito de Ismael, Quedar, Abdeel, Mibsão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Dumá, Massá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadade, Tema, Jetur, Nafis e Quedemá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Esses foram os filhos de Ismael e seus nomes, dados às suas vilas e aos seus acampamentos; doze chefes conforme suas tribos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Estes são os anos de vida de Ismael: cento e trinta e sete anos. Ele expirou e morreu, e foi reunido ao seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Eles habitaram desde Havilá até Sur, perto do Egito, como quem vai em direção à Assíria. Eles viviam em hostilidade um com o outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Estes são os eventos relacionados a Isaque, filho de Abraão. Abraão tornou-se pai de Isaque,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'e este tinha quarenta anos quando tomou por mulher Rebeca, filha de Betuel, o arameu de Padã-arã, e irmã de Labão, o arameu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Isaque orou a Yahweh por sua esposa, pois era estéril e Yahweh ouviu suas orações; Rebeca, sua esposa, engravidou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Os filhos lutavam dentro dela, e ela disse: \"Por que isso está acontecendo comigo?\". E foi consultar a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Yahweh disse-lhe: \"Há duas nações em teu útero, e dois povos serão separados de teu ventre. Um povo será mais forte que o outro, e o mais velho servirá o mais novo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Quando chegou o tempo de dar à luz, havia gêmeos em seu ventre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'O primeiro que saiu era todo ruivo e peludo, como uma vestimenta de pelos. E o chamaram de Esaú.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Logo em seguida, veio seu irmão, cuja mão segurava o calcanhar de Esaú. E lhe deram o nome de Jacó. Isaque tinha sessenta anos quando sua esposa os deu à luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Os meninos cresceram, e Esaú se tornou um caçador habilidoso, um homem do campo; porém, Jacó era um homem calmo que passava seu tempo nas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Isaque amava Esaú, pois ele comia os animais que seu filho caçava, já Rebeca amava Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Certa vez, Jacó havia feito um ensopado, quando Esaú chegou do campo, fraco de fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Então, Esaú disse a Jacó: \"Dá-me desse ensopado vermelho, por favor. Estou faminto!\". Por isso, ele foi chamado Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Jacó disse: \"Primeiro, vende-me o teu direito de primogenitura\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Esaú respondeu: \"Estou prestes a morrer. De que me serviria o direito da primogenitura?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'E Jacó retomou: \"Jura-me primeiro\". Então, Esaú fez um juramento e, desse modo, vendeu-lhe seu direito de primogenitura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Jacó deu pão e o ensopado de lentilhas a seu irmão. Ele comeu e bebeu, então, levantou-se e seguiu o seu caminho. Assim, Esaú desprezou o seu direito de primogenitura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Houve grande fome na terra, além da primeira, ocorrida nos dias de Abraão. Por isso, Isaque foi até Abimeleque, rei dos filisteus, em Gerar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'E Yahweh apareceu a ele e lhe disse: \"Não desças até o Egito, habita na terra que Eu te mostrarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Permanece nesta mesma terra, e Eu serei contigo e te abençoarei; pois darei a ti e aos teus descendentes todas estas terras, e cumprirei o que jurei a teu pai Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Multiplicarei a tua descendência como as estrelas do céu, e darei à tua semente todas estas terras. Em tua descendência, serão abençoadas todas as nações da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Farei isso, porque Abraão obedeceu à Minha voz e guardou a Minha prescrição, as Minhas ordenanças, os Meus estatutos e as Minhas leis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Isaque assim habitou em Gerar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Quando os homens do lugar lhe perguntaram sobre sua mulher, ele respondeu: \"É minha irmã\". Pois temeu dizer: \"É minha mulher\". Ele pensou consigo: \"Os homens deste lugar tentarão me matar para possuir Rebeca, pois ela é de boa aparência\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Isaque permaneceu ali por longo tempo. E aconteceu que Abimeleque, rei dos filisteus, olhou pela janela e viu Isaque acariciando Rebeca, sua mulher.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Abimeleque chamou Isaque e disse: \"É evidente que ela é tua mulher. Então, por que disseste: \'É minha irmã\'?\" Isaque respondeu-lhe: \"Porque temi que me matassem por causa dela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimeleque disse: Por que fizeste isso conosco? Se alguém de nós deitasse com tua mulher, tu terias trazido culpa sobre nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Então, Abimeleque ordenou a todo o povo, dizendo: \"Quem tocar neste homem ou na sua mulher, certamente será morto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Isaque semeou naquela terra e, no mesmo ano, colheu cem vezes mais, pois Yahweh o abençoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'O homem se enriqueceu e prosperou até tornar-se extremamente rico.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Possuía muitas ovelhas e gado, e grande número de servos, de modo que os filisteus o invejavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'E, por isso, os filisteus entulharam e entupiram com terra todos os poços cavados pelos servos nos dias de Abraão, seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Então, Abimeleque disse: \"Aparta-te de nós, pois tu és muito mais poderoso do que nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'E Isaque partiu dali, acampou-se no vale de Gerar, onde habitou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Isaque tornou a cavar os poços de água feitos nos dias de Abraão, seu pai, que os filisteus haviam entulhado, após a morte de Abraão. Isaque chamou os poços pelos mesmos nomes que seu pai já lhes havia dado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Assim que os servos de Isaque cavaram no vale, acharam uma fonte de águas correntes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Os pastores de Gerar contenderam com os pastores de Isaque, dizendo: \"Essa água nos pertence\". Por isso, Isaque deu ao poço o nome Eseque, pois disputaram por causa dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'E cavaram outro poço, e contenderam também por causa desse; por isso, foi-lhe dado o nome Sitna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Ele partiu dali e cavou ainda outro poço, contudo não contenderam por esse. Então, chamou o nome dele Reobote, pois disse: \"Yahweh agora nos deu um lugar, e prosperaremos na terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'E Isaque subiu dali a Berseba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Yahweh apareceu-lhe naquela noite e disse: \"Eu Sou o Deus de Abraão, teu pai. Não temas, pois Eu estou contigo e te abençoarei e multiplicarei a tua descendência, por causa de Meu servo Abraão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Isaque edificou ali um altar e invocou o nome de Yahweh. Ali ele armou a sua tenda, e seus servos cavaram um poço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Então, Abimeleque veio desde Gerar com Auzate, seu amigo, e Ficol, o chefe do seu exército, para encontrá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Isaque lhes disse: \"Por que viestes até mim, visto que me tratastes com hostilidade e me expulsastes do vosso meio?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'E lhe responderam: \"Temos visto claramente que Yahweh está contigo. Então, decidimos que deveria haver um juramento entre nós, sim, entre nós e ti. Portanto, permite-nos fazer uma aliança contigo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Tu não nos farás mal, assim como nós não te tocamos ete tratamos bem e te deixamos ir em paz. De fato, tu és o bendito de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Então, Isaque lhes ofereceu um banquete, e eles comeram e beberam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'E se levantaram de manhã e juraram um ao outro. Depois, Isaque os despediu e eles partiram em paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Naquele mesmo dia, os servos de Isaque vieram e contaram-lhe sobre o poço que haviam cavado. E disseram-lhe: \"Encontramos água\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'E deu ao poço o nome Seba, por isso, a cidade se chama Berseba até os dias de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Quando Esaú tinha quarenta anos, tomou por mulher Judite, a filha de Beeri, o heteu, e Basemate, a filha de Elom, o heteu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Elas trouxeram amargura de espírito para Isaque e Rebeca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Quando Isaque estava velho e seus olhos fracos, de modo que não podia enxergar, ele chamou Esaú, seu filho mais velho, e lhe disse: \"Meu filho\". Disse ele: \"Estou aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Ele disse: \"Olha, estou velho. Eu não sei o dia da minha morte;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Portanto pega tuas armas, tua aljava e o teu arco, vai para o campo e caça para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Faze uma comida deliciosa, do jeito que eu gosto, para que eu possa comer e te abençoar antes que eu morra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebeca ouviu quando Isaque falou com Esaú, seu filho. Esaú foi para o campo caçar e trazer a caça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Rebeca falou com Jacó, seu filho, e disse: \"Olha, eu ouvi teu pai falar com Esaú, teu irmão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '\'Traze-me uma caça e faze-me uma comida deliciosa, para que eu possa comer e te abençoar na presença de Yahweh antes da minha morte\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Portanto agora, meu filho, atende às minhas palavras naquilo que eu te ordenar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Vai até o rebanho, traze-me dois bons cabritos; e eu farei uma comida deliciosa para teu pai, do jeito que ele gosta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Tu levarás para teu pai para que ele coma, de modo que te abençoe, antes da sua morte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jacó disse a Rebeca sua mãe: \"Meu irmão é um homem peludo, e eu sou um homem liso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Porventura meu pai tocará em mim e me perceberá como um enganador. Eu trarei maldição sobre mim ao invés de bênção\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Sua mãe disse-lhe: \"Meu filho, que qualquer maldição caia sobre mim. Apenas atende às minhas palavras, e vai, e traze-os para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Então, Jacó foi, pegou os cabritos novos e os levou para sua mãe. Ela fez uma comida deliciosa, do jeito que o seu pai gostava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Rebeca pegou a melhor roupa de Esaú, o filho mais velho, a qual estava com ela em sua casa, e vestiu-a em Jacó, seu filho mais novo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Ela cobriu com a pele dos cabritos as mãos dele e a parte lisa do seu pescoço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Colocou a comida deliciosa e o pão que havia preparado nas mãos de seu filho Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Jacó foi até seu pai e disse: \"Meu pai\". Ele respondeu: \"Aqui estou; quem és tu, meu filho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jacó lhe disse: \"Eu sou Esaú, teu primogênito; eu tenho feito conforme ordenaste. Agora senta-te e come da minha caça para que me abençoes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Isaque disse a seu filho: \"Como tu encontraste a caça tão rápido, meu filho?\". Ele respondeu: \"Porque Yahweh, o teu Deus, trouxe até mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Isaque disse a Jacó: \"Aproxima-te de mim para que eu possa tocar-te, meu filho, e ver se és verdadeiramente meu filho Esaú ou não\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Jacó aproximou-se do seu pai Isaque, e este o tocou e disse: \"A voz é a de Jacó, mas as mãos são as de Esaú\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Isaque não o reconheceu, porque suas mãos eram peludas, como as de seu irmão Esaú. Então, Isaque o abençoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Ele perguntou: \"És tu realmente meu filho Esaú?\". E ele disse: \"Eu sou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Isaque disse: \"Traze a comida para mim, comerei da tua caça, e te abençoarei\". Jacó trouxe a comida para o seu pai. Isaque comeu, e Jacó trouxe-lhe vinho, e ele bebeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Logo, seu pai disse: \"Aproxima-te e me dá um beijo, meu filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Jacó aproximou-se e o beijou, e ele sentiu o cheiro da sua roupa e o abençoou, dizendo: \"Vê, o cheiro do meu filho é cheiro do campo que Yahweh tem abençoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Que Deus te dê a porção do orvalho do céu, a porção da fartura da terra e abundância de trigo e de vinho novo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Que os povos sirvam-te e as nações prostrem-se diante de ti. Sê mestre dos teus irmãos, e que os filhos da tua mãe inclinem-se diante de ti. Que todos que te amaldiçoarem sejam amaldiçoados, e todos que te abençoarem sejam abençoados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Assim que Isaque abençoou Jacó, e ele saiu da sua presença, Esaú seu irmão veio da sua caça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Ele também fez uma comida deliciosa e a trouxe para seu pai, dizendo: \"Pai, levanta-te, come algo da caça do teu filho, para que possas me abençoar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Isaque disse: \"Quem és tu?\", Ele disse: \"Eu sou teu filho, teu primogênito, Esaú\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Isaque ficou muito abalado e disse: \"Quem era aquele que trouxe a caça para mim? Eu comi tudo antes que tu viesses, e eu o abençoei. Certamente, ele será abençoado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Quando Esaú ouviu as palavras do seu pai, chorou com muita amargura e disse-lhe: \"Abençoa-me também, meu pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Isaque disse: \"Teu irmão veio aqui com esperteza e levou tua bênção\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Esaú disse: \"Não é com razão que ele seja chamado de Jacó? Ele enganou-me por duas vezes. Levou meu direito de primogenitura e agora levou minha bênção\". Então, perguntou: \"Tu não tens reservada uma bênção para mim?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isaque respondeu a Esaú: \"Olha, eu o coloquei por senhor sobre ti, dei-lhe todos seus irmãos como seus servos. E dei a ele fartura de trigo e vinho novo. O que mais posso fazer por ti, meu filho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Esaú disse ao seu pai: \"Não tens ainda uma bênção para mim, meu pai? Abençoa-me também, meu pai\". Esaú chorou em alta voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Isaque respondeu e disse-lhe: \"Olha, o lugar onde tu vais morar será longe das terras férteis, longe do orvalho que cai do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Pela tua espada viverás e tu servirás a teu irmão. Mas, quando te livrares, sacudirás o jugo do teu pescoço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Esaú odiou Jacó por causa da bênção que seu pai lhe dera. Esaú disse em seu coração: \"Os dias de luto por meu pai estão próximos; depois disso, eu matarei meu irmão Jacó\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'As palavras de Esaú, o primogênito, foram relatadas a Rebeca. Então, ela mandou chamar Jacó, seu filho mais novo, e disse-lhe: \"Vê, teu irmão Esaú se consolou planejando matar-te.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Portanto, agora, meu filho, obedece-me e foge para a casa de Labão, meu irmão, em Harã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Fica com ele por alguns dias, até que a fúria do teu irmão diminua e que ele esqueça o que tu tens feito a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Logo, eu te trarei de volta. Por que deveria eu perder os dois filhos em um dia?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Rebeca disse a Isaque: \"Estou aborrecida da vida por causa das filhas dos heteus. Se Jacó tomar uma das filhas dos heteus, filhas desta terra, o que será da minha vida?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Isaque chamou Jacó, abençoou-o, e ordenou-lhe: \"Não tomes mulher dentre as cananéias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Levanta-te, vai a Padã-Arã, à casa de Betuel, pai de tua mãe, e toma de lá uma mulher, uma das filhas de Labão, irmão de tua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Que o Deus Todo Poderoso te abençoe, e te faça frutificar, e te multiplique para que te tornes uma multidão de povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Que Ele te dê a bênção de Abraão, a ti e a teus descendentes, para que possas herdar a terra onde tu tens peregrinado, a qual Deus prometeu a Abraão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Assim Isaque despediu-se de Jacó, que se foi para Padã-Arã, à casa de Labão, que era filho de Betuel, o arameu, e irmão de Rebeca, mãe de Jacó e Esaú.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Então, Esaú viu que Isaque abençoou Jacó e o enviou à Padã-Arã para tomar uma esposa de lá. Ele também viu que, abençoando-o, Isaque tinha dado uma ordem dizendo: \"Não tomes uma esposa dentre as cananeias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'Esaú também viu que Jacó havia obedecido a seu pai e sua mãe, e ido até Padã-Arã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Esaú viu que as mulheres de Canaã não agradavam Isaac, seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Então, ele foi a Ismael e, apesar das mulheres que já possuía, tomou Maalate por mulher, filha de Ismael, filho de Abraão, e irmã de Nabaiote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Partiu Jacó de Berseba e seguiu para Harã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Tendo chegado a certo lugar para pernoitar, porque o sol já era posto, pegou uma das pedras, colocou embaixp de sua cabeça e se deitou ali para dormir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Ele sonhou e viu uma escada posta sobre a terra cujo topo alcançava o céu; e os anjos de Deus subiam e desciam por ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Acima dela, estava Yahweh, que disse: \"Eu sou Yahweh, o Deus de teu pai Abraão, e o Deus de Isaque. A terra em que estás deitado darei a ti e a teus descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Tua descendência será como o pó da terra, e tu te estenderás para o ocidente, para o oriente, para o norte e para o sul; todas as famílias da terra serão abençoadas por meio de ti e de teus descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Eis que estou contigo e te guardarei por onde fores. Eu te farei retornar a esta terra; não te deixarei, até que se tenha cumprido tudo o que te prometi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Jacó acordou do seu sono e disse: \"Realmente, Yahweh está neste lugar e eu não sabia\". Ele temeu e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, '\"Quão terrível é este lugar! Este não é outro lugar, senão a casa de Deus; esta é a porta para o céu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Então, Jacó levantou-se cedo pela manhã, tomou a pedra que havia usado como travesseiro, a pôs por coluna e derramou óleo sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Chamou aquele lugar de Betel, mas o nome da cidade era originalmente Luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'E Jacó fez um voto, dizendo: \"Se Deus estiver comigo e me proteger nesta jornada, e me der pão para comer, roupas para vestir,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'para que eu retorne salvo para a casa de meu pai, então, Yahweh será meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'E esta pedra que tenho posto por coluna será Casa de Deus, e de tudo quanto me deres, certamente eu darei um décimo a Ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Então, Jacó seguiu viagem e chegou à terra dos povos do leste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Enquanto ele olhava, viu um poço no campo e três rebanhos de ovelhas deitadas junto a ele, pois desse poço é que davam de beber aos rebanhos. Entretanto, havia uma grande pedra por cima da boca do poço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Quando todos os rebanhos estavam lá reunidos, os pastores rolavam a pedra da boca do poço e davam de beber às ovelhas; então, recolocavam a pedra por cima da boca do poço de volta em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Jacó lhes disse: \"Meus irmãos, de onde sois vós?\". Eles responderam: \"Somos de Harã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Ele lhes disse: \"Vós conheceis Labão, filho de Naor?\". E disseram: \"Nós o conhecemos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Jacó lhes perguntou: \"Ele está bem?\". Eles disseram: \"Ele está bem, e olhe ali, Raquel, sua filha, está chegando com as ovelhas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Jacó disse: \"Vê, estamos na metade do dia e não é a hora de recolher o rebanho. Vós devíeis dar de beber às ovelhas, e, então, levá-las para pastar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Eles disseram: \"Nós não podemos dar de beber às ovelhas até que os rebanhos estejam reunidos. Então, os homens irão tirar a pedra da boca do poço e daremos de beber às ovelhas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Enquanto Jacó ainda falava com eles, Raquel veio com as ovelhas de seu pai, porque estava cuidando delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Quando viu Raquel, a filha de Labão, irmão da sua mãe, e as ovelhas de Labão, Jacó aproximou-se, rolou a pedra da boca do poço e deu de beber ao rebanho de Labão, irmão de sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Jacó beijou Raquel e chorou em alto som.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Jacó contou a Raquel que era parente de seu pai, e que era filho de Rebeca. Então, ela correu e contou ao seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Quando Labão ouviu as novidades sobre Jacó, filho de sua irmã, correu para conhecê-lo, abraçá-lo, beijá-lo e o trouxe para sua casa. Jacó contou a Labão todas essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Labão disse-lhe: \"Tu és de fato meu osso e minha carne\". Então, Jacó ficou com ele por um mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Então, Labão disse a Jacó: \"Porque tu és meu parente, deverias servir-me de graça? Dize-me, qual será o teu salário?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Ora, Labão tinha duas filhas. O nome da mais velha era Lia, e o nome da mais nova era Raquel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Os olhos de Lia eram meigos, mas Raquel era bonita em forma e aparência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Jacó amava Raquel. Então, ele disse: \"Eu te servirei sete anos por Raquel, sua filha mais nova\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Labão disse: \"É melhor dá-la a ti do que a outro homem. Fica comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Então, Jacó serviu sete anos por Raquel; e estes lhe pareceram poucos dias pelo amor que ele tinha por ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Então, Jacó disse a Labão: \"Dá-me minha esposa, porque os meus dias já se completaram; para que eu possa casar-me com ela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Então, Labão juntou todos os homens da região e fez uma festa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'À noite, Labão tomou Lia, sua filha, e levou-a até Jacó, que dormiu com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Labão deu sua serva Zilpa à sua filha para ser serva dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Pela manhã, viu Jacó que era Lia! Jacó disse a Labão: \"O que é isso que fizeste a mim? Eu não te servi por Raquel? Por que, então, me enganaste?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Labão disse: \"Não é nosso costume entregar a filha mais nova antes da primogênita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Completa a semana nupcial desta filha, e nós te daremos a outra em retorno, por me servir mais sete anos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jacó fez isso e completou a semana de Lia. Então, Labão deu também a ele Raquel, sua filha, como sua esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Labão deu também Bila à sua filha Raquel para ser serva dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Então, Jacó dormiu com Raquel também, mas ele a amava mais do que a Lia. Então, Jacó serviu Labão por mais sete anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Yahweh viu que Lia não era amada, então, ele abriu o ventre dela, mas Raquel era estéril.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Lia concebeu e deu à luz um filho, e ela o chamou Rúben. Pois disse: \"Porque Yahweh tem visto a minha aflição; certamente agora meu marido me amará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Então, ela concebeu outra vez e deu à luz um filho. Ela disse: \"Porque Yahweh ouviu que eu não sou amada, Ele me deu mais este filho\", e ela o chamou Simeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Então, ela concebeu novamente e deu à luz um filho. Ela disse: \"Agora, desta vez, meu marido estará apegado a mim, pois eu lhe dei três filhos\". Por isso, chamou-o Levi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Ela concebeu novamente e deu à luz um filho. Ela disse: \"Desta vez, louvarei Yahweh\". Assim, chamou-o Judá; então, ela parou de ter filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Quando Raquel viu que não dava nenhum filho a Jacó, ela sentiu inveja de sua irmã e disse a Jacó: \"Dá-me filhos, senão morrerei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'A raiva de Jacó acendeu-se contra Raquel. Ele disse: \"Por acaso estou eu no lugar de Deus, que te impediu de gerar filhos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Ela disse: \"Vê, aqui está a minha escrava Bila. Tem relações com ela, para que dê à luz e traga filhos ao meu colo, por meio dela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Assim, deu-lhe sua escrava Bila como esposa, e Jacó teve relações com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Bila concebeu e deu a Jacó um filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Então, Raquel disse: \"Deus me fez justiça, ouviu a minha voz e me deu um filho\". Por isso, o chamou de Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Bila, escrava de Raquel, concebeu novamente e deu a Jacó o segundo filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Raquel disse: \"Tive grandes lutas com minha irmã e venci\". Ela o chamou Naftali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Quando Lia percebeu que havia parado de ter filhos, tomou Zilpa, sua escrava e a deu para Jacó como esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Zilpa, serva de Lia, deu a Jacó um filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Então, Lia disse: \"Afortunada!\". E o chamou Gade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Depois Zilpa, serva de Lia, deu o segundo filho a Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Lia disse: \"Como sou feliz! As filhas me chamarão de feliz\". Então, ela o chamou Aser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Nos dias da colheita do trigo, Rúben foi ao campo e achou mandrágoras. Ele as trouxe para Lia, sua mãe. Então, Raquel disse a Lia: \"Dá-me algumas das mandrágoras do teu filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Lia disse-lhe: \"Acaso é pouco que tu tenhas tomado o meu marido? Queres também tomar as mandrágoras do meu filho?\". E disse Raquel: \"Jacó se deitará contigo esta noite em troca das mandrágoras de teu filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Jacó voltou do campo à tarde. Lia foi ao seu encontro e disse: \"Irás unir-te a mim esta noite, porque eu te aluguei em troca das mandrágoras do meu filho\". Então, Jacó teve relações com Lia naquela noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Deus escutou Lia e ela concebeu e deu a Jacó o quinto filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Lia disse: \"Deus me recompensou, pois dei minha escrava a meu marido\". Ela o chamou Issacar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Lia concebeu outra vez e deu o sexto filho a Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'E disse: \"Deus me deu um bom presente. Agora o meu marido me honrará, pois lhe dei seis filhos\". Ela o chamou Zebulom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Depois, deu à luz uma filha e a chamou Diná.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Lembrou-se Deus de Raquel. Ele a ouviu e a tornou fecunda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Ela concebeu e deu à luz um filho e disse: \"Deus retirou a minha vergonha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Ela o chamou José, dizendo: \"Que Yahweh acrescente-me outro filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Depois que Raquel deu à luz a José, Jacó disse a Labão: \"Manda-me embora, para que eu volte para minha casa e para minha terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Dá-me minhas mulheres e meus filhos, pelos quais eu te servi e deixa-me ir, pois sabes o serviço que te prestei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Labão disse-lhe: \"Se tenho achado favor aos teus olhos, espera, pois eu soube, por meio de adivinhações, que Yahweh me abençoou por causa de ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Então, ele disse: \"Estipula o teu salário e eu te pagarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Jacó disse-lhe: \"Tu sabes de que maneira te servi e como cuidei do teu rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Porque tu tinhas pouco antes da minha vinda, mas depois aumentou grandemente. Yahweh te abençoou por onde trabalhei. Agora, quando trabalharei também por minha casa?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Então, Labão disse: \"O que te darei?\". Jacó disse: \"Tu não me darás nada. Voltarei a apascentar e a guardar o teu rebanho se fizeres isto por mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Deixa-me passar por todo o teu rebanho hoje, separando dele todos os cabritos manchados e os malhados; e todos os negros entre os cordeiros; e as manchadas e malhadas entre as cabras. Este será o meu salário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Minha integridade vai atestar por mim, quando mais tarde verificares o meu salário. Tudo o que não for manchado e malhado entre as cabras, e negro entre os cordeiros; se for achado comigo, será considerado furtado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Labão disse: \"Está bem. Que seja de acordo com a tua palavra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Naquele dia, Labão separou os bodes listrados e malhados, todas as cabras manchadas e malhadas, todas que tinham algum branco e todos os negros entre os cordeiros e os deu nas mãos dos seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Labão pôs três dias de caminhada entre ele e Jacó. E Jacó continuou apascentando o restante dos rebanhos de Labão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Jacó tomou varas verdes de estoraque, de amendoeira e de plátano. Descascando-as, fez nelas riscas brancas, fazendo aparecer o branco que nelas havia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Então, ele pôs as varas que havia descascado em frente aos rebanhos, nos bebedouros onde bebiam. E eles acasalavam quando vinham beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Os rebanhos acasalavam diante das varas e os rebanhos davam crias listradas, manchadas e malhadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Jacó separou os cordeiros e pôs o rebanho para o lado dos listrados e dos negros no rebanho de Labão. Então, ele separou seu rebanho para si e não o colocou com o rebanho de Labão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Todas as vezes que os mais fortes do rebanho acasalavam, Jacó colocava as varas nos bebedouros diante dos olhos do rebanho, para que acasalassem diante das varas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Mas, quando os mais fracos do rebanho vinham, ele não colocava as varas na frente deles. Assim, os fracos eram de Labão e os fortes eram de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'O homem se tornou muito próspero. Ele tinha grandes rebanhos, escravas e escravos, camelos e jumentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Então, Jacó ouviu as palavras dos filhos de Labão, que diziam: \"Jacó tem levado tudo o que era do nosso pai, e é das posses de nosso pai que ele tem adquirido toda esta riqueza\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Jacó viu o olhar na face de Labão. Jacó viu que a atitude de Labão para com ele tinha mudado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Então, Yahweh disse a Jacó: \"Retorna para a terra de teus pais e de teus parentes e Eu serei contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Jacó mandou chamar Raquel e Lia para o campo, junto do seu rebanho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'e lhes disse: \"Eu vejo que a atitude de vosso pai para comigo mudou, mas o Deus de meu pai tem estado comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Vós sabeis que, com toda minha força, tenho servido a vosso pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Vosso pai tem enganado a mim e mudado meu salário dez vezes, mas Deus não tem permitido que ele faça mal a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Quando ele dizia: \'Os animais manchados serão teu salário\', então, todo o rebanho nascia manchado. E, quando ele dizia: \'Os listrados serão o teu salário,\' então, todo o rebanho nascia listrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Desse modo, Deus tem tirado o gado de teu pai e dado a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Pois, no tempo da reprodução, eu vi em um sonho os bodes que estavam acasalando no rebanho. Os bodes eram listrados, manchados e malhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'O anjo de Deus disse a mim no sonho: \'Jacó\'. Eu disse: \'Eis me aqui\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Ele disse: \'Levanta os teus olhos e vê todos os bodes que estão acasalando no rebanho. Eles são listrados, manchados e malhados, pois Eu tenho visto todas as coisas que Labão está fazendo a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Eu sou o Deus de Betel, onde tu ungiste um pilar, onde tu juraste um voto a Mim. Agora, deixa esta terra e retorna à terra de teu nascimento\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Raquel e Lia responderam e lhe disseram: \"Existe alguma porção ou herança para nós na casa de nosso pai?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Não somos nós tratadas por ele como estrangeiras? Pois ele nos tem vendido e também devorado completamente nosso dinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Pois todas as riquezas que Deus tem tirado de nosso pai agora são nossas e de nossos filhos. Agora, então, o que quer que Deus tenha te dito, faz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Então, Jacó se levantou e colocou seus filhos e suas mulheres sobre os camelos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Ele começou a conduzir todo o seu gado, e toda a sua propriedade que ele havia adquirido, incluindo o gado em sua posse, o qual ele ganhou em Padã-Arã. Então, ele partiu para estar com Isaque, seu pai, na terra de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Enquanto Labão foi tosquiar seu rebanho, Raquel roubou os deuses da casa de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Jacó também enganou Labão, o arameu, não dizendo a ele que estava partindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Então, ele fugiu com tudo o que tinha e rapidamente atravessou o rio, e se dirigiu para a região montanhosa de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'No terceiro dia, Labão foi avisado que Jacó tinha fugido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Então, tomou seus parentes com ele e perseguiu Jacó por uma jornada de sete dias. Ele o alcançou na região montanhosa de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Ora, Deus veio a Labão, o arameu, em um sonho na noite e disse-lhe: \"Tem cuidado, não fales a Jacó nem bem nem mal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Labão alcançou Jacó. Então, Jacó armou sua tenda na região montanhosa. Labão com seus parentes também acamparam na região montanhosa de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Labão disse a Jacó: \"O que fizeste, que me enganaste e levaste as minhas filhas como prisioneiras de guerra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Por que fugiste secretamente, me enganaste e não me disseste? Eu teria te despedido com celebração e com cânticos, com tamborins e com harpas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Tu não me permitiste beijar e me despedir de meus netos e minhas filhas. Ora, tu agiste tolamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Tenho poder para te fazer mal, mas o Deus de teu pai falou-me ontem à noite e disse: \'Tem cuidado, não fales a Jacó nem bem nem mal\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'E agora tu foste embora, porque desejavas retornar para a casa de teu pai. Mas, por que roubaste os meus deuses?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Jacó respondeu e disse a Labão: \"Porque eu tive medo e pensei que tomarias tuas filhas de mim à força, saí secretamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Quem quer que tenha roubado teus deuses não continuará vivo. Na presença de nossos parentes, identifica o que for teu que esteja comigo e pega\". Pois Jacó não sabia que Raquel os tinha roubado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Labão entrou na tenda de Jacó, na tenda de Lia, e na tenda das duas servas, mas ele não os achou. Ele saiu da tenda de Lia e entrou na tenda de Raquel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Ora, Raquel havia tomado os deuses da casa, colocou-os na sela de um camelo e se sentou sobre eles. Labão procurou por toda a tenda, mas não os encontrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Ela disse a seu pai: \"Não fiques irritado, meu senhor, pois eu não posso me levantar diante de ti, pois estou no período de menstruação\". Então, ele procurou, mas não encontrou os deuses de sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Jacó estava irritado e argumentou com Labão. E lhe disse: \"Qual é minha ofensa? Qual é o meu pecado para que me persigas furiosamente?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Pois tu tens vasculhado todas as minhas posses. O que achaste de todos os bens de tua casa? Deixa-os aqui diante de nossos parentes, de modo que eles possam julgar entre nós dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Por vinte anos, eu tenho estado contigo. Tuas ovelhas e tuas cabras não têm abortado, nem tenho eu comido nenhum carneiro de teu rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'O que foi despedaçado por bestas eu não trouxe a ti. Em vez disso, eu suportei esta perda. Tu sempre me fizeste pagar por todo animal que faltava, se furtado pelo dia ou furtado pela noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Lá estava eu: pelo dia, o calor me consumia e, pela noite, o orvalho congelado; e eu ficava sem dormir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Esses vinte anos eu estive em tua casa. Eu trabalhei para ti por catorze anos por tuas duas filhas e seis anos por teu rebanho. Mudaste meu salário dez vezes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Se o Deus de meu pai, o Deus de Abraão, a quem Isaque teme, não estivesse comigo, certamente agora me terias mandado embora com mãos vazias. Deus tem visto a minha aflição e como eu tenho trabalhado duro e Ele te repreendeu ontem à noite\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Labão respondeu e disse a Jacó: \"As filhas são minhas filhas, os netos são meus netos e os rebanhos são meus rebanhos. Tudo o que vês é meu. Mas o que posso eu fazer hoje a estas minhas filhas ou a seus filhos que elas deram à luz?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Então, agora, façamos um pacto, tu e eu, e deixa isto ser um testemunho entre mim e ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Então, Jacó tomou uma pedra e a colocou como um pilar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Jacó disse aos seus parentes: \"Ajuntem pedras\". Então, eles tomaram pedras e fizeram uma pilha. Eles comeram alí junto à pilha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Labão chamou isso Jegar-Saaduta, mas Jacó chamou Galeede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Labão disse: \"Esta pilha é uma testemunha entre mim e ti hoje\". Por isso, foi chamado Galeede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Também foi chamado Mizpá, porque Labão disse: \"Que Yahweh vigie entre mim e ti quando estivermos fora de vista um do outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Se maltratares as minhas filhas ou se tomares quaisquer esposas além de minhas filhas, embora ninguém mais esteja conosco, atenta, Deus é testemunha entre mim e ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Labão disse a Jacó: \"Olha esta pilha e olha este pilar, o qual ergui entre mim e ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Esta pilha é uma testemunha, e o pilar é uma testemunha de que não passarei além desta pilha até ti, e que tu não passarás além desta pilha e deste pilar até mim, para trazer prejuízo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Que o Deus de Abraão, o Deus de Naor, o Deus do pai deles, julgue entre nós\". Jacó jurou por Deus, o qual seu pai Isaque temia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Jacó ofereceu um sacrifício no monte e chamou seus parentes para comer uma refeição. Eles comeram e passaram a noite toda no monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Cedo, pela manhã, Labão se levantou, beijou seus netos e suas filhas e os abençoou. Então, Labão os deixou e retornou para casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Jacó também seguiu em seu caminho, e os anjos de Deus o encontraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Quando Jacó os viu, ele disse: \"Este é o acampamento de Deus,\" então, ele chamou o nome daquele lugar Maanaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Jacó enviou adiante de si mensageiros a Esaú seu irmão, à terra de Seir, na região de Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Deu-lhes instruções dizendo: \"Isto é o que dirás ao meu senhor Esaú: Eis o que fala o teu servo Jacó: \'Eu morei com Labão, e estive com ele até agora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Tenho bois, jumentos e rebanhos, escravos e escravas. Enviei esta mensagem a meu senhor, para que eu possa alcançar o teu favor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Os mensageiros retornaram e disseram a Jacó: \"Nós fomos ao teu irmão Esaú. Ele está a caminho para encontrar-te; quatrocentos homens estão com ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Jacó temeu e se angustiou; dividiu em dois grupos o povo que estava com ele; e também os rebanhos, as manadas e os camelos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Ele disse: \"Se Esaú atacar um grupo e o destroçar, então, o outro grupo escapará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Jacó disse: \"Deus de meu pai Abraão, e Deus de meu pai Isaque, Yahweh, que me disse: \'Retorna à tua terra natal e à tua parentela, e Eu te prosperarei\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'sou indigno de toda a Tua fidelidade e de toda a Tua misericórdia para com o Teu servo. Eu atravessei o Jordão apenas com o meu cajado, e agora volto com dois grupos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Por favor, livra-me da mão do meu irmão Esaú, pois eu temo que ele mate a mim e as mães com os filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Pois Tu disseste: \'Eu certamente te farei prosperar. Farei que a tua descendência seja numerosa como a areia do mar, a qual não se pode contar\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Jacó permaneceu alí aquela noite. E do que tinha ele separou algo para presentear Esaú, seu irmão:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'duzentas cabras e vinte bodes, duzentas ovelhas e vinte carneiros,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'trinta camelas de leite com suas crias, quarenta vacas e dez touros, vinte jumentas e dez jumentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Ele os entregou a seus servos, cada manada em separado. E disse a seus servos: \"Ide adiante de mim e deixai um espaço entre uma manada e outra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Ele instruiu o primeiro servo, dizendo: \"Quando Esaú meu irmão te encontrar e te perguntar, dizendo: \'A quem pertences? Para onde vais? E de quem são estes animais diante ti?\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'então, dirás: \'são do teu servo Jacó. É um presente enviado para meu senhor Esaú. E eis que ele mesmo chegará atrás de nós\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Jacó instruiu também ao segundo grupo, ao terceiro, e a todos os homens que seguiam as manadas. Ele disse: \"Direis a mesma coisa a Esaú quando o encontrardes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Direis também: \'Teu servo Jacó está vindo atrás de nós.\'\" Pois ele pensou: \"Eu o apaziguarei com o presente que me antecede. Depois, quando eu o encontrar, talvez me receba bem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Então, o presente foi adiante dele. Ele mesmo permaneceu aquela noite no acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Jacó se levantou durante a noite, tomou suas duas mulheres, suas duas servas e seus onze filhos. Ele os enviou a atravessar um ponto raso do Jaboque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Desta maneira, ele os fez atravessar o ribeiro com todas as suas posses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Jacó foi deixado sozinho, e um homem lutou com ele até o romper do dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Quando o homem viu que não poderia derrotá-lo, tocou a juntura da coxa de Jacó, o qual teve o quadril deslocado, quando lutou com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'O homem disse: \"Deixa-me ir, pois já subiu o alvorecer\". Jacó disse: \"Eu não te deixarei ir sem que me abençoes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'O homem disse a ele: \"Qual é o teu nome?\" Ele respondeu: \"Jacó\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'O homem disse: \"Teu nome não será mais Jacó, e sim, Israel. Pois lutaste com Deus e com homens e prevaleceste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'E Jacó perguntou: \"Por favor diga-me o teu nome\". Ele disse: \"Por que perguntas o meu nome?\". E o abençoou ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Chamou Jacó aquele lugar de Peniel pois disse: \"Eu vi Deus face a face e minha vida foi preservada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Nasceu o sol sobre Jacó, quando ele passou Peniel. Ele estava mancando por causa de seu quadril.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Por isso, até hoje, os filhos de Israel não comem os ligamentos da coxa que estão na articulação do quadril, porque o homem feriu aqueles ligamentos quando deslocou o quadril de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Jacó levantou os olhos e viu que Esaú estava vindo, e com ele quatrocentos homens. Jacó dividiu os filhos entre Lia, Raquel e as duas servas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Então, ele pôs as servas e seus filhos à frente, Lia e seus filhos atrás deles, e por último Raquel e José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Ele mesmo passou à frente deles, prostrou-se ao chão por sete vezes, até aproximar-se de seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Então, Esaú correu ao seu encontro, abraçou-o e o beijou, e eles choraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Quando Esaú levantou os olhos viu as mulheres e as crianças, e perguntou: \"Quem são essas pessoas que estão contigo?\". Jacó respondeu: \"São os filhos que Deus graciosamente deu ao teu servo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Então, as servas se aproximaram com suas crianças e se prostraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Em seguida, Lia e suas crianças se aproximaram e se prostraram. Por último, José e Raquel se aproximaram e se prostraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Então, Esaú perguntou: \"O que tu pretendes com estes grupos de servos que foram ao meu encontro?\". Jacó disse: \"Para encontrar favor aos olhos de meu senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Esaú disse: \"Eu tenho muitos bens, meu irmão; guarda o que tens para ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jacó disse: \"Não, por favor, se encontrei graça aos teus olhos, então, aceita o presente da minha mão, porque, de fato, ver a tua face é como ver a face de Deus, e tu tens me aceitado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Por favor, aceita o presente que eu trouxe; porque Deus tem me abençoado grandemente e, por causa disso, tenho o suficiente\". Jacó insistiu com ele, até que Esaú aceitou seu presente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Então, Esaú disse: \"Sigamos nosso caminho, eu irei adiante de ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Jacó lhe disse: \"Meu senhor, sabe que as crianças são muito pequenas, e que as ovelhas e vacas ainda estão amamentando suas crias; se elas forem forçadas a caminhar demais em um só dia, todos os animais morrerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Por favor, meu senhor, passa adiante do teu servo; eu seguirei mais lentamente, conforme o passo do gado que está diante de mim, e no passo das crianças, até que chegue a meu senhor em Seir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Esaú disse: \"Permite-me deixar contigo alguns dos meus homens\". Mas Jacó disse: \"Por que fazer isso? Meu senhor já tem sido generoso o suficiente para comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Então, Esaú retomou o seu caminho para Seir, naquele mesmo dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jacó viajou para Sucote, edificou uma casa para si e fez abrigos para seu gado. Por isso, o nome do lugar se chama Sucote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Quando Jacó veio de Padã-Arã, chegou salvo à cidade de Siquém, a qual está na terra de Canaã, e acampou perto da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Então, comprou um pedaço de campo dos filhos de Hamor, pai de Siquém, por cem peças de prata, e ali armou sua tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Então, levantou ali um altar e o chamou de Deus, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Então, Diná, a filha que Lia teve de Jacó, saiu para conhecer as filhas da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Siquém, filho de Hamor, o heveu, príncipe da terra, a viu, a agarrou, a tomou e a violentou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Ele se apaixonou por Diná, a filha de Jacó, e falou ternamente a ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Siquém disse a seu pai Hamor: \"Consegue-me esta mulher para que seja minha esposa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Jacó ouviu que ele corrompeu a Diná, sua filha. Seus filhos estavam no campo com os rebanhos; Jacó calou-se até eles voltarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Hamor, o pai de Siquém, saiu para falar com Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Os filhos de Jacó voltaram do campo e ouviram sobre o ocorrido. Eles ficaram furiosos, estavam indignados porque ele havia desgraçado Israel, violentando a filha de Jacó, algo que não deveria ter sido feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Hamor falou-lhes, dizendo: \"Meu filho Siquém ama vossa filha. Por favor, entregai-a a ele para que seja sua esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Fazei aliança conosco, dai-nos vossas filhas e tomai nossas filhas para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Vós vivereis conosco e a terra estará disponível para que vivais, comercializeis e adquirais propriedades\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Siquém disse ao pai e aos irmãos de Diná: \"Deixai-me encontrar favor aos vossos olhos e o que me pedirem eu vos darei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Pedi-me o que vós quereis pela noiva e eu vos darei o que me pedirem, mas dai-me a mulher para que seja minha esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Os filhos de Jacó responderam a Siquém e Hamor, seu pai, com falsidade, devido ao que Siquém havia feito com Diná, irmã deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Eles disseram: \"Nós não podemos fazer isso: dar nossa irmã a qualquer um que esteja incircunciso, isso seria uma desgraça para nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'A única condição para aceitarmos é que vos circuncideis como nós, e que cada homem do vosso povo seja circuncidado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Então, nós vos daremos as nossas filhas e tomaremos as vossas filhas para nós, assim, viveremos convosco e nos tornaremos um só povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Mas, se vós não nos ouvirdes e não vos circuncidardes, tomaremos de volta nossa irmã e partiremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Essas palavras agradaram a Hamor e a seu filho Siquém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'O jovem não tardou em fazer o que eles disseram porque ele gostava da filha de Jacó e porque ele era a pessoa mais honrada da casa de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Hamor e o filho Siquém foram ao portão de sua cidade e falaram com todos os homens, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '\"Estes homens estão em paz conosco, deixai-os viver na terra e deixai-os fazer negócios, a terra é suficientemente grande para eles. Tomemos suas filhas como esposas e entreguemos-lhes as nossas filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Esta foi a única condição com a qual os homens concordaram para viverem conosco e nos tornarmos um só povo: Se cada homem entre nós for circuncidado, assim como eles o são.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Não serão todos os seus rebanhos e suas propriedades também nossos? Vamos entrar em acordo e, então, eles viverão conosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Todos os homens da cidade ouviram Hamor e Siquém, seu filho. E cada homem foi circuncidado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'No terceiro dia, quando eles estavam ainda com dores, dois filhos de Jacó, Simeão e Levi, irmãos de Diná, tomaram suas espadas, entraram silenciosamente na cidade e mataram todos os homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Também mataram Hamor e Siquém, seu filho, ao fio da espada e tiraram Diná da casa de Siquém e foram embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Os outros filhos de Jacó foram até onde estavam os corpos e saquearam a cidade porque o povo havia desonrado a irmã deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Eles tomaram seus rebanhos, manadas, jumentos e todas as coisas que havia na cidade e nos campos ao redor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'todas as suas riquezas. Todas as crianças e suas esposas foram capturadas. Eles tomaram todas as coisas que estavam em suas casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Jacó disse a Simeão e a Levi: \"Vós causastes grandes problemas para mim, fazendo com que os habitantes desta terra, cananeus e perizeus, me odeiem. Como somos em pouco número, se eles se juntarem para me atacar, irão destruir a mim e a minha casa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Mas Simeão e Levi disseram: \"Deveria Siquém ter tratado nossa irmã como uma prostituta?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Deus disse a Jacó: \"Levanta-te, sobe a Betel e habita ali. Constrói um altar ao Deus que apareceu a ti quando fugiste de Esaú, teu irmão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Então, Jacó disse à sua família e a todos que estavam com ele: \"Lançai fora os deuses estrangeiros que estão entre vós, purificai-vos e mudai vossas roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Partamos e subamos a Betel. Eu farei ali um altar a Deus que me respondeu no dia da minha angústia e esteve comigo por onde andei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Dito isto, eles entregaram a Jacó todos os deuses estrangeiros que estavam em suas mãos e os brincos que estavam em suas orelhas. Jacó enterrou-os debaixo do carvalho que estava próximo a Siquém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Enquanto viajavam, o terror de Deus caiu sobre as cidades que estavam ao seu redor, para que aqueles povos não perseguissem os filhos de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Então, Jacó chegou em Luz (esta é Betel), que fica na terra de Canaã; ele e todo seu povo que com ele estava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Ele construi ali um altar e o chamou de El-Betel, pois ali Deus havia se revelado a ele, quando estava fugindo de seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Débora, ama de Rebeca, morreu. Ela foi enterrada em Betel, debaixo de um carvalho, que passou a ser chamado Alom-Bacute.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Quando Jacó voltou de Padã-Arã, Deus apareceu-lhe novamente e o abençoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Deus lhe disse: \"Teu nome é Jacó, porém não mais o será. Tu serás chamado Israel\". E Deus lhe deu o nome de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Deus lhe disse: \"Eu sou o Deus Todo Poderoso. Frutifica e multiplica-te. Uma nação e uma multidão de nações virão de ti e haverá reis entre teus descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'A terra que dei a Abraão e a Isaque darei a ti e também a teus descendentes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'E Deus subiu de diante dele, do lugar onde Deus falou com Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Jacó levantou uma coluna no lugar onde Deus havia lhe falado, uma coluna de pedra. Ele derramou sobre ela uma oferta de libação, e também azeite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'E Jacó deu o nome Betel ao lugar onde Deus falou com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Eles partiram de Betel. Enquanto ainda estavam a alguma distância de Efrata, Raquel entrou em trabalho de parto. Foi-lhe muito difícil dar à luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Enquanto estava nas fortes dores de parto, a parteira lhe disse: \"Não temas, pois terás outro filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Como estava morrendo, em seu último suspiro nomeou-o Benoni, entretanto seu pai lhe chamou Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Raquel morreu e foi enterrada no caminho para Efrata (que é Belém).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Jacó levantou uma coluna sobre seu túmulo. É a marca de seu túmulo até os dias de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Israel partiu e armou sua tenda além da torre de Migdal-Éder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Enquanto Israel estava vivendo naquela terra, Rúben deitou-se com Bila, concubina de seu pai e Israel ouviu a respeito. Os filhos de Jacó eram doze:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'com Lia, ele teve Rúben, o primogênito, Simeão, Levi, Judá, Issacar e Zebulom;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'com Raquel, teve José e Benjamim;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'com Bila, serva de Raquel, teve Dã e Naftali;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'com Zilpa, serva de Lia, teve Gade e Aser. Todos esses são os filhos de Jacó, os quais nasceram em Padã-Arã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Jacó foi até Isaque, seu pai, em Manre, Quiriate-Arba (a mesma que Hebrom), onde peregrinaram Abraão e Isaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Isaque viveu cento e oitenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Expirou, morreu e foi recolhido aos seus ancestrais idoso e cheio de dias. Esaú e Jacó, seus filhos, sepultaram-no.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Estes são os descendentes de Esaú, também chamado de Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Estas são as mulheres que Esaú tomou dentre as filhas de Canaã: Ada, a filha de Elom, o heteu; Aolibama, a filha de Ana, neta de Zibeão, o heveu;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'e Basemate, filha de Ismael, irmã de Nebaiote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'De Esaú, Ada teve Elifaz, e Basemate teve Reuel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Aolibama teve Jeús, Jalão e Corá. Esses são os filhos de Esaú que nasceram na terra de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Esaú levou suas mulheres, seus filhos, suas filhas, todos os membros de sua casa e seu gado, todos os seus animais e possessões, que havia adquirido na terra de Canaã, e foi para uma terra distante do seu irmão Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Ele fez isso porque suas posses eram muitas para habitarem juntos. A terra onde haviam se estabelecido não podia sustentá-los por causa dos rebanos que possuíam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Por isso, Esaú, também conhecido como Edom, estabeleceu-se na região montanhosa de Seir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Estes foram os descendentes de Esaú, o ancestral dos edomitas, habitantes na região montanhosa de Seir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'E estes eram os nomes dos filhos de Esaú: Elifaz, filho de Ada, mulher de Esaú; Reuel, filho de Basemate, mulher de Esaú.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Os filhos de Elifaz foram: Temã, Omar, Zefô, Gatã e Quenaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Timna era concubina de Elifaz, filho de Esaú, deu à luz Amaleque. Esses foram os netos de Ada, mulher de Esaú.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Estes foram os filhos de Reuel: Naate, Zerá, Samá e Mizá. Esses foram os filhos de Basemate, mulher de Esaú.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Estes foram os filhos de Aolibama, mulher de Esaú, filha de Aná, filho de Zibeão. Ela teve de Esaú Jeús, Jalão e Corá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Estas foram os chefes dos descendentes de Esaú: os descendentes de Elifaz, o primogênito de Esaú, os chefes Temã, Omar, Zefô, Quenaz,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Corá, Gatã e Amaleque. Os chefes que nasceram a Elifaz na terra de Edom; esses eram netos de Ada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Estes foram os chefes de Reuel, filho de Esaú: Naate, Zerá, Sama e Mizá. Esses foram os chefes que descenderam de Reuel na terra de Edom. Eram netos de Basemate, mulher de Esaú.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Estes foram os chefes de Aolibama, mulher de Esaú: Jeús, Jalão e Corá. Esses foram os chefes que descenderam de Aolibama, mulher de Esaú, filha de Aná.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Esses são os descendentes de Esaú, que é Edom, e seus chefes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Estes foram os filhos de Seir, o horeu, moradores daquela terra: Lotã, Sobal, Zibeão, Anás,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Disom, Eser e Disã. Esses foram os chefes dos horeus, os habitantes de Seir na terra de Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Os filhos de Lotã foram: Hori e Hemã; Timna era irmã de Lotã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Foram estes os filhos de Sobal: Alvã, Manaate, Ebal, Sefô e Onã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Estes foram os filhos de Zibeão: Aías e Aná; este é o Aná que encontrou as fontes termais no deserto, enquanto levava às pastagens os jumentos de Zibeão, seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Estes foram os filhos de Aná: Disom e Aolibama, filha de Aná.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'E estes foram os filhos de Disom: Hendã, Esbã, Itrã e Querã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Estes foram os filhos de Eser: Bilã, Zaavã e Acã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Estes são os filhos de Disã: Uz e Arã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Estes foram os chefes dos horeus: o chefe Lotã, o chefe Sobal, o chefe Zibeão, o chefe Aná,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'o chefe Disom, o chefe Eser e o chefe Disã; esses foram os chefes dos horeus, de acordo com lista dos chefes na terra de Seir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Estes foram os reis que reinaram na terra de Edom antes de qualquer um ter reinado sobre os israelitas:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Belá, filho de Beor, reinou em Edom; e o nome de sua cidade era Dinabá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Quando Belá morreu, Jobabe, filho de Zerá, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Quando Jobabe morreu, Husã, da terra dos temanitas, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Quando Husã morreu, então, Hadade, filho de Bedade, que derrotou os midianitas no campo de Moabe, reinou em seu lugar. O nome de sua cidade era Avite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Quando Hadade morreu, Sâmela de Masreca reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Sâmela morreu, e, então, Saul de Reobote, junto ao rio, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Quando Saul morreu, Baal-Hanã, filho de Acbor, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Quando Baal-Hanã morreu, Hadar reinou em seu lugar. O nome da sua cidade era Paú; e sua mulher era Meetabel, filha de Matrede, neta de Mezaabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Estes foram os nomes dos chefes dos descendentes de Esaú, de acordo com suas tribos e regiões, por seus nomes: Timna, Alva, Jetete,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Aolibama, Elá, Pinom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Quenaz, Temã, Mibzar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Magdiel e Irão. Esses foram os chefes das tribos de Edom, de acordo com suas habitações, na terra que tinham possuído. Esse foi Esaú, o pai dos edomitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jacó habitou na terra onde seu pai tinha vivido, na terra de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Estes foram os eventos relacionados a Jacó. José, que era um jovem de dezessete anos de idade, estava cuidando do rebanho com seus irmãos. Ele estava com os filhos de Bila e os filhos de Zilpa, esposas de seu pai. José trouxe ao seu pai uma notícia desfavorável sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'E Israel amava José mais que todos os seus filhos, pois ele era o filho de sua velhice. Ele fez uma bela túnica para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Seus irmãos viram que seu pai o amava mais que a todos eles. Odiaram-no e não falavam cordialmente com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'José teve um sonho e o relatou aos seus irmãos. Eles o odiaram ainda mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Ele lhes disse: \"Por favor, escutai este sonho que tive.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Eis que estávamos amarrando fardos de grãos no campo e meu fardo se levantou e ficou em pé e seus fardos rodearam e se curvaram ao meu fardo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Seus irmãos disseram-lhe: \"Reinarás mesmo sobre nós? Governarás, de fato, sobre nós?\". Eles odiaram-no ainda mais por seus sonhos e suas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Ele teve outro sonho e o contou aos seus irmãos. Ele disse: \"Eis que tive outro sonho: o sol e a lua e onze estrelas se curvavam diante de mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Ele o contou ao seu pai, assim como aos seus irmãos e seu pai o repreendeu. Disse-lhe: \"O que é este sonho que tiveste? Eu, tua mãe e teus irmãos iremos, de fato, curvar-nos ao chão perante ti?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Seus irmãos estavam com ciúmes dele, mas seu pai manteve a questão em mente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Seus irmãos foram cuidar do rebanho de seu pai em Siquém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Israel disse a José: \"Teus irmãos não estão cuidando do rebanho em Siquém? Vem e te enviarei a eles\". José lhe disse: \"Estou pronto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Ele lhe disse: \"Vai agora, verifica se teus irmãos e o rebanho estão bem e traze-me notícias\". Então, Jacó enviou-lhe para fora do vale de Hebrom e José foi a Siquém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Um certo homem encontrou José e eis que ele estava perdido em um campo. O homem perguntou-lhe: \"O que procuras?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'José disse: \"Estou procurando meus irmãos. Dize-me, por favor, onde eles estão cuidando do rebanho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'O homem disse: \"Eles deixaram este lugar, pois ouvi-os dizer: \'Vamos para Dotã\'\". José foi atrás dos seus irmãos e os encontrou em Dotã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Eles o viram de longe e, antes que ele se aproximasse, conspiraram contra ele para matá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Seus irmãos disseram uns aos outros: \"Eis que o sonhador se aproxima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Vamos, agora, matá-lo e jogá-lo dentro de uma destas cisternas. E diremos: \'Um animal selvagem o devorou\'. Veremos o que será de seus sonhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Rúben ouviu isso, livrou-o de suas mãos e disse: \"Não vamos tirar a sua vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Rúben disse a eles: \"Não derrameis sangue. Jogai-o nesta cova no deserto, todavia não ponhais a mão nele\". Ele planejava resgatar José de suas mãos para fazê-lo retornar ao seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Aconteceu que, quando José chegou a seus irmãos, eles o despiram de sua bela túnica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Pegaram-no e o jogaram na cisterna, que estava vazia e sem água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Eles se sentaram para comer pão. Levantaram seus olhos e eis que viram uma caravana de ismaelitas vindo de Gileade, com seus camelos, carregando especiarias, bálsamo e mirra, que eles levavam para o Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Disse Judá aos seus irmãos: \"Que lucro teremos se matarmos nosso irmão e encobrirmos seu sangue?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Vinde, vamos vendê-lo aos ismaelitas e não coloquemos nossas mãos sobre ele, pois ele é nosso irmão, nossa carne\". Seus irmãos o escutaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Quando os mercadores midianitas passaram, seus irmãos ergueram José, fazendo-o sair da cisterna e o venderam por vinte siclos de prata aos ismaelitas. Os ismaelitas levaram José ao Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Quando Rúben retornou à cisterna, eis que José não estava lá. Ele rasgou suas roupas');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'e, voltando aos seus irmãos, disse: \"O rapaz não está lá. E eu, para onde irei?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Então, eles pegaram a túnica de José, mataram um cabrito e mergulharam a túnica no sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Depois a levaram ao seu pai e disseram: \"Encontramos isto. Por favor, vê se é a túnica do teu filho ou não\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Jacó reconheceu a veste e disse: \"É do meu filho. Um animal selvagem o devorou. José certamente foi despedaçado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Jacó rasgou suas roupas e colocou uma roupa de saco sobre seu quadril. E sofreu luto por seu filho por muitos dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Todos os seus filhos e filhas se levantaram para confortá-lo, mas ele se recusou ser consolado, dizendo: \"De fato, irei ao sheol lamentando por meu filho\". Seu pai chorou por ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'E os midianitas o venderam a Potifar no Egito, um oficial do Faraó, capitão da guarda real.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Naquele tempo, Judá deixou seus irmãos e permaneceu com um homem de Adulão, cujo nome era Hira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Ali, ele encontrou a filha de um cananeu, cujo nome era Suá. Ele a tomou por mulher e se deitou com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Ela engravidou, teve um filho e deram-lhe o nome de Er. Ela engravidou novamente e deu à luz um filho e');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'o chamou Onã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Novamente, teve um filho e o chamou Selá. Foi em Quezibe que ela o deu à luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Judá encontrou uma esposa para o seu primogênito Er, cujo nome era Tamar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Er, o primogênito de Judá, era mau aos olhos de Yahweh e Yahweh o matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Judá disse a Onã: \"Deita-te com a esposa do teu irmão, cumpre teu papel de cunhado para com ela e dá um filho para teu irmão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Onã sabia que a criança não seria dele. Sempre que se deitava com a esposa do seu irmão, derramava o sêmen no chão para que não desse um filho para seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'O que ele fazia era mau aos olhos de Yahweh e Yahweh também o matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Então, Judá disse a Tamar, sua nora: \"Permanece como viúva na casa de teu pai até que Selá, meu filho, cresça\". Pois temeu: \"Ele pode moorrer, assim como seus irmãos\". Tamar partiu e viveu na casa de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Após um longo tempo, a filha de Suá, esposa de Judá, faleceu. Judá foi confortado e subiu aos tosqueadores de suas ovelhas em Timnate, ele e seu amigo Hira, o adulamita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Disseram a Tamar: \"Eis que teu sogro está indo a Timnate tosquiar suas ovelhas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Ela tirou suas vestes de viúva, cobriu-se e envolveu-se com seu véu. Ela se sentou no portão de Enaim, próximo à estrada para Timnate. Viu que Selá havia crescido, mas ela não havia sido dada a ele como esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Quando Judá a viu, pensou que era uma prostituta, por estar com o rosto coberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Ele foi até ela na estrada e disse: \"Vem, por favor, deixa-me deitar contigo\", pois ele não sabia que ela era sua nora; ela disse: \"O que me darás para que deites comigo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Ele disse: \"Enviar-te-ei um cabrito do rebanho\". Ela disse: \"Tu me darás garantia até que o envies a mim?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Ele disse: \"Que garantia posso dar-te?\". E ela disse: \"Teu selo, teu cordão e o cajado que está em tua mão\". Ele os deu a ela, deitou-se com ela e ela engravidou dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Ela se levantou e partiu. Tirou seu véu e vestiu as vestes de sua viuvez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Judá enviou o cabrito do rebanho com seu amigo adulamita para receber a garantia das mãos da mulher, mas ele não a encontrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Então, o adulamita perguntou aos homens do local: \"Onde está a prostituta do templo que estava na estrada de Enaim?\". Eles disseram: \"Não havia prostituta do templo aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Ele retornou a Judá e disse: \"Não a encontrei. Também os homens do local disseram: \'Não havia prostituta do templo aqui\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Judá disse: \"Deixa que ela fique com os itens para que não sejamos razão de vergonha. De fato, enviei este cabrito, mas não a encontraste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Aconteceu que, após três meses, foi dito a Judá: \"Tamar, tua nora, prostituiu-se e está grávida\". Judá disse: \"Traze-a aqui e deixa-a ser queimada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Quando ela foi trazida, enviou ao seu sogro uma mensagem: \"Estou grávida do homem que é dono destas coisas\". Ela disse mais: \"Reconhece, por favor, a quem pertencem estes: o selo, o cordão e o cajado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Judá reconheceu os itens e disse: \"Ela é mais justa do que eu, visto que não a dei como esposa a Selá, meu filho\". Ele não se deitou com ela novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Sucedeu que, chegada a hora de ela dar à luz, eis que gêmeos estavam em seu ventre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Quando ela estava parindo, um bebê colocou uma mão para fora e a parteira pegou um fio escarlate e amarrou-o em sua mão e disse: \"Este veio primeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Todavia ele recolheu sua mão de volta e eis que seu irmão saiu primeiro. A parteira disse: \"Como quebraste a ordem!\". E ele foi chamado Perez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Então, seu irmão saiu, o que tinha um fio escarlate em sua mão, e ele foi chamado Zerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'José foi levado ao Egito. Potifar, um oficial de Faraó que era capitão da guarda e egípcio, comprou-o dos ismaelitas que o haviam levado para lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Yahweh estava com José e este se tornou próspero. José, então, passou a morar com seu senhor egípcio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Seu senhor viu que Yahweh estava com ele e que Yahweh prosperava tudo que ele fazia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'José encontrou favor diante dos olhos de seu senhor, a quem servia. Potifar o fez administrador de sua casa, e colocou sob seus cuidados tudo que possuía.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Desde que o colocou como administrador de sua casa e de tudo o que possuía, Yahweh abençoou o lar do egípcio por causa de José. A bênção de Yahweh estava em todas as coisas que Potifar tinha em sua casa e em seu campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Potifar pôs tudo sobre os cuidados de José. Ele não tinha que pensar sobre nada exceto sobre a comida que comia. José era formoso de porte e de aparência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'E aconteceu que, depois disso, a mulher de seu senhor desejou José. Ela disse: \"Deita-te comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Mas ele recusou e disse para ela: \"Escuta: meu senhor não precisa se preocupar sobre o que eu faço na casa. Ele pôs tudo sob meus cuidados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Ninguém é superior a mim nesta casa. Ele não vedou nada a mim, a não ser a ti, porque tu és a mulher dele. Como poderia eu cometer este grande mal e pecar perante Deus?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Ela falou com José dia após dia, mas ele se recusava a dormir ou estar com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Mas, certo dia, ele chegou à casa onde trabalhava e nenhum dos que ali trabalhavam estavam lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Ela o pegou pelas roupas e disse: \"Deita-te comigo\". Ele, porém, deixando suas roupas nas mãos dela, escapou e fugiu para fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Quando ela viu que ele tinha deixado suas roupas em suas mãos e fugiu para fora,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'chamou um dos homens da casa e disse para ele: \"Vede, Potifar trouxe um hebreu para nos insultar. Ele veio para deitar-se comigo e eu gritei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Quando me escutou gritando, deixou suas roupas comigo, fugiu e foi para fora\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Ela deixou a roupa dele perto de si até que o seu senhor chegou em casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'E deu para ele essa explicação: \"O servo hebreu que nos trouxeste veio para me insultar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Quando eu gritei, ele deixou suas roupas comigo e fugiu para fora\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Então, quando o seu senhor ouviu a explicação da mulher: \"Foi isso o que seu servo fez comigo\", Potifar ficou muito bravo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'O senhor de José o pegou e o colocou na prisão, um lugar onde ficavam confinados os prisioneiros do rei. Ele ficou na prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Mas Yahweh estava com José e era fiel a ele e o favoreceu aos olhos do carcereiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'O carcereiro confiou os prisioneiros a José para que cuidasse deles. Qualquer coisa que acontecesse, José estava encarregado disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'O carcereiro não se preocupava com nada que estava sob seus cuidados porque Yahweh estava com José. Qualquer coisa que fizesse, Yahweh o prosperava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Sucedeu, depois dessas coisas, que o copeiro e o padeiro do rei do Egito ofenderam seu mestre, rei do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Faraó indignou-se com seus dois oficiais, o copeiro chefe e o padeiro chefe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Ele os colocou em custódia na prisão do capitão da guarda, na mesma prisão onde José estava preso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'O capitão da guarda colocou José a cargo deles para que os servisse. Eles permaneceram sob custódia por algum tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Ambos sonharam um sonho — o copeiro e o padeiro do rei do Egito os quais estavam na prisão — cada homem sonhou seu próprio sonho, na mesma noite, e cada sonho teve sua própria interpretação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Quando José foi até eles pela manhã, observou que eles estavam tristes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Ele perguntou aos oficiais de Faraó que estavam com ele na prisão: \"Por que estais com o semblante tão triste hoje?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Eles responderam: \"Nós tivemos um sonho e ninguém consegue interpretá-lo\". José disse para eles: \"Não pertencem a Deus as interpretações? Contai-me por favor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'O copeiro chefe contou seu sonho a José dizendo: \"No meu sonho, contemplava uma videira na minha frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Na videira, havia três ramos. Enquanto ela estava brotando, suas flores saíram e seus cachos davam uvas maduras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'A taça de Faraó estava na minha mão. Eu peguei as uvas e as expremi na taça de Faraó e coloquei a taça em suas mãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'José disse a ele: esta é a interpretação desse sonho: \"Os três ramos são três dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Dentro de três dias, Faraó erguerá sua cabeça e te mudará de posição, restaurando-te como oficial dele. Tu servirás a taça de Faraó nas mãos dele, como quando eras seu copeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Mas lembra-te de mim quando estiver tudo bem contigo; peço-te que tenhas compaixão, falando de mim a Faraó e tira-me desta prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'De fato, eu fui sequestrado da terra dos hebreus. Aqui também não fiz nada para que me colocassem nesta prisão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Quando o padeiro chefe viu que a interpretação era favorável, ele disse a José: \"Eu também tive um sonho, e contemplei três cestas de pão na minha cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Na cesta do topo, havia todos os tipos de assados para Faraó, mas os pássaros comeram da cesta que estava na minha cabeça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'José respondeu e disse: \"Esta é a interpretação: as três cestas são três dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Dentro de três dias, Faraó erguerá a tua cabeça e serás enforcado em uma árvore e as aves comerão a tua carne\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'No terceiro dia, era o aniversário do Faraó. Ele deu um banquete para todos os seus servos. Ele \"levantou\" a cabeça do copeiro-mor e a cabeça do padeiro-mor entre seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Ele reabilitou o copeiro-mor para a sua responsabilidade e este colocou a taça na mão de Faraó novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Mas ele enforcou o padeiro-mor, assim como José havia interpretado para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Mas o copeiro-mor não se lembrou de José; ele o esqueceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Passados dois anos inteiros, Faraó teve um sonho. Eis que ele estava em pé junto ao Nilo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'De repente, sete vacas subiram do Nilo, desejáveis e gordas, e pastavam nos juncos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Logo, depois delas, sete outras vacas subiram do rio, indesejáveis e magras. Elas pararam junto às outras vacas à beira do rio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Então, as vacas indesejáveis e magras comeram as sete vacas desejáveis e gordas. Então, Faraó acordou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Depois, ele voltou a dormir e sonhou uma segunda vez. De repente, sete espigas de grão brotaram de um mesmo caule, saudáveis e boas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Eis que, depois delas, brotaram sete espigas, magras e queimadas pelo vento leste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'As espigas magras engoliram as setes espigas saudáveis. Faraó acordou, e eis que tinha sido um sonho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Aconteceu que, na manhã seguinte, seu espírito estava perturbado. Ele mandou chamar todos os mágicos e sábios do Egito. Faraó contou-lhes seus sonhos, mas ninguém conseguiu interpretá-los para Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Então, o chefe dos copeiros disse a Faraó: \"Hoje estou pensando em minhas ofensas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Faraó estava irritado com seus servos, e me pôs sobre custódia na casa do capitão da guarda, a mim e ao chefe dos padeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Nós tivemos um sonho na mesma noite, ele e eu. Sonhamos cada um o seu sonho, cada sonho com a sua interpretação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Estava conosco um jovem hebreu, servo do capitão da guarda. Contamos a ele nossos sonhos, e ele os interpretou. Ele interpretou para cada um de nós conforme o seu sonho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'E aconteceu conforme ele nos havia interpretado. Faraó me restaurou ao meu cargo, porém, ele enforcou o outro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Então, Faraó mandou chamar José. Rapidamente, tiraram-no da masmorra. Ele se barbeou, trocou de roupa e foi até Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Faraó disse para José: \"Eu tive um sonho, mas não há quem o interprete. Porém, ouvi dizer a teu respeito que, quando ouves um sonho, consegues interpretá-lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'José respondeu a Faraó, dizendo: \"Não sou eu, mas Deus responderá com favor a Faraó\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Faraó falou a José: \"Em meu sonho, eis que eu estava em pé, à beira do Nilo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'De repente, sete vacas subiram do Nilo gordas e desejáveis, e pastavam entre os juncos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Logo, depois delas, outras sete vacas subiram, uma após outra, fracas, muito indesejáveis e magras. Nunca vi em toda a terra do Egito coisas tão indesejáveis quanto essas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'As vacas magras e indesejáveis devoraram as sete primeiras vacas gordas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Quando as devoraram, não se podia saber que elas as haviam comido, pois permaneciam tão indesejáveis como antes. Então, eu acordei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Eu vi em meu sonho, e eis que sete espigas subiram, de um mesmo caule, cheias e boas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Eis que surgiram outras sete espigas murchas, magras e queimadas pelo vento leste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'As espigas magras engoliram as sete espigas boas. Eu contei estes sonhos aos mágicos, mas não houve quem o interpretasse para mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'José disse a Faraó: \"Os sonhos de Faraó são a mesma coisa. O que Deus está por fazer Ele declarou a Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'As setes vacas boas são sete anos, e as sete espigas boas são sete anos. Os sonhos são a mesma coisa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'As sete vacas magras e indesejáveis que subiram depois são sete anos, e também as sete espigas magras e queimadas pelo vento leste serão sete anos de fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Isso foi o que eu disse a Faraó. O que Deus está por fazer Ele revelou a Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Vê: sete anos de grande fartura virão em toda a terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Depois deles, virão sete anos de fome, e toda a fartura será esquecida na terra do Egito, e a fome devastará a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'A fartura não será lembrada na terra devido à fome que virá em seguida, pois será muito severa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Quanto ao sonho de Faraó ter se repetido, é porque isso foi estabelecido por Deus, e Deus o fará em breve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Ora, que Faraó encontre um homem entendido e sábio, e coloque-o sobre a terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Que Faraó nomeie supervisores sobre a terra, e que eles tomem a quinta parte dos produtos do Egito nos sete anos de fartura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Que ajuntem todos os mantimentos desses bons anos que estão chegando e armazenem o cereal sob a autoridade de Faraó, para alimento a ser usado nas cidades. Que eles o preservem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'O alimento será um suprimento para a terra durante os sete anos de fome que haverá na terra do Egito. Dessa forma, a terra não será devastada pela fome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Esse conselho foi bom aos olhos de Faraó e aos olhos de todos os seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Faraó disse aos seus servos: \"Podemos encontrar um homem como este, em quem o Espírito de Deus habita?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Então, Faraó disse a José: \"Visto que Deus lhe mostrou tudo isso, ninguém é tão entendido e sábio como tu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Tu estarás sobre a minha casa; segundo a tua palavra, todo o meu povo será governado. Somente no trono eu serei maior que tu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Faraó disse a José: \"Vê, eu te ponho sobre toda a terra do Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Faraó tirou o anel de selar de sua mão e colocou-o na mão de José. Ele o vestiu com roupas de linho fino e colocou uma corrente de ouro no pescoço dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Ele o fez subir à segunda carruagem que possuía. Homens gritaram perante ele: \"Dobrai o joelho\". Faraó o pôs sobre toda a terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Faraó disse a José: \"Eu sou Faraó e, sem a tua permissão, nenhum homem levantará a mão ou pé em toda a terra do Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Faraó chamou José pelo nome de Zafenate-Paneia. Deu-lhe Asenate por esposa, que era filha de Potífera, sacerdote de Om. José percorreu a terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'José tinha trinta anos de idade quando ele se apresentou perante Faraó, rei do Egito. José saiu da presença de Faraó e percorreu toda a terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Nos sete anos de fartura, a terra produziu abundantemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Ele ajuntou todo o mantimento produzido nos sete anos, na terra do Egito, e colocou o mantimento nas cidades. Ele pôs, em cada cidade, o mantimento dos campos ao redor dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'José armazenou cereais como a areia do mar, tanto que parou de contar porque foi além da conta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'José teve dois filhos com Asenate, filha de Potífera, sacerdote de Om, antes dos anos de fome chegarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'José chamou seu primogênito de Manassés, pois disse: \"Deus me fez esquecer de todos os meus problemas e de toda a casa do meu pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Ele chamou seu segundo filho de Efraim, pois disse: \"Deus me fez frutífero na terra da minha aflição\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Os sete anos de fartura que houve na terra do Egito chegaram ao fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Os sete anos de fome começaram, como José tinha dito. Havia fome em todas as terras, porém em toda a terra do Egito havia alimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Quando toda a terra do Egito teve fome, o povo clamou em alta voz a Faraó por comida. Faraó disse aos egípicios: \"Ide a José e fazei o que ele disser\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'A fome estava sobre toda a face da terra. José abriu todos os celeiros e vendeu aos egípicios. A fome estava severa na terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Toda a terra vinha ao Egito para comprar cereal de José, porque a fome era severa em toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Ora, Jacó soube que havia cereal no Egito. Ele disse aos seus filhos: \"Por que olhais uns para os outros?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Ele disse: \"Vede, eu ouvi dizer que no Egito existe cereal. Desçei até lá e comprai para nós, para que vivamos e não morramos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Os dez irmãos de José desceram para comprar cereal do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mas Benjamim, irmão de José, Jacó não o mandou com seus irmãos, pois temia que algum mal lhe acontecesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Os filhos de Israel chegaram para comprar juntamente com outras pessoas que vinham, porque a fome estava presente na terra de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Agora, José era o governador da terra. Era ele quem vendia para todo o povo da terra. Os irmãos de José vieram e se curvaram diante dele, baixando seus rostos para o chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'José viu seus irmãos e os reconheceu, mas ele se disfarçou e falou asperamente com eles, dizendo-lhes \"De onde viestes?\". Eles disseram: \"Da terra de Canaã, para comprar comida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'José reconheceu os seus irmãos, porém eles não o reconheceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Então, José se lembrou dos sonhos que tivera sobre eles, e lhes disse: \"Vós sois espiões! Viestes ver as partes indefesas da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Eles lhe disseram: \"Não, senhor meu. Teus servos vieram comprar comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Nós somos filhos de um único homem. Somos homens honestos. Teus servos não são espiões\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Ele lhes disse: \"Não, mas viestes ver as partes indefesas da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Eles disseram: \"Nós, teus servos, somos doze irmãos, filhos de um único homem da terra de Canaã. O mais novo está com nosso pai, e um irmão não vive mais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'José disse-lhes: \"É como eu vos disse: vós sois espiões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Por isso, sereis testados. Pela vida do Faraó, vós não saireis daqui, a menos que teu irmão mais novo venha aqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Enviai um de vós para buscar teu irmão. Ficareis na prisão, para que vossas palavras sejam testadas, se há verdade em vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Ele os pôs na prisão por três dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'José disse-lhes no terceiro dia: \"Fazei isso e vivei, pois eu temo a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Se sois homens honestos, deixai um dos vossos irmãos ficar confinado nessa prisão, mas vós ireis levar cereal por causa da fome de vossas casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Trazei vosso irmão mais novo a mim, para que as vossas palavras sejam confirmadas e não morrereis\". Então, eles o fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Eles disseram uns ao outros: \"Nós somos verdadeiramente culpados em relação ao nosso irmão, porque vimos a aflição de sua alma, quando ele suplicava conosco e não o ouvimos. Por isso, esta angústia veio sobre nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Rúben respondeu-lhes: \"Eu não vos disse: \'não pequeis contra o menino\', mas vós não me ouvistes? Agora vede: o sangue dele é cobrado de nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Eles não sabiam que José os entendia, porque havia um intérprete entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Ele se afastou e chorou. José voltou e falou com eles. Ele tomou Simeão deles e o amarrou diante dos seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Então, José ordenou seus servos que enchessem com cereal as bagagens dos seus irmãos, colocassem de volta o dinheiro de cada um em seus sacos e lhes dessem provisão para a jornada. E isso lhes foi feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Os irmãos carregaram seus jumentos com seu cereal e partiram dali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Quando um deles abriu o seu saco de cereal para dar comida ao seu jumento em um alojamento, ele viu seu dinheiro. Eis que ele estava na boca do saco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Ele disse para seus irmãos: \"Meu dinheiro foi posto de volta. Vede-o aqui na boca do saco de cereal\". Seus corações desfaleceram e, tremendo, viraram-se uns para os outros, dizendo: \"O que é isto que Deus fez conosco?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Eles foram a Jacó, seu pai, na terra de Canaã, e lhe contaram o que lhes acontecera. Eles disseram:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '\"O homem, o senhor da terra, falou duramente conosco e pensou que nós fôssemos espiões da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Nós dissemos para ele: \'Somos homens honestos. Não somos espiões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Somos doze irmãos, filhos do nosso pai. Um não vive mais e o mais novo está hoje com nosso pai na terra de Canaã\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'O homem, o senhor da terra, disse-nos: \'Com isso, eu saberei que sois homens honestos. Esteja um de vossos irmãos comigo, levai cereal por causa da fome em vossas casas, e ide por vosso caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Trazei vosso irmão mais novo para mim. Então, eu saberei que vós não sois espiões, mas que sois homens honestos. Então, soltarei vosso irmão pra vós, e podereis negociar na terra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Aconteceu que, quando esvaziaram suas bagagens, eis que cada um dos homens estava com sua bolsa de dinheiro no saco de cereal. Quando eles e seu pai viram suas bolsas de dinheiro, ficaram com medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Jacó, seu pai, disse-lhes: \"Estais me tirando meus filhos. José não está mais vivo, Simeão se foi, e quereis levar Benjamim. Todas essas coisas estão contra mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Rúben falou para seu pai: \"Podes matar meus dois filhos se eu não trouxer Benjamim de volta para ti. Coloca-o em minhas mãos, e eu o trarei para ti de novo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Jacó disse: \"Meu filho não descerá convosco. Pois seu irmão está morto e somente ele restou. Se lhe acontecer algum mal no caminho por onde forem, fareis meus cabelos brancos descerem com tristeza ao Sheol\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'A fome era severa na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Tendo eles acabado de comer o mantimento que trouxeram do Egito, disse-lhes seu pai: \"Voltai e comprai para nós algum alimento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Judá respondeu-lhe: \"O homem fortemente nos advertiu: \'Não vereis a minha face, a menos que o vosso irmão esteja convosco\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Se enviares conosco nosso irmão, voltaremos e compraremos alimento para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Mas, se não o enviares, não voltaremos. Porque o homem nos disse: \'Não vereis a minha face, a menos que o vosso irmão esteja convosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Israel disse: \"Por que me fizeste este mal, dizendo ao homem que tínheis outro irmão?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Eles responderam: \"O homem perguntou detalhes sobre nós e nossa família. Ele disse: \'O vosso pai ainda vive? Tendes outro irmão?\'. Respondemos conforme essas perguntas. Como podíamos saber que ele diria: \'Trazei o vosso irmão?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Judá disse para Israel, seu pai: \"Envia o rapaz comigo. Nós nos levantaremos e iremos para que vivamos e não morramos, tanto nós, como tu, e também os vossos filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Eu serei a garantia por ele e tu me terás por responsável. Se eu não o trouxer de volta e o apresentar perante ti, então, serei culpado para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Pois, se não tivéssemos demorado, certamente já teríamos voltado aqui pela segunda vez\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Seu pai, Israel, disse-lhes: \"Se tem que ser assim, fazei isto. Peguem alguns dos melhores produtos da terra e coloquem em vossas bagagens. Levem para o homem um presente: um pouco de bálsamo e de mel, essências aromáticas e mirra, nozes de pistache e amêndoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Levai em vossas mãos dinheiro em dobro. Levai de volta o dinheiro que foi devolvido na abertura de vossas bagagens. Talvez tenha havido algum engano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Levai também o vosso irmão. Levantai-vos e ide para o homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Que Deus Todo Poderoso conceda Sua misericórdia perante o homem, para que ele liberte o vosso outro irmão e Benjamim. Se me forem tirados os filhos, sem filhos ficarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Os homens pegaram aquele presente e levaram em mãos o dobro de dinheiro, junto com Benjamim. Eles se levantaram, foram para o Egito, e se apresentaram diante de José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Quando José viu Benjamim com eles, disse ao administrador da sua casa: \"Leva os homens para dentro de casa, abate um animal e prepara-o, para que eles comam comigo, ao meio-dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'O administrador fez como José dissera. Ele trouxe os homens para a casa de José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Os homens estavam com medo porque foram trazidos para a casa de José. Eles disseram: \"Isso é por causa do dinheiro que foi posto de volta em nossas bagagens na primeira vez que fomos trazidos, porque o homem está buscando uma oportunidade contra nós. Ele pode nos prender e nos tomar como escravos, e levar nossos jumentos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Eles se aproximaram do administrador da casa de José, e falaram com ele à porta da casa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'dizendo: \"Ouve, senhor, nós viemos pela primeira vez para comprar comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Aconteceu que, quando chegamos ao alojamento, abrimos nossas bagagens, e eis que o valor total do dinheiro de cada um estava na abertura de sua bagagem. Nós o trouxemos de volta em nossas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Também trouxemos mais dinheiro em nossas mãos para comprar alimento. Não sabemos quem colocou nosso dinheiro em nossas bagagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'O administrador disse: \"Paz seja convosco, não temais. O vosso Deus e o Deus do vosso pai deve ter colocado o dinheiro em vossas bagagens. Eu recebi o vosso dinheiro\". Então, o administrador trouxe-lhes Simeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'O administrador trouxe os homens para dentro da casa de José. Ele lhes deu água, e eles lavaram seus pés. Ele deu comida aos seus jumentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Eles prepararam os presentes para quando José viesse ao meio-dia, pois tinham ouvido que comeriam ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Quando José chegou, eles trouxeram os presentes que estavam em suas mãos para dentro da casa, e prostraram-se diante dele, ao chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Ele lhes perguntou sobre como estavam e disse: \"O vosso pai, o velho homem de quem falais, está bem? Ele ainda está vivo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Eles disseram: \"Teu servo, nosso pai, está bem. Ele ainda está vivo\". E se prostraram e se inclinaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Quando levantou seus olhos, ele viu Benjamim, seu irmão, filho de sua mãe, e disse: \"Este é o vosso irmão mais novo de quem falastes?\". Então, disse: \"Que Deus seja gracioso convosco, meu filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'José apressou-se para sair da sala, pois ele estava profundamente comovido por causa do seu irmão. Ele buscou um lugar para chorar, foi para seu quarto e ali chorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Ele lavou o seu rosto e voltou. Ele se controlou, dizendo: \"Servi a comida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Os servos serviram a José à parte, e aos seus irmãos separadamente. E os egípcios que ali estavam comeram à parte, porque os egípicios não podiam comer com os hebreus, pois isso era detestável para os egípcios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Os irmãos sentaram perante ele e foram colocados desde o primogênito até o mais novo, por ordem de idade. Eles estavam juntamente surpreendidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'José deu-lhes porções da comida que estava diante dele. Mas a porção de Benjamin era cinco vezes maior do que a de qualquer dos seus irmãos. Eles beberam e se alegraram com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'José ordenou ao mordomo de sua casa, dizendo: \"Enche as bagagens dos homens com alimento, tanto quanto conseguirem levar, e põe o dinheiro de cada homem na boca do alforje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Põe minha taça, a taça de prata, na boca do alforje do mais novo, assim como o dinheiro do seu cereal\". O mordomo fez como José havia dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Logo de manhã, os homens foram despedidos com os seus jumentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Quando eles já haviam saído da cidade, mas não estavam muito distantes, José disse ao seu mordomo: \"Levanta-te, segue os homens, e quando os alcançares, dize-lhes: \'Por que pagastes o bem com o mal?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Essa não é a taça na qual meu senhor bebe, e que ele usa para adivinhar? Fizestes mal, isso o que fizestes.\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'O mordomo os alcançou e repetiu-lhes essas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Eles lhe disseram: \"Porque meu mestre fala tais palavras? Longe de vossos servos fazerem semelhante coisa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Vê, o dinheiro que achamos na boca de nossas bagagens, trouxemos de volta para ti da terra de Canaã. Como, então, poderíamos roubar da casa do vosso mestre ouro ou prata?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, '\"Aquele dentre vossos servos com quem a taça for encontrada, morra, e nós também seremos escravos do meu senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'O mordomo disse: \"Ora, seja conforme as vossas palavras. Aquele com quem a taça for encontrada será meu escravo, e vós outros sereis inocentes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Então, cada homem apressou-se e colocou o seu saco no chão, e cada um abriu seu saco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'O mordomo buscou, começando pelo mais velho e terminou pelo mais novo, e a taça foi achada no saco de Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Então, eles rasgaram suas roupas. Cada homem carregou seu jumento e retornaram à cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Judá chegou com seus irmãos à casa de José. Ele ainda estava lá, e prostraram-se em terra diante dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'José perguntou-lhes: \"O que vós fizestes? Não sabeis que um homem como eu pode adivinhar?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Judá disse: \"Que diremos ao meu senhor? Que falaremos? Ou como nos justificaremos? Deus descobriu a iniquidade de teus servos. Vê, seremos escravos de meu senhor, tanto nós como aquele na mão de quem a taça foi achada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'José disse: \"Longe de mim fazer isto. O homem na mão de quem foi achada a taça, este será meu escravo, mas, quanto a vós outros, subi em paz ao vosso pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Então, Judá aproximou-se dele e disse: \"Meu senhor, por favor deixe teu servo falar uma palavra aos ouvidos do meu senhor, e que a tua ira não se acenda contra teu servo, porque tu és como Faraó\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Meu senhor perguntou a seus servos, dizendo: \'Tendes pai ou irmão?\';');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'E respondemos a meu senhor: \'Temos um pai, um velho homem, e um filho de sua velhice, um pequenino. Porém, seu irmão está morto, e ele é o único que restou de sua mãe, e seu pai o ama\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Então, tu disseste a teus servos: \'Trazei-o a mim, para que eu o veja\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Depois disso, dissemos ao meu mestre: \'O jovem não pode deixar seu pai, pois seu pai morreria se ele o deixasse\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Então, tu respondeste a teus servos: \'A menos que vosso irmão mais novo desça convosco, nunca mais vereis de novo a minha face\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'E sucedeu que, quando nós subimos para teu servo, meu pai, falamos a ele tuas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Nosso pai disse: \'Ide novamente e comprai algum alimento\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Então, dissemos: \'Não podemos descer. Se nosso irmão mais novo estiver conosco, então, desceremos, pois não teremos permissão de ver a face do homem a menos que nosso irmão mais novo esteja conosco\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Teu servo, meu pai, disse-nos: \'Vós sabeis que minha mulher me deu dois filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Um saiu de perto de mim, e eu disse: \"Certamente ele foi despedaçado, e nunca mais o vi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Ora, se também tirardes este de mim, e algum desastre lhe acontecer, fareis os meus cabelos brancos descerem com tristeza ao Sheol\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Ora, portanto, quando eu voltar para o teu servo, meu pai, e o jovem não estiver conosco, visto que sua alma está ligada à alma do garoto,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'acontecerá que, quando ele vir que o garoto não está conosco, ele morrerá. Teus servos faremos com que os cabelos brancos do teu servo, nosso pai, desçam com tristeza ao Sheol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Pois o teu servo se fez de garantia pelo garoto para o meu pai, dizendo: \'Se eu não o trouxer a ti, então, levarei a culpa diante do meu pai para sempre\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Ora, portanto, por favor, permite que teu servo fique no lugar do garoto como escravo para meu senhor, e deixa o garoto subir com seus irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Pois, como eu posso subir para meu pai se o garoto não estiver comigo? Tenho medo de ver o mal que sobreviria ao meu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Então, José não conseguia se controlar diante dos servos que estavam com ele. E disse em alta voz: \"Todos vós, deixai-me\". Então, nenhum servo ficou diante dele, quando José se revelou para seus irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Ele chorou em alta voz, os egípcios ouviram o choro e a casa de Faraó também ouviu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'José disse a seus irmãos: \"Eu sou José. Meu pai ainda está vivo?\". Seus irmãos não conseguiam respondê-lo pois estavam assustados em sua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Então, José disse a seus irmãos: \"Aproximai-vos de mim, por favor\". Então, eles se aproximaram. Ele disse: \"Eu sou José, vosso irmão, a quem vós vendestes para o Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Não vos entristeçais, nem vos afligis por terem me vendido para cá, pois foi para preservação das vossas vidas que Deus me enviou adiante de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Por dois anos, há fome nesta terra e ainda haverá cinco anos sem lavoura e colheita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Deus me enviou até vós para preservar a vossa descendência na terra e para preservar a vossa vida com grande livramento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Então, não fostes vós que me enviastes para cá, mas Deus; e Ele tem feito de mim um pai para Faraó, senhor de toda sua casa e governador de toda a terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Apressai-vos a ir ao meu pai e digam-lhe: \'Isto é o que teu filho José diz: \'Deus me fez senhor de todo o Egito. Vem até mim, não demores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Habitarás na terra de Gósen e estarás perto de mim, tu e teus filhos e os filhos de teus filhos e as tuas ovelhas e os teus bois e tudo o que tens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Ali te sustentarei, para que não caias em pobreza, tu, tua casa e tudo que tens, pois ainda haverá cinco anos de fome\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Olha, teus olhos veem, e os olhos de meu irmão Benjamin, que é minha boca que fala convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Fareis, pois, saber a meu pai a respeito de toda honra que tenho no Egito e a respeito de tudo que vistes. Apressai-vos em trazer meu pai pra cá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Ele abraçou seu irmão Benjamin e os dois choraram abraçados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Ele beijou todos os seus irmãos, chorando sobre eles. Depois disso, seus irmãos falaram com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Essa notícia foi dada na casa de Faraó: \"Os irmãos de José chegaram\". Isso muito agradou a Faraó e a seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Faraó disse a José: \"Diz a teus irmãos: \'Fazei isto: carregai vossos animais e ide à terra de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Buscai vosso pai e vossa família e vinde até mim. Eu vos darei uma boa terra no Egito e comereis do melhor da terra\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Ordena-lhes também, \'Fazei isto: levai carros da terra do Egito para vossos filhos e esposas. Trazei vosso pai e vinde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Não vos preocupeis com vossos bens, pois o melhor de toda a terra do Egito será vosso\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Os filhos de Israel assim o fizeram. José lhes deu carros, como Faraó havia ordenado, e lhes deu provisão para a jornada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Para todos, deu-lhes mudas de roupas, mas, para Benjamin, ele deu trezentas peças de prata e cinco mudas de roupa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Para seu pai, ele mandou isto: dez jumentos carregados com coisas boas do Egito; dez jumentas carregadas com grãos, pães e outros suprimentos para a jornada de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Então, ele enviou seus irmãos e eles partiram. E lhes disse: \"Não brigueis pelo caminho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Saíram do Egito e voltaram para a terra de Canaã, terra de seu pai Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Eles disseram a Jacó: \"José ainda está vivo, e ele é o governador das terras do Egito\". E seu coração ficou perplexo, pois ele não podia acreditar no que diziam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Disseram-lhe todas as palavras que José havia dito. Quando Jacó viu os carros que José havia enviado para levá-lo, o espírito de Jacó seu pai reviveu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'E Israel disse: \"É suficiente. José meu filho ainda está vivo. Eu irei vê-lo antes que eu morra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Israel partiu com tudo o que tinha e foi para Berseba. Lá ele ofereceu sacrifícios ao Deus de seu pai Isaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Deus falou com Isarel em uma visão, à noite, dizendo: \"Jacó, Jacó\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Ele disse: \"Eis-me aqui\". Deus disse: \"Eu sou Deus, o Deus de teu pai. Não temas descer para o Egito, pois lá farei de ti uma grande nação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Eu estarei contigo no Egito e, com certeza, te farei voltar. E José fechará teus olhos com sua própria mão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Então, Jacó levantou-se de Berseba; e os filhos de Israel levaram Jacó seu pai, seus filhos e suas esposas, nos carros que Faraó havia mandado para carregá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Eles levaram seus gados e seus bens que haviam acumulado na terra de Canaã. E vieram para o Egito Jacó e todos os seus descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Ele levou consigo para o Egito seus filhos e os filhos de seus filhos, suas filhas e as filhas de seus filhos e todos os seus descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Estes são os nomes dos filhos de Israel que foram para o Egito: Jacó e seus filhos: Rúben, primogênito de Jacó;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'os filhos de Rúben: Hanoque, Palu, Hezrom e Carmi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Os filhos de Simeão: Jemuel, Jamim, Oade, Jaquim, Zoar e Saul, filho de uma cananéia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Os filhos de Levi: Gérson, Coate e Merari.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'E os filhos de Judá: Er, Onã, Selá, Perez e Zerá, porém Er e Onã morreram na terra de Canaã. Os filhos de Perez foram Hezrom e Hamul;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'os filhos de Issacar: Tola, Puva, Iobe e Sinrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Os filhos de Zebulom: Serede, Elom e Jaleel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Esses são os filhos de Leia, que ela deu a Jacó em Padã-Arã, além de sua filha Diná. Seus filhos e filhas foram ao todo trinta e três pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Os filhos de Gade: Zifiom, Hagui, Suni, Ezbom, Eri, Arodi e Areli.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'E os filhos de Aser: Imná, Isvá, Isvi e Beria, e Sera, a irmã deles; e os filhos de Beria: Héber e Malquiel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Esses são os filhos de Zilpa, que Labão deu a sua filha Leia; e esses ela deu a Jacó, dezesseis pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Os filhos de Raquel, mulher de Jacó: José e Benjamin.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'E nasceram a José, na terra do Egito: Manassés e Efraim, os quais lhe foram dados por Asenate, filha de Potífera, sacerdote de Om.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'E os filhos de Benjamin: Belá, Bequer, Asbel, Gera, Naamã, Eí, Rôs, Mupim, Hupim e Arde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Esses são os filhos de Raquel, que nasceram a Jacó, catorze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'O filho de Dã: Husim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Os filhos de Naftali: Jazeel, Guni, Jezer e Silém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Esses são os filhos de Bila, que Labão deu à sua filha Raquel; e ela os deu a Jacó, sete pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Todas as pessoas que foram com Jacó para o Egito, que eram seus descendentes, sem contar as mulheres de seus filhos, no total, eram sessenta e seis pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Os filhos de José que lhe nasceram no Egito eram dois. Todas as pessoas da casa de Jacó que foram para o Egito eram setenta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Jacó enviou Judá à sua frente ao encontro de José, para que este tomasse o caminho para Gósen; e chegaram à terra de Gósen.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'José preparou sua carruagem e foi ao encontro de Israel, seu pai, em Gósen. Ele o viu, abraçou seu pescoço e chorou por muito tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Israel disse a José: \"Agora já posso morrer, pois vi o teu rosto, e ainda vives\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'José disse a seus irmãos e a casa de seu pai: \"Subirei e relatarei ao Faraó, dizendo: \'Meus irmãos e a casa de meu pai, que estavam na terra de Canaã, vieram até mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Os homens são pastores, pois eles têm cuidado de gado. E trouxeram seus rebanhos, seus gados e tudo o que eles possuem\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Então, quando Faraó vos chamar e perguntar: \'Qual é a vossa ocupação?\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'respondereis: \'Teus servos foram homens de gado desde a nossa juventude até agora, tanto nós como nossos pais\'. Fazei isso, então, vós podereis viver na terra de Gósen, pois todo pastor de rebanho é abominação para os egípcios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Depois, José foi e contou ao Faraó: \"Meu pai e meus irmãos, suas ovelhas, seus rebanhos e tudo o que têm chegaram da terra de Canaã; e estão na terra de Gosén\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Ele escolheu cinco de seus irmãos e os apresentou ao Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Faraó disse aos irmãos de José: \"Qual é a vossa ocupação?\". E eles lhe responderam: \"Teus servos são pastores de ovelhas, assim como nossos antepassados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Depois, eles disseram: \"Nós viemos como forasteiros a esta terra, porque a fome é severa na terra de Canaã e não há pastos para as ovelhas de teus servos. Então, agora, por favor, deixa que teus servos vivam na terra de Gosén\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Depois, Faraó falou com José e lhe disse: \"Teu pai e teus irmãos vieram a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'A terra do Egito está diante de ti. Que o teu pai e os teus irmãos habitem na melhor região, a terra de Gosén. Se tu conheces alguém capaz dentre eles, coloca-o como encarregado de meu rebanho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Então, José trouxe seu pai e o apresentou a Faraó. Jacó abençoou Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Faraó disse a Jacó: \"Quantos anos tens?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jacó lhe respondeu: \"Os anos de minhas peregrinações são cento e trinta anos. Os anos de minha vida são poucos e dolorosos. Eles não têm sido longos como os de meus antepassados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'E Jacó abençoou Faraó e se retirou de sua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Então, José estabeleceu seu pai e seus irmãos. Ele lhes deu um território nas terras do Egito, o melhor dessa terra, na terra de Ramessés, como Faraó havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'José providenciou alimento para seu pai e seus irmãos e para toda a casa de seu pai, de acordo com o número de seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Não havia alimento em toda aquela terra, pois a fome era severa. A terra do Egito e a terra de Canaã estavam desoladas por causa da fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'José arrecadou todo o dinheiro que havia na terra do Egito e na terra de Canaã, vendendo grãos aos que ali habitavam, depois José levou o dinheiro ao palácio do Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Quando todo o dinheiro das terras do Egito e Canaã acabou, todos os egípcios vieram a José dizendo: \"Dá-nos alimento! Deveríamos morrer em tua presença porque não temos mais dinheiro?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'José lhes respondeu: \"Se vosso dinheiro acabou, trazei vossos rebanhos e eu vos darei alimento em troca do vosso rebanho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Então, eles trouxeram seus rebanhos a José. José lhes deu alimento em troca de cavalos, ovelhas, gado e jumentos. Alimentou-os com pão em troca de todo o rebanho aquele ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Quando aquele ano terminou, eles vieram a José, no ano seguinte, dizendo: \"Não esconderemos de nosso senhor que nosso dinheiro acabou, e o senhor já possui nossos rebanhos de gado. Nada restou à vista de meu senhor, exceto nossos corpos e nossas terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Por que deveríamos morrer, tanto nós como nossas terras diante de teus olhos? Compra nossas terras em troca de alimento e nós e nossas terras seremos servos do Faraó. Dá-nos sementes para que possamos viver e não morrer e para que a terra não se torne desolada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Assim, José adquiriu toda a terra do Egito para Faraó. Cada egípcio vendeu seus campos, pois a fome era muito severa. Dessa forma, a terra se tornou do Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'E o povo se tornou escravo de um extremo a outro da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Apenas não comprou a terra dos sacerdotes, porque aos sacerdotes eram dadas porções de alimento. Eles se sustentavam da porção que lhes era dada por Faraó. Portanto, não venderam suas terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'José disse ao povo: \"Vede, eu vos comprei e comprei vossas terras hoje para o Faraó. Agora aqui estão sementes para vós e vós plantareis na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Na colheita, devereis dar a quinta parte ao Faraó e quatro partes serão vossas, para semear o campo e para servir de alimento às vossas famílias e aos vossos filhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Eles responderam: \"Tu salvaste nossas vidas. Achamos favor diante de teus olhos. Seremos escravos de Faraó\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Então, José fez disso um decreto que permanece na terra do Egito até hoje: a quinta parte pertence ao Faraó. Apenas a terra dos sacerdotes não se tornou propriedade de Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Assim Israel viveu na terra do Egito, na terra de Gosén. Seu povo ganhou posses ali. Eles frutificaram e multiplicaram-se grandemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Jacó viveu na terra do Egito dezessete anos, então, os anos da vida de Jacó foram cento e quarenta e sete anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Quando o tempo da morte de Israel se aproximava, ele chamou seu filho José e lhe disse: \"Se agora eu encontrar favor em ti, coloca a tua mão embaixo de minha coxa e mostra-me fidelidade e confiabilidade. Por favor, não me enterres no Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Quando eu adormecer com meus pais, leva-me para fora do Egito e enterra-me junto a meus pais\". José lhe respondeu: \"Eu farei como disseste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Israel disse: \"Jure a mim\", e José jurou a ele. Depois, Israel se inclinou sobre a cabeceira de sua cama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Aconteceu que, depois dessas coisas, veio alguém e disse a José: \"Eis que teu pai está doente\". Então, ele pegou seus dois filhos, Manassés e Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Quando disseram a Jacó \"Eis que teu filho José chegou para ver-te\", Israel se esforçou e se sentou na cama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Jacó disse a José: \"O Deus Todo Poderoso me apareceu na cidade de Luz, na terra de Canaã. Ele me abençoou');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'e me disse: \'Eis que te farei fértil e te multiplicarei. Farei de ti uma multidão de povos e darei a teus descendentes esta terra como possessão perpétua\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'E, assim, teus dois filhos, que nasceram para ti na terra do Egito antes que eu viesse a ti no Egito, eles são meus. Efraim e Manassés serão meus, assim como Rúben e Simeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Os filhos que tiveres depois deles serão teus; e em nome de seus irmãos receberão sua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Porque, quando vim de Padã, para minha tristeza, Raquel morreu no caminho da terra de Canaã, enquanto ainda faltava certa distância para chegar em Efrata. Eu a enterrei no caminho para Efrata\", que é Belém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Quando Israel viu os filhos de José, disse: \"Quem são estes?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'José lhe respondeu: \"Estes são meus filhos, que Deus me deu aqui\". Israel lhe disse: \"Traze-os até mim, para que eu os abençoe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Os olhos de Israel já não enxergavam devido a sua idade avançada, por isso ele não pôde vê-los. Então, José os trouxe para perto dele, que os beijou e os abraçou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Israel disse a José: \"Nunca esperei ver tua face novamente, mas Deus me permitiu ver teus filhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'José os tirou do colo de Israel e, então, prostou-se com rosto em terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'José pegou os dois, Efraim pela sua mão direita em direção à mão esquerda de Israel, e Manassés pela sua mão esquerda em direção à mão direita de Israel, e os trouxe para perto dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Israel estendeu sua mão direita e a pôs sobre a cabeça de Efraim, que era o mais jovem, e sua mão esquerda sobre a cabeça de Manassés, assim ele cruzou suas mãos, pois Manassés era o primogênito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Israel abençoou José, dizendo-lhe: \"O Deus com quem meus pais Abraão e Isaque andaram, o Deus que tem cuidado de mim até este dia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'o Anjo que tem me protegido de todo perigo, abençoe estes rapazes. E que o meu nome seja reconhecido neles, e também o nome de meus pais, Abraão e Isaque. E que se multipliquem sobre a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Quando José viu a mão direita de seu pai na cabeça de Efraim, isso lhe foi desagradável. Então, ele pegou a mão de seu pai e a removeu da cabeça de Efraim para a cabeça de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'José disse a seu pai: \"Assim não, meu pai, pois este é o primogênito. Põe tua mão direita sobre a cabeça dele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Seu pai se recusou e lhe disse: \"Eu sei, meu filho, eu sei. Ele também se tornará um povo, e ele também será grande. Mas seu irmão mais jovem será maior do que ele, e a descendência dele se tornará como uma multidão de nações\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Israel os abençoou naquele dia com estas palavras: \"O povo de Israel pronunciará bênçãos utilizando vossos nomes, dizendo: \'Que Deus vos faça como Efraim e Manassés\'\". Desse modo, Israel colocou Efraim à frente de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Israel disse a José: \"Eis que estou para morrer, porém Deus estará contigo, e Ele vai te trazer de volta para a terra de teus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Para ti, como alguém que está acima de teus irmãos, te dou a encosta da montanha que tomei dos amorreus com minha espada e com meu arco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Então, Jacó chamou seus filhos e lhes disse: \"Reuni-vos, que vou dizer-vos o que vos acontecerá no futuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Ajuntai-vos e escutai, filhos de Jacó. Escutai a Israel, vosso pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Rúben, tu és meu primogênito, minha força e o início do meu vigor, excelente em dignidade e poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Incontrolável como as águas turbulentas, não terás a primazia, porque subiste à cama de teu pai. Assim a contaminaste; subiste à minha cama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeão e Levi são irmãos. Suas espadas são armas de violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Ó minha alma, não entres em seu conselho. Não me encontrarei em seus ajuntamentos, pois meu coração é muito honrado para isso. Porque, no seu furor, mataram homens. Foi por prazer que esquartejaram bois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Que sua ira seja amaldiçoada, porque era forte, e sua fúria era cruel. Eu os dividirei em Jacó e os espalharei em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Judá, teus irmãos te louvarão. Tua mão será sobre o pescoço de teus inimigos. Os filhos de teu pai se curvarão diante de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Judá é um leãozinho. Tu resististe às tuas suas presas, meu filho. Inclinando-se, ele se agachou como um leão, como uma leoa. Quem se atreveria a despertá-lo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'O cetro não se apartará de Judá, nem o pendão de autoridade dentre seus pés, até que venha Siló. As nações lhe obedecerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Amarrando seu jumentinho na vinha e o potro da jumenta na videira escolhida, ele lavará suas roupas no vinho e sua túnica no sangue de uvas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Seus olhos serão tão escuros quanto o vinho e os seus dentes brancos como o leite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zebulom habitará na região costeira. Ele será um porto para os navios e seus domínios se estenderão até Sidom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issacar é um jumento forte, deitado entre os currais das ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Ele vê um bom lugar de descanso e uma terra agradável. Oferecerá seus ombros para a carga e se entregará como servo para as tarefas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dã julgará seu povo como uma das tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dã será como uma serpente à beira da estrada, uma serpente peçonhenta que morde o calcanhar do cavalo, e assim faz cair o seu cavaleiro para trás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Eu espero por Tua salvação, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gade, cavaleiros o atacarão, mas ele os atacará nos seus calcanhares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'O alimento de Aser será abundante, e produzirá iguarias reais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naftali é uma corça livre e terá belos filhotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'José é um ramo frutífero, perto de uma fonte, cujos galhos escalam acima do muro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Os arqueiros irão atacá-lo, atirar nele e assediá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Mas seu arco permanecerá firme e suas mãos permanecerão hábeis por causa das mãos do Poderoso de Jacó e devido ao nome do Pastor, a Rocha de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'O Deus de teu pai te ajudará e o Todo Poderoso Deus te abençoará com bênçãos celestiais de cima, bênçãos das profundezas que repousam abaixo e bênçãos dos seios e do ventre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'As bênçãos de teu pai serão maiores do que as bênçãos das antigas montanhas ou as coisas mais desejáveis das eternas colinas. Eles estarão sob a cabeça de José, bênçãos que coroam a cabeça de quem foi príncipe sobre seus irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamim é um lobo faminto. De manhã, devorará a presa e, à noite, dividirá o despojo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Essas são as doze tribos de Israel. Isso foi o que seu pai lhes disse quando os abençoou. A cada um abençoou com uma bênção apropriada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Então, ele os instruiu e lhes disse: \"Em breve, irei para o meu povo. Enterrai-me com meus antepassados na cova que está no campo de Efrom, o heteu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'na caverna que está no campo de Macpela, que é perto de Manre, na terra de Canaã, o campo que Abraão comprou de Efrom, o heteu, para sepultura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Ali, eles sepultaram Abraão e Sara, sua esposa; ali, eles sepultaram Isaque e Rebeca, sua esposa; e ali sepultei a Lia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'O campo e a cova que está nele foram comprados do povo de Hete\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Quando Jacó terminou essas instruções a seus filhos, recolheu seus pés na cama, deu seu último suspiro e foi para o seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Então, José se lançou sobre o rosto de seu pai, chorou sobre ele e o beijou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'José ordenou a seus servos, os médicos, para embalsamar seu pai. Então, os médicos embalsamaram Israel');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Eles levaram quarenta dias, pois esse é o tempo completo para embalsamento. Os egípcios lamentaram por ele setenta dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Quando os dias de lamento acabaram, José falou para a corte real de Faraó, dizendo: \"Se eu tenho achado graça aos teus olhos, por favor, dizei ao Faraó:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, '\'Meu pai me fez jurar, dizendo: \'Vê, estou para morrer. Sepulta-me no túmulo que cavei para mim mesmo na terra de Canaã. Lá me sepultarás\'. Agora, deixa-me subir e sepultar meu pai, e, então, retornarei\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Faraó respondeu: \"Vai e sepulta teu pai, como ele te fez jurar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'José foi sepultar seu pai. Com ele, subiram todos os oficiais de Faraó, toda a corte de sua casa, e todas as autoridades da terra do Egito,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'com toda a casa de José e seus irmãos, e a casa de seu pai. Mas eles deixaram suas crianças, seu rebanho de ovelhas, e seu rebanho de gados na terra de Gósen.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Foram também com ele carros e cavaleiros; era um grande grupo de pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Quando eles chegaram à eira de Atade, do outro lado do rio Jordão, eles lamentaram com grande e intenso choro. Lá, José fez sete dias de lamento por seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Quando os habitantes da terra, os cananeus, viram a lamentação na eira de Atade, eles disseram: \"Esta é uma ocasião muito triste para os egípcios\". É por esta razão que o lugar é chamado Abel-Mizraim e está além do Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Então, seus filhos fizeram a Jacó como ele lhes havia instruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Carregaram-no até a terra de Canaã e o sepultaram na caverna, no campo de Macpela, perto de Manre. Abraão havia comprado a caverna com o campo para ser lugar de sepultura. Ele comprou de Efrom, o heteu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Depois de sepultar seu pai, José retornou para o Egito, junto com seus irmãos, e todos aqueles que o acompanharam para o sepultamento de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Quando os irmãos de José viram que seu pai estava morto, disseram: \"E se José tiver um rancor e quiser nos retribuir por todo o mal que lhe causamos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Então, eles enviaram uma mensagem para José, dizendo: \"Teu pai deu instruções antes de morrer, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '\'Diz isto a José: Por favor, perdoa teus irmãos e o erro que eles cometeram quando te trataram mal. Agora, por favor, perdoa os servos do Deus de teu pai\'\". José chorou quando a mensagem chegou até ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Seus irmãos também prostaram-se diante dele e disseram: \"Eis que nós somos teus servos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'E José lhes respondeu: \"Não tenhais medo. Por acaso estou no lugar de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'É certo que vós planejastes contra mim, mas Deus tornou isso em algo bom, para preservar a vida de muitas pessoas, como vedes hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Então, agora, não tenhais medo. Eu proverei para vós e vossos filhos\". Ele lhes confortou e assim lhes falou gentilmente ao coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'José viveu no Egito junto com a família de seu pai. Ele viveu cento e dez anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'José viu os filhos de Efraim até a terceira geração. Ele também viu os filhos de Maquir, filho de Manassés. Eles nasceram sobre os joelhos de José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'José disse a seus irmãos: \"Eu estou para morrer, mas Deus certamente virá até vós e vos fará subir desta terra para a terra que Ele jurou dar a Abraão, Isaque e Jacó\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Então, José fez o povo de Israel jurar, dizendo: \"Deus certamente vos visitará. Neste tempo carregareis meus ossos daqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Então, José morreu aos cento e dez anos. Depois, eles o embalsamaram e o colocaram num caixão no Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Estes são os nomes dos filhos de Israel que vieram para o Egito com Jacó, cada um com sua casa:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Rúben, Simeão, Levi e Judá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issacar, Zebulon e Benjamin,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dã, Naftali, Gade e Aser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Todos os descendentes de Jacó eram setenta. José já estava no Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Então José, todos os seus irmãos e toda aquela geração morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Os israelitas eram frutíferos, numerosos e se tornaram fortes; a terra estava cheia deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Então, um novo rei se levantou no Egito, o qual não se importava com a memória de José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Ele disse ao seu povo: \"Olhai os israelitas; eles são mais numerosos e fortes que nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Vide. Vamos lidar sabiamente com eles. Caso contrário, eles continuarão a multiplicar-se e, se acontecer uma guerra, eles se juntarão aos nossos inimigos, lutarão contra nós, e deixarão a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Então, eles colocaram feitores que os oprimiam com trabalhos pesados. Os israelitas construíram cidades-armazéns para Faraó: Pitom e Ramessés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Porém, quanto mais os egípcios os oprimiam, mais os israelitas se tornavam numerosos e se espalhavam. Então, os egípcios começaram a temer os israelitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Os egípcios fizeram os israelitas trabalharem rigorosamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Eles tornaram a vida deles amarga, com trabalhos pesados com barro e tijolo, e com todo tipo de trabalho nos campos. Todo o trabalho exigido era pesado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Em seguida, o rei do Egito falou às parteiras dos hebreus; o nome de uma era Sifrá, e a outra se chamava Puá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Ele disse: \"Quando vós ajudardes as hebreias no parto, observai quando elas derem à luz. Se for menino, então deveis matá-lo; mas, se for menina, ela viverá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Entretanto as parteiras temiam a Deus e não fizeram como o rei do Egito lhes ordenara. Em vez disso, deixaram que os meninos vivessem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'O rei do Egito convocou as parteiras e lhes disse: \"Por que deixastes os meninos viverem?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'As parteiras responderam a Faraó: \"As hebreias não são como as egípcias; elas são vigorosas e terminam de dar à luz antes que uma parteira chegue a até elas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Deus protegeu aquelas parteiras. O povo cresceu numerosamente e se tornou muito forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Por conta do temor das parteiras, Deus lhes deu famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Faraó ordenou a todo o seu povo: \"Deveis jogar no rio todos os meninos nascidos, mas deixai todas as meninas viverem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Um homem da tribo de Levi casou-se com uma mulher descendente de Levi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'A mulher engravidou e deu à luz um filho. Quando ela viu que ele era um menino formoso, ela o escondeu por três meses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Mas, quando ela não pôde mais escondê-lo, tomou um cesto de junco e o revestiu de betume e piche. Depois colocou a criança dentro dele e o pôs nas águas, ao longo da margem do rio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Sua irmã ficou a certa distância para observar o que aconteceria com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'A filha de Faraó desceu ao rio para banhar-se, enquanto suas servas caminhavam pela margem. Ela viu o cesto entre os juncos e enviou uma serva para pegá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Quando o abriu, viu a criança. Diante dela, a criança chorava. Ela teve compaixão dele e disse: \"Esta é, certamente, uma criança hebreia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Então, a irmã da criança disse à filha de Faraó: \"Queres que eu vá e encontre uma mulher hebreia para alimentar a criança para a senhora?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'A filha de Faraó respondeu: \"Vai\". Então, a jovem foi e trouxe a mãe da criança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'A filha de Faraó disse à mãe da criança: \"Leva este menino e o amamenta para mim; eu te pagarei salário. Então, a mulher o levou e o amamentou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Quando o menino cresceu um pouco mais, ela o trouxe para a filha de Faraó e ele se tornou filho dela. Ela o chamou de Moisés, dizendo: \"Porque das águas o tirei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Quando Moisés cresceu, ele foi até seu povo e observou seu penoso trabalho. Certo dia, ele viu um egípcio surrando um hebreu, alguém de seu próprio povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Ele olhou para um lado e para o outro e, quando viu que não havia ninguém ali, matou o egípcio e escondeu seu corpo na areia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'E tornou a sair no dia seguinte e se deparou com dois hebreus lutando. Ele disse para aquele que iniciou a briga: \"Por que estás batendo em seu companheiro?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Mas o homem lhe respondeu: \"Quem te fez um líder e juiz sobre nós? Estás planejando me matar, como fizeste ao egípcio?\". Então Moisés ficou com medo e pensou: \"O que eu fiz, certamente, tornou-se conhecido dos outros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Faraó, ao ouvir a respeito disso, tentou matar Moisés. Mas Moisés fugiu e escondeu-se na terra de Midiã. Lá, ficou sentado perto de um poço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'O pastor de Midiã tinha sete filhas. Elas vieram, tiraram água, e encheram os coxos para dar de beber ao rebanho de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Os pastores vieram e tentaram tirá-las de lá, mas Moisés levantou-se e as defendeu. E, então, deu de beber ao rebanho delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Quando as moças foram até Reuel, seu pai, ele lhes disse: \"Por que voltastes para casa mais cedo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Elas responderam: \"Um egípcio nos resgatou dos pastores. Ele até deu de beber a nós e ao rebanho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Ele disse às filhas: \"E onde ele está? Por que o deixastes? Chamai-o para que possa comer conosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Moisés concordou em ficar com aquele homem, que também lhe deu sua filha Zípora em casamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Ela deu à luz um filho, e Moisés deu-lhe o nome de Gérson, dizendo: \"Eu tenho sido peregrino numa terra estrangeira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Muito tempo depois, o rei do Egito morreu. Os israelitas queixaram-se devido ao trabalho escravo. Eles imploraram por socorro, e suas súplicas chegaram a Deus por causa da Sua misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Quando Deus ouviu o clamor dos hebreus, trouxe à memória Sua aliança com Abrãao, com Isaque e com Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Deus olhou para os israelitas e entendeu sua situação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Moisés, agora, pastoreava o rebanho de Jetro, seu sogro, o sacerdote de Midiã. Moisés conduziu o rebanho para longe do deserto e chegou a Horebe, a montanha de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Então, o Anjo de Yahweh lhe apareceu numa chama de fogo em um arbusto. Moisés olhou, e eis que o arbusto estava em chamas, mas não se queimava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Moisés disse: \"Eu darei uma volta para ver melhor esse fenômeno, porque o arbusto não está sendo consumido pelas chamas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Quando Yahweh viu que ele contornou para ver, Deus o chamou das chamas e disse: \"Moisés, Moisés\". Moisés disse: \"Eis-me aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Deus ordenou: \"Não te aproximes mais! Tira os sapatos de teus pés, pois este lugar em que estás é terra consagrada a Mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'E disse mais: \"Eu sou o Deus de teu pai, o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó\". Então, Moisés cobriu o rosto, pois estava com medo de olhar para Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Yahweh disse: \"Com certeza, Eu tenho visto o sofrimento do Meu povo, que está no Egito. Eu tenho ouvido o seu clamor por causa dos feitores, pois conheço os seus sofrimentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Eu desci para libertá-los das mãos dos egípcios e para levá-los a uma terra boa e farta, uma terra de onde flui leite e mel; a região dos cananeus, heteus, amorreus, periseus, heveus e jebuseus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'O clamor do povo de Israel tem chegado a Mim. Além disso, Eu tenho visto a opressão causada pelos egípcios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Agora, portanto, Eu te enviarei a Faraó e, então tu deverás trazer meu povo, os israelitas, para fora do Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mas Moisés disse a Deus: \"Quem sou eu para ir a Faraó e tirar os Israelitas para fora do Egito?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Deus respondeu: \"Certamente, Eu estarei contigo. Isto será um sinal de que Eu o enviei. Quando tu tiveres trazido teus irmãos do Egito, vós me adorareis neste monte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Moisés disse a Deus: \"Quando eu for aos israelitas e disser-lhes: \'O Deus de vossos antepassados me enviou a vós,\' e, quando eles disserem a mim: \'Qual é o nome Dele?\', o que devo dizer-lhes?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Deus respondeu a Moisés: \"EU SOU O QUE SOU\". Deus disse: \"Tu deverás dizer ao israelitas: \'EU SOU me enviou a vós\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Deus também disse a Moisés: \"Tu deverás dizer aos israelitas: \'Yahweh, o Deus de vossos antepassados, o Deus de Abraão, de Isaque e de Jacó enviou-me a vós. Este é o Meu nome para sempre; é assim que me invocarão por todas as gerações\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Ide e reuni os anciãos de Israel. Dizei-lhes: \'Yahweh, o Deus de vossos antepassados, o Deus de Abraão, de Isaque e de Jacó, apareceu a mim e disse: \"De fato, Eu vos tenho observado e visto o que vos tem acontecido no Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Eu tenho prometido tirar-vos da opressão do Egito para a terra dos cananeus, heteus, amorreus, perizeus, heveus e jebuseus, uma terra de onde flui leite e mel\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Eles te ouvirão. Tu e os anciãos de Israel irão ao rei do Egito e dirão a ele: \'Yahweh, o Deus dos hebreus, encontrou-nos. Portanto, deixa-nos ir por três dias de jornada no deserto, de forma que ali possamos sacrificar a Yahweh, nosso Deus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Mas Eu sei que o rei do Egito não vos deixará partir, a menos que seja forçado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Eu os alcançarei com Minha mão e atacarei os egípcios com todos os prodígios que farei no meio deles. Após isso, ele vos deixará ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Eu asseguro que vós tereis o favor dos egípcios quando partirem; não partirão de mãos vazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Todas as mulheres pedirão prata, joias de ouro e roupas de suas vizinhas egípcias e de quaisquer outras que estiverem hospedadas na casa de suas vizinhas. Vós colocareis em seus filhos e filhas. Desse modo, vós saqueareis os egípcios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Moisés disse: \"E, se eles não acreditarem em mim, ou não me derem ouvidos e, além disso, disserem: \'Yahweh não te apareceu\'?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Deus lhe disse: \"O que é isso na tua mão?\". Moisés respondeu: \"Uma vara\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Yahweh disse: \"Joga-a no chão\". Moisés a jogou no chão, e a vara se tornou uma cobra. Moisés fugiu dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Yahweh disse a Moisés: \"Estende a tua mão e pega-a pela cauda\". Então, ele estendeu a mão e pegou a cobra. E se tornou uma vara em suas mãos novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '\"Isso é para que eles creiam que Yahweh, o Deus de vossos ancestrais, o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó, te apareceu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Yahweh também disse a ele: \"Agora, coloca tua mão dentro do teu manto\". Então, Moisés colocou a mão dentro do manto. Quando ele a tirou, sua mão estava leprosa, tão branca quanto a neve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Yahweh disse: \"Coloca tua mão dentro do manto novamente\". Então, Moisés assim o fez e, quando a tirou, ela havia se tornado saudável de novo, como o resto de sua carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Yahweh disse: \"Se eles não acreditarem em ti, se eles não prestarem atenção ao primeiro sinal do Meu poder ou não acreditarem, então, eles crerão por causa do segundo sinal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'E, se eles não acreditarem nem mesmo nesses dois sinais do Meu poder, ou não te derem ouvidos, então, pega um pouco de água do rio e derrama na terra seca. A água que tu pegares se tornará sangue na terra seca\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Então, Moisés disse a Yahweh: \"Senhor, eu nunca fui eloquente, nem no passado, nem desde que falaste ao teu servo. Eu sou hesitante para falar e lento de língua\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Yahweh disse a ele: \"Quem é Este que fez a boca do homem? Quem faz um homem mudo ou surdo, ou o que vê, ou o cego? Não sou eu, Yahweh?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Então, agora, vai. Eu serei a tua boca e te ensinarei o que dizer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Mas Moisés clamou: \"Senhor, por favor, manda outra pessoa, qualquer um que desejares enviar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Então, Yahweh ficou irado com Moisés. Ele disse: \"E Arão, teu irmão, o levita? Eu sei que ele pode falar bem. Além disso, ele está vindo te encontrar, e, ao ver-te, ficará alegre em seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Tu falarás a ele e colocarás as palavras em sua boca. Eu serei com a tua boca e com a boca de Arão. E eu mostrarei a ambos o que fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Ele falará ao povo por ti. Ele será a tua boca, e tu serás para ele como Eu sou para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Tu tomarás em tuas mãos esta vara. Com ela, farás os sinais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Então, Moisés voltou a Jetro, seu sogro, e disse-lhe: \"Deixa-me ir e retornar aos meus parentes que estão no Egito e ver se eles ainda estão vivos\". Jetro disse a Moisés: \"Vai em paz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Yahweh falou a Moisés em Midiã: \"Vai, retorna ao Egito, pois todos os homens que estavam tentando tirar tua vida estão mortos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Moisés tomou sua esposa e seus filhos e colocou-os em um jumento. Ele retornou para a terra do Egito. E ele pegou a vara de Deus em suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Yahweh disse a Moisés: \"Quando voltares ao Egito, cuida para que faças diante de Faraó todas as maravilhas que Eu coloquei em teu poder. Mas Eu vou endurecer o coração dele, e ele não deixará o povo ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Tu dirás a Faraó: \'Isto é o que Yahweh diz: Israel é meu filho, meu primogênito,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'e Eu te digo: \"Deixa Meu filho ir, para que Me adore\". Mas, se tu recusares a deixá-lo ir, Eu certamente matarei teu filho, teu primogênito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'A caminho do Egito, quando eles pararam para descansar à noite, Yahweh encontrou Moisés e tentou matá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Então, Zípora pegou uma faca de pedra e cortou fora o prepúcio de seu filho, e colocou aos pés de Moisés, dizendo: \"Certamente, tu és um marido sanguinário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Então, Yahweh o deixou. Ela disse: \"Certamente, tu és um marido sanguinário\" por causa da circuncisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Yahweh disse a Arão: \"Vai ao deserto para encontrar Moisés\". Arão foi, encontrou-o na montanha de Deus, e o beijou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Moisés contou a Arão todas as palavras que Yahweh lhe enviara para dizer e sobre todos os sinais do poder de Yahweh, que Ele lhe ordenara fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Então, Moisés e Arão foram e ajuntaram os anciãos dos israelitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Arão falou todas as palavras que Yahweh dissera a Moisés. Este expôs os sinais do poder de Yahweh diante do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'O povo acreditou. Quando eles ouviram que Yahweh observava os israelitas e que Ele havia visto sua opressão, então eles prostraram suas cabeças e O adoraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Depois dessas coisas, Moisés e Arão foram até Faraó e lhe disseram: \"Isto é o que Yahweh, o Deus de Israel, disse: \'Deixa meu povo ir. Assim, eles poderão celebrar uma festa para Mim, no deserto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Faraó disse: \"Quem é Yahweh? Por que eu devo ouvir Sua voz e deixar Israel ir? Eu não conheço Yahweh. Eu não deixarei Israel ir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Eles disseram: \"O Deus dos hebreus quer se encontrar conosco. Deixa-nos ir para uma viagem de três dias para celebrar e sacrificar a Yahweh, nosso Deus, de modo que não sejamos alvo de praga por meio de Sua espada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Mas o rei do Egito disse a eles: \"Moisés e Arão, por que estais tirando o povo do seu trabalho? Voltai ao trabalho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Ele também disse: \"Existem agora muitos hebreus em nossa terra, e os fazeis abandonar o seu trabalho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'No mesmo dia, Faraó deu uma ordem para os capatazes e mestres das tarefas do povo. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '\"Ao contrário de antes, não deis mais palha ao povo para fazer tijolos. Deixai que eles vão e reúnam palha para si mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Contudo ainda deveis exigir o mesmo número de tijolos que eles fizeram antes. Não aceiteis nenhum a menos, porque eles estão preguiçosos. É por isso que eles estão clamando e dizendo: \'Permita-nos ir e sacrificar ao nosso Deus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Aumentai a carga de trabalho para esses homens, para que não deem atenção às palavras enganosas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Então, os capatazes do povo e os mestres de obras saíram e informaram ao povo. Eles disseram: \"Isto é o que o Faraó disse: \'Eu não darei mais nenhuma palha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Vós mesmos deveis ir e pegar palha onde quer que as encontrem, mas vosso trabalho não será reduzido\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Então o povo espalhou-se por toda a terra do Egito, colhendo restolho ao invés de palha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Os mestres de obras, impelindo-os, disseram: \"Terminai vosso trabalho, mas palha não vos daremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Os mestres de obras do Faraó, que estavam sobre os capatazes israelitas, os mesmos que estavam sobre os trabalhadores, perguntaram-lhes: \"Por que vós não estais produzindo os tijolos exigidos, tanto ontem como hoje, como fazíeis anteriormente?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Então, os capatazes israelitas foram até Faraó e reclamaram. Eles disseram: \"Por que tratas teus servos desta forma?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Não dás a nós, teus servos, mais palha, e ainda nos dizes: \'Fazei tijolos!\' Nós, teus servos, somos castigados agora, mas esta falta é do teu povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Porém Faraó disse: \"Vós sois preguiçosos! Sois preguiçosos! Vós dizeis: \'Deixa-nos ir sacrificar a Yahweh.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Então, agora, voltai ao trabalho. Não iremos dar mais palha para vós, mas vós fareis o mesmo número de tijolos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Os capatazes israelitas perceberam o problema quando foram informados sobre esta decisão: \"Vós não reduzireis o número diário de tijolos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Eles procuraram Moisés e Arão, que estavam em pé, do outro lado do palácio, longe de onde estava Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Eles disseram a Moisés e Arão: \"Que Yahweh olhe para vós e vos aflija, porque vós fizestes com que Faraó olhasse para seus servos com maus olhos. Vós colocastes a espada em suas mãos para nos matar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Moisés se voltou para Yahweh e disse: \"Senhor, por que Tu tens causado problemas a este povo? Primeiro, por que Tu me enviaste para este lugar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Desde que vim falar com Faraó em Teu nome, ele tem causado problemas a este povo, e Tu não tens levado teu povo à liberdade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Então, Yahweh disse a Moisés: \"Agora, tu verás o que farei a Faraó. Verás que ele os deixará ir por causa da Minha forte mão. Devido à Minha poderosa mão, ele os expulsará da sua terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Deus falou a Moisés, dizendo: \"Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Eu apareci a Abraão, a Isaque e a Jacó, como Deus Poderoso; mas, por Meu nome, Yahweh, Eu não era conhecido por eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Eu também estabeleci a Minha aliança com eles, para lhes dar a terra de Canaã, a terra onde eles moraram como peregrinos, a terra pela qual eles passaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Além disso, Eu tenho escutado o gemido dos israelitas, os quais foram escravizados pelos egípcios, e Eu tenho Me lembrado da Minha aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Portanto, diz aos israelitas: \'Eu sou Yahweh. Eu vos tirarei da escravidão dos egípcios e vos libertarei do poder deles. Resgatar-vos-ei com Minha poderosa mão e com grandes atos de julgamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Eu vos tomarei para Mim, como Meu povo, e Eu serei vosso Deus. E vós sabereis que Eu Sou Yahweh, vosso Deus, que vos tirou da escravidão dos egípcios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Eu vos levarei para a terra que Eu prometi dar a Abraão, a Isaque e a Jacó. Eu a darei como posse. Eu Sou Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Quando Moisés disse isso aos israelitas, eles não o escutaram devido ao desânimo causado pela dura escravidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Então Yahweh falou a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '\"Vai e fala ao Faraó, rei do Egito, para deixar o povo de Israel partir de sua terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Moisés disse a Yahweh: \"Se os israelitas não têm me escutado, por que Faraó me escutará, já que eu não sou bom no falar?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Mas Yahweh falou a Moisés e a Arão, dando-lhes ordens para os israelitas e para Faraó, rei do Egito, a fim de que os israelitas deixassem a terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Estes foram os cabeças da casa dos seus pais: os filhos de Rúben, o primogênito de Israel, foram Hanoque, Palu, Hezrom e Carmi. Estas foram as famílias de Rúben.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Os filhos de Simeão foram Jemuel, Jamim, Oade, Jaquim, Zoar e Saul — o filho da mulher cananéia. Essas foram as famílias de Simeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Aqui estão listados os nomes dos filhos de Levi, conforme os seus descendentes. Eles foram Gérson, Coate e Merari. Levi viveu cento e trinta e sete anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Os filhos de Gérson foram Libni e Simei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Os filhos de Coate foram Anrão, Isar, Hebrom e Uziel. Coate viveu cento e trinta e três anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Os filhos de Merari foram Mali e Musi. Estes se tornaram famílias de Levi, junto de seus descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Anrão casou-se com Joquebede, irmã do seu pai. E ela lhe deu Arão e Moisés. Anrão viveu cento e trinta e sete anos e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Os filhos de Izar foram Corá, Nofegue e Zicri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Os filhos de Uziel foram Misael, Elzafã e Sitri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Arão casou-se com Eliseba, filha de Aminadabe, irmã de Nasom. Ela lhe deu Nadabe e Abiú, Eleazar e Itamar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Os filhos de Corá foram Assir, Elcana e Abiasafe. Estas foram as famílias dos coraítas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleazar, filho de Arão, casou-se com uma das filhas de Putiel. Ela deu à luz Fineias. Esses foram os cabeças dos pais dos levitas, junto de seus descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Estes foram os dois homens, Arão e Moisés, a quem Yahweh disse: \"Tirai os israelitas da terra do Egito, por seus grupos de guerreiros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Foram Arão e Moisés que falaram a Faraó, rei do Egito, para deixar partir os israelitas da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Quando Yahweh falou a Moisés na terra do Egito,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Ele disse: \"Eu sou Yahweh. Diz a Faraó, rei do Egito, todas as coisas que te direi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Mas Moisés disse a Yahweh: \"Eu não sou bom em falar, então, por que Faraó me escutará?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Yahweh disse a Moisés: \"Vê, Eu te tenho feito como um deus diante de Faraó. Arão, teu irmão, será o teu profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Tu dirás tudo o que Eu te ordenar dizer. Arão, teu irmão, falará a Faraó para que ele deixe o povo de Israel partir de sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Mas Eu endurecerei o coração de Faraó, e manifestarei muitos sinais do Meu poder e muitas maravilhas na terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Mas Faraó não te ouvirá. Então Eu colocarei Minha mão sobre o Egito e tirarei Meus batalhões, o Meu povo, os descendentes de Israel. Eu os tirarei da terra do Egito por meio de grandes atos de juízo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Os egípcios saberão que Eu sou Yahweh, quando Eu estender a Minha mão sobre o Egito e tirar os israelitas do meio deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Assim, Moisés e Arão fizeram; justamente como Yahweh lhes havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Moisés tinha oitenta anos, e Arão, oitenta e três, quando falaram a Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Yahweh falou a Moisés e a Arão:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '\"Quando Faraó vos disser: \'Fazei um milagre\', então tu dirás a Arão: \'Toma tua vara e lança-a diante de Faraó, para que se transforme numa serpente\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Então, Moisés e Arão foram a Faraó e fizeram exatamente conforme Yahweh havia ordenado. Arão lançou sua vara diante de Faraó e seus servos, e ela se transformou numa serpente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Então, Faraó também chamou os seus sábios e feiticeiros. Eles fizeram a mesma coisa por meio de sua feitiçaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Cada um deles lançou sua vara ao solo, e elas se transformaram em serpentes. Porém a vara de Arão devorou as serpentes deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'O coração de Faraó se endureceu e ele não os ouviu, assim como Yahweh havia dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Yahweh disse a Moisés: \"O coração de Faraó está endurecido e ele se recusa a deixar o povo ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Vai a Faraó pela manhã, quando ele estiver junto às águas. Fica à beira do rio, para encontrá-lo, e leva na mão a vara que se transformou numa serpente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Diz a ele: \'Yahweh, o Deus dos hebreus, enviou-me a ti para dizer-te: \"Deixa o meu povo ir, e, assim, eles poderão me adorar no deserto. Até agora, tu não tens nos ouvido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Yahweh disse: \"Assim, saberás que Eu sou Yahweh. Eu ferirei a água do rio Nilo com a vara que está em Minha mão, e o rio se transformará em sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Os peixes que estiverem no rio morrerão, e o rio cheirará mal. Os egípcios não conseguirão beber a água do rio\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'E, então, Yahweh disse a Moisés: \"Diz a Arão: \'Toma a tua vara e estende tua mão sobre as águas do Egito, sobre os seus rios, sobre seus canais, sobre suas lagoas e sobre todas as suas poças d\'água, para que suas águas se transformem em sangue. Faz isso e, então, haverá sangue por toda a terra do Egito, até mesmo nas vasilhas de madeira e de pedra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Moisés e Arão fizeram como Yahweh havia ordenado. Arão levantou a vara e feriu a água no rio, diante de Faraó e de seus servos. Toda a água do rio se transformou em sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Os peixes morreram e o rio começou a cheirar mal. Os egípicios não podiam beber da água do rio, e o sangue estava por todo lugar na terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Mas os feiticeiros do Egito fizeram a mesma coisa com a sua feitiçaria. Assim, o coração de Faraó se endureceu e ele se recusou a ouvir Moisés e Arão, exatamente como Yahweh havia dito que aconteceria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'E assim Faraó virou-se e foi para a sua casa. Ele nem mesmo considerou o caso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Todos os egípcios cavaram ao redor do rio procurando água para beber, porém não puderam beber da água do rio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'E sete dias se passaram depois de Yahweh ter ferido o rio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Falou Yahweh a Moisés: \"Vai a Faraó e dize-lhe: \'Assim diz Yahweh: \"Deixa Meu povo ir para que possa Me adorar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Se tu recusares a deixá-lo ir, afligirei seu país inteiro com rãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'O rio se encherá com abundância de rãs que subirão na sua casa, no seu quarto e na sua cama. Elas entrarão nas casas dos teus servos; elas sobrevirão sobre teu povo, entrarão nos fornos e nas tuas amassadeiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'As rãs atacarão a ti, o teu povo e todos os teus servos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Yahweh disse a Moisés: \"Diz a Arão: \'Estende tua mão e teu cajado sobre os rios, os ribeiros e lagos e faz subir rãs sobre a terra do Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Arão estendeu sua mão sobre as águas do Egito e rãs vieram e cobriram toda terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Porém os mágicos fizeram o mesmo com suas mágicas: eles trouxeram rãs sobre a terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Faraó, então, chamou Moisés e Arão e lhes disse: \"Rogai a Yahweh para que Ele retire de mim e do meu povo as rãs. Depois disso, deixarei o povo ir para que possa oferecer sacrifício a Ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Moisés disse a Faraó: \"Eu te darei o privilégio de me dizeres quando devo rogar por ti, por teus servos e por teu povo, para que as rãs sejam retiradas de sobre vós e de vossas casas e continuem apenas sobre o rio\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Faraó respondeu: \"Amanhã\". Moisés disse-lhe: \"Seja feito de acordo com tuas palavras para que saibas que não existe nenhum outro como Yahweh, nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'As rãs fugirão de vós, de vossas casas, de vossos servos e do teu povo. Elas permanecerão apenas no rio\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Moisés e Arão saíram da presença de Faraó. Depois disso, Moisés clamou a Yahweh com relação às rãs que Ele havia trazido sobre Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Yahweh fez conforme Moisés pediu: as rãs morreram nas casas, nos quintais e nos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'O povo as recolheu em montes e pilhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Mas Faraó, ao ver o alívio, endureceu seu coração e não deu ouvidos ao que disseram Moisés e Arão, exatamente como Yahweh havia dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Yahweh disse a Moisés: \"Diz a Arão: \'Estende teu cajado e toca a poeira da terra para que ela faça surgir piolhos por toda a terra do Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Assim eles fizeram e Arão estendeu sua mão e seu cajado. Tocou ele no pó da terra e piolhos apareceram sobre homens e animais. Toda poeira do chão se transformou em piolhos, por toda a terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Os mágicos tentaram, por meio de suas magias, produzir piolhos, mas não foram capazes. Havia piolhos nas pessoas e nos animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Por causa disso, os mágicos disseram a Faraó: \"Isso é o dedo de Deus\". Porém o coração de Faraó se endureceu de maneira que ele se recusou a ouvi-los. Aconteceu exatamente de acordo com o que Yahweh dissera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Yahweh disse a Moisés: \"Levanta-te bem cedo, pela manhã, coloca-te diante de Faraó, quando ele sair até o rio, e diz-lhe: \'Yahweh diz o seguinte: \"Deixa meu povo sair para que Me adore.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Mas, se tu não o deixares ir, enviarei enxames de moscas sobre ti, sobre teus servos, tuas casas e teu povo. As habitações dos egípcios ficarão tomadas de enxames, até mesmo o chão onde eles pisam ficará tomado de moscas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Porém, naquele dia tratarei Gósen, a terra onde meu povo habita, de forma diferente, pois ali não haverá nenhum enxame de moscas. Acontecerá dessa forma para que tu saibas que Eu sou Yahweh no meio desta terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Farei distinção entre Meu povo e o teu povo. Este sinal do Meu poder acontecerá amanhã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Assim fez Deus, e enormes enxames de moscas entraram na casa de Faraó e nas habitações de seus servos. Toda a terra do Egito ficou arruinada por causa dos enxames de moscas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Faraó chamou Moisés e Arão e disse-lhes: \"Ide, oferecei sacrifício ao vosso Deus aqui na nossa própria terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Moisés disse: \"Não é correto para nós agirmos dessa maneira, pois os sacrifícios que nós oferecemos a Yahweh, nosso Deus, é algo repugnante aos egípcios. Se oferecermos sacrifícios diante deles, os quais são repugnantes aos egípcios, eles não nos apedrejarão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Não, nós devemos fazer uma jornada de três dias pelo deserto, a fim de oferecermos sacrifício a Yahweh, nosso Deus, assim como Ele nos ordenou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Faraó disse: \"Eu vos deixarei ir e oferecer sacrifício a Yahweh, vosso Deus, no deserto. Mas vós não podereis ir muito longe, e orai por mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Moisés disse: \"Assim que eu sair da tua presença, orarei a Yahweh para que Ele remova os enxames de moscas da tua casa, dos teus servos e do teu povo. Entretanto, tu não poderás mais usar de artimanhas para não deixar nosso povo ir para sacrificar a Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Moisés saiu da presença de Faraó e orou a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Fez Yahweh conforme Moisés pediu: removeu os enxames de moscas da casa de Faraó, dos seus servos e do seu povo. Não restou nenhuma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'No entanto, Faraó endureceu seu coração outra vez e não deixou o povo ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Então, Yahweh disse a Moisés: \"Vai a Faraó e dize-lhe: \'Yahweh, o Deus dos hebreus, diz: Deixa Meu povo ir para que eles possam Me adorar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Mas, se tu recusares a deixá-los ir, se tu ainda os retiverdes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'então, a mão de Yahweh será sobre seu gado nos campos e sobre seus cavalos, jumentos, camelos, bois, ovelhas, e isso causará um terrível desastre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Yahweh tratará o gado de Israel e o gado do Egito diferentemente. Nenhum animal que pertença aos israelitas será morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Yahweh tem fixado um tempo. Ele disse: Será amanhã que Eu farei estas coisas na terra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Yahweh fez isso no dia seguinte: todo o gado do Egito morreu. Mas nenhum dos animais dos israelitas morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Faraó investigou, e eis que nem mesmo um animal dos israelitas havia morrido. Mas seu coração estava obstinado e ele não deixou o povo ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Então, Yahweh disse a Moisés e a Arão: \"Tomai alguns punhados de cinzas do forno. Tu, Moisés, deves jogar as cinzas para o ar enquanto Faraó estiver vendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Elas se tornarão poeira fina sobre toda a terra do Egito. Elas causarão bolhas e feridas nas pessoas e animais de toda a terra do Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Então Moisés e Arão pegaram as cinzas do forno e se colocaram diante de Faraó. Moisés as jogou para o ar, e elas causaram bolhas e chagas que se estouravam nas pessoas e nos animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Os mágicos não puderam resistir a Moisés por causa das bolhas, que vieram sobre eles e sobre todos os outros egípcios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Yahweh endureceu o coração de Faraó, que não deu atenção a Moisés e a Arão. Conforme Yahweh havia dito a Moisés que Faraó faria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Então, Yahweh disse a Moisés: \"Acorda cedo pela manhã, aguarda em frente de Faraó e dize-lhe: \'Yahweh, o Deus dos hebreus, disse: Deixa Meu povo ir para que ele possa Me adorar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'pois Eu enviarei, neste tempo, todas as Minhas pragas sobre vós, sobre vossos servos e sobre vosso povo. Eu farei isto para que tu possas saber que não há quem Me seja semelhante em toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Por agora, Eu teria te alcançado com Minha mão e atacado a ti e a teu povo com doença e tu terias sido exterminado da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Mas foi por esta razão que Eu te permiti sobreviver, a fim de te mostrar o Meu poder, de modo que Meu nome seja proclamado em toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Ainda assim, tu estás te levantando contra Meu povo para não deixá-lo ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Ouve! Amanhã, por esta hora, Eu trarei uma tempestade de granizo muito forte, tal qual não se tenha visto no Egito desde o dia em que foi fundado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Agora, pois, envia homens e recolhe teu gado e tudo o que tens nos campos envia para um lugar seguro. A chuva de granizo cairá sobre cada homem e animal que estiver no campo, e aqueles que não forem levados para casa morrerão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Então, os servos de Faraó que acreditaram na mensagem de Yahweh apressaram-se em trazer seus escravos e gado para dentro das casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Mas aqueles que não acreditaram na mensagem de Yahweh deixaram seus escravos e gados nos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Então Yahweh disse a Moisés: \"Estende tua mão em direção ao céu, e cairá granizo em toda a terra do Egito: sobre as pessoas, sobre os animais e sobre todas as plantas nos campos, por todo o Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Moisés levantou sua vara em direção ao céu, e Yahweh enviou trovões, granizo e relâmpagos sobre a terra. Ele fez cair chuva de granizo sobre a terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Houve relâmpagos e pesado granizo como nunca havia sido visto em toda a terra do Egito, desde que tornou-se uma nação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Por toda a terra do Egito, a chuva de granizo feriu tudo nos campos, tanto pessoas como animais. Feriu todas as plantas dos campos e quebrou todas as árvores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Somente na terra de Gósen, onde viviam os israelitas, não houve chuva de granizo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Faraó enviou homens para chamar Moisés e Arão. Ele lhes disse: \"Eu pequei desta vez. Yahweh é justo e eu e meu povo somos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Orai a Yahweh, porque os fortes raios e a chuva de granizo são demais. Eu vos deixarei ir e vós não ficareis mais aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Moisés disse-lhe: \"Assim que eu deixar a cidade, estenderei minhas mãos a Yahweh. Os trovões cessarão e não haverá mais granizo. Desse modo, vós sabereis que a terra pertence a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Porém, quanto a ti e a teus servos, eu sei que realmente ainda não honrais a Deus Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'O linho e a cevada foram destruídos, pois a cevada estava amadurecendo na espiga e o linho, florescendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Mas o trigo e o centeio não foram prejudicados, porque eram colheitas posteriores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Quando Moisés saiu da presença de Faraó e da cidade, ele estendeu suas mãos para Yahweh e os trovões e as chuvas de granizo pararam, e a chuva não mais caiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Quando Faraó viu que a chuva de granizo e os trovões haviam cessado, ele pecou outra vez e endureceu seu coração junto com os seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'O coração de Faraó foi endurecido. Então, ele não deixou o povo de Israel ir. E isso foi como Yahweh dissera a Moisés que Faraó agiria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Yahweh disse a Moisés: \"Vai a Faraó, pois lhe endureci o coração e também o de seus subordinados. Fiz isso para mostrar, por meio de sinais, o Meu poder sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'Fiz isso também para que vós possais dizer aos vossos filhos e netos tudo o que tenho feito; como tenho zombado do Egito e como tenho enviado vários sinais do Meu poder sobre eles. Desse modo, vós sabereis que Eu Sou Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Então, Moisés e Arão foram até Faraó e lhe disseram: \"Yahweh, o Deus dos hebreus, disse isto: \'Por quanto tempo recusarás humilhar-te perante Mim? Deixa que Meu povo vá para que possa Me adorar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Mas, se te recusares a deixar Meu povo ir, ouve, amanhã Eu mandarei gafanhotos para tua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Eles cobrirão a superfície da terra de modo que ninguém poderá enxergar o chão. Eles comerão os restos de tudo o que tiver escapado à tempestade de granizo. Eles devorarão também todas as árvores que tiverem crescido nos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Eles encherão as casas, as dos subordinados, bem como todas as casas dos egípcios, algo nunca visto desde então\". E Moisés saiu da presença de Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Os conselheiros disseram a Faraó: \"Ainda, por quanto tempo esse homem nos ameaçará? Deixa que os israelitas partam para que possam adorar a Yahweh, seu Deus. Tu ainda não entendeste que o Egito está destruído?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Moisés e Arão, então, foram levados novamente à presença de Faraó, que lhes disse: \"Ide e adorai a Yahweh, o vosso Deus. Mas quem irá?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Disse Moisés: \"Iremos com os jovens e os velhos, com nossos filhos e filhas. Levaremos também nossas ovelhas e nossos bois, porque devemos festejar em honra a Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Faraó disse a eles: \"Esteja, de fato, Yahweh convosco, se eu deixar ir vós e vossas crianças. Vede, vós tendes alguma má intenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Ide, mas somente os homens, para adorar Yahweh, pois isso é o que quereis\". Então Moisés e Arão foram levados da presença de Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Yahweh disse a Moisés: \"Estenda tua mão sobre a terra do Egito para que os gafanhotos possam atacar esta terra e devorar tudo, todas as coisas que não foram consumidas pela tempestade de granizo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Moisés estendeu seu cajado sobre a terra do Egito, e Yahweh mandou um vento forte sobre a terra, vindo do leste, durante todo o dia e toda a noite. Quando amanheceu, o vento do leste trouxe os gafanhotos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Os gafanhotos se espalharam por toda a terra do Egito. Algo assim nunca havia sido visto antes e nunca será novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Eles cobriram toda a supefície da terra, tornando-a escura; e devoraram toda a plantação e também os frutos das árvores que a tempestade de granizo não havia destruído. Por toda a terra do Egito, nenhuma vegetação resistiu, nem planta alguma permaneceu nos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Então Faraó rapidamente convocou Moisés e Arão e lhes disse: \"Pequei contra Yahweh, o vosso Deus, e contra vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Agora, então, perdoai a mim e rogai a Yahweh, para que Ele leve a morte para longe de mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Moisés saiu da presença de Faraó e orou a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Yahweh enviou uma tempestade com ventos fortes vindos do leste, lançando os gafanhotos no Mar Vermelho. Nenhum gafanhoto permaneceu em território Egípcio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Mas Yahweh endureceu ainda mais o coração de Faraó, e este não permitiu que os Israelitas saíssem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Então, Yahweh disse a Moisés: \"Estenda tua mão ao céu para que haja escuridão em toda a terra do Egito, trevas que poderão ser sentidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Moisés, então, estendeu sua mão ao céu, e vieram densas trevas sobre toda a terra do Egito por três dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Ninguém mais pode ver ninguém. E ninguém podia sair de casa durante esses três dias. Entretanto, havia luzes em todos os lares israelitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Faraó mandou chamar Moisés e disse: \"Ide e adorai a Yahweh. Até mesmo vossas famílias poderão ir convosco, mas vossas ovelhas e bois deverão permanecer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mas Moisés disse: \"Tu também deves dar-nos animais para sacrifício e holocausto em oferecimento a Yahweh, nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Nossos rebanhos também irão conosco, e nenhum casco deverá ser deixado para trás, porquanto devemos oferecê-los a Yahweh. Porque não sabemos com o que haveremos de adorar Yahweh, nosso Deus, até que cheguemos lá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Mas Yahweh continuou a endurecer o coração de Faraó, que não permitiu que os povo de Israel fosse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Faraó disse a Moisés: \"Afasta-te da minha presença! Presta atenção a uma coisa: que tu não me vejas novamente, pois no dia em que vires a minha face morrerás\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Moisés disse: \"É como tu mesmo disseste: eu não verei tua face outra vez\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Então, Yahweh disse a Moisés: \"Há ainda mais uma praga que Eu trarei sobre Faraó e o Egito. Depois disso, ele vos deixará ir. Quando, finalmente, ele vos deixar partir, ele vos expulsará completamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Instrui o povo dizendo que todo homem e toda mulher devem pedir a seu vizinho ou vizinha artigos de prata e ouro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Yahweh havia tornado os egípcios ansiosos em satisfazer os israelitas. Além disso, aos olhos dos servos de Faraó e do povo do Egito, o homem Moisés era muito importante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Moisés disse: \"Assim diz Yahweh: \'Por volta da meia noite, Eu passarei pelo Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Todos os primogênitos na terra do Egito morrerão, desde o primogênito de Faraó, que assenta em seu trono, até o primogênito da escrava que trabalha no moinho, e os primogênitos de todos os rebanhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Então, por toda a terra do Egito, haverá uma grande lamentação como nunca houve antes e como nunca haverá novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Mas, nem mesmo um cachorro latirá contra o povo de Israel; nem contra homem, tampouco contra animais dos rebanhos. Dessa forma, sabereis que Eu estou tratando os egípcios e os israelitas distintamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Todos os teus servos, Faraó, descerão a Mim, e se curvarão perante Mim. Eles dirão: \'Vai, tu e todo o povo que te segue!\' Depois disso, eu partirei\"\'. Então ele saiu da presença de Faraó com grande ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Yahweh disse a Moisés: \"Faraó não te ouvirá. Para que Eu possa fazer muitas coisas prodigiosas na terra do Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Moisés e Arão fizeram todos esses prodígios diante de Faraó. Porém, Yahweh endureceu o coração de Faraó, que não permitiu que o povo de Israel deixasse sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Yahweh falou a Moisés e a Arão na terra do Egito, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '\"Para vós, este primeiro mês será o início dos meses, o primeiro mês do ano para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Diz à assembleia de Israel: \'No décimo dia deste mês, cada um de vós deve tomar um cordeiro ou um cabrito; cada família fará isso, um cordeiro para cada família.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Se a família for pequena para um cordeiro, o homem e seu vizinho do lado comerão a carne de um cordeiro ou cabrito que for suficiente, conforme o número de pessoas. Deverá ser suficiente para todos que comerem; assim, eles deverão tomar carne suficiente para alimentar a todos vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Vosso cordeiro ou cabrito deverá ser sem mácula, um macho de um ano. Tomareis um cordeiro ou cabrito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Devereis guardá-lo até o décimo quarto dia do mês. Então, toda a assembleia de Israel deverá matar cada animal ao cair da tarde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Pegareis uma parte do sangue, e a colocareis nos dois umbrais e na parte superior da porta das casas, nas quais irão o animal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Naquela noite, comereis a carne, depois de tê-la, primeiro, assado ao fogo. Comereis com pão feito sem fermento, juntamente com ervas amargas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Não o comereis cru ou cozido em água. Ao invés disso, assá-lo-eis ao fogo, com a cabeça, as pernas e as partes internas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Não deixareis sobrar nada para a manhã seguinte. Queimareis tudo quanto sobrar até de manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Assim é como comereis: com o cinto apertado, sapatos nos pés e cajado na mão. Comereis apressadamente. Esta é a Páscoa de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Yahweh disse: \"Passarei na terra do Egito naquela noite, e ferirei todos os primogênitos dos homens e dos animais na terra do Egito. Punirei todos os deuses do Egito. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'O sangue será um sinal para Me mostrar as suas casas. Quando Eu vir o sangue, passarei por cima de vós, quando ferir a terra do Egito. Essa praga não virá sobre vós e não vos destruirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Esse dia se tornará um memorial para vós, o qual devereis observar como uma festividade para Yahweh. Será sempre uma lei para vós, através de todas as gerações, devereis observar este dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Comereis pães sem fermento durante sete dias. No primeiro dia, removereis o fermento de vossas casas. Qualquer que comer pão fermentado do primeiro até o sétimo dia deverá ser cortado de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'No primeiro dia, haverá uma assembleia que será dedicada ao Meu nome e no sétimo dia haverá outro ajuntamento semelhante. Nenhum trabalho será feito nesses dias, exceto o cozimento, para que todos possam comer. Somente esse trabalho deverá ser feito por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Observareis essa celebração dos pães sem fermento, porque nesse dia trarei vossos exércitos para fora da terra do Egito. Assim, observareis esse dia por todas as gerações. Será uma lei para vós, para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Comereis pães sem fermento desde o cair da tarde do décimo quarto dia do primeiro mês do ano até o cair da tarde do vigésimo primeiro dia do mesmo mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Durante esses sete dias, nenhum fermento deverá ser encontrado em vossas casas. Qualquer que comer pão com fermento será cortado da comunidade de Israel, seja essa pessoa um estrangeiro ou alguém nascido em vossa terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nada feito com fermento deverá ser comido. Onde quer que viverdes, comereis pão feito sem fermento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Então, Moisés convocou todos os anciãos de Israel e disse-lhes: \"Ide e escolhei os cordeiros que sejam suficientes para alimentar vossas famílias, e sacrificai o cordeiro da Páscoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Então, tomai um ramo de hissopo e mergulhai-o no sangue que estará numa bacia. Aspergireis o sangue da bacia no topo das portas e nos umbrais. Nenhum de vós sairá da porta da vossa casa até o amanhecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Porque Yahweh passará para ferir os egípcios. Quando Ele vir o sangue no topo das vigas da porta e dos umbrais, passará por cima da vossa porta e não permitará que o destruidor entre nas vossas casas para ferir-vos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Observareis isso para sempre, como uma lei para vós e vossos descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Quando entrardes na terra que Yahweh vos dará, como Ele prometeu fazer, observareis esse ato de adoração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Quando vossos filhos vos perguntarem: \'O que significa este ato de adoração?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Então direis: \'Este é o sacrifício da Páscoa de Yahweh, porque Yahweh passou por cima das casas dos israelitas no Egito, quando feriu de morte os egípcios. Ele libertou nossas famílias\'\". Então, o povo prostou-se e adorou a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Os israelitas foram e fizeram exatamente conforme Yahweh tinha ordenado a Moisés e Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Aconteceu que, à meia noite, Yahweh feriu de morte todos os primogênitos na terra do Egito, desde o primogênito do Faraó, o qual se assentava em seu trono, como também o primogênito do prisioneiro e todos os primogênitos dos rebanhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Faraó levantou-se à noite — ele, todos os seus servos e todos os egípcios. Houve grande lamento no Egito, pois não havia casa alguma onde não houvesse alguém morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'À noite, o Faraó convocou Moisés e Arão, e disse: \"Levantai-vos, saí do meio do meu povo, vós e os israelitas. Ide, adorai a Yahweh, conforme pedistes e queríeis fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Levai vossos rebanhos e gados, como dissestes, ide e também abençoai-me.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Os egípcios estavam com grande pressa para expulsá-los da terra, pois diziam: \"Vamos todos morrer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Então o povo tomou suas massas sem nenhum fermento adicionado. Suas amassadeiras já estavam amarradas a suas roupas e em seus ombros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'O povo de Israel fez conforme Moisés tinha dito. Foram pedidos aos egípcios os objetos de prata e ouro, como também roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Yahweh fez com que os egípcios desejassem agradar aos israelitas. Então, os egípcios deram qualquer coisa que fosse pedida por eles. Dessa forma, os israelitas despojaram os egípcios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Os israelitas viajaram de Ramessés a Sucote. Eram cerca de seiscentos mil homens a pé, sem contar as crianças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Uma multidão misturada de estrangeiros também foi com eles, junto com seus rebanhos e gados, um número muito grande.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Assaram pães sem fermento com a massa que eles trouxeram do Egito. Os pães estavam sem fermento porque tinham saído do Egito e não podiam se atrasar com o preparo da comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Os israelitas tinham habitado no Egito por quatrocentos e trinta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'No final dos quatrocentos e trinta anos, naquele mesmo dia, todos os exércitos de Yahweh saíram da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Essa foi uma noite para ficar acordado, pois Yahweh os tirou da terra do Egito. Essa foi a noite de Yahweh, para ser observada por todos os israelitas através de todas as suas gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Yahweh disse a Moisés e Arão: \"Aqui está a regra para a Páscoa: nenhum estrangeiro comerá dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'No entanto, todo escravo israelita comprado por dinheiro poderá comer após ter sido circuncidado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Estrangeiros e servos assalariados não deverão comer nada dessa comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'A refeição deverá ser comida na sua própria casa. Não levareis nenhuma carne para fora da casa, e não quebrareis osso algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Toda a comunidade de Israel deverá observar a celebração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Se um estrangeiro viver entre vós e quiser participar da Páscoa para Yahweh, todos os seus parentes homens deverão ser circuncidados. Então ele poderá celebrá-la. Ele se tornará como uma pessoa nativa. Contudo, nenhum incircunciso poderá comer dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Essa mesma lei será aplicada tanto para o nativo quanto para o estrangeiro que vive entre vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Assim, todos os israelitas fizeram exatamente como Yahweh tinha ordenado a Moisés e Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Isso aconteceu no mesmo dia em que Yahweh tirou Israel da terra do Egito, conforme seus exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Yahweh falou para Moisés e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '\"Dedica para Mim todo o primogênito, todo macho entre os israelitas, tanto homens, como animais. O primogênito Me pertencerá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Moisés disse ao povo: \"Trazei à memória este dia, o dia em que saístes do Egito - da casa da escravidão - pela mão poderosa de Yahweh, que vos tirou desse lugar. Não podereis comer pão fermentado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Vós saireis do Egito neste dia, no mês de Abibe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Quando Yahweh vos trouxer para a terra dos cananeus, heteus, amorreus, heveus e jebuseus, a terra que Ele jurou aos vossos ancestrais que vos daria, uma terra que mana leite e mel — então devereis observar este ato de adoração neste mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Por sete dias, devereis comer pão sem fermento; ao sétimo dia, harevá uma festa em honra a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Pão sem fermento deverá ser consumido durante os sete dias; nenhum pão com fermento deverá ser visto entre vós. Nenhum fermento deverá ser encontrado entre vós, dentro de vossas fronteiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Naqueles dias, direis aos vossos filhos: \'Isto é pelo que Yahweh fez por mim quando saí do Egito\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Isso será como lembrete na vossa mão e como lembrete na vossa fronte. Por isso a lei de Yahweh deverá estar em vossa boca, pois, com forte mão, vos trouxe do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Portanto devereis guardar essas leis ano após ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Quando Yahweh vos trouxer para terra dos cananitas, como Ele jurou a vós e a vossos ancestrais que iria fazer, e quando Ele vos der a terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'devereis separar para Ele todo primogênito, tanto dos homens quanto dos animais. Os machos serão para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Cada primogênito de jumento vós devereis comprar novamente com um cordeiro. Se não o comprardes novamente, então devereis lhe quebrar o pescoço. Porém, cada um dos vossos primogênitos machos entre todos os vossos filhos — devereis comprá-los novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Quando vosso filho vos perguntar mais tarde, \'O que isso significa?\' então lhe direis: \'Foi pela Sua forte mão que Yahweh nos tirou do Egito, da casa da escravidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Quando Faraó, obstinadamente, recusou-se a nos deixar sair, Yahweh matou todos os primogênitos na terra do Egito, tanto os primogênitos de pessoas e como os primogênitos dos animais. Por isso, eu sacrifico a Yahweh todo primogênito macho de todo animal, e por isso eu compro novamente os primogênitos entre meus filhos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Isso será um lembrete em suas mãos, e um lembrete em sua testa, pois foi com forte mão que Yahweh nos tirou do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Quando Faraó deixou o povo ir, Deus não os guiou pela terra dos filisteus, ainda que fosse o caminho mais próximo. Pois Deus disse: \"Talvez o povo mude de ideia quando vivenciar a guerra, e então retornará para o Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Então, Deus guiou o povo ao redor do deserto para o Mar Vermelho. Os israelitas subiram para fora do Egito armados para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Moisés levou os ossos de José consigo, pois José fez os israelitas jurarem solenemente e dizer: \"Deus certamente vos resgatará, e vós devereis levar meus ossos consvosco.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Os isrelitas viajaram de Sucote e acamparam em Etã, às margens do deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Yahweh ia diante deles durante o dia, em uma coluna de nuvem para guiá-los pelo caminho. Pela noite, Ele ia como coluna de fogo para dar a eles a luz. Assim, eles puderam viajar durante o dia e durante a noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Yahweh não retirou de diante do povo a coluna de nuvem para o dia, nem a coluna de fogo para a noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Deus falou a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '\"Dize aos israelitas que eles devem retornar e acampar diante de Pi Hairote, entre Migdol e o mar, antes de Baal Zefom. Vós acampareis junto ao mar, oposto a Pi Hairote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Faraó dirá sobre vós, israelitas, \'Eles estão vagando pela terra. Ficaram presos no deserto\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Eu endurecerei o coração de Faraó, e ele os perseguirá. Serei honrado por causa de Faraó e seu exército. Os egípcios saberão que Eu sou Yahweh.\" Então os israelitas acamparam como haviam sido instruídos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Quando o rei do Egito foi informado de que os israelitas haviam fugido, os pensamentos de Faraó e de seus servos voltaram-se contra o povo. Eles disseram: \"O que fizemos nós, deixando Israel livre de nos servir?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Então Faraó preparou suas carruagens e tomou seu exército com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Tomou seiscentas carruagens selecionadas e outras carruagens do Egito, todas com seus oficiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Yahweh endureceu o coração de Faraó, rei do Egito, e o rei perseguiu os israelitas. Os israelitas haviam saído triunfantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Mas os egípcios os perseguiram, com seus cavalos e carruagens, seus cavaleiros e seu exército. Eles alcançaram os israelitas no acampamento junto ao mar, ao lado de Pi Hairote, antes de Baal Zefom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Quando Faraó se aproximou, os israelitas olharam e ficaram surpresos. Os egípcios estavam marchando atrás deles; e ficaram apavorados. Os israelitas clamaram a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Eles disseram a Moisés: \"É porque não havia túmulos no Egito que nos trouxeste para morrer no deserto? Por que nos trataste assim, tirando-nos do Egito?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Não foi isso o que te dissemos? Nós te dissemos: \'Deixa-nos em paz, então poderemos servir aos egípcios. Teria sido melhor para nós trabalhar para eles do que morrer no deserto\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Moisés disse ao povo: \"Não temais. Permanecei firmes e vede o livramento que Yahweh proverá para vós hoje. Pois nunca mais vereis novamente os egípcios que vedes hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Yahweh lutará por vós, apenas permanecereis firmes\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Então Deus disse a Moisés: \"Moisés, por que continuas clamando a mim? Dize aos israelitas para irem em frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Levanta o teu cajado, estende a tua mão sobre o mar e divide-o em dois, para que o povo de Israel atravesse o mar em terra seca. Sabe que endurecerei os corações dos egípcios, para os perseguir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Serei honrado por causa de Faraó e todo seu exército, suas carruagens e seus cavaleiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Então os egípcios saberão que Eu sou Yahweh quando Eu for honrado por causa de Faraó, suas carruagens e seus cavaleiros.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'O anjo de Deus, que ia à frente dos israelitas, foi para trás deles. A coluna de nuvem, que ia à frente deles, ficou atrás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'A nuvem ficou entre o acampamento dos egípcios e o acampamento dos israelitas. E era uma nuvem escura para os Egípcios, mas iluminava a noite para os Israelitas. Então um lado não se aproximou do outro durante toda noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Moisés estendeu sua mão sobre o mar. Com um forte vento oriental, durante toda aquela noite, Yahweh recolheu e dividiu as águas do mar, tornando-o terra seca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Os Israelitas atravessaram pelo meio do mar em solo seco. As águas formaram uma muralha para eles, tanto do seu lado direito quanto do lado esquerdo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Os egípcios os perseguiram. Eles foram atrás dos israelitas para o meio do mar - com todos os cavalos, carruagens e cavaleiros de Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Mas, ao amanhecer, Yahweh impediu o exército egípcio através da coluna de fogo e da nuvem. Ele trouxe pânico entre os egípcios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'As rodas de suas carruagens ficaram travadas, e seus cavaleiros guiavam com dificuldade. Então os egípcios disseram: \"Vamos fugir de Israel, porque Yahweh está lutando a favor deles e contra nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Yahweh disse a Moisés: \"Estende tua mão sobre o mar para que as águas voltem sobre os egípcios, suas carruagens e cavaleiros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Então Moisés estendeu sua mão sobre o mar, e as águas voltaram ao curso normal quando amanheceu. Os egípcios tentaram fugir de dentro do mar, mas Yahweh lançou-os para o meio dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'As águas voltaram e cobriram as carruagens, os cavaleiros de Faraó e seu exército inteiro que tinha seguido as carruagens até o mar. Ninguém sobreviveu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'No entanto os israelitas caminharam por terra seca no meio do mar. As águas eram uma muralha para eles, tanto do lado direito quanto do esquerdo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Assim Yahweh livrou Israel das mãos dos egípcios naquele dia, e Israel viu os corpos deles à beira-mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Quando Israel viu o grande poder que Deus usou contra os egípcios, o povo honrou a Yahweh e confiou em Deus e em seu servo Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Então, Moisés e o povo de Israel entoaram esta canção a Deus. Eles cantaram: \"Eu louvo a Yahweh, pois Ele triunfou gloriosamente; o cavalo e seu cavaleiro, Ele lançou ao mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Yahweh é minha força e canção, Ele se tornou minha salvação. Este é meu Deus e eu O louvarei, o Deus de meu pai, e eu O exaltarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Yahweh é um guerreiro. Yahweh é o Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Ele lançou ao mar as carruagens de Faraó e seu exército. Os oficiais escolhidos de Faraó foram lançados ao Mar Vermelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'As profundezas os cobriram, desceram às profundezas como pedras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Tua mão direita, Yahweh, é gloriosa em poder; Tua mão direita, Yahweh, esmagou o inimigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Em grande majestade, Tu venceste aqueles que se levantaram contra Ti. Tu enviaste a Tua ira e ela os consumiu como palha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Pelo sopro de Tuas narinas, as águas se amontoaram; as águas correntes se levantaram; as águas profundas se congelaram no coração do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'O inimigo disse: \'Eu o perseguirei, eu vencerei, eu dividirei os despojos; meu desejo será satisfeito neles; eu conduzirei minha espada; minha mão os destruirá.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Mas Tu sopraste com o Teu vento, e o mar os cobriu; eles afundaram em poderosas águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Quem entre os deuses é como Tu, Yahweh? Quem é como Tu, majestoso em santidade, honrado em louvores, operando milagres?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Tu os alcançaste com Tua mão direita e a terra os tragou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Em Tua leal aliança, guiaste o povo que resgataste. Em Tua força, o guiaste para o santo lugar onde Tu vives.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Os povos ouvirão e tremerão; o terror alcançará os habitantes da Filístia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Então, os líderes de Edom temerão, os soldados de Moabe tremerão; todos os habitantes de Canaã se abalarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Terror e pavor virão sobre eles; pela força do Teu braço, eles se tornarão como pedra até que Teu povo passe, Yahweh, até que o povo que Tu resgataste tenha atravessado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Tu os trarás e os plantarás no monte de Tua herança, o lugar, Yahweh, que Tu fizeste para habitares, o santuário, nosso Deus, que Tuas mãos construíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Yahweh reinará para sempre e sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Pois os cavalos de Faraó entraram com suas carruagens e cavaleiros no mar. Yahweh derramou de volta as águas do mar por sobre eles. Porém os Israelitas caminharam por terra seca, no meio do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Miriam, a profetisa, irmã de Arão, tomou um tamborim e, com ela, todas as mulheres vieram com tamborins, dançando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Miriam cantou para elas: \"Cantai ao SENHOR, pois Ele triunfou gloriosamente. O cavalo e seu cavaleiro Ele lançou ao mar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Então desde o Mar Vermelho, Moisés guiou Israel adiante. Eles atravessaram pelo deserto de Sur. Viajaram três dias pelo deserto e não encontraram água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Então chegaram a Mara, mas não puderam beber a água de lá, pois era amarga. Por isso chamaram aquele lugar de Mara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Então o povo murmurou contra Moisés dizendo: \"O que podemos beber?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Moisés clamou a Yahweh, e Yahweh lhe mostrou um tronco de árvore. Moisés o lançou às águas, e elas se tornaram doces para beber. Foi nesse lugar que Yahweh lhes deu uma lei estrita e foi ali que Ele os testou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Ele disse: \"Se atentamente ouvirdes a Minha voz, Eu, Yahweh, o vosso DEUS, e fizerdes o que for correto aos Meus olhos - e se observardes os Meus mandamentos e obedecerdes às Minhas leis, não porei sobre vós nenhuma das aflições que Eu fiz cair sobre os egípcios; pois Eu sou Yahweh, aquele que vos cura.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Então o povo chegou até Elim, onde havia doze nascentes de água e setenta palmeiras. Eles acamparam junto das águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'O povo viajou de Elim, e toda a comunidade dos israelitas veio para o deserto de Sim, que fica entre Elim e Sinai, no décimo quinto dia do segundo mês, depois de partirem da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Toda a comunidade dos israelitas murmurou contra Moisés e Arão no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Os israelitas lhes disseram: \"Se ao menos tivéssemos morrido pela mão de Yahweh na terra do Egito, enquanto nos assentávamos perto das panelas de carne e comíamos pão até nos fartarmos? Pois vós nos trouxestes para este deserto, para matar toda a nossa comunidade de fome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Então, Yahweh disse a Moisés: \"Eu farei chover pão do céu sobre vós. O povo sairá e recolherá uma porção diária. Este será Meu teste para ver se eles andarão ou não na Minha lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Isto acontecerá no sexto dia: recolherão duas vezes mais do que recolheram nos outros dias, e cozinharão o que eles trouxerem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Então Moisés e Arão disseram para todo o povo de Israel: \"Ao anoitecer, vós sabereis que é Yahweh quem vos tirou da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'E, pela manhã, vós vereis a glória de Yahweh, pois Ele ouviu vossas murmurações contra Ele. Quem somos nós para que vós reclameis contra nós?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Moisés também disse: \"Vós sabereis quando Yahweh vos der carne ao anoitecer e, pão pela manhã para vos saciardes, pois Ele ouviu vossas murmurações contra Ele. Quem somos Arão e Eu? Vossas murmurações não são contra nós; são contra Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Moisés disse a Arão: \"Diga a toda a comunidade do povo de Israel: \"Aproximai-vos perante Yahweh, pois Ele tem ouvido vossas queixas.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Enquanto Arão falava para toda a comunidade do povo de Israel, eles olharam para o deserto e eis que a glória de Yahweh apareceu na nuvem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Depois, Yahweh falou a Moisés e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '\" Eu tenho ouvido as queixas do povo de Israel. Fale com eles e lhes diga: \'À noite, vós comereis carne, e, pela manhã, sereis saciados com pão. Então, vós sabereis que Eu sou o Yahweh, vosso Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'E aconteceu que, naquela noite, codornas vieram e cobriram o acampamento. De manhã, o orvalho caiu em volta do acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Quando o orvalho se foi, viram que, pelo chão do deserto, havia algo pequeno e redondo, como a geada no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Quando os israelitas viram isso, disseram uns aos outros: \"O que é isso?\" Eles não sabiam o que era. Moisés lhes disse: \"É o pão que Yahweh vos tem dado para comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Este é o mandamento que Yahweh tem dado: \'Vós tendes de guardar, cada um de vós, a porção que vos é necessária para comer: um ômer por pessoa, segundo o número do povo. É assim que fareis: juntai o suficiente para comer para cada pessoa que vive em sua tenda.\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'E o povo de Israel assim o fez. Alguns juntaram mais e outros, menos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Quando mediram isso com a medida do ômer, aqueles que haviam juntado mais não tinham nenhuma sobra, e aqueles que haviam juntado menos nada lhes faltou. Cada pessoa juntou o suficiente para suas necessidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Então Moisés lhes disse: \"Ninguém deve guardar para amanhã\". Entretanto, eles não escutaram a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Alguns deles guardaram para o dia seguinte, mas surgiram vermes e o pão se tornou detestável. Moisés ficou irado com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Eles o guardavam manhã após manhã. Cada pessoa juntava o suficiente para comer naquele dia. E o alimento se derretia, quando o sol ficava mais forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'E aconteceu que, no sexto dia, eles reuniram duas vezes mais pão, dois ômeres por cada pessoa. Todos os líderes da comunidade vieram e contaram isso a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Ele lhes disse: \"Isso é o que Deus disse: \'Amanhã é o descanso, o sábado santo em honra a Deus. Cozinhai o que quiserdes cozinhar, fervei o que quiserdes ferver. Tudo o que sobrar, guardai para vós até a manhã seguinte\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Então, eles os guardaram até pela manhã, como Moisés os instruiu. E não se tornou podre, nem criou vermes neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Moisés disse: \"Comei esta comida hoje, pois hoje é um dia reservado, o sábado, para honrar a Yahweh. Hoje não encontrareis comida nos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Reunireis isso durante seis dias, mas o sétimo é o dia do sábado. No sábado, não haverá maná\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'E aconteceu que, no sétimo dia, algumas pessoas saíram em busca do maná, porém nada encontraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Então, Yahweh disse a Moisés: \"Por quanto tempo vos recusareis a manter Meus mandamentos e Minhas leis?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Vede, Eu, Yahweh tenho vos dado o descanso. Então, no sexto dia, vos darei pão por dois dias. Cada um de vós ficará em sua morada, ninguém deverá sair de sua casa, no sétimo dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Então, o povo descansou no sétimo dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'O povo de Israel chamou o alimento de \"maná\". Era branco como a semente de coentro, e tinha o gosto como de pão feito com mel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Moisés lhes disse: \"Isso é o que Yahweh tem ordenado: \'Deixai um ômer de maná guardado para as gerações de vosso povo, para que vossos descendentes vejam o pão com que Eu vos alimentei no deserto, depois que vos tirei da terra do Egito\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Moisés disse a Arão: \"Pega um pote e coloca um ômer de maná dentro. Guarda isso perante Yahweh para as gerações do nosso povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Assim como Yahweh ordenou a Moisés, Arão guardou, ao lado do decreto da aliança, na arca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'O povo de Israel comeu o maná por quarenta anos, até chegarem à terra habitada. Eles comeram até chegarem à fronteira da terra de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Um ômer é a décima parte de um efa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Toda a comunidade dos israealitas partiu do deserto de Sim, seguindo as instruções de Yahweh. Eles acamparam em Refidim, mas lá não havia água para as pessoas beberem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Então, o povo culpou Moisés pela sua situação e lhe disse: \"Dá-nos água para beber\". Moisés disse: \"Por que vós reclamais? Por que vós testais a Deus?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'As pessoas estavam muito sedentas e elas se queixaram contra Moisés. Disseram: \"Por que tu nos tiraste do Egito? Para nos matar de sede, nossas crianças e nossos rebanhos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Então, Moisés clamou a Yahweh: \"O que eu deveria fazer com este povo? Eles estão prontos para me apedrejar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Yahweh disse a Moisés: \"Vai à frente dessas pessoas e leve contigo alguns anciãos de Israel. Leva também a vara com a qual feristes o rio e vai tu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Eu estarei diante de ti sobre a rocha no Horebe, e tu irás bater na rocha. Água sairá dela para o povo beber\". Então Moisés fez desta maneira à vista dos anciãos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Ele chamou aquele lugar de Massá e Meribá, devido às queixas dos israelitas, e porque eles testaram o Senhor dizendo: \"Está Yahweh entre nós ou não?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Então, o exército dos amalequitas veio e atacou Israel em Refidim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Assim, Moisés disse a Josué: \"Escolhe alguns homens e sai para lutar com os amalequitas. Amanhã, eu estarei no topo do monte com a vara de Deus em minha mão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Então, Josué fez como foi instruído e lutou contra os amalequitas, enquanto Moisés, Arão e Hur estavam no topo do monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Enquanto Moisés mantinha as mãos levantadas, Israel vencia; quando ele deixava suas mãos descansarem, os amalequitas começavam a vencer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Quando as mãos de Moisés ficaram pesadas, Arão e Hur pegaram uma pedra e a colocaram debaixo dele para que sentasse. Ao mesmo tempo, Arão e Hur mantinham suas mãos levantadas, um de um lado e outro de outro. Assim, as mãos de Moisés ficaram levantadas até o sol se pôr.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Dessa forma, Josué derrotou os amalequitas com a espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Deus disse a Moisés: \"Escreve isso em um livro e lê para Josué ouvir, porque Eu irei apagar a memória dos amalequitas de debaixo dos céus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Então, Moisés construiu um altar e o chamou de \"Yahweh é a minha bandeira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Ele fez isso, porque ele disse: \"Yahweh jurou que Ele irá guerrear contra Amaleque de geração em geração\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Jetro, o sacerdote de Midiã, sogro de Moisés, ouviu tudo o que Deus tinha feito a Moisés e ao seu povo Israel. Ele ouviu que Yahweh tirou Israel do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Jetro, sogro de Moisés, levou Zípora, esposa de Moisés, depois que ele a tinha enviado a sua casa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'e os seus dois filhos; o nome de um de seus filhos foi Gérson, pois Moisés disse: \"Eu fui peregrino em terra estranha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'O nome do outro foi Eliézer, pois Moisés disse: \"O Deus dos meus antepassados foi a minha ajuda. Ele me resgatou da espada de Faraó\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Jetro, sogro de Moisés, foi com os filhos de Moisés e a sua mulher para o deserto onde ele estava acampado no monte de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Ele disse para Moisés, \"Eu, teu sogro Jetro, estou indo ao teu encontro com a tua mulher e os teus dois filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Moisés saiu para encontrar o seu sogro, inclinou, e o beijou. Eles perguntaram um ao outro como estavam e, em seguida, foram à tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Moisés disse ao seu sogro tudo o que Yahweh havia feito ao faraó e aos egípcios por amor a Israel, acerca de todas as dificuldades enfrentadas no caminho e de como Yahweh os livrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Jetro alegrou-se com todas as coisas que Yahweh fez para o povo de Israel, e que Ele os resgatou das mãos dos egípcios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Jetro disse: \"Louvado seja Yahweh que vos livrou dos egípcios e das mãos de Faraó, e vos deixou livre de seu controle.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Agora, sei que Deus é maior do que todos os deuses, porque, quando os egípcios trataram arrogantemente os Iraelitas, Deus os resgatou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Jetro, sogro de Moisés, apresentou a Deus sacrifícios e holocautos. Arão e todos os anciãos de Israel vieram comer com o sogro de Moisés na presença de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'No dia seguinte, Moisés sentou-se para julgar o povo. O povo ficou à volta dele desde a manhã até à noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Quando o sogro de Moisés viu tudo o que ele fez para o povo, disse, \"O que é isso que estás fazendo com o povo? Por que estás sentado sozinho e o povo fica em tua volta desde a manhã até à noite\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Moisés disse ao seu sogro: \"As pessoas vêm até a mim para perguntar a direção de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Quando elas têm uma discussão, vêm a mim. Eu decido entre uma pessoa e outra, e lhes ensino os estatutos e as leis de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'O sogro de Moisés disse a ele: \"O que tu estás fazendo não é muito bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Certamente, desfalecerás tu e o teu povo que está contigo, porque o fardo é pesado demais para ti. Não podes fazer sozinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Ouve-me. Vou dar-te um conselho, e Deus será contigo, porque tu és para Deus o representante do povo, e levas as discussões deles a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Deves ensinar-lhes os estatutos Dele e as leis. Deves lhes mostrar o jeito de andar e o trabalho para fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Além disso, deves escolher homens, que honram a Deus, homens de confiança que odeiam o lucro injusto. Deves colocá-los acima das pessoas, para serem líderes de mil, cem, cinquenta e chefe de dez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Eles julgarão as pessoas em todos os casos, mas os casos difíceis eles trarão a ti. E todos os pequenos casos, eles podem julgá-los. Desse jeito, será fácil para ti, e eles carregarão o fardo contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Se fizeres isso, e se também Deus guiar-te, então estarás capacitado para suportar, e o povo estará pronto para irem para casa satisfeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Então, Moisés ouviu as palavras de seu sogro e fez tudo que ele tinha dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Moisés escolheu homens capazes de todo Israel e os colocou como cabeças sobre o povo, líderes responsáveis de mil, cem, cinquenta e líderes de dez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Eles julgaram o povo em circunstâncias normais. Os casos difíceis eles levaram para Moisés, mas eles mesmo julgaram os pequenos casos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Então, Moisés deixou o seu sogro, e Jetro voltou para sua própria terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'No terceiro mês depois de o povo israelita ter deixado a terra do Egito, naquele mesmo dia, eles voltaram para o deserto do Sinai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Depois de saírem de Refidim, eles acamparam no deserto do Sinai, em frente do monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Moisés subiu até Deus. Yahweh o chamou para a montanha e disse: \"Vós deveis falar à casa de Jacó, ao povo de Israel:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Vós tendes visto o que Eu fiz com os egípcios, como Eu vos carreguei nas asas das águias e vos trouxe para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Agora, portanto, se ouvirdes atentamente a Minha voz e guardardes a Minha aliança, sereis Minha propriedade exclusiva dentre todos os povos, porque toda a terra é Minha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Vós sereis reino de sacerdotes e a nação santa para Mim. Essas são as palavras que falarás ao povo de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Então Moisés voltou e convocou os anciãos do povo. Ele lhes apresentou todas as palavras que Yahweh havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Todo o povo respondeu dizendo: \"Nós faremos tudo o que Yahweh ordenou.\" Então, Moisés voltou a comunicar as palavras do povo para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Yahweh disse a Moisés: \"Virei a ti em uma nuvem espessa para que o povo Me ouça falar contigo e sempre creia em ti\". Então, Moisés falou as palavras do povo a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Yahweh disse para Moisés: \"Vá até o povo. Hoje e amanhã santificai-o para Mim, e faça com que lavem as próprias roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Estai prontos para o terceiro dia, porque, no terceiro dia, Eu, Yahweh, voltarei ao monte Sinai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Tu definirás todos os limites ao redor do monte para o povo. Dize a eles: \'Cuidado. Vós não podereis subir ao monte ou tocar em sua borda. Qualquer de vós que tocar no monte certamente será condenado à morte\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Ninguém tocará a mão na pessoa que fizer isso. Em vez disso, ela certamente deverá ser apedrejada ou flechada. Quer seja uma pessoa ou um animal, deverão ser condenados à morte. Quando a trombeta tocar por muito tempo, eles subirão até a base do monte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Então Moisés desceu do monte para o povo. Ele santificou o povo para Yahweh, e eles lavaram suas roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Ele disse para as pessoas: \"Estejam prontos para o terceiro dia; não vos chegareis a vossas esposas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'No terceiro dia, quando amanheceu, houve trovões e relâmpagos e uma nuvem espessa no monte. E ouviu-se um toque muito alto de trombeta. Todo o povo do acampamento ficou estremecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Moisés levou o povo para fora do acampamento ao encontro de Deus, e eles permaneceram na base do monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'O Monte Sinai foi completamente coberto com fumaça porque Yahweh havia descido sobre ele em fogo e fumaça. A fumaça subia como a de uma fornalha, e todo o monte estremecia violentamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Quando o som da trombeta aumentava cada vez mais, Moisés falava, e Deus lhe respondia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Yahweh desceu sobre o Monte Sinai, para o topo do monte, e chamou Moisés para lá. Então Moisés subiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Yahweh disse a Moisés: \"Desce e adverte o povo para não romper o limite para vir até Mim, ou muitos deles perecerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Os sacerdotes que se aproximam do SENHOR também devem se santificar - para que o SENHOR não se volte contra eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Moisés disse a Yahweh: \"O povo não poderá subir ao monte, porque Tu nos ordenaste: \'Marcai limites ao redor do monte e santificai-vos a Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Yahweh lhe disse: \"Vai, desce o monte e traze Arão contigo, mas os sacerdotes e o povo não poderão subir até Mim, ou Eu os atacarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Então, Moisés desceu até o povo e falou isso para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Deus disse todas estas palavras:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '\"Eu sou Yahweh, vosso Deus, que vos tirou da terra do Egito, fora da casa da servidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Vós não deveis ter nenhum outro deus além de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Vós não deveis ter para vós mesmos figuras entalhadas de nenhuma semelhança de qualquer coisa que está acima do céu, ou que esteja embaixo da terra, ou que esteja abaixo das águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Não vos ajoelhareis diante deles, nem os adorareis, porque Eu, Yahweh, vosso Deus, sou um Deus zeloso. Eu castigo os filhos pela maldade dos seus pais, até a terceira e a quarta geração daqueles que Me odeiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'Mas Eu mostrarei aliança de fidelidade até milhares de gerações daqueles que Me amarem e guardarem os Meus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Não tomareis o Meu nome, Yahweh, vosso Deus, em vão. Eu não terei por inocente aquele que tomar o Meu nome em vão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Lembrai-vos do dia de sábado para dedicá-lo a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Vós deveis trabalhar e fazer todo vosso trabalho durante seis dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Mas o sétimo dia é o Meu sábado, Yahweh, o vosso Deus. Nele, vós não deveis fazer nenhum trabalho, nem tu, nem teu filho, nem tua filha, nem teu servo, nem tua serva, nem teu gado, nem o estrangeiro que vive dentro dos teus muros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Porque, em seis dias, Eu, Yahweh, fiz os céus, a terra, e o mar e tudo que existe neles e então descansei no sétimo dia. Então Eu, Yahweh, abençoei o dia de sábado e o dediquei para Mim mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Honra a teu pai e tua mãe, dessa maneira, tu terás uma vida longa na terra, que Eu, Yahweh, teu Deus, te dei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Não cometas assassinato.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Não cometas adultério.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Não roubes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Não dês falso testemunho contra o teu vizinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Não cobices a casa do teu vizinho; não cobices a mulher do teu vizinho, seu servo, sua serva, seu boi, seu burro, ou qualquer coisa que pertença ao teu vizinho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Todo o povo viu os trovões e os raios e ouviram a voz de trombeta e viram a montanha fumegando. Quando o povo viu isso, eles tremeram e permaneceram distantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Eles disseram a Moisés: \"Fala-nos e nós o ouviremos; mas não deixes Deus nos falar, ou nós morreremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Moisés disse para o povo: \"Não temais, porque Deus veio vos provar para que a sua honra esteja em vós, a fim de que não pequeis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Então, o povo permaneceu longe, e Moisés se aproximou das densas trevas onde Deus estava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Yahweh disse a Moisés: \"Isto é o que dirás aos israelitas: \'Vós mesmos tendes visto que Eu tenho falado convosco do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Não façais para vós outros deuses diante de mim, deuses de prata ou deuses de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Vós deveis fazer um altar de terra para Mim e sacrificar sobre ele ofertas queimadas, ofertas pacíficas, ovelhas e bois. Em cada lugar, onde Meu nome estiver sendo honrado, Eu virei e vos abençoarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Se vós Me fizerdes um altar de pedras, não deveis construí-lo com pedras cortadas, porque, se vós usardes vossas ferramentas, o profanareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Não subireis pelos degraus, ao meu altar, para vos guardardes de expor vossas partes íntimas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, '\"Agora estes são os Decretos que deverás dizer ao povo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, '\'Se comprares um escravo hebreu, ele trabalhará por seis anos e, no sétimo ano, será liberto sem nenhum pagamento por isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Se ele veio por si mesmo, assim deverá ser liberto; se for casado, então sua esposa será liberta com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Se seu senhor der a ele uma esposa e ela gerar filhos ou filhas, então a esposa e as crianças pertencerão ao senhor, e ele deverá ir livre sozinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Mas, se o escravo disser claramente: \"Eu amo minha família e meu senhor; eu não irei livre\",');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'então, seu senhor deverá levá-lo perante Deus, e o colocará na porta ou portal, furará sua orelha com uma agulha espessa. Assim, o servo será seu escravo pelo resto de sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Se um homem vender sua filha como escrava, ela não será liberta como os servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Se ela não agradar a seu senhor, o qual a designou para si, o senhor deve permiti-la ser comprada de volta. Ele não tem o direito de vendê-la a um estrangeiro. Ele não tem esse direito, já que a tratou de forma desonrosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Se o senhor designá-la como esposa para seu filho, ele deverá tratá-la como se ela fosse sua filha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Se o filho a rejeitar como esposa e tomar outra esposa para si, ele não deve diminuir sua comida, vestimenta ou seus direitos conjugais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Mas, se o esposo não cumprir quanto a essas três coisas para ela, então ela poderá ser livre sem pagar nenhuma quantia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Qualquer um que ferir um homem de tal forma que ele morra, deverá ser condenado à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Se o homem não o fizer com intenção, mas acidentalmente, então irei designar um lugar para onde ele poderá fugir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Se um homem atacar intencionalmente seu vizinho e o matar, então tu terás que tirá-lo, ainda que esteja no altar de Deus, para que ele morra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Qualquer um que ferir seu pai ou sua mãe, certamente será condenado à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Qualquer um que sequestrar uma pessoa e vendê-la, ou for encontrada em seu poder, deverá ser condenado à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Qualquer um que amaldiçoar seu pai ou mãe deverá ser condenado à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Se homens brigarem, e um ferir o outro com uma pedra ou com socos, sem matá-lo, mas deixá-lo de cama;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'e este voltar a andar apoiado em seu bordão, o homem que feriu deverá pagar pelo tempo perdido, assim como pela sua completa recuperação, mas o homem não será culpado de assassinato.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Se um homem ferir seu servo ou sua serva com seu cajado e o servo chegar a morrer pelo golpe, aquele homem deverá ser punido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Entretanto, se o servo sobreviver por um ou dois dias, o senhor não será punido, porque já sofreu a perda de seu escravo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Se homens lutarem e acabarem por machucar uma mulher grávida e esta chegar a perder seu bebê, não havendo outro dano a ela, certamente o culpado deverá indenizá-la se seu marido exigir, e pagará conforme o juiz determinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Mas, se houver dano sério, deverás pagar a vida com outra vida,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'olho por olho, dente por dente, mão por mão, pé por pé,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'queimadura por queimadura, ferimento por ferimento, hematoma por hematoma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Se um homem ferir o olho de seu escravo ou escrava e destruí-lo, o senhor o deixará ir livre por seu olho destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Se arrancar um dente, também o libertará em compensação por seu dente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Se um boi fere com seu chifre um homem ou uma mulher causando-lhes a morte, o boi deverá ser apedrejado até a morte, e sua carne não deverá ser comida; mas seu dono será absolvido de culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Mas, se o boi já tinha o hábito de ferir no passado, e seu dono tinha conhecimento e não tomou nenhuma providência, e o boi matar um homem ou uma mulher, o boi deverá ser apedrejado e seu dono morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Se for pedido resgate por sua vida, ele deverá pagar com o que lhe for pedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Se um boi ferir com chifre o filho ou a filha de um homem, o dono do boi deverá fazer o que este decreto exige que ele faça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Se um boi ferir um escravo ou uma escrava, o dono do boi certamente pagará trinta siclos de prata ao seu senhor, e seu boi deverá ser apedrejado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Se alguém cavar uma cisterna, ou abrir e não tampá-la, e um boi ou jumento cair nela,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'o dono da cisterna certamente indenizará ao dono do animal pelo dano, e o animal morto passará a ser seu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Se um boi de um homem ferir o boi de outro homem de modo que ele morra, então venderá o boi vivo e dividirá o valor entre os donos, e eles também deverão dividir a carne do boi morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Mas, se era sabido que o boi já tinha o hábito de ferir no passado, e seu dono não tomou providências, ele deverá pagar animal por animal, e o boi morto se tornará dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Se um homem roubar um boi ou uma ovelha e os matar ou vender, então ele deve pagar cinco bois por um boi, e quatro ovelhas por uma ovelha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Se um ladrão for encontrado arrombando uma casa, e, se alguém o ferir e ele morrer, nesse caso nenhuma culpa pelo assassinato será colocado sobre a pessoa que o matar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Mas, se o sol nascer antes que ele arrombe, culpa pelo assassinato será colocada sobre a pessoa que o matou. O ladrão deverá fazer a restituição do que roubou. Se ele não possuir nada, então ele deverá ser vendido por seu roubo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Se o animal roubado for encontrado vivo em sua posse, seja um boi, um jumento ou uma ovelha, ele deverá pagar de volta em dobro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Se um homem levar seu rebanho para pastar em um campo ou em uma vinha e deixar seus animais soltos, e eles pastarem no campo de outro homem, ele deverá fazer a restituição com o melhor de sua própria vinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Se um incêndio começar e se espalhar entre os espinheiros, de maneira que os grãos colhidos, ou os grãos plantados, ou um campo for consumido, aquele que causou o incêndio deverá fazer a restituição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Se um homem der dinheiro e bens a seu vizinho para serem guardados com segurança, e eles forem roubados da casa desse homem, se o ladrão for encontrado, esse ladrão deverá pagar em dobro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Porém, se o ladrão não for encontrado, então o dono da casa deverá apresentar-se diante dos juízes a fim de ver se ele colocou sua própria mão na propriedade de seus vizinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Para toda disputa, seja por um boi, um jumento, uma ovelha, roupas, ou qualquer outra coisa que tenha sido perdida, sobre a qual alguém diga: \"Isto pertence a mim\", a causa das duas partes deverá ser apresentada diante dos juízes. O homem a quem o juiz considerar culpado deve pagar o dobro a seu vizinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Se um homem der a seu vizinho um jumento, um boi, uma ovelha ou qualquer animal para guardar e, se este morrer ou se machucar ou for levado sem que ninguém o veja,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'um juramento a Yahweh deverá ser feito por ambos como forma de verificar se uma pessoa colocou sua mão na propriedade de seu vizinho. O dono deverá aceitá-lo e o outro não fará restituição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Mas, se o animal tiver sido roubado dele, o outro deverá fazer a restituição ao seu dono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Se um animal tiver sido dilacerado, permiti que o outro homem traga o animal como evidência. Ele não terá que pagar pelo que foi dilacerado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Se um homem emprestar qualquer animal de seu vizinho e o animal se machucar ou morrer sem que o dono esteja presente, o outro homem deverá fazer a restituição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Mas, se o dono estiver presente, o outro homem não terá que pagar; se o animal tiver sido alugado, ele será pago por seu valor de locação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Se um homem seduzir uma virgem que não esteja prometida, e deitar-se com ela, ele deverá certamente torná-la sua esposa pagando o dote requerido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Se seu pai recusar-se completamente a entregá-la, ele deverá pagar o valor equivalente ao dote das virgens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Vós não devereis permitir que uma feiticeira viva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Aquele que dormir com um animal certamente deverá ser condenado à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Aquele que sacrificar a qualquer deus que não seja a Yahweh deverá ser completamente destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Não devereis maltratar um estrangeiro ou oprimi-lo, pois fostes estrangeiros na terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Não devereis maltratar nenhuma viúva ou órfão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Se porventura os afligirdes, e eles clamarem a Mim, Yahweh, certamente ouvirei o clamor deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Minha ira se acenderá, e vos matarei ao fio de espada; vossas esposas se tornarão viúvas e vossos filhos se tornarão órfãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Se emprestardes dinheiro a qualquer um dentre Meu povo que seja pobre, não devereis agir como um credor para com ele ou cobrar dele juros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Se tomardes o manto de seu vizinho como penhor, devereis devolvê-lo antes que o sol se ponha,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'pois este é o único cobertor para seu corpo; é seu manto para seu corpo. Onde mais ele poderá dormir? Quando ele clamar a Mim, Eu o ouvirei, pois sou compassivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Vós não devereis blasfemar contra Mim, Deus, nem amaldiçoar o juiz de vosso povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Vós não devereis reter ofertas de vossa colheita ou de vossos lagares. Devereis Me oferecer vossos primogênitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Vós fareis o mesmo com vossos bois e vossas ovelhas. Por sete dias, eles ficarão com suas mães, mas, ao oitavo dia, oferecei-os a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Vós sereis povo separado para Mim. Então, não devereis comer carne dilacerada por animais no campo. Em vez disso, devei jogá-la aos cães.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Não espalharás notícias falsas sobre ninguém, nem te ajuntarás com o ímpio para seres testemunha mentirosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Não seguirás a multidão para fazeres o mal, nem darás testemunho que perverta a justiça, para apoiar a multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Nem mesmo para favorecer um homem pobre em sua causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Se encontrares o boi do teu inimigo ou o seu jumento andando perdido, tu o levarás de volta para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Se vires o jumento de alguém que te odeia caído no chão sob sua carga, tu não o abandonarás. Tu deves certamente ajudá-lo a tirar a carga do jumento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Não perverterás o direito do pobre na sua causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Não farás falsas acusações, e não matarás o inocente e o justo, pois Eu não justificarei o ímpio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Nunca aceitarás suborno, pois o suborno cega os que veem e pervete as palavras dos justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Não oprimirás o estrangeiro, visto que vós conheceis a vida de um estrangeiro, pois fostes estrangeiros na terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Por seis anos semearás a tua terra e recolherás a sua produção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Mas no sétimo ano a deixarás descansando e não a cultivarás, de tal forma que os pobres entre teu povo possam comer. O que eles deixarem, os animais selvagens comerão. Tu farás o mesmo com tuas vinhas e olivais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Durante seis dias, tu farás o teu trabalho, mas no sétimo dia descansarás. Faze isto para que o teu boi e o teu jumento descansem, e para que o filho da tua escrava e o estrangeiro possa descansar e renovar-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Dai atenção a tudo que Eu tenho vos falado. Não mencioneis os nomes de outros deuses, nem permitais que seus nomes sejam ouvidos da tua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Três vezes por ano me celebrarás uma festa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Celebrarás a Festa dos Pães Asmos como Eu te ordenei, por sete dias comerás pães sem fermento. Naquele tempo, tu te apresentarás perante Mim no mês de Abibe, que é estabelecido para este propósito. Foi neste mês que saíste do Egito. Mas ninguém apareça de mãos vazias perante Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Celebrarás a Festa da Colheita, dos primeiros frutos do teu trabalho, do que tiveres semeado nos campos. Novamente, ao final do ano, celebrarás a Festa da Colheita quando juntares a produção dos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Todo homem deverá se apresentar perante Mim, Yahweh, três vezes no ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Não oferecerás o sangue dos sacrifícios feitos a Mim com pão fermentado. A gordura dos sacrifícios das minhas festas não deverá permanecer toda a noite até a manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Levarás os primeiros frutos, os melhores da tua terra, à Minha casa, a casa de Yahweh, teu Deus. Não cozinharás o cabrito no leite da mãe dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Eu envio um Anjo adiante de ti para te guardar pelo caminho, e para te levar ao lugar que Eu preparei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Dá atenção a Ele e obedeça à sua voz. Não o provoques, pois Ele não perdoará transgressões. Meu nome está sobre Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Se tu, de fato, obedecerdes sua voz e fizerdes tudo que Eu te digo, então Eu serei um inimigo para teus inimigos e um adversário para teus adversários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Meu Anjo irá adiante de ti e te levará aos amorreus, heteus, perizeus, cananeus, heveus e aos jebuseus; e Eu os exterminarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Não te curvarás aos seus deuses, adorando-os ou fazendo como eles fazem. Ao contrário, tu os destruirás completamente e esmigalharás seus altares de pedra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Servireis a Yahweh, teu Deus, e Ele abençoará o teu pão e a tua água; e Eu removerei as doenças do meio de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Nenhuma mulher será estéril ou abortará seu bebê na tua terra. O número dos dias da tua vida completarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Eu enviarei o meu terror adiante de ti, para aqueles em cujas terras vós entrardes. Eu exterminarei todos os povos que vós encontrardes. Eu farei com que todos os seus inimigos fujam com medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Eu enviarei vespas diante de ti que expulsarão os heveus, cananeus e os heteus diante de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Eu não os expulsarei de vossa presença num só ano, ou a terra se tornaria abandonada, e os animais selvagens se multiplicariam contra vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Em vez disso, Eu os expulsarei pouco a pouco de diante de vós, até que sejais frutíferos e herdeis a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Eu estabelecerei os teus limites desde o mar Vermelho até o mar dos filisteus, e desde o deserto até o rio Eufrates. Eu te darei vitória sobre os habitantes da terra. Tu os expulsarás de diante de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Não farás aliança com eles ou com seus deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Eles não devem viver na tua terra, ou eles te fariam pecar contra mim. Se adorardes seus deuses, isso certamente se tornará uma armadilha para ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Então Yahweh disse para Moisés: \"Subi até Mim, tu, Arão, Nadabe, Abiú e setenta anciãos de Israel, e me adorareis de longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Somente Moisés pode vir para perto de Mim. Os outros não deverão chegar perto, nem o povo poderá subir com ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Moisés foi e relatou para o povo toda as Palavras e Decretos de Yahweh. Todo o povo respondeu em uma só voz e disse: \"Nós faremos o que a Palavra de Yahweh tem dito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Então Moisés escreveu toda a Palavra de Yahweh. De manhã cedo, Moisés construiu um altar no pé da montanha e arrumou doze pilares de pedra, assim essas pedras representam as doze tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Ele enviou alguns jovens israelitas para ofertar holocaustos e sacrificar ofertas de comunhão de bois para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Moisés pegou metade do sangue e colocou dentro de bacias; ele aspergiu a outra metade sobre altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Ele pegou o Livro da Aliança e leu em voz alta para o povo. Ele disse: \"Nós faremos o que Yahweh tem falado. Nós seremos obedientes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Então Moisés pegou o sangue aspergiu sobre o povo. Ele disse: \"Este é o sangue da Aliança que Yahweh tem feito convosco dando-lhes esta promessa com todas estas Palavras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Depois Moisés, Arão, Nadabe, Abiú, e setenta dos anciãos israelitas subiram para a montanha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Eles viram o Deus de Israel. Sob seus pés estava a calçada feita de pedra de safira, tão clara quanto o próprio céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Deus não estendeu sua mão irada sobre os líderes Israelitas. Eles viram a Deus, e eles comeram e beberam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Yahweh disse para Moisés: \"Sobe até Mim na montanha e fica lá. Eu te darei as tábuas de pedra e a Lei e os Mandamentos que Eu tenho escrito, para que tu possas ensiná-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Então Moisés partiu com Josué, seu assistente, e subiu para a Montanha de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Moisés tinha dito para os anciãos: \"Ficai aqui e esperai por nós até que retornemos para vós. Arão e Hur estarão convosco. Se alguém tiver alguma questão ide até eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Então Moisés subiu até a montanha, e a nuvem o cobriu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'A glória de Yahweh se estabeleceu no Monte Sinai e a nuvem o cobriu por seis dias. No sétimo dia, Yahweh chamou por Moisés da nuvem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'A aparência da glória de Yahweh era como um fogo devorador no topo da montanha aos olhos dos israelitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Moisés entrou na nuvem e subiu para a montanha. Ele esteve na montanha por quarenta dias e quarenta noites.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Yahweh disse a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '\"Dize à nação de Israel, aos que têm coração voluntário, para ajuntar uma oferta. Tu deves receber essas ofertas para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Eis as ofertas que tu deves coletar do meio do povo: ouro, prata, bronze, lã e linho fino,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'e azul e roxo e peles de carneiro tingidas de vermelho; pelo de cabra;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'pele crua tirada de animais marinhos; madeira de acácia;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'óleo para as lâmpadas do santuário, especiarias para o óleo da unção e fragrância para o incenso,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'pedra de ônix e outras pedras preciosas para cravá-las ao colete sacerdotal e ao peitoral.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Fareis para Mim um santuário, para que Eu habite no meio do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Fareis tudo exatamente conforme mostrarei nos planos do tabernáculo e todos o seus componentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Eles devem fazer uma arca talhada em madeira de acácia. Seu cumprimento terá dois côvados e meio; sua largura terá um côvado e meio; e a altura será de um côvado e meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Cobrirás a arca com ouro puro por dentro e por fora, e farás uma borda de ouro ao redor do topo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Forjarás quatro argolas de ouro, e as fixarás nos quatro pés da arca, com duas argolas de um lado, e do outro lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Fareis, para Mim, varas de madeira de acácia e as cobrirás com ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Colocarás as varas por dentro das argolas que estão dos dois lados da arca, para carregá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'As varas devem permanecer por dentre as argolas da arca, que não devem ser removidas delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Porás dentro da arca os decretos do pacto que eu darei a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Fareis para Mim um propiciatório de ouro puro com tampa. A largura terá dois côvados e meio; a profundidade terá um côvado e meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Farás para Mim dois querubins de ouro maciço para as duas extremidades do propiciatório.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Faze-Me querubins, um em uma extremidade do propiciatório, e outro na outra extremidade. Forjarás como uma só peça os querubins e o propiciatório.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Os querubins terão suas asas abertas de frente para o propiciatório, protegendo-o. Os querubins estarão virados um de frente para o outro, olhando em direção ao centro do propiciatório.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Porás o propiciatório no topo da arca, colocarás dentro da arca os Decretos do pacto que Eu darei a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Sobre a tampa da arca, Eu Me encontrarei contigo. Falarei contigo por cima do propciatório. Falarei por entre os dois querubins que estão sobre a arca que contém os Decretos da aliança que Eu falarei a ti sobre todas as ordenanças que darei aos israelitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Farás uma mesa de madeira de acácia. Seu comprimento terá dois côvados; sua profundidade terá um côvado, e sua altura terá um côvado e meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Cobrirás de ouro puro, e a borda do topo farás de ouro ao redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Farás uma moldura com borda coberta de ouro, medindo quadro dedos de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Farás quatro argolas de ouro e as porás nas quatro extremidades, onde os quatro pés estão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'As argolas deverão ser forjadas à moldura, para prover lugar às varas, a fim de carregá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Farás as varas de madeira de acácia e as cobrirás de ouro, para que a mesa seja carregada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Os utensílios, louças, colheres, vasos e suas tigelas, deverão ser usados para oferecer as libações. Farás de ouro puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Tu deverás regularmente apresentar os pães da presença sobre a mesa, diante de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Tu farás um candelabro de puro ouro maciço. O candelabro, seu pedestal e haste farás com relevo. Seus copos em formato de flor, e as flores deverão ser feitas em uma só peça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Seis braços deverão sair dos seus lados, três braços deverão sair de um lado e três braços do candelabro deverão sair do outro lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'O primeiro braço deverá ter três copos em forma de flor de amêndoa, com cálice e botão, e três copos feitos em forma de flor de amêndoa no outro braço, com cálice e botão. Será o mesmo para os seis braços. Todos os braços deverão sair da haste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Na própria haste, deverá ter quatro copos feitos em forma de flor de amêndoa, com cálice e botão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'O cálice e o botão deverão estar nos primeiros pares de braços, feitos como peça única, e um cálice e um botão debaixo do segundo par de braços, também feitos como peça única. Da mesma forma o cálice e o botão deverão estar debaixo do terceito par de braços, feitos como peça única. Os seis braços deverão sair do candelabro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'O cálice e os botões deverão ser feitos como peça única, uma peça de puro ouro batido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Tu deverás fazer o candelabro e suas sete lamparinas, e posicioná-las para iluminar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'O seus aparadores e apagadores deverão ser feitos de ouro puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Um talento de ouro puro deverá ser usado para fazer o candelabro e seus utensílios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Certifica-te de fazer tudo conforme o padrão que está sendo mostrado a ti no monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Deves fazer o tabernáculo com dez cortinas de linho fino, e azul, e roxo e vermelho, com querubins bordados nelas. Trabalho este feito por habilidosos artesãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'O comprimento de cada cortina deve ser de vinte e oito côvados, a largura de quatro côvados. Todas as cortinas deverão ser do mesmo tamanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Cinco cortinas deverão ser ajuntadas umas às outras, e as outras cinco cortinas também ajuntadas umas às outras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Deves fazer laços de azul na borda da última cortina do primeiro agrupamento. Do mesmo jeito, deves fazer os mesmos laços na extremidade final da última cortina do segundo agrupamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Deves fazer cinquenta laçadas na primeira cortina, e deves fazer cinquenta laçadas na última cortina do segundo grupamento. Faças isso para que as laçadas estejam opostas umas às outras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Deves fazer cinquenta fechos de ouro e juntar as cortinas com eles para que o tabernáculo seja unido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Deves fazer cortinas de pelos de cabra para que sirva de cobertura sobre o tabernáculo. Deves fazer onze dessas cortinas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'O comprimento de cada cortina deverá ser de trinta côvados, e a largura de cada uma, quatro côvados. Cada uma das onze cortinas deverá ser do mesmo tamanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Deves juntar cinco cortinas entre si e as outras seis cortinas entre si. Deves dobrar a sexta cortina na frente da Tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Deves fazer cinquenta laçadas na borda da última cortina do primeiro grupamento, e cinquenta laçadas na borda da última cortina que compõe o segundo grupamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Farás cinquenta fechos de bronze e os colocarás nos laços. Então deves unir as cortinas para que sejam como uma só peça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'A metade restante da cortina, que é a parte que sobra da cortina da tenda, deve cobrir o fundo do tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Deve haver um côvado de cortina de um lado, e um côvado de cortina do outro lado - a parte que está sobrando em comprimento deve cobrir os lados do tabernáculo de um lado e do outro, deve cobri-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Deves fazer, para o tabernáculo, uma cobertura feita de pele de carneiro tingida de vermelho, e uma outra cobertura de couro para ir sobre a primeira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Deves fazer tábuas de madeira de acácia, na vertical, para o tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'O comprimento de cada tábua deverá ser de dez côvados, e sua largura, de um côvado e meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Deve haver dois encaixes, um em cada tábua, para que elas possam se encaixar uma na outra. Farás todas as tábuas do tabernáculo desta maneira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Quando fizeres as tábuas para o tabernáculo, deves fazer vinte tábuas para o lado sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Farás quarenta bases de prata para que vá abaixo das vinte tábuas. Deve haver duas bases debaixo da primeira tábua para que sejam seus pedestais, também deve haver duas bases debaixo das outras tábuas para que sejam seus pedestais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Para o segundo lado do tabernáculo, no lado norte, deves fazer vinte tábuas');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'e suas quarenta bases de prata. Deve haver duas bases debaixo da primeira tábua, duas bases debaixo da segunda tábua, e assim por diante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Para o fundo do tabernáculo, no lado oeste, deves fazer seis tábuas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Farás duas tábuas para os cantos do fundo do tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Essas tábuas devem possuir suas bases separadas, porém juntas pelo mesmo anel, em sua extremidade superior. Deve ser dessa maneira para ambos os cantos do fundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Devem ter oito tábuas juntamente com suas bases. Deve haver dezesseis bases para todas, duas bases debaixo da primeira, duas debaixo da seguinte, e assim por diante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Deves fazer travessões de madeira de acácia - cinco para as tábuas de um lado do tabernáculo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'cinco travessões para as tábuas no outro lado do tabernáculo, e cinco travessões para o lado do fundo do tabernáculo para o oeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'O travessão no centro das tábuas, que as conectará, se estenderá de uma extremidade à outra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Banharás as tábuas com ouro. Deves também fazer as argolas de ouro, para que sirvam de suportes para os travessões, e deves banhar as tábuas com ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Deves montar o tabernáculo de acordo com o plano que te foi mostrado no monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Deves fazer também um véu de azul, roxo e vermelho, e de linho fino, com bordados de querubins, trabalho de um habilidoso artesão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Deves pendurá-lo em quatro colunas de madeira de acácia banhadas em ouro. Essas colunas devem possuir ganchos de ouro e estarem sobre quatro bases de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Deves prender as cortinas debaixo dos fechos, e deverás trazer a Arca da aliança para dentro do véu. O véu é para fazer separação entre o lugar santo e o lugar santíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Colocarás o propiciatório sobre a Arca do testemunho, que está no lugar santíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Deverás colocar a mesa do lado de fora do véu. O candelabro deve ser posicionado em frente à mesa, no lado sul do tabernáculo. A mesa deve estar no lado norte do tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Deves fazer uma cortina para a entrada da tenda. Farás a cortina de azul, púrpura, e carmesim, de linho fino torcido, trabalho de um bordador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Para as cortinas, deves fazer cinco pilares de madeira de acácia banhados com ouro. Seus ganchos devem ser de ouro, e fundirás cinco bases de bronze para os pilares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Tu deves fazer o altar de madeira de acácia, cinco côvados de comprimento e cinco côvados de largura. O altar deve ser quadrado e com três côvados de altura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Tu deves fazer extensões de seus quatro cantos no formato de chifres de boi. Os chifres serão feitos como uma só peça com o altar, e deves cobri-los com bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Tu deves fazer utensílios para o altar: potes para cinzas, e também pás, bacias, garfos e braseiros. Deves fazer todos esses utensílios com bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Deves fazer uma grelha para o altar, na forma de uma rede de bronze. Faça um anel de bronze para cada um dos quatro cantos da grelha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Tu deves colocar a grelha sob a borda do altar, de maneira que chegue até o meio do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Deves fazer varas para carregar o altar, varas de madeira de acácia, e deves cobri-las com bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'As varas devem passar por dentro das argolas, e elas devem estar nos dois lados do altar para ser carregado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Tu deves fazer o altar oco, de tábuas. Deves fazê-lo como te foi mostrado no monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Tu deves fazer um átrio para o tabernáculo. No lado sul do átrio, deve haver cortinas de linho fino torcido de cem côvados de comprimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'As cortinas serão sustentadas por vinte colunas, cujas bases serão de bronze. Deve haver ganchos ligados às colunas, e hastes de prata para as cortinas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Da mesma forma, no lado norte, deve haver cortinas de cem côvados de comprimento, com vinte postes, vinte bases de bronze, ganchos ligados às colunas e hastes de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Na largura do átrio, no lado oeste, deve haver uma cortina de cinqüenta côvados de comprimento. Deve haver dez postes e dez bases.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'O átrio deve também ter cinquenta côvados de comprimento no lado leste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'As cortinas para um lado da entrada devem ser de quinze côvados de comprimento. Elas devem ter três colunas com três bases.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'O outro lado também deve ter cortinas de quinze côvados de comprimento. Elas devem ter suas três colunas e três bases.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'O portão do átrio deve ser uma cortina de vinte côvados de comprimento. A cortina deve ser feita de azul, roxo, e vermelho, linho fino torcido, obra de bordador. Ela deve ter quatro colunas com quatro bases.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Todas as colunas do átrio devem ter hastes de prata, ganchos de prata, e bases de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'O comprimento do pátio deverá ser de cem côvados, a largura de cinqüenta côvados, e a altura de cinco côvados, com finas cortinas de linho fino torcido em toda a extensão, e as bases de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Todos os utensílios a serem utilizados na tenda, e todas as estacas para o tabernáculo e para o pátio devem ser feitas de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Tu deves ordenar os israelitas para trazerem azeite puro de azeitonas prensadas para as lâmpadas, de modo que elas possam queimar continuamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Na Tenda do encontro, do lado de fora do véu que está diante da Arca da aliança, Arão e seus filhos deverão manter as lâmpadas acesas de tarde até a manhã, perante Yahweh. Essa ordenança será um estatuto perpétuo ao longo das gerações da nação israelita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Chama para si seu irmão Arão e seus filhos Nadabe, Abiú, Eleazar e Itamar dentre os israelitas para servir-Me como sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Tu deves fazer para Arão, teu irmão, vestimentas que são dedicadas a Mim. Essas vestimentas serão para a sua honra e esplendor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Tu deves falar a todo o povo que tem habilidades especiais, aqueles a quem Eu enchi com o Espírito de sabedoria, para que façam as vestimentas de Arão para separá-lo para Me servir como Meu sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'As vestimentas que eles devem fazer são um peitoral, uma estola, um manto bordado, um turbante e um cinto. Eles devem fazer essas vestimentas dedicadas a Mim. Elas serão para seu irmão Arão e seus filhos para Me servirem como sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Os artesãos devem usar linho fino, ouro, azul, roxo e vermelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Eles devem fazer o colete sacerdotal de ouro, de linho fino torcido, e de lã azul, roxa e vermelha. Deve ser um trabalho de um artesão especialista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Deve ter duas ombreiras unidas nas extremidades superiores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Seu cinto de costura fina deve ser como o colete sacerdotal; deve ser feito formando uma só peça com o colete sacerdotal, feito de ouro, linho fino torcido e de azul, roxo e vermelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Tu deves levar duas pedras de ônix e gravar nelas os nomes dos doze filhos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Seis de seus nomes devem estar em uma pedra, e seis nomes devem estar na outra pedra, em ordem de idade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Com o trabalho de um lapidário em pedra, como gravação por sinete, gravarás as duas pedras com os nomes dos doze filhos de Israel. Tu deves montar as pedras com engastes de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Colocarás as duas pedras nas ombreiras do colete sacerdotal para lembrar Yahweh dos filhos de Israel. Arão carregará seus nomes perante Yahweh, sobre os dois ombros como uma lembrança a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Deves fazer engastes de ouro');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'e duas correntes entrelaçadas de puro ouro como cordões, e deves fixar as correntes nos engastes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Deves fazer um peitoral do juízo, trabalho de um especialista, desenhado como o sacerdotal. Faça-o de ouro, de azul, roxo, de lã vermelha e de linho fino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Deve ser quadrado. Tu deves dobrar o peitoral duas vezes. Ele deve ser de um palmo de comprimento e de um palmo de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Deves fixar nele quatro fileiras de pedras preciosas. A primeira fileira deve ter um rubi, um topázio e uma granada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'A segunda fileira deve ter uma esmeralda, uma safira e um diamante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'A terceira deve ter um jacinto, uma ágata e uma ametista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'A quarta deve ter um berilo, um ônix e um jaspe. Elas devem ser montadas em engastes de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'As pedras devem ser arrumadas com os nomes dos doze filhos de Israel, cada uma na ordem dos nomes. Elas devem ser como a gravação de um sinete de anel, cada nome estando como uma das doze tribos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Tu deves fazer no peitoral correntes como cordas, trabalho entrelaçado de ouro puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Deves fazer duas argolas de ouro para o peitoral e deves fixá-las nas duas extremidades dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Deves fixar as duas correntes de ouro nas duas extremidades do peitoral.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Deves fixar as outras extremidades das duas correntes entrelaçadas aos dois engastes. Então tu deves prendê-los nas ombreiras do peitoral do colete, na parte da frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Deves fazer duas argolas de ouro, e colocá-las nas outras duas extremidades do peitoral, no limite próximo à borda interior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Tu deves fazer mais duas argolas de ouro, e deves fixá-las no fundo das duas ombreiras da frente do colete sacerdotal, próximas às suas costuras, sobre a fina costura do cinto do colete sacerdotal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Eles devem prender o peitoral com essas argolas nas argolas do colete sacerdotal com o cordão azul, para que ele seja fixado exatamente acima do cinto costurado do colete sacerdotal. Isso é para que o peitoral não se separe do colete sacerdotal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Quando Arão for para o lugar santo, ele deve levar os doze nomes dos filhos de Israel no peitoral do juízo sobre o seu coração para tomada de decisão, como um memorial contínuo diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Tu deves colocar no peitoral do juízo o Urim e o Tumim. Eles devem estar no peito de Arão quando se adentrar perante Yahweh, e Arão deve constantemente levar o juízo dos israelitas em seu peito perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Tu deves fazer o manto do colete sacerdotal completamente de tecido na cor púrpura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Ele deve ter uma abertura para a cabeça no meio. A abertura deve ter uma borda costurada arredondada para que não se rompa. Deve ser feito por um tecelão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Em sua bainha, deves fazer romãs de fio azul, roxo e vermelho ao redor. Sinos de ouro devem ser colocados entre eles ao redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Deve haver um sino de ouro e uma romã, um sino de ouro e uma romã - continuamente - ao redor da bainha do manto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Este manto deve estar em Arão quando ele servir, para que seu som possa ser ouvido quando ele entrar no lugar santo, perante Yahweh, e ao sair. Isso é para que ele não morra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Tu deves fazer uma placa de ouro puro e gravar nele, como a gravação de um sinete, DEDICADO A YAHWEH.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Deves prender essa placa com um cordão azul na frente do turbante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Isso deve estar na testa de Arão; ele deve sempre levar toda a culpa que possa ser atribuída às ofertas dos presentes sagrados que os israelitas dedicaram a Yahweh. O turbante deve estar sempre em sua testa para que Yahweh possa aceitar seus presentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Deves fazer uma túnica de fino linho, e tu deves fazer um turbante de fino linho. Deves fazer também um cinto, com o trabalho de um bordador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Para os filhos, de Arão deves fazer capas, cintos e tiaras para glória e ornamento deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Tu deves vestir teu irmão Arão e seus filhos com ele. Tu deves ungi-los, ordená-los, e dedicá-los a Mim, para que eles possam Me servir como sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Tu deves fazer-lhes calções de linho para cobrir suas partes íntimas, calções que os cobrirão da cintura até as coxas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Arão e seus filhos devem usá-los quando eles entrarem na Tenda do encontro, ou quando eles se aproximarem do altar, para servir no lugar santo. Eles devem fazer isso para que não venham a carregar iniquidade e morram. Isso será uma lei permanente para Arão e seus descendentes após ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Agora isso é o que tu deves fazer para dedicá-los a Mim para que então possam me servir como sacerdotes. Pega um novilho e dois carneiros sem mácula,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'pães e bolos sem levedura misturados com azeite. Também pega bolachas sem levedura mergulhadas no óleo. Faze as bolachas usando uma farinha de trigo fina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Deves pô-los em uma única cesta, trazê-los na cesta, e apresentá-los com o novilho e os dois carneiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Deves apresentar Arão e seus filhos na entrada da Tenda do encontro. Deves lavar Arão e seus filhos na água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Deves pegar as roupas e vestir Arão com a túnica, o manto do colete sacerdotal, o colete sacerdotal, e o peitoral, prendendo o tecido fino do colete sacerdotal em volta dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Deves colocar o turbante em sua cabeça e a coroa santa em cima do turbante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Então pega o óleo da unção e derrama em sua cabeça e, dessa forma, unge-o.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Deves trazer seus filhos e pôr capas neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Deves vestir Arão e seus filhos com cintos e pôr turbantes neles. O trabalho do sacerdócio pertencerá a eles por uma lei permanente. Dessa forma, deves consagrar Arão e seus filhos para que eles sirvam a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Vós deveis trazer o novilho à Tenda do encontro e Arão e seus filhos devem repousar suas mãos na cabeça dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Tu deves matar o novilho perante Mim, Yahweh, na entrada da Tenda do encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Deves tomar uma parte do sangue do novilho e pô-lo nas pontas do altar com teu dedo, e deves derramar o sangue remanescente na base do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Deves tomar toda a gordura que cobre as vísceras e também tomarás a gordura que envolve o fígado e os dois rins; queima tudo no altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Mas a carne, a pele e o excremento do novilho, tu deves queimá-los fora do campo. Isso será uma oferta pelos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Deves tomar o primeiro carneiro, e Arão e seus filhos devem repousar suas mãos na cabeça dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Tu deves matar o carneiro. Então pega seu sangue e espalha-o em cada lado e dentro do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Tu deves cortar o carneiro em pedaços e lavar suas vísceras e pernas, e deves pôr as vísceras, juntamente com suas partes e sua cabeça,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'sobre o altar. Então queima o carneiro inteiro. Será um holocausto para mim, Yahweh. Isso produzirá um aroma agradável para mim; será uma oferta de holocausto feita a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Deves então pegar o outro carneiro, e Arão e seus filhos devem repousar suas mãos na cabeça dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Então tu deves matar o carneiro e pegar parte de seu sangue. Coloca-o na ponta da orelha direita, no polegar da mão direita e no polegar do pé direito de Arão e dos seus filhos. Então deves derramar sangue em cada lado do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Deves pegar parte do sangue que está no altar e parte do óleo de unção, e derramar em Arão e em suas roupas, e também em seus filhos e suas roupas. Arão será, então, separado para Mim, assim como suas roupas, seus filhos e as roupas dos seus filhos com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Deves pegar a gordura do carneiro, a gordura da cauda, a gordura que cobre as vísceras, a cobertura do fígado, dos dois rins, a gordura que os envolve, e a coxa direita – porque esse carneiro é para a consagração dos sacerdotes a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Pega um pão, um bolo feito com azeite, e uma bolacha de dentro da cesta de pães sem levedura que haverá perante Mim, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Tu deves colocá-los nas mãos de Arão e de seus filhos. Eles deverão apresentá-los perante Mim, Yahweh, e mostrá-los como uma oferta a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Tu deves, então, pegar o alimento de suas mãos e queimá-lo no altar junto com o holocausto. Isso produzirá um aroma agradável para Mim; será uma oferta de fogo oferecida a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Deves pegar o peito do carneiro usado para consagração de Arão e apresentá-lo como uma oferta a Mim, Yahweh. Então esta será sua porção para comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Tu deves dedicar a Mim o peito que ofereceste como oferta e a coxa que fora apresentada – o peito que fora ofertado e a coxa que fora apresentada, ambos vieram do carneiro de consagração de Arão e seus filhos a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Essas porções de carne, dadas pelos israelitas, devem pertencer para sempre a Arão e a seus descendentes. Pela norma das ofertas pacíficas, estas serão ofertas para os sacerdotes, tiradas das ofertas dos israelistas, apresentadas a Mim, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'As roupas santas de Arão também devem ser reservadas para seus filhos depois dele. Eles serão ungidos nelas e ordenados para Mim nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'O sacerdote que sucedê-lo dentre seus filhos, que virá à Tenda do encontro para servir a Mim, no santo lugar, usará essas roupas por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Tu deves tomar o carneiro da consagração dos sacerdotes e cozinhar sua carne em um lugar santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Arão e seus filhos devem comer a carne do carneiro e o pão que está dentro da cesta na entrada da Tenda do encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Eles devem comer a carne e o pão que tu sacrificaste para ordenança deles, para ser consagrada a Mim. Ninguém mais pode comer essa comida, porque devem considerá-la consagrada a Mim, reservada para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'E se, na manhã seguinte, houver sobrado algo da carne ou do pão da ordenação, então tu deves queimá-los. Não deverá ser comido porque foram consagrados a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Dessa forma, ao seguir tudo o que Eu comandei para que fizesses, deves fazer com Arão e seus filhos. Tu deves tomar sete dias para consagrá-los a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Todo dia tu deves oferecer um novilho como oferta de perdão pelos pecados. Tu deves purificar o altar, fazendo expiação por ele, e deves ungi-lo com óleo para consagração a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Por sete dias, tu deves purificar o altar e consagrá-lo a Yahweh. Então o altar será completamente consagrado a Mim. Tudo o que tocar o altar será separado para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Tu deves oferecer, todos os dias, no altar, dois cordeiros de um ano de idade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Um cordeiro tu deves oferecer pela manhã e o outro cordeiro tu deves oferecer perto do anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Com o primeiro cordeiro, oferecerás dois quilos de farinha fina misturada com um litro de azeite de oliva e derramarás um litro de vinho como oferta de bebida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Tu deves oferecer o segundo cordeiro ao pôr do sol. Tu deves ofertar a mesma oferta queimada da manhã e a mesma oferta de bebida. Essas produzirão um aroma agradável para Mim; será uma oferta de fogo feita a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Isso deve ser uma oferta de fogo regular feita pelo seu povo. Tu deves fazê-lo na entrada da Tenda de encontro perante Mim, Yahweh, onde te encontrarei para falar contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Ali me encontrarei com os israelistas; a tenda ficará separada para Mim pela Minha glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Eu consagrarei a Tenda do encontro e o Altar para aqueles que pertencem somente a Mim. Eu irei também consagrar Arão e seus filhos para servirem a Mim como sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Eu viverei entre os israelitas e serei o seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Eles saberão que eu sou Yahweh, seu Deus, que os tirou da terra do Egito para que Eu pudesse viver entre eles. Eu sou Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Tu deves fazer um altar para queimar incenso. Deves fazê-lo com madeira de acácia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'O seu comprimento deve ser de um côvado e sua largura de um côvado. O altar deve ser quadrado e sua altura deve ser de dois côvados. As suas pontas devem ser feitas como uma só peça com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Deves cobrir o altar do incenso com ouro puro ― sua tampa, seus lados e suas pontas. Deves fazer uma moldura de ouro para o altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Deves fazer duas argolas de ouro para serem presas à moldura do altar nos seus dois lados opostos. As argolas devem ser o suporte das varas para carregar o altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Deves fazer as varas de madeira de acácia e deves cobri-las com ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Deves colocar o altar de incenso diante do véu que está diante da Arca da Aliança. Ele estará diante do propiciatório que está sobre a Arca da Aliança, onde te encontrarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Arão deve queimar incenso aromático todas as manhãs. Ele deve queimá-lo quando organizar as lâmpadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Quando Arão acender as lâmpadas outra vez, à noite, ele deve queimar incenso no altar de incenso. Essa deve ser uma oferta de incenso regular diante de Mim, Yahweh, por todas as gerações do teu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Mas tu não deves oferecer outro incenso sobre o altar de incenso, nem outro holocausto ou oferta queimada. Tu não deves derramar oferta de bebida sobre o altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Arão deve fazer propiciação sobre as pontas do altar de incenso uma vez por ano. Ele deve fazer isso usando o sangue da oferta de sacrifício pelo pecado. O sumo sacerdote deve fazer isso por todas as gerações do teu povo. Essa oferta será completamente dedicada a Mim, Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Yahweh disse a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '\"Quando tu fizeres o censo dos israelitas, então cada pessoa deve dar o resgate pela sua vida a Yahweh. Tu deves fazer isso após contá-los, para que não haja praga entre eles quando tu os contares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Todo o que for contado no censo pagará meio ciclo de prata, de acordo com o peso do santuário (um ciclo corresponde a vinte geras). Esse meio ciclo será uma oferta a Mim, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Todo o que for contado, de vinte anos acima, deve dar essa oferta a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Quando o povo ofertar a Mim para fazer expiação por vossas vidas, o rico não deve dar mais que meio ciclo e o pobre não deve dar menos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Tu deves receber o dinheiro da expiação dos israelitas e deves aplicá-lo no serviço da Tenda do encontro. Isso deve ser um memorial para os israelitas diante de Mim, para fazer expiação por vossas vidas.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Yahweh disse a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '\"Tu também deves fazer uma grande pia de bronze com uma base de bronze, uma pia para purificação. Tu deves colocá-la entre a Tenda do encontro e o altar, e deves despejar água nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Arão e seus filhos devem lavar suas mãos e seus pés com a água da pia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Quando eles entrarem na Tenda do encontro, ou quando se aproximarem do altar para Me servir queimando ofertas, eles devem lavar-se com água, para que não morram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Eles devem lavar suas mãos e pés para que não morram. Essa será uma lei permanente para Arão e seus descendentes por todas as gerações do teu povo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Yahweh disse a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '\"Toma estas finas especiarias: quinhentos ciclos de mirra líquida, duzentos e cinquenta ciclos de canela aromática, duzentos e cinquenta ciclos de cálamo aromático,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'quinhentos ciclos de cássia, medidos com o peso do ciclo do santuário, e um him de azeite de oliva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Tu deves fazer o óleo santo da unção com esses ingredientes, o trabalho de um perfumista. Esse será um óleo santo de unção reservado para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Tu deves ungir a tenda do encontro com esse óleo e também a Arca da Aliança,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'a mesa e todos os seus utensílios, o candelabro e seus equipamentos, o altar de incenso,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'o altar do holocausto com todos os seus equipamentos e a pia com sua base.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Tu deves dedicá-los a Mim para que sejam completamente consagrados a Mim. Tudo o que tocar essas coisas também será separado para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Deves ungir Arão e seus filhos e consagrá-los a Mim para que me sirvam como sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Tu deves dizer aos israelitas: \'Este deve ser um óleo de unção que é dedicado a Yahweh por todas as gerações do teu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Ele não deve ser aplicado na pele das pessoas, nem deveis fazer outro óleo com a mesma fórmula porque ele é consagrado a Yahweh. Deveis considerá-lo assim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Quem fizer perfume como ele, ou quem aplicá-lo em outrem, essa pessoa deve ser cortada do seu povo.\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Yahweh disse a Moisés: \"Toma especiarias - estoraque, ônica e gálbano - especiarias aromáticas com puro incenso, cada um em quantidades iguais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Prepara-os na forma de incenso, misturado por perfumista, temperado com sal, puro e consagrado a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Tu os triturarás até obter uma mistura muito fina. Ponha parte dele em frente à Arca da Aliança, que está na Tenda do encontro, onde te encontrarei. Tu o considerarás completamente dedicado a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Quanto a esse incenso que prepararás, não farás outro com a mesma fórmula para vós mesmos. Ele deve ser santíssimo a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Quem preparar algo como ele para usar como perfume deve ser cortado do seu povo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Disse Yahweh a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '\"Vê, Eu tenho chamado pelo nome a Bezalel filho de Uri filho de Hur, da tribo de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Eu tenho enchido a Bezalel com meu Espírito, para dar-lhe sabedoria, entendimento e conhecimento em todo tipo de atividade artística,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'para fazer desenhos artísticos e trabalhar em ouro, prata e bronze;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'também para cortar e definir pedras e para fazer entalhe em madeira, ou seja, para trabalhar em toda atividade artística.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Além dele, Eu tenho designado também a Aoliabe, filho de Aisamaque, da tribo de Dã. Eu tenho colocado nos corações de todos os que são sábios para que eles possam fazer tudo o que Eu tenho te ordenado. Isso inclui');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'a Tenda do encontro, a Arca dos Decretos da Aliança, a tampa da expiação que estará sobre a Arca, e todos os utensílios da Tenda:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'a mesa com seus utensílios, o candelabro de ouro puro com todos os seus utensílios, o altar do incenso,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'o altar para as ofertas queimadas com os seus utensílios, e a pia grande com a sua base;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'as vestes finamente tecidas, a saber, as vestes sagradas para Arão, o sacerdote, e as de seus filhos, separados para Me servirem como sacerdotes;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'Isso também inclui o óleo da unção e o incenso de aroma agradável para o lugar sagrado. Esses artesãos devem fazer todas as coisas como Eu te ordenei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Disse Yahweh a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '\"Fala aos israelitas: \'Vós certamente guardareis os sábados de Yahweh, porque isso será um sinal entre Ele e vós através das gerações; para que saibais que Ele é Yahweh, que vos separastes para Ele mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Então vós deveis guardar o sábado, tratá-lo como santo, separado para Ele. Quem profanar o sábado certamente deverá ser morto. Qualquer um que trabalhar no sábado, essa pessoa deverá ser expulsa do meio do seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Durante seis dias trabalharás, mas o sétimo dia será o sábado de descanso solene, santo, separado para a honra de Yahweh. Quem fizer qualquer tipo de trabalho no dia de sábado certamente deverá ser morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Portanto os israelitas devem guardar o sábado, observando-o através das gerações como lei perpétua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'O sábado será um sinal entre Yahweh e os israelitas para sempre, porque Yahweh fez os céus e a terra em seis dias e, no sétimo dia, descansou e tomou alento\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Quando Deus acabou de falar com Moisés no monte Sinai, deu-lhe as duas tábuas dos Decretos da Aliança, tábuas feitas de pedra, escritas pela Sua própria mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Quando o povo viu que Moisés demorava para descer da montanha, eles se ajuntaram em volta de Arão e lhe disseram: \"Vem, faze-nos um ídolo para que vá a nossa frente. Quanto a esse Moisés, o homem que nos tirou da terra do Egito, não sabemos o que aconteceu com ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Então Arão lhes disse: \"Tirai os brincos de ouro das orelhas de vossas esposas e das orelhas dos vossos filhos e filhas, e trazei-os a mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'E todo o povo retirou os brincos de ouro que estavam em suas orelhas e os levou a Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Ele recebeu o ouro do povo, e o modelou em forma de um bezerro. Então o povo disse: \"Israel, este é o vosso deus que vos tirou da terra do Egito.\"\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Quando Arão viu isso, ele construiu um altar diante do bezerro e proclamou, dizendo: \"Amanhã haverá um festival em honra a Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'No dia seguinte, o povo se levantou cedo e ofereceu ofertas queimadas e trouxeram ofertas pacificas. Então se sentaram para comer e beber, e depois se levantaram para se divertir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Então Yahweh disse a Moisés: \"Vá imediatamente, pois o teu povo, os quais tiraste da terra do Egito, tem se corrompido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Eles rapidamente se desviaram do caminho que Eu os ordenei. Eles moldaram um bezerro para eles e o adoraram e fizeram sacrificios para ele. Eles têm dito: \'Israel, esse é o seu deus que vos tirou da terra do Egito\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'E disse Yahweh a Moisés: \"Eu tenho visto esse povo. Vê, eles são um povo teimoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Agora, pois, não tentes me impedir. Minha furia irá queimar contra eles, então EU os destruirei. Feito isso irei fazer uma grande nação por meio de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Porém Moisés tentou acalmar Yahweh seu Deus. Ele disse: \"Yahweh por que a tua ira se acende contra o teu povo, os quais Tu trouxeste da terra do Egito com grande poder e mão poderosa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Por que os egípcios deveriam dizer: \'Ele os livrou do mal para matá-los nas montanhas e destruí-los da face da terra\'? Afasta-te desta fúria ardente e retira essa punição de sobre o Teu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Lembra-te de Abraão, de Isaque e de Israel, Teus servos, aos quais Tu juraste, por ti mesmo, dizendo-lhes: \"Multiplicarei teus descendentes como as estrelas nos céus, e lhes darei toda esta terra a qual tenho falado. Eles a herdarão para sempre\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Então Yahweh desistiu da punição que Ele lhe havia dito que traria contra o Seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Então Moisés se virou e desceu a montanha, carragando as duas tábuas dos Decretos da Aliança em suas mãos. As tábuas estavam escritas em ambos os lados, frente e verso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'As tábuas e os seus escritos eram obras do próprio Deus, esculpidos por Ele mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Quando Josué ouviu o barulho do povo que gritava, ele disse a Moisés: \"Há gritos de combate no acampamento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Mas disse-lhe Moisés: \"Isso não é grito dos vitoriosos, e nem barulho de pessoas derrotadas, o que escuto é o som de pessoas cantando\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Quando Moisés chegou ao acampamento, ele viu o bezerro e as pessoas dançando. Logo enfureceu-se. Ele lançou as tábuas de suas mãos e as quebrou ao pé da montanha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Ele pegou o bezerro que as pessoas haviam feito, queimou-o, triturou-o até virar pó, e o despejou na água. Então ele fez com que o povo de Israel a bebesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Então Moisés disse a Arão: \"O que esse povo te fez, para que trouxesses tamanho pecado sobre ele\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Disse-lhe Arão: \"Não se acenda a vossa ira, meu senhor. Tu conheces esse povo, e sabes o quanto eles empenhados em fazer o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Eles me disseram: \'Faze-nos um deus que vá a nossa frente. Quanto a Moisés, o homem que nos trouxe da terra do Egito, nós não sabemos o que houve com ele\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Então eu lhes disse: \'Aqueles que têm ouro, tirem-no. Eles me deram, e eu o lancei ao fogo, e saiu esse bezerro\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Moisés viu que o povo estava agindo de forma estranha, pois Arão os deixou perder o controle, expondo-os à zombaria dos seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Então Moisés ficou de pé, na entrada do acampamento, e disse: \"Quem estiver do lado de Yahweh, venha até mim\". Todos os levitas se ajuntaram em volta dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Ele lhes disse: \"Yahweh, o Deus de Israel, diz isto: \'Que cada homem prepare sua espada ao lado indo e vindo, de porta em porta, por todo o acampamento, e mate seus irmãos, seus companheiros e vizinhos\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Os levitas fizeram conforme Moisés lhes havia ordenado. Naquele dia morreram cerca de três mil homens do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Moisés disse aos levitas: \"Vós fostes postos a serviço de Yahweh hoje, pois cada um de vós agiu contra seu irmão, portanto Yahweh vos deu uma benção hoje\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'No dia seguinte, Moisés disse ao povo: \"Cometestes um grande pecado. Agora eu subirei a Yahweh. Talvez eu possa fazer expiação pelo vosso pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Moisés voltou a Yahweh e disse: \"Oh, esse povo cometeu um grande pecado e fizeram para si um ídolo de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Mas agora, perdoa-lhes o pecado; se não o fizeres, apaga-me do livro que escreveste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Yahweh disse a Moisés: \"Aquele que tiver pecado contra mim, essa pessoa eu apagarei do meu livro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Agora vai e conduz este povo para o lugar sobre o qual eu te falei. Vê, o Meu anjo irá na tua frente. Porém no dia em que Eu os castigar, Eu os punirei por seu pecado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Então Yahweh enviou a praga para o povo, por fezer o bezerro, aquele que Arão havia fabricado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Yahweh disse a Moisés: \"Parte daqui, tu e o povo que tiraste da terra do Egito. Vái para a terra a respeito da qual tenho feito um juramento a Abraão, a Isaque e a Jacó, quando Eu disse: \'Eu a darei à tua descendência\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Enviarei um anjo à tua frente, e expulsarei os cananeus, os amorreus, os heteus, os perizeus, os heveus e os jebuseus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Vai para a terra da qual está fluindo leite e mel, porém Eu não irei contigo, porque és um povo muito teimoso. Eu poderei destruir-te no caminho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Quando o povo ouviu essas palavras inquietantes, pranteou, e não se adornou de jóias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Yahweh havia dito a Moisés: \"Dize aos israelitas: \'Sois um povo teimoso. Se Eu fosse no meio de vós, ainda que por um momento, vos destruiria. Portanto, tirai os vossos adornos para que Eu decida o que fazer convosco\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Então os israelitas não usaram jóias, desde o monte Horebe em diante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Moisés tomou uma tenda, e a armou do lado de fora do acampamento, a uma certa distância. Ele a chamou de Tenda do encontro. Todo aquele que pedia qualquer coisa a Yahweh ia à Tenda do encontro, fora do acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Quando Moisés ia à Tenda, todo o povo se levantava e ficava de pé na entrada de sua própria tenda, observando Moisés, até que ele entrasse na Tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'E quando Moisés entrava na Tenda, a coluna de nuvem descia e ficava à entrada da Tenda, e Yahweh falava com Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Sempre que o povo via a coluna de nuvem parada em frente à entrada da Tenda, todos se levantavam e adoravam, cada um na entrada de sua tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'E Yahweh falava com Moisés face a face, como quem fala com seu amigo. Em seguida, Moisés voltava para o acampamento, mas o seu servo, o jovem Josué, filho de Num, permanecia na Tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'E Moisés disse a Yahweh: \"Tu me dizes: \'Leva este povo em sua jornada\', mas não tens me mostrado quem enviarás comigo. Disseste também: \'Conheço-Te por teu nome, e achaste favor aos Meus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Se achei favor aos Teus olhos, rogo-Te que agora me mostres os Teus caminhos, para que eu Te conheça, a fim de que continue a achar favor aos Teus olhos. Lembra-Te de que esta nação é o Teu povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Yahweh respondeu-lhe: \"Eu mesmo irei contigo, e te darei descanso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Então Moisés lhe disse: \"Se Tu mesmo não fores conosco, não nos tires daqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Caso contrário, como saber que encontrei favor aos Teus olhos, eu e o Teu povo? Acaso não é somente por andares conosco, que eu e o Teu povo somos diferentes de todos os outros povos da face da terra?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'E Yahweh disse a Moisés: \"Farei também isso que Me pediste, pois achaste favor aos Meus olhos, e te conheço pelo nome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Disse Moisés: \"Por favor, mostra-me a Tua glória\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Yahweh disse: \"Farei passar toda a minha bondade diante de ti, e diante de ti proclamarei o meu nome, \'Yahweh\'. Eu serei gracioso com quem Eu quiser ser gracioso, e mostrarei misericórdia a quem Eu quiser mostrar misericórdia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Porém Yahweh disse: \"Não poderás ver a Minha face, porque ninguém pode ver a Minha face e viver\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Yahweh disse: \"Vê, eis um lugar próximo de Mim; Tu ficarás sobre esta rocha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Enquanto a Minha glória passar, te colocarei numa fenda da rocha, e te cobrirei com Minha mão até Eu passar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Então, tirarei a Minha mão e verás as Minhas costas, mas a Minha face não será vista\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Yahweh disse para Moisés: \"Corta duas tábuas de pedra como as primeiras tábuas de pedra. Eu escreverei nessas tábuas de pedra as palavras que estavam nas primeiras tábuas de pedras, as tábuas que tu quebraste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Prepara-te pela manhã e sobe o Monte Sinai, e apresenta-te a mim no topo da montanha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Ninguém poderá subir contigo. Não deixe ninguém mais ser visto em nenhum lugar da montanha. Nem manada, nem rebanhos devem pastar em frente à montanha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Então Moisés cortou duas tábuas de pedra como as primeiras, levantou-se de manhã cedo e subiu ao Monte Sinai, como Yahweh havia lhe instruído. Moisés carregou as tábuas de pedra em suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Yahweh desceu em uma nuvem e esteve com Moisés ali, e ele pronunciou o nome \"Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Yahweh passou à frente dele e proclamou: \"Yahweh, Yahweh, Deus é misericordioso e gracioso, não se ira facilmente e é abundante na aliança com fidelidade e confiança,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'mantendo fielmente a aliança por milhares de gerações, perdoando iniquidades, transgressões e pecados. Porém Ele, de maneira nenhuma, livrará o culpado. Ele vai trazer punição para os pecados dos pais sobre os filhos, e sobre os filhos dos filhos, até a terceira e a quarta geração\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Moisés rapidamente prostrou sua cabeça ao chão e adorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Depois ele disse: \"Se agora eu tenho achado favor em Teu olhar, meu Senhor, por favor vem sobre nós, por essas pessoas teimosas. Perdoa nossas iniquidades e nossos pecados, e leva-nos como tua propriedade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Yahweh disse: \"Vê, Eu estou para fazer uma aliança. Perante todo o teu povo, Eu irei fazer maravilhas como as que não foram feitas em toda a terra ou em qualquer nação. Todas essas pessoas, perante ti, verão minhas grandes obras, por isso estou fazendo uma coisa terrível contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Obedece o que estou te ordenando hoje. Eu estou prestes a expulsar de diante de ti os amorreus, os cananeus, os heteus, os perizeus, os haveus e os jebuseus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Tem cuidado para não fazeres alianças com os que habitam a terra para onde estás indo, ou eles se tornarão uma armadilha perante ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Em vez disso, tu deves quebrar seus altares, esmagar seus pilares de pedras sagradas e cortar os postes de Aserá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Pois não deves adorar outros deuses, por mim O SENHOR, cujo nome é \'Ciumento\', sou o Deus ciumento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Tem cuidado para não fazeres alianças com os que habitam a terra, pois eles se prostituem para seus deuses, e sacrificam a eles e te convidarão para que comas algo do sacrifício deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Então tomarás algumas das filhas deles para os teus filhos, e as filhas deles se prostituirão para seus deuses, e eles farão teus filhos se prostituirem para os deuses deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Não faças para ti mesmo deuses de metal fundido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Tu deves manter o festival de pães sem fermento. Como eu lhe comandei, tu deves comer pão sem fermento por sete dias, no tempo fixo, no mês de abib, pois foi no mês de abib que vieste do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Todos os primogênitos são meus, inclusive todos os primogênitos machos do teu rebanho, tanto de vacas quanto de ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Tu deves comprar de volta os primogênitos dos burros com cordeiros, porém se não comprares de volta tu deves quebrar-lhes o pescoço. Tu deves comprar de volta todos os primogênitos de teus filhos. Ninguém deve aparecer perante mim de mãos vazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Tu deves trabalhar por seis dias, porém no sétimo dia tu deves descansar. Mesmo durante o tempo de cultivo e na colheita, tu deves descansar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Tu deves observar o festival das semanas com a primeira produção da colheita de trigo, e tu deves observar o festival da colheita no final do ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Todos os teus homens deverão se apresentar diante de mim, Yahweh, o Deus de Israel, três vezes por ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Pois Eu expulsarei nações de diante de ti e expandirei tuas fronteiras. Ninguém deverá cobiçar tuas terras, quando apareceres diante de mim, Yahweh, teu Deus, três vezes por ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Não oferecerás sangue do meu sacrifício com nenhum fermento, ou nenhuma carne do sacrifício do festival de páscoa, que sobrou pela manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Tu deverás trazer o melhor e o primeiro fruto do teu campo para a minha casa. Não cozinharás um cabrito no leite de sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Yahweh disse a Moisés: \"Escreve estas palavras, pois Eu me compromento com estas palavras que falei, e fiz uma aliança com o povo de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Moisés esteva lá com Yahweh por quarenta dias e quarenta noites; ele não comeu nenhuma comida, nem bebeu água. Ele escreveu nas tábuas as palavras da Aliança, os dez Mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Quando Moisés desceu do Monte Sinai com as duas tábuas do Decreto da Aliança em suas mãos, ele não sabia que a pele de sua face tinha se tornado radiante enquanto falava com Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Quando Arão e todos os israelitas viram Moisés, a pele da face dele estava brilhando, e eles ficaram com medo de se aproximar dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Mas Moisés lhes chamou, e Arão e todos os líderes da comunidade vieram a ele. Depois Moisés falou com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Após isso, todo o povo de Israel veio a Moisés, e ele disse a eles todos os mandamentos que Yahweh tinha dado a ele no Monte Sinai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Depois que Moisés terminou de falar com eles, ele colocou um véu sobre sua face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Sempre que Moisés estava perante Yahweh para falar com Ele, ele removia o véu. Depois ele colocava o véu de volta quando ele ia embora. Ele saía da tenda e dizia aos israelitas o que tinha sido ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Os israelitas viram a face de Moisés brilhando. Porém depois ele colocava o véu sobre sua face de novo até que voltasse a falar com Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Moisés reuniu toda a comunidade dos filhos de Israel e lhes disse: \"Estas são as coisas que Yahweh vos ordenou fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Em seis dias, qualquer trabalho poderá ser feito, todavia, para vós, o sétimo dia será um dia santificado. O dia de sábado será para descansar; é dia santo para Yahweh. Qualquer um que realizar algum trabalho nesse dia deverá morrer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Vós não podereis nem ao menos acender fogo em vossas casas no dia de sábado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Moisé falou a toda comunidade de Israel: \"Isto foi o que Yahweh ordenou:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, '\'separai uma oferta para Yahweh, todos vós que tendes um coração disposto. Trazei uma oferta para Yahweh — ouro, prata, bronze;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'lã azul, roxa e vermelha e linho fino; pelos de cabra;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'peles de carneiro tingidas de vermelho e couro fino; madeira de acácia;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'azeite para as lamparinas do santuário, especiarias para o óleo da unção e fragrância de incenso;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'pedras de ônix e outras pedras preciosas para serem colocadas no colete e no peitoral da veste sacerdotal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Todo homem habilidoso entre vós virá e fará tudo o que Yahweh ordenou —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'o tabernáculo, com sua tenda, sua cobertura, seus colchetes, suas armações, barras, seus postes e suas bases;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'também a arca, com suas varas para transportá-la, a tampa da expiação e a cortina para cobri-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'A mesa, com as varas para transporte com todos os seus utensílios e os pães da presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'O candelabro das luzes, com seus acessórios, suas lâmpadas e o azeite para as lâmpadas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'o altar de incenso, com suas varas para transporte, o óleo da unção e as fragrâncias de incensos; a cortina para a entrada do tabernáculo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'o altar para as ofertas queimadas, com suas grelhas de bronze e varas para o seu transporte e todos os utensílios; a grande bacia de bronze, com sua base.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'As cortinas externas da entrada do pátio, com suas colunas e bases e a cortina para a entrada do pátio;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'as estacas do tabernáculo e do pátio, junto com suas cordas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'as vestes finamente tecidas para servir no lugar santo, as vestes sagradas para Arão, o sacerdote, e seus filhos, para que eles sirvam como sacerdotes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Então, todas as tribos de Israel partiram e se afastaram da presença de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Todo aquele cujo coração o instigava e a quem o seu espírito queria, veio e trouxe uma oferta para Yahweh para a construção do tabernáculo, para todos os objetos do serviço e para as vestes sagradas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Então, vieram homens e mulheres, todos que tinham um coração disposto. Eles traziam broches, brincos, anéis e ornamentos, todos os tipos de jóias de ouro. Todos eles ofereceram ofertas de ouro a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Todos aqueles que tinham lã azul, roxa e vermelha, linho fino, pelos de cabra, peles de ovelhas tingidas de vermelho ou fino couro os trouxeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Todos os que tinham oferta de prata ou bronze trouxeram para Yahweh e todos que tinham madeira de acácia para ser utilizada as trouxeram para serem usadas na obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Toda mulher habilidosa tecia lã com suas mãos e trazia o que havia feito — lã azul, roxa ou vermelha, ou linho fino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Todas as mulheres cujos corações estavam dispostos a fiar os pêlos das cabras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Os líderes trouxeram pedras de ônix e outras pedras preciosas para serem fixadas no colete e no peitoral da veste sacerdotal;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'trouxeram especiarias e azeite para as lâmpadas, para o óleo da unção e para o incenso perfumado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Os israelitas trouxeram uma oferta voluntária para Yahweh; cada homem e cada muher, cujos corações estavam dispostos, trouxeram materiais para a obra que Yahweh ordenara para Moisés realizar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Moisés disse aos israelitas: \"Vede, Yahweh chamou pelo nome a Bezalel, filho de Uri, filho de Hur, da tribo de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Ele encheu Bezalel com Seu Espírito, dando-lhe sabedoria, entendimento e conhecimento para todos os tipos de artesanato,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'para fazer desenhos artísticos e trabalhar com ouro, prata e bronze;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'também para cortar e lapidar pedras e esculpir em madeira — para fazer todos os tipos de artesanato.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Ele colocou isso em seu coração para ensinar, tanto Bezalel quanto Aoliabe, filho de Aisamaque, da tribo de Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Ele os encheu de habilidade para fazer todo o tipo de trabalho, para trabalhar como artesãos, como gravadores, como bordadores em lã azul, roxo e vermelho, linho fino e como tecelões. Eles são artesãos em todos os tipos de trabalho e são desenhistas artísticos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Desse modo, Bezalel e Aoliabe irão trabalhar e também cada pessoa de coração capacitado na qual Deus colocou habilidade e conhecimento para saberem como construir o santo lugar, seguindo as instruções que Ele vos deu para fazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Moisés convocou Bezalel e Aoliabe, e toda pessoa hábil para a qual Yahweh dera destreza, e cujo interior do coração foi movido por Ele para vir e fazer o trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Eles receberam de Moisés todas as ofertas que os israelitas trouxeram para construir o santo lugar. O povo continuou trazendo a Moisés ofertas vonlutárias toda manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Então todas as pessoas capacitadas, trabalhando no santuário vieram do serviço que estavam fazendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Eles disseram a Moisés: \"O povo está trazendo mais do que o necessário para fazer o trabalho que Yahweh nos ordenou fazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Desse modo, Moisés instruiu que ninguém no acampamento trouxesse mais ofertas para a construção do santuáio. Então o povo parou de trazer presentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Eles tinham mais do que materiais suficientes para todo o trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Assim todos os artesãos dentre eles construíram o tarbenáculo com dez cortinas feitas com linho fino e lã azul, roxa e vermelha com desenhos de querumbins. Esse foi o trabalho de Bezalel, um artesão muito capaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'O comprimento de cada cortina era de vinte e oito côvados, com largura de quatro côvados. Todas as cortinas tinham o mesmo tamanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Bezalel juntou cinco cortinas umas com as outras, e outras cinco cortinas ele também as juntou umas com as outras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Ele laçou de azul ao longo da orla da cortina do primeiro grupo, e ele fez o mesmo ao longo da orla do segundo grupo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Ele fez cinquenta laços na primeira cortina e cinquenta laços na orla do segundo grupo opondo-as umas às outras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Ele fez cinquenta ganchos de ouro e uniram as cortinas com eles e assim o tabernáculo juntou-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Bezalel fez cortinas de pelos de cabras para servir como tenda sobre o tabernáculo; ele fez onze dessas cortinas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'O comprimento de cada cortina era de trinta côvados, e a largura de cada cortina era de quatro côvados. Cada uma das onze cortinas era do mesmo tamanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Ele juntou cinco cortinas umas com as outras e outras seis cortinas umas com as outras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Ele fez cinquenta laços na orla da cortina do primeiro grupo, e cinquenta laços ao longo da orla da cortina do segundo grupo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Bezalel fez cinquenta ganchos de bronze para unir a tenda para ser um todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Ele fez, para cobrir o tarbenáculo, uma cobertura de peles de carneiros tingidas de vermelho, e, acima dessas camadas, uma fina cobertura de couro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Bezalel fez tábuas verticais de madeira de acácia para o tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'O comprimento de cada tábua era de dez côvados, e sua largura era de um côvado e meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Existiam dois encaixes em cada tábua para unir uma à outra. Ele fez todas as tábuas do tarbenáculo dessa maneira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Assim ele fez as tábuas para o tarbenáculo. Ele fez vinte tábuas para o lado sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Bezalel fez quarenta bases de prata para ficarem debaixo das vinte tábuas. Existiam duas bases debaixo da primeira tábua, e também duas bases debaixo de cada tábua para os seus dois encaixes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Para o segundo lado do tabernáculo, o lado norte, ele fez vinte tábuas');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'e suas quarenta bases de prata. Havia duas bases debaixo da primeira tábua, duas bases debaixo da próxima tábua e assim por diante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Para os fundos do tabernáculo, ao oeste, Bezalel fez seis tábuas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Ele fez duas tábuas para os cantos dos fundos do tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Essas tábuas eram separadas em seus fundamentos, mas eram unidas no topo pela mesma argola. Era dessa forma em ambos os cantos dos fundos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Existiam oito tábuas, unidas com suas bases de prata. Tinham dezesseis bases ao todo, duas bases debaixo da primeira tábua, duas bases debaixo da próxima tábua, e assim por diante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Bezalel fez traves de madeira de acácia—cinco traves para as tábuas do outro lado do tabernáculo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'cinco traves para as tábuas dos fundos ao ocidente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Ele fez a trave central por entre as tábuas, isto é, parcialmente em cima, de uma extremidade à outra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Ele cobriu as tábuas com ouro. Eles fez as suas argolas com ouro, para servir como suporte para as traves, e também cobriu as barras com ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Bezalel fez o véu de lã azul, roxa e vermelha, e de linho fino, com desenhos de querubins, o trabalho de um habilidoso trabalhador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Ele fez para o véu quatro suportes de madeira de acácia, e os cobriu com ouro. Ele também fez ganchos de ouro para os pilares, e os fundiu com as quatro bases de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Ele pendurou o véu na entrada da tenda. Era feito de lã azul, roxa e vermelha, de lino fino, o trabalho de um bordador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Ele também fez para as tapeçarias cinco pilares com ganchos. Ele cobriu seus topos e suas hastes com ouro. Suas cinco bases eram feitas de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Bezalel fez a arca de madeira de acácia. O seu comprimento era de dois côvados e meio, a sua largura era de um côvado e meio e a sua altura era de um côvado e meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Ele a cobriu por dentro e por fora com ouro puro e fez para ela uma bordadura de ouro ao redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Ele fundiu quatro argolas de ouro para os seus quatro pés, com duas argolas de um lado e duas argolas do outro lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Ele fez varas de madeira de acácia e as cobriu com ouro;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'pôs as varas dentro das argolas, nos lados da arca para carregá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Fez também o propiciatório de ouro puro. O seu comprimento era de dois côvados e meio e a sua largura era de um côvado e meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Bezalel fez dois querubins de ouro batido para as duas extremidades do propiciatório.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Um querubim estava em uma extremidade do propiciatório e o outro querubim estava na outra extremidade. Eles formavam uma só peça com o propiciatório.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Os querubins estendiam as suas asas por cima e cobriam o propiciatório com elas. Eles estavam de frente um para o outro, com as faces voltadas para o propiciatório.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Bezalel fez a mesa de madeira de acácia. O seu comprimento era de dois côvados; a sua largura era de um côvado e a sua altura era de um côvado e meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Ele a cobriu com ouro puro e pôs uma bordadura de ouro puro ao redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Fez uma moldura para ela na largura de quatro dedos, com uma bordadura de ouro para a moldura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Ele fundiu para ela quatro argolas de ouro e as atou nos quatro cantos onde os seus pés estavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'As argolas foram atadas na moldura para receber as varas para carregar a mesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Ele fez as varas de madeira de acácia, por fora, e as cobriu com ouro, para carregar a mesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Ele fez os objetos que estariam sobre a mesa: pratos, colheres, tigelas e jarros a serem usados para derramar as ofertas. Ele os fez de ouro puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Ele fez o candelabro de ouro puro batido; fez o candelabro com sua base e haste. Seus copos, suas bases com folhas e suas flores formavam com ele uma só peça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Seis braços saíam dos seus lados: três braços saíam de um lado do candelabro, e três saíam do outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'O primeiro braço tinha três copos em forma de flor de amêndoa, com folhas na base e uma flor; e no outro braço, três copos feitos em forma de flor de amêndoa, com folhas na base e uma flor. Era a mesma coisa para todos os seis braços que saíam do candelabro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'No próprio candelabro, na haste central, havia quatro copos feitos na forma de flores de amêndoa, com suas bases com folhas e flores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Havia uma base com folhas sob o primeiro par de braços, formando uma só peça com ele; e uma base com folhas sob o segundo par de braços, também formando uma só peça com ele. Da mesma forma, havia uma base com folhas sob o terceiro par de braços, feito em uma só peça com ele. Assim era para todos os seis braços que saíam do candelabro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Suas bases com folhas e braços formavam todos uma só peça com ele, peça trabalhada em ouro puro batido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Bezalel fez o candelabro e suas sete lâmpadas, seus aparadores e seus apagadores de ouro puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Ele fez o candelabro e seus acessórios com um talento de ouro puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Bezalel fez o altar do incenso. Ele o fez de madeira de acácia. O seu comprimento era de um côvado e sua largura de um côvado. Ele era quadrado e sua altura tinha dois côvados. Seus chifres formavam uma só peça com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Ele cobriu o altar do incenso com ouro puro, sua parte superior, seus lados e seus chifres. Fez também uma bordadura de ouro para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Ele fez duas argolas de ouro e as fixou debaixo da bordadura, em lados opostos do altar do incenso. As argolas eram suportes onde passavam as varas para carregar o altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Fez as varas de madeira de acácia e as cobriu com ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Ele fez o óleo santo da unção e incenso aromático, puro, obra de perfumista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Bezalel fez o altar do holocausto de madeira de acácia. Era um quadrado de cinco côvados de comprimento, cinco de largura e três de altura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Ele fez extensões nos seus quatro cantos, no formato de chifres de boi. Os chifres formavam uma só peça com o altar, e ele o cobriu de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Ele fez todos os utensílios do altar: vasilhas para cinzas, pás, pias, os garfos e os braseiros. Ele fez todos esses utensílios de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Ele fez uma grelha para o altar, no formato de uma rede de bronze, embaixo da borda ao redor. Ela chegava até o meio do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Ele fundiu quatro argolas para os quatro cantos da grelha de bronze, como suportes para as varas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Bezalel fez varas de madeira de acácia e cobriu-as com bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Ele atravessou as varas pelos anéis dos lados do altar, para carregá-lo. Ele fez o altar oco, usando tábuas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Bezalel fez a grande pia de bronze com uma base de bronze. Ele fez a pia de espelhos pertencentes às mulheres que serviam à entrada da Tenda do encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Ele fez também o átrio. As cortinas do lado sul do átrio eram de linho fino, de cem côvados de comprimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'As cortinas tinham vinte colunas, com vinte bases de bronze. Havia ganchos anexos às colunas, bem como hastes de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Da mesma forma, do lado norte, havia cortinas de cem côvados, com vinte colunas, vinte bases de bronze, ganchos presos às colunas e hastes de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'As cortinas do lado oeste mediam cinquenta côvados, com dez colunas e bases. Os ganchos e hastes das colunas eram de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'As cortinas também mediam cinquenta côvados no lado leste do átrio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'As cortinas de um dos lados da entrada mediam quinze côvados. Elas tinham três colunas com três bases.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Do outro lado da entrada, havia também cortinas de quinze côvados, com três colunas e três bases.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Todas as cortinas ao redor do átrio eram feitas de linho fino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'As bases das colunas foram feitas de bronze. Os ganchos e hastes nas colunas foram feitos de prata, e o revestimento dos seus capitéis também foi feito de prata. Todas as colunas do átrio eram cobertas de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'A cortina do portão do átrio media vinte côvados. A cortina era feita de azul, vermelho e roxo, linho fino torcido, e media vinte côvados. Media vinte côvados de comprimento e cinco côvados de altura, como as cortinas do átrio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Tinha quatro bases de bronze e ganchos de prata. O revestimento de seus capitéis e de suas hastes era feito de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Todas as estacas das tendas do tabernáculo e do átrio eram feitas de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Este é o inventário das coisas para o tabernáculo, o tabernáculo dos Decretos da Aliança, seguindo as instruções de Moisés. Foi obra dos levitas debaixo da direção de Itamar, filho do sacerdote Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Bezalel, filho de Uri, filho de Hur, da tribo de Judá, fez tudo o que Yahweh havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Aoliabe, filho de Aisamaque, da tribo de Dã, trabalhou junto de Bezalel como um escultor, um habilidoso operário, e como um tecelão em lã azul, escarlate e púrpura e em linho fino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Todo o ouro que foi usado para o projeto, em todo o trabalho ligado ao lugar santo, isto é, o ouro da oferta, foi vinte e nove talentos e setecentos e trinta siclos, segundo a medida do siclo do santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'A prata dada pela comunidade pesou cem talentos e mil setecentos e setenta e cinco siclos, conforme o padrão do siclo do santuário,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'ou um beca por homem, isto é, meio siclo, segundo a medida do siclo do santuário. Essa representação foi alcançada com base em todos os que foram contados no censo, da idade de vinte anos para cima, que foram seiscentos e três mil quinhentos e cinquenta homens, ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Cem talentos de prata foram fundidos para fazer as bases do santuário e as bases das cortinas: cem bases, um talento para cada base.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Com os mil setecentos e setenta e cinco siclos de prata restantes, Bezalel fez os ganchos para as colunas, cobriu os seus capitéis, e fez as hastes para elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'O bronze da oferta pesou setenta talentos e dois mil e quatrocentos siclos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Com isso, ele fez as bases da entrada da Tenda do encontro, o altar de bronze, sua grelha de bronze, todo o equipamento para o altar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'as bases do átrio, as bases da entrada do átrio, todas as estacas de tenda para o tabernáculo e todas as estacas de tenda para o átrio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Com a lã azul, roxa e vermelha fizeram vestes finamente tecidas para cultuar no lugar santo. Eles fizeram as vestes de Arão para o lugar santo, conforme Yahweh havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Bezalel fez o colete de ouro e de lã azul, roxa e vermelha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Eles amassaram lâminas de ouro e as cortaram em fios, para entrelaçar com lã azul, roxa e de vermelha e com linho fino ― trabalho de um artesão habilidoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Eles fizeram ombreiras para o colete, atadas a ele nas suas duas pontas superiores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Seu cinto, finamente tecido, era como o colete, feito uma única peça com ele, feito de linho fino trançado que era dourado, azul, roxo e vermelho, conforme Yahweh havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Eles encravaram as pedras de ônix embutida em conjuntos de ouro, esculpidas com gravuras com os nomes dos doze filhos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Bezalel as pôs sobre as ombreiras do avental, como pedras para lembrar a Yahweh os doze filhos de Israel, como Yahweh tinha ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Ele fez o peitoral, o trabalho de um habilidoso artesão, modelado como o colete. Ele o fez de ouro, de lã azul, roxa e vermelha, e de linho fino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Era quadrado. Dobraram o peitoral em dois. Era de um palmo de cumprimento e de um palmo de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Eles fixaram nele quatro filas de pedras preciosas. A primeira fila tinha um rubi, um topázio, uma granada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'A segunda fila tinha uma esmeralda, uma safira e um diamante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'A terceira fila tinha um jacinto, uma ágata e uma ametista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'A quarta fila tinha um berilo, uma ônix, e um jaspe. As pedras foram montadas em ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'As pedras foram agrupadas de acordo com o nome dos doze filhos de Israel, cada uma delas ordenadas pelo nome. Eram esculpidas como um desenho em um anel de selar, cada nome correspondendo a uma das doze tribos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Sobre o peitoral eles fizeram correntes como cordas trançadas, trabalho de ouro puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Eles fizeram dois conjuntos de ouro e dois anéis de ouro, e uniram os dois aneis às duas pontas do peitoral.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Eles puseram as duas correntes trançadas de ouro nos dois anéis nas pontas do peitoral.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Eles uniram as duas outras pontas das correntes trançadas aos dois conjuntos. Uniram-nas às ombreiras na frente do colete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Eles fizeram dois anéis de ouro e os puseram sobre as duas outras pontas do peitoral, sobre a estola próxima à borda interna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Eles fizeram mais dois anéis de ouro e os uniram ao fundo do peitoral, na frente do colete, perto da sua costura, acima do cinto finamente tecido do colete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Eles amarraram o peitoral por seus anéis aos anéis do colete com um cordão azul, de modo que podia ser amarrado bem acima do cinto finamente tecido do colete. Assim foi feito para que o peitoral não se soltasse do colete. Isso foi feito como Yahweh havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Bezalel fez a túnica do colete completamente de tecido roxo ― trabalho de um tecelão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Ela possuía uma abertura bem no meio para a cabeça. A abertura tinha uma trança rodeada em suas extremidades de modo que não se descosturava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Sobre a bainha do fundo, eles fizeram romãs de lã azul, roxa e vermelha e de linho fino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Eles fizeram sinos de ouro puro, e os puseram entre as romãs ao redor da extremidade inferior da túnica, entre as romãs ―');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'um sino e uma romã, um sino e uma romã ― na extremidade da túnica para Arão cultuar. Isso foi como Yahweh havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Eles fizeram as capas de linho fino para Arão e para seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Eles fizeram o turbante de linho fino, a mitra ornada de linho fino, o forro de linho fino,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'e o cinto de linho fino e de lã azul, roxa e vermelha ― trabalho de um bordador. Isso foi como Yahweh havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Eles fizeram a lâmina da coroa sagrada de puro ouro; eles esculpiram nela, como uma gravura: DEDICADA A YAHWEH.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Eles amarraram ao turbante uma corda azul ao topo do turbante. Isso foi como Yahweh tinha ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Então a obra do tabernáculo, a tenda do encontro, foi concluída. O povo de Israel fez tudo. Eles seguiram todas as instruções que Yahweh havia dado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Eles trouxeram o tabernáculo a Moisés ― a tenda e todos os seus utensílios, seus fechos, tábuas, vigas, colunas e bases.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'A cobertura de peles de carneiro, tingidas de vermelho, a cobertura de couro de animais marinhos, o véu protetor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'a arca da aliança com suas varas e tampa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'Eles trouxeram a mesa, todos os seus utensílios e os pães da presença;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'o candelabro de ouro puro e suas lâmpadas alinhadas, com seus assessórios e o óleo para as lâmpadas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'o altar de ouro, óleo de unção e o incenso aromático; a cortina para a entrada do tabernáculo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'o altar de bronze com sua grelha de bronze e suas varas e utensílios e a bacia com sua base.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Eles trouxeram as cortinas para o pátio com suas colunas e bases, e a cortina para a entrada do pátio, suas cordas e estacas da tenda; e todos os utensílios para o culto no tabernáculo, a tenda do encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Eles trouxeram as vestes finas para ministrar no santo lugar, as vestes sagradas para o sacerdote Arão e seus filhos, para eles ministrarem como sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Assim, o povo de Israel fez todo o trabalho de acordo com o que Yahweh havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Moisés examinou todo o trabalho e observou o que haviam feito. Então Moisés os abençoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Então Yahweh falou a Moisés,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '\"No primeiro dia do primeiro mês, montarás o tabernáculo, a tenda do encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Colocarás a arca da aliança dentro da tenda e a cobrirás com um véu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Deverás trazer a mesa e pôr em ordem seus pertences sobre ela. Então deverás trazer o candelabro e colocar suas lâmpadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Porás o altar de incenso de ouro perante a arca da aliança, e deverás pôr cortinas na entrada do tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Colocarás o altar do holocausto à frente da entrada do tabernáculo, a tenda do encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Porás a pia entre a tenda do encontro e o altar, e a encherás de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Armarás o pátio em volta do tabernáculo, e estenderás a cortina à entrada do pátio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Tomarás o óleo da unção e ungirás o tabernáculo e tudo o que estiver nele. Dedicarás todos o seus utensílios a Mim; então serão santificados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Ungirás o altar do holocausto e todos os seus utensílios. Dedicarás o altar a Mim, e ele se tornará santíssimo para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Ungirás a pia de bronze e sua base, e a dedicarás a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Trarás Arão e seus filhos à entrada da tenda do encontro e deverás lavá-los com água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Vestirás Arão com as vestes dedicadas a Mim, ungirás a ele e o dedicarás a Mim para que ele Me sirva como Meu sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Trarás seus filhos e os vestirás com capas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Tu os ungirás como ungiste o pai deles, para que Me sirvam como sacerdotes. A unção deles lhes dará um sacerdócio permanente por todas as suas gerações.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Isso foi o que Moisés fez. Ele seguiu tudo o que Yahweh havia ordenado. Ele fez todas essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Então o tabernáculo foi levantado no primeiro dia do primeiro mês, no segundo ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Moisés levantou o tabernáculo, firmou suas bases, montou suas tábuas, uniu suas vigas, e firmou suas estacas e postes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Ele espalhou a cobertura sobre o tabernáculo como uma tenda, da maneira como Yahweh havia mandado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Pôs as Leis da Aliança dentro da arca. Colocou também os varais na arca e o propiciatório sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Trouxe a arca para dentro do tabernáculo. Esticou o véu para proteger a arca da aliança, como Yahweh havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Colocou a mesa dentro da tenda do encontro, no lado norte do tabernáculo, fora do véu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Colocou os pães em ordem na mesa diante de Yahweh, como Yahweh ordenou a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Ele pôs o candelabro dentro da tenda do encontro, em frente à mesa, no lado sul do tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Acendeu as lâmpadas diante de Yahweh, como Yahweh ordenou a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Pôs o altar de incenso de ouro na tenda do encontro, diante do véu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Queimou sobre ele incenso aromático, como Yahweh ordenou a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Pendurou a cortina na entrada do tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Pôs o altar para o sacrifício na entrada do tabernáculo, a tenda do encontro. Ele ofereceu o holocausto e a oferta de cereais sobre o altar, como Yahweh ordenou a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Colocou a pia de bronze entre a tenda do encontro e o altar, e pôs água dentro dela para lavar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Moisés, Aarão e seus filhos lavavam as mãos e os pés na bacia');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'toda vez que entravam na tenda do encontro e iam até o altar. Lavavam-se, como Yahweh ordenou a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Moisés levantou o átrio em volta do tabernáculo e do altar. Esticou a cortina na entrada do pátio. Dessa forma, Moisés terminou o trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Então a nuvem cobriu a tenda do encontro, e a glória de Yahweh encheu o tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Moisés não pôde entrar na tenda do encontro, pois a nuvem estava sobre ela, e porque a glória de Yahweh encheu o tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Toda vez que a nuvem subia de sobre o tabernáculo, o povo de Israel seguia sua jornada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Porém, se a nuvem não subisse do tabernáculo, então o povo não seguia. Eles ficavam até o dia em que ela subisse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Pois a nuvem de Yahweh estava sobre o tabernáculo durante o dia, e Seu fogo durante a noite, à vista de todo o povo de Israel, em todas as suas jornadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Yahweh chamou Moisés e falou a ele na Tenda do Encontro, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, '\"Fala ao povo de Israel e diz: \'Quando alguém dentre vós trouxer uma oferta a Yahweh, trazei como oferta um animal do vosso rebanho, seja ele de pequeno ou grande porte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Se a oferta dele for holocausto de gado graúdo, ele deverá oferecer um macho sem defeito na entrada da Tenda do Encontro, para que seja aceito diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Ele porá a mão sobre a cabeça do animal oferecido em holocausto, e então, a oferta será aceita em seu favor, para sua expiação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Ele sacrificará o novilho diante de Yahweh. Os sacerdotes, filhos de Arão, apresentarão o sangue e o aspergirão sobre o altar na entrada da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Então ele esfolará o holocausto e o cortará em pedaços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'E os filhos de Arão, o sacerdote, colocarão fogo no altar e lenha para o fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Os sacerdotes, filhos de Arão, colocarão em ordem os pedaços, a cabeça e a gordura sobre a lenha que está no fogo do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Mas as vísceras e as pernas, as lavarão com água. E então, o sacerdote queimará tudo no altar como holocausto. Isso produzirá um aroma agradável para Mim; será uma oferta queimada para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Se a oferta for holocausto de gado miúdo, de cordeiro ou de cabrito, ele oferecerá um macho sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Ele o matará do lado norte do altar diante de Yahweh. Os sacerdotes, filhos de Arão, aspergirão o sangue por todos os lados do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Então, ele o cortará em pedaços, juntamente com a cabeça e a gordura, e o sacerdote porá os pedaços em ordem sobre lenha que está no fogo sobre o altar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'mas as vísceras e as pernas serão lavadas com água. Então o sacerdote oferecerá tudo isso e queimará no altar. Isso é um holocausto, e produzirá um aroma agradável a Yahweh; será uma oferta feita para Ele pelo fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Se a oferta a Yahweh for holocausto de aves, então trará como oferta rolinhas ou pombinhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'O sacerdote a trará sobre o altar, destroncará a cabeça da ave e a queimará sobre o altar. Então ele fará o sangue escorrer ao lado do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Ele removerá o papo e as penas, e lançará sobre o lugar das cinzas, do lado leste do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Ele a cortará pelas asas, mas não a dividirá em duas partes. Então o sacerdote a queimará sobre o altar, sobre a lenha que está no fogo. Isso será um holocausto, e produzirá um aroma agradável para Yahweh; será uma oferta feita para Ele pelo fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Quando alguém trouxer uma oferta de cereais a Yahweh, sua oferta deverá ser farinha fina, e sobre ela derramará óleo e colocará incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Ele levará a oferta aos sacerdotes, filhos de Arão, e lá o sacerdote pegará uma mão cheia de farinha fina com o óleo e o incenso sobre ela. Então o sacerdote queimará a oferta como memorial no altar. Isto produzirá um aroma agradável a Yahweh. Será uma oferta queimada a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'O que sobrar da oferta de grãos pertencerá a Arão e a seus filhos. É oferta santíssima a Yahweh dentre aquelas queimadas a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Quando ofereceres uma oferta de cereais sem fermento, assada em um forno, deve ser pão macio de boa farinha misturada com óleo, ou pão duro sem fermento, e untado com óleo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Se a tua oferta de grãos for assada com uma panela de ferro plana, deve ser da boa farinha, sem fermento e misturada com óleo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Em pedaços a dividirás e derramarás óleo sobre ela. Essa é uma oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Se a tua oferta de cereais for assada em uma panela, deve ser feita com boa farinha e óleo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Deverás trazer a oferta de cereais feita dessas coisas a Yahweh, e será apresentada ao sacerdote, que a trará ao altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Então, o sacerdote tomará uma parte da oferta de cereais, oferecida como memorial, e a queimará no altar. Será uma oferta queimada, e produzirá um aroma agradável a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'O que sobrar da oferta de cereais pertencerá a Arão e a seus filhos. É oferta santíssima a Yahweh, dentre aquelas queimadas a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Nenhuma oferta de cereais que ofereceres a Yahweh deverá ser feita com fermento, porque não deverás queimar nenhum fermento, nem mel, como uma oferta queimada a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Tu oferecerás as ofertas a Yahweh como um dos primeiros frutos, mas elas não serão usadas como oferta de aroma agradável sobre o altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Deverás temperar cada oferta de cereais com sal. Nunca deverás deixar que o sal da aliança do teu Deus, falte na tua oferta de cereais. Deverás oferecer sal em todas as vossas ofertas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Se ofereceres uma oferta de cereais dos primeiros frutos a Yahweh, oferecerás grãos frescos torrados ao fogo e, depois, moídos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Então, deverás colocar óleo e incenso sobre ela. Essa é uma oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Depois o sacerdote queimará parte dos grãos moídos, o óleo e o incenso como oferta memorial. Essa é uma oferta queimada a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Se alguém oferecer um sacrifício pacífico, oferecendo um animal do rebanho, quer seja macho ou fêmea, ele deve oferecer um animal sem defeitos diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Ele porá a mão na cabeça da sua oferta e a matará na porta da tenda do encontro. Então os filhos de Arão, os sacerdotes, aspergirão o sangue da oferta nas bordas do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'O homem oferecerá o sacrifício pacífico oferecendo-o pelo fogo a Yahweh. A gordura que cobre ou que está conectada às vísceras,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'os dois rins, a gordura aderente a eles junto aos lombos e a pele do fígado com os rins—ele irá remover tudo isto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Os filhos de Arão queimarão isso no altar com o holocausto, o qual está na lenha que está no fogo. Isso irá produzir um doce aroma para Yahweh; será uma oferta feita a ele pelo fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Se o sacrifício pacífico de um homem a Yahweh é do rebanho; macho ou fêmea, ele deve oferecer um sacrifício sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Se ele oferecer um cordeiro pelo seu sacrifício, então ele deve oferecê-lo diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Ele porá sua mão sobre a cabeça do seu sacrifício e o matará diante da tenda do encontro. Então os filhos de Arão arspergirão o sangue nas bordas do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'O homem oferecerá um sacrifício pacífico como uma oferta queimada a Yahweh. A gordura, a cauda gorda inteira cortada perto ao espinhaço, a gordura que cobre as vísceras e toda gordura que está perto das vísceras,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'os dois rins e a gordura deles, que está no quadril, e a gordura aderente ao fígado, com os rins—ele irá remover tudo isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'E o sacerdote queimará tudo isso no altar como oferta queimada de alimento a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'E se a oferta do homem é uma cabra, então ele a oferecerá diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Ele porá sua mão na cabeça da cabra e a matará diante da tenda do encontro. Então os filhos de Arão aspergirão o sangue nas bordas do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'O homem oferecerá sua oferta queimada a Yahweh. Ele removerá a gordura que cobre as vísceras, e toda a gordura das vísceras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Ele também removerá os dois rins e a gordura deles, que está nos lombos, a gordura aderente ao fígado com os rins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'O sacerdote queimará tudo isso no altar como uma oferta queimada de alimento para produzir um aroma agradável. Toda a gordura pertence a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Será uma lei permanente através das gerações do teu povo em todo o lugar em que vós fizerdes vosso lar, que vós não deveis comer gordura ou sangue\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, '\"Diz ao povo de Israel: \'Quando alguém pecar sem intenção de fazê-lo, praticando qualquer das coisas que Yahweh recomendou que não se fizesse, e, se ele fizer alguma coisa que é proibida, deverá ser feito como se descreve a seguir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Se for o sumo sacerdote que pecar de forma a trazer culpa sobre o povo, então oferecerá pelo seu pecado um novilho sem defeito como uma oferta a Yahweh pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Ele deve trazer o novilho à entrada da Tenda do Encontro, diante de Yahweh, impor sua mão sobre o novilho e matá-lo diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'O sacerdote ungido pegará um pouco do sangue do novilho e o trará para a Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'O sacerdote molhará seu dedo no sangue e aspergirá um pouco dele sete vezes perante Yahweh, diante do véu do santíssimo lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'E o sacerdote colocará, diante de Yahweh, um pouco do sangue nos chifres do altar de incenso, que está na tenda do encontro, e despejará o sangue restante do novilho na base do altar do holocausto, que fica na entrada da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Ele removerá toda a gordura do novilho da oferta pelo pecado: A gordura que cobre as vísceras, toda a gordura que está junto delas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'os dois rins, a gordura que está sobre eles, ao lado dos lombos, e o lóbulo do fígado juntamente com os rins — ele deverá retirar tudo isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Ele retirará tudo, assim como ele o faz com a novilha do sacrifício de ofertas pacíficas. Então, o sacerdote queimará essas partes no altar do holocausto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'O couro do novilho e as sobras de carne, junto com a cabeça, pés, víceras e seu excremento;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'todo o restante das partes do novilho — ele levará para fora do acampamento, para um lugar onde se purificam para Mim, onde despejam as cinzas; queimarão aquelas partes sobre a lenha. Eles devem queimar aquelas partes onde despejam as cinzas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Se toda a congregação de Israel pecar sem desejar fazê-lo, se estiver sem consciência de que pecou, e tiver praticado qualquer das coisas que Yahweh recomendou que não fizesse, e se for culpada,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'então, quando o pecado que cometeu se tornar conhecido, a congregação deverá oferecer um novilho como oferta pelo pecado e trazê-lo diante da tenda do encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Os anciãos da congregação imporão suas mãos sobre a cabeça do novilho, perante Yahweh, e o novilho será morto diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'O sacerdote ungido trará um pouco do sangue do novilho para a Tenda do Encontro');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'e molhará o dedo no sangue e o aspergirá sete vezes perante Yahweh, diante do véu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Ele colocará um pouco do sangue nos chifres do altar, diante de Yahweh, que está na Tenda do Encontro, e despejará todo o sangue na base do altar do holocausto que fica na entrada da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Ele retirará toda a gordura e a queimará no altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Isso é o que ele deve fazer com o novilho. Da mesma forma que ele fez com o das ofertas pelo pecado, assim fará com este novilho, e o sacerdote fará a expiação para o povo, e eles serão perdoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Ele levará o novilho para fora do acampamento e o queimará assim como fez com o primeiro novilho. Esta é a oferta de pecado pela assembleia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Quando um líder pecar sem intenção, praticando qualquer coisa que Yahweh, seu Deus, ordenou que não fizesse, e, se ele for culpado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'então, quando o pecado cometido por ele for de seu conhecimento, deverá trazer para seu sacrifício um bode, macho sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Ele imporá sua mão sobre a cabeça do bode e o matará no lugar onde oferecem o holocausto diante de Yahweh. Esta é uma oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'O sacerdote pegará o sangue da oferta pelo pecado com seus dedos e o colocará nos chifres do altar do holocausto e despejará o restante do sangue na base do altar do holocausto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Ele queimará toda a gordura no altar, tal como o fez com a gordura do sacrifício de ofertas pacíficas. O sacerdote fará a expiação pelo líder, referente a seu pecado, e o líder será perdoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Se qualquer pessoa comum pecar sem intenção, praticando qualquer das coisas que Yahweh ordenara que não se fizesse, e se ele for culpado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'então, quando ele perceber o pecado que cometeu, deverá trazer para seu sacrifício uma cabra, uma fêmea sem defeito, como oferta pelo pecado que cometeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Ele imporá a mão sobre a cabeça do animal, da oferta pelo pecado, oferecendo-a e matando-a no lugar do holocausto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'O sacerdote tirará um pouco do sangue com seus dedos e o colocará nos chifres do altar do holocausto. Ele despejará todo o restante do sangue na base do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Ele retirará toda a gordura, da mesma forma que é retirada no sacrifício de ofertas pacíficas. O sacerdote a queimará no altar, como aroma agradável para Yahweh. O sacerdote fará a expiação do pecado, e ele será perdoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Se o homem trouxer um cordeiro e seu sacrifício for uma oferta pelo pecado, ele trará uma fêmea sem defeito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'imporá a mão sobre a cabeça do animal, da oferta pelo pecado, e o matará como oferta pelo pecado, no lugar onde realizaram o holocausto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'O sacerdote tirará um pouco do sangue das ofertas pelo pecado, com seus dedos, e o colocará nos chifres do altar do holocausto. Ele despejará todo o restante do sangue na base do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Ele cortará fora toda a gordura dele, da mesma forma que a gordura do cordeiro é retirada no sacrifício de ofertas pacíficas e o sacerdote a queimará no altar sobre os holocautos oferecidos a Yahweh. O sacerdote fará a expiação pelo seu pecado, e o homem será perdoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Se alguém pecar porque não testemunhou quando ele tiver observado alguma coisa sobre a qual é requerido que testemunhe, se ele tiver visto ou ouvido sobre isso, ele será responsabilizado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Ou se alguém tocar em qualquer coisa que Deus considera imunda, seja um cadáver de animal selvagem impuro, ou de um animal doméstico que já tenha morrido, ou de animal que rasteja, mesmo que a pessoa não tenha tido a intenção de tocá-lo, ele ficará impuro e será culpado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Ou se ele tocar a impureza de alguém, seja o que for, ainda que sem consciência, então ele será culpado quando souber disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Ou, se alguém jura precipitadamente com seus lábios, seja para fazer o mal ou o bem, qualquer que seja o juramento deste homem, mesmo que inconscientemente, quando ele souber disso, então será culpado de todas essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Quando alguém é culpado de alguma dessas coisas, ele deverá confessar qualquer pecado que tenha cometido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Então, deverá trazer uma oferta para Yahweh pela culpa do pecado que cometeu. Um animal fêmea do rebanho, seja ovelha ou cabra, por oferta pela culpa, e o sacerdote fará a expiação por ele no que diz respeito ao seu pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Se ele não tiver condições de comprar uma ovelha, então poderá trazer a Yahweh, como oferta pela culpa, duas rolinhas ou dois pombinhos, um pela oferta da culpa e outra para holocausto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Ele deve trazê-las ao sacerdote, que irá oferecê-las primeiro por oferta do pecado — ele irá torcer-lhe o pescoço, sem, entretanto, arrancar-lhe a cabeça do corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Então, ele aspergirá parte do sangue da oferta pela culpa sobre um lado do altar e escorrerá o restante do sangue na base do altar. Isso será a oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Ele deve oferecer o segundo pássaro como holocausto, como está descrito nas instruções, e o sacerdote irá fazer expiação por ele, pelo pecado que cometeu. Então, a pessoa será perdoada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Mas, se ele não pode comprar duas rolinhas ou dois pombinhos, então deve trazer como sacrifício pelo seu pecado um décimo de um efa de boa farinha por oferta pelo pecado. Ele não deverá colocar azeite ou incenso nela, porque isso é uma oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Ele deve levá-la ao sacerdote, que pegará um punhado dela como oferta memorial, e então a queimará no altar, por cima das ofertas queimadas para Yahweh. Essa é a oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'O sacerdote fará uma expiação por qualquer pecado que a pessoa tenha cometido, e essa pessoa será perdoada. As sobras da oferta pertencerão ao sacerdote, como ofertas de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Então Yahweh falou a Moisés dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '\"Se alguém violar um mandamento e pecar contra as coisas que pertencem a Yahweh, mas o fizer sem intenção, então deve trazer sua oferta pela culpa a Yahweh. Essa oferta deve ser um carneiro sem defeito do rebanho; isso deve ser avaliado em siclos de prata — os siclos do santuário — como uma oferta pela culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Ele deve restituir a Yahweh pelo que fez de errado em relação ao que é santo; deve adicionar uma quinta parte e dá-la ao sacerdote. Então, o sacerdote irá fazer expiação por ele com o cordeiro da oferta pela culpa, e essa pessoa será perdoada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Se alguém pecar e fizer qualquer coisa que Yahweh ordenou que não seja feito, mesmo que sem consciência, ele ainda assim é culpado, e deve carregar sua própria culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Ele deverá trazer ao sacerdote, como oferta pela culpa, um carneiro sem defeito do rebanho, que será devidamente avaliado. Então, o sacerdote fará expiação por ele relativa ao pecado que cometeu, e mesmo que seja inconsciente, ele será perdoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'É uma oferta pela culpa, pois certamente é culpado diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '\"Se alguém pecar e quebrar um mandamento contra Yahweh, como agir falsamente com seu próximo sobre algo emprestado a ele, ou, se ele trapacear ou roubá-lo, ou extorqui-lo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'ou achar algo que ele perdeu e mentir sobre isso, jurando falsamente, ou em qualquer coisa como estas, nas quais as pessoas pecam,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'então, ao vir isso à tona, se ele pecou, e for culpado, que restaure o que quer que tenha roubado ou extorquido, ou foi pego de empréstimo por ele ou algo perdido que ele achou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Ou, se ele mentiu sobre qualquer coisa, ele deve restaurar em sua totalidade e deve adicionar um quinto a mais para pagar àquele de quem lhe foi emprestado, no dia em que for declarado culpado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Então, ele deve trazer sua oferta pela culpa a Yahweh: um carneiro sem defeito do rebanho, que tenha o mesmo valor, como uma oferta pela culpa, será trazida ao sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'O sacerdote fará expiação por ele diante de Yahweh, e ele será perdoado do pecado que o tornará culpado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Então, Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, '\"Dá ordem a Arão e a seus filhos, dizendo: \'Esta é a lei do holocausto: o holocausto deve estar no coração do altar, por toda a noite até a manhã, e o fogo do altar ficará queimando continuamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'O sacerdote colocará suas vestes de linho e também colocará seus calções de linho. Ele apanhará as cinzas que restaram depois que o fogo consumiu o holocausto no altar e as colocará ao lado do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Ele tirará suas vestes e colocará novas vestimentas, para levar as cinzas para fora do acampamento a um lugar limpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'O fogo no altar será mantido aceso. Ele não deve ser apagado e o sacerdote queimará lenha sobre o altar toda manhã. Ele colocará a oferta queimada como foi pedido e queimará no altar a gordura das ofertas pacíficas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'O fogo deve ser mantido aceso no altar continuamente. Não deve ser apagado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Esta é a lei da oferta de cereais: Os filhos de Arão a oferecerão a Yahweh diante do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'O sacerdote tomará um punhado da farinha mais fina da oferta de cereais e do azeite e do incenso que está sobre a oferta de cereais e ele a queimará no altar como memorial de aroma agradável a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Arão e seus filhos comerão o que restar da oferta. Isso deve ser comido sem fermento em um lugar santo. Eles o comerão no pátio da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Não deve ser assado com fermento. Eu lhes dei como a parte que lhes cabe de Minhas ofertas queimadas. É coisa santíssima, como oferta pelo pecado e como oferta pela culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Por todo o tempo que virá para as gerações do teu povo, todo homem descendente de Arão pode comer isso como sua porção, tomada das ofertas queimadas a Yahweh. Qualquer que as tocar se tornará sant\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Então, Yahweh falou a Moisés novamente, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, '\"Esta é a oferta de Arão e de seus filhos, a qual eles oferecerão a Yahweh no dia em que forem ungidos: a décima parte de um efa da farinha mais fina, como uma oferta queimada contínua, metade dela pela manhã e metade à tarde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Isso será feito com azeite em uma assadeira. Quando estiver embebido, trarás para dentro. Em pedaços cozidos, tu oferecerás a oferta de cereais como um aroma agradável a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'O filho do sumo sacerdote que está se tornando o novo sumo sacerdote dentre seus filhos a oferecerá, como mandamento perpétuo, tudo isso deve ser queimado a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Toda oferta queimada do sacerdote será completamente queimada. Não deve ser comida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Yahweh falou a Moisés novamente, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, '\"Fala a Arão e a seus filhos, dizendo: \'Esta é a lei da oferta pelo pecado: a oferta pelo pecado deve ser sacrificada no lugar onde o holocausto é sacrificado diante de Yahweh; é algo santíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'O sacerdote, que a oferece pelo pecado, a comerá. Ela deve ser comida em um lugar santo, no pátio da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Qualquer coisa que tocar a carne da oferta se tornará santa, e, se o sangue for aspergido em alguma roupa, tu deves lavar a parte em que foi aspergido em um lugar santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Mas o pote de barro em que for cozida deve ser quebrado. Se for cozida em um pote de bronze, este deve ser esfregado e lavado em água limpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Qualquer homem dentre os sacerdotes poderá comer alguma dessas coisas, pois são santíssimas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Porém nenhuma oferta pelo pecado deve ser comida, cuja parte do sangue é trazida para dentro da tenda do encontro, para fazer expiação no lugar santo. Esta deve ser queimada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Esta é a lei da oferta pela culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'É santíssima. Eles deverão sacrificar o animal oferecido pela culpa no lugar em que sacrificam o holocausto e devem aspergir seu sangue por todos os lados do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Toda a gordura contida nela será oferecida: a gordura da cauda, a gordura de suas vísceras,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'os dois rins e a gordura neles, que estão perto dos lombos, e que cobre o fígado, com os rins — tudo isso deve ser tirado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'O sacerdote deverá queimar essas partes no altar como uma oferta feita pelo fogo a Yahweh. Esta é a oferta pela culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Todo homem entre os sacerdotes deve comer parte desta oferta. Deve ser comida em um lugar santo, pois é santíssima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'A oferta pelo pecado é como a oferta pela culpa. A mesma lei se aplica a ambas. Elas pertencem ao sacerdote que fizer expiação com elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'O sacerdote, que oferecer o holocausto de alguém, deve ter para si o couro desta oferta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Toda oferta de cereais, que for assada em um forno, e toda oferta semelhantemente cozida em uma frigideira ou em uma assadeira pertencerá ao sacerdote qua a oferecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Toda oferta de cereais, seja seca ou misturada com azeite, pertencerá igualmente a todos os descendentes de Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Esta é a lei do sacrifício da oferta pacífica, a qual o povo oferecerá a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Se alguém a oferecer com o propósito de dar graças, então deve oferecê-la com um sacrifício de bolos feitos sem fermento, mas misturados com azeite, de bolos feitos sem fermento, mas amassados com azeite e de bolos feitos com farinha fina, que é misturada com azeite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Também para o propósito de dar graças, ele deve oferecer, com esta oferta pacífica, bolos de pães feitos com fermento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Ele deve oferecer um de cada tipo desses sacrifícios como uma oferta apresentada a Yahweh. Isso pertencerá ao sacerdote que aspergir o sangue da oferta pacífica no altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Quem apresenta uma oferta pacífica com o propósito de dar graças deve comer da carne de sua oferta no dia do sacrifício. Ele não deve deixar nada sobrar até a manhã seguinte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Mas, se o sacrifício de sua oferta é para o propósito de um voto, ou com o propósito de uma oferta espontânea, a carne deve ser comida no dia que ele a oferecer em sacrifício, mas qualquer coisa que sobrar disso pode ser comida no dia seguinte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'De qualquer modo, qualquer carne do sacrifício, que perdurar ao terceiro dia, deve ser queimada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Se alguma carne do sacrifício de uma oferta pacífica de alguém for comida ao terceiro dia, ela não será aceita, nem terá valor para quem a ofereceu. Será algo abominável, e a pessoa que a comer carregará a culpa de seu pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Qualquer carne que tocar alguma coisa impura não deve ser consumida. Deve ser queimada. Quanto ao resto da carne, qualquer um que é limpo pode comê-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Contudo, uma pessoa impura, que comer carne do sacrifício de uma oferta pacífica que pertence a Yahweh, essa pessoa deve ser cortada de seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Se alguém tocar algo impuro — tanto impureza de homem, ou impureza de besta, ou alguma coisa impura ou repulsiva, e se ele depois comer da carne do sacrifício da oferta pacífica que pertence a Yahweh, esta pessoa deve ser eliminada de meio do seu povo\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Então Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, '\"Fala ao povo de Israel e diga: \'Não comais gordura alguma de boi ou de ovelha ou de bode.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'A gordura do animal que morreu sem ser em um sacrifício, ou a gordura de um animal degolado por animais selvagens, deve ser usada para outros propósitos, mas certamente não devais comê-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Qualquer pessoa que comer da gordura do animal que pode ser oferecido como oferta queimada a Yahweh deve ser eliminada do meio de seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Não comais nenhum sangue em nehuma de suas casas, quer seja de um pássaro ou de um animal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Qualquer pessoa que comer sangue deve ser eliminada do meio de seu povo\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Então Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, '\"Fala ao povo de Israel e diz: \'Aquele que oferecer uma oferta pacífica a Yahweh deve trazer parte desse sacrifício a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'A oferta para Yahweh deve ser queimada e trazida com suas próprias mãos. Ele deve trazer a gordura com o peitoral, para que seja uma oferta erguida, apresentada diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'O sacerdote deve queimar a gordura no altar, mas o peito deverá pertencer a Arão e a seus descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Vós deveis dar a coxa direita da oferta ao sacerdote como um presente, à parte do sacrifício de suas ofertas pacíficas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'O sacerdote, um dos descendentes de Arão, que oferece o sangue da oferta pacífica e a gordura — ele terá a coxa direita como sua porção da oferta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Pois Eu tenho tomado do povo de Israel o peito e a coxa da oferta apresentada e erguida a Mim, e Eu as dei a Arão, o sumo sacerdote e a seus descendentes; essas serão sempre a porção dos sacrifícios das ofertas pacíficas feitas pelo povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Esta é a porção de Arão e seus descendentes das ofertas queimadas a Yahweh, no dia que Moisés os apresentou para servir a Yahweh no ofício de sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Esta é a porção que Yahweh ordenou que fosse dada do povo de Israel, no dia em que Ele ungiu os sacerdotes. Isso será sempre sua porção por todas as gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Esta é a lei do holocausto, da oferta de cereais, da oferta pelo pecado, da oferta pela culpa, da oferta da consagração, e do sacrifício das ofertas pacíficas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'sobre as quais Yahweh deu ordens a Moisés no Monte Sinai no dia em que ordenou ao povo de Israel que oferecesse seus sacrifícios a Yahweh no deserto do Sinai\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '\"Toma Arão e seus filhos, suas vestes e o óleo da unção, o novilho para a oferta de pecado, os dois carneiros e o cesto com os pães não fermentados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Reúne toda a congregação à entrada da Tenda do Encontro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Então, Moisés fez como Yahweh ordenou, e a congregação ajuntou-se à entrada da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Moisés disse à congregação: \"Isto é o que Yahweh ordenou que seja feito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Moisés trouxe Arão e seus filhos, e os lavou com água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Ele vestiu Arão com a túnica e passou a faixa pela cintura dele, vestiu-o com a capa e pôs sobre ele o manto sacerdotal. Então, ele amarrou o manto sacerdotal com um cinto finamente trançado e atou-o ao corpo dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Ele colocou o peitoral em Arão. Nesse peitoral, posicionou o Urim e o Tumim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Ele fixou o turbante em sua cabeça. No turbante, bem à frente, uma lâmina de ouro, a coroa santa, como Yahweh havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Moisés pegou o óleo da unção, ungiu o tabernáculo e tudo o que lá havia e os consagrou a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Ele aspergiu o óleo sete vezes no altar e ungiu o altar e todos os utensílios que lá estavam, bem como a bacia e o suporte, para consagrá-los a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Ele derramou um pouco do óleo da unção sobre a cabeça de Arão e o ungiu para consagrá-lo a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Moisés trouxe os filhos de Arão e os vestiu com túnicas. Ele amarrou faixas em volta das cinturas deles e cobriu suas cabeças com mitras, assim como Yahweh havia mandado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Moisés trouxe o novilho para oferta pelo pecado, e Arão e seus filhos puseram suas mãos sobre a cabeça do novilho que eles tinham trazido para a oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Ele o matou, pegou seu sangue e o colocou com o dedo nos chifres do altar; purificou o altar, derramou o sangue na base do altar e o consagrou a Deus como forma de expiação dos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Ele retirou toda a gordura que estava nas vísceras, a que cobria o fígado, e os dois rins e a gordura junto a eles, e Moisés queimou tudo isso no altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Mas o novilho, seu couro e sua carne, bem como os excrementos foram queimados, fora do acampamento, exatamente como Yahweh havia determinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Moisés apresentou o carneiro para o holocausto, e Arão e seus filhos impuseram suas mãos sobre a cabeça do carneiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Ele o matou e aspergiu o sangue em cada lado do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Ele cortou o carneiro em pedaços e queimou a cabeça, os pedaços e a gordura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Ele lavou as vísceras e as pernas com água e queimou todo o carneiro no altar. Isso foi um holocausto de aroma agradável, oferta queimada a Yahweh, exatamente como Yahweh havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Então Moisés apresentou o outro carneiro, o da consagração, e Arão e seus filhos impuseram suas mãos sobre a cabeça do carneiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Arão matou-o, e Moisés recolheu um pouco do sangue e o passou na ponta da orelha direita de Arão, no polegar de sua mão direita e no dedão do seu pé direito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Ele trouxe os filhos de Arão e passou um pouco do sangue na ponta da orelha direita, no polegar da mão direita e no dedão do pé direito. Então, Moisés aspergiu o sangue em cada lado do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Ele recolheu a gordura, a cauda gorda, e toda a gordura que estava nas vísceras, a que cobria o fígado, os dois rins e a gordura junto a eles, e a coxa direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'E do cesto dos pães não fermentados, que estava perante Yahweh, ele apanhou um pão não fermentado, um outro feito com óleo e um outro pão fino, e os colocou sobre as gorduras e sobre a coxa direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Ele depositou tudo nas mãos de Arão e nas mãos de seus filhos e moveu por oferta de movimento perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Então, Moisés tomou tudo das mãos deles e queimou no altar para holocausto. Isso foi uma oferta consagrada, de aroma agradável a Deus. Foi uma oferta queimada para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Moisés tomou o peito e o movimentou como oferta movida para Yahweh. Isso foi a parte do carneiro que cabia a Moisés, para ordenação sacerdotal, como Yahweh havia ordenado a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Moisés pegou uma parte do óleo da unção e o sangue que estava no altar; aspergiu-o em Arão, em suas roupas, em seus filhos e nas roupas de seus filhos. Dessa forma, ele consagrou Arão e suas roupas, e seus filhos e suas roupas a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Então, Moisés disse a Arão e a seus filhos: \"Cozinhai a carne na entrada da tenda do encontro, e lá comei-a juntamente com o pão que está no cesto da consagração, assim como ordenei, dizendo: \'Arão e seus filhos comerão isso\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'E o que restar da carne e do pão vós deveis queimar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'E vós não saireis da entrada da tenda do encontro por sete dias, até que os dias da ordenação sejam cumpridos. Pois Yahweh vos consagrará por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Isso que foi feito neste dia é o que Yahweh ordenou para ser feito para vossa expiação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Vós permanecereis noite e dia, por sete dias, à entrada da Tenda do Encontro, e guardareis o que Yahweh ordenou, para que não morrais, porque isso é o que tenho ordenado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Então, Arão e seus filhos fizeram todas as coisas que Yahweh lhes havia ordenado por meio de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'No oitavo dia, Moisés chamou Arão, seus filhos e os anciãos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Ele disse a Arão: \"Toma um bezerro do rebanho para uma oferta pelo pecado e um carneiro sem defeito para o holocausto, e oferece-os perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Tu deverás falar ao povo de Israel e dizer: \'Tomai um bode para uma oferta pelo pecado, e um bezerro e um cordeiro, ambos de um ano e sem defeito, para holocausto;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'e tomai também um boi e um carneiro para a oferta pacífica, para sacrificar diante de Yahweh, e uma oferta de cereais misturada com azeite. Porque hoje Yahweh aparecerá a vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Então eles trouxeram tudo quanto Moisés ordenou para a tenda da congregação, e toda a comunidade de Israel se aproximou e se postou de pé diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Depois, disse Moisés: \"Isso é o que Yahweh vos ordenou para fazer, e então a glória Dele poderá aparecer a vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Moisés disse a Arão: \"Vem para perto do altar e oferece tua oferta pelo pecado e o holocausto. Faz expiação para ti mesmo e para o povo, e oferece o sacrifício pelo povo, para fazer expiação por si mesmo, assim como Yahweh ordenou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Arão foi para perto do altar e sacrificou o bezerro para a oferta pelo pecado, que era por si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Os filhos de Arão lhe apresentaram o sangue, e, então, ele molhou seu dedo no sangue e o colocou sobre os chifres do altar. Depois, derramou o sangue na base do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Todavia, ele queimou a gordura, os rins e a gordura que cobria o fígado no altar, como uma oferta pelo pecado, assim como Yahweh ordenara a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'E queimou a carne e o couro fora do acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Arão sacrificou o holocausto, e seus filhos lhe deram o sangue, o qual ele respingou por todos os lados do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Depois, eles lhe deram o holocausto, pedaço por pedaço, junto com a cabeça, e ele os queimou no altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Então, lavou as vísceras e as pernas e as queimou sobre o holocausto no altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Arão apresentou o sacrifício pelo povo — um bode — e depois o tomou como um sacrifício pelos seus pecados e o matou; ele o sacrificou pelo pecado, da mesma forma como fez com o primeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Apresentou o holocausto e o ofereceu como Yahweh havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Ele apresentou a oferta de cereais e encheu sua mão com ela e a queimou no altar, juntamente com o holocausto da manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Ele também sacrificou o boi e o carneiro, o sacrifício para oferta pacífica pelo povo. Os filhos de Arão lhe deram o sangue, o qual ele respingou em todos os lados do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Todavia, retiraram a gordura do boi e do carneiro, a cauda gorda, a gordura que cobre as vísceras, os rins e a gordura que cobria o fígado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Eles pegaram as partes que haviam sido retiradas e as colocaram sobre os peitos, e Arão queimou a gordura no altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Arão ergueu os peitos e a coxa direita para o alto como uma oferta diante de Yahweh e a apresentou a Ele, assim como Moisés havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Então, Arão levantou suas mãos em direção ao povo, e o abençoou. Depois de oferecer a oferta pelo pecado, o holocausto, e a oferta pacífica, ele desceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Moisés e Arão entraram na Tenda do Encontro, e depois saíram de novo e abençoaram o povo, e a glória de Yahweh apareceu para todos eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Saiu fogo de Yahweh e consumiu o holocausto e a gordura no altar. Quando todo o povo viu isso, eles gritaram e se prostraram, com o rosto no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Nadabe e Abiú, filhos de Arão, pegaram cada um o seu incensário, colocaram fogo nele e depois o incenso. Em seguida, ofereceram fogo não permitido diante de Yahweh, o qual Ele não tinha lhes ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Por causa disso, saiu fogo de diante de Yahweh e os devorou; e morreram perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Então, Moisés disse a Arão: \"Isto é o que o Yahweh estava falando quando disse: \'Eu revelarei Minha santidade àqueles que se aproximam de Mim e serei glorificado diante de todos\'\". E Arão se calou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Moisés chamou a Misael e Elzafã, filhos de Uziel, tio de Arão, e disse-lhes: \"Aproximai-vos e trazei vossos irmãos para fora do acampamento, diante do tabernáculo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Assim, eles se aproximaram e os levaram, ainda vestidos em suas túnicas sacerdotais, para fora do acampamento, conforme a instrução de Moisés');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'que disse a Arão, Eleazar e a Itamar, seus filhos: \"Não deixeis que os cabelos de vossas cabeças fiquem bagunçados e nem rasgueis as vossas vestes, para que não morrais e para que Yahweh não se enfureça com toda congregação. Contudo, deixai que vossos familiares, toda a casa de Israel, lamentem pela morte daqueles que foram consumidos pelo fogo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Não podereis deixar a porta da Tenda do Encontro, senão morrereis; pois o óleo da unção de Yahweh está sobre vós\". Assim eles procederam, de acordo com as instruções de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Yahweh falou a Arão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '\"Quando entrardes na Tenda do Encontro, não bebais vinho nem qualquer bebida forte, nem tu, nem teus filhos que ainda estão contigo, para que não morrais. Este será um estatuto permanente por todas as gerações, para que possais');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'diferenciar o santo e o profano, o puro e o impuro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'de forma que possais ensinar ao povo de Israel todos os estatutos que Yahweh ordenou através de Moisés\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Moisés disse a Arão, Eleazar e a Itamar, os filhos que lhe restaram: \"Tomai a oferta de cereais que sobraram das ofertas queimadas a Yahweh, comei-a sem fermento, junto ao altar, pois ela é santissíma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Vós a comereis em um lugar santo, uma vez que ela é a vossa porção e a de vossos filhos, das ofertas queimadas a Yahweh, porque assim é que me foi ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'O peito da oferta movida e a coxa que são oferecidos a Yahweh, vós deveis comer em local limpo, aceitável diante de Deus. Tu, teus filhos e tuas filhas devereis comer aquelas partes porque elas serão dadas a ti e a teus filhos como porção proveniente dos sacrifícios de ofertas pacíficas do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'A coxa que é oferta apresentada a Yahweh e o peito da oferta movida devem ser trazidos juntamente com as ofertas queimadas de gordura, para serem apresentadas como ofertas movidas a Yahweh. Elas pertencerão a ti e aos teus filhos contigo, como uma herança eterna, assim como determinou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Então, Moisés perguntou sobre o bode para o holocausto e descobriu que ele havia sido queimado. Por isso, ele se enfureceu com Eleazar e Itamar, os filhos remanescentes de Arão. Disse ele:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '\"Por qual motivo não comestes dentro da área do tabernáculo? Já que ela é santíssima, considerando que Yahweh vos ofereceu isso para remover a iniquidade da congregação e fazer expiação pelo povo diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'O sangue do sacrifício não foi trazido para dentro do tabernáculo; por esse motivo, vós certamente deveríeis ter comido a oferta dentro do tabernáculo conforme vos ordenei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Então, Arão respondeu a Moisés. Ele disse: Eis que eles fizeram a oferta pelo pecado deles e seu holocausto diante de Yahweh e isso aconteceu hoje. Se eu tivesse comido a oferta pelo pecado hoje, teria sido isso agradável aos olhos de Yahweh?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Ao ouvir tais palavras, Moisés se deu por satisfeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Yahweh falou a Moisés e a Arão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, '\"Falai ao povo de Israel, dizendo: \'Estas são as coisas vivas que vós podereis comer entre todos os animais que estão sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Vós podereis comer quaisquer animais que possuem casco fendido e também os que ruminam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Todavia, alguns animais que ruminam ou possuem casco fendido, vós não devais comer deles. Animais tais como o camelo, porque ele rumina, mas não possui casco fendido. Portanto, o camelo será impuro para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Também o texugo da rocha, porque rumina e não possui casco fendido, será impuro para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'E o coelho, porque rumina, mas não possui casco fendido, será impuro para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'E o porco, que, embora possua casco fendido, não rumina, então será impuro para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Vós não devereis comer nenhuma das suas carnes, nem tocar suas carcaças. Elas serão impuras para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Os animais que vivem na água que podereis comer são todos aqueles que possuem barbatanas e escamas, seja no oceano ou nos rios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Mas todas as criaturas vivas que não possuem barbatanas e escamas, nos oceanos ou nos rios, incluindo todas as que se movem nas águas e todas as que vivem na água, deverão ser detestadas por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Visto que elas deverão ser detestadas, vós não devereis comer suas carnes; também suas carcaças deverão ser detestadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Tudo o que não possui barbatanas ou escamas nas águas deverá ser detestado por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'As aves que devereis detestar e que não devereis comer são estas: a águia, o abutre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'a águia marinha, qualquer tipo de falcão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'todo tipo de corvo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'a coruja de chifre e a coruja das torres, a gaivota e qualquer tipo de gavião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'Vós devereis também detestar a coruja pequena e a coruja grande, o cormorão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'a coruja branca a coruja de celeiro, a águia-pescadora,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'a cegonha, qualquer tipo de garça, a poupa e também o morcego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Todos os insetos alados que andam sobre quatro patas deverão ser detestados por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Todavia, vós podereis comer qualquer inseto voador que também andar sobre patas, se ele possuir pernas articuladas para pular sobre o chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'E vós também podereis comer qualquer tipo de locusta, esperança, grilo ou gafanhoto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Mas todos os insetos voadores que possuem quatro patas deverão ser detestados por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Vós vos tornareis impuros, até o anoitecer, por estes animais, se tocardes a carcaça de algum deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'E quem pegar uma de suas carcaças deverá lavar suas roupas e permanecerá impuro até o anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Todo animal que possui casco fendido que não é completamente dividido ou aquele que não rumina será impuro para vós. Todo aquele que os tocar ficará impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Todo o que anda sobre suas patas entre todos os animais que andam sobre as quatro pernas, eles serão impuros para vós. Qualquer que tocar tais carcaças ficará impuro até o anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'E qualquer um que pegar tais carcaças deverá lavar suas roupas e ficará impuro até o anoitecer. Estes animais serão impuros para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Dos animais que rastejam pelo chão, estes são os animais que serão impuros para vós: a doninha, o rato, todo tipo de lagarto grande,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'a lagartixa, o lagarto monitor, o lagarto, o lagarto da areia e o camaleão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Dentre todos os animais que rastejam, esses são os que serão impuros para vós. Qualquer um que tocá-los, quando estiverem mortos, ficará impuro até o anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'E, se algum deles morrer e cair sobre alguma coisa, aquela coisa ficará impura; seja feita de madeira, tecido, couro, ou pano de saco. Não importa o que for ou para o que seja usado, deverá ser posto dentro d\'água e ficará impuro até o anoitecer. Então, ficará puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Para todos os potes de barro, dentro ou sobre os quais algum animal impuro cair, tudo o que estiver dentro do pote ficará impuro e vós devereis destruir esse pote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Todo alimento puro, que se permite comer, mas sobre o qual a água de um pote impuro caiu, ficará impuro. E qualquer bebida de tais potes ficará impura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Tudo em que alguma parte de carcaça de um animal impuro cair, ficará impuro, seja um forno ou pote de cozinhar. Deverão ser quebrados em pedaços. Isso é impuro e deverá ser impuro para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Uma fonte ou cisterna onde a água para beber é coletada permanecerá pura se tais criaturas caírem dentro delas; mas se alguém tocar a carcaça de um animal impuro na água, ficará impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Se alguma parte de uma carcaça impura cair sobre alguma semente para a plantação, esta semente continuará pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Mas, se a água for colocada sobre a semente e alguma parte de uma carcaça impura cair sobre ela, então ficará impura para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Se algum animal dos quais vós podeis comer vier a morrer, então, aquele que tocar sua carcaça ficará impuro até o anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'E qualquer que comer algo daquela carcaça deverá lavar as suas roupas e ficará impuro até o anoitecer. E aquele que carregar a carcaça deverá lavar suas roupas e ficará impuro até o anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Todo animal que rasteja sobre o solo deve ser detestado; não deverá ser comido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Tudo que rasteja sobre o ventre, e tudo que anda sobre as quatro patas, ou tudo que possui muitas patas — todos os animais que rastejam sobre o solo — vós não devereis comer, pois eles deverão ser detestados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Vós não devereis tornar-vos impuros com nenhuma criatura viva que rasteja. Vós não devereis tornar-vos impuros com elas, pois elas podem tornar-vos impuros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Pois Eu sou Yahweh, vosso Deus. Vós deveis vos manter santos. Portanto, sede santos porque Eu sou Santo. Vós não devereis vos contaminar com nenhum tipo de animal que se move sobre o solo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Pois Eu sou Yahweh, que vos tirou da terra do Egito, para ser vosso Deus. Portanto, vós devereis ser santos, pois Eu sou Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Esta é a lei a respeito dos animais, das aves e de toda criatura viva que se move nas águas e toda criatura que rasteja sobre o solo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'para as quais uma distinção é feita entre pura e impura. E entre os seres vivos que podem ser comidos e os seres vivos que não podem ser comidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Yahweh disse a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, '\"Fala ao povo de Israel, dizendo: \'Se uma mulher conceber e der a luz a um filho, ela estará impura por sete dias; da mesma forma que ela estará impura durante os sete dias do seu ciclo menstrual.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Ao oitavo dia, a carne do prepúcio do menino deve ser circuncidada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Então o período de purificação da mãe por causa do seu sangramento, continuará por trinta e três dias. Ela não poderá tocar em nada que for santo ou adentrar a área do tabernáculo, até que finde os dias de sua purificação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Mas se ela der a luz a uma filha, então, ela estará impura por duas semanas, como ela fica durante seu período. Assim, a purificação da mãe continuará por sessenta e seis dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Quando os dias de sua purificação terminarem, por um filho ou por uma filha. Ela deve trazer um cordeiro de um ano, como holocausto e um pombinho ou uma pomba, como oferta de pecado ao sacerdote na entrada da Tenda da Congregação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Então ele o oferecerá diante de Yahweh e fará a expiação por ela, que ficará purificada do fluxo de seu sangue. Esta é a lei, sobre uma mulher que dá a luz a um filho ou uma filha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Se ela não puder oferecer um cordeiro, então ela deverá levar duas pombas ou dois pombinhos. Um, como holocausto e o outro como oferta de pecado e o sacerdote fará expiação por ela; assim ela será limpa.\' \"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Yahweh falou para Moisés e para Arão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '\"Quando alguém tiver sobre a pele de seu corpo um inchaço, ou crosta de ferida, ou mancha brilhante e isto se tornar infecionado, então essa pessoa deve ser levada a Arão, o Sumo Sacerdote, ou a um de seus filhos, os sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Então o sacerdote examinará a enfermidade na pele de seu corpo. Se os pelos no local enfermo tiverem ficado esbranquiçados, e a área atingida for mais funda do que a pele, então trata-se de doença infecciosa. Depois do sacerdote examinar, ele o declarará impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Mas se a mancha brilhante na sua pele estiver esbranquiçada e a área atingida não for mais funda que a pele e os pelos na região enferma não tiverem ficado esbranquiçados, então o sacerdote deve isolar o enfermo por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'No sétimo dia, o sacerdote deve examiná-lo para averiguar, se na sua opinião, a enfermidade não piorou e não se espalhou pela pele. Se não tiver se espalhado, então o sacerdote deverá isolá-lo por mais sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'No sétimo dia, o sacerdote o examinará novamente para averiguar, se a área enferma está melhor e a enfermidade não se alastrou pela pele. Se não tiver se espalhado mais, então o sacerdote o declarará puro. É uma erupção na pele; ele deverá lavar as suas roupas e ficará limpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mas, se a erupção na pele tiver se espalhado depois que ele tiver se apresentado ao sacerdote para a purificação, então ele deve apresentar-se ao sacerdote novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'O sacerdote o examinará para averiguar se a erupção se espalhou pela pele. Se tiver se espalhado, então o sacerdote deverá declará-lo como impuro. Trata-se de doença infecciosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Quando alguém estiver com doença infecciosa, então ele precisará ser levado ao sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'O sacerdote o examinará para averiguar se existe um inchaço esbranquiçado sobre a pele, cujos pelos da região se tornaram brancos, ou se houver uma ferida em carne viva sobre o inchaço,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'então, trata-se de doença contagiosa crônica e o sacerdote deve declará-lo como impuro. E não o isolará, porque já está impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Se a doença contagiosa se alastrar vastamente e cobrir toda a pele da pessoa infectada, da cabeça aos pés, até onde é possível o sacerdote examinar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'então, o sacerdote deve examiná-la para averiguar se a enfermidade cobriu todo o seu corpo. Se tiver coberto, então o sacerdote deve declará-la como alguém que teve a efermidade purificada. Se tudo se tornou branco, então tal pessoa está pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mas se feridas em carne viva aparacerem sobre ela, estará impura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'O sacerdote examinará a ferida em carne viva e deve declará-lo como impura, porque a ferida em carne viva é impura. Trata-se de uma doença infecciosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Mas se a ferida em carne viva ficar novamente branca, então a pessoa deverá ir ao sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'O sacerdote examinará para averiguar se a carne ficou esbranquiçada. Se tiver ficado, então, o sacerdote vai anunciar que a pessoa está pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Quando uma pessoa tiver uma ferida com pus sobre a pele que já está curada');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'e se no lugar dessa ferida com pus, houver um inchaço esbranquiçado ou uma mancha clara de cor branco-avermelhada, então, esta deve ser mostrada ao sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'O sacerdote a examinará para averiguar se a mesma aparenta estar mais funda sob a pele e se os pelos na região ficaram brancos. Se sim, o sacerdote então declarará essa pessoa como impura. Trata-se de uma doença infecciosa, caso esta tenha se desenvolvido no lugar em que estava a ferida com pus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Mas se o sacerdote averiguar e notar que não há pelos brancos na região ferida, e que não está mais funda que a pele, mas que já clareou, então, o sacerdote precisa isolar a pessoa por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Se a enfermidade se espalhar completamente pela pele, então o sacerdote deve declarar a pessoa como impura. Trata-se de uma doença contagiosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Mas se a mancha clara permanecer no mesmo lugar e não se espalhar, então é uma cicatriz da ferida com pus e o sacerdote deve declarar a pessoa como pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Quando a pele tiver uma queimadura e quando a carne viva da queimadura se transformar em uma mancha branco-avermelhada ou uma mancha esbranquiçada,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'então o sacerdote a examinará para averiguar se os pelos clarearam e se a mancha está mais profunda que a pele. Se sim, trata-se de uma doença infecciosa que surgiu sobre a queimadura, e o sacerdote precisa declarar a pessoa como impura. Trata-se de uma doença infecciosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Mas se o sacerdote examiná-la e não encontrar pelos brancos na mancha e ela não estiver mais funda que a pele, porém já tenha desaparecido, então o sacerdote deverá isolar a pessoa por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Então o sacerdote deve examinar a pessoa no sétimo dia. Se a enfermidade tiver se espalhado completamente sobre a pele, então o sacerdote deverá declarar a pessoa como impura. Trata-se de uma doença contagiosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Se a mancha permanecer no mesmo lugar e não estiver espalhado sobre pele, mas clareado, então é um inchaço da queimadura e o sacerdote deve declarar a pessoa como pura, pois não é nada mais que uma cicatriz da queimadura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Se um homem ou mulher tem ferida na cabeça ou queixo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'então o sacerdote examinará a pessoa à procura de uma doença infecciosa, para ver se esta aparenta estar mais funda do que a pele e para ver se há pelos amarelos e finos nela. Se houver, então o sacerdote deve declarar a pessoa como impura. É uma doença chamada \"sarna\", trata-se de um tipo de doença infecciosa na cabeça ou queixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Se o sacerdote examinar a ferida e notar que esta não está mais funda que a pele e se não há pelos pretos nela, então o sacerdote isolará a pessoa com a doença infecciosa por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Ao sétimo dia, o sacerdote examinará a doença para ver se esta se espalhou. Se não houver pelos amarelos e se a doença não aparentar estar profunda na pele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'então a pessoa deve ser raspada, mas a área infectada não pode ser raspada, e o sacerdote precisa isolar a pessoa com a doença contagiosa por mais sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Ao sétimo dia, o sacerdote examinará a doença para averiguar se esta parou de se espalhar pela pele. Caso aparente não estar mais profunda do que a pele, então o sacerdote deve declarar a pessoa como pura. Tal pessoa deverá lavar suas próprias roupas e então estará pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Mas se a doença contagiosa tiver se espalhado completamente pela pele depois de o sacerdote declarar a pessoa como pura,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'então, o sacerdote deve examiná-la novamente. Se a doença tiver se espalhado pela pele, o sacerdote não precisa procurar por pelos amarelos. A pessoa está impura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Mas, se à vista do sacerdote, a doença contagiosa tiver parado de se espalhar e tiver crescido cabelo preto na área que havia sido infectada, então a doença foi sarada. A pessoa está limpa, e o sacerdote deve declará-la como pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Se um homem ou uma mulher tiver manchas brancas sobre a pele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'então o sacerdote deve examinar a pessoa para averiguar se as manchas estão esbranquiçadas, ou seja, é somente uma coceira que se desenvolveu sobre a pele. A pessoa está pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Se o cabelo de um homem caiu de sua cabeça, ele está calvo, mas, está puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'E se seu cabelo caiu da frente de sua cabeça e se sua fronte estiver calva, ele está puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Mas se houver uma ferida em sua cabeça ou fronte calva, essa é uma doença infecciosa que irrompeu sobre a pele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Então o sacerdote deve examinar a pessoa para averiguar se o inchaço da área infectada em sua cabeça ou fronte calva está branco-avermelhada tal como a aparência de uma doença contagiosa sobre a pele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Se está assim, então a pessoa está com uma doença contagiosa e está impura. O sacerdote deve declará-lo como impuro por causa da doença em sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'A pessoa que tem uma doença infecciosa deve vestir roupas rasgadas, seus cabelos precisam estar livremente soltos e deve cobrir seu rosto até o nariz e gritar: \"Impuro! Impuro!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Todos os dias que estiver com a doença infecciosa, essa pessoa estará impura. Porque está impura com uma enfermidade que pode se espalhar, essa pessoa deve viver sozinha. Deve viver fora do acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Uma peça de roupa, seja de lã ou de linho, que estiver infectada com mofo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'ou qualquer peça tecida ou tricotada com lã, ou linho, ou couro, ou qualquer artefato feito com couro -');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'se houver uma contaminação esverdeada ou avermelhada, no couro, na lã, ou no material tricotado, ou em qualquer artefato feito com couro, então é mofo que se espalha; deve ser apresentado ao sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'O sacerdote examinará a peça à procura de mofo; ele deve isolar qualquer peça em que há mofo por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Ao sétimo dia, ele examinará o mofo novamente. Se este tiver se espalhado pela vestimenta ou qualquer peça tecida ou tricotada com lã, ou linho, ou couro, ou qualquer artefato em que é utilizado couro, então é um mofo prejudicial, e a peça está impura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'O sacerdote deve queimar a vestimenta ou qualquer peça tecida ou tricotada com lã, ou linho, ou couro, ou feita com couro, onde o mofo prejudicial for encontrado, porque este pode levar à enfermidade. A peça deve ser completamente queimada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Se o sacerdote examinar a peça e notar que o mofo não se espalhou na vestimenta ou no material tecido ou tricotado com lã ou linho, ou em peças de vestuário de couro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'então ele ordenará que sejam lavadas essas peças nas quais o mofo foi encontrado e ele deve isolá-las por mais sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Então o sacerdote examinará a peça depois que a peça contaminada com mofo foi lavada. Se o mofo não mudou de cor, mesmo que não tenha se espalhado, a peça está impura. Queimarás a peça, não importa onde o mofo a tenha contaminado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Se o sacerdote examinar a peça e se o mofo tiver diminuido depois que esta foi lavada, então ele cortará a parte contaminada da vestimenta, ou do couro, ou da peça tecida com lã, ou tricotada com linho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Se o mofo ainda aparecer na vestimenta, quer seja naquela tecida com lã ou tricotada com linho, quer seja naquela feita de couro, ele está se espalhando. Queimarás qualquer peça em que houver o mofo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'A vestimenta ou qualquer peça tecida com linho ou tricotada com lã, ou feita de couro ou qualquer uma feita com couro, se a lavardes e o mofo desaparecer, então a peça precisa ser lavada uma segunda vez e então estará pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Esta é a lei sobre mofo em uma vestimenta de lã ou linho, ou qualquer outra peça tecida com linho, ou tricotada com lã, ou feita de couro, ou qualquer uma feita com couro, para que vós possais anunciá-la como pura ou impura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Yahweh falou a Moisés dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '\"Esta será a lei para pessoa impura, no dia de sua purificação. Ela deverá apresentar-se ao sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'O sacerdote sairá do acampamento para examinar a pessoa e verificar se a infecção da pele está curada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Então o sacerdote ordenará que a pessoa a ser purificada traga duas aves limpas e vivas, madeira de cedro, carmesim e hissopo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'O sacerdote lhe ordenará que mate uma das aves sobre a água fresca que estará num pote de barro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'O sacerdote trará a ave viva, e a madeira de cedro, e o carmesim, e o hissopo e mergulhará todas essas coisas, incluindo a ave viva, no sangue da ave que foi morta sobre a água fresca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Então o sacerdote espargirá essa água sete vezes sobre a pessoa que será limpa da infecção e em seguida o declarará puro. Depois disso, o sacerdote libertará a ave viva no campo aberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'A pessoa a ser purificada lavará as suas roupas, raspará todo o seu cabelo, lavar-se-á em água e então estará pura. Depois disso, essa pessoa entrará no acampamento, mas viverá fora de sua tenda por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'No sétimo dia, raspará todo o cabelo de sua cabeça e também deverá raspar sua barba e sobrancelhas. Deverá raspar todo o seu cabelo, lavar suas roupas e lavar-se em água; então estará limpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'No oitava dia, deverá pegar dois cordeiros sem defeito, uma ovelha de um ano sem defeito, três décimos de efa de fina farinha misturada com óleo como oferta queimada e uma medida de óleo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'O sacerdote que faz a purificação levantará a pessoa que será purificada, juntamente com todas essas coisas, perante Yahweh, na entrada da tenda do encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'O sacerdote pegará um dos cordeiros e o oferecerá como oferta pela culpa, juntamente com uma medida de óleo; ele os levantará como oferta perante Yahweh e os apresentará a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Ele deverá matar o cordeiro no lugar onde foram mortas as ofertas pelo pecado e os holocaustos, na área do tabernáculo, pois a oferta pelo pecado pertence ao sacerdote, assim como a oferta pela culpa, pois são santíssimas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'O sacerdote pegará parte do sangue da oferta de culpa e a colocará na ponta da orelha direita da pessoa que será purificada, no polegar de sua mão direita e no polegar de seu pé direito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Então o sacerdote pegará óleo e colocará na palma da sua própria mão esquerda,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'mergulhará seu dedo direito no óleo que está na sua mão esquerda e espargirá o óleo do seu dedo sete vezes perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'O sacerdote colocará o restante do óleo que está em sua mão na ponta da orelha direita da pessoa que será purificada, no polegar de sua mão direita e no polegar do seu pé direito. Ele deverá colocar o óleo em cima do sangue da oferta de culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'E o restante do óleo que estiver na mão do sacerdote ele colocará sobre a cabeça da pessoa que será purificada, e o sacerdote fará expiação por ele perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Depois o sacerdote oferecerá oferta pelo pecado e fará expiação por aquele que será purificado por causa de sua impureza e depois ele oferecerá a oferta queimada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Então o sacerdote oferecerá o holocausto e a oferta queimada no altar. O sacerdote fará expiação pela pessoa, e então ela ficará pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Porém se a pessoa for pobre e não puder pagar por esses sacrificios, então ela pegará um cordeiro como oferta de culpa a ser levantada e apresentada a Yahweh como expiação por ela e um décimo de efa de fina farinha misturada ao óleo como oferta queimada e porção de óleo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'juntamente com duas rolas e duas pombinhas, tal como for capaz de oferecer; um pássaro será oferta pelo pecado e o outro será holocausto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'No oitavo dia, deverá trazê-los ao sacerdote para sua purificação, na entrada da tenda do encontro, perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Então o sacerdote pegará o cordeiro para a oferta de culpa e a porção de óleo e os levantará como oferta a Yahweh e os apresentará a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Ele matará o cordeiro para a oferta de culpa e pegará parte do sangue da oferta de culpa e a colocará na ponta da orelha direita daquele que será purificado, no polegar de sua mão direita e no polegar de seu pé direito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Então o sacerdote derramará parte do óleo na palma da sua própria mão esquerda');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'e espargirá com seu dedo direito parte do óleo que está em sua mão esquerda sete vezes perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Então, o sacerdote porá parte do óleo que está em sua mão na ponta da orelha direita daquele que será purificado, no dedo polegar da sua mão direita, e no dedo polegar do seu pé direito, os mesmo lugares onde ele colocou o sangue da oferta de culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Ele colocará o restante do óleo que está em sua mão sobre a cabeça daquele que será purificado, para fazer expiação por ele perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Ele deverá oferecer uma das rolas ou pombinhas, conforme a pessoa tiver sido capaz de adquirir --');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'uma como oferta pelo pecado e a outra como holocausto, juntamente com a oferta queimada. Então o sacerdote fará expiação por aquele que será purificado perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Esta é a lei para a pessoa com infecção de pele, que não for capaz de adquirir a oferta para sua purificação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Yahweh falou a Moisés e a Arão dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '\"Quando tiveres entrado na terra de Canaã, a qual te dei por possessão, e se eu colocar lepra que se espalhe na casa, na terra de sua possessão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'então o dono da casa deverá vir e falar ao sacerdote. Ele deverá dizer: \'Parece-me que há algo como lepra em minha casa\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Então o sacerdote ordenará que eles esvaziem a casa antes de entrar e ver a evidencia de lepra, para que nada dentro da casa se torne impuro. Depois disso, o sacerdote deverá entrar para ver a casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Ele deverá examinar a lepra e confirmar se ela está nas paredes da casa, e confirmará se sua aparência é esverdeada ou avermelhada nas depressões de superficie das paredes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Se a casa tiver lepra, então o sacerdote sairá e fechará a porta da casa por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Então o sacerdote retornará no sétimo dia e examinará para confirmar se a lepra se espalhou pelas paredes da casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Se tiver se alastrado, então o sacerdote ordenará que se retirem as pedras onde a lepra tiver sido encontrada e as lançará em um lugar impuro fora da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Ele requererá que todas as paredes de dentro da casa sejam raspadas, e eles deverão pegar o material contaminado que foi raspado e lançar fora da cidade, em um lugar impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Eles deverão pegar outras pedras e colocá-las no lugar das pedras removidas e deverão usar um barro novo para rebocar a casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Se a lepra retornar e aparecer na casa da qual as pedras tiverem sido retiradas e as paredes tiverem sido raspadas e rebocadas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'então o sacerdote virá e examinará a casa para confirmar se a lepra se espalhou por ela. Se houver, então é lepra nociva, e a casa está impura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'A casa deverá ser derrubada. As pedras, madeiras, e todo o reboco da casa deverá se retirado para fora da cidade, para um lugar impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Assim também, qualquer um que entrar na casa durante o período em que estiver fechada estará impuro até o enterdecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Aquele que houver dormido na casa deverá lavar suas roupas, e aquele que houver se alimentado dentro da casa deverá lavar suas roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Se o sacerdote entrar na casa para examiná-la e checar se a lepra se espalhou pela casa, depois de ela ter sido rebocada, e então, se a lepra não tiver retornado, ele a declarará como casa limpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Então o sacerdote deverá pegar duas aves para purificar a casa, e madeira de cedro, e carmesim, e hissopo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Ele matará uma das aves sobre água fresca em um jarro de barro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Ele pegará a madeira de cedro, o hissopo, o carmesim e a ave viva e os mergulhará no sangue da ave morta, dentro da água fresca, e espargirá sobre a casa sete vezes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Ele limpará a casa com o sangue da ave e com a água fresca, com a ave viva, a madeira de cedro, o hissopo e o carmesim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Mas ele libertará a ave viva fora da cidade, nos campos abertos. Assim, ele fará expiação pela casa, e ela estará pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Esta é a lei para todos os tipos de infecção de pele que provoquem infecção e coceira');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'e para lepra na roupa e na casa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'para inchaço, para erupção cutânea e para mancha clara,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'que determinará quando qualquer desses casos for impuro ou quando for puro. Esta é a lei para infecções de pele e lepra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Yahweh falou a Moisés e a Arão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, '\"Falai ao povo de Israel, dizei a eles: \'Quando algum homem tiver um fluxo imundo que saia do seu corpo, tornar-se-á impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Sua impureza é devida ao fluxo imundo. Se seu corpo flui ou para de fluir, está imundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Toda cama na qual ele deitar ficará impura, tudo no qual ele sentar ficará impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Qualquer um que tocar na sua cama deverá lavar suas roupas e banhar-se na água e ficará impuro até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Alguém que sentar em algum lugar no qual o homem com fluxo imundo sentou, aquela pessoa deverá lavar suas roupas e banhar-se na água, ele ficará impuro até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'E qualquer que tocar o corpo de alguém que tem um fluido de fluxo imundo deverá lavar suas roupas e banhar-se na água, e ficará impuro até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Se a pessoa que tem tal fluxo imundo cuspir em alguém que está limpo, então aquela pessoa deverá lavar suas roupas e banhar-se na água, e ficará impura até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Qualquer que sentar onde aquele que tem fluxo cavalgar ficará impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Quem tocar em qualquer coisa que estiver embaixo daquela pessoa ficará impuro até o entardecer, e alguém que carregar aquelas coisas deverá lavar suas roupas e banhar-se na água; ele ficará impuro até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Toda pessoa em quem aquele que tiver tal fluxo tocar, sem ter antes lavado suas mãos na água, deverá lavar suas roupas e banhar-se na água e ficará impura até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Qualquer vaso de barro que alguém com tal fluxo imundo tocar deverá ser quebrado, e todo contêiner de madeira deverá ser lavado na água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Quando aquele que tiver um fluxo for limpo do seu próprio fluxo, então ele deverá contar sete dias para a sua purificação; então ele deverá lavar suas roupas e banhar seu corpo em água corrente. Então ficará limpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'No oitavo dia ele deverá tomar duas pombas ou duas rolinhas e virá diante de Yahweh na entrada da tenda do encontro; nesse lugar ele deverá dar os pássaros ao sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'O sacerdote deverá oferecê-los, um como oferta pelo pecado e o outro como um holocausto, e o sacerdote deverá fazer expiação por ele diante de Yahweh por seu fluxo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Se qualquer sêmen de homem sair de si espontaneamente, então ele deverá banhar todo seu corpo em água; ele ficará impuro até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Toda peça de roupa ou de couro na qual houver sêmen deverá ser lavada com água; ficará impura até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'E se uma mulher e um homem dormirem juntos e houver uma transferência de sêmen para ela, ambos deverão banhar-se na água; ficarão impuros até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Quando uma mulher menstruar, sua impureza será contínua por sete dias, e qualquer que tocar nela ficará impuro até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Todo lugar em que ela se deitar durante seu período menstrual ficará imundo; todo lugar em que ela se sentar ficará também imundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Qualquer que tocar na cama dela deverá lavar suas roupas e banhar-se na água; aquela pessoa ficará impura até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Quem tocar em quaquer lugar em que ela sentar deverá lavar suas roupas e banhar-se na água; aquela pessoa ficará impura até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Na cama ou em algum lugar no qual ela sentar, se alguém tocar, aquela pessoa ficará impura até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Se algum homem dormir com ela e se o fluxo impuro dela tocar nele, ele ficará impuro por sete dias. Toda cama na qual ele deitar ficará impura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Se uma mulher tiver um fluxo de sangue por muitos dias e aquele não for o tempo da sua menstruação ou se ela tiver um fluxo além do tempo da sua menstruação, durante todos os dias do fluxo de sua impureza, ela ficará como se estivesse nos dias do seu período. Está imunda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Toda cama na qual ela deitar durante o seu fluxo de sangue será para ela assim como a cama na qual ela deitar durante sua menstruação, e todo lugar no qual ela sentar ficará impuro, assim como a impureza da sua menstruação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'E quem tocar em alguma daquelas coisas ficará impuro; deverá lavar suas roupas e banhar-se na água, contudo ficará impuro até o entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Mas se ela estiver limpa do seu fluxo de sangue, então ela contará por si mesma sete dias e depois ela ficará limpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'No oitavo dia ela tomará para si duas pombas ou duas rolinhas e as levará ao sacerdote na entrada da tenda do encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'O sacerdote oferecerá um pássaro como uma oferta pelo pecado e o outro em holocausto e fará expiação por ela diante de Yahweh para que fique limpa do fluxo de sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Assim é que devereis separar o povo de Israel de suas impurezas, então eles não morrerão devido às suas impurezas, por contaminarem Meu tabernáculo, onde Eu vivo entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Esses são os regulamentos para todos que tiverem fluxo imundo, para qualquer homem de quem o sêmen for expelido e o fizer imundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Para qualquer mulher que tiver um período menstrual, para qualquer pessoa com fluxo imundo, seja homem ou mulher, e por qualquer homem que dormir com uma mulher impura\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Yahweh falou com Moisés, isto depois da morte dos dois filhos de Arão, quando eles se aproximaram de Yahweh e morreram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Yahweh disse a Moisés: \"Dize a Arão, teu irmão, que não entre a qualquer momento no santíssimo lugar além do véu, diante do propiciatório que está sobre a arca. Se ele entrar, ele morrerá, porque Eu apareceço na nuvem sobre o propiciatório.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Então será assim que Arão deverá entrar no lugar santíssimo: com um novilho, como oferta pelo pecado, e um carneiro, como holocausto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Deverá vestir-se com a túnica de linho sagrada e com as roupas de baixo que são calções de linho, deverá usar cinto de linho e turbante de linho sobre a cabeça. Estas são as vestes sagradas. Ele deverá banhar-se em água e vestir-se com essas roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Tomará da congregação de Israel dois bodes, como oferta pelo pecado, e um carneiro para holocausto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Então Arão deverá apresentar o novilho como sua oferta pelo pecado, para fazer expiação por si mesmo e por sua família.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Então ele deverá tomar dois bodes e apresentá-los perante Yahweh na entrada da tenda do encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Então Arão deverá lançar sorte sobre os dois bodes, uma por Yahweh e outra pelo bode expiatório.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Arão deverá apresentar o bode sobre o qual cair a sorte para Yahweh e sacrificá-lo como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Mas o bode sobre o qual a sorte cair como bode expiatório deverá ser levado vivo diante de Yahweh, para fazer a expiação enviando-o como o bode expiatório para o deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Então Arão deverá apresentar o novilho como sua oferta pelo pecado. Ele deve fazer expiação por si mesmo e por sua família, então matará o novilho como sua oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Arão tomará um incensário cheio de brasas de fogo tiradas do altar diante de Yahweh, com suas mãos cheias de incenso agradável bem moído, e trará para além do véu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Ali ele colocará o incenso no fogo diante de Yahweh, para que a nuvem do incenso cubra o propiciatório sobre a arca do Testemunho, a fim de que não morra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Então ele pegará um pouco de sangue do novilho e aspergirá com o seu dedo sobre a frente do propiciatório. Ele aspergirá um pouco de sangue com o seu dedo sete vezes diante do propiciatório.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Então ele matará o bode que for oferecido pelo pecado do povo e trará para além do véu. Ali ele fará com o sangue como fez com o sangue do novilho: aspergirá sobre o propiciatório na parte da frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Ele fará expiação pelo santo lugar por causa das ações impuras do povo de Israel, pela sua rebelião e todos os seus pecados. Ele também fará isso pela tenda do encontro, onde Yahweh habita entre eles, na presença de suas ações impuras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Ninguém mais deverá estar na tenda do encontro quando Arão entrar para fazer a expiação no santíssimo lugar, e até ele sair e tiver terminado de fazer a expiação por si mesmo, por sua família e por toda a congregação de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Ele sairá ao altar que está diante de Yahweh e fará expiação pelo altar e deverá pegar um pouco de sangue do novilho, e um pouco do sangue de bode, e colocará sobre chifres em volta do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Com o seu dedo aspergirá um pouco de sangue sete vezes sobre o altar, para purificá-lo das ações impuras do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Quando tiver terminado a expiação pelo santíssimo lugar, pela tenda do encontro e pelo altar, ele deverá apresentar o bode vivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Arão colocará as duas mãos sobre a cabeça do bode vivo e confessará sobre ele todas as fraquezas do povo de Israel, sua rebelião e todos os seus pecados. Então ele colocará sobre a cabeça do bode todos os pecados e mandará o bode embora aos cuidados de um homem que estiver pronto para conduzir o bode para o deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'O bode levará sobre si todas as fraquezas do povo para um lugar solitário. Lá no deserto, o homem deixará o bode ir livremente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Então Arão voltará à tenda do encontro, tirará as vestes de linho que ele havia colocado antes de entrar no santíssimo lugar e as deixará ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Ele deverá banhar-se em água em um lugar sagrado e colocar suas próprias roupas; então ele deverá sair e oferecer seu holocausto e o holocausto pelo povo, e desta maneira, fazer expiação por si mesmo e pelo povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Ele deverá queimar no altar a gordura da oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'O homem que soltar o bode expiatório deverá lavar suas roupas e banhar-se em água; depois disso, poderá voltar ao acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'O novilho e o bode da oferta pelo pecado, cujo sangue foi trazido para fazer a expiação no santo lugar, irão ser levados para fora do acampamento. Serão queimados o couro, a carne e o excremento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'O homem que queimar essas partes deverá lavar as suas roupas e banhar-se em água; depois disso, ele poderá voltar ao acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Isto será um estatuto perpétuo para vós: no sétimo mês, no décimo dia do mês, devereis humilhar-vos e não trabalhareis, tanto o nativo quanto o estrangeiro que vive entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Porque nesse dia a expiação será feita por vós, para vos purificar de todo pecado, então vós sereis limpos diante de Yahweh. Esse será um Sábado solene de descanso para vós, e devereis humilhar-vos e não trabalhareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Este será um estatuto para sempre entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'O sumo sacerdote que for ungido e ordenado para ser o sumo sacerdote no lugar de seu pai, fará expiação e colocará as vestes de linho, que são vestes santas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Ele fará a expiação para o santíssimo lugar, para a tenda do encontro e para o altar, e fará expiação pelo sacerdote e por toda a congregação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Isto será um estatuto perpétuo para vós: para fazer expiação uma vez por ano pelo povo de Israel, por causa de todos os seus pecados.\" E isso foi feito como Yahweh ordenou a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Yahweh falou com Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, '\"Fala a Arão, seus filhos e a todo o povo de Israel. Dize o que Yahweh tem lhes ordenado:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, '\'qualquer homem de Israel que matar um boi, um cordeiro ou um bode no arraial, ou que matá-lo fora do arraial, a fim de sacrificá-lo —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'e não o trouxer à entrada da tenda do encontro para oferecê-lo como um sacrifício a Yahweh ante o Seu tabernáculo, esse homem é culpado de carnificina. Ele derramou sangue, e ele deverá ser excluído do meio do seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'O propósito desse mandamento é de que o povo de Israel traga seus sacrifícios a Yahweh à entrada da tenda do encontro, ao sacerdote, para ser sacrificado como oferta pacífica a Yahweh, ao invés de oferecer sacrifícios em um campo aberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'O sacerdote aspergirá o sangue sobre o altar de Yahweh à entrada da tenda do encontro, e queimará a gordura para produzir um aroma agradável a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'O povo não deverá mais oferecer seus sacrifícios aos ídolos em forma de bode, pois, ao fazerem isso, agem como prostitutas. Esse será um estatuto permanente para eles e para suas gerações\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Dize-lhes, pois: \'qualquer homem de Israel, ou qualquer estrangeiro que vive entre eles, que oferecer um holocausto ou sacrifício');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'e não o trouxer à entrada da tenda do encontro a fim de sacrificá-lo a Yahweh, esse homem será excluído de seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'E qualquer um de Israel ou qualquer estrangeiro que vive entre eles que consumir sangue, presdipor-Me-ei contra essa pessoa que consumiu sangue e a excluirei do meio de seu povo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'pois a vida de um animal está em seu sangue. Eu dei o sangue deste para vós fazerdes expiação ao altar por vossas vidas porque esse é o sangue que faz expiação, pois, esse é o sangue que expia para a vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Assim sendo, Eu disse ao povo de Israel que ninguém dentre vós comerá sangue, como tampouco nenhum estrangeiro que vive entre vós o comerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'E qualquer um dentre o povo de Israel ou qualquer um dos estrangeiros que vive entre eles, que caça e mata um animal ou ave que pode ser comida, essa pessoa deverá despejar o sangue do animal e cobri-lo com terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Pois a vida de cada criatura está em seu sangue. Por isso Eu disse ao povo de Israel: \"vós não podeis comer o sangue de nenhuma criatura, pois a vida de toda criatura viva está em seu próprio sangue. Qualquer que comer, tem de ser excluído do povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Toda pessoa que comer um animal que morreu ou que tenha sido dilacerado por animais selvagens, seja essa pessoa um nativo, ou estrangeiro vivendo entre vós, precisará lavar suas roupas, banhar-se em água e estará impura até o entardecer. Depois disso, essa pessoa estará pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Mas se não lavar suas roupas ou banhar seu corpo, então deverá carregar essa culpa\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Disse Yahweh para Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, '\"Fala para o povo de Israel e dize-lhes: \'Eu sou Yahweh vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Não fareis as mesmas coisas que as pessoas fazem no Egito, onde habitastes. E não fareis as mesmas coisas que fazem as pessoas de Canaã, terra para onde Eu estou vos levando, nem andareis segundo os seus costumes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Minhas leis são o que vós deveis praticar, e os Meus mandamentos são o que deveis guardar, para andardes neles, porque Eu sou Yahweh vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Portanto, deveis guardar os Meus decretos e as Minhas leis. Quem obedecê-los, viverá. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Nenhum homem deverá se aproximar de uma parente próxima para ter relações sexuais com ela. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Não desonres o teu pai tendo relações com a tua mãe. Ela é a tua mãe! Não deves desonrá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Não terás relações com qualquer uma das esposas de teu pai; não deves desonrar teu pai desse jeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Não terás relações com qualquer uma das tuas irmãs, não importa se ela é filha da parte do teu pai ou filha da parte da tua mãe, seja ela nascida em tua casa ou distante de ti. Não terás relações com as tuas irmãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Não terás relações com a filha de teu filho ou com a filha de tua filha. Isso seria a tua própria vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Não terás relações com a filha da mulher de teu pai, gerada pelo teu pai. Ela é tua irmã, e não deves ter relações com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Não terás relações com a irmã de teu pai. Ela é parente próximo do teu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Não terás relações com a irmã de tua mãe. Ela é parente próxima da tua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Não desonres o irmão do teu pai tendo relações com a esposa dele. Não te aproximes dela com este propósito; ela é tua tia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Não terás relações com a tua nora. Ela é esposa do teu filho; não terás relações com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Não terás relações com a esposa do teu irmão; não o desonres desse jeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Não terás relações com uma mulher e sua filha, ou com a filha de seu filho ou filha da sua filha. Eles são parentes próximos dela, e ter relações com elas seria maldade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Não deverás casar com a irmã da tua mulher, como uma segunda mulher, e ter relações com ela enquanto a tua primeira esposa estiver viva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Não terás relações com uma mulher no seu período de menstruação. Ela está impura durante este período.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Não terás relações com a mulher do teu próximo contaminando-te com ela dessa forma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Não entregarás nenhum dos teus filhos para passar através do fogo, a fim de serem sacrificados para Moloque, porque não deves profanar o nome do teu Deus. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Não te deitarás com outro homem como se fosse mulher. Isso é abominação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Não te deitarás com nenhum animal, contaminando-te com isto. Nenhuma mulher deverá deitar-se com um animal. Isto é perversão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Não vos contamineis em nenhuma dessas maneiras, pois assim nações se contaminaram, as nações que expulsarei de diante de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'A terra se tornou contaminada, então Eu puni os seus pecados e a terra vomitou seus habitantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Vós, portanto, guardareis os Meus mandamentos e decretos, e não devereis fazer nenhuma destas coisas detestáveis, nem os nativos nem os estrangeiros que vivem entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Porque esta é a abominação que as pessoas cometeram na terra, aqueles que viveram aqui antes de vós, e agora a terra está contaminada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Portanto, cuidado para que a terra não vos vomite também depois de a terdes contaminado, assim como ela vomitou as pessoas que estiveram aqui antes de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Todo aquele que fizer alguma dessas coisas detestáveis, sim, aqueles que fizerem tais coisas, serão eliminados do seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Portanto, deveis guardar Meus mandamentos não praticando estes costumes detestáveis que foram praticados aqui antes de vós, então não sereis contaminados por eles. Eu sou Yahweh vosso Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '\"Fale a toda a assembléia do povo de Israel e dize-lhes: \'Devei ser santo, porque Eu, Yahweh, sou Deus santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Todos vós deveis honrar a vossa mãe e vosso pai, e guardar os Meus Sábados. Eu sou Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Não vos volteis para os ídolos inúteis, não façais deuses de metal para vós. Eu sou Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Quando oferecerdes ofertas pacíficas a Yahweh, vós deveis oferecer de modo que seja aceitável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Deve ser comida no mesmo dia em que oferecerdes, ou, no dia seguinte. Se alguma coisa restar para o terceiro dia, deveis queimar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Se for comida no terceiro dia, ela está contaminada. Ela não será aceita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Todavia, todo aquele que comê-la deverá carregar sua própria culpa, porque ele tem poluído o que foi dedicado a Yahweh. Esta pessoa deverá ser excluída do seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Quando tu colheres com tuas mãos, tu não deves colher completamente nas extremidades do campo, nem ajuntes toda a produção da sua colheita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Não deves ajuntar toda a vinha do seu vinhedo, nem tampouco as uvas caídas no terreno do seu vinhedo. Tu deverás deixar para o pobre e para o estrangeiro. Eu sou Yahweh vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Não furteis. Não mintais. Nem enganeis uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Não jureis em meu nome falsamente, nem profaneis o nome do vosso Deus. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Não oprimais o vosso próximo, nem o roubeis. O pagamento do empregado não ficará convosco toda a noite até pela manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Não amaldiçoes o surdo, nem sejas pedra de tropeço ao cego. Ao invés disto, deveis temer o vosso Deus. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Não crieis falsos julgamentos. Não devais favorecer alguém por ele ser pobre, ou por ser importante. Ao invés disto, julgai vosso próximo de forma justa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Não propagueis calúnia entre as pessoas, procurai defender a vida do vosso próximo. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Não odieis o vosso irmão em vossos corações. Devei honestamente repreender o vosso próximo, para que não compartilheis do pecado dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Não vingueis vós, nem guardeis nenhum rancor contra o vosso próximo, ao invés disto, amai vosso próximo como a vós mesmos. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Vós deveis guardar os meus mandamentos. Não permitais que vossos animais procriem com diferentes outros tipos de animais. Não mistureis dois diferentes tipos de sementes, quando plantardes em vosso campo. Nem vistais roupa de dois tipos diferentes de materiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Qualquer que dorme com uma mulher escrava comprometida com outro homem, mas que ainda não é resgatada nem liberta, eles deverão ser punidos. Não serão mortos, pois ela não era livre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'O homem deve oferecer uma oferta para Yahweh, à entrada da tenda do encontro, um cordeiro oferecei como oferta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Para que o sacerdote faça expiação por ele diante de Yahweh, um cordeiro pela oferta do pecado cometido por ele. Então o pecado cometido por ele será perdoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Quando tiverdes entrado na terra e tiverdes plantado todos os tipos de árvores para alimento. Então vós devereis proibir de serem comidos todos os frutos, por três anos. Eles não devem ser comidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Contudo, no quarto ano, todo o fruto será consagrado, como oferta de louvor á Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'No quinto ano, vós podereis comer do fruto, para que as árvores produzam mais. Eu sou Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Não comais nenhuma carne com sangue. Não consulteis espíritos sobre o futuro, nem busqueis poderes sobrenaturais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Não sigais os hábitos pagãos, tais como aparar os lados do seu cabelo ou cortando as bordas de sua barba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Não corteis o corpo por causa dos mortos, nem coloqueis marca alguma em vosso corpo. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Não desonreis vossa filha fazendo ela se prostituir, para que a nação não se prostitua, nem a terra se encha de maldade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Vós deveis guardar os Meus Sábados e honrar o santuário do Meu tabernáculo. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Não procureis os que procuram os mortos, nem espíritos. Não procureis, para que não sejais desonrados. Eu sou Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Vós deveis vos levantar diante de uma pessoa idosa e honrar a presença de uma pessoa mais velha. Vós deveis temer o vosso Deus. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Se um estrangeiro viver por um tempo em sua terra, vós não deveis maltratá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'O estrangeiro que viver convosco, vós o deveis amar como a vós mesmos, pois fostes estrangeiros na terra do Egito. Eu sou Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Não useis medidas falsas quando medirdes do cumprimento, de peso ou de capacidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Vós deveis usar balanças justas, pesos justos, efa justo, e him justo. Eu sou Yahweh, seu Deus, que vos tirei da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Vós deveis obedecerdes a todos os Meus mandamentos e todas as Minhas leis e os cumprirei. Eu sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '\"Diga ao povo de Israel: \'Qualquer um entre o povo de Israel, ou qualquer estrangeiro que viva em Israel, que entregar qualquer um de seus filhos a Moloque, certamente será morto. O povo deste lugar o apedrejará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'E também voltarei o Meu rosto contra esse homem, o expulsarei do meio do povo, pois ele entregou seu filho a Moloque, assim contaminou Meu santo lugar e profanou Meu santo nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Se o povo deste lugar fechar os olhos a respeito deste homem que entregou algum de seus filhos a Moloque, e não o matar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'então Eu mesmo virarei Meu rosto contra ele e seu clã, e o expulsarei, bem como qualquer um que se prostituir seguindo a Moloque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Aos que procuram aqueles que falam com os mortos, ou aqueles que falam com espíritos, prostituindo-se com eles, virarei Meu rosto e os expulsarei do meu do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Assim sendo, consagrai-vos a Yahweh e sede santos, pois Eu sou Yahweh, o vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Deverei guardar Meus mandamentos e cumprí-los. Eu sou Yahweh, que vos santifico.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Todo aquele que amaldiçoar seu pai ou sua mãe, certamente morrerá. Visto que amaldiçoou seu pai ou sua mãe, então é dele a culpa e merece a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'O homem que comete adultério com a esposa de outro homem, isto é, qualquer um que cometer adultério com a esposa de teu próximo -- certamente devem ser condenados a morte, ele e a mulher adúltera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'O homem que mantem relação sexual com a esposa do pai para dormir com ela desonrou seu próprio pai. Os dois, o filho e a esposa de seu pai, merecem morrer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Se um homem manter relação sexual com sua nora, os dois devem morrer. Estes cometeram perversão. Eles são culpados e merecem morrer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Se um homem se deitar com um outro homem, como se fosse uma mulher, ambos cometeram uma abominação e certamente devem morrer. Eles são culpados e merecem a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Se um homem se casar com uma mulher e também se casar com a mãe dela, isso é maldade. Eles devem ser queimados, ele e as mulheres, para que não haja maldade no meio de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Se um homem manter relação com um animal, deverá ser morto, e matareis o animal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Se uma mulher se aproxima de qualquer animal para dormir com ele, deveis matar a mulher e o animal. Eles certamente devem morrer. Eles são culpados e merecem a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Se um homem manter relação com sua irmã, mesmo se for filha de seu pai ou filha de sua mãe —mantendo relação com ela e ela com ele, é uma coisa vergonhosa. Eles devem ser expulsos da presença do povo, porque ele teve relações sexuais com sua irmã. Ele levará a culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Se um homem manter relação com uma mulher durante o período menstrual dela, ele está descobrindo o fluxo de sangue dela. Assim, ambos, o homem e a mulher, devem ser expulsos do meio do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Não tereis relação com a irmã de tua mãe, nem com a irmã do teu pai, pois vós haveis de desgraçar vossos parentes próximos. Sobre vós caireis a culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Se um homem tiver relação com a esposa de seu tio, ele tem desgraçado seu tio. Eles levarão a culpa e morrerão sem filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Se um homem se casar com a esposa do irmão, isso é impureza, pois ele tem violado as relações do casamento de seu irmão e eles não terão filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Vós devereis, entretanto, guardar todos os meus estatutos; devereis obedecer-lhes na terra para onde Eu estou vos levando para que ela não vos vomite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Vós não devereis andar de acordo com o costume das nações, porque Eu vos conduzirei, pois essas nações têm feito todas essas coisas, e Eu as detesto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Eu vos digo: \"Vós herdareis essa terra; Eu a darei por vossa possessão, uma terra da qual flui leite e mel. Eu sou Yahweh vosso Deus, que tem vos separado dos outros povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Devereis, portanto, distinguir entre animais puros e impuros e entre aves puras e impuras. Vós não deveis vos contaminar com animais impuros ou aves ou com qualquer criatura que se rasteja pelo chão, os quais Eu tenho separado de vós como impuros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Vocês devem ser santos, pois Eu, Yahweh, sou santo, e Eu vos tenho separado dos outros povos, pois pertenceis a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Um homem ou uma mulher que fala com os mortos ou fala com espíritos certamente devem morrer. O povo deverá apedrejá-los. Eles são culpados e merecem morrer\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Yahweh disse para Moisés: \"Fale aos sacerdotes, os filhos de Arão, e dize-lhes: \'Ninguém entre vós se tornará impuro por causa daquele que morrer entre vosso povo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'com excessão do parente próximo — tua mãe e pai, teu filho e filha, ou teu irmão');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'ou irmã virgem que esteja em tua casa e que não tem marido. Por ela, pode torna-se impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Mas ele não se tornará impuro para outros parentes, pois profanaria a si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Os sacerdotes não devem raspar os cabelos da cabeça ou cortar as extremidades das suas barbas, nem cortar os seus corpos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Eles devem ser separados para o seu Deus, e não desonrarem o nome do seu Deus, porque os sacerdotes apresentam as ofertas queimadas para Yahweh, o pão do seu Deus. Então os sacerdotes devem ser santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Eles não devem se casar com nenhuma mulher que é prostituta e que é profana, e eles não devem se casar com uma mulher divorciada do seu marido, porque eles são separados para o seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Tu santificarás porquanto oferece o pão ao vosso Deus. Ele deve ser santo à vossa vista, porque Eu, Yahweh, que os consagrei para Mim mesmo, Sou santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Qualquer filha de qualquer sacerdote que se profanar, transformando-se numa prostituta, desonra seu pai. Ela deve ser queimada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Aquele que é o sumo sacerdote entre seus irmãos, sobre cuja cabeça o óleo da unção tem sido derramado e que tem sido consagrado para usar as vestimentas especiais do sumo sacerdote, não deve usar seus cabelos soltos ou rasgar as suas vestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Ele não deve ir a qualquer lugar em que um corpo morto esteja presente e se profanar, mesmo se for seu pai ou sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'O sumo sacerdote não deve sair da área do santuário do tabernáculo ou profanar o santuário do seu Deus, porque ele tem sido consagrado como sumo sacerdote pelo óleo da unção do seu Deus. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'O sumo sacerdote tomará por esposa uma mulher virgem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Não deve se casar com uma viúva, uma mulher divorciada, ou uma mulher que seja prostituta. Ele não deve se casar com esses tipos de mulheres. Ele pode somente se casar com uma virgem do seu próprio povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Assim não profanará seus filhos entre seu povo, porque Eu sou Yahweh, quem o santifica\"\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, '\"Fala a Arão e dize-lhe: \'Qualquer dos teus descendentes por todas as gerações que tiver um defeito físico, não deve se aproximar para oferecer o pão do seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Nenhum homem que tenha um defeito físico deve aproximar-se de Yahweh, como um cego, manco, ou que seja desfigurado ou deformado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'ou um homem que seja inválido das mãos ou dos pés,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'corcunda ou anão, ou um homem com defeitos nos olhos, com uma doença, dor, cicatriz, ou algum testículo defeituoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Nenhum homem entre os descendentes do sacerdote Arão, que tenha um defeito físico poderá se aproximar para apresentar as ofertas queimadas para Yahweh. De igual modo, um homem tendo um defeito físico, não deve se aproximar para oferecer o pão para o seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Ele pode comer o pão do seu Deus, tanto do santíssimo como do santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'De qualquer forma, ele não deverá ir além das cortinas ou se aproximar do altar, porque ele tem um defeito físico, então ele não profanará o Meu santo lugar, porque Eu sou Yahweh, que os santifica.\"\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Então, Moisés falou estas palavras para Arão, para os seus filhos, e para todo o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Yahweh falou com Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '\"Fala com Arão e com seus filhos. Dize a eles para manterem-se longe das coisas sagradas do povo de Israel, as quais eles dedicaram a Mim. Eles não devem profanar Meu santo nome. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Diga a eles: \'Qualquer pessoa, dentre todos os vossos descendentes, do começo ao fim das gerações do povo, que esteja suja, quando se aproximar das coisas sagradas que o povo de Israel consagrou a Yahweh, esta pessoa deverá ser excluída da Minha presença. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Nenhum dos descendentes de Arão o qual tenha doença de pele contagiosa, ou uma infecção que flua de seu corpo, poderá comer qualquer um dos sacrifícios feitos a Yahweh até que ele esteja limpo. Qualquer um que tocar qualquer coisa suja pelo contato com os mortos, ou com um homem que tenha fluxo de sêmen,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'ou qualquer um que toque em algum réptil que o faça sujo, ou em qualquer pessoa que o faça sujo, seja o tipo de impureza que for—');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'então, o sacerdote que tocar qualquer coisa suja estará sujo até o anoitecer. Ele não deve comer nenhuma das coisas sagradas, a não ser que tenha banhado seu corpo em água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Quando o sol tiver se posto, ele, então, estará limpo. Depois do pôr do sol, ele poderá comer das coisas sagradas, pois elas são seu alimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Ele não deve comer nenhum animal encontrado morto ou que tenha sido morto por animais selvagens, para que não se contamine. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Os sacerdotes devem seguir Minhas instruções, ou eles serão culpados de pecado e podem morrer por Me profanarem. Eu sou Yahweh, que os santifico para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Ninguém que não pertença à família do sacerdote, incluindo seus convidados ou seus empregados, deve comer qualquer coisa que seja sagrada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Mas, se um sacerdote comprar algum escravo com o seu próprio dinheiro, este escravo poderá comer das coisas reservadas para Yahweh. E os membros da família do sacerdote e os escravos nascidos em sua casa, eles também podem comer com ele destas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Se a filha de um sacerdote casar-se com alguém que não seja um sacerdote, ela não poderá comer quaisquer das ofertas sagradas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Mas, se a filha do sacerdote for viúva, ou divorciada, e se ela não tiver filhos, e voltar a viver na casa do pai como em sua juventude, ela poderá comer da comida do pai. Mas ninguém que não seja da família do sacerdote poderá comer da comida do sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Se um homem comer da comida sagrada sem conhecimento, então ele deve recompensar o sacerdote por isto; ele deve adicionar um quinto ao que comeu e devolver ao sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'O povo de Israel não deve desonrar as coisas sagradas que eles ergueram e apresentaram a Yahweh,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'e nem fazê-los carregarem o pecado que os faça culpados por comerem da comida sagrada, pois eu sou Yahweh, que os santifico para Mim\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Yahweh falou com Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, '\"Fala a Arão e seus filhos, e a todo o povo de Israel e dize-lhes: \'Qualquer israelita, ou estrangeiro morando em Israel, quando apresentarem um sacrifício — quer seja dos seus votos, quer seja oferta voluntária, ou eles apresentem a Yahweh holocausto,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'para que seja aceito, eles devem oferecer um animal macho sem defeito do rebanho de gado, ovelhas, ou cabras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Mas vós não deveis oferecer nada com defeito. Eu não aceitarei isto em vosso favor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Qualquer um que oferecer sacrifício de ofertas pacíficas do gado ou do rebanho a Yahweh para cumprir um voto, ou uma oferta voluntária, este deve ser sem defeito para ser aceito. Não deve haver defeito no animal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Não deveis oferecer animais que estejam cegos, mutilados ou deformados, ou que tenham imperfeições, feridas ou sarna. Não deveis oferecer estes a Yahweh como um sacrifício por fogo no altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Poderás apresentar como ofertas voluntárias, um boi ou um cordeiro que seja comprido ou curto de membros, mas uma oferta como esta não será aceita no lugar de um voto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Não ofereçais animais a Yahweh que tenham tido os testículos esmagados, triturados, ou cortados. Não façais isso em vossas terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Não apresenteis estes de mãos estrangeiras como comida ao vosso Deus, porque eles são defeituosos ou desfigurados. Eles não serão aceitos em vosso favor\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Yahweh falou com Moisés e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '\"Quando nascem um bezerro, uma ovelha ou uma cabra, estes devem permanecer sete dias com suas mães. Então, do oitavo dia em diante, poderão ser aceitos como sacrifício ou oferta feita no fogo para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Não sacrifiqueis uma vaca ou uma ovelha com a sua cria, ambos no mesmo dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Quando vós sacrificardes uma oferta de ação de graças, deveis sacrificar de uma maneira aceitável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Isto deverá ser comido no mesmo dia em que for sacrificado. Não deixeis sobrar nada até a próxima manhã. Eu Sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Então, deveis guardar Meus mandamentos e cumpri-los. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Não desonrareis o Meu santo nome. Eu deverei ser reconhecido como santo pelo povo de Israel. Eu sou Yahweh, que os santifico para Mim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Aquele que vos tirou da terra do Egito, para ser o vosso Deus. Eu sou Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Yahweh falou a Moisés: \"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Dize ao povo de Israel, e fala a eles: \'Os festivais apontados por Yahweh, que tu deverás proclamar como assembéias santas, são Meus festivais regulares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Trabalhareis por seis dias, mas no sétimo dia é o Sábado de completo descanso, a assembéia santa. Não trabalhareis porque é o Sábado para Yahweh em todos os locais onde viveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Estes são os festivais apontados por Yahweh, as assembléias santas que deverás anunciar nos momentos apropriados:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'No primeiro mês, do décimo quarto dia ao entardecer, será a páscoa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'No décimo quinto dia do mesmo mês será o Festival dos Pães sem fermento à Yahweh. Por sete dias deverás comer pão sem fermento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'No primeiro dia vós tereis assembléia dedicada a Yahweh, não deveis trabalhar como de costume.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Devereis oferecer sacrifícios feitos no fogo durante sete dias para Yahweh. O sétimo dia é assembléia dedicada a Yahweh, no qual, não trabalhareis como de costume\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, '\"Fale ao povo de Israel e diga a eles, \'Quando vierdes a terra que vos darei, e quando ceifardes a colheita, então deveis trazer as primícias da colheita ao sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Ele erguerá as primícias na presença de Yahweh como oferta, para que seja aceita em vosso favor. Será depois do Sábado que o sacerdote erguerá e apresentará a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'No dia em que vós erguerdes as primícias em oferta a Mim, devem ser oferecido um cordeiro macho de um ano e sem defeito como sacrificio queimado a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'A oferta de grãos será de dois décimos de efa da melhor farinha misturada ao óleo, uma oferta queimada a Yahweh, a fim de produzir aroma agradável, e juntamente com este uma oferta de libação, um quarto de um him.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Não comereis pão, nem grãos torrados ou frescos, até o mesmo dia que trouxerdes essa oferta a Deus. Este será um mandamento permanente por todas as vossas gerações, onde quer que viverdes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Deverás contar do dia após o Sábado, do dia em que trouxeste a parte colhida para ser erguida em oferta e apresentada, sete semanas completas, sete Sábados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'até o dia após o sétimo Sábado. Ou seja, deverás contar cinquenta dias. Então deverás oferecer uma oferta queimada de novos grãos a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Deverás retirar de suas casas dois pães feitos de dois décimos de um efa. Deverão ser amassados com a melhor farinha e assados com trigo; estes serão uma oferta dos primeiros frutos que serão levantados e apresentados a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Apresentarás junto com os pães sete cordeiros de um ano sem defeito, touro jovem, e dois carneiros. Deverás queima-los em oferta a Yahweh, com a oferta de grãos e as ofertas de vinho, uma oferta queimada para produzir aroma agradável a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Deverás entregar um bode em oferta pelo pecado, e dois cordeiros de um ano para sacrifício, como oferta pacífica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'O sacerdote deverá oferecê-los perante Yahweh, juntamente com os pães dos primeiros frutos, e apresenta-los como oferta junto aos dois cordeiros. Serão ofertas sagradas para Yahweh pelo sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Deverás proclamar isto no mesmo dia. Haverá uma assembléia santa, portanto não trabalharás como de costume. Será ordenança perpétua por todas as vossas gerações em todos os lugares que habitardes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Quando ceifardes a colheita de vossa terra, não deverás faze-lo até os limites dos vossos campos e não ajuntarás as espigas que ficarem pelo caminho. Deveis deixá-las para os pobres e estrangeiros. Eu Sou Yahweh seu Deus\' \".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Yahweh disse a Moisés, falando:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, '\"Fale ao povo de Israel e diga: \'No sétimo mês, o primeiro dia será de descanso solene para vós, um memorial ao toque de trombetas, e uma santa assembleia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Não devais trabalhar como de costume, e devais oferecer sacrificios queimados para Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Então Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '\"Agora o décimo dia deste sétimo mês será o Dia de Expiação. Será uma assembléia dedicada a Yahweh, vós deverdes humilhar-vos e oferecer sacrifícios queimados para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Não trabalhareis neste dia porque é Dia de Expiação, para expiar-vos diante de Yahweh vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Qualquer que não se humilhar neste dia deverá ser excluído do vosso povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Qualquer um que trabalhar neste dia, Eu, Yahweh, destruí-lo-ei do meio do vosso povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Vós não trabalhareis de forma alguma neste dia. Este será um mandamento permanente por todas as gerações do vosso povo onde quer que vós viverdes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Este dia deverá ser o sábado de descanso solene, e vós vos humilhareis no entardecer do nono dia do mês. De uma tarde a outra tarde, o Sábado deve ser guardado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, '\"Fale ao povo de Israel, dizendo: \'Durante o décimo quinto dia do sétimo mês celebrareis o Festival dos Tabernáculos em homenagem a Yahweh. Ela terá duração de sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'No primeiro dia haverá santa assembléia. Não devereis fazer trabalho algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Durante sete dias oferecereis sacrifícios queimados á Yahweh. No oitavo dia haverá santa assembléia, e fareis sacrifício queimado para Yahweh. Esta será uma assembléia solene, portanto não haverá trabalho algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Estes são os festivais apontados por Yahweh, no qual vós proclamareis como assembléia santa para oferecerdes sacrifícios pelo fogo a Yahweh, oferta queimada e oferta de grãos, sacrifícios e libações, cada qual em seu próprio dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Estes festivais vós os adicionareis aos sábados de Yahweh e suas ofertas, todos os vossos votos, e todas as vossas ofertas pacíficas que oferecerdes a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Apesar do Festival dos Tabernáculos, no décimo quinto dia do sétimo mês, quando estiverdes reunidos os frutos da vossa terra, o Festival de Yahweh deverá ter duração de sete dias. O primeiro dia será de descanso solene e o oitavo dia também será de descanso solene.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'No primeiro dia vós deveis retirar o melhor fruto de vossas árvores, galhos de palmeiras, galhos com folhagem das árvores robustas, e salgueiro às margens do ribeiro, regorzijar-se-eis diante de Yahweh, seu Deus, por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Durante sete dias a cada ano, celebrareis este festival a Yahweh. Este será um mandamento perpétuo por todas as gerações do vosso povo onde quer que viverdes. Devereis celebrar este festival no sétimo mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Vós devereis permanecer em pequenas tendas por sete dias. Todos os israelitas natos deverão permanecer em pequenas tendas por sete dias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'para que teus descendentes, geração a geração, aprendam como Eu fiz o povo de Israel viver em pequenas tendas quando Eu os tirei da terra do Egito. Eu sou Yahweh, seu Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Desta forma, Moisés anunciou para o povo de Israel o festival apontado por Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, '\"Ordena ao povo de Israel para que te tragam óleo puro de oliva para suas lamparinas, a fim de que elas sempre queimem e iluminem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Do lado de fora da cortina, diante dos decretos da aliança na Tenda do Encontro, Arão deve, continuamente, manter acesa a lâmpada desde a noite até o amanhecer, diante de Yahweh. Isso será um mandamento permanente ao longo das gerações do Teu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'O sumo sacerdote deve sempre manter as lâmpadas acesas diante de Yahweh, as lâmpadas do candelabro de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Tu deves pegar a boa farinha e usá-la para assar doze pães. Esses devem conter dois décimos de uma efa em cada pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Depois, deves colocá-lo em duas fileiras, seis pães em cada fileira, sobre a mesa de ouro puro diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Tu deves pôr incenso puro ao longo de cada fileira de pães como um símbolo dos pães. Esse incenso será queimado para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Todo dia de sábado, o sacerdote deverá regularmente apresentar o pão diante de Yahweh em nome do povo de Israel, como um sinal de uma aliança perpétua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Essa oferta será de Arão e seus filhos. Eles devem comê-la em um lugar que é santo, pois é dedicada completamente a Mim, pois foram tomadas dentre as ofertas queimadas por fogo a Mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Aconteceu que o filho de uma mulher israelita, cujo o pai era um egípcio, estava entre o povo de Israel. Esse filho da mulher israelita brigou com um homem israelita no acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'O filho da mulher israelita blasfemou o nome de Yahweh e amaldiçoou a Deus, então, o povo o levou a Moisés. O nome de sua mãe era Selomite, a filha de Dibri, da tribo de Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Eles o mantiveram em custódia até que o próprio Yahweh declarasse sua vontade para com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Então, Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, '\"Leva o homem que blasfemou contra Deus para fora do acampamento. Todos os que o ouviram devem colocar as mãos sobre sua cabeça e, depois, a assembléia inteira deve apedrejá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Tu deves explicar ao povo de Israel, dizendo: \'Qualquer um que blasfemar seu Deus deve carregar sua própria culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Aquele que blasfemar o nome de Yahweh deve certamente ser condenado à morte. Toda a assembléia deve certamente apredejá-lo, seja ele um estrangeiro ou um israelita nativo. Se alguém blasfemar o nome de Yahweh, deverá ser condenado à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'E aquele que matar outro homem deve certamente ser condenado à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Aquele que matar o animal de alguém pagará de volta, vida por vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Se um homem ferir a seu vizinho, deverá ser feito a ele como ele fez para com seu vizinho:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'fratura por fratura, olho por olho, dente por dente. Assim como ele causou um ferimento em uma pessoa, deverá também ser feito a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Qualquer que matar um animal deverá pagá-lo de volta e qualquer que matar uma pessoa será condenado à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Tu deves ter a mesma lei para ambos: o estrangeiro e o israelita nativo, pois Eu sou Yahweh, seu Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Então Moisés falou com o povo de Israel, e o povo trouxe o homem para fora do acampamento, aquele que tinha blasfemado Yahweh. Eles o apedrejaram. O povo de Israel levou adiante o mandamento de Yahweh a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Yahweh falou a Moisés no Monte Sinai, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, '\"Fala com o povo de Israel e diga a eles: \'Quando entrares na terra que eu vos dou, guardareis um sábado para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Vós devereis plantar no campo por seis anos, e por seis anos podareis as vossas vinhas e colhereis os frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Mas no sétimo ano, devereis observar um sábado solene de descanso para a terra, um sábado para Yahweh. Não devereis plantar em vosso campo ou podar vossas vinhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Não devereis organizar colheita de qualquer alimento que cresça por si mesma, vós não devereis conduzir colheita organizada de qualquer uva que cresça de vinhas não podadas. Este será um ano de descanso solene para a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Qualquer fruto que a terra não trabalhada produza durante o ano sabático, será comida para vós. Vós, vossos servos e servas, vossos servos contratados e os estrangeiros que vivem convosco certamente colherão comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'E vosso gado, e também os animais silvestres certamente comerão o que quer que a terra há de produzir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Vós devereis contar sete sábados do ano, que serão, sete vezes sete anos, então tereis sete sábados de anos, totalizando quarenta e nove anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Então farás soar uma alta trombeta em todo lugar no décimo dia do sétimo ano. No Dia da Expiação certamente tocarás a trombeta por toda a tua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Vós devereis dedicar o quinquagésimo ano para Yahweh e proclamareis liberdade entre as terras, e para todos os seus habitantes. Este será um ano jubileu para vós, no qual devolvereis propriedades para vossos donos e retornareis escravos para vossas famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'O quinquagésimo ano será um jubileu para vós. Não devereis plantar ou conduzir colheita organizada. Comereis qualquer que nascer por si só, e colhereis as uvas que nascerem de vinhas não podadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Pois é o ano jubileu, o qual será santo para vós. Comereis do campo o que crescer por si só.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Devolvereis a todos suas propriedades no ano jubileu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Se vós venderdes alguma terra a vosso vizinho ou comprardes alguma terra de vosso vizinho, certamente não o enganareis ou trapaceareis uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Se vós comprardes terra de vosso vizinho, considereis o número de anos e safras que poderão ser colhidas até o próximo jubileu. Vosso vizinho o qual vende a terra considerará isto também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Um grande número de anos até o próximo jubileu aumentará o valor da terra, e um menor número de anos até o próximo jubileu diminuirá o valor da terra, porque o número de colheitas que a terra produzirá para o novo proprietário está relacionado com o número de anos até o próximo jubileu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Vós não sereis desonestos ou rudes com vosso próximo; pelo contrário, honrarás vosso Deus, pois Eu sou Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Portanto vós devereis obedecer aos meus decretos, guardareis as Minhas Leis e as levarei adiante. Então vós vivereis na terra em segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'A terra dará frutos, e vós comereis e vos fartareis e ali vivereis em segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Se vós disserdes: \"O que haveremos de comer durante o sétimo ano? Veja, não podemos plantar ou colher ou produzir.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Eu vos ordenarei minha bênção sobre vós no sexto ano, e este ano produzirá safra suficiente para três anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Vós plantareis no oitavo ano e continuareis a comer a colheita do ano anterior e estocareis a comida. Até a próxima colheita do nono ano, podereis comer os mantimentos guardados do ano anterior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Não vendereis a terra para um novo dono permanente, porque a terra é Minha. Vós todos sois estrangeiros e residentes temporários em Minha terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Vós deveis observar o direito de resgate para todas as terras que adquirirdes; devereis permitir que as terras sejam compradas de volta pela família da qual vós comprardes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Se vosso irmão israelita vier a ficar pobre e por esta razão lhe vender alguma propriedade sua, então seu parente mais próximo deverá vir e comprar de volta sua propriedade a que vos foi vendida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Se um homem não tiver parentes para resgatar sua propriedade, mas ele prosperou e tem capacidadede para resgatá-la,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'então ele calculará os anos desde que as terras foram vendidas e pagará o equivalente ao homem a quem vendeu. Então ele certamente voltará a sua propriedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Mas se ele não for capaz de tomar a terra de volta para si, então a terra vendida permanecerá na posse daquele que a comprou até o ano jubileu. No ano jubileu, a terra será devolvida ao homem que a vendeu, e o seu dono original retornará à sua propriedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Se um homem vender uma casa em uma cidade murada, então ele poderá comprá-la de volta dentro de um ano após ser vendida. Por um ano inteiro ele terá o direito de resgatá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Se a casa não for resgatada dentro de um ano inteiro, então a casa na cidade murada se tornará propriedade permanente do homem que a comprou, por toda geração de seus descendente. Esta casa não será devolvida no ano jubileu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mas as casas das vilas que não tiverem muros ao redor serão propriedades ligadas aos campos do país. Elas poderão ser compradas de volta, e deverão ser devolvidas durante o jubileu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Entretanto, as casas pertencentes aos levitas em suas cidades poderão ser resgatadas a qualquer hora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Se algum dos levitas não resgatar a casa que ele vendeu, então a casa vendida, na cidade onde certamente está localizada, será devolvida no jubileu, pois as casas das cidades dos levitas são suas propriedades entre o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Mas os campos em volta das cidades não poderão ser vendidos porque eles são propriedades permanentes dos levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Se o vosso compatriota se empobrecer a ponto de não poder se sustentar, então devereis ajudá-lo como ajudarias um estrangeiro ou qualquer outro estranho vivendo entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Não cobrareis juros nem tentareis obter lucro por meio dele de maneira alguma, mas honrareis vosso Deus e vosso irmão continuará vivendo convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Não empresteis dinheiro a ele com juros, nem vendais vossa comida visando ganhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Eu sou Yahweh vosso Deus, quem vos tirou do Egito, para vos dar a terra de Canaã, para ser o vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Se vosso compatriota vier a empobrecer e se vender para vós, não devereis tratá-lo como escravo. O tratareis como servo contratado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Ele será como alguém que vive temporariamente convosco. Ele servirá convosco até o ano jubileu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Então ele vos deixará, ele e suas crianças com ele, e ele retornará para sua própria família e para a propriedade de seus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Pois eles são Meus servos os quais os trouxe para fora da terra do Egito. Eles não serão vendidos como escravos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Não dominareis severamente sobre eles, mas certamente honrareis vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Quanto aos vossos escravos e vossas escravas, podereis obtê-los das nações que vivem a vossa volta, certamente comprareis dos que tiverem ao vosso redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Vós também podereis comprar escravos de estrangeiros que estão vivendo dentre vós, isto é, de suas famílias que estão no meio de vós, crianças que nasceram em vossas terras. Elas se tornarão vossa propriedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Devereis providenciar escravos como herança para vossas crianças depois de vós, para manter como propriedade. Destes, sempre tomareis vossos escravos, mas não dominareis severamente sobre vossos irmãos dentre o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Se um estrangeiro ou alguém que vive temporariamente convosco se tornar rico, e um dos vossos irmãos israelitas se tornar pobre e vender a si mesmo para este estrangeiro, ou para alguém da família do estrangeiro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'depois de vosso irmão israelita ter sido comprado, ele poderá ser comprado de volta. Alguém de sua família poderá resgatá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Poderá ser seu tio, ou o filho de seu tio, a resgatá-lo ou qualquer outro parente que seja próximo a sua família. Ou se tiver se tornado próspero poderá resgatar a si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Ele terá que negociar com o homem que o comprou; eles devem contar os anos desde o ano em que ele se vendeu para seu senhor até o ano jubileu. O preço de sua redenção se baseará no preço de um servo contratado, pelo número de anos que ele trabalharia para aquele que o comprou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Se faltarem muitos anos até o jubileu, ele deve pagar como preço por sua redenção a quantia proporcional ao número destes anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Se houver poucos anos para o ano jubileu, então ele deve negociar com seu senhor a quantidade de anos antes do jubileu, e pagará por sua redenção proporcionalmente ao número de anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Ele deve ser tratado como um homem contratado anualmente. Vós deveis certificar que ele não será tratado severamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Se ele não for remido sobre estes termos então ele deve servir até o ano jubileu e seus filhos com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Para Mim o povo de Israel é servo. Eles são Meus servos, os quais trouxe para fora da terra do Egito. Eu sou Yahweh, vosso Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '\"Não farás ídolos, muito menos erguerás imagens esculpidas ou pilares sagrados de pedra, e não porás nenhuma imagem esculpida em sua terra para te curvares, pois Eu sou Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Deveis guardar os Meus Sábados e honrar o Meu santuário. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Se andardes nas Minhas leis e guardardes os Meus mandamentos e os obedecerdes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'então, Eu darei chuva em sua estação; a terra entregará sua produção, e as árvores do campo entregarão seus frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Debulharás continuamente até a época de colher uvas, e essa colheita se estenderá até a estação do plantio. Comereis todo vosso pão e vivereis seguramente no local onde construístes vosso lar na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Eu darei paz na terra; deitar-vos-ei e nada temereis, afastarei os animais perigosos da vossa terra, e a espada não passará pela terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Perseguireis vossos inimigos, e eles cairão diante de vós pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Cinco de vós perseguirão a cem, e cem de vós perseguirão a dez mil; vossos inimigos cairão diante de vós pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Eu olharei para vós com favor e vos farei frutíferos e vos multiplicarei. Eu firmarei minha aliança convosco. Comerão por muito tempo da colheita estocada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Tereis de retirar a colheita do depósito, porque precisareis de mais espaço para a nova colheita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Eu colocarei meu tabernáculo em vosso meio, e Eu não vos detestarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Eu andarei em vosso meio e serei vosso Deus, e vós sereis meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Eu Sou Yahweh, seu Deus, que te trouxe da terra do Egito, para que não fostes seus escravos. Eu quebrei as barras dos vossos ombros, para fazer-vos andar de forma reta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Porém se vós não Me ouvirdes a Mim, e não obedecerdes a todos esses mandamentos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'e rejeitar Meus decretos e detestardes Minhas Leis, de maneira que não obedeçais todos os Meus mandamentos, e quebrar Minha Aliança,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'se fizerdes essas coisas, então Eu farei isto convosco: Eu infligirei terror em vós, doenças e febre que destruirão vossos olhos e drenarão vossas vidas. Vós plantareis vossas sementes por nada, porque vossos inimigos comerão de vossa produção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Eu porei o Meu rosto contra vós, e vós sereis sobrepujados por vossos inimigos. Homens que vos odeiam governar-vos-ão, e vós correreis mesmo quando ninguém vos perseguir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Se vós não ouvirdes aos meus mandamentos, então Eu os punirei sete vezes mais por vossos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Quebrarei vosso orgulho no vosso poder. Eu farei o céu sobre vós como aço e vossa terra, como bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Vossa força não servirá de nada, porque vossa terra não produzirá a sua colheita, e vossas árvores não produzirão seus frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Se vós andardes contra Mim e não ouvirdes a Mim, Eu trarei sete vezes mais golpes sobre vós, proporcionalmente aos vossos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Eu enviarei animais perigosos contra vós, que tomarão vossos filhos, destruirão vosso rebanho, e farão vossa população diminuir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Se, mesmo assim, vós não aceitardes Meus ensinamentos, mas continuardes andando contra Mim, então Eu também andarei contra vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Eu pessoalmente vos punirei sete vezes mais por vossos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Eu trarei sobre vós a espada que executará vingança por teres quebrado Minha aliança. Vós sereis reunidos dentro de vossas cidades, e Eu enviarei doenças sobre vós, e então sereis derrotados pelo poder de vosso inimigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Quando Eu cortar o vosso suprimento de comida, dez mulheres serão capazes de assar seu pão em um forno, e elas distribuirão o seu pão por peso. Vós comereis, mas não vos satisfareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Se mesmo assim, vós não Me ouvirdes, mas continuardes contra Mim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'então Minha ira se acenderá contra vós, e Eu vos punirei até sete vezes mais tanto quanto vossos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Vós comereis a carne de vossos filhos; vós comereis a carne de vossas filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Eu destruirei vossos altares, derrubarei vossos altares de incenso, e lançarei vossos cadáveres sobre os cadáveres de vossos ídolos, e Eu pessoalmente vos abominarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Eu tornarei vossas cidades em ruínas e destruirei vossos santuários. Eu não me agradarei com o aroma de vossos ofertas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Eu devastarei a terra. Vossos inimigos que viverão ali ficarão chocados com a devastação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Eu vos dispersarei de diante das nações, e Eu desembainharei Minha espada para vos perseguir. Vossa terra será abandonada e vossas cidades serão arruinadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Então a terra desfrutará de seus sábados por todo o tempo que ficar abandonada, e vós estareis na terra de vossos inimigos. Durante este tempo, a terra descansará e aproveitará seus sábados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Pelo tempo que permanecer abandonada, terá seu descanso, será o descanso que não teve em vossos sábados enquanto vós vivestes ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Aos remanescentes dentre vós, deixados nas terras de vossos inimigos, Eu enviarei medo em seus corações de modo que mesmo o som de uma folha lançada ao vento os amedrontará, e vós correreis como quem corre da espada. Vós caireis, mesmo quando ninguém estiver vos perseguindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Vós tropeçareis em vós mesmos como se estivésseis correndo da espada, ainda que ninguém vos esteja perseguindo. Não tereis poder para resistir ao vosso inimigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Vós perecereis entre as nações e a própria terra dos vossos inimigos vos devorará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'O restante de vós se perderá em vossos pecados, na terra de vossos inimigos e, por conta dos pecados de vossos pais, perecerão também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Porém se eles confessarem os seus pecados e os pecados de seus pais, e sua traição pela qual eles foram infiéis a Mim, e também seus caminhos contra Mim —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'os quais Me fizeram voltar contra eles e os entregar na terra de seus inimigos — se seus corações incircuncisos se tornarem humildes, e se eles aceitarem a punição por seus pecados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'então Eu Me lembrarei da Minha aliança com Jacó, Minha aliança com Isaque, e Minha aliança com Abraão; Eu também me lembrarei da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'A terra será abandonada por eles, então ela desfrutará com seus sábados enquanto estiver abandonada sem eles. Eles deverão pagar a penalidade por seus pecados, porque eles próprios rejeitaram Meus decretos e detestaram Minhas leis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Mas, apesar de tudo isso, quando eles estiverem na terra de seus inimigos, Eu não os rejeitarei, nem os detestarei para destruí-los completamente e desfazer a minha aliança com eles, pois Eu sou Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Mas, por misericórdia, Eu me lembrarei da aliança que Eu fiz com seus antepassados, os quais Eu tirei da terra do Egito, à vista das nações, para que Eu seja seu Deus. Eu sou Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Estes são os mandamentos, decretos, e leis que Yahweh fez entre Ele mesmo e o povo de Israel no Monte Sinai, através de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, '\"Fala ao povo de Israel e diz a eles: \'Quando um homem fizer um voto especial, que requer que ele use um valor padrão para uma pessoa, que ele dedique a Yahweh, usando os seguintes valores:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Seu valor padrão para um homem de vinte a sessenta anos de idade será de cinquenta siclos de prata, de acordo com o siclo do santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Para uma mulher da mesma idade, seu valor padrão será de trinta siclos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'De cinco a vinte anos de idade, seu valor padrão para um homem, será de vinte siclos e para a mulher, dez siclos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'De um mês de idade até cinco anos, o valor padrão para um homem será de cinco siclos de prata e para a mulher, três siclos de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'A partir de sessenta anos de idade para um homem, o padrão de valor será de quinze siclos de pratas e para uma mulher, dez siclos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Mas, se a pessoa que estiver fazendo o voto não puder pagar o valor padrão, então, a pessoa oferecida deverá ser apresentada ao sacerdote. O sacerdote avaliará a pessoa, de acordo com o valor que aquele que fez o voto seja capaz de pagar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Se alguém quiser sacrificar um animal a Yahweh, e se Yahweh o aceitar, então aquele animal será dedicado a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'A pessoa não deve alterar ou trocar o animal, um bom por um ruim ou um ruim por um bom. Se ele, de qualquer forma, trocar um animal pelo outro, ambos tornar-se-ão consagrados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'No entanto, se o que foi ofertado a Yahweh for, de fato, impuro, de forma que Yahweh não irá aceitá-lo, então a pessoa deverá levá-lo ao sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'O sacerdote irá avaliá-lo de acordo com o valor de mercado do animal. Qualquer valor que o sacerdote colocar sobre o animal, será o valor determinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'E se o proprietário desejar resgatá-lo, então a quinta parte de seu valor será adicionada ao seu preço de redenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Quando um homem desejar dedicar sua casa para ser consagrada a Yahweh, então o sacerdote estimará seu valor. Qualquer que seja o valor estabelecido pelo sacerdote, este será seu valor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Mas, se o proprietário dedicar sua casa e mais tarde desejar resgatá-la, então a quinta parte de seu valor, será adicionada ao seu valor de redenção. Desse modo, a casa será dele novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Se um homem desejar dedicar a Yahweh parte de sua terra, então o cálculo de seu valor será feito de acordo com a quantidade de semente necessária para plantar nela. Um hômer de cevada será avaliado em cinquenta siclos de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Se ele dedicar seu campo durante o ano jubileu, o valor estimado permanecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Mas, se ele dedicar seu campo após o jubileu, então o sacerdote deverá calcular o valor da propriedade de acordo com o número de anos que restarem até o próximo ano do jubileu, e o valor estimado deverá ser reduzido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Se o homem que dedicar seu campo, desejar resgatá-lo, então ele deverá adicionar a quinta parte do valor estimado e será dele novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Se ele não resgatar o campo, ou se o tiver vendido para outro homem, não poderá ser resgatado mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Em vez disso, o campo, quando for liberado no jubileu, será uma oferta santa a Yahweh, como um campo que tenha sido completamente ofertado a Yahweh. Este pertencerá ao sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Se um homem dedicar a Yahweh um campo que ele tenha comprado, mas que não for parte da propriedade de sua família,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'então, o sacerdote irá determinar o valor até o ano do jubileu e o homem deverá pagar o seu valor, naquele dia, como uma oferta santa a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'No ano do jubileu, o campo retornará para o homem que comprou, para o proprietário do terreno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Todo o valor estimado, será baseado no peso do ciclo do santuário. Vinte geras deverá ser equivalente a um ciclo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Mas um primogênito entre os animais pertencerá a Yahweh e poderá dedicá-lo. Quer seja o boi ou ovelha, pertencerá a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Se o animal estiver impuro, então o proprietário poderá comprá-lo de volta no valor estimado e a quinta parte será adicionada, naquele valor. Se o animal não é resgatado, então será vendido pelo valor determinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'No entanto, nada o que um homem dedicar a Yahweh, de tudo o que possui, seja humano ou animal, ou sua propriedade familiar, pode ser vendido ou resgatado. Tudo o que é dedicado é muito sagrado para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Nenhum resgate pode ser pago ao anátema que está designado para ser destruído. Esta pessoa será morta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Todo o dízimo da terra, quer cereais na terra, quer o fruto das árvores, é de Yahweh. Isto é consagrado a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Se um homem quiser resgatar o dízimo, deverá adicionar a quinta parte do valor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Quanto a todo o dízimo do rebanho doméstico, qualquer um que passar sob o cajado do pastor, será dedicado a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'O pastor não deverá procurar o melhor ou o pior dos animais, e ele não deverá substituir um pelo outro. Se ele trocar um pelo outro, ambos este ou aquele que for trocado será consagrado. E este não será resgatado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Estes são os mandamentos que Yahweh ordenou no Monte Sinai a Moisés, para o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Yahweh falou a Moisés na Tenda do Encontro no deserto do Sinai, no primeiro dia do segundo mês durante o segundo ano após o povo de Israel ter saído da terra do Egito. Yahweh disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '\"Realiza um censo de todos os homens de Israel, conforme cada clã, de acordo com a família de seus pais. Conta nominalmente, homem por homem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'todos aqueles que tiverem de vinte anos de idade para cima, que são aptos a lutarem como soldados por Israel. Tu e Arão registrareis o número de homens de acordo com grupo armado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Um homem de cada tribo, o cabeça do clã, deve servir convosco como o líder de sua tribo. Cada um deverá liderar os homens que lutarão por sua tribo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Estes são os nomes dos líderes que lutarão convosco: da tribo de Rúben, Elizur, filho de Sedeur;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'da tribo de Simeão, Selumiel, filho de Zurisadai;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'da tribo de Judá, Nasom, filho de Aminadabe;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'da tribo de Issacar, Netanel, filho de Zuar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'da tribo de Zebulom, Eliabe, filho de Helom;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'da tribo de Efraim, filho de José, Elisama, filho de Amiúde; da tribo de Manassés, Gamaliel, filho de Pedazur;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'da tribo de Benjamim, Abidã, filho de Gideoni;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'da tribo de Dã, Aiezer, filho de Amisadai;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'da tribo de Aser, Pagiel, filho de Ocrã;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'da tribo de Gade, Eliasafe, filho de Deuel;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'e, da tribo de Naftali, Airá, filho de Enã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Esses foram os homens escolhidos pelo povo. Eles lideraram as tribos de seus antepassados. Eles foram os líderes dos clãs em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Moisés e Arão convocaram esses homens, que foram designados pelos seus nomes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'e, junto a eles, reuniram todos os homens de Israel, no primeiro dia do segundo mês. Depois, cada homem de vinte anos de idade para cima identificou seu antepassado, nomeando os clãs e as famílias descendentes de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Então, Moisés registrou seus números no deserto do Sinai, como Yahweh lhe ordenara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Dos descendentes de Rúben, o primogênito de Israel, foram contados os nomes de todo homem de vinte anos de idade para cima apto a ir para a guerra, dos registros de seus clãs antepassados e famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Foram contados quarenta e seis mil e quinhentos homens da tribo de Rúben.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Dos descendentes de Simeão, foram contados todos os nomes de cada homem de vinte anos de idade para cima apto a ir para a guerra, dos registros dos clãs e das famílias de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Foram contados cinquenta e nove mil e trezentos homens da tribo de Simeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Dos descendentes de Gade, foram contados os nomes de todo homem de vinte anos de idade para cima apto a ir para a guerra, dos registros de seus clãs antepassados e famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Foram contados quarenta e cinco mil seiscentos e cinquenta homens da tribo de Gade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Dos descendentes de Judá, foram contados os nomes de todo homem de vinte anos de idade para cima apto a ir para a guerra, dos registros de seus clãs antepassados e famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Foram contados setenta e quatro mil e seiscentos homens da tribo de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Dos descendentes de Issacar, foram contados os nomes de todo homem de vinte anos de idade para cima apto a ir para a guerra, dos registros de seus clãs antepassados e famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Foram contados cinquenta e quatro mil e quatrocentos homens da tribo de Issacar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Dos descendentes de Zebulom, foram contados os nomes de todo homem de vinte anos de idade para cima apto a ir para a guerra, dos registros de seus clãs antepassados e famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Foram contados cinquenta e sete mil e quatrocentos homens da tribo de Zebulom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Dos descendentes de Efraim, filho de José, foram contados os nomes de todo homem de vinte anos de idade para cima apto a ir para a guerra, dos registros de seus clãs antepassados e famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Foram contados quarenta mil e quinhentos homens da tribo de Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Dos descendentes de Manassés, filho de José, foram contados os nomes de todo homem de vinte anos de idade para cima apto a ir para a guerra, dos registros de seus clãs antepassados e famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Foram contados trinta e dois mil e duzentos homens da tribo de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Dos descendentes de Benjamim, foram contados os nomes de todo homem de vinte anos de idade para cima apto a ir para a guerra, dos registros de seus clãs antepassados e famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Foram contados trinta e cinco mil e quatrocentos homens da tribo de Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Dos descendentes de Dã, foram contados os nomes de todo homem de vinte anos de idade para cima apto a ir para a guerra, dos registros de seus clãs antepassados e famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Foram contados sessenta e dois mil e setecentos homens da tribo de Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Dos descendentes de Aser, foram contados os nomes de todo homem de vinte anos de idade para cima apto a ir para a guerra, dos registros dos clãs e das famílias de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'contados quarenta e um mil e quinhentos homens da tribo de Aser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Dos descendentes de Naftali, foram contados os nomes de todo homem de vinte anos de idade para cima apto a ir para a guerra, dos registros dos clãs e das famílias de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Foram contados cinquenta e três mil e quatrocentos homens da tribo de Naftali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Moisés e Arão contaram todos esses homens, junto aos doze homens que estavam liderando as doze tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Então, todos os homens de Israel de vinte anos de idade para cima, todos os que poderiam lutar na guerra, foram contados em cada uma de suas famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Foram contados seiscentos e três mil quinhentos e cinquenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Mas os homens que eram descendentes de Levi não foram contados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'porque Yahweh dissera a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '\"Tu não contarás a tribo de Levi, nem levantarás o censo deles entre os filhos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Em vez disso, encarregarás os levitas de cuidar do Tabernáculo do Testemunho, cuidando de todas as suas mobílias e de tudo que nele há. Eles transportarão o Tabernáculo e as suas mobílias, cuidarão dele e acamparão ao seu redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Quando o Tabernáculo tiver que ser transportado para outro lugar, os levitas o desarmarão. Quando o Tabernáculo tiver de ser armado, os levitas o farão. Qualquer estranho que chegar perto do Tabernáculo será morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Quando o povo de Israel montar suas tendas, cada homem o fará perto da bandeira que pertence ao seu grupo armado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Porém, os levitas armarão suas tendas ao redor do Tabernáculo do Testemunho, para que Minha fúria não caia sobre o povo de Israel. Os levitas guardarão o Tabernáculo do Testemunho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'O povo de Israel fez todas essas coisas. Eles fizeram tudo que Yahweh ordenou através de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Yahweh falou novamente para Moisés e Arão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, '\"Todos os descendentes de Israel devem acampar envolta de sua bandeira, com o emblema da sua tribo. Suas tendas ficarão ao redor da tenda do encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Aqueles que pertencem à tribo de Judá devem acampar ao redor da bandeira de Judá, a leste da Tenda do Encontro, na direção do nascer do sol. Nason, filho de Aminadabe será o líder do exército de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'O exército de Judá tinha setenta e quatro mil e seiscentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'A tribo de Issacar deve acampar ao lado de Judá. Netanel, filho de Zuar será o lider do exército de Issacar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'O exército dele tinha cinquenta e quatro mil e quatrocentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'A tribo de Zebulom deve acampar ao lado de Issacar. Eliabe, filho de Helom será o lider do exército de Zebulom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'O exército dele tinha cinquenta e sete mil e quatrocentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'O exército acampado junto as tendas de Judá, eram ao todo de cento e oitenta e seis mil e quatrocentos homens. Eles serão os primeiros a levantar o acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'A tribo de Rúben acampará no lado sul, ao redor da sua bandeira. Elizur, filho de Sedeur será o líder do exército de Rúben.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'O exército dele tinha quarenta e seis mil e quinhentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'A tribo de Simeão acampará ao lado da tribo de Rúben. Selumiel, filho de Zurisadai será o líder do exército de Simeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'O exército dele tinha cinquenta e nove mil e trezentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'A tribo de Gade estará ao lado. Eliasafe, filho de Deuel será o líder do exército de Gade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'O exército dele tinha quarenta e cinco mil e seiscentos e cinquenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Os exércitos acampados junto as tendas de Rúben, eram ao todo de cento e cinquenta e um mil e quatrocentos e cinquenta homens. Eles serão os segundos a levantar acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Em seguida, a Tenda do Encontro levantará acampamento junto com os levitas, no centro de todos os acampamentos. Eles devem levantar acampamento na mesma ordem que eles acamparam. Cada homem deve estar em seu lugar, junto a sua bandeira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'A tribo de Efraim deverá acampar no lado oeste da tenda do encontro. Elisama, filho de Amiúde será o lider do exército de Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'O exército dele tinha quarenta mil e quinhentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'A tribo de Manassés acampará ao lado de Efraim. Gamaliel, filho de Pedazur será o líder do exército de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'O exército dele tinha trinta e dois mil e duzentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'A Tribo de Benjamim estará ao lado. Abidã, filho de Gideoni será o líder do exército de Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'O exército dele tinha trinta e cinco mil e quatrocentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Os exércitos acampados junto as tendas de Efraim eram ao todo de cento e oito mil e cem homens. Eles serão os terceiros a levantar acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'O tribo de Dã acampará na parte norte da tenda, ao redor da sua bandeira. Aiezer filho de Amisadai, será o líder do exército de Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'O exército dele tinha sessenta e dois mil e setecentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'A tribo de Aser acampará ao lado da tribo de Dã. Pagiel, filho de Ocrã será o lider do exército de Aser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'O exército dele tinha quarenta e um mil e quinhentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'A tribo de Naftali acampará ao lado. Airá, filho de Enã será o líder do exército de Naftali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'O exército dele tinha cinquenta e três mil e quatrocentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Os exércitos acampados junto as tendas de Dã eram ao todo de cento e cinquenta e sete mil e seiscentos homens. Eles serão os últimos a levantar acampamento com sua bandeira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Estes é o numero dos exércitos dos Israelitas contados de acordo com suas tribos. Todos os exércitos contados em seus acampamentos eram ao todo de seiscentos e três mil e quinhentos e cinquenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Mas, os Levitas não foram contados entre as pessoas de Israel. Isso aconteceu como Yahweh tinha ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'O povo de Israel fez tudo o que Yahweh ordenou a Moisés. Eles acamparam de acordo com suas bandeiras. Eles levantaram acampamento de acordo com a sequência das suas tribos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Essa é a história dos descendentes de Arão e Moisés, quando Yahweh falou com Moisés no Monte Sinai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Os nomes dos filhos de Arão eram Nadabe, o primogênito, e Abiú, Eleazar e Itamar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Estes são os nomes dos filhos de Arão, que foram ungidos e ordenados a servir como sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Mas, Nadabe e Abiú caíram mortos diante de Yahweh, quando ofereceram fogo estranho no deserto do Sinai. Nadabe e Abiú não tinham filhos, portanto, somente Eleazar e Itamar serviram como sacerdotes com Arão, pai deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Yahweh falou a Moisés e disse-lhe:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, '\"Traz a tribo de Levi e os apresentem a Arão, o sacerdote, para que eles o ajudem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Eles cumprirão suas obrigações em nome de Arão e de toda a comunidade, diante da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Eles servirão no Tabernáculo. Eles cuidarão de todas as mobílias da Tenda do Encontro, e ajudarão as tribos de Israel, nos ofícios do Tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Tu dedicarás os levitas a Arão e seus filhos. Eles serão inteiramente separados para ajudá-los a servir o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Tu escolherás, Arão e seus filhos como sacerdotes, mas qualquer estrangeiro que se aproximar, será morto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Yahweh falou a Moisés. Disse-lhe:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '\"Eu escolhi os levitas do meio do povo de Israel. Eu fiz assim, ao invés de escolher cada primogênito masculino nascido no meio dos israelitas. Os levitas pertencem a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Todos os primogênitos pertencem a Mim. No dia em que matei todos os primogênitos na terra do Egito, Eu separei todos os primogênitos de Israel para Mim, tanto homens quanto animais. Eles pertencem a Mim. Eu sou Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Yahweh falou a Moisés no deserto de Sinai. Disse-lhe:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '\"Conta os descendentes de Levi em cada família, nas casas de seus antepassados. Conta todos os homens que têm um mês de idade até o mais velho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Moisés os contou, seguindo as direções dadas a ele pelas palavras de Yahweh, como Ele, o Senhor, lhe ordenara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Os nomes dos filhos de Levi eram: Gérson, Coate e Merari.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Os clãs que vieram dos filhos de Gérson, foram Líbni e Simei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Os clãs que vieram dos filhos de Coate, foram Anrão, Izar, Hebrom e Uziel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Os clãs que vieram dos filhos de Merari foram Mali e Musi. Esses eram os clãs dos levitas, listados clã por clã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Os clãs dos Libnitas, a geraçâo dos Simeítas, vieram de Gérson. Esses são os clãs dos Gersonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Todos os homens de um mês de idade até o mais velho foram contados, totalizando sete mil e quinhentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Os clãs dos Gersonitas devem acampar, do lado oeste do Tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Eliasafe, filho de Lael liderará os clãs dos descendentes dos gersonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'A família de Gérson cuidará da Tenda do Encontro, incluindo o Tabernáculo. Eles cuidarão da Tenda, da sua cobertura e da cortina da entrada da Tenda da Congregação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'Eles devem cuidar das tapeçarias do pátio, das cortinas da entrada do pátio, do pátio ao redor do santuário e do altar. Eles cuidarão das cordas da Tenda do Encontro e de todo seu conteúdo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Estes são os clãs vindos de Coate: o clã dos Anramitas, o clã dos Izaritas, o clã dos Hebronitas, o clã dos Uzielitas. Estes clãs pertencem aos Coatitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Oito mil e seiscentos homens foram contados de um mês de idade até o mais velho, para cuidarem das coisas que pertenciam a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'As famílias dos descendentes de Coate devem acampar no lado sul do Tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Elizafã, filho de Uziel liderará os clãs dos coatitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Eles cuidarão da arca, da mesa, do candelabro, dos altares, dos utensílios sagrados usados nos cultos, da cortina e de tudo que envolva esse trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Eleazar, filho de Arão, o sacerdote, será o homem que liderará os levitas. Ele supervisionará o homem responsável pelo lugar santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Dois clãs vieram de Merari: o clã dos Malitas e o clã dos Musitas. Estes clãs vieram de Merari.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Seis mil e duzentos homens foram contados de um mês de idade até o mais velho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Zuriel, filho de Abiail, deverá liderar os clãs de Merari. Eles devem acampar no lado norte do Tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Os descendentes de Merari cuidarão do conjunto de estruturas do Tabernáculo, das barras transversais, colunas, bases, e tudo que está relacionado a isso, incluindo');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'os pilares e colunas que estão nos arredores do Tabernáculo, com suas bases, estacas e cordas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Moisés, Arão e seus filhos devem acampar do lado leste do Tabernáculo, perante a Tenda do Encontro, voltados para o nascer do sol. Eles serão os responsáveis pelo cumprimento dos deveres do lugar santo, em prol do povo de Israel. Qualquer estrangeiro que se aproximar do lugar santo deverá ser morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Moisés e Arão contaram todos os homens do clã de Levi que eram da idade de um mês até o mais velho, como Yahweh os ordenou. Eles contaram vinte e dois mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Yahweh disse a Moisés: \"Conta todos os primogênitos do povo de Israel que são das idades de um mês até o mais velho. Lista-os por nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Tu dedicarás os levitas para Mim, ao invés de todos os primogênitos do povo de Israel. Eu sou Yahweh. E tu dedicarás o gado dos levitas, ao invés dos primogênitos dos animais dos descendentes de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Moisés contou todos os primogênitos do povo de Israel, como Yahweh lhe ordenara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Ele contou todos os primogênitos masculinos por nome, de um mês de idade até o mais velho, totalizando vinte e dois mil, duzentos e setenta e três homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Novamente, Yahweh falou a Moisés. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '\"Separa para Mim os levitas, ao invés de todos os primogênitos do meio do povo de Israel e separa para Mim os animais dos levitas, ao invés dos animais do povo. Os levitas pertencem a Mim. Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Tu coletará cinco siclos pela redenção de cada um dos duzentos e setenta e três primogênitos de Israel, que excederam o número dos levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Tu usará os siclos do santuário como um padrão de peso. O siclo equivale a vinte geras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Tu dará o preço da redenção que tu pagastes a Arão e a seus filhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Então Moisés coletou o pagamento de redenção do povo, que excedia o número de resgatados pelos levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Moisés coletou o dinheiro dos primogênitos do povo de Israel. Ele coletou mil trezentos e sessenta e cinco siclos, segundo o siclo do santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Moisés deu a Arão e seus filhos o dinheiro recebido. Moisés fez tudo o que lhe foi dito para fazer, pela palavra de Yahweh, assim como Ele ordenara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Yahweh falou para Moises e Arão. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '\"Conduzi o censo dos descendentes homens de Coate entre os levitas, por seus clãs e antepassados das famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Contai todos os homens que têm entre trinta e cinquenta anos de idade. Esses homens entrarão para servir na Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Os descendentes de Coate cuidarão das coisas mais santas, separadas por Mim, na Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Quando o acampamento se preparar para avançar, Arão e seus filhos entrarão na Tenda, baixarão a cortina que separa o lugar mais santo do lugar santo, e cobrirão a Arca da Aliança com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Eles a cobrirão com pele de peixe-boi e espalharão um tecido azul sobre ela e inserirão as varas nos anéis da Arca para carregá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Eles forrarão a mesa dos pães da presença com um tecido azul. Sobre ela, colocarão as louças, as colheres, bacias, e as jarras para oferta. Os pães sempre estarão sobre a mesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Eles os cobrirão com um tecido vermelho escuro, novamente com pele de peixe-boi, e inserirão as varas nos anéis das mesas para carregá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Tomarão um pano azul e cobrirão o candelabro da luminária, juntamente com seus lampiões, pegadores, bandejas, e todas as jarras de azeite para os lampiões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Eles envolverão os candelabros e todos os seus acessórios com a pele do peixe-boi, e os colocarão em um suporte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Estenderão um pano azul sobre o altar de ouro e o cobrirão com pele de peixe-boi para, em seguida, inserir as varas de carregar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Eles juntarão todos os utensílios para o trabalho no lugar santo e os envolverão em um tecido azul, para, então, cobri-los com pele de peixe-boi e colocá-los no suporte de carregar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Eles removerão as cinzas do altar e o cobrirão com um tecido roxo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Colocarão nele todos os utensílios usados no serviço: os braseiros, garfos, pás, tigelas e todos os outros utensílios do altar. E cobrirão o altar com a pele de peixe-boi para, então, inserir as varas de carregar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Quando Arão e seus filhos cobrirem completamente o lugar santo e todos os seus utensílios, e quando o acampamento avançar, então os descendentes de Coates devem carregar o lugar santo. Se eles tocarem os instrumentos santos, morrerão. Este é o trabalho dos descendentes de Coate, de carregar as mobílias da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eliazar, filho do sacerdote Arão, carregará o azeite para o lampião. Ele deve supervisionar o carregamento do incenso doce, o cereal da oferta regular, o óleo da unção, todo o Tabernáculo e tudo que está nele, as mobílias santas e os utensílios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Yahweh falou para Moisés e Arão. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '\"Não permitais que o clã tribal dos coatitas seja removido dentre os levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Protegei-lhes, para que eles vivam e não morram fazendo isso. Quando eles se aproximarem das coisas mais santas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'eles não entrarão para ver o lugar santo, nem sequer por um momento, ou, então, morrerão. Arão e seus filhos serão quem entrarão. Estes são os que atribuirão a cada coatita sua tarefa, sua habilidade especial\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Yahweh falou novamente para Moisés. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '\"Conduze também um censo dos descendentes de Gérson, dos ancestrais das famílias de seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Conta todos os que têm de trinta a cinquenta anos de idade. Conta todos os que entrarão no serviço para fazer o trabalho na Tenda do Encontro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Este é o trabalho da tribo dos gersonitas, o que devem fazer e o que devem carregar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Eles carregarão as cortinas do Tabernáculo, a Tenda do Encontro, suas cobertas, as cobertas do peixe-boi que estão sobre ela, e as cortinas para a entrada da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'Eles devem carregar as cortinas do pátio, as cortinas da entrada da porta do pátio, que está perto do Tabernáculo e próximo do altar, suas cordas, e todos os utensílios para o serviço. Servirão em tudo o que diz respeito a essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Arão e seus filhos direcionarão todo o serviço dos descendentes dos gersonitas, em todas as coisas que eles transportarem, e em todos os seus serviços. Vós deveis designá-los para todas as suas responsabilidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Este é o serviço do clã dos descendentes dos gersonitas para a Tenda do Encontro. Itamar, filho de Arão, o sacerdote, deve liderá-los nos seus serviços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Tu contarás os descendentes de Merari por suas tribos, e os ordenarão pelas famílias de seus antepassados, de trinta anos de idade até cinquenta anos de idade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Conta cada um que se unirá ao grupo que servirá na Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Esta é a responsabilidade e o trabalho deles em todo o serviço na Tenda do Encontro. Eles devem cuidar da estrutura do Tabernáculo, suas traves, suas varas e suas bases,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'juntamente com as varas do pátio ao redor do Tabernáculo, suas bases, seus pegadores, suas cordas, com todos os seus objetos. Lista os nomes dos artigos que eles devem carregar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Este é o serviço dos clãs dos descendentes de Merari, o que eles devem fazer na Tenda do Encontro, sob a direção de Itamar, filho de Arão, o sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Moisés, Arão, e os líderes da comunidade contaram os descendentes dos Coates, pelos clãs dos antepassados de suas famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Eles contaram aqueles que tinham entre trinta a cinquenta anos de idade. Eles contaram todos que se juntariam para servir na Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Foram contados dois mil, setecentos e cinquenta homens nos seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Moisés e Arão contaram todos os homens nos clãs e famílias dos coatitas que servem na Tenda do Encontro. Fazendo isso, eles obedeceram ao que Yahweh, por intermédio de Moisés, havia ordenado que fizessem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Os descendentes de Gérson foram contados nos seus clãs, pelos antepassados de suas famílias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'de trinta a cinquenta anos de idade, todos os que se uniriam para servir na Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Todos os homens, contados em suas tribos e nas famílias de seus antepassados, totalizaram dois mil, seiscentos e trinta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Moisés e Arão contaram os clãs dos descendentes de Gerson que iriam servir na Tenda do Encontro. Fazendo isso, eles obedeceram ao que Yahweh havia ordenado, por intermédio de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Os descendentes de Merari foram contados nos seus clãs pelos descendentes dos antepassados de cada família,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'de trinta a cinquenta anos de idade, todos que se uniriam para servir na Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Todos os homens, contados por clã e por seus antepassados familiares, totalizaram três mil e duzentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Moisés e Arão contaram todos os homens, os descendentes de Merari. Fazendo isso, eles obedeceram ao que Yahweh havia ordenado, por intermédio de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Assim, Moisés e Arão, e os líderes de Israel, contaram todos os levitas nos seus clãs e pela família de seus antepassados');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'de trinta a cinquenta anos. Eles contaram todos os que trabalhariam no Tabernáculo, e que iriam carregar e cuidar dos itens da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Eles contaram oito mil, quinhentos e oitenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Conforme Yahweh ordenara, Moisés contou cada homem, mantendo a contagem de acordo com o tipo de trabalho que cada um fazia. Ele contou cada homem conforme o tipo de responsabilidade que ele iria ter. E, fazendo isto, eles obedeceram ao que Yahweh havia ordenado, por intermédio de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Yahweh falou com Moisés. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, '\"Ordena ao povo de Israel para pôr para fora do acampamento todos com doenças infecciosas de pele, todo aquele que tiver uma ferida com pus e todos o que estiverem impuros por haver tocado em um cadáver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Tanto homens quanto mulheres serão retirados do acampamento. Eles não devem contaminar o acampamento, no qual habito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Assim fez o povo de Israel. Eles os tiraram do acampamento, como Yahweh havia ordenado a Moisés. O povo de Israel obedeceu a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Novamente, Yahweh falou com Moisés. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, '\"Fala ao povo de Israel. Quando um homem ou mulher cometer qualquer pecado com outra pessoa, e não for fiel a Mim, essa pessoa será culpada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Ela confessará os pecados que cometeu e pagará o preço completo por sua culpa, acrescentando um quinto a mais. Ela pagará à pessoa contra quem tiver pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Mas, se a pessoa culpada não tiver nenhum parente próximo para receber o pagamento, ela terá que pagar o preço de sua culpa para Mim por meio de um sacerdote, além do carneiro da expiação por ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Toda oferta apresentada para um sacerdote, de todas as coisas santas e as coisas separadas para Mim pelo povo de Israel, pertencerão àquele sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'As ofertas de todas as pessoas pertencerão ao sacerdote. Tudo o que qualquer homem der ao sacerdote pertencerá àquele sacerdote\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Novamente, Yahweh falou a Moisés. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, '\"Fala ao povo de Israel. Dize-lhes: \'Se a esposa de um homem se desviar, pecando contra seu marido, e');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'se outro homem tiver dormido com ela, neste caso, ela está contaminada. Ainda que seu marido não veja ou saiba do ocorrido e isso ficar escondido e não tiver ninguém para testemunhar contra ela,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'contudo, se o marido pode sentir ciúmes e ficar desconfiado que sua esposa está contaminada. Porém, o sentimento de ciúmes pode falsamente vir sobre um homem quando sua mulher não estiver contaminada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Nesses casos, o homem deve trazer sua esposa ao sacerdote. O marido trará como oferta a décima parte de um efa de farinha de cevada. Ele não derramará azeite ou incenso sobre isso porque é uma oferta de cereais por ciúmes, como oferta de suspeita de pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'O sacerdote deverá aproximá-la e colocá-la diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'O sacerdote trará uma jarra de água sagrada e tirar pó do chão do tabernáculo e colocará o pó dentro da água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'O sacerdote apresentará a mulher diante de Yahweh. A mulher descobrirá sua cabeça e desamarrará seu cabelo. O sacerdote colocará o grão em suas mãos como oferta memorial. Este é o grão oferecido por ciúmes. O sacerdote segurará, em suas mãos, a água amarga, que pode trazer uma maldição a ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'O sacerdote ordenará que a mulher prometa um voto e falará para a mulher: \'Se nenhum outro homem tiver se relacionado sexualmente contigo e se tu não tiveres te perdido e cometido impureza, então, estarás livre da água amarga que pode levar-te à maldição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mas, se tu, uma mulher estando sob autoridade do seu marido, te desviaste, se tiveres te contaminado e, se outro homem tiver dormido contigo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, '(o sacerdote ordenará que a mulher prometa um voto que poderá trazer uma maldição e continuará falando com ela)\' então, Yahweh te colocará uma maldição que será mostrada para seu povo. E acontecerá que Yahweh fará definhar a tua coxa e inchará o teu ventre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Essa água que traz a maldição entrará em teu estômago, inchará teu abdome e enfraquecerá tua coxa\'. A mulher há de responder: \'Sim, que isso aconteça se eu tiver culpa\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'O sacerdote escreverá essas maldições em um rolo e, então, terá que lavar as palavras de maldições na água amarga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'O sacerdote fará com que a mulher beba a água amarga que traz maldição. A água que traz maldição entrará nela e se tornará amarga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'O sacerdote também pegará um punhado de oferta de grãos de ciúmes das mãos dela. Ele segurará a oferta de grãos diante de Yahweh e trazê-la até o altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'O sacerdote pegará um punhado da oferta de grãos, uma oferta representativa, e irá queimá-la no altar. Então, ele dará a mulher a água amarga para beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Quando ele der-lhe a água para beber, se estiver contaminada porque cometeu um pecado contra seu marido, então, a água que traz maldição entrará nela e se tornará amarga. Seu ventre se inchará e sua coxa definhará. A mulher será amaldiçoada entre seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Mas, se a mulher não estiver contaminada e estiver limpa, então, será liberada e será capaz de gerar filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Esta é a lei do ciúmes. Esta é a lei para uma mulher que trair seu marido e estiver contaminada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Esta é a lei para o homem com um sentimento de ciúmes quando ele estiver com ciúmes de sua esposa. Ele trará a mulher diante de Yahweh e o sacerdote fará com ela tudo o que esta lei dos ciúmes descreve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'O homem será eximido de culpa por trazer sua esposa para o sacerdote. A mulher terá que levar qualquer culpa que possa ter\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Yahweh falou para Moisés. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, '\"Fala ao povo de Israel, dizendo: \'Quando um homem ou uma mulher se consagrarem para Yahweh com um voto especial de nazireu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'precisará manter-se longe de vinho e de bebida forte: não beberá vinagre feito de vinho ou de bebida forte. Não beberá nenhum tipo de suco de uva, nem comerá uvas frescas ou secas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Durante todos os dias em que estiver separado para Mim, não comerá nada que seja feito de uvas, incluindo tudo que é feito das sementes e das cascas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Por todo o tempo do seu voto de separação, não usará lâmina em sua cabeça até que se cumpram os seus dias de separação para Yahweh. Ele se dedicará a Yahweh, e deixará o cabelo crescer em sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Durante todo o tempo em que estiver separado para Yahweh, não se aproximará de nenhum cadáver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Ele não se tornará impuro, mesmo que por seu pai, mãe, irmão ou irmã, se eles morrerem. Isso é porque ele está separado para Deus, como todos podem ver, por causa de seu cabelo longo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Durante todo o tempo de sua separação, ele será santo, reservado para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Se alguém morrer de repente ao seu lado e profanar sua consagração, então ele raspará sua cabeça no dia de sua purificação - no sétimo dia, ele raspará sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'No oitavo dia, ele trará duas rolinhas ou dois pombinhos ao sacerdote, na entrada da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'O sacerdote oferecerá um pássaro como oferta pelo pecado e o outro como oferta queimada. Esses farão expiação por ele, porque pecou por estar perto do corpo morto. Ele se consagrará novamente naquele mesmo dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Ele se dedicará a Yahweh pelo tempo de sua consagração. Trará um cordeiro macho de um ano como oferta de culpa. Os dias antes dele se contaminar não serão contados, porque sua consagração foi profanada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Esta é a lei do nazireu, para quando se completar o tempo de sua separação. Ele será trazido à entrada da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Apresentará sua oferta para Yahweh. Oferecerá como oferta queimada um cordeiro de um ano sem defeito. Trará como oferta pelo pecado uma ovelha de um ano sem defeito. Trará um carneiro que não tenha defeito como oferta pacífica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Trará também uma cesta de pães feitos sem fermento, bolos da melhor farinha misturada com azeite, pães asmos untados com azeite, junto com sua oferta de cereais e libação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'O sacerdote apresentará tudo diante de Yahweh. Ele oferecerá a oferta pelo pecado e a oferta queimada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Com a cesta de pães sem fermento, ele oferecerá o carneiro como sacrificio, como oferta pacífica para Yahweh. O sacerdote apresentará também a oferta de cereais e de libação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'O nazireu raspará a sua cabeça indicando sua separação para Deus, na entrada da Tenda do Encontro. Ele pegará o seu cabelo e o colocará no fogo que está debaixo do sacrificio da oferta pacífica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'O sacerdote pegará a espádua cozida do carneiro, um bolo sem fermento do cesto e um pão asmo. Ele os colocará nas mãos do nazireu, depois de haver raspado sua cabeça indicando separação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'O sacerdote os moverá, apresentando-os como oferta diante de Yahweh; isto é comida sagrada, reservada para o sacerdote, junto com o peito e a coxa que foram apresentados. Depois disso, o nazireu poderá beber vinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Esta é a lei do nazireu, que faz o voto de oferta por sua separação para Yahweh. Além de qualquer outra coisa que ele possa dar, ele deve manter as obrigações do voto que fez, para manter sua promessa indicada pela lei do nazireu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'De novo Yahweh falou com Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '\"Fala com Arão e seus filhos. Diz: \'Vós abençoareis o povo de Israel dessa forma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Que Yahweh vos abençoe e vos guarde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Que Yahweh faça a Sua face brilhar sobre vós e seja gracioso convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Que Yahweh vos olhe com favor e vos dê a paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'É dessa forma que eles devem dar o meu nome ao povo de Israel. Então, Eu os abençoarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'No dia em que Moisés finalizou o Tabernáculo, ele o ungiu e dedicou-o a Yahweh, junto com toda sua mobília. Ele fez o mesmo com o altar e todos os seus utensílios. Ele os ungiu e dedicou-os a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Naquele dia, os líderes de Israel, os cabeças das famílias dos antepassados, ofereceram sacrifícios. Esses homens estavam liderando as tribos. Foram eles que supervisionaram a contagem dos homens no censo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Eles trouxeram suas ofertas diante de Yahweh. Eles trouxeram seis carros cobertos e doze bois. Eles trouxeram um carro para cada dois líderes, e cada líder trouxe um boi. Eles apresentaram essas coisas em frente do Tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Então Yahweh falou a Moisés. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '\"Aceite as ofertas deles e use as ofertas para o trabalho na Tenda do Encontro. Dê as ofertas para os levitas, para cada um segundo seu serviço\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Moisés pegou os carros e os bois, e os deu para os levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Ele deu dois carros e quatro bois para os descendentes de Gérson, por conta daquilo que o trabalho deles necessitava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Ele deu quatro carros e oito bois para os descendentes de Merari, aos cuidados de Itamar, filho de Arão, o sacerdote. Ele fez isso por conta daquilo que o trabalho deles requeria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Mas, ele não deu nenhuma dessas coisas aos descendentes de Coate, porque deles seria o trabalho relacionado as coisas pertencentes a Yahweh, as quais carregariam em seus próprios ombros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Os líderes ofereceram seus bens para a dedicação do altar, no dia que Moisés ungiu o altar. Os líderes ofereceram seus sacrifícios em frente ao altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Yahweh disse a Moisés: \"Cada líder, em seu próprio dia, deve oferecer seu sacrifício para a dedicação do altar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'No primeiro dia, Nasom, filho de Aminadabe, da tribo de Judá, ofereceu seu sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'O sacrifício dele foi uma bandeja de prata, pesando cento e trinta siclos e uma bacia de prata pesando setenta siclos, segundo o peso padrão do siclo do Santuário. Ambos objetos estavam cheios de flor de farinha amassada, misturada com azeite para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Ele também deu um prato de ouro pesando dez siclos, cheio de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Ele deu como oferta queimada um novilho, um carneiro, e um cordeiro macho de um ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Ele deu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'Ele deu dois bois, cinco carneiros, cinco bodes, e cinco cordeiros machos de um ano, como oferta pacífica. Esse foi o sacrifício de Nasom, filho de Aminadabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'No segundo dia, Natanael filho de Zuar, líder de Issacar, ofereceu seu sacrifício');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Ele ofereceu como seu sacrifício uma bandeja de prata pesando cento e trinta ciclos e uma bacia de prata de setenta siclos, pelo peso padrão do siclo do lugar santo. Ambos objetos estavam cheios de flor de farinha amassada, misturada com azeite para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Ele também ofereceu um prato de ouro, pesando dez siclos, cheio de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Ele ofereceu como oferta queimada um novilho, um carneiro, e um cordeiro macho de um ano de idade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Ele ofereceu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'Ele ofereceu dois bois, cinco carneiros, cinco bodes e cinco cordeiros machos de um ano, como sacrifício para a oferta pacífica. Esse foi o sacrifício de Natanael, filho de Zoar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'No terceiro dia, Eliabe, filho de Helom, líder dos descendentes de Zebulom, ofereceu seu sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Seu sacrifício foi uma bandeja de prata, pesando cento e trinta siclos e uma bacia de prata, pesando setenta siclos, conforme o peso padrão do siclo do santuário. Ambos objetos estavam cheios de flor de farinha amassada, misturada com azeite para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Ele também ofereceu um prato de ouro, pesando dez siclos, cheio de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Ele ofereceu como oferta queimada um novilho, um carneiro e um cordeiro macho de um ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Ele ofereceu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'Ele ofereceu dois bois, cinco carneiros, cinco bodes e cinco cordeiros machos de um ano, como sacrifício para a oferta pacífica. Esse foi o sacrifício de Eliabe, filho de Helom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'No quarto dia, Elizur, filho de Sedeur, líder dos descendentes de Rúben, ofereceu seu sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Seu sacrifício foi uma bandeja de prata, pesando cento e trinta siclos e uma bacia de prata, pesando setenta siclos, conforme o peso padrão do siclo do santuário. Ambos objetos estavam cheios de flor de farinha amassada com óleo para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'Ele também deu uma prato de ouro pesando dez siclos, cheia de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'Ele ofereceu como oferta queimada um novilho, um carneiro e um cordeiro macho de um ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'Ele deu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'Ele deu dois bois, cinco carneiros, cinco bodes, e cinco cordeiros machos de um ano, como sacrifício para a oferta pacífica. Esse foi o sacrifício de Elizur, filho de Sedeur.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'No quinto dia, Selumiel, filho de Zurisadai, líder dos descendentes de Simeão, ofereceu seu sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'O sacrifício dele foi uma bandeja de prata, pesando cento e trinta siclos e uma bacia de prata, pesando setenta siclos, segundo o peso padrão do siclo do santuário. Ambos os objetos estavam cheios de flor de farinha misturada com óleo para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'Ele também deu um prato de ouro pesando, dez siclos, cheio de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'Ele deu como oferta queimada um novilho, um carneiro e um cordeiro macho de um ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'Ele deu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'Ele deu dois bois, cinco carneiros, cinco bodes, e cinco cordeiros machos de um ano, como o sacrifício para a oferta pacífica. Esse foi o sacrifício de Selumiel, filho de Zurisadai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'No sexto dia, Eliasafe, filho de Deuel, líder dos descendentes de Gade, ofereceu seu sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'O sacrifício dele foi uma bandeja de prata, pesando cento e trinta siclos e uma bacia de prata, pesando setenta siclos, segundo o peso padrão do siclo do santuário. Ambos os objetos estavam cheios de flor de farinha misturada com óleo para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'Ele também deu um prato de ouro, pesando dez siclos, cheio de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'Ele ofereceu como oferta queimada um novilho, um carneiro e um cordeiro de um ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, 'Ele deu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'Ele deu dois bois, cinco carneiros, cinco bodes, e cinco cordeiros machos de um ano, como sacrifício para a oferta pacífica. Esse foi o sacrifício de Eliasafe, filho de Deuel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'No sétimo dia, Elisama, filho de Amiúde, líder dos descendentes de Efraim, ofereceu seu sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Seu sacrifício foi uma bandeja de prata, pesando cento e trinta siclos e uma bacia de prata, pesando setenta siclos, segundo o peso padrão do siclo do santuário. Ambos os objetos estavam cheio de flor de farinha misturada com óleo para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'Ele também deu um prato de ouro, pesando dez siclos, cheio de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'Ele deu como oferta queimada um novilho, um carneiro e um cordeiro macho de um ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'Ele deu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'Ele deu dois bois, cinco carneiros, cinco bodes, e cinco cordeiros machos de um ano, como sacrifício para a oferta pacífica. Esse foi o sacrifício de Elisama, filho de Amiúde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'No oitavo dia, Gamaliel, filho de Pedazur, líder dos descendentes de Manassés, ofereceu seu sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Seu sacrifício foi uma bandeja de prata, pesando cento e trinta siclos e uma bacia de prata pesando setenta siclos, segundo o peso padrão do siclo do santuário. Ambos os objetos estavam cheios de flor de farinha misturada com óleo para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'Ele também deu um prato de ouro, pesando dez siclos, cheio de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'Ele deu como oferta queimada um novilho, um carneiro e um cordeiro macho de um ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'Ele deu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'Ele deu dois bois, cinco carneiros, cinco bodes, e cinco cordeiros machos de um ano, como sacrifício para a oferta pacífica. Esse foi o sacrifício de Gamaliel, filho de Pedazur.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'No nono dia, Abidã, filho de Gideoni, líder dos descendentes de Benajmim, ofereceu seu sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Seu sacrifício foi uma bandeja de prata, pesando cento e trinta siclos e uma bacia de prata, pesando setenta siclos, segundo o peso padrão do siclo do santuário. Ambos os objetos estavam cheio de flor de farinha misturada com óleo para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'Ele também deu um prato de ouro, pesando dez siclos, cheio de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'Ele deu como oferta queimada um novilho, um carneiro e um cordeiro macho de um ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'Ele deu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'Ele deu dois bois, cinco carneiros, cinco bodes, e cinco cordeiros machos de um ano, como sacrifício para a oferta pacífica. Esse foi o sacrifício de Abidã, filho de Gideoni.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'No décimo dia, Aiezer, filho de Amisadai, líder dos descendentes de Dã, ofereceu seu sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Seu sacrifício foi uma bandeja de prata, pesando cento e trinta siclos e uma bacia de prata, pesando setenta siclos, segundo o peso padrão do siclo do santuário. Ambos os objetos estavam cheios de flor de farinha misturada com óleo para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'Ele também deu um prato de ouro, pesando dez siclos, cheio de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'Ele ofereceu como oferta queimada um novilho, um carneiro e um cordeiro macho de um ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'Ele deu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'Ele deu dois bois, cinco carneiros, cinco bodes, e cinco cordeiros machos de um ano, como sacrifício para a oferta pacífica. Esse foi o sacrifício de Aiezer, filho de Amisadai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'No décimo primeiro dia, Pagiel, filho de Ocrã, líder dos descendentes de Aser, ofereceu seu sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Seu sacrifício foi uma bandeja de prata, pesando cento e trinta siclos e uma bacia de prata, pesando setenta siclos, segundo o peso padrão do siclo do Santuário. Ambos os objetos estavam cheios de flor de farinha misturada com óleo para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'Ele também deu um prato de ouro pesando dez siclos, cheio de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Ele deu como oferta queimada um novilho, um carneiro e um cordeiro de um ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Ele deu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'Ele deu dois bois, cinco carneiros, cinco bodes e cinco cordeiros machos de um ano, como sacrifício para a oferta de paz. Esse foi o sacrifício de Pagiel, filho de Ocrã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'No décimo segundo dia, Airá, filho de Enã, líder dos descendentes de Naftali, ofereceu seu sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Seu sacrifício foi uma bandeja de prata, pesando cento e trinta siclos e uma bacia de prata, pesando setenta siclos, segundo o peso padrão do siclo do santuário. Ambos os objetos estavam cheios de flor de farinha misturada com óleo para a oferta de cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Ele também deu um prato de ouro, pesando dez siclos, cheio de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Ele ofereceu como oferta queimada um novilho, um carneiro e um cordeiro macho de um ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Ele deu um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'Ele deu dois bois, cinco carneiros, cinco bodes, e cinco cordeiros machos de um ano, como sacrifício para a oferta pacífica. Esse foi o sacrifício de Airá, filho de Enã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Os líderes de Israel dedicaram todas estas coisas no dia que Moisés ungiu o altar. Eles dedicaram doze bandejas de prata, doze bacias de pratas e doze pratos de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Cada bandeja de prata pesando cento e trinta siclos e cada bacia pesando setenta siclos. Todas as vasilhas de prata pesavam dois mil e quatrocentos siclos, segundo o peso padrão do siclo do santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Cada um dos doze pratos de ouro, cheios de incenso, pesavam dez siclos segundo o peso padrão do siclo do santuário. Todas os pratos de ouro pesavam cento e vinte siclos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Eles dedicaram como oferta queimada doze touros, doze carneiros, e doze cordeiros machos de um ano. Eles deram suas ofertas de grãos. Eles deram doze bodes como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'De todo seu rebanho, eles deram vinte e quatro touros, sessenta carneiros, sessenta bodes e sessenta cordeiros machos de um ano, como sacrifício para a oferta pacífica. Isso foi para a dedicação do altar, depois que este foi ungido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Quando Moisés entrou na Tenda do Encontro para falar com Yahweh, ele ouviu Sua voz falando com ele. Yahweh falou com ele de cima da tampa do propiciatório, da arca do testemunho, entre dois querubins. Ele falou com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Yahweh falou a Moisés. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, '\"Fala a Arão e dize-lhe: \'As sete lâmpadas devem iluminar em frente ao candelabro quando tu acendê-las\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Arão fez isso. Ele acendeu as lâmpadas no candelabro para iluminar em frente deste, como Yahweh tinha ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'O candelabro era feito de ouro batido desde a sua base até o seu topo, com copos batidos em forma de flores, como Yahweh mostrou a Moisés, assim Moisés fez o candelabro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Novamente, Yahweh falou a Moisés. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, '\"Toma os levitas dentre o povo de Israel e purifica-os.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Assim farás para purificá-los: Asperge a água da expiação neles. Faze-os rasparem todo o corpo, lavarem suas roupas, e dessa maneira ficarão purificados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Então faze-os pegar um novilho com sua oferta de grãos de flor de farinha amassada com azeite. Permite que peguem outro novilho para oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Apresentarás os levitas perante a Tenda do Encontro, e reunirás toda a comunidade do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Quando apresentares os levitas diante de Yahweh, o povo de Israel colocará as suas mãos sobre os levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Arão oferecerá os levitas diante de Yahweh, apresentando-os como oferta movida do povo de Israel para que sirvam Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Os levitas colocarão suas mãos sobre as cabeças dos novilhos. Tu sacrificarás um novilho para oferta pelo pecado e o outro novilho para holocausto para Mim, para expiação dos levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Apresenta os levitas diante de Arão e diante de seus filhos, e oferece-os como oferta movida para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Dessa maneira tu separarás os levitas dentre o povo de Israel. Os levitas pertencerão a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Depois disso, os levitas entrarão para servir na Tenda do Encontro. Tu os purificarás. Tu os oferecerás para Mim como oferta movida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Faz isso, pois eles são inteiramente Meus dentre o povo de Israel. Eles tomarão o lugar de cada menino que abre o ventre, o primogênito de toda a descendência de Israel. Eu tenho tomado os levitas para Mim mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Todos os primogênitos entre o povo de Israel são Meus, tanto de homens quanto de animais. No dia em que Eu tirei as vidas de todos os primogênitos na terra do Egito, Eu os consagrei para Mim mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Eu tomei os levitas dentre o povo de Israel em lugar de todo o primogênito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Concedi os levitas como presente para Arão e seus filhos. Eu os tomei, dentre o povo de Israel, para fazerem o trabalho do povo, na Tenda do Encontro. Eu os concedi para fazerem expiação pelo povo de Israel, para que nenhuma praga prejudique o povo de Israel, quando aproximarem-se do lugar santo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Assim Moisés, Arão, e toda comunidade do povo de Israel fizeram com os levitas. Eles fizeram tudo o que Yahweh ordenara a Moisés acerca dos levitas. Assim lhes fizeram o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Os levitas purificaram a si mesmos dos pecados lavando suas roupas, e Arão apresentou-os por oferta movida para Yahweh e fez expiação por eles, para que fossem purificados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Depois disso, os levitas entraram para fazer o serviço deles na Tenda do Encontro diante de Arão e de seus filhos. Assim era como Yahweh havia ordenado a Moisés sobre os levitas. Assim eles fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Yahweh falou novamente a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, '\"Tudo isso é para os levitas que tenham vinte cinco anos ou mais. Estarão juntos para servirem na Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Eles devem parar de servir dessa maneira com a idade de cinquenta anos. Nesta idade eles não devem servir mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Eles podem ajudar seus irmãos que continuam a trabalhar na Tenda do Encontro, mas não devem mais servir. Assim conduzirás os levitas em todos estes assuntos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Yahweh falou a Moisés no deserto de Sinai, no primeiro mês do segundo ano, depois que eles saíram da terra do Egito. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, '\"Deixa o povo de Israel celebrar a Páscoa no tempo determinado do ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'No décimo quarto dia deste mês, ao entardecer, vós celebrareis a Páscoa no tempo determinado do ano. Vós a guardareis, seguireis todos os estatutos e obedecereis a todos os decretos que estão relacionados a ela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Então, Moisés disse ao povo de Israel que eles deveriam celebrar a Festa da Páscoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Então, eles celebraram a Páscoa no primeiro mês, no décimo quarto dia do mês, ao entardecer, no deserto de Sinai. O povo de Israel obedeceu a tudo que Yahweh ordenou a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Havia certos homens que se tornaram impuros, por tocarem no cadáver de um homem. Eles não podiam celebrar a Páscoa naquele dia. Então, eles foram diante de Moisés e Aarão naquele mesmo dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Aqueles homens disseram a Moisés: \"nós estamos impuros devido ao cadáver de um homem. Por que tu nos impedes de oferecer o sacrifício para Yahweh no tempo determinado do ano entre o povo de Israel?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Moisés lhes disse: \"Esperai para que eu ouça o que Yahweh instruirá acerca de vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Yahweh falou a Moisés. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, '\"Fala ao povo de Israel. Diz: \'Se qualquer um de vós ou vossos descendentes estiverdes impuros, devido a um cadáver ou estiverdes em uma viagem longa, ainda podereis celebrar a Páscoa para Yahweh\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Eles guardarão a Páscoa, no segundo mês, no décimo quarto dia, ao entardecer. Eles comerão com pão sem fermento e ervas amargas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Eles não deixarão nenhuma sobra para a manhã seguinte ou quebrarão osso algum dos animais. Eles devem guardar todos as regras para a Páscoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Porém, qualquer pessoa que estiver pura e não estiver em viagem, mas que falhar em celebrar a Páscoa, essa pessoa será eliminada de seu povo; porque ele não ofereceu o sacrifício que Yahweh exige no tempo determinado do ano. Tal homem deve carregar seu pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Se um estrangeiro vive entre vós e celebra a Páscoa em honra a Yahweh, ele deve celebrá-la e fazer tudo que Ele ordena, guardando os estatutos da Páscoa, obedecendo às leis. Vós tereis a mesma lei para o estrangeiro e para todo aquele que é nativo da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'No dia em que o Tabernáculo foi levantado, a nuvem cobriu o Tabernáculo, isto é, a própria Tenda do Testemunho. Ao entardecer, a nuvem permanecia sobre o Tabernáculo e tinha aparência de fogo até pela manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Ela permanecia dessa forma. A nuvem cobria o Tabernáculo à noite, tinha a aparência de fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Sempre que a nuvem se movia sobre a Tenda, o povo de Israel retomava sua viagem. Sempre que a nuvem parava, o povo acampava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Ao comando de Yahweh, o povo de Israel viajava e, ao Seu comando, eles acampavam. Enquanto a nuvem parava sobre o Tabernáculo, eles ficavam em seu acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Quando a nuvem permanecia sobre o Tabernáculo por muitos dias, o povo de Israel obedecia às instruções de Yahweh e não viajava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Às vezes, a nuvem permanecia poucos dias sobre o Tabernáculo. Neste caso, eles obedeciam o comando de Yahweh — voltariam a acampar e viajar ao Seu comando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Às vezes, a nuvem estava presente no acampamento desde o entardecer até de manhã. Quando a nuvem se elevava pela manhã, eles viajavam. Se ela continuava por um dia e por uma noite, apenas quando a nuvem se elevava, eles seguiam viagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Se a nuvem ficasse sobre o Tabernáculo por dois dias, um mês ou um ano, pelo tempo que ela permanecesse lá, o povo de Israel ficava no acampamento e não viajava. Mas, sempre que a nuvem se movia, eles seguiam viagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Eles acampavam sob o comando de Yahweh e viajavam ao Seu comando. Eles obedeciam às ordens de Yahweh, entregues por meio de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Yahweh falou a Moisés. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, '\"Faze duas trombetas de prata. Martela a prata para fazê-las e usa as trombetas para convocar o ajuntamento da comunidade e para chamar a comunidade a mover seus acampamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Os sacerdotes tocarão as trombetas para juntar toda a comunidade diante de ti, à entrada da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Se os sacerdotes tocarem apenas uma trombeta, então os líderes, os cabeças dos clãs de Israel, devem reunir-se contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Quando tocardes um sinal alto, os acampamentos do lado leste devem partir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Quando tocardes um sinal alto pela segunda vez, os acampamentos do lado sul, devem partir. Eles devem tocar um sinal alto para suas jornadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Quando a comunidade se reunir, tocai a trombeta, mas não alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Os filhos de Arão, os sacerdotes, devem tocar a trombeta. Isto será sempre uma regra ao longo de todas as vossas gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Quando fordes guerrear na vossa terra contra um adversário que vos oprime, então soareis um alarme com as trombetas. Eu, Yahweh, vosso Deus, me lembrarei de vós e vos salvarei dos vossos inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Também, nos tempos de celebração, tanto os vossos festivais regulares, quanto o começo dos meses, soareis as trombetas em honra das vossas ofertas queimadas e sobre os sacrifícios das vossas ofertas de comunhão. Isto será como uma recordação vossa para Mim, vosso Deus. Eu sou Yahweh, vosso Deus.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'No segundo ano, no segundo mês, no vigésimo dia do mês, a nuvem foi levantada do Tabernáculo dos decretos da aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'O povo de Israel, então, partiu do deserto do Sinai em sua jornada. A nuvem parou no deserto de Parã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Eles fizeram sua primeira jornada, seguindo o comando de Yahweh dado através de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'O acampamento sob a bandeira dos descendentes de Judá saiu primeiro, movendo seus exércitos individuais. Nasom, filho de Aminadabe, conduzia o exército de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Netanel, filho de Zuar, conduzia o exército da tribo dos descendentes de Issacar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Eliabe, filho de Helom, conduzia o exército da tribo dos descendentes de Zebulom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Os descendentes de Gérson e de Merari, que cuidavam do Tabernáculo, desmontaram o Tabernáculo e partiram em sua jornada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Depois, os exércitos sob a bandeira do acampamento de Rúben, partiram em sua jornada. Elizur, filho de Sedeur, conduzia o exército de Rúben.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Selumiel, filho de Zurisadai, conduzia o exército da tribo dos descendentes de Simeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Eliasafe, filho de Deuel, conduzia o exército da tribo dos descendentes de Gade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Os coatitas partiram. Eles carregaram os utensílios do Santuário. Outros deviam montar o Tabernáculo, antes dos coatitas chegarem ao próximo acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Os exércitos sob a bandeira dos descendentes de Efraim, partiram depois. Elisama, filho de Amiúde, conduzia o exército de Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Gamaliel, filho de Pedazur, conduzia o exército da tribo dos descendentes de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Abidã, filho de Gideoni, conduzia o exército da tribo dos descendentes de Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Os exércitos que acampavam sob a bandeira dos descendentes de Dã partiram por último. Aiezer, filho de Amisadai, conduzia o exército de Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Pegiel, filho de Ocrã, conduzia o exército da tribo dos descendentes de Aser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Airá, filho de Enã, conduzia o exército da tribo dos descendentes de Naftali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Esse era o modo como os exércitos do povo de Israel, partiram em sua jornada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Moisés falou com Hobabe, filho de Reuel, o midianita. Reuel era o pai da esposa de Moisés. Moisés falou com Hobabe e disse: \"Nós estamos viajando para o lugar que Yahweh descreveu. Yahweh disse: \'Eu vos darei esse lugar\'. Vem conosco e nós te faremos bem. Yahweh prometeu fazer o bem a Israel.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Mas Hobabe disse a Moisés: \"Eu não vou convosco. Eu vou para minha própria terra e para meu próprio povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Então Moisés respondeu: \"Por favor, não nos deixe. Tu sabes como acampar no deserto. Tu cuidarás de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Se tu fores conosco, nós faremos a ti o mesmo bem que Yahweh fizer a nós.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Eles viajaram da montanha de Yahweh por três dias. A arca da aliança de Yahweh foi à frente deles por três dias, para encontrar um lugar para eles descansarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'A nuvem de Yahweh estava sobre eles, durante o dia enquanto eles viajavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Sempre que a arca partia, Moisés dizia: \"Levanta-Te, Yahweh. Dispersa os Teus inimigos. Faz correr de Ti aqueles que Te odeiam.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Sempre que a arca parava, Moisés dizia: \"Retorna, Yahweh, para as muitas dezenas de milhares de Israel.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'E aconteceu que o povo murmurava sobre seus problemas aos ouvidos de Yahweh. Yahweh ouviu o povo e ficou irado. Então fogo vindo de Yahweh incendiou no meio deles e consumiu alguns nas extremidades do acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'O povo clamou a Moisés, e Moisés orou a Yahweh, e o fogo cessou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Aquele lugar foi chamado Teberá, porque o fogo de Yahweh se acendeu no meio eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Alguns estrangeiros vieram com os descendentes de Israel. Eles queriam uma comida melhor. Então as pessoas de Israel começaram a prantear e dizer: \"Quem nos dará carne para comer?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Lembramos do peixe que comíamos de graça no Egito, os pepinos, os melões, os alhos-porós, as cebolas e o alho. Agora estamos fracos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Nós não vemos nada além desse maná para comer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'O maná era como a semente de coentro, tinha a cor da semente de coentro e a cor da resina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'As pessoas caminhavam em volta e o colhia. Ele era triturado em moinhos, amassado em um pilão, cozido em panelas, e dele faziam bolos. Tinha o gosto do azeite de oliva fresco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Quando o orvalho caía, à noite, no acampamento, o maná também caía.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Moisés ouviu as pessoas chorando com seus familiares, e todos os homens estavam na entrada de suas barracas. Yahweh ficou muito indignado. Aos olhos de Moisés, eles estavam errados em reclamar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Moisés disse a Yahweh: \"Por que Tu trataste tão mal o teu servo? Porque Tu não estais satisfeito comigo? Tu me fizeste carregar a carga dessas pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Por acaso eu dei à luz a todas estas pessoas? Eu as concebi para dizeres a mim: \'Carrega-as no peito como a ama carrega seu bebê?\' Devo eu carregá-las para a terra que Tu juraste dar a teus antepassados?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Onde posso encontrar carne para todas estas pessoas? Elas estão pranteando na minha frente e dizendo-me: \'Dá-nos carne para comer\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Eu não posso suportar todas estas pessoas sozinho. Isto é demais para mim!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Se Tu vais me tratar assim, mata-me agora, se Tu és bondoso para comigo, afasta o meu sofrimento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Disse Yahweh a Moisés: \"Traga-me setenta anciãos de Israel. Tenha certeza de que são anciãos e oficiais dessas pessoas. Traga-os para a Tenda do Encontro para ficarem lá com você.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Eu virei e falarei contigo lá. Eu tomarei um pouco do Espírito que está em ti e colocarei sobre eles. Eles carregarão a carga das pessoas contigo. E tu não terás que suportar mais sozinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Diga às pessoas: \"Consagrem-se a Yahweh amanhã. Certamente vós comereis carne, vós lamentastes e Yahweh vos ouvistes. Tu disseste: \'Quem nos dará carne para comer? No Egito íamos bem.\' Todavia, Yahweh vos dará carne, e vós ireis comê-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Vós não comereis carne por apenas um dia, nem dois dias, nem cinco dias, nem dez dias, ou vinte dias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'mas comereis carne por um mês inteiro, até sair pelas vossas narinas. Isto será um desgosto para vós, porque rejeitastes Yahweh, que está no meio de vós, lamentando diante Dele dizendo: \'Por que saimos do Egito?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Então Moisés disse: \"Eu estou com seiscentas mil pessoas, e tu disseste: \'Eu os alimentarei com carne o mês inteiro\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Matarei eu os rebanhos para os satisfazer? Pescarei eu todos os peixes do oceano para os satisfazer?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Yahweh disse a Moisés: \"Por acaso a minha mão é curta? Agora tu verás se a minha palavra é verdade ou não\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Moisés saiu e contou as palavras de Yahweh às pessoas. Ele reuniu setenta dos anciãos do povo e os posicionou em volta da Tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Yahweh desceu em uma nuvem e falou a Moisés. Yahweh tomou parte do Espírito que estava em Moisés e o colocou sobre os setenta anciãos. Quando o Espírito repousou sobre eles, profetizaram, mas somente naquela ocasião e nunca mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Dois homens permanceram no acampamento. Eram Eldade e Medade. O Espírito também repousou sobre eles. Seus nomes estavam escritos na lista, mas eles não foram para fora da Tenda. Mesmo assim, profetizaram dentro do acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Um jovem no acampamento correu e contou a Moisés: \"Eldade e Medade estão profetizando no acampamento.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Josué, filho de Num, assistente de Moisés, um de seus escolhidos, falou a Moisés: \"Meu mestre Moisés, impeça-os\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Moisés disse-lhe: \"Tu estais com ciúmes por minha causa? Eu gostaria que todo o povo de Yahweh fosse profeta e que Ele colocasse Seu Espírito em todos eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Então, Moisés e os anciãos de Israel voltaram para o acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Então, veio um vento de Yahweh e trouxe codornas do mar. Elas caíram perto do acampamento, a um dia de jornada de um lado, e a um dia de jornada do outro lado. As cordornas cercaram o acampamento sobre dois côvados acima do chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'As pessoas estavam ocupadas reunindo as cordornas durante o dia todo, à noite, e no dia seguinte. Ninguém recolheu menos que dez ômeres de codornas. Eles as estenderam pelo acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Enquanto a carne estava entre seus dentes e estavam ainda mastigando, Yahweh enfureceu-se contra eles. Ele os atacou com uma grave doença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Esse lugar foi chamado de Quibrote-Taavá, porque eles enterraram o povo que ansiava por carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'As pessoas viajaram de Quibrote-Taavá para Hazerote, onde ficaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Miriã e Arão falaram contra Moisés, por causa de mulher etíope com quem ele se casou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'E disseram: \"Yahweh falou somente com Moisés? Ele não falou conosco também?\". Então, Yahweh ouviu o que disseram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Moisés era um homem humilde, o mais humilde de toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Imediatamente, Yahweh falou a Moisés, Arão e Miriã: \"Saí os três para a Tenda do Encontro\". Então, os três saíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Depois, Yahweh desceu em uma coluna de nuvem. Colocando-Se na entrada da Tenda, chamou Arão e Miriã e ambos vieram à frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Yahweh disse: \"Agora, ouvi as Minhas palavras. Quando um profeta Meu estiver entre vós, Eu revelarei a Mim mesmo a ele em visões e falarei com ele em sonhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Meu servo Moisés não é como esses. Ele é fiel a toda a Minha casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Eu falo diretamente com Moisés, não por visões ou enigmas. Ele vê a Minha forma. Então, por que não temestes falar contra Meu servo, contra Moisés?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'A ira de Yahweh se acendeu contra eles e, então, Ele os deixou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'A nuvem deixou a Tenda, e, subitamente, Miriã ficou com lepra — branca como a neve. Quando Arão se virou para Miriã, viu que ela estava com lepra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Arão disse a Moisés: \"Ah, meu mestre, rogo-te, não nos imputes este pecado. Nós falamos tolices e pecamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Por favor, não a deixes parecida com um recém-nascido morto, cuja carne está consumida pela metade quando sai do ventre de sua mãe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Então, Moisés clamou a Yahweh. Disse ele: \"Por favor, Deus, cura Miriã, por favor!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Yahweh disse a Moisés: \"Se o seu pai cuspisse na face dela, ela seria desonrada por sete dias. Deixa sua irmã fora do acampamento por sete dias. Depois, traz Miriã de volta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Então, Miriã foi retirada do acampamento por sete dias. O povo não partiu até que ela retornou ao acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Depois disso, o povo seguiu sua jornada para Hazerote e acampou no deserto de Parã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Então, Yahweh disse a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, '\"Envia alguns homens para espiar a terra de Canaã, que Eu dei para o povo de Israel. Envia um homem de cada tribo de seus antepassados. Cada homem deve ser um líder entre eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Moisés enviou-lhes do deserto de Parã, em obediência à ordem de Yahweh. Todos eles eram líderes entre o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Estes eram seus nomes: da tribo de Rúben, Samua, filho de Zacur;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Da tribo de Simeão, Safate, filho de Hori;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Da tribo de Judá, Calebe, filho de Jefoné;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'da tribo de Issacar, Igal, filho de José;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'da tribo de Efraim, Oseias, filho de Num.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Da tribo de Benjamim, Palti, filho de Rafu;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'da tribo de Zebulom, Gadiel, filho de Sodi;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'dos descendentes de José, da tribo de Manassés, Gadi, filho de Susi;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'da tribo de Dã, Amiel, filho de Gemali;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Da tribo de Aser, Setur, filho de Micael;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'da tribo de Naftali, Nabi, filho de Vofsi;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'da tribo de Gade, Geuel, filho de Maqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Esses eram os nomes dos homens que Moisés enviou para espiar a terra. Moisés chamou Oseias, filho de Num, pelo nome de Josué.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Moisés os enviou para espiar a terra de Canaã. Ele lhes disse: \"Aproximai-vos pelo Neguebe e subi até as montanhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Examinai como é a terra. Observai o povo que nela habita, se é forte ou fraco, e se são poucos ou muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'Vede como é a terra em que eles vivem. Ela é boa ou má? Como são as cidades ali? São como acampamentos ou são cidades fortificadas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Vede como é a terra, se é boa para o plantio ou não, e se há árvores nela ou não. Sede corajosos e trazei amostras do que a terra produz\". Aquele tempo era a estação da colheita das primeiras uvas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Então, os homens subiram e examinaram a terra desde o deserto de Zim até Reobe, perto de Lebo-Hamate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Eles subiram de Neguebe e chegaram até Hebrom. Aimã, Sesai, e Talmai, clãs descendentes de Anaque, habitavam ali. Hebrom havia sido construída sete anos antes de Zoã, no Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Quando alcançaram o vale de Escol, cortaram um ramo de videira com um cacho de uvas. Eles o carregaram numa vara entre dois homens do grupo. Também trouxeram romãs e figos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Aquele lugar foi chamado Vale de Escol, por causa do cacho de uvas que o povo de Israel cortou ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Após quarenta dias, eles retornaram de espiar a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Eles retornaram a Moisés, Arão, e a toda a comunidade do povo de Israel, que estava no deserto de Parã, em Cades. Relataram a eles e a toda a comunidade, e mostraram-lhes os frutos da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Eles contaram a Moisés: \"Nós chegamos à terra que tu nos enviaste. Ela certamente mana leite e mel. Aqui estão alguns de seus frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Porém, os povos que nela residem são poderosos. As cidades são fortificadas e muito grandes. Nós também vimos ali os descendentes de Anaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Os amalequitas vivem no Neguebe. Os heteus, os jebuseus, e amorreus residem nas montanhas. Os cananeus vivem próximo ao mar e às margens do rio Jordão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Então, Calebe fez calar o povo que estava reunido diante de Moisés. Ele disse: \"Subamos e tomemos posse da terra, pois certamente somos capazes de conquistá-la\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Mas os outros homens que haviam ido com ele disseram: \"Nós não somos capazes de atacar aquele povo, pois é muito mais forte que nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Então, eles disseminaram entre o povo de Israel um relato de desânimo sobre a terra que haviam espiado. Eles disseram: \"A terra que espiamos é uma terra que devora seus próprios habitantes. E todos os que vimos lá são de grande estatura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Ali vimos gigantes, descendentes de Anaque, povo que descende de gigantes. Ao nosso ver, éramos como gafanhotos em comparação a eles, e isso é o que também éramos à vista deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Naquela noite, toda a comunidade chorou em alta voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Todo o povo de Israel criticou Moisés e Arão. Toda a comunidade, então, disse: \"Seria melhor se tivéssemos morrido na terra do Egito ou aqui no deserto!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Por que Yahweh nos trouxe a esta terra para morrermos pela espada? Nossas esposas e nossos pequeninos se tornarão vítimas. Não seria melhor voltarmos para o Egito?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Disseram uns aos outros: \"Vamos escolher outro líder e retornar ao Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Então, Moisés e Arão se curvaram diante da assembleia da comunidade do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Josué, filho de Num, e Calebe, filho de Jefoné, que foram alguns daqueles mandados para examinar a terra, rasgaram suas vestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'E falaram a toda comunidade do povo de Israel, dizendo: \"A terra pela qual passamos e examinamos é muito boa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Se Yahweh se agradar de nós, Ele nos levará à terra e a nós entregará; da terra, flui leite e mel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Mas não vos rebeleis contra Yahweh e não tenhais medo do povo da terra. Nós os consumiremos facilmente, como se fossem comida. A proteção deles será removida, porque Yahweh está conosco. Não tenhais medo deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Mas toda a comunidade ameaçou a apedrejá-los até a morte. Então, a glória de Yahweh apareceu na Tenda do Encontro a todo o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Yahweh disse a Moisés: \"Por quanto tempo esse povo Me desprezará? Por quanto tempo ainda desconfiarão de Mim, a despeito de todos os sinais do Meu poder que Eu já lhes mostrei?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Eu os atacarei com pragas, os deserdarei e farei de tua família uma nação que será superior e mais poderosa que a deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Moisés disse a Yahweh: \"Se Tu fizeres isso, os egípcios ouvirão a respeito, porque Tu resgatastes este povo da mão deles, pelo Teu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Eles contarão isso aos moradores desta terra. Tais moradores têm ouvido que Tu, Yahweh, estás presente com este povo, porque Tu és visto face a face. Tua nuvem permanece sobre nosso povo e vais diante deles numa coluna de nuvem durante o dia e em uma coluna de fogo durante a noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Agora, se matares este povo como a uma só pessoa, as nações que ouviram a Tua fama comentarão e dirão:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, '\'porque Yahweh não pôde levar Seu povo à terra que prometera, Ele os matou no deserto\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Agora, imploro a Ti, usa Teu grande poder. Pois Tu disseste:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, '\'Yahweh é tardio em irar-se e abundante em misericórdia. Ele perdoa iniquidades e trangressões. De maneira nenhuma, Ele limpará a culpa quando Ele trouxer a punição do pecado dos antepassados sobre seus descendentes, até a terceira e quarta geração\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Perdoa, eu Te imploro, o pecado deste povo por causa da grandeza da Tua misericórdia, assim como Tu sempre perdoaste este povo, desde o tempo em que estiveram no Egito até agora\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Yahweh disse: \"Tenho os perdoado, cumprindo, assim, o teu pedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Mas, tão certo quanto Eu vivo, bem como toda a terra será cheia da Minha glória,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'todo esse povo que viu Minha glória e os sinais de poder que fiz no Egito e no deserto, eles ainda Me tentaram nestas dez vezes e não ouviram Minha voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Eu digo que certamente não verão a terra sobre a qual fiz uma promessa a seus antepassados. Nenhum deles que Me odiou verá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'exceto Meu servo Calebe, porque ele teve um outro espírito. Ele Me tem seguido inteiramente; Eu o levarei para terra que ele foi examinar. Seus descendentes a possuirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, '(Ora, os amalequitas e os cananeus vivem no vale.) Amanhã, voltai e ide para o deserto pelo caminho do Mar Vermelho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Yahweh falou a Moisés e Arão, dizendo-lhes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, '\"Por quanto tempo devo tolerar essa comunidade má que Me critica? Eu tenho ouvido as reclamações do povo de Israel contra Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Dize-lhes: \'Como Eu vivo\', diz Yahweh, \'como tendes dito aos Meus ouvidos, farei isto para vós:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Vossos corpos cairão mortos neste deserto, todos vós que reclamastes contra Mim, vós, que foram contados no censo, todo o povo de vinte anos para cima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Vós certamente não entrareis na terra em que Eu prometi que fariam suas casas, exceto Calebe, filho de Jefoné e Josué, filho de Num.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Mas vossos pequeninos aos quais dissestes que seriam vítimas, Eu os levarei à terra. Eles experimentarão da terra que tendes rejeitado!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Enquanto a vós, vossos corpos cairão neste deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Vossos filhos serão andarilhos no deserto por quarenta anos. Eles devem aguentar as consequências de vossos atos de rebelião até que o deserto mate seus corpos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Assim como o número de dias em que examinaram a terra — quarenta dias —, semelhantemente devei arcar com as consequências de vossos pecados por quarenta anos, um ano para cada dia e vós devei saber como é ser Meu inimigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Eu, Yahweh, tenho dito. Eu certamente farei isto a toda esta comunidade má que tem se juntado contra Mim. Eles serão completamente consumidos e aqui morrerão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Então, os homens que Moisés havia mandado olhar a terra morreram pela praga diante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Estes foram os homens que haviam retornado e trazido notícias ruins sobre a terra. Isto fez com que toda comunidade reclamasse contra Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Daqueles homens que foram olhar a terra, somente Josué, filho de Num e Calebe, filho de Jefoné permaneceu vivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Quando Moisés informou estas palavras ao povo de Israel, eles lamentaram profundamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Eles levantaram cedo de manhã e foram ao topo da montanha e disseram: \"Olha, nós estamos aqui, e iremos até o lugar que Yahweh prometeu, pois nós pecamos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Porém, Moisés disse: \"Por que agora estais violando o comando de Yahweh? Vós não tereis sucesso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Não vades, porque Yahweh não está convosco para previnir que sejais derrotados pelos vossos inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Os amalequitas e cananeus estão lá e vós morrereis pela espada porque vós tendes deixado de seguir a Yahweh. Então, Ele não estará no meio de vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Mas eles ousaram subir a região montanhosa; porém, nem Moisés, nem a Arca da Aliança de Yahweh deixaram o acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Então, os amalequitas desceram e também os cananeus que viviam naquelas montanhas. Eles atacaram os Israelitas e os derrotaram até Hormá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Então Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, '\"Fala com o povo de Israel e dize-lhes: \'Quando entrardes na terra onde habitareis, a qual Yahweh vos dará,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'preparareis uma oferta como aroma agradável a Ele: oferta queimada, ou um holocausto, ou sacrifício para cumprir um voto, ou uma oferta voluntária, ou uma oferta em alguma de vossas festas, e serão com vosso gado ou vosso rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Quando apresentardes uma oferta queimada, oferecei a Yahweh uma oferta de cereais de um décimo de um efa de flor de farinha misturada com um quarto de um him de azeite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Oferecei também juntamente com a oferta queimada ou com o sacrifício, um quarto de um him de vinho como oferta de bebida para cada cordeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Quando oferecerdes um carneiro, preparareis uma oferta de cereais de dois décimos de um efa de excelente farinha misturada com um terço de um him de azeite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Para a oferta de bebida, oferecei um terço de um him de vinho, como aroma agradável a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Quando preparardes um novilho como holocausto ou como um sacrifício para cumprir um voto, ou como uma oferta pacífica a Yahweh,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'então oferecei com o novilho, uma oferta de cereais de três décimos de um efa de flor de farinha misturada com a metade de um him de azeite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Oferecei como oferta de bebida a metade de um him de vinho, como uma oferta queimada como aroma agradável a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Fazei desta maneira para cada novilho, ou carneiro e para cada cordeiro, cabrito ou cabra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Todo sacrifício que preparardes e oferecerdes fazei-o como descrito aqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Todos os que são nascidos em Israel devem fazer essas coisas, quando qualquer um trouxer uma oferta queimada, como aroma que seja agradável a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Se um estrangeiro estiver convosco, ou qualquer um que esteja entre vós ao longo de vossas gerações, ele deve apresentar uma oferta queimada, como aroma agradável a Yahweh. Ele deve agir como vós agis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Haverá a mesma lei para a vossa comunidade e para os estrangeiros que estão convosco, uma lei permanente ao longo das vossas gerações. Como vós sois, assim também deve ser o peregrino que está convosco. Ele deve agir como vós agis perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'A mesma lei e decreto deve aplicar-se a vós e ao estrangeiro que está convosco\"\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Novamente Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, '\"Fala ao povo de Israel e dize-lhes: \'Quando entrardes na terra que Eu vos colocarei,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'quando comerdes do fruto da terra, apresentareis a Mim uma oferta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Das primícias de vossas farinhas deveis oferecer um bolo como oferta da mesma forma com que é feita a oferta da eira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Dar-Me-eis das primícias da vossa massa como oferta ao longo das vossas gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Algumas vezes, vós pecareis sem intenção de pecar, quando não obedecerdes todas estas ordens que Eu tenho falado a Moisés,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'ou seja, tudo que Eu tenho vos ordenado através de Moisés, desde o dia em que Eu comecei a vos dar ordens e daí em diante, ao longo das vossas gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Então toda a comunidade oferecerá um novilho como holacausto, como aroma agradável a Yahweh, no caso de pecado não intencional sem o conhecimento da comunidade. Junto com isso será realizada uma oferta de cereais e uma oferta de bebida, como ordenado pelo Meu decreto, e um bode como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'O sacerdote fará expiação por toda a comunidade de Israel. Eles serão perdoados porque o pecado foi um erro. Eles apresentarão, perante Mim, o sacrifício pelo seu erro, uma oferta queimada como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Então toda a comunidade do povo de Israel será perdoada e também os estrangeiros que estão entre eles, porque todo o povo cometeu o pecado sem intenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Se uma pessoa peca sem intenção de pecar, então ela oferecerá uma cabra de um ano como oferta de pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'O sacerdote fará expiação perante Yahweh pela pessoa que pecou sem intenção. Essa pessoa será perdoada quando a expiação for feita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Tende a mesma lei para aquele que faz qualquer coisa sem intenção, a mesma lei para aquele nascido entre o povo de Israel e para os estrangeiros que estão entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Mas a pessoa que fizer qualquer coisa em provocação, quer seja nascido de Israel, quer seja estrangeiro, blasfema contra Mim. Essa pessoa será expulsa do meio do seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Porque ela desprezou Minha palavra e desobedeceu Minhas ordens, essa pessoa deve ser eliminada. O seu pecado estará sobre ela\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Enquanto o povo de Israel estava no deserto, eles encontraram um homem ajuntando madeira no dia de sábado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Aqueles que o acharam o trouxeram a Moisés, Arão, e à toda a comunidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Eles o mantiveram retido porque ainda não havia sido declarado o que deveria ser feito com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Então Yahweh disse a Moisés: \"Certamente o homem deve ser morto. Toda a comunidade deve apedrejá-lo do lado de fora do acampamento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Então toda a comunidade levou-o para fora do acampamento e apedrejaram-no até a morte como Yahweh havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Novamente Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, '\"Diz aos descendentes de Israel e ordena-lhes que façam para si franjas para pendurar nas bordas de suas vestes, e nas franjas das bordas colocarão um cordão azul. Eles farão isso continuamente ao longo das suas gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Quando olhares para ele, isso vos será uma lembrança especial de todas as minhas ordens, para levar-vos a não seguir o vosso próprio coração e os vossos próprios olhos que vos tem levado a prostituir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Fazei isso para lembrardes e obedecerdes todas as minhas ordenanças, e então sereis santos, separados para Mim, o seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Eu sou Yahweh, o vosso Deus, Quem vos tirou da terra do Egito, para ser o vosso Deus. Eu sou Yahweh, o vosso Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Então, Coré, filho de Izar, filho de Coate, filho de Levi, junto de Datã e Abirão, filhos de Eliabe, e Om, filho de Pelete, descendentes de Rúben, reuniram alguns homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'Levantaram-se contra Moisés, junto de outros homens do povo de Israel, duzentos e cinquenta líderes da assembleia, membros renomados da comunidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Ajuntaram-se para confrontar Moisés e Arão. Disseram-lhes: \"Basta! Isto é demais. Toda a assembleia é santa, todos eles são santos e Yahweh está no meio deles. Por que vos elevais sobre o resto da assembleia de Yahweh?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Quando Moisés ouviu isto, caiu sobre o seu rosto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Falou com Coré e com todo o seu grupo dizendo: \"Pela manhã, Yahweh mostrará quem é Dele e quem é santo, este Ele trará para Si. Aquele a quem Ele escolher, Ele o trará para perto de Si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Fazei isso, Coré e todo o vosso grupo. Pegai incensários');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'amanhã e colocai fogo e incenso diante de Yahweh. O homem que for escolhido, será dedicado a Yahweh. Vós fostes longe demais, descendência de Levi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Novamente, Moisés disse a Coré: \"Agora escutai, vós descendência de Levi,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'por acaso é pouca coisa que o Deus de Israel tem vos separado da comunidade de Israel, para aproximar-vos Dele, para fazerdes os serviços no Tabernáculo, e estardes diante da comunidade para servi-los?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Ele vos trouxe para perto, trouxe toda a vossa parentela, os descendentes de Levi convosco, e ainda quereis o sacerdócio!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'É por este motivo que vós e todo vosso grupo têm reunido contra Yahweh. Então, por que estão murmurando contra Arão, que obedece a Yahweh?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Então, Moisés, chamou por Datã e Abirão, os filhos de Eliabe, mas disseram-lhe: \"Não iremos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Por acaso, é pouca coisa ter-nos tirado de uma terra de que flui leite e mel, para nos matar no deserto? Agora, quer te fazer líder sobre nós!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Portanto, Tu não nos trouxeste para uma terra de que flui leite e mel, nem nos deste campos nem vinhas como herança. Agora quer nos cegar com promessas vazias? Nós não iremos a ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Moisés se indignou e disse a Yahweh: \"Não consideres sua oferta. Eu não lhes tomei nenhum jumento, nem sequer lhes causei dano\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Então, Moisés disse a Coré: \"Amanhã, vós todos comparecei diante de Yahweh — tu, eles e Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Cada um de vós, levará seus incensários e colocará incenso nele. Então, cada homem levará, diante de Yahweh, seu incensário, duzentos e cinquenta incensários. Tu e Arão também levareis vossos incensários\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Então, cada homem levou seu incensário, acendeu-o, colocou o incenso, e ficou na entrada da Tenda do Encontro com Moisés e Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Coré reuniu toda a assembleia contra Moisés e Arão na entrada da Tenda do Encontro, e a glória de Yahweh apareceu para toda a assembleia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Então, Yahweh falou a Moisés e a Arão:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, '\"Separai-vos do meio desta assembleia, para que Eu possa consumi-los imediatamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Prostraram-se ao chão, Moisés e Arão, e disseram: \"Deus, o Deus dos espíritos e de toda humanidade, se um homem peca, deves Tu irar-te com toda a assembleia?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Yahweh respondeu a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, '\"Fala com a assembleia, diz: \'Afastai-vos das tendas de Coré, Datã e Abirão\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Então, Moisés se levantou e foi até Datã e Abirão; os anciãos de Israel o seguiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'E falou à assembleia: \"Afastai-vos das tendas destes homens ímpios, não toqueis em nada que lhes pertença, ou vós sereis consumidos por causa de todos os pecados deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Então, a comunidade de todos os lados das tendas de Coré, Datã e Abirão, os deixou. Datã e Abirão saíram e ficaram na entrada de suas tendas, com suas mulheres e filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Então, Moisés disse: \"Por isso, sabereis que Yahweh me enviou para fazer todas essas obras, porque eu não as fiz de minha própria vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Se esses homens morrerem de morte natural, como acontece normalmente, Yahweh não me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Mas, se Yahweh criar uma abertura na terra, que os engolirá como uma grande boca, junto de tudo o que é deles, e se eles descerem vivos ao Sheol, então, entendereis que estes homens desprezaram Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Logo que Moisés terminou de falar essas palavras, a terra se abriu debaixo desses homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'A terra abriu sua boca e os engoliu, suas famílias, e todas as pessoas que pertenciam a Coré, e também, todas as suas possessões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Eles e todos em suas famílias, desceram vivos ao Sheol. A terra se fechou sobre eles, e pereceram no meio da assembleia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'E toda Israel em torno deles, fugiu de seus gritos. Exclamando: \"A terra pode nos engolir também!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Então, acendeu o fogo da parte de Yahweh, e devorou os duzentos e cinquenta homens que ofereceram incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Outra vez, Yahweh falou a Moisés, e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, '\"Fala com Eleazar, filho do sacerdote Arão, para que tire os incensários das chamas, e espalhe as brasas para longe, pois foram dedicados a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Pega os incensários dos que perderam a vida por causa dos seus pecados, para que sejam como chapas marteladas e serem uma cobertura do altar. Aqueles homens os ofertaram diante de Mim, então eles são dedicados a Mim. Eles serão um sinal da minha presença ao povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Eleazar, o sacerdote, pegou os incensários de bronze que foram usados pelos homens que foram queimados. Ele os martelou como uma cobertura para o altar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'como Yahweh havia dito por meio de Moisés, para ser um lembrete ao povo de Israel, para que nenhuma pessoa que não descendesse de Arão se aproximasse para queimar incenso diante de Yahweh. Dessa maneira, nenhuma pessoa seria como Coré e seu grupo — exatamente como Yahweh havia ordenado por meio de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Mas, na manhã seguinte, toda a comunidade do povo de Israel, murmurou contra Moisés e Arão dizendo: \"Vós matastes o povo de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Então, aconteceu que a comunidade se reuniu contra Moisés e Arão, olharam em direção à Tenda do Encontro, e contemplaram que a nuvem estava cobrindo-a. A glória de Yahweh apareceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Moisés e Arão foram até a frente da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Então, Yahweh disse a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, '\"Sai do meio desta comunidade para que eu possa consumi-los imediatamente\". Então, Moisés e Arão se prostraram com seus rostos sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Moisés disse a Arão: \"Pega o incensário, acende-o em frente ao altar, coloca incenso, carrega-o rapidamente para a comunidade, e faze expiação por ela, pois a ira está vindo da parte de Yahweh. Iniciou-se a praga\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Então, Arão fez como Moisés o direcionou. Correu em direção ao meio da comunidade. A praga começou rapidamente a espalhar-se entre o povo, então, colocou o incenso e expiou pelo povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Arão se pôs entre a morte e a vida; dessa maneira, a praga cessou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Os que morreram pela praga, foram quatorze mil e setecentos, em números, tirando os que morreram pelas razões de Coré.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Arão retornou a Moisés na entrada da Tenda do Encontro, e a praga teve seu fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, '\"Dize ao povo de Israel que apresentem varas, uma de cada tribo de seus antepassados. Toma doze varas, uma de cada líder escolhido de cada tribo. Escreve o nome de cada homem em sua vara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Tu escreverás o nome de Arão na vara de Levi. Deverá ser uma vara de cada líder da sua tribo de antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Tu colocarás as varas na Tenda do Encontro em frente aos decretos da aliança, onde Me encontro contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'E acontecerá que a vara do homem que escolhi, florescerá. Eu farei parar as murmurações do povo de Israel, as quais eram contra ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Então, Moisés falou ao povo de Israel. Todos os líderes das tribos deram-lhe as varas, uma vara de cada líder, escolhida de cada tribo antepassada, doze varas ao todo. A vara de Arão estava entre elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'E Moisés colocou as varas diante de Yahweh, na Tenda dos Decretos da Aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'No dia seguinte, Moisés entrou na Tenda dos Decretos da Aliança, e viu que a vara de Arão da tribo de Levi havia florescido. Brotou, produziu flores e amêndoas maduras!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Moisés trouxe todas as varas de diante de Yahweh para todo o povo de Israel e cada homem tomou a sua vara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Yahweh disse a Moisés: \"Coloca a vara de Arão em frente aos decretos da Aliança. E mantém-na como um sinal de culpa contra as pessoas que se rebelaram, para que acabes com as murmurações contra Mim, ou então morrerão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Moisés fez assim como Yahweh havia lhe ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'O povo de Israel falou a Moisés, e disse-lhe: \"Nós morreremos aqui. Iremos todos perecer!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Todo aquele que vem, que se aproxima do Tabernáculo de Yahweh morrerá. Teremos todos que perecer?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Yahweh disse a Arão: \"Tu, teus filhos, e o clã dos teus antepassados sereis responsáveis por todos os pecados cometidos contra o santuário. Mas somente tu e teus filhos sereis responsabilizados por todos os pecados praticados por qualquer um no sacerdócio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'E os membros da tribo de Levi, tribo de vossos antepassados, tu os trarás contigo, para que se juntem a ti quando tu e teus filhos servirdes em frente à Tenda dos Decretos da Aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'ervirão a ti e a toda a tenda. No entanto, eles não se aproximarão de qualquer coisa no lugar santo ou que seja relacionada ao altar, senão morrereis tanto eles quanto vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Juntar-se-ão a ti para cuidar da Tenda do Encontro, para todo trabalho relacionado à tenda. O estrangeiro não se aproximará de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Terás que te responsabilizar pelo lugar santo e pelo altar, para que Minha ira não venha sobre o povo de Israel de novo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Vede, Eu mesmo escolhi dentre os descendentes de Israel os vossos irmãos, os levitas. Eles são uma oferta dada a vós para Yahweh, a fim de fazerem o trabalho relacionado à Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Mas somente tu e teus filhos exercereis o sacerdócio de acordo com tudo relacionado ao altar e tudo que há por dentro da cortina. Vós, vós mesmos, cumprirão aquelas responsabilidades. Dou a vós o sacerdócio como um presente, e qualquer estrangeiro que se aproximar deverá morrer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Então, Yahweh disse a Arão: \"Eis que te encarreguei de levantar ofertas para Mim, e toda a oferta santa que o povo de Israel Me der, Eu tenho dado a ti e a teus filhos como direito perpétuo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Das coisas santíssimas, que não passaram pelo fogo, isto será teu: toda oferta deles, com toda oferta de cereal, com toda oferta pelo pecado e toda oferta pela culpa, são coisas santíssimas para vós e para vossos filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Estas ofertas são santíssimas; todo homem deve comê-las, pois elas são santificadas para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Estas serão as ofertas que pertencerão a ti: seus presentes, todas as ofertas movidas dos filhos de Israel. Eu as dei para ti, para teus filhos e tuas filhas, como porção perpétua. Todos em tua família que estão ritualmente limpos podem comer qualquer uma dessas ofertas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'O melhor do azeite, o melhor do vinho novo e dos cereais, as primícias que o povo Me der, todas estas coisas tenho dado a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Os primeiros frutos maduros de toda a sua terra, que forem trazidos a Mim, serão teus. Todos na tua familia que estiverem limpos poderão comer estas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Todas as coisas consagradas em Israel serão tuas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Todos aqueles que abrem o ventre, todo primogênito, seja de homem, seja de animal, que o povo oferecer a Yahweh, ambos serão teus. Porém, o povo deverá resgatar de volta todo filho primogênito e também todo primogênito de animal impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Aqueles que serão resgatados pelo povo, serão resgatados depois de completar um mês de idade. Assim, o povo poderá resgatá-los por cinco siclos de prata, segundo o modelo de peso do siclo do santuário, que equivale a vinte geras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'O primogênito da vaca, da ovelha, ou da cabra, não poderão ser comprados de volta, estes são separados para Mim. Deverás aspergir seu sangue no altar e queimar sua gordura como oferta queimada de aroma agradável para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'A carne será tua, bem como o peito de oferta movida e a coxa direita, a carne deles será tua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Toda a oferta santificada que o povo de Israel apresentar a Yahweh, darei a ti, a teus filhos e filhas como herança perpétua. Isto é uma aliança perpétua de sal, uma aliança estabelecida para sempre perante Yahweh para contigo e para com os teus descendentes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Yahweh disse a Arão: \"Tu não terás herança na terra do povo, nem terás qualquer porção de propriedade entre o povo. Eu sou tua porção e herança entre o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Para os descendentes de Levi, vê, Eu dei todo dízimo em Israel como herança pelo serviço que fizeram na Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'De agora em diante, o povo de Israel não poderá chegar perto da Tenda do Encontro, ou serão responsabilizados por este pecado e morrerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Os levitas farão o trabalho ligado à Tenda do Encontro. Serão responsabilizados por qualquer pecado relacionado a isto. Essa será uma lei permanente ao longo das gerações de vosso povo. Eles não possuirão herança entre o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Pois os dízimos do povo de Israel, que foram apresentados a Mim como oferta, dei aos levitas como herança. Por isso, disse-lhes: \'Não possuirão herança entre o povo de Israel\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Yahweh falou com Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, '\"Fala com os levitas, dizendo-lhes: \'Quando receberdes do povo de Israel o dízimo que o Senhor vos deu como herança, oferecereis a Yahweh o dízimo disto, um dízimo dos dízimos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Essa vossa contribuição será considerada como se fosse a décima parte do grão da eira ou da produção do lagar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Assim, vós tamb; em apresentareis uma oferta a Yahweh de todos os dízimos que receberdes do povo de Israel. Destes, apresentareis a Arão, o sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'De todos os presentes que receberdes, fareis ofertas a Yahweh. Farei esta oferta das coisas que Eu vos dei, escolhendo a melhor delas, e a sua parte santa\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Então, lhes dirás: \'Quando apresentardes o melhor do que receberdes, o restante das vossas ofertas deverá ser considerado pelos levitas como o produto da eira e produto do lagar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Podereis comê-lo em qualquer lugar, vós e vossa família, porque isso é vossa recompensa por todo trabalho feito na Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Não sereis culpados por comer ou beber isso, se apresentardes a Yahweh o melhor do que receberdes. Mas não profaneis a santa oferta oferecida pelo povo de Israel, ou morrereis\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Yahweh falou a Moisés e a Arão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, '\"Este é um estatuto, uma lei que Eu vos ordeno. Dizei aos filhos de Israel que tragam uma novilha vermelha, sem mácula ou defeito, que nunca tenha carregado um jugo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'A novilha será entregue ao sacerdote Eleazar, que a levará para ser imolada fora do acampamento, à vista dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Eleazar, o sacerdote, pegará um pouco do sangue da vítima, e, com o dedo dele, aspergirá sete vezes, em direção à entrada da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Outro sacerdote queimará completamente a novilha: o couro, a carne, o sangue e até os excrementos dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'O sacerdote pegará um pau de cedro, hissopo, lã escarlarte, e os lançará no meio do fogo, enquanto a novilha estiver sendo queimada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Depois, ele lavará as suas vestes e se banhará nas águas. Assim, poderá entrar no acampamento, onde ficará impuro até ao anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'E aquele que incinerou a novilha, lavará as suas vestes nas águas e banhará a sua carne nas águas, mas ele permanecerá impuro até ao anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Alguém que estiver limpo, ajuntará as cinzas do novilho e as depositará fora do acampamento, em um lugar limpo. Ali, elas serão guardadas pela comunidade do povo de Israel para o preparo da água purificadora, pois essas cinzas são de uma oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Aquele que recolheu as cinzas da novilha, deverá lavar as suas roupas; e ele permanecerá impuro até ao anoitecer. Esta será uma lei permanente para os filhos de Israel e para os estrangeiros que vivem com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Aquele que tocar no cadáver de algum humano, ficará impuro por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Este deverá purificar-se, no terceiro e no sétimo dia, e se tornará limpo. Porém, se não se purificar no terceiro dia, ele não estará limpo no sétimo dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Qualquer pessoa que não se purificar, contaminará o Tabernáculo de Yahweh. Essa pessoa deverá ser eliminada de Israel, porque a água da purificação não lhe foi aspergida. Ele permanecerá imundo e sua impureza estará sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Esta é a lei para quando alguém morre dentro de uma tenda. Todo aquele que já estiver dentro da tenda, e o que nela entrar, ficará impuro por sete dias;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'todo recipiente aberto sem tampa, ficará impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Da mesma maneira, se alguém, na parte externa da tenda, tocar em algum morto por espada, ou em qualquer outro cadáver, ou em osso humano, ou mesmo numa sepultura, essa pessoa se tornará impura por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Para a purificação de uma pessoa impura, pegarás um pouco da cinza da oferta que foi queimada pelo pecado, e a misturarás com água corrente dentro de um jarro;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'um homem limpo, mergulhará o hissopo na água e a aspergirá sobre a tenda, e sobre todos os recipientes dentro dela; também aspergirá sobre as pessoas que estiveram lá dentro, e sobre quem tiver tocado no corpo de pessoa assassinada, ou em osso, ou em qualquer cadáver, ou sepultura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'No terceiro e no sétimo dia, alguém que estiver limpo, deverá aspergir a pessoa impura. No sétimo dia, a pessoa impura deverá purificar-se; também lavará as suas roupas e banhar-se-á em água corrente. Ao anoitecer, ela ficará limpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Mas toda pessoa impura que se recusar a se purificar será eliminada da comunidade, porquanto contaminará o santuário de Yahweh. Visto que a água da purificação não foi aspergida sobre ela, pemanecerá impura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Isto será um estatuto perpétuo: aquele que aspergir a água da purificação, deverá lavar suas vestes; aquele que tocar a água da purificação, ficará impuro até o anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Qualquer coisa que o impuro tocar, ficará impura. A pessoa que tocá-lo, também ficará impura até o anoitecer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Então, o povo de Israel — toda a comunidade — foi para o deserto de Zim, no primeiro mês. Eles ficaram em Cades. Ali, Miriã morreu e foi sepultada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Não havia água para a comunidade, por isso, juntaram-se contra Moisés e Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'O povo se queixou contra Moisés. Disseram: \"Teria sido melhor se tivéssemos morrido quando os nossos irmãos morreram diante de Yahweh!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Por que trouxeste a comunidade de Yahweh para este deserto para morrer aqui, nós e os nossos animais?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'E por que tu nos fizeste sair do Egito para trazer-nos para este lugar horrível? Aqui não há sementes, figos, vinhas ou romãs, e não há água para beber\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Então, Moisés e Arão saíram da frente da assembleia. Eles foram para a entrada da Tenda do Encontro e se prostraram com as suas faces voltadas para o chão. Ali, a glória de Yahweh lhes apareceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, '\"Pega o teu cajado e reúne a comunidade, tu e o teu irmão Arão. Fala à pedra diante dos olhos deles e ordena que dela flua água. Vocês tirarão água da rocha e a darão à comunidade e ao seu gado para beber\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Moisés pegou o cajado na presença de Yahweh, conforme Yahweh lhe ordenara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Então, Moisés e Arão reuniram a assembleia diante da rocha. Moisés lhes disse: \"Escutai agora, vós rebeldes. Devemos nós tirar água desta rocha para vós?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Então, Moisés levantou a sua mão e bateu na rocha duas vezes com o seu cajado, e saiu muita água. A comunidade e o seu gado a beberam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Então, Yahweh disse a Moisés e Arão: \"Porque não confiastes em mim e não me honrastes como Santo diante dos olhos do povo de Israel, não levarei esta assembleia à terra que também lhes dei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Esse lugar foi chamado águas de Meribá porque o povo de Israel contendeu com Yahweh ali, e Ele lhes mostrou a Sua santidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Moisés mandou mensageiros de Cades ao rei de Edom: \"O teu irmão Israel diz isto:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, '\'Tu conheces todas as dificuldades que temos enfrentado. Tu sabes que nossos antepassados desceram para o Egito e viveram por lá um tempo longo. Os egípcios nos trataram asperamente e também aos nossos antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Quando clamamos a Yahweh, Ele ouviu a nossa voz e mandou um anjo e nos tirou do Egito. Vê, estamos em Cades, uma cidade na fronteira com a tua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Eu estou te pedindo que nos deixes passar por tua terra. Não passaremos pelo campo ou pelo vinhedo, nem beberemos água dos teus poços. Passaremos ao longo da estrada real. Não nos desviaremos para a direita ou para a esquerda, até que tenhamos passado por tuas fronteiras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Mas o rei de Edom lhe respondeu: \"Não poderás passar por aqui. Se o fizeres, irei com a espada para te atacar\". Então, o povo de Israel lhe disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, '\"Nós iremos ao longo da estrada. Se nós ou as nossas manadas bebermos da tua água, nós pagaremos por isso. Apenas nos deixa passar a pé, sem fazer nada mais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Mas o rei de Edom respondeu: \"Tu não poderás passar\". Desse modo, o rei de Edom veio contra Israel com mão forte, com muitos soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'O rei de Edom se recusou a deixar Israel passar por sua fronteira. Por causa disso, Israel se afastou da terra de Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Assim, o povo partiu de Cades. O povo de Israel — toda a comunidade — chegou ao Monte Hor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Yahweh falou a Moisés e Arão no Monte Hor, na fronteira do Edom dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, '\"Arão será reunido ao seu povo, porque ele não entrará na terra que dei ao povo de Israel. Isto porque vos rebelastes contra a Minha palavra nas águas de Meribá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Toma Arão e Eleazar, seu filho, e os leva para o Monte Hor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Tira as roupas sacerdotais de Arão e coloca-as em Eleazer, seu filho. Arão morrerá e será reunido ao seu povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Moisés fez como Yahweh lhe ordenou. Eles subiram o Monte Hor diante de toda a comunidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Moisés lhe tirou as roupas sacerdotais e as colocou em Eleazar, seu filho. Arão morreu no topo da montanha. E, então, Moisés e Eleazar desceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Quando toda a comunidade viu que Arão estava morto, a nação inteira chorou por ele durante trinta dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Quando o rei cananeu de Arade, que vivia no Neguebe, ouviu que Israel vinha pela estrada de Atarim, ele atacou Israel e tomou alguns deles como cativos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Israel jurou a Yahweh, e disse: \"Se Tu nos deres a vitória sobre este povo, então destruiremos por completo suas cidades\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Yahweh ouviu a voz de Israel e concedeu-lhes a vitória sobre os Cananeus. Eles os destruiram completamente, e também suas cidades. O lugar foi chamado Hormá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Eles viajaram do Monte Hor pelo caminho para o Mar Vermelho, ao redor da terra de Edom. E o povo ficou muito desanimado no caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'O povo mumurava contra Deus e Moisés: \"Por que Tu nos tirastes do Egito para morrer no deserto? Não temos pão nem água, e odiamos essa comida miserável\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Então, Yahweh enviou serpentes venenosas contra o povo. As serpentes picaram as pessoas; muitas morreram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'O povo veio a Moisés e disse: \"Nós pecamos, porque murmuramos contra Yahweh e contra ti. Ora a Yahweh para que Ele leve as serpentes para longe de nós\". Então, Moisés orou pelo povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Yahweh disse a Moisés: \"Faz uma serpente e põe-na numa haste. Todo aquele que foi mordido sobreviverá, se olhar pra ela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Então, Moisés fez uma serpente de bronze, e a colocou na haste. Quando uma serpente picava alguém, se ele olhasse para a serpente de bronze, sobrevivia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Então, o povo de Israel viajou e acampou em Obote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Eles viajaram de Obote e acamparam no Ije-Abarim, no deserto de frente a Moabe, em direção ao leste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Dali, eles continuaram viajando, e acamparam no vale de Zerede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'E, partindo dali, prosseguiram viagem e acamparam no outro lado do rio Arnom, que está no deserto que se estende das fronteiras dos amorreus. O rio Arnom faz a fronteira entre Moabe e os amorreus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Por isso, diz no Livro das Guerras de Yahweh: \"Vaebe em Sufa, e os vales do Arnom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'na descida dos vales que leva à cidade de Ar e chega até a fronteira de Moabe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Dali, eles partiram para Beer, e foi ali no poço que Yahweh disse a Moisés: \"Reúna o povo, e Eu lhes darei água\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Então, Israel cantou esta canção: \"Brota, ó poço. Cantai sobre isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'O poço que nossos líderes cavaram, o poço que os nobres do povo cavaram com o cetro e as varas\". Então, do deserto, eles viajaram para Matana.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'De Matana eles viajaram para Naaliel, e de Naaliel para Bamote,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'e, de Bamote, ao vale na terra de Moabe. Ali, é onde o topo do monte Pisga defronta o deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Então, Israel enviou messageiros a Siom, rei dos amorreus, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, '\"Deixe-nos passar por sua terra. Nós não entraremos em nenhuma plantação ou vinha. Não beberemos a água dos seus poços. Viajaremos pela estrada real, até que tenhamos cruzado sua fronteira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Mas o rei Siom não permitiu a Israel atravessar seu território. Ao invés disso, Siom reuniu todo o seu exército e atacou Israel no deserto. Ele veio a Jaza, onde lutou contra Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Israel atacou o exército de Siom no fio de espada, e tomou a terra de Arnom ao rio Jaboque, até a fronteira do povo de Amon, que era fortificada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Israel tomou todas as cidades dos amorreus, e habitou em todas elas, incluindo Hesbom e todas as suas aldeias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Hesbom era a cidade de Siom, rei dos amorreus, que havia lutado contra o antigo rei de Moabe, e tomado todo o seu território até o rio Arnom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Por isso, aqueles que falam por provérbios dizem: \"Vinde a Hesbom. Que a cidade de Siom seja reconstruída e reestabelecida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Um fogo ardeu de Hesbom, uma chama da cidade de Siom que devorou Ar de Moabe, e os senhores dos altos de Arnom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Ai de ti, Moabe! Tu já perecestes, povo de Camos. Ele fez de seus filhos fugitivos e de suas filhas prisioneiras de Siom, rei dos amorreus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Mas nós conquistamos Siom. Hesbom está devastada por todo o caminho até Dibom. Nós os derrotamos até Nofá, que chega até Medeba\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Então, Israel habitou na terra dos amorreus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'E Moisés enviou homens para espiar Jazer. E Israel tomou suas aldeias e expulsou os amorreus que estavam ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Então, eles voltaram e subiram pelo caminho de Basã. Ogue, rei de Basã, saiu contra eles, ele e todo o seu exercito, para lutar em Edrei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Então, Yahweh disse a Moisés: \"Não o temas, porque Eu te dei a vitória sobre eles, e todo o seu exército, e toda a sua terra. Faça com ele o que tu fizestes com Siom, rei dos amorreus, que habitava em Hesbom\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Então, eles o mataram, seus filhos e todo o seu exército, até que nenhum deles ficou vivo. E eles lhes tomaram a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'O povo de Israel viajou até as planícies de Moabe, e ali acamparam, do outro lado do rio Jordão, nas proximidades da cidade de Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Balaque, filho de Zipor, viu tudo que Israel havia feito com os amorreus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Moabe estava com muito medo dos israelitas, pois eles eram muitos, e isto causava-lhes pavor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'O rei de Moabe disse aos anciãos de Midiã: \"Essa multidão comerá tudo à nossa volta como um boi que devora as ervas do campo\". Nessa época, Balaque, filho de Zipor, era rei de Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Ele mandou mensageiros para Balaão, filho de Beor, em Petor, que fica perto do rio Eufrates, na terra de sua nação e seu povo. Ele o chamou e disse-lhe: \"Olha, uma nação veio aqui do Egito. Eles cobrem a face da terra e estão agora ao meu lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Então, por favor, vem e amaldiçoa essa nação por mim, porque são mais fortes do que eu. Talvez, então, eu consiga atacá-los e expulsá-los dessa terra. Eu sei que qualquer um que abençoares será abençoado, e qualquer um que amaldiçoares será amaldiçoado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Então, os anciãos de Moabe e os anciãos de Midiã partiram, levando o pagamento pelos encantamentos. Eles foram até Balaão e falaram-lhe as palavras de Balaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Balaão disse: \"Ficai aqui esta noite. Eu trarei o que Yahweh disser para mim\". Então, os líderes de Moabe ficaram com Balaão naquela noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Veio Deus a Balaão e disse-lhe: \"Quem são esses homens que vieram a ti?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Balaão respondeu: \"Balaque, filho de Zipor, rei de Moabe, enviou-os para que me dissessem:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '\'Olha, esse povo que veio do Egito cobre a superfície da terra. Agora vem e amaldiçoa esse povo para mim. Talvez eu consiga lutar contra eles e expulsá-los dessa terra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Deus disse a Balaão: \"Não irás com aqueles homens. Não amaldiçoarás o povo de Israel, porque eles foram abençoados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Balaão se levantou pela manhã e disse aos líderes: \"Voltai para vossa terra, pois Yahweh Se recusou a permitir que eu vá convosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Então, os líderes de Moabe partiram e voltaram a Balaque. Disseram-lhe: \"Balaão se recusou a vir conosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Balaque enviou novamente líderes, que eram ainda mais honrados que o primeiro grupo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Eles foram a Balaão e disseram-lhe: \"Balaque, filho de Zipor, diz: \'Por favor, que nada te detenha de vir a mim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'porque eu te pagarei extremamente bem e te darei grandes honras, e farei tudo o que disseres. Então, por favor, vem e amaldiçoa esse povo para mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Balaão respondeu, e disse aos homens de Balaque: \"Mesmo que Balaque me desse seu palácio cheio de prata e ouro, eu não poderia ir contra a palavra de Yahweh, meu Deus, e fazer nada mais e nada menos do que Ele me disser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Então, por favor, esperem aqui também esta noite, para que eu compreenda o que mais Yahweh dirá a mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Deus veio a Balaão naquela noite e disse-lhe: \"Já que esses homens convocaram a ti, levanta-te e vai com eles. Mas faz apenas o que Eu lhe disser\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Balaão acordou pela manhã, preparou sua jumenta, e foi junto com os líderes de Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Mas, porque ele foi, a ira de Deus se acendeu. O anjo de Yahweh se colocou em frente ao caminho como alguém hostil a Balaão, que estava montado em sua jumenta. Os dois servos de Balaão estavam junto com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'A jumenta viu o anjo de Yahweh posicionado no caminho, com a espada desembainhada em sua mão. A jumenta se desviou da estrada e foi para o campo. Balaão bateu na jumenta para que ela voltasse ao caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Então, o anjo de Yahweh ficou numa parte estreita do caminho entre alguns vinhedos, com uma parede à sua direita e outra à sua esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'A jumenta viu novamente o anjo de Yahweh. Ela foi em direção à parede e pressionou o pé de Balaão contra ela. Balaão bateu nela de novo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'O anjo de Yahweh foi mais adiante, e posicionou-se em outra parte estreita, onde não havia saída em nenhum lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'A jumenta viu o anjo de Yahweh, e deitou-se debaixo de Balaão. A ira de Balaão se acendeu, e ele bateu na jumenta com seu cajado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Então, Yahweh abriu a boca da jumenta, e ela começou a falar. Ela disse a Balaão: \"O que fiz para que julgasses necessário bater-me três vezes?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Balaão respondeu: \"Foi porque agiste estupidamente comigo. Gostaria que houvesse uma espada em minha mão. Se tivesse, eu a teria matado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'A jumenta disse a Balaão: \"Não sou a jumenta em que montaste toda a tua vida até os dias de hoje? Já tive o hábito de fazer essas coisas contigo antes?\". Balaão disse: \"Não\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Então, Yahweh abriu os olhos de Balaão, e ele viu o anjo de Yahweh posicionado no caminho, com a espada desembainhada em sua mão. Balaão curvou sua cabeça, e deitou-se com a face na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'O anjo de Yahweh lhe disse: \"Por que bateste em tua jumenta três vezes? Olha, vim como alguém hostil a ti, pois tuas ações perante minha presença foram perversas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'A jumenta me viu três vezes, e desviou de mim as três vezes. Se ela não tivesse desviado, certamente o teria matado e poupado a vida dela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Balaão disse ao anjo de Yahweh: \"Pequei. Não sabia que estavas parado no caminho contra mim. Então, se essa viagem o desagradar, retornarei ao lugar de onde vim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Porém, o anjo de Yahweh disse a Balaão: \"Vá em frente com esses homens, mas tu falarás somente o que eu te disser\". Então, Balaão foi junto com os líderes de Balaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Quando Balaque ouviu que Balaão havia chegado, ele foi ao seu encontro na região de Moabe, que está na fronteira de Arnom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Balaque disse a Balaão: \"Não mandei homens para te convocar? Por que tu não vieste a mim? Não sou capaz de honrá-lo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Então, Balaão respondeu a Balaque: \"Vê, eu vim a ti. Será que tenho algum poder para dizer qualquer coisa? Posso dizer somente as palavras que Deus coloca em minha boca\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Balaão foi com Balaque, até Quiriate-Huzote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Então, Balaque sacrificou bois e ovelhas, e deu carne a Balaão e aos líderes que estavam com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Durante a manhã, Balaque levou Balaão às colinas de Baal. De lá, Balaão viu somente uma parte dos israelitas em seu campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Balaão disse para Balaque: \"Edifica-me sete altares aqui e prepara sete novilhos e sete carneiros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Assim, Balaque fez como Balaão pediu. Então Balaque e Balaão ofereceram um novilho e um carneiro sobre cada altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Então, Balaão disse para Balaque: \"Fica junto à tua oferta queimada e eu me afastarei. Talvez Yahweh venha e me encontre. Tudo o que Ele me mostrar eu te direi\". Então ele se foi para o topo de uma montanha sem árvores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Deus o encontrou, e Balaão lhe disse: \"Eu preparei sete altares, e ofereci um novilho e um carneiro sobre cada um\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Yahweh colocou uma mensagem na boca de Balaão e disse: \"Retorna a Balaque e fala para ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Assim, Balaão retornou a Balaque, que estava em pé junto à sua oferta queimada, e todos os lideres de Moabe estavam com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Então Balaão começou a falar a sua profecia e disse: \"Balaque trouxe-me de Arã. O rei de Moabe das montanhas do oriente. \'Vem, amaldiçoa Jacó para mim\', ele disse: \'Vem, sentencia Israel\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Como poderei amaldiçoar aqueles a quem Deus não amaldiçoou? Como poderei me opor àqueles a quem Yahweh não se opõe?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Pois do topo dos rochedos eu o vejo; das colinas eu o contemplo. Vede, existe um povo que vive sozinho e não se considera apenas uma nação comum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Quem pode contar o pó de Jacó ou até mesmo o número da quarta parte de Israel? Que eu morra a morte dos justos, e que a minha vida termine como a dele!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Balaque disse para Balaão: \"Que me fizeste? Eu te trouxe para amaldiçoar os meus inimigos, porém tu os abençoastes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Balaão respondeu e disse: \"Não deveria eu ser cuidadoso de dizer apenas o que Yahweh coloca na minha boca?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Assim, Balaque lhe disse: \"Por favor, vem comigo para outro lugar onde tu os podes ver. Verás deles somente os mais próximos, não todos eles. Dali, tu os amaldiçoarás para mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Assim, ele levou Balaão para o campo de Zofim, ao cume do Monte Pisga, e edificou mais sete altares. Ele ofereceu um novilho e um carneiro sobre cada altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Então Balaão disse para Balaque: \"Fica aqui junto à tua oferta queimada, enquanto eu me encontro com Yahweh ali\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Assim, Yahweh encontrou a Balaão e colocou uma mensagem em sua boca. Ele disse: \"Retorna a Balaque e lhe dá minha mensagem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Balaão retornou a ele, e eis que ele estava em pé junto à sua oferta queimada, e os líderes de Moabe estavam com ele. Então Balaque lhe disse: \"O que Yahweh disse?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Balaão começou a sua profecia. Ele disse: \"Levanta-te, Balaque, e escuta. Ouve-me, filho de Zipor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Deus não é homem, para que minta, nem ser humano, para que mude sua mente. Ele teria prometido alguma coisa sem cumpri-la? Ele teria dito que faria alguma coisa sem realizá-la?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Olha, recebi uma ordem para abençoar. Deus deu uma benção, e eu não posso revertê-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Ele não enxergou dureza em Jacó nem problema em Israel. Yahweh, o seu Deus, está com eles, e no meio deles há aclamações ao seu rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Deus os tirou do Egito com a força de um boi selvagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Não há encantamento que funcione contra Jacó, nem adivinhação que cause dano a Israel. Em vez disso, se dirá de Jacó e Israel: \'Vede o que Deus fez!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Vê, o povo se levanta como uma leoa, como um leão que sobe e ataca. Ele não se deitará até que coma a sua vítima e beba o sangue dos que ele matar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Então Balaque disse para Balaão: \"Se não os amaldiçoares, também não os abençoes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Porém Balaão, respondendo, disse para Balaque: \"Eu não te falei que tenho de dizer tudo o que Yahweh me falou para dizer?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Assim Balaque respondeu para Balaão: \"Vem agora, eu te levarei a outro lugar. Talvez dali Deus Se agrade que os amaldiçoes para mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Assim, Balaque levou Balaão para o cume do Monte Peor, com vista para o deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Balaão disse para Balaque: \"Edifica-me sete altares aqui e prepara-me sete novilhos e sete carneiros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Assim, Balaque fez como Balaão lhe havia dito; ele ofereceu um novilho e um carneiro sobre cada altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Quando Balaão viu que agradava a Yahweh em abençoar Israel, ele não fez, como das outras vezes, uso da feitiçaria. Ao invés disso, olhou em direção ao deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Levantou seus olhos e viu que Israel estava acampada, cada um em sua própria tribo, e o Espírito de Deus veio sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Ele recebeu essa profecia e disse: \"Balaão, filho de Beor, está para falar, o homem cujos olhos estão bem abertos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Ele fala e ouve as palavras de Deus. Ele vê a visão do Todo Poderoso, diante de quem ele se ajoelha de olhos abertos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Quão bonitas são suas tendas, Jacó, o lugar em que vives, Israel!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Como vales eles se espalham, como jardins à beira do rio, como aloés plantados por Yahweh, como cedros ao lado das águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Água flui de seus baldes, e suas sementes são bem regadas. Seu rei se elevará mais do que Agague, e seu reino será honrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Deus o traz do Egito com a força de um boi selvagem. Devorará as nações que lutam contra ele. Quebrará os seus ossos em pedaços, os atravessar\'a com suas flechas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Ele se agacha como um leão e como uma leoa, quem se atreve a perturbá-lo? Que todos os que o abençoarem sejam abençoados; que todos os que o amaldiçoarem sejam amaldiçoados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Então, a ira de Balaque se acendeu contra Balaão e ele bateu suas mãos juntas em raiva. Balaque disse a Balaão: \"Eu te chamei para amaldiçoar meus inimigos, mas vê, tu os tens abençoado três vezes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Então, deixa-me agora e vai para o teu lugar. Disse que te cobriria de honras, mas Yahweh te impediu de obter qualquer recompensa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Então, Balaão respondeu a Balaque: \"Eu disse aos mensageiros que tu me enviaste:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, '\'Ainda que Balaque me desse seu palácio cheio de prata e ouro, não poderia ir além das palavras de Yahweh e fazer por mim mesmo bem ou mal. Direi apenas o que Yahweh me ordenar a dizer\'. Não lhes disse isso?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Então, agora, vê, voltarei para meu povo, mas primeiro deixa-me avisar sobre o que estas pessoas farão ao teu povo nos dias à frente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Balaão começou a profetizar. Ele disse: \"Balaão, filho de Beor fala, o homem cujos olhos estão bem abertos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Essa é a profecia de alguém que ouve as palavras de Deus, que tem o conhecimento do Altíssimo, que tem visões do Todo Poderoso, diante de Quem ele se ajoelha de olhos abertos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Eu O vejo, mas Ele não está aqui agora. Eu olho para Ele, mas Ele não está perto. Uma estrela virá de Jacó, e um cetro subirá de Israel. Ele quebrará os líderes de Moabe e lhes destruirá a todos os descendentes de Sete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Então, Edom se tornará posse de Israel, e Seir também será sua possessão, inimigos de Israel, a quem Israel conquistará com força.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'De Jacó, virá um rei que terá domínio, e destruirá os sobreviventes da cidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Então, Balaão olhou para Amaleque e começou a profetizar. Disse-lhe: \"Amaleque já foi a maior das nações, mas seu fim será destruição\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Então, Balaão olhou em direção aos queneus e começou a profetizar. Disse-lhes: \"O lugar em que viveis é forte, e vossos ninhos estão nas rochas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'No entanto, o queneu será arruinado quando Assur vos levar cativos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Então, Balaão começou sua última profecia. Ele disse: \"Ai! Quem sobreviverá quando Deus fizer isso?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Navios virão da costa de Quitim; eles atacarão Assur e conquistarão Éber, mas eles, também, acabarão em destruição\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Então, Balaão se levantou e partiu. Retornou para sua casa, e Balaque também partiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Israel ficou em Sitim, e os homens começaram a se prostituir com as mulheres de Moabe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'pois os moabitas convidaram o povo aos sacrifícios dos seus deuses. E o povo comeu e se prostou diante dos deuses moabitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Os homens de Israel se juntaram em adoração a Baal-Peor, e a ira de Yahweh se acendeu contra Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Yahweh disse a Moisés: \"Mata todos os líderes do povo e os pendura diante de Mim para expô-los à luz do dia, para que a Minha fúria se retire de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Então, Moisés disse aos juízes de Israel: \"Cada um de vós executará os homens de sua tribo que se juntaram em adoração a Baal-Peor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Então, um israelita veio e trouxe aos membros de sua família uma mulher midianita. Isso acontenceu à vista de Moisés e de toda a comunidade do povo de Israel, enquanto eles choravam diante da Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Quando Fineias, filho de Eleazar, filho de Arão, o sacerdote, viu isso, levantou-se do meio da comunidade e pegou uma lança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Ele seguiu o homem israelita até Tenda e atravessou ambos os corpos com a lança, o homem israelita e a mulher. Então, a praga que o Senhor havia mandado ao povo de Israel, cessou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Aqueles que morreram pela praga foram vinte e quatro mil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Yahweh falou com Moisés e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, '\"Fineias, filho de Eleazar, filho de Arão, o sacerdote, desviou a Minha ira contra Israel, porque ele tinha paixão pelo Meu zelo entre eles. Assim, não consumi o povo de Israel em Minha ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Portanto, dize: Yahweh diz: \"Eu estou entregando a Fineias a Minha aliança de paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Esta será aliança de um sacerdócio perpétuo, para ele e sua descendência depois dele, pois foi zeloso a Mim, seu Deus. Ele fez expiação pelo povo de Israel\"\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'O nome do homem israelita que foi morto com a mulher midianita era Zinri, filho de Salu, líder de uma casa paterna dos simeonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'O nome da mulher midianita que foi morta era Cozbi, filha de Zur, cabeça de clã e família dentre os midianitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Também Yahweh falou com Moisés e lhe disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, '\"Trata os midianitas como inimigos e os ataca,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'pois eles vos trataram como inimigos, com seu engano. Eles vos conduziram à maldade, no caso de Peor e no caso de sua irmã Cozbi, a filha do líder de Midiã, que foi morta no dia da praga, no caso de Peor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Foi depois da praga que Yahweh falou com Moisés e Eleazar, filho do sacerdote Arão. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, '\"Contai toda a comunidade do povo de Israel, de vinte anos ou mais, pelas famílias de seus antepassados, todos que são aptos para guerrear por Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Então, Moisés e o sacerdote Eleazar falaram a eles na planície de Moabe diante do Jordão em Jericó, e disseram:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, '\"Contai o povo, de vinte anos de idade ou mais, como Yahweh ordenou a Moisés e ao povo de Israel, aqueles que saíram da terra do Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Rúben era o primogênito de Israel. De seu filho Hanoque, veio o clã dos hanoquitas; de Palu, veio o clã dos paluítas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'de Hezrom, veio o clã dos hezronitas; de Carmi, veio o clã dos carmitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Esses são os clãs descendentes de Rúben, foram contados quarenta e três mil, setecentos e trinta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Eliabe era o filho de Palu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Os filhos de Eliabe eram Nemuel, Datã e Abirão. Esses eram os mesmos Datã e Abirão que seguiram Coré quando eles desafiaram Moisés e Arão e rebelaram-se contra Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'A terra abriu sua boca e os engoliu junto com Coré quando todos os seus seguidores morreram. Naquele momento, o fogo devorou duzentos e cinquenta homens, que se tornaram um sinal de advertência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Todavia, a linhagem de Coré não morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Os clãs dos descendentes de Simeão eram esses: de Nemuel, o clã dos Nemuelitas; de Jamim, o clã dos Jaminitas; de Jaquim, o clã do Jaquinitas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'de Zerá, o clã dos Zeraítas; de Saul, o clã dos Saulitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Esses eram os clãs descendentes de Simeão, foram contados vinte e dois mil e duzentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Os clãs descendentes de Gade eram estes: de Zefom, o clã dos zefonitas; de Hagui, o clã dos hagitas; de Suni, o clã do sunitas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'de Ozni, o clã dos oznitas; de Eri, o clã dos eritas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'de Arode, o clã dos aroditas; de Areli, o clã dos arelitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Esses eram os clãs descedentes de Gade, foram contados quarenta mil e quinhentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Os filhos de Judá eram Er e Onã, mas esses homens morreram na terra de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Os clãs dos outros descendentes de Judá eram estes: de Selá, o clã de selanitas; de Perez, o clã de perezitas; e de Zerá, o clã dos zeraítas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Os descendentes de Perez eram estes: de Hezrom, o clã dos hezronitas; de Hamul, o clã dos hamulitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Esses eram os clãs dos descendentes de Judá, foram contados setenta e seis mil e quinhentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Os clãs dos descendentes de Issacar eram estes: de Tola, o clã de Tolaítas; de Puá, o clã dos Punitas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'de Jasube, o clã dos Jasubitas; de Sinrom, o clã dos Sinronitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Esses eram os clãs de Issacar, foram contados sessenta e quatro mil e trezentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Os clãs de descendentes de Zebulom eram estes: de Serede, o clã dos sereditas; de Elom, o clã dos elonitas; de Jaleel, o clã dos jaleelitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Esses eram os clãs dos zebulonitas, foram contados sessenta mil e quinhentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Os clãs de descendentes de José eram Manassés e Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Os descendentes de Manassés eram estes: de Maquir, o clã dos maquiritas (Maquir foi o pai de Gileade); de Gileade, o clã dos gileaditas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Os descendentes de Gileade eram estes: de lezer, o clã dos iezeritas; de Heleque, o clã dos helequitas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'de Asriel, o clã dos asrielitas; de Siquém, o clã dos siquemitas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'de Semida, o clã dos semidaítas; de Hefer, o clã dos heferitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Zelofeade, filho de Héfer, não teve filhos, apenas filhas. Os nomes de suas filhas eram Macla, Noa, Hogla, Milca e Tirza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Esses foram os clãs de Manassés, foram contados cinquenta e dois mil e setecentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Os clãs dos descendentes de Efraim foram estes: De Sutela, o clã dos sutelaítas; de Bequer, o clã dos bequeritas; de Taã, o clã dos taanitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Os descendentes de Sutela foram, de Erã, o clã dos eranitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Esses foram os clãs dos descendentes de Efraim, foram contados trinta e dois mil e quinhentos homens. Esses foram os descendentes de José, contados em cada um dos seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Os clãs dos descendentes de Benjamim foram estes: de Belá, o clã dos belaítas; de Asbel, o clã dos asbelitas; de Airã, o clã dos airamitas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'de Sufã, o clã dos sufamitas; de Hufã, o clã dos hufamitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Os filhos de Belá eram Arde e Naamã. De Arde, veio o clã dos arditas, e, de Naamã, veio o clã dos naamanitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Esses foram os clãs dos descendentes de Benjamim. Foram contados quarenta e cinco mil e seiscentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Os clãs dos descendentes de Dã eram, de Suão, os clãs dos suamitas. Esses foram os clãs dos descendentes de Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Todos os clãs dos suamitas foram contados sessenta e quatro mil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Os clãs dos descendentes de Aser foram estes: de Imna, o clã dos imnaítas; de Isvi, o clã dos isvitas; de Berias, o clã dos beriaítas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Os descendentes de Berias foram estes: de Héber, o clã dos heberitas; de Malquiel, o clã dos malquielitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'O nome da filha de Aser era Sera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Esses foram os clãs dos descendentes de Aser, foram contados cinquenta e três mil e quatrocentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Os clãs dos descendentes de Naftali foram estes: de Jazeel, o clã dos jazeelitas; de Guni, o clã dos gunitas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'de Jezer, o clã dos jezeritas; de Silém, o clã dos silemitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Esses foram os clãs dos descendentes de Naftali, foram contados quarenta e cinco mil e quatrocentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Esta foi a conta completa dos homens entre o povo de Israel: seiscentos e um mil, setecentos e trinta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Yahweh falou com Moisés e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, '\"A terra será dividida entre estes homens como uma herança de acordo com o número dos seus nomes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Para os clãs maiores, vós dareis maior herança, e, para os menores, dareis menor herança. Para toda família, dará uma herança de acordo com o número de homens que foram contados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Entretanto, a terra será dividida em lotes aleatórios. Eles herdarão a terra conforme a divisão feita entre as tribos dos antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'A herança deles será dividida entre os grandes e pequenos clãs, distribuídas para eles em lotes aleatórios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Os clãs dos levitas, contado clã por clã, foram estes: de Gérson, o clã dos gersonitas; de Coate, o clã dos coatitas; de Merari, o clã dos meraritas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Os clãs de Levi foram estes: o clã dos libnitas; o clã dos hebronitas; o clã dos malitas; o clã dos musitas; o clã dos coraítas. Coate era o antepassado de Anrão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'O nome da esposa de Anrão era Joquebede, uma descendente de Levi, que nasceu dos levitas no Egito. Ela deu à luz aos filhos de Anrão, que eram Arão, Moisés e Miriã, irmã deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'De Arão, nasceram Nadabe e Abiú, Eleazar e Itamar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Nadabe e Abiú morreram quando eles ofereceram fogo estranho diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Os homens que foram contados entre os levitas totalizaram vinte três mil, todos homens com um mês de idade pra cima. Mas eles não foram contados entre os descendentes de Israel porque não lhes foi dada herança entre o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Estes são os que foram contados por Moisés e pelo sacerdote Eleazar. Eles contaram o povo de Israel nas planícies de Moabe, junto ao Jordão em Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Mas, entre eles, não havia nenhum homem que havia sido contado por Moisés e pelo sacerdote Arão quando os descendentes de Israel foram contados no deserto de Sinai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Pois Yahweh dissera que todo aquele povo certamente morreria no deserto. Não foi deixado nenhum homem entre eles, exceto Calebe, filho de Jefoné, e Josué, filho de Num.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Então vieram a Moisés as filhas de Zelofeade, filho de Héfer, filho de Gileade, filho de Maquir, filho de Manassés, do clã de Manassés, filho de José. Estes eram os nomes de suas filhas: Macla, Noa, Hogla, Milca e Tirza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Elas ficaram diante de Moisés, do sacerdote Eleazar, dos líderes e diante de toda comunidade, na entrada da Tenda do Encontro. Elas disseram:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, '\"Nosso pai morreu no deserto. Ele não estava entre aqueles que conspiraram contra Yahweh na companhia de Coré. Ele morreu por seu próprio pecado, e não teve filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Por que o nome de nosso pai deveria ser tirado de seu clã por ele não ter tido nenhum filho? Dá-nos terra entre os parentes de nosso pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Então, Moisés levou o caso delas diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, '\"As filhas de Zelofeade estão falando corretamente. Tu certamente darás terra a elas, como uma herança entre os parentes de seu pai. E te certifica de que a herança de seu pai passe para elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Tu falarás com o povo de Israel, dizendo: \'Se um homem morrer e não tiver filhos, então vós garantireis que sua herança passe para sua filha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Se ele não tiver filha, então vós dareis sua herança ao seus irmãos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'se ele não tiver irmãos, então dareis sua herança para os irmãos de seu pai;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'se o seu pai não tiver irmãos, então dareis sua herança para o parente mais próximo em seu clã, e ele a tomará para si. Esta será uma lei estabelecida por decreto para o povo de Israel, como Yahweh ordenou a mim\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Yahweh disse a Moisés: \"Sobe às montanhas de Abarim e olha para a terra que Eu dei ao povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Depois de vê-la, tu também serás reunido ao teu povo, assim como o teu irmão Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Isto acontecerá porque vós vos rebelastes contra Meu comando no deserto de Zim. Lá, quando a água fluiu da rocha, em vossa ira, vós falhastes em honrar Minha santidade diante dos olhos de toda a comunidade\". Estas são as águas de Meribá de Cades no deserto de Zim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Então, Moisés falou com Yahweh e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, '\"Que Tu, Yahweh, Deus dos espíritos de toda a humanidade, aponte um homem sobre a comunidade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'um homem que saia e entre diante deles e os conduza para fora e os traga para dentro, para que Tua comunidade não seja como ovelhas que não têm pastor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Yahweh disse a Moisés: \"Toma Josué, filho de Num, um homem em quem Meu Espírito vive, e impõe tua mão sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Apresenta-o diante do sacerdote Eleazar e diante de toda a comunidade, e ordena-o diante de seus olhos para liderá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Tu colocarás parte de tua autoridade sobre ele, para que toda a comunidade do povo de Israel lhe obedeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Ele irá diante do sacerdote Eleazar para buscar Minha vontade para ele, pelas decisões de Urim. Será pelo comando de Josué que o povo sairá e entrará, ambos, ele e todo o povo de Israel com ele, toda a comunidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Então, Moisés fez como Yahweh lhe ordenara. Ele levou Josué e o colocou diante do sacerdote Eleazar e toda a comunidade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'impôs suas mãos sobre ele e ordenou-lhe para liderar, assim como Yahweh lhe ordenara fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Yahweh falou para Moisés e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, '\"Ordena ao povo de Israel e dize-lhes: \'Oferecei sacrifícios a Mim no tempo designado; a comida para Minhas ofertas queimadas de aroma agradável para Mim\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Tu também lhes dirás: \'Esta é a oferta queimada que vós oferecereis para Yahweh: dois cordeiros machos de um ano de idade, sem defeito, todos os dias, como um holocausto contínuo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Oferecei um cordeiro pela manhã, e o outro cordeiro ao entardecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Oferecei a décima parte de um efa da melhor farinha, como a oferta de cereais, misturado com um quarto de um him de azeite batido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Esse é o holocausto contínuo que foi ordenado no monte Sinai como aroma agradável, uma oferta queimada para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'A oferta de bebida será um quarto de um him para um dos cordeiros. Derramai, no lugar sagrado, uma oferta de bebida forte para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Oferecei o outro cordeiro ao entardecer, com uma oferta de cereais, como as oferecidas pela manhã. Oferecei também uma oferta de bebida com isso, uma oferta queimada, de aroma agradável para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'No dia de Sábado, oferecei dois cordeiros machos, de um ano de idade cada, sem defeito, e dois décimos de um efa da melhor farinha, como uma oferta de cereais, misturada com azeite, juntamente com a oferta de bebida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Esse será o holocausto de todo sábado, além do holocausto contínuo e a oferta de bebida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'No início de cada mês, oferecei um holocausto para Yahweh. Oferecei dois novilhos, um carneiro, e sete cordeiros machos de um ano de idade, sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'Oferecei também três décimos de um efa da melhor farinha, como oferta de cereais, misturada com azeite para cada novilho, e dois décimos da melhor farinha, como oferta de cereais, misturada com azeite para cada carneiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'Oferecei também um décimo de um efa da melhor farinha, misturada com azeite, como oferta de cereais para cada cordeiro. É holocausto de aroma agradável; oferta queimada a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'A oferta de bebida do povo será metade de um him de vinho para um novilho, um terço de um him para um carneiro, e um quarto de um him para um cordeiro. Essa será a oferta queimada, para todo mês de todos os meses do ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Como oferta pelo pecado, oferecei um bode a Yahweh. Esse será um acréscimo ao holocausto contínuo e à oferta de bebida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Durante o primeiro mês, no décimo quarto dia do mês, acontece a Páscoa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'No décimo quinto dia desse mês haverá um banquete. Por sete dias, comei pão sem fermento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'No primeiro dia, haverá uma reunião santa para honrar Yahweh. Não fareis nenhum trabalho nesse dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Porém, oferecei uma oferta queimada em holocausto a Yahweh. Oferecei dois novilhos, um carneiro, e sete cordeiros machos de um ano de idade, sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Oferecei, junto com o novilho, oferta de cereais de três décimos de um efa da melhor farinha, misturada com azeite e dois décimos junto com o carneiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Para cada um dos sete cordeiros, oferecei um décimo de um efa da melhor farinha, misturada com azeite,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'e um bode como uma oferta pelo pecado para fazer expiação por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Essas coisas oferecei além do holocausto da manhã, que é o holocausto contínuo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Assim, oferecei esses sacrifícios diariamente, durante os sete dias da Páscoa, a comida de oferta queimada de aroma agradável a Yahweh. Isso deve ser oferecido em acréscimo ao holocausto contínuo junto com a oferta de bebida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'No sétimo dia, farei vós uma santa convocação para honrar Yahweh, e vós não trabalheis nesse dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Além disso, no dia das primícias, quando vós oferecerdes uma nova oferta de cereais para Yahweh na vossa Festa das Semanas, tereis santa convocação para honrar Yahweh, e não fareis nenhum trabalho nesse dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Oferecei uma oferta queimada de aroma agradável para Yahweh. Oferecei dois novilhos, um carneiro, e sete cordeiros machos de um ano de idade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'Oferecei também oferta de cereais para acompanhar: da melhor farinha misturada com azeite, três décimos de um efa da melhor farinha misturada com azeite para cada novilho e dois décimos para um carneiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Oferecei um décimo de um efa da melhor farinha misturada com azeite para cada um dos sete cordeiros,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'e um bode para fazer expiação por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Quando vós oferecerdes esses animais sem defeitos, junto com as ofertas de bebida, isso será um acréscimo ao holocausto contínuo e à oferta de cereais\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, '\"No primeiro dia do sétimo mês, vós tereis uma santa assembleia em honra a Yahweh. Não fareis trabalho regular neste dia, será para vós um dia com toque de trombetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Oferecei a Yahweh uma oferta queimada, produzida com aroma suave; um novilho, um carneiro e sete cordeiros machos com um ano de idade, cada um deles sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'Oferecei, juntamente com estes, a oferta de cereais da melhor farinha fina misturada com azeite, três décimos de efa para o novilho, dois décimos para o carneiro;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'e um décimo para cada um dos sete cordeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Oferecei um bode como oferta para expiação do vosso pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Consagrai essas ofertas no sétimo mês, incluindo todas as ofertas que fareis no primeiro dia de cada mês: a oferta queimada especial e a oferta dos grãos acompanharão essas ofertas. A oferta queimada, os grãos e bebidas ofertadas serão incluídas de forma regular. Assim como foi feito com as ofertas, vós obedecereis o que foi decretado para produzir um aroma suave, como oferta queimada a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'No décimo dia do sétimo mês, realizai uma santa assembleia em honra de Yahweh, humilhai-vos e não trabalheis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Oferecei uma oferta queimada para produzir um aroma suave a Yahweh. Oferecei um novilho, um carneiro e sete cordeiros machos de um ano de idade. Cada um deles será sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Oferecei com eles a oferta de grãos, da melhor farinha misturada com azeite, três décimos de efa para o novilho, dois décimos para o carneiro');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'e, para os sete cordeiros, um décimo de efa para cada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Oferecei um bode macho. Isso será incluído na oferta pelo pecado para fazer a expiação, uma oferta queimada contínua, com a oferta de grãos e as ofertas de bebidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'No décimo quinto dia do sétimo mês, realizai uma santa assembleia em honra de Yahweh. Não façais trabalho regular e mantende uma festa a Ele por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Oferecei uma oferta queimada, um sacrifício queimado para produzir um aroma suave a Yahweh. Oferecei treze novilhos, dois carneiros e quatorze cordeiros de um ano de idade. Cada um será sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Oferecei, juntamente com estes, uma oferta de grãos, a flor da farinha misturada com azeite, três décimos de efa para cada um dos treze novilhos, dois décimos para cada um dos dois carneiros,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'e um décimo de efa para cada um dos catorze cordeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'Oferecei um bode como oferta pelo pecado em adição à oferta queimada regular, sua oferta de cereais e a oferta de bebidas oferecidas juntamente com essa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'No segundo dia da assembleia, oferecei doze novilhos, dois carneiros e quatorze cordeiros machos de um ano de idade, cada um sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'Trazei com eles uma oferta de cereais e de bebidas oferecidas com os novilhos, os carneiros e os cordeiros, fazendo tantas ofertas quanto ordenadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'Oferecei um bode macho como oferta pelo pecado incluindo a contínua oferta queimada, a oferta de grão e as ofertas de bebidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'No terceiro dia da assembleia, oferecei onze novilhos, dois carneiros, e quatorze cordeiros machos de um ano de idade, cada um sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'Fazei também uma oferta de grãos e de bebidas oferecidas com os novilhos, os carneiros e os cordeiros, fazendo tantas ofertas quanto ordenadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'Oferecei um bode macho como oferta pelo pecado, incluindo a contínua oferta queimada, a oferta de grãos e as ofertas de bebidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'No quarto dia da assembleia, oferecei dez novilhos, dois carneiros e quatorze cordeiros machos de um ano de idade, cada um sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'fazei também uma oferta de grãos e de bebidas oferecidas com os novilhos, os carneiros e os cordeiros, fazendo tantas ofertas quanto ordenadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'Oferecei um bode macho como oferta pelo pecado incluindo a contínua oferta queimada, a oferta de grão e as ofertas de bebidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'No quinto dia da assembleia, oferecei nove novilhos, dois carneiros e quatorze cordeiros machos de um ano de idade, cada um sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'Fazei, com eles, uma oferta de grãos e de bebidas oferecidas com os novilhos, os carneiros e os cordeiros, fazendo tantas ofertas quanto ordenadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'Oferecei um bode macho como oferta pelo pecado incluindo a contínua oferta queimada, a oferta de grãos e as ofertas de bebidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'No sexto dia da assembleia, oferecei oito novilhos, dois carneiros e quatorze cordeiros machos de um ano de idade, cada um sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'Fazei, com eles, uma oferta de grãos e de bebidas oferecidas com os novilhos, os carneiros e os cordeiros, fazendo tantas ofertas quanto ordenadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'Oferecei um bode macho como oferta pelo pecado incluindo a contínua oferta queimada, a oferta de grãos e as ofertas de bebidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'No sétimo dia de assembleia, oferecei sete novilhos, dois carneiros e quatorze cordeiros machos de um ano de idade, cada um sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'Fazei, com eles, uma oferta de grãos e de bebidas oferecidas com os novilhos, os carneiros e os cordeiros, fazendo tantas ofertas quanto ordenadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'Oferecei um bode macho como oferta pelo pecado, incluindo a contínua oferta queimada, a oferta de grãos e as ofertas de bebidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'No oitavo dia, tereis uma outra assembleia solene. Não façais trabalho regular.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Oferecei uma oferta queimada, para produzir um aroma suave a Yahweh. Oferecei um novilho, um carneiro e sete cordeiros machos com um ano de idade, cada um sem defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Fazei, juntamente com eles, uma oferta de grãos e de bebidas oferecidas com os novilhos, com os carneiros e com os cordeiros, fazendo tantas ofertas quanto ordenadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'Oferecei um bode macho como oferta pelo pecado incluindo a contínua oferta queimada, a oferta de grão e as ofertas de bebidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'São esses que vós oferecereis a Yahweh na festas fixas. Incluí vossos votos e ofertas voluntárias, assim como as vossas ofertas queimadas, grãos ofertados, bebidas ofertadas e ofertas pacíficas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'Moisés disse ao povo de Israel tudo aquilo que Yahweh havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Moisés falou aos líderes das tribos do povo de Israel, dizendo: \"Isto é o que Yahweh ordenou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Quando alguém fizer um voto a Yahweh, ou fizer um juramento ligado a uma promessa, não quebrará a sua palavra. Manterá sua promessa para fazer tudo o que disser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Quando uma jovem mulher, vivendo na casa de seu pai, fizer um voto a Yahweh e obrigar-se ao voto pela promessa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'e seu pai ouvir o voto e a promessa pela qual ela se obrigou, e se ele não disser nada em contrário, então os votos dela permanecerão válidos. Toda a promessa pela qual ela se obrigou permanecerá válida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Se o seu pai ouvir o seu voto ou a promessa, e não lhe disser nada em contrário, então todos os votos ou promessas que ela tiver feito permanecerão válidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Contudo, se ela casar-se enquanto estiver sob os votos ou promessas de seus lábios, pelos quais se comprometeu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'e o seu marido souber disso e não disser coisa alguma quando ouvi-la, então os votos e obrigações com os quais se comprometeu continuarão válidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Mas se o marido desaprová-la quando a ouvir, então ele cancelará os votos que ela tiver feito, a fala precipitada dos seus lábios pela qual ela se obrigou. Yahweh a liberará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Mas sobre a viúva ou a mulher divorciada, toda obrigação assumida por elas permanecerá válida contra ambas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'E se uma mulher casada fizer um voto, se ela se obrigar à promessa com juramento,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'e seu marido ficar sabendo disso e não desautorizá-la, se não cancelar o seu voto, então todos os seus votos serão válidos. Toda promessa pela qual ela se vinculou permanece válida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Mas se o marido, quando a ouvir, cancelar o que ela prometeu, então o que quer que seja, que terá sido dito pelos lábios dela, sobre os seus votos ou promessas não terá validade. Seu marido os terá cancelado. Yahweh a liberará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Todo voto ou promessa que uma mulher fizer e que a force a negar alguma coisa, pode ser confirmado ou cancelado pelo seu marido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Mas se ele não desautorizá-la no seu dia a dia, então, com isto, ele confirmará todas os votos e promessas que ela tiver feito. Ele as confirmou porque não lhe disse nada no tempo em que ele as ouviu sendo feitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'E se o seu marido tentar cancelar os votos da sua esposa muito tempo depois de ter ouvido essas promessas, então ele será responsável pelo pecado dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Estes são os estatutos que Yahweh ordenou a Moisés para lhes anunciar; estatutos estabelecidos entre um homem e sua esposa, e entre o pai e a sua filha, quando ela ainda está na sua juventude e na casa do seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Yahweh falou a Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, '\"Vinga o povo de Israel contra os midianitas. Após isso, morrerás e te reunirás ao teu povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Então Moisés falou ao povo, dizendo: \"Armai alguns de vossos homens para que saiam contra Midiã e executem a vingança de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Toda tribo dentro de Israel enviará mil soldados à guerra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Assim, dentre os milhares e milhares de homens de Israel, foram fornecidos mil de cada tribo para a guerra. Doze mil homens ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Então, Moisés os enviou para a batalha, mil de cada tribo, juntamente com Fineias, filho do sacerdote Eleazar, com alguns utensílios do Lugar Santo e trombetas em sua posse, para soar os alarmes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Guerrearam contra Midiã, como Yahweh havia ordenado a Moisés. Mataram todos os homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Juntamente com os outros mortos, mataram os reis de Midiã, Evi, Requém, Zur, Hur e Reba, os cinco reis de Midiã. Também mataram Balaão, filho de Beor, pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Os exércitos de Israel capturaram as mulheres de Midiã, suas crianças, todo o gado, rebanho e todos os seus bens. Levaram isso como despojos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Queimaram todas as suas cidades onde viviam, e todos os seus acampamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Levaram como despojos e prisioneiros, tanto as pessoas como os animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Trouxeram os prisioneiros e os despojos, as coisas capturadas a Moisés, ao sacerdote Eleazar e à comunidade do povo de Israel. Trouxeram isso ao acampamento na planície de Moabe, ao lado do Jordão, próximo a Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Moisés, o sacerdote Eleazar e todos os líderes da comunidade foram ao encontro deles fora do acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Mas Moisés estava irado com os oficiais do exército, os comandantes dos mil e os capitães de cem, que vieram da batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Moisés lhes disse: \"Deixastes todas as mulheres vivas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Vede, essas foram as mulheres que, por conselho de Balaão, fizeram com que o povo de Israel pecasse contra Yahweh no caso de Peor, quando a praga se espalhou entre a comunidade de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Agora, matai todos os meninos entre as crianças, e todas as mulheres que já dormiram com algum homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Mas tomai para si todas a moças que nunca dormiram com um homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Acampai do lado de fora do acampamento de Israel durante sete dias. Todos aqueles dentre vós que mataram alguém ou tocaram algum morto, deverão se purificar no terceiro dia e no sétimo dia, vós e vossos prisioneiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Purificai todo vestuário, tudo feito de couro de animal, pelo de bode e tudo que é feito de madeira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'O sacerdote Eleazar disse aos soldados que foram para a guerra: \"Esta é a lei decretada que Yahweh deu a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'o ouro, a prata, o bronze, o ferro, o latão e o chumbo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'e tudo que for resistente ao fogo, deverão passar pelo fogo. Então estarão puros. Depois, purificareis essas coisas com a água da purificação. Tudo aquilo que não puder ser passado pelo fogo deverá ser limpo com aquela água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Lavareis as vossas vestes no sétimo dia, e então ficareis limpos. Depois, podereis entrar no acampamento de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Então, Yahweh falou a Moisés dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, '\"Conta todos os despojos tomados, tanto de pessoas quanto de animais. Tu, com o sacerdote Eleazar, e os líderes da comunidade dos clãs dos antepassados');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'dividireis os despojos em duas partes, entre os soldados que saíram para a batalha, e todo o resto da comunidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Dos soldados que foram para a batalha, coleta um tributo a ser dado a Mim. Este tributo será um a cada quinhentos, dentre pessoas, gado, jumentos, ovelhas, ou bodes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Coleta este tributo da metade deles e o entrega ao sacerdote Eleazar, como uma oferta para ser apresentada a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Também da metade do povo de Israel, tu separarás um de cada cinquenta, dentre pessoas, gado, jumento, ovelhas, e bodes. Entrega-os aos levitas que cuidam do meu Tabernáculo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Então, Moisés e o sacerdote Eleazar fizeram como Yahweh havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Os despojos que restaram do que os soldados tomaram foram seiscentos e setenta e cinco mil ovelhas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'setenta e dois mil bois,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'sessenta e um mil jumentos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'e trinta e duas mil mulheres que nunca dormiram com homem algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'A metade que foi mantida com os soldados era em número de trezentos e trinta e sete mil ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'A parte de Yahweh dentre as ovelhas foi seiscentos e setenta e cinco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Os bois eram trinta e seis mil, dos quais o tributo a Yahweh foi setenta e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Os jumentos eram trinta mil e quinhentos, dos quais a parte a Yahweh foi sessenta e um.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'As pessoas eram dezesseis mil mulheres, das quais o tributo a Yahweh foi trinta e duas pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Moisés tomou o tributo para ser uma oferta apresentada a Yahweh. Ele a entregou ao sacerdote Eleazar, como Yahweh ordenara Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Quanto à metade do povo de Israel que Moisés havia tomado dos soldados que tinham ido para a guerra:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'a metade da comunidade era de trezentas e trinta e sete mil e quinhentas ovelhas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'trinta e seis mil bois,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'trinta mil e quinhentos jumentos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'e dezesseis mil mulheres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Da metade do povo de Israel, Moisés tomou um de cada cinquenta, tanto de pessoas quanto de animais. Ele os entregou aos levitas que cuidavam do tabernáculo de Yahweh, assim como Yahweh lhe ordenara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Então os oficiais do exército, os comandantes de mil, e os capitães de cem, vieram a Moisés,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'e disseram-lhe: \"Os teus servos contaram os soldados que estavam sob o nosso comando, e nenhum homem falta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Trouxemos a oferta para Yahweh, o que cada homem achou, artigos de ouro, pulseiras e braceletes, anéis, brincos e colares, para fazer expiação por nós diante de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Moisés e o sacerdote Eleazar receberam deles o ouro e todos os artigos trabalhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Todo o ouro da oferta que deram a Yahweh - as ofertas dos comandantes de mil e dos capitães de cem - pesava dezesseis mil setecentos e cinquenta siclos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Cada soldado tomou despojo, cada homem para si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Moisés e o sacerdote Eleazar tomou o ouro dos comandantes de mil e dos capitães de cem. Eles o levaram para a Tenda do Encontro, como memorial do povo de Israel para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Os descendentes de Rúben e de Gade possuíam um grande número de gado. Quando eles viram que as terras de Jazer e de Gileade eram propícias para o gado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'foram a Moisés, ao sacerdote Eleazar e aos líderes da comunidade e lhes disseram:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, '\"Atarote, Dibom, Jazer, Ninra, Hesbom, Eleale, Sebã, Nebo e Beom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'estas terras que Yahweh conquistou perante a comunidade de Israel, são propícias para o gado. Nós, teus servos, temos uma grande quantidade de gado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Disseram: \"Se nós encontramos favor aos teus olhos, permitas que estas terras sejam entregues a vossos servos, como posse. Não nos façais atravessar o Jordão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Moisés respondeu aos descendentes de Gade e Rúben: \"Deveriam teus irmãos irem à guerra enquanto vos estabeleceis aqui?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Por que desencorajais o coração do povo de Israel para que não entrem na terra que Yahweh lhes entregou?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Vossos pais fizeram a mesma coisa quando os enviei de Cades-Barneia para examinar a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Quando eles foram até o vale de Escol e viram a terra, desencorajaram o coração do povo de Israel para que não entrasse na terra que Yahweh lhes havia dado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Então, a ira de Yahweh se acendeu naquele dia e Ele jurou dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, '\'Certamente, nenhum dos homens que saíram do Egito, com vinte anos para cima verá a terra que Eu jurei a Abraão, a Isaque e a Jacó, porque eles não Me seguiram fielmente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Exceto Calebe, filho de Jefoné, o quenezeu, e Josué, filho de Num. Somente Calebe e Josué, porque perseveraram em Me seguir\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Então, a ira de Yahweh se acendeu contra Israel. Ele os fez peregrinar errantes pelo deserto por quarenta anos, até que toda aquela geração que havia cometido o mal aos Seus olhos fosse destruída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Agora, levantastes no lugar de vossos pais, como uma geração de homens pecadores para aumentar ainda mais a ardente ira de Yahweh contra Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Se vós deixardes de segui-Lo, Ele novamente abandonará Israel no deserto e vós sereis o motivo da destruição de todo este povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Então, eles se aproximaram de Moisés e disseram: \"Permita-nos construir currais para nosso gado e cidades para nossas famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Porém, nós nos armaremos e iremos com o exército de Israel até o deixarmos em seu lugar. Mas nossas famílias viverão nas cidades fortificadas, devido aos habitantes que ainda residem nesta terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Nós não retornaremos às nossas casas até que cada homem do povo de Israel tenha obtido a sua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Nós não herdaremos a terra com eles do outro lado do Jordão, pois a nossa herança é aqui no oriente do Jordão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Então, Moisés respondeu-lhes: \"Se vós fizerdes o que dizeis, se vos armardes para a guerra perante Yahweh');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'e cada um de vós atravessardes o Jordão, armados perante Yahweh, até que Ele tenha removido todos os Seus inimigos diante de Si,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'e a terra esteja submetida a Yahweh, só então podereis voltar. E vós estareis sem culpa perante Yahweh e Israel. Esta terra será vossa perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Entretanto, se não fizerdes isso, pecareis contra Yahweh. Estai certos de que vosso pecado vos achará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Edificai cidades para vossas famílias e currais para as vossas ovelhas e fazei aquilo que prometestes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Os descendentes de Gade e de Rúben disseram a Moisés: \"Teus servos farão o que tu, nosso senhor, ordena.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Nossas crianças, nossas mulheres, nossos rebanhos e todo nosso gado permanecerão nas cidades de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Porém, nós, teus servos, atravessaremos perante Yahweh para a batalha; todo homem que estiver preparado para a guerra, como tu, nosso senhor, dizes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Então, Moisés deu instruções a respeito deles ao sacerdote Eleazar, e Josué, filho de Num, e também aos líderes dos clãs de seus antepassados das tribos do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Moisés lhes disse: \"Se os descendentes de Gade e Rúben atravessarem o Jordão convosco, todo homem armado para a guerra perante Yahweh, e, se a terra estiver subjugada, então, lhes darei a terra de Gileade como posse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Porém, se não atravessarem o Jordão armados convosco, então, adquirirão suas posse entre vós na terra de Canaã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Os descendentes de Gade e Rúben responderam: \"Conforme o que Yahweh nos disse, nós o faremos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Nós atravessaremos o Jordão perante Yahweh para a terra de Canaã, mas a nossa herança será deste lado do Jordão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Assim, aos descendentes de Gade e de Rúben e à metade da tribo de Manassés, filho de José, Moisés entregou o reino de Siom, o reino dos amorreus e o reino de Ogue, rei de Basã. Ele lhes entregou a terra, e distribuiu todas as suas cidades, suas fronteiras e as cidades ao redor deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Os descendentes de Gade reconstruíram Dibom, Atarote, Aroer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atarote-Sofã, Jazer, Jogbeá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Bete-Ninra e Bete-Harã, como cidades fortificadas. Além disso, também construíram currais para suas ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Os descendentes de Rúben reconstruíram Hesbom, Eleale, e Quiriataim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebo, Baal-Meom (seus nomes foram posteriormente alterados) e Sibma. Eles deram outros nomes para as cidades que construíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Os descendentes de Maquir, filho de Manassés, foram a Gileade e a conquistaram dos amorreus que habitavam ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Então, Moisés entregou Gileade a Maquir, filho de Manassés, e os seus descendentes habitaram ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Jair, filho de Manassés, conquistou as cidades da região e as chamou de Havote-Jair.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Nobá conquistou Quenate e seus vilarejos e os chamou de Nobá, segundo seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Estas foram as caminhadas do povo de Israel depois de deixarem a terra do Egito, segundo seus exércitos, sob a liderança de Moisés e Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Moisés registrou os lugares de onde partiram e para onde foram, como Yahweh ordenou. Estas eram suas caminhadas, partida após partida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Viajaram de Ramessés durante o primeiro mês, saindo no décimo quinto dia. Na manhã seguinte da Páscoa, o povo de Israel partiu corajosamente, à vista de todos os egípcios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Isso ocorreu enquanto os egípcios estavam enterrando todos os seus primogênitos, aqueles a quem Yahweh havia matado, depois de executar juízos também contra os seus deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'O povo de Israel saiu de Ramessés e acampou em Sucote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Saíram de Sucote e acamparam em Etã, nos limites do deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Saíram de Etã e voltaram para Pi-Hairote, que está oposta a Baal-Zefom, onde acamparam próximo de Migdol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Então, saíram de Pi-Hairote e atravessaram pelo meio do mar, em direção ao deserto. Viajaram três dias pelo deserto de Etã e acamparam em Mara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Saíram de Mara e chegaram a Elim. Em Elim, havia doze fontes de água e setenta palmeiras. Ali foi onde acamparam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Saíram de Elim e acamparam junto ao mar Vermelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Saíram do mar Vermelho e acamparam no deserto de Sim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Saíram do deserto de Sim e acamparam em Dofca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Saíram de Dofca e acamparam em Alus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Saíram de Alus e acamparam em Refidim, onde não foi encontrada nenhuma água para o povo beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Saíram de Redifim e acamparam no deserto do Sinai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Saíram do deserto do Sinai e acamparam em Quibrote-Hataavá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Saíram de Quibrote-Hataavá e acamparam em Hazerote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Saíram de Hazerote e acamparam em Ritmá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Saíram de Ritmá e acamparam em Rimom-Perez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Saíram de Rimom-Perez e acamparam em Libna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Saíram de Libna e acamparam em Rissa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Saíram de Rissa e acamparam em Queelata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Saíram de Queelata e acamparam no monte Sefer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Saíram do Monte Sefer e acamparam em Harada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Saíram de Harada e acamparam em Maquelote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Saíram de Maquelote e acamparam em Taate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Saíram de Taate e acamparam em Terá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Saíram de Terá e acamparam em Mitca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Saíram de Mitca e acamparam em Hasmona.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Saíram de Hasmona e acamparam em Moserote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Saíram de Moserote e acamparam em Bene-Jaacã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Saíram de Bene-Jaacã e acamparam em Hor-Gidgade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Saíram de Hor-Gidgade e acamparam em Jotbatá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Saíram de Jotbatá e acamparam Abrona.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Saíram de Abrona e acamparam em Eziom-Geber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Saíram de Eziom-Geber e acamparam no deserto de Zim, em Cades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Saíram de Cades e acamparam no Monte Hor, na fronteira da terra de Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Arão, o sacerdote, subiu ao Monte Hor, por ordem de Yahweh, e ali morreu, no quadragésimo ano, após a saída do povo de Israel da terra do Egito, no quinto mês, no primeiro dia do mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Arão estava com cento e vinte e três anos quando morreu no Monte Hor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'O Cananeu, rei de Arade, que vivia na região sul do deserto, na terra Canaã, ouviu sobre a vinda do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Saíram do Monte Hor e acamparam em Zalmona.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Saíram de Zalmona e acamparam em Punom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Saíram de Punom e acamparam em Obote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Saíram de Obote e acamparam em Ijé-Abarim, na fronteira de Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Saíram de Ijé-Abarim e acamparam em Dibom-Gade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Saíram de Dibom-Gade e acamparam em Almom-Diblataim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Saíram de Almom-Diblataim e acamparam nas montanhas de Abarim, em frente a Nebo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Saíram das montanhas de Abarim e acamparam nas planícies de Moabe, junto ao Jordão, em Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Acamparam no Jordão, de Bete-Jesimote até Abel-Sitim, nas planícies de Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Yahweh falou a Moisés na planície de Moabe junto ao Jordão em Jericó e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, '\"Fala ao povo de Israel e dize-lhes: \'Quando cruzardes o Jordão para entrardes na terra de Canaã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'expulsareis todos os moradores da terra de diante de vós. Destruireis todas as suas imagens esculpidas, todas as imagens fundidas e demolireis todos os seus santuários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'E tomai posse da terra e habitai nela, porque Eu vos tenho dado a terra para a possuirdes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Herdai a terra por sorte, de acordo com cada clã. Para os clãs maiores, dai um grande pedaço de terra, e, para os grupos pequenos, dai um pequeno pedaço de terra. Em quaisquer clãs que a sorte cair, a terra lhes pertencerá. Vós herdareis a terra de acordo com as tribos de vossos antecessores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Mas, se não expulsardes os moradores da terra de diante de vós, então, as pessoas que permitirdes ficar se tornarão como farpas nos vossos olhos e espinhos nas vossas costelas. Elas tornarão a vossa vida difícil onde vos instalardes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Então, o que Eu intento fazer com esse povo, Eu farei também a vós\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Yahweh falou a Moisés, dizendo-lhe:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, '\"Ordena ao povo de Israel e dize-lhes: \'Quando entrardes na terra de Canaã, a terra que pertencerá a vós, a terra de Canaã e suas fronteiras,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'a fronteira sul se extenderá desde o deserto de Zim, ao longo de Edom. O extremo leste da fronteira sul será uma linha que terminará no extremo sul do mar Salgado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Vossa fronteira rodeará ao sul do monte de Acrabim e continuará através do deserto de Zim. De lá, irá ao sul de Cades-Barneia e continuará até Hazar-Hadar e seguirá até Azmom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'E dali, a fronteira irá até o ribeiro do Egito e seguirá até o mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'A fronteira oeste será no litoral do mar Grande. Essa será vossa fronteira oeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Vossa fronteira norte extenderá na linha que deve marcar o mar Grande até o monte Hor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'e do monte Hor até Lebo-Hamate, e dali até Zedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Então, a fronteira continuará até Zifrom, terminando em Hazer-Enã. Essa será vossa fronteira norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Então, demarcai vossa fronteira oriental de Hazar-Enã sul até Sefã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'A fronteira oriental descerá de Sefã até Ribla, ao oriente de Aim. A fronteira continuará ao longo do oriente do mar de Quinerete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Então, a fronteira continuará para o sul ao longo do rio Jordão para o mar Salgado e continuará para fronteira oriental do mar Salgado. Essa será tua terra, ao longo de todas as tuas fronteiras\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Então, Moisés ordenou ao povo de Israel, dizendo: \"Essa é a terra que recebereis por sorteio, que Yahweh ordenara, que se desse às nove tribos e meia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'a tribo dos descendentes de Rúben, a tribo dos descendentes de Gade, e a meia tribo de Manassés, segundo a designação de propriedade para tribo de seus antepassados, já haviam recebido sua terra, segundo a designação de propriedade para a tribo de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Isto é, as duas tribos e meia já receberam sua porção de terra, além do Jordão, do lado oriental de Jericó, em direção ao amanhecer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Yahweh falou com Moisés, dizendo-lhe:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, '\"Estes são os nomes dos homens que dividirão a terra para tua herança: Eleazar, o sacerdote, e Josué, filho de Num.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Tu escolherás um líder de cada tribo para dividir a terra para seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Estes são os nomes dos homens: da tribo de Judá, Calebe, filho de Jefoné.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Da tribo dos descendentes de Simeão, Semuel, filho de Amiúde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Da tribo de Benjamim, Elidá, filho de Quislom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Da tribo dos descendentes de Dã, o líder Buqui, filho de Jogli.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Dos descendentes de José, da tribo dos descendentes de Manassés, o líder Haniel, filho de Éfode.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Da tribo dos descendentes de Efraim, o líder Quemuel, filho de Siftã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Da tribo dos descendentes de Zebulom, o líder Elizafã, filho de Parnaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Da tribo dos descendentes de Issacar, o líder Paltiel, filho de Azã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Da tribo dos descendentes de Aser, o líder Aiude, filho de Selomi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'Da tribo dos descendentes de Naftali, o líder Pedael, filho de Amiúde\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Yahweh ordenou a esses homens que dividissem a terra de Canaã e entregassem a cada tribo de Israel sua porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Yahweh falou a Moisés nas planícies de Moabe, junto ao Jordão, em Jericó, e disse-lhe:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, '\"Manda o povo de Israel dar algumas de suas próprias terras aos levitas. Eles lhes darão cidades para habitar e pastagens em torno delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Os levitas habitarão nelas e as pastagens serão para seu gado, rebanhos, e todos os animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'As pastagens se estenderão dos muros das cidades por mil côvados, em todas as direções.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Medi vós dois mil côvados de fora da cidade no lado leste, e dois mil côvados no lado sul, dois mil côvados no lado oeste, e dois mil côvados no lado norte. Estas serão as pastagens para as cidades. As cidades estarão no centro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Seis das cidades que serão entregues aos levitas, servirão de cidades de refúgio. Vós deveis fornecê-las como lugares em que o homicida possa se proteger. Também forneçam quarenta e duas outras cidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'As cidades que serão dadas aos levitas serão, no total, quarenta e oito. Vós lhes dareis as pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'As maiores tribos do povo de Israel, as tribos que têm mais terra, devem fornecer mais cidades. As menores tribos fornecerão poucas cidades. Cada tribo deve fornecer aos levitas de acordo com o que receber\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Então, Yahweh falou a Moisés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, '\"Fala ao povo de Israel: \'Quando vós atravessardes o Jordão até a terra de Canaã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'escolhereis cidades para servirem de refúgio, para que qualquer homem que mate alguém involuntariamente possa proteger-se nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Estas cidades serão para vós refúgio do vingador, para que o homem acusado não seja morto sem antes ser julgado perante a comunidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Escolhei vós seis cidades como cidades de refúgio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Vós fornecereis três cidades além do Jordão e três na terra de Canaã. Elas serão cidades de refúgio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Para o povo de Israel, para os estrangeiros, para qualquer um que esteja vivendo entre vós, essas seis cidades servirão como um refúgio a qualquer um que mate alguém involuntariamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Se algum homem for acusado de golpear sua vítima com um instrumento de ferro e esta vítima morrer, então, o acusado é, de fato, um assassino. Ele certamente morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Se um homem acusado golpear com uma pedra em suas mãos de maneira que possa matar a vítima, se a vítima morrer, então o acusado é, de fato, um assassino. Ele certamente morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Se o homem acusado golpear sua vítima com uma arma de madeira que possa matar a vítima, se esta morrer, então o acusado é, de fato, um assassino. Ele certamente morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'O vingador do sangue pode, ele mesmo, matar o assassino. Quando o encontrar, poderá matá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'E, se o homem acusado empurrar uma pessoa com ódio, ou jogar alguma coisa nela, enquanto se esconde para emboscá-la, de modo que a vítima morra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'ou se ele atacá-la com ódio, com suas mãos, de modo que a vítima morra, então o acusado que a atacou certamente morrerá. Ele é um assassino. O vingador do sangue pode matá-lo se o encontrar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Mas, se o homem acusado, de repente, empurrar a vítima sem ter ódio premeditado, ou jogar alguma coisa que acerte a vítima sem emboscada,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'ou se ele jogar uma pedra que poderia matar a vítima sem vê-la, então, o acusado não era inimigo da vítima; ele não estava tentando machucá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Neste caso, a comunidade julgará entre o acusado e o vingador do sangue com base nestas regras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'A comunidade resgatará o acusado do poder do vingador do sangue. A comunidade retornará o acusado à cidade do refúgio ao qual ele estava originalmente protegido. Ele viverá lá até a morte do atual sacerdote, o qual foi ungido com óleo sagrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Mas, se o homicida, a qualquer momento, for além do limite da cidade de refúgio para a qual ele fugiu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'e se o vingador do sangue encontrá-lo fora do limite da sua cidade de refúgio, e se o vingador matar o homicida, ele não será acusado de assassinato.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Isto porque o homicida deveria ter permanecido na cidade de refúgio até a morte do sacerdote. Depois da morte do sacerdote, o homicida deverá retornar à terra onde tem sua propriedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Essas leis serão estatutos para vós e para todas as gerações do seu povo, em todos os lugares em que viverem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Quem matar qualquer pessoa deverá ser morto, conforme testificado pelas palavras das testemunhas. Mas, a palavra de apenas uma testemunha não deve causar a morte de uma pessoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Também, vós não aceitareis resgate pela vida de um homem que é culpado de homicídio. Ele certamente será morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'E vós não aceitareis resgate por alguém que tenha ido para uma cidade de refúgio. Vós não deveis, desta maneira, permitir que ele resida em sua propriedade até que o sacerdote morra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Não poluireis, desta maneira, a terra em que estais vivendo, porque o sangue de homicida polui a terra. Não fareis nenhuma expiação na terra quando sangue for derramado, a não ser pelo sangue daquele que o derramou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Assim, vós não corrompereis a terra na qual habitais, porque Eu estou habitando nela. Eu, Yahweh, habito entre o povo de Israel\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Então, os líderes das famílias de seus antepassados, do clã de Gileade, filho de Maquir, filho de Manassés dos clãs dos descendentes de José, aproximaram-se e falaram diante de Moisés e dos líderes, que eram príncipes e chefes de famílias do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Eles disseram: \"Yahweh te ordenou, nosso mestre, compartilhar uma parte da terra, por porção ao povo de Israel. Tu fostes ordenado por Yahweh, para dar a parte de Zelofeade, nosso irmão, para suas filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Mas, se elas se casarem com homens de outras tribos, entre o povo de Israel, então, a porção da terra será removida da parte de nosso antepassado. E será acrescentada como parte da tribo a que se unirem. Neste caso, a parte será removida e diminuída de nossa herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'E, quando chegar o ano do Jubileu do povo de Israel, a parte delas será somada à herança da tribo a que pertencerem. Assim, a parte delas será tirada da herança da tribo de nossos antepassados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Moisés deu uma ordem ao povo de Israel, pela palavra de Yahweh. Ele disse: \"O que a tribo dos descendentes de José diz está certo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Isto é o que Yahweh ordenou a respeito das filhas de Zelofeade. Ele disse: \'Que elas se casem com quem escolherem, mas devem se casar somente com os da tribo de seu pai\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Nenhuma herança do povo de Israel deve mudar de uma tribo para outra. Cada tribo do povo de Israel continuará com a herança da tribo de seu antepassado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Cada mulher do povo de Israel que possuir herança de sua tribo, deve casar-se com alguém da família da tribo de seu pai. Assim, cada um entre o povo de Israel conservará herança de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'E nenhuma herança mudará de mãos, de uma tribo para outra. Cada uma das tribos do povo de Israel deve preservar a sua herança\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Assim, as filhas de Zelofeade fizeram como Yaweh havia ordenado a Moisés;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Macla, Tirza, Holga, Milca e Noa, filhas de Zelofeade, casaram-se com os descendentes de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Casaram-se com familiares dos filhos de Manassés, filho de José. Dessa forma, a herança delas continuou na tribo do clã de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'São essas as ordens e as leis que Yahweh deu ao povo de Israel, por intermédio de Moisés, nas planícies de Moabe, junto ao Jordão, em Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Estas são as palavras que Moisés disse a todo Israel, além do Jordão, no deserto, na planície do vale do rio Jordão, defronte de Sufe, entre Parã, Tofel, Labã, Hazerote e Di-Zaabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'São onze dias de viagem desde Horebe, pelo caminho do monte Seir para Cades-Barneia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Aconteceu que, no quadragésimo ano, no primeiro dia do décimo primeiro mês, Moisés falou ao povo de Israel, dizendo-lhes tudo que Yahweh havia ordenado com relação a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Isso foi depois que Yahweh atacou Siom, rei dos amorreus, que habitava em Hesbom, e Ogue, o rei de Basã, que habitava em Astarote, em Edrei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Além do Jordão, na terra de Moabe, Moisés começou a anunciar estas instruções, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, '\"Yahweh, nosso Deus, falou conosco em Horebe, dizendo: \'Vós habitastes tempo suficiente nesta colina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Levantai-vos e continuai a vossa jornada, e ide para a colina dos amorreus e a todos os lugares próximos na planície do vale do rio Jordão, nas colinas, na baixada, no Neguebe e na costa, na terra dos cananeus, e no Líbano, até o grande rio, o Eufrates.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Vede, eu coloquei esta terra diante de vós. Ide e tomai posse da terra que Yahweh jurou a vossos pais — a Abraão, Isaque e Jacó — para dar a eles e à sua descendência\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Eu vos falei naquele tempo, dizendo: \'Eu mesmo não sou capaz de conduzir-vos sozinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Yahweh, vosso Deus, multiplicou-vos, e, vede, sois hoje como as estrelas do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Que Yahweh, o Deus de vossos pais, vos faça mil vezes mais numerosos do que sois, e vos abençoe, como Ele prometeu!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Mas como posso eu, sozinho, carregar vossas cargas, vossos fardos e vossas disputas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Escolhei homens sábios, homens de entedimento e de boa reputação, tribo por tribo, e eu os farei líderes sobre vós\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Vós me respondestes, dizendo: \'Aquilo que disseste é bom para nós!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Então, eu tomei os líderes de vossas tribos, homens sábios e de boa reputação, e os fiz líderes sobre vós, capitães de mil, capitães de cem, capitães de cinquenta, capitães de dez, e oficiais, tribo por tribo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Eu ordenei vossos juízes naquele tempo, dizendo: \'Ouvi as disputas entre vossos irmãos, e julgai retamente entre um homem e seu irmão, e também o estrangeiro que está com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Vós não demonstrareis parcialidade para com ninguém em uma disputa; ouvireis o pequeno e o grande do mesmo modo. Não tereis medo de confrontar o homem, pois o julgamento é de Deus. A disputa que for muito difícil para vós, trareis a mim, e eu a ouvirei\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Eu vos ordenei, naquele tempo, todas as coisas que deveríeis fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Partimos de Horebe e passamos por todo aquele grande e terrível deserto que vistes, em nosso caminho pelas colinas dos amorreus, como Yahweh, nosso Deus, nos havia ordenado; e chegamos a Cades-Barneia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Eu vos disse: \'Viestes às colinas dos amorreus, as quais Yahweh, nosso Deus, nos deu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Yahweh, vosso Deus, colocou a terra diante de vós; subi, tomai posse, como vos disse Yahweh, Deus de vossos pais; não temais, nem fiqueis desencorajados\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Todos vós viestes até mim e dissestes: \'Enviemos alguns homens adiante de nós, para que observem a terra, e tragam-nos informações sobre a maneira como devemos atacar, e sobre as cidades que devemos atravessar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'A ideia agradou-me; escolhi doze homens dentre vós, um de cada tribo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'E eles foram subindo em direção às colinas, chegaram ao vale de Escol, e sondaram a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Tomaram alguns dos frutos da terra em suas mãos e os trouxeram até nós. Disseram: \'A terra que Yahweh, nosso Deus, nos dá, é boa\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Apesar disso, recusastes a subir, rebelando-vos contra a ordem de Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Vós murmurastes em vossas tendas, e dissestes: \'É porque Yahweh nos odeia, que nos trouxe da terra do Egito, para nos entregar nas mãos dos amorreus e nos destruir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Para onde iremos agora? Nossos irmãos nos fizeram perder a coragem, dizendo: \'Aquele povo é maior e mais alto do que nós; suas cidades são grandes e fortificadas até os céus; mais ainda, vimos lá os filhos dos anaqueus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Então, eu vos disse: \'Não vos atemorizeis, nem tenhais medo deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Yahweh, vosso Deus, que vai adiante de vós, lutará por vós, assim como fez no Egito, diante de vossos olhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'e também no deserto, onde vistes como Yahweh, vosso Deus, cuidou de vós, como um homem cuida de seu filho, até chegardes a este lugar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Mesmo assim, não acreditastes em Yahweh, vosso Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'que foi à vossa frente no caminho, pela noite como fogo, e como nuvem durante o dia, para achar-vos lugar para armardes a vossa tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Yahweh ouviu vossas palavras, indignou-se e jurou, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, '\'Certamente, nenhum dos homens desta geração perversa verá a boa terra que Eu jurei dar a seus antepassados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'exceto Calebe, filho de Jefoné; Ele a verá, e a terra que pisou, darei a ele e a seus filhos, pois ele perseverou em seguir a Yahweh\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Yahweh também indignou-se comigo por vossa causa, dizendo: \'Tu também não entrarás ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Josué, filho de Num, que está diante de ti como teu servo, ele ali entrará. Encoraja-o para que ele lidere Israel, a fim de tomar sua herança\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Vossas pequenas crianças, que vós dissestes que seriam vítimas, que hoje não possuem conhecimento do bem ou do mal, elas entrarão. Para elas, Eu a darei, e elas tomarão posse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Mas quanto a vós, dai meia volta, e levai vossa jornada ao deserto, pelo caminho para o mar Vermelho\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Então, respondestes e me dissestes: \'Nós pecamos contra Yahweh; nós subiremos e lutaremos, e seguiremos tudo que Yahweh, nosso Deus, nos ordenou que fizéssemos\'. Todos os homens no vosso meio tomaram vossas armas de guerra, e estáveis prontos para subir a montanha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Yahweh disse a mim: \'Dize-lhes: \'Não os ataqueis e não luteis, pois não estarei convosco, e vós sereis feridos por vossos inimigos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Eu falei convosco desta maneira, mas não me ouvistes. Vós vos rebelastes contra a ordem de Yahweh; fostes arrogantes e subistes a montanha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Mas os amorreus, que viviam naquela montanha, vieram contra vós, e vos perseguiram como fazem as abelhas, e vos atacaram de Seir até Hormá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Voltastes e lamentastes diante de Yahweh; mas Yahweh não deu ouvido ao vosso clamor, e não vos deu atenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Assim, ficastes em Cades muitos dias, ficando ali muito tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Então, retornamos e continuamos nossa jornada deserto adentro, pelo caminho do mar Vermelho, como Yahweh me tinha falado. Rodeamos o monte Seir por vários dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Yahweh falou a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, '\'Rodeaste esta montanha tempo suficiente; volta-te para o norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Ordena ao povo, dizendo: \'Passai pela fronteira de vossos irmãos, os descendentes de Esaú, que habitam em Seir. Eles terão medo de vós. Mas tende o cuidado');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'de não lutardes contra eles, porque não vos darei nada da terra deles, nem sequer o suficiente para a sola de um pé pisar, porque dei o monte Seir a Esaú como herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Comprareis comida deles com dinheiro, para que comais. Comprareis também água deles com dinheiro, para que bebais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Pois Yahweh, vosso Deus, tem vos abençoado em todo trabalho de vossas mãos e tem conhecido vossa caminhada por este grande deserto. Pois, nestes quarenta anos, Yahweh, vosso Deus, esteve convosco e nada vos faltou\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Então, passamos à distância de nossos irmãos, os descendentes de Esaú, que habitam em Seir, no caminho de Arabá, de Elate e de Ezion Geber. Voltamos e passamos pelo caminho do deserto de Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Yahweh me disse: \'Não incomodes Moabe e não lutes contra eles em batalha. Pois dele não te darei terra alguma por tua possessão, porque dei Ar para os descendentes de Ló, como sua possessão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(Habitaram anteriormente lá, os emins, povo numeroso e de grande estatura — tão altos quanto os anaqueus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'também considerados refains, como os anaqueus; mas os moabitas os chamavam de emins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Os horeus também viveram lá, anteriormente, mas os descendentes de Esaú os expulsaram. Destruíram-nos e habitaram em seu lugar, como Israel fez com a terra de sua possessão que Yahweh lhes deu).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, '\'Agora, levantai-vos e atravessai o ribeiro de Zerede\'. Atravessamos o ribeiro de Zerede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Os dias, desde que chegamos de Cades-Barneia até atravessarmos o ribeiro de Zerede, foram trinta e oito anos. Isto foi naquele tempo em que toda a geração de homens preparados para a batalha havia desaparecido daquele povo, assim como Yahweh havia prometido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Além disso, a mão de Yahweh era contra aquela geração, para destruir o povo até que desaparecesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Estas coisas aconteceram quando todo homem de guerra dentre o povo já havia morrido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Sobre isso, Yahweh me falou, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, '\'Passa hoje por Ar, fronteira de Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'Quando te aproximares dos amonitas, não os incomodes ou lutes com eles, pois não te darei terra alguma dos amonitas como possessão, porque tenho dado aos descendentes de Ló como possessão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Esta também é considerada terra dos refains. Os refains habitaram lá anteriormente, mas os amonitas os chamavam de zanzumitas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'um povo grande e numeroso, tão alto quanto os anaqueus. Mas Yahweh os destruiu diante dos amonitas e os sucederam e habitaram no seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Assim também, Yahweh fez ao povo de Esaú, que habita em Seir, quando destruiu os horeus de diante deles e os descendentes de Esaú os sucederam e habitaram em seu lugar até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Quanto aos caftoritas, que vieram de Caftor, destruíram os aveus, que habitavam em povoados de Gaza, e habitaram no lugar deles).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, '\'Agora, levanta-te, vai pelo caminho e atravessa o vale de Arnom; olha, tenho dado, em tuas mãos Siom, o amorreu, rei de Hesbon, e suas terras. Começa a possuí-las e luta contra eles em batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Hoje farei com que comecem a ter medo e terror de ti. Todo o povo, debaixo do céu inteiro, ouvirá notícias sobre ti e tremerá, e se angustiará por tua causa\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Enviei mensageiros do deserto de Quedemote para Siom, rei de Hesbom, com palavras de paz, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, '\'Deixa-me passar por tua terra. Irei somente pela estrada, não irei nem para direita e nem para a esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Tu me venderás comida por dinheiro, para que eu coma e me darás água por dinheiro, para que beba. Apenas deixa-me atravessar a pé,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'assim como os descendentes de Esaú, que habitam em Seir, e os moabitas, que habitam em Ar, fizeram por mim, até que eu passe o Jordão para a terra que Yahweh, nosso Deus, nos dá\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Mas Siom, rei de Hesbom, não nos deixou passar por ele, pois Yahweh, nosso Deus, endureceu a sua mente e fez o seu coração ficar obstinado, para que o derrotasse pelo Seu poder, como aconteceu hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Yahweh me disse: \'Olha, comecei a dar Siom e sua terra diante de ti, começa a possuí-la a fim de herdares a sua terra\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Então, Siom veio contra nós, ele e todo o povo para lutar em Jaza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Yahweh, nosso Deus, o entregou a nós e o derrotamos, o ferimos de morte, com seus filhos e todo o seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Tomamos todas as cidades naquele dia e destruímos completamente todos os habitantes, mulheres e crianças, não deixamos nenhum sobrevivente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Trouxemos somente o gado como despojo para nós mesmos, assim como os despojos das cidades que tomamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Desde Aroer, que esta à beira do vale de Arnom e da cidade que está no vale, todo o caminho até Gileade, não existia cidade alta demais para nós. Yahweh nosso Deus nos deu vitória sobre todos os nossos inimigos diante de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Não fomos à cidade dos descendentes de Amom, assim como à margem do ribeiro de Jaboque nem às cidades das colinas ou a qualquer lugar que Yahweh, nosso Deus, tivesse nos proibido de ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Depois, viramos e subimos o caminho de Basã. Ogue, rei de Basã, veio com todo o seu povo e atacou-nos, para lutar em Edrei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Então, disse-me Yahweh: \'Não o temas, porque Eu o entregarei em tuas mãos, ele e todo seu povo e sua terra. Farás a ele o mesmo que fizeste a Siom, rei dos amorreus, que habitava em Hesbom\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Assim, Yahweh, nosso Deus, nos deu vitória sobre Ogue, rei de Basã, e todo o seu povo foi posto sobre nosso controle. E nós os derrotamos até que não ficou sobrevivente algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Então, naquele tempo, conquistamos todas suas cidades, e nenhuma cidade ficou que não conquistássemos: sessenta cidades em, toda a região de Argobe, o reino de Ogue em Basã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Todas essas cidades eram protegidas por altos muros, portões e ferrolhos; além de muitas outras cidades sem muros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Nós as destruímos completamente, como fizemos a Siom, rei de Hesbom, matando todos, homens, mulheres e crianças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Porém, reservamos para nós todo o gado e o despojo das cidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Naquele tempo, tomamos a terra da mão de dois reis amorreus que estavam além do Jordão, desde o rio Arnom até o monte Hermom');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(monte Hermom, que os sidônios chamam Siriom, e os amorreus o chamam Senir);');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'e todas as cidades do planalto, todo Gileade, e todo Basã, todo o caminho para Salca e Edrei, cidades do reino de Ogue, em Basã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Apenas Ogue, rei de Basã, havia restado dos refains; sua cama de ferro, que possuía nove côvados de comprimento e quatro côvados de largura, (de acordo com a medida usada naquele tempo) estava em Rabá, onde habitavam os descendentes de Amom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Naquele tempo, tomamos posse desta terra. Dei aos rubenitas e gaditas a região desde de Aroer, perto do vale de Arnom, e a metade das colinas de Gileade com as suas cidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'O resto de Gileade e toda região de Basã, o reino de Ogue, isto é, toda a região de Argobe e todo Basã dei à meia-tribo de Manassés. (Este território era chamado de terra dos refains.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, um descendente de Manassés, conquistou toda a região de Argobe até a fronteira com os gesuritas e os maacatitas. Ele chamou essa região, incluindo Basã, por seu próprio nome, Havote-Jair, até o dia de hoje).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'E para Maquir, dei Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Aos rubenitas e aos gaditas, dei o território de Gileade até o vale de Arnom, tanto o meio do vale como a fronteira do território, até o rio de Jaboque, que é a fronteira com os descendentes de Amom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Outra de suas fronteiras é também a planície do vale do rio Jordão, de Quinerete até o mar de Arabá, o mar Salgado, nas encostas orientais do monte Pisga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Naquele tempo, eu vos ordenei: \"Yahweh, vosso Deus, vos deu esta terra como posse. Vós, todos os guerreiros, passareis armados diante de vossos irmãos, o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Todavia, ficarão nas cidades que dei a vós, somente vossas mulheres, vossas crianças, e vosso gado, porque sei que tendes muito gado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'até que Yahweh dê descanso a vossos irmãos, assim como deu a vós, e eles também possuam a terra que Yahweh, vosso Deus, lhes dá além do Jordão. Então, voltareis, cada um de vós, para a propriedade que Eu vos tenho dado\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Também ordenei a Josué, naquele tempo, dizendo: \'Os teus olhos viram tudo o que Yahweh, teu Deus, fez a esses dois reis. Assim fará Yahweh a todos os reinos em que entrares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Não os temas, pois Yahweh, teu Deus, é quem pelejará por ti\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Naquele tempo, eu supliquei a Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, '\'Ó, Senhor Yahweh, Tu começaste a mostrar a teu servo, Tua grandeza e Tua forte mão; que Deus há na terra ou nos céus, que possa fazer obras como as que tens feito, e segundo Teus poderosos feitos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Deixa-me entrar! Deixa-me contemplar a boa terra que está além do Jordão, essa bela região montanhosa, e também o Líbano!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Mas, por vossa causa, Yahweh se indignou comigo, e não me deu ouvidos. Yahweh me disse: \'Basta! Não fales mais sobre este assunto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Sobe ao cume do monte Pisga e olha para o ocidente, para o norte, para o sul e para o oriente; contempla com teus olhos, pois não atravessarás o Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Em vez disso, dá ordens a Josué, encoraja-o e fortaleça-o, porque ele atravessará à frente deste povo, e o guiará na conquista da terra que tu verás\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Assim, nós ficamos no vale em frente a Bete-Peor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'E agora, ó Israel, ouve as leis e decretos que eu te ensino a fim de cumpri-los; para que vivas e tomes posse da terra que Yahweh, o Deus de teus pais, está te dando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Não adicionarás nada às palavras que te ordeno, nem diminuirás nada, a fim de cumprir os mandamentos de Yahweh, teu Deus, os quais eu te ordeno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Teus olhos viram o que Yahweh fez por causa de Baal-Peor; porque todos os homens que seguiram Baal-Peor, Yahweh, teu Deus, os destruiu do teu meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Todavia, tu, que te apegaste a Yahweh, teu Deus, estás vivo até hoje, cada um de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Vede, eu já vos ensinei as leis e decretos, conforme Yahweh, meu Deus havia me ordenado, para obedecê-los no meio da terra que ireis, a fim de possuí-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'No entanto, guardai-os e os cumpri; porque vossa sabedoria e vosso entendimento serão vistos diante das pessoas que ouvirão sobre esses estatutos e dirão: \'Certamente, essa grande nação é de pessoas sábias e de grande entendimento\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Pois, que outra grande nação tem um deus tão próximo deles como Yahweh, nosso Deus, está, onde quer que o clamemos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Qual outra grande nação tem leis e decretos tão justos como todas estas leis que coloco, hoje, diante vós?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Apenas prestai atenção e guardai, cuidadosamente, para não vos esquecerdes das coisas que vossos olhos viram, e para que isto não saia do vosso coração, todos os dias da vossa vida. Ao invés disso, tornai conhecido pelos vossos filhos e pelos filhos dos vossos filhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'o dia em que ficastes diante de Yahweh, vosso Deus, em Horebe, quando Yahweh me disse: \'Reúna-os para Mim, e Eu farei com que ouçam as Minhas palavras, para aprenderem a temer-Me todos os dias em que viverem na terra, e para ensiná-las a seus filhos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Vós vos aproximastes e ficastes ao pé da montanha, e esta ardia em fogo até o meio dos céus, com nuvens, densa escuridão e trevas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Yahweh falou convosco no meio do fogo; vós ouvistes o som destas palavras, mas não vistes forma alguma; somente ouvistes uma voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Ele vos declarou a aliança que vos ordenou cumprir, os Dez Mandamentos. Escreveu-os em duas tábuas de pedra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Yahweh ordenou-me, naquele tempo, a vos ensinar os estatutos e as ordenanças, a fim de que vós os cumprísseis na terra que estais atravessando para tomar posse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Prestai muita atenção, pois vós não vistes nenhum tipo de forma no dia em que Yahweh falou a vós em Horebe do meio do fogo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'para que não vos corrompais e façais imagens esculpidas semelhantemente a qualquer criatura, na forma de homem ou mulher;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'ou, semelhantemente, a qualquer animal que está sobre a terra; ou, semelhantemente, a qualquer ave que voa nos céus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'ou, semelhantemente, a qualquer animal que rasteja sobre o chão; ou, semelhantemente, a qualquer peixe que está nas águas debaixo da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Para que, quando levantardes os vossos olhos aos céus e, vendo o sol, a lua ou as estrelas, todo o exército celestial, não sejais levados a vos prostrardes para adorá-los, pois estas coisas Yahweh, vosso Deus, tem dado e compartilhado com todos as povos debaixo de todo o céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Todavia, Yahweh tomou a vós, tirando-vos da fornalha de ferro, fora do Egito, para serdes um povo da Sua própria herança, assim como sois hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Yahweh Se irou contra mim por vossa causa. Ele jurou que eu não passaria o Jordão, e que eu não entraria na boa terra, a terra que Yahweh, vosso Deus, vos dá como herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Ao invés disso, morrerei nesta terra; não passarei o Jordão; mas vós o cruzareis e possuireis essa boa terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Prestai atenção, vós mesmos, para não vos esquecerdes da aliança de Yahweh, vosso Deus, a qual Ele fez convosco, e não façais para vós nenhuma imagem esculpida na forma de tudo o que o Senhor vosso Deus vos proibiu de fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Pois o Senhor, vosso Deus é um fogo devorador, um Deus zeloso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Quando vós gerardes filhos e os filhos dos vossos filhos, e, quando vós estiverdes na terra por um longo tempo, e, se vos corromperdes a vós mesmos e fizerdes uma figura esculpida na forma de algo, e fizerdes o que é mau aos olhos de Yahweh, vosso Deus, para provocá-lo à ira —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'eu chamo os céus e a terra para testemunhar contra vós hoje que vós, em breve, perecereis completamente fora da terra, a qual estais passando pelo Jordão para a possuir; vós não prolongareis os vossos dias, mas sereis completamente destruídos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Yahweh vos espalhará entre os povos e sereis em número reduzido entre as nações para onde Yahweh vos levará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Lá, servireis outros deuses, obras das mãos humanas, deuses de madeira e pedra, os quais não veem, nem escutam, nem comem ou cheiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Mas, de lá, buscareis Yahweh, vosso Deus, e vós o achareis, quando vós O buscardes com todo o vosso coração e todo a vossa alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Quando estiverdes em sofrimento e quando todas estas coisas vierem sobre vós, nestes últimos dias, voltareis para Yahweh, vosso Deus, e ouvireis Sua voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Porque Yahweh, vosso Deus, é Deus misericordioso; Ele não falhará e nem vos destruirá, nem esquecerá da aliança que prometeu aos vossos pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Perguntai agora sobre os dias do passado, àqueles que existiram bem antes de vós. Desde o dia em que Deus criou o homem na terra, perguntai, de uma extremidade dos céus até a outra, se existiu algo grandioso parecido ou igual a isso que tendes ouvido?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Algum povo ouviu a voz de Deus falar do meio do fogo assim como vós ouvistes e vivestes?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Ou Deus se esforçou para ir e tomar para Si uma nação do meio de outras nações, por meio de provas, sinais e maravilhas, por meio de guerras e por mão poderosa, pelo braço estendido e por grande terror, como tudo o que Yahweh, vosso Deus, fez por vós no Egito diante dos vossos olhos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Estas coisas foram mostradas a vós, para que soubésseis que Yahweh é Deus e que não existe outro diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Ele fez ouvir a Sua voz acima dos céus, a fim de vos instruir; na terra, Ele vos mostrou Seu grande fogo; vós ouvistes Suas palavras do meio do fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Porque Ele amou vossos pais, não somente escolheu a descendência deles, mas também os resgatou do Egito com Sua presença e com Seu grande poder,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'a fim de expulsar diante de vós nações grandes e mais poderosas, para ali vos levar, para vos dar por herança a terra delas, como vedes neste dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Hoje, todavia, sabei e considerai, em vosso coração, que só Yahweh é Deus, acima dos céus e embaixo, na terra. Não existe outro igual a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Mantereis Seus estatutos e mandamentos, que hoje vos ordeno, para que vivais bem, vós e vossos filhos, e para prolongardes vossos dias na terra que Yahweh, vosso Deus, vos dá para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Então, Moisés selecionou três cidades do lado leste do rio Jordão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'para as quais qualquer pessoa pudesse se refugiar, se ela matasse uma pessoa acidentalmente, sem que ela fosse sua inimiga anteriormente. Refugiando-se nessas cidades, ela poderia sobreviver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'São elas: Bezer, no deserto, no planalto para os rubenitas; Ramote, em Gileade, para os gaditas; e Golã, em Basã, para os manassitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Esta é a lei que Moisés apresentou diante do povo de Israel;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'esses são os estatutos, as leis e outros decretos que Moisés falou ao povo de Israel quando eles saíram do Egito,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'quando eles estavam no leste do Jordão, no vale defronte a Bete-Peor, na terra de Siom, rei dos amorreus, que viviam em Hesbom, a quem Moisés e o povo de Israel derrotaram quando saíram do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Eles tomaram suas terras como uma posse e a terra de Ogue, rei de Basã, sendo esses dois reis dos amorreus, os quais estavam entre o Jordão, em direção ao leste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Este território veio desde Aroer, na beira do vale do Arnon, até o monte de Siom, que é o monte Hermon,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'e incluía toda a planície do vale do rio Jordão, para o leste, além do Jordão, em direção ao mar de Arabá, nas encostas do monte Pisga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Moisés chamou todo o povo de Israel e disse-lhes: \"Ouvi, ó Israel, os estatutos e decretos que hoje vos falo, para que os aprendais e os guardeis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Yahweh, nosso Deus, fez uma aliança conosco no monte Horebe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Yahweh não fez essa aliança com nossos antepassados, mas conosco, que estamos vivos aqui hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Yahweh falou convosco face a face no monte, do meio do fogo');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, '(Naquele momento, fiquei entre vós e Yahweh, para revelar-vos a palavra Dele; pois ficastes atemorizados por causa do fogo, e não subistes a montanha). Yahweh disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, '\'Eu sou Yahweh, teu Deus, que te tirei da terra do Egito, da casa da escravidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Não terás outros deuses diante de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Não farás para ti imagem de escultura, nem nada semelhante ao que está acima no céu, ou embaixo na terra, ou debaixo da água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Não te curvarás diante delas, nem as adorarás, pois Eu, Yahweh, teu Deus, sou um Deus zeloso. Eu castigo o pecado dos pais punindo seus filhos até a terceira e a quarta geração daqueles que Me rejeitam,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'e demonstro aliança de fidelidade a milhares daqueles que Me amam e guardam Meus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Não tomarás o nome de Yahweh, teu Deus, em vão, pois Yahweh não deixará impune quem usar o nome Dele indevidamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Guardarás o dia de sábado para o santificar, como ordenou Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Trabalharás e farás tuas tarefas por seis dias;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'mas o sétimo dia é um sábado para Yahweh, teu Deus. Nesse dia, não farás trabalho algum — nem tu, nem teu filho, nem tua filha, nem teu servo, nem tua serva, nem teu boi, nem teu jumento, nem qualquer gado teu, nem nenhum estrangeiro que estiver dentro dos teus portões. Isto é para que teu servo e tua serva descansem como tu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Lembrarás que foste servo na terra do Egito, e Yahweh, teu Deus, te tirou dali, com a mão forte e o braço estendido. Por isso, Yahweh, teu Deus, te ordena a guardar o dia de sábado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Honra teu pai e tua mãe, como Yahweh, teu Deus, ordenou que fizesses, e, assim, prolongarás tua vida na terra que Yahweh, teu Deus, te dá, e tudo te correrá bem');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Não matarás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Não adulterarás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Não roubarás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Não darás falso testemunho contra o teu próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Não cobiçarás a mulher do teu próximo, nem a sua casa, nem as suas terras, nem seu servo ou sua serva, nem seu boi, nem seu jumento, nem nada do que lhe pertença\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Essas palavras Yahweh falou em alta voz a toda a congregação na montanha, do meio do fogo, da nuvem e da densa escuridão. E não acrescentou qualquer palavra. Ele as escreveu em duas tábuas de pedra, e as entregou a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Sucedeu que, quando ouvistes a voz em meio à escuridão, enquanto a montanha queimava, vos achegastes a mim, com todos os anciãos e líderes das vossas tribos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Dissestes: \'Yahweh, nosso Deus, mostrou-nos a Sua glória e a Sua grandeza, e ouvimos a Sua voz do meio do fogo; hoje, vimos Deus falar com o homem, e este ainda continuar vivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Agora, pois, por que devemos morrer? Porque este imenso fogo nos consumirá; se continuarmos a ouvir a voz de Yahweh, nosso Deus, morreremos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Pois quem dentre os homens ouviu a voz do Deus vivo, falando do meio do fogo, e sobreviveu, como nós?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Vai tu, e escuta tudo o que Yahweh, nosso Deus, disser; repete para nós tudo o que Yahweh, nosso Deus, disser, e nós ouviremos e obedeceremos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Yahweh ouviu vossas palavras quando as falastes. Ele me disse: \'Eu ouvi as palavras desse povo, eles falaram bem em tudo que disseram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Quem dera o coração deles fosse sempre assim, que Me temessem e guardassem todos os Meus mandamentos, para que eles e seus filhos vivessem bem para sempre!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Vai e dize-lhes: Retornai a vossas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Tu, porém, permanece aqui comigo, e Eu te direi todos os mandamentos, estatutos e decretos que deverás ensinar-lhes, para que possam cumpri-los na terra que Eu lhes darei\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Cumprireis, portanto, o que Yahweh, vosso Deus, vos ordenou; não desviareis nem para a direita, nem para a esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Andareis em todo caminho que Yahweh, vosso Deus, vos ordenou, para que vivais, sejais bem sucedidos, e para que se prolonguem vossos dias na terra que possuireis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Estes são os mandamentos, estatutos e decretos que Yahweh, o vosso Deus, me ordenou para vos ensinar, para os guardar na terra à qual estais indo, além do Jordão, para possuí-la;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'a fim de que temais Yahweh, vosso Deus, e guardais todos os seus estatutos e mandamentos que eu vos ordeno, vós, vossos filhos e os filhos dos vossos filhos, todos os dias de vossa vida e para que os vossos dias se prolonguem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Portanto, escuta ó Israel, e guarda, para que te vás bem, e te multipliques grandemente na terra que mana leite e mel, como Yahweh, Deus de teus pais, te prometeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Escuta, Israel: Yahweh, nosso Deus, é o único Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Amarás a Yahweh, teu Deus, com todo o teu coração, com toda a tua alma e com todas as tuas forças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'As palavras, que hoje te ordeno, estarão sempre em teu coração;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'e tu as ensinarás diligentemente aos teus filhos; falarás ao sentares em tua casa, quando andares no caminho, quando deitares, e quando acordares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Tu as amarrarás como sinal em tua mão e elas te servirão como faixa entre teus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Escreverás nos batentes e nas portas de tuas casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Quando Yahweh, teu Deus, te estabelecer na terra que jurou a teus pais, Abraão, Isaque, e Jacó, que Ele te daria com grandes e boas cidades, que tu não edificaste');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'e casas cheias de todos os tipos de bens, que tu não encheste, poços que tu não cavaste, e vinhedos e oliveiras que tu não plantaste, tu comerás e ficarás satisfeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Então, tem cuidado para que não te esqueças de Yahweh, que te tirou da terra do Egito, da casa da escravidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Temerás Yahweh, teu Deus, a Ele prestarás culto e jurarás pelo Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Não seguirás outros deuses, os deuses dos povos que estão à tua volta —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'pois, Yahweh, teu Deus, que está no meio de ti, é um Deus zeloso; para que a ira de Yahweh, teu Deus, não se acenda contra ti e Ele te destrua da face da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Não tentarás Yahweh, teu Deus, como fizeste em Massá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Guardarás, diligentemente, os mandamentos de Yahweh, teu Deus, e os Seus solenes mandamentos e estatutos que Ele te ordenou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Farás o que é reto e bom aos olhos de Yahweh, para que te vás bem, entres e possuas a boa terra que Yahweh jurou a teus pais,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'para que expulses todos teus inimigos diante de ti, como disse Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Quando os teus filhos te perguntarem, no tempo que há de vir, dizendo: \'O que são os decretos da aliança, os estatutos, e os outros decretos que Yahweh, nosso Deus, te ordenou?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Então, tu dirás para teu filho: \'Fomos escravos de Faraó no Egito; Yahweh nos tirou do Egito com Sua poderosa mão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'e Ele fez sinais e maravilhas, grandes e terríveis, no Egito, contra Faraó, e em toda sua casa, diante de nossos olhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'e Ele nos tirou de lá, para nos estabelecer, para nos dar a terra que Ele jurou aos nossos pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Yahweh nos ordenou guardar todos estes estatutos, temer Yahweh, nosso Deus, para o nosso bem, para sempre, para que Ele nos preserve vivos, como estamos hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Se nós guardarmos todos esses mandamentos diante de Yahweh, nosso Deus, assim como ele nos ordenou, essa será a nossa justiça\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Quando Yahweh, teu Deus, te introduzir na terra que possuirás, e houver expulsado muitas nações diante de ti — os heteus, os girgaseus, os amorreus, os cananeus, os perizeus, os heveus, e os jebuseus — sete nações maiores e mais poderosas do que tu;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'e, quando tu as encontrares na batalha e Yahweh, teu Deus, der a vitória sobre elas, tu as atacarás, e as destruirás completamente. Não farás nenhuma aliança com elas, nem demonstrarás misericórdia para com elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Não entres em acordo matrimonial algum com elas; não dês tuas filhas para os filhos delas, e não tomes as filhas delas para teus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Pois farão teus filhos se desviarem para longe de mim, vindo a adorar a outros deuses. Assim, a ira de Yahweh se acenderá contra ti, e te destruirá rapidamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'É assim que lidará com elas: destruirás os seus altares, quebrarás em pedaços os seus pilares sagrados de pedras, cortarás os seus aserins e lançarás seus ídolos no fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Pois tu és uma nação que foste separada por Yahweh, teu Deus. Ele vos escolheu para ser um povo de Sua posse, dentre todos os outros povos que estão na face da Terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Yahweh não colocou Seu amor sobre ti, ou te escolheu por ser mais numeroso que outros povos, pois eras o menor de todos os povos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'mas porque Ele te amou e te livrou para cumprir o juramento que havia feito para teus pais. Esta é a razão pela qual Yahweh te resgatou com poderosa mão, da casa de escravidão, das mãos de Faraó, rei do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Portanto, saberás que Yahweh, teu Deus, é Deus, o Deus fiel, que guarda a aliança e fidelidade por mil gerações com aqueles que O amam e guardam Seus mandamentos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'mas retribui pessoalmente àqueles que O odeiam para os destruir. Ele não será brando para com aqueles que O odeiam, prontamente retribuirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Portanto, guardarás os mandamentos, os estatutos, e os decretos que hoje te ordeno, e assim o farás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Se ouvires estes decretos, e os guardares e os cumprires, Yahweh, teu Deus, manterá a aliança e a fidelidade que Ele jurou a teus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Ele te amará, te abençoará, e te multiplicará; ele abençoará o fruto do teu ventre e o fruto da tua terra, teu grão, teu vinho novo, e teu azeite, e multiplicará teu gado e a força dos teus rebanhos, na terra que jurou a teus pais que te daria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Serás mais abençoado que todos os outros povos; não haverá homem ou mulher estéril no meio de ti ou do teu gado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Yahweh afastará de ti todas as enfermidades; Ele não colocará sobre ti nenhuma das doenças malignas do Egito, que tu bem conheces, mas Ele as colocará sobre todos aqueles que te odiarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Tu consumirás todos os povos, que Yahweh, teu Deus, entregar em tuas mãos, e teus olhos não se compadecerão deles. E tu não adorarás os seus deuses, pois isto seria uma armadilha para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Se, em teu coração, disseres: \'Estas nações são mais numerosas que nós; como poderemos expulsá-las?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Não terás medo delas! Lembrarás do que Yahweh, teu Deus, fez a Faraó e a todo o Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'O grande sofrimento que teu olhos viram, os sinais, as maravilhas, a poderosa mão e a manifestação de poder pelos quais Yahweh, teu Deus, te tirou. Yahweh, teu Deus, fará assim para com todos os povos que tu temes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Além disso, Yahweh, teu Deus, enviará vespas entre eles, até que pereçam aqueles que houverem se escondido de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Não te assustes por causa deles, pois Yahweh teu Deus está no meio de ti, um Deus grande e temível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Yahweh, teu Deus, pouco a pouco, expulsará cada nação diante de ti. Não as vencerás todas de uma vez, pois os animais selvagens se multiplicariam em volta de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Mas Yahweh, teu Deus, te dará vitória sobre eles quando tu os encontrares em batalha; Yahweh os confundirá até que eles estejam destruídos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Ele colocará seus reis debaixo das tuas mãos e fará o nome deles desaparecer de debaixo dos céus. Nenhum deles será capaz de estar diante de ti, até que os tenhas destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Tu queimarás as imagens esculpidas de seus deuses; não cobiçarás a prata e o ouro que as recobrem, nem mesmo as tomarás para ti, pois isso seria uma armadilha para ti. Para Yahweh, o teu Deus, isso é uma abominação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Tu não trarás nenhuma abominação para dentro de tua casa, para que não venhas a adorá-la. Tu as rejeitarás completamente e as abominarás, pois toda abominação será separada para destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Guardarás todos os mandamentos que te dei hoje, para que tenhas vida e te multipliques, e entres e tomes posse da terra que Yahweh jurou a teus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Lembrarás de todos os caminhos que Yahweh, teu Deus, te conduziu nesses quarenta anos no deserto, para que Ele te humilhasse e te colocasse a prova, a fim de saber o que estava no teu coração, se tu guardarias os Seus mandamentos ou não.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Ele te humilhou, te deixou ter fome e te alimentou com maná, que tu nem conhecias, nem os teus pais conheciam. Ele fez estas coisas para que soubesses que o ser humano não vive somente de pão, mas de tudo que procede da boca de Yahweh é que o ser humano vive.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Tuas roupas não envelheceram em ti e teus pés não incharam durante esses quarentas anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'considera, pois, no teu coração, que Yahweh, teu Deus, te corrige, assim como um homem corrige seu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Guarda os mandamentos de Yahweh, teu Deus, para andares em Seus caminhos e O honrares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Porque Yahweh, teu Deus, está te levando a uma boa terra, terra de ribeiros de águas, de fontes e nascentes, que brotam dos vales e nas colinas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'uma terra de trigo e cevada, de vinhas, de figueiras e romãzeiras; terra de oliveiras e mel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'É uma terra em que comerás pão sem escassez, e onde não te faltará nada; uma terra cujas pedras são feitas de ferro e de cujos montes poderás tirar cobre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Comerás e te fartarás e bendirás a Yahweh, teu Deus, pela boa terra que Ele te deu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Cuidado para não te esqueceres de Yahweh, teu Deus, e negligenciares os Seus mandamentos, Suas ordenanças, e Seus estatutos, que hoje te ordeno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Senão, quando comeres e estiveres farto, e, quando construíres boas casas e nelas habitares, o teu coração fique elevado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'Cuidado, pois, quando as tuas manadas e teus rebanhos se multiplicarem, quando a tua prata e o teu ouro aumentarem, quando tudo que a ti pertence se multiplicar');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'e, assim, teu coração se tornar envaidecido, cuida para que não te esqueças de Yahweh, teu Deus, que te trouxe da terra do Egito, da casa da escravidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Não te esqueças Daquele que te conduziu pelo grande e terrível deserto, em que havia serpentes venenosas e escorpiões, e pela terra seca onde não havia água; Daquele que tirou água da dura rocha para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Ele te alimentou no deserto com o maná que teus antepassados nunca conheceram, para te humilhar e te provar, mas, para mais tarde, fazer o bem a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Portanto, não digas em teu coração: \'Meu poder e a força da minha mão conquistaram toda essa riqueza\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Mas lembra-te de Yahweh, teu Deus, porque Ele te deu poder para conquistar riquezas; para estabelecer a Sua aliança que jurou aos teus pais como existe hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Caso te esqueças de Yahweh, teu Deus, e sigas outros deuses, e os adores, e os reverencies, eu testemunho hoje contra ti, que, certamente perecerás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Como as nações que Yahweh está fazendo perecer diante de ti, assim perecerás, por não escutares a voz de Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Ouve, Israel: hoje atravessarás o Jordão, e tomarás posse de nações mais poderosas e fortes que tu, com cidades grandes e fortificadas até o céu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'um povo grande e alto, os anaqueus, que tu conheces e dos quais ouviste dizer: \'Quem resistirá aos anaqueus?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Portanto, saberás hoje que Yahweh, o teu Deus, é Aquele que vai adiante de ti como um fogo devorador. Ele os destruirá, e os subjugará diante de ti; tu os expulsarás e farás com que desapareçam rapidamente, assim como Yahweh te disse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Depois que Yahweh, o teu Deus, os tiver expulsado de diante de ti, não digas em teu coração: \'Por causa da minha justiça, Yahweh me trouxe para possuir esta terra\'; mas é por causa da maldade dessas nações que Yahweh as expulsa de diante de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Então, não é por causa da tua justiça ou da retidão do teu coração que possuirás a terra; mas sim por causa da maldade dessas nações que o teu Deus as expulsará de diante de ti, e para manter a palavra que jurou a teus antepassados Abraão, Isaque e Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Sabe, portanto, que não é por causa da tua justiça que Yahweh, o teu Deus, te dá esta boa terra para possuí-la, pois és um povo obstinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Lembra-te, e não te esqueças, de como provocaste à ira Yahweh, o teu Deus, no deserto. Desde o dia em que saíste da terra do Egito, até chegar a este lugar, foste rebelde contra Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Também provocaste a ira de Yahweh em Horebe, tanto que Ele Se enfureceu contra ti para te destruir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Quando eu subi à montanha para receber as tábuas de pedra, as tábuas da Aliança que Yahweh fez convosco, fiquei na montanha durante quarenta dias e quarenta noites, não comi pão, nem bebi água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Yahweh me deu as duas tábuas de pedra escritas por Seu dedo; nelas estavam escritas todas as palavras que Yahweh anunciou a vós na montanha, do meio do fogo, no dia da assembleia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Isto aconteceu no fim dos quarenta dias e quarenta noites, nos quais Yahweh me deu as duas tábuas de pedra, as tábuas da Aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Yahweh me disse: \"Levanta-te, desce rapidamente daqui, pois teu povo que tiraste do Egito se corrompeu. Desviaram-se rapidamente do caminho que Eu os ordenei; fizeram para si uma imagem de metal fundido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Além disso, Yahweh me falou e disse: \"Eu vi que este é um povo obstinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Deixa-Me destruí-lo e apagar seu nome de debaixo do céu, e Eu farei de ti uma nação mais poderosa e numerosa do que esta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Então, voltei e desci da montanha. A montanha ardia em fogo. As duas tábuas da Aliança estavam em minhas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Olhei e vi que havíeis pecado contra Yahweh vosso Deus. Fizestes para vós um bezerro de metal fundido, e vos desviastes do caminho que Yahweh vos havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Então, peguei as duas tábuas, joguei-as das minhas mãos, e as quebrei diante de vossos olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Novamente, prostrei-me diante de Yahweh por quarenta dias e quarenta noites. Não comi pão, nem bebi água, por causa de todo pecado que cometestes, fazendo aquilo que era mau aos olhos de Yahweh, provocando a Sua ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Porém, Yahweh me ouviu ainda esta vez. Pois eu estava com medo da ira e do furor de Yahweh que tanto estava irado convosco para vos destruir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Yahweh Se irou contra Arão para o destruir, mas, naquela mesma hora, orei também em favor de Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Então, tomei o vosso pecado, o bezerro que fizestes, e o lancei no fogo, esmaguei e o moí até que ficasse tão fino como o pó. E joguei seu pó no riacho que descia da montanha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Em Taberá, em Massá e em Quibrote-Hataavá, provocastes a ira de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Quando Yahweh vos enviou de Cabes-Barneia, disse: \"Subi e tomai a terra que Eu vos dei\"; vós vos rebelastes contra a ordem de Yahweh, vosso Deus, não acreditastes Nele e não ouvistes a Sua voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Tendes sido rebeldes contra Yahweh desde o dia em que vos conheci.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Então, prostrei-me diante de Yahweh, por quarenta dias e quarenta noites, porque Ele dissera que vos destruiria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Orei a Yahweh, dizendo: \"Ó Senhor Yahweh, não destruas Teu povo ou Tua herança, que resgataste com toda a Tua grandeza; e os tiraste do Egito com Tua poderosa mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Lembra-Te de Teus servos Abraão, Isaque e Jacó; não olhes para a obstinação deste povo, nem sua maldade, nem para seu pecado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'para que a terra de onde nos tiraste não diga: \'Porque Yahweh não conseguiu levá-los para a terra que lhes prometeu, e, por isso, passou a odiá-los e os tirou daqui para matá-los no deserto\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Mas este é o Teu povo, Tua herança, que tiraste com Tua grande força, exibindo o Teu poder\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Naquele tempo, Yahweh me disse: \"Esculpe duas tábuas de pedra, como as primeiras, vem até a Mim na montanha, e faze uma arca de madeira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Eu escreverei nas tábuas as palavras que estavam nas primeiras tábuas que quebraste, e tu as colocarás na Arca\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Então, fiz a Arca de madeira de acácia, e esculpi duas tábuas de pedras, como as primeiras, e subi à montanha, tendo as duas tábuas em minhas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Então, o Senhor escreveu os Dez Mandamentos nas tábuas, como fizera nas primeiras, os mandamentos que Yahweh havia falado para vós no monte, no dia da assembleia, do meio do fogo. Então, Yahweh entregou-me as tábuas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Virei-me, desci da montanha, e coloquei dentro da Arca as tábuas que havia feito. Ali estão elas, como Yahweh me ordenou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, '(O povo de Israel viajou de Beerote-Bene-Jaacã para Mosera. Ali, Arão faleceu e foi enterrado. Eleazar, seu filho, serviu como sacerdote em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'De lá, partiram para Gudgodá, e dali para Jotbatá, uma terra de riachos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Naquele tempo, Yahweh escolheu a tribo de Levi para carregar a arca do testemunho de Yahweh, para servir diante de Yahweh, e abençoar as pessoas em Seu nome até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Portanto, Levi não teve a porção da herança da terra com seus irmãos. Yahweh é sua herança, como Yahweh, seu Deus lhe disse).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, '\"Estive na montanha, como na primeira vez, quarenta dias e quarenta noites. Yahweh escutou-me ainda esta vez; Yahweh não desejou destruir-vos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Disse-me Yahweh: \'Levanta-te, vai na frente do teu povo para liderá-lo em sua jornada. Eles entrarão e possuirão a terra que Eu jurei dar a seus antepassados\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Agora, Israel, o que Yahweh, teu Deus, requer de ti, exceto que O temas, que andes em todos os Seus caminhos, que O ames, e O adores com todo o teu coração e com toda a tua alma,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'guardes os mandamentos de Yahweh, e Seus estatutos, que hoje estou te ordenando para teu próprio bem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'A Yahweh, teu Deus, pertencem o céu e o céu dos Céus, a terra, e tudo o que há nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Somente Yahweh teve prazer em teus pais e os amou, e Ele vos escolheu, descendência deles, mais do que as outras pessoas, como Ele faz hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Portanto, circuncidai o prepúcio do vosso coração, e não sejais teimosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Pois Yahweh, vosso Deus, é Deus dos deuses e Senhor dos senhores, o Poderoso Deus, o Temível, que não discrimina as pessoas e não aceita suborno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Ele executa a justiça para o órfão e a viúva, e mostra Seu amor para o estrangeiro, alimentando-o e vestindo-o.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Portanto, amai o estrangeiro; porque fostes estrangeiros na terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Temerás Yahweh, teu Deus; a Ele cultuarás e te apegarás, e, em Seu nome jurarás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Ele é a razão do teu louvor, e Ele é teu Deus, que tem feito por ti grandes e temíveis coisas, as quais teus olhos têm visto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Teus pais chegaram ao Egito, em setenta pessoas, e Yahweh, teu Deus, te tem feito mais numeroso do que as estrelas do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Então, amarás Yahweh teu Deus e guardarás as Suas instruções, Seus estatutos, Seus decretos, e Seus mandamentos, todos os dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Considerai que eu não estou falando para vossos filhos, os quais não conheceram nem viram a disciplina de Yahweh vosso Deus, Sua grandeza, Sua mão poderosa, ou Seu braço estendido,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'os sinais e as obras que Ele fez a Faraó, rei do Egito, e a toda sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'Tão pouco viram o que Ele fez ao exército do Egito, aos seus cavalos, ou aos seus carros; e de como Ele fez a água do mar Vermelho inundá-los enquanto eles vos perseguiam, e como Yahweh tem os destruído até hoje;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'ou o que Ele fez por vós no deserto antes de virdes para esse lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'Eles não viram o que Yahweh fez a Datã e Abirão, filhos de Eliabe, filho de Rúben; como a terra abriu a boca e os engoliu, com suas famílias, suas tendas, e todo ser vivo que os seguia, no meio de todo o Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Mas vós vistes todas as grandes obras que Yahweh tem feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Portanto, guardai todos os mandamentos que Eu vos ordeno hoje, para que vos torneis fortes, entreis e possuais a terra a que estais indo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'e, assim, vós prolongareis vossos dias na terra em que Yahweh jurou dar aos vossos pais e aos seus descendentes, uma terra de que mana leite e mel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Porque a terra que passais a possuir não se parece com a terra do Egito, de onde vós viestes, onde vós semeastes vossa semente e a regastes com vosso pé, como um jardim de ervas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'mas a terra que passais a possuir é uma terra de colinas e vales, que bebe água da chuva do céu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'a terra de que Yahweh, vosso Deus, cuida; os olhos de Yahweh, vosso Deus, estão sobre ela continuamente, desde o princípio até o fim do ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Se vós ouvirdes diligentemente aos meus mandamentos que eu vos ordeno hoje para amarem Yahweh, vosso Deus, e para servi-lo com todo o vosso coração e com toda vossa alma,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'então, darei a chuva de vossa terra em suas estações, a primeira e a última, assim, devei reunir vossos cereais, vosso vinho novo, e vosso óleo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Eu darei grama a vossos campos para vosso gado, e vós comereis e sereis fartos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Guardai-vos para que o vosso coração não se engane, e vos desvieis, e sirvais a outros deuses, e vos curveis a eles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'assim, a ira de Yahweh se acenderá contra vós, e, então, Ele fechará os céus, não haverá chuva, e a terra não produzirá seus frutos, e depressa perecereis na boa terra que Yahweh está dando a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Portanto, guardai essas minhas palavras em vosso coração e vossa alma; amarrai como um sinal em vossa mão, e deixai-las serem como faixas entre os vossos olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Ensinareis a vossos filhos e falareis sobre elas quando vos sentardes em vossas casas, quando andardes pela estrada, quando vos deitardes, e quando vos levantardes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Escrevereis tais palavras nos batentes das portas de vossas casas e nos portões da vossa cidade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'para que se multipliquem vossos dias e os dias de vossos filhos na terra que Yahweh sob juramento deu a vossos antepassados, enquanto houver céu sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Pois, se vós diligentemente guardardes todos esses mandamentos que eu vos ordenei e cumpri-los, para amar Yahweh, o vosso Deus, para andardes em todos os Seus caminhos, e, se vos apegardes a Ele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'então, Yahweh expulsará todas essas nações de diante de vós, e conquistareis nações maiores e mais poderosas que vós mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Todo lugar onde a planta do vosso pé pisar será vosso; do deserto do Líbano, e do rio, o Eufrates, até o mar do oeste será vossa fronteira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Homem nenhum será capaz de ficar a vossa frente; Yahweh, vosso Deus, irá espalhar o medo e o terror de vós sobre toda a terra que pisardes, como Ele vos disse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Vede, eu hoje coloco diante de vós a benção e a maldição;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'a benção, se obedecerdes aos mandamentos de Yahweh, vosso Deus, que hoje eu vos ordeno;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'e a maldição, se não obedecerdes aos mandamentos de Yahweh, vosso Deus, e vos desviardes para ir atrás de outros deuses que não conhecestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Quando Yahweh, vosso Deus, vos trouxer para a terra, a qual ireis possuir, colocareis a benção no monte Gerizim, e a maldição no monte Ebal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Não estão eles além do Jordão, oeste da estrada ocidental, na terra dos cananeus que moram em Arabá, de frente a Gilgal, ao lado dos carvalhos de Moré?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Pois vós estais para cruzar o Jordão, para irdes possuir a terra que Yahweh vosso Deus está vos dando, e vós ireis possuí-la e viver nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Guardareis todos os estatutos e todos os decretos que eu coloquei diante de vós hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Estes são os estatutos e os decretos que vós tereis que guardar na terra prometida que Yahweh, o Deus de vossos pais, vos entregou para possuirdes por todos os dias de vossas vidas nesta terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Certamente, destruireis todos os lugares que as nações cultuaram seus deuses, nas altas montanhas, nas colinas, e debaixo de toda árvore.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Destruireis seus altares, destruireis seus postes sagrados, e queimareis suas imagens de Aserá. Derrubareis as imagens esculpidas dos seus deuses e extinguireis os seus nomes daquele lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Não adorareis Yahweh dessa maneira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Mas, para o lugar que Yahweh, vosso Deus, escolherá dentre todas as vossas tribos para ali colocar Seu nome, ali será o lugar de Sua habitação, ali será o lugar que devereis ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Ali será o local a que trareis vossos holocaustos, sacrifícios, dízimos, e vossas ofertas das vossas mãos, ofertas de juramento, ofertas voluntárias, e os primogênitos de vossos gados e rebanhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Ali será o local em que vós e vossas famílias comereis perante Yahweh, vosso Deus, e regozijareis nas obras das vossas mãos, onde Yahweh, vosso Deus, vos abençoar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Não fareis as mesmas coisas como fazemos hoje aqui. Até então, todos fazem o que lhes parece certo aos próprios olhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'pois ainda não entrastes no lugar de descanso, na herança que Yahweh, vosso Deus, vos dá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Mas, quando atravessardes o Jordão e habitardes na terra que Yahweh, vosso Deus, vos dá como herança, e, quando Ele vos der descanso de todos os vossos inimigos ao redor, para viverdes em segurança,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'então, haverá um lugar que Yahweh, vosso Deus, escolherá, para ali fazer habitar Seu nome. Ali, levareis tudo o que vos ordeno: vossos holocaustos, sacrifícios, dízimos, e as ofertas das vossas mãos, e todas as ofertas em cumprimento aos vossos votos a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Vós regozijareis perante Yahweh, vosso Deus, vós, vossos filhos e vossas filhas, vossos servos e vossas servas, e o levita que está em vossos portões, pois este não possui porção ou herança entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Atentai para não oferecerdes vossas ofertas queimadas em qualquer lugar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'mas, no lugar que Yahweh escolher em uma de vossas tribos, ali oferecerei vossas ofertas queimadas, e ali fareis tudo o que vos ordenar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Porém, podereis abater e consumir os animais dentro de vossos portões, como desejais, recebendo a benção de Yahweh, vosso Deus, por tudo o que Ele tem vos dado. Animais como a gazela e o cervo, tanto a pessoa impura como a pura poderão comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Todavia, não comereis o sangue, mas o derramareis sobre a terra como água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Não comereis, dentro dos vossos portões, do dízimo do vosso trigo, do vosso vinho novo e do vosso azeite, nem dos primogênitos de vosso gado ou rebanho; nem comereis de qualquer carne provinda de vossos sacrifícios como também dos vossos juramentos que fizeres, nem de vossas ofertas voluntárias, nem das ofertas das vossas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Mas tu, teu filho, tua filha, teus servos, tuas servas e o levita que reside dentro dos teus portões, comerei perante Yahweh, teu Deus, no lugar que Ele escolher, e regozijarás perante Yahweh, teu Deus, em todas as obras de tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Atenta para não te esqueceres do levita enquanto habitares na tua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Quando Yahweh, teu Deus, alargar tuas fronteiras, como Ele havia te prometido, e tu disseres: \"Comerei carne\", devido ao teu desejo de comer carne, poderás comer carne como desejares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Se o lugar que Yahweh, teu Deus, escolher para colocar Seu nome estiver longe de ti, então, abaterás do teu gado e do teu rebanho que Yahweh deu a ti, como te ordenei; e poderás comer dentro dos teus portões, como desejares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Comerás do mesmo modo com que se come a gazela e o cervo. Tanto a pessoa impura como o pura poderão comer deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Porém, certifica-te de não comer o sangue, pois o sangue é vida; não comas a vida com a carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Não o comerás, o despejarás na terra como água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Não o comerás, para que vivas bem, tu e teus filhos depois de ti, quando fizeres o que é correto aos olhos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Mas as coisas que pertencem a Yahweh e que estão contigo, e as tuas ofertas de juramento, levarás ao lugar que Yahweh escolher.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Ali, oferecerás teus holocaustos, a carne e o sangue, no altar de Yahweh, teu Deus. O sangue dos teus sacrifícios serão derramados no altar de Yahweh, teu Deus e tu comerás a carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Ouve e guarda todas estas palavras que te ordeno, para que vás bem, tu e teus filhos depois de ti para sempre, quando tu fizeres o que é bom e reto aos olhos de Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Quando Yahweh, teu Deus, eliminar as nações de diante de ti, quando fores para expulsá-los, e tu os expulsares, e habitares na terra deles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'guarda-te para que não sejas seduzido a imitá-los, depois de terem sido destruídos diante de ti, atraído pelos seus deuses, caindo na armadilha de investigares e perguntares: \"Como essas nações adoravam seus deuses? Eu farei da mesma maneira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Tu não farás isso em respeito a Yahweh, teu Deus, pois eles fizeram tudo o que é repugnante a Yahweh, coisas que Ele odeia. Eles fizeram dessas coisas aos seus deuses, até mesmo queimaram seus filhos e suas filhas no fogo para seus deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'A tudo que eu te ordenar, atentarás. Nada acrescentarás nem diminuirás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Se surgir, no meio de ti, um profeta ou um adivinhador de sonhos, e, se ele te anunciar um sinal ou um prodígio,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'e, se o sinal ou prodígio sobre o qual te falou acontecer, e ele disser: \'Vamos seguir outros deuses, que não conhecestes, e vamos adorá-los\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'não escutes as palavras desse profeta, nem desse adivinhador de sonhos; pois Yahweh, teu Deus, está te provando, se O amas com todo o teu coração e com toda a tua alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Segue Yahweh, teu Deus, honra-O, guarda os Seus mandamentos, obedece a Sua voz, adora-O e apega-te a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Esse profeta ou esse adivinhador de sonhos deverá morrer, pois pregou rebelião contra Yahweh, teu Deus, que te tirou da terra do Egito, e que te resgatou da casa da escravidão. Esse profeta quer afastar-te do caminho pelo qual Yahweh, teu Deus, te ordenou andar. Assim, tira o mal do meio de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Suponha que teu irmão, o filho da tua mãe, ou teu filho, ou tua filha, ou a mulher do teu coração, ou o teu amigo que é muito chegado, te incitar em segredo, dizendo: \'Vamos adorar outros deuses que não conheces, nem tu nem teus antepassados;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'qualquer um dos deuses dos povos que estão ao teu redor, perto ou longe de ti, de uma a outra extremidade da terra\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Não concordes com ele nem o ouças. Nem tenhas piedade dele, nem o poupes, nem o protejas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Ao invés disso, certamente, o matarás; tua mão será a primeira contra ele para matá-lo, e, depois, a mão de todo o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Tu o apedrejarás até a morte, pois ele tentou afastar-te de Yahweh, teu Deus, que te tirou da terra do Egito, da casa da escravidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Todo povo de Israel ouvirá e temerá, e não continuará a cometer esse tipo de maldade no meio de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Se ouvires alguém dizer que, em alguma das cidades que Yahweh, teu Deus, te dá para viver,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'surgiram no meio de ti alguns homens perversos que incitaram os habitantes de tua cidade, dizendo: \'Vamos adorar outros deuses que tu não conheces\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Então, examinarás as evidências, farás uma averiguação, investigando isso cuidadosamente. Se for verdade e comprovado que alguma coisa abominável foi feita no meio de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Tu certamente atacarás os habitantes daquela cidade ao fio da espada, destruindo-a completamente e todo o povo que vive lá, juntamente com seus animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Tu ajuntarás todo o despojo deles no meio da rua e queimarás a cidade, bem como todo o seu despojo para Yahweh, teu Deus. A cidade será um monte ruínas para sempre; ela jamais será reconstruída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Nenhuma das coisas que foram separadas para serem destruídas devem ficar na tua mão. Faze assim, para que Yahweh desvie o furor de Sua ira, te mostre misericórdia, tenha piedade de ti, e te multipliques, como Ele jurou a teus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Ele fará isto porque tu ouviste a voz de Yahweh, teu Deus, para guardar todos os Seus mandamentos que eu tenho ordenado hoje, para fazeres o que é correto diante dos olhos de Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Vós sois o povo de Yahweh, vosso Deus. Não vos corteis, nem raspeis nenhuma parte do vosso rosto pelos mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Pois tu és povo separado para Yahweh, teu Deus, e Yahweh te escolheu para Sua posse, mais que todos os povos sobre a face da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Não comereis nada de repugnante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Estes são os animais que podereis comer: o boi, a ovelha, a cabra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'o veado, a gazela, a corça, o cabrito montês, o órix, o antílope e a ovelha selvagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Podereis comer quaisquer animais com casco partido, ou seja, que têm o casco dividido em dois, e que ruminam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'No entanto, não comereis alguns animais que ruminam ou que têm casco dividido em dois: o camelo, o coelho e o texugo da rocha. Porque eles ruminam, mas não têm o casco partido, eles são impuros para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'O porco também é impuro para vós, porque ele tem o casco partido, mas não rumina; ele é impuro para vós. Não comais carne de porco, e não toqueis suas carcaças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Das coisas que estão na água, podereis comer qualquer coisa que tenha barbatanas e escamas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'mas qualquer coisa que não tenha barbatanas nem escamas, não comereis; elas são impuras para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Todos os pássaros limpos podereis comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Mas estes são os pássaros que não comereis: a águia, o abutre, a águia pesqueira,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'o açor, o milhano, e qualquer tipo de falcão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'Não comereis qualquer tipo de corvo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'o avestruz, a coruja, a gaivota, qualquer tipo de gavião,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'o mocho, a íbis, a gralha,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'o pelicano, o abutre, o corvo marinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Não comereis a cegonha, qualquer tipo de garça, a poupa e o morcego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Todos os insetos alados são impuros para vós; eles não devem ser comidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Vós podereis comer todas as aves puras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Não comais nenhum animal que morreu por si; podereis dá-lo para o estrangeiro que estiver dentro de vossos portões, para que ele coma; ou podereis vendê-lo ao estrangeiro. Pois tu és povo separado para Yahweh, teu Deus. Não cozinharás um cabrito no leite de sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Darás o dízimo de toda a semente da tua terra, produto da tua colheita, ano após ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Comerás diante de Yahweh, teu Deus, no lugar que Ele escolher como Seu santuário, o dízimo do teu trigo, do teu vinho novo, do teu azeite, e o primogênito da tua manada ou do teu rebanho; Que tu aprendas a sempre honrar Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Se a jornada for muito longa para ti, de maneira que não possas carregar os dízimos, porque o lugar que Yahweh, teu Deus, escolherá como Seu santuário, for muito distante,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'converte a oferta em dinheiro, leva o dinheiro em tua mão, e vai para o lugar que Yahweh, teu Deus, escolherá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Gastarás o dinheiro no que desejares: no boi, na ovelha, no vinho, na bebida forte, ou no que desejares. Comerás diante de Yahweh, teu Deus, e alegra-te, tu e teus familiares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'O levita que estiver dentro de teus portões — não o desampares, pois ele não tem parte nem herança contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Ao final de cada terceiro ano, tu apresentarás todo o dízimo da tua produção daquele ano, e o depositarás dentro dos teus portões;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'e o levita, por não ter herança nem parte contigo, e o estrangeiro, e o órfão, e a viúva que estiverem dentro dos teus portões, virão e comerão, e ficarão satisfeitos. Faze isto, para que Yahweh, teu Deus, abençoe a ti em todo trabalho que a tua mão fizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Ao final de cada sete anos, cancelarás as dívidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Assim praticarás a quitação das dívidas: todo credor perdoará algo que emprestou ao seu próximo; ele não cobrará a dívida de seu próximo ou de seu irmão, porque o perdão dessas dívidas foi proclamado por Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Do estrangeiro, poderás exigir o pagamento das dívidas; mas perdoarás ao teu irmão, caso ele deva algo para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Porém, não haverá pobre em teu meio (porque Yahweh certamente te abençoará na terra que te dá para possuir como herança),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'se escutares diligentemente a voz de Yahweh, teu Deus, para guardar todos estes mandamentos que hoje te ordeno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Pois, Yahweh, teu Deus, te abençoará, como Ele prometeu. Emprestarás a muitas nações, mas não tomarás emprestado; governarás muitas nações, porém elas não te governarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Se, dentro de qualquer dos portões da terra que Yahweh, teu Deus, te dá, houver um homem pobre dentre os teus irmãos, não endurecerás o teu coração nem fecharás a tua mão, negando-lhe ajuda;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'mas abrirás a tua mão para emprestar-lhe o suficiente para suprir a sua necessidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Cuidado para não surgir pensamento perverso em teu coração, dizendo: \"O sétimo ano, o ano da remissão, está perto\", para que não sejas mesquinho em relação ao teu irmão pobre, negando-lhe ajuda; pois ele poderá clamar a Yahweh contra ti, e haverá pecado em ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Tu o ajudarás sem tristeza no teu coração, porque, em retorno, Yahweh, teu Deus, te abençoará em todo o trabalho que fizeres e em tudo aquilo que puseres a tua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Pois sempre haverá pobres na terra; por isso, eu te ordeno: \"Abrirás a mão em favor de teu irmão, do necessitado, e do pobre em tua terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Se um de teus irmãos, seja um homem hebreu ou uma mulher hebreia, for vendido a ti, poderá servir-te por seis anos, mas, no sétimo ano, o libertarás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Quando o deixares ir, não o despedirás de mãos vazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Deverás prover-lhe generosamente do teu rebanho, do teu trigo e das tuas uvas. Assim como Yahweh, teu Deus, te abençoou, assim também o abençoarás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Recordarás sempre que foste escravo na terra do Egito, e que Yahweh, teu Deus, te resgatou; por isso, hoje te ordeno que assim o faças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'E, se ele disser: \'Eu não me apartarei de ti\', por causa do amor que tem por ti e por tua casa, e por causa da boa convivência contigo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'então, usarás uma agulha grossa e lhe furarás a orelha na porta, e ele será teu servo para sempre. E fará da mesma forma com a tua serva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Não te pareça pesaroso libertá-lo, porque ele foi teu servo por seis anos e deu a ti duas vezes o valor de um assalariado. Yahweh, teu Deus, te abençoará em tudo o que fizeres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Consagrarás todo primogênito macho do teu gado e do teu rebanho a Yahweh, teu Deus; não trabalharás com o primogênito do teu gado, nem tosquiarás o primogênito do teu rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Tu o comerás a cada ano perante Yahweh, teu Deus, tu e a toda a tua casa, no local que Yahweh escolher.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Se houver qualquer imperfeição — se ele for coxo ou cego, ou tiver qualquer outro defeito — não o sacrificarás a Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Tu o comerás dentro dos teus portões; tanto a pessoa pura quanto a impura poderão comer, como se fosse carne de uma gazela ou de um cervo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Somente tu não comerás o seu sangue, mas o despejarás sobre a terra como água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Observai o mês de Abibe, e celebrai a Páscoa para Yahweh vosso Deus, pois, no mês de Abibe, Yahweh, vosso Deus, vos tirou do Egito, durante a noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Oferecei sacrifíicos da Páscoa para Yahweh, vosso Deus, com alguns do rebanho de ovelhas e vacas no lugar que Yahweh escolherá como Seu Santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Vós comereis pão sem fermento com o sacrifício; por sete dias, vós comereis pão sem fermento com o sacrifício, o pão da aflição; pois saíste com pressa da terra do Egito. Fazei isto todos os dias das vossas vidas para lembrardes do dia em que saíste da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Nenhum fermento deve ser encontrado entre vós, dentro de vossas fronteiras, durante sete dias; e nenhuma carne que vós sacrificardes ao anoitecer do primeiro dia deverá permanecer até a manhã seguinte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Vós não sacrificareis a Páscoa dentro dos portões da cidade que Yahweh, vosso Deus, vos dá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Ao invés disto, sacrificai no lugar que Yahweh, vosso Deus, escolher como Seu Santuário. Nele, vós apresentareis o sacrifício da Páscoa à noite, no pôr do Sol, na época do ano em que saístes do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Vós a assareis e a comereis no lugar que Yahweh, vosso Deus, escolher; na manhã, vós ireis para as vossas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Por seis dias, vós comereis pão sem fermento; no sétimo dia, haverá uma assembleia solene para Yahweh, vosso Deus. Neste dia não trabalhareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Vós contareis sete semanas para vós mesmos; do tempo que começardes a colocar a foice na plantação, vós contareis sete semanas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Vós guardareis a Festa das Semanas para Yahweh, vosso Deus, contribuindo com a oferta voluntária da vossa mão, de acordo com o que Yahweh, vosso Deus, vos abençoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Vós vos regozijareis perante Yahweh, vosso Deus, vós, vosso filho, vossa filha, vosso servo, vossa serva, o levita que está dentro dos portões da vossa cidade, o estrangeiro, o orfão e a viúva que estão entre vós, no lugar que Yahweh, vosso Deus, escolher para Seu santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Vós vos lembrareis que éreis escravos no Egito; observareis e seguireis esses estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Guardareis a Festa dos Tabernáculos por sete dias, depois que colherdes da plantação da vossa separação de grãos e das vossas uvas pisoteadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Regozijareis durante a Festa, vós, vosso filho, vossa filha, vosso servo, vossa serva, o levita, o estrangeiro, o orfão e a viúva que estão dentro dos vossos portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Por sete dias, observareis a Festa para Yahweh, vosso Deus, no lugar que Yahweh escolher, porque Yahweh, vosso Deus, vos abençoará em toda vossa colheita e em todo o trabalho de vossas mãos; e vos alegrareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Três vezes por ano, todos os vossos homens se apresentarão perante Yahweh, vosso Deus, no lugar que Ele escolher: na Festa do Pão sem Fermento, na Festa das Semanas e na Festa dosTabernáculos; e eles não aparecerão diante de Yahweh de mãos vazias;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'ao invés disso, todo homem ofertará como puder, para conhecer a benção que Yahweh, vosso Deus, vos dá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Escolhereis juízes e oficiais entre todas as cidades que Yahweh, vosso Deus, vos dá; eles serão escolhidos de cada uma das vossas tribos, e devem julgar as pessoas com um julgamento justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Não pervertereis a justiça; não mostrareis parcialidade, nem recebereis suborno, pois o suborno cega os olhos dos sábios e perverte as palavras do justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Vós seguireis a justiça, somente a justiça, para viverdes e tomardes como herança a terra que Yahweh, vosso Deus, vos dá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Não levantareis para vós mesmos nenhum tipo de poste-ídolo, a não ser o altar de Yahweh, vosso Deus, que fareis para vós mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Nem mesmo levantareis para vós mesmos qualquer pilar de pedra sagrado, que Yahweh, vosso Deus, odeia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Vós não sacrificareis a Yahweh, vosso Deus, um boi ou uma ovelha que tenha qualquer mancha ou defeito, pois isso seria abominação para Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Se for encontrado, no meio de vós, dentro de qualquer um dos portões da cidade que Yahweh, vosso Deus, vós dá, qualquer homem ou mulher que pratique o que é mal à vista de Yahweh, vosso Deus, quebrando a Sua aliança,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'qualquer um que tenha ido e adorado outros deuses e se prostrado a eles, mesmo ao sol, à lua, ou a qualquer um dos astros do céu, nada do que eu tenho ordenado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'e, se alguém vos falar sobre isso, ou, se ouvirdes sobre isso, então, fareis uma investigação cuidadosa. Se for verdade e estiverdes certos de que tal coisa detestável foi feita em Israel, eis o que fareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Trareis o homem ou a mulher que tiver cometido tal maldade para os portões da vossa cidade, esse mesmo homem ou essa mesma mulher, e apedrejai essa pessoa até a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Pela palavra de duas ou três testemunhas, essa pessoa será condenada à morte; mas não será condenada pela palavra de apenas uma testemunha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'A mão das testemunhas deve ser a primeira a condenar a pessoa à morte, e, a seguir, a mão de todo o povo; e vós removereis o mal do vosso meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Se surgir um assunto que seja muito difícil para vós julgardes, talvez uma questão de assassinato ou morte acidental, sobre o direito de uma pessoa ou o direito de outra pessoa, ou uma questão sobre algum tipo de dano feito, ou outro tipo de assunto, questões polêmicas no interior dos portões da vossa cidade, então, vós ireis ao lugar que Yahweh, vosso Deus, escolherá como Seu santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Ide aos sacerdotes, os descendentes de Levi, e ao juiz que estiver trabalhando nesse período; buscai o conselho deles, e eles vos darão o veredito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Seguireis a lei que vos foi dada, no lugar que Yahweh escolherá como Seu santuário. Vós sereis cuidadosos em fazer tudo o que eles vos direcionarem a fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Segui a lei que eles vos ensinarem, e façai de acordo com as decisões que eles vos informarem. Não vos afasteis do que eles vos disserem, nem para a direita nem para a esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Qualquer um que agir arrogantemente, não ouvindo o sacerdote que está servindo diante de Yahweh, vosso Deus, ou não ouvindo o juiz, esse homem morrerá; vós eliminareis o mal do meio de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Todo o povo deve ouvir e temer, e não mais agir arrogantemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Quando vós chegardes à terra que Yahweh, vosso Deus, vos dá, e, quando vós tomardes posse dela e começardes a viver nela, e disserdes: \'Designarei um rei sobre mim, como todas as outras nações que estão ao redor de mim\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'então, vós certamente designareis um rei sobre vós, aquele que Yahweh, vosso Deus, escolherá. Designareis, como rei sobre vós, alguém do meio dos vossos irmãos. Não colocareis um estrangeiro, que não é vosso irmão, sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Mas ele não poderá multiplicar cavalos para si, nem fazer o povo retornar ao Egito para que ele multiplique seus cavalos, pois Yahweh vos disse: \'Vós, de agora em diante, jamais retornareis por esse caminho\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'E ele não multiplicará esposas para si, para que seu coração não se desvie de Yahweh; nem acumulará para si grande quantidade de prata e ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Quando se assentar sobre o trono do seu reino, ele deve escrever para si, em um livro, uma cópia desta lei, que está diante dos sacerdotes, que são levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'O livro estará com ele, e ele o lerá todos os dias da sua vida, para aprender a honrar Yahweh, seu Deus, assim como guardar todas as palavras desta lei e estes estatutos, para os cumprir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Ele fará isso e, assim, seu coração não se exaltará sobre o de seus irmãos, e ele não se desviará dos mandamentos, nem para a direita, nem para a esquerda. Assim, prolongará os dias do seu reinado, dele e de seus filhos, no meio de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Os sacerdotes levitas, e toda a tribo de Levi, não terão porção nem herança com Israel; como sua herança, eles comerão das ofertas queimadas para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Eles não terão herança entre seus irmãos; Yahweh é a sua herança, como Ele lhes disse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Este será o direito dos sacerdotes, das ofertas do povo, daqueles que oferecem um sacrifício, quer seja boi ou ovelha: eles devem dar ao sacerdote a espádua, a queixada e as vísceras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Darás aos sacerdotes as primícias dos teus grãos, do teu vinho novo, do teu azeite, e a primeira tosquia da tua ovelha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Pois Yahweh, teu Deus, os escolheu dentre todas as tribos, ele e seus filhos, para ministrarem e servirem para sempre em nome de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Se um levita vier de qualquer uma das cidades de todo o Israel onde ele estiver morando, e desejar, com toda a sua alma, vir para o lugar que Deus escolher,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'então, ele servirá em nome de Yahweh, seu Deus, como fazem todos os seus irmãos levitas, que estão diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Eles terão porções similares para comer, além do que vier da venda dos bens de sua família.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Quando entrares na terra que Yahweh, teu Deus, te dá, não imitarás as práticas abomináveis daquelas nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Não será encontrado entre vós ninguém que coloque seu filho ou sua filha no fogo, ninguém que use adivinhações, que pratique agouros, que lance feitiços, que pratique bruxaria, que faça magia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'nenhum encantador, ninguém que fale com os mortos, ou com espíritos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Pois qualquer um que pratique essas coisas é abominável para Yahweh; é por causa dessas abominações que Yahweh, teu Deus, os está expulsando de diante de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Serás inculpável diante de Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Pois estas nações que conquistarás ouvem aqueles que praticam a feitiçaria e a adivinhação; mas a ti, Yahweh, teu Deus, não permitiu que o fizesses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Yahweh, teu Deus, vai levantar um profeta do teu meio, um de teus irmãos, como eu. Tu o ouvirás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Isso é o que pediste a Yahweh, teu Deus, no dia em que estiveram reunidos no Horebe, dizendo: \"Não nos deixes ouvir novamente a voz de Yahweh, nosso Deus, e nunca mais ver este grande fogo, ou nós morreremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Yahweh disse a mim: \"O que eles disseram é bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Eu levantarei um profeta para eles, dentre seus irmãos, semelhante a ti. Eu colocarei Minhas palavras em sua boca, e ele dirá a eles tudo que Eu ordenar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Eu pedirei contas de qualquer um que não ouvir as palavras que este profeta pronunciar em Meu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Mas o profeta que disser uma palavra com arrogância em Meu nome, uma palavra que Eu não ordenei que ele dissesse, ou que falar em nome de outros deuses, este profeta morrerá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Isso é o que dirás no teu coração: \"Como saberemos se a mensagem desse profeta é de Yahweh?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Se aquela coisa não acontecer nem se cumprir, então, saberás que é uma palavra que Yahweh não falou e esse profeta falou de forma arrogante, e tu não o temerás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Quando Yahweh, vosso Deus, remover as nações, daqueles cuja terra Yahweh, vosso Deus, está vos dando, e quando vierdes atrás delas e morardes em suas cidades e casas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'selecionarei três cidades para vós no meio da terra que Yahweh, vosso Deus, está dando para possuirdes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Construirei uma estrada e dividir as fronteiras de vossa terra em três partes, a terra que Yahweh, vosso Deus, vos fará possuir, para que qualquer um que mate outra pessoa possa refugiar-se nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Esta é a lei para aquele que comete homicídio e que se refugia nela para viver: qualquer que mate involuntariamente seu vizinho, sem previamente odiá-lo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'como quando um homem vai para a floresta com seu vizinho para cortar madeira, e sua mão dá um golpe com o machado para cortar a árvore, e a cabeça de ferro escapa do cabo e acerta o vizinho e ele morre, então, aquele homem deve refugiar-se em uma dessas cidades e viver nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Do contrário, o vingador do sangue pode ir atrás daquele que tirou a vida e, no calor da sua raiva, o alcançar, se o caminho for muito longo, o atacar e matar, ainda que o homem não mereça morrer, já que ele não odiava o seu vizinho anteriormente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Por isso, eu ordeno que vós selecioneis três cidades para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Se Yahweh, vosso Deus, ampliar as fronteiras da vossa terra, como Ele jurou aos vossos antepassados, e dar-vos toda a terra que Ele prometeu dar aos vossos antepassados;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'se vós guardardes todos esses mandamentos para cumpri-los, os quais vos estou ordenando hoje, mandamentos para amar Yahweh, vosso Deus, e andar em Seus caminhos, então, vós adicionarei mais três cidades para vós, além daquelas três.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Fazei isto para que o sangue inocente não seja derramado no meio da terra que Yahweh, vosso Deus, vos dá como herança, para que não haja culpa de sangue sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Mas, se alguém odeia o seu vizinho, armar-lhe uma cilada, levantar-se contra ele e, mortalmente, o ferir e matar, se este fugir para uma dessas cidades,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'então, os anciãos da cidade deverão enviá-lo e devolvê-lo de lá, e, entregá-lo nas mãos do parente responsável, para que ele morra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Não o olharás com piedade. Ao invés disso, tirarás de Israel a culpa do sangue inocente, para que te vá bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Não removereis os marcos de vossos vizinhos, que eles colocaram há muito tempo, na herança que vós recebereis, na terra que Yahweh, vosso Deus, vos dá como posse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Uma testemunha não se levantará sozinha contra um homem, por qualquer iniquidade, nem por qualquer pecado, em nenhuma questão que ele peque. Qualquer questão será confirmada pela boca de duas testemunhas, ou pela boca de três testemunhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Suponhais que uma falsa testemunha se levante contra qualquer homem para testificar uma injustiça contra ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Então, ambos os homens, aqueles entre os quais existe a controvérsia, colocar-se-ão diante de Yahweh, diante dos sacerdotes e dos juízes que os servem naqueles dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Os juízes farão uma investigação cuidadosa. Se a testemunha for falsa e testificar falsamente contra seu irmão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'então, farei a ela o que ela desejava fazer ao seu irmão. Desse modo, removereis o mal do meio de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Então, aqueles que permanecerem escutarão e temerão. Não cometerão semelhante mal entre vós novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Não olharás com piedade; vida pagará por vida, olho por olho, dente por dente, mão por mão, pé por pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Quando vós marchardes para batalha contra os vossos inimigos, e virdes cavalos, carros, e um povo mais numeroso do que vós, vós não ficareis com medo deles; pois Yahweh, vosso Deus, está convosco, ele que vos tirou da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Quando vós chegardes perto da batalha, o sacerdote deve aproximar-se e falar ao povo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'e dizer-lhes: \'Escutai, Israel, hoje vós vos aproximais de uma batalha contra os vossos inimigos; não deixeis os vossos corações fraquejarem; não temais, nem tremais, nem tenhais medo deles;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'pois Yahweh, vosso Deus, é quem vai convosco para lutar por vós contra os vossos inimigos e vos salvar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Os oficiais falarão com o povo e dirão: \'Que homem que construiu uma casa nova e não usufruiu dela? Deixai-o ir e retornar para sua casa, para que ele não morra na batalha e outro homem usufrua dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Que homem que plantou uma vinha e não desfrutou dela? Deixai ele ir e retornar para sua casa, para que ele não morra na batalha e outro homem desfrute dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Que homem que está noivo de uma mulher mas ainda não se casou com ela? Deixai ele ir e retornar à sua casa, para que ele não morra na batalha e outro homem se case com ela\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Os oficiais falarão mais ao povo e dirão: \'Que homem que é medroso ou de coração fraco? Deixai ele ir e retornar à sua casa, para que o coração do seu irmão não seja influenciado pelo coração dele\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Quando os oficiais terminarem de falar com o povo, eles escolherão comandantes sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Quando vós marchardes para atacar uma cidade, fazei a eles uma oferta de paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Se eles aceitarem a vossa oferta e abrirem seus portões para vós, todo o povo encontrado lá deve tornar-se vossos escravos e devem vos servir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Mas, se não fizerem oferta de paz para vós, mas, ao invés disso, guerrear contra vós, então, devei sitiá-los,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'e, quando Yahweh, vosso Deus, dar-vos vitória e colocá-los debaixo do vosso controle, matai todo homem da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Mas as mulheres, as crianças, o gado, e toda coisa que há na cidade, e tudo que for valioso, pegareis como despojo para vós. Vós consumireis o despojo dos vossos inimigos, de quem Yahweh, vosso Deus, tem vos dado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Agi dessa forma com todas as cidades que estão longe de vós, cidades que não são parte dessas nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Nas cidades desses povos que Yahweh, vosso Deus, está vos dando como herança, não deixeis com vida nada que respira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Ao invés disso, devei destruí-los completamente: os heteus, os amorreus, os cananeus, os perizeus, os heveus e os jebuseus, como Yahweh, vosso Deus, vos ordenou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'Fazei isso para que eles não vos ensinem a agir igual aos seus costumes repugnantes, assim como eles têm feito aos seus deuses. Se vós agirdes como eles, vós pecareis contra Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Quando vós sitiardes uma cidade por um longo tempo, enquanto vós fazeis guerra para capturá-la, não destruais as árvores da cidade cortando-as com um machado. Pois vós podeis comer o fruto delas, então, não as corteis. É a árvore do campo como um homem que sitiareis?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Apenas as árvores que sabeis que não dão fruto, podeis destruir e derrubar; construireis baluartes contra a cidade que fizer guerra contra vós, até que ela caia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Se alguém for encontrado morto na terra em que Yahweh, vosso Deus, vos dá para possuir, se este estiver estirado no campo, e seu agressor for desconhecido,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'então, vossos anciãos e vossos juízes sairão e medirão as distâncias do corpo até as cidades ao redor do corpo que foi morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Os anciãos da cidade que está mais perto do homem que foi morto pegarão uma novilha da manada, uma que nunca foi colocada ao trabalho, nem tenha sido usado uma canga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'Os anciãos daquela cidade trarão a novilha para o vale com água corrente, um vale que nunca tenha sido cultivado nem semeado, e quebrarão o pescoço da novilha ali no vale.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Os sacerdotes, descendentes de Levi, se aproximarão, pois deles Yahweh, vosso Deus, os tem escolhido para servi-Lo e para abençoarem o povo em nome de Yahweh; ouvi seus conselhos, pois sua palavra será o veredito em toda disputa e caso de violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Todos os anciãos daquela cidade que está mais próxima ao homem morto, lavarão suas mãos sobre a novilha que teve seu pescoço quebrado no vale;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'e responderão ao caso e dizer: \'Nossas mãos não derramaram este sangue, e nossos olhos não o viram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Perdoa, Yahweh, Teu povo Israel, a quem Tu redimiste, e não coloques culpa no sangue inocente no meio de Seu povo Israel\'. Então, o sangue derramado será perdoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Dessa forma, vós tirareis o sangue inocente de vosso meio, quando fizerdes o que é certo aos olhos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Quando fordes à batalha contra vossos inimigos e Yahweh, vosso Deus, der-lhes a vitória e os colocardes debaixo de vosso controle, então, devereis levá-los cativos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'Se virdes entre os cativos uma mulher bonita e tiverdes desejo por ela e quiserdes levá-la como esposa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'então, a levareis para vossa casa, depois, ela raspará sua cabeça e cortará suas unhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'Ela tirará as roupas que vestia quando foi levada cativa, e permanecerá na tua casa e lamentará por seu pai e sua mãe durante um mês. Depois disso, poderás dormir com ela tornando-te seu marido e ela será tua esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Mas, se não te agradares dela, então, deverá deixar-la ir onde ela desejar. Mas não poderás vendê-la por dinheiro, e não a trates como escrava, pois a humilhaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Se um homem tem duas esposas e uma é amada e a outra é odiada e ambas lhe tiverem dado filhos e o primogênito for da desprezada');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'então, no dia em que o homem fizer seus filhos herdarem o que possui, ele não poderá fazer o filho da amada o primogênito antes do filho da odiada, que, de fato, é o primogênito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Ao invés disso, ele reconhecerá o primogênito, o filho da esposa odiada, dando-lhe uma porção dobrada de tudo que ele possui; pois aquele filho é o começo de sua força; o direito da primogênitura pertence a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Se um homem tem um filho teimoso e rebelde que não obedece a voz de teu pai ou a voz de tua mãe, e que, ainda que seja corrigido, não ouvir;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'então, seu pai e sua mãe deverão pegá-lo e levá-lo para os anciãos de sua cidade e para o portão de sua cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'Eles dirão para os anciãos de sua cidade: \"Este nosso filho é teimoso e rebelde; ele não obedece nossa voz; ele é um glutão e bêbado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Então, com pedras, todos os homens de sua cidade deverão apedrejá-lo até a morte; e tu removerás o mal de vosso meio. O povo de Israel ouvirá sobre isso e temerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Se um homem cometer um pecado digno de morte, e for morto, e o tiveres pendurado em uma árvore,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'então, seu corpo não deverá permanecer na árvore por toda noite. Ao invés disso, tu certamente deverás enterrá-lo no mesmo dia, pois quem for pendurado é amaldiçoado por Deus. Obedece este mandamento para que tua terra não seja contaminada, que Yahweh, teu Deus, está te dando como herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Se vires o boi ou a ovelha de teu irmão israelita se afastar e se esconder dele, deve, certamente, trazê-los de volta para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Se o teu irmão israelita não estiver perto de ti, ou se não o conheceres, então, trarás o animal para a tua casa e ficará contigo até que ele o procure, e, então, o devolverás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Faz o mesmo com o jumento, e com as vestimentas, e com cada coisa perdida de seu companheiro Israelita; nada do que o seu companheiro tiver perdido, que tu encontrares, deve guardar para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Quando vires o jumento ou o boi de teu irmão israelita caído na estrada, certamente, deverás ajudá-lo a levantar-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'A mulher não usará roupas de homem, e nem o homem vestirá roupas de mulher; porque qualquer que fizer isso é uma abominação para Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Se encontrares um ninho de pássaros no caminho, numa árvore ou no chão, com filhotes ou com ovos dentro, e a mãe estiver sobre os filhotes ou os ovos, não pegar\'as a mãe juntamente com os filhotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Certamente, deixarás a mãe ir, mas poderás pegar os filhotes. Obedece a esta ordem de modo que te vás bem, e se prolonguem os teus dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Quando construíres uma casa nova, farás um parapeito para o telhado, para que não traga sangue para tua casa, se alguém cair de lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Não plantes tua vinha com dois tipos de semente, para que não se degenere todo o produto, tanto da semente que semeaste como da produção da vinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Não lavres a terra com um boi e um jumento juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Não te vistas com tecido que seja mistura de lã e linho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Faze franjas nos quatro cantos do manto com que te cobrires.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Supõe que um homem se case com uma mulher, durma com ela, e depois a odeie,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'acusando-a de coisas vergonhosas, colocando-lhe má reputação e dizendo: \"Tomei esta mulher, mas, quando cheguei perto dela, não encontrei nenhuma prova de virgindade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Então, o pai e a mãe da moça provarão a sua virgindade para os anciãos na porta da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'O pai da moça dirá aos anciãos: \"Entreguei minha filha a este homem como esposa, e ele a odeia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Olha, ele a tem acusado de coisas vergonhosas, dizendo: \'Não encontrei na tua filha prova de virgindade\'. Mas aqui está a comprovação da virgindade de minha filha\". Então, estenderão a roupa íntima diante dos anciãos da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Os anciãos da cidade pegarão o homem e o castigarão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'ele será multado em cem ciclos de prata, que serão entregues ao pai da menina, porque o homem colocou má reputação em uma virgem de Israel. Deverá tê-la como sua esposa; não poderá mandá-la embora durante todos os seus dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Mas, se a acusação for verdadeira, não se achando a prova da virgindade na moça,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'a levarão até a porta da casa de seus pais, e os homens de sua cidade a apedrejarão até a morte, pois a mesma cometeu uma ação vergonhosa em Israel, por agir como uma prostituta na casa de seu pai; e, assim, removereis o mal do meio de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Se um homem for encontrado dormindo com uma mulher que é casada com outro homem, então, ambos devem morrer, tanto o homem quanto a mulher, assim, removereis o mal diante de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Se houver uma moça virgem, noiva de um homem, e outro homem encontrá-la na cidade e ele dormir com ela,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'serão levados ambos à porta da cidade e apedrejados até a morte. Apedrejai a moça por não ter gritado, mesmo estando na cidade. Apedrejai o homem, por ter violado a mulher do próximo; assim, removereis o mal de diante de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Mas, se um homem encontrar no campo uma moça que é noiva, capturá-la e dormir com ela, apenas o homem que dormiu com a mesma deve morrer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Mas, à garota, não façais nada; não há nela pecado digno de morte. Neste caso, é como um homem que ataca seu vizinho e o mata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Pois ele encontrou a moça noiva em um campo; ela gritou, mas não havia ninguém para salvá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Se um homem encontrar uma moça virgem, e que não está noiva, e capturá-la, e dormir com ela e forem descobertos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'o homem que se deitou com ela deve dar cinquenta ciclos para o pai da moça, deverá tomá-la como sua esposa porque a humilhou; não poderá mandá-la embora durante todos os dias dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Um homem não deve tomar para si a mulher de seu pai; não deve tirar de seu pai os direitos do casamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Qualquer homem cujas partes íntimas foram esmagadas ou cortadas não entrará na assembleia de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Nenhuma criança ilegítima pode pertencer à assembleia de Yahweh; nem mesmo até a décima geração de seus descendentes, nenhum deles pode pertencer à assembleia de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Nenhum amonita ou moabita deve pertencer à assembleia de Yahweh; nem mesmo até a décima geração de seus descendentes, nenhum deles pode pertencer à assembleia de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Isso porque eles não foram ao vosso encontro com pão e água no caminho quando saístes do Egito, e porque contrataram contra vós Balaão, filho de Beor, de Petor, na Mesopotâmia, para vos amaldiçoar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Mas Yahweh, vosso Deus, não ouviu a Balaão; ao contrário, Yahweh, vosso Deus, transformou a maldição em benção para vós, porque Yahweh, vosso Deus, vos ama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Não procureis a paz ou prosperidade deles, durante todos os vossos dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Tu não odiarás um edomita, pois ele é teu irmão; nem odiarás um egípcio, porque foste estrangeiro em sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Os descendentes deles da terceira geração poderão pertencer à assembleia de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Quando marchardes, como um exército, contra vossos inimigos, então, guardareis de toda coisa má.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Se estiver entre vós um homem impuro por causa de algo que lhe aconteceu pela noite, então, ele sairá do acampamento do exército; ele não poderá voltar ao acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Quando entardecer, ele se banhará com água; ao pôr do sol, ele voltará para o acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Terás um lugar fora do acampamento para o qual possas ir;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'e terás, entre as tuas ferramentas, uma pá para cavar; quando abaixares para te aliviar, cavarás e, então, colocarás de volta a terra para cobrir teus excrementos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Porque Yahweh, teu Deus, anda no meio do teu acampamento para te dar vitória e entregar a ti os teus inimigos. Portanto, teu acampamento será santo, para que Ele não veja nenhuma coisa impura entre ti e não Se afaste de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Não devolverás para teu senhor um escravo que escapou dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Que ele viva contigo, em qualquer cidade que ele escolher. Não o oprimas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Não haverá prostitutas cultuais entre as filhas de Israel, nem haverá prostitutos ultuais entre aos filhos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Não trareis os salários de uma prostituta, ou o salário de um cão para a casa de Yahweh, vosso Deus, por nenhum voto; pois ambos são abominações para Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Não emprestes com juros ao teu companheiro israelita — juros sobre dinheiro, comida, ou qualquer coisa que é emprestada com juros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Para o estrangeiro, poderás emprestar com juros; mas, para teu companheiro israelita, não emprestarás com juros, para que Yahweh, teu Deus, te abençoe em tudo que colocares tua mão, na terra que vais possuir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Quando fizeres um voto para Yahweh, teu Deus, não demores em cumpri-lo, pois Yahweh, teu Deus, certamente requererá de ti; será pecado se não o cumprires.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Mas, se te abstiveres de fazer um voto, não será pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Aquilo que sair de teus lábios, observarás e cumprirás de acordo com o que prometeres a Yahweh, teu Deus, qualquer coisa que tenhas livremente prometido com tua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Quando fores à vinha de teu vizinho, comas quantas uvas quiseres, mas não coloques nenhuma no teu cesto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Quando fores à seara de teu vizinho, podes arrancar as espigas com tua mão, mas não uses foice na seara dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Quando um homem tomar uma mulher e se casar com ela, e se ela não encontrar graça aos olhos dele, por haver descoberto alguma coisa vergonhosa a seu respeito, então, escreverá para ela uma carta de divórcio e a entregará em suas mãos, mandando-a embora de sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Se ela sair da casa dele, ela poderá casar-se com outro homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Se o segundo marido a odiar e escrever-lhe uma carta de divórcio, e entregá-la na sua mão, e mandá-la para fora de sua casa; ou se este segundo marido, que a tomou para si como sua mulher, morrer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'então, seu primeiro marido, que a mandou embora, não poderá se casar novamente com essa mulher, depois que ela se tornou impura. Isto seria abominação para Yahweh. Não farás com que a terra se torne culpada; a terra que Yahweh, teu Deus, te dá por herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Quando um homem tomar uma nova mulher, ele não sairá à guerra com o exército, nem será requisitado para algum dever forçado. Ele estará livre para ficar em casa por um ano, e se alegrará com sua nova mulher.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Nenhum homem tomará como penhor as duas pedras de moinho, nem mesmo uma mó como garantia, pois, assim, estará penhorando a vida do devedor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Se um homem raptar qualquer um dos seus irmãos dentre o povo de Israel, e tratá-lo como um escravo, e vendê-lo, esse ladrão morrerá, e tu removerás o mal do meio de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Atenta sobre qualquer praga de lepra, para observares cuidadosamente, e seguires cada instrução dada a ti, as quais os sacerdotes levitas te ensinaram; como lhes ordenei, assim fareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Lembra-te do que Yahweh, teu Deus, fez a Miriã, quando saíste do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Quando deres a teu vizinho algum tipo de empréstimo, não entrarás em sua casa para tirar-lhe o penhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Ficarás do lado de fora, e o homem a quem emprestaste levará o penhor para ti até o lado de fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Se ele for um homem pobre, tu não dormirás com o penhor dele em tua posse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Sem falta, tu lhe restituirás o penhor antes do sol se pôr; então, ele poderá dormir em sua roupa e te abençoará. Isto será justiça para ti diante de Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Não oprimirás aquele servo que é pobre e necessitado, quer ele seja teu irmão israelita, ou estrangeiro na tua terra e dentro da tua cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Cada dia darás a ele o seu salário, antes do pôr do sol, pois ele é pobre e está contando com isso. Faze isto, então, para que ele não clame contra ti a Yahweh, e isto não seja um pecado cometido por ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Os pais não serão mortos por causa dos filhos, nem os filhos serão mortos por causa dos pais. Cada um morrerá pelo próprio pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Não perverterás a justiça que é devida ao estrangeiro ou ao órfão, nem tomarás a capa da viúva como um penhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Ao invés disso, trará à memória que tu foste um escravo no Egito, e que Yahweh, teu Deus, de lá te resgatou. Portanto, eu te instruo a obedecer a este mandamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Quando ajuntares tua colheita no teu campo, e esqueceres um feixe no campo, não voltarás para pegá-lo; deixa-o para o estrangeiro, para o órfão e para a viúva, para que Yahweh, teu Deus, te abençoe em toda obra das tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Quando sacudires tua oliveira, não voltarás para colher o que ficar nos ramos; isto será para o estrangeiro, para o órfão, e para a viúva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Quando colheres as uvas de tua vinha, não voltarás para colher de novo; o que ficar será para o estrangeiro, para o orfão, e para a viúva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Lembra-te que foste escravo na terra do Egito. Por isso, te instruo a obedecer a este mandamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Se houver uma disputa entre homens e eles forem para a corte, e os juízes os julgarem, então, eles absolvirão o justo e condenarão o mau.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Se o homem culpado merecer ser espancado, então, o juiz o fará deitar e ser espancado em sua presença com um número ordenado de golpes, de acordo com o seu crime.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'O juiz poderá lhe dar quarenta golpes, mas ele não poderá exceder esse número; pois, se ele exceder esse número e lhe der mais golpes, então, teu companheiro israelita será humilhado aos teus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Não amordaces o boi quando ele estiver debulhando o cereal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Se irmãos morarem juntos, e um deles morrer sem ter nenhum filho, então, a esposa do homem morto não poderá se casar com nenhum outro fora da família. Em vez disso, o irmão de seu marido dormirá com ela e a terá pra si como esposa, e fará cumprir seu dever de irmão do marido para com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Isso é para que o primogênito que ela der à luz suceda em nome do irmão morto, para que seu nome não pereça de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Mas, se o homem não desejar ter a esposa do seu irmão para si, então, ela irá ao portão, aos anciãos, e dirá: \"O irmão de meu marido se recusa a preservar o nome do seu irmão em Israel; ele não quer desempenhar a obrigação de irmão do marido para comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Então, os anciãos de sua cidade o chamarão e falarão com ele. Porém, se ele insistir e disser: \"Eu não desejo tomá-la\",');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'então, a esposa de seu irmão irá até ele na presença dos anciãos, tirará as suas sandálias dos pés, e cuspirá em sua face. Ela o responderá e dirá: \"Isso é o que se faz com quem não constrói a casa de seu irmão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Seu nome será chamado em Israel, \"A casa de quem teve sua sandália tirada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Se homens brigarem um com o outro, e a esposa de um deles vier para livrar seu marido da mão de quem o agride, e, se ela estender sua mão e pegá-lo nas partes íntimas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'então, cortarás a mão dela fora; que o teu olho não tenha piedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Não terás, em tua bolsa, pesos diferentes, um grande e um pequeno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Não terás, em tua casa, diferentes medidas, uma grande e uma pequena.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Terás um peso perfeito e justo; terás uma medida perfeita e justa, para que teus dias sejam longos na terra que Yahweh, teu Deus, te dá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Pois todos os que praticam tais coisas, todos os que agem injustamente, são abomináveis para Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Lembra-te do que Amaleque te fez na estrada enquanto saías do Egito,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'como ele te encontrou na estrada e te atacou por trás, todos os que estavam fracos na parte de trás, quando tu estavas debilitado e exausto. Ele não honrou a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Portanto, quando Yahweh, teu Deus, te der descanso de todos teus inimigos em redor, na terra que Yahweh, teu Deus, te dá para possuir como herança, não te esqueças de apagar a lembrança de Amaleque de debaixo do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Quando entrares na terra que Yahweh, teu Deus, te dará como herança, e, quando tomares posse dela e habitares nela,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'então, pegarás uma parte das primícias de toda a colheita da terra que Yahweh, teu Deus, te dá, a colocarás em um cesto e irás ao lugar que Yahweh, teu Deus, escolherá como Seu Santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Irás ao sacerdote que estiver servindo nesses dias e dirás a ele: \'Eu reconheço hoje, perante Yahweh, teu Deus, que eu cheguei à terra que Yahweh jurou aos nossos antepassados que nos daria\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'O sacerdote tomará o cesto da tua mão e o depositará diante do altar de Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'E, diante de Yahweh, teu Deus, dirás: \'Meu antepassado era um arameu errante. Desceu ao Egito e permaneceu lá, e seu povo era pequeno em número. Lá, ele se tornou uma nação grande, poderosa, e populosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Os egípcios nos trataram mal e nos afligiram. Eles nos fizeram trabalhar como escravos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Nós clamamos a Yahweh, o Deus de nossos pais. Ele ouviu a nossa voz e viu nossa aflição, nosso trabalho exaustivo e a nossa opressão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Yahweh nos tirou do Egito com mão poderosa, braço estendido, grande temor, sinais e maravilhas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'e Ele nos trouxe a este lugar e nos deu esta terra; terra da qual mana leite e mel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Eis que agora trago as primícias da colheita da terra que Yahweh me deu\'. Tu as colocarás diante de Yahweh, teu Deus, e O adorarás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'Regozijarão em todo o bem que Yahweh, teu Deus, tem feito por ti, por tua casa, pelo levita e o estrangeiro em teu meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Quando terminares de entregar todo o dízimo da tua colheita no terceiro ano, ou seja, o ano de dizimar, então, darás ao levita, ao estrangeiro, ao órfão e à viúva, para que comam dentro dos portões da cidade e se fartem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Dirás, diante de Yahweh, teu Deus: \'Trouxe da minha casa as coisas que pertecem a Yahweh, e as dei ao levita, ao estrangeiro, ao órfão e à viúva, de acordo com todos os mandamentos que Tu me destes. Não transgredi nenhum dos Teus mandamentos, nem me esqueci deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Dos dízimos, eu não comi no meu luto, e nem tirei quando eu estava impuro, nem dei nenhuma parte em honra aos mortos. Ouvi a voz de Yahweh, meu Deus; e obedeci a tudo que Tu me ordenaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Olha para cá do Lugar Santo em que vives, desde o céu, e abençoa o Teu povo, Israel, e a terra que nos deste; terra de que mana leite e mel, como juraste aos nossos pais\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Hoje Yahweh, teu Deus, está te ordenando que obedeças a esses estatutos e decretos; guardando-os e cumprindo-os com todo o teu coração e com toda a tua alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Reconheceste, hoje, que Yahweh é o teu Deus, e que andarás nos Seus caminhos e guardarás Seus estatutos, Seus mandamentos, e Seus decretos, e que ouvirás a Sua voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'E, hoje, Yahweh declarou que és o povo de Sua possessão, e que guardarás todos os Seus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'Yahweh, hoje, reconheceu que Ele te elevará sobre todas as outras nações, em louvor, reputação, e honra. Tu serás um povo separado para Yahweh, teu Deus, assim como Ele disse\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Moisés e os anciãos de Israel ordenaram ao povo e dizendo: \"Guardai todos os mandamentos que hoje eu vos ordeno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'No dia em que atravessardes o Jordão para a terra que Yahweh, vosso Deus, vos dá, levantareis algumas pedras grandes e as pintareis com cal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'Quando atravessardes, escrevereis nelas todas as palavras desta lei; vós entrareis na terra que Yahweh, vosso Deus, vos dá; uma terra de onde flui leite e mel, como Yahweh, Deus de vossos antepassados, vos prometeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Quando atravessardes o Jordão, levantareis estas pedras, que hoje vos ordeno, no monte Ebal, e as pintareis com cal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Lá, construireis um altar para Yahweh, vosso Deus, um altar de pedras. Entretanto, não usareis nenhuma ferramenta para talhar as pedras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Construireis o altar para Yahweh, vosso Deus, com pedras brutas; oferecereis ali ofertas queimadas para Yahweh, vosso Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'e sacrificareis ofertas pacíficas e comereis ali; vos alegrareis diante de Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'E escrevereis, nitidamente nas pedras, todas as palavras desta lei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Moisés e os sacerdotes, os levitas, falaram para todo o Israel, dizendo: \"Fazei silêncio e escutai, Israel: hoje vos tornastes o povo de Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Todavia, vós obedecereis à voz de Yahweh, vosso Deus, e cumprireis Seus mandamentos e estatutos, que hoje vos ordeno\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Moisés ordenou ao povo naquele mesmo dia, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, '\"Estas tribos ficarão no monte Gerizim para abençoar o povo, depois de passardes pelo Jordão: a tribo de Simeão, Levi, Judá, Isacar, José e Benjamin.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Estas são as tribos que estarão no monte Ebal para pronunciar maldições: a tribo de Rúben, Gade, Aser, Zebulon, Dã e Naftali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Os levitas responderão e dirão a todos os homens de Israel em alta voz:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, '\'Maldito o homem que esculpir ou fundir imagem. É abominação para Yahweh a obra da mão do artesão que a guarda em lugar escondido\'. Então, todo o povo responderá, dizendo: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, '\'Maldito o homem que desonrar seu pai ou sua mãe\'. Então, todo o povo responderá, dizendo: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, '\'Maldito o homem que remover as marcações da terra do seu vizinho\'. Então, todo o povo responderá, dizendo: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, '\'Maldito o homem que fizer o cego desviar-se do caminho\'. Então, todo o povo responderá: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, '\'Maldito o homem que usar a força para retirar a justiça do estrangeiro, do órfão ou da viúva\'. Então, todo o povo responderá: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, '\'Maldito o homem que se deitar com a esposa do seu pai, porque profanará os direitos do seu pai\'. Então, todo o povo responderá: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Maldito o homem que tiver relação sexual com algum animal\'. Então, todo o povo responderá: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, '\'Maldito o homem que tiver relação sexual com sua irmã, a filha de seu pai ou a filha de sua mãe\'. Então, todo o povo responderá: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, '\'Maldito o homem que dormir com sua sogra\'. Então, todo o povo responderá: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, '\'Maldito o homem que matar seu vizinho secretamente\'. Então, todo o povo responderá: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, '\'Maldito o homem que aceitar suborno para matar uma pessoa inocente\'. Então, todo o povo responderá: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, '\'Maldito o homem que não confirmar as palavras desta lei, para as cumprir\'. Então, todo o povo responderá: \'Amém!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Se, cuidadosamente, ouvires a voz de Yahweh, teu Deus, e guardares todos os Seus mandamentos que hoje te ordeno, Yahweh, teu Deus, te colocará sobre todas as outras nações da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Todas estas bençãos virão sobre ti e te alcançarão, se ouvires a voz de Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Bendito serás na cidade, e bendito serás no campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Benditos serão os frutos do teu ventre, e os frutos das tuas terras, e os frutos de teus animais, as crias dos teus gados, e as crias dos teus rebanhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Benditos serão o teu cesto e a tua vasilha de amassar pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Bendito serás quando vieres, e bendito serás quando fores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Yahweh fará teus inimigos, que se levantarem contra ti, serem derrubados diante de ti; eles sairão contra ti por um caminho, mas fugirão diante de ti por sete caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Yahweh mandará a benção ir sobre ti em teus celeiros e em tudo que tu colacares as mãos. Ele te abençoará na terra que Ele te deu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Yahweh te estabelecerá como povo santo, como Ele te jurou, se guardares os mandamentos de Yahweh, teu Deus, e andares nos Seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Todos os povos da terra verão que tu és chamado pelo nome de Yahweh, e eles terão medo de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Yahweh fará muito próspero o fruto do teu ventre, o fruto dos teus gados e o fruto do teu solo na terra que Ele jurou aos teus pais que te daria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Yahweh abrirá para ti as comportas do céu para dar a chuva para tua terra no momento certo, e abençoará todo o trabalho das tuas mãos. Emprestarás para muitas nações, mas não tomarás emprestado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Yahweh te porá como o cabeça, e não como cauda; estarás sempre por cima e não por baixo, se ouvires os mandamentos de Yahweh, teu Deus, que eu te ordeno hoje, tanto para observar como para cumpri-los,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'e, se não desviares de nenhuma das palavras que eu te ordeno hoje, nem para a direita, nem para a esquerda, nem seguir outros deuses para servi-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Se, porém, não ouvires a voz de Yahweh, teu Deus, para guardares todos os Seus mandamentos e Seus estatutos, que hoje te ordeno, então, todas essas maldições virão sobre ti e te alcançarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Maldito serás na cidade, e maldito serás no campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Malditos serão teu cesto e tua vasilha de amassar pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Malditos serão o fruto do teu ventre, o fruto das tuas terras, as crias dos teus gados, e as crias dos teus rebanhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Maldito serás quando vieres e maldito serás quando fores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Yahweh enviará sobre ti maldições, confusões, e afastará tudo em que colocares as mãos para fazer, até que sejas destruído, e até que morras, rapidamente, por causa das ações maldosas pelas quais tu Me abandonaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Yahweh te fará contrair uma praga, até que Ele te destrua na terra em que tu estás entrando para possuir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Yahweh te atacará com doenças infecciosas, com febres, inflamações, com seca e forte calor, com vento escaldante e com mofo. Estes te perseguirão até que tu morras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Teu céu, que está sobre tua cabeça, será de bronze; a terra, que está debaixo de ti, será de ferro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Yahweh fará a chuva de tua terra em pó e poeira, do céu isto descerá sobre ti, até que tu sejas destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Yahweh fará com que sejas derrotado diante dos teus inimigos; tu sairás por um caminho, e fugirás por sete caminhos. E serás motivo de horror para todos os reinos da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Teus cadaver se tornará comida para todos os pássaros dos céu e para os animais da terra; e não haverá ninguém para afugentá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Yahweh te atacará com as úlceras do Egito e com tumores, sarna e coceira, das quais não poderás ser curado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Yahweh te atacará com loucura, com cegueira, e com confusão mental.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Ficarás confuso ao meio dia, como o cego se confunde na escuridão, e tu não prosperarás em teus caminhos. Serás sempre oprimido e roubado, e não terás ninguém para te salvar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Tu casarás com uma mulher, mas outro homem dormirá com ela. Tu construirás uma casa, mas não viverás nela; plantarás videiras, mas não desfrutarás do fruto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Teu boi será morto diante dos teus olhos, mas não comerás sua carne; teu burro será levado para longe diante de ti, e não te será restituído. Tua ovelha será dada aos teus inimigos, e não terás ninguém para te ajudar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Teus filhos e tuas filhas serão dados a outros povos; teus olhos irão procurar por eles o dia inteiro, mas cansarão de esperar por eles. E não terás força em tua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'A colheita da tua terra e de todo o teu trabalho alimentará uma nação que não conheces. Serás sempre oprimido e esmagado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Então, enlouquecerás pelo que verás acontecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Yahweh te atacará nos joelhos e nas pernas com úlceras severas, das quais não poderás ser curado, da planta dos teus pés até o alto da tua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Yahweh te levará junto com o rei que colocaste sobre ti, para uma nação que nunca conheceste, nem tu e nem teus antepassados. Ali, cultuarás deuses de madeira e de pedra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Tornarás motivo de horror, um provérbio, e como escárnio entre os povos aos quais Yahweh te levará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Plantarás muitas sementes no teu campo, mas colherás pouco, pois os gafanhotos as consumirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Plantarás videiras e as cultivarás, mas não beberás nenhum vinho, nem colherás as uvas, pois os vermes as comerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Terás oliveiras em todo o teu território, mas não te ungirás com azeite, pois os frutos cairão da tua oliveira antes de amadurecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Terás filhos e filhas, mas eles não pertencerão a ti, pois serão levados cativos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Todas as tuas árvores e o todo fruto do teu solo, os gafanhotos consumirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'O estrangeiro que está em tua terra se multiplicará cada vez mais, e tu, cada vez mais, diminuirás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Ele emprestará a ti, mas não emprestarás a ele. Ele será a cabeça, e tu serás a cauda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Todas essas maldições virão sobre ti, e te perseguirão e te alcançarão até que sejas destruído. Isto acontecerá, pois não ouviste a voz de Yahweh, teu Deus, para guardar Seus mandamentos e Seus estatutos, que Ele te ordenou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Essas maldições serão como sinais e maravilhas sobre ti, e sobre teus descendentes para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Pois não cultuaste a Yahweh, teu Deus, com alegria e prazer de coração quando eras próspero,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'portanto, servirás aos inimigos que Yahweh enviará contra ti; irás servi-los com fome, com sede, em nudez, e em pobreza. Ele colocará um jugo de ferro em teu pescoço, até te destruir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Yahweh trará uma nação contra ti, de longe, dos confins da terra, como uma águia que voa para sua vítima, uma nação cuja língua não compreenderás;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'uma nação feroz de rosto, que não respeitará o velho, nem terá pena do jovem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Ela comerá os filhotes do teu gado e o fruto da tua terra até que sejas destruído. Não te deixará nenhum grão, nem vinho novo, ou azeite, nenhuma cria do teu gado ou do teu rebanho, até que te faça perecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Ela te sitiará em todos os portões da tua cidade, até que as tuas muralhas altas e fortes venham abaixo, em toda a tua terra, muralhas nas quais tu confiaste. Ela te sitiará em todos os portões da tua cidade, em toda a terra que Yahweh, teu Deus, havia te dado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Tu comerás o fruto de teu próprio corpo, a carne de teus filhos e de tuas filhas, que Yahweh, teu Deus te deu, no sitiamento e na desolação com a qual teus inimigos porão sobre ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'O homem que é gentil e refinado, ele será mesquinho para com o seu irmão e para com a mulher do seu amor, e para com qualquer filho que ele ainda tenha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Então, ele não dará para ninguém carne de seu próprio filho que ele estiver para comer, pois não sobrará nada para si mesmo, no sitiamento e na desolação que teu inimigo colocará sobre ti nos portões da tua cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'A mulher mais gentil e refinada entre vós, que não ousaria colocar a planta do seu pé no solo por causa da delicadeza e fragilidade, ela será mesquinha para com o homem do seu coração, para com seu filho, e para com sua filha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'Ela será mesquinha da placenta que sair por entre suas pernas, e dos filhos que ela gerar. Ela os comerá em privado pela falta de tudo, durante o sitiamento e desolação pelo qual teu inimigo colocará sobre ti nos portões da tua cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Se tu não guardares todas as palavras desta lei, que estão escritas neste livro, para honrar esse glorioso e temido nome Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Então, Yahweh fará que tuas pragas sejam terríveis, e as de teus descendentes; estas pragas serão grandes, de longa duração, e doenças severas, de longa duração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Novamente, Ele trará sobre ti todas as doenças do Egito que te assustaram; elas se apegarão a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Além disso, cada doença e praga que não está escrita no livro desta lei, essa também Yahweh irá trazer sobre ti até que tu sejas destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'E vós sereis poucos em número, embora vós fostes como estrelas no céu em número, pois não ouvistes a voz de Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Como Yahweh uma vez alegrou-se sobre vós em vos fazer o bem, e vos multiplicar, então, Ele se alegrará sobre vós em vos fazer morrer e em vos destruir. Vós sereis arrancados da terra que vós estais entrando para possuir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Yahweh vos dispersará entre todos os povos desde uma extremidade da terra até a outra. Lá, cultuareis outros deuses que vós não conheceis, nem vós, nem vossos antepassados, deuses de madeira e de pedra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Entre essas nações, não encontrarás facilidade e lá não haverá descanso para teus pés; ao invés disto, Yahweh te dará ali um coração angustiado, olhos sem esperança, e uma alma que chora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Tua vida estará suspensa, como por um fio, diante de ti; tu terás medo toda noite e todo dia, e não terás segurança em toda a sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Pela manhã, dirás: \'Eu gostaria que fosse noite!\' e, à noite, dirás: \'Eu gostaria que fosse manhã!\' por causa do medo em teu coração e das coisas que teus olhos terão que ver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Yahweh te fará voltar para o Egito novamente, em navios, pela rota sobre a qual Eu te disse: \'tu não verás o Egito novamente\'. Lá, oferecerás a ti mesmo para a venda para vossos inimigos, como escravos e escravas, mas ninguém vos comprará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Estas são as palavras que Yahweh ordenou a Moisés que dissesse ao povo de Israel na terra de Moabe. Palavras que foram adicionadas à aliança que Ele havia feito com os israelitas em Horebe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Moisés chamou todo Israel e disse-lhes: \"Vós vistes tudo que Yahweh fez a Faraó diante de vossos olhos na terra do Egito, com todos os seus servos, e com toda a sua terra —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'o grande sofrimento que vossos olhos viram, os sinais, e aquelas grandes maravilhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Mas, até hoje, Yahweh não vos deu um coração para entender, olhos para ver e ouvidos para ouvir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Eu vos conduzi por quarenta anos no deserto; vossas roupas não se desgastaram sobre vós, nem as sandálias em vossos pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Vós não comestes pão, nem bebestes vinho ou bebidas alcoólicas, para que soubésseis que Eu sou Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Quando viestes a este lugar, Siom, o rei de Hesbom, e Ogue, o rei de Basã, saíram contra nós para lutar, e nós os derrotamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Nós tomamos as suas terras, e as demos como herança aos rubenitas, aos gaditas, e à meia tribo de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Assim, guardai as palavras desta aliança e as cumpri, para que prospereis em tudo que fizerdes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Vós estais hoje, todos vós, diante de Yahweh, vosso Deus; vossos chefes, vossas tribos, vossos anciãos, e vossos oficiais —todos os homens de Israel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'vossos pequeninos, vossas esposas, e o estrangeiro que está entre vós em vosso acampamento, desde aqueles que cortam vossa madeira até os que tiram vossas águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Vós estais aqui para entrardes na aliança de Yahweh, vosso Deus, e no juramento que Ele hoje faz convosco,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'para hoje fazer de vós um povo Dele, e que Ele seja Deus para vós, como vos disse e jurou para vossos antepassados, Abraão, Isaque e Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Pois não é somente convosco que faço esta aliança e este juramento —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'com todos que estão conosco hoje diante de Yahweh, nosso Deus — mas também com aqueles que não estão aqui conosco hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Vós sabeis como vivemos na terra do Egito, e como passamos pelo meio das nações pelas quais passastes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Vistes as suas abominações: seus ídolos de madeira e de pedra, de prata e de ouro, que estavam entre elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Que não haja entre vós nenhum homem, nenhuma mulher, família, ou tribo cujo coração se desvie hoje de Yahweh, nosso Deus, para adorar os deuses dessas nações, para que não haja entre vós nenhuma raiz que produza veneno ou fel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'para que, quando alguém ouvir as palavras deste juramento, ela não abençoe a si mesma em seu coração, dizendo: \'eu terei paz, mesmo que eu ande na teimosia de meu coração\'. Isso destruirá a terra molhada, bem como a seca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Yahweh não o perdoará, mas, ao invés disso, a ira de Yahweh e Seu zelo fumegarão contra esse homem, e todas as maldições que estão escritas neste livro virão contra ele, e Yahweh apagará seu nome de sob o céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Yahweh o separará para a calamidade dentre todas as tribos de Israel, de acordo com todas as maldições da aliança que estão escritas neste livro da lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'A geração vindoura, vossos filhos, que virão depois de vós, e o estrangeiro que vem de uma terra distante, falarão, quando virem as pragas nesta terra e as doenças com as quais Yahweh a afligirá —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'e, quando eles virem que toda a terra se abrasou em enxofre e sal, onde nada é semeado nem dá frutos, onde nenhuma vegetação cresce, como na destruição de Sodoma e Gomorra, Admá e Zeboim, que Yahweh destruiu na Sua ira e no Seu furor —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'eles dirão, juntamente com todas as outras nações: \'Por que Yahweh fez isso com esta terra? O que significa o furor de tamanha ira?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Então, as pessoas dirão: \'Isto é porque eles abandonaram a aliança que Yahweh, o Deus de seus antepassados, fez com eles quando os tirou da terra do Egito,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'e porque eles foram e adoraram outros deuses, prostrando-se diante deles, deuses que eles não conheceram e que Ele não lhes havia dado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Por isso, a ira de Yahweh se acendeu contra esta terra, para trazer sobre ela todas as maldições escritas neste livro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Yahweh os arrancou de sua terra em ira, indignação e grande fúria, e os lançou em outra terra, como hoje se vê\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'As coisas encobertas pertencem somente a Yahweh, nosso Deus; mas as coisas reveladas pertencem a nós e a nossos descendentes para sempre, para que cumpramos todas as palavras desta lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Quando todas essas coisas te acontecerem, as bençãos e as maldições que agora coloquei diante de ti, e delas recordares mesmo em meio a outras nações que Yahweh, teu Deus, te vier a lançar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'e, quando tu retornares para Yahweh, teu Deus, obedeceres à Sua voz e seguires tudo aquilo que hoje estou te ordenando — tu e teus filhos — com todo teu coração e com toda tua alma;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'então, Yahweh, teu Deus, te libertará do cativeiro, terá compaixão de ti e, de novo, te reunirá dentre todos os povos entre os quais Yahweh, teu Deus, te havia espalhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Mesmo que alguém dos teus exilados esteja nos lugares mais distantes, de lá, Yahweh, teu Deus, o recolherá e o trará de volta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Yahweh, teu Deus, o introduzirá na terra que teus antepassados possuíram e tu a possuirás novamente. Ele te fará bem e te multiplicará mais que a teus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Yahweh, teu Deus, circuncidará o teu coração e o coração de teus descendentes, assim, amarás Yahweh, teu Deus, de todo o teu coração e de toda a tua alma, para que vivas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Yahweh, teu Deus, colocará todas essas maldições sobre teus inimigos, sobre aqueles que te odeiam e perseguem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Tu retornarás e obedecerás à voz de Yahweh e cumprirás todos os mandamentos que hoje te ordeno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Yahweh, teu Deus, trará abundância a todo o trabalho de tuas mãos, no fruto de teu ventre, no fruto dos teus animais e no fruto da tua terra, para a prosperidade; pois Yahweh voltará a alegrar-Se em ti para tua prosperidade, assim como Ele se alegrou com teus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Ele fará isso, se obedeceres à voz de Yahweh, teu Deus, guardando os Seus mandamentos e estatutos escritos neste livro da lei, se te voltares a Yahweh, teu Deus, de todo teu coração e de toda tua alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Este mandamento que, hoje, te ordeno não é muito difícil para ti, nem está fora do teu alcance.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Não está no céu, para que digas: \'Quem subirá ao céu por nós, nos trará e nos anunciará para que lhe obedeçamos?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Nem está do outro lado do mar, para que digas: \'Quem atravessará o mar por nós, nos trará e nos anunciará para que o obedeçamos?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Mas a palavra está muito próxima a ti, na tua boca e no teu coração, para que lhe obedeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Vê, hoje coloquei diante de ti a vida e o bem, a morte e o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Se obedeceres aos estatutos que hoje te ordeno, para amar Yahweh, teu Deus, andar nos Seus caminhos e guardar Seus mandamentos, Seus estatutos e Seus preceitos, então, tu viverás e te multiplicarás, e Yahweh, teu Deus, abençoará a ti e a terra que estás tomando posse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Mas, se teu coração se desviar e não quiseres ouvir e, ao invés disso, te afastares e adorar outros deuses,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'então, hoje, te declaro que, certamente, perecerás; não se prolongarão teus dias na terra em que entrarás para possuir, depois que atravessares o Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Chamo, hoje, céus e terra como testemunhas contra ti, que coloquei diante de ti a vida e a morte, as bençãos e as maldições; portanto, escolhe a vida para que vivas, tu e a tua descendência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Faz isto para amar a Yahweh, teu Deus, para obedeceres à Sua voz e te apegares a Ele; pois Ele é a tua vida e a extensão dos teus dias; faz isto para que vivas na terra que Yahweh jurou dar a teus antepassados: Abraão, Isaque e Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Moisés foi falar a todo o Israel estas palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Ele disse: \"Tenho, agora, cento e vinte anos de idade; já não posso mais ir e vir. Yahweh me disse: \'Não atravessarás o Jordão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Yahweh, teu Deus, irá à tua frente; Ele destruirá as nações diante de ti, e tu as possuirás. Josué irá à tua frente, como Yahweh falou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Yahweh lhes fará como fez com Siom e Ogue, os reis do amorreus, e com as terras deles, que destruiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Yahweh vos dará vitória sobre eles quando os encontrardes em batalha, e fareis com eles o que vos ordenei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Sede fortes e corajosos, não temais, nem vos apavoreis, pois Yahweh, vosso Deus, é quem irá convosco. Ele não falhará nem vos abandonará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Moisés chamou Josué e, na presença de todo o Israel, disse-lhe: \"Sê forte e corajoso, pois irás com este povo para a terra que Yahweh jurou dar aos teus antepassados; e tu o farás herdá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Yahweh irá à tua frente. Ele será contigo, não falhará, nem te abandonará. Não tenhas medo, nem te espantes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Moisés escreveu esta lei e a entregou aos sacerdotes, filhos de Levi, que carregavam a Arca da Aliança de Yahweh; ele também deu cópias a todos os anciãos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Moisés ordenou-lhes, dizendo: \"No final de cada sete anos, no tempo do cancelamento das dívidas, durante a Festa dos Tabernáculos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'quando todo o Israel aparecer diante de Yahweh, teu Deus, no lugar que Ele escolherá como Santuário, lerás esta lei diante de todo o Israel, para que ouçam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Reuni o povo, os homens, as mulheres, as crianças, e o estrangeiro que habita dentro dos portões das vossas cidades, para que ouçam e aprendam e, assim, honrem a Yahweh, vosso Deus, e guardem todas as palavras desta lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Fazei isto para que vossos filhos, que ainda não a conhecem, ouçam e aprendam a honrar Yahweh, vosso Deus, enquanto habitardes sobre a terra que ireis possuir quando atravessardes o Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Yahweh disse a Moisés: \"Vê, aproxima-se o dia em que morrerás. Chama Josué e apresentai-vos na Tenda do Encontro, para que Eu lhe ordene\". Moisés e Josué apresentaram-se na Tenda do Encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Yahweh apareceu na Tenda, numa coluna de nuvem. A coluna de nuvem pairou sobre a entrada da tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Yahweh disse a Moisés: \"Eis que descansarás com teus pais; os membros do povo se levantarão e agirão como uma prostituta, seguindo os deuses estranhos da terra para onde vão. Eles Me abandonarão e quebrarão a Aliança que fiz com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Então, naquele dia, Minha ira se acenderá contra eles, e os abandonarei. Esconderei deles a Minha face e serão devorados. Muitos desastres e problemas os acharão, e dirão naquele dia: \'Será que esses desastres vieram sobre nós por que o nosso Deus não está no nosso meio?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Com certeza, esconderei Minha face deles naquele dia, por causa da maldade que farão, voltando-se para outros deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Por isso, agora escrevei esta canção para vós mesmos e ensinai-a ao povo de Israel. Colocai-a em suas bocas, para que esta canção seja minha testemunha contra o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Pois, quando Eu os trouxer para a terra que jurei dar aos seus antepassados, a terra de que mana leite e mel, e, quando tiverem comido e ficarem satisfeitos e gordos, então, se voltarão a outros deuses para os servir. Eles Me desprezarão e quebrarão a Minha aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Quando muitos males e problemas atingirem este povo, esta canção será como testemunha diante deles, pois não será esquecida da boca de seus descendentes, porque Eu sei, Eu conheço hoje, os planos que estão formando, mesmo antes de tê-los trazido para a terra que lhes prometi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Então, Moisés escreveu esta canção no mesmo dia e a ensinou ao povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Yahweh ordenou a Josué, filho de Num, dizendo: \"Sê forte e corajoso, pois farei o povo de Israel entrar na terra que lhes jurei, e serei contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'E aconteceu que, quando Moisés terminou de escrever as palavras desta lei num livro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'ordenou aos levitas que carregassem a Arca da Aliança de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, '\"Tomai este livro da lei e colocai ao lado da Arca da Aliança de Yahweh, vosso Deus, para que esteja lá como testemunha contra vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Porque conheço vossa rebelião e teimosia. Se tendes sido rebeldes contra Yahweh enquanto estou convosco, quanto mais serão depois que eu morrer?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Reuni a mim todos os anciãos das vossas tribos e vossos oficiais, para que fale estas palavras aos seus ouvidos, e chame os céus e a terra como testemunhas contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Porque sei que, após a minha morte, certamente, vos corrompereis e desviareis do caminho que vos ordenei. Problemas virão sobre vós nos dias futuros. Isto acontecerá porque fareis o que é mau aos olhos de Yahweh, para provocar-Lhe à ira, através do trabalho de vossas mãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Moisés recitou aos ouvidos de toda a assembleia de Israel as palavras desta canção, até o seu fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Escutai, ó céus, e deixai-me falar. Deixai a terra ouvir as palavras de minha boca;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'e meus ensinamentos caírem como a chuva, e meu discurso descer como o orvalho, como a garoa sobre a grama macia, e como chuva sobre a relva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Pois eu proclamarei o nome de Yahweh, e engrandecerei o nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Ele é a Rocha, Suas obras são perfeitas; todos os Seus caminhos são justos. Ele é Deus fiel, em quem não há iniquidade. Ele é justo e reto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'O povo corrompeu-se contra Ele. Eles não são Seus filhos. Esta é a sua desgraça. São uma geração perversa e depravada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'É assim que recompensas Yahweh, povo tolo e insensato? Não é Ele teu pai, que te criou? Ele te fez e te estabeleceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Lembra dos dias remotos, considera as gerações passadas. Pergunta a teu pai e Ele te mostrará, aos teus anciãos e eles te contarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Quando o Altíssimo dava a cada nação a sua herança — quando dividiu os homens e estabeleceu os limites de cada povo, e também fixou o número dos seus deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Pois a porção de Yahweh é Seu povo; Jacó é a Sua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Ele o encontrou em uma terra deserta, no deserto estéril de ventos uivantes; Ele o protegeu e cuidou dele; Ele o guardou como a pupila de Seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Como a águia que guarda seu ninho, e voa ao redor de seus filhotes, assim Yahweh abriu Suas asas, tomou-os e os carregou sobre elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Yahweh sozinho o conduziu; nenhum deus estrangeiro o acompanhou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Ele o fez cavalgar sobre as alturas da terra, e o alimentou com os frutos do campo; alimentou-o com mel da rocha, e azeite da pedra dura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Ele comeu manteiga das vacas e tomou leite das ovelhas, com a gordura dos cordeiros, dos carneiros de Basã e dos bodes, com o melhor do trigo — e bebeste o vinho mais fino feito com o suco das uvas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Mas Jesurum engordou e deu coices — tu engordaste, te engrossaste e te saciaste — ele abandonou a Deus, que o fez, e desprezou a Rocha da sua salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Eles fizeram Yahweh ter ciúmes dos deuses estranhos, e O enfureceram com suas abominações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Eles sacrificaram aos demônios, e não a Deus — deuses desconhecidos, que haviam aparecido recentemente, que seus pais não temiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Tu abandonaste a Rocha que te gerou e te esqueceste do Deus que te formou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Yahweh viu isto e os desprezou, porque Seus filhos e Suas filhas O provocaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, '\"Eu esconderei deles a Minha face\", Ele disse: \"E verei qual será o seu fim, pois eles são uma geração perversa de filhos infiéis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Eles provocaram o Meu ciúme com aquilo que não é deus, e iraram-Me com seus ídolos sem valor. Portanto, Eu os provocarei ciúmes com aquele que não é povo; Eu os irritarei com uma nação insensata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Porque um fogo se acendeu na Minha ira, e queimará até o mais baixo Sheol; devorará a terra e a sua colheita; queimará os alicerces dos montes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Amontoarei desastres sobre eles, e esgotarei contra eles Minhas flechas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Serão devastados pela fome, e consumidos pelo calor ardente e terrível destruição; Eu enviarei contra eles animais selvagens, e animais venenosos que rastejam no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'A espada devastará por fora, e por dentro das casas, o terror. Destruirá tanto os jovens quanto as virgens; tanto o bebê de peito quanto o ancião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Eu disse que os espalharia por todos os cantos, e apagaria sua memória dentre os homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Se não receasse a provocação do inimigo, para que seus adversários não dissessem, iludindo-se: \'Nossa mão está erguida; não foi Yahweh quem fez tudo isso\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Pois Israel é uma nação sem sabedoria, e não há neles entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Se fossem sábios, entenderiam isso e considerariam seu destino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Como poderia um só perseguir mil, e dois pôr em fuga dez mil, a não ser que sua Rocha os tivesse vendido, e Yahweh os tivesse entregado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Pois a nossa Rocha não é como a dos nossos inimigos, como eles mesmos admitem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Pois suas vinhas vêm das vinhas de Sodoma e dos campos de Gomorra; suas uvas são venenosas, e seus cachos são amargos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Seus vinhos são veneno de serpentes e peçonha mortal de víboras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Não tenho Eu guardado esses planos secretamente, selado em Meus tesouros?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Minha será a vingança e a retribuição, quando seus pés tropeçarem; pois o dia do desastre está próximo, e as coisas que virão aproximam-se rapidamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Pois Yahweh fará justiça ao Seu povo, e terá compaixão dos Seus servos, quando Ele vir que o poder deles se foi, e não sobrou ninguém, nem escravos, nem livres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Então, Ele dirá: \"Onde estão seus deuses, a rocha em que se refugiavam? —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'os deuses que comiam a gordura de seus sacrifícios e bebiam o vinho de suas ofertas de libação? Que se levantem para ajudá-los, que sejam sua proteção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Vede agora que Eu, Eu mesmo, sou Deus, e não há outro além de Mim; Eu mato e faço viver; Eu firo e curo; E não há quem vos possa salvar da Minha mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Pois Eu levanto Minha mão ao céu e digo: Assim como Eu vivo para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'quando Eu afiar Minha espada reluzente, e quando Minhas mãos começarem a trazer justiça, Eu retribuirei vingança aos Meus inimigos, e recompensarei os que Me odeiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Embriagarei Minhas flechas com sangue, e a Minha espada devorará carne com o sangue dos mortos e cativos, e das cabeças dos líderes inimigos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Alegrai-vos, ó nações, com o povo de Deus, pois Ele vingará o sangue de vossos servos; Ele fará vingança aos vossos inimigos e Ele fará expiação por Sua terra e Seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Moisés veio e recitou todas as palavras deste cântico na presença do povo, ele e Josué, filho de Num.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Então, Moisés terminou de recitar essas palavras a todo Israel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'e disse-lhes: \"Aplicai vossas mentes a todas as palavras que hoje vos anuncio, para que ordeneis a vossos filhos que cumpram todas as palavras desta lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Pois esta palavra não é sem valor para ti, porque é a vossa vida, e, através dela, prolongareis vossos dias nesta terra, que atravessareis o Jordão para possuir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Yahweh falou a Moisés naquele mesmo dia:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '\"Sobe as montanhas de Abarim, ao monte Nebo, que está na terra de Moabe, em frente a Jericó. Tu verás a terra de Canaã, que Eu dou como propriedade ao povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Tu morrerás na montanha que subirás, e serás reunido ao teu povo, assim como teu irmão, Arão, morreu no monte Hor e foi reunido ao seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Pois fostes infiéis a Mim, em meio ao povo de Israel, nas águas de Meribá em Cades, no deserto de Zim; porque tu não Me santificaste entre o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Tu verás a terra diante de ti, mas tu não entrarás na terra que Eu dou ao povo de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Esta é a benção com a qual Moisés, o homem de Deus, abençoou o povo de Israel antes de sua morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Ele disse: \"Yahweh veio do Sinai e Se levantou de Seir sobre eles. Ele raiou do monte Parã, e veio com dez mil dos Seus santos. Fogo saía da Sua mão direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'De fato, Ele ama Seu povo; todos os Seus santos estão em Suas mãos e estão ajoelhados aos Seus pés; cada um receberá Suas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Eu, Moisés, vos ordeno uma lei, uma herança para a assembleia de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Então, Yahweh se tornou o Rei em Jesurum, quando os cabeças do povo reuniram todas as tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Deixa que Rúben viva e não morra, mas que sejam poucos os seus homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Esta é a benção para Judá. Moisés disse: \"Ouve, Yahweh, a voz de Judá, que Tu o reúnas ao seu povo novamente. Lutes por ele; sejas um socorro contra seus inimigos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Sobre Levi, Moisés disse: \"O Teu Tumim e o Teu Urim pertencem ao Teu homem fiel, aquele que colocaste em teste em Massá, com quem lutaste nas águas de Meribá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'O homem que disse sobre seu pai e mãe: \"Nunca os vi\". Nem reconheceu seus irmãos, ou nem contou seus próprios filhos. Pois guardou a Tua palavra e manteve a Tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Ele ensina a Jacó Teus decretos e, a Israel, Tua lei. Ele colocará incenso diante de Ti e ofertas completamente queimadas em Teu altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Abençoa, Yahweh, suas possessões e aceita as obras das suas mãos. Fere os lombos daqueles que se levantam contra ele, daqueles do povo que o odeiam, para que não se levantem novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Sobre Benjamim, Moisés disse: \"O amado de Yahweh habita em segurança ao lado dele; Yahweh o cercará o dia todo, e ele vive entre os braços de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Sobre José, Moisés disse: \"Que sua terra seja abençoada por Yahweh, com as preciosas coisas dos céus, com o orvalho e com as profundezas que estão por baixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Que sua terra seja abençoada com as coisas preciosas da colheita feita do sol. Com as coisas preciosas dos produtos dos meses,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'com as coisas mais excelentes dos montes antigos e com as coisas preciosas das eternas colinas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'Que sua terra seja abençoada com as coisas preciosas da terra e sua abundância e com a benevolência Daquele que estava na sarça. Deixa que a benção venha sobre a cabeça de José e sobre o topo da cabeça do que foi príncipe sobre seus irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Como o primogênito de um touro, ele é majestoso e seus chifres são os chifres de um touro selvagem. Com eles, irá pressionar os povos, todos eles, até os confins da terra. Estes são os dez milhares de Efraim; estes são os milhares de Manassés\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Sobre Zebulom, Moisés disse: \"Alegra-te Zebulom, em tua saída, e tu, Issacar, em tuas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Eles chamarão os povos para as montanhas. Lá, eles vão oferecer sacrifícios de justiça. Pois sugarão a abundância dos mares e da areia da praia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Sobre Gade, Moisés disse: \"Seja abençoado aquele que ampliar os domínios Gade. Ele habitará como a leoa e arrancará um braço ou uma cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Ele proveu a melhor parte para si mesmo, pois era a porção do líder da terra reservada. Ele veio com os cabeças do povo. Ele carregou a justiça de Yahweh e os decretos de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Sobre Dã, Moisés disse: \"Dã é um filhote de leão que salta de Basã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Sobre Naftali, Moisés disse: \"Naftali, satisfeito com favores e cheio das bençãos de Yahweh, toma posse da terra do oeste e sul\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Sobre Aser, disse Moisés: \"Abençoado seja Aser, mais que os outros filhos; que ele seja aceitável para seus irmãos e que ele mergulhe seu pé em azeite de oliva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Que as pilastras da cidade sejam de ferro e bronze; assim como os teus dias, tão longa será tua segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Não há outro como Deus, Jesurum — o mais alto, que cavalga sobre os céus para te ajudar, e, na Sua majestade, sobre as nuvens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'O eterno Deus é o refúgio e, abaixo, estão Seus braços eternos. Ele derrotará o inimigo diante de vós, e dirá: \'Destrói-no!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Habitará Israel em segurança. A fonte de Jacó estava segura em uma terra de grãos e vinho novo; de fato, que os céus gotejem o orvalho sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Abençoado és tu, Israel! Quem é como tu, um povo salvo por Yahweh, o escudo do teu socorro, e a espada de tua majestade? Teus inimigos tremerão diante de ti. Tu acabarás com seus lugares altos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Moisés subiu das planícies de Moabe ao monte Nebo, ao cume do Pisga, que fica de frente para Jericó. Ali, Yahweh mostrou-lhe toda a terra, desde Gileade até Dã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'toda Naftali, e a terra de Efraim e Manassés, e toda a terra de Judá, até o mar ocidental,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'e o Neguebe, e a planície do vale de Jericó, a cidade das palmeiras, até Zoar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Yahweh lhe disse: \"Esta é a terra que prometi a Abraão, a Isaque e a Jacó, dizendo: \'À tua descendência Eu a darei\'. Eu te fiz vê-la com teus olhos, mas não irás para lá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Então, Moisés, servo de Yahweh, morreu ali na terra de Moabe, conforme Yahweh havia prometido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Yahweh enterrou-o no vale, nas terras de Moabe, de frente para Bete-Peor, mas ninguém conhece o local da sua sepultura até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Moisés tinha cento e vinte anos quando morreu, mas enxergava bem e não havia perdido o seu vigor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'O povo de Israel lamentou por Moisés por trinta dias nas planícies de Moabe, e, então, acabaram os dias de luto por Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Josué, filho de Num, estava cheio do espírito de sabedoria, pois Moisés havia imposto suas mãos sobre ele. O povo de Israel o ouviu, e obedeceu ao que Yahweh ordenara a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Nunca mais, surgiu em Israel um profeta como Moisés, a quem Yahweh conhecia face a face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Nunca houve outro profeta igual a ele em todos os sinais e maravilhas que Yahweh o enviou para realizar na terra do Egito, a Faraó, a todos os seus servos, e a toda a sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'E jamais houve um profeta como ele nas grandes e terríveis coisas que ele fez aos olhos de todo Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Aconteceu que, após a morte de Moisés, servo de Yahweh, Yahweh falou a Josué, filho de Num, auxiliar de Moisés, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, '\"Moisés, meu servo, está morto. Prepara-te agora, levanta-te, atravessa esse Jordão, tu e todo esse povo, para a terra que estou dando ao povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Todo o lugar onde pisar a planta dos vossos pés, Eu vos darei, como prometi a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Desde o deserto e Líbano até o grande rio, o Eufrates, todas as terras dos heteus até o mar Grande, onde o sol se põe, pertencerão a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Ninguém será capaz de ir contra ti todos os dias de tua vida. Estarei contigo como estive com Moisés. Não te abandonarei e nem te deixarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Sê forte e corajoso. Porque tu farás este povo herdar a terra que prometi dar a teus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Sê forte e muito corajoso. Sê cuidadoso para obedecer à lei que meu servo Moisés te ordenou. Não te desvies dela, nem para a direita nem para a esquerda. Assim, serás bem sucedido aonde quer que fores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Tu sempre falarás sobre este livro da lei. Meditarás nele dia e noite, para que possas obedecer, por completo, o que nele está escrito. Então, tu serás próspero e bem sucedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Não te ordenei Eu? Sê forte e corajoso! Não tenhas medo. Não percas a coragem. Yahweh, teu Deus, é contigo aonde quer que andares\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Então, Josué ordenou aos líderes do povo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, '\"Ide através do acampamento e ordenai às pessoas: \'Preparai provisões para vós mesmos. Em três dias, vós atravessareis o Jordão e possuireis a terra que Yahweh, nosso Deus, está dando para nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Aos rubenitas, aos gaditas e à metade da tribo de Manassés, Josué disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, '\"Lembrai-vos da palavra que Moisés, o servo de Yahweh, ordenou-vos quando disse: \'Yahweh, vosso Deus, está vos dando descanso e esta terra\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Vossas esposas, crianças e vossos animais domésticos ficarão na terra que Moisés vos deu além do Jordão. Mas vossos guerreiros irão convosco e com vossos irmãos e os ajudarão');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'até que Yahweh tenha dado descanso a vossos irmãos, assim como deu a vós. Eles também tomarão posse da terra que Yahweh, vosso Deus, lhes dará. Depois, voltareis para a vossa própria terra e a possuireis, a terra que Moisés, servo de Yahweh, vos deu além do Jordão, onde nasce o sol\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'E eles responderam a Josué, dizendo: \"Tudo o que tu nos ordenaste, nós o faremos e iremos para onde quer que tu nos enviares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Obedeceremos a ti assim como obedecemos a Moisés. Que somente Yahweh, teu Deus, esteja contigo, assim como esteve com Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Quem se rebelar contra teus comandos e desobedecer às tuas palavras, será morto. Apenas sê forte e corajoso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Então, Josué, filho de Num, secretamente enviou, de Sitim, dois homens como espiões. Ele disse: \"Ide, observai a terra, especialmente Jericó\". Eles foram e chegaram na casa de uma prostituta, cujo nome era Raabe, e eles dormiram ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Disseram ao rei de Jericó: \"Vê, homens de Israel vieram aqui para espionar a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'O rei de Jericó mandou dizer a Raabe: \"Traz os homens que foram à tua casa, pois eles vieram para espionar toda a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Mas a mulher pegou os dois homens e os escondeu. Ela respondeu: \"Sim, os homens vieram a mim, mas eu não sabia de onde eles eram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Foram embora quando estava escurecendo, quando o portão da cidade estava fechando. Não sei para onde foram. Talvez os alcançareis se fordes, rapidamente, atrás deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Mas ela os havia colocado no terraço, e os escondido com talos de linho que havia arrumado ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Então, os homens os perseguiram pelo caminho do rio Jordão, e os portões foram fechados assim que os perseguidores saíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Os homens ainda não haviam se deitado para dormir quando ela subiu ao terraço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'Disse: \"Eu sei que Yahweh vos deu esta terra, e que grande temor por vós veio sobre nós. Todos os que vivem nesta terra ficarão desencorajados diante de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Nós ouvimos como Yahweh secou as águas do mar Vermelho para vós quando saístes do Egito. E ouvimos o que fizestes com os dois reis dos Amorreus, do outro lado do Jordão — Siom e Ogue — a quem destruístes completamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Assim que ouvimos isso, nossos corações derreteram-se, e não restou coragem em ninguém —porque Yahweh, vosso Deus, é Deus em cima nos céus e embaixo na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Agora, peço que jurai-me por Yahweh que, como fui bondosa convosco, vós também sereis bondosos para com a casa de meu pai. Dai-me um sinal claro');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'de que protegereis as vidas de meu pai, minha mãe, meus irmãos, minhas irmãs e de todas as suas famílias, e nos salvareis da morte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Os homens disseram a ela: \"Nossas vidas pela tua até a morte! Se não falares sobre nosso acordo, então, quando Yahweh nos der esta terra, seremos misericordiosos e fiéis a ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Então, ela os deixou descer pela janela usando uma corda. A casa em que ela morava havia sido construída nos muros da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Ela lhes disse: \"Ide para os montes e vos escondei, ou os perseguidores vos encontrarão. Escondei-vos lá por três dias, até que os perseguidores tenham retornado. Depois, segui vosso caminho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Então, os homens lhe disseram: \"Nós não ficaremos presos às promessas do juramento que nos fizeste jurar, se não fizeres isto:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Quando chegarmos à terra, tu amarrarás esta corda escarlate na janela pela qual descemos, e reunirás na casa contigo, teu pai, tua mãe, teus irmãos e todos os descendentes de teu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Quem passar das portas da tua casa para a rua, seu sangue estará sobre sua própria cabeça, e não teremos culpa. Porém, se uma mão for posta sobre qualquer um que esteja em tua casa, seu sangue estará sobre nossas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Mas, se denunciares nosso trato, nós não estaremos ligados à promessa que nos fizeste jurar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Raabe respondeu: \"Que seja feito como vós dissestes\". E eles foram embora. Depois, ela amarrou a corda escarlate na janela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Eles foram embora e subiram a colina, e lá permaneceram por três dias, até que os perseguidores retornaram. Estes haviam procurado por toda a estrada e nada encontraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Os dois homens retornaram, fizeram a travessia, e voltaram a Josué, filho de Num, e lhe contaram tudo o que havia acontecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'E eles disseram a Josué: \"Verdadeiramente, Yahweh nos deu esta terra. Todos os seus habitantes estão tremendo de medo por nossa causa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Josué levantou-se de madrugada e todos partiram de Sitim. Chegaram ao rio Jordão, ele e todo povo de Israel, e acamparam ali antes de atravessá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Após três dias, os oficiais passaram no meio do acampamento');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'e ordernaram ao povo, dizendo: \"Quando virdes a Arca da Aliança de Yahweh, vosso Deus, carregada pelos sacerdotes levitas, partireis deste lugar e a seguireis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Entretanto, conservai uma distância de dois mil côvados entre vós e ela. Não vos aproximeis dela. Assim, sabereis qual caminho seguir, caminho pelo qual nunca passastes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Josué disse ao povo: \"Santificai-vos porque amanhã Yahweh fará maravilhas no meio de vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Depois Josué disse aos sacerdotes: \"Levantai a Arca da Aliança e passai em frente ao povo\". Então, eles levantaram a Arca da Aliança e foram andando adiante do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Yahweh disse a Josué: \"Neste dia, te farei um grande homem aos olhos de todo o povo de Israel, para que vejam que estou contigo, como estive com Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Ordenarás aos sacerdotes que carregam a Arca da Aliança: \'Quando chegardes à beira das águas do rio Jordão, ali parareis”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Então, Josué disse ao povo de Israel: \"Chegai-vos e escutai as palavras de Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Deste modo, reconhecereis que o Deus Vivo está no meio de vós e, certamente, expulsará da vossa presença os cananeus, os heteus, os heveus, os perizeus, os girgaseus, os amorreus e os jebuseus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Eis que a Arca da Aliança do Senhor de toda a terra passará à vossa frente no Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Agora escolhei doze homens das tribos de Israel, um de cada tribo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Quando a planta dos pés dos sacerdotes que carregam a arca de Yahweh, o Senhor de toda a terra, tocarem as águas do Jordão, estas serão separadas; e ainda que as águas que fluem rio acima parem de fluir, formarão uma represa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Então, quando o povo levantou acampamento para atravessar o Jordão, os sacerdotes que carregavam a Arca da Aliança foram à frente do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Assim que os carregadores da Arca chegaram ao Jordão, e seus pés tocaram nas águas (o Jordão transbordava pelas suas margens durante a colheita),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'as águas que vinham de cima pararam e formaram uma represa a uma longa distância, na altura de Adã, cidade ao lado de Zaretã, e até por todo o caminho abaixo do mar da Arabá, que é o mar Morto. E o povo atravessou diante de Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Os sacerdotes que carregavam a Arca da Aliança de Yahweh ficaram parados no leito seco, no meio do Jordão, enquanto todo o povo de Israel atravessava em terra seca, até que todos acabassem de passar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Quando todo o povo cruzou o Jordão, Yahweh disse a Josué:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, '\"Escolhe doze homens dentre o povo, um homem de cada tribo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'Ordena-lhes: \'Pegai doze pedras do meio do Jordão, de onde os sacerdotes estão parados em terra seca, trazei-as convosco e deixai-as no lugar onde passareis esta noite\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Então, Josué chamou os doze homens que escolhera dentre as tribos de Israel, um de cada tribo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'Josué disse-lhes: \"Ide adiante da Arca de Yahweh, vosso Deus, no meio do Jordão. Cada um de vós tomará uma pedra em vossos ombros, de acordo com o número de tribos do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Isto será um sinal no meio de vós, e quando, nos dias vindouros, vossos filhos perguntarem: \'O que estas pedras significam para vós?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'direis a eles: \'As águas do Jordão foram divididas diante da Arca da Aliança de Yahweh. Quando esta passou pelo Jordão, as águas do Jordão foram divididas. Assim, estas pedras serão um memorial para o povo de Israel, eternamente”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'O povo de Israel fez como Josué ordenara: eles pegaram doze pedras do meio do Jordão, assim como Yahweh dissera a Josué. Então, eles as contaram conforme o número de tribos do povo de Israel, carregaram-nas consigo para o lugar onde acamparam, e as colocaram ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Então, Josué erigiu doze pedras do meio do Jordão, no lugar em que os pés dos sacerdotes que carregavam a Arca da Aliança pararam. O memorial está lá até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Os sacerdotes que carregavam a Arca permaneceram no meio do Jordão até que tudo o que Yahweh ordenara que Josué dissesse ao povo fosse cumprido, de acordo com tudo o que Moisés havia ordenado a Josué. O povo se apressou e atravessou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Quando todo o povo terminou de atravessar, a Arca de Yahweh e os sacerdotes atravessaram, diante do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'A tribo de Rúben, a tribo de Gade, e a meia tribo de Manassés passaram como um exército, diante do povo de Israel, assim como Moisés dissera a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Cerca de quarenta mil homens equipados para a guerra passaram diante de Yahweh, para a batalha nas planícies de Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Naquele dia, Yahweh fez Josué grande aos olhos de todo o Israel. Eles o honraram, assim como honraram a Moisés, por todos os dias da sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Assim Yahweh falou a Josué:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, '\"Ordena aos sacerdotes que carregam a Arca do Testemunho que saiam do Jordão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Então, Josué ordenou aos sacerdotes: \"Saí do Jordão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Quando os sacerdotes que carregavam a Arca da Aliança de Yahweh saíram do meio do Jordão, e as solas de seus pés pisaram em terra seca, as águas do Jordão retornaram ao seu lugar e transbordaram até as margens, exatamente como eram quatro dias antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'O povo saiu do Jordão no décimo dia do primeiro mês. Eles ficaram em Gilgal, a leste de Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'As doze pedras que haviam sido tiradas do Jordão, Josué as empilhou em Gilgal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Ele disse ao povo de Israel: \"Quando vossos descendentes perguntarem aos seus pais nos tempos vindouros: \'O que são estas pedras?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'dizei a vossos filhos: \'Israel atravessou o Jordão em terra seca\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Yahweh, vosso Deus, fez secar as águas do Jordão para vós, até que passásseis, conforme Yahweh, vosso Deus, fez com o mar Vermelho, o qual secou para nós, até que passássemos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'para que, assim, todos os povos da terra saibam que a mão de Yahweh é poderosa, e vós honrareis Yahweh, vosso Deus, eternamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Quando todos os reis dos amorreus, do lado oeste do Jordão, e todos os reis dos cananeus, que estavam ao longo da costa do grande mar, ouviram que Yahweh havia secado as águas do Jordão até que o povo de Israel tivesse atravessado, seus corações se derreteram, e já não havia mais neles espírito algum, por causa do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Naquele tempo, Yahweh disse a Josué: \"Faze facas de pedra e circuncida, mais uma vez, todos os homens de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Então, Josué fez facas de pedras e circuncidou os filhos de Israel em Gibeate-Haaralote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Esta é a razão pela qual Josué os circuncidou: todos os filhos de Israel que vieram do Egito, incluindo os homens de guerra, haviam morrido no deserto durante a peregrinação, depois de terem saído do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Embora todos os machos que haviam vindo do Egito tivessem sido circuncidados, nenhum dos meninos nascidos no deserto havia sido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Pois o povo de Israel peregrinou pelo deserto por quarenta anos, até que todas as pessoas, isto é, todos os homens de guerra que haviam saído do Egito morreram, pois eles não obedeceram à voz de Yahweh. E Yahweh jurou-lhes que não veriam a terra que Ele havia jurado aos seus antepassados que nos daria, uma terra que mana leite e mel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Foram seus filhos, os que Yahweh levantou em seu lugar, que Josué circuncidou, pois eles ainda não haviam sido circuncidados no caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'E, quando foram todos circuncidados, permaneceram no acampamento até sararem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'E Yahweh disse a Josué: \"Neste dia, Eu removi de vós toda a vergonha do Egito\". Por isso, aquele lugar é chamado Gilgal, até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'O povo de Israel acampou em Gilgal. Eles celebraram a Páscoa no décimo quarto dia do mês, ao anoitecer, nas planícies de Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'E, no dia seguinte à Páscoa, comeram alguns dos frutos da terra: pães sem fermento e cereais tostados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Um dia após eles comerem dos frutos da terra, o maná cessou. Já não havia mais maná para o povo de Israel, mas, naquele ano, eles comeram dos frutos da terra de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Quando Josué estava perto de Jericó, ele ergueu seus olhos e viu, e eis um homem em pé na sua frente; ele possuía uma espada desembainhada na mão. Josué foi até ele, e disse: \"És tu por nós ou pelos nossos adversários?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Ele respondeu: \"Nenhum dos dois, pois Eu sou Chefe do exército de Yahweh\". Então, Josué prostrou-se, com o rosto no chão, para O adorar e perguntou-Lhe: \"O que meu Senhor ordena ao Seu servo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Então, o Chefe do exército de Yahweh disse a Josué: \"Tira as sandálias dos teus pés, porque o local que pisas é santo\". E Josué assim o fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Ora, todas as entradas de Jericó estavam fechadas por causa do exército de Israel. Ninguém saía, nem entrava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Yahweh disse a Josué: \"Vê! Eis que Eu entreguei nas tuas mãos Jericó, o seu rei e os seus soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Vós marchareis ao redor da cidade, todo homem de guerra, rodeando-a uma vez ao dia. Fazei isto durante seis dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Sete sacerdotes levarão sete trombetas de chifre de carneiro adiante da Arca. No sétimo dia, marchareis ao redor da cidade sete vezes, e os sacerdotes tocarão fortemente as trombetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Então, eles tocarão longamente a trombeta de chifre de carneiro, e, quando ouvirdes o som da trombeta, todo o povo gritará bem alto, e as muralhas da cidade cairão. Os soldados deverão atacar, cada um, o lugar que estiver à sua frente”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Então, Josué, filho de Num, chamou os sacerdotes e disse-lhes: \"Levai a Arca da Aliança, e sete sacerdotes carregarão sete trombetas de chifre de carneiro adiante da Arca de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'E ele disse ao povo: \"Ide em frente e marchai ao redor da cidade, e os homens armados irão à frente da Arca de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Assim como Josué havia dito ao povo, os sete sacerdotes carregavam as sete trombetas de chifre de carneiro diante de Yahweh. Enquanto eles avançavam, tocavam suas trombetas. A Arca da Aliança de Yahweh seguia atrás deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Os homens armados caminhavam adiante dos sacerdotes, e eles tocavam suas trombetas. A retaguarda seguia após a Arca, e os sacerdotes tocavam continuamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Mas Josué ordenou ao povo: \"Não griteis vós. Nenhum som sairá da vossa boca até o dia em que eu disser para gritardes; só então gritareis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Então, ele fez a Arca de Yahweh rodear a cidade uma vez naquele dia. E entraram em seu acampamento e passaram a noite ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'No dia seguinte, Josué levantou-se de madrugada, e os sacerdotes levaram a Arca de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Os sete sacerdotes, que carregavam as sete trombetas de chifre de carneiro adiante da Arca de Yahweh, caminhavam continuamente e tocavam as trombetas. Soldados armados caminhavam adiante deles. Enquanto a retaguarda caminhava após a Arca de Yahweh, as trombetas soavam continuamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Eles marcharam ao redor da cidade uma vez no segundo dia, e retornaram ao acampamento. Eles fizeram isso por seis dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'No sétimo dia, eles se levantaram ao raiar do dia, e marcharam ao redor da cidade da mesma maneira que fizeram antes. Desta vez, porém, por sete vezes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Na sétima vez que os sacerdotes soaram as trombetas, Josué ordenou ao povo: \"Gritai! Porque Yahweh vos entregou a cidade!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'A cidade e tudo o que nela há serão condenados, por Yahweh, à destruição. Somente Raabe, a prostituta, viverá — ela e aqueles que estão com ela em sua casa — porque escondeu os homens que enviamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Quanto a vós, guardai-vos das coisas separadas à destruição, e, depois que as condenardes, não pegueis nenhuma delas. Se vós o fizerdes, tornareis maldito o acampamento de Israel, trazendo-lhe destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Toda a prata, ouro e as coisas feitas de bronze e ferro são consagrados a Yahweh, e serão levados para o Seu tesouro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Quando os sacerdotes tocaram as trombetas, o povo gritou bem alto e as muralhas ruíram. Então, o povo entrou na cidade, cada um correndo para o lugar em frente de si, e tomaram a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Eles destruíram completamente, ao fio da espada, tudo o que havia: homem e mulher, jovem e velho, vaca, ovelha e jumento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Então, Josué disse aos dois homens que espiaram a terra: \"Ide até a casa da prostituta. Trazei a mulher e todos os que estão com ela, como jurastes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Os espias foram e trouxeram Raabe para fora, com seu pai, sua mãe, seus irmãos e todos os parentes que estavam com ela. Eles os levaram para um lugar fora do acampamento de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'E queimaram a cidade e tudo o que havia nela. Somente a prata, o ouro e os utensílios de bronze e ferro foram colocados no tesouro da casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Mas Josué conservou com vida Raabe, a prostituta, a casa de seu pai, e todos os que com ela viviam. E ela vive em Israel até o dia de hoje, pois ela escondeu os homens a quem Josué enviara para espiar Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Então, Josué ordenou que, naquele momento, fizessem um juramento, dizendo: \"Maldito seja diante de Yahweh o homem que reconstruir esta cidade, Jericó. Com a perda de seu primogênito a fundará, e com a perda de seu filho mais novo ele levantará seus portões\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Assim Yahweh estava com Josué, e sua fama se espalhou pela terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Mas o povo de Israel foi infiel em relação ao que foi condenado para a destruição. Acã, filho de Carmi, filho de Zabdi, filho de Zerá da tribo de Judá, tomou para si algumas coisas que foram separadas para a destruição. Por isso, a ira de Yahweh acendeu-se contra o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Naqueles dias, Josué enviou homens para Ai, cidade próxima a Bete-Áven, leste de Betel. Ele lhes disse: \"Subi e espiai a terra\". Então, os homens subiram e espiaram Ai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Quando retornaram a Josué, disseram-lhe: \"Nem todo o povo deve subir para Ai. Subam apenas dois ou três mil homens para atacá-la. Não faças todo o povo se cansar em batalha, pois eles são poucos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Assim, subiram cerca de três mil homens do exército de Israel, mas fugiram diante dos homens de Ai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Os homens de Ai mataram cerca de trinta e seis israelitas enquanto os perseguiam desde o portão da cidade até as pedreiras; eles os mataram quando desciam a colina. E o coração do povo se derreteu de medo e perderam a coragem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Então, Josué rasgou suas vestes. Ele e os anciãos de Israel jogaram pó em suas cabeças e se prostraram, com seus rostos em terra, perante a Arca de Yahweh, permanecendo lá até a tarde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Josué disse: \"Ah! Yahweh Senhor! Por que fizeste este povo atravessar o Jordão para nos entregares nas mãos dos amorreus e estes nos destruírem? Antes nós tivéssemos nos contentado em ficar do outro lado do Jordão!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Senhor, que posso eu dizer, depois que Israel retrocedeu diante dos seus inimigos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Pois os cananeus e todos os habitantes da terra ouvirão isso. Irão nos cercar e fazer com que o povo da terra esqueça o nosso nome. E então, o que farás pelo Teu grande nome?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Yahweh disse a Josué: \"Levanta-te! Por que estás aí prostrado sobre teu rosto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel pecou! Eles violaram Minha aliança que lhes tinha ordenado. Eles roubaram das coisas que foram separadas. Eles roubaram, mentiram e esconderam seu pecado entre seus próprios pertences.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Por isso o povo de Israel não pôde permanecer ante seus inimigos. Eles fugiram dos inimigos porque eles mesmos mereceram sua destruição. Não estarei mais convosco se não destruirdes as coisas que devem ser destruídas, que estão entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Levanta-te! Consagra-Me o povo e dize-lhes: \'Santificai-vos para amanhã, pois Yahweh, o Deus de Israel, diz: Ainda há coisas separadas para a destruição no meio de vós, Israel. Não podereis resistir aos vossos inimigos até que removais dentre vós todas as coisas que foram separadas para a destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Pela manhã, tereis de vos apresentar segundo suas tribos. A tribo que Yahweh escolher se aproximará por clãs. O clã que Yahweh escolher deverá se aproximar casa por casa. A casa que Yahweh escolher deverá se aproximar homem por homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'E acontecerá que aquele que for encontrado com as coisas separadas para a destruição será queimado no fogo, ele e tudo o que tem, porque ele quebrou a aliança de Yahweh e porque causou desgraça em Israel”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'No dia seguinte, Josué acordou de madrugada e fez Israel se aproximar, tribo por tribo, e a tribo de Judá foi escolhida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Ele aproximou os clãs de Judá, e o clã dos zeraítas foi escolhido. Ele fez o clã dos zeraítas se aproximar, pessoa por pessoa, e Zabdi foi escolhido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Ele fez a família de Zabdi se aproximar, pessoa por pessoa, e Acã, filho de Carmi, filho de Zabdi, filho de Zerá, foi escolhido da tribo de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Então Josué disse a Acã: \"Meu filho, dize a verdade diante de Yahweh, o Deus de Israel, e confessa perante Ele. Dize-me o que tu fizeste, não escondas de mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Acã respondeu a Josué: \"Verdadeiramente, eu pequei contra Yahweh, o Deus de Israel. Eis o que fiz:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'quando vi entre os despojos uma bela capa babilônica, duzentos ciclos de prata e uma barra de ouro no peso de cinquenta ciclos, desejei-os e os peguei. Eles estão escondidos no chão, no meio de minha tenda, e a prata está debaixo da capa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Josué enviou mensageiros, que correram à tenda e lá estavam as coisas. Quando olharam, encontraram-nas escondidas em sua própria tenda e a prata estava embaixo da capa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Eles pegaram os objetos do meio da tenda e os levaram até Josué e todo o povo de Israel. Eles os puseram diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Depois, Josué e todo o Israel com ele pegaram Acã, filho de Zerá, e a prata, a capa, a barra de ouro, seus filhos e filhas, seus bois, seus jumentos, suas ovelhas, sua tenda e tudo o que ele tinha e os levaram ao vale de Acor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Então, Josué disse: \"Por que nos trouxeste esta desgraça? Hoje Yahweh trará desgraça sobre ti\". Todo o Israel apedrejou Acã; e apedrejaram os seus e as demais coisas, e os queimaram no fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'E levantaram sobre ele um grande monte de pedras, que permanece até o dia de hoje. Yahweh afastou Sua ira. Por isso o nome daquele lugar é vale de Acor, até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Yahweh disse a Josué: \"Não temas, não sejas covarde. Toma contigo todos os guerreiros. Sobe a Ai. Vê, eu tenho dado em tuas mãos o rei de Ai, seu povo, sua cidade e sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Farás a Ai e ao seu rei como fizeste a Jericó e ao seu rei, exceto que tomarás para vós os despojos e o gado. Prepara uma emboscada atrás da cidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Então, Josué subiu com todos os seus guerreiros para Ai. Escolheu trinta mil homens fortes e corajosos, e os enviou à noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Ordenou-lhes: \"Vede, ficai de emboscada contra a cidade, por detrás dela. Não vos afasteis muito da cidade, mas estejais todos em prontidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Eu e todos os homens que estão comigo nos aproximaremos da cidade, e quando eles saírem para nos atacar, nós fugiremos deles, como fizemos antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Eles virão atrás de nós até que os tenhamos atraído para longe da cidade. E dirão: \'Eles fogem de nós assim como fizeram da última vez\'. E quando estivermos fugindo deles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'saireis do esconderijo e tomareis a cidade. Yahweh, vosso Deus, a entregará na vossa mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Quando tomardes a cidade, colocareis fogo nela. Fareis isto por obediência às ordens dadas por meio da palavra de Yahweh. Eis o que vos tenho ordenado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Josué os enviou. Eles ficaram no local da emboscada, escondidos entre Betel e Ai, a oeste de Ai. Porém, naquela noite, Josué dormiu entre os guerreiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Josué levantou-se de madrugada, passou seu exército em revista e, então, com os anciãos de Israel, atacou o povo de Ai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Todos os guerreiros que estavam com ele avançaram e aproximaram-se da cidade. E ali acamparam, no lado norte de Ai. Havia um vale entre eles e Ai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Josué tomou cinco mil homens e os colocou de emboscada no lado oeste da cidade entre Betel e Ai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Posicionaram-se todos os soldados, o exército principal, no lado norte da cidade, e a emboscada no lado oeste. Josué passou aquela noite no vale.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Sucedeu que, quando o rei de Ai os avistou, ele e o seu exército levantaram-se cedo e se apressaram para atacar Israel no lugar em frente ao vale do rio Jordão. Ele não sabia que haviam montado uma emboscada para atacá-los por detrás da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Josué e todo o Israel se passaram por derrotados diante deles, e fugiram até o deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Todo o povo que estava na cidade foi convocado para persegui-los e, então, eles os perseguiram até que se afastassem da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Não ficou sequer um homem em Ai e Betel; todos saíram em perseguição a Israel. Eles abandonaram a cidade, deixando-a aberta, para perseguir Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Yahweh disse a Josué: \"Aponta a tua lança em direção a Ai, pois te darei Ai em tuas mãos\". Josué estendeu a lança que estava em sua mão em direção à cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Os soldados, escondidos em emboscada, rapidamente saíram do lugar onde estavam, no momento em que Josué estendeu a mão. Eles correram, entraram na cidade, a tomaram e, rapidamente, a incendiaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Então, os homens de Ai se viraram e, olhando para trás, viram a fumaça vinda da cidade subindo pelo céu; e não podiam escapar por nenhum caminho, pois os soldados israelitas, que fugiam para o deserto, agora se voltavam contra aqueles que os perseguiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'No instante em que Josué e todo o Israel viram que, pela emboscada, haviam capturado a cidade, por causa da fumaça que subia, voltaram e mataram os homens de Ai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'E os outros soldados de Israel, os que estavam na cidade, saíram para atacá-los. Então, os homens de Ai ficaram presos em meio ao exército de Israel, por um lado e pelo outro. Israel atacou os homens de Ai e nenhum deles sobreviveu ou escapou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Mas deixaram o rei de Ai vivo, a quem capturaram e levaram a Josué.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Sucedeu que, quando Israel havia terminado de matar todos os habitantes de Ai no campo próximo ao deserto onde os perseguiram, e quando todos eles — até o último — haviam caído ao fio da espada, todo o Israel voltou para Ai, matando também os que ali estavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Os que morreram naquele dia, homens e mulheres, foram doze mil, todos de Ai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Josué não abaixou sua mão. Permaneceu com a lança estendida até que o povo de Ai fosse completamente destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Israel tomou apenas o rebanho e o despojo da cidade para si, assim como Yahweh ordenara a Josué.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Josué queimou Ai e tornou-a um monte de ruínas para sempre. Esse lugar está abandonado até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Ele enforcou o rei de Ai em uma árvore e ali o deixou até o anoitecer. Quando o sol se pôs, por ordem de Josué, retiraram da árvore o corpo do rei, e o jogaram em frente aos portões da cidade. Fizeram uma grande pilha de pedras sobre o cadáver. Pilha esta que permanece até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Então, Josué construiu um altar a Yahweh, o Deus de Israel, no monte Ebal,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'conforme Moisés, o servo de Yahweh, ordenara ao povo de Israel, como está escrito no livro da lei de Moisés: \"Um altar de pedras brutas, na qual ninguém tivesse usado uma ferramenta de ferro\". Ele ofereceu holocaustos a Yahweh e eles sacrificaram ofertas pacíficas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'E ali, na presença do povo de Israel, ele escreveu nas pedras uma cópia da lei de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Todo o Israel, com seus anciãos, oficiais e juízes ficaram de um lado e outro da Arca, diante dos sacerdotes e levitas, que levavam a Arca da Aliança de Yahweh; tanto o estrangeiro quanto o natural, metade deles permaneceu em frente do monte Gerizim e a outra metade ficou em frente ao monte Ebal. Eles abençoaram o povo de Israel, assim como Moisés, o servo de Yahweh, havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Depois, Josué leu todas as palavras da lei, as bênçãos e maldições, conforme elas foram escritas no Livro da Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Não houve nenhuma palavra, de tudo aquilo que Moisés havia ordenado, que Josué não lesse na frente da assembleia de Israel, incluindo as mulheres, as crianças pequenas e os estrangeiros que viviam no meio deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Então, todos os reis que viviam além do Jordão, na região montanhosa e na baixada ao longo da costa do mar Grande, em direção ao Líbano, os reis dos heteus, dos amorreus, dos cananeus, dos perizeus, dos heveus e dos jebuseus, souberam disso,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'e ajuntaram-se, sob o mesmo comando, para batalhar contra Josué e Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Mas, quando os moradores de Gibeão ouviram o que Josué havia feito a Jericó e a Ai,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'eles agiram com um plano astuto. Mandaram mensageiros, que levavam alforjes velhos sobre seus jumentos e também levavam vinho em recipientes de couro velho, desgastados e rasgados, que haviam sido remendados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'Eles colocaram sandálias velhas e remendadas nos pés, e se vestiram com roupas velhas e desgastadas. Todo o pão que traziam era seco e mofado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Então, eles foram até Josué no acampamento em Gilgal e disseram a ele e aos homens de Israel: \"Nós viemos de uma região muito distante; então, fazei uma aliança conosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Os homens de Israel disseram aos heveus: \"Talvez vós habiteis perto de nós. Como faremos uma aliança convosco?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Eles disseram a Josué: \"Nós somos teus servos\". Josué lhes perguntou: \"Quem sois vós? De onde viestes?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Eles responderam: \"Teus servos vieram de uma terra muito distante, por causa do nome do teu Deus, Yahweh. Ouvimos relatos sobre Ele e sobre tudo o que Ele fez no Egito,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'e tudo o que fez aos dois reis dos amorreus do outro lado do Jordão, a Siom, rei de Hesbom, e a Ogue, rei de Basã, que estava em Astarote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Nossos anciãos e todos os habitantes da nossa terra nos disseram: ‘Tomai provisões para a jornada. Ide ao encontro deles e dizei-lhes: Nós somos vossos servos. Fazei um tratado conosco’.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Este é o nosso pão. Ele ainda estava quente quando saímos de nossas casas, para nos encontrarmos convosco. Mas, agora, ele já está seco e mofado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Estes recipientes de couro estavam novos quando os enchemos, e agora, vede, estão vazando. Nossas roupas e sandálias já se desgastaram por causa da longa jornada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Então, os israelitas tomaram algumas de suas provisões, mas não pediram conselho a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Josué fez uma aliança de paz com eles, para deixá-los viver. Os líderes do povo também fizeram um juramento a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Três dias depois de os israelitas terem feito aliança com eles, descobriram que eram seus vizinhos e que moravam perto deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Então, o povo de Israel partiu e chegou às suas cidades ao terceiro dia. Suas cidades eram Gibeão, Cefira, Beerote e Quiriate-Jearim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'O povo de Israel não os atacou, porque seus líderes haviam prestado juramento acerca deles diante de Yahweh, o Deus de Israel. Todos os israelitas criticaram seus líderes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Mas todos os líderes disseram ao povo: \"Fizemos um juramento acerca deles perante Yahweh, o Deus de Israel, e agora não podemos tocar neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Isto é o que lhes faremos: para evitar qualquer ira que possa vir sobre nós por causa do juramento que fizemos a eles, nós os deixaremos viver\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Os líderes disseram ao seu povo: \"Que vivam!\". Então, os gibeonitas tornaram-se lenhadores e tiradores de água para todos os israelitas, como os líderes lhes disseram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Josué os chamou e disse-lhes: \"Por que nos enganastes, dizendo: \'Moramos muito distante de vós\', quando vivíeis perto de nós?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Agora, por causa disso, sois malditos, e entre vós nunca deixará de haver escravos, que cortarão madeira e tirarão água para a casa do meu Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Eles responderam, dizendo: \"Porque foi dito aos teus servos que Yahweh, vosso Deus, mandou Seu servo Moisés para vos dar toda esta terra, e destruir todos os moradores desta terra diante de vós. Então, temíamos muito pelas nossas vidas, por causa de vós. Então fizemos isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Agora, vê, estamos em tuas mãos. Aquilo que parecer bom e correto para ti, faze conosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Então, Josué fez isto com eles: impediu que os israelitas os matassem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Naquele dia, Josué fez dos gibeonitas lenhadores e tiradores de água para a comunidade e para o altar de Yahweh, até o dia de hoje, no lugar que Yahweh escolhesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Adoni-Zedeque, rei de Jerusalém, ouviu que Josué havia capturado e destruído completamente a cidade de Ai (assim como ele havia feito com Jericó e seu rei), e ouviu que o povo de Gibeão havia feito acordo de paz com Israel e estava vivendo no meio deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'O povo de Jerusalém teve muito medo, pois Gibeão era uma cidade grande, como uma das cidades reais, e era maior que Ai, e todos os seus homens eram guerreiros fortes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Então, Adoni-Zedeque, rei de Jerusalém, enviou mensagem para Hoão, rei de Hebrom, a Pirã, rei de Jarmute, a Jafia, rei de Laquis, e a Debir, rei de Eglom, dizendo-lhes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, '\"Vinde e me ajudai. Vamos atacar Gibeão, porque fez acordo de paz com Josué e com o povo de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Os cinco reis dos amorreus: o rei de Jerusalém, o rei de Hebrom, o rei de Jarmute, o rei de Laquis e o rei de Eglom vieram com todos os seus exércitos, posicionaram-se contra a cidade de Gibeão e a atacaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Os gibeonitas enviaram mensagem a Josué e ao acampamento em Gilgal, dizendo: \"Não retires de teus servos a tua mão. Vem rapidamente, e salva-nos. Ajuda-nos, pois todos os reis dos amorreus que moram na região montanhosa se reuniram para nos atacar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Josué partiu de Gilgal, e, junto dele, todos os homens de guerra, incluindo os seus melhores guerreiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Yahweh disse a Josué: \"Não os temas. Eu os entreguei em tuas mãos. Nenhum deles poderá parar o teu ataque\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Depois de marchar a noite toda desde a cidade de Gilgal, Josué os atacou de surpresa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'E Yahweh confundiu os inimigos diante de Israel, que os matou em grande quantidade em Gibeão, perseguindo-os pelo caminho que sobe para Bete-Horom, matando-os até Azeca e Maqueda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Enquanto eles fugiam de Israel, descendo a montanha de Bete-Horom, Yahweh lançou grandes pedras do céu sobre eles por todo o caminho até Azeca, e morreram. E foram mais os que morreram das pedras de granizo do que aqueles que os homens de Israel mataram à espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Então, Josué falou a Yahweh, no dia em que Ele deu a vitória aos homens de Israel contra os amorreus. Isto é o que ele disse a Yahweh, diante de Israel: \"Sol, permanece em Gibeão, e lua, no vale de Aijalom\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'O sol parou, também a lua parou de se mover, até a nação se vingar dos seus inimigos. Não está isso escrito no Livro de Jasar? O sol parou no meio do céu, e não se pôs por quase um dia inteiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'E não houve nenhum dia como esse, nem antes nem depois dele, quando Yahweh atendeu, de tal forma, a voz de um ser humano. Pois Yahweh batalhava por Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Josué e todo o Israel retornaram ao acampamento em Gilgal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Então, os cinco reis escaparam e se esconderam na caverna em Maqueda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'E foi dito a Josué: \"Foram encontrados! Os cinco reis estão escondidos na caverna de Maqueda!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Josué disse: \"Arrastai grandes pedras contra a boca da caverna e colocai soldados lá para os guardar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Não fiqueis parados! Que persigais os vossos inimigos e ataqueis os que vão ficando atrás. Não os deixeis entrar nas cidades deles, pois Yahweh, vosso Deus, já os entregou em vossas mãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Josué e os filhos de Israel continuaram a vencê-los em uma grande matança, até que fossem quase completamente destruídos. Apenas alguns sobreviventes que escaparam chegaram às cidades fortificadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Todo o exército retornou em paz para Josué, no acampamento de Maqueda. E nenhum se atreveu a dizer uma palavra contra o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Então, Josué disse: \"Abri, vós, a boca da caverna e trazei-me aqueles cinco reis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Fizeram como ele mandou e trouxeram da caverna os cinco reis: o rei de Jerusalém, o rei de Hebrom, o rei de Jarmute, o rei de Laquis e o rei de Eglom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'E, quando trouxeram os reis a Josué, ele convocou cada homem de Israel, e disse aos comandantes dos soldados que foram para a batalha com ele: \"Ponde vossos pés nos pescoços deles\". Então, eles se aproximaram e puseram os pés nos pescoços dos reis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Então, Josué lhes disse: \"Não temais e nem vos abaleis. Sede fortes e corajosos. Isso é o que Yahweh fará com todos os vossos inimigos, contra os quais haveis de lutar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Então, Josué feriu e matou os reis e os pendurou em cinco árvores até a tarde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Quando o sol se pôs, Josué deu ordens, e eles foram tirados das árvores onde estavam pendurados e foram lançados na caverna onde tinham se escondido. Eles colocaram grandes pedras na boca da caverna, que permanecem ali até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Naquele mesmo dia, Josué tomou Maqueda e matou a todos ao fio de espada, inclusive o seu rei. Ele destruiu completamente todos os que nela havia. Não deixou nenhum sobrevivente. Ele fez com o reino de Maqueda como havia feito com o reino de Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Josué e todo o Israel foram de Maqueda para Libna e lutaram contra a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Yahweh também a entregou nas mãos de Israel, junto com seu rei. Josué atacou todas as pessoas que nela havia ao fio de espada. Ele não deixou nenhum sobrevivente ali e fez com o rei o mesmo que havia feito com o rei de Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Então, Josué e todo o Israel foram de Libna para Laquis. Eles a sitiaram e batalharam contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Yahweh deu Laquis nas mãos de Israel. Josué a tomou no segundo dia. Ele atacou, ao fio de espada, cada pessoa que estava lá, da mesma forma que ele havia feito em Libna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Horão, rei de Gezer, subiu para ajudar Laquis. Josué o atacou e também o seu exército, até que não restasse nenhum sobrevivente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Então, Josué e todo povo foram de Laquis para Eglom. Eles a sitiaram e lutaram contra ela,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'e a tomaram no mesmo dia. Eles a atacaram ao fio de espada e destruíram todos, completamente, como Josué havia feito a Laquis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Josué e todo o povo de Israel subiram de Eglom a Hebrom, e batalharam contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Eles a tomaram e a atacaram ao fio de espada, incluindo o rei e todos os seus povoados, como também todos os que nela estavam. Eles destruíram completamente todos ali, sem deixar sobreviventes, assim como fizeram a Eglom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Então, Josué e todo o exército de Israel retornaram a Debir e batalharam contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Eles a tomaram, bem como seu rei e todos os seus povoados. Eles os atacaram ao fio de espada e destruíram completamente todos os que estavam ali. Não deixaram sobreviventes, do mesmo modo que haviam feito a Hebrom, e como haviam feito a Libna e ao seu rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Josué conquistou toda aquela terra, a região montanhosa, o Neguebe, a baixada e as encostas das montanhas. De todos os reis, ele não deixou nenhum sobrevivente. Destruiu completamente cada criatura viva, como Yahweh, o Deus de Israel, havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Josué os atacou desde Cades-Barneia até Gaza, e toda a região de Gósen até Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'E, de uma só vez, Josué derrotou todos esses reis e tomou suas terras, pois Yahweh, o Deus de Israel, lutou por Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Então, Josué e todo o povo de Israel voltaram ao acampamento em Gilgal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Quando Jabim, rei de Hazor, ouviu isso, ele enviou uma mensagem para Jobabe, rei de Madom, para o rei de Sinrom e para o rei de Acsafe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'Ele também enviou a mensagem para os reis que estavam ao norte na região montanhosa, no vale do rio Jordão, ao sul de Quinerete, na baixada e na região montanhosa de Dor para o oeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Ele também enviou mensagem para os cananeus, do leste ao oeste, os amorreus, os heteus, os perizeus, os jebuseus, na região montanhosa, e para os heveus, perto da montanha de Hermom, na terra de Mispá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Todos os seus exércitos saíram com eles, um grande número de soldados, um número como a areia da praia. Eles tinham grande quantidade de cavalos e carros de guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Todos aqueles reis encontraram-se no tempo determinado e acamparam perto das águas de Merom, para batalhar contra Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Yahweh disse para Josué: \"Não tenhas medo da presença deles, porque amanhã, a esta hora, entregarei todos eles a Israel como homens mortos. Tu aleijarás seus cavalos e queimarás seus carros de guerra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Josué e todos os homens de guerra vieram. Eles chegaram, de repente, às águas de Merom, e atacaram os inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Yahweh entregou os inimigos nas mãos de Israel, e eles os feriram e os perseguiram até Sidom, Misrefote-Maim, e até o vale de Mispá para o leste. Eles os feriram até que não restasse nenhum de seus sobreviventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Josué fez a eles como Yahweh lhe havia falado. Ele aleijou os cavalos e queimou os carros de guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Josué retornou naquele tempo e tomou Hazor. Ele feriu o rei com a espada. (Hazor tinha sido a capital de todos esses reinos).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Eles atacaram com a espada todas as criaturas vivas que existiam naquele lugar, e as destruíram. Assim, nenhuma criatura foi deixada viva. Então, ele queimou Hazor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Josué tomou todas as cidades daqueles reis. Ele também capturou todos aqueles reis e os feriu ao fio da espada. Destruiu-os completamente, assim como Moisés, o servo de Yahweh, havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Israel não queimou nenhuma cidade construída nos montes, exceto Hazor, que Josué queimou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'O exército de Israel apossou-se de todos os despojos dessas cidades, juntamente com o gado deles. Eles mataram todos os seres humanos ao fio da espada, até que todos morressem. Eles não deixaram sobreviver nenhuma criatura que respirasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Assim como Yahweh havia ordenado ao seu servo Moisés, do mesmo modo, Moisés ordenou a Josué, e assim Josué fez. Ele não deixou de fazer nada daquilo que Yahweh havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Josué tomou toda aquela terra, a região montanhosa, todo o Neguebe, toda a terra de Gósen, as encostas das montanhas, o vale do rio Jordão, a região montanhosa de Israel, e a baixada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Desde o monte Halaque, perto de Seir, e indo para o norte até Baal-Gade no vale perto do Líbano, abaixo da montanha de Hermom, ele capturou todos os seus reis e os matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Josué travou batalhas por um longo tempo com todos esses reis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Não houve cidade que fizesse paz com o exército de Israel, exceto os heveus que viviam em Gibeão. Israel tomou todas as cidades restantes nas batalhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Porque foi Yahweh que endureceu os seus corações para saírem à guerra contra Israel, para que fossem completamente destruídos, sem misericórdia, assim como Ele havia ordenado a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Josué veio naquele tempo e destruiu os anaqueus, da região montanhosa de Hebrom, de Debir, de Anabe, de toda a região montanhosa de Judá, e de toda a região montanhosa de Israel. Josué os destruiu completamente com as suas cidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Nenhum dos anaqueus foi deixado na terra de Israel, exceto em Gaza, em Gate e em Asdode.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Assim, Josué tomou toda essa terra, como Yahweh dissera a Moisés. Josué a deu como herança a Israel, repartindo-a segundo cada uma de suas tribos. Então, a terra descansou da guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Ora, estes são os reis da terra, aos quais os homens de Israel derrotaram. Os israelitas possuíram as terras ao lado oeste do Jordão, no lado que o sol nasce, desde o vale do rio Arnom até o monte Hermom, e toda a Arabá do leste:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Siom, rei dos amorreus que habitava em Hesbom, dominava desde Aroer, que está à borda do vale de Arnom, e desde o meio do vale, e metade de Gileade, até o ribeiro de Jaboque, na fronteira dos amonitas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'Siom também governava a Arabá oriental, até o mar de Quinerete, e até o mar da Arabá (o mar Salgado), incluindo o caminho de Bete-Jesimote; e, ao sul, alcançava as encostas do monte Pisga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Ogue, o rei de Basã, era remanescente dos refains, que habitava em Astarote e em Edrei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Ele dominava o monte Hermom, Salca, e toda a Basã, até a fronteira dos povos gesureus e dos maacateus, e metade de Gileade, até a fronteira de Siom, rei de Hesbom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Moisés, servo de Yahweh, e o povo de Israel os derrotou; e Moisés, servo de Yahweh, distribuiu a terra como posse entre os rubenitas, os gaditas, e a meia-tribo de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Estes são os reis da terra que Josué e o povo de Israel derrotaram, no lado oeste do Jordão, desde Baal-Gade, no vale perto do Líbano, até o monte Halaque perto de Edom. Josué deu a terra para as tribos de Israel para tomarem posse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Deu-lhes a região montanhosa, a baixada, a Arabá, as encostas das montanhas, o deserto e o Neguebe: a terra dos heteus, amorreus, cananeus, perizeus, heveus e dos jebuseus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Os reis derrotados foram os seguintes: o rei de Jericó, o rei de Ai, que está ao lado de Betel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'o rei de Jerusalém, o rei de Hebrom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'o rei de Jarmute, o rei de Laquis,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'o rei de Eglom, o rei de Gezer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'o rei de Debir, e o rei de Geder,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'o rei de Hormá, o rei de Arade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'o rei de Libna, e o rei de Adulão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'o rei de Maqueda, o rei de Betel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'o rei de Tapua, o rei de Hefer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'o rei de Afeque, o rei de Lassarom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'o rei de Madom, o rei de Hazor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'o rei de Sinrom-Merom, o rei de Acsafe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'o rei de Taanaque, o rei do Megido,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'o rei de Quedes, o rei do Jocneão do Carmelo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'o rei de Dor, na colina de Dor, o rei de Goim, em Gilgal,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'e o rei de Tirza. Ao todo, trinta e um reis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Josué estava bem idoso quando Yahweh lhe disse: \"Tu estás bem idoso, mas ainda há muitas terras para conquistar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Esta é a terra que ainda resta: todas as regiões dos filisteus e todas as dos gesureus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'desde Sior, que está ao leste do Egito, e ao norte até a fronteira de Ecrom, que é considerada propriedade dos cananeus; os cinco governantes filisteus: o de Gaza, o de Asdode, o de Asquelom, o de Gate e o de Ecrom — o território dos aveus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'No sul, ainda restam todas as terras dos cananeus, desde Meara, pertencente aos sidônios, até Afeca, na fronteira dos amorreus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'bem como a terra dos gebalitas e todo o Líbano; no leste, desde Baal-Gade, ao pé do monte Hermom até Lebo-Hamate;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'também, todos os habitantes das regiões montanhosas desde o Líbano até Misrefote-Maim, incluindo todo o povo de Sidom. Eu os expulsarei diante do exército de Israel. Certifica-te de distribuir a terra a Israel, como uma herança, como te ordenei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Distribui esta terra como herança às nove tribos e à meia tribo de Manassés\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Com a outra meia tribo de Manassés, os rubenitas e os gaditas já haviam recebido sua herança que Moisés dera a eles, no lado leste do Jordão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'desde Aroer, que está à borda do vale do rio Arnom (incluindo a cidade que está no meio do vale), e todo o planalto de Medeba até Dibom;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'todas as cidades de Siom, rei dos amorreus, que reinou em Hesbom, até a fronteira dos amonitas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'e Gileade, a região dos gesureus e maacateus, todo o monte Hermom, toda a Basã até Salca;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'todo o reino de Ogue, em Basã, que reinou em Astarote e Edrei — esses são os que restaram dos refains — que Moisés derrotou e expulsou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Mas o povo de Israel não expulsou os gesureus nem os maacateus. Ao invés disso, eles vivem no meio de Israel até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Somente à tribo de Levi que Moisés não deu herança. As ofertas queimadas para Yahweh, o Deus de Israel, são a sua herança, como Deus dissera a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Moisés deu uma herança à tribo de Rúben, conforme os seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'O território deles incluía desde Aroer, que está à beira do rio Arnom, a cidade que está no meio do vale, e todo o planalto até Medeba;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Rúben também recebeu Hesbom, e todas as cidades que estão no planalto: Dibom, Bamote-Baal, Bete-Baal-Meom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jaza, Quedemote, Mefaate,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Quiriataim, Sibma e Zerete-Saar, no monte do vale;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Rúben recebeu, também, Bete-Peor, as encostas do monte Pisga e Bete-Jesimote;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'todas as cidades do planalto e todo o reino de Siom, rei dos amorreus, que reinou em Hesbom, o qual Moisés havia derrotado juntamente com os líderes de Midiã, Evi, Requém, Zur, Hur e Reba, líderes de Siom, que haviam habitado na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'O povo de Israel também matou, com espada, Balaão, filho de Beor, que praticava adivinhações, dentre aqueles que eles haviam matado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'A fronteira da tribo de Rúben é o rio Jordão. Essa foi a herança da tribo de Rúben, dada a cada família, incluindo suas cidades e povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Moisés deu como herança à tribo de Gade, segundo os seus clãs:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'o território de Jazer, todas as cidades de Gileade, incluindo a metade da terra dos amonitas, até Aroer, que está ao leste de Rabá;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'desde Hesbom até Ramá-Mispá e Betonim, desde Maanaim até a região de Debir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'Ainda, no vale, Moisés lhes deu Bete-Arã, Bete-Ninra, Sucote e Zafom, o restante do reinado de Siom, rei de Hesbom, tendo o rio Jordão como fronteira, até a extremidade do mar de Quinerete, do lado oriental do Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Essa foi a herança da tribo de Gade, segundo seus clãs, incluindo suas cidades e povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'À meia-tribo de Manassés, Moisés deu uma herança distribuída segundo seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'O território dela incluía desde Maanaim, toda a Basã, todo o reino de Ogue, rei de Basã, e todos os povoados de Jair, que estão em Basã, sessenta ao todo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'e a metade de Gileade, Astarote e Edrei (cidades do reino de Ogue, em Basã). Essa foi a herança repartida às famílias dos descendentes de Maquir, filho de Manassés, isto é, à metade do povo de Maquir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Essa foi a herança que Moisés distribuiu nas planícies de Moabe, além do Jordão, ao leste de Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Moisés não deu nenhuma herança para a tribo de Levi. Yahweh, o Deus de Israel, é a sua herança, como já lhes havia dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Estas são as áreas que o povo de Israel recebeu como herança na terra de Canaã, distribuídas a eles por Eleazar, o sacerdote, por Josué, filho de Num, e pelos líderes dos clãs das tribos dentre o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'A sua herança foi repartida por sorteio entre as nove tribos e meia, assim como Yahweh havia ordenado por intermédio de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Porque Moisés já havia dado a herança das duas tribos e meia além do Jordão, mas não deu aos levitas herança alguma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'A tribo de José era, na verdade, duas tribos: Manassés e Efraim. Mas nenhuma parte da herança na terra foi dada aos levitas, exceto algumas cidades para que habitassem, e os seus arredores para o seu gado e para os seus bens materiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'O povo de Israel fez como Yahweh havia ordenado a Moisés e, assim, repartiram a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Então, a tribo de Judá veio até Josué em Gilgal. Calebe, filho de Jefoné, o quenezeu, disse-lhe: \"Tu sabes o que Yahweh disse a Moisés, homem de Deus, a respeito de nós em Cades-Barneia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Eu tinha quarenta anos quando Moisés, servo de Yahweh, me enviou de Cades-Barneia para espionar a terra. Eu lhe trouxe um relatório conforme estava no meu coração para fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Porém, meus irmãos que subiram comigo fizeram o coração do povo derreter de medo. Mas eu perseverei em seguir Yahweh, meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Moisés jurou naquele dia, dizendo: \'Certamente, a terra que pisou o teu pé será herança para ti e para teus filhos para sempre, porque seguiste completamente a Yahweh, meu Deus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Agora, eis que Yahweh me conservou vivo durante estes quarenta e cinco anos como Ele prometeu. Yahweh falou esta palavra a Moisés quando Israel ainda peregrinava no deserto. Hoje estou com oitenta e cinco anos de idade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'E ainda sou tão forte hoje como era no dia em que Moisés me enviou. Tenho tanta força agora para guerrear, para ir e para vir, como eu tinha antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Agora, dá-me essa região montanhosa que Yahweh me prometeu naquele dia. Porque tu ouviste naquele dia que os anaqueus ali habitavam em grandes cidades fortificadas. Se Yahweh estiver comigo, eu os expulsarei, assim como Yahweh disse\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Então, Josué abençoou Calebe, filho de Jofoné, e deu-lhe Hebrom como herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Assim, Hebrom tornou-se herança de Calebe, filho de Jefoné, o quenezeu, até o dia de hoje, porque ele seguiu fielmente a Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'O nome de Hebrom, anteriormente, era Quiriate-Arba (Arba havia sido o maior homem entre os anaqueus). E a terra descansou da guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'A terra distribuída à tribo dos filhos de Judá, segundo os seus clãs, estendia-se ao sul até a fronteira de Edom, com o deserto de Zim sendo a extremidade do lado sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Sua fronteira do sul ia desde a extremidade do mar Salgado, da baía que estava voltada para o sul,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'estendia-se para o sul até a colina de Acrabim e ia ao longo de Zim; subia pelo sul de Cades-Barneia, passando por Hezrom, e subia até Adar e virava para Carca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Passava ao longo de Azmom, chegando até o ribeiro do Egito e terminava no mar. Essa era a sua fronteira do lado sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'A fronteira oriental ia do mar Salgado até a foz do Jordão. A fronteira ao norte percorria desde a baía do mar até a foz do Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'E subia até Bete-Hogla, passando ao longo do norte de Bete-Arabá. Então, subia até a pedra de Boã, o filho de Rúben.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Assim, a fronteira subia a Debir, desde o vale de Acor, e ia para o norte, em direção a Gilgal, que estava de frente à colina de Adumim, que ficava do lado sul do vale. Dali, a fronteira continuava ao longo das nascentes de En-Semes e ia até En-Rogel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Então, a fronteira subia pelo vale de Ben-Hinom para o lado sul da cidade dos jebuseus (que é Jerusalém), e subia até o cume do monte que estava em frente do vale de Hinom, no lado oeste, no fim do vale dos refains, ao norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'A fronteira estendia-se do topo das colinas até a fonte de Neftoa e, de lá, ia para as cidades do monte Efrom. Então, a fronteira estendia-se até Baalá, isto é, Quiriate-Jearim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Dali, a fronteira circundava a oeste de Baalá ao Monte Seir, e passava ao longo do lado do monte Jearim ao norte, isto é, Quesalom, descia para Bete-Semes e passava ao longo de Timna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'A fronteira ia ao lado norte da colina de Ecrom, e então curvava-se para Siquerom e passava ao longo do monte Baalá, de onde ia a Jabneel. A fronteira acabava no mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'A fronteira ocidental era o grande Mar e a sua costa. Esta é a fronteira ao redor da tribo de Judá, clã por clã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'De acordo com o mandamento de Yahweh a Josué, Josué deu a Calebe, filho de Jefoné, uma porção de terra entre a tribo de Judá, Quiriate-Arba, que é Hebrom (Arba era o pai de Anaque).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Calebe expulsou dali os três filhos de Anaque: Sesai, Aimã e Talmai, descendentes de Anaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Ele subiu dali contra os habitantes de Debir (o nome de Debir era Quiriate-Sefer).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Calebe disse: “O homem que atacar Quiriate-Sefer e a tomar, para este darei Acsa, minha filha, como esposa”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Otoniel, filho de Quenaz, irmão de Calebe, a tomou. Então Calebe deu a ele Acsa, sua filha, como esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Depois, quando Acsa foi até Otoniel, ela o persuadiu para que pedisse a seu pai um campo. Quando ela saltou de seu jumento, Calebe perguntou-lhe: “O que queres?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Acsa respondeu-lhe: “Faze-me um favor especial. Já que tu me deste a terra de Neguebe, dá-me também algumas fontes d\'água”. E Calebe lhe deu as fontes superiores e as fontes inferiores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Esta foi a herança da tribo de Judá, segundo os seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'As cidades pertencentes à tribo de Judá no extremo sul em direção à fronteira de Edom, eram: Cabzeel, Eder, Jagur,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Quiná, Dimona, Adada,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Quedes, Hazor, Itnã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Zife, Telem, Bealote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Hazor-Hadada, Queriote-Hezrom (também conhecida como Hazor),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amã, Sema, Molada,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Hazar-Gada, Hesmom, Bete-Pelete,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Hazar-Sual, Berseba, Biziotiá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baalá, Iim, Ezem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltolade, Quesil, Hormá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Ziclague, Madmana, Sansana,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaote, Silim, Aim e Rimom. Eram, ao todo, vinte e nove cidades, incluindo os seus vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Na região montanhosa mais baixa a oeste, havia Estaol, Zorá, Asná,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Zanoa, En-Ganim, Tapua, Enã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmute, Adulão, Socó, Azeca,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saraim, Aditaim, Gedera (que é, Gederotaim). Eram catorze cidades, incluindo os seus vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Zenã, Hadasa, Midgal-Gade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dileã, Mispá, Jocteel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Laquis, Bozcate, Eglom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Cabom, Laamás, Quitlis,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederote, Bete-Dagom, Naama e Maqueda. Eram dezesseis cidades, incluindo os seus vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Eter, Asã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Iftá, Asná, Nezibe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Queila, Aczibe e Maressa. Eram nove cidades, incluindo os seus vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ecrom, com suas cidades e vilarejos ao redor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'de Ecrom ao grande Mar, todos os seus assentamentos que eram perto de Asdode, incluindo seus vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdode, e as cidades e vilarejos ao redor, Gaza, com as suas cidades e vilarejos, para o ribeiro do Egito, e o grande Mar com sua costa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Na região montanhosa, Samir, Jatir, Socó,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Daná, Quiriate-Saná (isto é, Debir),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anabe, Estemó, Anim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosén, Holom e Gilo. Estas eram as onze cidades, incluindo os seus vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arabe, Dumá, Esã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janim, Bete-Tapua, Afeca,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Hunta, Quiriate-Arba (isto é, Hebrom) e Zior. Estas eram nove cidades, incluindo os seus vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maom, Carmelo, Zife, Jutá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jezreel, Jocdeão, Zanoa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Caim, Gibeá e Timna. Estas eram as dez cidades, incluindo os seus vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halul, Bete-Zur, Gedor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarate, Bete-Anote e Eltecom. Estas eram seis cidades, incluindo os seus vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Quiriate-Baal (que é, Quiriate-Jearim), e Rabá. Eram duas cidades, incluindo os seus vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'No deserto, eram Bete-Arabá, Midim, Secaca,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsã, a cidade do Sal, e En-Gedi. Eram seis cidades, incluindo os seus vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Porém, quanto aos jebuseus, os habitantes de Jerusalém, a tribo de Judá não os pôde expulsar. Assim, os jebuseus viveram com a tribo de Judá até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'A terra distribuída à tribo de José se estendia desde o Jordão até Jericó, ao leste das nascentes de Jericó, pelo deserto que sobe de Jericó através da região montanhosa de Betel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Ia de Betel até Luz e passava pela região dos arquitas até Atarote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Então, descia para o oeste até o território dos jafletitas, até o território de Bete-Horom inferior, até Gezer, indo terminar no mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Assim, as tribos de José, Manassés e Efraim receberam sua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'A região da tribo de Efraim foi distribuída segundo seus clãs como segue: a fronteira da sua herança para o leste ia de Atarote-Adar até Bete-Horom superior,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'e, dali, continuava até o mar. De Micmetá, ao norte, virava para o leste até Taanate-Siló e, passando por ela, a leste de Janoa;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'E de Janoa descia até Atarote e Naarate, e chegava a Jericó, terminando no Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'De Tapua, a borda se estendia para o oeste até o ribeiro de Caná e terminava no mar. Essa é a herança da tribo de Efraim, segundo seus clãs,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'juntamente com as cidades que foram escolhidas para a tribo de Efraim que estavam no meio da herança da tribo de Manassés, todas as cidades, assim como suas vilas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Eles não expulsaram os cananeus que habitavam em Gezer; então, os cananeus ficaram vivendo entre os efraimitas até o dia de hoje; porém, sujeitos a trabalho forçado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Esta foi a terra distribuída à tribo de Manassés (o qual era o primogênito de José), isto é, a Maquir, o primogênito de Manassés, pai de Gileade. Aos descendentes de Maquir, que era homem de guerra, foi distribuída a terra de Gileade e Basã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'A terra também foi dada por herança aos outros filhos de Manassés, conforme seus clãs, isto é, aos descendentes de Abiezer, Heleque, Asriel, Siquém, Hefer e Semida. Esses foram os descendentes machos de Manassés, filho de José, segundo seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Mas Zelofeade, filho de Hefer, filho de Gileade, filho de Maquir, filho de Manassés, não teve filhos, somentes filhas. Estes foram os nomes das suas filhas: Maalá, Noa, Hogla, Milca e Tirza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Elas se apresentaram a Eleazar, o sacerdote, a Josué, filho de Num, e aos líderes, e disseram: \"Yahweh ordenou a Moisés que nos desse herança entre os nossos irmãos\". Então, seguindo a ordem de Yahweh, ele deu àquelas mulheres uma herança entre os irmãos do seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Manassés recebeu dez partes da terra em Gileade e Basã, a qual ficava do outro lado do Jordão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'por causa das filhas de Manassés que receberam herança entre os filhos dele. A terra de Gileade foi dividida entre o restante da tribo de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'O território de Manassés abrangia de Aser até Micmetá, que ficava ao leste de Siquém. Então, a fronteira estendia-se para o sul até os habitantes que moravam perto da fonte de Tapua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, '(A terra de Tapua pertencia a Manassés, mas a cidade de Tapua, na fronteira de Manassés, pertencia à tribo de Efraim).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Depois, a fronteira descia ao longo do riacho de Caná. Estas cidades do sul do riacho no meio de Manassés pertenceram a Efraim. A fronteira de Manassés estava no lado norte do riacho e finalizava no mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'A terra do sul pertencia a Efraim e a terra do norte, a Manassés; o mar era sua fronteira. O lado norte estendia-se de Aser e, ao leste, até Issacar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Também em Issacar e Aser, Manassés recebeu Bete-Seã e suas vilas, Ibleão e suas vilas, os habitantes de Dor e suas vilas, os habitantes de En-Dor e suas vilas, os habitantes de Taanaque e suas vilas, e os habitantes de Megido e suas vilas (e a terceira cidade é Nafete).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Contudo, a tribo de Manassés não pôde tomar posse daquelas cidades, pois os cananeus continuavam a habitar naquela terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Mas, quando o povo de Israel tornou-se forte, sujeitou os cananeus a trabalhos forçados; porém, não os expulsou completamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Então, os descendentes de José disseram a Josué: \"Por que nos deste somente uma porção de terra e uma porção por herança, visto que somos um povo grande em número e Yahweh sempre nos tem abençoado?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Josué lhes disse: \"Se sois um povo numeroso, subi vós mesmos à floresta e limpai um local para vós na terra dos perizeus e dos refains, já que as colinas de Efraim são pequenas demais para vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'E os descendentes de José disseram: \"A região montanhosa não é suficiente para nós. Porém, todos os cananeus que vivem no vale têm carros de ferro, tanto os de Bete-Seã e suas vilas, como os que estão no vale de Jezreel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Então, Josué disse à casa de José, isto é, a Efraim e a Manassés: \"Vós sois um povo numeroso e tendes grande poder. Não tereis apenas uma porção de terra distribuída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'A região montanhosa também será vossa. Embora seja uma floresta, vós a limpareis e tomareis posse dela até as suas fronteiras mais distantes. Expulsareis os cananeus, mesmo que eles tenham carros de ferro e sejam fortes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Então, toda a congregação de Israel se reuniu em Siló. Ali estabeleceram a Tenda do Encontro e conquistaram a terra diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Havia sete tribos dentre os filhos de Israel que ainda não tinham recebido a sua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Josué disse aos filhos de Israel: \"Por quanto tempo adiareis a entrada e a posse da terra que Yahweh, Deus de vossos antepassados, vos deu?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Nomeai entre vós três homens de cada tribo, e eu os enviarei. Eles explorarão a terra de cima a baixo e escreverão uma descrição com a demarcação de sua herança. Então, retornarão a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Eles dividirão a terra em sete partes. Judá permanecerá em seu território no sul, e a casa de José continuará em seu território no norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Demarcareis a terra em sete partes e me trareis a sua descrição para que eu vos faça um sorteio diante de Yahweh, nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Os levitas não têm parte no meio de vós, pois o sacerdócio de Yahweh é sua herança. Gade, Rúben e a metade da tribo de Manassés já receberam sua herança além do Jordão. Esta é a herança que Moisés, o servo de Yahweh, lhes deu”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Então, os homens se levantaram e se foram. Josué ordenou àqueles que demarcariam a terra, dizendo: \"Levantai-vos, descei à terra, fazei uma descrição dela e, então, voltai a mim. Eu vos farei um sorteio diante de Yahweh em Siló\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Os homens saíram e caminharam de um lado para o outro na terra e fizeram, em um rolo, uma descrição de suas cidades, em sete seções, listando-as em cada seção. Então, voltaram a Josué no acampamento de Siló.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Ali, Josué fez-lhes um sorteio diante de Yahweh. Assim, Josué designou a terra para o povo de Israel. A cada um deles foi dada a sua porção da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Saiu, por sorteio, a designação da terra para a tribo de Benjamim, clã por clã. E o território sorteado estava localizado entre os descendentes de Judá e os descendentes de José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'No lado norte, suas fronteiras começavam no Jordão. A fronteira ia da encosta, ao norte de Jericó, e atravessava as regiões montanhosas do lado oeste. E alcançava o deserto de Bete-Áven.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'De lá, a fronteira passava ao longo do sul na direção de Luz (o mesmo lugar que Betel) e, então, descia para Atarote-Adar, pela encosta do monte que está ao sul de Bete-Horom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'E a fronteira, então, ia em outra direção: no lado oeste, ela fazia uma curva para o sul, em direção do monte que está diante de Bete-Horom. E chegava a Quiriate-Baal (que é Quiriate-Jearim), uma cidade que pertencia à tribo de Judá. Assim era a fronteira do lado oeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'O lado sul começava do lado de fora de Quiriate-Jearim. A fronteira ia até Efrom, até a fonte das águas de Neftoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'A fronteira descia para a extremidade do monte que está na frente do vale de Ben-Hinom, o qual está no vale de refains, ao norte. E ia ao fim do vale de Hinom, para o sul do lado dos jebuseus, e descia até En-Rogel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Passando para o norte, indo em direção de En-Semes e, de lá, para Gelilote, que está defronte da subida de Adumim. E descia até a pedra de Boã, filho de Rúben.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Passava pela encosta norte, margeando Bete Arabá, descendo até Arabá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'A fronteira passava na margem norte de Bete-Hogla, e seus extremos chegavam à baía norte do mar Salgado, ao fim do lado sul do Jordão. Esta era a fronteira do sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'O Jordão formava a fronteira do lado leste. Esta foi a herança da tribo de Benjamim, e foi-lhes dada, nos arredores, fronteiras por fronteiras, de acordo com os seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'As cidades da tribo de Benjamim conforme os seus clãs eram: Jericó, Bete-Hogla, Emeque-Queziz,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Bete-Arabá, Zemaraim, Betel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avim, Pará, Ofra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Quefar-Ha-Amonai, Ofni e Gaba. Eram doze cidades, sem contar os vilarejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Também havia as cidades de Gibeão, Ramá, Beerote,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mispá, Cefira, Moza,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Requém, Irpeel, Tarala,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Zela, Elefe, Jebus (isto é, Jerusalém), Gibeá e Quiriate. Havia catorze cidades, sem contar seus vilarejos. Essa é a herança de Benjamim para seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'A segunda sorte saiu para Simeão, e foi distribuída a cada um segundo seus clãs. Sua herança estava no meio da que pertencia à tribo de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'E tiveram por herança Berseba, Seba, Molada,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Hazar-Sual, Balá, Ezem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolade, Betul e Hormá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Simeão ainda recebeu Ziclague, Bete-Mercabote, Hazar-Susa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Bete-Lebaote e Saruém; estas treze cidades incluíam seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Simeão também recebeu Aim, Rimon, Eter e Asã; estas quatro cidades, incluindo seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Todos estes, inclusive os vilarejos que estavam ao redor dessas cidades, até Baalate-Ber (que é Ramá do Neguebe). Essa foi a herança da tribo de Simeão, distribuída segundo seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'A herança da tribo de Simeão fazia parte do território da tribo de Judá. Por causa do grande tamanho da terra distribuída à tribo de Judá, a tribo de Simeão recebeu sua herança no meio da porção deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'A terceira sorte saiu para a tribo de Zebulom, e foi distribuída segundo seus clãs. A fronteira de sua herança começava em Saride;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'a fronteira subia pelo oeste até Marala e tocava em Dabesete; dali, se estendia até o ribeiro próximo a Jocneão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'De Saride, a fronteira seguia para o leste até o limite com Quislote-Tabor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Dali, passava para o leste até Gate-Hefer e Ete-Cazim; depois, chegava a Rimom-Metoar e virava-se para Neá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'A fronteira norte se voltava em direção a Hanatom e terminava no vale de Iftael.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Esta região inclui as cidades de Catate, Naalal, Sinrom, Idala, e Belém. Eram doze cidades, incluindo seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Essa foi a herança da tribo de Zebulom, segundo seus clãs, as cidades e os seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'A quarta sorte saiu para Issacar, segundo os seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'E seu território incluía Jezreel, Quesulote, Suném,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hafaraim, Siom e Anaarate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Também incluía Rabite, Quisiom, Abes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remete, En-Ganim, En-Hada e Bete-Pazez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'A fronteira deles chegava até Tabor, Saazima, e Bete-Semes, e terminava no Jordão; eram dezesseis cidades e os seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Essa foi a herança da tribo de Issacar, segundo seus clãs; as cidades, incluindo seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'A quinta sorte saiu para a tribo de Aser, segundo seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'O seu território incluía Helcate, Hali, Bétem, Acsafe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alameleque, Amade, e Misal. A sua fronteira se estendia ao oeste para Carmelo e Sior-Libnate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Depois se virava ao leste para Bete-Dagom e ia até Zebulom; e, então, para o vale de Iftael, ao norte até Bete-Emeque e Neiel; e chegava até Cabul em direção ao norte,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'e se estendia até Ebrom, Reobe, Hamom, e Caná, até a grande Sidom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'A fronteira voltava-se em direção a Ramá; dali, para a cidade fortificada de Tiro; então, tornava-se para Hosa e, de lá, para o mar, na região de Aczibe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Umá, Afeca, e Reobe. Eram vinte e duas cidades, com seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Essa foi a herança da tribo de Aser, segundo seus clãs, as cidades e seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'A sexta sorte saiu para a tribo de Naftali, segundo seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'A fronteira deles ia desde Helefe, desde o carvalho até Zaananim, para Adâmi-Nequebe e Jabneel, assim como Lacum, e terminava no Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'A fronteira virava-se para o ocidente para Aznote-Tabor e ia para Hucoque; e chegava a Zebulom, no sul, e alcançava Aser no lado oeste e Judá a leste, à margem do rio Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'As cidades fortalecidas foram Zidim, Zer, Hamate, Recate, Quinerete,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Ramá, Hazor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Quedes, Edrei, En-Hazor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Existiam também Irom, Migdal-El, Horem, Bete-Anate, e Bete-Semes. Eram dezenove cidades, com seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Essa foi a herança da tribo de Naftali, segundo seus clãs, as e cidades, incluindo seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'A sétima sorte saiu para a tribo de Dã, segundo seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'O território de sua herança incluía Zorá, Estaol, Ir-Semes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Saalabim, Aijalom, e Itla.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Também incluía Elom, Timnate, Ecrom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteque, Gibetom, Baalate,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jeúde, Bene-Beraque, Gate-Rimom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Me-Jarcom, e Racom com o território defronte de Jope.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'O território da tribo de Dã foi pequeno para eles; então, os descendentes de Dã atacaram Lesem, lutaram contra ela, e a conquistaram. Eles mataram todos com espada, tomaram posse da terra, e se apoderaram dela. Eles mudaram o nome de Lesem, e a chamaram de Dã por causa de seu antepassado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Esta foi a herança da tribo de Dã, segundo seus clãs, e as cidades, incluindo seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Quando terminaram de repartir suas terras como herança, o povo de Israel deu uma herança dentre eles para Josué, filho de Num.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Por ordem de Yahweh, eles lhe deram a cidade que ele pediu: Timnate-Sera, na região montanhosa de Efraim. Ele a reconstruiu e ali morou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Estas foram as heranças que Eleazar, o sacerdote, Josué, filho de Num, e os líderes tribais de famílias de seus antepassados dentro do povo de Israel, distribuíram, por sorteio, em Siló, diante de Yahweh, na entrada da Tenda do Encontro. Assim, eles terminaram de repartir a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Então, Yahweh disse a Josué:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, '\"Fala ao povo de Israel, dizendo: \'Designai as cidades de refúgio de que Eu vos falei por meio de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Fazei isto para que alguém que tenha matado uma pessoa involuntariamente possa ir para lá. Essas cidades serão lugar de refúgio contra qualquer um que procura vingar o sangue de alguém que foi morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Aquele que matou correrá para uma dessas cidades, ficará à entrada do seu portão e explicará seu caso aos anciãos daquela cidade. Então, eles o levarão para dentro da cidade e lhes darão um lugar para habitar entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'E, se alguém vier tentar vingar o sangue de quem foi morto, as pessoas da cidade não lhe entregarão aquele que matou. Eles não o farão, pois matou seu próximo sem intenção e não tinha nenhum ódio por ele anteriormente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'O homicida deve permanecer naquela cidade até que compareça diante da assembleia para julgamento, e ali permanecerá até a morte do sumo sacerdote que estava servindo naqueles dias. Então, aquele que, acidentalmente, matou alguém poderá voltar à sua própria cidade e à sua casa, à cidade de onde fugiu\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Então, os israelitas designaram Quedes, na Galileia, na região montanhosa de Naftali; Siquém, na região montanhosa de Efraim; e Queriate-Arba (que é Hebrom), na região montanhosa de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Além do Jordão, a leste de Jericó, designaram Bezer, no deserto no planalto da tribo de Rúben; Ramote, em Gileade, da tribo de Gade; e Golã, em Basã, da tribo de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Essas foram as cidades designadas para todo o povo de Israel e para os forasteiros que habitam entre eles, para que aquele que matar alguém, sem intenção, possa fugir até elas, buscando segurança. Esse não morrerá pela mão daquele que deseja vingar o sangue que foi derramado, sem haver sido apresentado à assembleia para ser julgado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Então, os líderes tribais dos levitas foram até Eleazar, o sacerdote, e a Josué, filho de Num, e até os líderes das famílias de seus antepassados dentro do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'E disseram-lhes em Siló, na terra de Canaã: \"Yahweh vos ordenou, pela mão de Moisés, que nos désseis cidades para nela habitar, e pastagens para o nosso gado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Então, pela ordem de Yahweh, o povo de Israel deu de suas heranças aos levitas as seguintes cidades e seus pastos:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'O clã dos coatitas foi sorteado. Assim, os sacerdotes, os descendentes de Arão, que eram dos levitas, receberam treze cidades da tribo de Judá, da tribo de Simeão, e da tribo de Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'As outras famílias do clã coatita receberam, por meio de sorteio, dez cidades dos clãs das tribos de Efraim, Dã e da metade da tribo de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'E os descendentes de Gérson, por sorteio, receberam treze cidades dos clãs das tribos de Issacar, Aser, Naftali e da metade da tribo de Manassés em Basã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'O povo que era descendente de Merari, clã por clã, recebeu doze cidades das tribos de Rúben, Gade e Zebulom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Assim, o povo de Israel deu essas cidades, incluindo os seus pastos, para os levitas, através de sorteio, como Yahweh os havia ordenado pela mão de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Das tribos de Judá e Simeão, eles designaram mais algumas cidades da terra, aqui listadas por nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Elas foram dadas aos descendentes de Arão, que estavam entre os clãs dos coatitas, que eram da tribo de Levi. Porque eles foram os primeiros a serem sorteados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Os israelitas lhes deram Quiriate-Arba (Arba era o pai de Anaque), que é mesmo lugar que Hebrom, na região montanhosa de Judá, com as pastagens ao seu redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Mas os campos da cidade e os seus vilarejos já haviam sido dados a Calebe, filho de Jefoné, como sua propriedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Para os descendentes de Arão, o sacerdote, deram Hebrom com suas pastagens, que era uma cidade de refúgio para quem matasse outro sem intenção, e Libna com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jatir com as suas pastagens e Estemoa com suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Também deram Holom com suas pastagens, Debir com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Aim com suas pastagens, Jutá com os suas pastagens, Bete-Semes com suas pastagens. Foram dadas nove cidades dessas duas tribos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Da tribo de Benjamim, foram dadas Gibeão com suas pastagens, Geba com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatote com suas pastagens, e Almom com suas pastagens, quatro cidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'As cidades que foram dadas aos sacerdotes, os descendentes de Arão, foram treze cidades ao todo, incluindo suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Quanto ao restante das famílias dos filhos de Coate, levitas que pertencem aos clãs dos coatitas, receberam, por sorteio, estas cidades da tribo de Efraim:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Foram-lhes dadas Siquém com suas pastagens na região montanhosa de Efraim, cidade de refúgio para qualquer que matar alguém sem intenção, Gezer com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Quibzaim com os suas pastagens e Bete-Horom com suas pastagens. Quatro cidades ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Da tribo de Dã, foram dadas ao clã de Coate: Elteque com suas pastagens, Gibetom com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Aijalom com suas pastagens e Gate-Rimon com suas pastagens. Quatro cidades ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Da meia tribo de Manassés, duas cidades foram dadas ao clã de Coate: Taanaque com suas pastagens e Gate-Rimon com suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Houve dez cidades ao todo para os demais dos clãs coatitas, incluindo suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Da meia tribo de Manassés, duas cidades foram dadas aos clãs de Gérson (que eram outros clãs de levitas): Golã, em Basã, com suas pastagens, uma cidade de refúgio para qualquer que matar alguém sem intenção, juntamente com Beesterá e suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Para os clãs de Gérson também deram Quisiom, da tribo de Issacar, com suas pastagens, Daberate com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmute com suas pastagens, e En-Ganim com suas pastagens. Quatro cidades ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Da tribo de Aser, deram Misal com suas pastagens, Abdom com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helcate com suas pastagens, e Reobe com suas pastagens. Quatro cidades ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Da tribo de Naftali, foram dadas aos clãs de Gerson: Quedes com suas pastagens, na Galileia, cidade de refúgio para qualquer que matar alguém sem intenção; Hamote-Dor com suas pastagens, Cartã com os suas pastagens. Três cidades ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Houve treze cidades ao todo, dos clãs de Gérson, incluindo suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Para os demais levitas, os clãs de Merari, foram-lhes dadas da tribo de Zebulom: Jocneão com suas pastagens, Cartá com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna com suas pastagens, e Naalal com suas pastagens. Quatro cidades ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Para os clãs de Merari, quatro cidades foram dadas da tribo de Rúben: Bezer com suas pastagens, Jaza com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Quedemote com suas pastagens, Mefaate com suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'E, da tribo de Gade, foram-lhes dadas Ramote com suas pastagens, que fica em Gileade, cidade de refúgio para qualquer que matar alguém sem intenção, e Maanaim com suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Aos clãs de Merari também foram dadas Hesbom com suas pastagens, e Jazer com suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Todas essas cidades foram dadas aos vários clãs de Merari, que eram da tribo de Levi. Doze cidades ao todo lhes foram dadas por meio de sorteio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'As cidades dos levitas, localizadas no meio da terra que estava sob posse do povo de Israel, foram quarenta e oito cidades, incluindo suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Cada uma dessas cidades tinha suas pastagens ao redor. Assim foi com todas elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Dessa maneira Yahweh deu a Israel toda a terra que Ele havia prometido dar aos seus antepassados. Os israelitas a possuíram e nela habitaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Assim, Yahweh lhes deu descanso de todos os lados, conforme havia prometido aos seus antepassados. Nenhum de seus inimigos lhes pôde resistir. Yahweh entregou todos os seus inimigos nas suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Nenhuma das boas promessas que Yahweh falou para a casa de Israel falhou. Todas elas se cumpriram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Naquele momento, Josué chamou os rubenitas, os gaditas e a meia-tribo de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'Ele lhes disse: \"Vós tendes feito tudo o que Moisés, o servo de Yahweh, vos ordenou; vós tendes obedecido à minha voz em tudo o que vos ordenei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Não abandonastes os vossos irmãos em momento nenhum desses muitos dias, até hoje. Em vez disso, vós tendes obedecido às instruções dos mandamentos de Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Agora Yahweh, vosso Deus, deu descanso a vossos irmãos, assim como lhes havia prometido. Portanto, voltai e ide para as vossas tendas em vossa própria terra, que Moisés, o servo de Yahweh, vos deu do outro lado do Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Apenas tende cuidado de guardar os mandamentos e a lei que Moisés, o servo de Yahweh, vos ordenou: amai Yahweh, vosso Deus, andai em Seus caminhos, guardai os Seus mandamentos, e apegai-vos a Ele, e servi-O com todo o vosso coração e com toda a vossa alma\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Então, Josué os abençoou e os despediu; e eles voltaram para suas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Para a meia-tribo de Manassés, Moisés dera por herança terras em Basã, mas para a outra metade, Josué deu herança entre seus irmãos, na terra ao oeste do Jordão. E Josué os enviou para suas tendas, e os abençoou,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'dizendo: \"Retornai para vossas tendas com muitas riquezas, rebanhos, prata e ouro, bronze e ferro, e com muitas vestes. Reparti com vossos irmãos o despojo dos vossos inimigos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Então, os descendentes de Rúben, os descendentes de Gade e meia-tribo de Manassés voltaram para casa, deixando o povo de Israel em Siló, que está na terra de Canaã. Eles foram para a região de Gileade, para sua própria terra, da qual eles mesmos tomaram posse, em obediência ao mandamento de Yahweh, dado pelas mãos de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Quando eles chegaram ao Jordão, na terra de Canaã, os rubenitas, os gaditas e a meia-tribo de Manassés edificaram um altar ao lado do Jordão, um altar grande e imponente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'O povo de Israel ouviu sobre isso e disse: \"Vede! Os povos de Rúben, Gade e da meia-tribo de Manassés edificaram um altar na frente da terra de Canaã, em Gileade, na região próxima ao Jordão, no lado pertencente ao povo de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Quando o povo de Israel ouviu isso, toda a assembleia reuniu-se em Siló para fazer guerra contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Então, o povo de Israel enviou mensageiros aos rubenitas, aos gaditas e à meia-tribo de Manassés, na terra de Gileade. Eles também enviaram Finéias, filho de Eleazar, o sacerdote,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'e, com ele, dez líderes, um de cada família das tribos de Israel, todos eles chefes de famílias entre os clãs de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Eles foram ao encontro dos povos de Rúben, Gade e da meia-tribo de Manassés, na terra de Gileade, e disseram-lhes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, '\"Toda a assembleia de Yahweh diz isto: \'Que desobediência é essa que vós cometestes contra o Deus de Israel, deixando de seguir Yahweh, edificando um altar para vos rebelardes hoje contra Yahweh?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Nosso pecado, em Peor, não bastou para nós? Até agora não nos purificamos dele. Por causa daquele pecado veio uma praga sobre a comunidade de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Vós abandonareis Yahweh no dia de hoje? Se vos rebelardes contra Yahweh hoje, amanhã Ele estará irado contra toda a comunidade de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Se a terra que recebestes está impura, então, passai para a terra onde fica o Tabernáculo de Yahweh e tomai posse de terras entre nós. Porém, não vos rebeleis contra Yahweh, nem contra nós, edificando um altar para vós, um altar que não seja o altar de Yahweh, nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Não foi Acã, filho de Zerá, que quebrou a confiança em relação às coisas que foram reservadas para Deus? E não foi por isso que a ira caiu sobre o povo de Israel? Aquele homem não pereceu sozinho por sua iniquidade\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Então, as tribos de Rúben, Gade e a meia-tribo de Manassés disseram em resposta aos cabeças dos clãs de Israel:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, '\"O Poderoso Deus, Yahweh! O Poderoso Deus, Yahweh! Ele sabe e que Israel também saiba! Se isso foi em rebeldia ou infidelidade contra Yahweh, não nos poupe neste mesmo dia');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'por termos edificado um altar para abandonar Yahweh. Se edificamos esse altar para oferecer holocausto, ofertas de cereais ou ofertas pacíficas, então, que Yahweh nos faça pagar por isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Não! Nós o fizemos por receio de que, no futuro, os vossos filhos digam aos nossos filhos: \'O que tendes com Yahweh, o Deus de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Pois Yahweh fez o Jordão como fronteira entre nós e vós. Vós, filhos de Rúben e filhos de Gade, não tendes parte com Yahweh\'. Então, vossos filhos poderiam fazer com que os nossos filhos deixassem de adorar a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Por isso, dissemos: \'Edifiquemos agora um altar, não para holocausto, nem para quaisquer sacrifícios,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'mas para ser testemunho entre nós e vós e entre as gerações futuras, para que cultuemos a Yahweh diante Dele, com nossos holocaustos, nossos sacrifícios e nossas ofertas pacíficas, para que os vossos filhos nunca digam aos nossos filhos, no futuro: \'Não tendes parte com Yahweh\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Então, dissemos: \'Se isto for dito a nós ou aos nossos descendentes, então diremos: Vede! Esta é uma cópia do altar de Yahweh, que nossos antepassados fizeram, não para holocaustos, nem para sacrifícios, mas como testemunho entre nós e vós’.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Longe esteja de nós nos rebelarmos contra Yahweh e deixar de segui-Lo hoje, edificando um altar para holocaustos, ofertas de cereais ou para sacrifícios, além do altar de Yahweh, nosso Deus, que está perante o seu tabernáculo\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Quando Fineias, o sacerdote, e os líderes do povo, que são os cabeças dos clãs de Israel, ouviram as palavras que o povo de Rúben, Gade e Manassés disseram, isso foi agradável aos seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Fineias, filho de Eleazar, o sacerdote, disse ao povo de Rúben, Gade e Manassés: \"Hoje sabemos que Yahweh está entre nós, pois vós não fostes infiéis a Ele. Agora livrastes o povo de Israel da mão de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Assim, Fineias, filho de Eleazar, o sacerdote e os líderes retornaram do encontro dos rubenitas e dos gaditas, voltaram da terra de Gileade para a terra de Canaã, para o povo de Israel, e trouxeram resposta a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Sua resposta foi boa aos olhos do povo de Israel. O povo bendisse a Deus e não mais falou sobre fazer guerra contra os rubenitas e os gaditas, para destruir a terra na qual eles habitavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Os rubenitas e os gaditas chamaram o altar de \"Testemunho\", pois disseram: \"É um testemunho entre nós de que Yahweh é Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'E depois de muitos dias, quando Yahweh deu descanso para Israel de todos os inimigos que o cercavam, Josué estava muito velho, de idade avançada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Josué chamou todo o Israel, com seus anciãos, seus líderes, seus juízes e seus oficiais e disse-lhes: \"Eu estou muito velho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Vós tendes visto tudo o que Yahweh, vosso Deus, fez a todas as nações para o vosso bem, pois foi Yahweh, vosso Deus, quem lutou por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Vede! Eu distribuí entre vós as nações que restam ser conquistadas como uma herança para as vossas tribos, juntamente com todas as nações que já destruí, desde o Jordão até o grande Mar no oeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Yahweh, vosso Deus, as expulsará. Ele as expulsará de diante de vós. Ele tomará suas terras, e vós tomareis posse delas, assim como Yahweh, vosso Deus, vos prometeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Por isso, sede muito fortes, para que guardeis e façais assim como está escrito no Livro da Lei de Moisés, para que dela não desvieis nem para a direita, nem para a esquerda;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'a fim de não vos misturardes com essas nações que restarem em vosso meio, nem mencionardes os nomes de seus deuses, nem jurardes por eles, nem os adorardes, nem vos prostrardes diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Mas apegai-vos a Yahweh, vosso Deus, assim como tendes feito até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Pois Yahweh expulsou de diante de vós grandes e poderosas nações. Ninguém foi capaz de vos resistir até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Um único homem dentre vós fará correr mil deles, pois Yahweh, vosso Deus, é Aquele que luta por vós, assim como Ele vos prometeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Dedicai-vos a amar Yahweh, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Porém, se voltardes atrás e vos apegardes aos sobreviventes dessas nações que restarem no meio de vós, ou vos casardes com eles, ou vos unirdes com eles e eles convosco,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'então, sabei que, certamente, Yahweh, vosso Deus, não mais expulsará essas nações do meio de vós. Em vez disso, elas se tornarão um laço e armadilha para vós, açoites para as vossas costas, e espinhos nos vossos olhos, até que pereçais nesta boa terra que Yahweh, vosso Deus, vos deu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Em breve, irei pelo caminho de toda a terra. Vós sabeis, de todo o vosso coração e alma, que nenhuma palavra falhou de todas as boas coisas que Yahweh, vosso Deus, vos prometeu. Todas essas promessas se cumpriram. Nenhuma delas falhou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Mas, assim como se cumpriu toda palavra que Yahweh, vosso Deus, prometeu, assim Yahweh trará sobre vós todo o mal, até que Ele vos tenha destruído sobre esta boa terra que Yahweh, vosso Deus, vos deu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Ele fará isso se vós quebrardes a aliança de Yahweh, vosso Deus, a qual Ele ordenou que guardeis. Se adorardes outros deuses e vos prostardes diante deles, então, a ira de Yahweh se acenderá contra vós e, rapidamente, perecereis na boa terra que Ele vos deu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Então, Josué reuniu todas as tribos de Israel em Siquém, e chamou os anciãos de Israel, seus líderes, seus juízes e oficiais, e eles se apresentaram diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Josué disse a todo o povo: \"Isto é o que Yahweh, o Deus de Israel, diz: \'Vossos antepassados, Terá, pai de Abraão, e Naor viviam além do rio Eufrates, e adoravam outros deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Porém, Eu tomei vosso pai Abraão de além do Eufrates e o conduzi para a terra de Canaã e lhe dei muitos descendentes através do seu filho Isaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'E a Isaque dei Jacó e Esaú. Dei a Esaú a região de Seir como posse, mas Jacó e seus filhos desceram para o Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Enviei Moisés e Arão, e afligi os egípcios com pragas. Após isso, Eu vos tirei de lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Eu trouxe vossos antepassados do Egito e vós chegastes até o mar. Os egípcios os perseguiram com carruagens e cavaleiros até o mar Vermelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Quando vossos antepassados clamaram a Yahweh, Ele pôs uma escuridão entre vós e os egípcios. Ele lançou o mar por cima deles e os cobriu. Vós vistes o que fiz no Egito. Depois, habitastes no deserto por um longo tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Eu vos trouxe para a terra dos amorreus, que habitavam no outro lado do Jordão. Eles batalharam contra vós e Eu os entreguei em vossas mãos. Tomastes posse da terra deles e Eu os destruí diante de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Então, Balaque, filho de Zipor, rei de Moabe, levantou-se e atacou Israel. Ele mandou chamar Balaão, filho de Beor, para que vos amaldiçoasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Mas Eu não ouvi Balaão. Na verdade, ele vos abençoou. Assim, Eu vos resgatei das mãos dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Vós atravessastes o Jordão e fostes para Jericó. Os líderes de Jericó batalharam contra vós, assim como os amorreus, os perizeus, os cananeus, os heteus, os girgaseus, os heveus e os jebuseus. Eu vos dei a vitória e os coloquei debaixo de vosso controle.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Enviei vespas adiante de vós, que os expulsaram, assim como os dois reis dos amorreus diante de vós. Isto não aconteceu por vossas espadas ou por vossos arcos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Eu vos dei terras em que não trabalhastes e cidades que não edificastes e agora habitais nelas. Comestes do fruto de vinhas e oliveiras que não plantastes\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Agora, temei a Yahweh e servi-O com toda integridade e fidelidade. Jogai fora os deuses que vossos antepassados serviram além do Eufrates e no Egito e cultuai Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Se parecer errado aos vossos olhos cultuar Yahweh, escolhei hoje para vós mesmos a quem servireis. Se aos deuses que vossos antepassados serviram além do Eufrates, ou aos deuses dos amorreus, em cuja terra habitais. Mas, quanto a mim e a minha casa, nós serviremos a Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'O povo respondeu, dizendo: \"Nós jamais abandonaríamos Yahweh para servir a outros deuses,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'pois Yahweh é o nosso Deus, que nos trouxe, a nós e aos nossos ancestrais, da terra do Egito, da casa da escravidão, que fez esses grandes sinais à nossa vista, e que nos preservou em todo o caminho que andamos e entre todas as nações pelas quais passamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Depois, Yahweh expulsou diante de nós todos os povos, inclusive os amorreus que habitavam nesta terra. Então, nós também serviremos a Yahweh, porque Ele é o nosso Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Josué disse ao povo: \"Não podereis servir a Yahweh, porque Ele é um Deus santo. Ele é um Deus zeloso que não perdoará vossas transgressões e pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Se abandonardes Yahweh e servirdes a deuses estrangeiros, então, Ele Se voltará contra vós e vos afligirá. Ele vos consumirá, mesmo depois de ter feito o bem a vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Mas o povo disse a Josué: \"Não, nós serviremos a Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Então, Josué disse ao povo: \"Sois testemunhas contra vós mesmos de que escolhestes servir a Yahweh\". Eles disseram: \"Somos testemunhas\". Josué disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, '\"Agora, jogai fora os deuses estrangeiros que estão convosco e inclinai o vosso coração a Yahweh, o Deus de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'O povo disse a Josué: \"Nós serviremos a Yahweh, nosso Deus. Ouviremos a Sua voz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Josué fez uma aliança com o povo naquele dia. Ele lhe deu estatutos e leis em Siquém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Josué escreveu essas palavras no Livro da Lei de Deus. Pegou uma grande pedra e pôs debaixo do carvalho que ficava ao lado do santuário de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Josué disse a todo o povo: \"Vede! Esta pedra será testemunha contra nós. Ela ouviu todas as palavras que Yahweh nos disse. Assim, ela será testemunha contra vós, para que nunca negueis o vosso Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Então, Josué despediu o povo, cada um para a sua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Depois dessas coisas, Josué, filho de Num, o servo de Yahweh, morreu, com cento e dez anos de idade;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'e o sepultaram no território de sua herança, em Timnate-Sera, que está na região montanhosa de Efraim, ao norte do monte Gáas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Israel serviu a Yahweh por todos os dias de Josué e por todos os dias dos anciãos que sobreviveram a Josué, aqueles que vivenciaram tudo o que Yahweh havia feito por Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Os ossos de José, que o povo de Israel trouxe do Egito, foram enterrados em Siquém, na parte de terra que Jacó comprara dos filhos de Hamor, o pai de Siquém. Ele a comprou por cem peças de prata, e ela se tornou herança para os descendentes de José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Eleazar, filho de Arão, também morreu e foi sepultado em Gibeá, a cidade que fora dada a Fineias, seu filho. Esta ficava na região montanhosa de Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Após a morte de Josué, o povo de Israel perguntou a Yahweh, dizendo: \"Quem de nós atacará primeiro os cananeus para lutar contra eles?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Yahweh disse: \"Judá os atacará. Vede, Eu estou lhes dando o controle dessa terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Os homens de Judá disseram aos homens de Simeão, seus irmãos: \"Vinde conosco ao território que nos foi designado, para juntos lutarmos contra os cananeus. E nós iremos também convosco ao território que vos foi designado\". Então, a tribo de Simeão foi com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Os homens de Judá atacaram, e Yahweh lhes deu vitória sobre os cananeus e os perizeus. Eles mataram dez mil homens em Bezeque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Nessa cidade, encontraram Adoni-Bezeque e lutaram contra ele e derrotaram os cananeus e os perezeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Adoni-Bezeque escapou, mas eles o perseguiram e o pegaram e cortaram-lhe os dedos polegares das mãos e dos pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Então, Adoni-Bezeque disse: \"Setenta reis que tiveram seus dedos polegares das mãos e dos pés cortados ajuntavam comida debaixo da minha mesa. Assim como eu fiz, também fez Deus a mim\". Eles o levaram a Jerusalém, e lá ele morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Os homens de Judá lutaram contra Jerusalém e a tomaram. Eles a atacaram ao fio da espada, e puseram fogo na cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Depois disso, os homens de Judá desceram para lutar contra os cananeus que viviam na região montanhosa, no Neguebe, e na baixada ocidental.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Os homens de Judá avançaram contra os cananeus que viviam em Hebrom (o nome de Hebrom, anteriormente, era Quiriate-Arba) e derrotaram Sesai, Aimã e Talmai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'De lá, os homens de Judá avançaram contra os habitantes de Debir (o nome de Debir, anteriormente, era Quiriate-Sefer).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Calebe disse: \"Quem atacar Quiriate-Sefer e a tomar, eu lhe darei Acsa, minha filha, para ser sua esposa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Otoniel, filho de Quenaz (irmão mais novo de Calebe), capturou Debir. Então, Calebe lhe deu Acsa, sua filha, para ser sua esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Um dia, Acsa veio a Otoniel e insistiu que pedisse ao pai dela que lhe desse um campo. Enquanto estava descendo do jumento, Calebe lhe perguntou: \"O que posso fazer por ti?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Ela lhe respondeu: \"Dá-me uma bênção. Já que me deste a terra do Neguebe, dá-me também fontes de água\". Então, Calebe lhe deu as fontes superiores e as inferiores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Os descendentes do sogro de Moisés, o queneu, foram com o povo de Judá da cidade das Palmeiras até o deserto de Judá, que está no Neguebe, para viver com o povo de Judá, perto de Arade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'A tribo de Judá se uniu à de Simeão, seus irmãos, e atacaram os cananeus que habitavam Zefate, destruindo completamente a cidade. Por isso, ela passou a ser chamada Hormá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'O povo de Judá também capturou Gaza e a terra em torno dela, Asquelom e a terra em torno dela, e Ecrom e a terra em torno dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Yahweh estava com o povo de Judá. Eles tomaram posse da região montanhosa, mas não puderam expulsar os habitantes das planícies porque possuíam carruagens de guerra feitas de ferro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Hebrom foi dada a Calebe, conforme Moisés havia dito, e ele expulsou de lá os três filhos de Anaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Mas o povo de Benjamim não expulsou os jebuseus que habitavam Jerusalém. Por esta razão, os jebuseus têm vivido com o povo de Benjamim, em Jerusalém, até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'A casa de José preparou-se para atacar Betel, e Yahweh estava com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Enviaram espiões a Betel, a cidade que antigamente chamava-se Luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Os espiões viram um homem vindo de fora da cidade, e disseram-lhe: \"Mostra-nos, por favor, como entrar na cidade, e seremos bondosos contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Ele lhes mostrou um caminho. Então, atacaram a cidade ao fio da espada, mas deixaram que aquele homem e sua família fugissem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'O homem foi para a terra dos heteus, onde construiu uma cidade e a chamou de Luz, que é seu nome até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'O povo de Manassés não expulsou o povo que vivia nas cidades de Bete-Seã e suas vilas, ou Taanaque e suas vilas, ou aqueles que viviam em Ibleão e suas vilas, ou aqueles que viviam em Megido e suas vilas, porque os cananeus estavam determinados a viver naquela terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Quando Israel tornou-se forte, eles forçaram os cananeus a servi-los com trabalhos forçados. Porém, nunca os expulsaram de lá completamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Efraim também não expulsou os cananeus que viviam em Gezer. Assim, os cananeus continuaram a viver no meio deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zebulom não expulsou os habitantes de Quitrom, ou os habitantes de Naalol. Assim, os cananeus continuaram a viver entre eles, mas Zebulom os obrigou a servi- los com trabalhos forçados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Aser não expulsou os habitantes de Aco, ou os habitantes de Sidom, nem os habitantes de Alabe, Aczibe, Helba, Afeca e Reobe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Então, as tribos de Aser viveram entre os cananeus (aqueles que habitavam a terra) porque não os expulsaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'A tribo de Naftali não expulsou os habitantes de Bete-Semes, ou os habitantes de Bete-Anate. Assim, a tribo de Naftali viveu entre os cananeus (aqueles que habitavam a terra). No entanto, os habitantes de Bete-Semes e Bete-Anate foram submetidos a trabalhos forçados para o povo de Naftali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Os amorreus forçaram a tribo de Dã a viver na região montanhosa, não lhes permitindo descer à planície.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Os amorreus habitaram no monte Heres, em Aijalom, e em Saalabim. Mas o poderio militar da casa de José os conquistou, e eles foram sujeitados a servi-los com trabalhos forçados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'A fronteira dos amorreus ia do monte de Acrabim até Selá, da região montanhosa para cima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'O Anjo de Yahweh subiu de Gilgal a Boquim, e disse: \"Eu vos tirei do Egito, e vos trouxe para a terra que jurei dar aos vossos pais. Eu disse: \'Nunca quebrarei a Minha aliança convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Não façais aliança com aqueles que moram nesta terra. Derrubai os seus altares\'. Porém, não ouvistes a Minha voz. Por que fizestes isso?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Então, agora, digo: Não tirarei os cananeus diante de vós, mas eles se tornarão espinhos ao vosso lado, e os seus deuses se tornarão uma pedra de tropeço para vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Quando o Anjo de Yahweh falou estas palavras a toda a comunidade de Israel, o povo levantou sua voz e chorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Chamaram aquele lugar de Boquim. Ali, ofereceram sacrifícios a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Depois que Josué despediu o povo, os filhos de Israel foram cada um para seus respectivos lugares, para possuir suas terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'O povo serviu Yahweh durante o tempo de Josué e dos anciãos que continuaram vivos após ele, os quais viram as grandes obras que Yahweh havia feito a Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Josué, filho de Num, servo de Yahweh, morreu com a idade de cento e dez anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Foi sepultado no território de sua herança em Timnate-Heres, na região montanhosa de Efraim, ao norte do monte Gaás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Toda aquela geração também se juntou aos seus pais. E, após essa, levantou-se uma outra geração que não conhecia Yahweh, nem o que Ele fizera por Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'O povo de Israel fez o que era mau aos olhos de Yahweh e serviram aos baalins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Eles se separaram de Yahweh, o Deus de seus pais, Aquele que os havia tirado da terra do Egito. Eles foram atrás de outros deuses, os mesmos deuses dos povos que estavam em sua volta, e se inclinaram perante eles. Provocaram a ira de Yahweh, pois');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'se separaram de Yahweh e adoraram a Baal e a Astarotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'A ira de Yahweh se acendeu contra Israel, e Ele os entregou aos ladrões, que roubaram suas posses. Ele os vendeu como escravos que foram tomados pela força dos inimigos ao seu redor, de maneira que não puderam mais se defender.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Toda vez que Israel saía para lutar, a mão de Yahweh estava contra eles para derrotá-los, assim como Ele lhes havia jurado. Estavam em uma terrível aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Então, Yahweh levantou juízes que os salvaram das mãos daqueles que estavam roubando suas posses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Mesmo assim, eles não ouviram os seus juízes. Eles foram infiéis a Yahweh, entregando-se a prostituição: adorando a outros deuses. Eles rapidamente se desviaram do caminho em que seus pais haviam vivido, pois seus pais obedeceram aos mandamentos de Yahweh, porém eles mesmos não o fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Quando Yahweh levantava juízes para eles, Ele ajudava os juízes e os resgatava das mãos dos seus inimigos em todos os dias em que o juiz vivia. Pois Yahweh tinha piedade deles e de como gemiam por causa daqueles que os oprimiam e afligiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Mas quando o juiz morria, eles se desviavam e faziam coisas que eram ainda mais depravadas do que aquelas que os seus pais haviam feito. Eles seguiam outros deuses para os servir e adorar. Eles se recusavam a se arrepender de suas práticas malignas e de seus caminhos teimosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'A ira de Yahweh se acendeu contra Israel. Ele disse: \"Porque esta nação quebrou os termos da Minha aliança que fiz com seus pais, porque não escutaram a Minha voz,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'de agora em diante, Eu não retirarei diante deles nenhuma das nações que Josué deixou quando morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Farei isto para colocar Israel à prova, se eles guardarão, ou não, o caminho de Yahweh; se andarão nele, assim como seus pais o fizeram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Por isso, Yahweh deixou aquelas nações e não as expulsou rapidamente, nem as entregou nas mãos de Josué.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Ora, Yahweh deixou estas nações para pôr Israel à prova, isto é, todos em Israel que não haviam lutado nas guerras em Canaã');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, '(Ele fez isto para que a nova geração de israelitas, que não tinha experiência, aprendesse a guerrear):');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'cinco reis dos filisteus, todos os cananeus, os sidônios e os heveus que habitavam nos montes do Líbano, desde o monte Baal-Hermom até Lebo-Hamate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Estas nações foram deixadas por Yahweh para provar Israel, a fim de averiguar se obedeceriam aos mandamentos que Ele dera aos seus antepassados, por intermédio de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Assim, o povo de Israel viveu entre os cananeus, os heteus, os amorreus, os perizeus, os heveus e os jebuseus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Casaram-se com as filhas destes, assim como deram suas próprias filhas, em casamento, aos filhos deles. E adoraram os seus deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'O povo de Israel fez o que era mau aos olhos de Yahweh e se esqueceu de Yahweh, o seu Deus. Eles adoraram os baalins e Aserá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Por isso, a ira de Yahweh se acendeu contra Israel, e Ele os entregou nas mãos de Cuchã-Risataim, rei da Mesopotâmia. Eles serviram a Cuchã-Risataim por oito anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Quando o povo de Israel clamou a Yahweh, Yahweh levantou um libertador que viesse socorrê-los, o qual os libertaria: Otoniel, filho de Quenaz, irmão mais novo de Calebe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'O Espírito de Yahweh o capacitou, e ele julgou Israel e saiu para a guerra. Yahweh deu-lhe vitória sobre Cuchã-Risataim, rei da Mesopotâmia. A mão de Otoniel derrotou Cuchã-Risataim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'A terra teve paz por quarenta anos. Então, Otoniel, filho de Quenaz, morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Depois disso, os israelitas fizeram, novamente, o que era mau aos olhos de Yahweh. Então, Yahweh deu forças a Eglom, rei de Moabe, para se apoderar dos israelitas, porque haviam feito o que era mau aos olhos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Eglom se uniu aos amonitas e aos amalequitas e, juntos, derrotaram Israel e tomaram a posse da cidade das Palmeiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Os israelitas serviram a Eglom, rei de Moabe, por dezoito anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Quando o povo de Israel clamou a Yahweh, Yahweh levantou um libertador que os socorreria: Eúde, filho de Gera, um benjamita, homem canhoto. O povo de Israel o enviou, junto com os tributos, a Eglom, rei de Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Eúde fez para si uma espada de dois gumes, com um côvado de comprimento. Ele amarrou-a, por baixo da roupa, na sua coxa direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Ele entregou os tributos ao rei Eglom, de Moabe. Ora, Eglom era um homem muito gordo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Após Eúde ter deixado ali os tributos, ele saiu com os homens que haviam ajudado a carregá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Todavia, o próprio Eúde, quando chegou ao lugar onde havia imagens esculpidas perto de Gilgal, voltou e disse: \"Tenho uma mensagem secreta para ti, meu rei\". Eglom disse: \"Silêncio!\". Então, todos que o serviam deixaram a sala.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Eúde veio até ele. O rei se encontrava sentado sozinho num quarto superior de verão. Eúde disse: \"Tenho uma mensagem de Deus para ti\". O rei levantou-se da sua cadeira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Eúde estendeu a mão esquerda e tirou a espada que estava amarrada na sua coxa direita, e a cravou no corpo do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'O cabo da espada também entrou nele com a lâmina. A ponta da espada saiu pelas suas costas e a gordura se fechou sobre ela, pois Eúde não tirou a espada da barriga do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Então, Eúde saiu para o pórtico, fechou e trancou as portas do quarto superior atrás de si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Após sua saída, os servos do rei vieram e, vendo que as portas da sala superior estavam trancadas, pensaram: \"Certamente ele está fazendo as necessidades no quarto de verão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Mas eles foram ficando cada vez mais preocupados até sentirem que estavam negligenciando seus deveres, pois o rei ainda não havia aberto as portas do quarto superior. Então, tomaram a chave e abriram-nas, e ali estava o seu senhor, caído no chão, morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Enquanto seus servos estavam esperando, imaginando o que deveriam fazer, Eúde escapou, passando pelo lugar onde havia as imagens esculpidas de ídolos e, dali, fugiu para Seirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Quando ele chegou, soou a trombeta na região montanhosa de Efraim. Então, o povo de Israel desceu das colinas, e Eúde os liderava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Ele lhes disse: \"Segui-me, pois Yahweh derrotará os vossos inimigos, os moabitas\". Eles o seguiram, tomaram as passagens do Jordão dos moabitas e não permitiram que ninguém atravessasse o rio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Naquele tempo, mataram cerca de dez mil homens de Moabe. Todos fortes e hábeis, porém, nenhum deles escapou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Foi assim que, naquele dia, Moabe foi subjugado pela força de Israel. E a terra teve descanso por oitenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Depois de Eúde, o juiz seguinte foi Sangar, filho de Anate, que matou seiscentos filisteus com uma vara utilizada para conduzir bois. Ele também libertou Israel do perigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Após a morte de Eúde, o povo de Israel novamente fez o que era mau aos olhos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Yahweh os entregou nas mãos de Jabim, rei de Canaã, que reinava em Hazor. O comandante do seu exército era Sísera, que morava em Harosete-Hagoim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'O povo de Israel clamou a Yahweh por ajuda, pois Sísera tinha novecentas carruagens de guerra, feitas de ferro, e ele oprimiu fortemente o povo de Israel durante vinte anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Ora, Débora, uma profetisa, esposa de Lapidote, era quem julgava Israel naquela época.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Ela se assentava debaixo da palmeira de Débora, entre Ramá e Betel, na região montanhosa de Efraim, e o povo de Israel vinha até ela, para que julgasse suas disputas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Débora mandou chamar Baraque, filho de Abinoão, de Quedes em Naftali. Ela lhe disse: \"Yahweh, o Deus de Israel, te ordena: \'Vai ao monte Tabor e leva contigo dez mil homens de Naftali e Zebulom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Farei Sísera, o comandante do exército de Jabim, sair para te encontrar ao lado do rio Quisom, com suas carruagens e seu exército, e darei a ti a vitória sobre ele\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Baraque lhe disse: \"Se tu fores comigo, eu irei. Mas se não fores comigo, não irei”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Ela respondeu: \"Certamente irei contigo. Todavia, o caminho em que tu irás não te levará à honra, pois Yahweh derrotará Sísera pela mão de uma mulher\". Então, Débora levantou-se e foi com Baraque a Quedes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Baraque convocou os homens de Zebulom e Naftali para juntarem-se em Quedes. Dez mil homens o seguiram, e Débora foi com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Ora, Héber, o queneu, havia se separado dos queneus, que eram os descendentes de Hobabe, sogro de Moisés. Ele armou sua tenda junto ao carvalho em Zaananim, próximo de Quedes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Quando disseram a Sísera que Baraque, filho de Abinoão, havia subido ao monte Tabor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Sísera convocou todas as suas carruagens, novecentas carruagens de ferro, e todos os soldados que estavam com ele, de Harosete-Hagoim até o rio Quisom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Débora disse a Baraque: \"Vai! Pois este é o dia em que Yahweh deu a ti vitória sobre Sísera. Não é Yahweh que te conduz?\". Então, Baraque desceu do monte Tabor com os dez mil homens que o seguiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Yahweh confundiu Sísera, com todas as suas carruagens e todo o seu exército. E Sísera desceu da sua carruagem e correu a pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Baraque perseguiu as carruagens e o exército até Harosete-Hagoim, e todo o exército de Sísera foi morto ao fio da espada, e nenhum homem sobreviveu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Mas Sísera correu a pé para a tenda de Jael, a esposa de Héber, o queneu, pois havia paz entre Jabim, o rei de Hazor, e a casa de Héber, o queneu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Jael foi até Sísera e disse-lhe: \"Detém-te, meu mestre; detém-te a mim, e não tenhas medo\". Então, ele se deteve e entrou na tenda de Jael. E ela o cobriu com um cobertor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Ele lhe disse: \"Por favor, dá-me um pouco de água para beber, pois tenho sede\". Ela abriu uma bolsa de couro com leite, deu-lhe de beber, e o cobriu novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Ele lhe disse: \"Fica na entrada da tenda. Se alguém vier e te perguntar: \'Há alguém aí?\', responde: \'Não\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Então Jael, esposa de Héber, pegou uma estaca da tenda e um martelo. Foi, secretamente, até Sísera, que estava em sono profundo, e martelou a estaca na lateral da sua cabeça, até fazê-la fincar no chão. E ele morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Enquanto Baraque estava perseguindo Sísera, Jael foi ao seu encontro e disse-lhe: \"Vem, mostrarei a ti o homem que procuras\". Então, ele entrou na tenda com ela, e ali estava Sísera, morto, com a estaca da tenda na lateral da sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Naquele dia, Deus derrotou Jabim, rei de Canaã, diante do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'O poder do povo de Israel se fortaleceu, cada vez mais, contra Jabim, o rei de Canaã, até que eles o destruíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Naquele dia, Débora e Baraque, filho de Abinoão, cantaram esta música:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, '\"Quando os líderes assumiram a liderança de Israel, quando o povo alegremente voluntariou-se para a guerra, nós louvamos Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Ouvi, ó reis! Atentai, ó líderes! Eu cantarei a Yahweh! Cantarei louvores a Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Yahweh, quando saíste de Seir, quando Tu marchaste de Edom, a terra se abalou e os céus também se estremeceram; e as nuvens derramaram água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'As montanhas tremeram diante da face de Yahweh. Até o Monte Sinai tremeu diante da face de Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Nos dias de Sangar, filho de Anate, nos dias de Jael, as principais estradas foram abandonadas, e aqueles que passavam usavam somente caminhos tortuosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Havia poucos guerreiros em Israel, até que eu, Débora, tomei o comando. Uma mãe assumiu o comando em Israel!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Quando eles escolheram novos deuses, havia guerra nos portões da cidade. Não se viam escudos nem lanças entre os quarenta mil, em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Meu coração vai junto com os comandantes de Israel, junto com o povo que, alegremente, se voluntariou. Nós bendizemos a Yahweh por eles!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Pensai sobre isso, vós que cavalgais em jumentas brancas, sentados em tapetes como selas, e vós que andais ao longo do caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Ouvi as vozes dos que cantam entre os bebedouros. Ali eles falam novamente dos justos feitos de Yahweh, e das justas ações dos Seus guerreiros em Israel. Então, o povo de Yahweh desceu aos portões da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Desperta, desperta, Débora! Desperta, desperta, entoa um cântico! Levanta-te, Baraque, e captura os teus prisioneiros, filho de Abinoão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Então, os sobreviventes desceram aos nobres; o povo de Yahweh desceu a mim com os soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Vieram de Efraim, aqueles que tinham sua raiz em Amaleque; o povo de Benjamim vos seguiu. De Maquir desceram comandantes, e de Zebulom, aqueles que carregam uma vara de comando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Meus príncipes de Issacar estavam com Débora; e Issacar estava com Baraque, seguindo-o, apressadamente, ao vale. Junto aos clãs de Rúben, havia grande inquietação de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Por que sentastes entre as fogueiras, ouvindo os pastores tocando apitos para seus rebanhos? Os clãs de Rúben estavam em grande inquietação de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gileade ficou do outro lado do Jordão. E Dã, por que foi de um lado para o outro sobre os navios? Aser permaneceu na costa e morou perto de seus portos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zebulom foi a tribo que arriscou suas vidas até a morte, assim como Naftali, no campo de batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Reis vieram e lutaram, os reis cananeus lutaram em Taanaque, junto às águas do Megido. Todavia, eles não levaram nenhuma prata como saque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Dos céus, as estrelas lutaram; de seus caminhos, cruzando os céus, elas lutaram contra Sísera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'O rio Quisom os varreu; aquele antigo rio, o rio Quisom. Marcha, minha alma, sê forte!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Então, veio o som dos cascos dos cavalos galopando, o galope dos seus poderosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, '\'Amaldiçoai Meroz!\', diz o Anjo de Yahweh. \'Certamente, amaldiçoai seus habitantes! Porque não vieram para ajudar Yahweh, para ajudar Yahweh na batalha contra os poderosos soldados\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Jael é mais abençoada do que todas as outras mulheres. Jael, a esposa de Héber, o queneu, é mais abençoada do que todas as mulheres que vivem nas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'O homem pediu água, e ela lhe deu leite. Ela lhe trouxe manteiga em um prato adequado para príncipes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Ela colocou sua mão na estaca e sua mão direita no martelo de trabalhador. Com o martelo, ela golpeou Sísera, e esmagou a sua cabeça. Ela rachou seu crânio em pedaços quando o perfurou na lateral da cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Ele desabou entre os seus pés. Ele caiu e ficou ali. Entre os seus pés caiu estirado. O lugar onde caiu é onde foi violentamente morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Para fora da janela, ela olhou, a mãe de Sísera olhou através da grade, e gritou em tristeza: \'Por que o seu carro demora tanto para vir? Por que as batidas dos cascos dos cavalos que puxam a sua carruagem se atrasam?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Sua mais sábia princesa lhe respondeu, e ela repetia essas palavras a si mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '\'Por acaso não encontraram e dividiram a pilhagem? Uma virgem, duas virgens para cada homem; uma pilhagem de roupas coloridas para Sísera, uma pilhagem de roupas coloridas e de bordados, duas peças de roupas bordadas para os pescoços daqueles que pilharam?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Que pereçam todos os Teus inimigos, Yahweh! Mas que aqueles que Te amam sejam como o sol quando nasce em seu poder\". E a terra teve paz por quarenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'O povo de Israel fez o que era mau aos olhos de Yahweh, e Ele os entregou nas mãos dos midianitas por sete anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'O poder dos midianitas oprimiu Israel. Por causa deles, o povo de Israel fez abrigos para si nas covas das colinas, nas cavernas e nas fortalezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Acontecia que, toda vez que os israelitas faziam o seu plantio, os midianitas, os amalequitas e o povo do leste atacavam os israelitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Eles acampavam seus exércitos na terra e destruíam as plantações até Gaza. Não deixavam nenhuma comida em Israel, nem ovelhas, nem bois, nem jumentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Esses inimigos, com seus rebanhos e tendas, vinham como enxame de gafanhotos, e era impossível contar, tanto as pessoas como os seus camelos. Eles invadiam a terra para destruí-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Midiã enfraqueceu os israelitas tão severamente que o povo de Israel clamou a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Quando os israelitas clamaram a Yahweh por causa de Midiã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Yahweh enviou-lhes um profeta que disse: \"Isto é o que Yahweh, o Deus de Israel, diz: \'Eu vos trouxe do Egito; vos livrei da casa da escravidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Eu vos resgatei das mãos dos egípcios e das mãos de todos os que vos oprimiam. Eu os expulsei diante de vós, e vos dei a terra deles\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Eu vos disse: \'Eu sou Yahweh, vosso Deus. Eu vos ordenei não adorardes os deuses dos amorreus, em cuja terra vós habitais. Mas não obedecestes à Minha voz\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Então, o Anjo de Yahweh veio e se sentou debaixo de um carvalho em Ofra, que pertencia a Joás, o abiezrita. Gideão, filho de Joás, estava separando os grãos dos feixes de trigo, batendo-os no chão, no tanque de espremer uvas, para escondê-los dos midianitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'O Anjo de Yahweh apareceu a ele e disse-lhe: \"Yahweh está contigo, forte guerreiro!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Gideão disse-Lhe: \"Ó, meu Mestre, se Yahweh está conosco, por que tudo isto nos aconteceu? Onde estão todas as Suas grandes maravilhas que nossos pais nos contaram quando disseram: \'Não foi Yahweh que nos tirou do Egito?\'. Mas agora Yahweh nos abandonou e nos entregou nas mãos de Midiã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Yahweh olhou para ele e disse: \"Vai na força que tu já tens. Livra Israel das mãos dos midianitas. Não sou Eu que te enviei?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Gideão disse-Lhe: \"Por favor, Senhor, como poderei livrar Israel? Vê, minha família é a mais fraca em Manassés e eu sou o menos importante na casa do meu pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Yahweh disse-lhe: \"Eu estarei contigo, e tu derrotarás o exército inteiro dos midianitas, como se fossem um só homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Gideão disse-Lhe: \"Se encontrei favor aos Teus olhos, então, dá-me um sinal de que és Tu que estás falando comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Por favor, não vás embora até que eu volte trazendo a minha oferta e a coloque diante de Ti\". Yahweh disse: \"Esperarei até que voltes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Gideão foi e preparou um cabrito e, com um efa de farinha, fez pães sem fermento. Colocou a carne em um cesto e o caldo em uma panela. Trouxe-os para Ele, que estava debaixo do carvalho, e os apresentou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'O Anjo de Yahweh disse-lhe: \"Pega a carne e o pão sem fermento, coloca-os sobre esta rocha, e derrama o caldo sobre eles\". E Gideão assim o fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'O Anjo de Yahweh estendeu a ponta do cajado que estava em sua mão, tocando-a na carne e no pão sem fermento. Um fogo subiu da rocha e consumiu a carne e o pão sem fermento. Então, o Anjo de Yahweh foi embora e Gideão não O viu mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Gideão entendeu que Aquele era o Anjo de Yahweh, e disse: \"Ó, Senhor Yahweh! Vi o Anjo de Yahweh face a face!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Yahweh disse-lhe: \"Paz esteja contigo! Não tenhas medo, tu não morrerás\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Então, Gideão construiu ali um altar para Yahweh. Ele o chamou de \"Yahweh é Paz\". Até hoje, o altar está em Ofra, do clã dos abiezritas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Naquela noite, Yahweh disse-lhe: \"Pega o boi de teu pai e um segundo boi que tenha sete anos, derruba o altar de Baal que pertence a teu pai, e corta a Aserá que fica ao lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Constrói um altar a Yahweh, teu Deus, no topo deste lugar de refúgio, construindo-o da forma correta. Oferece o segundo boi como holocausto, usando a lenha do poste de Aserá que tu cortarás\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Então, Gideão levou dez dos seus servos e fez como Yahweh lhe ordenara. Mas, por estar com medo da casa de seu pai e dos homens da cidade, não fez isso durante o dia, ele o fez à noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'De manhã, quando os homens da cidade se levantaram, o altar de Baal estava derrubado, o poste de Aserá havia sido cortado, e o segundo boi havia sido oferecido sobre o altar que fora construído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Então, disseram uns aos outros: \"Quem fez isto?\". Quando conversaram com os outros buscando respostas, ouviram: \"Gideão, filho de Joás, fez esta coisa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Eles foram até Joás e lhe disseram: \"Traz para fora o teu filho para que ele seja morto, porque destruiu o altar de Baal e cortou o poste de Aserá que ficava ao lado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Joás falou a todos os que se opunham a ele: \"Defendereis vós a causa de Baal? Vós o salvareis? Quem defender a causa dele, que seja morto enquanto ainda é manhã. Se Baal é deus, que ele defenda a si mesmo quando alguém derrubar o seu altar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Então, naquele dia, chamaram Gideão de Jerubaal porque ele disse: \"Que Baal defenda a si mesmo contra ele\", porque Gideão derrubou o altar de Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Ora, todos os midianitas, os amalequitas e o povo do leste ajuntaram-se. Eles cruzaram o Jordão e acamparam no vale de Jezreel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Todavia, o Espírito de Yahweh veio sobre Gideão. Gideão tocou a trombeta, convocando o clã dos abiezritas para que o seguissem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Ele enviou mensageiros por toda a tribo de Manassés e eles foram convocados para segui-lo. Também enviou mensageiros para Aser, Zebulom e Naftali; e todos foram ao seu encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Gideão disse a Deus: \"Se Tu pretendes me usar para salvar Israel, como disseste,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'vê, eu estou colocando uma porção de lã na eira. Se pela manhã existir orvalho apenas na porção de lã e o chão estiver completamente seco, então saberei que Tu me usarás para salvar Israel, como disseste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Isto foi o que aconteceu: Gideão levantou-se cedo na manhã seguinte, apertou a porção de lã, e espremeu da lã o orvalho, o suficiente para encher uma tigela de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Então, Gideão disse a Deus: \"Não fiques irado contra mim, falarei mais uma vez. Por favor, permite-me mais um teste usando a porção de lã. Desta vez, faz ficar seca a porção de lã e que haja orvalho em todo o chão ao seu redor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Deus fez o que havia sido pedido naquela noite. A porção de lã estava seca e havia orvalho em todo o chão ao seu redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Então, Jerubaal (que é Gideão), levantou-se cedo, assim como todo o povo que estava com ele, e acamparam ao lado da fonte de Harode. O acampamento dos midianitas estava ao norte, no vale, próximo da colina de Moré.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Yahweh disse a Gideão: \"Há soldados demais para que Eu te dê a vitória sobre os midianitas; para que Israel não se glorie contra Mim, dizendo: \'Nosso próprio poder nos salvou\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Agora, portanto, proclama aos ouvidos do povo e dize: \'Qualquer um que esteja com medo, qualquer um que trema, volte e saia do monte Gileade\'\". Então, vinte e duas mil pessoas se foram, e dez mil permaneceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Yahweh disse a Gideão: \"Ainda há pessoas demais. Faze-os descer às águas, e ali Eu diminuirei o número para ti. Se Eu te disser: \'Este irá contigo\', ele irá contigo; mas se Eu disser: \'Este não irá contigo\', ele não irá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Então, Gideão fez o povo descer às águas, e Yahweh lhe disse: \"Separa todos aqueles que lamberem a água, como um cachorro lambe, daqueles que se ajoelharem para beber”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Trezentos homens lamberam, levando a mão à boca. O resto dos homens se ajoelhou para beber a água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Yahweh disse a Gideão: \"Com os trezentos homens que lamberam a água, Eu vos resgatarei e vos darei a vitória sobre os midianitas. Todos os outros voltem cada um para o seu lugar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Então, esses que foram escolhidos pegaram suas provisões e suas trombetas. Gideão despediu os demais homens de Israel, cada um para sua tenda, mas manteve os trezentos. Ora, o acampamento dos midianitas estava abaixo dele, no vale.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Na mesma noite, Yahweh lhe disse: \"Levanta-te! Ataca o acampamento, porque Eu te darei vitória sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Mas se estiveres com medo de descer, desce ao acampamento acompanhado de Purá, o teu servo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'e escuta o que dizem; e a tua coragem se fortalecerá para atacar o acampamento\". Então, Gideão desceu com o seu servo Purá até os postos dos vigias do acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Os midianitas, os amalequitas, e todo o povo do leste estavam situados ao longo do vale, tão numerosos como uma nuvem de gafanhotos. Seus camelos eram mais do que se podia contar; em número maior do que os grãos de areia da praia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Quando Gideão chegou ali, um homem estava contando seu sonho ao seu companheiro. O homem disse: \"Olha! Eu tive um sonho, e vi um pão de cevada rolando pelo acampamento dos midianitas. Veio sobre a tenda e bateu nela com tanta força que ela caiu e virou de cima para baixo, de maneira que ficou estendida na terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'O outro homem disse: \"Isto não é outra coisa senão a espada de Gideão, filho de Joás, o israelita. Deus lhe entregou a vitória sobre os midianitas e sobre todo o seu exército\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Quando Gideão ouviu a narração do sonho e sua interpretação, inclinou-se em adoração. Ele voltou ao acampamento de Israel e disse: \"Levantai-vos! Yahweh vos deu vitória sobre o exército dos midianitas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Ele dividiu os trezentos homens em três grupos, e deu a todos trombetas e jarras vazias, com tochas dentro de cada jarra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'E lhes disse: \"Olhai para mim e fazei o que eu fizer. Observai! Quando eu chegar ao limite do acampamento, fazei o que eu fizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Quando eu tocar a trombeta, tanto a minha como a de todos os que estiverem comigo, tocai as vossas trombetas também, em todos os lados do acampamento, e gritai: \'Por Yahweh e por Gideão!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Então, Gideão e os cem homens que estavam com ele chegaram ao limite do acampamento, no princípio da vigília da meia-noite. No momento em que os midianitas estavam trocando de guarda, eles tocaram as trombetas e quebraram os jarros que estavam em suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'As três companhias tocaram as trombetas e quebraram os jarros. Eles seguravam suas tochas na mão esquerda e as trombetas na mão direita para as tocarem. E bradaram: \"À espada de Yahweh e de Gideão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Todos ficaram em seus lugares ao redor do acampamento e todo o exército midianita correu. Eles gritavam e fugiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Quando tocaram as trezentas trombetas, Yahweh pôs a espada de cada homem midianita contra os seus companheiros e contra todo o seu próprio exército. O exército fugiu até Bete-Sita, em direção a Zererá, até os limites de Abel-Meolá, perto de Tabate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Os homens de Israel, de Naftali, de Aser e de todo o Manassés foram convocados e perseguiram os midianitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Gideão enviou mensageiros por toda a região montanhosa de Efraim, dizendo: \"Descei contra os midianitas e tomai o controle do rio Jordão, até Bete-Bara, para detê-los\". Então, todos os homens de Efraim se juntaram e tomaram controle das águas até Bete-Bara, e do rio Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Eles capturaram os dois príncipes de Midiã, Orebe e Zeebe. Mataram Orebe na rocha de Orebe, e mataram Zeebe no tanque de espremer uvas de Zeebe. Eles perseguiram os midianitas, e trouxeram as cabeças de Orebe e de Zeebe para Gideão, que estava do outro lado do Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Os homens de Efraim disseram a Gideão: \"O que é isto que tu fizeste conosco? Não nos chamaste quando foste lutar contra Midiã\". E tiveram uma dura discussão com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Ele lhes disse: \"O que eu fiz agora comparado ao que vós fizestes? Por acaso as sobras das colheitas de uvas de Efraim não são melhores do que toda a colheita de uvas de Abiezer?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Deus vos deu a vitória sobre os príncipes de Midiã, Orebe e Zeebe! O que eu realizei, comparado a vós?\". A ira deles contra Gideão se acalmou assim que ele disse isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Gideão foi até o Jordão e o atravessou, com os trezentos homens que estavam com ele. Todos estavam exaustos, mas ainda continuaram a perseguição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Ele disse aos homens de Sucote: \"Por favor, dai pães às pessoas que me seguem, pois estão exaustas, e estou perseguindo Zeba e Zalmuna, reis dos midianitas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Os líderes de Sucote disseram: \"Por acaso as mãos de Zeba e de Zalmuna já estão em teu poder? Por que devemos nós dar pão ao teu exército?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gideão disse: \"Quando Yahweh nos der a vitória sobre Zeba e Zalmuna, eu rasgarei a vossa carne com os espinhos e as sarças do deserto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Dali, ele foi a Peniel e falou da mesma maneira ao povo daquele lugar, mas os homens de Peniel lhe responderam como os homens de Sucote lhe haviam respondido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Ele falou também aos homens de Peniel e disse: \"Quando eu vier de volta em paz, derrubarei esta torre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Ora, Zeba e Zalmuna estavam em Carcor, com o seu exército de cerca de quinze mil homens. Esses eram os que haviam restado de todo o exército do povo do leste, porque haviam sido mortos cento e vinte mil homens que foram treinados para lutar com espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Gideão foi pelo caminho dos que habitavam em tendas, além de Nobá e Jogbeá. Ele derrotou o exército inimigo, pois não estavam esperando um ataque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Zeba e Zalmuna fugiram. Gideão continuou perseguindo-os e capturou os dois reis dos midianitas, Zeba e Zalmuna, colocando em pânico todo o exército deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Gideão, filho de Joás, voltou da batalha indo pelo caminho de Heres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Ele encontrou um jovem do povo de Sucote e lhe fez perguntas. O jovem lhe descreveu os líderes e anciãos de Sucote, setenta e sete homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Gideão foi aos homens de Sucote e disse: \"Vede aqui Zeba e Zalmuna, a respeito dos quais vós zombastes de mim, dizendo: ‘Por acaso tu já venceste Zeba e Zalmuna? Não sabemos que devemos dar pão ao teu exército\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Gideão capturou os anciãos da cidade e puniu os homens de Sucote com os espinhos e as sarças do deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Em seguida, derrubou a torre de Peniel e matou os homens daquela cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Então, Gideão disse a Zeba e Zalmuna, \"Como eram os homens que matastes em Tabor?\". Eles responderam: \"Eram como tu, cada um deles. Todos eles pareciam filhos de rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Gideão disse: \"Eles eram meus irmãos, filhos da minha mãe. Assim como Yahweh vive, se tivésseis poupado a vida deles, eu não vos mataria\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Ele disse a Jéter, seu primogênito, \"Levanta-te e mata-os!\". Mas o jovem não desembainhou a sua espada, pois estava com medo, porque ele ainda era um menino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Então, Zeba e Zalmuna disseram: \"Levanta-te e mata-nos! Pois como um homem é, assim é a sua força\". Gideão se levantou e matou Zeba e Zalmuna. Ele também tirou os ornamentos em forma de lua crescente que estavam no pescoço dos camelos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Então, os homens de Israel disseram a Gideão: \"Que tu reines sobre nós; tu, teu filho e teu neto, pois tu nos salvaste das mãos de Midiã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Gideão lhes disse: \"Não reinarei sobre vós, nem meu filho reinará sobre vós. Yahweh reinará sobre vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Disse-lhes ainda: \"Deixai-me fazer um pedido: que todos vós me deis os brincos do despojo\". Os midianitas tinham brincos de ouro, pois eram ismaelitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Eles responderam: \"Estamos felizes em dá-los a ti\". Eles estenderam uma capa, e todo homem colocou ali os brincos do seu despojo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'O peso dos brincos de ouro que ele pediu foi de mil e setecentos siclos de ouro. Este despojo foi adicionado aos ornamentos em forma de lua crescente, os pendentes, as roupas de púrpura que os reis de Midiã usavam e aos colares que estavam em volta do pescoço dos camelos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Gideão fez uma veste sacerdotal com os brincos de ouro e colocou-a na sua cidade, em Ofra, e todo Israel se prostituiu adorando aquela veste. Isso se tornou uma armadilha para Gideão e para os de sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Assim, os midianitas foram subjugados perante o povo de Israel, e não levantaram a cabeça novamente. Então, a terra teve paz por quarenta anos nos dias de Gideão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Jerubaal, filho de Joás, partiu e morou em sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Gideão foi pai de setenta filhos, pois tinha muitas mulheres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Sua concubina, que morava em Siquém, também lhe deu um filho, a quem Gideão deu o nome de Abimeleque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Gideão, filho de Joás, morreu numa boa velhice e foi enterrado na tumba de Joás, seu pai, em Ofra, do clã dos abiezritas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Aconteceu que, assim que Gideão morreu, o povo de Israel voltou a prostituir-se, adorando a baalins. Fizeram de Baal-Berite o seu deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Os israelitas não se lembraram de honrar a Yahweh, o seu Deus, que os havia resgatado das mãos de todos os seus inimigos, que estavam por todo lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Eles não guardaram suas promessas para com a família de Jerubaal, o outro nome de Gideão, em retribuição a todo o bem que ele havia feito em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Abimeleque, filho de Jerubaal, foi para os parentes de sua mãe em Siquém e para todo o clã da família de sua mãe e disse-lhes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, '\"Por favor, dizei isto para que todos os líderes em Siquém ouçam: \'Que é melhor para vós? Que todos os setenta filhos de Jerubaal dominem sobre vós, ou que somente um domine sobre vós?\' Lembrai-vos de que eu sou vosso osso e vossa carne\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Os parentes de sua mãe falaram por ele aos líderes de Siquém, e eles consentiram em seguir Abimeleque, porque disseram: \"Ele é nosso irmão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Deram-lhe setenta peças de prata tiradas da casa de Baal-Berite, e Abimeleque as usou para contratar homens inescrupulosos e imprudentes, e estes o seguiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Abimeleque foi para a casa de seu pai em Ofra e, sobre uma pedra, ele assassinou os seus setenta irmãos, os filhos de Jerubaal. Somente Jotão, o filho mais novo de Jerubaal, sobreviveu, porque se escondeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Todos os líderes de Siquém e de Bete-Milo ajuntaram-se e fizeram Abimeleque rei, junto ao carvalho perto da coluna que está em Siquém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Quando Jotão foi avisado sobre isso, ele foi e ficou de pé no cume do monte Gerizim. Ele gritou, dizendo-lhes: \"Ouvi-me vós, líderes de Siquém, a fim de que Deus vos ouça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Certa vez, as árvores foram ungir um rei para si. Elas disseram para a oliveira: \'Reina sobre nós\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Mas a oliveira lhes disse: \'Deveria eu deixar o meu azeite, o qual é usado para honrar deuses e homens, a fim de balançar de um lado para o outro sobre as outras árvores?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'As árvores disseram para a figueira: \'Vem e reina sobre nós\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Porém, a figueira lhes disse: \'Deveria eu deixar a minha doçura e o meu bom fruto, a fim de balançar de um lado para o outro sobre as outras árvores?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'As árvores disseram para a videira: \'Vem e reina sobre nós\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'A videira lhes disse: \'Deveria eu deixar o meu vinho novo, o qual alegra deuses e homens, a fim de balançar de um lado para o outro sobre as outras árvores?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Então, todas as árvores disseram ao espinheiro: \'Vem e reina sobre nós\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'O espinheiro disse para as árvores: \'Se verdadeiramente quereis me ungir rei sobre vós, vinde e encontrai segurança debaixo da minha sombra. Do contrário, que do espinheiro saia fogo e queime os cedros do Líbano\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Ora, será que agistes com verdade e honestidade, quando fizestes Abimeleque vosso rei? Será que agistes bem com Jerubaal e com a sua casa, como ele merecia?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Ora, meu pai lutou por vós, arriscando a própria vida, e vos resgatou das mãos dos midianitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Mas hoje vos levantastes contra a casa do meu pai e matastes os seus filhos, setenta pessoas, sobre uma pedra. Depois, fizestes Abimeleque, filho de sua serva, rei sobre os líderes de Siquém, por ser ele vosso parente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Se, de fato, agistes com honestidade e integridade com Jerubaal e a sua casa, então, alegrai-vos com Abimeleque, e que ele se alegre convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Mas, se não, que de Abimeleque saia fogo e queime os homens de Siquém e de Bete-Milo, e que dos homens de Siquém e de Bete-Milo saia fogo para queimar Abimeleque\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Jotão fugiu e escapou, indo para Beer. Ele morou ali porque era longe de Abimeleque, seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Abimeleque governou sobre Israel por três anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Deus enviou um espírito mau entre Abimeleque e os líderes de Siquém. Os líderes de Siquém traíram a confiança que Abimeleque tinha neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Deus fez isso para que a violência cometida contra os setenta filhos de Jerubaal fosse vingada, e Abimeleque, seu irmão, fosse responsabilizado pelo assassinato deles; e os homens de Siquém também fossem responsabilizados, porque o ajudaram a assassinar os seus irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Assim, os líderes de Siquém posicionaram homens para fazer emboscadas no alto das colinas. Eles roubavam todos os que passavam ao longo da estrada. E isso foi relatado a Abimeleque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Gaal, filho de Ebede, veio com seus parentes e estabeleceram-se em Siquém. Os líderes de Siquém confiaram nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Eles foram para o campo, colheram uvas dos vinhedos e as pisaram. Fizeram um festival na casa de seu deus, onde comeram e beberam, e amaldiçoaram Abimeleque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Gaal, filho de Ebede, disse: \"Quem é Abimeleque, e quem é Siquém, que devemos servi-lo? Ele não é o filho de Jerubaal? E Zebul não é o seu oficial? Servi aos homens de Hamor, pai de Siquém! Por que deveríamos servir a Abimeleque?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Eu gostaria que este povo estivesse sob meu comando! Então, eu removeria Abimeleque. Eu diria para Abimeleque: \'Convoca todo o teu exército\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Quando Zebul, o oficial da cidade, ouviu as palavras de Gaal, filho de Ebede, acendeu-lhe a ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Ele, secretamente, enviou mensageiros para Abimeleque, dizendo: \"Eis que Gaal, filho de Ebede, e seus parentes estão vindo para Siquém, e estão agitando a cidade contra ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Agora, levanta-te durante a noite, tu e teus soldados contigo, e preparai uma emboscada nos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Então, pela manhã, ao nascer do sol, levanta-te cedo e faze um ataque repentino à cidade. Quando ele e o povo que estiver com ele saírem contra ti, faze a eles o que tu puderes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Assim, Abimeleque levantou-se durante a noite, ele e todos os homens que estavam com ele, e fizeram uma emboscada contra Siquém, dividindo-se em quatro unidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Gaal, filho de Ebede, saiu e ficou de pé no portão de entrada da cidade. Abimeleque e os homens que estavam com ele saíram de seu esconderijo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Quando Gaal viu os homens, disse para Zebul: \"Vê, homens estão descendo do alto dos montes!\". Zebul disse-lhe: \"Estás vendo as sombras dos montes como se fossem homens\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Gaal falou novamente: \"Olha, homens estão descendo no meio da terra, e uma unidade está descendo do caminho do carvalho dos Adivinhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Então, Zebul lhe disse: \"Onde estão agora tuas palavras orgulhosas, que diziam: \'Quem é Abimeleque, para que o sirvamos?\'. Não são estes os homens que desprezaste? Sai agora e luta contra eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Gaal saiu liderando os homens de Siquém, e enfrentou Abimeleque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Abimeleque o perseguiu, e Gaal fugiu dele. Muitos caíram com feridas mortais ao longo do caminho até o portão de entrada da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Abimeleque ficou em Arumá; Zebul expulsou Gaal e seus parentes de Siquém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'No dia seguinte, o povo de Siquém saiu ao campo, e isso foi relatado a Abimeleque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Ele tomou seu povo e o dividiu em três unidades, e fizeram uma emboscada nos campos. Ele olhou e viu o povo descendo da cidade. Ele os atacou e os matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Abimeleque e a unidade que estava com ele atacaram e bloquearam o portão de entrada da cidade. As outras duas unidades atacaram todos os que estavam no campo e os mataram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Abimeleque lutou contra a cidade por todo aquele dia. Ele a tomou e matou o povo que estava ali. E derrubou seus muros e espalhou sal sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Quando todos os líderes da torre de Siquém ouviram isso, entraram na fortaleza da casa de El-Berite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Quando Abimeleque foi avisado de que os líderes haviam se reunido na torre de Siquém,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'subiu ao Monte Zalmon com todos os homens que estavam com ele. Então, pegou um machado e cortou os galhos, colocou-os em seus ombros e ordenou aos homens: \"O que me vistes fazer, fazei depressa também\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Cada um cortou um galho e seguiu Abimeleque. Eles os empilharam junto às paredes da torre e atearam fogo. Assim, todo o povo da torre de Siquém também morreu, cerca de mil homens e mulheres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Então, Abimeleque foi para Tebez, sitiou-a, e a conquistou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Mas havia uma torre forte na cidade. Todos os homens, mulheres e todos os líderes da cidade fugiram para lá. Trancaram-se e subiram até o terraço da torre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Abimeleque foi até a torre e a atacou. Mas, quando ele se aproximou da porta da torre para incendiá-la,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'uma mulher jogou sobre sua cabeça uma pedra de moinho que quebrou-lhe o crânio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Rapidamente ele chamou o jovem que era o seu escudeiro e disse-lhe: \"Desembainha tua espada e mata-me, assim, ninguém dirá sobre mim: Uma mulher o matou”. O jovem o transpassou, e ele morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Quando os homens de Israel viram que Abimeleque estava morto, foram para casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Assim, Deus vingou o mal que Abimeleque havia feito ao seu pai, ao assassinar os seus setenta irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Deus fez com que todo o mal dos homens de Siquém retornasse sobre suas próprias cabeças, e veio sobre eles a maldição de Jotão, filho de Jerubaal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Após Abimeleque, Tolá, filho de Puá, filho de Dodô, um homem de Issacar, que habitava em Samir, na região montanhosa de Efraim, levantou-se para libertar Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Julgou Israel durante vinte e três anos, morreu e foi sepultado em Samir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Ele foi sucedido por Jair, o gileadita, que julgou Israel durante vinte e dois anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Este tinha trinta filhos, que cavalgavam em trinta jumentos, e possuíam trinta cidades na terra de Gileade, as quais até hoje são chamadas cidades de Jair.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Jair morreu e foi enterrado em Camom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Mais uma vez, os israelitas fizeram o que era mau aos olhos de Yahweh, e adoraram os baalins, Astarote, os deuses da Síria, os deuses de Sidom, os deuses de Moabe, os deuses do povo de Amom e os deuses dos filisteus. Abandonaram Yahweh e não mais O adoraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'A ira de Yahweh se acendeu contra Israel, e Ele os entregou nas mãos dos filisteus e dos amonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Eles arrasaram e oprimiram o povo de Israel naquele ano. Durante dezoito anos, oprimiram todo o povo de Israel que estava além do Jordão, na terra dos amorreus, em Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Os amonitas atravessaram o Jordão para lutar contra Judá, contra Benjamim e contra a casa de Efraim, de maneira que Israel estava em grande desolação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Então, o povo de Israel clamou a Yahweh, dizendo: \"Pecamos contra Ti, pois abandonamos o nosso Deus e adoramos os baalins\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Yahweh disse ao povo de Israel: \"Não vos livrei dos egípcios, dos amorreus, dos amonitas, dos filisteus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'e também dos sidônios? Quando os amalequitas e os maonitas vos oprimiram, clamastes a Mim, e vos livrei do poder deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Porém, novamente Me abandonastes e adorastes outros deuses. Portanto, não vos livrarei mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Ide e clamai aos deuses que tendes adorado. Que eles vos salvem quando estiverdes em perigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Os israelitas disseram a Yahweh: \"Nós pecamos. Faze o que Te parecer melhor. Somente suplicamos que nos resgates hoje\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Eles se livraram dos deuses estrangeiros que possuíam e adoraram a Yahweh, e Ele não mais suportou a miséria de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Então, os amonitas reuniram-se e acamparam em Gileade. Os israelitas ajuntaram-se e acamparam em Mispá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Os líderes do povo de Gileade disseram uns aos outros: \"Quem será o homem que começará a lutar contra os amonitas? Ele se tornará o líder sobre todos os que vivem em Gileade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Ora, Jefté, o gileadita, era um guerreiro poderoso, mas ele era filho de uma prostituta. Seu pai era Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'A esposa de Gileade também lhe deu outros filhos. Quando estes cresceram, forçaram Jefté a deixar a casa e lhe disseram: \"Tu não herdarás nada da nossa família. Tu és filho de outra mulher\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Então, Jefté fugiu dos seus irmãos e morou na terra de Tobe. Homens sem lei se juntaram a Jefté e foram com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Alguns dias depois, o povo de Amom entrou em guerra contra Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Quando os amonitas atacaram Israel, os anciãos de Gileade foram buscar Jefté na terra de Tobe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Eles lhe pediram: \"Vem e sê nosso líder para lutarmos contra o povo de Amom\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Jefté disse aos líderes de Gileade: \"Vós me odiastes e me obrigastes a deixar a casa do meu pai. Por que vindes a mim agora que estais em apuros?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Responderam-lhe: \"É por isso que viemos a ti agora. Vem conosco e luta contra o povo de Amom, e tu serás o líder sobre todos os que habitam em Gileade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jefté disse-lhes: \"Se vós me levardes de volta para casa para lutar contra os amonitas, e se Yahweh nos der a vitória sobre eles, eu serei o vosso líder\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Os anciãos de Gileade disseram a Jefté: \"Seja Yahweh testemunha entre nós se não agirmos como prometemos!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Então, Jefté foi com os anciãos de Gileade, e o povo lhe fez líder e comandante sobre eles. Quando estava diante de Yahweh em Mispá, Jefté repetiu todas as promessas que havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Então, Jefté enviou mensageiros ao rei do povo de Amom, dizendo: \"Qual é o conflito entre nós? Por que tu vens à força para tomar a nossa terra?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'O rei dos amonitas respondeu aos mensageiros de Jefté: \"Porque, quando Israel veio do Egito, eles tomaram minha terra de Arnom até o Jaboque, além do Jordão. Agora devolve essas terras em paz”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Novamente, Jefté enviou mensageiros ao rei do povo de Amom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'que disseram: \"Isto é o que Jefté afirma: ‘Israel não tomou a terra de Moabe e a terra do povo de Amom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'mas quando eles vieram do Egito, Israel passou pelo deserto para o mar Vermelho e, dali, para Cades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Então, Israel enviou mensageiros ao rei de Edom, dizendo: \'Por favor, deixa-nos passar por tua terra\', mas o rei de Edom não lhes deu ouvidos. Eles também enviaram mensageiros ao rei de Moabe. Porém, ele também recusou. Assim, Israel ficou em Cades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Então, eles foram pelo deserto e contornaram a terra de Edom e a terra de Moabe, foram ao longo do lado leste da terra de Moabe e acamparam do outro lado de Arnom. Mas eles não entraram no território de Moabe, pois Arnom era a fronteira de Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Israel enviou mensageiros a Siom, rei dos amorreus, que governava em Hesbom. Israel disse-lhe: \'Por favor, deixa-nos passar pela tua terra para o lugar que é nosso\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Mas Siom não confiou em Israel para passar pelo seu território. Siom juntou todo o seu exército e o moveu para Jaza, e ali ele lutou contra Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Então, Yahweh, o Deus de Israel, entregou Siom e todo o seu povo nas mãos de Israel, que os derrotou. Assim, Israel tomou toda a terra dos amorreus que viviam naquele país.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Eles assumiram o controle de tudo no território dos amorreus, desde Arnom até o Jaboque, e desde o deserto até o Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Portanto, foi Yahweh, o Deus de Israel, que expulsou os amorreus da presença do Seu povo, os israelitas. Por que tu tomarias posse da terra deles agora?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Por acaso tu não tomarás posse da terra que Camos, teu deus, te der? Portanto, toda a terra que Yahweh, nosso Deus, nos deu, nós tomaremos posse dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Ora, és tu melhor que Balaque, filho de Zipor, rei de Moabe? Por acaso ele ousou discutir com os israelitas, ou declarou guerra contra eles?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Enquanto Israel viveu por trezentos anos em Hesbom e nas suas vilas, e em Aroer e nas suas vilas, e em todas as cidades que estão ao longo das margens de Armom, por que, então, tu não as tomaste de volta naquele tempo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Eu não te fiz nada de errado, mas tu estás cometendo um erro contra mim ao me atacar. Yahweh, o Juiz, decidirá hoje entre o povo de Israel e o povo de Amom’”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Mas o rei dos amonitas rejeitou a advertência que Jefté enviou a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Então, o Espírito de Yahweh veio sobre Jefté e ele passou por Gileade e Manassés, e passou por Mispá de Gileade, e de Mispá de Gileade ele passou pelos amonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Jefté fez um voto a Yahweh e disse: “Se Tu me deres a vitória sobre os amonitas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'então, qualquer um que sair da porta da minha casa para ir ao meu encontro, quando eu voltar em paz dos amonitas, pertencerá a Yahweh, e eu o oferecerei como holocausto”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Jefté passou pelos amonitas para lutar contra eles, e Yahweh lhe deu a vitória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Ele os atacou e causou uma grande matança, desde Aroer até Minite, vinte cidades, e até Abel-Queramim. Assim, os amonitas foram colocados sob o controle do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Jefté foi à sua casa em Mispá, e de lá sua filha saiu para encontrá-lo com tambores e danças. Ela era sua única filha. Além dela, ele não tinha nenhum outro filho ou filha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Assim que ele a viu, rasgou suas vestes e disse: \"Oh! Minha filha! Tu me entristeceste muito, e te tornaste aquela que me causa dor! Pois eu fiz um juramento a Yahweh, e não posso voltar atrás na minha promessa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Ela lhe disse: \"Meu pai, tu fizeste um voto a Yahweh; faze comigo o que prometeste, porque Yahweh te vingou dos teus inimigos, os amonitas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Ela disse ainda ao seu pai: \"Seja-me concedida esta promessa. Deixa-me sozinha por dois meses, para que eu vá e desça pelos montes, lamentando pela minha virgindade, eu e as minhas companheiras”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Ele disse: \"Vai\". Ele a mandou embora por dois meses. Ela o deixou, ela com as suas companheiras, e lamentaram a sua virgindade nos montes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'No final dos dois meses, ela voltou ao seu pai, que fez com ela de acordo com a promessa do voto que ele fizera. Ora, ela nunca havia se deitado com homem algum, e isto se tornou um costume em Israel:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'que as filhas de Israel, todo ano, por quatro dias, recontariam a história da filha de Jefté, o gileadita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Uma convocação veio para os homens de Efraim. Eles passaram por Zafom e disseram para Jefté: \"Por que tu guerreaste contra o povo de Amom e não nos chamaste para ir contigo? Queimaremos a tua casa sobre ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Jefté lhes disse: \"Eu e o meu povo estávamos em grande conflito com os povo de Amom. Quando eu vos chamei, não me livrastes deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Quando eu vi que vós não me livraríeis, confiei minha vida em minha própria força e combati o povo de Amom, e Yahweh me deu vitória. Por que viestes lutar contra mim hoje?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Jefté juntou todos os homens de Gileade e lutou contra Efraim. Os homens de Gileade atacaram os homens de Efraim porque eles disseram: \"Vós, gileaditas, sois fugitivos em Efraim e Manassés\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Os gileaditas tomaram as passagens do Jordão que levavam a Efraim. Quando qualquer um dos sobreviventes de Efraim dizia: \"Deixai-me atravessar o rio\", os homens de Gileade lhe diziam: \"Tu és um efraimita?\". Se ele respondesse: \"Não\",');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'então, eles diriam para ele: \"Dize: chibolete\". E se ele dissesse: \"sibolete\", porque não conseguia pronunciar a palavra corretamente, os gileaditas o prenderiam e o matariam nas passagens do Jordão. Quarenta e dois efraimitas foram mortos naquele tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Jefté serviu como juiz sobre Israel por seis anos. Então, Jefté, o gileadita, morreu, e foi enterrado em uma das cidades de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Depois dele, Ibsã, de Belém, serviu como juiz sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Ele tinha trinta filhos e trinta filhas. Estas foram dadas em casamento a outros homens de fora; e também de fora trouxe trinta mulheres para os seus filhos. Ele julgou Israel por sete anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Ibsã morreu e foi enterrado em Belém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Depois dele, Elom, o zebulonita, serviu como juiz sobre Israel. Ele julgou Israel por dez anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Elom, o zebulonita, morreu e foi enterrado em Aijalom, na terra de Zebulom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Depois dele, Abdom, filho de Hilel, o piratonita, serviu como juiz sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Ele teve quarenta filhos e trinta netos, que montavam setenta jumentos. Ele julgou Israel por oito anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Abdom, filho de Hilel, o piratonita, morreu, e foi enterrado em Piratom, na terra de Efraim, na região montanhosa dos amalequitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'O povo de Israel, mais uma vez, fez o que era mau aos olhos de Yahweh, e Ele os entregou nas mãos dos filisteus por quarenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Havia um homem de Zorá, do clã dos danitas, cujo nome era Manoá. Sua esposa, como era estéril, nunca havia dado à luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'O Anjo de Yahweh apareceu à mulher e disse-lhe: “Até agora, tu não tens conseguido engravidar e não deste à luz. Porém, tu ficarás grávida e darás à luz um filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Agora, sê cuidadosa para não beber vinho ou bebida forte, nem comer qualquer coisa impura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Vê, tu ficarás grávida e darás à luz um filho. Nenhuma navalha passará pela cabeça dele, porque o menino será nazireu para Deus, desde o ventre. Ele começará a libertar Israel das mãos dos filisteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Então, a mulher veio e disse ao seu marido: \"Um homem de Deus veio até mim, e sua aparência era como de um anjo de Deus, e ele me causou muito medo. Eu não perguntei de onde veio e ele não me disse o seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Ele me disse: \'Vê! Tu ficarás grávida e darás à luz um filho. Então, não bebas vinho nem bebida forte, e não comas nenhuma comida que a Lei declara como impura, porque a criança será um nazireu de Deus, desde o tempo em que estiver no teu ventre até o dia da sua morte\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Então, Manoá orou a Yahweh e disse: \"Ó, Senhor, por favor, faze com que o homem de Deus que Tu enviaste venha outra vez a nós e que ele nos ensine o que devemos fazer à criança que vai nascer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Deus ouviu a oração de Manoá, e o Anjo de Deus veio novamente até a mulher quando ela estava sentada no campo. Mas Manoá, seu marido, não estava com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'A mulher correu rapidamente e disse ao seu marido: \"Olha! O homem apareceu a mim, aquele que veio a mim outro dia!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Manoá se levantou e seguiu sua esposa. Quando ele chegou até o homem, disse: \"És tu o homem que falou com a minha esposa?”. O homem disse: \"Sou eu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Então, Manoá disse: \"Que as tuas palavras se tornem verdade; mas quais serão a regras para a criança, e qual será seu trabalho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'O Anjo de Yahweh disse a Manoá: \"Ela precisa fazer cuidadosamente tudo o que lhe disse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Ela não poderá comer nada que venha da vinha e não poderá beber vinho ou bebida forte; não poderá comer nenhuma comida que a lei declara como impura. Ela deve obedecer tudo o que lhe ordenei para fazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Manoá disse ao Anjo de Yahweh: \"Por favor, fica mais um pouco, para nos dar tempo para te preparar um cabrito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'O Anjo de Yahweh disse a Manoá: \"Mesmo que Eu fique, não comerei da vossa comida, mas se tu preparares um holocausto, consagra-o para Yahweh\". Manoá não sabia que era o Anjo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Manoá disse ao Anjo de Yahweh: \"Qual é o teu nome, para que te honremos quando a tua palavra se cumprir?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'O Anjo de Yahweh lhe disse: \"Por que perguntas o Meu nome? Ele é maravilhoso!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Então, Manoá pegou o cabrito com a oferta de cereal e ofereceu-os em cima da pedra a Yahweh. Ele fez algo maravilhoso enquanto Manoá e sua esposa estavam observando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Quando a chama subiu do altar em direção ao céu, o Anjo de Yahweh subiu na chama do altar. Manoá e sua esposa viram isso e se prostraram com seus rostos em terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'O Anjo de Yahweh não apareceu mais a Manoá nem à sua esposa. Então, Manoá soube que ele era o Anjo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Manoá disse à sua esposa: \"Certamente morreremos, porque vimos a Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Mas sua esposa lhe disse: \"Se Yahweh quisesse nos matar, Ele não teria recebido o holocausto e a oferta de cereais que nós Lhe demos. Ele não teria nos mostrado todas essas coisas, nem nos teria feito ouvir tais coisas neste tempo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Algum tempo depois, a mulher deu à luz um menino, e chamou-lhe Sansão. O menino cresceu, e Yahweh o abençoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'O Espírito de Yahweh começou a movê-lo em Maané-Dã, entre Zorá e Estaol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Sansão desceu a Timnate e ali viu uma mulher, uma das filhas dos filisteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Quando retornou, disse a seu pai e à sua mãe: \"Vi uma mulher em Timnate, uma das filhas dos filisteus. Agora, tomai-a para ser minha esposa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Seu pai e sua mãe lhe disseram: \"Não existe mulher entre as filhas de nossos parentes ou entre todo o nosso povo? Tomarás esposa dentre os incircuncisos filisteus?\". Sansão disse a seu pai: \"Traze-a para mim porque, quando eu a vejo, é ela quem me agrada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Mas seu pai e sua mãe não sabiam que isso vinha de Yahweh, pois Ele desejava criar conflito com os filisteus porque, naquele tempo, os filisteus dominavam Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Então, Sansão desceu a Timnate com seus pais, e chegaram às vinhas de Timnate. Ali, um leão novo veio até ele, rugindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'O Espírito de Yahweh veio repentinamente sobre Sansão, e ele, sem nada nas mãos, rasgou o leão ao meio, tão facilmente como se rasgasse um cabrito. Porém, não disse nada do que fizera ao seu pai ou à sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Depois disso, ele foi e falou com a mulher, e ela foi agradável à vista de Sansão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Alguns dias depois, quando voltou para casar-se com a mulher, desviou-se do caminho para ver a carcaça do leão; e eis que dentro dela havia um enxame de abelhas e mel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Ele raspou o mel com as mãos e foi comendo pelo caminho. Quando aproximou-se de seu pai e de sua mãe, deu-lhes um pouco do mel e eles comeram, mas não lhes disse que havia tirado o mel do que havia sobrado do corpo do leão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'O pai de Sansão desceu para onde estava a mulher, e Sansão deu uma festa ali, pois esse era o costume dos noivos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Assim que os parentes da mulher o avistaram, trouxeram trinta dos seus amigos para estarem com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Sansão disse-lhes: \"Vou contar-lhes um enigma. Se um de vós descobrir e me contar a resposta durante os sete dias da festa, distribuirei trinta vestes de linho e trinta conjuntos de roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Mas, se não me responderdes, então vós me dareis trinta vestes de linho e trinta conjuntos de roupas\". Responderam-lhe: \"Dize-nos o enigma para o ouvirmos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Ele lhes disse: \"Do que come saiu comida, do forte saiu doçura\". Mas seus convidados não descobriram a resposta em três dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'No quarto dia, disseram à esposa de Sansão: \"Engana teu marido para que nos forneça a resposta do enigma, ou queimaremos a ti e a casa do teu pai. Por acaso nos convidastes aqui para nos empobrecer?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'A mulher de Sansão começou a chorar na frente dele, dizendo: \"Tu me odeias! Tu não me amas! Falaste um enigma a alguns do meu povo, mas não me revelaste a resposta\". Sansão disse-lhe: “Olha aqui, se não revelei nem ao meu pai ou à minha mãe, por que revelaria a ti?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Ela chorou durante os sete dias da sua festa. No sétimo dia, Sansão deu-lhe a resposta porque ela o pressionou muito. E ela contou aos parentes do seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Então, no sétimo dia, antes do sol se pôr, os homens da cidade responderam a Sansão: \"O que é mais doce do que o mel? O que é mais forte do que um leão?\". Sansão lhes disse: \"Se não tivésseis arado com a minha novilha, não teríeis descoberto a resposta do meu enigma\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Então, o Espírito de Yahweh veio com poder sobre Sansão. Este desceu a Asquelom e matou trinta homens daquele lugar. Ele tomou despojo de roupas deles, e as deu aos que haviam respondido o enigma. Ardendo em furor, ele subiu para a casa do seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'A mulher de Sansão foi entregue como esposa ao melhor amigo dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Depois de alguns dias, durante o tempo da colheita de trigo, Sansão pegou um cabrito e foi visitar sua esposa. Ele disse para si mesmo: \"Eu irei ao quarto da minha esposa\". Mas o pai dela não lhe permitiu entrar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'O pai dela disse: \"Eu realmente pensei que tu a odiavas, então, entreguei-a ao teu amigo. Sua irmã mais nova é mais bonita do que ela, não achas? Toma-a em seu lugar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Sansão disse-lhe: \"Desta vez, serei inocente se fizer algum mal aos filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Sansão foi e pegou trezentas raposas e as amarrou juntas pelas caudas, em pares. Então, pegou tochas e prendeu-as no meio de cada par de caudas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Quando ele pôs fogo nas tochas, soltou as raposas dentro da plantação dos filisteus e elas colocaram fogo tanto nos feixes de grãos quanto nos cereais que havia no campo. As vinhas e os olivais também foram queimados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Os filisteus perguntaram: \"Quem fez isso?\". Disseram-lhes: \"Sansão, o genro do timnita, fez isso porque ele tomou a esposa de Sansão e a deu ao seu amigo\". Então, os filisteus foram e a queimaram com o seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Sansão disse-lhes: \"Se é isso o que vós fazeis, eu terei a minha vingança contra vós e depois de feita, pararei”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Ele os atacou e cortou-lhes em pedaços, quadril e coxa, com uma grande matança. Depois, desceu e foi habitar em uma caverna na rocha de Etã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Então, os filisteus subiram e prepararam-se para a batalha em Judá e posicionaram o seu exército em Leí.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Os homens de Judá disseram: \"Por que viestes nos atacar?\". Eles responderam: \"Estamos atacando para capturar Sansão e fazermos a ele o que ele fez conosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Então, três mil homens de Judá desceram à caverna na rocha de Etã e disseram a Sansão: \"Tu não sabes que os filisteus dominam sobre nós? O que é isso que fizeste conosco?\". Sansão respondeu-lhes: \"Eles fizeram comigo e então eu fiz com eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Disseram a Sansão: \"Viemos aqui para te amarrar e te entregar nas mãos dos filisteus\". Sansão disse-lhes: \"Jurai-me que vós não me matareis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Responderam-lhe: \"Só iremos amarrar-te com cordas e te entregar a eles. Prometemos que não te mataremos\". Então, amarraram-no com duas cordas novas e o tiraram da rocha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Quando Sansão chegou a Leí, os filisteus vieram gritando assim que o encontraram. Mas o Espírito de Yahweh veio sobre ele de tal maneira que as cordas em seus braços tornaram-se como linho queimado e caíram de suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Sansão encontrou uma queixada de jumento ainda fresca e, apanhando-a, matou com ela mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'E disse: \"Com a queixada de um jumento, montões sobre montões; com a queixada de um jumento matei mil homens\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Quando Sansão terminou de falar, lançou fora a queixada e chamou o lugar de Ramate-Leí.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Ele estava com muita sede e clamou a Yahweh, dizendo: \"Tu deste esta grande vitória ao teu servo. Todavia, agora eu morrerei de sede e cairei nas mãos desses incircuncisos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'E Deus abriu uma fonte em um lugar que fica em Leí, e saiu água. Quando ele bebeu, sua força retornou e ele reviveu. Então, ele chamou aquele lugar de En-Hacoré e está em Leí até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Sansão julgou Israel nos dias dos filisteus durante vinte anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Sansão foi a Gaza e viu lá uma prostituta; então, deitou-se com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'E falaram aos gazitas: \"Sansão está aqui\". Os gazitas cercaram o lugar em segredo, e o esperaram durante toda a noite junto ao portão da cidade. Eles se mantiveram quietos durante toda a noite. Disseram: \"Esperemos até o dia amanhecer, então o mataremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Mas Sansão ficou na cama só até a meia-noite. Então, ele se levantou e pegou os portões da cidade e suas duas colunas. Ele os arrancou do chão, com tranca e tudo, colocou-os sobre os ombros, e carregou-os até o topo da colina defronte de Hebrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Algum tempo depois, Sansão apaixonou-se por uma mulher que habitava no vale de Soreque. Seu nome era Dalila.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Os chefes dos filisteus vieram até ela e lhe disseram: \"Engana Sansão para ver de onde vem a sua grande força, e como poderemos prevalecer sobre ele, como amarrá-lo sem que se solte, a fim de humilhá-lo. Faze isso, e cada um de nós te daremos mil e cem peças de prata\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Então, Dalila disse a Sansão: \"Por favor, conta-me por que tu és tão forte, e como alguém poderia amarrar-te para que fosses dominado?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Sansão disse a ela: \"Se me amarrarem com sete cordas frescas de arco, que não forem secas, então me tornarei fraco, como qualquer outro homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Então, os governantes dos filisteus trouxeram a Dalila sete cordas frescas de arco, que ainda não se haviam secado, com as quais ela amarrou Sansão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Dalila mantinha homens escondidos no interior do seu quarto. Ela disse a Sansão: \"Os filisteus estão vindo sobre ti, Sansão!\". Mas ele arrebentou as cordas frescas de arco como um fio de estopa quando toca o fogo. Assim, o segredo de sua força não foi descoberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Dalila disse a Sansão: \"Tu me enganaste e me contaste mentiras. Por favor, conta-me como tu podes ser dominado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Ele lhe disse: \"Se me amarrarem com cordas novas, que nunca foram usadas para o trabalho, eu me tornarei fraco como qualquer outro homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Então, Dalila pegou cordas novas e o amarrou com elas. Depois disse: \"Os filisteus estão vindo sobre ti, Sansão!\". Homens estavam à espera no interior do quarto. Mas Sansão rompeu as cordas dos seus braços como se fossem um pedaço de linha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Dalila disse a Sansão: \"Até agora tu me enganaste e me contaste mentiras. Conta-me como podes ser dominado\". Sansão lhe disse: \"Se teceres as sete tranças do meu cabelo com um tecido em um tear, e pregar-lhe ao tear, serei como qualquer outro homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Enquanto ele dormia, Dalila amarrou as setes tranças do seu cabelo com um tecido em um tear, e pregou-as ao tear. Depois, ela lhe disse: \"Os filisteus estão vindo sobre ti, Sansão!\". Ele acordou do seu sono e arrancou o tecido e o prego do tear.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Disse-lhe ela: \"Como podes dizer-me, \'Eu te amo\', quando não compartilhas os teus segredos comigo? Tu zombaste de mim estas três vezes, e não me disseste como tens tão grande força\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Todos os dias, ela o pressionava com suas palavras; e o pressionou tanto, que ele desejava estar morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Então, Sansão contou tudo a ela, dizendo: \"Nunca foi passada navalha em minha cabeça, pois sou nazireu de Deus desde o útero de minha mãe. Se a minha cabeça for raspada, então minha força me deixará e eu me tornarei fraco como qualquer outro homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Quando Dalila viu que ele tinha contado toda a verdade, ela chamou os governantes dos filisteus, dizendo: \"Vinde outra vez, pois ele me disse tudo\". E eles foram até ela, trazendo a prata em suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Ela havia feito Sansão adormecer em seu colo. Assim, chamou um homem para raspar suas sete tranças da cabeça. Ela começou a subjugá-lo, pois a força dele o havia deixado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Dalila disse: \"Os filisteus estão vindo sobre ti, Sansão!\". Ele acordou do seu sono, dizendo: \"Sairei como as outras vezes, e ficarei livre\". Mas ele não sabia que Yahweh o havia deixado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Os filisteus capturaram-no e arrancaram-lhe os olhos. Levaram-no para Gaza, amarraram-no com grilhões de bronze e o fizeram girar a pedra de moinho da prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Mas o cabelo em sua cabeça começou a crescer novamente, depois que havia sido raspado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Então, os governantes filisteus reuniram-se para oferecer um grande sacrifício a Dagom, seu deus, para comemorar. Eles diziam: \"Nosso deus derrotou Sansão, nosso inimigo, e o deu em nossas mãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Quando o povo o viu, louvaram o seu deus, e disseram: \"Nosso deus derrotou o nosso inimigo e o entregou a nós; o destruidor do nosso país, que matou muitos dos nossos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Quando eles estavam celebrando, disseram: \"Chamai Sansão, para que ele nos faça rir\". Chamaram Sansão para fora da prisão, para fazê-los rir. Fizeram-no ficar de pé entre os pilares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Sansão disse ao jovem que segurava sua mão: \"Deixa-me tocar os pilares nos quais o prédio se sustenta, para que eu me apoie neles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Ora, a casa estava cheia de homens e mulheres, e todos os governantes dos filisteus estavam lá. No terraço, havia cerca de três mil homens e mulheres olhando, enquanto Sansão os estava entretendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Sansão clamou a Yahweh, dizendo: \"Senhor Yahweh, lembra-Te de mim! Por favor, fortalece-me somente esta única vez, Deus, para que eu me vingue, em um só golpe, dos filisteus, por arrancarem os meus dois olhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Sansão agarrou-se aos dois pilares do meio, nos quais o prédio se sustentava, e ele os empurrou, um pilar com sua mão direita, e o outro com a esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Sansão disse: \"Que eu morra com os filisteus!\". Ele empurrou com sua força, e o prédio caiu sobre os governantes e sobre todas as pessoas que lá estavam. Assim, as pessoas que ele matou quando morreu foram em maior número do que as que ele matou durante a sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Então, seus irmãos e toda a casa de seu pai desceram, tomaram-no e o levaram de volta. Eles o enterraram entre Zorá e Estaol, no túmulo de Manoá, seu pai. Sansão julgou Israel por vinte anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Havia um homem na região montanhosa de Efraim, e seu nome era Mica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Ele disse à sua mãe: \"As mil e cem peças de prata que foram tiradas de ti, pelas quais falaste uma maldição (eu a escutei), olha aqui: eu tenho a prata comigo. Fui eu que a roubei\". Sua mãe lhe disse: \"Que Yahweh te abençoe, meu filho!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Ele devolveu as mil e cem peças de prata à sua mãe, e ela disse: \"Dedico esta prata à Yahweh, para que meu filho faça imagens de escultura e de metal de fundição. Assim, agora eu a devolvo a ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Quando ele devolveu o dinheiro à sua mãe, ela tomou duzentas peças de prata e as deu a um ourives. Ele fez delas imagens de escultura e de metal de fundição, que foram colocadas na casa de Mica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Esse homem, Mica, tinha uma casa de ídolos. Ele fez um colete sacerdotal e alguns deuses da casa, e constituiu um de seus filhos como sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'Não havia rei em Israel naqueles dias, e todos faziam o que lhes parecia certo aos seus próprios olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Havia um jovem de Belém de Judá, da família de Judá, que era levita. Ele estava ali para cumprir seus deveres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Esse homem deixou Belém de Judá para ir encontrar um lugar para morar. Enquanto viajava, ele veio à casa de Mica, na região montanhosa de Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Mica disse-lhe: \"De onde vens?\". O homem lhe respondeu: \"Eu sou um levita de Belém de Judá, e estou viajando para encontrar um lugar em que possa morar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Mica disse-lhe: \"Mora comigo e sê para mim um pai e sacerdote. Eu te darei dez peças de prata por ano, um conjunto de roupas e tua comida\". Então, o levita aceitou ficar em sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'O levita estava contente em morar com aquele homem, e o jovem tornou-se para Mica como um de seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Mica separou o levita para os deveres sagrados, e o jovem tornou-se o seu sacerdote, e ficou na casa de Mica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Então, Mica disse: \"Agora eu sei que Yahweh me fará bem, porque este levita tornou-se o meu sacerdote\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'Não havia rei em Israel naqueles dias. A descendência da tribo de Dã buscava um território para habitar, pois ainda não havia recebido nenhuma herança entre as tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'O povo de Dã enviou cinco homens dentre todos da sua tribo, homens que eram guerreiros experientes de Zorá e de Estaol, para espionar a terra a pé, e observá-la. Disseram-lhes: \"Ide e observai a terra\". Eles foram à região montanhosa de Efraim, para a casa de Mica, e passaram a noite ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Quando estavam perto da casa de Mica, reconheceram a fala do jovem levita. Então, pararam-no e perguntaram-lhe: \"Quem te trouxe aqui? Que fazes neste lugar? Por que estás aqui?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Ele lhes respondeu: \"Isto é o que Mica fez a mim: ele me contratou para ser o seu sacerdote\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Eles pediram-lhe: \"Por favor, busca conselho de Deus, para que saibamos se a nossa jornada será bem-sucedida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'O sacerdote lhes disse: \"Ide em paz. Yahweh vos conduzirá no caminho em que deveis ir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Então, os cinco homens saíram e foram para Laís, e avistaram os habitantes que viviam em segurança, da mesma maneira que os sidônios viviam: seguros e sem perturbações. Não existia ninguém que os houvesse conquistado, nem que os incomodasse por coisa alguma naquela terra. Viviam distantes dos sidônios e não tinham negócios com ninguém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Os homens voltaram para a sua tribo em Zorá e Estaol. Seus parentes perguntaram-lhes: \"Qual é o vosso relato?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Eles lhes disseram: \"Vinde! Vamos atacá-los! Vimos a terra e é muito boa. Não estais fazendo nada? Não demoreis para atacar e conquistar a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Quando fordes, chegareis até um povo que pensa estar seguro. Aquela terra é extensa! Deus a entregou a vós. Um lugar onde não falta nada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Seiscentos homens da tribo de Dã, armados com armas de guerra, partiram de Zorá e Estaol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Subiram e acamparam em Quiriate-Jearim, em Judá. Por isso, as pessoas chamam aquele lugar de Maané-Dã até hoje. Isso fica a oeste de Quiriate-Jearim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Dali, eles partiram para a região montanhosa de Efraim e foram para a casa de Mica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Então, os cinco homens que haviam espionado a região de Laís disseram aos seus parentes: \"Por acaso vós sabeis que nestas casas há um colete sacerdotal, alguns deuses da casa, uma imagem de escultura, e uma imagem de metal de fundição? Tomai decisão agora do que ireis fazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Então, eles partiram dali e foram à casa do jovem levita, à casa de Mica, e o cumprimentaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Ora, os seiscentos danitas, armados com armas de guerra, ficaram de pé à entrada da porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Os cincos homens que foram espionar as terras, chegaram ali e tomaram a imagem de escultura, o colete sacerdotal, os deuses da casa, e a imagem de metal de fundição, enquanto o sacerdote ficou de pé à entrada da porta, com os seiscentos homens armados com armas de guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Quando eles entraram na casa de Mica e tomaram a imagem de escultura, o colete sacerdotal, os deuses da casa, e a imagem de metal de fundição, o sacerdote perguntou-lhes: \"O que estais fazendo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Eles disseram-lhe: \"Silêncio! Coloca tua mão sobre a boca e vem conosco, e sê para nós como pai e sacerdote. É melhor que sejas sacerdote da casa de um só homem ou o sacerdote de uma tribo e de um clã em Israel?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'O coração do sacerdote alegrou-se. Ele tomou o colete sacerdotal, os deuses da casa, e a imagem de escultura, e foi junto com o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Então, eles se viraram e partiram, colocando as crianças pequenas à frente, assim como o gado e suas posses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Quando estavam a uma boa distância da casa de Mica, os homens que estavam nas casas próximas de Mica foram convocados e alcançaram os danitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Eles gritaram aos danitas e estes, voltando-se, perguntaram a Mica: \"Por que convocaste teus homens?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Ele disse: \"Roubastes os deuses que eu fiz, tomastes o meu sacerdote, e partistes. Que mais me restou? Como podeis me perguntar: \'O que te incomoda?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'O povo de Dã lhe disse: \"Não nos faças ouvir coisa alguma do que tu dizes, se não, alguns homens enfurecidos te atacarão, e tu e a tua família morrereis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Então, o povo de Dã seguiu o seu caminho. Quando Mica viu que eles eram fortes demais para ele, virou-se e voltou para a sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'O povo de Dã tomou o que Mica havia feito, assim como o seu sacerdote, e foram para Laís, para um povo que estava seguro, sem perturbações, e os mataram ao fio de espada e queimaram a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Não havia ninguém para resgatá-los, pois era um longo caminho até Sidom, e não tinham negócios com ninguém. Isso foi no vale perto de Bete-Reobe. Os danitas reconstruíram a cidade e se estabeleceram ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Chamaram a cidade de Dã, em homenagem a Dã, seu ancestral, aquele que fora um dos filhos de Israel. Anteriormente, o nome da cidade era Laís.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'O povo de Dã levantou para si a imagem de escultura; e Jônatas, filho de Gérson, filho de Moisés, ele e seus filhos, foram sacerdotes da tribo de Dã até o dia em que o povo foi para o cativeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Assim, eles adoraram a imagem de escultura que Mica havia feito, durante todo o tempo em que a casa de Deus esteve em Siló.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Naqueles dias, quando não havia rei em Israel, havia um homem, um levita, que morava na área mais remota da região montanhosa de Efraim. Ele tomou para si uma mulher, uma concubina, de Belém de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Mas sua concubina foi infiel a ele. Ela o deixou e voltou para a casa do seu pai, em Belém de Judá. E lá permaneceu por quatro meses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Então, seu marido levantou-se e foi atrás dela, a fim de convencê-la a voltar. Seu servo o acompanhou com um par de jumentos. Quando seu marido chegou, ela o trouxe até seu pai, que ficou feliz quando o viu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Seu sogro o convenceu a permanecer ali por três dias. Comeram, beberam e dormiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'No quarto dia, ele se levantou cedo e se preparou para partir, mas o pai da mulher disse: \"Fortalece-te com um pedaço de pão, depois poderás ir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Então, os dois sentaram-se para comer e beber juntos. O pai da moça disse ao genro: \"Por favor, fica esta noite para te divertires”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Quando o levita preparou-se para sair, o pai da jovem insistiu que ficasse. Então, ele mudou seu plano e passou a noite ali novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'No quinto dia, ele acordou cedo para sair, mas o pai da moça disse: \"Fortalece-te, e espera até a tarde\". Então, os dois fizeram uma refeição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Quando o levita, sua concubina e seu servo levantaram-se para partir, o seu sogro, o pai da moça, disse-lhe: \"Olha, agora o dia está avançando para a noite. Por favor, fica outra noite e alegra-te. Poderás levantar-te cedo amanhã e voltar para casa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Mas o levita não estava disposto a ficar naquela noite. Ele levantou-se e saiu. Partiu em direção a Jebus (que é Jerusalém). Ele tinha um par de jumentos com selas, e sua concubina estava com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Quando aproximaram-se de Jebus, já era quase o fim do dia, e o servo disse ao seu mestre: \"Desviemos o nosso percurso para a cidade dos jebuseus, e passemos a noite ali\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Seu mestre lhe disse: \"Não nos desviaremos para nenhuma cidade de estrangeiros que não pertença ao povo de Israel. Iremos até Gibeá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'O levita disse ainda ao seu jovem: \"Vamos a um desses outros lugares e passaremos a noite em Gibeá ou Ramá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Assim prosseguiram, e o sol se pôs quando se aproximavam de Gibeá, no território de Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Eles se desviaram para lá a fim de passarem a noite em Gibeá. Eles entraram e se sentaram na praça da cidade, pois ninguém os recebeu em sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Então, ao anoitecer, um homem idoso estava vindo do seu trabalho. Ele era da região montanhosa de Efraim, mas estava morando por um tempo em Gibeá. Porém, os homens que moravam naquele lugar eram benjamitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Ele levantou seus olhos e, vendo o viajante na praça da cidade, disse: \"Para onde vais? E de onde vens?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'O levita respondeu-lhe: \"Estamos viajando de Belém de Judá para a parte mais remota da região montanhosa de Efraim, que é de onde eu sou. Fui a Belém de Judá e estou indo para a casa de Yahweh, mas não há ninguém que me receba em sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Temos palha e forragem para os nossos jumentos, e há pão e vinho para mim e para a tua serva que aqui está e para este jovem que acompanha os teus servos. Não nos falta nada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'O idoso os cumprimentou, dizendo: \"Que a paz esteja convosco! Cuidarei de todas as vossas necessidades, só não passeis a noite na praça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Então, o homem trouxe o levita para a sua casa e deu forragem aos seus jumentos. Lavaram seus pés, comeram e beberam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Enquanto se divertiam, alguns homens da cidade, homens imprestáveis, rodearam a casa, batendo à porta. Falaram ao homem idoso, o senhor da casa: \"Traze para fora o homem que trouxeste para a tua casa, para que tenhamos relações sexuais com ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'O homem, o senhor da casa, foi até eles e disse-lhes: \"Não, meus irmãos, por favor, não façais esse mal! Porque este homem é um hóspede na minha casa, não façais essa coisa maldosa!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Vede, minha filha virgem e a concubina dele estão aqui. Deixai-me trazê-las para fora agora. Violentai-as, fazei o que quiserdes com elas, mas não façais essa coisa maldosa com este homem!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Porém, os homens não lhe deram ouvidos. Então, o homem tomou a sua concubina e a trouxe para fora para eles. Eles a tomaram, estupraram-na e abusaram dela durante a noite e, ao amanhecer, a deixaram ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Ao amanhecer, a mulher veio e caiu à porta da casa do homem, onde o senhor dela estava, e permaneceu deitada ali até o dia clarear.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Seu senhor levantou-se pela manhã, abriu as portas da casa e saiu para seguir a viagem. Ele viu a sua concubina deitada ali no chão com as suas mãos na soleira da porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'O levita disse a ela: \"Levanta-te. Vamos\", mas não houve resposta. Ele a colocou sobre o jumento, e o homem partiu para casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Quando o levita chegou à sua casa, pegou uma faca, tomou a sua concubina e a cortou, membro por membro, em doze pedaços, e enviou os pedaços por todo o Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Todos os que viram disseram: \"Nunca se fez ou se viu tal coisa em todo o Israel, desde o dia em que o povo de Israel subiu da terra do Egito até hoje. Pensai nisto! Dai-nos conselho! Contai-nos o que se deve fazer!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Então, todo o povo de Israel saiu, como um só homem, de Dã até Berseba, incluindo a terra de Gileade, e se reuniram diante de Yahweh, em Mispá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Os líderes de todo o povo e de todas as tribos de Israel tomaram os seus lugares na assembleia do povo de Deus. Quatrocentos mil homens a pé, capazes de lutar com a espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Ora, o povo de Benjamim soube que o povo de Israel havia subido a Mispá. E os israelitas disseram: \"Contai-nos como essa maldade ocorreu?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'O levita, marido da mulher que havia sido assassinada, respondeu: \"Eu cheguei a Gibeá no território que pertence a Benjamim, eu e a minha concubina, para passarmos a noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Durante a noite, os líderes de Gibeá me atacaram, cercando a casa com a intenção de me matar. Eles violentaram a minha concubina, e ela morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Eu tomei a minha concubina, cortei o seu corpo em pedaços e os enviei para cada região da herança de Israel, por tamanho mal e ultraje por eles cometido em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Agora, todos vós, israelitas, dai aqui o vosso parecer e conselho!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Todo o povo se levantou como um só homem, e disse: \"Nenhum de nós irá para a sua tenda, e nenhum de nós voltará para casa!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Porém, faremos isto a Gibeá: nós a atacaremos, conforme o que o sorteio nos determinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Tomaremos dez homens de cada cem de todas as tribos de Israel, e cem de mil, e mil de dez mil, para fornecerem provisões para estes homens, para que, quando chegarem a Gibeá de Benjamim, eles os punam pela maldade que cometeram em Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Então, todos os soldados de Israel ajuntaram-se contra a cidade, unidos como se fossem um só homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'As tribos de Israel enviaram homens por toda a tribo de Benjamim, dizendo: \"Que maldade é essa que ocorreu entre vós?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Portanto, entregai-nos esses perversos homens de Gibeá, para que os matemos e, assim, removamos por completo o mal de Israel\". Porém, os benjamitas não deram ouvidos aos seus irmãos, o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Então, o povo de Benjamim saiu das cidades e se reuniu em Gibeá, a fim de se preparar para lutar contra o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'O povo de Benjamim trouxe consigo, vindos de suas cidades para lutar naquele dia, vinte e seis mil soldados, que eram treinados para lutar com a espada. Além desses, havia setecentos homens selecionados dos habitantes de Gibeá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Entre todos esses soldados, havia setecentos homens selecionados que eram canhotos, cada um dos quais era capaz de atirar uma pedra, com a funda, num fio de cabelo sem errar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Os homens de Israel, sem incluir os de Benjamim, foram contados em quatrocentos mil. Todos treinados para lutar com a espada. Eram homens de guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'O povo de Israel levantou-se, subiu a Betel e consultou a Deus. Perguntaram-Lhe: \"Quem de nós atacará o povo de Benjamim primeiro?\". Yahweh disse: \"Judá atacará primeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Os israelitas levantaram-se ao amanhecer e moveram o seu acampamento para próximo de Gibeá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Eles saíram para lutar contra Benjamim e tomaram seus postos de batalha contra eles, em Gibeá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Os benjamitas saíram de Gibeá e mataram vinte e dois mil homens do exército de Israel naquele dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Mas os israelitas se fortaleceram e formaram uma linha de batalha no mesmo local em que haviam tomado suas posições no primeiro dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Então, os israelitas subiram e choraram perante Yahweh até a tarde e buscaram a direção de Yahweh. Eles perguntaram: \"Devemos nos levantar novamente contra os nossos irmãos, os benjamitas?\". Yahweh disse: \"Atacai-os!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Então, os israelitas foram enfrentar os benjamitas no segundo dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Nesse segundo dia, o exército de Benjamim veio de Gibeá ao encontro deles, e matou dezoito mil homens do povo de Israel. Todos esses eram treinados para lutar com a espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Então, todos os guerreiros de Israel, e todo o povo, subiram a Betel e choraram. E ali ficaram sentados diante de Yahweh. Eles jejuaram naquele dia até a tarde e ofereceram holocaustos e ofertas pacíficas perante Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'O povo de Israel perguntou a Yahweh (porque, naqueles dias, a Arca da Aliança de Deus estava presente ali,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'e Fineias, filho de Eleazar, filho de Arão, estava ministrando perante a Arca naqueles dias): \"Devemos partir para a batalha mais uma vez contra os benjamitas, nossos irmãos, ou devemos parar?\". Yahweh disse: \"Atacai, porque amanhã Eu vos auxiliarei a derrotá-los\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Então, Israel posicionou homens em locais secretos ao redor de Gibeá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Os israelitas lutaram contra os benjamitas no terceiro dia, e formaram suas linhas de batalha contra Gibeá, como haviam feito antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Os benjamitas saíram e lutaram contra o povo, e foram atraídos para longe da cidade. Eles começaram a matar alguns do povo. Ali, cerca de trinta homens de Israel morreram nos campos e nas estradas. Uma das estradas subia para Betel e outra ia para Gibeá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Então, os benjamitas disseram: \"Eles estão derrotados e fogem de nós, como antes\". Mas os soldados de Israel disseram: \"Vamos recuar e atraí-los para fora da cidade, para as estradas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Todos os homens de Israel levantaram-se de seus postos e formaram-se em linha de batalha em Baal-Tamar. Então, os soldados de Israel que se encontravam escondidos nos locais estratégicos atacaram de suas posições, a oeste de Gibeá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Saíram dez mil homens selecionados de todo o Israel, contra Gibeá, e a batalha tornou-se feroz, mas os benjamitas não sabiam que o desastre estava próximo deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Yahweh derrotou Benjamim perante Israel. Naquele dia, os soldados de Israel mataram vinte e cinco mil e cem homens de Benjamim. Todos esses que morreram foram treinados para lutar com a espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Assim, os soldados de Benjamim viram que estavam derrotados. Os homens de Israel haviam cedido terreno a Benjamim, pois estavam contando com os homens que haviam-se posicionado nos locais secretos fora de Gibeá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Então, os homens que estavam se escondendo levantaram-se e avançaram em direção a Gibeá e, ao fio de espada, mataram todos os que estavam na cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'O sinal combinado entre os soldados de Israel e os que estavam escondidos era que uma grande nuvem de fumaça subiria da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Quando o sinal foi enviado, os soldados de Israel se afastaram da batalha. Ora, os homens de Benjamim já haviam começado a atacar, e mataram em torno de trinta homens de Israel, e disseram: \"É certo que estão derrotados perante nós, como na primeira batalha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Mas, quando a coluna de fumaça começou a subir, os benjamitas viraram-se para trás e viram a fumaça subindo ao céu, vinda da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Então, os israelitas voltaram-se contra eles. Os homens de Benjamim ficaram aterrorizados, pois viram que o desastre havia chegado sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Eles fugiram dos homens de Israel, escapando rumo ao deserto. Mas a batalha os alcançou. Os soldados de Israel saíram das cidades e os mataram onde eles estavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Cercaram os benjamitas e foram atrás deles, e os esmagaram em Noá, ao longo do caminho, até o leste de Gibeá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Da tribo de Benjamim, dezoito mil morreram. Todos eles eram homens que se destacavam na batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Eles se viraram e fugiram rumo ao deserto para a rocha de Rimom. Mas os israelitas mataram ainda cinco mil deles ao longo das estradas. E continuaram a perseguição, seguindo-os de perto até Gidom, e ali mataram mais dois mil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Todos os soldados de Benjamim que caíram naquele dia foram vinte e cinco mil homens treinados para lutar com a espada. Todos esses se destacavam na batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Mas seiscentos homens se viraram e fugiram para o deserto, rumo à rocha de Rimom, e ali ficaram por quatro meses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Os soldados de Israel se voltaram contra os benjamitas e os mataram a fio de espada, incluindo os que estavam nas cidades, o gado, e tudo o que encontravam. Por fim, queimaram todos os povoados pelo caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Ora, os homens de Israel haviam feito uma promessa em Mispá: \"Nenhum de nós dará sua filha para casar-se com um benjamita\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Então, o povo foi para Betel e ficou ali sentado diante de Deus até o anoitecer e, com altas vozes, choraram amargamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Eles clamaram: \"Por que, Yahweh, Deus de Israel, isto aconteceu a Israel, que uma de nossas tribos esteja faltando hoje?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'No dia seguinte, o povo levantou-se cedo, construiu ali um altar, e ofereceu holocaustos e ofertas pacíficas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'O povo de Israel disse: \"Qual de todas as tribos de Israel não subiu para a assembleia de Yahweh?\". Pois eles haviam feito uma promessa importante a respeito de quem deixasse de se reunir perante Yahweh, em Mispá. Eles haviam dito: \"Ele certamente será condenado à morte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'O povo de Israel teve compaixão de seu irmão Benjamim. Eles disseram: \"Hoje uma tribo foi cortada de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Quem dará esposas para aqueles que sobraram, sendo que nós fizemos uma promessa a Yahweh de que não permitiríamos que nenhum deles se casasse com nossas filhas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'E disseram: \"Qual das tribos de Israel não subiu até Yahweh, em Mispá?\". Foi descoberto que ninguém de Jabes-Gileade havia ido para a assembleia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Pois, quando o povo foi posto de forma ordenada, viram que nenhum dos habitantes de Jabes-Gileade estava lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'A assembleia mandou doze mil dos homens mais valentes com instruções para irem atacar os habitantes de Jabes-Gileade e matá-los, até mesmo as mulheres e as crianças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Fazei isto: “Vós matareis todo homem e toda mulher que já dormiu com um homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Os homens acharam entre os que moravam em Jabes-Gileade quatrocentas moças que nunca tinham dormido com um homem e as levaram para o acampamento em Siló, em Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'A assembleia inteira enviou uma mensagem ao povo de Benjamim, que estava na rocha de Rimom: que lhes estavam oferecendo paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Então, os benjamitas retornaram naquela hora e receberam as mulheres de Jabes-Gileade. Mas não havia mulheres suficientes para todos eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'O povo teve pena do que havia acontecido com Benjamim, porque Yahweh fez uma divisão entre as tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Então os líderes da assembleia disseram: \"Como nós arranjaremos esposas para os benjamitas que restaram, já que as mulheres de Benjamim foram mortas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Disseram: \"Deve haver herdeiros para os sobreviventes de Benjamim, para que uma tribo de Israel não seja destruída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Nós não podemos lhes dar nossas filhas como esposas, pois o povo de Israel fez uma promessa: \'Maldito seja qualquer um que der uma esposa a Benjamim”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Então disseram: \"Vós sabeis que todo ano se realiza uma festa para Yahweh, em Siló (que é ao norte de Betel, a leste da estrada que sobe de Betel para Siquém, ao sul de Lebona)\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Eles instruíram os homens de Benjamim, dizendo: \"Ide, escondei-vos e esperai nas vinhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Prestai atenção para o tempo em que as moças de Siló sairão para dançar. Então, correi para fora das vinhas e cada um de vós devereis tomar uma esposa das moças de Siló. Depois, voltai para a terra de Benjamim”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Quando seus pais ou seus irmãos vierem para protestar a nós, diremos a eles: \'Tende piedade deles por nós! Deixai que elas fiquem, pois não conseguimos esposas para cada um deles durante a guerra. E vós sois inocentes, pois não fostes vós que destes as vossas filhas para eles’”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Os benjamitas assim fizeram. Dentre as moças que estavam dançando, eles tomaram o número de mulheres que precisavam e as levaram para serem suas esposas. Eles foram e voltaram para o lugar de sua herança. E reconstruíram as cidades e moraram nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Então, o povo de Israel deixou aquele lugar e foi para casa, cada um para sua tribo e clã, e cada um para sua própria herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Naqueles dias, não havia rei em Israel. Todos faziam o que achavam certo aos seus próprios olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Nos dias em que os juízes julgavam, houve uma fome na terra; e um homem de Belém de Judá mudou-se para a terra de Moabe com sua mulher e seus dois filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'O nome do homem era Elimeleque, e o nome de sua esposa era Noemi. Os filhos se chamavam Malom e Quiliom. Eles eram efrateus, de Belém de Judá. Chegaram à terra de Moabe e habitaram ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Então, Elimeleque, marido de Noemi, morreu; e ela ficou com seus dois filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Seus filhos tomaram como esposas mulheres moabitas. O nome de uma era Orfa, e o nome da outra era Rute. Eles ficaram ali, por cerca de dez anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Então ambos, Malom e Quiliom morreram, ficando Noemi desamparada do seu marido e de seus dois filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Então Noemi decidiu ir embora de Moabe com suas noras e retornar para Judá porque ela ouvira, na região de Moabe, que Yahweh havia se lembrado do seu povo, dando-lhe alimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Então, deixou o lugar onde vivia com suas duas noras e, juntas, caminharam pela estrada, a fim de retornarem à terra de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Noemi disse para suas duas noras: \"Ide e voltai, cada uma de vós, para a casa de vossas mães. Que Yahweh vos trate com a mesma bondade com que tratastes vossos falecidos maridos e a mim também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Que o Senhor permita que cada uma de vós encontre descanso na casa de um outro marido\". Então, ela as beijou e choraram em voz alta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'E disseram: \"Não! Nós retornaremos contigo para junto de teu povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Mas Noemi disse: \"Voltai, minhas filhas! Por que haveríeis de vir comigo? Poderia eu ainda ter filhos em meu ventre para lhes dar como maridos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Voltai, minhas filhas, parti; ide em vosso próprio caminho, porque eu já estou muito velha para ter um marido. Ainda que eu dissesse que há esperança e me casasse esta noite e, então, tivesse filhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'acaso esperaríeis até que eles crescessem? Haveríeis de esperar por eles, sem vos casardes? Não, minhas filhas! Isso me entristece grandemente, muito mais que vos entristece, porque a mão de Yahweh se voltou contra mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Então, suas noras novamente choraram em voz alta. Orfa despediu-se de sua sogra com um beijo, mas Rute agarrou-se a ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Noemi disse: \"Ouve, tua cunhada está voltando para seu povo e para seus deuses. Volta tu também com ela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Mas Rute disse: \"Não me faça ir para longe de ti, porque para onde fores, eu irei; onde ficares, eu ficarei; teu povo será o meu povo, e teu Deus será o meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Onde tu morreres, eu morrerei, e ali serei sepultada. Que Yahweh me castigue, ainda mais, se alguma coisa que não seja a morte venha a nos separar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Quando Noemi viu que Rute estava determinada a ir com ela, parou de discutir com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Então, as duas viajaram até chegarem à cidade de Belém. E aconteceu, que quando elas chegaram em Belém, toda a cidade se comoveu a respeito delas, e as mulheres perguntavam: \"Seria esta Noemi?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Mas ela lhes disse: \"Não me chameis Noemi, mas me chamai Mara, pois o Todo-Poderoso tornou a minha vida muito amarga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Eu parti na fartura, mas Yahweh trouxe-me de volta para casa de mãos vazias. Então, porque me chamais Noemi, visto que Yahweh condenou-me, que o Todo-Poderoso me afligiu?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Então, Noemi e sua nora Rute, a moabita, retornaram da terra de Moabe. Elas vieram para Belém, no começo da colheita da cevada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Elimeleque, marido de Noemi, tinha um parente, Boaz, que era um homem rico e influente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Rute, a moabita, disse a Noemi: \"Agora, deixa-me ir recolher entre as espigas de trigo caídas no campo. Eu seguirei aquele em cujos olhos eu achar graça\". E Noemi disse a ela: \"Vai, minha filha!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Rute foi e recolheu o que restava nos campos, atrás dos ceifeiros. Ela passou a recolher as partes dos campos de Boaz, que era parente de Elimeleque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Eis que Boaz veio de Belém e disse aos ceifeiros: \"Que Yahweh esteja convosco\". E eles responderam: \"Que Yahweh te abençoe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Então, Boaz perguntou ao seu servo encarregado dos ceifeiros: \"A quem esta moça pertence?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'O servo encarregado dos ceifeiros lhe respondeu: \"Esta é a moça moabita que voltou com Noemi da terra de Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Ela me disse: \'Por favor, deixa-me recolher as espigas, entre os feixes, atrás dos ceifeiros\'. Ela veio e está de pé desde cedo; somente agora descansou um pouco no abrigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Então, Boaz disse a Rute: \"Tu estás me ouvindo, minha filha? Não vás colher em outro campo, não saias daqui. Em vez disso, fica aqui e trabalha com as minhas servas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Presta atenção somente no campo onde os homens estão ceifando e vai atrás das outras moças. Não instruí os homens a não te tocarem? E quando estiveres com sede, vai até os potes e bebe a água que os homens tiraram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Então ela se inclinou diante de Boaz, tocando o rosto no chão, e disse-lhe: \"Por que achei graça a teus olhos, para te preocupares comigo, uma estrangeira?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boaz respondeu-lhe: \"Foi relatado a mim tudo o que tens feito desde a morte de teu marido. Como deixaste teu pai, tua mãe e tua terra natal para vir a um povo que não conheces.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Que Yahweh te recompense por teu feito. Que recebas grande recompensa por parte de Yahweh, o Deus de Israel, sob cujas asas vieste buscar refúgio\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Então, ela disse: \"Que eu continue a achar graça aos teus olhos, meu senhor, pois me consolaste e falaste bondosamente comigo, embora eu não seja uma de tuas servas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Na hora da refeição, Boaz disse a Rute: \"Vem aqui e come um pouco de pão e mergulha o teu pedaço no vinagre de vinho\". Ela sentou-se ao lado dos ceifeiros, e ele lhe ofereceu alguns grãos torrados. Ela comeu até ficar satisfeita, e ainda sobrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Quando Rute se levantou para recolher as espigas, Boaz deu ordem aos seus servos, dizendo: \"Deixai que ela recolha até entre os feixes e não a impeçais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Certamente deixai cair algumas espigas de vossos feixes, para que ela as recolha e não a repreendeis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Assim ela recolheu as espigas naquele campo até a tarde. Depois debulhou todas as espigas que havia recolhido e foi quase um efa de cevada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Ela carregou-o e foi para a cidade, e sua sogra viu o que ela tinha recolhido. Rute também trouxe os grãos torrados que havia sobrado da refeição e deu a ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Sua sogra disse-lhe: \"Onde tu colheste hoje? Onde tu trabalhaste? Que o homem que te ajudou seja abençoado\". Então, Rute contou a sua sogra sobre o dono do campo onde ela tinha trabalhado. Ela disse: \"O nome do homem que é dono do campo onde trabalhei hoje é Boaz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Noemi disse a sua nora: \"Que ele seja abençoado por Yahweh, que não deixa de ser leal e bondoso com os vivos e com os mortos\". Noemi disse-lhe mais: \"Aquele homem é nosso parente; é um dos nossos resgatadores\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Rute, a moabita, disse: \"De fato, ele me disse: \'Fica com os meus ceifeiros, até que eles terminem toda a minha colheita\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Noemi disse a Rute, sua nora: \"É bom, minha filha, que saias com as servas dele, para que ninguém te perturbe em outra lavoura\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Assim, Rute permaneceu com as servas de Boaz, até o fim da colheita da cevada e da colheita de trigo. E ela morava com a sua sogra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Noemi, sua sogra, disse-lhe: \"Minha filha, não devo procurar um lugar de descanso para ti, para que fiques bem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Lembra de Boaz, o homem que te deixou trabalhar com suas jovens servas; não é ele o nosso parente? Ele estará esta noite limpando a cevada na eira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Portanto, lava-te, perfuma-te, põe tua melhor roupa, e desce para a eira. Mas não permitas que ele te veja até que ele termine de comer e beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Mas, quando ele se deitar, toma conhecimento do lugar onde ele se deitou; porque mais tarde tu irás até ele, descobrirás seus pés e deitarás ali. Então ele te dirá o que fazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Rute disse a Noemi: \"Eu farei tudo que disseste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Então ela desceu até a eira, e seguiu as instruções que sua sogra lhe havia falado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Quando Boaz comeu e bebeu, seu coração se alegrou, e ele foi deitar junto à pilha de grãos. Ela veio suavemente, descobriu seus pés e se deitou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'E sucedeu que, à meia-noite, o homem foi surpreendido. Ele virou-se e lá estava uma mulher deitada aos seus pés!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Ele disse: \"Quem és tu?\" E ela respondeu: \"Eu sou Rute, tua serva; estende o teu manto sobre tua serva, pois tu és um parente próximo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Boaz disse: \"Minha filha, que sejas abençoada por Yahweh. Tu mostraste mais bondade agora do que antes, pois não fostes atrás de nenhum jovem, seja rico ou pobre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'E agora, minha filha, não temas! Eu farei tudo o que disseste, porque toda a cidade do meu povo sabe que tu és uma mulher de valor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'É bem verdade que eu sou um parente próximo, mas acontece que existe um parente mais próximo do que eu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Fica aqui esta noite e, pela manhã, se ele quiser te resgatar, assim seja. Caso ele não faça o que deve fazer para contigo, então o farei, assim como vive Yahweh. Deita-te até que amanheça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Então ela deitou a seus pés, até de manhã. Mas levantou-se antes que uma pessoa a pudesse reconhecer. Pois Boaz tinha dito: \"Que ninguém saiba que uma mulher veio à eira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Então Boaz disse: \"Traze o manto com que te cobres e segura-o\". Quando ela assim o fez, ele despejou seis medidas de cevada e o colocou sobre os ombros dela. Então, ele foi para a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Quando Rute voltou, sua sogra disse-lhe: \"Como foi, minha filha?\" Então Rute disse tudo que o homem havia feito por ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Ela disse: \"Estas seis medidas de cevada são o que ele me deu, pois ele disse: \'Não voltes de mãos vazias para a tua sogra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Então, Noemi disse: \"Fica aqui, minha filha, até que saibas como será resolvido, pois aquele homem não descansará enquanto não tiver resolvido esta questão ainda hoje\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Boaz subiu até o portão e sentou-se ali. Logo, o parente mais próximo de quem Boaz havia falado passou. Boaz disse-lhe: \"Meu amigo, vem cá e senta-te aqui\". O homem veio e sentou-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Então Boaz chamou dez homens dentre os anciãos da cidade e disse-lhes: \"Sentai-vos aqui\". Assim todos se sentaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Boaz disse para o parente mais próximo: \"Noemi, que voltou da cidade de Moabe, está vendendo seu pedaço de terra, que era do nosso irmão Elimeleque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Resolvi te informar disso e dizer-te: \'Compra-a na presença dos que estão aqui sentados e na presença dos anciãos do meu povo\'. Se tu desejas resgatá-la, resgata-a. Mas, se tu não desejas resgatá-la, então me fala, para que eu saiba, pois não existe ninguém para resgatá-la além de ti, e depois de ti, só eu\". Então ele respondeu: \"Eu a resgatarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Então, Boaz disse: \"No dia que tu comprares o campo das mãos de Noemi, tu deverás também tomar Rute, a moabita, que foi esposa do falecido, para preservar o nome dele na sua herança\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Então, o parente mais próximo disse: \"Eu não posso resgatá-la para mim mesmo, sem danificar a minha própria herança. Exerce tu o meu direito de redentor para ti mesmo, porque eu não posso resgatá-la\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Antigamente, este era o costume em Israel com respeito ao resgate e a transferência de bens. Para validar o negócio, o homem tirava a sua sandália e a entregava ao outro; essa era a maneira de fazer acordos legais em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Assim, o parente mais próximo disse para Boaz: \"Comprai-a para ti mesmo\". E ele tirou sua sandália.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Então Boaz disse para os anciãos e para todo o povo: \"Vós testemunhais hoje que eu tenho comprado das mãos de Noemi tudo o que era de Elimeleque e tudo o que era de Quiliom e Malom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Além disso, sobre Rute, a moabita, a mulher de Malom, eu também adquiri o direito de ter ela como minha esposa, para preservar o nome do falecido na sua herança. Assim, o nome dele não será cortado do meio de seus irmãos e do portão da sua cidade. Vós sois testemunhas hoje\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Todas as pessoas que estavam no portão e os anciãos disseram: \"Nós somos testemunhas. Que Yahweh faça com esta mulher que está entrando na tua família como fez com Raquel e Lia: as duas edificaram a casa de Israel. Que prosperes em Efrata e sejas famoso em Belém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Que tua família seja como a de Perez, o qual Tamar teve de Judá, através da descendência que Yahweh dará para ti com essa jovem mulher\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Assim Boaz casou-se com Rute e ela se tornou sua esposa. Ele a conheceu intimamente. Yahweh permitiu que ela engravidasse e ela deu à luz um filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'As mulheres disseram para Noemi: \"Bendito seja Yahweh, que hoje não te deixou sem um resgatador. Que o seu nome seja famoso em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Que ele seja para ti um restaurador da vida e um consolador para tua velhice, pois tua nora, que te ama e que é melhor para ti do que sete filhos, deu à luz a ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Então Noemi pegou o menino, colocou-o em seu colo e passou a cuidar dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Suas vizinhas deram um nome para ele, dizendo: \"Um filho nasceu para Noemi\". E chamaram-no de Obede. Ele tornou-se o pai de Jessé, que tornou-se pai de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Estas são as descendências de Perez: Perez gerou Hezrom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hezrom gerou Rão, Rão gerou Aminadabe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Aminadabe gerou Nasom, Nasom gerou Salmom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmom gerou Boaz, Boaz gerou Obede,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obede gerou Jessé, e Jessé gerou Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Havia um certo homem de Ramataim-Zofim, da região montanhosa de Efraim; seu nome era Elcana, filho de Jeroão, filho de Eliú, filho de Toú, filho de Zufe, um efraimita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Ele teve duas esposas: o nome da primeira era Ana, e o nome da segunda, Penina. Penina teve filhos, mas Ana não os teve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Esse homem ia de sua cidade, ano após ano, para adorar e sacrificar a Yahweh dos Exércitos, em Siló. Os dois filhos de Eli, Hofni e Fineias, sacerdotes de Yahweh, estavam lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Quando o dia do sacrifício anual vinha a Elcana, ele sempre trazia porções de carne para Penina, sua mulher, e para todos os seus filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Mas para Ana ele sempre trazia uma porção dobrada, pois a amava, embora Yahweh tivesse fechado o seu útero.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Sua rival a provocava severamente a fim de irritá-la, pois Yaweh fechara seu útero.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Então, ano após ano, quando ela subia à casa de Yahweh com sua família, sua rival sempre a provocava. Assim, ela costumava chorar e não comer nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Elcana, seu marido, sempre lhe falava: \"Ana, por que choras? Por que não comes? Por que o seu coração está triste? Não sou eu para ti melhor do que dez filhos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Em uma dessas ocasiões, Ana levantou-se quando eles terminaram de comer e beber, em Siló. Eli, o sacerdote, estava sentado em sua cadeira, junto à porta da casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Profundamente angustiada, Ana orou a Yahweh e chorou amargamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Ela fez um voto e disse: \"Yahweh dos Exércitos, se Tu olhares a aflição de Tua serva e Te lembrares de mim, e não esqueceres de Tua serva, mas deres um filho à Tua serva, então o entregarei a Ti todos os dias de sua vida; e navalha alguma tocará sua cabeça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Enquanto ela estava orando a Yahweh, Eli observava sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Ana falava em seu coração. Seus lábios moviam-se, porém, sua voz não era ouvida. Eli pensou que ela estivesse bêbada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Ele falou a ela: \"Por quanto tempo ficarás embriagada? Livra-te de teu vinho!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Ana respondeu: \"Não, meu mestre, eu sou uma mulher de espírito abatido. Não bebi vinho nem bebida forte, mas estou derramando minha alma diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Não considere tua serva como uma mulher sem vergonha; tenho falado da minha grande preocupação e provocação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Então, Eli respondeu e disse: \"Vá em paz. Que o Deus de Israel conceda o que pediste a Ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Ela disse: \"Que tua serva ache favor à tua vista\". Então, a mulher seguiu no seu caminho e comeu; seu semblante não mais era triste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Eles se levantaram cedo pela manhã e adoraram a Yahweh. E voltaram para sua casa, em Ramá. Elcana dormiu com Ana, sua esposa, e Yahweh lembrou-se dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Quando veio o tempo, Ana concebeu e deu à luz um filho. Ela o chamou de Samuel, dizendo: \"Porque pedi por ele a Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Uma vez mais, Elcana e toda a sua casa foram oferecer a Yahweh o sacrifício anual e pagar seu voto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Mas Ana não foi. Ela havia falado ao seu marido: \"Eu não irei até que a criança desmame; então, eu o levarei para que ele possa aparecer perante Yahweh e viver lá para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Elcana falou-lhe: \"Faça o que te parecer bem. Espere até desmamá-lo; somente possa Yahweh confirmar Sua palavra\". Então, a mulher ficou e cuidou de seu filho até desmamá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Quando ela o desmamou, levou-o com ela, juntamente com um touro de três anos, uma efa de refeição e uma garrafa de vinho, e o levou à casa de Yahweh, em Siló. A criança ainda era nova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Eles mataram o touro, e trouxeram a criança para Eli.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Ela disse: \"Ó, meu mestre! Assim como vives, meu mestre, eu sou a mulher que esteve aqui, próxima a ti, orando a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Por essa criança eu orei e Yahweh me concedeu a petição que fiz a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Eu o entreguei a Yahweh; enquanto ele viver será cedido a Yahweh\". E Elcana e sua família adoraram a Yahweh ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, '1 Ana orou e disse: \"O meu coração exulta em Yahweh. Minha força é exaltada em Yahweh. A minha boca sorri de meus inimigos, porquanto me alegro na Tua salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Não há santo como Yahweh, pois não há ninguém além de Ti; não há rocha como o nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Não mais te vanglories tão orgulhosamente; não permitas que qualquer arrogância saia de tua boca. Pois Yahweh é um Deus de sabedoria; por meio Dele as ações são julgadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Os arcos dos homens poderosos são quebrados, mas aqueles que tropeçam são revestidos de força, como um cinto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Os que eram fartos alugam-se por pão; aqueles que eram famintos não mais têm fome. Mesmo a estéril dá à luz sete, mas a mulher que tem muitos filhos se enfraquece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Yahweh mata e traz à vida. Ele leva à sepultura e ressuscita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Yahweh faz o pobre, e faz o rico. Ele humilha, mas Ele também levanta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Ele levanta o pobre do pó. Ele levanta o necessitado do monte de cinzas para fazê-lo sentar-se com príncipes e herdar o assento de honra. Porque os pilares da terra são de Yahweh e Ele estabeleceu o mundo sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Ele guardará os pés daqueles que Lhe são fiéis, mas o ímpio será colocado para silenciar em trevas, porque ninguém prevalecerá por força.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Aqueles que se opõem a Yahweh serão quebrados em pedaços; Ele vai trovejar contra eles do céu. Yahweh julgará as extremidades da terra; dará força ao Seu rei e exaltará o poder do Seu ungido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Então, Elcana foi para sua casa em Ramá. A criança servia Yahweh na presença de Eli, o sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Os filhos de Eli eram homens ímpios. Eles não conheciam Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'O costume dos sacerdotes com o povo era que, quando qualquer homem oferecia um sacrifício, o servo do sacerdote vinha com um garfo de três dentes em sua mão, enquanto a carne estava cozinhando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'Ele a espetava dentro da panela, ou tacho, ou caldeirão, ou pote. Tudo o que o garfo trouxesse, o sacerdote levaria para si mesmo. Eles faziam isto em Siló com todos os israelitas que ali vinham.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Porém, em vez disso, antes que eles queimassem a gordura, o servo do sacerdote vinha e dizia ao homem que estava sacrificando: \"Dá carne de assar para o sacerdote, pois ele não aceitará carne cozida de ti, mas somente crua\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Se o homem dissesse para ele: \"Eles devem queimar a gordura primeiro, e depois levarás tanto quanto tu quiseres\", então ele dizia: \"Não. Tu me darás agora, senão vou tomá-la por força\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'O pecado desses jovens era muito grande diante de Yahweh, pois eles desprezavam a oferta de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Mas Samuel servia Yahweh como uma criança, vestido de um colete sacerdotal de linho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Sua mãe lhe fazia uma pequena túnica e a trazia, ano após ano, quando ela e seu marido subiam para oferecer o sacrifício anual.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Eli abençoava Elcana e sua mulher e dizia: \"Que Yahweh te dê mais filhos desta mulher, por causa do pedido que ela fez a Yahweh\". Então, eles retornavam à sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Yahweh novamente ajudou Ana, e ela novamente engravidou. Ela teve três filhos e duas filhas. Enquanto isso, o menino Samuel crescia diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Eli estava muito velho; ele ouvia a respeito de tudo o que seus filhos faziam a todo o Israel e como se deitavam com as mulheres que serviam à entrada da Tenda de encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Ele lhes disse: \"Por que fazeis tais coisas? Pois de todas as pessoas ouço sobre seus maus procedimentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Não, meus filhos, não é bom esse comentário que ouço. Vós fazeis o povo de Yahweh desobedecer a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Se um homem peca contra outro, Deus o julgará; mas se um homem peca contra Yahweh, quem vai falar por ele?\". Mas eles não queriam ouvir a voz de seu pai, porque Yahweh tinha intenção de matá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'O menino Samuel crescia em estatura e graça diante de Yahweh e também dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Um homem de Deus veio a Eli e disse-lhe: \"Yahweh diz: \'Eu não me revelei à casa de teu antepassado quando, no Egito, eles estavam em cativeiro, sob domínio de Faraó?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Eu o escolhi dentre todas as tribos de Israel para ser Meu sacerdote, subir ao Meu altar, queimar incenso e vestir um colete sacerdotal perante Mim. Eu dei à família de teu ancestral todas as ofertas queimadas do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Por que, então, tu desprezas os sacrifícios e ofertas que exigi no lugar onde Eu moro? Por que tu honras teus filhos acima de mim, engordando-os com o melhor de toda a oferta do Meu povo Israel?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Porque Yahweh, o Deus de Israel, diz: \'Eu prometi que a tua família e a casa de teu ancestral andariam diante de mim perpetuamente\'. Mas agora Yahweh diz: \'Longe de Mim fazer isso, porque Eu honrarei aqueles que Me honram, mas os que Me desprezam serão desprezados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Vê, estão chegando os dias em que cortarei teu poder e o poder da família de teu pai, de modo que não haverá qualquer homem de idade em tua família.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Tu verás sofrimento no local onde Eu moro. Embora prosperidade será dada a Israel, não haverá idoso algum em tua família.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Qualquer de vós que eu não eliminar do Meu altar, Eu farei com que ele consuma os teus olhos, e trarei desgosto para a tua vida. Todos os homens nascidos em tua família morrerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Este será para ti o sinal que virá sobre teus dois filhos, Hofni e Fineias: ambos irão morrer no mesmo dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Eu levantarei para Mim um sacerdote fiel, que vai fazer o que está no Meu coração e na Minha alma. Eu lhe edificarei uma casa firme; e ele andará para sempre diante do Meu rei ungido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Todo aquele que restar de tua família se inclinará a ele, pedindo-lhe uma moeda de prata e um pedaço de pão, e dirá: \'Suplico-te que me dês algum cargo sacerdotal, para que eu possa comer um pedaço de pão\"\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'O menino Samuel servia Yahweh sob a supervisão de Eli. A mensagem de Yahweh era rara naqueles dias; não havia frequente visão profética.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Eli, cuja vista começava a ficar ruim, de modo que ele não podia ver bem, estava dormindo em sua cama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'A lâmpada de Deus ainda não havia se apagado e Samuel estava deitado para dormir na casa de Yahweh, onde estava a Arca de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Então, Yahweh chamou Samuel, que disse: \"Aqui estou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Samuel correu até Eli e disse: \"Aqui estou, pois me chamaste\". Eli disse: \"Não te chamei; deita-te novamente\". Então, Samuel voltou e deitou-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Yahweh o chamou novamente: \"Samuel\". De novo, Samuel levantou-se e foi até Eli e disse: \"Aqui estou, pois me chamaste\". Eli respondeu: \"Não te chamei, meu filho; deita-te novamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Samuel ainda não tivera nenhuma experiência com Yahweh; nenhuma mensagem de Yahweh havia sido revelada a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Yahweh o chamou pela terceira vez. De novo, Samuel levantou-se, foi até Eli e disse: \"Aqui estou, pois me chamaste\". Então Eli percebeu que Yahweh havia chamado o menino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Eli disse a Samuel: \"Vai e deita-te novamente; se Ele te chamar de novo, deves dizer: \'Fala, Yahweh, pois o Teu servo está ouvindo\'\". Samuel voltou e deitou-se mais uma vez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Yahweh veio e permaneceu; Ele o chamou como nas outras vezes: \"Samuel, Samuel\". Então Samuel disse: \"Fala, pois o Teu servo está ouvindo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Yahweh disse a Samuel: \"Vê, vou fazer algo em Israel que tinirá nos ouvidos de todos os que ouvirem a respeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'Naquele dia, cumprirei contra Eli tudo o que Eu disse a ele sobre sua casa, do começo ao fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Eu lhe disse que estava prestes a julgar sua casa, de uma vez por todas, pelos crimes que ele conhece; porque seus filhos trouxeram uma maldição sobre eles mesmos e Eli não os impediu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Por causa disso, Eu jurei à casa de Eli que os pecados de sua casa jamais serão perdoados, nem por sacrifício, nem por oferta.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Samuel deitou-se até o amanhecer; depois, abriu as portas da casa de Yahweh. Mas Samuel estava com medo de contar a Eli sobre a visão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Então, Eli o chamou e disse: \"Samuel, meu filho\". Samuel respondeu: \"Aqui estou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Eli perguntou: \"Qual foi a palavra que Ele falou contigo? Por favor, não me escondas. Que Deus te castigue ainda mais, se tu esconderes alguma coisa de mim das palavras que Ele falou a ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Samuel contou-lhe tudo; não escondeu nada dele. Eli disse: \"Ele é Yahweh. Que Ele faça o que Lhe parecer bom\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Samuel crescia. Yahweh estava com ele e não permitiu que nenhuma de Suas palavras proféticas deixassem de acontecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Todo o Israel, desde Dã até Berseba, soube que Samuel foi escolhido para ser um profeta de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Yahweh apareceu novamente, em Siló, pois ele Se revelou a Samuel em Siló pela Sua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'A palavra de Samuel veio a todo o Israel. Naqueles dias, Israel saiu para batalhar contra os filisteus. Eles montaram acampamento em Ebenézer e os filisteus acamparam em Afeque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Os filisteus se enfileiraram para batalhar contra Israel. Quando a batalha se espalhou, Israel foi derrotado pelos filisteus, que mataram cerca de quatro mil homens no campo de batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Quando o povo voltou ao acampamento, os anciãos de Israel disseram: \"Por que Yahweh nos derrotou hoje diante dos filisteus? Vamos trazer para cá a Arca do testemunho de Yahweh, que está em Siló, para que ela esteja conosco e nos mantenha a salvo do poder dos nossos inimigos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Então, o povo enviou homens à Siló; de lá, eles carregaram a Arca do testemunho de Yahweh dos Exércitos, que se assenta sobre os querubins. Os dois filhos de Eli, Hofni e Fineias, estavam lá com a Arca do testemunho de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Quando a Arca do testemunho de Yahweh chegou ao acampamento, todo o povo de Israel deu um grande brado e a terra ressoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Quando os filisteus ouviram o barulho dos gritos, se perguntaram: \"O que significam esses altos gritos no acampamento dos hebreus?\". Então, perceberam que a Arca de Yahweh fora trazida ao acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Os filisteus estavam com medo; eles disseram: \"Deus veio ao acampamento. Ai de nós! Nada parecido com isso aconteceu antes!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Ai de nós! Quem nos protegerá da força desse poderoso Deus? Esse é o Deus que atacou os egípcios com muitos diferentes tipos de pragas no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Tende coragem e sede homens, filisteus! Ou vos tornareis escravos dos hebreus, como eles têm sido vossos escravos. Sede homens e lutai!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Os filisteus lutaram e Israel foi derrotado. Cada homem fugiu para sua casa, e a matança foi muito grande, pois trinta mil homens de Israel caíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'A Arca de Deus foi tomada e os dois filhos de Eli, Hofni e Fineias, morreram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Um homem de Benjamim correu da linha de batalha e veio a Siló no mesmo dia, chegando com suas roupas rasgadas e com terra em sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Quando ele chegou, Eli estava sentado na sua cadeira perto da estrada, olhando, pois seu coração preocupou-se por causa da Arca de Deus. Quando o homem entrou na cidade e contou as notícias, toda a cidade lamentou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Quando Eli ouviu o barulho do lamento, disse: \"O que significa esse alvoroço?\". O homem veio rapidamente e contou a Eli.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Nesse tempo, Eli tinha noventa e oito anos de idade; seus olhos não focalizavam e ele não podia ver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'O homem disse a Eli: \"Eu sou o que veio da linha de batalha. Eu fugi da batalha hoje\". Eli perguntou: \"Como foi isso, meu filho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'O homem que trouxe as notícias respondeu, dizendo: \"Israel fugiu dos filisteus. Também houve uma grande derrota entre o povo. Teus dois filhos, Hofni e Fineias, estão mortos, e a Arca de Deus foi tomada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Quando ele mencionou a Arca de Deus, Eli caiu da sua cadeira para trás, ao lado do portão. Seu pescoço se quebrou e ele morreu, porque ele era velho e pesado. Ele havia julgado Israel por quarenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Sua nora, esposa de Fineias, estava grávida e prestes a dar à luz. Quando ela ouviu as notícias de que a Arca de Deus foi capturada e que seu sogro e seu marido estavam mortos, ela se agachou e deu à luz, mas as dores do parto a sufocaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Perto da hora da sua morte, as mulheres que a auxiliavam disseram: \"Não temas, porque tu deste à luz um filho\". Ela não respondeu nem considerou em seu coração o que lhe disseram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Mas, chamou a criança Icabode, dizendo: \"A glória de Israel se foi!\". Porque a Arca de Deus havia sido capturada, e por causa de seu sogro e de seu marido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Ela disse: \"A glória de Israel se foi, porque a Arca de Deus foi capturada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Os filisteus capturaram a Arca da Aliança e a trouxeram de Ebenézer a Asdode.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Eles a levaram para dentro da casa de Dagom e a colocaram ao seu lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Quando as pessoas de Asdode acordaram, no dia seguinte, observaram que Dagom havia caído, com o rosto em terra, diante da Arca de Yahweh. Então, eles o levantaram e o puseram de volta no seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Quando acordaram pela manhã do dia seguinte, observaram que Dagom havia caído, com o rosto em terra, diante da Arca de Yahweh. Sua cabeça e ambas as mãos haviam sido cortadas e deixadas na entrada. Somente o tronco de Dagom permaneceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Esse é o motivo pelo qual, até hoje, os sacerdotes de Dagom e qualquer um que chegue à sua casa não pisam na entrada da casa de Dagom, em Asdode.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'A mão de Yahweh pesou sobre os habitantes de Asdode. Ele destruiu e afligiu com tumores Asdode juntamente com seus territórios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Quando os homens de Asdode perceberam o que estava acontecendo, eles disseram: \"A Arca do Deus de Israel não deve ficar conosco, pois Sua mão é dura contra nós e contra Dagom, nosso deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Então, eles mandaram reunir todos os governantes dos filisteus, e lhes disseram: \"O que devemos fazer com a Arca do Deus de Israel?\". Eles responderam: \"Deixe que a Arca do Deus de Israel seja levada para Gate\". E eles carregaram a Arca do Deus de Israel até lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Mas, depois que eles a levaram, a mão de Yahweh foi contra a cidade, causando grande confusão. Ele afligiu os homens da cidade, tanto o grande quanto o pequeno, e tumores apareceram neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Então, eles enviaram a Arca da Aliança para Ecrom. Mas, assim que a Arca da Aliança chegou lá, os ecronitas clamaram, dizendo: \"Eles nos trouxeram a Arca do Deus de Israel, para matar a nós e ao nosso povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Então, eles mandaram reunir todos os governantes dos filisteus, e lhes disseram: \"Mandem embora a Arca do Deus de Israel, e deixai-a retornar ao seu lugar, para que não mate a nós e ao nosso povo\". Pois havia pânico mortal por toda a cidade, e a mão de Deus foi muito pesada lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'O homem que não morreu foi afligido por tumores, e o choro da cidade subiu aos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'A Arca de Yahweh estava na terra dos filisteus há sete meses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Então, os filisteus chamaram os sacerdotes e adivinhadores, e disseram-lhes: \"O que deveremos fazer com a Arca de Yahweh? Dizei-nos como devemos mandá-la de volta à sua terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Os sacerdotes e adivinhadores disseram: \"Se mandardes a Arca do Deus de Israel de volta, não a mandeis sem um presente; deveis enviar uma oferta pela culpa. Assim, ficareis curados e sabereis por que motivo Deus não tirou Sua mão de vós até agora\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Então, o povo disse: \"Que oferta pela culpa devemos enviar-lhes de volta?\". Eles responderam: \"Cinco tumores de ouro e cinco ratos de ouro, pois cinco é o mesmo número dos governantes dos filisteus. Porque a mesma praga afligiu a vós e a vossos governantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Então, deveis fazer moldes de vossos tumores e moldes dos ratos que estão destruindo vossa terra; e dar glória ao Deus de Israel. Talvez Ele retire Sua mão de vós, de vossos deuses e de vossa terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Por que endureceríeis vosso coração, como os egípcios e o Faraó endureceram o deles? Quando o Deus de Israel lidou severamente com eles, os egípcios não deixaram o povo sair, e eles não saíram?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Agora, pois, preparai uma nova carroça com duas vacas leiteiras que nunca foram colocadas debaixo de jugo. Amarrai as vacas à carroça, mas levai os bezerros para casa, longe delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Então, pegai a Arca de Yahweh e colocai-a na carroça. Ao seu lado, colocai, dentro de uma caixa, as peças de ouro que estais retornando a Ele como uma oferta pela culpa. Então, deixai-a seguir seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'E observai: se ela seguir no caminho de sua própria terra, Bete-Semes, então, foi Yahweh que executou esse grande desastre. Mas se não, então saberemos que não foi Sua mão que nos afligiu; ao contrário, saberemos que isso aconteceu a nós por acaso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Os homens fizeram como eles disseram: pegaram duas vacas leiteiras, amarraram-nas à carroça e confinaram seus bezerros em casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Eles colocaram a Arca de Yahweh na carroça, juntamente com uma caixa contendo os tumores e os ratos de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'As vacas seguiram em direção a Bete-Semes. Elas foram por aquela estrada, mugindo todo o caminho, e não mudaram o trajeto nem para direita nem para a esquerda. Os governantes dos filisteus as seguiram até a fronteira de Bete-Semes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'O povo de Bete-Semes estava ceifando seu trigo no vale. Quando levantaram seus olhos e viram a Arca, eles se regozijaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'A carroça foi até o campo de Josué, da cidade de Bete-Semes, e parou ali, onde havia uma grande rocha; eles cortaram a madeira da carroça e ofereceram as vacas em holocausto a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Os levitas tomaram a Arca de Yahweh e a caixa que estava com ela, onde estavam as peças de ouro, e as colocaram sobre a grande rocha. Naquele mesmo dia, os homens de Bete-Semes ofereceram holocaustos e fizeram sacrifícios para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Quando os cinco governantes dos filisteus viram isso, eles retornaram no mesmo dia a Ecrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Esses são os tumores de ouro que os filisteus retornaram como oferta a Yahweh, pela culpa: um para Asdode, um para Gaza, um para Asquelom, um para Gate, e um para Ecrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Os ratos de ouro eram, em número, iguais ao número de todas as cidades que pertenciam aos cinco governantes dos filisteus, tanto das cidades fortificadas quanto das aldeias do interior. A grande rocha, onde eles colocaram a Arca de Yahweh, permanece até hoje como testemunha no campo de Josué, o bete-semita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Yahweh atacou alguns dos homens de Bete-Semes porque eles olharam para dentro de Sua Arca. Ele matou setenta homens. As pessoas lamentaram porque Yahweh havia dado a elas um grande castigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Os homens de Bete-Semes disseram: \"Quem é digno de estar diante de Yahweh, esse Deus Santo? E para quem a Arca irá de nós?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Eles enviaram mensageiros para os habitantes de Quiriate-Jearim, dizendo: \"Os filisteus trouxeram de volta a Arca de Yahweh; vinde e levai-a para vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Os homens de Quiriate-Jearin trouxeram a Arca de Yahweh, e a colocaram na casa de Abinadabe, na colina. Eles consagraram seu filho Eleazar para guardar a Arca de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'A Arca permaneceu em Quiriate-Jearin por muito tempo, a saber, vinte anos. Toda a casa de Israel lamentava e desejava retornar a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Disse Samuel a todo o povo de Israel: \"Se vós retornardes a Yahweh com todo o vosso coração, remover dentre vós os deuses estrangeiros e a Astarote, voltar os vossos corações a Yahweh e adorar somente a Ele, então, Ele vos resgatará da mão dos filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Assim, o povo de Israel removeu os Baalins e a Astarote e adoraram somente a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Então, Samuel disse: \"Congregue todo Israel em Mispá e eu orarei por vós a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Eles se reuniram em Mispá, tiraram água e a derramaram diante de Yahweh. Eles jejuaram aquele dia e disseram: \"Nós temos pecado contra Yahweh\". Ali, Samuel decidia as disputas de todo o povo de Israel e liderava o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Quando os filisteus ouviram que o povo de Israel havia se reunido em Mispá, os governantes dos filisteus atacaram Israel. Quando o povo de Israel ouviu isso, eles sentirammedo dos filisteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Então, disseram a Samuel: \"Não pares de clamar a Yahweh, nosso Deus, por nós. Assim, Ele nos livrará da mão dos filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Samuel tomou um cordeiro que ainda mamava e o ofereceu como uma oferta queimada completa a Yahweh. Samuel, então, clamou a Yahweh por Israel, e Yahweh lhe respondeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Enquanto Samuel estava oferecendo a oferta queimada, os filisteus se aproximaram para atacar Israel; mas Yahweh trovejou, com grande estrondo, naquele dia contra os filisteus; lançou-os em confusão, e eles foram derrotados diante de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Os homens de Israel perseguiram os filisteus, desde Mispá, e os mataram até debaixo de Bete-Car.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Então, Samuel tomou uma pedra e a colocou entre Mispá e Sem. Ele chamou esse lugar de Ebenézer e disse: \"Até aqui, Yahweh tem nos ajudou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Então, os filisteus foram subjugados e não entraram nas fronteiras de Israel. A mão de Yahweh foi contra os filisteus, todos os dias de Samuel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'As cidades que os filisteus haviam tomado de Israel, desde Ecrom até Gate, foram restauradas; Israel tomou de volta seu território dos filisteus. E houve paz entre Israel e os amorreus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Samuel julgou Israel todos os dias de sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'A cada ano, ele percorria um circuito de Betel a Gilgal e a Mispá. Ele decidia as disputas para Israel em todos esses lugares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Então, ele retornava a Ramá, porque sua casa era ali. Nesse lugar, ele também decidia as disputas por Israel e construiu um altar a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Quando Samuel já era velho, ele fez seus filhos juízes sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'O nome do seu primogênito era Joel, e o nome do seu segundo filho era Abias. Eles eram juízes em Berseba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Seus filhos não andaram em seus caminhos, mas foram atrás de ganhos desonestos. Eles recebiam subornos e pervertiam a justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Então, todos os anciãos de Israel se reuniram e vieram a Samuel, em Ramá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Eles lhe disseram: \"Vede, tu estás velho, e teus filhos não andam em teus caminhos. Nomeia para nós um rei para nos julgar, como em todas as nações\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Porém, isso desagradou a Samuel, quando eles disseram: \"Dá-nos um rei para nos julgar\". Então, Samuel orou a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Yahweh disse a Samuel: \"Obedece à voz do povo em todas as coisas que eles te disserem; porque eles não têm rejeitado a ti, mas eles têm rejeitado a Mim como rei sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Eles estão agindo, agora, da mesma forma que vêm agindo desde o dia em que Eu os tirei do Egito: abandonando-Me, e servindo a outros deuses. Do mesmo modo, eles estão fazendo contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Agora, ouve-os; porém, adverte-os solenemente e deixa-os saber a forma com a qual o rei governará sobre eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Então, Samuel disse todas as palavras de Yahweh ao povo que estava pedindo um rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Ele disse: \"Assim será como o rei reinará sobre vós. Ele tomará vossos filhos e os nomeará sobre os seus carros e para ser seus cavaleiros, e para correrem adiante dos seus carros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'nomerá para si mesmo capitães de mil soldados, e capitães de cinquenta soldados. Ele fará alguns deles arar seus campos, colher suas colheitas e outros para fazer suas armas de guerra e os equipamentos para seus carros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Ele também tomará vossas filhas para serem perfumistas, cozinheiras e padeiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Tomará o melhor dos vossos campos, das vossas vinhas e dos vossos olivais para dar aos seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Ele tomará o dízimo dos vossos grãos e das vossas vinhas para dar a seus oficiais e a seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Ele tomará vossos servos e vossas servas e o melhor dos vossos homens jovens e vossos jumentos; Ele colocará todos para trabalhar para si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Ele tomará o dízimo do vosso rebanho, e vós sereis seus escravos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Então, naquele dia, vós clamareis por causa do vosso rei, a quem escolhestes para vós mesmos; porém, Yahweh não vos responderá naquele dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Mas o povo recusou a ouvir Samuel; eles disseram: \"Não! Deve haver um rei sobre nós,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'para que possamos ser como as outras nações, e para que o nosso rei possa julgar-nos e sair adiante de nós e lutar as nossas batalhas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Quando Samuel ouviu todas as palavras do povo, ele as repetiu aos ouvidos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Yahweh disse a Samuel: \"Obedeça à voz deles e faça-lhes um rei\". Então, Samuel disse aos homens de Israel: \"Cada homem deve voltar para a sua própria cidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Havia um homem de Benjamim, um homem de influência. Seu nome era Quis, filho de Abiel, filho de Zeror, filho de Becorate, filho de Afias, o filho de um benjamita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Ele tinha um filho chamado Saul, um belo rapaz. Não havia um homem entre o povo de Israel que fosse mais bonito que ele. Era o mais alto de todo o povo; dos seus ombros para cima, sobressaía a todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'As jumentas de Quis, Pai de Saul, estavam perdidas. Então, Quis disse para Saul, seu filho: \"Leve um dos servos contigo; levanta-te e vá procurar pelas jumentas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Assim, Saul passou pela região montanhosa de Efraim e foi pela terra de Salisa, mas, eles não as encontraram. Depois, eles passaram pelas terras de Saalim. Porém, elas também não estavam lá. Posteriormente, eles passaram pelas terras dos benjamitas, mas ali também não as encontraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Quando eles foram para a terra de Zufe, Saul disse para o servo que estava com ele: \"Vem, vamos voltar, ou meu pai pode parar de se importar com as jumentas e começar a se preocupar conosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Porém, o servo lhe disse: \"Escuta, existe um homem de Deus nesta cidade. Ele é um homem honrado; tudo o que ele diz torna-se verdade. Vamos até lá. Talvez, ele possa nos dizer qual caminho devemos seguir em nossa jornada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Então, Saul disse ao seu servo: \"Mas, se formos, o que podemos levar ao homem? Pois o pão de nossa cesta acabou e não há presente para levarmos para o homem de Deus. O que nós temos?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'O servo respondeu, dizendo: \"Aqui, tenho comigo um quarto de siclo de prata, que darei ao homem de Deus, para nos dizer que caminho devemos seguir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(Antigamente, em Israel, quando um homem buscava vontade de Deus, ele dizia: \"Vem, vamos ao vidente\". Pois, os profetas de hoje em dia eram, antigamente, chamados de videntes).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Então, Saul disse ao seu servo: \"Falaste bem. Vem, vamos\". Logo, eles foram para a cidade onde estava o homem de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Assim que subiram o morro da cidade, eles acharam jovens mulheres que vinham para retirar água; Saul e seu servo lhes perguntaram: \"O vidente está aqui?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Elas responderam, dizendo: \"Ele está; vede, ele está à vossa frente. Apressai-vos, pois hoje ele está vindo para a cidade, porque, no lugar alto, as pessoas estão fazendo sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Assim que entrardes na cidade, o achareis, antes que ele vá ao lugar alto para comer. As pessoas não comerão até que ele chegue, porque ele abençoará o sacrifício; após isso, os que forem convidados comerão. Agora subi, pois ireis encontrá-lo imediatamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Então, eles subiram para a cidade. Enquanto entravam na cidade, viram Samuel vindo em direção a eles, indo para o lugar alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Um dia antes de Saul chegar, Yahweh havia revelado a Samuel:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '\"Amanhã, por volta dessa hora, irei te mandar um homem da terra de Benjamim, e tu irás ungi-lo para ser o rei sobre o Meu povo Israel. Ele salvará Meu povo das mãos dos filisteus. Pois tenho olhado com compaixão para o Meu povo, porque o clamor deles chegou a mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Quando Samuel viu Saul, Yahweh lhe disse: \"Aqui está o homem de quem te falei! Será ele que governará Meu povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Então, Saul se aproximou de Samuel no portão e disse: \"Diz onde é a casa do vidente?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel respondeu a Saul, dizendo: \"Eu sou o vidente. Suba antes de mim ao lugar alto, pois hoje comerás comigo. Pela manhã, eu te deixarei ir e te direi todas as coisas que estão em tua mente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'A respeito das jumentas que se perderam há três dias atrás, não te preocupes, pois elas foram achadas. Em quem estão todos os desejos de Israel? Não está em ti e em todos os da casa de teu pai?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saul respondeu, dizendo: \"Não sou eu um benjamita, da menor tribo de Israel? O meu clã, não é o clã menos importante da tribo de Benjamim? Por que, então, estás falando dessa maneira comigo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Então, Samuel pegou Saul e seu servo, levou-lhes para dentro do salão, e lhes sentou no principal lugar entre os que foram convidados, que eram por volta de trinta pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Samuel disse ao cozinheiro: \"Traz a porção que eu te dei, sobre a qual eu te disse: \'Coloca isso de lado\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Então, o cozinheiro pegou a coxa que havia sido levada em sacrifício e a colocou diante de Saul. Samuel disse: \"Olha o que tem sido guardado para ti! Coma isso, porque tem sido guardado até o tempo marcado para ti. Por agora, pode dizer: \'Eu convidei o povo\'\". Então, Saul comeu com Samuel naquele dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Quando eles desceram do lugar alto para a cidade, Samuel falou com Saul no terraço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Ao amanhecer, Samuel chamou Saul e disse: \"Levanta-te, para que eu possa enviar-te no teu caminho\". Então Saul levantou-se, e ele e Samuel foram para a estrada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Quando eles estavam indo para os arredores da cidade, Samuel disse a Saul: \"Diz ao servo para ir à nossa frente\" — e ele foi à frente — \"mas tu deves ficar aqui por um tempo, para que eu possa anunciar-te a mensagem de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Em seguida, Samuel pegou um frasco de azeite e despejou sobre a cabeça de Saul e o beijou. Ele disse: \"Yahweh não te ungiu para liderares a Sua herança?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Quando te afastares de mim hoje, encontrarás dois homens perto do túmulo de Raquel, no território de Benjamim, em Zelza. Eles te dirão: \'As jumentas que procurais foram encontradas. Acabou a preocupação de teu pai sobre as jumentas, e está aflito acerca de ti, dizendo: \"Que poderei eu fazer por meu filho?\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Portanto, tu irás mais adiante dali, e tu chegarás ao carvalho de Tabor. Três homens, indo a Deus em Betel, te encontrarão ali; um levando três cabritos, outro levando três pães, e outro carregando um odre de vinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Eles te saudarão e te darão dois pães, que tu receberás das mãos deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Depois disso, tu te chegarás ao monte de Deus, onde está a guarnição dos filisteus. Quando chegares à cidade, tu encontrarás um grupo de profetas descendo do lugar alto com harpa, tamborim, flauta e lira adiante deles; eles estarão profetizando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'O Espírito de Yahweh sobre ti virá, e tu profetizarás com eles, e tu serás mudado em um homem diferente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Então, quando esses sinais se cumprirem em ti, faze o que a tua mão encontrar para fazer, pois Deus é contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Desça a Gilgal adiante de mim. Depois eu descerei a ti para oferecer holocaustos e ofertas pacíficas. Espere sete dias até que eu venha a ti e mostre o que deverás fazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Quando Saul virou as costas para deixar Samuel, Deus lhe deu um outro coração. Então, todos aqueles sinais se cumpriram naquele dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Quando eles vieram ao monte, um grupo de profetas o encontrou, e o Espírito de Deus veio sobre ele, de modo que ele profetizou com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Quando os que antes conheciam Saul o viram profetizando com os profetas, perguntaram uns aos outros: \"O que aconteceu ao filho de Quis? É Saul um dos profetas agora?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Um homem daquele mesmo lugar respondeu: \"E quem é o pai dele?\". Por causa desse acontecimento, surgiu o dizer: \"É Saul também um dos profetas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Quando acabou de profetizar, ele foi ao lugar alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'O tio de Saul perguntou a ele e ao seu servo: \"Aonde fostes?\" E ele respondeu: \"Procurar as jumentas; quando nós percebemos que não as encontraríamos, fomos a Samuel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'O tio de Saul disse: \"Por favor, dizei-me o que Samuel vos disse\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Saul respondeu ao seu tio: \"Ele nos disse claramente que as jumentas tinham sido achadas\". Mas Saul não lhe disse sobre os assuntos do reino, dos quais Samuel havia falado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Então, Samuel convocou o povo para apresentar-se a Yahweh em Mispá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Ele disse ao povo de Israel: \"Isto é o que Yahweh, o Deus de Israel diz: \'Eu fiz Israel subir para fora do Egito, e vos resgatei das mãos dos egípcios, e da mão de todos os reinos que vos oprimiam\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Mas hoje vós tendes rejeitado o vosso Deus, que vos livrou de todas as vossas calamidades e aflições; e vós tendes falado a Ele: \'Estabeleça um rei sobre nós.\' Agora apresentem-se perante Yahweh, por tribos e por clãs\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Assim, Samuel fez chegar perto todas as tribos de Israel, e a tribo de Benjamim foi a escolhida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Daí ele fez aproximar a tribo de Benjamim por clãs; e o clã de Matri foi escolhido; e Saul filho de Quis foi escolhido. Mas quando eles foram procurá-lo, ele não foi encontrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'O povo, então, quis fazer mais perguntas a Deus: \"Há ainda um outro homem para vir?\". Yahweh respondeu: \"Ele escondeu-se entre as bagagens\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Eles correram e retiraram Saul de lá. Quando ele ficou de pé no meio do povo, ele era mais alto que qualquer pessoa, dos ombros para cima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Então, Samuel falou ao povo: \"Vistes que homem Yahweh escolheu? Não há ninguém igual a ele entre todo o povo!\". Todo o povo gritou: \"Vida longa ao rei!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Depois, Samuel falou ao povo os direitos e as regras do reinado, escreveu-os num livro, e colocou-o perante Yahweh. Samuel despediu todo o povo, e cada homem foi para a sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Saul também foi para a sua casa, em Gibeá, e com ele foram alguns homens fortes, cujo coração Deus tocara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Mas alguns homens indignos disseram: \"Como pode esse homem salvar-nos?\". Essas pessoas desprezaram Saul e não lhe trouxeram presente algum. Mas Saul manteve-se em silêncio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Então Naás, o amonita, saiu e sitiou Jabes Gileade. Todos os homens de Jabes disseram para Naás: \"Faça um pacto conosco e nós te serviremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Naás, o amonita, replicou: \"Eu farei um acordo convosco, sob a condição de eu extrair o olho direito de todos vós, pois, desta maneira, trarei desgraça sobre todo o Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Os anciãos de Jabes lhe responderam: \"Deixa-nos a sós por sete dias, e enviaremos mensageiros para todo o território de Israel. Então, se não houver alguém que nos ajude, nós nos renderemos a ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Os mensageiros vieram para Gibeá, onde Saul morava, e falaram ao povo o que havia acontecido. Todo o povo chorou em alta voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Eis que Saul vinha do campo acompanhando os bois. Saul disse: \"O que há de errado com as pessoas, pois estão chorando?\". Eles contaram a Saul o que os homens de Jabes haviam dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Quando Saul ouviu o que eles disseram, o Espírito de Deus veio sobre ele, e ele ficou muito irado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Tomou uma junta de bois, cortou-os em pedaços, e enviou as partes por todo o território de Israel, pelos mensageiros. Ele disse: \"Isto é o que acontecerá aos bois de qualquer de vós que não sair após Saul e após Samuel\". Logo, o temor de Yahweh caiu sobre o povo, e eles saíram juntos, como um só homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Quando ele os reuniu em Beseque, todo o povo de Israel era trezentos mil, e os homens de Judá, trinta mil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Eles disseram aos mensageiros: \"Vós direis aos homens de Jabes Gileade: \'Amanhã, quando o sol estiver quente, vós sereis resgatados\'\". Então, os mensageiros saíram e falaram aos homens de Jabes, e eles se alegraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Então, os homens de Jabes disseram a Naás: \"Amanhã nós nos renderemos a ti, e tu farás conosco o que bem te parecer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'No dia seguinte, Saul pôs o povo em três grupos. Eles vieram para o meio do acampamento durante a guarda matinal. Então, atacaram e derrotaram os amonitas até o calor do dia. Aqueles que sobreviveram foram dispersos, de maneira que não deixaram dois deles juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'E o povo disse a Samuel: \"Quem foi aquele que falou: \'Reinará Saul sobre nós?\'. Trazei os homens! Assim, serão postos para morrer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Mas Saul falou: \"Ninguém será morto neste dia, porque hoje Yahweh livrou Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Então, Samuel falou ao povo: \"Vinde, vamos a Gilgal e renovemos ali a monarquia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'E o povo foi para Gilgal e fez Saul rei diante de Yahweh, em Gilgal. Lá, eles sacrificaram ofertas pacíficas diante de Yahweh. Saul, com todos os homens de Israel, regozijaram-se grandemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Disse Samuel a todo o Israel: \"Eu tenho escutado tudo quanto vós me dissestes e eu estabeleci um rei sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Agora, aqui está o rei que vai diante de vós; eu estou velho e de cabelo grisalho; e meus filhos estão convosco. Eu tenho caminhado diante de vós desde a minha juventude até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Eu estou aqui; testemunhai contra mim diante de Yahweh e diante do Seu ungido. De quem tomei um boi? De quem tomei um jumento? A quem eu drefaudei? A quem tenho eu oprimido? Da mão de quem tenho eu recebido suborno para cobrir meus olhos? Testificai essas coisas contra mim, e eu vos restituirei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Eles disseram: \"Tu não nos defraudaste, não nos oprimiste e não roubaste coisa alguma das mãos de nenhum homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Ele lhes disse: \"Yahweh é testemunha contra vós, e Seu ungido é testemunha, hoje, de que vós não encontrastes nada em minhas mãos\". E eles lhe responderam: \"Yahweh é testemunha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Samuel disse ao povo: \"Foi Yahweh quem apontou Moisés e Arão, e quem trouxe vossos pais da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Agora, pois, apresentai-vos, para que eu entre em juízo diante de Yahweh sobre todas as obras de justiça de Yahweh, as quais Ele fez por vós e vossos pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Quando Jacó veio ao Egito, e vossos ancestrais clamaram a Yahweh, Ele enviou Moisés e Arão, que tiraram vossos pais do Egito e eles se acamparam neste lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Mas eles se esqueceram de Yahweh seu Deus; Ele os entregou na mão de Sísera, capitão do exército de Hazor, na mão dos filisteus, e na mão do rei de Moabe; todos esses lutaram contra vossos ancestrais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Eles clamaram a Yahweh e Lhe disseram: \'Nós temos pecado, porque nós abandonamos Yahweh e temos servido aos Baalins e aos Astarotes. Mas agora livra-nos da mão de nossos inimigos e nós Te serviremos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Então, Yahweh enviou Jerubaal, Baraque, Jefté, Samuel e lhes deu vitória sobre os inimigos ao redor, para que, assim, vivessem em segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Quando vistes que Naás, o rei dos amonitas, vinha contra vós, vós me dissestes: \'Não! Ao invés disso, reine um rei sobre nós\' — apesar de o vosso Deus Yahweh ser o vosso Rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Agora, aqui está o rei que vós escolhestes, quem vós pedistes e o qual Yahweh estabeleceu como rei sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Se vós temerdes a Yahweh, servi-Lo, obedecerdes à Sua voz, e não vos rebelardes contra os Seus mandamentos, então, ambos, vós e o rei que reina sobre vós, serão seguidores de Yahweh vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Se vós não obedecerdes à voz de Yahweh, antes, rebelardes contra os mandamentos de Yahweh, então, a mão de Yahweh será contra vós, assim como foi contra vossos ancestrais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Agora mesmo, apresentai-vos e vede que grande coisa Yahweh irá fazer diante de vossos olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Não é tempo da colheita de trigo? Clamarei a Yahweh para que Ele envie trovões e chuva. Então, sabereis e vereis quão grande são vossas maldades, as quais vós tendes feito diante de Yahweh, pedindo-Lhe um rei sobre vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Então, Samuel invocou Yahweh; e, no mesmo dia, Yahweh enviou trovão e chuva. O povo todo temeu grandemente a Yahweh e a Samuel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Então, todo o povo disse a Samuel: \"Interceda a Yahweh teu Deus por teus servos, para que nós não morramos. Pois nós temos acrescentado a todos os nossos pecados este mal, pedindo para nós um rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Samuel lhes respondeu: \"Não temais. Vós cometestes todo este mal, mas não vos afasteis de Yahweh, ao contrário, servi a Ele com todo o vosso coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Não vos desvieis para seguir ídolos inúteis, que não podem vos livrar, por serem inúteis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Por amor do Seu grandioso nome, Yahweh não rejeitará Seu povo, porque Yahweh Se agradou em fazer de vós um povo para Si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Quanto a mim, longe de mim que possa pecar contra Yahweh, cessando de orar por vós. Ao contrário, eu vos ensinarei o caminho que é bom e correto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Apenas temei e servi a Yahweh em verdade, com todo o vosso coração. Considerai as grandiosas coisas que Ele vos tem feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Porém, se vós persistires em fazer o mal, tanto vós como vosso rei morrerão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul tinha trinta anos quando começou a reinar; quando ele havia reinado quarenta anos sobre Israel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'ele escolheu três mil homens. Dois mil estavam com ele em Micmás e na região montanhosa de Betel, enquanto mil estavam com Jônatas, em Gibeá de Benjamim. O restante dos soldados, ele enviou para casa, cada homem para sua tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Jônatas derrotou as tropas dos filisteus que estavam em Geba, e os filisteus souberam disso. Então, Saul soou a trombeta por toda a terra, dizendo: \"Deixe os hebreus ouvirem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Todo o Israel ouviu que Saul havia derrotado as tropas dos filisteus, e também que Israel havia se tornado uma ofensa para os filisteus. Então, os soldados foram convocados para se juntarem a Saul, em Gilgal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Os filisteus se reuniram para lutar contra Israel: três mil carruagens, seis mil homens para dirigir as carruagens, e tropas numerosas como a areia na costa. Eles vieram e acamparam em Micmás, leste de Bete-Áven.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Quando os homens de Israel viram que eles estavam com problemas— pois o povo estava aflito — esconderam-se nas cavernas, nas vegetações, em rochas, em poços e em cisternas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Alguns dos hebreus passaram pelo Jordão até a terra de Gade e Gileade. Mas Saul estava ainda em Gilgal, e todo o povo o seguia, tremendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Ele esperou sete dias, o tempo que Samuel havia determinado. Mas Samuel não foi até Gilgal, e o povo estava se dispersando de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Saul disse: \"Trazei o holocausto e as ofertas pacíficas\". Então ele ofereceu o holocausto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Assim que ele acabaou de oferecer o holocausto, Samuel chegou. Saul saiu para encontrá-lo e cumprimentá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Então, Samuel lhe perguntou: \"O que tu fizeste?\" Saul respondeu: \"Quando vi que as pessoas estavam me deixando, que tu não vieste no tempo determinado, e que os filisteus haviam se ajuntado em Micmás, eu disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, '\'Agora os filisteus vão descer contra mim em Gilgal, e eu não tenho procurado o favor de Yahweh\'. Então eu me forcei a oferecer o holocausto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Samuel disse a Saul: \"Tu tens agido de forma tola. Não tens mantido o comando que Yahweh, o teu Deus, te deu. Pois Yahweh teria estabelecido teu reinado sobre Israel para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Mas agora seu reinado não continuará. Yahweh procurou um homem segundo Seu próprio coração, e Yahweh o nomeou para ser príncipe de Seu povo, pois tu não obedeceste ao que Ele te ordenou.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Então, Samuel se levantou e foi de Gilgal até Gibeá de Benjamin. Depois, Saul contou o povo que estava presente com ele, cerca de seiscentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Saul, seu filho Jônatas, e o povo que estava presente com eles, ficaram em Gibeá de Benjamin. Mas os filisteus acamparam em Micmás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Saqueadores vieram do campo dos filisteus em três grupos. Um grupo foi em direção a Ofra, para a terra de Sual.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'Outro grupo foi rumo a Bete-Horom, e outro grupo, em direção à fronteira que contempla o vale de Zeboim, rumo ao deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Nenhum ferreiro podia ser encontrado em nenhuma parte de Israel, pois os filisteus disseram: \"Caso contrário, os hebreus fariam espadas e lanças para si\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Mas todos os homens de Israel tinham que descer até os filisteus, cada um para afiar suas relhas, suas enxadas, machados e suas foices.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'O custo era de dois terços de um siclo para afiar machados e para amolar aguilhadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Então, no dia da batalha, não foram encontradas espadas ou lanças nas mãos dos soldados que estavam com Saul e Jônatas; somente Saul e seu filho Jônatas as tinham.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'As tropas dos filisteus foram até a passagem de Micmás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Um dia, Jônatas, filho de Saul, disse ao seu jovem escudeiro: \"Vem, vamos até as tropas militares dos filisteus, que estão do outro lado\". Mas ele não contou a seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Saul estava nas fronteiras de Gibeá, debaixo da romeira em Migrom. Havia cerca de seiscentos homens com ele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'incluindo Aías, filho de Aitube, irmão de Icabode, filho de Finéias, filho de Eli, sacerdote de Yahweh em Siló, que vestia um manto sacerdotal. O povo não sabia que Jônatas havia ido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'De cada lado do desfiladeiro que Jônatas pretendia atravessar para alcançar a tropa dos filisteus, havia um penhasco rochoso, de um lado e de outro. O nome de um penhasco era Bozez, e o do outro era Sené.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Um desses penhascos se localizava ao norte, defronte de Micmás, e o outro ao sul defronte de Gibeá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Jônatas disse ao seu jovem escudeiro: \"Vem, vamos atravessar o exército desses incircuncisos. Pode ser que Yahweh trabalhe a nosso favor, pois nada pode impedir Yahweh de salvar, com muitas ou com poucas pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Seu escudeiro respondeu: \"Faze tudo quanto estiver em teu coração. Vá em frente, vê, eu estarei contigo, para obedecer a todas as tuas ordens\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Então, Jônatas disse: \"Nós atravessaremos até aqueles homens, e nos mostraremos a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Se eles disserem: \'Esperem até que os alcancemos\', - então ficaremos em nosso lugar e não atravessaremos até eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Mas, se eles responderem: \'Vinde até nós\', então os alcançaremos, porque Yahweh os entregou em nossas mãos. Este será o nosso sinal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Então, os dois revelaram-se à tropa dos filisteus, que disseram: \"Olhem! Os hebreus estão saindo dos buracos onde haviam se escondido.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Então, os homens do exército disseram a Jônatas e a seu escudeiro: \"Vinde até nós, e lhes mostraremos algo\". Jônatas disse ao seu escudeiro: \"Segue-me, porque Yahweh os entregou nas mãos de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Então, Jônatas subiu engatinhando, e seu escudeiro o seguiu. Os filisteus caíram mortos diante de Jônatas, e seu escudeiro os matava atrás deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Neste primeiro ataque, Jônatas e seu escudeiro mataram cerca de vinte homens, dentro de meia jeira de terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Houve terror no acampamento, no campo e entre o povo. Até mesmo as tropas e os invasores estremeceram. A terra tremeu e houve grande desespero.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Os vigias de Saul, em Gibeá de Benjamim, olharam; a multidão de soldados filisteus estava se dispersando, e fugiam para lá e para cá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Então, Saul disse ao povo que estava com ele: \"Ora, contai e vede quem está faltando entre nós\". Quando eles contaram, Jônatas e seu escudeiro não estavam ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Saul disse a Aías: \"Traze a Arca de Deus aqui\" — porque a Arca estava com o povo de Israel naqueles dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Enquanto Saul falava com o sacerdote, crescia cada vez mais o tumulto no acampamento filisteu. Então, Saul disse ao sacerdote: \"Retira a tua mão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Saul e todo o povo que estava com ele reuniram-se e foram para a batalha. Cada espada dos filisteus estava contra seus próprios companheiros, e havia grande confusão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Os hebreus que, anteriormente, se juntaram aos filisteus, e que haviam ido com eles para o acampamento, uniram-se aos israelitas que estavam com Saul e Jônatas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Quando todos os homens de Israel, que haviam se escondido nas montanhas próximas a Efraim, ouviram que os filisteus estavam fugindo, eles também os perseguiram em batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Então, Yahweh livrou Israel naquele dia, e a batalha passou além de Bete-Áven.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Naquele dia, os homens de Israel estavam angustiados, porque Saul havia colocado o povo sob juramento e dito: \"Maldito seja aquele que comer qualquer comida antes do anoitecer e até que eu me vingue dos meus inimigos\". Por isso, nenhum dos soldados se alimentou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Então, todo o povo chegou a uma floresta onde havia mel no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Quando o povo entrou na floresta, o mel escorria, mas ninguém o tocou nem o levou à boca, porque temiam o juramento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Mas Jônatas não tinha ouvido que seu pai colocara o povo sob juramento. Ele estendeu a ponta da vara que estava em sua mão e a mergulhou no favo de mel. Ele levou a mão à boca, e seus olhos brilharam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Então, alguém do povo disse: \"Seu pai jurou rigorosamente, dizendo: \'Maldito seja o homem que comer comida neste dia\', embora o povo estivesse fraco de fome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Então, Jônatas disse: \"Meu pai trouxe perturbação sobre a terra. Veja como meus olhos tornaram-se brilhantes, porque eu provei um pouco deste mel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Quão bem faria ao povo, se tivesse comido hoje dos despojos achados dos seus inimigos? Por essa razão, o massacre não foi maior entre os filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Eles atacaram os filisteus, naquele dia, desde Micmás até Aijalom. O exército estava exausto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'O povo avançou vorazmente sobre os despojos e pegou ovelhas, bois e bezerros, matando -os no chão, e os comendo com sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Então, disseram a Saul: \"Veja, o exército está pecando contra Yahweh ao comer com sangue. \"Saul disse: \"Vós agistes de maneira infiel. Agora, trazei-me uma grande pedra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Saul disse: \"Ide entre o povo, e dizei-lhe: \'deixe cada homem trazer seu boi e sua ovelha, matai-os aqui, e comei. Não pequeis contra Yahweh comendo-os com sangue\". Assim, naquela noite, cada pessoa trouxe consigo seu próprio boi e o matou ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Saul ergueu um altar a Yahweh. Este foi o primeiro altar que edificou a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Então, Saul disse: \"Desçamos e persigamos os filisteus à noite e os saqueemos até o amanhecer; não deixemos nenhum deles vivo\". Eles responderam: \"Faz o que lhe parecer melhor\". Mas o sacerdote disse: \"Busquemos a Deus aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Saul consultou a Deus, dizendo: \"Descerei atrás dos filisteus? Tu os entregarás nas mãos de Israel?\". Mas Deus não lhe respondeu naquele dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Então, Saul disse: \"Vinde aqui, todos os líderes do povo; vede e sabei como este pecado aconteceu hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Porque, assim como Yahweh vive e salva Israel, mesmo sendo Jônatas meu filho, ele morrerá\". Mas nenhum homem dentre o povo lhe respondeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Ele disse a todo o Israel: \"Vós estareis de um lado, e eu e Jônatas, meu filho, estaremos do outro\". E o povo disse a Saul: \"Faz o que te parecer bom\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Por isso, Saul disse a Yahweh, o Deus de Israel: \"Mostra-nos a verdade\". E a sorte caiu sobre Jônatas e Saul, e o povo escapou de ser escolhido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Depois, Saul disse: \"Lançai sorte entre mim e meu filho, Jônatas\". E a sorte caiu sobre Jônatas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'E Saul disse a Jônatas: \"Dize-me o que fizeste\". Jônatas lhe disse: \"Eu provei um pouco de mel com a ponta da vara que estava em minha mão. Aqui estou eu. Eu morrerei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Saul disse: \"Deus me castigue ainda mais se tu não morreres, Jônatas.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Então, o povo disse a Saul: \"Deveria Jônatas morrer, ele que trouxe tamanha glória a Israel? Longe disso! Assim como Yahweh vive, que nenhum fio de seu cabelo caia no chão, pois ele trabalhou com Deus hoje\". Então o povo resgatou Jônatas, e ele não morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'E Saul parou de perseguir os filisteus, e eles foram para a sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Quando Saul começou a reinar sobre Israel, ele lutou contra todos os seus inimigos de todos os lados. Lutou contra Moabe, os amonitas, Edom, os reis de Zobá e os filisteus. Onde quer que fosse, ele se impunha sobre eles e os vencia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Ele agiu com grande coragem e derrotou os amalequitas. Ele resgatou Israel das mãos daqueles que os saqueavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Os filhos de Saul eram Jônatas, Isvi e Malquisua. Os nomes de suas duas filhas eram: Merabe, a mais velha, e Mical, a mais nova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'O nome da esposa de Saul era Ainoã, filha de Aimaás. O nome do comandante de seu exército era Abner, filho de Ner, tio de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Quis era o pai de Saul; e Ner, pai de Abner, era filho de Abiel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Houve guerra intensa contra os filisteus durante os dias do reinado de Saul. Quando Saul via um homem forte e valente, ele o juntava ao seu exército.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Samuel disse a Saul: \"Yahweh me enviou para ungir-te rei sobre Israel. Agora, ouve a palavra de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Isto é o que Yahweh dos Exércitos diz: \'Eu tenho visto o que Ameleque fez a Israel e a oposição que fizeram no caminho ao voltarem do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Agora, vai e ataca Ameleque e destrói completamente a todos e a tudo que eles têm. Não poupes ninguém, mas mata tanto homens quanto mulheres, crianças e bebês, gado e ovelhas, camelos e jumentos\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Saul convocou uma multidão dentre o povo na cidade de Telaim: duzentos mil homens a pé e dez mil homens de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Então, Saul veio à cidade de Ameleque e se espreitou no vale.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Então, Saul disse aos queneus: \"Ide, parti, saí do meio dos amalequitas, e eu não vos destruirei junto com eles. Pois vós mostrastes misericórdia com o povo de Israel, quando ele estava no Egito\". Então, os queneus fugiram do meio dos amalequitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Saul, então, atacou os amalequitas, desde Havilá até as fronteiras de Sur, que está ao leste do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Em seguida, ele capturou vivo Agague, rei dos amalequitas, e destruiu completamente todo o povo ao fio da espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Mas Saul e os Israelitas pouparam Agague e também o melhor do rebanho de ovelhas, gado, bezerros cevados e cabras. Tudo que estava bom eles não destruiram. Mas, destruíram totalmente qualquer coisa que estava desprezada ou danificada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Então, a palavra de Yahweh veio a Samuel, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '\"Estou angustiado por ter feito Saul rei, porque ele desistiu de Me seguir e não executou Meus mandamentos\". Samuel ficou furioso e clamou ao Senhor a noite inteira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Samuel levantou-se cedo para encontrar Saul, pela manhã. Disseram a Samuel: \"Saul veio ao Carmelo e ergueu um monumento a ele mesmo; em seguida, continuou a descer a Gilgal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Então, Samuel veio a Saul, e Saul lhe disse: \"Sejas bendito por Yahweh! Eu tenho cumprido o mandamento de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Samuel disse: \"Então, o que é este balido de ovelha em meus ouvidos e este mugido de bois que tenho ouvido?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Saul replicou: \"Eles os trouxeram dos amalequitas. Porque o povo preservou o melhor das ovelhas e bois para sacrificar a Yahweh, nosso Deus. O restante, nós destruímos completamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Samuel disse a Saul: \"Espera e eu te direi o que Yahweh disse a mim esta noite\". Saul disse a ele: \"Fala\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel disse: \"Embora sejas pequeno aos teus próprios olhos, tu não fostes chamado para ser um cabeça da tribo em Israel? Yahweh te ungiu rei sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Yahweh te enviou pelo teu caminho e disse: \'Segue e destrói completamente os pecadores, os amalequitas e luta contra eles até que sejam destruídos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Por que tu não obedeceste à voz de Yahweh, mas, ao invés disso, preservaste para si os despojos e fizeste o que é mau perante os olhos do Senhor?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Saul disse a Samuel: \"Decerto, eu tenho obedecido à voz de Yahweh e tenho seguido pelo caminho que Yahweh me enviou. Eu capturei a Agague, rei de Amaleque, e destruí completamente os amalequitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Mas o povo reteve parte dos despojos, ovelhas e gado, e as melhores coisas de lá destinadas à destruição, para sacrificar a Yahweh seu Deus em Gilgal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Samuel respondeu: \"Tem Yahweh mais prazer em holocaustos e sacrifícios do que na obediência à Sua voz? Obediência é melhor que sacrifício, e ouvi-Lo é melhor do que a gordura de carneiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Porque a rebelião é como pecado de adivinhação e a teimosia é como maldade e iniquidade. Porque tu tens rejeitado a palavra de Yahweh, Ele também rejeitou a ti como rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Então, Saul disse a Samuel: \"Eu pequei, pois eu desobedeci aos mandamentos de Yahweh e às Suas palavras, porque tive medo do povo e obedeci à voz deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Agora, por favor, perdoa meu pecado e volta-te a mim para que eu possa adorar a Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Samuel disse a Saul: \"Eu não irei voltar a ti, pois tens rejeitado a palavra de Yahweh, e Yahweh o rejeitou como rei de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Assim que Samuel se virou para partir, Saul segurou sua veste e a rasgou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Samuel disse a ele: \"Yahweh, hoje, tomou de ti o reino de Israel e o deu a um vizinho teu, alguém que é melhor que tu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Também, a Força de Israel não mentirá ou mudará de ideia; porque Ele não é homem, que muda de opinião\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Então, Saul disse: \"Eu pequei. Mas, por favor, me honra, agora, diante dos anciãos de meu povo e diante de Israel. Volta-te a mim, e eu adorarei a Yahweh nosso Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Então, Samuel voltou-se novamente a favor de Saul e Saul adorou a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Então, Samuel disse: \"Traz Agague, rei dos amalequitas até mim\". Agague veio, acorrentado, até ele e disse: \"Certamente, a amargura da morte passou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Samuel respondeu: \"Como tua espada fez mulheres sem filhos, logo, tua mãe, em meio às outras mulheres, ficará sem filhos\". Então, Samuel feriu Agague, esquartejando-o diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Samuel partiu para Ramá, e Saul foi para a casa dele em Gibeá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Samuel não viu Saul até o dia de sua morte, e pranteou por Saul. E Yahweh lamentou por ter ungido Saul como rei sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Yahweh disse a Samuel: \"Por quanto tempo te lamenterás por Saul, sendo que o rejeitei para ser rei sobre Israel? Encha teu vaso de azeite e vai. Eu te enviarei a Jessé de Belém, pois Eu escolhi para Mim um rei entre seus filhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Samuel disse: \"Como eu posso ir? Se Saul ouvir sobre isso, ele me matará\". Yahweh disse: \"Leve um bezerro contigo e diz: \'Eu vim para sacrificar a Yahweh\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Chame Jessé para o sacrifício, e Eu lhe mostrarei o que deves fazer. Tu ungirás para Mim aquele que Eu lhe disser\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel fez como Yahweh disse e foi a Belém. Os anciãos da cidade estavam tremendo enquanto vinham para encontrá-lo e disseram: \"Tu estás vindo em paz?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Ele disse: \"Em paz. Eu vim para sacrificar a Yahweh. Santificai-vos para o sacrifício a Yahweh e vinde comigo\". E ele consagrou Jessé e seus filhos a Yahweh. Depois, ele os chamou para o sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Quando eles vieram, ele olhou para Eliabe e disse a si mesmo que o ungido de Yahweh certamente estava diante dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Mas Yahweh disse a Samuel: \"Não olhe para a sua aparência externa, ou para a sua estatura, porque Eu o rejeitei. Pois Yahweh não vê como o homem vê; o homem olha para a aparência externa, mas Yahweh olha dentro do coração\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Então, Jessé chamou Abinadabe e o fez passar diante de Samuel. E Samuel disse: \"Nem a este Yahweh escolheu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Jessé fez passar Samá. E Samuel disse: \"Nem a este Yahweh escolheu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Jessé fez sete de seus filhos passarem diante de Samuel. E Samuel disse a Jessé: \"Yahweh não escolheu nenhum destes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Então Samuel disse a Jessé: \"Estão todos os teus filhos aqui?\". Ele respondeu: \"Ainda falta o mais novo, mas ele está cuidando das ovelhas\". Samuel disse a Jessé: \"Mande que o busquem, pois nós não nos sentaremos até que ele venha aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Jessé mandou que o trouxessem. Esse filho era ruivo e tinha olhos bonitos e uma bonita aparência. Yahweh disse: \"Levanta-te e unge-o, pois ele é o escolhido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Então, Samuel pegou o vaso de azeite e ungiu-o no meio de seus irmãos. O Espírito de Yahweh esteve em Davi daquele dia em diante. Então, Samuel se levantou e foi para Ramá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'O Espírito de Yahweh deixou Saul, e um espírito maligno vindo de Yahweh o perturbava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Os servos de Saul lhe disseram: \"Vê, um espírito maligno vindo de Yahweh te perturba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Nosso mestre, manda agora teus servos que estão diante de ti procurarem por um homem que seja um exímio tocador de harpa. Então, quando o espírito maligno, vindo de Deus, estiver em ti, ele a tocará e tu ficarás bem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Saul disse a seus servos: \"Encontrai para mim um homem que saiba tocar bem e trazei-o a mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Então, um dos jovens respondeu, dizendo: \"Eu vi um filho de Jessé, o belemita, que tem o dom de tocar. Um homem forte e corajoso, um homem de guerra, de discurso prudente, um homem de boa aparência; e Yahweh é com ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Então, Saul mandou os mensageiros a Jessé, e disse: \"Envia a mim teu filho Davi, que é pastor de ovelhas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Jessé pegou um jumento carregado com pão, um recipiente com vinho, e um novilho, e os mandou a Saul, juntamente com seu filho Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'E Davi veio para Saul e entrou a seu serviço. Saul o amou grandemente, e ele se tornou seu escudeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Saul enviou um mensageiro a Jessé, dizendo: \"Deixa que Davi esteja diante de mim, pois ele achou favor aos meus olhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Sempre que o espírito maligno vindo de Deus estava sobre Saul, Davi pegava a harpa e a tocava. Assim, Saul se acalmava e ficava bem, pois o espírito maligno se afastava dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Os filisteus ajuntaram seus exércitos para a batalha. Eles estavam reunidos em Socó, que pertence a Judá. Eles haviam acampado entre Socó e Azeca, em Efes-Damim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Saul e os homens de Israel acamparam-se no vale de Elá e formaram sua linha de batalha para encontrar os filisteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Os filisteus se posicionaram em uma montanha, e Israel se posicionou na montanha do outro lado, com um vale entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Um homem forte, cuja altura era de seis côvados e um palmo, saiu do acampamento filisteu. Ele era chamado Golias, de Gate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Ele tinha um capacete de bronze em sua cabeça e estava vestido com uma couraça de ferro. A couraça pesava cinco mil siclos de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Ele tinha uma armadura de bronze em suas pernas e uma lança de bronze nos ombros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'A vara de seu arpão era grande, com um laço de corda para lançá-la, como a corda em um suporte de tear. A ponta de sua lança pesava seis mil siclos de ferro. Seu escudo ia à sua frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Golias se levantou e gritou para as tropas de Israel: \"Por que vos posicionastes para a batalha? Não sou eu um filisteu, e não sois vós servos de Saul? Escolhei um homem entre vós e o fazei descer até mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Se ele for capaz de lutar comigo e me matar, então nós nos tornaremos vossos escravos. Mas, se eu derrotá-lo e o matar, então vós sereis nossos escravos, e nos servireis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Novamente, o filisteu disse: \"Eu desafio os exércitos de Israel hoje. Dai-me um homem para que lutemos juntos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Quando Saul e todo o Israel ouviram o que disse o filisteu, eles ficaram desencorajados e grandemente amedrontados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Davi era filho de Jessé, um efrateu de Belém de Judá. Jessé tinha oito filhos e era um homem idoso nos dias de Saul, avançado em anos entre os homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Os três filhos mais velhos de Jessé seguiram Saul na batalha. Seus nomes eram: Eliabe, o primogênito, o segundo, Abinadabe e o terceiro, Samá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Davi era o mais novo. Os três mais velhos seguiram Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Então, Davi ia e voltava — por entre o exército de Saul e o rebanho de seu pai, em Belém — para levar alimento aos irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Por quarenta dias, o homem forte dos filisteus vinha pela manhã e à tarde se apresentar para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Então, Jessé disse a seu filho Davi: \"Leva para os teus irmãos um efa deste grão tostado e estes dez pães; leva-os rapidamente para o campo para teus irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Leva também estes dez queijos para o capitão dos mil deles. Vê como teus irmãos estão indo e traz alguma prova de que estão passando bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Teus irmãos estão com Saul e todos os homens de Israel no vale de Elá, lutando contra os filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Davi se levantou cedo pela manhã e deixou o rebanho aos cuidados de um pastor. Ele pegou os suprimentos e saiu, como Jessé lhe havia ordenado. Ele veio ao campo enquanto o exército estava saindo do campo de batalha, gritando o lamento de guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'E Israel e os filisteus se alinharam para a batalha, exército contra exército.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Davi deixou seus pertences com o guarda de suprimentos, correu até o exército e cumprimentou seus irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Enquanto falava com eles, o homem forte, o filisteu de Gate chamado Golias, saiu do meio das tropas dos filisteus e disse as mesmas palavras de antes. E Davi as ouviu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Quando todos os homens de Israel viram Golias, esquivaram-se dele, pois estavam com muito medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Os homens de Israel disseram: \"Vistes este homem que se levantou? Ele veio para desafiar Israel. E o rei dará ao homem que o matar grandes riquezas, e também lhe dará sua filha em casamento, e fará a casa de seu pai livre dos impostos em Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Davi disse aos homens que que estavam perto dele: \"O que será feito pelo homem que matar esse filisteu e tirar a desgraça de sobre Israel? Quem é esse filisteu incircunciso, para que desafie o exército do Deus vivo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Então, o povo repetiu o que estavam falando e lhe disseram: \"E isso será feito ao homem que o matar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Eliabe, seu irmão mais velho, ouviu quando ele falou aos homens. Eliabe ficou irado com Davi e disse: \"Por que desceste até aqui? Com quem deixaste as poucas ovelhas no deserto? Eu conheço teus anseios e as travessuras de teu coração; pois tu desceste aqui para que pudesse ver a batalha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Davi disse: \"O que fiz eu agora? Não foi apenas uma pergunta?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Davi se desviou dele para outro, e falou da mesma forma. As pessoas responderam com as mesmas palavras de antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'As palavras que Davi disse foram ouvidas, os soldados as repetiram a Saul e ele mandou buscar Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Então, Davi disse a Saul: \"Não deixe que o coração de nenhum homem desfaleça por causa desse filisteu; teu servo irá e lutará com esse filisteu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Saul disse a Davi: \"Não és capaz de ir contra o filisteu para lutar com ele, pois és apenas um jovem, e ele, um homem de guerra desde a juventude\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Mas Davi disse a Saul: \"Teu servo costumava cuidar das ovelhas de seu pai. Quando um leão ou um urso veio para tomar um cordeiro dentre o rebanho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'eu o persegui, o ataquei e o resgatei de sua boca. E, quando se levantou contra mim, eu o peguei pela sua juba, o feri e o matei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Teu servo matou ambos, o leão e o urso. Este filisteu incircunciso será como um deles, uma vez que ele desafiou o exército do Deus vivo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Davi disse: \"Yahweh me resgatou das garras do leão e das garras do urso. Ele me resgatará das mãos desse filisteu\". Então, Saul disse a Davi: \"Vai, e que Yahweh seja contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Saul vestiu Davi com sua armadura. Ele colocou o capacete de bronze sobre sua cabeça e o vestiu com uma couraça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Davi assentou sua espada em sua armadura. Mas ele não era capaz de andar, pois não havia sido treinado para usá-la. Então, Davi disse a Saul: \"Eu não posso ir à luta com isto, pois não tenho costume de usá-la\". Então, Davi as tirou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Ele tomou sua vara nas mãos e pegou cinco pedras polidas do córrego; ele as colocou em sua bolsa de pastor. Sua funda estava em suas mãos e ele se aproximou do filisteu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'O filisteu veio e se aproximou de Davi, com seu escudeiro à sua frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Quando o filisteu olhou e viu Davi, ele o desprezou, pois era apenas um menino ruivo, com uma aparência agradável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Então, o filisteu disse a Davi: \"Sou eu um cão, para que venhas a mim com gravetos?\". E o filisteu amaldiçoou Davi em nome de seus deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'O filisteu disse ainda: \"Vem até mim e eu darei a tua carne aos pássaros do céu e às bestas do campo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Davi respondeu ao filisteu: \"Tu vens a mim com uma espada, uma lança e um dardo. Mas eu venho a ti, no nome de Yahweh dos Exércitos, o Deus dos exércitos de Israel, a quem desafiaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Hoje, Yahweh me dará vitória sobre ti, e eu te matarei e tirarei a cabeça de teu corpo. Hoje, eu darei os corpos do exército dos filisteus aos pássaros nos céus e às bestas feras da terra;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'e toda esta multidão saberá que há Deus em Israel; e toda esta multidão saberá que Yahweh dá a vitória não através de espadas ou lanças, pois a batalha é de Yahweh, e Ele vos entregará em nossas mãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Quando o filisteu se levantou e veio ao encontro de Davi, este correu rapidamente em direção ao exército inimigo, para encontrá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Davi colocou sua mão em sua bolsa, pegou uma pedra, lançou-a com o estilingue, e acertou o filisteu na testa. A pedra entrou na testa do filisteu, e ele caiu com o rosto no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Davi derrotou o filisteu com um estilingue e uma pedra. Ele acertou o filisteu e o matou. Não havia espada nas mãos de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Então, Davi correu e se pôs sobre o filisteu, desembainhou a espada dele e o matou, cortando-lhe fora a cabeça. Quando os filisteus viram que seu guerreiro forte estava morto, eles fugiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Então, os homens de Israel e de Judá se levantaram com gritos e perseguiram os filisteus até o vale e os portões de Ecrom. E os filisteus mortos caíram no caminho para Saraim, em todo o caminho de Gate a Ecrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Então, os homens de Israel voltaram da perseguição aos filisteus e saquearam seu acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Davi pegou a cabeça do filisteu e a trouxe a Jerusalém, mas colocou sua armadura em sua tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Quando Saul viu Davi sair em direção ao filisteu, ele disse a Abner, o capitão do exército: \"Abner, de quem este jovem é filho?\". Abner disse: \"Como tu vives, rei, eu não o sei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'O rei disse: \"Pergunta a quem deve saber, de quem este é filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Quando Davi retornou após matar o filisteu, Abner o tomou e o trouxe para diante de Saul, com a cabeça do filisteu em sua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Saul lhe perguntou: \"De quem és filho, meu jovem?\". Davi respondeu: \"Eu sou filho do teu servo Jessé, o belemita\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Depois de ter falado com Saul, a alma de Jônatas se uniu à de Davi e Jônatas o amou como sua própria alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Naquele dia, Saul introduziu Davi em seu serviço e não o deixou retornar à casa de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Em consequência disso, Jônatas e Davi fizeram entre si um pacto de amizade, porque Jônatas amou Davi como sua própria alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Jônatas se despiu do manto que usava e presenteou Davi juntamente com sua armadura, bem como sua espada, seu arco e seu cinto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Davi ia a todos os lugares para onde Saul o enviava e era bem sucedido. Saul o colocou como chefe dos seus guerreiros. Isto agradou a todos, até mesmo aos servos de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Ao retornarem para casa, vindo da vitória contra os filisteus, as mulheres de todas as cidades de Israel vieram, com júbilo, cantando e dançando ao som de tamborins e instrumentos musicais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'As mulheres cantavam e diziam umas às outras: \"Saul matou seus milhares, mas Davi dez milhares\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Saul ficou extremamente furioso, pois essa canção o incomodou. \"Eles renderam a Davi dez milhares, mas a mim apenas os milhares. O que mais pode ele almejar senão o reinado?\", disse Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'E, a partir daquele dia, Saul olhava Davi com suspeita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'No dia seguinte, um espírito maligno da parte de Deus se apoderou de Saul, e ele se encheu de ira dentro de casa. Então, Davi tocou seu instrumento exatamente como sempre fazia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Saul tinha na mão uma lança. Ele a arremessou contra Davi enquanto pensava no seu coração: \"Vou encravá-lo na parede\". Porém, Davi escapou dele por duas vezes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Saul temia Davi porque Yahweh estava com ele, e não mais com Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Saul, então, o removeu de sua presença e o comissionou como comandante de mil homens. Desta forma, Davi entrava e saía diante do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Ele prosperava em tudo o que fazia porque Yahweh era com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Saul, ao perceber que Davi prosperava em tudo, o admirou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Toda a nação de Israel e Judá amava Davi, pois ele saía e entrava diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Saul, então, disse a Davi: \"Vê, aqui está Merabe minha filha mais velha. Eu a darei a ti como esposa. Tão somente sê corajoso e guerreia as batalhas de Yahweh\". O raciocínio de Saul era: \"Não caia sobre ele minhas mãos e, sim, a dos filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Davi disse a Saul: \"Quem sou eu, e o que significa minha vida ou a família do meu pai em Israel para que eu seja genro do rei?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Porém, quando chegou o tempo para que Merabe fosse entregue a Davi, ela foi dada como esposa a Adriel, o meolatita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Mical, no entanto, a outra filha de Saul, amava Davi. Disseram isto a Saul, o que lhe agradou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Saul pensou: \"Vou dar Mical a Davi para que ela sirva de armadilha e, assim, a mão dos filisteus esteja contra ele\". Então, Saul disse a Davi pela segunda vez: \"Tu serás meu genro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Saul ordenou aos seus servos, dizendo: \"Conversai em particular com Davi e dizei-lhe: \'Vê, o rei gosta muito de ti, e todos os seus servos te amam também. Ora, pois, aceita o convite para ser genro do rei\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Então, os servos de Saul falaram essas palavras a Davi, mas este retrucou: \"Por acaso, vos parece coisa trivial ser genro do rei, já que sou pobre e de pouca estima em Israel\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Os servos de Saul contaram a ele as palavras que Davi dissera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Ao que Saul disse: \"Assim direis a Davi: \'O rei não está interessado em nenhum dote, tão somente em cem prepúcios dos filisteus como forma de vingança contra os inimigos dele\". Saul pensou que desse modo pudesse fazer Davi cair pelas mãos dos filisteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Quando seus servos disseram a Davi tais palavras, ele ficou feliz em tornar-se genro do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Antes mesmo de esgotar o prazo, Davi saiu com seus homens e matou duzentos filisteus. Ele trouxe os prepúcios, que foram todos entregues ao rei, para que Davi pudesse se tornar seu genro. Assim, Saul o presenteou com Mical, sua filha, que se tornou sua esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Saul viu e percebeu que Yahweh era com Davi. E Mical, filha de Saul, o amava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Saul temeu ainda mais Davi e, de contínuo, o odiava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Os príncipes dos filisteus saíram, depois disso, para a luta; e todas as vezes que isto acontecia, Davi era mais bem sucedido do que todos os servos de Saul; desta forma, seu nome passou a ser altamente estimado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Saul disse a Jônatas, seu filho, e a todos os seus servos que eles deveriam matar Davi. Mas Jônatas, filho de Saul, tinha grande afeição por Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Então, Jônatas disse a Davi: \"Meu pai Saul busca te matar. Portanto, protege-te pela manhã, e esconde-te em um lugar secreto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Eu sairei e ficarei junto a meu pai no campo onde tu estiveres, e eu falarei com meu pai sobre ti. Se eu for informado sobre algo, eu te direi.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Jônatas falou bem de Davi a Saul, seu pai, e lhe disse: \"Não permitas que o rei peque contra teu servo Davi. Pois ele não tem pecado contra ti, e seus atos fizeram bem a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Pois ele expôs sua própria vida quando matou o filisteu. Yahweh trouxe uma grande vitória para todo o Israel. Tu viste e te alegraste. Por que tu pecarias contra sangue inocente matando Davi, sem motivo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Saul ouviu Jônatas. Saul jurou: \"Assim como Yahweh vive, ele não será colocado para morrer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Depois, Jônatas chamou Davi e disse-lhe todas estas coisas. Jônatas trouxe Davi a Saul, e ele ficou em sua presença como antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'E houve guerra novamente. Davi saiu e lutou contra os filisteus, e os derrotou com grande massacre. Eles fugiram diante dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Um espírito mau, enviado por Yahweh, veio sobre Saul quando ele estava sentado em sua casa, com sua lança na mão. Davi tocava seu instrumento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Saul tentou prender Davi à parede com a lança, mas ele escapou para longe da presença de Saul. Então, Saul perfurou a parede com a lança. Davi fugiu e escapou naquela noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Saul enviou mensageiros à casa de Davi para vigiá-lo, para que ele pudesse matá-lo pela manhã. Mical, esposa de Davi, lhe disse: \"Se tu não salvares tua vida esta noite, amanhã tu serás morto.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Então, Mical baixou Davi pela da janela. Ele fugiu e escapou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Mical pegou um ídolo doméstico e o deitou na cama; colocou um travesseiro de pelo de cabra na cabeceira e os cobriu com roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Quando Saul enviou seus mensageiros para pegarem Davi, ela disse: \"Ele está doente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Mais tarde, Saul enviou novamente os mensageiros; ele disse: \"Tragam-no para mim na cama, para que eu possa matá-lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Quando os mensageiros entraram, viram que um ídolo doméstico estava sobre a cama com o travesseiro de pelo de cabra em sua cabeceira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Saul disse a Mical: \"Por que tu me enganaste e deixaste que meu inimigo escapasse de mim?\". Mical respondeu a Saul: \"Ele me disse: \'Deixa-me ir. Por que deveria matá-la?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Davi fugiu e escapou, indo até Samuel, em Ramá. Ele lhe contou tudo o que Saul havia feito. Depois, ele e Samuel ficaram em Naiote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Isto foi dito a Saul: \"Vê, Davi está em Naiote, em Ramá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Então, Saul enviou mensageiros para capturar Davi. Quando eles viram o grupo de profetas profetizando, e Samuel levantando-se como cabeça sobre eles, o Espírito de Deus veio sobre os mensageiros de Saul, e eles também profetizaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Quando contaram a Saul, ele enviou outros mensageiros, e eles também profetizaram. Então, Saul enviou mensageiros pela terceira vez, e eles também profetizaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Depois, Saul também foi a Ramá e chegou ao poço profundo que está em Sécu. Ele pergunto: \"Onde estão Samuel e Davi?\". Alguém disse: \"Vê, eles estão em Naiote, em Ramá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Saul foi para Naiote, em Ramá. E o Espírito de Deus veio também sobre ele. E Saul profetizava enquanto ia para Naiote, em Ramá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'E ele também tirou as roupas, e profetizou diante de Samuel, e deitou-se nu, durante todo aquele dia e toda aquela noite. Por causa disso, eles diziam: \"Está também Saul entre os profetas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Então, Davi fugiu de Naiote em Ramá e veio e disse a Jônatas: \"O que eu fiz? Qual é minha iniquidade? Qual é o meu pecado perante teu pai, para que me persiga para tirar-me a vida?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Jônatas disse a Davi: \"Longe disso. Tu não morrerás. Meu pai não faz nada grande nem pequeno que não me diga. Por que meu pai esconderia isso de mim? Não é assim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Davi, contudo, fez novamente um juramento e disse: \"Teu pai bem sabe que tenho achado graça aos teus olhos. Ele disse: \'Não permitas que Jônatas saiba disso, ou ele ficará entristecido\'. Mas, assim como é verdade que Yahweh vive, como tu vives, existe apenas um passo entre mim e a morte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Então, Jônatas disse a Davi: \"Qualquer coisa que tu disseres, eu farei por ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Davi disse a Jônatas: \"Amanhã será lua nova, e eu deveria sentar-me e comer com o rei. Mas deixa-me ir, para que eu me esconda nos campos até o terceiro dia ao anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Se teu pai sentir minha falta, então, dize-lhe: \'Davi disse seriamente que deveria partir para ir até Belém, sua cidade, porque lá acontecerá o sacrifício anual para toda a família\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Se ele disser \'tudo bem\', o teu servo terá paz. Mas se ele se enfurecer, sabes que ele decidiu fazer-me mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Assim, trata com zelo o teu servo. Porque tu tens levado o teu servo a ter uma aliança com Yahweh. Mas se houver pecado em mim, mata-me tu. Por que deverias tu apresentar-me ao teu pai?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Jônatas disse: \"Que isso esteja longe de ti. Se eu soubesse que meu pai decidiu ferir-te, por acaso, eu não te diria?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Então, Davi disse a Jônatas: \"Quem me dirá se, por acaso, o teu pai vai responder-te com rispidez?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jônatas disse a Davi: \"Vamos, saiamos para o campo\". E ambos foram para o campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Jônatas disse a Davi: \"Que Yahweh, o Deus de Israel, seja testemunha. Quando eu questionar meu pai por este tempo, amanhã ou pelo terceiro dia, se não existir boa vontade para contigo, não te faria saber?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Se meu pai se agrada de fazer-te algum mal, que Yahweh faça a mim o que Lhe aprouver se eu não te der a conhecer e te enviar para longe, de modo que possas ir em paz. Que Yahweh seja contigo, assim como Ele tem estado com meu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Como eu ainda estou vivo, tu não me mostrarias a aliança de fé de Yahweh, para que eu não morra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'E não interrompas a aliança de fé duradoura de minha casa, mesmo quando Yahweh exterminar da face da terra cada um dos inimigos de Davi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Então, Jônatas fez uma aliança com a casa de Davi e disse: \"Que Yahweh exija uma prestação de contas dos inimigos de Davi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Jônatas fez com que Davi reafirmasse os votos de amor por ele, porquanto ele o amava também como amava sua própria alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Então, Jônatas lhe disse: \"Amanhã é lua nova. Sentirão tua falta, porque o teu lugar ficará vazio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Quando ficares por três dias, desce rapidamente e vem ao local onde havias te escondido quando tudo começou, e permanece junto à pedra de Ezel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Eu lançarei três flechas para o lado como se estivesse mirando um alvo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'E enviarei meu jovem e lhe direi: \'Vai e acha as flechas\'. Se eu disser ao jovem rapaz: \'Vê, pega as flechas. Elas estão deste teu lado\", então vem. Porquanto, certo como vive Yahweh, haverá segurança para ti e nenhum perigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, '\"Mas se eu disser ao jovem rapaz: \'Vê, as flechas estão depois de ti\', então vai pelo teu caminho, pois Yahweh te manda ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Sobre o acordo firmado entre mim e ti, vê, Yahweh está entre mim e ti para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Então, Davi escondeu-se no campo. Quando a lua nova chegou, o rei assentou-se para comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'O rei assentou-se perto da parede, como fazia sempre. Jônatas se levantou e Abner sentou-se ao lado de Saul. Mas o lugar de Davi estava vazio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Saul ainda não havia dito nada naquele dia, porque ele pensava: \"Algo aconteceu-lhe. Com certeza, ele não está limpo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Mas no segundo dia, o dia depois da lua nova, o lugar de Davi continuava vazio. Saul perguntou a Jônatas, seu filho: \"Por que o filho de Jessé não veio para o jantar, nem ontem nem hoje?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jônatas respondeu-lhe: \"Davi seriamente pediu-me permissão para ir a Belém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Ele disse: \'Por favor, deixa-me ir. Porquanto nossa família tem um sacrifício na cidade, e meu irmão ordenou que eu estivesse lá. Agora, se encontrei graça em teus olhos, por favor deixa-me ir e ver meus irmãos\'. Por essa razão ele não veio à mesa do rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Então, a raiva de Saul ardeu contra Jônatas, e ele lhe disse: \"Filho de uma perversa, de uma mulher rebelde! Não sei eu que tu escolheste o filho de Jessé para tua própria vergonha, e para a vergonha da nudez de tua mãe?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Pelo tempo que o filho de Jessé viver sobre a terra, nem tu nem o teu reino serão estabelecidos. Agora, traga-o para mim, porque ele certamente morrerá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Jônatas respondeu a Saul, seu pai: \"Por qual razão ele deveria morrer? O que ele fez?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Então, Saul atirou-lhe sua lança para matá-lo. Assim, Jônatas soube que seu pai estava determinado a matar Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Jônatas, tomado de raiva, levantou-se da mesa e não comeu da comida no segundo dia do mês, porque estava entristecido por Davi, pois seu pai o havia desonrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Pela manhã, Jônatas foi para o campo encontrar-se com Davi, e um jovem rapaz estava com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'E disse ao jovem rapaz: \"Corre e encontra as flechas que eu lancei\". Enquanto o jovem rapaz corria, ele lançou uma flecha para além dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Quando o jovem rapaz chegou ao local onde as flechas caíram, Jônatas chamou o jovem rapaz e lhe perguntou: \"A flecha não está para lá de ti?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'E Jônatas gritou para o jovem rapaz: \"Corre! Sê rápido! Não fique!\". Então, o jovem rapaz recolheu as flechas e voltou para o seu senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Mas ele não sabia de nada. Somente Jônatas e Davi sabiam do assunto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Jônatas deu suas armas ao jovem rapaz e disse-lhe: \"Vai, leva-as até a cidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Assim que o jovem rapaz partiu, Davi ficou em pé no lado do sul, prostou seu rosto no chão, e curvou-se três vezes. Eles se beijaram e lamentaram-se, mas Davi lamentava-se mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Jônatas disse a Davi: \"Vai em paz, porque juramos em nome de Yahweh, dizendo: \'Que Yahweh esteja entre mim e ti, e entre os meus e os teus descendentes para sempre\". Então, Davi levantou-se e partiu, e Jônatas retornou para a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Então, Davi veio a Nobe para ver Aimeleque, o sacerdote. Aimeleque veio, trêmulo, encontrar-se com Davi e lhe disse: \"Por que estás sozinho e não há ninguém contigo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'Davi disse a Aimeleque, o sacerdote: \"O rei me mandou em uma missão e disse-me: \'Não deixes que ninguém saiba sobre o negócio que eu estou te enviando, e o que te ordenei.\' Estou sozinho porque encaminhei os jovens para um certo lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Agora, o que tens nas mãos? Dá-me cinco fatias de pão, ou qualquer coisa que tiveres aí\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'O sacerdote respondeu a Davi e disse: \"Não há pão comum, porém há pão santo — se os jovens tiverem se privado de mulheres\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Davi respondeu ao sacerdote: \"Certamente estamos privados de mulheres durante estes três dias. Quando eu parti, os corpos dos jovens foram dedicados a Yahweh, ainda que fosse uma jornada comum. Quanto mais hoje seus corpos serão dedicados a Yahweh?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Então, o sacerdote lhe deu o pão que foi dedicado a Yahweh. Pois não havia pão ali, apenas o pão da presença, que foi removido de diante de Yahweh a fim de que se colocasse pão quente em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Um dos servos de Saul estava lá naquele dia, detido perante Yahweh. Seu nome era Doegue, o edomeu, o chefe dos pastores de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Davi disse a Aimeleque: \"Não haveria aqui alguma lança ou espada? Pois eu não trouxe nem minha espada nem minhas armas comigo, porque o negócio do rei era urgente\". O sacerdote disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, '\"A espada de Golias, o filisteu a quem tu mataste no vale de Elá, está aqui, embalada em um pano atrás do manto sacerdotal. Se tu quiseres levá-la, pega-a, pois não há outra arma aqui\". Davi disse: \"Não há outra espada como aquela; dá-me, pois.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Davi levantou-se e escapou de Saul naquele dia e foi a Áquis, o rei de Gate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Os servos de Áquis lhe disseram: \"Não é este Davi o rei da terra? Eles não cantaram uns para os outros sobre ele com danças: \'Saul matou seus milhares, e Davi seus dez milhares\'?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Davi levou essas palavras a sério e teve muito medo de Áquis, o rei de Gate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Ele mudou seu comportamento diante deles e fingiu ser louco nas mãos deles; e ele fez marcas nas portas e deixou que sua saliva escorresse por sua barba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Então Áquis disse a seus servos: \"Vós não vedes que o homem é louco? Por que vós o trouxestes para mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Teria eu necessidade de homens loucos para que vós trouxésseis este indivíduo para agir como um em minha presença? Este indivíduo realmente entrará na minha casa?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Depois disso, Davi saiu dali e se escondeu na caverna de Adulão. Ao ouvirem isso, seus irmãos e toda a casa de seu pai desceram para estar ali com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Todos os que estavam angustiados, todos os que estavam endividados e qualquer pessoa que estivesse descontente, todos se juntaram a Davi. Ele se tornou o capitão deles. Havia cerca de quatrocentos homens com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Davi, então, partiu dali e foi para Mispá, em Moabe. Ele disse ao rei de Moabe: \"Por favor, permite que meu pai e minha mãe permaneçam convosco até que eu saiba a vontade de Deus para mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Ele deixou seus pais ali com o rei de Moabe. Seu pai e sua mãe ficaram com o rei durante todo o tempo em que Davi esteve na fortaleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Depois disso, o profeta Gade disse a Davi: \"Não fiques na tua fortaleza. Sai daí e vá até a terra de Judá\". E Davi saiu daquele lugar e foi até a floresta de Herete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Saul ficou sabendo que alguém descobriu onde Davi e seus homens estavam. Naquele momento, Saul se encontrava sentado debaixo de um tamarindeiro, em Gibeá, com sua lança na mão, na região de Ramá, e todos os seus servos estavam ao seu redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Saul disse a eles: \"Ouve, povo de Benjamim! Porventura, o filho de Jessé dará a cada um de vós campos e vinhas? Ele será capaz de fazer de vós todos capitães de milhares e de centenas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'em troca de tudo o que vós estais tramando contra mim? Nenhum de vós me informa quando meu filho firma um pacto com o filho de Jessé. Ninguém de vós sente compaixão por mim; ninguém de vós me informa que meu filho tem incitado meu servo Davi contra mim. Hoje ele se esconde e espera para poder me atacar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Então respondeu Doegue, o edomita, que se encontrava ao lado dos servos de Saul: \"Vi o filho de Jessé ir até Nobe, a Aimeleque, filho de Aitube.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Ele orou a Yahweh pedindo por ajuda e Ele lhe concedeu suprimentos e lhe deu a espada de Golias, o filisteu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Depois disso, o rei enviou alguém para buscar o sacerdote Aimeleque, filho de Aitube, e todos os que pertenciam à casa de seu pai, os sacerdotes que estavam em Nobe. Todos vieram até o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Disse Saul: \"Ouve agora, filho de Aitube\". Ao que ele respondeu: \"Aqui estou, meu senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Saul lhe disse: \"Por que razão tu e o filho de Jessé maquinastes o mal contra mim? Deste-lhe pão, a espada de Golias e ainda pediste a Deus para que Ele se levantasse contra mim, escondendo-se como ele faz hoje?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Aimeleque respondeu ao rei, dizendo: \"Quem entre seus servos é tão fiel a ti como Davi, genro do rei, e que está sobre tua guarda, e é honrado na vossa casa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Por acaso, esta é a primeira vez, hoje, que orei a Deus para ajudá-lo? Longe de mim tal coisa! Que o rei não atribua tal coisa a seus servos ou a toda casa de meu pai, porque vossos servos desconhecem tal assunto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'O rei retrucou: \"Tu certamente morrerás, Aimeleque; não somente tu, mas toda a casa de teu pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'O rei disse ao guarda que estava do lado dele: \"Tornai e matai os sacerdotes de Yahweh, porque suas mãos estão também com Davi, e porque eles sabiam que ele escapou, mas não me informaram isso\". Porém, os servos do rei recusaram-se a estender suas mãos para ferirem os sacerdotes de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'O rei, então, disse a Doegue: \"Tornai e matai os sacerdotes\". Doegue, o edomita, virou-se e atacou os sacerdotes. Naquele dia, ele matou oitenta e cinco pessoas que usavam o manto sacerdotal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Ao fio da espada, ele atacou Nobe, a cidade dos sacerdotes, matando homens, mulheres, crianças, crianças de colo, bois, jumentos e ovelhas. Ele matou a todos ao fio da espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Porém, um dos filhos de Aimeleque, filho de Aitube, chamado Abiatar, conseguiu escapar e fugiu para onde estava Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Abiatar contou a Davi que Saul havia assassinado os sacerdotes de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Davi disse a Abiatar: \"Naquele dia, quando Doegue, o edomita, estava ali, eu sabia que, com toda a certeza, ele iria contar tudo a Saul. Sou responsável por cada uma das mortes na família de teu pai!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Permaneça aqui comigo e não tenhas medo, pois quem buscar destruir tua vida vai fazer o mesmo com a minha. Tu estarás seguro comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Disseram a Davi: \"Vê, os filisteus estão lutando contra Queila e estão saqueando as eiras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Então Davi clamou a Yahweh por ajuda e perguntou-Lhe: \"Devo ir e atacar esses filisteus?\". Yahweh disse a Davi: \"Vai, ataca os filisteus e salva o povo de Queila\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Os homens de Davi disseram a ele: \"Vê, estamos amedrontados aqui em Judá. Quanto mais, então, ficaremos se formos para Queila contra o exército dos filisteus?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Então Davi novamente clamou a Yahweh por ajuda, Yahweh respondeu-lhe: \"Levanta-te e desce a Queila, pois Eu te darei vitória sobre os filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Davi e seus homens foram a Queila e lutaram contra os filisteus. Conduziram os rebanhos deles e atacaram-nos com grande matança. Assim, Davi salvou os habitantes de Queila.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Quando Abiatar, filho de Aimeleque, fugiu para encontrar Davi em Queila, veio com um manto sacerdotal em suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Foi dito a Saul que Davi havia partido para Queila. Saul disse: \"Deus o entregou nas minhas mãos. Ele está confinado, pois entrou numa cidade que tem portões e trancas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Saul convocou todos do seu exército para o combate, em direção a Queila, para cercar Davi e seus homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Davi sabia que Saul estava conspirando o mal contra ele. Então, disse ao sacerdote Abiatar: \"Traze aqui o manto sacerdotal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Davi disse: \"Yahweh, Deus de Israel, de fato o Teu servo tem ouvido que Saul busca vir a Queila, para destruir a cidade por minha causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Será que os homens de Queila me entregarão em suas mãos? Será que Saul descerá, conforme Teu servo tem ouvido? Yahweh, Deus de Israel, Te imploro, agrada-Te em falar com Teu servo\". Yahweh disse: \"Ele descerá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Assim, disse Davi: \"Será que os homens de Queila entregarão a mim e a meus homens nas mãos de Saul?\". Yahweh disse: \"Eles vos entregarão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Davi e seus homens, que eram cerca de seiscentos, levantaram-se e saíram de Queila, e iam de lugar em lugar. Foi dito a Saul que Davi havia escapado de Queila; então, ele parou de persegui-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Davi permaneceu em lugares seguros no deserto, numa região montanhosa do deserto de Zife. Saul procurava por ele todos os dias, mas Deus não o entregava em suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Davi percebeu que Saul havia saído a fim de tirar-lhe a vida; nesse momento, Davi estava no deserto de Zife, em Horesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Então, Jônatas, filho de Saul, levantou-se e foi até Davi em Horesa e o fortaleceu em Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Ele lhe disse: \"Não temas! Pois as mãos do meu pai, Saul, não te encontrarão. Serás rei sobre Israel, e eu estarei próximo a ti. Saul, meu pai, também sabe disso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Fizeram eles um pacto diante de Yahweh. Davi permaneceu em Horesa, e Jônatas foi para casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Os Zifeus vieram a Saul em Gibeá e disseram: \"Não está Davi escondido entre nós no forte de Horesa, no monte de Haquila, no sul de Jesimom?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Agora desce, rei! De acordo com teu desejo, desce! Nossa parte será entregá-lo nas mãos do rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Disse Saul: \"Sede abençoados por Yahweh, pois tivestes compaixão de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Ide, certificai-vos. Informai-vos e descobri onde está seu lugar escondido e quem o viu lá. Tenho sido informado de que ele é muito astuto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Então, vede e tomai cohecimento de todos os lugares onde ele se esconde. Voltai a mim com a informação certa, e, então, eu retornarei convosco. Se ele estiver na terra, eu o buscarei entre todos os milhares de Judá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Então, levantaram-se e foram a Zife, adiante de Saul. Ora, Davi e seus homens estavam no deserto de Maom, em Arabá, no sul de Jesimom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Saul e seus homens saíram em busca dele. E foi dito a Davi sobre isso; então, ele desceu para um monte rochoso e habitou no deserto de Maom. Quando Saul soube disso, perseguiu Davi no deserto de Maom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Saul ia por um lado da montanha, enquanto Davi e seus homens iam por outro lado. Davi se apressava para fugir de Saul. Enquanto Saul e seus homens estavam cercando Davi e seus homens para pegá-los,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'um mensageiro veio a Saul e disse: \"Apressa-te e vem, pois os filisteus atacaram repentinemante contra a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Assim, Saul retornou da perseguição a Davi e saiu contra os filisteus. Por isso, aquele lugar é chamado de Rocha de Fuga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, 'Davi subiu e habitou nos lugares seguros de En-Gedi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'Quando Saul retornou da caçada aos filisteus, foi dito a ele: \"Davi está no deserto de En-Gedi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Então, Saul pegou três mil homens, escolhidos de todo o Israel, e foi em busca de Davi e seus homens, nas rochas das cabras selvagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'No caminho, ele veio para o cercado das ovelhas, onde havia uma caverna. Saul foi à parte interna para se aliviar. Davi e seus homens estavam assentados no interior da caverna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'Os homens de Davi disseram a ele: \"Este é o dia sobre o qual Yahweh falou quando te disse: \'Entregarei teu inimigo nas tuas mãos, farás com ele o que quiseres\". Então, Davi se levantou e, silenciosamente, avançou e cortou a ponta do manto de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Logo após isso, o coração de Davi ficou aflito, porque ele cortou a ponta do manto de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'Ele disse aos seus homens: \"Que Yahweh me impeça de fazer alguma coisa ao meu mestre, ungido de Yahweh, para estender a minha mão contra ele, sabendo que ele é o ungido de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Assim, Davi repreendeu seus homens com estas palavras e não permitiu que eles atacassem Saul. Este se levantou, saiu da caverna e seguiu seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Mais tarde, Davi também se levantou, saiu da caverna e gritou por Saul: \"Meu senhor, o rei\". Quando Saul olhou para trás, Davi se inclinou com o rosto na terra e demonstrou respeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Davi disse a Saul: \"Por que tens escutado teus homens que dizem: \'Vê, Davi está procurando fazer-te mal?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Hoje, teus olhos estão vendo como Yahweh te colocou em minhas mãos, quando estávamos na caverna. Alguns me disseram para matar-te, mas te poupei. Eu disse: \'Não usarei minhas mãos contra meu senhor, pois ele é ungido de Yahweh\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Observa, meu pai! Vê a ponta do teu manto em minhas mãos. É verdade que cortei a ponta do teu manto e não te matei. Podes ver e saber que não há mal ou transgressão em minhas mãos; não cometi pecado contra ti, ainda que procuraste tirar a minha vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Que Yahweh julgue entre mim e ti, e Yahweh me vingue contra ti; porém, minhas mãos não deverão ser contra ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Conforme o provérbio dos antigos, que diz: \'Do mal, vem a maldade\'. Mas minha mão não será contra ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'À procura de quem o rei de Israel tem estado? Quem tu persegues? Um cachorro morto! Uma pulga!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Que Yahweh seja o juiz e julgue entre mim e ti, examine esta questão, defenda a minha causa e me permita escapar da tua mão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Quando Davi terminou de falar essas palavras, Saul disse: \"Esta é a tua voz, meu filho Davi?\". Saul levantou a voz e chorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'Ele disse a Davi: \"Tu és mais justo que eu, pois tens me retribuído com o bem pelo mal que te tenho feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'Declarastes hoje como tens sido bom para mim, pois não me mataste quando Yahweh colocou-me em tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Que homem encontra seu inimigo e o deixa ir em segurança? Que Yahweh te recompense com a bondade que tivestes comigo hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Agora sei que, certamente, serás rei e que o reino de Israel será estabelecido em tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Jura-me por Yahweh que não eliminarás meus descedentes depois de mim, e que não destruirás meu nome da casa do meu pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Então, Davi fez uma promessa a Saul. Em seguida, Saul foi para casa, mas Davi e seus homens seguiram para o lugar seguro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Samuel morreu. Todo o Israel se juntou, chorou por ele e o enterrou em sua casa, em Ramá. Então, Davi se levantou e desceu para o deserto de Parã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Havia um homem em Maom, cujos bens estavam em Carmelo. Ele era muito rico. Tinha três mil ovelhas e mil cabras. Ele estava tosquiando suas ovelhas em Carmelo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Seu nome era Nabal e o de sua esposa, Abigail. A mulher era inteligente e de boa aparência. Mas o homem era rude e cruel no trato. Ele era um descendente da casa de Calebe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Ouvindo Davi, no deserto, que Nabal estava tosquiando suas ovelhas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'enviou dez jovens e lhes disse: \"Subi ao Carmelo, ide a Nabal, e cumprimentai-o em meu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'Direis a ele: \'Vive em prosperidade. Paz para ti, paz para tua casa e paz seja para tudo o que tens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Sei que tu tens tosquiadores. Teus pastores estiveram conosco e nós não lhes causamos danos. Eles não perderam nada em todo o tempo em que estiveram em Carmelo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Pergunta aos teus jovens e eles te contarão. Agora, deixa meus jovens acharem favor aos teus olhos, pois viemos em um dia festivo. Por favor, dá alguma coisa que tens em mãos para teus servos e teu filho Davi\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Quando os jovens de Davi chegaram, disseram tudo isso em nome de Davi e aguardaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Nabal respondeu aos servos de Davi: \"Quem é Davi? Quem é esse filho de Jessé? Existem tantos servos que escapam de seus senhores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Eu deveria pegar o meu pão, minha água e a carne dos animais que matei para meus tosquiadores e dar a um homem que não sei de onde vem?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Então, os jovens de Davi se viraram, voltaram e contaram a ele tudo quanto foi dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Davi disse a seus homens: \"Todo vós, homens, embainhai vossas espadas\". E cada homem embainhou a sua espada. E Davi também embainhou a dele. Quatrocentos homens seguiram Davi e duzentos ficaram perto das bagagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Mas um dos jovens contou a Abigail, a esposa de Nabal, dizendo: \"Davi enviou mensageiros de fora do deserto para cumprimentar nosso senhor, e ele os ofendeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Porém, o homem foi muito bom para nós. Ele não nos causou dano e não perdemos nada em todo o tempo em que estiveram conosco, quando estávamos nos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Eles foram uma fortaleza para nós, tanto de dia quanto de noite, todo o tempo enquanto estivemos com eles, tosquiando as ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Portanto, sabe disso e considera o que irás fazer, pois foi tramado o mal contra nosso mestre e toda a sua casa. Ele é tão desonrado que ninguém o convence\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Então, Abigail se apressou e pegou duzentos pães, duas garrafas de vinho, cinco ovelhas preparadas, cinco medidas de trigo tostado, cem cachos de uva, duzentos bolos de figo e pôs sobre os jumentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Disse a seu jovem: \"Vai à minha frente, que eu vou atrás\". Mas ela não disse nada a seu marido Nabal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Enquanto ela montava em seu jumento e descia pela curva da montanha, Davi e seus homens vieram em sua direção e ela os encontrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Davi disse: \"Certamente, não adiantou eu ter guardado todas os pertences desse homem no deserto. Nada foi perdido de tudo quanto lhe pertencia, e me retornou o bem com o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Que Deus castigue severamente a mim, Davi, se, pela manhã, eu deixar vivo um só homem que pertencer a ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Quando Abigail avistou Davi, rapidamente, desceu de seu jumento e se prostrou diante dele, com o rosto em terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Aos seus pés, ela lhe disse: \"Apenas eu, meu senhor, seja a culpada. Por favor, deixa tua serva lhe falar e ouve as palavras de tua serva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Meu senhor, desconsidera esse homem sem honra, Nabal. Como é o seu nome, assim ele é: um tolo. Mas tua serva nem sequer viu seus homens, meu senhor, os que foram enviados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Agora, então, meu senhor, como Yahweh vive, e, como meu senhor vive desde que Yahweh te conteve de derramar sangue, e de vingar-te com tuas próprias mãos, tornem-se como Nabal teus inimigos e aqueles que buscam fazer-te mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'E, agora, aceita os presentes que tua serva trouxe para meu senhor. Que sejam dados aos jovens, os quais são companheiros de meu senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Por favor, perdoa a intromissão de tua serva. Yahweh certamente fará uma casa firme a meu senhor, porque meu mestre tem lutado as guerras de Yahweh; e o mal não te encontrará enquanto viveres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'E, se surgir algum homem que o persiga para tomar sua vida, a vida de meu mestre será atada a um feixe dos que vivem por Yahweh, nosso Deus; e Ele lançará para longe a vida dos teus inimigos, como uma pedra lançada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'E irá suceder que, quando Yahweh tiver cumprido para meu senhor todas as coisas boas, as quais Ele tem prometido a ti, e, quando Ele fizer de ti o líder sobre todo o Israel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'essas coisas não serão tristes para ti. Também não guardarás arrependimento do meu senhor, por ter derramado sangue sem causa, e por ter te vingado por ti mesmo. E, quando Yahweh tiver trazido sucesso a meu senhor, lembra-te de tua serva\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Davi disse a Abigail: \"Yahweh, o Deus de Israel, seja bendito! Ele te enviou a meu encontro hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'E bendita seja tua sabedoria, e tu sejas abençoada, porque me impedistes de pecar derramando sangue, e vingar-me com minhas próprias mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Verdadeiramente, como Yahweh vive, o Deus de Israel, que me impediu de ferir-te, a menos que tu não houvesses te apressado para vir ao meu encontro, certamente não teria deixado nenhum dos de Nabal, nem os bebês teriam sobrevivido pela manhã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Então, Davi recebeu de suas mãos o que ela trouxera para ele. E lhe disse: \"Vai em paz para tua casa. Vê, eu ouvi o teu pedido e o aceitei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Abigail voltou para Nabal. Ele estava fazendo um banquete em sua casa. Banquete como de um rei. O seu coração estava alegre, pois ele estava muito bêbado. Assim, ela não lhe contou nada até o amanhecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Sucedeu que, pela manhã, quando o vinho saiu de Nabal, sua esposa lhe contou o que havia acontecido. Seu coração morreu dentro dele e se tornou como uma pedra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Dez dias depois, Yahweh feriu Nabal e ele morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'E, quando Davi ouviu que Nabal estava morto, disse: \"Yahweh sê bendito, que tomou a causa do meu insulto vindo de Nabal, e livrou o teu servo de fazer o mal. E trouxe sobre a própria cabeça de Nabal a sua má ação\". Então, Davi enviou servos, que falaram a Abigail que ele desejava tomá-la como sua esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Quando os servos de Davi foram a Abigail em Carmelo, eles lhe disseram: \"Davi nos enviou a ti para que ele a tome como sua esposa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Ela se ajoelhou, prostrou-se com o rosto sobre a terra e disse: \"Vê, sou serva. Uma serva para lavar os pés dos servos de meu senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Abigail, rapidamente, montou seu jumento, com cinco jovens servas que a acompanhavam; e ela seguiu os mensageiros que Davi enviara e se tornou sua esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Davi também havia se casado com Ainoã de Jezreel; ambas se tornaram suas esposas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'porque Saul havia dado Mical, sua filha, esposa de Davi, para Palti, filho de Laís, que era de Galim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Os zifeus vieram a Saul, em Gibeá, dizendo: \"Não está Davi se escondendo no monte Haquila, que está diante de Jesimon?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Então, Saul levantou-se e foi para o deserto de Zife; havia com ele três mil homens, escolhidos de Israel, para procurar por Davi, no deserto de Zife.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Saul acampou no monte Haquila, que está diante de Jesimon, à beira da estrada. Porém, Davi estava no deserto, e viu que Saul vinha após ele pelo deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Davi enviou espias ao deserto e compreendeu que, de fato, Saul vinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Davi levantou-se e foi para o local onde Saul estava acampado; ele viu onde estavam deitados Saul e Abner, filho de Ner, o general de seu exército; Saul estava deitado, e o povo estava acampado ao seu redor; todos estavam adormecidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Então, Davi disse a Aimeleque, o heteu, e a Abisai, filho de Zeruia, irmão de Joabe: \"Quem descerá comigo ao acampamento de Saul?\". Abisai respondeu: \"Eu descerei contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Davi e Abisai desceram, à noite, ao acampamento: e lá estava Saul, dormindo, sua lança cravada no chão ao lado de sua cabeça. Abner e seus soldados estavam deitados ao seu redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Então, Abisai disse a Davi: \"Hoje, Deus colocou teu inimigo em tuas mãos. Agora, por favor, me permita encravá-lo ao chão com minha lança, com apenas um golpe. Não será necessário um segundo golpe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Davi disse a Abisai: \"Não o destruas, pois quem pode estender a sua mão contra o ungido de Yahweh e ficar inocente?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Davi continuou: \"Assim como Yahweh vive, Yahweh o matará; ou chegará o dia de sua morte, ou ele irá a batalha e perecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Que Yahweh não me permita estender minha mão contra o Seu ungido; mas, agora, eu te rogo: peguemos a lança que está ao lado de sua cabeça e a jarra de água, e saiamos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'E Davi pegou a lança e o jarro de água que estavam ao lado da cabeça de Saul, e saíram. Ninguém os viu ou soube que estiveram ali. Todos estavam adormecidos porque um profundo sono, da parte de Yahweh, viera sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Então, Davi foi para o outro lado do acampamento e ficou de pé no topo de uma montanha, ao longe; havia uma grande distância entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Davi gritou para o povo e para Abner, filho de Ner, dizendo: \"Não responderás, Abner?\" Então Abner respondeu dizendo: \"Quem és tu, que gritas ao rei?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Davi disse a Abner: \"Não és tu um homem corajoso? Quem é semelhante a ti em Israel? Por que, então, não vigiaste teu mestre, o rei? Pois alguém veio para matar o rei, teu mestre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Não é bom o que fizeste. Como vive Yahweh, tu mereces morrer, por não protegeres o teu mestre, o ungido de Yahweh. Agora, vê onde está a lança do rei, e a jarra de água que estavam ao lado de sua cabeça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Saul reconheceu a voz de Davi e disse: \"Esta é sua voz, meu filho Davi?\". Davi respondeu: \"Esta é a minha voz, meu mestre, rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Ele disse: \"Por que meu mestre persegue seu servo? O que tenho feito? Que maldade há em minhas mãos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Agora, pois, eu rogo que meu mestre ouça as palavras de seu servo. Se foi Yahweh que o enviou contra mim, que Ele aceite uma oferta; mas se foram homens, que eles sejam amaldiçoados em sinal de Yahweh, pois eles têm me lançado fora, para que eu não suba à herança de Yahweh, como que dizendo: \'Vai e adora outros deuses\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Agora, pois, não permitas que meu sangue se derrame pela terra, longe da presença de Yahweh; pois o rei de Israel tem saído em busca de uma pulga, como um caçador procura uma perdiz nas montanhas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Então Saul disse: \"Tenho pecado. Volta, meu filho Davi, pois não te farei mais mal, porque hoje tu preservaste minha vida. Vê, tenho agido como um tolo e cometido grande e terrível erro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Davi respondeu: \"Vê, tua lança está aqui, rei! Envia um dos jovens para buscá-la e te entregar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Que Yahweh pague a cada homem por sua justiça e fidelidade; porque Ele te colocou hoje em minhas mãos, mas eu não feriria o Seu ungido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'E vê, assim como tua vida foi preciosa aos meus olhos hoje, assim também tem a minha vida mais valor aos olhos de Yahweh, e que Ele me livre de todos os problemas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Então Saul disse a Davi: \"Sejas abençoado, Davi, meu filho, para que faças grandes coisas, e que tenhas sucesso\". Então, Davi seguiu seu caminho, e Saul retornou para o seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Davi disse em seu coração: \"Algum dia perecerei pela mão de Saul; não há melhor escolha do que fugir para a terra dos filisteus; Saul desistirá de me procurar nos arredores de Israel; assim, escaparei de sua mão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Davi levantou-se e saiu — ele e os seiscentos homens que o acompanhavam — para Áquis, filho de Maoque, o rei de Gate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Davi habitou em Gate — ele e seus homens, cada homem com toda a sua casa, e Davi com suas duas esposas, Aionã, a jezreelita, e Abigail a carmelita, esposa de Nabal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Saul, sendo informado de que Davi havia fugido para Gate, não o procurou mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Davi disse a Áquis: \"Se encontrei favor aos teus olhos, dá-me um lugar em uma das cidades do país, para que lá eu possa habitar. Por que deveria o teu servo habitar na cidade real contigo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Então, Áquis lhe deu Ziclague naquele dia; por isso, Ziclague pertence aos reis de Judá até estes dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'O tempo em que Davi habitou na terra dos filisteus foi de um ano e quatro meses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Davi e seus homens atacaram vários lugares; saquearam os gezuritas, e os amalequitas, pois estas nações eram os habitantes da terra, conforme se vai para Sur, tão longe quanto a terra do Egito. Eles habitavam nessa terra desde o tempo dos anciãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Davi atacou a terra e não poupou a vida de homens nem de mulheres; ele tomou as ovelhas, o gado, os jumentos, os camelos e as roupas. Ele atacava e retornava a Áquis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Áquis perguntava: \"Contra quem atacastes hoje?\". Davi respondia: \"Contra o sul de Judá\", ou \"Contra o sul dos jerameleus\", ou \"Contra o sul dos queneus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Davi não manteria vivos nem homens, nem mulheres para trazê-los a Gate, dizendo: \"Assim, não poderão dizer de nós: \'Davi fez assim e assim\'\". Fez isto durante todo o tempo em que morou no país dos filisteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Áquis acreditava em Davi, pois dizia: \"Ele tem feito com que seu povo em Israel o odeie; assim, ele será meu servo para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Aconteceu naqueles dias que os filisteus juntaram os seus exércitos para lutar contra Israel. Áquis disse a Davi: \"Certamente tu sabes que sairás a lutar comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Davi disse a Áquis: \"Saberás tu o que teu servo pode fazer\". Áquis disse a Davi: \"Então, eu irei, permanentemente, fazer de ti meu guarda pessoal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Samuel estava morto; todo o Israel estava se lamentando por ele; sepultaram-no em Ramá, cidade de seu nascimento. Ora, Saul havia expulsado da terra aqueles que haviam falado com os mortos, ou com os espíritos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Os filisteus ajuntaram-se e vieram acampar em Suném; e Saul reuniu todo o Israel, e acamparam-se em Gilboa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Quando Saul viu o exército dos filisteus, ele ficou com medo, e seu coração se afligiu muito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Saul orou a Yahweh por socorro; no entanto, Yahweh não lhe respondeu— nem por sonhos, nem por Urim, nem por profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Portanto, Saul disse aos seus servos: \"Encontrai-me uma mulher que fale com os mortos, para que eu vá até ela e busque seus conselhos\". Seus servos disseram-lhe: \"Vê, em En-Dor há uma mulher que fala com os mortos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Saul disfarçou-se, vestindo outra roupa, e foi — ele estava com dois dos seus homens. Eles foram ao anoitecer ao encontro da mulher. Disse-lhe: \"Adivinha para mim, peço-te, fala tu com os mortos e faze subir o nome que eu der a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'A mulher disse-lhe: \"Vê, sabes tu o que Saul fez: ele baniu da terra todos os que falam com os mortos ou com os espíritos. Então, por que preparas uma armadilha para minha vida, para me fazer morrer?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Saul jurou-lhe por Yahweh e disse-lhe: \"Assim como Yahweh vive, nenhuma punição te acontecerá por estas coisas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Então, a mulher perguntou-lhe: \"Quem devo fazer subir até ti? Disse-lhe Saul: \"Faze subir Samuel até mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Quando a mulher viu Samuel, ela gritou em alta voz e perguntou a Saul: \"Por que tu me enganaste? Pois tu és Saul\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'O rei disse-lhe: \"Não tenhas medo. O que tu vês?\". A mulher disse a Saul: \"Eu vejo um deus que vem subindo de dentro da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Perguntou-lhe Saul: \"Como ele é?\" Ela disse: \"Um homem velho está vindo; ele está vestido com um manto\". Saul entendeu que era Samuel, e curvou-se com a face no chão, mostrando respeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'O homem velho disse: \"Por que me perturbas e faze-me subir?\". Saul respondeu: \"Estou muito angustiado, pois os filisteus guerreiam contra mim. E Deus afastou-se de mim e não mais me responde, nem por profetas, nem por sonhos. Por este motivo, te chamei, para que me faças saber o que devo fazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Disse-lhe o homem velho: \"Por que me perguntas, uma vez que Yahweh afastou-se de ti, e tornou-se teu inimigo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Fez Yahweh o que disse que faria. Yahweh tem rasgado o reino de tuas mãos e tem entregue a alguém —a Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Porque não obecedeste à voz de Yahweh e não fizeste o que Ele, no ardor da Sua ira, ordenou contra Amaleque. Assim, Ele te fez isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Yahweh tirará a Sua mão sobre Israel e a colocará sobre os filisteus. Amanhã, tu e teus filhos estarão comigo. Yahweh entregará o exército de Israel nas mãos dos filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Então, Saul imediatamente prostrou-se no chão e foi tomado de medo ao ouvir essas palavras. Não houve força nele, pois ele não havia comido nenhum alimento o dia inteiro, nem a noite inteira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'A mulher foi a Saul e viu que ele ficou muito perturbado; ela lhe disse: \"Vê, tua serva ouviu a tua voz e, colocando a minha vida em perigo, fiz o que tuas palavras me disseram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Agora, pois, eu te imploro, ouve a voz de uma mulher serva, e deixa-me preparar um pouco de comida para ti. Come para que possas ter força quando fores em teu caminho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Porém, Saul recusou e lhe disse: \"Não comerei\". No entanto, seus servos, juntos com a mulher, convenceram-no, e ele os ouviu. Então, ele levantou-se do chão e sentou-se na cama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'A mulher tinha um novilho gordo em casa; ela apressou-se e o matou; tomando a farinha e o fermento, os amassou e cozeu o pão com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Ela os trouxe diante de Saul e de seus servos, e eles comeram. Então, eles se levantaram e saíram naquela noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Os filiteus recolheram todo o seu exército em Afeque; os israelistas acamparam-se junto à fonte que estava em Jezreel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Os príncipes dos filisteus passaram por centenas e milhares; Davi e seus homens passaram na retaguarda com Áquis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Então, os príncipes dos filisteus disseram: \"O que esses hebreus estão fazendo aqui?\". Áquis disse para os outros príncipes dos filisteus: \"Não é este Davi, servo de Saul, o rei de Israel, que tem estado comigo nestes dias, ou nestes anos, e em quem eu não tenho encontrado nenhuma culpa desde que ele veio a mim até hoje?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Mas os príncipes dos filisteus estavam zangados com ele; eles lhe disseram: \"Faze este homem ir embora, que ele vá de volta para o lugar que tu lhe deste; não deixes que ele vá conosco na batalha, de modo que ele não se torne um inimigo para nós durante a batalha. Por quanto mais poderia esse homem fazer as pazes com seu mestre? Não estaria com a cabeça dos nossos homens?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Não é este o Davi de quem cantam um ao outro em danças, dizendo: \'Saul feriu os seus milhares, e Davi os seus dez milhares?\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Então, Áquis chamou Davi e lhe disse: \"Como Yahweh vive, tu tens sido bom, e, no meu ponto de vista, a tua saída e a tua entrada comigo no exército é boa; pois não encontro nada de errado contigo desde o dia em que vieste a mim até hoje. Todavia, os príncipes não são favoráveis a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Então, retorna e vai em paz, para que não desagrades os príncipes dos filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Davi disse a Áquis: \"Mas o que eu tenho feito? O que encontraste em teu servo desde o dia em que eu vim ter contigo até este dia, que eu não possa ir e lutar contra os inimigos do meu senhor rei?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Áquis respondeu, dizendo: \"Eu sei que tu és tão irrepreensível diante dos meus olhos quanto um anjo de Deus, embora os príncipes dos filisteus tenham dito, \'ele não deve ir conosco à batalha\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Então, levanta-te de manhã cedo, tu e os servos de teu mestre que vieram contigo; assim que estiveres levantado de manhã cedo, quando tiver luz, ide embora\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Então, Davi levantou-se cedo, ele e os homens, para, de manhã, retornarem à terra dos filisteus. Mas os filisteus foram para Jezreel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'E aconteceu que, quando Davi e os homens dele chegaram a Ziclague, no terceiro dia, os amalequitas haviam invadido Neguebe e Ziclague. Eles atacaram Ziclague, queimando-a;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'e capturaram as mulheres e todos os outros que estavam lá, do menor ao maior. Eles não mataram ninguém, mas os levaram para fora e seguiram seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Quando Davi e seus homens chegaram à cidade, ela estava queimada— e suas esposas, filhos e filhas foram levados cativos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Então, Davi e o povo que estava com ele ergueram suas vozes e choraram até não terem mais forças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'As duas mulheres de Davi foram levadas, Ainoã a jezreelita e Abigail a esposa de Nabal, o carmelita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Davi estava em grande angústia, pois o povo estava falando sobre apedrejá-lo, porque o espírito de todos estava entristecido, cada homem pelos seus filhos e filhas; mas Davi fortaleceu-se em Yahweh, seu Deus');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Davi disse a Abiatar filho de Aimeleque, o sacerdote: \"Eu te imploro, traze o manto sacerdotal aqui para mim\". Abiatar trouxe o manto sacerdotal a Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Davi orou a Yahweh por uma direção, dizendo: \"Se eu perseguir a esse bando, os alcançarei?\". Yahweh respondeu: \"Persegue-os, pois tu certamente os alcançarás, e certamente irás recuperar tudo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Então, Davi foi — ele e os seiscentos homens que estavam com ele; eles foram ao riacho de Besor, onde ficaram aqueles que foram deixados para trás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Mas Davi continuou a perseguição, ele e quatrocentos homens, pois duzentos deles haviam ficado para trás — os que eram tão fracos que não podiam ir além do riacho de Besor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Eles acharam um egípcio em um campo e o trouxeram a Davi; eles lhe deram pão, e ele comeu; e lhe deram água para beber;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'e eles lhe deram um pedaço de bolo de figos e duas porções de uvas passas. Quando ele comeu, retomou a força, pois não havia comido nem pão e nem bebido água por três dias e três noites.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Davi lhe perguntou: \"A quem tu pertences? De onde vens?\". Ele disse: \"Eu sou um jovem homem do Egito, servo de um amalequita; meu mestre me deixou porque há três dias fiquei doente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Nós fizemos uma invasão no Neguebe dos queretitas, que pertence a Judá, e ao Neguebe de Calebe; e nós queimamos Ziclague\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Davi lhe disse: \"Irás me levar aos invasores\". O egípcio respondeu: \"Jura por Deus que não me matarás ou trairás, nem me mandarás para as mãos de meu mestre, e te levarei aos invasores\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Quando o egípcio levou Davi, os invasores estavam espalhados por todo o campo, comendo e bebendo, e dançando, por causa de todos os despojos que haviam pegado na terra dos filisteus e na terra de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Davi os atacou desde o crepúsculo até a tarde do dia seguinte. Nenhum homem escapou, exceto quatrocentos deles, que fugiram montados em camelos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Davi recuperou tudo o que os amalequitas levaram e resgatou suas duas esposas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Nada ficou perdido, nem o menor ou o maior, nem os filhos e as filhas, nem os despojos, nem mesmo o que os invasores pegaram para si mesmos. Davi trouxe tudo de volta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Davi pegou todos os rebanhos de gado e ovelhas. Eles os conduziam diante de Davi e diziam: \"Este é o despojo de Davi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Davi veio até os duzentos homens que, por serem fracos, não puderam seguir, ficando no riacho de Besor. Estes homens foram à frente para encontrar Davi e os que estavam com ele. Quando Davi aproximou -se, ele os cumprimentou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Então, todos os homens perversos e os companheiros inúteis entre aqueles que foram com Davi disseram: \"Porque estes homens não foram conosco, nós não lhes daremos nada dos despojos que nós recuperamos. Exceto que cada homem deve pegar sua esposa e suas crianças e levá-los para fora daqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Então disse Davi: \"Vós não deveis agir deste modo, meus irmãos, com o que Yahweh nos tem dado. Ele nos tem preservado e colocou em nossas mãos os invasores que vieram até nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Quem vos escutará nesta questão? Porque o que exigis para todos os que foram na batalha, também será exigido para todos os que guardaram os mantimentos; eles receberão a mesma porção\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'E foi assim desde aquele dia até o dia de hoje, pois Davi fez disso um estatuto e decreto para Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Quando Davi voltou a Ziclague, ele enviou alguns dos despojos aos anciãos de Judá, seus amigos, dizendo: \"Vede, aqui está um presente para vós dos despojos dos inimigos de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Para os anciãos que estavam em Betel, e para aqueles que estavam em Ramote do Sul, e para aqueles que estavam em Jatir,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'e para aqueles que estavam em Aroer, e para aqueles que estavam em Sifmote, e para aqueles que estavam em Estemoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'Também para os anciãos que estavam em Racal, e para aqueles que estavam nas cidades dos jerameelitas, e para aqueles que estavam na cidades dos queneus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'e para aqueles que estavam em Hormá, e para aqueles que estavam em Corasã, e para aqueles que estavam em Atace,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'e para aqueles que estavam em Hebrom, e para todos os lugares onde o próprio Davi e seus homens costumavam ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Ora, os filisteus lutaram contra Israel. Os homens de Israel fugiram de diante dos filisteus e caíram mortos no monte Gilboa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Os filisteus perseguiram, de perto, Saul e seus filhos. Eles mataram Jônatas, Abinadabe e Malquisua, filhos de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'A batalha contra Saul foi severa, e os arqueiros o acertaram. Ele estava com fortes dores por causa deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Então, Saul disse ao seu escudeiro: \"Tira tua espada e golpeia-me com ela. Caso contrário, estes incircuncisos virão e abusarão de mim\". Mas seu escudeiro não o fez, pois ele estava com muito medo. Então, Saul pegou sua própria espada e se jogou em cima dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Quando seu escudeiro viu que Saul estava morto, ele também se jogou sobre sua espada e morreu com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Assim, morreram Saul, seus três filhos e seu escudeiro — todos estes homens morreram juntos no mesmo dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Quando os homens de Israel, que estavam do outro lado do vale e do outro lado do Jordão, viram que os homens de Israel haviam fugido, e que Saul e seus filhos estavam mortos, eles abandonaram suas cidades e fugiram, e os filisteus vieram e habitaram nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'No dia seguinte, aconteceu que, quando os filisteus se aproximaram para despojar os mortos, estes encontraram Saul e seus três filhos caídos no monte Gilboa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Eles cortaram fora sua cabeça, despojaram sua armadura, e mandaram mensageiros por toda a terra dos filisteus para levar as notícias aos templos dos seus ídolos e para o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Eles colocaram a armadura dele no templo de Astarote e fixaram seu corpo na muralha da cidade de Bete-Seã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Quando os habitantes de Jabes-Gileade ouviram sobre o que os filisteus haviam feito com Saul,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'todos os homens de combate caminharam, por toda a noite, e pegaram o corpo de Saul e os corpos dos seus filhos da muralha de Bete-Seã. Eles voltaram para Jabes e, lá, os queimaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Então, eles pegaram seus ossos, os enterraram debaixo de uma tamareira, e jejuaram por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Depois da morte de Saul, Davi retornou do ataque aos amalequitas e permaneceu em Ziclague por dois dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'No terceiro dia, um homem veio do acampamento de Saul com suas roupas rasgadas e com pó sobre sua cabeça. Quando ele chegou até Davi, prostou-se com o rosto no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Davi disse-lhe: \"De onde vens?\". Ele respondeu: \"Eu escapei do acampamento de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Disse-lhe Davi: \"Por favor, dize-me o que ocorreu\". Ele respondeu: \"O povo fugiu da batalha. Muitos caíram e muitos estão mortos. Saul e Jônatas, seu filho, também estão mortos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Davi disse ao jovem: \"Como sabes que Saul e Jônatas, seu filho, estão mortos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'O jovem respondeu: \"Por coincidência, eu estava no Monte Gilboa, e lá Saul estava se apoiando sobre sua lança; carruagens e cavaleiros estavam quase o alcançando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Saul virou-se, viu-me e chamou-me. Eu respondi: \'Eis me aqui\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Ele me disse: \'Quem és tu?\'. Eu lhe respondi: \'Sou um amalequita\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Ele me disse: \'Por favor, aproxima-te e mata-me, pois estou em grande sofrimento, porém continuo vivo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Então, aproximei-me dele e o matei, pois eu sabia que ele não viveria depois de ter caído. Então, eu peguei a coroa que estava em sua cabeça e a faixa que estava em seu braço e as trouxe aqui para ti, meu mestre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Então, Davi rasgou suas roupas, e todos os homens que estavam com ele fizeram o mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Eles prantearam, choraram e jejuaram até o entardecer por Saul, por Jônatas filho de Saul, pelo povo de Yahweh e pela casa de Israel, por terem caído pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Davi disse ao jovem: \"De onde és?\". Ele respondeu: \"Sou filho de um estrangeiro amalequita\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Davi lhe disse: \"Por que não temeste matar o rei ungido de Yahweh com sua própria mão?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Davi chamou um dos jovens e disse: \"Vai e mata-o\". Então, aquele homem foi e o atingiu, e o amalequita morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Davi disse ao amalequita morto: \"Teu sangue está sobre tua cabeça, pois tua própria boca testificou contra ti e disse: \'Eu matei o rei ungido de Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Então, Davi cantou esta música fúnebre a respeito de Saul e Jônatas, filho de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'Ele ordenou que o povo ensinasse esta Canção do Arco aos filhos de Judá, a qual foi escrita no Livro de Jasar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, '\"Tua glória, Israel, está morta, assassinada em lugares altos! Como os poderosos caíram!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Não conteis isso em Gate, não o proclameis nas ruas de Asquelom, para que não regozijem as filhas dos filisteus, e as filhas dos incircuncisos não celebrem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Montanhas de Gilboa, que não haja orvalho nem chuva sobre vós, nem campos que deem grãos para ofertas, pois lá o escudo do poderoso foi profanado. O escudo de Saul não mais será ungido com óleo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Do sangue daqueles que foram mortos, dos corpos dos poderosos, o arco de Jônatas não recuou, e a espada de Saul não retornou vazia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul e Jônatas foram amados e graciosos em vida, e, em sua morte, não foram separados. Eles eram mais ágeis que águias, eram mais fortes que leões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Vós, filhas de Israel, chorai por Saul, que vos vestiu de luxuosas roupas escarlates, que colocou ornamentos de ouro em vossas vestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Como os poderosos caíram no meio da batalha! Jônatas foi morto nos lugares altos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Estou angustiado por ti, meu irmão Jônatas. Tu eras muito querido por mim. Teu amor era maravilhoso para mim, excedendo o amor de mulheres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Como os poderosos caíram, e as armas de guerra pereceram!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Depois disto, Davi perguntou a Yahweh e disse: \"Devo eu subir a uma das cidades de Judá?\". Yahweh o respondeu: \"Sobe”. Davi disse: \"Para qual cidade devo ir?\". Yahweh respondeu: \"Para Hebrom\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Então, Davi subiu com suas duas esposas, Ainoã de Jezreel, e Abigail a viúva de Nabal, o carmelita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Davi trouxe os homens que estavam com ele; cada um trouxe sua família, para as cidades de Hebrom, onde começaram a morar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Então, homens de Judá vieram e ungiram Davi rei sobre a casa de Judá. Eles falaram a Davi: \"Os homens de Jabes-Gileade enterraram Saul\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Então, Davi enviou mensageiros aos homens de Jabes-Gileade e disse a eles: \"Vós sois abençoados por Yahweh, já que mostrastes esta lealdade ao vosso senhor Saul, e o enterrastes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Agora, que Yahweh vos mostre Seu amor leal e Sua fidelidade. Eu também vos mostrarei esta bondade porque fizestes essa boa obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Agora, então, que vossas mãos sejam fortes; sede corajosos, pois Saul, vosso senhor, está morto, e a casa de Judá me ungiu rei sobre eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Mas Abner, filho de Ner, comandante do exército de Saul, tomou Isbosete, filho de Saul, e o trouxe para Maanaim;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'ele constituiu Isbosete rei sobre Gileade, Aser, Jezreel, Efraim, Benjamim e sobre todo o Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Isbosete, filho de Saul, tinha quarenta anos de idade quando começou a reinar sobre Israel, e reinou por dois anos. Todavia, a casa de Judá seguiu Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'O tempo em que Davi foi rei em Hebrom sobre a casa de Judá foi de sete anos e seis meses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Abner, filho de Ner, e os servos de Isbosete, filho de Saul, saíram de Maanaim para Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Joabe, filho de Zeruia, e os servos de Davi saíram e se encontraram perto do tanque de Gibeão. Ali, eles sentaram-se ao lado do tanque, um grupo de cada lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Abner disse a Joabe: \"Deixa os jovens se levantarem e competirem diante de nós\". Então, Joabe disse: \"Que se levantem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Então, os jovens levantaram-se e se reuniram: doze para Benjamim e Isbosete, filho de Saul, e doze dos servos de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Cada homem agarrou seu oponente pela cabeça e enfiou sua espada no lado do seu oponente, e eles caíram juntos. Assim, aquele lugar foi chamado, em hebraico, de \"Helcate-Hazurim\" ou \"Campo das Espadas\", que está em Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'A batalha foi muito severa naquele dia e Abner e os homens de Israel foram derrotados diante dos servos de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Os três filhos de Zeruia estavam ali: Joabe, Abisai, e Asael. Asael era rápido nos pés, como uma gazela selvagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Asael perseguiu de perto Abner e o seguiu sem se desviar nem para a direita e nem para a esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Abner olhou para trás e disse: \"És tu, Asael?\". Ele respondeu: \"Sou eu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Abner disse para ele: \"Desvia-te para tua direita ou para esquerda, e agarra um dos jovens e pega sua armadura\". Mas Asael não mudou de direção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Então, Abner disse novamente a Asael: \"Para de me perseguir. Por que eu deveria te derrubar ao chão? Como eu me apresentaria diante de Joabe, teu irmão?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Mas, Asael recusou-se a desviar e, então, Abner o apunhalou com a sua lança e ela atravessou-lhe o estômago. Asael caiu e ali morreu. E aconteceu que todos que chegavam ao lugar em que Asael caíra morto, ficavam parados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Mas Joabe e Abisai perseguiram Abner. Quando o sol estava se pondo, eles vieram para a colina de Amá, que é perto de Giá, próximo à estrada para o deserto de Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Os homens de Benjamim reuniram-se atrás de Abner e ficaram no topo da colina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Então, Abner chamou Joabe e disse: \"Será que a espada deve devorar para sempre? Tu não sabes que isto será amargo no final? Quanto tempo isto levará até que tu digas para teus homens pararem de perseguir seus irmãos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Joabe respondeu: \"Assim como Deus vive, se tu não tivesses dito isso, meus soldados teriam perseguido seus irmãos até pela manhã!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Então, Joabe tocou a trombeta, e todos os seus homens pararam e não mais perseguiram Israel, nem lutaram mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abner e seus homens viajaram toda aquela noite, por Arabá; eles cruzaram o Jordão, marcharam durante toda a manhã seguinte e, então, alcançaram Maanaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Joabe retornou da perseguição a Abner. Ele reuniu todos os seus homens, dos quais estavam faltando Asael e dezenove dos soldados de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Todavia, os homens de Davi mataram trezentos e sessenta homens de Benjamim, dentre os homens de Abner.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Então, eles pegaram Asael e o enterraram no túmulo de seu pai, que era em Belém. Joabe e seus homens viajaram toda a noite, e amanheceu-lhes o dia em Hebrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Então, houve uma longa guerra entre a casa de Saul e a casa de Davi. Davi se fortalecia mais e mais; todavia, a casa de Saul se enfraquecia cada vez mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Davi teve filhos em Hebrom. Seu primogênito foi Amnon, de Ainoã, a jezreelita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'seu segundo filho, Quileabe, de Abigail, que havia sido mulher de Nabal, o carmelita; o terceiro, Absalão, era filho de Maaca, filha de Talmai, rei de Gesur;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'o quarto filho de Davi, Adonias, filho de Hagite; o quinto filho era Sefatias, filho de Abital;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'e o sexto, Itreão, de Eglá, também mulher de Davi. Estes são os filhos de Davi que nasceram em Hebrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Aconteceu que, durante a guerra entre a casa de Saul e a casa de Davi, Abner tornou-se forte na casa de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Saul tinha uma concubina, cujo nome era Rizpa, filha de Aiá. Isbosete disse a Abner: \"Por que te deitaste com a concubina de meu pai?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Então, Abner ficou muito irritado com as palavras de Isbosete e disse-lhe: \"Sou eu um cão que pertence a Judá? Hoje eu estou mostrando fidelidade à casa de Saul, teu pai, teus irmãos e teus amigos, e não te entreguei nas mãos de Davi, e agora você me acusa sobre essa mulher?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Que Deus faça comigo muito pior, se eu não fizer por Davi como Yahweh jurou a ele:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'transferir o reino da casa de Saul e estabelecer o trono de Davi sobre Israel e sobre Judá, desde Dã até Berseba\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Isbosete não pôde responder a Abner mais nenhuma palavra, porque o temia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Então, Abner enviou mensageiros a Davi para lhe falarem, dizendo: \"De quem é a terra? Faz um pacto comigo, eu serei contigo e tu verás que minha mão estará contigo para trazer todo o Israel a ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Davi respondeu: \"Está bem, eu farei um pacto contigo; entretanto, uma coisa eu exijo de ti: não verás minha face, a menos que primeiro traga Mical, filha de Saul, quando tu vieres me ver\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Então, Davi mandou mensageiros para Isbosete, filho de Saul, dizendo: \"Dá-me minha mulher Mical, por quem eu paguei o preço de cem prepúcios de filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Assim, Isbosete mandou tirar Mical de seu marido, Paltiel, filho de Laís.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Seu marido foi com ela, chorando, ao longo do caminho, e seguiu-a até Baurim. Então, Abner lhe disse: \"Retorna para casa, agora\". Então, ele retornou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Abner falou com os anciãos de Israel, dizendo: \"No passado, vós queríeis fazer Davi reinar sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Agora, fazei isso. Porque o Senhor falou a Davi, dizendo: \'Pela mão do meu servo Davi, Eu livrarei o meu povo de Israel das mãos dos filisteus e das mãos de todos os vossos inimigos\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Abner também falou pessoalmente ao povo de Benjamim. Então, Abner também foi falar com Davi em Hebrom, para explicar tudo o que Israel e toda a casa de Benjamim haviam resolvido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Quando Abner e vinte de seus homens chegaram a Hebrom para ver Davi, ele havia preparado um banquete para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Abner expicou a Davi: \"Eu me levantarei e protegerei todo o Israel por ti, meu rei, de modo que eles façam um pacto contigo, para que tu reines sobre tudo o que desejares\". Assim, Davi dispensou Abner, e ele foi embora em paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Em seguida, os soldados de Davi e Joabe vieram de uma investida e trouxeram grande despojo com eles. Entretanto, Abner não estava com Davi, em Hebrom;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Davi o tinha dispensado, e Abner havia saído em paz. Quando Joabe e todo o exército chegaram, disseram a Joabe: \"Abner, filho de Ner, veio ao rei, o rei o dispensou e Abner saiu em paz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Então, Joabe foi ao rei e disse: \"O que fizeste? Vê, Abner veio a teu encontro! Por que o deixaste ir embora, e ele se foi?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Tu não sabes que Abner veio enganar-te para descobrir teus planos e saber tudo que estás fazendo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Quando Joabe deixou Davi, ele enviou mensageiros atrás de Abner, e o fizeram voltar do poço de Sira, mas Davi não sabia disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Quando Abner voltou a Hebrom, Joabe o levou à parte, no portão, para lhe falar em particular, e ali Joabe o esfaqueou no estômago e o matou. Dessa forma, Joabe vingou o sangue de Asael, seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Quando Davi ouviu a respeito disso, falou: \"Eu e meu reino somos inocentes perante Yahweh, para sempre, em relação ao sangue de Abner, filho de Ner.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Que a culpa da morte de Abner caia sobre a cabeça de Joabe e sobre toda a casa de seu pai. Que jamais deixe de haver na família de Joabe quem tenha feridas ou doenças de pele, ou quem seja manco e deva andar de muletas, ou quem seja morto pela espada, ou quem passe fome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Pois Joabe e Abisai, seu irmão, mataram Abner, porque ele havia matado seu irmão Asael na batalha em Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Davi disse a Joabe e a todo o povo que estava com ele: \"Rasgai vossas vestes, vesti-vos de sacos e chorai pelo corpo de Abner\". Então, o rei Davi seguiu após o caixão no funeral.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Sepultaram Abner em Hebrom. O rei chorou e gritou bem alto, perante o túmulo de Abner, e todas as pessoas também choraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'O rei lamentou por Abner e cantou: \"Deveria Abner morrer como morre um tolo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Suas mãos não estavam atadas; seus pés não estavam algemados. Como cai um homem diante dos filhos da injustiça, assim caíste\". Mais uma vez, todo o povo chorou sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Todo o povo veio fazer Davi comer enquanto ainda era dia, mas Davi jurou: \"Que Deus me castigue como quiser, se eu provar pão ou qualquer outra coisa antes de o sol se pôr\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Todas as pessoas tomaram conhecimento do luto de Davi, e isto pareceu-lhes bem, assim como ficaram satisfeitos com tudo o que o rei fizera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Então, todas as pessoas de todo o Israel entenderam, naquele dia, que não era desejo do rei matar Abner, filho de Ner.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'O rei disse aos seus servos: \"Não sabeis que hoje caiu em Israel um líder, um príncipe e um grande homem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'E hoje eu estou fraco, embora eu seja um rei ungido. Esses homens, os filhos de Zeruia, são fortes demais para mim. Que Yahweh retribua ao malfeitor, punindo-o por sua maldade, como ele merece\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Quando Isbosete, filho de Saul, ouviu que Abner havia morrido em Hebrom, suas mãos se enfraqueceram, e todo o Israel ficou preocupado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Ora, os filhos de Saul tinham dois homens que eram capitães de grupos de soldados. O nome de um deles era Baaná, e o outro, Recabe, filhos de Rimom, o beerotita, do povo de Benjamim. Beerote também é considerada parte de Benjamim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'e os beerotitas fugiram para Gitaim e vivem lá até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Jônatas, filho de Saul, tinha um filho que era aleijado dos pés. Ele tinha cinco anos de idade quando as notícias sobre Saul e Jônatas chegaram de Jezreel. Sua ama o pegou e fugiu, mas, enquanto ela estava correndo, o filho de Jônathas caiu, e se tornou aleijado. Seu nome era Mefibosete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Recabe e Baaná, os filhos de Rimom, o beerotita, viajaram durante o calor do dia para a casa de Isbosete, enquanto ele descansava na hora mais quente do dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'A mulher que vigiava a porta adormeceu, enquanto descansava, e, Recabe e Baaná entraram silenciosamente, e passaram por ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Logo após entrarem na casa, eles o atacaram e o mataram, enquanto ele estava deitado em sua cama, em seu quarto. Então, eles cortaram sua cabeça e a carregaram, viajando, por toda a noite, até Arabá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Eles trouxeram a cabeça de Isbosete até Davi, em Hebrom, e disseram ao rei: \"Olha, essa é a cabeça de Isbosete, filho de Saul, seu inimigo, o qual atentava por tua vida. Hoje Yahweh vingou o rei, nosso senhor, contra Saul e seus descendentes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Davi respondeu a Recabe e Baaná; ele lhes disse: \"Assim como Yahweh vive, Aquele que livrou minha vida de toda angústia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'quando alguém me contou: \'Olhe, Saul está morto\', pensando que estava trazendo boas notícias, eu o capturei e o matei em Ziclague. Aquela foi a recompensa que dei a ele por sua notícia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Quantos outros mais — quando homens perversos que mataram uma pessoa inocente na sua cama, em sua própria casa — não deveria eu requerer o sangue de suas mãos, e removê-los da terra?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Então, Davi deu ordens aos seus moços, e eles os mataram, cortaram fora suas mãos e pés e os penduraram ao lado do tanque, em Hebrom. Todavia, tomaram a cabeça de Isbosete e a enterraram no sepulcro de Abner, em Hebrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Então, todas as tribos de Israel vieram até Davi, em Hebrom, e disseram: \"Vê, somos tua carne e teu osso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Num passado recente, quando Saul reinava sobre nós, eras tu quem lideravas o exército de Israel. Yahweh te disse: \'Tu pastorearás Meu povo Israel e tu governarás sobre Israel\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Então, todos os anciãos de Israel vieram ao rei, em Hebrom, e o rei Davi celebrou uma aliança diante de Yahweh. Ungiram Davi rei sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Davi tinha trinta anos quando começou a reinar e reinou quarenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Em Hebrom, ele reinou sobre Judá sete anos e seis meses; em Jerusalém, ele reinou trinta e três anos sobre todo o Israel e Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'O rei e seus homens foram até Jerusalém contra os Jebuseus, os habitantes da terra. Eles disseram a Davi: \"Tu não virás aqui, exceto para seres expulso pelos cegos e aleijados. Davi não poderá vir aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'No entanto, Davi capturou a fortaleza de Sião, a qual é, agora, a cidade de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Naquele tempo, Davi disse: \"Qualquer que atacar os Jebuseus deverá passar pelo duto de água para alcançar aqueles \'cegos e aleijados\', que são inimigos de Davi\". É por isso que o povo diz: \"Os cegos e aleijados não poderão vir para o palácio\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Então, Davi passou a viver na fortaleza e a chamou de cidade de Davi. Ele fortificou seus arredores, desde o terraço até o interior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Davi se tornou muito poderoso porque Yahweh, o Deus dos Exércitos, estava com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Então, Hirão, rei de Tiro, enviou mensageiros a Davi e cedros, carpinteiros e pedreiros. Eles construíram uma casa para Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Davi sabia que Yahweh o tinha estabelecido como rei de Israel e que Ele havia exaltado seu reino por amor do Seu povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Após Davi ter deixado Hebrom e ido para Jerusalém, ele tomou mais cocumbinas e esposas em Jerusalém, e mais filhos e filhas nasceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Estes foram os nomes dos filhos que lhe nasceram em Jerusalém: Samua, Sabote, Natã, Salomão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Ibar, Eliusa, Nefegue, Jafia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisma, Eliadá e Elifelete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Quando os filisteus ouviram que Davi havia sido ungido como rei sobre Israel, todos eles saíram à sua procura. Mas Davi ouviu sobre isso e desceu para a sua fortaleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Os filisteus foram e se espalharam pelo vale de Refaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Então, Davi pediu ajuda de Yahweh. Davi disse: \"Deverei atacar os filisteus? Tu me darás vitória sobre eles?\". Yahweh disse a Davi: \"Ataca, pois Eu certamente te darei vitória sobre os filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Então, Davi atacou em Baal-Perazim, e ali os derrotou. Davi comentou: \"Yahweh derrotou meus inimigos diante de mim, como águas de um dilúvio destruidor\". Então, aquele lugar foi chamado Baal-Perazim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Os filisteus deixaram seus ídolos lá, e Davi e seus homens os levaram dali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Então, os filisteus subiram outra vez e se espalharam pelo vale de Refaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Davi buscou ajuda de Yahweh novamente, e Yahweh disse a ele: \"Tu não os atacarás pela frente; em vez disso, dá a volta e encontra-os perto das amoreiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Quando tu ouvires o som de marcha no soprar do vento, através do topo das amoreiras, então ataca com força. Faze isto porque Yahweh terá saído antes de ti, para atacar o exército dos filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'E Davi fez como Yahweh ordenou. Ele matou os filisteus desde Geba em todo o caminho até Gezer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Então, Davi reuniu novamente todos os homens escolhidos de Israel, trinta mil homens ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Davi levantou-se e foi com todos os homens que estavam com ele, de Baalá de Judá, para de lá trazer a Arca de Deus, que é chamado pelo nome de Yahweh dos Exércitos, que se assenta entronizado sobre os querubins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Eles puseram a Arca de Deus sobre um carro novo e a levaram da casa de Abinadabe, que está sobre uma colina. Uzá e Aiô, seus filhos, conduziam o carro novo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Eles trouxeram o carro da casa de Abinadabe, da colina, com a Arca de Deus sobre ele. Aiô andava à frente da arca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Então, Davi e toda a casa de Israel começaram a tocar diante de Yahweh, celebrando com instrumentos feitos de madeira de pinho, harpas, liras, tamborins, pandeiros e címbalos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Quando eles chegaram à eira de Nacom, os bois tropeçaram. Uzá estendeu a mão, pegou a Arca de Deus e a segurou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Então, a ira de Yahweh se acendeu contra Uzá. Deus o atacou ali, por causa do seu pecado. Uzá morreu ali, ao lado da Arca de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Davi ficou zangado porque Yahweh havia atacado Uzá, e ele chamou aquele lugar pelo nome de Perez-Uzá. Aquele lugar é chamado de Perez-Uzá até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Davi temeu a Yahweh naquele dia. Ele disse: \"Como a Arca de Deus pode vir até mim?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Assim, Davi não estava desejoso de levar a Arca de Yahweh com ele para a cidade de Davi; em vez disso, ele a deixou na casa de Obede-Edom, o geteu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'A Arca de Yahweh permaneceu na casa de Obede-Edom, o geteu, por três meses. Então, Yahweh o abençoou e a toda a sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Disseram ao rei Davi: \"Yahweh tem abençoado a casa de Obede-Edom e tudo que pertence a ele por causa da Arca de Deus\". Então, Davi foi e trouxe a Arca de Deus da casa de Obede-Edom para a cidade de Davi, com alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Quando aqueles que estavam carregando a Arca de Yahweh davam seis passos, ele sacrificava um boi e um novilho gordo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Davi dançou perante Yahweh, com todas as suas forças; ele estava vestindo somente um colete de linho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Então, Davi e toda a casa de Israel trouxeram a Arca de Yahweh com gritos e ao som de trombetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Nesse momento, quando a Arca de Yahweh chegou à cidade de Davi, Mical, filha de Saul, olhou pela janela. Ela viu o rei Davi saltando e dançando diante de Yahweh, então, ela o desprezou em seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Eles trouxeram a Arca de Yahweh e a colocaram no seu lugar, no meio da tenda que Davi havia preparado para ela. E Davi ofereceu holocaustos e ofertas pacíficas diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Quando Davi terminou de oferecer os holocaustos e as ofertas pacíficas, abençoou o povo no nome de Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Então, distribuiu entre todo o povo, toda a multidão de Israel, tanto para homens quanto para mulheres, um pão, uma porção de carne e um bolo de passas: então, todo o povo saiu; cada um retornou à sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Depois, Davi retornou para abençoar sua família. Mical, a filha de Saul, veio para encontrar Davi e disse: \"Quão honrado foi o rei de Israel hoje, despindo-se diante dos olhos das escravas, entre seus servos, como um sujeito qualquer que vergonhosamente se despe!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Davi respondeu a Mical: \"Eu fiz isso diante de Yahweh, que me escolheu no lugar do teu pai e no lugar de toda a sua família, que me designou como líder sobre o povo de Yahweh, sobre Israel. Diante de Yahweh eu me alegrarei!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Eu serei ainda mais indigno que isso. Eu me humilharei aos meus próprios olhos, mas, aos olhos das escravas que tu mencionaste, eu serei honrado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Então, Mical, a filha de Saul, não teve filhos até o dia da sua morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Aconteceu que, depois que o rei se estabeleceu em sua casa, e, depois que Yahweh lhe havia dado descanso de todos os seus inimigos ao redor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'o rei disse a Natã, o profeta: \"Vê, eu moro em uma casa de cedro, mas a Arca de Deus está numa tenda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Então, Natã disse ao rei: \"Vai, faz o que está em teu coração, porque Yahweh é contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Mas, naquela mesma noite, a palavra de Yahweh veio a Natã, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, '\"Vai e diz a Davi, meu servo: \'Isto é o que Yahweh diz: Tu Me edificarás uma casa para habitar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Porque Eu não habitei em uma casa, desde o dia em que tirei o povo de Israel do Egito até este dia; em vez disso, Eu tenho andado de lá para cá em uma tenda, num tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Por todos os lugares por onde Eu Me movi, entre o povo de Israel, disse Eu alguma coisa a algum dos líderes que designei para pastorear meu povo Israel, dizendo: \'Por que vós não Me edificastes uma casa de cedro?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Agora, pois, diz a meu servo Davi: \"Isto é o que Yahweh dos Exércitos diz: \'Eu te tirei das pastagens, de detrás das ovelhas, para que tu fosses governante sobre o Meu povo Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Eu estive contigo por onde foste e eliminei todos os teus inimigos de diante de ti. Agora, farei o teu nome grande, como os nomes dos grandes da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Eu designarei um lugar para o Meu povo Israel e o plantarei, para que eles vivam no seu próprio lugar e não sejam mais perturbados. Nunca mais os povos perversos os oprimirão, como fizeram antes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'como faziam desde os dias em que Eu designei juízes sobre o Meu povo Israel. Agora, te darei descanso de todos os teus inimigos. Ademais, Eu, Yahweh, declaro a ti que te edificarei uma casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Quando teus dias se completarem e tu descansares com teus pais, Eu levantarei um descendente depois de ti, um que sairá de ti, e estabelecerei seu reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Ele edificará uma casa ao Meu nome, e Eu estabelecerei o trono do seu reino para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Eu serei um pai para ele, e ele será Meu filho. Quando ele pecar, o disciplinarei com a vara de homens e com os açoites dos filhos dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Mas Minha aliança de fidelidade não o deixará, como a retirei de Saul, o qual Eu removi de diante de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Tua casa e teu reino serão confirmados para sempre perante ti. Teu trono será estabelecido para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Natã falou com Davi e lhe relatou todas essas palavras, e lhe contou toda a visão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Então, Davi, o rei, entrou e se assentou diante de Yahweh e disse: \"Quem sou eu, Senhor Yahweh, e o que é minha família para que Tu me trouxesses a este ponto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Isso foi pouco aos Teus olhos, Senhor Yahweh. Tu ainda falaste sobre a família de Teu servo para tempos distantes e me mostraste gerações futuras, Senhor Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'O que mais posso eu, Davi, Te dizer? Tu honraste Teu servo, ó Senhor Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Por causa da Tua palavra e para cumprir Teu propósito, Tu fizeste esse grande feito e o revelaste a Teu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Por essa razão, Tu és grande, Senhor Yahweh, porque não há ninguém igual a Ti, e não há outro Deus além de Ti, como ouvimos com nossos próprios ouvidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'E que nação é como o Teu povo Israel, a única nação na terra que Tu, Deus, foste e resgataste para Ti mesmo? Tu fizeste isso para que eles se tornassem um povo para Ti, para fazer um nome para Ti mesmo e realizar grandes e terríveis feitos para Tua terra. Tu expulsaste nações e seus deuses de diante do Teu povo, que resgataste do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Tu estabeleceste Israel como Teu próprio povo para sempre e Tu, Yahweh, Te tornaste o seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Então, agora, Yahweh Deus, que a promessa que fizeste com respeito a Teu servo e sua família seja estabelecida para sempre. Faz conforme disseste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Que o Teu nome seja para sempre grande e que as pessoas digam: \'Yahweh dos Exércitos é o Deus de Israel\', enquanto a casa de Teu servo Davi é estabelecida diante de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Porque Tu, Yahweh dos Exércitos, o Deus de Israel, revelaste a Teu servo que Tu lhe edificarás uma casa. É por isso que eu, Teu servo, encontrei coragem para orar a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Agora, Senhor Yahweh, Tu és Deus e Tuas palavras são dignas de confiança, e fizeste essa boa promessa a Teu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Agora, pois, se for do Teu agrado, abençoa a casa de Teu servo, para que ela continue para sempre diante de Ti. Pois Tu, Senhor Yahweh, disseste essas coisas, e, com Tua bênção, a casa de Teu servo será abençoada para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Depois disso, aconteceu que Davi atacou os filisteus e os derrotou. Assim, Davi tomou Gate e suas aldeias do controle dos filisteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Então, ele derrotou Moabe, fez com que seus homens se deitassem no chão e os mediu com uma corda, dessa forma: duas medidas de corda para matar, e uma medida inteira para manter com vida. Assim, os moabitas tornaram-se servos de Davi e lhe pagaram tributo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Davi, então, derrotou Hadadezer, filho de Reobe, o rei de Zobá, enquanto Hadadezer estava viajando para recuperar o seu domínio ao longo do rio Eufrates.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Davi capturou mil e setecentas carruagens de guerra e vinte mil soldados de infantaria. Davi mutilou todos os cavalos das carruagens, mas reservou um número suficiente deles para cem carruagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Quando os sírios de Damasco vieram para ajudar a Hadadezer, rei de Zobá, Davi matou vinte e dois mil sírios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Então, Davi pôs guarnições na Síria de Damasco, e os sírios tornaram-se servos dele e lhe pagavam tributos. Yahweh deu vitória a Davi onde quer que ele fosse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Davi tomou os escudos de ouro que estavam sobre os servos Hadadezer e os trouxe a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'De Betá e de Berotai, cidades de Hadadezer, o rei Davi tomou grande quantidade de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Quando Toí, rei de Hamate, ouviu que Davi havia derrotado todo o exército de Hadadezer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'enviou seu filho Jorão ao rei Davi para saudá-lo e abençoá-lo; porque Davi lutou contra Hadadezer e o derrotou. Também porque Hadadezer havia declarado guerra contra Toí. Jorão trouxe consigo objetos de prata, ouro e bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'O rei Davi consagrou esses objetos a Yahweh, bem como a prata e o ouro de todas as nações que ele conquistou —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'da Síria, de Moabe, de Amom, dos filisteus e de Amaleque, juntamente com todos os bens saqueados de Hadadezer, filho de Reobe, o rei de Zobá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'O nome de Davi ficou bem conhecido após retornar, com seus dezoito mil homens, da conquista dos sírios no vale do Sal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Ele colocou guarnições em Edom e todos os edomitas tornaram-se servos dele. Yahweh dava vitória a Davi por onde ele ia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Davi reinou sobre todo o Israel; ele governava com justiça e equidade sobre todo o seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joabe, filho de Zeruia, era o comandante do exército; e Jeosafá, filho de Ailude, era cronista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Zadoque, filho de Aitube, e Aimeleque, filho de Abiatar, eram sacerdotes; Seraías era escriba;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaia, filho de Joiada, liderava sobre os quereteus e peleteus; e os filhos de Davi eram conselheiros do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Davi disse: \"Existe ainda alguém da família de Saul a quem eu possa mostrar bondade, por amor de Jônatas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Na família de Saul havia um servo que se chamava Ziba, e o levaram para Davi. O rei lhe disse: \"Tu és Ziba?\". Ele respondeu: \"Sim, sou teu servo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Então, o rei disse: \"Existe alguém ainda da família de Saul a quem eu possa mostrar a bondade de Deus?\". Ziba respondeu para o rei: \"Jônatas ainda tem um filho, que é aleijado dos pés\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'O rei lhe disse: \"Onde ele está?\". Ziba respondeu ao rei: \"Está na casa de Maquir, filho de Amiel, em Lo-Debar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Então, o rei Davi mandou trazê-lo, e o trouxeram da casa de Maquir, filho de Amil, de Lo-Debar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Então, Mefibosete, filho de Jônatas, filho de Saul, veio a Davi e prostrou-se com a face no chão em honra a Davi. Davi disse: \"Mefibosete!\". Ele respondeu: \"Sim, sou teu servo!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Davi lhe disse: \"Não tenhas medo, pois certamente te mostrarei bondade por amor de Jônatas, teu pai, e restituirei todas as terras de Saul, teu avô, e comerás sempre à minha mesa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Mefibosete se prostrou e disse: \"Quem é o teu servo, para teres olhado com favor para um cachorro morto como eu?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Então, o rei chamou por Ziba, o servo de Saul, e lhe disse: \"Tudo o que pertencia a Saul e à sua família eu darei ao neto do teu senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Tu, teus filhos e teus servos lavrareis a terra para ele e tu colherás a safra para que o neto do teu senhor tenha sempre o que comer. Todavia, Mefibosete, neto do teu senhor, sempre comerá à minha mesa\". Ziba tinha quinze filhos e vinte servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Então, Ziba disse ao rei: \"Teu servo fará tudo o que meu mestre, o rei, ordenar\". O rei acrescentou: \"A respeito de Mefibosete, ele comerá à minha mesa, como um dos filhos do rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Mefibosete tinha um filho jovem que se chamava Mica. Todos os que viviam na casa de Ziba foram servos de Mefibosete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Então, Mefibosete viveu em Jerusalém e sempre comia à mesa do rei, mesmo sendo aleijado de ambos os pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'E aconteceu que, após um tempo, o rei dos amonitas morreu, e seu filho, Hanum, tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Davi disse: \"Eu mostrarei bondade para Hanum, filho de Naás, como seu pai mostrou bondade para comigo\". Então, Davi enviou seus servos para confortar Hanum, por causa de seu pai. Seus servos entraram na terra dos amonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Entretanto, os líderes dos amonitas disseram a seu senhor, Hanum: \"Tu realmente pensas que Davi está honrando teu pai por haver mandado homens para te confortar? Não teria Davi enviado seus servos a ti para que observassem a cidade, para espiá-la, a fim de tomá-la?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Então, Hanum tomou os servos de Davi, raspou-lhes a metade das barbas, cortou-lhes fora as vestes até suas nádegas e mandou que fossem embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Quando Davi se reuniu com eles, explicaram que foram profundamente humilhados. O rei disse: \"Permanecei em Jericó, até que vossa barba cresça novamente e, então, retornai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Quando os amonitas perceberam que se tornaram odiosos perante Davi, enviaram mensageiros e contrataram vinte mil soldados dos arameus, de Bete-Reobe e Zobá, mil homens do rei de Maaca e doze mil homens de Tobe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Quando Davi soube disso, mandou Joabe e todo o exército de soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Os amonitas vieram e formaram uma linha de batalha na entrada do portão da cidade, enquanto os arameus de Zobá e de Reobe e os homens de Tobe e de Maaca, ficaram em campo aberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Quando Joabe viu as linhas de batalha formadas, tanto à sua frente, quanto atrás, escolheu alguns dos melhores guerreiros e os organizou contra os arameus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'E o restante do exército ele entregou ao comando de seu irmão, Abisai, que os colocou na linha de batalha contra o exército dos amonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Joabe disse: \"Se os arameus forem tão fortes para comigo, então tu, Abisai, deves socorrer-me. Porém, se o exército dos amonitas for tão forte para contigo, eu irei te socorrer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Sê forte e deixa que nos mostremos fortes para o nosso povo e pelas cidades de nosso Deus, pois Yahweh fará o que é bom, segundo Seu propósito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Então, Joabe e os soldados do seu exército avançaram para a batalha contra os arameus, que foram forçados a fugir diante do exército de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Quando o exército dos amonitas viram que os arameus fugiram, eles também fugiram de Abisai e voltaram para a cidade. Então, Joabe retornou do povo de Amom e voltou para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Quando os arameus viram que estavam sendo derrotados por Israel, eles se reuniram novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Então, Hadadezer enviou as tropas dos arameus para além do rio Eufrates. Eles vieram a Helã, acompanhados por Sobaque, comandante do exército de Hadadezer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Quando Davi foi informado disso, reuniu todo o Israel, atravessou o Jordão e chegou a Helã. Os arameus se agruparam em linhas na batalha contra Davi e lutaram contra ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Os arameus fugiram de Israel. Davi matou setecentos soldados arameus que conduziam as carruagens e quarenta mil soldados de cavalaria. Sobaque, o comandante do exército arameu, foi ferido e ali morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Quando todos os reis que foram servos de Hadadezer viram que foram derrotados por Israel, declararam paz e se tornaram submissos a ele. Assim, os arameus temeram em continuar a ajudar os amonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Por ocasião da primavera, na época em que os reis normalmente vão à guerra, Davi enviou Joabe, seu servo, e todo o exército de Israel. Eles destruíram o exército de Amon e cercaram Rabá. Mas Davi ficou em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Aconteceu que, em uma tarde, Davi levantou-se de sua cama e andou até o terraço de seu palácio. De lá, ele acabou vendo uma mulher que estava se banhando, e ela era muito bonita de se olhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Davi mandou perguntar às pessoas quem conheceria a mulher. Alguém disse: \"Não é essa Bate-Seba, filha de Eliã, e não é ela a mulher de Urias, o heteu?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Davi enviou mensageiros, e a trouxeram; ela veio até ele, e ele dormiu com ela, que havia acabado de se purificar do período menstrual. Depois, ela retornou à sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'A mulher concebeu e mandou avisar a Davi; ela disse: \"Estou grávida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Então, Davi enviou mensagem a Joabe, dizendo: \"Traze-me Urias, o heteu\". Joabe trouxe Urias a Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Quando Urias chegou, Davi lhe perguntou como Joabe estava, como o exército estava e como a guerra ia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Davi disse a Urias: \"Vai à tua casa e lava teus pés\". Assim, Urias deixou o palácio do rei, e este enviou um presente a Urias logo após sua saída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Porém, Urias dormiu às portas do palácio do rei, junto a todos os servos de seu senhor, e não foi para sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Quando disseram a Davi: \"Urias não foi para sua casa\", Davi disse a Urias: \"Não vieste tu de uma jornada? Por que não foste para tua casa?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Urias respondeu a Davi: \"A arca, Israel e Judá estão em tendas, meu mestre Joabe e os seus servos estão acampados em campo aberto. Como, então, posso ir para minha casa para comer, beber e dormir com minha esposa? Tão certo como tu vives, não farei isso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Davi disse a Urias: \"Fica aqui também hoje, e amanhã deixarei que tu vás\". Então, Urias permaneceu em Jerusalém naquele dia e no dia seguinte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Quando Davi o chamou, ele comeu e bebeu diante dele, e Davi o embebedou. Ao anoitecer, Urias foi dormir em sua cama, com os servos de seu senhor; ele não retornou à sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Logo pela manhã, Davi escreveu uma carta para Joabe e a enviou pelas mãos de Urias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Davi escreveu na carta, dizendo: \"Coloca Urias na frente mais intensa da batalha e, então, aparta-te dele, para que seja ferido e morto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Assim, ao observavar o cerco da cidade, Joabe designou Urias para o local onde sabia que os mais fortes soldados inimigos estariam batalhando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Quando os homens da cidade saíram e lutaram contra o exército de Joabe, alguns dos soldados de Davi caíram, e Urias, o heteu, também foi morto lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Quando Joabe enviou notícias a Davi sobre tudo o que acontecia na guerra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'ordenou ao mensageiro, dizendo: \"Quando tu terminares de contar todas as coisas sobre a guerra ao rei,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'pode acontecer que ele fique com raiva e te diga: \'Por que fostes tão perto da cidade para lutar? Não sabíeis que eles atirariam da muralha?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Quem matou Abimeleque, filho de Jerubesete? Não foi uma mulher que jogou uma pedra de moinho nele, do alto do muro, de forma que ele morreu em Tébez? Por que fostes tão perto da muralha?\'. Então, deves responder: \'Teu servo Urias, o heteu, também está morto\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Então, o mensageiro saiu e foi a Davi e lhe contou tudo o que Joabe mandou que dissesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'E o mensageiro disse a Davi: \"O inimigo era mais forte do que nós no começo; eles saíram de encontro a nós, na batalha, mas os fizemos retroceder até à entrada do portão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Então, os arqueiros deles atiraram em teus soldados, do alto da muralha; alguns dos servos do rei foram mortos e o teu servo Urias, o heteu, também foi morto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Davi, então, disse ao mensageiro: \"Diz isto a Joabe: \'Não deixes que isso te aflija, porque a espada devora um assim como o outro. Continua tua batalha ainda mais forte contra a cidade e supera isso\' e encoraja-o\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Quando a mulher de Urias soube que seu marido estava morto, ela lamentou profundamente por seu marido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Quando seu luto passou, Davi mandou que a trouxessem da sua casa ao palácio; ela tornou-se sua esposa e lhe deu um filho. Mas o que Davi fez desagradou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Então, Yahweh enviou Natã a Davi. Ele veio a Davi e disse: \"Havia dois homens numa cidade. Um homem era rico e o outro pobre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'O rico tinha grande número de rebanhos e manadas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'mas o homem pobre não tinha nada, exceto uma pequena cordeirinha, a qual ele havia comprado, alimentado e criado. Ela cresceu junto com ele e seus filhos. A cordeira até comia com ele e bebia do seu próprio copo, e dormia em seus braços. Era como uma filha para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Um dia, o homem rico recebeu um visitante; porém, o homem rico não quis tomar de seus próprios rebanhos e manadas para lhe providenciar alimento. Ao invés disso, ele tomou a cordeirinha do homem pobre e a cozinhou para o seu visitante\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Davi ficou cheio de raiva contra o homem rico, e se enfureceu diante de Natã: \"Como vive Yahweh, o homem que fez isso merece ser condenado à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'E pela cordeira ele deve restituir quatro vezes mais, por ter feito tal coisa e porque ele não teve piedade do homem pobre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Então, Natã disse a Davi: \"Tu és esse homem! Yahweh, o Deus de Israel, diz: \'Eu o ungi rei sobre Israel, e Eu o resgatei da mão de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Eu te dei a casa de teu senhor, e, em teus braços, dei as esposas de teu senhor. Eu também te dei a casa de Israel e Judá. Porém, se isso fosse pouco, Eu teria te dado muitas outras coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Por que, então, tens desprezado os comandos de Yahweh, para fazer o que é mau aos Seus olhos? Tu mataste Urias, o heteu, com a espada, e tomaste sua esposa para ser a tua própria esposa. Tu o mataste com a espada do exército de Amom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Então, agora, a espada nunca deixará a tua casa, porque tens Me desprezado, e tomaste a esposa de Urias, o heteu, como tua esposa\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Yahweh diz: \'Vê, Eu levantarei desastre contra ti dentro de tua própria casa. Diante dos teus próprios olhos, Eu tomarei tuas esposas e as darei ao teu vizinho, e ele dormirá com tuas esposas em plena luz do dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Porque tu cometeste teu pecado secretamente, porém Eu farei isto diante de todo o Israel, à luz do dia\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Então, Davi disse a Natã: \"Eu pequei contra Yahweh\". Natã respondeu a Davi: \"Yahweh também perdoou teu pecado. Tu não serás morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Contudo, porque com a tua atitude desprezaste Yahweh, o filho que de ti nascer, certamente morrerá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Então, Natã saiu e foi para casa. Yahweh feriu o filho de Davi com a esposa de Urias, e ele ficou muito doente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Davi, então, implorou a Deus pelo menino. Davi jejuou, e entrou, e prostou-se no chão toda a noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Os anciãos de sua casa se levantaram e se puseram do lado dele, para lhe fazer levantar do chão, porém ele não levantou, e nem comeu com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'No sétimo dia, aconteceu que a criança morreu. Os servos de Davi estavam com medo de dizer-lhe que a criança havia morrido, pelo que eles disseram: \"Vede, enquanto a criança ainda estava viva, nós falávamos com ele, e ele não ouvia a nossa voz. O que poderá ele fazer a si mesmo se dissermos que o menino está morto?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Mas, quando Davi viu que seus servos estavam sussurrando entre si, ele percebeu que a criança havia morrido. Ele disse a seus servos: \"A criança está morta?\". Eles responderam: \"Ela está morta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Então, Davi se levantou do chão e lavou-se, ungiu-se e mudou as suas roupas. Ele foi ao tabernáculo de Yahweh e adorou ali, e depois voltou para o seu palácio. Quando ele pediu, colocaram o alimento diante dele e ele comeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Então, seus servos lhe disseram: \"Por que fizeste isso? Tu jejuaste e choraste pela criança enquanto ela estava viva, mas, quando a criança morreu, tu levantaste e comeste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Davi respondeu: \"Enquanto a criança ainda estava viva, eu jejuei e orei. Eu disse: \'quem sabe se Yahweh será gracioso comigo, e a criança poderá viver?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Mas, agora, ela está morta; por que devo jejuar? Posso eu trazê-la de volta? Eu irei até ela, porém ela não retornará a mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Davi confortou Bate-Seba, sua esposa, foi até ela e dormiu com ela. E ela gerou um filho, e o menino foi chamado Salomão. Yahweh o amou,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'e Ele enviou sua palavra através de Natã, o profeta, para chamá-lo Jedidias, porque Yahweh o amou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Então, Joabe lutou contra Rabá, a cidade real do povo de Amom, e ele conquistou sua fortaleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Joabe enviou mensageiros a Davi, e disse: \"Eu lutei contra Rabá, e tomei as fontes de água da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Portanto, junta o resto do exército e cerca a cidade e toma-a, porque se eu tomar a cidade, ela será chamada por meu nome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Então, Davi juntou todo o exército e foi a Rabá; ele lutou contra a cidade e a conquistou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Davi tomou a coroa da cabeça do rei; ela pesava um talento de ouro e nela havia uma pedra preciosa. A coroa foi colocada na cabeça de Davi. Então, ele trouxe grande quantidade de despojo para a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Ele trouxe o povo que estava na cidade e forçou-os a trabalhar com serras, picaretas de ferro, e machados; ele os fez trabalhar também em fornos de tijolos. Davi cobrou de todas as cidades do povo de Amom que fizesse esse trabalho. Depois, Davi e todo o exército retornaram para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Aconteceu que, depois disso, Amnom, filho de Davi, ficou muito atraído por sua bonita meia irmã Tamar, que era irmã legítima de Absalão, um dos outros filhos de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Amnom estava tão frustrado que ficou doente por causa de sua irmã Tamar. Ela era virgem, e parecia impossível a Amnom lhe fazer alguma coisa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Mas Amnom tinha um amigo cujo nome era Jonadabe, filho de Simeia, irmão de Davi. Jonadabe era um homem muito astuto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Ele disse a Amnom: \"Por que, filho do rei, estás deprimido toda manhã? Não queres me contar?\". Amnom lhe respondeu: \"Eu amo Tamar, irmã de meu irmão Absalão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Então, Jonadabe lhe disse: \"Deita-te na tua cama e finge estar doente. Quando teu pai vier te ver, pede-lhe: \'Poderias enviar, por favor, minha irmã Tamar para me dar alguma coisa de comer e cozinhar diante de mim, para que eu veja e coma da sua mão?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Amnom se deitou e fingiu estar doente. Quando o rei veio vê-lo, Amnom disse ao rei: \"Por favor, envia minha irmã Tamar para fazer alguma comida diante de mim, para que eu possa comer das mãos dela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Davi, então, mandou Tamar, que estava no palácio, e disse-lhe: \"Vai à casa de teu irmão Amnom e prepara-lhe algum alimento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Assim, Tamar foi à casa de seu irmão Amnom, que estava deitado. Ela pegou a massa e a amassou, fez pão à sua vista, e o assou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Ela tomou a forma e deu o pão a ele; porém, ele se recusou a comer. Então, Amnom disse aos outros presentes: \"Saí todos para longe de mim\". Então, todos se retiraram dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Então, Amnom disse a Tamar: \"Traz o alimento ao meu quarto para que eu possa comer de tua mão\". Então, Tamar tomou o pão que havia feito e o levou ao quarto de Amnom, seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Quando ela lhe trouxe o alimento, ele a segurou e disse: \"Vem, deita-te comigo, minha irmã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Ela lhe respondeu: \"Não, meu irmão, não me forces! Não se faz isso em Israel. Não faças essa coisa horrível!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Como eu poderia esconder a minha vergonha? E tu? Tu serias como um dos loucos de Israel! Agora, por favor, fala com o rei! Ele não me negará a ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Amnon não a ouviu. Como ele era mais forte do que Tamar, ele a segurou e deitou-se com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Então, Amnom odiou Tamar com extrema aversão. Ele a odiou mais do que a havia desejado. Amnom lhe disse: \"Levanta e sai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Ela lhe respondeu: \"Não! Porque este grande mal de me fazer sair é pior do que o que me fizeste!\". Mas Amnom não a ouviu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Ao invés disso, ele chamou seu servo pessoal e lhe disse: \"Tira esta mulher de diante de mim, e tranca a porta após ela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Então, seu servo a colocou para fora e trancou a porta após ela. Tamar estava usando uma túnica toda trabalhada, porque era assim que as filhas virgens do rei se vestiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Ela colocou cinzas em sua cabeça e rasgou a sua túnica; colocou as mãos sobre sua cabeça e se foi, chorando alto enquanto ia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Absalão, seu irmão lhe disse: \"Esteve Amnom, teu irmão, contigo? Porém, agora fica calada, minha irmã. Ele é teu irmão. Não leves essas coisas ao teu coração\". Então, Tamar permaneceu sozinha na casa de seu irmão, Absalão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Mas, quando o rei Davi ouviu sobre todas essas coisas, ele se enfureceu muito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Absalão não disse nada a Amnom porque Absalão o odiou pelo que ele havia feito a Tamar, e como ele havia desonrado sua irmã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Aconteceu que, depois de dois anos inteiros, Absalão tinha tosquiadores trabalhando em Baal-Hazor, que fica perto de Efraim. Absalão convidou todos os filhos do rei para visitá-lo ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Absalão foi ao rei e disse: \"Agora vê, teus servos estão tosquiando as ovelhas. Por favor, que venham o rei e seus servos comigo, o teu servo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'O rei respondeu a Absalão: \"Não, meu filho, não devemos ir todos nós, porque nós seríamos um peso para ti\". Absalão encorajou o rei, mas este não foi; entretanto, ele abençoou Absalão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Então, Absalão disse: \"Se não, por favor deixa meu irmão Amnom ir conosco\". O rei lhe perguntou: \"Por que Amnom deve ir contigo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Absalão pressionou Davi, e ele deixou Amnom e todos os outros filhos irem com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Absalão ordenou aos seus servos, dizendo: \"Ouvi atentamente: quando Amnom se embriagar com vinho e quando eu vos disser \'atacai Amnom\', então, matai-o. Não fiqueis com medo. Não sou eu quem vos ordenei? Sede bravos e corajosos!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Os servos de Absalão fizeram a Amnom conforme as suas ordens. Então, todos os filhos do rei se levantaram, e cada homem montou em sua mula e fugiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'E aconteceu que, enquanto eles estavam na estrada, as notícias chegaram a Davi, que disse: \"Absalão matou todos os filhos do rei, e não sobrou nenhum\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Então, o rei se levantou, rasgou suas vestes e se prostrou no chão, e todos os seus servos estavam com suas vestes rasgadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Jonadabe, filho de Simeia, irmão de Davi, respondeu e disse: \"Meu senhor, não deves acreditar que mataram todos os jovens, filhos do rei, pois só Amnom está morto. Absalão planejou isso desde o dia em que Amnon violentou sua irmã Tamar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Por isso, meu senhor, o rei não deve colocar essas coisas no coração e acreditar que todos os filhos do rei estão mortos, pois só Amnom está morto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Absalão fugiu. Um servo que estava de guarda levantou os olhos e viu muita gente vindo no caminho, na encosta, a oeste dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Então, Jonadabe disse ao rei: \"Vê, os filhos do rei estão vindo, assim como teu servo disse\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Assim, aconteceu que, acabando de falar, os filhos do rei chegaram, levantaram sua voz e choraram. O rei e todos os seus servos também choraram amargamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Porém, Absalão fugiu para Talmai, filho de Amiur, rei de Gesur. Davi lamentou por seu filho todos os dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Absalão fugiu e foi para Gesur, onde ficou por três anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Em seu pensamento, o rei Davi desejava ir e ver Absalão, porque ele estava confortado sobre a morte de Amnom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Joabe, filho de Zeruia, percebeu que o coração do rei desejava ver Absalão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Então, Joabe mandou trazer, de Tecoa, uma mulher sábia. Ele disse a ela: \"Por favor, finge que estás de luto e põe vestes de luto. Não te unjas com óleo; antes, finge ser uma mulher que há muito pranteia pelo falecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Depois, vai até o rei e fala sobre o que descreverei\". Então, Joabe disse a ela as palavras que ela deveria dizer ao rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Quando a mulher de Tecoa falou com o rei, ela se prostrou com o rosto no chão e disse: \"Ajuda-me, rei!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'O rei disse a ela: \"O que está errado?\". Ela respondeu: \"A verdade é que sou uma viúva, meu marido está morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Eu, tua serva, tive dois filhos. Eles brigaram entre si no campo, e não havia ninguém que os separasse. Um feriu o outro e o matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Agora, todo o clã se levantou contra a tua serva, dizendo: \'Entrega-nos o homem que matou seu irmão, para que o matemos, para pagar pela vida de seu irmão, a quem ele matou\'. Assim, eles matariam também o herdeiro. Desse modo, eles apagarão também a brasa que me restou, não deixando ao meu marido nem nome, nem descendência na face da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Então, o rei disse à mulher: \"Vai para a tua casa, e eu ordenarei que algo seja feito por ti.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'A mulher de Tecoa replicou: \"Ó rei, meu senhor, que toda a culpa recaia sobre mim e sobre a família de meu pai. O rei e seu trono sejam inocentes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'O rei respondeu: \"Qualquer um que disser alguma coisa a ti, traz a mim, e não mais te importunará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Então, ela disse: \"Por favor, ó rei, lembra-te de Yahweh, teu Deus, para que o vingador do sangue não destrua mais ninguém, a fim de que não destrua o meu filho\". O rei replicou: \"Tão certo quanto Yahweh vive, nem um fio de cabelo de teu filho cairá no chão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Então, a mulher disse: \"Por favor, deixa que a tua serva diga mais uma coisa ao rei, meu senhor\". Disse ele: \"Pois fala\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'A mulher disse: \"Por que pensas tal coisa contra o povo de Deus? Ao dizer isso, o rei se culpou por não ter trazido para casa seu filho banido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Pois é certo que todos morreremos, e somos como água derramada no chão, que não se pode ajuntar novamente. Porém, Deus não tira a vida; ao invés disso, Ele acha uma forma de fazer retornarem aqueles que foram expulsos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Se agora vim falar essa palavra ao rei, meu senhor, é porque as pessoas me amedrontaram. Então, tua serva disse a si mesma: \'Falarei agora com o rei. Pode ser que o rei atenda ao pedido de sua serva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Pois o rei me ouvirá, a fim de tirar sua serva das mãos do homem que queria destruir a mim e ao meu filho, e nos tirar da herança de Deus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Então, a tua serva orou: \'Yahweh, por favor, permite que a palavra do rei, o meu senhor, me alivie; como um anjo de Deus, assim o meu senhor, o rei, está discernindo o bem do mal\'. Que Yahweh, teu Deus, esteja contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'O rei respondeu à mulher: \"Por favor, não escondas de mim nada do que te perguntarei\". A mulher replicou: \"Que o rei, meu senhor, fale agora\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'O rei disse: \"Acaso não está a mão de Joabe contigo em tudo isso?\". A mulher respondeu, dizendo: \"Assim como tu vives, ó rei, meu senhor, ninguém pode escapar, para a direita nem para a esquerda, de nada que o rei, meu senhor, tenha dito. Foi o teu servo Joabe que me mandou e me disse para falar estas coisas que tua serva disse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'O teu servo Joabe fez isso para mudar o curso do que está acontecendo. Meu senhor é sábio, como a sabedoria de um anjo de Deus, para entender tudo o que está acontecendo na terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Então, o rei disse a Joabe: \"Vê agora, eu farei assim. Vai, portanto, e traz de volta o jovem Absalão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Então, Joabe se prostrou com o rosto no chão, em honra e gratidão ao rei. Joabe disse: \"Hoje o teu servo sabe que achou graça aos teus olhos, rei, senhor meu, porque o rei atendeu ao pedido do teu servo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Então, Joabe se levantou, foi à Gesur e trouxe Absalão de volta a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'O rei disse: \"Ele poderá retornar à sua casa; porém, não poderá ver a minha face\". Então, Absalão retornou à sua casa, mas não viu a face do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Em todo o Israel, não havia ninguém mais aprazível e belo do que Absalão. Da sola de seu pé ao topo de sua cabeça, não havia nele defeito algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Quando ele cortava o cabelo, ao final de cada ano, por lhe ser pesado, e o pesava, dava cerca de duzentos siclos, segundo a medida real.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'De Absalão nasceram três filhos e uma filha, cujo nome era Tamar. Ela era uma bela mulher.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Absalão viveu dois anos inteiros em Jerusalém sem ver a face do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Então, Absalão mandou chamar Joabe para enviá-lo ao rei, mas Joabe não foi até ele. Absalão mandou chamá-lo uma segunda vez, mas Joabe não foi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Então, Absalão disse aos seus servos: \"Vede! O campo de Joabe é próximo ao meu e tem cevada. Ide e ateai fogo ao campo\". Então, os servos de Absalão atearam fogo no campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Depois, Joabe se levantou e veio até a casa de Absalão e lhe disse: \"Por que teus servos atearam fogo ao meu campo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Absalão respondeu a Joabe: \"Vê, eu mandei te chamar dizendo: \'Vem aqui, para que eu te mandasse ao rei para dizer-lhe: \'Por que vim de Gesur? Teria sido melhor que eu tivesse ficado lá. Agora, então, deixa-me ver a face do rei e, se sou culpado, que ele me mate\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Então, Joabe foi até o rei e lhe falou. Quando o rei chamou Absalão, ele foi até o rei e se prostrou diante dele, e o rei beijou Absalão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Aconteceu que, pouco depois disso, Absalão preparou para si uma carruagem de guerra e cavalos, e cinquenta homens para irem adiante dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Absalão se levantava cedo e ficava parado à beira da estrada que levava ao portão da cidade. Quando passava algum homem, levando uma causa para o rei julgar, Absalão o chamava e dizia: \"De que cidade vieste?\". E ele respondia: \"Teu servo é de uma das tribos de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Então, Absalão lhe dizia: \"Olha, a tua causa é boa e reta, mas não há ninguém competente da parte do rei para ouvir-te\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Absalão dizia: \"Quisera eu ser juiz na terra, a fim de que qualquer um que tivesse alguma causa ou contestação viesse a mim, e eu lhe faria justiça!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Então, quando qualquer homem vinha ter com Absalão para honrá-lo, Absalão estendia a mão e o beijava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Ele agia assim com todos de Israel que vinham levar uma causa para o rei julgar. Dessa forma, Absalão conquistou os corações dos homens de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'No final de quatro anos, Absalão disse ao rei: \"Por favor, deixa-me ir pagar um voto que fiz a Yahweh em Hebrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Porque teu servo fez um voto enquanto ainda estava vivendo em Gesur, na Síria, dizendo: \'Se Yahweh, de fato, me fizer voltar a Jerusalém, eu O cultuarei\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Então, o rei lhe disse: \"Vai em paz\". Logo, Absalão se levantou e foi para Hebrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'E ele enviou espiões por todas as tribos de Israel, dizendo: \"Assim que ouvirdes o som da trombeta, vós direis: \'Absalão é rei em Hebrom!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Junto de Absalão, havia duzentos homens de Jerusalém que foram convidados. Esses homens foram na sua inocência, sem saber nada do que Absalão havia planejado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Enquanto Absalão oferecia sacrifícios, mandou chamar Aitofel, de Siló, sua cidade natal. Ele era conselheiro de Davi. A conspiração de Absalão se fortalecia porque aumentava cada vez mais a quantidade de pessoas que o seguia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Um mensageiro veio até Davi dizendo: \"Os corações dos homens de Israel estão com Absalão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Então, Davi disse a todos os seus servos que estavam com ele em Jerusalém: \"Levantai! Fujamos, ou nenhum de nós escapará de Absalão. Preparai para partir sem demora, ou ele nos alcançará rapidamente. Ele trará sobre nós desastre e atacará a cidade com a ponta da espada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Os servos do rei lhe disseram: \"Olha, os teus servos estão prontos para fazer o que nosso senhor, o rei, decidir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'O rei partiu e, com ele, toda a sua família; porém, deixou dez concubinas para cuidarem do palácio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Tendo, pois, o rei saído e todo o povo após ele, pararam na última casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Todo o seu exército marchava com ele, e adiante dele iam todos os quereteus, todos os peleteus e todos os giteus; seiscentos homens que o seguiram de Gate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Então, o rei disse para Itai, o giteu: \"Por que queres ir conosco? Volta e fica com o que se tornar rei, porque és estrangeiro e exilado. Retorna ao teu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Como saíste somente ontem, por que eu deveria te fazer vagar conosco? Nem mesmo eu sei aonde estou indo; então, retorna e leva teus compatriotas de volta. Que a lealdade e a fidelidade estejam convosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Mas Itai respondeu ao rei, dizendo: \"Tão certo como Yahweh vive, e o meu senhor, o rei, vive, aonde quer que o meu senhor, o rei, vá, lá também teu servo irá, mesmo que isso signifique viver ou morrer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Então, Davi disse para Itai: \"Vai, passa adiante e continua conosco\". Assim, Itai, o giteu, o acompanhou, juntamente com os seus homens e todas as famílias que estavam com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Todo o país pranteou em alta voz enquanto passavam pelo ribeiro de Cedrom, e enquanto o próprio rei o atravessava. Todos viajavam na estrada rumo ao deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Até mesmo Zadoque e todos os levitas estavam presentes, carregando a Arca da Aliança. Eles puseram a Arca de Deus no chão e, então, Abiatar se juntou a eles. Eles esperaram até que todas as pessoas tivessem saído da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'O rei disse a Zadoque: \"Carregai a Arca de Deus de volta para a cidade. Se eu achar graça aos olhos de Yahweh, Ele me trará de volta aqui e me mostrará novamente a Arca, o lugar onde Ele mora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Mas, se Ele disser: \'Não me agrado de ti\', vê, aqui estou. Que Ele faça de mim o que Lhe aprouver\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'O rei também disse a Zadoque, o sacerdote: \"Acaso não és vidente? Retorna à cidade em paz e leva os teus dois filhos contigo: Aimaaz, teu filho, e Jônatas, filho de Abiatar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Vê, eu esperarei nos desfiladeiros do deserto até receber notícias de vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Então, Zadoque e Abiatar carregaram a Arca de Deus de volta a Jerusalém e ficaram lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Mas Davi subiu o monte das Oliveiras descalço, chorando e com a cabeça coberta. Todos os homens do povo que estavam com ele cobriram as suas cabeças e subiram chorando, enquanto caminhavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Alguém falou com Davi, dizendo: \"Aitofel está envolvido na conspiração de Absalão\". Então, Davi orou: \"Ó, Yahweh, por favor, torna o conselho de Aitofel em loucura\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Aconteceu que, quando Davi chegou ao topo da estrada, onde Deus costumava ser adorado, Husai, o arquita, veio a ele, com o seu casaco rasgado e com terra na cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Davi disse lhe disse: \"Se viajares comigo, serás um peso para mim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'mas, se retornares à cidade e disseres a Absalão: \'Serei teu servo, ó rei; como fui servo de teu pai no passado, do mesmo modo serei teu servo\', assim, confundirás o conselho de Aitofel para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Porventura, não terás os sacerdotes Zadoque e Abiatar contigo? Assim, o que ouvirdes no palácio do rei deverás contar a Zadoque e a Abiatar, os sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Vê, ali com eles estão também os seus dois filhos, Aimaaz, filho de Zadoque, e Jônatas, filho de Abiatar. Tu deverás enviar-me, pelas mãos deles, tudo quanto ouvirdes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Então, Husai, amigo de Davi, voltou para a cidade, assim que Absalão chegou e entrou em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Quando Davi havia subido uma pequena distância do topo da montanha, Ziba, o servo de Mefibosete, veio ao seu encontro com dois jumentos selados. Sobre os jumentos, havia duzentos pães, cem cachos de passas, cem cachos de figo e um recipiente de couro com vinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'O rei disse a Ziba: \"Por que trouxeste estas coisas?\". Ziba respondeu: \"Os jumentos são para o transporte da família do rei, o pão e os cachos de figo são para teus homens comerem e o vinho é para beberem aqueles que estão debilitados no deserto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'O rei disse: \"E onde está o neto de teu senhor?\". Ziba respondeu: \"Ele ficou em Jerusalém, dizendo: \'Hoje, a casa de Israel restaurará, para mim, o reino de meu pai\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Então, o rei disse a Ziba: \"Tudo o que pertencia a Mefibosete agora pertence a ti\". Ziba respondeu: \"Eu me prostro humildemente a ti, meu senhor e rei. Que eu encontre favor aos teus olhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Quando o rei Davi se aproximou de Baurim, de lá saiu um homem do clã de Saul, cujo nome era Simei, filho de Gera. Este saiu amaldiçoando enquanto andava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Atirava pedras em Davi e em todos os oficiais do rei, apesar do exército e dos guarda-costas que estavam à direita e à esquerda do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Simei gritava amaldiçoando: \"Vai embora, sai daqui, vilão sanguinário!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Yahweh retribuiu a todos vós pelo sangue da família de Saul, cujo trono tomaste. Yahweh entregou o reino nas mãos de Absalão, teu filho. Agora, tu estás arruinado, pois és um homem sanguinário\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Então, Abisai, filho de Zeruia, disse ao rei: \"Por que deveria este cachorro morto amaldiçoar meu senhor, o rei? Por favor, deixa-me ir lá e tirar a cabeça dele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Mas o rei disse: \"O que tenho convosco, filhos de Zeruia? Talvez ele esteja me amaldiçoando porque Yahweh lhe disse: \'Amaldiçoa Davi\'. Quem, então, poderia lhe dizer: \"Por que estás amaldiçoando o rei?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Então, Davi disse a Abisai e a todos os seus servos: \"Se meu filho, que foi gerado do meu corpo, quer tirar-me a vida, quanto mais este benjamita pode, agora, desejar minha ruína? Deixai-o sozinho e que amaldiçoe, pois Yahweh lhe ordenou que fizesse isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Talvez, Yahweh verá a miséria lançada sobre mim, e me retribuirá com bondade pela sua maldição deste dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Então, Davi e seus homens viajaram pela estrada, enquanto Simei o seguia, na encosta do monte, amaldiçoando e lançando areia e pedras nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Então, o rei e todas as pessoas que estavam com ele ficaram cansadas. O rei descansou quando pararam à noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Quanto a Absalão e todos os homens de Israel que estavam com ele, chegaram a Jerusalém. E Aitofel estava com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Quando Husai, o arquita, amigo de Davi, encontrou Absalão, disse-lhe: \"Vida longa para o rei! Vida longa para o rei!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalão disse a Husai: \"Esta é a tua lealdade para com teu amigo? Por que não foste com ele?\". Husai disse a Absalão:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, '\"Não. O único a quem Yahweh escolheu, assim como o povo, e todos os homens de Israel, esse é o homem a quem eu pertencerei, e permanecerei com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Também, a que homem eu deveria servir? Não deveria servir na presença de seu filho? Assim como eu servi na presença de teu pai, eu servirei em tua presença\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Então, Absalão disse a Aitofel: \"Dá-nos o teu conselho sobre o que deveríamos fazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Aitofel respondeu: \"Dorme com as concubinas de teu pai, as quais ele deixou para cuidar do palácio, e todo o Israel ouvirá que te tornaste detestável diante de teu pai. Então, as mãos de todos os que estão contigo se fortalecerão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Assim, eles armaram uma tenda para Absalão no terraço do palácio, e Absalão dormiu com as concubinas de seu pai diante dos olhos de todo o Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Os conselhos que Aitofel dava naqueles dias eram como se um homem os ouvisse da boca do próprio Deus. Assim eram vistos todos os conselhos de Aitofel, tanto por Davi como por Absalão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Então, Aitofel disse a Absalão: \"Agora, deixa-me escolher doze mil homens. Eu me levantarei e perseguirei Davi hoje à noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Irei a ele enquanto estiver cansado e o aterrorizarei; o povo que está com ele fugirá e eu atacarei somente o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Eu trarei todo o povo de volta a ti, como uma noiva que vem ao seu marido, e todo o povo estará em paz contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'O que Aitofel disse agradou a Absalão e a todos os anciãos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Capítulo 15');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Capítulo 15');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Capítulo 15');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Husai complementou: \"Tu sabes que teu pai e seus homens são guerreiros fortes, implacáveis; são como uma ursa roubada de seus filhotes em um campo. Teu pai é um homem de guerra; ele não dormirá com o exército esta noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Agora, ele provavelmente está escondido em alguma cisterna ou em um outro lugar. Acontecerá que, quando alguns dos seus homens forem mortos no começo de um ataque, qualquer um que ouvir dirá: \'Aconteceu um massacre entre os soldados que seguem Absalão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Então, até os soldados mais corajosos, os de coração como de um leão, ficarão com medo; porque todo o Israel sabe que teu pai é um homem poderoso, e que os homens que estão com ele são muito fortes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Assim, eu recomendo que todo o Israel se reúna a ti, de Dã a Berseba, tão numeroso quanto a areia que está no mar, e que tu vás à batalha pessoalmente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Então, nós iremos até ele, onde quer que se encontre, e cairemos sobre ele como o orvalho cai sobre o chão. Nós não deixaremos nem ele, nem qualquer um de seus homens vivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Se ele se refugiar em alguma cidade, então, todo o Israel trará cordas para essa cidade, e nós a arrastaremos até o rio, até que não se encontre nem uma pequena pedra lá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Absalão e os homens de Israel disseram: \"O conselho de Husai, o arquita, é melhor do que o conselho de Aitofel\". Yahweh determinara a rejeição do bom conselho de Aitofel para trazer destruição sobre Absalão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Depois, Husai disse a Zadoque e a Abiatar, os sacerdotes: \"Aitofel aconselhou Absalão e os anciãos de Israel de tal e tal maneira, mas eu o aconselhei de outra forma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Agora, vai rapidamente e avisa a Davi, dizendo: \'Não acampes hoje à noite nos desfiladeiros de Araba, mas atravessa, sem demora, ou o rei será consumido, bem como todos os que estiverem com ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jônatas e Aimaaz estavam perto de uma fonte em En-Rogel. Uma serva costumava ir e informar-lhes o que necessitavam saber, para que não fossem vistos entrando na cidade. Quando recebiam a mensagem, iam e contavam ao rei Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Mas, desta vez, um jovem os viu e contou a Absalão. Então, Jônatas e Aimaaz saíram rapidamente e foram à casa de um homem, em Baurim, que tinha um poço no seu pátio, pelo qual eles desceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'A esposa do homem tomou uma coberta, a estendeu sobre a boca do poço e jogou grãos sobre ela, para que ninguém soubesse que Jônatas e Aimaaz estavam no poço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Os homens de Absalão foram à mulher da casa e disseram: \"Onde estão Aimaaz e Jônatas?\". A mulher lhes disse: \"Eles cruzaram o rio\". Então, depois de olharem em volta e não encontrá-los, retornaram a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Depois que eles partiram, Jônatas e Aimaaz saíram do poço e foram contar ao rei Davi, e disseram: \"Levanta-te e atravessa rapidamente as águas, porque Aitofel deu tal e tal conselho a teu respeito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Então, Davi se levantou, com todas as pessoas que estavam com ele, e cruzaram o Jordão. Até o amanhecer, nenhum deles havia falhado em cruzar o Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Quando Aitofel viu que seu conselho não fora seguido, selou seu jumento e saiu. Ele foi para sua própria cidade e, em casa, colocou seus afazeres em ordem e se enforcou. Deste modo, ele morreu e foi enterrado na tumba de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Então, Davi veio a Maanaim. Quanto a Absalão, ele atravessou o Jordão e com ele todos os homens de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Então, Absalão colocou Amasa no comando do exército, no lugar de Joabe. Amasa era o filho de Jéter, o ismaelita que dormira com Abigail, filha de Naás e irmã de Zeruia, a mãe de Joabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Então, Israel e Absalão acamparam na terra de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Aconteceu que, quando Davi veio a Maanaim, Sobi, filho de Naás, de Rabá dos Amonitas, Marquir, o filho de Amiel de Lo-Debar, e Barzilai, o gileadita de Rogelim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'trouxeram esteiras para dormir, cobertores, tigelas e potes, trigo, farinha de cevada, grãos torrados, vagem, lentilhas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'mel, manteiga, ovelhas e derivados de leite, para que Davi e o povo que estava com ele pudessem comer. Esses homem haviam dito: \"O povo está faminto, cansado e sedento no deserto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Davi contou o número de soldados que estavam com ele e nomeou-lhes capitães de mil e capitães de cem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Ele enviou um terço do seu exército sob o comando de Joabe, outro terço sob o comando de Abisai, filho de Zeruia, irmão de Joabe, e ainda outro terço sob o comando de Itai, o geteu. O rei disse ao exército: \"Certamente, irei pessoalmente convosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Mas os homens lhe disseram: \"Não deverás ir à batalha, pois, se nós fugirmos, eles não se importarão conosco, ou, se metade de nós perecer, ainda não se importarão. Porém, tu és digno de dez mil de nós! Por isso, será melhor que, na cidade, tu estejas pronto para nos ajudar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Então, o rei respondeu-lhes: \"Farei o que lhes parecer melhor\". O rei estava ao lado dos portões da cidade, enquanto todo o exército saía às centenas e aos milhares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'O rei ordenou a Joabe, Abisai e Itai dizendo: \"Sede cuidadosos, por minha causa, com o jovem Absalão\". E todo o povo ouviu o rei ordenando isso aos capitães, a respeito de Absalão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Então, o exército saiu para o campo, contra Israel, e a batalha se espalhou pela floresta de Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'O exército de Israel foi derrotado ali, diante dos soldados de Davi e, naquele dia, houve um grande massacre de vinte mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'A batalha se estendeu por todas as partes do campo e mais homens foram mortos pela floresta do que pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Absalão encontrou alguns soldados do exército de Davi. Ele montava sua mula, a qual passou sob grossos galhos de um grande carvalho. Aconteceu que a cabeça de Absalão ficou presa nos galhos da árvore; ele ficou pendurado ali, entre os galhos e o chão, enquanto a mula seguiu pelo caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Alguém viu isso e disse a Joabe. \"Olha, eu vi Absalão pendurado num carvalho!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Joabe disse ao homem que lhe contara sobre Absalão: \"Tu o vistes! Por que não o abatestes, lançando-o por terra? Eu teria lhe dado dez siclos de prata e um cinto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'O homem respondeu a Joabe: \"Ainda que eu recebesse mil siclos de prata, eu não teria estendido as mãos contra o filho do rei, pois nós todos ouvimos as ordens do rei a ti, Abisai e Itai, dizendo: \'Ninguém deve tocar no jovem Absalão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Se eu arriscasse minha vida por essa desobediência (e nada fica em oculto ao rei), tu terias me abandonado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Então, Joabe disse: \"Eu não esperarei por ti\". Assim, Joabe pegou três dardos e os lançou no coração de Absalão, atravessando-o quando este ainda estava vivo, pendurado no carvalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Então, dez jovens que carregavam a armadura de Joabe cercaram Absalão e o atacaram, matando-o.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Joabe tocou a trombeta e o exército regressou da perseguição a Israel, porque Joabe o reteve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Tomaram Absalão e o lançaram numa grande cova, na floresta. Eles enterraram seu corpo sob uma grade pilha de pedras, enquanto todo o Israel fugia, cada homem para sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Ora, Absalão, quando vivo, construiu para si mesmo um grande altar no vale do rei, e disse: \"Eu não tenho filho para perpetuar a memória do meu nome\". Logo, ele colocou seu próprio nome naquele altar, que é chamado de Monumento a Absalão até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Então, Aimaaz, filho de Zadoque, disse: \"Deixa-me ir correndo ao rei para levar as boas notícias, de como Yahweh o resgatou da mão dos seus inimigos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Joabe respondeu a ele: \"Tu não serás, hoje, o portador das notícias; tu o farás em outro dia. Hoje, tu não darás nenhuma notícia porque o filho do rei está morto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Então, Joabe disse ao cuxita: \"Vai, dize ao rei o que vistes\". O cuxita curvou-se diante de Joabe e correu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Aimaaz, filho de Zadoque, disse novamente a Joabe: \"Independentemente do que possa acontecer, por favor, deixa-me também correr e seguir o cuxita\". Joabe respondeu: \"Por que tu desejas correr, meu filho, visto que não terás nenhuma recompensa pela notícia?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'E disse Aimaaz: \"Aconteça o que for, irei\". Joabe, então, respondeu: \"Corra\". Aimaaz correu pelo caminho da planície e ultrapassou o cuxita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Davi estava sentado entre os portões internos e externos. O sentinela subiu ao telhado do portão e levantou seus olhos por cima dos muros. Quando olhou, viu um homem se aproximando, correndo sozinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'O sentinela anunciou e disse ao rei. Então, o rei disse: \"Se ele está só, deve haver notícias em seus lábios\". O corredor se aproximou da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Logo, o sentinela viu outro homem correndo, e o sentinela anunciou ao vigia do portão. Ele disse: \"Olha, há outro homem correndo sozinho\". O rei disse: \"Ele está trazendo notícias também\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'O sentinela, disse: \"Eu penso que o homem que corre na frente se parece com Aimaaz, filho de Zadoque\". O rei disse: \"Ele é um homem bom e está vindo com boas notícias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Então, Aimaaz chamou o rei: \"Está tudo bem\". E ele se curvou diante do rei com seu rosto na terra e disse: \"Bendito seja Yahweh teu Deus! Ele entregou os homens que se levantaram contra meu senhor, o rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Então, o rei respondeu: \"Está tudo bem com o jovem Absalão?\". Aimaaz respondeu: \"Quando Joabe, o servo do rei, me enviou a ti, rei, eu vi uma grande confusão, mas eu não sabia o que era\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'O rei disse: \"Fica aqui ao lado\". Então, Aimaaz aguardou ali ao lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Imediatamente, o cuxita chegou e disse: \"Tenho boas notícias ao meu senhor, o rei, pois hoje Yahweh te vingou de todos os que se levantaram contra ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'O rei, então, disse ao cuxita: \"Está tudo bem com o jovem Absalão?\". O cuxita respondeu: \"Os inimigos do meu senhor, o rei, e todos os que se levantaram contra ti para fazer-te mal sejam como aquele jovem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Então, o rei ficou profundamente abalado, subiu aos aposentos acima do portão e chorou. Andando de um lado para outro, lamentava: \"Meu filho Absalão, meu filho, meu filho Absalão! Meu desejo é que eu tivesse morrido em teu lugar, Absalão, meu filho, meu filho!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Disseram a Joabe: \"Vê, o rei está pranteando e lamentando por Absalão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Assim, a vitória daquele dia transformou-se em lamento para todo o exército, pois ouviram dizer: \"O rei está chorando por seu filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Naquele dia, os soldados tiveram que entrar sorrateiramente na cidade, como povo que foge envergonhado de uma batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'O rei cobriu seu rosto e clamava em alta voz: \"Meu filho Absalão, Absalão, meu filho, meu filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Então, Joabe entrou na casa do rei e lhe disse: \"Tu envergonhaste os teus soldados hoje, que salvaram a tua vida e a vida dos teus filhos e filhas, e a vida de tuas esposas e de tuas concubinas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'porque amas aqueles que te odeiam, e odeias aqueles que te amam. Pois, hoje, tu demonstraste que comandantes e soldados não significam nada para ti. Acredito que, hoje, se Absalão tivesse vivido e nós todos tivéssemos morrido, isso teria te agradado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Agora, pois, levanta-te e vai e fala bondosamente a teus soldados; porque, juro por Yahweh, se não fores, nenhum homem permanecerá contigo esta noite. Isto seria pior para ti do que todos os desastres que te aconteceram, desde a tua mocidade até agora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Então, o rei se levantou e sentou-se no portão da cidade. Foi avisado a todos os homens: \"Vede, o rei está sentado no portão\". Então, o povo veio diante do rei. Os israelitas haviam fugido, cada homem para sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Todo o povo estava discutindo entre si por todas as tribos de Israel, dizendo: \"O rei nos resgatou das mãos dos nossos inimigos\". Ele nos livrou das mãos dos filisteus, mas fugiu da terra por causa de Absalão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'E Absalão, a quem ungimos sobre nós, foi morto na batalha. Então, por que não estamos considerando trazer o rei de volta?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'O rei Davi mandou dizer aos sacerdotes Zadoque e a Abiatar: \"Falai aos anciãos de Judá: \'Por que sois os últimos a trazer o rei de volta para o palácio, uma vez que os comentários de todo o Israel são favoráveis ao rei para que volte ao palácio?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Vós sois meus irmãos, minha carne e meus ossos. Por que, então, sois os últimos a trazer de volta o rei?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Dizei a Amasa: \'Não és minha carne e meus ossos? Que Deus me castigue, ainda mais, se eu não te tornar o comandante do meu exército no lugar de Joabe\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'E ele conquistou o coração de todos os homens de Judá, como se fossem o coração de um só homem, de forma que disseram ao rei: \"Retornai, tu e todos os teus homens\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Então, o rei retornou e veio para o Jordão. E os homens de Judá vieram para Gilgal para encontrarem-se com o rei e acompanhá-lo na travessia do Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Simei, filho de Gera, benjamita, que era de Baurim, apressou-se com os homens de Judá para encontrar o rei Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Estavam com ele mil homens de Benjamim, também Ziba, o servo de Saul, seus quinze irmãos e vinte servos. Eles atravessaram o Jordão na presença do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Eles atravessaram para trazer a família do rei e para fazer o que ele desejasse. Simei, filho de Gera, prostrou-se diante do rei antes que ele começasse a atravessar o Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Simei disse ao rei: \"Meu senhor, não julgues teu servo culpado, nem traga à memória os atos que teu criado teimosamente fez naquele dia em que meu senhor, o rei, deixou Jerusalém. Porque o teu servo sabe que pecou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'É por esta razão que, hoje, eu venho diante de ti, como o primeiro da família de José, para encontrá-lo, meu senhor, rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Mas Abisai, filho de Zeruia, respondeu: \"Não deveria Simei ser condenado à morte por isso, por que ele amaldiçoou o ungido de Yahweh?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Então, Davi disse: \"O que tenho convosco, filhos de Zeruia, para que, agora, sejais meus adversários? Alguém será condenado hoje em Israel? Não sei eu que sou o rei de Israel?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Então, o rei disse a Simei: \"Tu não morrerás\". Isto o rei lhe prometeu com um juramento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Mefibosete, filho de Jônatas, filho de Saul, desceu para encontrar-se com o rei. Ele não se barbeou, nem lavou seus pés e suas vestes desde o dia em que o rei partiu até o dia em que voltou em paz para casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Quando ele veio para Jerusalém para encontrar o rei, este lhe perguntou: \"Por que não foste comigo, Mefibosete?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Ele respondeu: \"Meu senhor, ó rei, meu servo enganou-me, pois eu disse: \'Selarei um burro para montar nele e ir com o rei\', porque teu servo é aleijado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Meu servo Ziba me difamou diante do meu amado rei. Mas meu senhor, o rei, é como um anjo de Deus. Portanto, faze o que parecer bem aos teus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Porque toda a casa de meu pai foi morta diante do meu senhor, o rei, mas tu colocaste teu servo entre todos os que comem em tua mesa. Que direito, portanto, teria eu de reclamar alguma coisa ao rei?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Então, o rei lhe disse: \"Por que explicar mais alguma coisa? Eu decidi que tu e Ziba dividireis as terras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Então, Mefibosete respondeu ao rei: \"Deixa que ele fique com tudo. Para mim, importa que meu senhor, o rei, tenha voltado para casa em segurança\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Barzilai, o gileadita, desceu de Rogelim e atravessou o Jordão com o rei, acompanhando-o até o outro lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Barzilai era, agora, um ancião de oitenta anos. Ele havia provido o rei com bens enquanto este esteve em Maanaim, pois era um homem muito rico.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'O rei disse a Barzilai: \"Vem comigo e eu providenciarei para que fiques comigo em Jerusalém\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Barzilai respondeu ao rei: \"Quantos dias me restam na vida, para que eu vá com o rei para Jerusalém?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Tenho oitenta anos. Ainda posso distinguir entre o bem e o mal? Pode o teu servo sentir o sabor do que come ou bebe? Ainda posso ouvir a voz de cantores ou cantoras? Por que, então, deveria teu servo ser um peso para meu senhor, o rei?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Teu servo queria apenas atravessar o Jordão com o rei. Por que deveria o rei me recompensar com tão grande galardão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Por favor, deixa teu servo retornar ao lar para que possa morrer em minha própria cidade, diante do túmulo do meu pai e da minha mãe. Mas, vê, aqui está teu servo Quimã. Deixa-o atravessar com meu senhor, o rei, e faze-lhe o que te parecer bom\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'O rei respondeu: \"Quimã irá comigo, e farei com ele o que parecer bom para ti; e tudo o que desejares de mim, eu farei a ti.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Então, todo o povo atravessou o Jordão e o rei também o fez; o rei beijou Barzilai e o abençoou. Então, Barzilai retornou para sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Então, o rei atravessou para Gilgal e Quimã atravessou com ele. Todo o exército de Judá e também metade do exército de Israel, trouxeram o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Logo, todos os homens de Israel começaram a vir ao rei e dizer-lhe: \"Por que nossos irmãos, homens de Judá, te roubaram de nós e trouxeram o rei e sua família além do Jordão e todos os homens de Davi com eles?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Então, os homens de Judá responderam aos homens de Israel: \"É porque o rei tem mais intimidade conosco. Por que estais com raiva disso? Comemos algo às custas do rei? Ele nos deu presentes?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Os homens de Israel responderam aos homens de Judá: \"Temos dez tribos aparentadas com o rei; por isso, temos mais direitos a Davi que vós. Então, por que nos desprezastes? Não era nosso propósito primeiro trazer nosso rei para ser ouvido?\". Mas as palavras dos homens de Judá foram ainda mais severas que as dos homens de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Aconteceu de estar no mesmo lugar um homem problemático, cujo o nome era Sebá, filho de Bicri, um benjamita. Ele tocou a trombeta e disse: \"Nós não temos parte com Davi, nem temos herança alguma com o filho de Jessé. Que todos os homens voltem às suas casas, Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Então, todos os homens de Israel deixaram Davi e seguiram Sebá, filho de Bicri. Mas os homens de Judá seguiram de perto o seu rei, desde o Jordão até Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Quando Davi veio ao seu palácio em Jerusalém, ele tomou as dez concubinas que havia deixado para cuidar do palácio, e as colocou em uma casa, sob guarda. Ele provia suas necessidades, mas não dormiu mais com elas. Então, elas ali ficaram até o dia de suas mortes, vivendo como se fossem viúvas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Então, o rei disse a Amasa: \"Convoca os homens de Judá dentro de três dias; Tu deverás estar aqui, também\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Então, Amasa foi convocar os homens de Judá, mas ele ficou mais tempo do que o rei havia lhe ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Então, Davi disse a Abisai: \"Agora, Sebá, filho de Bicri, nos fará mais mal do que Absalão nos fez. Pega os servos do teu senhor, meus soldados, e o persiga, ou ele encontrará cidades fortificadas e escapará de nossa vista\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Então, os homens de Joabe, junto com os quereteus e os peleteus, e todos os guerreiros poderosos foram atrás de Sebá. Eles deixaram Jerusalém para perseguir o filho de Bicri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Quando eles estavam na pedra grande que fica em Gibeão, Amasa foi encontrá-los. Joabe estava vestindo a armadura, a qual incluía um cinto ao redor da sua cintura com uma espada embainhada a ela. Enquanto ele andava, a espada caiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Então, Joabe disse a Amasa: \"Está tudo bem contigo, meu primo?\". Joabe pegou Amasa pela barba, com a mão direita, para beijá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Amasa não notou o punhal que estava na mão esquerda de Joabe. Joabe apunhalou Amasa no estômago e suas entranhas derramaram-se no chão. Joabe não o atingiu novamente, e Amasa morreu. Então, Joabe e Abisai, seu irmão, perseguiram Sebá, filho de Bicri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Um dos homens de Joabe ficou ao lado de Amasa, e disse: \"Quem é a favor de Joabe e quem é a favor de Davi, siga Joabe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasa se revolvia sobre o seu próprio sangue no meio da estrada. Quando o homem viu que as pessoas ficavam paradas, ele carregou Amasa da estrada para dentro de um campo. Então, jogou uma capa sobre ele, porque viu que todas as pessoas que passavam por ali paravam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Depois que Amasa foi removido da estrada, todos os homens seguiram Joabe na perseguição de Sebá, filho de Bicri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Sebá passou por todas as tribos de Israel até Abel de Bete-Maaca, e por toda a terra dos beritas. Os beritas se reuniram e seguiram Sebá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Joabe e seus homens o alcançaram e o cercaram em Abel de Bete Maaca. Eles construíram uma rampa junto ao muro da cidade, e todo o exército que estava com Joabe bateu contra o muro para derrubá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Então, uma sábia mulher gritou de dentro da cidade: \"Ouve, por favor! Ouve, Joabe! Vem perto de mim para que eu possa falar contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Então, Joabe chegou próximo a ela, e a mulher disse: \"És tu, Joabe?\". Ele respondeu: \"Sou eu\". Então, ela lhe disse: \"Ouve as palavras da tua serva\". Ele respondeu: \"Estou ouvindo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Ela continuou: \"Eles costumavam dizer antigamente: \'Procura por conselhos em Abel\', e aquele conselho resolveria o problema.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Nós somos uma das cidades mais pacíficas e fiéis em Israel. Tu estás tentando destruir uma cidade que é mãe em Israel. Por que tu queres devorar a herança de Yahweh?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Joabe respondeu: \"Longe de mim, longe de mim que eu devore ou destrua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Isto não é verdade. Mas um homem dos montes de Efraim, chamado Sebá, filho de Bicri, tem levantado a sua mão contra o rei, contra Davi. Entrega-me esse homem e eu me retirarei da cidade\". A mulher disse a Joabe: \"A cabeça dele será jogada a ti por sobre o muro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'E a mulher, com sua sabedoria, foi a todo o povo. Eles cortaram fora a cabeça de Sebá, filho de Bicri, e a jogaram para Joabe. Então, ele tocou a trombeta e os homens de Joabe saíram da cidade, cada um para a sua casa. E Joabe retornou a Jerusalém, para o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Joabe comandava todo o exército de Israel, e Benaia, filho de Joiada, comandava os quereteus e os peleteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adorão era comandante dos homens que faziam trabalhos forçados, e Josafá, filho de Ailude, era o cronista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Seva era escriba e Zadoque e Abiatar eram sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Ira, o jairita, era ministro-chefe de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'No tempo do reinado de Davi, houve fome por três anos consecutivos, e Davi buscou a face de Yahweh. Então, Yahweh disse: \"Essa fome está sobre vós por causa de Saul e sua família assassina, que matou os gibeonitas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Os gibeonitas não pertenciam ao povo de Israel, eles eram remanescentes dos amorreus. O povo de Israel jurou não matá-los, mas, mesmo assim, Saul, em seu zelo pelo povo de Israel e Judá, tentou matar todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Então, o rei Davi reuniu os gibeonitas e disse-lhes: \"O que eu posso fazer por vós? Como posso fazer expiação, para que abençoeis o povo de Yahweh, que herda Sua bondade e promessas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Os gibeonitas responderam: \"Não se trata de prata ou ouro entre nós e Saul ou sua família. E não compete a nós matar ninguém em Israel\". Davi respondeu: \"O que quereis que vos faça?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Eles responderam ao rei: \"O homem que tentou nos matar, que planejou contra nós para que fôssemos destruídos e ficássemos sem lugar dentro das fronteiras de Israel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'deixa que sete homens de seus descendentes nos sejam entregues, e os enforcaremos diante de Yahweh, em Gibeá de Saul, o escolhido de Yahweh\". Então, o rei disse: \"Eu os entregarei a vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Mas o rei poupou Mefibosete, filho de Jônatas, filho de Saul, por causa do juramento, feito perante Yahweh, entre Davi e Jônatas, filho de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Assim, o rei tomou os dois filhos de Rispa, filha de Aías, filhos que ela concebeu de Saul — os nomes dos dois filhos eram Armoni e Mefibosete; e Davi também pegou os cinco filhos de Mical, filha de Saul, que ela tivera com Adriel, filho de Barzilai, o meolatita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'O rei os entregou nas mãos dos gibeonitas e eles os enforcaram no monte, diante de Yahweh, e todos os sete morreram juntos. Eles foram mortos durante a época da colheita, nos primeiros dias do início da colheita da cevada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Então, Rispa, filha de Aías, pegou um pano de saco e o estendeu para si sobre o monte ao lado dos corpos, desde o início da colheita, até que a chuva caiu sobre os corpos. Ela não permitiu que as aves do céu se aproximassem dos corpos durante o dia, nem animais selvagens à noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Foi dito a Davi o que Rispa, filha de Aías, a esposa escrava de Saul, havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Então, Davi tomou os ossos de Saul e os de seu filho Jônatas. Davi os tomou dos homens de Jabes Gileade que os havia furtado da praça de Bete-Seã, onde os filisteus haviam pendurado seus corpos, após os filisteus terem matado Saul, em Gilboa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Davi levou dali os ossos de Saul e os ossos de seu filho Jônatas, e também juntaram os ossos dos sete homens que foram enforcados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'Eles enterraram os ossos de Saul e de seu filho Jônatas na terra de Benjamim, em Zela, na sepultura de Quis, seu pai. Eles fizeram tudo que o rei ordenou. Depois disso, Deus respondeu suas orações em favor da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Os filisteus foram à guerra outra vez contra Israel. Davi foi com o seu exército e lutou contra os filisteus. Davi ficou cansado pela fadiga da batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Isbi-Benobe, um descendente de gigantes, tinha uma lança que pesava trezentos ciclos de bronze; ele estava armado com uma espada nova e tentou matar Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Mas Abisai, filho de Zeruia, socorreu Davi, atacou o filisteu e o matou. Então, os homens de Davi juraram para ele, dizendo: \"Nunca mais sairás à batalha conosco, para que tu não apagues a lâmpada de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Depois disso, houve outra batalha contra os filisteus, em Gobe, quando Sibecai, o husatita, matou Safe, que era um dos descendentes de Refaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Numa outra batalha contra os filisteus, em Gobe, Elanã, filho de Jaaré-Oregim, o belemita, matou Golias, o geteu, cuja lança parecia com uma lançadeira de tecelão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Houve mais outra batalha em Gate, onde estava um homem de grande estatura que tinha seis dedos em cada mão e seis dedos em cada pé: vinte e quatro ao todo. Ele também era descendente de Refaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Quando ele desafiou Israel, Jônatas, filho de Simei, irmão de Davi, o matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Esses eram descendentes de Refaim, de Gate, e eles foram mortos pelas mãos de Davi e pelas mãos de seus soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Davi louvou a Yahweh, com as palavras desta canção, quando Yahweh o livrou das mãos de todos os seus inimigos e da mãos de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Orou Davi dizendo: \"Yahweh é meu rochedo, minha fortaleza e meu libertador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Deus é minha rocha; Nele eu me refugio. Ele é meu escudo e a força da minha salvação, minha fortaleza e meu refúgio, Aquele que me livra da violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Clamarei a Yahweh, que é digno de louvor, e serei salvo dos meus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Pois as ondas da morte me cercaram; as ondas impetuosas da destruição me submergiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Os cordões do Sheol me cercaram; as armadilhas de morte me prenderam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Na minha angústia, clamei a Yahweh; clamei ao meu Deus e, do Seu Templo, Ele ouviu a minha voz, e meu clamor por socorro subiu até os Seus ouvidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Então, a terra sacudiu e tremeu. Os fundamentos dos céus tremeram e foram abalados, porque Deus estava irado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Das Suas narinas, subiu fumaça, e fogo abrasador saiu de Sua boca; e essas brasas ficaram em chamas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Ele abriu os céus e desceu, e, debaixo dos Seus pés, havia densas trevas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Ele montou num querubim e voou. Ele foi visto voando nas asas do vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Fez das trevas uma tenda ao redor Dele, ajuntando densas nuvens de chuva no firmamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Do relâmpago, diante Dele, caíram brasas de fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Yahweh trovejou dos céus. O Altíssimo bradou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Ele atirou flechas e espalhou Seus inimigos com raios, e os dispersou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Então, surgiram os canais de água; os fundamentos do mundo foram expostos ao brado de guerra de Yahweh, ao estrondo do sopro de Suas narinas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Das alturas, estendeu Sua mão e me segurou! Ele me tirou das águas profundas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Ele me resgatou do meu inimigo poderoso, daqueles que me odiavam, pois eles eram demasiadamente fortes para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Eles vieram contra mim no dia da minha angústia, mas Yahweh foi meu suporte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Ele também me levou a um lugar espaçoso e me salvou porque Se agradou de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Yahweh me recompensou conforme minha justiça; me restaurou conforme a pureza das minhas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Pois tenho guardado os caminhos de Yahweh e não ajo perversamente, desviando-me do meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Pois todos os Seus atos de justiça têm estado diante de mim; acerca dos Seus estatutos, não me desviei deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Eu fui inocente diante Dele e tenho me afastado do pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Por isto, Yahweh me restaurou segundo a minha justiça, segundo a minha pureza de coração diante dos Seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Ao fiel, Tu te mostras fiel; ao homem íntegro, Tu te mostras íntegro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Com o puro de coração, Tu te mostras puro; porém, Tu te mostras implacável com o perverso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Tu livras o aflito, mas os Teus olhos estão contra o soberbo para humilhá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Pois Tu, Yahweh, és minha lâmpada. Yahweh ilumina minha escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Pois Contigo, eu posso pular uma barreira; com meu Deus, eu posso saltar uma muralha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Quanto a Deus, Seu caminho é perfeito. A palavra de Yahweh é pura. Ele é escudo para todos os que Nele se refugiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Pois quem é Deus senão Yahweh? E quem é rocha senão nosso Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Deus é o meu refúgio e Ele conduz o justo no Seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Ele faz meus pés velozes como os da corça e me põe sobre as montanhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Ele treina minhas mãos para a guerra e meus braços para vergar um arco de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Tu me deste o escudo da Tua salvação, e o Teu favor me fez grande.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Tu fizeste um amplo lugar debaixo dos meus pés, para que eles não escorreguem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Eu persegui meus inimigos e os destruí. Não recuei até que eles foram derrotados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Eu os devorei e os despedacei; eles não conseguiram se levantar; eles caíram debaixo dos meus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Tu me fortaleceste para a batalha; subjugaste debaixo dos meus pés aqueles que se levantaram contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Tu me deste o pescoço dos meus inimigos; eu aniquilei os que me odeiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Eles suplicaram por ajuda, mas ninguém os socorreu; eles gritaram por Yahweh, mas Ele não os respondeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Eu os despedacei e fiz deles como poeira no chão. Eu os amassei como lama nas ruas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Tu também me resgataste das contendas do meu próprio povo. Tu tens me mantido por cabeça das nações. Um povo que não conheci, me serve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Estrangeiros foram obrigados a me reverenciar. Tão logo eles ouviram a meu respeito, me obedeceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Os estrangeiros saíram tremendo de suas fortalezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Yahweh vive! Seja exaltada a minha Rocha! Seja Deus exaltado, a Rocha da minha salvação!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Este é o Deus que executa vingança em meu favor; Aquele que sujeita povos a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Ele me liberta dos meus inimigos. Na verdade, Tu me ergueste acima daqueles que se levantaram contra mim. Tu me resgatas do homem violento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Por isso, eu Te darei graças, ó Yahweh, entre as nações; cantarei louvores ao Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Deus concede grande vitória ao Seu rei, e Ele revela Sua aliança de lealdade ao Seu ungido, a Davi e aos seus descendentes, para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Estas são as últimas palavras de Davi — Davi, filho de Jessé, o homem que foi altamente honrado, aquele que foi ungido pelo Deus de Jacó, o amável salmista de Israel:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, '\"O Espírito de Yahweh falou por mim, e Sua palavra estava em minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'O Deus de Israel falou, a Rocha de Israel me disse: \'Aquele que governa corretamente sobre os homens, que governa no temor de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'é como a luz da manhã quando o sol nasce, como uma manhã sem nuvens, quando a tenra grama nasce na terra, através da brilhante luz do sol, depois da chuva\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'De fato, minha família não é assim diante de Deus? Não fez Ele um pacto eterno comigo, ordenando segurança por todo o caminho? Não me dará Ele êxito?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Porém, o indigno será como espinhos para serem lançados fora, porque não podem ser colhidos com as mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'O homem que os tocar deve usar uma ferramenta de ferro, ou o cabo de uma lança. Devem ser queimados onde se encontram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Estes são os nomes dos soldados de elite de Davi: Josebe-Bassete, o taquemonita, era o líder dos soldados de elite; ele matou oitocentos homens em certa ocasião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Depois dele, estava Eleazar, filho de Dodô, um dos três poderosos homens de Davi. Estava presente quando desafiaram os filisteus que haviam se concentrado para batalhar, quando os homens de Israel retrocederam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Eleazar se levantou e combateu os filisteus até sua mão ficar cansada, e ficar grudada no cabo de sua espada. Yahweh trouxe uma grande vitória naquele dia. O exército retornou após Eleazar, apenas para despojar os corpos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Depois dele, era Samá, filho de Agé, o hararita. Os filisteus se concentraram onde havia um campo de lentilhas, e o exército fugiu deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Porém, Samá se levantou no meio do campo e o defendeu. Ele matou os filisteus, e Yahweh trouxe grande vitória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Três dos trinta soldados desceram a Davi no tempo da colheita, na caverna de Adulão. O exército dos filisteus estava acampado no vale de Refaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'Naquele tempo, Davi estava em sua fortaleza, uma caverna, enquanto os filisteus se estabeleceram em Belém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Davi estava desejoso por água, e disse: \"Se ao menos alguém me desse água para beber do poço em Belém, o poço que está perto do portão!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Então, esses três poderosos homens romperam por entre o exército dos filisteus, e tiraram água do poço de Belém, o poço do portão. Pegaram a água e a levaram a Davi; este, porém, recusou-se a beber. Ao invés disso, ele a derramou para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Então, ele disse: \"Longe de mim, Yahweh, que eu fizesse isso. Deveria eu beber o sangue de homens que arriscaram suas vidas?\". Assim, ele se recusou a beber. Essas são coisas que os três homens poderosos fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abisai, irmão de Joabe e filho de Zeruia, era o capitão sobre os três. Uma vez, combateu com sua lança contra trezentos homens, e os matou. Foi mencionado muitas vezes com os três soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Não era ainda mais famoso do que os três? Foi feito capitão deles. De qualquer forma, sua fama não se igualava à fama dos três soldados mais famosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Benaia, de Cabzeel, era filho de Joiada; ele era um homem forte que realizou poderosos feitos. Matou os dois filhos de Ariel, de Moabe. Também desceu em uma cova e matou um leão, enquanto nevava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Matou um homem egípcio muito grande. O egípcio tinha uma lança em sua mão, e Benaia o combateu com apenas um cajado. Ele arrancou a lança da mão do egípcio, e o matou com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Benaia, filho de Joiada, realizou esses feitos e foi nomeado ao lado dos três homens poderosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Foi mais estimado que os trinta soldados em geral, mas não foi tão estimado quanto os três soldados de elite. Ainda assim, Davi o colocou encarregado de sua guarda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Os trinta incluíam os seguintes homens: Asael, irmão de Joabe; Elanã, filho de Dodô, de Belém;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samá, o harodita; Elica, o harodita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Heles, o paltita; Ira, filho de Iques, o tecoíta;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiezer, o anatotita; Mebunai, o husatita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Zalmom, o aoíta; Maarai, o netofatita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Helebe, filho de Baaná, o neofatita; Itai, filho de Ribai, de Gibeá, dos filhos de Benjamin;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaia, o piratonita; Hidai, do ribeiro de Gaás;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abi-Albom, o arbatita; Azmavete, o barumita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eliaba, o saalbonita; os filhos de Jasém; Jônatas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Sama, o hararita; Aião, filho de Sarar, o hararita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifelete, filho de Aasbai, o maacatita; Eliã, filho de Aitofel, o gilonita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hezrai, o carmelita; Paarai, o arbita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Igal, filho de Natã, de Zobá; Bani da tribo de Gade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Zeleque, o amonita; Naarai, o beerotita, o carregador de armas de Joabe, filho de Zeruia;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira, o itrita; Garebe, o itrita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Urias, o heteu — trinta e sete ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Novamente, a ira de Yahweh se acendeu contra Israel, e incitou Davi contra eles, dizendo: \"Vai, faz a contagem em Israel e Judá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'O rei disse a Joabe, comandante do exército, que estava com ele: \"Vai a todas as tribos de Israel, desde Dã até Berseba, e conta todo o povo; assim, saberás o número total de homens capacitados para a batalha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Joabe disse ao rei: \"Que Yahweh, teu Deus, multiplique cem vezes o número de pessoas e que os olhos do meu senhor, o rei, vejam isto acontecer. Porém, por que meu rei quer isto?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Mesmo assim, a palavra do rei foi contra Joabe e contra os comandantes do exército. Então, Joabe e os comandantes saíram da presença do rei para contar o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Eles atravessaram o Jordão e acamparam perto de Aroer, num vale ao sul da cidade. Viajaram por Gade até Jazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Foram a Gileade e para a terra de Cades dos heteus, e depois dali, foram para Da-Jaã e rodearam até Sidom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Depois, foram à fortaleza de Tiro e a todas as cidades dos heveus e dos cananeus; foram a Berseba, ao sul de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Quando eles passaram por toda a terra, voltaram para Jerusalém ao final de nove meses e vinte dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Então, Joabe apresentou ao rei o total da contagem dos guerreiros. Havia ali oitocentos mil homens valentes que usavam a espada, e quinhentos mil em Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Mas o coração de Davi se entristeceu depois de ter feito a contagem dos homens. Ele disse a Yahweh: \"Pequei gravemente por fazer isto. Agora, Yahweh, perdoa o Teu servo, porque o que fiz foi uma loucura\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Quando Davi se levantou pela manhã, a palavra de Yahweh veio ao profeta Gade, vidente de Davi, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, '\"Vai e dize a Davi: \'Assim diz Yahweh: Eu te dou três escolhas; escolhe uma delas\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Então, Gade foi a Davi e lhe disse: \"Preferes três anos de fome na tua terra? Ou três meses de perseguição dos teus inimigos? Ou três dias de peste na tua terra? Decide qual é a resposta que vou dizer a quem me enviou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Então, disse Davi a Gade: \"Estou com uma grande angústia. Prefiro que caiamos nas mãos de Yahweh, melhor do que nas mãos dos homens, porque Suas misericórdias são muitas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Então, Yahweh enviou a peste sobre Israel, de manhã até o tempo determinado, e morreram setenta mil homens do povo, desde Dã até Berseba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Quando o anjo estendeu a sua mão sobre Jerusalém para destruí-la, Yahweh se arrependeu, por causa do prejuízo que iria causar, e disse ao anjo que estava destruindo o povo: \"Basta! Agora, retira tua mão\". Naquela hora, o Anjo de Yahweh estava ao longo da eira de Araúna, o jebuseu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Davi falou a Yahweh, quando viu o anjo que havia atacado o povo, e disse: \"Pequei e agi irresponsavelmente. Mas estas ovelhas o que fizeram? Por favor, castiga a mim e à família do meu pai!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Então, naquele dia, Gade veio a Davi e lhe disse: \"Vai e levanta um altar para Yahweh na eira de Araúna, o jebuseu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Então, Davi fez conforme Gade lhe instruiu, assim como Yahweh ordenara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Araúna viu o rei e seus soldados se aproximando; então, saiu e se prostrou ao rei, com o rosto no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Então, disse Araúna: \"Por que veio o rei, meu senhor, a teu servo?\". Davi respondeu: \"Para comprar a tua eira, assim poderei levantar um altar para Yahweh, para que a peste seja removida do povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Araúna disse a Davi: \"Toma-a como tua propriedade, meu senhor e rei; faz com ela o que bem lhe parecer. Vê, aqui estão os bois para oferecer, e o debulhador e a madeira para a lenha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Tudo isto, meu rei, eu, Araúna, darei a ti\". Disse ele ainda: \"Yahweh, teu Deus, se agrade de ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'O rei disse a Araúna: \"Não. Eu insisto em comprar pelo seu valor. Não oferecerei a Yahweh holocausto que não me custou nada\". Assim, Davi comprou a eira e os bois por cinquenta ciclos de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Davi construiu o altar a Yahweh e ofereceu o holocausto e a oferta queimada. Assim, Yahweh tornou-Se favorável para com a terra, e a peste parou em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'O rei Davi já estava velho e avançado em idade. Eles o cobriam com cobertores, mas ele não conseguia se manter aquecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Então, seus servos disseram a ele: \"Deixa que procuremos uma jovem virgem, para nosso mestre, o rei; que ela sirva ao rei e cuide dele, que ela deite em seus braços, para que o rei se mantenha aquecido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Então eles procuraram uma linda moça dentro de todas as fronteiras de Israel. Eles encontraram Abisague, a sunamita, e a levaram para o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'A moça era muito bonita. Ela serviu o rei e cuidou dele, mas o rei não teve relações sexuais com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Naquele tempo, Adonias, filho de Hagite, exaltava a si mesmo, dizendo: \"Eu serei o rei\". Então preparou para si carruagens e cavaleiros, com cinquenta homens, que corressem adiante dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Seu pai nunca o tinha confrontado, dizendo: \"Por que fizeste isto ou aquilo?\". Adonias era também um homem muito bonito, e nasceu depois de Absalão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Ele discutiu seus planos com Joabe, filho de Zeruia, e com Abiatar, o sacerdote. Eles seguiram Adonias e o ajudaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Mas Zadoque, o sacerdote, Benaia, filho de Joiada, o profeta Natã, Simei, Reí, e os homens poderosos que pertenciam a Davi não seguiram a Adonias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Adonias sacrificou, junto à pedra de Zoe-lete que está junto a En-Rogel, ovelhas, bois, e bezerros engordados. Ele convidou todos os seus irmãos, os filhos do rei, e todos os homens de Judá, os servos do rei;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'mas ele não convidou o profeta Natã, Benaia, os homens poderosos, e nem seu irmão, Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Então Natã falou com Bate-Seba, mãe de Salomão, dizendo: \"Tu não ouviste que Adonias, filho de Hagite, tornou-se rei; e Davi, nosso senhor, não sabe disso?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Agora, portanto, deixa-me te dar um conselho, para que salves a tua própria vida, e a vida de teu filho, Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Vai até o rei Davi, e dize-lhe: \'Meu senhor, o rei, tu não juraste a tua serva dizendo: \'Certamente, teu filho, Salomão, reinará depois de mim, e, ele sentará no meu trono?\' Por que, então, está Adonias reinando?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Enquanto tu estiveres ali falando com o rei, eu entrarei depois de ti, e confirmarei tuas palavras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Então Bate-Seba entrou no quarto do rei. O rei estava muito velho, e Abisague, a sunamita, estava servindo o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Bate-seba se inclinou e se prostrou perante o rei. E o rei disse: \"O que desejas?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Ela disse-lhe: \"Meu mestre, tu juraste à tua serva por Yahweh, teu Deus, dizendo: \'Certamente, Salomão, teu filho, reinará depois de mim e sentará no meu trono\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Agora veja, Adonias é rei, e tu, meu senhor, o rei, não sabes disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Ele sacrificou bois, bezerros engordados, e ovelhas em abundância, e convidou todos os filhos do rei, Abiatar (o sacerdote), e Joabe (o capitão do exército), mas ele não convidou Salomão, teu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Porém, meu mestre, o rei, os olhos de todo Israel estão em ti, esperando que tu digas a eles quem vai sentar no trono, depois de ti, meu senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'De outro modo, quando meu senhor, o rei, repousar com seus pais, eu e meu filho Salomão seremos considerados criminosos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Enquanto ela ainda falava com o rei, o profeta Natã entrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Os servos disseram ao rei: \"O profeta Natã está aqui\". Quando ele veio diante do rei, prostrou-se perante o rei com seu rosto no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Natã disse: \"Meu senhor, o rei, tu disseste: \'Adonias reinará depois de mim, e sentará no meu trono?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Pois ele desceu hoje e sacrificou bois, bezerros engordados, e ovelhas em abundância, e convidou todos os filhos do rei, os capitães do exército, e Abiatar, o sacerdote. Eles estão comendo e bebendo diante dele, e dizendo: \'Viva o rei Adonias!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mas, quanto a mim, teu servo, Zadoque (o sacerdote), Benaia (filho de Joiada) e o teu servo Salomão, ele não nos convidou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Meu senhor, o rei, tu fizeste isso sem contar a nós, teus servos, quem sentaria no trono depois de ti?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Então o rei Davi respondeu a ele, e disse: \"Chama Bate-Seba de volta a mim\". Ela veio até a presença do rei, e ficou em pé diante dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'O rei fez um juramento, dizendo: \"Assim como vive Yahweh, que me redimiu de toda angústia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'assim como eu te jurei por Yahweh, o Deus de Israel, dizendo: \'Salomão, teu filho, reinará depois de mim e sentará no meu trono, no meu lugar\'. Eu farei isso hoje!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Então Bate-Seba inclinou seu rosto no chão, e se prostrou diante do rei, e disse: \"Que meu senhor, o rei Davi, viva para sempre!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'O rei Davi disse: \"Chamai a mim Zadoque (o sacerdote), Natã (o profeta), e Benaia (filho de Joiada)\". Então, eles vieram perante o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'O rei lhes disse: \"Levai convosco os servos de vosso mestre e fazei com que Salomão, meu filho, monte em minha própria mula, e levai-o para Giom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Deixai que o sacerdote Zadoque e o profeta Natã o unjam rei sobre Israel, e tocai a trombeta, e dizei: \'Viva o rei Salomão!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Então vinde vós depois dele, e ele virá e se sentará no meu trono, pois ele será rei no meu lugar. Eu o designei para governar sobre todo Israel e Judá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Benaia, filho de Joiada, respondeu ao rei, dizendo: \"Que assim seja! Que Yahweh, o Deus do meu senhor, o rei, confirme isto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Como Yahweh esteve com meu mestre, o rei, que assim Ele esteja com Salomão, e faça seu trono maior do que o trono do meu senhor, o rei Davi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Então o sacerdote Zadoque, o profeta Natã, Benaia, filho de Joiada, os quereteus, e os peleteus desceram e fizeram com que Salomão andasse na mula do rei Davi; eles o levaram para Giom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Zadoque, o sacerdote, tirou o vaso de azeite do tabernáculo e ungiu Salomão. Então eles tocaram a trombeta, e todo o povo disse: \"Viva o rei Salomão!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Todo o povo subiu após ele tocando flautas e regozijando-se com grande alegria, de modo que a terra tremia com o barulho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Enquanto terminavam de comer, Adonias e todos os convidados que estavam com ele ouviram o barulho. Quando Joabe ouviu o som da trombeta, disse: \"Por que a cidade está tão barulhenta?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Enquanto ele ainda falava, Jônatas, filho de Abiatar, o sacerdote, chegou. Adonias disse: \"Entra, pois tu és um homem honrado e traz boas notícias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Jônatas respondeu e disse a Adonias: \"Nosso senhor, o rei Davi, constituiu a Salomão como rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'E o rei enviou com ele o sacerdote Zadoque, o profeta Natã, Benaia, filho de Joiada, os quereteus e os peleteus. Eles fizeram com que Salomão cavalgasse na mula do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'O sacerdote Zadoque e o profeta Natã ungiram Salomão como rei em Giom, e estão subindo de lá regozijando, por isso é que a cidade está barulhenta. Esse é o barulho que tu estás ouvindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Também Salomão está sentando no trono do reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Além disso, os servos do rei vieram abençoar nosso senhor, rei Davi, dizendo: \'Que o teu Deus faça o nome de Salomão maior que o teu nome, e faça o trono dele maior do que o teu trono\'. E o rei inclinou-se na cama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'O rei também disse: \'Bendito seja Yahweh, o Deus de Israel, que providenciou uma pessoa para sentar no meu trono neste dia, e que meus próprios olhos pudessem ver isso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Então todos os convidados de Adonias ficaram apavorados. Eles se levantaram, e cada homem seguiu seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Adonias ficou com medo de Salomão e, levantando-se, foi e agarrou as pontas do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Então disseram a Salomão: \"Vê, Adonias está com medo do rei Salomão, pois ele está agarrado às pontas do altar dizendo: \'Que o rei Salomão jure-me primeiramente que não matará seu servo com a espada\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Salomão disse: \"Se ele se mostrar um homem digno, nenhum fio de seu cabelo cairá em terra, mas, se for encontrado nele maldade, ele morrerá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Então o rei Salomão enviou homens que fizeram Adonias descer do altar. Ele veio e se inclinou ao rei Salomão, e Salomão disse-lhe: \"Vai para tua casa!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Quando o dia da morte de Davi se aproximou, ele deu ordens a Salomão seu filho, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, '\"Eu estou indo no caminho de toda a terra. Portanto sê forte, e age como homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Guarda os mandamentos de Yahweh, teu Deus, para andar em Seus caminhos, para obedecer Seus estatutos, Seus mandamentos, Suas decisões e Seus decretos da aliança, tendo o cuidado de fazer o que está escrito na lei de Moisés, para que prosperes em tudo que fizeres, aonde quer que fores,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'para que Yahweh cumpra a palavra que Ele falou acerca de mim, dizendo: \'Se teus filhos, cuidadosamente, observarem seus comportamentos, para andarem diante de Mim, fielmente, com todo o seu coração e com toda a sua alma, nunca cessarás de ter um homem no trono de Israel\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Sabes também o que Joabe, filho de Zeruia, me fez. Ele matou os dois comandantes dos exércitos de Israel: Abner, filho de Ner, e Amasa, filho de Jéter. Ele derramou o sangue de guerra em tempo de paz e colocou o sangue de guerra no cinto em volta de sua cintura e nos sapatos que ele calçava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Faze com Joabe conforme a tua sabedoria, mas não deixes que a sua cabeça grisalha desça à sepultura em paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Contudo, mostra bondade com os filhos de Barzilai, o gileadita, e coloca-os entre aqueles que comem à tua mesa, pois eles vieram a mim, quando eu fugi de Absalão, teu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Vê, está contigo Simei, filho de Gera, o benjamita de Baurim, o qual me amaldiçoou com uma terrível maldição, no dia em que eu ia para Maanaim. Simei desceu para me encontrar no rio Jordão, e eu jurei pelo nome de Yahweh, dizendo: \'Não te matarei pela espada\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Agora, portanto, não o deixes escapar sem punição. Tu és um homem sensato, e saberás o que deves fazer com ele. Tu farás que sua cabeça grisalha desça à sepultura com sangue\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Então Davi morreu e foi sepultado com seus antepassados, na cidade de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'O reinado de Davi foi de quarenta anos. Ele reinou por sete anos em Hebrom e por trinta e três anos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Então Salomão assentou-se no trono de Davi, seu pai, e seu governo foi firmemente estabelecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Então Adonias, filho de Hagite, veio a Bate-Seba, mãe de Salomão. Ela perguntou: \"Vieste pacificamente?\" Ele respondeu: \"Pacificamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Ele disse: \"Tenho algo para dizer-te\". Ela respondeu: \"Fala\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Adonias disse: \"Tu sabes que o reino era meu e que todo o Israel esperava que me tornasse rei. Contudo o reino foi transferido para meu irmão, porque ele o recebeu de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Agora um só pedido te faço, não me rejeites\". Bate-Seba disse-lhe: \"Fala\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Ele disse: \"Por favor, fala com o rei Salomão, pois ele não te recusará, para que ele me dê Abisague, a sunamita, como minha esposa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Bate-Seba disse: \"Muito bem, falarei com o rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Então Bate-Seba foi até o rei Salomão para falar com ele em favor de Adonias. O rei levantou-se para saudá-la e inclinou-se diante dela. Então ele se assentou em seu trono e mandou que trouxessem um trono para sua mãe. Ela se assentou à sua direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Ela lhe disse: \"Desejo fazer um pequeno pedido para ti. Não me recuses\". O rei respondeu: \"Pede, minha mãe, porque não te recusarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Ela disse: \"Permite que Abisague, a sunamita, seja dada como mulher para Adonias, teu irmão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'O rei Salomão respondeu para sua mãe: \"Por que tu me pedes Abisague, a sunamita, para Adonias? Por que não me pedes o reino também para ele, porque ele é meu irmão mais velho; para ele, para o sacedorte Abiatar e para Joabe, filho de Zeruia?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Então o rei Salomão jurou por Yahweh, dizendo: \"Que Deus faça comigo, e também mais, se Adonias não falou essa palavra contra a sua própria vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Agora, portanto, como Yahweh vive, que me estabeleceu e me colocou no trono de Davi, meu pai, e que me fez uma casa, como Ele prometeu, certamente, hoje Adonias será morto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Assim, o rei Salomão enviou Benaia, filho de Joiada, e ele achou Adonias e o matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Depois, o rei disse ao sacerdote Abiatar: \"Vai para Anatote, para os teus campos. Tu és digno de morte, mas não te matarei agora, porque tu carregaste a arca do Senhor Yahweh diante de Davi, meu pai, e participaste de todas as aflições de meu pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Assim, Salomão expulsou Abiatar para que não fosse sacerdote de Yahweh, para que se cumprisse a palavra de Yahweh, a qual Ele dissera acerca da família de Eli, em Siló.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'As notícias chegaram para Joabe, pois Joabe tinha apoiado Adonias, embora não tivesse apoiado Absalão. Assim, Joabe fugiu para a Tenda de Yahweh e segurou-se nas pontas do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Disseram ao rei Salomão que Joabe fugira para o Tabernáculo de Yahweh e agora estava ao lado do altar. Então Salomão enviou Benaida, filho de Joiada, dizendo: \"Vai e mata-o!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Então Benaia chegou até o Tabernáculo de Yahweh e disse-lhe: \"O rei disse: \'Sai\'\". Joabe respondeu: \"Não. Morrerei aqui\". Então, Benaia retornou para o rei, dizendo: \"Joabe disse que ficará e morrerá no altar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'O rei disse para Benaia: \"Faze como ele disse. Mata-o e enterra-o, para que tires de mim, e da casa de meu pai, o sangue que Joabe derramou sem causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Que Yahweh faça recair seu sangue sobre a sua própria cabeça, porque ele atacou dois homens mais justos e melhores que ele e matou-os com a espada: Abner, filho de Ner, o capitão do exército de Israel, e Amasa, filho de Jéter, o capitão do exército de Judá, sem que meu pai soubesse disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Assim o sangue deles recaia sobre a cabeça de Joabe e sobre a cabeça de seus descendentes para sempre. Mas, para Davi e sua descendência, e para sua casa, e para seu trono, haja paz de Yahweh para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Então, Benaia filho de Joiada, subiu e atacou Joabe e o matou. Ele foi enterrado em sua própria casa, no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'O rei colocou Benaia, filho de Joiada, sobre o exército, no lugar de Joabe, e colocou Zadoque, o sacerdote, no lugar de Abiatar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Então o rei mandou chamar Simei e lhe disse: \"Constrói para ti uma casa em Jerusalém e habita lá, e não saias dela para nenhum outro lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Porque, no dia em que saíres e atravessares o vale de Cedrom, sabe tu que certamente morrerás. Teu sangue será sobre tua própria cabeça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Então, Simei respondeu ao rei: \"O que disseste é bom. Como meu senhor, o rei, disse, assim teu servo fará\". Assim, Simei habitou em Jerusalém por muitos dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Ao fim de três anos, porém, dois dos servos de Simei fugiram para Aquis, filho de Maaca, o rei de Gate. E disseram a Simei: \"Vê, teus servos estão em Gate\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Então Simei se levantou, selou seu jumento e foi ao encontro de Aquis, em Gate, para buscar seus servos. Ele foi e os trouxe de volta de Gate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Quando Salomão soube que Simei havia saído de Jerusalém para Gate e havia retornado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'o rei mandou chamá-lo e lhe disse: \"Eu não te fiz jurar por Yahweh e testifiquei contra ti, dizendo: \'Sabe que, certamente, no dia em que saíres e fores para algum outro lugar, tu certamente morrerás\'? Então tu me falaste: \'O que tu disseste é bom\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Por que, então, não guardaste teu juramento a Yahweh e a ordem que eu dei para ti?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'O rei também disse para Simei: \"Tu sabes, no teu coração, toda a maldade que fizeste a Davi, meu pai. Portanto Yahweh retornará tua maldade sobre tua própria cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Todavia o rei Salomão será abençoado, e o trono de Davi será estabelecido perante Yahweh para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Então o rei deu ordem a Benaia, filho de Joiada, ele saiu e matou Simei. Assim foi confirmado o reino na mão de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Salomão aliou-se por casamento a Faraó, rei do Egito. Tomou a filha do Faraó e trouxe-a para a cidade de Davi, até que ele terminasse de construir seu próprio palácio, a casa de Yahweh, e o muro ao redor de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'As pessoas sacrificavam nos lugares altos, porque, até então, nenhuma casa havia sido construída para o nome de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Salomão demonstrava seu amor por Yahweh, andando nos estatutos de Davi, seu pai. Porém ele sacrificava e queimava incenso nos lugares altos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'O rei foi a Gibeão para ali sacrificar, pois lá estava o altar mais importante do monte. Salomão ofereceu mil ofertas queimadas sobre aquele altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Em Gibeão, Yahweh apareceu à noite a Salomão, em um sonho, e lhe disse: \"Pede! O que deveria eu dar a ti?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Então Salomão disse: \"Tu demonstraste grande fidelidade à aliança com Teu servo Davi, meu pai, porque ele andou diante de Ti em fidelidade, em justiça e em retidão de coração. Tu o preservaste em Teu grande amor leal e lhe deste um filho para hoje sentar no trono dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Agora, Yahweh, meu Deus, Tu fizeste Teu servo como rei no lugar de Davi, meu pai, ainda que eu seja apenas uma criança. Eu não sei direito como sair nem como entrar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Teu servo está no meio do povo que Tu escolheste, um povo grande, numeroso demais para ser numerado ou contado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Portanto, dá a Teu servo um coração sábio para julgar o Teu povo, para que eu possa discernir entre o bem e o mal. Pois quem seria capaz de julgar este Teu grande povo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Esse pedido de Salomão agradou ao Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Então Deus disse a ele: \"Porque tu pediste esta coisa e não pediste para ti uma vida longa ou riquezas ou a vida dos teus inimigos, mas pediste para ti entendimento para discernir a justiça,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'vê, agora, farei tudo o que tu me pediste segundo as tuas palavras. Eu te darei um coração de sabedoria e entendimento, como ninguém teve antes de ti, e ninguém igual a ti se levantará depois de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Eu também te dou o que não pediste, tanto riquezas quanto honra, de modo que não haverá entre os reis ninguém igual a ti durante todos os teus dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Se tu andares nos Meus caminhos, para guardares os Meus estatutos e os Meus mandamentos, como teu pai Davi andou, então, prolongarei os teus dias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Então Salomão acordou, e eis que era um sonho. Ele foi a Jerusalém e se pôs diante da Arca da Aliança do Senhor. Fez ofertas queimadas e ofertas de paz e fez um banquete para todos os seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Depois disso, duas mulheres prostitutas vieram ao rei e se puseram diante dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Uma mulher lhe disse: \"Ah, meu senhor, esta mulher e eu moramos na mesma casa, e eu dei à luz uma criança, com ela na casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Aconteceu que, no terceiro dia depois do parto, essa mulher também deu à luz. Nós estávamos juntas. Não havia mais ninguém conosco na casa, mas somente nós duas na casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Então o filho dessa mulher morreu numa noite, porque ela se deitou sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Então ela se levantou à meia-noite e tomou o meu filho do meu lado, enquanto a tua serva dormia, deitou-o no seio dela e deitou o filho morto dela em meu seio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Quando eu levantei pela manhã, para amamentar meu filho, ele estava morto. Mas, quando eu olhei cuidadosamente para ele, ao amanhecer, ele não era o filho que eu dei à luz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Em seguida, a outra mulher disse: \"Não, o vivo é meu filho, e o morto é teu filho\". A primeira mulher disse: \"Não, o que está morto é teu filho, e o vivo é meu filho\". E, assim, elas falaram perante o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Então o rei disse: \"Uma de vós diz: \'Este é o meu filho, o que está vivo, e, teu filho está morto\', e a outra diz: \'Não, teu filho está morto, e o meu filho é o que está vivo\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'O rei disse: \"Trazei-me uma espada\". Assim, eles trouxeram uma espada diante do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Em seguida, o rei disse: \"Dividi em duas a criança que vive. Dai metade a uma mulher e metade à outra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Então a mulher cujo filho estava vivo falou ao rei, pois seu coração estava cheio de compaixão por seu filho, e ela disse: \"Ah, meu mestre, dá a criança viva a ela, e de modo algum a mates\". Mas a outra mulher disse: \"Ela não será minha nem tua. Divide-a\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Então o rei respondeu e disse: \"Dai à primeira mulher a criança viva; de modo algum, a mates. Ela é a mãe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Quando todo o Israel ouviu o julgamento que o rei havia tomado, eles temeram o rei, porque viram que a sabedoria de Deus estava nele para dar julgamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'O rei Salomão era rei sobre todo o Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Estes eram seus oficiais: Azarias, filho de Zadoque, era o sacerdote;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Eliorefe e Aías, filhos de Sisa, eram secretários; Josafá, filho de Ailude, foi cronista;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benaia, filho de Joiada, era chefe do exército; Zadoque e Abiatar eram sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Azarias, filho de Natã, era chefe dos oficiais. Zabude, filho de Natã, era sacerdote e amigo do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Aisar era mordomo da casa. Adonirão, filho de Abda, era chefe dos homens sujeitos a trabalhos forçados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Salomão tinha doze oficiais que governavam sobre todo o Israel, que forneciam alimentos para o rei e toda a sua casa. Cada um tinha o dever de prover durante um mês no ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Estes eram os seus nomes: Ben-Hur, nos montes de Efraim;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Ben-Dequer, em Macaz, Saalabim, Bete-Semes, e Elom-Bete-Hanã;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Ben-Hesede, em Arubote (a ele pertencia Socó e toda a terra de Hefer);');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Ben-Abinadabe, em todo distrito de Nafote Dor (ele era casado com Tafate, a filha de Salomão);');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baaná, filho de Ailude, em Taanaque e Megido, e em toda a Bete-Seã, que está ao lado de Zaretã, abaixo de Jezreel, desde Bete-Seã até Abel-Meolá, para além de Jocmeão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Ben-Geber, em Ramote-Gileade (a ele pertenciam os povoados de Jair, filho de Manassés, que estão em Gileade, e a região de Argobe pertencia a ele, que está em Basã, sessenta grandes cidades com muros e ferrolhos de bronze);');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ainadabe, filho de Ido, em Maanaim;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Aimaaz, em Naftali (ele também se casou com Basemate, filha de Salomão);');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baaná, filho de Hasai, em Aser e em Bealote;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Josafá, filho de Paruá, em Issacar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Simei, filho de Elá, em Benjamin;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'e Geber filho de Uri, na terra de Gileade, a terra de Siom, rei dos Amorreus, e de Ogue, rei de Basã; e ele era o único oficial naquela terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Judá e Israel eram tão numerosos quanto a areia do mar. Eles estavam comendo e bebendo, e estavam felizes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Salomão reinava sobre todos os reinos, desde o rio Eufrates até a terra dos filisteus e até a fronteira do Egito. Eles entregaram tributo e serviram a Salomão todos os dias da sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'A provisão diária de Salomão era de trinta coros de farinha fina e sessenta coros de farinha mais grossa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'dez bois gordos, vinte bois de pasto, e cem ovelhas, além de veados, gazelas, cabritos monteses, e aves gordas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Pois ele tinha domínio sobre toda a região deste lado do rio Eufrates, desde Tifsa até Gaza, sobre todos os reis do lado de cá do rio Eufrates, e tinha paz por todos os lados ao redor dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Judá e Israel viveram em segurança, cada um debaixo da sua videira e debaixo da sua figueira, desde Dã até Berseba, todos os dias de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Salomão tinha quarenta mil baias para os cavalos dos carros de guerra, e doze mil cavaleiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Esses oficiais forneciam alimentos para o rei Salomão e para todos aqueles que comiam à mesa do rei Salomão, cada um no seu mês. Eles não permitiam que nada faltasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Também traziam ao lugar certo cevada e a palha para os cavalos dos carros de guerra, e cavalos de sela; cada um trazendo o que fora capaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Deus deu grande sabedoria e entendimento a Salomão, e amplitude de compreensão como a areia na praia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'A sabedoria de Salomão excedeu a sabedoria de todos os povos do leste e toda a sabedoria do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Ele era mais sábio que todos os homens — mais que Etã o ezraíta, Hemã, Calcol e Darda, filhos de Maol — e a sua fama atingiu todas as nações ao redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Ele disse três mil provérbios, e seus cânticos foram no número de mil e cinco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Ele descreveu as plantas, desde o cedro que se encontra no Líbano, até o hissopo que brota na parede. Ele também explicou sobre os animais, pássaros, répteis e peixes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'As pessoas vieram de todas as nações para ouvir a sabedoria de Salomão. Elas vieram de todos os reis da terra que haviam ouvido da sua sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Hirão, rei de Tiro, enviou seus servos até Salomão, quando escutou que o haviam ungido rei no lugar de seu pai, porque Hirão sempre amou a Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Salomão mandou uma mensagem a Hirão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, '\"Tu sabes que Davi, meu pai, não pôde construir uma casa para o nome de Yahweh, seu Deus, por causa das guerras que o cercavam, até que, durante sua vida, Yahweh pôs seus inimigos debaixo de seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Mas agora, Yahweh, meu Deus, tem me dado descanso por todos os lados. Não há nem adversários, nem desastres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Então eu pretendo construir um templo ao nome de Yahweh meu Deus, como Yahweh falou para Davi, meu pai, dizendo: \'Teu filho, que colocarei no teu trono em teu lugar, construirá o templo ao Meu nome\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Portanto ordena que cortem cedros do Líbano para mim. E meus servos se juntarão aos teus servos, e eu pagarei de forma justa para os teus servos conforme tudo o que concordares. Porque tu sabes que não há ninguém entre nós que saiba cortar madeira como os sidônios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Quando Hirão ouviu estas palavras de Salomão, regozijou-se grandemente e disse: \"Bendito seja hoje Yahweh, que deu a Davi um filho sábio sobre este tão grande povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Hirão enviou esta palavra a Salomão, dizendo: \"Ouvi a mensagem que me enviaste. Providenciarei tudo que desejares a respeito da madeira de cedro e de cipreste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Meus servos levarão as árvores do Líbano até o mar, e as farei como jangadas para ir pelo mar até o lugar que me designares. Chegando lá, eu as desamarrarei e tu as tirarás. Tu realizarás meu desejo, dando sustento para minha casa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Então Hirão deu a Salomão toda a madeira de cedro e cipreste que desejara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Salomão deu a Hirão vinte mil medidas de trigo para sustento de sua casa e vinte medidas de óleo puro. Salomão deu isto para Hirão ano após ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Yahweh deu sabedoria a Salomão, como lhe prometera. Havia paz entre Hirão e Salomão, e os dois fizeram uma aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'O rei Salomão recrutou trabalhadores de todo o Israel. Os trabalhadores forçados foram trinta mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Ele enviou ao Líbano dez mil por mês em turnos. Um mês eles estavam no Líbano e dois meses em casa. E Adonirão era o encarregado sobre os trabalhadores forçados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Salomão teve setenta mil que carregaram cargas e oitenta mil que cortavam as rochas nas montanhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Além de três mil e trezentos chefes-oficiais de Salomão, que estavam encarregados da obra e supervisionavam os trabalhadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'E o rei mandou que eles extraíssem grandes pedras de alta qualidade com as quais fariam a fundação do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Então os edificadores de Salomão, os de Hirão e os gebalitas cortaram e prepararam as madeiras e as pedras para construir o templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Então, Salomão começou a construir o templo de Yahweh. Isso aconteceu quatrocentos e oitenta anos após o povo de Israel ter deixado a terra do Egito, no quadragésimo ano do reinado de Salomão sobre Israel, no mês de Zive, que é o segundo mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'O templo que o rei Salomão construiu para Yahweh era de sessenta côvados de comprimento, vinte côvados de largura e trinta côvados de altura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'O pórtico em frente ao salão principal do templo era de vinte côvados de comprimento, igual à largura do templo, e dez côvados de profundidade em frente ao templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Para a casa, ele fez janelas com molduras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Junto aos muros da câmara principal, ele construiu salas, ao redor da sala externa e da sala interna. Ele construiu salas ao redor das paredes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'A sala do térreo tinha cinco côvados de largura, a central tinha seis côvados de largura, e a terceira era de sete côvados de largura. Na parte de fora, ele fez pilastras para reforço das paredes, para que as vigas não fossem inseridas nas paredes da casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'O templo foi construído com pedras preparadas na pedreira. Nenhum martelo, machado, ou nenhuma ferramenta de ferro foi ouvida enquanto ele estava sendo construído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'No lado sul do templo, havia uma entrada na parte térrea, então subia-se pelas escadas até a parte central, e da parte central até o terceiro nível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Assim, Salomão construiu o templo e o terminou; ele o cobriu com vigas e tábuas de cedro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Ele construiu salas ao redor de todo o templo, cada lado com cinco côvados de altura; elas estavam ligadas ao templo com madeiras de cedro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'A palavra de Yahweh veio a Salomão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '\"No que concerne a este templo que estás construindo, se andares nos Meus estatutos e praticares a justiça, guardares todos os Meus mandamentos e andares neles, então Eu confirmarei a Minha promessa que fiz a Davi, teu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'Habitarei no meio do povo de Israel e não os abandonarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Então, Salomão construiu o templo e o terminou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Ele construiu as paredes do interior com tábuas de cedro. Desde o piso até o teto, ele as cobriu por dentro com madeira; e o piso, cobriu com tábuas de cipreste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Ele construiu vinte côvados na parte de trás do templo com tábuas de cedro desde o piso até o teto. Ele construiu essa sala para que fosse uma sala interna, o Santíssimo Lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'O salão principal, que é o Santo Lugar, que estava em frente ao Santíssimo Lugar, era de quarenta côvados de comprimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Havia cedro dentro do templo, esculpido em forma de frutos e flores da cabaça. Por dentro, tudo era de cedro. Nenhum trabalho de pedra era visto no seu interior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Salomão preparou a sala interior do templo para que ali fosse colocada a Arca da Aliança de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'A sala interior era de vinte côvados de comprimento, e vinte côvados de largura e vinte de altura. Salomão revestiu as paredes com ouro puro e cobriu o altar com madeira de cedro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Salomão revestiu o interior do templo com ouro puro, e colocou correntes de ouro na frente da sala interior, e revestiu-a com ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Ele revestiu todo o interior com ouro, até que todo o templo foi terminado. Ele também revestiu com ouro todo o altar que pertencia à sala interior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Salomão fez dois querubins de madeira de oliveira, cada um deles com dez côvados de altura, para a sala interior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Uma das asas do primeiro querubim era de cinco côvados de comprimento, e outra asa dele tinha também cinco côvados de comprimento. Então, da ponta de uma asa até a ponta da outra, havia a distância de dez côvados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'O outro querubim também tinha asas de dez côvados. Os dois querubins tinham as mesmas dimensões e formas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'A altura de um querubim era de dez côvados, e o outro tinha a mesma altura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Salomão colocou o querubim na sala mais interior. As asas dos querubins eram estendidas, de forma que a asa de um tocava uma parede, e a asa de outro querubim tocava a outra parede. Suas asas tocavam uma na outra no meio do Santíssimo Lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Salomão revestiu os querubins com ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Ele entalhou todas as paredes da casa com figuras de querubim, palmeiras e flores abertas, na sala interior e exterior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Salomão revestiu o piso da casa com ouro, em ambas as salas, interior e exterior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Salomão fez portas de madeira de oliveira para entrada da sala interior. As vigas e batentes tinham cinco seções recuadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Então ele fez duas portas de madeira de oliveira, e fez nelas esculturas de querubim, palmeiras, e flores abertas. Ele revestiu-as com ouro, e espalhou o ouro no querubim e nas palmeiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Dessa forma, Salomão também fez, para entrada do templo, batentes de madeira de oliveira de quadro seções recuadas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'e duas portas de madeira de cipreste. As duas folhas de uma das portas moviam-se por dobradiça, como também as duas folhas da outra porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Ele esculpiu nelas querubim, palmeiras e folhas abertas, e, uniformemente, as revestiu com ouro na escultura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Ele construiu o pátio interior com três fileiras de pedra cortada e um fileira de vigas de cedro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'A fundação do templo de Yahweh foi lançada no quadragésimo ano, no mês de Zive.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'No décimo primeiro ano, no mês de Bul, que é o oitavo mês, o templo foi concluído em todas as suas partes de acordo com todas as suas especificações. Salomão levou sete anos para construir o templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Salomão levou treze anos para construir seu próprio palácio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Ele construiu o palácio do bosque do Líbano. Sua medida era cem côvados de comprimento, cinquenta de largura e trinta de altura. O palácio foi construído sobre quatro fileiras de pilares de cedro com vigas de cedro sobre os pilares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'A cobertura da casa foi feita com cedro apoiado sobre vigas. Essas vigas eram sustentadas por pilares. Havia quarenta e cinco vigas, quinze sucessivamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Havia três vigas em três fileiras, e cada janela ficava oposta a outra janela, em três conjuntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Todas as portas e postes eram quadrados; e janela era oposta à janela, em cada conjunto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Havia um pátio de cinquenta côvados de comprimento, com um pórtico na frente e pilares e um teto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Salomão construiu a sala do trono onde ele ficava para julgar, ísto é, a sala da justiça que era coberta com cedro desde o chão até às vigas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'A casa residencial de Salomão, em outro pátio dentro do recinto do palácio, foi projetada de maneira similar. Ele também construiu uma casa semelhante para a filha do Faraó, a quem ele havia tomado como esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Essas edificações eram adornadas com valiosas pedras lavradas, de medidas exatas, e cortadas com uma serra, e polidas em todos os lados. Essas pedras foram usadas desde o alicerce até as pedras no topo, e também no lado de fora para o grande átrio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Os alicerces foram construídos com enormes pedras de alto custo de oito e dez côvados de comprimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Por cima, ficavam valiosas pedras lavradas, cortadas sob medida, e vigas de cedro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'O grande pátio que cercava o palácio tinha três fileiras de pedras cortadas e uma fileira de vigas de cedro, como no pátio interior do templo de Yahweh e no pórtico do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'O rei Salomão mandou trazer Hirão, de Tiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Hirão era o filho de uma viúva na tribo de Naftali; seu pai era um homem de Tiro, um artesão em bronze. Hirão era cheio de sabedoria, entendimento e habilidade para fazer um bom trabalho com bronze. Ele veio ao rei Salomão para trabalhar com bronze para o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Hirão fez os dois pilares de bronze, cada um com dezoito côvados de altura e doze côvados de circunferência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Ele fez dois acabamentos de bronze polido para colocar no alto dos pilares. A altura de cada acabamento era de cinco côvados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Haviam treliças e correntes entrelaçadas para os acabamentos que decoravam o alto dos pilares, sete para cada acabamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Então Hirão fez duas fileiras de romãs de bronze em volta do topo de cada pilar para decorar os acabamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Os acabamentos no topo dos pilares do pátio eram decorados com lírios de bronze, de quatro côvados de altura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Os acabamentos ao redor dos dois pilares também incluíam, perto do topo, uma fileira de duzentas romãs de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Ele levantou os pilares do pátio do templo. O pilar da direita foi chamado de Jaquim e o da esquerda foi chamado Boaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Os topos dos pilares foram decorados com lírios de bronze. O trabalho dos pilares foi concluído dessa maneira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Hirão fez um tanque de metal, dez côvados de diâmetro. Sua altura era de cinco côvados e o tanque tinha trinta côvados de circunferência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Abaixo da borda do tanque, a cada dez côvados, ao longo de sua circunferência, foram fundidas flores e frutos de cabaça, juntas em uma só peça, quando o tanque foi feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'O tanque se apoiava em doze bois, três olhando em direção ao norte, três olhando em direção ao oeste, três voltados em direção ao sul e três voltados em direção ao leste. O tanque estava em cima deles e suas ancas estavam para dentro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'O tanque tinha quatro dedos de espessura e sua borda era como a borda de um copo, como uma flor de lírio. O tanque tinha capacidade para dois mil batos de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Hirão fez os dez suportes de bronze. Cada suporte tinha quatro côvados de comprimento, quatro de largura e três de altura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'O trabalho dos suportes era assim: tinham painéis que estavam fixados entre molduras,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'e, nos painéis e nas molduras, havia leões, bois e querubins. Acima e abaixo dos leões e bois, havia grinaldas esculpidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Cada suporte tinha quatro rodas e eixos de bronze e seus quatro cantos tinham apoio para a bacia. Os apoios eram fundidos com grinaldas em cada lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'A abertura ficava como um pedestal, com um côvado e meio de largura, dentro de uma coroa de um côvado de altura. Na abertura, havia gravuras esculpidas e seus painéis eram quadrados, não redondos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'As quatro rodas ficavam debaixo dos painéis e os eixos das rodas e seus aros ficavam no suporte. A altura de uma roda era de um côvado e meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'As rodas foram forjadas como as de uma carruagem. Seus eixos, seus aros, seus raios e seus cubos eram todos de metal fundido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'As quatro alças nos quatro cantos de cada suporte foram forjadas em uma só peça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'No topo dos suportes havia um cinto redondo de meio côvado de profundidade; no topo do suporte foram anexados apoios e painéis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Nas placas dos apoios e dos painéis, Hirão entalhou querubins, leões e palmeiras que cobriam o espaço disponível, circundada com grinaldas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Ele fez os dez suportes desta maneira: todos eles foram fundidos nos mesmos moldes, tinham o mesmo tamanho e forma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Hirão fez as dez bacias de bronze. Uma bacia podia suportar quarenta batos de água. Cada bacia era de quatro côvados e havia uma bacia em cada um dos dez suportes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Ele fez cinco suportes voltados para o sul do templo e cinco voltados para o norte. Ele pôs o tanque no canto leste, voltado para o sul do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Hirão fez as bacias, as pás e as caldeiras. Então ele finalizou toda a obra feita para o rei Salomão no templo de Yahweh:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'os dois pilares e os acabamentos em forma de taças que ficavam no topo, e os dois conjuntos de treliças decorativas para cobrir os acabamentos em forma de tigela no topo dos pilares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'Ele fez quatrocentas romãs para os dois conjuntos de treliças decorativas: duas fileiras de romãs para cada conjunto de treliça, para cobrir as duas taças de acabamento que estavam nos pilares; dez suportes');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'e dez bacias sobre os suportes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'Ele fez o tanque e os doze bois em baixo dele;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'também as vasilhas, pás, bacias e todos os outros utensílios. Hirão os fez de bronze polido, para o rei Salomão, para o templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'O rei os fez fundir na planície do Jordão, num terreno argiloso entre Sucote e Zaretã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Salomão não pesou todos os utensílios pois eram muitos para pesar, por isso o peso do bronze não pôde ser calculado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Salomão fez de ouro toda a mobília que estava no templo de Yahweh: o altar de ouro e a mesa dos pães da presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'Os castiçais, cinco do lado direito e cinco do lado esquerdo, em frente ao santuário interior, eram feitos de ouro puro; e as flores, as lâmpadas e as pinças eram de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'As taças, os aparadores das lâmpadas, bacias e braseiros eram todos feitos de ouro puro. E também as dobradiças das portas do santuário, que era o Santíssimo Lugar, e as das portas do templo, eram todas feitas de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Dessa maneira, todo o trabalho que o rei Salomão fez pela casa de Yahweh foi finalizado. Então Salomão trouxe as coisas que foram dedicadas a Yahweh por Davi, seu pai, a prata, o ouro, as mobílias e os depositou nos tesouros da casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Então Salomão reuniu diante de si, em Jerusalém, os anciãos de Israel, todos os líderes das tribos e os líderes das famílias do povo de Israel, para fazerem subir a Arca da Aliança de Yahweh da cidade de Davi, que é Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Todos os homens de Israel se reuniram diante do rei Salomão, na festa, no sétimo mês, no Mês de Etanim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Todos os anciãos de Israel vieram, e os sacerdotes fizeram subir a Arca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'Eles trouxeram a Arca de Yahweh, a Tenda do Encontro e todos os utensílios sagrados que ficavam na Tenda. Os sacerdotes e os levitas os trouxeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'O rei Salomão e toda a congregação de Israel se reuniram diante da Arca e sacrificaram ovelhas e bois que não se podiam contar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Os sacerdotes levaram a Arca da Aliança de Yahweh para o lugar dela, ao santuário interior, no Lugar Santíssimo, debaixo das asas dos querubins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Pois os querubins estendiam as suas asas para o lugar da Arca. Eles cobriam a Arca e as varas pelas quais ela era transportada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'As varas eram tão longas que as suas pontas eram vistas de dentro do Lugar Santo, em frente ao Lugar Santíssimo, mas, de fora, não eram vistas; e ali estão até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Nada havia na Arca, exceto as duas tábuas de pedra que Moisés ali depositara, quando Yahweh fez uma aliança com o povo de Israel, junto a Horebe, depois que eles saíram da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Aconteceu que, ao saírem os sacerdotes do Lugar Santo, uma nuvem encheu o templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Os sacerdotes não podiam permanecer de pé para ministrar, por causa da nuvem; pois a glória de Yahweh enchera o templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Então, Salomão disse: \"Yahweh falou que habitaria numa nuvem escura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Mas eu edifiquei para Ti uma casa exaltada, um lugar para Tua morada eterna\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Virando-se, então, o rei para o povo, que estava de pé, abençoou toda a congregação de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Ele disse: \"Seja louvado Yahweh, o Deus de Israel! Pois falou com Davi, meu pai, e cumpriu isso com as Suas próprias mãos, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, '\'Desde o dia em que Eu tirei o Meu povo Israel do Egito, não escolhi qualquer cidade dentre todas as tribos de Israel onde edificar uma casa para ali estabelecer o Meu Nome; porém escolhi Davi para governar sobre o Meu povo, Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Estava no coração de Davi, meu pai, edificar uma casa em nome de Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Mas Yahweh disse para Davi, meu pai: \'fizeste bem, nisso que estava no teu coração, para construir uma casa em Meu Nome;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'porém tu não edificarás o templo; teu filho, que procederá de ti, edificará um templo ao Meu Nome\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Yahweh cumpriu a palavra que Ele havia falado, porque eu me levantei em lugar de Davi, meu pai, e me assentei no trono de Israel, como Yahweh prometera, e edifiquei um templo ao nome de Yahweh, Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Eu edifiquei um lugar ali para a Arca, na qual está a aliança de Yahweh, a qual Ele fez com os nossos pais quando os tirou da terra do Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Salomão pôs-se diante do altar de Yahweh, perante toda a comunidade de Israel, e estendeu as suas mãos para os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Ele disse: \"Yahweh, Deus de Israel, não existe Deus como Tu, acima dos céus nem abaixo da terra, que guarda fielmente a Sua aliança com os Teus servos que caminham diante de Ti com todo o coração;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Tu, que tens mantido o que prometeste a Teu servo Davi, meu pai. Sim, Tu, que disseste com a Tua boca e tens executado isso com a Tua mão, como se vê hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Agora, Yahweh, Deus de Israel, cumpre o que prometeste ao Teu servo Davi, meu pai, quando disseste: \'Não te faltará sucessor diante de Mim que se assente no trono de Israel, contanto que os teus descendentes tenham cuidado de andar diante de Mim, como tu andaste diante de Mim\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Assim, Deus de Israel, eu oro para que se cumpra o que Tu prometeste ao Teu servo Davi, meu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Todavia habitará Deus na terra? Eis que o universo inteiro e o céu em si mesmo não podem contê-Lo; muito menos este templo que edifiquei!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Porém atenta para esta oração do Teu servo e sua súplica. Ó, Yahweh, meu Deus, atenta para o clamor e a oração que o Teu servo faz hoje, diante de Ti!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Que os Teus olhos permaneçam abertos noite e dia, em direção a este templo, o lugar sobre o qual Tu disseste: \'Meu Nome e Minha presença estarão lá\'; para ouvires a oração que o Teu servo fizer, voltado para este lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Assim, escuta o pedido do Teu servo e do Teu povo quando nós orarmos em direção a este lugar. Sim, ouve do lugar onde habitas, desde os céus; e quando ouvires, perdoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Se um homem pecar contra o seu próximo, e lhe for exigido que jure, e ele jurar diante do Teu altar, neste templo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'ouve então, do céu, e age; julga os Teus servos, condena o culpado, fazendo o seu proceder recair sobre a sua própria cabeça, e inocenta o justo, retribuindo-lhe segundo a sua justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Quando o Teu povo Israel for derrotado por um dos seus inimigos, por ter pecado contra Ti, se eles voltarem para Ti, confessarem o Teu nome, orarem e clamarem por Teu perdão neste templo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'então, por favor, escuta nos céus e perdoa o pecado do Teu povo Israel; torna a trazê-lo à terra que deste aos seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Quando os céus se fecharem e não houver chuva, quando Tu os afligires, por causa do pecado contra Ti, e eles orarem, voltados para este lugar, confessarem o Teu Nome e se converterem dos seus pecados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'então escuta dos céus e perdoa a transgressão dos Teus servos e do Teu povo Israel; ensinando-lhes o bom caminho no qual eles devem andar. Envia chuva sobre a Tua terra, a qual deste em herança ao Teu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Se houver fome na terra, enfermidade, praga, mofo, gafanhoto ou lagarta; ou se algum de seus inimigos os cercar nos portões das suas cidades; ou, se acontecer qualquer praga ou doença');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'e suceder, então, que orações e súplicas sejam feitas por qualquer indivíduo ou por todo o Teu povo Israel, conhecendo cada um a aflição do seu próprio coração enquanto estende as suas mãos para este templo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'ouve dos céus, o lugar onde Tu habitas; perdoa e age, retribui a cada um de acordo com toda a sua conduta, porque só Tu conheces o coração de todos os humanos. És o único que sabes o que procede de cada coração;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'para que eles temam a Ti todos os dias em que viverem na terra que deste aos nossos pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Também, quanto ao estrangeiro que não pertence ao Teu povo Israel: quando vier de terras distantes, por causa do Teu Nome');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(porque eles ouvirão quão grande é o Teu Nome, da Tua poderosa mão e do Teu braço estendido), quando ele vier e orar em direção a este templo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'então, por favor, ouve dos céus, o lugar onde habitas, e faze conforme tudo o que o estrangeiro a Ti clamar, a fim de que todos os povos da terra conheçam o Teu nome e temam a Ti, assim como ao Teu povo, Israel; e saibam que Teu Nome é invocado nesta casa que edifiquei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Quando o Teu povo sair à guerra contra os seus inimigos, seja qual for a orientação que Tu deres, e orar a Yahweh, voltado para a cidade que escolheste e para o templo que edifiquei ao Teu Nome,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'então escuta, dos céus, suas orações e seus pedidos, e defenda a causa deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Se acontecer de pecarem contra Ti (pois não há homem que não peque), e Tu te indignares contra eles e os entregares ao inimigo, de modo que os levem cativos para a terra do inimigo, distante ou próxima;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'e, na terra aonde forem levados em cativeiro, caírem em si e se converterem; se do cativeiro suplicarem a Ti, dizendo: \'transgredimos e pecamos; agimos perversamente\';');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'e, se verdadeiramente retornarem a Ti de todo o coração e de toda a alma, na terra em que estiverem cativos, e orarem a Ti, voltados para a sua terra, que deste aos seus pais, para a cidade que escolheste e para o templo que edifiquei ao Teu Nome;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'então lá dos céus, o lugar onde habitas, escuta suas orações, seus pedidos; e defende a causa deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'Perdoa o Teu povo, que tem pecado contra ti, e todas as suas transgressões contra os Teus mandamentos. Tem compaixão do Teu povo no cativeiro, para que os seus inimigos os tratem com compaixão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Eles são Teu povo, a quem Tu escolheste, a quem libertaste do Egito, do meio da fornalha de forjar ferro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Eu oro para que os Teus olhos estejam atentos à súplica dos Teus servos e escutes os pedidos do Teu povo, Israel, quando eles clamarem a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Porque Tu os separaste como Tua herança, Senhor Yahweh, dentre todos os povos da terra, para que pertençam a Ti e recebam Tuas promessas, como Tu nos instruíste por Moisés, Teu servo, quando do Egito tiraste os nossos pais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Assim que terminou de orar e suplicar a Yahweh, Salomão levantou-se de diante do altar de Yahweh, tendo estado de joelhos e com as mãos estendidas para os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Levantou-se e abençoou em alta voz toda a congregação, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, '\"Louvado seja Yahweh, que tem dado o descanso para o Seu povo Israel, cumprindo todas as Suas promessas. Nenhuma palavra tem falhado de todas as boas promessas que Ele fez por intermédio do Seu servo Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Que Yahweh, nosso Deus, esteja conosco, assim como Ele esteve com os nossos antepassados. Que Ele nunca nos deixe ou nos abandone;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'que Ele faça inclinar para Si o nosso coração, para viver em todos os Seus caminhos e guardar os Seus mandamentos, e os Seus estatutos, e os Seus decretos, que Ele ordenou aos nossos pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Que estas palavras que tenho falado e orado perante Yahweh estejam sempre diante de Yahweh, nosso Deus, dia e noite, para que Ele defenda a causa de Seu servo e a causa do Seu povo, Israel, assim como cada dia exigir;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'que todos os povos da terra conheçam que Yahweh é Deus, e não há outro Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Portanto, que o vosso coração seja verdadeiro para com Yahweh, nosso Deus, para andar nos Seus estatutos e guardar os Seus mandamentos, como neste dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Então, o rei e todo o Israel com ele ofereceram sacrifícios a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Salomão ofereceu um sacrifício de oferta de comunhão a Yahweh: vinte e dois mil bois e cento e vinte mil ovelhas. Assim, o rei e todo o povo de Israel dedicaram o templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'No mesmo dia, o rei consagrou a parte central do pátio em frente do templo de Yahweh; ele ofereceu o holocausto, a oferta de cereais e a gordura das ofertas de comunhão, já que o altar de bronze que está diante do templo de Yahweh era muito pequeno para caber nele o holocausto, a oferta de cereais e a gordura das ofertas de comunhão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Então, na mesma ocasião, ofereceu Salomão uma festa, e todo o Israel com ele, uma grande congregação, desde Lebo-Hamate até o rio do Egito, por sete dias e também por outros sete dias, um total de catorze dias, perante Yahweh, nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'No oitavo dia, o povo abençoou o rei; ele despediu o povo, e foram para suas casas, com regozijo e coração alegre por todas as boas coisas que Yahweh havia mostrado a Davi, Seu servo, e a Israel, Seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Depois que Salomão terminou de construir o templo de Yahweh e o palácio do rei, e depois que realizou tudo que o queria fazer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Yahweh apareceu a ele pela segunda vez, como havia aparecido em Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'E Yahweh lhe disse: \"Eu tenho escutado a oração e a súplica que tens feito diante de Mim. Estou consagrando este templo, o qual tu construíste para Mim, para colocar o Meu nome ali para sempre; Meus olhos e Meu coração estarão ali para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Se andares diante de Mim, como teu pai Davi andou, em integridade de coração e em retidão, obedecendo a tudo o que Eu te tenho ordenado e guardando Meus estatutos e Meus decretos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'então estabelecerei para sempre o trono de teu reino sobre Israel, como prometi a Davi, teu pai, dizendo: \'Nunca te faltará sucessor sobre o trono de Israel.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Mas, se tu ou teus filhos se afastarem de Mim e não guardarem Meus mandamentos e Meus estatutos que tenho estabelecido diante de ti, e se tu fores e adorares outros deuses e te curvares diante deles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'então Eu eliminarei Israel da terra que lhes dei; e este templo que consagrei ao Meu Nome, Eu o expulsarei para fora da minha presença; então Israel se tornará um motivo de zombaria e um objeto ridicularizado entre os povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Este templo se tornará um monte de ruínas, e todos que passarem por ele ficarão chocados, assobiarão e perguntarão: \'Por que Yahweh fez isto a esta terra e a esta casa?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Outros responderão: \'Porque eles abandonaram Yahweh, seu Deus, que trouxe seus antepassados para fora da terra do Egito, e eles se apegaram a outros deuses, curvaram-se diante eles, e os adoraram; por isso Yahweh trouxe toda esta calamidade sobre eles\'.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Aconteceu que, ao fim de vinte anos, Salomão havia terminado de construir os dois edifícios: o templo de Yahweh e o palácio do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Hirão, rei de Tiro, forneceu para Salomão árvores de cedro e de pinho, além de todo o ouro que Salomão desejava. Então o rei Salomão deu a Hirão vinte cidades na terra da Galiléia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'E Hirão saiu de Tiro para ver as cidades que Salomão tinha lhe dado, mas elas não o agradaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Então, Hirão perguntou a Salomão: \"Que cidades são estas que me destes, meu irmão?\" Hirão as chamou de Terra de Cabul, como são chamadas ainda hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Hirão havia enviado ao rei cento e vinte talentos de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Estas são as razões pelas quais Salomão impôs trabalhos forçados: para construir o templo de Yahweh e seu próprio palácio, para construir o Milo e o muro de Jerusalém, e ainda construir as defesas de Hazor, Megido e Gezer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Faraó, rei do Egito, tinha subido e tomado Gezer; ele a destruiu com fogo e matou os cananeus na cidade. Então Faraó deu a cidade para sua filha, esposa de Salomão, como presente de casamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Assim Salomão reconstruiu Gezer e Bete-Horom, a Baixa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Baalate e Tadmor, no deserto na terra de Judá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'e todas as cidades-armazéns que ele possuia, e as cidades para suas carruagens e as cidades para seus cavaleiros, e tudo que ele desejava construir para seu prazer em Jerusalém, no Líbano, e em todas as terras sob seu domínio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Quanto a todos os que restaram dos amorreus, dos heteus, dos perizeus, dos heveus e dos jebuseus, que não eram do povo de Israel —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'os descendentes daqueles que, depois deles, ficaram na terra, a quem o povo de Israel não conseguiu destruir totalmente — Salomão os recrutou como trabalhadores forçados, e é assim até os dias de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Entretanto Salomão não fez trabalhadores forçados do povo de Israel. Em vez disso, eles se tornaram seus soldados e seus servos, seus funcionários, seus oficiais e comandantes de seus batalhões de carruagens e seus cavaleiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Eles eram também os chefes oficiais, administrando os supervisores que estavam sobre as obras de Salomão — quinhentos e cinquenta deles — que supervisionavam o povo que fazia o trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'A filha do Faraó se mudou da cidade de Davi para a casa que Salomão havia construído para ela. Depois, Salomão construiu o Milo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'E oferecia Salomão, três vezes por ano, ofertas queimadas e ofertas de paz no altar que ele construiu para Yahweh, queimando incenso com elas no altar, que estava diante de Yahweh. Assim ele completou a construção do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'O rei Salomão construiu uma frota de navios em Eziom Geber, que fica perto de Elate, na costa do Mar Vermelho, na terra de Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Hirão enviou servos para a frota de Salomão, marinheiros que entendiam do mar, com os próprios servos de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Eles foram a Ofir com os servos de Salomão. De lá eles trouxeram quatrocentos e vinte talentos de ouro para o rei Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Quando a rainha de Sabá soube da fama de Salomão, por causa do nome de Yahweh, veio pô-lo a prova com questões difíceis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Ela veio a Jerusalém com uma grande caravana, com camelos carregados de especiarias, muito ouro e muitas pedras preciosas. Quando ela chegou, contou a Salomão tudo o que estava em seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Salomão respondeu todas as suas perguntas; não houve nada que ela perguntasse que o rei não respondesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Quando a rainha de Sabá viu toda a sabedoria de Salomão, o palácio que ele construiu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'a comida em sua mesa, o lugar dos seus oficiais, o trabalho dos seus servos e seus trajes, também os copeiros, e a maneira como ele oferecia sacrifícios na casa de Yahweh, ela ficou impressionada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Ela disse ao rei: \"É verdade o que eu ouvi no meu próprio país a respeito de tuas palavras e tua sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Eu não acreditei no que ouvi, até chegar aqui, e agora meus olhos viram isso. Nem metade me foi contada a respeito de tua sabedoria e riqueza! Tu excedes a fama da qual eu ouvi falar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Quão bem-aventuradas são as tuas mulheres e quão abençoados são os teus servos que constantemente estão diante de ti, porque ouvem a tua sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Bendito seja Yahweh, teu Deus, que se agradou de ti e te colocou no trono de Israel. Porque Yahweh amou Israel para sempre, Ele te fez rei para que praticasses a justiça e a retidão!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Ela deu ao rei cento e vinte talentos de ouro, uma grande quantidade de especiarias e pedras preciosas. Nenhuma quantidade tão grande de especiarias como essa que a rainha de Sabá deu ao rei Salomão foi dada a ele novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'A frota de Hirão, que trazia ouro de Ofir, também trazia de Ofir uma boa quantidade de madeira de sândalo e pedras preciosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'O rei usou a madeira de sândalo para fazer colunas para o Templo de Yahweh e para o palácio do rei, e harpas e liras para os cantores; nunca veio tão grande quantidade de madeira de sândalo como a que foi vista nesse dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'O rei Salomão deu à rainha de Sabá tudo o que ela desejou, tudo o que pediu e além daquilo que Salomão lhe dera segundo a sua generosidade real. Então ela retornou ao seu país com seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'O peso do ouro que foi levado a Salomão em um ano foi de seiscentos e sessenta e seis talentos de ouro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'além do ouro que os negociantes e mercadores traziam. Todos os reis da Arábia e governadores do país também trouxeram ouro e prata para Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'O rei Salomão fez duzentos grandes escudos de ouro batido; seiscentos ciclos de ouro foram usados em cada um.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Ele também fez trezentos escudos de ouro batido; três minas de ouro foram usadas em cada escudo; o rei colocou esses escudos dentro do palácio do bosque do Líbano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Então o rei fez um grande trono de marfim e o revestiu com o mais puro ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Havia seis degraus para o trono, e o encosto dele tinha um topo arredondado. Em cada lado do assento, havia apoio para os braços e dois leões em pé ao lado de cada apoio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Doze leões ficavam nos degraus, um em cada lado de cada um dos seis degraus. Não existia trono semelhante a este em reino algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Todas as taças que o rei Salomão usava para beber eram de ouro, e todas as taças para beber no Palácio da Floresta do Líbano eram de ouro puro; nenhuma delas era de prata, porque a prata não era considerada valiosa nos dias de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'O rei tinha no mar uma frota de navios oceânicos, junto com a frota de Hirão. Uma vez a cada três anos, a frota trazia ouro, prata e marfim, além de macacos e babuínos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Então o rei Salomão excedeu a todos os reis do mundo em riquezas e sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Todo o mundo procurava a presença de Salomão para ouvir sua sabedoria, a que Deus colocou em seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Aqueles que lhe visitavam traziam tributos, objetos de prata e ouro, vestes, armaduras e especiarias, assim como cavalos e mulas, ano após ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Salomão ajuntou carruagens e cavaleiros. Ele tinha mil e quatrocentos carros, além de doze mil cavaleiros que ele distribuiu nas cidades para carruagens e junto ao rei em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'O rei tinha prata em Jerusalém, tanta prata como pedras no chão. Ele fez o cedro ser tão abundante como os sicômoros que haviam nas campinas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Salomão possuia cavalos que havia comprado do Egito e de Cilícia. Os mercadores do rei compravam os cavalos em manadas, cada manada a um determinado preço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'As carruagens eram compradas do Egito por seiscentos siclos de prata cada, e os cavalos por cento e cinquenta siclos cada. Muitos destes foram, então, vendidos a todos os reis dos hititas e aramitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Então o rei Salomão amou muitas mulheres estrangeiras: a filha de Faraó, e mulheres moabitas, amonitas, edomitas, sidônias e heteias —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'nações concernentes as que Yahweh tinha dito para o povo de Israel: \"Vós não ireis entre elas para casar, nem elas virão até vós, porque elas certamente farão voltar o teu coração para os seus deuses\". Mas Salomão amou essas mulheres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Salomão teve setecentas esposas reais e trezentas concubinas. E suas mulheres desviaram o seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Na velhice de Salomão, suas esposas desviaram o seu coração para outros deuses; seu coração já não era totalmente rendido a Yahweh, seu Deus, assim como era o coração de Davi seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Pois Salomão seguiu Astarote, a deusa dos sidônios, e ele seguiu Moloque, o ídolo detestável dos amonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Salomão fez o que era mau a vista de Yahweh; ele não seguiu totalmente a Yahweh, como Davi, seu pai fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Então Salomão construiu um lugar alto para Camos, o ídolo detestável de Moabe, na colina leste de Jerusalém, e também para Moloque, o ídolo detestável dos amonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Ele também construiu lugares altos para todas suas esposas estrangeiras, que queimavam incenso e sacrificavam para seus deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Yahweh estava irado com Salomão, porque seu coração havia se desviado Dele, o Deus de Israel, mesmo tendo aparecido para Salomão duas vezes');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'e ordenado exatamente sobre isso, que ele não deveria seguir outros deuses. Mas Salomão não obedeceu o que Yahweh lhe ordenou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Portanto, Yahweh disse a Salomão: \"Porque tu tens desobedecido e não tens mantido a aliança e Meus estatutos que Eu te ordenei, certamente tirarei o reino de ti e o darei para teu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Contudo, por causa de Davi teu pai, Eu não farei isso em tua vida, mas o tirarei da mão de teu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'E ainda não tirarei todo o reino; Eu darei uma tribo para teu filho por causa de Davi meu servo, e por causa de Jerusalém, que Eu escolhi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Então Yahweh levantou um adversário para Salomão, Hadade, o edomita. Ele era da família real de Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Quando Davi estava em Edom, Joabe, o capitão do exército, subiu para sepultar os mortos daqueles que haviam sido mortos em Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'Joabe e todo o Israel permaneceram seis meses até que ele matou cada homem em Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Mas Hadade foi levado para o Egito com outros edomitas pelos servos de seu pai, quando Hadade ainda era criança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Eles deixaram Midiã e foram para Parã, de onde levaram homens com eles para o Egito, ao Faraó, rei do Egito, que lhes deu casa, terra e sustento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Hadade achou grande graça à vista de Faraó, então Faraó lhe deu uma esposa, irmã de sua própria mulher, a irmã de Tafnes, a rainha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'A irmã de Tafnes deu à luz um filho de Hadade. Eles o chamaram de Genubate. Tafnes o criou no palácio de Faraó. Então Genubate viveu no palácio de Faraó, entre os filhos de Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Quando Hadade estava no Egito, ele ouviu que Davi estava dormindo com seus antepassados, e que Joabe o capitão do exército estava morto; Hadade disse a Faraó: \"Deixa-me partir, então poderei ir ao meu próprio país\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Então Faraó disse a ele: \"Mas o que tem te faltado da minha parte, que agora buscas ir para teu próprio país?\" Hadade respondeu: \"Nada. Por favor, deixa-me partir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Deus também levantou outro adversário para Salomão, Rezom, filho de Eliada, que havia fugido de seu mestre Hadadezer, rei de Zobá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Rezom reuniu homens para ele mesmo e tornou-se capitão sobre uma pequena força, quando Davi derrotou os homens de Zobá. Os homens de Rezom foram para Damasco para morar lá, e Rezom controlou Damasco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Ele foi um inimigo de Israel todos os dias de Salomão, junto com o problema que Hadade causou. Rezom aborreceu Israel e reinou sobre a Síria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Então Jeroboão, filho de Nebate, um efrateu de Zeredá, um oficial de Salomão, cujo nome da mãe era Zerua, uma viúva, também levantou sua mão contra o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'A razão pela qual ele levantou sua mão contra o rei foi porque Salomão construiu o Milo e reparou a abertura do muro da cidade de Davi, seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Jeroboão era poderoso homem de valor. Salomão viu que o jovem era diligente, então deu-lhe um comando sobre todo o trabalho da casa de José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Naquele tempo, quando Jeroboão saiu de Jerusalém, o profeta Aías, o silonita, o encontrou na estrada. Então Aías vestiu uma veste nova e os dois estavam sozinhos no campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Então Aías agarrou a veste nova que estava sobre ele, e a rasgou em doze pedaços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Ele disse a Jeroboão: \"Pega dez pedaços, porque Yahweh, o Deus de Israel, diz: \'Vê, Eu rasgarei o reino das mãos de Salomão, e darei dez tribos a ti,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, '(mas Salomão terá uma tribo, por causa do Meu servo Davi e por causa de Jerusalém—a cidade que Eu tenho escolhido de todas as tribos de Israel)');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'porque eles Me abandonaram e adoraram Astarote, a deusa dos sidônios, Camos, o deus de Moabe, e Moloque, o deus do povo amonita. Eles não andaram nos Meus caminhos, para fazer o que é certo aos Meus olhos e guardar os Meus estatutos e Meus decretos, como fez Davi, seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Contudo, não tirarei todo o reino das mãos de Salomão. Em vez disso, Eu o farei reinar todos os dias de sua vida, por causa de Davi, Meu servo, que Eu escolhi, aquele que guardou Meus mandamentos e Meus estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Mas Eu tirarei o reino das mãos de seu filho, e Eu darei a ti dez tribos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Eu darei uma tribo para o filho de Salomão; então Davi, Meu servo, terá sempre uma lâmpada diante de Mim em Jerusalém, a cidade a qual Eu escolhi para colocar o Meu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Eu te tomarei, e tu reinarás para cumprir tudo o que tu desejas, e tu serás rei sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Se escutares tudo o que Eu te ordenar, e se andares em Meus caminhos e fizeres o que é certo aos Meus olhos, e se mantiveres Meus estatutos e Meus mandamentos, como Davi Meu servo fez, então Eu serei contigo e construirei para ti uma casa firme, como construi para Davi e darei Israel a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Eu punirei os descendentes de Davi, mas não para sempre.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Então Salomão tentou matar Jeroboão. Mas Jeroboão levantou-se e fugiu para o Egito, para Sisaque, rei do Egito, e permaneceu no Egito até a morte de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Quanto aos outros assuntos concernentes a Salomão, tudo que ele fez e sua sabedoria, não estão eles escritos no livro de feitos de Salomão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Salomão reinou em Jerusalém sobre todo o Israel por quarenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Ele adormeceu com seus antepassados e foi sepultado na cidade de Davi seu pai. Roboão, seu filho, se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Roboão foi para Siquém, pois todo Israel estava vindo pra Siquém para torná-lo rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'E aconteceu que Jeroboão, filho de Nebate, ouviu isto (pois ele continuava no Egito, para onde ele havia fugido da presença do rei Salomão) e voltou do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Então eles foram e o chamaram, e Jeroboão e toda a assembleia de Israel veio e disse a Roboão:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '\"O teu pai fez o nosso jugo pesado. Agora, torna o trabalho duro de teu pai mais fácil a nós, e alivia o jugo pesado que ele colocou sobre nós, e nós te serviremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Roboão disse a eles: \"Ide embora por três dias; depois voltai a mim\". Então o povo se foi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'O rei Roboão consultou os anciãos que aconselhavam Salomão, seu pai, enquanto ele estava vivo, e disse: \"Como vós me aconselhariam para que eu dê uma resposta a esse povo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Eles falaram com ele e disseram: \"Se te tornares servo deste povo hoje e os servires, e os responderes dizendo palavras boas para eles, então eles sempre serão teus servos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Mas Roboão ignorou o conselho que os anciãos deram a ele e foi consultar os jovens que cresceram com ele e estavam com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Roboão disse a eles: \"Qual conselho me daríeis, para que possamos responder às pessoas que falaram comigo e disseram: \'Alivia o jugo que teu pai colocou sobre nós?\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Os jovens que cresceram com Roboão falaram a ele, dizendo: \"Fala a este povo que disse que teu pai, Salomão, fez seu jugo pesado, mas que deve torná-lo mais leve, deve dizer a eles: \'Meu dedo mínimo é maior que a cintura do meu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Então, embora meu pai vos tenha sobrecarregado com um jugo pesado, eu aumentarei o vosso jugo. O meu pai vos castigou com chicotes, mas eu vos castigarei com escorpiões\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Então, Jeroboão e todo o povo vieram a Roboão no terceiro dia, como o rei os tinha instruido dizendo: \"Voltai a mim no terceiro dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'O rei respondeu ao povo rudemente e ignorou o conselho que os anciãos deram a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Ele lhes falou seguindo o conselho dos jovens, e disse: \"O meu pai vos sobrecarregou com jugo pesado, mas eu aumentarei o vosso jugo. O meu pai vos castigou com chicotes, mas eu vos castigarei com escorpiões\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Então o rei não ouviu ao povo, pois isso foi um evento causado por Yahweh, para que se cumprisse a palavra que Ele falou através de Aías, o silonita, para Jeroboão, filho de Nebate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Quando todo o Israel viu que o rei não os ouvia, o povo respondeu a ele dizendo: \"Que parte temos em Davi? Nós não temos herança com o filho de Jessé! Volta as tuas tendas, Israel. Olha pela tua própria casa, Davi\". Então, Israel voltou às suas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Mas, quanto ao povo de Israel que vivia nas cidades de Judá, Roboão tornou-se rei sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Então o rei Roboão enviou Adorão, encarregado dos trabalhadores forçados, mas todo Israel o apedrejou até a morte. O rei Roboão fugiu rapidamente em sua carruagem para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Israel se rebelou contra a casa de Davi até os dias de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Quando todo Israel ouviu que Jeroboão havia voltado, eles mandaram chamá-lo para sua assembleia e fizeram-no rei sobre todo o Israel. Não houve ninguém que seguiu a família de Davi, exceto a tribo de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Quando Roboão chegou a Jerusalém, ele convocou toda a casa de Judá e a tribo de Benjamim; estavam ali cento e oitenta mil homens escolhidos que eram soldados, prontos para lutar contra a casa de Israel, a fim de restaurar o reino a Roboão, filho de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Mas a palavra de Deus veio a Semaías, o homem de Deus, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, '\"Fala a Roboão, filho de Salomão, rei de Judá, para toda a casa de Judá e Benjamim, e ao resto do povo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, '\'Assim diz Yahweh: Não atacareis nem lutareis contra vossos irmãos o povo de Israel. Cada homem retornará a sua casa, pois Eu mesmo fiz isto acontecer\'\". Então eles ouviram a palavra de Yahweh, voltaram e seguiram o seu caminho, e obedeceram a Sua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Então Jeroboão construiu Siquém, na região montanhosa de Efraim, e morou ali. Saindo dali, foi e construiu Peniel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Jeroboão pensou: \"Agora o reino voltará para a casa de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Se este povo subir para oferecer sacrifícios no templo de Yahweh, em Jerusalém, então o coração deles se voltará outra vez ao seu senhor, para Roboão, rei de Judá. Eles me matarão e retornarão a Roboão, rei de Judá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Então o rei Joroboão buscou conselhos e fez dois bezerros de ouro, e disse para o povo: \"É demasiado que vós vades e subais a Jerusalém. Vede, estes são os vossos deuses, Israel, que vos tiraram da terra do Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Ele colocou um em Betel e outro em Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Assim, este ato se tornou um pecado. O povo foi para um ou outro até Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Jeroboão fez santuários idólatras nos lugares altos; ele também constituiu sacerdotes dentre todo o povo, que não eram filhos de Levi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Jeroboão ordenou uma festa no oitavo mês, no décimo quinto dia do mês, como a festa que há em Judá, e ele foi ao altar. Ele fez em Betel, sacrificando aos bezerros que fizera, e colocou em Betel os sacerdotes dos lugares altos que ele instituiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Jeroboão subiu ao altar que ele fez em Betel no décimo quinto dia do oitavo mês, no mês em que ele planejou na sua própria mente; ele ordenou uma festa para o povo de Israel e subiu até o altar para queimar incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Um homem de Deus veio de Judá, pela palavra de Yahweh, para Betel. Jeroboão estava junto ao altar para queimar incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'O homem de Deus gritou contra o altar, pela palavra de Yahweh: \"Altar, altar! Isto é o que Yahweh disse: \'Vê, um filho nascerá para a família de Davi, com o nome de Josias, e ele sacrificará os sacerdotes dos lugares altos que agora queimam incenso aqui, e, sobre ti, queimarão ossos humanos\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Então o homem de Deus deu um sinal no mesmo dia, dizendo: \"Esse é o sinal que Yahweh falou: \'Olha, o altar se partirá, e as cinzas sobre ele se derramarão\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Quando o rei ouviu o que o homem de Deus falou, que ele havia gritado contra o altar de Betel, Jeroboão estendeu a mão sobre o altar, dizendo: \"Prendei-o!\" Então a mão que ele estendeu contra o homem secou, e ele não conseguiu recolhê-la para si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, '(O altar também estava partido, e as cinzas se derramaram do altar, conforme o sinal que o homem de Deus havia dado por meio da palavra de Yahweh).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'O rei Jeroboão respondeu e disse para o homem de Deus: \"Intercede pelo favor de Yahweh, teu Deus, e ora por mim, para que a minha mão seja restaurada novamente\". Então o homem de Deus orou a Yahweh, e a mão do rei foi restaurada a ele novamente e ficou como estava antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'O rei falou para o homem de Deus: \"Vem para casa comigo, refresca-te e te darei uma recompensa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'O homem de Deus disse ao rei: \"Mesmo se tu me deres a metade de tuas posses, eu não irei contigo, não comerei e nem beberei água neste lugar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'pois Yahweh ordenou-me com Sua palavra: \'Tu não comerás pão ou beberás água, nem retornarás pelo caminho que tu vieste\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Então o homem de Deus foi por outro caminho e não retornou à sua casa pelo caminho por onde ele tinha vindo para Betel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Havia um velho profeta vivendo em Betel, e um de seus filhos veio e lhe falou todas as coisas que o homem de Deus tinha feito naquele dia em Betel. Seus filhos também falaram para ele o que o homem de Deus havia falado para o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'O pai deles lhes disse: \"Por qual caminho ele foi?\" Seus filhos tinham visto o caminho por onde o homem do Deus de Judá havia ido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Então, ele falou para os seus filhos: \"Selai o jumento para mim\". Então eles selaram o jumento, e ele foi embora cavalgando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'O velho profeta foi atrás do homem de Deus, achou-o sentado debaixo de um carvalho e lhe disse: \"És tu o homem de Deus que veio de Judá?\" Ele respondeu: \"Sou eu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Então o velho profeta lhe disse: \"Vem embora para a casa comigo e coma alguma coisa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'O homem de Deus respondeu: \"Eu não devo retornar contigo, nem ir contigo, nem comer ou beber água contigo, neste lugar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'pois foi ordenado a mim, pela palavra de Yahweh: \'Tu não comerás, nem beberás água lá, nem retornarás pelo caminho pelo qual tu vieste\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Então o velho profeta lhe disse: \"Eu também sou um profeta como tu és, e um anjo falou comigo, pela palavra de Yahweh, dizendo: \'Traze-o de volta contigo, para tua casa, para que ele coma algo e beba água\'\". Mas ele estava mentindo para o homem de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Então o homem de Deus voltou com o velho profeta e comeu e bebeu água em sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Quando eles se sentaram à mesa, a palavra de Yahweh veio para o profeta que o havia trazido de volta,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'e ele clamou para o homem de Deus que veio de Judá, dizendo: \"Yahweh disse: \'Porque tu foste desobediente à palavra de Yahweh e não guardaste o mandamento que Yahweh, teu Deus, te deu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'mas voltaste, comeste e bebeste água no lugar em que Yahweh disse para não comer nem beber água, teu corpo não será enterrado no túmulo de teus pais\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Depois de ele ter comido e bebido, o profeta selou o jumento do homem de Deus, o homem que tinha voltado com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Quando o homem de Deus foi embora, um leão veio até ele na estrada e o matou, e seu corpo ficou na estrada. Então o jumento ficou perto dele, e o leão também ficou diante do corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Quando homens passaram perto, e viram o corpo deixado na estrada e o leão diante do corpo, vieram e contaram isso na cidade onde o velho profeta vivia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Quando o profeta que o trouxe de volta do caminho ouviu, ele disse: \"É o homem de Deus, que desobedeceu à palavra de Yahweh. Portanto Yahweh entregou-o ao leão, que o rasgou em pedaços e o matou, como a palavra de Yahweh o tinha avisado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Então o velho profeta falou aos seus filhos, dizendo: \"Selai o meu jumento\", e eles o selaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Ele foi e encontrou o corpo deixado na estrada, e o jumento e o leão diante do corpo. O leão não tinha comido o corpo, nem atacado o jumento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'O profeta pegou o corpo do homem de Deus, colocou no jumento e o trouxe de volta. Ele foi para sua cidade para chorar por ele e para enterrá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Ele enterrou o corpo em seu próprio túmulo, e eles choravam sobre ele, dizendo: \"Ai, meu irmão!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Então, depois de o haver enterrado, o velho profeta falou aos seus filhos, dizendo: \"Quando eu estiver morto, enterrai-me num túmulo em que o homem de Deus estiver enterrado. Colocai meus ossos ao lado dos ossos dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Porque a mensagem que ele declarou pela palavra de Yahweh contra o altar em Betel e contra todas as casas nos lugares altos nas cidades de Samaria certamente acontecerá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Depois disso Jeroboão não se arrependeu dos seus maus caminhos, mas ainda nomeou sacerdotes comuns para os lugares altos, entre todos os tipos de pessoas. Ele consagrou qualquer um que quisesse servir como sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Isso tornou-se pecado para a família de Jeroboão e resultou na destruição dessa família, bem como no seu extermínio da face da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Naquele tempo Abias, filho de Jeroboão, ficou muito doente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Jeroboão disse para sua esposa: \"Por favor, levanta-te e disfarça-te, para que não sejas reconhecida como minha esposa, e vá a Siló, porque o profeta Aías está lá; ele disse a meu respeito, dizendo que eu seria rei sobre este povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Leva contigo dez pães, alguns bolos e uma vasilha de mel e vai até Aías. Ele dirá o que acontecerá com a criança\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'A esposa de Jeroboão fez isso; ela levantou e foi para Siló e entrou na casa de Aías. Entretanto Aías não enxergava; ele perdeu a visão devido a sua idade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Yahweh disse para Aías: \"Vê, a mulher de Jeroboão está vindo para consultar-te sobre o filho dela que está doente. Tu lhe falarás assim e assim, porque, quando ela entrar, fingirá ser outra mulher\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Quando Aías ouviu o som dos passos dela entrando pela porta, ele disse: \"Entre, mulher de Jeroboão. Por que finges ser outra pessoa que não és? Eu fui enviado a ti com más notícias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Vai, dize a Jeroboão que Yahweh, o Deus de Israel, diz: \'Eu te exaltei entre o povo e te constituí líder sobre o Meu povo, Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'E resgatei o reino da família de Davi e o dei a ti, mas tu não tens sido como Meu servo Davi, que guardou os Meus mandamentos e Me seguiu de todo o coração, para fazer somente o que era reto aos Meus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Em vez disso, tens feito o mal, pior do que os que foram antes de ti. Fizeste outros deuses e imagens de fundição para provocar-Me a ira, e Me deste as costas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Por isso, trarei desastre à tua família; exterminarei em Israel todo menino, escravo ou livre, e removerei completamente tua família, como alguém que queima estrume, até que desapareça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Qualquer um pertencente a tua família que morrer na cidade será comido pelos cães, e quem morrer no campo, será comido pelos passáros dos céus, porque eu, Yahweh, disse isso\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Então levanta-te, esposa de Jeroboão, e volta para tua casa; quando os teus pés entrarem na cidade, a criança morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Todo o Israel chorará por ele, e o sepultará. Ele é o único da família de Jeroboão que será sepultado, porque, somente nele, da casa de Jeroboão, foi encontrada alguma coisa boa aos olhos de Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Também Yahweh levantará um rei de Israel, que destruirá a família de Jeroboão, nesse dia. Hoje é este dia, agora mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Porque Yahweh atacará Israel, como se agita a cana nas águas, e Ele arrancará Israel desta boa terra, que deu a seus antepassados. Ele lhes espalhará além do rio Eufrates, pois, eles fizeram postes para Asterote, e provocaram a ira de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Ele abandonará Israel por causa dos pecados de Jeroboão; os pecados que ele tem cometido, e, através dos quais ele conduziu Israel a pecar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Então a esposa de Jeroboão levantou-se e partiu, e foi para Tirza. Assim que chegou à entrada da sua casa, o menino morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Todo o Israel o enterrou e chorou por ele, conforme a palavra de Yahweh, a qual ele falou por meio de seu servo Aías, o profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Quanto aos demais assuntos concernentes a Jeroboão, como ele guerreou e como ele reinou, estão escritos no livro da história dos reis de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Jeroboão reinou vinte e dois anos, e, depois, dormiu com seus antepassados, e Nadabe seu filho se tornou rei no seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Então Roboão, filho de Salomão, reinou em Judá. Roboão tinha quarenta e um anos quando se tornou rei, e ele reinou dezessete anos em Jerusalém, a cidade que Yahweh escolheu, de todas as tribos de Israel, para colocar Seu nome. Sua mãe era Amonita e se chamava Naamá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Judá fez o que era mau aos olhos de Yahweh; e, pelos pecados que cometeram, provocaram Seu ciúmes, mais do que fizeram os seus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Pois também edificaram, por si mesmos, lugares altos, pilares de pedra e postes de Astarote, sobre toda colina alta e debaixo de toda árvore verde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Existiam também prostitutas cultuais na terra. Eles fizeram as mesmas práticas abomináveis, como as outras nações, as quais Yahweh havia expulsado diante do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'No quinto ano do rei Roboão, Sisaque, rei do Egito, veio contra Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Ele levou embora as riquezas da casa de Yahweh, e as riquezas da casa do rei. Ele levou todas as coisas embora; ele também levou todos os escudos de ouro, que Salomão tinha feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'O rei Roboão fez escudos de bronze no lugar deles, e os entregou nas mãos dos comandantes da guarda que vigiavam as portas da casa do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'A partir de então, quando o rei entrava na casa de Yahweh, os guardas levavam os escudos; depois os devolviam para dentro da sala da guarda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Quanto aos demais assuntos referentes a Roboão, e de tudo que ele fez, não estão escritos no livro dos eventos dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Houve guerra constante entre Roboão e Jeroboão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Então Roboão dormiu com seus antepassados e foi sepultado com eles, na cidade de Davi. O nome da sua mãe era Naamá, a amonita. Abias, seu filho, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'No décimo oitavo ano do rei Jeroboão, filho de Nebate, Abias começou a reinar sobre Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Ele reinou por três anos em Jerusalém. O nome de sua mãe era Maaca. Ela era filha de Absalão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Ele andou em todos os pecados que seu pai havia cometido antes de seu tempo; seu coração não era devotado a Yahweh, seu Deus, como o coração de Davi, seu antepassado, havia sido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Mesmo assim, por causa de Davi, Yahweh, seu Deus, deu-lhe uma lâmpada em Jerusalém, levantando seu filho após ele, para fortalecer Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Deus falou isso porque Davi fez o que era certo aos Seus olhos; por todos os dias de sua vida, ele não virou as costas para nada que lhe havia sido ordenado, exceto no caso de Urias, o hitita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Houve guerra entre Roboão e Jeroboão durante todos os dias da vida de Abias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Os demais atos de Abias, tudo o que ele fez, não estão escritos no livro de eventos dos reis de Judá? Houve guerra entre Abias e Jeroboão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Abias dormiu com seus antepassados, e eles o sepultaram na cidade de Davi. Asa, seu filho, se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'No vigésimo ano de Jeroboão, rei de Israel, Asa começou a reinar sobre Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Ele reinou por quarenta e um anos em Jerusalém. O nome de sua avó era Maaca, a filha de Absalão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Asa fez o que era certo aos olhos de Yahweh, assim como Davi, seu antepassado, havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Ele expulsou as prostitutas cultuais da terra e removeu todos os ídolos que seus antepassados haviam feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Ele também removeu Maaca, sua avó, da posição de rainha, pois ela havia feito uma abominável imagem de um poste a Astarote. Asa destruiu esta imagem e a queimou no vale de Cedrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Mas os altares das colinas não foram removidos. Mesmo assim, o coração de Asa era completamente devotado a Yahweh, durante todos os seus dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Ele trouxe para o templo de Yahweh as coisas que foram dedicadas a Yahweh, por seu pai, e as coisas que ele mesmo havia dedicado, objetos feitos de prata e ouro, e vasos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Houve guerra entre Asa e Baasa, rei de Israel, durante todos os seus dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Baasa, rei de Israel, agiu agressivamente contra Judá e construiu Ramá, para que ninguém pudesse entrar ou sair da terra de Asa, o rei de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Então Asa pegou toda a prata e o ouro que foram deixados nos tesouros do templo de Yahweh, e os tesouros do palácio do rei. Ele os colocou nas mãos de seus servos e enviou a Ben-Hadade, filho de Tabrimom, filho de Heziom, o rei da Síria que habitava em Damasco. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, '\"Façamos uma aliança entre mim e ti, assim como houve entre meu pai e teu pai. Vê, eu te enviei um presente de prata e ouro. Quebra a tua aliança com Baasa, o rei de Israel, para que ele se afaste de mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Ben-Hadade ouviu ao rei Asa e enviou comandantes de seus exércitos, e eles atacaram as cidades de Israel. Eles atacaram Ijom, Dã, Abel-Bete-Maaca e toda Quinerete, junto com todo o território de Naftali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Quando Baasa ouviu isso, ele parou a construção de Ramá e voltou para Tirza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Então o rei Asa fez uma proclamação a todo o Judá. Ninguém foi excluído. Eles levaram as pedras e madeiras de Ramá, com as quais Baasa havia edificado a cidade. Então o rei Asa usou aquele material de construção para edificar Geba de Benjamim, e Mispá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Os demais atos de Asa, toda a sua força, e tudo o que fez, as cidades que construiu, não estão escritos no livro dos eventos dos reis de Judá? Porém, durante sua velhice, ele teve uma doença nos pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Então Asa dormiu com seus antepassados e foi sepultado com eles na cidade de Davi, seu pai. Josafá, seu filho, se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nadabe, filho de Jeroboão, começou a reinar sobre Israel no segundo ano do reinado de Asa, rei de Judá; ele reinou sobre Israel durante dois anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Ele fez o que era mau aos olhos de Yahweh e andou no caminho de seu pai, e no seu próprio pecado, pelo qual ele levou Israel a pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Baasa, filho de Aías, da família de Issacar, conspirou contra Nadabe; Baasa o matou em Gibetom, que pertencia aos filisteus, pois Nadabe e todo Israel cercavam Gibetom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'No terceiro ano de Asa, o rei de Judá, Baasa matou Nadabe, e se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Logo que se tornou rei, Baasa matou toda a família de Jeroboão. Ele não deixou que nenhum dos descendentes de Jeroboão respirasse; desta maneira ele destruiu sua linhagem real, como Yahweh havia falado através de seu servo Aías, o silonita,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'por causa dos pecados que Jeroboão havia cometido e pelos quais ele fez Israel pecar, pois provocou a ira de Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Os demais atos de Nadabe, e tudo o que ele fez, não estão escritos no livro de eventos dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Houve guerra entre Asa e Baasa, rei de Israel, durante todos os seus dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'No terceiro ano de Asa, o rei de Judá, Baasa, filho de Aías, começou a reinar sobre todo Israel em Tirza e ele reinou durante vinte e quatro anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Ele fez o que era mau aos olhos de Yahweh e andou no caminho de Jeroboão e em seus pecados, pelos quais levou Israel a pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'A palavra de Yahweh veio a Jeú, filho de Hanani, contra Baasa, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '\"Apesar de exaltar-te do pó e ter feito de ti um líder sobre o Meu povo Israel, tu tens andado no caminho de Jeroboão e tens feito Meu povo de Israel pecar, de modo que Me provocaste a ira com teus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Vê, Eu exterminarei completamente Baasa e sua família, farei com sua família assim como fiz à família de Jeroboão, filho de Nebate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Os cachorros comerão qualquer que pertence a Baasa que morrer na cidade, e as aves dos céus comerão os que morrerem nos campos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Quanto aos demais eventos de Baasa, o que ele fez e seu poderio, não estão escritos no livro dos eventos dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Baasa dormiu com seus antepassados e foi sepultado em Tirza, e Elá seu filho tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Então, pelo profeta Jeú, filho de Hanani, a palavra de Yahweh veio contra Baasa e sua família, não só por causa de todo o mal que ele fez à vista de Yahweh e que O provocou à ira com o trabalho de suas mãos, semelhantemente à família de Jeroboão, mas também porque Baasa tinha matado toda a familia de Jeroboão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'No vigésimo sexto ano de Asa, rei de Judá, Elá filho de Baasa, começou a reinar sobre Israel em Tirza; e reinou por dois anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Seu servo Zinri, capitão da metade dos carros de guerra, conspirou contra ele. Elá estava em Tirza, bebendo e embriagando-se na casa de Arza, que era seu mordomo em Tirza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Zinri foi para lá e o atacou, e o matou, no vigésimo sétimo ano de Asa, rei de Judá, e Zinri tornou-se rei no lugar de Elá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Quando Zinri começou a reinar e estava assentado em seu trono, ele matou toda a família de Baasa. Não deixou nenhum homem que pertencesse aos parentes ou os amigos de Baasa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Assim Zinri destruiu toda a família de Baasa, como foi dito pelas palavras de Yahweh, as quais Ele tinha falado contra Baasa por Jeú, o profeta,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'por todos os pecados de Baasa e os pecados de Elá, seu filho, que eles cometeram, pelos quais induziram Israel a pecar, de modo que provocaram Yahweh, o Deus de Israel, à ira em razão dos seus ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Quanto aos demais eventos de Elá e tudo o que ele fez, não estão escritos no livro de eventos dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'No vigésimo sétimo ano de Asa, rei de Judá, Zinri reinou, por somente sete dias, em Tirza. O exército estava acampado perto de Gibetom, que pertencia aos filisteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'O exército que se acampou ali ouviu dizer: \"Zinri conspirou contra o rei e o assassinou\". Então, naquele dia, no acampamento, todo o Israel declarou Onri, o comandante do exército, rei sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Onri subiu de Gibetom, e todo o Israel com ele, e eles sitiaram Tirza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Quando Zinri viu que a cidade havia sido tomada, entrou na fortaleza adjacente ao palácio do rei, e tocou fogo no prédio sobre ele. Dessa maneira ele morreu nas chamas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'Isso foi por causa dos pecados que ele havia cometido, por fazer o que era mau à vista de Yahweh, e andar pelo caminho de Jeroboão e no pecado que ele havia cometido, de modo a induzir Israel a pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Quanto aos demais atos de Zinri e a traição que executou, não estão escritos no livro de eventos dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'O povo de Israel estava dividido em duas partes. Metade do povo seguiu Tibni, filho de Ginate, para fazer dele rei; e a outra metade seguiu Onri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Mas o povo que seguiu Onri era mais forte que o povo que seguiu Tibni, filho de Ginate. Tibni morreu, e Onri tornou-se rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Onri começou reinar sobre Israel no trigésimo primeiro ano de Asa, rei de Judá, e reinou por doze anos. Ele reinou por seis anos em Tirza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Onri comprou a colina de Samaria de Semer por dois talentos de prata. Ele construiu uma cidade na colina e deu-lhe o nome de Samaria, depois do nome de Semer, o antigo proprietário da colina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Onri fez o que era mau aos olhos de Yahweh e agiu mais maliciosamente do que todos os que reinaram antes dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Pois ele andou em todos os caminhos de Jeroboão, filho de Nebate, e nos seus pecados pelos quais ele induziu Israel a pecar, para provocar Yahweh, o Deus de Israel, à ira em razão dos seus ídolos inúteis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Quanto aos demais atos de Onri, o que ele fez e o poderio que ele demonstrou, não estão escritos no livro de eventos dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Então Onri dormiu com seus antepassados e foi sepultado em Samaria; Acabe, seu filho, tornou-se rei em lugar de Onri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'No trigésimo oitavo ano de Asa, rei de Judá, Acabe, filho de Onri, começou a reinar sobre Israel. Acabe, filho de Onri, reinou sobre Israel, em Samaria, vinte e dois anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Acabe, filho de Onri, fez o que era mau à vista de Yahweh, mais que todos os que reinaram antes dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Era para Acabe algo trivial andar nos pecados de Jeroboão, filho de Nebate; assim, ele tomou como sua esposa Jezabel, a filha de Etbaal, rei dos sidônios; ele foi e adorou Baal e curvou-se diante dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Acabe construiu um altar para Baal, no templo de Baal, que ele havia edificado em Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Fez um poste dedicado a Astarote. Acabe fez ainda mais para provocar Yahweh, o Deus de Israel, provocando-Lhe ira, mais que todos os reis de Israel que reinaram antes dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Durante o reinado de Acabe, Hiel, o betelita, reconstruiu Jericó. Hiel lançou os alicerces da cidade ao custo da vida de Abirão, seu primogênito; e Segube, seu filho mais jovem, perdeu sua vida enquanto Hiel estava construindo os portões da cidade, de acordo com a palavra de Yahweh, pela qual Ele falou através de Josué, filho de Num.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Elias, o tesbita, de Tisbé, em Gileade, disse a Acabe: \"Assim como Yahweh, o Deus de Israel vive, diante de quem estou, não haverá orvalho ou chuva nestes anos, a menos que eu o diga\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'A palavra de Yahweh veio a Elias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '\"Sai daqui e vai para o leste; esconde-te ao lado do ribeiro de Querite, no lado leste do Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Acontecerá que tu beberás do ribeiro, e Eu ordenei aos corvos que te alimentem lá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Então Elias foi e fez como a palavra de Yahweh ordenou. Ele foi viver ao lado do ribeiro Querite, no lado leste do Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Os corvos traziam para ele pão e carne pela manhã e pão e carne à noite, e ele bebia do ribeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Mas, depois de um tempo, o ribeiro secou porque não havia nenhuma chuva na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'A palavra de Yahweh veio a ele dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '\"Levanta-te, vai para Sarepta, que pertence a Sidom, e habita lá. Vê, Eu ordenei a uma viúva que te sustente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Então ele levantou-se e foi para Sarepta e, quando ele chegou ao portão da cidade, a viúva estava lá, juntando lenha. Então ele a chamou e disse: \"Por favor, traze-me um pouco de água em uma jarra, para que eu possa beber\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Enquanto ela estava indo pegar água, ele a chamou e disse: \"Por favor, traze-me um pedaço de pão em tua mão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Ela respondeu: \"Assim como Yahweh, teu Deus, vive, eu não tenho nenhum pão, mas apenas um punhado de farinha em um pote e um pouco de azeite em uma jarra. Vê, eu estou juntando dois pedaços de lenha para que eu vá e cozinhe para mim e meu filho, para comermos e morrermos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Elias disse a ela: \"Não temas. Vai e faz como tens dito, mas faz-me um pouco de pão primeiramente e traz para mim. Então, depois faz um para ti e teu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Pois Yahweh, o Deus de Israel diz: \'O pote de farinha não se esvaziará, nem mesmo a jarra de azeite parará de fluir, até o dia que Yahweh mandar chuva na terra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Então ela fez como Elias lhe havia dito. Ela, Elias e o filho dela comeram por muitos dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'O pote de farinha não se esvaziou, nem a jarra de azeite secou, assim como a palavra de Yahweh tinha dito, como Ele falou por meio de Elias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Depois dessas coisas, o filho da mulher, a dona da casa, ficou doente. Sua doença era tão severa que não havia mais fôlego restando nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Então a mãe dele disse a Elias: \"O que tens contra mim, homem de Deus? Vieste aqui para me lembrar do meu pecado e matar meu filho?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Então Elias respondeu-lhe: \"Dá-me teu filho\". Ele pegou o menino dos braços dela e o carregou subindo até o quarto onde ele ficava e o deitou na sua cama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Elias clamou a Yahweh, dizendo: \"Yahweh, meu Deus, Tu trouxeste desastre até mesmo para esta viúva que me hospedou, matando seu filho?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Então Elias deitou-se sobre o menino três vezes; ele clamou a Yahweh e disse: \"Yahweh, meu Deus, eu Te imploro, por favor, que a vida deste menino retorne a ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Yahweh ouviu a voz de Elias; a vida do menino retornou, e ele reviveu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Elias tomou a criança e desceu do seu quarto trazendo-a para dentro da casa, entregou o menino à sua mãe e disse: \"Vê, teu filho está vivo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'A mulher disse a Elias: \"Agora eu sei que és um homem de Deus e que a palavra de Yahweh em tua boca é verdadeira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Então, depois de muitos dias, a palavra de Yahweh veio a Elias, no terceiro ano da seca, dizendo: \"Vai, apresenta-te a Acabe, e Eu enviarei chuva sobre a terra.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Elias foi apresentar-se a Acabe; naquela época, a fome era severa em Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Acabe chamou Obadias, que estava no comando do palácio. Obadias honrava muito a Yahweh,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'pois, quando Jezabel estava matando os profetas de Yahweh, Obadias pegou cem profetas e os escondeu de cinquenta em cinquenta em cavernas e alimentou-os com pão e água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Acabe disse a Obadias: \"Vai pela terra a todas as fontes de água e ribeiros, pode ser que acharemos pasto para conservar vivos os cavalos e mulas, e assim não perderemos todos os animais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Então eles dividiram a terra entre si para a percorrerem procurando água. Acabe foi por um caminho sozinho, e Obadias foi por outro caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Enquanto Obadias ia pela estrada, Elias, sem esperar, encontrou-o. Obadias o reconheceu e colocou o rosto em terra, e disse: \"És tu o meu senhor Elias?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Elias respondeu: \"Sou eu. Vai e diz a teu senhor: \'Olha, Elias está aqui\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Obadias respondeu: \"Em que pequei eu, para entregares o teu servo nas mãos de Acabe, para ele me matar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Assim como vive Yahweh, teu Deus, não há nação ou reino que meu senhor não tenha enviado homens para te procurar. Sempre que uma nação ou reino diz: \'Elias não está aqui\', Acabe faz com que eles jurem que não te acharam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Mas agora tu dizes: \'vai dizer ao teu senhor que Elias está aqui\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Assim que eu te deixar, o Espírito de Yahweh te levará para lugares onde eu não sei; e, indo eu dizer isso a Acabe, e ele não podendo te achar, ele me matará. Porém eu, teu servo, tenho adorado Yahweh desde minha juventude.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Não foi dito a ti, meu mestre, o que eu fiz quando Jezabel matou os profetas de Yahweh, como eu escondi cem profetas de Yahweh divididos entre cinquenta em cinquenta nas cavernas e os alimentei com pão e água?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'E agora tu dizes: \'Vai, fala ao teu senhor que Elias está aqui\'. Assim ele me matará.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Então Elias respondeu: \"Tão certo como Yahweh dos Exércitos vive, em cuja presença estou, hoje eu me apresentarei a Acabe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Assim Obadias foi se encontrar com Acabe e disse a ele o que Elias lhe dissera. Então o rei foi ao encontro de Elias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Quando Acabe viu Elias, disse-lhe: \"És tu, o pertubador de Israel?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Elias respondeu: \"Eu não tenho perturbado Israel, porém tu e a família de teu pai é que são os perturbadores, abandonando os mandamentos de Yahweh e seguindo os ídolos de Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Agora, ordena e reúne para mim todo Israel no monte Carmelo, junto a quatrocentos e cinquenta profetas de Baal e os quatrocentos profetas de Aserá, que se alimentam da mesa de Jesabel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Então Acabe ordenou a todo o povo de Israel e aos profetas que se reunissem no monte Carmelo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Elias se aproximou de todo o povo e disse: \"Até quando ficareis indecisos entre dois pensamentos? Se Yahweh é Deus, segui-o. Mas, se Baal é deus, então segui-o\". E o povo não respondeu a ele palavra alguma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Então Elias disse ao povo: \"Eu sou o último profeta de Yahweh, mas os profetas de Baal são quatrocentos e cinquenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Então deixai que eles tragam dois bois. Deixai que eles escolham um boi para eles e cortem em pedaços e coloquem sobre a lenha, mas não ponham fogo nela. Então eu prepararei o outro boi, colocarei sobre a lenha e não colocarei fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Então vós clamareis pelo nome de vosso deus e eu clamarei pelo nome de Yahweh, e o deus que responder por meio de fogo, esse é Deus.\" E todo o povo respondeu: \"Está bem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Então Elias disse aos profetas de Baal: \"Escolhei primeiro um boi para vós e o preparai, pois vós sois muitas pessoas. Então clamai pelo nome de vosso deus, mas não colocai fogo sob o boi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Eles pegaram o boi que lhes fora entregue e o prepararam, e clamaram no nome de Baal desde a manhã até ao meio-dia, dizendo: \"Baal, responde-nos!\" Mas não houve voz, nem ninguém que respondesse; e dançavam em volta do altar que haviam feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Ao meio dia, Elias zombava deles dizendo: \"Gritai mais alto! Ele é um deus! Talvez ele esteja pensando, ou atendendo alguma necessidade, ou em viagem, ou talvez esteja dormindo e precisa ser despertado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Então eles gritaram mais alto, e, conforme o seu costume, cortaram-se com facas e lancetas, até escorrer sangue sobre si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'O meio dia se passou, e eles ainda estavam delirantes até o momento do sacrifício da tarde, mas não havia qualquer voz ou alguém que respondesse; não havia quem prestasse atenção aos seus pedidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Então Elias disse a todo o povo: \"Chegai-vos a mim\", e todo o povo se aproximou dele. E ele reparou o altar de Yahweh, que estava em ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Elias pegou doze pedras, cada pedra representando uma das doze tribos dos filhos de Jacó — foi para Jacó que a palavra de Yahweh veio dizendo: \"Teu nome será Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Com as pedras, ele construiu um altar em nome de Yahweh, cavou uma cova em volta do altar, larga o suficiente para semear duas medidas de semente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'A seguir, ele armou a lenha para o fogo, dividiu o novilho em pedaços, e colocou os pedaços sobre a lenha. Ele disse: \"Enchei quatro cântaros de água e despejai sobre o sacrifício e sobre a lenha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Então disse: \"Façai pela segunda vez\", e eles fizeram isto pela segunda vez. Mais uma vez, ele disse: \"Façai uma terceira vez\", e eles fizeram pela terceira vez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'A água correu ao redor do altar e encheu a cova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Aconteceu que, na hora da oferta do sacrifício da tarde, o profeta Elias se aproximou e disse: \"Yahweh, Deus de Abraão, de Isaque e de Israel, manifesta hoje que tu és Deus em Israel, que eu sou Teu servo, e que eu tenho feito todas essas coisas conforme a Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Responde-me, Yahweh, responde-me, para que esse povo saiba que tu, Yahweh, és Deus e que tu fizeste o coração deles se voltar para Ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Então o fogo de Yahweh caiu e consumiu tanto o sacrifício, quanto a lenha, as pedras, o pó, e até a água que estava na cova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Quando todo o povo viu isso, todos se prostraram com o rosto em terra e disseram: \"Yahweh, Ele é Deus! Yahweh, Ele é Deus!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Elias disse ao povo: \"Agarrai os profetas de Baal; não deixai nenhum deles escapar\". Então eles os agarraram e Elias trouxe esses profetas para perto do ribeiro de Quison e os matou lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Elias disse à Acabe: \"Sobe, come e bebe, pois há som de muita chuva\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Assim sendo, Acabe subiu para comer e beber; enquanto isso, Elias subiu ao topo do monte Carmelo, inclinou-se na terra, colocou seu rosto entre seus joelhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'e disse ao seu servo: \"Sobe agora, olha na direção do mar\". O seu servo subiu, olhou e disse: \"Não há nada\". Então Elias disse: \"Vai de novo\" e assim por sete vezes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Na sétima vez, o servo disse: \"Olha, há uma nuvem subindo do mar, pequena como a mão de um homem\". Elias respondeu: \"Sobe e diz a Acabe: \'Prepara a tua carruagem e desce antes que a chuva te pare\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Aconteceu que, em pouco tempo, os céus se escureceram com nuvens e vento, e caiu uma forte chuva. Acabe entrou em sua carruagem e foi para Jezreel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'mas a mão de Yahweh estava sobre Elias. Ele enfiou o manto no seu cinto, depois correu, e ainda chegou antes de Acabe na entrada de Jezreel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Acabe contou a Jezabel tudo o que Elias havia feito e como matara todos os profetas com a espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Então Jezabel enviou um mensageiro a Elias, dizendo: \"Que os deuses façam comigo, e ainda mais, se eu não fizer com tua vida até amanhã a esta hora o mesmo que foi feito com a vida daqueles profetas mortos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Quando Elias ouviu isso, temendo, fugiu para salvar sua vida e chegou a Berseba, que pertence a Judá; e deixou seu servo ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Elias se foi ao deserto numa jornada de um dia e sentou-se debaixo de um arbusto. Ele pediu para si mesmo que morresse e disse: \"Já basta, Yahweh; toma a minha vida, pois não sou melhor do que meus antepassados mortos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Logo ele deitou e dormiu debaixo do arbusto; inesperadamente, um anjo lhe tocou e disse: \"Levanta-te e come\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Elias olhou e perto de sua cabeça havia um pão assado em brasas e um jarro de água. A seguir, ele comeu, bebeu e depois deitou-se novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'O Anjo de Yahweh veio uma segunda vez e o tocou, dizendo: \"Levanta-te e come, pois tua jornada será muito difícil\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Então ele se levantou, comeu, bebeu e viajou com a força daquele alimento por quarenta dias e quarenta noites até Horebe, o monte de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Ali, ele entrou em uma caverna e nela permaneceu. Depois, a palavra de Yahweh veio a ele e lhe disse: \"O que fazes aqui, Elias?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Elias respondeu: \"Eu tenho sido muito zeloso por Yahweh, Deus dos Exércitos, pois o povo de Israel abandonou Tua aliança, destruiu Teus altares e matou Teus profetas com a espada. Agora apenas eu fiquei, e eles ainda estão tentando tirar a minha vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Yahweh respondeu: \"Sai e sobe o monte diante de Mim\". Então Yahweh passou, e um forte vento se abateu sobre as montanhas quebrando as pedras em pedaços diante de Yahweh, mas Yahweh não estava no vento. Depois do vento, veio um terremoto, mas Yahweh não estava no terremoto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Depois do terremoto veio um fogo, mas Yahweh não estava no fogo. Depois do fogo, veio uma voz mansa e suave.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Quando Elias ouviu a voz, ele cobriu o rosto com sua capa, saiu e ficou em pé à entrada da caverna. Então veio uma voz dizendo: \"Que fazes aqui, Elias?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Elias respondeu: \"Eu tenho sido muito zeloso por Yahweh, Deus dos Exércitos, pois o povo de Israel abandonou Tua Aliança, destruiu Teus altares e matou Teus profetas à espada. Agora apenas eu fiquei, e eles ainda estão tentando tirar a minha vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Então Yahweh disse a ele: \"Vai, retorna por onde vieste, para o deserto de Damasco, e, quando lá chegares, ungirás a Hazel para ser rei sobre a Síria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Ungirás, também, a Jeú, filho de Ninsi, para ser rei sobre Israel, e ungirás a Eliseu, filho de Safate de Abel-Meloá, para ser profeta em teu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Acontecerá que Jeú matará quem escapar da espada de Hazael, e Eliseu matará quem escapar da espada de Jeú.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Porém Eu deixarei para Mim sete mil pessoas em Israel, cujos joelhos não se dobraram a Baal e cujas bocas não lhe beijaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Então Elias partiu dali e encontrou Eliseu, filho de Safate, que lavrava com doze juntas de bois adiante dele e, ele mesmo, lavrava com a décima segunda junta. Elias foi até Eliseu e colocou sua capa sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Depois Eliseu deixou os bois e correu até Elias e disse: \"Deixa que eu beije meu pai e minha mãe e depois te seguirei\". Então Elias lhe disse: \"Vai e volta, mas pensa sobre o que fiz contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Então Eliseu voltou a Elias, pegou a junta de bois, matou os animais, cozinhou a carne com a madeira do jugo dos bois, deu ao povo e eles comeram. Desde então, ele se levantou, passou a seguir Elias e o serviu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Ben-Hadade, rei da Síria, reuniu todo o seu exército. Havia trinta e dois reis de menor importância com ele, cavalos e carruagens. Ele subiu, cercou Samaria e lutou contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Enviou mensageiros à cidade de Acabe, rei de Israel, e lhe disse: \"Ben-Hadade te diz:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, '\'Tua prata e teu ouro são meus. Também tuas mulheres e crianças, as melhores, agora são minhas\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'O rei de Israel respondeu: \"Conforme o que disseste, meu mestre, rei. Eu e tudo o que tenho somos teus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Os mensageiros voltaram e disseram: \"Ben-Hadade assim diz: \'Enviei a palavra a ti dizendo que tu deverás me entregar tua prata, teu ouro, tuas mulheres e crianças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Mas eu enviarei meus servos a ti amanhã, nesta hora, e eles vasculharão tua casa e as casas de teus servos. Eles pegarão, com suas próprias mãos, e levarão tudo o que agradar seus olhos\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Então o rei de Israel reuniu todos os anciãos da terra e disse: \"Por favor, anotai e vede como esse homem procura problemas. Ele enviou mensagens para mim pedindo minhas mulheres, crianças, minha prata e meu ouro, e eu não os neguei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Todos os anciãos e todo o povo disseram a Acabe: \"Não o ouças nem atendas suas exigências\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Então Acabe disse aos mensageiros de Ben-Hadade: \"Dizei ao meu mestre, o rei: \'Concordo com tudo o que mandaste teu servo fazer pela primeira vez, mas eu não posso aceitar essa segunda ordem\'\". Então os mensageiros saíram e levaram a resposta a Ben-Hadade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Este enviou sua resposta a Acabe e disse: \"Que os deuses façam comigo e ainda mais, se até as cinzas de Samaria forem suficientes para todo o povo que me segue ter um punhado em suas mãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'O rei de Israel respondeu, dizendo: \"Dizei a Ben-Hadade: \'Ninguém que está apenas colocando sua armadura deveria se gabar como quem a está tirando\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Ben-Hadade ouviu a mensagem enquanto estava bebendo, ele e os reis abaixo dele, que estavam em suas tendas. Assim, ordenou aos seus homens: \"Alinhai-vos em posição para a batalha\". Então eles se prepararam em posição de batalha para atacar a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Eis que um profeta veio a Acabe, o rei de Israel, e disse: \"Yahweh diz: \'Tu viste este grande exército? Vê, eu o entregarei em tua mão hoje, e saberás que Eu sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Acabe respondeu: \"Por meio de quem?\" Yahweh respondeu: \"Pelos jovens oficiais que servem os governadores dos distritos\". Então Acabe disse: \"Quem iniciará a batalha?\" Yahweh respondeu: \"Tu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Então Acabe convocou os jovens oficiais que serviam aos governadores dos distritos. Eles eram duzentos e trinta e dois. Depois ele convocou todos os soldados, todo o exército de Israel, eram sete mil em número.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Eles saíram ao meio-dia. Ben-Hadade havia bebido e se embriagado em sua tenda, ele e os trinta e dois reis menores, que o estavam apoiando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Os jovens oficiais que serviam os governadores dos distritos foram para a frente primeiro. Então Ben-Hadade foi informado pelos espias que havia enviado: \"Os homens estão vindo de Samaria\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Ben-Hadade disse: \"Quer eles venham pela paz, quer pela guerra, trazei-os vivos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Então os jovens oficiais que serviam aos governadores dos distritos saíram da cidade, e o exército os seguiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Eles mataram cada um de seus inimigos, e os sírios fugiram. Israel os perseguiu. Ben-Hadade, o rei da Síria, escapou em um cavalo, junto com alguns cavaleiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Então o rei de Israel saiu, atacou os cavalos e carruagens e matou os sírios, impondo sobre eles um grande massacre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Então, o profeta veio ao rei de Israel e lhe disse: \"Vai, fortalece-te, entende e planeja o que estarás fazendo, pois, após um ano, o rei da Síria virá contra ti novamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Os servos do rei da Síria disseram a ele: \"O deus deles é deus dos montes. Por isso eles foram mais fortes que nós. Mas agora lutemos contra eles na planície e certamente seremos mais fortes que eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Assim, deve fazer isto: tira os reis, cada um de suas posições de autoridade, e substitui-os por comandantes do exército.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Levanta um exército como aquele que tu perdeste — cavalo por cavalo e carruagem por carruagem — para que possamos combatê-los na planície. Certamente, seremos mais fortes que eles\". Então Ben-Hadade ouviu o conselho dos servos e fez o que eles recomendaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Após o começo do novo ano, Ben-Hadade convocou os sírios e foi a Afeque para lutar contra Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'O povo de Israel, que estava convocado e provido de suprimento para lutar, acampou defronte deles como dois pequenos rebanhos de cabras, mas os sírios enchiam a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Então, um homem de Deus aproximou-se e disse ao rei de Israel: \"Assim diz Yahweh: \'Porque os sírios disseram que Yahweh é o deus dos montes, mas não é o deus dos vales, Eu colocarei esse grande exército em tua mão e saberás que Eu sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Assim, os exércitos acamparam, uns em frente aos outros, durante sete dias. No sétimo dia, a batalha começou. O povo de Israel matou cem mil sírios de infantaria em um dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'O restante fugiu para Afeque, entrou na cidade e o muro caiu sobre vinte e sete mil homens que restavam. Ben-Hadade fugiu e entrou na cidade, dentro de uma sala interna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Os servos de Ben-Hadade disseram a ele: \"Agora vê, nós ouvimos que os reis da casa de Israel são misericordiosos. Vamos nos vestir de panos de saco e cordas em volta de nossas cabeças e iremos ao rei de Israel. Talvez, ele poupe tua vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Assim, eles puseram pano de saco e cordas em torno de suas cabeças e depois foram ao rei de Israel e disseram: \"Teu servo Ben-Hadade diz: \'Deixa-me viver\'\". Acabe disse: \"Ele ainda vive? Ele é meu irmão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Os homens ouviram isso como um bom sinal de Acabe, então, rapidamente lhe responderam: \"Sim, teu irmão Ben-Hadade está vivo\". Então, Acabe disse: \"Ide e trazei-o\". Assim, Ben-Hadade veio a ele, e Acabe o convidou para entrar em sua carruagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Ben-Hadade disse a Acabe: \"Eu te restituirei as cidades que meu pai tomou de teu pai e podes fazer para ti praças em Damasco, assim como meu pai fez em Samaria\". Acabe respondeu: \"Eu te deixarei ir com esta aliança\". Então, Acabe fez uma aliança com ele e o deixou ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Um certo homem, um dos filhos dos profetas, disse a um de seus companheiros profetas pela palavra de Yahweh: \"Por favor, bate em mim\". Mas o homem se recusou a fazê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Então, o profeta disse ao seu seu companheiro profeta: \"Porque não obedeceste a voz de Yahweh, assim que me deixares, serás morto por um leão\". E, assim que aquele homem o deixou, um leão o encontrou e o matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Depois, o profeta encontrou outro homem e disse: \"Por favor, bate em mim\". Então, o homem bateu nele e o feriu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Assim, o profeta saiu e esperou pelo rei na estrada; ele havia se disfarçado com uma bandagem cobrindo os olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Quando o rei passava, o profeta clamou a ele, dizendo: \"Teu servo estava em plena batalha, e um soldado parou e trouxe um inimigo a mim, dizendo: \'Vigia este homem. Se ele escapar, tua vida será dada pela vida dele, ou então pagarás um talento de prata\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Mas, porque teu servo estava ocupado, indo aqui e ali, o soldado inimigo escapou\". Então, o rei de Israel disse a ele: \"Esta será tua punição — tu mesmo a decidiste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Então, o profeta rapidamente removeu a bandagem de seus olhos, e o rei de Israel reconheceu que ele era um dos profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'O profeta disse ao rei: \"Yahweh diz: \'Porque deixaste escapar de tua mão o homem que Eu havia sentenciado à morte, tua vida será tomada no lugar da vida dele, e teu povo por seu povo\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Então, o rei de Israel foi para sua casa ressentido e irado, e chegou a Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Algum tempo depois, Nabote, o jezreelita, tinha uma vinha em Jezreel, próxima ao pálacio de Acabe, rei de Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Acabe falou para Nabote, dizendo: \"Dá-me a tua vinha, para que possa transformá-la em uma horta, porque está próxima à minha casa. Em troca, eu te darei uma vinha muito melhor, ou, se tu preferires, te pagarei o valor dela em dinheiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Nabote respondeu a Acabe: \"Que Yahweh me proíba de te dar a herança dos meus antepassados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Assim, Acabe foi ao seu palácio ressentido e furioso por causa da resposta que Nabote, o jezreelita, deu a ele, quando disse: \"Eu não te darei a herança dos meus antepassados\". Ele se deitou em sua cama, virou seu rosto e se recusou a comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Jezabel, sua esposa, veio e disse a ele: \"Por que o teu coração está tão entristecido, que não comes?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Ele respondeu a ela: \"Eu falei para Nabote, o jezreelita e disse a ele: \'Dá-me a tua vinha por dinheiro, ou, se for do teu agrado, eu te darei outra vinha para que seja tua\'. Então ele respondeu a mim: \'Eu não te darei a minha vinha\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Assim, Jezabel, sua esposa, respondeu a ele: \"Tu não és o governante do reino de Israel? Levanta e come; alegra o teu coração. Eu obterei a vinha de Nabote, o jezreelita, para ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Assim, Jezabel escreveu cartas em nome de Acabe, selando-as com o selo dele e as enviou aos anciãos e aos nobres que se reuniam com ele e que viviam perto de Nabote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Ela escreveu nas cartas, dizendo: \"Proclamai um jejum e colocai Nabote acima do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Também colocai dois homens desonestos com ele e deixai-os testemunharem contra ele, dizendo: \'Tu amadiçoaste a Deus e ao rei\'\". Depois, tirai-o para fora e apedrejai-o até a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Assim, os homens da cidade dele, os anciãos e os nobres que viviam na cidade de Nabote fizeram como Jezabel descrevera nas cartas que ela havia enviado para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Eles proclamaram um jejum e colocaram Nabote acima do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Os dois homens desonestos entraram e sentaram diante de Nabote; eles testificaram contra Nabote, na presença do povo, dizendo: \"Nabote amaldiçoou a Deus e ao rei\". Então, eles o levaram para fora da cidade e o apedrejaram até a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Então, os anciãos mandaram uma palavra para Jezabel, dizendo: \"Nabote foi apedrejado e está morto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Assim, quando Jezabel ouviu que Nabote havia sido apedrejado e estava morto, ela disse a Acabe: \"Levanta-te e toma posse da vinha de Nabote, o jezreelita, a qual ele recusou te dar por dinheiro, porque Nabote não está mais vivo, mas morto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Quando Acabe ouviu que Nabote estava morto, levantou-se e desceu à vinha de Nabote, o jezreelita e tomou posse dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Então, a palavra de Yahweh veio a Elias, o tesbita, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '\"Levanta-te e vai encontrar Acabe, rei de Israel, que vive em Samaria. Ele está na vinha de Nabote, aonde foi para tomar posse dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Fala com ele e diz: \"Assim diz Yahweh: \'Tu mataste e tomaste posse?\'\". Então, dirás a ele: \"Assim diz Yahweh: \'No lugar onde os cães lambem o sangue de Nabote, os cães lamberão teu sangue; sim, o teu sangue\".\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Acabe disse a Elias: \"Achaste-me, meu inimigo?\". Elias respondeu: \"Achei-te, porque te vendeste para fazer o que é mau à vista de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Yahweh diz isto a ti: \'Olha, Eu trarei desgraça a ti e tu serás completamente consumido e cada um dos teus meninos, escravos e homem livre em Israel serâo cortados de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Farei da tua família como à familia de Jeroboão, filho de Nebate, e como à família de Baasa, filho de Aías, porque tu provocaste a Minha ira e conduziste Israel ao pecado\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Yahweh também falou com relação a Jezabel, dizendo: \'Os cães comerão Jezabel ao lado do muro de Jezreel.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Todo aquele que pertence a Acabe e que morrer na cidade, os cães o comerão; e as aves do céu comerão qualquer um que morrer no campo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Não havia ninguém como Acabe, que vendeu a si mesmo para fazer o que era mau à vista de Yahweh, a quem Jezabel, sua esposa, incitou a pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Acabe fez coisas repugnantes para os ídolos que ele seguiu, tal como todos aqueles amorreus haviam feito, aqueles que Yahweh havia expulsado de diante do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Quando Acabe ouviu essas palavras, rasgou suas vestes, cobriu-se de pano de saco, jejuou, deitou-se em pano de saco e se entristeceu muito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Então, veio a palavra do Senhor a Elias, o tesbita, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '\"Viste como Acabe se humilhou diante de Mim? Porque ele se humilhou diante de Mim, Eu não trarei essa desgraça nos dias dele; será nos dias de seu filho que Eu trarei desastre à sua família\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Três anos se passaram sem guerra entre a Síria e Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'E aconteceu que, no terceiro ano, Josafá, o rei de Judá, foi até o rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'O rei de Israel disse para seus servos: \"Vós sabeis que Ramote-Gileade é nossa, mas não fazemos nada para tomar das mãos do rei da Síria?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Assim, ele disse para Josafá: \"Irás tu comigo para a guerra em Ramote-Gileade?\". Josafá respondeu para o rei de Israel: \"Eu sou como tu és, meu povo é como o teu povo e meus cavalos são como os teus cavalos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Josafá disse para o rei de Israel: \"Por favor, busca a direção da palavra de Yahweh para o que farás primeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'E o rei de Israel reuniu os profetas, quatrocentos homens, e lhes disse: \"Eu deveria ou não ir a Ramote-Gileade para batalhar?\". Eles disseram: \"Ataca, porque o Senhor a entregará na mão do rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Mas Josafá disse: \"Ainda não há aqui outro profeta de Yahweh de quem nós devemos buscar conselho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'O rei de Israel disse para Josafá: \"Ainda há um homem de quem nós podemos buscar conselho de Yahweh para ajudar, Micaías, filho de Inlá, mas eu o odeio porque ele não profetiza nada de bom sobre mim, mas somente dificuldades\". Mas Josafá disse: \"O rei não pode dizer isto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Então, o rei de Israel chamou um oficial e ordenou: \"Traz Micaías, filho de Inlá, imediatamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Então, Acabe, o rei de Israel, e Josafá, o rei de Judá, estavam sentados cada um em um trono, vestidos em seus trajes reais, em um lugar aberto, na entrada do portão de Samaria e todos os profetas estavam profetizando diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Zedequias, filho de Quenaaná, fez ele mesmo chifres de ferro e disse: \"Diz Yahweh: \'Com estes, empurrarás os sírios até que eles sejam consumidos\"\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'E todos os profetas profetizaram o mesmo, dizendo: \"Ataca Ramote-Gileade e ganha, porque Yahweh a entregou nas mãos do rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'O mensageiro que foi chamar Micaías falou para ele, dizendo: \"Agora veja, as palavras dos profetas declaram coisas boas para o rei com uma só voz. Por favor deixe sua palavra ser como a de um deles e diga coisas boas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Micaías respondeu: \"Como Yahweh vive, o que Yahweh me disser, direi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Quando ele veio ao rei, o rei lhe disse: \"Micaías, deveríamos nós ir para Ramote-Gileade para batalhar, ou não?\" Micaías lhe respondeu: \"Ataca e ganha. Yahweh a entregará na mão do rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Então, o rei disse para ele: \"Quanto tempo devo te exigir para jurar e dizer para mim nada além da verdade em nome de Yahweh?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Assim, Micaías disse: \"Eu vi todo o Israel disperso para as montanhas, como ovelhas que não têm pastor e Yahweh disse: \'Estas não têm pastor. Permite que todos os homens retornem para suas casas em paz\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Então, o rei de Israel disse para Josafá: \"Eu não te disse que ele não profetizaria coisas boas concernentes a mim, mas somente desastre?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Então, Micaías disse: \"Assim sendo, escutai as palavras de Yahweh: Eu vi Yahweh, sentando, em Seu trono, e todo o exército do céu estava em pé junto a Ele em sua mão direita e esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Yahweh disse: \'Quem enganará Acabe, para que, então, ele suba e caia em Ramote-Gileade?\'. Um deles respondeu desse jeito e outro respondeu daquele jeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Então, um espírito veio adiante, ficou diante de Yahweh, e disse: \'Eu o enganarei\'. Yahweh disse-lhe: \'Como?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'O espírito respondeu: \'Eu sairei e serei um espírito de mentira na boca de todos os seus profetas\'. Yahweh respondeu: \'Tu o enganarás e tu também terás sucesso. Vai agora e faz assim\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Agora, vê, Yahweh colocou um espírito mentiroso na boca de todos estes teus profetas e Yahweh decretou desgraça para ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Então, Zedequias, filho de Quenaana, apareceu, bateu na bochecha de Micaías e disse: \"De que jeito o Espírito de Yahweh saiu de mim para falar contigo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Micaías disse: \"Veja, tu saberás naquele dia, quando correres para alguma sala interior para esconder\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'O rei de Israel disse para seu servo: \"Apreende Micaías e leva-o para Amom, o governador da cidade, e Joás, meu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'Dize-lhe: \'O rei diz: Coloca este homem na prisão e o alimenta somente com um pedaço de pão e um pouco de água, até que eu volte em paz\"\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Então, Micaías disse: \"Se retornares seguro, então, Yahweh não tem falado por mim\". E adicionou: \"Escutai isso, todos vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Assim, Acabe, rei de Israel, e Josafá, rei de Judá, subiram para Ramote-Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'O rei de Israel disse para Josafá: \"Eu me disfarçarei e entrarei na batalha, mas tu veste teus trajes reais\". Assim, o rei de Israel se disfarçou e foi para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Então, o rei da Síria havia ordenado aos trinta e dois capitães de suas carruagens, dizendo: \"Não ataqueis os soldados sem importância ou com importância. Em vez disso, atacai somente o rei de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'E aconteceu que, quando os capitães das carruagens viram Josafá, eles disseram: \"Certamente, ele é rei de Israel\". Eles voltaram a atacá-lo, então, Josafá gritou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Quando os comandantes das carruagens viram que não era o rei de Israel, eles pararam de persegui-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Mas um certo homem preparou o seu arco e, atirando ao acaso, acertou o rei de Israel, entre as juntas de sua armadura. Então, Acabe disse para o condutor de sua carruagem: \"Dê a volta e leva-me para fora da batalha, pois estou gravemente ferido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'A batalha ficou pior naquele dia e o rei foi mantido em sua carruagem voltada para os sírios. Ele morreu naquela tarde. O sangue de sua ferida escorreu para o fundo da carruagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Então, quando o sol estava se pondo, um clamor subiu do exército, dizendo: \"Todo homem deve voltar para sua cidade; e todo homem deve voltar para sua região!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'O rei Acabe morreu e foi levado para Samaria; eles o sepultaram lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Eles lavaram a carruagem ao lado do tanque de Samaria e os cachorros lamberam seu sangue (e isto foi no local onde as prostitutas se banhavam), assim como a palavra de Yahweh havia declarado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Quanto aos outros assuntos concernentes a Acabe, tudo que ele fez, a casa de marfim que ele construiu e todas as cidades que ele construiu não foram escritos no livro de Crônicas dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Assim, Acabe dormiu com seus antepassados e Acazias, seu filho, se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Então, Josafá, filho de Asa, começou a reinar sobre Judá no quarto ano de Acabe rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Josafá tinha trinta e cinco anos quando começou a reinar e ele reinou em Jerusalém por vinte e cinco anos. O nome de sua mãe era Azuba, a filha de Sili.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Ele andou nos caminhos de Asa, seu pai; e não se desviou deles; ele fez o que era certo aos olhos de Yahweh. Contudo, os lugares altos ainda não haviam sido tirados. O povo ainda estava sacrificando e queimando incenso nos lugares altos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Josafá fez paz com o rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Quanto aos outros assuntos concernentes a Josafá, e o poder que ele mostrou, e como ele promoveu uma guerra, não estão escritos no livro de Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Ele tirou da terra o resto das prostitutas cultuais que haviam permanecido nos dias de seu pai, Asa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Não havia rei em Edom, mas apenas um governador lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Josafá construiu navios; eles eram para ir a Ofir em busca de ouro, mas eles não foram porque os navios naufragaram em Eziom-Geber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Então, Acazias, filho de Acabe, disse para Josafá: \"Deixa que meus servos velejem com teus servos nos navios\". Mas Josafá não permitiu isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Josafá dormiu com seus antepassados e foi sepultado com eles na cidade de Davi, seu antepassado, Jeorão, seu filho, tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Acazias, filho de Acabe, começou a reinar sobre Israel, em Samaria, no décimo sétimo ano de Josafá, rei de Judá, e ele reinou dois anos sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ele fez o que era mau à vista de Yahweh e andou no caminho de seu pai, no caminho de sua mãe, e no caminho de Jeroboão, filho de Nebate, pelo qual ele conduziu Israel ao pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Ele serviu a Baal e o adorou e, assim, provocou Yahweh, o Deus de Israel, à ira, exatamente como seu pai havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Moabe rebelou-se contra Israel depois da morte de Acabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Então, Acazias caiu da grade da sua sacada superior em Samaria e com isso ficou ferido. Então, ele enviou mensageiros e disse-lhes: \"Ide, consultai a Baal-Zebube, o deus de Ecrom, se eu me recuperarei destes ferimentos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Mas o Anjo de Yahweh disse a Elias, o tesbita: \"Levanta-te, sobe ao encontro dos mensageiros do rei de Samaria e dize-lhes: \'Por acaso não há Deus em Israel para que consulteis a Baal-Zebube, o deus de Ecrom?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Por essa razão, assim diz Yahweh: \'Não descerás desta cama para onde subiste, mas, certamente, morrerás\"\'. Então, Elias saiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Quando os mensageiros retornaram a Acazias, este lhes perguntou: \"Por que retornastes?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Eles lhe disseram: \"Um homem veio ao nosso encontro e nos disse: \'Voltai ao rei que vos enviou e dizei-lhe: \'Assim diz Yahweh: \'Por acaso não há Deus em Israel para que teus homens consultem a Baal-Zebube, o deus de Ecrom? Por essa razão, não sairás desta cama para a qual subistes, mas certamente morrerás\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Acazias disse aos seus mensageiros: \"Qual a aparência do homem que veio ao vosso encontro e vos disse essas palavras?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'Responderam-lhes: \"Ele vestia uma roupa feita de pelos e tinha um cinto de couro amarrado em volta da cintura\". Então, o rei replicou: \"Este é Elias, o tesbita\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Então, o rei enviou um capitão com cinquenta soldados a Elias. Este subiu a Elias, que estava sentado no cume do monte, e lhe disse: \"Tu, homem de Deus, o rei diz: \'Desce\"\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Elias respondeu e disse ao capitão: \"Se eu sou homem de Deus, desça fogo do céu e consuma a ti e também os teus cinquenta homens\". Então, desceu fogo do céu e consumiu a ele e aos seus cinquenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Novamente, o rei Acazias enviou para Elias outro capitão com cinquenta soldados. Esse capitão também disse a Elias: \"Tu, homem de Deus, o rei diz: \'Desce rapidamente\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Elias respondeu e lhe disse: \"Se eu sou homem de Deus, desça fogo do céu e consuma a ti e também os teus cinquenta homens\". Outra vez, o fogo de Deus desceu do céu e o consumiu juntamente com seus cinquenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Ainda outra vez, o rei enviou um terceiro grupo de cinquenta guerreiros. Esse capitão subiu, pôs-se de joelhos diante de Elias e implorou, dizendo-lhe: \"Tu, homem de Deus, suplico-te, livra minha vida, e as vidas destes cinquenta guerreiros sejam preciosas à tua vista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Certamente, o fogo caiu do céu e consumiu os primeiros dois capitães com seus homens, mas agora permite que minha vida seja preciosa aos teus olhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Então, o Anjo de Yahweh disse a Elias: \"Desce com eles. Não tenhas medo deles\". Então, Elias se levantou e desceu com eles ao rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Elias disse a Acazias: \"Assim diz Yahweh: \'Tens enviado mensageiros para consultar Baal-Zebube, o deus de Ecrom. Por acaso não há Deus em Israel para que teus homens consultem a Baal-Zebube, o deus de Ecrom? Por essa razão, não sairás desta cama para a qual subistes, mas certamente morrerás\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Então, o rei Acazias morreu, de acordo com a palavra de Yahweh que Elias havia falado. Jorão começou a reinar em seu lugar, no segundo ano de Jeorão, filho de Jeosafá, rei de Judá, pois Acazias não tinha filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'O restante dos atos de Acazias não estão escritos no livro das Crônicas dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Quando Yahweh estava para tomar Elias aos céus, por meio de um redemoinho de vento, aconteceu que Elias saiu de Gilgal com Eliseu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Elias disse a Eliseu: \"Por favor, fica aqui, porque Yahweh me enviou para Betel\". Eliseu respondeu: \"Assim como vive Yahweh e tu vives também, eu não te abandonarei\". Então, eles desceram para Betel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Os filhos dos profetas que estavam em Betel vieram até Eliseu e lhe disseram: \"Tu sabes que hoje Yahweh tirará teu senhor de ti?\". Eliseu respondeu: \"Sim, eu sei, porém não faleis nisso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Elias lhe disse: \"Por favor, Eliseu, espera aqui, pois Yahweh me enviou a Jericó\". E Eliseu respondeu: \"Assim como vive Yahweh e assim como tu também vives, eu não te deixarei\". Então, eles foram para Jericó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Então, os filhos dos profetas que estavam em Jericó vieram até Eliseu e lhe disseram: \"Tu sabes que Yahweh tirará hoje teu senhor de ti?\". Eliseu respondeu: \"Sim, eu sei, mas não faleis sobre isso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Então, Elias lhe disse: \"Por favor, fica aqui, pois Yahweh me enviou ao Jordão\". Eliseu respondeu: \"Assim como vive Yahweh e assim como tu também vives, eu não te deixarei\". Então, eles partiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Depois, cinquenta dos filhos dos profetas ficaram em pé, de frente para eles, a uma certa distância, enquanto eles dois permaneceram em pé, diante do Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Elias pegou seu manto, enrolou e tocou a água com ele. O rio se dividiu em ambos os lados, de forma que eles dois o atravessaram em terra seca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Depois de terem atravessado, Elias disse a Eliseu: \"Pergunta-me o que devo fazer por ti antes que eu seja de ti tomado\". Eliseu respondeu: \"Por favor, peço-te que haja porção dobrada de teu espírito sobre mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Elias respondeu: \"Coisa difícil me pediste. Apesar disso, se tu me vires quando eu for tomado de ti, isso te acontecerá; caso contrário, isso não te acontecerá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Enquanto eles ainda desciam e conversavam, viram aparecer uma carruagem de fogo com cavalos de fogo que os separou um do outro e Elias subiu em um redemoinho de vento até os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Eliseu viu isso e clamou: \"Meu pai, meu pai, as carruagens de Israel e seus cavaleiros!\". Ele não o viu mais, pegou para si as roupas de Elias e rasgou-as em duas peças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Ele pegou a capa que Elias deixara cair e foi de volta para a beira do Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Tocou a água com a capa de Elias e disse: \"Onde está Yahweh, o Deus de Elias?\". Quando ele tocou as águas, estas se dividiram em ambos os lados e Eliseu atravessou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Quando os filhos dos profetas que eram de Jericó viram-no atravessar, disseram: \"O espírito de Elias repousa sobre Eliseu!\". Então, vieram ao seu encontro e prostraram-se diante dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'E disseram: \"Eis que há entre teus servos cinquenta homens fortes. Pedimos-te que os deixes ir em busca de teu senhor, pode ser que o Espírito de Yahweh o tenha tomado e o tenha deixado em alguma montanha ou em algum vale\". Eliseu respondeu: \"Não, não os envieis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Mas insistiram com Eliseu e o constrangeram até ficar envergonhado, então lhes disse: \"Enviai-os\". Assim, eles enviaram cinquenta homens e, por três dias, procuraram, mas não o encontraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Voltaram a Eliseu, enquanto ele estava em Jericó, e ele lhes disse: \"Não falei eu para vós, \'Não vades\'?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Os homens da cidade disseram a Eliseu: \"Vê, nós imploramos, a situação desta cidade é favorável, como meu senhor pode ver, mas as águas são ruins, e a terra não é fértil\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Eliseu respondeu: \"Trazei-me uma tigela nova e ponde sal nela\". Então, eles lhe trouxeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Eliseu foi até a nascente de água e pôs o sal nela; então, ele disse: \"Assim diz Yahweh: \'Eu sarei estas águas. De agora em diante, não haverá mais morte ou terra infrutífera\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Assim, as águas foram saradas até o dia de hoje, segundo a palavra de Eliseu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Então, Eliseu subiu dali a Betel. E, subindo ele pelo caminho, alguns jovens saíram da cidade zombaram dele, dizendo: \"Sobe, careca! Sobe, careca!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Virando-se ele para trás, viu-os e os amaldiçoou em nome de Yahweh. Então, duas ursas saíram da floresta e feriram quarenta e dois dos garotos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'E dali foi para o monte Carmelo e de lá retornou para Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'No décimo oitavo ano de Josafá, rei de Judá, Jorão, filho de Acabe, começou a reinar sobre Israel, em Samaria. Jorão reinou por doze anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'E fez aquilo que era mau à vista de Yahweh, mas não como seu pai e sua mãe; pois ele removeu a coluna sagrada de Baal que seu pai havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Entretanto, ele se manteve no pecado de Jeroboão, filho de Nebate, que fizera pecar a Israel e não se afastou desses pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Então, Messa, rei dos moabitas, criador de ovelhas, deu ao rei de Israel cem mil cordeiros e cem mil lãs de carneiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Mas, depois que Acabe morreu, o rei de Moabe se rebelou contra o rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Então, o rei Jorão saiu de Samaria naquele tempo e mobilizou todo o Israel para a guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Ele enviou uma mensagem para Josafá, rei de Judá, dizendo: \"O rei de Moabe tem se rebelado contra mim. Irás comigo contra Moabe para o combate?\". Josafá replicou: \"Irei. Estarei contigo, meu povo irá como teu povo, meus cavalos, como teus cavalos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Então, ele disse: \"Por qual caminho devemos atacar?\". Josafá respondeu: \"Pelo caminho do deserto de Edom\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Os reis de Israel, Judá e Edom marcharam em círculo por sete dias. Não encontraram água para o exército, nem para os cavalos e os animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Então, o rei de Israel disse: \"O que é isso? Será que Yahweh reuniu três reis para nos entregar nas mãos de Moabe?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Mas Josafá falou: \"Não existe aqui um profeta de Yahweh, para que possamos consultar Yahweh por meio dele?\". Um dos escravos do rei de Israel respondeu e disse: \"Eliseu, filho de Safate, está aqui, que derramava água sobre as mãos de Elias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Josafá disse: \"A palavra de Yahweh está com ele\". Então, o rei de Israel Josafá, e o rei de Edom desceram até ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Eliseu falou para o rei de Israel: \"O que eu tenho contigo? Ide aos profetas de teu pai e de tua mãe\". Então, o rei de Israel lhe disse: \"Não, porque Yahweh nos reuniu, os três reis, para nos entregar nas mãos de Moabe\". Eliseu replicou:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, '\"Assim como vive Yahweh dos Exércitos, em cuja presença estou, que se não fosse por honra à presença de Josafá, rei de Judá, eu não te daria atenção e nem te olharia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'No entanto, trazei-me um músico\". E, enquanto o harpista tocava, a mão de Yahweh veio sobre Eliseu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Ele disse: \"Assim diz Yahweh: \'Fazei este vale de rio seco encher de trincheiras\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Pois assim diz Yahweh: \'Não verás vento, nem verás chuva, mas este vale será cheio de água e beberás tu e todos os teus animais\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Isto é pouco aos olhos de Yahweh. Ele também vos concederá a vitória sobre os moabitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Atacareis todas as cidades fortificadas e todas as cidades escolhidas, cortareis todas as árvores frutíferas, interrompereis todas as fontes de água, e arruinareis com pedras toda a terra de cultivo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Na manhã seguinte, quase na hora de oferecer o sacrificío, as águas vinham descendo na direção de Edom, e a região se encheu de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Quando todos os moabitas ouviram que os reis tinham vindo para combatê-los, reuniram-se todos os que eram capazes de se armar, e permaneceram na fronteira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Despertaram cedo de manhã, e o sol refletia na água; viram os moabitas a água, diante si, vermelha como sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Eles exclamaram: \"Isto é sangue! Certamente os reis foram destruídos, eles se mataram uns aos outros! Agora, pois, Moabe, vamos despojá-los!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Quando os moabitas chegaram ao acampamento de Israel, os israelitas os surpreenderam e os atacaram, os quais fugiram diante deles. O exército de Israel avançou contra os moabitas por terra matando-os.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Israel destruiu as cidades e toda terra fértil, e cada homem lançou uma pedra e encheu os campos produtivos. Interromperam todos as fontes de água e cortaram todas as árvores frutíferas, apenas as pedras de Quir-Haresete ficaram no lugar. Porém, os soldados armados com estilingues a cercaram e a atacaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Quando Messa, rei de Moabe, viu que estava perdendo a batalha ficou perdido. Tomou consigo setecentos homens com espadas para romperem contra o rei de Edom, mas eles falharam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Então, ele tomou seu filho mais velho, que deveria reinar em seu lugar, e o ofereceu como sacrifício sobre o muro. E houve grande ira contra Israel, e o exército israelita deixou o rei Messa e retornou para sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'A esposa de um dos filhos dos profetas veio chorando a Eliseu, dizendo: \"Teu servo, meu marido, morreu, e tu sabes que teu servo era temente a Yahweh. Agora veio o credor para levar meus dois filhos como seus escravos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Então, Eliseu lhe disse: \"O que posso fazer por ti?\". Ela disse: \"Tua serva não tem nada em casa, senão um pote de azeite\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Então, Eliseu disse: \"Vai, e pede vasilhas vazias emprestadas aos teus vizinhos, tantas quantas forem necessárias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Então, deves entrar, fechar a porta sobre ti e teus filhos, e colocar o azeite dentro de todas as vasilhas. Põe à parte as vasilhas que estiverem cheias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Ela deixou Eliseu e fechou a porta sobre si e seus filhos. Eles traziam as vasilhas e ela as enchia com azeite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Quando as vasilhas estavam cheias, disse a seu filho: \"Traze-me outra vasilha\". Mas ele lhe disse: \"Não há mais vasilhas\". Então, o azeite parou de fluir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Então, ela veio e contou ao homem de Deus. Ele disse: \"Vai, vende o azeite, paga tuas dívidas, e, tu e teus filhos vivei do restante\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Um certo dia, Eliseu foi para Suném, onde vivia uma mulher importante, que insistiu que ele fosse comer com ela. Então, sempre que Eliseu passava por ali, parava para comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'A mulher disse a seu marido: \"Agora entendo que este, que sempre passa por aqui, é um santo homem de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Façamos um pequeno quarto no telhado, para Eliseu, coloquemos dentro uma cama, uma mesa, uma cadeira e uma lâmpada. Então, quando ele vier até nós, ficará ali\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Assim, quando chegou o dia em que Eliseu parou ali, ficou no quarto e descansou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Eliseu mandou o seu servo, Geazi, chamar a sunamita. Então, ele a chamou e, quando ela veio,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Eliseu mandou que dissesse a ela: \"Tu tiveste todo este trabalho por nossa causa. O que podemos fazer por ti? Podemos falar, por ti, com o rei ou com o comandante do exército?\". Ela respondeu: \"Eu habito no meio do meu próprio povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Eliseu disse: \"O que podemos fazer por ela, então?\" Geazi respondeu: \"Ora, ela não tem filho, e seu esposo é velho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Então, Eliseu respondeu: \"Chama-a\". Quando ele a chamou, ela se colocou de pé, à porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Eliseu disse: \"Por esse tempo, no próximo ano, você segurará um filho\". Ela disse: \"Não, meu senhor é homem de Deus, não mintas para tua serva\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Porém a mulher concebeu e deu à luz um filho, no ano seguinte, naquele mesmo período, como Eliseu lhe havia dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Quando a criança cresceu, saiu um dia a ter com seu pai, que estava com os ceifeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Ele disse a seu pai: \"Minha cabeça! Minha cabeça!\" O pai disse a seu servo: \"Leva-o para a mãe dele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Quando o servo pegou o menino e o trouxe para sua mãe, a criança se assentou no colo dela até o meio dia e, então, morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Então, a mulher se levantou e deitou o menino na cama do homem de Deus, fechou a porta e saiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Ela chamou seu marido e disse: \"Por favor, envia-me um dos servos e uma das jumentas, para que eu possa correr até o homem de Deus e, então, voltarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'O marido disse: \"Por que queres vê-lo hoje? Não é lua nova, nem mesmo sábado\". Ela respondeu: \"Vai ficar tudo bem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Então, ela selou a jumenta e disse para seu servo: \"Guia rapidamente; não pares a não ser que eu o diga\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Assim, ela saiu e foi ao encontro do homem de Deus, no monte Carmelo. Quando o homem de Deus a viu de longe, disse a Geazi, seu servo: \"Eis aí a mulher sunamita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Por favor, corre ao seu encontro e dize: \'Está tudo bem contigo, com teu marido e com a criança?\'\". Ela respondeu: \"Tudo está bem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Quando ela chegou ao homem de Deus, na montanha, ela se agarrou aos seus pés. Geazi se aproximou para afastá-la, mas o homem de Deus disse: \"Deixa-a sozinha, pois ela está muito angustiada e Yahweh me ocultou o problema e não me disse nada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Disse ela: \"Te pedi eu por um filho, meu senhor? Não disse eu: \'Não me enganes?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Então, Eliseu disse a Geazi: \"Põe tuas vestes de viagem e pega meu cajado em tua mão. Vai para a casa dela. Se encontrares algum homem, não o cumprimentes e, se alguém te cumprimentar, não lhe respondas. Deita meu cajado sobre a face da criança\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Mas a mãe da criança disse: \"Como vive Yahweh e como tu vives, não te deixarei\". Então, Eliseu se levantou e a seguiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Geazi se apressou à frente deles e deitou o cajado sobre a face da criança, mas a criança não falou, nem ouviu. Então, Geazi retornou para encontrar Eliseu e lhe disse: \"O menino não despertou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Quando Eliseu chegou à casa, a criança estava morta e continuava sobre a cama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Então, Eliseu entrou e fechou a porta sobre ele e a criança e orou a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Subiu e deitou sobre a criança: colocou a boca sobre sua boca, os olhos sobre seus olhos, e as mãos sobre suas mãos. Ele se estendeu sobre o menino, e o corpo do menino se aqueceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Então, Eliseu se levantou e andou pelo quarto e, novamente, se deitou e se estendeu sobre o garoto. A criança espirrou sete vezes e abriu os olhos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Eliseu chamou Geazi e disse: \"Chama a sunamita!\" Então, ele a chamou e, quando ela entrou no quarto, lhe disse: \"Pega teu filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Ela prostrou-se com o rosto ao chão, curvando-se aos seus pés, pegou seu filho e saiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Eliseu voltou a Gilgal. E havia fome na terra; e os filhos dos profetas estavam sentados perante ele. Ele disse a seu servo: \"Coloca uma grande panela no fogo e prepara um cozido para os filhos dos profetas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Um deles foi ao campo para colher vegetais e encontrou uma trepadeira selvagem, colheu frutos suficientes para encher a dobra de seu manto. Eles os cortaram e colocaram no cozido, mas não sabiam de que tipo eram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Assim serviram o cozido para os homens comerem. Mais tarde, enquanto comiam, eles gritaram dizendo: \"Homem de Deus, há morte na panela!\". E eles não puderam mais comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Eliseu disse: \"Trazei um pouco de farinha\". Ele a jogou dentro da panela e disse: \"Servi isto ao povo, então eles poderão comer\". E não havia mais nada perigoso na panela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Um homem veio de Baal-Salisa e trouxe ao homem de Deus vinte pães de cevada da nova colheita, e espigas frescas em seu alforje. Ele disse: \"Dá isto ao povo, para que possam comer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Seu servo disse: \"O quê? Como poderei eu servir isto a cem homens?\". Mas Eliseu disse: \"Dá isto ao povo, para que possam comer, pois assim diz Yahweh: \'Eles comerão e sobrará\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Então, o seu servo os serviu, eles comeram, e ainda sobrou um pouco, conforme a palavra que Yahweh prometera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naamã, comandante do exército do rei da Síria, era um grande e honrado homem diante de seu senhor, porque por ele Yahweh deu vitória aos sírios. Ele também era um forte e corajoso homem, mas estava com lepra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Os sírios haviam atacado em bando e tomado uma menina das terras de Israel. Ela servia à esposa de Naamã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'A menina disse a sua senhora: \"Eu queria muito que meu senhor estivesse com o profeta que vive em Samaria! Ele poderia ser curado de sua lepra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Então, Naamã foi e disse ao rei o que a menina da terra de Israel havia dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'O rei da Síria disse a Naamã: \"Vai agora e enviarei uma carta ao rei de Israel\". Naamã saiu e levou com ele dez talentos de prata, seis mil peças de ouro e dez mudas de roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Ele também levou para o rei de Israel a carta, que dizia: \"Logo que chegar a ti esta carta, saberás que eu te enviei Naamã, meu servo, para que o cures da sua lepra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Quando o rei de Israel leu a carta, ele rasgou as suas vestes e disse: \"Eu sou Deus, para matar ou fazer viver, para que o rei da Síria me envie um homem a fim de que eu o cure de sua lepra? Parece que ele está buscando motivo para se desentender comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Quando Eliseu, o homem de Deus, ouviu que o rei de Israel havia rasgado suas vestes, enviou um recado para o rei dizendo: \"Por que rasgaste tuas vestes? Deixe-o vir a mim agora e ele saberá que há profeta em Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Veio, pois, Naamã, com seus cavalos e com suas carruagens, e ficou à porta da casa de Eliseu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Eliseu enviou um mensageiro a ele, dizendo: \"Vai e mergulha no Jordão sete vezes e tua carne será restaurada; tu ficarás limpo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Mas Naamã ficou furioso, foi embora e disse: \"Vede! Eu estava certo de que ele sairia até mim e clamaria pelo nome de Yahweh, seu Deus e, ao tocar sua mão sobre o local, curaria minha lepra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Não são Abana e Farfar, os rios em Damasco, melhores que todas as águas de Israel? Não posso me banhar neles e ficar limpo?\". Então, ele retornou e foi embora irado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Os servos de Naamã se aproximaram e disseram: \"Meu pai, se o profeta mandasse fazer algo difícil, tu não farias? Quanto mais uma coisa tão simples! Mergulha e fica limpo\'.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Então, ele desceu e mergulhou sete vezes no Jordão, obedecendo às instruções do homem de Deus. Sua carne foi restaurada, como a carne de uma criança e ele foi curado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Naamã retornou ao homem de Deus, ele e toda a sua companhia, e veio e ficou diante dele. Ele disse: \"Vê, agora eu sei que não há Deus em toda a terra, exceto em Israel. Portanto, por favor, toma um presente de teu servo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Mas Eliseu respondeu: \"Como vive Yahweh, diante do qual estou, eu nada receberei\". Naamã insistiu com veemência para que Eliseu tomasse o presente, mas ele recusou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'E Naamã disse: \"Se não, eu te peço que deixe teu servo levar duas mulas de terra daqui. Teu servo não mais oferecerá nenhum holocausto para nenhum outro deus, mas a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Mas, em uma coisa, que Yahweh perdoe teu servo: quando meu rei vai à casa de Rimom, para lá adorar, ele se apoia em minha mão e eu me ajoelho no templo de Rimom. Quando eu me ajoellhar na casa de Rimom, que Yahweh perdoe teu servo nessa questão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Eliseu lhe disse: \"Vai em paz\". Naamã se foi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Quando Naamã já ia a uma pequena distância, Geazi, servo de Eliseu, o homem de Deus, disse consigo mesmo: \"Vê, meu senhor isentou a Naamã, o sírio, não recebendo das suas mãos os presentes que ele trouxe. Como vive Yahweh, eu correrei após ele e receberei dele alguma coisa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Então, Geazi seguiu após Naamã. Quando Naamã avistou alguém correndo atrás dele, desceu de sua carruagem para encontrá-lo e disse: \"Está tudo bem?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Geazi lhe respondeu: \"Meu senhor me enviou a ti, dizendo: \'Olha, agora mesmo vieram a mim, do alto da montanha de Efraim, dois jovens dos filhos dos profetas. Por favor, dá a eles um talento de prata e duas peças de roupa\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naamã respondeu: \"Estou muito feliz em lhe dar dois talentos\". Naamã insistiu com Geazi e amarrou dois talentos de prata em duas bolsas, com duas peças de roupas e as entregou a dois de seus servos, os quais carregavam as bolsas com a prata à frente de Geazi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Quando subiu a montanha, Geazi tomou as bolsas das mãos deles e as escondeu em sua casa, mandou os homens embora e eles sairam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Quando Geazi entrou, parou diante de seu senhor. Eliseu lhe disse: \"De onde vens?\". Ele respondeu: \"Teu servo não foi a lugar algum\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Eliseu disse a Geazi: \"Não estava meu espírito contigo, quando o homem desceu da carruagem para te encontrar? Era este o momento de aceitares dinheiro e roupas, plantação de oliveiras e de uvas, ovelhas e gados, servos e servas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Então, a lepra de Naamã virá sobre ti e teus descendentes para sempre\". Então, Geazi saiu de sua presença, com lepra tão branca como a neve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Os filhos dos profetas disseram a Eliseu: \"O lugar onde nós vivemos contigo é muito pequeno para todos nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Por favor, deixa-nos ir para o Jordão e permite que cada homem corte uma árvore lá, e edifiquemos um lugar onde possamos viver\". Eliseu respondeu: \"Vós podeis ir adiante\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Um deles disse: \"Por favor, vai com teus servos\". Eliseu respondeu: \"Eu irei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Então, foi com eles, e, quando foram para o Jordão, eles começaram a cortar árvores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Mas, enquanto um cortava, o machado caiu na água; ele gritou e disse: \"Oh não, meu senhor! Era emprestado!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Então, o homem de Deus disse: \"Onde caiu o machado?\". O homem mostrou a Eliseu o lugar. Então, ele cortou um pau, jogou na água e fez o ferro flutuar. Eliseu disse: \"Pega-o\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Então, o homem estendeu a sua mão e o pegou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Ora, o rei da Síria estava em guerra contra Israel. Ele consultou os seus servos, dizendo: \"O meu acampamento será nesse e naquele lugar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Então, o homem de Deus enviou ao rei de Israel, dizendo: \"Sê cuidadoso, não passe por aquele lugar, porque os sírios estão descendo para lá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Então, o rei de Israel enviou homens para aquele lugar, sobre o qual o homem de Deus o havia advertido. A advertência o salvou muitas vezes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'O rei da Síria ficou enfurecido sobre esse aviso. Ele chamou os seus servos e lhes disse: \"Não me contareis quem entre vós é a favor do rei de Israel?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Então, um dos seus servos disse: \"Não, rei meu senhor, é o profeta Eliseu, de Israel, quem conta para o rei de Israel as palavras que tu falas dentro do teu quarto!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'O rei replicou: \"Vai e vê onde Eliseu está. Então, eu enviarei homens para capturá-lo\". E lhe disseram: \"Vê, ele está em Dotã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Então, o rei enviou para Dotã cavalos, carruagens e um grande exército. Eles vieram à noite e cercaram a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Quando o servo do homem de Deus levantou-se bem cedo pela manhã e, quando saiu, eis que um grande exército com seus cavalos e suas carruagens cercaram a cidade. E o seu servo lhe disse: \"Oh, meu senhor! O que faremos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Eliseu respondeu: \"Não temas, porque os que estão conosco são muito mais numerosos do que os que estão com eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Eliseu orou e disse: \"Yahweh, eu Te rogo que abras seus olhos para que veja\". Assim Yahweh abriu os olhos do servo e ele viu. A montanha estava cheia de cavalos e carruagens de fogo cercando Eliseu!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Quando os sírios desceram até ele, Eliseu orou a Yahweh e disse: \"Torna esse povo cego, eu te peço\". Então, Yahweh os cegou como Eliseu pediu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'E Eliseu disse aos sírios: \"Este não é o caminho, tampouco esta é a cidade. Segui-me, e eu vos levarei ao homem ao qual vós procurais\". E ele os conduziu até Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'E aconteceu que, quando eles chegaram a Samaria, Eliseu disse: \"Yahweh abre os olhos desses homens para que eles vejam\". Yahweh abriu seus olhos e eles viram, e eis que eles estavam no meio da cidade de Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Assim que o rei de Israel os viu, disse a Eliseu: \"Meu pai, eu deveria matá-los? Eu deveria matá-los?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Eliseu respondeu: \"Tu não os matarás. Matarias tu aqueles a quem tens capturado com tua espada e o teu arco? Coloca pão e água diante deles, para que eles possam comer e beber, e deixa que voltem ao seu senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Então, o rei preparou mais comida para eles, e, quando eles terminaram de comer e beber, ele os despediu, e voltaram para o seu senhor. Aquelas tropas de soldados sírios, por um longo tempo, não retornaram à terra de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Depois disso, Ben-Hadade, rei da Síria reuniu todo o seu exército atacou Samaria e a cercou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Então, houve uma grande fome em Samaria. Eis que o cerco durou tanto e causou tamanha fome, que uma cabeça de jumento chegou a valer oitenta peças de prata, e uma caneca de esterco de pomba, cinco peças de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Enquanto o rei de Israel estava passando por um muro, uma mulher gritou-lhe, dizendo: \"Ajuda-me, meu senhor e rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Ele disse: \"Se Yahweh não te ajudar, como eu poderei socorrê-la? Acaso há trigo na eira ou vinho no lagar?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'O rei continuou: \"O que está te preocupando?\". Ela respondeu: \"Esta mulher me disse: \'Dá-me o teu filho para que o comamos hoje, e nós comeremos o meu filho amanhã\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Então, nós cozinhamos o meu filho e o comemos, e eu lhe disse no dia seguinte: \"Entrega teu filho para que possamos comê-lo, mas ela escondeu o seu filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Então, quando o rei ouviu as palavras da mulher, ele rasgou suas vestes (ora, ele estava passando pelo muro), e as pessoas olharam e viram que ele estava usando roupa de saco por baixo, cobrindo sua pele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Então, ele disse: \"Assim me faça Deus, e ainda mais, se a cabeça de Eliseu, filho de Safate, permanecer com ele hoje\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Estava, porém, Eliseu assentado em sua casa, e também os anciãos estavam assentados com ele. O rei enviou um homem adiante de si, mas, antes que o mensageiro chegasse a Eliseu, este disse aos anciãos: \"Vede como esse filho de um assassino mandou cortar minha cabeça? Vede: quando o mensageiro chegar, fechai a porta, e a mantende fechada. Não é o som dos passos do seu senhor atrás dele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Enquanto ele ainda estava falando com eles, eis que o mensageiro chegou e disse: \"O rei falou: \'Eis que este problema vem de Yahweh, que mais, pois, esperaria de Yahweh?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Eliseu disse: \"Ouvi a palavra de Yahweh. Assim diz Yahweh: \'Amanhã, por volta deste horário, uma medida de farinha fina será vendida por um siclo, e duas medidas de cevada por um siclo, no portão de Samaria\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Então, o capitão em cuja mão o rei se apoiava respondeu ao homem de Deus e disse: \"Vê, ainda que Yahweh fizesse janelas no céu, isso poderia acontecer?\" Eliseu respondeu: \"Eis que verás com teus próprios olhos isso acontecer, mas não comerás nada disso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Ora, havia quatro homens com lepra do lado de fora do portão de entrada da cidade. Eles disseram uns aos outros: \"Por que devemos ficar aqui sentados até morrermos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Se dissermos que devemos entrar na cidade enquanto há fome na cidade, morreremos lá. Mas, se ficarmos sentados aqui, também morreremos. Então, vamos ao exército dos sírios. Se eles nos deixarem viver, nós viveremos, e, se eles nos matarem, nós apenas morreremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'E, ao anoitecer, eles se levantaram para ir ao acampamento sírio. Quando eles chegaram ao ponto mais afastado do acampamento, não havia ninguém por lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Pois o Senhor havia feito com que o exército sírio ouvisse um ruído de carruagem de guerra e de cavalos — o ruído de outro grande exército — e eles disseram uns aos outros: \"Eis que o rei de Israel pagou os reis dos heteus e dos egípcios para virem contra nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Desse modo, os soldados se levantaram e fugiram, ao anoitecer, e deixaram suas tendas, seus cavalos, seus jumentos; deixando o acampamento como estava, fugiram para salvar suas vidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Quando os homens com lepra chegaram à parte mais afastada do acampamento, eles entraram numa tenda, comeram, beberam e foram embora levando de lá prata, ouro e roupas e esconderam tudo. Eles voltaram e entraram em outra tenda e dali também levaram o que encontraram e o esconderam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Então, disseram uns aos outros: \"Não é certo o que estamos fazendo. Este é um dia de boas-novas, mas estamos calados acerca disso. Se nós esperarmos até o romper do dia, o castigo virá sobre nós. Agora, então, vamos e anunciemos à casa do rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Assim, eles foram e chamaram os porteiros da cidade. Eles lhes disseram: \"Nós fomos ao acampamento dos sírios, mas não havia ninguém lá, somente cavalos e jumentos amarrados, e as tendas estavam como eles deixaram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'E os porteiros, gritando, anunciaram as notícias, e, então, elas foram ditas dentro da casa do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Dessa forma, o rei levantou-se de noite e disse aos seus servos: \"Agora eu vos direi o que os sírios nos fizeram. Eles sabem que nós estamos com fome. Então, eles saíram do acampamento para se esconderem nos campos. Eles estão dizendo: \'Quando eles saírem da cidade, nós os pegaremos vivos e entraremos na cidade\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Então, um dos servos do rei respondeu, dizendo: \"Eu te suplico que deixes alguns homens pegarem cinco dos cavalos que ainda restam, dos que foram deixados na cidade. Eles são todos como o resto da população de Israel que foi deixada—a maioria agora está morta; vamos enviá-los e vejamos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Assim, eles pegaram duas carruagens com cavalos e o rei os enviou atrás do exército dos sírios, dizendo: \"Ide e vede\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Eles foram atrás deles, até ao Jordão, e todo o caminho estava cheio de roupas e de utensílios que os sírios, na sua pressa, haviam abandonado. Assim, os mensageiros retornaram e anunciaram ao rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'O povo saiu e saqueou o acampamento dos sírios. Logo, uma medida de farinha fina foi vendida por um siclo, e duas medidas de cevada, por um siclo, assim como a palavra de Yahweh disse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'O rei havia ordenado que o capitão, em cuja mão ele se apoiava, ficasse encarregado do portão, mas as pessoas o pisotearam no portão. Ele morreu como o homem de Deus havia dito, quando o rei havia descido ao seu encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Dessa forma, isso aconteceu como o homem de Deus havia dito ao rei, dizendo: \"Por volta deste horário, no portão de Samaria, duas medidas de cevada estarão disponíveis por um siclo, e uma medida de farinha fina, por um siclo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Aquele capitão havia respondido ao homem de Deus, dizendo: \"Vê, ainda que Yahweh fizesse janelas no céu, isso poderia acontecer?\". Eliseu disse: \"Eis que tu verás isso acontecer com teus próprios olhos, mas não comerás nada disso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'E foi exatamente o que aconteceu com ele, pois o povo o pisoteou no portão e ele morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Eliseu havia falado para a mulher, cujo filho ele havia restaurado a vida. E disse-lhe: \"Levanta-te e vai com a tua família, e fica onde puderes em outra terra, porque Yahweh enviará fome sobre esta terra durante sete anos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Então, a mulher levantou-se e obedeceu a palavra do homem de Deus. Ela foi com a sua família e viveu na terra dos filisteus, durante sete anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'No final dos sete anos, a mulher retornou da terra dos filisteus, e foi até o rei para suplicá-lo por sua casa e por sua terra de volta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Ora, o rei estava falando com Geazi, servo do homem de Deus, dizendo: \"Por favor, conta-me todas as grandes coisas que Eliseu tem feito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Então, quando ele estava dizendo como Eliseu restaurou a vida da criança que estava morta, a mulher, cujo filho ele havia restaurado a vida, veio suplicar ao rei pela sua casa e pela sua terra. Então, disse Geazi: \"Meu senhor, rei, esta é a mulher e este é o filho dela, a quem Eliseu restaurou a vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Quando o rei perguntou à mulher acerca de seu filho, ela lhe explicou tudo. Então, o rei ordenou um oficial para ela, dizendo: \"Restitui-lhe tudo o que era dela e todas as suas colheitas dos seus campos, desde o dia em que ela deixou a terra até agora\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Depois, foi Eliseu a Damasco, onde Ben-Hadade, rei da Síria, estava doente. E lhe disseram: \"O homem de Deus chegou aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'O rei disse para Hazael: \"Leva contigo um presente e vai ao encontro do homem de Deus e, através dele, consulta a Yahweh, dizendo: \'Serei eu curado desta doença?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Então, Hazael foi ao encontro dele e levou consigo um presente de tudo de bom que havia em Damasco, carregado por quarenta camelos. Então, Hazael foi e ficou diante de Eliseu e disse: \"Teu filho, Ben-Hadade, rei da Síria, enviou-me a ti, perguntando: \'sararei eu dessa doença?\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Eliseu disse: \"Vai, diz para Ben-Hadade: \'Tu certamente recuperarás a saúde\', mas Yahweh mostrou-me que ele certamente morrerá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Então, Eliseu olhou fixamente para Hazael até que ele ficou envergonhado, e o homem de Deus chorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Hazael perguntou: \"Por que choras, meu senhor?\" Ele respondeu: \"Porque eu sei as maldades que farás ao povo de Israel. Colocarás fogo às suas fortalezas e matarás os seus jovens à espada; despedaçarás os seus pequeninos, e rasgarás o ventre das mulheres grávidas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Hazael respondeu: \"Quem teu servo é para fazer essas grandes coisas? Ele é apenas um cão\". Eliseu respondeu: \"Yahweh mostrou-me que tu serás o rei da Síria\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Então, Hazael deixou Eliseu e foi ao encontro do seu senhor, e este disse para ele: \"O que Elizeu te disse?\" Ele respondeu: \"Ele me disse que tu certamente te recuperarás\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Então, no dia seguinte, Hazael pegou um cobertor e molhou com água e cobriu o rosto de Ben-Hadade e, em seguida, ele morreu. Dessa forma, Hazael se tornou rei no lugar dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'No quinto ano de Jorão, filho de Acabe, rei de Israel, Jeorão começou a reinar. Ele era filho de Josafá, rei de Judá. Ele começou a reinar quando Josafá era o rei de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Jeorão tinha trinta e dois anos de idade quando começou a reinar, e reinou durante oito anos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Jeorão andou nos caminhos dos reis de Israel, conforme a família de Acabe; pois ele tinha como mulher a filha de Acabe, e ele fez o que era mau aos olhos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Contudo, por causa de seu servo Davi, Yahweh não quis destruir Judá, pois Ele lhe havia dito que sempre lhe daria descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Nos dias de Jeorão, Edom, sob a mão de Judá, se revoltou, e eles estabeleceram um rei para si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Então, Jeorão atravessou Zair com os seus comandantes e todas suas carruagens de guerra. Aconteceu que ele se levantou durante a noite, atacou e subjugou os edomitas que o haviam cercado e os comandantes das carruagens de guerra. Então, o exército de Jeorão escapou para as suas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Assim, Edom se rebelou contra o domínio de Judá até o dia de hoje, e, ao mesmo tempo, também Libna se rebelou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Os outros atos concernentes a Jeorão, tudo o que ele fez, não estão escritos no livro das Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Jeorão morreu e descansou com seus pais e foi enterrado junto a eles, na cidade de Davi. Então, Acazias, seu filho, tornou-se rei no lugar dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'No décimo segundo ano de Jorão, filho de Acabe, rei de Israel, Acazias filho de Jeorão, rei de Judá, começou a reinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Acazias tinha vinte e dois anos de idade quando começou a reinar; e reinou por um ano em Jerusalém. O nome de sua mãe era Atalia, filha de Onri, rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Acazias andou nos caminhos da casa de Acabe e fez o que era mau aos olhos de Deus, conforme a família de Acabe, pois Acazias era seu genro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Acazias foi com Jorão, filho de Acabe, para lutar contra Hazael, rei da Síria, em Ramote-Gileade. Os sírios feriram Jorão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'O rei Jorão voltou para ser curado em Jezreel das feridas que os sírios o tinham ferido em Ramá, quando ele lutou contra Hazael, rei da Síria. Então, Acazias, filho de Jeorão, rei de Judá, desceu a Jezreel para ver Jorão, filho de Acabe, porque havia sido ferido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'O profeta Eliseu chamou um dos filhos dos profetas e lhe disse: \"Prepara-te para viajar. Então, pega esse pequeno vaso de azeite em tuas mãos e vai para Ramote-Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Quando chegares lá, procura por Jeú, filho de Josafá, filho de Ninsi; entra, faze-o levantar dentre seus companheiros e conduze-o ao interior de um quarto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Então, pega o vaso de azeite e derrama-o sobre a cabeça dele e dize: \"Assim diz Yahweh: \'Eu te ungi rei sobre Israel\'\". Por isso, abre a porta e foge; não demores\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Então, o moço, o jovem profeta, foi para Ramote-Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Quando ele chegou, observou que os capitães do exército estavam sentados. Então, o jovem profeta disse: \"Capitão, eu venho com uma mensagem para ti\". Jeú perguntou: \"Para qual de nós?\" O jovem profeta respondeu: \"Para ti, capitão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Assim Jeú entrou na casa, subiu, e o profeta derramou o azeite na cabeça de Jeú e lhe disse: \"Yahweh, o Deus de Israel, diz: \'Eu te ungi rei sobre o povo de Yahweh, sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Deves matar a família de Acabe, teu senhor. Assim Eu terei vingado o sangue dos Meus servos, os profetas, e o sangue de todos os servos de Yahweh que foram assassinados pela mão de Jezabel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Assim toda a família de Acabe perecerá, e matarei todos os descendentes do sexo masculino, quer seja escravo, quer seja pessoa livre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Eu farei a casa de Acabe como a casa de Jeroboão, filho de Nebate e como a casa de Baasa, filho de Aías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Os cães comerão Jezabel em Jezreel, e lá não haverá ninguém para enterrá-la\'\". Então, o profeta abriu a porta e fugiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Então, Jeú saiu e foi até os servos de seu senhor, e um deles disse-lhe: \"Está tudo bem? Por que este louco veio a ti?\" Jeú lhes respondeu: \"Vós conheceis o homem e os tipos de coisas que ele diz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Eles disseram: \"Isso é mentira; conta-nos tudo\". Jeú respondeu: \"Ele disse isso para mim e também disse: \'Assim diz Yahweh: \'Eu te ungi como rei sobre Israel\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Então, cada um deles rapidamente tirou seus mantos e os colocaram embaixo de Jeú no topo dos degraus. E tocaram a trombeta e disseram: \"Jeú é rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Assim Jeú, filho de Josafá, filho de Ninsi, conspirou contra Jorão. Ora, Jorão estava defendendo Ramote-Gileade, ele e todo Israel, por causa de Hazael, rei da Síria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Mas o rei Jorão havia voltado a Jezreel para ser curado dos ferimentos que os sírios lhe haviam feito, quando ele pelejou contra o rei da Síria, Hazael. Jeú disse aos servos de Jorão: \"Se essa é a vossa opinião, então não deixeis ninguém escapar e sair da cidade, para ir e contar as notícias a Jezreel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Assim Jeú viajou em uma carruagem para Jezreel, pois Jorão estava em repouso lá. Ora, Acazias, rei de Judá, havia descido para ver Jorão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'O vigia estava posicionado na torre, em Jezreel e viu a tropa de Jeú vindo à distância. Ele anunciou: \"Eu vejo um grupo de homens chegando\". Jorão disse: \"Pega um cavaleiro, e envia-o para encontrá-los. Dize a ele para perguntar: \'Vós vindes em paz?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Assim Jeú disse: \"O que tu tens a ver com a paz? Vira-te e cavalga atrás de mim\". Então, o vigia contou ao rei: \"O mensageiro os encontrou, mas ele não está retornando\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Então, ele mandou um segundo homem montado a cavalo, que foi até eles e disse: \"O rei diz isto: \'Vós vindes em paz?\'\". Jeú respondeu: \"O que tu tens a ver com a paz? Vira-te e cavalga atrás de mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'De novo, o vigia reportou: \"Ele os encontrou, mas ele não está voltando. E, pelo andar da carruagem, ela está sendo guiada por Jéu, filho de Ninsi; está dirigindo como louco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Assim, Jorão disse: \"Deixa minha carruagem pronta\". Eles prepararam sua carruagem, e Jorão, rei de Israel, e Acazias, rei de Judá, guiaram, cada um a sua carruagem, para encontrar Jeú. Eles o encontraram na propriedade de Nabote, o jezreelita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Quando Jorão viu Jeú, ele disse: \"Estás vindo em paz, Jeú?\". Ele respondeu: \"Que paz pode haver, com os muitos atos idólatras de prostituição e bruxaria de tua mãe Jezabel?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Assim Jorão virou sua carruagem, fugiu e disse para Acazias: \"Há traição, Acazias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Então, Jeú puxou seu arco com toda força e atingiu Jorão entre seus ombros; a flecha atravessou seu coração e ele caiu de sua carruagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Então, Jeú disse a Bidcar, seu capitão: \"Pega-o e lança-o no campo de Nabote, o jezreelita. Lembra-te de quando tu e eu guiávamos juntos atrás de Acabe, teu pai, e Yahweh estabeleceu esta profecia contra ele:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, '\'Tão certo como Eu vi ontem o sangue de Nabote e o sangue de seus filhos, diz Yahweh, assim Eu te retribuirei neste campo\', diz Yahweh. Agora, então, pega e lança-o neste campo, de acordo com a palavra de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Quando Acazias, rei de Judá, viu isso, fugiu pelo caminho de Bete-Hagã. Mas Jeú o seguiu e disse: \"Matai-o, também, sobre a carruagem\", então eles atiraram nele na subida de Gur, que é próxima de Ibleão. Acazias fugiu para Megido e lá morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Os servos dele carregaram seu corpo em uma carruagem para Jerusalém e o enterraram em seu túmulo, junto a seus pais, na cidade de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Isso aconteceu no décimo primeiro ano de Jorão, filho de Acabe, tendo Acazias começado a reinar sobre Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Quando Jeú veio para Jezreel, Jezabel ouviu sobre isso e pintou seus olhos, arrumou seus cabelos, e olhou para fora da janela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Quando Jeú estava entrando no portão, ela lhe disse: \"Estás vindo em paz, tu, Zinri, assassino do teu senhor?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Jeú levantou os olhos para a janela e disse: \"Quem está do meu lado? Quem?\". Então, dois ou três eunucos olharam para fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Então, Jeú disse: \"Lançai-a daí abaixo\". Então, eles lançaram Jezabel para baixo, e um pouco do sangue dela se espalhou pela parede e pelos cavalos, e Jeú a pisoteou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Quando Jeú entrou no palácio, ele comeu e bebeu. Então, ele disse: \"Olhai agora aquela mulher maldita e a enterrai, pois ela é filha de rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Eles foram enterrá-la, mas não encontraram mais nada dela, senão o crânio, os pés e as palmas de suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Assim eles voltaram e contaram a Jeú. Ele disse: \"Esta é a palavra que Yahweh falou ao seu servo Elias, o tesbita, dizendo: \'Na terra de Jezreel, os cães comerão a carne de Jezabel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'e o corpo de Jezabel será como esterco, sobre a superfície dos campos na terra de Jezreel; assim, ninguém será capaz de dizer: \'Esta é Jezabel\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Acabe tinha setenta descendentes em Samaria. Jeú escreveu cartas e as enviou a Samaria, aos governantes de Jezreel, incluindo os anciãos e os tutores dos descendentes de Acabe, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '\"Vós, que estais com os descendentes do vosso senhor, e tendes carruagens de guerra, cavalos, uma cidade fortificada e armas, assim que receberdes esta carta,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'escolhei o melhor e mais capaz dos descendentes de vosso senhor e colocai-o no trono de seu pai, e lutai pela linhagem real de vosso senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Todavia, eles ficaram aterrorizados e disseram entre si: \"Vede, dois reis não puderam resistir diante de Jeú. Então, como podemos resistir?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Em seguida, o homem responsável pelo palácio, o homem que governava a cidade, os anciãos e os tutores dos filhos enviaram uma resposta de volta a Jeú: \"Somos teus servos. Faremos tudo o que pedires. Não faremos nenhum homem rei. Faz o que é bom aos teus olhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Então, Jeú escreveu uma segunda carta para eles, dizendo: \"Se estiverdes do meu lado e, se ouvirdes a minha voz, deveis tomar a cabeça dos descendentes de vosso senhor e trazei a mim, em Jezreel, até amanhã, neste horário\". Os descendentes do rei, que eram setenta, estavam com os homens importantes da cidade, que os criavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Quando a carta chegou até eles, pegaram os filhos do rei e os mataram, colocaram as setenta cabeças em cestos, e as enviaram a Jeú, em Jezreel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Um mensageiro veio a Jeú, dizendo: \"Trouxeram as cabeças dos filhos do rei\". Então, disse-lhe: \"Coloca-as em dois montões à entrada dos portões até o amanhecer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'De manhã, Jeú saiu e se pôs de pé, e disse para todo o povo: \"Vós sois inocentes. Vede, conspirei contra o meu senhor e o matei, mas quem matou a todos esses?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Agora, certamente, podeis compreender que nenhuma das palavras que Yahweh falou acerca da família de Acabe cairá por terra, pois Yahweh tem cumprido o que Ele falou através do seu servo Elias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Então, Jeú matou todos os que restavam da família de Acabe em Jezreel, e todos os seus oficiais importantes, seus amigos próximos, e seus sacerdotes. Nenhum deles sobreviveu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Em seguida, Jeú se levantou, saiu e foi para Samaria. Quando estava chegando a Bete-Equede dos pastores,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'ele encontrou os irmãos do rei Acazias, de Judá. Jeú disse-lhes: \"Quem sois vós?\" Eles responderam: \"Somos irmãos de Acazias, e estamos descendo para saudar os filhos do rei e os filhos da rainha Jezabel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Jeú disse aos seus homens: \"Apanhai-os vivos\". Então, eles os apanharam vivos e os mataram junto ao poço de Bete-Equede, todos os quarenta e dois homens. Nenhum deles escapou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Quando Jeú havia deixado o lugar, encontrou Jonadabe, filho de Recabe, que vinha ao seu encontro. Jeú cumprimentou-o e disse-lhe: \"Teu coração está comigo, assim como o meu está contigo?\". Jonadabe respondeu: \"Sim\". Jeú disse: \"Se ele estiver, dá-me a tua mão\". E Jonadabe deu-lhe sua mão, então Jeú tomou-o e colocou-o na carruagem com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Jeú disse: \"Vem comigo e vê o meu zelo para com Yahweh\". Então, ele levou Jonadabe em sua carruagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Quando ele retornou a Samaria, Jeú matou todos os descendentes de Acabe que restavam em Samaria, até destruir toda a linhagem real de Acabe, assim como Yahweh lhes havia anunciado anteriormente, por intermédio de Elias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Então, Jeú reuniu todo o povo e lhes disse: \"Acabe serviu pouco a Baal, mas Jeú o servirá muito mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Agora, portanto, chamai para mim todos os profetas de Baal, todos os seus adoradores e todos os seus sacerdotes. Não deixeis nenhum faltar, pois eu tenho um grande sacrifício para oferecer a Baal. Quem faltar não viverá\". No entanto, Jeú fez isso enganosamente, com intenção de matar todos os adoradores de Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Jeú disse: \"Separai um tempo para fazer uma reunião solene para prestar culto a Baal\". Então, eles anunciaram isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Então, Jeú enviou por todo o Israel, e todos os adoradores de Baal vieram, de modo que nenhum homem faltou. Eles vieram até o templo de Baal, e este ficou lotado de uma extremidade à outra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Jeú disse para o homem que guardava as roupas dos sacerdotes: \"Traz as vestimentas para todos os adoradores de Baal\". Então, o homem trouxe vestimentas para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Assim, Jeú foi com Jonadabe, filho de Recabe, até a casa de Baal, e ele disse aos adoradores de Baal: \"Examinai e observai que não se encontre aqui, entre vós, nenhum dos servos de Yahweh, mas somente os adoradores de Baal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Então, eles foram para oferecer sacrifícios e holocaustos. Jeú havia escolhido oitenta homens que ficariam do lado de fora e disse-lhes: \"Se algum dos homens que entrego em tuas mãos escapar, seja quem for que deixares escapar, a tua vida será tirada pela vida daquele que escapou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Então, assim que Jeú terminou de oferecer o holocausto, ele disse para os guardas e os capitães: \"Ide e matai-os. Não deixeis ninguém sair\". Então, eles os mataram ao fio de espada, e os guardas e os capitães os lançaram para fora e entraram na sala interior da casa de Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'E eles levaram para fora os postes que estavam na casa de Baal, e os queimaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Eles derrubaram o poste de Baal, destruíram sua casa e fizeram dela uma latrina; e assim o é até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Foi assim que Jeú destruiu de Israel a adoração a Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Contudo Jeú não abandonou os pecados de Jeroboão, filho de Nebate, os quais fizeram Israel pecar, isto é, a adoração a bezerros de ouro em Betel e Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Então, Yahweh disse a Jeú: \"Porque fizeste bem em executar o que era certo aos Meus olhos e fizeste à casa de Acabe conforme tudo o que estava em Meu coração, teus descendentes sentarão no trono de Israel por quatro gerações\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Todavia Jeú não teve o cuidado de caminhar na Lei de Yahweh, o Deus de Israel, com todo o seu coração. Ele não se afastou dos pecados de Jeroboão, que fizeram Israel pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Naqueles dias, Yahweh começou a cortar as regiões de Israel, e Hazael derrotou os israelitas nas fronteiras de Israel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'do Jordão para o oriente, toda a terra de Gileade, os gaditas e os rubenitas, e os manassitas, de Aroer, que é junto ao vale do Arnom, de Gileade a Basã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Quanto às outras questões acerca de Jeú, e tudo quanto ele fez, e todo o seu poder, não estão elas escritas no livro de Crônicas dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Jeú adormeceu com os seus ancestrais, e eles o sepultaram em Samaria. Então, Jeoacaz, seu filho, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'O período que Jeú reinou sobre Israel, em Samaria, foi de vinte e oito anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Quando Atalia, a mãe de Acazias, viu que seu filho estava morto, levantou-se e matou todas as crianças de descendência real.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Mas Jeoseba, filha do rei Jeorão e irmã de Acazias, tomou Joás, filho de Acazias, do meio dos filhos do rei, que seriam mortos, e escondeu-o de Atalia em um quarto, junto com a sua ama, para que o menino não fosse morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Ele esteve com Jeoseba, escondido na casa de Yahweh, durante seis anos, enquanto Atalia governava sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'No sétimo ano, Joiada enviou mensagens, trouxe os comandantes de cem dos cários e da guarda e levou-os consigo ao templo de Yahweh. Ele fez uma aliança com os comandantes, e os fez jurar solenemente na casa de Yahweh. Então, lhes mostrou o filho do rei,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'e ordenou-lhes dizendo: \"Eis o que deveis fazer: A terça parte de vós que vem no sábado manterá guarda na casa real,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'e a terça parte estará no portão de Sur e a outra terça parte estará no portão atrás da guarita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'E os dois outros grupos que não irão servir no sábado farão a guarda da casa de Yahweh para o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Fazei um círculo em volta do rei, cada homem com armas na mão. Qualquer pessoa que entrar no interior das fileiras seja morto. Deveis permanecer com o rei, quando ele sair e quando entrar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Os comandantes de cem obedeceram a tudo o que Joiada, o sacerdote, havia ordenado: cada um tomou seus homens, aqueles que serviriam no sábado e aqueles que deixariam de servir no sábado; e vieram a Joiada, o sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Então, o sacerdote Joiada entregou aos comandantes de cem as lanças e os escudos que pertenceram ao rei Davi e que estavam no templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Dessa forma, os guardas se levantaram, cada homem com sua arma na mão, desde o lado direito do templo até o lado esquerdo, próximo ao altar e ao templo, ficando em volta do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Então, Joiada trouxe o filho do rei, Joás, colocou-lhe a coroa e deu-lhe os decretos da Aliança. Eles o fizeram rei e o ungiram. Eles bateram palmas e disseram: \"Vida longa ao rei!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Quando Atalia ouviu o barulho da guarda e do povo, ela veio até o povo na casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Ela olhou e eis que o rei estava de pé junto à coluna, como era de costume, e os capitães e os trombeteiros estavam ao lado do rei. Todo o povo da terra regozijava-se e tocava trombetas. Então, Atalia rasgou suas vestes e gritou: \"Traição! Traição!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Assim, Joiada, o sacerdote, ordenou aos comandantes de cem que estavam sobre o exército; ele lhes disse: \"Levai-a para fora das fileiras. Matai à espada os que a seguirem\". Pois o sacerdote havia dito: \"Não a mateis na casa de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Então, eles a agarraram quando ela chegou ao local onde os cavalos entram no palácio, e ali foi morta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Dessa forma, Joiada fez uma aliança entre Yahweh, o rei e o povo, segundo a qual eles deveriam ser o povo de Yahweh; e também uma aliança entre o rei e o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Então, todo o povo da terra foi à casa de Baal e a derrubou. Eles demoliram os altares de Baal, despedaçaram suas imagens e mataram Matã, sacerdote de Baal, em frente aqueles altares. Então, o sacerdote Joiada designou guardas sobre o templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Joiada pegou os comandantes de cem, os cários, a guarda e todo o povo da terra. E juntos levaram o rei do templo de Yahweh, pelo caminho dos portões da guarda, até o palácio do rei. Então, Joás sentou no trono real.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'E todo o povo da terra se regozijou, e a cidade ficou tranquila depois de Atalia ter sido morta com a espada no palácio do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Joás tinha sete anos de idade quando ele começou a reinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'No sétimo ano de Jeú, Joás iniciou o seu reinado; ele reinou por quarenta anos em Jerusalém. O nome de sua mãe era Zíbia, de Berseba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Joás fez o que era reto aos olhos de Yahweh durante todo o tempo, pois o sacerdote Joiada o estava instruindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Entretanto os altares não foram retirados. O povo ainda continuava oferecendo sacrifícios e queimando incenso nos lugares altos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Joás disse aos sacerdotes: \"Todo o dinheiro das ofertas consagradas que for trazido ao templo de Yahweh, tanto os impostos do censo, pagamentos de votos quanto as ofertas voluntárias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Cada sacerdote deverá receber o dinheiro dessas ofertas de um dos seus tesoureiros e reparar qualquer estrago que for encontrado no templo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Mas, no vigésimo terceiro ano do rei Joás, os sacerdotes não tinham reparado nada no templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Então, o rei Joás chamou o sacerdote Joiada e os outros sacerdotes; e disse-lhes: \"Por que não tens consertado nada no templo? Agora não pegueis mais o dinheiro de seus contribuintes, mas pegai o que tem sido coletado para reparar o templo e dai àqueles que podem realizar os reparos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Então, os sacerdotes consentiram em não pegar mais dinheiro do povo e não reparar o templo eles mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Em vez disso, o sacerdote Joiada tomou um baú, abriu um buraco na tampa e colocou-o junto ao altar, do lado direito que as pessoas entravam na casa de Yahweh. Os sacerdotes que guardavam a entrada do templo colocaram todo o dinheiro que foi trazido, dentro do templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Sempre que eles viam que havia muito dinheiro no baú, o escriba do rei e o sumo sacerdote vinham e colocavam o dinheiro em sacos, e eles contavam o dinheiro encontrado no templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Eles deram o dinheiro contabilizado para as mãos dos homens que tomavam conta do templo de Yahweh. Eles pagaram aos carpinteiros e aos construtores que trabalharam no templo de Yahweh,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'e aos pedreiros e aos cortadores de pedras, para comprar madeira e pedras lavradas para reparar o templo de Yahweh, e para pagar todas as coisas que fossem necessárias para repará-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Mas o dinheiro que foi trazido ao templo de Yahweh não pagava a fabricação de quaisquer taças de prata, aparadores de lâmpadas, bacias, trombetas, ou qualquer utensílio de ouro ou prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Eles davam esse dinheiro para aqueles que faziam o trabalho de reparação do templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Além disso, eles não exigiam a prestação de contas do dinheiro pago aos homens que recebiam e pagavam os trabalhadores, pois esses homens eram honestos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Mas o dinheiro para as ofertas pela culpa e o dinheiro para as ofertas pelos pecados não era trazido para dentro do templo de Yahweh, porque este pertencia aos sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Então, Hazael, rei da Síria, atacou e lutou contra Gate, e a tomou. Hazael, então se voltou para atacar Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Joás, rei de Judá tomou todas as coisas consagradas que Josafá, Jeorão e Acazias, seus pais, reis de Judá, haviam consagrado, bem como todo ouro que foi encontrado nos tesouros do templo de Yahweh e do palácio do rei e os enviou para Hazael, rei da Síria; então, Hazael foi embora de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Quanto às outras questões acerca de Joás, tudo o que ele fez, não estão escritas no livro de Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Seus servos se levantaram e conspiraram juntos; eles atacaram Joás em Bete-Millo, no caminho que desce para Sila.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Jozacar, filho de Simeate, e Jozabade, filho de Somer, seus servos, o atacaram e ele morreu. Eles sepultaram Joás com seus ancestrais na cidade de Davi, e Amazias, seu filho, veio a ser rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'No vigésimo terceiro ano do reinado de Joás (filho de Acazias, rei de Judá), Jeoacaz, filho de Jeú, passou a reinar sobre Israel em Samaria, e reinou por dezessete anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Ele fez o que era mau aos olhos de Yahweh e seguiu os pecados de Jeroboão, filho de Nebate, com os quais ele havia levado Israel a pecar; e Jeoacaz não os abandonou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'A ira de Yahweh se acendeu contra Israel, e Ele os entregou repetidamente às mãos do rei Hazael, da Síria, e a Ben-Hadade, filho de Hazael.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Portanto, Jeoacaz implorou a Yahweh pedindo ajuda, e Yahweh ouviu as suas súplicas, pois viu o quanto o rei da Síria oprimia a Israel cruelmente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Então, Yahweh deu um libertador a Israel, libertando-os do poder dos sírios, e o povo de Israel passou a habitar em suas casas como antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'No entanto, não se desviaram dos pecados da casa de Jeroboão, que levou Israel a pecar, e continuaram neles. E o poste-ídolo permaneceu em Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Os sírios deixaram Jeoacaz com apenas cinquenta cavaleiros, dez carros e dez mil homens de infantaria, pois o rei da Síria os havia destruído e os fez como pó debaixo dos seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Com relação aos demais acontecimentos do reinado de Jeoacaz, seus feitos e poder, não estão eles escritos no livro de Crônicas dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Então, Jeoacaz descansou com seus antepassados e foi enterrado em Samaria. Jeoás, seu filho, tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'No trigésimo sétimo ano do reinado de Joás, rei de Judá, Jeoás, filho de Jeoacaz, passou a reinar sobre Israel, em Samaria; ele reinou por dezesseis anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Ele fez o que era mau aos olhos de Yahweh. Não abandonou nenhum dos pecados de Jeroboão, pelos quais ele levou Israel a pecar, contudo persistiu neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Com relação aos demais acontecimentos do reinado de Jeoás, seus feitos e o poder com qual lutou contra Amazias, rei de Judá, não estão eles descritos no livro de Crônicas dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Jeoás descansou com seus antepassados e Jeroboão se assentou em seu trono. Jeoás foi sepultado em Samaria, junto aos reis de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Eliseu ficou doente e tal enfermidade, posteriormente, causou sua morte. Então, Jeoás, rei de Israel, foi ao seu encontro e por ele chorou. Ele disse: \"Meu pai, meu pai, os carros de Israel e os cavaleiros o estão levando embora!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Assim disse Eliseu: \"Pega um arco e algumas flechas\". Então, Jeoás pegou um arco e algumas flechas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Eliseu disse ao rei de Israel: \"Coloca a tua mão no arco\", e ele o fez. Então, Eliseu pôs suas mãos sobre as do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Assim disse Eliseu: \"Abre a janela para o oriente\" e ele o fez. Então, Eliseu disse: \"Atira!\", e ele o fez. Em seguida, ele disse: \"Esta é a flecha da vitória de Yahweh, a flecha da vitória sobre a Síria, eis que irás atacar os sírios em Afeque até a sua consumação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Então, Eliseu disse: \"Pega as flechas\", e Jeoás o fez. Ele disse ao rei de Israel: \"Bate no chão\", Jeoás bateu três vezes e parou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Mas o homem de Deus se zangou com ele e disse: \"Deverias ter batido cinco ou seis vezes; assim, atacarias a Síria até sua total aniquilação, mas agora os atacarás apenas três vezes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Então, Eliseu faleceu e foi sepultado. Tropas moabitas invadiram a terra no início do ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Enquanto enterravam certo homem, viram um grupo de moabitas e jogaram o corpo na sepultura de Eliseu. Assim que o homem tocou os ossos de Eliseu, ele reviveu e ficou em pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Hazael, rei da Síria, oprimiu Israel durante todos os dias de Jeoacaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Mas Yahweh foi gracioso com Israel, e Se compadeceu deles, preocupou-Se com eles, por causa da Sua aliança com Abraão, Isaque e Jacó. Yahweh não os destruiu e ainda não os expulsou da Sua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Hazael, rei da Síria, faleceu e Ben-Hadade, seu filho, se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Jeoás, filho de Jeoacaz, tomou de Ben-Hadade, filho de Hazael, as cidades que haviam sido tomadas por guerra de Jeoacaz, seu pai. Jeoás o atacou três vezes e recuperou essas cidades de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'No segundo ano de Jeoás filho de Jeoacaz, rei de Israel, Amazias filho de Joás, começou a reinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Ele tinha vinte e cinco anos quando começou a reinar; reinou durante vinte e nove anos em Jerusalém. Sua mãe se chamava Jeodã de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Ele fez o que era certo aos olhos de Yahweh, embora, não como Davi, seu antepassado. Ele fez tudo o que seu pai, Joás, havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Porém os altares não foram destruídos. O povo continuava a sacrificar e queimar incenso neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Aconteceu que, logo que seu governo foi estabelecido, ele matou os servos que assassinaram seu pai, o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Contudo, não matou os filhos dos assassinos, pelo contrário, agiu em obediência ao que está escrito na Lei de Moisés, segundo a ordem de Yahweh: \"Os pais não serão mortos em lugar de seus filhos, nem os filhos serão mortos por causa dos pais. Entretanto, cada um será morto por seu próprio pecado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Ele mandou matar dez mil soldados de Edom no vale do Sal, também conquistou Selá em batalha e a chamou de Jocteel, como ainda é chamada nos dias de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Então, Amazias enviou mensageiros a Jeoás, filho de Jeoacaz, filho de Jeú, rei de Israel dizendo: \"Vem, vamos nos enfrentar face a face na batalha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Mas Jeoás, o rei de Israel, enviou mensageiros a Amazias, rei de Judá, dizendo: \"O espinheiro do Líbano mandou dizer ao cedro do Líbano: \'Dá tua filha como esposa para meu filho\', mas uma fera selvagem pisoteou o espinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'De fato, atacaste Edom e teu coração se encheu de orgulho. Orgulha-te em tua vitória, porém fica em casa. Por que te causarías problemas para caírdes tu e Judá contigo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Amazias, porém, não lhe deu atenção. Então, Jeoás, rei de Israel, atacou; ele e Amazias se enfrentaram face a face em Bete-Semes, no território de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Judá foi derrotado por Israel e todos os homens fugiram para casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Jeoás, rei de Israel, prendeu Amazias, rei de Judá, filho de Joás, filho de Acazias em Bete-Semes. Ele foi a Jerusalém e derrubou o muro de Jerusalém desde o portão de Efraim até a porta da esquina, destruiu quatrocentos côvados de seu muro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Ele tomou todo ouro e toda prata, todos os objetos encontrados no templo de Yahweh e os utensílios de valor do palácio do rei, como também os reféns, e voltou para Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Os demais atos de Jeoás, tudo o que fez, seu poder e como lutou com Amazias, rei de Judá, não estão escritos no livro de Crônicas dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Então, Jeoás descansou com seus antepassados e foi sepultado juntamente com os reis de Israel, e Jeroboão, seu filho, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Amazias, filho de Joás, rei de Judá, viveu mais quinze anos depois da morte de Jeoás, filho de Jeocaz, rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Os outros atos de Amazias não estão escritos no livro de Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Eles conspiraram contra Amazias em Jerusalém, e ele fugiu para Laquis. Ele fugiu para Laquis, mas mandaram persegui-lo em Laquis, onde o mataram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Eles o trouxeram sobre cavalos, e ele foi sepultado com seus antepassados na cidade de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Todo o povo de Judá tomou Azarias, que estava com dezesseis anos, e o fizeram rei em lugar de seu pai Amazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Foi Azarias que reconstruiu Elate e a restaurou para Judá, depois que o rei Amazias descansou com seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'No décimo quinto ano de Amazias, filho de Joás, rei de Judá, Jeroboão, filho de Jeoás, rei de Israel, começou a reinar em Samaria; ele reinou por quarenta e um anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Fez o que era mau aos olhos de Yahweh. Ele não se apartou de nenhum dos pecados de Jeroboão, filho de Nebate, com os quais fez Israel pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Ele restaurou a fronteira de Israel desde Lebo-Hamate até o mar de Arabá, seguindo os comandos da palavra de Yahweh, o Deus de Israel, que falou por meio de seu servo Jonas, filho de Amitai, o profeta, que era de Gate-Héfer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Pois Yahweh viu como era imenso o sofrimento de Israel para todos, tanto para escravos como para livres, e que não havia quem resgatasse Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Então, Yahweh disse que Ele não iria apagar o nome de Israel debaixo do céu; em vez disso, Ele os salvou pelas mãos de Jeroboão, filho de Jeoás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Quanto às outras questões relativas a Jeroboão, tudo o que ele fez, seu poder, como ele travou guerra e recuperou Damasco e Hamate, as quais estavam pertencendo a Judá, para Israel, não estão escritas no livro de Crônicas dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Jeroboão descansou com seus antepassados, com os reis de Israel, e Zacarias, seu filho, se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'No ano vinte sete de Jeroboão, rei de Israel, Azarias, filho de Amazias, rei de Judá, começou a reinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Azarias tinha dezesseis anos de idade quando começou a reinar. Ele reinou por cinquenta e dois anos em Jerusalém. O nome de sua mãe era Jecolias, natural de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Ele fez o que era correto aos olhos de Yahweh, assim como seu pai, Amazias, havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Entretanto, os altares das colinas não foram retirados. As pessoas continuavam a sacrificar e a queimar incenso neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Yaweh afligiu o rei com lepra, até o dia de sua morte, e ele viveu em uma casa separada. Jotão, o filho do rei, ficou responsável pelo palácio e governou o povo da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Quanto aos demais assuntos relacionados a Azarias, e a tudo o que ele fez, acaso não estão escritos no livro de Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Azarias dormiu com seus pais e foi sepultado na cidade de Davi, junto a seus ancestrais. Jotão, seu filho, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'No ano trinta e oito de Azarias, rei de Judá, Zacarias, filho de Jeroboão, reinou por seis meses sobre Israel, em Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Ele praticou o que era mau aos olhos de Yahweh, assim como seus pais haviam praticado. Ele não se apartou dos pecados de Jeroboão, filho de Nebate, que havia conduzido Israel a pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Salum, filho de Jabes, conspirou contra Zacarias, atacou-o em Ibleão e o matou. Então, ele reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Os demais atos relacionados a Zacarias estão escritos no livro de Crônicas dos reis de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Esta foi a palavra que Yahweh falou a Jeú, dizendo: \"Os teus descendentes até a quarta geração se assentarão no trono de Israel\". E assim aconteceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Salum, filho de Jabes, começou a reinar no ano trinta e nove de Uzias, rei de Judá, e reinou apenas um mês em Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Menaém, filho de Gadi, veio de Tirza para Samaria. Ele atacou e matou Salum, filho de Jabes, e reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Os demais assuntos relacionados a Salum e a conspiração que ele tramou estão escritos no livro de Crônicas dos reis de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Então, Menaém, vindo de Tirza, atacou Tifsa e seus arredores, com todos os seus habitantes, porque não lhe abriram a cidade. Menaém saqueou Tifsa e rasgou o ventre de todas as mulheres grávidas da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'No ano trinta e nove de Azarias, rei de Judá, Menaém, filho de Gadi, começou a reinar sobre Israel. Ele reinou dez anos em Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Menaém praticou o que era mau aos olhos de Yahweh. Por toda a sua vida, ele não se apartou dos pecados de Jeroboão, filho de Nebate, que havia levado Israel a pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Então, Pul, rei da Assíria, atacou a terra, e Menaém entregou a Pul mil talentos de prata, a fim de conquistar o apoio dele e manter-se no reino de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Para entregar essa soma ao rei da Assíria, Menaém obrigou cada homem rico de Israel a pagar cinquenta siclos de prata. Assim, o rei da Assíria suspendeu a invasão e retirou-se da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Quanto aos demais assuntos relacionados a Menaém, e a tudo o que ele fez, não estão porventura escritos no livro de Crônicas dos reis de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Então, Menaém dormiu com seus ancestrais, e Pecaías, seu filho, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'No ano cinquenta de Azarias, rei de Judá, Pecaías, filho de Menaém, começou a reinar sobre Israel, ele reinou dois anos em Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Praticou o que era mau aos olhos de Yahweh e não se apartou dos pecados de Jerobão, filho de Nebate, que havia levado Israel a pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Pecaías tinha um oficial chamado Peca, filho de Remalias, que conspirou contra ele e o matou, junto com Argobe e Arié, em Samaria, a cidadela do palácio do rei. Com ele estavam cinquenta homens gileaditas. Ele o matou e reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Os demais assuntos relacionados a Pecaías e a tudo o que ele fez estão escritos no livro de Crônicas dos reis de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'No ano cinquenta e dois de Azarias, rei de Judá, Peca, filho de Remalias, começou a reinar sobre Israel; reinou vinte anos em Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Ele praticou o que era mau aos olhos de Yahweh e não se apartou dos pecados de Jeroboão, filho de Nebate, que levou Israel a pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Nos dias de Peca, rei de Israel, Tiglate-Pileser, rei da Assíria, atacou e tomou Ijon, Abel-Bete-Maaca, Janoa, Quedes, Hazor, Gileade, a Galileia e toda a terra de Naftali e levou os seus habitantes cativos para a Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Então, Oseias, filho de Elá, tramou uma conspiração contra Peca, filho de Remalias, atacou-o e o matou. Assim, no ano vinte de Jotão, filho de Uzias, Oseias começou a reinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Os demais assuntos relacionados a Peca e a tudo o que ele fez estão escritos no livro de Crônicas do reis de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'No ano dois de Peca, filho de Remalias, rei de Israel, Jotão, filho de Uzias, rei de Judá, começou a reinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Ele tinha vinte e cinco anos de idade quando começou a reinar, reinou dezesseis anos em Jerusalém. O nome de sua mãe era Jerusa, a filha de Zadoque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Jotão fez o que era correto aos olhos de Yahweh. Ele seguiu todo o exemplo de seu pai, Uzias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Porém os altares das colinas não foram retirados. O povo continuava sacrificando e queimando incenso nos altares. Jotão edificou o portão superior do templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Os demais assuntos sobre Jotão e sobre tudo o que ele fez, acaso não estão escritos no livro de Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Naqueles dias Yahweh começou a enviar Rezim, rei da Síria, e Peca, filho de Remalias, contra Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Jotão dormiu com seus pais e foi sepultado junto a seus antepassados na cidade de Davi, seu antepassado. Então, Acaz, seu filho, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'No décimo sétimo ano de Peca, filho de Ramalias, Acaz, filho de Jotão, rei de Judá, começou a reinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Acaz tinha vinte anos de idade quando ele começou a reinar, e reinou por dezesseis anos em Jerusalém. Ele não fez o que era reto aos olhos de Yahweh, seu Deus, assim como Davi, seu antecessor havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Ao invés disso, ele andou no caminho dos reis de Israel; até colocou seu filho no fogo como holocausto, seguindo as abomináveis práticas das nações, que Yahweh expulsara do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Ele sacrificou e queimou incenso nos lugares altos, nos outeiros e debaixo de qualquer árvore verde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Então, Rezim, rei da Síria e Peca, filho de Remalias, rei de Israel, veio até Jerusalém para atacar. Eles cercaram Acaz, mas não puderam conquistar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Naquela ocasião, Rezim, rei da Síria, recuperou Elate da Síria e expulsou os homens de Judá para fora de Elate. Então, os arameus vieram para Elate, onde moram até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Então, Acaz enviou mensageiros a Tiglate-Pileser, rei da Assíria dizendo: \"Sou teu servo e teu filho. Vem e me salva das mãos do rei da Síria e da mão do rei de Israel, que me atacou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Acaz, então, pegou a prata e o ouro que foi achada no templo de Yahweh, e no meio dos tesouros do palácio do rei, e os mandou como presente ao rei da Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'O rei da Assíria o ouviu, e subiu contra Damasco, a conquistou e aprisionou os habitantes para Quir. Também matou Rezim, o rei da Síria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'O rei Acaz foi a Damasco para encontrar Tiglate-Pileser, rei da Assíria. Em Damasco, ele viu um altar. Ele enviou a Urias, o sacerdote, um modelo do altar com seu padrão e o desenho de todas as ferramentas necessárias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Urias, o sacerdote, construiu o altar para ser como as plantas que o rei Acaz lhe enviou de Damasco. Ele terminou antes que o rei Acaz retornasse de Damasco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Quando o rei, regressou de Damasco, viu o altar e ofereceu sacrifícios sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Ele fez seu holocausto e sua oferta de cereais, derramou sua oferta de bebida e aspergiu o sangue de sua oferta pacífica no altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'O altar de bronze que estava diante de Yahweh, ele o trouxe da frente do templo, dentre o altar e o templo de Yahweh, e o pôs no lado norte do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Então, o rei Acaz mandou Urias, o sacerdote, dizendo: \"No grande altar, queima o holocausto matinal e de tarde, a oferta de cereais, o holocausto do rei e sua oferta de cereais, com o holocausto de todos da terra, suas ofertas de cereais e suas ofertas de bebida. Aspergirás nele todo o sangue de todos os holocaustos e o sangue dos sacrifícios. Porém, no altar de bronze, eu pedirei orientação a Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Urias, o sacerdote, fez como o rei Acaz ordenara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'O rei Acaz removeu os painéis e as bases das estantes portáteis; e o mar, detrás das costas dos bois de bronze que estava embaixo, e o colocou sobre um pavimento de pedra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Ele removeu a cobertura para o sábado que eles construiram no templo, por toda a entrada do rei, fora do templo de Yahweh, por causa do rei da Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Para as outras questões relativas a Acaz e o que ele realizou, não estão elas escritas no Livro de Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Acaz morreu e foi sepultado junto com os seus antepassados na cidade de Davi. Ezequias, seu filho, se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'No décimo segundo ano de Acaz, rei de Judá, Oseias, filho de Elá, começou a reinar. Ele governou em Samaria sobre Israel por nove anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Ele fez o que era mau aos olhos de Yahweh, contudo, não como os reis de Israel que foram antes dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Salmanasar, rei da Assíria, o atacou, e Oseias ficou sendo servo dele e lhe pagava tributos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Então, o rei da Assíria percebeu que Oseias estava conspirando contra ele, porque Oseias havia enviado mensageiros a Sô, rei do Egito; além disso, ele não pagava tributos ao rei da Assíria, a cada ano como fazia antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Então, o rei da Assíria o amarrou e o encarcerou na prisão. Depois disso, o rei da Assíria subiu por toda a terra, atacou Samaria e a sitiou por três anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'No nono ano de Oseias, o rei da Assíria tomou Samaria e levou Israel cativo para a Assíria. Ele os colocou em Hala, próximo a Habor, rio de Gozã, e nas cidades dos medos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Esse cativeiro aconteceu porque o povo de Israel havia pecado contra Yahweh, o seu Deus, que os fez subir da terra do Egito, de debaixo do poder de Faraó, rei do Egito. O povo estava adorando outros deuses');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'e andaram nas práticas das nações que Yahweh havia expulsado de diante do povo de Israel e em outras práticas que os reis de Israel introduziram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'O povo de Israel fez secretamente coisas que não eram retas contra Yahweh, seu Deus. Eles edificaram santuários em todas as suas cidades, desde a torre dos vigias até a cidade fortificada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Eles também criaram pilares sagrados de pedra e postes a Asera em todo outeiro alto e debaixo de todas as árvores verdes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Eles queimaram incenso em todos os santuários, como as nações fizeram, aquelas que Yahweh expulsou de diante deles. Os israelitas fizeram coisas más para provocarem a ira de Yahweh;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'eles adoraram ídolos, sobre os quais Yahweh lhes dissera: \"Não façais isso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Ainda assim, Yahweh advertiu a Israel e a Judá por intermédio de todos os profetas e de todos os videntes, dizendo: \"Convertei-vos de vossos maus caminhos, guardai Meus estatutos e mandamentos, tende cuidado para guardar toda a Lei que ordenei a vossos pais e que Eu vos enviei por intermédio dos Meus servos, os profetas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Mas eles não quiseram ouvir; ao invés disso, eles foram muito teimosos como seus pais, que não confiaram em Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Eles rejeitaram os Seus estatutos, a aliança que havia feito com os seus antepassados e os decretos da aliança que Ele lhes havia dado. Eles seguiram práticas inúteis, tornando-se inúteis. Eles seguiram as nações pagãs que estavam ao redor deles, aquelas às quais Yahweh lhes havia ordenado não imitar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Eles ignoraram todos os mandamentos de Yahweh, seu Deus. Fizeram imagens de metal fundido de dois bezerros para cultuar. Fizeram um poste a Aserá e adoraram todas as estrelas dos céus e a Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Eles sacrificaram seus filhos e suas filhas no fogo em holocaustos, usaram adivinhação e encantamentos, venderam-se para fazer o que era mau aos olhos de Yahweh, provocando-Lhe à ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Portanto, Yahweh ficou muito indignado com Israel e os tirou diante da Sua face. Não ficou mais ninguém, além da tribo de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Nem mesmo Judá guardou os mandamentos de Yahweh, seu Deus, mas, em vez disso, seguiu as mesmas práticas pagãs que Israel estava seguindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Assim, Yahweh rejeitou todos os descendentes de Israel; Ele os afligiu e os entregou nas mãos daqueles que tomariam posse do despojo, até que os expulsou da Sua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Yahweh rasgou Israel da linhagem real de Davi; e eles fizeram rei a Jeroboão, filho de Nebate. Jeroboão afastou Israel de seguir Yahweh e os fez cometer um grande pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'O povo de Israel seguiu todos os pecados de Jeroboão e eles não se afastaram deles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'assim, Yahweh, tirou Israel da Sua presença, como Ele havia dito por meio de todos os Seus servos, os profetas, que Ele faria. Por isso, Israel foi transportado da sua própria terra para a Assíria, e assim é até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'O rei da Assíria trouxe gente da Babilônia, de Cuta, de Ava, de Hamate e de Sefarvaim, e os colocou nas cidades de Samaria, em lugar do povo de Israel. Eles ocuparam Samaria e viveram em suas cidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Aconteceu que, quando começaram a morar ali, não honraram a Yahweh. Então, Yahweh enviou leões que mataram alguns deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Por isso, falaram ao rei da Assíria, dizendo: \"As nações que tens levado e colocado nas cidades de Samaria não conhecem as práticas exigidas pelo Deus da terra. Assim, ele enviou leões entre eles e, eis que, os leões estão matando pessoas lá porque eles não conhecem as práticas exigidas pelo Deus da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Então, o rei da Assíria ordenou, dizendo: \"Levai para lá um dos sacerdotes que trouxestes, e deixai-o ir e viver lá, deixai-o ensinar as práticas exigidas pelo Deus da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Desse modo, um dos sacerdotes que eles haviam transportado de Samaria veio e habitou em Betel; ele os ensinou como deveriam temer Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Cada povo fez seus próprios deuses, e os colocaram nos santuários que os samaritanos tinham feito—todos os povos das cidades onde viviam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'O povo da Babilônia fez Sucote-Benote; o povo de Cuta fez Nergal; o povo de Hamate fez Asima;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'os aveus fizeram Nibaz e Tartaque; e os sefarvitas queimavam seus filhos em holocausto a Adrameleque e Anameleque, deuses de Sefarvaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Eles também temiam a Yahweh, e nomearam entre si sacerdotes para os lugares altos, os quais sacrificavam em favor deles, nos santuários dos templos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Temiam a Yahweh e também adoravam os seus próprios deuses, segundo os costumes das nações do meio das quais haviam sido retirados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Até hoje, eles persistem em seus antigos costumes. Eles nem temem a Yahweh, nem seguem os estatutos, os decretos, a Lei ou os mandamentos que Yahweh deu ao Seu povo Jacó—a quem Ele deu o nome de Israel—');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'e com quem Yahweh havia feito uma aliança e Lhes ordenara: \"Não temais outros deuses, nem vos inclineis diante deles, nem os adoreis, nem sacrifiqueis a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Mas Yahweh, que vos fez subir da terra do Egito com grande poder e braço estendido, é a Quem vós deveis honrar; é perante Ele que vos prostrareis, e é a Ele que sacrificareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Os estatutos e decretos, a Lei e os mandamentos que Ele vos escreveu, os guardareis para sempre. E não devais temer outros deuses,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'e a aliança que fiz convosco, não esquecereis; nem temereis outros deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Mas a Yahweh, vosso Deus, é a Quem temereis. E Ele vos livrará das mãos de todos os vossos inimigos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Contudo, eles não ouviram, pois continuaram a fazer o que haviam feito no passado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Dessa forma, essas nações temiam a Yahweh e também adoravam as suas imagens esculpidas, e seus filhos fizeram o mesmo—como fizeram os filhos de seus filhos. Eles continuaram a fazer o que seus antepassados fizeram, até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'No terceiro ano de Oseias, filho de Elá, rei de Israel, Ezequias, filho de Acaz, rei de Judá começou a reinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Tinha vinte e cinco anos quando começou a reinar; reinou vinte e nove anos em Jerusalém. O nome de sua mãe era Abi; ela era filha de Zacarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Ele fez o que era certo aos olhos de Yahweh, seguindo o exemplo de tudo que Davi, seu antepassado, havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Ele removeu os santuários, destruiu os pilares sagrados de pedra e derrubou as imagens de Aserá. Quebrou em pedaços a serpente de pedra que Moisés havia feito, porque naqueles dias o povo de Israel queimava incenso a ela; era chamada de \"Neustã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Ezequias confiava em Yahweh, o Deus de Israel, de maneira que, depois dele, não houve ninguém parecido dentre todos os reis de Judá, tampouco dentre os reis que reinaram antes dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Ele se manteve fiel a Yahweh. Não parou de segui-Lo, mas guardou Seus mandamentos, os quais Yahweh ordenou a Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Assim, Yahweh estava com Ezequias e, por onde ele foi, prosperou. Ele se rebelou contra o rei da Assíria e não o serviu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Atacou os filisteus até Gaza e suas fronteiras, desde a torre de vigia até a cidade fortificada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'No quarto ano do reinado do rei Ezequias, que era o sétimo de Oseias, filho de Elá, rei de Israel, Salmanasar, rei da Assíria, atacou Samaria e a cercou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'No fim de três anos, eles a tomaram, no sexto ano de Ezequias, que era o nono de Oseias, rei de Israel; dessa forma, Samaria foi capturada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Assim, o rei da Assíria levou Israel cativo para Assíria e o colocou em Hala, junto a Habor, rio de Gozã, e nas cidades dos medos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Ele assim o fez porque eles não obedeceram à voz de Yahweh, seu Deus, mas transgrediram Sua aliança, tudo o que Moisés, servo de Yahweh, havia ordenado. Eles se recusaram a ouvir ou fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'No décimo quarto ano do rei Ezequias, Senaqueribe, rei da Assíria, atacou todas as cidades fortificadas de Judá e as tomou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Então, Ezequias, rei de Judá, enviou uma mensagem ao rei da Assíria, que estava em Laquis, dizendo: \"Eu te ofendi. Retira-te de mim. Tudo o que me impuseres eu suportarei\". O rei da Assíria impôs a Ezequias, rei de Judá, o pagamento de trezentos talentos de prata e trinta talentos de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Então, Ezequias deu-lhe toda a prata que encontrou na casa de Yahweh e nos tesouros do palácio do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Depois, Ezequias retirou todo o ouro das portas do templo de Yahweh e dos pilares que ele havia revestido; ele deu o ouro ao rei da Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Mas o rei da Assíria mobilizou seu grande exército, enviando Tartã, Rabsaris e o comandante chefe de Laquis ao rei Ezequias em Jerusalém. Eles viajaram pelas estradas e chegaram a Jerusalém, aproximando-se do aqueduto do açude superior, na estrada que dava no campo dos lavandeiros e permaneceram ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Tendo eles chamado pelo rei Ezequias, vieram Eliaquim, filho de Hilquias, que era encarregado de cuidar da casa; Sebna, o escriba; e Joá, filho de Asafe, o cronista, ao encontro deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Então, o comandante chefe disse-lhes: \"falai a Ezequias que o grande rei, o rei da Assíria, disse: \'Qual é a fonte da tua confiança?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Tu falas apenas palavras inúteis, dizendo que tens aliados e força para a guerra. Em quem estás confiando? Quem te deu coragem para se rebelar contra mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Eis, que tu confias neste caniço quebrado que é o Egito, o qual, se alguém nele se apoiar, atravessará sua mão e o perfurará. Isso é o que o Faraó, rei do Egito, é para qualquer um que confiar nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Se, porém, me dissesses: \'Nós confiamos em Yahweh, nosso Deus\', não é Ele cujos altares e santuários Ezequias retirou e disse a Judá e a Jerusalém: \'Devei adorar perante esse altar em Jerusalém\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Agora, pois, eu quero fazer uma boa oferta do meu senhor, o rei da Assíria. Eu te darei dois mil cavalos, se fores capaz de encontrar cavaleiros para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Como poderias resistir a um só capitão dos menores dos servos de meu senhor? Tu colocaste tua confiança no Egito por causa de carros e cavaleiros!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Porventura, viajei até aqui, sem Yahweh, para atacar este lugar e o destruir? Assim disse Yahweh: \'Ataca esta terra e a destrua\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Então, Eliaquim, filho de Hilquias, Sebna e Joá disseram ao comandante chefe: \"Por favor, fala com teus servos em aramaico, para que possamos compreender. Não fales conosco na língua de Judá, aos ouvidos do povo que está em cima do muro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Mas o comandante chefe lhes disse: \"Por acaso, meu senhor me enviou para falar essas palavras a vosso senhor e a vós? Não me enviou ele para os homens que se assentam sobre a muralha, que juntamente convosco terão que comer seus próprios excrementos e beber sua própria urina?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Assim, o comandante chefe permaneceu e bradou em alta voz na língua dos judeus, dizendo: \"Escutai a palavra do grande rei, o rei de Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'O rei diz: \'Não deixeis que Ezequias vos engane, pois ele não é capaz de vos resgatar do meu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Não deixeis que Ezequias vos faça confiar em Yahweh, dizendo: \'Yahweh certamente nos resgatará; esta cidade não será entregue as mãos do rei da Assíria\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Não escuteis a Ezequias, pois isto é o que o rei da Assíria diz: \'Fazei paz comigo e vinde até mim. Então, todos dentre vós comerão de sua própria vide e de sua própria figueira e beberão água de sua própria cisterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Assim, fareis até que eu venha e vos leve embora para uma terra semelhante à vossa, uma terra de grãos e vinho novo, uma terra de pão e vinhas, uma terra de oliveiras e mel, de forma que vivais e não morrais\'. Não deis ouvidos a Ezequias quando ele vos tentar persuadir, dizendo: \'Yahweh nos resgatará\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Por acaso algum dos deuses dos povos os resgatou do poder do rei da Assíria? Onde estão os deuses de Hamate e de Arpade?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Onde estão os deuses de Sefarvaim, de Hena e de Iva? Algum desses resgatou Samaria de minha mão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Dentre todos os deuses das terras, há algum deus que resgatou sua terra do meu poder? Como poderia Yahweh salvar Jerusalém do meu domínio?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Mas o povo permaneceu em silêncio e não respondeu, porque o rei ordenara: \"Não lhe respondais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Então, Eliaquim, filho de Hilquias, que era encarregado de cuidar da casa; Sebna, o escriba; e Joá, filho de Asafe, o cronista, foram a Ezequias com suas vestes rasgadas e reportaram a ele as palavras do comandante chefe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Aconteceu que o rei Ezequias ouviu o relatório deles, rasgou as suas vestes, cobriu-se com pano de saco e entrou no templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Ele enviou Eliaquim, o mordomo, e Sebna, o escriba, e os anciãos dos sacerdotes, todos cobertos de sacos, a Isaías, filho de Amós, o profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Eles lhe disseram: \"Ezequias diz: \'Este dia é um dia de aflição, repreensão e desgraça, porque as crianças estão no tempo de nascer, mas não há nenhuma força para que nasçam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Pode ser que Yahweh ouça todas as palavras do chefe comandante, que o rei da Assíria enviou para provocar o Deus vivo, e repreenda essas palavras. Agora, levanta teu clamor pelos remanescentes que ainda estão aqui\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Assim, os servos do rei Ezequias vieram para Isaías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'E Isaías lhes disse: \"Dizei ao teu senhor: \'Yahweh diz: \'Não temas as palavras que tu ouviste, com as quais os servos do rei da Assíria tem me insultado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Vê, Eu colocarei um espírito nele, e ele ouvirá uma certa notícia e voltará para a sua própria terra. Eu farei ele cair pela espada em sua própria terra\"\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Então, o principal comandante retornou e encontrou o rei da Assíria lutando contra Libna, porque ele havia ouvido que o rei havia saído de Laquis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Então, Senaqueribe ouviu que Tiraca, rei da Etiópia e Egito, havia se mobilizado para lutar contra ele. Assim, ele enviou mensageiros novamente para Ezequias com uma mensagem:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '\"Diz para Ezequias, rei de Judá: \'Não deixes o teu Deus, em quem tu confiaste, enganar-te dizendo, \'Jerusalém não será dada na mão do rei da Assíria\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Vê, tu tens ouvido o que os reis da Assíria têm feito a todas as terras, destruindo-as completamente. Assim sendo, serás tu poupado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Os deuses das nações os têm poupado? As nações que meus pais destruíram: Gozã, Harã, Rezefe e o povo do Eden, em Telassar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Onde estão os reis de Hamate, o rei Arpade, o rei das cidades de Sefarvaim, de Hena e de Iva?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Ezequias recebeu essa carta dos mensageiros e a leu. Então, ele foi para o templo de Yahweh e a colocou diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Então, Ezequias orou diante de Yahweh e disse: \"Yahweh dos exércitos, Deus de Israel, Tu que sentas acima dos querumbins, Tu és o único Deus sobre todos os reinos da terra. Tu fizeste os céus e a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Inclina o Teu ouvido, Yahweh, e ouve. Abre os Teus olhos, Yahweh, e vê; ouve todas as palavras de Senaqueribe, que ele tem enviado para zombar do Deus vivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Verdadeiramente, Yahweh, o rei da Assíria tem destruído as nações e suas terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'Eles têm colocado seus deuses no fogo, porque eles não eram deuses, mas o trabalho das mãos dos homens, apenas madeira e pedra. Assim, os assírios os têm destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Agora então Yahweh, nosso Deus, salva-nos do seu poder, eu imploro, de forma que todos os reinos da terra saibam que Tu, Yahweh, és o único Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Então, Isaías, filho de Amoz, enviou uma mensagem para Ezequias, dizendo: \"Yahweh, o Deus de Israel, diz: \'Visto que tu tens orado a Mim acerca de Senaqueribe, rei da Assíria, Eu te ouvi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Esta é a palavra que Yahweh disse sobre ele: \'A virgem, filha de Sião, despreza e ri de ti para escarnecer. A filha de Jerusalém meneia sua cabeça para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'A quem tens desafiado e insultado? E contra quem tu tens orgulhosamente exaltado a tua voz e levantado os teus olhos? Contra o Santo de Israel!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Por meio dos teus mensageiros, tens desafiado o Senhor e dito: \'Com a multidão de minhas carruagens, eu tenho subido às alturas das montanhas, às elevações mais altivas do Líbano. Eu cortarei os altos cedros e os melhores ciprestes ali. Entrarei nas suas partes mais remotas, na sua floresta mais frutífera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Cavei cisternas e bebi águas estrangeiras. Sequei todos os rios do Egito sob a sola dos meus pés\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Tu não tens ouvido que Eu determinei isso há muito tempo e como tenho operado em tempos antigos? Agora, Eu estou executando estas coisas. Tu estás aqui para reduzir as cidades impenetráveis a montes de ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Seus habitantes, de pouca força, são despedaçados e envergonhados. Eles são plantas no campo, grama verde, a grama sobre o telhado ou grama no campo, queimadas antes de crescerem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Mas Eu conheço o teu sentar, o teu ir e vir e a tua fúria contra Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Por causa dessa fúria contra Mim e por causa da tua arrogância que tem chegado aos Meus ouvidos, Eu colocarei um anzol no teu nariz e Meu cabresto na tua boca; Eu te farei voltar pelo caminho de onde vieste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Este será o Meu sinal para ti: Neste ano, comereis do que nascer naturalmente e, no segundo ano, comereis do que brotar disso. Porém, no terceiro ano, tereis de plantar e colher, plantar vinhas e comer do seu fruto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'O remanescente da casa de Judá que sobreviver fincará raízes e dará frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Porque, de Jerusalém, virá um remanescente, e, do monte Sião, virão os sobreviventes. O zelo de Yahweh dos Exércitos fará isto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Portanto, acerca do rei da Assíria, Yahweh diz: \"Ele não entrará nesta cidade, nem disparará flecha alguma aqui. Tampouco ele virá diante dela com escudo ou edificará uma trincheira contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Ele vai sair pelo mesmo caminho por onde entrou; ele não entrará nesta cidade. Esta é a declaração de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Porque Eu defenderei esta cidade e a livrarei por Mim e por causa de Davi, Meu servo\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'E aconteceu que, naquela noite, o Anjo de Yahweh saiu e atacou o acampamento dos assírios, matando cento e oitenta e cinco mil soldados. Quando os homens se levantaram pela manhã, havia corpos espalhados por toda parte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Assim, Senaqueribe, rei da Assíria, deixou Israel e foi embora e ficou em Nínive.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Mais tarde, quando ele estava adorando na casa do seu deus, Nisroque, seus filhos Adrameleque e Sarezer o mataram ao fio da espada. Então, eles fugiram para a terra de Ararate. Depois disso, Esar-Hadom seu filho, tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'Naqueles dias, Ezequias ficou doente ao ponto de morrer. Assim, Isaías, filho de Amoz, o profeta, veio a ele e lhe disse: \"Yahweh diz: \'Põe tua casa em ordem; porque tu morrerás e não viverás\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Então, Ezequias virou sua face para a parede e orou a Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, '\"Por favor, Yahweh, lembra-Te de como eu andei fielmente diante de Ti, com todo o meu coração, e eu fiz o que era bom à Tua vista\". E Ezequias chorou alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Antes de Isaías ter saído do meio do pátio, a palavra de Yahweh veio a ele, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '\"Volta e diz a Ezequias, o líder do meu povo: \'Isto é o que Yahweh, o Deus de Davi, teu antepassado, diz: Ouvi tua oração e vi tuas lágrimas. Estou prestes a curar-te no terceiro dia, e tu subirás ao templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Acrescentarei quinze anos à tua vida, resgatarei a ti e a esta cidade da mão do rei da Assíria e defenderei esta cidade por Minha causa e por causa de Meu servo Davi\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Assim, Isaías disse: \"Tomai uma pasta de figos\". Eles fizeram assim e puseram-na em sua úlcera, e ele se recuperou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Ezequias disse a Isaías: \"Qual será o sinal de que Yahweh irá me curar e de que eu deva subir ao templo de Yahweh no terceiro dia?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Isaías replicou: \"Este será o sinal de Yahweh para ti, que Yahweh fará aquilo que tem dito. Deve a sombra avançar dez passos ou retroceder dez passos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Ezequias respondeu: \"É algo fácil para a sombra avançar dez passos. Não, que a sombra retroceda dez passos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Assim, Isaías, o profeta, clamou a Yahweh, e Ele retrocedeu a sombra em dez passos, do ponto em que ela se havia movido na escadaria de Acaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Naquele tempo, Meradoque-Baladã, filho de Baladã rei da Babilônia, enviou cartas e um presente a Ezequias, porque havia ouvido que Ezequias estava doente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Ezequias ouviu aquelas cartas e, então, mostrou aos mensageiros todo o palácio e suas coisas valiosas: a prata, o ouro, as finas especiarias, o óleo precioso, o depósito de suas armas e tudo que foi achado em seus tesouros. Não houve nada em sua casa nem em todo o seu reino que Ezequias não mostrasse a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Então, Isaías, o profeta, veio ao rei Ezequias e perguntou-lhe: \"O que esses homens disseram a ti? De onde eles vieram?\". Ezequias disse: \"Eles vieram do país distante da Babilônia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Isaías perguntou: \"O que eles viram em tua casa?\". Ezequias respondeu: \"Eles viram tudo em minha casa. Não há nada entre meus bens valiosos que eu não tenha mostrado a eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Assim, Isaías disse a Ezequias: \"Ouve a palavra de Yahweh:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, '\'Olha, os dias estão prestes a chegar em que tudo em teu palácio, as coisas que teus antepassados armazenaram até o presente dia, será carregado para a Babilônia. Nada será deixado, diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'E os filhos nascidos de ti, aqueles que tu criaste, serão levados, e eles se tornarão eunucos no palácio do rei da Babilônia\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Então, Ezequias disse a Isaías: \"Boa é a palavra de Yahweh que tu falaste\". Porque pensei: \"Haverá paz e segurança em meus dias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Quanto aos demais assuntos relacionados a Ezequias — todo o seu poder, e como ele construiu o reservatório de água e o túnel para abastecer a cidade com água —, não estão escritos no livro de Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Ezequias dormiu com seus antepassados, e Manassés, seu filho, tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manassés tinha doze anos quando começou a reinar. Ele reinou por cinquenta e cinco anos em Jerusalém. Sua mãe se chamava Hefzibá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Ele fez o que era mau à vista de Yahweh, como as coisas abomináveis das nações que Yahweh havia tirado diante do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Pois ele reconstruiu os lugares altos que Ezequias, seu pai, havia destruído, e ele construiu altares a Baal, fez um poste a Astarote, como o que Acabe, rei de Israel, havia feito, e ele se prostrou a todas as estrelas do céu e as adorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Manassés contruiu altares pagãos na casa de Yahweh, apesar do comando de Yahweh: \"Em Jerusalém, é onde Meu nome será para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Ele construiu altares para todas as estrelas do céu nos dois pátios do templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Ele ofereceu seu filho no fogo; ele praticou feitiçaria e encantamento, e se consultou com aqueles que falam com os mortos e aqueles que falam com os espíritos. Ele praticou muitos atos malignos diante de Yahweh, e ele provocou a ira de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'A imagem esculpida de Astarote que ele fez, ele a pôs no templo de Yahweh. Foi sobre esse templo que Yahweh havia dito a Davi e a Salomão, seu filho. Ele disse: \"Neste templo e em Jerusalém, a qual Eu escolhi de todas as tribos de Israel, que Eu colocarei Meu nome para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Não mais deixarei que os pés de Israel andem fora da terra que dei aos seus antepassados, caso eles obedeçam cuidadosamente tudo o que Eu os comandei, e sigam toda Lei que Meu servo Moisés ordenou a eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Mas as pessoas se recusaram a escutar, e Manassés os levou a fazer coisas bem piores, muito mais do que as nações que Yahweh havia destruído diante do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Assim, Yahweh falou por meio de Seus servos, os profetas, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, '\"Porque Manassés, rei de Judá, tem feito essas coisas abomináveis, e tendo agido perversamente, que todos os amorreus antes dele fizeram, e também havia feito Judá pecar com seus ídolos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'então, Yahweh, o Deus de Israel, diz: \'Vê, Eu estou para trazer tal mal sobre Jerusalém e Judá que qualquer que ouvir isto, ambos os ouvidos retinarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Eu estenderei sobre Jerusalém a corda de medidas usada contra Samaria, e a corda de prumo contra a casa de Acabe; Eu irei limpar Jerusalém, da mesma maneira que um homem lava a louça, lavando-a e virando-a de cabeça para baixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Eu lançarei fora o remanescente da Minha herança e os entregarei na mão de seus inimigos. Eles se tornarão vítimas e despojo para todos os seus inimigos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'porque eles fizeram o mal à Minha vista, e Me provocaram à ira, desde o dia em que seus ancestrais vieram do Egito, até o dia de hoje\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Além disso, Manassés derramou muito sangue inocente, até encher Jerusalém de morte de um extremo ao outro. Isto foi em adição ao pecado pelo qual ele fez Judá pecar, quando ela fez o que era mal à vista de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Quanto aos demais atos relacionados a Manassés, tudo que ele fez, e o pecado cometido, não estão escritos no livro de Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Manassés dormiu com seus antepassados e foi sepultado no jardim de sua própria casa, no jardim de Uzá. Amom seu filho tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Amom tinha vinte e dois anos quando começou a reinar; ele reinou por dois anos em Jerusalém. O nome de sua mãe era Mesulemete; ela era a filha de Haruz de Jobtá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Ele fez o que era mau à vista de Yahweh, da mesma maneira que Manassés, seu pai, fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Amom seguiu o caminho em que seu pai andou e adorou aos ídolos que seu pai adorou, e se prostrou a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Ele abandonou Yahweh, o Deus de seus pais, e não andou no caminho de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Os servos de Amom conspiraram contra ele e o mataram em sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Mas o povo da terra matou todos aqueles que conspiraram contra o rei Amom, e fizeram de Josias, seu filho, rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Quanto às demais situações relacionadas aos atos de Amom, os mesmos não estão escritos no livro de Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'O povo o sepultou na sua tumba no jardim de Uzá, e Josias seu filho se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josias tinha oito anos quando iniciou seu reinado; ele reinou por trinta e um anos em Jerusalém. O nome de sua mãe era Jedida (ela era filha de Adaías, de Bozcate).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Ele fez o que era correto aos olhos de Yahweh. Andou nos caminhos de Davi, seu antepassado, e não se desviou nem para a direita nem para a esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'E aconteceu que, no oitavo ano do reinado do rei Josias, ele enviou Safã filho de Azalias, filho de Mesulão, o escriba, ao templo de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '\"Sobe a Hilquias, o sumo sacerdote e dize-lhe para contar o dinheiro, que os guardas do templo recolheram do povo, por eles trazido ao templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Deixa que o dinheiro seja entregue nas mãos dos trabalhadores que estão encarregados do templo, para que eles façam reparos no templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'Que eles entreguem dinheiro aos carpinteiros, aos construtores e aos pedreiros e que comprem também madeira e pedras cortadas para reparar o templo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Porém não foi requerida a prestação de contas pelo dinheiro que lhes foi dado, pois eles agiam fielmente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Hilquias, o sumo sacerdote, disse a Safã, o escriba: \"Encontrei o Livro da Lei no templo de Yahweh\". Assim Hilquias entregou o livro a Safã, e ele o leu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Safã foi e levou o livro ao rei e também contou a ele, dizendo: \"Vossos servos já gastaram o dinheiro que se achava no templo, eles o entregaram na mão dos trabalhadores que supervisionam o cuidado do templo de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Então, Safã, o escriba disse ao rei: \"Hilquias, o sacerdote, deu-me um livro\". Então, Safã o leu para o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Aconteceu que, quando o rei ouviu as palavras da lei, rasgou suas vestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'O rei ordenou a Hilquias, o sacerdote, a Aicam, filho de Safã, a Acbor, filho de Micaías, a Safã, o escriba, e a Asaías, seu próprio servo, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '\"Ide e consultai Yahweh por mim, pelo povo e por toda Judá, por causa das palavras deste livro que foi encontrado. Pois grande é a ira de Yahweh que se acendeu contra nós, porque nossos ancestrais não escutaram as palavras deste livro, de modo a obedecer tudo o que foi escrito sobre nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Assim o sacerdote Hilquias, Aicam, Acbor, Safã e Asaías foram a Hulda, a profetisa, mulher de Salum, filho de Ticvá, filho de Harás, guardador das vestes (ela vivia em Jerusalém, no segundo quarteirão) e falaram com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Ela lhes disse: \"Isto é o que Yahweh, o Deus de Israel, diz: \'Diga ao homem que os enviou a Mim:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Assim diz Yahweh: Vede, Eu trarei desastre a este lugar e a seus habitantes, de acordo com tudo que está escrito neste livro que o rei de Judá leu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Pois eles Me abandonaram e queimaram incenso para outros deuses, de modo que provocaram a Minha ira diante de tudo o que cometeram; assim sendo, Minha ira se acendeu contra este lugar e não se extinguirá\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Mas para o rei de Judá, que os enviou para consultar a vontade de Yahweh, isso é o que a ele dirão: \'Yahweh, o Deus de Israel diz isso: Sobre as palavras que ouviste,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'porque o teu coração foi sensível e porque humilhaste a ti mesmo diante de Yahweh; quando ouviste o que falei contra este lugar e seus habitantes, que eles se tornariam em desolação e maldição, e porque rasgaste tuas vestes e choraste diante de Mim, Eu também te ouvi\' — essa é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Olha, Eu te recolherei para teus antepassados, e serás recolhido à tua sepultura em paz. Teus olhos não verão todo o desastre que Eu trarei a este lugar\'\". Assim os homens levaram essa mensagem de volta para o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Assim, o rei enviou mensageiros que reuniram até ele todos os anciãos de Judá e de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Então, o rei subiu ao templo de Yahweh e com ele todos os homens de Judá, todos os habitantes de Jerusalém, os sacerdotes, os profetas e todas as pessoas, do pequeno ao grande. Ele, então, leu aos ouvidos deles todas as palavras do Livro da Aliança, que havia sido encontrado no templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'O rei ficou ao lado da coluna e fez uma aliança perante Yahweh, de andar após Yahweh e guardar os Seus mandamentos, Seus regulamentos e Seus estatutos, com todo seu coração e toda a sua alma, para confirmar as palavras da aliança que foram escritas neste livro. Assim todo o povo concordou em apoiar a aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'O rei ordenou ao sumo sacerdote Hilquias, aos sacerdotes abaixo dele e aos porteiros a levarem para fora do templo de Yahweh todos os vasos que haviam sido feitos para Baal e Aserá e para todas as estrelas do céu. Ele os queimou fora de Jerusalém, nos campos de Cedrom, e carregou suas cinzas para Betel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Ele destituiu os sacerdotes idólatras que os reis de Judá haviam escolhido para queimar incenso nos lugares altos nas cidades de Judá e nos lugares ao redor de Jerusalém — aqueles que queimaram incensos para Baal, para o sol e a lua, para os planetas e para todas as estrelas do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Ele levou o poste de Aserá para fora do templo de Yahweh, para o Vale de Cedrom, fora de Jerusalém, e o queimou lá. Reduziu-o a pó e jogou o pó dentro dos túmulos do povo comum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Ele limpou as salas das prostitutas cultuais que estavam no templo de Yahweh, onde as mulheres teciam vestimentas para Aserá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Josias levou todos os sacerdotes para fora da cidade de Judá e profanou os lugares altos onde os sacerdotes haviam queimado incenso, desde Geba até Berseba. Destruiu os lugares altos que estavam na entrada da porta de Josué (o governador da cidade), que estava à esquerda da porta da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Apesar de os sacerdotes daqueles lugares altos não poderem servir no altar de Yahweh em Jerusalém, eles comiam pão sem fermento, no meio de seus irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Josias profanou Tofete, que estava no Vale do Ben Hinom, para que ninguém pudesse oferecer seu filho ou sua filha como holocausto a Moloque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Ele tirou os cavalos que os reis de Judá haviam dado ao sol. Eles estavam na área da entrada do templo de Yahweh, próxima à sala de Natã-Meleque, o camareiro. Josias queimou as carruagens do sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'O rei Josias destruiu os altares que estavam no terraço na parte superior de Acaz, que os reis de Judá haviam feito, e os altares que Manassés havia feito nos dois pátios do templo de Yahweh. Josias esmagou-os em pedaços e jogou-os no Vale de Cedrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'O rei profanou os lugares altos que estavam ao leste de Jerusalém, ao sul do monte da Destruição, que Salomão, o rei de Israel, havia construído para Astarote, o repugnante ídolo dos sidônios; para Camos, o repugnante ídolo de Moabe; e para Milcom, o repugnante ídolo dos amonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'O rei Josias quebrou em pedaços os pilares de pedra, cortou os postes de Aserá e preencheu o lugar com ossos humanos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Josias também destruiu completamente o altar que estava em Betel e os lugares altos que Jeroboão, filho de Nebate (aquele que fez Israel pecar), havia construído. Ele queimou o altar e o lugar alto e os reduziu a pó. Ele também queimou o poste de Aserá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Enquanto Josias olhava ao redor, notou os túmulos que estavam ao lado do monte. Ele enviou homens para pegarem os ossos dos túmulos; depois os queimou no altar, e, assim, o profanou. Isso ocorreu de acordo com a palavra de Yahweh que o homem de Deus havia falado, o homem que falara dessas coisas anteriormente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Depois ele disse: \"O que é aquele monumento que vejo?\". Os homens da cidade disseram-lhe: \"Aquele é o túmulo do homem de Deus que veio de Judá e falou sobre essas coisas que acabaste de fazer contra o altar de Betel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Assim Josias disse: \"Deixai-o estar. Ninguém deve mover os ossos dele\". Assim deixaram os ossos como estavam, juntamente com os ossos do profeta que havia vindo de Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Então, Josias removeu todas as casas dos lugares altos que estavam na cidade de Samaria, as quais os reis de Israel haviam feito, e que haviam provocado Yahweh à ira. Ele lhes fez exatamente o mesmo que havia feito em Betel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Matou todos os sacerdotes dos lugares altos, nos altares, e queimou ossos humanos neles. Depois ele retornou a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Então, o rei ordenou a todas as pessoas, dizendo: \"Mantende a Páscoa para Yahweh, vosso Deus, como está escrito neste Livro da Aliança\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Tal celebração de Páscoa nunca havia sido realizada desde os dias dos juízes que governaram Israel, nem em todos os dias dos reis de Israel ou Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Mas, no décimo oitavo ano do rei Josias, essa Páscoa de Yahweh foi celebrada em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Josias também baniu aqueles que falavam com os mortos ou com os espíritos. Ele também proibiu os feiticeiros, os ídolos e todas as coisas repugnantes que foram vistas na terra de Judá e em Jerusalém, para confirmar as palavras da lei que foram escritas no livro que o sacerdote Hilquias havia achado no templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Antes de Josias, não houve nenhum rei como ele, que se voltou para Yahweh com todo o seu coração, toda a sua alma e toda a sua força, que seguiu toda a lei de Moisés. E nunca mais houve um rei como ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'No entanto, Yahweh não Se desfez da ferocidade de Sua ira, que havia sido acendida contra Judá por toda a adoração pagã com que Manassés O havia provocado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Então, Yahweh disse: \"Eu removerei Judá de diante da minha vista, assim como removi Israel, e rejeitarei Jerusalém, a cidade que escolhi, e o templo sobre a qual Eu havia dito: \'Meu nome estará lá\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Quanto aos outros assuntos relativos a Josias, todas as coisas que ele fez, não estão escritas no livro de Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Em seus dias, Faraó Neco, rei do Egito, lutou contra o rei da Assíria no rio Eufrates. O rei Josias encontrou Neco em batalha, e Neco o matou em Megido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Os servos de Josias o carregaram morto em uma carruagem desde Megido, trouxeram-lhe para Jerusalém e sepultaram-no em seu próprio túmulo. Então, o povo da terra tomou Jeocaz, filho de Josias, ungiram-no, e o fizeram rei no lugar de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Joacaz tinha vinte e três anos quando começou a reinar e reinou três meses em Jerusalém. O nome de sua mãe era Hamutal; ela era filha de Jeremias de Libna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Joacaz fez o que era mau à vista de Yahweh, como todas as coisas que seus antepassados haviam feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Faraó Neco o colocou na prisão em Ribla, na terra de Hamate, para que ele não pudesse reinar em Jerusalém. Então, Neco multou Judá com cem talentos de prata e um talento de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Faraó Neco fez Eliaquim, filho de Josias, rei no lugar de Josias seu pai, e mudou seu nome para Jeoaquim. Porém ele levou Joacaz para o Egito, e Joacaz morreu ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Jeoaquim pagou a prata e o ouro para o Faraó. A fim de obedecer às ordens do Faraó, ele estabeleceu impostos sobre a terra e forçou cada homem entre o povo da terra a pagar a prata e o ouro, de acordo com os impostos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Jeoaquim tinha vinte e cinco anos de idade quando começou a reinar e reinou por onze anos em Jerusalém. O nome de sua mãe era Zebida; ela era filha de Pedaías de Ruma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Jeoaquim fez o que era mau aos olhos de Yahweh, como todos os seus antepassados haviam feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Nos dias de Jeoaquim, Nabucodonosor, rei da Babilônia, atacou Judá, levando Jeoaquim a se sujeitar a ele por três anos. Então, Jeoaquim voltou para trás e se rebelou contra Nabucodonosor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Yahweh enviou contra Jeoaquim tropas dos babilônios, dos sírios, dos moabitas e dos amonitas; Ele os enviou contra Judá para a sua destruição. Foi em conformidade com a palavra de Yahweh, falada por intermédio de seus servos, os profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Certamente, foi a comando de Yahweh que isto ocorreu a Judá, para removê-lo da Sua vista, por causa dos pecados de Manassés, e tudo que ele fez,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'e também pelo sangue inocente que derramou, pois encheu Jerusalém com sangue inocente. Yahweh não estava disposto a perdoar isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Com relação aos demais acontecimentos do reinado de Jeoaquim e seus feitos, não estão eles escritos no livro de Crônicas dos reis de Judá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Jeoaquim dormiu com seus antepassados, e Joaquim, seu filho, se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'O rei do Egito não mais atacou fora de suas terras, pois o rei da Babilônia havia conquistado todas as terras que estavam sob o controle do rei do Egito, desde o ribeiro do Egito até o rio Eufrates.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Joaquim tinha dezoito anos quando começou a reinar; reinou em Jerusalém por três meses. Sua mãe se chamava Neusta; e era filha de Elnatã, de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Ele fez o que era mau à vista de Yahweh, fazendo tudo que seu pai havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Naquele tempo, o exército de Nabucodonosor, rei da Babilônia, atacou Jerusalém e sitiou a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Nabucodonosor, rei da Babilônia, foi à cidade enquanto seus soldados a estavam sitiando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Joaquim, rei de Judá, entregou-se ao rei da Babilônia, juntamente com sua mãe, seus servos, seus príncipes e seus oficiais. No oitavo ano de seu reinado, o rei da Babilônia o capturou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Nabucodonosor saqueou todos os itens valiosos do templo de Yahweh, e do palácio do rei. Ele tornou em pedaços todos os objetos de ouro que Salomão, rei de Israel, havia colocado no templo de Yahweh, assim como Yahweh havia dito que aconteceria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Ele levou para o exílio toda Jerusalém, todos os líderes, todos os soldados, dez mil cativos, e todos os artesãos e ferreiros. Ninguém ficou, com excessão dos pobres daquela terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Nabucodonosor levou Joaquim cativo para a Babilônia, assim como a mãe do rei, suas esposas, oficiais e os poderosos da terra. Ele os levou para o exílio de Jerusalém para a Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Todos os soldados, sete mil deles, e mil artesãos e ferreiros, todos aptos para guerrear, o rei da Babilônia os levou para o exílio na Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'O rei da Babilônia instituiu Matanias, tio paterno de Joaquim, rei em seu lugar, e mudou seu nome para Zedequias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Zedequias tinha vinte e um anos quando começou a reinar; e reinou por onze anos em Jerusalém. Sua mãe se chamava Hamutal, ela era a filha de Jeremias, da Libna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Ele fez o que era mau à vista de Yahweh, fazendo tudo o que Jeoaquim havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Por causa da ira de Yahweh, todos esses eventos ocorreram em Jerusalém e Judá, até que Ele os expulsou da sua presença. Então, Zedequias se rebelou contra o rei da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'No nono ano do reinado do rei Zedequias, no décimo mês, no décimo dia do mês, Nabucodonosor, rei da Babilônia, veio com todo seu exército contra Jerusalém. Ele acampou em frente, e construíram um muro sitiando-os ao redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Assim, a cidade ficou sitiada até o décimo primeiro ano do reinado do rei Zedequias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'No nono dia do quarto mês daquele ano, a fome era tão severa na cidade que não havia comida para o povo da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Então, a cidade foi invadida, e todos os homens de guerra fugiram de noite pelo caminho do portão entre dois muros no jardim do rei, embora os babilônios estivessem ao redor da cidade. O rei foi em direção a Arabá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Mas o exército dos babilônios perseguiu o rei Zedequias e o alcançou nas planícies do rio Jordão, no vale próximo a Jericó. Todo seu exército estava disperso do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Eles capturaram o rei e o conduziram para o rei da Babilônia em Ribla, onde ele foi sentenciado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Quanto aos filhos de Zedequias, eles os massacraram diante de seus olhos. Então, arrancaram seus olhos, prenderam-no com correntes de bronze e o levaram para Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'No sétimo dia do quinto mês, que era o décimo nono ano do reinado de Nabucodonosor, rei da Babilônia, Nebuzaradã, um servo do rei da Babilônia e comandante de sua guarda, chegou em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Ele queimou o templo de Yahweh, o palácio real e todas as casas de Jerusalém; também ele queimou cada construção importante na cidade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'e todas as paredes em volta de Jerusalém foram destruídas pelo exército da Babilônia, que estava sob a autoridade do comandande da guarda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Quanto ao resto das pessoas que foram deixadas na cidade e aqueles que tinham se rendido ao rei da Babilônia, e o resto da população, Nebuzaradã, comandante da guarda, os levou para o exílio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Mas o comandante da guarda deixou alguns dos mais pobres da terra para trabalharem nos vinhedos e nos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Quanto aos pilares de bronze que estavam no templo de Yahweh, os suportes e o tanque de bronze que estavam no templo de Yaweh, os babilônios os quebraram em partes e levaram o bronze para Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Vasos, pás, apagadores, vasilhas e todos os utensílios de bronze com que cada sacerdote havia servido no templo, os babilônios levaram todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Os potes para remoção de cinzas e as bacias que eram feitas de ouro, e tudo o que era feito de prata, o comandante da guarda do rei também levou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Os dois pilares, o tanque de bronze e os suportes que Salomão havia feito para o templo de Yahweh continham mais bronze do que podia ser pesado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'A altura do primeiro pilar era de dezoito côvados, e havia um capitel de bronze sobre ele. O capitel tinha três côvados de altura, com treliças e romãs ao seu redor, tudo feito de bronze. O outro pilar e sua treliça era como o do primeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'O comandante da guarda levou Seraías, o sumo sacerdote, junto com Sofonias, o segundo sacerdote, e os três guardas do portão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Da cidade, ele levou um oficial que estava no comando dos soldados como prisioneiro, e cinco dos homens que aconselhavam o rei que ainda estavam na cidade. Ele também levou o oficial responsável por selecionar homens para o exército como prisioneiro, juntamente com sessenta homens importantes da terra que ainda estavam na cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Então, Nebuzaradã, comandante da guarda, os pegou e os levou ao rei da Babilônia em Ribla.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'O rei da Babilônia os matou em Ribla, na terra de Hamate. Desta forma, Judá foi levado em exílio para fora da sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Quanto ao povo que permaneceu na terra de Judá, os que Nabucodonozor, rei da Babilônia, havia deixado, ele colocou Gedalias, filho de Aicam, filho de Safã, encarregado por eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Ora, quando todos os comandantes de soldados, eles e seus homens, ouviram que o rei da Babilônia havia feito de Gedalias governador, eles foram até Gedalias em Mispá. Esses homens eram Ismael, filho de Netanias, Joanã, filho de Careá, Seraías, filho de Tanumete, o netofatita, e Jazanias, filho do maacatita, eles e seus homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Gedalias fez um juramento a eles e seus homens, e lhes disse: \"Não tenhais medo dos oficiais babilônios. Vivei na terra e servi ao rei da Babilônia, e tudo irá bem convosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Mas, isso aconteceu no sétimo mês, Ismael, filho de Netanias, filho de Elisama, da família real, veio com dez homens e atacou Gedalias. Gedalias morreu, assim como os homens de Judá e os babilônios que estavam com ele em Mispá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Então, todo o povo, desde o menor até o maior, e os comandantes de soldados, levantaram e foram para o Egito, porque eles estavam com medo dos babilônios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Isto aconteceu depois, no trigésimo sétimo ano do exílio de Joaquim, rei de Judá, no décimo segundo mês, no vigésimo sétimo dia do mês; Evil-Merodaque, rei da Babilônia libertou Joaquim, rei de Judá, da prisão. Isto aconteceu no ano em que Evil-Merodaque começou a reinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Ele falou gentilmente com ele e lhe deu um lugar mais honrado que o dos outros reis que estavam com ele na Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Evil-Merodaque retirou as roupas de prisioneiro de Joaquim, e Joaquim comeu regularmente na mesa do rei pelo resto de sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'E, regularmente, ele recebia alimentos e uma pensão era dada a ele todos os dias, pelo resto de sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adão, Sete, Enos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Quenã, Maalalel, Jarede,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Enoque, Matusalém, Lameque,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noé, Sem, Cam e Jafé..');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Os filhos de Jafé foram Gomer, Magogue, Madai, Javã, Tubal, Meseque e Tiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Os filhos de Gomer foram Asquenaz, Rifate e Togarma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Os filhos de Javã foram Elisá, Társis, Quitim e Dodanim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Os filhos de Cam foram Cuxe, Mizraim, Pute e Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Os filhos de Cuxe foram Seba, Havilá, Sabtá, Raamá e Sabtecá. Os filhos de Raamá foram Sebá e Dedã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Cuxe gerou Ninrode, que foi o primeiro poderoso na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Mizraim gerou os luditas, os anamitas, os leabitas, os naftuítas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'os patrusitas, os casluítas (dos quais vieram os filisteus) e os caftoritas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Canaã gerou Sidom, seu primogênito, e Hete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'Ele também gerou os jebuseus, os amorreus, os girgaseus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'os heveus, os arqueus, os sineus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'os arvadeus, os zemareus e os hamateus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Os filhos de Sem foram Elão, Assur, Arfaxade, Lude, Arã, Uz, Hul, Geter e Meseque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arfaxade gerou Selá, e Selá gerou Héber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Héber teve dois filhos; o nome de um era Pelegue, porque em seus dias a Terra foi dividida, e o nome de seu irmão era Joctã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Joctã gerou Almodá, Salefe, Hazarmavé, Jerá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadorão, Uzal, Dicla,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebal, Abimael, Sebá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ofir, Havilá e Jobabe. Todos esses eram filhos de Joctã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arfaxade, Selá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Héber, Pelegue, Reú,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serugue, Naor, Terá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abrão, que é Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Os filhos de Abraão foram Isaque e Ismael.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Esses são os seus filhos: o primogênito de Ismael era Nebaiote, depois Quedar, Adbeel, Mibsão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma, Dumá, Massá, Hadade, Tema,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Nafis e Quedemá. Esses foram os filhos de Ismael.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Os filhos de Quetura, concubina de Abraão, foram Zinrã, Jocsã, Medã, Midiã, Isbaque e Suá. Os filhos de Jocsã foram Sabá e Dedã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Os filhos de Midiã foram Efá, Efer, Enoque, Abida e Elda. Todos esses foram descendentes de Quetura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Abraão gerou Isaque. Os filhos de Isaque foram Esaú e Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Os filhos de Esaú foram Elifaz, Reuel, Jeús, Jalão e Corá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Os filhos de Elifaz foram Temã, Omar, Zefi, Gatã, Quenaz, Timna e Amaleque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Os filhos de Reuel foram Naate, Zerá, Samá e Mizá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Os filhos de Seir foram Lotã, Sobal, Zibeão, Anás, Disom, Eser e Disã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Os filhos de Lotã foram Hori e Homã, e Timna era irmã de Lotã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Os filhos de Sobal foram Aliã, Manaate, Ebal, Sefi e Onã. Os filhos de Zibeão foram Aías e Anás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'O filho de Anás foi Disom. Os filhos de Disom foram Hanrão, Esbã, Itrã e Querã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Os filhos de Eser foram Bilã, Zaavã e Jaacã. Os filhos de Disã foram Uz e Arã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Estes foram os reis que reinaram na terra de Edom, antes de qualquer rei ter reinado sobre os israelitas: Belá, filho de Beor; o nome de sua cidade era Dinabá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Quando Belá morreu, então, Jobabe, filho de Zerá, de Bozra, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Quando Jobabe morreu, Husão, da terra dos temanitas, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Quando Husão morreu, Hadade, filho de Bedade, que derrotou os midianitas na terra de Moabe, reinou em seu lugar. O nome de sua cidade era Avite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Quando Hadade morreu, então, Sâmela, de Masreca, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Quando Sâmela morreu, então, Saul, de Reobote, que vivia junto ao rio, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Quando Saul morreu, então, Baal-Hanã, filho de Acbor, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Quando Baal-Hanã, filho de Acbor, morreu, então, Hadade reinou em seu lugar. O nome de sua cidade era Paú. O nome de sua mulher era Meetabel, a filha de Matrede, a neta de Mezaabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Hadade morreu. Os chefes do clã em Edom eram Timna, Aliá, Jetete,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Aolíbama, Elá, Pinom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Quenaz, Temã, Mibzar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Magdiel e Irão. Esses eram os chefes dos clãs em Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Estes foram os filhos de Israel: Rúben, Simeão, Levi, Judá, Issacar, Zebulom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dã, José, Benjamim, Naftali, Gade e Aser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Os filhos de Judá foram Er, Onã e Selá, gerados com a filha de Suá, o cananeu. Er, o primogênito de Judá, era mau aos olhos de Yahweh, e Yahweh o matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Tamar, nora de Judá, gerou Perez e Zerá. Judá teve cinco filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Os filhos de Perez foram Hezrom e Hamul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Os filhos de Zerá foram Zinri, Etã, Hemã, Calcol e Dara, cinco ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'O filho de Carmi foi Acar, que trouxe desgraça sobre Israel quando roubou o que era dedicado a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'O filho de Etã foi Azarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Os filhos de Hezrom foram Jerameel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Rão e Quelubai. Rão foi pai de Aminadabe, e Aminadabe, de Nasom, um líder dentre os descendentes de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nasom foi pai de Salma, e Salma, de Boaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Boaz foi pai de Obede, e Obede, de Jessé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Jessé foi pai de Eliabe, seu primogênito; Abinadabe foi seu segundo filho; Simeia, o terceiro;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Netanel, o quarto; Radai, o quinto;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Ozen, o sexto; e Davi, o sétimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'As irmãs deles eram Zeruia e Abigail. Os três filhos de Zeruia foram Abisai, Joabe e Asael.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Abigail gerou Amasa, cujo pai era Jéter, o ismaelita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Calebe, filho de Hezrom, teve filhos com Azuba, sua mulher, e com Jeriote; seus filhos foram Jeser, Sobabe e Ardom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Azuba morreu e, então, Calebe casou-se com Efrata, que gerou Hur.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Hur foi pai de Uri, e Uri foi pai de Bezalel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Mais tarde, Hezrom, quando tinha sessenta anos de idade, casou-se com a filha de Maquir, pai de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Ela gerou Segube, que foi pai de Jair, que liderou vinte e três cidades na terra de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Gesur e Arã tomaram as cidades de Jair e Quenate, assim como também os sessenta povoados ao redor. Todos esses habitantes eram descendentes de Maquir, pai de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Após a morte de Hezrom, em Calebe Efrata, Abia, esposa de Hezrom, gerou Asur, que foi pai de Tecoa..');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Os filhos de Jerameel, o primogênito de Hezrom, foram: Rão, seu primogênito, Buna, Orém, Ozém e Aías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Jerameel teve outra esposa, cujo nome era Atara. Ela foi mãe de Onã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Os filhos de Rão, o primogênito de Jerameel, foram Maaz, Jamim e Equer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Os filhos de Onã foram Samai e Jada. Os filhos de Samai foram Nadabe e Abisur.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'A mulher de Abisur se chamava Abiail; ela gerou Abã e Molide.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Os filhos de Nadabe foram Selede e Apaim; Selede morreu sem filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'O filho de Apaim foi Isi. O filho de Isi foi Sesã. O filho de Sesã foi Alai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Os filhos de Jada, irmão de Samai, foram Jéter e Jônatas. Jéter morreu sem filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Os filhos de Jônatas foram Pelete e Zaza. Estes foram os descendentes de Jerameel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Sesã não teve filhos, apenas filhas. Sesã teve um servo egípcio, cujo nome era Jará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Sesã deu sua filha por mulher a Jará, seu servo; ela lhe gerou Atai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Atai foi pai de Natã, e Natã de Zabade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Zadabe foi pai de Eflal, e Eflal de Obede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obede foi pai de Jeú, e Jeú de Azarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Azarias foi pai de Helez, e Helez, de Eleasá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Eleasá foi pai de Sismai, e Sismai, de Salum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Salum foi pai de Jecamias, e Jecamias, de Elisama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Os filhos de Calebe, irmão de Jerameel, foram Messa, seu primogênito, que foi pai de Zife, e Maressa, seu segundo filho, que foi o pai de Hebrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Os filhos de Hebrom foram Corá, Tapua, Requém e Sema.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Sema gerou Raão, pai de Jorqueão. Requém gerou Samai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'O filho de Samai foi Maom, e Maom foi pai de Bete-Zur.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Efá, concubina de Calebe, gerou Harã, Moza e Gazez. Harã foi pai de Gazez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Os filhos de Jadai foram Regém, Jotão, Gesã, Pelete, Efá e Saafe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maacá, concubina de Calebe, gerou Seber e Tiraná.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Ela também gerou Saafe, pai de Madmana, Seva, pai de Macbena e de Gibeá. A filha de Calebe foi Acsa. Esses foram os descendentes de Calebe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Os filhos de Hur foram estes: seu primogênito Efrata, Sobal, pai de Quiriate-Jearim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, pai de Belém, e Harefe, pai de Bete-Gader.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Sobal, pai de Quiriate-Jearim, teve descendentes: Haroé, metade dos manaatitas');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'e os clãs de Quiriate-Jearim: os itritas, os fateus, os sumateus e os misraeus. Os zoratitas e os estaoleus descenderam destes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Os clãs de Salma foram os habitantes de Belém, os netofatitas, Atarote-Bete-Joabe, metade dos manaatitas, os zoritas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'os clãs dos escribas que viviam em Jabes: os tiratitas, os simeatitas e os sucatitas. Esses foram os queneus, que descenderam de Hamate, o antecessor de Recabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Estes são os filhos de Davi que nasceram em Hebrom: o primôgenito foi Amnom, de Ainoã de Jezreel; o segundo, Daniel, de Abigail de Carmel;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'o terceiro foi Absalão, cuja mãe era Maacá, filha de Talmai, rei de Gesur; o quarto foi Adonias, filho de Hagite;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'o quinto, Sefatias, de Abital; o sexto, Itreão, de sua esposa Eglá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Esses seis nasceram para Davi em Hebrom, onde ele reinou por sete anos e seis meses. Ele, então, reinou por trinta e três anos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Estes quatro filhos, de Bate-Seba, filha de Amiel, nasceram em Jerusalém: Simeia, Sobabe, Natã e Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Os outros nove filhos de Davi eram Ibar, Elisua, Elpalete,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nogá, Nefegue, Jafia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eliadá e Elifelete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Esses foram os filhos de Davi, sem incluir os filhos de suas concubinas. Tamar era irmã deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'O filho de Salomão foi Roboão. O filho de Roboão foi Abias. O filho de Abias foi Asa. O filho de Asa foi Josafá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'O filho de Josafá foi Jorão. O filho de Jorão foi Acazias. O filho de Acazias foi Joás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'O filho de Joás foi Amazias. O filho de Amazias foi Azarias. O filho de Azarias foi Jotão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'O filho de Jotão foi Acaz. O filho de Acaz foi Ezequias. O filho de Ezequias foi Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'O filho de Manassés foi Amom. O filho de Amom foi Josias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'O filho primôgenito de Josias foi Joanã; seu segundo filho, Jeoaquim; seu terceiro filho, Zedequias; e seu quarto filho, Salum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'O filho de Jeoaquim foi Jeconias. O último rei foi Zedequias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Os filhos de Jeconias, o cativo, foram Sealtiel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malquirão, Pedaías, Senazar, Jecamias, Hosama e Nedabias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Os filhos de Pedaías foram Zorobabel e Simei. Os filhos de Zorobabel foram Mesulão, Hananias e Selomite, irmã deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Seus outros cinco filhos foram Hasubá, Oel, Berequias, Hasadias e Jusabe-Hesede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Os filhos de Hananias foram Pelatias e Jesaías; e os filhos Refaías, os filhos de Arnã, os filhos de Obadias, os filhos de Secanias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'O filho de Secanias foi Semaías. Os filhos de Semaías foram Hatus, Igal, Bariá, Nearias e Safate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Os três filhos de Nearias foram Elioenai, Ezequias e Azricão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Os sete filhos de Elioenai foram Hodavias, Eliasibe, Pelaías, Acube, Joanã, Delaías e Anani.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Os descendentes de Judá foram Perez, Hezron, Carmi, Hur e Sobal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Sobal foi o pai de Reaías. Reaías foi o pai de Jaate. Jaate foi o pai de Aumai e Laade. Esses foram os antepassados que originaram os clãs dos zoratitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Estes foram os antepassados que originaram os clãs na cidade de Etã: Jezreel, Ismá e Idbás; e o nome da irmã deles, Hazelelponi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Penuel foi o antepassado que originou os clãs na cidade de Gedor. Ezer foi o que originou os clãs na cidade de Husa. Esses foram os descendentes de Hur, o primogênito de Efrata, que deu origem a Belém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Asur, o pai de Tecoa, teve duas esposas, Hela e Naara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Naara gerou Auzão, Héfer, Temeni e Haastari; esses foram os filhos de Naara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Os filhos de Hela foram Zerete, Izar, Etnaã');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'e Koz, que foi o pai de Anube, de Zobeba e dos clãs que descenderam de Acarel, filho de Harum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Jabez foi mais respeitado que seus irmãos. Sua mãe o chamou Jabez. Ela disse: \"Porque eu o gerei em dores\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Jabez clamou ao Deus de Israel e disse: \"Que Tu tão somente me abençoes, amplies meu território e que a Tua mão esteja comigo; assim, não serei afligido pelo mal e não terei que suportar a dor!\". Então, Deus atendeu a sua oração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Quelube, irmão de Suá, gerou Meir, que foi o pai de Estom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Estom gerou Bete-Rafa, Paseia e Teína, que iniciou a cidade de Ir-Naás. Esses foram os homens que viveram em Reca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Os filhos de Quenaz foram Otoniel e Seraías. Os filhos de Otoniel foram Hatate e Meonotai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Meonotai gerou Ofra e Seraías, que gerou Joabe, que originou Ge-Harasim, cujo povo era artesão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Os filhos de Calebe, filho de Jefoné, foram Iru, Elá e Naã. O filho de Elá foi Quenaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Os filhos de Jealelel foram Zife, Zifá, Tiria e Asareel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Os filhos de Ezra foram Jéter, Merede, Éfer e Jalon. A esposa egípcia de Merede gerou Miriã, Samai e Isbá, que se tornou pai de Estemoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Esses foram os filhos de Bitia, filha de Faraó, com quem Merede se casou. A esposa judia de Merede gerou Jerede, que foi pai de Gedor; Héber, que foi pai de Socó; e Jecutiel, que foi pai de Zanoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Dos dois filhos da esposa de Hodias, irmã de Naã, um gerou Queila, o garmita; o outro, Estemoa, o maacatita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Os filhos de Simão foram Amnom, Rina, Bene-Hanã e Tilom. Os filhos de Isi foram Zoete e Bene-Zoete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Os descendentes de Selá, filho de Judá, foram Er, pai de Leca, Lada, pai de Maressa, e os clãs dos que fabricavam tecidos em Bete-Asbeia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Joquim, os homens de Cozeba, Joás e Sarafe, que tinham propriedades em Moabe, mas retornaram a Belém. Essa informação é dos registros antigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Alguns desses povos foram oleiros que viveram em Netaim e Gedera e trabalharam para o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Os descendentes de Simeão foram Nemuel, Jamim, Jaribe, Zerá e Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Salum era filho de Saul; Mibsão era filho de Salum; e Misma era filho de Mibsão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Os descendentes de Misma foram seu filho, Hamuel; seu neto, Zacur; e seu bisneto, Simei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Simei teve dezesseis filhos e seis filhas. Os irmãos dele não tiveram mais filhos; por isso, seus clãs não cresceram em número como o povo de Judá cresceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Eles viveram em Berseba, Molada e Hazar-Sual.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'Eles também habitaram em Bila, Ezem, Tolade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'Betuel, Hormá, Ziclague,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'Bete-Marcabote, Hazar-Susim, Bete-Biri e Saraim; essas foram suas cidades até o reino de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Suas cinco aldeias foram Etã, Aim, Rimom, Toquem e Asã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'junto com os vilarejos isolados, distantes como Baal. Esses eram os lugares em que moraram e onde registraram suas genealogias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Os líderes do clã foram Mesobabe, Janleque, Josa, filho de Amazias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joel, Jeú, filho de Josibias, filho de Seraías, filho de Asiel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Elioenai, Jaacobá, Jesoaías, Asaías, Adiel, Jesimiel, Benaia');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'e Ziza, filho de Sifi, filho de Alom, filho de Jedaías filho de Sinri, filho de Semaías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Esses foram os nomes dos líderes dos clãs, e seus clãs foram numerosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Eles foram até o vale no lado leste, próximo a Gedor, para procurar pastagens para seus rebanhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'e encontraram boas e abundantes pastagens. A terra era ampla, tranquila e pacífica. Antigamente, os descendentes de Cam, viviam nesse lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Essa é somente uma lista por nome dos que, nos dias do rei Ezequias, rei de Judá, vieram e atacaram os acampamentos dos descendentes de Cam e de Meun, que também estavam naquele lugar. Eles os destruíram totalmente e permaneceram ali por causa das pastagens para seus rebanhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Quinhentos homens da tribo de Simeão foram ao monte Seir, com seus líderes Pelatias, Nearias, Refaías e Uziel, filhos de Isi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Eles derrotaram os remanescentes dos amalequitas e têm vivido ali até os dias atuais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'No caso dos filhos de Rúben, o primogênito de Israel — embora Rúben fosse o primogênito de Israel, seus direitos de primogenitura foram dados aos filhos de José, filho de Israel, pois Rúben havia contaminado a cama de seu pai. Então, ele não é registrado como sendo o filho mais velho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Judá era o mais forte de seus irmãos, e dele viria o líder, mas os direitos de primogenitura foram dados a José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Os filhos de Rúben, o primogênito de Israel, foram Hanoque, Palu, Hezrom e Carmi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Os descendentes de Joel foram estes: o filho de Joel foi Semaías. O filho de Semaías foi Gogue. O filho de Gogue foi Simei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'O filho de Simei foi Mica. O filho de Mica foi Reaías. O filho de Reaías foi Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'O filho de Baal foi Beera, a quem Tiglate-Pileser, rei da Assíria, levou para o exílio. Beera foi um líder na tribo de Rúben.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Os parentes de Beera, por seus clãs, são os seguintes, listados nos seus registros genealógicos: Jeiel, o mais velho, Zacarias, e');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Belá, filho de Azaz, filho de Sema, filho de Joel. Eles viveram em Aroer, tão longe quanto Nebo e Baal-Meom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'e, no lado leste, até o início do deserto, que se estende até o rio Eufrates. Isso porque eles possuíam muito gado na terra de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Nos dias de Saul, a tribo de Rúben atacou os hagarenos, e os derrotou. Eles viveram nas tendas dos hagarenos ao longo de toda a terra leste de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Os membros da tribo de Gade viveram perto deles, na terra de Basã, até Salca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Seus líderes eram Joel, cabeça de um clã, Safã, cabeça de outro clã, e Janai, e Safate, em Basã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Seus parentes, pelas famílias de seus pais, foram Micael, Mesulão, Sebá, Jorai, Jacã, Ziá e Héber, sete ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Essas pessoas nomeadas acima foram os descendentes de Abihail, e Abihail foi o filho de Huri. Huri foi o filho de Jaroá. Jaroá foi o filho de Gileade. Gileade foi o filho de Micael. Micael foi o filho de Jesisai. Jesisai foi filho de Jado. Jado foi o filho de Buz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Aí, filho de Abdiel, filho de Guni, foi cabeça da família de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Eles viveram em Gileade, em Basã e suas terras, e em todas as pastagens de Sarom, até suas fronteiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Todos esses foram listados pelos registros genealógicos dos dias de Jotão, rei de Judá, e de Jeroboão, rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Os rubenitas, os gaditas, e a meia tribo de Manassés, tinham quarenta e quatro mil soldados treinados para a guerra, que carregavam escudos e espadas, e sacavam o arco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Eles atacaram os hagarenos, Jetur, Nafis e Nodabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Eles receberam ajuda divina contra seus inimigos. Nesse caminho, os hagarenos e todos que estavam com eles foram derrotados; isso porque os israelitas clamaram a Deus na batalha, e Ele os respondeu, porque colocaram sua confiança Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Eles capturaram seus animais, incluindo cinquenta mil camelos, duzentas e cinquenta mil ovelhas, dois mil burros e cem mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Porque Deus lutou por eles, eles mataram muitos inimigos, e viveram na terra deles até o cativeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'A meia tribo de Manassés viveu na terra de Basã, até Baal-Hermom, Senir e o monte Hermom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Estes foram os líderes de suas famílias: Éfer, Isi, Eliel, Azriel, Jeremias, Hodavias e Jadiel. Eles eram homens fortes e corajosos, homens famosos, líderes de suas famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Mas eles não foram fiéis ao Deus de seus ancestrais. Ao invés disso, adoraram os deuses do povo da terra, a quem Deus havia destruído diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'O Deus de Israel agitou o espírito de Pul, rei da Assíria, também chamado Tiglate-Pileser, rei da Assíria. Ele levou ao exílio os rubenitas, gaditas e a meia tribo de Manassés. Ele os levou a Hala, Habor, Hara e para o rio de Gozã, onde permanecem até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Os filhos de Levi foram Gérson, Coate e Merari.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Os filhos de Coate foram Anrão, Izar, Hebrom e Uziel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Os filhos de Anrão foram Arão, Moisés e Miriã; e os filhos de Arão foram Nadabe, Abiú, Eleazar e Itamar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazar gerou Fineias, e Fineias, Abisua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abisua gerou Buqui, e Buqui, Uzi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Uzi gerou Zeraías, e Zeraías, Meraiote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Meraiote gerou Amarias, e Amarias, Aitube.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Aitube gerou Zadoque, e Zadoque, Aimaaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Aimaaz gerou Azarias, e Azarias, Joanã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Joanã gerou Azarias, que serviu no templo que Salomão construiu em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Azarias gerou Amarias, e Amarias, Aitube.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Aitube gerou Zadoque, e Zadoque, Salum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Salum gerou Hilquias, e Hilquias, Azarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Azarias gerou Seraías, e Seraías, Jeozadaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Jeozadaque foi levado cativo quando Yahweh exilou Judá e Jerusalém pela mão de Nabucodonosor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Os filhos de Levi foram Gérson, Coate e Merari.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Os filhos de Gérson foram Libni e Simei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Os filhos de Coate foram Anrão, Izar, Hebrom e Uziel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Os filhos de Merari foram Mali e Musi, que se tornaram o clã dos levitas pelas famílias de seus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Os descendentes de Gérson começaram com seu filho Libni. O filho de Libni, Jaate; o filho de Jaate, Zima;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'o filho de Zima, Joá; o filho de Joá, Ido; o filho de Ido, Zerá; o filho de Zerá, Jeaterai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'A descendência de Coate começou com seu filho Aminadabe. O filho de Aminadabe, Corá; o filho de Corá, Assir;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'o filho de Assir, Elcana; o filho de Elcana, Ebiasafe; o filho de Ebiasafe, Assir;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'o filho de Assir, Taate; o filho de Taate, Uriel; o filho de Uriel, Uzias e o filho de Uzias, Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Os filhos de Elcana foram Amasai, Aimote e Elcana.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'O filho do segundo Elcana foi Zofai; o filho de Zofai, Naate;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'o filho de Naate, Eliabe; o filho de Eliabe, Jeroão; o filho de Jeroão, Elcana.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Os filhos de Samuel foram o primogênito Joel, e Abias, o segundo filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'O filho de Merari, Mali; o filho de Mali, Libni; o filho de Libni, Simei; o filho de Simei, Uzá;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'o filho de Uzá, Simeia; o filho de Simeia, Hagias; o filho de Hagias, Asaías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Esses são os nomes dos homens a quem Davi colocou no comando da música, na casa de Yahweh, depois que arca fora descansar ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Eles serviam por meio do canto diante do tabernáculo da Tenda do Encontro, até que Salomão construiu a casa de Yahweh em Jerusalém. Eles cumpriam seus deveres seguindo as instruções dadas a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Estes foram os que serviram com seus filhos, dos clãs dos Coatitas vieram Hemã, o musicista; aqui estavam seus ancestrais, voltando no tempo, Hemã filho de Joel; Joel, filho de Samuel;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Samuel, filho de Elcana; Elcana, filho de Jeroão; Jeroão filho de Eliel. Eliel, filho de Toá;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Toá filho de Zufe; Zufe filho de Elcana; Elcana, filho de Maate; Maate, filho de Amasai; Amasai, filho de Elcana.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Elcana, o filho de Joel. Joel, filho de Azarias; Azarias, filho de Sofonias;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Sofonias, filho de Taate; Taate, filho de Assir; Assir, filho de Ebiasafe; Ebiasafe, filho de Corá;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Corá, filho de Izar; Izar, filho de Coate; Coate, filho de Levi; Levi, filho de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'O irmão de Hemã foi Asafe, que foi sua mão direita. Asafe, filho de Berequias; Berequias, filho de Simeia;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Simeia, filho de Micael; Micael, filho de Baaseias; Baaseias, filho de Malquias;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Malquias, filho de Etni; Etini, filho de Zerá; Zerá, filho da Adaías;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Adaías, filho de Etã; Etã, filho de Zima; Zima, filho de Simei;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Simei, filho de Jaate; Jaate, filho de Gérson. Gérson, filho de Levi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'À esquerda de Hemã, estavam seus irmãos, filhos de Merari. Entre eles se incluiam Etã, filho de Quisi; Quisi, filho de Abdi; Abdi, filho de Maluque;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Maluque, filho de Hasabias; Hasabias, filho de Amazias; Amazias, filho de Hilquias;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Hilquias, filho de Anzi; Anzi, filho de Bani; Bani, filho de Semer;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Semer, filho de Mali; Mali, filho de Musi; Musi, filho de Merari; Merari, filho de Levi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Seus irmãos, os levitas, eram designados para fazer todo o trabalho do tabernáculo, a Casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Arão e seus filhos fizeram a oferta referente ao Santo Lugar; fizeram ofertas no altar, ofertas queimadas; fizeram as ofertas no altar de incenso; tudo isso era para fazer expiação para Israel. Eles seguiram tudo que Moisés, servo de Deus, havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'A descendência de Arão é contada como segue: o filho de Arão foi Eleazar; o filho de Eleazar foi Fineias; o filho de Fineias foi Abisua;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'o filho de Abisua foi Buqui; o filho de Buqui foi Uzi; o filho de Uzi foi Zeraías;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'o filho de Zeraías foi Meraiote; o filho de Meraiote foi Amarias; o filho de Amarias foi Aitube;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'o filho de Aitube foi Zadoque; o filho de Zadoque foi Aimaaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Estes foram os lugares designados aos descendentes de Arão; para os clãs dos coatitas (os primeiros lotes foram designados a eles);');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'eles designaram Hebrom na terra de Judá e suas pastagens;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'mas os campos da cidade e as aldeias ao redor foram dadas a Calebe, filho de Jefoné.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'A esses descendentes de Arão, foram dados Hebrom, que era a cidade de refúgio, Libna, com suas pastagens, Jatir e Estemoa, com suas pastagens;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'e Hilém, com suas pastagens; Debir com suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'A esses descendentes de Arão, foram dados Asã, com suas pastagens; Bete-Senues, com suas pastagens;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'da tribo de Benjamim lhes foi dado Geba, com suas pastagens; Alemete, com suas pastagens; Anatote, com suas pastagens; os clãs coatitas receberam treze cidades ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Para o restante dos descendentes coatitas, foram dadas, por sorteio, dez cidades da meia-tribo de Manassés;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'aos descendentes de Gérson, em seus clãs variados, foram dadas treze cidades das tribos de Issacar, Aser, Naftali e da meia-tribo de Manassés em Basã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Aos descendentes de Merari, foram dadas doze cidades por sorteio nos seus vários clãs das tribos de Rúben, Gade e Zebulom;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'então, o povo de Israel deu essas cidades com suas pastagens aos levitas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'eles nomearam por sorte as cidades mencionadas anteriormente das tribos de Judá, Simeão e Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'A alguns dos clãs dos coatitas, foram dadas cidades da tribo de Efraim;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'deram-lhes Siquém (a cidade de refúgio), com suas pastagens, na região montanhosa de Efraim, Gezer, com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jocmeão, com suas pastagens, Bete-Horom, com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Aijalom, com suas pastagens, e Gate-Rimom e suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'A meia tribo de Manassés deu aos coatitas: Aner, com suas pastagens, Bileã, com suas pastagens; essas se tornaram posses do restante dos clãs coatitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Aos descendentes de Gérson foram dados, dos clãs da meia-tribo de Manassés; Golã, em Basã, com suas pastagens, Astarote, com suas pastagens;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'da tribo de Issacar, os descendentes de Gérson receberam Quedes, com suas pastagens, Daberate, com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Ramote, com suas pastagens e Aném, com suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'Da tribo de Aser, eles receberam Masal, com suas pastagens, Abdom, com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Hucoque, com suas pastagens, e Reobe, com suas pastagens;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'da tribo de Naftali, eles receberam Quedes, na Galileia, com suas pastagens, Hamom, com suas pastagens, e Quiriataim, com suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Ao restante dos Levitas, aos descendentes de Merari, foi dado da tribo de Zebulom, Rimono, com suas pastagens e Tabor, com suas pastagens;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'lhes foi dado também, no outro lado do Jordão em Jericó, no lado leste do rio, Bezer, no deserto, com suas pastagens; Jaza, com suas pastagens;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Quedemote, com suas pastagens; Mefaate, com suas pastagens. A esses, foram dados da tribo de Rúben.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'Da tribo de Gade, foram dados, Ramote, em Gileade, com suas pastagens, Maanaim, com suas pastagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Hesbom, com suas pastagens e Jazer, com suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Os quatro filhos de Issacar eram Tolá, Pua, Jasube e Sinrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Os filhos de Tolá eram Uzi, Refaías, Jeriel, Jamai, Ibisão e Samuel. Eles eram os chefes das casas de seus pais, dos descedentes de Tolá. Eles eram conhecidos como homens fortes e corajosos na sua geração. Eles chegaram ao número de vinte e dois mil e seiscentos nos dias de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'O filho de Uzi era Izraías, cujos filhos eram Micael, Obadias, Joel e Issias; os cinco eram chefes de clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Junto deles, havia trinta e seis mil homens para batalha, de acordo com as listas dos descendentes do seu clã, pois tinham muitas esposas e filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Seus irmãos, a tribo de Issacar, tinham oitenta e sete mil guerreiros, de acordo com as listas dos descendentes do seu clã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Os três filhos de Benjamin foram Belá, Bequer e Jadiael.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Os cinco filhos de Belá foram Ezbom, Uzi, Uziel, Jerimote e Iri. Eles foram soldados que deram origem a clãs. O registro dos seus homens de guerra era de vinte e dois mil e trinta e quatro, de acordo com a lista dos seus descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Os filhos de Bequer foram Zemira, Joás, Eliézer, Elioenai, Onri, Jerimote, Abias, Anatote e Alemete; todos estes foram seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'As listas dos seus clãs contavam vinte mil e duzentos chefes de famílias e homens de guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'O filho de Jediael foi Bilã. Os filhos de Bilã foram Jeús, Benjamin, Eúde, Quenaaná, Zetã, Társis e Aisaar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Todos esses foram filhos de Jediael. Listados em seus clãs foram dezessete mil e duzentos líderes e guerreiros preparados para a guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, '(Supim e Hupim foram filhos de Ir e Husim foi filho de Aer).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Os filhos de Naftali foram Jaziel, Guni, Jezer e Salum. Esses foram netos de Bila.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Manassés teve um filho chamado Asriel, o qual sua concubina Aramite deu à luz. Ela deu à luz também a Maquir, pai de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Maquir tomou por esposa uma irmã de Hupim e Supim, cujo nome era Maacá. Outro descendente de Manassés foi Zelofeade, que teve somente filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Maacá, esposa de Maquir, gerou um filho e ela o chamou de Peres. O nome do seu irmão foi Seres, cujos filhos eram Ulão e Raquém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'O filho de Ulão era Bedã. Estes foram os descendentes de Gileade, filho de Maquir, filho de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Hamolequete, a irmã de Gileade, gerou Isode, Abiezer e Maclá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Os filhos de Semida foram Aiã, Siquém, Líqui e Anião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Os decendentes de Efraim foram estes: o filho de Efraim foi Sutela. O filho de Sutela foi Berede. O filho de Berede foi Taate. O filho de Taate foi Eleadá. O filho de Eleadá foi Taate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'O filho de Taate foi Zabade. O filho de Zabade foi Sutela (Ézer e Eleade foram mortos pelos homens de Gate, nativos da terra, quando foram roubar seu gado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Efraim, pai deles, lamentou por muitos dias e seus irmãos vieram para confortá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Ele deitou-se com sua esposa. Ela concebeu e deu à luz um filho. Efraim chamou-o de Beriá, porque uma tragédia veio à sua família.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Sua filha foi Seerá, que edificou a Baixa e a Alta Bete-Horom e também Uzem-Seerá).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Seu filho foi Refa. O filho de Refa foi Resefe. O filho de Resefe foi Telá. O filho de Tela foi Taã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'O filho de Taã foi Ladã. O filho de Ladã foi Amiúde. O filho de Amiúde foi Elisama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'O filho de Elisama foi Num. O filho de Num foi Josué.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Suas posses e residências foram Betel e seus povoados ao redor. Eles estenderam-se ao leste para Naarã e ao oeste para Gezer e seus povoados, e Siquém e seus povoados até Gaza e seus povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Na fronteira com Manassés, estavam Bete-Seã e seus povoados, Taanaque e seus povoados, Megido e seus povoados e Dor e seus povoados. Nessas cidades, viveram os descendentes de José, filho de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Os filhos de Aser foram Imná, Isvá, Isvi e Berias. Sera foi a irmã deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Os filhos de Berias foram Héber e Malquiel, que foi o pai de Birzavite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Os filhos de Héber foram Jaflete, Somer, Hotão. Suá foi a irmã deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Os filhos de Jaflete foram Pasaque, Bimal e Asvate. Estes foram os filhos de Jaflete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Semer, irmão de Jaflete, teve esses filhos: Aí, Roga, Jeubá e Arã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'O irmão de Semer, Helém, teve estes filhos: Zofa, Imna, Seles e Amal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Os filhos de Zofa foram Suá, Harnefer, Sual, Beri, Inra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Bezer, Hode, Samá, Silsa, Itrã e Beera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Os filhos de Jéter foram Jefoné, Pispa e Ara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Os filhos de Ula foram Ará, Haniel e Rízia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Todos estes foram descendentes de Aser. Eles foram ancestrais de clãs, líderes de suas famílias, homens destacados, guerreiros e chefes dentre os líderes. Havia vinte e seis mil homens listados para o serviço militar, de acordo com suas listas numeradas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Os cinco filhos de Benjamin foram Belá seu primogênito, Asbel, Aará,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noá e Rafa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Os filhos de Belá foram Adar, Gera, Abiúde,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Naamã, Aoá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Sefufã, e Hurão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Estes foram os descendentes de Eúde, que foram cabeças dos clãs dos habitantes de Geba, os quais foram forçados a ir para Manaate:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Naamã, Aías e Gera. O último, Gera, os conduziu na sua mudança. Ele foi o pai de Uzá e Aiúde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Saaraim se tornou pai de filhos na terra de Moabe, depois que ele se divorciou de suas esposas Husim e Baara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'De sua esposa Hodes, Saaraim gerou Jobabe, Zíbia, Messa, Malcã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeuz, Saquias, e Mirma. Estes foram seus filhos, líderes nos seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Ele já era o pai de Abitube e Elpaal, filhos de Husim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Os filhos de Elpaal eram Héber, Misã e Semede (que construiu Ono e Lode com seus povoados vizinhos). Havia também Berias e Sema.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Eles foram cabeças dos clãs que viveram em Aijalom, os quais expulsaram os habitantes de Gate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Berias teve estes filhos: Aiô, Sasaque, Jerimote,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zebadias, Arade, Eder,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Micael, Ispá, e Joá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Elpaal teve estes filhos: Zebadias, Mesulão, Hizqui, Héber,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Ismerai, Izlias, e Jobabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Simei teve estes filhos: Jaquim, Zicri, Zabdi,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienai, Ziletai, Eliel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaías, Beraías, e Sinrate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Sasaque teve estes filhos: Ispã, Éber, Eliel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdom, Zicri, Hanã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananias, Elão, Antotias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Ifdeias, e Penuel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Jeroão teve estes filhos: Sanserai, Searias, Atalias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaaresias, Elias, e Zicri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Estes foram os cabeças dos clãs e líderes que viveram em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'O pai de Gibeão, Jeiel, cuja esposa se chamava Maacá, viveu em Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Seu primogênito foi Abdom, seguido de Zur, Quiz, Baal, Nadabe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Aiô, e Zequer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'O outro filho de Jeiel era Miclote, que gerou Simeia. Eles também habitaram perto de seus parentes em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner foi o pai de Quis. Quis foi o pai de Saul. Saul foi o pai de Jônatas, Malquisua, Abinadabe, e Es-Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'O filho de Jônatas foi Meribe-Baal. Meribe-Baal foi o pai de Mica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Os filhos de Mica foram Pitom, Meleque, Tareá, e Acaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Acaz gerou Jeoada. Jeoada foi o pai de Alemete, Azmavete, e Zinri. Zinri foi o pai de Moza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Moza foi o pai de Bineá. Bineá foi o pai de Rafa. Rafa foi o pai de Eleasá. Eleasá foi o pai de Azel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Azel teve seis filhos: Azricão, Bocru, Ismael, Searias, Obadias, e Hanã. Todos esses eram filhos de Azel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Os filhos de Eseque, seu irmão, foram Ulão seu primogênito, Jeús o segundo, e Elifelete o terceiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Os filhos de Ulão foram lutadores e arqueiros. Eles tiveram muitos filhos e netos, no total de cento e cinquenta. Todos estes foram descendentes de Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Então, todo o Israel foi registrado em genealogias. Eles foram registrados no livro dos reis de Israel. E, Judá foi levado em exílio para a Babilônia, por causa do seu pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Os primeiros a se restabelecerem em suas cidades foram alguns israelitas, sacerdotes, levitas e servidores do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Alguns descendentes de Judá, Benjamim, Efraim e Manassés habitaram em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Entre eles, estavam Utai, filho de Amiúde, filho de Onri, filho de Inri, filho de Bani, um dos descendentes de Perez, filho de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Entre os silonitas, estavam Asaías, o primogênito, e seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Entre os descendentes de Zerá estava Jeuel. O número de seus descendentes foi seiscentos e noventa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Entre os descendentes de Benjamim, estavam Salu, filho de Mesulão, filho de Hodavias, filho de Hassenuá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Também estavam Ibneias, filho de Jeroão; Elá, filho de Uzi, filho de Micri; Mesulão, filho de Sefatias, filho de Reuel, filho de Ibnijas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Seus parentes, inscritos nas genealogias, foram novecentos e cinquenta e seis. Todos esses homens eram líderes nos clãs de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Os sacerdores foram Jedaías, Jeoiaribe e Jaquim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Azarias, filho de Hilquias, filho de Mesulão, filho de Zadoque, filho de Meraiote, filho de Aitube, era responsável pela Casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Adaías, filho de Jeroão, filho de Pasur, filho de Malquias; Maasai, filho de Adiel, filho de Jareza, filho de Mesulão, filho de Mesilemite, filho de Imer;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'e seus parentes, eram líderes nos clãs de seus antepassados, e foram mil setecentos e sessenta. Eles foram homens capacitados no trabalho da Casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Entre os levitas, havia Semaías, filho de Hassube, filho de Azricão, filho de Hasabias, entre os descendendes de Merari.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Havia também Baquebacar, Heres, Galal e Matanias, filho de Mica, filho de Zicri, filho de Asafe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Obadias, filho de Samaías, filho de Galal, filho de Jedutum; e Berequias, filho de Asa, filho de Elcana, que habitou nos povoados dos netofatitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Os porteiros foram Salum, Acube, Talmom, Aimã, e seus descendentes. Salum foi o líder deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Antes, eles ficavam de guarda à porta do rei, ao lado leste do campo dos descendentes de Levi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Salum, filho de Coré, filho de Ebiasafe, filho de Corá, e seus irmãos, do clã de seu pai, os coraítas, foram responsáveis pelo serviço no templo, como guardas da entrada da tenda, assim como seus descendentes guardaram o acampamento de Yahweh, e também a sua entrada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Fineias, filho de Eleazar, foi responsável por eles no passado, e Yahweh era com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zacarias, filho de Meselemias, guardava a entrada do templo, a \"Tenda do Encontro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Todos os escolhidos como porteiros das entradas foram duzentos e doze. Seus nomes foram registrados nas genealogias nos seus povoados. Davi e o vidente Samuel, os colocaram em posições de confiança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Então, eles e seus filhos guardaram os portões da Casa de Yahweh, o Tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Os porteiros estavam posicionados em todos os quatro lados, na direção leste, oeste, norte e sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Seus irmãos, que habitavam nos seus povoados, vinham em turnos de sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Mas os quatro líderes dos porteiros, que eram levitas, foram encarregados de guardar as salas e os armazéns da Casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Eles passavam a noite em seus postos, ao redor da Casa de Deus, porque eram responsáveis por guardá-la e abri-la a cada manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Alguns deles eram responsáveis pelos untensílios do templo; eles os contavam quando eram trazidos e quando eram retirados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Alguns deles também foram encarregados de cuidar das coisas santas, os utensílios do templo e os suprimentos, incluindo a farinha, o vinho, o óleo, o incenso e as especiarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Alguns dos filhos dos sacerdotes misturavam as especiarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Matitias, um dos levitas, que era o primogênito de Salum, o coraíta, era responsável por preparar pão para as ofertas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Alguns de seus irmãos, decendentes dos coraítas, eram responsáveis pelo pão da presença, para o preparar todo sábado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Os cantores e os chefes da família dos levitas moravam em quartos no santuário, eles estavam isentos de trabalho porque realizavam suas tarefas dia e noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Estes foram líderes de família entre os levitas, como listados em seus registros genealógicos. Eles habitavam em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'O pai de Gibeão, Jeiel, cuja mulher se chamava Maaca, habitava em Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Seu primogênito foi Abdom, depois seus filhos Zur, Quis, Baal, Ner, Nadabe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Aiô, Zacarias e Miclote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Miclote foi o pai de Simeão. Eles também habitaram perto de seus irmãos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ner foi o pai de Quis. Quis foi o pai de Saul. Saul foi o pai de Jônatas, Malquisua, Abinadabe e Es-Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'O filho de Jônatas foi Meribe-Baal. Meribe-Baal foi o pai de Mica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Os filhos de Mica foram Pitom, Meleque, Tareá e Acaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Acaz foi o pai de Jará. Jará foi o pai de Alemete, Azmavete e Zinri. Zinri foi o pai de Moza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Moza foi o pai de Bineá. Bineá foi o pai de Refaías. Refaías foi o pai de Eleasa. Eleasa foi o pai de Azel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Os seis filhos de Azel foram Azricão, Bocru, Ismael, Searias, Obadias e Hanã. Estes foram os filhos de Azel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Os filisteus lutaram contra Israel. Todos os homens de Israel fugiram de diante dos filisteus e caíram mortos no Monte Gilboa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Os filisteus perseguiram Saul e seus filhos. Mataram Jônatas, Abinadabe e Malquisua, filhos de Saul,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'A batalha contra Saul foi severa, e os arqueiros o alcançaram. Ele foi gravemente ferido por eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Então, Saul disse ao seu escudeiro: \"Tira a tua espada e mata-me. De outra maneira, esses incircuncisos virão e abusarão de mim\". Mas seu escudeiro não o fez, porque estava com muito medo. Então, Saul tomou sua própria espada e jogou-se sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Quando o seu escudeiro viu que Saul estava morto, ele também jogou-se sobre sua espada e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Assim morreram Saul e seus três filhos; todos os membros de sua casa morreram juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Quando todos os homens de Israel que estavam no vale viram que eles fugiram e que Saul e seus filhos estavam mortos, eles abandonaram suas cidades e fugiram. Então, os filisteus vieram e habitaram nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'No dia seguinte, quando os filisteus vieram saquear os mortos, eles encontraram os corpos de Saul e seus filhos no monte Gilboa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Eles saquearam seu corpo, cortaram sua cabeça e tiraram sua armadura. Enviaram mensageiros por toda a Filístia para levarem a notícia aos seus ídolos e ao povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Eles colocaram a armadura de Saul no templo de seus deuses e pregaram sua cabeça no templo de Dagom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Quando todos em Jabes-Gileade ouviram tudo o que os filisteus fizeram a Saul,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'todos os guerreiros foram e pegaram o corpo de Saul e de seus filhos e os trouxeram para Jabes. Eles enterraram seus ossos debaixo do carvalho em Jabes e jejuaram por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Assim, Saul morreu porque foi infiel a Yahweh. Ele não obedeceu as instruções de Yahweh, mas pediu conselhos a alguém que consultava os mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'Ele não buscou a orientação de Yahweh, por isso, Yahweh o matou e entregou o reino a Davi, filho de Jessé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Então, todo o Israel veio a Davi em Hebrom e disse: \"Olha, nós somos tua carne e teus ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Num passado recente, quando Saul reinava sobre nós, tu lideravas o exército israelita. Yahweh, nosso Deus, te disse: \'Tu pastorearás meu povo Israel, e tu te tornarás governador sobre meu povo Israel\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Então, todos os anciãos de Israel vieram ao rei em Hebrom, e Davi fez um pacto com eles diante de Yahweh. Eles ungiram a Davi rei sobre Israel. Dessa maneira, a palavra de Yahweh que havia sido declarada por Samuel tornou-se verdadeira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Davi e todo o Israel foram a Jerusalém, que é Jebus. Estavam ali os jebuseus, habitantes da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Os habitantes de Jebus disseram a Davi: \"Tu não entrarás aqui\". Mas Davi tomou a fortaleza de Sião, que é a cidade de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'E disse: \"Quem primeiro atacar os jebuseus se tornará comandante\". E Joabe, filho de Zeruia, atacou primeiro, sendo, então, feito comandante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Então, Davi passou a morar na fortaleza. E eles a chamaram a cidade de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Ele fortificou a cidade ao redor, desde Milo até as muralhas, e Joabe, o restante da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Davi se tornou cada vez mais poderoso porque Yahweh dos Exércitos era com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Estes eram os líderes de Davi, os quais se mostraram fortes com ele em seu reino, juntamente com todo o Israel, para fazê-lo rei, obedecendo a palavra de Yahweh acerca de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Esta é a lista da elite dos guerreiros de Davi: Jasobeão, o filho de um Hacmonita, comandante de trinta, o qual, numa ocasião, matou trezentos homens com a sua lança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Depois dele, Eleazar, filho de Dodô, o aoíta, o qual foi um dos três guerreiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Ele estava com Davi em Pas-Damim, onde os filisteus se reuniram para a batalha. Havia ali um campo de cevada e o exército fugiu diante dos filisteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Eles se colocaram no meio do campo, defenderam-no e mataram os filisteus. Yahweh os salvou com uma grande vitória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Então, três dos líderes de trinta desceram a Davi no penhasco, na caverna de Adulão. O exército dos filisteus estava acampado no vale de Refaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Naquele tempo, Davi estava em sua fortaleza, a caverna, enquanto os filisteus haviam estabelecido o seu acampamento em Belém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Davi teve sede e disse: \"Quem me dera beber da água do poço de Belém, o poço que está próximo do portão!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Então, esses três guerreiros romperam o exército dos filisteus e tiraram água do poço de Belém, que está próximo do portão. Eles pegaram a água e a trouxeram a Davi, mas ele se recusou a bebê-la. Ao invés disso, derramou-a diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'Então, ele disse: \"Longe de mim, Yahweh, que eu bebesse disso! Beberia eu do sangue desses homens, que arriscaram suas vidas?\". Porque eles arriscaram suas vidas, Davi recusou-se a beber da água. Assim fizeram os três guerreiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Abisai, irmão de Joabe, foi capitão sobre os três. Certa vez, ele usou sua lança contra trezentos e os matou. Ele é mencionado juntamente com os três guerreiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Dos três, a ele foi dada dupla honra e o tornaram seu capitão, ainda que não fosse um deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaia, filho de Joiada, foi um homem poderoso de grandes feitos. Ele matou os dois filhos de Ariel de Moabe e também desceu à caverna e matou um leão enquanto estava nevando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Foi ele quem matou um egípicio, um homem de cinco côvados de altura. O egípicio tinha uma lança como um lançador de tecelão, mas ele o atacou com o seu cajado, arracando a lança da mão do egípicio e matando-o com a sua própria lança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Benaia, filho de Joiada, fez esses feitos e ganhou nome ao lado dos três guerreiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Ele era mais estimado que os trinta soldados em geral, mas não era tão reconhecido como os três maiores guerreiros da elite. Mesmo assim, Davi o colocou encarregado da sua guarda pessoal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Os guerreiros foram Asael, irmão de Joabe; Elanã filho de Dodô, de Belém;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Samote, o harorita; Heles, o pelonita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, filho de Iques, o tecoíta; Abiezer, o anatotita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibecai, o husatita; Ilai, o aoíta;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maarai, o netofatita; Helede, filho de Baaná, o netofatita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Itai, filho de Ribai, de Gibeá, dos descendentes de Benjamim; Benaías, o piratonita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Hurai, dos vales de Gaás; Abiel, o arbatita,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azmavete, o baarumita; Eiabá, o saalbonita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'os filhos de Hasem, o gizonita; Jônatas, filho de Sage, o hararita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Aião, filho de Sacar, o hararita; Elifal, filho de Ur;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hefer, o mequeratita; Aías, o pelonita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hezro, o carmelita; Naarai, filho de Ezbai;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, irmão de Natã; Mibar, filho de Hagri;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Zeleque, o amonita; Naarai, o berotita, escudeiro de Joabe, filho de Zeruia;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira, o itrita; Garebe, o itrita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urias, o heteu; Zabade, filho de Alai;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, filho de Ziza, o rubenita (um chefe dos rubenitas) e trinta com ele;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanã, filho de Maacá, e Jeosafá, o mitnita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uzias, o asteratita; Sama e Jeiel, filhos de Hotão, o aroerita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, filho de Sinri, e Joá, seu irmão, o tizita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel, o maavita; Jeribai e Josavias, filhos de Elnaão; Itma, o moabita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, Obede e Jaasiel, o mezobaíta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Estes foram os homens que vieram a Davi em Zicagle, enquanto ele ainda estava fugindo da presença de Saul, filho de Quis. Eles estavam entre os soldados, seus ajudantes na batalha;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'estavam armados com arcos e usavam tanto a mão direita quanto a esquerda para atirar pedras com fundas e flechas com os arcos. Eram benjamitas, companheiros da tribo de Saul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Aizer, o chefe, e Joás eram filhos de Semaá, o gibeatita. Havia Jeziel e Pelete, filhos de Azmavete. Havia também Beraca e Jéu, o anatotita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Ismaías, o gibeonita, soldado entre os trinta e, no comando dos trinta, Jeremias, Jaaziel, Joanã, Jozabade, o gederatita;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Eluzai, Jerimote, Bealias, Semarias e Sefatias, o harufita,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'os coraítas Elcana, Issias, Azarel, Joezer e Jasobeão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'e Joela e Zebadias, filhos de Jeroão de Gedor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Alguns gaditas se juntaram a Davi na fortaleza do deserto. Eles eram homens de guerra, treinados para a batalha, que sabiam usar escudo e lança; suas faces eram ferozes como as faces de leões. Eles eram ágeis como gazelas das montanhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Havia Ézer, o líder; Obadias, o segundo; Eliabe o terceiro;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Mismana, o quarto; Jeremias, o quinto;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Atai, o sexto; Eliel, o sétimo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Joanã, o oitavo; Elzabade, o nono;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jeremias, o décimo; Macbanai, o décimo primeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Esses filhos de Gade foram os líderes do exército; o menor conduzia cem, e o maior conduzia mil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Eles atravessaram o Jordão no primeiro mês, quando transbordava pelas margens, e afugentaram todos os que moravam nos vales, tanto na direção leste quanto na direção oeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Alguns dos homens de Benjamim e Judá vieram para a fortaleza de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Davi foi ao encontro deles e lhes disse: \"Se viestes em paz para me ajudar, podeis vos juntar a mim; mas, se viestes para me entregar para meus adversários, que o Deus de nossos antepassados veja e vos repreenda, já que eu não fiz nada errado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Então, o Espírito veio sobre Amasai, que era o chefe dos trinta. Amasai disse: \"Nós somos teus, Davi. Estamos do teu lado, filho de Jessé. Paz! Que a paz esteja com quem quer que te ajudar. Que a paz esteja com teus ajudantes, porque o teu Deus está te ajudando\". Então, Davi os recebeu e os fez comandantes sobre seus homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Alguns de Manassés se uniram a Davi quando ele veio com os filisteus para a batalha contra Saul. Eles não os ajudaram porque os chefes filisteus se consultaram entre si e mandaram Davi embora. Eles disseram: \"Ele irá se unir a Saul, colocando em risco nossas vidas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Quando ele foi a Ziclague, os homens de Manassés que se juntaram a ele foram Adna, Jozabade, Jediael, Micael, Jozabade, Eliú e Ziletai, capitães de milhares de Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Eles ajudaram Davi a lutar contra os saqueadores, pois eram homens de guerra. Mais tarde, eles se tornaram comandantes no exército.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Dia após dia, chegavam homens para ajudar Davi, até que se formou um grande exército, como o exército de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Este é o registro dos soldados armados para batalha, que vieram a Davi, em Hebrom, para passar o reino de Saul para ele, de acordo com a promessa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'De Judá, aqueles que carregavam escudo e lança eram seis mil e oitocentos armados para a guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Dos simeonitas, eram sete mil e cem homens de guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Dos levitas, eram quatro mil e seiscentos soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Joiada era o líder dos descendentes de Arão, e com ele havia três mil e setecentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Com Zadoque, um homem jovem, forte e corajoso, estavam vinte e dois líderes da familia de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'De Benjamim, tribo de Saul, havia três mil. A maioria deles se manteve fiel a Saul até esse momento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'De Efraim, havia vinte mil e oitocentos soldados, homens famosos na família de seus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Da meia tribo de Manassés, havia dezoito mil homens famosos, que vieram para tornar Davi rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'De Issacar, eram duzentos líderes, conhecedores do tempo e que sabiam o que Israel devia fazer. Todos os seus parentes estavam sob seu comando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'De Zebulom, eram cinquenta mil soldados preparados para a batalha, com todas as armas de guerra, e prontos para demonstrar sua total lealdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'De Naftali, havia mil oficiais, e, com eles, trinta e sete mil homens com escudos e lanças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'De Dã, havia vinte e oito mil homens preparados para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'De Aser, havia quarenta mil homens preparados para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Vindo do outro lado do Jordão, dos rubenitas, gaditas e da meia tribo de Manassés, havia cento e vinte mil homens portando todo tipo de armas para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Todos estes soldados, equipados para a batalha, vieram de Hebrom com a intenção de tornar Davi rei de todo o Israel. O restante de Israel também estava de acordo em tornar Davi rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Eles estiveram com Davi por três dias, comendo e bebendo, pois seus parentes haviam enviado provisões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Também, os que estavam próximos a eles, e os que estavam longe, como em Issacar, Zebulom e Naftali, trouxeram pães em jumentos, camelos, mulas e bois; bolos de figos, cachos de uvas passas, vinho, óleo, bois e ovelhas, pois Israel estava celebrando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Davi se consultou com os comandantes de milhares e de centenas, com cada líder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Ele disse para toda a assembleia de Israel: \"Se parecer bem para vós, e se isto vem de Yahweh, nosso Deus, enviaremos mensageiros de todos os lugares para nossos irmãos que permanecem em todas as regiões de Israel e para os sacerdotes e levitas que estão em suas cidades, para que se reúnam conosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Tragamos a arca do nosso Deus de volta para nós, porque não buscamos Sua vontade nos dias do reinado de Saul\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Toda a assembleia concordou em fazer essas coisas, porque pareceu certo aos olhos de todo o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Então, Davi reuniu todo o Israel, desde o rio Sior, no Egito, até Lebo-Hamate, para trazer a arca de Deus de Quiriate-Jearim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Davi e todo o Israel subiram a Baalá, que é Quiriate-Jearim, que pertence a Judá, para trazer de lá a arca de Deus, sobre a qual se invoca o nome de Yahweh, que está entronizado sobre os querubins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Então, eles colocaram a arca de Deus em uma carroça nova e a trouxeram da casa de Abinadabe; Uzá e Aiô estavam guiando a carroça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Davi e todo o Israel estavam celebrando diante de Deus com todas as suas forças. Eles estavam cantando com instrumentos de cordas, tamborins, címbalos e trombetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Quando chegaram à eira de Quidom, Uzá estendeu sua mão para segurar a arca, porque os bois tropeçaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Imediatamente, a ira de Yahweh se acendeu contra Uzá, e Yahweh o matou, porque ele tinha estendido sua mão para a arca. Ele morreu ali, diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Davi ficou irritado porque Yahweh tinha punido Uzá. Aquele lugar é chamado Perez-Uzá até os dias de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Davi teve medo de Deus naquele dia. Ele disse: \"Como posso levar a arca de Deus para minha casa?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Então, Davi não moveu a arca para a sua cidade, mas propôs deixá-la na casa de Obede-Edom, o geteu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'A arca de Deus permaneceu na casa de Obede-Edom, por três meses. Então, Yahweh abençoou sua casa e tudo que possuía.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Então, Hirão, rei de Tiro, enviou a Davi mensageiros, árvores de cedro, carpinteiros e pedreiros. Eles construíram uma casa para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Davi soube que Yahweh o tinha estabelecido como rei sobre Israel e que seu reino tinha sido exaltado por causa de Seu povo Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Em Jerusalém, Davi tomou outras esposas, e se tornou pai de mais filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Estes foram os nomes dos filhos dele, que nasceram em Jerusalém: Samua, Sobabe, Natã, Salomão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Ibar, Elisua, Elpelete,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Nogá, Nefegue, Jafia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Beeliada e Elifelete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Quando os filisteus ouviram que Davi tinha sido ungido como rei sobre todo o Israel, todos eles saíram a procurá-lo. Mas Davi soube disso e saiu contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Os filisteus vieram e invadiram o vale de Refaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Então, Davi pediu ajuda a Deus. Ele disse: \"Devo atacar os filisteus? Tu darás vitória sobre eles?\". Yahweh lhe disse: \"Ataca, pois Eu certamente os darei a ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Então, eles foram a Baal-Perazim, e lá ele os derrotou. Ele comentou: \"Yahweh destruiu meus inimigos por minha mão, como uma explosão de torrentes de água\". Então, o nome daquele lugar se tornou Baal-Perazim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Os filisteus abandonaram seus deuses os quais foram queimados por ordem de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Então, os filisteus invadiram o vale novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Naquela ocasião, Davi pediu ajuda a Deus outra vez. Deus lhe disse: \"Não ataques pela frente, mas dá a volta por trás, e passa pela floresta de amoreira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Quando tu ouvires o som de marcha pelo vento, soprando nas copas das amoreiras, ataca com força. Faze isso, pois Deus terá saído antes de ti para atacar o exército dos filisteus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Então, Davi fez conforme Deus havia ordenado. Ele derrotou o exército dos filisteus desde Gibeão até Gezer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Assim, a fama de Davi percorreu por todas as terras, e Yahweh fez com que todas as nações o temessem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Davi construiu casas para si, na cidade de Davi. Ele preparou um lugar para a Arca de Deus e lhe montou uma tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Então, disse Davi: \"Somente os levitas podem carregar a Arca de Deus, porque Yahweh os escolheu para carregá-la e servi-Lo para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Assim, Davi reuniu todo o Israel em Jerusalém, para trazer a Arca de Yahweh ao lugar que foi preparado para ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Davi reuniu os descendentes de Arão e os levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Dos descendentes de Coate, havia Uriel, o chefe, e seus parentes, cento e vinte homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Dos descendentes de Merari, havia Asaías, o chefe, e seus parentes, duzentos e vinte homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Dos descendentes de Gérson, havia Joel, o chefe, e seus parentes, cento e trinta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Dos descendentes de Elizafã, havia Semaías o chefe e seus parentes, duzentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Dos descendentes de Hebrom, havia Eliel, o chefe, e seus parentes, oitenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Dos descendentes de Uziel, havia Aminadabe, o chefe, e seus parentes, cento e doze homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Davi chamou os sacerdotes Zadoque e Abiatar, e os levitas Uriel, Asaías, Joel, Semaías, Eliel, e Aminadabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'Ele lhes disse: \"Vós sois os chefes das famílias dos levitas; dedicai-vos a Yahweh, vós e vossos irmãos, para que tragais a Arca de Yahweh, Deus de Israel, para o lugar que eu tenho preparado para ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Vós não a carregastes na primeira vez, por isso, Yahweh, nosso Deus, veio contra nós, porque nós não O buscamos ou obedecemos o Seu decreto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Então, os sacerdotes e os levitas consagraram-se para trazer a Arca de Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Os levitas carregaram a Arca de Deus em seus ombros com as varas, como Moisés tinha ordenado — conforme a palavra de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Davi falou com os líderes dos levitas para nomear seus irmãos para tocarem instrumentos musicais de corda, harpas e címbalos, tocando alto e cantando alegremente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Então, os levitas nomearam Hemã, filho de Joel, e um de seus irmãos, Asafe, filho de Berequias. Eles também nomearam os parentes dos descendentes de Merari e Etã, filho de Cusaías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'Com eles, estavam seus parentes de segunda ordem: Zacarias, Jaaziel, Semiramote, Jaiel, Uni, Eliabe, Benaia, Maaseias, Matitias, Elifeleu, Micneias, Obede-Edom e Jeiel, os porteiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Os músicos Hemã, Asafe e Etã foram nomeados para tocarem os címbalos de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zacarias, Aziel, Semiramote, Jaiel, Uni, Eliabe, Maaseias e Benaia tocavam instrumentos de cordas, definidos para soprano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Matitias, Elifeleu, Micneias, Obede-Edom, Jeiel e Azazias os dirigiam, tocando harpas, definidas para o baixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Quenanias, chefe dos levitas, foi o diretor de canto porque era professor de música.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Berequias e Elcana foram os guardas da arca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Sebanias, Josafá, Netanel, Amasai, Zacarias, Benaia e Eliézer, os sacerdotes, tocavam as trombetas diante da Arca de Deus, e Obede-Edom e Jeías guardavam a arca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Então, Davi, os anciãos de Israel e os comandantes de milhares trouxeram a Arca da Aliança de Yahweh da casa de Obede-Edom com alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Enquanto Deus ajudava os levitas que carregavam a Arca da Aliança de Yahweh, eles sacrificavam sete touros e sete carneiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Davi vestiu um manto de linho fino, assim como os levitas que carregavam a arca, os cantores e Quenanias, o líder do canto, com os cantores. Davi também vestiu um éfode de linho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Então, todo o Israel trouxe a Arca da Aliança de Yahweh com júbilos e com som de trombetas, com címbalos e instrumentos de corda e harpas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Mas, quando a Arca da Aliança de Yahweh chegou à cidade de Davi, Mical, filha de Saul, olhou pela janela e viu o rei Davi dançando e celebrando, ela, então, o desprezou em seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Eles trouxeram a Arca de Deus e a colocaram no meio da tenda que Davi havia montado para ela. Então, ofereceram holocaustos e ofertas pacíficas diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Quando Davi terminou os sacríficios de holocaustos e ofertas pacíficas, ele abençoou o povo em nome de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Ele distribuiu para todo israelita, tanto para homens como para mulheres, uma porção de pão, um pedaço de carne e bolo de uva passas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Davi designou determinados levitas para servir, diante da Arca de Yahweh, celebrar, agradecer e louvar Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Esses levitas foram Asafe, o líder, e, depois dele, Zacarias, Jeiel, Semiramote, Jaiel, Matitias, Eliabe, Benaia, Obede-Edom e Jeiel. Estes tocavam instrumentos de cordas e harpas. Asafe devia tocar os címbalos bem alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Os sarcedotes Benaia e Jaaziel tocavam as trombetas regularmente, diante da Arca da Aliança de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Então, naquele dia, Davi primeiro nomeou a Asafe e seus irmãos para entoar esse cântico de agradecimento a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Dai graças a Yahweh, invocai o Seu nome, fazei conhecidos Seus atos entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Cantai a Ele, cantai louvores a Ele, falai de todos os Seus maravilhosos atos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Gloriai-vos em Seu santo nome, deixai que se alegre o coração daqueles que buscam a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Buscai a Yahweh e Sua força, buscai a Sua presença continuamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Lembrai-vos das coisas maravilhosas que Ele fez, Seus milagres e os decretos de Sua boca,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'vós, descendentes de Israel, Seu servo, vós, povo de Jacó, Seus escolhidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Ele é Yahweh, nosso Deus. Seus decretos estão por toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Guardai Sua aliança na mente para sempre, a palavra que Ele ordenou por mil gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Ele traz à lembrança a aliança que Ele fez com Abraão, e Seu juramento a Isaque;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'o que Ele confirmou a Jacó por estatuto, e a Israel como um pacto eterno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Ele disse: \"Dar-vos-ei a terra de Canaã como parte da vossa herança\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Eu disse isso quando vós éreis apenas um pequeno grupo, tão poucos, e eram estranhos na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Eles foram de nação em nação, de um reino a outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Ele não permitiu que ninguém os oprimisse, Ele puniu reis pelo bem do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Ele disse: \"não toqueis nos meus ungidos e não causeis dano aos Meus profetas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Cantai a Yahweh, toda a terra, anunciai Sua salvação dia após dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Declarai a Sua glória entre as nações, Seus maravilhosos atos entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Pois Yahweh é grande e digno de ser louvado, e será temido entre todos os outros deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Porque todos os deuses das nações são ídolos, mas foi Yahweh quem criou os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Esplendor e majestade estão em Sua presença. Força e alegria estão diante dEle.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Tributai a Yahweh, vós clãs dos povos, tibutai a Yahweh glória e força.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Tributai a Yahweh a glória devida ao Seu nome. Trazei uma oferta e vinde diante dele. Curvai-vos diante de Yahweh em Seu santo esplendor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Tremei diante Dele toda a terra. O mundo também está estabelecido, não pode ser abalado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Alegrem-se os céus, regozige-se a terra; seja dito entre as nações, \"Yahweh reina\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Que o mar ruja, e as suas criaturas gritem com alegria. Que os campos sejam alegres, e tudo o que neles há.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Que as árvores das florestas gritem de alegria diante de Yahweh, porque Ele vem julgar a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Louvai a Yahweh, porque Ele é bom, porque a fidelidade da Sua aliança dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Então, dizei: \"Salva-nos, Deus da nossa salvação. Ajunta-nos e livra-nos das outras nações, para que possamos dar graças ao Teu santo nome e glória em Teus louvores\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Seja Yahweh, o Deus de Israel, louvado de eternidade a eternidade. Todos que estavam ali disseram: \"Amém\" e louvaram a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Então, Davi deixou Asafe e seus irmãos diante da Arca da Aliança de Yahweh, para servirem continuamente diante da arca, como requeria a obra de todos os dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Obede-Edom com seus sessenta e oito parentes estavam incluídos. Obede-Edom, filho de Jedutum, junto com Hosa, seria porteiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Zadoque, o sarcedote, e seus irmãos sacerdotes, serviriam diante do tabernáculo de Yahweh, no lugar alto, em Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Eles ofereceriam holocaustos para Yahweh no altar apropriado, continuamente, pela manhã e à tarde, conforme tudo quanto estava escrito na lei de Yahweh, a qual Ele deu por mandamento a Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Hemã e Jedutum estavam com eles, juntamente com os restantes que foram escolhidos pelo nome, para dar graças a Yahweh, porque a fidelidade da Sua aliança dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Hemã e Jedutum estavam no comando daqueles que tocavam trombetas, címbalos e outros instrumentos para a música sagrada. Os filhos de Jedutum guardavam o portão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Então, todo o povo se foi para as suas casas, e Davi voltou para abençoar sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Aconteceu que, após o rei ter se estabelecido em sua casa, ele disse ao profeta Natã: \"Olha, eu estou morando em uma casa de cedro, mas a Arca da Aliança de Yahweh está sob uma tenda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Então, Natã disse a Davi: \"Vai e faz o que está em teu coração, pois Deus é contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Mas, naquela mesma noite, a palavra de Deus veio a Natã, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '\"Vai e diz a Meu servo Davi: \'Assim diz Yahweh: Tu não construirás uma casa para Eu morar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'pois Eu não morei em casa alguma desde o dia em que tirei Israel do Egito até o dia de hoje. Em vez disso, tenho morado em uma tenda, um tabernáculo, em vários lugares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Em todos os lugares para os quais Me mudei, entre todo o Israel, porventura, falei alguma palavra aos líderes de Israel que designei para pastorear o Meu povo, dizendo: \'Por que não Me edificaste uma casa de cedro?\"\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Agora, pois, diz a Meu servo Davi: \'Assim diz Yahweh dos Exércitos: \"Eu te tirei da pastagem, de andar atrás das ovelhas, para que fosses governador do Meu povo Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Eu tenho estado contigo por onde quer que foste e tenho eliminado todos os teus inimigos de diante de ti, e farei teu nome tão grande quanto o nome dos maiores líderes na Terra;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Eu designarei um lugar para Meu povo Israel e o plantarei lá para que possam viver em seu próprio lugar e não sejam mais perturbados; não serão mais oprimidos por perversos, como antes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'desde os dias em que ordenei juízes sobre o Meu povo Israel. Então, Eu subjugarei todos os teus inimigos; também te digo, que Eu, Yahweh, edificarei uma casa para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Quando teus dias forem cumpridos para ires a teus pais, suscitarei um descendente depois de ti, um dos teus filhos, e Eu estabelecerei o seu reino;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'ele construirá uma casa para Mim e Eu estabelecerei o trono dele para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Eu lhe serei por Pai e ele será Meu filho; não retirarei dele Minha misericórdia, como a retirei de Saul, que governou antes de ti;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Eu o confirmarei na Minha casa em Meu reino para sempre, seu trono será estabelecido para sempre\"\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Natã falou a Davi, relatou-lhe todas essas palavras e lhe contou toda a visão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Então, o rei Davi entrou, ficou diante de Yahweh e disse: \"Quem sou eu, Deus Yahweh, e quem é minha família para que me tenhas trazido até aqui?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Pois isso foi pouco aos Teus olhos, Deus, falar sobre a família de Teu servo sobre um maravilhoso futuro, e me mostrar as gerações futuras, Deus Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Que mais posso eu, Davi, dizer a Ti? Tens honrado Teu servo. Tu tens dado reconhecimento especial ao Teu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Yahweh, por causa de Teu servo e para cumprir Teu propósito, tens feito grandes coisas para revelar todos os Teus grandes feitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Yahweh, não há ninguém como Tu e não há outro Deus além de Ti, assim como sempre ouvimos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Que nação na Terra é como Teu povo Israel a quem Tu, Deus, resgataste do Egito para ser Teu povo, e engrandeceste Teu próprio Nome pelos grandes e maravilhosos feitos? Tu expulsaste nações diante de Teu povo a quem resgataste do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Fizeste Israel, Teu povo para sempre, e Tu, Yahweh, Te tornaste o seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Então, agora, Yahweh, que a promessa que fizeste a respeito de Teu servo e sua família, seja estabelecida para sempre. Faze como falaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Que Teu nome seja estabelecido para sempre e seja engrandecido. Assim, o povo dirá: \'Yahweh dos Exércitos é o Deus de Israel\', e que a casa de Teu servo Davi permaneça firme diante de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Pois Tu, meu Deus, revelaste a Teu servo que lhe construirás uma casa; por isso encontrei eu, Teu servo, coragem para orar a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Agora, Yahweh, Tu és Deus e tens feito essa boa promessa a Teu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Agora, Te agradaste abençoar a casa de Teu servo, e que possa continuar para sempre diante de Ti; pois Tu, Yahweh, a tens abençoado e será abençoada para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Depois disso, aconteceu que Davi atacou os filisteus e os derrotou. Ele tomou Gate e suas vilas do controle dos filisteus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'então, derrotou Moabe, e os moabitas se tornaram servos de Davi e pagavam tributos a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Davi também derrotou Hadadezer, rei de Zobá, em Hamate, enquanto Hadadezer estava viajando para estabelecer seu domínio no rio Eufrates.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Davi capturou dele mil carros, sete mil cavaleiros e vinte mil soldados. Davi aleijou todos os cavalos dos carros, mas reservou o suficiente deles para cem carros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Quando os sírios de Damasco vieram socorrer Hadadezer, rei de Zobá, Davi matou vinte e dois mil deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Então, Davi pôs guarnições entre os sírios de Damasco, os quais se tornaram seus servos e lhe trouxeram tributos, e Yahweh dava vitória a Davi por onde quer ele fosse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Davi tomou os escudos de ouro que estavam com os servos de Hadadezer e os trouxe a Jerusalém;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'de Tibate e de Cum, cidades de Hadadezer, Davi tomou muito bronze. Foi com esse bronze que Salomão, mais tarde, fez o mar de bronze, os pilares e os utensílios de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Quando Toú, rei de Hamate, soube que Davi havia derrotado todo o exército de Hadadezer, rei de Zobá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Toú mandou Hadorão seu filho ao rei Davi para cumprimentá-lo e abençoá-lo, porque Davi havia lutado contra Hadadezer e derrotado, pois Hadadezer já havia travado guerra contra Toú. Hadorão trouxe com ele objetos de ouro, prata e bronze;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'os quais o rei Davi consagrou a Yahweh, junto com o ouro e a prata que tomou de todas as nações: Edom, Moabe, o povo de Ammon, os filisteus, e os amalequitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Abisai, filho de Zeruia matou dezoito mil edomitas no vale do Sal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Ele colocou guarnições em Edom, e todos os edomitas se tornaram servos de Davi. Yahweh dava vitória a Davi em qualquer lugar a que ele fosse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Davi reinou sobre todo o Israel, e ele administrava justiça e retidão a todo o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joabe, filho de Zeruia, era o comandante do exército, e Josafá, filho de Ailude, era escrivão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Zadoque, filho de Aitube, e Abimeleque, filho de Abiatar, eram sacerdotes; Sausa era escriba;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benaia, filho de Joiada, estava sobre os quereteus e peleteus, e os filhos de Davi eram os conselheiros do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'E sucedeu que Naás, rei do povo amonita, morreu, e seu filho se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Davi disse: \"Eu vou mostrar bondade com Hanum, filho de Naás, porque seu pai mostrou bondade para comigo\". Então, Davi enviou mensageiros para consolá-lo a respeito de seu pai. Os servos de Davi chegaram à terra dos amonitas e foram até Hanum, para consolá-lo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'mas os líderes dos amonitas disseram a Hanum: \"Tu acreditas que Davi está honrando teu pai porque ele enviou homens para te confortar? Não vieram os servos dele até ti para explorar e examinar as terras a fim de destruí-las?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Então, Hanum tomou os servos de Davi, rapou-os, cortou suas roupas da cintura até as nádegas, e mandou-os embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Quando explicaram isso a Davi, ele enviou mensageiros para encontrá-los, porque estavam profundamente envergonhados. O rei disse: \"Permanecei em Jericó até que vossas barbas cresçam novamente, e, então, retornai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Quando os amonitas viram que provocaram ódio em Davi, Hanum e os amonitas enviaram mil talentos de prata para alugar carros e cavaleiros da Mesopotânia, de Arã-Maacá e Zobá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Eles alugaram trinta e dois mil carros com o rei de Arã-Maacá e seu povo, que vieram e acamparam diante de Medeba. Os amonitas se uniram em suas cidades e saíram para a guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Quando Davi ouviu isso, ele enviou Joabe e seu exército para encontrá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'O povo amonita saiu e se posicionou para a batalha no portão da cidade, enquanto os reis que vieram, estavam sozinhos no campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Quando Joabe viu as linhas de batalha voltadas para ele, na frente e atrás, ele escolheu alguns dos melhores soldados de Israel e os organizou contra os sírios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Quanto ao restante do exército, ele entregou para o comando de Absai, seu irmão, e ele os colocou na linha de batalha contra o exército dos amonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Joabe disse: \"Se os sírios forem muitos fortes para mim, então tu, Absai, deve me resgatar. Mas, se o exército dos amonitas for muito forte para vós, então, eu virei e vos resgatarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Sejamos fortes, e nos mostremos fortes para o nosso povo e para as cidades do nosso Deus, pois Yahweh fará o que for melhor para o Seu propósito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Então, Joabe e os soldados de seu exército avançaram para a batalha contra os sírios, que foram forçados a fugir diante do exército de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Quando o exército dos amonitas viu que os sírios haviam fugido, eles também fugiram do irmão de Joabe, Abisai, e voltaram para dentro da cidade. Então, Joabe deixou os amonitas e voltou para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Quando os sírios viram que haviam sido derrotados por Israel, eles enviaram reforços de além do rio Eufrates, com Sofaque, comandante do exército de Hadadezer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Quando Davi soube disso, ele reuniu todo o Israel, atravessou o Jordão, e veio sobre eles. Ele organizou o exército para a batalha contra os sírios, e estes lutaram contra ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Os sírios fugiram de Israel, e Davi matou sete mil condutores de carros e quarenta mil soldados da infantaria. Ele também matou Sofaque, o comandante do exército.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Quando todos os reis, que eram servos de Hadadezer, viram que eles haviam sido derrotados por Israel, eles fizeram paz com Davi e o serviram. Então, os sírios não estiveram mais dispostos a ajudar os amonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Chegada a primavera, no tempo em que normalmente os reis vão à guerra, Joabe liderou o exército na batalha, devastou o território dos amonitas e sitiou Rabá. Davi, porém, permaneceu em Jerusalém. Joabe atacou Rabá e a derrotou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Davi tirou a coroa da cabeça do rei deles, e ele descobriu nela o peso de um talento de ouro, e nela havia pedras preciosas. A coroa foi colocada na cabeça de Davi, e ele trouxe o despojo da cidade em grande quantidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Ele trouxe o povo que estava na cidade, e o forçou a trabalhar com serras, picaretas de ferro e machados. Davi exigiu que todas as cidades dos amonitas fizessem esse trabalho. Então, Davi e todo o exército retornaram para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'E aconteceu que, mais tarde, estavam guerreando em Gezer contra os filisteus. Sibecai, o husatita, matou Sipai, um dos descendentes dos refains, e os filisteus foram subjugados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Aconteceu, novamente, outra guerra contra os filisteus em Gobe, e, Elanã, filho de Jair, matou Lami, irmão de Golias, o geteu, cuja lança era como a haste de tecelão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Aconteceu, novamente, outra guerra em Gate. Lá havia um homem de grande estatura, que tinha seis dedos em cada mão, e seis dedos em cada pé. Ele também era descendente dos refains.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Quando ele zombou do exército de Israel, Jônatas, filho de Simeia, irmão de Davi, o matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Esses foram descendentes dos refains de Gate, e foram mortos pela mão de Davi e pela mão de seus soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Satanás se levantou contra Israel e incitou Davi a fazer a contagem de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Davi disse a Joabe e aos comandantes do exército: \"Ide, contai o povo de Israel, de Berseba até Dã e reportai de volta a mim, para que eu saiba seu número\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joabe disse: \"Que Yahweh faça seu exército cem vezes maior do que já é. Mas, meu senhor, o rei, não servem todos eles ao meu senhor? Por que meu senhor quer isso? Por que trazer culpa sobre Israel?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Mas a palavra do rei foi final contra Joabe. Então, saiu Joabe e percorreu todo o Israel e depois voltou para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Joabe relatou o total da contagem de todos os homens de combate a Davi. Havia em Israel um milhão e cem mil homens que manejavam a espada. Somente em Judá havia quatrocentos e setenta mil soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Porém, Levi e Benjamim não foram contados entre eles, pois a ordem do rei foi abominável a Joabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Deus não se agradou desta ação. Por isso Ele atacou Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Davi disse a Yahweh: \"Eu pequei grandemente fazendo isso; agora retira a culpa de Teu servo, pois eu agi tolamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Yahweh disse a Gade, o profeta de Davi:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, '\"Vai e diz a Davi: \'Assim diz Yahweh: Eu te dou três opções, escolhe uma delas\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Gade foi até Davi e disse a ele: \"Assim diz Yahweh: \'Faz a tua escolha:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'ou três anos de escassez, três meses de perseguição por teus inimigos, sendo atacado por suas espadas, ou então, três dias da espada de Yahweh, isto é, uma praga em toda a terra, com o Anjo de Yahweh destruindo toda a terra de Israel\'. Agora, decide qual a resposta que levarei àquele que me enviou\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Então, Davi disse a Gade: \"Eu estou em grande aflição, deixa-me cair nas mãos de Yahweh ao invés de cair nas mãos dos homens, pois grandes são Seus misericordiosos feitos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Então, Yahweh enviou uma praga sobre Israel e setenta mil pessoas morreram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Yahweh enviou um anjo para destruir Jerusalém; porém, quando ele estava prestes a destruí-la, Yahweh olhou e mudou Sua opinião sobre aquele castigo. Ele falou ao anjo destruidor: \"Basta! Agora recolhe a tua mão\". E, naquela hora, o Anjo de Yahweh estava em pé na eira de Ornã, o jebuseu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Davi olhou para cima e viu o Anjo de Yahweh em pé entre a terra e o céu, com a espada desembainhada em suas mãos levantada sobre Jerusalém. Então, Davi e os anciãos, vestidos em sacos, se prostraram com o rosto em terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Davi disse a Yahweh: \"Não fui eu que ordenei que numerasse o exército? Eu fiz algo abominável, mas estas ovelhas, o que elas fizeram? Yahweh, meu Deus, que a Tua mão castigue a mim e a minha família, mas não castigue o Teu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Então, o Anjo de Yahweh ordenou Gade que dissesse a Davi que ele deveria subir e contruir um altar para Yahweh na eira de Ornã, o Jebuseu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Então, Davi subiu como Gade o instruiu a fazer em nome de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Enquanto Ornã estava malhando trigo, ele se virou e viu o anjo; então, ele e seus quatro filhos se esconderam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Quando Davi se aproximava, Ornã olhou e viu Davi. Ele deixou a eira e se prostrou diante de Davi com seu rosto no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Então, Davi disse a Ornã: \"Vende-me esta eira, para que eu possa construir um altar para Yahweh, eu pagarei o devido valor, para que a praga seja removida do povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Ornã disse a Davi: \"Toma-a para ti, meu senhor, o rei, faz com ela o que for bom aos teus olhos. Olha, eu te darei bois para os holocaustos e o debulhador como lenha e o trigo para oferta de cereais; te darei tudo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'O rei Davi disse a Ornã: \"Não, eu insisto em comprar pelo devido valor, eu não tomarei o que é teu e oferecerei como sacrifício a Yahweh o que não me custar nada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Então, Davi pagou seiscentos siclos de ouro pelo terreno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Ele construiu um altar para Yahweh ali e ofereceu holocaustos e ofertas pacíficas sobre o altar. Davi invocou Yahweh, que respondeu com fogo dos céus sobre o altar dos holocautos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Então, Yahweh deu ordem a Seu anjo e ele embainhou sua espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Então, Davi viu que Yahweh o respondeu no meio da eira de Ornã, o jebuseu; ele ofereceu ali, os seus sacrifícios ao mesmo tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Naquele tempo, o tabernáculo de Yahweh, que Moisés fez no deserto, e o altar dos holocaustos estavam no lugar alto de Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Contudo, Davi não pôde pedir direção para Deus, pois estava com medo da espada do Anjo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Então, Davi disse: \"Este é o lugar onde o Templo de Yahweh ficará, com o altar de holocaustos de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'E Davi ordenou aos seus servos que reunissem os estrangeiros que viviam na terra de Israel. Ele os nomeou pedreiros, para cortar blocos de pedra, a fim de construir o Templo de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Davi proveu uma grande quantidade de ferro para os pregos das portas que iriam nas entradas, e para dobradiças. Ele também proveu mais bronze do que poderia ser pesado');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'e mais cedro do que poderia ser contado. (Os sidônios e os tírios traziam muitas toras de cedro para Davi contar).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Davi disse: \"Meu filho Salomão é novo e sem experiência, e o Templo que será construído para Yahweh deve ser especialmente magnífico, de modo que seja famoso e glorioso em todas as outras terras. Então, eu prepararei para a construção\". E Davi fez grandes preparativos antes de sua morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Então, ele chamou seu filho, Salomão e ordenou que ele construísse um Templo para Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Davi disse a Salomão: \"Meu filho, era a minha intenção eu mesmo construir um templo sozinho, para o nome de Yahweh, meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Mas Yahweh veio até mim e disse: \'Tu derramaste muito sangue e lutaste muitas batalhas. Tu não construirás um templo ao Meu nome, porque tu derramaste muito sangue na terra diante de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Contudo, tu terás um filho que será um homem pacífico. Eu darei a ele descanso de todos os inimigos ao seu redor. O nome dele será Salomão, e Eu darei paz e descanso a Israel durante seus dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Ele construirá um templo ao Meu nome. Ele será Meu filho, e Eu serei seu Pai. Eu estabelecerei o trono do seu reino sobre Israel para sempre\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Agora, meu filho, que Deus esteja contigo e te capacite para ter sucesso. Que tu construas o Templo de Yahweh, Teu Deus, como Ele falou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Que Yahweh te dê discernimento e entendimento, para que tu obedeças a Lei de Yahweh, Teu Deus, quando Ele te colocar para governar Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Então, tu terás sucesso, se cuidadosamente obedecerdes os estatutos e decretos que Yahweh deu a Moisés acerca de Israel. Sê forte e corajoso; não temas, nem desanimes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Agora, vê, com grande esforço, eu preparei para o Templo de Yahweh cem mil talentos de ouro, um milhão de talentos de prata, e bronze e ferro em grande quantidade. Eu também provi madeira e pedra. Deve adicionar mais a tudo isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Tu terás muitos trabalhadores: pedreiros, engenheiros, carpinteiros e inúmeros artesãos habilidosos de todos os tipos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'que podem trabalhar com ouro, prata, bronze e ferro. Então, começa a trabalhar e que Yahweh esteja contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Davi também ordenou que todos os chefes de Israel ajudassem seu filho Salomão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '\"Yahweh, vosso Deus, está convosco e tem vos dado paz em todos os lados. Ele entregou, em minhas mãos, os habitantes da região, que é subjugada diante de Yahweh e seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Agora, buscai a Yahweh Teu Deus com todo vosso coração e com toda a vossa alma. Levantai e construí o Lugar Santo de Yahweh. Assim, podereis trazer a Arca da Aliança de Yahweh e as coisas que pertencem a Yahweh para a casa construída ao nome de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Quando Davi estava velho e perto do final de sua vida, ele fez seu filho Salomão, rei sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Ele reuniu todos os líderes de Israel, com os sacerdotes e levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Os levitas que tinham trinta anos ou mais foram contados, o número total foi de trinta e oito mil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, '\"Destes, vinte e quatro mil supervisionaram o trabalho da casa de Yahweh, e seis mil foram oficiais e juízes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Quatro mil foram porteiros; e quatro mil louvavam Yahweh com instrumentos que eu fiz para a adoração.\", disse Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Davi os dividiu em grupos que correspondiam aos filhos de Levi: Gérson, Coate e Merari.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Dos clãs decendentes de Gérson, havia Ladã e Simei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Havia três filhos de Ladã: Jeiel, o chefe, Zetão e Joel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Havia três filhos de Simei: Selomite, Haziel e Arã. Esses foram os líderes do clã de Ladã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Havia quatro filhos de Simei: Jaate, Ziza, Jeús e Berias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jaate era o mais velho, e Ziza o segundo, mas Jeús e Berias não tiveram muitos filhos, então, eram considerados como um único clã com as mesmas obrigações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Havia quatro filhos de Coate: Anrão, Izar, Hebrom e Uziel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Estes eram os filhos de Anrão: Arão e Moisés. Arão foi escolhido para consagrar as coisas santíssimas, e ele e seus descendentes ofereceriam incenso diante de Yahweh, O serviriam e pronunciariam bençãos em Seu nome, para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Mas, quanto a Moisés, homem de Deus, seus filhos foram considerados levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Os filhos de Moisés foram Gérson e Eliézer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'O descendente de Gérson foi Sebuel, o mais velho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'O descendente de Eliézer foi Reabias. Eliézer não teve outros filhos, mas Reabias teve muitos descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'O descendente de Izar foi Selomite, o líder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Os descendentes de Hebrom foram Jerias, o mais velho; Amarias, o segundo; Jaaziel, o terceiro; e Jecameão, o quarto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Os filhos de Uziel foram Mica, o mais velho, e Issias, o segundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Os filhos de Merari foram Mali e Musi. Os filhos de Mali foram Eleazar e Quis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Eleazar morreu sem ter filhos. Ele teve apenas filhas. Os filhos de Quis casaram com elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Os três filhos de Musi foram Mali, Eder e Jerimote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Estes foram os descendentes de Levi correspondentes aos seus clãs. Eles eram os líderes, contados e listados pelo nome, do clãs que trabalhavam no serviço da Casa de Yahweh, de trinta anos para cima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Davi disse: \"Yahweh, o Deus de Israel, deu descanso ao Seu povo. Ele estabelece a Sua Casa em Jerusalém para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Os levitas não precisarão mais carregar o Tabernáculo nem os utensílios usados para seu serviço\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Pelas últimas palavras de Davi, os levitas foram contados, de vinte anos de idade para cima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'O dever deles era auxiliar os descendentes de Arão no serviço da Casa de Yahweh. Eles cuidavam dos pátios, dos aposentos, da purificação cerimonial de todas as coisas pertencentes a Yahweh, e outras obras a serviço da casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Eles também tomavam conta dos Pães da Proposição, e do trigo fino para as ofertas de cereal, dos pães sem fermento e ofertas assadas, das ofertas misturadas com óleo, e todo tipo de medidas e pesos das coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Eles também se levantavam toda manhã para agradecer e adorar Yahweh. Eles faziam isso também ao entardecer');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'e sempre que holocaustos eram oferecidos para Yahweh, no sábado, nas Festas de Lua Nova e nos dias de celebração. Um número fixo, designado por decreto, sempre tinha que estar presente diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Eles estavam no comando da Tenda do Encontro, o Santo Lugar, e ajudavam seus companheiros, descendentes de Arão, no serviço da Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Os grupos de trabalho, baseados nos descendentes de Arão, foram estes: Nadabe, Abiú, Eleazar e Itamar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Nadabe e Abiú morreram antes de seu pai. Eles não tiveram filhos, então, Eleazar e Itamar serviam como sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Davi, juntamente com Zadoque, descendente de Eleazar, e Aimeleque, descendente de Itamar, dividiu-os em grupos para o seu trabalho como sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Havia mais homens influentes entre os descendentes de Eleazar do que entre os descendentes de Itamar, então, eles dividiram os descendentes de Eleazar em dezesseis grupos. Eles fizeram isso pelos cabeças dos clãs e pelos descendentes de Itamar. Estas divisões eram oito em número, correspondendo aos seus clãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Eles os dividiram imparcialmente por sorte, porque havia chefes do santuário e chefes escolhidos por Deus, ambos descendentes de Eleazar e de Itamar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Semaías, filho de Netanel, o escriba, um levita, registrou o nome deles na presença do rei, dos oficiais, de Zadoque, o sacerdote, de Aimeleque, filho de Abiatar, e dos líderes do sacerdócio e das famílias dos levitas. Um clã foi sorteado, dos descendentes de Eleazar e, então, o próximo seria sorteado dos descendentes de Itamar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'A primeira sorte foi para Jeoiaribe, a segunda para Jedaías,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'a terceira para Harim, a quarta para Seorim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'a quinta para Malquias, a sexta para Miamim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'a sétima para Hacoz, a oitava para Abias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'a nona para Jesuá, a décima para Secanias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'a décima primeira para Eliasibe, a décima segunda para Jaquim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'a décima terceira para Hupá, a décima quarta para Jesebeabe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'a décima quinta para Bilga, a décima sexta para Imer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'a décima sétima para Hezir, a décima oitava para Hapizes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'a décima nona para Petaías, a vigésima para Jeezquel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'a vigésima primeira para Jaquim, a vigésima segunda para Gamul,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'a vigésima terceira para Delaías e a vigésima quarta para Maazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Esta era a ordem do culto deles quando vinham ao Templo de Yahweh, segundo o procedimento dado a eles por Arão, seu antepassado, como Yahweh, o Deus de Israel, o havia instruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Este era o restante dos descendentes de Levi: dos filhos de Anrão, Subael. Dos filhos de Subael, Jedeías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Dos filhos de Reabias, Issias, que foi o líder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Dos izaritas, Selomote. Dos filhos de Selomote, Jaate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Os filhos de Hebrom, Jerias, o primogênito, Amarias, o segundo, Jaaziel, o terceiro e Jecameão, o quarto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Os filhos de Uziel incluíam Mica. Os filhos de Mica incluíam Samir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'O irmão de Mica foi Issias. Os filhos de Issias incluíam Zacarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Os filhos de Merari, Mali e Musi. O filho de Jaazias, Beno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Os filhos de Merari: Jaazias, Beno, Soão, Zacur e Ibri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Os filhos de Mali: Eleazar, que não teve filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Dos filhos de Quis, Jerameel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Dos filhos de Musi, Mali, Eder e Jerimote. Estes foram levitas, listados por suas famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Estes homens, tanto para os chefes de família, como também para os irmãos mais novos, lançaram sortes na presença do rei Davi, de Zadoque e de Aimeleque, juntamente com os líderes das famílias dos sacerdotes e levitas. Eles lançaram sortes, assim como os descendentes de Aarão tinham feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Davi e os líderes do serviço no tabernáculo selecionaram alguns dos filhos de Asafe, de Hemã e de Jedutum. Estes profetizavam com harpas, instrumentos de cordas e címbalos. Aqui está a lista de homens que fizeram esse serviço:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'dos filhos de Asafe: Zacur, José, Netanias e Asarela, filhos de Asafe, sob a sua direção, que profetizavam sob a supervisão do rei;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'dos filhos de Jedutum: Gedalias, Zeri, Jesaías, Simei, Hasabias e Matitias, que eram seis, sob a direção de seu pai, Jedutum, que tocava harpa para dar graças e louvar Yahweh;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'dos filhos de Hemã: Buquias, Matanias, Uziel, Sebuel, Jerimote, Hananias, Hanani, Eliatá, Gidalti, Romanti-Ezer, Josbecasa, Maloti, Hotir e Maaziote,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'todos esses eram filhos de Hemã, o profeta do rei. Deus deu a Hemã catorze filhos e três filhas para honrá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Todos esses estavam debaixo da direção de seus pais. Eles eram músicos na casa de Yahweh, com címbalos e instrumentos de cordas, enquanto serviam na casa de Deus. Asafe, Jedutum e Hemã estavam sob a supervisão do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Eles e seus irmãos, que foram habilitados e treinados para fazer músicas para Yahweh, somavam duzentos e oitenta e oito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Eles designaram seus serviços por sortes, tanto os jovens como os velhos, os mestres como os estudantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Dos filhos de Asafe, a primeira sorte caiu para a família de José; a segunda, para a família de Gedalias, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'A terceira caiu para Zacur, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'A quarta, para Izri, seus filhos e seus parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'A quinta, para Netanias, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'A sexta, para Buquias, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'A sétima, para Jesarela, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'A oitava, para Jesaías, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'A nona para Matanias, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'A décima, para Simei, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'A décima primeira, para Azarel, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'A décima segunda, para Hasabias, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'A décima terceira, para Subael, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'A décima quarta, para Matitias, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'A décima quinta, para Jerimote, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'A décima sexta, para Hananias, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'A décima sétima, para Josbecasa, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'A décima oitava, para Hanani, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'A décima nona, para Maloti, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'A vigésima, para Eliata, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'A vigésima primeira, para Hotir, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'A vigésima segunda, para Gidalti, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'A vigésima terceira, para Maaziote, seus filhos e parentes, que eram doze pessoas ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'A vigésima quarta, para Romanti-Ezer, seus filhos e parentes, que eram doze ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Estas foram as divisōes dos porteiros: dos coraítas, Meselemias, filho de Coré, um descendente de Asafe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Meselemias teve filhos: Zacarias, o primogênito; Jediael, o segundo; Zebadias, o terceiro; Jatniel, o quarto;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Elão, o quinto; Jeoanã, o sexto; Elioenai, o sétimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Obede-Edom teve filhos: Semaías, o primogênito; Jeozabade, o segundo; Joá, o terceiro; Sacar, o quarto; Netanel, o quinto;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Amiel, o sexto; Issacar, o sétimo; Peuletai, o oitavo; pois Yahweh o tinha abençoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Seu filho Semaíais também teve filhos, que foram chefes de suas famílias; eles foram homens com muitas habilidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Os filhos de Semaías foram Otni, Rafael, Obede e Elzabade. Seus parentes Eliú e Semaquias, também eram homens com muitas habilidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Todos eles foram descendentes de Obede-Edom. Eles, seus filhos e parentes foram homens capazes de fazer seus deveres nos serviços do tabernáculo; eram ao todo sessenta e dois descendentes de Obede-Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Meselemias teve filhos e parentes, homens capazes; dezoito ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Hosa, um descendente de Merari, teve filhos: Sinri, o líder (embora não fosse o primogênito, seu pai o fez líder),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Hilquias, o segundo; Tebalias, o terceiro; Zacarias, o quarto. Todos os filhos de Hosa e parentes, foram treze, ao todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Essas divisōes dos porteiros, correspondendo ao seus líderes, tinham responsabilidades, como seus parentes, para servir na casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Eles lançaram sortes, tanto para jovens, como para idosos, correspondentes a suas famílias, para cada portão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Quando as sortes foram lançadas para o portão leste, caiu para Selemias. Depois, lançaram sortes para Zacarias, seu filho, um conselheiro prudente, e sua sorte caiu para o portão norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'A Obede-Edom foi designado o portão sul; e a seus filhos foram designados os depósitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'A Supim e Hosa foram designados o portão oeste, junto ao portão Salequete, na estrada de cima. Vigias foram estabelecidos para cada família.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'A leste, ficavam seis levitas; ao norte, quatro, por dia; ao sul quatro, por dia, e nos depósitos ficavam duas duplas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'No pátio a oeste, ficavam quatro na estrada, e dois no pátio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Foram estas as divisōes dos porteiros. Eles foram ocupados pelos descendentes de Coré e Merari.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Dos levitas, Aías estava encarregado dos tesouros da Casa de Yahweh e dos tesouros das coisas que pertenciam a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Os descendentes de Ladã, dos gersonitas líderes das famílias de Ladã, eram Jeieli e seus filhos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Zetão e Joel, seu irmão, eram encarregados de vigiar os depósitos na Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Também havia guardas dos clãs de Anrão, de Isar, de Hebrom e de Uziel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Sebuel, filho de Gérson, o filho de Moisés, era o supervisor dos depósitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Seus parentes por parte de Eliézer foram: seu filho Reabias; o filho de Reabias, Jesaías; o filho de Jesaías, Jorão; o filho de Jorão, Zicri; e o filho de Zicri, Selomote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Selomote e seus parentes estavam encarregados de todos os depósitos que pertenciam a Yahweh, que o rei Davi, os líderes das famílias, os comandantes de milhares e de centenas de soldados, e os comandantes do exército haviam separado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Eles separaram os despojos ganhos em batalhas, para manutenção da Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Eles também eram encarregados de tudo que havia sido separado para Yahweh pelo profeta Samuel, Saul, filho de Quis, Abner, filho de Ner, e Joabe, filho de Zeruia. Tudo quanto havia sido separado para Yahweh estava sob a guarda de Selomote e seus parentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Dos descendentes de Isar, Quenanias e seus filhos ficaram encarregados das questões civis de Israel. Eles eram oficiais e juízes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Dos descendentes de Hebrom, Hasabias e seus irmãos eram mil e setecentos homens valentes, que estavam a oeste do Jordão, encarregados dos serviços de Yahweh e do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Dos descendentes de Hebrom, Jerias era líder de seus descendentes, contados das listas de suas famílias. No ano quarenta do reinado de Davi, eles examinaram os registros e acharam entre eles homens valentes em Jazer de Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Jerias tinha dois mil e setecentos parentes, que eram valentes líderes de suas famílias. Então, Davi lhes designou para chefiarem as tribos de Rúben e de Gade, e a meia tribo de Manassés, em todos os serviços de Deus e para as questões do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Esta é a lista dos líderes das famílias israelitas, comandantes de milhares e de centenas, assim como dos oficiais armados que serviram ao rei de várias formas. Cada divisão militar servia mês a mês durante o ano. Havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Sobre a divisão do primeiro turno do mês, estava Jasobeão, filho de Zabdiel; em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Ele foi descendente de Perez e estava no comando de todos os oficiais do exército no primeiro mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Sobre a divisão do segundo turno do mês, estava Dodai, o aoíta; o segundo no comando era Miclote. Em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'O terceiro comandante do exército era Benaia, filho de Joiada, sacerdote e líder; em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Esse é o Benaia que era líder dos trinta, e estava sobre os trinta. Seu filho Amizabade estava em sua divisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'O comandante para o quarto mês era Asael irmão de Joabe; seu filho Zebadias foi comandante depois dele. Em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'O comandante para o quinto mês era Samute, o israíta; em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'O comandante para o sexto mês era Ira, filho de Iques, o tecoíta; em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'O comandante para o sétimo mês era Helez, o pelonita, dos efraimitas; em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'O comandante para o oitavo mês era Sibecai, o husatita, dos zeraítas; em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'O comandante para o nono mês era Abiezer, o anatotita, dos benjamitas; em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'O comandante do décimo mês era Maarai, o netofatita, dos zeraítas; em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'O comandante do décimo primeiro mês era Benaías, o piratonita, dos efraimitas; em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'O comandante do décimo segundo mês era Heldai, o netofatita, dos descendentes de Otniel; em sua divisão, havia vinte e quatro mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Estes eram os líderes das tribos de Israel: sobre a tribo de Rúben, Eliézer, filho de Zicri, era o líder; sobre a tribo de Simeão, Sefatias, filho de Maaca, era o líder;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'sobre a tribo de Levi, Hasabias, filho de Quemuel, era o líder; e Zadoque liderava os aronitas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'sobre a tribo de Judá, Eliú, um dos irmãos de Davi, era o líder; sobre a tribo de Issacar, Onri, filho de Micael, era o líder;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'sobre a tribo de Zebulom, Ismaías, filho de Obadias, era o líder; sobre a tribo de Naftali, Jerimote, filho de Azriel, era o líder;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'sobre a tribo de Efraim, Oseias, filho de Azazias, era o líder; sobre a meia tribo de Manassés, Joel, filho de Pedaías, era o líder;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'sobre a meia tribo de Manassés, em Gileade, Ido, filho de Zacarias, era o líder; sobre a tribo de Benjamin, Jaasiel, filho de Abner, era o líder;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'sobre a tribo de Dã, Azarel, filho de Jeroão, era o líder. Esses eram os líderes das tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Davi não contou aqueles que tinham menos de vinte anos, porque Yahweh havia prometido aumentar Israel como as estrelas do céu;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joabe, filho de Zeruia, começou a contar os homens mas não terminou; por causa disso, veio a fúria sobre Israel. Esse número não foi escrito nas Crônicas do rei Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Azmavete, filho de Adiel, era encarregado dos tesouros do rei; Jônatas, filho de Uzias, era encarregado dos depósitos nos campos, nas cidades, nos vilarejos e nas torres fortificadas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Ezri, filho de Quelube, era encarregado dos trabalhadores, daqueles que cuidavam da terra;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Simei, o ramatita, era encarregado dos vinhedos, e Zabdi, o sifmita, era encarregado das uvas e das adegas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Sobre os olivais e os sicômoros que havia nas campinas, estava Baal-Hanã, o gederita; e, sobre os depósitos de azeite, estava Joás;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'sobre os rebanhos que estavam pastando em Sarom, estava Sitrai, o saronita; e, sobre os rebanhos que se encontravam nos vales, estava Safate, filho de Adlai;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'sobre os camelos, estava Obil, o ismaelita; sobre as jumentas, estava Jedias, o merononita; sobre os rebanhos, estava Jaziz, o hagrita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Todos esses estavam supervisionando as propriedades do rei Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Jônatas, tio de Davi, era um conselheiro, já que era um homem sábio e escriba. Jeiel, filho de Hacmoni, cuidava dos filhos do rei;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Aitofel era o conselheiro do rei, Husai, o arquita, era o conselheiro privado do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'A posição de Aitofel foi tomada por Joiada, filho de Benaia, e por Abiatar. Joabe era comandante do exército do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Davi reuniu todos os oficiais de Israel em Jerusalém, tanto os oficiais das tribos como os das fronteiras, que serviam ao rei no trabalho planejado, os comandantes de milhares e de centenas, os gestores de todas as propriedades e possessões do rei e de seus filhos, e os oficiais e guerreiros mais valentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Então, o rei Davi levantou-se e disse: \"Ouvi-me, meus irmãos e meu povo. Era a minha intenção construir um templo para a Arca da Aliança de Yahweh, um estrado para nosso Deus, e eu fiz os preparativos para construí-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Mas Deus me disse: \'Tu não construirás um templo em Meu nome, porque tu és um homem de guerra e já derramaste muito sangue\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'No entanto, Yahweh, o Deus de Israel, me escolheu de toda a família de meu pai para ser o rei sobre Israel para sempre. Ele escolheu a tribo de Judá como cabeça. Da tribo de Judá, e da casa do meu pai, de todos os filhos do meu pai, Ele escolheu a mim para ser rei sobre todo o Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Dentre todos os muitos filhos que Yahweh me deu, Ele escolheu Salomão, meu filho, para sentar-se no trono do reino de Yahweh, sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Ele me disse: \'Salomão, teu filho, construirá a Minha casa e os Meus pátios, pois Eu o escolhi para ser Meu filho, e Eu serei seu Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Eu estabelecerei o seu reino para sempre, se ele continuar comprometido em obedecer a Meus mandamentos e decretos, como tu fazes hoje\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Agora, então, à vista de todo o Israel, a assembleia de Yahweh, e na presença do nosso Deus que ouve, devei guardar e vos empenhar em cumprir todos os mandamentos de Yahweh, vosso Deus. Fazei isso para que possuais esta boa terra e a deixeis como uma herança para vossos filhos depois de vós para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Quanto a ti, Salomão, meu filho, conhece o Deus de teu pai, e serve-O com todo o teu coração e com uma alma disposta. Faz isso, pois Yahweh examina todos os corações e discerne toda motivação de todos os pensamentos. Se O buscares, tu O encontrarás, mas, se O abandonares, Ele te rejeitará permanentemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Considera que Yahweh te escolheu para construíres um templo como Seu santuário. Sê forte e faz isso\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Então, Davi deu a Salomão, seu filho, o projeto para a entrada do templo, para a construção do templo, dos depósitos, dos cômodos, das salas internas e do lugar da propiciação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'Deu ele a Salomão os projetos que havia desenhado para: o pátio do templo de Yahweh; todas as salas vizinhas; os depósitos do templo de Deus. Além dos tesouros para as coisas que pertencem a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'Davi deu a ele ordens para a divisão dos sacerdotes e levitas, para as responsabilidades designadas para o trabalho do templo de Yahweh, e para todos os objetos para o trabalho no templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Deu a ele o peso de todos os vasos de ouro para todo o tipo de trabalho, de todos os vasos de prata e de todos os objetos de todos os tipos de trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Ele especificou de forma detalhada as quantidades necessárias de ouro para: os candelabros de ouro e suas lâmpadas, os candelabros de prata e suas lâmpadas; para o uso adequado de cada candelabro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Ele deu o peso do ouro para as mesas dos pães da proposição, para cada mesa, e o peso da prata para as mesas de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Ele deu o peso do ouro puro para os garfos de carne, as vasilhas e as taças. Ele deu o peso para cada tigela de ouro e para cada tigela de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Ele deu o peso do ouro refinado para o altar do incenso, e o ouro para o modelo dos querubins que estendiam suas asas e cobriam a arca da Aliança de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Davi disse: \"Eu escrevi tudo isso conforme a direção e o entendimento que Yahweh me deu a respeito do modelo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Davi disse para Salomão, seu filho: \"Sê forte e corajoso. Faz o trabalho. Não tenhas medo ou ansiedade, pois Yahweh, meu Deus, é contigo. Ele não te deixará nem te abandonará até que todo o trabalho para a obra do templo de Yahweh esteja finalizado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Vê, aqui está a divisão dos sacerdotes e levitas para todo o trabalho no templo de Deus. Eles estarão contigo, juntamente com todos os homens dispostos e habilidosos, para te auxiliarem no trabalho e para realizarem a obra. Os oficiais e todas as pessoas estão prontas para seguir os teus comandos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'O rei Davi disse a toda assembleia: \"Salomão, meu filho, a quem Deus tem escolhido, ainda é jovem e inexperiente, e a tarefa é grande. Pois o templo não é para o povo, mas para Deus Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Portanto, eu fiz o meu melhor para prover para o templo do meu Deus. Estou dando ouro para as coisas a serem feitas de ouro, prata para as coisas a serem feitas de prata, bronze para as coisas a serem feitas de bronze, ferro para as coisas a serem feitas de ferro, e madeira para as coisas a serem feitas de madeira. Eu também estou dando pedras de ônix, pedras para serem incrustadas, pedras para o trabalho de sobreposição de várias cores, todo tipo de pedras preciosas e pedra mármore em abundância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Agora, por causa da minha alegria pelo templo do meu Deus, eu estou dando o meu tesouro pessoal de ouro e prata. Estou fazendo isso complementando a tudo o que eu já tenho preparado para este Santo Templo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'três mil talentos de ouro de Ofir, e sete mil talentos de prata refinada, para revestir as paredes dos cômodos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Estou doando ouro para as coisas que serão feitas de ouro, e prata para as coisas que serão feitas de prata, e coisas para todos os tipos de trabalho feitos pelos artesãos. Quem mais quer contribuir, voluntariamente, para Yahweh e se consagrar a Ele, hoje?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Então, foram feitas ofertas voluntárias pelos líderes das famílias dos antepassados, os líderes das tribos de Israel, os comandantes de milhares e de centenas, e pelos oficiais sobre os trabalhos do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Eles deram, para a obra do templo de Deus, cinco mil talentos e dez mil dáricos de ouro, dez mil talentos de prata, dezoito mil talentos de bronze e cem mil talentos de ferro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Aqueles que possuíam pedras preciosas deram-nas para o tesouro do templo de Yahweh, debaixo da supervisão de Jeiel, descendente de Gerson.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'O povo se alegrou por causa das ofertas voluntárias, porque eles tinham contribuído com sinceridade para Yahweh. O rei Davi também se alegrou grandemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Davi bendisse a Yahweh diante de toda a assembleia. Ele disse: \"Seja louvado Yahweh, Deus de nosso antepassado Israel, para sempre e sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Tua, Yahweh, é a grandeza, o poder, a glória, a vitória e a majestade. Porque tudo o que está nos céus e na terra é Teu. Teu é o reino, Yahweh, e Tu és exaltado como soberano sobre tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Tanto riquezas como honra vêm de Ti, e Tu dominas sobre todos os povos. Nas Tuas mãos, estão o poder e a força. Tu possuis a força e o poder de engrandecer as pessoas e dar força a quem quiser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Agora, então, nosso Deus, nós Te agradecemos e louvamos o Teu glorioso Nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Mas quem sou eu, e quem é o meu povo, para que pudéssemos ser capazes de oferecer tão voluntariamente estas coisas? Na verdade, todas as coisas vêm de Ti, e nós simplesmente Te devolvemos o que é Teu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Porque nós somos estranhos e peregrinos diante de Ti, assim como foram todos os nossos antepassados. Nossos dias na terra são como uma sombra, e não há esperança em permanecer na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Yahweh, nosso Deus, toda essa riqueza que nós coletamos para construir o templo, em honra ao Teu Santo Nome — ela vem de Ti e pertence a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Eu também sei, meu Deus, que Tu examinas o coração e tem prazer na retidão. Quanto a mim, na retidão do meu coração eu ofereci, voluntariamente, todas essas coisas, e agora vejo com alegria que o Teu povo que está presente aqui, voluntariamente, oferece presentes a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Yahweh, Deus de Abraão, Isaque e Israel — nossos antepassados — preserva isto para sempre na mente do Teu povo. Orienta os corações deles na Tua direção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Dá a Salomão, meu filho, o desejo de todo o coração para guardar os Teus mandamentos, os decretos da Tua Aliança e Teus estatutos, e cumprir todos esses planos de construir o palácio para o qual eu tenho feito provisão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Davi disse a toda assembleia: \"Agora, bendiga Yahweh, seu Deus\". Toda a assembleia bendisse a Yahweh, o Deus de seus antepassados; curvaram suas cabeças e adoraram Yahweh e prostraram-se diante do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'No dia seguinte, eles fizeram sacrifícios a Yahweh e ofereceram ofertas queimadas a Ele. Eles ofereceram mil touros, mil carneiros, e mil cordeiros, com suas ofertas de vinho e seus sacrifícios em abundância por todo Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Naquele dia, eles comeram e beberam diante de Yahweh, com grande celebração. Eles fizeram a Salomão, filho de Davi, rei pela segunda vez, e o ungiram com a autoridade de Yahweh para governar. Eles também ungiram Zadoque para ser sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Então, Salomão se assentou no trono de Yahweh, como rei no lugar de seu pai, Davi. Ele prosperou, e todo Israel obedeceu a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Todos os líderes, soldados, e os filhos do rei Davi foram leais ao rei Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Yahweh honrou grandemente a Salomão diante de todo Israel e conferiu a ele maior poder do que jamais havia dado a qualquer rei diante Dele em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Davi, filho de Jessé reinou sobre todo Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Davi foi rei de Israel por quarenta anos. Ele reinou por sete anos em Hebrom e por trinta e três anos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Ele morreu em boa velhice, depois de uma vida longa, com riquezas e honra. Salomão, seu filho, o sucedeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Os feitos do rei Davi estão escritos na história de Samuel, o profeta, na história de Natã, o profeta, e na história de Gade, o profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Lá estão registradas as obras do seu governo, seus feitos e os eventos que afetaram a ele, Israel e todos os reinos das outras terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Salomão, filho de Davi, se fortaleceu no seu governo e Yahweh, seu Deus, era com ele e o engrandeceu muito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Salomão falou a todo o Israel, aos comandantes de mil e de cem, aos juízes, a todo príncipe em todo o Israel e aos chefes das famílias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Então, Salomão e toda a congregação foram ao lugar alto que estava em Gibeão, pois lá estava a Tenda do Encontro de Deus, que Moisés, o servo de Yahweh, fizera no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Mas, Davi tinha levado a Arca de Deus de Quiriate-Jearim para o lugar que tinha preparado, pois ele tinha levantado uma tenda para ela em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Além disso, o altar de bronze que Bezalel, filho de Uri, filho de Ur, tinha feito, estava diante do Tabernáculo de Yahweh; Salomão e a congregação foram até ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Salomão foi até o altar de bronze, diante de Yahweh, que estava na Tenda do Encontro e ofereceu mil sacrifícios sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Deus apareceu a Salomão naquela noite e disse-lhe: \"Pede! O que tu queres?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Salomão disse a Deus: \"Tu mostraste grande aliança de fidelidade para com meu pai, Davi, e me fizestes rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Agora, Deus Yahweh, cumpra-se Tua promessa a Davi meu pai, pois Tu me fizeste rei sobre um povo tão numeroso como o pó da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Agora, dá-me sabedoria e conhecimento, para que eu possa liderar esse povo, pois quem pode julgar Teu povo, que é tão numeroso?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Deus disse a Salomão: \"Porque isso estava em teu coração e porque não pediste por riquezas, bens ou honra, nem pela vida daqueles que te odeiam, nem por uma vida longa para ti, mas porque tu pediste por sabedoria e conhecimento para ti, para que possas governar meu povo, sobre o qual eu te fiz rei, isto é o que te farei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Sabedoria e conhecimento te darei; Eu também lhe darei riquezas, bens, honra, como nenhum rei teve antes de ti e nenhum outro terá, depois de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Então, Salomão saiu de diante da Tenda do Encontro, no lugar alto que estava em Gibeá, veio para Jerusalém e reinou sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Salomão reuniu carros e cavaleiros: e ele tinha mil e quatrocentos carros e doze mil cavaleiros e os colocou nas cidades dos carros e junto de si, em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'O rei fez com que o ouro e a prata se tornassem tão comuns como as pedras em Jerusalém, e ele fez madeira de cedro tão comum como os sicômoros que há nas terras baixas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Quanto às importações de cavalos do Egito e Coa para Salomão seus mercadores compravam de Coa por um preço determinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Eles importavam um carro do Egito por seiscentos siclos de prata, e um cavalo por cento e cinquenta siclos. E também exportavam esses carros e cavalos para os reis dos heteus e arameus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Salomão determinou a construção de uma casa ao nome de Yahweh e a construção de um palácio para seu reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Salomão designou setenta mil homens para o carregamento, oitenta mil homens como cortadores de madeira nas montanhas e três mil e seiscentos homens para os supervisionarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Salomão enviou uma mensagem a Hirão, rei de Tiro, dizendo: \"Assim como tu fizeste com Davi meu pai, enviando-lhe cedros para construir uma casa para morar, faça o mesmo comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Vê, eu vou construir uma casa ao nome de Yahweh, meu Deus, para dedicar a Ele, para queimar diante Dele especiarias de aroma suave, apresentar continuamente o pão da proposição e para queimar ofertas nas manhãs e ao entardecer, aos sábados, nas luas novas e nas festas fixas de Yahweh, nosso Deus. Esta lei será eterna para Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'A casa que construirei será bem grande, porque o nosso Deus é maior que todos os outros deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Mas quem é capaz de construir a Deus uma casa, sendo que o universo inteiro e todo o céu não podem contê-lo? Quem sou eu para lhe construir uma casa, a não ser que seja para queimar sacrifícios?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Então, envia-me um homem que seja habilidoso no trabalho com ouro, prata, bronze, ferro, e tecido púrpura, carmesim e lã azul, um homem que saiba como fazer todo tipo de entalhe em madeira. Ele se juntará aos especialistas que estão comigo em Judá e Jerusalém, os quais meu pai, Davi, providenciou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Me mande também cedro, ciprestes e sândalo do Líbano, pois eu sei que os teus servos sabem como cortar mandeira do Líbano. Vê, meus servos estarão com teus servos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'para preparar para mim madeira em abundância, pois a casa a qual eu estou construindo será grande e maravilhosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Vê, eu darei para teus servos, os homens que cortarão madeira, vinte mil coros de trigo malhado, vinte mil coros de cevada, vinte mil batos de vinho e vinte mil batos de óleo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Então Hirão, o rei de Tiro, respondeu a Salomão: \"Porque Yahweh ama Seu povo, Ele tem te feito rei sobre ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Além disso, Hirão disse: \"Abençoado seja Yahweh, o Deus de Israel, que fez o céu e a terra, que deu a Davi, o rei, um filho sábio, presentando-o com prudência e entendimento, o qual construirá uma casa para Yaweh e uma casa para seu reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Agora, tenho te enviado um homem talentoso, dotado de inteligência, Hurão-Abi, meu especialista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Ele é o filho de uma mulher das filhas de Dã. Seu pai foi um homem de Tiro. Ele é habilidoso para trabalhar com ouro, prata, bronze, ferro, pedra, com madeira e com tecido de púrpura, lãs carmesim e azul, e linho fino. Ele também é talentoso para fazer qualquer tipo de entalhe e também projetos. Coloque-o para trabalhar entre os teus especialistas e também com os trabalhadores do meu senhor, Davi, teu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Agora, então, o trigo e a cevada, o óleo e o vinho, os quais meu senhor havia dito, deixe-me enviar essas coisas a teus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Nós iremos cortar madeira do Líbano, o quanto lhe for necessário. Nós a levaremos por jangadas pelo mar até Jope e tu a transportarás para Jerusalém\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Salomão contou todos os estrangeiros que estavam na terra de Israel, segundo o método que Davi seu pai, já havia feito. Eles encontraram cento e cinquenta e três mil, e seiscentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Ele designou setenta mil dos seus como carregadores, oitenta mil como cortadores de madeira nas montanhas e três mil e seiscentos como supervisores, para fazerem o povo trabalhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Então, Salomão começou a construir a casa de Yahweh em Jerusalém, no monte Moriá, onde Yahweh apareceu a seu pai, Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Ele preparou o lugar que Davi planejou para isto, na eira de Ornã, o jebuseu. Ele começou a construir no segundo dia do segundo mês, no quarto ano do seu reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Estas foram as dimensões da fundação que Salomão colocou para a casa de Deus. Usando o velho estilo de côvado, e eram sessenta côvados de comprimento e vinte côvados de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'O comprimento do pórtico na frente da casa era de vinte côvados, combinando com a largura do prédio. Sua altura também era de vinte côvados, e Salomão revestiu o interior com ouro puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Ele decorou o forro da entrada principal com cipreste, os quais ele revestiu de ouro fino, e entalhou com palmeiras e correntes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Ele decorou a casa com pedras preciosas; o ouro era ouro de Parvaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Ele também revestiu as vigas, batentes, paredes e portas com ouro; ele entalhou querubins nas suas paredes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Também construiu o Lugar Santíssimo. Seu comprimento combinava com a largura da casa, vinte côvados, e sua largura também era de vinte côvados. Revestiu-a com outro fino, totalizando seiscentos talentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'O peso dos pregos eram cinquenta siclos de ouro. Ele revestiu suas superfícies altas com ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Fez duas imagens de querubins para o Lugar Santíssimo; artesãos revestiram-no com ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'As asas dos querubins eram de vinte côvados de comprimento juntas; a asa de um querubim era de cinco côvados de comprimento, alcançando a parede da casa; a outra asa, era da mesma maneira, de cinco côvados de comprimento, alcançando a asa do outro querubim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'A asa do outro querubim também era de cinco côvados, alcançando a parede da casa; sua outra asa também era de cinco côvados, tocando a asa do primeiro querubim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'As asas desses querubins tomavam um total de vinte côvados. Os querubins foram postos de pé, com suas faces viradas à entrada principal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Fez um véu de azul, púrpura, lã de carmesim e linho fino, e ele decorou querubins nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Salomão também fez dois pilares, cada um com trinta e cinco côvados de altura, para a frente da casa; os capitéis que eram no topo deles, cada um, tinha cinco côvados de altura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Fez correntes para os pilares e os colocou no topo deles; ele também fez cem romãs e as juntou as correntes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Colocou os pilares na frente do templo, um ao lado direito, e outro no lado esquerdo; nomeou o pilar da direita de Jaquim, e o pilar da esquerda de Boaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Além disso, fez um altar de bronze de vinte côvados de comprimento e vinte côvados de largura e dez côvados de altura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Fez também um mar de fundição, que media dez côvados de uma borda a outra. A altura tinha cinco côvados e o mar redondo tinha trinta côvados de circunferência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Abaixo das bordas ao redor do mar estavam figuras de bois, dez em cada côvado, fundidas em uma só peça junto com o mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Este mar estava posto sobre doze bois, três olhavam para o norte, três olhavam para o oeste, três olhavam para o sul e três olhavam para o leste. O mar estava posicionado em cima deles, e as partes posteriores estavam voltadas para dentro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'O mar era grosso da largura como de uma mão, e sua borda foi moldada como a borda de um copo, como a flor de um lírio. O mar cabia três mil batos de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Fez também dez pias para lavar coisas; colocou cinco no lado direito e cinco no lado esquerdo; utensílios usados na queima de oferendas eram lavados nelas. O mar, no entanto, era para os sacerdotes se lavarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Fez dez candeeiros de ouro a partir das instruções para o desenho, colocou-os no templo, cinco do lado esquerdo e cinco do lado direito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Fez dez mesas e as colocou no templo, cinco no lado direito e cinco no lado esquerdo. Ele fez cem bacias de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Além disso, fez o pátio dos sacerdotes e o grande pátio, e as portas para o pátio foram revestidas de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Colocou o mar no lado direito da casa, no leste, de frente para o sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Hirão fez os vasos, as pás e as bacias para aspersão. Assim, Hirão completou o trabalho que fez para o rei Salomão na casa de Deus:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'os dois pilares, e os capitéis que estavam no alto dos dois pilares, e os dois conjuntos de treliças decoradas para cobrir os capitéis que estavam em cima dos pilares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'Fez quatrocentas romãs para os dois conjuntos de treliças decoradas: duas fileiras de romãs para cada conjunto de treliça para cobrir os dois capitéis que estavam nos pilares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Também fez bases e bacias para colocar em cima da base,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'um mar e os doze bois debaixo dele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'também os potes, pás, os garfos de carne, e todos os outros utensílios. Hurão-Abi, o habilidoso, fez estes para o rei Salomão, para a casa de Yahweh, de bronze polido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'O rei os fundiu na planície do Jordão, na terra argilosa entre Sucote e Zeredá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Portanto, Salomão fez todos estes utensílios em grande quantidade; de fato, o peso do bronze não pode ser conhecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Salomão fez todos os móveis que estavam na casa de Yahweh, o altar de ouro também, e as mesas onde o pão da presença deveria ser colocado;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'os candeeiros com sua lâmpadas que foram desenhados para queimar diante da sala interior, estes foram feitos com ouro puro;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'e as flores, as lâmpadas e as tenazes, de ouro, ouro puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Também os apagadores, as bacias, colheres, e os queimadores de incenso foram feitos de ouro puro. Quanto a entrada da casa, as portas do interior do Lugar Santíssimo e as portas da casa, que é, do templo, foram feitas de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Quando todo o trabalho que Salomão havia feito para a casa de Yahweh estava terminado, ele trouxe as coisas que Davi, seu pai, havia dedicado para esse propósito, incluindo a prata, o ouro e toda a mobília. Ele os colocou dentro dos armazéns da casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Então, Salomão reuniu em assembleia os anciãos de Israel, todos os chefes das tribos e os líderes das famílias do povo de Israel, em Jerusalém, para trazer a arca da aliança de Yahweh da cidade de Davi, isto é, Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Todos os homens de Israel reuniram-se diante do rei na festa, que aconteceu no sétimo mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Todos os anciãos de Israel vieram e os levitas carregaram a arca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Eles trouxeram a Arca, a Tenda do Encontro e todos os utensílios sagrados que estavam na Tenda. Os sacerdotes da tribo de Levi trouxeram essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'O rei Salomão e toda a assembleia de Israel se reuniram perante a Arca, sacrificando ovelhas e bois que não podiam ser contados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Os sacerdotes trouxeram a Arca da Aliança de Yahweh para o seu lugar, dentro da sala interna da casa, o Lugar Santíssimo, debaixo das asas dos querubins;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'pois os querubins estendiam suas asas sobre o lugar da Arca e cobriram a Arca e suas hastes, pelas quais era carregada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'As hastes eram tão longas que suas extremidades eram vistas do Lugar Santo, em frente da sala interna, mas elas não podiam ser vistas de fora. Elas estão ali até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Não havia nada na Arca, exceto as duas tábuas que Moisés havia colocado em Horebe, quando Yahweh fez uma aliança com o povo de Israel, ao saírem do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Depois disso, todos os sacerdotes saíram do Lugar Santo. Então, todos os sacerdotes que estavam presentes se dedicaram a Yahweh, sem observar a ordem de suas divisões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Também os levitas que eram cantores, todos eles, incluindo Asafe, Hemã, Jedutum, bem como seus filhos e irmãos, vestidos de linho fino e tocando címbalos, harpas e liras, estavam ao lado leste do altar. Com eles estavam cento e vinte sacerdotes soprando trombetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Aconteceu que os que tocavam trombetas e os cantores ministraram juntos, louvando e agradecendo a Yahweh. Eles levantaram suas vozes, com trombetas, címbalos e outros instrumentos, e louvaram a Yahweh. Eles cantaram \"Pois Ele é bom, pois Sua lealdade à Aliança dura para sempre.\" Então, a casa de Yahweh se encheu com uma nuvem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Os sacerdotes não puderam permanecer em pé para servir, por causa da nuvem, pois a glória de Yahweh encheu a Casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Então Salomão disse: \"Yahweh disse que moraria em densa escuridão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'mas eu tenho construído uma residência exaltada para Ti, um lugar em que habitarás para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Então, o rei virou-se e abençoou toda a assembleia de Israel, enquanto toda a assembléia de Israel estava de pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Ele disse: \"Que Yahweh, o Deus de Israel, seja louvado, Aquele que falou a Davi, meu pai, e cumpriu Sua palavra com Suas próprias mãos, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, '\'Desde o dia que Eu trouxe Meu povo da terra do Egito, Eu não escolhi nenhuma cidade, de todas as tribos de Israel, para construir uma casa, a fim de que Meu nome esteja ali. Tampouco, escolhi qualquer homem para ser príncipe sobre Meu povo Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Porém, Eu tenho escolhido Jerusalém, para que Meu nome possa estar lá e Eu escolhi Davi para ficar sobre Meu povo, Israel.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Agora, estava no coração de Davi, meu pai, construir uma casa para o nome de Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Mas Yahweh disse a Davi, meu pai: \'Já que estava no teu coração construir uma casa para o Meu nome, bem fizeste de ter isso no teu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Mesmo assim, não deverás construir a casa; ao invés disso, teu filho, que virá de ti, construirá a casa para o Meu nome\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Yahweh cumpriu a palavra que Ele disse, pois a construí, em lugar de Davi, meu pai, e eu sento no trono de Israel, como Yahweh prometeu. Eu construí a casa para o nome de Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Eu coloquei a Arca ali, onde está a Aliança de Yahweh, que Ele fez com o povo de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Salomão ficou em pé diante do altar de Yahweh na presença de toda a assembleia de Israel, e estendeu suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Pois ele havia feito uma plataforma de bronze, de cinco côvados de comprimento, cinco de largura e três de altura. Ele a tinha posto no meio do pátio. Subiu nela, ajoelhou-se diante de toda a assembleia de Israel e, então, estendeu suas mãos para os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'Ele disse: \"Yahweh, Deus de Israel, não há outro Deus como Tu, nem nos céus e nem na terra, que guardas Tua Aliança e Tua benignidade com Teus servos que andam diante de Ti com todo o coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Tu que guardaste a promessa que fizeste ao Teu servo Davi, meu pai. Sim, Tu falaste com Tua boca e cumpriste com Tua mão, como é hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Agora, então, Yahweh, Deus de Israel, cumpra o que prometeste ao Teu servo Davi, meu pai, quando Tu disseste: \'Tu não falharás em ter um homem diante de minha vista, para sentar-se no trono de Israel; se apenas seus descendentes tiverem cuidado em andar na Minha lei como tu tens andado diante de Mim.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Agora, então, Deus de Israel, eu oro para que a promessa que fizeste ao Teu servo Davi se torne realidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Mas Deus morará mesmo com a humanidade na terra? Veja, o universo inteiro e nem mesmo os céus podem conter-Te, muito menos este templo que construí!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Por favor, considera esta oração de Teu servo e seu pedido, Yahweh, meu Deus; ouve o clamor e a oração que Teu servo ora diante de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Que Teus olhos possam se abrir dia e noite para este templo, para o lugar em que Tu prometeste colocar o Teu nome. Tu podes ouvir a oração que Teu servo ora para este lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Ouve as solicitações do Teu servo e do Teu povo, Israel; quando orarmos em direção a este lugar. Sim, ouve do lugar onde moras, dos céus; e, quando ouvires, perdoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Se um homem pecar contra seu vizinho e for requerido dele fazer um juramento, e se ele vier e fizer um juramento diante de Teu altar nesta casa;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'ouve dos céus, age e julga Teus servos, devolvendo a quem é mal, para trazer sua conduta sobre sua própria cabeça. Declara os justos inocentes, para dar-lhes a recompensa por sua justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Quando o Teu povo Israel for derrotado pelo inimigo, porque eles pecaram contra Ti, — se eles retornarem a Ti, confessarem o Teu nome, orarem e pedirem perdão diante de Ti neste templo —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'então, por favor, ouve dos céus e perdoa os pecados de Teu povo Israel; traze-os de volta para a terra que deste a eles e a seus ancestrais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Quando os céus estiverem fechados e não houver chuva, porque o povo pecou contra Ti, — se eles orarem, voltados para este lugar, confessarem o Teu nome, e converterem-se de seu pecado, quando Tu os afligires —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'então, ouça nos céus a perdoa o pecado dos Teus servos e do Teu povo, Israel; quando Tu os direcionares no bom caminho no qual devem andar. Manda chuva na Tua terra, que deste ao Teu povo como herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Suponha que haja fome na terra ou que haja doença, ferrugem ou mofo, gafanhotos ou lagartas; ou suponha que seus inimigos ataquem os portões da cidade em sua terra, ou que haja qualquer praga ou enfermidade;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'suponha, então, que orações e pedidos sejam feitos por uma pessoa ou por todo o Teu povo de Israel — cada um sabendo a praga e a tristeza em seu próprio coração enquanto estende suas mãos para este templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Então, ouça do céu, o lugar onde moras; perdoa e restitua a cada pessoa segundo os seus caminhos. Tu conheces seu coração, porque Tu, e somente Tu, conheces os corações do seres humanos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Faze isso para que eles temam a Ti, para que possam andar em Teus caminhos todos os dias que viverem na terra que Tu deste aos nossos antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Quanto ao estrangeiro, que não pertence ao Teu povo, Israel, mas que — por causa de Teu grande nome, Tua mão poderosa e Teu braço erguido — vier e orar em direção a esta casa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'então, por favor, ouve dos céus, o lugar onde moras, e faze conforme tudo o que o estrangeiro pedir a Ti, para que todo o povo da terra possa conhecer o Teu nome e temer a Ti, assim como o Teu povo, Israel, e para que eles possam saber que esta casa que eu construí é chamada pelo Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Suponha que Teu povo vá a batalha contra seus inimigos, por qualquer caminho que possa mandar-lhes; e suponha que eles orem a Ti em direção a esta cidade que escolhestes e em direção a esta casa que construí em Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Então, ouve, dos céus, suas orações, suas súplicas e ajuda suas causas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Suponha que eles pequem contra Ti — já que não há ninguém que não peque — e suponha que Tu estejas bravo com eles e entregue-os ao inimigo, para que o inimigo os leve e os tome como cativos de suas terras, sejam elas distantes ou próximas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'Então, suponha que eles percebam que estão na terra para onde foram levados em exílio; e suponha que eles se arrependam e busquem o Teu favor na terra para qual foram levados em cativeiro. Suponha que digam: \'Nós agimos de forma perversa e pecamos. Nós agimos com maldade.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'Suponha que eles retornem a Ti com todo seu coração e com toda sua alma na terra de seu cativeiro, para onde eles foram levados cativos, e suponha que eles orem na direção da terra que lhes pertence, a qual Tu deste aos seus antepassados, e em direção à cidade que Tu escolheste, e em direção à casa que construí para o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Então, ouve dos céus, o lugar onde moras, a sua oração e as suas súplicas e ajuda sua causa. Perdoa Teu povo, que pecou contra Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Agora, meu Deus, eu imploro a Ti: abre os Teus olhos e mantém os Teus ouvidos atentos à oração que é feita neste lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Agora, então, levanta Deus Yahweh para o lugar de descanso teu e da Arca da Tua força. Deixa Teus sacerdotes, Deus Yahweh, serem vestidos com salvação e deixa Teus santos regozijarem-se em Tua bondade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Deus Yahweh não desvie a face de Teu ungido de Ti. Guarde em Teus pensamentos as Tuas ações de Aliança leal para com Davi, Teu servo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Quando Salomão terminou sua oração, fogo desceu dos céus e consumiu os holocaustos e sacrifícios, e a glória de Yahweh encheu a Casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Os sacerdotes não podiam entrar na casa de Yahweh, porque a Sua glória encheu Sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Todas as pessoas de Israel olhavam enquanto o fogo descia, e a glória de Yahweh estava sobre a Casa. Eles prostaram-se com o rosto no chão, sobre o pavimento de pedra, adoraram e deram graças a Yahweh; eles disseram: \"Porque Ele é bom, porque Sua aliança de lealdade dura para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Então, o rei e todo o povo ofereceram sacrifícios para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'O rei Salomão ofereceu um sacrifício de vinte e dois mil bois e cento e vinte mil ovelhas e bodes. Assim, o rei e todo o povo consagraram a casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Os sacerdotes ficaram de pé, cada um no lugar onde servia; os levitas também, com instrumentos de música a Yahweh, os quais Davi, o rei, havia feito para dar graças a Yahweh na canção \"Pois Sua aliança de lealdade dura para sempre\". Todos os sacerdotes soaram as trombetas diante deles, e todo o Israel ficou de pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Salomão consagrou o meio do pátio em frente à casa de Yahweh. Lá, ele ofereceu as ofertas queimadas e a gordura das ofertas pacíficas, porque o altar de bronze que ele havia feito não foi capaz de suportar as ofertas queimadas, as ofertas de cereais, e a gordura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Assim, Salomão manteve, naquele tempo, as festas por sete dias, e todo o Israel estava com ele, uma grande assembleia, desde Lebo-Hamate até o ribeiro do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'No oitavo dia, eles realizaram a congregação solene porque mantiveram a consagração do altar por sete dias, e a festa por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'No vigésimo terceiro dia do sétimo mês, Salomão enviou as pessoas para suas casas com os corações contentes e cheios de alegria por causa da bondade que Yahweh havia mostrado a Davi, Salomão e a Israel, Seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Assim, Salomão terminou a casa de Yahweh e sua própria casa. Todas as coisas que vieram ao coração de Salomão para fazer na casa de Yahweh e na sua própria, ele completou com sucesso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Yahweh apareceu a Salomão à noite, dizendo: \"Eu ouvi tua oração, e Eu escolhi este lugar para Mim mesmo como uma casa de sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Se Eu fechar os céus e não houver chuva, ou se Eu ordenar aos gafanhotos que devorem a terra, ou se Eu mandar doenças no meio do Meu povo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'então, se Meu povo, que é chamado pelo Meu Nome, se humilhar, orar, buscar a Minha face, e se voltar de seu mau caminho, Eu ouvirei do céu, perdoarei seu pecado e sararei sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Agora, Meus olhos estarão abertos e Meus ouvidos atentos para as orações feitas neste lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Pois Eu tenho escolhido e dedicado esta casa para que Meu Nome esteja lá para sempre, e Meus olhos e Meu coração estarão lá todo o tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'No que se refere a ti, se andares diante de Mim, como Davi, teu pai, andou, obedecendo a tudo que Eu te ordenei e guardando Meus estatutos e Meus decretos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'então, estabelecerei o trono do teu reino, como Eu disse na aliança com Davi, teu pai, quando Eu disse: \'Um descendente teu nunca deixará de reinar em Israel\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Mas, se vos afastardes e abandonardes Meus estatutos e Meus mandamentos que coloquei diante de vós, e se fordes e adorardes outros deuses e vos curvardes diante deles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'então, Eu vos arrancarei da Minha terra que Eu vos dei. Esta Casa que Eu tenho dedicado para Meu Nome, vou lançar para longe de Mim, e farei com que isto seja um provérbio e uma piada no meio de todos os povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'E, mesmo que este templo seja tão exaltado agora, todos os que passarem por ele ficarão chocados, e perguntarão: \'Por que Yahweh fez isto com esta terra e com esta Casa?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Outros responderão: \'Porque eles abandonaram Yahweh, seu Deus, que tirou seus ancestrais da terra do Egito, e se apegaram a outros deuses, e se curvaram a eles e os adoraram. Essa é a razão pela qual Yahweh trouxe todo esse desastre sobre eles\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Aconteceu que, ao final de vinte anos, durante os quais Salomão construiu a casa de Yahweh e sua própria casa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Salomão reconstruiu as cidades que Hirão deu a ele, e fez o povo de Israel viver ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Salomão atacou Hama-Zobá e a derrotou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Ele construiu Tadmor no deserto, e todas as cidades armazéns em Hamate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Também construiu Bete-Horom, a alta, e Bete-Horom, a baixa, cidades fortificadas com muros, portões e ferrolhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Ele construiu Baalate e todas as cidades armazéns que possuía, e todas as cidades para seus carros e as cidades para seus cavaleiros, e tudo que quis construir para seu prazer em Jerusalém, no Líbano e em todas as terras sob seu domínio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Quanto a todas as pessoas que sobraram dos heteus, dos amorreus, dos perizeus, dos heveus e dos jebuseus, que não pertenciam a Israel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'seus descendentes que haviam ficado na terra depois deles, que o povo de Israel não destruiu, Salomão fez deles trabalhadores forçados, o que são até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Entretanto, Salomão não fez do povo de Israel trabalhadores forçados; ao invés disso, eles se tornaram seus soldados, seus comandantes, seus oficiais e comandantes da cavalaria e seus cavaleiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Esses foram também os oficiais comandantes que dirigiam os encarregados do rei Salomão — duzentos e cinquenta deles —, que supervisionavam o povo que fazia o trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Salomão tirou a filha do Faraó da cidade de Davi, e levou para a casa que ele havia construído para ela, pois disse: \"Minha esposa não deve viver na casa de Davi, rei de Israel, porque onde quer que a arca de Yahweh esteve é santo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Então, Salomão ofereceu holocaustos a Yahweh em Seu altar, que ele construiu em frente ao pórtico.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Ele ofereceu sacrifícios de acordo com a programação diária requerida; ele os ofereceu segundo as orientações encontradas nos mandamentos de Moisés sobre o Sábado, as luas novas e as festas fixas, três vezes a cada ano: a festa dos Pães Sem Fermento, a festa das Semanas e a festa dos Cabanas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Seguindo os decretos de Davi, seu pai, Salomão designou as divisões dos trabalhos dos sacerdotes, e as posições dos levitas para louvar a Deus e para servir diante dos sacerdotes, de acordo com a programação diária requerida. Ele também designou os porteiros de acordo com suas divisões em cada portão, pois Davi, o homem de Deus, também havia ordenado isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Essas pessoas não se desviaram das ordens do rei aos sacerdotes e levitas, em relação a qualquer coisa, ou concernente aos armazéns.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Todo o trabalho ordenado por Salomão foi realizado, do dia da fundação da casa de Yahweh até a sua conclusão — a casa de Yahweh foi concluída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Então, Salomão foi a Eziom-Geber e a Elate, na costa da terra do Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Hirão lhe mandou navios comandados por oficiais que entendiam do mar; eles foram para Ofir, com os servos de Salomão; de lá eles trouxeram quatrocentos e cinquenta talentos de ouro para o rei Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Quando a rainha de Sabá ouviu sobre a fama de Salomão, ela veio até Jerusalém para testá-lo com perguntas difíceis. Veio com grande caravana, com camelos carregados de especiarias, muito ouro e pedras preciosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Quando chegou até Salomão, ela lhe contou tudo o que estava em seu coração. Salomão lhe respondeu todas as perguntas; nenhuma pergunta era tão difícil para Salomão; não houve pergunta que ele não respondesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Quando a rainha de Sabá viu a sabedoria de Salomão, o palácio que ele construíu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'a comida em sua mesa, o assento de seus servos, o trabalho de seus servos, os trajes deles, seus copeiros, os trajes deles e a maneira como ele oferecia holocausto na Casa de Yahweh, ela ficou como que fora de si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Ela disse ao rei: \"É verdadeiro o relato que ouvi em minha própria terra sobre tuas palavras e tua sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Não acreditei no que ouvi até chegar aqui, e agora meus olhos têm visto. Nem a metade da tua grandeza e sabedoria me foi dita! Ultrapassaste a fama que ouvi sobre ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Quão abençoado são o teu povo e teus servos que, constantemente, estão diante de ti e ouvem a tua sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Bendito seja Yahweh, teu Deus, o qual tomou prazer em ti e te colocou em Seu trono, para ser rei para Yahweh, teu Deus. Porque teu Deus amou Israel para o estabelecer para sempre, Ele te fez rei sobre eles, para que fizesses juízo e justiça!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Ela deu ao rei cento e vinte talentos de ouro e uma grande quantidade de especiarias e pedras preciosas. E jamais foi dada a Salomão tamanha quantidade de especiarias como a que a rainha de Sabá lhe deu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Os servos de Hirão e os servos de Salomão, que trouxeram ouro de Ofir, também trouxeram madeira de sândalo e pedras preciosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Com a madeira, o rei fez degraus para a casa de Yahweh e para sua casa, assim como harpas e liras para os músicos. Nenhuma madeira como esta havia sido vista antes, na terra de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'O rei Salomão deu à rainha de Sabá tudo que ela desejou, tudo que ela pediu, mais do que ela trouxe ao rei. Então, ela e seus servos retornaram à sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Ora, o peso do ouro que trouxeram a Salomão, em um ano, foi de seiscentos e sessenta e seis talentos de ouro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'fora o ouro que os negociantes e mercadores trouxeram. Todos os reinos da Arábia e os governadores dos países também trouxeram ouro e prata a Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'O rei Salomão fez duzentos grandes escudos de ouro batido, cada um deles tinha seiscentos siclos de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Fez também trezentos escudos de ouro batido, cada um com trezentos siclos de ouro, e o rei os colocou no palácio do bosque do Líbano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Então, o rei fez um grande trono de marfim e o revestiu com o mais fino ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Havia seis degraus até o trono, e a parte de cima do trono era arredondada atrás. Havia braços em cada lado do assento, e dois leões ficavam ao lado dos braços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Doze leões ficavam nos degraus, um em cada lado dos seis degraus. Não havia um trono como este em nenhum outro reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Todas as taças do rei Salomão eram de ouro, e todos as taças do palácio do bosque do Líbano eram de ouro puro. Nenhuma era de prata, porque a prata não era considerada valiosa nos dias de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'O rei tinha ao mar uma frota de navios oceânicos, juntamente com a frota de Hirão. A cada três anos, a frota trazia ouro, prata, marfim, assim como macacos e pavões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Então, o rei Salomão excedeu a todos os reis da terra, tanto em riqueza como em sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Toda a terra buscava a presença de Salomão para ouvir sua sabedoria, que Deus havia colocado em seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Aqueles que o visitavam traziam tributos, utensílios de prata e de ouro, vestes, armaduras, especiarias, assim como cavalos e mulas, ano após ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Salomão tinha quatro mil estábulos para cavalos e carros e doze mil cavaleiros, os quais ele distribuiu nas cidades dos carros e consigo mesmo, em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Ele dominava sobre todos os reis, desde o rio Eufrates à terra dos filisteus e até a fronteira do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'O rei tinha prata em Jerusalém, tanto quanto as pedras no chão. Fez o cedro ser tão abundante quanto as figueiras de sicômoros que estão nas planícies.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Trouxeram cavalos a Salomão, do Egito e de todas as terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Quanto aos outros atos de Salomão, os primeiros e os últimos, porventura, não estão escritos no livro da história de Natã, o profeta, na profecia de Aías, o silonita e nas visões de Ito, o vidente, acerca de Jeroboão, filho de Nebate?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Salomão reinou em Jerusalém, sobre todo Israel por quarenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Ele descansou com seus antepassados, e o sepultaram na cidade de Davi, seu pai; Roboão, seu filho, se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Roboão foi para Siquém, pois todo o Israel estava indo até lá para fazê-lo rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Aconteceu que Jeroboão, filho de Nebate, ouviu sobre isso e voltou do Egito (pois tinha ido para lá, fugindo da presença do rei Salomão).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Então, eles mandaram chamá-lo. Jeroboão e todo o Israel foram, falaram com Roboão e disseram:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '\"Teu pai fez nosso jugo difícil. Agora, faz com que o trabalho pesado de teu pai seja fácil, alivia o jugo pesado que ele colocou em nós, e nós te serviremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Roboão lhes disse: \"Voltai a mim depois de três dias\". Então, o povo saiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'O rei Roboão consultou os anciãos que estiveram perante Salomão, seu pai, quando ele ainda vivia. Ele disse: \"Como me aconselharíeis a dar uma resposta a esse povo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Eles lhe disseram: \"Se tu fores bom para com esse povo, o agradares e disseres boas palavras a eles, então eles sempre serão teus servos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Roboão, porém, ignorou o conselho que os anciãos tinham lhe dado e consultou os jovens que cresceram com ele e que estiveram perante ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Ele lhes disse: \"Que conselho me daríeis para que possamos responder ao povo que falou comigo e me disse: \'Alivia o jugo que teu pai colocou sobre nós\'?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Os jovens que cresceram com Roboão disseram: \"Isso falarás ao povo que disse que teu pai, Salomão, fez pesado o jugo sobre eles, mas que tu deverias fazê-lo mais leve. Dize-lhes: \'Meu dedo mínimo é mais grosso que a cintura do meu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Agora, no entanto, se a carga de meu pai foi um jugo pesado, eu irei aumentá-lo. Meu pai vos puniu com açoites, porém eu vos punirei com escorpiões\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Então, Jeroboão e todo o povo vieram a Roboão no terceiro dia, como o rei instruíra, dizendo: \"Voltai a mim no terceiro dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Roboão lhes respondeu rudemente, ignorando o conselho dos anciãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'Ele lhes falou, seguindo o conselho dos jovens: \"Meu pai fez pesado o vosso jugo, mas eu irei aumentá-lo. Meu pai vos puniu com açoites, porém eu vos punirei com escorpiões\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Assim, o rei não ouviu ao povo; pois essa mudança nos acontecimentos vinha de Deus, a fim de que Yahweh cumprisse a Sua palavra, que Aías, o silonita, falara a Jeroboão, filho de Nebate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Quando todo o Israel viu que o rei não os ouvia, o povo lhe respondeu, dizendo: \"Que parte temos nós com Davi? Não temos nós herança com o filho de Jessé! Cada um de vós deve voltar à sua própria tenda, Israel. Agora, vê a tua própria casa, Davi\". Então, todo o Israel retornou para suas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Mas, quanto ao povo de Israel que habitava nas cidades de Judá, Roboão reinou sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Então, o rei Roboão enviou Adorão, que era encarregado dos trabalhos forçados, porém o povo de Israel o apedrejou até a morte. O rei Roboão fugiu rapidamente, em sua carruagem, para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Então, Israel se rebelou contra a casa de Davi até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Quando Roboão chegou a Jerusalém, ele convocou as casas de Judá e Benjamim para lutar contra Israel, cento e oitenta mil homens que eram soldados, a fim de reconquistar o domínio para Roboão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Mas veio a palavra de Yahweh a Semaías, o homem de Deus, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, '\"Fala ao rei de Judá, Roboão, filho de Salomão, e a todo o Israel em Judá e Benjamim:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, '\'Yahweh diz: Tu não deves atacar ou fazer guerra contra teus irmãos. Cada homem deve retornar à sua casa, pois por minha vontade isso aconteceu.\'\". Assim, eles obedeceram às palavras de Yahweh e desistiram de atacar Jeroboão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Roboão viveu em Jerusalém e construiu cidades em Judá para defesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Ele fortificou Belém, Etã, Tecoa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Bete-Zur, Socó, Adulão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gate, Maressa, Zife,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraim, Laquis, Azeca,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Zorá, Aijalom e Hebrom. Essas são as cidades fortificadas em Judá e em Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Ele reforçou as fortalezas e pôs comandantes nelas, com armazéns para a provisão de azeite e de vinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Ele colocou escudos e lanças em cada cidade e edificou as cidades fortemente. Então, Judá e Benjamim lhe pertenceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Os sacerdotes e os levitas que estavam em todo o Israel vieram ter com ele dentro de suas fronteiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Os levitas deixaram seus pastos e propriedades, a fim de vir para Judá e Jerusalém, pois Jeroboão e seus filhos os tinham expulsado para longe, para que eles não pudessem mais exercer seus deveres sacerdotais para com Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Jeroboão designou para si sacerdotes para os altares dos lugares altos e fez ídolos nas formas de bezerro e de cabra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Pessoas de todas as tribos de Israel, aqueles que haviam colocado em seus corações buscar Yahweh, o Deus de Israel, seguiram os sacerdotes e vieram até Jerusalém para sacrificar a Yahweh, o Deus de seus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Assim, eles fortaleceram o reino de Judá e fizeram Roboão, filho de Salomão, forte, durante três anos, pois eles seguiram, por três anos, o caminho de Davi e Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Roboão tomou como esposa Maalate, filha de Jeremote, filho de Davi com Abiail, filha de Eliabe, filho de Jessé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Maalate lhe deu filhos: Jeús, Semarias e Zaão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Depois de Maalate, Roboão tomou Maacá, filha de Absalão. Ela lhe deu filhos: Abias, Atai, Ziza e Selomite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Roboão amava Maacá, filha de Absalão, mais que todas as suas outras esposas e concubinas (ele tomou dezoito mulheres e sessenta concubinas e tornou-se pai de vinte e oito filhos e sessenta filhas).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Roboão designou Abias, filho de Maacá para ser chefe, um líder entre seus irmãos; ele pretendia fazê-lo rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Roboão decidiu sabiamente: ele espalhou todos os seus filhos pela terra de Judá e de Benjamim, em cada cidade fortificada. Ele também lhes deu suprimentos em abundância e procurou muitas esposas para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Aconteceu que, quando o reinado de Roboão estava consolidado e no auge do poder, ele abandonou as leis de Yahweh e todo o Israel com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'No quinto ano do reinado de Roboão, o rei do Egito, Sisaque, subiu para atacar Jerusalém, isso por causa da infidelidade do povo para com Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Ele veio com mil e duzentas carruagens e sessenta mil cavaleiros; as tropas que vinham do Egito eram incontáveis, compostas de: líbios, suquitas e etíopes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Ele conquistou as cidades fortificadas de Judá e alcançou Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Então, o profeta, Semaías, veio a Roboão e aos líderes de Judá que estavam reunidos em Jerusalém por causa de Sisaque. Semaías falou: \"Assim diz Yahweh: \'Porque vós abandonastes a Mim, Eu vos entreguo nas mãos de Sisaque\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Assim, os princípes de Israel e o rei se humilharam e disseram: \"Yahweh é justo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Quando Yahweh viu que eles se humilharam, a palavra de Yahweh veio a Semaías, dizendo: \"Porque eles se humilharam, não mais os destruirei, Eu os pouparei parcialmente; isto é, a minha ira não será derramada sobre Jerusalém pelas mãos de Sisaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Porém, eles serão seus servos, para aprenderem a diferença entre servir Mim e servir a reinos estrangeiros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Dessa forma, Sisaque, rei do Egito, atacou Jerusalém e apoderou-se dos tesouros da casa de Yahweh, e dos tesouros da casa do rei. Ele levou tudo, inclusive os escudos de ouro feitos por Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Para substituí-los, então, o rei Roboão mandou fazer escudos de bronze, e confiou-os nas mãos dos capitães da guarda, que cuidavam das portas da casa do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Toda vez que o rei dirigia-se à casa de Yahweh, vinham os guardas levando os escudos; depois os depositavam na casa dos guardas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Por ter Roboão se humilhado, a ira de Yahweh desviou-se dele, para não destruí-lo completamente. Além disso, em Judá, ainda havia algo bom a ser encontrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Assim, o rei Jeroboão, reinou e fortaleceu seu reinado em Jerusalém. Roboão tinha quarenta e um anos quando começou a reinar. O nome da sua mãe era Naamá, a amonita. Ele reinou durante dezessete anos em Jerusalém, a cidade que Yahweh escolheu dentre todas as tribos de Israel, para ali colocar o Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Ele praticou o que era mau, porque não dispôs o coração para buscar a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Quanto aos demais assuntos, relacionados a Roboão, do começo ao fim, acaso não estão nas crônicas escritas por Semaías, o profeta, e por Ido, o vidente, que também registram as genealogias e as constantes guerras entre Roboão e Jeroboão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Roboão morreu e foi sepuldado na cidade de Davi, junto com seus pais. Abias, seu filho, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'No décimo oitavo ano do rei Jeroboão, Abias começou a reinar sobre Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Ele governou por três anos em Jerusalém; o nome de sua mãe era Micaías, filha de Uriel, de Gibeá. Houve guerra entre Abias e Jeroboão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Abias entrou na batalha com um exército de soldados corajosos e fortes; eram quatrocentos mil homens escolhidos. Jeroboão preparou as linhas de batalha contra ele com oitocentos mil homens escolhidos, soldados corajosos e fortes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Abias ficou no monte Zemaraim, que fica na região montanhosa de Efraim, e disse: \"Escutai-me, Jeroboão e todo o Israel!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Não sabeis que Yahweh, o Deus de Israel, deu a Davi o reinado sobre Israel para sempre, para ele e para os seus filhos através de uma Aliança formal?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Porém, Jeroboão, filho de Nebate, servo de Salomão, filho de Davi, se levantou e se rebelou contra seu senhor;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'a ele se juntaram homens desocupados e perversos. Eles vieram contra Roboão, filho de Salomão, que era jovem e inexperiente e não poderia lhes resistir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Agora, vós dizeis que podeis resistir ao governo poderoso de Yahweh, que está nas mãos dos filhos de Davi. Vós sois um grande exército, e tendes convosco os bezerros de ouro que Jeroboão fez como deuses para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Não expulsastes os sacerdotes de Yahweh, os descendentes de Arão e os levitas? Não fizestes para vós sacerdotes semelhantes aos povos das outras terras? Quem quer que venha e se consagre com um novilho e sete carneiros pode tornar-se sacerdote dos que não são deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Mas, quanto a nós, Yahweh é nosso Deus, e nós não O abandonamos. Nós temos sacerdotes, descendentes de Arão, servindo Yahweh, e os levitas, que estão no Seu trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Todas as manhãs e todas as tardes eles oferecem a Yahweh ofertas queimadas e incensos aromáticos. Eles também organizam o pão sobre a mesa purificada cerimonialmente, e acendem o candelabro de ouro com as suas lâmpadas para queimarem toda tarde. Nós guardamos os mandamentos de Yahweh, nosso Deus, mas vós o deixastes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Deus está conosco, à nossa frente, e os seus sacerdotes estão aqui com as suas trombetas para soar o alarme contra vós. Povo de Israel, não luteis contra Yahweh, o Deus dos vossos antepassados, pois vós não tereis sucesso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Mas Jeroboão preparou uma emboscada por trás deles; seu exército estava à frente de Judá, e a emboscada estava atrás deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Quando Judá olhou novamente, o combate estava adiante e a retaguarda deles. Eles clamaram a Yahweh, e os sacerdotes tocaram as trombetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Então, os homens de Judá gritaram e enquanto eles gritavam, aconteceu que, Deus feriu Jeroboão e todo o Israel diante de Abias e Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'O povo de Israel fugiu de Judá, pois Deus os entregou em suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Abias e seu exército realizaram um grande massacre, e quinhentos mil homens escolhidos de Israel morreram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Dessa maneira, o povo de Israel foi derrotado naquele tempo; o povo de Judá venceu porque eles confiaram em Yahweh, Deus de seus ancestrais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Abias perseguiu Jeroboão e tomou cidades dele: Betel, Jesana e Efrom com suas respectivas vilas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Jeroboão não recuperou poder novamente durante todos os dias de Abias; Yahweh feriu Jeroboão e ele morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Abias, porém, se tornou poderoso; ele tomou para si catorze mulheres e tornou-se o pai de vinte e dois filhos e dezesseis filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'O restante dos feitos de Abias, seus atos e palavras, estão escritos no livro da história do profeta Ido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Abias descansou com seus antepassados, e eles o enterraram na cidade de Davi. Asa, seu filho, se tornou rei em seu lugar. Em seus dias a terra esteve em paz por dez anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Asa fez o que era bom e certo aos olhos de Yahweh, seu Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'pois ele removeu os altares estrangeiros e os lugares altos; ele derrubou as colunas de pedra e cortou os postes de Aserá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Ele ordenou Judá a buscar Yahweh, o Deus de seus antepassados, e a obedecer as leis e os mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Ele também removeu de todas as cidades de Judá os lugares altos e altares de incenso. O reino estava em paz sob seu governo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Ele construiu cidades fortificadas em Judá, pois a terra estava em paz, e ele não teve guerra naqueles anos, pois Yahweh deu-lhe paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Asa disse a Judá: \"Vamos construir estas cidades e fazer muros ao redor delas, torres, portões e trancas; a terra ainda é nossa, pois nós buscamos Yahweh, nosso Deus. Nós O buscamos, e Ele nos deu paz de todos os lados\". Então eles construíram e tiveram êxito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Asa tinha um exército que carregava escudos e lanças; de Judá ele tinha trezentos mil homens, e de Benjamim, duzentos e oitenta mil homens que carregavam escudos e atiravam com arcos. Todos esses eram homens corajosos e fortes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Zerá, o etíope, veio contra eles com um exército de um milhão de soldados e trezentas carruagens, e chegou a Maressa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Então, Asa foi ao encontro dele, e eles estabeleceram as linhas de batalha no vale de Zefatá em Maressa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Asa clamou a Yahweh, seu Deus, e disse: \"Yahweh, não existe ninguém como Tu para socorrer os que não tem força, quando este está diante de muitos. Ajuda-nos, Yahweh, nosso Deus, pois confiamos em Ti, e em Teu nome viemos contra esse imenso número. Yahweh, Tu és nosso Deus; não deixa nenhum homem derrotar-Te\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Então, Yahweh derrotou os etíopes diante de Asa e Judá; e os etíopes fugiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Asa, e os seus soldados, os perseguiram até Gerar. Caíram tantos etíopes que eles não puderam se recuperar, pois eles foram completamente destruídos diante de Yahweh e de Seu exército. O exército recolheu muito despojo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'O exército destruiu todas as vilas ao redor de Gerar, pois o terror de Yahweh veio sobre os habitantes. Também saqueou todas as vilas, pois havia muito despojo nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'O exército também destruiu as tendas nômades; eles levaram ovelhas em abundância, assim como camelos, e, então, eles retornaram a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'O Espírito de Deus veio a Azarias, filho de Odede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Ele saiu ao encontro de Asa e lhe disse: \"Ouvi-me, Asa, toda Judá e Benjamim: Yahweh é convosco, enquanto vós permanecerdes com Ele. Se vós, O buscardes, Ele será encontrado por vós; mas, se vós o abandonardes, Ele vos abandonará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Ora, por um longo período, Israel estava sem o Deus verdadeiro, sem um sacerdote que os ensinasse, e sem a Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Mas, em sua angústia eles se voltaram para Yahweh, o Deus de Israel, e O buscaram, Ele foi encontrado por eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Naqueles dias, não havia paz para os que saíam, nem para os que chegavam, em vez disso, grandes perturbações estavam sobre todos os habitantes das terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Eles estavam se despedaçando, nação contra nação, e cidade contra cidade, pois Deus os aflingiu com todos os tipos de sofrimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Mas, sede fortes e não deixeis que vossas mãos se cansem, pois o vosso trabalho será recompensado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Quando Asa ouviu essas palavras, a profecia de Odede, o profeta, tomou coragem e se desfez de todas as coisas repugnantes da terra de Judá e Benjamim, e das cidades que ele havia conquistado da região montanhosa de Efraim; reconstruiu o altar de Yahweh, que estava em frente ao pórtico da Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Ele reuniu todo o Judá e Benjamim, e todos os que ficaram com eles, de Efraim, Manassés e de Simeão. Eles vieram de Israel a ele em grande número, quando eles viram que Yahweh, seu Deus, estava com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Então, se reuniram em Jerusalém no terceiro mês, no décimo quinto ano do reinado de Asa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Eles sacrificaram a Yahweh naquele dia alguns dos despojos que eles trouxeram: setecentos bois e sete mil ovelhas e cabras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Eles entraram em aliança para buscar Yahweh, o Deus de seus antepassados, de todo seu coração e de toda sua alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'Eles concordaram que todo aquele que se recusasse a buscar Yahweh, o Deus de Israel, deveria ser morto, tanto pequeno como grande, tanto homem como mulher.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Eles juraram a Yahweh em alta voz, com júbilos, com trombetas e cornetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Todos de Judá se alegraram com o juramento, pois eles tinham jurado de todo coração, e eles buscaram a Deus com toda vontade, e Ele foi achado por eles. Yahweh deu-lhes paz a todos ao seu redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Ele também removeu Maacá, sua avó, de ser rainha, porque ela tinha feito uma imagem repugnante de Astarote. Asa destruiu a imagem repugnante, a reduziu a pó e a queimou junto ao ribeiro de Cedrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Porém, os lugares altos não foram retirados de Israel. No entanto, o coração de Asa foi totalmente devoto todos os seus dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Ele trouxe até a Casa de Deus as coisas de seu pai e suas próprias coisas que pertenciam a Yahweh: objetos de prata e ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Não houve mais guerra até o trigésimo quinto ano do reinado de Asa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'No trigésimo sexto ano do reinado de Asa, sendo Baasa o rei de Israel, este invadiu Judá e fortificou Ramá, para que ninguém pudesse sair do território de Asa, rei de Judá, ou entrar nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Então, Asa trouxe a prata e o ouro dos depósitos da casa de Yahweh e da casa do rei e enviou a Ben-Hadade, rei da Síria, que morava em Damasco. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '\"Haja uma aliança entre mim e ti, como havia entre meu pai e teu pai. Olha, eu te enviei prata e outro. Quebra a aliança com Baasa, rei de Israel, para que assim ele possa me deixar em paz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Ben-Hadade deu ouvidos ao rei Asa e enviou os comandantes dos seus exércitos contra as cidades de Israel. Eles atacaram Ijom, Dã, Abel-Maim e todas as cidades de armazenamento de Naftali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Quando Baasa ouviu isso, ele parou de fortificar Ramá e cessou esse trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Então o rei Asa levou todo o Judá consigo, eles pegaram as pedras e as madeiras de Ramá, com as quais Baasa estava fortificando essa cidade, e usaram esse material para construir Geba e Mispá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Naquele tempo o vidente Hanani veio a Asa, rei de Judá, e lhe disse: \"O exército do rei da Síria escapou das tuas mãos porque tu confiaste no rei da Síria e não confiaste em Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Não eram os etíopes e os líbios um exército enorme, com muitos carros de guerra e cavaleiros? Contudo, porque tu confiaste em Yahweh, Ele te deu a vitória sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Os olhos de Yahweh percorrem todos os lugares sobre toda a terra, a fim de mostrar que Ele é forte para aqueles cujos corações são íntegros para com ele. Mas tu procedeste de forma tola nessa questão. Portanto, de ora em diante, tu terás guerra.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Então, irado por causa dessa questão, Asa lançou o vidente na prisão. Ao mesmo tempo, Asa oprimiu alguns do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Eis que os feitos de Asa, do primeiro ao último, estão escritos no Livros dos Reis de Judá e Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'No trigésimo nono ano do seu reinado, Asa foi acometido de uma doença muito grave nos pés. Mesmo assim, ele não buscou ajuda de Yahweh, mas apenas dos médicos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'No quadragésimo primeiro ano do seu reinado, Asa morreu e descansou com seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Ele foi sepultado no mesmo túmulo que havia cavado para si na cidade de Davi. Seu corpo foi colocado num esquife cheio de incensos doces e vários tipos de especiarias preparadas por perfumistas habilidosos, e fizeram uma grande fogueira, em sua homenagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Josafá, filho de Asa, reinou em seu lugar e se fortaleceu contra Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Ele colocou tropas em todas as cidades fortificadas de Judá e colocou guarnições na terra de Judá e nas cidades de Efraim, que Asa, seu pai, havia capturado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Yahweh era com Josafá, porque ele andou nos primeiros caminhos de Davi, seu ancestral, e não seguiu os baalins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Ao invés disso, ele buscou o Deus de seu ancestral, andou conforme seus mandamentos, e não de acordo com as obras de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Então, Yahweh estabeleceu o reino em sua mão; todo o Judá o trouxe tributos a Josafá. Ele teve riquezas e honra em abundância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Seu coração estava comprometido com os caminhos de Yahweh. Ele também removeu os altares e os postes-ídolos de Aserá de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'No terceiro ano de seu reinado, enviou seus oficiais Bene-Hail, Obadias, Zacarias, Netanel e Micaías para ensinarem nas cidades de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'Com eles, estavam os levitas: Semaías, Netanias, Zebadias, Asael, Semiramote, Jônatas, Adonias, Tobias e Tobadonias; e com esses levitas, os sacerdotes Elisama e Jeorão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Eles ensinaram em Judá, tendo o Livro da Lei de Yahweh com eles. Eles percorriam todas cidades de Judá e ensinavam o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'O temor de Yahweh caiu sobre todas os reinos das terras que estavam ao redor de Judá, de maneira que não guerrearam contra Josafá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Alguns dos filisteus trouxeram presentes a Josafá e prata como tributo. Os árabes também trouxeram a ele rebanhos, sete mil e setecentos carneiros e sete mil e setecentos bodes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Josafá tornou-se muito poderoso. Construiu fortalezas e cidades-celeiros em Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Ele tinha muitos suprimentos nas cidades de Judá e soldados, homens fortes e corajosos, em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Aqui está uma lista deles ordenada pelo nome das suas familias: em Judá, eram comandantes de mil: com o comandante Adná, trezentos mil guerreiros;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'com o comandante Joanã, duzentos e oitenta mil homens;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'e depois, com Amasias, filho de Zicri, que voluntariamente se ofereceu para servir a Yahweh, duzentos mil guerreiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'De Benjamim: Eliadá, homem poderoso e destemido, e com ele, duzentos mil armados com arcos e escudos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'depois dele, Jozabade e, com ele, cento e oitenta mil preparados para a guerra;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Esses foram os que serviram ao rei Josafá, além daqueles a quem o rei designou para as cidades fortificadas por todo o Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Josafá possuía grandes riquezas e honra; ele aliou-se com Acabe, por ter casado sua filha com alguém da família dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Depois de alguns anos, ele foi a Acabe em Samaria. Acabe matou muitas ovelhas e bois para ele e para o povo que estava com ele. Acabe também o persuadiu para, com ele, atacar Ramote-Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Acabe, rei de Israel, disse a Josafá, rei de Judá: \"Tu virás comigo para Ramote-Gileade?\". Josafá lhe respondeu: \"Eu sou como tu, e meu povo é como o vosso povo; estaremos contigo na batalha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Josafá disse ao rei de Israel: \"Por favor, busca uma palavra de Yahweh como uma resposta para ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Então, o rei de Israel ajuntou os profetas, quatrocentos homens, e disse-lhes: \"Devemos ir a Ramote-Gileade para a batalha ou não?\". Eles lhe responderam: \"Ataca, porque Deus vos dará vitória\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Mas, Josafá lhes disse: \"Há ainda aqui algum outro profeta de Yahweh, de quem possamos buscar conselho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'O rei de Israel disse a Josafá: \"Ainda há um homem a quem podemos buscar conselho de Yahweh: Micaías, filho de Inlá. Mas eu o odeio porque ele nunca profetiza algo bom sobre mim, mas apenas dificuldades\". Mas Josafá lhe disse: \"Não digas isso, rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Então, o rei de Israel chamou um oficial comandante: \"Traz Micaías, filho de Inlá, agora mesmo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Acabe, rei de Israel, e Josafá, rei de Judá, estavam sentados cada um em um trono, vestidos com seus mantos, em um lugar aberto na entrada do portão de Samaria, e todos os profetas estavam profetizando diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Zedequias, filho de Quenaaná, fez para si chifres de ferro e disse-lhes: \"Yahweh diz isto: \'Com estes ferirás os sírios até que sejam consumidos\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'E todos os profetas profetizavam o mesmo, dizendo: \"Ataca Ramote-Gileade e vence, porque Yahweh a entregará nas mãos do rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'O mensageiro que foi chamar Micaías lhe disse: \"Agora, olha as palavras dos profetas que declaram coisas boas ao rei a uma só voz. Por favor, que tua palavra seja como a palavra de um deles e diz coisas boas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Micaías lhe respondeu: \"Assim como Yahweh vive, o que Deus disser é o que eu lhe direi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Quando ele veio ao rei, o rei lhe disse: \"Micaías, devemos ir a Ramote-Gileade para a batalha ou não?\" Micaías lhe respondeu: \"Ataca e sê vitorioso! Pois será uma grande vitória\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Então, o rei lhe disse: \"Quantas vezes devo exigir que jures me dizer apenas a verdade no Nome de Yahweh?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Então, Micaías lhe respondeu: \"Eu vi todo Israel disperso nas montanhas, como ovelhas sem pastor, e Yahweh disse: \'Estes não têm pastor. Que todo homem retorne à sua casa em paz\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Então, o rei de Israel disse a Josafá: \"Não te disse que ele não profetizaria coisas boas sobre mim, mas apenas dificuldades?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Então, Micaías disse: \"Portanto, todos vós deveis ouvir a palavra de Yahweh! Eu vi Yahweh sentando em Seu trono, e todo o exército celestial em pé à Sua direita e à Sua esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Yahweh lhes disse: \'Quem enganará Acabe, rei de Israel, para que suba e caia em Ramote-Gileade?\'. Um lhe respondeu de uma maneira, e outro de outra meneira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Então, um espírito veio, ficou perante Yahweh, e lhe disse: \'Eu os enganarei\'. Yahweh lhe disse: \'Como?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'O espírito lhe respondeu: \'Irei e me tornarei um espírito mentiroso na boca de todos os seus profetas\'. Yahweh lhe respondeu: \'Tu os enganarás, e ainda serás bem sucedido. Vai agora e faz isto\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Então, Yahweh colocou um espírito mentiroso na boca destes profetas, e Yahweh decretou desastres a teu respeito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Então, Zedequias, filho de Quenaaná, veio a Micaías e lhe deu um tapa no rosto, e lhe disse: \"De que caminho o Espírito de Yahweh saiu de mim para falar a ti?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Micaías lhe disse: \"Tu saberás naquele dia, quando correres para alguma sala interna para esconder-te\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'O rei de Israel disse a alguns servos: \"Pegai Micaías e levai-o a Amom, o governador da cidade, e a Joás, meu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Dizei-lhe: \'O rei vos fala: colocai este homem na prisão e alimentai-o com apenas um pouco de pão e um pouco de água, até que eu retorne a salvo\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Então, Micaías lhe disse: \"Se retornares a salvo, então, Yahweh não falou por mim\", e ainda acrescentou: \"Ouvi isso, todos do povo!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Então, Acabe, rei de Israel, e Josafá, rei de Judá, subiram contra Ramote-Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'O rei de Israel disse a Josafá: \"Eu me disfarçarei e entrarei na batalha mas, tu, veste os trajes reais\". Então, o rei de Israel disfarçou-se, e foram à batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'O rei da Síria havia mandado aos capitães de seus carros, dizendo: \"Não ataqueis os soldados menos importantes e nem os mais importantes; em vez disso, atacai apenas o rei de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Sucedeu que, quando os capitães dos carros viram Josafá, disseram: \"Este é o rei de Israel\". Viraram-se para atacá-lo, mas Josafá clamou e Yahweh o ajudou; Deus os desviou dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'E aconteceu que, quando os comandantes dos carros viram que não era o rei de Israel, desistiram de persegui-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Mas um certo homem puxou seu arco ao acaso e atirou no rei de Israel entre as juntas da sua armadura. Então, Acabe disse ao condutor de seu carro: \"Volta e leva-me desta batalha, pois estou gravemente ferido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'A batalha piorou naquele dia, e o rei de Israel manteve-se em seu carro, encarando os sírios até a noite. Por volta do tempo em que o sol estava se pondo, ele morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Josáfa, rei de Judá, retornou em paz para sua casa em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Então, Jeú, filho de Hanani, o vidente, foi ao encontro do rei Josafá e lhe disse: \"Deverias tu ajudar o perverso? Deverias tu amar aqueles que odeiam Yahweh? Por isso, a ira de Yahweh está sobre ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'No entanto, alguma bondade pode ser encontrada em ti, porque tiraste os postes de Aserá da terra e dispuseste teu coração a buscar a Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Josafá viveu em Jerusalém e foi novamente passar pelo meio do povo, de Berseba até as regiões montanhosas de Efraim, e os trouxe de volta a Yahweh, o Deus de seus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Ele estabeleceu juízes na terra de uma a outra extremidade, em todas as cidades fortificadas de Judá, cidade por cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Ele disse aos juízes: \"Considerai o que fareis, porque não julgareis para homens, mas para Yahweh! Ele está convosco nos julgamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Que o temor de Yahweh esteja sobre vós. Sede cuidadosos quando julgardes, pois não há iniquidade com Yahweh, vosso Deus, nem qualquer favoritismo ou barganha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Além disso, em Jerusalém, Josafá nomeou alguns dos levitas, sacerdotes e alguns dos ancestrais das famílias de Israel para cuidar dos julgamentos para Yahweh e por causa das disputas. Então, retornaram a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Ele os instruiu, dizendo-lhes: \"Deveis servir em reverência a Yahweh, com fidelidade e com um coração perfeito. Isso é o que deveis fazer:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Sempre que chegar até vós alguma controvérsia de vossos irmãos que vivem em vossas cidades, seja sobre derramamento de sangue, sobre leis e mandamentos, sobre estatutos ou decretos, devereis avisá-los para que não cometam pecado contra Yahweh, e então Sua ira não virá sobre vós e sobre vossos irmãos. Se agirdes dessa forma, não sereis culpados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Vede! Amarias, o chefe dos sacerdotes, presidirá sobre vós nos negócios que pertencem a Yahweh; Zebadias, filho de Ismael, chefe da tribo de Judá, está encarregado de todos os assuntos do rei; e também os levitas serão oficiais a vosso serviço. Procedei corajosamente, e que Yahweh esteja com aqueles que são bons\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Aconteceu que, depois disso, o povo de Moabe, de Amom e com eles alguns meunitas, vieram contra Josafá para guerrear.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Então, alguém veio a Josafá, dizendo: \"Uma grande multidão está vindo contra ti de além do mar Morto, de Harã. Vê, eles estão em Hazazom-Tamar\", que é En-Gedi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Josafá começou a temer, pôs-se a buscar Yahweh e proclamou um jejum em toda Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Judá se reuniu para buscar Yahweh; eles vieram de todas as cidades de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Josafá permaneceu na congregação de Judá e Jerusalém, na casa de Yahweh, de frente ao novo pátio,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'e disse: \"Yahweh, Deus de nossos ancestrais, não és Deus nos céus? Não és Tu o soberano de todos os reinos das nações? Poder e força estão em Tuas mãos, para que ninguém Te resista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Deus nosso, não lançaste fora os habitantes desta terra diante do povo de Israel, e os deste para sempre aos descendentes de Abraão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Habitaram nela e edificaram lá um santuário para o Teu Nome, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, '\'Se um desastre vier a nós — a espada do Teu julgamento, ou praga, ou fome —, nós nos apresentaremos diante desta Casa, diante de Ti, pois o Teu Nome está nesta Casa, e clamaremos em nossa angústia, e Tu nos ouvirás e nos livrarás\'..');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Ora, aqui está o povo de Amom, Moabe e monte Seir, os quais não deixaste que Israel os invadisse, quando saíram da terra do Egito; ao invés disso, Israel se afastou deles e não os destruiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Vê como eles nos retribuem: estão vindo para expulsar-nos da terra que nos destes por herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Nosso Deus, não os julgarás? Pois não possuímos poder contra o grande exército que está vindo contra nós. Não sabemos o que fazer, mas nossos olhos estão voltados para Ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Todo povo estava em pé diante de Yahweh, com os seus pequeninos, esposas e crianças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Então, no meio da congregação, o Espírito de Yahweh veio sobre Jaaziel, filho de Zacarias, filho de Benaia, filho de Matanias, o levita, um dos filhos de Asafe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'E Jaaziel lhes disse: \"Escutai, todo Judá e todos vós, habitantes de Jerusalém, e o rei Josafá! Isto é o que Yahweh vos diz: \'Não temais, nem vos assusteis por causa desse grande exército; pois a batalha não vos pertence, mas a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Descereis amanhã contra eles. Vede, estão subindo pelo caminho da passagem de Ziz! Vós os encontreis na extremidade do vale, em frente ao deserto de Jeruel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Não tereis de lutar nesta batalha. Ficai em vossas posições! Ficai parados, e vede Yahweh vos resgatar — a Judá e a Jerusalém. Não temais nem fiqueis desencorajados. Ide contra eles amanhã, pois Yahweh está convosco\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Josafá prostrou sua cabeça e sua face ao chão. Todo Judá e os habitantes de Jerusalém se ajoelharam diante de Yahweh para O adorar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Os levitas, dos descendentes dos coatitas e coraítas, se levantaram e adoraram a Yahweh, o Deus de Israel, em alta voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Logo de manhã, eles se levantaram e saíram para o deserto de Tecoa. Quando saíam, Josafá levantou-se e disse: \"Escutai-me, Judá e vós, habitantes de Jerusalém! Confiai em Yahweh, vosso Deus, e sereis amparados; confiai em Seus profetas e sereis bem sucedidos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Quando ele consultou o povo, designou aqueles que iriam cantar para Yahweh e dar-Lhe graças por Sua santidade e glória, quando saíram à frente do exército, e disse-lhes: \"Dai graças a Yahweh, pois Sua fiel aliança dura para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Quando começaram a cantar e render graças, Yahweh preparou homens para emboscar o povo de Amom, Moabe e monte Seir, que foram contra Judá. Eles foram derrotados');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'pois o povo de Amom e o povo de Moabe se levantaram para lutar contra os habitantes de monte Seir, para que fossem completamente destruídos e mortos. Quando terminaram com os habitantes do monte Seir, todos ajudaram a se destruirem uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Quando Judá chegou ao posto de vigilância no deserto, eles procuraram o exército, observaram, e estavam todos mortos, caídos pelo chão; ninguém escapou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Quando Josafá e seu povo vieram saquear os despojos, encontraram entre eles grande abundância de riquezas, roupas e joias preciosas, que tomaram para si, mais do que poderiam carregar. Levou três dias para eles carregarem os despojos, porque eram muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'No quarto dia, eles se ajuntaram em uma assembleia no vale de Beraca. Ali adoraram a Yahweh; por isso o nome daquele lugar é vale de Beraca, até os dias de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Então eles retornaram, todos os homens de Judá e Jerusalém, com Josafá à frente, para ir novamente a Jerusalém com alegria, pois Yahweh lhes fez regozijar sobre seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Vieram a Jerusalém e à casa de Yahweh com liras, harpas e trombetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'O temor de Deus veio sobre todos os reinos das nações quando ouviram que Yahweh havia lutado contra os inimigos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Então, o reino de Josafá se aquietou pois seu Deus lhe deu paz com todos ao seu redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Josafá reinou sobre Judá; ele tinha trinta e cinco anos de idade quando começou a reinar, e reinou em Jerusalém durante vinte e cinco anos. O nome de sua mãe era Azuba, filha de Sili.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Ele andou nos caminhos de Asa, seu pai; não se desviou deles. Fez o que era bom aos olhos de Yahweh;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'porém, os santuários não foram removidos, nem o povo voltou seus corações ao Deus de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Já os outros assuntos a respeito de Josafá, do começo ao fim, foram escritos na história de Jeú, filho de Hanani, que foi escrito no Livro dos Reis de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Depois disso, Josafá, rei de Judá, se aliou com Acazias, o rei de Israel, que havia cometido muita maldade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Ele se aliou com ele para construir navios para ir a Társis; eles os construíram em Enziom-Geber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Então Eliézer, filho de Dodavá, de Maressa, profetizou contra Josafá, dizendo-lhe: \"Porque te aliastes com Acazias, Yahweh destruiu todos os teus projetos\". Os navios foram despedaçados de forma que não foi possível navegar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Josafá dormiu com seus ancestrais e foi sepultado com eles, na cidade de Davi; Jeorão, seu filho, tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Jeorão tinha irmãos, filhos de Josafá: Azarias, Jeiel, Zacarias, Azarias, Micael e Sefatias. Todos eram filhos de Josafá, rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Seu pai tinha lhes dado grandes presentes de prata, ouro, outras coisas preciosas e também as cidades fortificadas de Judá; mas ele deu o trono a Jeorão porque ele era seu primogênito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Quando Jeorão assumiu o reino de seu pai e se estabeleceu firmemente como rei, matou todos os seus irmãos com a espada e também vários outros líderes de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Jeorão tinha trinta e dois anos quando começou a reinar e reinou por oito anos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Ele andou pelos caminhos dos reis de Israel, como a casa de Acabe estava fazendo, pois havia tomado a filha de Acabe como sua esposa, ele fez o que era mau à vista de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'No entanto, Yahweh não quis destruir a casa de Davi, por causa da aliança que tinha feito com Davi; pois Ele havia prometido que sempre lhe daria vida e aos seus descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Nos dias de Jeorão, Edom se revoltou do controle de Judá e instituiu um rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Então, Jeorão atravessou com o seus comandantes e todas as suas carruagens. Isso aconteceu quando se levantou à noite e lutou contra os edomitas, os quais tinham cercado a ele e aos comandantes de suas carruagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Assim, Edom tinha estado em rebelião do poder de Judá até este presente dia. Libna também se revoltou ao mesmo tempo do seu controle, porque Jeorão tinha deixado Yahweh, o Deus de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Além disso, Jeorão tinha construído lugares altos nas montanhas de Judá e fez os habitantes de Jerusalém viverem como prostitutas. Ele levou Judá à perdição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Então veio a Jeorão a carta do profeta Elias. Ela dizia: \"Isto é o que Yahweh, o Deus de Davi, teu ancestral, diz: Porque não andaste nos caminhos de Josafá, teu pai, nem nos caminhos de Asa, rei de Judá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'mas tens andado nos caminhos dos reis de Israel e fizeste Judá e seus habitantes de Jerusalém agirem como uma prostituta, como a casa de Acabe fez, e porque mataste com a espada teus irmãos na família de teu pai, homens que eram melhores que tu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'vê, Yahweh atacará com uma grande praga o teu povo, tuas crianças, tuas mulheres e todos os teus bens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Tu mesmo ficarás muito enfermo por causa de uma doença em teus intestinos, até teus intestinos cairão fora por causa da doença, dia após dia\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Yahweh despertou contra Jeorão os espíritos dos filisteus e dos árabes que estavam perto dos etíopes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Eles atacaram Judá, invadiram seu território e levaram todos os bens que foram encontrados na casa do rei. Eles também carregaram seus filhos e suas mulheres. Nenhum filho foi deixado a ele, exceto Jeoacaz, o mais novo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Depois de tudo disso, Yahweh o feriu com uma doença incurável no intestino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Aconteceu, no devido tempo, no final de dois anos, que seus intestinos caíram fora por conta da sua doença, e ele morreu dessa doença severa. Seu povo não fez fogo em sua honra como tinha feito para os seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Ele começou a reinar quando tinha trinta e dois anos, reinou em Jerusalém por oito anos e morreu sem lamentação. Foi sepultado na cidade de Davi, mas não nos túmulos reais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Os habitantes de Jerusalém fizeram rei, em lugar de seu pai, a Acazias, seu filho mais novo, pois a tropa de homens que vieram com os árabes ao acampamento tinha matado todos os seus filhos mais velhos. Assim, Acazias, filho de Jeorão, rei de Judá, tornou-se rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Acazias tinha quarenta e dois anos quando começou a reinar; ele reinou por um ano em Jerusalém. O nome de sua mãe era Atalia, filha de Onri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Ele também andou nos caminhos da casa de Acabe, pois sua mãe era sua conselheira em fazer coisas más.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Acazias fez o que era mau à vista de Yahweh, como os da casa de Acabe estavam fazendo, pois eles eram seus conselheiros depois da morte de seu pai, para sua destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Ele também seguiu seus conselhos. Foi com Jorão, filho de Acabe, rei de Israel, para lutar contra Hazael, rei da Síria, em Ramote-Gileade. Os sírios feriram Jorão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Jorão voltou para ser curado em Jezreel das feridas que lhe fizeram em Ramá, quando ele lutou contra Hazael, rei da Síria. Assim, Acazias, filho de Jeorão, rei de Judá, desceu até Jezreel para ver Jorão, filho de Acabe, pois Jorão havia sido ferido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Ora, a destruição de Acazias foi feita por meio de Deus, pela da visita a Jorão. Quando ele chegou, foi com Jorão para atacar Jeú, filho de Ninsi, a quem Yahweh havia escolhido para destruir a casa de Acabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Aconteceu quando Jeú estava executando o julgamento de Deus, na casa de Acabe, que ele encontrou os líderes de Judá e os filhos dos irmãos de Acazias servindo Acazias. Jeú os matou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Jeú procurou por Acazias; encontraram-no escondendo-se em Samaria, trouxeram-no para Jeú e o mataram. Então, sepultaram-no, pois disserm: \"Ele é um filho de Josafá, que buscava Yahweh com todo o coração. Assim, a casa de Acazias não tinha mais poder para governar o reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Ora, quando Atalia, mãe de Acazias, viu que seu filho estava morto, levantou-se e matou todas as crianças reais na casa de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Mas Jeosabeate, uma filha do rei, tomou Joás, filho de Acazias, e o levou do meio dos filhos do rei que foram mortos. Ela o colocou em um quarto com sua ama. Assim, Jeosabeate, uma filha do rei Jeorão, a esposa de Joiada, o sacerdote (pois ela era irmã de Acazias), escondeu-o de Atalia, para que Atalia não o matasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Joás estava com eles, escondido na Casa de Deus, por seis anos, enquanto Atalia reinava sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'No sétimo ano, Joiada mostrou sua força e entrou numa aliança com os comandantes de centenas, Azarias filho de Jeroão, Ismael filho de Joanã, Azarias filho de Obede, Maaseias filho de Adaías, e Elisafate, filho de Zicri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Eles foram sobre Judá e reuniram os levitas de todas as cidades de Judá, assim como os cabeças das casas ancestrais de Israel, e eles vieram para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Toda a assembleia fez uma aliança com o rei na casa de Deus. Joiada lhes disse: \"Veja, o filho do rei reinará, assim como Yahweh havia dito a respeito dos descententes de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Isso é o que deveis fazer: um terço de seus sacerdotes e dos levitas que vieram para servir no sábado, serão guardas das portas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'outro terço será na casa do rei e o outro terço será à Porta do Fundamento. Todo o povo estará no pátio da casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Não deixeis que ninguém entre na casa de Yahweh, exceto os sacerdotes e os levitas que estão servindo. Eles podem entrar, pois eles são consagrados. Todas as outras pessoas devem obedecer os mandamentos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Os levitas rodearão o rei de todos os lados, todos os homens, cada um com sua arma em mãos. Qualquer que entrar na casa, que seja morto. Fique com o rei quando ele entrar e quando ele sair\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Assim, os levitas e toda a Judá fizeram tudo conforme o sacerdote Joiada ordenou. Cada um tomou seus homens, aqueles que estavam indo servir no sábado, e aqueles que estavam deixando de servir no sábado, pois Joiada, o sacerdote, não dispensou nenhuma das suas divisões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Então Joiada, o sacerdote, trouxe aos comandantes lanças e pequenos e grandes escudos, que pertenciam ao rei Davi que estavam na casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Joiada colocou todos os soldados, cada homem com sua arma em sua mão, do lado direito do templo até o lado esquerdo do templo, do lado do altar e o templo, ao redor do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Então, trouxeram para fora o filho do rei, puseram-lhe a coroa, e entregaram-lhe os decretos da aliança. Então eles o fizeram rei, e Joiada e seus filhos o ungiram. Então eles disseram: \"Vida longa ao rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Quando Atalia ouviu o barulho das pessoas correndo e adorando o rei, ela veio ao povo na casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'E ela olhou, e eis que o rei estava junto a seu pilar na entrada e os comandantes e trompetistas estavam com o rei. Todo o povo da terra estava regozijando e tocando trompetes; os cantores estavam tocando instrumentos musicais e dirigiam o canto de louvores. Então Atalia rasgou suas vestes e gritou: \"Traição! Traição!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Então, Joiada, o sacerdote, trouxe para fora os comandantes de centenas que estavam sobre o exército e disse-lhes: \"Traga ela para fora das fileiras; qualquer um que a seguir, deixe-o ser morto com a espada\". Pois o sacerdote disse: \"Não a matem na casa de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Assim, eles a prenderam e a levaram até a entrada da porta do cavalo da casa do rei, e ali a mataram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Então, Joiada fez uma aliança entre si mesmo, todo o povo e com o rei, que eles deveriam ser o povo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Todo o povo foi à casa de Baal e a destruiu. Eles quebraram os altares de Baal e suas imagens em pedaços e eles mataram Matã, o sacerdote de Baal, em frente daqueles altares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Joiada apontou oficiais para a casa de Yahweh sobre a mão dos sacerdotes, os quais eram levitas, o qual Davi tinha designado a casa de Yahweh, para ofertar as ofertas queimadas a Yahweh, assim como estava escrito na lei de Moisés, junto com regozijos e canções, assim como Davi direcionou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Joiada montou guardas nos portões da casa de Yahweh, assim, ninguém que estava impuro, de qualquer maneira, deveria entrar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Joiada levou com ele os comandantes de centenas, os nobres, os governadores do povo e todas as pessoas da terra. Conduziu o rei da casa de Yahweh; o povo veio através da porta superior para a casa do rei e colocou o rei no trono do reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Assim todo o povo da terra se regozijou, e a cidade estava tranquila. Quanto a Atalia, eles a mataram à espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joás tinha sete anos quando começou seu reinado; reinou por quarenta anos em Jerusalém. O nome de sua mãe era Zíbia, de Berseba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Joás fez o que era bom aos olhos de Yahweh em todos os dias do sacerdote Joiada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Joiada tomou duas mulheres para ele, e tornou-se pai de filhos e filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Aconteceu, depois dessas coisas, que Joás decidiu restaurar a casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Ele reuniu os sacerdotes e levitas, e disse-lhes: \"Ide todos os anos nas cidades de Judá e recolham de todo o Israel dinheiro para a restauração da casa de vosso Deus. Tenham certeza de começar logo\". De inicio os levitas nada fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Assim, o rei chamou Joiada, o sumo sacerdote, e disse-lhe: \"Por que não requerestes dos levitas que trouxessem de Judá e Jerusalém a taxa estabelecida por Moisés, o servo de Yahweh, e pela assembleia de Israel, para a tenda dos decretos da aliança?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Pois os filhos de Atalia, aquela mulher ímpia, que arruinaram a Casa de Deus, e deram todas as coisas sagradas da Casa de Yahweh aos cultos aos baalins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Assim, o rei ordenou e fizeram um baú e o colocaram do lado de fora da entrada da casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Então, anunciaram em Judá e Jerusalém, para que o povo trouxesse para Yahweh as taxas que Moisés o servo de Deus estabeleceu para Israel no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Todos os líderes e todo o povo regozijaram e trouxeram o dinheiro e colocaram no baú até terminar de enchê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Aconteceu que, sempre que traziam o baú aos oficiais do rei pela mão dos levitas, e sempre que viam que havia muito dinheiro nele, o escriba do rei e o oficial do sumo sacerdote vinham e esvaziavam o baú, e o levavam de volta ao seu lugar. Fizeram isso dia após dia, juntando uma grande quantidade de dinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'O rei e Joiada deram o dinheiro para aqueles que fizeram o trabalho de servir na casa de Yahweh. Esses homens contrataram pedreiros e carpinteiros para restaurar a casa de Yahweh, e também aqueles que trabalhavam com ferro e bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Aqueles que tinham o encargo do trabalho faziam que o trabalho de reparação fosse crescendo por suas mãos. Eles restauraram a casa de Deus em seu desenho original e o fortaleceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Quando terminaram, trouxeram o resto do dinheiro ao rei e a Joiada. Este dinheiro foi usado para fazer movéis para a casa de Yahweh, utensílios nas quais para servir e fazer ofertas, colheres e utensílios de ouro e prata. Ofereceram ofertas queimadas na Casa de Yahweh continuamente, todos os dias de Joiada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Joiada envelheceu e estava com idade avançada de cento e trinta anos de idade quando morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'O sepultaram na cidade de Davi, junto com os reis, porque ele havia feito o bem em Israel, para com Deus, e à Casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Após a morte de Joiada, os lideres de Judá vieram e honraram o rei. E o rei os ouviu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Eles abandonaram a Casa de Yahweh, o Deus de seus ancestrais, e louvaram aos deuses de Astarote e os ídolos. A ira de Deus veio sobre Judá e Jerusalém por causa dos erros deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Mesmo assim Ele lhes enviou profetas para os trazer de volta a Yahweh. Os profetas testificaram contra o povo, mas, eles se recusaram a ouví-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'O Espírito de Deus veio sobre Zacarias filho do sacerdote Joiada. Zacarias se levantou sobre o povo e disse-lhes: \"Disse Deus: \'Por que vós estais transgredindo os mandamentos de Yahweh, fazendo com que não prospereis? Desde quando abandonaram Yahweh, Ele também vos abandonou\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Mas eles conspiraram contra ele. Sob a ordem do rei, eles o apredejaram no pátio da casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Desta forma, o rei Joás ignorou a bondade que Joiada, pai de Zacarias, fizera com ele. Ao invés disso, ele matou o filho de Joiada. Quando Zacarias estava morrendo, disse: \"Que Yahweh veja e te faça prestar contas disso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'E aconteceu que, no final do ano, o exército da Síria se levantou contra Joás. Eles vieram a Judá e Jerusalém; mataram todos os líderes do povo, e enviaram todos os despojos ao rei de Damasco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'O exército de sírios vieram com um exército pequeno, mas Yahweh os deu a vitória sobre um grande exército, pois Judá abandonou Yahweh, o Deus de seus ancestrais. Dessa forma, os sirios trouxeram o julgamento sobre Joás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Quando os sírios se foram, deixaram Joás gravemente ferido. E seus próprios servos conspiraram contra ele, por causa do assassinato do filho do sacerdote Joiada. Eles o mataram em sua cama e o sepultaram na cidade de Davi, mas não nas tumbas dos reis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Estes foram os que conspiraram contra ele: foram Zabade, filho de Simeate, a amonita, e Jeozabade, filho de Sinrite, a moabita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Quanto aos filhos de Joás, as importantes profecias ditas sobre ele e a reconstrução da casa de Deus, eis que estão escritos no livro dos reis. E Amazias, seu filho, tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amazias tinha vinte e cinco anos quando começou a reinar. Reinou por vinte e nove anos em Jerusalém. O nome de sua mãe era Jeoadã, de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Ele fez o que era reto aos olhos de Yahweh, mas não com um coração completamente devotado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Aconteceu que, assim que seu governo ficou bem estabelecido, ele matou os servos que haviam assassinado seu pai, o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Porém ele não matou os filhos dos assassinos, mas agiu de acordo com o que está escrito na Lei, no Livro de Moisés, assim como Yahweh ordenou: \"Os pais não devem morrer pelos filhos, nem os filhos pelos pais. Em vez disso, cada pessoa deverá morrer pelo seu próprio pecado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Além do mais, Amazias reuniu Judá e registrou-o conforme os seus clãs familiares, sob os comandantes de mil e comandantes de cem, todos de Judá e Benjamim. Ele contou os que tinham de vinte anos para cima e encontrou trezentos mil homens aptos para irem à guerra e manejar lança e escudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Também contratou cem mil guerreiros de Israel por cem talentos de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Mas um homem de Deus veio a ele, dizendo: \"Rei, não deixes o exército de Israel ir contigo, pois Yahweh não está com Israel, isto é, com nenhum dos filhos de Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Mas, mesmo que tu vás e sejas forte e corajoso na batalha, Deus te fará cair diante do inimigo, pois Deus tem poder para ajudar e poder para derrubar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Disse Amazias ao homem de Deus: \"Mas o que faremos acerca dos cem talentos que eu havia entregue ao exército de Israel?\". O homem de Deus respondeu: \"Yahweh pode te dar muito mais do que isso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Então, Amazias separou o exército que tinha vindo de Efraim até ele e mandou-os para casa. Então, acendeu-se neles grande ira contra Judá e voltaram com grande fúria para sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Amazias criou coragem e conduziu seu povo para ir ao Vale do Sal; lá ele derrotou dez mil homens de Seir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'O exército de Judá capturou vivos outros dez mil. Eles os levaram à beira do abismo e os jogaram de lá, para que todos fossem quebrados aos pedaços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Mas os homens do exército que Amazias tinha mandado de volta, para que não fossem com ele para a batalha, atacaram as cidades de Judá, desde Samaria até Bete-Horom. Eles feriram três mil pessoas e levaram muitos despojos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'E aconteceu que, depois que Amazias voltou da matança dos edomitas, trouxe consigo os deuses do povo de Seir e os colocou como seus próprios deuses. Curvou-se diante deles e queimou-lhes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Então, a ira de Yahweh veio contra Amazias. Enviou-lhe um profeta que disse: \"Por que buscaste os deuses que não salvaram nem mesmo o seu próprio povo de tuas mãos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'E aconteceu que, enquanto o profeta estava falando para ele, o rei lhe disse: \"Nós te constituímos conselheiro do rei? Para! Por que tu deverias morrer?\". Então o profeta parou e disse: \"Sei que Deus decidiu te destruir, porque fizeste isso e não ouviste o meu conselho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Então Amazias, rei de Judá, consultou seus conselheiros e mandou mensageiros a Jeoás, filho de Jeoacaz, filho de Jeú, rei de Israel, dizendo: \"Encontremos um ao outro, face a face, em batalha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Mas Jeoás, rei de Israel, enviou mensageiros de volta a Amazias, rei de Judá, dizendo: \"O espinheiro que estava no Líbano mandou mensagem ao cedro no Líbano, dizendo: \'Dá tua filha a meu filho como esposa\', mas uma fera selvagem no Líbano passou e pisoteou o espinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Tu tens dito: \'Vede, eu destruí Edom\', e teu coração te elevou para teres orgulho de tua vitória. Mas fica em casa, por que deverias causar problemas a ti mesmo e caírem juntos tanto tu quanto Judá?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Mas Amazias não deu ouvidos, pois isso vinha de Deus, assim Ele entregaria o povo de Judá nas mãos dos seus inimigos, pois procuraram conselhos entre os deuses de Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Então, Jeoás, rei de Israel, atacou; ele e Amazias, rei de Judá, encontraram-se frente a frente, em Bete-Semes, que pertence a Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Judá foi destruído diante de Israel, e todos os homens fugiram para casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Jeoás, rei de Israel, capturou Amazias, filho de Joás, neto de Jeoacaz, rei de Judá, em Bete-Semes. Ele o trouxe a Jerusalém e derrubou os muros de Jerusalém, desde o portão de Efraim até o portão da esquina, quatrocentos côvados de distância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Ele tomou todo o ouro e prata, todos os objetos que foram encontrados na casa de Deus com Obede-Edom e as coisas valiosas da casa do rei, também fez reféns e voltou para Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Amazias, filho de Joás, rei de Judá, viveu quinze anos depois da morte de Jeoás, filho de Jeoacaz, rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Sobre os outros acontecimentos de Amazias, dos primeiros aos últimos, eis que não foram escritos no livro dos reis de Judá e Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Assim, desde o tempo em que Amazias deixou de seguir Yahweh, começaram a conspirar contra ele em Jerusalém. Ele fugiu para Laquis, mas enviaram homens atrás dele em Laquis e lá o mataram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Trouxeram-no de volta em cavalos e o enterraram junto com seus ancestrais na cidade de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Todo o povo de Judá tomou Uzias, que tinha dezesseis anos, e fizeram dele rei no lugar de seu pai, Amazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Foi ele quem reconstruiu Elate e a restaurou para Judá. Depois disso, o rei descansou com seus ancestrais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Uzias tinha dezesseis anos quando começou a reinar. Ele reinou por cinquenta e dois anos em Jerusalém. O nome de sua mãe era Jecolias e ela era de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Ele fez o que era correto aos olhos de Yahweh, seguindo o exemplo de seu pai, Amazias, em tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Ele se dispôs a seguir a Deus nos dias de Zacarias, que deu a ele instruções para obedecer a Deus. Enquanto ele buscou Yahweh, Deus o fez próspero.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Uzias foi à luta contra os filisteus e destruiu os muros da cidade de Gate, de Jabné e Asdode; ele construiu cidades no país de Asdode e junto aos filisteus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Deus o ajudou contra os filisteus, contra os árabes que viviam em Gur-Baal e contra os meunitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Os amonitas pagaram tributos a Uzias, e o seu nome se espalhou, até a entrada do Egito, pois ele se tornou muito poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Além disso, Uzias construiu torres em Jerusalém, no portão da Esquina, no portão do Vale, no canto do muro e os fortificou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Ele construiu torres de vigia no deserto e cavou muitos poços, pois ele tinha muito gado, tanto nas terras baixas como nas planícies. Ele tinha lavradores e vinhateiros nas terras das colinas e nos campos frutíferos, pois ele amava agricultura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Além do mais, Uzias tinha um exército de guerreiros que iam à guerra em grupos que eram organizados por seus números e contados por Jeiel, o escriba, e Maaseias, o oficial, sob a autoridade de Hananias, um dos comandantes do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'O número total de cabeças das casas de famílias e guerreiros era dois mil e seiscentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Sob sua mão estava um exército de trezentos e sete mil e quinhentos homens, que guerreavam poderosamente, para ajudar o rei contra o inimigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Uzias preparou para todo o exército: escudos, lanças, capacetes, couraças, arcos e pedras para atirar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Em Jerusalém, ele construiu máquinas, inventadas por homens habilidosos, para ficarem nas torres e nos cantos das muralhas, para atirar flechas e grandes pedras. Sua fama se espalhou por terras distantes, pois ele foi grandemente ajudado até se tornar poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Mas, quando Uzias se tornou poderoso, seu coração se encheu de orgulho e então ele agiu corruptamente; ele pecou contra Yahweh, seu Deus, pois ele foi à casa de Yahweh e queimou incensos no altar de incensos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Azarias, o sacerdote, foi atrás dele e com ele oitenta sacerdotes de Yahweh, homens corajosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Eles se opuseram a Uzias, o rei, e disseram-lhe: \"Não compete a ti, Uzias, queimar incenso para Yahweh, mas aos sacerdotes, os filhos de Arão, que foram consagrados para queimar incenso. Sai do Santo Lugar, pois tu foste infiel e não receberás honra de Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Então, Uzias se irou. Ele estava segurando um incensário em sua mão para queimar incenso. Enquanto ele estava irado com os sacerdotes, apareceu lepra em sua testa, diante dos sacerdotes na casa de Yahweh, ao lado do altar de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Azarias, o sacerdote chefe, e todos os sacerdotes olharam pra ele, e, então, ele se tornou leproso em sua testa. Eles rapidamente o tiraram de lá. De fato, ele se apressou em sair, porque Yahweh o atingira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Uzias, o rei, ficou leproso até o dia de sua morte e viveu numa casa separada, porque era leproso, pois ele foi tirado da casa de Yahweh. Jotão, seu filho, se encarregou da casa do rei e governou o povo da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Quanto aos outros feitos de Uzias, do primeiro ao último, estão no que Isaías, filho de Amoz, o profeta, escreveu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Então, Uzias descansou com seus ancestrais; eles o enterraram com seus ancestrais no túmulo pertencente aos reis, pois disseram: \"Ele é um leproso\". Jotão, seu filho, se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotão tinha vinte e cinco anos quando começou a reinar; ele reinou dezesseis anos em Jerusalém. Sua mãe se chamava Jerusa; ela era filha de Zadoque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Ele fez o que era reto aos olhos de Yahweh, seguindo o exemplo de seu pai, Uzias, em tudo. Ele também se negou a entrar no Templo de Yahweh. Mas o povo prosseguiu em suas práticas malignas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Ele construiu o portão superior da casa de Yahweh e construiu muito nas colinas de Ofel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Também construiu cidades na região montanhosa de Judá e nas florestas ele construiu castelos e torres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Ele também lutou contra o rei do povo de Amom e os derrotou. Naquele mesmo ano, o povo de Amom lhe deu cem talentos de prata, dez mil coros de trigo e dez mil de cevada. O povo de Amom lhe deu o mesmo no segundo e terceiro ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Então, Jotão tornou-se poderoso porque andava firmemente diante de Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Quanto aos outros atos de Jotão, todas as suas guerras e seus caminhos, eles estão escritos no livro dos reis de Israel e Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Ele tinha vinte e cinco anos quando começou a reinar e reinou por dezesseis anos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Jotão dormiu com seus antepassados, e o enterraram na cidade de Davi. Acaz, seu filho, tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Acaz tinha vinte anos de idade quando começou a reinar, e reinou por dezesseis anos em Jerusalém. Ele não fez o que era reto aos olhos de Yahweh, assim como Davi, seu pai, havia feito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'em vez disso, ele andou nos caminhos dos reis de Israel, e até fez imagens de fundição para os baalins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Além disso, ele queimou incenso no vale do filho de Hinom, e sacrificou seus filhos no fogo, de acordo com as práticas idólatras do povo que Yahweh expulsara de suas terras, diante do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Ele sacrificou e queimou incenso nos lugares altos, nas colinas e debaixo de toda árvore verde;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'pelo que Yahweh, o Deus de Acaz, o entregou nas mãos do rei da Síria. Os sírios o derrotaram e levaram um grande número de prisioneiros cativos para Damasco. Acaz também foi entregue nas mãos do rei de Israel, que o derrotou em um grande massacre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Pois Peca, filho de Remalias, matou em Judá cento e vinte mil soldados em um dia, todos eles homens corajosos, porque tinham abandonado Yahweh, o Deus de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Zicri, um homem poderoso de Efraim, matou Maaseias, filho do rei, e Azricão, o oficial do palácio, e Elcana, o segundo depois do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'O exército de Israel levou cativos de seus parentes duzentas mil esposas, filhos e filhas. Eles também levaram muitos despojos, que carregaram até Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Mas havia um profeta de Yahweh, seu nome era Odede; ele foi encontrar-se com o exército que entrava em Samaria, e disse-lhes: \"Porque Yahweh, o Deus de vossos antepassados, estava irado com Judá, Ele os entregou em vossas mãos; mas vós os matastes com uma fúria que alcançou os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'E agora, pretendeis manter os homens e as mulheres de Judá e Jerusálem como vossos escravos. Mas não sois culpado de vossos próprios pecados contra Yahweh, vosso Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Agora, então, ouvi-me: mandai os prisioneiros de volta, aqueles que tens tomado de vosso próprio irmão, pois o ardor da ira de Yahweh está sobre vós.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Então, certos líderes do povo de Efraim — Azarias, filho de Joanã, Berequias, filho de Mesilemote, Jeizquias, filho de Salum, e Amasa, filho de Hadlai — se levantaram contra os que voltavam da guerra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'e lhes disseram: \"Não trareis os prisioneiros aqui, pois além das nossas transgressões, o que quereis fazer acrescentaria ainda mais aos nossos pecados e às nossas culpas; pois nossa transgressão é grande, e temos o ardor da ira contra Israel.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Então, os homens armados deixaram os prisioneiros e o despojo diante dos líderes e de toda a congregação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Os homens que foram designados por nome levantaram-se, levaram os prisioneiros e vestiram todos que estavam nus entre eles com o despojo. Vestiram-nos e lhes deram sandálias, além de comida e água para beber. Trataram suas feridas, colocaram os fracos sobre os jumentos e os levaram de volta para suas famílias em Jericó, chamada a cidade das Palmeiras. Então, voltaram para Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Naquele tempo, o rei Acaz mandou mensageiros aos reis da Assíria, pedindo ajuda,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'pois novamente os edomitas atacaram Judá e levaram prisioneiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Os filisteus também invadiram as cidades da planície e do sul de Judá. Eles tomaram Bete-Semes, Aijalom, Gederote, Socó e seus vilarejos, Timna e seus vilarejos, também Ginzo e seus vilarejos, estabelecendo-se ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Pois Yahweh humilhou a Judá por causa de Acaz, o rei de Israel, já que ele agiu com maldade em Judá, e pecou contra Yahweh muito fortemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Tiglate-Pileser, rei da Assíria, veio a ele e o afligiu ao invés de fortalecê-lo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'pois Acaz saqueou a casa de Yahweh, e as casas do rei e dos líderes, para dar as coisas valiosas aos reis da Assíria, mas isso não o beneficiou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Este mesmo rei Acaz pecou ainda mais contra Yahweh em seu tempo de sofrimento;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'pois ele sacrificou aos deuses de Damasco, os deuses que o derrotaram. Ele disse: \"Porque os deuses dos reis da Síria os ajudaram, farei sacrifícios a eles, para que eles possam também me ajudar.\" Mas eles foram a ruína dele e de todo Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Acaz juntou todos os utensílios do templo de Deus e os despedaçou. Ele fechou as portas da casa de Yahweh, e fez para si altares em todos os cantos de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Em cada cidade de Judá, ele fez altares para queimar sacrifícios para outros deuses e, dessa forma, provocou a ira de Yahweh, o Deus de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Agora, o restante dos seus feitos e todos os seus caminhos, tanto os primeiros como os últimos, estão escritos no Livro dos Reis de Judá e Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Acaz descansou com seus antepassados, e o enterraram na cidade, em Jerusalém; mas não o trouxeram para os túmulos dos reis de Israel. Ezequias, seu filho, tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ezequias começou a reinar quando tinha vinte e cinco anos de idade; ele reinou vinte e nove anos em Jerusalém. Sua mãe se chamava Abia, filha de Zacarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Ele fez o que era reto aos olhos de Yahweh, seguindo o exemplo de Davi, seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'No primeiro ano de seu reinado, no primeiro mês, Ezequias abriu as portas da casa de Yahweh e as reparou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Ele trouxe os sacerdotes e levitas e os reuniu no pátio no lado leste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Disse-lhes: \"Ouvi-me, vós levitas! Consagrai-vos a Yahweh, consagrai a casa de Yahweh, o Deus de vossos antepassados, e tirai a imundícia desse santo lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Pois nossos antepassados pecaram e fizeram o que era mau aos olhos de Yahweh, nosso Deus; abandonaram-no, desviaram o rosto do lugar onde habita Yahweh e deram-lhe as costas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Também fecharam as portas do pórtico e apagaram as lâmpadas; não queimaram incenso nem ofereceram sacrifícios no santo lugar ao Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Por isso, a ira de Yahweh caiu sobre Judá e Jerusalém, e Ele os fez objeto de terror, de horror e de escárnio, como podeis ver com vossos próprios olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'É por isso que nossos pais caíram à espada; nossos filhos, nossas filhas e nossas esposas estão em cativeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Agora, está em meu coração fazer uma aliança com Yahweh, o Deus de Israel, para que Sua ira se desvie de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Meus filhos, não sejais negligentes agora, pois Yahweh vos escolheu para estardes diante Dele, para O adorardes, para serdes seus ministros e queimardes incenso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Então, os Levitas se levantaram: do povo do coatitas: Maate, filho de Amasai, e Joel, filho de Azarias; do povo de Merari: Quis, filho de Abdi, e Azarias, filho de Jealelel; dos filhos de Gérson: Joá, filho de Zima, e Éden, filho de Joá;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'dos filhos de Elizafã: Sinri e Jeuel; dos filhos de Asafe: Zacarias e Matanias;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'dos filhos de Hemã: Jeuel e Simei; dos filhos de Jedutum, Semaías e Uziel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Eles ajuntaram seus irmãos, consagraram-se e entraram, conforme o rei lhes ordenou, seguindo as palavras de Yahweh, para limpar a casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Os sacerdotes entraram na casa de Yahweh para limpá-la; tiraram toda a sujeira que encontraram no templo de Yahweh para o pátio da casa. Os levitas pegaram toda a imundícia e a lançaram no ribeiro de Cedrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Começaram a consagração no primeiro dia do primeiro mês. No oitavo dia do mês, chegaram ao pórtico de Yahweh. Então, por mais oito dias, consagraram a casa de Yahweh. No décimo sexto dia do primeiro mês, terminaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Então, foram até Ezequias, o rei, dentro do palácio, e disseram: \"Limpamos toda a casa de Yahweh, o altar de sacrifícios, com todos os seus utensílios, e a mesa do pão da proposição, com todos os seus utensílios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'E ainda preparamos e consagramos todos os itens que o rei Acaz havia jogado fora quando agiu com infidelidade, durante seu reinado. Vê, eles estão em frente ao altar de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Então, Ezequias, o rei, levantou-se cedo de manhã e reuniu os líderes da cidade; ele subiu à casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Trouxeram sete novilhos, sete carneiros, sete ovelhas e sete bodes como oferta pelos pecados do reino, pelo santuário e por Judá. Ordenou aos sacerdotes, os filhos de Arão, que os oferecessem sobre o altar de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Então, eles mataram os novilhos, os carneiros e as ovelhas. Os sacerdotes receberam o sangue e o aspergiram sobre o altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Trouxeram os bodes para oferta pelo pecado, diante do rei e da assembleia, e colocaram suas mãos sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Os sacerdotes os mataram e fizeram uma oferta pelo pecado com o sangue no altar, para fazer expiação por todo o Israel, pois o rei tinha ordenado que fizessem um sacrifício e uma oferta pelo pecado por todo o Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Ezequias colocou os Levitas na casa de Yahweh, com címbalos, harpas e liras, organizando-os pela ordem de Davi, de Gade, o vidente do rei, e Natã, o profeta; porque a ordem vinha de Yahweh, por meio de Seus profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Os levitas se levantaram com os instrumentos de Davi, e os sacerdotes com as trombetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Ezequias ordenou-lhes que oferecessem holocausto no altar. Quando o sacrifício começou, o cântico de Yahweh também começou, com trombetas, junto com os instrumentos de Davi, rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Toda a comunidade adorou, os cantores cantaram e as trombetas soaram; tudo isso continuou até o fim do sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Quando eles terminaram as ofertas, o rei e todos os que estavam presentes com ele se curvaram e adoraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Além disso, Ezequias, o rei, e os líderes ordenaram aos levitas que cantassem louvores a Yahweh com as palavras de David e de Asafe, o vidente. Eles cantaram louvores com alegria, curvaram-se e adoraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Então, Ezequias disse: \"Agora vós vos consagrastes a Yahweh. Vinde e trazei sacrifícios e ofertas de gratidão na casa de Yahweh\". A assembleia trouxe sacrifícios e ofertas de gratidão, e todos os que tinham um coração voluntário trouxeram holocaustos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'O número de holocaustos que a assembleia trouxe foi de setenta novilhos, cem carneiros e duzentos cordeiros. Todos esses foram para ofertas queimadas a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Os animais que foram consagrados a Yahweh foram seiscentos bois e três mil ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Porém eram poucos os sacerdotes para esfolar todos os holocaustos; então, os seus irmãos levitas os ajudaram até o trabalho terminar e os sacerdotes terminarem de se consagrar a Yahweh; pois os levitas eram mais cuidadosos em se consagrar do que os sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Além disso, havia muitos holocaustos; eles foram feitos com a gordura das ofertas pacíficas, e havia ofertas de libação para cada um dos sacrifícios. Assim, o serviço na casa de Yahweh foi posto em ordem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Ezequias alegrou-se, com todo o povo, por causa daquilo que Deus havia preparado para o povo, pois a obra foi feita rapidamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Ezequias enviou mensageiros para todo o Israel e Judá, e também escreveu cartas para Efraim e Manassés, para que eles fossem à casa de Yahweh em Jerusalém, para celebrar a Páscoa a Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Porque o rei, seus líderes, e toda a assembléia em Jerusalém resolveram juntos, e decidiram celebrar a páscoa no segundo mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Eles não puderam celebrar imediatamente, porque não havia sacerdotes consagrados em número suficiente, e o povo não havia se reunido em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Esta proposta pareceu boa aos olhos do rei e de toda assembléia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Então, eles concordaram em fazer uma proclamação por todo o Israel, de Berseba até Dã, para que o povo viesse celebrar a Páscoa de Yahweh, o Deus de Israel, em Jerusalém. Pois, um grande número deles não havia celebrado, segundo o que estava escrito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Assim, os mensageiros levaram as cartas do rei e de seus líderes por todo o Israel e Judá, conforme a ordem do rei. Eles falaram: \"Vós, povo de Israel, voltai para Yahweh, o Deus de Abraão, Isaque e Israel, para que Ele se volte para o restante de vós que escapastes das mãos dos reis da Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Não sejais como vossos ancestrais ou como vossos irmãos, que pecaram contra Yahweh, o Deus de seus ancestrais, por isso Ele lhes entregou à destruição, como vós podeis ver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Agora, não sejais teimosos, como vossos ancestrais foram, ao invés disso, sujeitai-vos a Yahweh e venhais para Seu Santo Lugar, o qual Ele tem santificado para sempre, e adorem Yahweh, vosso Deus, para que a Sua fúria se afaste de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Pois, se vos voltardes para Yahweh, vossos irmãos e crianças encontrarão compaixão diante daqueles que os levaram para longe como prisioneiros, e eles voltarão para esta terra. Porque Yahweh, vosso Deus, é gracioso e misericordioso, e não virará Sua face de vós, se vós retornardes para Ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Assim, os mensageiros foram de cidade em cidade pelas regiões de Efraim e Manassés, todo o caminho até Zebulom, mas o povo riu e caçoou deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Entretanto, certos homens de Aser, de Manassés e de Zebulom se humilharam, e vieram até Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'A mão de Deus também veio sobre Judá, para lhes dá um só coração, para cumprirem as ordens do rei e dos líderes conforme a palavra de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Muitas pessoas, se reuniram em uma grande assembleia em Jerusalém para celebrar a Festa dos Pães sem Fermento no segundo mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Eles se levantaram e tiraram os altares que estavam em Jerusalém e todos os altares de incenso; e eles os lançaram dentro do ribeiro de Cedrom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Então, eles mataram os cordeiros da Páscoa no décimo quarto dia do segundo mês. Os sacerdotes e levitas estavam envergonhados, e eles consagraram-se e trouxeram sacrifícios para a casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Eles se posicionaram em seus lugares segundo suas divisões, seguindo as direções que foram dadas na lei de Moisés, o homem de Deus. Os sacerdotes aspergiram o sangue que eles receberam das mãos dos levitas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'porque havia muitos na assembleia que não tinham se consagrado. Por isso, os Levitas sacrificaram os cordeiros da Páscoa por aqueles que não estavam purificados e não podiam consagrar seus sacrifícios a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Um grande número de pessoas, muitos deles de Efraim e Manassés, Issacar e Zebulom, não havia se purificado, mesmo assim, eles comeram a Páscoa, contrariando as instruções que estavam escritas. Mas Ezequias orou por eles dizendo: \"Que o bom Yahweh, possa perdoar a todos aqueles');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'que colocam em seu coração buscar a Deus, Yahweh, o Deus de seus ancestrais, mesmo que não tenham se purificado conforme os ritos de purificação do Santo Lugar.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Então, Yahweh ouviu Ezequias e curou o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'O povo de Israel que estava presente em Jerusalém celebrou o Festival dos Pães sem Fermento por sete dias com grande alegria. Os levitas e os sacerdotes adoraram Yahweh dia após dia, cantando para Yahweh, com instrumentos possantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Ezequias encorajou todos os levitas que entenderam o serviço de Yahweh. Assim, eles comeram por todo o festival, por sete dias, oferecendo sacrifícios de ofertas pacíficas e fazendo confissões a Yahweh, o Deus de seus ancestrais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Toda a assembleia decidiu celebrar por outros sete dias, e assim o fizeram com alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Pois, Ezequias, rei de Judá, deu para a assembleia mil novilhos e sete mil ovelhas para sacrifício; os líderes deram para a assembleia mil novilhos e dez mil ovelhas e bodes. Um grande número de sacerdotes se consagraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Toda a assembleia de Judá, com os sacerdotes e levitas, e todo o povo que se reuniu de Israel, como também os estrangeiros que vieram das terras de Israel e aqueles que viviam em Judá; todos se alegraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Assim, houve grande alegria em Jerusalém, pois, nem no tempo de Salomão, filho de Davi, rei de Israel, houve algo igual em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Então, os sacerdotes, os levitas, se levantaram e abençoaram o povo. Suas vozes foram ouvidas e suas orações se elevaram ao céu, Lugar Santo onde Deus vive.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Assim, quando tudo terminou, todo o povo de Israel que estava presente foi para as cidades de Judá, e eles quebraram em pedaços os pilares de pedra, destruíram os postes ídolos, derrubaram os lugares altos e os altares em toda a Judá e Benjamim. Eles também fizeram isso em Efraim e Manassés, até que destruíram a todos. Então, todo o povo de Israel retornou, cada um para a sua própria terra e para sua própria cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Ezequias estabeleceu as divisões dos sacerdotes e dos levitas organizados por suas divisões, cada homem designado ao seu trabalho, tanto sacerdotes quanto levitas. Ele os designou para fazer holocaustos e ofertas pacíficas, para servir, para agradecer, e para louvar nos portões do Templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Ele também designou a porção do rei para os holocaustos das suas próprias posses, isto é, para os holocaustos da manhã e da tarde e os holocaustos para os dias de sábado, das luas novas e dos festivais fixos, como estava escrito na lei de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Além disso, ele ordenou ao povo que vivia em Jerusalém que desse a porção para os sacerdotes e os levitas, para que eles se concentrassem em obedecer a lei de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Assim que a ordem saiu, o povo de Israel deu em abundância a primícia dos cereais, do vinho novo, do óleo, do mel e de toda sua colheita do campo. Eles trouxeram em grande quantidade o dízimo de tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'O povo de Israel e Judá que vivia nas cidades de Judá também trouxe o dízimo dos bois, das ovelhas, das coisas santas dedicadas a Yahweh, o seu Deus, e as ajuntaram em pilhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'No terceiro mês, eles começaram a ajuntar sua contribuição em pilhas e terminaram no sétimo mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Quando Ezequias e os líderes vieram e viram as pilhas, eles bendisseram Yahweh e Seu povo Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Então, Ezequias questionou os sacerdotes e os levitas sobre as pilhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Azarias, o sacerdote chefe, da casa de Zadoque, respondeu-lhe e disse: \"Desde que o povo começou a trazer as ofertas para a casa de Yahweh, temos comido e tem sido o suficiente, e tem sobrado bastante, pois Yahweh tem abençoado Seu povo. O que sobrou foi essa grande quantidade aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Assim, Ezequias ordenou que fossem preparados depósitos na casa de Yahweh, e eles os prepararam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'Então, eles fielmente trouxeram as ofertas, os dízimos e as coisas que pertenciam a Yahweh. Conanias, o levita, era o encarregado geral; e Simei, seu irmão, era o auxiliar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Jeiel, Azazias, Naate, Asael, Jerimote, Jozabade, Eliel, Ismaquias, Maate e Benaia eram encarregados sob a direção de Conanias e Simei, seu irmão, por determinação de Ezequias, o rei, e Azarias, o oficial sobre a casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Coré, filho de Imná, o levita, o guarda do portão oriental, estava encarregado das ofertas voluntárias de Deus, responsável por distribuir as ofertas a Yahweh e as ofertas santíssimas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Debaixo dele, estavam Éden, Miniamim, Jesuá, Semaías, Amarias e Secanias, nas cidades dos sacerdotes. Eles ocuparam posições de confiança; para que pudessem dar essas ofertas para seus irmãos, divisão por divisão, tanto para os importantes quanto não importantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Eles também deram para os homens de três anos para cima, que eram listados nas genealogias de seus antepassados que entravam na casa de Yahweh, como requerido na escala diária, para fazer seus trabalhos segundo suas divisões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Eles distribuíram aos sacerdotes de acordo com a genealogia de seus antepassados; e fizeram o mesmo para os levitas de vinte anos para cima, de acordo com seus cargos e suas divisões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Incluíram todos os seus pequeninos, suas esposas, seus filhos e suas filhas, por toda a comunidade, pois eles foram fiéis em se santificarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Para os sacerdotes, os descendentes de Arão, que estavam nos campos dos povoados pertencentes às suas cidades, ou em toda cidade, homens foram designados por nome, para dar porções a todo varão entre os sacerdotes e para todos os registrados na genealogia dos seus antepassados entre os levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Ezequias fez isso por todo o Judá e fez o que era bom, certo e fiel diante de Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Em todo projeto que ele começou no serviço da casa de Deus, a lei e os mandamentos para buscar seu Deus, ele trabalhou com todo o seu coração e foi bem-sucedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Depois dessas coisas e desses atos de fidelidade, Senaqueribe, rei da Assíria, veio e entrou em Judá, ele acampou para atacar as cidades fortificadas que ele intencionava capturar para si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Quando Ezequias viu que Senaqueribe tinha vindo com a intenção de lutar contra Jerusalém,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'ele consultou os seus líderes e os seus homens poderosos sobre a ideia de interromper as nascentes de água que estavam fora da cidade; eles o ajudaram a fazer isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Assim, muitas pessoas se juntaram e interromperam todas as nascentes e o riacho que estava fluindo pelo meio da terra. Eles disseram: \"Por que os reis da Assíria viriam e encontrariam bastante água?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Ezequias tomou coragem e fortificou o muro que estava danificado. Ele construiu as torres mais altas, e também o outro muro de fora. Ele também reforçou a Milo, na cidade de Davi, e produziu grandes quantidades de armas e escudos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Ele colocou comandantes militares sobre o povo, e os reuniu juntamente a ele na praça, junto à porta da cidade, e falou, encorajando-os. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '\"Sede fortes e de boa coragem. Não temais, nem fiqueis desencorajados, por causa do rei da Assíria e de todo o exército que está com ele, porque conosco está Alguém que é maior do que os que estão com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Com ele há apenas um braço humano, mas conosco está Yahweh, nosso Deus, para nos ajudar, e para lutar as nossas batalhas\". Então, o povo se confortou com as palavras de Ezequias, rei de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Depois disso, Senaqueribe, rei da Assíria, enviou seus servos para Jerusalém — ele, porém, estava em frente a Laquis, e todo o seu exército estava com ele —, para Ezequias, rei de Judá, e para todo o Judá que estava em Jerusalém. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, '\"Isso é o que Senaqueribe, rei da Assíria, diz: \'Em quem confiais para permanecerdes sitiados em Jerusalém?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Não está Ezequias vos enganando, para que ele vos deixe morrer de fome e de sede, ao dizer: \'Yahweh, nosso Deus, nos livrará da mão do rei da Assíria\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Esse não é o mesmo Ezequias que tirou os seus lugares altos e os seus altares, e ordenou a Judá e a Jerusalém: \'Em um único altar ireis adorar, e nele queimareis os vossos sacrifícios\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Não sabeis vós o que eu e meus antepassados fizemos a todos os grupos de povos das outras terras? Eram os deuses desses outros povos capazes, de alguma forma, de livrar a terra deles do meu poder?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Entre todos os deuses daquelas nações, que meus antepassados destruíram completamente, havia algum deus que poderia livrar o seu povo da minha mão? Por que deveria o vosso Deus ser capaz de vos livrar do meu poder?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Agora, não deixeis que Ezequias vos engane ou vos iluda desta maneira. Não acrediteis nele, pois não há deus em qualquer nação ou reino que tenha sido capaz de livrar o seu povo da minha mão, ou da mão dos meus antepassados. Quanto menos o vosso Deus vos livrará da minha mão?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Os servos de Senaqueribe falaram ainda mais contra Deus Yahweh e contra o Seu servo Ezequias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Senaqueribe também escreveu cartas para debochar de Yahweh, o Deus de Israel, e para falar contra Ele. Senaqueribe disse: \"Como os deuses das nações das terras não livraram o seu povo da minha mão, assim, o Deus de Ezequias não vai livrar o seu povo da minha mão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Eles gritaram na língua dos judeus ao povo de Jerusalém que estava no muro, para assustá-los e inquietá-los, a fim de capturar a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Eles falaram do Deus de Jerusalém, assim como eles falaram dos deuses dos povos da terra, que são meramente o trabalho das mãos de homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Ezequias, o rei, e Isaías, filho de Amós, o profeta, oraram sobre esse assunto e clamaram ao céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Yahweh enviou um anjo, que matou os guerreiros, os comandantes e os oficiais do rei no campo. Assim, Senaqueribe retornou envergonhado para sua própria terra. Quando ele tinha chegado na casa do seu deus, alguns dos seus próprios filhos o mataram a espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Desse modo, Yahweh salvou Ezequias e os habitantes de Jerusalém da mão de Senaqueribe, rei da Assíria, e da mão de todos os outros, e lhes deu descanso por todos os lados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Muitos trouxeram ofertas para Yahweh em Jerusalém, e presentes preciosos para Ezequias, rei de Judá, e assim ele foi exaltado aos olhos de todas as nações dali em diante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Naqueles dias, Ezequias ficou doente a ponto de morrer. Ele orou a Yahweh, que falou com ele e lhe de um sinal de que ele seria curado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Mas, Ezequias não retribuiu a Yahweh pela ajuda dada a ele, pois seu coração se exaltou. Assim, ira veio sobre ele, sobre Judá e Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Ezequias se humilhou pelo orgulho do seu coração, ambos, ele e os habitantes de Jerusalém. Assim, a ira de Yahweh não veio sobre eles durante os dias de Ezequias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Ezequias teve muitas riquezas e muita honra. Ele construiu para si muitos depósitos para prata, ouro, pedras preciosas e especiarias, assim como de escudos e todo tipo de objetos valiosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Ele também teve celeiros para a colheita dos cereais, vinho novo e óleo, e baias para todo tipo de animal. Ele também teve rebanhos em seus cercados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Além disso, ele construiu para si cidades e possuiu rebanhos e manadas em abundância, pois Deus tinha dado a ele muita riqueza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Foi esse mesmo Ezequias que tapou as nascentes superiores de água em Giom, e as canalizou pelo lado oeste da cidade de Davi. Ezequias teve sucesso em todos os seus projetos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Contudo, na questão dos embaixadores dos príncipes da Babilônia, que foram enviados a ele para fazerem perguntas sobre os sinais milagrosos que foram feitos na terra, Deus o deixou sozinho, para testá-lo e para saber tudo que estava em seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'As demais questões que dizem respeito a Ezequias, incluindo seus atos de lealdade à aliança, podem ser encontrados escritos na visão do profeta Isaías, filho de Amós, e no livro dos reis de Judá e Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Ezequias descansou com os seus ancestrais, e o sepultaram no sepulcro dos descendentes de Davi. Todo Judá e os habitantes de Jerusalém o honraram na sua morte. Manassés, seu filho, se tornou rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manassés estava com doze anos de idade quando começou a reinar; reinou cinquenta e cinco anos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Ele fez o que era mau à vista de Yahweh, como as repugnantes coisas das nações que Yahweh havia expulsado de diante do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Pois ele reconstruiu os lugares altos que Ezequias, seu pai, havia destruído, construiu altares para Baal, fez postes de Aserá, prostrou-se diante de todas as estrelas do céu e as adorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Manassés construiu altares pagãos na casa de Yahweh, embora Yahweh tenha ordenado: \"É em Jerusalém que Meu nome será estabelecido para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Ele construiu altares para todas as estrelas do céu nos dois pátios da casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Ofereceu seus filhos como ofertas queimadas no vale de Ben-Hinom. Praticou adivinhação e feitiçaria, leu presságios e consultou aqueles que falam com os mortos e aqueles que falam com espíritos. Ele praticou muitos males à vista de Yahweh e provocou a ira de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Ele colocou na casa de Deus uma figura de Aserá que ele próprio havia esculpido. Era sobre essa casa que Deus havia falado para Davi e Salomão, seu filho, dizendo: \"Nesta casa e em Jerusalém, a qual Eu escolhi de todas as tribos de Israel, que Eu porei o Meu nome para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Eu nunca mais removerei o povo de Israel para fora da terra que destinei para seus antepassados, se eles tão somente tiverem o cuidado de manter tudo que Eu lhes tenho ordenado, seguindo toda a lei, estatutos e decretos, os quais Eu dei por meio de Moisés\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Manassés levou Judá e os habitantes de Jerusalém a fazerem o mal mais do que as nações que Yahweh havia destruído diante do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Yahweh falou a Manassés e a seu povo, mas eles não deram atenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Assim, Yahweh trouxe a eles os comandantes do exército do rei da Assíria, que prenderam Manassés em correntes, amarraram-no com grilhões e o levaram para a Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Quando Manassés estava em angústia, implorou a Yahweh, seu Deus, e humilhou-se grandemente diante do Deus de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Ele orou e suplicou a Deus, que ouviu sua súplica e o trouxe de volta para Jerusalém, ao seu reino. Então, Manassés soube que Yahweh era Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Depois disso, Manassés construiu um muro do lado de fora da cidade de Davi, a oeste de Giom, no vale, para a entrada da porta do Peixe. Ele o fez passar em volta do monte Ofel e o levantou até uma grande altura. Pôs comandantes corajosos em todas as cidades fortificadas de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Tirou os deuses estrangeiros, como também o ídolo da casa de Yahweh e todos os altares que ele havia construído no monte da casa de Yahweh e em Jerusalém e jogou-os para fora da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Manassés reconstruiu o altar de Yahweh e ofereceu nele sacrifícios de ofertas pacíficas e de ações de graças. Ele ordenou Judá a servir Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Porém o povo ainda sacrificava nos lugares altos, mas somente para Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Os demais feitos concernentes a Manassés, sua oração a Deus e as palavras dos videntes que falaram a ele em nome de Yahweh, o Deus de Israel, estão escritas entre os feitos dos reis de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Sua oração e como Deus foi favorável a ele, todos os seus pecados e transgressões e os locais onde ele havia construído lugares altos e ergueu os postes de Aserá e as imagens esculpidas, antes de ter-se humilhado, estão escritos nas crônicas dos videntes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Assim, Manassés descansou com seus antepassados, e o sepultaram em sua própria casa. Amom, seu filho, tornou-se rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amom tinha vinte e dois anos quando começou a reinar. Reinou dois anos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Ele fez o que era mau à vista de Yahweh, como Manassés, seu pai, havia feito. Amom sacrificou a todas as imagens esculpidas que Manassés seu pai havia feito e as adorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Ele não se humilhou diante de Yahweh, como Manassés, seu pai, havia feito. Em vez disso, pecou mais e mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Seus servos conspiraram contra ele e o mataram em sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Mas os habitantes da terra mataram todos os que haviam conspirado contra o rei Amom e fizeram de Josias, seu filho, rei em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Josias tinha oito anos quando começou a reinar e reinou por trinta e um anos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Fez o que era reto aos olhos de Yahweh e andou nos caminhos de Davi, seu ancestral; não se desviou nem para a direita nem para a esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'No oitavo ano de seu reinado, quando ainda era jovem, começou a buscar o Deus de Davi, seu ancestral. No duodécimo ano, começou a purificar Judá e Jerusalém dos altares, dos postes-ídolos, das imagens de escultura e de metal fundido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'O povo quebrou os altares dos baalins na presença dele; despedaçou os altares de incenso que estavam sobre ele. Quebrou os postes-ídolos e as imagens de escultura e lançou fora as figuras de metal em pedaços, até ficarem como pó. Espalhou o pó sobre as sepulturas dos que lhes haviam sacrifícado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Queimou os ossos dos sacerdotes sobre os seus altares. Dessa forma, ele purificou Judá e Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Ele fez o mesmo nas cidades de Manassés, Efraim e Simeão, em todo o caminho até Naftali e nas ruínas que as cercavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Quebrou os altares, derrubou os postes-ídolos e as imagens de escultura em pó e cortou em partes os altares de incensos em toda a terra de Israel. Depois, voltou a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Aconteceu que, no décimo oitavo ano de reinado, depois de Josias haver purificado a terra e o templo, ele enviou Safã, filho de Azalias, Maaseias, o governador da cidade, e Joá, filho de Joacaz, o secretário; para reparar a casa de Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Estes foram a Hilquias, sumo sacerdote, e lhe confiaram o dinheiro que haviam trazido para a casa de Deus, que os levitas, os guardas dos portas, haviam recebido de Manassés, de Efraim, de todos os remanescentes de Israel, de toda a Judá, de Benjamim e dos habitantes de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Eles confiaram o dinheiro aos homens que supervisionavam o trabalho do templo de Yahweh. Esses homens pagaram aos trabalhadores que reconstruíam e restauravam o templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Deram-no aos carpinteiros e construtores, para comprarem pedras cortadas, madeiras para juntas e vigas para a estrutura, que era a mesma que o rei de Judá tinha separado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Os homens faziam o trabalho fielmente. Os supervisores eram Jaate e Obadias, os levitas, filhos de Merari; e Zacarias e Mesulão, filhos de Coate. Outros levitas, todos os que eram muito bons músicos, de perto dirigiam os trabalhadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Esses levitas estavam encarregados dos que carregavam o material de construção e de todo e qualquer trabalho. Lá também havia levitas que eram secretários, administradores e guardas dos portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Quando eles tiraram o dinheiro que tinham levado à casa de Yahweh, Hilquias, o sacerdote, achou o livro da Lei de Yahweh, que tinha sido dado por meio de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Hilquias disse a Safã, o escriba: \"Achei o livro da lei da casa de Yahweh\". Hilquias trouxe o livro a Safã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Safã levou o livro ao rei e também lhe disse: \"Teus servos estão fazendo tudo o que lhes foi confiado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Ajuntaram o dinheiro que se achou na casa de Yahweh e o entregaram nas mãos dos supervisores e trabalhadores\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Safã, o escriba, disse ao rei: \"Hilquias, o sacerdote, deu-me um livro\". Safã, então, leu-o para o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Aconteceu que, ouvindo o rei as palavras da Lei, rasgou suas vestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'O rei ordenou a Hilquias, Aicam, filho de Safã, Abdom, filho de Mica, Safã, o escriba, e Asaías, o servo dele, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '\"Ide e perguntai a Yahweh por mim e por aqueles que deixaram Israel e Judá, por causa das palavras do livro que foi encontrado. Grande é a ira que Yahweh tem derramado sobre nós. Grande ela é, porque nossos antepassados não ouviram as palavras do livro, para obedecer tudo que foi escrito ali\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Então, Hilquias e aqueles a quem o rei havia ordenado foram a Hulda, a profetisa, mulher de Salum, filho de Tocate, encarregado das vestes (ela vivia em Jerusalém no Segundo Distrito), e falaram com ela dessa maneira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Ela lhes disse: \"Isto é o que Yahweh, o Deus de Israel diz: \'Dizei ao homem que vos mandou a Mim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'isto é o que Yahweh diz: Vê, estou a ponto de destruir este lugar e trazer aos seus habitantes todas as maldições que foram escritas no livro e que foram lidas perante o rei de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Porque Me abandonaram e queimaram incenso a outros deuses, provocaram-Me à ira, com todos os atos que cometeram, derramarei Meu furor sobre este lugar, e não se apagará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Porém, ao rei de Judá, que vos enviou a perguntar a Yahweh o que ele deveria fazer, isto deveis dizer a ele: Yahweh, o Deus de Israel, assim diz: Sobre as palavras que tu ouviste,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'porque teu coração é terno e te humilhaste diante de Deus, quando ouviste as palavras Dele contra este lugar e seus habitantes, porque te humilhaste perante a Mim e rasgaste as vestes e choraste diante de Mim, Eu também te ouvi. Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Vê, Eu vou te reunir aos teus antepassados; tu serás recolhido em tua sepultura em paz, e teus olhos não verão nenhum dos desastres que irei trazer sobre este lugar e seus habitantes\'\". Os homens trouxeram essa mensagem ao rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'O rei enviou os mensageiros e os colocou juntos com todos anciãos de Judá e Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Então, o rei foi à casa de Yahweh, assim como todos os homens de Judá e os habitantes de Jerusalém, sacerdotes, levitas e todo o povo, do grande ao pequeno. Então, ele leu aos ouvidos de todos as palavras do Livro da Aliança, que tinha sido encontrado na casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'O rei permaneceu em seu lugar e fez uma aliança perante Yahweh, de andar segundo Yahweh e guardar Seus mandamentos, os decretos da Sua aliança e Seus estatutos, com todo o coração e toda a sua alma, de obedecer à palavra de aliança que fora escrita no Livro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Ele fez com que todo aquele que fosse achado em Jerusalém e em Benjamim permanecesse na aliança. Os habitantes de Jerusalém agiram em obediência para com a aliança de Deus, do Deus de seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Josias retirou todas as coisas repugnantes das terras que pertenciam ao povo de Israel. Ele fez todos em Israel adorarem Yahweh, o Deus deles. Enquanto ele viveu, eles não deixaram de seguir Yahweh, o Deus de seus ancestrais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Josias celebrou a Páscoa a Yahweh em Jerusalém; mataram os cordeiros para a Páscoa, no décimo quarto dia do primeiro mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Ele colocou os sacerdotes em suas posições e os encorajou no seu serviço na casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Disse aos levitas que ensinavam todo Israel e que eram dedicados a Yahweh: \"Ponde a Arca sagrada na casa que Salomão, filho de Davi, rei de Israel, construiu. Não a leveis em vossos ombros para lugar algum. Agora, adorai a Yahweh, vosso Deus, e servi ao seu povo em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Organizai-vos pelos nomes das casas de vossos ancestrais e suas divisões, seguindo as instruções de Davi, rei de Israel, e as de Salomão, seu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Levantai-vos no lugar sagrado, tomando vossas posições com as divisões dentro das casas dos ancestrais dos vossos irmãos, os descendentes do povo, e assumindo vossos postos com suas divisões entre os acestrais da casa dos levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Matai os cordeiros da Páscoa e consagrai-vos, preparai os cordeiros para os irmãos, fazendo conforme a palavra de Yahweh, que foi dada pelas mãos de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Josias deu a todo o povo trinta mil cordeiros e cabritos do rebanho, para as ofertas de Páscoa, a todos os presentes. Também deu três mil bezerros que pertenciam ao rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Seus líderes deram uma oferta voluntária ao povo, sacerdotes e levitas. Hilquias, Zacarias e Jeiel, os oficiais da casa de Deus, deram aos sacerdotes, para a Páscoa, ofertas de dois mil e seiscentos novilhos e trezentos bois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Também, Conanias, Semaías e Netanel, seus irmãos, e Hasabias, Jeiel e Jozabade, chefes dos levitas, deram aos levitas, cinco mil novilhos e quinhentos bois para as ofertas de Páscoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Então, o serviço estava preparado e, os sacerdotes assumiram seus postos, com os levitas em suas divisões, em resposta às ordens reais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Mataram os cordeiros da Páscoa, e os sacerdotes aspergiram o sangue que receberam das mãos dos levitas. Estes retiraram a pele dos cordeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Removeram as ofertas queimadas, para dividi-las na ordem das divisões de casas dos ancestrais de seu povo, para oferecê-los a Yahweh, como está escrito no Livro de Moisés. Fizeram o mesmo com os bois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Assaram os cordeiros da Páscoa com fogo, seguindo as instruções. Assim como as ofertas consagradas, cozinharam em potes, caldeirões e panelas e rapidamente as levaram para todo o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Mais tarde, prepararam para si e para os sacerdotes; porque os sacerdotes, os descendentes de Arão, estavam ocupados em oferecer as ofertas queimadas e a gordura até o anoitecer. Então, os levitas prepararam para si e para os sacerdotes, os descendentes de Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Os cantores, descendentes de Asafe, estavam em seus postos, direcionados por Davi, Asafe, Hemã, e Jedutum, o vidente do rei, e os guardas estavam em cada portão. Não precisavam sair de seus postos, porque seus irmãos, os levitas, lhes preparavam suas ofertas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Naquele tempo, todo o serviço para Yahweh estava sendo realizado para a celebração da Páscoa e para oferecer ofertas queimadas no altar de Yahweh, como o rei Josias havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'O povo de Israel, que estava presente, celebrou a Páscoa naquele momento e depois a festa dos pães sem fermento por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Nunca uma celebração de Páscoa em Israel havia sido tão grande desde os dias do profeta Samuel; ou tivera qualquer um dos reis de Israel celebrado a Páscoa como Josias o fez, juntamente com os sacerdotes, levitas e todo o povo de Judá e Israel, que estava presente, e os habitantes de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Essa Páscoa foi celebrada no décimo oitavo ano do reinado de Josias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Após tudo isso, depois que Josias colocou o templo em ordem, Neco, rei do Egito, levantou-se para lutar contra Carquêmis, no rio Eufrates, e Josias foi lutar contra ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Mas Neco enviou embaixadores a ele, dizendo: \"O que fiz eu contigo, rei de Judá? Não estou indo te atacar hoje, mas sim ao reino contra o qual estou em guerra. Deus me ordenou que eu me apressasse, não te oponhas a Deus, que está comigo, pois Ele pode te destruir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'No entanto, Josias se negou a recuar. Disfarçou-se a fim de lutar contra ele. Não ouviu as palavras de Neco, que vieram da boca de Deus; então, foi lutar no vale do Megido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Arqueiros atiraram no rei Josias, e o rei disse aos seus servos: \"Levai-me daqui, estou gravemente ferido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Então, seus servos o tiraram de seu carro e o colocaram em seu carro extra. Levaram-no para Jerusalém, onde ele morreu. Foi ele sepultado na tumba de seus ancestrais. Toda a Judá e Jerusalém choraram por Josias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Jeremias lamentou por Josias; todos os cantores e cantoras lamentam por ele até o dia de hoje. Essas canções se tornaram costume em Israel; elas foram escritas nas canções de lamentações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Quanto às outras coisas relacionadas a Josias, seus bons atos, sua obediência ao que está escrito nos livros da Lei de Yahweh');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'e os seus feitos do início ao fim, estão escritos no livro dos reis de Judá e Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'O povo da terra tomou Jeoacaz, filho de Josias, e o fez rei em Jerusalém, no lugar de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Jeoacaz começou a reinar em Jerusalém quando tinha vinte três anos de idade. Reinou apenas três meses,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'porque o rei do Egito o removeu de Jerusalém e impôs ao povo um tributo de cem talentos de prata e um talento de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'E o rei do Egito deu a Eliaquim, irmão de Jeoacaz, o reinado sobre Judá e Jerusalém além de mudar seu nome para Jeoaquim. Quanto a Jeoacaz, Neco o prendeu e o levou para o Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Jeoaquim começou a reinar quando tinha vinte e cinco anos e reinou durante onze anos em Jerusalém. Ele praticou o que era mau aos olhos de Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Então, Nabucodonosor, rei da Babilônia, o atacou e o prendeu em correntes, a fim de levá-lo para a Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Nabucodonosor também carregou alguns objetos do templo de Yahweh para a Babilônia e os colocou em seu palácio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Os demais assuntos relacionados a Jeoaquim, as coisas abomináveis que ele praticou e o que mais lhe aconteceu estão escritos no livro dos reis de Israel e Judá. Então, Joaquim, seu filho, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Joaquim, quando começou a reinar, tinha oito anos de idade; reinou durante três meses e dez dias em Jerusalém. Ele praticou o que era mau aos olhos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Na primavera, o rei Nabucodonosor enviou homens e o trouxe para Babilônia, com os utensílios valiosos do templo de Yahweh; o rei da Babilônia constituiu Zedequias para substituir seu irmão Joaquim como rei sobre Judá e Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Zedequias, quando começou a reinar, tinha vinte e um anos de idade. Reinou por onze anos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Ele praticou o que era mau aos olhos de Yahweh, seu Deus. Não se humilhou diante de Jeremias, o profeta, que falou palavras enviadas pela boca de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Zedequias também rebelou-se contra Nabucodonosor, que o tinha feito jurar lealdade perante Deus. Com o coração obstinado e endurecido, Zedequias não se converteu a Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Além disso, as transgressões de todos os líderes dos sacerdotes e do povo aumentavam mais e mais, pois imitavam as práticas repugnantes das nações pagãs. Eles contaminaram o templo de Yahweh, que Ele tinha santificado para Si, em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Yahweh, o Deus de seus pais, falou-lhes repetidas vezes, insistindo em adverti-los por meio de Seus mensageiros, porque Ele tinha compaixão do Seu povo e do lugar da Sua habitação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Porém, eles zombaram dos mensageiros de Deus, desprezaram Suas palavras e ridicularizavam Seus profetas, provocando a ira de Yahweh, que se inflamou contra Seu povo, até que não houvesse mais remédio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Por isso, Deus trouxe sobre eles o rei dos caldeus, que matou os seus jovens à espada no santuário e não poupou jovens, nem virgens, nem homens velhos, nem homens com cabelos grisalhos. Deus os entregou a todos nas mãos dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Ele levou para a Babilônia todos os utensílios grandes e pequenos do templo de Deus, os tesouros da habitação de Yahweh e os tesouros do rei e seus oficiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Eles incendiaram o templo de Deus, destruíram os muros de Jerusalém, queimaram todos os palácios e destruíram todas as coisas belas que havia ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'O rei levou para a Babilônia todos aqueles que escaparam da espada. Foram feitos escravos do rei e de seus filhos até o tempo do reino da Pérsia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Isso aconteceu para que se cumprisse a palavra de Yahweh pela boca de Jeremias: \"até que a terra receba compensação por seus sábados, durante todo o tempo em que ela repousar, até que se cumpram os setenta anos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'No primeiro ano de Ciro, o rei da Pérsia, cumpriu-se a palavra de Yahweh dita pela boca de Jeremias. Yahweh despertou o espírito de Ciro, o rei da Pérsia, e este mandou proclamar por todo o seu reino — e o fez também por escrito — o seguinte decreto:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, '\"Isto é o que Ciro, o rei da Pérsia, diz: \'Yahweh, o rei dos céus, entregou-me todos os reinos da terra. Ele me encarregou de construir uma templo para Si em Jerusalém, que fica em Judá. Quem dentre vós pertence ao Seu povo fique livre para ir, e que Yahweh, vosso Deus, esteja convosco\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'No primeiro ano de Ciro, rei da Pérsia, Yahweh cumpriu a Sua palavra que veio da boca de Jeremias e avivou o espírito de Ciro, rei da Pérsia. A voz de Ciro, foi ouvida por todo o seu reino. Isto é o que estava escrito e foi falado:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, '\"Assim diz Ciro, rei da Pérsia: \'Yahweh, Deus dos céus, me deu todos os reinos da Terra e me nomeou para construir para Ele um templo em Jerusalém, que fica em Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Aquele dentre vós que for do Seu povo, que Deus seja com esta pessoa, para que suba para Jerusalém, que fica em Judá, e construa o templo para Yahweh, Deus de Israel, que habita em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Povos de todas as partes do reino, onde sobreviventes daquela terra estão vivendo, devem provê-los com prata, ouro, posses e animais, assim como ofertas voluntárias para o templo de Deus em Jerusalém\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Então, levantaram-se os chefes das famílias de Judá e de Benjamim, os sacerdotes e levitas e todos a quem o Espírito de Deus despertou para subir e construir a cidade Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Todos os que habitavam nos arredores os ajudaram com prata, objetos de ouro, posses, animais, itens valiosos e ofertas voluntárias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'O rei Ciro também cedeu os objetos que pertenciam ao templo de Yahweh, aqueles que Nabucodonosor havia trazido de Jerusalém e colocado na casa de seus próprios deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Ciro, rei da Pérsia, os colocou sobre o controle de Mitredate, o tesoureiro, para que ele os contasse e os entregasse a Sesbazar, o líder de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Esta era a quantidade de objetos: trinta bacias de ouro, mil bacias de prata, vinte e nove facas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'trinta tigelas de ouro, quatrocentas e dez pequenas tigelas de prata e outros mil objetos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Havia ao todo cinco mil e quatrocentos itens de ouro e prata. Sesbazar trouxe todos eles quando os exilados vieram da Babilônia para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Estes são os filhos da província, que voltaram do cativeiro do Rei Nabucodonozor, que os tinha exilado na Babilônia, os que retornaram para Jerusalém e Judá, cada uma para sua própria cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Eles vieram com Zorobabel, Jesua, Neemias, Seraías, Reelaías, Mardoqueu, Bilsã, Mizpar, Bigvai, Reum e Baaná. Este é o registro dos homens do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Os descendentes de Parós: dois mil cento e setenta e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Os descendentes de Sefatias: trezentos e setenta e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Os descendentes de Ara: setecentos e setenta e cinco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Os descendentes de Paate-Moabe, dos filhos de Jesua e Joabe: dois mil oitocentos e doze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Os descendentes de Elão, mil duzentos e cinquenta e quatro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Os descendentes de Zatu: novecentos e quarenta e cinco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Os descendentes de Zacai: setecentos e sessenta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Os descendentes de Bani: seiscentos e quarenta e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Os descendentes de Bebai: seiscentos e vinte e três.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Os descendentes de Azgade: mil duzentos e vinte e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Os descendentes de Adonicão, seiscentos e sessenta e seis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Os descendentes de Bigvai: dois mil e cinquenta e seis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Os descendentes de Adim: quatrocentos e cinquenta e quatro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Os descendentes de Ater, da família de Ezequias: noventa e oito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Os descendentes de Bezai: trezentos e vinte e três.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Os descendentes de Jora: cento e doze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Os descendentes de Hasum: duzentos e vinte e três.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Os descendentes de Gibar: noventa e cinco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Os descendentes de Belém: cento e vinte e três.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Os descendentes de Netofate: cinquenta e seis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Os descendentes de Anatote: cento e vinte e oito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Os descendentes de Azmavete: quarenta e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Os descendentes de Quiriate-Jearim, de Cefira e de Beerote: setecentos e quarenta e três.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Os descendentes de Ramá e de Geba: seiscentos e vinte e um.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Os descendentes de Micmás: cento e vinte e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Os descendentes de Betel e de Ai: duzentos e vinte e três.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Os descendentes de Nebo: cinquenta e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Os descendentes de Magbis: cento e cinquenta e seis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'Os descendentes do outro Elão: mil duzentos e cinquenta e quatro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Os descendentes de Harim: trezentos e vinte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Os descendentes de Lode, de Hadide e de Ono: setecentos e vinte e cinco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Os descendentes de Jericó: trezentos e quarenta e cinco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Os descendentes de Senaá: três mil seiscentos e trinta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Os sacerdotes: os descendentes de Jedaías, da casa de Jesuá: novecentos e setenta e três.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Os descendentes de Imer: mil e cinquenta e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Os descendentes de Pasur: mil duzentos e quarenta e sete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Os descendentes de Harim: mil e dezessete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Os levitas: os descendentes de Jesuá e Cadmiel, descendentes de Hodavias: setenta e quatro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Os cantores: os descendentes de Asafe: cento e vinte e oito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Os descendentes dos porteiros: descendentes de Salum, de Ater, os de Talmom, de Acube, de Hatita, e de Sobai: ao todo, cento e trinta e nove.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Aqueles que foram atribuídos para servir no templo: os descendentes de Zia, Hasufa, Tabaote,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'os descendentes de Queros, de Sia, de Padom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'os descendentes de Lebana, de Hagaba, de Acube,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'os descendentes de Hagabe, de Sanlai, e de Hanã;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'os descendentes de Gidel, de Gaar, de Reaías,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'os descendentes de Rezim, de Necoda, de Gazão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'os descendentes Uzá, de Paseia, de Besai,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'os descendentes de Asná, de Meunim, de Nefusim;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'os descendentes de Baquebuque, de Hacufa, de Harur,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'os descentendes de Baslute, de Meída, de Harsa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'os descendentes de Barcos, de Sísera, de Tamá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'os descendentes de Nesias e de Hatifa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Os descendentes dos servos de Salomão: os descendentes de Sotai, de Soferete, de Peruda,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'os descendentes de Jaala, de Darcom, de Gidel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'os descendentes de Sefatias, de Hatil, de Poquerete-Hazebaim e de Ami.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'O total dos designados para servir no templo e dos descendentes dos servos de Salomão foram trezentos e noventa e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Estes são os que subiram de Tel-Melá, de Tel-Harsa, de Querube, de Adã e de Imer — mas não foram capazes de provar que seus antepassados eram de Israel:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'os descendentes de Delaías, de Tobias e de Necoda, seiscentos e cinquenta e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'E dos descendentes dos sacerdotes: Os descendentes de Habaías, Hacoz, e Barzilai (que tomou por esposa uma filha de Barzilai, de Gileade, e foi chamado pelo nome dele).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Estes procuraram encontrar sua genealogia no registro, mas não puderam encontrar, uma vez que eles foram considerados impuros para o sacerdócio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Então, o governador disse a eles que não deveriam comer qualquer sacrifício até que um sacerdote com Urim e Tumim aprovasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'O grupo inteiro totalizou quarenta e dois mil trezentos e sessenta,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'não incluindo seus servos e suas servas. Estes foram sete mil trezentos e trinta e sete, e seus cantores e cantoras, duzentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Seus cavalos: setecentos e trinta e seis. Suas mulas: duzentos e quarenta e cinco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'Seus camelos: quatrocentos e trinta e cinco. Seus jumentos: seis mil e setecentos e vinte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Alguns dos chefes de famílias, foram ao templo de Yahweh, em Jerusalém, e deram ofertas voluntárias para restaurarem o templo de Yahweh no seu antigo lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Eles ofertaram, de acordo com sua capacidade, para o tesouro da obra: sessenta e um mil dáricos de ouro, cinco mil minas de prata, e cem túnicas sacerdotais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Então, os sarcedotes e levitas, o povo, os cantores do templo, os porteiros e aqueles designados para servir no templo habitaram nas suas cidades, assim como todo o Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'No sétimo mês, após a volta dos israelitas às suas cidades, o povo se reuniu, como um só homem, em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Jesua, filho de Jozadaque, e seus irmãos, os sacerdotes, Zorobabel, filho de Sealtiel, e seus irmãos se ergueram e construíram um altar para o Deus de Israel, a fim de oferecerem holocaustos, como ordenado na lei de Moisés, homem de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Então estabeleceram o altar sobre as suas bases, apesar do medo que tinham dos povos ao redor. Eles ofereceram holocaustos a Yahweh ao amanhecer e ao anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Também observaram a Festa dos Tabernáculos, como está descrito, e ofereceram holocaustos, dia após dia, conforme o estabelecido, em cada dia determinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Assim, havia holocaustos diários e mensais e ofertas para todas as festas fixas de Yahweh, juntamente com as ofertas voluntárias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Eles começaram a oferecer holocaustos a Yahweh no primeiro dia do sétimo mês, embora os fundamentos do templo não tivessem sido postos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Então deram prata para os pedreiros e carpinteiros; e, comida, bebida e azeite para o povo de Sidom e de Tiro, para que eles enviassem cedro do Líbano a Jope, pelo mar, como autorizado por Ciro, rei da Pérsia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Então, no segundo mês do segundo ano, após terem vindo para o templo de Deus, em Jerusalém, Zorobabel, filho de Sealtiel, e Jesua, filho de Jozadaque, e o resto dos sacerdotes, os levitas e aqueles que vieram de volta do cativeiro para Jerusalém começaram a obra. Eles designaram os levitas de vinte anos ou mais para supervisionarem a obra do templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Então se apresentaram Jesua com os seus filhos e os seus irmãos, Cadmiel e os seus filhos, e os descendentes de Hodavias, para supervisionarem os que faziam a obra no templo de Deus, bem como os filhos de Henadade, seus filhos e seus irmãos, os levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Quando os construtores assentaram os alicerces do templo de Yahweh, os sacerdotes se apresentaram com suas vestimentas e com trombetas, e os levitas, filhos de Asafe, louvaram a Yahweh com címbalos, conforme as instruções deixadas por Davi, rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Eles cantavam responsivamente, com louvor e gratidão a Yahweh: \"Ele é bom, porque a sua misericórdia dura para sempre sobre Israel\". Todo o povo jubilou com grande brado de alegria e adoração a Yahweh porque o alicerce do templo estava pronto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Mas muitos dos sacerdotes, levitas, chefes de famílias, já idosos, que tinham visto o primeiro templo choraram bem alto quando, diante de seus olhos, foram lançados os alicerces deste templo. Porém, muitos gritaram de júbilo com alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'De maneira que não se podiam distinguir entre as vozes de júbilo das vozes de choro das pessoas, porque o povo gritava muito alto e o som se ouvia de longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Quando os adversários de Judá e de Benjamim ouviram que o povo que havia voltado do exílio estava construindo o templo para Yahweh, o Deus de Israel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'foram falar com Zorobabel e os chefes de famílias de seus antepassados, e disseram: \"Permiti que possamos ajudar a construir o templo, pois, como vós, buscamos a vosso Deus e temos oferecido sacrifícios a Ele desde os dias em que Esar-Hadom, rei da Assíria, nos trouxe para este lugar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Porém Zorobabel, Jesua e outros chefes de famílias de Israel lhes responderam: \"Não sois vós, mas nós que devemos construir o templo do nosso Deus. Nós mesmos, sozinhos, o construiremos para Yahweh, o Deus de Israel, assim como Ciro, o rei da Pérsia, nos ordenou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Então o povo da terra passou a desanimar o povo de Judá e fez com que os judeus ficassem com medo de construir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Eles também subornaram os conselheiros para frustrar seus planos. Fizeram isso durante todo o reinado de Ciro até os dias do reinado de Dario, rei da Pérsia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Assim, no princípio do reinado de Xerxes, eles escreveram uma acusação contra os habitantes de Judá e Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Foi durante o reinado de Artaxerxes que Bislão, Mitredate, Tabeel e seus companheiros lhe escreveram. A carta foi escrita em aramaico, com tradução.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Assim Reum, o comandante, e Sinsai, o escriba, escreveram a Artaxerxes sobre Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Então Reum, Sinsai e seus companheiros, que eram juízes, além de outros oficiais no governo persa, de Ereque, da Babilônia e de Susã, em Elam, escreveram uma carta;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'e a eles se juntaram pessoas que o grande e nobre Assurbanípal forçou a se estabelecerem junto com os outros que estavam na província deste lado do rio Eufrates.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Esta é uma cópia da carta que eles enviaram a Artaxerxes: \"Teus servos, homens da província deste lado do rio Eufrates, escrevem isto:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, '\'Saiba o rei que os judeus que da tua parte vieram a nós foram a Jerusalém e estão reconstruindo aquela cidade rebelde e má. Eles estão restaurando os muros e reparando os seus fundamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Que o rei saiba que, se esta cidade for construída e os muros finalizados, eles não pagarão os direitos, os impostos e os pedágios, e assim trarão prejuízo ao rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Agora, visto que temos vivido às custas do palácio, não é apropriado vermos qualquer desonra acontecer ao rei. Por isso é que estamos recomendando ao rei');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'que busque no livro das crônicas de teus pais, e saberás que esta é uma cidade rebelde, que tem causado muitos problemas aos reis e às províncias; ela tem sido um centro de rebelião há muito tempo. Foi por essa razão que a cidade foi destruída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Estamos informando ao rei que, se esta cidade e seus muros forem reconstruídos, não restará nada para ti na província deste lado do rio Eufrates\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Então o rei mandou a seguinte resposta a Reum, a Sinsai e a seus companheiros que moravam em Samaria e na província além do rio Eufrates: \"Que a paz seja convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'A carta que me enviastes foi traduzida e lida na minha presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Ordenei uma investigação e descobri que, desde tempos antigos, essa cidade tem se rebelado e se revoltado contra reis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Jerusalém tem sido governada por grandes reis que tiveram poder sobre toda a província além do rio Eufrates, e a eles se pagavam os direitos, os impostos e os pedágios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Agora, ordenai a esses homens que parem de construir essa cidade até que eu faça um decreto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Tomai cuidado para não negligenciar isto. Por que permitir que essa ameaça cresça e prejudique os interesses da realeza?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Quando o decreto do rei Artaxerxes foi lido perante Reum, Sinsai e seus companheiros, eles foram rapidamente a Jerusalém e forçaram os judeus a pararem a construção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Assim, a obra no templo de Deus em Jerusalém parou até o segundo ano do reinado de Dario, rei da Pérsia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Então, os profetas Ageu e Zacarias, filho de Ido, o profeta, profetizaram em nome do Deus de Israel para os judeus em Judá e Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Zorobabel, filho de Sealtiel e Jesua, filho de Jozadaque, se levantaram e começaram a construir o templo de Deus em Jerusalém, com os profetas os encorajando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Então, Tatenai, o governador da província a oeste do Eufrates, Setar-Bozenai e seus companheiros vieram e lhes disseram: \"Quem lhes deu ordem para construir este templo e concluir estes muros?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Eles também disseram: \"Quais os nomes dos homens que estão edificando esta construção?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Mas os olhos de Deus estavam sobre os anciãos judeus, e seus inimigos não os fizeram parar. Eles estavam esperando que uma carta fosse enviada para rei Dario e a resposta a respeito disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Esta foi a carta que Tatenai, o governador da província além do Eufrates, e Setar-Bozenai e seus companheiros oficiais, na província além do Eufrates, enviaram a Dario, o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Eles enviaram um relatório dizendo ao rei Dario: \"Toda paz esteja contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Saiba o rei que fomos à Judá, ao Templo do grande Deus. Ele está sendo construído com grandes pedras, e a madeira já está em suas paredes. Essa obra está sendo feita totalmente pelas mãos deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Nós perguntamos aos anciãos: \'Quem vos deu ordem para construir este templo e estes muros?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Nós lhes perguntamos seus nomes de modo que saibais quem são eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Eles responderam e disseram: \"Nós somos servos Daquele que é o Deus dos céus e da terra e estamos reconstruindo este templo que foi construído há muito tempo, quando o grande rei de Israel o ergueu e completou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Entretanto, quando nossos antepassados enfureceram o Deus do céu, Ele os entregou nas mãos de Nabucodosor, rei da Babilônia, que destruiu este templo e tomou o povo, exilando-o na Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'No entanto, no primeiro ano de Ciro como rei na Babilônia, Ciro mesmo emitiu um decreto para a reconstrução do templo de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'O rei Ciro também devolveu os objetos de ouro e de prata que pertenciam ao templo de Deus, aqueles que Nabucodonosor havia levado do templo em Jerusalém, para o templo na Babilônia. Ele os devolveu a Sesbazar, a quem havia feito governador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Ele lhe disse: \"Pega estes objetos. Vai e coloca-os no templo, em Jerusalém. Deixa o templo de Deus ser reconstruído ali.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Esse Sesbazar lançou os fundamentos para o templo de Deus em Jerusalém; e ele foi sendo construído, mas ainda não concluído.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Agora, se parecer bem ao rei, que seja feita uma busca na casa dos arquivos da Babilônia para ver se existe alguma declaração do rei Ciro sobre a construção do templo de Deus em Jerusalém. Então o rei enviará um parecer sobre isso a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Então o rei Dario ordenou que se fizesse uma busca na casa dos arquivos da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Na cidade fortificada de Ecbatana, na província da Média, um pergaminho foi encontrado, e este era o seu registro:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, '\"No primeiro ano do rei Ciro, o rei emitiu um decreto sobre o Templo de Deus em Jerusalém: \'Que o templo seja reconstruído como um local para oferecer sacrifícios, que seus fundamentos sejam lançados; a sua altura seja sessenta côvados, e a sua largura, sessenta côvados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'com três fileiras de pedras grandes e uma fileira de madeira nova, e que os custos sejam pagos pela casa do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Agora, trazei de volta os utensílios de ouro e de prata que pertencem ao templo de Deus, os quais Nabucodonosor levou do templo em Jerusalém para o templo na Babilônia. Enviai-os de volta para o templo em Jerusalém e depositai-os dentro do templo de Deus.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Agora, pois, Tatenai, governador da província dalém do rio, Setar-Bozenai e vossos companheiros que estais na província dalém do rio Eufrates, afastai-vos desse lugar!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Que ninguém interfira na obra do templo de Deus, para que o governador dos judeus e os seus anciãos construam esse templo de Deus no seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Eu estou ordenando o que deveis fazer para com esses anciãos judeus que estão na construção do templo de Deus: dos fundos reais dos tributos recebidos da província dalém do rio Eufrates, paguem todas as despesas a estes homens, para que a obra não seja interrompida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Tudo quanto for necessário: novilhos, carneiros, ou cordeiros para os holocaustos para o Deus dos céus; grãos, sal, vinho ou azeite, de acordo com a palavra dos sacerdotes em Jerusalém, dai a eles, todos os dias, sem falta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Fazei isso para que levem a oferta de aroma agradável ao Deus dos céus e orai por mim, o rei, e por meus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Eu ordeno que, se qualquer um violar este decreto, uma viga seja arrancada de sua casa e ele seja empalado nela. Sua casa será transformada em um amontoado de entulho por causa disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Que Deus, que fez habitar lá o Seu nome, derrube qualquer rei ou povo que levantar a mão para mudar este decreto ou para destruir o templo de Deus em Jerusalém. Eu, Dario, promulguei este decreto. Que seja executado com diligência!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Então, depois do decreto enviado pelo rei Dario, Tatenai, o governador da província deste lado do rio Eufrates, Setar-Bozenai e seus companheiros fizeram tudo que o rei Dario ordenara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Assim, os anciãos dos judeus construíram do modo como Ageu e Zacarias instruíram por profecia. Eles construíram de acordo com a ordem do Deus de Israel e os decretos de Ciro, de Dario e de Artaxerxes, reis da Pérsia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'O templo foi concluído no terceiro dia do mês de Adar, no sexto ano do reinado do rei Dario.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'O povo israelita, sacerdotes, levitas e o restante dos cativos celebraram com alegria a dedicação do templo de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Eles ofereceram cem touros, duzentos carneiros e quatrocentos cordeiros para a dedicação do templo de Deus. Doze bodes também foram oferecidos como oferta pelo pecado por todo o Israel, um para cada tribo em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Eles também nomearam os sacerdotes em suas divisões e levitas em suas classes para o serviço de Deus em Jerusalém, como estava escrito no livro de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Então aqueles que estavam no exílio celebraram a Páscoa no décimo quarto dia do primeiro mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Os sacerdotes e levitas se purificaram e fizeram os sacrifícios da Páscoa por todos aqueles que estavam no exílio, incluindo eles mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Os israelitas que comeram o cordeiro pascoal foram aqueles que retornaram do exílio, que se separaram da impureza dos povos da terra e procuraram Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Eles celebraram alegremente a Festa dos Pães sem Fermento, por sete dias, pois Yahweh trouxe-lhes alegria e mudou o coração do rei da Assíria a favor deles, para lhes fortalecer as mãos na obra de Seu templo, o templo do Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Depois destas coisas, durante o reinado de Artaxerxes, rei da Pérsia, Esdras veio da Babilônia. Esdras era filho de Seraías, filho de Azarias, filho de Hilquias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'filho de Salum, filho de Zadoque, filho de Aitube,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'filho de Amarias, filho de Azarias, filho de Meraiote,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'filho de Zeraías, filho de Uzi, filho de Buqui,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'filho de Abisua, filho de Fineias, filho de Eleazar, filho de Arão, o sumo sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Esdras veio da Babilônia e ele era um hábil escriba na Lei de Moisés que Yahweh, o Deus de Israel, havia dado. O rei lhe concedeu tudo o que ele pediu, pois a mão de Yahweh era sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Alguns dos descendentes de Israel e os sacerdotes, levitas, cantores do templo, porteiros e aqueles que foram designados para servirem no templo também subiram até Jerusalém no sétimo ano do rei Artaxerxes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Esdras chegou a Jerusalém no quinto mês daquele mesmo ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Ele saiu da Babilônia no primeiro dia do primeiro mês. Foi no primeiro dia do quinto mês que ele chegou em Jerusalém, porque a boa mão de Deus era sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Esdras tinha determinado em seu coração estudar, seguir e ensinar os estatutos e juízos da Lei de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Esta é a cópia da carta que o rei Artaxerxes deu a Esdras, o sacerdote e escriba que estudava os mandamentos e estatutos de Yahweh e os ensinava ao povo de Israel:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '\"O rei dos reis Artaxerxes ao sacerdote Esdras, escriba da Lei do Deus dos céus:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Estou ordenando que qualquer pessoa de Israel que vive no meu reino, juntamente com os seus sacerdotes e levitas, que desejar ir a Jerusalém, poderá ir contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Eu, o rei, e meus sete conselheiros, envio a todos vós, para investigardes em Judá e em Jerusalém a respeito da Lei de Deus, que está em vossas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'Tu deves levar a prata e o ouro que o rei e os seus conselheiros voluntariamente ofereceram ao Deus de Israel, cuja habitação está em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'Além de toda a prata e ouro que receberes na província da Babilônia, bem como as ofertas voluntárias do povo e dos sacerdotes para o templo de Deus, em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Com este recurso, terás o cuidado de comprar bois, cordeiros, ovelhas e as ofertas de cereais e de bebida. Oferecei-os no altar que está no templo de vosso Deus, em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Faze com o resto da prata e do ouro o que parecer melhor a ti e a teus irmãos, de acordo com a vontade do vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Entregai, diante do Deus Jerusalém, os objetos que vos foram dados para o serviço do templo do vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Qualquer outra coisa que for necessária para o templo do vosso Deus, o que vós quiserdes, será pago pelo tesouro real.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Eu, o rei Artaxerxes, faço um decreto a todos os tesoureiros na província dalém do rio Eufrates, que qualquer coisa que Esdras vos solicitar lhe seja concedido prontamente,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'até cem talentos de prata, cem coros de cereais, cem batos de vinho e cem batos de azeite, e sal à vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Tudo que for ordenado pelo Deus dos céus, que seja feito com zelo para Seu templo. Por que deveria cair Sua ira sobre o meu reino e meus filhos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Estamos informando a eles acerca de vós para que não imponham qualquer tributo ou imposto a nenhum dos sacerdotes, levitas, músicos, porteiros ou sobre as pessoas que foram designadas para o serviço do templo e aos servos do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Esdras, com a sabedoria que Deus tem te concedido, nomeie magistrados e juízes para servirem a todas as pessoas dalém do rio Eufrates, isto é, todos os que conhecem as leis do vosso Deus. E ensina-as aos que não as conhecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Todo aquele que não obedecer plenamente à lei do vosso Deus e à lei do rei seja punido ou com a morte, ou com o exílio, ou com o confisco dos seus bens, ou com a prisão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Esdras orou dizendo: \"Bendito seja Yahweh, o Deus de nossos antepassados, que pôs no coração do rei este propósito de glorificar o templo de Yahweh, em Jerusalém,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'e que estendeu a mim a fidelidade da Sua aliança, diante do rei, dos seus conselheiros e de todos os seus príncipes poderosos. Tenho sido fortalecido pela mão de Yahweh, meu Deus, e reuni líderes de Israel para voltarem comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Estes são os chefes das famílias, e esta é a genealogia dos que voltaram comigo da Babilônia durante o reinado do rei Artaxerxes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'dos descendentes de Fineias, Gérson; dos descendentes de Itamar, Daniel; dos descendentes de Davi, Hatus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'dos descendentes de Secanias, dos descendentes de Parós, Zacarias; e, com ele, foram registrados cento e cinquenta homens na genealogia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Dos descendentes de Paate-Moabe, Elioenai, filho de Zeraías e, com ele, foram registrados duzentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Dos descendentes de Zatu, Secanias, filho de Jaaziel e, com ele, foram registrados trezentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Dos descendentes de Adim, Ebede, filho de Jônatas e, com ele, foram registrados cinquenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Dos descendentes de Elão, Jesaías, filho de Atalias e, com ele, foram registrados setenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Dos descendentes de Sefatias, Zebadias, filho de Micael e, com ele, foram registrados oitenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Dos descendentes de Joabe, Obadias, filho de Jeiel e, com ele, foram registrados duzentos e dezoito homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Dos descendentes de Bani, Selomite, filho de Josifias e, com ele, foram registrados cento e sessenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Dos descendentes de Bebai, Zacarias, filho de Bebai e, com ele, foram registrados vinte e oito homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Dos descendentes de Azgade, Joanã, filho de Hacatã e, com ele, foram registrados cento e dez homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Dos descendentes de Adonicão, os últimos que chegaram: Elifelete, Jeiel e Samaías, e com eles, vieram sessenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Dos descendentes de Bigvai, Utai e Zabude e, com ele, foram registrados setenta homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Esdras disse: \"Eu reuni os viajantes junto ao canal que dá para Aava, e acampamos lá por três dias. Examinei o povo e os sacerdotes, mas não encontrei lá nenhum descendente de Levi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Então enviei Eliézer, Ariel, Semaías, Elnatã, Jaribe, Elnatã, Natã, Zacarias e Mesulão — os que eram líderes — bem como Joiaribe e Elnatã, que eram mestres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Depois, enviei-os a Ido, líder de Casifia. Eu lhes disse o que falar a Ido e aos seus parentes, aos que servem no templo em Casifia, para nos enviar servidores ao templo de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Então eles nos enviaram, pelas mãos de nosso bondoso Deus, um homem chamado Serebias, que era homem prudente. Ele era descendente de Mali, filho de Levi, filho de Israel. Serabias, com os seus filhos e irmãos, em número de dezoito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'Também enviaram Hasabias e, com ele, Jesaías, um dos filhos de Merari, com os seus irmãos e os filhos deles, em número de vinte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'Daqueles que se comprometeram a servir no templo, os quais Davi e seus oficiais deram para o serviço dos levitas: duzentos e vinte, cada um deles mencionado nominalmente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Então, proclamei, à margem do Canal de Aava, um jejum para nos humilharmos perante Deus para buscarmos o Seu reto caminho, tanto para nós quanto para nossas crianças e todos os nossos bens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Fiquei constrangido em perguntar ao rei por armamento ou cavaleiros para nos proteger contra os inimigos ao longo do caminho, uma vez que dissemos ao rei: \'A mão de nosso Deus está sobre todo aquele que O busca, e o Seu poder e a Sua ira estão sobre todos aqueles que Dele se esquecem\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Então jejuamos e imploramos a Deus quanto a isso, e Ele nos atendeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Em seguida, selecionei doze homens dos principais sacerdotes: Serebias, Hasabias e dez de seus irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'Pesei prata, ouro, e utensílios e ofertas para o templo de Deus, que o rei, os seus conselheiros, os seus oficiais e todo Israel livremente ofertaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Então pesei e entreguei, em suas mãos, seiscentos e cinquenta talentos de prata, cem talentos de utensílios de prata, cem talentos de ouro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'vinte tigelas de ouro que juntas valiam, no total, mil dáricos, e dois vasos de bronze fino e polido, tão precioso como o ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Eu disse a eles: \'Vós estais consagrados a Yahweh, bem como estes utensílios. E esta prata e este ouro são ofertas voluntárias a Yahweh, o Deus de vossos antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Vigiai-os e guardai-os até que os peseis na presença dos principais sacerdotes, dos levitas, e dos chefes de famílias de Israel, em Jerusalém, nas salas do templo de Deus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Os sacerdotes e os levitas receberam a prata, o ouro e os utensílios que haviam sido pesados, a fim de os trazerem para Jerusalém, para o templo do nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Partimos do Canal de Aava no décimo segundo dia do primeiro mês para irmos a Jerusalém. A mão do nosso Deus estava sobre nós. Ele nos protegeu contra nossos inimigos e contra aqueles que tentaram nos emboscar ao longo do caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Assim entramos em Jerusalém e permanecemos lá por três dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Então, no quarto dia, a prata, o ouro e os utensílios foram pesados no templo do nosso Deus, pelas mãos de Meremote, filho de Urias, o sacerdote. Com eles estavam Eleazar, filho de Fineias, e os levitas Jozabade, filho de Jesua, e Noadias, filho de Binui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Tudo foi contado e pesado, e o peso total foi registrado naquela mesma hora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Aqueles que retornaram do cativeiro, o povo do exílio, ofereceram holocausto ao Deus de Israel: doze novilhos por todo Israel, noventa e seis carneiros, setenta e sete cordeiros, e doze bodes em holocausto. Tudo foi oferecido em holocausto a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Então entregaram os decretos reais aos mais altos oficiais e governadores da província deste lado do rio Eufrates, e eles ajudaram o povo e o templo de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Quando essas coisas terminaram, os oficiais me abordaram e disseram: \"O povo de Israel, os sacerdotes e os levitas não se separaram do povo de outras terras e suas abominações: cananeus, heteus, perizeus, jebuseus, amonitas, moabitas, egípcios e amorreus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Pois eles tomaram algumas de suas filhas e misturaram o povo santo com o povo de outras terras, e os oficiais e líderes foram os primeiros nessa infidelidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Ao ouvir isso, rasguei minhas vestes e meu manto e arranquei o cabelo de minha cabeça e a barba. Então sentei envergonhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Todos aqueles que tremiam diante das palavras do Deus de Israel acerca dessa infidelidade se ajuntaram a mim enquanto eu sentava envergonhado até o sacrifício da tarde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Mas, na hora do sacrifício da tarde, levantei-me da minha posição de humilhação em minhas vestes e meu manto rasgados, ajoelhei-me e elevei minhas mãos a Yahweh, meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'Eu disse: \"Meu Deus, sinto vergonha e desgraça em levantar meu rosto para Ti, pois nossas iniquidades aumentam sobre nossa cabeça, e nossa culpa cresce até os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Desde os dias dos nossos antepassados ​​até agora, estamos em grande culpa. Em nossas iniquidades, nós, nossos reis e nossos sacerdotes fomos entregues nas mãos dos reis deste mundo, à espada, ao cativeiro, e à pilhagem e aos rostos envergonhados como estamos hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'No entanto, agora, por um curto período de tempo, a misericórdia de Yahweh, nosso Deus, veio para deixar alguns sobreviventes e nos dar uma posição em Seu lugar sagrado. Isso se deu para nosso Deus iluminar nossos olhos e nos dar um pouco de alívio em nossa escravidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Porque somos escravos, mas o nosso Deus não Se esqueceu de nós, pois tem estendido Sua aliança de fidelidade para conosco. Ele fez isso à vista do rei da Pérsia, a fim de nos dar novas forças, para que pudéssemos reconstruir o templo de nosso Deus e levantar Suas ruínas. Ele fez isso para poder nos dar um muro de proteção em Judá e em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Agora, ó nosso Deus, o que podemos dizer depois disso? Nós esquecemos os Teus mandamentos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'os mandamentos que Tu deste para Teus servos, os profetas, quando Tu disseste: \'Esta terra em que vós estais entrando para possuir é uma terra impura. Ela está contaminada pelo povo que nela habita com suas abominações. De uma extremidade à outra, eles a encheram de suas impurezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Agora, então, não entregueis vossas filhas aos filhos deles; não tomeis as suas filhas para vossos filhos e não busqueis acrescentar-lhes paz e bem-estar, para que sejais fortes e comais do melhor da terra. Assim, vossos descendentes possuirão a terra para todo o sempre\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'No entanto, depois de tudo que nos sobreveio em virtude de nossas más obras e nossa grande culpa — já que Tu, nosso Deus, retiveste o que nossas iniquidades merecem e nos permitiste sobreviver —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'deveríamos novamente quebrar Teus mandamentos e fazer casamentos mistos com essas pessoas abomináveis? Não ficarias indignado e nos aniquilarias de modo que não restasse nenhum de nós, que nenhum de nós viesse a escapar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Yahweh, Deus de Israel, Tu és justo, pois permanecemos como poucos sobreviventes neste dia. Olha! Estamos aqui, diante de Ti, em nossa culpa, embora saibamos que não há ninguém que possa estar diante de Ti por causa disso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Enquanto Esdras orava e confessava, ele chorava e prostrava-se diante do templo de Deus. Uma grande multidão de homens israelitas, mulheres e crianças se juntaram a ele, e o povo chorava amargamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Secanias, filho de Jeiel, dos descendentes de Elão, disse a Esdras: \"Fomos infiéis ao nosso Deus e temos casado com mulheres estrangeiras do povo de outras terras. Mas agora, apesar disso, ainda há esperança para Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Então, agora deixa-nos fazer uma aliança com nosso Deus para mandar sair todas as mulheres e seus filhos de acordo com os conselhos do Senhor e os conselhos daqueles que temem aos mandamentos do nosso Deus, e que se faça de acordo com a Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Levanta-te, porque isso é uma tarefa tua, e nós estamos contigo. Sê forte e faze isso!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Então, Esdras levantou-se e fez os principais sacerdotes, os levitas e todos de Israel prometerem agir dessa maneira. Assim todos eles fizeram um juramento solene.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Esdras levantou-se de diante do templo de Deus e foi aos quartos de Joanã, filho de Eliasibe. Ele não comeu pão e nem bebeu água porque estava lamentando sobre a infidelidade daqueles que voltaram do cativeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Desse modo, eles anunciaram em Judá e Jerusalém, para todo o povo que voltou do exílio, que todos se reunissem em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Qualquer um que não viesse em três dias, de acordo com os conselhos dos oficiais e anciãos, perderia todos os seus bens e seria excluído da grande congregação do povo que voltou do exílio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Então, todos os homens de Judá e de Benjamin, em três dias, reuniram-se em Jerusalém. Era o nono mês e o vigésimo dia do mês. Todo o povo estava de pé na praça, diante do templo de Deus, e eles tremeram por causa desta palavra e da chuva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Esdras, o sacerdote, levantou-se e disse: \"Vós mesmos cometestes traição. Vós vivestes com mulheres estrangeiras, e assim a culpa de Israel foi aumentada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Mas agora, confessai o vosso pecado a Yahweh, o Deus de vossos antepassados, e fazei a vontade Dele. Separai-vos dos povos da terra e das mulheres estrangeiras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Toda a congregação respondeu em alta voz: \"Nós faremos conforme tu disseste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Todavia, há um povo numeroso e é época da chuva. Nós não temos como ficar do lado de fora, e não é apenas um ou dois dias de trabalho, porque muitos de nós temos transgredido grandemente nesse assunto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Então deixa nossos líderes representarem toda a congregação. Todos os que permitiram que mulheres estrangeiras vivessem em nossas cidades virão, no tempo combinado com os anciãos e os juízes da cidade, até que a furiosa ira de nosso Deus se afaste de nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Jônatas, filho de Asael, e Jazeías, filho de Ticvá, apoiados por Mesulão e Sabetai, o levita, se opuseram a isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'E assim fez o povo que retornou do exílio. Esdras, o sacerdote, escolheu homens, os chefes de famílias, segundo a casa de seus antepassados, todos eles identificados pelo nome, e eles examinaram o assunto no primeiro dia do décimo mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'No primeiro dia do primeiro mês, eles terminaram de investigar todos os casos de homens que viviam com mulheres estrangeiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Entre os descendentes dos sacerdotes havia aqueles que viveram com mulheres estrangeiras: dentre os descendentes de Jesua, filho de Jozadaque, e seus irmãos estavam Maaseias, Eliézer, Jaribe e Gedalias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'E então eles decidiram mandar embora suas mulheres. Uma vez que eram culpados, eles ofereceram um carneiro do rebanho por sua culpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Dentre os descendentes de Imer: Hanani e Zebadias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Dentre os descendentes de Harim: Maaseias, Elias, Semaías, Jeiel e Uzias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Dentre os descendentes de Pasur: Elioenai, Maaseias, Ismael, Netanel, Jozabade e Eleasa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Dentre os levitas: Jozabade, Simei, Quelaías, também chamado Quelita, Petaías, Judá e Eliézer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Dentre os cantores: Eliasibe. Dos porteiros: Salum, Telem e Uri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Dentre o resto dos israelitas, dentre os descendentes de Parós: Ramias, Jezias, Malquias, Miamim, Eleazar, Hasabias e Benaia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Dentre os descendentes de Elão: Matanias, Zacarias, Jeiel, Abdi, Jerimote e Elias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Dentre os descendentes de Zatu: Elioenai, Eliasibe, Matanias, Jerimote, Zabade e Aziza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Dentre os descendentes de Bebai: Jeoanã, Hananias, Zabai e Atlai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Dentre os descendentes de Bani: Mesulão, Maluque, Adaías, Jasube, Seal e Jerimote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Dentre os descendentes de Paate-Moabe: Adná, Quelal, Benaia, Maaseias, Matanias, Bezaleel, Binui e Manassés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Dentre os descendentes de Harim: Eliézer, Issias, Malquias, Semaías, Simeão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamim, Maluque e Semarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Dentre os descendentes de Hasum: Matenai, Matatá, Zabade, Elifelete, Jeremai, Manassés e Simei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Dentre os descendentes de Bani: Maadai, Anrão, Uel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaia, Bedias, Queluí,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vanias, Meremote, Eliasibe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Matanias, Matenai e Jaasai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Dentre os descendentes de Binui: Simei,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemias, Natã, Adaías,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Macnadbai, Sasai, Sarai,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azareel, Selemias, Semarias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Salum, Amarias e José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Dentre os descendentes de Nebo: Jeiel, Matitias, Zabade, Zebina, Jadai, Joel e Benaías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Todos esses tomaram mulheres estrangeiras e tiveram filhos com algumas delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'As palavras de Neemias, filho de Hacalias. Ora, aconteceu no mês de quisleu, no vigésimo ano, enquanto eu estava na fortaleza de Susã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'quando um dos meus irmãos, Hanani, veio com algumas pessoas de Judá, e eu perguntei-lhes sobre os judeus que haviam escapado, o remanescente dos judeus que estava lá, e sobre Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Eles me disseram: \"Aqueles na província que sobreviveram ao cativeiro estão em grande dificuldade e desgraça, porque os muros de Jerusalém foram arrombados, e os portões foram incendiados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'E, assim que ouvi essas palavras, sentei-me e chorei por vários dias. Continuei de luto e de jejum, orando perante o Deus dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Eu disse: \"Yahweh, Deus dos céus, o Deus que é grande e maravilhoso, Tu que manténs a Tua aliança e a Tua benignidade com aqueles que Te amam e guardam os Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Escuta a minha oração e abre os Teus olhos, para que Tu possas escutar a oração do Teu servo, que oro diante de Ti, dia e noite, pelo povo de Israel, Teus servos. Eu estou confessando os pecados do povo de Israel, pois nós temos pecado contra Ti. Eu e a casa do meu pai pecamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Nós temos agido perversamente contra Ti, e não temos guardado os mandamentos, as leis e os decretos que Tu ordenaste ao Teu servo Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Por favor, lembra-Te da palavra que ordenaste ao Teu servo Moisés: \'Se agirdes infielmente, Eu irei espalhar-vos entre as nações,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'mas, se retornardes a Mim e seguirdes os Meus mandamentos e os praticardes, embora o vosso povo tenha sido espalhado pelos lugares mais distantes debaixo do céu, Eu irei juntá-los e os trarei para o lugar que Eu escolhi para estabelecer o Meu Nome\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Eles são os Teus servos e o Teu povo, a quem Tu resgataste pelo Teu grande poder e pela Tua mão forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Yahweh, eu Te imploro, ouve agora a oração do Teu servo e a oração dos Teus servos que se deleitam em honrar o Teu Nome. Faz com que Teu servo seja bem-sucedido hoje, e concede-lhe misericórdia às vistas deste homem\". Eu servia como copeiro do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'No Mês de Nisã, no vigésimo ano do rei Artaxerxes, quando o rei selecionou o vinho, peguei-o e dei-o ao rei. Ora, eu nunca havia ficado triste na presença dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Então o rei me disse: \"Por que o seu rosto está tão triste? Tu não pareces estar doente. Isso deve ser tristeza do coração\". Então, fiquei com muito medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Eu disse ao rei: \"Que o rei viva para sempre! Como o meu rosto não estaria triste? A cidade, onde estão os sepulcros dos meus pais, está em ruínas, e os portões foram destruídos pelo fogo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Então, o rei me disse: \"O que queres que eu faça?\" Eu orei ao Deus dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Então, eu respondi ao rei: \"Se parecer bom ao rei, e se o teu servo tem sido agradável aos teus olhos, vossa majestade poderia enviar-me para Judá, cidade dos selpucros dos meus pais, para que eu possa reconstruí-la\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'O rei respondeu-me (e a rainha estava sentada ao lado dele): \"Por quanto tempo ficarás fora e quando tu retornarás?\" O rei ficou feliz em me enviar quando eu lhe dei as datas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Então, eu disse ao rei: \"Se for do agrado do rei, que cartas possam ser entregues a mim para os governadores das províncias situadas além do rio, para que eles me permitam passar pelos seus territórios, no meu caminho para Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Que, dentre elas, haja também uma carta para Asafe, o guarda da floresta do rei, para que ele me dê madeira para fazer as vigas das portas da fortaleza perto do templo, e para o muro da cidade, e para a casa onde morarei\". Então, pela boa mão de Deus sobre mim, o rei atendeu aos meus pedidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Eu fui até os governadores das províncias situadas além do rio, e dei-lhes as cartas do rei. Ora, o rei tinha enviado comigo oficiais do exército e cavaleiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Quando Sambalate, o horonita, e Tobias, o oficial amonita, ouviram isso, eles ficaram muito irritados pelo fato de ter chegado alguém que queria ajudar o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Então, fui a Jerusalém, e fiquei lá por três dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Levantei-me à noite, eu e alguns poucos homens. Não contei a ninguém o que Deus tinha colocado no meu coração para fazer por Jerusalém. Não tinha nenhum animal comigo, além do animal no qual eu estava montado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Saí de noite pela porta do Vale, em direção à fonte do Dragão e pela porta do Esterco, e examinei os muros de Jerusalém, que haviam sido derrubados, e as portas de madeira haviam sido destruídas pelo fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Então, fui até à porta da Fonte, e para o tanque do rei. Mas, devido ao lugar ser muito estreito, não havia como passar com o animal no qual eu estava montado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Então, fomos naquela noite pelo vale e examinamos o muro, e eu voltei e entrei pela porta do Vale, e assim retornei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Os governantes não sabiam aonde eu tinha ido ou o que eu tinha feito, e eu ainda não tinha informado aos judeus, nem aos sacerdotes, nem aos nobres, nem aos governantes, e nem aos demais que fariam o trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Eu lhes disse: \"Vós vedes o problema em que estamos, como Jerusalém está em ruínas e como os seus portões foram destruídos pelo fogo. Vinde, vamos reconstruir o muro de Jerusalém para que não estejamos mais em desgraça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Contei-lhes que a boa mão do meu Deus estava sobre mim, e também sobre as palavras do rei, que ele me tinha dito. Eles disseram: \"Levantemo-nos e construamos\". Então, eles fortaleceram as mãos para a boa obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Mas, quando Sambalate, o horonita, e Tobias, o oficial, e Gesém, o árabe, ouviram isso, eles zombaram de nós, desprezaram-nos e disseram: \"O que vós estais fazendo? Vós estais vos rebelando contra o rei?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'E eu lhes respondi: \"O Deus dos céus nos fará bem-sucedidos. Nós somos os Seus servos e nos levantaremos e construiremos. Mas vós não tendes parte, nem direito e nem memorial em Jerusalém\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Então, Eliasibe, o sumo sacerdote, dispôs-se com seus irmãos sacerdotes, e eles reconstruíram a Porta das Ovelhas. Consagraram-na e colocaram as portas no lugar. Depois continuaram até consagrar a Torre dos Cem e prosseguiram até a Torre de Hananel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Perto dele trabalharam os homens de Jericó e, logo adiante deles, Zacur, filho de Inri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Os filhos de Hassenaá reconstruíram a Porta do Peixe. Colocaram as vigas no lugar e instalaram as portas com seus ferrolhos e trancas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Meremote reparou o trecho seguinte; ele é o filho de Urias, filho de Hacoz. E o próximo trecho foi reparado por Mesulão; ele é filho de Berequias, o qual é filho de Mesezabel. E o próximo trecho foi reparado por Zadoque; ele é filho de Baamá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Os tecoítas fizeram a reconstrução próximo deles, mas os líderes deles recusaram-se a fazer o trabalho ordenado pelos seus supervisores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Joiada, filho de Paseia, e Mesulão, filho de Besodeias, repararam a Porta Velha. Colocaram as vigas e puseram as portas, os ferrolhos e as trancas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Próximo a eles, Melatias, o gibeonita, e Jadom, o merenotita, homens de Gibeão e Mispá, fizeram reparos na porção onde o governador da província dalém do rio morava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Próximo a ele, Uziel, filho de Haraías, um dos ourives, fez a reconstrução; e, próximo a ele, estava Hananias, um perfumista. Eles reconstríram Jerusalém até o muro Largo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Refaías, filho de Hur, fez a reconstrução próximo a eles. Ele era o governador de metade do distrito de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Próximo a ele, Jedaías, filho de Harumafe, reconstruiu perto de sua casa. Próximo a ele reconstruiu Hatus, filho de Hasabneias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Malquias, filho de Harim, e Hassube, filho de Paate-Moabe, reconstruíram outro trecho juntamente com a Torre dos Fornos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Próximo a eles, Salum filho de Haloés, o governador da outra metade do distrito de Jerusalém, fizeram a reconstrução com a ajuda de suas filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Hanum e os moradores de Zanoa reconstruíram o Portão do Vale. Eles o reconstruíram, colocaram as portas, os ferrolhos e as trancas. Eles repararam mil côvados até o Portão do Esterco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Malquias, filho de Recabe, o governador do distrito de Bete-Haquerém, reparou a Porta do Esterco. Ele a construiu, colocou as portas, os ferrolhos e as trancas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Salum, filho de Col-Hoze, o governador do distrito de Mispá, reconstruiu a Porta da Fonte. Ele a construiu, a cobriu, colocou as portas, os ferrolhos e as trancas. Ele também reconstuiu o muro do tanque de Siloé, do jardim do rei, até os degraus que descem da cidade de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Neemias, filho de Azbuque, governador da metade do distrito de Bete-Zur, fez os reparos até em frente ao sepulcro de Davi, até o açude artificial, e até a casa dos soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Depois dele, os levitas, incluindo Reum, filho de Bani e próximo a ele Hasabias, o governador da metade do distrito de Queila, fizeram os reparos no seu distrito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Depois dele, seus compatriotas, incluindo Bavai, filho de Henadade, o governador da metade do distrito de Queila fizeram reparos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Próximo a ele Ézer, filho de Jesua, governador de Mispá, reparou outro trecho em frente à subida para a casa de armas, até a esquina do muro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Depois dele, Baruque, filho de Zabai, com muita dedicação fez reparos em outro trecho, desde a esquina do muro até a porta da casa de Eliasibe, o sumo sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Depois dele, Meremote, filho de Urias, filho de Hacoz, fez reparos em outro trecho, desde a porta da casa de Eliasibe até o fim dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Próximo a ele, os sacerdotes que habitavam nos arredores de Jerusalém fizeram reparos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Depois deles, Benjamim e Hassube fizeram reparos defronte de suas próprias casas. Depois deles Azarias, filho de Maaseias, filho de Ananias, fez reparos perto de sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Depois dele, Binuí, filho de Henadade fez reparos em outro trecho, desde a casa de Azarias até a esquina do muro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, filho de Uzai, fez reparos defronte da esquina e da torre que sai da casa real superior, perto do pátio da guarda. Após ele, Pedaías, filho de Parós, fez reparos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Os servos do templo que moravam em Ofel, fizeram reparos até defronte da Porta da Água ao leste da grande torre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Depois deles, os tecoítas fizeram reparos em outro trecho, oposto à grande torre, que sobressai até o muro de Ofel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Os sacerdotes fizeram reparos em cima da Porta dos Cavalos; cada um em frente à sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Depois deles Zadoque, filho de Imer, reparou o trecho em frente à sua própria casa. E, depois dele, Semaías, filho de Secanias, o guarda da porta leste, fez reparos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Depois deles, Hananias, filho de Selemias, e Hanum, o sexto filho de Zalafe, repararam outro trecho. Depois deles, Mesulão, filho de Berequias, fez reparos em frente à sua morada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Depois dele, Malquias, um dos ourives, fez reparos na casa dos servos do templo e dos mercadores que estava em frente à Porta da Guarda até a torre de vigia da esquina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'E os ourives e comerciantes fizeram reparos entre a torre de vigia da esquina e a Porta das Ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'E, quando Sambalate ouviu que estávamos construindo o muro, isso ardeu em seu interior, ficou furiosamente irado e zombou dos judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Na presença de seus irmãos e do exército de Samaria, ele disse: \"O que esses fracos judeus estão fazendo? Eles vão restaurar a cidade para eles mesmos? Irão oferecer sacrifícios? Irão finalizar o trabalho em um dia? Trarão à vida as pedras dos montes de entulhos, depois de terem sido queimadas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Tobias, o amonita estava com ele e lhe disse: \"Se apenas uma raposa subir no que estão construindo, isso poderia quebrar seu muro de pedra!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Ouve, nosso Deus, pois somos desprezados. Faze voltar as ofensas sobre suas próprias cabeças e entregue-os a serem saqueados em uma terra onde sejam prisioneiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Não cubras suas iniquidades e não apagues os seus pecados de diante de Ti, pois eles provocaram a ira dos que edificavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Então, nós construímos o muro em toda sua extensão até a metade da sua altura, porque o povo tinha ânimo para trabalhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Mas, quando Sambalate, Tobias, o árabe, os amonitas e os asdoditas ouviram que o trabalho de reparos dos muros de Jerusalém estava avançando e que os lugares quebrados no muro estavam sendo fechados, arderam-se em grande ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Todos eles conspiraram juntos; então vieram para lutar contra Jerusalém e causar nela confusão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Mas nós oramos ao nosso Deus e colocamos guardas para proteger-nos contra eles dia e noite, por causa das suas ameaças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Então, as pessoas de Judá disseram: \"A força daqueles que carregam os fardos está diminuindo, há muito entulho e nós não somos capazes de reconstruir o muro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'E nossos inimigos disseram: \"Eles não saberão ou não verão até que entremos no meio deles, e os matemos, e parem o trabalho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Naquele tempo, os judeus que moravam perto deles vieram de todas as direções e falaram conosco dez vezes, advertindo-nos do esquema que eles estavam tramando contra nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Então, posicionei pessoas nas partes mais baixas do muro, nas áreas expostas. Posicionei cada família com suas espadas, lanças e arcos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Então, olhei, coloquei-me de pé e disse aos nobres, aos governadores e ao resto do povo: \"Não tenhais medo deles. Lembrai-vos do Senhor, que é grande e maravilhoso. Lutai por vossas famílias, vossos filhos e vossas filhas, vossas esposas e vossas casas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'E aconteceu que, após nossos inimigos ouvirem que seus planos se tornaram conhecidos por nós e que Deus havia frustrado os deles, todos nós retornamos para o muro, cada um ao seu trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Desde aquele dia, metade dos meus servos trabalhavam exclusivamente para reconstruir o muro, e a outra metade dos homens segurava lanças, escudos e arcos e usavam armaduras, enquanto os líderes apoiavam todo o povo de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Os mesmos trabalhadores que construíam o muro e carregavam cargas também guardavam suas posições. Cada um trabalhava com uma mão e, com a outra mão, segurava uma arma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Cada construtor usava sua espada ao lado e era assim que trabalhava. O que tocava trombeta permanecia ao meu lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Eu disse aos nobres, aos oficiais, e ao resto do povo: \"O trabalho é grande e extenso, e nós estamos separados no muro, distantes uns do outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'Devei correr ao lugar de onde ouvirdes o som da trombeta e ajuntai-vos lá. Nosso Deus lutará por nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Então, nós estávamos fazendo o trabalho. A metade deles segurava lanças desde o alvorecer até o anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Eu também disse ao povo naquele tempo: \"Que cada homem e seu servo passe a noite no meio de Jerusalém, para que eles possam ser nossos guardas durante a noite e trabalhem durante o dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Então, nem eu, nem meus irmãos, nem meus servos, nem os homens da guarda que me seguiam, nenhum de nós trocou a roupa, e cada um de nós carregava sua arma, mesmo quando buscava água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Então, os homens e suas esposas levantaram um grande clamor contra seus companheiros judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Pois lá havia alguns que diziam: \"Nós com nossos filhos e filhas, somos muitos. Então, deixai-nos pegar grãos para que possamos comer e permaneçamos vivos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Também havia alguns que diziam: \"Estamos dando como garantia nossos campos, nossos vinhedos e nossas casas para obter grãos durante a fome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Alguns também diziam: \"Fizemos empréstimos de dinheiro para pagar o imposto do rei sobre nossos campos e nossos vinhedos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'No entanto, nós somos da mesma carne e sangue que nossos irmãos, e nossas crianças são as crianças deles. Somos forçados a vender nossos filhos e nossas filhas para que se tornem escravos. Algumas de nossas filhas já foram escravizadas. Mas não está em nosso poder ajudar porque agora, outros homens possuem nossos campos e nossos vinhedos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Eu fiquei muito irado quando ouvi seu clamor e essas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Então, pensei sobre isso e trouxe acusações contra os nobres e oficiais. Eu disse a eles: \"Vós cobrais juros, cada um de seu próprio irmão\". Organizei uma grande assembleia contra eles');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'e disse-lhes: \"Nós, tanto quanto fomos capazes, compramos de volta nossos irmãos judeus da escravidão, que foram vendidos às nações, mas vós mesmos vendem vossos irmãos e irmãs, para que eles sejam vendidos de volta a nós!\". Eles permaneceram em silêncio e não encontraram uma palavra para dizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Eu também disse: \"O que estão fazendo não é bom. Não devíeis caminhar no temor do nosso Deus, para evitar a difamação das nações que são nossas inimigas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Eu, meus irmãos e meus servos lhes estamos emprestando dinheiro e grãos. Mas devemos parar de cobrar juros sobre esses empréstimos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Devolvei a eles, hoje mesmo, seus campos, seus vinhedos, seus pomares de oliva, suas casas e a porcentagem do dinheiro, dos grãos, do vinho novo e do azeite que exigiram deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Então, eles disseram: \"Devolveremos o que tiramos deles e não exigiremos nada deles. Faremos como dizes\". Então, chamei os sacerdotes e os fiz jurar para fazerem como prometeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Sacudi a dobra do meu manto e disse: \"Então, que Deus sacuda da sua casa e das suas posses todo homem que não mantiver sua promessa. Que ele possa ser sacudido e esvaziado\". Toda a assembleia disse: \"Amém\", e eles louvaram a Yahweh, e o povo fez como haviam prometido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Então, desde o tempo em que fui indicado para ser o governador na terra de Judá, do vigésimo ano até o trigésimo-segundo ano do rei Artaxerxes, durante doze anos, nem eu nem meus irmãos comemos a comida fornecida para o governador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Mas os governadores anteriores, que estavam antes de mim, colocaram obrigações pesadas sobre o povo e tomaram deles quarenta siclos de prata por sua comida e vinho diários. Até os servos deles oprimiam o povo. Mas eu não fiz assim por causa do temor a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Eu também continuei a trabalhar no muro, e não compramos nenhuma terra. E todos os meus servos estavam reunidos lá para o trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'À minha mesa, estavam os judeus e os oficiais, cento e cinquenta homens, além daqueles que nos visitaram dentre as nações que estavam ao nosso redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Ora, o que era preparado a cada dia era um boi, seis ovelhas escolhidas e também aves e, a cada dez dias, todos os tipos de vinho em abundância. E, mesmo assim, para tudo isso, eu não exigi o alimento permitido do governador, porque as exigências eram muito pesadas sobre o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Lembra-te de mim, para o bem, meu Deus, por tudo o que eu fiz por esse povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Agora, quando Sambalate, Tobias e Gesém, o árabe, e o restante dos nossos inimigos ouviram que eu reconstruí o muro e que não havia mais nenhuma brecha deixada aberta, embora eu ainda não tivesse colocado as portas nos portões,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Sambalate e Gesém enviaram mensagem a mim, dizendo: \"Vem, encontremo-nos em algum lugar na planície de Ono\". Mas eles pretendiam fazer mal a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Eu enviei mensageiros a eles, dizendo: \"Estou fazendo um grande trabalho e não posso descer. Por que o trabalho seria interrompido enquanto eu o deixasse para descer até vós?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Eles me enviaram a mesma mensagem quatro vezes, e eu lhes respondi da mesma maneira cada vez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Sambalate enviou seu servo a mim da mesma maneira pela quinta vez, com uma carta aberta em sua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Nela estava escrito: \"É dito entre as nações, e Gesém também diz, que tu e os judeus estão planejando se rebelar, por isto estás reconstruindo o muro. Pelo que dizem estes relatos, tu estás para se tornar o rei deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'E tu também designaste profetas para proclamar sobre ti em Jerusalém, dizendo: \'Há um rei em Judá!\' Estejas certo de que o rei ouvirá este relato. Portanto vem, e falemos um com o outro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Então eu enviei uma mensagem para ele, dizendo: \"As coisas não aconteceram como disseste, pois, em teu coração, as inventaste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Pois todos eles queriam nos deixar com medo, pensando: \"Eles retirarão as mãos de fazer o trabalho, e não será concluído\". Mas agora, Deus, por favor, fortaleça minhas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Fui à casa de Semaías, filho de Delaías, filho de Meetabel, que estava em sua casa. Ele disse: \"Encontremo-nos na casa de Deus, dentro do templo, e fechemos as portas do templo, pois eles estão vindo para te matar. À noite, eles virão para matá-lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Respondi: \"Um homem, como eu, fugiria? E um homem, como eu, entraria no templo somente para salvar a própria vida? Eu não entrarei!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'E percebi que não era Deus que o enviou, mas que ele havia profetizado contra mim. Tobias e Sambalate o haviam contratado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Eles o contrataram para me deixar com medo, para que eu pudesse fazer o que ele disse e pecasse, então eles poderiam me dar uma má reputação a fim de me humilhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Lembra-te de Tobias e Sambalate, meu Deus, e de tudo o que eles fizeram. Também lembra-te da profetisa Noádia e do restante dos profetas que tentaram me amedrontar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Então o muro foi finalizado no vigésimo-quinto dia do mês de Elul, depois de cinquenta e dois dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Quando todos os nossos inimigos ouviram sobre isso, todas as nações ao nosso redor, eles ficaram com medo e sentiram-se humilhados. Pois eles sabiam que o trabalho foi feito com a ajuda do nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Também, naqueles dias, os nobres de Judá enviaram muitas cartas a Tobias, e as cartas de Tobias vieram até eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Pois havia muitos em Judá que eram vinculados a ele por um juramento, pois ele era o genro de Secanias, filho de Ara. Seu filho, Joanã, tinha tomado como sua esposa a filha de Mesulão, filho de Berequias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Eles também me falavam bem dele e relataram minhas palavras de volta a ele. Cartas foram enviadas a mim por Tobias para me amedrontar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Quando o muro foi concluído e eu havia colocado as portas no lugar, e os porteiros, os cantores e os levitas foram designados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'dei a meu irmão Hanani o encargo de administração de Jerusalém, juntamente com Hananias, que era chefe da fortaleza, pois ele era um homem fiel e temia a Deus mais que muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'E disse-lhes: \"Não abrais os portões de Jerusalém até que o sol esteja alto. Enquanto os porteiros estão em guarda, deveis fechar as portas e trancá-las. Designai guardas dos que moram em Jerusalém, alguns em seus postos de guarda e outros em frente a suas próprias casas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Ora, a cidade era ampla e grande, porém havia poucas pessoas nela e as casas não haviam sido reconstruídas ainda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Meu Deus colocou, em meu coração, de reunir os nobres, os oficiais e o povo para registrá-los conforme suas famílias. E encontrei o livro da genealogia daqueles que haviam retornado primeiro e nele achei escrito o seguinte:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, '\"Este é o povo da província que saiu do cativeiro em que Nabucodonosor, o rei da Babilônia, os levou para o exílio. Eles retornaram a Jerusalém e a Judá, cada um para sua cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Eles vieram com Zorobabel, Jesua, Neemias, Azarias, Raamias, Naamani, Mardoqueu, Bilsã, Misperete, Bigvai, Neum e Baaná. O número dos homens do povo de Israel incluía o seguinte:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'os descendentes de Parós, dois mil cento e setenta e dois;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'os descendentes de Sefatias, trezentos e setenta e dois;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'os descendentes de Ara, seissentos e cinquenta e dois;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'os descendentes de Paate-Moabe, por meio da descendência de Jesua e de Joabe, dois mil oitocentos e dezoito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'os descendentes de Elão, mil duzentos e cinquenta e quatro;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'os descendentes de Zatu, oitocentos e quarenta e cinco;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'os descendentes de Zacai, setecentos e sessenta;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'os descendentes de Binuí, seiscentos e quarenta e oito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'os descendentes de Bebai, seissentos e vinte e oito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'os descendentes de Azgade, dois mil trezentos e vinte e dois;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'os descendentes de Adonicão, seiscentos e sessenta e sete;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'os descendentes de Bigvai, dois mil e sessenta e sete;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'os descendentes de Adim, seiscentos e cinquenta e cinco;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'os descendentes de Ater, de Ezequias, noventa e oito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'os descendentes de Hasum, trezentos e vinte e oito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'os descendentes de Bezai, trezentos e vinte e quatro;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'os descendentes de Harife, cento e doze;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'os descendentes de Gibeão, noventa e cinco;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'os homens de Belém e de Netofá, cento e oitenta e oito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'os homens de Anatote, cento e vinte e oito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'os homens de Bete-Azmavete, quarenta e dois;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'os homens de Quiriate-Jearim, Cefira e Beerote, setecentos e quarenta e três;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'os homens de Ramá e Geba, seiscentos e vinte e um;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'os homens de Micmás, cento e vinte e dois;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'os homens de Betel e Ai, cento e vinte e três;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'os homens do outro Nebo, cinquenta e dois;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'o povo do outro Elão, mil duzentos e cinquenta e quatro;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'os homens de Harim, trezentos e vinte;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'os homens de Jericó, trezentos e quarenta e cinco;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'os homens de Lode, Hadide e Ono, setecentos e vinte e um;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'os homens de Senaá, três mil novecentos e trinta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Os sacerdotes: os descendentes de Jedaías (da casa de Jesua), novecentos e setenta e três;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'os descendentes de Imer, mil e cinquenta e dois;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'os descendentes de Pasur, mil duzentos e quarenta e sete;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'os descendentes de Harim, mil e dezessete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Os levitas: os descendentes de Jesua, por meio de Cadmiel, da descendencia de Binuí e de Hodevá, setenta e quatro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Os cantores: os descendentes de Asafe, cento e quarenta e oito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Os porteiros dos descendentes de Salum, os descendentes de Ater, os descendentes de Talmom, os descendentes de Acube, os descendentes de Hatita, os descendentes de Sobai, cento e trinta e oito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Os servos do templo: os descendentes de Zia, os descendentes de Hasufa, os descendentes de Tabaote,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'os descendentes de Queros, os descendentes de Sai, os descendentes de Padom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'os descendentes de Lebana, os descendentes de Hagaba, os descendentes de Salmai,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'os descendentes de Hanã, os descendentes de Gidel, os descendentes de Gaar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'os descendentes de Reaías, os descendentes de Rezim, os descendentes de Necoda,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'os descendentes de Gazão, os descendentes de Uzá, os descendentes de Paseia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'os descendentes de Besai, os descendentes de Meunim, os descendentes de Nefusesim;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'os descendentes de Baquebuque, os descendentes de Hacufa, os descendentes de Harur,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'os descendentes de Baslite, os descendentes de Meída, os descendentes de Harsa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'os descendentes de Barcos, os descendentes de Sísera, os descendentes de Tamá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'os descendentes de Nesias, os descendentes de Hatifa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Os descendentes dos servos de Salomão: os descendentes de Sotai, os descendentes de Soferete, os descendentes de Perida,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'os descendentes de Jaala, os descendentes de Darcom, os descendentes de Gidel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'os descendentes de Sefatias, os descendentes de Hatil, os descendentes de Poquerete-Hazebaim, os descendentes de Amom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Todos os servos do templo e os descendentes dos servos de Salomão, eram trezentos e noventa e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'E estes foram os que vieram de Tel-Melá, Tel-Harsa, Querube, Adom e Imer, porém eles não puderam provar que eles ou seus antepassados eram descendentes de Israel:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'os descendentes de Delaías, os descendentes de Tobias, e os descendentes de Necoda, seiscentos e quarenta e dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'E dos sacerdotes: os descendentes de Hobaías, de Hacoz e de Barzilai, o qual tomou como esposa uma das filhas de Barzilai, o gileadita, e passou a ser chamado por esse nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Estes buscaram seus registros entre aqueles que foram registrados segundo sua genealogia, todavia, não encontraram, por isso foram excluídos do sacerdócio como impuros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'E o governador disse-lhes que não deveriam ser autorizados a comer a quota de comida dos sacerdotes, provenientes dos sacrifícios, até que se levantasse um sacerdote com Urim e Tumim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Toda a assembleia reunida era quarenta e dois mil trezentos e sessenta,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'além dos seus servos e das suas servas, os quais eram sete mil trezentos e trinta e sete. Eles tinham duzentos e quarenta e cinco cantores e cantoras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Eles tinham setecentos e trinta e sete cavalos; duzentos e quarenta e cinco mulas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'quatrocentos e trinta e cinco camelos e seis mil setecentos e vinte jumentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Alguns dos chefes das famílias paternas deram ofertas para a obra. O governador deu à tesouraria mil dáricos de ouro, cinquenta bacias e quinhentos e trinta túnicas sacerdotais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Alguns dos chefes das famílias paternas deram para a tesouraria da obra vinte mil dáricos de ouro e duas mil e duzentas minas de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'O restante do povo deu vinte mil dáricos de ouro, duas mil minas de prata e sessenta e sete túnicas sacerdotais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Os sacerdotes, os levitas, os porteiros, os cantores, alguns do povo, os servos do templo e todo o Israel, estabeleceram-se em suas cidades. Ao sétimo mês, o povo de Israel estava instalado em suas cidades\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Todo o povo se reuniu como um só homem na praça em frente à Porta das Águas. Eles pediram que Esdras, o escriba, trouxesse o livro da Lei de Moisés, o qual Yahweh ordenou a Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'No primeiro dia do sétimo mês, Esdras, o sacerdote, trouxe a Lei perante a assembleia, homens e mulheres, e todos os que podiam ouvir e entender.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Ele se pôs diante da praça em frente à Porta das Águas, e leu desde manhã cedo até o meio dia, na presença de homens e mulheres, e de todo aquele que podia entendê-la. E todo o povo ouviu atentamente o Livro da Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Então, Esdras, o escriba, subiu num palco de madeira que o povo havia feito para aquele propósito. Estando de pé ao seu lado direito, Matitias, Sema, Anaías, Urias, Hilquias e Maaseias, e estando de pé ao seu lado esquerdo, Pedaías, Misael, Malquias, Hasum, Hasbadana, Zacarias e Mesulão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Esdras abriu o livro à vista de todo o povo, pois ele estava elevado acima do povo, e, quando ele o abriu, todo o povo levantou-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Esdras agradeceu a Yahweh, o grandioso Deus, e todo o povo levantou as mãos, e respondeu: \"Amém! Amém!\". Então, eles inclinaram suas cabeças e adoraram Yahweh com o rosto voltado para o chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Também Jesua, Bani, Serebias, Jamim, Acube, Sabetai, Hodias, Maaseias, Quelita, Azarias, Jozabade, Hanã, Pelaías —os levitas— ajudaram o povo a entender a Lei, enquanto o povo permanecia no seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Eles leram no livro, a Lei de Deus, tornando-a clara com a interpretação, e fornecendo o sentido para que eles entendessem a leitura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Neemias, o governador, e Esdras, o sacerdote e escriba, e os levitas que interpretavam disseram para o povo: \"Este dia é santo para Yahweh, vosso Deus. Não lamenteis, nem choreis\". Pois, todo o povo chorava enquanto ouvia as palavras da Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Então, Neemias disse-lhes: \"Ide, comei carnes gordas e bebei bebidas doces, e enviai porções para quem não tiver nada preparado, pois este dia é santo ao nosso Senhor. Não vos entristeçais, pois a alegria de Yahweh é a vossa força\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Então, os levitas fizeram o povo se aquietar, dizendo: \"Aquientem-se! Pois este dia é santo. Não vos entristeçais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Então, todo o povo foi comer, beber, repartir a comida e celebrar com grande alegria, porque eles entenderam as palavras que lhes foram explicadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'No segundo dia, os líderes das famílias dos antepassados de todo o povo, os sacerdotes e os levitas, vieram juntos a Esdras, o escriba, para aprenderem sobre as palavras da Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'E eles encontraram escrito na Lei como Yahweh tinha ordenado através de Moisés, que o povo de Israel deveria habitar em tendas durante a festa do sétimo mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Eles deveriam proclamar em todas as suas cidades e em Jerusalém, dizendo: \"Ide às montanhas, e trazei ramos de oliveira cultivadas, e de oliveiras silvestres, e de murtas, e folhas de palmeira e de árvores frondosas, para fazerem tendas, como está escrito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Então, as pessoas saíram e trouxeram os ramos; e fizeram para si tendas, cada um em seu próprio terraço, em seus pátios, e nos átrios da casa de Deus, e na praça da Porta das Águas, e na praça do Porta de Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'E a assembleia dos que tinham retornado do cativeiro fez tendas e habitou nelas. Pois, desde os dias de Josué, filho de Num, até aquele dia, o povo de Israel não havia celebrado essa festa. Por isso a alegria do povo foi muito grande.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'E dia após dia, desde o primeiro dia até o último, Esdras leu do livro da Lei de Deus. Eles celebraram a festa por sete dias, e no oitavo dia houve uma assembleia solene em obediência ao decreto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'No vigésimo quarto dia do mesmo mês, o povo de Israel se reuniu para um jejum usando roupas de saco e colocando pó sobre as suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Os descendentes de Israel separam-se de todos os estrangeiros. Eles se levantaram e confessaram os seus próprios pecados e as iniquidades dos seus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Eles se levantaram nos seus lugares, e por uma quarta parte do dia, leram o Livro da Lei de Yahweh, seu Deus. Na outra quarta parte do dia, eles ficaram confessando-se e curvando-se perante Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Os levitas Jesua, Bani, Cadmiel, Sebanias, Buni, Serebias, Bani e Quenani ficaram de pé nas escadas e chamaram em voz alta a Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Então, os levitas Jesua, Cadmiel, Bani, Hasabneias, Serebias, Hodias, Sebanias e Petaías disseram: \"Levantai-vos e louvai a Yahweh, vosso Deus, para sempre e sempre. Que eles bendigam ao Teu glorioso nome, e que seja exaltado acima de toda benção e louvor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Tu és Yahweh. Somente Tu. Tu fizestes o céu, os mais altos céus, com todos os seus exércitos, e a Terra e tudo o que nela há, e os mares e tudo o que neles há. Tu destes vida a todos, e os exércitos do céu Te adoram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Tu és Yahweh, o Deus que escolheu Abrão e o tirou de Ur dos caldeus e deu-lhe o nome de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Vistes que o coração dele era fiel diante de Ti e fizestes com ele uma aliança pela qual daria aos seus descendentes a terra dos cananeus, dos heteus, dos amorreus, dos perizeus, dos jebuseus e dos girgaseus. Tu cumpriste a Tua promessa porque És justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Tu vistes a aflição de nossos antepassados no Egito e ouvistes o seu clamor junto ao mar Vermelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Fizeste sinais e maravilhas contra o Faraó, todos os seus servos e todo o povo da sua terra, porque sabias que os egípcios agiam com arrogância contra eles. Mas Tu fizeste para Ti mesmo um nome, que permanece até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Tu dividiste o mar diante deles, de modo que passaram pelo meio do mar em terra seca; e lançaste os seus perseguidores nas profundezas, como uma pedra em águas profundas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Tu os guiaste com uma coluna de nuvem durante o dia, e uma coluna de fogo durante a noite, para iluminar o caminho onde deveriam ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'No monte Sinai Tu desceste e falaste com eles do céu e deste-lhes decretos justos e leis verdadeiras, bons estatutos e mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Tu fizeste conhecido a eles o Teu santo sábado e deste-lhes mandamentos, estatutos e leis através de Moisés, Teu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Tu deste-lhes pão do céu para sua fome e água da rocha para sua sede, e Tu lhes disseste para irem e tomarem posse da terra que juraste lhes dar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Mas eles e os nossos antepassados agiram desrespeitosamente, e foram teimosos e não escutaram os Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Eles se recusaram a escutar e não lembraram das maravilhas que fizeste entre eles, mas tornaram-se teimosos, e na sua rebeldia escolheram um líder para retornar à sua escravidão. Mas Tu és um Deus cheio de perdão, graça e compaixão, demoras a ficar irado e és cheio de amor. Tu não os abandonastes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Mesmo quando eles fundiram um bezerro de metal e disseram: \'Este é vosso Deus que vos tirou do Egito\', e cometeram grandes blasfêmias;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Tu, na Tua compaixão, não os abandonaste no deserto. A coluna de nuvem para guiá-los no caminho não os deixava durante o dia, e nem a coluna de fogo durante noite para iluminar o caminho em que eles deveriam andar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Tu deste o teu bom Espírito para instruí-los e o Teu maná Tu não negaste à boca deles, e deste água para a sede deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Por quarenta anos Tu proveste para eles no deserto e não lhes faltava nada. As suas roupas não envelheceram e os seus pés não incharam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Tu lhes deste reinos e povos, e distribuiste para eles cada canto da terra. Então, eles tomaram posse da terra de Siom, rei de Hesbom, e a terra do Ogue, rei de Basã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Tu fizestes os seus filhos tão numerosos quantos as estrelas do céu, e os trouxe para a terra que Tu falaste aos seus antepassados para entrar e possuir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Então, o povo entrou e possuiu a terra e Tu subjugaste diante deles os habitantes da terra, os cananeus. Tu os deste nas suas mãos, com os seus reis e os povos da terra, para que Israel pudesse fazer com eles o que bem quisesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Eles capturaram as cidades fortes e uma terra produtiva, e capturaram casas cheias de todo tipo de bens, cisternas já cavadas, vinhas e olivais e árvores frutíferas em abundância. Então, eles comeram e ficaram satisfeitos, e engordaram, e deleitaram-se em Tua grande bondade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Ainda assim, eles se tornaram desobedientes e se rebelaram contra Ti. Lançaram a Tua Lei para trás das costas. Eles assassinaram Teus profetas que os alertaram para voltar-se a Ti, e cometeram grandes blasfêmias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Então, Tu os entregaste nas mãos dos seus inimigos, que os fizeram sofrer. E no tempo do seu sofrimento, eles clamaram a Ti, e Tu os ouviste do céu; e, por causa das Tuas grandes misericórdias, Tu enviaste libertadores que os livraram das mãos dos seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Mas, depois que eles descansaram, fizeram o mal novamente diante de Ti, e Tu os abandonaste nas mãos dos seus inimigos; então os seus inimigos dominaram sobre eles. No entanto, quando eles retornaram e clamaram a Ti, Tu os ouviste do céu; muitas vezes, por causa da Tua compaixão, Tu os resgataste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Tu os alertaste para que voltassem à Tua Lei. Contudo eles agiram arrogantemente e não escutaram os Teus mandamentos. Eles pecaram contra os Teus decretos que dão vida a qualquer um que obedecê-los. Eles viraram as costas obstinadamente e endureceram seus pescoços e se recusaram a ouvir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Por muitos anos os suportaste e os advertiste pelo Teu Espírito através dos Teus profetas. Mesmo assim eles não escutaram. Então, Tu os entregaste nas mãos dos povos vizinhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Mas, nas Tuas grandes misericórdias, Tu não os destruíste completamente, nem os abandonaste, pois Tu és um Deus gracioso e misericordioso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Agora nosso Deus, o grande, o poderoso e maravilhoso Deus, que mantém a Sua aliança e grande amor, não deixe que pareça pequena para a Ti toda essa dificuldade que veio sobre nós, nossos reis, nossos príncipes, e sobre nossos sacerdotes e nossos profetas e nossos antepassados e todo o povo desde os dias dos reis da Assíria até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Tu és justo em tudo que nos tem acontecido, pois Tu tens agido com fidelidade, mas nós temos agido perversamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Nossos reis, nossos príncipes, nossos sacerdotes, e nossos antepassados não têm guardado a Tua Lei, nem prestado atenção aos Teus mandamentos ou aos decretos da Tua aliança pela qual Tu os advertiste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Mesmo no seu próprio reino, enquanto eles desfrutavam da Tua grande bondade para com eles, na grande e produtiva terra que Tu colocaste diante deles, eles não Te serviram ou deixaram os seus maus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Agora nós somos escravos na terra que deste aos nossos antepassados para desfrutar seus frutos e suas boas dádivas, e eis que nós somos escravos nela!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'A rica produção das nossas terras vai para os reis que Tu colocaste sobre nós por causa dos nossos pecados. Eles reinam sobre os nossos corpos e sobre o nossos gados como eles querem. Nós estamos em grande angústia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'Por causa de tudo isso, nós firmamos uma aliança por escrito. No documento selado estão os nomes dos nossos príncipes, levitas, e sacerdotes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Aqueles que puseram seus nomes nos documentos selados foram: Neemias, o governador, filho de Hacalias, Zedequias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Seraías, Azarias, Jeremias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pasur, Amarias, Malquias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hatus, Sebanias, Maluque,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harim, Meremote, Obadias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginetom, Baruque,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesulão, Abias, Miamim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maazias, Bilgai, e Semaías. Estes foram os sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Os levitas foram: Jesua, filho de Azanias, Binui, da família de Henadade, Cadmiel');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'e seus colegas levitas, Sebanias, Hodias, Quelita, Pelaías, Hanã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Mica, Reobe, Hasabias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zacur, Serebias, Sebanias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodias, Bani e Beninu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Os líderes do povo foram: Parós, Paate-Moabe, Elão, Zatu, Bani,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Buni, Azgade, Bebai,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonias, Bigvai, Adim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Ezequias, Azur,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodias, Hasum, Bezai,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Harife, Anatote, Nebai,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpias, Mesulão, Hezir,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesezabel, Zadoque, Jadua,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatias, Hanã, Anaías,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Oseias, Hananias, Hassube,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Haloês, Pílea, Sobeque,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Reum, Hasabna, Maaseias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Aías, Hanã, Anã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Maluque, Harim e Baaná.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'E o resto do povo, os que eram sacerdotes, levitas, porteiros, cantores, servos do templo, e todos os que tinham se separado do povo das terras vizinhas e se devotado à lei de Deus, inclusive suas esposas, seus filhos e suas filhas, todos os capazes de entender e compreender,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'eles se juntaram com seus irmãos e seus nobres, e se comprometeram juntos, sob pena de maldição e sob juramento, a andarem na lei de Deus, que foi entregue por Moisés, o servo de Deus, e a observarem e obedecerem todos os mandamentos de Yahweh nosso Senhor, seus decretos e seus estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'Nós prometemos que não daríamos nossas filhas aos povos da terra nem tomaríamos suas filhas para os nossos filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Nós também prometemos que, se o povo da terra trouxesse mercadoria ou qualquer grão para vender no dia de sábado, nós não compraríamos deles no sábado nem em qualquer dia santo. Todo sétimo ano deixaremos que nossos campos descansem e cancelaremos todas as dívidas contraídas por outros judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Nós aceitamos os mandamentos de dar a cada ano um terço de um siclo para o serviço da casa do nosso Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'de provê-la dos pães consagrados, das ofertas regulares de cereais, dos holocaustos, das ofertas para os sábados, para as festas de lua nova, para as festas fixas e também das ofertas sagradas e das ofertas pelo pecado, a fim de fazer propiciação por Israel, bem como para todo o trabalho da casa do nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Os sacerdotes, os levitas e o povo lançaram sortes para a oferta da lenha. As sortes lançadas escolheriam quais das nossas famílias trariam lenha para a casa de nosso Deus nos tempos estabelecidos a cada ano. A lenha seria queimada no altar de Yahweh, nosso Deus, como está escrito na lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Prometemos trazer à casa de Yahweh os primeiros frutos produzidos do nosso solo e os primeiros frutos de todas as árvores a cada ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'E como está escrito na lei, prometemos trazer à casa de Deus e aos sacerdotes que alí servem os primogênitos dos nossos filhos e dos nossos rebanhos de gado, ovelhas e cabras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Nós traremos as primícias da nossa massa de trigo, de nossas ofertas de cereal e do fruto de toda árvore. E as primícias do vinho novo e do óleo nós traremos aos sacerdotes, aos depósitos da casa do nosso Deus. Nós traremos aos levitas os dízimos do nosso solo, porque os levitas recolhem os dízimos em todas as cidades onde nós trabalhamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Um sacerdote, descendente de Arão, deverá estar com os levitas quando eles receberem os dízimos. Os levitas devem trazer a décima parte dos dízimos à casa do nosso Deus, aos depósitos da tesouraria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'E o povo de Israel e os descendentes de Levi devem trazer as contribuições de cereais, vinho novo e óleo aos armazéns onde estão guardados os utensílios do santuário e onde os sacerdotes estão servindo e os porteiros e os cantores ficam. Nós não vamos negligenciar a casa do nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Os líderes do povo viviam em Jerusalém, e o restante do povo lançou sorte para trazer uma entre cada dez pessoas para viver em Jerusalém, a cidade santa, e as outras nove restantes permaneceriam em outras cidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'E o povo abençoou todos aqueles que se ofereceram de boa vontade para morar em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Estes são os oficiais das províncias que viviam em Jerusalém. Entretanto, nas cidades de Judá, cada qual vivia em sua própria terra, incluindo alguns israelitas, sacerdotes, levitas, servos do templo e descendentes dos servos de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Em Jerusalém viviam alguns dos descendentes de Judá e alguns dos descendentes de Benjamim. O povo de Judá incluía: Ataías, filho de Uzias, filho de Zacarias, filho de Amarias, filho de Sefatias, filho de Maalelel, descendente de Perez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'E havia Maaseias, filho de Baruque, filho de Col-Hose, filho de Hazaías, filho de Adaías, filho de Joiaribe, filho de Zacarias, filho do silonita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Todos os filhos de Perez que viviam em Jerusalém eram quatrocentos e sessenta e oito. Eles eram homens valentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Estes são os descendentes de Benjamim: Salu, filho de Mesulão, filho de Joede, filho de Pedaías, filho de Colaías, filho de Maaseias, filho de Itiel, filho de Jesaías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'E, após ele, Gabai e Salai, um total de novecentos e vinte e oito homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Joel, filho de Zicri era superintendente sobre eles, e Judá filho de Senua era o segundo no governo da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'E dos sacerdotes: Jedaías, filho de Joiaribe, Jaquim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraías, filho de Hilquias, filho de Mesulão, filho de Zadoque, filho de Meraiote, filho de Aitube, príncipe da casa de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'e seus companheiros que faziam o trabalho da casa, oitocentos e vinte e dois homens. Seguindo vem Adaías, filho de Jeroão, filho de Pelalias, filho de Anzi, filho de Zacarias, filho de Pasur, filho de Malquias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'Seus irmãos, que eram os cabeças das familias, duzentos e quarenta e dois homens, e Amassai, filho de Azarel, filho de Aazai, filho de Mesilemote, filho de Imer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'e seus irmãos, homens valentes e corajosos, cento e vinte e oito em número, e o superintendente sobre eles era Zabdial, filho de Gedolim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Dentre os levitas: Semaías, filho de Hassube, filho de Azricão, filho de Hasabias, filho de Buni,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'e Sabetai e Jozabade, que vinham dos líderes dos levitas e estavam com a responsabilidade do trabalho externo da casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'E havia Matanias, filho de Mica, filho de Zabdi, filho de Asafe, que era o diretor que liderava os momentos de ações de graças na oração, e Babebuquias, o segundo entre seus irmãos, e Abda, filho de Samua, filho de Galal, filho de Jedutum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Todos os levitas na cidade santa eram duzentos e oitenta e quatro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Os porteiros eram: Acube, Talmon e seus irmãos que guardavam as portas, cento e setenta e dois homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'E os restantes de Israel e dos sacerdotes e levitas estavam em todas as cidades de Judá. Cada um vivia na propriedade da sua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Os trabalhadores do templo moravam em Ofel, e Ziá e Gispa eram os chefes deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'O superintendente dos levitas que serviam em Jerusalém era Uzi, filho de Bani, filho de Hasabias, filho de Matanias, filho de Mica, dos descendentes de Asafe, que eram cantores no serviço da casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Eles estavam debaixo da autoridade do rei. Todos os dias, eram dadas ordens firmes para os cantores, conforme se requeria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'E Petaías, filho de Mesezabel, da descendência de Zerá, filho de Judá, estava ao lado do rei em todas as questões referentes ao povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'E sobre as vilas e seus campos, alguns do povo de Judá viviam em Quiriate-Arba e suas vilas, em Dibom e suas vilas, e em Jecabzeel e suas vilas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'Eles também viviam em Jesua, Molada, em Bete-Palete,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'em Hasar-Sual e em Berseba e suas vilas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'Alguns do povo de Judá viviam em Ziclague, Mecona e em suas vilas:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'En-Rimom, Zorá, Jarmute;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Zanoa, Adulão e suas vilas, em Laquis e seus campos e Azeca e suas vilas. E assim eles viviam desde Berseba até o vale de Hinom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'O povo de Benjamim também vivia em Geba, Micmás, Aia, Betel e suas vilas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Eles também viviam em Anatote, Nobe, Ananias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hazor, Ramá, Gitaim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadide, Zeboim, Nebalate,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lode e Ono, o vale dos artífices.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Alguns dos levitas que viviam em Judá estavam distribuídos também entre o povo de Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Estes são os sacerdotes e os levitas que voltaram com Zorobabel, filho de Sealtiel, e com Jesua: Seraías, Jeremias, Esdras,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarias, Maluque, Hatus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Secanias, Reum e Meremote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Estavam também Ido, Ginetom, Abias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Miamim, Maadias, Bilga,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaías, Joiaribe e Jedaías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Salu, Amoque, Hilquias e Jedaías. Esses eram os líderes dos sacerdotes e os seus companheiros, nos dias de Jesua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Os levitas eram Jesua, Binui, Cadmiel, Serebias, Judá e Matanias, que estavam encarregados dos cânticos de ações de graças, junto com os seus companheiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Baquebuquias e Uni, seus companheiros, ficaram à frente deles durante o culto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jesua era o pai de Joiaquim, Joiaquim era o pai de Eliasibe, Eliasibe era o pai de Joiada,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Joiada era o pai de Jonatã, e Jonatã era o pai de Jadua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Nos dias de Joiaquim, estes eram os sacerdotes, os chefes de famílias: Meraías era o líder da família de Seraías, Hananias era o líder da família de Jeremias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Mesulão era o líder da família de Esdras, Jeoanã era o líder da família de Amarias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Jonatã era o líder da família de Maluqui e José era o líder da família de Sebanias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Adna era o líder da família de Harim, Helcai era o líder da família de Meraiote,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Zacarias era o líder da família de Ido, Mesulão era o líder da família de Ginetom, e');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Zicri era o líder da família de Abias. Havia também o líder da família de Miniamim.. Piltai era o líder da família de Maadias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Samua era o líder da família de Bilga, Jeonatã era o líder da família de Semaías,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Matenai era o líder da família de Joiaribe, Uzi era o líder da família de Jedaías,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Calai era o líder da família de Salai, Eber era o líder da família de Amoque,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Hasabias era o líder da família de Hilquias, e Netanel era o líder da família de Jedaías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Nos dias de Eliasibe, os levitas Eliasibe, Joiada, Joanã e Jadua foram resgistrados como chefes de famílias, e os sacerdotes foram registrados durante o reinado de Dario, o persa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Os descendentes de Levi e os chefes das suas famílias foram registrados no livro das crônicas, até os dias de Joanã, filho de Eliasibe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Os líderes dos levitas eram Hasabias, Serebias e Jesua, filho de Cadmiel, com seus companheiros que ficaram à frente deles para louvarem e darem graças, respondendo seção por seção, em resposta à ordem de Davi, o homem de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Matanias, Baquebuquias, Obadias, Mesulão, Talmom e Acube eram os porteiros que guardavam os armazéns dos portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Eles serviram nos dias de Joiaquim, filho de Jesua, filho de Jozadaque, e nos dias de Neemias, o governador, e de Esdras, o sacerdote e escriba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Na dedicação do muro de Jerusalém, o povo procurou levitas de todos os lugares, para trazê-los à Jerusalém para celebrar a dedicação com alegria, com ações de graças e cantando com címbalos, harpas e com liras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Os cantores se ajuntaram vindo dos arredores de Jerusalém e das vilas dos netofatitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Eles também vieram de Bete-Gilgal e dos campos de Geba e Azmavete, pois os cantores tinham construído para si mesmos vilas ao redor de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Os sacerdotes e os levitas se purificaram e, então, purificaram o povo, os portões e o muro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Então, fiz os líderes de Judá subirem até o topo do muro e formei dois grandes coros, que davam graças. Um deles foi para a direita do muro em direção à porta do Esterco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Hosaías e metade dos líderes de Judá os seguiram,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'e depois deles foram Azarias, Esdras, Mesulão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Judá, Benjamim, Semaías, Jeremias');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'e alguns dos filhos dos sacerdotes com trombetas, e Zacarias, filho de Jônatas, filho de Semaías, filho de Matanias, filho de Micaías, filho de Zacur, filho de Asafe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'Estavam também os parentes de Zacarias, Semaías, Azarel, Milalai, Gilalai, Maai, Netanel, Judá, Hanani, com os instrumentos de música de Davi, o homem de Deus. Esdras, o escriba, estava na frente deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Na Porta da Fonte, eles subiram as escadas da cidade de Davi, pelas escadas que levavam ao muro acima do palácio de Davi, até a Porta das Águas, ao leste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'O outro coro, daqueles que davam graças, foi na outra direção. Eu segui por cima do muro, com metade do povo, pela torre dos Fornos, até a muralha Larga,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'e pela Porta de Efraim, e pela porta Velha, e pela Porta do Peixe, e pela torre de Hananel, e pela torre dos Cem, até a Porta das Ovelhas; e eles pararam na Porta da Guarda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Assim, ambos os coros daqueles que davam graças posicionaram-se no seu lugar na casa de Deus, e eu também posicionei-me no meu lugar, com metade dos oficias comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'E os sacerdotes posicionaram-se no seu lugar: Eliaquim, Maaseias, Miniamim, Micaías, Elioenai, Zacarias e Hananias, com as trombetas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'Maaseias, Semaías, Eleazar, Uzi, Jeoanã, Malquias, Elão e Ézer. Os cantores cantavam sob a regência de Jezraías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'E eles ofereceram grandes sacrifícios naquele dia e se alegraram, pois Deus lhes fez alegrar com grande alegria. As mulheres e as crianças também se alegraram. Então, a alegria de Jerusalém podia ser ouvida de longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Naquele dia, homens foram designados para cuidar dos depósitos para as contribuições, os primeiros frutos e os dízimos dos campos das cidades, para colocar neles as porções exigidas por lei para os sacerdotes e para os levitas. Pois Judá estava alegre por causa dos sacerdotes e dos levitas que estavam diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Eles realizaram o serviço do seu Deus e o serviço da purificação, e assim também fizeram os cantores e os porteiros, conforme o mandamento de Davi e de Salomão, seu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Há muito tempo, nos dias de Davi e Asafe, havia os regentes dos cantores, e havia canções de louvor e ações de graças para Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Nos dias de Zorobabel e nos dias de Neemias, todo o Israel dava as porções diárias para os cantores e para os porteiros. Eles separavam a porção que era para os levitas, e os levitas separavam a porção que era para os descendentes de Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Naquele dia, eles leram o livro de Moisés diante do povo. Foi encontrado nos escritos que nenhum dos amonitas ou moabitas deveria juntar-se ao povo de Deus, para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Isso ocorreu porque eles não vieram até o povo de Israel com pão e com água, mas contrataram Balaão para amaldiçoar Israel. Contudo, nosso Deus transformou a maldição em bênção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Assim que eles ouviram a Lei, separaram de Israel cada pessoa estrangeira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Antes disso, o sacerdote Eliasibe tinha sido encarregado dos depósitos da casa do nosso Deus. Ele era parente de Tobias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Eliasibe preparou para Tobias uma sala grande onde, anteriormente, eles guardavam as ofertas de cereais, o incenso, os utensílios, os dízimos dos cereais, vinho novo e o óleo, que foram designados para os levitas, os cantores, os porteiros, e as contribuições para os sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Mas, durante todo esse tempo, eu não estava em Jerusalém. No trigésimo segundo ano do reinado de Artaxerxes, rei da Babilônia, fui ao rei. Depois de algum tempo, pedi ao rei permissão para partir,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'e, então, retornei para Jerusalém. Eu percebi o mal que Eliasibe havia feito, dando a Tobias uma sala no pátio da casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Eu estava muito irado e lancei todos os artigos domésticos da casa de Tobias para fora da sala.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Ordenei que purificassem as salas e recoloquei nelas os utensílios da casa de Deus, as ofertas de cereais e o incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Fiquei sabendo que as porções dos levitas não lhes estavam sendo dadas, e que retornaram cada um para o seu campo, os levitas e os cantores que faziam a obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Então, confrontei os oficiais e disse: \"Por que a casa de Deus é negligenciada?\". Juntei-os e os coloquei nos seus postos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Então, todo o Judá trouxe o dízimo dos cereais, o vinho novo e o azeite para os depósitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Designei como tesoureiros dos depósitos Selemias, o sacerdote, e Zadoque, o escriba; e dos levitas, Pedaías. Junto a eles estavam Hanã, filho de Zacur, filho de Matanias, pois eram considerados confiáveis. Seus deveres eram distribuir os suprimentos a seus colegas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Lembra-te, meu Deus, a respeito disso e não esqueças as boas obras que fiz para a casa de Deus e seus cultos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Naqueles dias, vi em Judá o povo pisando lagar no sábado, trazendo montões de cereais que eram carregados sobre os jumentos como também vinho, uvas, figos e todo tipo de carga pesada que traziam à Jerusalém no dia de sábado. Eu protestei por estarem vendendo alimento naquele dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Homens de Tiro que moravam em Jerusalém trouxeram peixes e todo o tipo de mercadorias e as vendiam no sábado para as pessoas de Judá e na cidade!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Então, confrontei os líderes de Judá: \"Que mal é este que estais fazendo, profanando o dia de sábado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Acaso vossos pais também não fizeram isso? E nosso Deus não trouxe todo este mal sobre nós e sobre esta cidade? Agora, estais trazendo ira sobre Israel, profanando o sábado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Quando escureceu sobre os portões de Jerusalém, antes do sábado, ordenei que as portas fossem fechadas e que não fossem abertas até depois do sábado. Posicionei alguns dos meus servos nos portões, para que nenhuma carga pudesse entrar no dia de sábado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Os mercadores e vendedores de todos os tipos de mercadorias acamparam fora de Jerusalém uma ou duas vezes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Mas eu lhes avisei: \"Por que vós acampastes fora do muro? Se o fizerdes novamente, eu lançarei mão sobre vós!\". Daquele tempo em diante, não tornaram a vir no sábado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Então, ordenei aos levitas que se purificassem e viessem guardar as portas, para santificar o dia de sábado. Também nisso, Deus meu, lembra-te de mim; e tem misericórdia de mim, por causa da Aliança de lealdade que tens mostrado a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Naqueles dias, também vi Judeus que haviam se casado com mulheres de Asdode, Amom e Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Metade dos filhos deles falavam a língua de Asdode. Nenhum deles podia falar a língua de Judá, mas somente a língua de um dos outros povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Eu os confrontei e os amaldiçoei, bati em alguns deles e arranquei-lhes os cabelos. Eu os fiz jurar por Deus, dizendo: \"Não deis vossas filhas aos filhos deles, nem tomareis as filhas deles para os vossos filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Salomão, rei de Israel, não pecou por causa dessas mulheres? Entre muitas nações não havia rei como ele, e ele foi amado pelo seu Deus, e Deus o fez rei sobre todo o Israel. No entanto, suas esposas estrangeiras fizeram com que ele pecasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Deveríamos, então, escutar-vos, fazer todo esse mal e agir de maneira traiçoeira contra nosso Deus, casando-nos com mulheres estrangeiras?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Um dos filhos de Joiada, filho de Eliasibe, o sumo sacerdote, era genro de Sambalate, o horonita. Por isso fiz com que ele fugisse da minha presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Lembra-te deles, meu Deus, porque contaminaram o sacerdócio, a aliança do sacerdócio e os levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Assim, eu os purifiquei de todas as coisas estrangeiras e estabeleci deveres para os sacerdotes e os levitas, cada um na sua própria tarefa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'Providenciei também deveres para a oferta de madeiras nos tempos designados e para as prímicias. Lembra-te de mim, meu Deus, para meu o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Isto aconteceu nos dias de Xerxes (este é o Assuero que reinou da Índia até a Etiópia, sobre mais de cento e vinte e sete províncias).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Naqueles dias, o rei Xerxes reinava em seu trono real na cidadela de Susã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'No terceiro ano de seu reinado, ele deu um banquete para todos os seus oficiais e seus servos. O exército da Pérsia e da Média, os nobres e os governadores das províncias estavam em sua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Ele mostrou a riqueza do esplendor de seu reino e a honra gloriosa de sua majestade, por muitos dias, por cento e oitenta dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Quando se completaram esses dias, o rei deu um banquete com duração de sete dias. O banquete foi para todo o povo na fortaleza de Susã, do maior ao menor. Foi feito nos pátios do jardim do palácio do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'O pátio do jardim foi decorado com cortinas de algodão branco e violeta, com cordões de linho fino e púrpura, argolas de prata pendentes nos pilares de mármore. Havia assentos de ouro e prata em um pavimento mosaico de granito, mármore, madrepérola e pedras preciosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Bebidas eram servidas em taças de ouro e cada taça era única; havia muito vinho real por causa da generosidade do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'E bebiam conforme foi decretado: \"Não deverá haver limite\". O rei deu ordens a todos os mordomos do palácio que servissem o que cada convidado desejasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'A rainha Vasti também deu um banquete para as mulheres no palácio real do rei Xerxes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'No sétimo dia, quando o coração do rei se sentia feliz por causa do vinho, ordenou que Meumã, Bitza, Harbona, Bigtá, Abagta, Zetar e Carcas, os sete oficais que serviam ao rei,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'que trouxessem a rainha Vasti diante dele com sua coroa real. Ele queria mostrar, ao povo e aos oficiais, sua beleza, pois ela era muita bonita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Porém, a rainha Vasti recusou-se a atender a palavra do rei, trazida a ela por seus oficiais. O rei ficou muito irado; sua raiva ardia dentro dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Então, o rei consultou os homens que eram conhecidos por serem sábios, que entendiam os tempos (este era o procedimento do rei com todos aqueles que entendiam das leis e dos costumes dos persas).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'E os mais próximos a ele eram Carsena, Setar, Admata, Társis, Meres, Marsena e Memucã, os sete príncipes da Pérsia e Média. Eles tinham acesso ao rei, e ocupavam os cargos mais importante do reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, '\"De acordo com a lei, o que deve ser feito à rainha Vasti por não obedecer a ordem do rei Xerxes, dada a ela pelos oficiais?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Memucã disse na presença do rei e dos oficiais: \"A rainha não errou somente contra o rei, mas também contra todos os oficiais e todo o povo nas províncias do rei Xerxes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Pois, o que a rainha fez chegará ao conhecimento de todas as mulheres. Isso fará com que elas tratem os seus maridos com desprezo. Elas dirão: \'o rei Xerxes ordenou que a rainha Vasti fosse trazida à sua presença, mas ela se recusou\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Antes do fim deste dia, as mulheres nobres da Pérsia e Média que ouvirem o que a rainha fez dirão o mesmo a todos os oficiais do rei. Haverá muito desprezo e ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Se for do agrado do rei, faça um decreto real, que seja escrito conforme as leis dos medos e persas, que não pode ser revogada, que Vasti não mais venha à presença do rei. Que o rei dê sua posição à outra que seja melhor que ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Quando o decreto do rei for proclamado através de todo o seu grande reino, todas as esposas honrarão seus maridos, dos mais ricos aos mais pobres\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'O rei e seus nobres agradaram-se deste conselho e o rei fez o que Memucã propôs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Ele enviou cartas a todas as províncias em suas próprias línguas. Ordenou que todo homem deveria ser senhor de sua própria família. Este decreto foi dado na língua de cada povo no império.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Depois dessas coisas, quando a ira do rei Xerxes diminuiu, ele pensou sobre Vasti e o que ela havia feito. Ele também pensou sobre o decreto que havia feito contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Então, os jovens do rei que lhe serviam disseram: \"Deixe que se procure moças bonitas e virgens para o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Que o rei nomeie oficiais em todas as províncias de teu reino, para juntar todas as moças virgens e bonitas para teu harém no palácio em Susã. Que sejam colocadas sob o cuidado de Hegai, o oficial do rei, que é responsável pelas mulheres, e que elas recebam tratamento de beleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Que a moça que agradar ao rei se torne a rainha em lugar de Vasti\". Este conselho agradou o rei e, assim, ele fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Havia um certo judeu na cidade de Susã, cujo nome era Mardoqueu, filho de Jair, filho de Simei, filho de Quis, que era um benjamita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Ele havia sido levado de Jerusalém com os exilados, junto aos que foram levados com Jeconias, rei de Judá, a quem Nabucodonosor, rei da Babilônia, levou embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Ele estava cuidando de Hadassa, que é Ester, filha do seu tio, porque ela não tinha pai nem mãe. A moça era muito bonita e atraente. Mardoqueu a criou como sua própria filha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Quando a ordem e o decreto do rei foram proclamados, muitas moças foram trazidas para o palácio em Susã. Elas foram colocadas sob o cuidado de Hegai. Ester também foi levada para dentro do palácio do rei e colocada sob o cuidado de Hegai, o encarregado das mulheres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'A moça lhe agradou e ganhou o seu favor. Imediatamente, ele providenciou um tratamento de beleza para ela e sua porção de comida. Ele designou para ela sete servos das moças no palácio do rei e a transferiu, juntamente com os servos das moças, para o melhor lugar da casa das mulheres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Ester não havia dito a ninguém sobre quem era seu povo ou sua família, porque Mardoqueu lhe tinha instruído que não dissesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Todos os dias, Mardoqueu passava em frente do pátio, fora da casa das mulheres, para saber sobre o bem estar de Ester, e sobre o que teria acontecido com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Quando chegava o momento de cada moça ir ao rei Xerxes (obedecendo os regulamentos das mulheres, cada moça tinha que completar doze meses do tratamento de sua beleza, seis meses com óleo de mirra e seis com perfumes e cosméticos),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'quando a jovem ia ao rei, o que quer que desejasse era dado a ela na casa das mulheres, para que levasse ao palácio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'À noite, ela poderia ir e, pela manhã, deveria retornar para a segunda casa das mulheres, aos cuidados de Saasgaz, o oficial do rei, que era encarregado pelas concubinas. Ela não retornaria para o rei novamente, a menos que o tivesse agradado muito e que ele mandasse chamá-la pelo nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Então, quando chegou a vez de Ester, filha de Abiail, tio de Mardoqueu, que a havia criado como sua própria filha, ir ao rei, não pediu nada senão o que Hegai, o oficial do rei, que era encarregado pelas mulheres, sugeriu. E Ester ganhou o favor de todos que a viram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Ester foi levada ao rei Xerxes, para dentro da residência real, no décimo mês, que era o Mês de Tebete, no sétimo ano do seu reinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'O rei amou Ester mais que a todas as outras mulheres, e ela alcançou favor e bondade diante dele, mais que todas as outras virgens. Assim, ele pôs a coroa real em sua cabeça e a fez rainha no lugar de Vasti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'O rei deu um grande banquete para todos seus oficiais e seus servos — o banquete de Ester. Ele liberou de impostos as províncias; e também deu presentes com sua generosidade real.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Quando as virgens foram reunidas pela segunda vez, Mardoqueu estava sentado à porta do palácio do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Ester ainda não havia contado a ninguém sobre sua família ou seu povo, como Mardoqueu tinha instruído. Ela continuou seguindo o conselho de Mardoqueu, como tinha feito quando foi criada por ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'Naqueles dias, enquanto Mardoqueu estava sentado à porta do palácio do rei, dois oficiais do rei, Bigtã e Teres, que guardavam a entrada, ficaram revoltados e procuraram matar o rei Xerxes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Quando o assunto foi revelado a Mardoqueu, ele disse à rainha Ester, e Ester falou ao rei em nome de Mardoqueu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'A informação foi investigada e confirmada, e ambos os homens foram enforcados. A história foi escrita no Livro das Crônicas na presença do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Depois dessas coisas, o rei Xerxes promoveu Hamã, filho de Hamedata, o agagita, e colocou sua posição de autoridade sobre todos os oficiais que estavam com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Todos os servos do rei, que serviam nos portões do rei, sempre ajoelhavam e prostravam-se para Hamã, como o rei lhes havia ordenado para fazer; porém Mardoqueu não se ajoelhava nem se prostrava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Então, os servos do rei que estavam nos portões do rei disseram a Mardoqueu: \"Por que desobedeces a ordem do rei?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Eles lhe falavam dia após dia, mas ele se recusava a obedecer suas ordens. Então, eles falaram com Hamã para ver se o procedimento de Mardoqueu seria tolerado, porque ele lhes havia dito que era judeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Quando Hamã viu que Mardoqueu não se ajoelhava nem prostava diante dele, encheu-se de raiva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Sabendo a que povo Mardoqueu pertencia, desprezou a ideia de matar somente a ele, porque os servos do rei lhe falaram a que povo Mardoqueu pertencia. Hamã queria exterminar todos os judeus, o povo de Mardoqueu, que estava em todo o reino de Xerxes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'No primeiro mês, que é o Mês de Nisã, no décimo segundo ano do rei Xerxes, eles lançaram o pur, que quer dizer \"lançar sorte\", diante de Hamã, dia a dia e mês a mês, para selecionar o mês, até que eles escolheram o décimo segundo, o Mês de Adar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Então, Hamã disse para o rei Xerxes: \"Existe um certo povo espalhado e distribuído entre as províncias do teu reino; suas leis são diferentes das leis dos outros povos, e eles não obedecem às leis do rei. Então, não é adequado para o rei deixá-los viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Se isso for do agrado do rei, dá ordem para matá-los, e eu pesarei dez mil talentos de prata nas mãos daqueles que serão encarregados dos assuntos do rei, para que eles coloquem na tesouraria do rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Então, o rei tirou o anel de selar de sua mão, e o deu a Hamã, filho de Hamedata, o agagita, inimigo dos judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'E disse o rei para Hamã: \"Esse dinheiro seja dado de volta para ti, e também esse povo, para fazeres dele o que desejares\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Então, foram chamados os escribas do rei, no décimo terceiro dia do primeiro mês. Conforme tudo o que Hamã havia ordenado, foi escrito para os governadores de todas as províncias, para os governadores de todos os povos, e também aos oficiais de todos os povos; para cada província em sua própria escrita, e para todo povo em sua própria lingua. Em nome do rei Xerxes, foi escrito e selado com seu anel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Enviaram os documentos pelos correios para todas as províncias do rei, para aniquilar, matar e destruir todos os judeus, tanto jovens e velhos como crianças e mulheres, em um dia, no décimo terceiro dia do décimo segundo mês, o Mês de Adar, e recolher suas posses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Uma cópia do documento foi feita, como lei, para cada província. Em cada província se fez saber que o povo deveria estar preparado para aquele dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Os mensageiros saíram e, apressados, distribuíram a ordem do rei; o decreto também foi distribuído dentro do palácio de Susã. O rei e Hamã se assentaram para beber, mas a cidade de Susã estava tumultuada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Quando Mardoqueu soube tudo o que havia acontecido, ele rasgou suas vestes, vestiu-se de panos de saco, cobriu-se de cinzas, foi para o meio da cidade e chorou com um alto e amargo choro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Ele foi até os portões do palácio do rei, porque ninguém poderia entrar vestido de panos de saco pelas portas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Em toda província, onde quer que a ordem e o decreto alcançassem, havia grande luto entre os judeus, com jejum, choro e lamento. Muitos deles ficaram com pano de saco e cinzas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Quando as criadas de Ester e os eunucos vieram informá-la, a rainha ficou angustiada. Ela enviou vestuários para Mardoqueu, para que ele tirasse seus panos de sacos, mas ele não aceitou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Então, Ester chamou por Hatá, um dos eunucos do rei, que fora designado para servi-la; ela ordenou que ele fosse até Mardoqueu e soubesse o que havia acontecido, e o que significava aquilo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Saiu Hatá para falar com Mardoqueu na praça da cidade, diante dos portões do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Mardoqueu lhe relatou tudo o que acontecera, e o total da prata que Hamã prometera depositar na tesouraria do rei, a fim de destruir os judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Também lhe deu uma cópia do decreto publicado em Susã, para a destruição dos judeus, a fim de que Hatá mostrasse a Ester, dando a ela a responsabilidade de ir ao rei suplicar por sua misericórdia, em favor do seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Saiu Hatá e falou para Ester o que Mardoqueu dissera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Então, Ester falou a Hatá que voltasse a Mardoqueu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Ela disse: \"Todos os servos do rei e o povo das províncias do rei sabem que qualquer homem ou mulher que vá ao rei, até o interior do pátio, sem ser chamado, para ele há somente uma lei: \'morrerá\'; exceto para aquele a quem o rei estender o cetro de ouro, então, viverá. Porém eu não fui chamada para estar com o rei nesses trinta dias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Então, Hatá levou as palavras de Ester para Mardoqueu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Mardoqueu enviou de volta essa mensagem: \"Não penses tu que irás escapar, no palácio do rei, mais do que qualquer outro judeu;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'se te calares agora, socorro e livramento se levantarão de outro lugar, mas tu e a casa de teu pai perecerão. Quem sabe, não foi para esta ocasião que fostes escolhida para ser rainha?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Então, Ester enviou esta mensagem para Mardoqueu:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, '\"Vá, reúne todos os judeus que vivem em Susã, jejueis por mim, não comais, nem bebais por três dias, noite e dia. Eu e minhas criadas jejuaremos também. Então, irei ao rei, ainda que seja contra a lei, e, se eu perecer, perecerei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Mardoqueu foi e fez tudo o que Ester lhe mandara fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Depois de três dias, Ester colocou os trajes reais e foi ao jardim interno do palácio do rei, na frente da casa do rei. O rei estava sentado em seu trono real, na casa real, diante da entrada da casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Quando o rei viu Ester, a rainha, em pé, no pátio, ela alcançou graça aos seus olhos. Ele estendeu para ela o cetro de ouro na sua mão. Então, Ester se aproximou e tocou a ponta do cetro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Então o rei disse a ela: \"O que queres, rainha Ester? Qual é teu pedido? Até a metade do meu reino te será dada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Ester disse: \"Se for do agrado do rei, que o rei e Hamã venham ao banquete que lhes preparei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Então o rei disse: \"Trazei Hamã depressa, para que façamos o que Ester disse\". O rei e Hamã foram ao banquete que Ester havia preparado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Quando o vinho estava sendo servido no banquete, o rei disse a Ester: \"Qual é tua petição? Será garantida a ti. Qual é a tua solicitação? Até metade do reino te será garantida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Ester respondeu: \"Minha petição e minha solicitação são estas:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'se encontrei graça aos olhos do rei e se agrada ao rei garantir minha petição e honrar meu pedido, que o rei e Hamã venham ao banquete que também prepararei para vós amanhã, e eu responderei à pergunta do rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Hamã saiu dali com o coração alegre e satisfeito. Mas, quando Hamã viu Mardoqueu no portão do rei e que Mardoqueu não se levantou ou mostrou algum temor a ele, ficou furioso contra Mardoqueu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Entretanto, Hamã controlou-se e foi para casa. Ele mandou buscar seus amigos e os reuniu, juntamente com sua esposa Zeres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Hamã se vangloriou do esplendor de suas riquezas, de seus muitos filhos, de todas as promoções pelas quais o rei o homenageara, e de como ele se havia elevado acima de todos os oficiais e servos do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Hamã disse: \"Até mesmo a rainha Ester não convidou a ninguém além de mim para ir com o rei ao banquete que ela havia preparado. E amanhã estou novamente convidado por ela para estar junto com o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Mas tudo o que estou falando não me satisfaz, enquanto eu vir Mardoqueu, o judeu, sentado à porta do palácio real\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Então, Zeres, sua mulher, disse para Hamã e todos os seus amigos: \"Mandes fazer uma forca de cinquenta côvados de altura. De manhã, falas com o rei para que Mardoqueu seja enforcado nela. Depois alegra-te com o rei no banquete\". Isso agradou Hamã, e ele mandou construir a forca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Naquela noite o rei não conseguiu dormir. Ele ordenou que seus servos trouxessem os registros do seu reinado, e eles trouxeram e leram em voz alta para o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'E se achou registrado o que Mardoqueu tinha dito sobre Bigtã e Teres, dois oficiais do rei que guardavam a porta de entrada, os quais tinham tentado matar o rei Xerxes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'O rei perguntou: \"O que foi feito para dar honra ou reconhecimento para Mardoqueu por ter feito isso?\". Então, os homens do rei, seus servos, responderam: \"Nada foi feito para ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'O rei disse: \"Quem está no pátio?\" Hamã tinha acabado de entrar no pátio exterior da casa do rei, para falar com o rei sobre o enforcamento de Mardoqueu na forca que havia preparado para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'E os servos do rei lhe responderam: \"Hamã está no pátio\". O rei disse: \"Deixai-o entrar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Quando Hamã entrou, o rei lhe disse: \"O que poderia ser feito ao homem a quem o rei tem o prazer de honrar?\". Então, Hamã disse no seu coração: \"A quem o rei teria o prazer de honrar senão a mim?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Hamã disse para o rei: \"Ao homem a quem o rei tem prazer em honrar');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'sejam trazidos os trajes reais que o rei tenha usado e o cavalo que o rei costuma montar e se coloque uma coroa real sobre a sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Então, que os trajes e o cavalo sejam entregues a alguns dos oficiais mais nobres do rei. Que eles vistam os trajes reais no homem a quem o rei tem prazer de honrar e conduzam tal homem sobre o cavalo, pelas ruas da cidade. Que eles proclamarem diante dele: \'Assim se faz ao homem a quem o rei tem prazer em honrar!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Então, o rei disse a Hamã: \"Depressa, toma os trajes e o cavalo, como disseste, e faz assim para Mardoqueu, o judeu, que está sentado à porta do rei. E não falhes em coisa alguma do que disseste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Então, Hamã pegou os trajes e o cavalo. Ele vestiu Mardoqueu e o conduziu sobre o cavalo, pelas ruas da cidade. Ele proclamou diante dele: \"Assim se faz ao homem a quem o rei tem prazer em honrar!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Mardoqueu voltou para o portão do rei. Mas Hamã apressou-se para sua casa, lamentando, com sua cabeça coberta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Hamã contou para Zeres, sua esposa e todos os seus amigos sobre tudo o que lhe acontecera. Então, seus homens, que eram conhecidos por sua sabedoria, e Zeres sua esposa, disseram-lhe: \"Se este Mardoqueu, diante do qual já começaste a cair, é judeu, tu não prevalecerás contra ele, mas certamente cairás diante dele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Enquando eles estavam falando com ele, os oficiais do rei chegaram. Eles se apressavam para trazer Hamã ao banquete que Ester tinha preparado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Então, o rei e Hamã foram à festa com a rainha Ester.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Neste segundo dia, enquanto estavam servindo o vinho, o rei disse a Ester: \"Qual é tua petição, rainha Ester? Isso te será dado. Qual é o teu pedido? Até metade do reino, te será dado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Então, a rainha Ester respondeu: \"Se achei graça aos teus olhos, ó rei, e se for do teu agrado, que me seja dada minha própria vida — essa é a minha petição — e também peço isso para o meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Pois fomos vendidos, eu e meu povo, para sermos destruídos, mortos e aniquilados. Se nós tivéssemos apenas sido vendidos à escravidão, como escravos e escravas, eu teria permanecido em silêncio, pois nenhum sofrimento como esse justificaria perturbar o rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Então, o rei Xerxes respondeu a Ester: \"Quem é ele? Onde está a pessoa cujo coração o levou a fazer tal coisa?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Ester disse: \"Este perverso Hamã é o adversário e o inimigo!\". Então, Hamã ficou aterrorizado diante do rei e da rainha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'O rei se levantou furioso do banquete do vinho na festa e foi ao jardim do palácio, mas Hamã ficou para implorar pela sua vida à rainha Ester. Ele viu que um desastre estava sendo decidido contra ele pelo rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Então, o rei voltou do jardim do palácio para a sala onde o vinho tinha sido servido. Hamã tinha acabado de se inclinar no leito, onde estava Ester. O rei disse: \"Ele vai atacar a rainha na minha presença e na minha própria casa?\" Assim que essa frase foi pronunciada pelo rei, os servos cobriram o rosto de Hamã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Então, Harbona, um dos oficiais que servia o rei, disse: \"Uma forca de cinquenta côvados de altura foi colocada de frente à casa de Hamã. Ele a preparou para Mardoqueu, aquele que falou para proteger o rei\". O rei disse: \"Enforcai-o nela!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Então, eles enforcaram Hamã na forca que ele preparou para Mardoqueu; assim, a ira do rei se acalmou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Naquele mesmo dia, o rei Xerxes deu à rainha Ester as propriedades de Hamã, o inimigo dos judeus; e Mardoqueu começou a servir diante do rei, pois Ester havia dito ao rei que Mardoqueu era seu parente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'O rei tirou seu anel de selar, que tomou de Hamã, e o deu a Mardoqueu. Ester encarregou Mardoqueu de cuidar dos bens de Hamã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Então, Ester falou novamente ao rei. Ela se prostrou até o chão e chorou implorando a ele que colocasse um fim no plano maligno que Hamã, o agagita, havia tramado contra os judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Então, o rei estendeu a Ester o cetro de ouro, e ela se levantou diante do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Ela disse: \"Se for do agrado do rei, e se achei graça aos teus olhos, se parecer justo diante do rei, e se te agrado, deixa que seja escrito um decreto para revogar as cartas escritas por Hamã, filho de Hamedata, o agagita, as cartas que ele escreveu para destruir os judeus que estão nas províncias do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Pois como poderei suportar ver este desastre cair sobre meu povo? Como poderei assistir à destruição da minha família?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'O rei Xerxes disse à rainha Ester e a Mardoqueu, o judeu: \"Vede, eu dei à Ester a casa de Hamã, e o enforcaram porque ele atacaria os judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Escrevei outro decreto para os judeus em nome do rei e selai com o anel do rei. Pois, um decreto escrito em nome do rei e selado com o anel do rei não pode ser revogado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Então, os escribas do rei foram chamados naquele momento, no terceiro mês, que é o Mês de Sivã, no vigésimo terceiro dia do mês. O decreto foi escrito contendo tudo o que Mardoqueu havia ordenado acerca dos judeus. Foi escrito aos governos provinciais, governadores e oficiais de todas as províncias que estavam localizadas da Índia até a Etiópia, cento e vinte e sete províncias, a cada província na sua própria grafia e em sua própria língua, e aos judeus foi escrito em sua grafia e língua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Mardoqueu escreveu em nome do rei Xerxes e selou com o anel do rei. Ele enviou os documentos por intermédio de mensageiros montados nos cavalos mais velozes que eram usados a serviço do rei, da cavalaria real.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'O rei deu permissão aos judeus que estavam em cada cidade para que se reunissem e se organizassem para proteger suas vidas; para aniquilar, matar e destruir qualquer força armada de qualquer povo ou província que os atacasse, inclusive crianças e mulheres; ou saqueassem suas possessões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'Isso deveria acontecer em todas as províncias do rei Xerxes, no décimo terceiro dia do décimo segundo mês, que é o Mês de Adar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Uma cópia do decreto deveria ser emitida como lei e publicada em todos os povos. Os judeus deveriam estar prontos naquele dia para se vingar de seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Então, os mensageiros montaram em cavalos reais que eram usados a serviço do rei, e partiram apressadamente. O decreto do rei também foi emitido a partir do palácio em Susã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Então, Mardoqueu deixou a presença do rei vestindo roupas reais azuis e brancas, com uma grande coroa de ouro e manto de linho fino e de púrpura. E a cidade de Susã gritou e se alegrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Os judeus ficaram felizes, com júbilo, alegria e honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Em cada província e em cada cidade, em todo lugar onde chegava o decreto do rei, havia alegria e júbilo entre os judeus, banquetes e festas. Muitos dentre os vários povos da terra se tornaram judeus, pois o temor dos judeus havia caído sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'No décimo segundo mês, que é o Mês de Adar, no décimo terceiro dia, quando a ordem do rei e decreto entrariam em vigor, no dia em que os inimigos dos judeus esperavam vencê-los, aconteceu o contrário. Os judeus ganharam força sobre aqueles que lhes odiavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Os judeus se ajuntaram em suas cidades por todas as províncias do rei Xerxes, para erguer as mãos contra aqueles que tentavam trazer-lhes desastre. Ninguém conseguia resistir-lhes, pois o temor deles tinha caído sobre todos os povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Todos os oficiais das províncias, governadores provinciais, os governadores, e os administradores do rei ajudaram os judeus, porque o temor que tinham de Mardoqueu tinha caído sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Pois Mardoqueu tinha grande influência na casa do rei, e sua fama se espalhou em todas as províncias, porque Mardoqueu foi se tornando grande.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Os judeus atacaram seus inimigos com espadas, matando e destruindo eles, e fizeram como eles desejaram para com aqueles que os odiavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Na própria fortaleza de Susã, os judeus mataram e destruíram quinhentos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Eles mataram Parsandata, Dalfom, Aspata,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Porata, Adalia, Aridata,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Farmasta, Arisai, Aridai e Vaisata,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'e os dez filhos de Hamã, filho de Hamedata, o inimigo dos judeus. Mas eles não levaram nenhum bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Naquele dia, o número dos mortos na fortaleza de Susã foi comunicado ao rei. O rei disse para a rainha Ester:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, '\"Os judeus mataram quinhentos homens na fortaleza de Susã, incluindo os dez filhos de Hamã. O que, então, terão feito no resto das províncias do rei? Agora, qual é a tua petição? Ela te será concedida. Qual é o teu pedido? Isso lhe será concedido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Ester disse: \"Se é de agrado do rei, deixa que os judeus de Susã tenham permissão para fazer também amanhã conforme o decreto de hoje, e que os dez filhos de Hamã sejam pendurados na forca\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Então, o rei ordenou que assim se fizesse. Um decreto foi emitido em Susã, e eles enforcaram os dez filhos de Hamã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Os judeus que estavam em Susã ajuntaram-se no décimo quarto dia do Mês de Adar, e mataram trezentos homens a mais em Susã, mas não colocaram as mãos nos bens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Os outros judeus que estavam nas províncias do rei se juntaram para defender suas vidas, e eles receberam alívio de seus inimigos e mataram setenta e cinco mil dos que os odiavam, mas não colocaram as mãos nos bens daqueles que eles mataram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Aconteceu, no décimo terceiro dia do Mês de Adar, no décimo quarto dia, eles descansaram e fizeram dele um dia de banquete e de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Mas os judeus que estavam em Susã se ajuntaram no décimo terceiro dia e no décimo quarto dia. No décimo quinto dia, eles descansaram e fizeram dele um dia de banquete e alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Por isso os judeus das vilas, que construíram suas casas nas cidades rurais, observam o décimo quarto dia do Mês de Adar como um dia de alegria e banquete, e como um dia no qual eles enviam ofertas de comida uns para os outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Mardoqueu registrou estas coisas e enviou cartas para todos os judeus que estavam em todas as províncias do rei Xerxes, ambos de perto e longe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'obrigando-os a guardarem o décimo quarto dia e o décimo quinto dia de Adar todo ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Estes foram os dias em que os judeus se livraram de seus inimigos, e o mês quando sua tristeza tornou-se em alegria, e a lamentação em dia de celebração. Eles deveriam torná-los dias de banquete e alegria, enviando ofertas de comida uns aos outros, e ofertas para os pobres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Assim, os judeus continuaram a celebração que tinham começado, fazendo o que Mardoqueu tinha lhe escrito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Naquele tempo, Hamã, filho de Hamedata, o agagita, o inimigo de todos os judeus, tinha tramado eliminar os judeus e tinha lançado o pur (isto é, a sorte), para aniquilá-los e destruí-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Mas, quando o assunto chegou até o rei, ele deu ordens por cartas, para que o malicioso plano que Hamã tinha planejado contra os judeus recaísse sobre a sua própria cabeça, e que ele e seus filhos fossem pendurados na forca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Por isso, aqueles dias foram chamados Purim, segundo o nome de pur. Por causa de tudo o que estava escrito naquela carta, do que haviam visto e do que lhes havia acontecido,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'os judeus aceitaram um novo costume e encargo. Este costume seria por eles mesmos, sua descendência e por todos os que se juntaram a eles. Seria que eles celebrariam estes dois dias todos os anos. Celebrariam na forma prescrita e na data certa cada ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Esses dias deveriam ser celebrados e observados em toda geração, toda família, toda província, e toda cidade. Esses judeus e seus descedentes jamais cessariam de observar fielmente estes dias de Purim, assim eles jamais esqueceriam deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'A rainha Ester, filha de Abiail, e o judeu Mardoqueu escreveram com toda autoridade e confirmaram esta segunda carta sobre o Purim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Cartas foram enviadas para todos os judeus das cento e vinte e sete províncias do reino de Xerxes, desejando-lhes paz e segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Essas cartas confirmavam os dias de Purim, nas suas datas determinadas, como Mardoqueu, o judeu, e a rainha Ester ordenaram aos judeus. Os judeus aceitaram esta obrigação para eles mesmos e seus descendentes, como também eles aceitaram os tempos de jejum e lamentação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'A ordenança de Ester confirmou estes regulamentos a respeito de Purim, e isso foi escrito no livro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Então, o rei Xerxes impôs um imposto na terra e nas regiões litorâneas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Todos os seus atos de força e poder, junto com o relato da grandeza de Mardoqueu, que lhe foi dada pelo rei, estão escritas no livro das crônicas dos reis da Média e da Pérsia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Mardoqueu, o judeu, foi o segundo na hierarquia do rei Xerxes. Ele era grande entre os judeus e popular com seus muitos irmãos judeus, pois buscava o bem-estar de seu povo e ele falava pela paz de todo o seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Havia um homem na terra de Uz chamado Jó. Homem íntegro e reto que temia a Deus e se afastava do mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Jó teve sete filhos e três filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Tinha sete mil ovelhas, três mil camelos, quinhentas juntas de bois, quinhentas jumentas e uma multidão de empregados. Ele era o maior de todos os homens do oriente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Os filhos, no dia determinado para cada um, ofereciam uma festa em sua casa. Eles convidavam também suas três irmãs para comerem e beberem com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Quando os dias da festa terminavam, Jó os chamava e os consagrava. Levantava-se cedo de manhã e oferecia holocaustos para cada um dos seus filhos, pois ele dizia: \"Talvez os meus filhos tenham pecado e blasfemado contra Deus em seus corações\". Jó sempre fazia isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Então, chegou o dia em que os filhos de Deus apresentaram-se diante de Yahweh, e, com eles, veio também Satanás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Yahweh disse a Satanás: \"De onde vens?\". E Satanás respondeu a Yahweh, dizendo: \"De rodear a Terra e andar por ela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Yahweh disse a Satanás: \"Observaste o meu servo Jó? Porque não existe ninguém como ele na Terra, homem íntegro e reto, que teme a Deus e se afasta do mal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'E Satanás respondeu a Yahweh: \"Por acaso, Jó teme a Deus sem motivo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Não fizeste um muro em volta dele, ao redor da sua casa e em tudo que está a sua volta? Abençoaste as obras das suas mãos e seu rebanho aumentou na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Todavia, estende a Tua mão sobre tudo o que ele possui e vê se ele não blasfema contra Ti na Tua face\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Yahweh disse a Satanás: \"Então, tudo o que ele possui está em teu poder. Só não estendas a tua mão sobre ele\". E Satanás retirou-se da presença de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Em certo dia, os filhos e as filhas de Jó estavam comendo e bebendo vinho na casa do irmão mais velho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Um mensageiro veio a Jó e disse: \"Os bois estavam lavrando e as jumentas pastando ao lado deles;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'de repente, chegaram os sabeus e os atacaram e os levaram embora. Também mataram os servos ao fio de espada e só eu escapei para trazer-te a notícia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Enquanto ele falava, um outro mensageiro veio e disse: \"Fogo de Deus caiu dos céus e queimou todas ovelhas e os servos; e só eu escapei para trazer-te a notícia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Enquanto este ainda falava, um outro mensageiro chegou e disse: \"Os caldeus formaram três grupos, atacaram os camelos e os levaram. Quanto aos servos, mataram ao fio espada e só eu escapei para trazer-te a notícia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Enquanto este ainda falava, outro também chegou, dizendo: \"Os teus filhos e as tuas filhas estavam comendo e bebendo vinho na casa do irmão mais velho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'veio um vento forte do deserto, atingiu os quatro cantos da casa, que caiu sobre eles e eles morreram; só eu escapei para trazer-te a notícia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Então, Jó levantou-se, rasgou sua túnica, rapou a sua cabeça, prostrou-se em terra e adorou a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'E disse: \"Nu, eu vim do ventre da minha mãe e, nu, eu voltarei para lá. Yahweh deu e Yahweh tirou. Bendito seja o nome de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Em tudo isso, Jó não pecou e nem acusou a Deus por qualquer maldade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Chegou o dia em que os filhos de Deus se apresentaram diante de Yahweh e, com eles, veio também Satanás se apresentar diante de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Yahweh disse a Satanás: \"De onde vens?\". E Satanás respondeu a Yahweh: \"De rodear a Terra e andar por ela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Yahweh disse a Satanás: \"Observaste o meu servo Jó? Porque não existe ninguém como ele na Terra, homem íntegro e reto, que teme a Deus e se afasta do mal. Ele continua firme em sua integridade, embora tu Me persuadiste contra ele, para destruí-lo sem causa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Satanás respondeu a Yahweh: \"De fato, pele por pele, um homem dará tudo o que tem pela sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Mas estende Tua mão agora e toca seus ossos e sua carne e vê se ele não Te amaldiçoa na Tua face\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Yahweh disse a Satanás: \"Vê, ele está em tuas mãos, somente poupe-lhe a vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Então, Satanás saiu da presença de Yahweh e feriu Jó com terríveis feridas, da sola dos pés até o alto da sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Jó pegou um pedaço de telha para se coçar e sentou-se no meio das cinzas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Então, sua esposa disse-lhe: \"Tu continuas com tua integridade? Amaldiçoa Deus e morre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Mas ele lhe disse: \"Tu falas com uma mulher louca. Receberíamos as coisas boas de Deus e não as más?\". Em tudo isto, Jó não pecou com seus lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Quando os três amigos de Jó ouviram sobre todo o mal que lhe sobreviera, cada um veio de seu próprio lugar: Elifaz, o temanita; Bildade, o suita; Zofar, o naamatita. Eles determinaram um certo tempo para vir chorar com ele e o confortar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Quando, de longe, eles ergueram seus olhos, não o reconheceram. Então, levantaram a voz e choraram, rasgaram os seus mantos e lançaram pó para o ar e sobre suas próprias cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'E sentaram com ele no chão, por sete dias e sete noites e não lhe disseram palavra alguma; pois viram que o seu sofrimento era muito grande.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Depois disso, Jó abriu sua boca e amaldiçoou o dia do seu nascimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, '\"Que pereça o dia em que eu nasci e a noite que disse: \'Um menino foi concebido!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Que aquele dia seja escuro; e que Deus, lá do alto, não o considere, nem deixe a luz do sol brilhar sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Que as trevas e a sombra da morte reivindiquem-no para eles mesmos; que a nuvem viva sobre ele; que todas as coisas que fazem o dia negro possam verdadeiramente aterrorizá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Que densas trevas se apoderem daquela noite; que não se regozije ela entre os dias do ano; nem seja contada entre os dias dos meses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Seja aquela noite estéril; e, nela, não se ouça som de júbilo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Que eles amaldiçoem aquele dia, aqueles que sabem como acordar o Leviatã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Que as estrelas do amanhecer se tornem escuras. Que aquele dia olhe em direção à luz, mas não o encontre; nem o deixe ver as pálpebras dos olhos do amanhecer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'porque não fechou as portas do ventre da minha mãe, nem escondeu o sofrimento diante dos meus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Por que eu não morri quando eu sai do ventre da minha mãe? Por que não rendi o espírito quando minha mãe me deu à luz?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Por que seus joelhos me receberam? Por que me amamentariam os seios da minha mãe?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Agora eu estaria repousando tranquilamente. Eu dormiria e descansaria');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'com reis e conselheiros da terra, que construíram tumbas para si que agora estão em ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Ou eu estaria deitado com príncipes que uma vez tiveram ouro, que encheram suas casas com prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Ou, talvez, eu seria como aborto que nunca teria nascido, como uma criança que nunca viu a luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Ali, o perverso cessa de perturbar; e, ali, repousam os cansados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Ali, os prisioneiros ficam à vontade juntos; eles não houvem a voz do feitor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Pequenos e grandes estão lá; o servo está livre de seu senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Por que se dá luz aquele que está em miséria? Por que se concede vida àquele que está com a alma amargurada;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'para aquele que anseia pela morte, mas ela não vem; para aqueles que procuram pela morte mais que os que procuram por tesouro escondido?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Por que a luz é concedida à aquele que se alegra muito e fica feliz quando encontra a sepultura?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Por que a luz é concedida ao homem cujo caminho está escondido, um homem a quem Deus o encobriu?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'O meu suspiro vem antes da minha comida; o meu gemido é derramado como água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Aquilo que eu temia veio sobre mim; o que eu receava me aconteceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Eu não estou tranquilo, eu não estou calmo; eu não tenho descanso; pelo contrário, tenho problemas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Então, Elifaz, o temanita respondeu, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, '\"Se alguém tentar falar contigo, serás impaciente? Mas quem pode conter sua própria fala?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Eis que tens ensinado a muitos; tens fortalecido mãos fracas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Tuas palavras têm sustentado os que estavam caindo, tens feito fortes os joelhos vacilantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Mas agora os problemas chegaram a ti e sofres; e, ao ser atingido, te aflinges.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Não poderia o teu temor a Deus te dar confiança? Não poderia a integridade dos teus caminhos te dar esperança?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Pensa sobre isto: quem alguma vez pereceu sendo inocente? Ou qual dos íntegros foi destruído?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Baseado no que tenho observado, aquele que pratica iniquidade e que planta o mal também o colherá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Pelo sopro de Deus, eles perecem; pelo vento da Sua ira, são consumidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Cessa o rugido do leão e a voz do leão feroz; os dentes dos leões novos se quebram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'O leão perece por falta de presas; os filhotes da leoa são espalhados por todos os lados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Então, ouvi uma questão que alguém me trouxe secretamente, os meus ouvidos ouviram o segredo disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Ele me falou em visões durante a noite, quando as pessoas caem em sono profundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Temor e tremor vieram a mim e fizeram todos os meus ossos estremecerem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Então, um espírito passou diante da minha face; os pêlos do meu corpo levantaram-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'O espírito permaneceu em pé, mas eu não pude discernir a sua aparência. Um vulto estava diante dos meus olhos; houve silêncio e eu ouvi uma voz que dizia:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Pode um homem mortal ser mais justo que Deus? Pode um homem ser mais puro que seu Criador?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Eis que Deus não confia nos Seus servos; se até a Seus anjos atribui loucura,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'quanto mais aos que habitam em casas de barro, cuja fundação é o pó, que irão se desfazer mais rapidamente que a ferrugem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Entre a manhã e a noite, eles são destruídos; eles perecem para sempre sem que ninguém se lembre deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'As tendas deles não estão montadas entre eles? Eles morrem; eles morrem sem sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Chama agora, será que há alguém que te responderá? A qual dos santos tu te dirigirás?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Porque a raiva mata o homem imprudente. A inveja mata o tolo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Eu já vi uma pessoa tola lançar raízes, mas subitamente amaldiçoei o seu lar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Os seus filhos estão longe da segurança, eles são esmagados no portão da cidade. Não há quem lhes resgatem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Os famintos devoraram a sua colheita; eles a tiram até dos espinhos. Os sedentos anseiam pela sua riqueza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Porque os problemas não vêm do solo; nem as tribulações vêm do chão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Ao invés disso, a humanidade faz a sua própria tribulação, como as faíscas voam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Quanto a mim, voltaria para Deus; para Ele, entregaria a minha causa —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Ele, que faz coisas grandes e insondáveis, maravilhas inumeráveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Ele dá chuva à terra e envia água aos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Ele faz isto para elevar às alturas aqueles que estão abatidos; para levantar à segurança aqueles que estão de luto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Ele frustra os planos dos astutos, de modo que as suas mãos não possam obter êxito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Ele apanha os sábios na sua própria astúcia; os planos dos perversos logo se findam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Eles encontram trevas durante o dia, e, ao meio dia, tateam como cegos como se fosse à noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Mas Ele salva os pobres da espada que está na boca deles e as pessoas necessitadas das mãos dos fortes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Assim, o pobre tem esperança e a injustiça tapa a sua própria boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Abençoado é o homem que Deus corrige, portanto, não desprezes a disciplina do Todo Poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Porque Ele fere e ata o ferimento; Ele fere e depois as Suas mãos curam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Ele irá te salvar de seis problemas; e, em sete dificuldades, nenhum mal te tocará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'Na fome, Ele te resgatará da morte; na guerra, do poder da espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Tu estarás escondido do perigo da língua; e tu não temerás a destruição quando vier.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Tu rirás da destruição e da fome; tu não temerás os animais devoradores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Porque terás uma aliança com as pedras do teu campo; e os animais selvagens estarão em paz contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Tu saberás que a tua tenda está protegida, visitarás o seu aprisco e, nele, nada faltará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Tu saberás também que a tua posteridade será grande e os teus descendentes serão como o capim no solo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Tu morrerás com uma idade avançada como uma semente que é colhida no tempo certo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Vê, nós já examinamos este caso e assim é, ouve e sabe disso por ti mesmo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Então, Jó respondeu, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, '\"Ó! Se apenas a minha angústia fosse pesada, se toda a minha calamidade fosse colocada na balança!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Por agora, seriam mais pesadas que a areia dos mares. Por isso, minhas palavras foram precipitadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Já que as flechas do Todo Poderoso estão em mim, meu espírito bebe o veneno delas; o terror de Deus está posto contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'O jumento selvagem vai ficar desesperado quando tem grama? Ou vai ficar o boi com fome quando ele tem pasto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Pode aquilo que não tem sabor ser comido sem sal? Ou tem qualquer sabor a clara de um ovo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Eu me recuso tocá-los pois são como comida desagradáveis para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Ó, quem dera que se cumprisse o meu pedido; ó, como desejaria que Deus respondesse a pergunta que eu lhe fiz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Eu desejaria que Deus me esmagasse de uma vez, que me soltasse de Suas mãos e me tirasse desta vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Que ainda seja este o meu consolo — mesmo que eu exulte numa dor implacável: que eu não tenha negado as palavras do Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Que força eu tenho para tentar esperar? Qual é o meu fim, para que eu possa prolongar a minha vida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'É minha força a força das pedras? Ou é minha carne feita de bronze?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Não é verdade que eu não tenho ajuda em mim mesmo e que a sabedoria tenha sido tirada de mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Para a pessoa que está a desfalecer, compaixão deveria ser mostrada pelo seu amigo; mesmo que ele tenha abandonado o temor do Todo Poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Mas meus irmãos me traíram como um ribeiro de água no deserto,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'como canais de água que transbordam para nada, os quais ficam turvos por causa do gelo sobre eles, como a neve que nela se esconde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Quando ela descongela, desaparece; quando está quente, ela se derrete para fora do seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'As caravanas que viajam pelos seus caminhos, elas desviam seu caminho da água, caminham para terra seca e perecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Caravanas de Temá olharam para lá, enquanto os viajantes de Sabá esperaram por eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Eles ficaram desapontados porque estavam certos de que encontrariam água; eles foram lá, mas foram enganados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Pois agora vós, amigos, não são nada para mim; vós vedes a minha terrível situação e estais com medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Por acaso, eu disse: \'dai-me alguma coisa?\'. Ou: \'oferecei-me um presente da vossa riqueza?\';');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'ou: \'salvai-me das mãos dos meus adversários?\'; ou, \'resgatai-me das mãos dos meus opressores?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Ensinai-me e manter-me-ei em paz; fazei-me entender onde eu tenho errado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Como são dolorosas as palavras verdadeiras! Mas os vossos argumentos, como eles realmente me corrigem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Vós planejais ignorar minhas palavras, tratando as palavras de um homem desesperado como o vento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'De fato, lançastes sorte sobre o órfão e negociastes vosso amigo como mercadoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Agora, portanto, por favor, olhai para mim, certamente eu não mentiria na vossa face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Mudai de parecer, eu vos peço; que não deixeis alguma injustiça convosco, pois, de fato a minha causa é justa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Está o mal em minha língua? Não pode minha boca discernir coisas maliciosas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Não é penoso o trabalho para os homens da terra? Não são seus dias como de um assalariado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Como o servo que anseia pelas sombras da noite e, como o assalariado que olha o seu pagamento,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'assim me deram como herança, meses de miséria e noites de aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Quando me deito, digo a mim mesmo: quando me levantarei? e quando a noite se vai? Estou cansado de me revirar na cama até o amanhecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Minha carne está coberta de vermes e crostas de sujeira; as feridas da minha pele se ressecam e voltam a se abrir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Meus dias são mais velozes que a lançadeira do tecelão, passam sem esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Deus, lembra-Te que minha vida é somente um sopro e meus olhos não mais verão o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Os olhos de Deus, que me veem, não mais me verão; Seus olhos estarão sobre mim, mas eu não mais existirei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Assim como a nuvem é consumida e desaparece, quem vai para o Sheol nunca mais voltará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Não retornará mais para sua casa, nem seu lugar o conhecerá novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Portanto, não conterei minha boca; falarei da angústia do meu espírito; queixarei no mais amargo da minha alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Porventura sou eu o mar ou um monstro marinho, para colocares um guarda sobre mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Quando digo: \'Minha cama me confortará e meu leito facilitará a minha queixa\';');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'então, Tu me assustas com sonhos e me aterrorizas com visões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Prefiro ser estrangulado e morrer que preservar os meus ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'A minha vida é odiosa; eu não desejaria estar sempre vivo. Deixa-me sozinho porque meus dias são inúteis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Que é o homem para que atentes para ele e ponhas sobre ele Teus pensamentos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'para que o observes toda manhã e o testes a cada momento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Quanto tempo vai demorar antes que olhes para mim, antes que me deixes sozinho o suficiente para que eu possa respirar um pouco?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Mesmo que eu peque contra Ti, o que isto Te seria, Tu, que guardas os homens? Por que fizeste de mim um alvo para que eu seja uma carga para Ti?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Por que não perdoas minhas transgressões e levas embora minhas iniquidades? Por isso, eu me deitarei no pó; Tu me buscarás, porém não mais existirei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Então, respondeu Bildade, o suíta, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, '\"Até quando falarás tais coisas? Até quando serão as palavras da tua boca como vento impetuoso?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Pode Deus perverter o direito e o Todo Poderoso corromper a justiça?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Teus filhos pecaram contra Ele; nós sabemos disso, pois Ele os entregou às suas transgressões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Mas, se buscares diligentemente a Deus e apresentares ao Todo Poderoso a tua petição;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'se o teu coração e tuas ações forem retas, Ele certamente te faria o bem, te recompensaria dando novamente tua família e te fazendo próspero.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Embora os teus planos iniciais fossem humildes, ainda tua condição final seria grandiosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Por favor, pergunta às gerações passadas e considera o que os antepassados aprenderam!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Nós sabemos que nascemos ontem e que não sabemos nada pois nossos dias na terra são apenas sombra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Eles não te ensinarão, nem te contarão? Eles não dirão palavras vindas dos seus corações?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Pode o papiro crescer sem lodo ou o junco crescer sem água?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Estando ainda eles verdes, sem ter sido cortados, secam-se antes de qualquer outra planta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'São assim também os passos de todo que se esquece de Deus, a esperança do corrupto perecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Sua confiança se desfará e sua segurança será frágil como uma teia de arranha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Ele se apoia em sua casa, mas ela não permanecerá em pé; segura-se nela, mas ela não se sustentará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Sob o sol, eles são verdes e seus ramos passam para além de todo o jardim;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'suas raízes envolvem os montes de pedras e procuram bons lugares nas rochas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Mas, se esta pessoa é destruida fora de seu lugar, então, aquele lugar irá negá-lo e dirá: \'nunca te vi\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Eis a \"alegria\" das pessoas com esses comportamentos; outras plantas brotarão em seu lugar no mesmo solo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Deus nunca castigará um homem inocente, nem segurará pela mão o malfeitor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Ele irá encher sua boca de risos e seus lábios de gritos de júbilo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Aqueles que te odeiam se vestirão de vergonha e a tenda dos corrupto não mais existirá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Então, Jó respondeu, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '\"Verdadeiramente, eu sei que é assim. Mas como é que a pessoa pode estar correta diante de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Se ela quer discutir com Deus, Ele não lhe responde uma vez em mil vezes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Deus é prudente no coração, forte e poderoso, quem já se endureceu contra Ele e foi bem sucedido?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Ele é quem tira as montanhas sem avisar a ninguém quando as move na Sua ira,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Ele é quem move a Terra para fora do seu lugar faz suas colunas estremecerem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'É o mesmo Deus que diz ao sol para não nascer e não nasce e quem cobre as estrelas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Quem, por si mesmo, estende os céus, pisoteia e subjuga as ondas do mar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Quem faz a Ursa, Orion, Plêiades e as constelações do sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'É o mesmo Deus que faz grandes coisas, coisas incompreensíveis — coisas maravilhosas incontáveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Vê, Ele passa por mim e eu nem O vejo; Ele segue adiante também, mas eu não O percebo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Se Ele remove alguma coisa, quem pode O impedir? Quem pode Lhe dizer: \'o que Tu fazes?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Deus não irá retirar a Sua ira; os ajudadores de Raabe se curvam diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Quanto menos eu poderia Lhe responder, poderia escolher palavras para discutir com Ele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Mesmo que eu fosse justo, eu não Lhe responderia; eu pediria somente misericórdia ao meu Juiz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Mesmo que eu clamasse e Ele me respondesse, não acredito que Ele estaria ouvindo a minha voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Porque Ele me quebra com tempestade e multiplica-me as feridas sem causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Ele nem me permite retomar o fôlego e me enche de amargura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Se é uma questão de força, saiba! Ele é poderoso! Se for uma questão de justiça, quem pode intimá-Lo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Mesmo estando com a razão, minha própria boca me condenaria; mesmo que eu não tenha culpa, minhas palavras me provariam culpado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Estou sem culpa, mas já não me interesso mais por mim mesmo; eu desprezo a minha própria vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Não faz diferença nenhuma, é por isso que eu disse que Ele destrói ambos, os justos e os maus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Se qualquer flagelo mata subitamente, Ele rirá da aflição dos inocentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'A Terra está entregue nas mãos dos perversos; Deus cobre os rostos dos Seus juízes. Se não for Ele que faz isso, então, quem é?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Meus dias são mais velozes que um mensageiro corredor; os meus dias desaparecem, eles não veem nenhum bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Eles são tão rápidos quanto barcos de juncos e tão rápidos quanto a águia que se lança em sua vítima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Se eu dissese que vou esquecer minhas queixas, que vou tirar a minha face triste e estar feliz,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'estaria com medo de todas minhas tristezas porque eu sei que Tu não irás me considerar inocente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Eu serei condenado; por que, então, tentaria em vão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Se me lavasse com água de neve e tornasse as minhas mãos limpas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Deus me mergulharia numa vala e a minha própria roupa ficaria com nojo de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Porque Deus não é homem, como eu sou; eu poderia respondê-L; não poderíamos nos apresentar juntos ao tribunal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Não há juiz entre nós que possa por as mãos sobre ambos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Não há um outro juiz que tire a vara de Deus de cima de mim, que possa evitar o Seu terror de me assustar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Então, eu poderia falar alto e não O temer. Mas, com as coisas desse jeito, eu não posso fazer isto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Estou cansado da minha vida; darei renda solta à minha reclamação; falarei na amargura da minha alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Direi a Deus: \'Não me condene apenas; mostra-me a razão porque me acusas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Será que é bom que me oprimas; desprezar a obra de Tuas mãos enquanto Tu sorris nos planos dos corruptos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Tens Tu olhos de carne? Vês Tu como o homem vê?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Os Teus dias são como os dias da humanidade ou os Teus anos, como os anos de homens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'para inquerir a minha iniquidade e averiguar o meu pecado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'mesmo sabendo que não sou culpado e não há ninguém que pode me resgatar de Tuas mãos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Tuas mãos me formaram e me moldaram por completo, mas Tu estás me destruindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Lembra-Te, eu Te imploro, que Tu me modelaste como barro; Tu irás me trazer ao pó novamente?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Não me derramaste como leite e me coalhaste como queijo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Tu me vestiste com pele e carne, de ossos e tendões, teceste a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Tu tens me concedido vida e aliança de fidelidade; Tua ajuda tem guardado o meu espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Mas ainda estas coisas escondeste no Teu coração — Eu sei que isto é o que pensavas:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'que, se eu pecasse, Tu notarias; Tu não me perdoarias das minhas iniquidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Ai de mim, se sou corrupto; mesmo se eu fosse íntegro, não poderia levantar minha cabeça, uma vez que estou cheio de desgraça e olhando meu próprio sofrimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Se a minha cabeça se levantar, Tu me caçarás como um leão; outra vez, Tu Te mostras poderoso a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Tu trazes novas testemunhas contra mim e aumentas Tua ira contra mim; Tu me atacas com novos exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Então, porque me tirastes do ventre? Quem me dera eu tivesse entregue meu espírito e que nenhum olho nunca tivesse me visto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Eu seria como quem nunca existiu, teria sido levado do ventre para a sepultura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Não são poucos os meu dias? Para, deixa-me, sozinho, para que eu descanse um pouco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Antes que eu vá para o lugar de onde nunca voltarei, para a terra das trevas e da sombra da morte;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'para a terra escura como a meia noite, a terra da sombra da morte, desordenada, onde a luz parece com a meia noite\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Então, Zofar, o naamatita, respondeu, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, '\"Não deveria tal multidão de palavras serem respondidas? Deveria acreditar neste homem, cheio de palavras?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Deveria tua vanglória fazer outros permanecerem em silêncio? Quando tu zombas de nossos ensinamentos, ninguém fará com que te sintas envergonhado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Pois dizes a Deus: \'Minhas doutrinas são puras, estou eu sem culpa diante dos Teus olhos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Mas, ah, se Deus falasse Deus e abrisse Seus lábios contra ti;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Ele te mostraria os segredos da sabedoria! Pois Ele é grande em entendimento. Sabe que Deus exige menos de ti que a tua iniquidade merece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Podes tu entender a Deus por procurar por Ele? Podes tu compreender perfeitamente o Todo Poderoso?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Este assunto é tão alto quanto o céu; que poderás fazer? Isso é mais profundo que o Sheol; o que podes tu saber?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Isso mede mais que a Terra e é mais amplo que o mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Se Ele passar por alguém e calá-lo, se Ele chamar alguém para o julgamento, então, quem poderá impedi-lo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Pois Ele conhece pessoas falsas; quando Ele vê a iniquidade, Ele não a percebe?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Mas o povo tolo não tem entendimento; eles vão obtê-lo quando um jumento selvagem der cria a um homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Mas, imagina que tu tenhas posto certo o teu coração e tenhas alcançado com as tuas mãos em direção a Deus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'imagina que a iniquidade estivesse em tuas mãos, mas que, depois, tu a tenhas posto longe de ti e não tenhas deixado que a injustiça habite em tuas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Então, certamente, tu levantarias teu rosto sem sinal de vergonha; de fato, tu estarias firme e sem medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Tu esquecerias o teu sofrimento; tu te lembrarias disto apenas como águas que passaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Tua vida seria mais brilhante que o meio dia; embora houvesse trevas, tornariam-se como a manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Tu estarias seguro porque há esperança; de fato, tu terias encontrado segurança sobre ti e descansarias seguro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Também tu te deitarias em descanso e ninguém te faria medo, certamente, muitos buscariam o teu favor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Mas os olhos dos perversos vão fracassar, eles não terão como fugir; a sua única esperança será o último suspiro de vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Então, Jó respondeu, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, '\"Sem dúvida, vós sois o povo; a sabedoria morrerá convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Mas eu tenho entendimento tanto quanto vós; eu não sou inferior a vós. Na verdade, quem não sabe coisas como estas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Eu sou motivo de riso para o meu próximo. Eu, aquele que chamou Deus e foi respondido por Ele! Eu, um justo e inocente; sou agora motivo de riso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'No pensamento de quem está tranquilo, há desprezo pela calamidade; um empurrão para aqueles cujos os pés estão escorregando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'As tendas dos bandidos prosperam e aqueles que provocam a Deus sentem-se seguros; as suas próprias mãos são os seus deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Mas agora pergunta aos animais e eles te ensinarão; pergunta às aves dos céus e elas te contarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Ou fale para a Terra e ela te ensinará; os peixes do mar irão declarar-te isto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Qual animal entre todos estes não sabe que a mão de Yahweh fez isto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Em Sua mão, está a vida de todo ser vivo e o fôlego de toda humanidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'O ouvido não examina as palavras como o paladar prova a comida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Com os homens velhos, há sabedoria; com o passar dos dias, há entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Com Deus, estão a sabedoria e o poder; Ele tem conselho e entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Vê, Ele destrói algo e aquilo não pode ser construído novamente; se Ele aprisiona alguém, não pode ser liberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Vê, se Ele retém as águas, elas se secam; e, se Ele as solta, elas inundam a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Com Ele, estão a força e a sabedoria; as pessoas que são enganadas e o enganador, ambas pertencem a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Ele conduz os conselheiros para longe, entristecidos, com os pés descalços; Ele torna juízes em tolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Ele toma a autoridade dos reis; Ele enrola um pano nas cinturas deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Ele conduz os sacerdotes para longe, entristecidos, com os pés descalços e derruba pessoas poderosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Ele remove o discurso daqueles que são confiados a falar e tira o entendimento dos anciãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Ele derrama desprezo sobre os príncipes e afrouxa o cinto dos poderosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Ele revela coisas profundas da escuridão e traz à luz as sombras de onde as pessoas estão mortas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Ele faz nações fortes e Ele também as destrói; Ele faz crescer nações e Ele também as faz prisioneiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Ele tira o entendimento dos líderes do povo da Terra; e os faz vaguear por um deserto, onde não existe caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Eles apalpam no escuro, sem luz, e Ele os faz cambalear como um bêbado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Vê, meu olho tem visto tudo isso; meu ouvido tem ouvido e entendido isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'O que vós sabeis, também sei; não sou inferior a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'No entanto, eu preferiria falar com o Todo Poderoso; desejo a razão diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Mas vós mascarais a verdade com mentiras; vós sois médicos sem valor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Ó, que vós pudésseis permanecer em silêncio! Assim, passaríeis por sábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Ouvi agora a minha defesa; escutai os argumentos dos meus próprios lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Vós falareis injustamente para Deus e direis mentiras a Ele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Vós poderíeis mostrar bondade a Ele? Poderíeis realmente argumentar no tribunal como advogados de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Seria realmente bom para vós se Ele vos examinasse? Poderíeis enganar Deus como se enganam homens?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Ele certamente vos reprovaria se secretamente vós mostrásseis parcialidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Não poderia Sua majestade vos amedrontar? Não poderia Seu pavor cair em vós?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Vossas memoráveis palavras são provérbios feitos de cinzas; vossas defesas são torres feitas de barro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Calai-vos, deixai-me sozinho, assim, posso falar, deixai vir sobre mim o que vier.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Tomarei minha própria carne nos meus dentes; tomarei minha vida nas minhas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Vê, se Ele me mata, não terei mais esperança, no entanto, eu defenderei meus caminhos diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Esta será a razão da minha absolvição: eu não virei diante Dele como homem sem Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Deus, ouve cuidadosamente meu discurso; permite que minhas declarações cheguem aos Teus ouvidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Vê, agora, tenho colocado minha defesa em ordem; eu sei que sou inocente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Quem é a pessoa que poderia levantar-se contra mim no tribunal? Se Tu vens para fazer isso e, se fosse provado que estou errado, então, eu me silenciaria e desistiria da vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Deus, faz apenas duas coisas por mim e, então, não me esconderei da Tua face:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'retira Tua mão opressiva de mim e não deixes os Teus terrores me amedrontarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Então, chama-me e responderei; ou deixa-me falar-Te e Tu me respondes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Quantas são as minhas iniquidades e meus pecados? Deixa-me saber minhas transgressões e meus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Por que escondes Tua face de mim e me tratas como Teu inimigo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Poderás perseguir uma folha voando? Irás Tu perseguires uma palha seca?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Pois escreves coisas amargas contra mim; tens me feito herdar as iniquidades da minha juventude.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Também pões os meus pés no tronco; Tu, que observas todos os meus passos, examinas o chão onde as solas dos meus pés têm andado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'embora eu seja como uma coisa apodrecida, como uma vestimenta que as traças tenham comido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'O homem, que é nascido de mulher, vive apenas alguns dias e está cheio de problemas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Ele brota do chão como uma flor e é cortado, foge como uma sombra e não dura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Tu olhas para alguém assim? E me levas a julgamento contigo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Quem pode tirar coisa limpa a partir de uma coisa suja? Ninguém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Os dias do homem são determinados. O número dos seus meses estão Contigo. Tu apontaste os limites dos quais ele não pode passar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Desvia-te dele para que possa descansar, para que possa aproveitar seu dia como um diarista, se puder fazê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Pode haver esperança para uma árvore; se for cortada, poderá brotar de novo, para que seu caule tenro não desapareça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Embora sua raiz envelheça na terra e seu toco morra no chão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'apenas com o cheiro das águas, brotará e dará ramos como uma planta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Mas o homem morre. Ele se torna fraco. De fato, o homem para de respirar e onde está?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Como a água desaparece de um lago e como o rio perde água e seca,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'assim as pessoas se deitam e não se levantam novamente. Até que os céus não existam mais, eles não acordarão nem se despertarão do seu sono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Ah! Se Tu me escondesses no Sheol longe dos problemas, se me escondesses até que a Tua ira passasse, fixasses o tempo da minha permanência lá e Te lembrasses de mim!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Se um homem morre, ele viverá novamente? Se assim for, desejaria esperar todo o meu tempo penoso até que minha libertação chegasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Tu chamarias e eu responderia. Desejarias ver a obra de Tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Tu contarias e cuidaria dos meus passos; não vigiarias meu pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Minha transgressão seria selada em uma bolsa. Tu cobririas a minha iniquidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Mas até montanhas caem e não dão em nada; até as rochas são removidas do seu lugar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'as águas desgastam as pedras e suas enchentes lavam o pó da terra e Tu destróis a esperança do homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Tu sempre o derrotas e ele passa. Tu mudas o rosto dele e o mandas para morrer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Se seus filhos são honrados, ele não sabe disso. E, se são humilhados, ele não os vê.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Ele sente apenas a dor do próprio corpo e lamenta por si mesmo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Então, Elifaz, o temanita, respondeu e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, '\"Deveria um homem sábio responder com conhecimento inútil e se saciar com o vento do leste?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Deveria argumentar com conversa inútil ou com discursos com os quais ele não faça o bem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Na verdade, tu diminuis o respeito por Deus; tu obstruis a devoção a Ele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'a tua iniquidade ensina à tua boca; tu escolhes ter a língua de um homem astuto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Tua própria boca te condena, não a minha; de fato, teus próprios lábios testificam contra ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'És tu o primeiro homem que nasceu? Vieste tu à existência antes das montanhas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Tens ouvido o conhecimento secreto de Deus? Tu limitas a sabedoria a ti mesmo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'O que sabes que nós não sabemos? O que compreendes o que nós já não compreendemos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Conosco estão ambos: os grisalhos e os homens idosos, os quais são bem mais velhos que teu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'As consolações de Deus são pequenas demais para ti; palavras muito brandas para ti?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Por que teu coração te leva para longe? Por que teus olhos brilham');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'e voltas teu espírito contra Deus e deixas sair tais palavras de tua boca?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'O que é o homem para estar limpo? Como o nascido de mulher pode ser justo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Vê, Deus não confia nem mesmo em Seus santos; de fato, os céus não são puros à Sua vista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Quanto menos limpo é aquele que é abominável e corrupto, que bebe a iniquidade como a água!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Escuta-me e eu te mostrarei; eu te anunciarei o que tenho visto,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'coisas que os sábios ensinaram, as quais vieram de seus pais, coisas que seus ancestrais não ocultaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'Estes eram seus antepassados, aos quais tão somente, a terra foi dada; entre eles, nenhum estranho jamais passou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'O homem perverso torce de dor todos os dias, o número de anos que estão reservados para o opressor sofrer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Um som de terrores está em seus ouvidos; enquanto ele está na prosperidade, o destruidor vem sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Ele não acha que retornará das trevas; a espada espera por ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Ele vai a vários lugares à procura de pão, dizendo: \'Onde está?\'. Ele sabe que o dia da escuridão está perto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Desespero e angústia o deixam com medo; prevalecem contra ele, como um rei pronto para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Porque ele estendeu a mão contra Deus e se comportou orgulhosamente contra o Todo Poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Esse homem perverso corre até Deus com teimosia, com um escudo espesso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Isto é verdade, mesmo que ele tenha coberto o rosto com sua gordura, acumule-a em sua cintura');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'e tenha vivido em cidades desoladas; em casas nas quais ninguém mais habita e que estavam prontas para se tornarem montes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Ele não será rico; sua riqueza não durará; nem mesmo sua sombra durará na Terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Ele não se afastará das trevas;; uma chama incendiará seus ramos; irá embora pelo sopro da boca de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Que ele não confie em coisas inúteis, enganando a si mesmo; porque a inutilidade será sua recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Isso acontecerá antes do tempo de sua morte; seu ramo não se tornará verde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Suas uvas verdes serão derrubadas como as da videira; ele deixará cair as suas flores como as da oliveira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'A companhia de pessoas sem Deus será estéril; o fogo consumirá suas tendas de propina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Elas concebem o mal e dão luz à iniquidade; seus ventres concebem engano\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Então, Jó respondeu:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, '\"Eu tenho ouvido muitas coisas como essas; sois todos consoladores miseráveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Não terão fim essas palavras inúteis? O que está errado convosco para responderdes assim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Eu também poderia falar como vós, se estivésseis em meu lugar; eu poderia amontoar palavras contra vós e menear minha cabeça zombando de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Ah, como eu poderia encorajar-vos com a minha boca! Como a consolação de meus lábios poderia aliviar a vossa dor!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Se falo, a minha dor não é aliviada; se não falo, como posso ter auxílio?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Mas agora, Deus, Tu me tornaste alguém sem nenhum vigor; Tu fizeste a minha família desolada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Fizeste-me secar, isso constitui uma testemunha contra mim, o emagrecimento do meu corpo depõe contra mim e testifica contra meu rosto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Deus, em Sua ira, me deixou em pedaços e me perseguiu; Ele tem rangido Seus dentes contra mim; e meu inimigo fixa seus olhos em mim enquanto Ele me deixa em pedaços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Pessoas estão de boca aberta para mim, elas me esmurram no queixo; elas se reuniram contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Deus me entregou nas mãos dos perversos e me faz cair nas mãos dos corruptos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Eu estava tranquilo, mas Ele me despedaçou. Então, Ele me agarrou pelo pescoço, deixou-me em pedaços e também fez de mim o Seu alvo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Seus flecheiros me rodeiam; Deus penetra os meus rins, não me poupa; derrama no chão a minha bilis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Ele me esmaga contra o muro uma vez e de novo. Ele corre contra mim como um guerreiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Costurei vestes de luto sobre minha pele; enterrei minha testa na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'O meu rosto está vermelho de tanto choro. A sombra da morte circunda os meus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Mesmo que não haja violência nas minhas mãos e seja pura a minha oração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Terra, não cubras o meu sangue! Que meu choro não tenha lugar de descanso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Eis que agora, minha testemunha está nos céus; alguém, que me defende, está nas alturas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Meus amigos zombam de mim, mas os meus olhos derramam lágrimas diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Eu peço para que uma testemunha no céu defenda a causa deste homem diante de Deus, como um homem faz com seu próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Pois, em alguns poucos anos, irei a um lugar de onde não mais voltarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Meu espírito está desfalecido e meus dias estão se acabando; meu túmulo está pronto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Certamente, os zombadores estão comigo; e tenho que ficar vendo suas provocações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Dá-me um defensor que seja para mim uma garantia diante de Ti. Quem mais poderá me ajudar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Pois Tu, Deus, mantiveste os seus corações sem entendimento; por isso, Tu não os exaltarás acima de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Aquele que denuncia seus amigos por uma recompensa, os olhos dos seus filhos falharão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Mas Ele fez de mim um escárnio para as pessoas; elas cospem no meu rosto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Minha visão também está turva de tanta tristeza; todas as partes do meu corpo estão tão finas como sombras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Os justos ficarão pasmos com isso; e o inocente se levantará contra esses homens sem Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'O justo seguirá o seu caminho; o que tem mãos limpas crescerá, ficando cada vez mais forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Mas, quanto a todos vós, vinde agora! Eu não encontrarei nenhum homem sábio entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Foram-se os meus dias; meus planos fracassaram, assim como os desejos do meu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Essas pessoas, esses zombadores, trocam a noite pelo dia; a luz ficou próxima da escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Vejo o Sheol como minha casa; tenho estendido minha cama na escuridão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'tenho dito à cova: \'Tu és meu pai\'; aos vermes: \'Vós sois minha mãe ou minha irmã\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'onde está, então, a minha esperança? A minha esperança: quem poderá ver?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Descerá a esperança comigo aos portões do Sheol quando descermos ao pó?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Então, Bildade, o suíta, respondeu:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, '\"Quando irás parar de falar? Considera, depois falaremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Por que nós somos tratados como animais; por que nos tornamos ignorantes na tua presença?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Tu, que te despedaças na tua ira, poderia a Terra ser abandonada por tua causa ou poderiam as pedras serem removidas de seus lugares?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Realmente, a luz de uma pessoa corrupta será apagada; a faísca do seu fogo não brilhará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'A luz se escurecerá na sua tenda e a lâmpada sobre ela será tirada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Os seus passos firmes ficarão curtos; os seus próprios planos o lançarão para baixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Porque, por seus próprios pés, será lançado na rede e andará nos fios enredados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'A armadilha o pega pelo calcanhar; o laço o prende firme.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Uma corda está escondida para ele no chão; e uma armadilha no caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Terrores o farão sentir medo por todos os lados; eles o perseguirão pelo calcanhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Suas riquezas se tornarão em fome e a calamidade estará pronta ao seu lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'As partes do seu corpo serão devoradas; realmente, o primogênito da morte o devorará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Ele é arrancado da segurança da sua tenda, levado para o rei dos terrores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Um povo que não é seu habitará na sua tenda depois que eles virem o enxofre espalhado dentro de sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Suas raízes secarão por baixo; por cima, serão cortados os seus ramos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Sua memória perecerá na Terra; e, pelas ruas, não terá nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Ele será tirado da luz para as trevas e será expulso deste mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Ele não terá filhos ou netos em sua geração e também nenhuma lembrança dos parentes de onde morava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Aqueles que vivem no ocidente serão amedrontados pelo que lhe acontece em um dia; aqueles que vivem no oriente ficarão amedrontados por isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Certamente, tais são as casas dos corruptos, lugares daqueles que não conhecem a Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Então, Jó respondeu:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, '\"Até quando me fareis sofrer e me atormentareis com palavras?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Por dez vezes, repreendestes a mim e não estais envergonhados de tratar-me duramente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Se, de fato, eu errei, meu erro permanece comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Se, na verdade, quereis exaltar-vos sobre mim e usar a minha humilhação contra mim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'então, deveríeis saber que Deus fez algo errado comigo e me pegou em Sua rede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Vede, clamo: \'Violência!\', mas não obtenho resposta; clamo por socorro, mas não há justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Ele fez um muro no meu caminho, para que eu não passe e colocou trevas em minhas veredas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Despojou-me da minha glória e tirou-me a coroa da cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Quebrou-me por todos lados e fui destruído; arrancou-me as esperanças como a uma árvore.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Também acendeu a Sua ira contra mim e me considera um dos Seus adversários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Suas tropas se reúnem, levantam um cerco contra mim e acampam ao redor da minha tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Ele pôs meus irmãos longe de mim; e meus conhecidos estão completamente afastados de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Meus parentes falharam comigo; e meus amigos mais próximos se esqueceram de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Aqueles que se hospedaram em minha casa e também minhas servas me consideram como um estrangeiro; sou um estranho aos seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Chamo meu servo, mas ele não me responde, ainda que eu o suplique com minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'O meu hálito é desagradável à minha mulher; sou repugnante para os que nasceram da minha mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Até as crianças me desprezam; se me levanto para falar, elas falam contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Todos meus amigos íntimos me odeiam; os que amo se viraram contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Os meus ossos se apegaram à minha pele e à minha carne; escapei só com a pele dos meus dentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Tende compaixão de mim! Tende compaixão de mim, meus amigos! Pois a mão de Deus me tocou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Por que me perseguis como se fossem Deus? Por que não estais satisfeitos com a ruína da minha carne?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Ó, se as minhas palavras fossem escritas! Ó, se fossem registradas num livro!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Ó, se, com pena de ferro e com chumbo, fossem gravadas numa rocha para sempre!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Quanto a mim, sei que o meu Redentor vive e que, por fim, Ele se levantará sobre a Terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Depois que a minha pele, ou seja, este corpo, for destruído, então, na minha carne, verei a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Eu, O verei com meus próprios olhos; eu e não outra pessoa. Meu coração se enfraquece dentro de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Se dizeis: \'Como o perseguiremos! A origem da sua aflição está nele\';');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'então, tende medo da espada, porque a ira traz a punição da espada, para saberdes que existe um julgamento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Então, Zofar, o naamatita, respondeu:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, '\"Os meus pensamentos me fazem responder rapidamente, por causa da minha preocupação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Ouço uma repreensão que me ofende, mas um espírito que procede do meu entendimento me responde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Tu não sabes que, desde tempos antigos, quando Deus colocou o homem na Terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'o triunfo do corrupto é curto e a alegria do homem sem Deus permanence apenas por um instante?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Mesmo que a sua altura alcance os céus e a sua cabeça toque as nuvens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'tal pessoa perecerá permanentemente como suas próprias fezes; todos aqueles que o viram, dirão: \'Onde ele está?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Ele voará como um sonho e não será encontrado; na verdade, será dissipado como a visão da noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Os olhos que o viram não o verão mais; mesmo o seu lugar não o verá mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Seus filhos procurarão o favor dos pobres; e suas mãos terão que devolver sua riqueza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Os seus ossos estão cheios do vigor da mocidade, mas esse vigor se deitará com ele no pó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Mesmo que a maldade seja doce na boca dele; mesmo que ele a esconda debaixo da língua,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'segurando-a, sem deixá-la sair, mantendo-a em sua boca —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'a comida se torna amarga em seu intestino; torna-se veneno de cobra dentro dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Ele engole riquezas, mas irá vomitá-las; Deus as expulsará de seu ventre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Ele sugará o veneno das cobras e a língua da víbora o matará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Ele não viverá para desfrutar das correntes e dos rios de mel e manteiga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Restituirá o fruto do seu trabalho e não poderá comê-lo; não desfrutará da riqueza que adquiriu com seu comércio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Pois ele oprimiu e rejeitou os pobres; tomou violentamente casas que não construiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Porque ele não experimentou nenhuma satisfação, ele não será capaz de guardar qualquer coisa que lhe proporcione prazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Nada sobrou que ele não tenha consumido. E, assim, sua prosperidade não permanecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Na abundância de sua riqueza, cairá em dificuldade; a mão de cada um que está em pobreza virá sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Quando ele estiver enchendo seu estômago, Deus derramará a fúria da Sua ira sobre ele; como chuva, cairá sobre ele enquanto come.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Ainda que esse homem fuja da arma de ferro, um arco de bronze o atingirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'A flecha penetrará as suas costas e emergirá; de fato, a ponta resplandecente sairá através do seu fígado. Terrores virão sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Escuridão total está reservada para os seus tesouros; um fogo não abanado o consumirá e acabará com o que restou na sua tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Os céus revelarão sua iniquidade e a Terra se levantará contra ele como testemunha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'A riqueza da sua casa desaparecerá; os seus bens se derramarão no dia da ira do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Esta é a recompensa de Deus para o homem corrupto, a herança que lhe foi reservada por Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Então, Jó, respondeu e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, '\"Ouvi cuidadosamente meu discurso e que ele seja o conforto que vós oferecereis a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Tolerai-me e eu também falarei; depois que eu falar, podeis zombar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Quanto a mim, é a minha reclamação para uma pessoa? Por que eu não estaria impaciente?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Olhai para mim, ficai espantado e colocai vossa mão à boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Quando penso em meus sofrimentos, fico aterrorizado e tremedeiras tomam conta do meu corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Por que as pessoas malvadas continuam a viver, tornam-se velhas e crescem em poder?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Seus descendentes são estabelecidos com eles às suas vistas e sua posteridade é estabelecida ante seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Suas casas estão salvas do medo; e a vara de Deus não está sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Seus bois se reproduzem e isso não falha; suas vacas dão à luz e não perdem seus bezerros prematuramente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Eles enviam seus pequenos como rebanhos e suas crianças dançam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Eles cantam ao som do tamborim, da harpa e se regozijam com a música da flauta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Eles gastam seus dias em prosperidade e vão, calmamente, ao Sheol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Dizem a Deus: \'Aparta-Te de nós, pois não desejamos nenhum conhecimento dos Teus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Quem é o Altíssimo para que O adoremos? Que vantagem teríamos se tivéssemos orado a Ele?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Vede, não está a prosperidade deles em suas próprias mãos? Eu não tenho o que fazer com o conselho dos maus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Quantas vezes a lâmpada dos maus se apaga ou a calamidade vem sobre eles? Quantas vezes Deus lhes dá dar tristeza na Sua ira?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Quantas vezes eles se tornam como palha ante o vento ou como os ciscos que a tempestade leva para longe?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Vós dizeis: \'Deus coloca a culpa de outro para Seus filhos pagarem\'. Deixai-o pagar por si mesmo, para que ele saiba que é culpado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Deixai que seus próprios olhos vejam sua destruição e deixai-o beber da ira do Altíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Por que ele se preocuparia com sua família quando o número de seus meses for cortado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Poderá alguém ensinar conhecimento a Deus, já que Ele julga até mesmo aqueles que estão em posição elevada?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Um homem morre com toda a sua energia, ficando completamente quieto e à vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Seu corpo está cheio de leite e a medula de seus ossos está umedecida e saudável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Outro homem morre em amargura de alma, alguém que nunca experimentou algo de bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Eles, da mesma maneira, descansam na poeira; os vermes vêm sobre ambos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Vede, eu conheço os vossos pensamentos e os caminhos nos quais desejais enganar-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Pois vós dizeis: \'Onde está a casa do príncipe agora? Onde está a tenda em que o homem mau uma vez habitou?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Vós nunca perguntastes aos viajantes? Vós não sabeis as evidências que eles falam,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'que o homem mau está guardado do dia da calamidade e que ele é guiado para longe do dia da ira?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Quem condenará os caminhos do homem mau perante a sua face? Quem o recompensará pelo que ele tem feito?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Ele será carregado à sepultura; homens guardarão seu túmulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'O solo do vale será doce para ele; todas as pessoas virão depois dele, assim como há inúmeras pessoas que foram antes dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Como, então, vós podeis consolar-me com estes absurdos, já que, em vossas repostas, não há nada além de falsidade?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Então, Elifaz, o temanita, respondeu:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, '\"Pode o homem ser útil a Deus? Pode o sábio ser útil a Ele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Há algum prazer para o Todo Poderoso se fores justo? Há algum proveito para Ele se tornares teus caminhos irrepreensíveis?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'É por causa da tua reverência por Ele, que Ele te repreende e te leva a juízo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Não é grande a tua malícia? E sem fim as tuas iniquidades?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Pois tu tens exigido segurança de teus irmãos sem razão; tu tens retirado as roupas daquele que estava nú.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Tu não destes água ao sedento e negastes pão ao faminto,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'mesmo sendo tu um homem poderoso, possuindo a terra; mesmo sendo tu um homem honrado, viveu nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Tu despediste as viúvas de mãos vazias; o braço dos orfãos foi quebrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Portanto, as armadilhas estão à tua volta e medo repentino te aflinge.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Há trevas, para que tu não vejas; uma abundância de águas te cobrem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Não está Deus nas alturas do céu? Olha para a altura das estrelas, quão altas estão!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Tu dizes: \'O que Deus sabe? Pode Ele julgar por meio de densa escuridão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Nuvens carregadas O cobrem para que Ele não nos veja; Ele anda nos altos céus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Guardarás os antigos caminhos, nos quais andaram os homens corruptos —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'os quais foram arrebatados antes do seu tempo, cuja fundação tem sido arrastada como um rio,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'aqueles que disseram a Deus: \'Aparta-Te de nós\'; aqueles que disseram: \'O que pode nos fazer o Todo Poderoso?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Mesmo assim, Ele encheu suas casas com bens, os planos dos corruptos estão longe de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Os justos veem a sua destruição e se alegram; pessoas inocentes riem deles até o escárneo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Eles dizem: \'Na verdade, aqueles que se levantam contra nós são exterminados; o fogo tem consumido suas posses\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Agora, concorda com Deus e fica em paz com Ele; assim, o bem virá para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Rogo-te: recebe instruções da Sua boca; guarda a Sua palavra no teu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Se retornares ao Todo Poderoso e, se puseres a iniquidades longe das tuas tendas, tu serás edificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Lança fora o teu tesouro no pó, o ouro de Ofir entre as pedras dos ribeiros,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'e o Todo Poderoso será o teu tesouro e a tua prata preciosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Então, terás prazer no Todo Poderoso; tu levantarás o teu rosto a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Tu farás a tua oração a Ele e Ele te ouvirá; Tu cumprirás os teus votos diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Tu também ordenarás qualquer coisa e esta será confirmada a ti; a luz brilhará em teus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Deus humilha o homem orgulhoso e salva aqueles com olhos baixos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Ele resgatará o homem inocente; tu serás resgatado através da pureza das tuas mãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Depois, Jó respondeu e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, '\"Ainda hoje, a minha queixa é amarga; minha mão é pesada por causa do meu sofrimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Ah, se eu soubesse onde encontrá-Lo! Ah, se eu pudesse ir ao Seu lugar!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Eu apresentaria o meu caso diante Dele e encheria a minha boca com argumentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Eu aprenderia as palavras com as quais Ele me responderia e entenderia o que Ele me diria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Ele iria argumentar contra mim segundo a grandeza do Seu poder? Não, Ele prestaria atenção em mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Então, um homem reto poderia argumentar com Ele. Assim, eu seria liberto para sempre pelo meu juiz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Vê, eu vou para o oriente, mas Ele não está lá; vou para o ocidente, mas não consigo achá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Mesmo para o norte, onde Ele está a trabalhar, não posso vê-Lo; e, para o sul, onde Ele se esconde, eu não posso vê-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Mas Ele conhece o caminho em que ando; quando Ele me prova, eu saio como o ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Os meus pés seguiram apressadamente as Suas pisadas; eu guardei o Seu caminho e não me desviei dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Não abadonei o mandamento dos Seus lábios; Eu guardei como um tesouro as palavras da Sua boca mais que minha porção de comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Mas Ele é único, quem pode Lhe virar as costas? Aquilo que Ele deseja, faz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Ele carrega Seu decreto contra mim; e há muitas outras coisas como essas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Por isso, estou aterrorizado em Sua presença; quando eu penso Nele, fico com medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Pois Deus fez enfraquecer o meu coração; oTodo Poderoso aterrorizou-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Porém, eu não fui destruído pelas trevas, as densas trevas que encobrem o meu rosto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Por que os tempos para o julgamento dos corruptos não são marcados pelo Todo Poderoso? Por que os fiéis não veem seus dias de julgamento chegar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Há corruptos que removem os marcos de fronteira; há corruptos que roubam à força os rebanhos e colocam nos seus próprios pastos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Eles roubam o jumento dos órfãos; eles levam o boi da viúva como penhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Eles forçam os necessitados para fora do caminho; os pobres da Terra se escondem deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Vê, como jumentos selvagens no deserto, esse pobre povo sai para o seu trabalho, procurando, atentamente, por comida; talvez, o deserto proverá comida para seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Povo pobre que colhe durante a noite nos campos dos outros; eles recolhem restos de uvas da colheita dos corruptos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Eles se deitam nus toda noite; eles não têm cobertor no frio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Eles são molhados pela chuva das montanhas; eles se deitam perto das grandes rochas porque não têm habitação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Há corruptos que arrancam os órfãos do peito das suas mães e também corruptos que levam as crianças dos pobres como penhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Mas os pobres andam quase nus sem vestimenta; embora com fome, eles carregam os feixes de cereais de outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Os pobres fazem óleo dentro dos muros daqueles corruptos; eles pisam os lagares dos corruptos, mas eles mesmos sofrem com a sede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Na cidade, as pessoas gemem; os feridos clamam, mas Deus não Se atenta para as suas orações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Alguns desses corruptos rebelam-se contra a luz; eles não sabem seus caminhos e nem permanecem nos mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Antes de amanhecer, o homicida se levanta e mata pessoas pobres e necessitadas; de noite, ele é como um ladrão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Também, o olho do adúltero espera pelo crepúsculo; ele diz: \'Nenhum olho me verá\'. Ele disfarça sua face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Na escuridão, os corruptos invadem casas; eles se escondem durante o dia; eles não se importam com a luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Pois, para todos eles, a manhã é como densas trevas; eles são amigos dos terrores das densas trevas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Rapidamente, eles morrem como espuma na superfície das águas; sua porção da terra está amaldiçoada; ninguém vai trabalhar nas suas vinhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Como a seca e o calor derretem a neve em água; também o Sheol consome aqueles que pecaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'O ventre que o gerou o esquecerá; o verme se deliciará dele; ele nunca mais será lembrado. Dessa forma, o corrupto será quebrado como a árvore.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'O corrupto devora a mulher estéril que nunca teve filhos; ele não faz o bem para a viúva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Ainda assim, Deus arrasta as pessoas poderosas com o Seu poder; Ele Se levanta e não fortalece suas vidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Deus lhes permite achar que estão seguras; e elas são felizes por isso, mas os Seus olhos estão em seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Essas pessoas são exaltadas; mas, em pouco tempo, e elas se vão; certamente, elas serão rebaixadas; serão reunidas como todas as outras; serão cortadas como as pontas das espigas dos cereais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Se assim não for, quem pode provar-me que sou mentiroso; quem pode fazer o meu discurso inválido?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Então, Bildade, o suíta respondeu e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, '\"Domínio e temor estão com Ele; Ele coloca ordem nos Seus altos lugares do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Há fim ao número dos Seus exércitos? Sobre quem a Sua luz não resplandece?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Então, como o homem pode ser justo perante Deus? Como pode ele, que é nascido de mulher ser limpo, aceitável a Ele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Vê, mesmo a lua não tem brilho para Ele; as estrelas não são puras aos Seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Quanto menos o homem que é um verme --- um filho de homem, que é uma minhoca!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Então, Jó respondeu e disse,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, '\"Como tu tens ajudado ao que não tem força! Como tens salvado o braço que não tem força!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Como tens aconselhado ao que não tem sabedoria e revelado a ele melhor conhecimento!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Com ajuda de quem proferiste estas palavras? E de quem era o espírito que saiu de ti?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Os mortos tremem, aqueles que estão debaixo das águas e todos que habitam nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'O Sheol está nu perante Deus; a própria destruição não tem cobertura contra Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Ele estende os céus do norte sobre espaço vazio e suspende a Terra acima do nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Ele prende as águas nas Suas densas nuvens, mas as nuvens não se rasgam debaixo delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Ele encobre a face da lua e espalha as suas nuvens sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Ele marcou um limite circular por cima das águas como a linha entre a luz e as trevas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Os pilares do céu estremecem e são surpreendidos pela Sua repreensão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Ele acalmou o mar pela Sua força; pelo Seu conhecimento, despedaça a Raabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Pelo Seu sopro, limpou os céus; a Sua mão feriu a serpente fugitiva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Vê, esses são apenas a beirada dos Seus caminhos. Quão pequeno é um sussurro que podemos ouvir Dele! Quem pode compreender o trovão do Seu poder?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Jó, retmou sua fala e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, '\"Tão certo como Deus vive, Quem arrancou a minha justiça, o Todo Poderoso, que tornou minha vida amarga,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'pois, enquanto a minha vida ainda estiver em mim e o fôlego de Deus em minhas narinas, é isto que farei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Meus lábios não falarão iniquidade, nem a minha língua falará engano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Nunca vou admitir que vós três estáveis certos; até que eu morra, eu nunca negarei minha integridade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Eu me apego à minha justiça e não a deixarei ir; meus pensamentos não me repreenderão enquanto eu viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Que o meu inimigo seja como o homem corrupto; e aquele que se levanta contra mim seja como o homem injusto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Pois qual é a esperança de um homem corrupto quando Deus o destrói, quando Deus tira-lhe a vida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Poderá Deus ouvir seu choro quando a aflição vier sobre ele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Alegrar-se-á ele no Todo Poderoso e clamará a Deus em todos os tempos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Eu vos ensinarei a respeito da mão de Deus; não ocultarei os pensamentos do Todo Poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Vede, todos vós tendes visto isto pessoalmente; por que, então, tendes falado tudo isso sem nenhum sentido?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Este é o destino do homem corrupto com Deus, a herança do opressor que ele recebe do Todo Poderoso:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'se seus filhos se multipicarem, será para a espada; sua prole nunca terá comida suficiente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Todos os que sobreviverem serão sepultados pela praga e suas viúvas não farão lamentação alguma por eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Ainda que o homem corrupto acumule prata como o pó e acumule roupas como barro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'ele poderá acumular roupas, mas pessoas justas as vestirão e as pessoas inocentes dividirão a prata entre elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Ele constrói sua casa como a da aranha, como a cabana que um guarda faz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Ele se deita em riquezas, mas não fará isto para sempre; ele abre seus olhos e tudo se foi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Terrores o inundam como águas; uma tempestade o arrasta pela noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'O vento do leste o leva para longe e ele sai; e o varre do seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'O vento do leste se joga sobre ele e não pára; ele tenta escapar das suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'O vento bate palmas a ele em gozação; seus assobios o tiram do seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Certamente, existe uma mina para a prata e um lugar onde se refina o ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'O ferro é tirado da terra; e o cobre é fundido da pedra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Um homem põe fim às trevas e procura, no limite mais distante, as pedras na escuridão e nas densas trevas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Ele abre um túnel afastado de onde as pessoas vivem, lugares esquecidos, nos quais as pessoas não colocam seus pés. Ele se dependura longe dos homens, ele balança para lá e para cá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'A terra, de onde procede o pão, é revolvida em baixo como por fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'As suas pedras são lugares onde se encontra a safira e sua poeira contém ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Nenhuma ave da rapina conhece este caminho, nem o olho do falcão pode vê-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'O animal orgulhoso não andou por tais caminhos, nem o leão feroz passou por lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'O homem estende a mão sobre as pedras duras; ele revolve as montanhas pelas suas raízes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Ele corta canais no meio das pedras; os seus olhos veem todas as coisas valiosas lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Ele fecha os rios para que não corram. O que está escondido lá ele traz para a luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Onde se achará a sabedoria? Onde está o lugar do entendimento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'O homem não conhece o seu preço; e nem é este encontrado na terra dos viventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'As águas profundas embaixo da terra dizem: \'Não está em mim\'; o mar diz: \'Também não está em mim\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Não pode ser conseguida com ouro; e nem pode a prata ser pesada como seu preço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Também não pode ser comprada com o ouro de Ofir, nem com o precioso ônix, ou com a safira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'O ouro e o cristal não podem ser igualados em valor à sabedoria; nem se pode trocar por joias de ouro fino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Não vale a pena fazer menção ao coral ou jaspe; certamente, o preço da sabedoria é mais que rubis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'O topázio da Etiópia não se compara com ela; nem pode ser valorizada em termos de ouro puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'De onde, pois, vem a sabedoria? Onde está o lugar do entendimento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'A sabedoria está escondida dos olhos de todos os seres viventes e está guardada em oculto das aves dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'A destruição e a morte dizem: \'Temos escutado somente um rumor acerca disto com os nossos ouvidos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Deus entende o caminho para ela; Ele conhece o seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Pois Ele vê os limites da Terra e vê abaixo de todos os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'No passado, Ele fez a força do vento e dividiu as águas por medidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Ele colocou um limite para a chuva e um caminho para o relâmpago dos trovões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Então, Ele viu a sabedoria e a anunciou; Ele a estabeleceu e a examinou de fato.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Para as pessoas, Ele disse: \'Vê, o temor do Senhor é sabedoria; e apartar-se do mal é entendimento\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Jó continuou o discurso e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, '\"Ó, quem me dera eu fosse o que era nos meses passados quando Deus cuidava de mim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'quando a Sua luz brilhava sobre a minha cabeça, e quando eu andava pelas trevas guiado pela Sua luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Ó, quem me dera fosse como era nos dias da minha colheita, quando a amizade de Deus estava sobre a minha tenda,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'quando o Todo Poderoso ainda estava comigo e meus filhos estavam à minha volta,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'quando meus caminhos eram cobertos de nata e a rocha derramava sobre mim rios de azeite!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Quando eu ia ao portal da cidade, quando me sentava na praça da cidade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'os jovens me viam e mantinham distância de mim por respeito e os idosos se levantavam e ficavam de pé diante de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Os príncipes paravam suas falas quando eu chegava; eles colocavam as mãos sobre suas bocas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'As vozes dos nobres eram silenciadas e as suas línguas grudavam no céu da boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Porque, depois que os seus ouvidos me ouviam, eles me abençoavam; depois que os seus olhos me viam, eles testemunhavam a meu respeito e me aprovavam;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'pois eu resgatava o pobre quando ele clamava e também os órfão que não tinham ninguém para o ajudar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'A bênção daquele que estava prestes a morrer vinha sobre mim e eu fazia com que o coração da viúva cantasse de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Eu vestia a justiça e ela me cobria; a minha justiça era como um manto e um turbante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Eu era olhos dos cegos; pés para os coxos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'e pai dos necessitados. Eu examinava a causa até mesmo dos que eu não conhecia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Eu quebrava as mandíbulas do corrupto; arrancava a vítima dentre os seus dentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'E eu falava: \'morrerei no meu ninho; multiplicarei os meus dias como os grãos de areia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'As minhas raízes se espalharam pelas águas, o orvalho ficava sobre os meus ramos a noite inteira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'A honra em mim era sempre nova e o arco da minha força estava sempre novo em minha mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Os homens me escutavam; eles esperavam por mim; ficavam em silêncio para ouvir o meu conselho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Depois que eu acabava de falar, eles não falavam mais; o meu discurso caía como água sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Eles sempre esperavam por mim como esperavam pela chuva; eles abriam largamente as suas bocas para beberem as minhas palavras, como fariam para a chuva tardia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Eu lhes sorria quando menos esperavam; eles não rejeitavam a luz do meu rosto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Eu selecionava os caminhos para eles e me sentava como o chefe deles; eu vivia como rei no seu exército, como alguém que consola os enlutados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Agora, os que são mais novos que eu não possuem nada, mas zombam de mim — esses jovens, cujos pais que trabalhassem ao lado dos cães de guarda do meu rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Pois de que me serveria a força das mãos dos seus pais, homens cuja força da sua idade madura já pereceu?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Eles eram magros por causa da pobreza e fome, andavam roendo em lugares secos na escuridão do deserto e na desolação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Apanhavam malvas e folhas de arbustos; e o seu alimento eram as raízes dos arbustos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Eles eram expulsos do meio dos homens, que gritavam para eles, como se grita para ladrões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Por isso, eles tinham que viver nos vales dos rios, em buracos da terra e das rochas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Entre os arbustos, urravam como jumentos e, debaixo dos arbustos, se ajuntavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Eles eram filhos de tolos, verdadeiramente eram filhos de homens sem nome. Eles eram expulsos da terra com chicotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Mas, agora, para os seus filhos, tornei-me canção de zombaria; na verdade, eu agora sou piada para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Eles me abominam, ficam distantes de mim e não se privam de cuspir no meu rosto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Portanto, Deus afroxou a corda do meu arco e me afligiu, por isso, aqueles que zombam de mim não se detêm diante de minha face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'À minha direita, levanta-se gente vil; eles levantam contra mim o seu cerco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Eles destroem meu caminho, promovem desastres para mim, homens que ninguém pode deter.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Eles vêm contra mim como um exército por meio de grande buraco na muralha da cidade; no meio das ruínas, se lançam contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Terrores vieram sobre mim; a minha honra foi retirada como se pelo vento; a minha prosperidade se foi como as nuvens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Agora, a minha vida se derrama dentro de mim; muitos dias de sofrimento se prederam a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'De noite, os meus ossos são perfurados, as dores que me corroem não descansam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'A poderosa força de Deus desfigurou as minhas vestes; esta me envolve como a gola da minha túnica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Ele me lançou na lama; tornei-me como pó e cinza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Clamo a Ti, Deus, mas Tu não me respondes; Eu me levanto e Tu não olhas para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Tu mudaste e Te tornaste cruel a mim; com a força da Tua mão, Tu me persegues.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Tu me levantas no vento e fazes com que ele me leve para longe; lanças a mim para um lado e outro na tempestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Pois eu sei que me trarás à morte, para casa destinada a todos seres viventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Porventura, não estende alguém sua mão para implorar por ajuda quando cai? Não clama por socorro aquele que está atribulado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Não chorei por aquele que se encontrava em tribulação? Não lamentei pelo homen necessitado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Quando procurei pelo bem, o mal me sobreveio, quando eu esperei pela luz, sobreveio a mim a escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'O meu coração está atribulado e não descansa; dias de aflição vieram sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Tenho passado como alguém que vive nas trevas, mas não por causa do sol; levanto-me na assembleia e clamo por socorro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Tornei-me irmão de chacais e companheiro de avestruzes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'A minha pele é escura e se desfaz; os meus ossos estão queimados pelo calor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Por isso, a minha harpa foi afinada para hinos de lamento e a minha flauta para tocar aos que se queixam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Eu fiz uma aliança com os meus olhos; como, então, olharia a virgem com desejo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Qual é a porção que tenho do Deus lá de cima, a herança do Todo Poderoso das alturas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Eu pensava que a calamidade fosse para os injustos e os desastres para os corruptos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Será que Deus não vê os meus caminhos e conta todos os meus passos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Se eu andei em falsidade, se o meu pé se apressou para o engano,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'que Deus me pese numa balança para que saiba da minha integridade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Se o meu passo se desviou do caminho certo, se o meu coração seguiu as atrações dos meus olhos, se alguma mancha de impureza se apegou às minhas mãos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'de fato, que outros comam o que plantei, inclusive, que a colheita seja arrancada das minhas plantações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Se o meu coração se atraiu por outra mulher, se espreitei à porta do próximo para tomar a sua esposa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'então, que a minha esposa moa o grão de cereais de outro homem e que outros se deitem com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Certamente, isso seria um crime terrível; portanto, digno de castigo pelos juízes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Porque isso é fogo que consome tudo para o Sheol e que queimaria toda a minha colheita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Se ignorei o direito de justiça do meu servo ou da minha serva, quando reclamaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'O que farei quando Deus Se levantar para me julgar? Quando Ele vier me julgar, como Lhe responderia?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Aquele que me formou no ventre não lhes formou também? Não é O mesmo que nos moldou no ventre?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Se eu neguei o desejo dos pobres, ou, se causei lágrimas nos olhos da viúva,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'ou, se eu comi sozinho e não permiti que os órfãos comessem também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'No entanto, os órfãos cresceram comigo na minha juventude como se fosse com um pai e cuidei da mãe deles, uma viúva, do ventre da minha própria mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Se vi alguém perecendo por falta de cobertor, ou um homem necessitado de roupa;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'e, se seu coração não me abençou porque não se aqueceu com a lã do meu rebanho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'se levantei a minha mão contra os órfãos, porque vi o meu sustento no portão da cidade, então, trazei as acusações contra mim!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Que meu ombro caia das minhas costas e que o meu braço aparte-se das juntas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Porque a calamidade de Deus seria um terror para mim; por causa da Sua majestade, eu não faria nenhuma destas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Se fiz do ouro a minha confiança, e, se disse ao ouro puro: \'Tu és a minha segurança\';');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'se me alegrei por causa da minha grande riqueza, pelas muitas posses que as minhas mãos obtiveram, então, trazei as acusações contra mim!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Se vi o sol quando brilhou, ou a lua caminhando em seu fulgor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'e, se o meu coração foi atraído secretamente, para que a minha boca beijasse a minha mão em adoração a eles —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'isso também seria um crime a ser punido pelos juízes, pois teria negado ao Deus que está no alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Se me alegrei com a ruína do inimigo ou celebrei o desastre que lhe tomou,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'certamente, não permiti que a minha boca pecasse por desejar maldição sobre a vida dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Se o homem da minha tenda nunca tivesse dito: \'Quem encontrará alguém que não foi saciado com os alimentos de Jó?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, '(Até os estrangeiros nunca tiveram que ficar ao relento, pois sempre abri minha porta aos viajantes), se não fui assim, então, trazei as acusações contra mim!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Se como ser humano, ocultei os meus pecados, escondendo a minha culpa nas minhas túnicas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, '(porque temi a grande multidão e porque o desprezo das famílias me aterrorizou, para que me mantivesse calado e não mais saísse), então, trazei as acusações contra mim!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Ó, quem me dera se tivesse alguém para me ouvir, esta é a minha declaração da verdade; que o Altíssimo me responda! Se eu tivesse apenas a nota escrita pelos meus inimigos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Certamente, a exibiria abertamente nos meus ombros. A usaria como uma coroa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Eu Lhe declararia os meus passos, como um príncipe seguro, iria até Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Se a minha terra clamar contra mim e os seus canais chorarem juntos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'se consumi os seus frutos sem pagar ou causei a perda da vida dos donos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'que cresçam espinhos ao invés do trigo e a erva ao invés da cevada\". Acabaram-se as palavras de Jó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Então, estes três homens deixaram de responder a Jó porque ele se considerava justo aos seus próprios olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Então, inflamou-se a ira de Eliú, filho de Baraquel de Buz, o buzita, da família de Rão; ele se irou contra Jó, porque este se justificava a si mesmo em vez de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'A ira de Eliú se inflamou também contra os seus três amigos porque não haviam achado a resposta para Jó e, ainda assim, o condenaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Eliú esperou para falar com Jó porque os outros homens eram mais velhos que ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Contudo, quando Eliú viu que não havia resposta na boca destes três homens, inflamou-se sua ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Então, Eliú filho de Baraquel de Buz falou: \"Eu sou jovem e vós sois velhos. Por isso, ponderei e não ousei dar a minha opinião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Eu disse: \'que a longevidade dos dias fale, a multidão dos anos ensine sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Mas é o espírito dentro do homem que lhe dá entendimento, o sopro do Todo Poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Não são só os mais velhos que são os sábios, não são só os de idade que entendem o que é justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Por isso, eu vos digo: \'Escutai-me; também vos direi o meu conhecimento\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Eis que esperei por vossas palavras, escutei vossos argumentos enquanto estáveis pensando acerca do que dizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'De fato, eu prestei atenção em vós; eis que não havia dentre vós quem pudesse convencer Jó ou quem pudesse responder às suas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Cuidado para não dizer: \'Nós achamos a sabedoria!\'. Deus irá derrotar a Jó; homem comum não pode fazer isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Porque Jó não direcionou suas palavras contra mim, por isso, não irei responder a ele com vossas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Estes três homens estão sem palavras, não conseguem mais responder a Jó, não têm mais palavra para dizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Poderia eu esperá-los porque eles não estão falando, porque estão ali em silêncio e não conseguem mais responder?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Não, eu também responderei minha parte, expressarei meu conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Pois estou cheio de palavras, o espírito em mim me impulsiona.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Eis que meu peito está como o vinho fermentando e sem brechas, como novos odres prestes a explodir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Falarei, para que ache alívio; abrirei meus lábios e responderei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Que não faça eu acepção de pessoas, nem adularei homem algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Porque não sei como adular, se eu o fizesse, meu Criador em breve me levaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Mas agora, Jó, suplico-te, escuta meu discurso; ouve todas as minhas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Eu abri minha boca; minha língua falou na minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Minhas palavras declaram a justiça do meu coração; os meus lábios falam puro conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'O Espírito de Deus me fez; o sopro do Todo Poderoso me deu vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Se tu podes, responde-me; define tuas palavras diante de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Vê, eu estou apenas como tu estás sob a vista de Deus; eu também fui formado do barro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Eis que o meu terror não te farás temer; nem uma pressão pesada sobre ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Tu falaste ao meu ouvido; tenho ouvido o som das tuas palavras, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, '\'Eu estou limpo e sem transgressão; eu sou inocente e não há pecado em mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Eis que Deus encontra oportunidades para me atacar; Ele me considera como seu inimigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Ele prende os meus pés; Ele vigia todos os meus caminhos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Vê, nisto não estás correto — porque Deus é maior que o homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Por que lutas contra Ele? Deus não tem que explicar nenhum dos Seus feitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Pois Deus fala uma — sim, duas, embora o homem não perceba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Em um sonho, em uma visão da noite, quando sono profundo cai sobre os homens, totalmente adormecidos nas suas camas —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'então, Deus abre os ouvidos dos homens e os assusta com ameaças,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'para tirar o homem dos seus propósitos pecaminosos e do seu orgulho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Deus afasta a vida dos homens do poço, de caminhar para a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'O homem é punido também com dor na sua cama, com constante agonia em seus ossos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'para que sua vida abomine comida e sua alma abomine iguarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Sua carne é consumida e isto não pode ser visto; seus ossos, que não se viam, agora aparecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'De fato, sua alma se aproxima do poço; sua vida, daqueles que a desejam destruir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Mas, se houver um anjo que pode ser mediador para ele, um mediador, um dentre os milhares de anjos, para mostrar a ele o que é certo fazer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'e, se o anjo for gentil com ele e disser a Deus: \'Salva esta pessoa de ir ao fundo do poço; eu encontrei redenção para ela\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'sua carne se restaurará como carne de uma criança; ele retornará aos dias de força da juventude.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Ele orará a Deus e Deus será generoso com ele, para que veja, com alegria, o rosto de Deus. Deus dará à pessoa sua vitória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Então, essa pessoa cantará em frente a outras e dirá: \'Eu pequei e perverti o que era justo, mas meu pecado não foi punido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Deus resgatou a minha alma de ir ao fundo do poço; minha vida continuará a ver a luz\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Eis que Deus fez todas estas coisas com uma pessoa, duas e três vezes para com o homem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'para trazer de volta sua alma do poço, para que ele seja iluminado com a luz da vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Presta atenção, Jó, e ouve-me; fica em silêncio e eu falarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Se tiveres qualquer coisa para dizer, responde-me; fala, porque eu desejo provar que estás correto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Se não tiver, então, escuta-me; permanece em silêncio e eu te ensinarei a sabedoria\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Além disso, Eliú continuou a falar:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, '\"Ouvi as minhas palavras, homens sábios; escutai-me, vós, que tendes conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Pois o ouvido distingue as palavras assim como o paladar saboreia a comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Que escolhamos por nós mesmos o que é justo: que descubramos entre nós o que é bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Pois Jó disse: \'Eu sou justo, mas Deus tirou meus direitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Apesar dos meus direitos, eu sou considerado um mentiroso. Minhas feridas são incuráveis, embora sem pecado\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Que homem é como Jó, que bebe zombaria como água,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'que anda na companhia daqueles que fazem o mal e dos homens perversos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Pois ele disse: \'É inútil uma pessoa ter prazer fazendo o que Deus quer\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Escutai-me, vós, homens de entendimento: longe de Deus fazer maldade; longe do Todo Poderoso cometer pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Porque Ele paga o trabalho de uma pessoa; recompensa a todo homem nos seus próprios caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Certamente, Deus não faz maldade, o Todo Poderoso nunca perverte a justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'A quem Deus entregou autoridade para governar toda a Terra? Quem colocou todo mundo sob Sua autoridade?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Se as Suas intenções fossem definidas somente Nele, e, se Ele juntasse de volta para Si mesmo o Seu espírito e Seu sopro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'então, toda carne junta pereceria; a humanidade voltaria ao pó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Se agora tendes entendimento, escutai isto: escutai o som das minhas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Pode alguém que odeia justiça governar? Condenarás a Deus, que é justo e poderoso?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Deus, que fala ao rei: \'Tu és vil\', ou aos nobres: \'Vós sois maus\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Deus, que não faz acepção entre pessoas e os líderes; não estima as pessoas ricas mais que as pobres, porque todos são obras de Suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Num momento, eles morrerão; à meia noite, pessoas serão agitadas e morrerão; pessoas poderosas morrerão, mas não por mãos humanas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Porque os olhos de Deus estão sobre os caminhos das pessoas; Ele vê todos os seus passos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Não há escuridão ou densas trevas onde os praticantes da iniquidade podem esconderem-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Porque Deus não precisa examinar mais a pessoa; não há necessidade de comparecer diante Dele para o julgamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Ele quebra homens poderosos em pedaços; seus caminhos não precisam de mais investigação; põe os outros em seus lugares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Dessa forma, Ele tem conhecimento dos seus feitos; Ele lança essas pessoas na escuridão, elas são destruídas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'À vista dos outros, Ele os mata devido aos seus maus feitos como criminosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Porque deixaram de segui-Lo e não quiseram reconhecer nenhum dos Seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Assim, eles fazem o clamor do povo pobre chegar a Ele. Ele ouve o choro do povo aflito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Quando Ele fica em silêncio, quem pode Lhe condenar? Se Ele esconde a Sua face, quem O pode encontrar? Ele reina sobre as nações e todas as pessoas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'de modo que o homem corrupto não reine e não haja ninguém que engane o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Imagina que alguém diga a Deus: \'Certamente sou culpado, mas não irei pecar mais;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'ensina-me o que eu não posso ver; eu cometi pecado, mas não farei mais\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Tu pensas que Deus irá punir o pecado dessa pessoa, ainda que tu não gostes do que Deus faz? Deve escolher, não eu. Assim, diz aquilo que tu sabes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Homens de entendimento me dirão — de fato, qualquer homem sábio que me ouvir dirá:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, '\'Jó fala sem conhecimento, suas palavras são sem entendimento\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Se tão somente Jó colocado em julgamento, nos pequenos detalhes, devido à sua fala como dos homens maus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Ele adiciona rebelião ao seu pecado; aplaude, zombando no nosso meio; ele continuou falando palavras más contra Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Posteriormente, Eliú continuou, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, '\"Pensas que é justo dizer: \'Meu direito perante Deus\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Pois perguntas: \'Qual utilidade isso tem para mim?\' e \'Eu estaria melhor se tivesse pecado?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Eu vos responderei, a ti e aos teus amigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Olhai para os céus e vede; eis que as núvens estão muitos mais altas que vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Se tu pecares, que mal tu fazes a Deus? Se as tuas transgressões se amontoam, que fazes a Ele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Se és justo, que podes dar a Ele? Que receberá Ele da tua mão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'A tua maldade só pode ferir um homem, já que tu és homem; e a a tua justiça só pode favorecer a outro filho de um homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Por causa de muitos atos de opressão, pessoas lamentam; elas clamam por socorro dos braços de homens poderosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Mas ninguém diz: \'Onde está Deus, meu Criador, que nos dá canções à noite,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'que nos ensina mais que às feras do campo e que nos faz mais sábios que os pássaros dos céus?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Ali eles lamentam, mas Deus não responde por causa do orgulho do homem mau.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Deus certamente não ouvirá um clamor insensato, o Todo Poderoso não prestará atenção a isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Quanto menos Ele lhe responderá se disseres que não O vê, que o teu caso está diante Dele e que estás esperando por Ele!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Quanto menos Ele te responderá se disseres que Ele nunca pune a ninguém com ira e que Ele não está muito preocupado com o orgulho das pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Então, Jó abre a sua boca apenas para falar tolice, ele amontoa palavras sem entendimento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Eliú continuou e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, '\"Permite-me que alongue o meu discurso e te mostrarei algumas coisas, pois tenho um pouco mais a dizer em defesa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Adquirirei o meu conhecimento lá de longe; reconhecerei que justiça pertence ao meu Criador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Por isso, minhas palavras não serão falsas; alguém que é maduro em conhecimento está contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Vê, Deus é grande e não despreza a ninguém; Ele é poderoso em entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Ele não preserva a vida de pessoas pecadoras; pelo contrário, faz o que é reto para aqueles que sofrem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Ele não retira os Seus olhos das pessoas justas, mas assenta-os em tronos como reis para sempre; eles são exaltados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Se forem presos por correntes e amarrados em cordas de sofrimento,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'então, Ele lhes revela o que fizeram, suas transgressões e seu orgulho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Ele também abre os ouvidos deles para as Suas instruções e os comanda para retornarem da iniquidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Se eles O ouvirem e O adorarem, passarão os seus dias em prosperidade e os seus anos em contentamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Porém, se eles não ouvirem, perecerão pela espada, morrerão porque não têm conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Aqueles que são corruptos guardam sua ira no coração; não clamam por ajuda mesmo quando Deus os amarra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Eles morrem em sua juventude; as suas vidas terminam entre os prostitutos de cultos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Deus resgata pessoas aflitas por meio de suas aflições; Ele abre os ouvidos delas por meio de suas opressões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Por isso, Ele deseja tirar-te do desespero para um lugar amplo, onde não exista tribulação e onde a sua mesa será preparada com comida cheia de gorduras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Mas tu estás cheio de julgamento acerca de pessoas más; julgamento e justiça estão diante de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Não permitas que a tua ira te seduza para a zombaria ou que a grandeza do resgate te atraia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Pode a tua riqueza te beneficiar, de maneira que não te aches em desgraça ou pode toda a força do teu empenho te ajudar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Não anseies pela noite para cometer pecado contra outros, quando as pessoas são tiradas das suas casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Sê cuidadoso para que não te voltes ao pecado, porque estás sendo testado através do sofrimento para que tu fiques distante do pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Vê, Deus é exaltado em Seu poder; quem é um mestre igual a Ele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Quem alguma vez instruiu-Lhe acerca do Seu caminho? Quem pode dizer a Ele: \'Tu cometeste injustiça\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Lembra-te de exaltar as obras Dele, sobre as quais as pessoas têm cantado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Todas as pessoas olharam para estas obras, mas vêm estas obras apenas de longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Vê, Deus é grande, mas nós não O entendemos bem; o número dos Seus anos é incalculável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Ele faz subir as gotas de água que Ele destila como chuva do Seu vapor;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'gotas que as nuvens descarregam e gotejam em abundância sobre a raça humana.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'De fato, poderá alguém entender a extensa propagação das nuvens e dos relâmpagos da Sua habitação?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Vê, Ele espalha o Seu relâmpago em volta Dele e cobre os fundamentos do oceano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Desta maneira, Ele julga as pessoas e dá comida em abundância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Ele segura em Suas mãos o relâmpago até que ordena a atingir os seus alvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Seu trovão avisa sobre a tempestade e o gado também pode ouvir que ela se aproxima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'De fato, nisto, meu coração treme; sai do seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Ouve, ó, ouve o barulho da Sua voz, o som que sai da Sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Ele o envia abaixo do céu e envia Seu relâmpago para as fronteiras da Terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Uma voz ruge depois; Ele troveja com a voz da Sua majestade; Ele não restringe Seu relâmpago quando Sua voz é ouvida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Deus troveja maravilhosamente com Sua voz. Ele faz grandes coisas que não podemos compreender.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Pois Ele diz à neve: \'Cai sobre a terra!\'; da mesma forma, Ele diz à chuva: \'Sê uma grande chuva!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Ele pára a mão de cada homem no trabalho, para que todas as pessoas que Ele fez possam ver Seus atos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Então, os animais começam a se esconder em suas tocas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'A tempestade vem de sua câmara do sul e o frio dos ventos que se espalham no norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Pelo sopro de Deus, o gelo é formado; a expansão das águas é congelada como metal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'De fato, Ele sobrecarrega a densa nuvem com umidade; Ele espalha Seus relâmpagos através das nuvens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Ele guia as nuvens ao redor por Sua orientação, para fazer o que Ele manda sobre a superfície de todo o mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Ele faz tudo isso acontecer; às vezes, para correção, às vezes, em favor de sua Terra e, às vezes, como ações de fidelidade à aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Ouve isto, Jó! Pára e pensa sobre as ações maravilhosas de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Sabes como Deus força Sua vontade sobre as nuvens e faz os relâmpagos iluminá-las?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Tu compreendes o equilíbrio das nuvens, as maravilhosas ações de Deus, que é perfeito em conhecimento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Tu compreendes como tuas vestes esquentam quando a terra se torna ainda calma por causa do vento que vem do sul?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Tu podes espalhar o céu, como Ele pode — o céu, que é forte como um espelho de metal fundido?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Ensina-nos o que devemos dizer a Ele, pois não podemos estabelecer argumentos por causa da escuridão das nossas mentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Ele deveria ser informado de que desejo falar com Ele? Poderia uma pessoa desejar ser engolida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Agora, pessoas não podem olhar para o sol quando está brilhando no céu, depois de o vento passar e limpá-lo de suas nuvens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Para fora do norte, vem esplendido ouro — acima de Deus, há espantosa majestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'No que diz respeito ao Todo Poderoso, não podemos encontrá-Lo; Ele é grande em poder e justiça. Ele não oprime as pessoas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'portanto, as pessoas O temem. Ele não presta qualquer atenção àqueles que são sábios em suas próprias mentes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Então, Yahweh chamou Jó para fora de uma tempestade violenta e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, '\"Quem é este que traz escuridão aos Meus planos com palavras sem sentido?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Agora, cinge teus lombos como homem porque te farei perguntas e tu deverás Me responder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Onde estavas quando coloquei os fundamentos da Terra? Dize-Me, já que tens tanto entendimento!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Quem determinou suas dimensões? Dize-Me, se sabes! Quem esticou a linha de medida sobre ela?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Sobre o que foram colocados seus alicerces? Quem colocou a pedra angular');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'quando as estrelas da manhã cantaram juntas e todos os filhos de Deus gritaram de alegria?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Quem fechou o mar com portas quando ele se arrebentou, como se tivesse saído do ventre —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'quando lhe revesti de nuvens e fiz da densa escuridão suas fraldas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Isso foi quando marquei Meus limites para o mar e quando coloquei suas grades e portas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'quando lhe disse: \'Podes vir até aqui, mas não além! Aqui é onde colocarei um limite para o orgulho das tuas ondas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Alguma vez, desde o inicio de teus dias, deste ordens à manhã para começar? E já fizeste com que o nascer do sol conhecesse seu devido lugar, no funcionamento das coisas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'para que segurasse os cantos da Terra, de forma que os corruptos pudessem ser sacudidos para fora dela?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'A Terra muda sua aparência como o barro muda com a marca do carimbo; todas as coisas nela se levantam claramente como as dobras de um pedaço de roupa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'A \'luz\' dos corruptos é tirada; seu braço levantado é quebrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Tu já foste pelas fontes das águas do mar? Já andaste pelas partes mais baixas das profundezas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Os portões da morte já foram revelados a ti? Já viste os portões da sombra da morte?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Já percebeste a Terra em sua expansão? Dize-Me, já que sabes tudo isso!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Onde está o caminho para o lugar de descanso da luz? E, para as trevas, onde está seu lugar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Tu podes levar a luz e as trevas para seus lugares de trabalho? Podes levá-las de volta para suas casas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Sem dúvida, sabes porque já tinhas nascido; o número de teus dias é tão grande!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Já entraste nas reservas para a neve ou já viste as reservas para o granizo —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'essas coisas que guardei para os tempos da aflição, para os tempos da batalha e de guerra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Qual é o caminho pelo qual os relâmpagos são distribuídos? Ou por onde os ventos são espalhados do leste sobre a Terra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Quem criou os canais para as inundações da chuva? Ou quem criou os caminhos para o relâmpagos do trovão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'para fazer com que chova nas terras onde não existem pessoas e nos desertos onde ninguém vive,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'para suprir as necessidades das regiões inférteis e solitárias; para fazer crescer os renovos da erva?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Existe um pai da chuva? Que criou as gotas do orvalho?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'De que ventre surgiu o gelo? Quem gerou a geada branca do céu?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'As águas se escondem e se tornam como pedra; as superfícies das profundezas se congelam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Podes apertar as correntes do Sete Estrelos ou desfazer os cordéis do Órion?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Podes fazer com que as constelações apareçam no tempo certo? Podes guiar a Ursa com seus filhos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Conheces as leis dos céus? Podes ordenar as normas do céu sobre a Terra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Podes levantar tua voz até as nuvens, para que a abundância das águas da chuva te cubram?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Podes mandar relâmpagos para que saiam e te digam: \'Estamos aqui\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Quem colocou sabedoria nas nuvens ou deu entendimento à névoa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Quem pode contar as nuvens com sua habilidade? Quem pode derramar água dos odres celestiais');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'quando o pó se torna uma dura massa e os torrões da Terra se colam?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Podes caçar presa para as leoas ou satisfazer o apetite dos leõezinhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'quando se inclinam nos seus covis e se juntam escondidos para se deitar e esperar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Quem providencia presas para os corvos quando seus pequeninos clamam a Deus e cambaleiam por falta de comida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Tu sabes a que horas cabras silvestres dão à luz na rocha? Podes observar as corças quando dão suas crias?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Podes tu contar os meses da sua gestação? Tu sabes a hora que dão à luz as suas crias?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Elas se encurvam, dão à liuz as suas crias e, depois, terminam as suas dores de parto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Os seu filhotes se tornam fortes e crescem num campo aberto; elas saem e não voltam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Quem deixa o jumento selvagem ir livremente? Quem soltou as cadeias do jumento bravo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'cujo lar Eu fiz no deserto e cuja casa fiz na terra salgada?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Ele ri com desprezo do ruído na cidade; ele não ouve o grito do condutor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Ele vagueia sobre as montanhas como seu pasto; lá, ele procura por toda planta verde para comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Estará o búfalo feliz em te servir? Consentirá ele em estar no teu cural?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Com a corda, poderás controlar o búfalo para cultivar a terra? Irá ele arar os vales para ti?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Poderás confiar nele porque a força dele é grande? Poderás deixar o teu trabalho para ele fazer?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Poderás depender dele para trazer os teus grãos para casa, para juntar os grãos no teu celeiro?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'As asas da avestruz batem orgulhosamente, mas as suas asas e penas são de amor?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Ela deixa os seus ovos na terra e ela os deixa aquecidos no pó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Ela se esquece de que um pé pode esmagá-los ou uma besta selvagem poderá pisoteá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Ela lida duramente com os seus filhos como se não fossem dela. Ela não teme que o seu trabalho seja em vão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'porque Deus a privou da sabedoria e não lhe deu nenhum entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Quando ela corre rapidamente, ela ri com desprezo do cavalo em que monta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Tu deste ao cavalo a sua força? Vestiste o seu pescoço com as suas crinas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Fizeste com que ele saltasse como gafanhoto? A majestade do seu respirar é temível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Pateando, escava o chão e se alegra com a sua força; ele corre ao encontro das armas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Ele zomba do medo e não se espanta; ele não recua diante da espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Ao som da aljava soando contra o seu flanco, junto da lança e do dardo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Ele engole o chão com ferocidade e raiva; ao som da trombeta, ele não poderá ficar em pé num lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'No entanto, sempre que a trombeta toca, ele diz: \'Ah!\'. Ele cheira a guerra de longe — os gritos trovejantes dos comandantes e os gritos de guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'É por tua sabedoria que o gavião voa para que estenda as suas asas para o sul?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'É por tuas ordens que a águia voa alto e faz o seu ninho no alto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Ela vive no penhasco e faz a sua casa no cume do penhasco, uma fortaleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'De lá, ela procura as suas vítimas; os seus olhos as vêm de muito longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'E seus filhos também bebem o sangue, onde estão pessoas mortas, ali está ela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Yahweh continuou a falar para Jó; Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '\"Pode alguém que deseja criticar tentar corrigir ao Altíssimo? Aquele que argumenta com Deus, que ele responda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Então, Jó respondeu a Yahweh e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, '\"Vê, eu sou insignificante; como posso responder a Ti? Eu ponho a minha mão sobre a minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Falei uma vez e não responderei; aliás, duas vezes, mas não procederei adiante\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Depois, Yahweh respondeu a Jó no meio de uma tempestade e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, '\"Agora, cinge os teus lombos como homem, porque vou te fazer perguntas e tu deverás Me responder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Irás realmente dizer que sou injusto? Irás Me condenar para que tu declares que estás certo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Tens tu um braço como Deus? Podes tu trovejar com uma voz como a Dele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Agora, veste-te de glória e dignidade; cobre-te de honra e majestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Derrama o excesso de tua ira; olha para todo aquele que é soberbo e humilha-o.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Olha para todo aquele que é orgulhoso e humilha-o; pisa sobre as pessoas perversas onde elas ficam de pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Enterra-os na terra juntos, aprisiona as suas faces em lugar escondido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Depois, irei também reconhecer a ti que a tua mão direita pode te salvar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Contempla agora o brutamonte que Eu fiz assim como te fiz; ele come capim tal como o boi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Vê, a sua força está nos seus lombos; o seu poder está nos músculos da sua barriga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Ele movimenta a sua cauda tal como um cedro; os tendões da sua coxa estão bem juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Os seus ossos são como tubos de bronze; as suas pernas são como barras de ferro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Ele é o chefe das criaturas de Deus. Apenas Deus, que o fez, pode vencê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Os montes lhe provêm alimento; as bestas do campo brincam por perto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Ele se deita debaixo dos lotus no abrigo do mato, nos pântanos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'As plantas de lotus cobrem-lhe com a sua sombra; os salgueiros do riacho estão a sua volta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Se o rio inunda as suas margens, ele não estremece; ele é confiante, ainda que o rio Jordão venha a subir até a sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Poderá alguém capturá-lo com um gancho ou perfurar o seu nariz com uma armadilha?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Tu podes tirar o leviatã com um anzol? Ou amarrar a sua mandíbula com uma corda?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Tu podes colocar uma corda em seu nariz ou furar a sua mandíbula com um gancho?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Será que ele vai fazer muitos pedidos para ti? Ele falará suaves palavras para ti?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Fará ele um acordo contigo, de maneira que irás levá-lo como servo para sempre?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Brincarás com ele como farias com um pássaro? Tu vais laçá-lo para suas servas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Irão os grupos de pescadores negociar por ele? Irão eles dividi-lo no comércio entre os mercadores?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Poderás tu preencher seu couro com arpões ou sua cabeça com lanças de pescador?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Coloca tua mão sobre ele apenas uma vez e irás lembrar a batalha e não o farás mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Vê, a esperança de qualquer um que faz isso é mentira; ou não seria alguém jogado jogado para baixo ao avistá-lo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Nenhum é tão feroz que se atreva a agitar o leviatã; quem pois é ele que pode ficar de pé diante de Mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Quem primeiro Me deu qualquer coisa que Eu precisasse retribuir? Tudo que está abaixo dos céus é Meu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Eu não vou manter o silêncio em relação às pernas do leviatã, nem sobre a questão da força, nem sobre sua graciosa forma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Quem pode tirar seus revestimentos externos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Quem pode penetrar sua dupla armadura? Quem pode abrir as portas do seu rosto — rodeado por seus dentes, que são um terror?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Suas costas são compostas de linhas de escudos, apertados como um estreito selo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Um está tão perto do outro que o ar não pode passar entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Eles estão unidos; permanecem juntos, de modo que não podem ser separados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Seu forte espirro emite lampejo brilhante; seus olhos são como as pálpebras do amanhecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'De sua boca, saem tochas queimando, faísca de fogo saltam dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'De suas narinas, saem fumaça como uma panela em ebulição sobre um fogo abanado para ficar bem quente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Sua respiração acende carvão em chamas; o fogo sai da sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Em seu pescoço, está a força e o terror dança em sua frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'As dobras da sua carne estão unidas; elas estão firmes nele; elas não podem ser movidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Seu coração é tão duro como uma pedra — de fato, tão duro como uma pedra de moinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Quando ele se levanta, até os deuses têm medo; por causa do medo, eles fogem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Se uma espada toca nele, não faz nada — nem a lança faz, nem a seta, ou qualquer outra arma apontada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, 'Ele pensa no ferro como se fosse palha e, no bronze, como se fosse madeira podre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, 'Uma flecha não pode fazê-lo fugir; para ele, pedras lançadas tornam-se restolhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, 'Cacetes são considerados como palha; ele ri do zumbido do voo de uma lança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, 'As suas partes inferiores são como pedaços pontiagudos de cerâmica quebrada; Ele deixa uma trilha de lama espalhada como se fosse um máquina de debulhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, 'Ele faz o profundo espumar como um pote de água fervente; ele torna o mar como caldera de ungento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, 'Ele cria uma rastro de ondas brilhantes após si; alguém poderia pensar que a profundeza tinha cabelo acinzentado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, 'Na Terra, não há igual a ele, que foi feito para viver sem medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, 'Ele vê tudo o que é orgulhoso; ele é rei sobre todos os filhos do orgulho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Então, Jó respondeu a Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, '\"Eu sei que Tu podes fazer todas as coisas, que nenhum propósito Teu pode ser impedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Tu me perguntaste: \'Quem é este que, sem conhecimento, encobre planos?\'. De fato, falei coisas que eu não entendia, coisas muito difíceis de compreender, sobre as quais eu nada sabia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Tu me disseste: \'Escuta, agora, e Eu falarei; perguntar-te-ei e tu me dirás\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Eu Te conhecia pelo escutar de meus ouvidos, mas agora meus olhos Te veem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Eu me desprezo; arrependo-me no pó e na cinza\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Aconteceu que depois de ter dito estas palavras para Jó, Yahweh disse a Elifaz, o temanita: \"Minha ira inflamou-se contra ti e contra teus dois amigos por não terdes dito coisas certas acerca de Mim como fez meu servo Jó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Agora, então, levai para vós sete touros e sete carneiros, ide ao meu servo Jó e oferecei-os para vós em holocausto. Meu servo Jó intercederá por vós e Eu aceitarei a sua oração para que Eu não vos trate conforme a vossa insensatez. Pois não dissestes o que é certo a Meu respeito, como Meu servo Jó fez\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Então, Elifaz, o temanita, Bildad, o suíta, e Zofar, o naamatita, foram e fizeram o que Yahweh havia lhes ordenado e Yahweh aceitou a intercessão de Jó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Quando Jó orou pelos seus amigos, Yahweh restaurou seus bens. Yahweh deu-lhe o dobro do que ele possuía antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Então, todos os irmãos de Jó e todas as suas irmãs e todos os que antes o conheciam vieram e comeram com ele uma refeição em sua casa. Consolaram e confortaram-lhe sobre todas as desgraças que Yahweh lhe trouxera. Cada pessoa deu a Jó uma moeda de prata e um anel de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Yahweh abençoou o final da vida de Jó mais que o começo; ele tinha catorze mil ovelhas, seis mil camelos, mil juntas de bois e mil jumentas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Ele tinha também sete filhos e três filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'A primeira filha chamou-lhe Jemima, a segunda, Quézia e a terceira, Quéren-Hapuque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Em toda a Terra, não foram achadas mulheres tão formosas como as filhas de Jó. Seu pai deu-lhes uma herança bem como aos seus irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Depois disso, Jó viveu cento e quarenta anos; ele viu seus filhos e os filhos dos seus filhos até a quarta geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Então, Jó morreu, sendo velho e cheio de dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Como é abençoado o homem que não anda no conselho dos maus, não permanece no caminho dos pecadores, nem se assenta na roda dos zombadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Mas o seu prazer está na Lei de Yahweh e, na Sua Lei, medita dia e noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Ele será como a árvore plantada perto das correntes das águas, que produz seu fruto na estação certa e cujas folhas não murcham. Ele terá êxito em tudo o que fizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Com os perversos não é assim. Eles são como a palha que o vento leva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Por isso, os perversos não permanecerão de pé no julgamento, nem os pecadores no ajuntamento dos justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Pois Yahweh aprova o caminho dos justos, mas o caminho dos perversos perecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Por que as nações estão em rebelião e os povos conspiram em vão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Os reis da terra juntos se levantam, e os governadores se unem e conspiram contra Yahweh e contra o Seu Messias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '\"Vamos quebrar as algemas que eles nos colocaram e arrancar suas correntes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Aquele que se assenta nos céus ri deles. Yahweh zomba deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Então, na Sua ira, Ele lhes falará e, com Sua fúria, os aterrorizará, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '\"Eu mesmo ungi Meu rei em Sião, Meu santo monte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Eu anunciarei o decreto de Yahweh. Ele me disse: \"Tu és Meu Filho! Neste dia Eu Te gerei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Pede-Me e Eu Te darei as nações por herança e as regiões mais distantes da terra por Tua posse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Tu as quebrarás com o cetro de ferro. Tu as esmagarás como um pote de barro.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Agora, ó reis, estais avisados; sede corrigidos vós, governadores da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Adorai a Yahweh com temor e regozijai-vos com tremor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Beijai o Filho para que Ele não Se ire convosco, e não sejais mortos quando Sua ira rapidamente se acender. Abençoados são todos aqueles que se refugiam Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Salmo de Davi, quando fugiu de seu filho Absalão. Yahweh, como tem crescido o número dos meus inimigos! Muitos se levantam contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Muitos dizem a meu respeito: \"Deus não o ajudará.\" Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Mas Tu, Yahweh, és um escudo em volta de mim, és a minha glória e Quem me ergue a cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Levanto a voz para Yahweh, e Ele me responde do Seu santo monte. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Eu deito e durmo; acordo, pois Yahweh me sustém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Não temerei as multidões que se levantaram contra mim por todos os lados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Levanta, Yahweh! Salva-me, meu Deus! Pois Tu acertarás o maxilar de todos os meus inimigos; Tu quebrarás os dentes dos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'A salvação vem de Yahweh. Que Tuas bênçãos estejam sobre o Teu povo. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Para o regente musical; com instrumentos de cordas. Salmo de Davi. Responde-me quando clamo, Deus da minha justiça; em minha aflição, Tu tens me aliviado. Tem misericórdia de mim e escuta a minha oração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Ó povo, até quando transformareis minha honra em vergonha? Até quando amareis aquilo que é inútil e procurareis mentiras? Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Sabei que Yahweh separa os piedosos para Si mesmo; Yahweh ouvirá quando eu clamar por Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Irai-vos, mas não pequeis! Meditai em vosso coração na vossa cama e em silêncio. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Oferecei sacrifícios de justiça e colocai vossa confiança em Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Muitos dizem: \"Quem vai nos mostrar algo bom?\". Yahweh, levanta a luz do Teu rosto sobre nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Tu tens dado mais alegria ao meu coração que a alegria deles quando abundantes são seus grãos e vinhos novos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'É em paz que eu me deitarei e dormirei, pois somente Tu, Yahweh, me trazes segurança e proteção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Para o regente musical; com instrumentos de sopro. Salmo de David. Escuta meu clamor, Yahweh, considera o meu gemer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Ouve o som do meu clamor, meu Rei e meu Deus, pois é a Ti que eu oro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Yahweh, pela manhã, Tu ouves o meu choro; pela manhã, eu trago a Ti minha petição e aguardo com expectativa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Certamente, Tu és um Deus que não aprova o mal; quem o pratica não habitará Contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'O arrogante não ficará de pé em Tua presença; Tu odeias todo comportamento malicioso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Tu destróis os mentirosos; Yahweh despreza a violência e o homem falso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Mas, quanto a mim, por causa do Teu amor leal, eu entrarei em Tua casa e, em reverência, me prostrarei ante Teu santo templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Yahweh, guia-me em Tua justiça por causa dos meus inimigos; faze o Teu caminho reto diante de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Não há verdade na boca dos meus adversários; seu interior é mau, suas gargantas são como um sepulcro aberto, e eles seduzem com suas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Declara-os culpados, ó Deus; que seus esquemas sejam a sua queda! Expulsa-os por suas muitas transgressões, pois se rebelaram contra Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Todavia, alegrem-se todos aqueles que se refugiam em Ti; permite que sempre gritem de júbilo porque Tu os defendes; deixa que se regozijem em Ti todos os que amam o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Pois Tu, Yahweh, abençoas o justo e, como um escudo, o cercas com Teu favor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Para o regente musical; com instrumentos de cordas. Adaptado para o estilo Seminite. Salmo de Davi. Yahweh, não me repreendas com raiva ou me disciplines em Tua ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Tem misericórdia de mim, Yahweh, pois sou frágil. Cura-me, Yahweh, pois meus ossos estão tremendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Minha alma também está muito perturbada. Yahweh, até quando isso vai continuar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Retorna, Yahweh, e resgata-me! Salva-me por causa do Teu amor leal!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Pois, na morte, não há lembrança de Ti. No Sheol, quem Te louvará?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Estou cansado do meu gemido; todas as noites, molho minha cama com lágrimas, lavo o meu leito com elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Meus olhos escurecem de tristeza; eles enfraquecem por causa dos meus adversários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Afastai-vos de mim, todos vós que praticais a iniquidade, pois Yahweh tem escutado o som do meu choro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Yahweh escutou meu apelo por misericórdia; Yahweh aceitou minha oração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Todos os meus inimigos estão envergonhados e muito atribulados. Eles serão humilhados e se afastarão repentinamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Composição musical de Davi, a qual ele cantou a Yahweh acerca das palavras de Cuxe, o benjamita. Yahweh, meu Deus, refugio-me em Ti! Salva-me de todos aqueles que me perseguem, resgata-me!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'De outra forma, eles me atacarão como um leão, rasgando-me em pedaços, e ninguém mais será capaz de me livrar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Yahweh, meu Deus, se eu cometi injustiça e existe culpa em minhas mãos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'se fiz algum mal para aquele que estava em paz comigo ou prejudiquei meu adversário sem motivo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'então, que meu inimigo persiga a minha vida e a destrua; que ele pisoteie o meu corpo no chão e deixe-me desonrado no pó. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Levanta-Te, Yahweh, na Tua ira! Ergue-Te contra o furor dos meus inimigos! Desperta-Te em meu favor e cumpre Teus justos decretos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Todos os países se reúnam ao Teu redor; toma o Teu lugar de autoridade sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Tu, Yahweh, que julgas as nações, justifica-me porque eu sou justo e inocente, ó Altíssimo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Que as obras más dos perversos cheguem ao fim, mas que estabeleças os justos, ó justo Deus, Tu, que examinas corações e mentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Meu escudo vem de Deus, Aquele que salva o reto de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Deus é um justo juiz. A cada dia, mostra-Se indignado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Se alguém não se arrepender, Ele afiará Sua espada e preparará Seu arco para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Deus Se prepara para usar armas contra ele; faz Suas flechas flamejantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'O perverso gera a maldade, concebe planos destrutivos e dá à luz a falsidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Ele cava um buraco, aprofunda-o e, então, cai no buraco que fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Seus planos destrutivos se voltam contra si mesmo, pois sua violência cairá sobre sua própria cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Eu darei graças a Yahweh por Sua justiça; eu cantarei louvores a Yahweh Altíssimo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Para o regente musical; adaptado ao estilo Gitite. Salmo de Davi. Yahweh, nosso Deus, quão majestoso em toda a terra é o Teu nome! Tu, que revelas Tua glória acima dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Da boca das crianças e dos pequeninos, Tu fazes brotar força contra os Teus adversários, a fim de silenciar os inimigos e os rebeldes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Quando olho para o céu e contemplo o que os Teus dedos fizeram, a lua e as estrelas que fixaste no lugar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'que importância tem a raça humana para que dela Te lembres? E o ser humano para que o visites?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'No entanto, Tu o fizeste apenas um pouco menor que os seres celestiais, e, de glória e honra, o coroaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Tu o fizeste dominar sobre o trabalho das Tuas mãos; Tu puseste todas as coisas debaixo dos seus pés:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'todas as ovelhas e bois e até os animais selvagens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'as aves dos céus e os peixes do mar, tudo o que percorre as correntes dos mares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Yahweh, Senhor nosso, quão magnífico em toda a terra é o Teu nome!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Para o regente musical; adaptado para o estilo Mute-laben. Salmo de Davi. Eu darei graças a Yahweh com todo o meu coração! Contarei todos os Seus atos maravilhosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Eu estarei alegre, regozijarei em Ti; cantarei louvores ao Teu nome, ó Altíssimo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Quando meus inimigos retrocedem, eles caem e perecem diante de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Pois tu tens defendido minha justa causa; Tu sentas no Teu trono, ó justo juiz!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Tu aterrorizaste as nações com o Teu grito de guerra; Tu destruíste os ímpios e apagaste suas memórias para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Os inimigos caíram como ruínas, quando Tu derrubaste suas cidades. Todas as suas lembranças pereceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Mas Yahweh permanece para sempre; Ele estabelece o Seu trono para julgar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Ele julga o mundo de forma justa. Ele faz decisões justas para as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Yahweh também será uma fortaleza para os oprimidos, uma fortaleza em tempos difíceis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Aqueles que conhecem o Seu nome confiam em Ti, pois Tu, Yahweh, não abandonas aqueles que Te procuram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Adorai a Yahweh, que reina em Sião; anunciai às nações o que Ele tem feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Pois Deus, que vinga o sangue derramado, lembra-Se deles e não Se esquece do choro dos oprimidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Tem misericórdia de mim, Yahweh; vê como sou oprimido por aqueles que me odeiam, Tu, que podes me levantar dos portões da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Ó, que eu possa proclamar todo o Seu louvor! Nos portões da filha de Sião, eu me regozijarei em Tua salvação!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'As nações afundaram na cova que elas mesmas criaram; seus pés estão presos nas armadilhas que elas esconderam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Yahweh fez-Se conhecido; Ele executa os Seus julgamentos; os maus caem nas armadilhas de suas próprias ações. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Os corruptos voltam para trás, são mandados ao Sheol; este é o destino de todas as nações que se esquecem de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Mas os necessitados nem sempre serão esquecidos, nem a esperança dos oprimidos será frustrada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Levanta-te, Yahweh; não deixes o homem nos vencer; que as nações sejam julgadas na Tua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Apavora-os, Yahweh; que as nações saibam que são meramente mortais. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Por que, Yahweh, permaneces distante? Por que Te escondes nos momentos difíceis?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Os corruptos, em sua arrogância, perseguem o oprimido; que eles fiquem presos nas armadilhas que eles mesmos prepararam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Pois o corrupto se orgulha dos desejos do seu coração; ele bendiz ao ganancioso e insulta Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'O corrupto é orgulhoso; ele não busca a Deus; ele não pensa a respeito de Deus porque não se importa com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Seus caminhos sempre são prósperos, mas Teus julgamentos estão distantes da sua vista. Ele ridiculariza todos os seus adversários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'E diz, em seu coração: “Eu nunca serei abalado! Eu e minhas gerações não enfrentaremos adversidades”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Sua boca está cheia de maldição, de engano e de palavras maldosas e perigosas; sua língua fere e destrói.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Ele arma emboscada perto das vilas; nos lugares secretos, ele mata o inocente; seus olhos buscam alguma vítima indefesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Como um leão à espreita na toca, ele aguarda para pegar o oprimido. Ele o captura quando este cai em sua rede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Suas vítimas são abatidas e esmagadas; elas caem em suas fortes redes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Ele diz, em seu coração: \"Deus se esqueceu; Ele escondeu a Sua face e não se importa de olhar isso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Levanta-Te, Yahweh; ergue Tua mão, Deus! Não te esqueças dos oprimidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Por que o corrupto blasfema de Deus, em seu coração, dizendo: \"Tu não me responsabilizarás\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Tu, porém, tomaste conhecimento, porque sempre vês aquele que inflige miséria e tristeza; o desamparado confia em Ti; Tu proteges o órfão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Quebra o braço do homem corrupto e mau; faze-o prestar contas de toda a sua maldade, a qual ele achou que Tu não descobririas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Yahweh é o Rei para todo o sempre, as nações são expulsas de Sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Yahweh, Tu tens ouvido as necessidades dos oprimidos; Tu fortaleces o seu coração, Tu escutas as suas orações;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Tu defendes o órfão e o oprimido, para que ninguém na terra cause terror novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Para o regente musical. Salmo de Davi. Eu me refugio em Yahweh. Como dizeis vós a mim: \"Foge como um pássaro para a montanha”?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Vede! Os corruptos preparam seus arcos. Eles colocam suas flechas nas cordas para, da escuridão, atirarem nos retos de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Pois, se os alicerces estiverem destruídos, o que pode o justo fazer?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Yahweh está em Seu santo templo. O trono de Yahweh está nos céus. Seus olhos veem, Seus olhos examinam os filhos dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Yahweh examina ambos, os justos e os maus, porém odeia aqueles que amam praticar a violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Sobre os ímpios, Ele fará chover brasas vivas e enxofre; um vento escaldante será para eles a porção do Seu cálice!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Porque Yahweh é justo e ama a justiça; os justos verão a Sua face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Para o regente musical; adaptado para Sheminite. Salmo de Davi. Salva-nos, Yahweh! Porque não existem mais homens bons; desapareceram os homens fiéis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Todos dizem palavras vãs uns aos outros; falam com lábios bajuladores e com duplo sentido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Que Yahweh corte todos os lábios bajuladores e toda língua que declara palavras orgulhosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Esses são os que dizem: \"Com nossas línguas, venceremos. Quando nossos lábios falam, quem pode ser senhor sobre nós?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, '\"Por causa da violência contra os pobres e dos gemidos dos necessitados, Eu Me levantarei\", diz Yahweh, \"Eu providenciarei a segurança para aqueles que anseiam por ela.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'As palavras de Yahweh são puras, como prata purificada em uma fornalha na terra, refinada sete vezes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Tu és Yahweh! Tu nos sustentarás e, desta geração perversa, nos preservarás para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Os perversos rondam por todos os lados, quando o mal é exaltado entre os filhos dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Para o regente musical. Salmo de Davi. Por quanto tempo, Yahweh, Te esquecerás de mim? Por quanto tempo, esconderás de mim a Tua face?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Por quanto tempo, irei me preocupar e terei pesar no meu coração o dia todo? Por quanto tempo, meu inimigo triunfará sobre mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Olha para mim e responde-me, Yahweh, meu Deus! Ilumina os meus olhos ou dormirei o sono da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Não deixes meus inimigos dizerem: \"Eu o derrotei\"; que meus inimigos não digam: \"Eu prevaleci sobre o meu adversário\". Do contrário, eles se alegrarão quando eu for derrubado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Mas eu confio em Tua fiel aliança; meu coração se regozija em Tua salvação!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Eu cantarei a Yahweh porque Ele tem me tratado com muita generosidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Para o regente musical. Salmo de Davi. Diz o tolo, em seu coração: \"Não há Deus\". Eles são corruptos e cometeram atos abomináveis; não há ninguém que faça o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Yahweh olha do céu para os filhos dos homens para ver se há alguém que entenda, que busque a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Todos se desviaram, todos se tornaram corruptos; não há um que faça o bem, nenhum sequer!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Será que não conhecem nada, esses que cometem iniquidades, que devoram meu povo como quem come pão, e não invocam Yahweh?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Eles tremem de medo, porque Deus está no ajuntamento dos justos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Vós quereis humilhar o pobre. Todavia, Yahweh é o seu refúgio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Ah, se a salvação de Israel viesse de Sião! Quando Yahweh trouxer de volta Seu povo do cativeiro, então, Jacó exultará e Israel se alegrará!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Salmo de Davi. Yahweh, quem poderá habitar no Teu tabernáculo? Quem poderá morar no Teu santo monte?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'O que anda irrepreensivelmente, fazendo o que é reto e, de coração, fala a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'O que não calunia com sua língua, prejudicando os outros, nem insulta seu próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'O que despreza quem tem uma conduta vã, mas honra os que temem a Yahweh; o que mantém sua palavra, mesmo quando fica prejudicado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'O que não empresta dinheiro buscando lucro e não aceita suborno para testemunhar contra o inocente. Aquele que faz essas coisas nunca será abalado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Miktam de Davi. Protege-me, ó Deus, pois me refugio em Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Digo a Yahweh: \"Tu és o meu Senhor. Vem de Ti tudo o que tenho de bom\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Quanto às pessoas santas que estão na terra, elas é que são nobres; todo o meu prazer está na companhia delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Os que buscam outros deuses aumentarão suas aflições. Não derramarei ofertas de sangue aos seus deuses, nem exaltarei seus nomes com os meus lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Yahweh, Tu és a minha porção escolhida e meu cálice; Tu sustentas o meu destino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'As divisas caíram para mim em lugares agradáveis; certamente, a minha herança é prazerosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Glorificarei a Yahweh, que me aconselha; até mesmo à noite, minha mente me instrui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Em todo o tempo, tenho Yahweh diante de mim; não serei abalado, pois Ele está à minha direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Portanto, o meu coração se alegra e o meu espírito exulta. Certamente, vou viver em segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Pois não abandonarás a minha alma no Sheol, nem permitirás que o Teu fiel experimente a decomposição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Tu me ensinas o caminho da vida; na Tua presença, há alegria abundante; na Tua mão direita, há prazer eterno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Oração de Davi. Escuta a minha súplica por justiça, Yahweh; inclina Teus ouvidos ao meu pedido de ajuda! Ouve minha oração, que vem de lábios sinceros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Que a minha sentença venha da Tua presença; que Teus olhos vejam o que é correto!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Se Tu examinares o meu coração, se vieres a mim durante a noite, Tu me purificarás e não acharás nenhum plano mau; minha boca não transgredirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Quanto aos feitos da humanidade, pela palavra dos Teus lábios, mantive-me fora dos caminhos do homem perverso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Meus passos ficaram firmes em Teus caminhos; meus pés não vacilaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Clamo a Ti, ó Deus, pois me respondes; inclina os Teus ouvidos para mim e me escuta quando falo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Mostra, de maneira maravilhosa, a Tua fidelidade à aliança; Tu, que salvas com a Tua mão direita aqueles que em Ti se refugiam dos seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Protege-me como a menina dos Teus olhos; esconde-me, à sombra das Tuas asas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'dos maus que me agridem, dos inimigos que me cercam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Eles não têm misericórdia de ninguém; suas bocas falam com orgulho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Eles cercam meus passos, fixam seus olhos sobre mim para me derrubarem no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'São como um leão ansioso por uma vítima, como um leão novo à espreita no esconderijo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Levanta-Te, Yahweh! Ataca-os! Derruba-os! Com a Tua espada, resgata a minha vida dos perversos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Com a Tua mão, Yahweh, livra-me dos homens deste mundo, cuja herança está somente nesta vida! Enche-lhes o ventre de tudo o que lhes reservaste; que seus filhos sejam saciados com suas riquezas, e deixem o que sobrar às suas crianças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Quanto a mim, verei a Tua face em retidão. Quando eu despertar, ficarei satisfeito ao ver a Tua semelhança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Para o regente musical. Salmo de Davi, servo de Yahweh, quando ele cantou para Yahweh as palavras desta canção. No dia em que Yahweh o livrou das mãos de todos os seus inimigos e das mãos de Saul, ele cantou: Eu te amo, Yahweh, minha força.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Yahweh é minha rocha, minha fortaleza, o único que me traz à segurança; o meu Deus é a minha força; Nele eu me refugio. Ele é meu escudo, a força da minha salvação e o meu lugar seguro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Eu invocarei Yahweh, que é digno de ser adorado, e serei salvo dos meus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'As cordas da morte me cercaram, as correntezas da perdição me fizeram temer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'As cordas do Sheol me envolveram; as armadilhas da morte me prenderam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Na minha aflição, eu clamei por Yahweh; eu clamei por ajuda ao meu Deus. Do Seu templo, Ele ouviu a minha voz; meu clamor por socorro chegou à Sua presença, chegou aos Seus ouvidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Então, a terra se abalou e tremeu, e os fundamentos das montanhas foram sacudidos pela fúria de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Fumaça saiu de Suas narinas; fogo ardente saiu de Sua boca; brasas foram acesas por isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Ele abriu os céus e desceu, e uma densa escuridão estava debaixo de Seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Ele montou em um querubim e voou, deslizando nas asas do vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Ele fez da escuridão uma tenda ao Seu redor, fez morada em pesadas nuvens de chuva nos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Granizos e brasas de fogo caíram do trovão diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Yahweh trovejou nos céus! A voz do Altíssimo ressoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Ele atirou Suas flechas e dissipou Seus inimigos; muitos raios os dispersaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Então, ao Teu grito de guerra, Yahweh, e no sopro do vento de Tuas narinas, os canais de águas apareceram e os fundamentos do mundo foram expostos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Ele estendeu a mão das alturas e me segurou! Ele me tirou da correnteza das águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'E me resgatou da força dos meus inimigos, daqueles que me odiavam, que eram mais fortes que eu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Eles vieram contra mim no dia da minha aflição, mas Yahweh foi meu apoio!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Ele me colocou em um grande lugar aberto. Ele me salvou, pois Se agradou de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Yahweh me recompensou por causa da minha retidão; Ele me restaurou, pois minhas mãos estavam limpas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Pois permaneci nos caminhos de Yahweh e não me afastei perversamente do meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Todos os Seus decretos de justiça estão diante de mim. Quanto aos Seus estatutos, eu não me apartei deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Sou inocente diante Dele e me mantive afastado do pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Yahweh me restaurou por causa da minha retidão, pois minhas mãos estavam limpas diante dos Seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Para aqueles que são fiéis, Tu Te mostras fiel; para um homem íntegro, mostras integridade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Para aquele que é puro, Tu Te revelas puro; mas Tu reages à altura para com o perverso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Pois Tu salvas o aflito, mas humilhas aqueles que têm olhos orgulhosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Tu dás luz para minha lamparina; Yahweh, meu Deus, ilumina minha escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Pois, contigo, posso ultrapassar barreiras; pelo meu Deus, eu posso saltar por cima de muralhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Quanto a Deus, Seu caminho é perfeito. A palavra de Yahweh é pura! Ele é um escudo para aqueles que se refugiam Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Pois quem é Deus senão Yahweh? Quem é a rocha senão nosso Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'É Deus quem me cinge de força; Ele coloca o justo no seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Ele faz meus pés rápidos como um cervo e me coloca sobre as alturas!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Ele treina minhas mãos para a guerra e meus braços para dobrar um arco de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Tu me deste o escudo da Tua salvação. Tua mão direita me sustenta e o Teu favor me exalta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Tu fizeste um lugar plano para os meus pés, de modo que eles não escorreguem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Eu persegui meus inimigos e os capturei; e não retornei até que fossem destruídos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Eu os esmaguei até que não pudessem se levantar; eles caíram debaixo dos meus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Pois Tu me cingiste de força para a batalha; subjugaste todos aqueles que se levantaram contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Tu me entregaste o pescoço dos meus inimigos; eu aniquilei os que me odiavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Eles chamaram por socorro, mas ninguém os salvou; eles chamaram por Yahweh, mas Ele não respondeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Eu os reduzi a pequenos pedaços, como poeira diante do vento; eu os lancei fora como lama nas ruas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Tu me resgataste das contendas do povo. Tu me fizeste cabeça entre as nações. Povos que eu não conhecia sujeitaram-se a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Assim que me ouvem, eles me obedecem; estrangeiros foram forçados a se curvarem diante de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Os estrangeiros, tremendo, saem de seus esconderijos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Yahweh vive! Bendita seja minha Rocha! Que o Deus da minha salvação seja exaltado!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Este é o Deus que executa vingança por mim, que a mim sujeita nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Eu fui liberto de meus inimigos! Certamente, Tu me exaltas sobre aqueles que se levantam contra mim! Tu me resgataste do homem violento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Por isso, te darei graças, Yahweh, diante das nações; cantarei louvores ao Teu nome!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Deus dá grandes vitórias ao Seu rei e mostra Sua fidelidade à aliança ao seu ungido: por Davi e por seus descendentes, para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Para o regente musical. Salmo de Davi. Os Céus declaram a glória de Deus, e o firmamento faz conhecidas as obras das Suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Dia após dia esse discurso se manifesta; noite após noite revelam seu conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Não há som ou palavras, suas vozes não são ouvidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Sua mensagem, porém, vai por toda a terra e seu discurso, até os confins do mundo. Deus armou uma tenda para o sol entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'O sol é como um noivo saindo de seu aposento e como um homem forte que se regozija quando corre em sua jornada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'O sol nasce de um horizonte e atravessa o céu de uma ponta a outra, nada escapa do seu calor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'A lei de Yahweh é perfeita e refrigera a alma; o testemunho de Yahweh é fiel e torna sábio o simples.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'As instruções de Yahweh são justas e alegram o coração; o mandamento de Yahweh é límpido e traz luz para os olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'O temor de Yahweh é puro e duradouro; as justas declarações de Yahweh são verdadeiras e totalmente corretas!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'São mais valiosas do que ouro, mais do que muito ouro puro; são mais doces do que o mel quando este goteja dos favos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Sim, por elas teu servo é advertido; na obediência há grande recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Quem pode discernir todos os próprios erros? Limpa-me das falhas escondidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Livra teu servo também dos pecados da arrogância, não permita que ela governe sobre mim. Então eu serei perfeito e serei inocente das minhas transgressões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Que as palavras da minha boca e os pensamentos do meu coração sejam aceitáveis aos Teus olhos, Yahweh, minha Rocha e meu Redentor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Para o regente musical. Salmo de Davi. Que Yahweh te ajude no dia da tribulação; que o nome do Deus de Jacó te proteja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Que, do Seu santuário, te envie socorro e te ampare desde Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Que Ele Se lembre de todas as tuas ofertas e aceite os teus holocaustos. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Que Ele te conceda o desejo do teu coração e realize todos os teus planos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Então nos alegraremos em tua vitória e, no nome do nosso Deus, levantaremos bandeiras. Que Yahweh conceda todas as tuas petições.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Agora sei que Yahweh salva o Seu ungido; Ele responde do Seu santo céu e o resgata com a força da Sua mão direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Alguns confiam em carruagens, outros, em cavalos, mas nós invocamos o nome de Yahweh, nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Eles tropeçam e caem, mas nós nos erguemos e ficamos de pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Yahweh, salva o rei; ajuda-nos quando clamarmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Para o regente musical. Salmo de Davi. O rei regozija-se na Tua força, Yahweh! Quão grandemente ele exulta na Tua salvação!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Tu lhe concedeste o desejo de seu coração e não lhe negaste a petição dos lábios. Interlúdio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Pois Tu lhe trouxeste ricas bênçãos; puseste em sua cabeça uma coroa do mais puro ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Ele Te pediu vida e Tu lhe deste; concedeste-lhe longos dias para sempre e sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'A glória dele é grande por causa da Tua vitória; Tu lhe conferiste esplendor e majestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'A ele deste infinitas bênçãos e a alegria da Tua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Pois o rei confia em Yahweh; por causa do amor leal do Altíssimo ele não será abalado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Tua mão alcançará Teus inimigos; Tua mão direita alcançará todos aqueles que Te odeiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'No tempo da Tua ira, Tu os queimarás como em uma fornalha ardente. Yahweh os consumirá na Sua ira, e o fogo os devorará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Tu eliminarás seus filhos da terra; eles não terão descendentes entre a raça humana.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Se eles tramarem o mal contra Ti, não serão bem sucedidos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'pois Tu lhes farás correr de volta; Tu apontarás o Teu arco para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Sê exaltado, Yahweh, na Tua força! Nós cantaremos e louvaremos o Teu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Para o regente musical; adaptado para \"o ritmo do cervo\". Salmo de Davi. Deus meu, Deus meu, por que me abandonaste? Por que estás tão longe de me salvar e distante dos meus gritos de angústia?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Deus meu, eu clamo de dia, mas Tu não me respondes; e de noite eu não estou em silêncio, mas não encontro alívio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Ainda assim, Tu és santo; entronizado entre os louvores de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Nossos ancestrais confiaram em Ti; confiaram, e Tu os livraste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Clamaram a Ti, e foram resgatados. Confiaram em Ti, e não se desapontaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Mas eu sou um verme e não um homem; uma desgraça para a humanidade e desprezado pelo povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Todos aqueles que me veem zombam de mim; eles me insultam; balançam sua cabeça para mim e dizem:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, '\"Ele confia em Yahweh; que Yahweh o resgate. Que Ele o livre, pois regozija-se Nele.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Pois Tu me trouxeste do ventre; Tu me deste segurança quando eu estava no seio de minha mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'A Ti fui entregue desde que nasci; Tu és meu Deus desde que eu estava no ventre de minha mãe!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Não fiques longe de mim, pois as dificuldades estão perto; não há ninguém para me ajudar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Muitos touros me cercaram; fortes touros de Basã me rodeiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Eles abrem suas bocas contra mim como o bramido do leão rasgando sua vítima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Estou sendo derramado como água, e todos os meus ossos estão deslocados. Meu coração é como cera que se derrete nas minhas entranhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Minha força secou-se como um pedaço de cerâmica; minha língua gruda no céu da boca. Tu me deitaste no pó da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Cães me cercaram, fui rodeado por um bando de homens maus; eles perfuraram minhas mãos e pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Eu posso contar todos os meus ossos. Eles me olham e me encaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Dividem minhas vestes entre si; jogaram sortes pelas minhas roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Não fiques longe, Yahweh; por favor, apressa-Te em ajudar-me, minha força!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Resgata minha alma da espada e minha vida das garras dos cães selvagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Salva-me da boca do leão; resgata-me dos chifres de bois selvagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Declararei Teu nome para meus irmãos; no meio da assembleia eu Te louvarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Vós que temeis a Yahweh, louvai-O! Todos os descendentes de Jacó, honrai-O! Temei-O, todos vós, descendentes de Israel!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Pois Ele não desprezou nem abominou o sofrimento do aflito; Yahweh não escondeu Sua face dele; quando o aflito clamou a Ele, Ele ouviu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Meu louvor será por Ti na grande assembleia; eu cumprirei minhas promessas diante daqueles que O temem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Os oprimidos comerão e ficarão satisfeitos; aqueles que buscam Yahweh O louvarão. Que vossos corações vivam para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Todos os povos da terra se lembrarão e se voltarão para Yahweh. Todas as famílias das nações se curvarão diante de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Pois o reino é de Yahweh; Ele é quem governa sobre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Todas as pessoas prósperas da terra celebrarão um banquete e O adorarão; todos os que descem ao pó, aqueles que não podem preservar sua própria vida, se curvarão diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'A geração futura também O servirá; e eles contarão para a geração seguinte sobre Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Eles virão e proclamarão a Sua justiça; contarão sobre os Seus feitos para aqueles que ainda não nasceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Salmo de Davi. Yahweh é o meu pastor; de nada terei falta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Ele me faz deitar em verdes pastos e me guia às águas tranquilas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Ele restaura a minha vida; Ele me guia pelos caminhos justos por amor ao Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Mesmo se eu andar por um vale da mais escura sombra, não temerei mal algum, pois Tu estás comigo; Tua vara e Teu cajado me consolam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Preparas um banquete para mim, na presença dos meus inimigos. Unges a minha cabeça com óleo, o meu cálice transborda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Certamente, Tua bondade e amor leal me acompanharão todos os dias da minha vida; e morarei na casa de Yahweh para sempre!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Salmo de Davi. A terra e toda a sua plenitude são de Yahweh; o mundo e todos os que vivem nele;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'pois sobre os mares Ele fundou a terra e a estabeleceu sobre os rios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Quem subirá ao monte de Yahweh? Quem ficará de pé em Seu santuário?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Aquele que tem as mãos limpas e um coração puro; aquele que não deu testemunho falso e não faz um juramento enganador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Ele receberá a bênção de Yahweh e a justiça do Deus de sua salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Assim será a geração daqueles que O buscam, daqueles que buscam a face do Deus de Jacó. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Levantai vossas cabeças, ó portões; levantai-vos, ó portas eternas, para que entre o Rei da glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Quem é o Rei da glória? Yahweh, forte e poderoso; Yahweh, poderoso nas batalhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Levantai vossas cabeças, ó portões; levantai-vos, ó portas eternas, para que entre o Rei da glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Quem é o Rei da glória? Yahweh dos Exércitos; Ele é o Rei da glória! Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Salmo de Davi. A Ti, Yahweh, eu elevo a minha alma!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Meu Deus, confio em Ti. Não permitas que eu seja humilhado, nem que meus inimigos se regozijem triunfantes sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Nenhum dos que esperam em Ti sejam desonrados, mas que sejam envergonhados aqueles que agem traiçoeiramente, sem motivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Faze-me conhecer os Teus caminhos, Yahweh; ensina-me Tuas veredas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Guia-me em Tua verdade e ensina-me, pois Tu és o Deus da minha salvação; em Ti está minha esperança o tempo todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Lembra-Te, Yahweh, dos Teus atos de compaixão e da Tua fidelidade à aliança, pois eles sempre existiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Não Te lembres dos pecados ou da rebelião da minha juventude; lembra-Te de mim pela fidelidade à aliança, Yahweh, por causa da Tua bondade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Yahweh é bom e justo; por isso, Ele ensina o caminho aos pecadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Ele guia os humildes naquilo que é justo e lhes ensina o Seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Todos os caminhos de Yahweh são de amor constante e de fidelidade àqueles que guardam Sua aliança e Seus testemunhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Por amor do Teu nome, Yahweh, perdoa meu pecado, que é tão grande!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Quem é o homem que teme a Yahweh? O Senhor o instruirá no caminho que deve escolher.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Ele habitará em prosperidade, e seus descendentes herdarão a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'A intimidade de Yahweh é para aqueles que O temem; Ele os faz conhecer a Sua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Meus olhos estão sempre em Yahweh, pois Ele tirará meus pés da armadilha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Volta-Te para mim e tem misericórdia de mim, pois estou sozinho e aflito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'As tribulações do meu coração têm-se multiplicado; livra-me do meu sofrimento!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Vê minha aflição e minha fadiga; perdoa todos os meus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Vê como são muitos os meus inimigos; eles me odeiam com ódio cruel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Protege minha vida e me resgata; não permitas que eu seja humilhado, pois em Ti me refugio!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Que a integridade e a retidão me protejam, pois eu espero em Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Ó Deus, resgata Israel de todas as suas tribulações!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Salmo de Davi. Julga-me, Yahweh, pois tenho caminhado com integridade; eu tenho confiado em Yahweh, sem vacilar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Examina-me, Yahweh, e prova-me; prova a pureza da minha mente e do meu coração!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Pois Tua fidelidade à aliança está sempre diante dos meus olhos e tenho caminhado em Tua verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Eu não me associo com pessoas fraudulentas, nem me misturo com pessoas desonestas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Odeio a reunião dos malfeitores, e não vivo com os maus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Eu lavo minhas mãos na inocência, e vou para o Teu altar, Yahweh,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'cantando uma canção de louvor e relatando todas as Tuas maravilhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Yahweh, eu amo a casa onde Tu moras, o lugar onde a Tua glória habita!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Não me removas com os pecadores, nem minha vida com os homens sanguinários,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'cujas mãos executam conspirações, cuja mão direita pratica subornos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Mas, quanto a mim, andarei em integridade. Resgata-me e tem misericórdia de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Meus pés estão firmes em um terreno plano; nas assembleias, eu louvarei a Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Salmo de Davi. Yahweh é a minha luz e a minha salvação; de quem terei medo? Yahweh é o refúgio da minha vida; de quem teria pavor?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Quando os malfeitores se achegaram para devorar a minha carne, meus adversários e inimigos é que tropeçaram e caíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Embora um exército se acampe contra mim, meu coração não terá medo; embora declarem guerra contra mim, mesmo assim eu continuarei confiante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Uma coisa eu peço a Yahweh e isto buscarei: que eu possa viver na casa de Yahweh todos os dias da minha vida, para ver a beleza de Yahweh e meditar no Seu templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Pois no dia da tribulação, Ele me esconderá no Seu abrigo; Ele me esconderá no interior de Sua tenda. Ele me levantará sobre o alto de uma rocha!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Então, minha cabeça estará erguida acima dos inimigos que me cercam. Com alegria, oferecerei sacrifícios em Sua tenda; cantarei e louvarei a Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Ouve, Yahweh, minha voz quando a Ti clamo! Tem misericórdia de mim e responde-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Meu coração fala sobre Ti: \"Buscai a Minha presença!\" A Tua presença, Yahweh, eu buscarei!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Não escondas a Tua face de mim; não rejeites Teu servo com ira; Tu tens sido o meu ajudador; não me deixes nem me abandones, Deus da minha salvação!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Mesmo que meu pai e minha mãe me abandonem, Yahweh me acolherá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Ensina-me o Teu caminho, Yahweh! Conduze-me em um caminho plano por causa dos meus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Não me entregues aos desejos dos meus inimigos, pois testemunhas falsas têm-se levantado contra mim, respirando violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'O que teria acontecido comigo se eu não acreditasse que veria a bondade de Yahweh na terra dos viventes?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Espera por Yahweh! Sê forte e valente em teu coração! Espera por Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Salmo de Davi. A Ti clamo, Yahweh, minha rocha; não me ignores, pois, se Tu não me responderes, eu me juntarei aos que descem à sepultura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Ouve a voz da minha súplica quando eu clamo a Ti por socorro, quando eu levanto as minhas mãos em direção ao Teu santuário!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Não me arrastes com os ímpios, aqueles que praticam a iniquidade, que falam de paz com o seu próximo, mas têm ódio no coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Dá-lhes o que, por suas obras, merecem, e retribui-lhes pelos seus atos de maldade; retribui-lhes, dando a eles o que lhes é devido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Porque eles não entendem os feitos de Yahweh, nem as obras de Suas mãos, Ele os derrubará e nunca mais os reerguerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Bendito seja Yahweh porque ouviu a voz da minha súplica!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Yahweh é a minha força e o meu escudo. Nele confia o meu coração e sou socorrido. Por isso, meu coração se regozija grandemente, e eu O louvarei com cânticos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Yahweh é a força do Seu povo; Ele é o refúgio de salvação do Seu ungido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Salva o Teu povo e abençoa a Tua herança; sê Tu o pastor deles e conduze-os para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Salmo de Davi. Tributai a Yahweh, vós, filhos de Deus; tributai a Yahweh glória e poder!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Tributai a Yahweh a glória que Seu nome merece; prostrai-vos diante de Yahweh no esplendor da Sua santidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'A voz de Yahweh é ouvida sobre as águas. O Deus da glória troveja; Yahweh troveja sobre as muitas águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'A voz de Yahweh é poderosa; a voz de Yahweh é majestosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'A voz de Yahweh quebra os cedros; Yahweh despedaça os cedros do Líbano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Ele faz o Líbano saltar como bezerro e Siriom, como um novilho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'A voz de Yahweh lança labaredas de fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'A voz de Yahweh estremece o deserto; Yahweh faz tremer o deserto de Cades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'A voz de Yahweh faz os carvalhos retorcerem e despe as florestas. Todos em Seu templo dizem: \"Glória!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Yahweh assentou-Se como Rei sobre o dilúvio; Yahweh se assenta como Rei para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Yahweh dá força ao Seu povo; Yahweh abençoa o Seu povo com paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Salmo. Cântico na dedicação do Templo. Salmo de Davi. Eu Te exaltarei, Yahweh, pois me ergueste e não permitiste que meus inimigos se regozijassem sobre mim;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Yahweh, meu Deus, eu clamei a Ti por socorro e Tu me curaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Yahweh, Tu tiraste a minha alma do Sheol, Tu me mantiveste vivo para eu não descer ao túmulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Cantai louvores a Yahweh, vós que sois Seu povo fiel! Dai graças quando vos lembrardes da Sua santidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Pois Sua ira é apenas por um momento, mas Seu favor é por toda a vida. O choro vem por uma noite, mas a alegria vem pela manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Confiantemente, eu disse: \"Nunca serei abalado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Yahweh, por Teu favor, Tu me estabeleceste como uma montanha forte; mas quando escondeste a Tua face, fiquei perturbado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Clamei a Ti, Yahweh, e busquei o favor do meu Senhor!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Que vantagem há em minha morte, se eu descer para o túmulo? Será que o pó Te louvará? Declarará Tua fidelidade?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Ouve, Yahweh, e tem misericórdia de mim! Yahweh, sê meu ajudador!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Tu transformaste meu pranto em júbilo; Tu removeste minha roupa de saco e me vestiste com alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Então, agora, meu coração honrado cantará louvores a Ti e não ficará em silêncio. Yahweh, meu Deus, eu Te agradecerei para sempre!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Para o regente musical. Salmo de Davi. Em Ti, Yahweh, me refugio; nunca deixes que eu seja humilhado. Salva-me pela Tua justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Ouve-me e salva-me depressa! Seja minha rocha de refúgio, uma fortaleza para me salvar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Pois Tu és a minha rocha e a minha fortaleza; por causa do Teu nome, conduze-me e guia-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Arranca-me das armadilhas que eles prepararam para mim, pois Tu és o meu refúgio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Em Tuas mãos confio meu espírito; Tu me resgatarás, Yahweh, Deus fiel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Odeio aqueles que servem a ídolos inúteis; mas eu confio em Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Eu me alegrarei e me regozijarei na Tua fidelidade à aliança, pois Tu viste minha aflição, conheceste a angústia da minha alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Não me entregaste nas mãos do meu inimigo. Tu colocaste meus pés em um lugar amplo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Tem misericórdia de mim, Yahweh, pois estou aflito; definham de tristeza os meus olhos, a minha alma e o meu corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Pois minha vida está cansada da tristeza e meus anos, dos gemidos. Minha força falha por causa do meu pecado e meus ossos estão definhando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Por causa de todos os meus inimigos, o povo me despreza; meus vizinhos estão assustados com minha situação, e todos os que me conhecem estão horrorizados. Fogem de mim quando me veem na rua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Sou esquecido como um homem morto, do qual ninguém se lembra. Sou como um vaso quebrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Pois tenho ouvido sussurro de muitos, notícias terríveis de todos os lados, como se, juntos, tramassem contra mim. Eles planejam tirar-me a vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Mas eu confio em Ti, Yahweh, e digo: \"Tu és o meu Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Meu destino está em Tuas mãos. Resgata-me dos meus inimigos e daqueles que me perseguem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Faze Tua face brilhar sobre o Teu servo; salva-me por Teu amor leal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Não me deixes ser humilhado, Yahweh, pois eu clamo a Ti! Que os ímpios sejam humilhados. Que eles fiquem em silêncio no Sheol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Sejam silenciados os lábios mentirosos, que contra o justo falam coisas insolentes, com arrogância e desprezo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Quão grande é a Tua bondade, que tens guardado para aqueles que Te reverenciam; Tu as concedes, diante dos filhos dos homens, àqueles que em Ti se refugiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'No abrigo de Tua presença, esconde-os das tramas dos homens. Tu os proteges, em um abrigo, da violência das línguas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Bendito seja Yahweh, pois Ele mostrou Sua maravilhosa fidelidade à aliança quando eu estava na cidade sitiada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Embora tenha dito na minha pressa: \"Estou eliminado dos Teus olhos\", ainda ouviste o meu apelo por ajuda quando clamei a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Ó, amai Yahweh, todos os Seus fiéis seguidores. Yahweh protege os fiéis, mas castiga por completo os orgulhosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Sede fortes e confiantes, todos vós que esperais pela ajuda de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Salmo de Davi. Masquil. Abençoada é a pessoa cuja transgressão é perdoada, cujo pecado é coberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Abençoado é o homem que Yahweh não considera culpado e, em cujo espírito, não há engano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Enquanto permaneci em silêncio, meus ossos enfraqueciam por eu gemer o dia todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Pois, dia e noite, Tua mão pesava sobre mim; minha força foi se esgotando como no tempo seco do verão. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Então, reconheci o meu pecado diante de Ti e não mais escondi a minha iniquidade. Eu disse: \"Confessarei minhas transgressões a Yahweh\", e Tu perdoaste a culpa do meu pecado. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Portanto, todos os que são piedosos devem orar a Ti no tempo de grande aflição. Assim, quando as águas transbordarem, elas não lhes alcançarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Tu és meu esconderijo; Tu me protegerás da tribulação. Tu me cercarás com as canções de vitória. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Eu te instruirei e te ensinarei o caminho que deves seguir. Eu te instruirei com Meus olhos fixos em ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Não sejas como um cavalo ou uma mula, que não têm entendimento e somente com cabresto e freio são controlados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'O corrupto tem muitas tristezas, mas o amor leal de Yahweh cercará aqueles que Nele confiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Alegrai-vos em Yahweh, e regozijai-vos, ó justos; gritai de alegria todos os que são retos de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Regozijai-vos em Yahweh, ó justos! É apropriado aos corretos que O louvem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Louvai a Yahweh com a harpa; entoai louvores a Ele com a harpa de dez cordas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Cantai a Ele novas canções; tocai habilidosamente e cantai com júbilo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Pois a palavra de Yahweh é reta, e tudo o que Ele faz é justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Ele ama a retidão e a justiça. A terra está cheia da fidelidade de Yahweh à aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Pela palavra de Yahweh, os céus foram criados e todas as estrelas foram feitas pelo sopro de Sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Ele ajunta as águas do mar como um amontoado; Ele coloca os oceanos em depósitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Que toda a terra tema a Yahweh; que todos os habitantes do mundo O reverenciem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Pois Ele falou e tudo foi feito; Ele ordenou e tudo tomou o seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Yahweh frustra as alianças das nações; Ele anula os planos dos povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'O propósito de Yahweh permanece para sempre, os planos de Seu coração, para todas as gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Abençoada é a nação cujo Deus é Yahweh, o povo a quem Ele escolheu como Sua própria herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Yahweh olha dos céus e vê todas as pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Do lugar em que mora, Ele observa os que vivem na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Ele, que molda o coração de todos eles, observa todos os seus feitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Nenhum rei está a salvo pelo seu vasto exército; um guerreiro não é salvo por sua grande força.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'O cavalo é falsa segurança de vitória; apesar de sua grande força, ele não pode resgatá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Vede! Os olhos de Yahweh estão sobre aqueles que O temem, sobre aqueles que esperam em Seu amor leal,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'para livrar suas vidas da morte e mantê-los vivos em tempos de fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Nós esperamos por Yahweh; Ele é nossa ajuda e nosso escudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Nossos corações se regozijam Nele, pois confiamos em Seu santo nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Que Teu amor leal, Yahweh, esteja conosco, assim como colocamos nossa esperança em Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Salmo de Davi, quando ele fingiu estar louco perante Abimeleque, que o expulsou de sua presença. Eu louvarei Yahweh em todo o tempo; Seu louvor estará sempre em minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Eu louvarei Yahweh! Que os oprimidos ouçam e regozijem-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Louvai Yahweh comigo; exaltemos juntos o Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Eu busquei Yahweh e Ele me respondeu; deu-me vitória sobre todos os meus medos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Aqueles que olham para Ele ficam radiantes e suas faces não são envergonhadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Este homem oprimido clamou e Yahweh o ouviu; Ele o libertou de todas as suas angústias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'O Anjo de Yahweh acampa-se ao redor dos que O temem e os livra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Experimentai e vede que Yahweh é bom; feliz é o homem que Nele se refugia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Temei Yahweh, vós os Seus santos; nada falta aos que O temem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Aos leões jovens, às vezes, falta comida e sofrem com a fome, mas àqueles que buscam Yahweh nada de bom faltará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Vinde, filhos, escutai-me; eu ensinarei a vós o temor de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Qual homem que deseja a vida, e anseia viver muitos dias para ver o bem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Guarda a tua língua do mal e os teus lábios de proferirem engano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Afasta-te do mal e faze o bem; busca a paz e segue-a.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Os olhos de Yahweh estão sobre os justos e Seus ouvidos, atentos ao seu clamor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'A face de Yahweh está contra aqueles que praticam o mal, a fim de remover a sua memória da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Os justos clamam e Yahweh ouve, e os livra de todas as suas aflições.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Yahweh está próximo dos quebrantados de coração e salva os de espírito abatido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Muitas são as aflições do justo, mas Yahweh o livra de todas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Ele protege seus ossos; nenhum deles será quebrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'A maldade matará o corrupto; aqueles que odeiam o justo serão condenados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Yahweh redime a alma dos seus servos; dos que Nele se refugiam, nenhum será condenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Salmo de Davi. Yahweh, defende-me daqueles que contendem comigo; luta contra os que lutam contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Pega o Teu escudo pequeno e o escudo grande; levanta-Te e me ajuda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Usa Tua lança e Teu machado de batalha contra aqueles que me perseguem; dize para minha alma: \"Eu Sou tua salvação.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Que aqueles que procuram tirar-me a vida sejam envergonhados e desonrados; os que planejam machucar-me que retornem e se confundam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Que eles sejam como a palha diante do vento, enquanto o anjo de Yahweh os leva para longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Que o caminho deles seja escuro e escorregadio, enquanto o anjo de Yahweh os persegue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Sem motivo, eles estenderam sua rede para mim; eles cavaram uma cova para minha vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Que a destruição os pegue de surpresa; e a rede que eles estenderam os pegue inesperadamente; que caiam nela, para sua própria destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Mas eu me alegrarei e rejubilarei na Tua salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Todos os meus ossos dirão: \"Yahweh, quem é igual a Ti, que resgata os oprimidos dos que são mais fortes do que eles, e livra os pobres e necessitados daqueles que tentam roubá-los?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Falsas testemunhas se levantam; elas me acusam falsamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Elas me pagam o mal pelo bem, o que me deixa triste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Todavia, quando estavam doentes, eu usei roupa de saco; jejuei por eles com minha cabeça curvada sobre meu peito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Eu estive de luto como se fossem meus irmãos; eu lamentei como pela minha mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Mas, quando eu tropecei, eles se alegraram e se ajuntaram; eles se uniram contra mim, e eu fui surpreendido por eles, que me rasgaram sem parar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Sem respeito algum, zombaram de mim, rangeram raivosamente seus dentes para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Senhor, por quanto tempo contemplarás? Resgata minha alma desses ataques destrutivos; resgata minha vida dos leões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Então, eu agradecerei a Ti na grande assembleia; eu O louvarei entre muitas pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Não deixes meus inimigos enganadores se alegrarem sobre mim; não deixes que sigam em frente com seus esquemas cruéis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Pois eles não falam de paz, mas inventam palavras enganosas contra os que vivem em paz na nossa terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Eles abrem suas bocas contra mim, dizendo: \"Ah! Nossos olhos viram isso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Tu tens visto isso, Yahweh, não fiques em silêncio; Senhor, não estejas longe de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Levanta-Te e desperta para minha defesa; meu Deus e meu Senhor, defende minha causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Defende-me, Yahweh meu Deus, por Tua retidão, não deixes que se alegrem sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Não permitas que digam em seus corações: \"Ah, nós temos o que desejávamos\". Não deixes que digam: \"Nós o devoramos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Que sejam postos em vergonha e sejam confundidos os que se alegram com a minha angústia. Sejam cobertos de vergonha e desonra os que me insultam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Os que desejam minha defesa gritem de alegria e sejam contentes; que eles falem continuamente: \"Yahweh seja louvado! Ele que se regozija no bem-estar de Seu servo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Então, eu falarei da Tua justiça e Te louvarei durante todo o dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Para o regente musical. Salmo de Davi, servo de Yahweh. O pecado fala como um oráculo no coração do homem ímpio; não há temor de Deus em seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Pois consola a si mesmo, pensando que seus pecados não serão descobertos, nem odiados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Suas palavras são pecaminosas e enganadoras; ele não deseja ser sábio nem fazer o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Quando deita na sua cama, planeja caminhos para o pecado; ele segue por um caminho maligno, e não rejeita o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Teu amor leal, Yahweh, alcança os céus; Tua lealdade alcança as nuvens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Tua justiça é como as montanhas de Deus; Tua justiça é como o mais profundo mar. Yahweh, Tu conservas tanto a humanidade quanto os animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Quão precioso é o Teu amor leal, Deus! Os homens se refugiam sob a sombra das Tuas asas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Eles serão abundantemente satisfeitos com a comida da Tua casa; Tu os deixarás beber do Teu rio de delícias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Pois, Contigo, está a fonte da vida; em Tua luz, veremos a luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Prolonga o Teu amor leal a todos aqueles que Te conhecem e a Tua justiça, aos retos de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Não permitas que o pé do homem orgulhoso chegue até mim. Não permitas que a mão do ímpio me leve embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Ali caíram os malfeitores; eles estão abatidos no chão e não podem se levantar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Salmo de Davi. Não te irrites por causa dos malfeitores; não invejes os que agem injustamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Pois eles logo secarão como a grama e murcharão como as plantas verdes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Confia em Yahweh e faze o bem. Habita na terra e alimenta-te em fidelidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Então, deleita-te em Yahweh, e Ele te concederá os desejos do teu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Entrega os teus caminhos a Yahweh; confia Nele e Ele agirá em teu favor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Ele demonstrará a tua justiça como a luz do dia e a tua inocência como o meio-dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Aquieta-te perante Yahweh e espera pacientemente por Ele. Não te enfureças se alguém obtiver sucesso no que fizer, nem se alguém realizar seus planos maldosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Não te ires nem te enfureças. Não te preocupes; isso só causa problemas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Os malfeitores serão eliminados, mas os que esperam em Yahweh herdarão a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Em pouco tempo, o homem mau desaparecerá; Tu olharás para o seu lugar, mas ele terá sumido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Mas os humildes herdarão a terra, e se deleitarão em paz abundante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'O corrupto trama contra o justo e range seus dentes contra ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'O Senhor ri dele, pois vê que seu dia está chegando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Os ímpios desembainham suas espadas e preparam seus arcos para derrubar o oprimido e o necessitado, para matar os que são justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Suas espadas perfurarão seus próprios corações e seus arcos serão quebrados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Melhor é o pouco que o justo possui que a abundância de muitos corruptos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Pois os braços dos corruptos serão quebrados, mas Yahweh sustenta os justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Yahweh toma conta dos íntegros, dia após dia, e a herança deles será para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Eles não serão envergonhados quando os tempos forem ruins. Quando a fome vier, eles terão o suficiente para comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Mas os homens maus perecerão. Os inimigos de Yahweh serão como o viço dos pastos; eles serão consumidos e desaparecerão como fumaça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'O corrupto pega emprestado e não paga, mas o justo é generoso e dá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Aqueles que são abençoados por Deus herdarão a terra; aqueles que são amaldiçoados por Ele serão eliminados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'É por Yahweh que os passos de um homem são estabelecidos, o homem em cujo caminho Ele tem prazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Se ele cair, não ficará prostrado, pois Yahweh o segura pela mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Eu era jovem e agora sou velho, mas nunca vi o justo ser abandonado, nem seus filhos implorando por pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'O dia todo ele é generoso e empresta, e seus filhos serão uma bênção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Volta-te para longe do mal e faze o que é certo; então, estará seguro para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Pois Yahweh ama a justiça e não abandona seus seguidores fiéis. Eles são preservados para sempre, mas os descendentes dos ímpios serão eliminados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Os justos herdarão a terra e nela viverão para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'A boca do justo fala sabedoria e multiplica a justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'A lei de Deus está em seu coração; seus pés não escorregarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'O corrupto vigia o justo e busca matá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Yahweh não o abandonará nas mãos do perverso ou o condenará quando for julgado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Espera por Yahweh e permanece em Seu caminho, e Ele te levantará para que possuas a terra. Tu verás quando os ímpios forem eliminados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Vi um homem corrupto e terrível se espalhar como uma árvore verdejante em seu solo nativo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'mas, quando passei novamente, ele não estava lá. Eu o procurei, mas ele não pôde ser encontrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Observa o homem íntegro e presta atenção ao justo; há um futuro bom para o homem de paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Os pecadores serão totalmente destruídos; o futuro para os ímpios será eliminado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'A salvação dos justos vem de Yahweh; Ele os protege em tempos de aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Yahweh os ajuda e os resgata. Ele os resgata dos homens perversos e os salva porque se refugiam Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Salmo de Davi, para trazer à memória. Yahweh, não me repreendas em Tua ira, não me castigues em Tua fúria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Pois as Tuas flechas me perfuram e a Tua mão me pressiona.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Meu corpo todo está enfermo por causa da Tua ira; não há saúde em meus ossos por causa dos meus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Pois minhas iniquidades me afogam; elas são um fardo pesado demais para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Minhas feridas estão infectadas e cheiram mal por causa da minha insensatez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Estou curvado e humilhado; lamento constantemente o dia todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Pois meu interior está ardendo, e não há nada saudável em minha carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Estou entorpecido e completamente esmagado. Meu coração angustiado me faz gemer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Senhor, Tu entendes os anseios mais profundos do meu coração e meus gemidos não estão escondidos de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Meu coração bate depressa, minha força se vai e minha visão diminui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Meus amigos e companheiros se afastam por causa da minha condição, meus vizinhos se mantêm longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Aqueles que buscam tirar-me a vida colocam armadilhas para mim. Eles buscam me machucar; falam palavras destrutivas, dizem palavras enganosas o dia inteiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Todavia, eu sou como um surdo e não escuto nada; sou como um mudo, que não diz nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Eu sou como um homem que não ouve e que não dá resposta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Certamente espero por Ti, Yahweh; Tu responderás, Senhor meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Eu digo isto para que meus inimigos não se regozijem sobre mim. Se meu pé escorregar, eles farão coisas terríveis contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Pois estou prestes a tropeçar e estou constantemente em dor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Eu confesso minha culpa, estou ciente do meu pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Mas meus inimigos são numerosos; aqueles que me odeiam injustamente são muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Eles me pagam o bem com o mal; proferem acusações contra mim, mesmo que eu tenha buscado o que é correto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Não me abandones, Yahweh; meu Deus, não Te afastes de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Vem rapidamente me ajudar, ó Senhor, minha salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Para o regente musical, para Jedutum. Salmo de Davi. Eu decidi: \"Terei cuidado com a minha conduta para não pecar com a língua; porei mordaça em minha boca enquanto estiver na presença de um homem mau.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Mas, enquanto fiquei calado, sem dizer sequer as coisas boas, e minha dor piorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Meu coração ardia; quando pensava sobre estas coisas, ardia como fogo; então, finalmente, eu disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, '\"Yahweh, faz-me saber quando será o fim da minha vida e a extensão dos meus dias; mostra-me quão passageiro eu sou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Eis que Tu fizeste meus dias do tamanho de alguns palmos da mão; a duração da minha vida é nada diante de Ti. De fato, o homem é como um sopro. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Sim, todo homem anda como uma sombra; todos se apressam para acumular riquezas, embora não saibam quem as receberá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Agora, Senhor, pelo que estou aguardando? Tu és minha única esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Livra-me de todos os meus pecados; não faças de mim objeto de zombaria dos tolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Eu estou em silêncio, não consigo abrir a minha boca por causa do que Tu fizeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Para de me açoitar, pois estou sendo consumido com o golpe de Tua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Quando disciplinas os homens por causa do pecado, Tu consomes, como uma traça, as coisas que eles mais valorizam; sim, certamente todas as pessoas são apenas como um sopro. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Ouve a minha oração, Yahweh, e escuta o meu clamor! Ouve o meu choro! Não fiques indiferente a mim, pois sou como um estranho para Contigo, um estrangeiro, como foram todos os meus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Desvia o Teu olhar de mim, para que eu possa voltar a sorrir antes de morrer.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Para o regente musical. Salmo de Davi. Esperei com paciência por Yahweh; Ele Se inclinou para mim e ouviu o meu clamor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Tirou-me de uma horrível cova, de um lamaçal; pôs os meus pés numa rocha e fez os meus passos seguros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Ele pôs uma nova canção em minha boca para louvar o nosso Deus. Muitos verão isso e O honrarão, e confiarão em Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Abençoado é o homem que põe a sua confiança em Yahweh e que não honra os orgulhosos nem aqueles que se voltam para as mentiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Yahweh, meu Deus, muitas são as maravilhas que tens feito; os Teus pensamentos sobre nós não podem ser enumerados; se eu os declarasse e falasse sobre eles, seriam mais do que se pode contar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Não Te deleitas em sacrifícios ou ofertas, abriste os meus ouvidos; não tens exigido holocaustos nem sacrifícios pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Então, eu disse: \"Vê, aqui estou; no rolo do livro está escrito a meu respeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Meu deleite é fazer a Tua vontade, meu Deus; Tuas leis estão no meu coração\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Proclamei as boas notícias da Tua justiça na grande assembleia; Yahweh, Tu sabes que meus lábios não se detiveram de fazer isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Não ocultei a Tua justiça em meu coração; declarei a Tua fidelidade e a Tua salvação; não escondi da grande assembleia o Teu amor leal nem a Tua verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Não retires de mim Teus atos de misericórdia, Yahweh; que o Teu amor leal e a Tua verdade me preservem sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Inúmeros problemas me cercam; minhas iniquidades têm me alcançado de maneira que não consigo mais enxergar; elas são mais que os cabelos da minha cabeça, e meu coração está desanimado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Agrada-Te, Yahweh, em me resgatar; e apressa-Te em me ajudar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Que sejam completamente envergonhados e desapontados os que buscam tirar-me a vida. Recuem em desonra todos aqueles que têm prazer em me machucar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Fiquem escandalizados, por conta da sua vergonha, todos aqueles que me dizem: \"Bem feito! Bem feito!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Mas regozijem-se e alegrem-se em Ti todos aqueles que Te procuram; aqueles que amam a Tua salvação digam continuamente: \"Yahweh seja louvado!”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Sou pobre e necessitado; ainda assim, o Senhor se preocupa comigo. Tu és a minha ajuda, e Tu vens em meu resgate; não Te demores, meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Para o regente musical. Salmo de Davi. Abençoado é aquele que se preocupa com o necessitado. No dia da aflição, Yahweh o salvará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Yahweh o preservará e o manterá vivo, e ele será abençoado na terra; Yahweh não o entregará ao desejo dos seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Yahweh lhe dará suporte no leito de sofrimento; Tu farás do seu leito de doença um leito de cura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Eu disse: “Yahweh, tem misericórdia de mim! Cura-me, porque eu pequei contra Ti.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Meus inimigos falam mal de mim, dizendo: “Quando morrerá e perecerá o seu nome?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Se meu inimigo vem me ver, ele diz coisas inúteis; seu coração investiga a minha situação de calamidade e, quando vai embora, ele revela para outros a minha situação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Os que me odeiam juntam-se e cochicham a meu respeito; esperam que o mal venha sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Eles dizem: \"Uma doença horrível veio fortemente sobre ele; agora que ele está prostrado, não se levantará mais.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Na verdade, até o meu amigo mais íntimo, em quem eu confiava, que comia do meu pão, levantou seu calcanhar contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Mas Tu, Yahweh, tem misericórdia de mim e me levanta, para que eu lhes retribua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Nisto sei que Tu tens prazer em mim, que meus inimigos não triunfem sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Quanto a mim, Tu me sustentas em minha integridade e me manténs diante de Tua face para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Que Yahweh, o Deus de Israel, seja louvado de eternidade em eternidade. Amém e Amém!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Para o regente musical. Masquil dos filhos de Corá. Assim como a corça anseia por correntes de água, também tenho sede de Ti, ó Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Tenho sede de Deus, do Deus vivo. Quando virei e me apresentarei diante de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Minhas lágrimas têm sido o meu alimento dia e noite, enquanto meus inimigos estão sempre me dizendo: \"Onde está o teu Deus?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Derrama-se em pranto a minha alma, quando trago à mente as lembranças de como eu andava com a multidão, guiando o povo à casa de Deus, com vozes de alegria e louvor; uma multidão celebrando em festa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Por que estás abatida, ó minha alma? Por que estás angustiada dentro de mim? Espera em Deus, pois ainda O louvarei. Ele é a minha salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Meu Deus, minha alma está abatida dentro de mim; por isso, eu Te trago à memória nas terras do Jordão, nos três picos do Monte Hermom e no monte Mizar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Um abismo chama outro abismo ao barulho de Tuas cachoeiras; todas as Tuas ondas e vagalhões vieram sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Ainda assim, Yahweh ordenará Seu amor leal durante o dia; à noite, Sua canção estará comigo, uma oração ao Deus da minha vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Eu direi a Deus, minha Rocha: \"Por que Te esqueceste de mim? Por que ando lamentando por causa da opressão do inimigo?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Semelhante a uma espada em meus ossos é quando meus adversários me insultam, sempre a perguntar: “Onde está o teu Deus?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Por que estás abatida, ó minha alma? Por que estás angustiada dentro de mim? Espera em Deus, pois ainda O louvarei. Ele é a minha salvação e o meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Faze-me justiça, ó Deus, e defende minha causa contra uma nação perversa; livra-me dos falsos e injustos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Pois Tu és o Deus da minha fortaleza. Por que Tu me rejeitaste? Por que ando lamentando por causa da opressão do inimigo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Ó, envia Tua luz e Tua verdade; que elas me guiem; que elas me levem para o Teu santo monte e para a Tua habitação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Então, eu irei ao altar de Deus, ao Deus da minha intensa alegria; Eu Te louvarei com a harpa, ó Deus, meu Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Por que estás abatida, ó minha alma? Por que estás angustiada dentro de mim? Espera em Deus, pois ainda O louvarei. Ele é a minha salvação e o meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Para o regente musical. Salmo dos filhos de Corá. Masquil. Com nossos próprios ouvidos, ó Deus, ouvimos nossos ancestrais nos contarem sobre os feitos que Tu realizaste em seus dias, nos tempos antigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Com a Tua mão, expulsaste as nações para plantar o Teu povo; Tu afligiste povos e espalhaste nosso povo pela terra deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Pois eles não conquistaram a terra por suas espadas, nem os seus próprios braços os salvaram, mas, por Tua mão direita, pelo Teu braço e pela luz do Teu rosto, por causa do Teu amor por eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Tu és o meu Rei, ó Deus; ordena a vitória para Jacó!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Por Ti, derrubaremos nossos adversários; pelo Teu nome, pisotearemos aqueles que se levantarem contra nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Porque não confiarei no meu arco, nem a minha espada me salvará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Mas Tu nos salvaste de nossos adversários, e envergonhaste aqueles que nos odeiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Em Deus, nos gloriamos o dia todo, e daremos graças ao Teu nome para sempre. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Mas agora Tu nos rejeitaste e nos trouxeste desonra, e já não sais acompanhando nossos exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Tu nos fizeste fugir do nosso adversário; e aqueles que nos odeiam nos saqueiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Tu nos entregaste como ovelhas para serem abatidas, e nos espalhaste entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Tu vendeste o Teu povo por nada, e nem por isso Tua riqueza aumentou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Tu nos fizeste objeto de vergonha para os nossos vizinhos, desprezados e escarnecidos por aqueles que nos rodeiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Tu nos tornaste um insulto entre as nações; somos o motivo pelo qual os povos balançam a cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Minha desonra está sempre diante de mim e a vergonha cobre o meu rosto,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'por causa da voz do que zomba e insulta, por causa do inimigo e do vingador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Tudo isso nos sobreveio, ainda que não tivéssemos nos esquecido de Ti ou procedido infielmente à Tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Nosso coração não voltou atrás; nossos passos não se desviaram do Teu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Porém, Tu nos esmagaste no lugar dos chacais e nos cobriste com a sombra da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Se tivéssemos nos esquecido do nome do nosso Deus, ou estendido nossas mãos para um deus estranho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Deus não saberia disso? Pois Ele conhece os segredos do coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'De fato, por Tua causa somos entregues à morte o dia todo; somos considerados como ovelhas para o abate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Desperta! Por que dormes, Senhor? Levanta-Te, não nos rejeites para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Por que escondes a Tua face e Te esqueces da nossa aflição e da nossa opressão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Somos rebaixados até o pó; nossos corpos agarram-se à terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Levanta-Te para nos ajudar! Resgata-nos por causa do Teu amor leal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Para o regente musical; adaptado para Shoshanim. Salmo dos filhos de Corá. Masquil. Um cântico de amores. Meu coração transborda de boas palavras. Lerei em alta voz as palavras que compus acerca do Rei; minha língua é como a caneta de um habilidoso escritor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Tu és mais justo que os filhos dos homens; graça é derramada em Teus lábios. Por isso, nós sabemos que Deus Te abençoou para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Coloca Tua espada na Tua coxa, ó Poderoso, em Tua glória e majestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Em Tua majestade, cavalgas triunfantemente, por causa da Tua verdade, mansidão e justiça; Tua mão justa Te ensinará coisas formidáveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Tuas flechas estão afiadas; os povos caem diante de Ti; Tuas flechas estão nos corações dos reis inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Teu trono, ó Deus, é para sempre e sempre; um cetro de justiça é o cetro do Teu reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Tu amaste a justiça e odiaste a maldade; por isso, Deus, o Teu Deus, Te ungiu com óleo de alegria mais que a Teus companheiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Todas as Tuas peças de roupa cheiram mirra, aloés e cássia; fora dos palácios de marfim, os instrumentos de cordas têm Te alegrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'As filhas dos reis estão entre as Tuas damas de honra; à Tua mão direita está a rainha, vestida em ouro de Ofir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Ouve, filha, considera e inclina teus ouvidos; esquece-te do teu próprio povo e da casa de teu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Desta maneira o Rei desejará a tua beleza; Ele é o teu Senhor, reverencia-O.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'A filha de Tiro estará lá com um presente; os ricos dentre o povo implorarão Teu favor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'A filha real no palácio está toda esplendorosa; sua veste é trabalhada em ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Ela será conduzida ao Rei em vestidos bordados; as virgens, suas companheiras, a seguirão; serão trazidas a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Elas serão conduzidas em alegria e regozijo, e entrarão no palácio do Rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'No lugar de Teus pais, estarão Teus filhos, que Tu farás príncipes em toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Eu farei Teu nome ser lembrado em todas as gerações; por isso, os povos Te darão graças para sempre e sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Para o regente musical. Salmo dos filhos de Corá; adaptado para Alamote. Deus é o nosso refúgio e a nossa força, socorro bem presente em tempos de angústia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Por isso, não teremos medo, mesmo que a terra trema e as montanhas sejam lançadas até o coração dos mares,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'mesmo que as águas rujam e se enfureçam, e as montanhas tremam em sua fúria. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Há um rio, cujas correntes alegram a cidade de Deus, o Santo Lugar do Tabernáculo do Altíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Deus está no meio dela; não será abalada. Deus a ajudará desde o amanhecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'As nações se enfurecem e os reinos foram abalados. Ele ergueu a Sua voz e a terra se dissolveu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Yahweh dos Exércitos está conosco; o Deus de Jacó é o nosso refúgio. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Vinde e vede os atos de Yahweh, a desolação que Ele trouxe sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Ele põe fim às guerras até os confins da terra; Ele quebra o arco e corta a lança em pedaços; Ele queima as carruagens no fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Aquietai-vos e sabei que Eu sou Deus! Eu serei exaltado entre as nações; Eu serei exaltado na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Yahweh dos Exércitos está conosco; o Deus de Jacó é o nosso refúgio. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Para o regente musical. Salmo dos filhos de Corá. Batei palmas, todos os povos; exultai, celebrando a Deus com som de triunfo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Porque Yahweh, o Altíssimo, é tremendo! Ele é o grande Rei sobre toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Ele subjuga os povos a nós, e põe as nações sob nossos pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Ele escolheu para nós uma herança, a glória de Jacó, a quem Ele amou. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Deus subiu em meio às aclamações, Yahweh Se elevou ao som de trombetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Cantai louvores a Deus, cantai louvores! Cantai louvores ao nosso Rei, cantai louvores!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Porque Deus é Rei sobre toda a terra; cantai louvores com entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Deus reina sobre as nações; Deus se assenta em Seu santo trono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Os príncipes dos povos se uniram ao povo do Deus de Abraão, pois os escudos da terra pertencem a Deus. Ele é grandemente exaltado!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Cântico. Salmo dos filhos de Corá. Grande é Yahweh, e digno de ser louvado na cidade de nosso Deus, em Seu santo monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Belo em elevação, e alegria de toda a terra, é o monte Sião, sobre os lados do norte, a cidade do grande Rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Deus se fez conhecido em seus palácios, como um refúgio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Pois, vede, os reis se reuniram e juntos passaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Quando eles viram isso, ficaram maravilhados e, assombrados, fugiram apressadamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'O temor tomou conta deles; sentiram dores como as da mulher em trabalho de parto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Com o vento oriental Tu quebraste os navios de Társis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Como nós ouvimos, assim temos visto na cidade de Yahweh dos Exércitos, na cidade do nosso Deus; Deus a estabelece para sempre. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Nós meditamos em Teu amor leal, ó Deus, no meio do Teu templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Assim como é o Teu nome, Deus, também o Teu louvor se estende até os confins da terra. Tua mão direita está cheia de retidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Que o monte Sião se alegre, que as filhas de Judá se regozijem por causa dos Teus justos decretos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Andai em volta do Monte Sião, caminhai ao redor dele, contai suas torres,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'observai bem suas muralhas e notai seus palácios, para contardes à próxima geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Porque este Deus é o nosso Deus para sempre e sempre. Ele será nosso guia até a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Ouvi isto, vós, todos os povos; dai ouvidos, vós, todos os habitantes do mundo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'humildes e nobres, ricos e pobres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Minha boca falará com sabedoria, e a meditação do meu coração será com entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Inclinarei meus ouvidos a uma parábola, começarei meu enigma com a harpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Por que temerei os dias maus, quando a iniquidade me envolver até os calcanhares?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Por que temerei àqueles que confiam em suas riquezas e se vangloriam com a quantidade de seus bens?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'É certo que ninguém pode remir seu irmão ou dar a Deus resgate por ele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'pois a redenção de uma vida é custosa e ninguém pode pagar o que devemos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Ninguém pode viver para sempre, de modo que seu corpo não se deteriore,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'pois ele verá deterioração. Homens sábios morrem; o tolo e o estúpido também perecem e deixam suas riquezas para os outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Em seus pensamentos íntimos, suas famílias continuarão para sempre e os lugares onde vivem serão para todas as gerações. Eles dão seus próprios nomes às suas terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Mas, mesmo tendo riquezas, o homem não permanece vivo para sempre; ele é como as feras que perecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'O caminho deles é sua insensatez; ainda assim, os homens que os seguem aprovam o que eles dizem. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Como ovelhas, eles são destinados ao Sheol, a morte será o seu pastor; os justos terão poder sobre eles pela manhã, e seus corpos serão consumidos no Sheol, sem lugar para eles morarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Mas Deus redimirá minha vida do poder do Sheol. Ele me acolherá. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Não temas quando alguém se tornar rico, quando o poder de sua casa aumentar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'pois, quando morrer, nada levará consigo; sua glória não irá com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Ele bendisse à sua alma enquanto viveu; e homens te louvam quando vives para ti mesmo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'ele se juntará à geração de seus pais e nunca mais verão a luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Aquele que tem riqueza, mas não tem entendimento, é como as feras que perecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Salmo de Asafe. Falou o Poderoso Deus, Yahweh, e chamou toda a terra, de onde o sol nasce até onde se põe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Desde Sião, a perfeição da beleza, Deus resplandece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Nosso Deus vem e não se mantém em silêncio; adiante Dele arde um fogo devorador, e ao Seu redor há uma grande tempestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Do alto, Ele chama os céus e a terra para que Ele julgue o Seu povo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '\"Reuni Meus fiéis para Mim, aqueles que fizeram uma aliança Comigo pelo sacrifício.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Os céus declaram a Tua justiça, pois Deus mesmo é o Juiz. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, '\"Ouve, povo Meu, e eu te direi; Eu sou Deus, o teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Não te repreenderei por teus sacrifícios; os teus holocaustos estão sempre diante de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Não levarei nenhum touro de tua casa, ou bodes para fora do teu curral.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Pois todos os animais da floresta são Meus, e o gado sobre as milhares de colinas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Eu conheço todos os pássaros das montanhas, e os animais ferozes do campo são Meus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Se Eu tivesse fome, não te contaria; pois o mundo é Meu, e tudo o que nele está.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Acaso, comerei Eu da carne de touros ou beberei do sangue de bodes?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Oferece a Deus sacrifício de ações de graças, e paga teus votos ao Altíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Clama a mim nos dias de angústia. Eu te resgatarei e tu Me glorificarás.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Mas ao ímpio Deus diz: \"Por que declaras Meus estatutos e tomas Minha aliança em tua boca,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'tu que odeias a instrução e jogas Minhas palavras fora?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Quando vês um ladrão, o apoias; tomas parte entre os que cometem adultério.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Entregas tua boca ao mal, e tua língua expressa engano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Tu te assentas e falas contra teu irmão; difamas o filho de tua própria mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Enquanto tens feito essas coisas, Eu Me mantive calado; então pensavas que Eu era alguém como tu. Mas te reprovarei e trarei à tona, diante de teus olhos, tudo o que tens feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Agora considera isto, tu que te esqueces de Deus; senão, te despedaçarei e não haverá ninguém para te ajudar!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Aquele que oferece sacrifício de ações de graças Me glorifica, e para quem planeja o seu caminho do modo correto, Eu mostrarei a salvação de Deus.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Para o regente musical. Salmo de Davi, quando o profeta Natã veio até Davi, depois que este se deitou com Bate-Seba. Tem misericórdia de mim, ó Deus, por causa do Teu amor leal; por amor das Tuas muitas misericórdias, apaga as minhas transgressões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Lava-me completamente da minha iniquidade e purifica-me do meu pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Pois eu conheço as minhas transgressões, e o meu pecado está sempre diante de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Contra Ti, contra Ti somente, eu pequei e fiz o que é mau à Tua vista, de maneira que és justo quando falas, e correto quando julgas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Eis que eu nasci em iniquidade; em pecado minha mãe me concebeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Eis que Tu desejas a verdade no meu íntimo, e no coração me ensinas a sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Purifica-me com hissopo e ficarei limpo; lava-me, e eu ficarei mais branco do que a neve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Faze-me ouvir júbilo de alegria para que os ossos que Tu quebraste se regozijem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Esconde a Tua face dos meus pecados e apaga todas as minhas iniquidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Cria em mim, ó Deus, um coração puro, e renova em mim um espírito reto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Não me lances fora da Tua presença, e não retires o Teu Santo Espírito de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Restaura-me a alegria da Tua salvação, e sustém-me com um espírito disposto a obedecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Então eu ensinarei aos transgressores os Teus caminhos, e os pecadores se converterão a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Perdoa-me por derramar sangue, Deus da minha salvação, e eu aclamarei de alegria pela Tua justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Senhor, abre os meus lábios, e a minha boca proclamará o Teu louvor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Pois Tu não Te agradas de sacrifício, senão eu o daria; Tu não tens prazer em holocaustos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Os sacrifícios que agradam a Deus são um espírito quebrantado; um coração contrito e arrependido Tu não desprezarás, ó Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Faze o bem a Sião, segundo a Tua boa vontade; reconstrói os muros de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Então Tu Te alegrarás nos sacrifícios de justiça, nas ofertas queimadas e nos holocaustos; e nosso povo oferecerá novilhos em Teu altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Para o regente musical. Masquil de Davi, quando Doegue, o edomita, veio e contou a Saul, dizendo-lhe: \"Davi foi à casa de Abimeleque.\" Por que te orgulhas em criar problemas, ó homem poderoso? Pois a fidelidade de Deus à aliança nunca tem fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Tua língua planeja destruição, como uma lâmina afiada, trabalhando enganosamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Tu amas mais o mal do que o bem, o mentir, ao invés do falar retamente. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Tu amas todas as palavras devoradoras, ó língua enganosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Deus te destruirá para sempre. Ele te pegará e te arrancará para fora da tua tenda e te expulsará da terra dos viventes. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Os justos verão isso e temerão; rirão dele e dirão:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, '\"Vede! Este é o homem que não fez de Deus o seu refúgio; antes, confiou na abundância de sua própria riqueza e se fortaleceu destruindo os outros.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Mas eu sou como uma oliveira verde na casa de Deus; confiarei no amor leal de Deus, para sempre e sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Te louvarei para sempre, ó Deus, pelo que fizeste. Eu esperarei em Teu nome, porque é bom, na presença dos Teus fiéis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Para o regente musical; adaptado para Maalate. Masquil de Davi. O tolo diz em seu coração: “Não existe Deus.\" Eles são corruptos e cometem iniquidades abomináveis; não há quem faça o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Deus olha dos céus para os filhos da humanidade para ver se há algum que tenha entendimento, alguém que O busque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Todos eles se afastaram, todos se corromperam; não existe ninguém que faça o bem, nenhum deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Aqueles que cometem iniquidade não têm entendimento? Eles devoram o Meu povo como se estivessem comendo pão, e não clamam por Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Eles estavam apavorados, apesar de não haver razão para ter medo. Foi Deus quem espalhou os ossos daqueles que acamparam contra ti; essas pessoas foram envergonhadas porque Deus as rejeitou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Oh, que a salvação de Israel venha de Sião! Quando Deus trouxer de volta Seu povo do cativeiro, então Jacó se regozijará e Israel se alegrará!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Para o regente musical, com instrumentos de cordas. Masquil de Davi, quando os zifeus vieram e disseram a Saul: \"Por acaso, não está Davi escondido entre nós?\" Salva-me, ó Deus, pelo Teu nome, e julga-me pelo Teu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Ouve minha oração, ó Deus; dá ouvidos às palavras da minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Pois estrangeiros se levantaram contra mim, e homens sem piedade procuram tirar-me a vida. Eles não se importam com Deus. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Eis que Deus é o meu auxílio; Yahweh é quem me sustenta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Ele retribuirá meus inimigos com o mal; na Tua fidelidade, destrói-os.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'A Ti, voluntariamente, oferecerei sacrifícios; darei graças ao Teu nome, Yahweh, porque és bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Pois me resgataste de toda tribulação; meus olhos viram a derrota dos meus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Para o regente musical, com instrumentos de cordas. Masquil de Davi. Dá ouvidos à minha oração, ó Deus, e não Te escondas da minha súplica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Presta atenção em mim e responde-me; eu não tenho descanso dos meus problemas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'por causa da voz dos meus inimigos, por causa da opressão dos maus; pois eles me trazem problemas e, com raiva, me perseguem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Dentro do peito, meu coração se angustia, e os terrores da morte caíram sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Temor e tremor vieram sobre mim; o horror tem-me envolvido por completo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Eu disse: \"Ó, se eu tivesse asas como uma pomba, então eu voaria até encontrar repouso!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Eis que eu poderia vaguear bem distante e ficaria no deserto. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Eu me apressaria em ir para um abrigo longe do vendaval e da tempestade.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Destrói, Yahweh, e confunde a linguagem deles, pois eu tenho visto violência e contendas na cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Dia e noite eles percorrem suas muralhas; iniquidade e injúria estão dentro dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'A maldade está em seu meio; opressão e engano não deixam suas ruas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Pois não é um inimigo que me afronta, isso eu poderia suportar; nem é aquele que me odeia o que se levanta contra mim, porque dele eu teria me escondido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Mas és tu, homem igual a mim, meu companheiro e amigo íntimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Nós tínhamos uma agradável comunhão; íamos juntos à casa de Deus, com a multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Que a morte venha repentinamente sobre eles; que eles desçam vivos ao Sheol, pois a maldade está onde eles vivem, bem no meio deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Quanto a mim, eu invocarei a Deus, e Yahweh me salvará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Ao entardecer, pela manhã e ao meio-dia eu me queixarei e lamentarei, e Ele ouvirá a minha voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Ele, em segurança, resgatará a minha vida da batalha, pois são muitos os que lutam contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Deus, Aquele que governa desde a eternidade, ouvirá e lhes responderá. Interlúdio Pois eles não mudam sua conduta e não temem a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Meu amigo levantou suas mãos contra aqueles que estavam em paz com ele, não respeitando o seu acordo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Sua boca era macia como manteiga, mas seu coração era hostil; suas palavras eram mais suaves do que o azeite, mas, na verdade, eram como espadas desembainhadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Coloca teus fardos sobre Yahweh, e Ele te sustentará; Ele nunca permitirá que o justo se abale.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Mas Tu, ó Deus, trarás os perversos para a cova da destruição; os homens sanguinários e enganosos não viverão nem a metade do que os outros. Mas eu confiarei em Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Para o regente musical; adaptado para Jonate-elem-recoquim. Salmo de Davi, quando os filisteus o prenderam em Gate. Um mictam. Tem misericórdia de mim, ó Deus, pois os homens estão me atacando; aqueles que lutam contra mim me oprimem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Meus inimigos tentam me esmagar o dia todo; pois há muitos que, arrogantemente, lutam contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Mas quando eu estiver com medo, em Ti confiarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Em Deus, cuja palavra eu louvo, em Deus eu coloquei a minha confiança e não temerei; o que poderia me fazer um simples homem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'O dia todo eles distorcem minhas palavras; todos os seus pensamentos são para fazer o mal contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Reúnem-se, escondem-se, e observam os meus passos, esperando para tirar-me a vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Não deixes escapar esses que praticam iniquidade. Derruba os povos na Tua ira, ó Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Tu contaste as minhas vagueações e colocaste minhas lágrimas em Teu odre; não estão elas no Teu livro?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Meus inimigos retrocederão no dia em que eu Te invocar; isto eu sei: que Yahweh é por mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Em Deus, cuja palavra eu louvo, em Yahweh, cuja palavra eu louvo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'em Deus eu ponho a minha confiança e não temerei; o que poderia me fazer um simples homem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Tenho o dever de cumprir os votos que fiz, ó Deus; a Ti oferecerei ações de graças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Pois Tu resgataste minha vida da morte; Tu guardaste meus pés da queda, para que eu ande diante de Deus na luz dos vivos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Para o regente musical; adaptado para Al-Tachete. Salmo de Davi, quando ele fugia de Saul, na caverna. Um mictam. Tem misericórdia de mim, ó Deus, tem misericórdia de mim, pois eu me refugio em Ti até que estas tribulações se acabem. Eu permaneço sob as Tuas asas protetoras, até que essa calamidade termine.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Eu clamarei ao Deus Altíssimo, ao Deus que faz todas as coisas por mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Ele enviará ajuda do céu e me salvará; Ele está irado com aqueles que me oprimem. Interlúdio Deus enviará Sua graça e Sua fidelidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Minha vida está cercada por leões; estou entre aqueles que estão prontos para me devorar; seus dentes são como lanças e flechas, e suas línguas, como espadas afiadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Sê exaltado, ó Deus, acima dos céus; que a Tua glória permaneça sobre toda a terra!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Eles prepararam uma armadilha para os meus pés, e eu estava aflito. Eles cavaram uma cova para mim, porém, eles mesmos caíram nela! Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Meu coração está firme; Deus, meu coração está firme! Cantarei, sim, cantarei louvores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Desperta, meu coração, desperta com alaúde e harpa; eu despertarei o amanhecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Eu Te louvarei, ó Yahweh, entre os povos; cantarei louvores a Ti entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Pois a Tua misericórdia chega até os céus, e a Tua fidelidade alcança as nuvens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Sê exaltado, ó Deus, sobre os céus; que a Tua glória seja exaltada sobre toda a terra!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Para o regente musical; adaptado para Al Tachete. Salmo de Davi. Um mictam. Vós, governantes, falais com justiça? Julgais vosso povo com retidão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Não! Vós cometeis maldade em vossos corações; com as vossas mãos espalhais violência sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Os ímpios se desviam desde o ventre; eles erram o caminho desde que nasceram, falando mentiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'O veneno deles é como o veneno de cobra; eles são como a víbora surda, que tapa seus ouvidos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'para não ouvir a voz dos encantadores, não importa o quão habilidosos sejam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Quebra os dentes deles em suas bocas, ó Deus; arranca os caninos dos leões jovens, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Que eles escorram como as águas que escorrem continuamente; quando eles armarem suas flechas, que elas fiquem sem pontas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Sejam como a lesma que se derrete enquanto vai, como uma criança abortada que nunca viu a luz do sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Antes que vossas panelas sintam o calor dos espinhos, Ele os arrancará como um redemoinho de vento, tanto os espinhos verdes como os secos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'O justo se alegrará quando vir a vingança de Deus; lavará seus pés no sangue dos maus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'para que os homens digam: \"Certamente, há uma recompensa para o justo; certamente, há um Deus que julga a terra.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Para o regente musical; adaptado para Al Tachete. Salmo de Davi, quando Saul mandou que vigiassem a sua casa para matá-lo. Um mictam. Resgata-me dos meus inimigos, meu Deus; defende-me daqueles que se levantam contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Mantém-me a salvo dos que praticam a iniquidade e salva-me dos homens sanguinários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Pois eles esperam em uma emboscada para tirar-me a vida. Homens poderosos se reúnem contra mim, mas não por causa das minhas transgressões ou dos meus pecados, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Eles se preparam para me atacar, embora eu esteja sem culpa. Desperta, vê e ajuda-me!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Tu, Yahweh, Deus dos Exércitos, o Deus de Israel, levanta e pune todas as nações; não sejas misericordioso para com nenhum transgressor perverso. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Eles retornam ao entardecer, uivam como cães e andam ao redor da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Vê, eles ameaçam com suas bocas; seus lábios são como espadas, pois dizem: \"Quem pode nos escutar?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Mas Tu, Yahweh, escarneces deles. Tu zombas de todas as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Deus, minha força, eu esperarei por Ti; Tu és minha torre alta!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Meu Deus virá me encontrar com Seu amor leal; Deus me fará ver o meu desejo sobre meus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Não os mates, ou o meu povo se esquecerá. Espalha-os pelo Teu poder e faze-os cair, Yahweh, nosso escudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Pelos pecados de suas bocas e pelas palavras de seus lábios, sejam eles capturados em seu orgulho e pelas maldições e mentiras que relatam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Consome-os em ira, consome-os até que eles não mais existam; que eles saibam que Deus reina em Jacó e até os confins da terra. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Ao entardecer, eles retornam, uivando como cães e contornando a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Eles vagueiam procurando comida e, enquanto não estão satisfeitos, rosnam como cachorros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Todavia, eu cantarei sobre a Tua força, e pela manhã cantarei sobre o teu amor constante! Pois Tu tens sido minha torre alta e refúgio no dia da minha angústia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'A Ti, minha força, eu cantarei louvores, pois Deus é a minha torre alta, o Deus de amor leal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Para o regente musical; adaptado para Susã Edute. Mictam de Davi, para o ensino. Quando ele lutou contra Arã Naaraim e com Arã Zobá, e quando Joabe voltou e matou doze mil edomitas no vale do Sal. Ó Deus, Tu nos rejeitaste e rompeste nossas defesas; tens estado irado. Restaura-nos novamente!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Fizeste a terra tremer e abriste-lhe fendas; repara suas brechas, pois ela está estremecendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Tu mostraste coisas severas a Teu povo; fizeste-nos beber o vinho cambaleante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Tu deste uma bandeira para aqueles que Te honram, para ser exibida por causa da verdade. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Para que aqueles que Tu amas sejam libertos, resgata-nos com a Tua mão direita e responde-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Deus falou em Sua santidade: \"Eu Me alegrarei; dividirei Siquém e repartirei o vale de Sucote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Gileade é Meu, Manassés é Meu também; Efraim é Meu capacete, e Judá é o Meu cetro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moabe é Minha bacia de lavar; sobre Edom atirarei minha sandália; darei Meu grito de vitória sobre a Filístia.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Quem me levará à cidade fortificada? Quem me guiará a Edom?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Não foste Tu, ó Deus, que nos rejeitaste? Tu não tens ido com nosso exército para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Ajuda-nos contra o inimigo, pois o socorro do homem é inútil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Nós triunfaremos com a ajuda de Deus; Ele pisoteará nossos inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Para o regente musical, com instrumentos de cordas. Salmo de Davi. Ouve meu clamor, ó Deus, e atende à minha oração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Desde os confins da Terra eu clamo a Ti, quando meu coração está oprimido; guia-me à rocha, que é mais alta do que eu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Pois Tu tens sido meu refúgio, uma torre forte contra o inimigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Que eu habite no Teu tabernáculo para sempre, e me refugie sob o abrigo de Tuas asas. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Pois Tu, ó Deus, ouviste meus votos; me deste a herança daqueles que honram o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Tu prolongarás a vida do rei; os seus dias serão como muitas gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Ele habitará para sempre diante de Deus; que a misericórdia e a verdade o preservem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Eu cantarei louvores ao Teu nome para sempre, para que eu cumpra meus votos todos os dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Para o regente musical, à maneira de Jedutum. Salmo de Davi. Somente em Deus a minha alma espera em silêncio, pois Dele vem a minha salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Somente Ele é a minha rocha e a minha salvação; Ele é a minha fortaleza e eu não serei fortemente abalado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Até quando vós todos atacareis um homem para o derrubardes, como um muro inclinado ou uma cerca prestes a cair?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Eles só pensam em como derrubá-lo da sua posição honrosa, e amam contar mentiras; eles o bendizem com suas bocas, mas em seus corações o maldizem. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Somente em Deus a minha alma espera em silêncio, pois minha esperança está depositada Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Somente Ele é a minha rocha e a minha salvação; Ele é a minha torre alta. Não serei abalado!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Em Deus está a minha salvação e a minha honra; Deus é a minha rocha forte e o meu refúgio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Confiai Nele em todo o tempo, ó povo, derramai diante Dele o vosso coração. Deus é um refúgio para nós. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Certamente, os homens humildes são como um sopro, e os homens de alta posição, uma mentira; eles serão pesados na balança; quando pesados juntos são mais leves que um sopro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Não confieis na opressão nem no roubo. Não ponhais inutilmente vossa esperança nas riquezas, pois elas não darão frutos; não coloqueis nelas o vosso coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Uma vez Deus falou, duas vezes eu ouvi isto: o poder pertence a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Senhor, a Ti também pertence a fidelidade à aliança, porque retribuis a cada um segundo as suas ações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Salmo de Davi, quando ele estava no deserto de Judá. Deus, Tu és o meu Deus! Eu Te procuro diligentemente; minh\'alma tem sede de Ti. A minha carne anseia por Ti em uma terra seca e cansada, onde não há água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Então eu olhei para Ti no santuário, para ver Teu poder e Tua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'A Teu amor leal é melhor do que a vida; por isso, os meus lábios Te louvarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Eu Te bendirei enquanto viver; em Teu nome levantarei as minhas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'A minha alma se fartará, como de tutano e de gordura; com lábios alegres, a minha boca Te louvará,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'quando eu pensar em Ti em minha cama e meditar em Ti durante a noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Pois Tu tens sido o meu socorro, e na sombra das Tuas asas eu me alegro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Minha alma se apega a Ti; Tua mão direita me ampara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Mas aqueles que procuram destruir a minha vida cairão nas profundezas da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Eles serão entregues ao poder da espada e se tornarão comida para os chacais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Mas o rei se alegrará em Deus; todos os que juram em Seu nome se gloriarão Nele; mas a boca daqueles que falam mentiras será fechada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Para o regente musical. Salmo de Davi. Ouve, ó Deus, a voz do meu clamor; preserva a minha vida da ameaça dos meus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Esconde-me da conspiração secreta dos malfeitores, do tumulto daqueles que praticam a iniquidade;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'os quais afiam suas línguas como espadas e apontam, como flechas, palavras amargas');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'para, de lugares secretos, atirarem no inocente; eles atiram de repente, sem temor algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Encorajam-se uns aos outros num plano maligno. Juntos e secretamente, eles combinam como colocar armadilhas, dizendo: \"Quem nos verá?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Eles inventam planos pecaminosos e dizem: \"Nós terminamos um plano cuidadoso.\" Os pensamentos e o íntimo do coração dos homens são profundos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Mas Deus atirará neles uma flecha; de repente, serão feridos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Ele os fará tropeçar, pois suas línguas estão contra eles; todos os que os virem, balançarão suas cabeças, zombando deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Todo o povo temerá e declarará os feitos de Deus. Os homens sabiamente considerarão as obras que Ele tem feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'O justo se alegrará em Yahweh e Nele se refugiará; todos os retos de coração se gloriarão Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Para o regente musical. Salmo e cântico de Davi. Nosso louvor espera por Ti em Sião, ó Deus; a Ti pagaremos nossos votos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Tu que ouves a oração, a Ti todos os homens virão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'As iniquidades prevalecem contra nós; quanto às nossas transgressões, Tu as perdoarás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Feliz é o homem a quem Tu escolhes para trazê-lo para perto de Ti, para que viva em Teus átrios. Nós ficaremos satisfeitos com a bondade da Tua casa, Teu santo templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Em retidão, Tu nos responderás realizando coisas maravilhosas, Deus da nossa salvação; Tu és a esperança de todas as extremidades da terra, dos que estão distantes, do outro lado do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Tu firmaste as montanhas; Tu que estás cingido de força.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Tu que acalmas o rugido dos mares, o rugido das ondas e a comoção dos povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Aqueles que vivem nas extremidades da terra estão amedrontados com as evidências das Tuas obras; Tu trazes alegria desde o nascer do sol até o seu poente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Tu socorres a terra regando-a e enriquecendo-a abundantemente. As correntes de Deus estão cheias de água para prover de grãos as pessoas, pois assim ordenaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Tu molhas os seus sulcos abundantemente; Tu reestabeleces as valas; Tu amoleces a terra com chuva e abençoas os frutos no meio dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Tu coroas o ano com a Tua bondade. Os Teus caminhos transbordam de fartura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'As pastagens do deserto gotejam como o orvalho, e as colinas cingem-se de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'As pastagens estão cobertas de rebanhos, e os vales, cobertos de grãos; eles gritam e cantam de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Para o regente musical. Um cântico e salmo. Aclamai a Deus com alegria, toda a Terra;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Cantai a glória de Seu nome; fazei Seu louvor glorioso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Dizei a Deus: \"Quão temíveis são os Teus atos! Pela grandeza do Teu poder, Teus inimigos se submeterão a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Toda a Terra Te adorará e cantará a Ti; eles cantarão louvores ao Teu nome.\" Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Vinde e vede as obras de Deus; Como são formidáveis os Seus atos para com os filhos dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Ele tornou o mar em terra seca; Seu povo passou a pé pelo rio; ali nos regozijamos Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Ele governa para sempre por Seu poder; Seus olhos observam as nações; que os rebeldes não exaltem a si mesmos. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Bendizei a Deus, ó povos, fazei o som de Seu louvor ser ouvido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Ele nos mantém entre os vivos, e não permite que nossos pés tropecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Pois Tu, ó Deus, nos provaste; provaste-nos como a prata é provada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Tu nos trouxeste para uma armadilha; Tu colocaste um fardo severo em nossas costas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Tu fizeste pessoas cavalgarem sobre nossas cabeças; nós passamos pelo fogo e pela água, mas Tu nos trouxeste a um lugar de abundância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Eu virei para Tua casa com holocaustos; Eu pagarei meus votos a Ti,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'os quais meus lábios prometeram e minha boca falou quando eu estava em aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Eu oferecerei a Ti holocaustos de animais gordos, com o doce aroma de carneiros; eu oferecerei touros e cabras. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Vinde e escutai, todos vós que temem a Deus, e declararei o que Ele tem feito pela minha alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'A Ele clamei com minha boca e Ele foi louvado com minha língua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Se eu tivesse mantido o pecado em meu coração, o Senhor não teria me ouvido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Mas Deus realmente ouviu; Ele deu atenção à voz da minha oração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Bendito seja Deus, que não rejeitou a minha oração, nem Seu amor leal para comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Para o regente musical, com instrumentos de cordas. Salmo e cântico. Que Deus seja misericordioso e nos abençoe, e faça resplandecer a Sua face sobre nós, Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'para que todos os Teus caminhos sejam conhecidos na terra, e a Tua salvação, entre todas as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Que os povos Te louvem, ó Deus; que todos os povos Te louvem!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Oh, que as nações regozijem-se e cantem de alegria, pois Tu julgarás os povos com justiça e governarás as nações na terra. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Que os povos Te louvem, ó Deus; que todos os povos Te louvem!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Que a terra produza sua colheita, e Deus, o nosso Deus, nos abençoe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Deus nos tem abençoado, e que todos os confins da terra O honrem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Para o regente musical. Salmo e cântico de Davi. Que Deus Se levante e que Seus inimigos sejam espalhados; fujam de diante Dele aqueles que O odeiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Como a fumaça se dissipa, assim sejam eles dissipados; assim como a cera se derrete no fogo, que os perversos pereçam na presença de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Mas que os justos se alegrem; exultem diante de Deus! Que se regozijem e se alegrem!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Cantai a Deus, cantai louvores ao Seu nome. Louvai Aquele que cavalga sobre as planícies do vale do rio Jordão. Yahweh é o Seu nome; regozijai-vos diante Dele!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Um pai para os órfãos e juiz para as viúvas é Deus na Sua santa habitação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Deus coloca o solitário em família; Ele liberta os prisioneiros para a prosperidade, mas os rebeldes vivem em uma terra seca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Deus, quando Tu foste diante do Teu povo, quando marchaste pelo deserto, Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'a terra estremeceu; os céus derramaram chuva na presença de Deus, o Sinai estremeceu na presença de Deus, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Tu, ó Deus, enviaste chuva abundante; fortaleceste Tua herança quando estava enfraquecida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Teu povo habitou nela; Tu, ó Deus, deste da Tua bondade ao pobre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Yahweh deu as ordens e um grande exército as anunciou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Reis de exércitos fogem. Eles fogem e as mulheres que esperam em casa dividem os despojos: pombas cobertas com prata e suas asas, com ouro amarelo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Quando alguns de vós ficastes entre os currais, por que fizestes isso?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'O Onipotente espalhou reis ali. Foi como neve no monte Zalmom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'O monte de Deus é o monte de Basã; alta montanha é o monte de Basã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Por que olhas com inveja, tu, ó região montanhosa, para o monte em que Deus deseja habitar? Certamente, Yahweh viverá nele para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'As carruagens de Deus são incontáveis, milhares de milhares; Yahweh está entre eles no santo lugar, como no Sinai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Tu subiste às alturas; Tu levaste muitos cativos; Tu recebeste presentes dentre os homens, até daqueles que lutavam contra Ti, para habitar ali, ó Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Bendito seja Yahweh que, diariamente, carrega nossos fardos, o Deus que é a nossa salvação. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Nosso Deus é Deus que salva; Yahweh, o Senhor, é o único capaz de nos resgatar da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Certamente, Deus esmagará a cabeça de Seus inimigos, o couro cabeludo daqueles que caminham em ofensas contra Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'O Senhor disse: \"Eu trarei de volta Meus inimigos de Basã; Eu os trarei de volta das profundezas dos mares,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'para que tu os esmagues, mergulhando teus pés no sangue deles, assim como as línguas dos teus cachorros terão sua porção no sangue dos teus inimigos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Eles têm visto suas procissões, ó Deus, as procissões de meu Deus, meu Rei, para o santo lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Os cantores foram à frente, depois os instrumentistas e, no meio, as moças solteiras tocando tamborins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Bendizei a Deus nas assembleias; louvai a Yahweh, vós que sois a fonte de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Primeiro vem Benjamim, a menor das tribos, então, os líderes de Judá e suas multidões, os líderes de Zebulom e os líderes de Naftali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Teu Deus, Israel, decretou tua força; revela a nós o Teu poder, ó Deus, como revelaste nos tempos passados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Revela-nos o Teu poder do Teu templo, em Jerusalém, onde reis trazem presentes a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Grita na batalha contra as bestas selvagens nos juncos, contra os povos, aquelas multidões de touros e bezerros. Humilha-os e faze-os trazer presentes a Ti; espalha os povos que amam fazer guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Príncipes virão do Egito; a Etiópia se apressará para estender suas mãos para Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Cantai a Deus, vós reinos da terra; Interlúdio Cantai louvores a Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Àquele que cavalga no céu dos céus, que existe desde os tempos antigos; vede, Ele levanta Sua voz com poder!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Atribuí força a Deus; Sua majestade está sobre Israel e Sua força está nos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Deus, tu és temível em Teu santo lugar; o Deus de Israel, Ele dá força e poder para Seu povo. Bendito seja Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Para o regente musical; adaptado a Shoshanim. Salmo de Davi. Salva-me, ó Deus, pois as águas têm colocado minha vida em perigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Eu me afundo na lama profunda, onde não há lugar para ficar de pé; eu cheguei às águas profundas, onde as correntezas passam sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Estou cansado de tanto clamar; minha garganta está seca; meus olhos desfalecem enquanto espero por meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Aqueles que me odeiam sem razão são mais do que os cabelos da minha cabeça; aqueles que querem me eliminar, sendo meus inimigos pelos motivos errados, são poderosos; tenho que devolver o que não roubei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Deus, Tu conheces minha insensatez, e meus pecados não Te são ocultos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Que aqueles que esperam em Ti não sejam envergonhados por minha causa, Senhor, Yahweh dos Exércitos; que aqueles que Te buscam não sejam postos em desonra por minha causa, Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Por causa de Ti eu tenho suportado repreensões; a vergonha tem coberto minha face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Tornei-me um estranho para os meus irmãos, um desconhecido para os filhos da minha mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Pois o zelo de Tua casa me consome, e os insultos dos que Te insultam têm caído sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Quando eu chorei e jejuei, eles me insultaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Quando eu fiz do pano de saco a minha vestimenta, fui objeto de zombaria para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Aqueles que se assentam no portão da cidade falam de mim; eu sou uma canção para os bêbados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Mas quanto a mim, minha oração é para Ti, Yahweh. No tempo em que a aceitares, ó Deus, pela grandeza da Tua misericórdia, responde-me na fidelidade da Tua salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Tira-me da lama, não me deixes afundar; que eu seja liberto daqueles que me odeiam e resgatado das águas profundas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Que as correntezas de águas não me façam submergir, e que a profundeza não me trague; que a cova não feche sua boca sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Responde-me, Yahweh, pois boa é Tua fidelidade à Tua aliança; porque muitas são as Tuas misericórdias para mim, volta-Te para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Não escondas Tua face de Teu servo, pois estou aflito. Responde-me depressa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Aproxima-Te de mim e me redime. Por causa dos meus inimigos, resgata-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Tu conheces minha repreensão, minha vergonha e minha desonra; meus adversários estão todos diante de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'A repreensão tem partido meu coração, eu estou cheio do peso da angústia. Procurei alguém que tivesse compaixão, mas não havia ninguém; procurei por consoladores, mas não encontrei nenhum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Deram-me veneno como alimento; na minha sede, eles me deram vinagre para beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Que a mesa diante deles se torne em armadilha; quando pensarem que estão em segurança, que ela se torne uma cilada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Que seus olhos sejam escurecidos para que não possam ver; e faze com que os lombos deles tremam constantemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Derrama Tua indignação sobre eles, e que a fúria de Tua vingança os ataque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Que os lugares deles sejam desolados; que ninguém viva em suas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Pois eles perseguiram aquele que Tu feriste; eles relatam aos outros sobre a dor daqueles a quem Tu machucaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Acusa-os de terem cometido iniquidade após iniquidade; não os deixes alcançar vitória no Teu julgamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Que eles sejam apagados do Livro da Vida e não sejam inscritos junto com os justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Mas eu estou aflito e triste; que a Tua salvação, ó Deus, me leve a um lugar alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Eu louvarei o nome de Deus com uma canção e O exaltarei com ações de graças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Isso agradará Yahweh mais do que um boi ou um touro com chifres e cascos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Os mansos verão isso e ficarão alegres; vós que buscais a Deus, revivam os vossos corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Pois Yahweh ouve os necessitados e não despreza Seus prisioneiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Que o céu e a terra O louvem, os mares e tudo que neles se move.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Pois Deus salvará Sião e reconstruirá as cidades da terra de Judá; o povo viverá ali e a possuirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Os descendentes de Seus servos a herdarão; e aqueles que amam o Seu nome ali viverão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Para o regente musical. Salmo de Davi, para trazer à memória. Salva-me, ó Deus! Yahweh, vem rápido e ajuda-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Que todos os que tentam tirar-me a vida sejam envergonhados e humilhados; que eles voltem atrás, e sejam desonrados os que têm prazer na minha miséria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Que retornem por causa de sua vergonha aqueles que dizem: \"Bem feito! Bem feito!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Que todos os que Te buscam alegrem-se e sejam felizes em Ti; aqueles que amam a Tua salvação sempre digam: \"Deus seja louvado!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Todavia, eu sou pobre e necessitado; apressa-Te a mim, ó Deus; Tu és o meu socorro e o meu resgatador. Yahweh, não demores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Em Ti, Yahweh, eu me refugio; que eu nunca seja envergonhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Resgata-me e protege-me em Tua retidão; inclina Teus ouvidos para mim e salva-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Sê minha rocha de refúgio, aonde eu sempre possa ir; Tu deste uma ordem para salvar-me, pois Tu és minha rocha e minha fortaleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Resgata-me, meu Deus, das mãos dos perversos, das mãos dos homens injustos e cruéis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Pois Tu és minha esperança, Senhor Yahweh. Eu tenho confiado em Ti desde que eu era criança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Desde o ventre, tenho sido sustentado por Ti; Tu és Aquele que me tiraste do ventre de minha mãe; meu louvor será continuamente a Teu respeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Tornei-me um exemplo para muitas pessoas; Tu és meu forte refúgio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Minha boca se encherá com Teu louvor, todo o dia com Tua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Não me rejeites em minha velhice; não me abandones quando minha força falhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Pois meus inimigos estão falando sobre mim; aqueles que espreitam a minha vida estão conspirando juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, '\"Deus o desamparou”, dizem eles, “persegui-o e tomai-o, pois não há ninguém para salvá-lo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Deus, não Te afastes de mim, meu Deus, apressa-Te para ajudar-me!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Sejam envergonhados e consumidos aqueles que são hostis à minha vida; sejam cobertos com repreensão e desonra aqueles que buscam o meu mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Mas eu sempre esperarei em Ti e Te adorarei mais e mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Minha boca falará sobre Tua justiça e Tua salvação durante todo o dia, embora eu não consiga compreendê-las.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Virei com os feitos poderosos do Senhor Yahweh; farei menção da Tua justiça, somente a Tua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Deus, Tu tens me ensinado desde a minha mocidade; mesmo agora eu declaro as Tuas obras maravilhosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'De fato, agora que estou velho e de cabelos grisalhos, ó Deus, não me abandones; para que eu declare a Tua força à próxima geração, e Teu poder para todos os que estão por vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Também a Tua justiça, ó Deus, é muito elevada! Tu que tens feito grandes coisas, ó Deus, quem se compara a Ti?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Tu, que me fizeste ver muitos problemas severos, nos ressuscitarás novamente, nos trarás de volta das profundezas da Terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Que Tu aumentes minha grandeza e voltes a me confortar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Eu também Te louvarei com a harpa por Tua fidelidade, meu Deus; a Ti cantarei louvores com a harpa, ó Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Meus lábios gritarão de alegria quando eu cantar louvores a Ti, assim como a minha alma, que Tu redimiste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Minha língua também falará sobre Tua justiça por todo o dia; pois foram envergonhados e estão confusos aqueles que procuravam o meu mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Salmo de Salomão. Dá ao rei Teus justos decretos, ó Deus, e Tua justiça, ao filho do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Que ele julgue o Teu povo com retidão e os Teus pobres com justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Que as montanhas produzam paz para o povo, e as colinas produzam retidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Que ele julgue os pobres do povo, salve os filhos dos necessitados e esmague o opressor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Que eles Te honrem enquanto durar o sol e enquanto houver a lua, por todas as gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Que ele desça como a chuva sobre a erva ceifada, como o aguaceiro que rega a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Que os justos floresçam nos seus dias, e haja uma abundância de paz até que não mais exista a lua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Que ele tenha domínio de um mar a outro, do rio até as extremidades da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Que aqueles que vivem no deserto se inclinem diante dele, e seus inimigos lambam o pó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Que os reis de Társis e das ilhas paguem-lhe tributos, e os reis de Sabá e de Seba ofereçam-lhe presentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Que todos os reis se prostrem diante dele, que todas as nações o sirvam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Pois ele ajuda o necessitado, que clama, e o aflito, pois não têm quem os socorra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Ele se compadece do pobre e do necessitado, e salva a vida dos que estão em necessidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Ele resgata as suas vidas da opressão e da violência, o sangue deles é precioso aos seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Que viva o rei! Que o ouro de Sabá lhe seja dado. Que as pessoas sempre orem por ele, e Deus o abençoe em todo o dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Haja abundância de grãos na terra, no topo das montanhas, suas plantações se ondulem; que o seu fruto seja como o do Líbano, e que os habitantes das cidades floresçam como a relva no campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Que o seu nome permaneça para sempre, que seu nome continue assim como o sol; que as pessoas o abençoem e todas as nações o chamem de abençoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Bendito seja Yahweh Deus, o Deus de Israel, o único que faz maravilhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Que Seu glorioso nome seja exaltado para sempre, e toda a terra se encha com a Sua glória! Amém e amém!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'As orações de Davi, filho de Jessé, terminam aqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Salmo de Asafe. Certamente, Deus é bom para Israel, para aqueles cujo coração é puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Mas quanto a mim, meus pés quase deslizaram; meus pés quase escorregaram debaixo de mim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'porque eu tinha inveja dos arrogantes quando eu vi a prosperidade dos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Pois eles não passam por aflições nem na morte, mas são fortes e bem alimentados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Eles são livres das cargas dos outros mortais; não são afligidos como os outros homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'O orgulho os adorna como um colar em volta de seus pescoços; a violência os veste como um manto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'De tal cegueira vem o pecado; maus pensamentos passam através de seus corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Zombeteiramente, dizem coisas más; orgulhosamente, eles ameaçam com violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Com a boca falam contra os céus, e suas línguas perambulam pela terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Desta forma, o seu povo se volta para eles e bebe, abundantemente, de suas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Eles dizem: \"Como Deus sabe? Tem algum conhecimento o Altíssimo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Essas pessoas são perversas; elas estão sempre despreocupadas, tornando-se cada vez mais ricas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Certamente, foi em vão eu ter guardado meu coração e lavado minhas mãos na inocência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Pois tenho sido afligido o dia todo, e sou disciplinado a cada manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Se eu tivesse dito: \"Eu falarei essas coisas\", eu teria traído a geração dos Teus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Embora eu tentasse compreendê-las, isto era muito difícil para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Então eu entrei no santuário de Deus e entendi o destino deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Certamente, Tu os colocas em lugares escorregadios; Tu os fazes cair na ruína.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Eles se tornam uma desolação num momento, e são totalmente consumidos de pavor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Eles são como um sonho depois que se acorda; Yahweh, quando Te levantares, Tu nada pensarás sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Pois meu coração estava aflito, e eu estava profundamente ferido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Eu era estúpido e ignorante; eu era como um animal selvagem diante de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Todavia, estou sempre Contigo; Tu seguras minha mão direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Tu me guiarás com Teu conselho e, depois, me receberás em glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Quem tenho nos céus senão a Ti? Não há ninguém na terra que eu deseje senão a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Minha carne e meu coração se enfraquecem, mas Deus é a força do meu coração para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Aqueles que estão longe de Ti perecerão; Tu destruirás todos os que são infiéis a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mas quanto a mim, tudo o que eu preciso fazer é me aproximar de Deus. Eu fiz de Yahweh Deus o meu refúgio. Eu proclamarei todos os Teus feitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Masquil de Asafe. Deus, por que nos rejeitaste eternamente? Por que Tua ira queima contra as ovelhas de Teu pasto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Traz à lembrança o Teu povo, aquele que redimiste nos tempos antigos, aquele que adquiriste para ser Tua própria herança, e o monte Sião, onde Tu habitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Vem ver as ruínas completas, todo o dano que o inimigo fez no lugar santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Teus adversários rugiram no meio do lugar que Tu designaste; eles hastearam suas bandeiras de batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Eles o destruíram com machados, como se fosse uma densa floresta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Eles esmagaram e quebraram todos os entalhes de madeira; eles os quebraram com machados e martelos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'E atearam fogo em Teu santuário; eles profanaram o local onde vives, lançando-o ao chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Disseram em seus corações: \"Nós destruiremos todos eles\". E queimaram todos os Teus santuários no país.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Nós não vemos mais nenhum sinal milagroso de Deus; não há mais profetas, e ninguém dentre nós sabe quanto tempo isso vai durar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Até quando, ó Deus, o inimigo continuará a insultar-Te? O inimigo blasfemará o Teu nome para sempre?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Por que reténs a Tua mão, a Tua mão direita? Tira a Tua mão direita das Tuas vestes e os destrói.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Mas Deus tem sido meu Rei desde os tempos antigos, trazendo salvação à terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Tu dividiste o mar pela Tua força; esmagaste as cabeças dos monstros marinhos nas águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Tu esmagaste a cabeça do Leviatã e o deste como alimento para aqueles que vivem no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Abriste fontes e córregos; secaste rios perenes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'O dia é Teu, e a noite é Tua também; colocaste o sol e a lua em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Estabeleceste todos os limites da terra; Tu fizeste o verão e o inverno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Relembra-Te como o inimigo diz insultos contra Ti, Yahweh, como aquele povo tolo que blasfemou Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Não entregues a vida de Tua pomba a um animal selvagem. Não Te esqueças para sempre da vida do Teu povo oprimido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Traz à mente Tua aliança, pois as regiões escuras da terra estão cheias de violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Não deixes que o oprimido retorne envergonhado. Que o pobre e o oprimido louvem o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Levanta-Te, Deus; defende Tua própria honra; lembra-Te como os tolos Te insultam o dia todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Não Te esqueças da voz de Teu adversário ou do alvoroço dos que continuam a desafiar-Te.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Para o regente musical; adaptado para Al Tachete. Salmo de Asafe, um cântico. Damos-Te graças, ó Deus; agradecemos, pois Teu nome está perto; os homens declaram as Tuas maravilhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Quando Eu escolher o tempo determinado, julgarei com retidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Ainda que a terra e todos os que nela habitam tremam de medo, Eu sustento os pilares da terra. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Eu disse aos soberbos: “Não sejais arrogantes!” E aos perversos: “Não vos vanglorieis!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Não vos exalteis, nem faleis com arrogância.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Pois a vitória não vem do leste, nem do oeste, nem do deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Mas Deus é o Juiz; Ele humilha um e exalta outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Pois há um cálice na mão de Yahweh, com vinho espumante misturado com especiarias, e Ele o derrama. Certamente, todos os perversos da terra o beberão até a última gota.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Mas, quanto a mim, anunciarei para sempre o que fizeste, cantarei louvores ao Deus de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Ele diz: “Aniquilarei as forças do perverso, mas as forças do justo serão exaltadas.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Para o regente musical, com instrumentos de cordas. Salmo de Asafe. Um cântico. Deus tornou-Se conhecido em Judá; Seu nome é grande em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Sua tenda fica em Salém; Sua morada está em Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Ali, Ele quebrou as flechas dos arcos, o escudo, a espada e as outras armas de guerra. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Tu és mais glorioso e excelente que as montanhas de despojos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Aqueles que têm o coração valente foram saqueados; eles caíram no sono. Todos os guerreiros foram inúteis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Diante da Tua repreensão, ó Deus de Jacó, cavaleiros e cavalos adormecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Somente Tu és temido. Quem pode ficar ao Teu lado quando estás irado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Dos céus, fizeste Teu julgamento ser ouvido; a terra ficou temerosa e em silêncio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'quando Tu, ó Deus, Te levantaste para executar julgamento e para salvar todos os oprimidos da terra. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Certamente, a Tua ira contra os homens será para o Teu louvor, e, com o restante da ira, Te cingirás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Fazei votos a Yahweh, vosso Deus, e os cumpri. Que todos os que estão ao Seu redor tragam presentes, pois Ele deve ser temido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Ele retira o espírito dos príncipes; Ele é temido pelos reis da terra!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Para o regente musical, à maneira de Jedutum. Salmo de Asafe. Com minha voz, clamo a Deus; com minha voz, clamo a Deus e Ele me escuta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'No dia da minha aflição, eu busco a Yahweh; à noite, eu estendo minhas mãos para fora e elas não se cansam. Minha alma se recusa a ser consolada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Eu me lembro de Deus enquanto eu gemo; penso Nele enquanto eu desfaleço. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Tu manténs meus olhos abertos; eu estou muito perturbado para falar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Penso sobre os dias antigos, sobre tempos que já passaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Durante a noite, eu me relembro da canção que um dia cantei. Penso cuidadosamente e tento compreender o que aconteceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Yahweh me rejeitará para sempre? Ele nunca mais me mostrará Seu favor novamente?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Seu amor leal se foi para sempre? Sua promessa falhou para sempre?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Yahweh Se esqueceu de ser gracioso? Sua fúria excluiu Sua compaixão? Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Eu digo: “Este é o meu pesar: a mão direita do Altíssimo mudou para conosco.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Mas eu trarei à mente os Teus feitos, Yahweh, eu pensarei sobre Tuas maravilhosas obras da antiguidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Meditarei sobre todos os Teus feitos e refletirei neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Teu caminho, ó Deus, é santo; que deus se compara ao nosso grandioso Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Tu és o Deus que realiza maravilhas; Tu tens revelado Tua força entre os povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Pelo Teu grande poder, Tu deste vitória ao Teu povo, os descendentes de Jacó e José. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'As águas Te viram, ó Deus, as águas Te viram e tiveram medo; os abismos tremeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'As nuvens derramaram água, os céus nublados trovejaram, Tuas flechas reluziram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Tua voz de trovão foi ouvida nos ventos; os relâmpagos iluminaram o mundo; a terra tremeu e se abalou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Tua vereda passou pelo mar e Teu caminho pelas águas em ascensão, mas Tuas pegadas não foram vistas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Tu guiaste o Teu povo como um rebanho, pelas mãos de Moisés e Arão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Masquil de Asafe. Escutai meus ensinamentos, povo meu, ouvi as palavras da minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Abrirei minha boca em parábolas; contarei sobre coisas ocultas do passado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'O que ouvimos e aprendemos, o que os nossos pais nos contaram,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'não ocultaremos dos nossos descendentes. Contaremos às próximas gerações sobre os atos louváveis de Yahweh, Sua força, e as maravilhas que Ele fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Pois Ele estabeleceu os decretos da aliança em Jacó e instituiu uma lei em Israel, ordenando que os nossos antepassados a ensinassem aos seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Assim ordenou para que a geração seguinte conhecesse Seus decretos, os filhos ainda não nascidos, que também deveriam contar aos seus próprios filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Então, eles colocariam sua esperança em Deus e não se esqueceriam dos Seus feitos, mas guardariam Suas ordenanças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Eles não seriam como seus antepassados, que foi uma geração teimosa e rebelde; uma geração cujo coração não era reto, e cujo espírito não era comprometido com Deus, nem fiel a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Os filhos de Efraim estavam armados com arcos, mas retrocederam no dia da batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Eles não guardaram a aliança de Deus, e se recusaram a obedecer à Sua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Eles se esqueceram dos Seus feitos e das maravilhas que lhes havia mostrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Maravilhas que foram feitas diante dos olhos dos seus antepassados na terra do Egito, na terra de Zoã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Ele dividiu o mar e os guiou ao atravessá-lo; Ele fez as águas se levantarem como muros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Durante o dia, os guiava com uma nuvem e, durante a noite, com a luz do fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Ele partiu as rochas no deserto, e lhes deu água em abundância, suficiente para encher as profundezas do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Ele fez ribeiros fluírem da pedra e fez a água fluir como rios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Ainda assim, continuaram a pecar contra Ele, rebelando-se contra o Altíssimo no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Eles desafiaram a Deus em seus corações ao pedirem comida para satisfazerem sua vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Eles falaram contra Deus: \"Poderia Deus, realmente, preparar uma mesa para nós no deserto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Sabemos que, quando Ele bateu na pedra, águas brotaram e ribeiros fluíram, mas poderá Ele também dar-nos pão? Proverá carne para Seu povo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Quando Yahweh ouviu isso, irou-Se; então, Seu fogo ardeu contra Jacó e Sua ira atacou Israel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'pois eles não acreditaram em Deus e não confiaram em Sua salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Então, Ele ordenou aos altos céus e abriu as suas portas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'Ele fez chover maná para que comessem, e deu-lhes os grãos do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'O povo comeu o pão dos anjos. Ele lhes enviou comida em abundância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Fez com que o vento do leste soprasse no céu e, por Seu poder, guiou o vento sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Fez chover carne sobre eles como pó, pássaros tão numerosos quanto a areia do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Estes caíram no meio do acampamento, ao redor das tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Então, comeram até se fartarem, pois Ele lhes deu o que haviam desejado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Mas, antes que eles estivessem satisfeitos, quando a comida ainda estava em suas bocas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'a ira de Deus os atacou e matou seus mais fortes. Ele derrubou os jovens de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Apesar disso, eles continuaram a pecar e não acreditaram em Seus feitos maravilhosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Por isso, Deus encurtou os seus dias; seus anos foram cheios de terror.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Sempre que Deus os afligia, eles começavam a buscá-Lo, e voltavam e, fervorosamente, O buscavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Eles lembravam que Deus era a sua Rocha e que o Altíssimo era o seu Resgatador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Eles O bajulavam com suas bocas, mas Lhe mentiam com suas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Pois seus corações não eram plenamente sinceros com Ele, e eles não eram fiéis à Sua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Mesmo assim, Deus, sendo misericordioso, perdoou suas iniquidades e não os destruiu. Sim, muitas vezes, Ele reteve Sua ira e não acendeu todo o Seu furor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Lembrou-se de que eles foram feitos de carne, como um vento que passa e não retorna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Quantas vezes se rebelaram contra Ele no deserto e O entristeceram nas regiões infrutíferas!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Repetidamente, eles desafiaram a Deus e ofenderam o Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Não pensaram no Seu poder, nem como Ele os resgatou do inimigo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'quando mostrou Seus terríveis sinais no Egito e Suas maravilhas na região de Zoã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Ele transformou os rios dos egípcios em sangue, para que eles não bebessem de suas correntes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Enviou enxames de moscas para devorá-los, e sapos que assolaram suas terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Deu suas colheitas às larvas e seu trabalho, aos gafanhotos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Ele destruiu suas vinhas com granizo e seus sicômoros com mais granizo ainda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Entregou seu gado ao granizo e seus rebanhos aos raios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'O ardor da Sua ira queimou contra eles, enviando Seu furor, Sua fúria e Sua aflição como agentes que traziam desastre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Ele abriu caminho para Sua ira; não os poupou da morte, mas os entregou à praga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Matou todos os primogênitos do Egito, o primogênito de suas forças nas tendas de Cam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Conduziu Seu próprio povo para fora como ovelhas e os guiou através do deserto, como a um rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Conduziu Seu povo, com segurança e sem temor, e o mar cobriu seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Então, os trouxe para as fronteiras da Sua terra santa, até o monte que Sua mão direita adquiriu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Expulsou as nações de diante deles e deu sua herança, estabelecendo as tribos de Israel em suas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Ainda assim, eles contestaram e desafiaram o Altíssimo Deus e não mantiveram Suas promessas solenes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Foram infiéis e agiram traiçoeiramente como seus pais; eram tão incertos quanto um arco defeituoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Eles O irritaram com seus altares pagãos e provocaram Sua ira com seus ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Quando Deus ouviu isso, irou-se, e rejeitou completamente Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Ele abandonou o tabernáculo de Siló, a tenda onde havia vivido entre o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Ele permitiu que Sua Arca fosse capturada e entregou Sua glória na mão do inimigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Entregou Seu povo à espada, e enfureceu-se contra Seus herdeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Fogo devorou seus jovens, e suas jovens não tiveram canto nupcial.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Seus sacerdotes caíram à espada, e suas viúvas não puderam chorar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Então, Yahweh acordou como se dormisse, como um guerreiro que grita por causa de vinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Ele expulsou Seus adversários e os entregou à vergonha eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Rejeitou a tenda de José, e não escolheu a tribo de Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Escolheu a tribo de Judá e o Monte Sião, que Ele amava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Ele edificou Seu santuário como os céus, como a terra que Ele estabeleceu para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Escolheu Davi, Seu servo, e o tomou do pastoreio de ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Tirou-o do trabalho com as ovelhas e seus filhotes, e o trouxe para ser pastor de Jacó, Seu povo, e de Israel, Sua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Davi os pastoreou com a integridade de seu coração e os guiou com a habilidade de suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Salmo de Asafe. Ó Deus, nações estrangeiras invadiram Tua herança; eles contaminaram Teu santo templo e transformaram Jerusalém em um monte de ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Eles deram os cadáveres dos Teus servos como alimento às aves do céu, os corpos de Teu povo fiel, às bestas da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Eles derramaram o sangue dos cadáveres como água, em torno de Jerusalém, e não havia ninguém para os enterrar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Nós nos tornamos motivo de repreensão para nossos vizinhos, motivo de zombaria e escárnio daqueles que nos cercam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Por quanto tempo, Yahweh? Tu ficarás irado para sempre? Por quanto tempo, arderá o Teu ciúme como fogo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Derrama Tua ira sobre as nações que não Te conhecem e sobre os reinos que não invocam o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Pois eles devoraram Jacó e destruíram suas vilas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Não cobres de nós os pecados dos nossos antepassados; que Teus atos misericordiosos venham a nós, pois estamos muito desanimados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Ajuda-nos, Deus da nossa salvação, por causa da glória do Teu nome; salva-nos e perdoa nossos pecados por amor do Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Por que as nações diriam: “Onde está o Deus deles?”. Que o sangue derramado de Teus servos seja vingado nas nações, diante dos nossos olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Que os lamentos dos prisioneiros venham diante de Ti; com a grandeza de Teu poder, preservas os condenados à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Retribui às nossas nações vizinhas sete vezes o insulto que fizeram a Ti, Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Então, nós, o Teu povo e Tuas ovelhas do Teu pasto, Te daremos graças para sempre. Nós contaremos os Teus louvores a todas as gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Para o regente musical; adaptado para o estilo Shoshanim Edut. Salmo de Asafe. Escuta, ó Pastor de Israel, Tu, que, como um rebanho, guias José; Tu, que assentas acima dos querubins, brilha sobre nós!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Perante Efraim, Benjamim e Manassés, desperta o Teu poder, vem e salva-nos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Ó Deus, restaura-nos; brilha a Tua face sobre nós, e seremos salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Yahweh, Deus dos Exércitos, até quando ficarás zangado com as orações do Teu povo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Tu os alimentaste com pão de lágrimas e deste-lhes grande quantidade de lágrimas para beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Tu nos colocaste por objeto de disputa para os nossos vizinhos, e nossos inimigos caçoam de nós entre si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Deus dos Exércitos, restaura-nos; brilha a Tua face sobre nós, e seremos salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Trouxeste uma videira do Egito; Tu expulsaste as nações e a plantaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Limpaste a terra para ela, que lançou raízes e encheu a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'As montanhas foram cobertas com a sua sombra e os cedros de Deus, com os seus galhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Ela estendeu seus galhos até o mar e seus ramos até o rio Eufrates.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Por que derrubaste seus muros para que todos os que passam colham suas uvas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'O javali da floresta as destrói, e os animais selvagens do campo alimentam-se delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Volta-Te, ó Deus dos Exércitos; olha do céu abaixo, vê e cuida dessa videira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Esta é a raiz que a Tua mão direita plantou, o broto que fizeste crescer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Ela está queimada e cortada; que todos os Teus inimigos pereçam, por causa da Tua repreensão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Que a Tua mão esteja sobre o homem que está à Tua direta, sobre o filho do homem que fortaleceste para Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Então, não nos afastaremos de Ti; vivifica-nos, e invocaremos o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Restaura-nos, Yahweh, Deus dos Exércitos; faze a Tua face brilhar sobre nós, e seremos salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Para o regente musical; adapatado ao estilo Gitite. Salmo de Asafe. Cantai, em voz alta, a Deus, nossa força; aclamai de alegria ao Deus de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Cantai uma canção e tocai o tamborim, a lira prazerosa e a harpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Tocai a trombeta no dia da lua nova e no dia da lua cheia, quando nossos dias de festa começarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Pois é um estatuto para Israel, um decreto dado pelo Deus de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Ele ordenou como uma regra a José, quando foi contra a terra do Egito, onde ouvi uma língua que não conhecia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, '\"Eu removi o fardo do seu ombro; suas mãos foram libertas dos cestos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Na tua aflição, clamaste e Eu te ajudei; Eu te respondi de uma nuvem escura de trovão. Eu te provei nas águas de Meribá. Interlúdio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Escuta, Meu povo, pois Eu estou te advertindo, ó Israel. Se apenas me ouvisses!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Não tenhas deuses estranhos no meio de ti; não adores nenhum deus estrangeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Eu sou Yahweh, teu Deus, que te trouxe da terra do Egito. Abre a tua boca e Eu a encherei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Mas Meu povo não ouviu as Minhas palavras; Israel não Me obedeceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Então, Eu os entreguei à sua própria teimosia, para fazerem o que lhes parecesse certo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Ó, se Meu povo Me escutasse! Ó, se Meu povo andasse em Meus caminhos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Então, Eu rapidamente subjugaria seus inimigos e viraria Minha mão contra seus opressores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Que aqueles que odeiam Yahweh se encolham de medo diante Dele! Que eles sejam humilhados para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Eu alimentaria Israel com o melhor do trigo; Eu te satisfaria com o mel da rocha”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Salmo de Asafe. Deus põe-Se de pé na divina assembleia; no meio dos deuses, Ele profere o julgamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Até quando vós julgareis injustamente e mostrareis favoritismo aos ímpios? Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Defendei os pobres e os órfãos; garanti os direitos dos aflitos e dos desamparados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Resgatai o pobre e o necessitado; tirai-os da terra dos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Eles não sabem, nem entendem; eles vagueiam na escuridão; todas as fundações da terra sucumbem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Eu disse: \"Vós sois deuses e todos vós sois filhos do Altíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'No entanto, morrerão como homens e cairão como qualquer um dos príncipes.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Levanta-Te, ó Deus, julga a terra, pois Tu tens uma herança em todas as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Salmo de Asafe. Um cântico. Deus, não fiques em silêncio! Não nos ignores, nem Te mantenhas imóvel, ó Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Vê, Teus inimigos estão fazendo um tumulto e aqueles que Te odeiam levantaram suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Eles conspiram contra o Teu povo e, juntos, planejam contra os protegidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Eles disseram: \"Vinde, vamos destruí-los como nação. Então, o nome de Israel não será mais lembrado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Juntos, eles tramaram uma estratégia e fizeram uma aliança contra Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Isso inclui as tendas de Edom e os ismaelitas, o povo de Moabe e os hagarenos, que tramam juntos a');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Gebal, Amom, Amaleque; isso também inclui a Filístia e os habitantes de Tiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Assíria também está aliada a eles; estão ajudando os descendentes de Ló. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Faze a eles como fizeste a Midiã; como fizeste a Sísera e a Jabim no rio Quisom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Eles pereceram em En-Dor e se tornaram esterco para a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Faze a seus nobres como a Orebe e a Zeebe, e a todos os seus príncipes, como a Zebá e a Zalmuna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Eles disseram: \"Deixai-nos tomar as pastagens de Deus.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Meu Deus, torna-os como o redemoinho, como palha ante o vento,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'como o fogo que queima a floresta e como a chama que incendeia as montanhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Persegue-os com o Teu vento forte, e apavora-os com a Tua tempestade de vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Cobre seus rostos com vergonha para que busquem Teu nome, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Que sejam envergonhados e aterrorizados para sempre; que pereçam em desgraça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Então, saberão que somente Tu, Yahweh, és o Altíssimo sobre toda a terra!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Para o regente musical; adaptado ao estilo Gitite. Salmo dos filhos de Corá. Quão amável é o lugar da Tua habitação, Yahweh dos Exércitos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Minha alma anseia e desfalece pelos átrios de Yahweh; meu coração e todo o meu ser clamam pelo Deus vivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Até o pardal achou casa, e a andorinha, ninho para si, onde possa abrigar seus filhotes; eu encontrei Teus altares, Yahweh dos Exércitos, meu Rei e meu Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Abençoados são aqueles que vivem em Tua casa; aqueles que Te louvam continuamente. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Abençoado é o homem cuja força está em Ti, em cujo coração, estão os caminhos retos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Passando pelo vale de Baca, eles encontram fontes de água para beber, como as primeiras chuvas fazem ao transbordar as cisternas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Eles caminham com vigor crescente, até que cada um se apresente a Deus em Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Yahweh, Deus dos Exércitos, ouve minha oração; escuta o que estou dizendo, Deus de Jacó! Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Ó Deus, nosso escudo, mostra preocupação pelo Teu ungido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Pois mais vale um dia em Teus átrios que mil em outro lugar. Eu prefiro ficar à porta da casa do meu Deus a viver nas tendas dos ímpios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Pois Yahweh Deus é sol e escudo; Yahweh dá graça e honra; Ele não recusa nenhum bem àqueles que caminham em integridade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Yahweh dos Exércitos, abençoado é o homem que em Ti confia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Ao regente musical. Salmo dos filhos de Corá. Yahweh, Tu mostraste favor à Tua terra; restauraste o bem-estar de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Perdoaste a iniquidade do Teu povo; cobriste todos os seus pecados. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Retiraste toda a Tua ira; desviaste o Teu furor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Restaura-nos, Deus da nossa salvação, e retira de nós a Tua ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Ficarás irado conosco para sempre? Permanecerás irado através das gerações futuras?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Não nos vivificará novamente? Então, o Teu povo se regozijará em Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Mostra-nos a Tua fidelidade, Yahweh, concede-nos a Tua salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Eu ouvirei o que Deus Yahweh diz, porque Ele fará as pazes com o Seu povo, Seus fiéis seguidores. No entanto, eles não devem voltar aos caminhos insensatos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Certamente, Sua salvação está próxima dos que O temem; então, a glória permanecerá em nossa terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'A fidelidade e a verdade se encontraram; a justiça e a paz se beijaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'A verdade brotará do chão e a justiça olhará desde o céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Sim, Yahweh dará Suas boas dádivas e nossa terra produzirá seus frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'A justiça irá adiante Dele e fará um caminho para as Suas pegadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Oração de Davi. Escuta, Yahweh, e me responda, pois eu sou pobre e oprimido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Proteja-me, pois eu sou fiel; meu Deus, salva Teu servo que confia em Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Seja misericordioso comigo, Senhor, pois a Ti eu clamo o dia todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Alegra o teu servo, pois a Ti, Senhor, eu oro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Senhor, Tu és bom. Pronto a perdoar, mostras grande benignidade para com todos os que Te invocam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Yahweh, escuta minha oração e atende à voz das minhas súplicas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'No dia da minha angústia, eu clamarei a Ti e Tu me responderás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Não há ninguém entre os deuses que se compare a Ti, Senhor; Não há obras como as Tuas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Todas as nações que criastes virão e se prostrarão diante de Ti, Senhor, e honrarão o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Pois Tu és grande e Teus feitos são maravilhosos; somente Tu és Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Ensina-me, Yahweh, os Teus caminhos e, então, eu andarei na Tua verdade. Prepara meu coração para temer o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Senhor, meu Deus, eu Te louvarei com todo o meu coração e glorificarei Teu nome para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Pois grande é a Tua fidelidade para comigo; Tu resgataste minha vida das profundezas do Sheol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Deus, o arrogante se levantou contra mim. Muitos homens violentos atentam contra a minha vida. Eles não respeitam a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Mas Tu, Senhor, és um Deus misericordioso e gracioso, tardio para irar-Te e abundante em fidelidade e verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Volta-Te para mim e tenha misericórdia de mim; dá forças ao Teu servo; salva o filho de Tua serva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Mostra-me um sinal do Teu favor. Então, aqueles que me odeiam verão e se envergonharão, pois Tu, Yahweh, tens me ajudado e me confortado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Cântico. Salmo dos filhos de Corá. Sobre o monte santo fica a cidade por Ele fundada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Yahweh ama os portões de Sião mais do que todas as tendas de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Coisas gloriosas são ditas sobre Ti, cidade de Deus. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Mencionei Raabe e Babilônia aos meus seguidores. Vê, eis a Filístia e Tiro, juntamente com a Etiópia – e direi: \"Este aqui nasceu lá.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'De Sião será dito: \"Cada um destes nasceu nela; e o próprio Altíssimo a estabelecerá.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Yahweh escreve no livro de registro das nações: \"Este, nasceu lá.\" Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Então, tanto os cantores quanto os dançarinos dizem: \"Todas as minhas fontes estão em Ti.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Cântico: Salmo dos filhos de Corá; ao regente musical, adaptado para Maalate Leanote. Masquil de Hemã, o ezraíta. Yahweh, Deus da minha salvação, eu clamo dia e noite diante de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Escuta a minha oração, ouve o meu choro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Estou cheio de aflições e minha vida atingiu o Sheol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'As pessoas me tratam como aquele que vai para a cova; eu sou um homem sem forças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Estou abandonado entre os mortos; sou como os mortos deitados no túmulo, sobre quem não Te importas mais, porque eles estão afastados do Teu cuidado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Colocaste-me no fundo da cova, no escuro e nas profundezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Tua ira repousa pesada sobre mim e todas as Tuas ondas se quebram sobre mim. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Por causa de Ti, meus conhecidos me evitam. Tu me fizeste uma abominação para eles. Estou cercado e não posso escapar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Meus olhos estão enfraquecidos por causa das minhas aflições; o dia todo eu clamo a Ti, Yahweh. Eu ergo minhas mãos a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Farás maravilhas pelos mortos? Os que já morreram se levantarão e adorarão a Ti? Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Será a Tua fidelidade proclamada na sepultura e a Tua lealdade, no lugar dos mortos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Será que as Tuas maravilhas serão conhecidas na escuridão, ou a Tua retidão no lugar de esquecimento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Mas eu clamo a Ti, Yahweh; pela manhã, minha oração chega perante Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Yahweh, por que me rejeitas? Por que escondes Tua face de mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Desde a minha juventude, eu sempre estive afligido e à beira da morte. Sofri sob Teus horrores; eu estou desesperado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'A Tua ira veio sobre mim e os Teus terrores me aniquilaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Rodeiam-me como água o dia todo; todos têm-me cercado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Tiraste de mim todo amigo e conhecido. Minha única conhecida é a escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Masquil de Etã, o ezraíta. Eu cantarei para sempre as bondades de Yahweh. Proclamarei Sua verdade às futuras gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Pois, disse eu: \"A fidelidade foi estabelecida para sempre; Tu estabeleceste a Tua verdade nos céus.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, '\"Fiz uma aliança com o Meu escolhido, fiz um juramento ao Meu servo Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Estabelecerei seus descendentes para sempre e firmarei seu trono por todas as gerações.\" Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Os céus louvam as Tuas maravilhas, Yahweh; aTua verdade é louvada na assembleia dos santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Quem nos céus se compara a Yahweh? Quem entre os seres celestiais é como Yahweh?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Ele é um Deus grandemente honrado no conselho dos santos e temido entre todos os que O cercam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Yahweh Deus dos Exércitos, quem é poderoso como Tu, Yahweh? A Tua verdade Te envolve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Tu governas o mar revolto; quando as ondas se levantam, Tu as acalmas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Tu esmagaste Raabe como alguém que foi morto. Dispersaste os Teus inimigos com Teu braço forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Os céus e a terra pertencem a Ti. Tu fizeste o mundo e tudo o que nele há.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Tu criaste o norte e o sul. Tabor e Hermom regozijam-se no Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Tens um braço poderoso e uma mão forte, e a Tua destra é exaltada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Retidão e justiça são os fundamentos do Teu trono. A fidelidade e a verdade vêm diante de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Felizes os que Te adoram! Yahweh, eles andam na luz da Tua face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Eles se regozijam no Teu nome durante todo o dia, e Te exaltam na Tua justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Tu és a sua força majestosa e pelo Teu favor eles são vitoriosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Pois o nosso escudo pertence a Yahweh; ao Santo de Israel pertence o nosso rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Há muito tempo atrás, falaste em visão aos Teus fiéis; dizendo: \"Coloquei uma coroa sobre alguém poderoso; levantei um escolhido entre o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Escolhi Meu servo Davi, e com Meu santo óleo o ungi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Minha mão o sustentará; Meu braço o fortalecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Nenhum inimigo o enganará; nenhum filho da impiedade o oprimirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Esmagarei os inimigos dele na sua presença; matarei todos aqueles que o odiarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Minha verdade e minha fidelidade estarão com ele; pelo Meu nome, ele será vencedor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Colocarei a sua mão sobre o mar e a sua mão direita sobre os rios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Ele Me chamará: \'Tu és meu Pai, meu Deus e a rocha da minha salvação.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Também o colocarei como Meu primogênito, o mais exaltado dos reis da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Estenderei Minha fidelidade para com ele para sempre; e Minha aliança permanecerá segura com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Farei seus descendentes subsistirem para sempre, e seu trono durará assim como os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Se seus filhos abandonarem a Minha lei e desobedecerem aos Meus decretos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'se eles quebrarem Minhas regras e desobedecerem às Minhas ordens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'então, punirei sua rebelião com vara e suas iniquidades com açoites.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Mas não removerei dele o Meu amor, nem serei infiel à Minha promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Não quebrarei Minha aliança ou mudarei as palavras dos Meus lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Jurei uma vez por todas pela Minha santidade — Eu não mentirei a Davi —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'seus descendentes continuarão para sempre em seu trono, assim como o sol perante Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Ele será estabelecido para sempre, assim como a lua, testemunha fiel no céu.\" Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Mas Tu o recusaste e o rejeitaste; e Te iraste contra o Teu rei ungido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Renunciaste à aliança do Teu servo. Profanaste a sua coroa e a jogaste no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Derrubaste todas as suas paredes e arruinaste suas fortalezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Todos que passaram o roubaram. Ele se tornou um objeto de escárnio para seus vizinhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Exaltaste a mão direita dos seus inimigos; fizeste todos os seus inimigos se alegrarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Voltaste o fio da sua espada, e não o sustentaste na batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Levaste seu esplendor ao fim; derrubaste seu trono no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Abreviaste os dias da sua juventude e o cobriste com vergonha. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Até quando, Yahweh? Tu Te esconderás para sempre? Até quando a Tua ira queimará como fogo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Oh, pensa quão curto é o meu tempo e como criaste em vão todos os filhos dos homens!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Quem pode viver e não morrer, ou resgatar sua própria vida do poder do Sheol? Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Senhor, onde estão os Teus antigos atos de fidelidade que juraste a Davi?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Lembra-Te, ó Senhor, das afrontas feitas contra Teu servo e como eu suportei em meu coração os muitos insultos das nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Teus inimigos insultaram, Yahweh, e zombaram do Teu ungido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Bendito seja Yahweh para sempre. Amém e amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Oração de Moisés, o homem de Deus. Senhor, Tu tens sido o nosso refúgio por todas as gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Antes das montanhas serem formadas, ou antes de formaste a terra e o mundo, de eternidade a eternidade, Tu és Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Tu fazes o homem retornar ao pó, e dizes: \"Voltai, vós, filhos dos homens.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Pois, para Ti, mil anos são como o dia de ontem que passou, e como uma vigília da noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Tu os varres como uma inundação e eles adormecem; pela manhã, eles são como a grama que brota.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Pela manhã, ela brota e cresce; à tarde, ela murcha e seca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Na verdade, somos consumidos pela Tua ira, e na Tua fúria ficamos aterrorizados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Tu colocaste nossas iniquidades diante de Ti; nossos ocultos pecados, na luz da Tua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Nossa vida passa sob a Tua fúria; nossos anos se vão rapidamente, como um suspiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Nossos anos chegam a setenta ou, se formos saudáveis, a oitenta, mas até mesmo nossos melhores anos são marcados por aflições e tristeza. Sim, eles passam rapidamente e nós voamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Quem conhece a intensidade da Tua ira e a Tua fúria, conforme o temor que ela incita?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Então, ensina-nos a considerar nossa vida, de modo que vivamos sabiamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Volta-te, Yahweh! Até quando? Tem compaixão dos Teus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Pela manhã, satisfaz-nos com Tua fidelidade para que nos regozijemos e nos alegremos todos os nossos dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Alegra-nos pelos dias que nos afligiste e pelos anos em que sofremos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Que os Teus servos vejam o Teu trabalho e que as nossas crianças vejam a Tua majestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Que a graça do Senhor, nosso Deus, seja sobre nós e faça prosperar o trabalho de nossas mãos; sim, que faça prosperar a obra das nossas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Aquele que habita no abrigo do Altíssimo descansará à sombra do Onipotente, e');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'dirá de Yahweh: \"Ele é meu refúgio e minha fortaleza, meu Deus, em Quem confio.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Pois Ele te resgatará do laço do caçador e da praga mortal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Ele te protegerá com Suas penas e, sob Suas asas, encontrarás refúgio. Sua verdade é um escudo e proteção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Tu não temerás o terror da noite ou a flecha lançada de dia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'nem a praga que se alastra na escuridão ou a doença que vem ao meio-dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Ainda que milhares caiam ao teu lado e dezenas de milhares, à tua direita, tu não serás atingido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Tu apenas observarás e verás a recompensa dos ímpios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Pois disseste: \"Yahweh é meu refúgio\", e fizeste do Altíssimo a tua habitação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Nenhum mal te sucederá, nem praga alguma chegará à tua tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Pois Ele dará ordem a Seus anjos para te protegerem e guardarem em todos os teus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Eles te sustentarão com suas mãos para que não tropeces em alguma pedra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Esmagarás leões e víboras debaixo de teus pés; pisotearás leões jovens e serpentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Porque a Mim se apegou com amor, Eu o livrarei. Eu o protegerei porque ele é leal a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Quando ele Me invocar, eu lhe responderei. Estarei com ele nas tribulações; Eu lhe darei vitória e o honrarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Eu o satisfarei com vida longa e lhe mostrarei a Minha salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Salmo. Cântico para o dia de sábado. É bom render graças a Yahweh e cantar louvores ao Teu nome, ó Altíssimo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'E proclamar pela manhã o teu amor leal e, todas as noites, a Tua fidelidade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'com uma harpa de dez cordas e com a melodia da lira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Pois Tu, Yahweh, me alegraste com Teus atos. Exultarei pelas obras das Tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Como são grandes os Teus atos, Yahweh! Teus pensamentos são muito profundos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Uma pessoa violenta não percebe, nem mesmo um tolo entende isto:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'o perverso que cresce como a erva, e mesmo todos os malfeitores que prosperam, estão condenados à destruição eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Mas Tu, Yahweh, reinarás para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'De fato, olha para Teus inimigos, Yahweh! De fato, olha para Teus inimigos. Eles perecerão! Todos os que praticam a iniquidade serão dispersos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Tu tens aumentado o meu poder, como o poder do boi selvagem; fui ungido com óleo fresco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Meus ouvidos têm ouvido e meus olhos têm visto a queda e a destruição de meus cruéis inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'O justo florescerá como a palmeira e crescerá como um cedro do Líbano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Eles estão plantados na casa de Yahweh e florescerão nos átrios do nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Eles produzirão frutos mesmo quando idosos; permanecerão viçosos e vigorosos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'para proclamarem que Yahweh é justo. Ele é a minha rocha e não há injustiça Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Yahweh reina; Ele está vestido de majestade. Yahweh está vestido de força; Ele está cingido de poder. O mundo está firmemente estabelecido; não pode ser abalado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Teu trono está estabelecido desde tempos antigos; Tu és desde a eternidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Os oceanos se levantam, Yahweh; eles levantaram sua voz; suas ondas batem e rugem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Acima do ruído de muitas ondas, mais poderoso que as rebentações do mar, mais poderoso é Yahweh nas alturas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Teus solenes comandos são extremamente fiéis; a santidade ornamenta Tua Casa, Yahweh, para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Yahweh, Deus que vinga, brilha sobre nós, Deus que vinga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Levanta-te, juiz da terra! Dá aos orgulhosos o que eles merecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Até quando os ímpios, Yahweh, até quando os ímpios se alegrarão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Eles proferem palavras arrogantes; Todos aqueles que praticam o mal se orgulham.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Eles esmagam o Teu povo, Yahweh; eles afligem as nações que pertencem a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Eles matam a viúva e o estrangeiro, e assassinam o órfão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Eles dizem: \"Yahweh não verá, o Deus de Jacó não terá conhecimento disso.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Entendei, ó estúpidos! E vós, tolos, quando tereis sabedoria?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Aquele que fez os ouvidos não ouvirá? Aquele que formou os olhos não verá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Aquele que disciplina as nações não corrige? É Ele que dá conhecimento ao homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Yahweh conhece os pensamentos dos homens, que são como um sopro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Abençoado é aquele a quem Tu repreendes, Yahweh, aquele a quem ensinas a Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Tu dás a ele descanso em tempos de dificuldade, até que se abra a cova para o ímpio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Porque Yahweh não renunciará ao Seu povo ou abandonará a Sua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Pois o julgamento será novamente justo; e todos os retos de coração o seguirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Quem se levantará para me defender contra os malfeitores? Quem se levantará por mim contra os perversos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Se Yahweh não tivesse sido minha ajuda, em breve eu estaria deitado no lugar do silêncio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Quando eu disse: \"Meu pé escorrega\", Teu amor leal, Yahweh, me sustentou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Quando as preocupações dentro de mim são muitas, Teu conforto me faz feliz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Pode um trono de iniquidade, o qual cria injustiça em nome da lei, associar-se Contigo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Eles conspiram juntos para tirar a vida do justo, e condenam o inocente à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Mas Yahweh tem sido minha torre alta; o meu Deus é a rocha do meu refúgio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Ele lhes trará a sua própria iniquidade e os destruirá em sua própria maldade. Yahweh, nosso Deus, os exterminará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Vinde, cantemos a Yahweh; cantemos com alegria à Rocha da nossa salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Apresentemo-nos diante Dele com ações de graças; cantemos a Ele com salmos de louvor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'porque Yahweh é o grande Deus, o grande Rei acima de todos os deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Em Suas mãos estão as profundezas da terra; os altos das montanhas Lhe pertencem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'O mar é Dele, pois Ele o fez, e Suas mãos formaram a terra seca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Vinde, adoremos e prostemo-nos; ajoelhemos diante de Yahweh, nosso criador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Porque Ele é o nosso Deus, e nós somos povo do Seu pasto, e ovelhas das Suas mãos. Hoje – oh, que escutais a Sua voz!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, '\"Não endureçais o vosso coração, como em Meribá, ou como no dia de Massá, no deserto,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'onde seus antepassados desafiaram a Minha autoridade e provaram a Minha paciência, apesar de terem visto as Minhas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Por quarenta anos, Eu estive irado com aquela geração e disse: \'Esse é um povo cujo coração se desvia; não conhece os Meus caminhos.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Por isso, jurei na Minha ira que eles não entrariam no Meu lugar de descanso.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Oh! Cantai a Yahweh um cântico novo, cantai a Yahweh toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Cantai a Yahweh, bendizei o Seu nome; anunciai a Sua salvação dia após dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Declarai a Sua gloria entre as nações, Suas maravilhosas obras entre todas as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Pois Yahweh é grande e digno de ser louvado; Ele é mais temível que todos os deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Pois todos os deuses das nações são ídolos, mas Yahweh fez os céus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'esplendor e majestade estão em Sua presença; força e beleza estão em Seu santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Tributai a Yahweh, vós famílias das nações, tributai a Yahweh glória e força.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Tributai a Yahweh a glória que Seu nome merece; trazei uma oferta e entrai em Seu átrios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Prostrai-vos diante de Yahweh, na beleza da Sua santidade. Tremei diante Dele toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Falai entre as nações: \"Yahweh reina\". O mundo está estabelecido e não pode ser abalado. Ele julga os povos com justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Alegrem-se os céus, e regozije-se a terra; ruja o mar e tudo o que nele há.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Exultem os campos e tudo que neles há; todas as árvores na floresta gritem de alegria');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'diante de Yahweh, pois Ele está vindo; Ele está vindo para julgar a terra, Ele julgará o mundo com justiça e os povos com a Sua fidelidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Yahweh reina; alegre-se a terra, alegrem-se as muitas ilhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Nuvens e escuridão O cercam; retidão e justiça são a base do Seu trono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Fogo vai adiante Dele e consome Seus adversários por todos os lados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Sua luz ilumina o mundo; a terra vê e treme.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'As montanhas derretem como cera diante de Yahweh, o Senhor de toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Os céus declaram Sua justiça, e todas as nações veem a Sua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Sejam envergonhados todos os que servem os ídolos e se orgulham de imagens inúteis. Prostem-se diante Dele todos os deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Yahweh, Sião ouviu e se orgulhou, e as filhas de Judá se alegraram por causa dos Teus julgamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Pois tu, Yahweh, és o Altíssimo sobre a terra. Tu és exaltado sobre todos os deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Vós que amais Yahweh, odiai o mal! Ele protege a vida de Seus santos, e Ele os tira da mão do perverso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'A luz é espalhada sobre os justos e a alegria, sobre os retos de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Alegrai-vos em Yahweh, vós justos, e dai graças ao lembrar do Seu santo nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Salmo. Cantai a Yahweh um cântico novo, pois Ele tem feito coisas maravilhosas. Sua mão direita e Seu braço santo Lhe deram a vitória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Yahweh tornou conhecida a Sua salvação; Ele, abertamente, mostrou Sua justiça para todas as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Lembrou-se do Seu amor leal e da Sua fidelidade à casa de Israel; todos os confins da terra viram a salvação do nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Celebrai com alegria a Yahweh, toda a terra; aclamai, regozijai-vos, cantai louvores!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Cantai louvores a Yahweh com a harpa, com a harpa e sons melodiosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Com trombetas e ao som de buzinas, celebrai diante do Rei, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Brame o mar e tudo o que ele contém, o mundo e aqueles que nele vivem!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Os rios batam palmas, e as montanhas cantem de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Yahweh está vindo julgar a terra; Ele julgará o mundo com justiça e as nações com equidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Yahweh reina; tremam as nações. Ele está entronizado sobre os querubins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Yahweh é grande em Sião; Ele é exaltado acima de todas as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Louvem Seu grande e impressionante nome; Ele é santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'O Rei é forte e ama a justiça. Tu estabeleceste equidade; Tu executaste o direito e a justiça em Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Louvai Yahweh, nosso Deus, e adorai diante do estrado de Seus pés, pois Ele é santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Moisés e Arão estavam entre Seus sacerdotes, e Samuel estava entre aqueles que invocavam a Yahweh e Ele lhes respondia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Da coluna de nuvem, Ele lhes falava e eles obedeciam aos Seus mandamentos e aos estatutos que Ele lhes dava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Tu lhes respondeste, Yahweh, nosso Deus. Tu fostes para eles um Deus perdoador, mas, também, puniste os atos pecaminosos deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Louvai Yahweh, nosso Deus, e adorai em Seu santo monte, pois Yahweh, nosso Deus, é santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Salmo de agradecimento. Celebrai com júbilo a Yahweh, toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Servi a Yahweh com alegria; vinde diante de Sua presença com cânticos de júbilo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Sabei que Yahweh é Deus, Ele nos fez e somos Dele. Somos Seu povo e ovelhas do Seu pasto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Entrai por Suas portas com ações de graças e em Seus átrios com louvor; dai graças a Ele e bendizei o Seu nome,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'pois Yahweh é bom. Seu amor leal dura para sempre e Sua fidelidade permanece por todas as gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Salmo de Davi. Cantarei o amor leal e a justiça; a Ti, Yahweh, eu cantarei louvores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Eu andarei no caminho da integridade. Oh, quando Tu virás a mim? Andarei em minha casa com integridade de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Eu não colocarei transgressão diante dos meus olhos; odeio a conduta daqueles que se desviam; isso não se apegará a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Longe de mim o perverso de coração; não me envolverei com o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Eu calarei aquele que calunia seu vizinho secretamente. Não vou tolerar ninguém que tenha um comportamento orgulhoso e uma atitude arrogante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Meus olhos estarão sobre os fiéis da terra para que habitem comigo. Aquele que anda no caminho perfeito me servirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Pessoas enganadoras não permanecerão dentro da minha casa; os mentirosos não se estabelecerão diante dos meus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Manhã após manhã, destruirei todos os ímpios da terra; exterminarei todos os malfeitores da cidade de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Oração do aflito, quando está angustiado e derrama sua lamentação diante de Yahweh. Ouve a minha oração, Yahweh; chegue a Ti o meu clamor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Não escondas Tua face de mim no dia da tribulação. Ouve-me, quando a Ti clamar, responde-me rapidamente!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Pois os meus dias passam como fumaça e os meus ossos queimam como fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Meu coração está ferido, sou como a grama seca; esqueço até de comer meu pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Por causa dos meus gemidos contínuos, meus ossos se apegam à minha pele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Sou como o pelicano do deserto; tornei-me como a coruja das ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Não durmo; sou como um pardal solitário sobre o telhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Meus inimigos me afrontam o dia todo; aqueles que zombam de mim usam meu nome para lançar maldição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Tenho comido cinzas como se fosse pão e misturado a minha bebida com lágrimas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'por causa da Tua ira e da Tua indignação me levantaste e me derrubaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Meus dias são como uma sombra que desaparece e, como a grama, vou secando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Mas Tu, Yahweh, vives para sempre e Teu nome permanecerá por todas as gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Tu Te levantarás e terás misericórdia de Sião. Agora é o momento de ter misericórdia dela; o tempo determinado chegou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Porque Teus servos amam suas pedras e sentem compaixão pelo pó das suas ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'As nações respeitarão o Teu nome, Yahweh, e todos os reis da terra honrarão a Tua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Yahweh reconstruirá Sião e aparecerá em Sua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Nesse tempo, Ele responderá as orações dos desamparados; Ele não rejeitará suas orações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Isto será escrito para as gerações futuras e um povo ainda não nascido louvará a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Pois Ele olhou das alturas do Seu santuário; do céu Yahweh olhou a terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'para ouvir os gemidos dos prisioneiros, para libertar aqueles que foram condenados à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Então, homens proclamarão o nome de Yahweh em Sião e Seus louvores em Jerusalém');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'quando os povos e reinos se reunirem para servir a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Ele enfraqueceu minha força no meio da minha vida. Ele encurtou os meus dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Eu disse: \"Meu Deus, não me leves no meio da minha vida; Tu permaneces por todas as gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Desde os tempos antigos, Tu fundaste a terra; os céus são obras de Tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Eles perecerão, mas Tu permanecerás; todos ficarão velhos como uma vestimenta; como roupas, Tu os removerás e eles desaparecerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Mas Tu és o mesmo e Teus anos não terão fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Os filhos de Teus servos viverão seguros e seus descendentes viverão em Tua presença.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Salmo de Davi. Louva a Yahweh, ó minha alma! Tudo o que há dentro de mim louve Seu santo nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Louva a Yahweh, ó minha alma, e não te esqueças de nenhum dos Seus beneficíos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Ele é quem perdoa todos os teus pecados; Ele é quem cura todas as tuas doenças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Ele redime tua vida da destruição e te coroa com amor leal e com ternos atos de misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Ele satisfaz tua vida com boas coisas, de modo que tua juventude é renovada como a da águia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Yahweh faz justiça e juízo para todos os oprimidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Ele fez os Seus caminhos conhecidos a Moisés e Seus atos, aos descendentes de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Yahweh é misericordioso e gracioso; Ele é paciente e grande é o Seu amor leal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Ele não disciplinará para sempre; Ele não ficará irado para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Ele não nos trata como merecemos, por causa da nossa iniquidade; não nos retribui conforme nossos pecados exigem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Assim como os céus estão muito acima da terra, assim é grande o Seu amor leal para aqueles que O honram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Como está distante o oriente do ocidente, assim Ele tem removido de nós a culpa dos nossos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Como um pai tem compaixão dos seus filhos, assim Yahweh tem compaixão daqueles que O honram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Porque Ele sabe como nós fomos formados; Ele sabe que somos pó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Quanto ao homem, seus dias são como a grama; ele floresce como a flor do campo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'o vento sopra sobre ela, e ela desaparece, e ninguém sabe onde ela havia crescido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Mas o amor fiel de Yahweh é de eternidade a eternidade sobre aqueles que O honram. Sua retidão se estende aos Seus descendentes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'aqueles que guardam Sua aliança e se lembram de obedecer às Suas instruções.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Yahweh estabeleceu Seu trono nos céus e as leis de Seu reino sobre todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Louvai a Yahweh, vós anjos poderosos, que obedeceis à Sua palavra, que obedeceis aos Seus comandos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Louvai a Yahweh todos os Seus exércitos de anjos, vós que sois Seus servos, que executais a Sua vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Louvai a Yahweh todas as Suas criaturas, em todos os lugares onde Ele reina. Eu louvarei a Yahweh com toda a minha vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Eu Te louvarei, Yahweh, com toda a minha vida! Yahweh meu Deus, Tu és magnífico; Tu estás vestido de esplendor e majestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Estás coberto de luz como de um manto; Tu estendes os céus como uma tenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Tu colocas nas nuvens as vigas da Tua morada; Tu fazes das nuvens Tua carruagem; Tu andas sobre as asas do vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Tu fazes dos ventos Teus mensageiros, e de Teus servos, chamas de fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Tu lançaste os fundamentos da terra, e ela jamais será abalada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Tu cobriste a terra com água como um vestido; as águas cobriram as montanhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'À Tua reprovação, as águas retrocederam; ao som trovejante da Tua voz, elas fugiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'As montanhas subiram, e os vales se expandiram em direção aos lugares que Tu determinaste para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Estabeleceste um limite que não podem ultrapassar, para que jamais cubram a terra novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Fazes brotar as fontes nos vales que correm entre as montanhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Elas saciam todos os animais do campo; os jumentos selvagens matam a sede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Junto às suas margens, as aves do céu fazem seus ninhos e, entre os galhos, põem-se a cantar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Tu regas os montes desde a Tua morada no céu. A terra se enche com o fruto do Teu trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Tu fazes crescer o pasto para o gado e plantas para o cultivo do homen, que tira da terra o seu alimento:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'vinho que faz o homen alegre, óleo que faz sua face brilhar e alimento para sustentar sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'As árvores de Yahweh são bem regadas; Ele plantou os cedros do Líbano;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'ali, os pássaros fazem seus ninhos. As cegonhas fazem seu lar nos pinheiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'As cabras selvagens vivem no alto das montanhas; os penhascos dão abrigo aos animais roedores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Determinaste a lua para marcar as estações; o sol sabe quando deve se pôr.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Trazes a escuridão da noite, quando todas as bestas das florestas saem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Os leões novos rugem por sua presa e buscam em Deus seu alimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Quando o sol sobe, eles se retiram e dormem em suas cavernas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'O homem sai para o seu trabalho e labuta até a noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Yahweh, quão numerosas são as Tuas obras! Com sabedoria fizeste todas elas; a terra está cheia das Tuas riquezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Eis o mar, grande e extenso, repleto de inúmeras criaturas, grandes e pequenas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Ali passam os navios e o Leviatã, que Tu formaste para nele brincar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Todos eles esperam em Ti para que lhes dês o alimento na hora certa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Se Tu lhes dás, eles o recolhem; se abres a Tua mão, eles ficam satisfeitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Quando escondes Tua face, eles ficam perturbados; quando retira-lhes o fôlego, eles morrem e retornam ao pó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Quando envias o Teu Espírito, eles são criados, e renovas a face da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'A glória de Yahweh durará para sempre; Yahweh se alegrará em Suas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Ele olha para a terra e ela treme; toca as montanhas e elas fumegam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Cantarei a Yahweh por toda a minha vida; eu cantarei louvores ao meu Deus enquanto eu viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Que meus pensamentos sejam agradáveis a Ti; eu me alegrarei em Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Que sejam eliminados os pecadores da face da terra e que os ímpios não existam mais. Eu louvorei a Yahweh com toda a minha vida. Louvai a Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Louvai a Yahweh, invocai o Seu nome, fazei Suas obras conhecidas entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Cantai-lhe, cantai-lhe louvores; fazei conhecidas todas as Suas maravilhosas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Gloriai-vos no Seu santo nome, alegre-se o coração daqueles que buscam a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Buscai Yahweh e Sua força; buscai Sua presença continuamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Lembrai-vos das coisas maravilhosas que Ele fez, de Seus milagres e os decretos de Sua boca,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'vós descendentes de Abraão, Seu servo, vós povo de Jacó, Seus escolhidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Ele é Yahweh, nosso Deus. Seus decretos estão por toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Ele se lembra para sempre da Sua aliança, da palavra que Ele ordenou para mil gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Ele traz à memória a aliança que fez com Abraão, e seu juramento à Isaque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Isto é o que Ele confirmou a Jacó como estatuto, e a Israel como uma aliança eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Ele disse: \"Eu vos darei a terra de Canaã como porção de vossa herança.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Ele lhes disse isso quando eram poucos em número; pouquíssimos e estrangeiros na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Eles saíram de nação em nação e de um reino a outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Ele não permitiu que ninguém os oprimissem; e repreendeu reis por causa deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Ele disse: \"Não toqueis nos meus ungidos e não façais mal aos meus profetas.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Chamou a fome sobre a terra, cortou todo o suprimento de pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Ele enviou um homem à frente deles; José foi vendido como servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Seus pés foram presos por correntes, correntes de ferro foram colocadas nele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'até o tempo em que sua predição se cumpriu. A palavra de Yahweh o colocou à prova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'O rei enviou servos para soltá-lo, o governador do povo o libertou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Ele o pôs encarregado de sua casa como governador de todas as suas posses,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'para instruir seus príncipes conforme quisesse e para ensinar a sabedoria a seus anciãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Então, Israel entrou no Egito e Jacó morou por um tempo na terra de Cam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Deus aumentou Seu povo grandemente e o fez mais numeroso do que seus adversários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Ele fez com que seus inimigos odiassem Seu povo, maltratassem Seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Ele enviou Moisés, Seu servo, e Arão, a quem havia escolhido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Eles executaram Seus sinais entre os egípcios, Suas maravilhas na terra de Cam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Ele enviou trevas e escureceu aquela terra, mas seu povo não obedeceu aos Seus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Ele transformou as águas em sangue e matou seus peixes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Suas terras se encheram de sapos, até mesmo nos quartos dos governadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Ele falou e enxames de moscas e mosquitos cobriram seu território.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Ele enviou granizo e chuva, com raios e trovões para suas terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Ele destruiu suas vinhas e suas figueiras, quebrou as árvores de seus territórios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Ele falou e vieram os gafanhotos, muitos gafanhotos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'que comeram toda a vegetação do país, toda a colheita da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Ele matou todos os primogênitos em suas terras, as primícias de toda a força deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Retirou os israelitas, que saíram com prata e ouro; e nenhuma de suas tribos tropeçou no caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'O Egito se alegrou quando eles saíram, pois os egípcios estavam com medo deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Yahweh estendeu uma nuvem para cobri-los e fogo para iluminá-los de noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Os israelitas pediram por comida e Ele trouxe codornizes e os saciou com pão do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Dividiu a rocha e águas jorraram dela, fluíram no deserto como um rio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Pois Ele trouxe à mente Sua santa promessa que fez a Abraão, Seu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Ele liderou Seu povo com alegria, Seu escolhido com gritos de triunfo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Deu-lhes as terras das nações, tomaram posse das riquezas dos povos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'para que guardassem Seus estatutos e obedecessem às Suas leis. Louvado seja Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Louvai a Yahweh. Rendei graças a Yahweh, pois Ele é bom, porque Sua fidelidade dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Quem poderá descrever os poderosos atos de Yahweh ou proclamar integralmente todos os seus atos de louvor?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Felizes são aqueles que agem corretamente, e cujas ações são sempre justas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Lembra-Te de mim, Yahweh, quando Tu mostrares favor ao Teu povo; visita-me com a Tua salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Assim, verei a prosperidade dos Teus escolhidos, e me regozijarei na alegria do Teu povo, e me gloriarei com a Tua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Nós pecamos, como nossos ancestrais; nós temos errado e temos feito o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Nossos pais não apreciaram Teus feitos maravilhosos no Egito; eles ignoraram Teus muitos atos de fidelidade; eles foram rebeldes contra o Altíssimo, junto ao mar Vermelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'No entanto, Ele os salvou, por amor de Teu nome, para que pudesse revelar o Teu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Ele repreendeu o mar Vermelho, e o secou. Em seguida, os guiou pelas profundezas, como por um deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Ele os salvou das mãos daqueles que os odiavam, e os resgatou do poder do inimigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Mas as águas cobriram seus adversários; nenhum deles sobreviveu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Então, eles creram em Tuas palavras, e cantaram louvores a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Mas eles, rapidamente, esqueceram-se do que havias feito, e não esperaram pelas Tuas instruções.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Eles tinham desejos insaciáveis no deserto, e desafiaram a Deus na região árida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Ele lhes deu o que pediram, mas enviou uma doença que consumiu os seus corpos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'No acampamento, invejaram Moisés e Arão, os santos sacerdotes de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'A terra se abriu e engoliu Datã, cobrindo os seguidores de Abirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Um fogo começou entre eles, e consumiu os ímpios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Eles fizeram um bezerro em Horebe, e adoraram essa imagem de metal fundido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Eles trocaram a glória de Deus pela imagem de um touro que come grama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Eles se esqueceram de Deus, seu salvador, o qual havia feito grandes coisas no Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Ele havia feito maravilhas na terra de Cam, e atos poderosos no mar Vermelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Ele teria decretado a destruição do povo se Moisés, Seu escolhido, não houvesse intercedido, com Ele na brecha, para desviar Sua ira de destruí-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Então, eles desprezaram a terra frutífera; eles não confiaram na Sua promessa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'mas murmuraram em suas tendas, e não obedeceram à Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Portanto, Ele levantou a Sua mão e jurou que iria deixá-los morrer no deserto;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'dispersaria seus descendentes entre as nações, e os espalharia em terras estrangeiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Eles adoraram a Baal-Peor e comeram sacrifícios oferecidos aos mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'E provocaram a Sua ira, com suas ações, e uma praga se espalhou entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Então, Finéias se levantou para intervir, e a praga cessou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Isto lhe foi imputado como um ato de justiça para todas as gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Eles também enfureceram Yahweh nas águas de Meribá, e Moisés foi castigado por causa deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Eles fizeram Moisés amargo, e ele falou de forma imprudente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Eles não destruiram as nações, como Yahweh lhes havia ordenado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'mas se misturaram com as nações, e aprenderam seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Adoraram seus ídolos, que se tornaram em armadilha para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Eles sacrificaram seus filhos e suas filhas à demônios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Eles derramaram sangue inocente, o sangue de seus filhos e filhas, os quais sacrificaram aos ídolos de Canaã, profanando a terra com sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Eles foram contaminados por seus atos; em suas ações, eles se prostituíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Então, Yahweh Se irou contra o Seu povo, e desprezou a sua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Ele os entregou nas mãos das nações, e aqueles que os odiavam dominaram sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Seus inimigos os oprimiram e eles foram submetidos à sua autoridade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Muitas vezes, Ele veio para ajudá-los, mas eles continuaram se rebelando e foram abatidos pelos seus próprios pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'No entanto, Ele atentou à sua angústia, quando os ouviu clamando por socorro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Ele Se lembrou da aliança com eles e Se arrependeu, por causa do Seu amor leal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Ele fez com que seus conquistadores tivessem pena deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Salva-nos, Yahweh, nosso Deus. Nos reúna dentre as nações para que possamos dar graças ao Teu santo nome, e glória em Teus louvores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Que Yahweh, Deus de Israel, seja louvado de eternidade em eternidade. Todos dizem: \"Amém\". Louvem a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Rendei graças a Yahweh porque Ele é bom e Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Que repitam isso os redimidos de Yahweh, aqueles que Ele resgatou do poder do inimigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'Ele os reuniu das terras estrangeiras, do leste e do oeste, do norte e do sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Eles vagaram no deserto, por terras áridas, e não encontraram cidade para habitar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Eles estavam famintos, sedentos e desmaiavam de exaustão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Então, nas suas dificuldades, clamaram a Yahweh e Ele os resgatou das suas aflições.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Ele os guiou pelo caminho reto. Então, encontraram uma cidade para viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Que todos louvem a Yahweh por Seu amor leal e pelas maravilhas que Ele tem feito pela humanidade!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Porque Ele sacia os sedentos e o apetite dos famintos, e os enche com bondade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Alguns se assentaram na escuridão e na sombra da morte, oprimidos em aflição e correntes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Isso porque eles se rebelaram contra a Palavra de Deus e rejeitaram os mandamentos do Altíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Ele abateu os seus corações com trabalhos pesados; eles tropeçaram e não houve quem os erguesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Assim, em suas dificuldades, eles clamaram a Yahweh. E Ele os livrou das suas aflições.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Ele os tirou da escuridão e das sombras da morte; e quebrou as suas algemas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Oh! Que o povo louve a Yahweh por Seu amor leal e pelas maravilhas que Ele tem feito pela humanidade!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Pois Ele quebrou os portões de bronze e cortou as barras de ferro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Eles foram insensatos em seus caminhos de rebelião e afligidos por causa dos seus pecados;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'perderam o apetite por qualquer comida e chegaram perto dos portões da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Então, na sua dificuldade, eles clamaram a Yahweh; Ele os livrou das suas aflições.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Ele enviou a Sua Palavra e os curou; Ele os resgatou das suas tribulações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Oh! Que o povo louve a Yahweh pelo Seu amor leal e pelas maravilhas que Ele tem feito pela humanidade!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Que ofereçam sacrifícios de gratidão e proclamem, com alegria, os Seus feitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Os que viajam, em navios pelos mares, para negociar além-mar');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'viram os feitos de Yahweh e as suas maravilhas nas profundezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Porque Ele ordenou e a tempestade se levantou nos mares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Os navios alcançaram o céu, desceram às profundezas. Suas vidas se derreteram em aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Eles foram balançados e cambaleavam como bêbados; por fim, perderam toda a esperança de salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Assim, na dificuldade, eles clamaram a Yahweh que os tirou da aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Ele acalmou a tempestade e as ondas se aquietaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Então, eles se regozijaram porque o mar se acalmou; Ele os levou ao porto desejado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Oh! Quisera que todas as pessoas louvassem a Yahweh por Seu amor leal e pelas maravilhas que Ele tem feito para a humanidade!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Que elas O exaltem na assembleia do povo e O louvem no conselho dos anciãos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Ele transformou rios em um deserto, fontes de águas em terra seca,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'e uma terra frutífera em um lugar estéril, por causa da maldade desse povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Ele transformou o deserto em poços de água e terra seca em mananciais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Ele estabeleceu famintos ali, e eles edificaram uma cidade para viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Plantaram campos, vinhas e produziram colheitas abundantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Ele os abençoou, de modo que eles se multiplicaram grandemente; não permitiu que seu rebanho diminuisse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Eles foram reduzidos e humilhados por dolorosa aflição e sofrimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Ele derramou desprezo sobre os líderes e os fez vaguear por lugares desertos, onde não há caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Ele ergueu o necessitado da miséria e multiplicou suas famílias, como um rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'O justo verá isso e se alegrará, e todo o ímpio fechará a sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Quem é sábio considere tudo isso e medite nos bondosos atos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Cântico. Salmo de Davi. Meu coração, ó Deus, está firme; eu cantarei, sim, eu também cantarei louvores, com o meu coração honrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Acordai, saltério e harpa; eu acordarei o amanhecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'A Ti, Yahweh, eu darei graças entre os povos! Eu cantarei louvores a Ti entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Pois o Teu amor leal é grande e se eleva acima do firmamento, e a Tua fidelidade alcança os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Sê exaltado, ó Deus, acima dos céus, e que a Tua glória seja exaltada sobre toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Para que sejam resgatados aqueles a quem Tu amas; resgata-nos com a Tua mão direita e responde-nos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Deus, em Sua santidade, falou: \"Eu Me regozijarei; Eu dividirei Siquém e repartirei o vale de Sucote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Gileade é Meu e Manassés é Meu; também Efraim é Meu capacete e Judá é Meu cetro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moabe é a bacia em que Me lavo; sobre Edom Eu atirarei Meu sapato; Eu gritarei vitória sobre a Filístia.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Quem me trará para a cidade forte? Quem me conduzirá a Edom?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Deus, Tu nos rejeitaste? Tu que já não sais com o nosso exército para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Ajuda-nos contra o adversário, pois o socorro do homem é inútil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Nós triunfaremos com a ajuda de Deus. Ele pisará nossos inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Para o regente musical. Salmo de Davi. Ó, Deus, a quem eu louvo, não fiques em silêncio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Pois os perversos me atacam e falam mentiras contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Eles me cercam e dizem coisas odiosas e me atacam sem motivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Em troca do meu amor, eles me difamam, mas eu oro por eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Eles me pagam o mal pelo bem, e eles odeiam o meu amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Aponta um homen ímpio contra tal inimigo; que um acusador esteja à sua direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Quando ele for julgado, que seja culpado; que sua oração seja considerada pecaminosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Que sejam poucos os seus dias; que outro pegue o seu oficio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Que seus filhos fiquem órfãos e sua esposa, viúva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Que seus filhos andem sem destino, pedindo esmolas, e sejam expulsos de suas casas em ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Que o credor pegue tudo o que ele possui; que estranhos saqueiem o que ele ganha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Ninguém prolongue nenhuma bondade para com ele; que ninguém tenha piedade dos seus órfãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Que sua descendência desapareça; que seu nome seja apagado da próxima geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Que o pecado de seus ancestrais sejam mencionados a Yahweh; e os pecados de sua mãe não sejam esquecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Que sua culpa esteja sempre diante de Yahweh; que Yahweh corte sua memória da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Que Yahweh faça isto porque esse homen nunca se preocupou em mostrar alguma bondade; pelo contrário, atormenta o oprimido, o necessitado e o desencoraja até a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Ele amou a maldição; que ela se volte para ele. Ele odiou a benção; que a benção não venha a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Ele se vestiu de maldição, como uma roupa; que ela penetre em seu interior como água, como óleo em seus ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Que a maldição seja para ele como roupas que ele usa para se cobrir, como o cinto que ele sempre usa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Que essa seja a recompensa de Yahweh para meus acusadores, para aqueles que falam mal de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Yahweh, meu Deus, tem misericórdia de mim por amor do Teu nome. Salva-me por Teu amor leal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Porque sou oprimido e necessitado e meu coração está ferido dentro de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Eu estou desaparecendo como a sombra no anoitecer; sou jogado para longe como um gafanhoto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Meus joelhos estão enfraquecidos pelo jejum, estou ficando pele e ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Estou sendo desdenhado pelos meus acusadores; quando me veem, eles balançam suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Ajuda-me, Yahweh meu Deus; salva-me por Teu amor leal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'E que eles saibam o que estais fazendo; que Tu, Yahweh, tens feito isto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Ainda que eles me amaldiçoem, Tu me abençoas; quando eles me atacarem, que sejam expostos à vergonha, e que Teu servo se alegre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Que meus adversários sejam vestidos de vergonha; que usem sua vergonha como um manto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Com minha boca darei graças a Yahweh; eu o louvarei no meio da multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Porque Ele estará à direita daquele que é necessitado, para salvá-lo daqueles que o julgam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Salmo de Davi. Yahweh disse ao meu Senhor: \"Assenta-te à Minha direita até que Eu ponha os Teus inimigos debaixo de Teus pés.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'De Sião, Yahweh tomará o cetro de Sua força; governará entre os Teus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Com vestes santas, o Teu povo Te seguirá voluntariamente no dia do Teu poder; os Teus jovens virão como o orvalho emergindo do amanhecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Yahweh jurou e não se arrependerá: \"Tu és um sacerdote eterno, à maneira de Melquizedeque.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'O Senhor, que está à Tua direita, destruirá reis no dia da Sua ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Ele julgará as nações; Ele encherá os campos de batalha com cadáveres; destruirá os líderes em muitas nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Ele beberá do riacho pelo caminho e, então, levantará a Sua cabeça depois da vitória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Louvai a Yahweh. Darei graças a Yahweh, com todo o meu coração, na assembleia dos justos, em suas reuniões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'As obras de Yahweh são grandiosas, ansiosamente aguardadas por todos aqueles que as desejam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Sua obra é majestosa e gloriosa, e sua justiça perdura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Ele faz coisas maravilhosas que serão lembradas; Yahweh é gracioso e misericordioso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Dá alimento aos Seus servos fiéis. Ele sempre Se lembrará da Sua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Mostrou Suas poderosas obras ao Seu povo, dando-lhes a herança das nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'As obras de Suas mãos são fiéis e justas; todas as Suas instruções são confiáveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Elas são estabelecidas para sempre, para serem observadas fielmente e adequadamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Ele deu vitória ao Seu povo; estabeleceu Sua aliança para sempre; santo e maravilhoso é o Seu nome!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'O temor de Yahweh é o princípio da sabedoria; aqueles que seguem Suas instruções têm bom entendimento. Seu louvor dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Louvai a Yahweh. Bendito é o homem que obedece a Yahweh, que tem grande prazer em Seus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Seus descendentes serão poderosos na terra; os descendentes dos justos serão abençoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Prosperidade e riqueza estão em sua casa; Sua justiça durará para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'A luz brilha nas trevas para os justos; Ele é gracioso, misericordioso e justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Feliz é o homem que se compadece e empresta dinheiro, que conduz seus negócios com honestidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Pois ele nunca será abalado; o homem justo será lembrado para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Ele não teme notícias ruins; ele é seguro, pois confia em Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Seu coração é tranquilo e não sente medo, até que ele triunfe sobre seus adversários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Ele dá generosamente aos pobres; sua justiça dura para sempre; ele será exaltado com honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'O perverso verá isso e ficará furioso; ele rangerá seus dentes e fugirá; o desejo dos perversos perecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Louvai a Yahweh. Louvai-o, vós, servos de Yahweh; louvai o nome de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Bendito seja o nome de Yahweh, agora e para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Desde o nascer ao pôr do sol, louvado seja o nome de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Yahweh é exaltado sobre todas as nações, e Sua glória alcança acima dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Quem é como Yahweh, nosso Deus, que está entronizado nas alturas');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'e, do alto, olha para o céu e a terra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Do pó, Ele levanta o pobre, e do monturo ergue o necessitado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'para que ele possa assentar-se com príncipes, com os príncipes do Seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Ele dá um lar à mulher estéril, e a faz uma alegre mãe de filhos. Louvado seja Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Quando Israel saiu do Egito, e a casa de Jacó do meio daquele povo estrangeiro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Judá tornou-se Seu santuário e Israel, Seu reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'O mar viu e fugiu; o Jordão recuou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'As montanhas saltaram como carneiros, as colinas saltaram como cordeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Mar, por que fugiste? Jordão, por que recuaste?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Montanhas, por que saltastes como carneiros? Colinas, por que saltastes como cordeiros?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Terra, estremece diante do Senhor, na presença do Deus de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Ele transformou a rocha em um lago de águas, e a dura rocha em uma fonte de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Não a nós, Yahweh, não a nós, mas ao Teu nome seja a glória, por causa do Teu amor e da Tua fidelidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Por que as nações diriam: \"Onde está o Deus deles?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Nosso Deus está nos Céus; Ele faz conforme Lhe agrada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Os ídolos das nações são ouro e prata, obra das mãos dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Esses ídolos têm boca, mas não falam; têm olhos, mas não veem;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'têm ouvidos, mas não ouvem; têm nariz, mas não cheiram;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'eles têm mãos, mas não sentem; eles têm pés, mas não andam, nem falam com suas próprias bocas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Aqueles que os fazem são semelhantes a eles, assim como todos os que neles confiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Israel, confia em Yahweh; Ele é teu socorro e escudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Casa de Aarão, confia em Yahweh; Ele é teu socorro e escudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Tu que honras Yahweh, confia Nele; Ele é o teu socorro e escudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Yahweh tem-se lembrado de nós e nos abençoará. Ele abençoará a casa de Israel, abençoará a casa de Aarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Ele abençoará aqueles que O honram, tanto jovens como velhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Que Yahweh vos multiplique mais e mais, vós e vossos descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Que sejais abençoados por Yahweh, que fez os céus e a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Os céus pertencem a Yahweh, mas a terra foi dada à humanidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Os mortos não louvam a Yahweh, nem os que descem ao silêncio;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'mas nós bendiremos a Yahweh, agora e para sempre. Louvai a Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Eu amo Yahweh; Ele escuta a minha voz e minhas súplicas por misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Porquanto Ele me escuta, eu O invocarei enquanto viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Laços de morte me cercaram, e as armadilhas do Sheol me confrontaram; eu me senti angustiado e triste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Então, invoquei o nome de Yahweh: \"Ó, Yahweh, salva a minha vida!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Yahweh é misericordioso e justo; nosso Deus é compassivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Yahweh protege os simples; eu estava abatido, e Ele me salvou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Minha alma pode retornar ao seu lugar de descanso, pois Yahweh tem sido bondoso comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Livraste a minha vida da morte, meus olhos das lágrimas e meus pés do tropeço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Servirei a Yahweh na terra dos viventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Eu cri Nele, mesmo quando disse: \"Estou em grande aflição.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Em minha perturbação, disse: \"Todos os homens são mentirosos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Como retribuirei a Yahweh por toda a Sua bondade para comigo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Levantarei o cálice da salvação e invocarei o nome de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Cumprirei meus votos a Yahweh na presença de todo o Seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Preciosa, aos olhos de Yahweh, é a morte dos Seus santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Yahweh, certamente, sou Teu servo. Sou Teu servo, o filho da Tua serva; Tu me livras das minhas amarras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Eu Te oferecerei sacrifícios de ação de graças, e invocarei o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Cumprirei meus votos feitos a Yahweh na presença de todo o Seu povo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'nos átrios da casa de Yahweh, no meio de ti, Jerusalém. Louvai a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Louvai a Yahweh, todas as nações; exaltai-O, todos os povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Pois Sua fidelidade é grande para conosco, e a verdade de Yahweh dura para sempre. Louvai a Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Dai graças a Yahweh, pois Ele é bom, pois Sua fidelidade dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Que Israel diga: \"Sua fidelidade dura para sempre.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Que a casa de Arão diga: \"Sua fidelidade dura para sempre.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Que os fiéis seguidores de Yahweh digam: \"Sua fidelidade dura para sempre.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Na minha angústia, clamei a Yahweh, Ele me respondeu e me libertou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Yahweh está comigo, eu não temerei; o que o homem pode me fazer?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Yahweh está ao meu lado, é meu ajudador; triunfarei sobre os que me odeiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'É melhor buscar refúgio em Yahweh do que confiar no homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'É melhor se refugiar em Yahweh do que colocar sua fé em príncipes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Todas as nações me cercaram, mas, em nome de Yahweh, eu as exterminei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Elas me cercaram, sim, elas me cercaram; em nome de Yahweh, eu as exterminei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Elas me cercaram como abelhas, e desapareceram tão rapidamente quanto os espinhos no fogo; em nome de Yahweh, eu as exterminei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Elas me atacaram para me derrubar, mas Yahweh me ajudou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Yahweh é minha força e alegria; é Ele quem me resgata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'O grito alegre de vitória é ouvido nas tendas dos justos; a mão direita de Yahweh domina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'A mão direita de Yahweh é exaltada; a mão direita de Yahweh conquista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Não morrerei, mas viverei e declararei os atos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Yahweh me puniu severamente, mas Ele não me entregou à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Abri as portas da justiça para mim, entrarei por elas e darei graças a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Esta é a porta de Yahweh; o justo entra por ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Eu te darei graças, pois Tu me respondeste e te tornaste a minha salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'A pedra que os construtores rejeitaram se tornou a pedra angular.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Isto é obra de Yahweh, e é maravilhoso aos nossos olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Este é o dia em que Yahweh agiu; nele nos regozijaremos e nos alegraremos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Ó, Yahweh, faz-nos vitoriosos! Faz-nos prosperar!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Bendito é o que vem em nome de Yahweh; da casa de Yahweh nós vos abençoamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Yahweh é Deus. Ele resplandece sobre nós; amarrai com cordas o sacrifício no altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Tu és o meu Deus, e eu Te darei graças; Tu és o meu Deus; Eu Te exaltarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Oh, dai graças a Yahweh, pois Ele é bom. Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Como são felizes aqueles cuja conduta é irrepreensível, que andam na lei de Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Como são felizes aqueles que guardam os decretos da Sua aliança, que O buscam de todo o coração,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'que não praticam o mal, mas andam em Seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Tu nos ordenaste a guardar Teus preceitos, para cumpri-los fielmente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Que eu seja estabelecido firmemente para cumprir Teus estatutos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Então, não me envergonharei quando meditar em todos os Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Eu Te louvarei com um coração sincero, quando aprender Teus justos juízos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Cumprirei Teus estatutos; não me desampares jamais!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Como poderá um jovem manter sua conduta irrepreensível? Guardando-se de acordo com a Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Com todo o meu coração Te busco; não me deixes desviar dos Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Escondi Tuas palavras no meu coração para não pecar contra Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Bendito és Tu, Yahweh! Ensina-me Teus estatutos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Com meus lábios tenho declarado todos os juízos da Tua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'No caminho dos decretos da Tua aliança, tenho mais alegria que em todas as riquezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Meditarei nos Teus preceitos e contemplarei os Teus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Tenho prazer nos Teus estatutos; não me esquecerei da Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Sê generoso com Teu servo, para que eu viva e guarde a Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Desvenda os meus olhos para que eu contemple as maravilhas da Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Sou um peregrino na terra; não escondas de mim os Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Minha alma sempre anseia por todos os Teus juízos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Tu repreendes os soberbos, que são malditos, e que se desviam dos Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Aparta de mim a desgraça e a humilhação, pois guardo os decretos da Tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Ainda que governantes tramem e falem contra mim, Teu servo medita nos Teus estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Os decretos da Tua aliança são o meu prazer, são meus conselheiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Minha alma está apegada ao pó! Vivifica-me segundo a Tua palavra!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Eu Te relatei minha conduta, e Tu me respondeste. Ensina-me os Teus estatutos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Faz-me entender o caminho dos Teus preceitos, para que eu medite em Teus maravilhosos ensinamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Minha alma se derrete de tristeza. Consola-me, segundo a Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Afasta-me do caminho da falsidade e ensina-me graciosamente a Tua lei!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Escolhi o caminho da fidelidade e decidi seguir os Teus juízos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Eu me apego aos decretos da Tua aliança; que eu não seja envergonhado, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Percorrerei o caminho dos Teus mandamentos, pois Tu amplias meu entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Ensina-me, Yahweh, o caminho dos Teus estatutos, e eu os seguirei até o fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Dá-me entendimento para seguir a Tua lei e a guardarei com todo o meu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Guia-me no caminho dos Teus mandamentos, pois neles me deleito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Inclina o meu coração para os decretos da Tua aliança, e não para a cobiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Desvia os meus olhos de contemplarem coisas inúteis! Vivifica-me no Teu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Confirma ao Teu servo a promessa que fizeste aos que Te temem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Afasta de mim as reprovações que me deixam temeroso, pois sei que Teus juízos são bons.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Almejo por Teus preceitos; vivifica-me com Tua justiça!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'E venham sobre mim, Yahweh, o Teu amor leal e a Tua salvação, conforme a Tua promessa;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'assim, saberei responder aos que me desafiam, pois confio em Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Jamais tires da minha boca a palavra da verdade, pois espero por Teus juízos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Assim, observarei a Tua lei, sem cessar, para todo o sempre;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'andarei em segurança, pois busco os Teus preceitos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'e falarei dos decretos da Tua aliança diante dos reis, e não serei envergonhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Teus mandamentos, que eu amo, são o meu prazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Levantarei as mãos para os Teus mandamentos, que eu amo, e meditarei em Teus estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Lembra-Te da palavra dada ao Teu servo, pela qual me deste esperança!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Este é o meu consolo na aflição: que a Tua palavra me dá vida!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Os soberbos zombam de mim, mas não me afasto da Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Yahweh, lembro-me dos Teus juízos do passado, e sou consolado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Indignação apoderou-se de mim, por causa dos ímpios, pois rejeitam Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Teus estatutos têm sido as minhas canções na casa da minha peregrinação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Durante a noite, lembro-me do Teu nome, Yahweh, e guardo Tua lei;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'esse tem sido o meu propósito, porque guardo Teus preceitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Yahweh, Tu és a minha herança! Prometi guardar as Tuas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'De todo o coração, imploro a Tua graça; tem misericórdia de mim, segundo a Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Examinei meus caminhos e dirigi meus passos para os decretos da Tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Apresso-me e não demoro em cumprir Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Os laços do ímpio me prendem, contudo não me esqueço da Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'À meia-noite, levanto-me para dar-Te graças por Teus justos juízos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Sou amigo de todos os que Te temem e cumprem Teus preceitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'A terra está cheia do Teu amor leal, Yahweh. Ensina-me Teus estatutos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Tens sido bondoso para com o Teu servo, segundo a Tua Palavra, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Ensina-me o discernimento e a entendedimento, pois creio nos Teus estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Antes de ser afligido, eu andava errado mas, agora, obedeço à Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Tu és bondoso e fazes o bem. Ensina-me os Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Os soberbos inventam mentiras contra mim, porém, de todo o meu coração, obedeço aos Teus preceitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'O coração deles tornou-se endurecido; eu, porém, me deleito na Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Foi bom para mim ter sofrido para que aprendesse os Teus estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Mais preciosa para mim é a palavra da Tua boca do que milhões em ouro e prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Tuas mãos me criaram e me formaram; dá-me entendimento para aprender os Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Os que Te temem se alegrarão quando me virem, porque espero em Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Reconheço, Yahweh, que Teus juízos são justos, e que me afligiste por causa da Tua fidelidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Oro para que eu seja confortado por Teu amor leal, segundo a palavra que deste ao Teu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Venha sobre mim a Tua compaixão e viverei, pois tenho prazer na Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Envergonhados sejam os soberbos, que me difamam com calúnias; eu, porém, meditarei nos Teus preceitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Voltem-se para mim, os que Te temem; aqueles que conhecem os decretos da Tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Que meu coração seja irrepreensível com respeito aos Teus estatutos, para que eu não seja envergonhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Minha alma anseia por Teu livramento; espero em Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Meus olhos esperam por Tua promessa: quando me consolarás?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Embora eu tenha me tornado como um odre de vinho na fumaça, ainda assim, não me esqueço dos Teus estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Quantos serão os dias do Teu servo? Quando executarás os Teus juízos contra aqueles que me perseguem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Os soberbos, que não andam segundo a Tua lei, abriram covas para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Todos os Teus mandamentos são fiéis. Socorre-me dos que me perseguem injustamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Eles quase me eliminaram da terra; eu, porém, não abandono os Teus preceitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Por Teu amor leal, vivifica-me, para que eu guarde os decretos de Tua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Yahweh, por toda a eternidade a Tua palavra permanece nos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'A Tua fidelidade se estende de geração em geração. Tu estabeleceste a terra, e ela permanece;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'por Teus juízos, ela continua até hoje, pois todas as coisas estão a Teu serviço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Se a Tua lei não fosse o meu prazer, eu teria perecido em minha aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Jamais me esquecerei dos Teus preceitos, pois por eles Tu tens me dado vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Sou Teu; salva-me porque busco os Teus preceitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Os ímpios espreitam para me destruir, mas me concentro nos decretos da Tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Tenho visto há limites em toda perfeição; porém, Teus mandamentos são ilimitados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Como amo a Tua lei! É minha meditação todo o dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Teus mandamentos, que estão sempre comigo, me fazem mais sábio do que meus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Tenho mais entendimento que todos os meus mestres, porque medito nos decretos da Tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Compreendo mais que os anciãos, porque guardo os Teus preceitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Guardo os meus pés de todo o mau caminho para obedecer à Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Não me aparto dos Teus juízos, pois Tu me tens instruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Quão doces são as Tuas palavras ao meu paladar! Sim, mais doces que o mel para a minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Por meio dos Teus preceitos, adquiro entendimento, por isso detesto todo caminho falso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'A Tua Palavra é lâmpada para os meus pés e luz para o meu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Fiz um voto e o cumprirei: obedecerei aos Teus justos juízos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Estou muito aflito! Yahweh, vivifica-me segundo Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Aceita, Yahweh, as ofertas voluntárias da minha boca, e ensina-me Teus justos juízos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Minha vida está sempre em perigo; todavia, não me esqueço da Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'O ímpio montou uma armadilha contra mim, porém, não me desviei dos Teus preceitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Tomei como herança eterna os decretos da Tua aliança, pois eles são alegria para o meu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Meu coração está decidido a obedecer aos Teus estatutos para sempre e sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Detesto aqueles que agem de forma inconstante, mas amo a Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Tu és o meu abrigo e o meu escudo; espero na Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Apartai-vos de mim, malfeitores! Quero cumprir os mandamentos do meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Sustenta-me segundo as Tuas promessas para que eu viva; não permitas que eu seja envergonhado na minha esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Ampara-me e serei salvo; meditarei continuamente nos Teus estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Tu rejeitas a todos que se desviam dos Teus estatutos, porque são pessoas falsas e astutas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Tu rejeitas, como escória, todos os ímpios da terra; por isso, amo os decretos da Tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Meu corpo estremece de temor diante de Ti, e tenho medo dos Teus justos juizos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Pratico o que é justo e correto; não me entregues aos meus opressores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Garante o bem-estar do Teu servo; não permitas que o arrogante me oprima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Os meus olhos desfalecem à espera da Tua salvação e da Tua justa promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Trata o Teu servo conforme a Tua aliança fiel, e ensina-me os Teus estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Sou Teu servo; dá-me entendimento para que eu conheça os decretos da Tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'É hora de agires, Yahweh, pois eles violaram a Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Amo os Teus mandamentos mais que o ouro, mais que o puro ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Por isso, em tudo sigo os Teus preceitos, e aborreço todo o caminho de falsidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Os decretos da Tua aliança são maravilhosos, por isso eu os observo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'A explicação das Tuas palavras ilumina e dá entendimento aos simples.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Abro a minha boca e suspiro, pois desejo Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Volta-Te para mim e tem misericórdia de mim, como costumas fazer aos que amam o Teu nome!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Conduze os meus passos na Tua palavra; não deixes nenhum pecado me governar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Livra-me da opressão dos homens; assim, obedecerei aos Teus preceitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Faz resplandecer o Teu rosto sobre o Teu servo e ensina-me Teus estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Rios de lágrimas correm dos meus olhos, porque as pessoas não cumprem a Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Tu és justo, Yahweh, e Teus juízos são retos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Tu ordenaste os decretos da Tua aliança com justiça e com grande fidelidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Meu zelo me consome porque meus adversários esqueceram as Tuas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Tua palavra é totalmente pura e o Teu servo a ama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Embora pequeno e desprezado, não me esqueço dos Teus preceitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Tua Justiça é justiça eterna, e a Tua lei é a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Embora a aflição e a angústia tenham me atingido, Teus mandamentos são o meu prazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Os decretos da Tua aliança são justos para sempre; dá-me entendimento para que eu viva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Com todo o meu coração, clamo a Ti. Atende-me, Yahweh, e guardarei os Teus estatutos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Eu suplico: salva-me, e cumprirei os decretos da Tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Levanto antes do amanhecer e clamo por ajuda. Em Tua palavra coloco minha esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Mantenho os meus olhos abertos nas vigílias da noite, para meditar em Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Ouve a minha voz segundo o Teu amor leal, Yahweh; vivifica-me conforme Teus juízos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Meus perseguidores se aproximam; eles estão afastados da Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Tu estás perto, Yahweh, e todos os Teus mandamentos são verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Há muito tempo, aprendi os decretos da Tua aliança, os quais Tu estabeleceste para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Vê minha aflição e livra-me, pois não me esqueço da Tua lei!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Advoga minha causa e defende-me; vivifica-me de acordo com as Tuas promessas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'A salvação está longe dos ímpios porque não procuram os Teus estatutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Grandes são os Teus atos de misericórdia, Yahweh! Vivifica-me segundo os Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Numerosos são os meus inimigos e aqueles que me perseguem; porém, não me desvio dos decretos da Tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Vejo os traidores e sinto desgosto porque não guardam a Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Vê como amo os Teus preceitos, Yahweh! Vivifica-me segundo o Teu amor leal!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'A essência da Tua palavra é a verdade; e todos os Teus justos juízos são eternos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Príncipes me perseguem sem motivo; porém, meu coração reverencia a Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Regozijo-me em Tuas promessas, como alguém que encontra um grande tesouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Eu detesto e aborreço a falsidade, mas amo a Tua lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Sete vezes ao dia, Te louvo porque Teus juízos são justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Grande paz têm os que amam a Tua lei: para eles não há tropeço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Eu espero por Tua salvação, Yahweh, e cumpro os Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Obedeço aos decretos da Tua aliança e os amo intensamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Guardo os Teus preceitos e os decretos da Tua aliança, pois todos os meus caminhos estão diante de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Chegue a Ti o meu clamor, Yahweh. Dá-me entendimento de acordo com a Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Chegue a minha súplica à Tua presença. Ajuda-me, conforme a Tua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Que transborde louvor dos meus lábios, pois Tu me ensinas os Teus estatutos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Que a minha língua cante a Tua palavra, porque todos os Teus mandamentos são justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Que a Tua mão me socorra, pois escolhi os Teus preceitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Desejo o Teu livramento, Yahweh; Tua lei é o meu prazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Que eu viva para Te louvar, e que os Teus justos juízos me socorram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Ando sem destino, como ovelha desgarrada; procura o Teu servo, pois não me esqueço dos Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Cântico dos degraus. Em minha aflição, clamei a Yahweh e Ele me respondeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Livra-me, Yahweh, dos que mentem com seus lábios e enganam com sua língua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Como Ele vos punirá, e o que mais Ele vos fará, vós que tendes uma língua mentirosa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Ele atirará em vós com flechas afiadas de guerreiros, que foram forjadas sobre as brasas de zimbro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Ai de mim, porque fui peregrino em Meseque, e habitei nas tendas de Quedar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Por muito tempo vivi com os que odeiam a paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Sou pela paz, mas, quando falo, eles são pela guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Cântico dos degraus. Elevo meus olhos para os montes. De onde virá o meu socorro?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'O meu socorro vem de Yahweh, que fez os céus e a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Ele não permitirá que teus pés escorreguem; Aquele que te protege não dormirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Vê, o guardião de Israel nunca pega no sono ou dorme.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Yahweh é teu guardião; Yahweh é a sombra à tua direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'O sol não te prejudicará de dia, nem a lua de noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Yahweh te protegerá de todo mal, Ele protegerá tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Yahweh te protegerá em tudo o que fizeres, agora e para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Cântico dos degraus. Salmo de Davi. Alegrei-me quando me disseram: \"Vamos à Casa de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Jerusalém, nossos pés estão dentro de teus portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jerusalém, que foste cuidadosamente construída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'As tribos sobem para Jerusalém — as tribos de Yahweh — como um testemunho para Israel, para dar graças ao nome de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Lá, tribunais foram definidos, tribunais da casa de Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Orai pela paz de Jerusalém! Terão paz aqueles que te amam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Haja paz dentro das muralhas que te defendem; que tenham paz dentro das tuas fortalezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Pelo bem dos meus irmãos e amigos direi: \"Haja paz em ti.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Pelo bem da casa de Yahweh, nosso Deus, buscarei o teu bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Cântico dos degraus. A Ti elevo os meus olhos, Tu que estás entronizado nos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Vede, assim como os olhos dos servos estão atentos à mão de seu mestre, e os olhos da serva, à mão de sua senhora, assim nossos olhos estão voltados para Yahweh, nosso Deus, até que Ele tenha misericórdia de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Tem misericórdia de nós, Yahweh, tem misericórdia de nós, pois estamos fartos de tanta humilhação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Estamos mais do que cheios da zombaria dos insolentes e do desprezo dos orgulhosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Cântico dos degraus. Salmo de Davi. Se Yahweh não estivesse ao nosso lado — Israel o diga —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'se Yahweh não estivesse ao nosso lado quando os homens se levantaram contra nós,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'então, eles nos teriam engolido vivos, quando se enfureceram contra nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'A água nos teria arrastado para longe; a torrente teria passado sobre nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Então, as águas abundantes teriam nos afogado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Bendito seja Yahweh, que não nos deu por presas aos dentes deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Escapamos como pássaros do laço dos caçadores; o laço foi rompido, e nós escapamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Nosso socorro está em Yahweh, que fez o céu e a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Cântico dos degraus. Aqueles que confiam em Yahweh são como o monte Sião: inabalável, que permanece para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Como as montanhas cercam Jerusalém, assim Yahweh cerca o Seu povo, agora e para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'O cetro da impiedade não governará na terra dos justos. Caso contrário, os justos poderiam se corromper.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Faz o bem, Yahweh, para aqueles que são bons e para aqueles que têm um coração justo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'mas, aqueles que seguem caminhos tortuosos, Yahweh os levará com os malfeitores. Que a paz esteja sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Cântico dos degraus. Quando Yahweh restaurou a sorte de Sião, ficamos como os que sonham.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Então, a nossa boca se encheu de riso e a nossa língua, de cânticos. E disseram entre as nações: \"Yahweh fez grandes coisas por eles.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Sim! Yahweh fez grandes coisas por nós. Por isso, estamos tão felizes!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Restaura nossa sorte, Yahweh, como as correntes no Neguebe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Aqueles que semeiam com lágrimas colherão com brados de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Aquele que sai chorando, carregando sementes para plantar, voltará com regozijo, trazendo consigo os seus feixes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Cântico de degraus. De Salomão. Se Yahweh não edificar a casa, inutilmente trabalham aqueles que a edificam. Se Yahweh não guardar a cidade, em vão o vigia montará guarda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Inútil vos será acordar de madrugada e voltar tarde para casa, trabalhando arduamente pelo pão; aos Seus amados, Yahweh provê enquanto eles dormem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Os filhos são herança de Yahweh, e o fruto do ventre é a Sua recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Como flechas nas mãos de um guerreiro, assim são os filhos da juventude.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Como é abençoado o homem que tem a sua aljava cheia deles. Ele não será envergonhado quando confrontar seus inimigos à porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Cântico de degraus. Como é feliz aquele que honra Yahweh, aquele que anda em Seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'O que o teu trabalho te fornecer, tu desfrutarás; serás abençoado e próspero.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Tua esposa será como videira frutífera em tua casa; teus filhos serão como plantas de oliveira que se sentam ao redor da tua mesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Sim, certamente, o homem que honra Yahweh será abençoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Que Yahweh te abençoe desde Sião; que tu vejas a prosperidade de Jerusalém todos os dias da tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Que tu vivas para ver os filhos dos teus filhos. Que a paz esteja sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Cântico dos degraus. Desde a minha juventude, eles têm-me afligido frequentemente — que Israel o diga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Desde a minha juventude, eles têm-me afligido frequentemente; todavia, não me derrotaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Os lavradores araram sobre minhas costas; eles abriram longos sulcos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Todavia, Yahweh é justo; Ele cortou as cordas dos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Que eles retornem envergonhados — todos os que odeiam Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Que sejam como o capim nos telhados, que murcha antes de crescer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'e não enche a mão do ceifador, nem os braços daquele que ata os feixes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Que todos aqueles que passam não digam: \"A benção de Yahweh esteja sobre vós. Nós vos abençoamos em Nome de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Cântico de degraus. Das profundezas eu clamo a Ti, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Senhor, escuta a minha voz; estejam os Teus ouvidos atentos aos meus pedidos de súplica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Yahweh, se Tu notasses as iniquidades, quem de nós resistiria?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Contudo, em Ti há perdão, para que sejas reverenciado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Eu espero por Yahweh; minha alma espera e, na Tua palavra, tenho esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Minha alma espera pelo Senhor mais do que os vigias esperam pela manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Israel, espera em Yahweh. Yahweh é misericordioso e está totalmente disposto a perdoar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'É Ele quem redimirá Israel de todos os seus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Cântico dos degraus. Yahweh, meu coração não é orgulhoso, e meus olhos não são altivos. Eu não espero por grandes coisas ou me preocupo com questões demasiadamente difíceis para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Na verdade, eu acalmei e aquietei a minha alma; como uma criança desmamada de sua mãe; a minha alma, dentro de mim, é como essa criança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Israel, espera em Yahweh, agora e para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Cântico dos degraus. Yahweh, por amor a Davi, relembra de todas as suas aflições.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Relembra como ele jurou a Yahweh, como ele fez voto ao Poderoso de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Ele disse: \"Não entrarei em minha casa ou deitarei em minha cama,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'não darei sono aos meus olhos ou descanso às minhas pálpebras');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'até que eu encontre um lugar para Yahweh, um tabernáculo ao Poderoso de Jacó.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Ouvimos dizer que a arca está em Efrata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Nós a encontramos nos campos de Jaar. Iremos ao tabernáculo de Deus; adoraremos no estrado de Seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Levanta-Te, Yahweh. Vem ao Teu lugar de repouso, Tu e a arca da Tua fortaleza!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Que os Teus sacerdotes se vistam de integridade; que Teus fiéis bradem de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Por causa do Teu servo Davi, não Te afastes do Teu rei ungido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Yahweh jurou firmemente a Davi; Ele não voltará atrás: \"Colocarei um de teus descendentes em teu trono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Se teus filhos guardarem a Minha aliança e as leis que Eu lhes ensinarei, os filhos deles também sentarão sobre teu trono para todo o sempre.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Certamente, Yahweh escolheu Sião; Ele a desejou para Seu trono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, '\"Este é o Meu lugar de descanso para sempre; viverei aqui, pois a escolhi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Eu a abençoarei abundantemente com provisões;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'saciarei seus pobres com pão. Vestirei seus sacerdotes com salvação; seus fiéis bradarão de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Ali, farei crescer a força de Davi; e colocarei uma lâmpada para o Meu ungido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Envergonharei seus inimigos, mas a coroa dele brilhará.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Cântico dos degraus. De Davi. Vede quão bom e agradável é que os irmãos vivam juntos, em união!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'É como o óleo precioso sobre a cabeça e que desce sobre a barba, a barba de Arão, e desce até a gola de suas vestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'É como o orvalho de Hermom, que cai sobre os montes de Sião. De lá, Yahweh ordenou a bênção: vida para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Bendizei a Yahweh, todos os Seus servos! Todos vós que servis na Casa do Senhor durante a noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Erguei as mãos para o santo lugar e bendizei a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Yahweh te abençoe de Sião, Ele que fez os céus e a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Louvai Yahweh. Louvai o nome de Yahweh. Louvai-o, servos de Yahweh,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'vós que servis na Casa de Yahweh, nos pátios da Casa de nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Louvai Yahweh, pois Ele é bom; cantai louvores ao Seu nome, pois é prazeroso fazê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Pois Yahweh escolheu Jacó para Si e Israel como Sua posse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Eu sei que Yahweh é grande, que nosso Senhor é sobre todos os deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Tudo o que Yahweh deseja, Ele o faz nos céus, na terra, nos mares e nas profundezas do oceano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Ele traz as nuvens de longe, fazendo com que raios acompanhem a chuva, e trazendo os ventos para fora de Seus depósitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Ele matou o primogênito do Egito, tanto dos homens quanto dos animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Ele enviou sinais e maravilhas ao Egito, contra Faraó e todos os seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Ele atacou muitas nações e matou reis poderosos:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Siom, rei dos amorreus, e Ogue, rei de Basã, e todos os reinos de Canaã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'Ele deu sua terra como herança, uma herança para Israel, o Seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Seu nome, Yahweh, dura para sempre; Sua reputação, Yahweh, perdura por todas as gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Pois Yahweh defende Seu povo e tem compaixão de Seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Os ídolos das nações são prata e ouro, trabalho das mãos dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Esses ídolos têm boca, mas não falam; têm olhos, mas não vêem;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'eles têm ouvidos, mas não ouvem, nem há respiração em suas bocas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Aqueles que o fazem são como eles, assim como todos os que confiam neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Descendentes de Israel, bendizei Yahweh; descendentes de Arão, bendizei Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Descendentes de Levi, bendizei Yahweh; tu que honras Yahweh, bendizei Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Bendito seja Yahweh em Sião, Ele que vive em Jerusalém. Louvai Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Oh, dai graças a Yahweh, porque Ele é bom, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Oh, dai graças ao Deus dos deuses, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Oh, dai graças ao Senhor dos senhores, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Àquele que, sozinho, faz grandes maravilhas, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Àquele que com sabedoria fez os céus, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Àquele que estendeu a terra sobre as águas, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Àquele que fez os grandes luminares, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'o sol para governar o dia, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'a lua e a as estrelas para governarem a noite, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Àquele que matou os primogênitos do Egito, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'e tirou Israel do seu meio, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'com uma forte mão e um braço erguido, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Àquele que dividiu o mar Vermelho, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'e fez Israel atravessá-lo ao meio, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'mas derrubou Faraó e o seu exército no mar Vermelho, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Àquele que conduziu Seu povo pelo deserto, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Àquele que matou grandes reis, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'e matou reis famosos, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Siom, rei dos Amorreus, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'e Ogue, rei de Basã, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'e deu a terra deles como herança, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'uma herança para Israel, seu servo, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Àquele que se lembrou de nós e nos ajudou em nossa humilhação, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'e que nos deu vitória sobre nossos inimigos, pois o Seu amor leal dura para sempre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'que dá alimento a todos os seres vivos, pois o Seu amor leal dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Oh, dai graças ao Deus dos céus, pois o Seu amor dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Sentamos às margens dos rios da Babilônia e choramos quando pensamos em Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Nos salgueiros daquele lugar penduramos nossas harpas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Lá, aqueles que nos capturaram nos pediam canções, e aqueles que zombavam de nós pediam que ficássemos alegres, dizendo: \"Cantai a nós uma das canções de Sião.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Como podíamos cantar uma canção sobre Yahweh em terra estrangeira?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Se eu ignorar tua memória, Jerusalém, que a minha mão direita perca a destreza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Que a minha língua se prenda ao céu da minha boca se eu não pensar mais sobre ti, se eu não preferir Jerusalém aos meus maiores deleites.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Relembra, Yahweh, o que os edomitas fizeram no dia em que Jerusalém caiu. Eles disseram: \"Destruí-a, destruí-a até seus alicerces.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Filha da Babilônia, prestes a ser destruída — que seja abençoado quem quer que retribua o que fizeste a nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Que seja abençoado quem quer que pegue os teus filhos pequenos e os arremesse contra a rocha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Salmo de Davi. Darei graças a Ti com todo o meu coração! Diante de deuses eu cantarei louvores a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Eu me prostrarei em direção ao Teu santo templo e darei graças ao Teu nome, por causa do Teu amor leal e da Tua verdade, pois magnificaste, acima de tudo, a Tua palavra e o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'No dia em que eu clamei a Ti, Tu me respondeste; Tu me encorajaste e fortificaste a minha alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Todos os reis da terra darão graças a Ti, Yahweh, porque eles ouvirão as palavras da Tua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'De fato, eles celebrarão os caminhos de Yahweh, porque grande é a glória de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Yahweh é supremo e, ainda assim, preocupa-Se com o humilde; mas o soberbo, Ele o conhece de longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Ainda que eu ande no meio ao perigo, Tu preservarás a minha vida; Tu estendes a Tua mão contra a raiva dos meus inimigos, e a Tua mão direita me salvará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Yahweh estará comigo até o fim; Teu amor leal, Yahweh, dura para sempre. Não abandones o que as Tuas mãos fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Ao regente musical. Salmo de Davi. Yahweh, Tu me examinas e me conheces.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Tu sabes quando me assento e quando me levanto; mesmo de longe, Tu conheces os meus pensamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Tu observas o meu andar e o meu deitar; Tu conheces todos os meus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'E antes que uma palavra chegue à minha língua, Tu já a conheces completamente, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Tu me cercas por trás e pela frente, e sobre mim colocas a Tua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Tal conhecimento é maravilhoso demais para mim; é muito elevado e não consigo alcançá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Para onde irei a fim de escapar do Teu Espírito? Para onde fugirei da Tua presença?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Se eu subir aos céus, Tu ali estás; se eu fizer minha cama no Sheol, Tu estás lá também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Se eu voar nas asas da manhã e habitar nos confins dos mares,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'ainda ali Tua mão me guiará; Tua mão direita me sustentará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Se eu disser: \"Certamente as trevas me encobrirão e a luz se tornará noite ao meu redor\",');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'nem mesmo a escuridão me esconderá de Ti. A noite resplandecerá como o dia, pois a escuridão e a luz são iguais para Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Tu formaste o meu interior; Tu me teceste no ventre de minha mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Eu Te darei graças, pois me formaste de um modo incrivelmente maravilhoso! Teus feitos são admiráveis e minha alma o sabe muito bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Meus ossos não estavam escondidos de Ti quando, em secreto, fui formado e tecido, como nas profundezas da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Tu me viste dentro do ventre, um ser ainda sem forma, e todos os dias determinados a mim já estavam escritos no Teu livro, mesmo antes de qualquer um deles existir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Quão preciosos são Teus pensamentos para comigo, ó Deus! Como é grande a soma deles!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Se eu tentasse contá-los, eles seriam mais numerosos do que a areia. E quando eu acordo, ainda estou Contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Quem dera matasses os perversos, ó Deus! Afastai-vos de mim, homens violentos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Eles falam contra Ti maliciosamente e tomam o Teu nome em vão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Não odeio aqueles que Te odeiam, Yahweh? Não odeio aqueles que se levantam contra Ti?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Eu os odeio profundamente; eles se tornaram meus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Examina-me, ó Deus, e conhece o meu coração; prova-me e conhece os meus pensamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Vê se existe alguma maldade em mim e me guia pelo caminho eterno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Ao regente musical. Salmo de Davi. Yahweh, salva-me do ímpio; preserva-me dos homens violentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Em seu coração, eles planejam o mal; eles provocam brigas todos os dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Sua língua fere como serpente; veneno de víboras está em seus lábios. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Livra-me das mãos dos ímpios, Yahweh; preserva-me dos homens violentos que planejam me derrubar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Os arrogantes prepararam uma armadilha para mim; estenderam-me uma rede; eles armaram uma cilada para mim. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Eu disse para Yahweh: Tu és o meu Deus! Escuta meu clamor por misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Yahweh, meu Senhor, Tu és poderoso para salvar-me; Tu proteges minha cabeça no dia da batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Yahweh, não concedas ao ímpio os seus desejos; não permitas que seus planos tenham êxito. Interlúdio');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Todos os que me cercam erguem a cabeça; deixa que a maldade dos seus lábios os cubra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Permite que as brasas quentes caiam sobre eles; lança-os dentro do fogo, dentro de poços sem fundo, para nunca mais se erguerem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Que os caluniadores não estejam seguros na terra; ao homem violento, que o mal o persiga e o derrube.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Eu sei que Yahweh julgará em favor do aflito, e que Ele exercerá justiça aos necessitados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Certamente, os justos darão graças ao Teu nome; os retos viverão na Tua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Salmo de Davi. Yahweh, eu clamo a Ti; vem rápido. Ouça-me quando eu chamo por Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Que minha oração seja como incenso perante Ti; que minhas mãos levantadas sejam como o sacrifício da tarde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Yahweh, coloca guarda sobre a minha boca; guarda a porta dos meus lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Não deixes que meu coração deseje nenhum mal, ou participe de atos pecaminosos junto aos ímpios. Não me deixes comer nenhuma das suas iguarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Deixa que o homem justo me bata; será uma bondade para mim. Deixa que ele me corrija; será como um óleo sobre minha cabeça; que minha mente não se recuse em aceitar, pois minha oração é sempre contra as práticas perversas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Seus líderes serão lançados do topo dos penhascos; eles ouvirão as minhas palavras, que são agradáveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Eles dirão: \"Como alguém que ara e lavra a terra, assim nossos ossos foram espalhados à boca do Sheol.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Certamente, meus olhos Te contemplam, Yahweh, Senhor Deus; em Ti me refugio; não deixes minha alma indefesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Protege-me das ciladas que armaram para mim, armadilhas dos malfeitores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Deixa os ímpios caírem nas suas próprias redes, enquanto eu escapo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Masquil de Davi, quando ele estava na caverna. Uma oração. Com minha voz, clamo a Yahweh; com minha voz suplico a Yahweh em meu favor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Coloco diante Dele o meu lamento; conto-Lhe as minhas tribulações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Quando meu espírito está fraco dentro de mim, Tu sabes o meu caminho. No caminho que ando, esconderam uma armadilha para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Olho para a minha direita e vejo que não há ninguém que se importe comigo. Não há saída para mim; ninguém se importa com a minha vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Clamei a Ti, Yahweh, e disse: \"Tu és o meu refúgio, minha porção na terra dos viventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Ouça o meu clamor, pois eu estou muito abatido; resgata-me dos meus perseguidores, pois são mais fortes do que eu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Tira a minha alma da prisão. Então, darei graças ao Teu nome. Os justos se juntarão à minha volta porque Tu tens sido bom para mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Salmo de Davi. Escuta minha oração, Yahweh; ouve minhas súplicas. Por causa da Tua fidelidade e justiça, responde-me!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Não entres em juízo com o Teu servo, pois à Tua vista ninguém é justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'O inimigo perseguiu a minha alma; ele me derrubou no chão; ele me fez viver nas trevas como aqueles que estão mortos há muito tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Meu espírito está desfalecido dentro de mim; meu coração se desespera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Trago à lembrança os dias antigos; medito em todas as Tuas obras; reflito nos Teus feitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Estendo minhas mãos a Ti em oração; minha alma tem sede de Ti como uma terra seca. (Selá.)');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Responde-me depressa, Yahweh, porque meu espírito desfalece. Não escondas a Tua face de mim, ou me tornarei como aqueles que descem à cova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Faze-me ouvir da Tua bondade pela manhã, pois eu confio em Ti. Mostra-me o caminho onde devo andar, pois elevo a minha alma a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Livra-me dos meus inimigos, Yahweh; eu me refugio em Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Ensina-me a fazer a Tua vontade, pois és meu Deus. Que Teu bom Espírito me guie na terra da retidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Yahweh, vivifica-me por amor do Teu nome; na Tua justiça, livra a minha alma da tribulação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Na Tua fidelidade, aniquila os meus adversários e destrói os meus inimigos, pois sou Teu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Salmo de Davi. Bendito seja Yahweh, minha Rocha, que treina as minhas mãos para a guerra, e os meus dedos para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Tu és o meu refúgio e a minha fortaleza; minha torre alta e meu libertador; meu escudo e Aquele em quem me refugio; Aquele que submete as nações a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Yahweh, o que é o homem para que Tu tomes conhecimento dele, ou o filho do homem, para que o consideres?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'O homem é como um sopro; seus dias são como a sombra que passa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Faz o céu baixar e descer, Yahweh; toca as montanhas e as faz fumegar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Envia relâmpagos e dispersa meus inimigos; atira Tuas flechas e faça com que eles fujam em confusão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Estende Tua mão do alto, e me resgata das muitas águas e da mão dos estrangeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Suas bocas falam mentiras, e sua mão direita é a destra da falsidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Cantarei um cântico novo a Ti, ó Deus; com a harpa de dez cordas, cantarei louvores a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Tu deste salvação aos reis; salvaste Davi, Teu servo, da espada maligna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Salva-me e livra-me das mãos dos estrangeiros; suas bocas falam mentiras, e sua destra é falsidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Que nossos filhos sejam como plantas crescidas na sua mocidade, e nossas filhas sejam como colunas angulares esculpidas, lavradas como as de um palácio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Que nossos celeiros estejam repletos de todos os tipos de mantimentos, e nossas ovelhas se reproduzam aos milhares e dezenas de milhares, em nossos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Então, nossos bois serão fortes para o trabalho. Ninguém invadirá nossos muros, e não haverá fugas e nem lamentações em nossas ruas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Feliz é o povo com tais bênçãos. Feliz é o povo que tem Yahweh como seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Salmo de louvor. De Davi. Eu te exaltarei, meu Deus, meu Rei; bendirei o Teu nome para todo o sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Todos os dias te bendirei e adorarei o Teu nome para todo o sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Grande é Yahweh e digno de ser louvado; Sua grandeza é insondável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Uma geração louvará os Teus feitos e a próxima proclamará os Teus atos poderosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Meditarei na majestade da Tua glória e em Tuas obras maravilhosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Elas proclamarão o poder dos Teus feitos tremendos, e eu declararei a Tua grandeza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Eles declararão a Tua grande bondade, e cantarão sobre a Tua justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Yahweh é gracioso e misericordioso, tardio em se irar e abundante em Sua bondade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Yahweh é bom para com todos; Suas ternas misericórdias estão em todos os Seus feitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Tudo o que Tu criaste te louvará, Yahweh; os Teus fiéis te bendirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Os Teus fiéis anunciarão a glória do Teu reino, e falarão do Teu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Farão conhecidos aos homens os feitos poderosos de Deus e o glorioso esplendor de Seu reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'O Teu reino é um reino eterno, e o Teu domínio dura por todas as gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Yahweh sustenta todos os que estão caídos e levanta todos aqueles que estão abatidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Os olhos de todos esperam por Ti; e Tu lhes dás comida no devido tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Abres a mão e satisfazes o desejo de todos os viventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Yahweh é justo em todos os Seus caminhos e gracioso em tudo o que faz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Yahweh está perto de todos aqueles que O invocam, de todos os que O invocam com sinceridade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Ele cumpre o desejo daqueles que O temem; Ele ouve seus clamores e os salva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Yahweh vela sobre todos aqueles que O amam, mas destruirá todos os ímpios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Minha boca proclamará o louvor de Yahweh. Que todos os homens bendigam Seu santo nome, para sempre e sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Louvado seja Yahweh. Louva, ó minha alma, a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Eu louvarei Yahweh enquanto eu viver; eu cantarei louvores ao meu Deus enquanto eu existir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Não deposites tua confiança em príncipes ou na humanidade, nos quais não há salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Quando o fôlego de vida de uma pessoa para, ela retorna ao pó; nesse dia, os planos terminam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Feliz é aquele que tiver o Deus de Jacó como auxílio, aquele cuja esperança está em Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Yahweh fez os céus e a terra, o mar e tudo o que neles há; Ele mantém Sua fidelidade para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Ele executa justiça aos oprimidos e alimenta os famintos. Yahweh liberta os prisioneiros;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Yahweh abre os olhos do cego; Yahweh eleva aqueles que foram humilhados; Yahweh ama as pessoas justas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Yahweh protege os estrangeiros na terra; Ele eleva os órfãos e as viúvas; Ele se opõe aos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Yahweh reinará para sempre; o teu Deus, ó Sião, reinará por todas as gerações. Louvai a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Louvai a Yahweh, porque é bom cantar louvores ao nosso Deus; é prazeroso e apropriado louvá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Yahweh edifica Jerusalém e reúne os dispersos do povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Ele cura os corações quebrantados e sara-lhes as feridas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Ele conta as estrelas e dá nome a todas elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Grande é o nosso Deus e maravilhoso em poder; Seu entendimento não pode ser medido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Yahweh restaura os oprimidos; Ele lança ao chão os perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Cantai para Yahweh com ações de graças; cantai louvores ao nosso Deus com a harpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Ele cobre os céus com nuvens e prepara chuva para a terra, fazendo com que a relva cresça nas montanhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Ele alimenta os animais e os filhotes dos corvos, quando choram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Ele não se deleita na força do cavalo; Ele não encontra prazer nos fortes músculos de um homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Yahweh tem prazer naqueles que O honram, que esperam em Sua bondade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Louvai a Yahweh, Jerusalém! Louvai a Yahweh, Sião!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Ele reforça as trancas de seus portões; Ele abençoa as crianças que habitam entre vós;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Ele traz paz para dentro de vossas fronteiras; Ele vos satisfaz com o melhor do trigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Ele envia Seus mandamentos à terra; Sua palavra corre com muita rapidez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Ele faz cair a neve como lã; Ele espalha a geada como cinzas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Ele lança o granizo como migalhas. Quem pode suportar o frio que Ele envia?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Ele envia Sua palavra e os faz derreter; Ele faz o vento soprar e as águas fluírem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Ele proclamou Sua palavra a Jacó, Seus estatutos e Seus justos decretos a Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Ele não fez isso com nenhuma outra nação e elas nada conhecem sobre os Seus decretos. Louvai a Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Aleluia! Louvai a Yahweh do alto dos céus; louvai-O nas alturas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Louvai-O, todos os Seus anjos, louvai-O, todos os Seus exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Louvai-O, sol e lua; louvai-O, todas as estrelas reluzentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Louvai-O, altos céus; e vós, águas que estão acima dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Louvai o nome de Yahweh, pois Ele ordenou, e foram criados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Ele também os estabeleceu para todo o sempre; Ele estabeleceu um decreto que nunca mudará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Louvai a Yahweh, toda a terra, monstros marinhos e todas as profundezas do oceano,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'fogo e granizo, neve e nuvens, ventos tempestuosos que obedecem à Sua palavra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'montanhas e todas as colinas, árvores frutíferas e todos os cedros,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'animais selvagens e domésticos, criaturas que rastejam e pássaros,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'reis da terra e todas as nações, príncipes e todos os que governam sobre a terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'moços e moças, anciãos e crianças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Todos vós, louvai o nome de Yahweh, pois somente o Seu nome é exaltado e a Sua glória se estende sobre a terra e os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Ele reforça o vigor do Seu povo, para o louvor dos Seus santos, os israelitas, povo que Lhe é íntimo. Louvai a Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Louvai a Yahweh. Cantai a Yahweh um novo cântico; cantai Seu louvor na assembleia dos santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Alegra-te, ó Israel, em teu Criador; regozijai-vos, filhos de Sião, em vosso Rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Adorai Seu nome com danças; cantai e louvai-O com tamborim e harpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Pois Yahweh tem prazer no Seu povo; Ele coroa o humilde com a salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Que os fiéis regozijem-se em vitória; que eles cantem de alegria em suas camas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Que os louvores a Deus estejam em suas bocas, e a espada de dois gumes, em suas mãos, para');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'executar vingança entre as nações e castigo sobre os povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Eles amarrarão seus reis com correntes e seus nobres com algemas de ferro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Eles executarão o julgamento que foi escrito. Isto será uma honra para todos os seus fiéis. Louvai a Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Louvai a Yahweh. Louvai a Deus em Seu santuário, louvai-O nos altos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Louvai-O pelos Seus atos grandiosos; louvai-O pela Sua imensa grandeza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Louvai-O com o sopro da trombeta; louvai-O com alaúde e harpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Louvai-O com tamborins e danças; louvai-O com instrumentos de cordas e de sopro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Louvai-O com címbalos sonoros; louvai-O com címbalos retumbantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Todo o ser que respira, louve a Yahweh. Louve a Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Provérbios de Salomão, filho de Davi, rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Estes provérbios são para ensinar a sabedoria e a instrução, para ensinar palavras de entendimento,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'para que recebas correção, de forma que faças o que é direito, justo e correto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Estes provérbios também são para dar sabedoria aos simples, entendimento e prudência aos jovens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Para que os sábios ouçam e aumentem seu aprendizado, e para que as pessoas com discernimento sejam guiadas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'para que entendam os provérbios, os dizeres e as palavras dos sábios, e seus enigmas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'O temor de Yahweh é o princípio do conhecimento, mas os tolos desprezam a sabedoria e a disciplina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Meu filho, ouve o ensino de teu pai e não desprezes a instrução de tua mãe;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'eles serão como uma coroa graciosa para a tua cabeça e colares para o teu pescoço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Meu filho, se pecadores tentarem te persuadir a pecar junto com eles, recusa-te a segui-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Se disserem: \"Vem conosco! Armemos uma emboscada para matar alguém; fiquemos escondidos e ataquemos um inocente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Vamos tragá-lo vivo, como a sepultura engole aqueles que estão saudáveis, como os que descem à cova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Encontraremos todo tipo de coisas valiosas, encheremos nossas casas com o que roubamos de outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Vem conosco! Teremos tudo em comum\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Meu filho, não andes neste caminho com eles, nem deixes teu pé tocar por onde eles passam;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Pois seus pés correm para o mal e eles se apressam em derramar sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'É inútil armar uma rede para pegar um pássaro enquanto o pássaro está atento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Esses homens, que ficam à espreita para se matarem, armam armadilhas para eles mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Assim são os caminhos de todo aquele que se enriquece com injustiça; o ganho injusto tira a vida daqueles que o buscam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'A sabedoria clama intensamente nas ruas e levanta a sua voz nas praças;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'nas esquinas tumultuadas, ela brada; nos portões da entrada da cidade, ela proclama:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, '\"Até quando, vós que não possuís sabedoria, continuareis a amar a tolice? Até quando, vós zombadores, vos deleitareis na zombaria, e até quando, vós tolos, odiareis o conhecimento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Prestai atenção na minha repreensão; Eu vos derramarei meus pensamentos e vos revelarei as minhas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Chamei, mas recusastes a me ouvir; estendi a minha mão e ninguém prestou atenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'Ignorastes toda a minha instrução e desconsiderastes a minha repreensão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Rirei na vossa calamidade, zombarei de vós quando o terror vier,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'quando o pavor vier como uma tempestade e o desastre varrer como um redemoinho, então, a angústia e a aflição cairão sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Clamareis a mim, e não responderei; Vós me procurareis desesperadamente, mas não me achareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Pois odiastes o conhecimento e não escolhestes o temor de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Não seguistes meus conselhos e desprezastes toda a minha repreensão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Comereis o fruto dos vossos caminhos e, com o fruto das vossas intrigas, vos enchereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Pois os ingênuos são mortos quando se desviam, e a prosperidade dos tolos os destruirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Mas aquele que ouvir a mim viverá em segurança e descansará tranquilo, sem temer o mal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Filho meu, se tu receberes minhas palavras e entesourares meus mandamentos contigo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'conserva teus ouvidos atentos à sabedoria e inclina teu coração ao entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Se clamares por entendimento e elevares tua voz por isso,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'se buscares isso como quem busca prata e, procurares entendimento como quem procura tesouros escondidos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'então, tu entenderás o temor de Yahweh e encontrarás o conhecimento de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Pois Yahweh dá sabedoria; de Sua boca, vêm conhecimento e entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Ele reserva a verdadeira sabedoria para aqueles que Lhe agradam; Ele é um escudo para os que andam em integridade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Ele guarda as veredas da justiça e preservará o caminho dos que são fiéis a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Então, tu entenderás a retidão, a justiça, a equidade e todo bom caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Pois a sabedoria entrará no teu coração, e o conhecimento será agradável à tua alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'O discernimento te vigiará, o entendimento te guardará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Eles te resgatarão do caminho do mal, daqueles que falam coisas perversas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'daqueles que abandonam os caminhos justos e andam nos caminhos da escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Esses se alegram em fazer o mal e deleitam-se nas perversidades da maldade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Eles seguem caminhos tortuosos e, usando o engano, escondem seus percursos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'A sabedoria e a discrição te salvarão da mulher adúltera, da mulher imoral e de suas palavras sedutoras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Ela abandona o companheiro de sua mocidade e se esquece da aliança de seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Pois a sua casa se inclina para a morte e as suas trilhas, para a sepultura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Todos os que se dirigirem a ela não retornarão, nem encontrarão os caminhos da vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Porém, tu andarás no caminho dos bons e seguirás as veredas dos justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Pois os que agem corretamente habitarão na terra e os íntegros nela permanecerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Mas os perversos serão eliminados da terra, e dela os infiéis serão arrancados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Meu filho, não te esqueças dos meus mandamentos e mantém meus ensinamentos em teu coração,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'para que longos dias, anos de vida e paz, lhe sejam acrescentados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Que a fidelidade e a lealdade à aliança jamais te abandonem; amarra-as ao teu pescoço e escreve-as na tábua do teu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Então, acharás favor e boa reputação perante os olhos de Deus e do homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Confia em Yahweh com todo o teu coração e não te apoies em teu próprio entendimento;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'reconhece-O em todos os teus caminhos e Ele fará retas as tuas veredas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Não sejas sábio aos teus próprios olhos, teme Yahweh e afasta-te do mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Isso será cura para tua carne e repouso para o teu corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Honra a Yahweh com tuas riquezas e com os primeiros frutos de toda a tua produção,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'e teus celeiros se encherão, e teus barris transbordarão de vinho novo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Meu filho, não desprezes a disciplina de Yahweh e não odeies Sua repreensão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'pois Yahweh disciplina a quem ama, como um pai lida com um filho que lhe agrada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Abençoado é aquele que encontra a sabedoria, este também alcança entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'O que tu ganhas com a sabedoria é melhor que a recompensa da prata e o seu lucro, melhor que o ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'A sabedoria é mais preciosa que joias e nada do que desejas se compara a ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Ela tem longevidade em sua mão direita; em sua mão esquerda, riquezas e honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Seus caminhos são caminhos de bondade e todas as suas veredas são de paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Ela é uma árvore de vida para aqueles que a pegam; aqueles que a mantêm são abençoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Pela sabedoria, Yahweh fundou a Terra; pelo entendimento, Ele estabeleceu os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Pelo Seu conhecimento, os abismos se abriram e as nuvens pingaram o seu orvalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Meu filho, mantém o bom senso e o discernimento, e não os perca de vista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'Eles serão vida para a tua alma e um adorno de favor para o teu pescoço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Então, andarás em segurança no teu caminho e teus pés não tropeçarão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'quando deitares, não terás medo; tu te deitarás e o teu sono será suave.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Não tenhas medo do terror repentino, nem da devastação causada pelo perverso quando ela vier,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'pois Yahweh estará ao teu lado e guardará os teus pés de serem pegos em uma armadilha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Não retenhas o bem aos que merecem, quando estiver em teu poder fazê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Não digas ao teu próximo: \"Vai e volta de novo, e amanhã te darei\", quando tiveres o dinheiro contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Não faças plano algum contra o teu próximo, que vive perto de ti e confia em ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Não brigues, sem razão, com alguém, quando este nada fez para prejudicar-te.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Não invejes o homem violento, nem escolhas nenhum de seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Pois o homem desonesto é detestável para Yahweh, mas Ele faz do justo o Seu confidente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'A maldição de Yahweh está sobre a casa do perverso, mas Ele abençoa a casa dos justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Ele faz de tolos os zombadores, mas concede o Seu favor aos humildes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Os sensatos herdarão honra, mas os tolos serão expostos em sua vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Escutai, filhos, a instrução do pai, e prestai atenção; assim conhecereis o que é o entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Estou vos dando boas instruções; não abandoneis o meu ensino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Quando eu era o menino do meu pai, o tenro e único filho da minha mãe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'ele me ensinava e me dizia: \"Que teu coração se agarre em minhas palavras; guarda meus mandamentos e vive.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Adquire sabedoria e entendimento; não te esqueças nem rejeites as palavras de minha boca;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'não abandones a sabedoria, e ela te protegerá; ama-a, e ela te manterá em segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'A sabedoria é a coisa mais importante. Portanto, adquire sabedoria e usa tudo o que possuis para adquirir o entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Valoriza a sabedoria e ela te exaltará; ela te honrará quando tu a abraçares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Ela colocará uma coroa de honra em tua cabeça; ela te dará um diadema de glória\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Ouve, meu filho, e presta atenção às minhas palavras, e tu terás muitos anos de vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Eu te conduzi no caminho da sabedoria; eu te guiei pelos caminhos justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Quando andares, ninguém impedirá os teus caminhos, e, se correres, tu não tropeçarás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Apega-te à instrução, não a soltes; guarda-a, pois ela é a tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Não sigas a vereda dos perversos e não andes pelo caminho dos que fazem o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Evita-o, não passes por ele; afasta-te dele e vai por outro caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Pois eles não conseguem dormir até que façam o mal, e seu sono é roubado até que façam alguém tropeçar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Pois eles comem o pão da maldade e bebem o vinho da violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Mas a vereda dos justos é como a primeira luz do dia, que tem brilho crescente; ela brilha mais e mais até que a plenitude do dia chegue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'O caminho dos perversos é como a escuridão; eles não sabem em que tropeçam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Meu filho, presta atenção às minhas palavras; inclina o teu ouvido aos meus dizeres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Que eles não se afastem de teus olhos; guarda-os em teu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Pois as minhas palavras são vida para aqueles que as encontram e saúde para o seu corpo inteiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Mantém o teu coração seguro e guarda-o com toda a diligência, porque dele fluem as fontes da vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Remove de ti as palavras falsas e afasta de ti a fala perversa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Que os teus olhos olhem para frente e fixa o teu olhar no que está diante de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Faz um trajeto reto para os teus pés; então, todos os teus caminhos estarão seguros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Não te desvies nem para a direita nem para a esquerda; afasta os teus pés do mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Meu filho, presta atenção à minha sabedoria; inclina os teus ouvidos ao meu entendimento,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'para que aprendas sobre a discrição, e teus lábios protejam o conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Pois os lábios da mulher adúltera destilam mel, e a sua boca é mais suave que o azeite,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'mas, no final, é amarga como o absinto, e afiada como a espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Seus pés descem à morte, seus passos levam para o caminho do Sheol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Ela não se preocupa com o rumo da vida; seus passos vagam, ela não sabe para onde vai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Agora, meus filhos, escutai a mim; não desvieis das palavras da minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Mantém o teu caminho longe dela, e não te aproximes da porta da sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Faz desta maneira para não acontecer que dês tua honra a outros, ou teus anos de vida a uma pessoa cruel;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'estranhos se fartem da tua riqueza; aquilo pelo qual trabalhaste vá para a casa de estranhos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'e, no fim da tua vida, gemas quando tua carne e corpo se esvaírem;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'e digas: \"Como odiei a disciplina e meu coração rejeitou a correção!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Não obedeci aos meus professores, nem inclinei os meus ouvidos aos que me instruíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Quase fui completamente arruinado no meio da assembleia, entre a congregação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Bebe água da tua própria cisterna, e água corrente do teu próprio poço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Por acaso, deveriam as tuas fontes se derramarem por todo lado, e teus ribeiros correrem em praça pública?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Sejam somente para ti, e não para estranhos contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Que a tua fonte seja abençoada, e alegra-te com a esposa da tua mocidade;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'porque ela é uma corça amorosa, uma gazela graciosa. Que os seios dela sempre te encham de prazer e tu estejas continuamente embriagado pelo seu amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Pois, por que tu, meu filho, serias cativado por uma adúltera? Por que abraçarias os seios de uma mulher imoral?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Yahweh vê tudo o que uma pessoa faz e observa todos os caminhos em que anda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'O corrupto será capturado por suas próprias iniquidades; as cordas do seu pecado o prenderão firmemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Ele morrerá por causa da sua falta de disciplina, e, pela sua insensatez, se desviará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Meu filho, se puseste o teu dinheiro como garantia do empréstimo que o teu próximo pediu, se deste a tua palavra para o empréstimo de alguém que não conheces,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'então, terás feito uma armadilha para ti mesmo por tua promessa, e tu foste pego pelas palavras de tua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Neste caso, meu filho, faz isto e livra-te, pois caíste nas mãos do teu próximo. Vai, humilha-te e defende o teu caso perante o teu próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Não dês aos teus olhos sono algum, e às tuas pálpebras, nenhum descanso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Livra-te como uma gazela das mãos do caçador, como um pássaro da mão do passarinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Olha para a formiga, preguiçoso, considera os caminhos dela, e sê sábio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Ela não tem comandante, oficial ou governante,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'contudo, prepara seu alimento no verão, e, durante a colheita, armazena o que irá comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Quanto tempo dormirás, preguiçoso? Quando levantarás do teu sono?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, '\"Um pouco mais de sono, um pouco mais de descanso, um pouco mais de braços cruzados para descansar\";');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'e a tua pobreza te alcançará como um ladrão e as tuas necessidades, como um soldado armado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'A pessoa inútil, o homem perverso, vive com um discurso tortuoso,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'piscando seus olhos, fazendo sinais com seus pés e apontando com seus dedos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Ele planeja o mal com o seu coração enganoso; ele sempre atiça a discórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Por isso, sua desgraça o alcançará em um instante; em um momento, ele será quebrado sem possibilidade de cura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Há seis coisas que Yahweh odeia, sete que são abomináveis a Ele:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'os olhos do orgulhoso, a língua que mente, as mãos que derramam sangue dos inocentes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'o coração que inventa planos perversos, os pés que correm apressadamente para fazer o mal,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'a testemunha que expira mentiras e aquele que semeia discórdia entre irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Meu filho, obedece ao mandamento de teu pai e não abandones o ensinamento de tua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Liga-os sempre ao teu coração; amarra-os ao redor do teu pescoço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Quando andares, eles te guiarão; quando dormires, eles zelarão por ti, e, quando acordares, eles te ensinarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Pois o mandamento é lâmpada, e o ensinamento é luz; as repreensões que vêm da disciplina são o caminho de vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Ela te preserva da mulher imoral, das suaves palavras da adúltera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Em teu coração, não cobice a sua beleza, e não sejas capturado por seus cílios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Dormir com uma prostituta pode custar-te um pedaço de pão, mas a esposa de outro pode custar a tua própria vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Por acaso pode um homem transportar fogo junto ao seu peito sem queimar as suas roupas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Pode um homem andar sobre brasas sem queimar seus pés?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Assim é o homem que dorme com a mulher do seu próximo; aquele que dormir com ela não ficará impune.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'As pessoas não desprezam um ladrão se ele furta para saciar sua necessidade, quando está faminto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Contudo, se for pego, pagará sete vezes o que furtou. Ele deverá entregar tudo de valor em sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Aquele que comete adultério não tem juízo; quem age assim destrói a si próprio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Feridas e vergonha são o que ele merece, e sua desgraça não se apagará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Pois o ciúme faz um homem ficar furioso; ele não mostrará nenhuma misericórdia quando se vingar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Ele não aceitará nenhuma compensação, e não poderá ser comprado, ainda que tu lhe ofereças muitos presentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Meu filho, guarda as minhas palavras e conserva os meus mandamentos contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Obedece aos meus mandamentos e vive; guarda a minha instrução como a menina dos teus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Amarra-os aos teus dedos; escreve-os na tábua do teu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Diz à sabedoria: \"És minha irmã\", e chama ao entendimento o teu parente,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'para te guardares da mulher adúltera, da mulher imoral e das suas suaves palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Da janela de minha casa, eu estava olhando através das grades,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'e, vendo os ingênuos, percebi, entre os jovens, um rapaz sem juízo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Aquele rapaz passou pela rua, perto da esquina dela, e foi em direção à sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'Era o crepúsculo, no final do dia, no tempo da noite e da escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Ali a mulher o encontrou, vestida como prostituta, com um coração enganoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Ela era barulhenta e teimosa, seus pés não paravam em casa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'ora nas ruas, ora no mercado, em toda esquina ela ficava à espreita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Então, ela o agarrou e o beijou e, atrevidamente, disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '\"Fiz minha oferta pacífica hoje, paguei os meus votos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Então, saí para encontrar-te, procurando, ansiosamente, o teu rosto, e te achei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Estendi cobertas em minha cama, lençóis coloridos do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Perfumei o meu leito com mirra, aloés e canela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Vem! Embriaguemo-nos de amor até o amanhecer; saciemo-nos fazendo amores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Pois meu marido não está em casa; ele foi fazer uma longa viagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Ele pegou uma bolsa com dinheiro e voltará no dia de lua cheia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Com seu falar sedutor, ela o persuadiu, e, com seus suaves lábios, o convenceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Imediatamente, ele a seguiu, como um boi que vai ao matadouro ou como um cervo pego em uma armadilha,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'até que uma flecha lhe perfure o fígado, ou como um pássaro que corre para o laço, sem saber que isso lhe custará a vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Agora, meus filhos, escutai-me, prestai atenção às palavras da minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Que teu coração não se desvie para os caminhos dela; não andes perdido em suas veredas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Ela já causou a queda de muitos; não são poucas as suas vítimas fatais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Sua casa está nos caminhos para o Sheol, que descem até as câmaras escuras da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Por acaso a sabedoria não está exclamando? O entendimento não está levantando a sua voz?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'No topo das colinas, ao lado da estrada, nas encruzilhadas, a sabedoria se posiciona.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Perto dos portões da entrada da cidade, à entrada dos portões, ela exclama:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, '\"Povo, é a vós que eu clamo; a minha voz é para os filhos dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Vós que sois ingênuos, aprendei a sabedoria; e vós que sois insensatos, acrescentai entendimento à vossa mente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Escutai, porque falarei de coisas nobres e, quando meus lábios se abrirem, direi coisas que são corretas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'pois minha boca fala o que é confiável e meus lábios odeiam a maldade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Todas as palavras da minha boca são justas, não há nada torcido ou enganoso nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Todas as minhas palavras são retas para aquele que as entende; minhas palavras são corretas para aqueles que acham o conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Escolhei a minha instrução acima da prata e o conhecimento mais do que o ouro puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Pois a sabedoria é melhor que joias; nenhum tesouro se compara a ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Eu, a sabedoria, vivo com a prudência, e possuo conhecimento e discrição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'O temor de Yahweh é odiar o mal; eu odeio o orgulho e a arrogância, o caminho maligno e o discurso perverso. Eu os odeio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Eu tenho o bom conselho e a verdadeira sabedoria; eu tenho discernimento e a força pertence a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Por mim, os reis reinam, e os governantes fazem leis que são justas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Por mim, os príncipes lideram e os nobres governam com justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Eu amo os que me amam, e encontram-me os que, diligentemente, me buscam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Comigo há riquezas, honra, fartura duradoura e justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Meu fruto é melhor que o ouro, melhor até mesmo que o ouro refinado; o que eu produzo é melhor do que a prata pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Eu ando no caminho que é correto, nas veredas que conduzem à justiça,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'para que eu dê uma herança aos que me amam e encha os seus tesouros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Yahweh me criou no princípio; antes de Seus feitos antigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Em eras passadas, fui feita, desde o princípio, desde o começo da Terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Antes que existissem os oceanos, eu fui gerada, antes que houvesse abundantes nascentes de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Antes que os montes fossem firmados, e antes das colinas, eu nasci.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Nasci antes que Yahweh tivesse feito a Terra ou os campos, ou mesmo a primeira poeira no mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Eu estava lá quando Ele estabeleceu os céus, quando Ele desenhou o horizonte sobre a superfície do abismo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Eu estava lá quando Ele estabeleceu as nuvens acima e quando as fontes do abismo foram firmadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Eu estava lá quando Ele fez o limite do mar, de modo que as águas não se espalhassem além de onde Ele as ordenou, e quando Ele pôs o limite dos fundamentos da terra seca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Eu estava ao Seu lado, como um mestre artesão; eu era Seu deleite dia após dia, sempre me alegrando diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Eu estava me alegrando em todo o Seu mundo, e meu deleite era nos filhos dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Agora, meus filhos, escutai-me, pois aqueles que mantêm meus caminhos serão benditos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Escutai a minha instrução e sede sábios; não a negligencieis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Aquele que me escuta será abençoado, vigiando a cada dia aos meus portões, esperando junto aos batentes das minhas portas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Pois quem quer que me encontre, encontra vida, e encontrará o favor de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Mas aquele que falhar, faz mal à sua própria vida; todos os que me odeiam amam a morte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'A sabedoria já edificou sua própria casa; ela talhou sete pilares de pedras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Ela já abateu seus animais para a refeição, misturou seu vinho e pôs a mesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Ela enviou convites com suas criadas e exclamou dos pontos mais altos da cidade:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '\"Vós que sois ingênuos, vinde para cá!\". Ela fala aos que não têm bom senso:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '\"Vinde! Comei da minha comida e bebei do vinho que misturei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Deixai vossas atitudes insensatas e vivei; andai no caminho do entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Quem corrige um zombador recebe afronta, e quem repreende uma pessoa maldosa recebe insultos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Não repreendas o zombador, ou ele te odiará; repreende o sábio, e ele te amará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Dá instrução a um sábio, e ele se tornará ainda mais sábio; ensina o justo, e ele crescerá em seu conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'O temor de Yahweh é o princípio da sabedoria, e o conhecimento do Santo é o entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Pois, através de Mim, teus dias serão multiplicados, e anos de vida te serão acrescentados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Se tu fores sábio, serás sábio para ti mesmo, mas, se tu fores zombador, suportarás isso sozinho”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'A insensatez é mulher ignorante; ela é indisciplinada e não sabe de nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Ela se assenta à porta de sua casa, toma um assento nos lugares altos da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Ela chama os que passam, aqueles que andam em linha reta em seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '\"Vinde aqui, vós que sois ingênuos!\", ela diz para aqueles que não têm sensatez:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '\"As águas roubadas são doces, e o pão comido em secreto é delicioso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Eles, porém, não sabem que a morte está ali, que seus convidados estão nas profundezas do mundo dos mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Provérbios de Salomão. Um filho sábio alegra o seu pai, mas um filho tolo traz aflição à sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Tesouros acumulados por meio de perversidade não têm valor, mas fazer o que é correto te livra da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Yahweh não deixa passar fome a alma do justo, mas frustra os desejos dos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'A mão preguiçosa faz a pessoa empobrecer, mas a mão do diligente ganha riquezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'O filho sábio ajunta a colheita no verão, mas aquele que dorme durante a colheita é vergonhoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Presentes de Deus estão sobre a cabeça do justo, mas a boca dos perversos encobre a violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'A pessoa justa faz tornarem-se felizes os que se lembram dela, mas o nome dos perversos apodrecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Aqueles que são sensíveis aceitam ordens, mas o tolo que fala muito irá à ruína.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Aquele que caminha em integridade caminha em segurança, mas aquele que faz seus caminhos tortos, este será descoberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Aquele que pisca o olho causa aflição, e o tolo que muito fala será derrubado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'A boca do justo é uma fonte de água de vida, mas a boca do perverso encobre a violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'O ódio provoca conflitos, mas o amor cobre todas as ofensas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'A sabedoria é achada nos lábios da pessoa que tem discernimento, mas a vara é para as costas daquele que não tem juízo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Os sábios acumulam conhecimento, mas a boca do tolo faz aproximar a destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'A riqueza do rico é sua cidade fortificada; a pobreza dos pobres é a sua miséria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'O salário do justo conduz à vida; o lucro dos perversos conduz ao pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Está no caminho para a vida os que seguem a disciplina, mas aquele que rejeita a repreensão se desvia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Quem esconde o ódio tem lábios mentirosos e o que espalha calúnias é tolo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Quando há muitas palavras, transgressão não falta, mas aquele que é cuidadoso com o que diz é sábio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'A língua do justo é prata pura; há pouco valor no coração do perverso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Os lábios do justo alimentam a muitos, mas os tolos morrem por causa da sua falta de bom senso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Os bons presentes de Yahweh trazem riqueza, sem dor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'A perversidade é um jogo que o tolo pratica, mas a sabedoria é prazer ao homem de entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'O medo do perverso virá sobre ele, mas o desejo dos justos será concedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Como a tempestade que passa, assim deixam de existir os perversos; mas o justo é como um fundamento que dura para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Como vinagre para os dentes e fumaça para os olhos, assim é o preguiçoso para aqueles que o enviam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'O temor a Yahweh prolonga a vida, mas os anos dos perversos serão curtos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'A esperança dos justos é sua alegria, mas a expectativa dos perversos perecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'O caminho de Yahweh protege os que possuem integridade, mas a destruição é para os perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'O justo nunca será derrotado, mas os perversos não permanecerão na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Da boca do justo sai o fruto de sabedoria, mas a língua perversa será cortada fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Os lábios do justo sabem o que é aceitável, mas da boca dos perversos só vêm más palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Yahweh odeia balanças que não são precisas, mas se alegra com um peso justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Quando vem o orgulho, vem a desgraça, mas com a humildade está a sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'A integridade dos justos os guia, mas as atitudes perversas dos traiçoeiros os destroem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'A riqueza é inútil no dia da ira, mas fazer o que é certo te protege da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'A conduta correta do inocente faz seu caminho reto, mas o perverso cairá por sua própria perversidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'A integridade daqueles que agradam a Deus os manterá seguros, mas os traiçoeiros cairão em suas próprias cobiças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Quando um homem perverso morre, sua esperança perece, e a esperança que estava em sua força se transforma em nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'O justo é mantido longe da angústia, e esta recai sobre o perverso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Com sua boca, o ímpio destrói o seu próximo, mas, por meio do conhecimento, os justos são mantidos em segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Quando os justos prosperam, a cidade se alegra; quando os perversos perecem, há gritos de júbilo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Através dos bons presentes dos que agradam a Deus, a cidade se torna grandiosa; pela boca dos perversos, a cidade é derrubada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'O homem que despreza seu amigo não tem bom senso, mas o homem de entendimento permanece quieto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Aquele que espalha calúnias revela segredos, mas a pessoa fiel mantém o segredo guardado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Quando não há direção sábia, a nação cai, mas a vitória vem por se consultar muitos conselheiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Aquele que se faz de fiador de empréstimo para um estranho, certamente, sofrerá, mas aquele que evita fazer parte desse tipo de promessa estará seguro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'A mulher graciosa é honrada, mas as pessoas impiedosas se agarram à riqueza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'A pessoa gentil beneficia a si mesma, mas aquele que é cruel machuca a si próprio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'O perverso mente para ganhar seu salário, mas aquele que semeia o que é justo colhe o salário da verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'A pessoa que faz o que é certo viverá, mas aquele que busca o mal morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Yahweh odeia aqueles cujos corações são perversos, mas se deleita nos que são inocentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Certamente, os perversos não passarão impunes, mas os descendentes dos justos serão mantidos seguros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'A mulher bonita, mas sem discrição, é como um anel de ouro no nariz de um porco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Os desejos dos justos resultam no bem, mas os perversos podem esperar somente a ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Existe aquele que espalha, e acumulará ainda mais; existe outro que retém o que deveria dar, e se dirige para a pobreza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'A pessoa generosa prosperará, e aquele que dá água aos outros terá água para si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'O povo amaldiçoa o que se recusa a vender grãos, mas bons presentes coroam a cabeça do que os vende.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Aquele que busca, diligentemente, o bem encontra o favor, mas aquele que busca o mal, este o achará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Os que confiam em suas próprias riquezas cairão, mas, à semelhança das folhas, os que fazem o bem florescerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'O que traz problemas à sua própria casa herdará o vento, e o tolo será servo do sábio de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'O fruto do justo será como uma árvore de vida, e aquele que é sábio cativa almas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Se o justo recebe o que merece, quanto mais o perverso e o pecador!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Aquele que ama a disciplina e o conhecimento, mas odeia a correção é estúpido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Yahweh concede favor ao homem bom, mas condena o homem que faz planos maus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Uma pessoa não pode se firmar pela maldade, mas os justos não podem ter suas raízes arrancadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Uma esposa digna é a coroa do seu marido, mas a que traz vergonha é como uma doença que lhe apodrece os ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Os planos dos justos são corretos, mas o conselho dos imorais é enganoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'As palavras dos corruptos são uma emboscada, esperando uma chance para matar, mas as palavras dos honestos os mantêm seguros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Os corruptos são derrubados e se vão, mas a casa dos justos se manterá em pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Uma pessoa é elogiada pela sabedoria que possui, mas o que faz escolhas perversas é desprezado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'É melhor ter uma posição sem importância — ser somente um servo — do que te gabares da tua importância, mas não tiveres nenhuma comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'O justo se importa com as necessidades do seu animal, mas até a compaixão do corrupto é falha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'O que lavra a sua terra terá abundância de comida, mas aquele que segue projetos inúteis não tem bom senso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'O corrupto deseja o que homens maus roubaram de outros, mas o fruto dos justos vem deles mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'A pessoa má se prende em sua conversa maliciosa, mas o justo escapa da angústia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Do fruto de suas palavras, uma pessoa se enche de boas coisas, assim como o trabalho de suas mãos a recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'O caminho do tolo é correto aos seus próprios olhos, mas o sábio ouve o conselho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'O tolo mostra a sua ira imediatamente, mas o que ignora um insulto é prudente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Aquele que fala a verdade diz o que é certo, mas a falsa testemunha diz mentiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'As palavras do que fala precipitadamente são como golpes de uma espada, mas a língua dos sábios traz cura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Os lábios verdadeiros duram para sempre, mas a língua mentirosa dura somente um momento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Há engano nos corações dos que planejam fazer o mal, mas a alegria vem para os conselheiros de paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Nenhum mal vem ao justo, mas os corruptos estão cheios de dificuldades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Yahweh odeia lábios mentirosos, mas os que vivem fielmente são Seu deleite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'O prudente esconde o seu conhecimento, mas o coração dos tolos exclama a insensatez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'As mãos dos diligentes governarão, mas os preguiçosos serão sujeitos ao trabalho forçado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'A ansiedade no coração de uma pessoa pesa sobre ela, mas uma boa palavra a alegra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'O justo é um guia para seu amigo, mas o caminho dos corruptos os desvia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'O preguiçoso não assará a sua caça, mas o diligente obterá preciosa riqueza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Na vereda da justiça está a vida, e no caminho da sua carreira não há morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'O filho sábio ouve a instrução do seu pai, mas o zombador não escuta a repreensão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Do fruto de sua boca, o homem desfruta de coisas boas, mas o apetite do traiçoeiro é para a violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Aquele que guarda a sua boca protege sua vida, mas o que abre muito seus lábios arruinará a si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'O desejo do preguiçoso anseia e nada ganha, mas a vontade dos diligentes será ricamente satisfeita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'O justo odeia mentiras, mas o perverso torna-se repugnante, e o que faz é vergonhoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'A justiça protege aqueles que são irrepreensíveis em seus caminhos, mas a perversidade desvia os pecadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Há quem diz ser rico, mas nada tem; há outro que entrega tudo o que tem, mas é, verdadeiramente, rico.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'O resgate da vida de um homem rico é a sua fortuna, mas um homem pobre não escuta a ameaça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'A luz dos justos resplandece, mas a lâmpada dos perversos será apagada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'O orgulho só produz contenda, mas a sabedoria está com aqueles que ouvem bons conselhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'As riquezas são diminuídas quando há excesso de vaidade, mas aquele que ganha trabalhando com as suas mãos fará seu dinheiro aumentar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Quando a esperança é adiada, faz adoecer o coração, mas o desejo realizado é árvore de vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Aquele que despreza a instrução trará destruição a si mesmo, mas quem honra o mandamento será recompensado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'O ensino de uma pessoa sábia é fonte de vida que afasta dos laços da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'O bom conhecimento conquista favor, mas o caminho dos desleais é intransitável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'As pessoas prudentes agem com conhecimento em todas as suas decisões, mas o tolo expõe sua insensatez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'O mensageiro perverso cai em problemas, mas o enviado fiel traz reconciliação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Quem ignora a disciplina terá pobreza e vergonha, mas a honra virá para aquele que aprende com a correção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Um desejo realizado é doce para a alma, mas os tolos odeiam afastar-se do mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Caminha com pessoas sábias e tu serás sábio, mas o companheiro dos tolos sofrerá dano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'O desastre corre atrás dos pecadores, mas os justos são recompensados com o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Uma boa pessoa deixa herança para seus netos, mas a riqueza do pecador é armazenada para a pessoa justa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Um campo não arado na propriedade dos pobres poderia produzir muito alimento, mas é destruído pela injustiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Aquele que não disciplina seu filho o odeia, mas aquele que ama seu filho tem o cuidado de discipliná-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'O justo come até satisfazer o seu apetite, mas o estômago dos ímpios está sempre com fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'A mulher sábia constrói a sua casa, mas a mulher tola a destrói com suas próprias mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'O que anda em retidão teme a Yahweh, mas o que é desonesto em seus caminhos O despreza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Na boca do tolo está a vara do seu orgulho, mas a boca do sábio o preservará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Onde não há boi, o celeiro fica limpo, mas uma colheita abundante pode vir pela força de um boi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Uma testemunha verdadeira não mentirá, mas a falsa testemunha respira mentiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'O zombador procura sabedoria e não a encontra, mas o conhecimento vem fácil ao prudente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Foge da presença do homem insensato, pois tu não acharás conhecimento em seus lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'A sabedoria do prudente é entender seu próprio caminho, mas a tolice do tolo é engano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Tolos zombam quando o sacrifício de culpa é oferecido, mas, entre os justos, o favor é boa vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'O coração conhece sua própria amargura e nenhum estranho partilha de sua alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'A casa dos perversos será destruída, mas a tenda dos justos florescerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Há um caminho que parece correto aos olhos do homem, mas o fim dele leva à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Até no riso tem dor o coração, e o fim da alegria é a tristeza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'O que não é fiel terá aquilo que merece, mas uma pessoa boa terá o que é seu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'O homem que não foi ensinado acredita em tudo, mas o prudente pensa em seus passos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'O sábio teme e se afasta do mal, mas o tolo rejeita, confiantemente, um aviso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'O que se ira com facilidade cometerá erros, e o que planeja o mal será odiado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Os ingênuos herdam a tolice, mas os prudentes são coroados de conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Os maus se curvarão diante dos bons, e os perversos se curvarão aos portões dos justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'O pobre é odiado até pelos próprios vizinhos, mas o rico tem muitos amigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'O que mostra desprezo pelo seu vizinho está pecando, mas o que favorece o pobre encontra a felicidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Acaso, os que planejam o mal não erram? Mas aqueles que planejam fazer o bem receberão um compromisso de fidelidade e confiança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Em todo o trabalho, haverá proveito, mas, quando só há conversa, isto leva à pobreza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'A coroa dos sábios é a sua riqueza, mas a loucura dos tolos só traz mais insensatez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Uma testemunha verdadeira salva vidas, mas a falsa testemunha respira mentiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'No temor de Yahweh, o homem forte tem esperança, e seus filhos terão local de proteção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'O temor de Yahweh é fonte de vida que afasta o homem dos laços da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'A glória do rei é achada no grande número de seu povo, mas sem o povo o príncipe está arruinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'O paciente tem grande entendimento, mas o precipitado exalta a tolice.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Um coração tranquilo é vida para o corpo, mas a inveja apodrece os ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'O que oprime o pobre insulta o seu Criador, mas o que favorece o necessitado O honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'O perverso cai pela sua má conduta, mas o justo tem refúgio mesmo na sua morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'A sabedoria repousa no coração do prudente, mas o que existe no coração dos tolos será conhecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Fazer o que é correto exalta uma nação, mas o pecado é a vergonha para qualquer povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'O favor do rei é com o servo que age com sabedoria, mas sua ira será para aquele que age vergonhosamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'A resposta suave afasta a ira, mas a palavra áspera atiça a raiva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'A língua dos sábios honra o conhecimento, mas a boca dos tolos derrama loucura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Os olhos de Yahweh estão por toda parte, observando os maus e os bons.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'A língua que cura é uma árvore de vida, mas a língua enganadora esmaga o espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'O tolo despreza a disciplina de seu pai, mas aquele que aprende com a correção é prudente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Na casa do justo, há um grande tesouro, mas os ganhos do ímpio lhe trazem aflições.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Os lábios dos sábios espalham conhecimento, mas o coração dos tolos nada oferece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Yahweh odeia os sacrifícios dos corruptos, mas a oração dos justos é Seu deleite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Yahweh odeia o caminho dos corruptos, mas Ele ama os que buscam o que é correto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Haverá dura disciplina para qualquer um que abandonar o caminho, e o que odeia a correção morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'O Sheol e a destruição estão abertos diante de Yahweh, quanto mais o coração dos filhos dos homens!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'O escarnecedor se ofende com a correção; ele não vai ao encontro do sábio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'O coração feliz torna o rosto alegre, mas a dor do coração esmaga o espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'O coração do que entende procura conhecimento, mas a boca dos tolos se alimenta de loucura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Todos os dias dos oprimidos são miseráveis, mas o coração alegre tem um banquete interminável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Melhor é o pouco com temor a Yahweh, do que um grande tesouro com inquietação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Melhor é uma refeição com verduras onde há amor que um boi cevado acompanhado de ódio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'O homem com raiva atiça brigas, mas o que demora a irar-se acalma as desavenças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'O caminho do preguiçoso é como um lugar cheio de espinhos, mas o caminho dos justos é uma estrada plana.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'O filho sábio traz alegria ao seu pai, mas o tolo despreza sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'A insensatez diverte a pessoa que carece de bom senso, mas aquele que tem entendimento anda pelo caminho reto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Os planos falham onde não há conselho, mas, com muitos conselheiros, os planos têm êxito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'A pessoa encontra alegria quando dá uma resposta pertinente; quão boa é uma palavra no tempo certo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'O caminho da vida leva o prudente para cima, para que ele se afaste do Sheol, que fica abaixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Yahweh derruba a casa dos orgulhosos, mas protege a propriedade da viúva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Yahweh odeia os pensamentos dos corruptos, mas as palavras de bondade são puras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'O ladrão traz problema para sua família, mas aquele que odeia os subornos viverá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'O coração do justo pensa antes de responder, mas a boca dos corruptos derrama toda a sua maldade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Yahweh está longe dos corruptos, mas ouve a oração dos justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'A luz dos olhos traz alegria ao coração, e as boas notícias são saúde para o corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Se prestares atenção quando alguém te corrige acerca de como vives, permanecerás entre os sábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Aquele que rejeita a disciplina despreza a si mesmo, mas aquele que escuta a correção ganha entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'O temor a Yahweh ensina sabedoria, e a humildade vem antes da honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Os planos do coração pertencem ao homem, mas a resposta da língua vem de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Todos os caminhos de uma pessoa são puros ao seus próprios olhos, mas Yahweh pesa o espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Submete os teus trabalhos a Yahweh, e teus planos serão bem sucedidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Yahweh fez tudo para o Seu propósito, até os homens maus para o dia da tribulação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Yahweh odeia todos os que têm um coração arrogante. Certamente, eles não ficarão impunes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Pela fidelidade à aliança, pela lealdade a ela, a iniquidade é expiada e, pelo temor a Yahweh, as pessoas se afastam do mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Quando os caminhos de uma pessoa são agradáveis a Yahweh, Ele faz com que até seus inimigos tenham paz com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Melhor é ter pouco de uma forma correta que muito rendimento com injustiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'No coração, uma pessoa planeja seu caminho, mas Yahweh dirige seus passos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Decisões de autoridade estão nos lábios de um rei; sua boca não deve trair a justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'As balanças honestas vêm de Yahweh; todos os pesos da bolsa são obra Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Praticar a perversidade é desprezível para os reis, pois o trono é estabelecido por fazer o que é certo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Um rei tem prazer em lábios que falam o que é correto, e ama aquele que fala a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'A fúria de um rei é um mensageiro da morte, mas o homem sábio tentará aplacar a sua ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Na luz da face de um rei está a vida, e o seu favor é como a nuvem que traz uma chuva da primavera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'É melhor adquirir sabedoria que ouro. Obter entendimento deve ser preferível à prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'A estrada das pessoas corretas as afasta do mal; aquele que protege a sua vida guarda o seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'O orgulho vem antes da destruição, e o espírito altivo, antes da queda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'É melhor ser humilde entre os pobres que dividir os despojos com os orgulhosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Quem considera atentamente o que lhe é ensinado encontra o que é bom, e aqueles que confiam em Yahweh serão abençoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Aquele que é sábio de coração é chamado de prudente; a doçura da voz melhora a capacidade de ensinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'O entendimento é uma fonte de vida para aqueles que o têm, mas a correção dos tolos é a sua própria tolice.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'O coração da pessoa sensata instrui a sua boca e acrescenta conhecimento aos seus lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'As palavras agradáveis são como um favo de mel — doçura para a alma e cura para os ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Há caminho que parece correto para o homem, mas o seu fim é caminho para a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'O apetite do trabalhador trabalha por ele, pois a sua fome o motiva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'A pessoa inútil escava o problema, e seu discurso é como fogo abrasador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'O perverso semeia o conflito; quem espalha boatos separa amigos próximos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Um homem de violência mente ao seu próximo e o conduz para um caminho que não é bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Aquele que pisca o olho trama perversidades; aquele que morde os lábios fará o mal acontecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Os cabelos grisalhos são uma coroa de glória que se ganha vivendo de maneira correta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'É melhor ser lento para irar-se que ser um guerreiro; quem domina seu espírito é mais forte do que aquele que conquista uma cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'As sortes são lançada no colo, mas a decisão vem de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'É melhor ter tranquilidade com um pedaço de pão seco que uma casa cheia de banquetes e conflitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'O servo sábio governará sobre o filho que age vergonhosamente, e terá parte na herança como um dos filhos de seu senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'O crisol é para a prata, e a fornalha é para o ouro, mas Yahweh refina os corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'A pessoa que faz o mal presta atenção aos lábios maliciosos; o mentiroso dá ouvidos à língua destruidora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Quem zomba do pobre insulta ao seu Criador, e aquele que se regozija com a desgraça não ficará sem punição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Os netos são a coroa dos idosos e os pais trazem honra a seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'O discurso eloquente não é apropriado ao tolo; muito menos os lábios mentirosos à realeza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'O suborno é como uma pedra mágica para aquele que o oferece; para onde quer que ele se volte, será bem sucedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Quem decide ignorar a ofensa busca o amor, mas aquele que repete o assunto separa amigos íntimos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Uma repreensão penetra mais fundo na pessoa que tem entendimento do que cem golpes num tolo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Uma pessoa má busca apenas a rebelião, por isso, um mensageiro cruel será enviado contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'É melhor encontrar-se com uma ursa roubada dos seus filhotes que com um tolo na sua insensatez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Quando alguém retribui o bem com o mal, o mal nunca deixará a sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'O começo do conflito é como aquele que libera água por todo lugar; portanto, foge da disputa antes que ela se inicie.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Aquele que absolve o ímpio e aquele que condena o justo — ambos são abominação a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Por que o tolo pagaria para aprender a sabedoria se ele não tem capacidade de aprendê-la?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'O amigo ama em todo o tempo, e um irmão nasce nos tempos de dificuldades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'O homem que não tem juízo faz promessas que impõem obrigações a si mesmo, e torna-se responsável pelas dívidas de seu próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Aquele que ama o conflito ama o pecado; aquele que faz muito alta a soleira da sua porta causa ossos quebrados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'A pessoa que tem o coração corrupto não encontra nada de bom; aquele que tem a língua perversa cai na calamidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Aquele que gera um tolo traz sofrimento a si mesmo; quem quer que seja pai de um insensato não terá alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'O coração alegre é um bom remédio, mas o espírito abatido seca os ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'O homem perverso aceita o suborno secreto para perverter os caminhos da justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Aquele que tem entendimento volta o seu rosto para a sabedoria, mas os olhos do tolo perdem-se nos confins da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'O filho tolo é o sofrimento do seu pai e a amargura da mãe que o gerou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Nunca é bom punir o justo, nem açoitar os nobres que têm integridade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Aquele que tem conhecimento usa poucas palavras, e aquele com entendimento tem um temperamento equilibrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Até um tolo é tido por sábio quando fica calado; se mantém a boca fechada, ele é considerado inteligente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Aquele que se isola busca seu próprio desejo, e luta contra todo o bom senso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'O tolo não encontra satisfação no entendimento, mas apenas em revelar o que está em seu próprio coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Quanto ao ímpio, o desprezo vem com ele — juntamente com a vergonha e a repreensão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'As palavras da boca de um homem são águas profundas; a fonte da sabedoria é um ribeiro corrente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Não é bom ser parcial com o perverso, nem negar justiça ao justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Os lábios do tolo trazem-lhe conflito, e a sua boca convida o golpe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'A boca do tolo é a sua ruína, e ele é pego na armadilha dos seus lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'As palavras do difamador são como deliciosos pedaços de comida que descem para as partes internas do corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Quem é desleixado em seu trabalho é um irmão para aquele que o destrói.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'O nome de Yahweh é uma torre forte; o justo corre para ela e fica seguro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'A riqueza do rico é a sua cidade fortificada e, em sua imaginação, é como um muro alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'O orgulho precede a ruína, a humildade vem antes da honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Aquele que responde antes de ouvir mostra insensatez e passa vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'O espírito de uma pessoa sobreviverá à doença, mas um espírito abatido, quem o pode suportar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'O coração do inteligente adquire conhecimento, e o ouvido do sábio o buscará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'O presente que homem der pode abrir-lhe o caminho, e trazê-lo até uma pessoa importante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'O primeiro a defender seu caso parece correto até que seu oponente venha e o questione.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Lançar a sorte faz cessar disputas e separa fortes oponentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Um irmão ofendido é mais difícil de conquistar que uma cidade forte, e a desavença é como as barras de um castelo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'O estômago de cada um é cheio do fruto de sua boca; da colheita dos seus lábios, ele fica satisfeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'A morte e a vida são controladas pela língua, e aqueles que a amam comerão do seu fruto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Aquele que encontra uma esposa encontra um bem, e alcança a benevolência de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'O pobre implora por misericórdia, mas o rico responde duramente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Aquele que acredita ter muitos amigos é levado à ruína por eles, mas há amigo que está mais próximo que um irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Melhor é o pobre que anda em sua integridade que o tolo que fala de modo perverso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Não é bom ter desejo sem conhecimento, e aquele que corre muito rápido perde o caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'É a insensatez de uma pessoa que arruína sua vida, mas seu coração se irrita contra Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'A riqueza traz muitos amigos; mas o pobre é deixado por seus amigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'A falsa testemunha não ficará impune, e aquele que despeja mentiras não escapará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Muitos pedirão favor à pessoa generosa, e todos são amigos daquele que dá presentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Se até os irmãos do pobre o odeiam, quanto mais os seus amigos se afastarão dele! Ele os chama, mas já foram embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Aquele que obtém sabedoria ama sua própria vida; aquele que guarda o conhecimento achará o que é bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'A falsa testemunha não sairá impune; aquele que fala mentiras perecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Não é adequado que o tolo viva no luxo; muito menos que o escravo domine príncipes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'A discrição faz a pessoa não perder a calma, e a sua glória é ignorar a ofensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'A ira do rei é como o bramido de um leão jovem, mas seu favor é como orvalho sobre a relva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'O filho tolo é a ruína do seu pai, e a esposa rixosa é uma goteira constante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'A casa e a riqueza são heranças dos pais, mas a esposa prudente vem de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'A preguiça lança a pessoa para um sono profundo, mas aquele que não é disposto a trabalhar terá fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Aquele que obedece ao mandamento guarda sua vida, mas a pessoa que não pensa a respeito de seus caminhos morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Quem é benevolente com os pobres empresta a Yahweh, e Ele lhe retribuirá pelo que houver feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Disciplina teu filho enquanto há esperança, não queiras levá-lo à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'A pessoa de temperamento forte deve pagar a pena; se tu o resgatares, terás que fazê-lo uma segunda vez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Escuta o conselho e aceita a instrução, para te tornares sábio ao fim de tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Muitos são os planos no coração da pessoa, mas é o propósito de Yahweh que permanecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'A lealdade é o que uma pessoa deseja, e um pobre é melhor que um mentiroso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'O temor a Yahweh leva pessoas à vida; aquele que o tiver estará satisfeito e não afligido pelo perigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'O preguiçoso põe a sua mão no prato, mas nem a levará de volta à boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Golpeia o zombador, e o ingênuo se tornará prudente; corrige o que tem discernimento, e ele ganhará conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Aquele que rouba seu pai e faz sua mãe fugir é o filho que traz vergonha e reprovação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Se parares de ouvir a instrução, meu filho, então, te desviarás das palavras de conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'A testemunha corrupta zomba da justiça, e a boca dos ímpios engole iniquidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'A condenação está preparada para os zombadores, e os açoites, para as costas dos tolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'O vinho é zombador e a bebida forte é briguenta; quem se deixar desviar por eles não é sábio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'O furor de um rei é como o rugido de um leão jovem; quem lhe provoca a ira peca contra a própria vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'É uma honra para alguém evitar o conflito, mas os tolos saltam para dentro da briga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'O preguiçoso não lavra no outono; ele busca a produção na estação da colheita, mas não terá nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'O propósito que está no coração humano é como águas profundas, mas a pessoa com entendimento trará isso para fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Muitas pessoas proclamam que são leais, mas quem achará alguém que seja fiel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'O justo caminha em sua integridade, seus filhos serão felizes se o seguirem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Um rei que se assenta no trono para julgar separa todo o mal que está diante dos seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Quem pode dizer: \"Eu mantenho o meu coração puro; estou limpo do meu pecado\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Pesos diferenciados e medidas desiguais; Yahweh odeia ambos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Até um jovem é conhecido por suas ações, se a sua conduta for pura e correta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Ouvidos que ouvem e olhos que veem, Yahweh fez ambos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Não ames dormir ou tu ficarás pobre; abre os teus olhos e tu terás muito para comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, '\"Ruim! Ruim!\" diz o comprador, mas, quando vai embora, se gaba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Há ouro e pedras preciosas em abundância, mas os lábios de conhecimento são uma joia preciosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Pega a roupa daquele que se fez fiador da dívida de um estranho; que ela sirva de penhor por ele garantir a dívida de quem não conhece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'O pão adquirido por meio do engano tem sabor doce, mas, depois, sua boca se encherá de pedrinhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Os planos são estabelecidos por meio de conselho e, somente com orientação sábia, deve-se fazer guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'O mexeriqueiro revela segredos; por isso, não te associes com pessoas que falam demais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Se uma pessoa amaldiçoa seu pai ou sua mãe, sua lâmpada será apagada no meio das trevas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Uma herança recebida antecipadamente não será uma bênção no final.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Não digas: \"Eu te retribuirei por esse mal!\". Espera por Yahweh, e Ele te resgatará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Yahweh odeia pesos desiguais; Ele não Se agrada de balanças desonestas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Os passos de uma pessoa são direcionados por Yahweh; como, então, ela poderá entender o seu caminho?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'É uma armadilha falar precipitadamente: “Está consagrado a Deus\", e pensar sobre o que isso significa somente depois de ter feito seu voto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'O rei sábio espalha os perversos e, depois, faz passar a roda sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'O espírito humano é a lâmpada de Yahweh, que busca o mais íntimo do coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'A piedade e a lealdade preservam o rei; o seu trono é assegurado pelo amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'A glória do jovem está na sua força, e o esplendor dos idosos, em seus cabelos grisalhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Pancadas que fazem uma ferida purificam do mal, e golpes limpam o mais íntimo do corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'O coração do rei é uma corrente de água na mão de Yahweh; Ele o dirige para onde deseja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'O caminho de cada um parece correto aos seus próprios olhos, mas é Yahweh que sonda os corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Fazer o que é correto e justo é mais aceitável para Yahweh do que o sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Os olhos altivos e o coração orgulhoso — a lâmpada dos corruptos — são pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Os planos do diligente, certamente, conduzem à prosperidade, mas quem se apressa excessivamente se dirige à pobreza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Adquirir riquezas por meio da língua mentirosa é neblina passageira e um laço que mata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'A violência dos maus os varrerá, porque se recusam a fazer o que é justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'O caminho do culpado é tortuoso, mas aquele que é puro faz o que é correto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'É melhor viver num canto do terraço que na casa compartilhada com uma esposa briguenta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'O coração dos corruptos anseia o mal; seu vizinho não acha favor em seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Quando o zombador é punido, o simples se torna sábio, e quando o sábio é instruído, ele recebe o conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Deus, o Justo, observa a casa do corrupto e leva os maus à ruína.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Aquele que tapa os ouvidos ao clamor do pobre também clamará, mas não será ouvido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Um presente entregue em secreto abranda a ira, um presente às escondidas aplaca o grande furor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Quando a justiça é feita, ela traz alegria ao justo, mas traz terror para os malfeitores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Aquele que vagueia afastando-se do caminho do entendimento descansará na assembleia dos mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Quem ama o prazer se tornará pobre; aquele que ama o vinho e o azeite não será rico.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'O corrupto é a redenção para o justo, e o traiçoeiro é a redenção para os que são corretos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'É melhor viver no deserto do que com uma esposa briguenta e raivosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Há azeite e tesouro precioso na casa do sábio, mas o homem insensato os devora por completo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Aquele que pratica o que é justo e é benevolente encontra vida, justiça e honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'O homem sábio escala a cidade dos poderosos e derruba a fortaleza em que confiavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Quem guarda sua boca e sua língua mantém-se longe de aflições.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'O orgulhoso e altivo — cujo nome é \"Zombador\" — atua com orgulho arrogante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'O desejo do preguiçoso o mata, porque as suas mãos se recusam a trabalhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Todo o dia, ele anseia por mais e mais, mas aquele que é justo dá e não retém para si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'O sacrifício do corrupto já é detestável; torna-se mais ainda quando é oferecido com intenções malignas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'A falsa testemunha perecerá, mas aquele que escuta falará por todo o tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'O homem mau se mostra com uma face dura, mas a pessoa correta tem certeza de seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Não há sabedoria, nem entendimento, nem conselho que possa permanecer contra Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'O cavalo é preparado para o dia da batalha, mas a vitória vem de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'O bom nome vale mais que grandes riquezas e o favor é melhor que prata e ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Ricos e pobres têm algo em comum: Yahweh é o Criador de todos eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Um homem prudente percebe o perigo e se esconde, mas o tolo avança e sofre por isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'A recompensa da humildade e do temor de Yahweh são riquezas, honra e vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Espinhos e laços se encontram no caminho do perverso; quem guarda sua vida se manterá longe deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Ensina a criança no caminho em que deve andar e, quando envelhecer, não se desviará dessa instrução.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Os ricos governam sobre os pobres e o que pega emprestado é escravo daquele que lhe empresta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Quem semeia injustiça colherá problemas e a vara de sua fúria desaparecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Aquele que tem olhos generosos será abençoado, pois compartilha do seu pão com os pobres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Afasta o zombador e a contenda acabará, as disputas e os insultos cessarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Aquele que ama um coração puro e cujo discurso é gracioso terá o rei como seu amigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Os olhos de Yahweh preservam o conhecimento, mas as palavras do traiçoeiro, Ele as derruba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'O preguiçoso diz: \"Há um leão na rua! Se eu sair, serei morto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'A boca da mulher adúltera é um poço profundo; aquele que está sob a ira de Yahweh cairá nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'A tolice está ligada ao coração da criança, mas a vara da disciplina a afastará dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Aquele que oprime os pobres para aumentar sua riqueza, ou presenteia os ricos, empobrecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Inclina o teu ouvido e escuta as palavras dos sábios e aplica o teu coração ao meu conhecimento,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'pois será agradável para ti mantê-las em teu interior e estarem todas prontas em teus lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Para que a tua confiança esteja em Yahweh, eu as ensino hoje, a ti mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Já não te escrevi trinta ditados de instrução e conhecimento,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'para te ensinar a verdade nessas palavras de confiança, para que dês respostas confiáveis a quem te enviou?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Não roubes o pobre, porque ele é pobre, nem esmagues o aflito no portão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'pois Yahweh defenderá a causa deles e tirará a vida de quem os roubar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Não sejas amigo de alguém que é dominado pela raiva e não andes com quem se enfurece,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'para que tu não aprendas seus costumes, nem tua alma se envolva em alguma armadilha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Não sejas aquele que logo aperta as mãos fazendo promessa, nem aquele que fica por fiador de dívidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Se tu não tens como pagar, o que impediria alguém de tirar a tua cama debaixo de ti?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Não removas o limite de pedra antigo que teus pais fixaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Já observaste um homem habilidoso em seu trabalho? Ele estará diante de reis, não no meio de pessoas comuns.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Quando te assentares para comer com um governador, observa cuidadosamente o que está diante de ti,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'e coloca uma faca contra tua garganta, se tu fores uma pessoa que gosta de comer muita comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Não desejes as delícias dele, porque é a comida das mentiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Não trabalhes excessivamente para ganhar riqueza; sê sábio o suficiente para saber quando parar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Por acaso, farás teus olhos brilharem pelo que, certamente, cria asas como a águia e sai voando pelo céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Não comas a comida daquele que tem o olho mau, nem desejes suas delícias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'porque ele é o tipo de homem que conta o preço da comida. \"Come e bebe!\", ele te diz, mas o coração dele não está contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Tu vomitarás o pouco que comeste e terás desperdiçado teus elogios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Não fales aos ouvidos de um tolo, porque ele desprezará a sabedoria de tuas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Não movas nenhuma pedra de limite antiga, nem invadas os campos dos órfãos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'porque o seu Redentor é forte, e Ele defenderá a causa deles contra ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Aplica o teu coração à instrução e os teus ouvidos, às palavras de conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Não negues disciplina à criança, pois, se tu a castigares com uma vara, ela não morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Bata-lhe com uma vara, e salvarás a alma dela do Sheol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Meu filho, se o teu coração for sábio, então, o meu coração também estará contente;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'meu íntimo se alegrará quando os teus lábios falarem o que é correto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Que o teu coração não inveje os pecadores, mas continue no temor a Yahweh o dia todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Certamente, há um futuro e a tua esperança não será eliminada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Escuta, meu filho — tu mesmo! — sê sábio e dirige o teu coração no caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Não te associes com os bêbados ou com os gulosos, comilões de carne,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'pois bêbados e gulosos ficam pobres, e a sonolência os vestirá com trapos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Escuta o teu pai, que te gerou, e não desprezes a tua mãe quando ela estiver velha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Compra a verdade, mas não a vendas; compra sabedoria, instrução e entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'O pai do justo grandemente se alegrará, e aquele que gera um filho sábio estará contente nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Que teu pai e tua mãe se alegrem, e que aquela que te concebeu se regozije.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Meu filho, dá-me o teu coração, e que os teus olhos observem os meus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Pois a prostituta é uma cova profunda, e a mulher imoral, um poço estreito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Ela fica à espreita como um ladrão e aumenta o número de traidores entre a humanidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Quem tem o “Ai”? Quem tem a tristeza? Quem tem as lutas? Quem está reclamando? Quem tem feridas sem causa? Quem tem olhos vermelhos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Aqueles que passam horas bebendo vinho, aqueles que experimentam o vinho misturado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Não olhes para o vinho quando está vermelho, quando ele brilha no copo e escorre suavemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'No fim, ele morde como uma serpente e dá picada à semelhança da víbora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Teus olhos verão coisas estranhas e o teu coração falará perversidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Tu serás como um que dorme em alto mar ou deita-se no topo do mastro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '\"Golpearam-me!”, tu dirás, \"mas não me machucaram. Bateram-me, mas não senti. Quando despertarei para buscar outra bebida?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Não sintas inveja daqueles que são maus, nem desejes associar-te a eles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'porque seus corações planejam violência, e seus lábios falam sobre o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Por meio da sabedoria, uma casa é construída e, pelo entendimento, é estabelecida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Pelo conhecimento, seus cômodos se enchem com todas as riquezas preciosas e agradáveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'O guerreiro de sabedoria é forte, e a pessoa de conhecimento aumenta sua força,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'porque, pela direção sábia, tu podes fazer a tua guerra e, com muitos conselheiros, há vitória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'A sabedoria é alta demais para o tolo, entre os líderes, no portão, ele não abre sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Há um que planeja fazer o mal; as pessoas o chamam de mestre das intrigas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Um plano insensato é pecado, e os homens desprezam o zombador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Se te mostrares fraco e com medo no dia de dificuldade, então, a tua força é pequena.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Resgata aqueles que são levados à morte, e segura aqueles que cambaleiam para a matança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Se disseres: \"Eis que não sabemos nada sobre isso\", por acaso, Aquele que pesa os corações não entende o que estás dizendo? E Aquele que guarda tua vida não sabe? Por acaso, Deus não dará a cada um o que merece?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Meu filho, come mel, porque é bom, porque o gotejamento do favo de mel é doce para o teu paladar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Assim é a sabedoria para tua alma; se tu a achares, haverá um futuro, e tua esperança não será cortada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Não fiques à espreita, como o corrupto que ataca a casa do justo. Não destruas a casa dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Porque o justo cai sete vezes e se levanta de novo, mas os corruptos são abatidos pela calamidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Não celebres quando teu inimigo cair, e que o teu coração não fique contente quando ele tropeçar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Yahweh verá e desaprovará e desviará Sua fúria dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Não te preocupes por causa dos malfeitores, nem invejes os corruptos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'porque a pessoa má não tem futuro, e a lâmpada dos corruptos se apagará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Teme a Yahweh e teme o rei, meu filho; não te associes com aqueles que se rebelam contra eles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'pois, de repente, seu desastre virá, e quem sabe o tamanho da destruição que virá para ambos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Estes também são dizeres dos sábios: parcialidade no julgamento de um caso da lei não é bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Quem diz ao corrupto: \"Tú és justo\" será amaldiçoado pelos povos e odiado pelas nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Mas aqueles que repreendem o corrupto terão deleite e presentes de bondade virão para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Uma resposta honesta é como um beijo de amizade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Prepara o teu trabalho de fora e deixa tudo pronto para ti mesmo no campo; depois disso, constrói a tua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Não dês testemunho contra teu próximo sem causa, nem enganes com teus lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Não digas: \"Farei a ele o que ele fez a mim; eu lhe pagarei de volta pelo que ele fez\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Eu passei pelo campo do homem preguiçoso, passei pela vinha do homem sem entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'Espinhos cresceram em todo o lugar, a terra estava coberta com urtigas e seu muro de pedra estava derrubado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Então, eu vi e considerei isso; eu olhei e recebi instrução.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Um pouco dormindo, uma pouco cochilando, um pouco descansando de braços cruzados;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'e a pobreza vem sobre ti como um ladrão, e as tuas necessidades, como um soldado armado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Estes também são provérbios de Salomão, copiados pelos homens de Ezequias, rei de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'A glória de Deus é encobrir as coisas, mas a glória dos reis é investigá-las.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Como os céus estão em altura e a terra em profundidade, assim o coração dos reis é indecifrável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Remove a escória da prata e o fundidor poderá usar prata em sua obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Assim também, remove os ímpios da presença do rei e seu trono será estabelecido fazendo o que é justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Não honres a ti mesmo na presença do rei e não te coloques num lugar designado para os grandes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'É melhor que ele te diga: \"Sobe aqui\", do que tu seres humilhado por ele na presença de um nobre. O que tu testemunhaste');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'não tragas, apressadamente, diante do tribunal. O que tu farás no final, quando o teu próximo te envergonhar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Discute o teu caso entre ti e teu próximo e não reveles o segredo de outrem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'ou aquele que te ouve trará vergonha sobre ti e a má fama a teu respeito não poderá ser silenciada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Como maçãs de ouro em engastes de prata, assim é a palavra falada no tempo certo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Como um brinco de ouro ou uma joia feita de ouro fino, assim é a repreensão sábia para um ouvido atento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Como o frio da neve no tempo da colheita, assim é o mensageiro fiel para aqueles que o enviam, ele restaura a vida dos seus senhores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Como nuvens e vento sem chuva, assim é aquele que se gaba de um presente que ele não deu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Com paciência, um comandante pode ser persuadido, e uma língua suave pode quebrar um osso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Se tu encontrares mel, come só o suficiente, senão, terás demais e vomitarás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Não ponhas o teu pé com muita frequência na casa do teu próximo, ele poderá se cansar de ti e te odiar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'O homem que levanta falso testemunho contra o seu próximo é como um bastão usado na guerra, ou uma espada, ou uma flecha afiada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Um homem infiel no qual tu confias no tempo de dificuldades é como um dente quebrado ou um pé que escorrega.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Como a pessoa que tira a roupa no tempo frio, ou como vinagre derramado sobre a soda, assim é aquele que canta canções para um coração pesado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Se o teu inimigo está faminto, dá-lhe alimento para comer e, se ele está com sede, dá-lhe água para beber,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'porque tu colocarás brasas ardentes sobre a sua cabeça e Yahweh te recompensará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Tão certo como o vento norte traz a chuva, assim a língua que conta segredos produz rostos enraivecidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'É melhor viver no canto do terraço que compartilhar a casa com uma mulher briguenta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Como água fria para o que está com sede, assim são as boas notícias de um país distante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Como a nascente suja ou a fonte arruinada, assim é o justo que cambaleia diante dos ímpios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Não é bom comer muito mel, assim como buscar honra sobre honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'A pessoa sem domínio próprio é como uma cidade com brechas ou sem muros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Como a neve no verão ou a chuva na colheita, assim o tolo não merece honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Como o pardal bate asas e a andorinha se move ao voar, assim também a maldição injusta não se cumpre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'O chicote é para o cavalo, a rédea é para o jumento, e a vara é para as costas dos tolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Não respondas ao tolo conforme a sua insensatez, ou te tornarás como ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Responde ao tolo conforme é apropriado à insensatez dele, para que ele não se torne sábio aos seus próprios olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Quem envia uma mensagem pela mão do tolo corta seus próprios pés e bebe violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Como as pernas de um paralítico, que pendem frouxas, assim é um provérbio na boca dos tolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Como amarrar uma pedra na funda, assim é dar honra ao tolo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Como um espinho que entra na mão de um bêbado, assim é um provérbio na boca dos tolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Como um arqueiro que fere todos ao seu redor, assim é aquele que contrata um tolo ou qualquer um que passa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Como um cachorro que retorna ao seu próprio vômito, assim é o tolo que repete a sua insensatez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Vês alguém que é sábio a seus próprios olhos? Há mais esperança para o tolo do que para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'O preguiçoso diz: \"Há um leão na estrada! Há um leão entre os lugares abertos!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Assim como a porta vira nas dobradiças, assim é o preguiçoso sobre sua cama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'O preguiçoso põe sua mão no prato e nem sequer tem força para levá-la à boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'O preguiçoso é mais sábio aos seus próprios olhos do que sete homens que respondem com bom senso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Como aquele que segura as orelhas de um cão, assim é quem está passando e se enfurece numa disputa que não é sua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Como o louco que atira flechas flamejantes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'assim é aquele que engana seu próximo e diz: \"Eu estava brincando!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Por falta de madeira, o fogo se apaga e, onde não há mexeriqueiro, a rixa cessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Como o carvão é para a brasa e a madeira para o fogo, assim é o briguento para acender um conflito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'As palavras do mexeriqueiro são como iguarias deliciosas, que descem ao interior do corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Como a cobertura brilhante de um vaso de barro, assim são os lábios ardentes com um coração mau.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Aquele que odeia os outros disfarça, com os lábios, os seus sentimentos e armazena o engano dentro de si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Ele falará graciosamente, mas não acredites nele, pois há sete abominações em seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Apesar de seu ódio estar encoberto pelo engano, sua perversidade será exposta na assembleia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Aquele que cava uma cova, nela cairá; e a pedra rolará de volta ao que a empurrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'A língua mentirosa odeia as pessoas que ela oprime, e a boca bajuladora causa a ruína.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Não te gabes sobre o amanhã, pois não sabes o que o dia poderá trazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Que outros te elogiem, não a tua própria boca, um estranho, e não teus próprios lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Considera o peso de uma pedra e o peso da areia; a provocação do tolo é mais pesada que ambas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Existe a crueldade da raiva e o transbordar da ira, mas quem é capaz de suportar o ciúme?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'É melhor a repreensão aberta que o amor escondido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Fiéis são as feridas causadas por um amigo, mas um inimigo pode beijar-te abundantemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Uma pessoa que está saciada rejeita até mesmo o favo de mel, mas, para o faminto, todo amargo é doce.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Como um pássaro que vai sem rumo, longe de seu ninho, assim é o homem que se afasta de onde vive.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Perfume e incenso fazem o coração alegrar-se, mas a doçura de um amigo vem de seu conselho sincero.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Não abandones teu amigo e o amigo de teu pai, e não vás à casa de teu irmão no dia da tua calamidade. Melhor é um vizinho que está próximo que um irmão que está longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Sê sábio, meu filho, e faz meu coração alegrar-se; então, eu responderei àquele que zomba de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'O homem prudente vê a adversidade e se esconde, mas os ingênuos seguem adiante e sofrem por causa disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Toma a veste daquele que se pôs por fiador de um estranho; e toma-a em penhor quando ele se tornar fiador de uma mulher imoral.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Aquele que bendisser seu vizinho em alta voz pela manhã, essa bênção será considerada uma maldição!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Uma esposa briguenta é como uma goteira constante em dia de chuva;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'impedi-la é como tentar impedir o vento, ou tentar pegar óleo com a mão direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Ferro afia ferro; do mesmo modo, o homem afia seu amigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'O que cuida da figueira comerá seu fruto, e o que protege seu senhor será honrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Como a água reflete a face de uma pessoa, assim o coração da pessoa reflete o que ela é.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Como o Sheol e Abaddon nunca estão satisfeitos, assim os olhos do homem nunca se satisfazem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'O crisol é para a prata e o forno é para o ouro; e uma pessoa é testada quando é elogiada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Mesmo que tritures o tolo com o pilão, junto com o grão, ainda assim, a insensatez não o deixará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Certifica-te de conheceres a condição de teus rebanhos, e preocupa-te com tuas manadas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'pois a riqueza não é para sempre. Por acaso uma coroa dura por todas as gerações?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Tu deves saber quando o feno é removido e os novos brotos aparecem, e o tempo em que a grama das montanhas é colhida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Aqueles cordeiros fornecerão tuas roupas, e os bodes fornecerão o preço do campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'Haverá leite das cabras para tua alimentação — o alimento de tua casa — e nutrição para tuas servas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Os corruptos fogem quando ninguém os persegue, mas os justos são ousados como um leão jovem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Por causa da transgressão da terra, ela possui muitos governantes, mas, com um homem de entendimento e conhecimento, ela durará muito tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'O pobre que oprime outro pobre é como chuva forte que não deixa alimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Aqueles que abandonam a lei elogiam os corruptos, mas aqueles que guardam a lei lutam contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Os homens maus não entendem a justiça, mas aqueles que buscam a Yahweh entendem tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'É melhor o pobre que anda em sua integridade que o rico que é tortuoso em seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Aquele que guarda a lei é um filho com entendimento, mas aquele que é companheiro dos gulosos envergonha seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Aquele que faz sua fortuna cobrando muitos juros ajunta sua riqueza para outro que terá compaixão dos pobres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Se alguém desvia o ouvido de ouvir a lei, até a sua oração é detestável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Quem fizer desviar o justo para o mau caminho cairá em sua própria cova, mas os irrepreensíveis terão uma boa herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'O rico é sábio aos seus próprios olhos, mas o pobre que tem entendimento o avaliará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Quando os justos triunfam, há grande glória, mas, quando os corruptos se levantam, o povo se esconde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Aquele que esconde seus pecados não prosperará, mas aquele que os confessa e os abandona alcançará misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Abençoado será aquele que sempre vive com reverência, mas quem endurece seu coração cairá em dificuldades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Como um leão rugindo ou um urso quando ataca, assim é o governante corrupto sobre os pobres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'O governante a quem falta entendimento é um opressor cruel, mas aquele que odeia a desonestidade prolongará seus dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Se um homem é culpado porque derramou o sangue de alguém, ele será um fugitivo até a morte, e ninguém o ajudará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Quem caminha com integridade será mantido a salvo, mas aquele que tem o caminho torto cairá logo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Aquele que lavra a sua terra terá muita comida, mas quem segue objetivos inúteis terá muita pobreza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'O homem fiel terá grandes bênçãos, mas aquele que se enriquece rapidamente não ficará impune.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Não é bom mostrar parcialidade, mas, por um pedaço de pão, o homem cometerá uma transgressão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'O homem mesquinho corre atrás de riquezas, mas ele não sabe que a pobreza virá sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Quem repreende alguém alcançará dele mais favor do que alguém que o bajule com sua língua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Qualquer um que rouba seu pai e sua mãe e diz: \"Isso não é pecado\", esse é companheiro do que destrói.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'O homem ganancioso provoca conflitos, mas o que confia em Yahweh prosperará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Aquele que confia em seu próprio coração é um tolo, mas quem anda em sabedoria será mantido longe do perigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Àquele que dá aos pobres não lhe faltará nada, mas quem fecha os olhos para eles receberá muitas maldições.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Quando os corruptos se levantam, o povo se esconde, mas quando eles perecem, os justos aumentam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'A pessoa que recebeu muitas repreensões, mas endurece seu pescoço, será quebrada a tal ponto que não poderá ser curada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Quando os justos se multiplicam, o povo se alegra, mas quando um ímpio é o governante, o povo suspira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Aquele que ama a sabedoria faz seu pai regozijar-se, mas o que mantém a companhia de prostitutas destrói sua riqueza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'O rei estabelece a terra pela justiça, mas o que exige subornos a destrói.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'O homem que bajula seu vizinho espalha uma rede para seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'No pecado de uma pessoa má, existe uma armadilha, mas o justo canta e regozija-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'O justo conhece os direitos do pobre; o corrupto não entende tal conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Os zombadores incendeiam uma cidade, mas os que são sábios afastam a ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Quando um sábio tem uma discussão com um tolo, ele ri e se irrita, e não haverá descanso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Os sanguinários odeiam o que não tem culpa e buscam a vida dos justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'O tolo revela toda a sua ira, mas o homem sábio a contém e se acalma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Se um governante presta atenção a mentiras, todos os seus oficiais serão corruptos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'O pobre e o opressor têm algo em comum, pois Yahweh dá luz aos olhos de ambos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Se um rei julga os pobres com a verdade, seu trono será estabelecido para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'A vara e a reprovação dão sabedoria, mas uma criança livre de disciplina envergonha sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Quando os corruptos estão no poder, a transgressão aumenta, mas os justos verão a queda desses ímpios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Dá disciplina ao teu filho, e ele te dará descanso; ele trará deleite para a tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Onde não há profecia, o povo perde o controle próprio, mas aquele que mantém a lei é abençoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'O escravo não será corrigido por palavras, pois, apesar de ele entender, não haverá resposta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Vês um homem precipitado em suas palavras? Há mais esperança para o tolo que para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'O que mima seu escravo desde a infância, no final disso, terá problemas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Uma pessoa irada provoca conflito, e o enfurecido comete muitos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'O orgulho de uma pessoa a humilha, mas o que tem um espírito humilde receberá honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'O que é cúmplice de um ladrão odeia sua própria vida; ele ouve a maldição e não diz nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'O medo do homem monta uma armadilha, mas o que confia em Yahweh será protegido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Muitos são os que buscam a face do governante, mas o homem recebe a justiça que vem de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'O homem injusto é uma abominação para os justos, mas aquele cujo caminho é correto é detestável para o corrupto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'As palavras de Agur, filho de Jaque — um enunciado. Este homem declarou para Itiel, Itiel e Ucal:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Certamente, eu sou mais como um animal do que como ser humano; não tenho o entendimento do ser humano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Não aprendi a sabedoria, e não tenho o conhecimento do Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Quem subiu ao céu e, de lá, desceu? Quem recolheu o vento no vazio de suas mãos? Quem reuniu as águas em um manto? Quem estabeleceu todas as extremidades da terra? Qual é o seu nome, e qual é o nome do seu filho? Se é que o sabes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Toda palavra de Deus é pura. Ele é um escudo para os que Nele se refugiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Nada adiciones às Suas palavras, ou Ele te repreenderá e provará que és mentiroso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Duas coisas eu peço a ti, não as retenhas de mim antes que eu morra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Coloca a vaidade e a mentira longe de mim. Não me dês nem a pobreza nem a riqueza, somente a comida de que preciso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Porque se eu tiver muito, Te negarei e direi: \"Quem é Yahweh?\" Ou se ficar pobre, roubarei e profanarei o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Não difameis um escravo diante do seu senhor, ou ele vos amaldiçoará, e vós sereis culpados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'A geração que amaldiçoa seu pai e não abençoa sua mãe');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'é a geração que é pura aos seus próprios olhos, mas não é lavada da sua imundícia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Esta é a geração — quão altivos são seus olhos e levantadas as suas pálpebras! —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'cujos dentes são espadas e suas mandíbulas são facas. Assim, eles podem devorar da terra os pobres e, da humanidade, os necessitados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'A sanguessuga tem duas filhas, \"Dá e Dá\", elas choram. Há três coisas que nunca estão satisfeitas, quatro que nunca dizem: “Basta!”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'O Sheol, o útero estéril, a terra sedenta por água e o fogo que nunca diz: \"Basta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Os olhos que zombam do pai e desprezam a obediência da mãe; seus olhos serão arrancados pelos corvos do vale e comidos por abutres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Há três coisas que são maravilhosas demais para mim, quatro que eu não entendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'o caminho da águia para o céu, o caminho da cobra para a rocha, o caminho do navio no meio do mar e o caminho do homem com uma mulher virgem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Este é o caminho de uma adúltera — ela come, limpa seus lábios, e diz: \"Não fiz nada de errado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Há três coisas que fazem a terra estremecer e a quarta, ela não pode suportar:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'um escravo quando se torna rei; um tolo quando se farta de comer;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'uma mulher odiada quando se casa; e uma empregada quando ela toma o lugar da sua senhora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Quatro coisas são pequenas na terra e, ainda assim, são muito sábias:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'as formigas, criaturas que não são fortes, mas preparam a comida no verão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'os coelhos, criaturas que não são poderosas, mas fazem suas casas nas rochas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Os gafanhotos que não têm rei, mas todos eles marcham enfileirados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'Quanto ao lagarto, podes segurá-lo em tuas mãos, ainda assim, eles são encontrados nos palácios dos reis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Há três coisas que são imponentes em seu caminhar, quatro que são imponentes na forma que andam:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'o leão, o mais forte entre os animais selvagens, não foge de nada;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'um galo firmado em esporas, um bode, e um rei, cujos soldados estão ao seu lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Se tens sido um tolo, exaltando-te a ti mesmo, ou se tens concebido o mal — coloca tuas mãos sobre a boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Assim como bater o leite produz manteiga, e o nariz produz sangue se for torcido, assim as obras feitas com raiva produzem conflito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Palavras do rei Lemuel, um oráculo ensinado por sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'O quê, meu filho? O quê, filho do meu ventre? O quê, filho dos meus votos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Não dês tua força às mulheres, ou os teus caminhos àqueles que destroem reis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Não convém a reis, Lemuel, não convém a reis beber vinho, nem a governantes desejar a bebida forte;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'porque quando eles bebem, esquecem-se do que foi decretado, e pervertem os direitos de todos os aflitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Dai bebida forte ao que está perecendo e vinho aos amargurados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Ele beberá e se esquecerá de sua pobreza, e não se lembrará de suas dificuldades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Fala por aqueles que não podem falar, pelas causas de todos os que estão perecendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Fala e julga pela medida do que é justo, e defende a causa dos pobres e necessitados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Quem pode achar uma esposa virtuosa? Seu valor vai muito além de joias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'O coração de seu marido confia nela e ele não terá falta de nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Ela faz coisas boas por ele e não más, todos os dias de sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Ela escolhe lã e linho, e trabalha com o deleite de suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Ela é como os navios mercantes, traz comida de longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Ela se levanta enquanto é noite, dá comida à sua família e distribui as tarefas entre suas servas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Ela avalia um campo e o compra, com o fruto de suas mãos, planta uma vinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Ela se veste de força e fortalece os seus braços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Ela percebe o que lhe trará bom lucro; durante toda a noite, sua lâmpada não se apaga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Ela põe suas mãos no fuso e segura a roca de fiar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Ela estende sua mão aos pobres, estende suas mãos aos necessitados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Ela não teme a neve por sua família, pois toda a sua família está vestida com lã escarlate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Ela faz cobertas para sua cama e veste-se de roupas de linho púrpura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Seu marido é conhecido junto aos portões, quando ele se assenta com os anciãos da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Ela faz vestes de linho e as vende, fornece faixas aos comerciantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Ela se veste de força e honra e ri para o futuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Ela abre sua boca com sabedoria e a lei dos benevolentes está em sua língua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Ela vigia os caminhos de sua casa e não come do pão da preguiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Seus filhos crescem e a chamam de abençoada; seu marido a elogia, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, '\"Muitas mulheres fizeram o bem, mas tu a todas superas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'A elegância é enganosa, a beleza é fútil, mas a mulher que teme a Yahweh, essa será elogiada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Dai a ela o fruto de suas mãos e que seu trabalho a engrandeça nos portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Estas são as palavras do pregador, o filho de Davi e rei em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Vaidade das vaidades, diz o pregador: nada é importante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Que lucro o homem obtém de todo o trabalho com que se afadiga debaixo do sol?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Uma geração vai, outra geração vem, mas a terra permanece para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'O sol nasce e se põe, e novamente se apressa a retornar ao lugar onde nasceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'O vento sopra para o sul e circula ao redor para o norte, sempre indo pelo seu caminho e voltando novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Todos os rios correm para o mar, mas o mar nunca se enche. Ao lugar para onde os rios vão, para ali, eles irão novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Tudo se torna cansaço e ninguém pode explicar isso. Os olhos não ficam satisfeitos com o que veem, nem os ouvidos com o que ouvem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'O que foi é o que será, e o que se fez é o que se fará. Não há nada de novo debaixo do sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Há algo sobre o qual possa ser dito: \"Vê! Isto é novo?\" O que quer que exista já havia existido há muito tempo, em tempos antigos, muito antes de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Ninguém parece lembrar-se daquilo que aconteceu nos tempos antigos, nem das coisas que ocorreram muito depois, e o que acontecerá no futuro, provavelmente, também não será lembrado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Eu sou o pregador, e tenho reinado sobre Israel em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Apliquei minha mente a estudar e a procurar com sabedoria sobre tudo o que é feito debaixo dos céus. Essa procura é uma tarefa penosa que Deus entregou aos filhos dos homens para se ocuparem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Tenho visto todas as obras que são feitas debaixo do sol, e tudo é inútil, como tentar agarrar o vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'O que está distorcido não pode ser endireitado; o que falta não pode ser contado!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Tenho falado ao meu coração, dizendo: \"Vê! Adquiri mais sabedoria do que todos os que viveram antes de mim, em Jerusalém. Minha mente tem visto grande sabedoria e conhecimento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Então, apliquei meu coração a conhecer a sabedoria e também a loucura e a tolice. Eu cheguei à compreensão de que isso também era uma tentativa de agarrar o vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Pois na abundância da sabedoria há muita frustração, e aquele que aumenta o saber, aumenta o sofrimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Eu disse ao meu coração: \"Vem agora; vou te testar com minha felicidade. Então experimenta a alegria\". Mas olha, isso também é só uma ilusão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Eu falei sobre o riso: \"Isso é loucura\"; e sobre o prazer: \"Qual é a utilidade disso?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Eu considerei em meu coração como satisfazer meus desejos com vinho. Deixei minha mente me guiar com sabedoria, embora ainda estivesse apegado à insensatez. Eu procurei descobrir o que é bom para as pessoas fazerem debaixo do céu, durante os dias de suas vidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Eu realizei grandes coisas. Construí casas e plantei vinhas para mim mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Cultivei pomares de árvores frutíferas para mim; plantei todo tipo de árvores frutíferas nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Eu criei reservatórios de água para irrigar um bosque onde as árvores estavam crescendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Eu adquiri escravos e escravas; tive escravos nascidos em meu palácio. Também tive grandes rebanhos e manadas de gado, muito mais do que qualquer outro rei que governou Jerusalém antes de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Igualmente, acumulei para mim mesmo prata e ouro, os tesouros dos reis e províncias. Escolhi cantores e cantoras e tive concubinas, os prazeres dos filhos dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Então, eu me tornei mais poderoso e rico do que todos os que viveram antes de mim, em Jerusalém, conservando comigo a sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Tudo o que meus olhos desejaram não lhes neguei. Eu não neguei ao meu coração nenhum prazer, porque meu coração se encheu de alegria com todo meu trabalho, e o prazer foi a recompensa de todos os meus esforços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Então, olhei para tudo o que minhas mãos haviam realizado e para o trabalho que fiz; mas, novamente, tudo era vaidade e como uma tentativa de agarrar o vento. Não havia proveito debaixo do sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Então, voltei a considerar a sabedoria e também a insensatez do tolo: que poderá fazer o rei? Apenas o que não tenha sido feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'Então, comecei a entender que sabedoria é melhor do que insensatez, exatamente como a luz é melhor do que as trevas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'O homem sábio utiliza seus olhos para enxergar aonde está indo, mas o insensato é como alguém que anda no escuro. Entretanto percebi que todos têm o mesmo destino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Então, eu disse em meu coração: o que acontece ao tolo também me acontecerá. Então, que diferença faz em ser muito sábio? Concluí em meu coração: isso também é apenas ilusão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Tanto o homem sábio quanto o tolo não serão lembrados por muito tempo. Nos dias do porvir, tudo será esquecido. Assim como o tolo, o homem sábio também morre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Então, detestei a vida porque achei má toda obra feita debaixo do sol, porque tudo é inútil, e como uma tentativa de agarrar o vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Eu odiei todas as minhas realizações pelas quais trabalhei debaixo do sol, porque devo deixá-las para trás, para o homem que me suceder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Quem sabe se ele será um sábio ou um tolo? No entanto, ele será senhor sobre tudo o que meu trabalho e sabedoria construíram. Isso também é ilusão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Portanto, meu coração começou a se desesperar por todo esforço que fiz debaixo do sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Pois pode haver alguém que trabalhe com sabedoria, com conhecimento e habilidade, mas deixará tudo o que fez para quem não fez nada disso. Isso também é ilusão e uma grande tragédia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Pois que proveito a pessoa tem em trabalhar arduamente e tentar em seu coração completar o duro trabalho que realiza debaixo do sol?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Todo dia seu trabalho é penoso e estressante, e à noite sua alma não encontra descanso. Isso também é ilusão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Não há nada melhor para alguém do que simplesmente comer e beber, e estar satisfeito do seu trabalho. Vi que, na verdade, tudo vem das mãos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Pois quem pode comer ou ter algum tipo de prazer distante de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Porque a todo o que Lhe agrada Deus dá sabedoria, conhecimento e alegria. No entanto, para o pecador, Ele dá o trabalho de ajuntar e armazenar para entregá-lo a outro de quem Deus Se agrade. Isso também é vaidade e como uma tentativa de agarrar o vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Para tudo há um tempo determinado, um tempo para cada propósito debaixo do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Há um tempo para nascer e um tempo para morrer; um tempo para plantar e um tempo para arrancar o que foi plantado;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'um tempo para matar e um tempo para curar; um tempo para derrubar e um tempo para construir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Há um tempo para chorar e um tempo para rir; um tempo para lamentar e um tempo para dançar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'um tempo para atirar pedras e um tempo para juntar pedras; um tempo para abraçar pessoas e um tempo para deixar de abraçar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'um tempo para buscar coisas e um tempo de parar de buscar; um tempo para guardar coisas e um tempo para jogar coisas fora;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'um tempo para rasgar roupas e um tempo para costurar roupas; um tempo para calar e um tempo para falar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Há um tempo para amar e um tempo para odiar; um tempo para guerra e um tempo para paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Que vantagem o trabalhador tem de seu trabalho?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Eu vi a obra que Deus deu ao homem para realizar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Deus fez tudo adequado para seu devido tempo. Ele também colocou a eternidade no coração do homem; mas os homens não conseguem entender as obras que Deus fez desde o princípio até o fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Entendi que não há nada melhor para alguém do que se alegrar em fazer o bem enquanto viver,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'e que todo aquele que come e bebe deve entender como desfrutar do bem que vem de seu trabalho. Isso é um presente de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Eu sei que tudo quanto Deus faz dura para sempre. Nada pode ser acrescentado ou tirado disso, porque Deus é Quem fez isso para as pessoas se aproximarem Dele com honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'O que existe já foi, e o que será já existiu. Deus faz o homem buscar coisas escondidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Vi a maldade que há debaixo do sol: no lugar onde deveria estar a justiça e no lugar da retidão estava a maldade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Eu disse em meu coração: Deus julgará o justo e o ímpio, no tempo certo, por cada coisa e cada obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Eu disse em meu coração: Deus prova os homens para mostrar-lhes que são como animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Pois o destino dos filhos dos homens e o destino dos animais são o mesmo. A morte de um é como a morte do outro. O respirar é o mesmo para todos eles. Não há vantagem dos homens sobre os animais; pois não têm o mesmo fôlego?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Todos estão indo para o mesmo lugar. Tudo vem do pó, e para o pó tudo retornará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Quem sabe se o espírito do homem vai para cima e o espírito dos animais vai para debaixo da terra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Então, novamente, concluí que não há nada melhor para alguém do que ter prazer em seu trabalho, pois essa é sua recompensa. Quem o fará voltar para ver o que acontecerá depois dele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Mais uma vez, pensei sobre toda a opressão que ocorre debaixo do sol. Eis as lágrimas das pessoas oprimidas, e elas não tinham ninguém para confortá-las! O poder estava nas mãos de seus opressores, e não havia ninguém para trazer-lhes conforto!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Logo, considero mais afortunadas as pessoas que já morreram do que aquelas que ainda estão vivas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'No entanto, mais afortunado do que ambas é aquele que ainda não viveu, aquele que não viu quaisquer dos atos malignos que são cometidos debaixo do sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Então, vi que todo ato de fadiga, e todo trabalho habilidoso tornou-se motivo de inveja para o próximo. Isso também é vaidade e como a tentativa de agarrar o vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'O tolo fecha suas mãos e não trabalha; então sua própria carne torna-se sua comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Mas é melhor uma mão cheia de lucro com trabalho tranquilo, do que duas mãos cheias com o trabalho de tentar agarrar o vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Então refleti novamente sobre mais futilidades e mais vaidades que se dissipam sob o sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Há o tipo de homem que é solitário. Ele não tem ninguém, nem filho, nem irmão. Não há fim para todo seu trabalho, e seus olhos não ficam satisfeitos com a riqueza obtida. Então, ele questiona: para quem estou trabalhando duramente e me privando do prazer? Isso também é vaidade, uma má situação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Duas pessoas juntas trabalham melhor que uma; juntas, elas podem obter melhor pagamento pelo seu trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Pois, se uma cair, a outra pode levantá-la. No entanto, a tristeza segue o que está sozinho; quando ele cai, não há ninguém para levantá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Se dois se deitarem juntos, eles podem se aquecer, mas como pode um se aquecer sozinho?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Um homem sozinho pode ser dominado, mas dois podem resistir a um ataque. Uma corda tripla não será facilmente quebrada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'É melhor ser um jovem pobre, mas sensato, do que um velho rei tolo que não sabe mais ouvir conselhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Isso é verdade, mesmo que o jovem se torne rei depois de sair de uma prisão, ou mesmo que ele tenha nascido pobre no seu reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Contudo eu vi todos os que estavam vivos e caminhando debaixo do sol, submetendo-se a outro jovem que foi levantado como rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Não tem fim o número de pessoas sobre quem o novo rei governa; mas, depois, muitas delas não o exaltarão mais. Certamente, essa situação é vaidade, e como a tentativa de agarrar o vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Presta atenção a tua conduta quando fores à casa de Deus. Vai lá para ouvir. Ouvir é melhor do que oferecer sacrifícios como tolos, pois não sabem o que fazem; são perversos em sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Não sejas muito rápido para falar, nem teu coração se apresse a trazer qualquer assunto diante de Deus. Deus está no céu, mas tu estás na terra; portanto sejam poucas as tuas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Se tens muitas coisas para te preocupares, provavelmente terás sonhos ruins. Quanto mais palavras falares, provavelmente mais coisas tolas dirás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Quando fizeres um voto a Deus, não demores a cumpri-lo, pois Deus não tem prazer em tolos. Cumpre o que prometeres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Melhor não fazer um voto do que fazê-lo e não cumprir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Não permitas que tua boca te faça pecar. Não digas ao mensageiro de Deus: \"Esse voto foi um erro\". Por que fazer com que Deus Se ire, por teres jurado falsamente, provocando-O a destruir o trabalho de tuas mãos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Porque em muitos sonhos, como em muitas palavras, há vaidade; então, teme a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Quando vires, em tua província, o pobre ser oprimido e negligenciado de um tratamento justo e correto, não te surpreendas como se ninguém soubesse disso, porque há pessoas no poder que vigiam aqueles que estão abaixo deles, e ainda há outros que estão acima deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Além disso, o produto da terra é para todos, e o próprio rei tira produtos dos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Quem ama a prata não ficará satisfeito com ela, e qualquer pessoa que ama as riquezas sempre quer mais. Isso também é vaidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'À medida que a prosperidade aumenta, também aumentam as pessoas que a consomem. Que vantagem existe na riqueza para seu proprietário, exceto em vê-la com seus olhos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'O sono de um homem trabalhador é doce, quer coma pouco, quer muito; mas os bens de uma pessoa rica não lhe permitem dormir bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Há um mal severo que vi debaixo do sol: riquezas acumuladas pelo dono, resultando em sua própria miséria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Quando o homem rico perde os bens através de má sorte, seu próprio filho, a quem ele gerou, fica sem nada nas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Como um homem nasce nu do ventre de sua mãe, assim também ele deixará essa vida. Ele não pode levar em suas mãos nada de seu trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Outro mal severo é que exatamente como uma pessoa veio, assim ela também voltará. Que lucro alguém pode ter trabalhando para o vento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Durante seus dias, ele come na escuridão, com muita angústia, doença e ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Eis o que tenho visto: bom e adequado é comer e beber, e aproveitar o lucro de todo nosso trabalho, enquanto trabalhamos duro sob o sol durante os dias da vida que Deus nos deu, pois esta é a tarefa do homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Qualquer um a quem Deus tenha dado riquezas e bens, e a capacidade de receber sua parte e alegrar-se em seu trabalho — isso é um presente de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Porque não lembrará muito dos dias de sua vida, porque Deus o faz manter-se ocupado com as coisas que ele gosta de fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Há uma maldade que tenho visto debaixo do sol, e isso é difícil para os homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Deus pode dar bens, riqueza e honra para um homem, de forma que não lhe falte nada que deseje para si; mas, ao mesmo tempo, Deus não lhe dá habilidade para aproveitá-los. Em vez disso, outra pessoa usa suas coisas. Isso é vaidade, uma aflição cruel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Se um homem tem cem filhos e vive muitos anos, ainda que seu tempo de vida seja longo, mas, se seu coração não fica satisfeito com as boas coisas, e ele não é sepultado com honra, então digo que um bebê nascido morto está em melhor situação que ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Mesmo tal bebê nasceu em vão, e vai embora na escuridão, e seu nome permanece oculto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Apesar de essa criança não ver o sol ou nada conhecer, ela descansa, enquanto aquele homem não.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Mesmo que um homem viva por dois mil anos, mas, se não aprender a desfrutar das coisas boas, ele vai para o mesmo lugar que todo mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Embora todo o trabalho de um homem seja encher seu estômago, seu apetite ainda não fica satisfeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'De fato, que vantagem tem a pessoa sábia em relação à tola? Que vantagem tem o homem pobre, mesmo que saiba como agir diante de outras pessoas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'É melhor ficar satisfeito com o que os olhos podem ver do que desejar o que queira um apetite delirante, o que também é inútil e é como tentar agarrar o vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'O que quer que tenha existido já recebeu o seu nome, e o que a humanidade é já foi conhecido. Assim, tornou-se inútil disputar com Aquele que é o poderoso juiz de tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Quanto mais palavras são faladas, mais a futilidade aumenta; então, qual a vantagem disso para um homem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Pois quem sabe o que é bom para o homem em sua vida durante seus fúteis e numerosos dias, pelos quais ele passa como uma sombra? Quem pode dizer a um homem o que virá debaixo do sol, depois que ele se for?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Um bom nome é melhor do que perfume caro, e o dia da morte é melhor que o do nascimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'É melhor ir a uma casa em dia de luto do que em dia de festa, pois o luto chega a todas as pessoas no final da vida; portanto os vivos devem levar isso ao seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'A tristeza é melhor que o riso, porque, depois da tristeza do rosto, vem a alegria do coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'O coração do sábio está na casa do luto, mas o coração dos tolos está na casa em festa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Melhor é ouvir a repreensão do sábio do que a canção dos tolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Porque como o crepitar dos espinhos queimando debaixo de uma panela, assim é o riso dos tolos. Isso também é vaidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'A extorsão, certamente, faz o homem sábio tornar-se tolo, e o suborno corrompe o coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Melhor é o final de algo do que o início; e as pessoas pacientes de espírito são melhores que as orgulhosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Não te apresses em irar-te no espírito, pois a ira reside no coração dos tolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Não digas: \"Por que os dias passados foram melhores do que estes?\", pois não é sábio fazer esse tipo de pergunta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'A sabedoria é tão valiosa quanto as coisas que herdamos de nossos antepassados. Ela proporciona benefícios para aqueles que veem o sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Pois a sabedoria proporciona tanta proteção quanto o dinheiro pode proporcionar, mas a vantagem do conhecimento é que a sabedoria dá vida a quem a possui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Considera os feitos de Deus. Quem pode endireitar qualquer coisa que Ele fez torta?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Quando os tempos forem bons, vive feliz neles; mas, quando os tempos forem maus, considera isto: Deus permitiu que ambos existissem lado a lado. Por essa razão, ninguém descobrirá nada que venha depois de si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Tenho visto muitas coisas sem sentido em meus dias. Há pessoas justas que perecem, apesar de sua justiça, e há pessoas perversas que vivem uma vida longa, apesar do seu mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Não sejas hipócrita, nem sábio aos teus próprios olhos. Por que deverias destruir-te a ti mesmo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Não sejas perverso demais, nem tolo. Por que deverias morrer antes do teu tempo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'É bom que adquiras essa sabedoria e que não deixes a justiça. Porque a pessoa que teme a Deus cumprirá todas as suas obrigações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'A sabedoria é poderosa para o homem sábio, mais do que dez governantes em uma cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Não há um homem justo na terra que faça o bem e nunca peque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Não escutes toda palavra que é dita, porque podes ouvir teu servo amaldiçoar-te.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Semelhantemente, tu mesmo sabes que, em teu próprio coração, frequentemente tens amaldiçoado outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Tudo isso provei pela sabedoria. Disse eu: \"Serei sábio\"; mas isso era mais do que eu poderia ser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'A sabedoria está longe e muito profunda. Quem pode encontrá-la?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Voltei meu coração para aprender, examinar e buscar sabedoria e explicações da realidade, para entender que o mal é estúpido e que a tolice é loucura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Descobri que mais amargo do que a morte é qualquer mulher cujo coração está cheio de armadilhas e redes, e cujas mãos são correntes. Quem quer que agrade a Deus escapará dela, mas o pecador será pego por ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Considera o que descobri, diz o pregador. Tenho acrescentado uma descoberta à outra para encontrar uma explicação da realidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Isso é o que ainda estou procurando, mas não encontrei: encontrei um homem justo entre mil, mas uma mulher entre todos aqueles não encontrei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Descobri apenas isto: Deus criou a humanidade justa; mas ela se afastou, procurando por muitas dificuldades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Quem é um homem sábio? Quem sabe o que os eventos da vida significam? A sabedoria em um homem faz a sua face brilhar, e a dureza do seu rosto mudar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Eu aconselho que obedeças à ordem do rei, por causa do juramento que fizeste, diante de Deus, de protegê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Não te apresses a sair de sua presença e não apoies algo errado, pois o rei faz o que deseja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'A palavra do rei é soberana; então, quem lhe dirá: \"O que estás fazendo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Quem guarda os mandamentos do rei evita o dano. O coração de um homem sábio reconhece a direção certa e o tempo oportuno para agir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Para toda pergunta há uma resposta e um tempo certo para respondê-la, porque as dificuldades do homem são grandes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Ninguém sabe o que virá a seguir. Quem lhe contará o que está por vir?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Ninguém controla a própria respiração até o ponto de fazê-la cessar, e ninguém tem poder sobre o dia da sua morte. Ninguém é desligado do exército durante uma guerra, e a maldade não salva aqueles que são seus escravos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Eu vi tudo isso, e apliquei meu coração a todo tipo de trabalho que é feito sob o sol. Há um tempo quando uma pessoa oprime a outra para sua própria infelicidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Então, vi o sepultamento público dos maus. Eles foram retirados do lugar santo, sepultados e exaltados pelas pessoas da cidade onde realizaram suas obras más. Isso também é inútil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Quando uma sentença contra um crime cruel não é executada rapidamente, isso induz os corações dos seres humanos a fazerem o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Mesmo que um pecador faça o mal centenas de vezes e viva por muito tempo, sei que as coisas irão bem para aqueles que respeitam a Deus, que honram a Sua Presença com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Mas não para o homem mau — sua vida não será prolongada; seus dias são como uma sombra passageira porque ele não honra a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Há outra coisa sem sentido que ocorre na terra: o que acontece às pessoas justas, também acontece às injustas, e o que acontece às pessoas injustas acontece às justas. Digo que isso também é ilusão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Portanto, recomendo a felicidade, pois não há coisa melhor para um homem sob o sol do que comer, beber e ser feliz. É a felicidade que o acompanhará em seu trabalho por todos os dias de sua vida, a qual Deus tem lhe dado sob o sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Quando apliquei meu coração a conhecer a sabedoria e entender o trabalho feito na terra, o qual frequentemente é sem descanso para os olhos, de noite ou de dia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'eu considerei todos os feitos de Deus, e que o homem não pode entender o trabalho que é feito sob o sol. Não importa o quanto um homem trabalhe para encontrar respostas, ele não as encontrará. Ainda que um homem sábio acredite que conheça, ele de fato não conhece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Eu pensei profundamente sobre tudo isso, tentando entender as pessoas justas e sábias, e seus feitos. Eles estão todos nas mãos de Deus. Ninguém sabe se o amor ou o ódio virá para alguém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Todos têm o mesmo destino. O mesmo destino espera tanto os justos quanto os perversos, os bons e os maus, os puros e os impuros, os que sacrificam e os que não sacrificam. Assim como as pessoas boas morrerão, assim também os pecadores; assim como os que juram morrerão, também morrerá o homem que teme fazer um juramento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Existe um destino cruel para tudo o que é feito debaixo do sol, um mesmo destino para todos. Os corações dos seres humanos são cheios de maldade, e a tolice está em seus corações enquanto eles vivem. E depois de tudo, eles morrem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Pois, para qualquer um que permanece entre os vivos, há esperança, assim como um cachorro vivo é melhor que um leão morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Porque todos os vivos sabem que morrerão, mas os mortos não sabem coisa alguma. Eles já não têm nenhuma recompensa, pois a memória deles foi esquecida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'O seu amor, ódio e inveja desapareceram há muito tempo. Eles nunca mais terão parte em nada que é feito debaixo do sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Segue teu caminho, come teu pão com alegria e bebe teu vinho com um coração feliz, porque Deus aprova a celebração das boas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Sejam tuas roupas sempre brancas, e seja tua cabeça ungida com óleo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Vive alegremente com a esposa que amas, todos os dias da tua vida inútil, os dias que Deus tem te dado debaixo do sol, esses inúteis dias. Essa é tua recompensa nesta vida, pelo trabalho que fizeste debaixo do sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Tudo o que tuas mãos encontram para fazer, trabalha com tuas forças, porque não há trabalho, explicação, conhecimento ou sabedoria na sepultura para onde vais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Eu tenho visto algumas coisas interessantes debaixo do sol: a corrida não pertence aos ligeiros; a batalha não pertence aos fortes; o pão não pertence aos sábios; as riquezas não pertencem aos prudentes; o favor não pertence aos entendidos. Entretanto, tempo e acaso afetam a todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Porque ninguém sabe quando morrerá, assim como o peixe preso em uma rede de morte, ou como pássaros pegos com uma armadilha. Assim como os animais, seres humanos são aprisionados em tempos maus, que repentinamente caem sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Eu também tenho visto sabedoria debaixo do sol, de maneira que me pareceu grandiosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Havia uma pequena cidade com apenas alguns homens nela, e um grande rei veio contra ela; sitiou-a e construiu grandes rampas contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Mas, na cidade, foi encontrado um homem pobre e sábio, cuja sabedoria salvou a cidade; no entanto, depois, ninguém se lembrou daquele pobre homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Então concluí: sabedoria é melhor que força, mas a sabedoria de um pobre homem é desprezada, e suas palavras não são ouvidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'As palavras dos sábios faladas calmamente são melhor ouvidas que os gritos de qualquer governante entre os tolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Sabedoria é melhor que armas de guerra, mas um pecador pode arruinar muitas coisas boas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Como uma mosca morta faz o perfume cheirar mal, assim uma pequena tolice pode superar a sabedoria e a honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'O coração de uma pessoa sábia tende para a direita, mas o coração de um tolo tende para a esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Quando um tolo caminha pela rua, seu pensamento é deficiente, provando a todos que ele é um tolo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Se as emoções de um governante se levantarem contra ti, não deixes teu trabalho. A calma pode tranquilizar um grande ultraje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Há um mal que tenho visto sob o sol, um tipo de erro que vem do governante:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'aos tolos são dadas posições de liderança, enquanto aos homens bem-sucedidos, posições inferiores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Tenho visto escravos montando cavalos e homens bem-sucedidos andando a pé, como escravos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Aquele que cava um buraco pode cair nele e, sempre que alguém derruba um muro, uma cobra pode picá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Qualquer um que corte pedras pode ser machucado por elas, e o homem que corta madeira está em perigo por isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Se uma lâmina de ferro está cega, e um homem não a afia, então ele deve usar mais força; mas a sabedoria oferece uma vantagem para o sucesso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Se uma cobra morde, antes de ser encantada, não há vantagem para o encantador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'As palavras da boca de um homem sábio são graciosas, mas os lábios do tolo o devoram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Assim que as palavras começam a fluir da boca de um tolo, as tolices aparecem e, no fim, sua boca flui com loucura cruel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Um tolo multiplica palavras, mas ninguém sabe o que está por vir. Quem sabe o que acontecerá com ele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'O trabalho duro dos tolos os fadiga, de modo que eles nem sabem o caminho para a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Ai de ti, terra, se teu rei é um menino, e se teus líderes começam a festejar de manhã!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Mas abençoada és tu, terra, se teu rei é filho de nobres, e se teus líderes comem na hora certa, para obter força, e não para embriaguez!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Por causa da preguiça, o teto desmorona, e por causa das mãos ociosas, a casa tem goteiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'As pessoas preparam comida para alegrar-se; o vinho traz prazer à vida, e o dinheiro preenche todas as necessidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Não amaldiçoes o rei, nem mesmo em tua mente, e não amaldiçoes os ricos em teu quarto, pois uma ave do céu pode levar tuas palavras. Tudo que tem asas pode espalhar o assunto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Lança teu pão sobre as águas, pois tu o encontrarás novamente, após muitos dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Reparte-o com sete, ou até com oito pessoas, pois tu não sabes que desastres virão sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Se as nuvens estão cheias de chuva, elas se esvaziam na terra; e, se uma árvore cai em direção ao sul ou ao norte, não importa onde, lá permanecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Qualquer um que observar o vento não plantará, e quem observar as nuvens não colherá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Como não sabes o caminho do vento, nem como os ossos de uma criança crescem no ventre materno, assim também não podes compreender a obra de Deus, que criou todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'De manhã, planta tua semente; até o começo da noite, trabalha com tuas mãos como for preciso, pois não sabes o que prosperará: se a da manhã ou a da noite, ou se ambas igualmente serão boas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Verdadeiramente, a luz é doce, e é agradável aos olhos ver o sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Se alguém vive muitos anos, deixa-o ser feliz em todos eles, mas deixa-o pensar sobre os dias vindouros da escuridão, pois eles serão muitos. Tudo o que virá será vaidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Alegra-te, jovem, na tua juventude, e que teu coração seja cheio de alegrias nos dias de tua mocidade. Persegue os bons desejos de teu coração e o que quer que esteja à vista de teus olhos. Contudo sabe tu que Deus te pedirá contas de todas essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Aparta a ira de teu coração e ignora qualquer dor no teu corpo, porque a juventude e o seu vigor são vaidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Lembra-te do teu Criador nos dias da tua juventude, antes que venham os dias de dificuldade, e antes que cheguem os anos quando dirás: \"Não tenho neles prazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Faze isso antes que se apague a luz do sol, da lua e das estrelas, e as nuvens escuras retornem após a chuva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'Chegará o tempo quando tremerá o guardião do palácio, e os homens fortes se curvarão, e as mulheres cessarão seus moedores, por serem poucos, e aqueles que olham para fora das janelas já não verão claramente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'Chegará o tempo quando as portas serão fechadas na rua, e cessará o som da moagem; quando os homens ficarão assustados com o som de um pássaro, e o canto das vozes das meninas desaparecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Chegará o tempo quando os homens terão medo de altura e de perigos nas estradas, quando a amendoeira florescer, quando os gafanhotos se arrastarem, e quando os desejos naturais falharem. Então, o homem irá para o lar eterno e os enlutados descerão pelas ruas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'Lembra-te do teu Criador antes que o fio de prata seja cortado, ou a taça dourada seja esmagada, ou o jarro, estilhaçado na primavera, ou a roda d\'água seja quebrada no poço;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'antes que o pó volte à terra, de onde veio, e o espírito retorne a Deus que o deu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Vaidade das vaidades, diz o pregador, tudo é inútil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'O sábio era erudito e ensinava o conhecimento ao povo. Ele estudou e contemplou, e colocou em ordem muitos provérbios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'O pregador procurou escrever usando palavras vívidas e verdadeiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'As palavras dos sábios são como aguilhões. Como pregos bem fixados são as palavras dos mestres nas coleções de seus provérbios, que são ministrados por um pastor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Meu filho, fica ciente também disto: a escrita de muitos livros não tem limite, e o muito estudar traz cansaço ao corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'O fim de tudo o que se tem ouvido é: teme a Deus, e guarda Seus mandamentos, pois esse é todo o dever da humanidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Porque Deus trará toda ação a julgamento, juntamente com tudo o que está oculto, seja ele bom ou mau.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'O Cântico dos Cânticos, o qual é de Salomão. Uma jovem mulher falando para o seu amante:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, '\"Ah, que tu me beijes com os beijos de tua boca, teu amor é melhor do que vinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Teu óleo de ungir tem uma fragrância agradável; teu nome flui como perfume, então as mulheres jovens te amam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Leve-me contigo! Corramos!\" A mulher falando para si mesma: \"O rei me trouxe aos seus aposentos\". A mulher falando para seu amante: \"Eu estou alegre, em ti eu me regozijo, deixe-me celebrar teu amor, isto é melhor do que vinho. É natural que as outras mulheres enamorem de ti\". A mulher falando para as outras mulheres:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, '\"Eu sou morena, mas amável, filhas dos homens de Jerusalém, escura como as tendas de Quedar, amável como as cortinas de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Não repareis em mim porque eu sou morena, porque o sol me bronzeou. Os filhos de minha mãe estão aborrecidos comigo, eles me puseram a guardar as vinhas, mas minha própria vinha, eu não soube guardar\". A mulher falando para seu amante:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, '\"Dize-me, tu a quem amo, onde tu alimentas teu rebanho? Onde descansas seu rebanho ao meio dia? Porque eu deveria ser como alguém que vagueia entre os rebanhos dos seus companheiros?\". Seu amante respondeu a ela:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, '\"Se tu não sabes, mais bela entre as mulheres, segue o rastro das minhas ovelhas e pastoreia tuas cabras jovens perto das tendas dos pastores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Eu te comparo, meu amor, à égua atrelada a carruagem do Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Tua face é formosa com os ornamentos; e teu pescoço, com as joias raras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Eu te farei ornamentos de ouro cravados de prata\". A mulher falando de si mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, '\"Enquanto o rei se reclinava, meu nardo emitiu sua fragrância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Meu amado é para mim como um bolsa de mirra que passa a noite entre os meus seios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Meu amado é para mim como um ramo de flores de hena das vinhas de En Gedi\". Seu amante falando para ela:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, '\"Veja como tu és bela, meu amor; como tu és bela; teus olhos são como pombas\". A mulher falando para seu amante:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, '\"Veja como és belo, meu amado, como és belo. As plantas exuberantes servem nossa cama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'As vigas da nossa casa são de cedro, e os seus ramos são de cipreste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Eu sou apenas uma flor em uma planície, apenas um lírio em um vale\". O homem fala:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, '\"Assim como um lírio está entre espinhos, assim tu estás, minha amada, entre as filhas dos meus compatriotas\". A mulher fala consigo mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, '\"Como uma árvore de damasco está entre as árvores da floresta, assim é meu amado entre os homens jovens. Eu sento-me à sua sombra com grande prazer, e o seu fruto é doce ao meu paladar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Ele me trouxe ao salão de banquetes e seu estandarte sobre mim é o amor\". A mulher falando ao seu amado:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, '\"Sustenta-me com bolos de uvas passas e refresca-me com damascos, pois desfaleço de amor\". A mulher fala consigo mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, '\"A tua mão esquerda esteja debaixo de minha cabeça e tua mão direita me abraça\". A mulher fala às outras mulheres:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, '\"Eu quero que prometeis, filhas de Jerusalém, pelas gazelas e pelas corças dos campos, que não nos interrompam enquanto estamos fazendo amor\". A mulher fala para si mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, '\"Ouço o som do meu amado! Oh, aí vem ele, saltando sobre os montes, pulando sobre as colinas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Meu amado é como uma gazela ou um cervo jovem; vê, ele está atrás da nossa parede, olhando pelas janelas, espiando pelas grades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Meu amado falou comigo, dizendo: \'Levanta-te, minha amada, minha bela, vem comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Eis que o inverno passou; as chuvas pararam e se foram;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'as flores aparecem na terra; chegou o tempo da poda e do canto dos pássaros e o som das pombas é ouvido em nossa terra;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'a figueira amadurece seus figos, e as videiras florescem, exalando sua fragrância. Levante-te, minha amada, minha bela, e vem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Pomba minha que andas pelas fendas da rocha, nas fendas secretas dos penhascos da montanha, deixe-me ver o teu rosto. Deixa-me ouvir a tua voz, pois a tua voz é doce e o teu rosto é amável\'\". A mulher fala consigo mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, '\"Apanhai-me as raposas, as pequenas raposas que danificam as vinhas, pois as nossas vinhas estão floridas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Meu amado é meu, e eu sou dele; ele pasta entre os lírios com prazer\". A mulher falando ao seu amado:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, '\"Volta, meu amado, antes que as suaves brisas do amanhecer soprem e as sombras desapareçam. Volta depressa; sê como uma gazela ou um cervo jovem nas montanhas acidentadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'À noite em meu leito eu estava ansiando por meu amado; eu procurei por ele, mas não pude encontrá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Disse para mim mesma, \"Eu levantarei e percorrerei por toda a cidade, nas ruas e praças; eu buscarei meu amado\". Eu procurei por ele, mas eu não o encontrei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Encontrei os guardas enquanto eles estavam fazendo as rondas na cidade. Eu perguntei a eles, \"Viram meu amado?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Foi logo após passar pelos guardas que encontrei aquele a quem minha alma ama. Eu o agarrei e não o deixei ir, até que eu o introduzisse na casa de minha mãe, no quarto onde fui concebida. A mulher falando para as outras mulheres:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Eu quero que vocês jurem, filhas dos homens de Jerusalém, pelas gazelas e corças dos campos, que vocês não interromperão nosso namoro até que chegue ao fim. A jovem mulher falando consigo mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'O que vem subindo do deserto como uma coluna de fumaça, perfumado com mirra e incenso, com todos os perfumes vendidos por mercadores?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Olhe, é a liteira de Salomão; escoltada por sessenta guerreiros, sessenta soldados de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, '8 Eles são experientes com espadas e são especialistas em batalha. Cada um tem sua espada ao lado, armado contra o terror da noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'O Rei Salomão fez para si mesmo uma liteira de madeira do Líbano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'A liteira foi feita de prata; o encosto foi feito de ouro, e o assento forrado em púrpura. Seu interior foi amorosamente decorado pelas filhas dos homens de Jerusalém. Disse a jovem mulher para as mulheres de Jerusalém:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Filhas dos homens de Sião, saiam e contemplem o Rei Salomão, usando a coroa que recebeu de sua mãe em seu casamento, naquele dia feliz de sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Oh, tu és bela, meu amor; tu és bela! Por detrás do teu véu os teus olhos são como pombas. Teus cabelos são como um rebanho de cabras descendo do Monte Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Teus dentes são como um rebanho de ovelhas recém tosquiadas saindo do lavadouro. Cada uma tem o seu par de gêmeos e não há nenhuma entre elas sem cria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Teus lábios são como um fio escarlate, graciosa é a tua boca. Por trás do véu, tuas bochechas são como as metades de uma romã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Teu pescoço é como a torre de Davi, construída como sala de armas, nela estão pendurados mil escudos, todos os escudos de soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Teus dois seios são como dois filhos gêmeos de uma gazela pastando entre os lírios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Antes que o amanhecer chegue e as sombras fujam, eu irei ao monte de mirra e à colina do incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Tu és toda formosa, meu amor, e em ti não existe defeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Venha comigo do Líbano, minha noiva! Venha comigo do Líbano; desce do topo de Amana, do topo de Senir e Hermon, das covas dos leões, da montanha dos leopardos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Tu roubaste meu coração, minha irmã, minha noiva; tu roubaste meu coração, com apenas um olhar para mim, com apenas uma joia do seu colar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Quão belo é teu amor, minha irmã, minha noiva! Quão melhor é o teu amor do que o vinho! E a fragrância de teu perfume do que qualquer especiaria!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Teus lábios, minha noiva, escorrem mel; mel e leite estão debaixo de tua língua, a fragrância de tuas vestes é como a fragrância do Líbano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Minha irmã, minha noiva, tu és um jardim fechado, uma nascente selada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Teus renovos são um pomar de romãs com frutos seletos; e de flores de hena e nardo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'nardo e açafrão, cálamo e canela, com todo tipo de madeiras aromáticas, mirra, aloés e as mais finas especiarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Tu és fonte do jardim, um poço de água fresca, riachos fluindo do Líbano\". A jovem falando ao seu amado');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, '\"Desperte vento norte; venha vento sul; assoprem em meu jardim, para que as suas especiarias espalhem os seus aromas. Que o meu amado entre no seu jardim e saboreie alguns dos seus frutos escolhidos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Eu entrei no meu jardim, minha irmã, minha noiva; eu ajuntei minha mirra com minhas especiarias. Comi meus favos com meu mel; tomei meu vinho com meu leite. Os amigos falando aos amantes: \"Comam, amigos! Bebam e se embriaguem com o amor!\". A jovem fala a si mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, '\"Eu estava adormecida, mas meu coração estava acordado em um sonho. Eis o som do meu amado, batendo e dizendo: \'Abra a porta, minha irmã, minha amada, minha pomba, minha virgem, pois minha cabeça está molhada com orvalho; meu cabelo, com o orvalho da noite\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, '\'Já tirei meu manto; devo colocá-lo de novo? Já lavei meus pés; devo sujá-los?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Meu amado coloca sua mão pela abertura da fechadura da porta, e meu coração foi agitado por ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Eu me levantei para abrir a porta para o meu amado; minhas mãos estavam gotejando com mirra, meus dedos com mirra líquida, na maçaneta da porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Eu abri a porta para o meu amado, mas meu amado havia voltado e ido embora. Meu coração se entristeceu; eu fiquei desanimada. Procurei por ele, mas não o encontrei; chamei por ele, mas ele não me respondeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Os sentinelas que estavam perto da cidade me encontraram; eles me atacaram e me feriram. Os guardas das muralhas tiraram meu manto\". A jovem falando às mulheres da cidade:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, '\"Quero que prometais, filhas de Jerusalém, que, se encontrardes meu amado, lhe digais que estou doente por causa do meu amor por ele\". As mulheres de Jerusalém falando à jovem:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, '\"Como teu amado é melhor que outro homem amado, tu que és linda entre as mulheres? Por que teu amado é melhor que outro amado, para que nos peça que façamos um juramento como este?\". A jovem falando às mulheres da cidade:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, '\"Meu amado é radiante e corado, o melhor entre dez mil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Sua cabeça é como o ouro mais puro; seu cabelo é cacheado e tão preto quanto um corvo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Seus olhos são como pombos junto às correntes de água, lavados em leite, montados como joias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Suas bochechas são como camas de especiarias, exalando essências aromáticas. Seus lábios são lírios, derramando mirra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Seus braços são ouro polido adornado com jóias; seu abdome é marfim coberto com safiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Suas pernas são pilares de mármore, colocados em bases de ouro puro; sua aparência é como o Líbano, escolhido como os cedros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Sua boca é a mais doce; ele é completamente amável. Este é o meu amado, e este é o meu amigo, filhas de Jerusalém\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Para onde foi o teu amado, ó mais bela entre as mulheres? Em que direção foi o teu amado, para que nós possamos procurá-lo convosco? A jovem mulher falando para si mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Meu amado desceu para o seu jardim, aos canteiros de especiarias, para pastar no jardim e para ajuntar lírios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Eu sou do meu amado, e meu amado é meu; ele pastoreia em meio aos lírios com prazer. O amado da mulher falando a ela:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Tu és tão linda quanto Tirza, meu amor, tão amável quanto Jerusalém, tão inspiradora quanto um exército com suas bandeiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Vire os teus olhos para longe de mim, pois eles me perturbam. Teus cabelos são como um rebanho de cabras descendo das encostas do Monte Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Teus dentes são como um rebanho de ovelhas subindo do lavadouro. Cada uma tem um filhote gêmeo, e nenhuma delas está sem cria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Tuas bochechas são como metades de uma romã atrás do seu véu. O amado da mulher falando a ele mesmo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Existem sessenta rainhas, oitenta concubinas e incontáveis mulheres jovens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Mas minha pomba, minha imaculada, é única; ela é a filha especial de sua mãe; ela é a predileta de quem a gerou. As filhas dos meus camponeses a viram e a chamaram abençoada; as rainhas e as concubinas também a viram, e a elogiaram. O que as rainhas e as concubinas disseram:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, '\"Quem é esta que aparece como o amanhecer, tão bela como a lua, tão brilhante quanto o sol, tão inspiradora quanto um exército com suas bandeiras?\". O amado da mulher falando a ele mesmo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Eu desci ao bosque de nogueiras para examinar os brotos no vale, para ver se as videiras haviam brotado, e se as romãs estavam em flor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Eu estava tão feliz que senti como se estivesse andando na carruagem de um príncipe. O amado da mulher falando a ela:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Volte, volte, mulher perfeita. Volte, volte para que eu possa te contemplar. A jovem mulher falando para seu amado: Por quê tu olhas para mim, a mulher perfeita, como se eu estivesse dançando entre duas filas de dançarinas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, '\"Como seus pés são belos em suas sandálias, filha de príncipe! As curvas de suas coxas são como jóias, obras das mãos de um artesão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Seu umbigo é como uma taça redonda; onde nunca pode faltar vinho. Sua barriga é como um montão de trigo cercado de lírios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Teus seios são como dois filhotes gêmeos de uma gazela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Teu pescoço é como uma torre de marfim; Teus olhos são como os poços que ficam ao lado da porta de Bath Rabbim. Teu nariz é tão belo como a torre do Líbano que se avista de Damasco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Tua cabeça se ergue como o monte Carmelo; o cabelo em sua cabeça é vermelho escuro. O rei está encantado com suas tranças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Que linda e adorável tu és, minha amada, com seus deleites!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Tua altura é como de uma palmeira e teus seios como cachos de fruta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Eu pensei: \'Eu quero subir a palmeira; eu tomarei seus frutos\'. Que seus seios sejam como cachos de uvas, e o aroma de tua respiração como maçãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Que tua boca seja como o melhor vinho\", \"fluindo suavemente para meu amado, deslizando sobre nossos lábios e dentes\". A jovem mulher fala para seu amado:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, '\"Eu sou do meu amado e ele me deseja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Vem, meu amado, vamos fugir para o campo; vamos passar a noite nos povoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Levantemos cedo para ir aos vinhedos; vamos ver se as vinhas brotaram, se as suas flores desabrocharam, e se as romãzeiras estão em flor. Ali eu te darei o meu amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'As mandrágoras exalam sua fragrância; à entrada da casa onde moramos, estão toda sorte de variedades de frutas, novas e velhas, que eu guardei para você, meu amado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, '\"Eu gostaria que fosses como meu irmão, amamentado pelos seios da minha mãe. Então sempre que eu te encontrasse lá fora, eu poderia beijar-te, e ninguém me desprezaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Eu te guiaria e te levaria para dentro da casa da minha mãe, e tu me ensinarias. Eu te daria vinho aromático para beber e um pouco do suco de minhas romãs\". A jovem mulher falando para si mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, '\"Sua mão esquerda está sob minha cabeça e sua mão direita me abraça\". A mulher falando para as outras mulheres:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, '\"Eu quero que jureis, filhas dos homens de Jerusalém, que vós não interrompais nosso amor até que ele acabe\". As mulheres de Jerusalém falando:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, '\"Quem é essa que está vindo do deserto, inclinando-se em seu amado?\". A jovem mulher falando para seu amor: \"Eu te despertei debaixo da macieira; ali sua mãe te concebeu; ali ela te deu a luz, ela te trouxe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Põe-me como um selo no teu coração, como selo em teu braço, pois o amor é forte como a morte. A paixão é tão implacável quanto o Sheol; é explosão de fogo, é uma labareda de fogo, uma chama mais quente do que qualquer outro fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Águas torrenciais não poderiam apagar o amor, nem a inundação poderia afogá-lo. Se um homem desse todos os bens de sua casa por amor, a oferta seria completamente desprezada\". Os irmãos da jovem mulher falando entre eles:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, '\"Nós temos uma pequena irmã, e ela ainda não tem seios formados. O que podemos fazer para nossa irmã no dia que ela for prometida em casamento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Se ela for uma parede, nós construiremos nela uma torre de prata. Se ela for uma porta, nós a decoramos com tábuas de cedro\". A jovem falando de si mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, '\"Eu era uma parede, mas meus seios agora são como torres de fortaleza, então eu sou completamente madura aos seus olhos\". A jovem falando de si mesma:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, '\"Salomão tinha uma vinha em Baal-Hamom. Ele arrendou a vinha para aqueles que a manteriam. Cada um tinha que trazer doze quilos de prata por seus frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Minha vinha é só minha, os doze quilos de prata pertecem a ti, meu querido Salomão, e os dois quilos e meio são para aqueles que a mantêm por seus frutos\". O amante falando para ela:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, '\"Vós que viveis nos jardins, meus companheiros estão ouvindo sua voz; deixe-me ser o único que ouve também\". A jovem mulher falando para seu amante:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, '\"Apressa-te, meu amado, e sê como a gazela ou um jovem cervo pelos montes perfumados!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Visão de Isaías, filho de Amoz, que teve a respeito de Judá e Jerusalém, nos dias de Uzias, Jotão, Acaz e Ezequias, reis de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Ouvi, ó céus, e escuta, ó terra, porque Yahweh disse: \"Tenho nutrido e criado filhos, mas eles se rebelaram contra Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'O boi conhece o seu dono, e o jumento, o seu cocho, mas Israel não tem conhecimento, Israel não entende\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Ai da nação pecadora! Povo carregado de iniquidade, descendência de malfeitores, filhos que agem corruptamente! Eles abandonaram Yahweh, desprezaram o Santo de Israel e afastaram-se Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Por que seríeis ainda castigados? Por que vos rebelais cada vez mais? A cabeça toda está doente, todo o coração está fraco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Da sola do pé até a cabeça, não há parte sã, senão feridas, contusões e chagas abertas, que não foram limpas nem fechadas, nem atadas e tratadas com óleo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Vosso país está arruinado, vossas cidades estão queimadas, vossos campos — em vossa presença, destruídos por estrangeiros — abandonados e devastados, tomados por estrangeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'A filha de Sião foi abandonada como uma cabana na vinha, como uma choupana no pepinal, como uma cidade sitiada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Se Yahweh dos Exércitos não nos tivesse deixado alguns remanescentes, seríamos como Sodoma, e semelhantes a Gomorra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Ouvi a palavra de Yahweh, vós governantes de Sodoma; escutai a lei do vosso Deus, ó povo de Gomorra:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, '\"O que são as multidões de sacrifícios para Mim?\", diz Yahweh. \"Eu estou farto dos sacrifícios de carneiro e da gordura de animais cevados; não Me agrado do sangue de bois, cordeiros ou bodes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Quando viestes a Mim, quem vos pediu que pisásseis nos Meus átrios?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Não continueis a trazer sacrifícios inúteis; o incenso é abominação para Mim, vossas luas novas e assembleias de sábado. Eu não suporto vossas reuniões solenes, todas repletas de perversidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Eu odeio vossas luas novas e vossas festas solenes. Elas são um fardo para Mim; estou cansado de aturá-las!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Assim, quando levantardes vossas mãos em oração, esconderei Meus olhos de vós; mesmo que façais muitas orações, não as ouvirei, pois vossas mãos estão cheias de sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Lavai-vos e limpai-vos! Removei toda a maldade das vossas obras diante de Mim! Parai com a maldade;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'aprendei a fazer o bem; buscai a justiça; acabai com a opressão; fazei justiça ao órfão; defendei a viúva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Vinde agora, e raciocinemos juntos\" — diz Yahweh — \"ainda que os vossos pecados sejam como o escarlate, eles se tornarão brancos como a neve; mesmo que eles sejam vermelhos como o carmesim, eles se tornarão como a branca lã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Se estiverdes dispostos a obedecer, comereis o melhor da terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'mas se recusardes e vos rebelardes, a espada vos devorará\", pois a boca de Yahweh o disse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Como a cidade fiel se tornou prostituta! Ela — que era cheia de justiça, que era cheia de retidão — agora está cheia de assassinos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Tua prata tornou-se impura, teu vinho misturou-se com água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Teus príncipes são rebeldes e companheiros de ladrões; todos amam subornos e correm atrás de recompensas. Não defendem os órfãos, nem a petição da viúva que chega diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Portanto, esta é a declaração do Senhor, Yahweh dos Exércitos, o Poderoso de Israel: \"Ai deles! Buscarei vingança contra os Meus adversários. Sim, Eu Me vingarei dos Meus inimigos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Voltarei Minha mão contra vós, purificarei vossa escória com potassa e tirarei todas as vossas impurezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Eu restaurarei vossos juízes como antes, e vossos conselheiros como no início; depois disso, sereis chamados de cidade de retidão, uma cidade fiel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Sião será redimida com justiça; e com retidão, os arrependidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Os rebeldes e pecadores serão esmagados juntos, e aqueles que abandonarem Yahweh também o serão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Sereis envergonhados pelos carvalhos sagrados que desejastes e ficareis envergonhados pelos jardins que escolhestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Pois sereis como um carvalho que perde suas folhas, e como um jardim que não tem água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'O homem forte será como a estopa, e seu trabalho, como uma fagulha; ambos queimarão juntos, e ninguém apagará o fogo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'As coisas que Isaías, filho de Amoz, viu, relacionadas a Judá e a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Acontecerá que, nos últimos dias, o monte da casa de Yahweh será estabelecido como o mais alto dos montes, será exaltado sobre as colinas, e todas as nações correrão para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Muitos povos virão e dirão: \"Vinde! Subamos ao monte de Yahweh, à casa do Deus de Jacó. Ali, Ele nos ensinará os Seus caminhos e andaremos em Suas veredas\". Pois de Sião sairá a lei, a palavra de Yahweh virá de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Ele julgará entre as nações e dará vereditos para muitos povos; eles converterão suas espadas em arados e suas lanças, em foices; nação nenhuma levantará a espada contra outra nação, nem jamais treinará para a guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Vinde, ó casa de Jacó, e andemos na luz de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Pois Tu abandonaste o Teu povo, a casa de Jacó, porque eles estão cheios dos costumes do leste e de adivinhadores, como os filisteus, e fazem acordos com os filhos dos estrangeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'A terra deles está cheia de prata e ouro, e não há limites para sua riqueza; também está repleta de cavalos, não há limites para as suas carruagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Sua terra está cheia de ídolos; eles adoram o trabalho das próprias mãos, objetos que seus dedos fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'O povo se curvará e indivíduos cairão; portanto, não os levantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Vai até os locais rochosos e esconde-te no chão por causa do terror que vem de Yahweh, de Sua glória e majestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'O olhar altivo do homem será humilhado, a arrogância do homem será derrubada, e somente Yahweh será exaltado naquele dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Pois haverá um dia em que Yahweh dos Exércitos irá contra todo aquele que é orgulhoso e exaltado e contra todo aquele que é arrogante — e este será humilhado;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'contra todos os cedros do Líbano, que são altos e elevados, e contra todos os carvalhos de Basã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'Naquele dia, Yahweh dos Exércitos será contra todos os altos montes, contra todas as colinas elevadas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'contra toda torre alta, contra todo muro fortificado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'contra todos os navios de Társis e contra todas as belas embarcações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'O orgulho do homem será humilhado e a sua arrogância cairá. Somente Yahweh será exaltado naquele dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Os ídolos passarão completamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Os homens fugirão para as cavernas nas rochas e para os buracos no chão, por causa do terror que vem de Yahweh e do esplendor da Sua majestade, quando Ele Se levantar para aterrorizar a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Naquele dia, o povo jogará fora os seus ídolos de prata e de ouro — que fizeram para serem adorados. Eles vão lançá-los às toupeiras e aos morcegos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'O povo correrá para as cavernas nas rochas e para dentro das fendas dos penhascos, devido ao terror que vem de Yahweh e da Sua glória e majestade, quando Ele Se levantar para aterrorizar a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Parai de confiar no homem, cujo sopro de vida está em suas narinas, pois que valor ele tem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Eis que o Senhor Yahweh dos Exércitos está prestes a tirar de Jerusalém e de Judá o sustento e o apoio: todo o suprimento de pão, todo o suprimento de água;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'e o homem poderoso, o guerreiro, o juiz, o profeta, o adivinhador, o ancião;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'o capitão de cinquenta, o cidadão respeitado, o conselheiro, o hábil artesão e o mago.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, '\"Colocarei jovens para serem seus líderes, e os meninos governarão sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'As pessoas serão oprimidas umas pelas outras, cada um pelo seu vizinho; as crianças insultarão os idosos e os corrompidos desafiarão pessoas de honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Um homem agarrará seu irmão na casa do seu pai e dirá: \'Tu tens um casaco, sê o nosso comandante. Que estas ruínas fiquem sob o teu poder\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Naquele dia, ele gritará e dirá: \'Não sou médico, eu não tenho pão ou vestimenta. Não me faças comandar este povo\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Pois Jerusalém está arruinada, e Judá caiu, porque suas falas e suas ações são contra Yahweh, para desafiarem a glória de Seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'O olhar em suas faces os denuncia; e eles falam dos seus pecados como o povo de Sodoma, eles não os escondem. Ai deles! Trouxeram o mal para si mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Dizei aos justos que isto será bom para eles, pois comerão do fruto de suas ações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Ai do corrupto! Tudo lhe irá mal, pois ele receberá do que suas mãos têm feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Quanto ao Meu povo, crianças são seus opressores e mulheres governam sobre eles. Ó, Meu povo, teus líderes te enganam e te confundem o caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Yahweh Se levanta para pleitear; Ele Se levanta para julgar as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Yahweh virá com julgamento contra os anciãos e os líderes do Seu povo. \"Vós tendes devorado a vinha. O que foi saqueado dos pobres está em vossas casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Por que esmagais o Meu povo e triturais a face dos pobres?\" — Esta é a declaração do Senhor, Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Yahweh diz que as filhas de Sião são orgulhosas, caminham de cabeça erguida, flertam com seus olhos, dão passos curtos ao andar, fazendo um tinir com os enfeites de seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'Porque elas são assim, o Senhor formará feridas nas cabeças das filhas de Sião, Yahweh raspará suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Naquele dia, o Senhor removerá suas lindas joias dos tornozelos, os turbantes, os colares,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'os pingentes das orelhas, os braceletes e os véus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'os lenços de cabelo, os ornamentos do tornozelo, os cintos, as caixas de perfumes e os amuletos de sorte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Ele removerá os anéis e as joias do nariz,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'as vestes festivas, os mantos, os véus e as bolsas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'os espelhos de mão, os linhos finos, os enfeites da cabeça e os xales.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Em vez de perfumes doces haverá mau cheiro; em vez de cinto, uma corda; em vez de cabelo bem penteado, calvície; em vez de um manto, uma cobertura de pano de saco; e cicatriz, em vez de beleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Teus homens cairão pela espada e teus guerreiros cairão na guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Os portões de Jerusalém lamentarão e chorarão. Desolada, Sião se sentará no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Naquele dia, sete mulheres tomarão um só homem, e dirão: \"Comeremos nosso próprio alimento, vestiremos nossa própria roupa, mas permita que tomemos teu nome para remover nossa vergonha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Naquele dia, o renovo de Yahweh será lindo e glorioso e o fruto da terra será saboroso e agradável para os sobreviventes em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Então, o que ficar em Sião e o que permanecer em Jerusalém será chamado santo, isto é, todo aquele que for registrado entre os vivos em Jerusalém,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'quando o Senhor tiver lavado a imundice das filhas de Sião e limpado as manchas de sangue do meio de Jerusalém, pelo espírito de justiça e pelo espírito de fogo ardente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Então, sobre todo o monte Sião e sobre suas assembleias, Yahweh criará nuvem e fumaça de dia, e o brilho de uma chama de fogo à noite. Isto será uma cobertura sobre toda a glória;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'será um abrigo contra o sol durante o calor do dia; um refúgio e uma cobertura contra a tempestade e a chuva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Cantarei ao meu amado uma canção de amor sobre a Sua vinha. Meu amado possuía uma vinha em uma colina fértil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Ele a cavou, removeu as pedras e a plantou com uma videira da melhor qualidade. Construiu uma torre no meio dela e edificou também um lagar. Ele esperava que ela produzisse uvas boas, porém, produziu uvas selvagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'E agora, habitantes de Jerusalém e homens de Judá, julgai entre Mim e a Minha vinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'O que mais poderia ser feito à Minha vinha que Eu já não tenha feito? Quando Eu esperava boas uvas, por que produziu uvas selvagens?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Agora Eu vos direi o que farei com a Minha vinha: removerei a cerca e será transformada num pasto; derrubarei o seu muro e ela será pisada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Eu a devastarei, e ela não será podada nem capinada; mas sarças e espinhos brotarão nela, e ordenarei às nuvens que não derramem chuva sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Pois a videira de Yahweh dos Exércitos é a casa de Israel, e os homens de Judá são Sua agradável plantação. Ele esperou por justiça, mas, em vez disso, houve matança; esperou por retidão, mas houve clamor por socorro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Ai daqueles que juntam casa a casa, campo a campo, até que não haja mais nenhum lugar, e se tornam os únicos donos da terra!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Yahweh dos Exércitos me disse que muitas casas ficarão vazias, até mesmo as grandiosas e impressionantes ficarão sem moradores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Pois uma vinha de dez jeiras dará apenas um bato, e um ômer de semente dará apenas um efa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Ai daqueles que se levantam de manhã cedo para buscar bebida forte, aqueles que se demoram noite adentro até que o vinho os inflame!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Eles fazem banquetes com harpas, liras, tamborins, flautas e vinho; mas não reconhecem o trabalho de Yahweh, nem consideram os feitos de Suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Portanto, o Meu povo foi levado ao cativeiro por falta de entendimento; seus nobres estão com fome, e o povo comum não tem nada para beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Por isso, o Sheol aumentou o seu apetite e abriu grandemente a sua boca; seus nobres, o povo, seus líderes e os foliões, e os que estão felizes entre eles descem para o Sheol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'O homem se curvará e a humanidade será humilhada; os olhos dos altivos serão rebaixados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Yahweh dos Exércitos será exaltado em Sua justiça, e Deus, o Santo, Se mostrará santo por meio de Sua justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Então as ovelhas pastarão como em seu próprio pasto, e os cordeiros pastarão nas ruínas como estrangeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Ai daqueles que puxam a iniquidade com cordas de futilidade, e puxam o pecado com corda de carroça!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Ai daqueles que dizem: \"Que Deus Se apresse, que Ele aja com rapidez para que vejamos isso acontecer; e que os planos do Santo de Israel se aproximem e cheguem, para que os conheçamos!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Ai daqueles que chamam o mal de bem e o bem de mal; que representam a escuridão como luz e a luz como escuridão; que representam o amargo como doce e o doce como amargo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Ai daqueles que são sábios aos seus próprios olhos e prudentes em seu próprio entendimento!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Ai daqueles que são campeões em beber vinho e mestres em misturar bebidas fortes;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'daqueles que absolvem o culpado em troca de dinheiro, e privam o inocente de seus direitos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Portanto, assim como a língua de fogo devora o restolho, e como a palha se queima, assim suas raízes apodrecerão e sua flor será levada como a poeira. Pois eles rejeitaram a lei de Yahweh dos Exércitos e desprezaram a palavra do Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Por isso, a ira de Yahweh está acesa contra o Seu povo, e Ele levantou Sua mão contra eles e os puniu; as montanhas tremem, e seus cadáveres são como lixo nas ruas. Apesar de tudo isso, Sua ira não retrocede, e Sua mão continua estendida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Ele levantará uma bandeira para as nações distantes e assobiará aos que estão nos confins da terra. Olhai, eles virão rápida e prontamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Não há entre eles cansados ou quem tropece; ninguém sente sono ou dorme; nem seus cintos se afrouxam, nem suas sandálias se arrebentam;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'suas flechas são afiadas e seus arcos estão curvados; os cascos de seus cavalos são como pederneiras e suas carruagens correm como redemoinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Seu rugido será como de leão. Eles rugirão como leões jovens; rugirão e agarrarão suas presas, e as levarão para longe, sem ninguém para resgatá-las.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Naquele dia, eles rugirão contra a presa, como o rugido do mar. Se alguém olhar para a terra, verá escuridão e aflição, pois até a luz será escurecida pelas nuvens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'No ano em que o rei Uzias morreu, eu vi o Senhor assentado em um trono alto e sublime; e a bainha do Seu manto enchia o templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Acima Dele, estavam os serafins; cada um tinha seis asas: com duas cobriam o rosto, com duas cobriam os pés, e com duas voavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'E diziam, em alta voz, uns aos outros: \"Santo, Santo, Santo é Yahweh dos Exércitos! Toda a terra está cheia da Sua glória\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'As bases das portas tremiam à voz dos que clamavam, e a casa se encheu de fumaça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Então eu disse: \"Ai de mim, pois estou perdido! Porque sou um homem de lábios impuros e vivo no meio de um povo de lábios impuros, e os meus olhos viram o Rei, Yahweh dos Exércitos!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Então, um dos serafins voou até mim, trazendo em sua mão uma brasa que havia tirado do altar com uma tenaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Ele tocou minha boca com a brasa e disse: \"Vê! Isto tocou os teus lábios, tua culpa foi removida e teu pecado, perdoado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Ouvi a voz do Senhor dizendo: \"A quem enviarei? Quem irá por Nós?\" Então eu disse: \"Aqui estou eu, envia-me\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Ele disse: \"Vai e dize a este povo: \'Ouvireis, mas não entendereis; vereis, mas não percebereis\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Torna o coração deste povo insensível; seus ouvidos fiquem surdos e seus olhos, cegos, para que eles não vejam com seus olhos, não ouçam com seus ouvidos, não entendam com o coração, e não se voltem e sejam curados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Então eu disse: \"Senhor, por quanto tempo?\". Ele me respondeu: \"Até que as cidades fiquem devastadas e sem habitantes, as casas fiquem sem moradores e a terra se torne despovoada;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'e até que Yahweh mande o povo para longe, e grande seja a solidão da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Mesmo que um décimo do povo permaneça nela, será novamente destruída; como o terebinto e o carvalho que são derrubados, e seu tronco permanece, assim a santa semente estará nesse toco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Durante os dias de Acaz, filho de Jotão, filho de Uzias, rei de Judá, aconteceu que Rezim, rei da Síria, e Peca, filho de Remalias, rei de Israel, subiram a Jerusalém para atacá-la, mas não conseguiram prevalecer contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Foi relatado à casa de Davi que a Síria era aliada de Efraim. O seu coração e o coração do seu povo agitaram-se, como as árvores do bosque se agitam com o vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Então, Yahweh disse a Isaías: \"Sai com o teu filho Sear-Jasube para te encontrares com Acaz, no final do canal do tanque superior, no caminho do campo do Lavandeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'Dize-lhe: Sê cuidadoso e acalma-te. Não temas nem te intimides por causa desses dois pedaços de lenha fumegantes; nem pela ira ardente de Rezim e da Síria, nem por Peca, filho de Remalias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'A Síria, Efraim e o filho de Remalias têm planejado o mal contra ti, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, '\'Vamos atacar e aterrorizar Judá; vamos conquistá-la e fazer reinar sobre ela o nosso rei, o filho de Tabeel\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'O Senhor Yahweh diz: Isso não sucederá, jamais acontecerá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'pois a capital da Síria é Damasco e o cabeça de Damasco é Rezim. Dentro de sessenta e cinco anos, Efraim será destruída e deixará de ser povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'A capital de Efraim é Samaria, e o cabeça de Samaria é o filho de Remalias. Se não persistirdes na fé, certamente, não permanecereis seguros”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'O Senhor falou novamente a Acaz, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, '\"Pede um sinal a Yahweh, teu Deus; um sinal que seja nas profundezas ou nas alturas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Porém, Acaz respondeu: \"Não pedirei, nem porei Yahweh à prova\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Então, Isaías respondeu: \"Ouvi, ó casa de Davi. Não vos é o bastante que testeis a paciência das pessoas? Deveis ainda testar a paciência do meu Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Portanto, o próprio Senhor vos dará um sinal: eis que a virgem conceberá e dará à luz um filho, e ele será chamado Emanuel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Ele comerá coalhada e mel até que saiba recusar o mal e escolher o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Pois antes que a criança saiba recusar o mal e escolher o bem, a terra desses dois reis, a quem temes, será desolada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Yahweh trará sobre ti, sobre o teu povo e sobre a casa do teu pai, dias como nunca houve, desde que Efraim se separou de Judá — Ele vos trará o rei da Assíria\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Naquele tempo, Yahweh assobiará às moscas das extremidades dos rios do Egito e às abelhas da terra da Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Elas virão e pousarão nos desfiladeiros, dentro das fendas das rochas, sobre os arbustos espinhosos, em todas as pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Naquele tempo, o Senhor usará uma navalha que foi alugada para além do rio Eufrates — que é o rei da Assíria — para raspar a cabeça, assim como os pelos das pernas e também removerá a barba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Naquele dia, um homem criará uma novilha e duas ovelhas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'e, por causa da abundância de leite, ele comerá coalhada, pois todo aquele que restar na terra comerá coalhada e mel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Naquele tempo, onde havia mil vinhas no valor de mil siclos de prata, não haverá nada além de sarças e espinhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Os homens entrarão ali para caçar com arco e flecha, pois toda aquela terra será sarças e espinhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Eles permanecerão distantes de todas as colinas que antes cultivavam com a enxada, por medo das sarças e dos espinhos; mas ali será lugar onde os bois e as ovelhas pastarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Yahweh me disse: \"Toma uma grande tábua e escreve nela: ‘Maer-Salal-Has-Baz’\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Convocarei testemunhas fiéis para atestar por mim, chamarei Urias, o sacedorte, e Zacarias, filho de Jeberequias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Deitei-me com a profetisa, ela concebeu e deu à luz um filho. Então, Yahweh me disse: \"Dá-lhe o nome de Maer-Salal-Has-Baz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Pois, antes que a criança saiba dizer \'papai\' ou \'mamãe\', as riquezas de Damasco e os despojos de Samaria serão levados pelo rei da Assíria\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Yahweh tornou a falar comigo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, '\"Porque este povo rejeitou as águas calmas de Siloé, e alegrou-se com Rezim e com o filho de Remalias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'eis que o Senhor fará vir sobre ele as poderosas e impetuosas águas do rio — o rei da Assíria e toda a sua glória —, que transbordarão ao longo de todos os canais e extravasarão por suas margens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'O rio passará por Judá e a inundará até que alcance o pescoço. A extensão de suas margens encherá a sua terra por completo, ó Emanuel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Ó povos, sereis destruídos! Ouvi, todos vós que sois de lugares distantes: armai-vos para a guerra, mas sereis quebrados em pedaços; sim, mesmo prontos para a guerra, sereis despedaçados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Mesmo que façais um plano, este será frustrado. Mesmo que deis ordens, nada se cumprirá, pois Deus está conosco!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Pois Yahweh, com Sua mão forte sobre mim, advertiu-me a não andar pelo caminho deste povo, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, '\"Não chames tudo de conspiração, como faz este povo; não temas o que eles temem, e não fiques aterrorizado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'É a Yahweh dos Exércitos a Quem deves santificar-te; seja Ele o teu temor, pois Ele é o único de Quem deves ter pavor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Ele te será por santuário, mas servirá como uma pedra de tropeço e uma rocha de escândalo para as duas casas de Israel, e de armadilha e de laços para o povo de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Muitos tropeçarão e cairão; e serão destruídos, enlaçados e capturados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Conserva o testemunho, sela o registro, entrega-o aos Meus discípulos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Esperarei por Yahweh, que esconde Sua face da casa de Jacó, e O aguardarei com confiança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Vede! Aqui estou, com os filhos que Yahweh me deu, para sinais e maravilhas em Israel, da parte de Yahweh dos Exércitos, que habita no monte Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Quando vos falarem: \"Consultai os médiuns e os feiticeiros, aqueles que sussurram e murmuram encantamentos! Porventura, não deveria um povo consultar seus deuses? Não se deveria consultar os mortos em favor dos vivos?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Respondei: \"Consultai a Lei e o Testemunho!\" Se não falarem dessa forma, é porque não há luz neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Eles passarão pela terra em grande fome e aflição. Quando tiverem fome, ficarão irados e, ao olharem para cima, amaldiçoarão o seu rei e o seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'Eles olharão para a terra e verão sofrimento, escuridão e tristeza de aflição. E serão lançados em densas trevas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Não haverá mais escuridão para aquela que estava angustiada. Em tempos antigos, Deus humilhou a terra de Zebulom e a terra de Naftali; porém, depois disso, Ele a tornará gloriosa, desde o mar, além do Jordão, Galileia das nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'O povo que andava em trevas viu uma grande luz; e, sobre os que habitavam na terra da sombra da morte, resplandeceu a luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Tu multiplicaste a nação e lhe aumentaste a alegria; eles se alegrarão diante de Ti, como se regozijam no tempo da colheita e como se alegram os homens quando repartem os despojos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Pois Tu tens quebrado o jugo de sua carga, a trave dos seus ombros, o bastão do seu opressor, como fizeste no dia de Midiã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Pois todo calçado daqueles que andavam em combate e toda capa revolvida em sangue serão queimados, como lenha no fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Porque um menino nos nasceu, um filho nos foi dado; o governo estará sobre os Seus ombros; e o Seu nome será: Maravilhoso Conselheiro, Deus Forte, Pai da Eternidade, Príncipe da Paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'O crescimento do Seu governo e da Sua paz não terá fim; Seu governo será sobre o trono de Davi e sobre o seu reino, para o estabelecer e sustentá-lo com justiça e retidão, desde agora e para sempre. O zelo de Yahweh dos Exércitos fará isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'O Senhor enviou uma palavra contra Jacó, e ela caiu sobre Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Todos saberão, inclusive Efraim e os habitantes de Samaria, que, com orgulho e coração arrogante, dizem:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, '\"Os tijolos caíram, mas reconstruiremos com pedras lavradas; os sicômoros foram cortados, mas colocaremos cedros no lugar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Portanto, Yahweh suscitará contra eles os adversários de Rezim e instigará seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Os sírios do leste e os filisteus do oeste devorarão Israel com a boca aberta. Com tudo isso, porém, a ira de Yahweh não será apaziguada, e Sua mão continuará estendida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Mas o povo não se voltou para quem o atingiu, nem buscou Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Portanto, Yahweh cortará de Israel a cabeça e a cauda, seu ramo e seu junco, num único dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'O líder e os nobres são a cabeça; o profeta que ensina mentiras é a cauda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Aqueles que guiam este povo o desencaminham, e aqueles que são conduzidos por eles são engolidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Portanto, o Senhor não Se alegrará com seus jovens, nem terá compaixão de seus órfãos e viúvas, visto que todos são corruptos e malfeitores, e toda boca profere tolices. Mesmo assim, não cessou a Sua ira, e permanece estendida a Sua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'A maldade queima como fogo, que devora os cardos e os espinhos, incendiando as matas da floresta, fazendo crescer uma coluna de fumaça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Através da transbordante ira de Yahweh dos Exércitos, a terra é queimada e o povo é como combustível para o fogo; nenhum homem poupa seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Eles agarrarão a comida da direita e ainda estarão com fome, comerão a comida da esquerda, mas não ficarão satisfeitos. Cada homem comerá a carne de seu próprio braço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manassés devorará Efraim e Efraim devorará Manassés; e, juntos, atacarão Judá. Mas, mesmo com tudo isso, a ira de Yahweh não se apartará, pois Sua mão continuará estendida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Ai daqueles que promulgam leis injustas e prescrevem decretos desonestos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Eles privam de justiça os necessitados, roubam os direitos dos pobres do Meu povo, despojam as viúvas e fazem de presa o órfão!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'O que vós fareis no dia do julgamento quando a destruição vier de longe? A quem vós correreis em busca de ajuda, e onde deixareis as vossas riquezas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Nada restará, e vos humilhareis entre os prisioneiros ou caireis entre os mortos. Com tudo isso, Sua ira não cessará e a Sua mão continuará estendida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Ai da Assíria, o cajado da Minha ira, a vara pela qual Eu aplico a Minha fúria!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Eu a envio contra uma nação arrogante, contra o povo que fez transbordar a Minha ira. Eu lhe ordenei pegar o espólio, arrebatar a presa e pisá-los como lama nas ruas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Mas essa não é a intenção do rei da Assíria, nem é esse o seu pensamento; antes, está em seu coração destruir e eliminar muitas nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Pois ele diz: \"Por acaso, todos os meus príncipes não são reis?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Não é Calno como Carquêmis? Não é Hamate como Arpade? Não é Samaria como Damasco?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Assim como a minha mão derrotou os reinos idólatras, os quais esculpiram imagens melhores do que as de Jerusalém e Samaria,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'assim como fiz a Samaria e a seus ídolos sem valor, não irei também fazer o mesmo a Jerusalém e aos seus ídolos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Quando o Senhor tiver terminado o Seu trabalho no monte Sião e em Jerusalém, Ele dirá: \"Eu punirei o discurso do coração arrogante do rei da Assíria e seu olhar orgulhoso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Pois ele diz: \"Por meio da minha força e da minha sabedoria, eu agi, pois tenho compreensão; removi as fronteiras dos povos, roubei seus tesouros e, como um homem poderoso, abati seus habitantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Minha mão capturou as riquezas das nações, como a um ninho e, como quem junta ovos abandonados, eu juntei toda a terra. E ninguém bateu suas asas, ou abriu sua boca, ou murmurou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Terá o machado orgulho de si mesmo contra aquele que o manuseia? Aplaudirá o serrote a si mesmo mais do que àquele que o usa? É como se a vara pudesse levantar aquele que a levanta, ou como se um bastão de madeira pudesse levantar uma pessoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Por essa razão, o Senhor Yahweh dos Exércitos enviará magreza entre Seus guerreiros de elite; e, debaixo de Sua glória, haverá um incêndio queimando como fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'A luz de Israel se tornará um fogo, e seu Santo, uma chama; queimará e devorará seus espinhos e arbustos em um dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Yahweh consumirá a glória de sua floresta e de sua terra frutífera, a alma e o corpo; será como a vida de um homem doente que se esvai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'O restante das árvores de sua floresta será tão pouco, que uma criança poderá contar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Naquele dia, o restante de Israel, os da família de Jacó que escaparam, não mais confiarão naquele que os derrotou, mas, certamente, dependerão de Yahweh, o Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'O restante de Jacó retornará ao Deus poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Pois ainda que teu povo, Israel, seja como a areia da praia, somente um remanescente deles retornará. A destruição está decretada, como uma demanda transbordante de justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Pois o Senhor, Yahweh dos Exércitos, executará a destruição determinada sobre toda esta terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Por isso, o Senhor Yahweh dos Exércitos diz: \"Meu povo que vive em Sião, não tenhais medo do assírio. Ele vos golpeará com a vara e elevará seu cajado contra vós, como os egípcios fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Não tenhais medo dele, pois, em um curto período de tempo, a Minha indignação contra vós acabará e a Minha ira servirá para a destruição dele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Naquele tempo, Yahweh dos Exércitos usará um chicote contra eles, como quando Ele derrotou Midiã junto à rocha de Orebe. Ele estenderá Seu cajado sobre o mar e o levantará, como fez no Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Naquele dia, a carga será tirada do teu ombro e o jugo será destruído do teu pescoço, e o jugo será destruído por causa da gordura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Os inimigos chegaram a Aiate e passaram por Migrom; armazenaram suas provisões em Micmás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Eles atravessaram o desfiladeiro e se alojaram em Geba. Ramá treme e Gibeá de Saul fugiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Chora em alta voz, ó filha de Galim! Dá ouvidos, ó Laís! Pobre de ti, Anatote!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena está fugindo, e os habitantes de Gebim correm em busca de segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Hoje os inimigos pararão em Nobe e agitarão o punho junto à montanha da filha de Sião, o monte de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Eis que o Senhor, Yahweh dos Exércitos, cortará fora os ramos com um horripilante estrondo; as maiores árvores serão derrubadas e os elevados serão abatidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Ele derrubará o matagal da floresta com um machado, o Líbano cairá pela mão do Poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Um ramo brotará a partir do tronco de Jessé, um arbusto crescerá da sua raiz e dará fruto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'O Espírito de Yahweh repousará sobre Ele, o Espírito de sabedoria e de entendimento, o Espírito de instrução e de poder, o Espírito de conhecimento e de temor a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Seu prazer será o temor a Yahweh. Ele não julgará pelo que Seus olhos veem, nem decidirá pelo que Seus ouvidos ouvem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Ao invés disso, Ele julgará os pobres com justiça e decidirá, de forma justa, a favor dos humildes da terra. Ele ferirá a terra com a vara da Sua boca, e, com o sopro dos Seus lábios, matará o corrupto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'A justiça será o cinto dos Seus lombos, e a fidelidade, o cinto ao redor da Sua cintura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'O lobo habitará com o cordeiro, o leopardo se deitará com o cabrito, o bezerro, o leãozinho e o bezerro engordado, juntos. Uma criança pequena os conduzirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'A vaca e o urso pastarão juntos, os seus filhotes deitarão um ao lado do outro, o leão comerá palha, como o boi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Um bebê brincará em cima do buraco da cobra e a criança desmamada colocará a mão na toca da serpente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Ninguém ferirá nem causará destruição em todo o Meu santo monte; pois a terra será cheia do conhecimento de Yahweh, como as águas cobrem o mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Naquele dia, a raiz de Jessé será como uma bandeira para os povos. As nações A procurarão, e Seu lugar de descanso será glorioso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Naquele dia, o Senhor, novamente, estenderá Sua mão para resgatar o remanescente do Seu povo, que permanece na Assíria, no Egito, em Patros, na Etiópia, em Elão, em Sinar, em Hamate e nas ilhas do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Ele levantará uma bandeira para as nações e recolherá os desterrados de Israel e os dispersos de Judá desde os quatro cantos da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Ele cessará a inveja de Efraim e as hostilidades de Judá serão eliminadas. Efraim não invejará Judá, e Judá não será hostil a Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Em vez disso, eles se lançarão sobre as colinas dos filisteus ao oeste e, juntos, saquearão o povo do leste. Eles atacarão Edom e Moabe, e o povo de Amom lhes obedecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Yahweh destruirá completamente o golfo do mar do Egito. Com Seu vento ardente, Ele moverá a mão sobre o rio Eufrates e o dividirá em sete correntes. Assim, este poderá ser atravessado de sandálias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Haverá uma estrada para o remanescente do Seu povo que voltar da Assíria, como foi para Israel na sua vinda da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Naquele dia, dirás: \"Darei graças a Ti, Yahweh. Pois, embora estejas irado comigo, a Tua ira se afastou de mim, e tens me confortado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Deus é a minha salvação; confiarei Nele e não temerei, pois Yahweh, sim, Yahweh é a minha força e o meu cântico. Ele é a minha salvação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Com alegria, tirareis água do poço da salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Naquele dia, direis: \"Dai graças a Yahweh e invocai o Seu nome; declarai os Seus atos entre os povos; proclamai quão exaltado é o Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Cantai a Yahweh, porque Ele tem feito coisas gloriosas; seja isso conhecido em toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Exultai e cantai com alegria, habitantes de Sião, pois grande é o Santo de Israel no meio de vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Uma advertência para a Babilônia, que Isaías, filho de Amoz, recebeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Levantai uma bandeira em sinal na montanha árida; clamai, em voz alta, para eles; acenai com as mãos para que entrem nas portas dos nobres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Eu dei ordens aos Meus consagrados, sim, Eu chamei Meus poderosos homens para executar a Minha ira, os que se alegram em Me exaltar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Ouve-se o barulho da multidão nas montanhas, como de muitas pessoas; o som de um tumulto dos reinos, como muitas nações reunidas! Yahweh dos Exércitos está convocando as tropas para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Eles vêm de um país distante, de além da extremidade do horizonte. Yahweh está com as armas de Sua indignação para destruir toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Uivai, pois o dia de Yahweh está próximo; do Todo-Poderoso, virá a destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Portanto, todas as mãos ficarão frouxas e todo coração se derreterá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Ficarão assombrados; dores e aflições os tomarão, como as dores de uma mulher no parto. Olharão atônitos uns para os outros e os seus rostos estarão ardentes como fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'O dia de Yahweh vem com furor cruel, transbordando de ira ardente, para pôr a terra em assolação e para destruir os pecadores que nela estão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'As estrelas do céu e suas constelações não darão sua luz. O sol será escurecido desde a aurora, e a lua não resplandecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Eu castigarei o mundo por sua maldade e os corruptos por sua iniquidade. Colocarei fim à arrogância dos orgulhosos e abaterei a arrogância dos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Farei os homens serem mais escassos que ouro puro, e a humanidade mais difícil de achar que o ouro fino de Ofir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Portanto, farei os céus tremerem, e a terra será sacudida do seu lugar, pelo furor de Yahweh dos Exércitos, no dia da fúria de Sua ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Como uma corça perseguida ou como uma ovelha sem pastor, assim todo homem voltará em direção ao seu próprio povo e fugirá para a sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Todo aquele que for achado será morto, e todo aquele que for capturado morrerá pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Suas crianças serão despedaçadas diante de seus olhos; suas casas serão saqueadas e suas esposas, violentadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Eis que estou prestes a incitar os guerreiros da Média para atacá-los, os quais não terão interesse na prata nem se deleitarão com ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Seus arcos despedaçarão os jovens. Não terão pena dos bebês e não pouparão as crianças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Então, a Babilônia, a mais admirada dos reinos, o esplendor do orgulho dos caldeus, será devastada por Deus, como Sodoma e Gomorra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Não será povoada nem habitada, geração após geração. O árabe não armará ali a sua tenda, nem os pastores farão descansar os seus rebanhos nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Mas os animais selvagens do deserto repousarão ali. Suas casas se encherão de corujas; avestruzes e cabras selvagens pularão ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'As hienas uivarão nos seus castelos, e os chacais, nos seus lindos palácios. Bem perto está o tempo dela; os seus dias não tardarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Yahweh terá compaixão de Jacó; Ele escolherá Israel novamente e o restaurará à sua própria terra. Estrangeiros se unirão a eles e se tornarão parte da casa de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'As nações os trarão ao seu próprio lugar. Então, a casa de Israel os possuirá como servos e servas na terra de Yahweh. Eles tornarão cativos aqueles que os haviam capturado, e reinarão sobre os seus opressores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'No dia em que Yahweh te der descanso do teu sofrimento e angústia, e do árduo trabalho que te obrigaram a executar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'tu cantarás esta canção de insulto contra o rei da Babilônia: \"Como o opressor chegou ao fim; a fúria arrogante terminou!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Yahweh quebrou a vara da maldade, o cetro daqueles governantes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'que, furiosos, feriram as pessoas com golpes incessantes e, com raiva, reinavam sobre as nações, com um ataque desenfreado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Toda a terra descansa e está quieta; todos começam a celebrar com canções.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Até as árvores de cipreste e os cedros do Líbano se alegram sobre ti; eles exclamam: \'Desde que caíste, nenhum lenhador sobe aqui para nos cortar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'O Sheol abaixo está ávido para te encontrar quando fores para lá. Despertou, por tua causa, os mortos que foram reis da terra, e fez levantar dos seus tronos todos os que haviam sido reis das nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Todos eles falarão, dizendo: \'Tu estás fraco como nós. Tu te tornaste como nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Tua grandiosidade foi lançada para o Sheol com o som dos teus instrumentos de cordas. Larvas estão espalhadas abaixo de ti, e vermes te cobrem\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Como tu caíste do céu, estrela da alva, filho da manhã! Como foste lançado por terra, tu que conquistaste as nações!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Disseste em teu coração: \'Eu subirei aos céus, exaltarei meu trono acima das estrelas de Deus e me assentarei no monte da assembleia, nas distâncias longínquas do norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Subirei acima das alturas das nuvens; eu farei a mim mesmo semelhante ao Deus Altíssimo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Todavia, tu descerás ao Sheol, para a profundidade do abismo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Aqueles que te virem te contemplarão e prestarão atenção em ti. Eles dirão: \'É este o homem que fez a terra tremer, que abalou os reinos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'que fez do mundo um deserto, que derrubou as suas cidades e não deixou os prisioneiros voltarem para as suas casas?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Todos os reis das nações, todos eles, deitam em honra, cada um na sua própria tumba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Mas tu foste expulso da tua sepultura como um galho jogado fora. Os mortos te cobrem como uma veste, os perfurados pela espada, que descem às pedras do abismo. Tu foste como um cadáver pisoteado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Tu não te juntarás a eles no túmulo, porque destruíste a própria terra e mataste o teu próprio povo. Os filhos dos malfeitores nunca serão mencionados novamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Preparai um massacre para os filhos dele! Pela iniquidade dos seus ancestrais, que eles não se levantem para possuir a terra, para encher o mundo com cidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, '\"Eu Me levantarei contra eles\" — esta é a declaração de Yahweh dos Exércitos. \"Eu cortarei da Babilônia o nome, a descendência e a posteridade\" — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, '\"Eu também farei dela um lugar para corujas, um lugar de pântanos; Eu a varrerei com a vassoura da destruição\" — esta é a declaração de Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Yahweh dos Exércitos jurou: \"Certamente, como Eu planejei, acontecerá; como Eu propus, assim será:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Eu quebrarei o assírio em Minha terra e, sobre Minhas montanhas, o esmagarei debaixo dos Meus pés. Então, o seu jugo será levado para longe do Meu povo, a sua carga, para longe dos seus ombros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Este é o plano que está determinado para toda a terra, e esta é a mão levantada sobre todas as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Pois Yahweh dos Exércitos planejou isto. Quem poderá impedi-Lo? Sua mão está levantada. Quem a fará recuar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Esta declaração veio no ano em que o rei Acaz morreu:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, '\"Não te alegres, Filístia, porque a vara que te batia foi quebrada. Pois da raiz da serpente crescerá uma víbora, e o seu fruto será uma serpente voadora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Os primogênitos dos pobres vão alimentar suas ovelhas no Meu pasto, e os necessitados se deitarão seguros. Eu matarei de fome a tua raiz e isso aniquilará teus sobreviventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Lamenta, portão; chora, cidade; todos vós estareis derretidos, Filístia; pois vem do norte uma nuvem de fumaça, e não há desertores em suas fileiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Que resposta será dada aos mensageiros daquela nação? Dizei-lhes que Yahweh estabeleceu Sião, e nela os aflitos de Seu povo encontrarão refúgio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Uma declaração sobre Moabe: De fato, em uma noite, Ar de Moabe foi devastada e destruída; certamente, em uma só noite, Quir de Moabe foi devastada e destruída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Eles foram ao templo, o povo de Dibom foi aos altos lugares para chorar. Moabe pranteia sobre Nebo e Medeba. Todas as suas cabeças estão calvas e todas as barbas estão cortadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Em suas ruas, eles vestem panos de saco; em seus terraços e na praça, todos lamentam, derretem-se em lágrimas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hesbom e Eleale clamam por ajuda; suas vozes são ouvidas tão longe quanto em Jaaz. Por isso, os homens armados de Moabe clamam por ajuda; eles tremem em seu interior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Meu coração chora por Moabe; seus fugitivos fogem para Zoar e para Eglate-Selisia. Eles sobem chorando para Luíte; na estrada para Horonaim, eles lamentam, em alta voz, por sua destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'As águas de Ninrim secaram-se, a grama está seca e a vegetação morre; nada está verde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'A fartura que cultivaram e estocaram, eles a levam para além do riacho dos salgueiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'O choro espalha-se por todo a terra de Moabe; a lamentação, tão longe quanto Eglaim e Beer-Elim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Pois as águas de Dimom estão cheias de sangue; mas Eu trarei ainda mais sobre Dimom. Um leão atacará tanto os que escaparem de Moabe quanto os que restarem na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Enviai carneiros ao governador da terra, desde Selá, no deserto, até ao monte da filha de Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Como pássaros errantes, como ninhada dispersa, assim são as filhas de Moabe nos vaus do rio de Arnom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, '\"Dá conselhos!\", elas clamam. \"Executa justiça; providencia alguma sombra como a noite no meio do dia; esconde os refugiados; não traias os fugitivos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Que os refugiados de Moabe vivam entre vós; sê para eles um esconderijo contra o destruidor\". Pois, quando a opressão for interrompida, e a destruição cessar, e desaparecer da terra aqueles que oprimem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'um trono será estabelecido em fidelidade à aliança; alguém vindo da tenda de Davi se assentará com fidelidade. Ele julgará enquanto busca a justiça e pratica o que é correto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Temos ouvido falar do orgulho de Moabe, sua arrogância, sua soberba e sua ira. Porém, seu discurso soberbo são palavras vazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Assim, Moabe geme por Moabe, todos eles lamentam. Vós, que fostes completamente devastados, chorai pelos bolos de passas de Quir-Haresete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Os campos de Hesbom estão secos, bem como as videiras de Sibma. Os governantes das nações pisaram as videiras selecionadas, que alcançavam Jazer e espalhavam-se até o deserto. Seus brotos se espalhavam e iam além do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Na verdade, chorarei juntamente com Jazer pela vinha de Sibma. Eu vos regarei com Minhas lágrimas, Hesbom e Eleale. Pois, em vossos campos de frutas de verão e de colheita, Eu acabei com os gritos de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'O regozijo e a alegria desapareceram dos pomares; e, nas vinhas, não se canta nem há gritos alegres. Não há quem pise vinho nos lagares. Eu fiz cessar os gritos de júbilo dos pisadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Então, Meu coração suspira como uma harpa por Moabe, e Meu íntimo, por Quir-Heres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Quando Moabe se apresentar cansado no lugar alto, e entrar em seu templo para orar, suas orações nada alcançarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Esta é a palavra que Yahweh disse, anteriormente, a respeito de Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Novamente, Yahweh diz: \"Dentro de três anos, a glória de Moabe desaparecerá; a despeito de seus muitos habitantes, os remanescentes serão pouquíssimos e insignificantes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Uma declaração acerca de Damasco. Eis que Damasco deixará de ser cidade e se tornará um montão de ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'As cidades de Aroer serão abandonadas. Serão lugares para os rebanhos se deitarem e ninguém os assustará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Fortalezas desaparecerão de Efraim, do reino de Damasco e do remanescente da Síria; eles serão como a glória do povo de Israel. Esta é a declaração de Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Naquele dia, a glória de Jacó definhará e a gordura da sua carne se tornará magra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Será como quando o ceifeiro ajunta os grãos e colhe espigas com seu braço. Será como alguém que colhe espigas no vale de Refaim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'No entanto, algumas espigas serão deixadas, como acontece quando a oliveira é sacudida: duas ou três azeitonas na ponta do galho mais alto, quatro ou cinco nos ramos mais altos de uma árvore frutífera — esta é a declaração de Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Naquele dia, os homens atentarão para o seu Criador e seus olhos olharão para o Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Eles não olharão para os altares, o trabalho de suas mãos, nem olharão para o que seus dedos fizeram, os postes-ídolos ou imagens do sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'Naquele dia, as suas fortalezas serão abandonadas como os matagais das encostas, que foram abandonados por causa dos filhos de Israel. Elas se tornarão uma desolação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Pois esqueceste o Deus da tua salvação e ignoraste a rocha Daquele que é a tua fortaleza. Então, mesmo que tu semeies lindas lavouras e cultives nelas videiras importadas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'quando as plantares, protegeres e delas cuidares, logo tua semente crescerá, mas não haverá colheita no dia da dor e do desespero.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Ouvi! Este é o alvoroço de muitos povos, que rugem como o bramido dos mares, e o estrondo das nações, que rugem como o bramido das águas impetuosas!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'As nações rugirão como o bramido de muitas águas. Porém, Deus as repreenderá e elas fugirão para longe; serão dispersadas pelo vento como palhas nas montanhas, como a vegetação seca perante uma tempestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Ao anoitecer, o terror virá! Antes do amanhecer, terão ido embora. Essa é a porção daqueles que nos saqueiam, o fim de quem nos rouba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Ai da terra de asas ruidosas, que está ao longo dos rios da Etiópia;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'que envia embaixadores pelo mar, em navios de papiros sobre as águas. Ide, vós mensageiros velozes, para uma nação alta e de pele lisa, para um povo temido pelos de perto e pelos de longe, para uma nação forte e esmagadora, cuja terra os rios dividem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Todos vós, habitantes do mundo, vós que viveis sobre a terra, quando um sinal for levantado nas montanhas, vede; e quando a trombeta soar, ouvi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Isto é o que Yahweh disse para mim: \"Da Minha casa observarei, silenciosamente, como o ardor do sol resplandecente, como o orvalho no calor, em tempos de colheita\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Antes da colheita, quando a florada terminar e as flores amadurecerem como uvas, Ele cortará os ramos com ganchos de poda, cortará e tirará os galhos espalhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Eles serão deixados juntos para as aves das montanhas e para os animais da terra. As aves de rapina passarão o verão com eles e os animais da terra passarão o inverno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Naquele tempo, serão levados tributos a Yahweh dos Exércitos — por um povo alto e de pele lisa, povo temido por todos, de longe e de perto, por uma nação forte e esmagadora, cuja terra é dividida por rios — ao monte Sião, o lugar do nome de Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Uma declaração acerca do Egito. Eis que Yahweh avança para o Egito, montado em uma nuvem ligeira. Os ídolos do Egito tremem diante Dele e o coração dos egípcios se derrete em seu interior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, '\"Eu colocarei os egípcios uns contra os outros: um homem lutará contra o seu irmão, lutará contra o seu próximo; cidade contra cidade e reino contra reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'O ânimo do Egito será enfraquecido dentro dele e Eu destruirei o seu conselho; eles pedirão conselhos aos ídolos, invocarão os espíritos dos mortos, consultarão videntes e espiritualistas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Eu entregarei os egípcios nas mãos de um senhor implacável; um rei poderoso os governará\" — esta é a declaração de Yahweh, o Senhor dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'As águas do mar secarão e o rio ficará seco e árido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Os rios exalarão mau cheiro; os riachos do Egito diminuirão e secarão; as canas e os juncos murcharão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'As canas ao longo do Nilo, das margens do Nilo, e tudo o que foi semeado junto ao Nilo secará, será removido e não mais existirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Os pescadores gemerão e prantearão; todos os que lançarem anzóis ao Nilo lamentarão, e aqueles que lançam redes nas águas se entristecerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Aqueles que trabalham com linho fino e os que tecem algodão se envergonharão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Os tecelões do Egito serão esmagados; todos os que trabalham por salário ficarão com o espírito conturbado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Os príncipes de Zoã são completamente tolos. Tornou-se insensato o conselho dos mais sábios conselheiros do faraó. Como podeis dizer ao faraó: \"Eu sou filho de um homem sábio, filho dos antigos reis\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Onde estão os vossos sábios? Que eles vos façam saber o que Yahweh dos Exércitos determinou a respeito do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Tornaram-se tolos os príncipes de Zoã, os príncipes de Mênfis estão enganados; aqueles que são as pedras angulares de suas tribos fizeram o Egito errar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Yahweh lançou no meio deles um espírito perverso, e eles fizeram o Egito errar em tudo o que fizesse, como um bêbado cambaleando em seu vômito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Não há nada que alguém possa fazer pelo Egito, seja cabeça ou seja cauda, seja ramo de palma ou seja junco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Naquele dia, os egípcios serão como mulheres. Eles tremerão e temerão porque a mão de Yahweh dos Exércitos Se erguerá contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'A terra de Judá se tornará motivo para o Egito cambalear. Quando se lembrarem dela, temerão, por causa do plano de Yahweh contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Naquele dia, haverá cinco cidades no território do Egito que falarão o idioma de Canaã e jurarão lealdade a Yahweh dos Exércitos. Uma delas será chamada Cidade do Sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'Naquele dia, haverá um altar para Yahweh no meio da terra do Egito e, em sua fronteira, um pilar de pedra para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Será um sinal e um testemunho para Yahweh dos Exércitos na terra do Egito. Quando clamarem a Yahweh por causa dos opressores, Ele lhes enviará um salvador e um defensor que os livrará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Yahweh será conhecido pelo Egito e os egípcios conhecerão a Yahweh naquele dia. Eles adorarão com sacrifícios e ofertas, farão votos a Yahweh e os cumprirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Yahweh afligirá o Egito, afligindo-os e curando-os. Eles se voltarão para Yahweh, Ele ouvirá suas orações e os curará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'Naquele dia, haverá uma estrada do Egito até a Assíria; os assírios virão ao Egito e os egípcios, à Assíria. Os egípcios adorarão com os assírios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Naquele dia, Israel será o terceiro, juntamente com o Egito e a Assíria, uma bênção no meio da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Yahweh dos Exércitos os abençoará e dirá: \"Abençoado seja o Egito, povo Meu; Assíria, trabalho das Minhas mãos; e Israel, Minha herança\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'No ano em que Tartã, enviado por Sargão, rei da Assíria, veio a Asdode, ele a atacou e a tomou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'Nessa mesma ocasião, Yahweh falou por meio de Isaías, filho de Amoz, dizendo: \"Vai e tira a veste de saco da tua cintura, e também as sandálias dos teus pés\". Assim ele fez, passando a caminhar descalço e nu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Yahweh disse: \"Assim como o Meu servo Isaías caminhou nu e descalço por três anos, este é um sinal e um presságio contra o Egito e contra a Etiópia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'desta mesma forma, o rei da Assíria conduzirá os prisioneiros do Egito e os exilados da Etiópia — jovens e idosos — nus e descalços, com as nádegas descobertas, para a vergonha do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Eles ficarão aterrorizados e envergonhados pela Etiópia, sua esperança, e pelo Egito, sua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Naquele dia, os que habitam na região costeira dirão: \'Vede o que aconteceu com a nossa fonte de esperança, a quem pedimos ajuda para sermos resgatados do reino da Assíria. E agora, como poderemos escapar?\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Declaração acerca do deserto que fica junto ao mar. Como tempestades de vento varrendo o Neguebe, ele vem do deserto, de uma terra horrível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Foi-me dada uma terrível visão: o homem traidor continua traindo e o destruidor destrói. Sobe e ataca, ó Elão; sitia, ó Média; Eu cessarei todo o seu gemido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Por isso, meus lombos estão cheios de dores; dores como de uma mulher na hora do parto se apoderaram de mim; fiquei abatido pelo que ouvi e estou transtornado pelo que vi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Meu coração se agita; o horror me apavora; a noite que eu desejava se tornou terror para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Eles preparam a mesa, estendem os tapetes, comem e bebem; levantai-vos, príncipes, e ungi vossos escudos com óleo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Pois isto é o que o Senhor me disse: \"Vai, coloca uma sentinela, que deve relatar o que vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Quando esse vigia vir uma carruagem, um par de cavaleiros, pessoas montadas em jumentos e camelos, então, ele ficará atento e muito alerta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Então, gritou a sentinela: \"Senhor, na torre de vigia, eu fico o dia todo, todos os dias, e permaneço no meu posto durante a noite toda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Aí vem uma carruagem com um homem e um par de cavaleiros. Ele exclama: \"Caiu! A Babilônia caiu! E todas as imagens esculpidas de seus deuses estão quebradas no chão!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Ó meu povo, debulhado e peneirado, filhos da minha eira! O que eu ouvi de Yahweh dos Exércitos, o Deus de Israel, isso eu vos declarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Declaração acerca de Dumá. Alguém de Seir me chama: \"Sentinela, o que resta da noite? Sentinela, o que resta da noite?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'A sentinela disse: \"A manhã vem e também a noite. Se quiseres perguntar, então, volta e pergunta novamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Uma declaração acerca da Arábia. No deserto da Arábia passais a noite, vós, caravanas de dedanitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Trazei água para os sedentos, ó habitantes da terra de Tema, encontrai os fugitivos com pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Pois eles fugiram da espada, da espada desembainhada, do arco armado e da pressão da guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Pois isto é o que o Senhor me disse: \"Dentro de um ano, como o ano de um trabalhador assalariado, toda a glória de Quedar despedaçará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Restarão apenas poucos flecheiros, os valentes de Quedar\", pois Yahweh, o Deus de Israel, assim falou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Declaração acerca do vale da Visão: Por qual razão agora todos os teus foram aos telhados?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'É para que ouças uma cidade barulhenta, uma cidade cheia de folia? Teus cadáveres não foram mortos pela espada, nem morreram em batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Todos os teus governantes fugiram juntos, mas foram capturados sem o uso de um arco; todos eles foram capturados juntos, ainda que tenham fugido para longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Por isso, eu disse: \"Não olheis para mim, eu chorarei amargamente; não tenteis me consolar acerca da destruição da filha do meu povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Pois há um dia de tumulto, de atropelo e de confusão, vindo do Senhor Yahweh dos Exércitos, no vale da Visão; um dia de derrubada de muros e de pessoas gritando para as montanhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Elão pega a aljava, com carruagens de homens e cavaleiros, e Quir expõe o escudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'E teus vales férteis estarão cheios de carruagens, e os cavaleiros se posicionarão junto ao portão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Ele tirou a proteção de Judá e, naquele dia, tu olhaste para as armas do palácio da floresta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Viste as brechas da cidade de Davi, que eram muitas, e coletaste a água do açude inferior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Vós contastes as casas de Jerusalém e as demolistes para fortificar os muros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Vós fizestes um reservatório entre os dois muros para a água do açude antigo, mas não considerastes o construtor da cidade, que havia planejado isso há muito tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'O Senhor Yahweh dos Exércitos vos chamou naquele dia para chorar, para lamentar, para raspar as cabeças e para vestir panos de saco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Mas, vede, em vez disso, há celebração e alegria, matança de gado e de ovelhas; carne para comer e vinho para beber; comamos e bebamos, pois amanhã morreremos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Isto foi revelado aos meus ouvidos por Yahweh dos Exércitos: \"Certamente, esta iniquidade não será perdoada, mesmo quando vós morrerdes\", diz o Senhor Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'O Senhor Yahweh dos Exércitos diz isto: \"Vai para este administrador, para Sebna, o qual está sobre a casa, e diz:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, '\'O que estás fazendo aqui, e quem te deu permissão para talhar uma sepultura no lugar alto, escavando na rocha um lugar de descanso para ti mesmo?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Vê, homem forte: Yahweh está prestes a te arremessar, prestes a te lançar abaixo; Ele te pegará firmemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Certamente, Ele te rodará em voltas e voltas e te lançará como uma bola em um vasto país. Lá, tu morrerás, e lá estarão as tuas gloriosas carruagens; tu serás a vergonha da casa do teu senhor!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, '\"Eu te removerei do teu ofício e do teu posto. Tu serás derrubado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Eu chamarei Meu servo Eliaquim, filho de Hilquias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'Eu o vestirei com a tua túnica e colocarei nele a tua faixa; e transferirei a tua autoridade para a mão dele. Ele será um pai para os habitantes de Jerusalém e para a casa de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Eu colocarei a chave da casa de Davi sobre o ombro dele; ele abrirá e ninguém fechará; ele fechará e ninguém abrirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Eu o fixarei como um prego em um lugar seguro, e ele se tornará um trono de glória para a casa de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Colocarão sobre ele toda a glória da casa de seu pai, a prole e os descendentes, todo pequeno recipiente, desde os copos até todos os jarros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Naquele dia — isto é uma declaração de Yahweh dos Exércitos — o prego firmado em um lugar fixo será quebrado e cairá, e o peso que estava nele se soltará — pois Yahweh falou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Uma declaração sobre Tiro: Lamentai, navios de Társis, pois não há casa nem porto; da terra de Chipre, foi-lhes revelado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Calai-vos, habitantes do litoral; os mercadores de Sidom, que viajam pelo mar, vos encheram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Sobre as grandes águas estavam os cereais de Sior, a colheita do Nilo era o seu produto; e isso se tornou o comércio das nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Envergonha-te, Sidom, porque o mar falou, o poderoso entre os mares. Ele diz: \"Eu não entrei em trabalho de parto, nem dei à luz, também não criei meninos, nem eduquei meninas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Quando a notícia chegar ao Egito, haverá luto em relação a Tiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Atravessai até Társis; lamentai, habitantes do litoral.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'É esta a vossa cidade jubilante, cujas origens são de tempos antigos, cujos pés a carregaram a lugares distantes, para peregrinar no exterior?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Quem planejou isso contra Tiro, a doadora de coroas, cujos comerciantes são príncipes, cujos negociantes são os honrados da terra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Yahweh dos Exércitos planejou isso para desonrar seu orgulho e toda a sua glória, para envergonhar todos os seus honrados da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Arai a vossa terra, como aram o Nilo, filha de Társis. Não há mais um mercado em Tiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Yahweh estendeu Sua mão sobre o mar, Ele abalou os reinos; quanto a Canaã, Ele deu ordem para que destruíssem as fortalezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Ele disse: \"Não te alegrarás novamente, virgem oprimida, filha de Sidom; levanta-te, vai para Chipre; mas nem lá terás descanso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Vede a terra dos caldeus. Esse povo deixou de existir; os assírios fizeram dela um deserto para animais selvagens. Eles montaram um cerco de torres, destruíram seus palácios,7 fizeram uma pilha de ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Lamentai, navios de Társis, pois vosso refúgio foi destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Naquele dia, Tiro será esquecida por setenta anos, como os dias de vida de um rei. Após o final dos setenta anos, acontecerá em Tiro algo como na canção da prostituta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Pega uma harpa, vai pela cidade, ó prostituta esquecida; toca bem, canta muitas canções para que, talvez, tu sejas lembrada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Acontecerá que, depois dos setenta anos, Yahweh ajudará Tiro e ela voltará, novamente, a ganhar dinheiro pelo seu trabalho de prostituta, e oferecerá seus serviços a todos os reinos da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Seus lucros e ganhos serão dedicados a Yahweh. Eles não serão armazenados ou guardados no tesouro, pois serão dados àqueles que vivem na presença de Yahweh, e serão usados para supri-los com abundância de comida e para que tenham roupas da melhor qualidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Vede, Yahweh está prestes a esvaziar a terra, a devastá-la, desfigurar sua superfície, dispersar seus habitantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Isso acontecerá tanto ao povo quanto ao sacerdote; tanto ao servo quanto ao seu mestre; tanto à serva quanto à sua senhora; tanto ao comprador quanto ao vendedor; tanto ao credor quanto ao devedor; tanto ao que recebe juros quanto ao que paga juros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'A terra será completamente devastada e completamente despida, pois Yahweh assim o disse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'A terra lamenta e seca, o mundo murcha e dispersa, seu povo importante desvanece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'A terra está poluída pelos seus habitantes porque eles transgrediram as leis, violaram os estatutos e quebraram a aliança eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Portanto, a maldição devora a terra e seus habitantes são achados culpados. Os habitantes da terra queimam e poucas pessoas sobram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'O vinho novo seca, a vinha murcha e gemem todos os que tinham coração alegre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'O som de júbilo dos pandeiros cessa e a festança daqueles que se regozijam também; a alegria da lira cessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Eles já não bebem vinho nem cantam, e a bebida forte é amarga para aqueles que a bebem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'A cidade do caos foi destruída; todas as casas estão fechadas e vazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Há um clamor nas ruas por causa do vinho; toda a alegria acabou, o contentamento da terra desapareceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Na cidade ficou a desolação e o portão está quebrado em ruína.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Pois assim será toda a terra entre as nações, como quando as oliveiras são sacudidas, como o recolher das uvas quando a colheita é feita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Eles levantarão suas vozes e gritarão de alegria à majestade de Yahweh; alegremente, gritarão do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Portanto, glorificai Yahweh no oriente e, nas ilhas do mar, dai glória ao nome de Yahweh, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Da parte mais distante da terra, nós ouvimos canções: \"Glória ao Justo!\". Mas eu disse: \"Eu estou esgotado, eu estou esgotado, ai de mim! O traidor tem lidado traiçoeiramente, sim, o traidor tem agido muito traiçoeiramente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'O terror, a cova e o laço vêm sobre vós, habitantes da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Aquele que foge do som do terror cairá na cova, e aquele que conseguir subir da cova será capturado pelo laço. As janelas dos céus se abrirão e as fundações da terra tremerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'A terra será completamente quebrada e rasgada; e será violentamente sacudida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'A terra cambaleará como um homem bêbado e balançará de um lado para o outro como uma barraca. A transgressão dela será pesada sobre si mesma; cairá e não levantará novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Naquele dia, Yahweh punirá as hostes celestiais nas alturas e os reis terrenos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Eles serão ajuntados, aprisionados em uma cova e trancados em uma prisão; após muitos dias, serão castigados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Então, a lua será envergonhada, o sol, humilhado, pois Yahweh dos Exércitos reinará em glória no monte Sião, em Jerusalém, e diante de Seus anciãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Yahweh, Tu és o meu Deus! Eu Te exaltarei! Louvarei o Teu nome porque Tu tens feito coisas maravilhosas, coisas planejadas há muito tempo, em perfeita fidelidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Porque Tu fizeste da cidade um monte de pedras; de uma cidade fortificada, uma ruína; e, de uma fortaleza de estrangeiros, uma cidade destruída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Portanto, um povo forte Te glorificará; a cidade das nações cruéis Te temerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Pois Tu tens sido um lugar de proteção para aquele que é pobre, um abrigo para o necessitado na sua angústia, um refúgio na tempestade e uma sombra no calor. Porque o sopro do cruel é como uma tormenta contra uma parede,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'como o calor na seca. Tu dominaste o barulho dos forasteiros; assim como o calor se abranda pela sombra de uma nuvem, assim o cântico dos cruéis cessará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Nesse monte, Yahweh dos Exércitos fará, para todos os povos, um banquete de coisas gordurosas, de vinhos selecionados, de carnes macias; um banquete com os mais finos vinhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Sobre esse monte, Ele destruirá o manto que cobre todos os povos e a teia tecida sobre todas as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Ele engolirá a morte para sempre; o Senhor Yahweh enxugará dos rostos todas as lágrimas; Ele tirará de toda a terra a desgraça contra o Seu povo, porque Yahweh assim o disse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Naquele dia, será dito: \"Vede, este é o nosso Deus! Temos esperado por Ele e Ele nos salvará. Este é Yahweh! Temos esperado Nele, nós exultaremos e nos alegraremos na Sua salvação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Pois a mão de Yahweh repousará sobre este monte, e Moabe será pisada no Seu lugar, assim como a palha é pisada em um poço cheio de estrume.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Eles estenderão suas mãos, como um nadador as estende para nadar; mas Yahweh abaterá o orgulho deles, apesar da habilidade de suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Os muros altos da sua fortaleza, Ele os derrubará por terra, até o pó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Naquele dia, será entoado este cântico na terra de Judá: Nós temos uma cidade forte; Deus colocou a salvação por seus muros e colunas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Abri, vós, os portões, para que entre a nação justa, que mantém a fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Todo aquele que tem a mente alicerçada em Ti, Tu o manterás em perfeita paz, porque ele confia em Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Confiai em Yahweh para sempre; porque Yah, que é Yahweh, é a Rocha eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Ele derrubará aqueles que vivem orgulhosamente; Ele lançará ao chão a cidade fortificada; Ele a reduzirá ao pó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Ela será pisada pelos pés dos pobres e trilhada pelos necessitados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'A vereda do justo é plana; Tu, que és Justo, nivelas o caminho de quem é reto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Sim, no caminho dos Teus julgamentos esperamos por Ti, Yahweh; Teu nome e Tua reputação são o nosso desejo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Minha alma anseia por Ti durante a noite; sim, dentro de mim, meu espírito Te busca diligentemente. Porque quando Teus juízos vêm à terra, os habitantes do mundo aprendem a justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Ainda que o favor seja mostrado ao corrupto, ele não aprenderá sobre a justiça. Na terra da retidão, ele age de maneira má, e não enxerga a majestade de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Yahweh, Tua mão está levantada, mas eles não percebem. Porém, eles verão o zelo que tens pelo Teu povo e serão envergonhados; porque o fogo reservado aos Teus adversários os devorará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Yahweh, Tu nos trarás paz. De fato, Tu também realizaste por nós todos os nossos feitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Yahweh, nosso Deus, outros senhores além de Ti dominaram sobre nós; mas nós adoramos somente o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Eles estão mortos e não mais se levantarão. Na verdade, Tu vieste em julgamento e os destruíste; e fizeste perecer toda a sua memória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Tu aumentaste a nação, Yahweh, Tu aumentaste a nação! Tu és honrado! Tu estendeste todas as fronteiras de nossa terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Yahweh, eles, angustiados, olharam para Ti e sussurraram orações quando estavam sob Tua disciplina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Como uma grávida perto de dar à luz, que está em dores e grita em seu trabalho de parto, assim estamos nós diante de Ti, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Nós engravidamos, estivemos em dores de parto, mas é como se tivéssemos dado à luz o vento. Nós não trouxemos salvação à terra, nem caíram os habitantes do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Teus mortos viverão; seus corpos ressuscitarão. Despertai e cantai com alegria, vós que habitais no pó, pois Teu orvalho é o orvalho da luz, e a terra trará de volta os seus mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Vai, povo meu, entra em teus quartos e fecha tuas portas atrás de ti; esconde-te por um tempo, até que passe a indignação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Porque eis que Yahweh está para sair de Seu lugar para punir os habitantes da terra por causa da sua iniquidade; a terra revelará o sangue nela derramado e não mais esconderá os que foram mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Naquele dia, Yahweh, com Sua espada grande, forte e resistente, punirá o Leviatã, a serpente fugitiva, o Leviatã, a serpente tortuosa e matará o monstro, o dragão do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Naquele dia, cantai sobre a videira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, '\"Eu, Yahweh, sou Seu protetor; Eu a rego continuamente. Portanto, ninguém a danifique, pois Eu a vigio noite e dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Eu não estou irado. Ó, se na batalha houver tão somente espinhos e abrolhos, marcharei contra eles; Eu os queimarei todos juntos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'a menos que eles busquem Minha proteção e façam paz Comigo. Que eles façam paz Comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'No dia vindouro, Jacó lançará raízes; Israel florescerá e brotará, enchendo de frutos toda a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Porventura, Yahweh já atacou Israel do modo como feriu as nações que lhe atacaram? Foram os israelitas mortos como no massacre dessas nações, que foram mortas por eles?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Na medida exata, Tu os contestaste, enviando Israel embora; Tu os expulsaste com Teu impetuoso vento leste..');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Desta maneira, a iniquidade de Jacó será expiada e este será o fruto da remoção do seu pecado: quando Ele fizer todas as pedras do altar como pedaços de pedras de cal, nenhum poste de Aserá e nenhum altar de incenso permanecerão de pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Pois a cidade fortificada está desolada, a habitação está deserta e abandonada como o deserto. Ali, o bezerro comerá; ali, ele se deitará e consumirá os seus ramos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Os galhos se quebrarão quando estiverem secos. Mulheres virão e farão fogo com eles, porque não é um povo com entendimento. Portanto, seu Criador não Se compadecerá; Aquele que os fez não terá misericórdia deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'E virá o dia em que Yahweh debulhará as suas espigas desde a correnteza do rio Eufrates até o ribeiro do Egito; e vós, povo de Israel, sereis colhidos um por um.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Naquele dia, uma grande trombeta tocará; os que estiverem perecendo na terra da Assíria e os exilados na terra do Egito virão e adorarão Yahweh no monte santo em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Ai da coroa majestosa usada pelos bêbados de Efraim, da flor desbotada da sua gloriosa beleza, que está sobre a cabeça do vale exuberante, dos que são dominados pelo vinho!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Eis que o Senhor envia alguém que é poderoso e forte; como chuva de granizo, e tempestade destruidora, como tempestade torrencial, Ele esmagará cada coroa no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'A coroa majestosa dos bêbados de Efraim será pisada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'A flor desbotada da sua gloriosa beleza, que está sobre a cabeça do rico vale, será como o primeiro figo maduro antes do verão: quando alguém o vê, enquanto ainda está em sua mão, ele o engole.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Naquele dia, Yahweh dos Exércitos Se tornará uma bela coroa e um diadema de beleza para o remanescente do Seu povo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'um espírito de justiça para aquele que está assentado para julgar e força para aqueles que fazem seus inimigos voltarem dos seus portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Mas mesmo estes cambaleiam com vinho e se desequilibram com bebida forte. O sacerdote e o profeta cambaleiam com bebida forte e são engolidos pelo vinho. Eles se desequilibram com a bebida forte, cambaleiam com a visão e erram nas decisões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Verdadeiramente, todas as mesas estão cobertas com vômito, não havendo nenhum lugar limpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'A quem ele ensinará conhecimento e a quem explicará a mensagem? Para aqueles que foram desmamados ou àqueles que acabaram de ser retirados do peito?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Porque é mandamento em cima de mandamento, mandamento em cima de mandamento; regra em cima de regra, regra em cima de regra; um pouco aqui, um pouco lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'De fato, Ele falará ao povo com lábios que gaguejam e em língua estrangeira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'No passado, Ele lhes disse: \"Este é o descanso, dai descanso ao que está cansado; e nisto está o renovo\", mas eles não deram ouvidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Então, a palavra de Yahweh será para eles mandamento em cima de mandamento; mandamento em cima de mandamento; regra em cima de regra, regra em cima de regra; um pouco aqui, um pouco lá; para que possam ir e cair novamente, e sejam quebrados, laçados e capturados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Ouvi, pois, a palavra de Yahweh, vós que zombais, que governais esse povo em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Tendes dito: \"Fizemos uma aliança com a morte, e com o Sheol chegamos a um acordo. Então, quando o chicote avassalador passar, não nos atingirá. Porque fizemos da mentira nosso refúgio e nos escondemos na falsidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Portanto, o Senhor Yahweh diz: \"Eu colocarei em Sião uma pedra fundamental, uma pedra já provada, pedra preciosa, uma fundação segura. Aquele que crê, não será envergonhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Eu farei da justiça a vara de medir e, da retidão, o prumo. A Saraiva varrerá o refúgio das mentiras e as águas da inundação sufocarão o esconderijo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Vossa aliança com a morte será dissolvida, e vosso acordo com o Sheol não subsistirá. Quando a inundação furiosa passar, sereis engolidos por ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Sempre que ela passar, irá vos engolir, manhã após manhã, passará e, de dia e de noite, virá. Quando a mensagem for entendida, causará terror.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Pois a cama é muito curta para um homem se esticar e o cobertor estreito demais para ele se enrolar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Yahweh se levantará como no monte Perazim; Ele mostrará Sua ira como no vale de Gibeão, para fazer Sua obra, Sua obra estranha, e para executar a tarefa Dele, a estranha tarefa Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Agora, portanto, não zombeis, ou vossas amarras serão apertadas. Eu tenho ouvido do Senhor Yahweh dos Exércitos um decreto de destruição contra toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Escutai e dai ouvidos à minha voz; estai atentos e escutai as minhas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'O fazendeiro que ara o dia todo para plantar, somente ara o solo? Ele, continuamente, cava e ara o campo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Tendo ele preparado o solo, não espalha a semente de cominho, semeia o cominho, coloca o trigo nas eiras, a cevada no lugar certo e a espelta nas margens?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'O Seu Deus o instrui; Ele o ensina sabiamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Além disso, o cominho não é debulhado com instrumento de trilhar, nem rodas passam por cima do cominho, mas batem-se o endro e o cominho com a vara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'O grão é moído para o pão, mas não fino demais e, apesar de as rodas do seu carro e seus cavalos o espalharem, os cavalos não o trituram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Isto também vem de Yahweh dos Exércitos, que é maravilhoso em conselho e excelente em sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Ai de Ariel! Ariel, a cidade onde Davi acampou! Acrescentai ano a ano, deixai que os festivais completem o seu ciclo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Eu sitiarei Ariel, e ela pranteará e lamentará; ela será para Mim como uma fornalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Eu acamparei ao teu redor, Eu te sitiarei com baluartes e farei um cerco contra ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Então, serás derrubada e do chão falarás; a tua fala sairá do pó. A tua voz será como a de um fantasma em sua cova, e tua fala será muito fraca, vinda do pó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'A multidão dos teus invasores será como o pó e a multidão dos cruéis será fraca, como a palha que passa. Isto acontecerá de repente, em um momento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Vós sereis punidos por Yahweh dos Exércitos com trovões, terremotos, grandes ruídos, ventos fortes e tempestades violentas, e com as chamas de um fogo devorador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Como um sonho, uma visão da noite, será a multidão de todas as nações que lutará contra Ariel e sua fortaleza. Eles vão lutar contra ela, contra suas fortificações, para pressioná-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Será como um homem faminto que sonha que está comendo, porém, quando acorda, seu estômago está vazio. Será como um homem sedento que sonha que está bebendo, porém, quando acorda, está ofegante com sua sede ainda não saciada. Sim, assim será também a multidão das nações que lutam contra o monte Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Surpreendei-vos e ficai atônitos; cegai-vos e permanecei cegos! Estais embriagados, mas não com vinho; cambaleais, mas não com bebida forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Porque Yahweh derramou sobre vós um espírito de profundo sono. Ele fechou os vossos olhos profetas, e cobriu as vossas cabeças, videntes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Toda revelação tornou-se para vós como as palavras de um livro que está selado, que se dá a alguém que é capaz de ler, dizendo: \"Lê isto\". Ele também dirá: \"Eu não posso, pois está selado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Se o livro é dado a alguém que não é capaz de ler, dizendo: \"Lê isto\", ele dirá: \"Eu não sou capaz de ler\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'O Senhor disse: \"Este povo se aproxima de Mim e Me honra com sua boca, com seus lábios, mas seu coração está longe de Mim. Seu culto a Mim é um mandamento ensinado por homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Portanto, vede, Eu continuarei a fazer uma obra maravilhosa no meio deste povo, maravilha após maravilha. A sabedoria de seus homens perecerá e o entendimento dos homens prudentes desaparecerá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Ai daqueles cujas obras estão em trevas, que cavam profundamente e escondem seus planos de Yahweh. Eles dizem: \"Quem nos vê, e quem nos conhece?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Vós virais as coisas de cabeça para baixo! Deveria o oleiro ser considerado como barro, de modo que a coisa que é feita dissesse sobre aquele que a fez: \"Ele não me fez\", ou a coisa formada dissesse sobre aquele que a formou: \"Ele não entende\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Em pouco tempo, o Líbano será transformado em campo, e o campo se transformará em floresta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Naquele dia, os surdos ouvirão as palavras de um livro, e, das profundezas das trevas, os olhos dos cegos verão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Os oprimidos se regozijarão em Yahweh, e os pobres dentre os homens se regozijarão no Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Os cruéis cessarão e o escarnecedor desaparecerá. Todos aqueles que amam fazer o mal serão eliminados;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'os quais, por causa de uma palavra, acusam um homem e o fazem criminoso; preparam armadilhas para aquele que procura justiça no portão, e abatem o justo com mentiras vazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Portanto, isto é o que Yahweh diz acerca da casa de Jacó — Yahweh, que redimiu Abraão: \"Jacó não mais se envergonhará nem ficará pálida a sua face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Mas, quando ele vir suas crianças, o trabalho de Minhas mãos, eles honrarão o Meu nome. Eles santificarão o nome do Santo de Jacó e permanecerão no temor do Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Os desobedientes no espírito chegarão ao entendimento, e os que murmuram aprenderão as instruções\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, '\"Ai dos filhos rebeldes!\" — esta é a palavra de Yahweh: \"Eles fazem planos que não procedem de Mim, fazem alianças com outras nações que não foram direcionados pelo Meu Espírito e, assim, acrescentam pecado sobre pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Eles se preparam para descer ao Egito, mas não buscaram Minha direção. Procuram proteção do Faraó e buscam refúgio à sombra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Por isso, a proteção de Faraó será sua vergonha, e o refúgio à sombra do Egito, sua humilhação,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'embora seus príncipes estejam em Zoã e os seus mensageiros tenham chegado a Hanes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Todos serão envergonhados por causa de um povo que não pode ajudá-los, que não lhes serve de ajuda nem de auxílio, mas de vergonha e, até mesmo, desgraça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Uma mensagem sobre as feras do Neguebe: \"Ao longo da terra de tristezas e perigos, da leoa e do leão, da víbora e da serpente voadora, eles carregam suas riquezas nos lombos dos jumentos e seus tesouros nas corcovas dos camelos, para um povo que não poderá ajudá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'A proteção do Egito é inútil, por isso, o tenho chamado de Raabe, aquele que nada faz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Agora, vai, escreve isto em sua presença em uma tábua e escreve em um pergaminho, para que seja preservado como testemunho para um tempo que ainda virá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Pois este é um povo rebelde, filhos mentirosos, filhos que não ouvirão o conselho de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Eles dizem aos videntes: \'Não tenhais visões!\' e aos profetas: \'Não profetizeis a verdade para nós! Dizei-nos coisas agradáveis. Profetizai ilusões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Desviai o caminho. Apartai-vos da vereda; afastai da nossa presença o Santo de Israel\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Porém, assim diz o Santo de Israel: \'Porque rejeitais esta palavra e confiais na opressão e no engano, e vos apegastes a isso,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'então, este pecado será para vós como uma rachadura de muro que está prestes a cair, como uma saliência em um muro alto, cuja queda acontecerá de repente, subitamente\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Ele o quebrará como se quebra um vaso do oleiro; Ele não o poupará, de modo que não se encontre, entre seus pedaços, nem um caco que possa raspar as cinzas da lareira ou tirar água de uma cisterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Pois assim diz o Senhor Yahweh, o Santo de Israel: \"Ao retornar e descansar, sereis salvos; na tranquilidade e na confiança estará a vossa força. Porém, vós não quisestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Dissestes: \'Não, fugiremos a cavalo\', então, fugireis; e \'Cavalgaremos em cavalos velozes\', então, aqueles que vos perseguem serão velozes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Mil fugirão da ameaça de um; e, pela ameaça de cinco, fugireis, até que sejais deixados como um mastro no topo da montanha ou como uma bandeira numa colina\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Yahweh ainda espera para ser bondoso convosco; por isso, Ele está pronto para ter misericórdia de vós; pois Yahweh é um Deus de justiça. Benditos são todos os que esperam Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Pois um povo viverá em Sião, em Jerusalém, e nunca mais chorareis. Ele certamente Se compadecerá de vós ao ouvir o vosso clamor; e, quando o ouvir, vos responderá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Ainda que Yahweh vos dê o pão da adversidade e a água da aflição, mesmo assim, o vosso Mestre não mais Se esconderá, mas O vereis com vossos próprios olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'Vossos ouvidos ouvirão uma palavra atrás de vós, dizendo: \"Este é o caminho, andai nele!\", quando vos virardes para a direita ou para a esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Profanareis vossas imagens esculpidas, revestidas de prata e vossas imagens fundidas de ouro, vós as jogareis fora como trapo de imundície. Direis a elas: \"Fora daqui!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Ele trará chuva sobre a vossa semente, quando semeardes a terra; e haverá pão em abundância na terra, e a colheita será abundante. Neste dia, vosso rebanho pastará em amplos pastos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Os bois e os jumentos que lavram a terra comerão forragens temperadas, que foram separadas com uma pá e uma forquilha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Do topo de cada montanha e do topo de cada colina, fluirão rios e correntes de águas, no dia da grande matança, quando as torres caírem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'A luz da lua será como a luz do sol, e a luz do sol brilhará sete vezes mais, como a luz de sete dias. Yahweh cuidará das fraturas do Seu povo e sarará as feridas que lhes fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Vede, o nome de Yahweh vem de um lugar distante, ardendo com Sua ira e em densa fumaça. Seus lábios estão cheios de fúria e Sua língua é como um fogo consumidor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Seu respirar é como um rio transbordante que cobre até o pescoço, que peneira as nações com a peneira da destruição. Seu respirar é como um freio nos queixos dos povos que os faz perderem o rumo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Tereis uma canção como na noite em que se observa uma festa santa, e alegria de coração, como alguém que vai com uma flauta à montanha de Yahweh, à Rocha de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Yahweh fará o esplendor da Sua voz ser ouvido e mostrará a força do Seu braço em fúria impetuosa e labaredas de fogo, com vendaval, tempestade e granizo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Pois, pela voz de Yahweh, a Assíria será despedaçada; Ele a acertará com uma vara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'E cada golpe da vara do castigo que Yahweh lhes der será acompanhado com música de tamborins e harpas, enquanto Ele guerreia e luta contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Pois o lugar destinado à queima foi preparado há muito tempo. Na verdade, estava preparado para o rei, e Deus o fez profundo e largo. A fogueira está preparada com fogo e muita lenha. O sopro de Yahweh, como uma corrente de enxofre, a acenderá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Ai daqueles que descem para o Egito em busca de ajuda, que dependem de cavalos. Colocam sua confiança em carros, por serem muitos, e em cavaleiros, por serem incontáveis, mas não se preocupam com o Santo de Israel e não buscam Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Porém, Ele é sábio e trará desastre, e não retirará as Suas palavras. Ele se levantará contra a casa dos perversos e contra aqueles que ajudam os que cometem pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Os egípcios são homens, e não Deus. Seus cavalos são carne, e não espírito. Quando Yahweh estender Sua mão, tanto quem ajuda tropeçará, quanto quem busca ajuda cairá; ambos perecerão juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Isto é o que Yahweh me diz: \"Como um leão, mesmo um jovem leão, que rosna sobre sua presa, não se assusta e nem foge quando um grupo de pastores se reúne contra ele, com suas vozes e barulho, assim Yahweh dos Exércitos descerá para lutar no monte Sião, sobre sua colina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Como pássaros em voo, assim Yahweh dos Exércitos protegerá Jerusalém. Yahweh a protegerá e a resgatará; enquanto voa por cima dela, a preservará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Voltai-vos para Ele, contra quem vos rebelastes profundamente, povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Porque, naquele dia, cada um jogará fora seus ídolos de prata e deuses de ouro, feitos pelas vossas mãos pecaminosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'A Assíria cairá pela espada; uma espada, feita não por homens, a consumirá. Ela fugirá da espada e seus jovens serão submetidos a trabalhos forçados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Eles perderão toda a confiança por causa do terror, e seus príncipes temerão quando virem a bandeira de guerra de Yahweh — essa é a declaração de Yahweh, cujo fogo está em Sião, e cuja fornalha está em Jerusalém\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Um rei reinará com retidão, e príncipes governarão com justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Cada um será como um abrigo contra o vento e refúgio contra a tempestade, como correntes de água em local seco e como a sombra de uma grande rocha em terra árida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Então, os olhos dos que veem não se escurecerão e os ouvidos dos que ouvem estarão atentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'O imprudente terá entendimento e o gago falará com clareza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'O tolo não será mais chamado de nobre, nem o enganador, de respeitável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Pois o tolo fala tolices e, em seu coração, trama o mal e profere difamações contra Yahweh. Ele deixa o faminto com fome e impede o sedento de beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'As artimanhas do enganador são más; ele trama maldades para arruinar o pobre com mentiras, mesmo quando a petição do pobre é justa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Mas o homem nobre planeja coisas nobres e, por causa da sua nobreza, ele será estabelecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Levantai-vos, ó mulheres sossegadas, e ouvi a minha voz; e vós, filhas despreocupadas, dai ouvidos a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Em pouco mais de um ano, ó mulheres tão descuidadas, vossa confiança será quebrada, pois a colheita de uvas falhará, e não haverá ceifa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Tremei, mulheres tranquilas; preocupai-vos, vós que estais tão confiantes; despi-vos de suas finas roupas e vesti-vos de panos de saco ao redor de vossas cinturas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Ireis prantear pelos campos deleitosos e pelas vinhas frutíferas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'A terra do meu povo se encherá de espinheiros e sarças, até mesmo em todas as casas de alegria, na cidade jubilosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Porque o palácio será abandonado, a cidade populosa ficará deserta; o monte e a torre da guarda se tornarão cavernas perpétuas, para o deleite dos jumentos selvagens e para pasto dos rebanhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'até que, do alto, seja derramado sobre nós o Espírito, e o deserto se torne um campo fértil, e o campo fértil seja considerado um bosque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Então, a justiça habitará no deserto e a retidão viverá no campo fértil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'O fruto da retidão será a paz, e o resultado da justiça será o sossego e a segurança, para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Meu povo viverá em habitação de paz, em moradas seguras e em locais tranquilos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Mesmo que haja granizo, que o bosque seja destruído e a cidade seja totalmente aniquilada,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'sereis abençoados, vós que semeais próximo aos ribeiros e que deixais pastar, soltos, o boi e o jumento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Ai de ti, destruidor que não foste destruído! Ai de ti, traidor que não foste traído! Quando parares de destruir, serás destruído. Quando parares de trair, eles te trairão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Yahweh, sê benevolente conosco; esperamos por Ti! Sê Tu nosso braço a cada manhã, nossa salvação no tempo de tribulação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Ao grande barulho, os povos fogem; quando Te levantas, as nações se dispersam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Vosso despojo é colhido como os gafanhotos colhem; os homens saltam sobre ele como os gafanhotos saltam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Yahweh é exaltado. Ele vive nas alturas. Ele encherá Sião de justiça e retidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Ele será, ó Sião, a estabilidade em teu tempo, abundância de salvação, sabedoria e conhecimento; o temor de Yahweh é o seu tesouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Vede! Seus enviados gritam nas ruas; os embaixadores, que esperavam a paz, choram amargamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'As estradas estão desertas, não há mais viajantes. As alianças são quebradas, as testemunhas são desprezadas e a humanidade é desrespeitada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'A terra pranteia e murcha; o Líbano envergonha-se e murcha; Sarom é como um deserto; Basã e Carmelo perdem suas folhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, '\"Agora Me levantarei\", diz Yahweh; \"Agora serei exaltado! Agora serei elevado!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Vós concebeis palha e dais à luz restolho; vosso fôlego é um fogo que vos consumirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Os povos serão queimados como se queima a cal, como espinheiros que são cortados e queimados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Vós que estais longe, ouvi o que fiz; e vós que estais perto, reconhecei o Meu poder\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Os pecadores em Sião temem; o tremor apoderou-se dos ímpios. Quem dentre nós pode habitar com o fogo devorador? Quem dentre nós pode habitar com chamas eternas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Aquele que anda em justiça e fala honestamente, aquele que rejeita o ganho da opressão, aquele que acena com as mãos para não aceitar o suborno, que tapa os ouvidos para não ouvir falar de crimes de sangue, e que fecha os olhos para não contemplar o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Esse habitará nas alturas; seu local de defesa será as fortalezas das rochas; sua comida e sua água estarão em constante provisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Teus olhos verão o rei em sua beleza, e contemplarão a vasta terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Teu coração refletirá sobre o terror. Onde está o escriba, onde está aquele que pesou o dinheiro? Onde está aquele que contou as torres?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Tu já não verás as pessoas provocadoras, um povo de língua diferente, a quem tu não compreendes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Olha para Sião, a cidade de nossos banquetes; teus olhos verão Jerusalém como uma habitação calma, como uma tenda cujas estacas não serão arrancadas ou nenhuma de suas cordas arrebentadas: uma tenda que não será removida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Em vez disso, Yahweh, em Sua majestade, estará conosco num lugar de largos rios e córregos, nos quais nenhum barco com remos viajará e nenhum grande navio de guerra navegará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Porque Yahweh é o nosso juiz, Yahweh é o nosso legislador, Yahweh é o nosso rei; Ele nos salvará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'As tuas cordas estão frouxas; elas não podem segurar o mastro em seu lugar, não podem estender a vela. Quando o grande despojo for dividido, até os coxos levarão sua parte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'O povo não dirá: \"Estou doente\", pois o povo que vive ali terá sua iniquidade perdoada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Chegai-vos, ó nações, e ouvi; prestai atenção, ó povos! A terra e tudo o que nela há, ouvi! O mundo e todas as coisas que provêm dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Yahweh está irado com todas as nações e furioso com todos os exércitos delas; Ele as destruiu completamente. Ele as entregou para a matança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Seus mortos não serão enterrados; o cheiro dos seus cadáveres estará em todo o lugar e as montanhas serão encharcadas com o sangue deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Todas as estrelas do céu desaparecerão, o céu será enrolado como um pergaminho; e todas as suas estrelas vão se apagar, como a folha que desvanece da videira e os figos podres, da figueira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Porquanto a Minha espada embriagou-se no céu. Olhai! Ela descerá sobre Edom e o povo que separei para a destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'A espada de Yahweh está pingando sangue; coberta de gordura, está pingando o sangue dos cordeiros e bodes, coberta com a gordura dos rins dos carneiros. Porque Yahweh tem um sacrifício em Bozra e uma grande matança na terra de Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Os bois selvagens serão abatidos junto a eles, e os touros, com os novilhos. A sua terra será embriagada com sangue e nela ficará a grossa poeira com a gordura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Este será o dia da vingança para Yahweh, o ano em que vai retribuí-los por causa de Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Os riachos de Edom se tornarão em piche, a sua poeira, em enxofre, sua terra se tornará um piche ardente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'E queimará dia e noite; a sua fumaça subirá para sempre; de geração em geração, será uma terra devastada; ninguém passará por ela, para todo o sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Mas os pássaros selvagens e os animais viverão ali; a coruja e o corvo farão lá os seus ninhos. Ele estenderá sobre ela a linha de medição da ruína e o prumo de destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Seus nobres não terão algo para chamar de reino e todos os seus príncipes nada serão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Espinhos crescerão em seus palácios, urtigas e ervas daninhas em suas fortalezas. Será uma habitação de chacais, um lugar para avestruzes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Os animais selvagens e as hienas se encontrarão ali, os bodes selvagens clamarão uns aos outros. Animais noturnos se assentarão e encontrarão esse lugar de descanso para si mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Corujas farão seus ninhos, colocarão seus ovos e os chocarão, e protegerão os seus filhotes. Sim, falcões se reunirão ali, cada um com o seu par.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Consultai o livro de Yahweh; nenhum destes será esquecido. Nenhum ficará sem um parceiro; porque a Sua boca ordenou isso e foi o Seu Espírito que os ajuntou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Ele lançou sorte para seus lugares e a Sua mão mediu a terra com uma corda. Eles a possuirão para sempre, de geração em geração, viverão ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'O deserto e a terra seca ficarão felizes; o deserto se regozijará e florescerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Florescerá abundantemente e se regozijará, cantando com alegria; a glória do Líbano lhe será dada, o esplendor do Carmelo e Sarom; eles verão a glória de Yahweh, o esplendor do nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Fortalecei as mãos fracas e firmai os joelhos que tremem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Dizei àqueles de coração aflito: \"Sede fortes, não temais! Vede! Vosso Deus virá com vingança, com recompensa; Ele virá e vos salvará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Então, os olhos dos cegos verão e os ouvidos dos surdos ouvirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'O homem manco saltará como um cervo e a língua muda cantará, pois água brotará nos lugares desolados e rios, no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'A areia, que queima, se tornará um lago e a terra sedenta, mananciais de água. Na habitação dos chacais, onde uma vez se deitaram, haverá gramado com canas e juncos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Haverá ali uma estrada que será chamada o Caminho Santo. O impuro não passará por lá. Será para aqueles que andam no caminho de Deus, nenhum tolo andará nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Nenhum leão estará lá, nenhuma besta feroz andará nele; eles não serão achados no caminho; porém, o redimido caminhará nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Os resgatados de Yahweh retornarão e virão cantando para Sião, a alegria eterna estará em suas cabeças; felicidade e alegria tomarão conta deles; tristeza e pranto fugirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'No décimo quarto ano do rei Ezequias, Senaqueribe, rei da Assíria, atacou todas as cidades fortificadas de Judá e as conquistou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Então, o rei da Assíria enviou o comandante chefe de Laquis a Jerusalém, ao rei Ezequias, com um grande exército. Ele se aproximou do canal da piscina superior, na estrada para o campo dos lavadores, e ficou ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Os oficiais israelitas que saíram da cidade para falar com eles eram: Eliaquim, filho de Hilquias, o administrador do palácio; Sebna, o secretário do rei e Joá, filho de Asafe, que escreveu as decisões do governo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'O comandante chefe lhes disse: \"Dizei a Ezequias que o grande rei, o rei da Assíria, diz: \'Qual é a origem da tua confiança?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Falas somente palavras inúteis, dizendo que há conselho e poder para a guerra. Agora, em quem confias? Quem te deu coragem para te rebelares contra mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Vê! Tu confias no Egito, aquela cana quebrada na qual te apoias para caminhar, mas, se o homem se apoiar nela, será como um pedaço de pau que furará a sua mão. Isso é o que Faraó, rei do Egito, é para qualquer um que nele confia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Mas, se me disseres: \'Confiamos em Yahweh, nosso Deus\'; não é Ele cujos santuários e altares Ezequias levou embora, e disse para Judá e Jerusalém: \'Vós deveis adorar diante desse altar em Jerusalém\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Agora, pois, quero te oferecer uma boa oferta do meu senhor, o rei da Assíria: Eu te darei dois mil cavalos, se fores capaz de encontrar cavaleiros para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Como poderás resistir a um só capitão dos menores servos do meu senhor? Colocaste tua confiança no Egito por causa de seus carros e cavaleiros!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Agora, então, eu viajei até aqui sem Yahweh, para lutar contra essa terra e destruí-la? Yahweh me disse: \'Ataca essa terra e destrói-a!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Então, Eliaquim, filho de Hilquias; Sebna e Joá disseram ao comandante chefe: \"Por favor, fala a teus servos na linguagem dos arameus, o aramaico, para que possamos entender. Não fales conosco na linguagem de Judá, aos ouvidos das pessoas que estão no muro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Mas o comandante chefe disse: \"Meu senhor enviou-me ao teu senhor e a vós para falar essas palavras? Não me enviou para esses homens que estão sentados no muro, que terão que comer seus próprios excrementos e beber sua própria urina convosco?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Então, o comandante chefe levantou e gritou, na língua judaica, dizendo: \"Ouvi as palavras do grande rei, o rei da Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'O rei diz: \'Não deixeis Ezequias vos enganar, porque ele não será capaz de vos resgatar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Não deixeis Ezequias vos fazer confiar em Yahweh, dizendo: \'Yahweh certamente nos resgatará; esta cidade não será entregue nas mãos do rei da Assíria\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Não deis ouvidos a Ezequias, pois isto é o que o rei da Assíria diz: \"Fazei paz comigo e vinde a mim. Então, cada um de vós comerá da vossa própria videira e da própria figueira, e beberá água da vossa própria cisterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Fareis isso até que eu venha e vos leve para uma terra como a vossa própria terra, uma terra de trigo e vinho novo, uma terra de pão e vinhedos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Não deixeis que Ezequias vos induza ao erro, dizendo: \'Yahweh nos resgatará\'. Porventura, algum dos deuses dos povos os resgatou do poder do rei da Assíria?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Onde estão os deuses de Hamate e de Arpade? Onde estão os deuses de Sefarvaim? Eles resgataram Samaria do meu poder?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Dentre todos os deuses dessas terras, há algum deus que resgatou sua terra do meu poder, como se Yahweh pudesse salvar Jerusalém do meu poder?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Mas o povo permaneceu em silêncio e não lhe respondeu, porque a ordem do rei era: \"Não respondais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Então, Eliaquim, filho de Hilquias, o mordomo; Sebna, o escriba; e Joá, filho de Asafe, o oficial de registro, foram a Ezequias com suas roupas rasgadas e lhe relataram as palavras do comandante chefe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Quando o rei Ezequias ouviu seus relatos, ele rasgou suas roupas, cobriu-se com pano de saco e foi para o templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Ele enviou Eliaquim, que estava a cargo do palácio; Sebna, o escriba, os anciãos e os sacerdotes, todos cobertos com panos de saco, a Isaías, filho de Amoz, o profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Eles lhe disseram: \"Ezequias disse: \'Este dia é o dia da aflição, repreensão e desgraça, como quando um filho está pronto para nascer, mas a mãe não tem forças para dar à luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Talvez Yahweh, teu Deus, ouça as palavras do comandante-chefe, a quem o seu superior, o rei da Assíria, enviou para afrontar o Deus vivo, e repreenda as palavras que Yahweh, teu Deus, ouviu. Agora, eleva tua oração pelos que ainda restam aqui\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Então, os servos do rei Ezequias vieram até Isaías,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'e Isaías lhes disse: \"Dizei a vosso senhor o que Yahweh diz: \'Não temais as palavras que ouvistes, com as quais os servos do rei da Assíria têm insultado a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Eis que Eu colocarei um espírito nele, e ele, ao ouvir um certo relato, voltará para a sua própria terra. Eu farei que ele caia pela espada em sua própria terra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Então, o comandante-chefe retornou e encontrou o rei da Assíria lutando contra Libna, pois ouvira que o rei havia saído de Laquis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Ora, Senaqueribe ouviu que Tiraca, rei da Etiópia e do Egito, havia mobilizado uma luta contra ele; então, ele novamente enviou mensageiros para Ezequias com esta mensagem:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, '\"Dizei a Ezequias, rei de Judá: Que o teu Deus, em quem confias, não te engane, dizendo: \'Jerusalém não será entregue às mãos do rei da Assíria\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Vê! Ouviste o que os reis da Assíria fizeram a todas as terras, destruindo-as completamente. Então, tu pensas que serás livrado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Por acaso, os deuses das nações livraram as que meus pais destruíram: Gozã, Harã, Rezefe e o povo do Éden, em Telassar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Onde está o rei de Hamate, o rei de Arpade, o rei das cidades de Sefarvaim, de Hena e Iva?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Ezequias recebeu esta carta das mãos dos mensageiros e a leu. Então, subiu ao templo de Yahweh e a abriu diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Ezequias orou a Yahweh:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, '\"Yahweh dos Exércitos, Deus de Israel, Tu que estás assentado acima dos querubins, Tu que és o único Deus sobre todos os reinos da terra, Tu que criaste os céus e a terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'inclina Teu ouvido, Yahweh, e ouve. Abre Teus olhos, Yahweh, e vê; ouve as palavras de Senaqueribe, as quais mandou para zombar do Deus vivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Isso é verdade, Yahweh: os reis da Assíria destruíram todas as nações e suas terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'Eles queimaram seus deuses, pois não eram deuses, mas o trabalho das mãos de homens, apenas madeira e pedra. Por isso, os assírios os destruíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Agora, Yahweh, nosso Deus, salva-nos do seu poder, para que todos os reinos da terra saibam que Tu és o Único, Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Então, Isaías, filho de Amoz, enviou uma mensagem a Ezequias, dizendo: \"Yahweh, o Deus de Israel, diz: \'Porque oraste a Mim a respeito de Senaqueribe, rei da Assíria,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'esta é a palavra que Yahweh falou sobre ele: \'A filha virgem de Sião te despreza e ri escarnecendo de ti; a filha de Jerusalém meneia a cabeça zombando de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'A quem tu afrontaste e insultaste? E contra quem exaltaste tua voz, levantando teus olhos com orgulho? Contra o Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Por meio dos teus servos, afrontaste o Senhor, e disseste: \'Com a multidão das minhas carruagens, subi até o alto das montanhas, até as mais altas elevações do Líbano. Eu cortarei seus altos cedros e os ciprestes selecionados e entrarei no mais distante dos altos lugares, na mais frutífera floresta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Eu cavei poços e bebi água; sequei todos os rios do Egito debaixo das solas dos meus pés\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Não ouviste como Eu determinei isso há muito tempo e planejei isso em tempos antigos? Agora, estou fazendo isso acontecer. Tu estás aqui para reduzir as cidades fortificadas a um monte de ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Seus habitantes, de pouca força, são despedaçados e envergonhados. Eles são plantas no campo, grama verde, o mato no telhado ou no campo, antes do vento do leste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Mas Eu conheço o teu assentar, a tua saída, a tua chegada e a tua fúria contra Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Por causa da tua fúria contra Mim, e porque tua arrogância chegou aos Meus ouvidos, Eu colocarei Meu anzol em teu nariz, Meu freio em tua boca; Eu farei com que voltes pelo mesmo caminho pelo qual vieste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Isto será um sinal para ti: neste ano, comereis o que crescer na terra, e, no segundo ano, o que crescer a partir deste. Mas, no terceiro ano, deveis plantar e colher, plantar vinhas e comer dos seus frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'O remanescente da casa de Judá que sobreviver lançará raiz novamente, e produzirá fruto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Pois, a partir de Jerusalém, um remanescente sairá; os sobreviventes virão do monte Sião. O zelo de Yahweh dos Exércitos fará isso\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Portanto, Yahweh disse assim sobre o rei da Assíria: \"Ele não entrará nesta cidade, nem lançará flecha aqui. Nem virá até ela com escudo ou levantará rampa de cerco contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'O caminho pelo qual veio será o mesmo caminho pelo qual sairá; ele não entrará nesta cidade\" — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, '\"Eu defenderei esta cidade e a resgatarei, por amor de Mim e por amor do Meu servo Davi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Então, o anjo de Yahweh saiu e atacou o acampamento dos assírios, matando cento e oitenta e cinco mil soldados. Quando os homens se levantaram cedo de manhã, havia cadáveres deitados por toda parte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Então, Senaqueribe, rei da Assíria, deixou Israel e foi para casa. Voltou para Nínive e ali ficou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Depois, enquanto Senaqueribe estava adorando na casa de seu deus — Nisroque —, seus filhos Adrameleque e Sarezer o mataram com a espada. Então, eles fugiram para a terra de Ararate. Esar-Hadom, seu filho, reinou em seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Naqueles dias, Ezequias estava doente a ponto de morrer. Então, Isaías, filho de Amoz, o profeta, veio a ele e lhe disse: \"Yahweh diz: \'Coloca tua casa em ordem, pois tu morrerás; não viverás!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Então, Ezequias virou sua face para a parede e orou a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Ele disse: \"Por favor, Yahweh, traz à memória como tenho andado fielmente diante de Ti, com todo o meu coração, e como tenho feito o que é bom aos Teus olhos\"; e Ezequias chorou em alta voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Então a palavra de Yahweh veio a Isaías, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, '\"Vai e diz a Ezequias, o líder do Meu povo: \'Isto é o que Yahweh, o Deus de Davi, teu ancestral, diz: ‘Eu ouvi tua oração, e vi tuas lágrimas. Vê! Eu acrescentarei quinze anos à tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'E Eu resgatarei a ti e a esta cidade do poder do rei da Assíria e defenderei esta cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'E este será o sinal para ti, da parte de Yahweh, de que Eu farei o que prometi:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Olha! Eu farei a sombra na escada de Acaz retroceder dez degraus\'\". Então, a sombra retrocedeu dez degraus na escada, na qual havia avançado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Esta foi a oração escrita de Ezequias, rei de Judá, quando ficou doente e se recuperou:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, '\"Eu disse que, na metade da minha vida, passaria pelos portões do Sheol; e sou enviado até lá pelo resto dos meus anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Eu disse que não veria mais Yahweh na terra dos vivos; não mais contemplaria a humanidade ou os habitantes do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Minha vida foi removida e tomada de mim, como uma tenda de pastor; minha vida foi enrolada como um tecedor. Tu me cortastes do Teu tear; entre o dia e a noite, Tu estás terminando com minha vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Clamei até o amanhecer; como um leão, Ele quebra todos os meus ossos. Entre o dia e a noite, Tu estás acabando com minha vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Como uma andorinha, eu gorjeio; arrulho como uma pomba; meus olhos se tornam cansados de olhar para cima. Senhor, estou oprimido; ajuda-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'O que devo dizer? Ele também falou comigo e Ele mesmo fez isso; andarei lentamente todos os meus anos, pois estou sobrecarregado de aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Senhor, os sofrimentos que me enviaste são bons para mim; que minha vida me seja restituída. Tu restauraste minha vida e minha saúde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Foi para meu benefício que experimentei tamanha aflição. Tu me resgataste da cova da destruição, pois Tu lançaste todos os meus pecados para trás de Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Pois o Sheol não Te agradece; a morte não Te louva; aqueles que descem até a sepultura não esperam na Tua fidelidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'A pessoa viva, a pessoa viva, ela é que Te agradece, como faço neste dia; o pai faz conhecer aos filhos a Tua fidelidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Yahweh está prestes a me salvar, e celebraremos com música, todos os dias de nossas vidas, na casa de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Ora, Isaías havia dito: \"Tragam uma pasta de figos amassados, coloquem-na na úlcera e ele será curado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Ezequias também havia perguntado: \"Qual será o sinal indicando que deverei subir ao templo de Yahweh?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Naquele tempo, Merodaque Baladão, filho de Baladão, rei da Babilônia, enviou cartas e um presente para Ezequias, pois ouviu que ele esteve enfermo e havia se recuperado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Ezequias ficou feliz com aquilo. Ele mostrou aos mensageiros onde armazenava suas coisas de valor — prata, ouro, especiarias e azeite fino — e mostrou também seu arsenal e tudo que existia em seus depósitos. Não ficou nada em sua casa, nem em toda extensão de seu reinado, que Ezequias não tenha mostrado aos mensageiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Depois disso, o profeta Isaías veio até onde estava Ezequias e indagou: \"O que esses homens te disseram? De onde vieram?\". Respondeu Ezequias: \"Eles vieram de uma terra distante, da Babilônia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Isaías perguntou: \"O que viram em tua casa?\". Ezequias respondeu: \"Eles viram tudo que existe em minha casa. Não ficou nada de valor entre minhas coisas que não tenham visto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Isaías, então, disse a Ezequias: \"Ouve a palavra de Yahweh dos Exércitos:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, '‘Logo chegarão os dias quando tudo que estiver no teu palácio, as coisas que teus pais guardaram até o presente, serão levadas para Babilônia. Nada será deixado para trás’, diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, '“E os teus descendentes, que tu mesmo geraste, eles os levarão embora, e se tornarão eunucos no palácio do rei da Babilônia”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Ezequias disse para Isaías: “É boa a palavra de Yahweh a qual tu disseste”; pois pensava consigo: “Haverá paz e estabilidade durante os meus dias”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, '\"Consolai, consolai Meu povo\", diz vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, '\"Falai com ternura a Jerusalém; proclamai a ela que sua guerra terminou, que sua iniquidade está perdoada, que ela, por todos os seus pecados, recebeu em dobro da mão de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Uma voz clama: \"No deserto, preparai o caminho de Yahweh; fazei uma estrada reta no deserto para o nosso Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Todo vale será levantado; toda montanha e colina será nivelada; a terra acidentada será feita plana e os lugares íngremes serão aplanados;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'a glória de Yahweh será revelada e todos juntos a verão, pois assim a boca de Yahweh falou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Uma voz diz: \"Clama!\". Outra responde: \"O que eu deveria clamar?\". \"Toda carne é relva e toda a sua fama é como a flor do campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'A relva seca e a flor murcha quando o fôlego de Yahweh sopra sobre elas; certamente, a humanidade é relva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'A relva seca, a flor murcha, mas a palavra do nosso Deus permanecerá para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Vai para uma alta montanha, Sião, portadora das boas notícias. Grita em voz alta, Jerusalém. Tu, que trazes boas notícias, levanta a tua voz, não tenhas medo. Dize às cidades de Judá: \"Eis aqui vosso Deus!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Vede, o Senhor Yahweh vem como um guerreiro vitorioso, e Seu braço forte governa por Ele. Vede! Seu galardão está com Ele, e aqueles que Ele resgatou vão diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Ele alimentará Seu rebanho como um pastor; reunirá, em Seus braços, os cordeiros e os carregará perto de Seu coração; mansamente, conduzirá as ovelhas que amamentam seus filhotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Quem já mediu as águas na concha de Sua mão, mediu a expansão do céu a palmos, conteve o pó da terra em uma cesta, pesou as montanhas com balanças ou as colinas com pratos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Quem compreendeu a mente de Yahweh, ou O instruiu como Seu conselheiro?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'De quem Ele já recebeu instrução? Quem O ensinou a fazer coisas corretas, ou Lhe ensinou a sabedoria, ou Lhe mostrou o caminho do entendimento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Vede! As nações são como uma gota em um balde; são consideradas como pó nas balanças. Vede! Ele pesa as ilhas como um grão de poeira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'O Líbano não é combustível suficiente, nem os animais selvagens são bastantes para serem queimados como ofertas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Todas as nações são insuficientes diante Dele; elas são consideradas por Ele como nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'A quem, então, comparareis Deus? A qual ídolo O comparareis?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Um ídolo, que um artesão molda, o ourives o cobre de ouro e forja correntes de prata para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'A fim de fazer uma oferta, alguém escolhe uma madeira que não apodrece e procura um artesão habilidoso para fazer um ídolo que não tombe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Por acaso vós não sabeis? Não tendes ouvido? Isso não vos foi dito desde o início? Não entendestes desde a fundação da terra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Ele é o que Se assenta acima do horizonte da terra; os habitantes são como gafanhotos diante Dele. Ele estende os céus como uma cortina e os espalha como uma tenda para nela habitar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Ele reduz os governantes a nada; torna insignificantes os juízes da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Mal foram plantados, mal foram semeados, mal seus caules firmam raízes na terra, quando Ele sopra sobre eles, então murcham e o vento os leva como palha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, '\"A quem, então, Me comparareis? A quem Me assemelho?\", diz o Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Olhai para o céu! Quem criou todas essas estrelas? Ele faz sair o exército delas e chama todas pelo nome. Pela grandeza de Sua força e pelo vigor de Seu poder, nenhuma delas se perde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Por que dizes, Jacó, e declaras, Israel: \"Meu caminho está escondido de Yahweh\", e \"Meu Deus não está preocupado com o meu direito\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Por acaso não sabes? Não ouviste? O eterno Deus, Yahweh, o Criador dos confins da terra, não Se cansa nem Se fatiga; não há limite para o Seu entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Ao cansado, Ele dá força, e ao fraco, restaura o vigor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Até os jovens se cansam e fatigam, e os moços tropeçam e caem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Mas aqueles que esperam por Yahweh renovarão suas forças; eles subirão com asas como águias; correrão e não se cansarão; caminharão e não se enfraquecerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, '\"Calai-vos diante de Mim, terras costeiras; que as nações renovem suas forças; que se aproximem e falem; ajuntemo-nos para discutir uma questão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Quem instigou aquele que vem do leste, chamando-o em justiça para o Seu serviço? Ele lhe entrega nações e o ajuda a subjugar reis; com a sua espada, Ele os faz como pó; com o seu arco, Ele os faz como a palha levada pelo vento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Ele os persegue e passa adiante deles em segurança, percorrendo com agilidade um caminho que seus pés pouco tocaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Quem realizou e completou esses feitos? Quem convocou as gerações desde o princípio? Eu, Yahweh, o primeiro e com os últimos, Eu o Sou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'As ilhas viram isso e temeram; os confins da terra tremem; eles se aproximam e vêm chegando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Cada um ajuda o seu próximo e todos dizem um para o outro: \'Sê corajoso\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Assim o carpinteiro encoraja o ourives, e o que trabalha com o martelo encoraja o que trabalha com a bigorna, dizendo acerca da solda: \'É boa\'. Eles a prendem com pregos para que não tombe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Mas tu, Israel, Meu servo, Jacó, a quem Eu escolhi, descendência de Abraão, Meu amigo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'tu, a quem Eu trouxe de volta dos confins da terra, a quem Eu chamei de lugares distantes e a quem Eu disse: \'Tu és Meu servo\', Eu te escolhi e não te rejeitei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Não temas, pois Eu sou contigo. Não fiques ansioso, pois Eu sou teu Deus. Eu te fortalecerei e te ajudarei; Eu te sustentarei com a Minha mão direita de justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Vê, todos que estavam irados contra ti ficarão envergonhados e desonrados; aqueles que se opõem a ti serão como o nada e perecerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Tu procurarás e não encontrarás aqueles que disputavam contra ti; aqueles que guerreavam contra ti serão como nada, absolutamente nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Pois Eu, Yahweh, teu Deus, segurarei tua mão direita e te direi: \'Não temas; Eu estou te ajudando\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Não temas, vermezinho de Jacó, e vós, homens de Israel; Eu te ajudarei — esta é a declaração de Yahweh, o teu Redentor, o Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Vê, Eu te farei como uma lâmina de debulhar, afiada, nova e com dois gumes; tu debulharás as montanhas e as moerás; tu farás das colinas como palha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Tu os peneirarás e o vento os levará; o vento os dispersará. Tu te regozijarás em Yahweh e te gloriarás no Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Os oprimidos e necessitados procuram água, mas não há; suas línguas estão secas de sede. Eu, Yahweh, responderei às orações deles; Eu, o Deus de Israel, não os abandonarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Farei os ribeiros fluírem descendo as encostas e as fontes no meio dos vales; transformarei o deserto em um tanque de água e a terra seca, em fontes de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'No deserto, Eu porei o cedro, a acácia, a murta e a oliveira; no deserto, colocarei pinheiros, ciprestes e buxos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Eu farei isso para que todos vejam, reconheçam e juntos entendam que a mão de Yahweh fez isso, o Santo de Israel criou tudo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, '\"Apresentai a vossa causa\", diz Yahweh; \"Trazei vossos melhores argumentos\", diz o Rei de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Que eles apresentem seus melhores argumentos; que eles se apresentem para nos declarar o que acontecerá, para que saibamos bem acerca dessas coisas. Que eles nos contem predições do futuro, para que possamos refletir sobre elas e saibamos como terão se cumprido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Contai a respeito do futuro, para que saibamos se sois deuses; fazei coisas boas ou más, para que fiquemos espantados e impressionados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Vede, vossos ídolos são nada; vossos feitos são nada; aquele que vos escolhe é abominável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, '\"Eu levantei alguém do norte e ele vem; de onde o sol nasce, Eu convocarei aquele que chama pelo Meu nome, e ele pisará os governantes como lama, como um oleiro que pisa o barro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Quem anunciou isso desde o início, para que saibamos? E, antes do tempo, para que disséssemos: \'Ele é justo?\'. De fato, nenhum deles decretou nem predisse isso; sim, ninguém vos ouviu dizer coisa alguma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Eu fui o primeiro que disse a Sião: \'Vede, aqui estão eles\'; enviei um arauto a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Quando olho, não há ninguém dentre eles que dê bom conselho, e, quando Eu pergunto, ninguém responde palavra alguma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Vede, todos eles são nada e seus feitos são nada; as suas imagens de metal são vazias como o vento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Eis aqui o Meu Servo, a Quem Eu sustento; o Meu Escolhido, em Quem tenho alegria. Eu pus o Meu Espírito sobre Ele; Ele trará justiça às nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Não clamará, nem gritará; não fará Sua voz ser ouvida nas ruas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'A cana esmagada, Ele não a quebrará e o pavio que fumega, Ele não o apagará; Ele estabelecerá a justiça com fidelidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Não Se cansará, nem desanimará, até que tenha estabelecido a justiça na terra; e as terras costeiras esperarão por Sua Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Assim diz Deus Yahweh — Aquele que criou os céus e os estendeu, que fez a terra e tudo que ela produz, que dá fôlego às pessoas que nela vivem e vida aos que nela habitam:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, '“Eu, Yahweh, Te chamei em justiça e segurarei a Tua mão. Eu Te guardarei e Te estabelecerei como aliança para o povo, como uma luz para os gentios,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'para abrires os olhos dos cegos, para libertares os cativos da prisão e, do cárcere, aqueles que estão nas trevas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Eu sou Yahweh, este é o Meu nome; Minha glória Eu não darei a nenhum outro, nem Meu louvor aos ídolos de escultura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Eis que as primeiras coisas já se passaram; agora, Eu anuncio coisas novas. Antes que aconteçam, Eu vos contarei sobre elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Cantai a Yahweh uma nova canção e Seu louvor desde os confins da terra; vós, os que navegais pelo mar e tudo quanto nele há; vós, terras costeiras, e aqueles que lá vivem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Que o deserto e as cidades clamem, as aldeias onde Quedar habita gritem de alegria! Que os moradores de Selá cantem; gritem do alto dos montes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Que eles deem glória a Yahweh e anunciem Seu louvor nas ilhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Yahweh sairá como um guerreiro; como um homem de guerra, Ele despertará Seu zelo. Gritará, sim, dará Seus gritos de guerra; Ele mostrará Seu poder aos Seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Eu Me calei por um longo tempo, e tenho ainda Me contido; agora darei gritos como uma mulher que está em trabalho de parto; Eu gemerei e suspirarei ofegantemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Arrasarei montanhas e colinas e farei secar toda a sua vegetação; transformarei rios em ilhas e secarei os pântanos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Guiarei os cegos por um caminho que eles não conhecem; Eu os conduzirei por veredas que eles não conhecem. Transformarei as trevas em luz diante deles e farei retos os caminhos tortuosos. Essas coisas Eu farei e não os abandonarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Mas voltarão, e serão completamente envergonhados, aqueles que confiam em imagens de esculturas, aqueles que dizem às imagens de fundição: \"Vós sois nossos deuses\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Surdos, ouvi; olhai, vós, cegos, para que vejam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Quem é cego, senão o Meu servo? Ou surdo como o mensageiro que Eu enviei? Quem é tão cego quanto Meu parceiro de aliança, ou cego como o servo de Yahweh?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Tu vês muitas coisas, mas não as compreendes; os ouvidos estão abertos, mas nada ouves.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Agradou a Yahweh louvar Sua justiça e fazer Sua Lei gloriosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Este é um povo roubado e saqueado; todos eles estão presos em covas, mantidos cativos em prisões; eles se tornaram um despojo sem ninguém para os salvar, e ninguém disse: \"Traze-os de volta!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Quem dentre vós ouvirá isso? Quem ouvirá e atenderá no futuro?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Quem deu Jacó por despojo e Israel aos saqueadores? Não foi Yahweh, contra quem nós temos pecado, em cujos caminhos eles se recusaram a andar e cuja Lei se recusaram a obedecer?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Portanto, Ele derramou a indignação de Sua ira contra eles, com devastação de guerra, e ardeu em chamas ao redor deles, mas não perceberam isso. Queimou-os, mas eles não colocaram isso no coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Mas agora, é isto o que Yahweh diz. Ele, que vos criou, ó Jacó; Ele, que vos formou, ó Israel: \"Não temais, porque Eu vos redimi; Eu vos chamei pelo vosso nome. Sois Meus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Quando passares pelas águas, Eu estarei contigo; quando passares pelos rios, eles não te submergirão; quando passares pelo fogo, não te queimarás, nem as chamas te causarão dano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Porque Eu Sou Yahweh, teu Deus, o Santo de Israel, teu Salvador. Eu dei o Egito para te resgatar, a Etiópia e Seba em teu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Visto que és precioso e especial aos Meus olhos, porque Eu te amo; por isso, darei pessoas em teu lugar e outros povos em troca de tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Não temas, pois estou contigo. Eu trarei tua descendência do leste, e te ajuntarei desde o oeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Direi ao norte: \'Entrega-os\' e, ao sul: \'Não retenhas ninguém! Trazei Meus filhos de longe e Minhas filhas das regiões remotas da terra');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, '— todos os que são chamados pelo Meu Nome, os que Eu criei para Minha glória, aqueles que Eu formei, sim, aqueles que Eu fiz\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Trazei o povo que tem olhos, mas é cego, que tem ouvidos, mas é surdo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Todas as nações se ajuntem e os povos se reúnam. Quem dentre eles declarou isto e anunciou eventos passados? Que tragam suas testemunhas para provarem que estão certos, que eles ouçam e afirmem: \'Isso é verdade\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Vós sois Minhas testemunhas\", declara Yahweh; \"e Meu servo, a quem escolhi, para que conheçam e acreditem em Mim e entendam quem Eu Sou. Antes de Mim, nenhum deus se formou, e não haverá nenhum depois de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Eu, Eu Sou Yahweh e não há salvador além de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Eu declarei, salvei e proclamei e não há nenhum outro deus entre vós. Vós sois Minhas testemunhas\", declara Yahweh; \"Eu Sou Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Desde toda a eternidade, Eu o Sou e não há quem possa resgatar alguém das Minhas mãos. Agindo Eu, quem pode mudar o que Eu faço?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Isto é o que Yahweh diz, vosso Redentor, o Santo de Israel: \"Por vossa causa, Eu enviei um exército contra a Babilônia e conduzi todos os fugitivos de lá, transformando em lamentação as expressões de alegria dos babilônios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Eu Sou Yahweh, vosso Santo, o Criador de Israel, vosso Rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Isto é o que Yahweh diz — Aquele que abriu um caminho no mar e uma vereda nas águas impetuosas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'Aquele que conduziu o carro, o cavalo, o exército e a tropa poderosa. Eles caíram juntos, nunca se levantarão novamente; foram extintos, apagados como um pavio queimado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, '\"Não penseis sobre essas coisas antigas, nem considereis as coisas de tempos atrás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Vede, Eu estou prestes a fazer uma coisa nova; agora, isso começou a acontecer; vós não o percebestes? Eu vou fazer uma estrada na terra seca e correntes de água no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Os animais selvagens do campo Me honrarão, e também os chacais e os avestruzes, porque Eu dei água ao deserto e rios para a terra seca, para Meus escolhidos beberem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'pessoas que Eu formei para Mim a fim de declararem Meu louvor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Mas vós não Me chamastes, Jacó; vós vos cansastes de Mim, Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Não Me trouxeste algumas das tuas ovelhas, como ofertas queimadas, nem Me honraste com vossos sacrifícios. Eu não te sobrecarreguei com ofertas de grãos, nem te cansei com ofertas de incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Não compraste cana de cheiro doce, nem derramaste para Mim a gordura de teus sacrifícios; mas Me sobrecarregaste com teus pecados, Me cansaste com tuas maldades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Eu, sim, Eu Sou aquele que apaga tuas ofensas por causa de Mim; e Eu não trarei à mente teus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Lembra-Me do que aconteceu. Vamos debater juntos; apresenta tua causa para que tua inocência seja provada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Teu primeiro pai pecou e teus primeiros líderes se rebelaram contra Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Por isso, Eu profanei os líderes do santuário; entreguei Jacó para a destruição completa e Israel para humilhação extrema\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Agora ouve, Jacó, Meu servo, ó Israel, a quem Eu escolhi:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Isto é o que Yahweh diz, Aquele que te criou e te formou no ventre e que te ajudará: \"Não temas, Jacó, Meu servo; e tu, Jesurum, a quem Eu escolhi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Porque Eu derramarei água na terra sedenta e ribeiros sobre a terra seca; Eu derramarei Meu Espírito sobre a tua descendência e a Minha bênção sobre os teus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Eles brotarão em meio à grama, como salgueiros junto a correntes de águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Um dirá: \'Eu pertenço a Yahweh\'; outro se chamará pelo nome de Jacó; outro escreverá, em sua mão, \'Pertenço a Yahweh\', e será chamado pelo nome de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Isto é o que Yahweh diz, o Rei de Israel e seu Redentor, Yahweh dos Exércitos: \"Eu Sou o primeiro e o último. Não há outro Deus além de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Quem é igual a Mim? Que o anuncie e explique os eventos que ocorreram desde que Eu estabeleci Meu povo antigo; que declarem os eventos que estão por vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Não temais, nem vos espanteis. Eu não declarei isso há muito tempo e não o anunciei? Vós sois Minhas testemunhas: há outro Deus além de Mim? Não há outra Rocha; Eu não conheço nenhuma\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Todos os que fazem ídolos são nada. As coisas nas quais se deleitam são inúteis; suas testemunhas não podem ver ou saber de nada, e eles serão envergonhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Quem formaria um deus ou fundiria um ídolo que é inútil?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Eis que todos os seus companheiros serão envergonhados. Os artesãos são apenas homens. Que eles se apresentem juntos; eles se acovardarão e serão envergonhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'O ferreiro trabalha com suas ferramentas e forma o ídolo, trabalhando sobre as brasas. Ele o molda com os martelos e trabalha nisso com seu braço forte. Ele passa a ter fome e sua força diminui; ele não bebe água e fica enfraquecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'O carpinteiro mede a madeira com uma linha e a marca com um lápis. Ele lhe dá forma com suas ferramentas e a marca com um compasso. Ele a molda conforme a figura de um homem, com a beleza de um ser humano, para ficar em uma casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Ele corta os cedros, ou escolhe um cipreste ou um carvalho. Ele mesmo busca árvores na floresta; planta um pinheiro e a chuva o faz crescer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'E utiliza a madeira para fogo e para aquecer a si próprio. Sim, ele acende o fogo e assa o pão. Então, dela, ele faz um deus, e se curva perante ele; faz um ídolo e se prostra diante dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Ele queima parte da madeira no fogo, onde assa sua carne. Então, come e se satisfaz. Ele se aquece e diz: \"Ah, eu me aqueço, estou vendo o fogo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Com o restante da madeira, ele faz um deus, uma imagem esculpida; ele se curva perante ela e a reverencia; ora a ela, dizendo: \"Resgata-me, porque tu és o meu deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Eles não sabem, nem mesmo entendem, porque seus olhos estão cegos e não podem ver, e seus corações não podem perceber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Ninguém pensa; não há compreensão para dizer: \"Eu queimei parte da madeira no fogo; sim, eu também assei pão sobre as suas brasas. Eu assei carne sobre essas brasas e comi. Agora deveria eu fazer da outra parte da madeira alguma coisa repugnante para adorar? Deveria eu me prostrar a um pedaço de madeira?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'É como se ele estivesse comendo cinzas; seu coração enganoso o desviou. Ele não pode resgatar a si mesmo, nem dizer: \"Esta coisa na minha mão direita é um falso deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Pensa sobre essas coisas, ó Jacó, pois tu és o Meu servo, ó Israel: Eu te formei, tu és Meu servo. Israel, tu não serás esquecido por Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Eu desfiz teus atos rebeldes como uma nuvem espessa; e os teus pecados, como uma nuvem. Volta-te para Mim, porque Eu te redimi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Cantai, ó céus, porque Yahweh fez isto; exultai, regiões mais baixas da terra. Irrompam com júbilo, vós, montes, e também vós, florestas e todas as vossas árvores, porque Yahweh redimiu Jacó e mostrará a Sua glória em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Isto é o que Yahweh diz, o teu Redentor, Aquele que te formou desde o ventre: \"Eu sou Yahweh, que fiz todas as coisas; que, sozinho, estendi os céus; sozinho, formei a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Eu que frustro os presságios dos faladores fúteis e desonro aqueles que leem premunições; Eu que derrubo a sabedoria dos sábios e faço dos seus conselhos tolices.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Eu, Yahweh, que cumpro as declarações do Meu servo e trago o conselho dos Meus mensageiros; que digo de Jerusalém: \'Ela será habitada\', e, das cidades de Judá: \'Elas serão construídas novamente e Eu levantarei os seus lugares devastados\';');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'que digo ao profundo mar: \'Seca-te, e Eu secarei as tuas correntes\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Yahweh é quem diz de Ciro: \'Ele é o Meu pastor, e fará tudo o que Eu desejo; ele decretará sobre Jerusalém: \'Ela será reconstruída\'; e, sobre o templo: \'Suas fundações serão estabelecidas\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Isto é o que Yahweh disse a Ciro, Seu ungido, cuja mão direita Eu seguro, a fim de subjugar as nações diante dele, uma após outra, desarmar os reis e abrir portas diante dele, de modo que portões permanecerão abertos:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, '\"Eu irei adiante de vós e nivelarei as montanhas; Eu quebrarei em pedaços as portas de bronze e despedaçarei as trancas de ferro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'e darei a ti o tesouro das trevas e as riquezas escondidas no caminho; e saberás que sou Eu, Yahweh, quem te chamou pelo nome. Eu, o Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Por amor de Jacó, Meu servo, de Israel, Meu escolhido, te chamei pelo nome: dei a ti um título de honra, embora não Me conheças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Eu sou Yahweh, e não há outro; não há outro Deus além de Mim. Eu te prepararei para a batalha, mesmo que tu não Me conheças;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'para que o povo saiba que, do nascer do sol até o poente, não há outro Deus além de Mim. Eu sou Yahweh, e não há outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Eu formo a luz e crio as trevas; Eu faço a paz e crio a calamidade; Eu sou Yahweh, que faço todas essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Derramai, ó céus, chuvas do alto; derrama do céu a justiça. Deixa que a terra a absorva e produza a salvação, e, junto com ela, brote a retidão. Eu, Yahweh, as criei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Ai de quem discutir com Aquele que o formou! Para Ele, não passa de vaso de barro entre outros vasos de barro no chão! Poderia o barro dizer ao oleiro: \'O que tu fazes?\' ou: \'O que estás fazendo?\', \'Teu trabalho não teve mãos quando foi feito?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Ai daquele que diz para um pai: \'O que geras?\' ou para uma mulher: \'O que dás à luz?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Isto é o que Yahweh diz, o Único Santo de Israel, seu Criador: \'Por que tu perguntas o que farei sobre Meus filhos? Falarás para Mim sobre o que farei com o trabalho das Minhas mãos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Eu fiz a terra e nela criei o homem. Foram as Minhas mãos que estenderam para fora os céus e Eu dei ordem para as estrelas brilharem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Eu levantei Ciro na Minha justiça e Eu endireitarei todos os seus caminhos. Ele edificará a Minha cidade; ele deixará os exilados do Meu povo irem para casa, não por preço nem por suborno\'\", diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Isto é o que Yahweh diz: \"Os ganhos do Egito e as mercadorias da Etiópia, com os sabeus, homens de grande estatura, serão trazidos a ti. Eles serão teus. Eles te seguirão, chegando acorrentados. Eles se curvarão a ti e suplicarão, dizendo: \'Certamente, Deus é contigo e não há outro além Dele\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Verdadeiramente, Tu és o Deus que Te escondes, o Deus de Israel, o Salvador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Eles serão envergonhados e desonrados juntos; estes que esculpem ídolos caminharão em humilhação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Mas Israel será salvo por Yahweh, com salvação eterna; tu nunca mais serás envergonhado ou humilhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Porquanto, assim diz Yahweh, que criou os céus, o verdadeiro Deus que criou a terra, que a criou e a estabeleceu; Ele a criou, não como um desperdício, mas a projetou para ser habitada: \"Eu sou Yahweh, e não há outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Eu não falei em algum lugar particular ou oculto; Eu não falei para os descendentes de Jacó: \'Busquem-Me em vão\'. Eu sou Yahweh, que falo com sinceridade; Eu declaro as coisas que estão certas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Congregai-vos e vinde! Reuni-vos todos vós, refugiados entre as nações! Não têm conhecimento os que carregam imagens de escultura e oram para deuses que não podem salvar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Aproximai-vos e declarai isso para Mim; apresentai a evidência! Deixai que conspirem juntos. Quem mostrou essas coisas há muito tempo atrás? Quem as anunciou? Não fui Eu, Yahweh? Não existe Deus além de Mim, um Deus justo e Salvador; não há outro além de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Voltai-vos para Mim e sereis salvos, vós, de todos os confins da terra; pois Eu sou Deus, e não há outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Juro por Mim mesmo, declaro Meus justos decretos e não voltarei atrás: \'todo joelho se dobrará, toda língua jurará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Dirão a Mim: \'Só em Yahweh há salvação e força\'\". Todos os que com Ele estão zangados O servirão, envergonhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Em Yahweh, toda a descendência de Israel será justificada; Nele, eles se gloriarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel se curva, Nebo se inclina; seus ídolos são transportados sobre animais de carga. Esses ídolos que vós carregais são cargas pesadas sobre os animais exaustos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Juntos, eles se curvam e se ajoelham; não podem livrar-se dessas imagens e eles próprios foram para o cativeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Ouvi-Me, casa de Jacó, todos vós, o remanescente da casa de Israel, que tenho carregado antes do vosso nascimento, desde o ventre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'E, mesmo na vossa velhice, Eu sou o mesmo; até quando vossos cabelos se tornarem brancos, Eu vos carregarei. Eu vos fiz e vos sustentarei e vos protegerei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'A quem Me comparareis? Com que vós achais que Me pareço, a fim de ser comparado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'O povo tira ouro de suas sacolas e pesa prata na balança; eles contratam um ferreiro, que transforma isso em um deus; inclinam-se diante dele e o adoram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Eles o colocam sobre os ombros e o levam; colocam-no em seu lugar; ali permanece, não se move. Clamam a ele, mas este não pode responder nem salvar ninguém dos seus problemas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Pensai nestas coisas, nunca as ignoreis, vós rebeldes!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Pensai nas coisas passadas, naquelas dos tempos antigos, porque Eu Sou Deus e não há outro, Eu Sou Deus e não há ninguém semelhante a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Eu anuncio o fim desde o início, e antecipo aquilo que ainda não aconteceu. Eu digo: \"Meu plano acontecerá, e faço como Eu desejo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Chamo uma ave de rapina do leste, o homem da Minha escolha de uma terra distante; sim, Eu disse, Eu também o cumprirei; Eu designei por propósito, Eu também o farei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Ouvi-Me, vós, insubordinados que estão longe de fazer o que é correto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Estou trazendo para perto a Minha justiça; ela não está longe e Minha salvação não demora; Eu trarei salvação a Sião e a Minha glória, a Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Desce e senta-te no pó, virgem filha da Babilônia; senta-te no chão sem um trono, filha dos caldeus. Tu não mais serás chamada graciosa e delicada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Pega o moinho e mói a farinha; remove teu véu e a cauda de teu vestido, descobre tuas pernas, atravessa os ribeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Tua nudez será descoberta, sim, tua vergonha será vista: Eu Me vingarei e não pouparei um homem sequer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Nosso Redentor, Yahweh dos Exércitos, é o Seu nome, o Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Senta-te em silêncio e vai para a escuridão, filha dos caldeus; pois não mais serás chamada rainha de reinos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Eu estava furioso com Meu povo; corrompi a Minha herança e a dei em tuas mãos, mas tu não mostraste qualquer misericórdia; colocaste pesada opressão sobre os idosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Disseste: \"Dominarei para sempre como rainha soberana\". E, até agora, não levaste a sério essas coisas, nem consideraste como elas terminariam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Então, agora ouve isto, tu que amas o prazer e estás segura, tu que dizes em teu coração: \"Eu existo, e não há ninguém como eu; nunca me tornarei viúva, nem jamais experimentarei a perda de filhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Mas ambas estas coisas acontecerão num momento, num dia: a perda de filhos e a viuvez; virão com grande força, apesar das tuas feitiçarias, teus muitos encantos e amuletos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Tu confiaste na tua maldade e disseste: \"Ninguém me vê\"; tua sabedoria e teu conhecimento te desviaram, mas tu dizes em teu coração: \"Eu existo e não há ninguém igual a mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'O desastre te sobrevirá; tu não serás capaz de evitá-lo com teus encantamentos. A destruição virá e tu não serás capaz de desviar-te dela, e a calamidade te atacará de repente, antes que tu saibas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Persiste em lançar teus encantamentos e tuas muitas feitiçarias, as quais tens recitado fielmente desde tua infância; talvez tu serás bem sucedida, talvez espantarás o desastre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Tu estás cansada com tuas muitas consultas; que esses homens te levantem e te salvem, esses que mapeiam os céus e olham para as estrelas, esses que anunciam as luas novas — que eles te salvem do que te acontecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Vê, eles se tornarão como restolho e o fogo os queimará. Eles não salvarão a si mesmos do poder das chamas. Não há carvão para aquecê-los e nem fogo para se sentarem em volta!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Isso é o que eles se tornaram para ti, aqueles com quem tu trabalhaste, com quem fizeste comércio desde a tua juventude; cada um deles continua cometendo suas próprias tolices; e, quando tu clamares por socorro, não haverá ninguém para te salvar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Ouvi isto, casa de Jacó, vós que sois chamados pelo nome Israel, que viestes da semente de Judá; vós que jurais pelo nome de Yahweh e invocais o Deus de Israel, mas não com sinceridade nem de maneira justa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Pois eles chamam a si mesmos povo da cidade santa e confiam no Deus de Israel; Yahweh dos Exércitos é o Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, '\"Declarei as coisas de tempos atrás; elas saíram da Minha boca e as fiz conhecidas; então, de repente, agi, e elas aconteceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Porque Eu sabia que tu eras obstinada, os músculos de teu pescoço são rígidos como ferro e tua testa, como o bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Por isso, Eu te declarei essas coisas antecipadamente; antes de acontecerem, Eu te informei para que não dissesses: \'Meu ídolo as fez\', ou: \'Minha imagem esculpida e minha imagem de metal fundido ordenaram essas coisas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Tu ouviste sobre elas, vês toda essa evidência, e não admitirás que aquilo que Eu disse é verdade? De agora em diante, mostrarei a ti coisas novas, antes escondidas, que não sabias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Agora, e não em tempos passados, elas foram criadas e, antes de hoje, não ouviste falar sobre elas para que não digas: \'Sim, eu já sabia\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Tu nunca as ouviste, delas não soubeste; estas coisas não foram abertas aos teus ouvidos anteriormente. Pois Eu sabia que sois muito falsa e que tens sido rebelde desde o nascimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Por amor do Meu nome, adiarei a Minha ira e, pela Minha honra, Me guardarei de destruir-te.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Vê, Eu te refinei, mas não como prata; Eu te purifiquei no forno da aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Por amor a Mim, por amor a Mim, agirei; pois como posso permitir que Meu nome seja desonrado? Não darei Minha glória a ninguém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Ouve-Me, Jacó! Israel, a quem chamei: Eu sou o mesmo; sou o Primeiro e também sou o Último.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Sim, Minha mão estabeleceu a fundação da terra, Minha mão direita estendeu os céus; quando os chamo, eles atendem juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Juntai-vos, vós todos, e ouvi! Quem dentre vós anunciou estas coisas? O aliado de Yahweh cumprirá seu propósito contra a Babilônia. Ele conduzirá a vontade de Yahweh contra os caldeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Eu, Eu falei! Sim, Eu o convoquei. Eu o trouxe, e ele vencerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Vinde para perto de Mim e ouvi isto; desde o início, não falei em segredo; quando isto acontecer, Eu estarei lá\". Agora, o Senhor Yahweh me enviou junto com o Seu Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Isto é o que Yahweh, teu Redentor, o Santo de Israel diz: \"Eu sou Yahweh, teu Deus, que te ensina como vencer, que te guia pelo caminho que deves andar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Ah! Se apenas tivesses obedecido aos Meus mandamentos! Tua paz e tua prosperidade teriam fluído como um rio, e tua justiça, como as ondas do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'Teus descendentes seriam tão numerosos quanto a areia, os filhos do teu ventre tão numerosos quanto os grãos de areia; teu nome não teria sido cortado nem desaparecido diante de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Saí da Babilônia! Fugi dos caldeus! Com gritos de júbilo, anunciai isto! Fazei-o conhecido! Levai-o até os confins da terra! Dizei: \'Yahweh redimiu Seu servo Jacó\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Eles não tiveram sede quando Yahweh os conduziu pelos desertos; para eles, fez a água fluir da rocha; Ele partiu a rocha e as águas jorraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Não há paz para os maus\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Ouvi-me, vós, moradores do litoral! Prestai atenção, vós, povos distantes. Yahweh me chamou pelo nome antes do nascimento, desde o ventre da minha mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Ele tornou minha boca como espada afiada; escondeu-me na sombra da Sua mão; Ele me fez como uma flecha polida, e, na Sua aljava, escondeu-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Ele me disse: \"Tu és Meu servo, Israel, por meio de quem Eu mostro Minha glória\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Mas eu respondi: \"Ainda que eu acredite que tenha trabalhado em vão, que tenha gastado inutilmente minha energia, contudo, minha justiça vem de Yahweh, e minha recompensa repousa com meu Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Agora, diz Yahweh, Aquele que me formou desde o nascimento para ser Seu servo, a fim de restaurar Jacó novamente para Si, para juntar Israel a Ele. Sou honrado aos olhos de Yahweh e o meu Deus Se tornou minha força.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Ele diz: \"É muito pouco para ti ser Meu servo para restabelecer as tribos de Jacó e restaurar os sobreviventes de Israel. Eu te tornarei luz aos gentios, para que sejas Minha salvação até os confins da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Isto é o que Yahweh diz, o Redentor de Israel, o seu Santo, àquele que é desprezado, odiado pelas nações e escravo dos governadores: \"Reis te verão e se levantarão, príncipes te contemplarão e te reverenciarão por causa de Yahweh, que é fiel, o Santo de Israel, que te escolheu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Isto é o que Yahweh diz: \"No momento em que Eu decidir te mostrar Meu favor, te responderei, e, no dia da salvação, te ajudarei; protegerei a ti e te farei mediador de uma aliança, para reconstruir a terra e transferir ao povo a herança desolada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Dirás aos prisioneiros: \'Saí\'; àqueles que estão nos calabouços: \'Mostrai-vos\'. Eles pastarão ao longo das estradas e todas as encostas descobertas serão suas pastagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Eles não sentirão fome ou sede; tampouco serão assolados pelo calor do sol, porque Quem deles tem compaixão os conduzirá; Ele os guiará para as fontes de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'E transformarei num caminho plano todas as Minhas montanhas; Eu nivelarei Minhas estradas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Vê, estes virão de uma terra distante; alguns virão do norte e do oeste, enquanto outros virão da terra de Sinim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Louvai, céus, e regozija-te, terra; cantai, ó montanhas! Porque Yahweh consola o Seu povo e terá compaixão dos Seus aflitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Porém, Sião disse: \"Yahweh me abandonou e o Senhor Se esqueceu de mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Por acaso, pode uma mulher esquecer-se de seu bebê, que ainda é amamentado, de forma que ela não tenha compaixão do filho a quem deu à luz? Mas, mesmo que ela se esqueça, Eu jamais Me esquecerei de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Escrevi o vosso nome nas palmas das Minhas mãos e vossos muros estão continuamente diante de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Vossos filhos virão depressa, enquanto aqueles que vos destruíram estão indo embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Olhai ao redor e vede, todos eles estão se ajuntando e vindo até vós. Tão certo como Eu vivo — isto é o que Yahweh declara — vós, certamente, os usareis como joias e, como uma noiva, vos adornareis com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Embora tu foste um deserto desolado, uma terra em ruínas, agora, serás demasiadamente pequena para os habitantes, e os que te devoraram estarão longe de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Os filhos que nasceram de ti, durante o teu tempo de lamento, dirão aos teus ouvidos: \'Este lugar é muito apertado para nós; dá-nos um espaço maior para morar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Então, vós fareis esta pergunta: \"Quem deu à luz estes filhos para mim? Era estéril e desolada, exilada e abandonada. Quem criou estes filhos? Olhai, fui deixada sozinha; de onde vieram estes?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Eis o que diz Yahweh: \"Vede, erguerei Minha mão às nações; levantarei Minha bandeira de alerta aos povos. Eles trarão vossos filhos em seus braços e carregarão vossas filhas em seus ombros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Reis serão vossos pais adotivos e as rainhas deles serão vossas amas; eles vos reverenciarão com o rosto no chão e lamberão a poeira dos vossos pés; e vós sabereis que Eu sou Yahweh; os que esperam por Mim não serão envergonhados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Podem os despojos serem subtraídos do guerreiro, ou os cativos serem libertos de um tirano?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Mas isto é o que diz Yahweh: \"Sim, os cativos serão tomados do guerreiro e os despojos serão resgatados, porque estarei em oposição a vossos adversários e salvarei vossos filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Alimentarei vossos opressores com sua própria carne; eles se embriagarão com o próprio sangue, como se fosse vinho. E todos saberão que Eu, Yahweh, sou vosso Salvador e Redentor, o Todo-Poderoso de Jacó\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Isto é o que Yahweh diz: \"Onde está o certificado de divórcio, com que Me divorciei de vossa mãe? Ou para qual dos Meus credores Eu vos vendi? Vede, vós fostes vendidos por causa dos vossos pecados e, por causa da vossa rebeldia, vossa mãe foi mandada embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Por que ninguém estava lá quando Eu cheguei? Por que ninguém respondeu quando Eu chamei? Era Minha mão muito curta para vos redimir? Não havia poder em Mim para vos resgatar? Vede, na Minha repreensão, Eu sequei o mar; Eu transformo os rios em um deserto; os peixes morrem por falta de água e apodrecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Eu visto os céus com escuridão; Eu os cubro com pano de saco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'O Senhor Yahweh Me deu a língua como a de um daqueles que são ensinados, de modo que Eu falo palavras de conforto para os cansados. Ele Me desperta manhã após manhã, Ele desperta Meus ouvidos para ouvir como aqueles que são ensinados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'O Senhor Yahweh abriu Meus ouvidos e Eu não fui rebelde, nem Me desviei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Eu dei Minhas costas para aqueles que Me feriram e Meu rosto para aqueles que arrancaram Minha barba. Eu não escondi Minha face dos insultos e dos cuspes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Pois o Senhor Yahweh Me ajudará. Portanto, não serei desonrado; por isso, pus Minha face como uma rocha, pois sei que não serei envergonhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Aquele que Me justificará está por perto. Quem Me resistirá? Levantemos e confrontemos uns aos outros. Quem é Meu acusador? Que ele se aproxime de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Vede, o Senhor Yahweh Me ajudará. Quem Me declarará culpado? Vede, todos se desgastarão como uma roupa; a traça os comerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Quem dentre vós teme a Yahweh? Quem obedece à voz do Seu servo? Quem dentre vós anda na escuridão e não tem luz? Ele deve confiar no nome de Yahweh e confiar no Seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Vede, todos vós que acendeis fogo, que vos equipais com tochas, andai na luz do vosso fogo e nas chamas que acendestes. Isto é o que vós recebereis de Mim: vós deitareis em um lugar de tormento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Ouvi-me, vós que procurais a retidão, vós que buscais Yahweh. Olhai para a rocha da qual fostes formados, para a pedreira de onde fostes extraídos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Olhai para Abraão, vosso pai, e para Sara, que vos deu à luz. Quando Eu o chamei, ele era um indivíduo solitário. Eu o abençoei e o fiz numeroso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Sim, Yahweh consolará Sião; Ele confortará todos os seus lugares assolados; fará seu deserto como o Éden; sua região seca, ao lado do vale do rio Jordão, como o jardim de Yahweh. Alegria e contentamento serão encontrados nela, ações de graças e som de cânticos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, '\"Atentai a Mim, povo Meu; ouvi-Me, povo Meu! Pois emitirei um decreto e farei Minha justiça como luz para as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Minha justiça está perto, Minha salvação chegará, Meu braço julgará as nações; as terras costeiras esperarão, ansiosamente, por Mim e pelo Meu braço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Elevai os vossos olhos para o céu e olhai para a terra embaixo. Os céus sumirão como a fumaça, a terra se desgastará como uma roupa, e seus habitantes morrerão como as moscas. Mas Minha salvação continuará para sempre e Minha justiça nunca falhará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Ouvi-Me, vós que sabeis o que é correto, vós que tendes a Minha lei no coração. Não temais os insultos dos homens, nem desanimeis com a ofensa deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Porque a traça os devorará como a uma roupa e o verme os comerá como a lã; mas a Minha justiça será para sempre e Minha salvação, para todas as gerações\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Desperta, desperta, veste-Te de força, braço de Yahweh! Desperta como nos dias antigos, como nas gerações passadas. Não foste Tu que despedaçaste Raabe, o monstro do mar, que perfuraste o dragão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Não foste Tu que fizeste secar o mar, as águas do grande abismo, que fizeste das profundezas do mar um caminho para os redimidos atravessarem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Os remidos de Yahweh retornarão a Sião e entrarão nela com gritos de júbilo e a alegria eterna coroará suas cabeças; o regozijo e a alegria os alcançarão, a tristeza e o luto fugirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, '\"Eu, Eu Sou Aquele que te conforta. Por que tens medo de um homem que morrerá, de filhos de homens, que são como a relva?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Por que te esqueceste de Yahweh, teu Criador, que estendeu os céus e lançou as fundações da terra? Todo dia, tu estás em constante pavor por causa da fúria ardente do opressor quando ele decide te destruir. Onde está a fúria do opressor?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Quanto ao que está cativo, Yahweh se apressará para libertá-lo. Ele não morrerá e nem descerá à cova, nem lhe faltará o pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Pois Eu Sou Yahweh, teu Deus, que agita o mar de modo que suas ondas rujam — Yahweh dos Exércitos é o Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Eu coloquei as Minhas palavras em tua boca e te cobri com a sombra da Minha mão; Eu estabeleci os céus, coloquei os alicerces da terra e disse a Sião: \'Tu és Meu povo\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Desperta, desperta! Levanta-te, Jerusalém, que bebeste das mãos de Yahweh, da taça da Sua ira; que bebeste do cálice, até o resto da taça da embriaguez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Não há, dentre os filhos que ela gerou, nenhum que a guie. De todos os filhos que ela criou, nenhum a toma pela mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Estes dois problemas te aconteceram; quem lamentará contigo? A desolação e a destruição, a fome e a espada. Quem te consolará?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Teus filhos desmaiaram; eles se deitam em cada esquina, como um antílope em uma rede; eles estão cheios da ira de Yahweh, da repreensão do teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Agora, porém, ouve isto, tu que estás aflita e embriagada, mas não com vinho:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Assim diz o teu Senhor Yahweh, teu Deus, que defende a causa de Seu povo: \"Vê, Eu tiro a taça da vertigem da tua mão — o cálice, que é a taça da Minha ira — para que não bebas dela novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Eu a colocarei nas mãos de teus atormentadores, aqueles que te disseram: \'Deita-te, para que caminhemos sobre ti\'; os que fizeram de tuas costas como o chão e como rua, para que andassem por cima\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Desperta, desperta! Reveste-te de força, Sião; põe teus belos vestidos, Jerusalém, cidade santa; porque nunca mais os impuros e os incircuncisos entrarão por teus portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Sacode de ti mesma a poeira, levanta-te e assenta-te, Jerusalém; arranca a corrente do teu pescoço, ó cativa filha de Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Porque isto é o que Yahweh diz: \"Tu foste vendida por nada e serás redimida sem dinheiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Isto é o que diz o Senhor Yahweh: \"No início, Meu povo desceu para viver temporariamente no Egito; recentemente, a Assíria os tem oprimido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Agora, o que Eu tenho aqui — esta é a declaração de Yahweh — visto que o Meu povo foi levado embora por nada? Aqueles que os dominam zombam — esta é a declaração de Yahweh — e o Meu Nome é blasfemado continuamente, o dia todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Entretanto, Meu povo conhecerá o Meu nome; eles saberão, naquele dia, que sou Eu quem fala: \'Sim, sou Eu\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Como são bonitos, sobre os montes, os pés do mensageiro que traz boas novas, que anuncia a paz, que testemunha boas novas, que anuncia a salvação, que diz a Sião: \"Teu Deus reina!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Ouve! Teus sentinelas levantam a voz e, juntos, gritam de alegria; pois eles verão, com os próprios olhos, o retorno de Yahweh a Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Rompei em júbilo, cantando juntas, vós, ruínas de Jerusalém; porque Yahweh confortou o Seu povo; Ele redimiu Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Yahweh despiu Seu santo braço à vista de todas as nações; toda a terra verá a salvação do nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Afastai-vos, afastai-vos! Saí daí; não toqueis em nada impuro; saí do meio dela! Purificai-vos, vós que carregais os vasos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Não partireis correndo, nem saireis em pânico, porque Yahweh irá adiante de vós; o Deus de Israel será a vossa retaguarda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Vê! Meu Servo agirá sabiamente; Ele será engrandecido e elevado; Ele será exaltado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Assim como muitos ficaram horrorizados diante Dele, pois Sua aparência estava tão desfigurada que não parecia de um homem (Seu aspecto não mais parecia humano),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'assim Meu servo causará admiração a muitas nações; reis fecharão suas bocas por causa Dele, porque eles verão o que não lhes havia sido contado, e entenderão aquilo que nunca tinham ouvido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Quem acreditou em nossa mensagem? E a quem foi revelado o braço de Yahweh?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Pois Ele cresceu diante de Yahweh como um rebento e como o germinar de um broto na terra seca. Ele não tinha nenhuma aparência notável nem esplendor; quando O vimos, não havia beleza Nele que pudesse nos atrair.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Ele foi desprezado e rejeitado pelas pessoas, um homem de sofrimento, familiarizado com a dor. Como um de quem os homens escondem o rosto, Ele foi desprezado e O consideramos insignificante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Mas Ele, certamente, suportou nossas doenças e carregou nosso sofrimento; ainda que achássemos que Ele estava sendo punido por Yahweh, atingido e afligido por Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Ele foi perfurado por causa de nossa rebeldia; Ele foi esmagado por causa de nossos pecados. A punição que nos traz a paz estava sobre Ele e, por Suas feridas, fomos sarados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Nós todos, como ovelhas, havíamos nos desviado; cada um em direção a seu próprio caminho; e Yahweh colocou sobre Ele a iniquidade de todos nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Ele foi oprimido; contudo, quando foi humilhado, não abriu a Sua boca. Como um cordeiro que é conduzido para o abate, e como ovelhas que, diante de seus tosquiadores, ficam em silêncio, Ele não abriu a Sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Por opressão e julgamento, Ele foi condenado. Quem daquela geração pensava mais sobre Ele? Ele foi cortado da terra dos viventes; por causa das ofensas do meu povo, a punição foi colocada sobre Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Eles colocaram Sua sepultura com os criminosos, e com o homem rico em Sua morte, embora Ele não tivesse cometido nenhuma violência, nem houvesse engano em Sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'No entanto, foi a vontade de Yahweh esmagá-Lo e fazê-Lo adoecer. Quando Ele fizer de Sua vida uma oferta pelo pecado, Ele verá Sua descendência, prolongará Seus dias e o propósito de Yahweh se cumprirá através Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Depois do sofrimento de Sua vida, verá o que Ele fez e ficará satisfeito com isso. Meu justo Servo justificará muitos e carregará suas iniquidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Portanto, darei Sua porção entre as multidões e Ele dividirá os despojos com muitos, porque Ele Se expôs à morte e foi contado com os transgressores. Ele carregou os pecados de muitos e intercedeu pelos transgressores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, '\"Canta, mulher estéril, tu que não deste à luz! Canta alegremente e clama, tu que nunca tiveste dores de parto. Porque os filhos da desamparada são mais do que os da mulher casada\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, '\"Alarga a tua tenda e abre livremente as suas cortinas; estica suas cordas e firma bem as suas estacas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Porque te espalharás para a direita e para a esquerda; teus descendentes conquistarão nações e reassentarão cidades desoladas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Não temas, pois não serás envergonhada, nem desanimes, pois não serás desonrada; tu esquecerás a vergonha da tua juventude e a desgraça do teu abandono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Pois o teu Criador é o teu marido; o Seu nome é Yahweh dos Exércitos. O Santo de Israel é o teu Redentor; Ele é chamado o Deus de toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Porque Yahweh te chamou de volta como se fosses uma esposa abandonada e aflita de espírito, como uma mulher jovem que se casou e foi rejeitada\", diz o teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, '\"Por um breve momento, Eu te abandonei, mas, com grande compaixão, Eu te trarei de volta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Num transbordar de ira, escondi Meu rosto de ti por um momento, mas, com eterno amor leal, terei misericórdia de ti\" — diz Yahweh, Aquele que te salva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, '\"Pois isto é para Mim como as águas de Noé; como jurei que as águas de Noé não mais inundariam a terra, assim também jurei que não mais me irarei contra ti ou te castigarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Ainda que as montanhas caiam e os montes sejam sacudidos, ainda assim, Meu amor inabalável não se afastará de ti, nem Minha aliança de paz será abalada\" — diz Yahweh, que tem misericórdia de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, '\"Ó, aflita, açoitada pela tempestade e desconsolada, vê! Eu assentarei tuas pedras com turquesas e edificarei teus alicerces com safiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Farei as tuas colunas de rubis, as tuas portas de pedras brilhantes e as tuas muralhas de pedras preciosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Todos os teus filhos serão ensinados por Yahweh; e a paz de teus filhos será grande.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Serás restabelecida em retidão; não mais experimentarás a perseguição; não temerás, pois nada amedrontador chegará a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Vê! Se alguém levantar contenda, não virá de Mim; qualquer que levantar contenda contra ti cairá em derrota.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Olha! Fui Eu Quem criou o ferreiro, que sopra as brasas e produz ferramentas para o seu trabalho, e fui Eu Quem criou o devastador, para destruir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Nenhuma arma forjada contra ti prosperará; e tu condenarás todos os que te acusarem. Esta é a herança dos servos de Yahweh e a sua defesa diante de Mim\" — declara Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, '\"Vinde, todos vós que estais com sede, vinde às águas! E vós que não tendes dinheiro, vinde, comprai e comei; sim, vinde e comprai vinho e leite, sem dinheiro e sem custo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Por que gastais dinheiro com aquilo que não é pão e trabalhais por aquilo que não satisfaz? Ouvi-Me, atentamente, comei o que é bom, desfrutai da fartura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Inclinai vossos ouvidos e vinde a Mim! Ouvi, para que possais viver! Eu farei uma aliança eterna convosco: Minha fidelidade prometida a Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Vede, Eu o pus como uma testemunha às nações, como um líder e comandante para os povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Vede, chamareis uma nação que não conheceis; e uma nação que não vos conhecia correrá para vós, por causa de Yahweh, vosso Deus, O Santo de Israel, que vos glorificou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Buscai a Yahweh enquanto Ele pode ser encontrado; invocai-O enquanto Ele está perto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Que o ímpio deixe seu caminho e o homem mau, os seus pensamentos. Que ele se volte para Yahweh, que Se compadecerá dele; o nosso Deus é Quem o perdoará abundantemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, '\"Pois os Meus pensamentos não são os vossos pensamentos, nem os vossos caminhos, Meus caminhos\" — diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, '\"Porque, assim como os céus são mais altos que a terra, os Meus caminhos são mais altos que os vossos caminhos e os Meus pensamentos são mais altos que os vossos pensamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Assim como a chuva e a neve caem do céu e não retornam para lá sem que reguem a terra, fazendo-a germinar e dar semente ao semeador e pão ao que come,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'assim também será a palavra que sair da Minha boca: não voltará a Mim sem efeito, mas cumprirá aquilo que desejo e terá êxito no propósito para o qual Eu a enviei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Saireis com alegria e sereis conduzidos pacificamente; montanhas e vales romperão em cânticos diante de vós e todas as árvores dos campos baterão palmas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'No lugar dos espinheiros, crescerão pastagens e, no lugar da urtiga, a murta crescerá; e serão, pelo nome de Yahweh, um sinal eterno que jamais será cortado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Porque assim diz Yahweh: \"Observai o que é reto, fazei o que é justo; porque a Minha salvação está perto e a Minha justiça está prestes a ser revelada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Abençoado é o homem que assim o faz e persevera firmemente. Ele guarda o sábado, sem o profanar e guarda a sua mão de fazer o mal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Nenhum estrangeiro que se uniu a Yahweh diga: \"Yahweh, certamente, me excluirá do Seu povo\". Que o eunuco não fale: \"Vê, eu sou uma árvore seca.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Porque assim diz Yahweh: \"Aos eunucos que guardam os Meus sábados e escolhem o que Me agrada, e guardam a Minha aliança,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Eu construirei para eles, na Minha casa e dentro dos Meus muros, um monumento que é melhor do que ter filhos e filhas; Eu lhes darei um nome eterno que nunca lhes será retirado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Também os estrangeiros que se aliam a Yahweh para servi-Lo e que amam o nome de Yahweh para adorá-Lo, todos os que observam o sábado e não o violam, e guardam a Minha aliança,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Eu os trarei ao Meu santo monte e os alegrarei na Minha casa de oração; seus holocaustos e sacrifícios serão aceitos no Meu altar, porque a Minha casa será chamada casa de oração para todas as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Esta é a declaração do Senhor Yahweh, que ajunta os rejeitados de Israel — Eu ainda trarei outros para acrescentar a eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Todos vós, animais do campo, todos os animais da floresta, vinde e devorai!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Todos os vossos guardas são cegos; eles não entendem; são como cães mudos que não conseguem latir; deitando-se, sonham, e amam dormir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Eles são cães gulosos que nunca estão satisfeitos; são pastores sem discernimento; todos se desviaram para seu próprio caminho, cada um busca seu próprio interesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, '\"Vinde\", eles dizem: \"Tomemos vinho e bebida forte; amanhã será como hoje, um dia sem igual”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'O justo perece, mas ninguém se importa; as pessoas que são fiéis a Deus são recolhidas e ninguém entende que os justos são retirados da presença do mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Os justos entram na paz; descansam em suas camas aqueles que andam em retidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Mas vinde aqui, filhos das feiticeiras, filhos da adúltera e da mulher que se prostituiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'De quem estais zombando? Para quem estais abrindo vossa boca e mostrando a língua? Não sois vós filhos da rebelião e filhos do engano?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Vós ardeis de desejo, juntos, sob os carvalhos, embaixo de toda árvore verde; vós que matais vossos filhos nos vales secos, debaixo das fendas das rochas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Entre as pedras lisas do vale do rio está a tua porção. Verdadeiramente, estas são a tua recompensa. Derramaste tua bebida de sacríficio para elas e levantaste uma oferta de cereal. Teria Eu prazer nestas coisas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Preparaste a tua cama no alto da montanha, e foste lá para oferecer sacrifícios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Colocaste teus símbolos atrás da porta e dos umbrais; tu Me abandonaste; ficaste nu, subiste e alargaste a tua cama. Fizeste uma aliança com eles; amaste a cama deles e viste a sua nudez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Foste a Moloque, com óleo, e multiplicaste perfumes. Mandaste teus embaixadores para longe; desceste até o Sheol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Tu te cansaste das tuas muitas jornadas, mas nunca disseste: \"Não há esperança\". Encontraste vida em tuas mãos, por isso não enfraqueceste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, '\"Com quem estás preocupado? De quem tens tanto medo para que ajas tão falsamente, a ponto de não te lembrares de Mim ou pensares a Meu respeito? Porque fiquei em silêncio por tanto tempo, não Me temes mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Eu proclamarei a tua justiça, contarei os teus feitos, mas eles não te ajudarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Quando tu clamares, que teus muitos ídolos te salvem. O vento os carregará e um sopro os levará para longe. Mas aquele que se refugia em Mim herdará a terra e possuírá o Meu santo monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Ele dirá: \'Aplanai, aplanai! Preparai o caminho! Tirai todos os tropeços do caminho do Meu povo!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Pois assim diz Aquele que é alto e sublime, que habita eternamente, cujo nome é Santo: \"Eu habito num alto e santo lugar e também com o contrito e humilde de espírito, para restaurar o espírito dos humildes e reanimar o coração dos contritos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Porque não acusarei para sempre, nem ficarei irado o tempo todo, para que o espírito do homem, a vida que Eu criei, não desfaleça diante de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Por causa do pecado do seu ganho injusto, Eu estive irado e o castiguei; escondi a Minha face e Me indignei, mas ele se rebelou e seguiu o caminho do seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Eu tenho visto os seus caminhos, mas o curarei. Eu o guiarei e o confortarei, e consolarei todos os que lamentaram por ele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'trazendo alegria aos lábios. Paz, paz para os de longe e para os de perto — diz Yahweh — Eu os curarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Mas os corruptos são como o mar agitado, que não se aquieta, e suas águas lançam lodo e lama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Não há paz para o ímpio — diz Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, '\"Clama bem alto, não te detenhas! Levanta a tua voz como uma trombeta! Declara ao Meu povo a sua transgressão e à casa de Jacó, os seus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'No entanto, eles ainda Me buscam diariamente e se deleitam em conhecer os Meus caminhos, como uma nação que pratica a justiça e não abandona a Lei do seu Deus. Eles Me pedem por julgamentos retos e têm prazer em se aproximar de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'E dizem: \'Por que temos jejuado, mas Tu não vês? Por que temos nos humilhado, mas não percebes?\'. Vede, no dia do vosso jejum, buscais o vosso próprio prazer e oprimis todos os vossos trabalhadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Vede, vós jejuais para contender, brigar e ferir com punho de iniquidade; jejuando como fazes hoje, não tereis a vossa voz ouvida lá no alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'É este o jejum que, de fato, Eu escolhi? Um dia para o homem humilhar a si mesmo, para curvar sua cabeça como um junco e deitar em panos de saco e cinzas? Vós, realmente, chamais isso de jejum, de um dia que agrada a Yahweh?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Não é este o jejum que Eu escolhi, que quebres as cadeias da impiedade, desfaças as cordas da opressão, libertes os oprimidos e despedaces todo o jugo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Não é para que dividas o teu pão com o faminto e tragas o pobre e o desabrigado para a tua casa?\" Não é que quando vires alguém nu, vista-o e não te recuses socorrer o próximo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Então, a tua luz surgirá como o nascer do sol e a tua cura virá depressa; a tua retidão virá adiante de ti, e a glória de Yahweh será a tua retaguarda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Então, tu invocarás e Yahweh te responderá; clamarás e Ele dirá: \"Estou aqui\". Se arrancares do teu meio o jugo, o dedo acusador e a fala maliciosa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'se proveres para o faminto e satisfizeres a alma aflita, então, a tua luz brilhará nas trevas e serás como o meio dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Então, Yahweh te guiará continuamente e te satisfará numa terra seca, fortalecerá os teus ossos. Tu serás como um jardim regado e como um manancial, cujas águas jamais faltam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Alguns reconstruirão as antigas ruínas, tu restaurarás os fundamentos de muitas gerações; serás chamado \"o reparador de muro\", \"o restaurador de ruas para habitação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, '\"Se impedires os teus pés de profanarem o sábado, se não fizeres o que te agrada no Meu santo dia, se tu chamares o sábado de deleite e as coisas de Yahweh de santas e honradas, se honrares o sábado, deixando os teus próprios negócios, não buscando o teu próprio prazer e não falando palavras vãs,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'então, terás satisfação em Yahweh; Eu te farei cavalgar sobre os mais altos lugares da terra, e te sustentarei com a herança do teu pai Jacó — pois a boca de Yahweh falou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Eis que a mão de Yahweh não está tão encolhida, para que não possa salvar, nem tão surdo o Seu ouvido, para que não consiga ouvir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Contudo, vossas maldades fazem separação entre vós e vosso Deus; por causa dos vossos pecados, Ele escondeu de vós o Seu rosto para não vos ouvir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Porque as vossas mãos estão contaminadas com sangue e vossos dedos, com pecado. Vossos lábios falam mentiras e vossas línguas falam o que é mau.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Não há quem clame com justiça e ninguém apela por seus direitos com verdade; eles confiam em palavras vãs e contam mentiras; concebem maldades e dão à luz o pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Eles chocam ovos de cobras venenosas e tecem teias de aranha; os que comem dos seus ovos morrerão; e, se um ovo é esmagado, sai dele uma cobra venenosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'As suas teias não podem ser usadas como roupa, eles não poderão se vestir com o próprio trabalho; suas obras são pecaminosas e atos de violência estão em suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Seus pés correm para o mal e se apressam em derramar sangue inocente. Seus pensamentos são pensamentos de pecado; violência e destruição são os seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Eles não conhecem o caminho da paz e não há justiça em seus passos. Fizeram para si estradas tortuosas; quem anda por elas não sabe o que é paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Por isso, a justiça está longe de nós, e a retidão não nos alcança. Esperamos pela luz, eis que só há trevas; procuramos pelo resplendor, mas andamos na escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Nós tocamos as paredes como os cegos, como aqueles que não conseguem ver. Nós tropeçamos ao meio-dia como se fosse noite; entre os fortes, nós somos como os mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Rugimos como ursos e gememos como pombos; esperamos por justiça, mas não há nenhuma; por salvação, mas ela está longe de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Pois as nossas transgressões se multiplicam diante de Ti e os nossos pecados dão testemunho contra nós; pois as nossas transgressões estão conosco e conhecemos os nossos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Transgredimos negando a Yahweh e nos desviamos de seguir o nosso Deus. Pregamos a opressão e a rebelião, dando à luz a reclamação do coração e palavras mentirosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'A justiça retrocedeu e a integridade está longe; pois a verdade tropeça em praças públicas e a retidão não pode vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'A verdade desfalece, e aquele que vira as costas para a maldade torna-se uma vítima. Yahweh viu isso e ficou insatisfeito, pois não havia justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Ele viu que não havia nenhum homem e ficou surpreso por não haver ninguém que intercedesse. Por isso, o Seu próprio braço trouxe a salvação, e a Sua retidão O sustentou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Vestiu-Se de justiça como de uma couraça e pôs na cabeça o capacete da salvação; vestiu-Se com roupas de vingança e Se cobriu de zelo, como de um manto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Ele os retribuiu segundo as suas obras; ira aos Seus adversários e vingança aos Seus inimigos; às ilhas, punição como recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Então temerão o nome de Yahweh desde o oeste, e a Sua glória, desde o nascer do sol; porque Ele virá como uma correnteza impetuosa, dirigida pelo Espírito de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, '\"Um Redentor virá até Sião e virá para aqueles que se desviam dos atos rebeldes de Jacó\". Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, '\"E, quanto a Mim, este é a Minha aliança com eles\" — diz Yahweh: \"O Meu Espírito está sobre ti e as Minhas palavras, que coloquei em tua boca, não se apartarão dela, nem da boca de teus filhos, nem da boca dos filhos dos teus filhos, desde agora e para sempre\" — diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Levanta-te, resplandece! Porque chegou a tua luz e a glória de Yahweh nasce sobre ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Embora a escuridão cubra a terra e as densas trevas envolvam os povos, ainda assim, Yahweh resplandecerá sobre ti e a Sua glória será vista em ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'As nações caminharão para a tua luz e os reis, para o resplendor da tua aurora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Olha ao redor e vê. Todos eles se reúnem e vêm a ti. Teus filhos virão de longe e tuas filhas serão carregadas nos braços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Então, verás e ficarás radiante; o teu coração regozijará e transbordará de alegria, porque as riquezas do mar afluirão a ti e os tesouros das nações a ti virão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Caravanas de camelos te inundarão, os camelinhos de Midiã e Efá. Todos virão de Sabá, trazendo ouro e incenso, e cantarão louvores a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Todos os rebanhos de Quedar serão trazidos para junto de ti, os carneiros de Nebaiote te servirão. Serão ofertas agradáveis sobre o Meu altar, e Eu cobrirei de glória a Minha casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Quem são esses que voam como nuvens, como pombas aos seus pombais?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'As terras costeiras esperam em Mim; os navios de Társis vêm à frente para trazer os teus filhos de longe e, com eles, sua prata e seu ouro, para o nome de Yahweh, teu Deus, para o Santo de Israel, porque Ele te glorificou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Filhos de estrangeiros reconstruirão os teus muros, e os seus reis te servirão; pois, se te castiguei em Minha ira, agora, na Minha graça, Eu terei misericórdia de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Tuas portas permanecerão abertas continuamente; nem de dia nem de noite serão fechadas, para que a riqueza das nações seja trazida a ti, sendo conduzida por seus reis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'De fato, as nações e os reinos que não te servirem perecerão; essas nações serão totalmente destruídas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'A glória do Líbano virá a ti; o cipreste, o pinheiro e o abeto virão juntos para enfeitar o Meu santuário; e farei glorioso o lugar onde pisam Meus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Os filhos daqueles que te oprimiram virão e se curvarão diante de ti; todos os que te desprezavam se curvarão aos teus pés; eles te chamarão de Cidade de Yahweh, a Sião do Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Ao invés de permanecer abandonada e odiada, sem ninguém passando por ti, Eu te farei eterno motivo de orgulho e alegria, de geração em geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Tu beberás o leite das nações e te alimentarás do peito dos reis. Tu saberás que Eu, Yahweh, Sou teu Salvador e teu Redentor, o Poderoso de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Em vez de bronze, trarei ouro, em vez de ferro, trarei prata; em vez de madeira, bronze e, em vez de pedras, ferro; farei pacíficos os teus oficiais e justos os teus governantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Não mais se ouvirá sobre a violência em tua terra, nem sobre devastação ou destruição dentro de tuas fronteiras; mas aos teus muros chamarás Salvação, e às tuas portas, Louvor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'O sol não mais te servirá para luz durante o dia, nem o brilho da lua te iluminará à noite, mas Yahweh será a tua luz perpétua, o teu Deus será a tua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Teu sol não mais voltará a se pôr, nem a tua lua se retirará e desaparecerá, porque Yahweh será a tua luz para sempre, e os teus dias de luto cessarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Todo o teu povo será justo; eles tomarão a posse da terra para sempre; serão o ramo da Minha plantação, obras das Minhas mãos, para que Eu seja glorificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'O menor virá a ser mil, e o mínimo, uma nação forte. Eu, Yahweh, farei estas coisas quando chegar a hora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'O Espírito do Senhor Yahweh está sobre Mim, porque Yahweh Me ungiu para pregar as boas novas aos oprimidos; Ele Me enviou para curar os de coração quebrantado, para proclamar liberdade aos cativos e para abrir as cadeias dos que estão presos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Ele Me enviou para proclamar o ano aceitável de Yahweh, o dia da vingança do nosso Deus, e para consolar todos os que choram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Ele Me enviou para dar a todos os que choram, em Sião, uma coroa ao invés de cinzas, óleo de alegria ao invés de luto, veste de louvor em lugar de um espírito angustiado; a fim de que se chamem carvalhos de justiça, plantados por Yahweh, para a Sua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Eles reconstruirão as antigas ruínas, restaurarão os lugares antes destruídos e reedificarão as cidades assoladas — desolações de muitas gerações anteriores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Os estrangeiros ficarão de pé e alimentarão os vossos rebanhos, e os filhos dos estrangeiros trabalharão nos vossos campos e vinhedos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Vós sereis chamados sacerdotes de Yahweh e vos chamarão como servos do nosso Deus. Comereis a fartura das nações e vos gloriareis nas riquezas delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Ao invés de vergonha, tereis dupla honra; em lugar de desonra, exultareis em vossa herança; por isso, na vossa terra possuireis o dobro, e tereis eterna alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Porque Eu, Yahweh, amo a justiça, odeio o roubo e toda a maldade. Eu, fielmente, lhes retribuirei e farei com eles uma aliança eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'A sua posteridade será conhecida entre as nações e os seus descendentes, entre os povos; todos quantos os virem os reconhecerão como o povo que Yahweh abençoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Eu me regozijarei muito em Yahweh; eu me alegrarei muito em meu Deus, porque Ele me vestiu com vestes de salvação e me envolveu com o manto de justiça, como um noivo que se adorna com um turbante e como uma noiva que se adorna com as suas joias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Porque assim como a terra produz as plantas que brotam e como o jardim faz crescer o seu plantio, assim o Senhor Yahweh fará brotar a justiça e o louvor perante todas as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Por amor a Sião, não me silenciarei; por amor a Jerusalém, não descansarei até que a sua justiça resplandeça como o nascer do sol, e a sua salvação queime como uma tocha acesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'As nações verão a tua justiça e todos os reis, a tua glória. Tu serás chamada por um novo nome, que Yahweh escolherá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Tu também serás como uma bela coroa real na mão de Yahweh, como um turbante de realeza na mão do teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'De ti, nunca mais será dito \"Abandonada\"; de tua terra, nunca mais será dito \"Desolada\". Certamente, tu serás chamada \"Meu prazer está nela\", e a tua terra se chamará \"Casada\", pois Yahweh Se alegra em ti e a tua terra se casará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Verdadeiramente, como um homem jovem que se casa com uma mulher jovem, assim teus filhos se casarão contigo; como um noivo se alegra com sua noiva, teu Deus Se alegrará contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Tenho colocado vigias nas tuas muralhas, ó Jerusalém; eles não estão em silêncio nem de dia, nem de noite. Vós, que continuamente vos lembrais de Yahweh, não pareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Não permitais que Ele descanse até que restabeleça Jerusalém e faça dela um louvor na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Yahweh declarou pela Sua mão direita e pelo Seu braço forte: \"Certamente, não darei mais os teus grãos como comida aos teus inimigos. Estrangeiros não mais beberão teu vinho novo, para o qual tens trabalhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Pois aqueles que colherem grãos, deles comerão e louvarão a Yahweh, e aqueles que colherem uvas, delas beberão vinho nos pátios do Meu santuário\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Passai, passai pelos portões! Preparai o caminho para o povo! Construí a estrada, construí-a! Ajuntai as pedras! Levantai uma bandeira como sinal para as nações!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Vede, Yahweh anuncia aos confins da terra: \"Dizei à filha de Sião: Vê, teu Salvador está vindo! Vê, tua recompensa vem com Ele e tua recompensa está indo à frente Dele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Eles vos chamarão de \"Povo santo, os redimidos de Yahweh\". E tu, Sião, serás chamada de \"Procurada, uma cidade que não está abandonada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Quem é este que vem de Edom, vestido em vivas cores, vindo de Bozra? Quem é Ele que, com majestosas roupas reais, marcha com absoluta confiança por causa da Sua grande força? “Este sou Eu, falando de justiça, e poderosamente capaz de salvar”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Por que Tuas roupas estão vermelhas, como se Tu tivesses pisado uvas em um lagar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, '“Eu pisei no lagar sozinho; das nações, nenhum homem se juntou a Mim. Eu pisei as uvas em Minha ira e as esmaguei no Meu furor. Seu sangue respingou em Minha roupa e a manchou completamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Pois Eu olhei ansioso para o dia da vingança e vi que o ano para a Minha redenção havia chegado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Procurei, mas não havia ninguém para Me ajudar. Fiquei surpreso por não ter encontrado alguém para ajudar, mas Meu próprio braço Me trouxe a vitória, e Minha forte ira Me conduziu adiante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Esmaguei os povos na Minha ira e os embriaguei no Meu furor, derramando seu sangue pela terra”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Celebrarei o glorioso amor fiel de Yahweh e as Suas obras dignas. Contarei tudo o que Yahweh fez por nós e sobre Sua grande bondade para com a casa de Israel. Mostrou-nos compaixão por causa da Sua misericórdia, de Seu amor fiel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Pois Ele disse: \"Com certeza, eles são Meu povo, filhos que não são infiéis\". Ele Se tornou o Salvador deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Até o fim de todo o sofrimento deles, Ele sofreu também, e o anjo de Sua presença os salvou. Em Seu amor e misericórdia, Ele os salvou, os levantou e os carregou desde os tempos antigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Mas eles se rebelaram e ofenderam Seu Santo Espírito. Assim, Ele Se tornou inimigo e lutou contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Seu povo meditou sobre os antigos tempos de Moisés. Disseram: \"Onde está Deus, O qual lhes tirou do mar com os pastores e seus rebanhos? Onde está Deus, O qual colocou Seu Santo Espírito sobre eles?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Onde está Deus, O qual fez Seu glorioso poder ir com a mão direita de Moisés e dividiu a água diante deles, para fazer um nome perpétuo para Ele mesmo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Onde está Deus, O qual lhes guiou até o fim da água profunda? Como um cavalo correndo em uma superfície plana, eles não caíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Como o gado que desce pelo vale, o Espírito de Yahweh lhes deu descanso. Assim, Tu guiaste Teu povo para fazer a Ti mesmo um nome de louvor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Do céu, olha para baixo e observa de Tua santa e gloriosa habitação. Onde estão o Teu zelo e Teus atos poderosos? Tuas ações piedosas e compassivas foram guardadas de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Pois Tu és nosso Pai, embora Abraão não nos conheça e Israel nos ignore, Tu, Yahweh, és o nosso Pai. “Nosso Redentor”, este tem sido o Teu Nome desde os tempos antigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Yahweh, por que Tu nos fazes vagar longe dos Teus caminhos e endureces nossos corações, para que nós não obedeçamos a Ti? Volta, pelo bem dos Teus servos, pelas tribos da Tua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Teu povo possuiu o Teu santo lugar por um curto tempo. Então, nossos inimigos pisaram nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Nós nos tornamos como aqueles sobre quem Tu nunca governaste, como aqueles que nunca foram chamados pelo Teu Nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Oh, se tivesses aberto os céus e descido! As montanhas se abalariam com Tua presença,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'assim como o fogo acende os gravetos e faz ferver a água. Oh, que Teu nome seja conhecido por Teus adversários, que as nações tremam em Tua presença!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Anteriormente, quando fizeste coisas admiráveis que não esperávamos, desceste, e as montanhas tremeram em Tua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Desde os tempos antigos, ninguém ouviu ou percebeu, ninguém viu outro Deus além de Ti, que trabalha para os que Nele esperam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Tu vens para ajudar aqueles que se alegram em fazer o que é correto, aqueles que Lhe obedecem e se dedicam aos Teus caminhos. Tu te iraste quando pecamos. Em Teus caminhos nós sempre seremos resgatados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Nós somos todos como imundos e toda nossa justiça é como um trapo de imundície. Todos nós murchamos como folhas, e nossas iniquidades, como o vento, transportam-nos para longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Não há ninguém que invoque o Teu nome, que faça um esforço para apegar-se a Ti, pois escondeste Tua face de nós e nos entregaste aos nossos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Ainda assim, Yahweh, Tu és o nosso Pai. Somos barro e Tu és nosso oleiro; e todos nós somos obras de Tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Não fiques demasiadamente irado, Yahweh, nem te lembres sempre dos nossos pecados. Por favor, olha para nós, Teu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Tua santa cidade tornou-se um deserto; Sião tornou-se um deserto, sim, Jerusalém é uma desolação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Nosso santo e lindo templo, onde nossos pais oravam a Ti, foi destruído pelo fogo, e tudo que era tão precioso está em ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Como podes ainda Te conter, Yahweh? Como podes permanecer em silêncio e continuar a nos humilhar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, '\"Eu estava pronto a ser procurado por aqueles que não perguntavam por Mim, a ser achado por aqueles que não Me procuravam. Eu disse: \'Eu estou aqui! Eu estou aqui!\' para uma nação que não chamava pelo Meu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Estendi as Minhas mãos o dia todo a um povo teimoso, que anda em um caminho que não é bom, que tem andado segundo os seus próprios pensamentos e planos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Eles são um povo que Me ofende continuamente, oferecendo sacrifícios em jardins e queimando incenso sobre tijolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Eles se sentam entre as sepulturas e passam a noite toda comendo carne de porco com o caldo de carne impura em seus pratos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Eles dizem: \'Afasta-Te, não chega perto de mim, porque sou mais santo do que Tu\'. Essas coisas são como fumaça no Meu nariz, um fogo que arde durante todo o dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Eis que está escrito diante de Mim: Eu não me calarei, vou pagar-lhes de volta; Eu lhes darei a recompensa');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'por seus pecados e pelos pecados de seus pais\", diz Yahweh. \"Eu vou pagar-lhes por queimarem incenso nos montes e zombarem de Mim nas colinas. Portanto, retribuirei completamente as suas obras passadas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Assim diz Yahweh: \"Como quando o suco é encontrado em um cacho de uvas e se diz: \'Não o danifiques, pois há algo bom nele\', isto é o que Eu farei por amor de Meus servos: não destruirei todos eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Trarei descendentes de Jacó e de Judá, que possuirão as Minhas montanhas. Meus escolhidos herdarão a terra e os Meus servos viverão lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Sarom se tornará um pasto para as ovelhas e o vale de Acor, um lugar de descanso para os rebanhos, para o Meu povo que Me procura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Mas vós que abandonais Yahweh, que vos esqueceis do Meu santo monte, que preparais uma mesa para a deusa Sorte e encheis copos de vinho misturado para o deus chamado Destino,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'vou destinar-vos para a espada. E todos vós se curvarão ao matadouro porque, quando chamei, vós não respondestes; quando falei, não Me ouvistes; em vez disso, fizestes o que era mau perante Mim e escolhestes fazer aquilo em que Eu não tenho prazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Assim diz o Senhor Yahweh: \"Eis que os Meus servos comerão, mas vós passareis fome; os Meus servos beberão, mas vós ficareis sedentos; Meus servos se alegrarão, mas vós sereis envergonhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Os Meus servos gritarão felizes por terem um coração alegre, mas vós chorareis pela dor do vosso coração e vos lamentareis por terem um espírito angustiado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Vós deixareis para trás o vosso nome como uma maldição para Meus escolhidos falarem; Eu, o Senhor Yahweh, vos matarei; Eu chamarei Meus servos por outro nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Aquele que pronunciar uma bênção sobre a terra será abençoado por Mim, o Deus da verdade. Aquele que fizer um juramento sobre a terra jurará por Mim, o Deus da verdade, porque os problemas passados serão esquecidos, pois estarão escondidos de Meus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Eis que Eu estou prestes a criar novos céus e uma nova terra; e as primeiras coisas não serão lembradas nem trazidas à memória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Mas vós sereis felizes e vos regozijareis sempre no que Eu estou prestes a criar. Eis que Eu estou prestes a criar alegria para Jerusalém e, para o seu povo, contentamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Eu Me regozijarei em Jerusalém e serei feliz com o Meu povo; choro e gritos de desespero não mais serão ouvidos nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Nunca mais uma criança viverá lá apenas por alguns dias; nem um idoso morrerá antes de seu tempo. Aquele que morrer aos cem anos de idade será considerado ainda jovem. Quem não atingir a idade de cem anos será considerado amaldiçoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Eles construirão casas e nelas habitarão; plantarão vinhas e comerão dos seus frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Eles não mais construirão uma casa e outra pessoa viverá nela; não plantarão e outros comerão. Como o tempo de vida das árvores, serão os dias do Meu povo. Os Meus escolhidos desfrutarão plenamente do trabalho de suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Eles não trabalharão em vão, nem darão à luz filhos para a ruína. Pois eles são os filhos dos abençoados por Yahweh, e os seus descendentes estarão com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Antes de eles clamarem, Eu responderei; e enquanto eles estiverem ainda falando, Eu os ouvirei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'O lobo e o cordeiro pastarão juntos e o leão comerá palha como o boi, mas o pó será a comida da serpente. Não mais farão o mal, nem dano algum, em todo o Meu santo monte\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Isto é o que Yahweh diz: \"O céu é o Meu trono e a terra é o estrado dos Meus pés. Então, onde está a casa que construireis para Mim? Onde é o lugar para o Meu descanso?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Minha mão fez todas essas coisas e, assim, elas vieram a existir — esta é uma declaração de Yahweh. Este é o homem que Eu aprovo: o quebrantado e contrito de espírito e que treme com a Minha palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Aquele que mata um boi também mata um homem; aquele que sacrifica um cordeiro também quebra o pescoço de um cachorro; aquele que oferece uma oferta de cereais também oferece o sangue de porco; aquele que oferece um memorial de incenso também bendiz a idolatria. Eles escolheram seus próprios caminhos e se agradaram em suas abominações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Da mesma forma, Eu escolhi puni-los. Eu trarei o que eles temem porque, quando Eu os chamei, eles não responderam; quando Eu falei, eles não escutaram. Eles fizeram o que era mau aos Meus olhos e escolheram fazer aquilo que Me desagrada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Ouvi a palavra de Yahweh, vós que tremeis com a Sua palavra: \"Vossos irmãos que vos odeiam e vos excluem por causa do Meu nome disseram: \'Que Yahweh seja glorificado. Então, veremos a vossa alegria\', mas eles serão envergonhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Um som de grande tumulto vem da cidade, um som do templo, o som de Yahweh retribuindo aos Seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Antes que entrasse em trabalho de parto, ela deu à luz; antes que viessem as dores, ela deu à luz um filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Quem ouviu tal coisa? Quem viu tais coisas? Nascerá uma povo em um dia? Poderá uma nação ser estabelecida em um momento? Todavia, assim que Sião entrar em trabalho de parto, dará à luz aos seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Eu geraria e não permitiria que o bebê nascesse?” — pergunta Yahweh; ou “Eu traria uma criança para o momento do parto e a deteria?” — pergunta o teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Alegrai-vos com Jerusalém e ficai felizes por ela, todos vós que a amam; alegrai-vos com ela, todos vós que por ela lamentaram!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Pois ireis mamar e ficareis satisfeitos; nos seus seios, vós sereis confortados, pois bebereis até que vos farteis e tereis prazer na abundância da sua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Isto é o que Yahweh diz: \"Eu estou prestes a derramar prosperidade sobre ela como um rio, e as riquezas das nações, como uma inundação. Vós mamareis nela, sereis levados em seus braços e sereis afagados em seus joelhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Como uma mãe conforta seu filho, Eu vos confortarei; em Jerusalém, sereis confortados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Vós vereis isso e o vosso coração se alegrará; vossos ossos brotarão como a tenra grama. A mão de Yahweh será revelada aos Seus servos, mas Ele mostrará Sua ira contra os Seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Eis que Yahweh virá com fogo, e Suas carruagens são como vendaval trazendo o calor da Sua ira, e Sua repreensão com chamas de fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Pois Yahweh executa o juízo sobre o homem com fogo e com Sua espada. Os mortos por Yahweh serão muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Eles se dedicam a Yahweh e se fazem puros para entrarem nos jardins, seguindo aqueles que comem carne de porco e outras coisas abomináveis, como ratos. \"Todos eles perecerão” — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, '“Pois Eu conheço seus feitos e seus pensamentos. Chegará o tempo em que Eu juntarei todas as nações e línguas; elas virão e verão a Minha glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Eu porei um poderoso sinal no meio delas. Então, Eu enviarei os sobreviventes para as nações: para Társis, Pul e Lude (de grandes arqueiros), para Tubal, Javã e para o litoral distante, onde eles não ouviram sobre mim nem viram Minha glória. Eles proclamarão Minha glória entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Eles trarão de volta todos os vossos irmãos, de todas as nações, como uma oferta a Yahweh. Eles virão em cavalos e em carruagens, em charretes, sobre mulas e camelos, para Jerusalém, o Meu monte santo” — diz Yahweh. “Pois o povo de Israel trará uma oferta de cereais, em um vaso puro, à casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Eu escolherei alguns deles como sacerdotes e levitas” — diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, '“Assim como os novos céus e a nova terra, que Eu vou criar, permanecerão diante de Mim” — esta é a declaração de Yahweh — “assim sua descendência e seu nome permanecerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'De um mês para o outro, e de um sábado para o próximo, todas as pessoas virão e se curvarão diante de Mim” — diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, '“Eles sairão e verão os corpos mortos dos homens que se rebelaram contra Mim, pois o verme que os comem não morrerá, e o fogo que os consome não se extinguirá; e isso será abominação para toda a carne\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Estas são as palavras de Jeremias, filho de Hilquias, um dos sacerdotes em Anatote, na terra de Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'A palavra de Yahweh veio a ele nos dias de Josias, filho de Amom, rei de Judá, no décimo terceiro ano do seu reinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Ela também veio nos dias de Jeoaquim, filho de Josias, rei de Judá, até o quinto mês do décimo primeiro ano de Zedequias, filho de Josias, rei de Judá, quando o povo de Jerusalém foi levado como prisioneiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, '\"Antes que Eu te formasse no ventre, Eu te escolhi; antes que tu saísses do ventre, Eu te separei; Eu te fiz um profeta para as nações\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Eu disse: \"Ah, Senhor Yahweh, eu não sei como falar, porque sou muito jovem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Mas Yahweh me disse: \"Não digas: \'Eu sou muito jovem\'. Tu irás para todos os lugares aonde Eu te enviar, e dirás tudo o que Eu te ordenar!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Não tenhas medo deles, pois Eu estou contigo para te socorrer\" — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Então, Yahweh estendeu Sua mão, tocou minha boca e me disse: \"Agora, Eu coloquei Minha palavra na tua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Hoje, Eu estou te nomeando sobre as nações e reinos para arrancar e quebrar, para destruir e derrubar, para construir e plantar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'A palavra de Yahweh veio a mim, dizendo: \"O que vês, Jeremias?\". Eu disse: \"Vejo um ramo de amendoeira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Yahweh me disse: \"Viste bem, pois Eu estou vigiando para que a Minha palavra se cumpra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'A palavra de Yahweh veio a mim uma segunda vez, e disse: \"O que vês?\". Eu disse: \"Vejo uma panela fervente, cuja superfície está agitada, que se inclina do norte para cá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Yahweh me disse: \"O desastre virá do norte sobre todos os que habitam nesta terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Pois Eu estou chamando todas as tribos dos reinos do norte, declara Yahweh. Elas virão, e todos colocarão seus tronos junto aos portões de entrada de Jerusalém, contra todos os muros que a cercam, e contra todas as cidades de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Eu pronunciarei uma sentença contra elas por todo o mal em abandonarem-Me, por queimarem incenso a outros deuses e por adorarem o que fizeram com as próprias mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Prepara-te! Levanta-te e dize-lhes tudo o que Eu te ordenar. Não te abales diante deles, ou serei Eu que te abalarei diante deles!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Vê que hoje Eu fiz de ti uma cidade fortificada, uma coluna de ferro, e muros de bronze contra toda a terra — contra os reis de Judá, seus oficiais, seus sacerdotes e o povo desta terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Eles lutarão contra ti, mas não te derrotarão, pois Eu estarei contigo para te resgatar\" — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, '\"Vai e proclama aos ouvidos de Jerusalém. E diz: \'Assim diz Yahweh: Eu Me lembro, em teu favor, da fidelidade à aliança na tua juventude, do teu amor no tempo em que éramos noivos, quando tu seguias atrás de Mim no deserto, por uma terra não semeada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Israel era consagrado a Yahweh, os primeiros frutos da Sua colheita! Todos aqueles que os comiam eram tidos por culpados e a calamidade vinha sobre eles — esta é a declaração de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Ouvi a palavra de Yahweh, casa de Jacó e todas as famílias na casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Assim diz Yahweh: \"O que vossos pais acharam de errado Comigo, para que se afastassem de Me seguir? Por que eles seguiram ídolos inúteis e eles mesmos tornaram-se inúteis?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Eles não perguntaram: \'Onde está Yahweh, que nos trouxe da terra do Egito? Onde está Yahweh, que nos guiou no deserto, pela terra de Arabá e de covas, uma terra árida e de profunda escuridão, uma terra por onde ninguém passa e ninguém habita?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Mas Eu vos trouxe para a terra do Carmelo, para comer de seu fruto e outras coisas boas! No entanto, quando chegastes, contaminastes minha terra e fizestes da minha herança uma abominação!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'O sacerdote não perguntou: \'Onde está Yahweh?\' Mas os intérpretes da lei não se importaram Comigo! Os pastores se rebelaram contra Mim. Os profetas profetizaram por Baal e andaram atrás de coisas sem proveito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Então, Eu ainda vos acusarei — esta é a declaração de Yahweh — e acusarei os filhos dos vossos filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Atravessai para a costa de Quitim e olhai; enviai mensageiros a Quedar, descobri e vede se ali já houve algo assim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Por acaso, houve alguma nação que trocou seus deuses, mesmo estes não sendo deuses? Mas Meu povo trocou sua Glória por aquilo que não lhes pode ajudar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Tremei, céus, por causa disto! Ficai chocados e aterrorizados — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Pois Meu povo cometeu dois males contra Mim: eles abandonaram a Mim, a fonte de águas vivas, e cavaram cisternas para si mesmos, cisternas quebradas que não podem reter água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Por acaso, Israel é um escravo? Por acaso, nasceu ele na casa de seu senhor? Então, por que ele se tornou pilhagem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Os leões jovens rugiram contra ele. Eles fizeram muito barulho e fizeram da sua terra um lugar horrível! Suas cidades estão destruídas, sem nenhum habitante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Além disso, o povo de Mênfis e de Tafnes raspou-vos a cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Por acaso, não fostes vós mesmos que fizestes isso quando abandonastes Yahweh, vosso Deus, enquanto Ele vos guiava pelo caminho?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Então, agora, por que pegar a estrada para o Egito e beber as águas de Sior? Por que pegar a estrada para a Assíria e beber as águas do rio Eufrates?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'É a tua perversidade que te repreende, e a tua incredulidade que te pune. Então, pensa nisso e entende o quanto é mau e amargo abandonar Yahweh, teu Deus, e não Me temer mais — esta é a declaração do Senhor, Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Pois Eu quebrei o teu jugo, o que tinhas nos tempos antigos; Eu rompi os teus grilhões. Ainda assim, disseste: \'Eu não servirei!\', visto que tu te curvaste em todas as altas colinas e debaixo de toda árvore frondosa, como uma adúltera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Eu mesmo plantei a ti como uma videira escolhida, uma semente completamente verdadeira. No entanto, como te tornaste uma vinha corrupta e imprestável?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Mesmo que te limpes no rio ou te laves com sabão forte, tua iniquidade é uma mancha perante Mim — esta é a declaração do Senhor Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Como podes dizer: \'Eu não estou contaminada! Eu não sigo os baalins\'? Olha o que fizeste nos vales! Considera o que tens feito — tu és como a veloz fêmea do camelo, correndo para lá e para cá;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'és como uma jumenta selvagem no cio, acostumada com o deserto, farejando o vento! Quem poderá conter o seu desejo? Nenhum dos machos precisa se cansar procurando-a, pois no tempo do acasalmento a acharão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Não deixes que os teus pés fiquem descalços, nem tua garganta tenha sede! Mas tu disseste: \'Não há esperança! Não! Eu amo os estranhos e vou atrás deles!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Como a vergonha de um ladrão quando é encontrado, assim a casa de Israel será envergonhada — ela, seus reis, seus príncipes, seus sacerdotes e profetas!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'Esses são os que dizem para a árvore: \'Tu és meu pai\'; e para a pedra: \'Tu me deste à luz\'. Suas costas estão viradas para Mim, e não os seus rostos. Todavia, eles dizem nos tempos de transtorno: \'Levanta-Te e salva-nos\'!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Mas onde estão os deuses que fizestes para vós mesmos? Eles que se levantem se quiserem salvar-vos nos tempos de transtorno, pois vossos ídolos são tão numerosos quanto as vossas cidades, Judá!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Então, por que Me acusais de agir errado? Todos vós pecastes contra Mim — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Eu puni vosso povo em vão. Eles não quiseram aceitar a disciplina. Vossa espada devorou vossos profetas como um leão destruidor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Vós que pertenceis a esta geração, prestai atenção em Minha palavra, a palavra de Yahweh! Por acaso, Eu tenho sido um deserto para Israel, ou uma terra de profunda escuridão? Por que Meu povo diz: \'Vamos vagar por aí, não voltaremos mais a Ti\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Por acaso, uma virgem se esqueceria de suas joias ou uma noiva de seus véus? Contudo, Meu povo se esqueceu de Mim por incontáveis dias!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Quão bem te preparaste para procurar o amor! Até mesmo ensinaste os teus caminhos para mulheres perversas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'O sangue da vida dos inocentes e pobres foi encontrado nas tuas roupas, mesmo não sendo eles flagrados em arrombamentos de casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'No entanto, dizes: \'Eu sou inocente; com certeza a ira de Yahweh se desviará de mim\'. Mas vê! Serás julgado pelo que dizes: \'Não pequei\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Por que tratas tão levianamente esta mudança nos teus caminhos? Tu te frustrarás com o Egito, assim como te frustraste com a Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Tu também sairás de lá abatida, com as tuas mãos na cabeça, pois Yahweh rejeitou aqueles em quem confiaste, então não serás ajudada por eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, '\"Se um homem divorciar-se de sua esposa, e ela se separar dele e tornar-se esposa de outro homem, por acaso ele voltará a ela novamente? Não já estaria aquela terra completamente contaminada? Tu viveste como prostituta com muitos amantes, e queres voltar para Mim? — Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Levanta teus olhos para os lugares altos e estéreis e vê! Existe algum lugar onde não praticaste ato sexual ilícito? Na beira das estradas te sentas e esperas por teus amantes, como um nômade no deserto. Tu tens contaminado a terra com a tua prostituição e maldade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Então as chuvas da primavera foram retidas, e as chuvas tardias não chegaram. Mas a tua face é arrogante, como a face de uma mulher promíscua. Tu te recusas a sentir vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Por acaso agora mesmo não me chamaste: \'Meu pai, meu mais próximo amigo de minha juventude,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'ficará irritado para sempre? Ele guardará Sua raiva até o fim?\' Vê! Isso é o que disseste, mas tu cometes todo o mal possível!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Então, Yahweh me disse nos dias do rei Josias: \"Tu vês o que a infiel Israel tem feito? Ela sobe para toda montanha alta e debaixo de toda árvore frondosa, e ali ela age como uma prostituta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Eu disse: \'Depois dela fazer todas essas coisas, ela voltará para mim\', mas ela não voltou. Então Judá, sua irmã infiel, viu isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Eu vi que, apesar de a infiel Israel haver cometido adultério, e Eu haver lhe dado uma certidão de divórcio, mesmo assim, Judá, a sua irmã infiel, não teve medo e também foi para fora e agiu como uma prostituta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Ela não se importava em nada com a sua prostituição; ela contaminou a terra, cometeu adultério com pedras e árvores, adorando-as.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'E, depois de tudo isso, Judá, a sua irmã infiel, voltou para Mim; porém, não com todo o seu coração, mas com uma mentira — esta é a declaração de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Então, Yahweh me disse: \"A infiel Israel tem sido mais justa que a infiel Judá!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Vai e proclama essas palavras para o norte. Dize: \'Volta, infiel Israel! —Esta é a declaração de Yahweh — Eu não estarei irado contigo para sempre, porque sou fiel — esta é a declaração de Yahweh — Eu não ficarei irado para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Reconhece a tua iniquidade, porque tu tens transgredido contra Yahweh, teu Deus; tens compartilhado teus caminhos com estranhos embaixo de toda árvore frondosa! Pois não tens escutado Minha voz! — Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Volta, povo infiel! — Esta é a declaração de Yahweh — Porque Eu sou teu marido. Eu vos trarei, um de uma cidade e dois de um clã, e vos trarei a Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Eu vos darei pastores segundo o Meu coração, e eles vos apascentarão com conhecimento e percepção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Então, acontecerá que, naqueles dias, aumentareis e dareis fruto na terra — esta é a declaração de Yahweh — Não mais se dirá: \"A arca da aliança de Yahweh!\" Esse assunto não mais surgirá em vosso coração, nem será lembrado; ela não fará falta, e não será feita uma outra\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Naquele tempo, proclamarão a respeito de Jerusalém: \'Este é o trono de Yahweh\', e todas as outras nações se reunirão em Jerusalém, em nome de Yahweh. Elas não mais andarão na teimosia de seus perversos corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'Nesses dias, a casa de Judá andará com a casa de Israel. Elas virão juntas da terra do norte para a terra que Eu dei como herança aos vossos ancestrais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Eu disse a Mim mesmo: \'Como Eu quero te honrar como Meu filho e te dar uma terra agradável, a herança mais bonita do que há em qualquer outra nação!\' Eu teria dito: \'Tu me chamarás de meu Pai\'. Teria dito que tu não te desviarias de Me seguir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Porém, como uma mulher infiel ao seu marido, tu Me traíste, casa de Israel — esta é a declaração de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Ouve-se uma voz nos lugares altos e estéreis, o choro e a súplica de Israel! Porque eles mudaram seus caminhos, eles se esqueceram de Yahweh, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, '\"Voltai, povo infiel! Eu vos curarei da infidelidade!\" \"Eis que nós viremos para Ti, porque Tu és Yahweh, nosso Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Certamente, as mentiras vêm das colinas, um ruído de confusão das montanhas. Certamente, Yahweh, nosso Deus, é a salvação de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Mas os ídolos vergonhosos consumiram aquilo pelo qual nossos ancestrais trabalharam: seus rebanhos e gado, seus filhos e filhas!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Deitemo-nos em vergonha. Que a vergonha nos cubra porque pecamos contra Yahweh, nosso Deus! Nós mesmos e nossos ancestrais, desde a nossa juventude até hoje, não escutamos a voz de Yahweh, nosso Deus!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Se voltares, ó Israel — esta é a declaração de Yahweh — então, é a Mim a quem tu deves voltar. Se tirares tuas coisas abomináveis de diante de Mim e não te desviares de Mim novamente,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'se jurares: \'Tão certo como Yahweh vive\', com fidelidade, justiça e retidão, então, Nele as nações serão abençoadas e Nele se gloriarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Porque assim diz Yahweh a cada pessoa de Judá e de Jerusalém: \'Lavrai vosso campo e não semeeis entre espinhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Circuncidai-vos a Yahweh e removei os prepúcios do vosso coração, ó homens de Judá e habitantes de Jerusalém, senão Minha fúria se espalhará como fogo e queimará, sem que ninguém possa apagá-la, por causa das maldades dos vossos atos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Anunciai em Judá e seja proclamado em Jerusalém; dizei: \'Tocai a trombeta na terra\'. Proclamai: \'Reuni-vos. Vamos às cidades fortificadas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Levantai o sinal, apontai-o para Sião, correi para a vossa segurança! Não permaneçais, porque estou trazendo do norte o desastre, e uma grande destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Um leão está saindo do seu matagal e alguém que destruirá as nações está de partida. Ele deixou o seu lugar para trazer horror à tua terra, para tornar as tuas cidades em ruínas, onde ninguém viverá. Por isso vesti-vos de pano de saco, lamento e pranto;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'porque a força da ira de Yahweh não se desviou de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Acontecerá que, naquele dia — esta é a declaração de Yahweh — os corações do rei e de seus oficiais estarão como mortos. Os sacerdotes ficarão aterrorizados e os profetas, horrorizados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Então eu disse: \"Ó, Senhor Yahweh, certamente enganaste este povo e Jerusalém quando disseste: \'Haverá paz para vós\'. Entretanto, a espada está golpeando contra suas vidas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Naquele tempo será dito a este povo e a Jerusalém: \"Um vento abrasador virá dos planaltos do deserto para a filha do Meu povo. Não para peneirar nem para limpar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Um vento muito mais forte do que este virá sob o Meu comando e, agora, Eu pronunciarei uma sentença contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Vede! Ele avança como as nuvens, e suas carruagens são como uma tempestade. Seus cavalos são mais rápidos do que as águias. Ai de nós, porque seremos devastados!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Limpa teu coração da maldade, Jerusalém, para que sejas salva. Por quanto tempo os teus pensamentos serão sobre como pecar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Pois uma voz está trazendo notícias de Dã e o desastre que virá já pode ser ouvido das montanhas de Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Informai às nações a respeito disto: Vede! Anunciai a Jerusalém que os adversários vêm de uma terra distante para darem o seu grito de guerra contra as cidades de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Eles serão como vigias de uma plantação, ao redor dela por todos os lados, pois ela se rebelou contra Mim — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'A tua conduta e os teus atos que te fizeram isto. Esta será a tua punição. Quão terrível será! Atingirá o teu próprio coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Meu coração, meu coração! Eu estou angustiado em meu coração. Meu coração está conturbado dentro de mim. Não consigo ficar calado, pois ouço o som da trombeta, um alarme para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Haverá desastre após desastre, pois toda a terra está devastada. Repentinamente, são destruídas as minhas tendas e, num instante, as minhas cortinas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Até quando verei a bandeira e ouvirei o som da trombeta?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, '\"Pois o Meu povo é tolo e não Me conhece. São insensatos e não têm entendimento. São habilidosos para o mal, mas não sabem fazer o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Olhei para a terra. Vede! Ela era sem forma e vazia. Não havia luz nos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Olhei para as montanhas. Vede! Elas tremiam, e todas as colinas estremeciam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Eu olhei. Vede! Não havia ninguém, e todas as aves dos céus haviam fugido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Eu olhei. Vede! Os pomares haviam-se transformado em desertos e todas as cidades estavam arrasadas diante de Yahweh, diante do furor de Sua ira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Pois assim diz Yahweh: \"Toda a terra será devastada, mas Eu não a destruirei completamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Por esta razão, a terra lamentará, e os céus, acima, escurecerão. Pois Eu anunciei as Minhas intenções; não voltarei atrás, nem desistirei de realizá-las.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Todas as cidades fugirão do barulho dos cavaleiros e dos flecheiros com arcos; elas fugirão para as florestas; todas as cidades escalarão as rochas. As cidades serão abandonadas, pois não haverá ninguém para habitá-las.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Agora que foste devastada, o que farás? Pois, embora te vistas de púrpura e te adornes com joias de ouro e, com pinturas, faças teus olhos parecerem maiores, os homens que te cobiçavam, agora te rejeitam. Eles estão tentando tirar tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Então, ouço um som de angústia; a aflição como a do parto do primeiro filho; a voz da filha de Sião, que está ofegante. Ela estende as mãos: \'Ai de mim! Estou desfalecendo por causa desses assassinos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Correi pelas ruas de Jerusalém, procurai também nas praças da cidade; então, olhai e pensai sobre isto: se puderes achar um homem ou qualquer um que aja com justiça, ou esteja tentando agir fielmente, então, perdoarei Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Mesmo que eles digam: \'Tão certo quanto Yahweh vive\', ainda assim, estão jurando falsamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Yahweh, por acaso Teus olhos não buscam fidelidade? Tu golpeias as pessoas, mas elas não sentem dor. Tu os tens derrotado completamente, mas eles ainda se recusam a receber disciplina. Eles tornam suas faces mais duras que a rocha, pois se recusam a se arrepender.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Então eu disse: \"Certamente, apenas o povo pobre é assim. Esses são tolos, pois não conhecem os caminhos de Yahweh, os decretos do seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Irei para as pessoas importantes e lhes declararei as mensagens de Yahweh porque, pelo menos, eles conhecem os caminhos de Yahweh, os decretos do seu Deus. Mas, todos eles quebraram o jugo juntos, todos eles romperam as correntes que os ligavam a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Por isso, um leão da mata os atacará. Um lobo de Arabá os arruinará. Uma pantera à espreita atacará suas cidades. Qualquer um que sair da cidade será dilacerado, porque suas transgressões aumentam e seus atos de infidelidade são ilimitados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Por que Eu deveria perdoar essas pessoas? Seus filhos Me abandonaram e fizeram juramento pelos que não são deuses. Eu os tenho alimentado por completo, mas eles cometeram adultério e andaram em grande número para as casas de prostituição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Eles eram como cavalos bem nutridos, perambulando a fim de se acasalarem, cada um relinchando à mulher de seu próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Por acaso, Eu não os deveria punir? —Esta é a declaração de Yahweh — e Eu não deveria Me vingar de uma nação como esta?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Subi até os terraços de suas vinhas e destruí-as, mas não façais uma destruição total sobre elas. Aparai suas videiras, uma vez que essas videiras não vieram de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Pois as casas de Israel e de Judá têm-Me traído completamente — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Elas têm falado falsamente de Yahweh e dizem: \'Ele não fará nada. O mal não virá sobre nós, nem veremos a espada ou a fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Os profetas têm-se tornado como o vento; a palavra não está neles; por isso, que caiam sobre eles mesmos o que eles dizem que acontecerá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Assim diz Yahweh, o Deus dos Exércitos: \"Por que falastes isso, vede, Eu estou prestes a colocar a Minha palavra na tua boca, e ela será como um fogo e este povo será como madeira, pois ela os consumirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Vede! Eu trarei uma nação de longe contra vós, casa de Israel — esta é a declaração de Yahweh — uma nação duradoura, uma nação antiga. Uma nação cuja língua tu não conheces, nem entendes o que eles dizem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Sua aljava é como um túmulo aberto. Todos eles são guerreiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Então, tua colheita será consumida, teus filhos e tuas filhas também, e a tua comida. Eles comerão teus rebanhos e gados; eles comerão do fruto de tuas vinhas e figueiras. Com a espada, eles demolirão tuas cidades fortificadas, nas quais tu confias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Mas, mesmo naqueles dias — esta é a declaração de Yahweh — Eu não pretendo destruir-vos completamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Quando vós, Israel e Judá, disserdes: \'Por que Yahweh, nosso Deus, tem feito todas estas coisas conosco?\' Então tu, Jeremias, lhes dirás: \'Assim como vós abandonastes a Yahweh e servistes a deuses estrangeiros em vossa terra, assim, vós também servireis a estranhos em uma terra que não é a vossa\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Relata isso à casa de Jacó e seja ouvido em Judá. Diz:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, '\'Ouvi isto vós, ó povo tolo, que não tendes entendimento; que tendes olhos, mas não podeis ver, e tendes ouvidos, mas não podeis ouvir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Vós não Me temeis? — Esta é a declaração de Yahweh — nem tremeis diante da Minha face? Eu coloquei a areia como limite para o mar, um decreto contínuo que não se pode violar, ainda que as ondas subam e desçam, mesmo assim, não o violam. Embora as ondas rujam, elas não o ultrapassam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Mas este povo tem um coração obstinado. Eles se desviaram em rebelião e foram embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Pois eles não dizem em seus corações: \'Temamos a Yahweh, nosso Deus, Aquele que traz a chuva, as primeiras chuvas e as chuvas tardias, no seu tempo certo, nas semanas determinadas de nossa colheita\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Vossas iniquidades têm impedido que essas coisas aconteçam. Vossas iniquidades têm impedido que as coisas boas venham até vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Pois homens ímpios são achados com o Meu povo. Eles ficam à espreita como alguém que se agacha para capturar pássaros; eles põem uma armadilha para apanhar o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Como uma gaiola cheia de pássaros, assim também todas as suas casas estão cheias de engano. Por isso, eles crescem e se enriquecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Eles se tornaram gordos e satisfeitos por estarem em boas condições. Eles ultrapassaram todos os limites da maldade; não defendem a causa do povo, nem a causa dos órfãos. Eles prosperam, mesmo não dando justiça aos necessitados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Por acaso, não devo Eu castigá-los por essas coisas? — Esta é a declaração de Yahweh — E, por acaso, não Me vingarei de uma nação como esta?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Atrocidades e horrores têm ocorrido nesta terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Os profetas profetizam engano e os sacerdotes governam com seu próprio poder. Meu povo ama isso, mas, no fim, o que há de acontecer?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Buscai segurança, povo de Benjamim, deixando Jerusalém. Tocai a trombeta em Tecoa. Levantai um sinal sobre Bete-Haquerém, porque o mal vem surgindo do norte; uma grande destruição está vindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'A filha de Sião, a bela e delicada mulher, será destruída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Contra ela irão os pastores e seus rebanhos; armarão tendas ao seu redor; cada homem apascentará com a sua própria mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Dirão: \"Consagrai-vos para a batalha. Levantai-vos, ataquemos ao meio-dia. É muito ruim que a luz do dia esteja esmaecendo, que as sombras da tarde estejam caindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Mas ataquemos à noite e destruamos a fortaleza dela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Pois assim diz Yahweh dos Exércitos: \"Cortai suas árvores e levantai rampas de cerco contra Jerusalém. Esta é a cidade certa para se atacar, porque ela está cheia de opressão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Como um poço que faz brotar água fresca, assim esta cidade continua produzindo iniquidade. A violência e a desordem são ouvidas nela. As doenças e as feridas estão, continuamente, diante da Minha face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Aceita a disciplina, Jerusalém, ou Eu Me desviarei de ti e te farei uma ruína, uma terra desabitada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Assim diz Yahweh dos Exércitos: \"Certamente, eles recolherão, como numa vinha, aqueles que restaram em Israel. Examina novamente e estende a tua mão para coletar as uvas que deixou escapar das vinhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'A quem eu devo declarar e advertir para que ouçam? Vede! Seus ouvidos são incircuncisos, eles não são capazes de prestar atenção! Vede! A palavra de Yahweh veio a eles para corrigi-los, mas eles não a quiseram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Mas eu estou cheio com a fúria de Yahweh. Estou cansado de retê-la. Ele me disse: \"Derrama-a sobre as crianças nas ruas e nos grupos de jovens. Pois cada homem será levado cativo com sua esposa; e cada idoso e os de idade muito avançada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Suas casas serão dadas a outros, juntamente com seus campos e suas esposas. Pois Eu atacarei os habitantes da terra com a Minha mão — esta é declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Desde o menor até o maior, todos eles são ávidos pelo ganho desonesto. Do profeta ao sacerdote, todos eles praticam a falsidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Eles têm curado as feridas do Meu povo apenas superficialmente, quando dizem: \'Paz, paz!\' quando não há paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Por acaso, eles se envergonharam quando praticaram abominações? Eles não se envergonharam; nem sequer sabem o que é ficar de rosto corado! Por isso, eles cairão entre os que caírem; eles serão derrubados quando forem punidos, diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Assim diz Yahweh: \"Ficai de pé na encruzilhada e vede; perguntai pelos caminhos antigos. \'Onde fica o bom caminho?\' Então ide por ele e encontrai um lugar de descanso para vós. Mas o povo dirá: \'Não iremos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Eu designei para ti guardas para ouvirem a trombeta. Mas eles disseram: \'Não ouviremos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Por isso, nações, ouvi! Vede, vós testemunhas, o que lhes acontecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Ouve, ó terra! Vê, Eu trarei o desastre a esse povo, o fruto dos seus pensamentos. Eles não prestaram atenção à Minha palavra ou à lei; pelo contrário, eles a rejeitaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'O que este incenso subindo de Sabá significa para Mim? Ou estes cheiros suaves de uma terra distante? Vossos holocaustos não são aceitáveis a Mim, nem o são os vossos sacrifícios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Pois Yahweh diz: \"Vê, Eu colocarei uma pedra de tropeço contra este povo. Eles tropeçarão nela, pais e filhos juntamente. Os habitantes e seus vizinhos também perecerão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Assim diz Yahweh: \"Vê, um povo está vindo da terra do norte. Pois uma grande nação tem sido provocada para vir de uma terra distante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Eles estarão armados de arcos e lanças. Eles são cruéis e não têm compaixão. Seu som é como o barulho do mar, e estão cavalgando em formação como homens de guerra contra ti, ó filha de Sião.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Nós temos ouvido as notícias sobre eles. Nossas mãos caem flácidas de aflição. A angústia se apodera de nós como as dores de uma mulher em trabalho de parto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Não saiais para o campo, nem andeis pelas estradas, pois as espadas do inimigo e o terror estão em todo o redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, '\"Ó, filha do Meu povo, veste-te de saco, rolando em cinzas, como o funeral de um filho único. Faze para ti um funeral amargo, porque o destruidor virá, repentinamente, sobre nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, '\"Eu te criei, Jeremias, aquele que examina o Meu povo como quem testa o metal, para que examines e testes o caminho deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Ele é o mais teimoso dos povos, que sai ao redor difamando os outros. Todos eles são bronze e ferro, agindo corruptamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Os foles já se queimaram pelo fogo que os aquecia; o chumbo já foi consumido nas chamas. O refino continua entre eles, mas é inútil, porque o mal não é removido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Eles serão chamados prata rejeitada, pois Yahweh os tem rejeitado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Esta é a palavra que veio a Jeremias da parte de Yahweh:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, '\"Põe-te à porta da casa de Yahweh e proclama esta palavra! Dize: \'Ouvi a palavra de Yahweh, todos de Judá que entram por estes portões para adorar Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Yahweh dos Exércitos, Deus de Israel, diz: Endireitai os vossos caminhos e praticai o que é bom, e vos deixarei viver aqui neste lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Não confieis em palavras enganosas, dizendo: \'Templo de Yahweh! Templo de Yahweh! Templo de Yahweh!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Mas se endireitardes completamente os vossos caminhos e praticardes o que é bom; se realmente praticardes a justiça entre um homem e o seu próximo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'se não explorardes os que estão na terra, o órfão ou a viúva, e não derramardes sangue inocente neste lugar, e nem seguirdes outros deuses para o seu próprio mal,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'então, Eu vos deixarei habitar neste lugar, na terra que dei aos vossos antepassados desde a antiguidade e para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Vede! Vós confiais em palavras enganosas e inúteis que não vos ajudam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Vós roubais, matais e cometeis adultério? Jurais falsamente e ofereceis incenso a Baal, e seguis outros deuses que não conhecestes?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'E, depois vós vindes diante de Mim nesta casa, onde Meu nome é proclamado, e dizeis: \'Estamos salvos\', para continuardes a praticar todas essas abominações?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Nesta casa, que leva o Meu nome, um covil de ladrões aos vossos olhos? Mas eu tenho visto isto — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Portanto, vai ao Meu lugar que estava em Siló, onde permiti que o Meu nome habitasse no início, e olha o que Eu fiz por causa da maldade do Meu povo Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Agora, porque fizestes todas essas coisas — esta é a declaração de Yahweh — Eu vos falei repetidas vezes, mas não Me ouvistes. Eu os convoquei, mas não Me respondestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Portanto, o que fiz a Siló, também farei a esta casa, que se chama pelo Meu nome, a casa em que confiastes, este lugar que dei a vós e a vossos pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Eu vos expulsarei da Minha presença, como expulsei todos os vossos irmãos, todos os descendentes de Efraim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'E tu, Jeremias, não ores por este povo, e não levantes um lamento ou oração em seu favor, nem intercedas a Mim, pois não te ouvirei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Não vês o que eles fazem nas cidades de Judá e nas ruas de Jerusalém?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Os filhos juntam a lenha e os pais acendem o fogo! As mulheres amassam a farinha para fazerem bolos à rainha dos céus, e colocam ofertas de bebidas aos deuses, a fim de Me provocarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Estão realmente me provocando? — esta é a declaração de Yahweh — não é a si mesmos que provocam, para sua própria vergonha?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Portanto, o Senhor Yahweh diz isto: \'Vê, a minha raiva e a minha ira se derramarão sobre este lugar, sobre os homens e animais, sobre as árvores nos campos e os frutos da terra. Queimará e não se apagará\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Yahweh dos Exércitos, o Deus de Israel, diz: \'Juntai os vossos holocaustos aos vossos sacrifícios e comei a carne\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Pois quando tirei os vossos pais da terra do Egito, não exigi nada deles. Eu não ordenei coisa alguma sobre holocaustos e sacrifícios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Apenas lhes dei esta ordem: \'Ouvi a Minha voz, e serei o vosso Deus e vós sereis o Meu povo. Então, andai no caminho que Eu lhes guiar, para que tudo vá bem a vós\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Mas não me ouviram, nem prestaram atenção. Viveram nos seus próprios planos, no propósito do seu coração perverso. Andaram para trás e não para frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Desde o dia em que vossos ancestrais saíram da terra do Egito até hoje, Eu enviei todos os Meus servos e profetas até vós. Persisti em enviá-los,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'mas não Me ouviram, não prestaram atenção, foram teimosos. Foram mais perversos do que seus ancestrais\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Anuncia essas palavras a eles, mas não te ouvirão. Anuncia essas coisas a eles, mas eles não te responderão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Dize a eles que esta é uma nação que não ouve a voz de Yahweh, seu Deus, e não recebe a correção; a verdade foi destruída e desapareceu de seus lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Cortai vossos cabelos e jogai fora. Cantai uma canção fúnebre sobre os lugares abertos. Pois Yahweh rejeitou e abandonou esta geração na Sua ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Os filhos de Judá fizeram o que era mau aos Meus olhos — esta é a declaração de Yahweh — eles colocaram suas imagens detestáveis na casa onde Meu nome é anunciado, para corrompê-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Construíram o santuário de Tofete, que está no vale de Ben-Hinom. Fizeram isto para queimar seus filhos e filhas como sacrifício, coisa que nunca ordenei, que nunca Me veio à mente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Então vede, vem os dias — esta é a declaração de Yahweh — em que não se chamará Tofete ou vale de Ben-Hinom, mas vale da Matança; enterrarão cadáveres em Tofete até que não haja mais lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'E os cadáveres deste povo servirão de comida para as aves do céu e para os animais da terra, e não haverá ninguém para espantá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Darei fim às cidades de Judá e às ruas de Jerusalém, à voz de alegria e júbilo, à voz do noivo e da noiva; porque a terra se tornará em deserto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, '\"Naquele tempo, eles tirarão das sepulturas os ossos dos reis de Judá e de seus oficiais, os ossos dos sacerdotes e profetas, e os ossos dos habitantes de Jerusalém — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Então, eles os espalharão à luz do sol, da lua e de todas as estrelas dos céus; estas coisas no céu às quais eles têm seguido e servido, e às quais eles têm inquirido e adorado. Os ossos não serão reunidos e enterrados novamente. Eles serão como esterco na superfície da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Em cada lugar remanescente onde Eu os tenho lançado, eles escolherão para si mesmos a morte, ao invés da vida, todos os que ainda restaram desta terrível nação – esta é a declaração de Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Então diga a eles: \'Yahweh diz isto: Cai alguém e não se levanta? Fica alguém perdido e não tenta retornar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Por que este povo, Jerusalém, tem virado as costas em permanente infidelidade? Eles agarram-se à mentira e não querem se arrepender.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Eu prestei atenção e ouvi, mas eles não falaram direito; ninguém estava triste por sua maldade, ninguém para dizer: \'O que eu tenho feito?\' Todos eles vão para onde desejam, como um cavalo correndo em direção a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Até mesmo a cegonha no céu conhece as estações certas, e as pombas, andorinhas, e tordos. Eles migram no tempo certo, mas Meu povo não conhece os decretos de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Por que vós dizeis: \'Nós somos sábios! E a lei de Yahweh está conosco?\' Na verdade, vede! A pena enganosa dos escribas tem criado mentira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Os homens sábios serão envergonhados. Eles estão consternados e presos. Vede! Eles rejeitam a palavra de Yahweh; então, qual é a utilidade da sabedoria deles?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Assim, Eu darei as esposas deles para outros, e os seus campos para aqueles que irão possuí-los; desde o mais jovem até o maior, todos eles se dão à avareza! Desde o profeta até o sacerdote, todos eles praticam o engano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Eles curaram superficialmente a ferida do Meu povo. Eles disseram: \'Paz! Paz!\', mas não havia paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Eles estavam envergonhados quando eles praticavam abominações? Eles não estavam envergonhados. Eles não tiveram humildade. Então eles cairão no tempo da punição deles, com aqueles que já haviam caído. Eles serão derrubados, diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Eu irei removê-los completamente e não haverá uvas na vinha, nem haverá figos nas figueiras. Pois a folha secará, e o que Eu tenho dado a eles morrerá – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'O povo dirá: \'Por que nós estamos assentados aqui? Vamos juntos; vamos para as cidades fortificadas, e lá nos tornaremos silenciosos na morte. Pois Yahweh nosso Deus nos silenciará. Ele nos fará tomar veneno, desde que nós pecamos contra Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Nós estamos esperando por paz, mas não haverá nada bom. Nós estamos esperando por um tempo de cura, mas vede, haverá terror.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'O bufar dos Seus cavalos são ouvidos desde Dã. Toda a terra treme ao som do relinchar dos Seus cavalos fortes. Pois eles virão e consumirão a terra e sua riqueza, a cidade e os que vivem nela\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Pois vede, Eu estou enviando cobras no meio de vós, víboras que vós não podeis encantar, e elas vos morderão – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Minha tristeza não tem fim, e meu coração está doente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Vde! A voz estridente da filha do Meu povo de uma terra distante! Não está Yahweh em Sião? Ou não está nela o seu Rei? Por que, então, eles Me ofendem com as suas figuras esculpidas e os ídolos estrangeiros sem valor?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'A colheita já passou, o verão terminou. Mas nós não fomos salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Eu estou ferido devido à ferida da filha do Meu povo. Eu choro diante das coisas horríveis que têm acontecido a ela; eu estou consternado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Não há bálsamo em Gileade? Não há médico lá? Por que a cura da filha do Meu povo não acontece?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Se, ao menos, eu chorasse sem parar, e meus olhos fossem uma fonte de lágrimas! Pois choraria de dia e de noite pelos mortos da filha do meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Se, ao menos, alguém me desse um lugar para os viajantes no deserto ficarem, onde eu pudesse ir e abandonar o meu povo. Se, ao menos, eu pudesse largá-los, já que todos são adúlteros, um bando de traidores!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Yahweh declara: \"Eles dizem coisas falsas com suas línguas, que são seus arcos fraudulentos, mas não é por causa de nenhuma fidelidade deles que se tornam fortes na terra. Eles vão de um ato perverso para outro. Eles não Me conhecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Ficai atentos, cada um de vós, contra vosso companheiro, e não confieis em qualquer irmão, pois todos os irmãos são enganadores, e cada companheiro anda caluniando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Cada homem zomba do seu companheiro, e não fala a verdade. Suas línguas ensinam coisas fraudulentas; eles estão exaustos de cometer iniquidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Vossa habitação está no meio do engano; pelo engano, recusam a conhecer-Me – esta é a declaração de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Yahweh dos Exércitos diz: \"Vede! Estou prestes a refinar-vos e a vos testar, pois o que mais Eu posso fazer por causa do que Meu povo fez?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Suas línguas são flechas afiadas, eles falam coisas infiéis. Com suas bocas, proclamam paz a seus vizinhos, mas com seus corações armam ciladas para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Eu não deveria puni-los por causa dessas coisas? – Esta é a declaração de Yahweh – Eu não deveria Me vingar de uma nação como esta?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Eu cantarei uma canção de luto e lamentação às montanhas, e uma canção fúnebre será cantada aos pastos. Pois estão queimados para que ninguém possa passar por eles. Já não se ouvirá o som de nenhum gado. Os pássaros dos céus e todos os animais fugiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Pois Eu transformarei Jerusalém em pilhas de ruínas, um esconderijo de chacais. Eu farei das cidades de Judá lugares de ruínas, sem habitantes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Que homem é sábio o suficiente para entender isso? O que a boca de Yahweh proclama para ele, e ele a declarará? Por que a terra pereceu, e está destruída como o deserto, por onde ninguém pode passar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Yahweh diz: \"É porque eles abandonaram Minha lei, que Eu coloquei diante deles, porque eles não ouvem a Minha voz e não caminham de acordo com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'É porque eles caminham de acordo com seus corações teimosos e seguem baalins, como seus pais lhes ensinaram a fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Por essa razão, Yahweh dos Exércitos, o Deus de Israel, diz isto: \'Vede! Eu estou prestes a fazer este povo comer algo amargo e beber água envenenada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Então, Eu os dispersarei entre as nações que eles não conhecem, nem eles e nem seus ancestrais. Eu enviarei uma espada atrás deles até que Eu os tenha destruído completamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Yahweh dos Exércitos diz: \"Pensai nisto: chamai as cantoras de funerais; deixai que elas venham. Mandai procurar as mulheres habilidosas em lamentar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Que elas se apressem e cantem uma canção de lamento sobre nós; assim, nossos olhos se encherão de lágrimas e nossas pálpebras fluirão com água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Porque o som do lamento é ouvido em Sião: \'Como estamos devastados! Estamos grandemente envergonhados porque abandonamos a terra, uma vez que derrubaram nossas casas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Então vós, mulheres, escutai a palavra de Yahweh; prestai atenção às mensagens que vêm da Sua boca. Então, ensinai vossas filhas uma canção de lamentação, e a cada companheira, uma canção fúnebre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'A morte veio por nossas janelas; ela entra nos nossos palácios. Ela destrói crianças de fora, e jovens nas praças da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Declara isto: \'Os cadáveres dos homens cairão como esterco nos campos, e como talos de grãos após os ceifeiros, e não haverá ninguém para recolhê-los\' – esta é a declaração de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Yahweh diz isto: \"Que o sábio não se orgulhe de sua sabedoria, ou o guerreiro de sua força; que o rico não se orgulhe da sua riqueza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Pois, se um homem se orgulhar de alguma coisa, que seja disto: de Me conhecer e saber que Eu sou Yahweh, que ajo com amor leal, justiça e retidão na terra. Pois é nisto que Eu tenho prazer – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Eis que vêm dias, quando Eu punirei todos os que são apenas circuncidados em seu corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Eu punirei o Egito e Judá, Edom, amonitas e moabitas, todas as pessoas que cortam seus cabelos, que habitam no deserto. Pois todas as nações são incircuncisas e toda a casa de Israel tem um coração incircunciso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Escuta a palavra que Yahweh está anunciando para ti, ó casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Yahweh diz isto: \"Não aprendais os caminhos das outras nações, e não fiqueis desanimados com os sinais nos céus, pois as nações estão atemorizadas com isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Porque os costumes religiosos desses povos são inúteis. Eles cortam uma árvore em uma floresta; obra das mãos do artífice, feita com machado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Então, eles a decoram com prata e ouro. Eles a reforçam com martelo e pregos, para que ela não caia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Esses ídolos são como espantalhos em um pepinal, pois eles também não podem dizer nada. Eles precisam ser carregados porque não podem andar. Não tenhais medo deles, pois eles não podem vos trazer o mal, nem são capazes de fazer qualquer coisa boa.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Não existe ninguém igual a Ti, Yahweh. Tu és grande, e Teu nome é grande em poder!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Quem não Te teme, Rei da nações? Pois isso é o que Tu mereces! Não há nenhum igual a Ti, dentre todos os sábios das nações, ou em todo o reino deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Eles são todos brutos e estúpidos, discípulos de ídolos, que não são nada além de um pedaço de madeira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Eles trazem prata batida de Társis, e ouro de Ufaz; são feitos por artífices, pelas mãos dos fundidores. Suas roupas são azuis e púrpuras. Seus homens hábeis fizeram todas essa coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Mas Yahweh é o verdadeiro Deus. Ele é o Deus vivo e o eterno Rei. A terra treme com Sua ira, e as nações não podem suportar o Seu furor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Assim direis a eles: \'Os deuses que não fizeram o céu e a terra iráo desaparecer da terra e debaixo dos céus.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Mas foi Ele quem fez a terra pelo Seu poder, e Ele estabeleceu o mundo pela Sua sabedoria, e pelo Seu entendimento estendeu os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Ao som da voz do Seu trovão, as águas no céu rugem, e Ele traz as névoas dos fins da Terra. Ele faz os relâmpagos para a chuva e manda os ventos do Seu depósito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Todo homem se tornou ignorante, sem conhecimento. Todo artesão é envergonhado por seus ídolos. Porque a imagem que eles fizeram são fraudes; não há vida nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Elas são inúteis, o trabalho de escarnecedores; eles irão perecer no tempo de sua punição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Mas Deus, a porção de Jacó, não é assim, pois Ele é o moldador de todas as coisas. Israel é a tribo de Sua herança. Yahweh dos Exércitos é Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Recolhe o teu pacote e deixa a tua terra, tu, povo que estás vivendo num lugar sitiado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Pois Yahweh diz isso: \"Vê! Eu estou prestes a lançar fora os habitantes dessa terra. Eu lhes causarei aflição, e eles se encontrarão assim.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Ai de mim! Por causa dos meus ossos quebrados, minha ferida está infectada. Então, eu disse: \"Certamente isso é agonia, mas eu devo suportá-la\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Minha tenda está devastada, e todas as cordas da minha tenda foram cortadas. Eles tiraram meus filhos para longe de mim; então, eles já não existem mais. Não existe mais ninguém para levantar minha tenda e levantar minhas lonas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Pois os pastores se tornaram estúpidos. Eles não buscam Yahweh; então, eles não têm sucesso e todos os seus rebanhos foram espalhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Vêm rumores: \"Vede! Está chegando! Um grande terremoto vindo da terra do norte para tornar a cidade de Judá em ruínas, esconderijo de chacais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Eu sei, Yahweh, que o caminho do homem não vem dele mesmo. Nenhuma pessoa que caminha dirige seus próprios passos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Disciplina-me, Yahweh, com justiça, mas não com a Tua ira, para não me destruires.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Derrama a Tua indignação sobre as nações que não Te conhecem, e sobre as famílias que não chamam pelo Teu nome. Pois eles devoraram Jacó; eles o consumiram e destruíram completamente a sua habitação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'A palavra de Yahweh veio a Jeremias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, '\"Escuta as palavras desta aliança, e as declara para cada homem de Judá e para os habitantes de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Diz a eles: \'Yahweh, Deus de Israel, diz isto: Maldito serão todos os que não escutarem as palavras desta aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Esta é a aliança que ordenei a vossos ancestrais para guardarem o dia em que Eu os trouxe da terra do Egito, do forno de fundição de ferro. Eu disse: \"Escutai a Minha voz e fazei todas as coisas, como vos tenho ordenado, pois vós sereis Meu povo e Eu serei vosso Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Obedecei-Me para que Eu confirme o juramento que fiz a vossos ancestrais, de que Eu daria a eles a terra que mana leite e mel, onde vós morais hoje\". Então, eu, Jeremias, respondi: \"Sim, Yahweh!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Yahweh me disse: \"Proclama todas estas coisas nas cidades de Judá e nas ruas de Jerusalém. Diz: \'Escutai as palavras desta aliança e obedecei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Eu dei uma ordem para vossos ancestrais desde o dia em que Eu os trouxe da terra do Egito até o presente tempo, falando e persistindo em avisá-los: \"Ouvi a Minha voz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Mas eles não ouviram nem prestaram atenção. Cada um andou na teimosia do seu coração perverso. Então, Eu trouxe todas as maldições desta aliança que ordenei que viriam contra vós. Mesmo assim, não obedeceram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'E Yahweh me disse: \"Uma conspiração foi descoberta entre os homens de Judá e os habitantes de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Eles voltaram para a iniquidade dos seus ancestrais, que se recusaram a ouvir as Minhas palavras e andaram após outros deuses para adorá-los. A casa de Israel e a casa de Judá quebraram a Minha aliança, que Eu havia estabelecido com seus ancestrais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Portanto, Yahweh diz isto: \'Eis que estou para trazer uma calamidade sobre eles, desastre do qual não serão capazes de escapar. Então, eles clamarão a Mim, mas Eu não os ouvirei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'As cidades de Judá e os habitantes de Jerusalém irão e clamarão aos deuses a quem ofertaram, mas, certamente, não serão por eles salvos no momento do seu desastre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Pois, Judá, o número dos teus deuses são como o número de tuas cidades. E como o número de ruas em Jerusalém, são os altares vergonhosos que ali levantaste, para queimares incenso a Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Então, tu, Jeremias, não deves orar por eles. Não deves lamentar ou orar em favor deles, pois Eu não ouvirei quando eles clamarem a Mim na sua calamidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Por que Meu povo amado pratica tanta maldade na Minha casa? A carne dos teus sacrifícios não pode te ajudar. Tu te alegras por causa de tuas más ações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'No passado, Yahweh te chamou de oliveira frondosa e bela, com frutos deliciosos, mas Ele acenderá um fogo contra essa árvore, que soará como brado de uma tempestade, e seus galhos serão quebrados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Pois Yahweh dos Exércitos, Aquele que te plantou, tem decretado a calamidade que virá sobre ti, por causa da maldade que a casa de Israel e a casa de Judá têm cometido — eles têm provocado a Minha ira, entregando ofertas a Baal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Yahweh me fez conhecer estas coisas, então, as conheci. Tu, Yahweh, me fizeste ver as ações deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Eu estava como um cordeiro manso indo para um abatedouro. Eu não sabia que eles tinham feito planos contra mim: \"Vamos destruir a árvore com os seus frutos! Vamos cortá-la da terra dos viventes; assim, o nome dela não será mais lembrado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Mas Yahweh dos Exércitos é o Justo Juiz, que examina o coração e a mente. Eu testemunharei Tua vingança contra eles, porque tenho apresentado minha causa a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Portanto, Yahweh diz isto sobre as pessoas de Anatote que estão procurando me matar: \"Eles disseram: \'Tu não deves profetizar em nome de Yahweh, ou morrerás por nossas mãos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Então, Yahweh dos Exércitos diz isto: \'Vê, estou prestes a puni-los. Seus jovens morrerão pela espada; seus filhos e filhas morrerão de fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Nenhum deles sobrará, porque Eu estou trazendo uma calamidade contra as pessoas de Anatote, o ano da sua punição.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Tu és justo, Yahweh, sempre que eu trago contendas a Ti. Devo, certamente, contar a Ti minha razão de reclamar: Por que o caminho dos pecadores tem sucesso? Todas as pessoas sem fé são bem sucedidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Tu os plantaste e eles criaram raízes. Eles continuam a produzir frutos. Tu estás perto da boca deles, mas bem longe de seus corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'No entanto, Tu me conheces, Yahweh. Tu tens me visto e examinaste o meu coração para Contigo. Leva-os embora como ovelhas para o abate, e os separa para o dia do abate!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Por quanto tempo a terra continuará secando e as plantas de todos os campos murchando? Por causa da maldade de seus habitantes, animais selvagens e pássaros desapareceram. De fato, as pessoas falam: \"Deus não sabe o que irá acontecer conosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Yahweh disse: \"De fato, se tu, Jeremias, te cansaste correndo com os homens, como poderás competir com os cavalos? Se tu caíste no campo seguro, como farás na floresta ao longo do Jordão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Porque até teus irmãos e a família do teu pai têm te traído e te denunciado em voz alta. Não confies neles, mesmo que te digam coisas boas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Eu abandonei a Minha casa; eu rejeitei a Minha herança. Eu dei Meu próprio povo amado nas mãos dos seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Minha herança se tornou para Mim como leão na floresta; ela levantou sua voz contra Mim, então, Eu a odeio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Não se tornou o Meu bem precioso como uma ave de rapina colorida, atrás da qual outras aves, abutres, perseguem por toda parte? Vai e traze todos os animais selvagens para devorá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Muitos pastores têm destruído Meu vinhedo. Eles têm destruído Minha porção de terra; eles tornaram Minha agradável porção em um deserto, uma desolação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Eles fizeram dela uma desolação. Eu lamento por ela, pois está devastada. Toda a terra se tornou desolada, pois não há quem se importe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Destruidores vieram contra todos os lugares do deserto, porque a espada de Yahweh devora de uma ponta à outra da terra. Não há nenhuma segurança na terra para qualquer criatura viva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Eles semearam trigo, mas colheram arbustos espinhosos. Eles estão cansados de trabalhar e não ganhar nada. Então, humilhados sejam vossos ganhos, por causa da ira de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Yahweh diz isso contra todos os Meus vizinhos, os iníquos que atacam a posse que Eu fiz Meu povo Israel herdar: \"Vede, Eu sou aquele que vos arranca da própria terra, e irá arrancar a casa de Judá dentre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Então, depois de arrancar aquelas nações, irá acontecer que Eu terei compaixão deles e irei trazê-los de volta, cada um à sua herança e à sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Acontecerá que, se essas nações, cuidadosamente, aprenderem o caminho do Meu povo, para jurar sobre Meu nome: \'Yahweh vive\', assim como eles têm ensinado o Meu povo a jurar por Baal, então, serão estabelecidos no meio do Meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Mas se alguém não ouvir, irei arrancar aquela nação. Certamente, será arrancada e destruída\" — essa é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Yahweh disse a mim: \"Vai e compra um cinto de linho e põe-no sobre os teus lombos, mas não o coloques na água\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Então, eu comprei um cinto, como Yahweh havia ordenado, e pus sobre os meus lombos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Então, a palavra de Yahweh veio a mim pela segunda vez e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, '\"Pega o cinto que compraste, que está sobre teus lombos, levanta-te e viaja para o Eufrates. Esconde-o na fenda de uma rocha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Então, fui e o escondi no Eufrates, assim como Yahweh me havia ordenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Após muitos dias, Yahweh disse a mim: \"Levanta-te e volta ao Eufrates, retira de lá o cinto que Eu lhe disse para esconder\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Então, voltei ao Eufrates e tirei o cinto de onde o havia escondido. Eis que o cinto estava apodrecido, não servia para nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Então, a palavra de Yahweh veio a mim de novo e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, '\"Assim diz Yahweh: Da mesma maneira, Eu destruirei a grande arrogância de Judá e Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Este povo perverso que recusa a ouvir a Minha palavra, que caminha na dureza de seus corações, que vai atrás de outros deuses para adorá-los e se curvar diante deles, eles serão como esse cinto que não serve para nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Assim como o cinto se apega aos lombos do homem, Eu tenho feito toda a casa de Israel e toda a casa de Judá se apegar a Mim, para serem Meu povo, para Me darem louvor e honra. Mas eles não quiseram Me ouvir — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Assim, tu deves dizer esta palavra a eles: \'Yahweh, o Deus de Israel, diz assim: \"Todo jarro se encherá de vinho\". Eles te dirão: \"Não sabemos, de fato, que todo jarro se encherá de vinho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Então, dize-lhes: Assim diz Yahweh: Vede, Eu encherei com embriaguez cada habitante desta terra, os reis que assentaram no trono de Davi, os sacerdotes, profetas e todos os habitantes de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Então, Eu mesmo colocarei uns contra os outros, tanto os pais quanto os filhos. Não terei pena ou compaixão deles e não os pouparei da destruição — esta é a declaração de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Ouvi e prestai atenção. Não sejais arrogantes, pois Yahweh tem dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Dai honra a Yahweh, vosso Deus, antes que Ele traga escuridão e faça vossos pés tropeçarem nas montanhas, ao anoitecer. Pois estais esperando por luz, mas Ele transformará o lugar em escuridão profunda, em uma nuvem escura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Portanto, se não ouvirdes, chorareis em segredo por causa de vossa arrogância. Meus olhos, certamente, chorarão e derramarão lágrimas, pois o rebanho de Yahweh foi levado cativo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, '\"Diz ao rei e à rainha mãe: \'Humilhai-vos e assentai-vos, pois as coroas de vossas cabeças, vosso orgulho e glória, cairão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'As cidades do Neguebe serão fechadas, e não terá ninguém para abri-las. Judá será levada cativa, totalmente em exílio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Levantai vossos olhos e olhai os que vêm do norte. Onde está o rebanho que foi dado a vós, o rebanho que era tão belo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Que dirás quando Deus colocar sobre vós aqueles a quem educastes para serem vossos amigos? Não será este o início das dores que vos acometereis, assim como uma mulher que está em trabalho de parto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Então, podereis dizer em vosso coração: \'Por que estas coisas estão acontecendo conosco?\' Por causa da multidão de vossas iniquidades é que vossas saias estão levantadas e fostes violentadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Podem as pessoas da Etiópia mudarem sua cor da pele, ou o leopardo mudar suas pintas? Assim também vós, acostumados com a maldade, serão capazes de fazer o bem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Então, Eu os espalharei como a palha levada pelo vento do deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Isto é o que tenho vos dado, a porção que determinei para vós, porque tendes Me esquecido e confiado em mentiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Portanto, Eu mesmo arrancarei as vossas saias e vossas partes íntimas serão vistas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Vossos adultérios e relinchos, a infâmia da vossa prostituicão sobre as colinas e nos campos. Eu tenho visto essas coisas abomináveis! Ai de ti, Jerusalém! Até quando ainda não te purificarás?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Essa é a palavra de Yahweh que veio a Jeremias a respeito da seca:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, '\"Judá lamenta e suas portas estão enfraquecidas. Eles estão lamentando sentados no chão. Seu choro por Jerusalem está subindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Os poderosos enviam seus servos em busca de água. Quando vão até as trincheiras, não encontram água. Todos eles retornam sem sucesso; envergonhados e frustrados, cobrem suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Por não haver chuva, a terra está rachada. Os lavradores estão envergonhados e cobrem suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Até a corça deixa seus filhotes nos campos e os abandona, pois não há erva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Os burros selvagens ficam nas planícies lisas e farejam no vento, como chacais. Seus olhos desfalecem porque não há vegetação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Mesmo que nossas iniquidades testemunhem contra nós, Yahweh, age por causa do Teu nome. Nossas ações infiéis aumentaram; nós temos pecado contra Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Ó esperança de Israel, quem o salvou no tempo da angústia. Por que serás como um estrangeiro na terra, como um viajante estrangeiro que vem e passa apenas uma noite?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Por que serás como um homem confuso, como um guerreiro que não é capaz de resgatar ninguém? Pois Tu estás em nosso meio, Yahweh! Teu nome foi proclamado sobre nós. Não nos abandone.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Yahweh disse sobre este povo: \"Uma vez que eles amam vaguear, eles não têm impedido seus pés de fazê-lo\". Yahweh não Se agrada deles. Agora, Ele Se lembrará de suas iniquidades e punirá os seus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Yahweh disse a mim: \"Não ore pelo bem desse povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Quando jejuarem, não ouvirei sua lamentação e, se eles oferecerem holocausto e ofertas de alimento, não terei prazer neles. Vou destruí-los pela espada, pelo fome e pela praga\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Então eu disse: \"Oh, Senhor Yahweh! Eis que os profetas estão dizendo ao povo: \'Vós não vereis a espada, não haverá fome para vós, pois eu lhes darei a verdadeira segurança neste lugar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Yahweh disse a mim: \"Os profetas profetizaram mentiras em Meu nome. Eu não os enviei, nem lhes dei ordem alguma ou falei com eles. Eles vos profetizam falsas visões, adivinhações, doutrinas inúteis e o engano de suas próprias mentes e corações!”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Portanto, Yahweh disse: \"Sobre os profetas que estão profetizando em Meu nome, sem que Eu os tenha enviado, aqueles que dizem que não haverá espada e nem fome nesta terra, estes profetas irão perecer por espada e fome;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'e o povo a quem eles profetizaram serão jogados nas ruas de Jerusalém por conta da fome e da espada, pois não haverá ninguém para enterrá-los, nem eles, nem suas esposas, seus filhos e suas filhas; porque eu derramarei sobre eles sua própria iniquidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Diga esta palavra a eles: \'Deixai que meus olhos fluam em lágrimas, noite e dia. Que elas não cessem, pois haverá um grande colapso da filha virgem do Meu povo; uma profunda e incurável ferida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Se Eu sair pelos campos, verei aqueles que foram mortos pela espada. E se eu for à cidade, verei aqueles que estão doentes de fome. O profeta e o sacerdote vagueiam sobre a terra, mas não sabem para onde vão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Tu rejeitaste Judá completamente? Tu odeias Sião? Por que nos aflige quando não há cura para nós? Nós esperamos por paz, mas não há nada bom; por um tempo de cura, mas vê, há apenas terror.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Nós admitimos, Yahweh, nossas ofensas, e a iniquidade de nossos antepassados, pois temos pecado contra Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Não nos rejeites! Por causa do Teu nome, não faças do Teu glorioso trono uma desgraça. Lembra-Te daTua aliança conosco e não a anules.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Há entre os ídolos de outras nações, alguém que possa fazer cair chuva dos céus? Tu não és o único, Yahweh nosso Deus, quem o fazes? Nossa esperança está em Ti, pois Tu fazes todas estas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Então, Yahweh me disse: \"Ainda que Moisés e Samuel estivessem diante de Mim, ainda assim Eu não seria favorável a este povo. Manda-os para longe de Mim. Que eles saiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'E acontecerá que eles te dirão: \'Para onde iremos?\' Então, tu lhes dirás: \'Yahweh disse: Aqueles destinados à morte devem ir para a morte; aqueles destinados à espada devem ir para a espada. Aqueles destinados à fome devem ir para a fome; e aqueles destinados ao cativeiro devem ir para o cativeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Porque Eu os punirei com quatro grupos: espada para abater, cães para dilarecerar, pássaros dos céus e bestas da terra para consumir e destruir — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Eu farei deles um espetáculo terrível para todos os reinos da terra, por causa de tudo que Manassés, filho de Ezequias, rei de Judá, fez em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Quem terá compaixão de ti, Jerusalém? Quem chorará por ti? Quem voltará a perguntar sobre teu bem estar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Tu Me abandonaste — esta é a declaração de Yahweh — tu Me deste as costas. Então, Eu te golpearei com Minha mão e te destruirei. Eu estou cansado de ter compaixão de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Então, Eu os espalharei com uma pá nos portões da terra. Eu os despojarei de seus filhos. Eu destruirei Meu povo, pois eles não deixaram os seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Eu farei o número das suas viúvas maior do que a areia das praias. Contra as mães dos jovens, Eu mandarei o destruidor ao meio-dia; trarei angústia e terror repentinamente sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'A mãe que deu à luz sete filhos enfraquecerá; ela suspirará, seu sol se escurecerá enquanto ainda é dia. Ela será envergonhada e confundida, pois Eu darei à espada aqueles que lhe restarem na presença dos seus inimigos — esta é a declaração de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Ai de mim, minha mãe! Porque tu me deste à luz? Pois sou um homem de contendas e discussões diante de toda a terra. Eu não emprestei e nem tomei emprestado de ninguém, mas todos eles me amaldiçoam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Yahweh disse: \"Eu não te resgataria para o bem? Eu, certamente, farei os teus inimigos te implorarem por socorro, no tempo da calamidade e da angústia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Pode alguém esmagar o ferro? Especialmente o ferro do norte que é misturado com bronze?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Aos teus inimigos Eu darei, livremente como despojo, tua riqueza e teus tesouros. Eu farei isto por causa de todos os teus pecados cometidos dentro de tuas fronteiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Então, Eu farei com que tu sirvas teus inimigos em uma terra que não conheces, porque um fogo se acenderá, arderá na Minha ira contra ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Yahweh, Tu sabes! Lembra-Te de mim e socorre-me. Traz vingança para mim contra os meus perseguidores. Na Tua longanimidade, não permitas que me levem embora; sabes que sofro acusações por Tua causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Encontrei Tuas palavras e as consumi. Tuas palavras tornaram-se uma alegria para mim e delícia para o meu coração, pois, sou chamado pelo Teu nome, ó Yahweh, Deus dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Não me assentei na roda daqueles que celebram e regozijam. Eu me sentei sozinho por causa da Tua mão poderosa, porque Tu me encheste de indignação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Por que é contínua a minha dor e minha ferida incurável, e se recusa a ser curada? Tu serás para mim como águas enganosas, águas que secam?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Portanto, assim disse Yahweh: \"Se te arrependeres, Jeremias, Eu te restaurarei e te colocarei de pé diante de Mim e tu Me servirás. Se tu separares as coisas tolas das coisas preciosas, serás Minha boca. O povo voltará a ti, mas tu mesmo não retornarás a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Eu farei de ti como um muro de bronze impenetrável para este povo, e eles farão guerra contra ti. Mas eles não te derrotarão porque Eu Sou contigo para te salvar e te resgatar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Eu te salvarei das mãos dos ímpios e te resgatarei da mão dos tiranos — esta é a declaração de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, '\"Não tomes uma esposa para ti e não tenhas filhos ou filhas neste lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Porque assim diz Yahweh a respeito dos filhos e filhas que nascem neste lugar, para as mães que dão à luz a eles e para os pais que geraram nesta terra:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, '\'Eles morrerão de enfermidades terríveis, não serão lamentados ou enterrados, serão como esterco no chão. Eles morrerão por espada e fome, e seus corpos serão alimento para os pássaros dos céus e para as feras da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Assim diz Yahweh: \"Não entres em nenhuma casa que esteja em luto; não lamentes e não se compadeça deles. Pois Eu levei para longe dessas pessoas a Minha paz, Meu amor leal e a Minha misericórdia! — Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Ambos, grandes e pequenos, morrerão nesta terra. Eles não serão enterrados, nem serão lamentados por ninguém; não cortarão a si mesmos e nem rasparão as suas cabeças por eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Ninguém deve compartilhar alimento com os que estiverem pranteando para confortá-los por causa dos mortos e, ninguém deve dar de beber o cálice de consolação pela morte de seu pai ou mãe, a fim de confortá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Tu não entrarás numa casa de banquete para sentar-se com eles, para comer e beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Pois, Yahweh dos Exércitos, Deus de Israel, disse isto: Vede, diante de vossos olhos, em vossos dias e neste lugar, Eu farei cessar o som de alegria e celebração, e também a voz do noivo e da noiva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Então, acontecerá que tu falarás todas estas palavras para esse povo, e eles te dirão: \'Por que Yahweh decretou esse grande mal contra nós? Qual é a nossa iniquidade? Qual é nossa iniquidade e pecado contra Yahweh nosso Deus?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Então, responde-lhes: \'É porque vossos ancestrais Me abandonaram!\' — Esta é a declaração de Yahweh. \'Eles foram atrás de outros deuses e os adoraram, e curvaram-se diante deles; eles Me abandonaram e não guardaram a Minha lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Todavia, vós mesmos fizestes mais maldades do que vossos ancestrais, cada pessoa está caminhando pela obstinação do seu coração perverso; não há ninguém que Me escute.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Portanto, Eu vos tirarei desta terra para uma terra que não conheceis, nem vós, nem vossos ancestrais; e vós adorareis os deuses de lá, dia e noite, e não vos darei nenhum favor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Vede! Os dias estão chegando — esta é a declaração de Yahweh — quando não mais se dirá: \'Tão certo como vive Yahweh, Aquele que trouxe o povo de Israel da terra de Egito\';');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'mas, \'tão certo como vive Yahweh, Aquele que livrou o povo de Israel da terra do norte e das terras por onde Ele os espalhou!\' Eu vos trarei de volta à terra que dei aos vossos ancestrais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Vede! Eu enviarei muitos pescadores — esta é a declaração de Yahweh — e eles pescarão o povo. Depois disso, Eu enviarei muitos caçadores, e eles vos caçarão em todas as montanhas, morros e fendas de rochas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Porque Meus olhos estão sobre todos os vossos caminhos; não podereis esconder-vos de Mim; vossa iniquidade não será oculta diante dos Meus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Primeiramente, Eu vos retribuirei em dobro por vossa iniquidade e pecado, por contaminar a Minha terra com vossas imagens detestáveis, e por encherem minha herança com vossos ídolos abomináveis.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Yahweh, Tu és minha fortaleza e meu refúgio, meu lugar seguro no dia da angústia. As nações virão a Ti dos confins da terra e dirão: \'Certamente, os nossos ancestrais herdaram mentira, vaidade e coisas que não servem para nada\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, '\"O povo faz para si deuses que, na verdade, não são deuses?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Portanto, vede! Eu farei com que eles, nesse tempo, conheçam a Minha mão e o Meu poder; então, eles saberão que Yahweh é Meu nome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, '\"O pecado de Judá está escrito com um ponteiro de ferro, com uma ponta de diamante; está gravado nas tábuas de seus corações e nas pontas de seus altares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Seus filhos lembram-se dos altares e dos postes ídolos, junto às árvores verdejantes nos altos montes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Os postes ídolos estão na Minha montanha e nas campinas. Tua riqueza e todo o teu tesouro, darei como despojo, juntamente com teus lugares altos, por causa do teu pecado cometido em todos os teus territórios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Tu perderás a herança que te dei. Farei com que teus inimigos te levem como escravo para uma terra que não conheces, pois acendeste o fogo da Minha ira, o qual queimará eternamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Disse Yahweh: \"Maldito é o homem que confia no homem, faz da carne sua força e desvia o coração para longe de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Ele será como um pequeno arbusto no deserto, e não perceberá quando vier o bem. Ele ficará nos lugares pedregosos do deserto, em terras estéreis e desabitadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Mas bendito é o homem que confia em Yahweh, cuja esperança é Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Ele será como uma árvore plantada ao lado das águas, que estende suas raízes ao longo de um riacho; não temerá quando o calor vier, porque suas folhas estarão sempre verdes; Não temerá o ano da seca, nem cessará de produzir frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'O coração humano é mais enganoso do que qualquer outra coisa, e é perverso; quem pode conhecê-lo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Eu sou Yahweh, o único que sonda a mente, que prova os corações, a fim de dar a cada um de acordo com os seus caminhos, de acordo com os frutos de suas ações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Como uma perdiz que choca um ovo que ela não pôs, assim é alguém que enriquece desonestamente; mas quando estiver bem, na metade de sua vida, suas riquezas o abandonarão e, no fim, será um tolo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'O lugar de nosso santuário é um trono de glória, exaltado desde o princípio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Yahweh é a esperança de Israel. Todos que Te abandonam serão envergonhados. Aqueles na terra que deixarem a Ti, serão escritos no pó. Porque eles estão abandonando Yahweh, a Fonte das águas vivas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Cura-me, Yahweh, e ficarei curado! Salva-me, e serei salvo. Porque Tu és meu cântico de louvor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Vê, eles dizem para mim: \'Onde está a palavra de Yahweh? Que venha!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Quanto a mim, eu não fugi de ser um pastor seguindo-Te. Eu não desejei pelo dia da calamidade. Tu sabes as proclamações que vieram de meus lábios; elas foram feitas em Tua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Não sejas um terror para mim; Tu és meu refúgio no dia da calamidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Que meus perseguidores sejam envergonhados, mas não me deixes ser envergonhado. Que eles sejam desanimados, mas não me deixes desanimar. Envia o dia da calamidade contra eles e despedaça-os com uma destruição dobrada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Yahweh me disse isto: \"Vai e põe-te em pé no portão do povo, onde os reis de Judá entram e saem, e em todos os outros portões de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Dize-lhes: \'Ouvi as palavras de Yahweh, reis de Judá e todo o povo de Judá, e todos os moradores de Jerusalém que passam por estes portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Assim diz Yahweh: \"Sede cuidadosos pelo amor de vossas vidas e não carregueis carga no dia de sábado, nem as leveis até os portões de Jerusalém,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'nem as tireis de vossas casas no dia de sábado. Não façais nenhum trabalho, mas consagrai o sábado para Yahweh, assim como Eu ordenei que vossos ancestrais fizessem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Eles não deram ouvidos nem prestaram atenção; antes, endureceram a cerviz, não Me ouvindo, nem aceitando a disciplina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Acontecerá que, se vós realmente me ouvirdes — esta é declaração de Yahweh — e não trouxerdes carga para os portões desta cidade no dia de sábado, mas, ao invés disso, consagrardes o dia de sábado a Yahweh e não fizeres qualquer trabalho nele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'então, os reis, príncipes e aqueles que se assentarem no trono de Davi, virão para os portões desta cidade, nas carruagens com seus cavalos, eles e seus líderes, homens de Judá e moradores de Jerusalém, e esta cidade será habitada eternamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Eles virão das cidades de Judá, de todos arredores os de Jerusalém, das terras de Benjamim e das planícies, das montanhas e do Neguev e queimarão holocaustos, sacrifícios, oferta de cereais e incenso, e ofertas de gratidão à Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Mas, se não Me ouvirdes para consagrar o dia de sábado a Yahweh, e levardes vossas cargas, e entrardes nos portões de Jerusalém no dia de sábado, então, Eu queimarei seus portões, um fogo consumirá as fortalezas de Jerusalém, e não será apagado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Esta é a palavra de Yahweh que veio a Jeremias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, '“Levanta-te e vai à casa do oleiro, pois lá te farei ouvir Minha palavra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Então, fui para a casa do oleiro e eis que ele estava trabalhando em sua roda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Mas o vaso de barro que ele estava moldando se estragou em suas mãos; então, ele mudou de ideia e fez outro vaso, que pareceu bom aos seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'E a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, '\"Não poderia Eu agir contigo, ó casa de Israel, da mesma maneira que o oleiro? – Esta é a declaração de Yahweh. Vede! Como o barro na mão do oleiro, assim sois vós na Minha mão, ó casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Em um momento, Eu posso proclamar algo sobre uma nação ou reino que irei arrancar, derrubar ou destruir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Mas se a nação sobre a qual Eu fizer essa proclamação se converter de seu mal, então, Eu Me arrependerei da calamidade que planejava trazer sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Em outro momento, Eu posso proclamar algo sobre uma nação ou reino que irei edificar ou plantar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Mas, se eles fizerem mal diante dos Meus olhos, por não ouvirem a Minha voz, então, Eu não mais farei o bem que havia dito que lhes faria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Então, agora, fala aos homens de Judá e aos moradores de Jerusalém dizendo: \'Assim diz Yahweh: Vede, Eu estou planejando uma calamidade contra vós. Arrependei-vos, cada um, do seu mau caminho, para que vossos caminhos e práticas vos tragam coisas boas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Mas eles dirão: \'Não há esperança. Agiremos de acordo com os nossos próprios planos, de acordo com o que deseja cada coração perverso e teimoso\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Portanto, assim diz Yahweh: \'Perguntai às nações: quem, alguma vez, ouviu tal coisa? A virgem de Israel cometeu um ato terrível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Por acaso, a neve do Líbano desaparece nas encostas dos montes rochosos? Por acaso, os riachos das montanhas, que vêm de longe, perdem suas águas frias?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Contudo, Meu povo se esqueceu de Mim. Eles têm dado ofertas a ídolos falsos, que os fizeram tropeçar em seus caminhos; eles deixaram os caminhos antigos para andar em atalhos não aplainados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Suas terras se tornarão um terror, um objeto de eterno desprezo. Todos os que passarem por ela irão estremecer e balançar suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Eu os dispersarei diante de seus inimigos como o vento oriental. Eu lhes mostrarei minhas costas e não minha face, no dia da sua calamidade.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Então, o povo disse: \"Vinde e façamos planos contra Jeremias, uma vez que a lei dos sacerdotes, ou o conselho dos sábios, ou as palavras dos profetas, nunca se acabarão. Vinde e o ataquemos com nossas palavras e não prestemos atenção em nada do que ele proclamar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Atenta para mim, Yahweh, e escuta a voz de meus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Será que a sua calamidade, realmente, será minha recompensa por ser bondoso para com eles? Pois eles cavaram uma cova para mim. Lembra-Te como me levantei diante de Ti para falar em favor deles e fazer Tua fúria se desviar deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Portanto, entrega seus filhos à fome e lhes entrega ao poder da espada. Que suas mulheres fiquem sem os filhos e se tornem viúvas; que seus homens e seus jovens sejam mortos pela espada na batalha;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'que um grito de angústia seja ouvido de suas casas, quando, de repente, trouxeres invasores contra eles. Pois cavaram uma cova para me capturar e esconderam armadilhas para meus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Mas Tu, Yahweh, conheces todos os seus planos para me matar. Não perdoes suas iniquidades e pecados; não apagues seus pecados diante de Ti. Em vez disso, que eles sejam derrotados diante de Ti. Age contra eles no tempo da Tua ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Disse Yahweh: \"Vá e compra uma botija de barro do oleiro, e leva contigo os anciãos do povo e os sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Então, vá até o vale de Ben-Hinom que está à entrada do portão dos Cacos e lá proclama as palavras que Eu te direi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Assim dirás: \'Ouvi a palavra de Yahweh, reis de Judá e moradores de Jerusalém! Assim diz Yahweh dos Exércitos, o Deus de Israel: Eis que Eu estou para trazer calamidade sobre este lugar, e os ouvidos de todos que ouvirem sobre isso irão formigar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Eu farei isso porque eles têm Me abandonado e profanaram este lugar. Neste lugar, eles ofereceram sacrifícios para deuses que nunca conheceram. Eles e seus ancestrais e os reis de Judá também têm enchido este lugar com sangue inocente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'Eles construíram os lugares altos de Baal para queimarem seus filhos como um holocausto, algo que Eu nunca mandei, nem falei e nem me passou pela cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Portanto, eis que os dias estão chegando – isto é uma declaração de Yahweh – quando este lugar não será mais chamado de Tofete, nem o vale de Ben-Hinom, mas será vale da Matança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Neste lugar, frustrarei os planos de Judá e Jerusalém; Eu os farei cair pela espada diante de seus inimigos e pela mão dos que procuram tirar-lhes a vida. Então, darei seus cadáveres como comida para os pássaros dos céus e para as feras da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'E farei desta cidade uma ruína e um objeto de desprezo; todo aquele que passar por ela se espantará e zombará por causa de todas as suas pragas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'E os farei comer a carne dos seus filhos e filhas, cada homem consumirá a carne do seu próximo, no cerco e na angústia provocados pelos seus inimigos, por aqueles que querem tirar-lhes a vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Então, quebrarás a botija na presença dos homens que foram contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Tu dirás a eles: \'Assim diz Yahweh dos Exércitos: Eu farei a mesma coisa com este povo e com esta cidade – esta é a declaração de Yahweh – assim como Jeremias despedaçou a botija de barro, de modo que ela não possa ser reparada novamente, o povo enterrará os mortos em Tofete, até que não haja mais lugar para enterrá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Isto é o que farei com este lugar e com os seus moradores; esta cidade será como Tofete – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'As casas de Jerusalém e dos reis de Judá serão imundas como Tofete, assim como todas as casas daqueles que, nos terraços, adoram todas as estrelas dos céus e oferecem ofertas de bebida a outros deuses.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Então, Jeremias regressou de Tofete, lugar para onde Yahweh o havia enviado para profetizar. Pondo-se em pé no pátio da Casa de Yahweh, disse a todo o povo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, '\"Assim diz Yahweh dos Exércitos, Deus de Israel: Eis que, trarei sobre esta cidade e sobre todas as cidades, toda a calamidade que proclamei contra ela, pois endureceram seus pescoços e se recusaram a ouvir as minhas Palavras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Pasur, filho de Imer, o mais alto sacerdote da Casa de Yahweh, ouviu Jeremias profetizando essas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Então, Pasur açoitou Jeremias, o profeta, e colocou-o no tronco que estava no portão superior de Benjamim, na Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'E aconteceu que, no dia seguinte, Passur tirou Jeremias do tronco. Então, Jeremias lhe disse: \"Yahweh não o chama mais Pasur, mas tu és Magor-Missabibe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Porque assim diz Yahweh: \'Eis que farei de ti um objeto de terror para ti e para todos os teus amigos; pois eles cairão pela espada de seus inimigos e teus olhos verão isso. Entregarei todo o Judá nas mãos do rei da Babilônia. Ele os levará cativos à Babilônia ou os matará à espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Eu entregarei toda a riqueza dessa cidade e todo o fruto do seu trabalho, tudo o que há de precioso e todos os tesouros dos reis de Judá. Tudo isso colocarei nas mãos de teus inimigos, eles te saquearão e tudo levarão para a Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Mas tu, Pasur, e todos os moradores de tua casa ireis para o cativeiro. Tu irás para a Babilônia e ali morrerás. Tu e todos os teus amigos, para quem profetizastes falsamente, serão enterrados ali.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, '\"Tu me enganaste, ó Yahweh, e enganado fiquei. Tu foste mais forte do que eu e prevaleceste. Tornei-me motivo de riso o dia inteiro; todos zombam de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Pois sempre que eu falo, grito e proclamo: \'Violência e destruição\', a palavra de Yahweh tem-se tornado para mim reprovação e zombaria, todos os dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Quando eu disse: \'Eu não me lembrarei mais de Yahweh, e não falarei mais o Seu nome\', meu coração se tornou como o fogo, retido em meus ossos. Eu tenho me esforçado para contê-lo, mas não consigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Eu ouço rumores de terror vindo de muitas pessoas, por todos os lados: \'Denunciai! Nós devemos denunciá-lo!\' Aqueles que estão próximos me observam, esperando a minha queda: \'Talvez ele possa ser enganado. Se assim for, poderemos dominá-lo e e nos vingarmos dele\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Mas Yahweh está comigo, como um poderoso guerreiro; por isso, os meus perseguidores serão confundidos. Eles não me derrotarão e ficarão muito envergonhados porque não tiveram sucesso. Eles sofrerão uma vergonha interminável, que nunca será esquecida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Mas Tu, Yahweh dos Exércitos, Tu que examinas os justos e vês os pensamentos e o coração, deixa-me ver Tua vingança sobre eles, pois apresentei a minha causa a Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Cantai a Yahweh! Louvai a Yahweh! Porque Ele tem resgatado as vidas dos que são oprimidos pelas mãos dos malfeitores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Maldito o dia em que nasci. Não seja bendito o dia em que minha mãe me deu à luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Que seja amaldiçoado o homem que contou a meu pai, dizendo: \'Um menino te nasceu\', trazendo grande alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Que esse homem seja como as cidades que Yahweh derrubou, quando Ele não tinha misericórdia. E ouça ele um clamor de ajuda ao amanhecer e um grito de guerra ao meio-dia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'porque Yahweh não me matou no ventre ou fez de minha mãe minha sepultura. Quem dera ela ficasse grávida eternamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Por que eu saí do ventre de minha mãe? Para ver sofrimentos e aflições, para que meus dias fossem cheios de vergonha?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Esta é a palavra que veio de Yahweh para Jeremias, quando o rei Zedequias enviou Pasur, filho de Malquias, e o sacerdote Sofonias, filho de Maaseias, que lhe disseram:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, '\"Procura o conselho de Yahweh a nosso favor, pois Nabucodonosor, rei da Babilônia, está levantando guerra contra nós. Talvez Yahweh realize milagres por nós, como no passado, e faça com que ele se afaste de nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Então, Jeremias lhes disse: \"Isto é o que deves dizer a Zedequias:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, '\'Yahweh, Deus de Israel, diz: Vede, estou prestes a voltar contra vós os instrumentos de guerra que estão em vossas mãos, com os quais estais lutando contra o rei da Babilônia e os caldeus que vos estão cercando do outro lado dos muros! Eu os reunirei no meio desta cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Então, Eu mesmo lutarei contra vós, com a mão erguida e o braço forte e com indignação, fúria e grande ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Pois Eu atacarei os habitantes desta cidade, tanto homens como animais, e eles morrerão com uma praga severa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Depois disso – esta é a declaração de Yahweh – Zedequias, rei de Judá, seus servos, o povo, e qualquer remanescente nesta cidade depois da praga, da espada e da fome, Eu entregarei todos nas mãos de Nabucodonosor, rei da Babilônia, de seus inimigos e daqueles que buscam tirar-lhes a vida. Então, ele os matará ao fio da espada. Ele não terá piedade, não os poupará ou terá compaixão.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Então, para este povo devereis dizer: \'Assim diz Yahweh: Vede, Eu estou prestes a colocar diante de vós o caminho da vida e o caminho da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Qualquer um que permanecer nesta cidade morrerá pela espada, fome e praga; mas, qualquer um que sair e se ajoelhar diante dos babilônios que vos têm cercado, viverá. Este escapará com vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Pois eu estabeleci minha face contra esta cidade, em ordenança, para trazer desastre e não trazer o bem –esta é a declaração de Yahweh. Ela está sendo entregue nas mãos do rei da Babilônia, e ele a queimará.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Acerca da casa do rei de Judá, escutai a palavra de Yahweh:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, '\'Casa de Davi\', diz Yahweh, \'executa a justiça pela manhã e resgata os que foram roubados pelas mãos do opressor, ou Minha fúria virá como fogo e te queimará, pois não há ninguém que possa apagá-la, por causa da maldade de tuas práticas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Vede, habitantes do vale, planalto rochoso, Eu estou contra vós – esta é a declaração de Yahweh – Eu estou contra qualquer um que está dizendo: \"Quem subirá para nos atacar?\" ou \"Quem entrará em nossas casas?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Eu vos castigarei segundo o fruto de vossas práticas – esta é a declaração de Yahweh – e Eu acenderei nos arvoredos um fogo que consumirá tudo à sua volta.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Assim diz Yahweh: \"Descei à casa do rei de Judá e proclamai ali esta palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'Dizei: \'Rei de Judá, que te assentas no trono de Davi, ouve a palavra de Yahweh. Ouvi também vós, servos do rei, e vós, povo do rei, que passais por estes portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Assim diz Yahweh: \'Exerce a justiça e a retidão e resgata das mãos do opressor todo aquele que é explorado. Não maltrates nenhum estrangeiro, órfão ou viúva em tua terra. Não pratiques a violência, nem derrames sangue inocente neste lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Pois se, verdadeiramente, fizeres o que digo, os reis que se assentam no trono de Davi entrarão pelas portas desta casa em carruagens e cavalos, acompanhados de seus servos e de seu povo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Mas, se não ouvires as Minhas palavras, o que tenho anunciado – esta é a declaração de Yahweh – então, este palácio real se tornará em desolação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Pois assim diz Yahweh acerca do palácio do rei de Judá: \'És para mim como Gileade ou como o alto da montanha do Líbano. Ainda assim, certamente, o transformarei em um deserto, em uma cidade desabitada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Pois preparei destruidores para se levantarem contra ti! Homens com suas armas cortarão teus melhores cedros e os lançarão no fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Então, muitas nações passarão por esta cidade e perguntarão umas às outras: \'Por que Yahweh agiu dessa maneira com esta grande cidade?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Responderão: \'Porque abandonaram a aliança de Yahweh, seu Deus, e se prostraram e adoraram outros deuses.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Não choreis pelo morto, nem lastimeis por ele, mas pranteai por todo aquele que for levado cativo, porque nunca mais retornará, nem verá novamente a terra em que nasceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Pois assim diz Yahweh acerca de Salum, filho de Josias, rei de Judá, que reinou em lugar de Josias, seu pai: \'Ele partiu deste lugar e não mais voltará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Ele morrerá no lugar para onde o levaram cativo e nunca mais verá esta terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Ai daquele que edifica sua casa sem retidão, e seus aposentos com injustiça, que faz seu vizinho trabalhar para ele de graça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Ai daquele que diz: \'Eu construirei para mim uma casa ampla, com cômodos espaçosos\'. Então, abre-lhe largas janelas, cobre-a com cedro, e a pinta de vermelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Por acaso, é ter painéis de cedro que faz com que sejas um bom rei? Não foi teu pai que comeu e bebeu, e mesmo assim agiu com justiça e retidão? Por isso, as coisas iam bem para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Ele julgou em favor do pobre e do necessitado; por isso, as coisas iam bem. Não é isso o que significa me conhecer? – essa é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Mas não tens olhos ou coração para nada, exceto para o teu ganho desonesto e para derramar sangue inocente, para oprimir e esmagar os outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Portanto, assim diz Yahweh acerca de Jeoaquim, filho de Josias, rei de Judá: Não o lamentarão com \'Ai, meu irmão!\' ou \'Ai, minha irmã!\' Nem o lamentarão com \'Ai, senhor!\' ou \'Ai, majestade!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Ele será sepultado como se sepulta um asno, será arrastado e jogado para fora das portas de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Subi aos montes do Líbano e clamai, levantai as vossas vozes em Basã. Clamai desde as montanhas de Abarim, pois todos os vossos amigos serão destruídos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Eis que falei convosco em vossa prosperidade, mas dissestes: \'Não ouviremos\'. Este tem sido o vosso comportamento desde a juventude, não ouvis a Minha voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'O vento apascentará todos os vossos pastores, e vossos amigos irão para o cativeiro. Eis que, certamente, sereis envergonhados e humilhados por todos os vossos atos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Ó tu, que habitas no Líbano, que fazes o teu ninho nos cedros, como terão pena de ti quando te vierem dores e aflições como as de uma mulher em trabalho de parto!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, '\"Como eu vivo!\", diz Yahweh, \"ainda que tu, Joaquim, filho de Jeoaquim, rei de Judá, fosses o anel de selar em minha mão direita, eu te arrancaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Pois te entreguei nas mãos daqueles que procuram tirar tua vida, e daqueles a quem temes: nas mãos de Nabucodonosor, rei da Babilônia, e dos caldeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Eu expulsarei a ti e à tua mãe, que te gerou, para outra terra, diferente da qual nascestes e ali morrereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'À terra para a qual eles desejavam voltar, não mais retornarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'É esse homem, Jeoaquim, um vaso inútil e quebrado? É esse homem um vaso que ninguém deseja? Por que o expulsaram, bem como sua descendência, e os lançaram em uma terra que não conheciam?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Terra, terra, terra! Ouve a palavra de Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Yahweh diz: \'Escreve sobre esse homem, Joaquim: \'ele não terá filhos, não prosperará nos seus dias, e nenhum de seus descendentes alcançará o sucesso ou se sentará novamente no trono de Davi e governará sobre Judá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, '\"Ai dos pastores que destroem e dispersam as ovelhas do Meu pasto – Esta é a declaração de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Por isso, Yahweh, o Deus de Israel, diz a respeito dos pastores que estão pastoreando seu povo: \"Vós estais dispersando Meu rebanho e o afastando. Vós não vos importastes com eles. Eu vos punirei pelo mal de vossas práticas –Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Eu mesmo recolherei o remanescente do Meu rebanho de todas as terras para onde Eu os expulsei e os conduzirei de volta à sua pastagem, onde eles frutificarão e se multiplicarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Então, Eu levantarei pastores sobre eles, que irão pastoreá-los; assim, eles não temerão nem serão aniquilados. Nenhum deles será perdido – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Vede, dias estão chegando quando Eu levantarei Davi, um Ramo Justo. Ele reinará como Rei; Ele agirá com sabedoria e executará justiça e retidão na terra – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Em Seus dias, Judá será resgatada e Israel viverá em segurança. E este é o nome pelo qual Ele será chamado: Yahweh, Nossa Justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Portanto, vede! Dias estão chegando quando eles já não dirão: \'Vive Yahweh, que fez o povo de Israel subir da terra do Egito\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Em vez disso, eles dirão: \"Vive Yahweh, que fez subir e trouxe de volta os descendentes da casa de Israel da terra do norte e de todas as terras onde eles haviam sido expulsos\'. E eles viverão em suas próprias terras\" – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Em relação aos profetas, meu coração está partido, e todos os meus ossos estremecem. Eu me tornei como um homem bêbado, como um homem ao qual o vinho tem dominado, por causa de Yahweh e Suas santas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Pois a terra está cheia de adúlteros. Por causa deles a terra secou. As campinas nos desertos secam. Os caminhos desses profetas são perversos; seu poder não é usado da maneira correta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, '\"Pois ambos, os profetas e os sacerdotes, estão contaminados. Eu encontrei sua perversidade até em Minha casa! – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Portanto, seus caminhos serão como lugares escorregadios na escuridão. Eles serão empurrados e cairão nele. Pois Eu enviarei desgraça sobre eles no ano de seu castigo – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Pois Eu vi os profetas de Samaria fazendo o que é repulsivo: eles profetizaram por Baal e desviaram Meu povo Israel dos caminhos corretos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Entre os profetas em Jerusalém, Eu tenho visto coisas horríveis: eles cometem adultério e andam em engano; eles fortalecem as mãos dos malfeitores; ninguém se converte de sua maldade; todos eles têm-se tornado como Sodoma para Mim, e seus habitantes, como Gomorra!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Portanto, Yahweh dos Exércitos diz isso acerca dos profetas: \"Vede, Eu estou prestes a fazê-los comer erva amarga e beber água envenenada, pois a contaminação tem saído dos profetas de Jerusalém para toda a terra.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Yahweh dos Exércitos diz isto: \"Não deis ouvidos às palavras dos profetas que vos profetizam. Eles têm vos iludido! Eles estão anunciando visões de suas próprias mentes, não da boca de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Eles estão, constantemente, dizendo aos que me desonram: \'Yahweh declara que haverá paz para vós\'. Pois todos os que andam na teimosia de seus próprios corações dizem: \'Desgraças não virão sobre vós\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Quem esteve no conselho de Yahweh? Quem vê e ouve Sua palavra? Quem presta atenção em Sua palavra e a escuta?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Vede! Há uma tempestade vindo de Yahweh! Sua fúria está se movendo, e a tempestade está girando. Ela está girando sobre a cabeça dos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'A ira de Yahweh não retornará até que Ele a tenha executado e trazido à existência as intenções de Seu coração. No fim dos dias, vós compreendereis isto claramente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Eu não enviei esses profetas. Eles apenas apareceram. Eu não proclamei nada a eles, mas eles ainda têm profetizado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Pois se eles tivessem ficado em Meu conselho, eles teriam feito Meu povo ouvir Minha palavra; eles os teriam levado a se arrependerem do seu mau caminho, e da maldade das suas ações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Esta é a declaração de Yahweh – Sou Eu apenas Deus de perto e não também Deus de longe?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Pode alguém se esconder em um lugar secreto de tal modo que Eu não possa vê-lo? – Esta é a declaração de Yahweh – E Não preencho Eu os Céus e a Terra? –Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Eu tenho ouvido o que os profetas dizem, esses que estão profetizando engano em Meu nome. Eles disseram: \'Sonhei! Sonhei!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Por quanto tempo isto permanecerá, profetas que profetizam mentiras de suas mentes, e que profetizam do engano de seu coração?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Eles estão planejando fazer Meu povo se esquecer do Meu nome com os sonhos que eles contam cada um ao seu companheiro; assim como seus antepassados se esqueceram do Meu nome por causa do nome de Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'O profeta que teve um sonho, deixa que conte o sonho. Mas aquele a quem Eu tenho proclamado algo, que declare Minha palavra com verdade. O que tem em comum a palha com o grão? – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'E minha palavra não é como o fogo? Não é como um martelo que despedaça uma rocha? –Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Portanto, vede, Eu estou contra os profetas, contra qualquer um que rouba palavras de outra pessoa e diz que elas vêm de Mim – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Vede! Eu estou contra os profetas, os que usam suas línguas para profetizar decretos – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Vede, Eu estou contra os profetas que sonham enganosamente e proclamam os sonhos e, desta forma, corrompem o Meu povo com engano e vaidade – Esta é a declaração de Yahweh. Eu sou contra eles porque não os enviei nem lhes dei ordens. Então, eles, certamente, não ajudarão esse povo – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Quando esse povo, ou um profeta, ou um sacerdote te perguntar: \'Qual é o fardo de Yahweh?\' Então deverás dizer a eles: \'Tu és o fardo e Eu vou te desamparar\' – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Quanto aos profetas, sacerdotes e ao povo que estão dizendo: \'Este é o fardo de Yahweh\', a estes Eu punirei, a eles e à sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Vós continuareis a dizer, cada um ao seu companheiro, e cada homem ao seu irmão: \'Qual foi a resposta de Yahweh?\' e \'O que Yahweh declarou?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Mas não devereis continuar a falar sobre o \'fardo de Yahweh\', porque o fardo é a palavra própria de cada homem, e vós distorceis as palavras do Deus vivo, Yahweh dos Exércitos, nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Isto é o que tu dirás ao profeta: \'O que Yahweh te respondeu? ou \'O que Yahweh disse?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Mas se disseres: \'O fardo de Yahweh\', assim diz o Senhor: Porque tu disseste estas palavras: \'O fardo de Yahweh\', quando te enviei, dizendo: \'Não dirás: \"O fardo do Senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Por isso, vede! Eu estou prestes a vos levantar e vos arrojarei para longe de Mim, juntamente com a cidade que dei a vós e aos vossos antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'Então, porei sobre vós eterna vergonha e insultos que jamais serão esquecidos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Yahweh mostrou-me duas cestas de figos que estavam diante do templo de Yahweh. (Esta visão aconteceu depois que Nabucodonosor, rei da Babilônia, levou para exílio Joaquim, filho de Jeoaquim, rei de Judá, os oficiais de Judá, o artesão e os ferreiros de Jerusalém e os trouxe à Babilônia).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Uma das cestas de figos era muito boa, como os primeiros figos maduros, mas na outra cesta os figos eram tão ruins que eles não podiam ser comidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Yahweh me disse: \"O que vês, Jeremias?\" Eu respondi: \"Figos. Figos que estão muito bons e figos que estão tão ruins que não podem ser comidos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Então a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, '\"Yahweh, Deus de Israel, diz isto: Eu olharei para os exilados de Judá, para o benefício deles, justamente como estes bons figos, os exilados que mandei para fora deste lugar, para a terra dos babilônios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Eu colocarei neles os Meus olhos para o bem e os restaurarei a esta terra. Eu os edificarei, e não os derrubarei. Eu os plantarei e não os arrancarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Então, Eu lhes darei um coração para Me conhecer, pois Eu sou Yahweh. Eles serão Meu povo e Eu serei seu Deus. Eles se voltarão a Mim com todo o seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Mas como os figos ruins, que estão tão ruins que não podem ser comidos, isso é o que Yahweh diz: \'Eu agirei desta maneira com Zedequias, rei de Judá, com seus oficiais e o resto de Jerusalém que restar nesta terra ou que ficar na terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Eu os transformarei em algo assustador, um desastre à vista de todos os reinos da terra, uma desgraça e assunto para provérbios, provocações e maldições em todos os lugares onde Eu os levar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Eu enviarei a espada, a fome e a praga contra eles, até que sejam destruídos da terra que dei a eles e aos seus antepassados.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Esta é a palavra que veio a Jeremias sobre todo o povo de Judá. Veio no quarto ano de Jeoaquim, filho de Josias, rei de Judá. Este foi o primeiro ano de Nabucodonosor, rei da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'Jeremias, o profeta, proclamou isto a todo o povo de Judá e a todos os habitantes de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Ele disse: \"Por vinte e três anos, desde o décimo terceiro ano de Josias, filho de Amom, rei de Judá até este dia, as palavras de Yahweh têm vindo a mim, e eu as tenho falado continuamente, mas vós não escutastes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Yahweh vos enviou todos os Seus servos, os profetas, de novo e de novo, mas vós não ouvistes nem prestastes atenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Esses profetas disseram: \'Deixai que cada homem volte de seu caminho ímpio e da corrupção de suas práticas e retorne à terra que Yahweh deu, em tempos antigos, a vossos antepassados e a vós, como um presente permanente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Assim, não andeis após outros deuses para adorá-los ou curvarem-se a eles, e não Me provoqueis com a obra de vossas mãos; deste modo, não vos farei mal algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Mas não Me ouvistes e Me provocastes com o trabalho de vossas mãos. Então, Eu os punirei – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Yahweh dos Exércitos diz isto: \'Porque não ouvistes Minhas palavras,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'vede, estou prestes a enviar uma ordem para mandar buscar todas as pessoas do norte, como também Nabucodonosor, Meu servo, rei da Babilônia, e trazê-los contra esta terra e contra seus habitantes, e contra todas as nações ao redor. Pois vou separá-las para destruição. Eu as transformarei em horror, um objeto de zombaria e interminável desolação – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Os sons de alegria e celebração, as vozes do noivo e da noiva, o som das pedras de moinho e da luz das lamparinas, Eu farei todas essas coisas desaparecerem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Depois, toda esta terra se tornará desolação e horror, e estas nações servirão ao rei da Babilônia por setenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Então, acontecerá que, quando os setenta anos se completarem, Eu punirei o rei da Babilônia e aquela nação, a terra dos babilônios, por sua iniquidade, e farei deles uma eterna desolação – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'E executarei contra a terra todas as palavras que falei, tudo o que está escrito neste livro que Jeremias profetizou contra as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Porque também muitas outras nações e grandes reis farão deles escravos. Eu lhes retribuirei por conta de seus atos e pela obra de suas mãos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Pois Yahweh, Deus de Israel, disse a mim: \"Pega esta taça de vinho de fúria de Minhas mãos e faze com que todas as nações às quais estou te mandando bebam-na.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Beberão e tropeçarão, reclamando loucamente diante da espada que estou enviando contra eles.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Então, peguei a taça da mão de Yahweh e fiz com que todas as nações, às quais Yahweh mandou-me, bebessem o vinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jerusalém, as cidades de Judá e seus reis e oficiais, para transformá-los em ruínas e algo terrível, em objetos de zombaria e maldição, assim como o são nos dias atuais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Outras nações também tiveram que beber do vinho: Faraó, rei do Egito, e seus servos; seus oficiais e todo o seu povo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'todo o povo de herança mista e todos os reis da terra de Uz; todos os reis da terra dos filisteus, Asquelom, Gaza, Ecrom e o remanescente de Asdode;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edom, Moabe e os amonitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'Os reis de Tiro e Sidom, os reis das costas do outro lado do mar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedã, Temá e Buz com todos aqueles que cortam os cabelos nos lados de suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'Estes povos também tiveram que beber do vinho: todos os reis da Arábia e todos os reis do povo de herança mista que vivem no deserto;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'todos os reis de Zinri, todos os reis de Elão, e todos os reis da Média;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'todos os reis do norte, aqueles que estão perto e os que estão longe, todos com seus irmãos e todos os reinos do mundo que estão na superfície da terra. Finalmente, o rei da Babilônia beberá o vinho, após todos estes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Yahweh disse a mim: \"Agora, tu precisas dizer a eles: \'Yahweh dos Exércitos, Deus de Israel, diz isto: Bebei e embebedai-vos e vomitai, caí e e não torneis a levantar-vos diante da espada que estou enviando contra vós\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Então, acontecerá que se eles recusarem-se a pegar a taça de tuas mãos e beberem, tu dirás a eles: \'Yahweh dos Exércitos diz isto: Tu, certamente, deves bebê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Pois, vede, estou prestes a trazer desastre na cidade que é chamada pelo Meu nome, e vós deveis ficar livres de punição? Vós não sereis livres, pois eu estou enviando uma espada contra todos os habitantes da terra! – Esta é a declaração de Yahweh dos Exércitos.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Tu deves profetizar a eles todas estas palavras e dizer: \'Yahweh rugirá das alturas e gritará com Sua voz da Sua santa morada, e rugirá poderosamente contra o Seu rebanho; e Ele gritará, como os que pisam as uvas, contra todos os que vivem na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'O barulho da batalha vai ressoar até os confins da terra, pois Yahweh está trazendo acusações contra as nações, e Ele irá trazer juízo à toda carne. Ele entregará os ímpios à espada – Esta é a declaração de Yahweh.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Yahweh dos Exércitos diz isto: \'Vede! O desastre está indo de nação a nação, e uma grande tempestade se levanta dos confins da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Então, naquele dia, aqueles que foram mortos por Yahweh se estenderão de uma extremidade da terra à outra; eles não serão pranteados, recolhidos ou enterrados. Eles serão como esterco no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Lamentai, pastores, e gritai por socorro! Rolai na poeira, vós líderes do rebanho, pois o dia de serdes abatidos chegou. Vós sereis dispersos quando cairdes como um vaso precioso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'O refúgio para os pastores se foi. Não há escapatória para os líderes do rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Ouvi os gritos dos pastores e os lamentos dos líderes do rebanho, porque Yahweh está destruindo os seus pastos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Assim, as pastagens pacíficas serão devastadas por causa da ira feroz de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Como um jovem leão, deixou sua morada, pois a terra deles se tornará um horror por causa da ira do opressor, por causa da ira feroz de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'No começo do reinado de Jeoaquim, filho de Josias, rei de Judá, esta palavra veio de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Assim diz Yahweh: \"Coloca-te de pé no pátio da Minha casa e dize a todas as cidades de Judá, que vêm adorar em Minha casa. Proclama todas as palavras que te ordenei falar a eles. Não omitas nenhuma palavra!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Pode ser que eles escutem e que cada homem abandone seus caminhos maus; então, Eu me compadecerei com relação ao desastre que estou planejando trazer sobre eles, por causa da maldade das suas práticas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Dirás a eles: \'Assim diz Yahweh: Se não Me ouvirdes para andardes de acordo com a Minha lei, que coloquei diante de vós;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'se não ouvirdes as palavras dos Meus servos, os profetas, que Eu envio persistentemente – mas não ouvistes –');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'então, Eu farei a esta casa igual à Siló; tornarei esta cidade em uma maldição perante todas as nações da terra.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Os sacerdotes, os profetas e todo o povo ouviu Jeremias anunciando estas palavras na Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Então, ocorreu que, quando Jeremias terminou de anunciar tudo o que Yahweh o havia mandado dizer a todo o povo, os sacerdotes, os profetas e todo o povo o agarraram e disseram: \"Certamente morrerás!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Por que profetizastes em nome de Yahweh e dissestes que esta casa será como Siló, e esta cidade ficará em ruínas e sem habitantes?\" Todo o povo juntou-se contra Jeremias na Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Ao ouvirem estas palavras, oficiais de Judá subiram da casa do rei para a Casa de Yahweh, e se assentaram à entrada da Porta Nova da Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Os sacerdotes e os profetas falaram aos oficiais e a todo o povo, dizendo: \"É correto que este homem morra, visto que profetizou contra esta cidade, como ouvistes com vossos próprios ouvidos!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Então, Jeremias falou a todos os oficiais e a todo o povo, dizendo: \"Yahweh me mandou para profetizar contra esta casa e esta cidade, para proferir todas as palavras que ouvistes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Portanto, agora, endireitai os vossos caminhos e práticas, e ouvi a voz de Yahweh, vosso Deus, a fim de que Ele se compadeça com relação ao desastre que proclamou contra vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Eu mesmo – olhai para mim! – estou em vossas mãos. Fazei comigo o que é bom e correto aos vossos olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Mas estais plenamente cientes de que se matardes a mim, estareis trazendo sangue inocente sobre vós, esta cidade e seus habitantes, pois, de fato, Yahweh me enviou para proclamar todas estas palavras aos vossos ouvidos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Então, os oficiais e todo o povo falaram aos sacerdotes e profetas: \"Não é correto que este homem morra, pois nos proclamou coisas em nome de Yahweh, nosso Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Logo, alguns homens dentre os anciãos da terra se levantaram e falaram a toda a assembleia do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Eles disseram: \"Miqueias, de Moresete, profetizou nos dias de Ezequias, rei de Judá. Ele falou a todo o povo de Judá, dizendo: \'Assim diz Yahweh dos Exércitos: Sião será lavrada como um campo, Jerusalém se tornará um amontoado de entulho e o monte do templo se tornará uma colina coberta de matagais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Por acaso, Ezequias, rei de Judá, e todo o povo o matou? Por acaso, ele não temia Yahweh e intercedia, clamando que Yahweh tivesse misericórdia? Faremos nós, então, mal maior contra as nossas próprias vidas?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Enquanto isso, havia outro homem profetizando em nome de Yahweh: Urias, filho de Semaías, de Quiriate-Jearim. Ele também profetizou contra essa cidade e essa terra, em concordância com as palavras de Jeremias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Quando o rei Jeoaquim e todos os seus soldados e oficiais ouviram suas palavras, o rei tentou matá-lo, mas, ouvindo isso, Urias afligiu-se e fugiu para o Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'O rei Jeoaquim enviou ao Egito Elnatá, filho de Acbor, e alguns outros homens com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Eles tiraram Urias do Egito e o levaram ao rei Jeoaquim, que o matou à espada, e lançou seu corpo nas sepulturas das pessoas comuns.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Mas Aicã, filho de Safã, protegeu Jeremias, para que não caísse nas mãos do povo e fosse morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'No início do reinado de Zedequias, filho de Josias, rei de Judá, esta palavra veio de Yahweh a Jeremias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Isto é o que Yahweh me disse: \"Faze para ti grilhões e jugos, e coloca-os em teu pescoço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'E manda também grilhões e jugos para o rei de Edom, para o rei de Moabe, para o rei de Amom, para o rei de Tiro e para o rei de Sidom. Envia-os através das mãos dos mensageiros que vieram a Jerusalém ter com Zedequias, rei de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Ordena-lhes que falem aos seus senhores, dizendo: Yahweh dos Exércitos, Deus de Israel, diz: Assim direis aos vossos senhores:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Eu fiz a terra com Meu grande poder e com o Meu braço estendido. Também fiz as pessoas e os animais sobre a terra, e os dou a quem me apraz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'E, agora, entrego todas estas terras nas mãos de Nabucodonosor, rei da Babilônia, meu servo. Também lhe dou os seres vivos dos campos para servi-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Todas as nações servirão a ele, a seu filho e a seus netos até o tempo final de sua terra, quando muitas nações e poderosos reis o subjugarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Se alguma nação e reino não servirem a Nabucodonosor, rei da Babilônia, e não se submeterem ao rei da Babilônia, eu os castigarei com espada, fome e praga — esta é a declaração de Yahweh — até que Eu, pelas suas mãos, a destrua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'E vós, não mais escuteis vossos profetas, vossos adivinhos, vossos videntes, intérpretes de sonhos e feiticeiros que vos falam: \'Não sirvais o rei da Babilônia\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Eles profetizam mentiras a fim de enviar-vos para longe de vossas terras, para que Eu vos expulse e, assim, pereçais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Mas a nação que se submeter ao rei da Babilônia e o servir, permitirei que descansem na sua terra — esta é a declaração de Yahweh — e eles a cultivarão e nela farão moradias.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Então, falei com Zedequias, rei de Judá, e lhe entreguei esta mensagem: \"Submete-te ao jugo do rei da Babilônia, serve a ele e ao seu povo e viverás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Por que morreríeis — tu e teu povo — pela espada, fome e praga, como declarou Yahweh a respeito da nação que se recusar a submeter-se ao rei da Babilônia?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Não deis ouvidos às palavras dos profetas que vos dizem: \'Não sirvais ao rei da Babilônia\', pois eles estão profetizando mentiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Porque não os enviei — esta é a declaração de Yahweh — eles profetizam mentiras em Meu nome, para que Eu vos expulse e pereçais, vós e os profetas que vos profetizam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Proclamei aos sacerdotes e a todo povo dizendo: \"Yahweh diz: não deis ouvidos às palavras de vossos profetas que dizem: \'Vede! Os objetos pertencentes à Casa de Yahweh estão voltando da Babilônia agora!\' Eles vos profetizam mentiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Não lhes deis ouvidos, servi ao rei da Babilônia e vivereis. Por que trazer ruína à cidade?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Se eles são profetas e se, de fato, a palavra de Yahweh está com eles, que intercedam a Yahweh dos Exércitos, para que não sejam levados à Babilônia os objetos que ainda estão em sua casa, na casa do rei de Judá e em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Assim diz Yahweh dos Exércitos sobre as colunas, o tanque, os suportes e o que sobrou dos utensílios nesta cidade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'os quais Nabucodonosor, rei da Babilônia, não tomou quando levou cativo Jeconias, filho de Jeoaquim, rei de Judá, de Jerusalém para a Babilônia com todos os nobres de Judá e de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Yahweh dos Exércitos, Deus de Israel, diz a respeito dos utensílios que permaneceram na Casa de Yahweh, na casa do rei de Judá e em Jerusalém:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, '\'Eles serão trazidos para Babilônia, e ali ficarão até o dia em que Eu determinar — esta é a declaração de Yahweh — então, Eu os trarei e os devolverei a este lugar.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Aconteceu que, no início do reinado de Zedequias, rei de Judá, no quinto mês do quarto ano, o profeta Hananias, filho de Azur, que era de Gibeão, falou-me na Casa de Yahweh, na presença dos sacerdotes e de todo povo, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, '\"Yahweh dos Exércitos, o Deus de Israel, diz isto: Eu tenho quebrado o jugo imposto pelo rei da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Dentro de dois anos, Eu trarei de volta a este lugar todos os utensílios pertencentes à Casa de Yahweh, que Nabucodonosor, rei da Babilônia, levou para Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Então, trarei de volta a este lugar Jeconias, filho de Jeoaquim, rei de Judá, e todos os exilados de Judá que foram levados para Babilônia — esta é a declaração de Yahweh — pois quebrarei o jugo do rei da Babilônia.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Então, Jeremias, o profeta, respondeu ao profeta Hananias, na presença dos sacerdotes e de todo o povo que estava na Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Jeremias, o profeta, disse: \"Que Yahweh faça isto: que Yahweh confirme as palavras que tens profetizado e traga de volta a este lugar os utensílios pertencentes à Casa de Yahweh, e todos os exilados da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Contudo, ouve as palavras que proclamo a ti e a todo o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Os profetas que existiram antes de mim e de ti, desde a antiguidade, também profetizaram sobre muitas nações e contra poderosos reinos, sobre guerras, fome e praga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Então, o profeta que profetizar que haverá paz, se sua palavra se cumprir, saberá que, de fato, ele é um profeta enviado por Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Mas o profeta Hananias pegou o jugo do pescoço de Jeremias, o profeta, e o quebrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Então, Hananias disse na presença do povo: \"Yahweh diz isto: Deste modo, em dois anos, Eu quebrarei o jugo do pescoço de toda a nação, imposto por Nabucodonosor, rei da Babilônia.\" Então, Jeremias, o profeta, seguiu o seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Depois que o profeta Hananias quebrou o jugo do pescoço de Jeremias, o profeta, a palavra de Yahweh veio até Jeremias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, '\"Vai e fala a Hananias: Yahweh diz isto: Tu quebraste um jugo de madeira; porém, Eu farei um jugo de ferro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Pois Yahweh dos Exércitos, Deus de Israel, diz: Eu tenho colocado um jugo de ferro no pescoço de todas as nações para servirem a Nabucodonosor, rei da Babilônia, e elas o servirão. Eu também lhe dei os animais do campo, para que governe sobre eles.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Depois, Jeremias, o profeta, disse ao profeta Hananias: \"Ouve, Hananias! Yahweh não te enviou, mas fizeste este povo acreditar em mentiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Então, Yahweh diz isto: \'Vê que estou te mandando para fora da Terra. Tu morrerás neste ano, porque proclamastes rebelião contra Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'E o profeta Hananias morreu naquele ano, no sétimo mês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Estas são as palavras da carta que Jeremias, o profeta, enviou de Jerusalém para os anciãos remanescentes entre os cativos, aos sacerdotes, aos profetas e a todo o povo que Nabucodonosor exilou de Jerusalém para a Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Isso aconteceu após o rei Jeconias, a rainha mãe, os altos oficiais, os príncipes de Judá e de Jerusalém, os carpinteiros e os ferreiros terem saído de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Ele enviou essa carta pelas mãos de Elasa, filho de Safã, e de Gemarias, filho de Hilquias, os quais Zedequias, rei de Judá, tinha enviado a Nabucodonosor rei da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'A carta dizia: \"Yahweh dos Exércitos, o Deus de Israel, diz a todos os cativos, os quais exilei de Jerusalém para a Babilônia:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, '\'Construí casas e vivei nelas, plantai jardins e comei seus frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Tomai mulheres e gerai filhos e filhas. Tomai mulheres para vossos filhos e dai vossas filhas em casamento. Deixai-os gerar filhos e filhas, e multiplicai para que não sejais poucos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Buscai a paz na cidade para onde vos deportei, e orai a Mim, para que tenhais paz, na medida em que ela estiver em paz.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Pois Yahweh dos Exércitos, o Deus de Israel, diz: \'Não deixeis que vossos profetas, que estão no meio de vós, e vossos adivinhos vos enganem, e não deis importância aos sonhos que vós mesmos estais tendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Pois estão profetizando enganos para vós em Meu nome. Eu não os enviei\' — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Pois assim diz Yahweh: \'Quando se completarem os setenta anos designados para a Babilônia, Eu vos ajudarei e cumprirei Minha boa palavra para convosco, trazendo-vos de volta a este lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Pois Eu bem sei os pensamentos que tenho a vosso respeito — esta é a declaração de Yahweh — pensamentos de paz e não de desgraça, para vos dar um futuro e esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Então, vós Me invocareis e orareis, e Eu vos ouvirei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'E Me buscareis e Me achareis, quando Me buscardes de todo o vosso coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Então, serei achado por vós — esta é a declaração de Yahweh. Eu trarei de volta a vossa sorte, e vos reunirei dentre todas as nações e lugares para onde vos espalhei — esta é a declaração de Yahweh. Pois, vos trarei de volta do lugar de onde vos exilei.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Vós dizeis que Yahweh levantou profetas para nós, na Babilônia;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'todavia, Yahweh diz para o rei que se assenta no trono de Davi, e para todo o povo que habita nesta cidade, vossos irmãos que não foram levados ao cativeiro;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'assim diz Yahweh dos Exércitos: \'Eu lhes mandarei espada, fome e peste; Eu lhes farei como figos podres que não podem ser comidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Eu lhes perseguirei com espada, fome e peste, e eles serão uma visão terrível aos olhos de todos os reinos da terra. Eles serão objeto de horror, maldição, ofensa e vergonha dentre todas as nações por onde Eu os espalhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Isto porque não ouviram as Minhas palavras — assim diz Yahweh — as quais lhes enviei através de Meus servos, os profetas. Eu as enviei repetidamente, mas vós não ouvistes — assim diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Então, escutai a palavra de Yahweh, vós todos os que fostes exilados de Jerusalém para a Babilônia:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, '\'Eu, Yahweh dos Exércitos, o Deus de Israel, vos digo acerca de Acabe, filho de Colaías, e Zedequias, filho de Maaseias, que a vós profetizaram mentiras em Meu nome: Vede, estou prestes a vos entregar nas mãos de Nabucodonosor, rei da Babilônia. Ele vos matará diante de vossos olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Uma maldição será lançada, por causa dessas pessoas, a todos os cativos de Judá na Babilônia, dizendo: \'Que Yahweh vos faça como a Zedequias, e como a Acabe, os quais o rei da Babilônia queimou no fogo.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Isto acontecerá por causa das coisas terríveis que fizestes a Israel, quando cometestes adultério com as esposas de vossos vizinhos, e declarastes falsas palavras em Meu nome, coisas que não vos mandei dizer. Pois Eu sou Aquele que sabe, Eu sou a testemunha – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Sobre Semaías, o neelamita, dizei:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Assim diz Yahweh dos Exércitos, o Deus de Israel: Porque enviaste cartas em teu próprio nome a todo o povo em Jerusalém, como também a Sofonias, filho de Maaseias, o sacerdote, e a todos os sacerdotes dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, '\'Yahweh o fez sacerdote no lugar de Jeoiada, o sacerdote, para que fosse responsável pela Casa de Yahweh.\' Deveis controlar todas as pessoas que deliram e se fazem de profetas. Deveis prendê-los com correntes no pescoço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Então, por que não repreendestes Jeremias de Anatote, que se nomeou profeta entre vós?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Pois ele nos enviou à Babilônia, e disse: \"Será um longo tempo; construí casas e vivei nelas, plantai jardins e comei seus frutos.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Sofonias, o sacerdote, leu essa carta para Jeremias, o profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Então, a palavra de Yahweh veio a Jeremias dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, '\"Envia a Palavra a todos os exilados e dize: \'Assim diz Yahweh sobre Semaías, o neelamita: Porque Semaías profetizou a vós, quando Eu mesmo não o enviei, levando-vos a crer em mentiras,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'porém, assim diz Yahweh: Vede, estou para castigar Semaías, o neelamita, e seus descendentes. Não haverá em sua família nenhum homem que habitará entre este povo, nem verá o bem que farei pelo Meu povo – essa é a declaração de Yahweh – pois ele proclamou rebeldia contra Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Esta é a palavra que de Yahweh veio a Jeremias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, '\"Isto é o que Yahweh, o Deus de Israel, diz: Escreve para ti, em um livro, as palavras que te declarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Vede! Dias virão – esta é a declaração de Yahweh – quando Eu mudarei o destino do Meu povo, Israel e Judá. Eu, Yahweh, já disse isso. Pois os trarei de volta à terra que dei aos vossos antepassados, e eles a possuirão.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Estas são as palavras que Yahweh declarou acerca de Israel e de Judá:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, '\"Pois Yahweh diz isto: Ouvimos uma voz trêmula de pavor, não de paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Perguntai e observai se um homem pode dar à luz uma criança. Por que eu vejo todos os homens jovens com as mãos no ventre, como uma mulher em trabalho de parto? Por que todos os seus rostos ficaram pálidos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Ah! Como aquele dia será grandioso, como nenhum igual. Será um tempo de angústia para Jacó, mas ele será livre dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Porque será naquele dia, esta é a declaração de Yahweh dos Exércitos, que quebrarei o jugo sobre o teu pescoço, e quebrarei tuas correntes, para que estrangeiros não os escravizem mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Mas irão adorar a Yahweh, seu Deus, e servir a Davi, a quem Eu levantarei como rei sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Portanto, tu, meu servo Jacó, não temas, esta é a declaração de Yahweh, e não te espantes, Israel. Pois eu vos trarei de volta de terras distantes, e vossos descendentes, da terra dos cativos. Jacó retornará e estará em paz; ele estará seguro, e não haverá mais terror.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Pois Eu estou convosco – esta é a declaração de Yahweh – para vos salvar. Destruirei totalmente todas as nações onde Eu vos espalhei. Mas, certamente, não darei fim a vós, mas vos disciplinarei de maneira justa; certamente, não vos deixarei impunes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Pois Yahweh diz isto: \"Tua injúria é incurável, tua ferida está infectada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Não há ninguém para defender o teu caso; não há quem possa curá-lo, não tem remédio para a tua ferida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Todos os teus amantes se esqueceram de ti. Eles não te procurarão, pois Eu te feri com a ferida de um inimigo e a disciplina de um mestre cruel, por causa das tuas muitas iniquidades e incontáveis pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Por que gritas de dor? Tua ferida é incurável. Por causa de tuas muitas iniquidades, teus incontáveis pecados, Eu fiz estas coisas a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Então, todos os que te consumirem serão consumidos, e todos os teus adversários irão para o cativeiro. E os que te despojam, serão despojados. Todos os que te saqueiam, entregarei para o saque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Pois restaurarei a ti; Eu curarei as tuas feridas – esta é a declaração de Yahweh – Eu farei isto porque eles chamaram-te: Rejeitada. Ninguém se importa com Sião.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Yahweh diz isto: \"Vede! Estou prestes a mudar o destino das tendas de Jacó e de ter compaixão de seus lares. Então, uma cidade será construída sobre um monte de ruínas, e um palácio no seu devido lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Uma canção de louvor e um som de alegria sairão deles, porque Eu os multiplicarei e não serão diminuídos; Eu os honrarei para que não sejam humilhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Então, seu povo será como antes, e sua comunidade será estabelecida diante de mim, quando Eu punir todos aqueles que, agora, os atormentam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Seu príncipe procederá deles. Ele virá do meio deles, e o farei aproximar-se, e ele se chegará a Mim; se Eu não fizer isto, quem se atreverá a chegar perto de Mim? – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'E vós sereis Meu povo, e Eu serei vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Vede! A tempestade de Yahweh, sua fúria, já foi liberada. É uma tempestade contínua, e isso cairá na cabeça dos ímpios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'A ira de Yahweh não retornará até que tenham se cumprido todos os propósitos de Seu coração. Nos últimos dias, entendereis isto.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Esta é a declaração de Yahweh: \"Naquele tempo, Eu serei o Deus de todas as famílias de Israel e eles serão Meu povo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Assim diz Yahweh: \"O povo que sobreviveu à espada, achou favor no deserto; Eu darei descanso a Israel.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Yahweh me apareceu no passado e disse: \"Eu te amei, Israel, com amor eterno. Por isso te atraí a Mim com amor leal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Edificarei novamente a ti e serás edificada, ó virgem Israel! Ainda pegarás teus tamborins e sairás com danças alegres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Plantarás vinhas novamente nas montanhas de Samaria; os agricultores plantarão e colherão os frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Porque virá o dia em que as sentinelas, nas montanhas de Efraim, proclamarão: \'Levantai-vos, subamos à Sião para Yahweh, nosso Deus.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Pois, Yahweh diz isto: \"Exultai de alegria por Jacó! Exultai por causa da cabeça das nações! Que seja ouvido o louvor! Dizei: \'Yahweh tem salvado Seu povo, o remanescente de Israel.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Vede, estou prestes a trazê-los das terras do norte. Eu os ajuntarei das partes mais distantes da Terra. Os cegos e os aleijados estarão entre eles; mulheres grávidas e as que estão prestes a dar à luz também. Uma grande multidão retornará aqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Eles virão chorando, e os conduzirei enquanto fazem suas súplicas. Eu vou guiá-los aos ribeiros de águas, por um caminho reto em que não tropeçarão, pois serei um pai para Israel, e Efraim será meu primogênito.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, '\"Escutai, nações, a palavra de Yahweh! E anunciai nas ilhas distantes. Vós, nações, deveis dizer: \'Aquele que espalhou Israel o reunirá e o guardará, como um pastor que guarda suas ovelhas.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Porque Yahweh resgatou Jacó e o livrou da mão do que era mais forte do que ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Então, eles virão e se regozijarão nas alturas de Sião. Seus rostos brilharão por causa da bondade de Yahweh; por causa do trigo e do vinho novo, do óleo e da cria de cordeiros e bezerros. Pois suas vidas se tornarão como um jardim regado, e eles nunca mais sentirão tristeza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Então, as virgens se alegrarão com danças e os jovens e velhos ficarão juntos, porque tornarei o luto deles em celebração. Terei compaixão deles e os farei regozijarem-se, ao invés de se lamentarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Então, saciarei a vida dos sacerdotes com fartura. Meu povo se satisfará com a Minha bondade – esta é a declaração de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Assim diz Yahweh: \"Uma voz é ouvida em Ramá, lamento e choro amargo: Raquel está chorando por seus filhos e se recusa a ser consolada sobre eles, pois não vivem mais.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Assim diz Yahweh: \"Reprime tua voz de choro e teus olhos das lágrimas, porque há uma recompensa para o teu sofrimento— esta é a declaração de Yahweh— teus filhos retornarão da terra do inimigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Há esperança para o teu futuro— esta é a declaração de Yahweh— teus filhos retornarão para os seus territórios.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, '\"Eu, certamente, ouvi Efraim lamentando: \'Tu me castigaste e fui punido. Traze-me de volta como um novilho não domado e voltarei, pois Tu és Yahweh, meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Porque, depois que me voltei para Ti, me arrependi; depois de ser domado, bati em minha coxa com pesar. Eu estava envergonhado e humilhado por carregar a culpa da minha juventude.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Não é Efraim Meu filho precioso? Não é ele Meu filho querido e agradável? Pois quando falo contra ele, certamente, ainda Me lembro com amor. Assim, Meu coração lhe deseja. Eu, certamente, terei compaixão dele — esta é a declaração de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Coloca marcos e põe sinais que te guiem; coloca a tua mente no caminho pelo qual andaste. Volta, virgem de Israel! Volta para as tuas cidades!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Por quanto tempo continuarás a fraquejar, filha rebelde? Pois, Yahweh criou algo novo na terra: uma mulher cercará um homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Yahweh dos Exércitos, o Deus de Israel, diz: \"Quando Eu trouxer de volta o povo para sua terra, dirão isto na terra de Judá e nas suas cidades: \'Que Yahweh te abençoe, ó morada da justiça, ó monte santo!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Pois Judá e todas as suas cidades viverão juntas ali, assim como os lavradores e pastores com seus rebanhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Pois, Eu darei aos cansados água para beber, e vou saciar todos os que sofrem de sede.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Depois disto, acordei e percebi que meu sono havia sido agradável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Eis que, dias virão – esta é a declaração de Yahweh – quando Eu semearei as casas de Israel e de Judá, com semente de homens e de animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'No passado, Eu os mantive sob vigilância, a fim de arrancá-los, derrubá-los, demoli-los, destruí-los e prejudicá-los. Mas nos dias que virão, Eu os vigiarei, a fim de edificá-los e plantá-los – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'Naqueles dias ninguém mais dirá: \'Os pais comeram uvas verdes e os dentes dos filhos ficaram opacos.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Pois, cada homem morrerá em sua própria iniquidade; todos os que comerem uvas verdes, terão seus dentes opacos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Eis que virão dias – esta é a declaração de Yahweh – quando estabelecerei uma nova aliança com a casa de Israel e com a casa de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Não será como a aliança que Eu estabeleci com seus pais, nos dias em que os tomei pela mão, para trazê-los para fora da terra do Egito. Aqueles foram dias em que quebraram minha aliança; embora Eu fosse o Senhor deles — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Mas esta é a aliança que estabelecerei com a casa de Israel depois desses dias, esta é a declaração de Yahweh: \'Eu colocarei a Minha lei no meio deles e a escreverei em seus corações, pois Eu serei o seu Deus e eles serão o Meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Então, cada homem não ensinará mais ao seu próximo, nem cada um ao seu irmão, dizendo: \'Conhece a Yahweh!\' Pois todos eles, do menor até o maior, conhecerão quem Eu sou – esta é a declaração de Yahweh – pois Eu perdoarei a sua iniquidade e não Me lembrarei mais dos seus pecados.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Yahweh diz isto – Yahweh, Aquele que faz o sol brilhar durante o dia, e organiza a lua e as estrelas para brilharem à noite. Ele é quem coloca o mar em movimento para que suas ondas rujam. Yahweh dos Exércitos é o Seu nome. Ele diz:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, '\"Somente se estas coisas permanentes desaparecerem da minha vista – esta é a declaração de Yahweh – os descendentes de Israel deixarão de ser, para sempre, uma nação perante Mim.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Assim diz Yahweh: \"Somente se os mais altos céus puderem ser medidos, e a fundação da Terra puder ser descoberta, rejeitarei todos os descendentes de Israel, por causa de tudo o que eles fizeram – esta é a declaração de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, '\"Eis que dias virão – esta é a declaração de Yahweh – quando a cidade será reconstruída para Mim, da torre de Hananel até o portão da Esquina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Então, a corda de medir será estendida até a colina de Garebe, e contornará Goa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Todo o vale de cadáveres e de cinzas, todos os campos, passando pelo vale de Cedrom até a esquina do portão dos Cavalos, no oriente, serão consagrados a Mim, Yahweh. A cidade nunca mais será arrancada ou destruída novamente.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Esta é a palavra que veio de Yahweh a Jeremias no décimo ano de Zedequias, rei de Judá, no décimo oitavo ano de Nabucodonosor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Naquele tempo, o exército do rei da Babilônia estava sitiando Jerusalém, e Jeremias, o profeta, estava preso no pátio da guarda, na casa do rei de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Zedequias, rei de Judá, o prendeu, dizendo: \"Por que profetizas e dizes: \'Yahweh diz: Eu estou prestes a entregar esta cidade nas mãos do rei da Babilônia e ele a conquistará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Zedequias, rei de Judá, não escapará das mãos dos babilônios, mas certamente será entregue na mãos do rei da Babilônia. Sua boca falará à boca do rei, e seus olhos verão os olhos do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Ele levará Zedequias para a Babilônia e ficará lá, até que Eu cuide dele – essa é a declaração de Yahweh – ainda que lutes contra os babilônios, tu não serás bem sucedido.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Jeremias disse: \"A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, '\'Eis que Hanameel, filho de teu tio Salum, está vindo a ti e dirá: \"Compra o meu campo que está em Anatote, pois a ti pertence o direito de comprá-lo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Então, como Yahweh declarou, Hanameel, filho do meu tio, veio a mim no pátio da guarda e me disse: \"Compra meu campo que está em Ananote, na terra de Benjamim, pois o direito de herança é teu. Compra-o para ti.\" Então, eu soube que esta era a palavra de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Eu comprei de Hanameel, o filho do meu tio, o campo em Ananote, e pesei para ele dezessete siclos de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Assinei a escritura, a selei, e chamei testemunhas para conferirem. Então pesei a prata numa balança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Depois, peguei a escritura da compra que estava selada, seguindo os termos e estatutos, bem como a escritura aberta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'Entreguei a escritura selada a Baruque, filho de Nerias, filho de Maseias, na frente de Hanameel, filho do meu tio, e das testemunhas que assinaram na escritura selada, e diante de todos os judeus que estavam sentados no pátio da guarda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Então, ordenei a Baruque diante deles, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, '\"Yahweh dos Exércitos, o Deus de Israel, diz isto: \'Pegue estes documentos com a escritura de compra, tanto a selada como a aberta, os ponha em um jarro de barro, para que durem por muito tempo.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Porque Yahweh dos Exércitos, o Deus de Israel, diz: \"Casas, campos e vinhas serão comprados novamente nesta terra.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Depois de entregar a escritura de compra a Baruque, filho de Nerias, eu orei a Yahweh e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, '\"Ah, Senhor Yahweh! Vê! Tu sozinho fizeste os céus e a terra pelo Teu grande poder e com Teu braço estendido. Nada que digas é difícil demais para que faças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Tu demonstras misericórdia a milhares e retribuis a iniquidade dos pais nos filhos. Tu és o Grande e Poderoso Deus, Yahweh dos Exércitos é o Teu nome!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Tu és grande em sabedoria e poderoso em obras, pois Teus olhos estão abertos para todas as pessoas, para dar a cada homem aquilo que ele merece, segundo a sua conduta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Tu fizeste sinais e maravilhas na terra do Egito, até o dia de hoje; aqui em Israel e entre toda a humanidade, fizeste Teu nome conhecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Pois trouxeste o teu povo, Israel, para fora do Egito com sinais e maravilhas, com mão forte, com braço estendido e com grande terror.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'Então, deste a eles esta terra, a qual jurou que daria aos antepassados deles, uma terra que jorra leite e mel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'E entraram e tomaram posse dela; mas eles não obedeceram à Tua voz, nem viveram em obediência à Tua lei. Eles não fizeram nada daquilo que ordenaste que fizessem, então trouxeste toda essa desgraça sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Olhai! Os cercos chegaram à cidade para conquistá-la. Pois pela espada, fome e peste a cidade foi entregue nas mãos dos babilônios, que lutam contra ela. Pois o que disseste que aconteceria, está acontecendo; e vede, Tu mesmo o vês.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'E Tu me disseste: \"Compre um campo para ti com prata, e tenha testemunhas, mesmo que a cidade esteja sendo entregue nas mãos dos babilônios.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Esta é a palavra de Yahweh que veio a Jeremias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, '\"Olhai! Eu sou Yahweh, Deus de toda a humanidade. Existe algo que seja difícil demais para mim?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Portanto, Yahweh diz isto: \"Vede, vou entregar esta cidade nas mãos dos babilônios, e Nabucodonosor, rei da Babilônia, a conquistará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Os babilônios que estão lutando contra esta cidade, entrarão e a incendiarão. Eles a queimarão, junto com as casas em cujos telhados as pessoas adoravam Baal e derramavam ofertas de bebidas a outros deuses, para Me provocarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Pois o povo de Israel e de Judá, certamente, tem sido um povo que, desde a sua juventude, faz o que é mau diante dos Meus olhos. O povo de Israel, certamente, Me ofendeu com as práticas de suas mãos – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Pois esta cidade tem sido uma provocação à Minha ira e fúria desde o dia em que eles a construíram. E tem sido assim até o dia de hoje. Então, Eu a removerei de diante de Mim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'por causa de toda a maldade do povo de Israel e Judá, das coisas que eles fizeram para Me provocar; eles, seus reis, príncipes, sacerdotes, profetas e todos os habitantes de Judá e de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Eles voltaram suas costas para Mim, ao invés de suas faces, mesmo que zelosamente os ensinasse. Eu tentei ensiná-los, mas nenhum deles escutou para receber instrução.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Eles colocaram seus ídolos abomináveis na casa que se chama pelo Meu nome, para contaminá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Depois, edificaram os altos de Baal no vale de Ben-Hinom, para sacrificar seus filhos e filhas a Moloque, algo que Eu não lhes ordenei, nem me passou pela mente que fizessem tal abominação, para fazerem Judá pecar.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Portanto, Eu, Yahweh, o Deus de Israel, digo isto a respeito desta cidade, a cidade da qual vós falais: \'Está entregue nas mãos do rei da Babilônia pela espada, fome e peste.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Vede, Eu estou prestes a reuni-los de todas as terras de onde os dispersei na Minha ira, fúria e grande raiva. Certamente, os trarei de volta a este lugar e permitirei que vivam em segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'E eles serão o Meu povo, e Eu serei o seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Eu lhes darei um só coração e uma só forma de Me honrarem todos os dias, para o seu bem e o bem de seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'E Eu estabelecerei uma aliança eterna com eles, não deixarei de fazer-lhes o bem. Porei o Meu temor no seu coração, e eles nunca mais se afastarão de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'E Me regozijarei, fazendo o bem a eles. Eu os plantarei firmemente nesta terra com todo o Meu coração e toda a Minha vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Pois Yahweh diz isto: \'Assim como Eu trouxe essa grande desgraça sobre este povo, trarei sobre eles todo o bem que lhes tenho prometido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Então, campos serão comprados nesta terra, sobre a qual dizeis: \"Esta é uma terra arruinada, que não tem nem homens, nem animais. Ela foi entregue nas mãos dos babilônios.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Eles comprarão campos com prata; escrituras serão assinadas e seladas. Eles chamarão testemunhas na terra de Benjamim, nos lugares ao redor de Jerusalém, nas cidades de Judá, nas cidades da região montanhosa, nas cidades das planícies e nas cidades do sul. Pois Eu mudarei o destino deles, esta é a declaração de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Então, a palavra de Yahweh veio a Jeremias, pela segunda vez, enquanto ele ainda estava preso no pátio da guarda, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, '\"Yahweh, o Criador que faz estas coisas, que as forma a fim de estabelecê-las, Yahweh é o Seu nome, diz isto:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, '\'Clama a Mim e te responderei; revelarei coisas grandes para ti, mistérios que não conheces.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Pois Yahweh, o Deus de Israel, diz isto acerca das casas desta cidade, e das casas dos reis de Judá, que foram derrubadas para a defesa contra as rampas de cercos e a espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Os babilônios estão chegando para lutar e para encher as casas com cadáveres, a quem Eu matarei com Minha ira e fúria, porque escondi Minha face desta cidade, por causa de todas as suas maldades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Mas, vede, Eu estou prestes a trazer saúde e cura, pois Eu irei curá-los e lhes trarei abundância, paz e fidelidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Eu trarei de volta a sorte de Judá e Israel, e os reedificarei como no princípio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Então, os purificarei de toda maldade que eles cometeram contra Mim; perdoarei todas as iniquidades que praticaram, e todas as maneiras pelas quais se rebelaram contra Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Então, esta cidade se tornará para Mim um objeto de alegria, uma canção de louvor e honra diante das nações da terra, que ouvirão todas as coisas boas que Eu farei para ela. Então, elas tremerão espantadas por causa de todo o bem e da paz que lhes darei.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Yahweh diz isto: \"Neste lugar sobre o qual agora vós estás dizendo: \'É uma desolação. Não existe nenhum homem, nem animal nas cidades de Judá; e as ruas de Jerusalém são inabitáveis, sem nenhum homem ou animal.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Novamente, serão ouvidos os sons de alegria e celebração, sons de noivos e noivas, sons das vozes de pessoas que fazem ofertas de agradecimento à Casa de Yahweh: \"Dai graças a Yahweh dos Exércitos, porque Ele é bom, o Seu amor leal não tem fim\". Pois mudarei o destino desta terra, tornando-a como era no princípio\', diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Assim diz Yahweh dos Exércitos: \"Neste lugar desolado, onde agora não existe homem nem animal, haverá novamente, em todas as cidades, pastos onde os pastores poderão repousar seus rebanhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Nas cidades da região montanhosa, nas cidades das planícies, nas cidades do Sul, na terra de Benjamim, nas vilas ao redor de Jerusalém e nas cidades de Judá ainda passarão os rebanhos pelas mãos de quem os conte\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Olhai! Eis que vêm dias – esta é a declaração de Yahweh – quando Eu farei o que prometi à casa de Israel e à casa de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'Naqueles dias e naquele tempo, farei brotar de Davi um Renovo Justo, e ele fará justiça e retidão na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'Naqueles dias, Judá será salva e Jerusalém viverá em segurança, pois este é o nome pela qual será chamada: \"Yahweh é a nossa justiça.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Pois assim diz Yahweh: \"Nunca faltará um homem da linhagem de Davi para assentar-se no trono da casa de Israel,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'nem faltará um homem dos sacerdotes levitas, diante de Mim, para levantar holocaustos, para queimar ofertas de alimentos, e realizar ofertas de cereais em todo o tempo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'A palavra de Yahweh veio a Jeremias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, '\"Assim diz Yahweh: Se puderdes quebrar Minha aliança com o dia e com a noite, de modo que não haja nem dia nem noite a seu tempo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'então, vós também quebrareis Meu pacto com Davi, Meu servo, para que ele não tenha um filho para reinar em seu trono; como também o Meu pacto com os pastores levitas, Meus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Como as estrelas do céu não podem ser contadas, e como a areia do mar não pode ser medida, assim aumentarei os descendentes de Davi, Meu servo, e dos levitas que Me servem.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'A palavra de Yahweh veio a Jeremias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, '\"Não tens considerado o que este povo tem declarado quando dizem: \'As duas famílias que Yahweh escolheu, agora Ele tem rejeitado?\' Assim, desprezam Meu povo, dizendo que eles não são mais uma nação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Eu, Yahweh, digo isto: \'Se a minha aliança com o dia e a noite não vale mais, e se Eu não manter a harmonia do céu e terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'então, Eu rejeitarei os descendentes de Jacó e Davi, Meu servo, e não trarei uma pessoa para governar sobre os descendentes de Abraão, Isaque e Jacó. Porque lhes restaurarei a sorte e lhes mostrarei misericórdia.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Esta é a palavra que veio de Yahweh a Jeremias, quando Nabucodonosor, rei da Babilônia e todo o seu exército, juntamente com todos os reinos da terra, os domínios sob o seu poder, e todo o seu povo que atacavam Jerusalém e todas as suas cidades, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, '\"Yahweh, o Deus de Israel, diz assim: \'Vai, fala com Zedequias, rei de Judá, e dize-lhe: Assim diz Yahweh: \'Olhai, Eu estou prestes a entregar esta cidade nas mãos do rei da Babilônia, e Ele a queimará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Tu não escaparás da mão dele, pois, certamente, serás capturado e entregue em suas mãos. Teus olhos verão o rei da Babilônia; ele falará diretamente contigo. E irás para a Babilônia.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Ouve a palavra de Yahweh, Zedequias, rei de Judá! Yahweh diz isto a respeito de ti: \"Tu não morrerás pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Tu morrerás em paz. Assim como queimavam seus antepassados, os reis antes de ti, em funerais, eles queimarão seu corpo. E dirão: \"Ah, mestre!\" Eles lamentarão por ti. Pois eu falei isto – essa é a declaração de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Então, Jeremias, o profeta, proclamou para Zedequias, rei de Judá, todas estas palavras em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Quando o exército do rei da Babilônia guerreava contra Jerusalém e contra as cidades remanescentes de Judá: Laquis e Azeca, cidades fortificadas, haviam permanecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Esta é a palavra que veio de Yahweh a Jeremias, depois que o rei Zedequias havia estabelecido um acordo com todo o povo de Jerusalém para proclamar liberdade:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'Que cada homem libertasse seus escravos hebreus, tanto homens quanto mulheres. Ninguém mais deve escravizar um judeu, que era seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Então, todos os líderes e pessoas que assinaram o acordo obedeceram. Cada pessoa libertaria seu escravo, homem e mulher e não mais os escravizaria. Eles ouviram e os mandaram embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Mas depois disso, mudaram de idéia. Eles trouxeram de volta os escravos que haviam libertado e os forçaram a se tornarem escravos novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Então, a palavra de Yahweh veio a Jeremias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, '\"Yahweh, o Deus de Israel, diz isto: Eu mesmo estabeleci uma aliança com vossos antepassados no dia em que os tirei da terra do Egito, da casa da escravidão, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, '\'Ao final de sete anos, cada homem deve mandar embora seu irmão, seu companheiro hebreu que se vendeu a ti, e te serviu por seis anos. Manda-o embora em liberdade\'. Mas vossos antepassados não Me ouviram, nem prestaram atenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Agora, vós mesmos estais arrependidos e começais a fazer o que é certo perante Meus olhos. Proclamastes liberdade, cada homem ao seu vizinho. E vós estabelecestes um acordo perante Mim, na casa que é chamada pelo Meu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Mas profanastes Meu nome e voltastes atrás; fizestes cada homem trazer de volta seu escravo, homem e mulher, os que mandaram embora, para irem onde desejassem. Vós os forçastes a vos servirem novamente.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Portanto, Yahweh diz isto: \'Vós mesmos não têm Me escutado. Deverias ter proclamado liberdade, cada um de vós, a teus irmãos e companheiros israelitas. Olhai! Estou prestes a proclamar liberdade, esta é a declaração de Yahweh; liberdade pela espada, pela peste e pela fome; pois Eu farei de vós uma coisa horrível aos olhos de todos os reinos da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Então, eu lidarei com as pessoas que transgrediram Minha aliança, que não mantiveram as palavras do acordo que estabeleceram diante de Mim, quando cortaram um bezerro em dois, e andaram entre suas partes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'isto é, os líderes de Judá e Jerusalém, os oficiais e os sacerdotes, e todo o povo da terra que andaram entre as partes do bezerro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Eu os entregarei nas mãos dos seus inimigos e dos que querem suas vidas. Seus corpos serão alimento para os pássaros dos céus e para as feras da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Então, entregarei Zedequias, rei de Judá, e os seus líderes nas mãos dos seus inimigos, e daqueles que procuram matá-los, e na mão do exército do rei da Babilônia, que tem-se levantado contra vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Olhai, estou prestes a dar-lhes uma ordem – esta é a declaração de Yahweh – e os trarei de volta a esta cidade para guerrear contra vós, tomá-los, e queimá-los. Porque tornarei as cidades de Judá em ruínas, onde não haverá habitantes.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'A palavra veio a Jeremias, da parte de Yahweh, nos dias de Jeoaquim, filho de Josias, rei de Judá, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, '\"Vai à família dos recabitas e fala com eles. Então, leva-os à Minha casa, até uma das salas e dá vinho para que bebam.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Então, eu trouxe Jazanias, filho de Jeremias, filho de Habazinias, e seus irmãos, todos os seus filhos, e toda a família dos recabitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'Eu os levei à Casa de Yahweh, à sala dos filhos de Hanã, filho de Jigdalias, homem de Deus. Essa sala ficava ao lado da sala dos líderes, que ficava acima da sala de Maaseias, filho do porteiro Salum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Então, eu coloquei jarras e cálices cheios de vinho perante os recabitas e lhes disse: \"Bebam um pouco de vinho.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Mas eles disseram: \"Nós não beberemos vinho algum, pois nosso antepassado, Jonadabe, filho de Recabe, nos ordenou: \'Jamais bebereis vinho, nem vós, nem vossos descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Também não construireis casas, semeareis semente alguma ou plantareis vinhas; isto não é para vós. Pois deveis viver em tendas por todos os vossos dias; assim, vivereis muitos dias na terra onde permanecereis como estrangeiros.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Nós obedecemos à voz de Jonadabe, filho de Recabe, nosso antepassado, em tudo o que ele nos ordenou: para não bebermos vinho em todos os nossos dias; nem nós, nem nossas mulheres, nem nossos filhos e nem nossas filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'E nós nunca construiremos casas para morar, e nunca haverá vinha, campo ou semente em nossa posse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Nós temos vivido em tendas, ouvido e feito tudo aquilo que Jonadabe, nosso antepassado, nos ordenou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Mas quando Nabucodonosor, rei da Babilônia, atacou a terra, nós dissemos: \'Vinde, vamos a Jerusalém para escaparmos dos exércitos dos babilônios e dos sírios.\' Então, estamos vivendo em Jerusalém.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Então, veio a palavra de Yahweh a Jeremias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, '\"Yahweh dos Exércitos, o Deus de Israel, diz isto: \'Vai, dize aos homens de Judá e aos habitantes de Jerusalém: \"Não recebereis Minha correção e não ouvireis Minhas palavras? – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'As palavras de Jonadabe, filho de Recabe, que ele deu ordem a seus filhos para não beberem vinho, foram acatadas até os dias de hoje. Eles obedeceram à ordem de seu antepassado. Mas, quanto a Mim, Eu vos tenho falado insistentemente, mas não ouvis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Eu vos enviei todos os Meus servos, os profetas. Eu fui persistente ao enviá-los para dizer: \'Cada um se afaste do seu mau caminho e faça boas obras; ninguém mais siga e adore outros deuses. Assim, ficareis na terra que vos dei a vós outros e a vossos antepassados\'. Ainda assim, não ouvistes ou prestastes atenção em Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Porque os descendentes de Jonadabe, filho de Recabe, observaram as ordens que seus antepassados lhes deram, mas este povo se recusa a Me ouvir.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Então, Yahweh, o Deus dos Exércitos e Deus de Israel, diz: \'Olhai, trarei sobre Judá e sobre todos os moradores de Jerusalém todos os desastres que proclamei contra eles; porque lhes falei, mas se recusaram a ouvir. Eu os chamei, mas não responderam.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Jeremias disse à família dos recabitas: \"Yahweh dos Exércitos, o Deus de Israel, diz isto: Vós ouvistes os mandamentos de Jonadabe, vosso antepassado, e os guardastes; vós obedecestes a tudo o que ele vos ordenou,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'então, Yahweh dos Exércitos, o Deus de Israel, diz isto: Sempre haverá alguém da linhagem de Jonadabe, filho de Recabe, para Me servir.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'No quarto ano de Jeoaquim, filho de Josias, rei de Judá, veio esta palavra de Yahweh a Jeremias:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, '\"Pegue um rolo para ti e escrevas nele todas as palavras que Eu te falei sobre Israel e Judá, e sobre todas as nações. Tudo o que Eu tenho dito, desde os dias de Josias até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Talvez, quando o povo de Judá ouvir sobre todos os desastres que pretendo trazer sobre eles, cada um se desvie do mau caminho, e assim Eu possa perdoar a sua iniquidade e seu pecado.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Então, Jeremias chamou Baruque, filho de Nerias; e Baruque escreveu no rolo, todas as palavras ditadas por Jeremias, que Yahweh lhe havia falado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Em seguida, Jeremias ordenou a Baruque dizendo: \"Estou proibido de ir à Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Assim, tu deves ir e ler o rolo que escreveste pela minha ordem. No dia do jejum, tu deverás ler as palavras de Yahweh perante o povo, na Casa de Yahweh, e também as lerás perante todos de Judá, que vêm das suas cidades. Proclame essas palavras para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Talvez seus pedidos de misericórdia cheguem perante Yahweh, e cada pessoa se desvie do seu mau caminho, uma vez que a ira que Yahweh proclamou contra este povo é severa.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Assim, Baruque, filho de Nerias, fez tudo o que o profeta Jeremias havia ordenado. Ele leu em voz alta as palavras de Yahweh na Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Sucedeu que, no quinto ano, no nono mês, de Jeoaquim, filho de Josias, rei de Judá, todas as pessoas em Jerusalém e as pessoas que vieram para Jerusalém das cidades de Judá, proclamaram um jejum em honra a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Baruque leu em voz alta as palavras de Jeremias na Casa de Yahweh, na sala de Gemarias, filho de Safã, o escriba, no pátio superior, junto ao portão de entrada da Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Quando Micaías, filho de Gemarias, filho de Safã, ouviu todas as palavras de Yahweh que estavam no rolo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'desceu para a casa do rei, para a sala do escriba. Eis que, todos os oficiais estavam sentados ali: Elisama, o escriba, Delaías, filho de Semaías, Elnatã, filho de Acbor, Gemarias, filho de Safã, Zedequias, filho de Hananias, e todos os oficiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Então, Micaías relatou a eles todas as palavras que ouvira quando Baruque leu em voz alta para o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Assim, todos os oficiais enviaram Jeúdi, filho de Netanias, filho de Selemias, filho de Cuxe, à Baruque. Jeúdi disse a Baruque: \"Pegue o rolo em tuas mãos, o rolo que tu estavas lendo ao povo e venha.\" Então, Baruque, filho de Nerias, pegou o rolo em suas mãos e foi até os oficiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'E eles disseram: \"Senta-te e lê o rolo para nós.\" Então, Baruque leu o rolo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Aconteceu que, quando eles ouviram todas aquelas palavras, entreolharam-se com medo e disseram para Baruque: \"Nós, certamente, precisamos relatar todas essas palavras ao rei.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Eles perguntaram a Baruque: \"Diga-nos, como escreveste todas essas palavras, Jeremias as ditou?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Baruque disse: \"Ele ditou todas estas palavras para mim, e eu as escrevi com tinta neste rol.\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Então, os oficiais disseram a Baruque: \"Vai, esconde-te, e Jeremias também. Não deixeis ninguém saber onde estais.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Colocaram o rolo na sala de Elisama, o escriba. Depois, foram para ao pátio do palácio, e relataram tudo ao rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Então, o rei enviou Jeúdi para buscar o rolo. Jeúdi o trouxe da sala de Elisama, o escriba, e o leu em voz alta para o rei e para todos os oficiais que estavam em pé ao lado dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Naquele momento, o rei estava em sua casa de inverno, pois era mês nono, e um braseiro estava queimando diante dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Aconteceu que, conforme Jeúdi lia três ou quatro colunas, o rei as cortava com uma faca e as atirava dentro do fogo no braseiro, até que todo o rolo foi destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Porém, nem o rei e nenhum dos seus servos que ouviram todas aquelas palavras ficaram assustados, nem rasgaram suas roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Ainda que Elnatã, Delaías e Gemanias tivessem pedido ao rei que não queimasse o rolo, ele não os ouviu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'O rei ordenou a Jerameel, seu filho, Seraías, filho de Azriel, e a Selemias, filho de Abdeel, que prendessem Baruque, o escriba, e Jeremias, o profeta, mas Yahweh os havia escondido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Então, a palavra de Yahweh veio a Jeremias, depois que o rei queimara o rolo e as palavras que Baruque escrevera, ditadas por Jeremias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, '\"Volta, pega outro rolo para ti, e escreve nele todas as palavras que estavam no rolo original que Jeoaquim, rei de Judá, queimou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Dirás isto para Jeoaquim, rei de Judá: \'Tu queimaste aquele rolo e disseste: Por que tens escrito que o rei da Babilônia, certamente, virá e destruirá esta terra? Por que ele acabará com os homem e os animais dela?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Portanto, Yahweh diz isto em relação a ti, Jeoaquim, rei de Judá: \"Nenhum descendente teu sentará no trono de Davi. Quanto a ti, teu cadáver será jogado fora no calor do dia e na geada da noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Punirei a ti, teus descendentes e teus servos, por causa da maldade de todos vós. Trarei sobre vós, sobre todos os habitantes de Jerusalém, e sobre todos os habitantes de Judá os desastres que tenho falado e não ouviram.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Assim, Jeremias pegou outro rolo e deu a Baruque, filho de Nerias, o escriba. E Baruque escreveu nele todas as palavras ditadas por Jeremias que estavam no rolo queimado por Jeoaquim, rei de Judá. Além disso, muitas outras palavras semelhantes foram acrescentadas a este rolo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Ora, Zedequias, filho de Josias, reinou no lugar de Joaquim, filho de Jeoaquim. Nabucodonosor, rei da Babilônia, fez Zedequias rei sob a terra de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Mas Zedequias, seus servos, e o povo da terra não escutaram as palavras de Yahweh, que foram proclamadas pelas mãos do profeta Jeremias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Assim, o rei Zedequias enviou Jeucal, filho de Selemias e Sofonias, filho de Maaseias, o sacerdote, ao profeta Jeremias, para lhe dizerem: \"Ore em nosso favor para Yahweh, nosso Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Jeremias estava indo e vindo entre as pessoas, pois não havia sido preso ainda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'O exército do Faraó saíra do Egito, e quando os caldeus, que sitiavam Jerusalém, ouviram a notícia sobre eles, deixaram a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Então, veio a palavra de Yahweh a Jeremias, o profeta, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, '\"Yahweh, o Deus de Israel, diz: \'Isto é o que tu dirás ao rei de Judá, porque ele te enviou para buscar Meu conselho: Vê, o exército do Faraó, que veio para te ajudar, está prestes a voltar para o Egito, a sua própria terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Os caldeus irão retornar, lutarão contra essa cidade, a conquistarão e a queimarão.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Yahweh diz isto: Não se enganem dizendo: \'Os caldeus com certeza estão nos deixando\'. Porque eles, certamente, não irão embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Mesmo que derrotásseis todo o exército babilônico, que luta contra vós, até que só homens feridos sejam deixados em suas tendas, eles se levantariam e queimariam esta cidade.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Foi então que o exército babilônico deixou Jerusalém enquanto o exército do Faraó estava vindo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'então, Jeremias saiu de Jerusalém para ir à terra de Benjamim. Ele queria tomar posse de um pedaço de terra lá entre seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Enquanto ele estava no Portão de Benjamim, um capitão da guarda que estava lá – seu nome era Jerias, filho de Selemias, filho de Hananias – agarrou o profeta Jeremias e disse: \"Tu estás fugindo para o lado dos babilônios.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Mas Jeremias disse: \"Isso não é verdade. Eu não estou fugindo para o lado dos babilônios\". Mas Jerias não o escutou. Prendeu Jeremias e o levou aos oficiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Os oficiais estavam bravos com Jeremias. Eles o açoitaram e o colocaram na casa de Jônatas, o escriba, que havia sido transformada em uma prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Jeremias foi colocado numa cela subterrânea, onde ficou por muitos dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Então, o rei Zedequias mandou alguém trazê-lo ao palácio. Em sua casa, o rei perguntou-lhe secretamente: \"Há alguma palavra de Yahweh?\"Jeremias respondeu: \"Há uma palavra: Tu serás entregue na mão do rei da Babilônia.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Então, Jeremias disse ao rei Zedequias: \"Qual foi meu pecado contra ti, contra teus servos ou contra este povo para que me pusesses na prisão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Onde estão os teus profetas, aqueles que profetizaram para ti e disseram que o rei da Babilônia não atacará a vós, nem a esta terra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Mas, agora, escute, meu senhor, ó rei! Deixo meu pedido diante de ti. Não me coloques novamente na casa de Jônatas, o escriba, senão morrerei lá.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Então, o rei Zedequias deu uma ordem. Seus servos confinaram Jeremias no pátio da guarda. Um pedaço de pão era entregue a ele todos os dias, da rua dos padeiros, até que todo o pão da cidade acabasse. E Jeremias permaneceu no pátio da guarda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Sefatias, filho de Matã, Gedalias, filho de Pasur, Jeucal, filho de Selemias, e Pasur, filho de Malquias, ouviram as palavras que Jeremias estava declarando para todo o povo. Ele dizia:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Assim diz Yahweh: \"Quem permanecer nesta cidade será morto pela espada, fome e peste. Porém, quem for com os babilônios, sobreviverá. Ele escapará com sua própria vida e viverá.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Assim diz Yahweh: \"Esta cidade será entregue nas mãos do exército do rei da Babilônia e ele a conquistará.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Então, os oficiais disseram ao rei: \"Deixa este homem morrer, pois o que ele diz está enfraquecendo as mãos dos soldados que permanecem nesta cidade e de todo o povo. Ele está proclamando estas palavras, pois não está trabalhando pela segurança deste povo, mas, sim, para a destruição.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Então, o rei Zedequias disse: \"Olhai, ele está em vossas mãos, pois não há rei capaz de resistir a vós.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Então, pegaram Jeremias e o jogaram dentro da cisterna de Malquias, filho do rei. A cisterna ficava no pátio da guarda. Eles desceram Jeremias com cordas. Não havia água na cisterna, mas lama, e ele afundou nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Ora, Ebede-Meleque, o etíope, que era um dos eunucos do palácio do rei, ouviu que eles tinham colocado Jeremias na cisterna. Quando o rei estava assentado no Portão de Benjamim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Ebede-Meleque saiu do palácio e foi falar com ele. Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, '\"Ó rei, meu senhor, estes homens têm tratado mal o profeta Jeremias. Eles o lançaram numa cisterna para que morra de fome, pois não há mais comida na cidade.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Então, o rei deu uma ordem para Ebede-Meleque, o etíope. Ele disse: \"Tome trinta homens daqui e tire o profeta Jeremias da cisterna antes que ele morra.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Assim, Ebede-Meleque reuniu os homens e foi para a casa do rei, para um depósito de roupas debaixo da casa. De lá, pegaram trapos e roupas desgastadas, e os desceu a Jeremias na cisterna, por meio de cordas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Ebede-Meleque, o etíope, disse a Jeremias: \"Ponha as roupas desgastadas e os trapos debaixo de seus braços e sobre as cordas.\" E Jeremias fez isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Então, eles puxaram Jeremias com as cordas, desta forma o tiraram da cisterna e o trouxeram para cima. E Jeremias permaneceu no pátio da guarda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Em seguida, o rei Zedequias mandou trazer o profeta Jeremias à sua presença, à terceira entrada da Casa de Yahweh. O rei disse a Jeremias: \"Quero perguntar-te algo. Não escondas a resposta de mim.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Jeremias disse a Zedequias: \"Se eu te responder, certamente, não me matarás? Mas se eu te der conselhos, não me ouvirás.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Mas o rei Zedequias jurou secretamente a Jeremias, dizendo: \"Assim como Yahweh vive, aquele que nos criou, não te matarei, nem te entregarei nas mãos dos homens que estão buscando tua vida.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Jeremias disse a Zedequias: Yahweh, o Deus dos Exércitos, o Deus de Israel, diz assim: \"Se te renderes aos oficiais do rei da Babilônia, então vivereis, e esta cidade não será queimada. Tu e tua família viverão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Mas, se não te renderes aos oficiais do rei da Babilônia, então esta cidade será entregue nas mãos dos caldeus. Eles a queimarão e tu não escaparás das mãos deles.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'O rei Zedequias disse a Jeremias: \"Mas tenho medo do povo de Judá, que já se rendeu aos caldeus, porque se eu for entregue nas mãos deles, eles me maltratarão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Jeremias respondeu: \"Eles não o entregarão. Obedeça à ordem de Yahweh que estou lhe dizendo, e tudo te irá bem e tu viverás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Mas se não te renderes, isto é o que Yahweh tem me mostrado:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Olhai! Todas as mulheres que ficaram na casa do rei de Judá serão levadas aos oficiais do rei da Babilônia. E elas lhe dirão: \'Tens sido enganado por teus amigos; e eles têm te arruinado. Teus pés estão afundados na lama, e os teus amigos fugiram.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Pois todas as tuas esposas e filhos serão levados aos caldeus e não poderás escapar de suas mãos. Serás capturado pela mão do rei da Babilônia e esta cidade será queimada.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Então, Zedequias disse a Jeremias: \"Não contes a ninguém sobre estas palavras, para que não morras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Se os oficiais souberem que falei contigo, se eles vierem e te disserem: \'Conta-nos sobre o que conversaste com o rei. Não nos escondas nada ou te mataremos. E conta-nos o que o rei disse a ti\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'então, deves dizer a eles: \'Eu supliquei ao rei que não me deixasse voltar à casa de Jônatas, para não morrer ali.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Então, todos os oficiais vieram a Jeremias e o interrogaram, e ele respondeu como o rei o instruíra. Assim, eles pararam de falar com ele, pois não haviam escutado a conversa entre Jeremias e o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'E Jeremias permaneceu no pátio da guarda até o dia em que Jerusalém foi invadida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'No nono ano, no décimo mês de Zedequias, rei de Judá, Nabucodonosor, rei da Babilônia, veio com todo o seu exército contra Jerusalém e a cercaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'No décimo primeiro ano e quarto mês de Zedequias, no nono dia do mês, a cidade foi invadida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Então, todos os oficiais do rei da Babilônia vieram e se assentaram no Portão do Meio: Nergal-Sarezer de Sangar, Nebo-Sarsequim, um oficial importante. Nergal Sarezer, alto oficial, e com eles todos os outros oficiais do rei da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Aconteceu que, quando Zedequias, rei de Judá e todos os seus guerreiros os viram, fugiram. Eles saíram da cidade à noite, pelo caminho do jardim do rei, através do portão entre os dois muros. O rei saiu na direção da Arabá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'mas o exército dos caldeus perseguiu-os e alcançou Zedequias nas planícies do vale do rio Jordão, perto de Jericó. Eles o capturaram e o trouxeram até Nabucodonosor, rei da Babilônia, em Ribla, na terra de Hamate, onde Nabucodonosor o sentenciou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'O rei matou os filhos de Zedequias diante dele, em Ribla. Ele também matou todos os homens nobres de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Cegou os olhos de Zedequias e o prendeu com correntes de bronze para levá-lo à Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Então, os babilônios queimaram a casa do rei e as casas do povo. Eles também derrubaram os muros de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Nebuzaradã, capitão da guarda do rei, levou para o exílio o resto do povo que havia ficado na cidade. Isso incluía os que se renderam aos babilônios e o restante da população.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Mas Nebuzaradã, o capitão da guarda do rei, permitiu que as pessoas mais pobres, que não possuíam nada, permanecessem na terra de Judá. Deu-lhes vinhas e campos naquele mesmo dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Nabucodonosor, o rei da Babilônia, havia dado uma ordem sobre Jeremias para Nebuzaradã, o capitão da guarda do rei. Ele dissera:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, '\"Leva-o e cuida bem dele. Não o machuque. Faça por ele tudo o que te disser.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Então, Nebuzaradã, capitão da guarda do rei, Nebusazbã, Rabe-Sáris, Nergal-Sarezer, Rabe-Mague e todos os oficiais mais importantes do rei da Babilônia');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'mandaram retirar Jeremias do pátio e o entregaram a Gedalias, filho de Aicam, filho de Safã, para que o levasse para casa; assim, Jeremias permaneceu entre o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Ora, a palavra de Yahweh viera a Jeremias enquanto estava preso no pátio da guarda, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, '\"Fala com Ebede-Meleque, o etíope, e diz: Yahweh dos Exércitos, o Deus de Israel, diz isto: Vede, Eu estou prestes a cumprir minhas palavras contra esta cidade, para o mal e não para o bem. Pois todas elas se cumprirão perante ti naquele dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Mas eu te resgatarei naquele dia, esta é a declaração de Yahweh, e não serás entregue nas mãos dos homens a quem temes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Pois Eu, certamente, te salvarei. Tu não cairás pela espada. Escaparás com vida, pois confias em Mim\" – esta foi a declaração de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Esta foi a palavra de Yahweh, que veio a Jeremias, depois que Nebuzaradã, o capitão da guarda do rei, o libertou em Ramá. Ele o encontrara acorrentado no meio dos exilados de Jerusalém e de Judá, que estavam sendo conduzidos para o exílio na Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'O chefe da guarda levou Jeremias e lhe disse: \"Yahweh, teu Deus, decretou este desastre contra este lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Agora, Yahweh o trouxe, e fez como havia decretado. Portanto, tudo isso vos aconteceu porque pecastes contra Ele e não obedecestes à Sua voz. Esse é o motivo pelo qual essas coisas têm acontecido convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Mas, agora vê! Eu te liberto hoje das correntes que estão em tuas mãos. Se for bom aos teus olhos que venhas comigo até a Babilônia, vem, e cuidarei de ti. Mas se não for bom aos teus olhos que venhas comigo para a Babilônia, então não venhas. Olha, toda a terra está diante de ti. Vá para onde for bom e direito aos teus olhos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Mas, visto que Jeremias demorava a se decidir, Nebuzaradã lhe disse: \"Volta a Gedalias, filho de Aicam, filho de Safã, a quem o rei da Babilônia nomeou governador das cidades de Judá. Habita com ele entre o povo, ou vai para onde for bom aos teus olhos.\" O comandante da guarda do rei deu a ele comida e um presente, e o deixou ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Então, Jeremias foi a Gedalias, filho de Aicam, em Mispá. Ele ficou com Gedalias entre o povo que foi deixado para trás na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Quando alguns comandantes dos soldados de Judá que ainda estavam no campo, e seus homens, ouviram que o rei da Babilônia havia feito de Gedalias, filho de Aicam, governador da terra, e que lhe havia confiado homens, mulheres e crianças que eram os mais pobres da terra, que não haviam sido exilados na Babilônia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'foram até ele em Mispá. Eram eles: Ismael, filho de Netanias; Joanã e Jônatas, filhos de Careá; Seraías, filho de Tanumete; os filhos de Efai, o netofatita; e Jazanias, filho do Maacatita, todos eles e seus homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Gedalias, filho de Aicam, filho de Safã, jurou a eles e seus homens: \"Não tenhais medo de servir os oficiais babilônios. Vivei na terra e servi o rei da Babilônia, e isso será bom para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'E, vede, eu continuarei morando em Mispá para me encontrar com os babilônios que vierem a nós. Então, colhei as uvas para fazer vinho, frutas de verão e azeite, e armazenem em vossas vasilhas. Vivei nas cidades que vós tendes ocupado.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Todos os judeus em Moabe, entre os amonitas, e em Edom, e em toda terra, ouviram que o rei da Babilônia havia deixado um remanescente em Judá e que ele havia nomeado Gedalias, filho de Aicam, filho de Safã, como governador sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Então, todos os judeus retornaram dos lugares para onde eles haviam se dispersado. Voltaram à terra de Judá, para Gedalias, em Mispá, e colheram uvas para o vinho e frutas de verão em grande quantidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Joanã, filho de Careá, e todos os comandantes dos exércitos no campo, vieram a Gedalias, em Mispá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'Eles disseram-lhe: \"Tu percebes que Baalis, rei dos amonitas, enviou Ismael, filho de Netanias para assassinar-te?\" Mas Gedalias, filho de Aicam, não acreditou neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Então, Joanã, filho de Careá, falou em segredo a Gedalias, em Mispá, e disse: \"Permita que eu vá matar Ismael, filho de Netanias. Ninguém suspeitará de mim. Por que deveria ele matar-te? Por que permitir que todos de Judá que têm estado junto a ti sejam dispersados e os remanescentes de Judá sejam destruídos?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Mas Gedalias, filho de Acaim, disse a Joanã, filho de Careá: \"Não faças isso, pois tu estás dizendo mentiras a respeito de Ismael.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'No sétimo mês, Ismael, filho de Netanias, filho de Elisama, da família real, e alguns oficiais do rei, vieram — dez homens estavam com ele — a Gedelias, filho de Aicam, em Mispá. Ali, eles comeram juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Mas Ismael, filho de Netanias, e os dez homens que estavam com ele, levantaram-se e atacaram Gedalias, filho de Aicam, filho de Safã, com a espada. Ismael matou Gedalias, a quem o rei da Babilônia havia posto como responsável pela terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Então, Ismael matou todos os judeus que estavam com Gedalias, em Mispá, e os soldados caldeus encontrados lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Esse era o segundo dia, depois da morte de Gedalias, mas ninguém sabia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Alguns homens vieram de Siquém, de Siló e de Samaria; oitenta homens que tinham raspado a barba, rasgado suas vestes e cortado a si mesmos, trazendo ofertas de alimento e incenso em suas mãos, para irem à Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Ismael, filho de Netanias, saiu de Mispá para encontrá-los, chorando enquanto caminhava. Então, aconteceu que encontrando-os, disse a eles: \"Venham a Gedalias, filho de Aicam!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Quando eles entraram na cidade, Ismael, filho de Netanias, abateu-os e jogou-os dentro de uma cova, ele e os homens que estavam com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Mas lá havia dez homens entre eles, os quais disseram para Ismael: \"Não nos mate, pois existem mantimentos nossos em um campo: trigo e cevada, azeite e mel.\" Então, ele não os matou, com seus outros companheiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'A cova onde Ismael jogou todos os corpos dos homens que ele matou, juntamente com o corpo de Gedalias, era uma cova larga que tinha sido cavada pelo Rei Asa, quando ele foi atacado pelo Rei Baasa, de Israel. Ismael, filho de Netanias, a encheu com aqueles que ele havia matado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Depois, Ismael capturou todo o restante do povo, que estava em Mispá, as filhas do rei e todas as pessoas que foram deixadas em Mispá, que Nebuzaradã, chefe da guarda, havia confiado a Gedalias, filho de Aicam. Então, Ismael, filho de Netanias, levou-os cativos e atravessou o território de Amom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Mas Joanã, filho de Careá, e os comandantes do exército que estavam com ele ouviram sobre todo o dano que Ismael, filho de Netanias, havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'Então, ele juntou os seus homens e foi lutar contra Ismael, filho de Netanias. E o encontraram no grande tanque de Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'E aconteceu que, quando todas as pessoas que estavam com Ismael viram Joanã, filho de Careá, e os comandantes do exército que estavam com ele, ficaram muito felizes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Então, todos os que Ismael havia capturado em Mispá, viraram as costas e foram para o lado de Joanã, filho de Careá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Mas Ismael, filho de Netanias, fugiu de Joanã com oito homens, e foi ao povo de Amom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Joanã, filho de Careá e todos os comandantes do exército que estavam com ele levaram de Mispá todas as pessoas que haviam sido resgatadas de Ismael, filho de Netanias. Isto foi depois de Ismael ter matado Gedalias, filho de Aicam. Joanã e seus companheiros levaram os homens fortes, os homens de luta, as mulheres, as crianças e os eunucos que haviam sido resgatados em Gibeão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Então, eles partiram e ficaram por um tempo em Gerute-Quimã – que fica perto de Belém – para, dali, entrarem no Egito');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'por causa dos caldeus. Estavam com medo deles desde que Ismael, filho de Netanias, matou Gedalias, filho de Aicam, a quem o rei da Babilônia havia posto como responsável pela terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Então, todos os comandantes do exército e Joanã, filho de Careá, e Jezanias, filho de Hosaías, e todo o povo, desde o menor até o maior, aproximaram-se de Jeremias, o profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'Eles lhe disseram: \"Deixa nossa súplica vir diante de ti. Ora por nós, para Yahweh teu Deus, por este povo que restou, pois, como podes ver, somos poucos em número.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Pergunta a Yahweh, teu Deus, para que nos diga o caminho que devemos ir e o que devemos fazer.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Então, Jeremias, o profeta, disse a eles: \"Eu tenho vos ouvido. Vede, eu orarei a Yahweh, vosso Deus, assim como vós pedistes. O que Yahweh disser, eu vos direi; não vs ocultarei nada.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Eles disseram a Jeremias: \"Que Yahweh seja uma testemunha verdadeira e fiel contra nós, se não agirmos sob cada palavra que Yahweh, teu Deus, nos ordenar a fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Quer seja boa ou má, obedeceremos à voz de Yahweh, nosso Deus, a quem te enviamos, para que tudo nos vá bem ao obedecermos à voz de Yahweh, nosso Deus.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Depois de dez dias, a palavra de Yahweh veio a Jeremias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Então, Jeremias chamou Joanã, filho de Careá e todos os comandantes do exército com ele, e todo o povo, do menor ao maior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'E lhes disse: \"Yahweh, o Deus de Israel, a quem me enviastes para apresentar vosso pedido diante dEle, diz:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Se voltardes e permanecerdes nesta terra, então, vos edificarei e não vos derrubarei; Eu vos plantarei e não vos arrancarei, pois Me arrependi do desastre que trouxe sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Não temais o rei da Babilônia, a quem vós temeis. Não o temais – essa é a declaração de Yahweh – desde que estou convosco para vos salvar e vos resgatar da mão dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Pois vos concederei misericórdia, terei compaixão e vos levarei de volta à vossa terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Mas, se disserdes: \"Não ficaremos nesta terra\", se não escutardes a Minha voz, a voz de Yahweh, vosso Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'se disserdes: \"Não! Nós iremos para a terra do Egito, onde não veremos nenhuma guerra, onde não ouviremos o som da trombeta e não teremos fome de alimento. Nós viveremos ali\",');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'Então, ouvi esta palavra de Yahweh, aos remanescentes de Judá. Yahweh dos Exércitos, Deus de Israel, diz: \'Se, realmente, vos preparardes para ir ao Egito e viverdes lá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'então, a espada que temeis vos atingirá na terra do Egito. A fome que vos preocupa vos perseguirá até o Egito, e ali morrereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Então, acontecerá que todos os homens que se prepararam para ir ao Egito, a fim de lá morarem, morrerão por espada, fome ou praga. Não haverá sobreviventes deles; nenhum escapará do desastre que lhes trarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Porque, assim diz Yahweh dos Exércitos, Deus de Israel: Assim como a minha ira e a minha fúria foram derramadas sobre os habitantes de Jerusalém, da mesma maneira, minha fúria será derramada sobre vós, se fordes para o Egito. Vós vos tornareis um objeto de maldição e horror, um objeto de maldições e desgraça. E nunca mais vereis este lugar.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Então, Jeremias disse: \"Yahweh tem falado a vosso respeito, ó remanescentes de Judá. Não entreis no Egito! Certamente, sabeis que hoje tenho sido testemunha contra vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Pois enganastes a vós mesmos quando me enviastes a Yahweh, vosso Deus, e dissestes: \'Ora a Yahweh, nosso Deus, por nós. Tudo o que Yahweh, nosso Deus, te disser, dize-nos e nós faremos.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Pois eu tenho falado a vós hoje, mas não obedecestes à voz de Yahweh, vosso Deus, em nada do que Ele me enviou para vos dizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Agora, certamente, sabei que morrereis pela espada, fome e praga, no lugar onde desejais viver.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Quando Jeremias terminou de proclamar ao povo todas as palavras que Yahweh, seu Deus, o mandou dizer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Azarias, filho de Hosaías, Joanã, filho de Careá, e todos os homens arrogantes disseram para Jeremias: \"Tu estás dizendo mentiras. Yahweh, nosso Deus, não te enviou para dizer: \'Não entreis no Egito para viverdes lá.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Mas é Baruque, filho de Nerias, que está te incitando contra nós, para nos entregar nas mãos dos caldeus, para que causem nossa morte e nos façam cativos na Babilônia.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Então, Joanã, filho de Careá, todos os príncipes do exército e todas as pessoas, desobedeceram à voz de Yahweh e habitaram na terra de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Joanã, filho de Careá e todos os comandantes dos exércitos tiraram todos os remanescentes de Judá, que retornaram das nações para onde eles foram dispersados, para viverem na terra de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Eles tiraram os homens e as mulheres, as crianças e as filhas do rei, e toda pessoa a quem Nebuzaradã, o capitão da guarda do rei, havia deixado permanecer com Gedalias, filho de Aicam, filho de Safã. Eles também tiraram Jeremias, o profeta, e Baruque, filho de Nerias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'Eles foram à terra do Egito, à Tafnes, porque desobedeceram à voz de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Então, a palavra de Yahweh veio a Jeremias, em Tafnes, e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, '\"Pega algumas pedras largas em tuas mãos e, à vista do povo de Judá, esconda-as no pavimento de cimento, na entrada da casa de Faraó, em Tafnes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'Então, dize-lhes: \'Assim diz Yahweh dos Exércitos, Deus de Israel: Vede, Eu estou prestes a enviar mensageiros e trazer Nabucodonosor, rei da Babilônia, Meu servo. Colocarei seu trono sobre essas pedras que tu, Jeremias, enterraste. Nabucodonosor colocará seu pavilhão real sobre elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Pois ele virá e atacará a terra do Egito. Qualquer um que estiver destinado à morte, será entregue à morte. Qualquer um que estiver destinado ao cativeiro, será levado cativo. E qualquer um que estiver destinado à espada, será entregue à espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Então, Eu colocarei fogo nos templos dos deuses do Egito. Nabucodonosor os queimará ou os capturará. Ele limpará a terra do Egito, assim como os pastores limpam os insetos de suas vestes. Ele sairá daquele lugar intacto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Quebrará os pilares sagrados de Bete-Semes na terra do Egito. Ele queimará os templos dos deuses egípicios.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Esta é a palavra que veio a Jeremias, concernente aos judeus que viviam na terra do Egito, os que estavam em Migdol, Tafnes, Mênfis e na terra de Patros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Assim diz Yahweh dos Exércitos, Deus de Israel: \"Vós mesmos tendes visto todos os desastres que Eu trouxe sobre Jerusalém e sobre todas as cidades de Judá. Vede, elas hoje são ruínas. Não há ninguém que viva nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Isto é por causa das coisas iníquas que eles fizeram para Me ofenderem, queimando incenso e adorando outros deuses. Esses eram deuses que nem eles mesmos, nem vós, nem os vossos antepassados conhecestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Então, repetidamente, enviei a eles todos os Meus servos, os profetas. Eu os enviei para dizer: \'Parem de fazer essas coisas abomináveis que Eu odeio.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Mas eles não ouviram, recusaram-se a prestar atenção e não se converteram da sua iniquidade em queimar incenso a outros deuses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Então, a Minha fúria e a Minha ira se derramaram, acendendo uma fogueira nas cidades de Judá e nas ruas de Jerusalém, tornando-as em ruínas e devastações até o dia de hoje.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Agora, assim diz Yahweh, o Deus dos Exércitos, o Deus de Israel: \"Por que estais cometendo grandes iniquidades contra vós mesmos? Por que estais causando a exterminação de Judá, homens e mulheres, crianças e bebês? Nenhum remanescente restará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Pela vossa iniquidade tens Me ofendido com as obras de vossas mãos, ao queimardes incenso a outros deuses na terra do Egito, onde vivestes. Fostes para lá para serdes destruídos, então, sereis uma maldição e um opróbrio entre todas as nações da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Esquecestes das iniquidades cometidas por vossos antepassados e as iniquidades cometidas pelos reis de Judá e suas esposas? Esquecestes das maldades cometidas por vós mesmos e vossas esposas nas terras de Judá e nas ruas de Jerusalém?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Até hoje, eles ainda não se humilharam. Eles não honraram a Minha lei e o decreto que Eu estabeleci diante deles e de seus antepassados, e também não andaram neles.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Portanto, assim diz Yahweh dos Exércitos, Deus de Israel: Vede, Eu estou a ponto de virar a Minha face contra vós e vos trazer desastre para destruir todos de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Removerei o remanescente de Judá que decidiu ir à terra do Egito para viver lá. Eu farei isso, de modo que todos eles perecerão na terra do Egito. Eles cairão pela espada e pela fome. Do menor ao maior, eles perecerão pela espada e pela fome. Eles morrerão e se tornarão objeto de blasfêmia, maldição, opróbrio e uma coisa horrível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Eu castigarei o povo que habita na terra do Egito, assim como Eu puni Jerusalém com a Minha espada, com a fome e com a praga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Nenhum fugitivo ou sobrevivente dos remanescentes de Judá que foram viver na terra do Egito retornarão para a terra de Judá, mesmo que queiram voltar a viver lá. Nenhum deles retornará, com exceção dos poucos que escaparão.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Então, todos os homens que sabiam que suas esposas queimavam incenso a outros deuses, e todas as mulheres que estavam na grande assembleia, e todo o povo que estava vivendo na terra do Egito, em Patros, responderam a Jeremias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'dizendo: \"Sobre a palavra que falaste em nome de Yahweh, nós não te ouviremos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Certamente, faremos todas as coisas que dissemos que faríamos: queimar incenso para a Rainha dos Céus e derramar libações para ela, assim como os nossos antepassados, nossos reis e nossos líderes fizeram nas cidades de Judá e nas ruas de Jerusalém. Então, seremos fartos com comida e prosperaremos, sem experimentar nenhum desastre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Quando nos abstivemos de fazer estas coisas, de oferecer incenso à Rainha dos Céus e derramar ofertas de libações para ela, todos sofremos com a pobreza e estávamos morrendo pela espada e pela fome.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'As mulheres disseram: \"Quando estávamos ofertando incenso diante da Rainha dos Céus e derramando ofertas de libações para ela, acaso foi contra a vontade de nossos maridos que fizemos essas coisas, fazendo bolos à sua imagem e derramando oferendas de libações para ela?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Então, Jeremias disse a todo o povo, aos homens e às mulheres, e a todas as pessoas que lhe responderam, proclamando:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, '\"Yahweh não se lembraria dos incensos que vós queimastes nas cidades de Judá e nas ruas de Jerusalém, vós e vossos antepassados, vossos reis, vossos líderes e o povo dessa terra? Pois o Senhor chama isso à memória e isso vem aos Seus pensamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Ele não poderia mais suportar isso, por causa das vossas práticas iníquas e das abominações que cometestes. Por isso, a vossa terra tornou-se uma desolação, um horror, e uma maldição; por causa disso, não há nenhum habitante até os dias de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Porque vós queimastes incenso, pecastes contra Yahweh e não quisestes ouvir à Sua voz, Sua lei, Seus estatutos e os decretos da Sua aliança. Este desastre tem acontecido contra vós, até os dias de hoje.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Jeremias, disse a todo o povo e a todas as mulheres: \"Ouvi a palavra de Yahweh, todos de Judá que estão na terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Assim diz Yahweh dos Exércitos, Deus de Israel: \'Vós e as vossas esposas falastes com as bocas e cumpristes com as mãos, dizendo: Certamente cumpriremos os votos que fizemos de adorar à Rainha dos Céus e derramar ofertas de libações a ela. Agora, fazei o que prometestes, cumpri os vossos votos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Agora, ouvi a palavra de Yahweh, todos de Judá que habitais na terra do Egito: Vede, Eu tenho jurado pelo Meu grande nome, diz Yahweh. Meu nome não será chamado pela boca de qualquer um dos homens de Judá em toda a terra do Egito, vós que agora dizeis: assim como o Senhor Yahweh vive.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Vede, Eu estou vos vigiando para o desastre e não para o bem. Cada pessoa de Judá na terra do Egito perecerá pela espada e pela fome até que todos sejam consumidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Então, os sobreviventes da espada retornarão da terra do Egito para a terra de Judá, apenas um pequeno número deles. Todos os remanescentes de Judá que foram à terra do Egito para viverem lá saberão qual a palavra que se tornará realidade: a Minha ou a deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Este será o sinal para vós – esta é a declaração de Yahweh – Eu vos castigarei neste lugar. Certamente, sabereis que as Minhas palavras virão contra vós com desastre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Assim diz Yahweh: Vede, Eu estou prestes a entregar Faraó Hofra, rei do Egito, nas mãos dos seus inimigos e daqueles que o perseguem. E será como Eu entreguei a Zedequias, rei de Judá, nas mãos de Nabucodonosor, rei da Babilônia, seu inimigo que procurava matá-lo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Esta é a palavra que Jeremias, o profeta, disse a Baruque, filho de Nerias, quando este escreveu no rolo as palavras de Jeremias — isto foi no quarto ano de Jeoaquim, filho de Josias, rei de Judá – ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, '\"Yahweh, Deus de Israel, diz isto para ti, Baruque:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Tu dissestes: \'Ai de mim, pois Yahweh acrescentou agonia à minha dor. Meu gemido me cansou; eu não encontro descanso.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Isso é o que deves dizer: Yahweh diz isto: Vê, o que Eu construí, agora destruo. O que Eu plantei, agora arranco. Farei isto em toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Mas esperas grandes coisas para ti mesmo? Não esperes por isso, pois vem desastre sobre toda a humanidade — esta é a declaração de Yahweh — mas Eu te dou a tua vida como teu despojo por onde quer que fores.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Esta é a palavra de Yahweh que veio a Jeremias, o profeta, a respeito das nações,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'para o Egito: \"Isto é sobre o exército do Faraó Neco, rei do Egito, que estava em Carquêmis, junto ao rio Eufrates. Este era o exército que Nabucodonosor, rei da Babilônia, derrotou no quarto ano de Jeoaquim, filho de Josias, rei de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Preparai os pequenos e os grandes escudos, e ide adiante para lutar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Colocai as selas nos cavalos e montai neles, vós cavaleiros. Tomai vossos lugares com capacetes nas cabeças. Afiai as lanças e colocai vossa armadura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'O que Eu estou vendo aqui? Eles estão cheios de terror e estão fugindo, pois seus soldados estão derrotados. Eles estão correndo por segurança e não estão olhando para trás. O terror está por toda parte — esta é a declaração de Yahweh —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'o rápido não pode fugir, e os soldados não podem escapar. Eles tropeçam no norte e caem junto ao rio Eufrates.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Quem é este que sobe como o Nilo, quando as águas se agitam e caem como os rios?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'O Egito sobe como o Nilo, e suas águas se agitam e caem como os rios. E o Egito diz: \'Eu subirei; eu cobrirei a terra; eu destruirei cidades e seus habitantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Avançai, cavalos. Ficai zangadas, carruagens. Que os soldados avancem, Etiópia e Líbia, homens habilidosos com o escudo; e Lídia, homens habilidosos em usar seus arcos.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Esse dia será o Dia da Vingança do Senhor Yahweh dos Exércitos, e Ele Se vingará de Seus inimigos. A espada devorará e ficará satisfeita. Ela beberá do sangue deles. Pois haverá um sacrifício ao Senhor Yahweh dos Exércitos na terra do norte, junto ao rio Eufrates.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Avança para Gileade e consegue remédios, filha virgem do Egito. É inútil colocar muito remédio em ti mesma. Não há cura para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'As nações têm ouvido de tua vergonha. A terra está cheia com teus lamentos, pois tropeçam soldado contra soldado; ambos caem juntos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Essa é a palavra que Yahweh disse a Jeremias, o profeta, quando Nabucodonosor, rei da Babilônia veio e atacou a terra do Egito:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, '\"Anuncia no Egito e proclama em Migdol, Mênfis, e Tafnes. Posiciona-te e prepara-te, pois a espada está devorando tudo à tua volta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Por que teus poderosos estão de bruços no chão? Não resistirão, porque Eu, Yahweh, os abati.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Ele aumenta o número daqueles que tropeçam. Os soldados caem uns sobre os outros. Eles estão dizendo: \'Levantai-vos. Deixai-nos voltar para casa. Deixai-nos voltar para nosso próprio povo, para nossa terra nativa. Permiti que deixemos esta espada que está nos abatendo.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Ali, eles dirão: \'Faraó, o rei do Egito, só faz barulho; deixou passar a sua oportunidade.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Como vivo Eu — declara o Rei, cujo nome é Yahweh dos Exércitos — alguém virá, que é como monte Tabor e Carmelo, pelo mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Estai prontos vós mesmos e vossas bagagens para o cativeiro, vós que viveis no Egito. Pois Mênfis se tornará uma desolação e uma destruição e, por isso, ninguém viverá lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'O Egito é uma bonita novilha, mas um inseto que machuca vem do norte. Ele está vindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Os soldados mercenários em seu meio estão como um touro engordado, mas eles também vão se afastar e fugir. Eles não ficarão juntos, pois o dia de seu desastre está vindo contra eles, o tempo de sua punição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'O Egito chia e rasteja como uma cobra, pois seus inimigos estão marchando contra ele. Eles estão indo em sua direção, como cortadores de lenha com machados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Eles cortarão as florestas, embora seja impenetrável — esta é a declaração de Yahweh. Pois os inimigos serão mais numerosos do que gafanhotos, incapazes de serem contados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'A filha do Egito será envergonhada; será entregue nas mãos do povo do norte.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Yahweh dos Exércitos, o Deus de Israel, diz: \"Vede, Eu estou a ponto de punir Amom, de Tebas, Egito e seus deuses; seus reis, os faraós, e aqueles que confiam neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Eu estou entregando-lhes nas mãos dos que procuram suas vidas, e na mão de Nabucodonosor, rei da Babilônia, e seus servos. Então, depois disso, o Egito será habitado como nos dias anteriores — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Mas tu, Meu servo Jacó, não temas. Não desanimes, Israel, pois vê, Eu estou a ponto de trazer-te de volta de tão longe, e tua descendência da terra de seus cativos. Então, Jacó retornará, encontrará paz, e estará seguro, e não haverá ninguém para aterrorizá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Tu, Meu servo Jacó, não temas — esta é a declaração de Yahweh. Pois Eu sou contigo. Eu trarei completa destruição contra todas as nações de onde Eu te dispersei. Mas não te destruirei completamente. Ainda irei disciplinar-te justamente. É certo que não te deixarei impune.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Esta é a palavra de Yahweh que veio para Jeremias, o profeta, a respeito dos Filisteus. Esta palavra veio antes do ataque de Faraó a Gaza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Yahweh diz: \"Vede! Dilúvios estão se levantando no norte. Eles serão como um rio transbordando! Eles inundarão a terra e tudo o que há nela, suas cidades e seus habitantes! Todos gritarão por socorro, e todos as habitantes lamentarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Ao som do estrondo dos cascos de fortes cavalos, ao rugido dos suas carruagens e ao ruído de suas rodas, pais não ajudarão seus filhos por causa de suas próprias fraquezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'Pois o dia está vindo em que devastará todos os Filisteus, para eliminar de Tiro e de Sidom todo sobrevivente que quiser ajudá-los. Pois Yahweh está devastando os Filisteus, aqueles que restam na ilha de Caftor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Rasparão a cabeça em Gaza. Quanto a Asquelom, as pessoas que são deixadas em seu vale ficarão em silêncio. Até quando retalharás o próprio corpo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Ah, espada de Yahweh! Quanto tempo será até que te silencies? Volta para a tua bainha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Como podes ficar em silêncio? Pois Yahweh deu ordens a ti. Ele te enviou para atacar Asquelom e o litoral.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Sobre Moabe, Yahweh dos Exércitos, Deus de Israel, diz: \"Ai de Nebo, porque foi devastada. Quiriataim foi capturada e envergonhada. Sua fortaleza foi esmagada e desgraçada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'A honra de Moabe não mais existe. Seus inimigos em Hesbom planejaram um desastre contra ela. Eles disseram: \'Vinde e vamos destruí-la como nação. Homens loucos também perecerão. Uma espada irá atrás de ti.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Ouvi! Um som de grito vem de Horonaim, onde há ruína e grande destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moabe foi destruída e o choro de seus filhos foi ouvido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Eles sobem a colina de Luíte chorando, pois no caminho de Horonaim gritos são ouvidos por causa da destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Fugi! Salvai vossas vidas e vos torneis como árvores de zimbro no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Por causa da confiança em vossas obras e riquezas, vós também sereis capturados. Então, Quemós sairá para o cativeiro junto com os seus sacerdotes e líderes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Porque o destruidor virá a cada cidade e nenhuma delas escapará. O vale perecerá e a planície será devastada, como Yahweh disse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Dai asas a Moabe, pois ela, certamente, sairá voando. Suas cidades se tornaram em terrenos baldios, onde não há ninguém para viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Qualquer preguiçoso em fazer a obra de Yahweh será amaldiçoado! Qualquer que retiver sua espada para derramar sangue será amaldiçoado!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Moabe se sente seguro desde que era jovem. Ele é como seu vinho que nunca foi derramado de vasilha em vasilha. Ele nunca foi para o cativeiro. Portanto, tem gosto bom, como sempre, e seu sabor permanece inalterado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Vede, os dias vêm – esta é a declaração de Yahweh – quando Eu enviarei a ele aqueles que o derrubarão, derramarão todas as suas panelas e quebrarão os seus potes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Então, Moabe terá vergonha de Quemós da mesma forma que Israel teve vergonha de Betel, sua confiança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Como podes tu dizer: \'Nós somos soldados, poderosos homens de luta\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Moabe será devastada e suas cidades atacadas. Pois os melhores jovens foram para o local de abate –Essa é a declaração do Rei! Yahweh dos Exércitos é o Seu Nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'O desastre de Moabe está prestes a acontecer; a calamidade corre rapidamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Todos vós, que estais ao redor de Moabe, gemei. E vós, todos os que conhecem sua fama, gritai: \'Ai, o bastão forte e a vara honrada se quebraram.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Desce do teu lugar honrado e senta-te em terra seca, tu, filha moradora de Dibom. Porque o destruidor de Moabe te ataca; aquele que destruirá tuas fortalezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Ficai em pé na estrada e observai, vós, povo que vive em Aroer. Perguntai àqueles que estão fugindo e escapando: \'O que está havendo?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moabe foi envergonhado, pois foi destruído. Ruído e lamento; gritos por ajuda. Dizei ao povo às margens do rio Arnom que Moabe está devastada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Agora, a punição veio sobre a terra do planalto, sobre Holom, Jaza, Mefaate,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Dibom, Nebo, Bete-Diblataim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Quiriataim, Bete-Gamul, Bete-Meom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Queriote, Bozra e todas as cidades na terra de Moabe, as cidades distantes e as próximas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'O chifre de Moabe foi cortado; seu braço foi quebrado — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Embriagai-o, porque agiu orgulhosamente contra Yahweh. Que Moabe se revolva no seu vômito; deixai que ele se torne objeto de riso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Pois Israel não se tornou um objeto de riso para vós? Israel foi encontrado entre ladrões, para que, frequentemente, balanceis vossa cabeça ao falar dele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Abandonai as cidades e acampai nos penhascos, habitantes de Moabe. Sede como uma pomba, que faz o ninho nas beiras seguras dos penhascos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Nós temos ouvido sobre a soberba de Moabe, sua arrogância, sua altivez, seu orgulho, sua vanglória e o conceito em seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Esta é a declaração de Yahweh — Eu mesmo conheço seu discurso desafiador, o qual equivale a nada, como seus atos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Então, Eu vou uivar e lamentar por Moabe, e gritar em socorro por todos de Moabe. Eu lamentarei pelas pessoas de Quir-Heres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Chorarei por ti mais do que chorei por Jazer, vinha de Sibma! Teus ramos passaram pelo mar de sal e chegaram tão longe quanto Jazer. Os destruidores atacaram teu fruto de verão e tua vinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Então, celebração e regozijo foram tirados das árvores frutíferas e da terra de Moabe. Eu coloquei um fim para o vinho de seus lagares. Eles não pisarão com gritos de alegria. Quaisquer gritos não serão gritos de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Desde os gritos em Hesbom, tanto quanto em Elealé, seu som é ouvido até Jaza, de Zoar até Horonaim e Eglate-Silíssia, uma vez que mesmo as águas do Ninrim secaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Porque eu colocarei um fim a qualquer um, em Moabe, que faça sacrifícios em santuários e a qualquer um que queime incenso aos seus deuses — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Meu coração está lamentando por Moabe como uma flauta. Meu coração está lamentando como flautas pelas pessoas de Quir-Heres. As riquezas que eles ganharam se foram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Pois toda cabeça é calva e toda barba, raspada. Incisões estão em cada mão, e panos de saco estão em volta de suas cinturas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Há luto em todos os lugares, nos telhados e nas praças de Moabe, pois Eu destruí Moabe como vasos que ninguém quer — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Como tem sido destruído! Como eles uivam em suas lamentações! Moabe deu as costas em vergonha! Então, Moabe se tornará um objeto de escárnio e terror para todos aqueles que estão ao redor dele.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Yahweh diz: \"Vê, o inimigo virá voando como uma águia, estendendo suas asas sobre Moabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Queriote foi capturado, e suas fortalezas foram conquistadas. Porque naquele dia, o coração dos soldados de Moabe serão como o coração de mulheres em dores de parto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Então, Moabe será destruído para que não seja mais povo, uma vez que ele se engrandeceu contra Mim, Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Terror, cova e armadilha estão vindo sobre vós, habitantes de Moabe — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Qualquer um que fugir por causa do terror cairá na cova, e qualquer um que escalar a cova será capturado na armadilha, pois Eu os trarei isso no ano da Minha vingança contra eles — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Aqueles que fogem ficarão na sombra de Hesbom, sem qualquer força, pois o fogo sairá de Hesbom, e a chama do meio de Siom para devorar a fronte de Moabe e o topo das cabeças do povo prepotente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Ai de ti, Moabe! O povo de Quemós está destruído, pois seus filhos são levados como cativos e suas filhas para o cativeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Mas Eu restaurarei as fortunas de Moabe nos últimos dias – Esta é a declaração de Yahweh.\" O julgamento sobre Moabe termina aqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'A respeito do povo amonita, Yahweh diz isto: \"Israel não tem filhos? Não há nenhum herdeiro em Israel? Por que Milcom ocupa Gade, e seu povo vive nessas cidades?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Esta é a declaração de Yahweh: Vede, dias virão quando Eu soar o sinal da batalha contra Rabá (entre os amonitas), a qual virá a ser um montão de ruínas e suas vilas serão incendiadas. Pois Israel possuirá todos os que o possuíram\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Uiva e lamenta, Hesbon, pois Ai será devastada! Gritai, filhas de Rabá! Vesti pano de saco. Lamentai e dai voltas pelos muros, pois Milcom está indo para o cativeiro, junto com seus sacerdotes e líderes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Por que estás orgulhosa da tua força? Tua força escoará pelo caminho, filha rebelde, tu que confias em tua riqueza. Tu dizes: \'Quem virá contra mim?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Vê, Eu estou prestes a trazer terror sobre ti — essa é a declaração de Yahweh, o Senhor dos Exércitos. Esse terror virá de todos os que estão à tua volta. Cada um de vós será disperso diante disso. Não haverá ninguém para reunir todos os que estão fugindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Mas, depois disso, restaurarei a sorte do povo amonita — essa é a declaração de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Sobre Edom, Yahweh dos Exércitos diz isto: \"Não há mais sabedoria a ser encontrada em Temã? Os bons conselhos desapareceram para todos os que têm entendimento? Toda sabedoria foi corrompida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fugi! Retornai! Ficai em buracos no chão, habitantes de Dedã. Pois trarei o desastre de Esaú sobre ele, no momento em que Eu o punir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Se colhedores de uva viessem a ti, eles não deixariam um pouco para trás? Se ladrões viessem à noite, não levariam somente o quanto procuravam?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Mas Eu despojei Esaú nu. Revelei seus lugares escondidos. Então, ele não será capaz de se esconder. Seus filhos, seus irmãos e seus vizinhos estão destruídos, e ele se foi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Deixa teus órfãos para trás, Eu os guardarei em vida, e tuas viúvas podem confiar em Mim.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Pois Yahweh diz isto: \"Vede, todos os que não merecem isso, certamente, devem beber deste copo. Tu pensas que irás livrar-te da punição? Não irás, pois certamente, beberás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Pois Eu tenho jurado por Mim mesmo – esta é a declaração de Yahweh – que Bozra se tornará em horror, em desgraça, em devastação, em objeto de maldição. Todas as cidades se tornarão em devastação, para sempre.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Eu ouvi notícias de Yahweh e a mensagem que foi enviada às nações: \'Ajuntai-vos todos e atacai-a. Preparai-vos para a batalha\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, '\"Pois, vede, Eu te fiz pequena, comparada a outras nações, desprezada pelo povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Quanto ao medo que tens causado, o orgulho do teu coração tem te enganado, tu que habitas nos penhascos, que ocupas as altas colinas, de modo que podes fazer teu ninho como uma águia. Eu te trarei para baixo — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Edom se tornará em horror para todos os que passarem por ele. Todos tremerão e assobiarão por causa desses desastres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Como a destruição de Sodoma e Gomorra e suas vizinhas, diz Yahweh, ninguém viverá lá; nenhuma pessoa ficará lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Vede, ele irá para cima como um leão vindo da floresta de verdes pastagens do Jordão. Pois eu, rapidamente, farei Edom correr de lá e colocarei no comando alguém que escolherei. Pois quem é semelhante a Mim e quem Me convocará? Qual pastor é capaz de resistir a Mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Então, escuta os planos que Yahweh decidiu contra Edom, os planos que Ele formou contra os habitantes de Temã. Eles, certamente, serão arrastados no caminho, até mesmo o menor rebanho. Suas pastagens se tornarão em ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Ao som de sua queda a terra estremece. O som dos gritos angustiados são ouvidos até o mar Vermelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Vede, alguém atacará, rapidamente, como uma águia, descerá e abrirá suas asas sobre Bozra. Então, naquele dia, os corações dos soldados de Edom se tornarão como o coração de uma mulher em dores de parto.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'A respeito de Damasco: \"Hamate e Arpade serão envergonhados, pois eles têm ouvido notícias do desastre. Estão assustados! Eles se tornaram perturbados como o mar, que não pode ficar calmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damasco se tornou muito frágil. Isso a fez fugir, acometida de terror! Aflição e dor tomou para si, como a dor de uma mulher dando à luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Como está abandonada a cidade do louvor, a cidade da minha alegria!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Portanto, esses jovens homens cairão nessas praças e todos os guerreiros perecerão naquele dia — esta é a declaração de Yahweh dos Exércitos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Pois, no muro de Damasco, atearei fogo que devorará as fortalezas de Ben-Hadade.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Sobre Kedar e os reinos de Hazor que Nabucodonosor, rei da Babilônia, feriu, Yahweh diz isto: \"Levantai e atacai Quedar e destruí todo o povo do Oriente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Eles pegarão suas tendas e seus rebanhos, as cortinas de suas tendas e todo o seu equipamento; seus camelos serão levados e os homens lhes gritarão: \'O terror está ao redor!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Fugi! Ide para um caminho distante! Ficai nos buracos no chão, habitantes de Hazor — esta é a declaração de Yahweh — pois Nabucodonosor, rei da Babilônia, idealizou um plano contra vós. Fugi! Retornai!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Levantai! Atacai a nação tranquila, que habita em segurança, diz Yahweh. Eles não têm portões ou trancas e seu povo vive por si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Pois seus camelos e a abundância de suas propriedades se tornarão em despojo. Então, Eu espalharei ao vento todos os que cortam as pontas dos seus cabelos e Eu trarei desastre de todos os lados — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Hazor se tornará um covil de chacais, uma terra permanentemente vazia. Ninguém viverá lá; nenhum ser humano ficará lá.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Esta é a palavra de Yahweh que veio a Jeremias, o profeta, sobre Elão. Isto aconteceu no início do reinado de Zedequias, rei de Judá, e ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, '\"Yahweh dos Exércitos diz isto: Vede, Eu estou prestes a quebrar o arqueiro de Elão, a fonte do seu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Pois Eu trarei os quatro ventos dos quatro cantos da terra e Eu espalharei o povo de Elão ao vento. Não há nação para a qual os que foram dispersos de Elão não irão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Então, Eu despedaçarei Elão diante dos seus inimigos e diante de todos os que procuram sua vida. Pois Eu trarei desastre contra eles, a fúria da Minha ira — esta é a declaração de Yahweh. Enviarei a espada atrás deles até que Eu os tenha aniquilado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Então, colocarei Meu trono em Elão e destruirei o rei e os líderes de lá —esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'E acontecerá, nos últimos dias, que Eu mudarei a sorte de Elão — esta é a declaração de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Esta é a palavra que Yahweh declarou a respeito da Babilônia, a terra dos babilônios, pela mão de Jeremias, o profeta:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, '\"Relatai às nações e fazei com que escutem. Levantai um sinal e fazei com que ouçam. Não escondais isto. Dizei: \'A Babilônia está tomada, Bel está humilhado, Marduque está desanimada. Seus ídolos estão humilhados; suas imagens estão assustadas.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'A nação do norte se levantará contra ela para transformá-la numa terra desolada. Ninguém, nem homem ou fera, viverá nela. Eles fugirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'Naqueles dias e naquele tempo, o povo de Israel e o povo de Judá voltarão, reunidos e em choro, à procura de Yahweh, seu Deus – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Eles perguntarão o caminho para Sião e irão em direção a ela. Eles se juntarão para Yahweh, em uma eterna aliança que não será esquecida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Meu povo era como ovelhas perdidas. Seus pastores as desviavam nas montanhas; eles as fizeram errar de colina a colina. Elas foram e se esqueceram do lugar onde viveram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Todos os que foram até elas as devoraram. Seus adversários disseram: \'Nós não somos culpados, porque elas pecaram contra Yahweh, seu verdadeiro lar; Yahweh, a esperança de seus ancestrais.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Deixai o meio da Babilônia; saí da terra dos babilônios; sede como bodes que vão antes do resto do rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Pois, vede, estou prestes a movimentar e levantar um grupo de grandes nações do norte contra a Babilônia. Eles se vingarão contra ela. Babilônia será capturada de lá. Suas flechas são como um guerreiro habilidoso, que não volta de mãos vazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'A Babilônia será saqueada. Todos aqueles que a saquearem ficarão satisfeitos –Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Regozijai-vos, celebrai, ó saqueadores da minha herança; pulai ao redor como um bezerro em seu pasto; relinchai como um cavalo poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Então, vossa mãe será grandemente envergonhada; aquela que vos concebeu ficará envergonhada. Vede! ela será a menor das nações, um deserto, uma terra seca, um ermo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Por causa da vingança de Yahweh, a Babilônia não ficará inabitada, mas será completamente devastada. Todos os que passarem por ali estremecerão por causa da Babilônia e gemerão por causa de todas as suas feridas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Ajeitai-vos contra a Babilônia, ao redor dela. Todos os que inclinam seus arcos devem atirar nela. Não fique para trás nenhuma de suas flechas, pois ela tem pecado contra Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Gritai vitória contra ela, todos em sua volta! Ela já rendeu seu poder; suas torres caíram; suas paredes estão no chão, pois essa é a vingança de Yahweh. Tomai vingança nela! Fazei a ela assim como ela fez às outras nações!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Destruí o semeador e aquele que usa a foice no tempo da colheita na Babilônia. Que cada pessoa volte para seu próprio povo, por causa da espada do opressor, e fuja para sua própria terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israel é uma ovelha desgarrada e guiada por leões. Primeiro, o rei da Assíria o devorou e, depois disso, Nabucodonosor, rei da Babilônia, quebrou seus ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Portanto, Yahweh dos Exércitos, o Deus de Israel, diz assim: Vede! Eu estou prestes a punir o rei da Babilônia e sua terra, assim como Eu puni o rei da Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Eu restaurarei Israel e sua terra natal; ele pastará no Carmelo e em Basã. Então, ele ficará satisfeito nas regiões montanhosas de Efraim e Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'Naqueles dias e naquele tempo, diz Yahweh, iniquidade será procurada em Israel, mas nada será encontrada. Eu perguntarei sobre os pecados de Judá, mas nenhum será encontrado. Pois Eu perdoarei os remanescentes que eu poupar.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Subi contra a terra de Merataim, contra ela e os habitantes de Pecode. Colocai-os à espada e preparai-os para a destruição. Fazei tudo o que Eu vos mando – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Os sons da batalha e uma enorme destruição estão na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Como o martelo de todas as terras tem sido cortado fora e destruído, como a Babilônia tem-se tornado um terror entre as nações,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Eu tenho preparado uma armadilha para vós. Tu foste capturada, Babilônia, e não sabes disso! Foste encontrada e capturada, porque se opôs a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Yahweh abriu Seu arsenal e tirou os instrumentos da Sua ira. Há uma obra para o Senhor Yahweh dos Exércitos na terra dos babilônios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Atacai-a de longe. Abri seus celeiros e amontoai-a como montes de grãos. Preparai-a para destruição. Não deixeis remanescentes dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Matai todos os seus bois. Mandai-os para o lugar de matança. Ai deles, pois seu dia chegou, tempo de sua punição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Há o som daqueles que fogem, daqueles que são sobreviventes, da terra da Babilônia. Esses relatarão a vingança de Yahweh, nosso Deus, para Sião, e vingança para Seu templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Convocai os arqueiros contra a Babilônia, todos aqueles que inclinam seus arcos. Acampai ao redor dela, e não deixeis que ninguém escape. Retribuí a ela pelo que tem feito. Fazei a ela na mesma proporção que ela fez, pois ela tem desafiado Yahweh, o único Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Então, seus homens jovens cairão nas praças da cidade, e todos os seus homens de guerra serão destruídos nesse dia – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Vede! Eu estou contra ti, ó orgulhosa, pois teu dia chegou, ó orgulhosa, o tempo em que Eu irei punir-te. Esta é a declaração do Senhor Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Então, os orgulhosos tropeçarão e cairão. Ninguém os levantará. Eu acenderei um fogo em suas cidades; ele devorará tudo em sua volta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Yahweh dos Exércitos diz assim: O povo de Israel está oprimido, juntamente com o povo de Judá. Todos aqueles que os capturaram ainda os mantêm; eles se recusaram a deixá-los ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'O único que os resgata é forte. Yahweh dos Exércitos é Seu nome. Ele, verdadeiramente, defenderá a causa deles, para trazer descanso à terra, e trará inquietação aos habitantes da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Uma espada está contra os babilônios; contra os habitantes da Babilônia, seus líderes, e seus homens sábios – Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Uma espada está vindo contra aqueles que dizem palavras de adivinhação, assim como para aqueles que se revelam como tolos. Uma espada está vindo contra seus soldados, e eles se encherão de terror.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Uma espada está vindo contra seus cavalos, suas carruagens e todo o povo que está no meio da Babilônia, e eles se tornarão como mulher. Uma espada está vindo contra seus tesouros, e eles serão saqueados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Uma estiagem está vindo sobre suas águas e elas ficarão secas. Pois ela é a terra de ídolos inúteis, e eles agem como loucos por seus ídolos inúteis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Então, bestas do deserto, junto com os chacais, habitarão ali, e os jovens avestruzes viverão nela. Pois em todo o tempo, ela não será habitada. De geração em geração, ela não será moradia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Assim como Deus destruiu Sodoma e Gomorra e seus vizinhos, ninguém viverá ali, nenhuma pessoa ficará nela – esta é a declaração de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, '\"Vede, um povo vem do norte, pois uma grande nação e muitos reis foram despertados de uma terra distante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Eles pegarão arcos e lanças. Eles são cruéis e não têm compaixão. O som dele é como o rugido do mar e, como homens de guerra, eles estão cavalgando em formação contra ti, filha da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'O rei da Babilônia ouviu o seu relato e suas mãos enfraqueceram. A angústia o apreendeu como a uma mulher em parto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Contemplai! Ele sobe como um leão das margens do rio Jordão para o local de pastagem permanente. Pois Eu irei, rapidamente, fazer com que eles fujam de lá, e colocarei alguém que será escolhido para o comando. Pois quem é semelhante a Mim e quem Me convocará? Que pastor é capaz de Me resistir?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Portanto, ouvi os planos que Yahweh estabeleceu contra a Babilônia, os planos que Ele planejou contra a terra dos babilônios. Eles, certamente, serão arrastados, até mesmo o menor rebanho. Seus pastos se tornarão lugares de ruína.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Ao som da conquista da Babilônia a terra estremece, e seu grito de aflição é ouvido entre as nações.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Yahweh diz: \"Vede, estou prestes a despertar um vento de destruição sobre a Babilônia e sobre aqueles que vivem nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Eu enviarei estrangeiros à Babilônia. Eles irão espalhar e devastar a terra, pois virão sobre ela de todos os lados, no dia do desastre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Não deixeis que os arqueiros dobrem seus arcos; não deixeis que eles coloquem armadura. Não poupeis os jovens; destruí todo o seu exército,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Pois os feridos cairão na terra dos caldeus; aqueles que morrerem cairão em suas ruas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Porque Israel e Judá não foram abandonados pelo seu Deus, por Yahweh dos Exércitos, ainda que a terra deles esteja cheia de ofensas cometidas contra o Santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Fugi do meio da Babilônia; deixai que cada homem salve a si mesmo. Não pereçais na iniquidade dela, pois este é o tempo da vingança de Yahweh. Ele lhe dará a sua paga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'A Babilônia era uma taça de ouro na mão de Yahweh, que fez toda a terra embriagada; nações beberam seu vinho e se tornaram insanas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'A Babilônia cairá de repente, e será destruída. Lamentai por ela! Dai a ela remédios para sua dor; talvez ela possa ser curada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, '\'Nós desejávamos curar a Babilônia, porém ela não foi curada. Deixai-a e vamo-nos para nossa própria terra. Pois sua culpa alcança os céus; está acumulada até as nuvens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Yahweh declarou nossa inocência. Vinde, contemos em Sião os atos de Yahweh nosso Deus.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Afiai as flechas e pegai os escudos. Yahweh está agitando o espírito do rei da Média em um plano para destruir a Babilônia. Isto é por causa da vingança de Yahweh, vingança pela destruição de Seu Templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Levantai a bandeira sobre os muros da Babilônia; colocai os guardas; posicionai as sentinelas; preparai as emboscadas, pois Yahweh fará o que planejou. Ele fará o que tem anunciado contra os habitantes da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Tu, povo que vive próximo a muitas correntes de água, povo que és rico com tesouros; teu fim chegou. O fio de tua vida é, agora, encurtado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Yahweh dos Exércitos jurou por Sua própria vida: \'Eu vos encherei de inimigos, como uma praga de gafanhotos; eles levantarão um grito de guerra contra vós.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Ele fez a terra por Seu poder; Ele colocou o mundo no lugar por Sua sabedoria. Por Seu entendimento, estendeu os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Quando Ele brada como trovão, há o rugido das águas nos céus, pois Ele traz as nuvens dos confins da terra. Ele faz os relâmpagos para a chuva e envia o vento de Seus tesouros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Todo homem torna-se como um animal absolutamente ignorante; todo ferreiro é envergonhado por seus ídolos. Seus ídolos fundidos e derramados são fraudes; não há vida neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Eles são inúteis, trabalho dos zombadores; eles perecerão no tempo de sua punição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Mas Deus, a porção de Jacó, não é como eles, pois Ele é quem molda todas as coisas. Israel é a tribo de Sua herança; Yahweh dos Exércitos é o Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Tu, Babilônia, és Meu martelo de guerra, Minha arma para a batalha. Contigo esmagarei nações e destruirei reinos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Contigo esmagarei cavalos e seus cavaleiros; contigo esmagarei carruagens e seus condutores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Contigo esmagarei cada homem e mulher; contigo esmagarei os velhos e os novos. Contigo esmagarei os jovens e as virgens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Contigo esmagarei os pastores e seus rebanhos; contigo esmagarei o lavrador e sua junta de bois. Contigo esmagarei os governadores e oficiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'À sua vista, Eu pagarei à Babilônia e a todos os seus habitantes por todo o mal que fizeram em Sião. Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Vede, Eu sou contra ti, montanha de destruição; tu que destróis toda a terra – esta é a declaração de Yahweh. Eu a atingirei com Minha mão e a rolarei para baixo dos penhascos. Depois, farei de ti uma montanha completamente queimada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Eles não tirarão de ti qualquer pedra para a construção, nem pedra angular nem alicerce, pois tu te tornarás uma eterna devastação – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Levantai um estandarte sobre a terra. Tocai a trombeta sobre as nações. Chamai as nações para atacá-la. Convocai contra ela os reinos de Ararate, Mini e Asquenaz; indicai um comandante para atacá-la; trazei cavalos como enxame de gafanhotos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Preparai as nações para atacá-la: os reis dos medos e seus governantes, todos os seus oficiais e todas as terras sob seu comando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Porque a terra tremerá e se angustiará, visto que os planos de Yahweh continuam contra a Babilônia, para fazer da terra da Babilônia uma terra devastada, onde não há morador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Os soldados da Babilônia pararam de guerrear; eles ficaram nas fortalezas. Suas forças falharam; eles se tornaram como mulheres; suas casas estão em chamas; as barras de seus portões estão quebradas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Um emissário corre para proclamar a outro emissário, e um mensageiro conta a outro mensageiro, para reportar ao rei da Babilônia que sua cidade foi tomada de ponta a ponta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'Assim, as travessias sobre o rio estão dominadas; o inimigo queima os pântanos de junco, e os guerreiros da Babilônia ficam amedrontados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Pois Yahweh dos Exércitos, Deus de Israel, diz: A filha da Babilônia é como eira no tempo da debulha. É o tempo de pisá-la. Em breve, o tempo da colheita virá para ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, '\'Nabucodonosor, rei da Babilônia, me devorou, me drenou, me secou e me transformou em um vaso vazio. Ele me engoliu como um monstro marinho. Ele encheu seu estômago com minhas comidas finas e me vomitou.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Os habitantes de Sião dirão: \'Que a violência feita a mim e à minha família seja contra a Babilônia\', Jerusalém dirá: \'Que o meu sangue seja contra os habitantes da Babilônia.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Portanto Yahweh diz: \"Vede, estou prestes a defender teu caso e trazer vingança para ti, pois secarei as águas da Babilônia e farei com que suas nascentes sequem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'A Babilônia se tornará uma pilha de entulho, uma morada de chacais, um horror, objeto de zombaria, onde não há habitantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Os babilônios rugirão juntos como leões jovens. Eles rosnarão como filhotes de leão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Quando eles estiverem excitados com a ganância, Eu farei para eles um banquete; Eu os farei embriagarem-se para que fiquem felizes e, depois, durmam um sono interminável e não acordem – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Eu os farei descer como cordeiros ao matadouro, como carneiros e bodes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Como a Babilônia foi capturada, então, o louvor de toda a terra foi confiscado. Como a Babilônia se tornou um lugar de ruínas entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'O mar veio sobre a Babilônia! Ela está coberta com o tumulto das suas ondas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Suas cidades tornaram-se desolações, uma terra seca e um deserto, uma terra que ninguém habita, e nenhum ser humano passa através dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Então, eu punirei Bel na Babilônia; Eu trarei para fora de sua boca o que ele engoliu, e as nações deixarão de ir até ele com suas ofertas. Os muros da Babilônia cairão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Saí do meio dela, Meu povo. Deixai que cada um salve sua própria vida do furor de Minha ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Não deixeis que vossos corações fiquem tímidos ou temerosos das notícias que são ouvidas na terra, pois as notícias virão em um ano. Após isso, no próximo ano, haverá novidades, e a violência estará na terra. Dominador contra dominador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Portanto, vede, vêm os dias quando punirei os ídolos esculpidos da Babilônia. Toda sua terra será envergonhada, e todos os seus abatidos cairão em seu meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Depois, os céus e a terra e tudo neles se regozijarão sobre a Babilônia. Pois os destruidores virão por ela do norte – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Assim como a Babilônia fez os mortos de Israel caírem, os mortos de sua terra cairão na Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Sobreviventes da espada, ide! Não permaneçais. Lembrai-vos de Yahweh de longe; deixai Jerusalém vir à vossa mente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Nós estamos envergonhados, pois ouvimos insultos; a repreensão cobriu nossas faces, pois os estrangeiros entraram nos lugares sagrados da Casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Portanto, vede, dias virão quando eu punirei seus ídolos esculpidos. Os feridos irão gemer em toda a sua terra – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Porque, mesmo que a Babilônia suba aos céus ou fortifique suas fortalezas mais altas, os destruidores virão por Mim contra ela – esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Um grito de socorro veio da Babilônia, uma grande ruína da terra dos caldeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Porque Yahweh destrói a Babilônia e faz a sua grande voz perecer. Seus inimigos rugem como as ondas de muitas águas; seu barulho torna-se muito forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Porque os destruidores vieram contra ela, contra a Babilônia; e seus guerreiros foram capturados. Seus arcos estão quebrados, pois Yahweh é o Deus da vingança. Ele, certamente, realizará essa retribuição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Pois eu farei seus príncipes, seus sábios, seus oficiais e seus soldados embriagarem-se, e eles dormirão um interminável sono e nunca acordarão. Esta é a declaração do Rei! Yahweh dos Exércitos é o seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Yahweh dos Exércitos diz: Os largos muros da Babilônia serão completamente demolidos, e seus altos portões serão queimados. Então, os povos que vierem em sua ajuda farão o seu trabalho em vão; tudo o que as nações tentarem fazer por ela, será queimado.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Esta é a palavra que Jeremias, o profeta, ordenou a Seraías, filho de Nerias, filho de Maseias quando ele foi com Zedequias, rei de Judá, à Babilônia, no quarto ano de seu reinado. Seraías era o chefe dos oficiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Porque Jeremias escreveu em um livro sobre todo o desastre que estava por vir sobre a Babilônia; todas estas palavras estão escritas a respeito da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Jeremias disse a Seraías: \"Quandos fores à Babilônia, verás e lerás essas palavras em voz alta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'E dirás: \'Yahweh, Tu mesmo declaraste que destruirias este lugar. Não haverá habitantes, nem pessoas, nem animais. Será, permanentemente, desolada.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Então, quando terminares de ler este livro, amarra uma pedra nele e o joga no meio do Eufrates.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'Dize: \'A Babilônia afundará como isto. E não surgirá por causa do desastre que estou enviando contra ela, e eles cairão.\" As palavras de Jeremias terminam aqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Zedequias tinha vinte e um anos quando começou a reinar e reinou onze anos em Jerusalém. Sua mãe se chamava Hamutal; ela era filha de Jeremias, de Libna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Ele fez o que era mau aos olhos de Yahweh, fez tudo o que Jeoaquim havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Por causa da ira de Yahweh, todos esses eventos aconteceram em Jerusalém e Judá, até que Ele os expulsou de sua presença. Então, Zedequias se rebelou contra o rei da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Aconteceu que, no nono ano do reinado de Zedequias, no décimo dia do décimo mês, Nabucodonosor, rei da Babilônia, veio a Jerusalém com todo o seu exército. Eles acamparam em frente à cidade e construíram rampas até o topo das muralhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Assim, a cidade foi sitiada até o décimo primeiro ano do reinado de Zedequias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'No nono dia do quarto mês daquele ano, a fome havia-se tornado tão severa na cidade que já não restava comida para o povo daquela terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Então, a cidade foi invadida e, mesmo com os babilônios cercando a cidade, todos os guerreiros fugiram, saindo durante a noite, através do portão que estava entre as duas paredes, ao lado do jardim real. Eles foram em direção a Arabá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'mas o exército dos babilônios perseguiu o rei Zedequias e o alcançou na planície do rio Jordão, perto de Jericó. Todo o seu exército se dispersou e o abandonou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Eles capturaram o rei Zedequias e o trouxeram ao rei da Babilônia, em Ribla, na terra de Hamate, onde ordenou sentença sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'O rei da Babilônia matou os filhos de Zedequias diante de seus olhos e, em Ribla, também matou todos os líderes de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'E cegou Zedequias e o prendeu em correntes de bronze e o levou para a Babilônia. Zedequias permaneceu preso até o dia de sua morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'No décimo dia do quinto mês, do décimo nono ano do reinado de Nabucodonosor, rei da Babilônia, Nebuzaradã chegou em Jerusalém. Ele era o comandante da guarda real e um servo do rei da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Ele queimou a Casa de Yahweh, o palácio real e todas as casas de Jerusalém; todas as construções importantes da cidade também foram queimadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'E ele comandou o exército babilônico na destruição dos muros em volta de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Quanto aos mais pobres e o restante do povo que ficou na cidade, os desertores de Judá que se entregaram ao rei da Babilônia e o restante dos artesãos, Nebuzaradã, o comandante da guarda real, levou alguns deles para o exílio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Mas Nebuzaradã, o comandante da guarda real, deixou os mais pobres da terra para trabalharem no campo e nas vinheiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'A respeito dos pilares de bronze pertencentes à Casa de Yahweh, e as bases do tanque de bronze que estavam na Casa de Yahweh, os babilônios os quebraram em pedaços e carregaram todo o bronze de volta a Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'As jarras, pás, aparadores de lâmpadas, bacias e todos os utensílios de bronze que os sacerdotes usavam no templo, os babilônios levaram embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'As bacias e os braseiros, as jarras, as vasilhas, candelabros e bacias que eram feitas de ouro ou de prata, o comandante da guarda real também levou embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Os dois pilares, o tanque e os doze bois de bronze que estavam em baixo das bases, objetos que Salomão havia feito para a Casa de Yahweh, continham mais bronze do que podiam pesar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Os pilares tinham, cada um deles, dezoito côvados de altura e a circunferência de doze côvados. Cada um tinha quatro dedos grossos e era oco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Um capitel de bronze estava no topo. Ele tinha cinco côvados de altura, com rede e romãs em volta. Tudo feito de bronze. O outro pilar e romãs eram iguais ao primeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Havia noventa e seis romãs nos lados do capitel e cem romãs acima e ao redor da rede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'O comandante da guarda real aprisionou Seraías, o sumo sacerdote, juntamente com Sofonias, o segundo sacerdote, e os três guardas da porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Dos que ainda estavam na cidade, ele aprisionou um oficial que estava no comando dos soldados e sete conselheiros do rei. Também aprisionou o chefe do exército, responsável por recrutar homens, além de sessenta outros homens importantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Então, Nebuzaradã, o comandante da guarda real, levou-os para o rei da Babilônia, em Ribla.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Nessa cidade, a terra de Hamate, Nabucodonosor ordenou a morte de todos eles. Desta forma, Judá saiu de sua terra para o exílio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Esses são os números de pessoas que Nabucodonosor exilou: no sétimo ano, três mil e vinte três judeus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'no oitavo ano, Nabucodonosor prendeu oitocentos e trinta e duas pessoas de Jerusalém;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'no vigésimo terceiro ano de Nabucodonosor, Nebuzaradã, o capitão da guarda real, exilou setecentos e quarenta e cinco judeus. No total, foram exiladas quatro mil e seiscentas pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'No trigésimo sétimo ano do exílio de Jeoaquim, rei de Judá, no vigésimo quinto dia do décimo segundo mês, Evil-Merodaque, rei da Babilônia, libertou da prisão Jeoaquim, rei de Judá. Isto aconteceu no ano em que Evil-Merodaque começou a reinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'O rei falou gentilmente com ele e lhe deu o assento de honra mais elevado do que os de outros reis que estavam com ele, na Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Evil-Merodaque trocou as roupas de prisioneiro de Jeoaquim e ele passou a comer regularmente na mesa do rei, pelo resto de sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Uma porção alimentar e uma pensão lhe foram dadas durante o resto de seus dias, até a sua morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'A cidade que uma vez esteve cheia de habitantes agora está completamente solitária! Ela tornou-se como uma viúva, embora fosse uma nação poderosa. Era uma princesa entre as nações, mas agora é forçada à escravidão!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Ela chora e lamenta na noite, e suas lágrimas escorrem por suas bochechas. Nenhum dos seus amantes a conforta. Todos os seus amigos a traíram. Eles tornaram-se seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Depois da pobreza e aflição, Judá foi levada ao exílio. Ela vive entre as nações e não encontra descanso. Todos os seus perseguidores a apanharam no seu desespero.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'As estradas de Sião choram, porque ninguém vem para as festas solenes. Todos os portões dela estão desolados. Seus sacerdotes gemem. Suas virgens estão tristes, e ela mesma está em completo desespero.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Seus adversários tornaram-se seus mestres, seus inimigos prosperam. Yahweh a tem afligido por causa dos seus muitos pecados. Suas crianças pequenas vão ao cativeiro, vão até o seu adversário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'A beleza deixou a filha de Sião. Seu príncipe tornou-se como cervo que não encontra pasto, e eles vão sem força diante dos seus perseguidores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Nos dias da sua aflição e seu exílio, Jerusalém lembrará de todos os tesouros preciosos que ela tinha em dias passados. Quando seu povo caiu nas mãos dos adversários, ninguém a ajudou. Os adversários a viram e zombaram da sua destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jerusalém pecou grandemente; por esse motivo, ela tornou-se desprezada como algo imundo. Todos os que a honravam agora a desprezam, desde que eles viram sua nudez. Ela geme e tenta virar-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Tornou-se suja debaixo das suas saias. Ela não pensou no seu futuro. Sua queda foi terrível. Não havia ninguém para confortá-la. Ela clamava: \"Vê minha aflição, Yahweh, pois, o inimigo tornou-se grande demais!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'O adversário pôs sua mão sobre todos os nossos preciosos tesouros. Ela viu as nações entrarem no seu santuário, mesmo que Tu tenhas ordenado que elas não devessem entrar na Tua assembléia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Todo o seu povo geme enquanto procura por pão. Eles têm dado seus preciosos tesouros por comida para restaurarem suas vidas. Vê, Yahweh, e me considera, pois tenho me tornado inútil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Vós que passais não vos importais comigo? Olha e vê se lá está alguém que sofre como eu tenho sofrido, desde que Yahweh me tem atormentado no dia da Sua ira feroz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'É do alto que Ele envia fogo dentro dos meus ossos, e isso os conquistou. Ele tem espalhado uma rede para meus pés e me fez voltar. Ele me tem feito constantemente desolado e fraco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'O jugo das minhas transgressões está atado pela Sua mão. Elas estão amarradas e colocadas sobre meu pescoço. Ele fez minha força enfraquecer. O Senhor me entregou nas suas mãos, e não sou capaz de ficar de pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'O Senhor tem lançado fora todo homem poderoso que me defendeu. Ele tem convocado uma assembleia contra mim, para esmagar os meus homens vigorosos. O Senhor tem pisoteado a filha virgem de Judá no lagar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Por essas coisas eu choro. Meus olhos, água flui dos meus olhos, desde que o consolador, que deveria restaurar minha vida, está longe de mim. Minhas crianças estão desoladas, porque o inimigo triunfou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Sião está com suas mãos estendidas; não há ninguém para consolá-la. Yahweh ordenou que aqueles que estão à volta de Jacó se tornem seus adversários. Jerusalém é algo imundo para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Yahweh é justo, pois eu me rebelei contra Seus mandamentos. Ouvi, todos vós, povos, e vede meu sofrimento. Minhas virgens e meus homens vigorosos foram levados ao cativeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Eu chamei por meus amigos, mas eles foram traiçoeiros diante de mim. Meus sacerdotes e meus anciãos pereceram na cidade, enquanto eles procuravam comida para restaurar suas vidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Vê, Yahweh, pois estou em sofrimento; minhas entranhas gritam, meu coração está perturbado dentro de mim, por eu ter sido muito rebelde. Lá fora, a espada tira os filhos de uma mãe; dentro da casa, há somente morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Ouviram meus gemidos, mas não há ninguém para me consolar. Todos os meus inimigos têm ouvido das minhas tribulações. Eles se alegram por Tu teres feito isso. Tu nos trouxeste o dia que prometeste; agora, que eles se tornem como eu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Que toda a maldade deles venha diante de Ti. Trata com eles como trataste comigo, por causa de todas as minhas transgressões. Meus gemidos são muitos, e meu coração está desfalecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'O Senhor cobriu a filha de Sião com a nuvem de Sua ira! Ele já lançou a beleza de Israel do céu para a terra e não se lembrou do estrado dos seus pés no dia da Sua ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'O Senhor engoliu e não teve compaixão de nenhuma de todas as cidades de Jacó. Nos dias de Sua ira, Ele lançou à terra as cidades fortificadas da filha de Judá; em desonra, Ele lançou ao chão o reino e os seus príncipes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'No furor da Sua, ira Ele eliminou a força de Israel. Ele já retirou a Sua mão direita da frente do inimigo. Ele queimou a Jacó como o fogo ardente queima tudo à sua volta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Ele tem amarrado Seu arco para nós como um inimigo. Ele firmou a Sua destra como um adversário com mãos prontas para disparar. Ele já abateu todas as pessoas muito preciosas aos Seus olhos. Na tenda da filha de Sião, lançou o Seu furor como fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'O Senhor tornou-Se como um inimigo. Ele engoliu Israel. Já engoliu todos os seus palácios. Destruiu as suas fortalezas. Já aumentou o pranto e a lamentação para a filha de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Ele atacou o Seu tabernáculo como se fosse uma cabana de jardim. Destruiu o lugar da congregação solene. Yahweh fez com que as congregações solenes e sábados fossem esquecidos em Sião, porque Ele desprezou tanto reis como sacerdotes, na indignação da Sua ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'O Senhor rejeitou o Seu altar; Ele detestou o Seu santuário. Deu os muros do palácio nas mãos do inimigo. Estes deram um grito de vitória na casa de Yahweh, como se fosse um dia de festa solene.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Yahweh decidiu deliberadamente destruir os muros da cidade da filha de Sião. Ele esticou uma linha de medir e não deteve Sua mão destruidora. E já fez as muralhas de lamento e as paredes se tornarem frágeis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Os portões dela afundaram na terra; Ele já destruiu e quebrou os seus ferrolhos. O rei e os príncipes dela estão no meio dos gentios, onde não há mais lei, e seus profetas não encontram as visões de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Os anciãos da filha de Sião se sentam no chão e choram silenciosamente. Eles atiraram terra em suas cabeças e se vestiram de sacos. As virgens de Jerusalém abaixam suas cabeças para o chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Acabaram-se as lágrimas dos meus olhos; meu estômago está roncando; meu íntimo se derrama até o chão, por causa da destruição da filha do meu povo, porque os meninos e as crianças de peito desfalecem nas estradas das aldeias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Eles dizem para suas mães: \"Onde está o pão e o vinho?\", desmaiando como homens feridos nas estradas da cidade, suas vidas caindo no colo das suas mães.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'O que eu posso dizer sobre ti, filha de Jerusalém? A quem te assemelharei para confortar a ti, filha virgem de Sião? A tua ferida é grande como o mar. Quem pode te curar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Teus profetas viram mentiras tolas e visões para ti. Eles não revelaram a tua iniquidade para restaurar a tua sorte, mas ouviram oráculos enganadores e tentações para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Todos aqueles que passam pela estrada batem palmas para ti. Eles assobiam, agitam a cabeça contra a filha de Jerusalém e dizem: \"É esta a cidade que chamaram \'A Perfeição da Beleza\', \'A Alegria de Toda a Terra\'?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Todos os teus inimigos abrem a boca contra ti e zombam de ti. Eles assobiam, rangem os dentes e dizem: \"Nós já a engolimos! Certamente este é o dia que esperávamos! Nós já o encontramos! Nós já o vimos!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Yahweh já fez o que havia decidido. Ele cumpriu a Sua palavra. Já te derrubou sem compaixão, porque Ele permitiu o inimigo se alegrar sobre ti e elevou o poder dos teus adversários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Os corações deles clamam ao Senhor, muralhas da filha de Sião! Deixai as lágrimas caírem como um rio, dia e noite. Não te dês alívio. Não pares de secar as lágrimas dos teus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Levanta e chora alto na noite; no princípio das horas, derrama como água o teu coração diante da face do Senhor. Levanta as tuas mãos a Ele pela vida dos teus filhos, que desfalecem de fome nas entradas de todas as ruas.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Vê, Yahweh, e lembra-Te daqueles a quem tens tratado severamente. Poderão as mulheres comer o fruto de seus ventres, as crianças que elas cuidaram? Poderão o sacerdote e o profeta ser abatidos no santuário do Senhor?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Jazem juntamente o moço e o velho nas terras e nas ruas. Minhas virgens e meus homens vigorosos caíram pela espada. Tu os abateste no dia da Tua ira. Tu os mataste impiedosamente e não mostraste compaixão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Tu tens chamado os meus terrores ao redor como chamarias o povo para uma festa solene; não houve quem escapasse, ou sobrevivesse no dia da ira de Yahweh. Aqueles que eu alimentei e criei meu inimigo destruiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Eu sou um homem que viu a miséria sob a vara da fúria de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Ele me guiou e me fez andar na escuridão, ao invés da luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Certamente, Ele se voltou contra mim repetidamente, o dia todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Ele fez a minha carne e a minha pele desaparecerem e quebrou meus ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Ele construiu um cerco contra mim e me rodeou com amargura e sofrimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Ele me fez viver em lugares escuros, como aqueles que morreram há muito tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Construiu um muro ao meu redor, não posso escapar. Tornou minhas correntes pesadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Embora eu peça ajuda e grite por socorro, Ele rejeita as minhas orações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Ele bloqueou meu caminho, com parede de pedra lavrada; fez meus caminhos tortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Ele é como um urso, esperando para me emboscar, um leão no esconderijo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Ele desviou os meus caminhos, despedaçou-me, deixou-me desolado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Curvou Seu arco e me colocou como alvo de Sua flecha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Ele perfurou meus rins com as flechas de sua aljava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Tornei-me motivo de riso para todo o meu povo, o objeto de seus insultos durante todo o dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Ele me encheu de amargura e me forçou a beber absinto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Ele esmagou meus dentes com cascalho, afundou-me no pó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Minha alma está privada de paz, esqueci o que é felicidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Então, eu disse: \"Minha resistência pereceu, assim como a minha esperança em Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Lembre-se da minha aflição e das minhas andanças, do absinto e da amargura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Continuamente me lembro disso e estou curvado dentro de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Mas chamo isso à memória e, portanto, tenho esperança:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'O amor inabalável de Yahweh nunca cessa, e Suas misericórdias não têm fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'São novas a cada manhã. Tua fidelidade é grande!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, '\"Yahweh é minha herança\", eu disse. Então, esperarei Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Yahweh é bom para os que esperam Nele, para aquele que O busca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'É bom esperar, em silêncio, pela salvação de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'É bom para o homem carregar o jugo em sua juventude.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Que ele fique sozinho, e em silêncio, porque Deus pôs tal jugo sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Que ponha a boca no pó, talvez ainda haja esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Que ele dê a face ao que o golpeia e que se encha de desgraça,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'porque o Senhor não nos rejeitará para sempre;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'embora cause tristeza, Ele terá compaixão segundo a abundância de Seu amor inabalável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Porque Ele não aflige de bom grado ou atormenta os filhos dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Para esmagar todos os cativos na terra debaixo de Seus pés,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'para desviar a justiça dos homens diante da face do Altíssimo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'para suprimir uma pessoa em sua causa — o Senhor não o vê?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Quem é que fala e acontece a não ser que o Senhor o tenha decretado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Não sai da boca do Altíssimo tanto o mal quanto o bem? Como pode qualquer pessoa viva queixar-se?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Como pode qualquer homem queixar-se da punição pelos seus pecados?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Esquadrinhemos e examinemos os nossos caminhos e voltemos para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Levantemos nossos corações e as nossas mãos para o Deus dos céus e oremos:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, '\"Nós transgredimos e nos rebelamos contra Ti, de modo que Tu não nos perdoaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Tu te cobriste com ira e nos perseguiste. Tu nos abateste e não tiveste piedade de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Tu te cobriste com uma nuvem, de modo que nenhuma oração possa atravessá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Tu nos fizeste refugo e resto entre os povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Todos os nossos inimigos abriram a sua boca com zombaria contra nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Medo da sepultura veio sobre nós, desolação e esmagamento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'O meu olho desce com rios de água por causa do esmagamento da filha do meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Meus olhos fluem, eles não param, pois não há fim para isso');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'até que Yahweh olhe para baixo e veja do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Meus olhos trazem uma dor severa à minha vida por causa de todas as filhas da minha cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Meus inimigos me caçaram implacavelmente como a um pássaro, sem motivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Eles destruíram a minha vida num fosso e colocaram uma pedra sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Águas cobriram minha cabeça; Eu disse: \"Estou perdido!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Invoquei o Teu nome, Yahweh, do mais profundo fosso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Tu ouviste minha voz quando eu clamei: \"Não escondas Teus ouvidos do meu pedido de alívio, do meu clamor de socorro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Tu Te aproximaste de mim no dia em que eu Te invoquei, Tu me disseste: \"Não temas!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Senhor, Tu me defendeste quando eu estava em julgamento por minha vida, Tu salvaste minha vida!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Yahweh, Tu viste a opressão deles sobre mim. Julga meu caso com justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Viste todos os atos deles de vingança, todos os planos deles contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Tu ouviste o desprezo deles, Yahweh, e todos os planos deles em relação a mim');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Tu ouviste os lábios dos que se levantaram contra mim; Tens escutado os pensamentos profundos deles, que são contra mim o dia inteiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Seja no seu sentar ou no seu levantar, olha, Yahweh! Eu sou o objeto de suas canções de escárnio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Retribui-lhes, Yahweh, causa-lhes danos, tanto quanto o que têm feito as mãos deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Põe medo no coração deles; põe a Tua maldição sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Persegue-os na Tua ira e destrói-os em todos os lugares debaixo dos céus, Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'O ouro tornou-se escuro; como o ouro mais puro mudou! As pedras santas foram espalhadas na esquina de cada rua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Os preciosos filhos de Sião valiam seu peso em ouro puro. Mas agora não valem mais que vasos de argila feitos pelas mãos do oleiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Até os chacais oferecem o peito para amamentar seus filhotes, mas a filha do meu povo tem-se tornado tão cruel como os avestruzes no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'A língua da criança de peito cola-se ao céu da sua boca sedenta; crianças pedem pão, mas não há nada para elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Os que comiam comidas caras agora passam fome nas ruas; Os que cresceram vestindo vestes escarlates agora se deitam sobre pilhas de lixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'O castigo da filha do meu povo é maior do que o de Sodoma, que foi derrubada como num momento, e ninguém levantou uma mão para ajudá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Seus líderes eram mais puros que a neve e mais brancos que o leite. Seus corpos eram mais saudáveis que corais; e a sua forma, como safira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Agora a sua aparência escureceu mais que a fuligem, e já estão irreconhecíveis nas ruas, pois a sua pele colou-se aos seus ossos e está seca como a lenha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Aqueles que foram mortos pela espada foram mais felizes do aqueles que foram mortos pela fome, que se definharam, perfurados pela falta de qualquer colheita do campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'As mãos de mulheres compassivas cozinharam seus próprios filhos; eles foram seu alimento no tempo em que a filha do meu povo estava sendo destruída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Yahweh demonstrou toda a Sua ira. Ele derramou Sua ardente raiva; sobre Sião, Ele acendeu fogo que consumiu seus alicerces.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Os reis da terra não acreditavam, nem qualquer dos moradores do mundo acreditava que inimigos ou adversários pudessem entrar pelos portões de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Mas isso aconteceu por causa dos pecados dos seus profetas e as iniquidades dos sacerdotes que derramaram sangue justo no meio dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Eles vagueavam, cegos, pelas ruas. Estavam tão contaminados por aquele sangue ao ponto de ninguém ter permissão para tocar suas vestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, '\"Apartai-vos, imundos!\", gritava-lhes o povo. \"Apartai-vos, apartai-vos! Não os toqueis!\" E assim vagueavam errantes; entre as nações se dizia: \"eles já não podem permanecer aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'O próprio Yahweh os espalhou e já não cuida deles. Eles não honram os sacerdotes nem mostraram qualquer compaixão aos anciãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Nossos olhos falharam, procurando em vão por ajuda; das nossas torres de vigia, olhávamos por uma nação que não poderia nos salvar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Eles espreitavam os nossos passos, não podíamos andar pelas nossas ruas. Nosso fim estava perto; e os nossos dias, contados, pois é chegado o nosso fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Nossos perseguidores foram mais rápidos do que as águias no céu. Eles nos seguiram até as montanhas e à espreita esperavam por nós no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'O fôlego em nossas narinas, O ungido de Yahweh, Ele é o que foi preso nas suas covas, Dele se dizia: \"Sob Sua sombra viveremos entre as nações\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Regozija-te e alegra-te, filha de Edom, você que vive na terra de Uz. Mas a ti também esse cálice passará; tu te embriagarás e te desnudarás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Filha de Sião, o teu castigo chegará ao fim, Ele não estenderá seu exilio. Mas, filha de Edom, os teus pecados serão descobertos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Lembra-te, Yahweh, do que aconteceu conosco. Vê e considera a nossa vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Nossa herança foi entregue a estranhos; nossas casas, a estrangeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Nós nos tornamos órfãos, pois não temos pai, e nossas mães são como viúvas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Temos que pagar com prata a água que bebemos e temos que pagar com prata para buscar nossa própria madeira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Os que nos perseguem estão próximos de nós; estamos cansados, não encontramos descanso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Temos nos entregado aos egípcios e aos assírios para obter comida suficiente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Nossos pais pecaram; eles não existem mais, e nós suportamos suas iniquidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Escravos dominam sobre nós, e não há ninguém para nos resgatar de suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Arriscamos nossas vidas para obter o nosso pão, por causa da espada no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Nossa pele se tornou quente como um forno, por causa do ardor da fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Mulheres são violadas em Sião; e as virgens, nas cidades de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'O príncipes são por eles enforcados, e não é dada honra os anciãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Os jovens são forçados a moer com a pedra de moinho, e meninos cambaleiam sob pesadas cargas de lenha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Os anciãos deixaram o portão da cidade, e os jovens deixaram sua música.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'A alegria do nosso coração acabou, e a nossa dança se transformou em lamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'A coroa caiu de nossa cabeça! Ai de nós, porque pecamos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Por isso nosso coração adoeceu, e nossos olhos se escureceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Por essas coisas nossos olhos escurecem, porque chacais passeiam no Monte Sião, que está desolado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Mas Tu, Yahweh, reinas para sempre e Te assentarás sobre Teu trono, de geração em geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Por que Te esqueceste de nós para sempre? Por que nos deixarás por tantos dias?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Restaura-nos a Ti, Yahweh, e nós seremos restaurados. Renova nossos dias como nos tempos antigos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'a menos que nos tenhas rejeitado totalmente e estejas irado conosco além da medida!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'No trigésimo ano, no quarto mês, ao quinto dia do mês, eu estava vivendo entre os cativos, no rio Quebar. Os céus se abriram e tive visões de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Ao quinto dia daquele mês — era o quinto ano do exílio do rei Joaquim —,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'a palavra de Yahweh veio a Ezequiel, filho de Buzi, o sacerdote, na terra dos caldeus, junto ao rio Quebar, e a mão de Yahweh estava sobre ele naquele lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Olhei e havia um vendaval vindo do norte, uma nuvem enorme com fogo cintilante dentro dela, com brilho ao redor e dentro dela; o fogo era da cor de âmbar dentro da nuvem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'No meio, havia a semelhança de quatro seres viventes. Eis a sua aparência: tinham a semelhança de um homem;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'porém cada uma tinha quatro rostos e cada uma das criaturas tinha quatro asas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Suas pernas eram retas, mas as plantas dos seus pés eram como as patas de um bezerro que brilhava como bronze polido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Além disso, tinham mãos humanas debaixo das suas asas em todos os quatro lados; os rostos e as asas dos quatro eram assim:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'as asas tocavam as asas da próxima criatura e não se viravam enquanto andavam; pelo contrário, cada uma andava para frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'A semelhança dos seus rostos era como o rosto humano. Os quatro tinham rosto de leão ao lado direito, e os quatro tinham rosto de boi ao lado esquerdo. Os quatro tinham também o rosto de uma águia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Seus rostos eram assim e as suas asas estavam abertas de modo que cada uma tinha um par de asas que tocava as asas da outra criatura e também um par de asas que cobria os seus corpos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Cada uma ia para frente, para onde o Espírito fosse, elas andavam sem se virar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Os seres viventes pareciam brasas ardentes, eram como tochas; o fogo respladecia e se movia entre os seres e havia clarões de relâmpago.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Os seres viventes se moviam rapidamente para frente e para trás e tinham a semelhança de relâmpago!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Depois, olhei para os seres viventes; havia uma roda no chão, ao lado dos seres viventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Assim era a aparência e a estrutura das rodas: cada roda era como berilo e as quatro tinham a mesma semelhança; a sua aparência e a sua estrutura eram como uma roda interligada à outra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Enquanto as rodas se moviam, elas iam a uma das suas quatro direções, sem se virar enquanto iam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Quanto aos seus aros, eram altos e assustadores, porque os aros estavam cheios de olhos ao seu redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Sempre que os seres viventes se moviam, as rodas se moviam com eles. Quando os seres viventes erguiam-se da terra, as rodas também se erguiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Aonde quer que o Espírito fosse, eles iam, e as rodas se erguiam com eles, porque o Espírito do ser vivente estava nas rodas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Quando os seres se moviam, as rodas também se moviam; e, quando os seres paravam, as rodas paravam; quando os seres se erguiam da terra, as rodas se erguiam com eles, porque o Espírito do ser vivente estava nas rodas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Sobre as cabeças dos seres viventes, havia uma redoma como cristal refulgente, estendida sobre as suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Debaixo da redoma, cada uma das asas dos seres esticava-se e tocava nas asas do outro ser. Cada um dos seres viventes também tinha um par de asas para se cobrir; cada um tinha um par para cobrir o seu próprio corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Então, ouvi o som das suas asas como o barulho de muitas águas; como a voz do Onipotente, sempre que se moviam; como o som de um exército. Sempre que paravam, abaixavam as suas asas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Uma voz vinha por cima da redoma, sobre as suas cabeças, sempre que paravam e abaixavam as suas asas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Sobre a redoma que estava acima das suas cabeças, havia algo semelhante a um trono que era da aparência de uma safira, e, sobre esse trono, havia alguém que parecia um homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Vi que esse homem, da cintura para cima, parecia um metal brilhante cheio de fogo e, da cintura para baixo, vi um fogo que brilhava ao seu redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Como a aparência de um arco-íris nas nuvens em um dia chuvoso, havia a aparência da luz cintilante que a rodeava. Era a aparência da glória de Yahweh. Quando vi isso, caí com o rosto em terra e ouvi a voz de Quem falava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'E Ele me disse: \"Filho do homem, põe-te em pé, e falarei contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Então, enquanto me falava, o Espírito entrou em mim e me pôs em pé, e O ouvi falando comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Ele me disse: \"Filho do homem, estou te enviando ao povo de Israel, às nações rebeldes que têm se rebelado contra Mim. Tanto eles como seus antepassados têm pecado contra Mim até o dia de hoje!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Seus descendentes têm semblantes teimosos e corações duros. Eu te envio a eles, para que lhes digas: \'Isto é o que Yahweh Deus diz\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'quer te ouçam, quer não, pois são uma casa rebelde. Ao menos, saberão que um profeta esteve no meio deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Tu, filho do homem, não tenhas medo deles nem das suas palavras. Não temas, embora estejas entre sarças e espinhos e vivas entre escorpiões. Não tenhas medo das suas palavras, nem desfaleças por causa dos seus rostos, pois são uma casa rebelde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Porém, tu lhes dirás Minhas palavras, quer ouçam, quer não, pois são muito rebeldes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Mas tu, filho do homem, ouve o que Eu te digo, não sejas rebelde como aquela casa rebelde. Abre a tua boca e come o que Eu estou para te dar!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Então olhei, e uma mão me foi estendida; nela, havia um rolo de um livro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Ele o desenrolou diante de mim. O livro estava escrito por dentro e por fora e, nele, estavam escritos prantos, lamentações e tristezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Ele me disse: \"Filho do homem, come o que achares, come este rolo; vai e fala à casa de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Então abri a minha boca e Ele me deu o rolo para comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Ele me disse: \"Filho do homem, dá de comer ao teu estômago e enche as tuas entranhas deste rolo que dei a ti!\". Então eu comi, e era, na minha boca, doce como o mel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Então, Ele disse: \"Filho do homem, vai à casa de Israel e fala as Minhas palavras a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Porque não estás sendo enviado a um povo de uma fala estranha ou de uma língua difícil, mas à casa de Israel;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'não a uma nação poderosa, de fala estranha ou língua difícil, cujas palavras não possas entender! Se Eu te enviasse a eles, eles te ouviriam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Mas a casa de Israel não estará disposta a ouvir-te, pois não estão dispostos a Me ouvir, porque toda casa de Israel é obstinada e dura de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Eis que fiz teu rosto tão teimoso como os seus rostos e a tua testa tão dura quanto a deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Eu fiz a tua testa como um diamante, mais duro que a pedra! Não os temais, nem fiques desencorajado pelos seus rostos, porque são uma casa rebelde\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Então, Ele me disse: \"Filho do homem, todas as palavras que Eu te anunciar, guarda no coração e, com os teus ouvidos, escuta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Então, vai aos cativos, ao teu povo; tu lhes falarás e lhes dirás: \'Assim diz Yahweh Deus\', quer te ouçam, quer não\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Depois, o Espírito me levantou e ouvi atrás de mim o estrondo de um grande terremoto: \"Bendita seja a glória de Yahweh em Sua habitação!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Era o som das asas dos seres viventes enquanto tocavam uma na outra, o som das rodas que estavam com elas e o estrondo do grande terremoto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'O Espírito me levantou, levou-me embora e saí amargurado com meu espírito indignado; a mão de Yahweh me pressionava fortemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Então, fui aos cativos em Tel-Abibe, que moravam junto ao rio Quebar, e lá fiquei por sete dias, sobrecarregado de espanto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Depois desses sete dias, aconteceu que a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, '\"Filho do homem, Eu te fiz um sentinela para a casa de Israel; assim, escuta a palavra da Minha boca e dá-lhes o Meu aviso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Quando Eu disser ao ímpio: \'Certamente morrerás\', e não lhe avisares ou não deres a advertência ao perverso sobre suas más ações, para que ele viva, o ímpio morrerá no seu pecado, mas exigirei o sangue dele da tua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Entretanto, se advertires o corrupto e ele não se desviar da sua maldade ou das suas ações perversas, então ele morrerá por causa do seu pecado, mas tu terás salvado a tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Se o justo se desviar da sua justiça e agir injustamente, colocarei uma pedra de tropeço diante dele, e ele morrerá. Porque tu não o advertiste, ele morrerá em seu pecado e Eu não trarei à memória as ações justas que executou, mas exigirei o sangue dele da tua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Entretanto, se advertires o homem justo que pare de pecar, e ele não pecar, ele certamente viverá, uma vez que foi avisado, e tu salvarás tua própria vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'A mão de Yahweh estava ali sobre mim e me disse: \"Levanta-te e sai para o vale! Lá, falarei contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Levantei-me e saí para o vale; lá, a glória de Yahweh estava, como a glória que eu tinha visto junto ao rio Quebar; então caí com o rosto em terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Então, entrou em mim o Espírito e me pôs em pé, e falou comigo dizendo: \"Vai e te tranca dentro da tua casa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'porque agora, filho do homem, colocarão cordas sobre ti e te amarrarão para que não possas sair dentre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Farei que tua língua grude no céu da tua boca, de forma que ficarás mudo e não poderás repreendê-los, uma vez que são uma casa rebelde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Mas, quando Eu falar contigo, abrirei a tua boca para que lhes digas: \'Assim diz Yahweh Deus\'. Quem quiser ouvir que ouça; aquele que não quiser não ouça, porque são uma casa rebelde!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'E Tu, filho do homem, leva contigo um tijolo e coloca-o à tua frente. Nele, desenha a cidade de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Em seguida, põe um cerco e edifica fortificações perante ela. Levanta uma rampa de assalto contra a cidade e põe acampamentos em torno dela e coloca os aríetes ao seu redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Então, pega para ti uma panela de ferro e usa como um muro de ferro entre ti e a cidade e dirige o teu rosto para ela, pois estará sitiada, e tu colocarás o cerco contra ela. Isso será um sinal para a casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Então, deita-te sobre o teu lado esquerdo e coloca sobre ele o pecado da casa de Israel; carregarás o seu pecado conforme o número dos dias em que te deitares, em frente à casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Eu mesmo estou atribuindo a ti um dia para representar cada ano de sua punição: trezentos e noventa dias. Dessa forma, tu carregarás o pecado da casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'E, quando completares esses dias, deita-te outra vez, agora sobre o teu lado direito. Assim, carregarás o pecado da casa de Judá por quarenta dias. Eu te atribuirei um dia para cada ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Põe o teu rosto em direção a Jerusalém, que está sob o cerco e, com o teu braço descoberto, profetiza contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Eis que Eu estou pondo cordas em ti. Assim, tu não virarás de um lado para o outro, até que tenhas completado os dias de teu cerco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Toma para ti trigo, cevada, feijão, lentilhas, painço e espelta; coloca-os numa vasilha e faze pão para ti, segundo o número dos dias em que te deitares sobre o teu lado. Por trezentos e noventa dias, tu comerás isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'A comida que comerás será por peso, vinte siclos por dia, e comerás em horários determinados a cada dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Então, beberás água pela medida de um sexto de him e beberás em horários determinados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Tu a comerás como bolos de cevada, mas a assarás sobre excremento humano, à vista deles!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Assim diz Yahweh: \"Isso significa que o pão que o povo de Israel comerá ali será imundo entre as nações, para onde os banirei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Então, eu disse: \"Ah, Senhor Yahweh! Eu nunca fui impuro! Também nunca comi nada morto, nem qualquer coisa morta por animais. Desde a minha juventude até agora, carne suja nunca entrou na minha boca!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Então, Ele me disse: \"Olha! Eu te dou esterco de vaca em vez de excremento humano; assim, tu prepararás teu pão sobre ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Ele também me disse: \"Filho do homem, eis que estou tirando o sustento de pão em Jerusalém e eles, com ansiedade, farão racionamento de pão e, com desespero, beberão água racionada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Porque terão falta de pão e de água, todo homem ficará apavorado com o seu irmão e serão consumidos por causa da sua iniquidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, '\"Então, tu, filho do homem, pega uma espada afiada como uma navalha de barbeiro; passa a navalha sobre tua cabeça e tua barba e toma uma balança para pesar e dividir teus cabelos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Queima um terço deles com fogo no meio da cidade, quando os dias do cerco estiverem completos; toma um terço dos cabelos e corta-os com a espada ao redor da cidade. Então, espalha um terço ao vento e Eu puxarei a espada para perseguir o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Mas tira uma mecha de cabelos dali e amarra-a nas dobras de tua veste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Então, pega um pouco mais desse cabelo e joga-o no meio do fogo; queima-o no fogo. Dali, sairá um fogo contra toda a casa de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Assim diz Yahweh Deus: \"Esta é Jerusalém no meio das nações, onde a coloquei, cercada por outras terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Mas ela tem, maldosamente, rejeitado Meus decretos mais que as nações, e rejeitado Meus estatutos mais que os países que a cercam. O povo rejeitou Meus juízos e não andou nos Meus estatutos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Portanto, assim diz Yahweh Deus: \"Porque és mais rebelde que as nações que te rodeiam e não andaste nos Meus estatutos, nem agiste segundo Meus decretos e até agiste segundo os decretos das nações que te cercam,\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'por isso, assim diz Yahweh Deus: eis que Eu mesmo agirei contra ti! Executarei juízos no meio de ti, para que as nações possam ver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Farei a ti o que Eu nunca fiz e nunca farei outra vez, por causa de todas as tuas abominações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Portanto, os pais comerão os filhos no meio de ti e os filhos comerão seus pais, uma vez que executarei juízo sobre ti e espalharei em todas as direções todos os teus sobreviventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Portanto, tão certo como Eu vivo — esta é uma declaração de Yahweh Deus — porque contaminaste o Meu santuário com todas as tuas coisas detestáveis e com todas as tuas abominações, por isso, Eu mesmo te reduzirei em número. Eu retirarei, sem piedade, os olhos sobre ti e não te pouparei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Um terço dos teus morrerá pela praga; no meio de ti, eles serão consumidos pela fome; um terço cairá pela espada que está ao teu redor, então, espalharei um terço em todas as direções e puxarei uma espada para persegui-los também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Então, Minha ira se completará e farei que a Minha fúria se apodere deles. Ficarei satisfeito e saberão que Eu, Yahweh, falei na Minha ira quando completei a Minha fúria contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Farei de ti uma desolação e uma vergonha para as nações que te rodeiam, aos olhos de todos os que passam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Então, Jerusalém se tornará algo para os outros condenarem e zombarem, um aviso e um horror às nações que a rodeiam. Executarei juízos contra ti com ira e fúria; com uma repreensão furiosa. Eu, Yahweh, assim declarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Enviarei flechas ásperas de fome contra vós, que se tornará o meio com o qual vos destruirei. Porque aumentarei a fome sobre vós e farei cessar a vossa provisão de pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Enviarei fome e bestas-feras contra vós para destruir vossos filhos. Peste e sangue passarão por vós e trarei uma espada contra ti. Eu, Yahweh, declarei isso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, '\"Filho do homem, vira o teu rosto para os montes de Israel e profetiza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'E dize: \'Montes de Israel, ouvi a palavra de Yahweh Deus! Assim diz Yahweh Deus aos montes e aos outeiros, aos ribeiros e aos vales. Eis que trago uma espada contra vós e destruirei os vossos altares nas colinas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Então, vossos altares serão desolados e os altares de incenso serão destruídos; destroçarei os vossos mortos diante de seus ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Lançarei os mortos de Israel diante de seus ídolos e espalharei vossos ossos em redor de vossos altares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Em todo lugar onde viverem, cidades serão destruídas e os altares das colinas serão arruinados, de tal modo que vossos altares serão destruídos e desolados. Depois, vossos ídolos serão quebrados e desaparecerão, vossos altares de incenso serão cortados e vossas obras serão desfeitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Os mortos cairão no vosso meio e sabereis que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Mas preservarei o remanescente dentre vós e haverá alguns que escaparão da espada dentre as nações, quando fordes espalhados por entre os países.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Então, os que escaparem, lembrarão de Mim entre as nações onde serão postos em cativeiro, que fiquei entristecido pelos seus corações imorais que se desviaram de Mim, e pelos seus olhos que se prostituíram seguindo seus ídolos. Depois, mostrarão nojo em seu rosto por causa da impiedade que cometeram com todas as suas abominações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Assim, saberão que Eu sou Yahweh. Foi por esta razão que Eu disse que lhes traria este mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Assim diz Yahweh Deus: Bate com as mãos e com os pés. E dize: \'Ah!\', por causa de todas as abominações malignas da casa de Israel, eles cairão pela espada, fome e praga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'O que estiver longe morrerá pela praga e o que estiver perto morrerá pela espada. O remanescente que for poupado morrerá pela fome. Dessa forma, cumprirei a Minha fúria contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Então, sabereis que Eu sou Yahweh, quando os seus mortos estiverem estendidos no meio dos seus ídolos, em redor dos seus altares, em toda montanha alta, em todos os picos dos montes e debaixo de toda a árvore viçosa e carvalho frondoso, os lugares onde queimaram incensos a todos os seus ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Estenderei a mão contra eles e deixarei a terra desolada e destruída, do deserto a Dibla, em todos os lugares onde vivem. Então, eles saberão que Eu sou Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, '\"Tu, filho do homem, Yahweh Deus diz isto à terra de Israel: \'O fim, o fim chegou aos quatro cantos da terra\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'O fim sobreveio a ti, eis que derramarei Minha ira sobre ti, e te julgarei de acordo com os teus caminhos; e trarei sobre ti todas as tuas abominações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Os Meus olhos não terão compaixão de ti, e não te pouparei. Pelo contrário, trarei sobre ti os teus caminhos, e as tuas abominações estarão no meio de ti. Então, sabereis que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Assim diz Yahweh Deus: Desastre! Um desastre ímpar! Vede, está vindo. Eis que vem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'O fim certamente está vindo. O fim despertou contra ti. Eis que está vindo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'A sentença vem para ti que habita na terra. O tempo chegou! Próximo está o dia da destruição e os montes não mais se regozijarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Em breve, lançarei Minha fúria contra ti e encherei Minha ira sobre ti; quando Eu te julgar de acordo com os teus caminhos e trouxer todas as tuas abominações sobre ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Porque Meu olho não olhará compassivamente e Eu não te pouparei. Conforme os teus caminhos, farei a ti; e as tuas abominações estarão no meio de ti. E sabereis que Eu sou Yahweh, aquele que vos está castigando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Eis o dia! Eis que está vindo! Veio a tua ruína, já floresceu a vara, já brotou a soberba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'A violência se levantou para servir de vara de impiedade; nenhum deles e nenhum da sua multidão; nada da sua riqueza, e nada do seu valor perdurará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'O tempo está vindo; o dia está próximo. Não deixes o comprador se alegrar, nem que o vendedor se lamente, porque Minha ira está sobre a multidão inteira!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Porquanto o vendedor nunca mais voltará a ter o que vendeu, ainda que vivam, pois a profecia é contra toda a multidão. Eles não retornarão, porque nenhum homem, vivendo em seu pecado, será fortalecido!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Tocaram a trombeta e prepararam tudo, mas ninguém está marchando para a batalha; porque Minha ira está sobre toda a multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'A espada está fora, mas a praga, e a fome estão dentro da casa. Os que estão no campo morrerão à espada, enquanto a fome e a praga consumirão os que estão na cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Mas sobreviventes escaparão dentre eles e irão aos montes. Como as pombas dos vales, todos eles gemerão, cada um pela sua iniquidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Todas as mãos se tornarão débil e todos os joelhos esmorecerão como água;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'e vestirão pano de saco, terror lhes cobrirá, vergonha estará em todos os rostos, calvície em todas as cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Lançarão a sua prata nas ruas e o seu ouro será como sujeira. A sua prata e o seu ouro não os poderão resgatar no dia da ira de Yahweh. Suas vidas não serão salvas e sua fome não será satisfeita, porque sua iniquidade tornou-se uma pedra de tropeço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Em sua soberba, levaram a beleza dos seus ornamentos de joias e, com elas, fizeram suas imagens de idolatria e coisas detestáveis. Portanto, Eu estou tornando isso em coisas impuras para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Depois, entregarei essas coisas nas mãos dos estrangeiros, como presa, e, aos corruptos da terra, como presa, e eles os profanarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Então, desviarei deles a Minha face quando eles profanarem o Meu lugar secreto; salteadores entrarão e o profanarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Faze uma cadeia; porque a terra está cheia de juízo de sangue e a cidade está repleta de violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Portanto, trarei os mais iníquos das nações, os quais tomarão as suas casas e porei um fim à soberba dos seus valentes, porquanto os seus lugares santos serão profanados!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Haverá angústia! Buscarão paz, mas paz nenhuma haverá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Virá desastre sobre desastre, e haverá rumor sobre rumor. Então, procurarão uma visão do profeta, mas a lei do sacerdote perecerá e o conselho dos anciãos perecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'O rei lamentará e o príncipe se vestirá de desespero, enquanto as mãos do povo da terra tremerão de medo. Assim, procederei com eles: segundo os seus próprios caminhos. Com seus próprios juízos, Eu os julgarei, até que saibam que Eu sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Aconteceu que, no sexto ano, no sexto mês, no quinto dia do mês, quando me sentei em minha casa e os anciãos de Judá se assentaram diante de mim, novamente, a mão de Yahweh Deus caiu sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Olhei, e eis que havia algo com a aparência de um homem. Da cintura para baixo, era fogo e, da cintura para cima, era a aparência de algo que brilha, como metal brilhante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Então, ele estendeu para mim o que parecia uma mão e pegou-me pelos cabelos da minha cabeça; o Espírito me levantou entre a terra e o céu e, em visões de Deus, ele me levou para Jerusalém, à entrada do portão interior ao norte, onde o ídolo que provoca grande ciúme estava colocado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'E eis que a glória do Deus de Israel estava ali, conforme a semelhança que eu havia visto no vale.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Então, Ele me disse: \"Filho do homem, levanta os teus olhos para o norte\". Então, levantei os meus olhos para o norte e, ao norte do portão que leva ao altar; à entrada, estava o ídolo do ciúme.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Ele me disse então: \"Filho do homem, vês o que estão fazendo? Estas são grandes abominações que a casa de Israel está fazendo aqui para Me afastar do Meu santuário. Mas tu verás maiores abominações ainda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Então, ele me trouxe à porta do pátio e olhei; havia um buraco na parede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Ele me disse: \"Filho do homem, cava nesta parede\". Então, cavei na parede e havia uma porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Então, Ele me disse: \"Vai e vê as abominações corruptas que estão fazendo aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Então, entrei e olhei, e eis que havia toda a sorte de animais que se arrastam, e de animais abomináveis, e todos os ídolos da casa de Israel estavam esculpidos na parede em todo o derredor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Setenta anciãos da casa de Israel estavam lá e Jazanias, filho de Safã, estava em pé meio deles. Eles estavam em pé diante das imagens e cada um tinha o incensário na mão para que o aroma do incenso subisse em uma nuvem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Ele me disse: \"Filho do homem, vês o que os anciãos da casa de Israel estão fazendo nas trevas? Cada um faz isso na câmara oculta do seu ídolo, porque dizem: \'Yahweh não nos vê! Yahweh abandonou a terra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Então, Ele me disse: \"Vira novamente e vê as outras grandes abominações que estão fazendo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Em seguida, levou-me à entrada da porta da casa de Yahweh, que estava no lado do norte, e eis que as mulheres estavam sentadas lá, de luto por Tamuz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Então, disse-me: \"Vês isso, filho do homem? Vira de novo e vê ainda maiores abominações do que essas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Ele me pôs no pátio interior da casa de Yahweh e, eis que à entrada do templo de Yahweh, entre o pórtico e o altar, havia cerca de vinte e cinco homens de costas para o templo de Yahweh; com seus rostos para o leste, eles estavam adorando o sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Ele me disse: \"Vês isso, filho do homem? É algo pequeno para a casa de Judá fazer essas abominações que eles estão fazendo aqui? Porque encheram a terra com violência e voltaram a provocar-Me à ira, colocando o ramo aos seus narizes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Assim também Eu agirei entre eles com furor; Meus olhos não terão compaixão e não os pouparão. Ainda que gritem em Meus ouvidos em alta voz, não os ouvirei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Então, Ele clamou aos meus ouvidos em alta voz, dizendo: \"Deixa que os guardas subam à cidade, cada um com suas armas de destruição nas mãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Eis que vinham seis homens do caminho da porta superior do lado norte, cada um trazendo a sua arma destruidora. Havia um homem no meio deles vestido de linho com um estojo de escrivão em sua cintura. Eles entraram e pararam ao lado do altar de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Então, a glória do Deus de Israel se levantou de sobre o querubim, do lugar onde ele estava, e foi para a entrada da casa. Ele chamou o homem vestido de linho, o que tinha um estojo de escrivão na cintura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'E Yahweh disse: \"Passa pelo meio da cidade de Jerusalém e marca com um sinal a testa dos homens que suspiram e gemem por causa de todas as abominações que cometem no meio dela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Enquanto eu escutava, Ele falou para os outros: \"Passai no meio da cidade após ele, e matai. Não deixeis que vossos olhos tenham compaixão e não poupeis,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'nem homens idosos, nem jovens, nem virgens, nem crianças ou mulheres. Matai todos! Mas não vos aproximeis de ninguém que tenha o sinal na testa. Começai pelo Meu Santuário!\". Então, eles começaram pelos anciãos que estavam em frente à casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Ele lhes disse: \"Profanai a casa, enchei o pátio com os mortos. Ide!\" Então, eles foram e atacaram a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Assim que eles a atacaram, encontrei-me sozinho, caí com rosto em terra e lamentei dizendo: \"Ah, Senhor Yahweh, Tu destruirás todo o remanescente de Israel no derramamento da Tua ira em Jerusalém?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Ele me disse: \"A iniquidade da casa de Israel e Judá é excessivamente grande. A terra está cheia de sangue e a cidade, cheia de perversões; eles dizem: \'Yahweh esqueceu da terra, Yahweh não vê!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Por isso, Meus olhos não verão com compaixão e Eu não lhes pouparei. Pelo contrário, trarei tudo isso sobre a cabeça deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'E e eis que o homem, vestido de linho que tinha o estojo de escrivão na cintura, voltou. Ele voltou com a resposta dizendo: \"Eu fiz tudo o que me mandaste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Quando eu olhei para a redoma que estava acima das cabeças dos querubins, algo apareceu por cima deles, como se fosse uma pedra de safira, com a aparência semelhante a um trono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Então, Yahweh falou com o homem vestido de linho e disse: \"Vai para o meio das rodas, por baixo dos querubins, e pega em tuas mãos as brasas acesas que estão entre os querubins, e as espalhe sobre a cidade\". Então, enquanto eu olhava, o homem entrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Os querubins estavam em pé, ao lado direito da casa, quando o homem entrou e uma nuvem cobriu o pátio interior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'A glória do Senhor saiu dos querubins, parou sobre a entrada da casa e a encheu com a nuvem; o pátio ficou cheio do brilho da glória do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Ouvia-se o som das asas dos querubins até o pátio exterior, como a voz do Deus Poderoso quando Ele fala.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Aconteceu que, quando Deus ordenou ao homem vestido de linho, dizendo: \"Pega o fogo do meio das rodas que está entre os querubins\", o homem entrou e parou ao lado das rodas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Então, um querubim estendeu sua mão para o fogo que estava no meio deles, apanhou as brasas e as colocou nas mãos daquele que estava vestido de linho. O homem pegou as brasas e saiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Vi, sobre os querubins, algo como se fosse a mão de um homem por baixo de suas asas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Então, olhei e eis que quatro rodas estavam ao lado dos querubins, uma roda ao lado de cada querubim; a aparência das rodas parecia com uma pedra de berilo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Sua aparência era a mesma: cada uma das quatro como se fosse uma roda dentro da outra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Quando elas se moviam, iam em qualquer das quatro direções sem se virar, mas andavam para onde a cabeça se dirigisse; não se viraram em nenhuma outra direção enquanto iam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Todo o corpo deles, incluindo suas costas, mãos e asas, estava coberto de olhos; e os olhos cobriam as quatro rodas em todo o redor delas também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'E ouvi que as rodas eram chamadas de \"giratórias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Cada querubim tinha quatro faces: a primeira era a face de um querubim, a segunda era a face de um homem, a terceira era a face de um leão, e a quarta era a face de uma águia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'E os querubins, que eram os seres viventes que vi junto ao rio Quebar, elevaram-se ao alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Quando os querubins se moviam, as rodas iam ao lado deles; e, quando os querubins levantavam suas asas da terra, as rodas não mudavam de direção, mas continuavam ao lado deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Quando os querubins paravam, as rodas também paravam e, quando se elevavam, as rodas também se elevavam, porque o Espírito do ser vivente estava nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Então, a glória do Senhor saiu da entrada da casa e parou sobre os querubins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Os querubins levantaram suas asas, subindo da terra, enquanto eu os via saindo, e as rodas fizeram o mesmo ao lado deles. Pararam à entrada do oriente da casa de Yahweh e a glória do Deus de Israel veio sobre eles do alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'São esses os seres viventes que vi abaixo do Deus de Israel, perto do rio Quebar, e percebi que eram querubins.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Cada um deles tinha quatro faces e quatro asas e, debaixo das asas, havia algo semelhante a mãos humanas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'E a semelhança de seus rostos era como a daqueles que vi na visão do rio Quebar e cada um andava para a sua frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Então, o Espírito me levantou e me trouxe para a porta oriental da casa de Yahweh, voltada ao oriente. Eis que contemplei, diante do portão, vinte e cinco homens. Vi Jazanias, filho de Azur, e Pelatias, filho de Benaías, líderes do povo, no meio deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Deus me disse: \"Filho do homem, estes são os homens que fazem planos de iniquidade e aconselham perversamente nesta cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Eles dizem: \'Não é agora o tempo de edificar casas; esta cidade é a panela e nós somos a carne\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Por isso, profetiza contra eles. Profetiza, filho do homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Então, o Espírito de Yahweh veio sobre mim e me disse: \"Dize: \'Assim diz Yahweh\': Como vós dizeis, ó casa de Israel, porque Eu sei o que pensais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Multiplicastes os vossos mortos nesta cidade e, com eles, enchestes as estradas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Por isso, Yahweh Deus diz: As pessoas que matastes, cujos corpos colocastes no meio de Jerusalém, são a carne, e esta cidade é a panela. Mas vós sereis arrancados para fora desta cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Vós temeis a espada, portanto, Eu trago espada sobre vós, esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Eu vos tirarei do meio da cidade e vos colocarei nas mãos de estranhos e trarei julgamento contra vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Caireis à espada. Eu vos julgarei no interior das fronteiras de Israel e sabereis que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Esta cidade não será vossa panela, nem vós sereis a carne dentro dela. Eu vos julgarei no interior das fronteiras de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Então, vós sabereis que Eu Sou Yahweh, Aquele cujos estatutos vós não andastes neles, e cujos decretos não obedecestes. Ao contrário, tendes procedido conforme os decretos das nações que vos rodeiam\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Aconteceu que, enquanto eu profetizava, Pelatias filho de Benaías, morreu. Então, caí sobre o meu rosto e chorei em alta voz dizendo: \"Ah, Senhor Yahweh, destruirás completamente o resto de Israel?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Filho do homem, os teus irmãos! Os teus próprios irmãos! Os homens de teu parentesco e de toda casa de Israel! Todos eles são aqueles de quem os habitantes de Jerusalém disseram: \'Eles estão longe de Yahweh! Esta terra nos foi dada como possessão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Portanto, dize: \"Assim diz Yahweh Deus: \'Apesar de tê-los removido para longe entre as nações, e, embora Eu os tenha espalhalho entre as terras, mesmo assim, Eu tenho sido um santuário para eles por pouco tempo nas terras para onde foram\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Portanto dize: \'Assim diz Yahweh Deus: Eu vos juntarei dentre os povos e vos congregarei das terras para onde fostes espalhados; darei a vós a terra de Israel\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Então, eles irão e removerão todas coisas detestáveis e todas as abominações deste lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Eu lhes darei um só coração e porei neles um espírito novo. Tirarei deles o coração de pedra e lhes darei um coração de carne,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'para que eles andem nos Meus estatutos, guardem os Meus decretos e os pratiquem. Eles serão Meu povo e Eu serei o seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Mas para aqueles que andam com os corações voltados para as suas coisas detestáveis e suas abominações, Eu farei recair as suas obras sobre as suas cabeças, esta é a declaração de Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Os querubins levantaram suas asas, e as rodas ao seu lado os acompanhavam, e a glória do Deus de Israel estava sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Então, a glória de Yahweh subiu desde o meio da cidade e ficou no monte que está ao oriente da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'O Espírito me levantou e me levou até a Babilônia, junto com os exilados, em visão pelo Espírito de Deus, e a visão que havia tido desapareceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'E eu declarei aos exilados todas as coisas que Yahweh havia me mostrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Veio a mim a palavra de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, '\"Filho do homem, tu vives no meio da casa rebelde, que tem olhos para ver mas não vêem, e ouvidos para ouvir mas não ouvem, porque é casa rebelde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Quanto a ti, filho do homem, prepara as tuas coisas para o exílio, e prepara para sair de dia, à vista deles, porque Eu te enviarei ao exílio à vista deles, do lugar que vives para um outro lugar. Talvez eles comecem a perceber, embora sejam casa rebelde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Tu tirarás tuas coisas para o exílio de dia à vista deles; sairás de tarde à vista deles, como alguém que vai para o exílio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Faze um buraco na parede, à vista deles, e sai através dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Levarás os teus pertences em teus ombros, à vista deles; às escuras os transportarás. Cobre a tua face, para que não vejas a terra, porque Eu te coloquei como sinal para a casa de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'E eu fiz como fui ordenado. Durante o dia eu tirei os meus pertences, como se fosse para o exílio, e de tarde fiz um buraco na parede com as mãos. Tirei meus pertences na escuridão, e levantei-os e coloquei nos ombros à vista deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Então, veio a mim a palavra de Yahweh pela manhã, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, '\"Filho do homem, não te perguntou a casa de Israel, esta casa rebelde: \'O que estás fazendo?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Dize-lhes: \'Assim diz Yahweh Deus: Esta ação profética se refere aos príncipes em Jerusalém, e a toda casa de Israel que está no meio deles\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Dize: \'Eu sou um sinal para vós. Assim como fiz, será feito a eles; eles irão para o exílio e para o cativeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'O príncipe que está no meio deles levantará seus pertences nos ombros, na escuridão, e sairá pela parede. Eles escavarão a parede e tirarão as suas coisas. Ele cobrirá a sua face, e não verá a terra com seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Também estenderei a minha rede sobre ele e será apanhado em minha armadilha; e então, o levarei para Babilônia, a terra dos Caldeus, mas ele não a verá, ele morrerá ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Espalharei também, em toda direção, todos os que estiverem ao redor dele para seu socorro, bem como todo seu exército, e enviarei a espada atrás deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Então, eles saberão que Eu sou Yahweh, quando lhes espalhar no meio das nações e os dispersar por toda parte da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Mas pouparei alguns homens no meio deles, da espada e da praga, para que contem todas as suas abominações entre as nações para onde forem, e saberão que Eu sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Veio a mim a palavra de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, '\"Filho do homem, come o teu pão com tremor, e bebe a tua água com estremecimento e com receio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Então, dize ao povo da terra: \"Assim diz Yahweh Deus acerca dos habitantes de Jerusalém e da terra de Israel: Eles comerão o seu pão com tremor e beberão a sua água estremecendo, pois a terra será despojada da sua abundância, por causa da violência daqueles que vivem nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'E as cidades onde habitam serão desoladas; a terra será improdutiva; e sabereis que Eu sou Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Veio outra vez a palavra do Senhor a mim dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, '\"Filho do homem, que provérbio é este que vós tendes na terra de Israel que diz: \'Os dias estão prolongados e toda visão falhou\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Portanto, dize-lhes: \'Assim diz Yahweh Deus: Eu porei fim neste provérbio e o povo de Israel não o usará mais\'. Fala para eles: \'Os dias estão próximos, quando toda visão será cumprida\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Porque não haverá mais falsas visões ou adivinhações no meio da casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Porque Eu, Yahweh, falo e realizo as palavras que digo. Não será mais adiada. Pois Eu falarei essa palavra em vossos dias, casa rebelde, e cumprirei! Esta é a declaração de Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'E veio, de novo, a palavra de Yahweh a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, '\"Filho do homem! Vê, a casa de Israel tem dito: \'A visão que ele vê é para muitos dias no futuro e ele profetiza sobre os tempos que estão longe\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Portanto, dize-lhes: \'Assim diz Yahweh Deus: As Minhas palavras não serão mais adiadas; a palavra que Eu falei se cumprirá — essa é a declaração de Yahweh Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Outra vez, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, '\"Filho do homem, profetiza contra os profetas que estão profetizando em Israel e dize-lhes que estão profetizando a partir das suas próprias imaginações. \'Ouvi a palavra de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Yahweh Deus diz isto: Ai dos falsos profetas que segue seu próprio espírito, mas não veem nada!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Ó, Israel, os seus profetas têm sido como raposas numa terra inóspita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Tu não subiste às brechas do muro ao redor da casa de Israel para repará-la, para que ela resista à batalha no dia de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'O povo tem falsas visões e faz falsas previsões; e aqueles que dizem: \'Esta é a declaração de Yahweh\'. Yahweh não os enviou; eles, todavia, têm trazido mensagens mentirosas ao povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Acaso não tivestes falsas visões e falsas previsões, quando dissestes: \'Tal é a declaração de Yahweh\', quando Eu não falei isso?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Portanto, assim diz Yahweh Deus: \'Porque tendes tido falsas visões e tendes mentido, esta é a declaração de Yahweh Deus contra vós:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Minha mão será contra os profetas com visões falsas e aqueles com falsas previsões. Eles não estarão na assembleia do Meu povo ou inscritos no registro da casa de Israel; não irão para terra de Israel. Pois sabereis que Eu sou Yahweh Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Por isso, porque eles levam Meu povo a se desviar, dizendo: \'Paz!\' quando não há paz, eles constroem uma parede e a rebocam com cal\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Dize àqueles que estão rebocando a parede com cal: \'Esta vai cair; virá uma pancada de chuva e enviarei granizo para derrubá-la e um vento tempestuoso a rachará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Vede, o muro vai cair. Os outros não vos disseram: \'Onde está o cal que foi colocado nele?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Portanto, assim diz Yahweh Deus: Trarei uma tempestade em Meu furor, e, na Minha ira, haverá inundação de chuva! No Meu furor, a chuva de granizo o destruirá completamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Eu derrubarei a parede coberta com cal e a demolirei, para que seja descoberta a sua fundação. Assim, cairá e vós perecereis no meio dela. E sabereis que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Assim, cumprirei o Meu furor contra a parede e contra aqueles que colocaram cal nela. Eu direi a vós: \'A parede não existe mais e nem o povo que a cobriu com cal,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'os profetas de Israel que profetizaram acerca de Jerusalém e que tiveram visões de paz para ela. Mas não há paz! — esta é a declaração de Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Então, tu, filho do homem, põe o teu rosto contra as filhas do teu povo, que profetizam de seu próprio entendimento, e profetiza contra elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'E dize: \'Assim diz Yahweh Deus: Ai das mulheres que costuram pulseiras mágicas para todas as juntas das mãos e que fazem véus da medida de suas cabeças, usadas para caçarem o povo. Caçarás o Meu povo, mas salvarás as tuas próprias vidas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Vós Me profanastes no meio do Meu povo por punhados de cevada e migalhas de pão, para matar o povo que não deveria morrer e para manter vivos os que não deveriam viver, por causa das vossas mentiras para o Meu povo que vos escutava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Portanto, assim diz Yahweh Deus: Estou contra as vossas pulseiras mágicas que são usadas para caçar vidas, como se fossem pássaros. Certamente, Eu as rasgarei de vossos braços; e o povo, a quem caçastes como pássaros, Eu os livrarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Eu também rasgarei vossos véus e salvarei Meu povo das vossas mãos; e eles nunca mais serão presas em vossas mãos. E vós sabereis que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Visto que entristecestes o coração das pessoas justas com mentiras, mesmo Eu não desejando isso, e fortalecestes os perversos para não deixarem o seu caminho e salvarem sua vida —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'portanto, não tereis mais visões falsas nem continuareis a fazer previsões, pois Eu resgatarei o Meu povo das vossas mãos. E sabereis que Eu sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Alguns dos anciãos de Israel vieram e se sentaram diante de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, '\"Filho do homem, estes homens deram lugar em seus corações aos ídolos e colocaram o tropeço de sua maldade diante de sua própria face. Deveria Eu ser consultado por eles?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Portanto, anuncia isto a eles: \'Assim diz Yahweh Deus: Qualquer homem de Israel que, depois de guardar seus ídolos no coração, ou colocar tropeço de maldade diante de sua face, vier consultar os profetas, Eu, Yahweh, lhes responderei conforme a multidão de seus ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Eu farei isto para reconquistar os corações da casa de Israel, que foram afastados de Mim, através dos seus ídolos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Portanto, diz à casa de Israel: \'Assim diz Yahweh Deus: Arrependei-vos e deixai os vossos ídolos! Desviai o rosto de todas as vossas abominações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Pois a todos os da casa de Israel e a todos os estrangeiros que vivem em Israel, que Me abandonam, guardam seus ídolos no coração, colocam tropeço de maldade diante deles e que, depois, vêm consultar o profeta, Eu mesmo, Yahweh, lhes responderei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Virarei Meu rosto contra esses homens e farei deles um sinal e um provérbio, Eu os eliminarei do meio do Meu povo e vós sabereis que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Se um profeta for enganado e falar a mensagem, então, Eu, Yahweh, enganarei este profeta; estenderei Minha mão contra ele e o destruirei do meio do Meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Eles levarão suas próprias iniquidades; e a iniquidade do profeta será a mesma iniquidade daquele que consultá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Para que a casa de Israel não se desvie de seguir-Me e nem se contamine por estas transgressões. Eles serão o Meu povo e Eu serei o seu Deus, esta é a palavra de Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, '\"Filho do homem, quando um povo pecar contra Mim, cometendo graves transgressões, Eu estenderei Minha mão contra ele e cortarei sua provisão, enviando fome sobre ele e seus animais, exterminando-os da terra;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'e, mesmo se estes três homens — Noé, Daniel e Jó — estivessem ali, poderiam somente livrar suas próprias vidas, por sua justiça\" — esta é a palavra de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, '\"Se Eu enviar animais selvagens pela terra e eles a devastarem, e ela se tornar improdutiva por causa dos animais,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'mesmo se esses três homens estivessem nela — assim como Eu vivo, diz Yahweh Deus — eles não poderiam salvar nem mesmo seus próprios filhos ou suas filhas; apenas suas vidas seriam poupadas e a terra seria desolada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Ou, se Eu trouxer a espada contra aquela terra e disser: \'Espada, passa pela terra e extermina o homem e o animal dela\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'mesmo se esses três homens estivessem nela — assim como Eu vivo, diz Yahweh — eles não poderiam salvar nem mesmo seus próprios filhos ou suas filhas; apenas suas vidas seriam resgatadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Ou, se Eu enviar a peste sobre esta terra e derramar meu furor contra ela com derramamento de sangue, para eliminar homem e animal,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'mesmo se Noé, Daniel e Jó estivessem nessa terra — assim como Eu vivo, declara Yahweh Deus — eles não poderiam nem mesmo salvar seus filhos ou suas filhas; apenas suas próprias vidas seriam resgatadas, pela sua justiça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Porque assim diz Yahweh Deus: \"Certamente, irei piorar a situação enviando contra Jerusalém Minhas quatro punições — fome, espada, animais selvagens e peste — para eliminar todo homem e todo animal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Mas, se houver sobreviventes que levem para fora os filhos e as filhas que foram deixados na cidade, eis que, quando eles vierem a vosso encontro, vereis seus caminhos e suas ações; e ficareis consolados da punição que Eu enviei para Jerusalém e de tudo que Eu enviei sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Os sobreviventes irão consolar-vos quando virdes os seus caminhos e suas ações, e sabereis que não fiz isto em vão — esta é a palavra de Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, '\"Filho do homem, como pode a videira ser melhor que qualquer árvore com galhos que está entre as árvores da floresta?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'O povo tira madeira da videira para fazer alguma coisa? Ou fazem eles uma estaca para pendurar alguma coisa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Olha! Se ela é jogada no fogo como combustível, e, se o fogo queima tanto o meio como o fim dela, seria útil para alguma coisa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Vê! Quando estava inteira, não servia para nada; quando o fogo queimar, aí é que não servirá para nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Portanto, Yahweh Deus diz: Ao invés de entregar as árvores do bosque, entreguei a videira como combustível para ser queimada; do mesmo jeito farei com os habitantes de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Voltarei a Minha face contra eles. Mesmo que tenham saído do fogo, ainda assim, o fogo os consumirá; então, tu saberás que Eu sou Yahweh, quando Eu virar a Minha face contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Então, Eu farei com que a terra fique abandonada e sem serventia, porque eles têm cometido pecado — esta é a declaração de Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Então, veio a mim a palavra de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, '\"Filho do homem, informa a Jerusalém sobre as suas abominações');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'e declara: \'Assim diz Yahweh Deus a respeito de Jerusalém: A tua origem e o teu nascimento vêm da terra dos cananeus; teu pai era amorreu e tua mãe, heteia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'No dia em que nasceste, a tua mãe não cortou teu umbigo, nem foste lavada com água, para tua purificação, nem esfregada com sal; nem foi embrulhada com vestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Nenhum olho se compadeceu de ti para fazer qualquer uma dessas coisas a teu favor, mas, com nojo de ti, te lançaram em campo aberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Mas Eu passei por ti, vi-te manchada no teu sangue; então, disse a ti: \'Vive!\', Eu te disse quando estava ainda ensanguentada, \'vive!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Eu te fiz crescer como a planta na terra. Tu te multiplicaste e te engradeceste tornando jóia das jóias. Os teus seios tornaram-se firmes e seu cabelo cresceu, mas tu estavas nua e estéril.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Passei novamente por ti. Vê! O tempo de amor veio a ti, então, Eu estendi sobre ti o Meu manto e cobri a tua nudez. Então, jurei e fiz aliança contigo — esta é a declaração de Yahweh — e passaste a ser Minha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Então, Eu te lavei com água, enxuguei teu sangue de ti e ungi com óleo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Eu te vesti com roupas bordadas, calcei teus pés com sandálias de couro nobre. Eu te envolvi com linho fino e te cobri com seda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'De joias, Eu te adornei, coloquei braceletes em teus braços e um colar em teu pescoço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Eu coloquei um pendente em teu nariz, brincos nas tuas orelhas e uma linda coroa em tua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Assim foste adornada com ouro e prata; e foste vestida com linho fino, seda e roupas bordadas; comeste de farinha excelente, mel e óleo; eras muito formosa e te tornaste rainha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'E a tua fama correu entre as nações por causa da tua beleza, pois eras perfeita pela majestade que te dei — assim diz Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Mas confiaste em tua formosura e te corrompestes como uma prostituta por causa da tua fama, prostituindo-te a todos que passavam por ti e tua beleza se tornou deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Depois, tomaste as tuas vestes e, com elas, adornaste, de várias cores, os lugares altos e te comportaste como uma prostituta. Isso não deveria ter acontecido. Nem deveria tal coisa ter existido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Tu tomaste das excelentes jóias de ouro e de prata que te dei; fizeste imagens de homens e te prostituiste como querias com elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Tu tomaste as tuas vestes bordadas e as cobriste; puseste, diante delas, Meus óleos e perfumes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'O Meu pão que te dei — feito de farinha fina, óleo e mel — puseste diante dos ídolos como cheiro suave, isso foi o que aconteceu — esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Além disso, tomaste teus filhos e tuas filhas que gerastes para Mim e os sacrificaste às imagens para serem devorados como comida. Será que era tão pequena a tua fama de prostituição,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'que ainda tinhas que matar Meus filhos e entregá-los como oferta queimada?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Em todas as tuas abominações e nos atos da tua prostituição, não lembraste dos dias da tua mocidade, quando estavas nua e estéril, debatendo-te em teu sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Ai! Ai de ti! — esta é a palavra de Yahweh Deus — além de todo esse pecado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'tu edificaste lugar de adoração e altares em todos os locais públicos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Edificaste o teu lugar alto em todo começo de caminho e profanaste tua formosura, ofereceste o teu corpo a todos que passavam e multiplicaste tua prostituição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Agiste como uma prostituta com os egípcios, com teus vizinhos com corpos avantajados, e praticaste muitos outros atos de prostituição, provocando-Me a ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Olha! Eu te destruirei com a Minha mão e tirarei a tua porção. Entregarei a tua vida aos teus inimigos, as filhas dos filisteus, as quais se envergonharam do teu comportamento obceno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Agiste como uma prostituta com os assírios, porque eras insaciável. Agiste como uma prostituta e, mesmo assim, não te saciaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Tu te prostituíste muito mais na terra dos mercadores da Caldeia, e, mesmo assim, não te saciaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Quão fraco é o teu coração — assim diz Yahweh Deus — fazendo tu estas coisas e agindo como uma prostituta sem vergonha?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Edificaste o teu prostíbulo em cada caminho e fizeste o teu altar em cada rua; não foste nem mesmo como uma prostituta, pois recusaste até teu pagamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Tu, mulher adúltera, aceitaste os estranhos em lugar de teu marido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Homens pagam para toda prostituta, mas tu dá salários a todos os teus amantes e os subornas para que venham prostituirem-se contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Então, esta é a diferença entre tu e todas outras mulheres, pois nenhum homem vai pedir que durmas com eles. Ao invés disso, tu fazes o contrário, pagas a eles. Ninguém te paga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Portanto, tu prostituta, escuta a palavra de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Yahweh Deus diz: Porque tens derramado tua volúpia e descoberto tua nudez para a prostituição com teus amantes e com teus ídolos abomináveis, por causa do sangue dos teus filhos que lhe destes;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'por este motivo, Eu ajuntarei todos teus amantes com os quais te encontraste, todos os que amaste, junto com aqueles os quais tu odiaste, Eu os ajuntarei contra ti de todos os lados. Exporei tuas partes íntimas diante deles, para que vejam toda tua nudez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Eu te punirei por adultério e derramamento de sangue e trarei sobre ti o derramar de sangue da Minha ira e paixão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'E te entregarei nas mãos de teus inimigos e eles derrubarão os teus lugares de adoração a ídolos e demolirão os teus altares, desnudarão as tuas vestes, tomarão todas as tuas jóias, deixando-te nua e despida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Então, subirá uma multidão contra ti, apedrejarão e cortarão a ti com suas espadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Queimarão tuas casas, executarão juízos e julgamentos a ti aos olhos de muitas mulheres; farei cessar a tua prostituição e já não mais pagarás aos seus amantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Então, acalmarei a Minha fúria contra ti; Minha ira se desviará de ti, sossegarei e não mais Me indignarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Porque não te lembraste dos dias da tua mocidade e Me provocaste a ira por causa de todas estas coisas, por isso, cuidado! Eu farei a punição por tudo aquilo que fizeste — esta é a declaração de Yahweh Deus. Não acrescentaste infidelidade para todas as tuas outras práticas detestáveis?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Eis que todos aqueles que falam em provérbios a teu respeito dirão: \"Tal como é a mãe, também é a filha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Tu és a filha de tua mãe, que detestou seu marido e seus filhos, tu és a irmã de tuas irmãs, que detestaram seus maridos e seus filhos. Tua mãe era heteia e teu pai amorreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Tua irmã mais velha era Samaria e suas filhas era as que habitavam ao norte; enquanto a tua irmã mais nova era a única que vivia ao teu lado sul, isto é, Sodoma e suas filhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Tu não só andavas nos caminhos deles, como imitavas as práticas de suas abominações, mas, em todos teus caminhos, foste pior que eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Assim como Eu vivo — diz Yahweh Deus — tua irmã Sodoma e suas filhas não fizeram tanto quanto tu e tuas filhas fizestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Eis que este era o pecado da tua irmã Sodoma: ela era arrogante em seu ócio, distraída, despreocupada de qualquer coisa. Ela nunca estendeu a mão para o pobre e o necessitado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Ela era arrogante e praticava abominações diante de Mim, então, Eu as removi do seu lugar, como tu viste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'E nem mesmo Samaria praticou metade de teus pecados; tu fizeste coisas mais abomináveis que ela e mostraste que tuas irmãs eram melhores que tu, por causa das abominações que fizeste!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'E tu, mostra a tua vergonha; dessa maneira, tu tens mostrado que tuas irmãs foram melhores que tu, por causa dos pecados que cometeste em todos caminhos abomináveis. Tuas irmãs agiram de melhor forma; especialmente tu, mostra a tua vergonha, pois, dessa maneira, mostra que tuas irmãs têm agido melhor que tu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Pois Eu restaurarei a sorte de Sodoma — a sorte de Sodoma e suas filhas; a sorte de Samaria e suas filhas; e a tua sorte ficará entre elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'E, por causa destas coisas, serás envergonhada de todas as coisas que cometeste e isso será um conforto para elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Tua irmã Sodoma e suas filhas serão restauradas, como Samaria e suas filhas serão restauradas em suas posses. Assim como tu e tuas filhas também serão restauradas à tua condição anterior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Sodoma, tua irmã, nem foi mencionada por ti, nos dias em que eras orgulhosa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'antes que tua corrupção fosse revelada. Mas, agora, tu és objeto do desprezo pelas filhas de Edom e de todos os filisteus ao seu redor, todos te desprezam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Tu serás envergonhada por causa das tuas obras repugnantes! — assim diz Yahweh!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Assim diz Yahweh Deus: \"Tratarei contigo da forma que mereces, pois tu desprezaste o teu juramento quebrando a aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Eu, contudo, Me lembrarei da Minha aliança que fiz contigo, nos dias da tua mocidade, e estabelecerei contigo a Minha aliança eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Então, tu te lembrarás dos teus caminhos e te evergonharás, quando receberes tuas irmãs mais velhas e as mais novas, porque Eu as darei a ti por filhas, mas não por causa da tua aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Eu estabelecerei Minha aliança contigo e tu saberás que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Por esta razão, tu te lembrarás e ficarás envergonhada; nunca mais abrirás a tua boca por causa da tua vergonha, quando Eu te perdoar por tudo que fizeste — assim diz Yahweh Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, '\"Filho do homem, apresenta um enigma e conta uma parábola à casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'Dize-lhes: \'Assim diz Yahweh Deus: Uma grande águia com grandes asas e plumagem comprida, cheia de penas de várias cores, foi para o Líbano e pegou um ramo no topo de uma árvore de cedro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Arrancou-lhe a ponta dos seus ramos e a levou para a terra de Canaã; ela a plantou numa cidade de comerciantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Ela também pegou semente da terra e a plantou num solo fértil. Ela a plantou junto a muitas águas, como um salgueiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Então, brotou e se tornou uma videira baixa, espalhada pelo chão. Seus ramos viraram-se para a águia e suas raízes cresceram debaixo dela. Assim, tornou-se uma videira e produziu ramos e brotos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Mas havia outra grande águia com asas grandes e muitas penas. Eis que esta videira voltou suas raízes para águia e espalhou seus ramos em sua direção, do lugar em que tinha sido plantada, assim seria regada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Ela tinha sido plantada em terra boa, junto a muitas águas, assim produziria ramos e brotaria frutos, para tornar-se uma magnífica videira\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Dize ao povo: \'Assim diz Yahweh Deus: Isto prosperará? A águia não lhe arrancará as suas raízes e não lhe apanhará o seu fruto, para que todas as folhas de seus brotos sequem? Nem braço forte ou muitas pessoas serão necessárias para puxá-la pelas suas raízes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Então, vê! Depois que foi plantada, crescerá? Não murchará quando o vento oriental tocá-la? Secará completamente onde foi plantada\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, '\"Dize à casa rebelde: \'Não sabeis o significado destas coisas? Eis que o rei da Babilônia chegou a Jerusalém e tomou seu rei e seus príncipes e os levou consigo para Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Então, ele tomou um descendente real, fez uma aliança com ele e o fez jurar, também tirou o povo poderoso da terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'para humilhar o reino, para que não se levantasse. Ao manter sua aliança, a terra sobreviverá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Mas o rei de Jerusalém se revoltou contra o rei da Babilônia, ao enviar seus embaixadores ao Egito para que lhe mandassem cavalos e um exército. Será que ele prosperará? Aquele que faz essas coisas escapará? Se ele quebrar a aliança, escapará?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Tão certo como Eu vivo! — assim diz Yahweh Deus — certamente ele morrerá na terra do rei que o constituiu como rei, aquele cujo juramento desprezou e cuja aliança quebrou, ele morrerá no meio da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Faraó, com seu poderoso exército e com sua tropas de muitos homens para a guerra, não o protegerá na batalha, quando o exército da Babilônia construir trincheiras e sitiar os muros a fim de destruir muitas vidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Assim, o rei desprezou o seu juramento ao quebrar a aliança. Eis que ele estendeu a sua mão para fazer uma promessa, e, no entanto, ele fez todas essas coisas; ele não escapará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Portanto, assim diz Yahweh Deus: Tão certo como Eu vivo, não foi o Meu juramento que ele desprezou e a Minha aliança que ele quebrou? Então, trarei a punição sobre a sua cabeça!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Espalharei a Minha rede sobre ele e será pego no Meu laço. Então, o levarei à Babilônia e, lá, executarei juízo sobre ele, pela trapaça que cometeu quando ele Me traiu!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Todos seus refugiados em seus exércitos cairão pela espada e os que permanecerem serão espalhados em todas as direções. Então, sabereis que Eu sou Yahweh; Eu declarei que isto aconteceria\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Assim diz Yahweh Deus: \"Então, tirarei um broto da parte mais alta da árvore de cedro e a plantarei longe de seus ramos tenros. Eu a cortarei e Eu mesmo a plantarei em um alto e sublime monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'A plantarei no alto monte de Israel, então, produzirá ramos e dará frutos e se tornará um cedro majestoso, para que cada pássaro que voa, viva debaixo dele; e se aninharão na sombra de seus ramos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Então, todas as árvores do campo saberão que Eu sou Yahweh. Abati a árvore alta e elevei a árvore baixa, sequei a árvore verde e fiz a árvore seca florescer. Eu sou Yahweh, declarei que isso aconteceria; e o tenho feito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Veio a mim, mais uma vez, a palavra de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, '\"Que quereis dizer, vós que usais este provérbio em relação à terra de Israel: \'Os pais comeram uvas verdes e os dentes dos filhos ficaram ásperos\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Tão certo como eu vivo — esta é uma declaração de Yahweh Deus — não mais haverá ocasião alguma para usardes este provérbio em Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Eis que toda a vida pertence a Mim — tanto a vida do pai quanto a vida do filho, ambas pertencem a Mim! A alma que pecar, esta morrerá!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'O que pode ser dito de um homem que é reto e pratica a justiça e retidão —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'se ele não come nos montes, nem ergue os seus olhos aos ídolos da casa de Israel, e não contamina a mulher do seu próximo, muito menos se unir com uma mulher durante a menstruação, ele é um homem correto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'Que dizer do homem que a ninguém oprime, que devolve ao devedor o que foi posto como penhor num empréstimo, não rouba, mas dá a sua comida ao faminto e cobre o nu com roupas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Que dizer do homem que não cobra juros altos pelo dinheiro emprestado e não ganha lucros exagerados com o que vende? Diz-se dele que este homem pratica a justiça e estabelece fidelidade entre as pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'Se tal homem anda em Meus estatutos e guarda os Meus decretos para agir fielmente, então, a promessa para este homem reto é: Ele certamente viverá! — assim declara Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Porém, imagina que ele tenha um filho violento, que derrama sangue e pratica muitas dessas faltas aqui mencionadas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'ainda que seu pai não o tenha feito, o filho come nos montes e profana a esposa do seu próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Este homem oprime o pobre e o necessitado, extorque, rouba, não devolve o penhor, levanta seus olhos aos ídolos e comete abominações,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'empresta dinheiro com juros elevadíssimos e ganha lucro exagerado com aquilo que vende. Será que este homem deveria viver? É certo que não! Ele, certamente, morrerá e o seu sangue estará nele porque fez todas estas coisas detestáveis. Será culpado por sua própria morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Imagina que haja um homem que tenha um filho e o filho vê todos os pecados que o pai cometeu e, embora os veja, ele não os pratica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Este filho não come nos montes, não ergue seus olhos aos ídolos da casa de Israel e não profana a esposa do seu próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'Este filho não oprime a ninguém, não pega penhor, nem toma coisas roubadas; pelo contrário, dá a sua comida ao faminto e cobre de roupas o nu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Não retira do pobre a sua mão, não cobra juros que seja muito elevado, nem ganha muito lucro por um empréstimo, mas guarda os Meus decretos e anda de acordo com os Meus estatutos; este filho não morrerá pelo pecado do seu pai: certamente, viverá!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Seu pai, uma vez que oprimiu aos outros por extorsão, roubou o seu irmão e fez o que não é reto entre o seu povo — eis que ele morrerá na sua iniquidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Todavia, vós dizeis: \'Por que o filho não carrega a iniquidade do seu pai?\'. Porque o filho pratica a justiça e a retidão e guarda todos os Meus estatutos; ele os põe em prática. Ele, certamente, viverá!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Aquele que pecar é o que morrerá. Um filho não carregará a iniquidade do seu pai e o pai não carregará a iniquidade do seu filho. A retidão de quem age retamente, nele mesmo, estará; e a corrupção do mau estará nele mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Mas, se o corrupto se desviar de todos os pecados que praticou, guardar todos os Meus estatutos e praticar a justiça e a retidão, ele, certamente, viverá e não morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Todas as transgressões que ele cometeu não serão lembradas contra ele. Ele viverá pela retidão que pratica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Acaso, Eu Me regozijo na morte do corrupto — assim declara Yahweh Deus — e não em que ele se arrependa do seu mau caminho para que possa viver?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Mas, se um homem justo se desviar da sua retidão, cometer iniquidade e praticar abominações, como todas as abominações que um corrupto comete, será que ele viverá? Toda a retidão que ele tiver praticado não será lembrada quando ele Me trair em sua transgressão. Portanto, morrerá nos pecados que ele cometeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Mas vós dizeis: \'O caminho de Yahweh não é justo!\'. Ouvi, casa de Israel! Será que os Meus caminhos são injustos? Não serão os vossos caminhos que são injustos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Quando o homem justo desviar-se da sua retidão e cometer iniquidade e morrer por causa dela, então, ele morrerá na iniquidade que ele tiver praticado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Mas, se um homem perverso se desviar da injustiça que tiver praticado e praticar justiça e retidão, então, preservará a sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Porque ele viu e se desviou de todas as transgressões que fez. Ele, certamente, viverá e não morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Mas a casa de Israel diz: \'O caminho de Yahweh não é justo!\'. Por que o Meu caminho não é justo, casa de Israel? São os vossos caminhos que não são justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Portanto, julgarei a cada um dentre vós de acordo com os seus caminhos, casa de Israel — assim declara Yahweh Deus. Arrependei-vos e vos desviai de todas as vossas transgressões, para que elas não sejam pedras de tropeço contra vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Tirai de vós todas as transgressões que cometestes; e tende um novo coração e um novo espírito. Por que devíeis morrer, casa de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Porque não tenho prazer na morte de ninguém — assim declara Yahweh Deus — então, arrependei-vos e vivei!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, '\"Agora, pois, levantai uma lamentação contra os líderes de Israel');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'e dizei: \'Quem foi a vossa mãe? Uma leoa entre os leões; no meio de leõezinhos, ela criou os seus filhotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Ela criou um dos seus filhotes para que se tornasse um leão forte, um leão que aprendeu a capturar as suas presas e, depois, se tornou devorador de homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'As nações ouviram a respeito dele. Ele foi preso em uma armadilha e, com ganchos, o levaram para a terra de Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Depois, ela viu que, embora tenha esperado pelo seu retorno, suas expectativas já estavam esgotadas, por isso, tomou outro dos seus filhotes e o criou para que se tornasse um leão forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Esse jovem leão vagava entre os leões. Era um leão jovem e aprendeu a apanhar as suas presas; ele devorava homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Ele prendia as suas viúvas e arruinava as suas cidades. A terra e a sua plenitude foram abandonadas por causa do soar do seu rugido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Mas as nações vieram contra ele vindas das províncias vizinhas; espalharam seus laços sobre ele. Ele foi apanhado na sua armadilha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Com ganchos, colocaram-no numa gaiola e o levaram ao rei da Babilônia. Levaram-no às fortalezas para que a sua voz não mais fosse ouvida nos montes de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Vossa mãe era como uma videira plantada no vosso sangue à borda da água. Era frutífera e cheia de ramos por causa da abundância de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Tinha ramos fortes, que eram usados como cetros de governantes e o seu tamanho era exaltado sobre os ramos; sua altura foi vista pela grandeza da sua folhagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Mas a videira foi desarraigada com fúria e deixada terra abaixo; um vento oriental fez secar os seus frutos. Seus ramos fortes foram quebrados e se secaram; foram consumidos pelo fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Por isso, agora, está plantada no deserto, numa terra seca e sedenta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Pois o fogo saiu dos seus ramos longos e consumiu os seus frutos. Não há nenhum ramo forte nela, nenhum cetro para governar\'. Esta é a lamentação que será cantada como lamentação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Por volta do sétimo ano, no décimo dia do quinto mês, os anciãos de Israel vieram consultar Yahweh e se assentaram diante de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Então, veio a mim a palavra de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, '\"Filho do homem, declara aos anciãos de Israel, dizendo: \'Assim diz Yahweh Deus: Viestes consultar-Me? Tão certo como Eu vivo, não serei consultado por vós! — esta é a declaração de Yahweh Deus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Tu irás julgá-los? Julgarás tu, filho do homem? Que eles saibam sobre as abominações de seus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'Dize-lhes: \'Assim diz Yahweh Deus: No dia em que Eu escolhi Israel e levantei a Minha mão para jurar aos descendentes da casa de Jacó e Me fiz conhecer na terra do Egito, quando Eu ergui Minha mão e jurei para eles, Eu disse: \'Eu sou Yahweh, vosso Deus\' —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'naquele dia, levantei a Minha mão para jurar que os tiraria da terra do Egito para uma terra que Eu, cuidadosamente, havia escolhido para eles, da qual flui leite e mel; foi o mais belo ornamento entre todas as terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Eu disse a eles: \'Que cada homem tire as coisas detestáveis que seduzem os seus olhos e também os ídolos do Egito. Não vos torneis imundos. Eu sou Yahweh, o vosso Deus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Mas eles se rebelaram contra Mim e relutaram em ouvir-Me. Cada homem não jogou fora as coisas detestáveis que seduzem os seus olhos, nem abandonou os ídolos do Egito. Então, Eu decidi derramar a Minha fúria para satisfazer a Minha ira contra eles, no meio da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Agi por amor do Meu nome, para que não fosse profanado aos olhos das nações em que eles estavam. Fiz-Me conhecer a eles, aos seus olhos, tirando-os da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Então, Eu os tirei da terra do Egito e os trouxe ao deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Ali, Eu lhes dei os Meus estatutos e lhes fiz conhecer os Meus decretos, pelos quais o homem viverá, se lhes obedecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Também lhes dei os Meus sábados como um sinal entre Mim mesmo e eles, para que soubessem que Eu sou Yahweh, que os santifica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Mas a casa de Israel se rebelou contra Mim no deserto. Não andaram nos Meus estatutos. Em vez disso, rejeitaram os Meus decretos, pelos quais o homem viverá, se lhes obedecer. Eles profanaram os Meus sábados. Então, Eu disse que derramaria sobre eles a Minha fúria, no deserto, para acabar com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Eu agi por amor do Meu nome, para que não fosse profanado aos olhos das nações, diante das quais Eu os havia tirado do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Eu também levantei a Minha mão para jurar-lhes, no deserto, que não os traria para a terra que Eu ia lhes dar; uma terra de que flui leite e mel, que era o mais belo ornamento entre todas as terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Jurei isso porque rejeitaram os Meus decretos e não andaram nos Meus estatutos; profanaram os Meus sábados, já que seus corações seguiam seus ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Mas os Meus olhos se compadeceram deles por causa da sua destruição e não os aniquilei no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Eu disse a seus filhos e suas filhas no deserto: \'Não andeis conforme os estatutos de vossos pais; não guardeis os seus decretos, nem vos contamineis com seus ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Eu sou Yahweh, vosso Deus, andai nos Meus estatutos; guardai os Meus decretos e obedecei a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Guardai os Meus sábados santos, para que sejam um sinal entre Mim e vós, para que saibais que Eu sou Yahweh, o vosso Deus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Mas os seus filhos e suas filhas se rebelaram contra Mim. Não andaram nos Meus estatutos, nem guardaram os Meus decretos, segundo os quais o homem pode viver se lhes obedecer. Eles profanaram os Meus sábados. Então, Eu decidi derramar sobre eles a Minha fúria para satisfazer a Minha ira contra eles no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Mas Eu desviei a Minha mão e agi por amor do Meu nome, para que não fosse profanado aos olhos das nações que Me viram trazendo os israelitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Eu também levantei a Minha mão para eles no deserto, para jurar que os espalharia entre as nações e os dispersaria entre as terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Eu decidi fazer isso, pois eles não obedeceram aos Meus decretos, rejeitaram os Meus estatutos e profanaram os Meus sábados. Seus olhos desejavam os ídolos de seus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Então, também lhes dei estatutos que não eram bons e decretos pelos quais eles não poderiam viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'Eu os fiz impuros por suas ofertas, quando eles fizeram um sacrifício de cada primogênito no ventre e os puseram no fogo. Fiz isso para aterrorizá-los, para que eles saibam que Eu sou Yahweh!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Portanto, filho do homem, anuncia isto à casa de Israel; dize-lhes: ‘Assim diz Yahweh Deus: Vossos pais Me blasfemaram, traindo-Me. E assim o fizeram:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'quando os trouxe para a terra que Eu levantei as mãos para lhes entregar, e, quando viram todos os altos montes e as árvores frondosas, ofereceram ali os seus sacrifícios e Me provocaram com as suas ofertas. Lá eles também queimaram incenso perfumado e derramaram ofertas de bebida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Então, Eu lhes disse: \'Que lugar alto é este, para onde ireis?\'. Assim, é chamado de Bamá até hoje\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Portanto, dize à casa de Israel: ‘Assim diz Yahweh Deus: Por que vos contaminais com os caminhos de vossos pais? E por que vós agis como prostitutas, procurando por coisas repugnantes?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Pois, quando ofereceis as vossas ofertas e pondes vossos filhos no fogo, até o dia de hoje, vós vos tornais imundos com todos os vossos ídolos. Então, por que Eu deveria deixar que vós Me questioneis, casa de Israel? Assim como Eu vivo — esta é a declaração de Yahweh Deus — Eu não deixarei que vós Me questioneis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'O vosso pensamento jamais se tornará realidade. Vós dizeis: \'Sejamos como as outras nações, como os clãs das outras terras que adoram madeira e pedra\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Assim como Eu vivo — esta é a declaração de Yahweh Deus — certamente, reinarei sobre vós com mão poderosa, braço levantado e fúria que se derramará sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Eu vos tirarei dos outros povos e vos reunirei dentre os países aos quais fostes espalhados. Eu farei isto com mão poderosa e com fúria derramada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'Então, Eu vos levarei ao deserto dos povos e, ali, vos julgarei face a face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Assim como julguei vossos pais no deserto da terra do Egito, assim também Eu vos julgarei — esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Eu farei com que passeis debaixo da Minha vara e Eu vos farei obedecer às exigências da aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Purificarei dentre vós os rebeldes e os que se revoltam contra Mim. Eu os tirarei para a terra em que permanecerão como estrangeiros, mas eles não entrarão na terra de Israel. Então, sabereis que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Assim, a vós, casa de Israel, diz Yahweh Deus: Cada um de vós deve ir para os seus próprios ídolos. Adorai-os, se vos recusardes a ouvir a Mim, mas vós não deveis mais profanar o Meu santo nome com vossas ofertas e vossos ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Pois, no Meu santo monte, no pico da montanha de Israel — esta é a declaração de Yahweh Deus —, toda a casa de Israel Me adorará. Eu estarei satisfeito em requerer as vossas ofertas e também os primeiros frutos do vosso tributo, com todas as vossas coisas santas, naquele lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Eu vos aceitarei como incenso perfumado, quando Eu vos tirar dos povos e vos ajuntar fora dos países onde fostes espalhados. Eu Me mostrarei santo entre vós para que as nações vejam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Então, quando Eu vos trouxer à terra de Israel, à terra que levantei a Minha mão para dar a vossos pais, vós sabereis que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Ali, vos lembrareis dos vossos maus caminhos e todas as vossas obras pelas quais vos tornastes imundos e vos odiareis aos vossos próprios olhos por todas as más ações que haveis cometido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Pois sabereis que Eu sou Yahweh quando vos faço isto por amor do Meu nome, não por vossos maus caminhos, nem por vossas ações corruptas, casa de Israel — esta é a declaração de Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, '\"Filho do homem, volta o teu rosto para as terras do sul e fala contra o sul; profetiza contra a floresta do Neguebe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'Diz à floresta do Neguebe: \'Esta é a declaração de Yahweh — assim diz Yahweh Deus: Eis que porei fogo entre vós. Consumirá toda árvore fresca e toda árvore seca entre vós. A chama de fogo não se apagará e toda a face do sul e do norte será queimada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'Então, toda a carne verá que eu sou Yahweh, quando Eu acender o fogo e ele não se apagar\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'Então, eu disse: \"Ah! Yahweh Deus, eles estão dizendo de mim: \'Não é um mero narrador de parábolas?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, '\"Filho do homem, vira o teu rosto contra Jerusalém e fala contra os santuários; profetiza contra a terra de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Diz à terra de Israel: \'Assim diz Yahweh: Eis que estou contra vós! Tirarei a Minha espada da bainha e eliminarei de ti tanto o homem justo quanto o homem ímpio!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Para que Eu elimine de ti tanto o homem justo quanto o homem corrupto, a Minha espada sairá da bainha contra toda a carne desde o sul até ao norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Então, toda a carne saberá que Eu, Yahweh, tirei a Minha espada da bainha. Ela não mais recuará!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'E tu, filho do homem, suspira até que os teus lombos se quebrem!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'E, depois, eles te perguntarão: \'Por que razão estás suspirando?\'. E tu lhes dirás: \'Por causa da notícia que está vindo, pois todo o coração desmaiará e toda a mão esmorecerá! Todo o espírito desmairá e todo o joelho se desfará em águas. Eis que está vindo e será assim! — declara Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Depois, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, '\"Filho do homem, profetiza e diz: \'Assim diz Yahweh: Diz: Uma espada! Uma espada! A espada será afiada e polida!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'A espada será afiada para que faça uma grande chacina! Será polida para que seja como relâmpago! Deveríamos nos regozijar no cetro do Meu filho? A espada que vem odeia todo o madeiro como tal!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Assim, a espada será dada para que seja polida, para depois ser agarrada pela mão! A espada é afiada, é polida e é dada à mão daquele que mata!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Pede ajuda e lamenta, filho do homem! Pois aquela espada veio contra o Meu povo! Ela está contra todos os líderes de Israel. Eles são lançados contra a espada juntamente com o povo. Portanto, bate na tua coxa!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Porque há uma prova, mas, e se o cetro não perdurar? — esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Tu, porém, filho do homem, profetiza e bate as tuas mãos juntas, porque a espada atacará mesmo pela terceira vez! Uma espada para os que serão abatidos! É uma espada para que muitos sejam massacrados, atravessando-os por todo o lado!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Para que derretam os seus corações e se multiplique a sua queda, enviei a chacina da espada contra as suas portas! Ai! É feito como relâmpago, libera para o matadouro!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Tu, espada! Vira-te à direita! Vira-te à esquerda! Vai aonde quer que o teu rosto vire.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Pois também baterei as Minhas mãos e trarei descanso à Minha fúria! Eu, Yahweh, declaro isto!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'A palavra de Yahweh veio a mim, mais uma vez, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, '\"Agora tu, filho do homem, designa duas estradas à espada para o rei da Babilônia, que está a caminho. As duas estradas começarão na mesma terra e um marco indicará a uma delas como a que leva à cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Marca uma estrada ao exército da Babilônia para que venha a Rabá, a cidade dos amonitas. Marca a outra para que leve ao exército de Judá e à cidade de Jerusalém, que está fortificada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Pois o rei da Babilônia parará numa encruzilhada, no cimo dos dois caminhos, para fazer adivinhação. Ele mexerá algumas flechas, consultará alguns ídolos e examinará as entranhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Na sua mão direita, será como uma adivinhação sobre Jerusalém, para bater com aríetes contra ela, para abrir a sua mão e ordenar a chacina, para soar um grito de guerra e para erguer os aríetes contra as portas, para edificar uma rampa e para erguer torres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Parecerá uma adivinhação inútil aos olhos dos que estão em Jerusalém, os que juraram em blasfêmia aos da Babilônia! Porém, ele se lembrará da iniquidade, para que sejam apanhados!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Portanto, assim diz Yahweh Deus: Porque trazeis a vossa iniquidade à Minha memória, as vossas transgressões serão reveladas! Vossos pecados serão vistos em todas as vossas ações! Por esta razão, lembrareis a todos que sereis capturados pela mão do vosso inimigo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'E vós, profanos e ímpios governantes de Israel, cujo dia de castigo chegou e cujo tempo de cometer iniquidade terminou,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Yahweh Deus vos diz: Removei o turbante e tirai a coroa! As coisas não serão do mesmo jeito! Exaltai os humildes e humilhai os exaltados!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Uma ruína! Uma ruína! Farei uma ruína! Ela não será restaurada até que venha aquele designado para executar o juízo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Assim, tu, filho do homem, profetiza e dize: \'Assim diz Yahweh Deus ao povo de Amom em relação à desgraça que lhes sobrevirá: \'Uma espada, uma espada é desembainhada! É afiada para a chacina para que devore e será como relâmpago!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Enquanto profetas veem visões ocas para vós, enquanto fazem rituais para vos trazerem mentiras, esta espada estará nos pescoços dos ímpios que estão para serem mortos, cujo dia do castigo veio e cujo tempo da iniquidade está para terminar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Devolvei a espada à sua bainha. Ao lugar da vossa criação, à terra da vossa origem, Eu vos julgarei!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'Derramarei a Minha indignação sobre vós! Lançarei o fogo da Minha ira contra vós e Eu vos entregarei na mão de homens cruéis, gênios da destruição!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Vós vos tornareis combustível para o fogo! O vosso sangue estará no meio da terra. Não sereis lembrados, pois Eu, Yahweh, declarei isto!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, '\"Agora, filho do homem, irás tu julgar? Julgarás tu a cidade de sangue? Faze-lhe conhecer todas as suas abominações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Tu deves dizer: \'Assim diz Yahweh Deus: Esta é uma cidade que derrama sangue no meio de si mesma, para que venha o seu tempo; é uma cidade que faz ídolos, para tornar-se impura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'És culpada pelo sangue que derramaste e te tornaste impura pelos ídolos que fizeste. Pois fizeste chegar o teu dia e aproximaste o fim dos teus anos. Por isso, Eu te tornarei vergonha para as nações e zombaria à vista de toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Ambos os que estão perto como aqueles que estão longe, zombarão de ti, tu, cidade imunda, com a reputação conhecida em todos os lugares como sendo cheia de confusão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Vê! Os príncipes de Israel, cada um, pelo seu próprio poder, vieram a ti para derramar sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Eles desonraram pais e mães dentro de ti e oprimiram os estrangeiros em seu meio. Eles maltrataram os órfãos e as viúvas dentro de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Desprezaste as Minhas coisas santas e profanaste os Meus sábados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Homens caluniosos vieram ao meio de ti para derramar sangue e eles comem nos montes. Eles praticam maldade no meio de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'A nudez de um pai é revelada em ti. Eles abusaram da mulher impura no meio de ti durante a impureza dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Homens que cometem abominações com as esposas dos seus próximos e homens que tornam vergonhosamente impuras suas próprias noras; homens que abusam das suas próprias irmãs — filhas dos seus próprios pais — todos estes estão entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Estes homens aceitam subornos entre vós para derramar sangue. Ganhastes e obtivestes lucro exagerado, danificastes vosso próximo por meio da opressão e vos esquecestes de Mim — declara Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Vê! Com a Minha mão, Eu ataquei o ganho desonesto que tu fizeste e o derramamento de sangue que está em teu meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Teu coração ficará de pé? Tuas mãos serão fortes nos dias em que Eu mesmo lidarei contigo? Eu, Yahweh, estou declarando isto e Eu vou fazer isto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Assim, te espalharei entre as nações e te dispersarei pelas terras. Desta maneira, Eu purificarei a tua imundície.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Assim, tu te tornarás imunda aos olhos da nação. Então, tu saberás que Eu sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Depois, veio a mim a palavra de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, '\"Filho do homem, a casa de Israel tornou-se escória para Mim. Todos eles são os restos de bronze e estanho; ferro e chumbo no meio de ti. Serão como a escória de prata na tua fornalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Por isso, assim declara Yahweh Deus: \'Pois todos vós vos tornastes como escória. Eis que estou prestes a vos reunir no centro de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Assim como uma coleção de prata, bronze, ferro, chumbo e estanho no meio do forno deve ter fogo soprado contra ela, Eu vou vos derreter. Assim, Eu vos reunirei em Minha ira e fúria. Irei vos colocar lá e soprar o fogo para derretê-la, por isso, irei vos reunir na Minha raiva e na minha ira; lá, Eu vos lançarei fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Assim, Eu vos reunirei e soprarei com o fogo da Minha ira, de modo que sereis derramados no meio dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Como prata fundida no meio de uma fornalha, eis que vos derretereis no meio dela e sabereis que Eu, Yahweh, derramei a Minha fúria contra vós!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Veio a mim a palavra de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, '\"Filho do homem, dize-lhe: \'És uma terra que não foi purificada. Não há chuva no dia da ira!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Há uma conspiração de seus profetas no meio dela, como um leão rugindo rasgando uma vítima. Eles consomem vidas e tomam riquezas preciosas; fazem muitas viúvas dentro dela!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Os seus sacerdotes violam a Minha lei e profanam as Minhas coisas santas. Eles não distinguem entre coisas santas e coisas profanas e não ensinam a diferença entre o imundo e o puro. Eles escondem os seus olhos dos Meus sábados para que Eu seja profanado em seu meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Seus príncipes dentro dela são como lobos que rasgam suas vítimas. Eles derramam sangue e destroem a vida, para fazer lucro desonestamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Os seus profetas nos pintaram com cal; eles veem falsas visões e predizem mentiras para eles. Dizem: \'Declara Yahweh Deus\' sendo que Yahweh não falou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Então, as pessoas da terra oprimiram pela extorsão e arracam por meio de roubo e maltratam o pobre e o necessitado; oprimem o estrangeiro sem justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Assim, procurei por um homem entre eles que construísse uma parede e que estaria diante de Mim em sua brecha para a terra, para que Eu não a destruísse, mas a ninguém encontrei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Então, derramarei sobre eles a Minha indignação. Eu os exterminarei com o fogo do Meu furor e fiz que o seu caminho recaísse à sua própria cabeça — declara Yahweh Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, '\"Filho do homem, havia duas mulheres, filhas da mesma mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Agiram como prostitutas no Egito durante a sua juventude. Lá, agiram como prostitutas. Os seus seios foram espremidos e seus mamilos virgens foram acariciados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Seus nomes eram Oolá— a irmã mais velha — e Oolibá — sua irmã mais nova. Então, elas se tornaram Minhas e deram à luz filhos e filhas. Seus nomes significam: Oolá significa Samaria e Oolibá significa Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Mas Oolá agiu como uma prostituta mesmo sendo Minha; ela cobiçou seus amantes, os assírios que a dominavam,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'o governador que vestia violeta, e os seus príncipes, que eram fortes e formosos, todos eles homens andando a cavalos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Então, ela se entregou a eles como uma prostituta, a todos os melhores dos homens assírios e se tornou imunda com todo mundo que ela cobiçou — com todos seus ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Pois ela não tinha deixado o seu comportamento de prostituta no Egito, quando quiseram dormir com ela quando era uma menina, quando começaram a acariciar seus seios virgens, quando começaram a derramar seu comportamento promíscuo sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Portanto, a entreguei na mão dos seus amantes, nas mãos dos assírios aos quais ela cobiçou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Eles a despiram. Tomaram seus filhos e suas filhas e a mataram à espada; ela se tornou vergonhosa para outras mulheres, então, eles passaram o julgamento sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Sua irmã Oolibá viu isso, mas ela cobiçou ainda mais apaixonadamente e agiu como uma prostituta ainda mais que sua irmã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Ela cobiçou os assírios, os governantes e os príncipes dominantes, os quais se vestiam impressionantemente, eram homens montando cavalos. Todos eram fortes, homens formosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Vi que ela se tornou imunda. Foi o mesmo para as duas irmãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Então, ela aumentou a sua prostituição ainda mais. Ela viu homens esculpidos nos muros, imagens dos caldeus pintados de vermelho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'usando cintos em torno de sua cintura, com turbantes compridos nas suas cabeças. Todos tinham aparência de príncipes de carruagem, à semelhança dos filhos da Babilônia, naturais da Caldeia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'Assim que os viu, ela os cobiçou e enviou mensageiros para eles na Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Então, os babilônios vieram a ela e para sua cama de cobiça e a tornaram imunda com a sua promiscuidade. Pelo que ela havia feito, ela se tornou imunda, então, ela se virou para longe deles em desgosto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Ela exibiu seus atos de prostituição e mostrou o seu corpo nu, então, Eu me afastei dela, assim como Minha alma se afastou de sua irmã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Então, ela cometeu muito mais atos da prostituição, enquanto trazia à mente e imitava os dias da sua juventude, quando se comportou como uma prostituta na terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Então, ela cobiçou os seus amantes, cujas partes íntimas eram como as dos jumentos e cujas emissões reprodutivas eram como as dos cavalos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'É assim que cometeste atos vergonhosos de tua juventude, quando os egípcios acariciaram teus mamilos e apertaram teus seios jovens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Portanto, à Oolibá, assim diz Yahweh Deus: \'Eis que colocarei teus amantes contra ti. Aqueles de quem tu te afastaste trarei contra ti de todos os lados:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'os babilônios, os caldeus de Pecode, Soá, Coa e todos os assírios com eles, homens fortes e formosos, governantes e comandantes, todos os príncipes e homens de reputação, todos eles montando a cavalos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Virão contra ti armados em carruagens, vagões, e com grande multidão de pessoas. Eles irão armar grandes escudos, pequenos escudos e capacetes contra ti por toda parte. Eu lhes darei oportunidade de te punir e eles te punirão com suas ações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Colocarei a Minha ira zelosa sobre ti e eles lidarão contigo em fúria. Eles cortão teus narizes, tuas orelhas e os teus sobreviventes cairão pela espada. Tomarão de ti teus filhos e tuas filhas, teus sobreviventes serão devorados pelo fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Eles tirarão suas roupas e todas as suas jóias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Então, removerei de ti teu comportamento vergonhoso e teus atos de prostituição da terra do Egito. Não erguerás teus olhos para eles com saudade, e não mais pensarás no Egito\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Pois assim declara Yahweh Deus: \'Eis que te entregarei à mão daqueles que tu odeias, de volta à mão daqueles de quem tinhas te afastado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Eles lidarão contigo com ódio; tomarão todas as tuas posses e te abandonarão despida e nua. A vergonha da nudez e da tua prostituição será revelada, seu comportamento vergonhoso e tua promiscuidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Estas coisas serão feitas na tua ação como prostituta, cobiçando as nações pelas quais te tornaste imunda com os seus ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Andaste no caminho da tua irmã, por isso, entregarei o cálice de punição dela na tua mão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Assim declara Yahweh Deus: \'Beberás o cálice da tua irmã que é profundo e grande. Tu te tornarás motivo de riso e assunto para deboche — neste copo, cabe muita coisa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Serás cheia de embriaguez e tristeza, do cálice de horror e devastação; do cálice da tua irmã Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Beberás e o deixarás vazio; então, irás quebrá-lo e rasgarás teus seios com os cacos. Pois Eu declarei isto — assim declara Yahweh Deus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Portanto, assim declara Yahweh Deus: \'Porque tu te esqueceste de Mim e me lançaste atrás, nas tuas costas; então, também suportarás as consequências de teu comportamento vergonhoso e de teus atos de imoralidade sexual\"\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Yahweh me disse: \"Filho do homem, julgarás Oolá e Oolibá? Então, apresenta a elas as suas ações abomináveis,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'já que cometeram adultério e há sangue nas suas mãos. Cometeram adultério com seus ídolos e até colocaram seus filhos no fogo, como comida para seus ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Então, elas continuam fazendo isto Comigo: Tornaram o Meu santuário imundo e, no mesmo dia, profanaram os Meus sábados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Pois, quando degolaram suas crianças para seus ídolos, no mesmo dia, vieram ao Meu santuário para profaná-lo! Então, eis que é isto que fizeram no seio da Minha casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Enviaste homens que vieram de muito longe, a quem os mensageiros tinham sido enviados, agora, eis que eles realmente vieram, aqueles para quem banhaste, pintaste os teus olhos e te adornaste com jóias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Sentaste numa cama bonita e numa mesa arranjada diante deles, onde tu colocaste o Meu incenso e o Meu óleo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Assim, o som de uma multidão barulhenta estava ao seu redor; incluindo todo tipo de homens, até beberrões foram trazidos do deserto com homens de classe baixa e puseram nos teus braços braceletes e coroas bonitas nas tuas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Então, eu disse àquela que fora desgastada por adultério: \'Agora com ela serão sexualmente imorais, e ela com eles\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Eles chegaram e dormiram com ela, como homens fazem com uma prostituta. Dessa forma, dormiram com Oolá e Oolibá, que eram mulheres imorais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Mas homens justos julgarão e as punirão como adúlteras e as castigarão com a sentença para os que derramaram sangue, porque são adúlteras e o sangue está em suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Então, assim declara Yahweh Deus: Levantarei uma multidão contra elas e as entregarei para serem aterrorizadas e saqueadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Então, aquela multidão as apedrejará com pedras e com suas espadas as cortará. Eles matarão seus filhos e suas filhas, também queimarão as suas casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Então, removerei o comportamento vergonhoso da terra e disciplinarei todas as mulheres para que não mais ajam como prostitutas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Então, colocarão o teu comportamento vergonhoso contra ti. Suportareis a culpa de teus pecados com teus ídolos e, assim, sabereis que Eu sou Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'A palavra de Yahweh veio a mim no nono ano, no décimo mês e ao décimo dia do mês, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, '\"Filho do homem, registra a data de hoje, porque exatamente neste dia o rei da Babilônia sitiou Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Fala uma parábola contra esta casa rebelde. Dize-lhe: \'Assim declara Yahweh Deus: \'Põe uma panela no fogo e coloca água nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'põe pedaços de carne nela, todos os bons pedaços, as pernas e as espáduas; enche-a com os melhores ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Toma o melhor do rebanho e ajunta um monte de lenha debaixo da panela de ossos, ferve bem a carne e cozinha os ossos nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Portanto, assim declara Yahweh Deus: Ai da cidade sanguinária, da panela, que está enferrujada por dentro e cuja ferrugem não vai sair dela. Tira a carne dela pedaço a pedaço, mas não lança sorte sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Pois o seu sangue está no meio dela. Ela o derramou sobre uma rocha nua; não a derramou na terra para tapá-la com poeira,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'para aumentar a Minha ira e Me vingar. Derramei o seu sangue na rocha nua para que não fosse coberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Portanto, assim declara Yahweh Deus: Ai da cidade sanguinária. Eu também aumentarei a fogueira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Amontoa a lenha e acende o fogo. Cozinha bem a carne e mistura com especearias; deixa que os ossos se queimem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Depois, coloca a panela vazia sobre as brasas, para que aqueça e arda o seu bronze, para que a sua imundície seja derretida e a sua ferrugem consumida\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Ela se tornou exausta pelo trabalho, pois sua espessa ferrugem não saiu mesmo com fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Teu comportamento vergonhoso está na tua imundície, porque quis purificarte, mas ainda não te tornaste pura. Tu ainda não estarás livre da tua imundície até que a Minha ira se retire de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Eu, Yahweh, declarei isso e assim farei. Não voltarei atrás, nem Me arrependerei. Assim como foram os teus caminhos e as tuas práticas, eles te julgarão! — assim declara Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, '\"Filho do homem! Eis que estou tirando o desejo dos teus olhos com um golpe, mas não deves lamentar nem chorar e não se derramem as tuas lágrimas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Deve gemer silenciosamente. Não faças uma lamentação pelos mortos. Amarra o teu turbante em ti e calça as tuas sandálias nos teus pés, mas não cubras os cabelos do teu rosto com véu e não comas do pão dos homens que choram por terem perdido as suas esposas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Então, falei ao povo pela manhã e a minha esposa morreu à noite. E, na manhã seguinte, fiz o que me havia sido ordenado fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'O povo me perguntou: \"Não dirás a nós o que isto significa, estas coisas que estás fazendo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Eu lhes disse: \"A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, '\'Dize à casa de Israel, assim declara Yahweh Deus: Eis que profanarei o Meu santuário — o orgulho do vosso poder, o deleite dos vossos olhos e o anelo da vossa alma; e os vossos filhos e as vossas filhas a quem deixastes para trás, cairão pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Fareis exatamente como eu fiz: não cobrireis os cabelos do vosso rosto com véu, nem comereis do pão dos homens que lamentam!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'Em vez disso, vossos turbantes estarão em vossas cabeças e as vossas sandálias nos vossos pés; não lamentareis, nem chorareis, pois definhareis nas vossas iniquidades e cada homem gemerá pelo seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Assim, Ezequiel vos será um sinal, uma vez que tudo que ele fez, fareis também vós quando isto vier. Então, sabereis que Eu sou Yahweh Deus!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, '\"Tu, porém, filho do homem, no dia em que Eu lhes tirar o seu templo, que é a sua alegria, o seu orgulho, e o prazer de seus olhos, e o desejo do seu coração — e, quando Eu lhes tirar seus filhos e suas filhas —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'naquele dia, um sobrevivente virá a vós para vos dar as notícias!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'Naquele dia, a vossa boca se abrirá para com aquele sobrevivente e falarás — não mais estareis em silêncio. Sereis um sinal para eles para que saibam que Eu sou Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, '\"Filho do homem, vira teu rosto contra o povo de Amom e profetiza contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Dize ao povo de Amom: \'Amonitas, ouvi a palavra de Yahweh Deus. Isto é o que Yahweh Deus diz: Porque dissestes, \'Bem feito!\' contra o Meu santuário, quando foi profanado, contra a terra de Israel quando foi desolada e contra a casa de Judá quando foi ao exílio;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'por isso, entregar-vos-ei como propriedade ao povo do oriente. Eles se estabelecerão em vossos acampamentos, morarão no meio de vós, comerão vossos frutos e beberão vosso leite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Farei de Rabá pasto para camelos e, dos amonitas, campos para rebanhos. Então, sabereis que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Assim declara Yahweh Deus: Tu bateste palmas, sapateaste os teus pés e alegraste de contentamento no teu íntimo contra a terra de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Por isso, eis que te derrubarei com Minha mão, Eu te darei por despojo às nações. Cortarei a ti dentre os povos e te farei perecer em meio dos países. Destruirei a ti e tu saberás que sou Yahweh\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Assim declara Yahweh Deus: \'Porque Moabe e Seir dizem: \'Eis que a casa de Judá é como qualquer outra nação\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Por isso, eis que abrirei a encosta de Moabe, começando nas fonteiras de suas cidades, desde a glória da terra de Bete-Jesimote, Baal-Meom e Quiriataim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Ao povo do oriente que estava contra o povo de Amom, Eu vos darei como propriedade, de modo que os amonitas não serão lembrados entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Então, Eu executarei juízos contra Moabe e saberão que Eu Sou Yahweh\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Assim declara Yahweh Deus: \'Edom se vingou da casa de Judá e cometeu erro fazendo isto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Por isso, assim declara Yahweh Deus: Destruirei Edom com Minha mão e destruirei todas pessoas e animais de lá. Farei deles uma ruína, lugar abandonado, desde Temã até Dedã cairão pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Exercerei a Minha vingança em Edom, pela mão do Meu povo Israel e eles farão com Edom de acordo com Minha ira e fúria; conhecerão a Minha vingança — assim declara Yahweh Deus\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Assim declara Yahweh Deus: \'Os filisteus tomaram vingança com despeito e, em seu íntimo, tentaram destruir Judá de novo e de novo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Então, isto é o que diz Yahweh Deus: Eis que estenderei a Minha mão contra os filisteus, eliminarei os quereteus e destruirei todo o restante deles que está no litoral.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Porque tomarei grande vingança contra eles com fúria de destruição. Então, saberão que Eu Sou Yahweh, quando Me vingar deles\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'No décimo primeiro ano, no primeiro dia do mês, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, '\"Filho do homem, visto que Tiro falou contra Jerusalém: \'Ah! A porta do povo está destruída! Ela está destruída. Eu vou me enriquecer porque ela está arruinada\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Por isso, assim declara Yahweh Deus: \'Eu estou contra ti, Tiro, e levantarei contra ti muitas nações, como se levanta uma tempestade no mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Eles destruirão os muros de Tiro, derrubarão as suas torres. Eu varrerei o seu pó e farei dela uma rocha nua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Ela será um enxugadouro de redes no meio do mar, pois assim declarei — assim declara Yahweh Deus — e ela servirá de despojo para as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Suas filhas que estão nos campos serão mortas com a espada e elas saberão que Eu sou Yahweh\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Pois assim diz Yahweh: Eis que, do norte, trago Nabucodonosor, rei da Babilônia, rei dos reis, contra Tiro; com cavalos, carros, cavaleiros e grande multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Ele matará tuas filhas nos campos, cercará tua cidade, construirá uma rampa contra teus muros e levantará escudos contra ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Ele porá os seus aríetes contra os teus murros e, com seus instrumentos, destruirá as tuas torres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Seus cavalos serão muitos, de modo que o pó deles te cobrirá. Os teus muros serão abalados pelo estrondo dos cavaleiros, das carruagenss e dos carros. Quando ele entrar nos teus portões, entrará como um homem que entra numa cidade com muros derrubados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Com os cascos de seus cavalos, pisará todas as tuas ruas. Ele matará teu povo à espada e as tuas colunas fortes cairão por terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Eles saquearão todas as tuas riquezas e mercadorias; destruirão todos os teus muros e tuas casas luxuosas. Tuas pedras, tua madeira e teu cascalho serão lançados nas águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Eu silenciarei o ruído das tuas músicas, de modo que a tua harpa não será ouvida mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Farei de ti uma rocha nua e tu te tornarás como um enxugadouro de redes. Não serás construída novamente, porque Eu, Yahweh Deus, falei — assim declara Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Assim declara Yahweh Deus para Tiro: \'Não estremecerão as ilhas com o estrondo da tua destruição e com os lamentos dos feridos quando a grande destruição estiver no vosso meio?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Então, todos os príncipes do mar descerão dos seus tronos, tirarão os seus mantos e despirão suas vestes bordadas. Eles se vestirão com roupas de tremor, assentar-se-ão no chão, estremecerão sem parar e ficarão apavorados por vossa causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Eles levantarão um lamento contra ti e dirão: Como tu, que eras povoada por mercadores, foste destruída. A famosa cidade, que era muito poderosa — desapareceu do mar. Teus moradores espalharam um terror sobre si mesmos e sobre todos que moravam perto deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Agora, o litoral estremece no dia da tua queda. As ilhas no mar estão aterrorizadas, porque tu morreste\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Porque, assim declara Yahweh Deus: Quando Eu fizer de ti uma cidade isolada, como outras cidades desabitadas, quando levantar os abismos contra ti e, quando as vastas águas te cobrirem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'então, Eu te abaterei como o povo antigo, como aqueles já lançados na cova, porque te farei habitar nas mais baixas partes da terra como as ruínas dos tempos antigos. Por causa disso, tu não retornarás nem retomarás teu lugar na terra dos vivos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Eu colocarei sobre ti o desastre e já não mais serás. Então, serás procurada, mas não serás achada nunca mais — assim declara Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Novamente veio a palavra de Yahweh a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, '\"Filho do homem, começa uma lamentação sobre Tiro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'e dize a Tiro, aquele que vive na entrada do mar, que negocia com povos de muitas ilhas, assim te diz Yahweh Deus: Tiro, tu dizes: \'Sou perfeita em formosura\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Tuas fronteiras estão no coração dos mares; os que te construíram aperfeiçoaram a tua beleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Fizeram todas as tuas tábuas com cipreste do monte Hermon; buscaram cedro do Líbano para fazer um mastro para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Os teus remos eram feitos com os carvalhos de Basã; os teus bancos de madeira de cipreste do Chipre, e eram cobertos com marfim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Tuas velas eram de linho colorido vindas do Egito, que serviam como tua bandeira; de azul e púrpura das ilhas do Egito eram os teus toldos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Aqueles que vivem em Sidom e Arvade eram teus remadores; os peritos de Tiro, que estavam no meio de ti, eram teus pilotos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Os artesãos experientes de Gebal eram os calafetadores de tuas fendas; e seus marinheiros no teu meio negociavam por ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Persas, lídios e os da Líbia eram parte de teu exército, teus homens de guerra. Eles penduraram seus escudos e capacetes junto com os teus, aumentando teu esplendor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Os homens de Arvade e Heleque, no teu exército, estavam sobre os teus muros ao teu redor, e os gamaditas nas tuas torres. Eles penduravam seus escudos nos teus muros, à tua volta, completando a tua beleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Társis era teu parceiro de comércio, por causa da tua abundante riqueza em mercadoria: prata, ferro, estanho e chumbo. Eles compravam e vendiam as tuas mercadorias!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javã, Tubal e Meseque comercializavam escravos e artigos feitos de bronze. Eles negociavam tuas mercadorias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Togarma negociava cavalos, garanhões e mulas pelas tuas mercadorias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Os homens de Rodes eram teus mercadores e muitas ilhas teus fregueses. Eles traziam, em retorno, chifres de marfim e ébano como tributo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'A Síria negociava muitos de teus produtos e eles trocavam por esmeraldas, púrpura, tecidos coloridos, panos finos, pérolas e rubis, como mercadoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Judá e a terra de Israel trocavam mercadorias contigo. Davam em troca: trigo de Minite, bolos, mel, óleo e bálsamo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damasco comercializava todos teus produtos, por causa de tua grande riqueza e davam em troca vinho de Helbom e lã do Zahar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Dã e Javã de Uzal trocavam mercadorias de ferro trabalhado, canela e cálamo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedã era teu negociador de cobertores de sela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'A Arábia e todos os chefes de Quedar eram mercadores contigo e negociavam cordeiros, carneiros e bodes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Os comerciantes de Sebá e Raamá vinham vender as melhores especiarias e todo tipo de jóias preciosas; negociavam ouro pelas tuas mercadorias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Harã, Cané e Éden negociavam contigo, junto com Sebá, Assur e Quilmade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Estes eram teus mercadores em mantos finos, em tecidos violeta feitos à mão, cobertores coloridos, bordados e tapetes feitos de cordões trançados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Os navios de Társis transportavam as mercadorias! Tu estavas cheia, com carga pesada no coração dos mares!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Os teus remadores te conduziram até grandes mares; e o vento oriental te quebrou no meio deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Tuas riquezas, mercadorias e teu comércio; teus marinheiros, pilotos e fazedores de navios; teus fregueses e todos os homens de guerra contigo; toda a tua equipe de navio — eles afundarão até as profundezas do mar, no dia da tua destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'As cidades dos mares tremerão ao som dos gritos de teus pilotos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'todos teus remadores descerão dos navios; marinheiros e todos os pilotos no mar ficarão em terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'Então, eles te farão ouvir as suas vozes e irão prantear amargamente; lançarão o pó sobre as suas cabeças e se revolverão nas cinzas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Eles raparão suas cabeças por ti; eles se amarrarão com pano de saco, chorarão amargamente por ti e gritarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Eles se lamentarão por ti e cantarão seu luto, dizendo: quem é como Tiro, que foi reduzido ao silêncio no meio do mar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Quando as tuas mercadorias chegavam nos portos, satisfaziam a muitos povos; pois enriquecia os reis da terra com tuas riquezas e mercadorias!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Mas, quando foste quebrantada pelos mares, pelas águas profundas, tua mercadoria e toda a tua equipe afundaram!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Todos os habitantes da costa ficaram chocados por tua causa e os reis estremeceram horrorizados! Seus rostos tremiam!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Os comerciantes dos povos zombam de ti; pois te tornaste um horror e deixarás de existir para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'E veio a mim a palavra de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, '\"Filho do homem, dize ao rei de Tiro, \'assim declara Yahweh Deus: O teu coração é arrogante, pois disseste: \'Eu sou deus! Eu me assentarei no trono dos deuses no meio dos mares!\'. Mesmo sendo homem e não deus, em teu coração, consideras a ti como deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Tu pensas que és mais sábio que Daniel e que não há mistério algum que te supreenda!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Enriqueceste com sabedoria e habilidade, adquiriste ouro e prata nos teus tesouros!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Pela grande sabedoria e por teu comércio, multiplicaste as tuas riquezas, por isso o teu coração é arrogante por causa da tua riqueza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Portanto, assim declara Yahweh Deus: porque igualaste o teu coração a de um deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'trarei estrangeiros contra ti, homens terríveis dentre outras nações. Eles trarão as suas espadas contra a beleza da tua sabedoria e zombarão do teu esplendor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Eles te farão cair na cova e morrerás como aqueles que morrem no coração do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Verdadeiramente, dirás: \'Eu sou um deus\' para aqueles que te matam? Tu és homem e não Deus e estarás nas mãos daquele que te perfura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Morrerás como um incircunciso pelas mãos dos estranhos — pois Eu assim declaro — assim declara Yahweh Deus”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Mais uma vez, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, '“Filho do homem, levanta uma lamentação sobre o rei de Tiro e dize para ele: \'Assim declara Yahweh Deus: Tu eras o modelo da perfeição, cheio de sabedoria e perfeito em formosura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Estavas no Éden, o jardim de Deus. Toda pedra preciosa te cobria: rubi, topázio, esmeralda, crisólito, ônix, jaspe, safira, turquesa e berilo. Suas guarnições e montagens eram feitas de ouro e foram preparados no dia em que foste criado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Eu te coloquei no monte santo de Deus como querubim ungido para guardar a humanidade. Estavas no meio de pedras brilhantes e nelas andavas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Eras íntegro em teus caminhos, desde o dia em que foste criado até que se achou injustiça em ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Por meio da grandeza do teu comércio, tu te encheste de violência e pecaste. Portanto, Eu te expulsei do monte de Deus, como um que se contaminou e te destruí, querubim da guarda, e te expulsei do meio das pedras brilhantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Teu coração foi arrogante por causa da tua formosura; arruinaste a tua sabedoria por causa do teu esplendor. Eu te lancei por terra. Eu te coloquei diante dos reis para que possam te ver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Por causa dos teus muitos pecados e desonestidade no comércio, profanaste os teus santuários. Por causa disso, fiz sair fogo de ti; que te consumirá. Eu te tornarei cinza na terra à vista de todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Todos os que te conhecem se espantarão; ficarão chocados e tu não mais existirás\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Então, veio a mim a palavra de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, '“Filho do homem, profetiza contra Sidom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'Dize-lhe: \'assim declara Yahweh Deus: Eis que Eu sou contra ti, Sidom! Para que Eu seja glorificado no meio de ti e teu povo saiba que Eu sou Yahweh, quando executar justiça e demonstrar a Minha santidade no meio de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Enviarei sobre ti uma praga, sangue em tuas ruas e os mortos cairão no meio de ti. Quando a espada vier contra ti por todos os lados, saberás que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Então, não haverá mais espinhos pontiagudos e abrolhos que causem dor à casa de Israel entre os povos que a rodeiam e a desprezam; e saberão que Eu sou Yahweh Deus!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Assim declara Yahweh Deus: \'Quando Eu juntar a casa de Israel dentre os povos nos quais foram espalhados e, quando Me santificar no meio deles, diante das nações, eles edificarão as suas casas na terra que darei ao Meu servo Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Então, habitarão seguros nela e edificarão casas, plantarão vinhas e viverão seguros quando Eu executar a justiça em todos aqueles ao seu redor que a desprezaram; e eles saberão que Eu sou Yahweh, o seu Deus!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'No décimo ano, no décimo mês, no dia doze, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, '\"Filho do homem, dirige o teu rosto contra Faraó, o rei do Egito; profetiza contra ele e contra todo o Egito,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'dizendo: \'assim declara Yahweh Deus: Vê, estou contra ti, Faraó, rei do Egito. Tu, grande monstro, que vives no meio do rio, que dizes: \'o meu rio é somente para mim, eu o fiz para mim mesmo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Mas Eu colocarei anzóis no teu queixo e o peixe do teu Nilo pegará nas tuas escamas; Eu te tirarei do meio do teu rio, juntamente com todos os peixes que pegaram nas tuas escamas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Eu te lançarei para um lugar selvagem, tu e todos os peixes do teu rio. Tu cairás na terra vazia; não será recolhido ou levantado. Entregar-te-ei como alimento para animais da terra e para as aves dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Então, todos os moradores do Egito saberão que Eu sou Yahweh, porque eles têm sido um bordão de cana para a casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Quando eles te tomaram nas mãos, tu te quebraste e rasgaste os ombros deles; e, quando eles encostaram em ti, tu foste quebrado, mas fizeste as pernas deles ficarem instáveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Portanto, assim declara Yahweh Deus: Vê! Eu trarei a espada contra ti. Eliminarei de ti tanto homem como animal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'E a terra do Egito se tornará vazia e em ruína. E eles saberão que Eu Sou Yahweh, porque o monstro do mar havia falado: \'O rio é meu, porque eu o fiz\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Portanto, vê! Estou contra ti e o teu rio e entregarei a terra do Egito para desolação e perda, e se tornará um deserto, desde Migdol até Sevene e as fronteiras da Etiópia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Nenhum pé de homem passará por ela e nem pé de animal passará por ela. Não será habitada durante quarenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Porque Eu tornarei a terra do Egito em desolação no meio das terras não habitadas e as suas cidades serão desoladas por quarenta anos no meio das cidades arruinadas; e espalharei os egípcios entre as nações e os dispersarei pelas terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Porque assim declara Yahweh Deus: No fim de quarenta anos, juntarei o Egito no meio dos povos entre os quais fora espalhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'Eu restaurarei as fortunas do Egito e os trarei de volta para a região de Patros, para suas terras de origem. E, ali, serão um reino humilde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Será o mais humilde entre os reinos e não será mais levantado entre as nações. Eu os diminuirei para que não mais governem sobre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Os egípcios não terão mais a confiança da casa de Israel. Ao invés disso, eles serão uma lembrança da iniquidade que Israel cometeu quando olhou para o Egito à procura de socorro. E eles saberão que Eu sou Yahweh Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Isso aconteceu no ano vinte e sete, no primeiro dia do primeiro mês, quando a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, '\"Filho do homem, Nabucodonosor, o rei da Babilônia, enviou o seu exército num trabalho duro contra Tiro. Toda cabeça se gastou até ficar calva e todo ombro esfolou a pele. Ele e o seu exército não tiveram nenhum benefício pelo trabalho árduo que fizeram contra Tiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Portanto, assim diz Yahweh Deus: \'Vê! Darei a terra do Egito a Nabucodonosor, o rei da Babilônia, e ele tirará a sua riqueza, roubará suas possessões, e levará tudo o que ele encontrar ali; essa será a recompensa para seu exército.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Eu lhe dei a terra do Egito como a recompensa do trabalho que ele prestou para Mim — esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Neste dia, Eu farei brotar um chifre da casa de Israel; Eu farei com que tu fales no meio deles e eles saberão que sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'A palavra de Yahweh veio a mim, dizendo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, '\"Filho do homem, profetiza e diz, \'Assim diz Yahweh Deus: Lamentai, \'Maldito é o dia que está por vir\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'O dia está perto sim, o dia de Yahweh. Será um dia de nuvens, uma hora de julgamento das nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Depois uma espada virá contra o Egito e haverá angústia na Etiópia quando os mortos cairem no Egito, quando eles levarem a sua riqueza, e quando as suas fundações forem destruídas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Etiópia, Líbia, Lídia e todos os estrangeiros, junto com o povo pertecente à aliança, todos cairão pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Assim diz Yahweh: Os que apoiam o Egito cairão e o orgulho da sua força cairá. Desde Migdol até Sevene seus exércitos cairão pela espada — esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Eles serão desolados no meio das terras abandonadas e as suas cidades estarão entre as cidades aruinadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'E eles saberão que Eu sou Yahweh, quando Eu puser fogo no Egito e quando os que a ajudavam forem destruidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Neste dia, enviarei mensageiros em navios para aterrorizar a segurança da Etiópia e haverá angústia entre eles no dia do juízo do Egito. Eis que está vindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Assim diz Yahweh Deus: Eu darei fim às multidões do Egito pela mão de Nabucodonosor, o rei da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Ele, junto ao seu exército, o terror das nações, serão trazidos para destruir a terra; eles desembainharão as suas espadas contra o Egito e encherão a terra de mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Eu secarei os rios e venderei a terra para o homem mau. Eu farei a terra e a sua plenitude desolada pela mão de estranhos — Eu, Yahweh, falei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Assim diz Yahweh Deus: Destruirei os ídolos e cessarei as imagens do ídolo de Mênfis. Não haverá mais um príncipe na terra do Egito e Eu trarei terror ao meio dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'E assolarei a Patros, colocarei fogo em Zoã e executarei atos de juízo em Nô.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Pois Eu derramarei o Meu furor sobre Pelúsio, a fortaleza do Egito, eliminarei a multidão de Tebas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'E colocarei fogo no Egito; Pelúsio estará em grande angústia, Tebas será destruída e Mênfis terá inimigos todos os dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Os jovens no Áven e Pi-Besete cairão à espada e suas cidades cairão em cativeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Em Táfnes, o dia escurecerá, quando ali Eu quebrar o jugo do Egito; e o orgulho do seu poder será eliminado. Uma nuvem a cobrirá e suas filhas serão levadas ao cativeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Assim, executarei atos de juízo no Egito e eles saberão que Eu sou Yahweh\"\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Então, no décimo primeiro ano, no primeiro mês, no sétimo dia do mês, a palavra do Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, '\"Filho do homem, Eu quebrei o braço do Faraó, o rei do Egito. Vê! Não foi atado e nem foram colocadas curativos para sarar, para tornar-se forte e conseguir manejar a espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Portanto, assim diz Yaweh Deus: \'Eis que Eu estou contra o Faraó, o rei do Egito. E Eu quebrarei os seus braços, tanto o forte quanto o quebrado e farei a espada cair da sua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Espalharei os egípcios no meio das nações e os dispersarei pelas terras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Fortalecerei os braços do rei da Babilônia e colocarei Minha espada na sua mão para destruir os braços do Faraó. Ele gemerá diante do rei da Babilônia como geme o que está morrendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Eu fortificarei os braços do rei da Babilônia, mas os braços do Faraó cairão. E eles saberão que Eu sou Yahweh, quando puser a Minha espada na mão do rei da Babilônia; e ele atacará a terra do Egito com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Então, Eu espalharei os egípcios entre as nações e os dispersarei pelas terras. E eles saberão que Eu sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Sucedeu acerca disto que, no décimo primeiro ano, no terceiro mês, no primeiro dia do mês, veio a mim a palavra de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, '\"Filho do homem, dize ao Faraó, o rei do Egito, e à multidão em sua volta: \'Quem é semelhante a ti em sua grandeza?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Eis que a Assíria era um cedro no Líbano, com ramos formosos, de sombrosa folhagem, de alta estatura, com seus ramos expessos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Muitas águas o fizeram crescer; as profundezas das águas o fez crescer; rios corriam nesta área e os seus canais eram estendidos para todas árvores do campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Era mais alta que qualquer outras árvores do campo e se multiplicaram os seus ramos e as suas varas se alongaram por causa das muitas águas em suas raízes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Todas as aves do céu se aninhavam nos seus ramos, todos os animais do campo davam cria debaixo das suas folhagens. E as nações se assentavam à sua sombra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Era formosa na sua grandeza e na extensão dos seus ramos e, nas muitas águas, estavam as suas raízes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Os cedros no jardim de Deus não se igualavam a ele. Nenhuma árvore de cipreste se assemelhava aos seus ramos, plátanos não se comparavam aos seus galhos. Não havia outra árvore no jardim de Deus como esta em sua formosura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Eu o fiz formoso com a multidão de ramos; e todas árvores do Éden, que estavam no jardim de Deus, tiveram inveja dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Portanto, assim diz Yahweh Deus: Porque te elevaste em tua estatura, te levantaste no teu topo entre seus ramos e exaltaste teu coração por causa da tua altura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Eu te entreguei na mão da mais poderosa das nações, que te dará o tratamento merecido pela tua corrupção. Já te lançei fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Estrangeiros, que eram terror de todas as nações, te cortaram e te deixaram morrer. Os teus ramos caíram sobre os montes e em todos os vales; os teus renovos foram quebrados por todas as correntes da terra. Então, todas as nações da Terra se retiraram debaixo das tuas sombras e te deixaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Todas as aves do céu pousavam no tronco da árvore caída e todos os animais do campo se vieram sobre os seus ramos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Isso aconteceu para que nenhuma outra árvore que crescesse junto às águas, se exaltasse pelas suas folhagens ou por sua altura, para que nenhuma outra árvore que cresce junto às águas crescesse até o alto. Pois todas elas estão destinadas à morte abaixo da terra, no meio dos filhos dos homens, com os que descem à cova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Assim diz Yahweh Deus: No dia em que o cedro desceu para o Sheol, Eu trouxe luto para a terra, cobrí as suas águas profundas e retive as águas do oceano. Retive as águas profundas e fiz aparecer luto para o Líbano, por causa dele. E todas as árvores do campo desfaleceram por causa dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Eu trouxe tremor para as nações ao som da sua queda, quando o fiz descer ao inferno, com aqueles que descem à cova. Eu consolei todas as árvores do Éden e o melhor do Líbano, todas as árvores que beberam as águas, dos lugares mais baixos da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Pois elas também desceram com o cedro para o Sheol, para se unir aos que foram mortos pela espada. Estes foram seu braço forte, as nações que viviam às suas sombras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Qual das árvores do Éden que era semelhante a ti em glória e em grandeza? Também tu serás derrubada com as árvores do Éden nas mais baixas partes da terra; no meio dos incircuncisos, morarás com aqueles que foram mortos pela espada\'. Este é Faraó e toda sua multidão — essa é a declaração de Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'E sucedeu que, no décimo segundo ano, no décimo segundo mês, no primeiro dia do mês, a palavra de Yahweh veio a mim dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, '\"Filho do homem, levanta uma lamentação por Faraó, o rei do Egito; dize-lhe: \'Foste comparado a um filho de leão entre as nações, mas és como um monstro nos mares; feres e agitas as águas, sujando-as com teus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Assim diz Yahweh Deus: \'Estenderei Minha rede sobre ti no ajuntamento de muitos povos e vão te recolher na Minha rede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Vou te abandonar na terra e te lançar no campo, farei com que as aves do céus morem em ti; e os animais famintos da terra sejam saciados por ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'E, porei tua carne sobre as montanhas e encherei os vales com a podridão do teu corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Depois, derramarei teu sangue sobre os montes e as nascentes dos vales se encherão com teu próprio sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Quando te destruir, cobrirei os céus e escurecerei tuas estrelas; cobrirei o sol com uma nuvem e a lua não resplandecerá sua luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Todas as estrelas brilhantes do céu escurecerei sobre ti e trarei trevas sobre tua terra — assim diz Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Afligirei o coração de muitos povos, de terras que não conheces, quando Eu causar tua destruição entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'E muitos povos ficarão perplexos por tua causa; seus reis tremerão de terror, quando Eu agitar Minha espada diante deles. A todo instante, um tremerá por causa de ti, no dia da tua queda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Assim diz Yahweh Deus: \'A espada do rei da Babilônia virá contra ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Farei cair, pela espada dos valentes, a tua multidão, e cada valente aterrorizará as nações. Eles tirarão o orgulho do Egito e destruirão toda a sua multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Destruirei todos os animais que estão junto às muitas águas; nem pés de homem, nem cascos de animais agitarão mais as águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Então, acalmarei suas águas e farei com que seus rios corram como azeite — assim diz Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Quando Eu fizer da terra do Egito um lugar de abandono, quando a terra for despojada de tudo, quando Eu ferir todos os que habitam nela, saberão que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Haverá um lamento. As filhas das nações lamentarão por causa do Egito e por causa de toda a sua multidão — assim diz Yahweh Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'E aconteceu que, no décimo segundo ano, no décimo quinto dia do mês, veio a palavra de Yahweh a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, '\"Filho do homem, pranteia pela multidão do Egito e faz com que desçam — ela e as filhas das nações poderosas — às profundezas da terra, juntamente com aqueles que descem à cova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, '\'Acaso és mais formosa que qualquer outra? Desce e deita-te com o incircunciso\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Eles cairão entre aqueles que foram mortos pela espada; o Egito foi entregue à espada! Eles o medirão juntamente com sua multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Os valentes poderosos de dentro do Sheol declararão a respeito do Egito e de sua aliada: \'Eles desceram juntamente com os incircuncisos e com aqueles que foram mortos pela espada\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'A Assíria está lá com toda sua assembleia. Os sepulcros a cercaram. Todos foram mortos pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Aqueles cujos sepulcros foram colocados no interior das covas, com toda a sua assembleia. Sua sepultura cerca todos os que tinham sido mortos pela espada, causando espanto na terra dos viventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Ali está Elão com toda a sua multidão, a sepultura o cercou; todos foram mortos. Todos aqueles que foram mortos pela espada, que desceram incircuncisos até as partes mais baixas da terra, que trouxeram terrores à terra dos viventes e carregam sua própria vergonha, juntamente com aqueles que descem à cova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Eles puseram uma cama para Elão e sua multidão no meio dos mortos; sua sepultura o cercou. Todos esses incircuncisos foram mortos pela espada, porque trouxeram terrores à terra dos viventes. Portanto, levarão sua própria vergonha, com aqueles que descem à cova. Elão está entre todos os que foram mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Ali estão Meseque, Tubal e toda sua multidão! Suas sepulturas os cercam. Todos eles são incircuncisos, mortos pela espada, porque trouxeram terrores à terra dos viventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Eles não estarão com os valentes que caíram incircuncisos, que desceram ao Sheol com seus instrumentos de guerra, colocaram suas espadas debaixo de suas cabeças e suas iniquidades sobre seus ossos. Porque eram o terror dos valentes na terra dos viventes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Mas tu, Egito, serás abatido no meio dos incircuncisos! Estarás com os que foram atravessados pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Edom está ali com seus reis e com todos os seus líderes. Eles foram colocados com todos aqueles que foram mortos pela espada. Estarão com os incircuncisos e com aqueles que descem à cova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Ali estão os príncipes do norte, todos eles e todos os sidônios, que desceram com aqueles que foram atravessados pela espada. Eram poderosos e causavam medo nos outros, mas agora estão lá, envergonhados, incircuncisos com aqueles que foram atravessados pela espada. Eles levaram sua própria vergonha com os que descem à cova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Faraó olhará e será consolado por toda sua multidão que havia perecido pela espada — Faraó e todo seu exército — assim diz Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Eu o coloquei como terror na terra dos viventes, mas ele vai ser jogado no meio do incircunciso, entre aqueles atravessados pela espada, Faraó e toda sua multidão — assim diz Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, '\"Filho do homem, declara isto ao seu povo; dize-lhes: \'Quando trago uma espada contra uma certa terra, o povo dessa terra leva um homem dentre eles e fazem dele a sua sentinela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'Ele vê que a espada vem sobre a terra e toca a sua trombeta para avisar o povo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'Se o povo ouvir o som da trombeta, mas não der atenção e, se a espada vier e os matar, o sangue de cada um está sobre sua própria cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Se alguém ouvir o som da trombeta e não o levar em conta, o seu sangue será sobre ele; mas se ele atentar, ele salvará a sua própria vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Contudo, se o sentinela não tocar a trombeta quando vir a espada, fazendo com que o povo não seja avisado e se a espada vier e levar uma vida, então, essa pessoa morrerá em seus próprios pecados, mas exigirei o seu sangue do sentinela\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Mas quanto a ti, filho do homem! Coloquei-te por sentinela sobre a casa de Israel; ouvirás as palavras da Minha boca e os avisarás em Meu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Se Eu disser ao corrupto: \'Certamente morrerás!\' mas, não anunciares isto como advertência ao corrupto, acerca do seu caminho, então, ele que é corrupto morrerá em seu pecado, mas exigirei o seu sangue da tua mão!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Tu, porém, se avisares ao corrupto sobre o seu caminho, para que se aparte dele e ele não se apartar do seu caminho, então, ele morrerá em seu pecado, mas tu terás salvo a tua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'E tu, filho do homem, diz à casa de Israel: \'Assim falarás: \'Nossas transgressões e nossos pecados estão sobre nós e estamos desfalecendo neles! Como viveremos?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Dize-lhes: \'Tão certo como Eu vivo — assim diz Yahweh Deus — não tenho prazer na morte do corrupto, pois, se o corrupto se arrepender do seu caminho, ele viverá! Arrependei-vos! Arrependei-vos dos vossos maus caminhos! Pois, por que devíeis morrer, casa de Israel?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Tu, agora, filho do homem, diz ao povo: \'A retidão do homem reto não o salvará quando ele pecar! A corrupção do homem mau não o fará perecer caso se arrependa do seu pecado! Pois o homem reto não viverá por causa da sua retidão, quando ele pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Se eu disser ao reto: Ele certamente viverá! e, se ele confiar na sua retidão e depois cometer injustiça, não Me lembrarei de nenhuma obra da sua retidão. Ele morrerá pela corrupção que cometeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Então, se eu disser ao corrupto: Certamente morrerás, mas, se ele se arrepender dos seus pecados e fizer o que é justo e reto —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'se ele devolver o que emprestou ou restituir o que roubou e, se andar nos estatutos da vida e não mais cometer pecado, então, certamente viverá, ele não morrerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Nenhum dos pecados que ele tiver cometido será lembrado contra ele; ele fez o que é justo e reto e certamente viverá!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Mas vós dizeis: O caminho do Senhor não é justo! Porém, são os vossos caminhos que não são justos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Quando um homem reto se desviar da sua retidão e cometer pecado, então, ele morrerá!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Quando o corrupto se afastar da sua corrupção e fizer o que é justo e reto, ele viverá por causa dessas coisas!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Mas vós dizeis: O caminho do Senhor não é justo! Eu julgarei a cada um segundo o seu caminho, casa de Israel!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'E aconteceu, no décimo segundo ano, no quinto dia do décimo mês do cativeiro, veio um fugitivo de Jerusalém e disse: \"A cidade foi capturada!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'A mão de Yahweh havia estado sobre mim na noite anterior à vinda do fugitivo e a minha boca foi aberta no momento em que ele veio pela manhã. Assim, a minha boca foi aberta; não mais fiquei em silêncio!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, '\"Filho do homem, os que habitam naquelas ruínas na terra de Israel estão falando e dizem: \'Abraão era uma só pessoa e herdou a terra, mas nós somos muitos! A terra nos foi dada por possessão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Portanto, dize-lhes: \'Assim diz Yahweh Deus: Vós comeis sangue e ergueis os vossos olhos aos vossos ídolos, também derramais sangue de pessoas. Será que tereis a posse da terra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Vós dependestes das vossas espadas e fizestes coisas abomináveis; cada um profana a esposa do seu próximo. Será que tereis a posse da terra?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Assim lhes dirás: \'Assim diz Yahweh Deus: Tão certo como Eu vivo, os que vivem entre as ruínas morrerão pela espada e Eu darei esses nos campos para que sejam devorados pelas feras e os que estão nas fortalezas e nas cavernas morrerão de pragas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Então, tornarei a terra numa desolação e horror; e a soberba do seu poder findará, pois os montes de Israel ficarão desertos e ninguém passará por eles\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Assim, saberão que Eu sou Yahweh, quando Eu fizer da terra uma desolação e um horror por causa de todas as abominações que fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'E tu, agora, filho do homem — teu povo fala sobre ti nos muros e nos portões das casas e cada um diz ao outro — cada homem ao seu irmão: \'Vamos ouvir a palavra que procede de Yahweh!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Por isso, o Meu povo virá a ti, como costumam fazer, e se sentarão diante de ti e ouvirão as tuas palavras, mas não as obedecerão. Pois palavras certas estão na suas bocas, mas os seus corações estão atrás de lucro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Pois tu és como uma bela canção para eles, um maravilhoso som que é tocado com um instrumento de corda, por isso ouvirão as tuas palavras, mas nenhum deles as obedecerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Então, quando tudo isto acontecer, eis que vai acontecer — aí eles saberão que um profeta esteve no meio deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, '\"Filho do homem, profetiza contra os pastores de Israel. Profetiza e dize-lhes: \'Assim diz Yahweh Deus, aos pastores: Ai dos pastores de Israel que pastoreiam a si mesmos. Não deviam os pastores guardar o rebanho?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Vós comeis as gorduras e vos vestis de lã. Matais o cevado do rebanho; mas não cuidais das ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Não fortalecestes as que têm doenças, nem sarastes as enfermas. Não ligastes as quebradas, não procurastes as desgarradas, nem buscastes as perdidas. Pelo contrário, liderais sobre elas com rigor e violência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Então, foram espalhadas por falta de um pastor e se tornaram comida para todas as feras dos campos após terem sido espalhadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'O Meu rebanho se espalha pelas montanhas e em cada monte elevado, e se dispersam por toda a superfície da terra. Ainda assim, ninguém os procura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Portanto, pastores, ouvi a palavra de Yahweh:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Tão certo como Eu vivo — declara Yahweh Deus — já que o Meu povo se tornou presa e alimento para todas as feras nos campos, porque não havia um pastor e nenhum dos Meus pastores procuraram o Meu rebanho, mas cuidam de si mesmos, guardam a si mesmos e não pastorearam o Meu rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Portanto, pastores, ouvi a palavra de Yahweh:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Assim diz Yahweh Deus: Eis que estou contra os pastores e exigirei o Meu rebanho das suas mãos. Então, farei com que deixem de pastorear o Meu rebanho; os pastores não mais pastorearão a si mesmos, uma vez que tirarei o Meu rebanho das suas mãos, para que o Meu rebanho não mais lhes sirva de alimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Porque assim diz Yahweh Deus: Eis que Eu mesmo procurarei pelo Meu rebanho e cuidarei dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Assim como um pastor procura pelo seu rebanho, no dia em que está no meio do seu rebanho espalhado, assim buscarei pelo Meu rebanho e os resgatarei de todos os lugares por onde foram espalhados no dia de nuvens e de escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Então, os trarei para fora dentre os povos; Eu os congregarei de diversas partes das terras e os trarei de volta à sua terra. Eu os colocarei em pastos à beira dos montes de Israel, junto às fontes, e em todos os lugares habitados da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Eu os colocarei em verdes pastos; os altos montes de Israel serão a sua pastagem. Ali, descansarão em bons lugares para a pastagem, em pastos abundantes, e pastarão nos montes de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Eu mesmo pastorearei o Meu rebanho e lhes darei descanso — esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Buscarei os perdidos e restaurarei os desgarrados. Unirei os quebrados e sararei os enfermos, mas os gordos e fortes serão destruídos. Eu os pastorearei com justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Agora tu, Meu rebanho — assim diz Yaweh Deus: eis que Eu serei um Juiz entre as ovelhas e entre carneiros e bodes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Não basta se alimentar num bom pasto, precisais pisotear o que restar do pasto; e não vos é suficiente beber de águas limpas, precisais enlamear os rios com os vossos pés?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'As Minhas ovelhas deverão comer o que pisoteastes e beber o que enlameastes com os pés?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Portanto, assim lhes diz Yahweh Deus: Eis que Eu mesmo julgarei entre as ovelhas gordas e as magras,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'porquanto puxastes com os vossos quadris e ombros e empurrais com chifres as fracas, até as espalhardes para longe da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Salvarei as Minhas ovelhas e não servirão mais de presa; julgarei entre uma ovelha e outra!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Colocarei no meio deles um só pastor, o Meu servo Davi. Ele os alimentará e será o seu pastor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Pois Eu, Yahweh, serei o seu Deus e o Meu servo Davi será um príncipe no meio deles — Eu, Yahweh, assim declarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Então, farei um acordo de paz com eles e tirarei os animais selvagens da terra, para que vivam em segurança no deserto e durmam seguros nas florestas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Também farei deles e do lugar ao redor do Meu monte, bênção; mandarei chuvas no tempo certo. Essas serão chuvas de bênção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Depois, as árvores do campo darão o seu fruto e a terra dará o seu produto. As Minhas ovelhas estarão seguras na sua terra; então, saberão que Eu sou Yahweh, quando quebrar as varas do seu jugo, e, quando os resgatar da terra dos que os escravizaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Não mais serão presa para as nações e os animais selvagens da terra não mais os devorarão, pois viverão em segurança e ninguém os intimidará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Pois Eu lhes darei um bom lugar para o plantio, assim, nunca mais morrerão de fome na terra e as nações não mais trarão insultos contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Então, saberão que Eu, Yahweh seu Deus, estou com eles. Eles são o Meu povo, a casa de Israel — esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Porque vós sois ovelhas do Meu pasto e Meu povo e Eu sou vosso Deus — esta é a declaração de Yahweh Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Então, a palavra de Yahweh veio a mim dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, '\"Filho do homem, põe a tua face contra o monte Seir e profetiza contra ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'Dize-lhe: \'Assim diz Yahweh Deus: Eis que Eu sou contra ti, monte Seir, e te golpearei com a Minha mão e te farei uma desolação e um horror.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Farei de tuas cidades ruínas, e vós tornareis desolados; então, sabereis que eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Porque sempre foste hostil ao povo de Israel e porque os espalhaste pelas mãos da espada, no tempo da sua angústia, no momento em que o castigo era maior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Assim como Eu vivo — esta é a declaração de Yahweh Deus — Eu te prepararei para o derramamento de sangue e o sangue vai te perseguir! Já que tu não odeias o derramamento de sangue, o sangue te perseguirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Farei do monte Seir uma desolação completa, um deserto e eliminarei qualquer um que passar e retornar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Então, encherei as suas montanhas com os seus mortos. Todos aqueles mortos pela espada, cairão em teus altos montes e vales, e em todos os teus córregos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Farei de vós uma perpétua desolação. Vossas cidades não serão habitadas, assim vós sabereis que eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Tu disseste: \"Estas duas nações e estas duas terras se tornarão minhas e nós as possuiremos\", mesmo que Yahweh esteja presente com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Portanto, tão certo como Eu vivo — declara Yahweh Deus — assim farei segundo a tua ira e segundo o teu zelo que tiveste no teu ódio a Israel e Me mostrarei a eles quando Eu te julgar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Assim saberás que Eu sou Yahweh. Eu ouvi todos os insultos que tu falaste contra os montes de Israel, quando tu disseste: \"Eles foram destruídos, eles foram entregues a nós, para os devorar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Tu te exaltaste contra Mim com o que disseste e tu multiplicaste as palavras que falaste contra Mim; e Eu ouvi tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Assim diz Yahweh Deus: Farei de ti uma desolação, enquanto toda terra se regozija.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Como te alegraste com a destruição da herança do povo de Israel, farei o mesmo a ti. Tu te tornarás uma desolação, monte Seir, e todo o Edom; sim todo ele! Então, eles saberão que Eu sou Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, '\"Agora tu, filho do homem, profetiza aos montes de Israel e dize: \'Montes de Israel, ouvi a palavra de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Assim diz Yahweh Deus: O inimigo disse contra ti: \"Bem feito!\" e \"Os teus antigos lugares altos tornaram-se nossa possessão\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Portanto, profetiza e dize: \"Assim diz Yahweh Deus: Por causa da vossa desolação e por causa dos ataques que vieram sobre vós de todos os lados, vós vos tornastes uma possessão das outras nações; fostes sujeitos aos lábios, às línguas caluniosas e às histórias do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Portanto, montes de Israel, ouvi a palavra de Yahweh Deus: Assim diz Yahweh Deus aos montes e às colinas, às correntes de água e aos vales, aos desertos assolados e às cidades abandonadas que se tornaram presa e alvo de zombaria para as outras nações, que os rodeiam —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'portanto, assim diz Yahweh Deus: \'Certamente, falei, no fogo e na Minha fúria, contra outras nações e contra Edom e todos que tomaram a Minha terra para eles como sua possessão, contra todos que tiveram ao mesmo tempo júbilo em seu coração e desdém em seu espírito, para saquearem a Minha terra\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Portanto, profetiza à terra de Israel e dize aos montes e às colinas, às correntes de água e aos vales: \'Assim diz Yahweh Deus: Eis que falei em Minha fúria e em Minha ira, porque vós levastes vexame às nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Portanto, assim diz Yahweh Deus: Eu mesmo levantarei a Minha mão para jurar que as nações que estão ao redor de vós certamente, carregarão a sua própria vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Vós, porém, montes de Israel, produzireis ramos e dareis fruto para o meu povo Israel, uma vez que, em breve, retornarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Eis que Eu estou convosco e vos trato com graça; sereis lavrados e semeados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Assim, multiplicarei em vós homens dos montes em toda a casa de Israel, as cidades serão habitadas e as ruínas reedificadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Multiplicarei homem e animais em vossos montes, para que eles multipliquem e sejam frutíferos. Depois, farei com que sejais habitada, como antes, Eu vos farei prosperar mais do que fostes no passado e sabereis que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Trarei homens, meu povo Israel, para andarem sobre vós. Eles vos possuirão e vós sereis sua herança e não mais causarão morte dos seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Assim diz Yahweh Deus: Porque a vós eles dizem: \"Vós devorais pessoas e os filhos da vossa nação morreram\",');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'portanto, não mais devorareis as pessoas e não mais fareis a vossa nação ficar sem filhos. Esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Nem mais vos deixarei ouvir insultos das nações; não mais levarás sobre vós o vexame dos povos ou fará com que a vossa nação caia — esta é a declaração de Yahweh Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Depois, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, '\"Filho do homem, quando a casa de Israel habitou em sua terra, eles profanaram os seus caminhos e seus feitos. Seus caminhos eram como a impureza de uma mulher na menstruação, assim eram diante de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Por isso, derramei a Minha fúria contra eles, por causa do sangue que derramaram na terra e porque contaminaram com seus ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Espalhei-os pelas nações; foram dispersos pelas terras. Julguei-os segundo os seus caminhos e seus feitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Depois, foram às nações, e onde quer que foram, profanaram o Meu santo nome, quando o povo deles dizia: \'São estes realmente o povo de Yahweh? Pois foram lançados para fora da sua terra\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Mas tive compaixão do Meu santo nome, que a casa de Israel havia profanado dentre as nações, quando lá estiveram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Portanto, diz à casa de Israel: \'Assim diz Yahweh Deus: Não procedo assim por causa de vós, casa de Israel, mas pelo Meu santo nome, que vós profanastes dentre as nações por onde fostes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Porque santificarei o Meu grande nome, que vós profanastes dentre as nações; no meio das quais vós profanastes. Então, as nações saberão que Eu sou Yahweh — esta é a declaração de Yahweh Deus — quando vós virdes que Eu sou santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Eu vos tirarei dentre as nações e vos ajuntarei de toda a terra e vos reunirei na vossa terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Depois, aspergirei água pura sobre vós e ficareis purificados de todas as vossas impurezas e de todos os vossos ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Dar-vos-ei um novo coração e porei, no vosso íntimo, um novo espírito e tirarei o vosso coração de pedra e vos darei um coração de carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Colocarei o Meu Espírito em vós e vos farei andar em Meus estatutos e guardar os Meus mandamentos, para que os cumprais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Depois, habitareis na terra que Eu dei aos vossos antepassados; sereis Meu povo e Eu serei vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Porque, Eu vos livrarei de toda a vossa imundície. Trarei trigo e o multiplicarei; não mais porei fome sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Multiplicarei o fruto das árvores e a produção do campo, para que não mais tenhais vergonha e fome entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Então, lembrareis dos vossos caminhos corruptos e vossos feitos que não eram bons; mostrareis nojo em vossos rostos, por causa do vosso próprio pecado e vossas obras abomináveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Não faço isto por causa de vós — esta é a declaração de Yahweh — sabeis disso. Então, ficai envergonhados e humilhai-vos por causa dos vossos caminhos, casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Assim diz Yahweh Deus: No dia em que Eu vos purificar de toda a vossa iniquidade, Eu vos farei habitar nas cidades e reedificar os lugares arruinados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'Pois lavrareis a terra arruinada até que não mais seja uma ruína, diante dos olhos de todos que passam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Então, eles dirão: \"Esta terra estava desolada, mas tornou-se como o jardim do Éden; as cidades desoladas e as ruínas desabitadas que foram derribadas são agora fortificadas e habitadas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'E as outras nações ao vosso redor saberão que Eu sou Yahweh, que edifiquei as ruínas e replantei os lugares abandonados. Eu sou Yahweh. Assim declarei e assim farei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Assim diz Yahweh Deus: Vou novamente ser procurado pela casa de Israel, para fazer isto para eles, para lhes multiplicar como um rebanho de pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Como rebanho é separado para sacrifícios, como rebanho de Jerusalém nas suas festas solenes, assim serão as cidades arruinadas, cheias de rebanhos de pessoas e saberão que Eu sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'A mão de Yahweh estava sobre mim, Ele me levou pelo Espírito de Yahweh e me colocou no meio de um vale; estava cheio de ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Depois, Ele me fez passar ao redor deles; eram muitos no grande vale, e estavam sequíssimos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Ele me disse: \"Filho do homem, poderão estes ossos voltar a viver?\". E eu disse: \"Senhor Yahweh, só Tu o sabes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Então, Ele me disse: \"Profetiza sobre estes ossos e dize-lhes: \'Ossos secos, ouvi a palavra de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Assim diz Yahweh Deus a estes ossos: Eis que porei o espírito em vós e vivereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Colocarei tendões sobre vós e porei carne; revestir-vos-ei de pele e porei em vós o espírito, para que vivais. Então, sabereis que Eu sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Então, profetizei como me fora ordenado; enquanto profetizava, eis que houve um ruído, como de alguma coisa se mexendo. Depois, os ossos se ajuntaram — cada um ao seu osso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Olhei e eis que tendões já estavam neles; a carne cresceu e a pele lhes cobriu; mas ainda não havia neles o espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Então, Yahweh me disse: \"Profetiza ao espírito, profetiza, filho do homem, e dize-lhe: \'Assim diz Yahweh Deus: Vem dos quatro ventos, ó espírito e assopra nestes mortos, para que vivam\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Assim, profetizei como me ordenara; o espírito entrou neles e viveram. Então, ficaram de pé, um exército muito numeroso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Depois, Yahweh me disse: \"Filho do homem, estes ossos são toda a casa de Israel. Eis que dizem: \'Nossos ossos secaram, foi-se a nossa esperança. Fomos derrubados\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Portanto, profetiza e dize-lhes: \'Assim diz Yahweh Deus: Eis que abrirei as vossas sepulturas e vos tirarei delas, Meu povo. E vos trarei à terra de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Depois, sabereis que Eu sou Yahweh, quando abrir as vossas sepulturas e vos tirar delas, povo Meu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Porei o Meu Espírito em vós e vivereis, e vos farei descansar na vossa terra, e sabereis que Eu sou Yahweh. Assim declaro e assim farei — esta é a declaração de Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Então, a palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, '\"Agora, pois, pega um pedaço de madeira e escreve nele: \'Para Judá e para todo o povo de Israel, seus companheiros\'. Depois, toma outro pedaço de madeira e escreve nele: \'Para José, ramo de Efraim, e para todo o povo de Israel, seus companheiros\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Junta ambos num só pedaço de madeira, para que se tornem um só em tua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Quando o teu povo falar a ti e disser: \'Não nos revelarás o que estas coisas significam?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Então, dize-lhes: \'Assim diz Yahweh Deus: Eis que levarei o ramo de José, que está na mão de Efraim, e as tribos de Israel, seus companheiros, e os ajuntarei ao ramo de Judá, e serão um só ramo, e se tornarão um só na Minha mão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Segura, na tua mão, os ramos nos quais escreveste diante dos seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Declara-lhes: \'Assim diz Yahweh Deus: Eis que estou prestes a tirar o povo de Israel dentre as nações para onde foram; Eu os ajuntarei de todas as terras em derredor e os trarei para sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Farei deles uma só nação na terra, nos montes de Israel, e haverá um só rei, será rei sobre todos eles, e não mais serão duas nações. Não mais estarão divididos em dois reinos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Então, não mais se profanarão com os seus ídolos, nem com suas coisas abomináveis, nem com outros pecados. Porquanto, os livrarei de todas as suas ações de incredulidade com as quais pecaram, e os purificarei. Então, serão Meu povo e Eu serei seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Davi, meu servo, reinará sobre eles. Então, haverá um só pastor sobre eles e andarão segundo os Meus decretos e guardarão os Meus estatutos e os obedecerão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Viverão na terra que dei ao Meu servo Jacó, onde os seus pais habitaram. Nela viverão para sempre, eles, seus filhos e seus netos, porque Davi, Meu servo, será seu líder para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Estabelecerei um acordo de paz com eles. Será um acordo eterno com eles. Irei estabelecê-los e os multiplicarei e colocarei o Meu santo lugar no meio deles para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'A Minha habitação será com eles; serei seu Deus, e eles serão Meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Então, as nações saberão que Eu sou Yahweh que santifico Israel, quando o Meu santo lugar estiver no meio deles\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'A palavra de Yahweh veio a mim dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, '\"Filho do homem, vira o teu rosto para Gogue, a terra de Magogue, o principal chefe de Meseque e Tubal; e profetiza contra ele, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, '\'Assim diz Yahweh Deus: Eis que sou contra ti, Gogue, principal chefe de Meseque e Tubal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Então, Eu te farei voltar e porei anzóis em teus queixos; Eu te levarei com todas as tuas armas, teus cavalos e cavaleiros, toda armadura completa, uma grande companhia com grandes e pequenos escudos, todos manejando espada!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Pérsia, Cuxe e Pute estarão com eles, todos com escudos e capacetes!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Omer e todas suas tropas e a casa de Togarma, das partes distantes do norte e todas as suas tropas! Muitas pessoas estarão contigo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Prepara-te! Sim, dispõe-te tu e tuas tropas reunidas contigo e sê o comandante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Tu, Israel, serás visitado depois de muitos dias; e, depois de muitos anos, tu irás à terra que se recuperou da espada e que foi reunida dentre muitos povos, junto às montanhas de Israel, as quais foram arruinadas; mas aquela terra foi tirada dentre os povos, e todos eles viverão em segurança!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Então, subirás, virás como a tempestade, e serás como uma nuvem que cobre a terra, tu, todas as tuas tropas e muitos soldados contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Assim diz Yahweh Deus: Acontecerá naquele dia que terás planos ambiciosos no teu coração e farás projetos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Então, dirás: \'subirei contra a terra aberta; eu irei contra as pessoas tranquilas, que vivem em segurança, todos vivendo onde não há muros ou trancas e onde não há portões na cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Eu vou capturar despojos e roubar as pilhagens, para pôr a mão contra as ruínas recentemente habitadas, contra as pessoas reunidas das nações, pessoas que estão adquirindo gado e propriedades e vivem no centro da terra\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Sabá, Dedã e os comerciantes de Társis, juntamente com todos os jovens guerreiros dirão: \'Vens tu para tomar o despojo? Reuniste teus exércitos para remover o despojo, para levar a prata e o ouro, para pegar gado e as propriedades e transportar grande despojo?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Poranto, profetiza, filho do homem, e dize para Gogue: Assim diz Yahweh Deus: Naquele dia, quando Meu povo Israel estiver vivendo em segurança, tu não o saberás?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Virás do teu lugar, do extremo norte com um grande povo contigo, todos montados a cavalos, uma grande companhia, um grande exército.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Atacarás Meu povo Israel, como uma nuvem que cobre a terra. Nos últimos dias, Eu o trarei contra Minha terra, então, as nações saberão quando Eu manifestar Minha santidade através de ti, Gogue, para ser santo diante de teus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Assim diz Yahweh Deus: Não és tu aquele de quem falei antigamente, por intermédio de Meus servos, os profetas de Israel, que profetizaram em seu próprio tempo durante anos contra eles?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Assim acontecerá naquele dia, quando Gogue atacar a terra de Israel — assim diz Yahweh Deus — Minha indignação elevará a Minha ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'No Meu zelo e no fogo da Minha ira, declaro que, naquele dia, haverá um grande terremoto na terra de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Tremerão diante de Mim, os peixes do mar, os pássaros dos céus, os animais dos campos e todas as criaturas que se arrastam na terra, bem como todas as pessoas que estão na superfície da terra. As montanhas serão derrubadas e os penhascos cairão, todos os muros cairão por terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Convocarei contra ele a espada, em todas as Minhas montanhas. Assim diz Yahweh Deus — a espada de cada homem se voltará contra seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Então, Eu o julgarei por meio da praga e do sangue; chuva transbordante e pedras de granizo e fogo, e enxofre ardente sobre ele, suas tropas, e as muitas nações que com ele estão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Assim, mostrarei a Minha grandeza e a Minha santidade, e Me tornarei conhecido aos olhos de muitas nações e eles saberão que Eu sou Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, '\"Tu, pois, filho do homem, profetiza contra Gogue e dize: Assim diz Yahweh Deus: \'Eis que Eu sou contra ti, Gogue, chefe de Meseque e Tubal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Eu te farei retornar e te guiarei; Eu te levarei do extremo norte até as montanhas de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Então, arrancarei o teu arco da tua mão esquerda e farei cair as flechas da tua mão direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Morrerás nas montanhas de Israel, tu e todas as tuas tropas e os soldados que estão contigo. Eu te entregarei às aves de rapina e aos animais selvagens dos campos, para que te devorem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Tu morrerás na superfície do campo, pois Eu mesmo declaro isto — assim diz Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Então, enviarei fogo sobre Magogue e os que vivem em segurança nas ilhas e eles saberão que Eu sou Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Pois Eu farei o Meu santo nome conhecido no meio do Meu povo Israel e não permitirei mais que Meu santo nome seja profanado; as nações saberão que Eu sou Yahweh, o santo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Eis que virá o dia e isso acontecerá — assim diz Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Então, aqueles que habitam as cidades de Israel sairão e farão incêndios com suas armas, com escudos grandes e pequenos, arcos e flechas, bastões e lanças, e, por sete anos, eles queimarão tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Eles não trarão lenha dos campos ou cortarão árvores das florestas, mas com as armas farão fogo; tomarão daqueles que os despojaram; saquearão aqueles que os saquearam — assim diz Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, '\"Naquele dia, darei a Gogue, uma sepultura em Israel, o vale daqueles que viajam para o leste do mar, que espantará aqueles que o desejarem atravessar. Lá eles irão sepultar Gogue com toda a sua multidão. Eles irão chamá-lo de vale de Hamom-Gogue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Por sete meses, a casa de Israel os sepultará, para purificar a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Pois, todos os povos da terra os sepultarão; e será um dia memorável para eles quando Eu for glorificado — assim diz Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, '\"Então, eles designarão homens para que atravessem a terra sem parar, e juntamente com os que viajam, procurem os que morreram, a fim de sepultá-los e purificar a terra. No final do sétimo mês, eles farão a busca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Ao atravessarem a terra, vendo algum osso humano, eles colocarão um sinal à sua volta, até que os coveiros o enterrem no vale de Hamom-Gogue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'E o nome da cidade será Hamoná. Dessa forma, eles purificarão a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Tu, pois, ó filho do homem, assim diz Yahweh Deus: dize a todas as aves de toda espécie e a todos os animais selvagens nos campos: \"Ajuntai-vos e vinde; reuni-vos de todos os lados para o Meu sacrifício, que faço por ti, um grande sacrifício nas montanhas de Israel, para que tu comas carne e bebas sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Tu comerás a carne dos poderosos e beberás o sangue dos príncipes da terra; dos carneiros, dos cordeiros, das cabras e dos touros engordados em Basã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Então, comereis gordura para vos satisfazerdes; e bebereis sangue até a embriaguez; com o sacrifício que vos ofereço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Vós ficareis satisfeitos de cavalos, de cavaleiros e todo homem de guerra, à Minha mesa, assim diz Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, '\"Eu estabelecerei a Minha glória entre as nações e todas as nações verão o juízo que Eu executo e a Minha mão que Eu farei cair sobre elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'A casa de Israel saberá que Eu sou Yahweh, seu Deus, desde aquele dia em diante\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'As nações saberão que a casa de Israel foi levada em cativeiro por causa da sua iniquidade, com a qual eles Me traíram, então, escondi o Meu rosto deles e os entreguei nas mãos de seus adversários e todos caíram à espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Eu os tratei de acordo com as suas imundícies e os seus pecados, escondi deles o Meu rosto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Por isso, assim diz Yahweh Deus: agora restaurarei a sorte de Jacó e terei compaixão de toda a casa de Israel, quando Eu agir com zelo pelo Meu santo nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Então, eles se esquecerão de toda a sua vergonha e deslealdade com as quais Me traíram. E descansarão, em suas terras, em segurança, sem ninguém para assustá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Quando Eu os restaurar dos povos e os reunir das terras dos seus inimigos, Eu Me mostrarei santo neles, aos olhos de muitas nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Então, eles saberão que Eu sou Yahweh, seu Deus, porque Eu os enviei ao cativeiro entre as nações, mas, depois, Eu os trouxe de volta às suas terras. Não deixarei nenhum deles em outras nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Não lhes esconderei mais o Meu rosto, quando derramar o Meu Espírito sobre a casa de Israel — assim diz Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'No início do vigésimo quinto ano de nosso cativeiro, no décimo dia do mês, no décimo quarto ano depois da tomada da cidade, no mesmo dia, a mão de Yahweh veio sobre mim;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'em visões, Deus me levou à terra de Israel; Ele me pôs sobre um monte muito alto; para o sul e havia algo que parecia ser as edificações de uma cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Depois, Ele me levou para lá, onde havia um homem, cuja aparência era como a do bronze. Uma corda de linho e uma vara de medir estavam em sua mão e ele permanecia de pé no porta da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Disse-me o homem: \"Filho do homem, vê com teus olhos e ouve com teus ouvidos, e atenta tua mente em tudo que estou te revelando, pois Eu te trouxe até aqui para te mostrar isso. Conta tudo quanto vires à casa de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Havia um muro ao redor da área do templo. E, na mão do homem, havia uma vara de medir de seis côvados de comprimento, tendo cada côvado quatro dedos a mais. Ele mediu o muro, que era a medida de uma vara de largura e uma de altura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Então, ele veio para o portão do templo, que é de frente para o oriente. Ele subiu os degraus e mediu a soleira do portão, que tinha uma vara de largura e a outra soleira, uma vara de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'As câmaras de guarda, cada uma media uma vara de comprimento e uma de largura e o espaço entre as câmaras tinha cinco côvados e na soleira do portão do templo, perto do pórtico, tinha uma vara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Ele mediu o pórtico do portão, que era uma vara de comprimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Então, mediu o pórtico do portão, que era de oito côvados. Os pilares eram de dois côvados de largura; e o pórtico do portão estava na direção do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Havia três câmaras de guarda de cada lado, e cada uma delas tinha a mesma medida, e os muros que as separavam tinham a mesma medida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Então, o homem mediu a largura da porta de entrada, que era de dez côvados; e mediu o comprimento do portão de entrada, treze côvados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Ele mediu o muro, de um côvado de altura, que faz fronteira com a frente das câmaras; as câmaras mediam seis côvados de cada lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Depois, ele mediu a porta, desde o telhado de uma câmara até da outra, que era de vinte e cinco côvados, da entrada da primeira até a segunda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Ele mediu também, o muro que estava entre as câmaras de guarda, sessenta côvados de comprimento; e mediu, ainda, o pórtico da portão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'A distância da entrada frontal do portão até o fim do pórtico do portão era de cinquenta côvados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Havia também janelas fechadas em frente às câmaras, e em frente aos pilares, dentro dos portões e ao redor, como também nos pátios. Havia janelas ao redor, pelo lado de dentro, e cada batente era decorado com palmeiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Então, o homem me levou para o pátio externo do templo; vi que havia salas e também um pavimento no pátio, com trinta salas naquele pavimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'O pavimento inferior dos portões e a sua largura era a mesma do comprimento dos portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Então, o homem mediu a distância da frente do portão inferior até o interior do pátio de dentro, que era de cem côvados do lado do oriente, e o mesmo do lado do norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Em seguida, ele mediu o comprimento e a largura do portão, que estava ao norte do pátio exterior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Havia três câmaras de cada lado do portão; seus pilares e seu pórtico, tinham a mesma medida do portão principal, que era de cinquenta côvados no comprimento e vinte e cinco côvados na largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Suas janelas, seu pórtico e suas palmeiras, eram da medida do portão de frente para o oriente; subiam sete degraus até ele, e seu pórtico ficava do lado oposto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Havia um portão para dentro do pátio, em frente ao portão voltado para o norte, justamente onde também havia o portão do oriente; o homem mediu de um portão ao outro, cem côvados de distância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Em seguida, o homem me levou para o portão da entrada do sul; seus pilares e pórtico tinham a mesma medida dos portões de fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Havia janelas fechadas na entrada e em seus pórticos, assim como nos portões. O portão do sul e seu pórtico mediam cinquenta côvados de comprimento e vinte cinco de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Havia sete degraus que subiam até o portão e seu pórtico, e havia palmeiras entalhadas nas paredes em ambos os lados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Havia um portão para dentro do pátio do lado sul e o homem mediu desse portão até o portão da entrada sul, cem côvados de distância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Então, o homem me levou para dentro do pátio no caminho do portão do sul, que tinha a mesma medida dos outros portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Suas câmaras, seus pilares e pórticos, tinham as mesmas medidas de outros portões; havia janelas ao redor do pórtico; que mediam cinquenta côvados de comprimento e vinte cinco de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Havia também pórticos ao redor da parede interior; estes mediam vinte e cinco côvados de comprimento e cinco de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Este pórtico ficava de frente para o pátio externo, com palmeiras esculpidas em suas paredes, oito degraus subiam até ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Depois, o me homem levou ao pátio interior pelo caminho oriental e mediu o portão, que tinha a mesma medida dos anteriores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Seus portões, pilares e pórtico também tinham a mesma medida dos outros portões e havia janelas ao seu redor. O portão interior e seu pórtico mediam cinquenta côvados de comprimento e vinte e cinco de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Seu pórtico ficava de frente para o pátio externo e tinha palmeiras em ambos lados e oito degraus subindo até ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Em seguida, o homem me levou ao portão norte, e o mediu, como também os outros portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Suas câmaras, seus pilares e seu pórtico mediam o mesmo que os outros portões e havia janelas ao redor. A entrada e seu pórtico mediam cinquenta côvados de comprimento, e vinte e cinco de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Seu pórtico ficava de frente ao pátio externo e tinha palmeiras em ambos lados e oito degraus subindo até ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Havia uma câmara com uma porta para cada entrada interna, onde eles lavavam os holocaustos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Havia duas mesas, em ambos lados de cada pórtico, nas quais o holocausto era imolado e era realizada a oferta pela culpa e pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Ao lado da entrada do átrio, subindo para o portão do norte, havia duas mesas. Também do outro lado, havia duas mesas no pórtico do portão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Havia quatro mesas em ambos os lados, perto da portão; eles imolavam animais em oito mesas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Havia quatro mesas de pedra lavrada para os holocaustos, com um côvado e meio de comprimento, um côvado e meio de largura e um côvado de altura. Nelas, eles colocavam os instrumentos, com os quais imolavam os sacrifícios para o holocausto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Ganchos de duas pontas de um palmo de comprimento, pendurados por dentro em toda a volta; e a carne dos sacrifícios estava sobre as mesas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Perto do portão interior, no pátio interno, estavam as câmaras dos cantores. Uma dessas câmaras estava do lado norte e uma do lado sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Então, o homem me disse: \"Esta sala de frente para o sul é para os sacerdotes que estão a serviço do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'A sala de frente para o norte é para os sacerdotes a serviço do altar. Estes são os filhos de Zadoque, que dentre os levitas, se aproximaram de Yahweh, para O servirem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Em seguida, ele mediu o pátio, com cem côvados de comprimento e cem de largura; era quadrado, com um altar em frente do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Depois, o homem me levou ao pórtico do templo e mediu os batentes dos portões, que tinham cinco côvados de espessura nos dois lados. Sua entrada tinha três côvados de um lado e três côvados do outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'O comprimento do pórtico era de vinte côvados e sua profundidade era de onze côvados. Havia degraus que subiam até ele e colunas erguidas de um lado e do outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Depois disso, o homem me levou para o lugar santo do templo e mediu os pilares das portas, seis côvados de largura para cada lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'A largura do corredor da entrada era de dez côvados; a parede de cada lado era de cinco côvados de comprimento. Então, o homem mediu as dimensões do santo lugar — quarenta côvados de comprimento e vinte côvados de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Então, o homem entrou no lugar santo e mediu os pilares da entrada: dois côvados e a entrada era de seis côvados de largura; e a parede media sete côvados de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Então, ele mediu o comprimento dos quartos — vinte côvados; e a sua largura — vinte côvados para a frente do muro do templo. Daí, ele me disse: \"Este é o Lugar Santíssimo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Então, o homem mediu a parede do templo, que tinha seis côvados de espessura e a largura de cada lado dos quartos, em volta do templo, era de quatro côvados de comprimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'As salas laterais estavam em três níveis, uma sala por cima da outra, e trinta salas em cada andar. Havia camadas em volta da parede do templo para apoiar todos os lados, porque não haviam sido colocados suportes na parede da casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'As câmaras laterais aumentavam em largura, de andar para andar, de andar em andar ao redor e para cima. Assim, subia do andar inferior até o superior, passando pelo nível do meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Então, vi uma parte elevada em volta do templo, as fundações das salas laterais, que mediam a espessura de seis côvados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'A largura externa da parede das salas laterais, era de cinco côvados. Havia um espaço aberto do outro lado desta sala, no templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'E as salas mediam vinte côvados de largura, por todo o redor do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Havia portas nos lados das entradas das salas laterais para uma área aberta, para o lado norte havia uma porta e outra para o lado do sul. A largura desta área aberta era de cinco côvados ao redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'O edifício que estava separado, do lado ocidental, tinha setenta côvados de largura. A sua parede media cinco côvados de espessura em todo redor e noventa côvados de comprimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Assim, o templo media de cem côvados de comprimento. Os edifícios separados, suas paredes e o pátio mediam cem côvados de comprimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'A largura da frente oriental do templo, também era de cem côvados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Então, o homem mediu o comprimento do edifício por trás do templo, ao oriente, com suas galerias da cada lado; mediam cem côvados. O templo e o pórtico do átrio,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'as paredes interiores e janelas e as galerias ao redor, eram em três níveis, amadeiradas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Acima da porta, para o interior do templo e o espaço ao longo das paredes, tinham uma medida pré-determinada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Estava decorado de querubins e palmeiras; e havia uma palmeira entre cada querubim, e cada querubim tinha duas faces;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'a face humana era voltada para a palmeira de um lado, e a face de leão, voltada para a palmeira do outro lado. Era assim em toda a volta do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Desde o chão até em cima da entrada, os querubins e as palmeiras, estavam posicionados no exterior da parede do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Os pilares do templo eram quadrados. Sua aparência, era semelhante a de');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'um altar de madeira em frente do templo, que tinha três côvados de altura, e dois côvados de comprimento de cada lado. Seus cantos, sua base, e suas paredes eram feitas de madeira. Então, o homem me disse: \"Esta é a mesa que fica diante de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Havia portas duplas, para o templo e para o Santíssimo Lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Essas portas tinham dois painéis dobráveis cada, dois painéis para uma porta e dois painéis para a segunda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Esculpidas nelas, nas portas do templo, havia querubins e palmeiras, assim como era a decoração das paredes e havia uma cobertura de madeira, na parte de fora do pórtico da entrada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Havia janelas estreitas e palmeiras de cada lado do pórtico, e nos cômodos laterais do templo, como também nas suas soleiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Em seguida, o homem me levou para o exterior do pátio, no lado norte, para as salas, em frente ao exterior do pátio, que dá para o norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Aquelas salas mediam cem côvados em frente e cinquenta côvados de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Algumas delas se pocisionavam no interior do pátio e se distanciavam vinte côvados do templo. Havia três níveis de salas e as que estavão por cima direcionavam-se às de baixo e estavão abertas para elas, mas tendo uma passagem. Algumas das salas tinham vista para o pátio exterior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'A passagem era de dez côvados de largura e cem côvados de comprimento do corredor, em frente das salas. As portas das salas pocisionavam-se para o norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Mas as salas de cima eram pequenas, porque os corredores tomavam muito espaço, mais que o espaço ocupado pelos corredores das salas de baixo e do meio do edifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Porque as salas do terceiro andar não tinham colunas, como as do pátio, que tinham as colunas. Então, as salas do nível mais alto era pequena, em comparação, as salas do nível de baixo e do meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'O muro de fora subiu ao longo das salas, em direção ao exterior do pátio. Aquele muro tinha cinquenta côvados de comprimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'E o comprimento das salas, no exterior do pátio, era de cinquenta côvados e as salas direcionadas ao santuário mediam cem côvados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Havia uma entrada para as salas de baixo, no lado oriental, vindo do exterior do pátio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Ao longo do muro do pátio exterior, no lado oriental, em frente ao pátio interior do templo, havia também salas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'com uma passagem na frente delas. Eram da mesma aparência das salas do lado norte, tinham o mesmo comprimento e largura, as mesmas saídas, mesmos os arranjos e portas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'No lado sul, havia portas nas salas, que eram semelhantes às do lado norte. Uma passagem no interior, tinha uma porta acima dela e a passagem abria para várias salas. No lado oriental, havia uma entrada na passagem numa extremidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Então, o homem me disse: \"As salas do norte e as salas do sul, que estão na frente do pátio exterior, são as salas sagradas, onde os sacerdotes que se aproximam de Yahweh comerão a comida santa. Lá colocarão as coisas santíssimas; a oferta de cereais, a oferta pelo pecado e a oferta pela culpa, pois este é um lugar sagrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Quando os sacerdotes entrarem, eles não sairão do lugar sagrado para a pátio exterior, sem deixarem ali as roupas com as quais ministram, uma vez que elas são sagradas, e vestirão outras roupas antes de se aproximarem do povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'O homem completou a medição da casa interior e, em seguida, levou-me para o portão que dá para o oriente e mediu a área ao redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Ele mediu o lado oriental, com uma vara de medição, quinhentos côvados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Ele mediu o lado norte, quinhentos côvados, mediu com a vara de medição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Ele também mediu o lado sul, quinhentos côvados, mediu com a vara de medição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Ele também virou e mediu o lado ocidental, quinhentos côvado, com a vara de medição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Ele mediu os quatro lados. Havia uma parede em torno dela, que media quinhentos côvados de comprimento e quinhentos côvados de largura, para fazer separação entre o sagrado e o profano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Então, o homem veio e me levou à porta que está aberta para o oriente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Eis que, a glória do Deus de Israel vinha do oriente; Sua voz era como o som de muitas aguás, e a terra brilhava por causa da Sua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'E pareceu com a visão que tive, quando vi o homem que veio para destruir a cidade e as visões eram como a visão que tive no rio Quebar e caí com o rosto em terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'E a glória de Yahweh veio ao templo pelo caminho da porta que abre para o oriente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Então, o Espírito me levantou e me levou até o pátio interno. Eis que a glória de Yahweh encheu o templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'O homem estava parado ao meu lado e ouvi alguém falando comigo dentro do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'E me disse: \"Filho do homem, esta é a casa do Meu trono e da sola dos Meus pés, onde viverei no meio do Meu povo Israel para sempre. A casa de Israel não profanará mais o Meu nome, nem eles e nem seus reis, com suas infidelidades ou com os cadáveres dos seus reis nos seus lugares altos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Não profanarão mais o Meu santo nome pondo o seu limiar perto do Meu limiar e seu umbral perto do Meu umbral, havendo apenas uma parede entre Eu e eles. Eles profanaram o Meu santo nome com atos desagradáveis e por isso os consumi na Minha ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Agora, que eles removam para longe de Mim as suas infidelidades e os cadáveres dos seus reis; e Eu viverei no meio deles para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Filho do homem, diz à casa de Israel acerca deste templo para que se envergonhem das suas iniquidades; eles deveriam pensar acerca deste relato.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Pois se eles estão envergonhados de tudo que fizeram, então, revela-lhes o desenho do templo, seus detalhes, suas saídas, suas entradas e todos seus decretos e suas leis. Escreve isto, diante de seus olhos, para que guardem todos os aspectos e todas as leis e as obedeçam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Esta é a lei do templo: Do pico do monte à sua borda ao redor, será santíssimo. Eis que esta é a lei do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Estas serão as medidas do altar em côvados, este será um côvado regular, a largura de um palmo de comprimento. E a parte inferior ao redor do altar será um côvado profundo e sua largura será também de um côvado. A borda em todo seu contorno será de um palmo; e esta será a base do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Da parte inferior do nível elevado, para base mais baixa do altar são dois côvados e esta base é um côvado de largura. Então, da pequena base até a base larga do altar, são quatro côvados e a base larga é um côvado de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'A lareira do altar para queimar ofertas será da altura de quatro côvados e haverá quatro chifres apontando para cima da lareira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'A lareira é de doze côvados de comprimento e doze côvados quadrados de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Sua àrea é de catorze côvados de comprimento e catorze côvados de largura cada um dos quatro lados, e seu aro é a metade da largura. A lareira é um côvado de largura ao redor, com seus degraus virados para o oriente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Depois, ele me disse: \"Filho do homem, assim diz Yahweh Deus: Estas são as instruções do altar no dia em que eles o fizerem, para oferecerem a oferta queimada em cima dele e para espalharem sangue sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Darás um bezerro por oferta pelo pecado aos sacerdotes levitas que são da descendência de Zadoque, que se chegam a Mim para Me servirem — esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Então, levarás do seu sangue e o porás nos quatro chifres do altar, nos quatro lados à sua margem e no contorno ao redor; o purificarás e farás a sua expiação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Então, levarás o bezerro de oferta pelo pecado e queima no lugar indicado no templo, do lado de fora do santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Então, no segundo dia, oferecerás um bode macho sem mancha, os bodes serão ofertas pelo pecado; os sacerdotes purificarão o altar como purificaram o bode.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Quando terminarem a purificação, oferecerão um gado sem defeito do rebanho, e um carneiro sem mancha do rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'E os oferecerão perante Yahweh; os sacerdotes deitarão sal neles e os oferecerão como oferta queimada a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Prepara um bode macho como oferta pelo pecado todos os dias, durante sete dias, e os sacerdotes também prepararão um bezerro e um carneiro do rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Eles expiarão o altar por sete dias e o purificarão e, deste modo, irão consagrá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Eles devem cumprir esses dias e, do oitavo dia em diante, os sacerdotes prepararão as vossas ofertas queimadas e as vossas ofertas pacíficas sobre o altar, e Eu vos aceitarei — esta é a declaração de Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Então, o homem me levou de volta para a porta do exterior do santuário, que dá para o oriente a qual estava fechada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'E disse-me Yahweh: \"Esta porta foi fechada; não será aberta. Ninguém entrará por ela, porque Yahweh, o Deus de Israel, entrou por ela, por isso estará bem fechada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'O rei de Israel se sentará ali para comer perante Yahweh; ele entrará pelo caminho do pórtico, e sairá pelo mesmo caminho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Depois, ele me levou pelo caminho da porta do norte que olha para o templo. Olhei e eis que a glória de Yahweh encheu o templo de Yahweh e caí com meu rosto em terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Então, Yahweh me disse: \"Filho do homem, pondera em teu coração; vê, com teus olhos, e ouve, com teus ouvidos, tudo que Eu estou declarando a ti, todos os estatutos do templo de Yahweh e todas as leis; considera as entradas e as saídas do santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'E dize aos rebeldes, da casa de Israel, \'assim diz Yahweh Deus: Que sejam suficientes para ti, todas as vossas ações abomináveis, ó casa de Israel —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'trouxestes estranhos com coração incircunciso, e carne incircuncisa para estarem no Meu santuário, profanando a Minha casa, quando Me oferecestes comida, gordura e sangue — quebrastes a Minha aliança com todas as vossas ações abomináveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Tu não cumpriste tuas tarefas, considerando as Minhas coisas santas, mas nomeaste os outros para o fazer, e os designaste para cuidar do Meu santo lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Assim diz Yahweh Deus: Nenhum estranho, incircunciso de coração e incircunciso de carne, de todos aqueles que vivem no meio de Israel, entrarão no lugar santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Mas os levitas que foram para longe e se desviaram para longe de Mim, indo para os seus ídolos, eles pagarão pelos seus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Entretanto, eles serão servos no Meu santuário, vigiando as portas da casa e servindo nela. E eles imolarão as ofertas queimadas e sacrificarão ao povo, e estarão diante dele para lhes servir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'E, porque eles ofereceram os sacrifícios diante dos seus ídolos e serviram de pedra de tropeço e de pecado para casa de Israel, por isso, Eu levantarei a Minha mão para prestar um juramento contra eles — esta é a palavra de Yahweh Deus — eles terão sua punição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Eles não virão a Mim como Meus sacerdotes, nem se aproximarão das Minhas coisas santas, nem das coisas santíssimas; pelo contrário, eles sofrerão a sua repreensão e a culpa das ações abomináveis que fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Mas os colocarei como guardas do trabalho na casa, por todos os seus direitos e todas as coisas que nela são feitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Então, os sacerdotes levitas, os filhos de Zadoque que cumpriram os deveres do Meu santuário quando o povo de Israel estava longe de Mim, eles virão a Mim para Me adorarem. Eles virão diante de Mim para Me oferecerem gordura e sangue — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Eles virão ao Meu santuário; se aproximarão da Minha mesa para Me adorarem e cumprirem os seus deveres para comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Quando vierem pelas portas do átrio interior, terão que se vestir de roupas de linho e não virão de lã, dentro das portas no interior do pátio e do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Devem estar de touca de linho nas suas cabeças e linho nas roupas de baixo, até as suas coxas. Eles não deverão vestir roupas que os fazem suar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Quando saírem para o exterior do pátio, para o outro pátio do exterior para ir ao povo, deverão tirar as roupas que vestiram quando serviam; e as deixar nas câmaras santas, para que não santifiquem outras pessoas pelo contato das suas roupas sagradas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'E não raparão as suas cabeças, nem deixarão os seus cabelos soltos, mas deverão arrumar os cabelos das suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Nenhum sacerdote deve beber o vinho, quando vier para dentro do pátio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Nem devem casar com mulheres viúvas ou divorciadas e tomá-las como esposa, mas só as virgens da linhagem da casa de Israel ou as viúvas que foram anteriormente casadas com um sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Portanto, eles ensinarão o Meu povo a diferença entre o santo e o profano; eles os farão saber entre o impuro e o puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Em caso de disputa, eles se levantarão para julgar com os Meus decretos; eles deverão ser justos. Guardarão a Minha lei e os Meus estatutos em todas as festas e celebrarão os Meus santos sábados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Eles não irão onde estiver um morto para que não se contaminem, a não ser seus pais ou suas mães, filho ou filha, irmão ou irmã, que não se casaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Depois de o sacerdote se purificar, contará um periodo de sete dias para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'No dia em que ele entrar no lugar santo, dentro do pátio interior para servir no lugar santo, trará ofertas pelo seu pecado — esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Esta será a sua herança: Eu sou a sua herança e não devais dar propriedade a eles em Israel; Eu serei a propriedade deles!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Eles comerão das ofertas, ofertas pelo pecado, ofertas pela culpa e toda coisa dedicada a Yahweh em Israel será deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'O melhor de todos os primeiros frutos de toda espécie e de toda oferta, tudo isso será dos sacerdotes, também dareis o melhor da vossa farinha, para que repouse a bênção sobre vossa casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Os sacerdotes não comerão carcaça ou animal dilacerado, seja ave ou fera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Quando usardes sortes para dividir a terra como herança, fareis uma oferta para Yahweh; esta oferta será uma santa porção da terra, vinte e cinco mil côvados de comprimento e dez mil côvados de largura. Será santo todo este lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'A partir disso, será quinhentos côvados por quinhentos côvados quadrado rodeando o lugar santo, com cinquenta côvados de largura da borda ao redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'A partir deste lugar santo, medireis uma porção de vinte e cinco mil côvados de comprimento e dez mil de largura; ali será o santuário, o lugar santíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Será o lugar santo na terra para os sacerdotes que servem a Yahweh, que se aproximam de Yahweh para servi-Lo; servirá de lugar para suas casas e lugar santo para o santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Terão vinte cinco mil côvados de comprimento e dez mil de largura e serão as cidades dos levitas que ministram no templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Vós designareis uma área para cidade, cinco mil côvados de largura e vinte cinco mil de comprimento, será próximo da porção reservada para o santuário; esta cidade pertencerá a toda a casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'A terra do príncipe será nos dois lados da área reservada para o santuário e cidade, estarão no seu ocidente e no seu oriente. O comprimento corresponderá ao comprimento de uma das porções, do ocidente para o oriente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Esta terra será de propriedade do príncipe em Israel; Meus príncipes nunca mais oprimirão Meu povo; ao invés disso, eles darão esta terra à casa de Israel, por suas tribos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Assim diz Yahweh Deus: Basta, príncipes de Israel! Removei a violência e a opressão; fazei justiça e juízo! Parai com a opressão sobre Meu povo — esta é a declaração de Yahweh Deus —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Tereis balanças precisas, o efa justo e o bato justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'O efa e o bato serão da mesma quantidade, para que o bato seja a décima parte do ômer; o efa será a décima parte do ômer, as suas quantidades serão correspondentes ao ômer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'O siclo será de vinte geras; sessenta siclos serão uma mina para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Esta é a contribuição que ireis apresentar: a sexta parte do efa para cada ômer de trigo e dareis a sexta parte de um efa de cada cevada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'As leis da oferta do azeite serão a décima parte do bato de cada coro (que são dez batos), ou para cada ômer, visto que o ômer também é de dez batos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Uma ovelha ou cabrito de cada rebanho de duzentos animais das regiões mais regadas de Israel será usado para oferta queimada ou oferta pacífica para fazer expiação pelo povo — esta é a declaração de Yahweh Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Todo povo da terra dará esta oferta para o príncipe de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Será a responsabilidade do príncipe dar os animais para ofertas queimadas, ofertas de manjares, ofertas de libações nas festas e celebrações de lua nova, nos dias de sábado e em todas as festas marcadas da casa de Israel. Ele fará ofertas pelo pecado, ofertas de manjares, ofertas queimadas e ofertas pacíficas para fazer expiação pela casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Assim diz Yahweh Deus: No primeiro mês, no primeiro dia do mês, levarás um bezerro sem mancha do rebanho e o ofercerás pelo pecado no santuário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'O sacerdote levará do sangue da oferta pelo pecado e porá nas ombreiras da casa e nos quatro cantos da listra do altar e nas ombreiras da porta do átrio interior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Farás isto no sétimo dia do mês pelo pecado de cada um, por acidente ou ignorância; assim, expiarás o templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'No primeiro mês, no décimo quarto dia do mês, haverá festa, uma festa de sete dias; comereis pão sem fermento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Neste dia, o príncipe preparará, para ele mesmo e para todo povo da terra, um bezerro como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'E, nos sete dias da festa, o príncipe preparará oferta queimada para Yahweh: sete bezerros e sete carneiros sem mancha, cada dia, por sete dias e um bode cada dia como oferta pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Então, o príncipe preparará oferta de manjares do efa para cada bezerro e efa para cada carneiro e um him de azeite para cada efa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'No sétimo mês, no décimo quinto dia do mês, na festa, o príncipe oferecerá nestes sete dias: ofertas pelo pecado, ofertas queimadas, ofertas de manjares e ofertas de azeite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Assim diz Yahweh Deus: \"A porta do átrio interno virado para o oriente será fechada por seis dias de trabalho, mas, no sábado, será aberta e também no dia de lua nova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'O príncipe entrará no átrio de fora pelo caminho da porta, pela entrada de fora e parará diante da ombreira da porta do interior, enquanto os sacerdotes oferecem sua oferta queimada e a oferta pacífica. Então, ele adorará no umbral da porta interior, e sairá, mas a porta não será fechada até o anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'E o povo da terra também adorará diante de Yahweh na entrada desta porta aos sábados e luas novas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'As ofertas queimadas, que os príncipes oferecem a Yahweh no dia de sábado, serão seis cordeiros sem mancha e um carneiro sem mancha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'A oferta de manjares com o carneiro será um efa e a oferta de manjares com cordeiro será o que quiser dar e um him de azeite com cada efa de trigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'No dia de lua nova, deve oferecer um bezerro sem mancha do rebanho, seis cordeiros e um carneiro sem mancha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Ele deve fazer oferta de manjares de um efa pelo bezerro e um efa pelo carneiro e o que quiser dar pelo cordeiro e um him de azeite por cada efa de trigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Quando o príncipe entrar pelo caminho da porta e por seu pórtico, ele deve sair pelo mesmo caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Mas, quando o povo da terra vier diante de Yahweh nas festas marcadas, aquele que entrar na porta do norte para adorar deve sair pela porta do sul; aquele que entrar pela porta do sul deve sair pela porta do norte. Ninguém deverá voltar pela porta que entrou, pois deverá sair pela porta que está em frente dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'O príncipe deve estar no meio deles; quando entrarem, ele deve entrar e, quando saírem, ele deve deve sair.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Nas festas, a oferta de manjares deve ser um efa de trigo pelo bezerro e um efa pelo carneiro e tudo que quiser dar juntamente com os cordeiros; um him de azeite por cada efa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Quando o príncipe fizer oferta voluntária ou oferta queimada ou oferta pacífica para Yahweh, a porta virada ao oriente será aberta para ele. Ele oferecerá suas ofertas queimadas ou suas ofertas pacíficas, como faz no dia de sábado. Então, sairá e, depois de ter saído, a porta será fechada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Além disso, darás um cordeiro sem mancha de um ano como oferta queimada para Yahweh, todos os dias; e farás isso todas manhãs.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Juntamente com ele, darás ofertas de manjares todas as manhãs, a sexta parte de um efa e um terço de um him de azeite para misturar com a oferta de flor de farinha para Yahweh, em estatuto permanente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Eles prepararão o cordeiro, a oferta de manjares e o azeite todas manhãs, uma oferta queimada permanente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Assim diz Yahweh Deus: \'Se o príncipe der um presente a algum dos seus filhos, esta é sua herança. Esta será a propriedade dos seus filhos, é uma herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Mas, se der um presente de sua herança a um dos seus servos, então, isso será seu até o ano da liberdade e, depois, será devolvido ao príncipe. Sua herança será certamente para seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'O príncipe não tomará a herança do povo, da sua própria possessão; ele deve dar a seus filhos sua própria possessão, para que o Meu povo não seja espalhado cada homem da sua possessão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Depois, o homem me trouxe pela entrada da porta para o lugar das câmaras santas dos sacerdotes, que olhavam para o norte, e eis que havia um lugar para o lado do ocidente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'E ele me disse: “Este é o lugar onde os sacerdotes cozerão a oferta pela culpa e a oferta pelo pecado, e onde cozerão a oferta de manjares. Eles não trarão as ofertas ao átrio exterior, pois assim o povo será consagrado”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Então, ele me trouxe para o átrio exterior e me fez passar às quatro esquinas do átrio e vi que, em todas as esquinas do átrio, havia outro átrio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Nas quatro esquinas do átrio exterior, havia quatro átrios pequenos, quarenta cúbitos de comprimento e trinta de largura, todos os quatro átrios tinham as mesmas dimensões');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Havia uma parede feita de pedra ao redor de todos os quatro e uma cozinha abaixo da parede feita de pedra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'E o homem me disse: \"Estes são os lugares onde os servos do templo cozinharão os sacrifícios do povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Depois, o homem me levou de volta à entrada do templo e havia água que saía por baixo do limiar do templo, em direção ao oriente, pois a face do templo estava voltada para o oriente e as águas saíam do lado sul do templo, pela direita do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Então, levou-me para fora pelo portão norte e me fez dar uma volta para a porta do oriente, ali as águas corriam para o lado sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Saiu o homem para o lado do oriente, tinha uma linha de medir em sua mão; e mediu mil côvados e me fez passar pelas águas e as águas davam na altura dos tornozelos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Novamente, ele mediu mil côvados e me atravessou, as águas davam na altura dos joelhos; outra vez, mediu mil côvados e as águas na altura da cintura; as águas eram profundas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Em seguida, mediu ainda outros mil côvados, mas já era um rio que não se podia atravessar a nado, porque as águas já eram muito profundas e não se podia atravessar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Então, ele me perguntou: \"Viste isso, filho do homem?\". E me levou para fora e me fez voltar à margem do rio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Enquanto voltava pela margem do rio, vi muitas árvores, de um lado e do outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'O homem me disse: \"Estas águas estão indo para o oriente, descendo para Arabá; e entram no mar Morto, cujas aguás se tornarão saudáveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'E será que por onde este rio passar toda criatura viverá e haverá muitos peixes, e, quando estas águas chegarem, elas tornarão as águas salgadas em águas saudáveis; e tudo viverá por onde o rio passar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Então, acontecerá que os pescadores de En-Gedi permanecerão nas águas e haverá lugar para estender as redes de pesca em En-Eglaim. Haverá uma grande variedade de peixes no mar Morto, como os peixes do mas Grande que serão em abundância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Mas os pântanos e os charcos do mar salgado não serão renovados; serão para prover o sal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Junto desse rio, à sua margem, em ambos os lados, crescerão todos os tipos de árvores que dão frutos para alimento. Suas folhas não murcharão e seus frutos não deixarão de crescer. Em cada mês, as árvores darão seus frutos, porque suas águas saem do santuário. Seus frutos servirão de alimento e suas folhas servirão de cura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Assim diz Yahweh Deus: Este será o limite que dividirás para a terra das doze tribos de Israel: José terá duas partes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Vós dividireis por igual aquilo que Eu edifiquei pela Minhas mãos e jurei dar a vossos pais. Esta terra vos será por herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Este será o limite da terra: para o norte, desde o mar Grande, pelo caminho de Hetlom, e depois até Zedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Então, o limite irá de Berota para Sibraim, que está entre Damasco e Hamate e depois para Hazer-Haticom, que fica ao lado do limite de Haurã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Assim, o limite partirá do mar para Hazar-Enom, na fronteira com Damasco e Hamate para o norte. Este será o limite do lado norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'No lado oriental, entre Haurã e Damasco, e entre Gileade e a terra de Israel, será o rio Jordão. Tu medirás desde o limite até o mar oriental; tudo isso será o limite do oriente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'E o limite do lado sul: o sul de Tamar para as águas de Meribote-Cades, ao longo do ribeiro do Egito para o Grande Mar, este será o limite do lado sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'E o limite do ocidente estará o Grande Mar, onde vai em direção oposta a Hamate. Este será o limite do lado ocidental.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Assim, repartireis esta terra entre vós e para as tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Vós a repartireis em herança, entre vós e entre os estrangeiros que vivem em vosso meio, aqueles que tiveram filhos entre vós, e que são como povo nativo entre os filhos de Israel. Terão herança convosco, entre as tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Então, na tribo onde o estrangeiro habitar, ali dareis a sua herança — esta é a declaração de Yahweh Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Estes são os nomes das tribos: a tribo de Dã receberá uma porção da terra; sua fronteira vai ao longo do norte da fronteira de Israel pelo caminho de Hetlom e Lebo-Hamate. Sua fronteira vai desde Hazar-Enom, ao longo do limite com Damasco ao norte e até Hamate. A fronteira de Dã será desde o lado leste a todo caminho do Grande Mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'E, junto ao limite de Dã, desde o leste até ao lado oeste, Aser terá uma porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'E, junto ao limite de Aser, desde o lado leste para o lado oeste, Naftali terá uma porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'E, junto ao limite de Naftali desde o leste para o lado oeste, Manassés terá um porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'E, junto ao limite de Manassés desde o lado leste para o oeste, Efraim terá uma porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'E, junto ao limite de Efraim desde o lado leste para o o este, Rúben terá uma porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'E, junto do limite de Rúben desde o lado leste para o oeste, Judá terá uma porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'A oferta da terra que fizeres será ao longo do limite com Judá, que se estende do lado leste para o oeste; e será de vinte e cinco mil côvados de largura. Seu comprimento corresponde a uma porção de tribo, desde o lado leste até o lado oeste, e o templo estará no meio dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Esta é terra que oferecerás a Yahweh; será de vinte e cinco mil côvados de comprimento e dez mil côvados de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Estas serão as tarefas das atribuições da porção santa da terra: os sacerdotes terão terras separadas para eles, medindo vinte e cinco mil côvados de comprimento para o lado do norte; dez mil côvados de largura para o lado oeste; dez mil côvados de largura para o lado leste; vinte e cinco mil côvados de comprimento para o lado sul, com o lugar santo de Yahweh no meio dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Isto será para a consagração dos sacerdotes da linhagem de Zadoque, que têm Me servido fielmente e não se desviaram quando o povo de Israel se desviou, como os levitas também fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'A oferta para eles será a porção desta santíssima terra, estendendo-se ao limite dos levitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'A terra dos levitas, ao longo do limite da terra, dos sacerdotes será de vinte e cinco mil côvados de comprimento e dez mil côvados de largura. Todo o comprimento das duas extensões de terra será de vinte e cinco mil côvados de comprimento e vinte mil côvados de largura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'E eles não a venderão nem a trocarão; nenhuma destas primícias da terra de Israel podem ser transferidas a outros, pois tudo isto é santidade a Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'A terra restante, cinco mil côvados de largura e vinte e cinco mil côvados de comprimento, será para o uso comum da cidade, das casas e das pastagens; a cidade estará no meio dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Estas serão as medidas da cidade: o lado do norte terá quatro mil e quinhentos côvados de comprimento; o lado do sul terá quatro mil e quinhentos côvados de comprimento; o lado do leste terá quatro mil e quinhentos côvados de comprimento; e o lado do oeste terá quatro mil e quinhentos côvados de comprimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Haverá pastagem para a cidade, duzentos e cinquenta côvados em direção ao norte, duzentos e cinquenta côvados em direção ao sul, duzentos e cinquenta côvados em direção ao leste e duzentos e cinquenta côvados em direção ao oeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'E, quanto à área restante da oferta santa, ela terá dez mil côvados para o leste e dez mil côvados para o oeste. Ela se estenderá ao longo do limite da santa oferta e esta produzirá alimentos para todos que trabalham na cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'O povo que serve na cidade, dentre todas as tribos de Israel, cultivará aquela terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Todas as terras oferecidas medirão vinte e cinco mil côvados por vinte e cinco mil côvados. Desse modo, farás uma oferta santa da terra, juntamente com a terra da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'O resto da terra, em cada lado da oferta santa e da área da cidade, será para o príncipe. O trecho da terra do príncipe do lado leste terá vinte e cinco mil côvados, desde do limite da oferta santa para o leste e o trecho do oeste será de vinte e cinco mil côvados para o limite do oeste. A oferta santa e o santuário do templo estarão no meio dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'A terra que se estende da propriedade dos levitas e a área do meio da cidade será para o príncipe; estará entre o limite de Judá e o limite de Benjamim, essa terra será para o príncipe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'E, quanto ao resto das tribos, as suas porções tambem irão do lado do leste para o lado oeste. Benjamim receberá uma porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'E, junto do limite de Benjamim desde o lado leste para o oeste, Simeão terá uma porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Junto do limite de Simeão desde o lado leste para o oeste, Issacar terá uma porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'E, junto do limite de Issacar desde o lado leste para o lado oeste, Zebulom terá uma porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Ao sul do limite de Zebulom, do lado leste para o lado oeste, a tribo de Gade terá uma porção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'O limite sul de Gade se estenderá desde Tamar até as águas de Meribá de Cades, para ao lado do ribeiro de Egito e até ao mar Grande.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Essa é a terra a qual lançareis sortes e será a herança das tribos de Israel. Estas serão as suas porções. Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'E estas são as saídas da cidade: do lado norte a medida terá quatro mil e quinhentos côvados de comprimento,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'serão três portas com os nomes das tribos de Israel: uma porta de Rúben, uma porta de Judá, uma porta de Levi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Do lado leste, a medida terá quatro mil e quinhentos côvados de comprimento, serão três portas: uma porta de José, uma porta de Benjamim e uma porta de Dã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'No lado leste, a medida será de quatro mil e quinhentos côvados de comprimento e serão três portas: uma porta de Simeão, uma porta de Issacar e uma porta de Zebulom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Do lado oeste, a medida será de quatro mil e quinhento côvados e serão três portas: uma porta de Gade, uma porta de Aser e uma porta de Naftali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'A distância ao redor da cidade será de dezoito mil côvados; desde aquele dia, o nome da cidade será chamado \"Yahweh está ali\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'No terceiro ano do reinado de Jeoaquim, rei de Judá, Nabucodonosor, rei da Babilônia, veio a Jerusalém e sitiou a cidade para lhe cortar o abastecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'O Senhor deu a Nabucodonosor vitória sobre Jeoaquim, rei de Judá, e lhe deu alguns dos objetos sagrados da casa de Deus. Ele os trouxe para a terra da Babilônia, para a casa do seu deus, e colocou os objetos sagrados na casa do tesouro do seu deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'O rei falou a Aspenaz, seu oficial chefe, para trazer alguns do povo de Israel, tanto da família real como da nobreza;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'jovens sem defeito, de boa aparência, habilitados em toda sabedoria, cheios de conhecimento e entendimento e qualificados para servir no palácio do rei. Ele deveria ensiná-los sobre a literatura e a língua babilônica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'O rei separou para eles uma porção diária de suas iguarias e do vinho que ele bebia. Esses jovens deveriam ser treinados por três anos e, depois disso, serviriam ao rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Entre eles, estavam Daniel, Hananias, Misael e Azarias, vindos de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'O oficial chefe lhes deu outros nomes: a Daniel, o de Beltessazar; a Hananias, o de Sadraque; a Misael, o de Mesaque; e a Azarias, o de Abednego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Mas, Daniel resolveu não se contaminar com as finas iguarias do rei e com o vinho que ele bebia. Assim, ele pediu permissão ao oficial chefe para que não se contaminasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Então, Deus deu a Daniel favor e compaixão da parte do oficial chefe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'E ele disse a Daniel: \"Tenho medo do rei, meu senhor, pois ele ordenou quais iguarias e bebidas tu deverias comer e beber. Por que ele deveria ele te ver mais abatido que os outros jovens da tua idade? O rei poderia cortar minha cabeça por tua causa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Então, Daniel falou ao mordomo a quem o oficial chefe havia designado sobre ele, Hananias, Misael e Azarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Ele disse: \"Por favor, faz uma experiência conosco, teus servos, por dez dias. Dá-nos somente vegetais para comer e água para beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Então, compara nossa aparência com a aparência dos jovens que comem as iguarias do rei, e trata-nos, teus servos, baseado no que tu observares\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Assim, o mordomo concordou com Daniel em fazer isso e os testou por dez dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Ao fim dos dez dias, suas aparências estavam mais saudáveis, e eles estavam mais bem nutridos que todos os jovens que comeram das iguarias do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Dessa forma, o mordomo retirou as iguarias e seus vinhos e lhes deu apenas vegetais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Então, para esses quatro jovens, Deus deu conhecimento e discernimento em toda a literatura e sabedoria, e Daniel tinha discernimento sobre todos os tipos de visões e sonhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'No fim do período dado pelo rei, o oficial chefe os trouxe perante Nabucodonosor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'O rei conversou com eles e, entre todo o grupo, não havia ninguém comparável a Daniel, Hananias, Misael e Azarias. Eles permaneceram perante o rei, prontos para servi-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Em todas as questões de sabedoria e entendimento que o rei lhes perguntava, ele os achou dez vezes mais sábios que todos os magos e videntes que estavam em todo o seu reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Daniel permaneceu ali até o primeiro ano do rei Ciro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'No segundo ano do seu reinado, Nabucodonosor teve sonhos. Ele ficou com sua mente perturbada e não conseguiu dormir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Assim, o rei convocou os magos e os adivinhos, chamou os feiticeiros e sábios para lhes contar sobre os seus sonhos. Então, eles vieram e se apresentaram perante o rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'O rei lhes disse: \"Eu tive um sonho e minha mente está ansiosa para saber o seu significado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Então, os sábios falaram ao rei em aramaico: \"Ó Rei, vive para sempre! Conta o sonho para nós, os teus servos, e revelaremos o significado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'O rei respondeu aos sábios: \"Este assunto já está resolvido. Se vós não me revelardes o sonho e a sua interpretação, vossos corpos serão dilacerados e vossas casas serão transformadas em um monte de lixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Mas, se me contardes o sonho e o seu significado, vós recebereis de mim presentes, uma recompensa e grande honra. Então, dizei-me o sonho e o seu significado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Eles lhe pediram novamente: \"Rei, conta o sonho a nós, teus servos, e lhe diremos o seu significado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'O rei respondeu: \"Eu tenho certeza de que vós quereis mais tempo, porque sabeis da minha firme decisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Mas, se não me contardes o meu sonho, só há uma sentença para vós. Vós decidistes preparar palavras falsas e enganosas que, juntos, concordastes em dizer-me até que eu mude de ideia. Então, dizei-me o sonho e eu saberei que vós podeis interpretá-lo para mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Os sábios responderam ao rei: \"Não há nenhum homem na terra capaz de atender à exigência do rei. Não há rei grande e poderoso que tenha exigido uma coisa dessas de algum mago, ou de qualquer adivinho, ou de um sábio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'O que o rei exige é difícil e não há ninguém que possa dizer ao rei, exceto os deuses e eles não vivem entre os humanos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Isso fez o rei ficar irado e muito enfurecido, e ele deu ordens para destruir, na Babilônia, todos aqueles que eram conhecidos por sua sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Então, saiu um decreto dizendo que todos aqueles conhecidos por sua sabedoria seriam condenados à morte. Por causa desse decreto, eles procuraram Daniel e seus amigos para que fossem condenados à morte também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Então, Daniel respondeu com prudência e discrição para Arioque, o comandante do corpo da guarda do rei, que havia vindo matar todos aqueles que eram conhecidos na Babilônia por sua sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Daniel perguntou ao comandante do rei: \"Por que o decreto do rei é tão urgente?\". Então, Arioque disse a Daniel o que havia acontecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Daniel foi e solicitou uma audiência com o rei para que pudesse lhe apresentar a interpretação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Então, Daniel foi para sua casa e explicou a Hananias, Misael e Azarias o que havia acontecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Ele os exortou a buscarem a misericórdia do Deus do céu acerca deste mistério, para que eles não fossem mortos juntamente com os outros sábios da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Naquela noite, o mistério foi revelado a Daniel, numa visão. Então, Daniel louvou ao Deus do céu');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'e disse: \"Louvado seja o nome de Deus para todo o sempre, pois toda a sabedoria e todo poder pertencem a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Ele muda os tempos e as estações, Ele remove reis e coloca reis em seus tronos. Ele dá sabedoria ao sábio e conhecimento àqueles que têm entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Ele revela as coisas profundas e escondidas, porque Ele sabe o que está em trevas, e a luz vive com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Deus dos meus pais, eu te agradeço e te louvo pela sabedoria e por tudo o que me deste. Agora, Tu me fizeste saber o que te pedimos; Tu nos fizeste saber o assunto que concerne ao rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Então, Daniel foi ver Arioque (aquele que o rei designou para matar todos os sábios na Babilônia). Ele foi e lhe disse: \"Não mates os sábios na Babilônia. Leva-me ao rei e eu lhe mostrarei a interpretação do seu sonho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Rapidamente, Arioque trouxe Daniel à presença do rei e lhe disse: \"Encontrei, entre os exilados de Judá, um homem que vai revelar o significado do sonho do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'O rei disse a Daniel (que era chamado Beltessazar): \"Tu és capaz de me revelar o sonho que tive e o seu significado?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel respondeu: \"O mistério que o rei requer não pode ser revelado nem por aqueles que têm a sabedoria, nem pelos adivinhos, nem por mágicos ou por astrólogos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'No entanto, há um Deus que vive no céu, que revela os mistérios, e Ele te fez conhecer, rei Nabucodonosor, o que irá acontecer nos dias que virão. Estes foram os teus sonhos e as visões de tua mente, enquanto tu estavas deitado em tua cama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Quanto a ti, ó rei, teus pensamentos sobre tua cama eram sobre coisas futuras, e Aquele que revela segredos te fez saber o que está prestes a acontecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Quanto a mim, este mistério não me foi revelado por eu ter mais sabedoria que qualquer outra pessoa viva. Este segredo me foi revelado para que tu, rei, possas entender o significado e, assim, conhecer os pensamentos profundos dentro de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Rei, tu olhaste para cima e viste uma grande estátua. Essa estátua, que era muito poderosa e brilhante, estava diante de ti. Seu brilho era tremendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'A cabeça da estátua era feita de ouro fino. O peito e os braços eram feitos de prata. Seu ventre e coxas eram feitos de bronze,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'e suas pernas eram feitas de ferro. Seus pés eram, em parte, de ferro e, em parte, de barro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Tu olhavas para cima e uma pedra foi cortada, apesar de não ter sido por mãos humanas, e atingiu a estátua nos pés de ferro e argila, e os destruiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Então, o ferro, a argila, o bronze, a prata e o ouro foram quebrados em pedaços ao mesmo tempo, tornando-se como palha de eiras no verão. O vento os levou embora e não houve mais vestígios restantes deles. Mas a pedra que feriu a estátua se tornou uma grande montanha e encheu toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Esse foi o teu sonho. Agora diremos ao rei o seu significado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Tu, rei, és rei dos reis a quem o Deus dos céus tem dado o reino, o poder, a força e a honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'Ele tem dado, em tuas mãos, o lugar onde os seres humanos vivem. Ele tem dado todos os animais dos campos e os pássaros dos céus em tuas mãos, e tem feito de ti governante sobre todos eles. Tu és a cabeça de ouro da estátua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Depois de ti, outro reino inferior ao teu se levantará, e ainda um terceiro reino de bronze governará sobre toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Haverá um quarto reino, forte como o ferro, porque o ferro quebra outras coisas em pedaços, ele despedaça tudo. O reino despedaçará todas as coisas e as esmagará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Assim como tu viste que os pés e os dedos eram feitos, em parte, de barro e, em parte, de ferro, esse será um reino dividido; algumas das forças de ferro estarão nele, assim como viste uma mistura com barro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Como os dedos dos pés eram, em parte, feitos de ferro e, em parte, feitos de barro, da mesma forma o reino será, em parte, forte e, em parte, frágil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Assim como viste o ferro misturado com barro, as pessoas também serão uma mistura; elas não ficarão juntas, assim como o ferro não se mistura com o barro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Nos dias daqueles reis, o Deus do céu levantará um reino que nunca será destruído, nem mesmo será conquistado por outro povo. Ele quebrará os outros reinos em pedaços e porá um fim em todos eles, e permanecerá para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Assim como viste, uma pedra foi cortada da montanha, mas não por mãos humanas, e ela quebrou em pedaços o ferro, o bronze, o barro, a prata, e o ouro; o grande Deus te fez saber, rei, o que acontecerá depois disso. O sonho é verdadeiro e a interpretação é confiável\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'O rei Nabucodonosor caiu sobre sua face perante Daniel e o honrou; ele ordenou que uma oferta fosse feita e que incenso fosse oferecido a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'O rei disse a Daniel: \"Verdadeiramente teu Deus é o Deus dos deuses, o Senhor dos reis, e o único que revela segredos, pois fostes capaz de revelar esse mistério\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Então, o rei fez Daniel altamente honrado e deu a ele muitos presentes maravilhosos. Ele o fez governador sobre toda a província da Babilônia e também o fez governador chefe sobre todos os demais sábios da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'A pedido de Daniel, o rei nomeou Sadraque, Mesaque e Abednego administradores sobre toda a província da Babilônia. Mas Daniel permaneceu no palácio do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'O rei Nabucodonosor fez uma estátua de ouro que media sessenta côvados de altura e seis côvados de largura. Ele a levantou na planície de Dura, na província da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Então, Nabucodonosor enviou mensagens aos sátrapas, prefeitos, governadores, conselheiros, tesoureiros, juízes, magistrados e a todos os oficiais das províncias, para que viessem à dedicação da estátua que ele havia levantado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Então, os sátrapas, prefeitos, governadores, conselheiros, tesoureiros, juízes, magistrados e todos os oficiais das províncias se juntaram para a dedicação da estátua que o rei Nabucodonosor erguera. Todos estavam de pé diante da estátua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Então, o arauto clamou em alta voz: \"Ordena-se a todos os povos, nações e línguas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'que, ao ouvirem o som da trombeta, da flauta, da harpa, da cítara, do saltério, da gaita de foles e de todo tipo de música, se prostrem e adorem a estátua de ouro que o rei Nabucodonosor ergueu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Qualquer um que não se prostrar e não a adorar, será lançado na mesma hora numa fornalha de fogo ardente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Então, quando todos os povos ouviram os sons da trombeta, da flauta, da harpa, da cítara, do saltério, da gaita de foles e de todo tipo de música, todos os povos, nações e línguas se prostraram e adoraram a estátua de ouro que o rei Nabucodonosor levantara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Nessa hora, alguns caldeus vieram e fizeram acusações contra os judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Eles disseram ao rei Nabucodonosor: \"Ó rei, vive para sempre!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'O rei fez um decreto que toda pessoa que ouvisse os sons da trombeta, da flauta, da harpa, da cítara, do saltério, da gaita de fole e de todo tipo de música deveria prostrar-se e adorar a estátua de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Quem não se prostrasse e adorasse deveria ser lançado numa fornalha de fogo ardente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Há alguns judeus que designaste para os negócios da província da Babilônia — seus nomes são Sadraque, Mesaque e Abednego. Esses homens, ó rei, não fazem caso de ti, pois não adoram nem servem aos teus deuses, nem se prostram diante da estátua de ouro que ergueste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Então, Nabucodonosor, cheio de ira, ordenou que Sadraque, Mesaque e Abednego fossem trazidos a ele. Assim, esses homens foram trazidos diante do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nabucodonosor lhes perguntou: \"Vós decidistes, Sadraque, Mesaque e Abednego, não adorar aos meus deuses, nem se prostrar diante da estátua de ouro que levantei?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Agora, se estais prontos, quando ouvirdes os sons da trombeta, da flauta, da harpa, da cítara, do saltério, da gaita de fole e de todo tipo de música, vos prostrareis e adorareis a estátua que fiz, e tudo ficará bem. Mas, se não adorardes, sereis imediatamente lançados em uma fornalha de fogo ardente. E quem é o deus que será capaz de vos salvar das minhas mãos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Sadraque, Mesaque e Abednego responderam ao rei: \"Ó Nabucodonosor, não temos necessidade de te responder sobre esse assunto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Se há uma resposta, é que o nosso Deus, a Quem servimos, é capaz de nos livrar da fornalha de fogo ardente, e Ele nos livrará da tua mão, ó rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Mas, se não, fica sabendo, ó rei, que não adoraremos os vossos deuses e não nos prostraremos diante da estátua de ouro que levantaste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Então, Nabucodonosor se encheu de ira e seu rosto mudou contra Sadraque, Mesaque e Abednego. Ele ordenou que a fornalha fosse aquecida sete vezes mais do que normalmente se aquecia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Então, ordenou a alguns homens fortes do seu exército que amarrassem Sadraque, Mesaque e Abednego e os jogassem na fornalha de fogo ardente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Eles foram amarrados ainda vestindo suas vestes — túnicas, turbantes e outras roupas —, e jogados na fornalha de fogo ardente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'A ordem do rei foi estritamente seguida, e a fornalha estava tão quente que as chamas mataram os homens que carregaram Sadraque, Mesaque e Abednego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Estes três homens, Sadraque, Mesaque e Abednego, caíram amarrados dentro da fornalha de fogo ardente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Então, o rei Nabucodonosor se espantou e se levantou rapidamente. Ele perguntou a seus conselheiros: \"Não jogamos três homens amarrados no fogo?\". Eles responderam ao rei: \"Certamente, rei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Ele disse: \"Mas vejo quatro homens que não estão amarrados andando no fogo, e eles não estão feridos. O brilho do quarto é como de um filho dos deuses\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Então, Nabucodonosor chegou perto da porta da fornalha de fogo ardente e gritou: \"Sadraque, Mesaque e Abednego, servos do Deus Altíssimo, saí! Vinde para cá!\". Sadraque, Mesaque e Abednego saíram do fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Os sátrapas, prefeitos, governadores e conselheiros do rei que estavam ali reunidos viram esses homens. O fogo não feriu seus corpos; os cabelos de suas cabeças não estavam chamuscados; suas vestes não foram prejudicadas e não havia cheiro de fumaça neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Nabucodonosor disse: \"Louvemos o Deus de Sadraque, Mesaque e Abednego, que enviou o Seu anjo e livrou os Seus servos. Eles confiaram Nele quando deixaram de lado a minha ordem, e entregaram os seus corpos em vez de adorar ou se prostrar a qualquer deus, exceto seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Portanto, eu decreto que qualquer povo, nação ou língua que fale alguma coisa contra o Deus de Sadraque, Mesaque e Abednego seja dilacerado, e que suas casas sejam transformadas em monturos, porque não há outro deus que seja capaz de salvar como Este\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Então, o rei fez prosperar a Sadraque, Mesaque e Abednego na província de Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'O rei Nabucodonosor enviou este decreto a todos os povos, nações, e línguas que viviam sobre a terra: \"Que a vossa paz seja multiplicada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Pareceu-me bem contar a vocês acerca dos sinais e maravilhas que me fez o Altíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Quão grandes são os Seus sinais e quão poderosas são as Suas maravilhas! Seu Reino é um reino eterno e o Seu domínio vai de geração a geração\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Eu, Nabucodonosor, vivia alegremente em minha casa e desfrutava de prosperidade no meu palácio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Mas tive um sonho e fiquei com medo. Enquanto eu estava ali deitado, as imagens que eu vi e as visões em minha mente me perturbaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Então, expedi um decreto para que trouxessem diante de mim todos os sábios da Babilônia, a fim de que interpretassem o sonho para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Então, vieram os magos, os adivinhadores, os sábios e os astrólogos. Eu lhes contei o sonho, mas eles não puderam interpretá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Por fim, veio Daniel (chamado Beltessazar, segundo o nome do meu deus, e em quem está o espírito dos deuses santos) e contei-lhe o sonho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, '\"Beltessazar, chefe dos magos, eu sei que o espírito dos deuses santos está em ti, e que nenhum mistério é muito difícil para ti. Dize-me o que eu vi em meu sonho e o que significa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Estas foram as visões que tive em minha mente enquanto dormia: olhei e havia uma árvore no meio da terra e ela era muito alta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'A árvore cresceu e se tornou forte. O seu topo alcançou os céus e podia ser vista até os confins da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Suas folhas eram lindas, seus frutos eram abundantes e nela havia comida para todos. Os animais do campo achavam sombra sob ela e as aves do céu viviam em seus ramos. Todas as criaturas se alimentavam dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Enquanto estava deitado em minha cama, eu vi, em minha mente, um mensageiro descendo dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Ele clamou e disse: \'Abatei a árvore e cortai seus ramos, sacudi as suas folhas e espalhai seus frutos. Que os animais fujam dela e os pássaros voem para longe de seus ramos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Deixai o tronco e suas raízes na terra, cercai-a com uma cinta de ferro e bronze no meio da grama verde do campo; que seja molhada com o orvalho dos céus; que viva com os animais entre as plantas da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Que a sua mente seja mudada, deixando de ser humana, e lhe seja dada uma mente de animal, até que se passem sete anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Esta decisão veio do decreto apresentado pelo mensageiro. É uma decisão tomada pelo Santíssimo, para que aqueles que estão vivos saibam que o Altíssimo governa sobre os reinos dos povos, e os dá a quem Ele quer, para os governar, até ao homem mais humilde\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Eu, rei Nabuconodosor, tive esse sonho. Agora tu, Beltessazar, conta-me a interpretação, porque nenhum dos sábios no meu reino pode o interpretar para mim. Mas tu és capaz de fazê-lo, porque o espírito dos deuses santos está em ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Então Daniel, também chamado de Beltessazar, ficou triste por algum tempo, seus pensamentos o perturbaram. O rei disse: \"Beltessazar, não deixe que o sonho ou sua interpretação te perturbem\". Beltessazar respondeu: \"Meu senhor, que este sonho seja para aqueles que te odeiam; que esta interpretação seja para os teus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'A árvore que tu viste — a que cresceu e se tornou forte, e cujo topo alcançou os céus, e que podia ser vista até os confins da terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'cujas folhas eram lindas, e cujos frutos eram abundantes, e nela havia comida para todos e, debaixo dela, animais do campo achavam sombra, e na qual as aves do céu viviam —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'tu és esta árvore, rei. Tu cresceste e te fortaleceste. Tuas grandezas se espalharam alcançando os céus e tua autoridade alcançou os confins da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Tu, rei, viste um santo mensageiro que desceu do céu e disse: \'Cortai a árvore e a destruí, mas deixai o tronco e suas raízes na terra, cercai-a com cinta de ferro e bronze, no meio da grama verde do campo. Que seja molhada com o orvalho dos céus. Que ela viva com os animais selvagens no campo até que sete anos se passem\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Esta é a interpretação, rei. Este é o decreto do Altíssimo que te alcançou, ó rei e meu senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Tu serás expulso do meio dos homens e viverás com os animais do campo; comerás grama como um boi e serás molhado com o orvalho dos céus. Sete anos se passarão até que tu saibas que o Altíssimo governa sobre os reinos dos povos e Ele os dá a quem quiser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Como foi ordenado que fossem deixados o tronco e as raízes da árvore, da mesma forma, o teu reino será devolvido a ti a partir do momento em que tu aprenderes que é o céu que governa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Portanto, ó rei, aceita o meu conselho: deixa de pecar e faz o que é certo. Afasta-te de tuas iniquidades e mostra misericórdia ao oprimido. Talvez, assim, a tua prosperidade seja prolongada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Todas essas coisas aconteceram ao rei Nabucodonosor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Doze meses depois, ele estava caminhando no palácio real, na Babilônia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'e disse: \"Esta não é a grande Babilônia que eu construí para ser minha residência real, para a glória da minha majestade?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Enquanto o rei ainda estava dizendo isso, uma voz veio do céu: \"rei Nabucodonosor, foi decretado que este reino foi tirado de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Tu serás afastado das pessoas e o seu lar será com os animais do campo. Tu comerás grama como o boi. Sete anos se passarão até reconheceres que o Altíssimo governa sobre os reinos dos povos, e os dá a quem Ele deseja\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Este decreto contra Nabucodonosor se cumpriu imediatamente. Ele foi expulso do meio do povo, comeu grama como boi e o seu corpo foi molhado com o orvalho dos céus. O seu cabelo cresceu como as penas das águias e as suas unhas, como as das aves.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, '\"Ao fim dos dias, eu, Nabucodonosor, levantei meus olhos para o céu e a minha sanidade voltou a mim. Eu louvei ao Altíssimo, honrei e glorifiquei Àquele que vive para sempre, pois Seu reinado é um reinado eterno. O Seu reino dura de geração em geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'Para Ele, todos os habitantes da terra são considerados como nada; Ele faz o que Lhe apraz entre os exércitos do céu e os habitantes da terra. Ninguém pode pará-Lo, nem desafiá-Lo. Ninguém pode dizer-Lhe: \'Por que Tu fizeste isso?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'No mesmo momento em que a minha sanidade retornou, minha majestade e o meu esplendor me foram devolvidos para a glória do meu reino. Os meus conselheiros e os meus nobres solicitaram o meu favor. Fui colocado de volta no meu trono e ainda mais grandeza me foi dada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Agora eu, Nabucodonosor, louvo, exalto e honro ao Rei do céu, porque todas as Suas obras são retas e Seus caminhos são justos. Ele pode humilhar aqueles que andam em orgulho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Belsazar, o rei, fez um grande banquete para mil de seus nobres e bebeu vinho em frente de todos os mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Enquanto Belsazar provava o vinho, deu ordens para que trouxessem as taças feitas de ouro e prata que Nabucodonosor, seu pai, havia tirado do templo em Jerusalém, para que ele, seus nobres, suas esposas e concubinas pudessem beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Os servos trouxeram as taças de ouro que haviam sido tiradas do templo de Israel, a casa de Deus, em Jerusalém. O rei, seus nobres, suas esposas e suas concubinas beberam nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Eles beberam o vinho e louvaram seus ídolos feitos de ouro, prata, bronze, ferro, madeira e pedra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Naquele momento, os dedos de uma mão humana apareceram diante do castiçal, e escreveram no reboco da parede do palácio do rei. O rei podia ver parte da mão enquanto escrevia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Então, a fisionomia do rei mudou e seus pensamentos o perturbaram; suas pernas não o puderam suportar, e seus joelhos ficaram batendo um no outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'O rei gritou, ordenando que trouxessem os adivinhos, sábios e astrólogos. O rei disse aos sábios da Babilônia: \"Aquele que explicar esta inscrição e a interpretar, será vestido de púrpura e terá uma corrente de ouro no pescoço. Ele terá a autoridade como do terceiro governante do reino\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Então, todos os homens do rei, que eram conhecidos por sua sabedoria vieram, mas não puderam ler a escrita ou explicar o significado ao rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Então, o rei Belsazar ficou muito alarmado e sua fisionomia mudou. Seus nobres estavam perplexos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Ao saber o que o rei e seus nobres estavam falando, a rainha entrou no salão do banquete e disse: \"Rei, vive para sempre! Não deixes que teus pensamentos te perturbem. Não deixes que tua fisionomia mude.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Há um homem em teu reino que tem o espírito dos santos deuses. Nos dias de teu pai, foram encontrados nele luz, entendimento e sabedoria como a sabedoria dos deuses. O rei Nabucodonosor, teu pai, fez dele chefe dos magos, assim como chefe dos adivinhos, dos sábios e dos astrólogos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Neste Daniel, ao qual o rei pôs o nome de Beltessazar, foram encontrados um espírito excelente, conhecimento, entendimento para interpretar sonhos, explicar enigmas e resolver problemas. Agora, chama Daniel e ele te dirá o significado do que está escrito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Então, Daniel foi trazido diante do rei. O rei lhe disse: \"Tu és Daniel, um dos exilados de Judá, ao qual meu pai, o rei, tirou de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Eu ouvi sobre ti, que o espírito dos deuses está em ti e que a luz, o entendimento e a excelente sabedoria foram achados em ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Os sábios e os adivinhos acabaram de ser trazidos à minha presença para ler a escrita e saber interpretar para mim, mas eles não puderam fazer conhecida a interpretação disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Eu ouvi que tu podes dar interpretações e resolver problemas. Agora, se tu puderes ler a escrita e me dizer seu significado, serás vestido de púrpura e terás uma corrente de ouro no pescoço, e terás a autoridade como do terceiro governante do reino\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Então, Daniel respondeu diante do rei: \"Que os teus presentes fiquem contigo e dá tuas recompensas para outra pessoa. Entretanto, eu lerei a escrita para ti, rei, e direi o significado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Quanto a ti, ó rei, o Deus Altíssimo deu a Nabucodonosor, teu pai, o reino, a grandeza, a glória e a majestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Por causa da grandeza que Deus deu a ele, todos os povos, todas as nações e línguas tremiam e temiam diante dele. Ele matava aqueles que desejava que morressem e mantinha vivos aqueles que ele desejava que vivessem. Ele exaltava e abatia a quem queria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Mas, quando o seu coração foi arrogante e seu espírito se endureceu para agir presunçosamente, ele foi derrubado de seu trono real e sua majestade lhe foi tirada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Ele foi expulso do meio dos homens, teve a mente semelhante a de um animal e viveu com os jumentos selvagens. Ele comeu grama como os bois e seu corpo foi molhado com orvalho do céu, até que aprendeu que o Deus Altíssimo governa sobre os reinos do povo e constitui sobre eles a quem deseja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Mas tu, seu filho, Belsazar, não humilhaste o teu coração, mesmo que soubesses de tudo isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Tu te elevaste contra o Senhor do céu. Da sua Casa foram trazidas as taças que tu, teus nobres, suas esposas e suas concubinas beberam vinho, e tu deste louvores aos ídolos feitos de prata, ouro, bronze, ferro, madeira e pedra — ídolos que não veem, não ouvem nem sabem de nada. Tu não honraste o Deus que segura a tua respiração em Sua mão e que conhece todos os teus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Então, Deus enviou uma mão de Sua presença e fez a inscrição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Esta é a escrita que foi feita: Mene, Mene, Tequel e Parsim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Este é o significado: Mene: Deus enumerou teu reino e trouxe fim a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tequel: foste pesado na balança e encontrado em falta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres: teu reino será dividido e entregue aos medos e persas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Então, Belsazar deu uma ordem e eles vestiram Daniel com púrpura. Uma corrente de ouro foi colocada em seu pescoço e o rei fez uma proclamação sobre ele, de que teria a autoridade como o terceiro maior governante do reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Aquela noite, Belsazar, o rei da Babilônia, foi morto,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'e Dario, o medo, recebeu o reino, quando tinha cerca de sessenta e dois anos de idade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Dario decidiu colocar sobre o reino cento e vinte governadores de províncias que governariam sobre todo o reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Sobre eles, havia três administradores chefes e Daniel era um deles. Esses administradores chefes foram colocados para supervisionar os governadores das províncias, para que o rei não tivesse perdas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Daniel se destacava sobre os outros administradores chefes e os governadores provinciais, porque tinha um espírito extraordinário. O rei planejava o colocar sobre todo o reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Então, os outros administradores chefes e os governadores das províncias procuraram por erros no trabalho que Daniel fazia para o reino, mas não puderam achar nenhuma corrupção ou falha no seu trabalho, porque ele era fiel; nenhum erro ou negligência foram encontrados nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Então, aqueles homens disseram: \"Não conseguimos achar nenhuma razão para nos queixarmos desse Daniel, a não ser que achemos algo contra ele em relação à lei do seu Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Então, esses administradores e governadores apresentaram um plano ao rei. Eles lhe falaram: \"Rei Dario, vive para sempre!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Todos os administradores chefes do reino, os governadores regionais, os governadores provinciais, os conselheiros e os governadores consultaram juntos e decidiram que tu, o rei, deves fazer um decreto e deves fazer cumpri-lo, para que quem fizer um pedido para qualquer deus ou homem, dentro de trinta dias, senão a ti, rei, essa pessoa seja lançada na cova dos leões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Agora, rei, faz um decreto e assina o documento para que não possa ser alterado, como manda a lei dos medos e persas, de modo que este não possa ser revogado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Então, o rei Dario assinou o documento tornando o decreto em uma lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Quando Daniel soube que o documento havia sido assinado como lei, ele foi para dentro da sua casa — suas janelas ficavam abertas em seu quarto superior em direção a Jerusalém —, dobrou os joelhos, como fazia três vezes ao dia, orou e deu graças a Deus, como antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Então, esses homens, que juntos formaram a conspiração, viram Daniel fazer pedidos e clamar por ajuda a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Então, eles se aproximaram do rei e falaram com ele sobre seu decreto: \"Tu não fizeste um decreto no qual todos os que fizessem um pedido para qualquer deus ou homem durante os próximos trinta dias, exceto a ti, ó rei, deveriam ser jogados na cova dos leões?\". O rei respondeu: \"O assunto está resolvido, conforme foi indicado pela lei dos medos e persas, que não poderá ser anulada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Então, eles responderam ao rei: \"Aquele Daniel, uma das pessoas do exílio de Judá, não dá atenção a ti, rei, ou ao decreto que assinaste. Ele ora ao Deus dele três vezes ao dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Quando o rei ouviu isso, ficou terrivelmente angustiado e pensou em como poderia livrar Daniel dessa regra. Ele trabalhou até o pôr do sol para tentar salvar Daniel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Aqueles homens, que juntos formaram a conspiração, se reuniram com o rei e lhe disseram: \"Sabe, rei, esta é uma lei dos medos e persas, que nenhum decreto ou estatuto que o rei estabelecer pode ser mudado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Então, o rei deu uma ordem, e trouxeram Daniel e o jogaram na cova dos leões. O rei disse a Daniel: \"Que o teu Deus, ao Qual tu serves continuamente, te livre dos leões\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Uma pedra foi colocada sobre a entrada da cova, e o rei selou a cova com o seu anel e com os anéis dos seus nobres, para que nada pudesse ser mudado a respeito de Daniel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Então, o rei foi ao seu palácio e, durante a noite, ficou em jejum. Nenhum entretenimento foi trazido a sua presença, e ele não conseguiu dormir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Então, no dia seguinte cedo, o rei se levantou e rapidamente foi até a cova dos leões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Quando chegou perto da cova, chamou por Daniel com a voz triste, e disse: \"Daniel, servo do Deus Vivo, o teu Deus, a Quem serves continuamente, foi capaz de te salvar dos leões?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Então, Daniel disse ao rei: \"Ó rei, vive para sempre!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'O meu Deus mandou um anjo e fechou a boca dos leões, e eles não me machucaram, porque fui achado inocente perante Ele e também perante ti, rei, e eu não te fiz mal algum\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'O rei ficou muito feliz e ordenou que tirassem Daniel da cova. Então, Daniel foi tirado da cova. Nenhum dano foi encontrado nele, pois ele havia confiado no seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'O rei deu uma ordem e eles trouxeram aqueles homens que haviam acusado Daniel e os jogaram na cova dos leões — eles, seus filhos e suas esposas. Antes de alcançarem o chão, os leões os atacaram e quebraram todos os seus ossos em pedaços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Então, o rei Dario escreveu para todos os povos, todas as nações e línguas que vivem em toda a terra: \"Que a paz aumente em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Faço um decreto, em todo o domínio de meu reino, pelo qual os homens tremam e temam perante o Deus de Daniel, pois Ele é o Deus Vivo e Ele vive para sempre, e o Seu reino nunca será destruído; Seu domínio não terá fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Ele nos protege e nos salva; Ele faz sinais e maravilhas nos céus e na terra; Ele protegeu Daniel do poder dos leões\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Então, Daniel prosperou durante o reinado de Dario e durante o reinado de Ciro, o persa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'No primeiro ano de Belsazar, rei da Babilônia, Daniel teve um sonho e visões em sua mente, enquanto estava deitado em sua cama. Então, ele escreveu o que viu em seu sonho e registrou os mais importantes acontecimentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel explicou: \"Em minha visão à noite, eu vi que os quatro ventos do céu agitavam o mar Grande.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Quatro grandes animais, cada um diferente do outro, ergueram-se do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'O primeiro era semelhante a um leão, mas tinha asas de águia. Enquanto eu estava olhando, as asas lhe foram arrancadas, e o mesmo foi erguido do chão, para se firmar sobre os dois pés, como um homem. A mente de um homem lhe foi dada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Houve um segundo animal, semelhante a um urso, e estava curvado, e tinha três costelas entre os dentes da sua boca. E lhe foi dito: \'Te levanta e devora multidões\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Depois disso, eu olhei novamente. Havia um outro animal que era semelhante a um leopardo. Sobre suas costas havia quatro asas, como asas de uma ave. Ele tinha quatro cabeças, e lhe foi dada autoridade para governar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Depois disso, eu vi, em meu sonho à noite, um quarto animal, terrível, assustador e muito forte. Ele tinha grandes dentes de ferro; devorava e quebrava em pedaços tudo que sobejava. Ele era diferente dos outros animais e tinha dez chifres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Enquanto eu observava os chifres, vi outro chifre, que crescia entre eles, um chifre pequeno. Três dos primeiros chifres foram arrancados pelas raízes. Vi, nesse chifre, olhos semelhantes ao de um homem, e uma boca, que falava com arrogância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Permaneci olhando: eis que surgiram tronos, e o Ancião dos dias se assentou. Suas vestes eram brancas como a neve e os cabelos da sua cabeça, como a pura lã; seu trono era como chamas de fogo e as rodas dele, como fogo ardente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Um rio de fogo fluía diante dele; milhões o serviam, e centenas de milhões estavam diante dele. O tribunal estava em sessão e os livros foram abertos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Permaneci observando, por causa das palavras arrogantes pronunciadas pelo chifre. Eu olhava, enquanto o animal era morto, e o seu corpo destruído e entregue para ser queimado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Quanto aos outros quatro animais, sua autoridade lhes foi tirada, porém suas vidas foram prolongadas por um período de tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Em minhas visões, naquela noite, vi alguém, semelhante ao filho do homem, vindo com as nuvens do céu; então, ele se aproximou do Ancião de dias e foi apresentado diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Autoridade, glória e poder real Lhe foram dados para que todos os povos, todas as nações e línguas Lhe servissem. Sua autoridade para governar é uma autoridade eterna, que não passará, e Seu reino nunca será destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Quanto a mim, Daniel, meu espírito se abateu dentro de mim, e as visões que eu vi em minha mente me perturbaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Aproximei-me de um deles e pedi para me mostrar o significado de todas essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Esses grandes animais, os quatro, são quatro reis que se levantarão sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Mas os santos do Altíssimo receberão o reino e eles o possuirão para sempre e sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Então, eu desejei saber mais sobre o quarto animal — que era tão diferente dos outros e terrível com os seus dentes de ferro e garras de bronze — ele devorava, despedaçava e pisoteava o que era deixado aos seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Eu queria saber sobre os dez chifres, em sua cabeça, e sobre o outro chifre, que cresceu quando caíram os outros três. Eu queria saber sobre o chifre que tinha olhos e sobre a boca que falava com arrogância sobre grandes coisas, os quais pareciam ser maiores que seus companheiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Enquanto eu olhava, o chifre travava uma guerra contra os santos e os derrotava,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'até que o Ancião de dias veio, e a justiça foi dada aos santos do Altíssimo. Então, chegou o tempo em que os santos receberam o reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Isto é o que aquela pessoa disse: \'Quanto ao quarto animal, será um quarto reino, na terra, que será diferente de todos os outros reinos. Ele devorará toda a terra, a pisoteará e a quebrará em pedaços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Quanto aos dez chifres, dez reis se levantarão do reino, e um outro se levantará depois deles. Ele será diferente dos anteriores e dominará sobre os três reis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Falará palavras contra o Altíssimo e oprimirá os santos do Deus Altíssimo. Tentará mudar suas festas e leis. Essas coisas serão dadas em suas mãos por um tempo, dois tempos e meio tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Mas o tribunal estará em sessão, e o poder lhe será tirado, e será aniquilado e destruído até o fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'O reino, o domínio e a grandeza dos reinos sob todo o céu serão dados aos santos do Altíssimo. Seu reino é um reino eterno e todos os outros reinos o servirão e o obedecerão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Aqui está o final da visão. Quanto a mim, Daniel, meus pensamentos ficaram alarmados e meu rosto mudou de aparência, mas eu guardei essas coisas comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'No terceiro ano do reinado de Belsazar, eu, Daniel, tive uma visão, depois da que tive antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Na visão, estava na cidade fortificada de Susã, na província do Elão, pois eu estava à margem do rio Ulai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Ergui os olhos e vi, diante de mim, um carneiro com dois chifres à margem do rio. Um chifre era maior que o outro, porém, o mais comprido cresceu mais devagar, sendo ultrapassado em comprimento pelo mais curto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Eu vi o carneiro dando cabeçadas para o oeste, para o norte e para o sul; nenhum animal conseguiu prevalecer contra ele. Nenhum deles foi capaz de resgatar alguém de suas mãos. Ele fez o que quis, e se tornou grande.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Enquanto eu pensava sobre isso, vi que um bode veio do oeste, atravessando toda a face da terra, correndo rápido e não parecia tocar no chão. O bode tinha um grande chifre entre seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Ele veio ao carneiro que tinha dois chifres, o qual eu vi à margem do rio, e o bode correu em direção ao carneiro com uma terrível fúria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Vi o bode se aproximar do carneiro com muita fúria. Ele o atingiu e quebrou seus dois chifres. O carneiro perdeu seu poder de resistir ao bode. O bode derrubou o carneiro no chão e pisou nele. Não havia ninguém que pudesse livrar o carneiro de seu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Então, o bode se tornou muito grande; porém, quando ele se tornou forte, o chifre grande foi quebrado. Em seu lugar, outros quatro grandes chifres cresceram e apontavam para os quatros cantos dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'De um desses chifres, cresceu um outro chifre, pequeno a princípio, mas que se tornou muito grande e apontava em direção ao sul, ao leste e em direção à terra gloriosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Ele se tornou tão grande que entrou em guerra com o exército celestial. Uma parte desse exército e algumas das estrelas do céu foram atiradas na terra e pisoteadas pelo bode.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Ele se tornou grande, tão grande quanto o comandante do exército divino. O holocausto contínuo foi tirado dele, e o lugar de seu santuário foi contaminado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Por causa da sua rebeldia, o exército será entregue ao chifre do bode, e os sacrifícios serão interrompidos. O chifre lançará a verdade por terra, e ele terá êxito no que fizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Então, ouvi um anjo falando com outro anjo: \"Por quanto tempo durará a visão sobre os holocaustos, o pecado que traz destruição, a entrega do santuário e o exército celestial sendo pisoteado?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Ele me disse: \"Durará por duas mil e trezentas noites e manhãs. Depois disso, o santuário será restaurado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Quando eu, Daniel, tive essa visão, tentei compreendê-la. E apareceu diante de mim alguém semelhante a um homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Eu ouvi a voz do homem falando, da outra margem do rio Ulai. Ele disse: \"Gabriel, ajuda esse homem a compreender a visão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Então, ele veio perto de onde eu estava. Quando chegou, eu estava apavorado e prostrado ao chão. Ele me disse: \"Compreende, filho do homem, que a visão é do tempo do fim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Quando ele falou comigo, caí em sono profundo com meu rosto no chão. Então, ele me tocou e me fez ficar em pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Ele disse: \"Vê, eu te mostrarei o que acontecerá depois, no tempo da ira, porque a visão se trata do tempo determinado para o fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Quanto ao carneiro que viste, o que tinha dois chifres, eles são os reis da Média e da Pérsia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'O bode é o rei da Grécia. O grande chifre entre seus olhos é o primeiro rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'A respeito do chifre que foi quebrado no lugar em que outros quatro surgiram, quatro reinos surgirão dessa nação, mas não com seu grande poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Nos últimos tempos desses reinos, quando os transgressores alcançarem seu limite, um rei com expressão sombria e muito inteligente surgirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Seu poder será grande, mas não por seu próprio poder. Ele será incrível naquilo que destrói; ele vai agir e ter sucesso. Ele destruirá pessoas poderosas, pessoas entre os santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Pela sua astúcia, fará com que o engano prospere sob sua mão. Ele se tornará grande em sua própria mente e irá destruir muitas pessoas inesperadamente. Ele até se levantará contra o Rei dos reis e será quebrado, mas não por qualquer mão humana.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'A visão a respeito das noites e manhãs é verdade, mas sela a visão, pois se refere a muitos dias no futuro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Então, eu, Daniel, desmaiei e fiquei doente por muitos dias; depois me levantei e fui tratar dos negócios do rei. Mas eu estava chocado com a visão e não havia ninguém que a entendesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Dario era o filho de Assuero, um descendente dos medos. Foi Assuero que se tornou rei sobre o reino dos babilônios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'No primeiro ano do reinado de Dario, eu, Daniel, estava estudando os livros que contêm a palavra de Yahweh, a palavra que veio a Jeremias, o profeta. Eu observei que seriam setenta anos até a desolação de Jerusalém acabar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Voltei meu rosto para o Senhor Deus, para buscá-Lo em oração, com pedidos, em jejum, usando roupas feitas de saco e sentado em cinzas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Orei para Yahweh, meu Deus, e fiz a confissão dos nossos pecados. Eu disse: \"Senhor, Tu és o grande e maravilhoso Deus que manténs Tua aliança e és fiel com aqueles que Te amam e guardam os Teus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Nós pecamos e fizemos o que é errado. Agimos de forma perversa e nos rebelamos, nos desviando dos Teus mandamentos e decretos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Não ouvimos os Teus servos, os profetas, que falaram em Teu nome para nossos reis, nossos líderes, nossos antepassados e para todo o povo da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'A Ti, Deus, pertence a justiça. A nós, hoje, no entanto, pertence a vergonha, em nossos rostos — ao povo de Judá, àqueles que vivem em Jerusalém e a todos em Israel. Isso inclui aqueles que estão perto e aqueles que estão longe, em todas as terras aonde os espalhaste. Isso é por causa da grande traição que nós cometemos contra Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'A nós, Yahweh, pertence a vergonha em nossos rostos — aos nossos reis, nossos líderes e nossos pais — porque temos pecado contra Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Ao Senhor, nosso Deus, pertencem a compaixão e o perdão, pois temos nos rebelado contra Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'Nós não obedecemos a voz de Yahweh, nosso Deus, andando em Suas leis, que nos deu, através dos Seus servos, os profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Todo Israel transgediu a Tua Lei e se recusou a obedecer a Tua voz. A maldição e o juramento que estão escritos na Lei de Moisés, o servo de Deus, foram derramados sobre nós, porque nós pecamos contra Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Yahweh confirmou as palavras que Ele falou contra nós e contra nossos governadores, trazendo sobre nós grande desgraça. Pois, debaixo de todo o céu não foi feito nada que se pudesse comparar com o que foi feito a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Como está escrito na lei de Moisés, todo esse desastre nos sobreveio; contudo, nós não imploramos pela misericórdia de Yahweh, nosso Deus, afastando-nos das nossas iniquidades e prestando atenção à Sua verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Portanto, Yahweh preparou o desastre e o trouxe sobre nós; porque Yahweh, nosso Deus, é justo em todos os atos que faz, ainda que nós não tenhamos obedecido à Sua voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Agora, Senhor, nosso Deus, Tu tiraste o Teu povo da terra do Egito com mão poderosa e Tu fizeste Teu nome grande como neste dia. Mas, mesmo assim, nós pecamos; nós fizemos coisas perversas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Senhor, por causa de todas as Tuas obras de justiça, deixa a Tua raiva e a Tua ira se afastarem da Tua cidade, Jerusalém, Teu santo monte. Por causa dos nossos pecados e por causa das iniquidades dos nossos antepassados, Jerusalém e o Teu povo se tornaram um objeto de desprezo para todos ao nosso redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Agora, nosso Deus, escuta a oração do Teu servo e os seus pedidos por misericórdia; por teu amor, Senhor, faze o Teu rosto brilhar no Teu santuário, que está desolado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Meu Deus, abre os Teus ouvidos e ouve; abre os Teus olhos e vê. Nós fomos destruídos; olha para a nossa cidade, que é chamada pelo Teu nome. Nós não pedimos a Ti ajuda por causa da Tua justiça, mas por causa da Tua grande misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Senhor, escuta! Senhor, perdoa! Senhor, presta atenção e age! Por amor a Ti, não demores, meu Deus, pois a Tua cidade e o Teu povo são chamados pelo Teu nome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Enquanto eu falava, orava e confessava o meu pecado e o pecado do meu povo, Israel, e apresentava os meus pedidos diante de Yahweh, meu Deus, em favor do monte santo do meu Deus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'enquanto eu orava, Gabriel — o homem que eu já havia visto na minha visão, no princípio — voou em minha direção, rapidamente, no momento do sacrifício da tarde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Ele me deu entendimento e me disse: \"Daniel, eu vim agora para te dar conhecimento e entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Quando tu começaste a pedir por misericórdia, a ordem foi dada, e eu vim para te dar a resposta, pois tu és muito amado. Portanto, considera esta palavra e entende a revelação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Setenta semanas estão decretadas para o teu povo e para a tua santa cidade para acabar com a culpa, pôr um fim ao pecado, expiar a iniquidade, trazer a justiça eterna, encerrar a visão e a profecia e consagrar o Lugar Santíssimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Sabe e compreende que, desde a emissão da ordem para restaurar e reconstruir Jerusalém até a vinda do ungido (que será um líder), haverá sete semanas e sessenta e duas semanas. Jerusalém será reconstruída com ruas e um fosso, apesar dos tempos de aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Após as sessenta e duas semanas, o ungido será destruído e não haverá nada. O exército de um governante vindouro destruirá a cidade e o Lugar Santo. O seu fim será com uma inundação e haverá guerra até o fim. Desolações foram decretadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Ele confirmará uma aliança com muitos por uma semana. No meio da semana, ele colocará um fim ao sacrifício e às ofertas. Nas asas das abominações, virá alguém que fará desolações. O fim e a destruição estão decretados para serem derramados sobre aquele que fez a desolação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'No terceiro ano de Ciro, rei da Pérsia, uma mensagem foi revelada a Daniel, quem também era chamado de Beltessazar e essa mensagem era verdadeira. Era sobre uma grande guerra. Daniel entendeu a mensagem quando teve compreensão da visão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'Naqueles dias, Eu, Daniel, estive lamentando por três semanas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Eu não comi iguarias, nem carne, não bebi vinho e não me ungi com óleo até o fim de três semanas inteiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'No vigésimo quarto dia do primeiro mês, enquanto eu estava ao lado do grande rio, o Tigre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'eu olhei para cima e vi um homem vestido de linho, com um cinto de ouro puro de Ufaz em volta de sua cintura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Seu corpo era como topázio, sua face como raio, seus olhos eram como tochas flamejantes, seus braços e seus pés eram como bronze polido e o som de suas palavras era como o som de uma grande multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Eu, Daniel, vi sozinho a visão, pois os homens que estavam comigo não a viram. Contudo, um grande temor veio sobre eles e eles correram para se esconder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Então, eu estava só e vi a grande visão. Nenhuma força permaneceu em mim, minha aparência radiante mudou pavorosamente e nenhuma força restou em mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Então, eu ouvi suas palavras e enquanto eu as ouvia, caí sobre a minha face em sono profundo com o rosto ao chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Uma mão me tocou e fez tremer os meus joelhos e as minhas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'O anjo me disse: \"Daniel, homem muito amado, entende as palavras que te digo e levanta, pois eu fui enviado a ti\". Quando me disse essas palavras, eu me levantei tremendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Então, ele me disse: \"Não temas, Daniel. Desde o primeiro dia em que inclinaste tua mente para entender e te humilhar diante do teu Deus, tuas palavras foram ouvidas e eu vim por causa de tuas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'O príncipe do reino da Pérsia me resistiu e fui mantido lá com os reis da Pérsia por vinte e um dias. Mas Miguel, um dos maiores príncipes, veio para me ajudar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Agora, eu vim para te ajudar a entender o que acontecerá ao teu povo nos últimos dias. Pois, a visão é para os dias que ainda virão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Quando ele falou comigo, usando essas palavras, eu virei meu rosto para o chão e fui incapaz de falar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Alguém parecido com um humano me tocou os lábios e eu abri a minha boca e falei com ele, que estava perante mim: \"Meu senhor, a visão me deixou aflito e eu não tenho mais forças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Eu sou teu servo. Como posso falar contigo? Pois eu já não tenho mais forças e não há mais fôlego em mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Aquele com a aparência humana me tocou e me fortaleceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Ele disse: \"Homem muito amado, não temas. A paz seja contigo. Sê forte agora, sê forte!\" Enquanto ele falava comigo, fui fortalecido e disse: \"Fala meu senhor, pois me fortaleceste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Ele disse: \"Sabes por que vim a ti? Em breve retornarei para lutar contra o príncipe da Pérsia. Quando eu for, o príncipe da Grécia virá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Mas eu vou te dizer o que está escrito no Livro da Verdade. Não há ninguém que se mostre forte diante de mim, exceto Miguel, vosso príncipe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, '\"No primeiro ano de Dario, o medo, Eu mesmo vim apoiar e proteger Miguel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'E agora, revelarei a verdade para ti. Três reis surgirão na Pérsia, e o quarto será muito mais rico que todos os outros. Quando ele ganhar poder através de suas riquezas, ele incitará todos contra o reino da Grécia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Um poderoso rei se levantará e governará um grande reino, e agirá de acordo com os seus desejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Quando ele se levantar, seu reino será quebrado e dividido para os quatro ventos do céu, e não para seus descendentes, e não terá a autoridade de antes. Pois seu reino será desenraizado e dado a outros que não são seus descendentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'O rei do sul se tornará forte, mas um dos seus comandantes será ainda mais forte do que ele, e governará seu reino com grande poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Depois de alguns anos, no tempo certo, eles farão uma aliança. A filha do rei do sul virá ao rei do norte para confirmar o acordo. Mas ela não conservará o seu poder, nem manterá o dele. Ela será abandonada; ela e aqueles que a trouxeram, seu pai e aqueles que a apoiaram naqueles tempos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Mas, das suas raízes, um ramo crescerá em seu lugar. Ele atacará o exército e entrará na fortaleza do rei do norte, guerreará contra eles e os conquistará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Ele levará seus deuses para o Egito, junto com suas figuras de metal fundido e seus preciosos vasos de prata e de ouro e, por alguns anos, evitará atacar o rei do norte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'O rei do norte invadirá a região do reino do sul, mas retornará à sua própria terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Seus filhos se prepararão e montarão um grande exército, o qual avançará e arrasará tudo. Ele percorrerá todo o caminho até chegar à sua fortaleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Então, o rei do sul ficará muito irado e lutará contra o rei do norte. E este levantará um grande exército, mas será derrotado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'O exército será arrasado, o coração do rei do sul se exaltará e derrotará dezenas de milhares, mas, mesmo assim, ele não será vitorioso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'O rei do norte erguerá um outro exército, maior que o primeiro. Alguns anos depois, o rei do norte, certamente, voltará com um exército maior, com fortes armamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Naqueles tempos, muitos se levantarão contra o rei do sul. Os mais violentos entre o teu povo se juntarão a eles para cumprir a visão, mas eles tropeçarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'O rei do norte virá, construirá rampas e conquistará uma cidade fortificada. As forças do sul, nem mesmo os seus melhores soldados, não serão capazes de resistir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'O invasor fará tudo o quiser contra ele, e ninguém poderá detê-lo. Ele se estabelecerá na gloriosa terra de Israel e a destruição estará na sua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'O rei do norte virá com determinação e com a força de todo o seu reino, e fará um acordo com o rei do sul. A este, ele dará a sua filha em casamento para lhe destruir o reino. Porém, o plano não terá sucesso nem o ajudará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Depois disso, o rei do norte atentará às regiões costeiras e dominará muitas delas. Mas um comandante porá fim à sua insolência e, com audácia, lhe retribuirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Então, ele atentará às fortalezas da sua própria terra, mas tropeçará e cairá, e não será encontrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Então, alguém se levantará em seu lugar e aumentará os impostos pagos para manter o esplendor do reino. Porém, em pouco dias ele será destruído, sem ira ou batalhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Em seu lugar, se levantará um desprezado, a quem o povo não deu a honra da realeza; ele virá tranquilamente e tomará o reino, com astúcia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Um exército será varrido, como uma inundação, perante ele. Ambos, exército e líder, estabelecidos pela aliança, serão destruídos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'A partir do momento em que for feita a aliança, ele agirá enganosamente; com apenas um pequeno número de pessoas se tornará forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Sem aviso, ele virá para a parte mais rica da província e fará o que nem seu pai, nem seu avô fizeram; dividirá, entre seus seguidores, o saque, a pilhagem e a riqueza. Ele tramará a derrubada das fortalezas, mas somente por um tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Ele juntará seu poder e sua coragem e reunirá um grande exército contra o rei do sul. O rei do sul travará batalha com um grande e poderoso exército, mas ele não será capaz de resistir por causa dos planos feitos contra ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Mesmo aqueles que comem suas finas comidas tentarão destruí-lo. Seu exército será varrido como uma inundação e muitos deles serão mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Com seus corações voltados para o mal, esses reis se sentarão na mesma mesa, mas mentirão um ao outro. Tal diálogo não os ajudará, pois o fim virá no tempo determinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Então, o rei do norte retornará para sua terra com muitas riquezas; porém, seu coração estará contra a santa aliança. Ele fará o que desejar e retornará para sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'No tempo determinado, ele voltará e invadirá o sul novamente. Porém, desta vez não será como antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Pois ele terá medo dos navios de Quitim e voltará atrás. Ele se enfurecerá contra a santa aliança e mostrará benevolência para com aqueles que abandonarem a santa aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Seus exércitos se levantarão e profanarão o Santuário, isto é, a fortaleza; eles farão cessar os holocaustos contínuos e estabelecerão a abominação, que causará completa desolação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Ele enganará aqueles que tiverem violado a aliança e os seduzirá, mas o povo que conhece o seu Deus será forte e tomará uma atitude.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Os sábios entre o povo instruirão a muitos. Mas tropeçarão pela espada, pelo fogo, pelo cativeiro, e serão roubados de suas posses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Ao caírem, receberão uma pequena ajuda, mas muitos se juntarão a eles com falsidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Alguns dos sábios tropeçarão para que sejam refinados, limpos e purificados até o fim do tempo. Pois o tempo determinado ainda virá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'O rei fará o que desejar. Ele exaltará e magnificará a si mesmo acima de todos os deuses, falará coisas surpreendentes contra o Deus dos deuses e prosperará até que a ira esteja completa, pois o que foi decretado se cumprirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Ele não mostrará respeito pelo Deus de seus pais, nem pelo deus preferido das mulheres, ou por qualquer outro deus, pois agirá orgulhosamente e se proclamará acima de tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Ao invés deles, ele honrará o deus das fortalezas. Ele honrará com prata e ouro, com pedras preciosas e presentes caros, um deus a quem seus antepassados não conheceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Ele atacará a fortaleza mais forte com a ajuda de um deus estrangeiro. Ele dará muita honra a qualquer um que o reconheça. Ele os fará governar sobre muitos e dividirá a terra como recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'No tempo do fim, o rei do sul atacará. O rei do norte virá contra ele como tempestade, com carros e cavaleiros e muitos navios. Ele virá contra as terras, as atravessará e arrasará tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Ele virá para a terra gloriosa de Israel e dezenas de milhares de israelitas cairão, mas muitos de Edom e Moabe, e os remanescentes do povo de Amom escaparão de suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Ele estenderá sua mão para as terras; a terra do Egito não escapará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Terá autoridade sobre os tesouros de ouro e prata, e sobre todas as riquezas do Egito; os líbios e os etíopes o servirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Porém, notícias do leste e do norte o alarmarão e ele seguirá com grande fúria para destruir e separar muitos para a destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Ele assentará barracas em seu palácio, entre os mares e o glorioso monte santo. Seu fim virá e não haverá quem o socorra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Naquele tempo, Miguel, o grande príncipe que guarda o teu povo se levantará. Haverá um tempo de tribulação como nunca houve desde o início de qualquer nação até então. Naquele tempo, teu povo será salvo, todo aquele cujo nome for achado escrito no Livro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Muitos desses que dormem no pó da terra ressuscitarão, alguns para a vida eterna e outros para vergonha e desprezo eterno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Aqueles que são sábios resplandecerão como o brilho do céu acima, e aqueles que convertem muitos para a justiça brilharão como as estrelas, para sempre e sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Mas tu, Daniel, sela estas palavras; guarda o livro selado até o fim do tempo. Muitos correrão aqui e ali, e o conhecimento aumentará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Então, eu, Daniel, olhei e havia outros dois em pé; um ficou de um lado da margem do rio e o outro do outro lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Um deles disse para o homem vestido de linho, aquele que estava rio acima: \"Quanto tempo haverá até o fim desses eventos maravilhosos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Eu ouvi o homem vestido de linho, que estava rio acima, ele levantou suas mãos para o céu e jurou por Aquele que vive para sempre, que haveria um tempo, tempos e metade de um tempo. Quando o poder do povo santo tiver sido destruído, todas essas coisas terão acontecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Eu ouvi, mas não entendi. Então, perguntei: \"Meu senhor, qual será o resultado de todas essas coisas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Ele disse: \"Vai-te, Daniel, porque essas palavras estão lacradas e seladas até o fim dos tempos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Muitos serão purificados, limpos e refinados, mas os maus agirão com maldade. Nenhum dos maus entenderá, mas aqueles que são sábios entenderão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Desde o tempo que o sacrifício diário for tirado e a abominação que causa completa desolação estiver estabelecida, haverá um mil duzentos e noventa dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Bendito é o que espera até o fim de mil trezentos e trinta e cinco dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Tu deves seguir teu caminho até o fim, e descansarás. Tu descansarás e te levantarás no lugar designado para ti no fim dos dias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Esta é a palavra de Yahweh, que veio a Oseias, filho de Beeri, nos dias de Uzias, Jotão, Acaz e Ezequias, reis de Judá, e nos dias de Jeroboão, filho de Joás, rei de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Quando a princípio, Yahweh falou por intermédio de Oseias, disse a ele: \"Vai, toma para ti uma mulher que seja prostituta. Ela terá filhos, resultado da prostituição. A terra cometeu grande prostituição por abandonar Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Então, Oseias se casou com Gômer, filha de Diblaim, e ela concebeu e lhe deu um filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Yahweh disse a Oseias: \"Põe nele o nome de Jezreel. Pois, em breve, punirei a casa de Jeú pelo derramamento do sangue de Jezreel e cessarei o reino da casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Acontecerá no dia em que quebrarei o arco de Israel no vale de Jezreel.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Gômer concebeu novamente e deu à luz uma filha. Então, Yahweh disse a Oseias: \"Põe nela o nome de Lo-Ruama, pois não terei mais misericórdia da casa de Israel, põe-lhe o nome de Lo-Ruama; porque não me compadecerei da casa de Israel; de maneira alguma perdoarei por completo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Contudo, terei misericórdia da casa de Judá, e os salvarei por Mim mesmo, Yahweh, o Deus deles. Não os salvarei pelo arco, nem pela espada, nem pela guerra, nem pelos cavalos e nem por cavaleiros.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Então, depois de Lo-Ruama ter desmamado, Gômer concebeu e deu à luz outro filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Então, Yahweh disse: \"Põe-lhe o nome de Lo-Ami, pois, vós não sois Meu povo e nem Eu, vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Contudo, o número de filhos de Israel será como a areia do mar, que não pode ser medida, nem contada. Embora tenha sido dito a eles: \'Vós não sois Meu povo\', se dirá: \'Sois povo do Deus vivo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'O filhos de Judá e os filhos de Israel se reunirão, designarão um líder, e subirão da terra, porque grande será o dia de Jezreel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Dizei a vossos irmãos: \'Meu povo!\', e a vossas irmãs: \'A vós foi mostrada compaixão\'.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Trazei uma acusação contra vossa mãe; trazei uma acusação porque ela não é Minha mulher, e nem eu sou seu Marido. Que ela afaste de si sua prostituição e seus atos de adultério de entre os seus seios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Senão, Eu a despirei e mostrarei a sua nudez como no dia em que ela nasceu. Eu a farei como o deserto, como terra seca, e a matarei de sede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Não terei nenhuma misericórdia dos seus filhos, pois são filhos da prostituição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Porque sua mãe foi uma prostituta, e ela os concebeu, agindo vergonhosamente. Ela disse: \"Irei atrás dos meus amantes, pois eles me dão meu pão e água, minha lã e linho, meu óleo e bebida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Portanto, construirei uma cerca para bloquear seu caminho com espinhos. Erguerei uma parede contra ela para que não possa encontrar o seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Ela irá procurar seus amantes, mas não os alcançará. Ela os buscará, mas não os achará. Então, ela dirá: \"Voltarei ao meu primeiro marido, pois estava melhor do que agora\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Porque ela não reconheceu que fui Eu quem lhe deu o grão, o vinho novo e o azeite, e que multipliquei sua prata e ouro, que eles usaram para Baal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Assim, tirarei o grão dela na época da colheita, e o Meu vinho novo em sua estação. Tomarei a Minha lã e o Meu linho que foram usados para cobrir a sua nudez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Então a desnudarei diante de seus amantes, e ninguém a resgatará da Minha mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Também farei cessar todas as suas celebrações: suas festas, suas luas novas, seus sábados, e todas as suas festividades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, '\"Destruirei suas videiras e suas figueiras, das quais ela disse: \'Este é o pagamento que os meus amantes me deram\'. Farei delas uma floresta, e os animais do campo as devorarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Eu a punirei pelos dias de festa dos baalins, quando ela queimava incenso para eles, quando se adornou com seus anéis e joias, e ia atrás de seus amantes e se esquecia de Mim\" — essa é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Então a reconquistarei, levarei-a para o deserto e falarei ternamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Eu lhe devolverei suas vinhas e o vale de Acor como porta de esperança. Ela Me responderá como nos dias de sua mocidade, como no dia em que subiu da terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, '\"Naquele dia\"— Yahweh declara— \"tu Me chamarás: \'meu Marido\', e não mais Me chamarás: \'meu Baal\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Pois, Eu removerei os nomes dos baalins de teus lábios; os nomes deles não serão mais lembrados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Naquele dia, em favor deles, farei uma aliança com as feras dos campos, com os pássaros do céu, com os répteis da terra. Tirarei da terra o arco, a espada, e a guerra, e os farei deitar em segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Prometo ser teu marido para sempre. Prometo ser teu marido em retidão, justiça, aliança fiel e misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Irei Me comprometer em fidelidade, e tu conhecerás Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, '\"Naquele dia, responderei\" — esta é a declaração de Yahweh — \"responderei aos céus, e eles responderão à terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'A terra responderá ao grão, ao vinho novo e ao óleo, e eles responderão a Jezreel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'E a semearei na terra para Mim, e terei misericórdia de Lo-Ruama. Direi a Lo-Ami: \'Tu és Ammi Attah\', e eles Me dirão: \'Tu és o meu Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Yahweh me disse: \"Vai, de novo, ama uma mulher, amada pelo seu marido, porém, adúltera. Ama-a como Eu, Yahweh, amo o povo de Israel, embora se voltem a outros deuses e amem bolos de passas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Então, compra-a para mim por quinze peças de prata e um ômer e meio de cevada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Eu disse a ela: \"Deves viver comigo muitos dias. Não serás prostituta e nem serás de nenhum outro homem. Do mesmo jeito, serei também para ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Pois, o povo de Israel viverá por muitos dias sem um rei, sem príncipe, sem sacrifício, sem coluna de pedra, sem estola sacerdotal, e sem ídolos do lar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Depois, o povo de Israel retornará e buscará a Yahweh, seu Deus, e a Davi, seu rei; e, nos últimos dias, virão em tremor diante de Yahweh e da Sua bondade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Ouvi a palavra de Yahweh, vós povo de Israel. Yahweh tem uma acusação contra os habitantes da terra, porque não há verdade nem misericórdia e não há conhecimento de Deus na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Há maldição, mentira, matança, roubo e adultério. O povo transgrediu todos os limites, e multiplicou-se o derramamento de sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Por isso, a terra lamenta, e todos os que nela moram desfalecem; as bestas nos campos e as aves no céu, até mesmo os peixes do mar são tirados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Todavia, ninguém contenda; não deixeis que ninguém acuse ao outro. Porque sois vós, os sacerdotes, a quem estou acusando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Vós, sacerdotes, tropeçareis de dia; os profetas tropeçarão com vós de noite, e Eu destruirei a vossa mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'O meu povo está sendo destruído por falta de conhecimento. Porque vós, sacerdotes, rejeitastes o conhecimento, também Eu vos rejeitarei como Meus sacerdotes. Porque esquecestes a Minha Lei, embora Eu seja o vosso Deus, Eu também Me esquecerei dos vossos filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Quanto mais multiplicavam os sacerdotes, mais eles pecavam contra Mim. Trocaram a sua honra por vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Eles se alimentam do pecado do Meu povo; eles são gananciosos por mais da sua maldade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Será assim para o povo como para os sacerdotes: Eu punirei todos eles pelas suas práticas; Eu os retribuirei por suas ações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Comerão, mas não se fartarão; cometerão prostituição, mas não se multiplicarão, porque se distanciaram de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Amam a promiscuidade sexual, vinho, e o vinho novo, que lhes tirou o entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Meu povo consulta os seus ídolos de madeira, e as suas bengalas lhes dão profecias. Pois uma mente de promiscuidade os desviou, e agiram como prostitutas, ao invés de serem fiéis ao seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Eles sacrificam no alto dos montes e queimam incenso nas colinas, debaixo dos carvalhos, álamos e terebintos, porque sua sombra é boa. Então, suas filhas cometem imoralidade sexual, e suas noras cometem adultério.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Não punirei vossas filhas quando escolherem cometer imoralidade sexual, nem vossas noras quando cometerem adultério. Pois, também os homens se dão às prostitutas, e oferecem sacrifícios para que eles possam cometer atos imorais com as prostitutas sagradas. Por isso, este povo sem entendimento será arruinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Embora tu, Israel, tenhas cometido adultério, que Judá não se torne culpado. Não venhais a Gilgal, vós povo, não subais a Bete-Áven, e não jureis, dizendo: \"Vive Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Pois, Israel se comportou teimosamente, como uma vitela rebelde. Como pode Yahweh levá-los para um pasto, como o de cordeiros numa campina espaçosa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Efraim se juntou aos ídolos; deixa-o só.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Mesmo quando a sua bebida forte acaba, eles continuam a cometer adultério; os seus líderes amam, apaixonadamente, a sua vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'O vento os envolveu nas suas asas, e serão envergonhados por causa dos seus sacrifícios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, '\"Ouvi isto, sacerdotes! Prestai atenção, casa de Israel! Ouvi, casa do rei! O julgamento vem contra todos vós. Vós fostes uma armadilha em Mispá e uma rede estendida sobre o Tabor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Os rebeldes mergulharam na matança, mas Eu castigarei todos eles..');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Conheço Efraim, e Israel não está escondido de Mim. Efraim, agora tu te tornaste como uma prostituta; Israel está corrompido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Suas práticas não lhes permitem voltar para Deus, porque o espírito de prostituição está no meio deles, e não conhecem Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'A soberba de Israel testifica contra ele. Assim, Israel e Efraim tropeçarão em sua culpa; e Judá também cairá com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Eles irão com os seus rebanhos e manadas para buscarem a Yahweh, mas não O acharão, porque Ele se retirou deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Eles foram infiéis a Yahweh, porque geraram filhos ilegítimos. Agora, as festas da Lua Nova os consumirão com seus campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Tocai a trombeta em Gibeá, e a trombeta em Ramá. Levantai um grito de batalha em Bete Áven: \'Nós iremos te seguir, Benjamim!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraim se tornará uma desolação no dia do castigo. Entre as tribos de Israel, Eu declarei o que, certamente, se cumprirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Os líderes de Judá são como aqueles que retiram as pedras de limites. Sobre eles Eu derramarei Minha ira como água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Efraim está esmagado, ele está esmagado em julgamento porque, voluntariamente, seguiu após ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Portanto, Eu serei como uma traça para Efraim, e como podridão para a casa de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Quando Efraim viu a sua doença e Judá viu a sua ferida, então Efraim foi à Assíria, e Judá enviou mensageiros ao grande rei. Mas ele não foi capaz de curar ou sarar a sua ferida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Assim, serei como leão para Efraim, e como leãozinho para a casa de Judá. Eu, Eu mesmo, os rasgarei e irei embora; Eu os levarei para fora, e não haverá ninguém para os resgatar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Irei e voltarei ao Meu lugar, até que reconheçam a sua culpa e busquem a Minha face, até que, sinceramente, busquem-Me na sua angústia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, '\"Vinde! Voltemos para Yahweh. Porque Ele nos despedaçou, mas irá nos sarar; Ele nos feriu, mas atará nossas feridas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Depois de dois dias, Ele nos dará vida novamente; Ele nos levantará ao terceiro dia, e viveremos diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Conheçamos a Yahweh, prossigamos em O conhecer. A Sua vinda é certa como o amanhecer; Ele virá até nós como as chuvas, como as chuvas da primavera que molham a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Efraim, que farei a ti? Que farei a ti, Judá? Tua fidelidade é como a nuvem da manhã, como o orvalho que cedo passa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Por isso, por meio dos profetas, Eu os parti em pedaços, Eu os matei com as palavras de Minha boca. Meus decretos são como a luz que brilha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Pois desejo fidelidade, e não sacrifício; e o conhecimento de Deus mais do que ofertas queimadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Como Adão, eles quebraram a Aliança; eles foram infiéis Comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gileade é uma cidade de malfeitores marcada com pegadas de sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Como bandos de ladrões à espreita de alguém, assim estão os sacerdotes unidos para cometerem assassinato no caminho de Siquém; eles praticam crimes vergonhosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Na casa de Israel vi uma coisa horrível; a prostituição de Efraim está lá, e Israel se contaminou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Também para ti, Judá, uma colheita foi determinada, quando Eu restaurar o Meu povo do cativeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Sempre que quero curar Israel, o pecado de Efraim é exposto, assim como as maldades de Samaria, pois praticam o engano; e o ladrão entra, e um bando de saqueadores ataca na rua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Não entendem nos seus corações que Me lembro de todas as suas maldades. Agora, suas ações os envolvem; estão diante da Minha face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Com sua maldade alegram o rei, e os príncipes com suas mentiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Todos são adúlteros, como um forno aquecido pelo padeiro que cessa de agitar o fogo, desde o amassar da massa até estar levedada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'No dia do nosso rei, os príncipes ficaram doentes com os efeitos do vinho. Ele estendeu a mão aos escarnecedores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Porque preparam o coração como um forno, enganam enquanto maquinam seus planos. Sua raiva arde lentamente toda a noite; pela manhã queima ardentemente como uma chama viva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Todos eles estão quentes como um forno, e devoram aqueles que reinam sobre eles. Todos seus reis caíram; nenhum deles clama a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraim se mistura com os povos; é um bolo achatado que não foi virado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Estrangeiros devoraram sua força e ele não o sabe. Cabelos grisalhos estão espalhados nele, mas ele não o sabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'A arrogância de Israel testifica contra ele; todavia eles não voltaram para Yahweh, seu Deus, nem O buscaram, apesar disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Efraim é como uma pomba ingênua e sem bom senso, que invoca o Egito e, em seguida, voa para a Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Quando forem, atirarei Minha rede sobre eles, e os farei descer como as aves dos céus. Eu os punirei, conforme o que tem ouvido sua congregação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Ai deles! Porque se afastaram de Mim. Devastação lhes sobrevirá! Eles se rebelaram contra Mim! Eu os teria resgatado, mas eles falaram mentiras contra Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Não clamaram a Mim com todo o seu coração, mas lamentam em suas camas. Eles se ajuntam para o trigo e vinho novo, e se viram contra Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Embora Eu os tenha instruído e fortalecido os seus braços, estão agora pensando o mal contra Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Eles voltaram, mas não para Mim, o Altíssimo. São como um arco traiçoeiro. Os seus príncipes cairão pela espada por causa da insolência de suas línguas. Isso se tornará escárnio na terra do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, '\"Põe uma trombeta em tua boca! Ele virá como uma águia sobre a Casa de Yahweh; porque o povo quebrou Minha Aliança e se rebelou contra Minha Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Eles clamam a Mim: \'Ó Deus, nós, Israel, Te conhecemos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Mas Israel rejeitou o que é bom, e o inimigo o perseguirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Eles estabeleceram reis, mas não por Mim. Eles constituíram príncipes, mas sem Meu conhecimento. Com sua prata e ouro fizeram ídolos para si, mas foi somente para serem destruídos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'O teu bezerro foi rejeitado, Samaria. A Minha ira se acendeu contra este povo. Por quanto tempo eles serão culpados?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Pois esse ídolo vem de Israel; um artífice o fez — isto não é Deus! O bezerro de Samaria será destruído em pedaços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Pois as pessoas semearam vento e colheram tormenta. O talo existente não florescerá; ele não produzirá farinha. Se ele amadurecer, os estrangeiros o devorarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Israel foi devorado; agora ele está entre as nações como coisa inútil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Pois eles subiram para a Assíria como um solitário jumento selvagem. Efraim contratou para si os seus amantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Mesmo que eles tenham contratado seus amantes entre as nações, Eu os reunirei. Eles começarão a definhar por causa da opressão do rei dos príncipes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Pois Efraim multiplicou altares para fazer ofertas pelo pecado; mas, ao invés disso, eles se tornaram altares para cometer pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Eu poderia escrever a Minha Lei para eles dez mil vezes, mas eles a iriam ver como algo estranho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Quanto aos sacrifícios das Minhas ofertas, eles sacrificam carne e a comem, mas Eu, Yahweh, não os aceitarei. Agora, lembrarei da sua iniquidade e punirei seus pecados. Eles voltarão para o Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Israel se esqueceu de Mim, o seu Criador, e construíram templos. Judá fortificou muitas cidades, mas enviarei fogo nas suas cidades, este fogo destruirá seus palácios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Não te alegres, Israel, não exultes como os outros povos. Pois tu tens sido infiel, renunciando ao Teu Deus. Amas o salário de prostituta em todas as eiras de trigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Mas a eira e o lagar não os alimentarão, e o vinho novo lhes faltará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Eles não continuarão vivendo na terra de Yahweh; em vez disso, Efraim voltará para o Egito e comerão comida impura na Assíria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Não derramarão ofertas de vinho a Yahweh, também não Lhe agradarão com ofertas. Os seus sacrifícios serão como alimento de luto: todo aquele que comer será profanado. Pois seu alimento será somente para eles; não entrará na casa de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'O que fareis no dia da solenidade, e no dia da festa para Yahweh?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Vede! Se eles escaparem da destruição, o Egito os ceifará, e Mênfis os sepultará. Quanto aos seus tesouros de prata, as urtigas os possuirão e os espinhos encherão as suas tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Os dias do castigo estão vindo; os dias da retribuição estão chegando. Que todo o Israel saiba destas coisas. O profeta é um tolo, e o homem inspirado é louco, por causa da sua grande iniquidade e hostilidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'O vigia de Efraim está com o meu Deus, mas o profeta é como uma armadilha para aves em todos os seus caminhos, inimizade na casa do seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Eles têm-se corrompido profundamente, como nos dias de Gibeá. Yahweh lembrará de suas iniquidades, e punirá os seus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Yahweh diz: \"Quando encontrei Israel, foi como apanhar uvas no deserto. Vi seus pais como se vê o primeiro fruto da figueira. Mas eles foram para Baal-Peor, e se consagraram a esse ídolo vergonhoso. Se tornaram tão detestáveis como o ídolo que amaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Quanto a Efraim, a sua glória voará como um pássaro. Não haverá nascimento, nem gravidez, nem concepção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Embora venham a criar filhos, Eu os tirarei para que não fique nenhum deles. Ai deles quando Eu me afastar!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Vejo Efraim, como vejo Tiro, plantado no campo, mas Efraim trará seus filhos a alguém que os matará.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Dá-lhes, Yahweh — o que o Senhor lhes dará? Dê-hes útero que aborte e seios sem leite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, '\"Por causa de toda a sua maldade em Gilgal, passei a odiá-los desde aquele momento. Por causa das suas práticas pecaminosas, Eu os lançarei fora da Minha casa. Não os amarei mais; todos os seus príncipes são rebeldes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Efraim está doente, e as suas raízes secaram; não darão fruto. Ainda que tenham filhos, Eu matarei seus amados filhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'O meu Deus os rejeitará porque não Lhe obedeceram. Eles andarão errantes entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israel é uma videira fértil que dá os seus frutos. Quantos mais seus frutos aumentaram, mais altares multiplicaram. Quanto mais produzia sua terra, mais aumentavam seus altares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'O coração deles é enganador; agora devem carregar as suas culpas. Yahweh irá destruir seus altares; Ele irá destruir seus pilares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Pois eles dirão: \"Nós não temos rei, porque não tememos a Yahweh. E o rei — o que ele poderia fazer por nós?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Eles falam palavras vazias e fazem alianças, jurando falsamente. Então, a justiça brotará como uma erva daninha nos sulcos de um campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Os habitantes de Samaria serão atemorizados por causa do bezerro de Bete-Áven. Seu povo lamentará por causa dele, como aqueles sacerdotes idólatras que se regozijavam nele e pelo seu esplendor; porém ele já não existe mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Será levado para Assíria como um presente para o grande rei. Efraim será humilhado, e Israel sentirá vergonha do seu ídolo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'O rei de Samaria será destruído como um pedaço de madeira lançado sobre a água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Os lugares altos de iniquidade serão destruídos. Este é o pecado de Israel! Espinhos e abrolhos crescerão sobre seus altares. As pessoas dirão às montanhas: \"Cobri-nos!\", e às colinas: \"Caí sobre nós!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, '\"Israel, tu tens pecado desde os dias de Gibeá; ali permaneceste. A guerra não alcançará os filhos da iniquidade em Gibeá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Quando Eu desejar, eu os disciplinarei. As nações irão se reunir contra eles e irão prendê-los por sua dupla iniquidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Efraim é uma bezerra domada que gosta de debulhar o grão, por isso colocarei o jugo em seu pescoço. Porei o jugo sobre Efraim; Judá lavrará; Jacó desfará os torrões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Semeai para vós justiça, e colhei o fruto da misericórdia. Lavrai o solo da lavoura, porque já é tempo de buscar a Yahweh, até que Ele venha e faça chover justiça sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Lavrastes a maldade, colhereis a iniquidade. Comestes o fruto da mentira, porque confiastes nos vossos planos e nos vossos muitos soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Portanto, um tumulto de guerra se levantará no meio do teu povo, e todas as suas fortalezas serão destruídas. Será como Salmã, que destruiu Bete-Arbel no dia da batalha, quando as mães foram despedaçadas com seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Assim acontecerá contigo, Betel, por causa da tua iniquidade. Ao romper do dia, o rei de Israel será completamente destruído\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, '“Quando Israel era jovem Eu o amei, e chamei Meu filho para fora do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Quanto mais eram chamados, mais se afastavam de Mim. Eles sacrificavam aos baalins e queimavam incenso aos ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Todavia, fui Eu quem ensinei Efraim a andar; fui Eu quem os levantou pelos braços, mas eles não perceberam que Eu cuidava deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Eu lhes orientei com laços de amor, com laços de ternura. Eu era para eles como alguém que tirou o jugo de sobre suas cabeças, inclinando-Me e lhes alimentando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Eles não voltarão para a terra do Egito. A Assíria será seu rei; porque eles se recusam a voltar para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'A espada cairá sobre suas cidades e destruirá as trancas das suas portas; serão destruídas por causa do seus próprios planos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Meu povo está determinado a se virar contra Mim. Embora eles Me chamem de Altíssimo, ninguém os ajudará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Como desistirei de ti, Efraim? Como te entregarei, Israel? Como te farei como Admá? Ou como Zeboim? Meu coração se comove dentro de Mim; toda Minha compaixão está agitada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Eu não vou executar Minha ira; não vou destruir Efraim. Pois Eu Sou Deus e não homem; Eu Sou O Santo entre vós, e não virei com Minha ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Eles seguirão Yahweh; e Ele rugirá como o leão. Quando Ele rugir, seus filhos virão tremendo do oeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Eles virão tremendo como um pássaro, os do Egito; e como uma pomba, os da terra da Assíria. Eu os farei viver nas suas casas\" — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, '\"Efraim Me rodeia com falsidade; e a casa de Israel, com engano. Mas Judá ainda anda Comigo, ainda é fiel a Mim, O Único Santo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efraim se alimenta de vento e segue após o vento leste. Multiplica, continuamente, mentira e violência. Faz aliança com a Assíria e leva azeite para o Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Yahweh também tem uma demanda contra Judá e castigará Jacó por aquilo que tem feito, e vai retribuí-lo por suas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Ainda no útero, Jacó agarrou seu irmão pelo calcanhar e, na sua humanidade, brigou com Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Ele brigou com o anjo e venceu. Chorou e implorou por Seu favor. Ele encontrou Deus em Betel; ali, Deus falou com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Este é Yahweh, o Deus dos Exércitos; \"Yahweh\" é o nome pelo qual deve ser chamado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Então, volta para o teu Deus. Guarda o amor leal e a justiça, e espere continuamente por teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Os mercadores têm balanças falsas em suas mãos; eles amam defraudar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Efraim disse, \"Eu me tornei muito rico por mim mesmo. Em todo o meu trabalho eles não encontrarão qualquer iniquidade em mim, qualquer coisa que possa ser pecado.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, '\"Eu sou Yahweh, teu Deus, da terra do Egito. Eu farei, novamente, com que vivam em tendas, como nos dias dos festivais estabelecidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Eu falei aos profetas e lhes dei muitas visões. Pelas mãos dos profetas eu dei parábolas.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Gileade certamente tem ídolos por vaidade. Em Gilgal, eles sacrificam touros; seus altares serão como um amontoado de pedras nos sulcos dos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Jacó fugiu para a terra de Aram; Israel trabalhou para conseguir uma esposa; guardou rebanhos de ovelhas para consegui-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Yahweh trouxe Israel do Egito por meio de um profeta e, o profeta cuidou deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Efraim rudemente provocou a ira de Yahweh. Por isso o Senhor deixará o sangue derramado sobre Efraim, e trará desgraça sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, '\"Quando Efraim falou, houve tremor. Ele exaltou a si mesmo em Israel, mas se tornou culpado por causa da adoração a Baal, e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Agora, pecam mais e mais. Fazem imagens de metal fundido com sua prata, ídolos tão cuidadosamente trabalhados, todos eles são obras de artesão. As pessoas falam deles: \'Estes homens que sacrificam beijem os bezerros\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Pois eles serão como a nuvem da manhã, como o orvalho que desaparece cedo, como a palha que se espalha na eira, e como a fumaça que sai da chaminé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Mas Eu Sou Yahweh vosso Deus desde a terra do Egito. Tu deves reconhecer que não há Deus além de Mim, não há nenhum outro salvador. Tu deves reconhecer que, além de Mim, não há outro Salvador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Eu te conheci no deserto, numa terra de grande secura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Quando tu tinhas pasto, ficaste cheio; e quando estavas na tua abundância, teu coração se exaltou. Por esta razão me esqueceste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Eu virei como um leão sobre eles; como leopardo vigiarei ao longo do caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Eu os atacarei como a ursa que é roubada de seus filhotes. Rasgarei o peito deles, e os devorarei como um leão, e como um animal selvagem devorarei em pedaços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Tu estás destruído, ó Israel, mas de Mim vem o teu socorro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Onde está agora o teu rei, para que ele te salve em todas as tuas cidades? Onde estão os teus juízes, a quem tu disseste, \'Dá-me um rei e príncipes?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Eu lhes dei um rei na Minha raiva, e eu o tirei na Minha ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'A iniquidade de Efraim está registrada; o seu pecado também está guardado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Dores de parto virão sobre ele, mas ele é um filho insensato; pois, quando é o tempo de nascer, ele não sai do ventre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Eu os resgatarei da mão do Sheol? Irei resgatá-los da morte? Onde estão ó morte as tuas pragas? Onde está, ó Sheol, a tua destruição? O arrependimento está escondido dos meus olhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Embora Efraim seja próspero no meio dos irmãos, um vento virá do leste; o vento de Yahweh soprará no deserto, e a fonte de Efraim secará, e o seu poço não terá água. Os inimigos roubarão todos os vossos objetos preciosos nos vossos armazéns.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samaria será culpada, porque se rebelou contra o seu Deus. Eles cairão pela espada; suas crianças serão despedaçadas, e as grávidas terão seus ventres abertos pelo meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Israel, volta a Yahweh teu Deus, pois tens caído, por causa da tua iniquidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Toma contigo as palavras e converte-te a Yahweh. Diz a Ele: \"Tira para fora toda nossa iniquidade, e aceita o que é bom, então vamos oferecer-Te os frutos dos nossos lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'A Assíria não nos salvará; não iremos cavalgar em cavalos para a guerra. Nem mesmo diremos mais para a obra das nossas mãos: \'Vós sois nossos deuses\'; porque só em Ti órfão encontra misericórdia.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, '\"Eu os curarei da sua infidelidade; Eu os amarei livremente, porque a minha ira se afastou deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Eu serei como orvalho para Israel; ele florescerá como o lírio, e lançarei as suas raízes como um cedro do Líbano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Os seus ramos se espalharão; sua formosura será como a das oliveiras, e sua fragrância será como os cedros do Líbano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Os que viviam à sua sombra voltarão; eles serão vivificados como as sementes e florescerão como a videira. A sua fama será como a vide do Líbano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Efraim, o que tenho Eu com os ídolos? Eu te responderei e cuidarei de ti. Eu Sou como o cipreste cujas folhas estão sempre verdes; o teu fruto procede de Mim\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Quem é sábio para que entenda estas coisas? Quem compreende estas coisas, para que as conheça? Porque os caminhos de Yahweh são retos, e os justos andarão neles, mas os rebeldes neles tropeçarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Palavra de Yahweh que veio para Joel, filho de Petuel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, '\"Escutai isto, vós, anciãos, todos vós habitantes da terra. Porventura, isto alguma vez aconteceu nos vossos dias ou nos dias dos vossos antepassados?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Dizei aos vossos filhos acerca disto, e que os vossos filhos contem aos filhos deles, e os filhos destes à próxima geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'O que o gafanhoto cortador deixou, o gafanhoto migrador comeu; o que o gafanhoto migrador deixou, o gafanhoto devorador comeu; o que o gafanhoto devorador deixou, o gafanhoto destruidor comeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Acordai, bêbados, e chorai! Clamai, todos vós, bebedores de vinho, porque o vinho doce já foi retirado de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Porque uma nação forte e numerosa invadiu a Minha terra. Os seus dentes são dentes de leão, e ele tem as presas de uma leoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Ele transformou a Minha vinha em um lugar de horror, e expôs a nudez da Minha figueira. Ele descascou o seu caule e jogou fora; os ramos foram deixados embranquecidos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Lamentai como a virgem vestida com roupas de saco pela morte do seu jovem marido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'A oferta de cereais e a oferta de bebidas já foi cortada da casa de Yahweh. Os sacerdotes, servos de Yahweh, lamentam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Os campos foram devastados e a terra lamenta. O vinho novo secou e o óleo acabou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Envergonhai-vos, agricultores; pranteai, produtores de vinho, pelo trigo e pela cevada, pois a colheita dos campos pereceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'As vinhas e as figueiras secaram; as romeiras, as palmeiras e as macieiras também; todas as árvores do campo pereceram; pelo que a alegria dos filhos dos homens acabou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Colocai roupas de sacos e clamai, vós, sacerdotes! Clamai, ministros do altar. Aproximai-vos, deitai-vos a noite toda em panos de saco, vós servos do meu Deus. Porque a oferta de grãos e a oferta de bebidas foram retiradas da casa do vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Convocai um santo jejum e uma assembleia santa. Reuni os anciãos e todos os habitantes da terra para a casa de Yahweh, vosso Deus, e clamai por Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Ah! Que dia! Porque o dia de Yahweh está quase chegando. Com isto virá do Todo Poderoso a destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Não terá sido retirado o alimento diante dos nossos olhos, a alegria e o júbilo da casa de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'As sementes apodreceram por debaixo dos torrões; os celeiros foram devastados e os armazéns foram destruídos, porque secou o trigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Como gemem os animais! Os rebanhos de gado estão sofrendo porque não têm pasto; também os rebanhos de ovelhas sofrem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Yahweh, eu clamo a Ti. Porque o fogo devorou os pastos do deserto, e as chamas queimaram todas as árvores do campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Até os animais do campo anseiam por Ti, porque as correntes de água secaram e o fogo devorou os pastos do deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, '\"Tocai a trombeta em Sião e soai o alarme no Meu monte santo! Deixai que todos os habitantes da terra tremam de medo, pois o dia de Yahweh está chegando; de fato está perto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'É um dia de escuridão e melancolia, um dia de nuvens e densa escuridão. Como a aurora que se espalha pelas montanhas, um grande e poderoso exército está se aproximando. Nunca houve um exército como esse, e nunca haverá de novo, mesmo depois de muitas gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Um fogo está consumindo tudo na frente dele, e por detrás a chama está ardendo. À frente dele a terra é como o jardim do Éden, mas atrás há um deserto arruinado. De fato, nada escapará dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'A aparência do exército é como cavalos, e correm como cavaleiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Eles saltam com um som como o dos carros de guerra no topo das montanhas, como o som de chama de fogo que devora a palha, como um poderoso exército pronto para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Na sua presença, o povo está em angústia, e todos os seus rostos tornam-se pálidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Eles correm como poderosos guerreiros, sobem os muros como soldados, marcham como em um só passo e não quebram suas fileiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Nenhum deles empurra o outro para o lado; eles marcham cada um em seu caminho. Quebram as defesas e não saem da linha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Eles se apressam na cidade, correm no muro, sobem nas casas e passam pelas janelas como ladrões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'A terra treme em frente deles; os céus tremem; o sol e a lua escurecem e as estrelas deixam de brilhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Yahweh levanta a Sua voz diante do Seu exército, pois Seus guerreiros são muito numerosos, são fortes, aqueles que executam Seus comandos. Pois o dia de Yahweh é grande e muito terrível. Quem pode sobreviver?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, '\"Ainda agora mesmo\", diz Yahweh, \"retornai para mim de todo o vosso coração, com jejum, choro e lamento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Rasgai o vosso coração e não apenas as vossas roupas e voltai para Yahweh vosso Deus. Pois, Ele é gracioso e misericordioso, tardio para se irar, e grande em misericórdia e muda de idéia de infligir punição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Quem sabe? Talvez Ele se voltará e se compadecerá, deixando uma bênção após Ele, uma oferta de cereais e bebida para Yahweh vosso Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Tocai a trombeta em Sião, convocai um santo jejum e uma assembleia santa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Congregai o povo, convocai uma assembleia santa. Ajuntai os anciãos, as crianças e os que mamam. Que os noivos saiam dos seus quartos, e as noivas, dos seus aposentos nupciais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Que os sacerdotes, os ministros de Yahweh, chorem entre o pórtico e o altar; que digam: \"Tem misericórdia do Teu povo, Yahweh, e não tragas vergonha para Tua herança, para que as nações governem sobre eles\". Por que diriam entre as nações: \"Onde está o teu Deus?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Então Yahweh Se mostrou zeloso pela Sua terra, teve misericórdia do Seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Yahweh respondeu ao Seu povo: \"Eu vos mandarei grãos, vinho novo e azeite. Vós ficareis satisfeitos, e Eu não vos farei mais uma desgraça entre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Eu removerei para longe de vós o exército do norte, e os conduzirei para uma terra seca e abandonada. A dianteira do seu exército irá para o mar oriental e a sua retaguarda para o mar ocidental. Subirá o seu mau cheiro e subirá sua podridão\". Por que Ele tem feito grandes coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Não temas, terra, alegra-te e regozija-te, pois Yahweh fez grandes coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Não temais, feras do campo, pois os pastos do deserto brotarão, as árvores produzirão frutos e as figueiras e a vinhas produzirão com vigor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Alegra-te, povo de Sião, e regozija-te em Yahweh, teu Deus. Pois Ele vos dará a chuva de outono no devido tempo, enviará muita chuva para ti, a chuva de outono e a chuva de primavera, assim como antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, '\"A eira estará cheia de trigo e os tonéis transbordarão com vinho e azeite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Eu vos restaurarei os anos que os gafanhotos comeram — o gafanhoto migrador, o gafanhoto devorador, o gafanhoto destruidor e o gafanhoto cortador — Meu poderoso exército que Eu mandei entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Vós comereis abundantemente e vos saciareis, e louvareis o Nome de Yahweh, vosso Deus, que fez maravilhas no meio de vós, e Eu nunca trarei de novo vergonha ao Meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Vós sabereis que Eu estou no meio de Israel e que Eu Sou Yahweh, vosso Deus, e não há outro, e Eu nunca trarei vergonha para o Meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'Acontecerá, depois, que derramarei Meu Espírito sobre toda carne, e vossos filhos e filhas profetizarão. Vossos idosos sonharão; vossos jovens terão visões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Naqueles dias, derramarei Meu Espírito também sobre os servos e as servas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'Mostrarei maravilhas no céu e na terra; sangue, fogo e colunas de fumaça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'O sol se tornará em trevas e a lua em sangue, antes que venha o grande e terrível Dia de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'E todo aquele que clamar pelo Nome de Yahweh será salvo. Pois, no monte Sião e em Jerusalém, estarão aqueles que escaparam, como Yahweh disse, e, entre os sobreviventes, aqueles a quem Yahweh chamar..');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, '\"Eis que naqueles dias e naquele tempo, quando Eu trouxer os exilados de Judá e de Jerusalém,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'juntarei todas as nações, e os trarei ao vale de Josafá. Eu as julgarei lá, por causa do Meu povo e da Minha herança, Israel, a quem eles espalharam entre as nações, e porque dividiram a Minha terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Eles lançaram sortes para o Meu povo, trocaram um menino por uma prostituta, e venderam uma menina por vinho para beberem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Agora, por que estais zangados Comigo, Tiro, Sidom e todas as regiões da Filístia? Vós vos vingareis de Mim? Até mesmo, se vos vingardes de Mim, imediatamente retribuirei o que tendes feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Porque vós tomastes Minha prata e Meu ouro, e levastes Meus preciosos tesouros para vossos templos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'Vendestes o povo de Judá e de Jerusalém para os gregos, para que os levassem para longe dos seus territórios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Vede, estou quase a fazer-vos sair do lugar onde os vendestes, e retribuirei o que fizestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Venderei os vossos filhos e filhas, pela mão do povo de Judá. Eles os venderão aos sabeus, uma nação muito distante\". Porque assim disse Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Proclamai isto entre as nações: \"Preparai-vos para guerra, despertai os homens poderosos, deixai que eles se aproximem, que todos os homens se preparem para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Forjai vossas enxadas em espadas, e vossas foices em lanças. Que o fraco diga: \'Eu sou forte\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Apressai-vos e vinde, todas as nações próximas, ajuntai-vos lá\". Ó Yahweh, faz descer Teus guerreiros poderosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Permiti que as nações se levantem e venham até o vale de Josafá. Porque lá estarei sentado para julgar todas as nações ao derredor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Lançai a foice, porque já está pronta a colheita. Vinde e pisai as uvas, porque o lagar está cheio. Os vasos dos lagares transbordam, porque a sua maldade é enorme.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Existe um tumulto, um tumulto no vale do Julgamento. Porque o dia de Yahweh está próximo no vale do Julgamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'O sol e a lua se escurecerão, e as estrelas esconderão seu brilho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Yahweh rugirá de Sião, e de Jerusalém erguerá Sua voz. Os céus e a terra tremerão, mas Yahweh será um abrigo para o Seu povo, e uma fortaleza para o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, '\"Para que saibais que sou Yahweh, vosso Deus, que habito em Sião, o Meu santo monte. Então, Jerusalém será santa, e nenhum exército marchará através dela outra vez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'Acontecerá que, naquele dia, os montes destilarão vinho doce; os vales manarão leite; todos os riachos de Judá estarão cheios de água, e uma fonte virá da casa de Yahweh e regará o vale de Sitim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'O Egito se tornará uma devastação abandonada, e Edom se tornará um deserto, por causa da violência feita ao povo de Judá, porque eles derramaram sangue inocente na sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Mas Judá será habitada para sempre, e Jerusalém será habitada de geração em geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Eu Me vingarei do sangue daqueles de quem ainda não me vinguei\", porque Yahweh habita em Sião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Palavras de Amós, um dos pastores em Tecoa, que recebeu em revelação, concernentes a Israel. Ele a recebeu nos dias de Uzias, rei de Judá, e também nos dias de Jeroboão, filho de Joás, rei de Israel, dois anos antes do terremoto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Ele disse: \"Yahweh ruge de Sião, Ele levanta Sua voz de Jerusalém. Os pastos dos pastores murcham, e o cume do Carmelo se seca\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Assim diz Yahweh: \"Por três pecados de Damasco, mesmo por quatro, Eu não revogarei o castigo, porque eles esmagaram Gileade com instrumentos de ferro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Mandarei fogo na casa de Hazael que devorará a fortaleza de Ben Hadad.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Quebrarei os ferrolhos de Damasco, exterminarei o habitante do vale de Áven e também o homem que segura o cetro de Bete-Éden. E o povo da Síria será levado em cativeiro para Quir\", diz o Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Assim diz Yahweh: \"Por três pecados de Gaza, mesmo por quatro, não revogarei o castigo, porque levaram cativo o povo inteiro e o entregaram a Edom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Mandarei fogo nas muralhas de Gaza que devorará a sua fortaleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Eu destruirei o homem que vive em Asdode e o homem que segura o cetro de Asquelon. Colocarei a Minha mão contra Ecron, e o restante dos filisteus perecerá\", diz o Senhor Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Assim diz Yahweh: \"Por três pecados de Tiro, mesmo por quatro, não revogarei o castigo, porque eles entregaram cativo o povo inteiro para Edom e quebraram sua aliança de irmandade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Mandarei fogo nas muralhas de Tiro, que devorará sua fortaleza.\"\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Assim diz Yahweh: \"Por três pecados de Edom, mesmo por quatro, não revogarei o castigo, porque perseguiu seu irmão com a espada e desamparou toda a miséricordia. Sua ira não cessou, e seu furor foi eterno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Mandarei fogo em Teman que devorará os palácios de Bozrah\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Assim diz Yahweh: \"Por três pecados do povo de Amon, mesmo por quatro, não revogarei o castigo, porque eles abriram o ventre das mulheres grávidas de Gileade, para alargarem suas fronteiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Atearei fogo nas muralhas de Rabá que devorará os palácios, com alarido no dia da batalha, com tempestade no dia do redemoinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'O seu rei irá ao cativeiro, ele e todos os seus oficiais juntos\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Assim diz Yahweh: \"Por três pecados de Moabe, mesmo por quatro, Eu não retirarei o castigo, porque ele queimou os ossos do rei de Edom até as cinzas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Eu enviarei fogo em Moabe que devorará as fortalezas de Queriote. Moabe morrerá em alvoroço, com gritos e ao som de trombeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Eu destruirei o seu juiz e matarei todos os príncipes juntamente com ele\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Assim diz Yahweh: \"Por três pecados de Judá, mesmo por quatro, não retirarei o castigo, porque eles rejeitaram a Lei de Yahweh e não obedeceram aos Seus estatutos. As suas mentiras fizeram com que se perdessem, do mesmo modo que seus pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Enviarei fogo sobre Judá, que devorará as fortalezas de Jerusalém\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Assim diz Yahweh: \"Por três pecados de Israel, mesmo por quatro, não revogarei o castigo, porque eles venderam os inocentes por prata e os necessitados por um par de sandálias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Eles esmagam as cabeças dos pobres como as pessoas pisam no pó do chão. Eles afastam os oprimidos para longe. Um homem e o seu pai deitam-se com a mesma jovem, e assim profanam o Meu Santo Nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Eles deitam-se ao lado de cada altar sobre roupas penhoradas e na casa do seu Deus bebem o vinho dos que foram multados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'No entanto, Eu destruí o amorreu diante deles, cuja altura era como a altura dos cedros; ele era forte como os carvalhos. Destruí o seu fruto por cima e suas raízes por baixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Também vos fiz subir da terra do Egito e vos conduzi por quarenta anos no deserto, para que possuísseis a terra dos amoreus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Levantei profetas dentre vossos filhos e nazireus dentre vossos jovens. Não é assim, povo de Israel?\" Essa é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, '\"Mas vós persuadistes os nazireus a beberem vinho e ordenastes os profetas a não profetizarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Vê! Eu vos esmagarei como um carro cheio de grãos pode esmagar alguém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'A pessoa ágil não escapará, o forte não aumentará sua própria força nem o poderoso se salvará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'O arqueiro não resistirá, o corredor não escapará nem o cavaleiro se salvará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Mesmo os guerreiros mais corajosos fugirão nus naquele dia!\" Assim diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Ouvi esta palavra que Yahweh falou contra vós, povo de Israel, contra toda a família que tirei da terra do Egito:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, '\"Eu escolhi somente a ti, dentre todas as famílias da terra. Portanto, Eu te punirei por todos teus pecados.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Andarão dois juntos a não ser que estejam de acordo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Rugirá o leão na floresta quando ele não tem presa? Poderá o filhote de leão rosnar do seu esconderijo sem ter apanhado nada?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Pode um pássaro cair numa armadilha na terra quando a isca não está nela? A armadilha se levantará do chão sem ter apanhado coisa nenhuma?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Soará a trombeta numa cidade sem que as pessoas se estremeçam? Poderá vir um desastre sobre uma cidade o qual Yahweh não tenha enviado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Certamente, o Senhor Yahweh não fará nada, a menos que Ele revele Seu plano para Seus servos, os profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'O leão rugiu — quem não temerá? O Senhor Yahweh falou — quem não profetizará?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Proclamai isto nas fortalezas de Asdode e nas fortalezas na terra do Egito. Dizei: \"Reuni-vos nos montes de Samaria, e vede que grande confusão e opressão estão em seu meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Porque não sabem fazer o que é correto\". Assim diz Yahweh: \"Eles acumulam violência e destruição em suas fortalezas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Portanto, assim diz Yahweh: \"Um inimigo cercará a terra e derrubará suas cidadelas e pilhará suas fortalezas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Assim diz Yahweh: \"Como o pastor que retira da boca do leão apenas duas pernas ou um pedaço de uma orelha, assim o povo de Israel que vive em Samaria será resgatado, com apenas um canto de sofá ou somente um pedaço da cama\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Ouve e testifica contra a casa de Jacó — esta é a declaração do Senhor Yahweh, o Deus dos Exércitos:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, '\"Nos dias em que Eu punir os pecados de Israel, punirei também os altares de Betel, e os chifres do altar serão cortados e cairão no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Eu destruirei a casa de inverno juntamente com a casa de verão. As casas de marfim perecerão e grandes casas desaparecerão\". Assim diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Ouvi esta palavra, vacas de Basã, vós que estais no monte de Samaria, que oprimis o pobre, que esmagais o necessitado, e dizeis a vossos maridos: \"Trazei-nos bebidas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'O Senhor Yahweh jurou por Sua santidade: \"Vede, dias virão sobre vós, quando vos levarão com anzóis, os últimos de vós com arpões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Saireis pelas brechas dos muros, cada um de vós atravessareis e sereis lançados em direção do Harmon!\" Assim diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, '\"Vinde para Betel e pecai, ide para Gilgal e multiplicai os pecados. Trazei, todas as manhãs, os vossos sacrifícios; e os vossos dízimos, de três em três dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Oferecei sacrifícios de ações de graça com pão; proclamai ofertas voluntárias, anunciai-as, pois isso te agrada, ó povo de Israel!\" Assim diz o Senhor Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, '\"Eu vos deixei de dentes limpos, em todas as vossas cidades, e deixei faltar pão em todos os vossos lugares. No entanto, vós não voltastes para Mim\", assim diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, '\"Eu também retive de vós a chuva quando ainda faltavam três meses para a colheita. Eu fiz chover sobre uma cidade, e não fiz chover sobre a outra. Houve chuva em uma parte da terra, mas a parte de terra em que não choveu, essa secou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Duas ou três cidades cambaleavam até outra cidade para beber água, mas as pessoas não se saciavam. No entanto, vós não voltastes para Mim!\" assim diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, '\"Eu vos afligi com ferrugem e mofo. A multidão de teus jardins, tuas vinhas, tuas figueiras e tuas oliveiras, o gafanhoto a devorou. No entanto, vós não voltastes para Mim\", assim diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, '\"Eu enviei a praga sobre vós, como no Egito. Eu matei vossos jovens com a espada, arrastei vossos cavalos e fiz o mau cheiro dos vossos campos chegar a vossas narinas. No entanto, não vos voltastes para Mim\", assim diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, '\"Eu derrubei cidades no meio de ti, assim como derrubei Sodoma e Gomorra. Vós éreis como um tição tirado do fogo; no entanto, não voltastes para Mim\", assim diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Portanto, Eu farei algo terrível contigo, Israel! E porque Eu farei algo terrível contigo, prepara-te para te encontrares com teu Deus, Israel!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Porque é Ele que forma as montanhas e também cria o vento, revela Seus pensamentos à humanidade, faz a escuridão da manhã e pisa sobre os lugares altos da Terra. Yahweh, Deus dos Exércitos, é Seu Nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Ouvi estas palavras que Eu trago como um lamento sobre vós, casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'A virgem de Israel caiu; não se levantará mais; está esquecida em sua terra; não há quem a levante\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Pois assim diz o Senhor Yahweh: \"À cidade que saiu com mil restarão cem, e à que saiu com cem restarão dez dos que pertencem à casa de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Pois assim diz Yahweh à casa de Israel: \"Buscai-Me e vivei!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Não busqueis Betel; não entreis em Gilgal; nem passeis a Berseba. Porque Gilgal certamente será levada cativa, e Betel se tornará em nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Buscai a Yahweh e vivei, ou Ele irromperá como fogo na casa de José. Ele devorará, e não haverá ninguém para apagá-lo em Betel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Essas pessoas transformam a justiça em coisa amarga e lançam por terra a retidão!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Deus fez as Plêiades e o Órion; Ele muda a escuridão em alvorada; Ele torna o dia em trevas com a noite e chama as águas do mar; Ele as derrama na face da terra. Yahweh é o Seu nome!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Ele traz súbita destruição sobre o forte, para que a destruição venha sobre a fortaleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Eles odeiam todos aqueles que os corrigem às portas da cidade, e abominam todos os que falam a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Porque vós pisais o pobre e dele tomais porções de trigo. Embora tenhais construído casas de pedras trabalhadas, não vivereis nelas. Tendes deliciosas videiras, mas não bebereis do seu vinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Pois Eu sei quantas são as vossas ofensas e quão grandes são vossos pecados. Vós que afligis o justo, tomais o suborno e rejeitais o necessitado às portas da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'No entanto, neste momento, os prudentes estão em silêncio porque o tempo é mau.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Procurai o bem, e não o mal, para que possais viver. Pois Yahweh, o Deus dos Exércitos, certamente estará convosco, como dizeis que Ele está.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Odiai o mal, amai o bem; estabelecei a justiça às portas da cidade. Talvez Yahweh, o Deus dos Exércitos, seja gracioso com o remanescente de José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Portanto, assim diz Yahweh, o Deus dos Exércitos, o Senhor: \"Haverá lamento em todas as praças, e eles dirão em todas as estradas, \'Ai de nós!\' Eles chamarão os fazendeiros para o luto e os enlutados para lamentar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Dentro de toda vinha haverá lamento, porque Eu passarei pelo meio de vós\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Ai de vós que desejais o dia de Yahweh! Por que desejais o dia de Yahweh? Será de trevas, e não de luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Será como quando um homem foge de um leão, e um urso o encontra; ou ele entra numa casa, coloca sua mão na parede, e uma cobra o morde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Não será o dia de Yahweh um dia de trevas, e não de luz? De escuridão sem nenhuma claridade?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Odeio e detesto vossas festividades, não tenho prazer em vossas assembleias solenes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Apesar de me oferecerdes vossos holocaustos e ofertas de manjares, não os aceitarei, nem olharei para as ofertas pacíficas de vossos animais cevados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Tirai de Mim o ruído das vossas canções; não mais ouvirei o som de vossas harpas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Antes, deixai a retidão fluir como água; e a justiça, como um rio perene.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Foi para mim que trouxestes sacrifícios e ofertas no deserto por quarenta anos, casa de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Erguestes Sicute como vosso rei, e Quium, vosso deus astral, ídolos que fizestes para vós mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Por isso, Eu vos levarei para o exílio, além de Damasco\", diz Yahweh, cujo nome é o Deus dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Ai daqueles que estão tranquilos em Sião e daqueles que se sentem seguros no monte de Samaria, os homens notáveis das melhores nações, dos quais a casa de Israel busca auxílio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Vossos líderes dizem: \"Ide a Calné, e vede; depois ide a Hamate, a grande cidade; então, descei a Gate dos filisteus. São eles melhores do que vossos dois reinos? As fronteiras deles são mais extensas do que as vossas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Ai daqueles que afastam o dia da desgraça e fazem com que o trono da violência se aproxime.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Deitam-se nas camas de marfim e se estendem nos seus sofás. Comem cordeiros do rebanho e novilhos do curral.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Eles inventam canções tolas ao som da harpa; improvisam instrumentos, como fez Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Bebem vinho dos barris e se ungem com o mais fino óleo, mas não lamentam a ruína de José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Portanto, eles serão exilados com os primeiros deportados; os banquetes dos preguiçosos cessarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Eu, o Senhor Yahweh, jurei por Mim mesmo\". Esta é a declaração do Senhor Yahweh, o Deus dos exércitos: \"Eu detesto o orgulho de Jacó; Eu odeio suas fortalezas. Portanto, entregarei a cidade e tudo o que nela há\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'E acontecerá que, se dez homens restarem em uma casa, morrerão todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Se o familiar de um homem vier buscar seus cadáveres — aquele que for cremá-los, depois de retirar os corpos da casa — se ele disser para a pessoa na casa: \"Está alguém contigo?\", e essa pessoa disser: \"Não\", então ele dirá: \"Cala-te, pois não devemos mencionar o nome de Yahweh!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Pois, vede, Yahweh dará uma ordem, e a grande casa cairá em ruínas; e a casa pequena, em pequenos pedaços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Por acaso, correm os cavalos sobre as rochas? Ou se pode arar ali com bois? Vós, porém, transformastes justiça em veneno e o fruto da retidão em amargura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Vós, que vos alegrais sobre Lo-Debar, dizendo: \"Não tomamos Carnaim por nossa própria força?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, '\"Mas, vede, Eu levantarei contra vós uma nação, casa de Israel\", esta é a declaração do Senhor Yahweh, o Senhor dos Exércitos: \"Ela te afligirá desde Lebo-Hamate até a fonte de Arabá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Isto é o que o Senhor Deus mostrou-me. Eis que Ele formou gafanhotos quando a erva começou a germinar. Eis que essa era a erva serôdia depois da colheita do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Quando eles terminaram de comer a vegetação do solo, então eu disse: \"Senhor Yahweh, perdoa, por favor! Jacó é muito pequeno, como sobreviverá?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Yahweh cedeu com relação a isso. \"Isso não acontecerá\", disse Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Isto é o que o Yahweh me mostrou: Eis que o Senhor Yahweh chamou o fogo para julgar. Secou as grandes e profundas águas embaixo da terra e poderia ter devorado o solo também;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'mas eu disse: \"Senhor Yahweh, para, por favor! Jacó é muito pequeno. Como sobreviverá?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Yahweh cedeu acerca disso: \"Isso também não acontecerá\", disse o Senhor Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Isto é o que Ele me mostrou: Eis que o Senhor parou ao lado do muro, com um prumo nas Suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Yahweh me disse: \"Amós, o que vês?\". Eu disse: \"Um prumo\". Então, o Senhor disse: \"Olha, colocarei um prumo no meio do Meu povo Israel. Não vou mais poupá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Os lugares altos de Isaque serão destruídos; os santuários de Israel serão arruinados, e Me levantarei contra a casa de Jeroboão com a espada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Então, Amazias, o sacerdote de Betel, enviou mensagem para Jeroboão, rei de Israel: \"Amós conspirou contra ti no meio da casa de Israel. A terra não pode suportar todas as suas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Porque isto é o que Amós disse: \'Jeroboão morrerá pela espada, e Israel certamente será levado ao exílio longe da sua terra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Amazias disse a Amós: \"Vidente, vai. Foge de volta para a terra de Judá, come pão lá e profetiza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Mas não profetizes mais aqui em Betel, porque é o Santuário do rei e a casa real\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Então, Amós disse a Amazias: \"Eu não sou profeta, nem filho de profeta. Sou um vaqueiro e cultivador de sicômoros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Mas Yahweh me levou de onde eu estava pastoreando o rebanho e me disse: \"Vai, profetiza para o Meu povo Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Agora, ouve a palavra de Yahweh. Tu dizes: \"Não profetizes contra Israel e não fales contra a casa de Isaque\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Portanto, isto é o que Yahweh diz: \"Tua esposa será prostituta na cidade; teus filhos e tuas filhas cairão pela espada; a tua terra será medida e dividida; tu morrerás numa terra impura e, sem dúvida, Israel irá para o exílio fora da sua terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Isto é o que o Senhor Yahweh me mostrou. Vê, um cesto de frutas de verão!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Ele disse: \"O que vês, Amós?\". Eu disse: \"Um cesto de frutas de verão\". Então, Yahweh me disse: \"O fim chegou para Meu povo, Israel; não terei mais misericórdia para com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Os cânticos do templo se tornarão em lamentos. Naquele dia\", assim diz o Senhor Yahweh, \"os cadáveres serão muitos; em todos os lugares, serão lançados para fora, em silêncio!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Ouvi isto, vós que atropelais os necessitados e destruís os pobres da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Eles dizem: \"Quando passará a lua nova, para que possamos vender grãos de novo? E o sábado, quando passará, para que possamos vender o trigo? Vamos fazer a medida pequena e aumentar o preço, para trapacear com balanças enganadoras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Isto é, que possamos vender trigo ruim, comprar o pobre por prata e o necessitado por um par de sandálias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Yahweh jurou pelo orgulho de Jacó: \"Certamente Eu jamais vou esquecer qualquer de tuas ações.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Não tremerão por isso a terra e cada um que vive nela a chorar? Tudo isso encherá como o rio Nilo; subirá e baixará como o rio do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, '\"Isso virá naquele dia\", diz o Senhor Yahweh, \"que Eu vou fazer o sol se pôr ao meio dia e vou escurecer a terra em plena luz do dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Transformarei as vossas festas em velório, e todas as vossas canções em lamentações. Eu farei todos vós vestirdes roupas de saco e tereis as cabeças rapadas. Vou fazer isto como velório por um filho único, e o seu fim como um dia amargo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Vede, os dias estão vindo\", assim diz o Senhor Yahweh, \"quando Eu enviar a fome na terra — não fome de pão nem sede de água, mas de ouvir as palavras de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Eles irão cambaleando de mar em mar; correrão do norte para o leste, para procurar a palavra de Yahweh, mas não a encontrarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Naquele dia as belas virgens e os jovens vão desfalecer de sede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Aqueles que juram pelos pecados de Samaria, esses cairão e nunca se levantarão de novo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Eu vi o Senhor em pé, junto ao altar, e Ele disse: \"Bate no topo dos pilares, assim as fundações tremerão, de modo que se quebrem em pedaços sobre as cabeças deles. Eu matarei o último deles com a espada. Nenhum deles conseguirá fugir, nenhum deles escapará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Ainda que cavem até o Sheol, lá, Minha mão os tomará. Ainda que subam ao céu, de lá os farei descer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Ainda que se escondam no topo do Carmelo, lá os procurarei e os tomarei. Ainda que se escondam da Minha vista no fundo do mar, lá Eu darei ordem à serpente, e serão picados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Ainda que vão para o cativeiro, conduzidos por seus inimigos diante deles, lá Eu darei ordens para a espada, e ela os matará. Eu manterei Meus olhos sobre eles, para lhes causar mal, e não o bem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'O Senhor Yahweh dos Exércitos toca a terra, e ela se derrete; todos os que vivem nela pranteiam; tudo isso se levantará como rio e diminuirá novamente, como o rio do Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'É Ele que constrói sua escada nos céus, e tem estabelecido Seu firmamento sobre a terra. Ele chama as águas do mar e as derrama sobre a face da terra. Yahweh é Seu Nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Assim diz Yahweh: \"Povo de Israel, não sois para Mim como o povo da Etiópia? Não fiz Eu subir a Israel da terra do Egito; e os filisteus, do Caftor; e os sírios, de Quir?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Vede, os olhos do Senhor Yahweh estão sobre o reino pecaminoso, e Eu o destruirei da face da terra, mas não destruirei totalmente a casa de Jacó\". Esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, '\"Vede, Eu darei ordens e sacudirei a casa de Israel dentre as nações, como se agitam os grãos numa peneira, de modo que nem a menor pedra cairá no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Todos os pecadores do Meu povo morrerão pela espada, aqueles que dizem: \'Desastre não nos atingirá nem nos encontrará\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Naquele dia, levantarei a tenda de Davi, que caiu, e fecharei suas brechas. Levantarei suas ruínas e as reconstruirei como nos dias passados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Que eles possuam o remanescente de Edom e todas as nações que são chamadas pelo Meu Nome\". Esta é a declaração de Yahweh, que faz isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, '\"Vede, os dias virão\", diz Yahweh, \"em que o lavrador alcançará o que ceifa, e o que pisa as uvas alcançará o que planta as sementes. Então, as montanhas destilarão vinho doce, e todas as colinas derramarão dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Eu trarei de volta do cativeiro Meu povo Israel. Eles construirão as cidades arruinadas e habitarão nelas. Plantarão vinhas e beberão do seu vinho, farão jardins e comerão dos seus frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Eu os plantarei em suas terras, e eles nunca serão desarraigados da terra que lhes tenho dado\", diz Yahweh, teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Visão de Obadias. Assim diz o Senhor Yahweh a respeito de Edom: \"Temos ouvido uma mensagem de Yahweh, e um mensageiro foi enviado entre as nações, dizendo: \'Levantai-vos! Levantemo-nos contra ele para a batalha!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Eis que te farei pequeno entre as nações. Serás grandemente desprezado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'O orgulho do teu coração te enganou, tu que habitas nas fendas das rochas, em tua alta morada; que dizes em teu coração: \'Quem poderá me derrubar na terra?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Ainda que faças tua torre alta como a da águia, e ainda que faças o teu ninho entre as estrelas, Eu te derrubarei de lá\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, '\"Se ladrões viessem a ti ou assaltantes pela noite (como estás destruído!), não roubariam só o necessário? Se colhedores de uvas viessem a ti, eles não deixariam cachos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Esaú foi saqueado, teus tesouros escondidos, levados embora!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Todos os teus aliados te levarão para fora do teu território. Os homens que estão em paz contigo te enganaram, e prevaleceram contra ti. Os que comem o teu pão colocaram uma armadilha debaixo de ti. Não há entendimento neles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, '\"Não irei naquele dia\", diz Yahweh, \"que destruirei os sábios de Edom, e tirarei o entendimento do monte de Esaú?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Teus homens poderosos serão destruídos, ó Temã; então todo homem será exterminado do monte de Esaú pela matança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Por causa da violência feita a teu irmão Jacó, serás coberto de vergonha e serás exterminado para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'No dia em que estiveste distante, no dia em que inimigos levaram sua riqueza, e estrangeiros entraram por suas portas, e lançaram sortes sobre Jerusalém, eras como um deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Mas não devias olhar com prazer o dia do teu irmão, o dia de sua desgraça e nem alegrar-te sobre o povo de Judá no dia de sua destruição. Não sejas insolente no dia do seu sofrimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Não entres pela porta do Meu povo no dia da sua calamidade; não olhes para sua aflição no dia do seu desastre, não lances mão dos seus bens no dia de sua ruína.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Não fiques nas encruzilhadas para matar seus fugitivos. Não ponhas tua mão sobre os seus sobreviventes no dia da angústia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'O dia do Senhor Yahweh virá breve sobre todas as nações. Como tens feito, assim será feito a ti; as tuas ações se voltarão contra tua própria cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Assim como bebeste no Meu Santo Monte, também todas as nações beberão continuamente. Elas beberão e engolirão, e serão como se nunca tivessem existido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Mas no Monte Sião estarão aqueles que escaparem, e ele será santo; e a casa de Jacó possuirá suas próprias heranças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'A casa de Jacó será fogo, e a casa de José uma labareda, e a casa de Esaú como palha seca, e eles irão queimá-los e consumi-los. Não haverá sobreviventes da casa de Esaú\", Yahweh o disse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, '\"E aqueles que são do Neguebe possuirão a montanha de Esaú, e os da planície de Sepelá possuirão as terras dos filisteus; e eles possuirão a terra de Efraim, e a terra de Samaria; e Benjamim possuirá Gileade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Os exilados do exército do povo de Israel possuirão a terra de Canaã até Sarepta. Os exilados de Jerusalém, que estão em Sefarade, possuirão as cidades de Neguebe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Os libertadores subirão para o monte Sião para julgarem o monte de Esaú, e o reino será de Yahweh.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'A palavra de Yahweh veio a Jonas, filho de Amitai, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, '\"Levanta-te e vai a Nínive, aquela grande cidade, e clama contra ela, porque a sua maldade subiu até mim.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Mas Jonas levantou-se em direção a Társis, para fugir da presença de Yahweh. Ele desceu até Jope e encontrou um navio que estava de partida para Társis. Assim, ele pagou a passagem e embarcou no navio com eles para Társis, para longe da presença de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Mas Yahweh mandou uma forte ventania sobre o mar, que se tornou em uma grande tempestade. Parecia que o navio estava a ponto de se despedaçar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Então, os marinheiros ficaram com muito medo e cada um gritou ao seu próprio deus. Eles jogaram a carga do navio no mar para torná-lo mais leve. Mas Jonas havia descido ao porão do navio, onde dormia profundamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Então o capitão veio até ele e disse-lhe: \"Por que tu estás dormindo? Levanta-te! Invoca o teu deus! Talvez teu deus tenha piedade e não pereçamos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Todos diziam uns aos outros: \"Vinde, lancemos sortes, para que possamos saber quem é a causa deste mal que está acontecendo conosco.\" Então, eles lançaram sortes, e a sorte caiu sobre Jonas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Então eles disseram a Jonas: \"Por favor, conta-nos quem é a causa deste mal que está acontecendo conosco. Qual é a tua ocupação e de onde tu vens? Qual é o teu país e de que povo és?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Jonas disse-lhes: \"Eu sou hebreu e temo a Yahweh, o Deus do céu, que fez o mar e a terra seca.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Então os homens estavam ainda mais assustados e disseram a Jonas: \"O que é isso que fizeste?\" Pois os homens compreenderam que ele estava fugindo da presença de Yahweh, pelo que havia declarado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Então disseram a Jonas: \"O que devemos fazer contigo para que o mar se acalme para nós?\" Pois o mar tornou-se cada vez mais violento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Jonas disse-lhes: \"Levantai-me e jogai-me dentro do mar. Então o mar ficará calmo para vós, pois sei que é por minha causa que esta forte tempestade veio até vós.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Entretanto, os homens remaram intensamente para conseguir voltar à terra, mas eles não conseguiram, porque o mar estava tornando-se mais e mais violento contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Então, eles clamaram a Yahweh e disseram: \"Nós suplicamos a Ti, Yahweh, nós a Ti rogamos, não nos deixes perecer por causa da vida deste homem e não coloques sobre nós a culpa de sua morte, porque Tu, Yahweh, tens feito apenas o que Te agrada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Então eles pegaram Jonas e lançaram ao mar; e a fúria do mar cessou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Então os homens temeram muito a Yahweh. Eles ofereceram sacrifícios a Yahweh e fizeram votos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'Ora, Yahweh preparou um grande peixe para engolir Jonas; e Jonas esteve no ventre do peixe três dias e três noites.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'E orou Jonas a Yahweh, seu Deus, das entranhas do peixe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'E disse: \"Na minha angústia clamei a Yahweh e Ele me respondeu; do ventre do Sheol gritei por socorro e Tu ouviste a minha voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Tu me lançaste no profundo, no coração dos mares, e as correntes me rodearam; todas as Tuas ondas e Tuas torrentes passaram sobre mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Então eu disse: Fui expulso de diante dos Teus olhos; tornarei, porventura, a ver o Teu santo templo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'As águas me cercaram até a alma; o abismo estava à minha volta, as algas se enrolaram na minha cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Eu desci até às bases das montanhas; as trancas da terra me encarceraram para sempre. Mesmo assim, trouxeste a minha vida de volta da cova, Ó Yahweh, meu Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Quando a minha alma já desfalecia dentro de mim, eu me lembrei de Yahweh; então a minha oração subiu a Ti, no Teu santo templo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Aqueles que se apegam aos falsos ídolos afastam de si a Tua misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Quanto a mim, oferecerei a Ti sacrifícios com voz de agradecimento; o que prometi, cumprirei. A Yahweh pertence a salvação!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Falou, pois, Yahweh ao peixe, o qual vomitou Jonas sobre a terra seca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'A palavra de Yahweh veio a Jonas pela segunda vez, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, '\"Levanta, vai a Nínive, aquela grande cidade, e proclama a ela a mensagem que te ordenei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Então Jonas se levantou e foi para Nínive, em obediência à palavra de Yahweh. Era cidade muito grande, sendo necessários três dias para percorrê-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Jonas entrou na cidade e a percorreu durante um dia, proclamando: \"Daqui a quarenta dias, Nínive será destruída\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Os habitantes de Nínive creram em Deus e proclamaram um jejum. Todos puseram sobre si panos de saco, desde o maior até o menor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Quando a notícia chegou ao rei de Nínive, ele se levantou do trono, tirou as vestes reais, cobriu-se com pano de saco e sentou-se sobre cinzas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Então fez uma proclamação e a publicou em Nínive: \"Pelo decreto do rei e seus nobres, não há permissão para homem ou animal, manada ou ovelha comer coisa alguma. Não os deixeis comer, nem beber água,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'mas sejam cobertos de pano de saco, tanto os homens como os animais, e clamem a Deus com força. Cada um abandone seus maus caminhos e a violência que está em suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Quem sabe abrirá Deus mão de Sua ira e mudará Sua decisão, para que não sejamos destruídos?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'E Deus viu o que fez o povo, como abandonou seus maus caminhos. Então Deus mudou de ideia sobre a punição que Ele disse que lhe faria, e não o fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Mas isso desagradou a Jonas, e ele ficou muito irado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Então Jonas orou a Yahweh e disse: \"Ó, Yahweh, não foi isso o que eu disse quando estava no meu próprio país? Por isso eu fugi apressadamente para Társis, porque eu sabia que Tu és um Deus gracioso, compassivo, longânimo, abundante em fidelidade, e que mudas de ideia quanto ao mal que anunciaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Por isso, Yahweh, agora eu peço, tira-me a vida, porque para mim é melhor morrer do que viver.\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Yahweh disse: \"É razoável essa tua ira?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Então Jonas saiu da cidade e sentou-se ao oriente dela. Ali fez para si um abrigo e sentou-se debaixo dele, à sombra, a fim de ver o que aconteceria à cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Yahweh fez crescer uma planta por cima de Jonas para que lhe fizesse sombra sobre a cabeça, a fim de o livrar de sua aflição. Jonas se alegrou muito por causa da planta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Mas Deus, no dia seguinte, ao nascer do sol, enviou um verme, que atacou a planta e ela secou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Aconteceu que, quando o sol nasceu na manhã seguinte, Deus enviou um vento oriental muito quente. Então o sol bateu na cabeça de Jonas e ele desmaiou. Então Jonas desejou morrer. Ele disse a si mesmo: \"Melhor para mim é morrer do que viver.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Então Deus disse a Jonas: \"É razoável essa tua ira por causa da planta?\" Então Jonas disse: \"É justo que eu esteja irado, até a morte.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Yahweh disse: \"Tu te compadeceste da planta, pela qual não tiveste que trabalhar, nem a fizeste crescer. Ela cresceu numa noite e numa noite morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Então não deveria Eu ter compaixão da grande cidade de Nínive, na qual há mais de cento e vinte mil pessoas que não sabem a diferença entre sua mão direita e sua mão esquerda, além de muitos animais?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Esta é a palavra de Yahweh, vinda em visão a Miqueias, o morastita, nos dias de Jotão, Acaz e Ezequias, reis de Judá, a respeito de Samaria e Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Ouvi, vós todos os povos. Ouvi, ó terra, e tudo que está em ti. Seja o Senhor Yahweh testemunha contra vós, o Senhor, do Seu santo templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Vede! Yahweh sai do Seu lugar; Ele descerá e pisará sobre os lugares altos na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'As montanhas se derreterão diante Dele; os vales serão derretidos como a cera diante do fogo, como águas que são derramadas de lugares elevados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Tudo isso por causa da rebelião de Jacó e por causa dos pecados da casa de Israel. Qual foi o motivo da rebelião de Jacó? Não foi Samaria? E dos lugares altos de Judá? Não foi Jerusalém?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Farei de Samaria um monte de ruínas no campo, como um lugar para plantar vinhedos. Levarei suas pedras de construção para os vales e deixarei suas fundações expostas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Todas as suas imagens esculpidas serão quebradas em pedaços; e todas as ofertas para ela serão queimadas. E de todos os seus ídolos farei uma ruína. Pois ela os ajuntou pelo pagamento de uma prostituta e por pagamento de uma prostituta eles voltarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Por essa razão, lamentarei e uivarei; andarei descalço e nu; lamentarei como os chacais e gemerei como a coruja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Porque suas feridas são incuravéis, pois chegaram até Judá, e alcançaram o portão do meu povo, até Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Não faleis sobre isso em Gate; nem tampouco choreis. Em Bete-Leafra, eu me revolvo no pó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Passai, habitantes de Safir, em vergonha e nudez. Não saiais, habitantes de Zaanã. Bete-Ezel, pranteai, porque a vossa proteção foi tirada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Porque os habitantes de Marote esperam ansiosamente por boas novas, pois de Yahweh desceu a calamidade até os portões de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Atai os cavalos às carruagens, ó habitantes de Laquis. Tu, Laquis, foste o princípio do pecado para a filha de Sião, porque a transgressão de Israel foi achada em ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Por isso, oferecerás um presente de despedida a Moresete-Gate; a cidade de Acazib enganará os reis de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Eu trarei um conquistador para vós, habitantes de Maressa; o esplendor de Israel virá a Adulão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Raspai vossas cabeças e cortai vossos cabelos por causa dos filhos de tuas delícias. Ficai calvos como águias, pois vossos filhos serão levados ao exílio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Ai daqueles que planejam a iniquidade, daqueles que, em suas camas, planejam fazer o mal. Pela manhã o fazem porque têm poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Eles desejam os campos e os arrebatam; eles desejam as casas e as tomam. Eles oprimem um homem e sua casa, ele e sua herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Portanto, assim diz Yahweh: \"Eis que estou prestes a trazer uma calamidade contra essa família, da qual não podereis vos livrar. Não caminhareis arrogantemente porque será um tempo mau.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Naquele dia, vossos inimigos cantarão uma canção sobre vós, e levantarão um pranto lastimoso, entoando: \'Nós, israelitas, estamos completamente arruinados; Yahweh mudou o território do nosso povo. Como Ele pode removê-lo de nós? Ele reparte os nossos campos com os traidores!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Assim, vós, ricos, não tereis descendentes para dividir o território por sorteio, na assembleia de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '\'Não profetizeis\' — dizem eles. \'Eles não devem profetizar essas coisas; as injúrias não virão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Por acaso, isso deve realmente ser dito, casa de Jacó? \'Está o Espírito de Yahweh irado? Estes são realmente Seus feitos?\'. As Minhas palavras não fazem bem para aqueles que andam retamente?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Ultimamente, o Meu povo se levantou como um inimigo. Vós tirastes a capa, a vestimenta daqueles que passavam sem suspeita, como soldados que regressam da batalha para o que pensam que é segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Vós tirastes as mulheres que pertencem ao Meu povo de suas casas agradáveis; tirastes para sempre a Minha benção dos seus filhos mais jovens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Levantai e ide, pois este não é um lugar onde deveis ficar; por causa da impureza, ele será completamente destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Se alguém viesse a vós, com um espírito de falsidade e mentira, e dissesse: \'Eu profetizarei a vós acerca do vinho e da bebida forte\', ele seria considerado um profeta para este povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Certamente, Eu ajuntarei a todos vós, Jacó. Certamente, reunirei o remanescente de Israel. Irei reuni-los como ovelhas num aprisco, como rebanho no meio do seu pasto. Haverá um barulho alto por causa da multidão de pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Alguém que abre o caminho irá adiante deles. Eles atravessarão o portão e sairão; seu rei irá adiante deles. Yahweh estará à sua frente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Eu disse: \"Agora ouvi, vós, líderes de Jacó e chefes da casa de Israel: não é certo que vós entendeis a justiça?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Odiais o bem e amais o mal, vós que tirais a pele do Meu povo e a carne de seus ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Vós também comeis sua carne, e arrancais a pele, quebrais seus ossos, e os repartis em pedaços, como carne na panela, assim como carne no caldeirão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Então, vós, governantes, clamareis a Yahweh, mas Ele não vos responderá. Naquele tempo, Ele esconderá a Sua face de vós, porque praticastes más obras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Assim diz Yahweh a respeito dos profetas que fazem vaguear o Meu povo: \"Para aqueles que os alimentam, eles anunciam: \'Haverá prosperidade\'. Mas, para os que não põem nada em suas bocas, contra esses, eles começam uma guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Portanto, será noite para vós, sem visão alguma; tereis trevas para que não façais nenhuma adivinhação. O sol se porá sobre os profetas, e o dia se escurecerá para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Os videntes serão envergonhados, e os adivinhadores se confundirão. Todos eles cobrirão os seus lábios, porque de Mim não haverá resposta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Mas, quanto a mim, estou cheio do Poder pelo Espírito de Yahweh, e cheio de justiça e de força, para declarar a Jacó a sua transgressão, e para Israel o seu pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Agora, ouvi isto, vós, líderes da casa do Jacó, e chefes da casa de Israel, vós que detestais a justiça e perverteis tudo que é direito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Construístes Sião com sangue e Jerusalém com iniquidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Os vossos líderes dão sentenças por suborno, vossos sacerdotes ensinam por lucro, e vossos profetas adivinham por dinheiro. E ainda confiais em Yahweh, e dizeis: \"Não está Yahweh conosco? Nenhum mal virá sobre nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Portanto, por causa de vós, Sião será lavrada como um campo, Jerusalém se tornará um amontoado de escombros, e o monte do Templo será como um matagal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Mas, nos últimos dias, acontecerá que o monte da Casa de Yahweh será estabelecido sobre os outros montes; será exaltado sobre as colinas e para ele afluirão os povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Muitas nações irão e dirão: \"Vinde, subamos ao monte de Yahweh, para a Casa do Deus de Jacó. Ele ensinará Seus caminhos e andaremos em Seus passos.\" Porque a Lei virá de Sião e a palavra de Yahweh, de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Ele julgará entre muitos povos e será o árbitro sobre muitas nações longínquas. De suas espadas farão arados, e das suas lanças, foices. Nação não mais levantará a espada contra outra nação, nem mais treinarão para a guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Em vez disso, eles sentarão, cada um debaixo da sua videira e debaixo da sua figueira. Ninguém os fará temer, porque a Boca de Yahweh dos exércitos falou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Porque todos os povos andam, cada um, em nome do seu deus. Mas nós andaremos no Nome de Yahweh, nosso Deus, para todo o sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, '\"Naquele dia\", diz Yahweh, \"irei congregar a que mancava e ajuntar a que fora exilada, aqueles que Eu afligi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Farei da que manca remanescente e dos que foram exilados uma nação forte; e Eu, Yahweh, reinarei sobre eles no monte Sião, agora e para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'E tu, torre de guarda do rebanho, fortaleza da filha de Sião, a ti virá, sim, a restauração do teu domínio antigo, o reino que pertence à filha de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Agora, por que gritas tão alto? Não há rei no meio de ti? Teu conselheiro morreu? É por isso que foste tomado de dores como de uma mulher que está em trabalho de parto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Sofre dores e esforça-te para dar à luz, como uma mulher em trabalho de parto, ó filha de Sião. Porque agora sairás da cidade, viverás no campo e irás para Babilônia. Ali, serás resgatada. Ali, Yahweh vai te resgatar das mãos de teus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Agora muitas nações se congregaram contra ti; elas dizem: \'Que Jerusalém seja profanada, que nossos olhos se regozijem sobre Sião.\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'O profeta diz: \"Eles não conhecem os pensamentos de Yahweh, nem entendem Seus planos, pois Ele juntou as nações como feixes para a eira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Yahweh diz: \"Levanta-te e castiga, ó filha de Sião, porque farei de ferro os teus chifres e de bronze os teus cascos. Tu esmagarás muitos povos e consagrarei tuas riquezas injustas e teus bens para Mim mesmo, Yahweh, o Senhor de toda terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Agora, ajunta-te em posição de batalha, filha de guerreiros. Os guerreiros montaram um cerco ao redor da cidade, com uma vara eles batem na face do Juiz de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Mas tu, Belém Efrata, ainda que sejas pequena entre as famílias de Judá, de ti virá para Mim Aquele que governará em Israel, cuja procedência é desde os tempos antigos, desde a eternidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Portanto Deus os abandonará até o momento em que aquela que está em trabalho de parto dê à luz um filho, e o restante dos seus irmãos voltem aos filhos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Ele Se levantará e pastoreará Seu rebanho, na força de Yahweh, na majestade do Nome de Yahweh, seu Deus. Eles permanecerão, porque naquele tempo Ele será grande até os confins da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Ele será nossa paz. Quando os assírios vierem para a nossa terra, quando marcharem contra nossas fortalezas; então, levantaremos contra eles sete pastores e oito nobres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Esses homens pastorearão a terra da Assíria, com a espada, e a terra de Ninrode, em suas entradas. Ele nos resgatará dos assírios, quando eles vierem para a nossa terra, quando marcharem dentro das nossas fronteiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'O remanescente de Jacó estará entre muitos povos, como o orvalho de Yahweh, como os chuviscos sobre a relva, que não esperam pelo homem, nem pelos filhos dos seres humanos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'O remanescente de Jacó estará entre as nações, no meio de muitos povos, como o leão entre os animais da floresta, como um leãozinho entre os rebanhos das ovelhas. Quando ele passar por eles, irá pisá-los e despedaçá-los, e não haverá quem poderá salvá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Tua mão estará levantada contra teus inimigos e ela os destruirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, '\"Acontecerá naquele Dia\", diz Yahweh \"que destruirei do meio de ti os teus cavalos e demolirei tuas carruagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Eu destruirei as cidades da tua terra e derrubarei todas as tuas fortalezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Eu destruirei a feitiçaria das tuas mãos, e não terás mais advinhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Eu destruirei tuas imagens esculpidas e tuas colunas sagradas de pedra, que estão no meio de ti. Não mais adorarás as obras de tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Eu arrancarei do teu meio os postes de Aserá, e destruirei tuas cidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'Eu executarei vingança com ira e furor sobre as nações que não Me obedeceram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Agora, ouvi o que Yahweh diz: \"Levanta-te e põe tua causa diante dos montes; que as colinas ouçam a tua voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Escutai a acusação de Yahweh, vós, montes, e vós, fundações firmes da terra. Porque Yahweh tem uma acusação contra o Seu povo, e Ele entrará em juízo contra Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, '\"Povo Meu, o que fiz para se cansarem de Mim? Responde-Me!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Pois Eu te tirei da terra de Egito e te resgatei da casa da servidão. Enviei Moisés, Arão e Miriã para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Meu povo, lembra-te do que Balaque, rei de Moabe, edificou, e o que Balaão, filho de Beor, respondeu-lhe quando saíste de Sitim para Gilgal, para que conheças os atos de justiça de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'O que poderei trazer a Yahweh, quando me prostrar ao Deus Altíssimo? Poderia me apresentar diante Dele, oferecendo, em holocausto, bezerros de um ano de idade?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Yahweh se agradaria com milhares de carneiros, ou com dez mil rios de azeite? Daria o meu primogênito pelas minhas transgressões, o fruto do meu corpo pelo meu próprio pecado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Ele te disse, ó homem, o que é bom e o que Yahweh requer de ti: age com justiça, ama a misericórdia, e anda humildemente para com o teu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'A voz de Yahweh proclama para a cidade, mesmo agora a sabedoria reconhece o Teu Nome: \"Olha para o cajado, para Aquele que o colocou no lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Há riquezas na casa do perverso, que é desonesto, e falsas balanças, que são abomináveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Deveria considerar alguém como inocente se ele usa balanças fraudulentas, com uma bolsa de pesos enganosos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Os ricos estão cheios de violência, os habitantes têm falado mentiras, e a língua deles é enganosa em sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Portanto, Eu te ferirei com um ferimento severo e te deixarei em ruínas por causa de teus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Comerás, mas não te satisfarás; o vazio que há em ti permanecerá. Acumularás bens, mas não se conservarão, e o que conservares darei à espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Semearás, mas não colherás; prensarás azeitonas, mas não te ungirás com azeite; pisarás uvas, mas não beberás vinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Os estatutos feitos por Onri têm sido guardados, assim como todas as obras da casa de Acabe. Tens andado nos conselhos deles. Por isso te farei uma cidade em ruínas, e dos teus habitantes, um objeto de assobio, e serás desprezado como Meu povo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Ai de mim! Sou como quem colhe frutos do verão após o período da colheita, após o respigo das uvas nos vinhedos: não há mais cachos de frutas para encontrar, nem figo novo, que tanto desejo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'As pessoas piedosas desapareceram da terra e não há sequer uma pessoa justa em toda humanidade. Todos mentem, preparando armadilhas para derramar sangue; cada um caça seu próprio irmão com uma rede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'As suas mãos são boas só para fazer o mal: o governante exige dinheiro, o juiz aceita suborno, e o homem poderoso está dizendo aos outros o que quer obter. Assim, eles tramam juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'O melhor deles é como um espinheiro, o mais justo entre eles é pior que uma cerca de espinhos. Este é o dia que foi predito por teus sentinelas, o dia da tua punição. Agora começará a confusão deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Não acrediteis em nenhum vizinho; nem ponhais a vossa confiança em nenhum amigo. Tende cuidado com o que dizeis, até mesmo para a mulher que se deita nos vossos braços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Porque o filho desonra seu pai, a filha levanta-se contra sua mãe, e a nora, contra sua sogra. Os inimigos do homem são as pessoas da sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Mas, quanto a mim, olharei para Yahweh. Esperarei pelo Deus da minha salvação; meu Deus me ouvirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Não te alegres a respeito de mim, minha inimiga; ainda que eu tenha caído, eu me levantarei. Quando me sentar nas trevas, Yahweh será a minha luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Porque pequei contra Yahweh, suportarei a Sua ira, até que Ele julgue meu caso e execute Seu juízo sobre mim. Ele me levará para a luz, e O verei regastar-me em Sua justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Então, minha inimiga verá isso e será coberta de vergonha, ela, que havia dito: \"Onde está Yahweh, o teu Deus?\". Meus olhos olharão para ela; será pisada como a lama nas ruas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'O dia para construir teus muros virá; neste dia, tuas divisas serão expandidas para mais longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Naquele dia, teu povo virá para ti, da Assíria e das cidades do Egito, desde o Egito até o grande rio, o Eufrates, de mar a mar e de montanha a montanha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Essas terras serão abandonadas, por causa das pessoas que estão vivendo lá agora, por causa do fruto de suas ações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Pastoreia o Teu povo com Tua vara, o rebanho da Tua herança. Eles vivem sozinhos em uma floresta, cercados de terras férteis. Deixa que pastem em Basã e Gileade, como nos dias antigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, '\"Como no dia em que saístes da terra do Egito, Eu lhes mostrarei maravilhas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'As nações verão e ficarão envergonhadas com o poder deles. Colocarão as mãos em suas bocas; seus ouvidos ficarão surdos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Elas lamberão a poeira como a cobra, como as criaturas que rastejam na terra. Elas sairão tremendo de suas tocas; com pavor, virão a Ti, Yahweh, nosso Deus, e temerão por Tua causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Quem é Deus igual a Ti, que tiras o pecado, que perdoas as transgressões do remanescente da Tua herança? Não manténs Tua ira para sempre, porque Tu amas nos mostrar Teu amor leal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Tu, novamente, terás compaixão de nós; Tu colocarás nossas iniquidades debaixo de Teus pés. Tu lançarás todos os nossos pecados nas profundezas do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Darás a verdade para Jacó e o amor leal a Abraão, como Tu juraste a nossos antepassados nos dias antigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'A mensagem de sentença acerca de Nínive. O livro da visão de Naum, o elcosita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Yahweh é um Deus ciumento e vingador; Yahweh é vingador e está furioso; Yahweh Se vinga dos Seus adversários, e Ele conserva Sua ira contra Seus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Yahweh demora para Se irar e grande em poder; Ele não inocentará Seus inimigos. Yahweh faz Seu caminho no redemoinho e na tempestade, e as nuvens são o pó dos Seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Ele repreende o mar e o faz secar; Ele seca todos os rios. Basã está fraco, e o Carmelo também; as flores do Líbano estão murchas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Os montes tremem na Sua presença, e as colinas se dissolvem; a terra desmorona na Sua presença, de fato, o mundo e todos os que vivem nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Quem pode ficar em pé diante do Seu furor? Quem pode resistir à Sua ira ardente? Sua ira é derramada como fogo, e as rochas são quebradas por Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Yahweh é bom, uma fortaleza no dia da angústia; Ele é fiel aos que se refugiam Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Porém, Ele acabará de vez com os Seus inimigos, com uma devastadora inundação; Ele os perseguirá até à escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'O que planejais contra Yahweh? Ele acabará de vez com isso; a aflição não se levantará pela segunda vez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Porque, eles ficarão enredados como num emaranhado de espinhos; ficarão bêbados em seu próprio vinho; serão completamente devorados pelo fogo, como a palha seca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Alguém se levantou entre vós, Nínive, que planejou o mal contra Yahweh, alguém que promoveu maldades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Assim diz Yahweh: \"Mesmo que eles sejam mais fortes e mais numerosos, no entanto serão destruídos; seu povo não mais existirá. Mas tu, Judá: Embora Eu tenha afligido a ti, não te afligirei mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Agora quebrarei o jugo daquele povo de sobre ti; quebrarei tuas correntes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Yahweh deu uma ordem a teu respeito, Nínive: \"Não haverá mais descendentes com teu nome. Eu extirparei tuas imagens de escultura e imagens de fundição das casas dos teus deuses. Eu cavarei teus sepulcros, pois és desprezível\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Vê, sobre os montes estão os pés daquele que está trazendo boas novas, que está anunciando paz! Celebra tuas festas, Judá, e guarda os teus votos, porque o perverso não te invadirá mais; ele será completamente extirpado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Aquele que te despedaçará está vindo contra ti. Guarda as muralhas da cidade, vigia as estradas, fortalece-te, junte os teus exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Pois Yahweh está restaurando a majestade de Jacó, como a majestade de Israel, embora os saqueadores tenham devastado e destruído seus ramos de videira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Os escudos dos seus homens poderosos são vermelhos e os homens corajosos estão vestidos de escarlate; as carruagens brilham com seus metais no dia da sua preparação e as lanças de cipreste vibram no ar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'As carruagens correm velozmente nas ruas, elas correm apressadamente de um lado para o outro nas ruas largas. Eles são como tochas, e correm como o relâmpago.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Aquele que te despedaçará chama seus oficiais; eles tropeçam uns nos outros no seu caminho; eles se apressam para proteger o muro da cidade. O largo escudo está de prontidão para proteger desses ataques.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'As comportas dos rios são forçadas e se abrem e o palácio cai em ruínas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'A rainha é despojada de suas vestes e é levada cativa; as suas servas gemem como pombas, batendo nos seus seios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Nínive é como um reservatório que vaza água, com o seu povo fugindo como água que escorre. Outros gritam: \"Parai, parai\", mas ninguém olha para trás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Saqueai a prata, saqueai o ouro, pois não há fim para o esplendor de todas as coisas bonitas de Nínive.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Nínive está vazia e arruinada. O coração de todos derrete, os joelhos de todos tremem juntos, e a angústia está em todos; suas faces estão pálidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Onde está, agora, a toca dos leões, o lugar onde os jovens leões se alimentavam, o lugar onde o leão e a leoa caminhavam, com os filhotes, onde não tinham medo de nada?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'O leão rasgava suas vítimas em pedaços para seus filhotes; ele estrangulava presas para suas leoas, e enchia sua caverna com presas; suas tocas, com carcaças despedaçadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, '\"Vê, Eu estou contra ti\" — esta é a declaração de Yahweh dos Exércitos. \"Eu queimarei os teus carros na fumaça, e a espada devorará os teus jovens leões. Eu exterminarei a tua presa de tua terra, e as vozes de teus mensageiros não serão mais ouvidas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Ai da cidade sanguinária! Ela está toda cheia de mentiras e de propriedades roubadas. Sempre fazendo suas vítimas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Mas agora há ruído de chicotes e barulhos das batidas das rodas, o galopar dos cavalos e carruagens que saltam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Há cavaleiros que atacam, espadas reluzentes, lanças brilhantes, amontoados de cadáveres, grandes pilhas de corpos. Não há fim para os corpos. Os que os atacaram tropeçam sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Isso está acontecendo devido às ações lascivas da bela prostituta, mestra em feitiçarias, que vende nações, por meio da sua prostituição, e famílias por meio de suas feitiçarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, '\"Vê, Eu estou contra ti\" — esta é a declaração de Yahweh dos Exércitos — \"Eu levantarei a tua saia sobre o teu rosto e mostrarei a tua nudez às nações, a tua vergonha aos reinos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Lançarei imundícias sobre ti e te tratarei com desprezo; farei de ti alguém a quem todos olharão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'E acontecerá que todo aquele que te olhar fugirá de ti e dirá: \'Nínive está destruída. Quem chorará por ela?\' Onde posso encontrar alguém para te confortar?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Nínive, por acaso tu és melhor do que Tebas, aquela que foi construída junto ao rio Nilo, a que tinha água a sua volta, que tinha o oceano como defesa e o mar como muros?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Etiópia e Egito eram a sua força, uma força sem limites; Pute e Líbia, seus aliados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Mesmo assim, Tebas foi levada; ela foi em cativeiro, suas criancinhas foram despedaçadas nas entradas de toda rua; suas inimigas lançaram sortes pelos seus homens nobres, e todos os seus grandes homens foram acorrentados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Tu também ficarás embriagada. Tentarás te esconder e buscarás refúgio contra os teus inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Todas as tuas fortalezas serão como figueiras com figos novos: se forem sacudidos, cairão na boca de quem os come.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Vê, as pessoas no meio de ti são mulheres; os portões da tua terra foram escancarados aos teus inimigos; o fogo devorou os teus ferrolhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Vai tirar água e guardar para quando vier o cerco; reforça as tuas fortalezas; entra no barro e pisa a argamassa; prepara as formas para fazer os tijolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'O fogo te devorará ali e a espada te destruirá. Ele te devorará como os gafanhotos jovens devoram tudo. Multiplica-te como muitos gafanhotos jovens, como muitos gafanhotos adultos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Tu multiplicaste os teus comerciantes mais do que as estrelas dos céus; mas eles parecem gafanhotos jovens: eles pilham a terra e depois voam para longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Os teus príncipes são tantos quanto gafanhotos adultos e os teus generais são como nuvens de gafanhotos, que se acampam nas paredes, num dia frio. Mas, quando o sol se levanta, esses fogem e ninguém sabe para onde foram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Rei da Assíria, os teus pastores estão adormecidos, os teus governadores estão descansando. Teu povo está espalhado pelos montes e não há ninguém para o reunir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Não há cura possível para as tuas feridas. Tuas feridas são graves. Todos os que ouvirem as notícias acerca de ti baterão palmas por tua causa. Quem já escapou da tua maldade constante?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'A mensagem que o profeta Habacuque recebeu:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, '\"Yahweh, até quando devo clamar por ajuda, e Tu não ouvirás? Tenho gritado a Ti: \'Violência!\', mas Tu não me salvas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Por que Tu me fazes ver a iniquidade e contemplar a transgressão? Destruição e violência estão diante de mim; há dissenção e se levantam contendas!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Por isso, a Lei é enfraquecida e a justiça não dura tempo algum. Pois os maus cercam os justos; por isso, a falsa justiça sobressai\". Yahweh responde a Habacuque:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, '\"Olha as nações e as examina; deslumbra-te e maravilha-te! Pois certamente farei algo em teus dias que não acreditarás quando te for anunciado a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Pois, vê! Estou prestes a levantar os caldeus, aquela nação feroz e impetuosa, que está marchando por toda a largura da Terra, para se apoderarem de casas que não lhes pertencem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'São aterrorizantes e amedrontadores; deles mesmos procedem seu julgamento e esplendor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Seus cavalos também são mais velozes que leopardos, mais rápidos que lobos ao entardecer. Assim, seus cavalos trotam e seus cavaleiros vêm de grande distância; eles voam como uma águia que se apressa para comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Todos eles vêm para trazer violência, suas multidões vão como o vento do deserto e eles juntam os cativos como areia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Então, eles zombam dos reis, e os governantes são apenas objeto de escárnio para eles. Eles riem a cada fortaleza, porque amontoam terras e as tomam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Então, o vento se moverá velozmente e passará — eles são homens culpados, cujo deus é sua força\". Habacuque faz outra pergunta a Yahweh:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, '\"Tu não vens de tempos antigos, Yahweh, meu Deus, meu Santo? Nós não morreremos. Yahweh os destinou para julgamento, e Tu, Rocha, os estabeleceste para correção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Teus olhos são puros demais para contemplar o mal, e Tu não és capaz de olhar para a transgressão com favor. Por que, então, Tu tens olhado favoravelmente àqueles que traem? Por que estás calado, enquanto os maus engolem os que são mais justos que eles?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Tu fazes homens como peixes no mar, como répteis que não têm quem os governe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Eles levantam a todos com anzol; arrastam homens com suas redes de pesca e os juntam em suas redes de arrasto. Por isso, eles se regozijam e se alegram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Por isso, eles sacrificam a suas redes de pesca e queimam incenso a suas redes de arrasto, porque é por suas redes que vivem no luxo, e sua comida é da melhor espécie!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Por acaso, continuarão a esvaziar suas redes e continuarão a massacrar as nações, sem sentirem compaixão?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Estarei no meu posto de vigilância e tomarei posição na torre da guarda, e observarei atentamente para ver o que Ele me dirá, e como devo agir com a minha queixa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Yahweh me respondeu e disse: \"Grava a visão, e escreve claramente em tábuas para que quem passar correndo a possa ler.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Porque a visão ainda é para o futuro, e pronunciará no final, e não falhará. Ainda que ela se atrase, espera-a; porque, com certeza, virá e não tardará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Olha! Aquele cujos desejos não são corretos é arrogante; mas o justo viverá pela sua fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Assim como o vinho é traiçoeiro, o homem arrogante também não permanece. A sua ganância é como a morte, que nunca está satisfeita. Ele ajunta para si todas as nações e recolhe para si todos os povos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Por acaso, não criarão todos esses um dito para ridicularizá-lo, e uma canção de zombaria contra ele, e dirão: \'Ai daquele que acumula o que não é seu! Pois até quando irás acumular o peso dos penhores, que tu tens tomado?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Por acaso não se levantarão de repente os que te mordem, e se despertarão os que te aterrorizam? Tu te tornarás uma vítima para eles!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Porque tu saqueaste muitas nações, todo o remanescente dos povos te saqueará. Pois derramaste sangue humano e agiste com violência contra a terra, as cidades e todos os seus habitantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, '\'Ai daquele que cobiça ganhos desonestos para sua casa, a fim de pôr seu ninho no alto para se manter seguro da mão do mal!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Tu planejaste vergonha para tua casa, porque eliminaste muitas pessoas, e pecaste contra ti mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Pois as pedras clamarão da parede, e as vigas de madeira lhes responderão:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, '\'Ai daquele que edifica uma cidade com sangue, e que estabelece uma vila com iniquidade!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Não provém de Yahweh dos Exércitos que os povos trabalhem para o fogo e que todas as outras nações se cansem em vão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Ainda assim, a terra será cheia do conhecimento da glória de Yahweh, como as águas cobrem o mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, '\'Ai daquele que incentiva seu próximo a beber! Tu que entornas sua garrafa, pressionando-o a se embebedar, a fim de veres a sua nudez!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Tu serás cheio de vergonha, em vez de glória. Agora é tua vez! Bebe, e mostra tua incircuncisão! O cálice da mão direita de Yahweh passará por ti e a desgraça cobrirá a tua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'A violência feita ao Líbano te cobrirá, e a destruição dos animais te aterrorizará, porque derramaste sangue humano, e procedeste com violência contra a terra, contra as cidades e contra todos seus habitantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Qual proveito tem a figura esculpida para ti? Pois, aquele que a esculpiu ou quem molda a figura do metal fundido é um professor de mentiras; porque ele confia na obra de suas próprias mãos, quando faz esses deuses mudos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, '\'Ai daquele que diz à madeira: Desperta! Ou à pedra muda: Levanta-te!\' Por acaso essas coisas ensinam? Vê! Estão cobertas de ouro e de prata, mas não há fôlego algum nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Porém, Yahweh está no Seu santo templo! Que toda a terra se cale diante Dele.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'A oração do profeta Habacuque:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, '\"Yahweh, ouvi Tua palavra e temi! Yahweh, reaviva o Teu trabalho durante estes tempos; e, ao longo destes tempos, faze-o conhecido; lembra-Te de ter compaixão, na Tua ira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Deus veio de Temã e o Santo veio do monte Parã. Selá. A Sua glória cobriu os céus e a terra ficou cheia do Seu louvor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Os dois raios de Sua mão brilharam como a luz, e ali Ele escondeu o Seu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Doenças mortais foram diante Dele e a praga perseguiu Seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Ele ficou parado e mediu a Terra; Ele olhou e sacudiu as nações. Até as montanhas indestrutíveis foram despedaçadas e as colinas intermináveis se prostraram. Seu caminho é eterno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Vi as tendas de Cusan tremendo, os tecidos das tendas na terra de Midiã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Estava Yahweh irado com os rios? Era a Tua ira contra os rios, ou a Tua fúria contra o mar, quando montaste os Teus cavalos e Tuas carruagens vitoriosas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Tu revelaste o Teu arco; Tu colocaste flechas no Teu arco! Selá. Tu dividiste a terra com os rios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'As montanhas Te viram e se contorceram de dor. Correntes de águas passaram sobre elas; o mar profundo deu um grito e levantou suas ondas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'O sol e a lua ficaram parados em seus lugares altos diante do clarão de Tuas flechas que voaram, diante do relâmpago de Tua lança reluzente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Tu marchaste sobre a terra com indignação. Em ira, Tu castigaste as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Tu saíste para a salvação do Teu povo, para a salvação do Teu ungido. Tu destróis a liderança da casa do ímpio, para o expor desde a sua base até o pescoço. Selah.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Tu trespassaste a cabeça dos seus guerreiros com as suas próprias flechas, porque eles vieram como uma tempestade para nos espalhar; seu regozijo era como o de quem devora o pobre em um lugar escondido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Tu viajaste sobre o mar com Teus cavalos, através das ondas, das grandes águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Eu ouvi e tremi em meu interior! Meus lábios estremeceram com o som. A podridão entra nos meus ossos e eu tremo por dentro enquanto espero silenciosamente pelo dia em que a angústia virá sobre o povo que nos invade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Ainda que a figueira não floresça e não haja nenhum fruto nas videiras; e ainda que o produto da oliveira falte e os campos não produzam alimento; e ainda que o rebanho seja exterminado dos currais e não haja nenhum gado nos estábulos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'ainda assim, eu me regozijarei em Yahweh. Eu me alegrarei pelo Deus da minha salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'O Senhor Yahweh é a minha força e Ele faz meus pés como os do cervo. Ele me faz ir adiante nos meus lugares altos. — Para o diretor da música, em meus instrumentos de cordas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Esta é a palavra de Yahweh que veio a Sofonias, filho de Cuchi, filho de Gedalias, filho de Amarias, filho de Ezequias, nos dias de Josias, filho de Amom, rei de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, '\"Eu destruirei tudo sobre a face da terra\", assim diz Yahweh:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, '\"Destruirei homens e animais. Destruirei as aves dos céus, os peixes do mar e todos os que causam tropeços. Extirparei o homem da face da terra\", assim diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Estenderei a minha mão contra Judá e todos os habitantes de Jerusalém. Aniquilarei deste lugar todo remanescente de Baal e os nomes dos idólatras entre os sacerdotes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'as pessoas que estão sobre os telhados e que adoraram os corpos celestes; aqueles que adoram a Yahweh e juram por Ele, mas também juram por Milcom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'Também aniquilarei aqueles que deixam de seguir Yahweh, que não buscam a Ele nem o consultam\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Calai-vos na presença do Senhor Yahweh, pois o Seu dia se aproxima; Yahweh preparou o sacrifício e santificou os seus convidados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, '\"E acontecerá que, no dia do sacrifício de Yahweh, castigarei os príncipes e os filhos do rei e todos que se vestem de roupas estrangeiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Nesse dia castigarei todos aqueles que saltam o pedestal dos ídolos, os que enchem a casa dos seus senhores com violência e engano\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, '\"Assim será naquele dia\", diz Yahweh, \"um choro de angústia virá da porta do Peixe, lamentação do Segundo Distrito e um grande ruído de destruição dos montes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Lamentai, habitantes de Mactes, pois todos os mercadores serão arruinados, e todos os que pesam a prata serão aniquilados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'E acontecerá que, naquele tempo, esquadrinharei Jerusalém com lanternas e castigarei os homens apegados ao seu vinho e que dizem nos seus corações: \'Yahweh não fará nada, nem bem nem mal\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Suas riquezas serão saqueadas, e suas casas devastadas e abandonadas! Construirão casas, mas não viverão nelas, plantarão vinhas, mas não beberão do seu vinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'O grande dia de Yahweh está perto, está perto e iminente. O som do dia de Yahweh será tal que até mesmo um guerreiro gritará amargamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Aquele dia será de fúria, de aflição e angústia; dia de tempestade e devastação, dia de trevas e escuridão, um dia de nuvens e escuridão profundas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Será dia de trombetas e gritos de guerra contra as cidades fortificadas e as torres altas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Pois Eu trarei angústia sobre a humanidade e, então, andarão como homens cegos, pois pecaram contra Yahweh. Seu sangue será despejado como pó, e suas entranhas como esterco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Nem a sua prata nem o seu ouro serão capazes de salvá-los no dia da fúria de Yahweh. O fogo dos ciúmes de Yahweh consumirá toda terra, pois a aniquilação que Ele trará contra os habitantes da terra será terrível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Reuni-vos, ajuntai-vos, nação sem pudor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Antes que o decreto entre em vigor, antes que o dia passe como a palha, antes que venha sobre vós o furor da ira de Yahweh, antes que o dia da ira de Yahweh venha sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Buscai Yahweh, todos os humildes da terra que obedeceis Seus decretos! Buscai a justiça! Buscai a humildade e talvez sejais protegidos no dia da ira do Senhor!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Gaza será abandonada, e Asquelom será transformada em devastação! Expulsarão Asdode ao meio-dia, extirparão Ecrom!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Ai dos habitantes da costa do mar, a nação dos quereteus! Yahweh falou contra vós, Canaã, terra dos filisteus. Eu vos destruirei até que não haja em vós remanescente!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Então, a costa do mar se tornará em pasto, terra para pastores e currais para ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'A região costeira pertencerá ao remanescente da casa de Judá, que apascentará os seus rebanhos. Seu povo se deitará ao entardecer, nas casas de Asquelom, e Yahweh, seu Deus, cuidará deles e restaurará sua sorte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, '\"Eu ouvi as provocações de Moabe e as injúrias do povo de Amom quando eles provocaram Meu povo e violaram suas fronteiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Portanto, assim como Eu vivo\", esta é a declaração de Yahweh dos Exércitos, Deus de Israel, \"Moabe se tornará como Sodoma, e o povo de Amom como Gomorra; um lugar de ervas daninhas e um poço de sal, devastada para sempre! Mas o remanescente do Meu povo os saqueará, e o remanescente da minha nação herdará a terra deles!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Isto acontecerá a Moabe e Amom por causa de seu orgulho, uma vez que provocaram e insultaram o povo de Yahweh dos Exércitos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Então, eles temerão Yahweh, Ele zombará de todos os deuses da terra. Todos O adorarão, de todos os lugares, de toda beira-mar!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Vós etíopes, também sereis perfurados pela Minha espada,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'e a mão de Deus atacará o norte e destruirá a Assíria. Então, Nínive se tornará uma ruína, tão seca como o deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Então, rebanhos descansarão lá, todos os animais das nações, tanto o pelicano como o ouriço, descansarão no topo de suas colunas. Suas vozes soarão na janela, e entulho estará nas portas; suas vigas de cedro entalhado serão expostas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Essa é a cidade exultante que viveu sem medo e que disse no seu coração: \"Eu sou, e não há outra igual\". Ela se tornou um horror, um lugar para animais ferozes pastarem! Cada um que passa por ela zombará com assobios e farão gestos de desprezo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Ai da cidade rebelde! A cidade violenta está contaminada!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Ela não ouviu a voz de Deus nem aceitou a correção de Yahweh. Ela não confia em Yahweh e não se aproximará do seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Os príncipes dela são leões que rugem em seu meio! Os seus juízes são lobos da noite que não deixam nada para ser comido pela manhã!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Os seus profetas são homens insolentes e traiçoeiros! Seus sacerdotes profanam o que é santo e violam a lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Yahweh é justo no meio dela. Ele não comete injustiça. Manhã após manhã, Ele dispensará Sua justiça. Ela não será escondida em meio à luz, embora os injustos não conheçam a vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Eu exterminei nações, as suas fortalezas estão arruinadas. Arruinei as suas ruas, para que ninguém passe por elas. Suas cidades foram destruídas, para que não haja homem que habite nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Eu disse: \"Certamente tu Me temerás. Aceita a correção e não sejas cortado de tuas casas por tudo que eu planejei fazer a ti\". Mas eles estavam ansiosos para começar todas as manhãs corrompendo todas as suas ações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, '\"Portanto, espera por mim\", assim diz Yahweh, \"até o dia em que Eu me levantar para o despojo. Pois Minha decisão é ajuntar as nações, reunir os reinos e derramar sobre eles a Minha ira, toda a Minha fúria, de tal modo que toda a terra será devorada pelo fogo da Minha ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Mas então darei lábios puros ao povo, para chamar todos eles no nome de Yahweh para Me servirem de pé, ombro a ombro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Para além do rio da Etiópia, os Meus adoradores, o Meu povo disperso, trarão ofertas que Me são devidas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'No dia em que não houver vergonha por todas as vossas ações que vós cometestes contra Mim, uma vez que Eu retirarei de ti os que celebraram o teu orgulho e porque tu não mais agirás arrogantemente no Meu santo monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Mas Eu te deixarei como um povo humilde e pobre, e tu te refugiarás no nome de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'O remanescente de Israel não mais cometerá injustiça ou falará mentiras, e não se achará língua enganosa em sua boca; assim eles pastarão e se deitarão, e ninguém os assustará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Canta, filha de Sião! Grita, Israel! Alegra-te e regozija-te de todo o teu coração, filha de Jerusalém!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Yahweh te tirou o castigo; Ele lançou fora teus inimigos! Yahweh é o Rei de Israel entre vós. Vós nunca mais tereis medo do mal!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'Naquele dia dirão a Jerusalém: \"Não temas, Sião. Não se enfraqueçam as tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Yahweh, teu Deus, está no meio de ti, poderoso para te salvar. Ele celebrará sobre ti e, com alegria, silenciará no Seu amor. Ele Se alegrará por ti e gritará de alegria,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'como no dia da festa solene. Eu tirarei a calamidade de ti e não trarei mais nenhuma vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Eis que Eu vou tratar com todos os seus opressores. Naquele tempo vou resgatar os coxos e reunir os marginalizados. Eu removerei tua vergonha e te darei louvor e honra em toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'E, naquele tempo, Eu vos guiarei; naquele tempo, Eu vos reunirei juntos. Eu farei com que todas as nações da terra te respeitem e te louvem, quando vires que Eu te restaurei\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'No segundo ano do rei Dario, no sexto mês, no primeiro dia do mês, a palavra de Yahweh veio pelo profeta Ageu, para o governador de Judá, Zorobabel, filho de Sealtiel, e para o sumo sacerdote Josué, filho de Jozadaque, e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, '\"Assim diz Yahweh dos Exércitos: \'Este povo diz: Não é a hora para virmos ou para construirmos a casa de Yahweh\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'E então a palavra de Yahweh veio pelo profeta Ageu, e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, '\"Seria este o tempo de viverdes em casas bem construídas, enquanto esta casa continua arruinada?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Então, Yahweh dos Exércitos diz: \'Considerai vossos caminhos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Vós semeastes muitas sementes, mas recolhestes pouco; vós comeis, mas não tendes o suficiente; vós bebeis, mas não vos saciais. Vós vestis roupas, mas não vos aqueceis, e o assalariado ganha dinheiro apenas para pôr em bolsa cheia de furos!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Assim diz Yahweh dos Exércitos: \"Considerai os vossos caminhos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Subi a montanha, trazei madeira, e construí a Minha casa; então terei prazer nela, e Eu serei glorificado!\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, '\"Vós procurais por mais, mas — vede! — tendes trazido pouco para casa, mas Eu com um sopro o dissipei! Por quê?\" Esta é a declaração de Yahweh dos Exércitos: \"Porque Minha casa continua em ruínas, enquanto cada homem tem prazer em sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Por causa disso, os céus retêm o orvalho de vós, e a terra retém sua produção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Eu tenho mandado a seca sobre a terra e sobre as montanhas, sobre o grão e sobre o vinho novo, sobre o óleo e sobre a colheita da terra, sobre os homens e sobre os animais, e sobre todo o trabalho de suas mãos!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Então Zorobabel, filho de Sealtiel, e o sumo sacerdote Josué, filho de Jozadaque, junto com o remanescente do povo, obedeceram à voz de Yahweh, seu Deus, e as palavras do profeta Ageu, porque Yahweh, seu Deus, o tinha enviado. As pessoas temeram a face de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Depois Ageu, o mensageiro de Yahweh, falou a mensagem de Yahweh para o povo e disse: \"\'Eu estou convosco!\' Essa é a declaração de Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Então, Yahweh moveu o espírito do governador de Judá, Zorobabel, filho de Sealtiel, e o espírito do sumo sacerdote Josué, filho de Jozadaque, e o espírito de todo o remanescente do povo, de modo que eles foram e trabalharam na casa de Yahweh dos Exércitos, seu Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'no vigésimo quarto dia do sexto mês, no segundo ano do rei Dario.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'No sétimo mês, no vigésimo primeiro dia do mês, a palavra de Yahweh veio pelo profeta Ageu, e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, '\"Fala ao governador de Judá, Zorobabel, filho de Sealtiel, e ao sumo sacerdote Josué, filho de Jozadaque; e ao remanescente do povo. Diz:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, '\'Dos que restaram entre vós, quem viu esta casa na sua glória anterior? E como vós a vedes agora? Não é esta como nada aos vossos olhos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Agora, pois, sê forte, Zorobabel!\' Esta é a declaração de Yahweh. \'E sê forte, sumo sacerdote Josué, filho de Jozadaque; e sede fortes, todas as pessoas da terra!\' Esta é a declaração de Yahweh: \'E trabalhem, pois Eu estou convosco!\' Esta é a declaração de Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, '\'Pelas promessas contidas na aliança que Eu estabeleci convosco quando saístes do Egito, e o Meu Espírito habitava entre vós, não temais!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Pois assim diz Yahweh dos Exércitos: \'Em pouco tempo, Eu mais uma vez estremecerei os céus e a terra, o mar e a terra seca!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'E Eu estremecerei cada nação, e cada nação Me trará suas coisas preciosas, e encherei esta casa de glória!\', diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, '\'A prata e o ouro são Meus!\' Esta é a declaração de Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, '\'A glória desta casa será maior no futuro do que no seu começo,\' declara Yahweh dos Exércitos, \'e darei paz a este lugar!\' Declara Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Ao vigésimo quarto dia do nono mês, no segundo ano de Dario, a palavra de Yahweh veio pelo profeta Ageu, e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, '\"Assim diz Yahweh dos Exércitos: Pergunta aos sacerdotes acerca da Lei, e diz:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Se um homem carregar a carne dedicada a Yahweh na aba do seu vestido e, se tocar a aba no pão ou guisado, vinho ou óleo, ou qualquer outro tipo de comida, essa comida se tornará santa?\" Os sacerdotes responderam dizendo: \"Não\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Então, Ageu disse: \"Se alguém impuro, por causa da morte, tocar qualquer uma dessas coisas, ficarão elas impuras?\" Os sacerdotes responderam dizendo: \"Sim, elas se tornarão impuras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Portanto, Ageu respondeu e disse: \"\'Assim são essas pessoas e esta nação diante de Mim!\', declara Yahweh. \'E assim é com tudo o que é feito por suas mãos: o que eles me oferecem é impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Portanto, a partir deste dia em diante, antes que qualquer pedra seja colocada sobre outra pedra, no templo de Yahweh, considerai:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Sempre que alguém vinha ao lagar, para tirar vinte medidas de grãos, havia somente dez; sempre que alguem vinha ao tonel, para tirar cinquenta medidas de vinho, havia somente vinte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Eu vos afligi em todo o trabalho das vossas mãos com ferrugem e mofo, mas vós ainda não retornastes para mim\', declara Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Considerai a partir deste dia em diante, desde o vigésimo quarto dia do nono mês, desde o dia em que a fundação do templo de Yahweh foi colocada. Considerai isto!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Ainda há semente no celeiro? A videira, a figueira, a romeira e a oliveira não produziram! Mas, a partir deste dia, Eu vos abençoarei!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Então, a palavra de Yahweh veio, pela segunda vez, a Ageu no vigésimo quarto dia do mês e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, '\"Fala ao governador de Judá, Zorobabel, e diz: \'Estremecerei os céus e a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Pois derrubarei o trono dos reinos e destruirei as forças dos reinos das nações! Derrubarei as carruagens e seus cavaleiros; os cavalos e seus cavaleiros cairão, cada um por causa da espada do seu irmão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, '\'Naquele dia\', declara Yahweh dos Exércitos, \'Eu te levarei, Zorobabel, filho de Sealtiel, como meu servo\', declara Yahweh. \'Eu te colocarei como o selo do Meu anel, pois foi a ti que escolhi!\', declara Yahweh dos Exércitos!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'No oitavo mês do segundo ano do reinado de Dario, a palavra de Yahweh veio a Zacarias, filho de Baraquias, filho de Ido, o profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Yahweh estava extremamente irado com vossos pais!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, '\"Dize-lhes: \'Assim diz Yahweh dos Exércitos: Tornai para Mim! — esta é a declaração de Yahweh dos Exércitos. Retornarei para vós — assim diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Não sejais como vossos pais, aos quais outrora os profetas clamaram, dizendo: \'Assim diz Yahweh dos Exércitos: Convertei-vos agora dos vossos maus caminhos e das vossas práticas pecaminosas!\'. Mas eles não ouviram e nem prestaram atenção — essa é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Vossos pais, onde estão eles? Onde estão os vossos profetas? Eles permanecem aqui para sempre?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Não lhes alcançaram as Minhas palavras e os Meus decretos, que Eu mandei por meio dos Meus servos, os profetas aos vossos pais? Então, arrependeram-se, dizendo: \'O que Yahweh dos Exércitos planejou fazer conosco, segundo o que nossas ações mereciam, assim Ele o fez\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'No vigésimo quarto dia do décimo primeiro mês, que é o mês de Sebate, no segundo ano do reinado de Dario, a palavra de Yahweh veio a Zacarias, filho de Baraquias, filho de Ido, o profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Eu vi, de noite, um homem, que estava montado num cavalo vermelho; ele estava entre as murteiras do vale e, atrás delas, achavam-se cavalos vermelhos, marrons e brancos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Eu disse: \"Senhor, o que são essas coisas?\". Então, o anjo que havia falado comigo me disse: \"Mostrarei a ti o que são essas coisas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Então, o homem, que estava de pé no meio das murteiras, me respondeu, dizendo: \"Estes são aqueles que Yahweh têm enviado para percorrer a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Eles responderam ao anjo de Yahweh que estava entre as murteiras e lhe disseram: \"Estivemos percorrendo a terra; e eis que toda terra ainda está calma, em descanso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Então, o anjo de Yahweh respondeu: \"Ó, Yahweh dos Exércitos, até quando não mostrarás compaixão por Jerusalém e pelas cidades de Judá, que têm sofrido indignação nesses setenta anos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Yahweh respondeu ao anjo que havia falado comigo com palavras bondosas, palavras de conforto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Então, o anjo que havia falado comigo me disse: \"Clama e dize: \'Yahweh dos Exércitos diz isto: Tenho sido zeloso por Jerusalém e por Sião com grande compaixão!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Estou muito irado com as nações que se sentem seguras. Eu estava apenas um pouco indignado e elas agravaram o mal\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Portanto, Yahweh dos Exércitos diz: \"Eu Me voltei a Jerusalém com misericórdias. Minha casa será edificada no meio dela — essa é a declaração de Yahweh dos Exércitos — e o cordel de medir será estendido sobre Jerusalém!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Proclama outra vez, dizendo: \"Yahweh dos Exércitos diz isto: \'Minhas cidades novamente transbordarão bens, Yahweh novamente consolará Sião e, novamente, Ele escolherá Jerusalém\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Então, levantei meus olhos e vi quatro chifres!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Eu disse ao anjo que falava comigo: \"O que são essas coisas?\". Ele me respondeu: \"São os chifres que dispersaram Judá, Israel e Jerusalém\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Então, o Yahweh me mostrou quatro ferreiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Eu Lhe disse: \"O que essas pessoas vieram fazer?\". Ele me respondeu, dizendo: \"Aqueles são os chifres que dispersaram Judá, até que nenhum homem pudesse levantar sua cabeça. Mas essas pessoas estão vindo para expulsá-los e para derrubar os chifres das nações que levantaram qualquer chifre contra a terra de Judá para dispersá-la\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Voltei a levantar os meus olhos, e vi um homem com um cordel de medir em suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'E eu disse: \"Aonde tu vais?\". Ele me respondeu: \"Medir Jerusalém, para ver o seu comprimento e a sua largura\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Então, o anjo que havia falado comigo saiu, e outro anjo foi ao encontro dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'O segundo anjo lhe disse: \"Corre e fala a esse jovem que Jerusalém habitará numa terra aberta por causa da multidão de pessoas e animais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Porque Eu, diz Yahweh, serei o muro de fogo ao redor dela e serei a glória em seu meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Levantai! Levantai! Fugi da terra do norte, diz Yahweh, pois vos tenho dispersado como os quatro ventos do céu, diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Levantai! Fugi, ó Sião, vós que viveis com a filha da Babilônia!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Depois que Yahweh dos Exércitos me honrou e me enviou contra as nações que vos roubaram, todo aquele que vos tocar, toca na menina dos olhos de Deus! Depois de Yahweh ter feito essas coisas, Ele disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, '\"Eu mesmo levantarei a Minha mão sobre eles e eles serão servos dos seus escravos\". E sabereis que Yahweh dos Exércitos me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, '\"Canta alegremente, ó filha de Sião, porque Eu estou prestes a vir acampar no meio de ti!\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Então, grandes nações se ajuntarão a Yahweh nesse dia. Ele diz: \"E serás o Meu povo; portanto, acamparei no meio de ti\", e tu saberás que Yahweh dos Exércitos me enviou a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Portanto, Yahweh herdará Judá como Sua propriedade justa na terra santa e também escolherá Jerusalém para Si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Cale-se toda a carne, diante de Yahweh, porque Ele tem Se levantado do Seu santo lugar!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Então, Yahweh mostrou-me Josué, o sumo sacerdote, parado diante do anjo do Senhor, e Satanás estava em pé ao seu lado direito para acusar-lhe do pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'O anjo de Yahweh disse a Satanás: \"Que Yahweh te repreenda, Satanás! Aquele que escolheu Jerusalém te repreenda! Não é este um tição tirado do fogo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Josué estava em pé diante do anjo e vestia uma roupa suja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'O anjo falou para aqueles que estavam em pé diante dele: \"Tirai-lhe as roupas sujas\". E disse a Josué: \"Vê! Tenho posto a tua iniquidade para que passe de ti e te vestirei com roupas finas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Ele disse: \"Deixa que coloquem um turbante limpo sobre a tua cabeça!\". E colocaram um turbante limpo sobre a cabeça de Josué e lhe vestiram com roupas limpas no momento em que o anjo de Yahweh estava ali, em pé!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Em seguida, o anjo de Yahweh, solenemente, ordenou a Josué, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, '\"Assim diz Yahweh dos Exércitos: Se andares nos Meus caminhos, e, se guardares os Meus mandamentos, tu governarás a Minha casa e guardarás os Meus átrios, pois deixarei que tenhas livre acesso entre os que aqui estão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Ouvi, Josué, sumo sacerdote, tu e os teus companheiros que vivem contigo! Estes homens são um sinal, pois Eu mesmo levantarei Meu servo, o Renovo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Agora, olha para esta pedra que Eu coloquei diante de Josué. Sobre esta pedra, estão sete olhos e nela gravarei uma inscrição\". Esta é a declaração de Yahweh dos Exércitos: \"e tirarei o pecado desta terra em um dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, '\"Naquele dia\" — esta é a declaração de Yahweh dos Exércitos — \"cada homem convidará o seu vizinho para se sentar debaixo de sua videira e debaixo de sua figueira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Então, o anjo que falava comigo voltou e me despertou, como se eu estivera dormindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Ele me perguntou: \"O que tu vês?\". Respondi: \"Vejo um candelabro feito de ouro maciço, com uma bacia por cima. Há sete lâmpadas sobre ele e sete tubos em cima de cada lâmpada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Duas oliveiras estão nele, uma no lado direito do vaso, e outra no lado esquerdo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Então, perguntei ao anjo que falava comigo: \"O que significam essas coisas, meu senhor?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'O anjo me respondeu: \"Tu não sabes o que essas coisas significam?\". Respondi: \"Não, meu senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Então, ele me disse: \"Esta é a palavra de Yahweh para Zorobabel: Não por força nem por poder, mas pelo Meu Espírito\" — diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, '\"Quem és tu, grande monte? Diante de Zorobabel, irás te tornar uma planície, e ele colocará a pedra angular, exclamando \'Graça! Graça sobre ela!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'A palavra de Yahweh veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, '\"As mãos de Zorobabel lançaram a fundação desta casa e elas irão concluí-la. Então, saberás que Yahweh dos Exércitos me enviou a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Quem desprezou o dia das pequenas coisas? Este povo se alegrará e verá o prumo de pedra nas mãos de Zorobabel. (Estas sete lâmpadas são os olhos de Yahweh que percorrem toda a terra)\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Então, eu perguntei ao anjo: \"O que são essas duas oliveiras que estão ao lado esquerdo e à direita do candelabro?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Novamente perguntei: \"O que são esses dois ramos de oliveira ao lado dos dois tubos de ouro que vertem azeite dourado?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Então, ele me perguntou: \"Tu não sabes o que é isto?\". Eu disse: Não, meu senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Então, ele disse: \"Estes são os dois ungidos que estão diante do Senhor de toda a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Depois, virei-me e levantei os meus olhos, e vi um pergaminho que voava!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'O anjo disse para mim: \"O que vês?\". Eu respondi: \"Vejo um pergaminho voando, de vinte côvados de comprimento e dez côvados de largura\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Então, ele me disse: \"Esta é a maldição que sairá pela face de toda terra: todo ladrão será expulso, conforme a maldição que foi dita, por um lado, e todos aqueles que juram falsamente serão eliminados com base no que foi dito, por outro lado, de acordo com suas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Eu os lançarei fora, esta é a declaração de Yahweh dos Exércitos; assim, estes entrarão dentro da casa do ladrão e na casa daquele que jura falsamente pelo Meu nome. E ela permanecerá na sua casa e consumirá sua madeira e suas pedras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'O anjo que falava comigo saiu e me disse: \"Levanta teus olhos e vê o que está vindo!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Eu disse: \"O que é isto?\" Ele respondeu: \"É um cesto contendo uma efa, que está vindo. Estas são suas iniquidades em toda a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Então, a tampa de chumbo que cobria foi levantada do cesto e, dentro dele, havia uma mulher sentada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'O anjo disse: \"Esta é a impiedade!\". E a lançou de volta dentro do cesto, e pôs a tampa de chumbo sobre o cesto aberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Levantei meus olhos e eis que vi duas mulheres vindo em minha direção; o vento estava sobre suas asas; elas tinham asas como asas de cegonha. E levantaram o cesto entre a terra e os céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Então, eu disse ao anjo que falava comigo: \"Para onde estão levando o cesto?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Ele me disse: \"Para edificar o templo na terra de Sinar, pois, estando o templo pronto, o cesto será posto no lugar preparado para ela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Então, voltei, levantei meus olhos e vi quatro carruagens saindo dentre dois montes e os dois montes eram feitos de bronze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'A primeira carruagem era de cavalos vermelhos, a segunda carruagem de cavalos pretos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'a terceira carruagem de cavalos brancos e a quarta carruagem de cavalos com pintas acinzentadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Então, perguntei ao anjo que falava comigo: \"O que é isto meu senhor?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'E o anjo me respondeu, dizendo: \"Estes são os quatro ventos do céu, que saem de onde estavam, diante do Senhor de toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Aquele que está com os cavalos pretos vai para as terras do norte, os cavalos brancos vão para as terras do oeste; e os cavalos com pintas acinzentadas vão para as terras do sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, '\"Esses cavalos fortes saíram a percorrer toda terra; então, o anjo disse: \'Ide e percorrei toda a terra!\'. E partiram por toda terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Ele me chamou e disse: \'Eis que os que vão para as terras do norte apaziguarão o meu espírito a respeito das terras do norte\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Então, veio a mim a palavra de Yahweh, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, '\"Toma as ofertas dos exilados — de Heldai, de Tobias e de Jedaías — vai, neste mesmo dia, e leva à casa de Josias, filho de Sofonias, que veio da Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Toma a prata e o ouro, faze uma coroa e coloca sobre a cabeça de Josué, filho de Jeozadaque, o sumo sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'Fala a ele: \"Assim diz Yahweh dos Exércitos: \'este homem, cujo o nome é Renovo, crescerá onde está e edificará o templo de Yahweh!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Ele edificará o templo de Yahweh e aumentará o seu esplendor; então, irá se assentar e reinará no seu trono. Ele será sacerdote sobre o seu trono e haverá entendimento de paz entre ambos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Uma coroa será colocada no templo de Yahweh para honrar Heldai, Tobias e Jedaías, assim como memorial da bondade de Hem, filho de Sofonias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Portanto, aqueles que estão longe virão e construirão o templo de Yahweh e tu saberás que Yahweh dos Exércitos me enviou a vós; isto somente acontecerá, se ouvirdes a voz de Yahweh vosso Deus!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Quando o rei Dario havia governado por quatro anos, no quarto dia do mês de Quisleu (que era o nono mês), a palavra de Yahweh veio a Zacarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'O povo de Betel enviou Sarezer, Regem-Meleque e os seus homens para suplicarem diante da face de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'Eles perguntaram aos sacerdotes que estavam na casa de Yahweh dos Exércitos e para os profetas, dizendo: \"Porventura, devo lamentar por meio de um jejum neste quinto mês, como tenho feito durante muitos anos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Então, a palavra de Yahweh dos Exércitos veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, '\"Fala para todo o povo da terra e para o sacerdote e dize-lhes: \'Quando jejuastes e pranteastes no quinto e no sétimo mês, durante esses setenta anos, verdadeiramente, jejuastes para Mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Quando comiam e bebiam, não comiam e bebiam para vós mesmos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Porventura, não são as mesmas palavras que Yahweh proclamava por meio da boca dos antigos profetas, quando habitavam em Jerusalém e nas cidades ao redor, em prosperidade, e fostes assentados no Neguebe e nas colinas ao oeste?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'A palavra de Yahweh veio a Zacarias, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, '\"Yahweh dos Exércitos diz isto: \'Julgai com a verdadeira justiça, piedade e misericórdia. Que cada um faça isso ao seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Acerca da viúva e do órfão, do estrangeiro e do pobre, não os oprimais, e que nenhum de vós intenteis o mal contra o outro, no vosso coração\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Mas eles se recusaram a prestar atenção, virando as costas com teimosia. Eles taparam seus ouvidos para não ouvirem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Eles endureceram seu coração, que se tornou duro como diamante, e não quiseram ouvir a lei nem as palavras de Yahweh dos Exércitos. Ele havia enviado essas mensagens para o povo, por meio do Seu Espírito, no tempo antigo, pela boca dos profetas. Mas o povo se recusou a ouvir e Yahweh dos Exércitos ficou muito irado com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, '\"Assim como clamei e eles não ouviram; da mesma forma clamarão a Mim, mas não lhes ouvirei\", disse Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, '\"E os espalharei como um vendaval por todas as nações que eles ainda não viram e a terra ficará desolada depois deles, de sorte que ninguém passará pela terra, nem retornará por lá, porque transformaram sua linda terra numa desolação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'A palavra de Yahweh dos Exércitos veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, '\"Assim diz Yahweh dos Exércitos: \'Tenho por Sião grande zelo; tenho por ela ardente zelo com grande ira!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Assim diz Yahweh dos Exércitos: \'Voltarei para Sião e viverei no meio de Jerusalém, porque Jerusalém será chamada \'A Cidade da Verdade\' e o monte de Yahweh dos Exércitos será chamado \'O Monte Santo!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Assim diz Yahweh dos Exércitos: \"Homens e mulheres idosos voltarão a andar pelas ruas de Jerusalém, cada um com sua bengala por causa da idade avançada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'As ruas da cidade estarão cheias de meninos e meninas brincando nelas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Assim diz Yahweh dos Exércitos: \"Se isso parece impossível aos olhos do remanescente deste povo naqueles dias, será que também parece impossível aos Meus olhos?\" — esta é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Assim diz Yahweh dos Exércitos: \"Eis que estou prestes a resgatar o Meu povo da terra do oriente e da terra do ocidente!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'Porque os trarei de volta e viverão no meio de Jerusalém. Assim, voltarão a ser Meu povo e serei Seu Deus em verdade e em retidão!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Assim diz Yahweh dos Exércitos: \"Vós que, agora, continuais ouvindo as mesmas palavras que vieram das bocas dos profetas, quando o alicerce da Minha casa foi lançado, fortalecei as vossas mãos para que o templo seja construído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Porque, antes daqueles dias, ninguém realizou colheita alguma, não havia salário para os homens nem os animais lhes davam ganho, por causa do inimigo, não havia paz para quem saía ou entrava. Coloquei cada um contra o seu próximo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, '\"Mas agora não será como nos dias antigos. Eu estarei com o remanescente deste povo\" — esta é a declaração de Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, '\"Porque sementes de paz serão semeadas; a videira dará o seu fruto e a terra dará o seu alimento; os céus darão o seu orvalho, porque farei o remanescente deste povo herdar todas estas coisas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, '\"Casa de Judá e casa de Israel, vós fostes um exemplo de maldição para as outras nações. Então, hei de vos resgatar e sereis uma bênção. Não tenhais medo; fortalecei as vossas mãos!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Porque Yahweh dos Exércitos diz: \"assim como planejei lhes fazer mal quando os vossos antepassados provocaram a Minha ira e não voltei atrás, diz Yahweh dos Exércitos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'assim também planejarei nestes dias fazer, novamente, o bem a Jerusalém e à casa de Judá! Não temais!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, '\"Eis o que deveis fazer: falar a verdade, cada um ao seu próximo; julgar com verdade, justiça e paz em seus portões;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'não planejar, em vosso coração, fazer o mal um ao outro; e não amar juramentos falsos — porque abomino essas coisas! — esta é a declaração de Yahweh\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Depois, a palavra de Yahweh dos Exércitos veio a mim, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, '\"Yahweh dos Exércitos diz isto: \'os jejuns, ao quarto mês, ao quinto mês, ao sétimo mês e ao décimo mês, se tornarão tempos de júbilo, alegria e festivais solenes para a casa de Judá! Portanto, ameis a verdade e a paz!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Assim diz Yahweh dos Exércitos: \"o povo retornará, até os que vivem em muitas cidades diferentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'Os moradores de uma cidade irão para outra cidade e dirão: \'Vamos, rapidamente, suplicar diante da face de Yahweh e buscar Yahweh dos Exércitos!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Muitas pessoas e nações poderosas buscarão Yahweh dos Exércitos em Jerusalém e implorarão pelo favor de Yahweh!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Assim diz Yahweh dos Exércitos: \"Naqueles dias, dez homens de cada língua e nação apanharão a bainha da vossa túnica e dirão: \'Deixai que vos acompanhemos, porque ouvimos que Deus é convosco!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Esta é a palavra de Yahweh, declarada sobre a terra de Hadraque e Damasco. Pois o olho de Yahweh está sobre toda a humanidade e também sobre todas as doze tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'Esta declaração também é sobre Hamate, cujas extremidades se estendem até Damasco e sobre Tiro e Sidom, embora sejam muito sábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Tiro edificou para si uma fortaleza e amontoou prata como pó e ouro puro como lama nas ruas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Vê! Eis que o Senhor a despojará e destruirá sua força no mar; assim será consumida pelo fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Asquelom a verá e será atemorizada! Gaza também terá grande tremor! Ecrom, suas expectativas serão frustradas! O rei de Gaza perecerá e Asquelom não mais será habitada!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Forasteiros farão suas habitações em Asdode e a soberba dos filisteus será exterminada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Porque tirarei o seu sangue das suas mãos e as suas abominações que estão entre os seus dentes. Então, serão o remanescente para o nosso Deus, como um clã em Judá, e Ecrom se tornará como os jebuseus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Acamparei ao redor da Minha terra, contra as forças inimigas, para que ninguém saia ou entre; pois nenhum opressor passará por ela. Agora vigiarei a Minha terra com os Meus próprios olhos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Exulta, com grande júbilo, ó filha de Sião! Exulta com alegria, ó filha de Jerusalém! Eis que o teu Rei vem a ti com justiça, para te resgatar. Ele é humilde, e vem montado num jumento, num jumentinho, a cria de uma jumenta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Então, exterminarei os carros de Efraim e o cavalo de Jerusalém e o arco será exterminado da batalha; Ele proclamará paz às nações e o Seu domínio será de mar a mar e do rio às extremidades da terra!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, '\"Assim como a ti, libertarei os teus cativos do abismo sem água, por causa do sangue da Minha aliança contigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Retornai à fortaleza, vós, cativos da esperança! Hoje mesmo, declaro que vos restituirei em dobro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'porquanto curvei Judá como Meu arco. Enchi Minha aljava com Efraim. Suscitei teus filhos, Sião, contra os teus filhos, Grécia, e fiz a ti, Sião, como a espada de um valente!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Yahweh lhes aparecerá e as Suas flechas sairão como o relâmpago! Pois meu Senhor Yahweh fará soar a trombeta e avançará com tempestades vindas de Teman.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Yahweh dos Exércitos vai defendê-los e eles os exterminarão e derrotarão as pedras das fundas. Então, eles beberão e gritarão como homens embriagados com vinho e serão cheios de vinho como bacias, como os cantos do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Então, naquele dia, Yahweh, seu Deus, irá resgatá-los; como o rebanho do Seu povo, porque serão as joias de uma coroa, resplandecendo sobre a sua terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Quão grande é a sua bondade e quão grande é a sua formosura! Os jovens florescerão com os cereais e as moças virgens com o vinho doce!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Pedi por chuva a Yahweh na estação das chuvas da primavera — Yahweh é quem faz tempestades — e Ele dá chuvas a todos e vegetação no campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Pois os ídolos do lar falam falsamente; os adivinhos imaginam mentiras; eles contam sonhos enganosos e dão consolação vazia, pois sofrem como ovelhas que não têm pastor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'A Minha ira se acende contra os pastores; são os bodes — os líderes — que punirei. Yahweh dos Exércitos também cuidará de Seu rebanho, a casa de Judá, e fará deles como o Seu cavalo de guerra em batalha!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'De Judá, sairá a pedra angular; dela, virá o pilar da tenda, o arco da guerra e todos os líderes juntos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Serão como guerreiros que pisam seus inimigos na lama das ruas da batalha; eles farão guerra, pois Yahweh está com eles, e irão envergonhar os que montam os cavalos de guerra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Eu fortificarei a casa de Judá e salvarei a casa de José; pois os restaurarei e terei misericórdia deles. Serão como se Eu não os tivesse jogado para fora, pois Eu sou Yahweh, Deus deles, e os ouvirei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Então, Efraim será como um guerreiro, e o seu coração se alegrará como pelo vinho, seus filhos verão e se alegrarão. Seu coração se alegrará em Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Eu assobiarei por eles e os reunirei, pois irei remi-los, e eles se tornarão grandes como foram antes!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Eu os semeei entre os povos, mas eles se lembrarão de mim em países distantes. Então, eles e suas crianças viverão e retornarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Pois os restaurarei da terra do Egito e os ajuntarei da Assíria. Eu os trarei da terra de Gileade e do Líbano até que não haja mais espaço para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Eu passarei pelo mar da sua aflição, ferirei as ondas desse mar e secarei todas as profundezas do Nilo. A majestade da Assíria será lançada para baixo e o cetro do Egito será tirado dos egípcios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Eu os reforçarei em Mim mesmo, e eles andarão em Meu nome — essa é a declaração de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Abra tuas portas, Líbano, para que o fogo devore teus cedros!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Lamentai, ciprestes, pelos cedros que caíram! O que era majestoso foi devastado! Lamentai, carvalhos de Basã, a densa floresta foi abaixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Os pastores uivam porque a sua glória foi destruída! Os leões rugem porque a arrogância do rio Jordão foi devastada!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Assim diz Yahweh, meu Deus: \"Como um pastor, cuida das ovelhas destinadas ao abate!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, '(Aqueles que as compram, as massacram e não são punidos, e aqueles que as vendem dizem: \'Bendito seja Yahweh, porque me tornei rico!\' pois os pastores que trabalham para os donos dos rebanhos não têm piedade delas.)');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Pois já não terei piedade dos habitantes desta terra! Assim declara Yahweh\". Vê! \"Eu mesmo estou a ponto de entregar cada um na mão do seu próximo e na mão do seu rei, e destruirão a terra, e não livrarei nenhum deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Assim, tornei-me o pastor do rebanho destinado ao abate, para aqueles que negociavam as ovelhas. Tomei duas varas; uma chamei de \"Graça\" e a outra de \"Unidade\". Foi assim que apascentei as ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Em um mês, destruí os três pastores. Perdi a paciência com eles, e eles também me odiaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Então, eu disse aos donos: \"Não trabalharei mais para vós como pastor. As ovelhas que estão morrendo, deixai-as morrer; as ovelhas que estão sendo destruídas, deixai que sejam destruídas. Deixai as ovelhas remanescentes comerem a carne do seu próximo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Tomei a vara chamada \"Graça\" e a quebrei para anular o acordo que fiz com todas as minhas tribos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Naquele dia, o acordo foi quebrado, e aqueles que negociavam ovelhas, e que estavam me vigiando, souberam que era a palavra que Yahweh tinha falado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Eu te disse: \"Se for bom para ti, paga meu salário. Mas se não, não faças isso\". Então, eles pesaram meu salário (trinta peças de prata).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Então, Yahweh me disse: \"Deposita a prata no tesouro, este magnífico preço em que por eles fui avaliado!\" Assim, peguei as trinta moedas de prata e depositei no tesouro da Templo de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Então, quebrei a minha segunda vara, \"Unidade,\" para quebrar a irmandade entre Judá e Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Yahweh me disse: \"Novamente, pega o utensílio do pastor insensato para ti,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'pois, vê, estou a ponto de colocar na terra um pastor. Ele não cuidará das ovelhas que estão perecendo, não buscará a ovelha perdida, nem curará a ovelha aleijada. Ele não alimentará a ovelha saudável, mas comerá a carne das ovelha gordas, e as rasgará até os seus cascos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Ai do pastor inútil, que abandona o rebanho! Que a espada lhe caia sobre seu braço e sobre seu olho direito! Que seu braço seque e que seu olho direito fique cego!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Esta é uma declaração da palavra de Yahweh a respeito de Israel — uma declaração de Yahweh, que estendeu os céus e colocou os fundamentos da terra, que forma o espírito do homem dentro dele:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, '\"Vê! Estou a ponto de fazer de Jerusalém um cálice de tontear, levando todos os povos que a cercam a cambalear ao seu redor. Também será assim para Judá durante o cerco a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Naquele dia, farei de Jerusalém uma pedra pesada para todos os povos. Quem tentar levantar essa pedra se machucará muito, e todas as nações da terra se ajuntarão contra aquela cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Naquele dia — esta é a declaração de Yahweh —, Eu golpearei todos os cavalos com terror e cada cavaleiro com fúria. Eu olharei com graça para a casa de Judá; golpearei todos os cavalos do exército com cegueira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Então, os líderes de Judá dirão em seus corações: \'Os habitantes de Jerusalém são a nossa força por causa de Yahweh dos Exércitos, o Deus deles\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'Naquele dia, farei com que os líderes de Judá sejam como braseiros no meio da madeira e como tocha flamejante entre os grãos, porque consumirão todos os povos vizinhos à sua direita e à sua esquerda. Jerusalém voltará a viver em seu próprio lugar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Yahweh salvará primeiro as tendas de Judá, para que a honra da casa de Davi e a honra dos que vivem em Jerusalém não sejam maiores do que a do restante de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'Naquele dia, Yahweh será o defensor dos habitantes de Jerusalém, e naquele dia os que forem fracos entre eles serão como Davi, enquanto que a casa de Davi será como Deus, como o Anjo de Yahweh diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, '\"Naquele dia, começarei a destruir todas as nações que vierem contra Jerusalém;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'mas derramarei um espírito de compaixão e súplicas na casa de Davi e nos habitantes de Jerusalém, para que olhem para Mim, Aquele que eles feriram. Eles vão chorar por Mim, como se chora por um filho único; lamentarão amargamente por ele como os que lamentam a morte de um filho primogênito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Naquele dia, os lamentos em Jerusalém serão tão grandes como os lamentos em Hadade-Rimon na planície de Megido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'A terra chorará, os clãs à parte uns dos outros. O clã da casa de Davi à parte e suas esposas estarão separadas dos homens. O clã da casa de Natã à parte e suas esposas estarão separadas dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'O clã da casa de Levi à parte e suas esposas estarão separadas dos homens. O clã dos simeítas à parte e suas esposas estarão separadas dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'Cada clã dos clãs restantes, cada clã à parte e as esposas estarão separadas dos homens\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, '\"Naquele dia, uma fonte se abrirá para a casa de Davi e os habitantes de Jerusalém, pelo seu pecado e impureza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Naquele dia — esta é a declaração de Yahweh dos Exércitos —, cortarei os nomes dos ídolos da terra para que não mais sejam lembrados. Eu também farei com que os falsos profetas e o espírito imundo saiam da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Se algum homem continuar a profetizar, seu pai e sua mãe que o geraram lhe dirão: \'Não viverás, porque falas mentiras em Nome de Yahweh!\'. Então, seu pai e sua mãe que o geraram, o transpassarão à espada quando ele profetizar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Naquele dia, cada profeta ficará envergonhado de sua visão quando for profetizar. Esses profetas não usarão mais um manto de pele a fim de enganar o povo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'cada um dirá: \'Eu não sou um profeta! Eu sou lavrador, pois a terra tornou-se meu trabalho quando ainda era jovem!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Mas alguém lhe dirá: \'O que são essas feridas nas tuas mãos?\'. Ele responderá: \'Fui ferido na casa dos meus amigos\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, '\"Espada! Levanta-te contra o Meu pastor, o homem que está perto de Mim!\" — esta é a declaração de Yahweh dos Exércitos. \"Fere o pastor e as ovelhas se dispersarão! Porque virarei a Minha mão contra os pequeninos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, '\"Então, de toda a terra,\" — esta é a declaração de Yahweh — \"dois terços serão cortados! Essas pessoas irão perecer; apenas um terço permanecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Farei aquela terceira parte passar pelo fogo e os refinarei como a prata é refinada; vou testá-los como o ouro é testado. Eles invocarão o Meu nome e lhes responderei e direi: \'Este é o Meu povo!\'. E eles dirão: \'Yahweh é o meu Deus!\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Eis que vem o dia de Yahweh, quando teu despojo será dividido no meio de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Pois ajuntarei todas as nações contra Jerusalém e a cidade será capturada. As casas serão saqueadas e as mulheres violentadas; metade da cidade será levada ao cativeiro, e o remanescente do povo não será exterminado da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Mas Yahweh irá sair e declarar guerra contra aquelas nações quando Ele pelejar no dia da batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Naquele dia, Seus pés pararão no monte das Oliveiras, o qual está além de Jerusalém, ao oriente. O monte das Oliveiras será dividido ao meio, entre o oriente e o ocidente, por um vale muito grande, e a metade do monte retrocederá em direção ao norte e a outra metade em direção ao sul.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Então, fugireis vale abaixo, entre os montes de Yahweh, pois o vale entre aqueles montes se estenderá até Azal. Fugireis como fugistes do terremoto, nos dias de Uzias, rei de Judá. Então, Yahweh, meu Deus, virá e todos os santos estarão com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'Naquele dia, não haverá luz; também não haverá frio nem geada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Naquele dia, um dia que só Yahweh conhece, não mais haverá dia ou noite; a noite ainda será dia claro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Naquele dia, águas vivas fluirão para fora de Jerusalém. Metade delas fluirá para o mar oriental e metade para o mar ocidental, no verão e no inverno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Yahweh será Rei sobre toda a terra. Naquele dia, haverá Yahweh, o único Deus, e tão somente o Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Toda a terra se tornará como o Arabá, de Geba a Rimom, sul de Jerusalém. Jerusalém resplandecerá continuamente e permanecerá no seu devido lugar, da porta de Benjamim ao lugar onde estava a primeira porta, até o portão da Esquina e da torre de Hananel aos lagares do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'O povo habitará em Jerusalém e não mais haverá maldição vinda de Deus contra eles. Jerusalém habitará em segurança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Esta será a praga com a qual Yahweh atacará todos os povos que pelejaram contra Israel: a carne deles apodrecerá mesmo estando eles de pé; seus olhos apodrecerão nas suas órbitas e suas línguas apodrecerão nas suas bocas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Naquele dia, grande confusão vinda de Yahweh lhes sobrevirá! Cada um agarrará a mão do seu próximo, cada um levantará a mão contra o seu próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Judá também pelejará contra Jerusalém. Ajuntarão as riquezas de todas as nações circunvizinhas — ouro, prata, vestes pomposas, em grande abundância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Uma praga também assolará os cavalos e as mulas, os camelos e os jumentos, e todo o animal naqueles campos também sofrerá da mesma praga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Então, acontecerá que todo aquele que permanecer naquelas nações que se levantaram contra Jerusalém subirão anualmente para adorar o Rei, Yahweh dos Exércitos, para observar a Festa dos Tabernáculos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Acontecerá que, se alguém dentre todas as nações da terra não subir a Jerusalém para adorar ao Rei, Yahweh dos Exércitos, então, Yahweh dos Exércitos não lhes dará chuva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Se a nação do Egito não subir, então, não terá chuva. Uma praga de Yahweh assolará as nações que não subirem para guardar a Festa dos Tabernáculos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Esse será o castigo para o Egito e o castigo para toda a nação que não subir para guardar a Festa dos Tabernáculos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'Mas, naquele dia, estará gravado nas campainhas dos cavalos: \"Separai-vos para Yahweh\", e os recipientes na casa de Yahweh serão como as bacias diante do altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Pois todas as panelas em Jerusalém e Judá serão separadas para Yahweh dos Exércitos e todo aquele que trouxer um sacrifício comerá nelas e nelas cozerá. Naqueles dias, mercadores não mais existirão na casa de Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Palavra de Yahweh para Israel por intermédio de Malaquias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, '\"Eu vos tenho amado\", diz Yahweh. \"Mas vós dizeis: \'Como nos tens amado?\' Não foi Esaú irmão de Jacó?\", diz Yahweh. \"Ainda assim tenho amado Jacó,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'mas Esaú Eu tenho odiado. Tenho devastado suas montanhas e abandonado sua herança para os chacais do deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'E Edom diz: \'Estamos abatidos, mas edificaremos as ruínas\'\". Yahweh dos Exércitos diz: \"Eles poderão edificar, mas Eu destruirei. Os homens os chamarão \'o país da maldade\' e \'as pessoas as quais Yahweh tem amaldiçoado para sempre\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Seus próprios olhos verão, e dirão: \'Grande é Yahweh além das fronteiras de Israel\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'O filho honra seu pai, e o servo honra seu senhor. Se Eu sou o pai, onde está a Minha honra? Se Eu Sou o Senhor, onde está a Minha reverência?\", diz Yahweh dos Exércitos aos sacerdotes, que desprezam o Meu Nome. \"Mas dizeis: \'Como desprezamos o Teu Nome?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Oferecendo pão impuro sobre o Meu altar. E dizeis: \'Como temos Te profanado?\' Dizendo que a mesa de Yahweh é desprezível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Quando oferecem animais cegos para o sacrifício, não é isso mal? E, quando ofereceis o coxo e o doente, não é isso mal? Apresentai isso ao vosso governador. Ele vos aceitará ou terá agrado de vós?\", diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, '\"E agora tentai pedir favor a Deus, de modo que Ele seja gracioso convosco. Com uma oferta dessa em vossas mãos, Ele se agradará de vós?\", diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, '\"Oh, se houvesse um entre vós que fechasse a porta do templo, para que não acendêsseis o fogo no Meu altar em vão! Não tenho prazer em vós\", diz Yahweh dos Exércitos. \"Não aceitarei nenhuma oferta de vossas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Porque desde o nascer até o pôr do sol, Meu Nome será grande entre as nações, e em todos os lugares, incenso e ofertas puras serão oferecidos ao Meu Nome. Porque o Meu Nome será grande entre as nações\", diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, '\"Mas vós estais profanando Meu Nome, quando dizeis que a mesa do Senhor é impura e seus frutos são desprezíveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Vós também dizeis: \'Como é cansativo!\', e Me desprezais\", diz Yahweh dos Exércitos. \"Vós trazeis o animal que foi roubado, o coxo ou o doente; e isso trazeis como vossa oferta! Devo aceitar isso de vossas mãos?\", diz Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, '\"Maldito seja o enganador, que tem um animal sem defeito, macho do seu rebanho, e faz voto de o dar a Mim, mas ainda assim sacrifica a Mim um defeituoso\", diz o Senhor. \"Pois Eu Sou o grande Rei\", diz Yahweh dos Exércitos, \"e Meu Nome será honrado entre as nações\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'E agora, ó sacerdotes, este mandamento é para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, '\"Se não ouvirdes isto e não dispuserdes o vosso coração para dar glória ao Meu Nome\", diz Yahweh dos Exércitos, \"enviarei uma maldição sobre vós, e amaldiçoarei tudo o que recebeis por vosso trabalho. Na verdade, já os amaldiçoei, porque não guardastes no coração os Meus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Vede! Repreenderei vossos descendentes e espalharei esterco em vossas caras, o esterco das vossas ofertas, e sereis lançados fora com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Sabereis que Eu enviei este mandamento para vós, e que Minha Aliança continuará com Levi\", diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, '\"Minha Aliança com ele era de vida e paz, e a dei para Me honrar, e ele Me honrou e se maravilhou por Meu Nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'O ensino verdadeiro estava em Sua boca e nenhuma falsidade foi achada em seus lábios. Ele caminhou Comigo em paz e retidão, e desviou muitos do pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Pois os lábios do sacerdote devem guardar sabedoria, e em sua boca, o povo deve procurar instrução, porque ele é o mensageiro de Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Mas vos desviastes do caminho verdadeiro. Vós fizestes muitos tropeçarem a respeito da Lei. Corrompestes a aliança de Levi\", diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, '\"Por isso, vos fiz desprezíveis e vis diante de todos os povos, porque não guardastes os Meus caminhos, mas mostrastes parcialidade na instrução da Lei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Não temos todos um único Pai? Não fomos criados por um único Deus? Por que agimos de uma maneira traiçoeira cada um contra seu irmão, profanando a aliança de nossos pais?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Judá agiu traiçoeiramente e uma coisa repugnante foi cometida em Israel e Jerusalém. Porque Judá profanou o Lugar Santo de Yahweh, que Ele ama, e se casou com a filha de um deus estrangeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Que Yahweh retire das tendas de Jacó qualquer homem que fizer isso, que esteja acordado e ciente, mesmo que traga ofertas para Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'E vós também fazeis isto: cobris o altar de Yahweh com lágrimas, choros e suspiros, porque Ele jamais atenta para as ofertas de vossas mãos, nem as aceita com prazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Mas perguntais: \"Por que não?\" Porque Yahweh foi testemunha diante de ti e a mulher da tua mocidade, contra a qual tens sido infiel. Apesar disso, ela foi tua companheira e tua esposa por aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Ele não vos fez um, com a porção do Seu Espírito? E por que Ele vos fez um? Porque Ele tinha esperança de ter uma descendência fiel. Portanto, vigiai o vosso espírito, e não sejais infiéis à mulher da vossa mocidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, '\"Porque Eu detesto o divórcio\", diz Yahweh, o Deus de Israel, \"e o que cobre suas vestes com violência\", diz Yahweh dos Exércitos. \"Portanto, vigiai o vosso espírito e não sejais infiéis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Vós tendes cansado Yahweh com vossas palavras. Mas dizeis: \"Como O temos cansado?\". Dizendo: \"Todo aquele que faz o mal é bom aos olhos de Yahweh, e Ele Se deleita neles\" ou \"Onde está o Deus da Justiça?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, '\"Vede! Estou para enviar Meu Mensageiro, e Ele preparará o caminho antes de Mim. E o Senhor, a Quem buscais, virá de repente para o Seu templo. O Mensageiro da Aliança, em Quem vos deleitais, virá\", diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Mas quem suportará o dia da Sua vinda? E quem poderá ficar de pé quando Ele aparecer? Porque Ele é como um fogo purificador, e como o sabão que branqueia completamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Ele sentará para julgar como um purificador da prata, e purificará os filhos de Levi. Ele os refinará como o ouro e a prata, e eles trarão as ofertas de justiça para Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Então, as ofertas de Judá e Jerusalém serão agradáveis a Yahweh, como nos dias antigos e como nos anos da antiguidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, '\"Portanto, Eu Me aproximarei de vós para o julgamento. Rapidamente testemunharei contra os feiticeiros, os adúlteros, as falsas testemunhas e contras aqueles que oprimem os trabalhadores em seus salários, contra aqueles que oprimem a viúva e os órfãos, contra aqueles que não amparam os estrangeiros, e contra aqueles que não Me honram,\" diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Porque Eu, Yahweh, não mudo; por isso, vós, povo de Jacó, não fostes consumidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Desde os dias de vossos pais, deixastes de lado Meus preceitos e não os guardastes. Voltai-vos para Mim, e Eu Me voltarei a vós\", diz Yahweh dos Exércitos. \"Mas vós dizeis: \'Como voltaremos?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Roubará o homem a Deus? Mas vós estais Me roubando. Ainda dizeis: \'Como Te roubamos?\' Nos dízimos e ofertas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Vós, toda a nação, estais amaldiçoados porque Me roubais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Trazei todo o dízimo à casa do tesouro, para que haja comida na Minha casa. E provai-Me agora nisto\", diz Yahweh dos Exércitos, \"se Eu não vos abrir as janelas do céus e derramar, de modo abundante, bênçãos sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Eu repreenderei quem destrói vossas plantações, para que não destruam a colheita da vossa terra; vossas vinhas nos campos não perderão seus frutos\", diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, '\"Todas as nações vos chamarão abençoada, pois sereis uma terra de deleites,\" diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, '\"Vossas palavras contra Mim foram duras\", diz Yahweh. \"Mas vós dizeis: \'O que falamos contra Ti?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Vós tendes dito: \'É inútil servir a Deus. Que proveito há em guardarmos Seus mandamentos ou lamentarmos diante de Yahweh dos Exércitos?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'E, agora, nós chamamos o arrogante de abençoado. Malfeitores não somente prosperam, como também tentam a Deus e escapam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Então, aqueles que temiam a Yahweh falaram uns com os outros. Yahweh prestou atenção e os ouviu, e um livro memorial foi escrito, diante Dele, sobre aqueles que temiam a Yahweh e honravam Seu Nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, '\"Eles serão Meus\", diz Yahweh dos Exércitos, \"Minha propriedade exclusiva, no dia em que Eu agir. Eu terei compaixão deles, como um homem que tem compaixão de seu próprio filho, que o serve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Então, mais uma vez, ficará evidente a vós quem é o justo e quem é o mau, quem adora a Deus e quem não O adora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Vede! O dia vem ardendo como uma fornalha, quando todos os orgulhosos e ímpios serão como a palha. O dia que vem os queimará\", diz Yahweh dos Exércitos, \"E não lhes sobrará raiz nem ramo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Mas para vós, que temeis o Meu Nome, o sol da justiça nascerá trazendo cura sob suas asas. Vós saireis saltando como bezerros do curral.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'E pisareis os ímpios, porque eles serão como cinza debaixo das plantas de vossos pés naquele dia em que Eu agir\", diz Yahweh dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, '\"Lembrai-vos de obedecer à Lei do Meu servo Moisés, os estatutos e decretos que lhe ordenei, em Horebe, para todo o Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Eis que vos enviarei Elias, o profeta, antes que venha o grande e terrível dia de Yahweh.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Ele converterá o coração dos pais aos filhos, e o coração dos filhos aos pais; para que Eu não venha e ataque a terra com destruição completa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Livro da genealogia de Jesus Cristo, Filho de Davi, Filho de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraão foi o pai de Isaque; Isaque, o pai de Jacó; Jacó, o pai de Judá e seus irmãos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Judá foi o pai de Farés e Zará, gerados de Tamar. Farés foi o pai Esrom; Esrom foi o pai de Arão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Arão foi o pai de Aminadabe; Aminadabe, pai de Nasom; Nasom, pai de Salmom;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salmom foi o pai de Boaz, gerado de Raabe; Boaz, o pai de Obede, gerado de Rute; Obede, pai de Jessé, e');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Jessé foi o pai do rei Davi. Davi foi pai de Salomão, gerado pela esposa de Urias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salomão foi o pai de Roboão; Roboão, pai de Abias; Abias, pai de Asa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Asa, pai de Josafá; Josafá foi o pai de Jorão, e Jorão foi um ancestral de Ozias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Ozias, foi o pai de Jotão; Jotão, pai de Acaz; Acaz, pai de Ezequias;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ezequias foi o pai de Manassés; Manassés, pai de Amom; Amom, pai de Josias, e');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Josias foi um ancestral de Jeconias e seus irmãos, no tempo da deportação para a Babilônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'E, após a deportação para a Babilônia, Jeconias foi o pai de Salatiel; Salatiel, foi um ancestral de Zorobabel;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Zorobabel, foi o pai de Abiúde; Abiúde, pai de Eliaquim; Eliaquim, pai de Azor;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Azor foi o pai de Sadoque; Sadoque, pai de Aquim; Aquim, pai de Eliúde;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Eliúde foi o pai de Eleazar; Eleazar, pai de Matã; Matã, pai de Jacó, e');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jacó foi o pai de José, marido de Maria, da qual nasceu Jesus, aquele que é chamado Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Todas as gerações: de Abraão até Davi, foram catorze gerações; de Davi até a deportação para a Babilônia, foram catorze gerações; e da deportação para a Babilônia até Cristo, foram catorze gerações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'O nascimento de Jesus Cristo aconteceu assim: Maria, sua mãe, estava noiva de José, mas antes de se unirem em casamento, ela achou-se grávida pelo Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'José, seu marido, era um homem justo, e não querendo desonrá-la publicamente, decidiu terminar seu noivado secretamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Enquanto pensava nessas coisas, um anjo do Senhor apareceu para ele em um sonho, dizendo: \"José, filho de Davi, não temas receber Maria como tua mulher, porque o que nela foi gerado é concebido pelo Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Ela dará à luz um filho e tu o chamarás de Jesus, porque Ele salvará Seu povo dos seus pecados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Tudo isso aconteceu para que se cumprisse o que foi dito pelo Senhor por meio do profeta:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '\"Eis que a virgem conceberá e dará à luz um filho, e o chamarão Emanuel, que significa \'Deus conosco\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'José ao acordar de seu sono, fez como o anjo do Senhor lhe havia ordenado e a recebeu como sua esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Entretanto não teve relações sexuais com ela, até que deu à luz um filho. E ele deu-lhe o nome de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Depois do nascimento de Jesus, em Belém da Judéia, nos tempos do rei Herodes, os sábios do Oriente chegaram a Jerusalém, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, '\"Onde está aquele que nasceu, o Rei dos Judeus? Nós vimos a sua estrela no Oriente e viemos adorá-Lo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Quando o rei Herodes ouviu isso, ficou perturbado, e com ele toda a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Herodes reuniu todos os chefes dos sacerdotes e os mestres do povo, e perguntou: \"Onde o Cristo vai nascer?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Eles disseram: \"Em Belém da Judeia, porque está escrito pelo profeta:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '\'E tu, Belém, na terra de Judá, não és a menor dentre as principais cidades de Judá, porque de ti virá um líder que irá pastorear o Meu povo de Israel\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Então Herodes chamou secretamente os sábios para perguntar-lhes exatamente quando a estrela tinha aparecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Ele os enviou a Belém, dizendo: \"Ide e procurai pelo menino com cuidado. Quando o achardes, avisai-me, para que eu possa ir e adorá-Lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Depois de terem ouvido o rei, partiram, e a estrela que eles tinham visto no Oriente foi adiante deles até que parou acima do lugar onde o menino estava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Quando eles viram a estrela, regozijaram-se com grande alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Eles entraram na casa, viram o menino com Maria, Sua mãe, curvaram-se e O adoraram. Eles abriram seus tesouros e ofereceram-Lhe presentes: ouro, incenso e mirra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Deus os alertou em sonho que não retornassem a Herodes, e eles partiram para o seu próprio país por outro caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Depois de partirem, um anjo do Senhor apareceu a José em sonho e disse: \"Levante-te, pega o menino e sua mãe, e foge para o Egito. Permanece lá até que eu te diga, porque Herodes procurará o menino para destruí-Lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Naquela noite, José levantou-se, pegou o menino com Sua mãe e partiu para o Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Ele permaneceu lá até a morte de Herodes. Isso cumpriu o que o Senhor dissera por meio do profeta: \"Do Egito chamei Meu Filho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Então Herodes, quando viu que tinha sido enganado pelos sábios, ficou furioso. Ele mandou matar todos os meninos de dois anos ou menos que estavam em Belém e em toda aquela região, de acordo com o tempo indicado com precisão pelos sábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Então cumpriu-se o que havia sido falado pelo profeta Jeremias:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '\"Uma voz de lamento e de grande gemido foi ouvida em Ramá, era Raquel lamentando por seus filhos, e ela recusou-se a ser confortada porque eles não mais existiam\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Quando Herodes morreu, eis que um anjo do Senhor apareceu em um sonho a José no Egito e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, '\"Levanta-te e pega o menino e Sua mãe e vai para a terra de Israel, porque aqueles que tentaram tirar a vida do menino estão mortos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'José levantou-se, pegou o menino e Sua mãe, e foi para a terra de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Entretanto, quando ele ouviu que Arquelau estava reinando sobre a Judéia, no lugar de seu pai Herodes, ficou com medo de ir para lá. Depois que Deus o avisou em um sonho, ele saiu para a região da Galiléia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'e foi viver em uma cidade chamada Nazaré. Cumpriu-se o que disseram os profetas, que ele se chamaria o Nazareno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Naqueles dias, surgiu João Batista pregando no deserto da Judeia, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, '\"Arrependei-vos, pois o Reino dos Céus está próximo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Pois este é aquele sobre o qual o profeta Isaías falou: \"A voz do que clama no deserto: \'Preparai o caminho do Senhor, fazei retos os Seus caminhos\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'João vestia roupas de pele de camelo, um cinto de couro em volta da cintura e seu alimento era gafanhotos e mel silvestre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Então Jerusalém, toda a Judéia e toda a região em volta do Rio Jordão foram a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'Eles foram batizados por João no Rio Jordão, confessando os seus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Quando ele viu muitos dos fariseus e dos saduceus, vindo a ele para serem batizados, disse-lhes: \"Raça de víboras, quem vos induziu a tentar fugir da ira que está vindo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Produzi, pois, frutos dignos de arrependimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'E não penseis em dizer entre vós: \'Nós temos Abraão como nosso pai\'. Pois eu vos digo que Deus é capaz de fazer surgir filhos a Abraão até mesmo dessas pedras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'O machado já foi posto à raiz das árvores. Toda árvore que não produz bom fruto é cortada e lançada ao fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Eu vos batizo com água para arrependimento, mas Aquele que vem depois de mim é mais poderoso do que eu e eu não sou digno nem de carregar Suas sandálias. Ele vos batizará com o Espírito Santo e com fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'A pá está em Sua mão para limpar completamente Sua eira e ajuntar Seu trigo no celeiro, mas Ele queimará a palha com fogo que nunca poderá ser apagado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Então Jesus veio da Galileia para o Rio Jordão para ser batizado por João,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'todavia João tentou impedi-Lo, dizendo: \"Eu preciso ser batizado por Ti, e Tu vens a mim?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Jesus respondeu e disse-lhe: \"Permita isto agora, pois é correto a nós cumprir toda a justiça\". Então João O permitiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Depois que foi batizado, Jesus saiu imediatamente da água e eis que os céus foram abertos sobre Ele, e viu o Espírito de Deus descendo como uma pomba e pousando sobre Si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Uma voz vinda dos céus disse: \"Este é o Meu Filho amado. Dele muito me agrado.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Então Jesus foi guiado pelo Espírito ao deserto para ser tentado pelo diabo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Após ter jejuado por quarenta dias e quarenta noites, Ele teve fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'O diabo veio e disse-Lhe: \"Se Tu És o Filho de Deus, ordena a estas pedras que se transformem em pães\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Mas Jesus, respondendo, disse-lhe: \"Está escrito: \'Não só de Pão viverá o homem, mas de toda palavra que procede da boca de Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Então o diabo O levou para a cidade santa, colocou-O no ponto mais alto do templo');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'e disse-Lhe: \"Se Tu És o Filho de Deus, lança-Te daqui abaixo, pois está escrito: \'Ele dará ordem aos Seus anjos para que tomem conta de ti,’ e \'Eles irão segurá-lo em suas mãos, para que teu pé não tropece contra uma pedra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Disse-lhe Jesus: \"Também está escrito: \'Tu não deves colocar o Senhor teu Deus à prova\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Novamente o diabo O levou para um lugar alto e mostrou a Ele todos os reinos do mundo juntamente com seu esplendor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'Ele disse a Jesus: \"Todas estas coisas te darei, se te prostrares e me adorares\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Então Jesus disse-lhe: \"Sai daqui Satanás! Pois está escrito: \'Adorarás ao Senhor teu Deus e somente a Ele darás culto\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Então o diabo O deixou e anjos vieram e O serviram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Quando Jesus soube que João havia sido preso, retirou-se para a Galiléia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Saindo de Nazaré foi viver em Cafarnaum, que fica junto ao mar da Galileia, nos territórios de Zebulom e Naftali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Isto aconteceu para que se cumprisse o que foi dito pelo profeta Isaías:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '\"Terra de Zebulom e terra de Naftali, caminho do mar, além do Jordão, Galileia dos Gentios!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'O povo que estava em trevas viu uma grande luz, e sobre aqueles que estavam na região da sombra da morte surgiu uma luz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'A partir daquele momento, Jesus começou a pregar e a dizer: \"Arrependei-vos, pois o Reino dos Céus está próximo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Enquanto caminhava à beira do mar da Galileia, viu dois irmãos, Simão, que é chamado Pedro, e André, que lançavam as redes ao mar, pois eram pescadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Disse-lhes Jesus: \"Vinde, segui-me e eu vos farei pescadores de homens\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Imediatamente eles deixaram as redes e O seguiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Enquanto Jesus caminhava, viu outros dois irmãos, Tiago, o filho de Zebedeu, e João. Eles estavam em um barco com Zebedeu, seu pai, consertando suas redes. Ele os chamou');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'e, imediatamente, eles deixaram o barco e seu pai, e O seguiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Jesus percorreu toda a Galileia, ensinando nas sinagogas deles, pregando as boas novas do Reino e curando todos os tipos de enfermidades e de doenças entre o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'As notícias sobre Ele correram por toda a Síria, e as pessoas trouxeram-Lhe todos aqueles que estavam doentes, com diversas enfermidades e tormentos: endemoninhados, epilépticos e paralíticos; e Jesus os curou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Grandes multidões O seguiram da Galileia, Decápolis, Jerusalém e Judeia e dalém do Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Quando Jesus viu a multidão, subiu ao monte, sentou-se, e seus discípulos vieram até Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Então Ele abriu a sua boca e os ensinou, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '\"Felizes são os pobres em espírito, pois deles é o Reino dos Céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Felizes os profundamente entristecidos, pois eles serão confortados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Felizes são os mansos, pois eles herdarão a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Felizes os que têm fome e sede de justiça, porque eles serão satisfeitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Felizes são os misericordiosos, pois eles obterão misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Felizes são os puros de coração, pois eles verão a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Felizes são os pacificadores, pois eles serão chamados filhos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Felizes os que são perseguidos por causa da justiça, pois deles é o Reino dos Céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Felizes sois vós quando as pessoas vos ofenderem e vos perseguirem, ou disserem todo tipo de maldades e falsidades contra vós por serdes meus seguidores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Regozijai-vos e alegrai-vos, pois grande é a vossa recompensa no céu. Pois dessa maneira as pessoas perseguiram os profetas que viveram antes de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Vós sois o sal da terra, mas se o sal perder o seu sabor, como poderá ser usado outra vez? Jamais será útil para alguma coisa, exceto para ser jogado fora e ser pisado pelas pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vós sois a luz do mundo. Uma cidade edificada sobre a colina não pode ficar escondida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Ninguém acende uma lamparina e coloca-a debaixo de um cesto, mas, em vez disso, coloca-a na candeia, e brilha para todos na casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Que a vossa luz brilhe diante das pessoas de tal forma que elas vejam as vossas boas obras e louvem ao vosso Pai que está no céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Não penseis que Eu vim para destruir a Lei ou os profetas; não vim para destruí-los, mas para cumpri-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Por isso, verdadeiramente, Eu vos digo que, até que os céus e a terra passem, nem um ponto ou til irá, de alguma forma, ser mudado na Lei, até que todas as coisas sejam cumpridas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Portanto qualquer um que quebrar o menor desses mandamentos e ensinar os outros a fazer o mesmo será chamado menor no Reino dos Céus. Mas qualquer um que guardar estes mandamentos e os ensinar será chamado grande no Reino dos Céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Por isso Eu vos digo que, se a vossa justiça não exceder a justiça dos escribas e fariseus, de forma alguma entrareis no Reino dos Céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Ouvistes o que foi dito nos tempos antigos: \'Não matarás\', e \'Qualquer um que matar estará sujeito a julgamento.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Mas Eu vos digo que qualquer um que se irar contra seu irmão estará sujeito a julgamento; e qualquer que disser para seu irmão: \'Tu és um idiota!\' estará sujeito a ser julgado no tribunal; e qualquer que disser: \'Seu tolo!\' estará sujeito ao fogo do inferno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Portanto se estiveres levando a tua oferta para o altar e ali te lembrares que o teu irmão tem algo contra ti,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'deixa a tua oferta lá, na frente do altar, e vai primeiro reconciliar-te com o teu irmão, e depois volta e apresenta a tua oferta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Entra em acordo com o teu acusador rapidamente, enquanto estás com ele no caminho para o tribunal, para que o teu acusador não te entregue ao juiz, e o juiz te entregue aos oficiais, e sejas lançado na prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Verdadeiramente eu te digo: não sairás dali até que pagues o último centavo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Ouvistes o que foi dito: \'Não adulterarás\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Mas Eu vos digo que qualquer um que olhar para uma mulher com intenção impura já cometeu adultério com ela em seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'E, se o teu olho direito te leva a pecar, tira-o e joga-o fora, porque é melhor uma parte do teu corpo perecer do que todo o teu corpo ser lançado no inferno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'E, se a tua mão direita te leva a pecar, corta-a e joga-a fora, pois é melhor uma das partes do teu corpo perecer do que todo o teu corpo ser lançado no inferno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Também foi dito: \'Qualquer um que mandar embora a sua esposa dê a ela uma carta de divórcio.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Mas Eu vos digo que todo aquele que se divorciar de sua esposa, exceto por causa de imoralidade sexual, faz dela uma adúltera; e qualquer um que casar com ela, depois que ela se divorciou, comete adultério.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Também ouvistes o que foi dito para aqueles nos tempos antigos: \'Não jureis falsamente, mas cumpri os vossos juramentos ao Senhor.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Mas Eu vos digo que não jureis por nada: nem pelo céu, pois é o trono de Deus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'nem pela terra, pois é o firmamento dos Seus pés; nem por Jerusalém, pois é a cidade do Grande Rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Nem jures pela tua cabeça, pois não podes tornar um fio de cabelo preto ou branco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Mas que a tua palavra seja: \'Sim, sim,\' ou \'Não, não.\' Qualquer coisa a mais do que isso vem do maligno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Ouvistes o que vos disseram: \'Olho por olho e dente por dente.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Entretanto Eu vos digo: não resistais a quem é mau; pelo contrário, a qualquer um que der um tapa no lado direito da tua face, oferece a ele o outro lado também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'E, se alguém quiser te levar ao tribunal e tomar a tua túnica, deixa essa pessoa tomar também a tua capa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'E, se alguém te obrigar a caminhar uma milha, vai com ele duas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Dá a qualquer um que te pedir, e não vires as tuas costas para qualquer pessoa que deseja te pedir algo emprestado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Ouvistes o que foi dito: \'Ama o teu próximo e odeia o teu inimigo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Contudo Eu vos digo: amai os vossos inimigos e orai por aqueles que vos perseguem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'para que sejais filhos do vosso Pai que está nos céus, pois Ele faz o Seu sol nascer sobre os maus e os bons e manda chuva para os justos e os injustos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Porque, se amardes apenas aqueles que vos amam, que recompensa ganhareis? Não é verdade que até os cobradores de impostos fazem a mesma coisa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'E, se saudardes apenas os vossos irmãos, o que fazeis a mais do que os outros? Não é verdade que até os gentios fazem a mesma coisa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Portanto sede perfeitos, como é perfeito o vosso Pai celestial.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Tende cuidado que não façais obras de justiça diante das pessoas para serdes vistos por elas, pois não tereis recompensa do vosso Pai que está no céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Então, quando derdes esmolas, não toqueis a trombeta diante de vós mesmos como fazem os hipócritas nas sinagogas e nas estradas, a fim de terem o louvor das pessoas. Verdadeiramente eu vos digo: eles já receberam a sua recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Todavia, quando derdes esmolas, não deixeis a vossa mão esquerda saber o que a vossa mão direita está fazendo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'para que as vossas esmolas sejam dadas em segredo; então o vosso Pai, que vê em segredo, vos recompensará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'E, quando orardes, não sejais como os hipócritas, pois eles amam orar em pé nas sinagogas e nas esquinas das ruas, para serem vistos pelas pessoas. Verdadeiramente eu vos digo que eles já receberam a sua recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Mas, quando orardes, entrai nos vossos quartos, fechai a porta, e orai a vosso Pai, que está em segredo; então vosso Pai, que vê em segredo, vos recompensará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'E, quando orardes, não façais repetições inúteis, como fazem os gentios; pois eles pensam que serão ouvidos por causa de suas muitas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Portanto não sejais como eles, pois o vosso Pai sabe do que precisais antes de pedirdes a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Portanto orai assim: \'Nosso Pai celestial, santificado seja o Teu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Que o Teu reino venha. Que a Tua vontade seja feita na terra assim como é feita no céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Dá-nos hoje o nosso pão diário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Perdoa as nossas dívidas, assim como nós perdoamos aos nossos devedores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'E não nos conduzas à tentação, mas livra-nos do maligno.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Porque se perdoardes as ofensas das pessoas, vosso Pai celestial também vos perdoará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Mas se não perdoardes as ofensas das pessoas, vosso Pai não perdoará as vossas ofensas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Além disso, quando jejuardes, não apresenteis tristeza no rosto, como fazem os hipócritas, pois eles desfiguram os seus rostos para demonstrar aparência de pessoas que jejuam. Verdadeiramente Eu vos digo que já receberam a recompensa deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Entretanto vós, quando jejuardes, ungi as vossas cabeças e lavai os vossos rostos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'para que não demonstreis às pessoas que estais jejuando, mas apenas ao vosso Pai, que está em segredo. E vosso Pai, que vos vê em segredo, vos recompensará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Não acumuleis para vós tesouros na terra, onde traça e ferrugem os consomem, e onde ladrões invadem e roubam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Em vez disso, acumulai tesouros no céu, onde nem traça nem ferrugem destroem, e onde ladrões não invadem nem roubam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Pois onde estiver o vosso tesouro, ali estará também o vosso coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Os olhos são a lâmpada do corpo. Portanto, se os vossos olhos são bons, todo o vosso corpo se encherá com luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Mas, se os vossos olhos são maus, todo o vosso corpo se encherá de trevas. Assim, se a luz que está em vós são na verdade trevas, quão grandes são essas trevas!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Ninguém pode servir a dois senhores, pois irá odiar a um e amar o outro, ou será devoto de um e desprezará o outro. Não podeis servir a Deus e às riquezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Portanto Eu vos digo: não vos preocupeis com a vossa vida, o que comereis ou o que bebereis, ou acerca do vosso corpo, o que vestireis. Pois a vida não é mais do que a comida, nem o corpo mais do que as roupas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Vede as aves do céu: elas não semeiam, nem colhem, nem se ajuntam em celeiros, contudo vosso Pai celestial as alimenta. Não sois muito mais valiosos do que elas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'E qual dentre vós que, sendo ansioso, pode adicionar um côvado a seu tempo de vida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'E por que estais ansiosos com o vestuário? Considerai os lírios dos campos, como eles crescem: eles não trabalham e não tecem roupa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Ainda assim eu vos digo: até mesmo Salomão em toda a sua glória não se vestiu como um deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Se Deus veste a grama dos campos, que existe hoje e amanhã é lançada ao forno, quanto mais Ele vos vestirá, homens de pequena fé?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Portanto não estejais ansiosos, dizendo: \'O que comeremos?\' ou, \'O que beberemos?\' ou, \'Com o que nos vestiremos?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Pois os gentios buscam todas essas coisas, e o vosso Pai celestial sabe que precisais de todas elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Mas buscai primeiro o Seu reino e a Sua justiça e então todas essas coisas vos serão providenciadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Portanto não estejais ansiosos pelo amanhã, pois o amanhã trará suas próprias ansiedades. É suficiente ao dia de hoje o seu próprio mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Não julgueis para que não sejais julgados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'pois com o julgamento com que julgardes sereis julgados, e com a medida com que medirdes sereis medidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'E por que enxergas o cisco que está no olho do teu irmão, mas não percebes a tora de madeira que está no teu próprio olho?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Como podes dizer a teu irmão: \'Deixa-me tirar o cisco que está em teu olho\', enquanto tens uma tora de madeira em teu próprio olho?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Hipócrita! Tira primeiro a tora de madeira do teu próprio olho e então verás claramente, para que possas tirar o cisco que está no olho do teu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Não deis o que é santo aos cães, nem lanceis as vossas pérolas aos porcos, para que eles não as pisem com os pés e voltando-se contra vós, vos despedacem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Pedi, e vos será dado; buscai, e achareis; batei, e vos será aberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Pois todo aquele que pede, recebe; e aquele que busca, encontra; e para o que bater será aberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Ou qual homem entre vós que, se o filho pedir um pedaço de pão, dará a ele uma pedra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Ou se o filho pedir um peixe, lhe dará uma cobra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Portanto se vós, sendo maus, sabeis dar boas dádivas aos vossos filhos, quanto mais vosso Pai celestial, que está nos céus, não dará coisas boas para aqueles que Lhe pedirem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Portanto tudo aquilo que desejais que as pessoas vos façam, deveis também fazer para elas; porque essa é a Lei e os Profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Entrai pela porta estreita, porque larga é a porta e espaçoso é o caminho que leva à destruição, e existem muitas pessoas que passam por ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Mas estreita é a porta, e apertado é o caminho que leva à vida, e poucos são aqueles que o encontram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Cuidado com os falsos profetas, os quais chegam com roupas de ovelhas, mas na verdade são lobos famintos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Pelos seus frutos os conhecereis. As pessoas colhem uvas de espinheiros, ou figos de urtigas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Do mesmo modo, toda árvore boa produz bons frutos, mas a árvore má produz frutos maus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Não existe árvore boa que produza frutos maus, e também não existe árvore má que produza frutos bons.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Toda árvore que não produz bom fruto é cortada e lançada ao fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Então é pelos seus frutos que os conhecereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Nem todo que Me diz: \'Senhor, Senhor,\' entrará no Reino dos Céus, mas apenas o que faz a vontade de Meu Pai que está nos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Muitas pessoas Me dirão naquele dia: \'Senhor, Senhor, nós não profetizamos em Teu nome? Em Teu nome não expulsamos demônios e não fizemos muitos milagres?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Então Eu lhes direi abertamente: \'Eu nunca vos conheci! Afastai-vos de Mim, vós que praticais a iniquidade!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Portanto todo aquele que ouve as Minhas palavras e as obedece será como o homem sábio que construiu a sua casa sobre a rocha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'Veio a chuva, transbordaram os rios, e os ventos sopraram e bateram sobre aquela casa; mas ela não caiu, pois tinha sido alicerçada sobre a rocha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Mas todo aquele que ouve as Minhas palavras e não obedece, será como um homem tolo que construiu a sua casa sobre a areia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'Veio a chuva, transbordaram os rios, os ventos sopraram e bateram sobre aquela casa, e ela caiu; e a sua destruição foi completa.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'E aconteceu que, quando Jesus acabou de falar essas palavras, as multidões estavam maravilhadas pelo Seu ensino,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'porque Ele ensinava como alguém que tinha autoridade, e não como os escribas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Quando Jesus desceu do monte, uma grande multidão O seguiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Então veio um leproso e ajoelhou-se diante Dele, dizendo: \"Senhor, se Tu queres, podes me purificar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Jesus estendeu Sua mão e o tocou, dizendo: \"Eu quero. Sê purificado\". Imediatamente ele foi curado da sua lepra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Jesus disse-lhe: \"Vê que não digas nada a homem algum. Segue o teu caminho, mostra-te para o sacerdote e apresenta a oferta que Moisés ordenou, como um testemunho para eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Quando Jesus entrou em Cafarnaum, um centurião veio a Ele e suplicou:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, '\"Senhor, meu servo está prostrado em casa paralisado em terrível sofrimento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Jesus disse-lhe: \"Eu irei e o curarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'O centurião respondeu: \"Senhor, eu não sou digno de que entres na minha casa, mas apenas diz uma palavra e meu servo será curado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'pois eu também sou um homem sujeito à autoridade e tenho soldados abaixo de mim. Eu digo a este: \'Vai,\' e ele vai, e para outro: \'Vem,\' e ele vem, e para meu servo: \'Faz isso,\' e ele faz.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Quando Jesus ouviu isso, ficou admirado e disse à aqueles que o estavam seguindo: \"Verdadeiramente Eu vos digo que nem mesmo em Israel encontrei alguém com tanta fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Eu vos digo: muitos virão do Leste e do Oeste, e sentarão à mesa com Abraão, Isaque e Jacó, no Reino do Céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Mas os filhos do reino serão lançados nas trevas exteriores, onde haverá choro e ranger de dentes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Jesus disse ao centurião: \"Vai! Assim como crestes, assim seja feito a ti\". E o servo foi curado naquela mesma hora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Quando Jesus entrou na casa de Pedro, viu a sogra deste deitada com febre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Jesus tocou a mão dela, e a febre a deixou; então ela se levantou e começou a servi-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Ao anoitecer, as pessoas trouxeram a Jesus muitos que eram controlados por demônios, e Ele expulsou os espíritos com uma palavra, e curou todos os que estavam doentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Dessa forma, cumpriu-se o que foi dito por Isaías, o profeta: \"Ele tomou sobre Si nossas doenças e carregou nossas enfermidades\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Quando Jesus viu a multidão em Sua volta, deu instruções que partissem para o outro lado do mar da Galiléia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Então um escriba veio a Ele e disse: \"Mestre, eu Te seguirei para qualquer lugar que fores\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Jesus disse-lhe: \"As raposas têm tocas, e os pássaros do céu possuem ninhos, mas o Filho do Homem não tem onde repousar a Sua cabeça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Outro dos discípulos disse-Lhe: \"Senhor, permita-me primeiro ir e enterrar meu pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Mas Jesus disse-lhe: \"Segue-Me, e deixa os mortos enterrarem seus próprios mortos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Quando Jesus entrou em um barco, Seus discípulos O seguiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Então veio uma grande tempestade no mar, de tal forma que as ondas cobriam o barco; contudo Jesus estava dormindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Os discípulos vieram a Ele e O acordaram, dizendo: \"Salva-nos Senhor; nós estamos prestes a morrer!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Jesus disse-lhes: \"Por que estais com medo? Sois de pequena fé?\" Então Ele se levantou, repreendeu os ventos e o mar, e houve uma grande calmaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Os homens maravilharam-se e disseram: \"Que tipo de homem é este, que até mesmo os ventos e o mar Lhe obedecem?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Quando Jesus chegou ao outro lado, na região dos gadarenos, dois homens que eram controlados por demônios O encontraram. Eles estavam vindo dos sepulcros e eram muito violentos, de tal forma que nenhum viajante podia passar por aquele caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Então eles gritaram e disseram: \"O que temos nós Contigo, Filho de Deus? Vieste aqui para nos atormentar antes do tempo determinado?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Não muito longe dali, uma grande manada de porcos estava se alimentando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Os demônios imploravam a Jesus dizendo: \"Se nos expulsares, manda-nos para aquela manada de porcos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Jesus disse-lhes: \"Ide!\" Os demônios saíram e foram para os porcos; e então toda a manada precipitou-se pela ladeira íngreme em direção ao mar e os porcos morreram na água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Os homens que tomavam conta dos porcos fugiram e, quando entraram na cidade, contaram tudo, inclusive o que tinha acontecido com os endemoninhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Então toda a cidade veio para se encontrar com Jesus. Quando eles O viram, suplicaram-Lhe para que deixasse a região deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Jesus entrou em um barco, cruzou o mar e veio à Sua própria cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Então trouxeram a Ele um homem paralítico deitado numa esteira. Vendo a fé deles, Jesus disse ao homem paralítico: \"Filho, tem bom ânimo. Os teus pecados foram perdoados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Então alguns dos escribas disseram entre si: \"Este homem está blasfemando\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Jesus conhecia seus pensamentos e disse: \"Por que estais pensando o mal em vossos corações?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'O que é mais fácil dizer: \'Teus pecados estão perdoados\' ou dizer: \'Levanta-te e anda\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Mas, para que saibais que o Filho do Homem tem autoridade na terra para perdoar pecados...\" — disse então ao paralítico — \"Levanta-te, pega a tua esteira e vai para tua casa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Então o homem se levantou e saiu para a sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Quando as multidões viram isso, ficaram maravilhadas e louvaram a Deus, que tinha dado tamanha autoridade às pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Saindo dali, Jesus viu um homem chamado Mateus, que estava sentado no local de coletar impostos, e disse-lhe: \"Segue-me\". Ele se levantou e O seguiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Estando Jesus em uma casa, sentado à mesa para comer, muitos coletores de impostos e pecadores vieram e jantaram com Ele e seus discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Quando os fariseus viram isso, disseram aos Seus discípulos: \"Por que vosso mestre come com os coletores de impostos e os pecadores?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Ao ouvir isso, Jesus disse: \"Os que têm saúde não precisam de um médico, apenas os doentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Vós deveríeis aprender o que significa isto: \'Eu desejo misericórdia e não sacrifício\', pois Eu não vim para chamar os justos para o arrependimento, mas sim os pecadores\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Então os discípulos de João vieram a Jesus e disseram: \"Por que nós e os fariseus jejuamos com frequência, mas Teus discípulos não jejuam?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Jesus disse-lhes: \"Podem os convidados de um casamento ficarem tristes enquanto o noivo ainda está com eles? Mas virão os dias em que o noivo será tirado deles, e então eles jejuarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Ninguém coloca um pedaço de tecido novo em uma roupa velha, pois o remendo se romperá da roupa, e um rasgo pior será feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Ninguém coloca vinho novo em odres velhos; se fizer isso, as peles vão se romper, o vinho será derramado, e os odres serão destruídos. Ao invés disso, coloca-se vinho novo em odres novos, e ambos serão preservados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Enquanto Jesus dizia essas coisas, um oficial veio e ajoelhou-se diante Dele, dizendo: \"Minha filha acabou de falecer, mas vem e coloca Tua mão sobre ela, e ela viverá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Então Jesus se levantou e o seguiu com Seus discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Eis que uma mulher, que há doze anos sofria de hemorragia, veio atrás de Jesus e tocou a borda de Sua roupa;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'pois ela disse para si: \"Se eu apenas tocar em Sua roupa, serei curada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Todavia Jesus virou-se, e ao vê-la disse: \"Ânimo, filha, tua fé te curou\". E a mulher foi curada instantaneamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Quando Jesus entrou na casa do oficial, viu que os flautistas e as multidões estavam fazendo muito barulho;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'Ele disse: \"Retirai-vos daqui, pois a menina não está morta, mas dorme\". Porém eles riram Dele em zombaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Quando a multidão foi retirada, Ele entrou no quarto, pegou a menina pela mão e ela se levantou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Essa notícia espalhou-se por toda aquela região.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Enquanto Jesus seguia adiante, dois homens cegos O seguiram, gritando e dizendo: \"Tenha compaixão de nós, Filho de Davi!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Quando Jesus entrou em casa, os homens cegos vieram a Ele. Jesus disse-lhes: \"Credes que Eu posso fazer isso?\" Eles responderam: \"Sim, Senhor.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Então Jesus tocou nos olhos deles e disse: \"Seja feito conforme a vossa fé\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'E os olhos deles foram abertos. Então Jesus ordenou terminantemente a eles: \"Vede que ninguém fique sabendo disso.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Mas os dois homens saíram e espalharam essa notícia por toda aquela região.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Enquanto aqueles dois homens iam embora, um homem mudo possuído por um demônio foi trazido a Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Quando o demônio foi expulso, o homem mudo falou. As multidões estavam atônitas e disseram: \"Isso nunca foi visto anteriormente em Israel!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Mas os fariseus disseram: \"É pelo chefe dos demônios que Ele expulsa demônios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Jesus foi por todas as cidades e povoados, ensinando em suas sinagogas, pregando o Evangelho do reino e curando todo tipo de doenças e enfermidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Quando viu as multidões, teve compaixão delas, porque estavam abatidas e confusas, pois eram como ovelhas sem um pastor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Ele disse a Seus discípulos: \"A seara é grande, mas os trabalhadores são poucos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Portanto rogai ao Senhor da seara, para que envie trabalhadores para Sua seara\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Jesus reunindo seus doze discípulos, deu-lhes autoridade sobre os espíritos imundos, para expulsá-los, e para curar todos os tipos de doenças e enfermidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Os nomes dos doze apóstolos eram estes: o primeiro, Simão, também chamado Pedro, e André, seu irmão; Tiago, filho de Zebedeu, e João, seu irmão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filipe e Bartolomeu; Tomé e Mateus, o coletor de impostos; Tiago, filho de Alfeu, e Tadeu;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simão, o zelote, e Judas Iscariotes, que O iria trair.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Jesus enviou esses doze; Ele os instruiu dizendo: \"Não vades a nenhum lugar onde os gentios vivem, e não entreis em nenhuma das cidades dos samaritanos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Em vez disso, ide às ovelhas perdidas da casa de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'E à medida que seguirdes, pregai e dizei: \'O Reino dos Céus está próximo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Curai os enfermos, ressuscitai os mortos, purificai os leprosos, e expulsai demônios. De graça recebestes, de graça dai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Não leveis ouro, prata, nem bronze em vossos cintos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'nenhuma bolsa para suas jornadas, nem duas túnicas, nem sandálias, nem cajado, pois digno é o trabalhador do seu alimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Qualquer cidade ou povoado em que entrardes, encontrai quem é digno ali, e ficai lá até partirdes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Quando entrardes na casa, saudai-a.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Se a casa é digna, deixai a vossa paz sobre ela; mas, se não é digna, que a vossa paz volte para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'E para aqueles que não vos receberem ou ouvirem as vossas palavras, quando partirdes daquela casa ou cidade, batei a poeira de vossos pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Verdadeiramente Eu vos digo: haverá mais tolerância para a terra de Sodoma e Gomorra no dia do julgamento do que para essa cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Vede que Eu vos envio como ovelhas para o meio de lobos, portanto sede sábios como serpentes e dóceis como pombas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Estai alerta contra as pessoas, pois elas vos entregarão aos tribunais e nas suas sinagogas, sereis chicoteados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Por minha causa vos trarão perante governantes e reis, como um testemunho a eles e aos gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Quando eles vos entregarem, não fiqueis ansiosos sobre como ou o que ireis falar, pois vos será dado o que haveis de dizer naquele momento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Pois não sereis vós que falareis, mas o Espírito do vosso Pai que falará por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Irmãos entregarão irmãos para a morte, e o pai ao seu filho. Filhos se levantarão contra seus pais e os matarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Vós sereis odiados por todos por causa do Meu Nome, mas aquele que persistir até o fim será salvo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Quando eles vos perseguirem nessa cidade, fugi para a próxima, pois verdadeiramente eu vos digo: não tereis ido a todas as cidades de Israel, antes que o Filho do Homem venha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'O discípulo não é maior que seu mestre, nem o servo está acima de seu senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'É suficiente para o discípulo que ele seja como seu mestre, e o servo como seu senhor. Se eles chamaram o mestre da casa de Belzebu, bem pior serão os nomes que eles darão aos membros da sua casa!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Portanto não os temais, pois não há nada oculto que não será revelado, e nada escondido que não será conhecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'O que eu vos digo na escuridão, dizei-o à luz do dia e o que ouvis em sussurro aos vossos ouvidos, proclamai-o sobre o topo das casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Não tenhais medo daqueles que matam o corpo, mas não conseguem matar a alma. Ao invés disso, temei Aquele que pode destruir tanto a alma quanto o corpo no inferno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Não são dois pardais vendidos por uma pequena moeda? Mesmo assim nenhum deles cai ao chão sem o conhecimento do vosso Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Mas mesmo os cabelos da vossa cabeça, estão todos contados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Não temais. Vós sois muito mais valiosos que muitos pardais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Portanto todo aquele que Me confessar diante dos homens, Eu também o confessarei diante de Meu Pai que está no céu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'entretanto aquele que Me negar diante dos homens, Eu também o negarei diante de Meu Pai que está no Céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Não penseis que Eu vim trazer paz sobre a terra; não vim trazer paz, mas espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Eu vim para colocar o homem contra seu pai, e a filha contra sua mãe, e a nora contra a sua sogra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'Os inimigos do homem serão os da sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Aquele que ama o pai ou a mãe mais do que a Mim não é digno de Mim; e aquele que ama o filho ou a filha mais do que a Mim não é digno de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'Aquele que não pegar sua cruz e Me seguir não é digno de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Aquele que achar sua vida irá perdê-la; mas aquele que perder sua vida por Minha causa irá achá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Aquele que vos receber, a Mim receberá, e aquele que receber a Mim, também receberá Aquele que Me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Aquele que receber um profeta, porque ele é um profeta, receberá recompensa de profeta, e aquele que receber um homem justo, porque ele é um homem justo, receberá recompensa de homem justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Quem der até mesmo um copo de água a um destes pequeninos, por ele ser um discípulo, verdadeiramente eu vos digo: ele não perderá a sua recompensa de modo alguma\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Quando Jesus terminou de instruir os doze discípulos, partiu dali para ensinar e pregar nas cidades deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'João, ao ouvir na prisão sobre os feitos de Jesus, enviou uma mensagem por meio dos seus discípulos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'e disse-Lhe: \"Tu És o que estava por vir, ou há outra pessoa que devemos esperar?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Jesus respondeu-lhes: \"Ide e anunciai a João o que vedes e ouvis:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'cegos recebem a vista, coxos andam, leprosos são purificados, surdos ouvem, mortos são trazidos de volta à vida, e aos necessitados são anunciadas as boas novas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'E abençoado é aquele que não encontra motivo de tropeço em Mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Enquanto eles iam por seu caminho, Jesus começou a dizer às multidões sobre João: \"O que fostes ver no deserto? Uma cana sendo balançada pelo vento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'O que fostes ver? Um homem vestido com roupas finas? Na verdade, aqueles que vestem roupas finas vivem em casas de reis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Mas, o que fostes ver? Um profeta? Sim, Eu vos digo: muito mais que profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Este é aquele sobre quem está escrito: \'Vê, Eu estou enviando Meu mensageiro diante da tua face, o qual irá preparar o caminho diante de ti\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Em verdade vos digo: entre os nascidos de mulher, ninguém é maior do que João Batista; porém a pessoa menos importante no Reino dos Céus é maior do que ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Desde os dias de João Batista até hoje, o Reino dos Céus sofre violência, e homens que se utilizam de violência o tomam à força.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Pois todos os profetas e a lei profetizaram até João.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'E, se vós quereis aceitar isso, este é Elias, o que havia de vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Aquele que tiver ouvidos para ouvir ouça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'A que devo comparar esta geração? É como crianças brincando no mercado, que sentam e chamam uns aos outros');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'e dizem: \'Nós tocamos flauta a vós, e não dançastes. Nós lamentamos, e não pranteastes\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Pois veio João, não comendo, nem bebendo, e eles disseram: \'Ele tem demônio\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'O Filho do Homem veio comendo e bebendo, e eles disseram: \'Olhem, Ele é um homem glutão e um beberrão, um amigo de coletores de impostos e de pecadores! Todavia a sabedoria é justificada por suas obras\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Então Jesus começou a repreender as cidades onde a maioria de seus milagres foram realizados, porque elas não se arrependeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '\"Ai de ti, Corazim! Ai de ti, Betsaida! Se os milagres que foram realizados em vós fossem realizados em Tiro e Sidom, eles teriam se arrependido há muito tempo com roupas de saco e cinza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Porém haverá mais tolerância para Tiro e Sidom no dia do julgamento do que para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Tu, Cafarnaum, serás exaltada ao céu? Não! Serás lançada para baixo, ao inferno; pois, se em Sodoma se realizassem os milagres que foram realizados em ti, ela teria permanecido até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Mas Eu te digo que será mais fácil para a terra de Sodoma, no dia do juízo, do que para ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'Naquele momento, Jesus disse: \"Eu Te louvo, Pai, Senhor do céu e da terra, pois ocultaste estas coisas aos sábios e entendidos, e as revelastes às criancinhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Sim, Pai, pois assim foi do Teu agrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Todas as coisas foram confiadas a Mim por Meu Pai, e ninguém conhece o Filho, exceto o Pai, e ninguém conhece o Pai, exceto o Filho e aquele a quem o Filho desejar revelar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Vinde a Mim todos os que estais cansados e sobrecarregados, e Eu vos darei descanso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Tomai o Meu jugo sobre vós e aprendei de Mim, pois Sou manso e humilde de coração, e encontrareis descanso para as vossas almas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'porque o meu jugo é suave e a minha carga é leve\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Naquele tempo, Jesus passou pelas plantações de cereais, no dia de sábado. Seus discípulos estavam com fome e começaram a colher espigas e comê-las.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Mas, quando os fariseus viram isso, disseram a Jesus: \"Olha, Teus discípulos fazem o que não é permitido fazer no sábado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Todavia Jesus disse-lhes: \"Nunca lestes o que Davi fez quando ele e seus homens estavam com fome?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Ele entrou na casa de Deus e comeu os pães consagrados, os quais não eram permitidos a ele comer, nem aos que estavam com ele, mas permitido somente aos sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'E não lestes na lei que, no sábado, os sacerdotes profanam esse dia no templo, contudo ficam sem culpa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Todavia eu vos digo: está aqui Aquele que é maior do que o templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Se soubésseis o que significa: \'Eu desejo misericórdia e não sacrifício\', não condenaríeis inocentes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'pois o Filho do Homem é Senhor do sábado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Então Jesus partiu de lá e entrou na sinagoga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Eis que lá havia um homem com uma mão atrofiada. Os fariseus perguntaram a Jesus: \"É permitido curar no sábado?\" de forma que eles pudessem acusá-Lo de pecar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Jesus disse-lhes: \"Que homem entre vós, o qual tendo apenas uma ovelha, e, se essa ovelha cair em um buraco profundo, no sábado, não a agarraria e a tiraria dali?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Quanto mais valor, então, tem um homem do que uma ovelha! Logo, é permitido fazer o bem no sábado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Então Jesus disse ao homem: \"Estende a tua mão\". Ele a estendeu e ela foi restaurada, ficando exatamente como a outra mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Mas os fariseus saíram e conspiravam contra Ele, sobre como poderiam tirar-Lhe a vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Jesus, percebendo isso, afastou-se dali. Muitas pessoas O seguiram, e Ele curou a todas');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'e ordenou-lhes que não O fizesse conhecido aos outros,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'para se tornar verdade o que foi dito por Isaías, o profeta:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '\"Vede Meu servo a quem escolhi, O Meu amado, em quem Minha alma tem prazer. Eu colocarei Meu Espírito sobre Ele, e Ele anunciará justiça aos gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Ele não discutirá, nem gritará, nem alguém ouvirá Sua voz nas ruas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Ele não quebrará uma cana torcida, Ele não apagará o pavio que fumega, até que Ele leve a justiça à vitória,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'e os gentios terão confiança em Seu nome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Então foi levado a Ele um homem cego e mudo, possuído por um demônio, e Jesus o curou. O resultado foi que o homem mudo passou a ver e a falar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Todas as multidões ficaram maravilhadas e disseram: \"Pode este homem ser o Filho de Davi?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Mas, quando os fariseus ouviram desse milagre, disseram: \"Este homem não expulsa demônios senão por Belzebu, o príncipe dos demônios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Jesus, conhecendo os seus pensamentos, disse-lhes: \"Todo reino dividido contra si mesmo ficará desolado, e toda cidade ou casa dividida contra si mesma não permanecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Se Satanás expulsa Satanás, ele está dividido contra si mesmo; como o seu reino permanecerá?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'E se Eu expulso demônios por Belzebu, por quem expulsam os vossos filhos? Por causa disso, eles serão vossos juízes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Mas se Eu expulso os demônios pelo Espírito de Deus, então o Reino de Deus chegou a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'E como pode alguém entrar na casa do homem forte e roubar seus pertences sem amarrá-lo primeiro? Então, ele roubará os pertences de sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Aquele que não está comigo é contra Mim, e aquele que comigo não ajunta espalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Por isso, vos digo: todo pecado e blasfêmia serão perdoados aos homens, mas a blasfêmia contra o Espírito não será perdoada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Qualquer um que falar alguma palavra contra o Filho do Homem, isso lhe será perdoado; mas aquele que falar contra o Espírito Santo, isso não lhe será perdoado, nem neste mundo, nem no mundo que está por vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Se uma árvore é boa, o seu fruto será bom; se uma árvore é má, o seu fruto será mau, pois uma árvore é conhecida por seus frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Raça de víboras, se vós sois maus, como podeis dizer coisas boas? Pois a boca fala do que o coração está cheio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'O homem bom, do seu bom tesouro, tira o que é bom, já o homem mau, do seu mau tesouro, tira o que é mau.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'E eu vos digo que, no dia do juízo, as pessoas prestarão contas por cada palavra inútil que elas disserem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Portanto, pelas tuas palavras sereis justificados, e pelas tuas palavras sereis condenados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Então, certos escribas e fariseus disseram a Jesus: \"Mestre, nós queremos ver um sinal Teu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Contudo Jesus respondeu-lhes: \"Uma geração má e adúltera procura por sinal; mas nenhum sinal lhe será dado, exceto o sinal de Jonas, o profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Porque assim como Jonas esteve três dias e três noites na barriga do grande peixe, assim estará o Filho do Homem três dias e três noites no coração da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Os homens de Nínive se levantarão, no juízo, contra essa geração de pessoas e a condenarão, pois eles se arrependeram com a pregação de Jonas, e vede: está aqui alguém maior do que Jonas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'A rainha do Sul se levantará, no juízo, com os homens dessa geração e a condenará, pois ela veio dos confins da terra para ouvir a sabedoria de Salomão, e vede: está aqui alguém maior do que Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Quando um espírito imundo sai de um homem, anda por lugares secos e procura por descanso, mas não encontra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Então diz: \'Eu voltarei para a minha casa, de onde vim\'. Tendo voltado, encontra a casa varrida e posta em ordem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Então vai e leva consigo outros sete espíritos piores que ele mesmo, e todos eles entram para viver lá. Então a condição final desse homem se torna pior do que a primeira. Assim será com essa geração má\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Enquanto Jesus ainda falava às multidões, eis que sua mãe e seus irmãos estavam do lado de fora, procurando falar com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Alguém lhe disse: \"Olha, Tua mãe e Teus irmãos estão do lado de fora, procurando falar contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Mas Jesus disse ao que falou com Ele: \"Quem é Minha mãe? E quem são Meus irmãos?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Então Ele estendeu as mãos aos Seus discípulos e disse: \"Olhai, aqui estão minha mãe e meus irmãos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Pois aquele que faz a vontade do meu Pai que está no céu, essa pessoa é Meu irmão, irmã e mãe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Naquele dia Jesus saiu de casa e sentou-se à beira do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Uma grande multidão se juntou em volta Dele. Então Ele entrou em um barco e sentou-se; toda a multidão permaneceu em pé na praia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Então Jesus disse-lhes muitas coisas em parábolas. Ele disse: \"Eis que o semeador saiu para semear.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Enquanto ele semeava, algumas sementes caíram na beira da estrada, e os pássaros vieram e as devoraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Outras sementes caíram no solo rochoso, onde elas não tinham muita terra, e imediatamente elas brotaram porque o solo não tinha profundidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Mas, quando o sol nasceu, elas foram queimadas, pois não tinham raízes, e então secaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Outras sementes caíram entre as plantas espinhosas, as quais cresceram e as sufocaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Outras sementes caíram em solo bom e produziram grãos, algumas cem vezes mais, outras sessenta e outras trinta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Aquele que tem ouvidos, ouça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Os discípulos vieram e disseram a Jesus: \"Por que falas às multidões em parábolas?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Jesus respondendo, disse-lhes: \"A vós tem sido dado o privilégio de entender os mistérios do Reino dos Céus, mas não a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Porque àquele que tem, muito mais lhe será dado, porém àquele que não tem, até o que tem lhe será tomado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Então, Eu lhes falei em parábolas, porque, mesmo vendo, não veem realmente e, mesmo ouvindo, não ouvem, nem entendem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Para eles, a profecia de Isaías é cumprida, a qual diz: \'Ouvindo, ouvireis, mas de maneira nenhuma entendereis; vendo, vereis, mas de maneira nenhuma percebereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Porque o coração deste povo tornou-se insensível, e ouviram com má vontade, e fecharam seus olhos; se assim não fosse, eles perceberiam com seus olhos, ouviriam com seus ouvidos, entenderiam com seus corações, e se arrependeriam, e Eu os curaria\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Mas abençoados são os vossos olhos, porque veem; e os vossos ouvidos, porque ouvem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Em verdade eu vos digo que muitos profetas e homens justos desejaram ver as coisas que vós vedes, e eles não as viram, e ouvir as coisas que vós ouvistes, e eles não as ouviram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Compreendei, então, a parábola do semeador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Quando alguém ouve a palavra do Reino, mas não a entende, então o maligno vem e rouba aquilo que foi semeado em seu coração. Essa é a semente que foi semeada à beira do caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'A que foi semeada em solo rochoso é aquele que ouve a palavra e imediatamente a recebe com alegria;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'entretanto ele não tem raiz em si mesmo, mas só permanece por pouco tempo. Quando a tribulação ou a perseguição se levanta por causa da palavra, ele tropeça imediatamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'A que foi semeada entre plantas espinhosas é aquele que ouve a palavra, mas as preocupações do mundo e o engano das riquezas sufocam a palavra, e ela torna-se infrutífera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Aquela que foi semeada em bom solo é aquele que ouve a palavra e a entende; esse é o que verdadeiramente produz fruto; alguns cem vezes mais do que foi plantado, alguns sessenta, e alguns trinta vezes mais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Jesus apresentou-lhes outra parábola, dizendo: \"O Reino dos Céus é como um homem que semeou boa semente em seu campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Porém, enquanto as pessoas dormiam, seu inimigo veio e também semeou ervas daninhas no meio do trigo, e, então, foi embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Quando as sementes de trigo brotaram e produziram suas espigas, então ervas daninhas também apareceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Os servos do dono do campo vieram e disseram-lhe: \'Senhor, não plantaste boa semente no seu campo? Como agora ele tem ervas daninhas?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Ele disse-lhes: \'Um inimigo fez isso\'. Os servos disseram a ele: \'Queres, então, que as arranquemos?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'O dono do campo disse: \'Não! Porque enquanto vós puxardes as ervas daninhas, podereis puxar o trigo também junto com elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Deixai os dois crescerem juntos até a colheita. No tempo da colheita, eu direi aos encarregados: \"Primeiramente puxai as ervas daninhas e as amarrai em feixes para queimá-las, contudo, juntai o trigo no meu celeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Então Jesus apresentou-lhes outra parábola, dizendo: \"O Reino dos Céus é como uma semente de mostarda que um homem pegou e semeou em seu campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Essa semente é, de fato, a menor de todas as sementes. Mas, quando cresce, é maior que as plantas do jardim e torna-se uma árvore, de modo que os pássaros vêm e fazem ninho nos seus galhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Jesus então contou-lhes outra parábola: \"O Reino dos Céus é como fermento que uma mulher pegou e misturou com três medidas de farinha até a massa fermentar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Todas essas coisas Jesus disse às multidões em parábolas; e, sem parábolas, Ele não lhes disse nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Isso foi para que o que foi dito por meio do profeta se tornasse verdade, quando ele disse: \"Eu abrirei minha boca em parábolas; eu direi coisas que estavam escondidas desde a fundação do mundo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Então Jesus deixou as multidões e entrou em casa. Seus discípulos vieram a Ele e disseram: \"Explica para nós a parábola das ervas daninhas no campo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Jesus respondendo, disse-lhes: \"Aquele que semeia a boa semente é o Filho do Homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'O campo é o mundo; a boa semente são os filhos do reino e as ervas daninhas são os filhos do maligno,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'e o inimigo que os plantou é o maligno. A colheita é o fim do mundo, e os encarregados da colheita são os anjos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Portanto, como as ervas daninhas são recolhidas e queimadas no fogo, assim será no fim do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'O Filho do Homem enviará seus anjos e eles ajuntarão do seu reino todas as coisas que causam pecado, e aqueles que cometem iniquidade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'e os lançarão na fornalha de fogo, onde haverá lamento e rangido de dentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Então os justos brilharão como o sol, no reino de seu Pai. Aquele que tem ouvidos, ouça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'O Reino dos Céus é como um tesouro escondido em um campo que um homem achou e o escondeu. Em sua alegria, ele vai, vende tudo que possui e compra aquele campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Novamente, o Reino dos Céus é como um homem que é um mercador à procura de pérolas preciosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Quando ele encontrou uma pérola de grande valor, foi e vendeu tudo que possuía e a comprou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Novamente, o Reino dos Céus é como uma rede que foi lançada ao mar e capturou criaturas de todos os tipos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Quando estava cheia, os pescadores arrastaram-na para a praia. Então sentaram e juntaram as coisas boas em cestos, porém, as coisas sem valor jogaram fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Será desta maneira no fim do mundo: os anjos virão e separarão os maus dentre os justos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'e os lançarão na fornalha de fogo, onde haverá lamento e rangido de dentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Vós entendestes todas essas coisas? Os discípulos disseram a ele: \"Sim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Então Jesus disse-lhes: \"Portanto todo mestre da lei que torna-se discípulo do Reino dos Céus é como um homem que é o dono de uma casa, que retira coisas velhas e novas de seu tesouro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Aconteceu que, quando Jesus terminou essas parábolas, Ele deixou aquele lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Então Jesus entrou na sua própria região, e ensinou as pessoas nas suas sinagogas, e eles ficaram maravilhados e disseram: \"De onde este homem consegue Sua sabedoria e estes milagres?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Não é este homem o filho do carpinteiro? Não é Sua mãe Maria? E não são Tiago, José, Simão e Judas Seus irmãos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'E Suas irmãs não estão entre nós? Então, de onde este homem tira todas estas coisas?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Eles ofendidos por Jesus. Mas Ele lhes disse: \"Um profeta não é sem honra, exceto em seu próprio país e em sua própria família\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'E Ele não realizou muitos milagres lá por causa da descrença deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Naquele tempo, Herodes, o tetrarca, ouviu as notícias sobre Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Ele disse aos seus servos: \"Esse é João, o Batista; ele ressuscitou dos mortos, por isso esses poderes estão operando Nele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Pois Herodes o havia prendido, amarrado e colocado na prisão, por causa de Herodias, a esposa de seu irmão Filipe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'porque João havia lhe dito: \"Não é legítimo tê-la como tua esposa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Herodes teria mandado matá-lo, mas ele temeu o povo, porque eles o consideravam um profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Mas, quando o aniversário de Herodes chegou, a filha de Herodias dançou no meio dos convidados e agradou a Herodes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Em resposta, ele prometeu com um juramento que daria a ela qualquer coisa que ela pedisse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Após ser instruída por sua mãe, ela disse: \"Dá-me aqui, em um prato, a cabeça de João, o Batista\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'O rei ficou muito triste com o pedido dela, mas, por causa do seu juramento e por causa de todos os que estavam no jantar com ele, ordenou que isso deveria ser feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Ele enviou soldados, os quais decapitaram João na prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Então sua cabeça foi trazida em um prato e dada à menina e ela a levou para a sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Então seus discípulos vieram, pegaram o corpo e o enterraram. Após isso, eles foram e contaram a Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Quando Jesus ouviu o que havia acontecido, retirou-se de lá, em um barco, para um lugar isolado. Ao ouvir isso, as multidões O seguiram a pé, vindas das cidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Então Jesus desembarcou, viu a grande multidão, teve compaixão dela e curou seus doentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Quando o fim da tarde chegou, os discípulos vieram a Ele e disseram: \"Este é um lugar deserto e o dia já terminou. Despede as multidões, para que elas possam ir às vilas e comprar comida para si\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Mas Jesus disse-lhes: \"Eles não precisam ir embora, dai-lhes algo para comer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Eles Lhe disseram: \"Nós temos aqui apenas cinco pães e dois peixes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Jesus disse: \"Trazei-os para Mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Então Jesus ordenou que a multidão se sentasse na grama. Ele pegou os cinco pães e os dois peixes e, olhando para o céu, abençoou, partiu os pães, deu-os aos discípulos e os discípulos os deram à multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Todos comeram e ficaram satisfeitos. Então eles recolheram o que sobrou dos pedaços de comida: doze cestos cheios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Aqueles que comeram eram em torno de cinco mil homens, além de mulheres e crianças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Imediatamente Ele fez os discípulos entrarem no barco e irem adiante Dele para o outro lado, enquanto despedia a multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Depois que mandou a multidão embora, Ele subiu a montanha sozinho para orar. Quando escureceu, Ele estava lá sozinho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Mas o barco estava distante da terra e quase fora de controle por causa das ondas, pois o vento soprava contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Na quarta vigília da noite, Jesus aproximou-se deles, andando sobre o mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Quando os discípulos O viram andando sobre o mar, ficaram aterrorizados e disseram: \"É um fantasma!\" E eles gritaram de medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Mas Jesus falou-lhes imediatamente: \"Sede corajosos! Sou Eu! Não tenhais medo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Pedro respondeu-Lhe: \"Senhor, se és Tu, ordena a mim para que vá a Ti sobre a água\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Jesus disse: \"Vem!\" Assim Pedro saiu do barco e andou sobre as águas para ir até Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Mas, quando Pedro viu o vento, teve medo; e, começando a afundar, gritou: \"Senhor, salva-me!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Jesus imediatamente esticou a mão, agarrou Pedro e disse-lhe: \"Tu, que tens pequena fé, por que duvidaste?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Então, quando Jesus e Pedro entraram no barco, o vento parou de soprar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Os discípulos no barco adoraram a Jesus e disseram: \"Verdadeiramente Tu és o Filho de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Após completarem a travessia, chegaram a terra, em Genesaré.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Quando os homens naquele lugar reconheceram Jesus, enviaram mensagens para todos os lugares nos arredores e trouxeram a Ele todos os que estavam doentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'Eles Lhe imploraram que pudessem apenas tocar na borda do Seu manto, e todos os que tocaram foram curados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Então alguns Fariseus e escribas vieram de Jerusalém a Jesus e disseram:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '\"Por que os Teus discípulos violam a tradição dos anciãos? Pois eles não lavam suas mãos quando comem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Jesus respondeu e disse-lhes: \"E vós, por que violais o mandamento de Deus por causa das vossas tradições?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Pois Deus diz: \'Honra teu pai e tua mãe,\' e \'Aquele que maldisser seu pai ou sua mãe, certamente morrerá\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Mas vós dizeis: \'Aquele que disser a seu pai ou a sua mãe: \'Qualquer ajuda que poderíeis receber de mim é agora oferta para Deus\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'essa pessoa não terá de honrar seu pai\'. Dessa forma, vós anulais a palavra de Deus por causa das vossas tradições.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Hipócritas! Bem falou a profecia de Isaías sobre vós quando disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '\'Este povo honra-Me com os lábios, mas seu coração está longe de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Eles Me adoram em vão, porque ensinam mandamentos humanos\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Então Ele chamou a multidão para Si e disse-lhes: \"Ouvi e entendei:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'nada do que entra pela boca torna impura uma pessoa. Ao contrário, o que sai da boca, isso é o que torna impura uma pessoa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Então os discípulos vieram e disseram a Jesus: \"Sabes que os fariseus ficaram ofendidos quando ouviram a Tua declaração?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Jesus respondeu e disse: \"Toda planta que Meu Pai Celestial não plantou será arrancada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Deixai-os a sós; eles são guias cegos. Se um cego guia outro cego, ambos cairão no barranco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Pedro respondeu e disse a Jesus: \"Explica-nos essa parábola\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Jesus disse: \"Ainda estais sem entendimento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Não vedes que tudo o que entra pela boca passa pelo estômago e, por fim, é expelido?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Mas as coisas que saem da boca vêm do coração. Isso é o que torna uma pessoa impura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Pois do coração procedem maus pensamentos, assassinatos, adultérios, imoralidades sexuais, roubos, falsos testemunhos, e insultos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Essas são as coisas que tornam impura uma pessoa. Mas comer com as mãos sujas não torna impura uma pessoa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Então Jesus saiu dali e retirou-Se em direção às regiões das cidades de Tiro e Sidom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'E uma mulher Cananeia veio daquela região, gritando: \"Tem misericórdia de mim, Senhor, filho de Davi; minha filha está severamente atormentada por um demônio\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Mas Jesus não lhe respondeu qualquer palavra. Seus discípulos vieram e imploraram-Lhe, dizendo: \"Despede-a, pois ela está gritando atrás de nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Mas Jesus respondeu e disse: \"Eu não fui enviado senão às ovelhas perdidas da casa de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Porém ela veio e prostrou-se ante Ele, dizendo: \"Senhor, ajuda-me\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Ele respondeu e disse: \"Não é correto tirar o pão dos filhos e lançá-lo aos cachorrinhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Ela disse: \"Sim, Senhor, mas mesmo os cachorrinhos comem algumas migalhas que caem da mesa dos seus donos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Então Jesus respondeu e disse-lhe: \"Mulher, grande é a tua fé! Seja-te feito isso exatamente como desejas\". E sua filha ficou curada naquela hora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Jesus deixou aquele lugar e aproximou-Se do mar da Galiléia. Depois Ele subiu a um monte e sentou-Se lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Grandes multidões vieram a Ele; as pessoas traziam coxos, cegos, mudos e aleijados, e muitos outros que estavam doentes. Eles eram apresentados aos pés de Jesus, e Ele os curava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Então a multidão se maravilhava quando as pessoas viam os mudos falarem, os aleijados serem curados, os coxos andarem e os cegos verem. Eles todos louvaram ao Deus de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Jesus chamou a Si seus discípulos e disse: \"Eu tenho compaixão dessa multidão, porque eles continuam Comigo por três dias e nada têm para comer. Eu não quero mandá-los embora sem comer, temo que eles desfaleçam no caminho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Os discípulos disseram-Lhe: \"Onde conseguiremos pães suficientes que satisfaçam tão grande multidão, em um lugar tão deserto?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Jesus disse-Lhes: \"Quantos pães tendes?\" Eles disseram: \"Sete, e um peixinho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Então Jesus ordenou à multidão para sentar-se no chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Ele tomou os sete pães e o peixe, e, após dar graças, partiu os pães e os deu aos discípulos; e os discípulos distribuíram-nos à multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Todas as pessoas comeram e ficaram satisfeitas. E eles recolheram sete cestos cheios dos pedaços partidos que sobraram da comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Aqueles que comeram eram quatro mil homens, além das mulheres e crianças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Então Jesus despediu as multidões, entrou no barco e partiu para a região de Magadã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Os fariseus e saduceus vieram colocar Jesus à prova, pedindo que lhes mostrasse um sinal do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Mas Ele lhes respondeu: \"Quando a tarde vem, vós dizeis: \'Haverá bom tempo, pois o céu está avermelhado\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'E de manhã dizeis: \'O tempo hoje está ruim, as nuvens estão vermelhas e escuras\'. Sabeis interpretar o aspecto do céu, mas não sabeis interpretar os sinais dos tempos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Uma geração má e adúltera pede um sinal, mas nenhum sinal será dado senão o de Jonas.\" E Jesus, deixando-os, foi embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Os discípulos chegaram ao outro lado, mas eles esqueceram-se de levar pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Jesus disse-lhes: \"Prestai atenção e sede cuidadosos com o fermento dos fariseus e saduceus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Os discípulos discutiam entre si dizendo: \"É porque não trouxemos pão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'E Jesus percebendo isso disse: \"Homens de pequena fé, por que discutis entre vós e dizeis que é por não trazerdes pão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Vós ainda não percebeis e nem vos lembrais dos cinco pães para cinco mil homens e de quantos cestos recolhestes?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'E dos sete pães para quatro mil homens e de quantos cestos recolhestes?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Como não entendeis que não vos falei de pães? Prestai atenção e sede cuidadosos com o fermento dos fariseus e saduceus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Então eles entenderam que Ele não estava falando de serem cuidadosos com o fermento dos pães, mas de serem cuidadosos com os ensinamentos dos fariseus e saduceus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Quando Jesus veio para as regiões próximas de Cesareia de Filipe, perguntou a Seus discípulos: \"Quem o povo diz ser o Filho do Homem?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Eles disseram: \"Alguns dizem: \'João, o Batista\'; uns dizem: \'Elias\', outros dizem: \'Jeremias ou um dos profetas\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'E Ele perguntou-lhes: \"Mas vós dizeis que Eu sou quem?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Respondendo Simão Pedro, disse: \"Tu és o Cristo, o Filho do Deus vivo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'E Jesus lhe respondeu: \"És abençoado, Simão Barjonas, pois não foi carne e sangue que te revelaram isso, mas O Meu Pai que está no céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'E também Eu te digo que tu és Pedro, e sobre esta rocha edificarei a Minha igreja e as portas do inferno não prevalecerão contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Eu te darei as chaves do Reino do Céu. O que ligares na terra terá sido ligado nos céus e o que desligares na terra terá sido desligado no céu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Então Jesus ordenou aos discípulos que não contassem a ninguém que Ele era o Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'A partir daquele momento, Jesus começou a dizer aos Seus discípulos que Lhe era necessário ir para Jerusalém sofrer muitas coisas nas mãos dos anciãos, principais sacerdotes e escribas; ser morto e ressuscitar no terceiro dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Então Pedro chamou Jesus à parte e reprovou-O, dizendo: \"Longe de Ti, Senhor, isso nunca vai Te acontecer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Mas, Jesus voltando-se, disse: \"Sai para trás de Mim, Satanás, tu és para Mim pedra de tropeço, porque não cuidas das coisas de Deus, mas das coisas dos homens\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Então Jesus disse a Seus discípulos: \"Se alguém quiser Me seguir, negue-se a si mesmo, tome a sua cruz e siga-Me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Portanto quem quiser salvar a sua vida a perderá. E quem perder a sua vida por Minha causa a encontrará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Pois o que aproveitaria a uma pessoa ganhar o mundo inteiro e perder a sua vida? O que pode uma pessoa dar em troca da sua vida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Porque o Filho do Homem virá na glória do Seu Pai com os Seus anjos. Então Ele recompensará cada um de acordo com aquilo que tiver feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Verdadeiramente Eu vos digo que alguns de vós dos que aqui estão não experimentarão a morte até que vejam o Filho do Homem vindo no Seu Reino\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Seis dias depois, Jesus levou consigo Pedro, Tiago e seu irmão João, e em particular subiu com eles a um alto monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Ele foi transfigurado na frente deles; Seu rosto brilhava como o sol, e Suas vestes tornaram-se brilhantes como a luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Eis que lhes apareceram Moisés e Elias, falando com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Então, Pedro disse a Jesus: \"Senhor, é bom para nós estarmos aqui. Se desejas, farei aqui três tendas: Uma para o Senhor, uma para Moisés, e uma para Elias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Ele ainda estava falando quando uma nuvem os encobriu, e ouviu-se uma voz vinda da nuvem, dizendo: \"Este é Meu Filho amado, em Quem me agrado. A Ele ouvi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Quando os discípulos a ouviram, caíram com os seus rostos em terra e estavam com muito medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Então Jesus veio e tocou neles e disse-lhes: \"Levantai-vos e não tenhais medo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'E eles olharam e não viram ninguém, exceto Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Enquanto eles desciam o monte, Jesus ordenou-lhes, dizendo: \"Não conteis essa visão a ninguém, até que o Filho do Homem seja ressuscitado dentre os mortos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Seus discípulos perguntaram a Ele, dizendo: \"Por que os escribas dizem que Elias deve vir primeiro?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Jesus respondeu e disse: \"Elias de fato virá e restaurará todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Todavia Eu vos digo: \"Elias já veio, mas eles não o reconheceram; ao invés disso, fizeram o que quiseram com ele. Do mesmo modo, o Filho do Homem vai sofrer igualmente nas mãos deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Então os discípulos entenderam que Ele estava falando sobre João, o Batista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Quando eles chegaram junto à multidão, um homem veio, ajoelhou-se diante de Jesus, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, '\"Senhor, tenha misericórdia de meu filho, ele é epiléptico e sofre demais. Muitas vezes ele cai no fogo, e outras muitas ele cai na água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Eu o trouxe para os Teus discípulos, mas eles não puderam curá-lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Jesus respondendo disse: \"Geração perversa e descrente, até quando estarei convosco? Até quando vos aguentarei? Trazei o menino para mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Jesus repreendeu o demônio e este saiu do menino, que foi curado naquela hora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Então os discípulos vieram a Jesus em particular e disseram: \"Por que nós não pudemos expulsá-lo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Jesus disse a eles: \"É por causa da vossa pequena fé; pois de fato eu vos digo: se tiverdes fé como um pequeno grão de mostarda, podereis dizer para este monte: \'Move-te daqui para lá.\' E ele se moverá. Nada vos será impossível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, '');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Enquanto eles estavam na Galileia, Jesus disse aos seus discípulos: \"O Filho do Homem está para ser entregue nas mãos dos homens;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'eles vão matá-Lo mas, ao terceiro dia, Ele ressuscitará\". Os discípulos ficaram muito tristes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Quando eles chegaram a Cafarnaum, aproximaram-se de Pedro os cobradores do imposto das duas dracmas, e perguntaram: \"O Teu mestre não paga os impostos?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Ele respondeu: \"Sim, ele paga\". Mas quando Pedro entrou na casa, Jesus antecipou-se, dizendo: \"O que achas, Simão? De quem os reis da terra recebem taxa ou tributo? Dos seus filhos ou dos estrangeiros?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Quando Pedro disse: \"Dos estrangeiros,\" Jesus disse a ele: \"Então os seus filhos estão dispensados de pagar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Mas, para que não os escandalizemos, vai ao mar, lança o anzol, e o primeiro peixe que tu pescares, segura-o e abre-lhe a boca. Encontrarás aí uma moeda de prata. Pega-a e dá ao coletor de impostos por mim e por ti.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Naquele mesmo tempo, os discípulos vieram a Jesus e perguntaram: \"Quem é o maior no Reino dos Céus?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Jesus chamou para si uma criança, colocou-a entre eles');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'e disse: \"Verdadeiramente eu vos digo que, a menos que vos convertais e vos torneis como criança, de modo algum entrareis no Reino dos Céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Portanto aquele que se humilhar como esta criança é o maior no Reino dos Céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'E aquele que receber uma destas crianças em meu nome, a mim me recebe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Mas aquele que levar a pecar um destes pequeninos que acreditam em mim, melhor seria que uma grande pedra de moinho fosse pendurada em seu pescoço e fosse afundado até as profundezas do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Ai do mundo por causa dos que fazem tropeçar! É necessário que venham os tropeços, mas ai da pessoa pela qual vem o tropeço!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Se tua mão ou teu pé te faz tropeçar, corta-o e atira-o longe de ti. É melhor para ti entrares na vida manco ou aleijado, do que seres atirado no fogo eterno tendo as duas mãos ou os dois pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Se o teu olho te leva a tropeçar, arranca-o e atira-o longe de ti. É melhor para ti entrares na vida com um olho do que seres atirado no fogo eterno tendo os dois olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Vede que não desprezeis nenhum destes pequeninos. Pois Eu vos digo que os seus anjos nos céus vêem continuamente a face de meu Pai que está nos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, '');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'O que pensais? Se alguém tiver cem ovelhas, e uma dessas se extraviar, não deixa as noventa e nove sobre a colina, e parte seguindo aquela que se extraviou?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Verdadeiramente vos digo que, se ele a encontra, alegra-se mais por esta do que pelas noventa e nove que não se desviaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Do mesmo modo, não é o desejo de vosso Pai celeste que pereça um destes pequeninos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Se teu irmão pecar, vai, dize-lhe sobre sua falta, entre ti e ele somente. Se ele te ouvir, terás ganhado o teu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Mas, se ele não te ouvir, traz contigo mais uma ou duas pessoas e, então, pela boca de duas ou três testemunhas toda palavra será confirmada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Porém, se ele se recusar a ouvi-lo, dize-o à igreja. Se ele também se recusar a ouvir a igreja, considera-o como um gentio e coletor de impostos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Verdadeiramente eu vos digo: tudo que ligardes na terra será ligado no céu; e tudo que desligardes na terra será desligado no céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Além disso, eu vos digo que, se dois concordarem na terra sobre qualquer coisa que pedirem, isso será feito em favor deles por meu Pai, que está nos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Pois onde há dois ou três reunidos em meu nome, ali estou no meio deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Então Pedro veio e disse a Jesus: \"Senhor, quantas vezes meu irmão pecará contra mim e eu lhe perdoarei? Até sete vezes?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jesus respondeu: \"Não apenas sete vezes, mas até setenta vezes sete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Portanto o reino dos céus é similar a certo rei que queria acertar as contas com seus servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Assim que ele começou o acerto, foi-lhe trazido um servo que devia dez mil talentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Mas, uma vez que ele não tinha os meios para pagar, seu senhor ordenou que ele fosse vendido juntamente com a esposa e os filhos e tudo o que ele tinha, e o pagamento fosse feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Então o servo caiu prostrado diante dele e disse: \'Senhor, tem paciência comigo, e eu te pagarei tudo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Então o senhor daquele servo, movido de compaixão, livrou-o e perdoou-lhe a dívida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Mas aquele servo saiu e encontrou um de seus conservos que lhe devia cem denários. Ele agarrou-o, pegou-o pela garganta, e disse: \'Paga-me o que me deves\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Mas seu conservo caiu e implorou-lhe, dizendo: \'Tem paciência comigo, e eu te pagarei\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Mas o primeiro servo se recusou a perdoar-lhe. Em vez disso, ele atirou-o na prisão, até que lhe pagasse tudo o que devia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Quando seus conservos viram tudo o que tinha acontecido, ficaram muito desapontados, foram e contaram ao seu senhor tudo o que tinha acontecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Então o senhor daquele servo o chamou e disse-lhe: \'Servo mau, perdoei-te toda aquela dívida porque me imploraste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Não devias tu ter tido misericórdia do teu conservo, assim como eu tive misericórdia de ti?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Seu senhor enfureceu-se e entregou-o aos torturadores até que ele pagasse tudo aquilo que era devido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Assim também meu Pai celeste vos fará, se cada um de vós não perdoar, de coração, ao seu irmão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Aconteceu que, quando Jesus terminou essas palavras, partiu da Galileia e foi para a região da Judeia, além do rio Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Grandes multidões O seguiram, e Ele as curou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Fariseus vieram a Ele e, colocando-O à prova, disseram: \"É legítimo a um homem repudiar sua esposa por qualquer motivo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Jesus respondeu dizendo: \"Não lestes que Aquele que os fez desde o princípio os fez homem e mulher?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'E que Ele também disse: \'Por essa razão, o homem deixará seu pai e sua mãe e se unirá a sua mulher, e os dois se tornarão uma só carne?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Logo eles não são mais dois, mas uma só carne. Portanto, o que Deus uniu, ninguém separe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Eles Lhe disseram: \"Por que, então, Moisés nos mandou dar uma certidão de divórcio e repudiar?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Ele disse-lhes: \"Por causa da dureza do vosso coração, Moisés vos permitiu repudiar vossas esposas, mas, no princípio, não era dessa forma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Eu vos digo que todo aquele que repudiar sua esposa, exceto por imoralidade, e casar-se com outra, comete adultério;.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Os discípulos disseram a Jesus: \"Se esse é o caso de um homem em relação a sua esposa, não é bom casar-se\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Mas Jesus disse-lhes: \"Nem todos podem aceitar esse ensinamento, mas somente aqueles a quem é permitido aceitá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Pois há eunucos que são nascidos assim do útero de suas mães. E há eunucos que são feitos eunucos pelos homens. E há eunucos que fizeram a si mesmos eunucos por causa do Reino dos Céus. Aquele que está apto para receber esse ensino receba-o\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Então foram trazidas algumas crianças para que Ele estendesse as mãos sobre elas e orasse, mas os discípulos repreenderam-lhes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Todavia Jesus disse: \"Deixai as crianças, e não as proibais de vir a Mim, pois delas é o Reino dos Céus.\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Ele colocou as mãos sobre elas, e então partiu dali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Eis que um homem veio a Jesus e disse: \"Mestre, o que posso fazer de bom para ter a vida eterna?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Jesus disse-lhe: \"Por que Me perguntas sobre o que é bom? Só um é bom, mas se queres entrar na vida, cumpra os mandamentos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'O homem perguntou-Lhe: \"Quais mandamentos?\" Jesus respondeu: \"Não matarás, não cometerás adultério, não roubarás, não dirás falso testemunho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'honra teu pai e tua mãe, e amarás o teu próximo como a ti mesmo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'O jovem disse-Lhe: \"A todas essas coisas tenho obedecido; o que eu preciso fazer ainda?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jesus respondeu-lhe: \"Se desejas ser perfeito, vai, vende o que tens, e dá aos pobres, e terás um tesouro no céu; então vem e segue-Me.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Mas, quando o jovem ouviu o que Jesus falou, foi embora triste, pois tinha muitas propriedades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Jesus disse aos seus discípulos: \"Verdadeiramente Eu vos digo que é difícil para um homem rico entrar no Reino dos Céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Novamente eu vos digo: É mais fácil para um camelo passar através do buraco da agulha, do que para um homem rico entrar no Reino de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Quando os discípulos ouviram isso, ficaram muito maravilhados e disseram: \"Quem então pode ser salvo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Jesus olhou-os e disse: \"Para o ser humano isso é impossível, mas para Deus todas as coisas são possíveis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Então Pedro respondeu e disse-Lhe: \"Vê, nós deixamos tudo e Te seguimos; o que então receberemos?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Jesus disse-lhes: \"Verdadeiramente Eu vos digo que, na regeneração, quando o Filho do Homem sentar-se no Seu glorioso trono, vós que tendes Me seguido também sentareis sobre doze tronos para julgar as doze tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Todo aquele que deixou casas, irmãos, irmãs, pai, mãe, filhos, ou propriedades, por causa do Meu nome, receberá cem vezes mais e herdará a vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Porém muitos dos primeiros serão últimos; e muitos dos últimos serão primeiros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Pois o Reino dos Céus é como o dono de uma propriedade que saiu cedo, pela manhã, para contratar trabalhadores para a sua vinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Após ter combinado com os trabalhadores um denário por dia, ele os enviou para a sua vinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Ele saiu novamente por volta da terceira hora e viu outros trabalhadores ociosos na praça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'E disse-lhes: \'Ide também vós a minha vinha, e eu vos darei o que for justo\'. Então eles foram trabalhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Outra vez, ele saiu por volta da sexta hora e, de novo, na nona hora, e fez o mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Uma vez mais, por volta da décima primeira hora, ele saiu e encontrou outros que estavam ociosos. E perguntou-lhes: \'Por que estais aqui ociosos todo o dia?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Eles lhe responderam: \'Porque ninguém quis nos contratar\'. Ele lhes disse: \'Ide também para a minha vinha\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Quando a tarde chegou, o dono da vinha disse ao administrador: \'Chama os trabalhadores e paga-lhes o salário, começando do último até o primeiro\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Quando os trabalhadores que foram contratados na décima primeira hora chegaram, cada um deles recebeu um denário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Quando os primeiros trabalhadores chegaram, eles pensaram que poderiam receber mais, contudo cada um deles também recebeu um denário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Quando eles receberam seus pagamentos, queixaram-se do dono da propriedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Eles disseram: \'Estes últimos trabalharam somente uma hora, mas tu os fizeste igual a nós, que suportamos o fadiga do dia e do intenso calor\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Mas o dono respondeu a um deles, dizendo: \'Amigo, eu não te faço injustiça, não combinaste comigo por um denário?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Recebe o que te pertence e vai embora; eu decidi dar a esses trabalhadores contratados por último exatamente o mesmo que a ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Não é meu direito fazer o que eu quiser com as minhas posses? Ou são teus olhos maus porque eu sou generoso?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Assim os últimos serão os primeiros, e os primeiros os últimos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Quando Jesus estava subindo para Jerusalém, chamou à parte os doze discípulos e, no caminho, disse-lhes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '\"Vede: Nós estamos subindo para Jerusalém, e o Filho do Homem será entregue aos principais sacerdotes e escribas. Eles O condenarão à morte');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'e O entregarão aos gentios para que zombem Dele, O açoitem e O crucifiquem. Mas no terceiro dia Ele ressuscitará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Então a mãe dos filhos de Zebedeu veio a Jesus com seus filhos. Ela se prostrou diante Dele e fez-Lhe um pedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Jesus perguntou-lhe: \"O que queres?\" Ela respondeu: \"Ordena que, no Teu reino, esses meus dois filhos possam sentar, um a Tua direita e outro a Tua esquerda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Mas Jesus respondeu e disse: \"Não sabeis o que estais pedindo. Vós sois capazes de beber o cálice que Eu estou prestes a beber?\" Eles responderam: \"Somos capazes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Ele lhes disse: \"Meu cálice de fato vós bebereis. Mas sentar-se a minha direita e sentar-se a minha esquerda não cabe a Mim conceder, mas isso é para aqueles que foram preparados por Meu Pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Quando os outros dez discípulos ouviram isso, eles ficaram indignados com os dois irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Mas Jesus chamou-os para Si e disse-lhes: \"Sabeis que os governantes dos gentios os subjulgam, e os homens mais importantes exercem autoridade sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Mas não deve ser dessa forma entre vós. Ao contrário, qualquer que deseja se tornar grande entre vós deve ser o vosso servo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'e qualquer que deseja ser o primeiro entre vós deve ser o vosso servo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'assim como o Filho do Homem não veio para ser servido, mas para servir, e para dar sua vida como resgate de muitos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Quando eles saíram de Jericó, uma grande multidão O seguiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'E eis que dois homens cegos estavam sentados à beira da estrada; quando eles ouviram que Jesus estava passando perto, gritaram dizendo: \"Senhor, Filho de Davi, tem misericórdia de nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Mas a multidão os repreendeu, dizendo-lhes que ficassem quietos. Contudo eles clamavam mais alto e diziam: \"Senhor, Filho de Davi, tem misericórdia nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Então Jesus parou, chamou-os e disse: \"O que querem que Eu vos faça?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Eles Lhe disseram: \"Senhor, que nossos olhos sejam abertos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Então Jesus, sendo movido de compaixão, tocou nos olhos deles. Imediatamente eles receberam a visão e o seguiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Quando Jesus e Seus discípulos se aproximavam de Jerusalém e chegaram a Betfagé, ao Monte das Oliveiras. Dali Jesus enviou dois discípulos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'dizendo-lhes: \"Entrai na próxima vila e imediatamente encontrareis lá uma jumenta amarrada e um jumentinho com ela. Desamarrai-os e trazei-os para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Se alguém vos disser qualquer coisa sobre isso, dizei: \'O Senhor precisa deles e imediatamente vos devolverá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Isso aconteceu para que se cumprisse o que foi dito pelo profeta, que disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '\"Dizei à filha de Sião: \'Vê, Teu Rei está vindo a ti, humilde e montado em um jumento, em um jumentinho, cria de um animal de carga\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Então os discípulos foram e fizeram como Jesus os havia instruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Eles trouxeram o jumento e o jumentinho, e colocaram seus trajes nos animais e Jesus montou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'A maioria da multidão espalhou suas vestimentas no caminho, e outros cortaram ramos das árvores e os espalhavam pelo caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'As multidões que passaram à frente de Jesus e aqueles que O seguiam, gritavam, dizendo: \"Hosana ao filho de Davi! Bendito é o que vem em nome do Senhor! Hosana nas alturas!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Quando Jesus entrou em Jerusalém, toda a cidade estava agitada, dizendo: \"Quem é este?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'As multidões responderam: \"Este é Jesus, o profeta de Nazaré da Galileia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Então Jesus entrou no templo e expulsou todos aqueles que ali compravam e vendiam. Também derrubou a mesa de dinheiro dos cambistas e os assentos daqueles que vendiam pombos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'Ele lhes disse: \"Está escrito: \'Minha casa será chamada casa de oração,\' mas vós fazeis dela um covil de ladrões\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'E os cegos e os aleijados vieram a Ele no Templo, e Ele os curou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Mas, quando os principais sacerdotes e os escribas viram os milagres que Ele fez e quando eles ouviram as crianças gritando no templo e dizendo: \"Hosana ao filho de Davi\", eles ficaram furiosos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'e disseram a Ele: \"Tu estás ouvindo o que estas pessoas estão dizendo?\" Jesus respondeu-lhes: \"Sim! Mas vós nunca lestes: \'Da boca dos pequeninos e das crianças que mamam sai o perfeito louvor\'\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Então Jesus deixou-os e saiu da cidade para Betânia e passou a noite lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Pela manhã, quando Ele retornou para a cidade, estava com fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Viu uma figueira na margem da estrada; foi até ela, mas não encontrou nada nela, exceto folhas. Ele disse à árvore: \"Jamais volte a nascer fruto de ti\". E imediatamente a figueira secou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Quando os discípulos viram isso, maravilharam-se e disseram: \"Por que a figueira secou imediatamente?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jesus respondeu e disse-lhes: \"Verdadeiramente eu vos digo: Se tiverdes fé e não duvidardes, não só fareis o que foi feito a esta figueira, mas dirão a este monte: \'Arranca-te e lança-te dentro do mar\', e isso será feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Todas as coisas que pedirdes em oração, acreditando, recebereis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Quando Jesus entrou no Templo, os principais sacerdotes e os anciãos do povo vieram a Ele, enquanto estava ensinando, e disseram: \"Com que autoridade fazes estas coisas? E quem Te deu esta autoridade?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jesus respondeu e disse-lhes: \"Eu também vos farei uma pergunta. Se me responderdes, da mesma forma Eu vos direi com que autoridade faço estas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'De onde veio o batismo de João? Do céu ou dos homens?\" Eles discutiram entre eles mesmos, dizendo: \"Se nós dissermos: \'Do céu\', Ele nos dirá: \'Por que então não acreditastes nele?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Mas, se dissermos: \'Dos homens\', nós tememos a multidão, porque todos eles veem João como um profeta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Então eles responderam a Jesus e disseram: \"Nós não sabemos\". Ele também disse a eles: \"Nem Eu vos direi com que autoridade Eu faço estas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Todavia o que pensais? Um homem tinha dois filhos. Ele foi ao primeiro e disse: \'Filho, vai trabalhar hoje na vinha\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'O filho respondeu e disse: \'Eu não irei\'. Mas depois ele mudou sua opinião e foi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'E o homem foi ao segundo filho e disse a mesma coisa. Esse filho respondeu e disse: \'Eu irei, senhor\', contudo ele não foi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Qual dos dois filhos fez a vontade de seu pai?\" Eles disseram: \"O primeiro\". Jesus disse a eles: \"Verdadeiramente Eu vos digo: Os coletores de impostos e as prostitutas entrarão no Reino de Deus antes de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Pois João veio a vós no caminho de justiça, mas vós não acreditastes nele; enquanto os coletores de impostos e as prostitutas acreditaram. Vós, porém, mesmo vendo isso, não vos arrependestes e não crestes nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, '\"Ouvi outra parábola: Havia um homem, um proprietário de terra que plantou uma vinha, colocou cerca nos arredores, fez um lagar para pisotear uvas, construiu uma torre de vigia e arrendou a propriedade para lavradores de vinha. Depois ele foi para outro país.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Quando chegou o tempo da colheita da uva, ele enviou alguns servos aos responsáveis pela vinha para receber suas uvas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Mas os lavradores da vinha pegaram os servos do proprietário, espancaram um, mataram outro, e apedrejaram o outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Mais uma vez, o proprietário enviou outros servos, mais que da primeira vez. Todavia os lavradores da vinha os trataram da mesma maneira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Depois disso, o proprietário enviou-lhes seu próprio filho, dizendo: \'Eles respeitarão meu filho\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Mas, quando os lavradores da vinha viram o filho, disseram entre eles: \"Este é o herdeiro. Vinde, vamos matá-lo e tomar a herança\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Então eles o pegaram, lançaram-no para fora da vinha, e o mataram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Agora, quando o proprietário da vinha retornar, o que fará àqueles lavradores da vinha?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'As pessoas disseram a ele: \"Ele destruirá aqueles homens miseráveis da forma mais severa e arrendará a vinha a outros lavradores, que lhe entregarão sua parte no tempo da colheita\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jesus disse-lhes: \"Vós nunca lestes nas Escrituras: \'A pedra que os construtores rejeitaram tornou-se a pedra angular. Isso veio do Senhor e é maravilhoso aos nossos olhos\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Portanto Eu vos digo: O Reino de Deus será tirado de vós e será dado a uma nação que produza frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'E quem quer que caia sobre esta pedra será quebrado em pedaços. Mas sobre aquele sobre o qual ela cair, esse será esmagado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Quando os principais sacerdotes e os fariseus ouviram Suas parábolas, entenderam que Ele estava falando sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Buscando prendê-Lo, temiam a multidão porque as pessoas consideravam-No um profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'E respondeu-lhe Jesus novamente em parábolas, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '\"O Reino dos Céus é semelhante a um rei que fez uma festa de casamento para seu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Ele enviou seus servos para chamar aqueles que haviam sido convidados para a festa de casamento, mas eles não quiseram vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Novamente, o rei enviou outros servos, dizendo: \"Dizei àqueles que são convidados: \'Vede, eu preparei um jantar; meus bois e animais cevados foram mortos, e tudo está pronto. Vinde para a festa de casamento\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Mas eles não deram atenção e partiram: um para o seu campo, outro para os seus negócios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'E os outros agarraram os servos do rei, trataram-nos vergonhosamente e os mataram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'O rei ficou furioso e, tendo enviado seus soldados, mataram aqueles assassinos e incendiaram a cidade deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Então disse aos seus servos: \'A festa de casamento está pronta, mas aqueles que foram convidados não eram dignos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Portanto ide pelas encruzilhadas dos caminhos e a quantos encontrardes convidai-os para a festa de casamento \'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Os servos saíram pelos caminhos e reuniram todos os que encontraram, tanto maus como bons. Então, o salão ficou cheio de convidados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Mas, quando o rei entrou para ver os convidados, viu um homem que não estava com trajes de casamento');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'e disse-lhe: “Amigo, como entraste aqui sem trajes de casamento?” E o homem se calou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Então o rei disse aos servos: \'Amarrai as mãos e os pés desse homem e atirai-o nas trevas exteriores, onde haverá choro e ranger de dentes\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Porque muitos são chamados, porém poucos são escolhidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Então os fariseus foram e planejaram como poderiam pegar Jesus em sua própria fala.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'E enviaram-lhe os seus discípulos junto com os herodianos. Eles disseram a Jesus: \'Mestre, nós sabemos que és verdadeiro e ensinas o caminho de Deus em verdade e não te importas com a opinião de ninguém e não faz diferença entre as pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Então diga-nos o que achas? É lícito pagar impostos a César ou não?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Tendo percebido a maldade deles, Jesus lhes disse: \"Por que estão me testando, seus hipócritas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Mostrai-me a moeda do imposto\". Então trouxeram-Lhe um denário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Jesus disse-lhes: \"De quem é esta imagem e este nome?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Eles lhe disseram: \"De César\". Então disse-lhes Jesus: \"Dai a César o que é de César, e a Deus o que é de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Quando ouviram isso, maravilharam-se, deixaram-No e foram embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Naquele dia, foram ter com Ele saduceus, dizendo não haver ressurreição, e interrogaram-No,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'dizendo: \"Mestre, Moisés disse: \'Se um homem morre, não tendo filhos, seu irmão deve casar-se com a esposa dele e ter um filho para seu irmão\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Havia sete irmãos. O primeiro casou-se e então morreu. Não tendo filhos, deixou sua esposa para seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Da mesma forma, o segundo, o terceiro e até o sétimo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Depois de todos eles, a mulher morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Agora na ressurreição, de qual dos sete irmãos ela será esposa? Pois todos a tiveram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jesus, porém, lhes respondeu: “Vós estais errados, porque não conheceis as Escrituras nem o poder de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Pois na ressurreição eles não se casam e nem se dão em casamento. Em vez disso, são como anjos no céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Mas, a respeito da ressurreição dos mortos, não lestes o que foi dito por Deus:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '\'Eu sou o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó?\' Deus não é o Deus dos mortos, mas dos vivos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Quando as multidões ouviram isso, se maravilharam com o Seu ensino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Mas, quando os fariseus ouviram que Jesus tinha calado os saduceus, eles se reuniram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Um deles, um doutor da Lei, questionou-O, testando-O:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '\"Mestre, qual é o maior mandamento da Lei?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Jesus lhes disse: \"\'Ame ao Senhor teu Deus com todo o teu coração, com toda a tua alma e com toda a tua mente\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Esse é o maior e primeiro mandamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'E o segundo mandamento é semelhante a esse: \'Amarás o teu próximo como a ti mesmo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'Desses dois mandamentos depende toda a Lei e os profetas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Enquanto os fariseus ainda estavam reunidos, Jesus lhes perguntou, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, '\"O que pensais sobre o Cristo? De quem ele é filho?\" Eles lhe disseram: \"O filho de Davi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Disse-lhes Jesus: \"Como então Davi, no Espírito, o chama Senhor, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '\"O Senhor disse ao meu Senhor: \'Assenta-te à minha direita, até que eu ponha os teus inimigos por debaixo de teus pés?\'\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Se Davi, pois, chama a Cristo \"Senhor\", como é que Ele é filho de Davi?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Ninguém podia responder-Lhe uma palavra sequer, e nenhum homem se atrevia questioná-Lo daquele dia em diante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Então Jesus falou à multidão e aos seus discípulos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'dizendo: \"Os escribas e fariseus se assentam na cadeira de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Portanto o que quer que eles vos ordenem, fazei e guardai. Mas não imiteis seus atos, pois eles falam, mas não os praticam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Sim, eles atam fardos pesados que são difíceis de carregar, e os colocam nos ombros dos homens. Mas eles mesmos não moverão um dedo para carregá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Eles fazem todos os seus atos para serem vistos pelos homens, pois aumentam os seus filactérios e alargam as franjas das vestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'Eles amam os primeiros lugares nos banquetes e as primeiras cadeiras nas sinagogas');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'e as saudações especiais nas praças e serem chamados \'Mestres\' pelo povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Mas não deveis ser chamados \'Rabi\', pois para vós há um só Mestre, e todos vós sois irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'E não chamai nenhum homem na terra de vosso pai, pois para vós há um só Pai, e Ele está nos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Nem sejais chamados \'mestres\', pois para vós há um só Mestre, o Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Mas aquele que é maior entre vós será vosso servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Quem se exaltar será humilhado, e quem se humilhar será exaltado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Mas ai de vós, escribas e fariseus, hipócritas! Vós que fechais o Reino dos Céus aos homens. Pois não entrais e nem deixais entrar os que entrariam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, '');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Ai de vós, escribas e fariseus, hipócritas! Pois rodeais o mar e a terra para fazer um prosélito. E quando ele tiver se tornado um, o fizestes duas vezes mais filho do inferno do que vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Ai de vós, guias cegos, que dizeis: \'Quem jurar pelo santuário, nada vale, mas quem jurar pelo ouro do santuário, está obrigado para com o seu juramento\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Cegos tolos! Qual é maior, o ouro ou o santuário que santifica o ouro?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'E \'Quem jurar pelo altar, nada vale. Mas quem jurar pela oferta que está sobre ele, está obrigado para com o seu juramento\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Cegos! Qual é maior, a oferta ou o altar que consagra a oferta?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Portanto quem jura pelo altar, jura por ele e por todas as coisas sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'E quem jura pelo santuário, jura por ele e por quem habita nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'E quem jura pelo céu, jura pelo trono de Deus e por quem se assenta nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Ai de vós, escribas e fariseus, hipócritas! Pois dais o dízimo da hortelã, do endro e do cominho, mas deixais os preceitos mais importantes da Lei: justiça, misericórdia e fé. Mas deveis fazer essas coisas sem omitir aquelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Guias cegos, que filtrais um mosquito, mas engolis um camelo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Ai de vós, escribas e fariseus, hipócritas! Pois limpais fora do copo e do prato, mas por dentro estão cheios de rapina e intemperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Fariseus cegos! Limpai primeiro dentro do copo e do prato, para que o exterior também fique limpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Ai de vós, escribas e fariseus, hipócritas! Pois sois como sepulcros caiados, que por fora parecem bonitos, mas por dentro estão cheios de ossos de mortos e de imundícia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Da mesma maneira, exteriormente também pareceis justos aos homens, mas por dentro estais cheios de hipocrisia e de iniquidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Ai de vós, escribas e fariseus, hipócritas! Porque edificais os sepulcros dos profetas e ornamentais os túmulos dos justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'Vós dizeis: “Se tivéssemos vivido nos dias dos nossos pais, não teríamos sido participantes com eles no derramamento do sangue dos profetas”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Portanto, testificais contra vós mesmos que sois filhos dos que mataram os profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Completai também a medida de vossos pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Serpentes, raça de víboras, como escapareis do juízo do inferno?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Portanto vede, eu vos envio profetas, sábios e escribas. Alguns deles matareis e crucificareis, e alguns açoitareis nas vossas sinagogas e perseguireis de cidade em cidade;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'para que recaia sobre vós todo sangue dos justos lançado na terra, desde o de Abel, o justo, até o de Zacarias, filho de Baraquias, a quem matastes entre o santuário e o altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Verdadeiramente eu vos digo: \"Todas essas coisas virão sobre esta geração\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jerusalém, Jerusalém, que matas os profetas e apedrejas os que te são enviados! Quantas vezes eu tentei ajuntar os vossos filhos, como a galinha ajunta seus pintinhos debaixo das suas asas, mas não quisestes!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Vede, a vossa casa vos será deixada deserta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Eu vos digo, não me vereis de agora em diante até que direis: \'Bendito o que vem em nome do Senhor\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Jesus saiu do templo e, enquanto caminhava, Seus discípulos vieram até Ele para mostrar-Lhe as construções do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Mas Ele lhes respondeu, dizendo: “Não vedes todas estas coisas? Verdadeiramente Eu vos digo: nenhuma pedra ficará sobre outra pedra que não seja derrubada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Estando Jesus assentado no Monte das Oliveiras, os discípulos vieram até Ele em particular e disseram: \"Dize-nos, quando estas coisas acontecerão? Qual será o sinal da Tua vinda e do fim desta época?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Jesus respondeu e disse-lhes: “Cuidado para que ninguém vos engane.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Pois muitos virão em Meu nome, dizendo: \'eu sou o Cristo\', e enganarão a muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Ouvireis falar de guerras e de rumores de guerras; vede, não vos assusteis, pois é necessário que estas coisas aconteçam; mas ainda não é o fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Pois nação se levantará contra nação, e reino contra reino. Haverá fomes e terremotos em vários lugares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Mas estas coisas são apenas o início das dores de parto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Então vos entregarão às tribulações e vos matarão, e sereis odiados por todas as nações por causa do Meu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'E muitos serão atribulados, e trairão uns aos outros, e odiarão uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Muitos falsos profetas se levantarão e enganarão a muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Por se multiplicar a iniquidade, o amor de muitos se esfriará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Mas aquele que perseverar até o fim, será salvo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Este evangelho do reino será pregado em todo o mundo como testemunho para todas as nações; e então virá o fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Portanto, quando virdes a abominação da desolação que foi falada por Daniel, o profeta, estando no lugar sagrado (que o leitor entenda),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'aqueles que estiverem na Judéia fujam para os montes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'aquele que estiver no terraço não desça para pegar nada que esteja em sua casa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'e aquele que estiver no campo não retorne para pegar sua capa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Mas ai daquelas que estiverem grávidas e que estiverem amamentando naqueles dias!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Orai para que a vossa fuga não ocorra no inverno, ou no Sábado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Pois haverá grande tribulação, tal que nunca existiu desde o início do mundo até agora, e nem haverá jamais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Se aqueles dias não tivessem sido abreviados, ninguém seria salvo; mas, por causa dos eleitos, aqueles dias serão abreviados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Logo, se qualquer pessoa vos disser: \'Eis aqui o Cristo!\' ou, \'Lá está o Cristo!\' Não acrediteis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Pois falsos Cristos e falsos profetas virão e apresentarão grandes sinais e maravilhas para enganar, se possível até os eleitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Eis que vos tenho predito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Entretanto, se vos disserem, \'Eis que Ele está no deserto\', não saiais; ou, \'Ei-Lo no interior da casa\', não acrediteis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Pois assim como o relâmpago sai do oriente e brilha até o ocidente, assim será a vinda do Filho do Homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Onde estiver o cadáver, ali os abutres se ajuntarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'E logo após a tribulação daqueles dias, o sol escurecerá, a lua não nos dará a sua luz, as estrelas cairão do céu, e os poderes dos céus serão abalados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Então o sinal do Filho do Homem aparecerá no céu, e todas as tribos da terra se lamentarão e verão o Filho do Homem vindo sobre as nuvens do céu, com poder e grande glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Ele enviará os Seus anjos com grande som de trombeta, e eles reunirão os Seus eleitos dos quatro ventos da terra, de uma a outra extremidade dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Aprendei a parábola da figueira: Assim quando os ramos se renovam e brotam suas folhas, sabeis que o verão está próximo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'assim também, quando virdes todas estas coisas, deveis saber que Ele está próximo, às portas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Verdadeiramente Eu vos digo que esta geração não passará, sem que todas estas coisas tenham acontecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'O céu e a terra passarão, mas as Minhas palavras nunca passarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Mas, a respeito daquele dia e hora, ninguém sabe, nem os anjos do céu, nem o Filho, mas somente o Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Assim como foi nos dias de Noé, também será na vinda do Filho do Homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Pois naqueles dias antes do dilúvio, eles estavam comendo e bebendo, casando e dando-se em casamento, até o dia em que Noé entrou na arca;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'e não se deram conta, até que o dilúvio veio e levou a todos - assim será a vinda do Filho do Homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Então dois homens estarão num campo; um será levado, e o outro será deixado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Duas mulheres estarão moendo no moinho; uma será tomada, e a outra deixada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Portanto vigiai, pois não sabeis em que dia vem o vosso Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Mas sabei isto: se o dono da casa soubesse a que hora o ladrão viria, ele estaria vigilante e não permitiria que sua casa fosse arrombada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Portanto, também vós deveis estar preparados, pois o Filho do Homem virá naquela hora em que não esperais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Assim, quem é o servo fiel e sábio, que seu senhor o deixou responsável por seus criados, com o fim de dar-lhes o alimento no tempo certo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Abençoado é aquele servo a quem seu senhor encontrá-lo fazendo isso quando ele vier.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Verdadeiramente Eu vos digo: o seu senhor o colocará sobre tudo o que ele possui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Mas se o servo mau disser em seu coração: \'Meu senhor está demorando\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'e começar a bater nos seus conservos, e a comer e beber com os bêbados;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'então o senhor daquele servo virá no dia em que ele não espera, e em uma hora que não sabe,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'e o cortará em pedaços e lhe dará o mesmo destino dos hipócritas; ali haverá choro e ranger de dentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Então o Reino dos Céus será semelhante a dez virgens que tomaram suas lâmpadas e saíram ao encontro do noivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Cinco delas eram tolas e cinco eram sábias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'E quando as tolas pegaram suas lâmpadas, elas não levaram azeite consigo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'mas as sábias trouxeram vasilhas de azeite juntamente com suas lâmpadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'E demorando o noivo, todas elas ficaram com sono e dormiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Mas à meia-noite, ouviu-se um grito: \'Eis o noivo! Saí ao seu encontro.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Então todas as virgens se levantaram e ajuntaram suas lâmpadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'As tolas disseram às sábias: \'Dai-nos um pouco do vosso azeite porque nossas lâmpadas estão se apagando.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Mas as sábias responderam, dizendo: \'De modo algum, não haverá suficiente para nós e vós, ide aos que vendem azeite e comprai para vós.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Enquanto elas foram comprar, o noivo chegou, e as que estavam prontas foram com ele para a festa de casamento e a porta foi fechada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Após isso as outras virgens também chegaram e disseram: \'Senhor, senhor, abre-nos a porta\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Mas ele respondeu e disse: \'Verdadeiramente vos digo que não vos conheço.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Portanto vigiai, porque não sabeis o dia nem a hora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Pois será como um homem que quando estava prestes a ir para outro país, chamou seus servos e os colocou no controle dos seus bens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'A um deles deu cinco talentos, a outro deu dois, e ainda a outro ele deu um talento - cada um de acordo com sua própria habilidade, e partiu em viagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Imediatamente, o que recebeu cinco talentos foi negocia-los e fez outros cinco talentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Da mesma maneira, o que recebeu dois talentos fez outros dois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Mas o servo que recebeu um talento foi embora, cavou um buraco no chão e escondeu o dinheiro do seu senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'E após um longo tempo, o senhor daqueles servos voltou e acertou as contas com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'O servo que recebeu cinco talentos veio e trouxe outros cinco; ele disse: \'Senhor, tu me deste cinco talentos. Eis aqui mais cinco talentos.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Seu senhor disse-lhe: \'Muito bem, servo bom e fiel! Foste fiel sobre poucas coisas; sobre muitas te colocarei. Entra na alegria do teu senhor\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'E aproximando-se o servo que recebeu dois talentos disse: \'Senhor, tu me deste dois talentos. Eis aqui mais dois talentos.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Seu senhor disse-lhe: \'Muito bem, servo bom e fiel! Foste fiel sobre poucas coisas; sobre muitas te colocarei. Entra na alegria do teu senhor\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Então o servo que recebeu um talento disse: \'Senhor, eu sei que és rigoroso; colhes onde não semeaste; e ajuntas onde não espalhaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Eu tive medo, então fui e escondi na terra o teu talento. Aqui tens o que é teu\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Mas o seu senhor lhe respondeu, dizendo: “Servo mau e preguiçoso, sabias que eu colho onde não semeei e que ajunto onde não espalhei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Portanto, deverias ter entregue o meu dinheiro aos banqueiros, e na minha volta eu o receberia com juros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Portanto, tirai o talento dele e dai-o ao que tem dez talentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Pois a todo que possui, mais será dado - e terá em abundância. Mas ao que não possui nada, até o que ele tem lhe será tirado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Lançai o servo inútil para fora, nas trevas. Ali haverá choro e ranger de dentes\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'E quando o Filho do Homem vier em Sua glória e todos os anjos com Ele, então Ele se assentará no Seu glorioso trono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'Diante Dele estarão juntas todas as nações, e Ele separará as pessoas umas das outras, como o pastor separa as ovelhas dos bodes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Ele colocará as ovelhas à Sua mão direita, mas os bodes à Sua mão esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Então o Rei dirá àqueles à Sua mão direita: \'Vinde, benditos do Meu Pai, herdai o Reino que vos foi preparado desde a fundação do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Pois Eu tive fome e Me destes de comer; tive sede e Me destes de beber; era forasteiro e Me acolhestes;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'estava nu e Me vestistes; estava doente e cuidastes de Mim; estive preso e viestes ver-Me\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Então os justos responderão, dizendo: “Senhor, quando é que Te vimos com fome, e Te alimentamos? Ou com sede e Te demos de beber?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'E quando é que Te vimos forasteiro e Te acolhemos? Ou nu e Te vestimos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'E quando Te vimos doente ou na prisão e fomos Te visitar?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'E o Rei lhes responderá: “Verdadeiramente Eu vos digo que, o que fizestes por um dos Meus pequeninos irmãos, a Mim o fizestes\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Então Ele dirá àqueles à Sua mão esquerda: “Afastai-vos de Mim, vós malditos, para o fogo eterno que foi preparado para o diabo e seus anjos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'porque Eu tive fome e não Me destes de comer; tive sede e não Me destes de beber;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'era forasteiro e não Me acolhestes; estive nu e não Me vestistes; doente e na prisão e não me visitastes\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Então eles também responderão, dizendo: “Senhor, quando é que Te vimos com fome, ou com sede, ou forasteiro, ou nu, ou doente, ou preso, e não Te servimos?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Então Ele lhes responderá: “Verdadeiramente Eu vos digo, o que não fizestes a um dos Meus pequeninos, foi a Mim que o deixastes de fazer.”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Estes irão para o castigo eterno, mas os justos para a vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Aconteceu que, quando Jesus terminou todas estas palavras, Ele disse aos Seus discípulos:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '\"Sabeis que daqui a dois dias será a Páscoa, e o Filho do Homem será entregue para ser crucificado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Então os principais sacerdotes e os anciãos do povo reuniram-se no palácio do sumo sacerdote, que se chamava Caifás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'Secretamente, eles conspiraram prender Jesus e matá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Mas diziam: \"Não durante a festa, para que não se levante um tumulto entre o povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Estando Jesus em Betânia, na casa de Simão, o leproso,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'enquanto estava reclinado à mesa, uma mulher veio a Ele trazendo um vaso de alabastro com bálsamo muito valioso, e o derramou sobre Sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Mas quando os discípulos viram isso, eles se zangaram e disseram: \"Qual a razão para tal desperdício?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'O bálsamo poderia ser vendido por uma boa quantia e dada aos pobres\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Mas Jesus, sabendo disso, disse a eles: \"Por que estão perturbando esta mulher? Ela praticou uma boa ação para comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Sempre tereis os pobres convosco, mas nem sempre me tereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Pois quando ela derramou o bálsamo sobre o meu corpo, ela o fez para o meu sepultamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Verdadeiramente Eu vos digo, onde quer que este evangelho seja pregado em todo o mundo, o que esta mulher fez será contado em sua memória\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Então, um dos doze, que se chamava Judas Iscariotes, foi aos principais sacerdotes');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'e disse-lhes: \"O que me dareis se eu o entregar a vós?\" Eles pesaram trinta moedas de prata para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'A partir daquele momento, ele procurava uma oportunidade para entregá-Lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'No primeiro dia dos pães asmos, os discípulos vieram a Jesus e disseram: \"Onde desejas que te preparemos a refeição da Páscoa?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Ele disse: \"Ide à cidade, a certo homem e dizei-lhe: O Mestre diz: \'Minha hora está próxima. Eu celebrarei a Páscoa em tua casa com meus discípulos\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Os discípulos fizeram como Jesus os instruiu e prepararam a refeição da Páscoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Quando a noite chegou, Ele sentou-se para comer com seus doze discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Enquanto eles comiam, disse-lhes: \"Verdadeiramente Eu vos digo que um de vós me trairá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Eles ficaram muito tristes, e cada um perguntava-Lhe: \"Certamente não sou eu, Senhor?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Ele respondeu: \"Aquele que pôs comigo a mão no prato, esse me trairá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'O Filho do Homem morrerá, conforme está escrito sobre Ele. Mas ai daquele por quem o Filho do Homem é traído! Seria melhor para ele que não tivesse nascido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Judas, que iria traí-Lo, disse: \"Sou eu, Rabi?\" Ele respondeu: \"Tu o disseste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Enquanto comiam, Jesus tomou um pão e, abençoando-o, o partiu e o distribuiu a Seus discípulos, dizendo: \"Tomai, comei. Este é o meu corpo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Então Ele tomou o cálice e dando graças, deu-lhes, dizendo: \"Bebei dele, todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Pois este é o meu sangue, o sangue da Aliança, que é derramado por muitos para o perdão dos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Mas Eu lhes digo que não beberei de novo deste fruto da videira, até o dia em que eu o beberei novamente convosco no Reino de Meu Pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Depois de cantarem um hino, saíram para o Monte das Oliveiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Jesus disse-lhes então: \"Essa noite todos vós vos escandalizareis por minha causa, pois está escrito: \'Eu ferirei o pastor e as ovelhas do rebanho serão dispersas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Mas após Eu ressuscitar, irei adiante de vós para a Galileia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Disse-lhe Pedro: \"Ainda que todos se escandalizem por tua causa, eu não me escandalizarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jesus disse-lhe: \"Verdadeiramente te digo, que esta noite, antes que o galo cante, me negarás três vezes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Pedro disse-Lhe: \"Mesmo que tiver de morrer contigo, não te negarei\". O mesmo disseram todos os discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Então Jesus foi com eles a um lugar chamado Getsêmani e disse aos discípulos: \"Sentai-vos aqui enquanto Eu vou ali orar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Ele levou Pedro e os dois filhos de Zebedeu consigo, começou a entristecer-se e angustiar-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Então disse-lhes: \"Minha alma está profundamente entristecida até a morte. Permanecei aqui e vigiai Comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Ele se distanciou um pouco, prostrou-se com o rosto ao chão, e orou. Ele disse: \"Meu Pai, se é possível, que passe de mim este cálice. Entretanto que não seja como Eu desejo, mas como Tu desejas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Ele veio aos seus discípulos e os encontrou dormindo, e disse a Pedro: \"Ora, não podeis vigiar comigo por uma hora?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Vigiai e orai para que não entreis em tentação. O espírito de fato está preparado, mas a carne é fraca\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Ele afastou-se uma segunda vez para orar e disse: \"Meu Pai, se não é possível que esse cálice passe, sem que Eu o beba. Seja feita a Tua vontade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Ele voltou mais uma vez e os encontrou dormindo, pois seus olhos estavam pesados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Então deixando-os de novo, afastou-se e orou pela terceira vez, dizendo as mesmas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Depois, Jesus veio aos discípulos e lhes disse: \"Estais dormindo e descansando ainda? Vede, a hora está próxima, e o Filho do Homem será entregue nas mãos dos pecadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Levantai-vos, vamos. Eis que o traidor se aproxima\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Enquanto Ele ainda falava, Judas, um dos doze, acompanhado de uma grande multidão, vinda da parte dos principais sacerdotes e anciãos do povo, vieram com espadas e paus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'O homem que estava para trair Jesus dera-lhes um sinal dizendo: \"Aquele que eu beijar, é ele. Prendei-o');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Imediatamente, ele foi a Jesus e disse: \"Salve, Rabi!\" E o beijou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jesus disse-lhe: \"Amigo, faça aquilo que vieste fazer\". Então eles se aproximaram, lançaram suas mãos sobre Jesus e O prenderam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Eis que um dos que estavam com Jesus estendeu sua mão, puxou a espada, e feriu o servo do sumo sacerdote, cortando sua orelha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'E Jesus disse-lhe: \"Coloca tua espada de volta ao seu lugar, pois todo aquele que pega em espada, perecerá pela espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Não pensas que Eu posso clamar ao Meu Pai, e Ele me enviaria mais de doze legiões de anjos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Mas então, como se cumpririam as Escrituras, que dizem ser necessário que isto aconteça?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'Naquela hora, Jesus disse à multidão: \"Viestes com espadas e paus para me prender como um ladrão? Eu sentava-me diariamente no templo ensinando e não me prendestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Mas tudo isto aconteceu para que os escritos dos profetas fossem cumpridos\". Em seguida, todos os discípulos o deixaram e fugiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Aqueles que prenderam Jesus o levaram a Caifás, o sumo sacerdote, onde os escribas e os anciãos estavam reunidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Mas Pedro O seguia a distância até o pátio do sumo sacerdote. Entrou e sentou-se com os guardas para ver o fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Os principais sacerdotes e todo o Sinédrio procuravam um falso testemunho contra Jesus, para que pudessem condená-Lo à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'Eles não encontraram nenhum, mesmo que tantas falsas testemunhas tenham se apresentado. Porém mais tarde, duas vieram à frente');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'e disseram: \"Este homem disse: \'Posso destruir o templo de Deus e reconstruí-lo em três dias\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'O sumo sacerdote levantou-se e Lhe disse: \"Tu não tens resposta? O que é isso que testificam contra Ti?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Mas Jesus ficou em silêncio. O sumo sacerdote disse-Lhe: \"Eu te ordeno pelo Deus vivo, diga-nos se és o Cristo, o Filho de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jesus respondeu-lhe: \"Tu disseste por ti mesmo. Mas Eu te digo que de agora em diante verás o Filho do Homem sentando ao lado direito do Todo-Poderoso, vindo sobre as nuvens do céu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Então o sumo sacerdote rasgou suas vestes e disse: \"Ele tem falado blasfêmia! Por que ainda precisamos de testemunhas? Ouvistes a blasfêmia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'O que pensais?\" Eles responderam e disseram: \"Ele é digno de morte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'E cuspiam em Sua face, batiam Nele e O esbofeteavam,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'e diziam: \"Profetiza-nos, Cristo. Quem é que Te bateu?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'E estando Pedro assentado do lado de fora, no pátio, uma criada foi até ele e disse: \"Tu também estavas com Jesus da Galileia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Mas ele negou na frente de todos, dizendo: \"Eu não sei do que estás falando\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Quando ele saiu para o portão, outra criada o viu e disse aos que estavam ali: \"Este homem também estava com Jesus de Nazaré\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'E ele negou de novo com um juramento: \"Eu não conheço esse homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Pouco depois, aqueles que estavam ali vieram e disseram a Pedro: \"Certamente, tu também és um deles, porque a tua maneira de falar te denuncia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Então ele começou a amaldiçoar e a jurar: \"Eu não conheço esse homem\", e imediatamente um galo cantou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Pedro lembrou-se das palavras que Jesus lhe dissera: \"Antes do galo cantar, tu me negarás três vezes\". Então ele foi para fora e chorou amargamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Quando a manhã chegou, todos os principais sacerdotes e anciãos do povo conspiravam contra Jesus, para O matarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'E tendo-O amarrado, levaram-No e O entregaram a Pilatos, o governador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Então Judas, que O havia traído, vendo que Jesus fora condenado, ficou cheio de remorso, devolveu as trinta moedas de prata aos principais sacerdotes e anciãos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'e disse: \"Eu pequei traindo sangue inocente\". Mas eles disseram: \"O que nos importa? Isso é contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Então ele jogou as moedas de prata no templo, retirou-se e foi enforcar-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Os principais sacerdotes pegaram as moedas de prata e disseram: \"Não é lícito colocá-las junto às ofertas, porque é preço de sangue\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Eles discutiram juntos o assunto e, com o dinheiro, compraram o campo do oleiro para sepultar estrangeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Por essa razão, até o dia de hoje, o campo é chamado \"Campo de Sangue\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Então, cumpriu-se o que foi dito pelo profeta Jeremias: \"Eles pegaram as trinta moedas de prata, preço pelo qual Ele foi avaliado pelo povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'e deram isso pelo campo do oleiro, conforme o Senhor me ordenou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Então Jesus, estando diante do governador, este perguntou-Lhe: \"És Tu o Rei dos Judeus?\" Jesus respondeu-lhe: \"Tu o dizes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Mas, quando Ele foi acusado pelos principais sacerdotes e anciãos, nada respondeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Então Pilatos disse-Lhe: \"Não ouves todas as acusações contra Ti?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Mas Ele não respondeu uma palavra sequer, e assim o governador ficou muito admirado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Durante a festa, era costume do governador libertar um prisioneiro escolhido pela multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Naquela ocasião, eles tinham um prisioneiro muito conhecido, chamado Barrabás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Então, quando eles estavam todos reunidos, Pilatos disse-lhes: \"A quem quereis que eu vos solte? Barrabás ou Jesus, chamado Cristo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Porque sabia que eles O haviam entregado por inveja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Enquanto ele estava sentado no tribunal, sua mulher enviou-lhe uma palavra dizendo: \"Não te envolvas com esse justo; porque hoje, em sonho, muito sofri por seu respeito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Os principais sacerdotes e os anciãos persuadiram a multidão a pedir Barrabás, e matar Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'O governador perguntou-lhes: \"Qual dos dois quereis que eu vos solte?\" Eles disseram: \"Barrabás\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Pilatos disse-lhes: \"O que devo eu fazer com Jesus, chamado Cristo?\" E todos responderam: \"Crucificai-O\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'E ele disse: \"Que mal fez Ele?\" Mas eles gritaram ainda mais alto: \"Crucificai-O\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Então, quando Pilatos viu que não poderia fazer nada e que um tumulto estava começando, ele pegou água, lavou as mãos diante da multidão e disse: \"Eu sou inocente do sangue deste homem; isso é convosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Todo o povo disse: \"Que o sangue Dele caia sobre nós e nossos filhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Então ele libertou a Barrabás, mas açoitou a Jesus e O entregou para ser crucificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Então os soldados do governador levaram Jesus para dentro do pretório, e juntaram toda a companhia de soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Eles O despiram e colocaram um manto vermelho Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'Então fizeram uma coroa de espinhos e colocaram em Sua cabeça, e um cajado na Sua mão direita, e eles ajoelhavam diante Dele e zombavam Dele, dizendo: \"Salve, Rei dos judeus!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'E, cuspindo Nele, pegaram o cajado e bateram na Sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Enquanto zombavam Dele, tiraram-Lhe o manto vermelho, vestiram-No com as suas próprias roupas, e levaram-No para ser crucificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Ao saírem, eles encontraram um homem de Cirene chamado Simão, a quem obrigaram a carregar a Sua cruz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Eles chegaram a um lugar chamado Gólgota, que significa \"Lugar da Caveira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Deram-Lhe vinho misturado com fel; mas tendo provado, não quis beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Depois de O crucificarem, dividiram entre si as roupas Dele, lançando sorte;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'e, assentados ali, o vigiavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'E puseram acima da Sua cabeça a acusação na qual estava escrito: \"ESTE É JESUS O REI DOS JUDEUS\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Dois ladrões foram crucificados com Ele, um à Sua direita e outro à Sua esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Aqueles que passavam, blasfemavam Dele, balançando a cabeça');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'e dizendo: \"Tu, que irias destruir o templo e reconstruí-lo em três dias, salva-Te a Ti mesmo. Se Tu és o Filho de Deus, desça da Cruz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Da mesma maneira, os principais sacerdotes estavam zombando Dele juntamente com os escribas e anciãos, e diziam:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '\"Ele salvou os outros, mas não pode salvar-Se a Si mesmo. Ele é o Rei de Israel! Que Ele desça agora da cruz, e nós creremos Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Ele confiou em Deus; que Deus O resgate agora, se Lhe quer bem, porque Ele disse: \'Eu sou o Filho de Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'E os ladrões que estavam crucificados com Ele também falavam-Lhe os mesmos insultos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Desde a hora sexta até a hora nona, escuridão veio sobre toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Perto da hora nona, Jesus clamou em alta voz e disse: \"Eli, Eli, lamá sabactani?\", que significa: \"Deus meu, Deus meu, por que Me desamparaste?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Quando alguns dos que estavam parados ali ouviram isso, disseram: \"Ele está chamando por Elias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Imediatamente um deles correu, pegou uma esponja, encheu-a de vinagre, colocou-a na ponta de um caniço, e deu-Lhe de beber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Os outros disseram: \"Deixe-O sozinho, vamos ver se Elias virá para salvá-Lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Então Jesus clamou novamente em alta voz e entregou Seu espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'E eis que o véu do templo rasgou-se em duas partes de alto a baixo; a terra tremeu, e as rochas se fenderam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'Os túmulos foram abertos, e muitos corpos de santos, que dormiam, foram ressuscitados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'Eles saíram dos túmulos após a Sua ressurreição, entraram na cidade santa e apareceram a muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Quando o centurião e aqueles que guardavam a Jesus viram o terremoto e as coisas que haviam acontecido, ficaram com muito medo e disseram: \"Verdadeiramente este era o Filho de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Muitas mulheres, que seguiam a Jesus desde a Galiléia para O servirem, estavam ali, olhando de longe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Entre elas, Maria Madalena; Maria, a mãe de Tiago e José; e a mãe dos filhos de Zebedeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Ao cair da tarde, veio de Arimateia um homem rico, chamado José, que também era discípulo de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Ele aproximou-se de Pilatos e pediu o corpo de Jesus. Então Pilatos ordenou que lhe fosse dado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'José tomou o corpo, envolveu-o em um pano limpo de linho');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'e o colocou em seu túmulo novo, que havia sido escavado na rocha. Depois ele rolou uma grande pedra em frente à porta do túmulo e foi embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Maria Madalena e a outra Maria estavam lá, sentadas diante do sepulcro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'No dia seguinte, que era o dia depois da Preparação, os principais sacerdotes e os fariseus reuniram-se com Pilatos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'Eles disseram: \"Senhor, lembramo-nos que quando Aquele enganador estava vivo, Ele disse: \'Após três dias, Eu ressuscitarei\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Portanto ordena que o túmulo seja vigiado até o terceiro dia, ou então Seus discípulos podem vir, roubar o corpo e dizer ao povo: \'Ele ressuscitou dos mortos\'; e esse último engano será ainda pior que o primeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilatos disse-lhes: \"Levai guardas, ide e guardai o túmulo como bem vos parecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Indo eles, montaram guarda ao túmulo, selando a pedra e deixando ali os guardas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'E após o sábado, ao raiar o primeiro dia da semana, Maria Madalena e a outra Maria foram ver o sepulcro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'E eis que houvera um grande terremoto, pois um anjo do Senhor desceu do céu, veio e rolou a pedra e sentou-se sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Seu aspecto era como um relâmpago e as suas roupas, brancas como a neve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Os guardas tremeram de medo e ficaram como mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Mas o anjo, dirigindo-se às mulheres, disse-lhes: \"Não temais, eu sei que buscais Jesus, que foi crucificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Ele não está aqui, mas ressuscitou como tinha dito. Vinde ver o lugar onde o Senhor estava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Ide depressa e dizei aos Seus discípulos: \'Ele ressuscitou dentre os mortos e vai à frente de vós para a Galileia, lá O vereis\'. É como vos digo!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'As mulheres deixaram o sepulcro rapidamente com temor e grande alegria, e correram para falar aos discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'E eis que Jesus veio ao encontro delas e disse: \"Saudações!\". As mulheres, aproximando-se, abraçaram-Lhe os pés e O adoraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Então Jesus lhes disse: \"Não temais. Ide e dizei para Meus irmãos irem à Galileia e lá Me verão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'E enquanto as mulheres estavam indo, eis que alguns dos guardas foram à cidade e contaram aos chefes dos sacerdotes tudo o que tinha acontecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Tendo os sacerdotes se reunido com os anciãos e elaborado um plano, deram uma grande quantidade de dinheiro aos soldados, recomendando-lhes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, '\"Dizei que os discípulos de Jesus vieram de noite e roubaram-lhe o corpo, enquanto dormíamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'E se esta notícia chegar aos ouvidos do governador, nós o convenceremos, e vos deixaremos livres de preocupações\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Então os soldados pegaram o dinheiro e fizeram conforme tinham sido instruídos. Essa história se espalhou entre os judeus até o dia de hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Os onze discípulos foram para a Galileia, para o monte que Jesus lhes indicara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Quando eles O viram, O adoraram, mas alguns duvidaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'E Jesus, aproximando-se deles, disse-lhes: \"Toda autoridade foi-Me dada no céu e sobre a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Portanto ide e fazei discípulos de todas as nações. Batizando-as em nome do Pai, do Filho e do Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Ensinando-as a guardar todas as coisas que vos tenho ordenado. E eis que estou convosco todos os dias, até o fim dos tempos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Este é o princípio do evangelho de Jesus Cristo, o Filho de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Como está escrito no livro do profeta Isaías: \"Eis aí estou enviando o Meu mensageiro diante da Tua face, o qual irá preparar o Teu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'A voz de alguém clamando no deserto: \'Preparai o caminho do Senhor, fazei retas as Suas veredas\'\";');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'João veio, batizando no deserto e proclamando um batismo de arrependimento para perdão dos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Toda a província da Judeia e todos os habitantes de Jerusalém vinham até ele. Eles eram batizados por ele no rio Jordão, confessando os seus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'João vestia-se com roupas de pelos de camelo, tinha um cinto de couro ao redor de sua cintura e alimentava-se de gafanhotos e mel silvestre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Ele proclamava, dizendo: \"Alguém está vindo depois de mim, o qual é mais poderoso do que eu, e eu não sou digno de abaixar para desatar as correias de Suas sandálias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Eu vos batizei com água, mas Ele vos batizará com o Espírito Santo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Aconteceu que, naqueles dias, Jesus veio de Nazaré da Galileia, e foi batizado por João no rio Jordão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Quando Jesus saiu da água, Ele viu os céus se abrirem e o Espírito descendo sobre Ele como uma pomba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'E uma voz veio dos céus: \"Tu és Meu Filho amado. Eu tenho muito prazer em Ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Então o Espírito imediatamente O compeliu para o deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Ele esteve no deserto por quarenta dias, sendo tentado por Satanás. Ele estava com os animais selvagens, e os anjos O serviam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Depois que João foi preso, Jesus veio até a Galileia, proclamando o evangelho de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'dizendo: \"O tempo é cumprido, e o reino de Deus está próximo. Arrependei-vos e credes no evangelho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Caminhando junto ao mar da Galileia, Ele viu Simão e André, irmão de Simão, lançando a rede ao mar, pois eram pescadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Jesus disse-lhes: \"Vinde, segui-Me, e Eu vos farei pescadores de homens\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Imediatamente deixaram as redes e seguiram-No.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'E Jesus, caminhando um pouco mais além, viu Tiago, filho de Zebedeu, e João, seu irmão; eles estavam no barco consertando as redes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'E logo os chamou, e eles deixaram seu pai, Zebedeu, com os empregados no barco e O seguiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Entraram em Cafarnaum, e no Sabbath Jesus entrou na sinagoga e pôs-se a ensinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Eles estavam maravilhados com o Seu ensino, porque Ele os ensinava como alguém que tem autoridade e não como os escribas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'E ali, na sinagoga, estava um homem com um espírito imundo que gritou dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, '\"O que temos nós contigo, Jesus de Nazaré? Vieste para nos destruir? Eu sei quem és. Tu és o Santo de Deus!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Jesus repreendeu o demônio e disse: \"Cala-te e sai dele!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'E o espírito imundo jogou-o no chão e saiu dele gritando em alta voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Todas as pessoas estavam maravilhadas e perguntavam umas às outras: \"O que é isso? Um novo ensinamento com autoridade? Ele ordena até os espíritos imundos, e eles O obedecem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Imediatamente a notícia acerca Dele espalhou-se em toda a região da Galileia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Logo que saíram da sinagoga, foram à casa de Simão e André, com Tiago e João.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'A sogra de Simão estava deitada, enferma e com febre. E logo eles falaram a Jesus sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Então Ele veio, segurou-a pela mão e a levantou; a febre a deixou, e ela começou a servi-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Quando era noite, depois que o sol se pôs, eles Lhe trouxeram todos os que estavam doentes ou possuídos por demônios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'Toda a cidade reuniu-se à porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Ele curou muitos que estavam doentes de várias enfermidades e expulsou muitos demônios. Mas não permitiu que os demônios falassem, porque eles O conheciam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Ele levantou-se muito cedo, enquanto ainda estava escuro; saiu, foi para um lugar solitário e ali orou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Simão e aqueles que estavam com Ele O procuravam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'Eles O encontraram e disseram-Lhe: \"Todos estão procurando por Ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Ele lhes disse: \"Vamos para outros lugares, para as cidades vizinhas, para que Eu pregue lá também. É isso que Eu vim fazer aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Ele foi por toda Galileia, pregando em suas sinagogas e expulsando os demônios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Um leproso veio até Ele e Lhe suplicava de joelhos. Ele disse a Jesus: \"Se Tu quiseres, podes me tornar limpo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Movido de compaixão, Jesus estendeu a sua mão e o tocou, dizendo-lhe: \"Eu quero. Sê limpo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Imediatamente a lepra o deixou, e ele ficou limpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Jesus advertiu-o severamente e o mandou embora,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'dizendo-lhe: \"Olha, não digas nada a ninguém, mas vai e apresenta-te ao sacerdote e oferece pela tua purificação o que Moisés ordenou, como testemunho para eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Mas ele saiu e começou a proclamar a todos e espalhou a notícia, de tal maneira que Jesus não podia entrar livremente em qualquer cidade. Ele tinha que ficar em lugares desabitados, mas mesmo assim as pessoas vinham a Ele de todos os lugares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Quando voltou para Cafarnaum, depois de alguns dias, ouviu-se que Ele estava em casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Assim, muitos se reuniram lá, e não havia mais espaço, nem mesmo à porta, e Jesus anunciava-lhes a palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Alguns vieram a Jesus trazendo-Lhe um homem paralítico; quatro pessoas o carregavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Mas eles não podiam chegar perto Dele por causa da multidão. Então, removeram o telhado do lugar onde Jesus estava e, tendo feito um buraco, desceram o leito no qual o homem paralítico estava deitado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Vendo-lhes a fé, disse Jesus para o homem paralítico: \"Filho, teus pecados estão perdoados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'E havia ali alguns escribas da lei sentados que raciocinavam em seu coração:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '\"Como pode esse homem falar deste jeito? Ele blasfema! Quem pode perdoar pecados senão Deus somente?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Imediatamente, Jesus, sabendo em Seu espírito o que eles estavam pensando entre si, disse-lhes: \"Por que estais pensando isto em vossos corações?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'O que é mais fácil dizer para o homem paralítico: \'Os teus pecados estão perdoados\' ou dizer: \'Levanta-te, pega o teu leito e anda\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Mas, para que saibais que o Filho do Homem tem autoridade na terra para perdoar pecados,\" disse Ele ao paralítico:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, '\"Eu te digo: Levanta-te, pega o teu leito e vai para tua casa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Ele se levantou e imediatamente pegou seu leito e saiu da casa na frente de todos, de modo que estavam todos maravilhados e deram glória a Deus e disseram: \"Nós nunca vimos qualquer coisa como esta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Ele saiu novamente para a beira do mar, e toda a multidão vinha a Ele, e Ele a ensinava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Enquanto passava, viu a Levi, o filho de Alfeu, que estava sentado no lugar de coletar impostos, e lhe disse: \"Segue-me.\" Ele se levantou e O seguiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Enquanto Jesus estava à mesa na casa de Levi, muitos cobradores de impostos e pecadores comiam com Jesus e os seus discípulos, porque havia muitos que O seguiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Quando os escribas dos fariseus viram que Jesus estava comendo com pessoas pecadoras e cobradores de impostos, falaram aos discípulos Dele: \"Por que Ele come com cobradores de impostos e pecadores?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Quando Jesus ouviu isto, disse-lhes: \"Pessoas saudáveis não precisam de médico; somente os doentes precisam. Eu não vim para chamar os justos, mas os pecadores\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Os discípulos de João e os fariseus estavam jejuando. Vieram alguns e disseram-Lhe: \"Por que os discípulos de João e os discípulos dos fariseus jejuam, mas os Teus discípulos não jejuam?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Jesus disse-lhes: \"Podem os convidados do casamento jejuar enquanto o noivo ainda está com eles? Enquanto eles têm o noivo, eles não podem jejuar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Mas dias virão em que o noivo lhes será tirado e, naqueles dias, eles jejuarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Ninguém remenda um pedaço de roupa nova em uma roupa velha; caso contrário, o remendo irá romper a roupa velha, e um rasgo maior se fará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Nenhum homem põe vinho novo em odres velhos; se ele fizer isso, o vinho novo romperá as peles, e tanto o vinho como os odres se perderão. Em vez disso, põe-se vinho novo em odres novos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'E aconteceu que, em um dia de Sabbath, ao passar Jesus por algumas plantações, Seus discípulos começaram a abrir caminhos arrancando as espigas de grãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'E os fariseus disseram-Lhe: \"Vê, por que eles estão fazendo algo que não é permitido no Sábado?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Ele lhes disse: \"Nunca lestes o que Davi fez quando estava em necessidade e com fome, ele e os homens que estavam com ele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Como ele entrou na casa de Deus quando Abiatar era o sumo sacerdote e comeu o pão da presença, que não é permitido para qualquer um comer, exceto os sacerdotes; e o deu também àqueles que estavam com ele?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Jesus disse: \"O Sabbath foi feito para o homem, não o homem para o Sabbath.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Portanto, o Filho do Homem é Senhor até do Sabbath\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Novamente, Jesus entrou na sinagoga e havia um homem com uma mão atrofiada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'E algumas pessoas O observavam atentamente para ver se Ele o curaria no Sabbath, para que pudessem acusá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Jesus disse ao homem com a mão atrofiada: \"Levanta e vem aqui para o meio de todos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Então, Ele disse às pessoas: \"É permitido fazer o bem no Sabbath ou fazer mal; salvar uma vida, ou matar?\". Mas eles ficaram em silêncio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Ele, olhando ao redor indignado, muito entristecido pela dureza de seus corações, disse ao homem: \"Estende a mão\". Ele estendeu a mão e Jesus a restaurou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Os fariseus se retiraram e, imediatamente, começaram a conspirar com os herodianos, sobre como poderiam matá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Então, Jesus foi com seus discípulos para o mar. E uma grande multidão de pessoas O seguia, vinda da Galileia, da Judeia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'de Jerusalém, Idumeia e dalém do Jordão, e dos arredores de Tiro e Sidom. Quando ouviram falar das coisas que Ele estava fazendo, uma grande multidão veio até Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'E pediu a Seus discípulos que deixassem um pequeno barco pronto para Ele, por causa da multidão, para que não O esmagassem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Pois Ele curou a muitos, a ponto de que todos os que padeciam de enfermidades, ansiosamente, se aproximavam Dele para tocá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Sempre que os espíritos imundos O viam, caíam diante Dele, clamavam e diziam: \"Tu és o Filho de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Ele, com firmeza, ordenava-lhes que não O tornassem conhecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Ele subiu à montanha e chamou por aqueles que queria, e vieram a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Escolheu os doze (a quem chamou apóstolos) para que estivessem com Ele, para enviá-los a proclamar a mensagem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'e ter autoridade para expelir demônios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Ele nomeou os doze: Simão, a quem Ele deu o nome de Pedro;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Tiago, filho de Zebedeu, e João, irmão de Tiago, aos quais Ele deu o nome de Boanerges, que significa filhos do trovão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'e André; Filipe; Bartolomeu; Mateus; Tomé; Tiago, filho de Alfeu; Tadeu; Simão, o zelote;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'e Judas Iscariotes, que O trairia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Então, Ele foi para casa, e a multidão se ajuntou novamente de modo que eles não podiam nem mesmo se alimentar de pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Quando Sua família ouviu sobre isso, eles saíram para impedi-Lo, pois diziam: \"Ele está fora de si\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Os escribas que vieram de Jerusalém diziam: \"Ele está possuído por Belzebu\" e \"pelo chefe dos demônios é que Ele expulsa os demônios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Jesus os chamou e falou-lhes em parábolas: \"Como pode Satanás expulsar Satanás?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Se um reino está dividido contra si mesmo, tal reino não pode permanecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Se uma casa está dividida contra si mesma, tal casa não conseguirá permanecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Se Satanás se levantou contra si mesmo e está dividido, não pode permanecer, mas chegou ao fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Mas ninguém pode entrar na casa de um homem forte e roubar seus pertences sem amarrá-lo primeiro; então, lhe saqueará a casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Verdadeiramente eu vos digo, todos os pecados dos filhos dos homens serão perdoados, até mesmo todas as blasfêmias que proferiram;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'mas quem blasfema contra o Espírito Santo nunca terá perdão, mas é culpado de um pecado eterno\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Jesus disse isso porque estavam dizendo: \"Ele tem um espírito imundo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Sua mãe e irmãos vieram e ficaram do lado de fora. Eles enviaram alguém para chamá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Uma multidão sentou-se em volta Dele e falou para Jesus: \"Tua mãe e Teus irmãos estão lá fora e estão à Tua procura\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Ele lhes respondeu: \"Quem são minha mãe e meus irmãos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Ele olhou para todos os que estavam sentados em círculo a sua volta e lhes disse: \"Vede, aqui estão minha mãe e meus irmãos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Porque qualquer um que faz a vontade de Deus, esse é Meu irmão, irmã e mãe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Novamente, Jesus começou a ensinar à beira do mar. E uma grande multidão se reuniu ao seu redor, assim, Ele entrou em um barco no mar, e sentou-se. Toda a multidão estava ao lado do mar, na praia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Ele lhes ensinava muitas coisas por parábolas, e lhes dizia:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '\"Escutai! Eis que o semeador saiu para semear.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Enquanto ele semeava, algumas sementes caíram no caminho, as aves vieram e as devoraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Outras caíram em terreno rochoso, onde não havia muita terra. Imediatamente elas brotaram, porque a terra não tinha profundidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Mas quando o sol nasceu, elas foram queimadas porque não tinham raízes e secaram-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Outras sementes caíram em meio às plantas espinhosas, estas cresceram e sufocaram. E com isso as sementes não produziram grãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Outras sementes caíram em solo bom e produziram grãos enquanto cresciam e se multiplicavam, alguns produzindo trinta, outros sessenta, e outros cem vezes mais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Ele disse: \"Aquele que tem ouvidos para ouvir, ouça!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Quando Jesus estava sozinho, os que estavam perto Dele e os doze, perguntaram-Lhe sobre as parábolas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Ele disse-lhes: \"A vós é dado o mistério do Reino de Deus, mas àqueles de fora tudo é feito em parábolas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'para que, vendo, vejam, mas não enxerguem, e ouvindo, ouçam, mas não percebam, caso contrário, eles se converteriam e Deus os perdoaria\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Ele lhes disse: \"Vós não entendeis esta parábola? Como então compreendereis todas as outras?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'O semeador semeia a palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'E aqueles à beira do caminho são os que a ouvem, mas vem Satanás e rouba imediatamente de seus corações a palavra que neles foi semeada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'E alguns são aqueles que são semeados em solo rochoso, os quais, quando ouvem a palavra, logo a recebem com alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'E eles não têm raízes em si mesmos, mas resistem por um tempo. Então, vem tribulação ou perseguição por causa da palavra, e, imediatamente, eles tropeçam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'E outros são aqueles semeados em meio aos espinhos. Eles são os que ouvem a palavra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'mas os cuidados do mundo, a ilusão das riquezas e as ambições por outras coisas entram e sufocam a palavra, e ela torna-se infrutífera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'E há aqueles que são semeados em solo bom. Eles ouvem a palavra, a recebem e ela produz fruto, alguns trinta, outros sessenta e outros cem vezes”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Jesus disse-lhes: \"Vós trazeis uma lâmpada para dentro da casa e a colocais embaixo de um cesto ou embaixo da cama? Vós a trazeis e a colocais no velador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Porque nada há oculto, que não venha a ser conhecido, nem há algo em segredo que não venha a ser descoberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Se alguém tem ouvidos para ouvir, ouça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Ele lhes disse: \"Prestai atenção ao que ouvis, pois a medida que vós medirdes, vos medirão a vós e ainda mais vos será aumentada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Porque aquele que tem, mais lhe será dado, e ao que não tem, dele será tirado até o que tem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Jesus disse: \"O Reino de Deus é como um homem que planta sua semente no solo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'Ele dorme e se levanta, enquanto a semente brota e cresce, embora não saiba como.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'A terra por si mesma produz o fruto: primeiro surge a planta, depois a espiga, e mais tarde, os grãos que enchem a espiga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'E quando o grão está maduro, imediatamente, o homem passa a foice porque a colheita chegou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Disse-lhe ainda: \"A que podemos comparar o reino de Deus? E qual parábola podemos usar para explicá-lo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Ele é como um grão de mostarda que, quando é plantado, é a menor de todas as sementes na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Porém, quando plantado, cresce e se torna maior do que todas as hortaliças do jardim. E forma ramos grandes, de modo que as aves do céu podem fazer seus ninhos em sua sombra”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'E com muitas parábolas lhes dirigia a palavra, conforme podiam compreender.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'E Ele nada lhes falava, a não ser em parábolas. Porém, em particular, explicava tudo aos Seus próprios discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Naquele dia, ao anoitecer, Ele lhes disse: \"Vamos para o outro lado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Deixando a multidão, os discípulos levaram Jesus, pois já estava no barco. Outros barcos também estavam com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Então começou uma violenta tempestade com vento, e as ondas invadiam o barco, de modo que estava prestes a ficar cheio de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Mas Jesus estava na popa, dormindo sobre um travesseiro. Os discípulos o acordaram, dizendo: \"Mestre, Tu não Te importas que estejamos prestes a morrer?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Jesus acordou, repreendeu o vento e disse ao mar: \"Silêncio, fica calmo”. E o vento cessou e houve grande calmaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Ele disse-lhes: \"Por que estais com medo? Vós ainda não tendes fé?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Estavam cheios de grande temor e disseram uns aos outros: \"Quem é Este que até o vento e o mar Lhe obedecem?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Chegaram ao outro lado do mar, à região dos gerasenos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Assim que Jesus saiu do barco, um homem com espírito imundo, saindo dos sepulcros, veio até Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'O homem vivia em sepulcros. Ninguém podia detê-lo, nem mesmo com uma corrente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Ele havia sido preso várias vezes com correntes e algemas, mas as quebrava e ninguém tinha força para dominá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Todas as noites e dias, nos sepulcros e nas montanhas, ele gritava e se cortava com pedras afiadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Quando viu Jesus de longe, correu e ajoelhou-se diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'Ele clamou em alta voz: \"Que tenho eu contigo, Jesus, Filho do Deus Altíssimo? Imploro-Te, por Deus, que não me atormentes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Pois Jesus já lhe havia ordenado: \"Sái deste homem, espírito imundo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Todavia Jesus o interrogou: \"Qual é o teu nome?\" Respondeu ele: \"Meu nome é Legião, pois nós somos muitos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'E implorava a Jesus repetidamente que não os mandasse para fora da região.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Aconteceu que uma grande manada de porcos pastava no monte,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'e os espíritos imundos O imploraram, dizendo: \"Manda-nos para os porcos; deixa-nos entrar neles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'E Jesus assim lhes permitiu. Então os espíritos imundos saíram e entraram nos porcos. A manada, de uns dois mil, lançou-se ao lago por um precipício, e se afogaram na água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'As pessoas que apascentavam os porcos fugiram, relataram esses fatos na cidade e nos campos, e todo o povo correu para ver o que se havia passado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Chegando a Jesus, viram o endemoniado, o que tivera a legião, sentado, vestido e em perfeito juízo e eles ficaram com medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Aqueles que viram o que acontecera ao homem possuído por demônios contaram o que havia ocorrido a ele e também aos porcos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Começaram a suplicar para Jesus que deixasse sua região.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Quando Ele estava entrando no barco, o homem antes possuído por demônios implorou para que pudesse estar com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Jesus porém, não lhe permitiu, mas disse: \"Vai para tua casa, para teu povo, e dize-lhes o que o Senhor fez por ti e como teve misericórdia de ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Então o homem foi embora e proclamou em Decápolis os grandes feitos de Jesus por ele. E todos ficaram maravilhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Quando Jesus atravessou novamente para o outro lado, no barco, uma grande multidão se aglomerou ao Seu redor, enquanto Ele estava junto ao mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'E eis que chegou um dos chefes da sinagoga, chamado Jairo, e caiu aos Seus pés quando O viu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'Ele implorava repetidamente, dizendo: \"Minha filhinha está à beira da morte. Te imploro que venhas e imponhas as Tuas mãos sobre ela, e assim ficará bem e viva\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Então Jesus foi com ele. Uma grande multidão O seguia e O comprimia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Ora, havia uma mulher que sofria de hemorragia há doze anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'Ela muito sofrera sob os cuidados de vários médicos e gastara tudo o que possuía. Mas nada lhe ajudava; pelo contrário, piorava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Tendo ouvido falar a respeito de Jesus, veio por detrás, entre a multidão, e tocou-lhe o manto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Pois ela dizia: \"Se eu tocar ao menos Suas vestes, serei curada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Naquele instante, se lhe estancou a hemorragia e a mulher sentiu que seu corpo estava liberto do seu sofrimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Imediatamente, Jesus percebeu que Dele havia saído poder. Virou-se, no meio da multidão, e perguntou: \"Quem tocou em Minhas vestes?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Os Seus discípulos Lhe disseram: “Vês esta multidão comprimindo-Te e dizes: ‘Quem Me tocou?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Mas Jesus olhou ao Seu redor para ver quem havia feito isto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'A mulher, sabendo o que lhe havia acontecido, temeu e tremeu. Ela veio, prostrou-se diante de Jesus e contou-Lhe toda a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Então, lhe disse: \"Filha, tua fé te curou. Vai em paz e fica livre da tua doença\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Enquanto Ele falava, algumas pessoas vieram da casa do chefe da sinagoga, dizendo: \"Tua filha está morta. Por que ainda incomodas o Mestre?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Mas quando Jesus ouviu o que eles diziam, disse ao chefe da sinagoga: \"Não temas. Apenas crê\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'E não permitiu que ninguém O acompanhasse, exceto Pedro, Tiago e João, irmão de Tiago.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Quando chegaram a casa do chefe da sinagoga, viu Jesus um alvoroço, e os que estavam chorando e lamentando alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Quando Ele entrou na casa, disse-lhes: \"Por que estais alvoroçados e chorais? A criança não está morta, mas dorme\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Riram de Jesus, porém Ele colocou todos para fora, tomou o pai da criança, a mãe e os que estavam com Ele, e foi onde a criança estava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'E, tomando a mão da menina, disse-lhe: \"Talita cumi\", que significa: \"Menina, Eu te digo: \'Levanta-te\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Imediatamente a criança se levantou e andou (pois ela tinha doze anos de idade). Logo foram tomados de grande espanto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Jesus ordenou expressamente que ninguém soubesse disso, dizendo que dessem algo de comer à menina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Jesus saiu dali e veio para sua terra natal, e Seus discípulos O seguiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Quando chegou o Sabbath, Ele ensinou na sinagoga. Muitos O ouviram e ficaram maravilhados. Eles diziam: \"Onde Ele aprendeu esses ensinamentos?\". \"Que sabedoria é essa que Lhe foi dada?\". \"O que são esses milagres que Ele faz com Suas mãos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, '\"Não é Esse o carpinteiro, filho de Maria, e irmão de Tiago, José, Judas e Simão? Não estão Suas irmãs conosco?\". E eles se escandalizaram com Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'E Jesus lhes disse: \"Não há profeta sem honra, a não ser em sua terra natal, e entre seus próprios parentes, e em sua própria casa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Ele não podia realizar qualquer milagre ali, exceto a alguns doentes sobre os quais Ele impôs Suas mãos e os curou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'A falta de fé deles O deixou atônito. E ele saiu pelas vilas ensinando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Ele chamou os Doze e começou a enviá-los, dois a dois; e deu-lhes autoridade sobre os espíritos imundos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'e Ele os instruiu que nada levassem pelo caminho, a não ser um cajado: nem pão, nem bolsa, nem dinheiro em seus cintos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'mas que calçassem sandálias e não vestissem duas túnicas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Disse-lhes ainda: \"Sempre que entrardes em uma casa, ficai nela até que deixeis o lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'E se em algum lugar não vos receberem nem vos ouvirem, quando sairdes dali, sacudi a poeira debaixo de vossos pés, em testemunho contra eles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Eles saíram e proclamaram que as pessoas deveriam arrepender-se de seus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'E expulsavam muitos demônios, ungiam muitos doentes com óleo e os curavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'O rei Herodes ouvira isso, pois o nome de Jesus havia se tornado bastante conhecido. Alguns diziam: \"João, o Batista, foi levantado dentre os mortos e devido a isso, esses poderes miraculosos estão agindo Nele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Outros diziam: \"Ele é Elias\". Ainda outros diziam: \"Ele é um profeta, como um dos profetas de antigamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Mas quando Herodes ouviu isso, disse: \"João, o qual eu decapitei, foi ressuscitado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Pois o próprio Herodes havia mandado prender João e o colocou na prisão por causa de Herodias (esposa de seu irmão Filipe), pois ele havia se casado com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Porque João dissera a Herodes: \"Não é lícito que possuas a esposa de teu irmão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'No entanto, Herodias guardava rancor contra João e desejava matá-lo, mas não podia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'pois Herodes temia João, sabia que ele era um homem justo e santo, e o mantinha em segurança. Ao ouvir João, Herodes sentia-se incomodado, porém ouvia-o de boa vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Então, em um dia oportuno, por conta de seu aniversário, Herodes ofereceu um jantar a seus oficiais, comandantes e líderes da Galileia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'A filha da própria Herodias veio e dançou para eles e ela agradou Herodes e seus convidados. O rei disse à menina: \"Pede-me qualquer coisa que desejares e eu te darei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Ele jurou-lhe dizendo: \"Qualquer coisa que me pedires eu te darei, até mesmo metade do meu reino\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Ela saiu e disse à sua mãe: \"O que devo pedir-lhe?\" Ela respondeu: \"A cabeça de João, o Batista\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Ela imediatamente se apressou de volta ao rei e lhe pediu, dizendo: \"Desejo que me dês, agora mesmo, sobre um prato, a cabeça de João, o Batista\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'O rei se entristeceu muito, mas por causa de seu juramento e dos convidados, não poderia recusar seu pedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Então o rei enviou um soldado de sua guarda e o ordenou a trazer a cabeça de João. O guarda foi e o decapitou na prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Ele trouxe sua cabeça num prato e deu-a à menina e ela deu à sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Ao ouvirem isso, seus discípulos vieram e colheram seu cadáver e o colocaram num túmulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Os apóstolos, reunindo-se em volta de Jesus, contaram-Lhe tudo o que eles haviam feito e ensinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Ele lhes disse: \"Vinde à parte para um lugar deserto e descansai por um tempo\". Pois muitos estavam indo e vindo e eles não tiveram tempo nem mesmo para comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Então foram sós, num barco, para um lugar deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Mas muitos os viram saindo e os reconheceram, e correram juntos, a pé, de todas as cidades, e eles chegaram antes deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Quando desembarcaram, Jesus viu uma grande multidão e teve compaixão deles, porque eram como ovelhas sem um pastor. E Ele começou a ensiná-los muitas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Quando a hora estava avançada, Seus discípulos vieram a Ele e disseram: \"Este é um lugar deserto e a hora já está avançada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Despede-os para que possam ir a campos e vilas próximos comprar algo para comer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Mas Jesus, respondendo, disse-lhes: \"Dai-lhes algo para comer\". Eles disseram-Lhe: \"Podemos ir e comprar duzentos denários de pão e dar-lhes para que comam?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Ele lhes disse: \"Quantos pães tendes vós? Ide e conferi\". Quando eles descobriram, disseram: \"Cinco pães e dois peixes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Ele ordenou que todos sentassem em grupos sobre a grama verde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Eles sentaram em grupos; grupos de cem e de cinquenta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Ele, pegando os cinco pães e dois peixes, olhando para o céu, abençoou e partiu os pães e os deu aos discípulos para que colocassem em frente à multidão. E dividiu os dois peixes entre todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Todos comeram até se saciarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'Eles coletaram os pedaços de pães partidos, doze cestos cheios, e também pedaços de peixe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Eram cinco mil homens os que comeram os pães.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Imediatamente Ele fez Seus discípulos entrarem no barco e seguirem à Sua frente para o outro lado, para Betsaida, enquanto Jesus dispersava a multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Quando eles saíram, Ele subiu a montanha para orar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'A noite veio, o barco estava agora no meio do mar, e Ele estava sozinho em terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Ele viu que eles estavam tendo grande dificuldade ao remar, pois o vento era contrário. Então, por volta da quarta vigília da noite, Ele veio a eles, andando sobre o mar, e queria passar adiante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Mas quando O viram andando sobre o mar, pensaram que era um fantasma e gritaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'Pois O viram e ficaram aterrorizados. Mas imediatamente Ele lhes disse: \"Sede corajosos! Sou Eu! Não temais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Ele entrou no barco com eles, e o vento cessou de soprar. Eles estavam completamente maravilhados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'pois não entenderam acerca dos pães; em vez disso, seus corações estavam endurecidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Terminada a travessia, eles vieram à terra de Genesaré e ancoraram o barco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Quando saíram do barco, o povo imediatamente reconheceu Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'As pessoas percorreram toda a região e começaram a trazer-Lhe os doentes sobre macas, onde quer que ouviam que Ele estivesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Onde quer que Ele entrasse nas vilas, cidades ou campos, eles colocavam os doentes nas praças, e rogavam-Lhe que lhes permitisse ao menos tocar na borda de Suas vestes. E todos quantos O tocavam eram curados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Os fariseus e alguns dos escribas que vieram de Jerusalém, reuniram-se em torno de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Eles viram que alguns dos Seus discípulos comiam pães com mãos impuras, ou seja, sem lavá-las.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, '(Pois os fariseus e todos os judeus não comem sem lavar as mãos, pois guardam a tradição dos anciãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Quando retornam do mercado, os fariseus não comem, a menos que se lavem. E existem muitas outras regras as quais eles seguem rigorosamente, incluindo a lavagem de copos, jarros, vasos de bronze, e até dos assentos das mesas).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Os fariseus e os escribas perguntaram a Jesus: \"Por que os Teus discípulos não vivem de acordo com a tradição dos anciãos, pois comem seus pães sem lavar as mãos?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Ele respondeu-lhes: \"Hipócritas, bem profetizou Isaías acerca de vós, como está escrito: \'Este povo me honra com seus lábios, entretanto seu coração está distante de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Eles me oferecem um culto vazio, ensinando as regras de homens como suas doutrinas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Vós abandonais os mandamentos de Deus e vos apegais à tradição dos homens.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Disse-lhes ainda: \"Convenientemente rejeitais os mandamentos de Deus para que mantenhais vossas tradições!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Pois Moisés disse: \'Honra teu pai e tua mãe\', e, \'Aquele que maldisser a seu próprio pai ou mãe, certamente morrerá\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Entretanto vós dizeis: \'Se um homem disser ao seu pai ou mãe: \"Qualquer ajuda que devias receber de mim é \'Corbã,’” (isto quer dizer, \'Ofertado a Deus\'),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'então não mais permitis que ele faça alguma coisa para seu pai ou sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Estais anulando o mandamento de Deus pela tradição que transmitistes. E vós fazeis muitas coisas semelhantes”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Outra vez, chamou Ele a multidão e disse-lhes: \"Todos vós, ouvi o que digo, e entendei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Não há nada fora do homem que, adentrando-o, possa contaminá-lo. Mas é o que sai dele que o torna impuro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, '');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Naquele momento, quando Jesus deixou a multidão e entrou na casa, os Seus discípulos Lhe perguntaram sobre a parábola.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Jesus disse: \"Vós também continuais sem entender? Não vês que tudo o que adentra o homem não pode torná-lo impuro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'pois isto não pode entrar em seu coração, mas vai para seu estômago e então é expelido\". Com esta afirmação, Jesus tornou todos os alimentos puros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Ele disse: \"O que sai do homem é o que o torna impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Pois do interior do coração, procedem os maus pensamentos, a imoralidade sexual, o roubo, o assassinato,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'o adultério, a cobiça, a maldade, o engano, a sensualidade, a inveja, a calúnia, o orgulho, a tolice.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Todos estes males brotam de dentro, e eles tornam o homem impuro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Ele saiu dali e foi para a região de Tiro e Sidom. Entrou em uma casa e não quis que ninguém soubesse que Ele estava lá, mas não podia ocultar-Se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Imediatamente porém, uma mulher cuja filha pequena tinha um espírito imundo, ouviu a respeito de Jesus, veio e se prostrou aos Seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Todavia a mulher era grega, de origem siro-fenícia. Ela Lhe implorou que expulsasse o demônio de sua filha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Ele lhe disse: \"Deixa que as crianças se alimentem primeiro. Pois não é bom tirar o pão das crianças e lançá-lo aos cachorrinhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Contudo ela Lhe respondeu: \"Sim, Senhor, mas até os cachorrinhos debaixo da mesa comem as migalhas das crianças\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Ele disse-lhe: \"Porque disseste isso, és livre para ir. O demônio saiu da sua filha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Ela retornou para casa e encontrou a criança deitada na cama, e o demônio a havia deixado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Então, Ele saiu novamente da região de Tiro, passando por Sidom até o Mar da Galileia, na região de Decápolis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Eles trouxeram-Lhe um surdo que tinha deficiência na fala, e imploravam para Jesus colocar Sua mão sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Ele o tirou da multidão e, em particular, pôs Seus dedos em seus ouvidos e, após cuspir, Ele tocou sua língua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'Jesus olhou para o céu, suspirou e disse-lhe: \"Efatá!\", que quer dizer, \"Abre-te!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'E, imediatamente, seus ouvidos se abriram, e aquilo que obstruía sua língua foi retirado, e ele pôde falar claramente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Ele ordenou-lhes que não contassem a ninguém. Quanto mais os ordenava, tanto mais anunciavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Eles estavam absolutamente maravilhados, dizendo: \"Ele fez bem todas as coisas. Ele faz até mesmo o surdo ouvir e o mudo falar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Naqueles dias, havia novamente uma grande multidão, e eles não tinham nada para comer. Jesus chamou Seus discípulos e disse-lhes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, '\"Tenho compaixão da multidão, pois permanecem comigo há três dias e não têm o que comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Se eu os despedir para as suas casas sem comererem, desfalecerão pelo caminho. Muitos deles vieram de longe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Seus discípulos responderam: \"Onde podemos conseguir pães o bastante para satisfazer essas pessoas neste lugar deserto?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Jesus perguntou: \"Quantos pães tendes?\". Eles disseram: \"Sete\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Ele ordenou à multidão que se assentasse no chão. Ele pegou os sete pães, deu graças e os partiu; deu aos discípulos para servirem, e eles serviram a multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Eles também tinham alguns peixinhos, e depois de dar graças, Ele ordenou aos discípulos que os servissem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Eles comeram e ficaram satisfeitos. Os discípulos pegaram dos pedaços que havia sobrado, sete cestos grandes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Havia cerca de quatro mil homens ali. Jesus os despediu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Imediatamente Ele foi para o barco com Seus discípulos e foram para a região de Dalmanuta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Então os fariseus vieram e começaram a discutir com Ele. Pediram-Lhe um sinal do céu, para testá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Suspirando profundamente em Seu espírito, disse: \"Por que esta geração busca um sinal? Em verdade vos digo que nenhum sinal será dado a esta geração\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'E, deixando-os, entrou novamente no barco e partiu para o outro lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Aconteceu que os discípulos se esqueceram de levar pães. E tinham apenas um pão no barco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Jesus lhes advertiu: \"Atentai-vos e guardai-vos do fermento dos fariseus e do fermento de Herodes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Os discípulos arrazoavam entre si: \"É porque não temos pão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Jesus percebendo isso, disse-lhes: \"Por que arrazoais por não terdes pão? Não percebeis ainda? Não entendeis? Estão os vossos corações endurecidos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Tendes olhos e não vedes? Tende ouvidos e não ouvis? Não vos lembrais?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Quando Eu parti os cinco pães entre os cinco mil, quantos cestos de pães recolhestes?\". Responderam-Lhe: \"Doze\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '\"E quando reparti os sete pães entre os quatro mil, quantos cestos recolhestes?\". Eles disseram: \"Sete\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Então perguntou-lhes: \"E ainda não entendeis?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Eles chegaram a Betsaida. As pessoas levaram até Jesus um cego rogando-Lhe que o tocasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Jesus o tomou pela mão e o levou para fora da aldeia. Quando Ele cuspiu em seus olhos e colocou as mãos sobre ele, perguntou-lhe: \"Vês alguma coisa?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Levantando os olhos, ele disse: \"Vejo homens que parecem árvores andando\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Então Ele novamente tocou-lhe os olhos; a visão do homem foi restaurada e ele tudo viu com clareza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Jesus o mandou para sua casa e disse: \"Não entres na cidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Jesus foi com Seus discípulos para as aldeias de Cesareia de Filipe. No caminho, Ele perguntou aos discípulos: \"Quem as pessoas dizem que Eu sou?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Eles responderam: \"João, o Batista. Outros dizem: \'Elias\'; outros, \'Um dos profetas\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Ele perguntou-lhes: \"Mas quem vós dizeis que Eu sou?\". Respondendo, Pedro disse: \"Tu és o Cristo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Jesus advertiu-lhes que não contassem a ninguém a respeito Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Ele começou a ensiná-los que o Filho do Homem deve sofrer muitas coisas, ser rejeitado pelos anciãos, pelos principais sacerdotes e pelos escribas, ser morto, e ressuscitar após três dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Ele disse isso abertamente. Então Pedro, chamando-O em particular, começou a repreendê-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Mas Jesus virou-se, olhou para os discípulos, repreendeu a Pedro, dizendo: \"Para trás de Mim, Satanás! Não pensas nas coisas de Deus, mas nas dos homens\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Então Ele chamou a multidão com os discípulos e disse: \"Se alguém quiser Me seguir, negue-se a si mesmo, tome sua cruz e siga-Me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Pois aquele que quiser salvar sua vida, a perderá, e qualquer que perder sua vida por causa de Mim e do Evangelho, este a salvará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Que benefício terá aquele que ganhar o mundo todo e perder sua vida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'O que daria o homem em troca da sua vida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Qualquer que se envergonhar de Mim e da Minha palavra nesta geração adúltera e pecadora, o Filho do Homem se envergonhará dele quando vier na glória de Seu Pai com os santos anjos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'E Jesus disse-lhes: \"Em verdade vos digo, alguns de vós que estão aqui não experimentarão a morte antes que vejam o reino de Deus vir com poder\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Seis dias depois, Jesus tomou consigo Pedro, Tiago e João, e os levou em particular a um alto monte. Então foi transfigurado diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Suas vestes tornaram-se radiantemente brilhantes, extremamente brancas, mais brancas do que qualquer lavandeiro na terra poderia branquear.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Então Elias e Moisés apareceram a eles e conversavam com Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Pedro respondeu e disse a Jesus: \"Rabi, é bom estarmos aqui; façamos três tendas: uma para Ti, uma para Moisés, uma para Elias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, '(Ele não sabia o que dizer, pois estavam aterrorizados).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Uma nuvem veio e os envolveu. Então uma voz veio da nuvem: \"Este é meu Filho amado. A Ele ouvi!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'De repente, quando olharam em volta, não viram mais ninguém com eles, apenas Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Ao descerem do monte, Ele lhes ordenou que não contassem a ninguém o que haviam visto, até que o Filho do Homem ressuscitasse dos mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Então eles guardaram o assunto para si mesmos, mas discutiam o que poderia significar \"ressuscitar dos mortos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Eles lhe perguntaram: \"Por que os escribas dizem que Elias deve vir primeiro?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Jesus lhes respondeu: \"Elias realmente vem primeiro para restaurar todas as coisas. Então por que está escrito que o Filho do Homem deve sofrer muitas coisas e ser desprezado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Mas Eu vos digo que Elias veio, e fizeram o que quiseram com ele, exatamente como as escrituras dizem sobre ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Quando voltaram para onde estavam os outros discípulos, viram que uma grande multidão os rodeava, e escribas discutindo com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'E quando a multidão O viu, ficou maravilhada, e correu até Ele para cumprimentá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Ele perguntou a Seus discípulos: \"Sobre o que vós estais discutindo com eles?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Alguém da multidão Lhe respondeu: \"Mestre, eu Te trouxe meu filho; ele tem um espírito que o impede de falar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Este o faz ter convulsões, o derruba e ele espuma pela boca, range seus dentes, e se enrijece. Eu pedi a Seus discípulos para expulsá-lo, mas eles não puderam\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Ele lhes respondeu: \"Geração incrédula, até quando Eu terei de estar convosco? Até quando Eu vos suportarei? Trazei-o para Mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Eles trouxeram-Lhe o menino. Quando o espírito viu Jesus, imediatamente o fez convulsionar. O menino caiu no chão e rolando espumava pela boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Jesus perguntou a seu pai: \"Há quanto tempo ele está assim?\" O pai disse: \"Desde a infância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'E muitas vezes o atira no fogo ou na água, e tenta destruí-lo. Se Tu podes fazer algo, tem compaixão de nós e ajuda-nos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jesus lhe disse: \"’Se Tu podes!’ Todas as coisas são possíveis ao que crê\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Imediatamente o pai da criança clamou e disse: \"Eu creio! Ajuda-me na minha incredulidade!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Quando Jesus viu a multidão correndo em direção a eles, repreendeu o espírito imundo, dizendo-lhe: \"Espírito surdo e mudo, Eu te ordeno: Sai dele, e nunca mais entres nele novamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'E gritou e convulsionou o menino grandemente e então saiu dele. Ele parecia morto, tanto que a maioria do povo dizia: \"Ele está morto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Mas Jesus o tomou pela mão e o levantou, e o menino ficou de pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Quando Jesus entrou na casa, Seus discípulos Lhe perguntaram em particular: \"Por que não pudemos expulsá-lo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Ele lhes disse: \"Esse tipo não pode ser expulso senão pela oração\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Partindo de lá, passavam pela Galileia, e Jesus não queria que ninguém soubesse onde eles estavam,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'pois Ele ensinava a seus discípulos e lhes dizia: \"O Filho do Homem será entregue nas mãos dos homens, e eles O matarão. Quando Ele for morto, após três dias ressuscitará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Mas eles não entenderam esta declaração e estavam com medo de perguntar-Lhe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Foram para Cafarnaum. Quando Ele estava em casa perguntou a Seus discípulos: \"O que vós estáveis discutindo pelo caminho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Mas eles ficaram calados, pois argumentavam uns com os outros pelo caminho sobre quem era o maior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Ele sentou-se, chamou os doze e disse-lhes: \"Se alguém quer ser o primeiro, será o último e o servo de todos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Ele pegou uma criança pequena, colocou-a no meio deles, e tomando-a em Seus braços, disse-lhes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '\"Qualquer um que receber uma criança como esta em Meu nome, este também Me recebe; e se alguém Me recebe, este não recebe a Mim, mas Àquele que Me enviou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'João disse-Lhe: \"Mestre, nós vimos alguém expulsando demônios em Teu nome e o proibimos, porque ele não nos segue\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Mas Jesus disse: “Não o proibais. Porque ninguém pode fazer um milagre em Meu nome e logo depois dizer algo ruim a Meu respeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Quem não é contra nós, é por nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Qualquer um que vos der um copo de água para beber porque sois de Cristo, verdadeiramente vos digo que não perderá sua recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Qualquer que fizer um destes pequeninos que crê em Mim tropeçar, seria melhor para ele ter uma grande pedra de moinho amarrada em volta de seu pescoço e ser lançado ao mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Se tua mão te faz tropeçar, corta-a fora. É melhor para ti entrar na vida com uma das mãos decepada do que ter as duas mãos e ires para o inferno, para o fogo que não se apaga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, '.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Se teu pé te faz tropeçar, corta-o fora. Melhor será que entres na vida aleijado, a ter os dois pés, e seres lançado no inferno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, '.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Se teu olho te causar tropeço, arranca-o. Melhor será que entres no Reino de Deus com um olho do que ter os dois olhos, e seres lançado no inferno,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'onde os vermes nunca morrem, e o fogo nunca se apaga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Porque cada um será salgado com fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'O sal é bom, mas se o sal tiver perdido o sabor, como podeis fazê-lo salgar novamente? Tende sal em vós mesmos, e vivei em paz uns com os outros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Jesus deixou aquele lugar e foi para a região da Judeia, para além do rio Jordão; e as multidões vieram a Ele novamente. Ele os ensinava, como tinha por costume.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Os fariseus se aproximaram e para testá-Lo perguntaram: \"É lícito ao marido divorciar-se de sua esposa?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Ele respondeu: \"O que vos ordenou Moisés?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Eles disseram: \"Moisés permitiu ao homem escrever uma certidão de divórcio e, então, repudiar a esposa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Jesus, então, lhes disse: \"Foi por causa de vossos corações endurecidos que Moisés escreveu essa lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Mas, desde o início da criação, \'Deus os fez macho e fêmea’.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, '‘Por esse motivo o homem deixará seu pai e sua mãe e se unirá à sua esposa');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'e os dois se tornarão uma única carne. Então já não são dois, mas uma única carne\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Portanto, o que Deus uniu, não separe o homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Quando eles estavam em casa, os discípulos mais uma vez Lhe perguntaram sobre isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Ele disse-lhes: \"Todo aquele que repudiar sua mulher e se casar com outra, comete adultério.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Se ela se divorciar de seu marido e se casar com outro homem, ela comete adultério\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Traziam-Lhe suas crianças para que pudesse tocá-las, mas os discípulos os repreendiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Quando Jesus viu isto, ficou indignado, e disse-lhes: \"Deixai as crianças virem até Mim e não as proibais, pois o reino de Deus pertence aos que são semelhantes a elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Verdadeiramente vos digo: Todo aquele que não receber o reino de Deus como uma criança, de modo algum entrará nele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Então, Ele tomou as crianças em Seus braços e as abençoou impondo as mãos sobre elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Quando Ele continuou Seu caminho, um homem veio correndo, ajoelhou-se diante Dele e perguntou: \"Bom Mestre, o que farei para herdar a vida eterna?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'E Jesus lhe respondeu: \"Por que Me chamas bom? Ninguém é bom, exceto Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Tu conheces os mandamentos: \'Não matarás, não cometerás adultério, não roubarás, não darás falso testemunho, não defraudarás, honrarás teu pai e tua mãe\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Disse o homem: \"Mestre, todas essas coisas tenho obedecido desde quando era jovem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Jesus olhou para ele e o amou, e disse-lhe: \"Uma coisa te falta; vai, vende tudo o que tens e dá-o aos pobres, e terás um tesouro no céu. Então, vem e segue-Me\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Mas o homem, desanimado com esta palavra, retirou-se triste porque tinha muitos bens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Jesus olhou em volta e disse aos Seus discípulos: \"Como é difícil para os ricos entrar no reino de Deus!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Os discípulos estavam admirados com Suas palavras. Mas, Jesus disse-lhes outra vez: \"Filhos, como é difícil entrar no reino de Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'É mais fácil um camelo passar pelo buraco de uma agulha, do que um rico entrar no Reino de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Eles estavam perplexos e diziam uns aos outros: \"Então, quem pode ser salvo?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Jesus olhou para eles e disse: \"Para os homens é impossível, mas não para Deus. Porque todas as coisas são possíveis para Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Pedro começou a dizer-Lhe: \"Eis que nós deixamos tudo para trás e Te seguimos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jesus respondeu: \"Verdadeiramente vos digo, não há quem tenha deixado casa, irmãos, irmãs, mãe, pai, filhos ou terras por Minha causa e pelo Evangelho');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'que não receba cem vezes mais, agora neste mundo, casas, irmãos, irmãs, mães, filhos, terras, com perseguições; e no mundo que virá, vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Mas muitos que são primeiros serão últimos, e os últimos serão primeiros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Eles estavam no caminho, subindo para Jerusalém, e Jesus ia à frente deles. Os que O seguiam estavam assustados e tinham medo. Jesus chamou os doze à parte novamente, e começou a dizer-lhes o que aconteceria a Ele em breve:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, '\"Eis que estamos subindo para Jerusalém e o Filho do Homem será entregue aos chefes dos sacerdotes e aos escribas. Eles O condenarão à morte e O entregarão aos gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'Zombarão Dele, cuspirão Nele, O açoitarão e O matarão. Mas depois de três dias, Ele ressuscitará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Tiago e João, filhos de Zebedeu, vieram até Ele e disseram: \"Mestre, queremos que atendas o pedido que Te faremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Ele lhes disse: \"Que quereis que Eu vos faça?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Eles responderam: \"Permite-nos sentar com o Senhor em Sua glória, um à Tua direita e outro à Tua esquerda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Mas Jesus lhes respondeu: \"Não sabeis o que estais pedindo. Vós podeis beber do cálice do qual beberei, ou suportar o batismo com o qual serei batizado?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Eles responderam-Lhe: \"Nós podemos\". Disse-lhes Jesus: \"Do cálice que Eu beber, vós bebereis. E do batismo que Eu sou batizado, vós também sereis batizados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Mas não cabe a Mim conceder quem se assenta à Minha direita ou à Minha esquerda, mas é para aqueles a quem isso foi preparado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Quando os outros dez discípulos ouviram sobre isso, ficaram indignados com Tiago e João.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Jesus chamou-os para Si e disse: \"Vós sabeis que aqueles que são considerados governantes dos gentios os dominam, e os seus altos oficiais exercem autoridade sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Mas não deve ser dessa forma entre vós. Aquele que deseja tornar-se grande entre vós, deve ser o vosso servo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'e aquele que deseja ser o primeiro entre vós, deve ser escravo de todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Pois o Filho do Homem não veio para ser servido, mas para servir e dar a Sua vida em resgate de muitos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'E vieram para Jericó. Saindo Jesus de Jericó com os Seus discípulos e uma grande multidão, um homem chamado Bartimeu, filho de Timeu, um mendigo cego, estava sentado à beira da estrada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Ouvindo ele que era Jesus, O Nazareno, que estava chegando, começou a gritar e a dizer: \"Jesus, Filho de Davi, tem compaixão de mim!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Muitos o censuravam e diziam para que se calasse. Mas ele gritava ainda mais: \"Filho de Davi, tem compaixão de mim!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Jesus parou e ordenou-lhes que o chamassem. Então chamaram o cego, dizendo: \"Coragem! Levanta! Ele te chama\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Ele lançou fora a sua capa, levantou-se em um salto e veio a Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Jesus, respondendo-lhe, disse: \"O que queres que Eu te faça?\". O cego Lhe disse: \"Rabi, que eu recupere minha visão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Jesus disse: \"Vai, a tua fé te curou\". Imediatamente, ele recebeu sua visão e O seguia pelo caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Quando se aproximavam de Jerusalém, perto de Betfagé e Betânia, no Monte das Oliveiras, Jesus enviou dois de Seus discípulos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'e disse-lhes: \"Ide ao povoado que está diante de vós. Logo que entrardes nele, encontrareis um jumentinho que nunca foi montado. Desatai-o e trazei-o.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Se alguém vos disser: \'Por que estais fazendo isso?\', respondei: \'O Senhor precisa dele e logo o devolverá para cá\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Eles foram e encontraram um jumentinho amarrado a um portão, do lado de fora na rua e o desamarraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Algumas pessoas estavam ali e lhes perguntaram: \"O que fazeis desamarrando o jumentinho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Eles responderam conforme Jesus havia lhes dito, e as pessoas os deixaram ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Os dois discípulos levaram a Jesus o jumentinho, puseram suas vestes sobre ele, e Jesus montou nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Muitas pessoas estendiam suas vestes no caminho e outras estendiam ramos que haviam cortado dos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Os que iam adiante Dele e os que O seguiam clamavam: \"Hosana! Bendito O que vem em nome do Senhor!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Bendito seja o reino que vem de nosso pai Davi! Hosana nas alturas!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Então Jesus entrou em Jerusalém, dirigiu-se ao templo e observou tudo ao redor. E, sendo tarde da noite, partiu para Betânia com os doze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'No dia seguinte, quando retornaram de Betânia, teve fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'E vendo uma figueira que mostrava suas folhas a uma certa distância, foi ver se poderia achar nela algum fruto. Chegando perto dela, não achou nada além de folhas, pois não era estação de figos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Ele disse à figueira: \"Ninguém jamais comerá um fruto teu novamente\". E os discípulos Dele ouviram isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'E vieram para Jerusalém. E entrando no templo, Jesus começou a expulsar os que ali vendiam e compravam. Derrubou as mesas dos cambistas e as cadeiras dos que vendiam pombas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'E não permitiu que ninguém atravessasse o templo carregando qualquer coisa que pudesse ser vendida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Ele lhes ensinava, dizendo: \"Não está escrito: \'A Minha casa será chamada casa de oração para todas as nações?\' Mas vós tendes feito dela um covil de ladrões\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Os chefes dos sacerdotes e os escribas ouviram o que Ele disse e procuravam uma maneira para matá-Lo. Pois O temiam, visto que toda a multidão estava impressionada com os Seus ensinamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Ao entardecer, eles saíram da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'E pela manhã, enquanto caminhavam, viram que a figueira estava seca até a raiz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Então Pedro, lembrando-se, disse-Lhe: \"Rabi, eis que a figueira que Tu amaldiçoaste secou-se\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Jesus lhes respondeu: \"Tende fé em Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Verdadeiramente vos digo que qualquer um dentre vós que disser a este monte: \'Ergue-te e lança-te ao mar\', e não duvidar no seu coração, mas crer que o que foi dito acontecerá, assim Deus o fará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Portanto Eu vos digo que tudo que pedirdes em oração, crede que já o recebestes, e vos será concedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Quando estiverdes orando, vós deveis perdoar tudo que tendes contra alguém, para que vosso Pai que está nos céus também perdoe as vossas transgressões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, '.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Eles retornaram para Jerusalém. Enquanto Jesus andava pelo templo, os chefes dos sacerdotes, os escribas e os anciãos se dirigiram a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'E Lhe perguntaram: \"Com que autoridade fazes essas coisas? E quem Te deu autoridade para realizá-las?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Jesus lhes disse: \"Vou lhes fazer uma pergunta, respondei-me e lhes direi com que autoridade faço essas coisas:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'O batismo de João era do céu ou dos homens? Respondei-me\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Eles discutiam entre si, argumentavam e diziam: \"Se dissermos: \'Do céu\', ele dirá: \'Então por que não crestes nele?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Mas se dissermos: \'Dos homens\'...\" Eles temiam o povo, pois todos consideravam que João era profeta de fato.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Então responderam a Jesus: \"Não sabemos\". E Jesus lhes disse: \"Tampouco Eu lhes direi com que autoridade faço essas coisas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Então Jesus começou a ensiná-los por parábolas, dizendo: \"Um homem plantou uma vinha, colocou um cercado ao redor, cavou um poço para prensar as uvas, e construiu uma torre. Então arrendou a vinha para alguns lavradores e saiu de viagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'No tempo certo da colheita, ele enviou um servo até os lavradores para receber deles do fruto da vinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Mas eles o pegaram, o espancaram e o mandaram de volta sem nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Mais uma vez, ele mandou outro servo, e lhe feriram na cabeça e o humilharam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Ele mandou ainda outro, e a este mataram. Eles trataram a muitos outros servos da mesma maneira, espancando alguns e matando outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'E restava-lhe ainda um, seu filho amado, o último que lhes fora enviado. Ele disse: \'Eles respeitarão o meu filho\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Mas os lavradores disseram entre si: \'Esse é o herdeiro, vamos matá-lo e a herança será nossa\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Eles o agarraram, o mataram e o jogaram para fora da vinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Portanto, que fará então o dono da vinha? Ele virá, destruirá os lavradores e dará a vinha para outras pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Acaso não lestes esta Escritura? \'A pedra que os construtores rejeitaram veio a ser a angular.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Isso vem do Senhor, e é maravilha aos nossos olhos’\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Eles procuraram um meio de prender Jesus, mas temiam a multidão, pois sabiam que Ele havia contado essa parábola contra eles. Então O deixaram e foram embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'E eles Lhe enviaram alguns dos fariseus e dos herodianos para que O apanhassem em alguma palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Quando chegaram, disseram-Lhe: \"Mestre, sabemos que és verdadeiro e não Te importas com a opinião de ninguém, porque não julgas pela aparência dos homens. Verdadeiramente ensinas o caminho de Deus. É certo pagarmos impostos a César ou não? Devemos pagar ou não?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Mas Jesus conhecia a hipocrisia deles e disse-lhes: \"Por que Me testais? Trazei-Me um denário para que Eu o veja\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Eles Lhe trouxeram um. Então, Jesus perguntou: \"De quem é esta imagem e inscrição?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Eles Lhe responderam: \"De César\". Jesus disse: \"Dai a César o que é de Cesar e a Deus, o que é de Deus\". E ficaram maravilhados com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Então os saduceus, que dizem não haver ressurreição, vieram até Ele e perguntaram-Lhe, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '\"Mestre, Moisés nos deixou escrito que: \'Se o irmão de um homem morrer e deixar uma esposa sem filhos, o irmão deve casar-se com a viúva e ter filhos para seu irmão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Havia sete irmãos; o primeiro teve esposa e depois morreu, sem deixar filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Então, o segundo a tomou por esposa e morreu, sem deixar filhos. E com o terceiro de igual modo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'E os sete não deixaram filhos. Depois de todos, a mulher também morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Na ressurreição, quando ressuscitarem, de quem ela será esposa? Já que os sete irmãos a tiveram como esposa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Respondeu-lhes Jesus: \"Não é esta a razão pela qual estais enganados, porque não conheceis as Escrituras nem o poder de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Pois quando ressuscitarem dentre os mortos, não se casam nem se dão em casamento, mas são como os anjos nos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Mas, quanto aos mortos que são ressuscitados, não lestes no livro de Moisés, no relato sobre a sarça, como Deus falou com ele e disse: \'Eu sou o Deus de Abraão, o Deus de Isaque e o Deus de Jacó?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Ele não é Deus de mortos, mas de vivos. Grande é o vosso erro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Um dos escribas veio e ouviu a discussão, ele viu que Jesus lhes respondeu bem. E perguntou-Lhe: \"Qual mandamento é o mais importante de todos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Respondeu Jesus: \"O mais importante é este: \'Ouve, Israel, o Senhor nosso Deus é o único Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Amarás, pois, o Senhor teu Deus, com todo o teu coração, com toda a tua alma, com todo o teu entendimento, e com todas as tuas forças\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'O segundo mandamento é este: \'Ama o teu próximo como a ti mesmo\'. Mandamento maior do que esses não existe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Então o escriba lhe disse: \"Muito bem, Mestre! Verdadeiramente falaste que Deus é um só, e que não há outro exceto Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'Amá-Lo com todo o coração, com todo o entendimento e com todas as forças, e amar ao próximo como a si mesmo, é mais importante do que todos os sacrifícios e holocaustos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Quando Jesus viu que ele deu uma resposta sábia, disse-lhe: \"Tu não estás longe do Reino de Deus\". Depois disto, ninguém mais se atreveu a questionar Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'E, enquanto ensinava no templo, Jesus respondeu-lhes, dizendo: \"Como dizem os escribas que o Cristo é filho de Davi?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Davi mesmo disse pelo Espírito Santo: \'O Senhor disse ao meu Senhor: Senta-te à Minha direita, até que Eu faça dos teus inimigos como escabelo debaixo dos teus pés\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'O próprio Davi chama o Cristo de \'Senhor\', então, como pode ser filho dele?\". A grande multidão O ouvia com alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Em seu ensinamento, Jesus dizia: \"Cuidado com os escribas, que desejam andar com longas túnicas, receber saudações nas praças,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'os lugares principais nas sinagogas e os lugares de honra nos banquetes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Eles também devoram as casas das viúvas e, para o justificar, fazem longas orações. Estes receberão maior condenação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Então Jesus sentou-Se perto de uma caixa de ofertas na área do templo. Ele estava olhando as pessoas enquanto lançavam seu dinheiro na caixa. Muitas pessoas ricas lançavam ali grandes quantias de dinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Então, uma pobre viúva chegou e colocou na caixa duas moedas, que valem um quadrante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Jesus chamou os Seus discípulos e disse-lhes: \"Verdadeiramente vos digo: Esta viúva pobre colocou ali mais do que todos aqueles que ofertaram na caixa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Todos eles deram do que lhes era abundante, mas esta viúva, de sua pobreza, colocou todo o dinheiro que tinha para viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Enquanto Jesus saía do templo, um de Seus discípulos disse-Lhe: “Mestre, olha que lindas pedras e construções!”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Jesus respondeu: \"Vês estas grandes construções? Não será deixada pedra sobre pedra que não seja derrubada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'E, assentando-se Ele no Monte das Oliveiras do lado oposto do templo, Pedro, Tiago, João e André Lhe perguntaram em particular:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '“Dize-nos, quando essas coisas acontecerão? Qual será o sinal quando todas essas coisas estiverem prestes a acontecer?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Jesus começou a dizer-lhes: “Sede cautelosos para que ninguém vos engane.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Muitos virão em Meu nome e dirão: ‘Eu sou o Cristo’, e enganarão a muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'E quando ouvirdes de guerras e rumores de guerras, não vos preocupeis; essas coisas devem acontecer, mas ainda não será o fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Porque nação se erguerá contra nação, e reino contra reino. Haverá terremotos em muitos lugares, e fome. Esse é o início das dores de parto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Ficai alertas. Eles vos entregarão às assembleias, e sereis espancados nas sinagogas. Vós estareis diante de governadores e reis por Minha causa, como um testemunho para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Mas é preciso que primeiro o evangelho seja proclamado a todas as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Quando vos prenderem e levarem a julgamento, não preocupeis com o que deveis dizer. Porque naquela hora, o que deveis dizer lhes será dado; não sereis vós que falareis, mas o Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Irmão entregará irmão à morte, e pai a seu filho. Filhos se levantarão contra seus pais e causarão as suas mortes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Vós sereis odiados por todos por causa do Meu nome. Mas aquele que suportar até o fim, esse será salvo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Quando virdes a abominação da desolação no lugar onde não devia estar (que o leitor entenda), aqueles que estão na Judeia fujam para as montanhas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'aquele que estiver no telhado não desça para casa, nem pegue qualquer coisa nela,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'aquele que estiver no campo não retorne para pegar sua capa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Mas ai das que estiverem grávidas e das que estiverem amamentando naqueles dias!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Orai para que isso não ocorra no inverno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Porque haverá grande tribulação, tão grande como nunca houve desde o início, quando Deus criou o mundo até agora, e nunca mais haverá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Se o Senhor não tivesse encurtado os dias, ninguém seria salvo. Mas por causa dos eleitos, aqueles que Ele escolheu, abreviou assim os dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Então, se alguém vos disser: ‘Eis o Cristo aqui!\" Ou: ‘Eis que lá está Ele!’, não acrediteis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Porque falsos Cristos e falsos profetas aparecerão e farão sinais e maravilhas, de modo a enganar, se possível, até os eleitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Ficai alertas! Eis que vos falei todas estas coisas antes delas acontecerem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Todavia, depois da tribulação daqueles dias, o sol escurecerá, a lua não dará a sua luz,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'as estrelas cairão do céu, e os poderes que estão nos céus serão sacudidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Então, verão o Filho do Homem vir nas nuvens com imenso poder e glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Ele enviará Seus anjos e juntará Seus eleitos dos quatro ventos, dos confins da terra aos confins do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Aprendei a lição da figueira. Assim que o galho se renova e mostra suas folhas, sabeis que o verão está perto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'E também, quando virdes essas coisas acontecendo, sabei que Ele está perto, às portas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Verdadeiramente Eu vos digo, esta geração não passará até que todas essas coisas aconteçam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Céu e terra passarão, mas Minhas palavras nunca passarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Mas a respeito daquele dia ou hora, ninguém sabe, nem mesmo os anjos no céu, nem o Filho, somente o Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Ficai alertas! Vigiai e orai, porque não sabeis quando será o tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'É como um homem que vai para uma viagem: ele deixa sua casa e coloca seus servos no comando da casa, cada um com seu trabalho. E ele ordena ao vigia que fique acordado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Por isso vigiai! Porque não sabeis quando o dono da casa voltará, se à tarde, à meia noite, quando o galo cantar, ou pela manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'Se Ele vier de repente, que Ele não vos encontre dormindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'O que Eu vos digo, digo a todos: Vigiai!”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Em dois dias seria a Páscoa e a Festa dos Pães sem Fermento. E os principais sacerdotes e os escribas andavam procurando um modo para prendê-lo em segredo e matá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Pois diziam: \"Não durante a Páscoa, para que um tumulto não surja entre o povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Estava Jesus em Betânia na casa de Simão, o leproso, e enquanto ele se reclinava à mesa, aproximou-se uma mulher com um vaso de alabastro que continha um líquido muito precioso, nardo puro. Ela quebrou o vaso e derramou sobre a cabeça de Jesus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'mas alguns se indignaram. Eles diziam entre si: \"Por que esse desperdício de perfume?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Esse perfume poderia ser vendido por mais de trezentos denários e assim ser dado aos pobres”. E a repreendiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Mas Jesus disse: \"Deixai-a em paz. Por que a perturbais? Ela fez uma bela coisa por Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'No meio de vós sempre haverá pobres e sempre que quiserdes podeis fazer o bem a eles, porém, não Me tereis sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Ela fez o que podia, ungiu o Meu corpo antecipadamente para o sepultamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Verdadeiramente vos digo, onde quer que o Evangelho for pregado no mundo todo, o que essa mulher fez será contado, em memória dela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Então Judas Iscariotes, um dos Doze, foi até os principais sacerdotes para entregar Jesus a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Quando os sacerdotes ouviram isso, alegraram-se e prometeram dar-lhe dinheiro. E ele começou a procurar uma oportunidade de entregar-lhes Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'No primeiro dia da Festa dos Pães sem Fermento, quando eles sacrificavam o cordeiro da Páscoa, Seus discípulos disseram-lhe: \"Onde desejas que preparemos a refeição da Páscoa?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Ele enviou dois dos Seus discípulos e disse-lhes: \"Ide para a cidade e um homem carregando uma jarra de água vos encontrará. Segui-o.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'E onde quer que ele entrar, segui-o e dizei ao dono da casa: \'O Mestre diz: Onde fica a sala em que comerei a refeição da Páscoa com Meus discípulos?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'E ele vos mostrará uma grande sala mobiliada no andar superior que está pronta. Fazei lá nossos preparativos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Os discípulos saíram e foram até a cidade; encontraram tudo como Ele havia lhes dito e prepararam a refeição da Páscoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Quando já era noite, Ele veio com os doze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Enquanto estavam reclinados à mesa e comendo, Jesus disse: \"Verdadeiramente Eu vos digo, um de vós, que está comendo Comigo, irá Me trair\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Todos se entristeceram e um a um disseram-Lhe: \"Acaso sou eu?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Jesus, respondendo, disse-lhes: \"É um dos doze, aquele que agora mergulha o pão Comigo na tigela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Porque o Filho do homem vai conforme as escrituras dizem sobre Ele; mas ai daquele que O trair! Melhor seria para ele se não tivesse nascido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Enquanto comiam, Jesus pegou o pão, abençoou-o, repartiu-o e lhes deu. Então disse: \"Tomai, este é o Meu corpo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Ele pegou um cálice, agradeceu, deu-lhes e todos beberam dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Então disse-lhes: \"Este é o Meu sangue da aliança, o sangue que é derramado em favor de muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Em verdade vos digo, Eu não beberei novamente do fruto da vinha até o dia em que Eu beber o vinho novo no Reino de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Após cantarem um hino, foram para o Monte das Oliveiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Jesus lhes disse: \"Vós todos Me abandonareis, porque está escrito: \'Ferirei o Pastor e todas as ovelhas se espalharão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Mas depois da Minha ressurreição, Eu irei à vossa frente para a Galileia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Pedro lhe disse: \"Mesmo que todos Te abandonem, eu não Te abandonarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Jesus disse a ele: \"Verdadeiramente Eu digo que, esta noite, antes que o galo cante duas vezes, você Me negará três vezes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Mas Pedro disse: \"Mesmo que eu morra Contigo, não Te negarei\". Todos eles fizeram a mesma promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Eles foram para um lugar chamado Getsêmani, e Jesus disse aos Seus discípulos: \"Sentai aqui enquanto Eu oro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Ele tomou Pedro, Tiago e João, então começou a ficar angustiado e em extrema aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Jesus disse-lhes: \"Minha alma está profundamente triste, a ponto de morrer. Permanecei aqui e vigiai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Jesus foi um pouco mais longe, caiu em terra, e orava, para que, se fosse possível, essa hora passasse Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Ele disse: \"Aba, Pai, todas as coisas são possíveis para Ti, tira este cálice de Mim. Porém, que não seja a Minha vontade, mas a Tua\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Ele retornou, encontrou-os dormindo, e disse a Pedro: \"Simão, tu estás dormindo? Não podes vigiar nem por uma hora?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Vigiai e orai para que não entreis em tentação. O espírito está preparado, mas a carne é fraca\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Novamente Ele Se distanciou e orou, e usou as mesmas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Outra vez Se aproximou Jesus dos discípulos e os encontrou dormindo; seus olhos estavam muito pesados e eles não sabiam o que Lhe dizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Ele veio pela terceira vez e disse-lhes: \"Ainda estais dormindo e descansando? Basta! A hora chegou. Eis que o Filho do Homem está sendo entregue às mãos dos pecadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Levantai-vos, vamos! Eis que aquele que está Me traindo está próximo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Imediatamente, enquanto Ele ainda falava, Judas, um dos doze, chegou, e uma grande multidão estava com ele; armada de espadas e pedaços de pau, da parte do principais sacerdotes, escribas e anciãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'O traidor deu-lhes um sinal, dizendo: \"É Aquele que eu beijar\". Prendei-O e levai-O sob guarda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Quando Judas chegou, imediatamente veio até Jesus e Lhe disse: \"Rabi!\" e ele O beijou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Então eles O pegaram e prenderam-No.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Mas um dos que ali estavam puxou sua espada, feriu o servo do sumo sacerdote e cortou fora sua orelha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Jesus lhes disse: \"Saístes para Me prender como contra um ladrão, com espadas e pedaços de pau?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Quando Eu estava convosco e ensinava diariamente no templo, não Me prendestes. Mas isso foi feito para que as Escrituras fossem cumpridas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'E todos os que estavam com Jesus O deixaram e fugiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Um jovem O seguia, o qual estava vestindo apenas um lençol de linho que estava envolto nele; eles o agarraram, mas');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'o jovem deixou para trás o lençol e fugiu deles nu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Levaram Jesus ao sumo sacerdote. Reuniram-se todos os principais sacerdotes, anciãos e escribas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Nessa hora, Pedro acompanhava tudo a distância, até o interior do pátio do sumo sacerdote. Ele se sentou entre os guardas, que estavam próximos ao fogo, para se manter aquecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Os principais sacerdotes e todo o Sinédrio procuravam testemunhos contra Jesus, para que pudessem matá-Lo. Mas eles não encontraram,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'pois muitos trouxeram falsos testemunhos contra Ele, mas mesmo esses testemunhos eram divergentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Alguns se levantaram e trouxeram falso testemunho contra Ele; eles diziam:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '\"Nós O ouvimos dizer: \'Eu destruirei esse templo feito por mãos humanas e em três dias eu construirei outro, não feito por mãos humanas\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Ainda assim seus testemunhos divergiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Então, o sumo sacerdote se levantou no meio deles e perguntou a Jesus: \"Tu não respondes nada? O que esses homens depõem contra Ti?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Mas Ele estava em silêncio e não respondia. Outra vez o sumo sacerdote perguntou: \"Tu és o Cristo, o Filho do Deus Bendito?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Jesus disse: \"Eu sou. E vereis O Filho do Homem sentado à direita do Poderoso e vindo com as nuvens do céu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Diante disso, o sumo sacerdote rasgou suas roupas e disse: \"Ainda precisamos de testemunhas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Vós ouvistes a blasfêmia. Qual é a vossa decisão?\". E todos condenaram a Jesus como merecedor de morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Alguns começaram a cuspir Nele e cobrir o Seu rosto, bater Nele e dizer: \"Profetiza!\" Os guardas O levaram e bateram Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Estando Pedro na parte de baixo, no pátio, uma das servas do sumo sacerdote veio até ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'Ela, vendo Pedro próximo ao fogo, para se manter aquecido, olhou bem para ele e disse: \"Tu também estavas com o Nazareno, Jesus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Mas ele negou, dizendo: \"Eu nem sei nem entendo o que tu estás falando\". Então ele saiu para o pátio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Mas lá, a criada o viu e começou a dizer de novo aos que ali estavam: \"Esse homem é um deles!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Mas ele negou isso novamente. Logo, os que lá se encontravam diziam a Pedro: \"Com certeza és um deles, pois também és um galileu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Mas ele começou a amaldiçoar e a jurar: \"Eu não conheço esse Homem de quem falais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Então, imediatamente, o galo cantou pela segunda vez. Pedro então se lembrou das palavras que Jesus havia lhe dito: \"Antes que o galo cante duas vezes, três vezes Me negarás\". Ele se irrompeu em tristeza e começou a chorar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'De manhã cedo, os principais sacerdotes se encontraram com os anciãos e escribas e todo o Sinédrio. Eles amarraram Jesus, levaram-No e O entregaram a Pilatos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Pilatos Lhe perguntou: \"Tu és o Rei dos Judeus?\" Ele respondeu: \"Tu o dizes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Os principais sacerdotes apresentavam muitas acusações contra Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Pilatos perguntou novamente: \"Tu não respondes nada? Vês quantas acusações eles têm contra Ti?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Mas Jesus não mais respondeu a Pilatos, e isso o deixou impressionado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Na época da festa, era de costume Pilatos soltar um prisioneiro qualquer que eles escolhessem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Juntamente com os rebeldes na prisão, entre os assassinos presos por terem tomado parte em uma rebelião, havia um homem chamado Barrabás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'A multidão veio até Pilatos e começou a pedir-lhe para fazer o que era de costume.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'E Pilatos respondeu-lhes: \"Quereis que eu solte o Rei dos Judeus?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Pois ele sabia que era por inveja que os principais sacerdotes tinham entregado Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Mas os principais sacerdotes incitaram a multidão a clamar que, no lugar Dele, Barrabás fosse solto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Pilatos tornou a responder-lhes: \"O que então eu deveria fazer com o Rei dos Judeus?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Eles gritaram novamente: \"Crucifica-O!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Pilatos disse-lhes: \"O que Ele fez de errado?\". Mas eles gritavam mais e mais: \"Crucifica-O!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Pilatos, querendo agradar a multidão, entregou-lhes Barrabás. Ele entregou Jesus para que, depois de açoitado, fosse crucificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Os soldados O levaram para dentro do Palácio, que é o Pretório, e chamaram todo o destacamento dos soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Vestiram-No com um manto púrpura, trançaram uma coroa de espinhos e a colocaram em Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'Começaram, então, a saudá-Lo dizendo: \"Viva o Rei dos Judeus!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Eles bateram em Sua cabeça com um bordão e cuspiram Nele e, de joelhos, prestaram-Lhe homenagens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Depois de zombarem Dele, despiram-Lhe o manto púrpura e O vestiram com Suas próprias roupas, e levaram-No para fora, a fim de ser crucificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Eles obrigaram um transeunte, que vinha do campo, a carregar a cruz de Jesus. Seu nome era Simão de Cirene (pai de Alexandre e Rufo).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Os soldados levaram Jesus a um lugar chamado Gólgota, que quer dizer Lugar da Caveira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'E ofereceram-Lhe vinho misturado com mirra, mas Ele não bebeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Então O crucificaram e dividiram Suas roupas, lançando sortes para determinar que peça cada soldado pegaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Era a hora terceira quando O crucificaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Em uma placa, eles escreveram a acusação: \"O REI DOS JUDEUS\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Com Ele crucificaram dois ladrões, um à sua direita e o outro à sua esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, '');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Aqueles que passavam O insultavam, balançando suas cabeças e dizendo: \"Ah! Tu és o que destruiria o templo e o reconstruiria em três dias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'salva a Ti mesmo e desce da cruz!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Do mesmo modo, os principais sacerdotes zombavam Dele entre si, com os escribas, e diziam: \"Ele salvou os outros, mas não consegue salvar a Si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Que o Cristo, o Rei de Israel, desça agora da cruz e assim possamos ver e acreditar\". E os que com Ele foram crucificados também O insultavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Na hora sexta, a escuridão veio sobre toda a terra até a hora nona.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Na hora nona, Jesus bradou em alta voz: \"Eloí, Eloí, lamá sabactani?\", que significa, \"Deus meu, Deus meu, por que Me desamparaste?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Alguns dos que estavam ali ouviram e disseram: \"Eis que Ele está chamando por Elias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Alguém correu, colocou vinagre em uma esponja, a pôs em uma vara e O deu para beber. O homem disse: \"Vejamos se Elias vem tirá-Lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Então Jesus bradou em alta voz e morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'E o véu do templo se partiu em dois, de cima a baixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'E o centurião que estava diante Dele, vendo-O expirar desse modo, disse: \"Verdadeiramente este Homem era o Filho de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Havia também mulheres que observavam à distância. Entre elas estavam Maria Madalena, Maria (a mãe de Tiago, o mais novo, e de José) e Salomé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'Quando Ele estava na Galileia, elas O seguiam e O serviam. Muitas outras mulheres também subiram com Ele para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Ao cair da tarde, por ser o Dia de Preparação, isto é, a véspera do Sabbath,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'José de Arimateia foi até lá. Ele era um respeitado membro do Conselho, que esperava o Reino de Deus. Ele corajosamente foi até Pilatos e pediu pelo corpo de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilatos admirou-se de que Jesus já estivesse morto; então chamou o centurião e lhe perguntou se Jesus morrera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Quando Pilatos ouviu do centurião que Ele estava morto, cedeu o corpo a José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'José tinha comprado um lençol de linho. Ele desceu Jesus da cruz, envolveu-O com o lençol, e colocou-O em um sepulcro talhado na rocha. Então, rolou uma pedra sobre a entrada do sepulcro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'E Maria Madalena e Maria, a mãe de José, viram o lugar onde Jesus fora sepultado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Ao final do Sabbath, Maria Madalena, Maria, a mãe de Tiago e Salomé compraram especiarias aromáticas para ir ungir o corpo de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'No primeiro dia da semana, bem cedo, ao nascer do sol, elas foram até o sepulcro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Elas se perguntavam umas às outras: \"Quem rolará para nós a pedra do sepulcro?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Quando ergueram os olhos, viram que alguém havia rolado a pedra, que era muito grande.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Entrando no sepulcro, viram um jovem vestido com manto branco, sentado ao lado direito, e ficaram atônitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Ele lhes disse: \"Não temais. Procurais por Jesus, o Nazareno, que foi crucificado. Ele ressuscitou! Não está aqui. Vede o lugar onde O puseram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Mas ide dizer a Seus discípulos e a Pedro que Jesus vai adiante de vós para a Galileia. Lá O vereis, como Ele lhes havia dito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Elas saíram e correram do sepulcro, estavam tremendo e assombradas. Não disseram nada a ninguém, pois tinham muito medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Tendo ressuscitado na manhã do primeiro dia da semana, Jesus apareceu primeiro a Maria Madalena, de quem expulsara sete demônios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Ela saiu e contou o que tinha visto a todos que estiveram com Ele, enquanto esses lamentavam e choravam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Eles ouviram que Jesus estava vivo e que fora visto por ela, mas não creram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Depois destas coisas, Ele apareceu em uma forma diferente para mais dois deles, enquanto estavam a caminho do campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Eles foram contar ao resto dos discípulos, mas estes não creram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Depois, Jesus apareceu aos onze, enquanto eles se reclinavam à mesa, e os censurou pela incredulidade e dureza de coração, por não terem crido naqueles que O viram depois de ter ressuscitado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Então, disse-lhes: \"Ide pelo mundo todo, pregai o Evangelho a toda criatura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Quem crer e for batizado será salvo, e o que não crer será condenado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Estes sinais acompanharão aqueles que creem: em Meu nome expulsarão demônios, falarão novas línguas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'pegarão serpentes com as mãos e se beberem algo venenoso, isso não os ferirá; imporão as mãos sobre os doentes e eles serão curados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Depois do Senhor Jesus ter falado com eles, foi levado aos céus e se assentou à direita de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Os discípulos saíram e pregaram por toda parte, enquanto o Senhor trabalhava com eles e confirmava a palavra através dos milagrosos sinais que os seguiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Uma vez que muitos tentaram colocar em ordem uma narrativa sobre os acontecimentos que se realizaram entre nós -');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'conforme nos foi transmitido pelos que desde o começo foram testemunhas oculares e servos da mensagem -,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'então pareceu-me bom também, investigando cuidadosamente o curso de todas essas coisas desde o começo, escrevê-las em sua ordem correta, excelentíssimo Teófilo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'para que conheças plenamente a verdade sobre as coisas que te foram ensinadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Nos dias de Herodes, rei da Judeia, havia um certo sacerdote, chamado Zacarias, da ordem de Abias. Sua mulher era da linhagem de Arão e chamava-se Isabel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Ambos eram justos diante de Deus, andando de modo irrepreensível em todos os mandamentos e exigências do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Mas eles não tinham filhos, porque Isabel era estéril, e também eram ambos muito velhos nesse tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Aconteceu que Zacarias estava na presença de Deus, cumprindo os seus deveres sacerdotais, conforme a sua linhagem;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'então ele foi escolhido por sorteio, segundo o costume do ofício sacerdotal, para entrar no templo do Senhor e queimar incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Toda a multidão estava orando do lado de fora no momento em que o incenso estava sendo queimado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Então um anjo do Senhor apareceu a ele, de pé, à direita do altar do incenso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Quando Zacarias o viu, ficou perturbado e o medo veio sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Mas o anjo disse-lhe: “Não temas, Zacarias, porque a tua oração foi ouvida. Tua esposa, Isabel, dará à luz um filho, e tu o chamarás João.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Tu terás alegria e satisfação, e muitas pessoas se regozijarão com o seu nascimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Pois ele será grande aos olhos do Senhor; não beberá vinho, nem bebida forte; e, ainda no ventre de sua mãe, ele será cheio do Espírito Santo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'e muitos dentre o povo de Israel se voltarão ao Senhor, seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Ele irá à frente do Senhor no espírito e poder de Elias, para voltar o coração dos pais aos seus filhos, e levar os desobedientes a andarem de acordo com a sabedoria dos justos. Ele fará isso a fim de formar um povo preparado para o Senhor”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Zacarias disse ao anjo: “Como posso ter certeza disso? Pois eu sou um homem velho e minha esposa é de idade avançada”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'O anjo respondeu: “Eu sou Gabriel, permaneço na presença de Deus e fui enviado para falar contigo e trazer-lhe essas boas novas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'E eis que ficarás mudo e não poderás falar até o dia em que isso suceder, porque não acreditaste em minhas palavras, que se cumprirão no momento certo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Enquanto as pessoas esperavam por Zacarias, elas se perguntavam por que ele estava há tanto tempo no templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Quando ele saiu, ele não podia falar com eles, por isso fez movimentos com as mãos para tentar explicar o que aconteceu. Então perceberam que ele teve uma visão enquanto estava lá dentro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Aconteceu que, quando os dias de seu serviço terminaram, ele voltou para sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Depois desses dias, sua esposa Isabel ficou grávida e se escondeu por cinco meses, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '\"Isso foi o que o Senhor fez por mim quando Ele me olhou com favor para tirar a minha vergonha diante das pessoas”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'No sexto mês de gestação, o anjo Gabriel foi enviado por Deus para uma cidade da Galileia, chamada Nazaré,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'a uma virgem que estava noiva de um homem chamado José. José era descendente de Davi, e o nome da virgem era Maria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'O anjo apareceu a ela e disse: “Saudações, tu que és grandemente favorecida! O Senhor é contigo!”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Mas ela ficou muito perturbada com essas palavras e se perguntou que tipo de saudação seria essa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'E o anjo falou para ela: “Não temas, Maria, pois foste agraciada por Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Eis que conceberás em teu ventre e darás à luz um filho. Tu lhe porás o nome de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Ele será grande, será chamado Filho do Altíssimo. O Senhor Deus Lhe dará o trono de Seu pai, Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'Ele reinará sobre a casa de Jacó para sempre, e Seu reinado jamais terá fim”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Maria disse ao anjo: “Como isso acontecerá, visto que sou virgem?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'O anjo respondeu e disse-lhe: “O Espírito Santo virá sobre ti, e o poder do Altíssimo te envolverá. Por isso, aquele que é Santo nascerá e será chamado O Filho de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Eis que Isabel, tua parente, também concebeu um filho na sua velhice. Ela que era chamada estéril está em seu sexto mês de gestação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Pois nada será impossível para Deus”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Maria disse: \"Eis aqui a serva do Senhor. Que isso seja feito em mim de acordo com a Sua palavra\". E o anjo a deixou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Naqueles dias, Maria partiu às pressas para uma região montanhosa, para uma cidade da Judeia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'E ela entrou na casa de Zacarias e saudou Isabel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Quando isso aconteceu, ouvindo Isabel a saudação de Maria, o bebê em seu ventre saltou, e Isabel ficou cheia do Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'Ela exclamou em alta voz e disse: “Tu és bendita entre todas as mulheres, e abençoado é o fruto do teu ventre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Como é possível que a mãe do meu Senhor venha me visitar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Assim que ouvi sua saudação, o bebê que carrego em meu ventre saltou de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'E bem-aventurada aquela que creu porque se cumprirão todas as coisas que lhe foram ditas pelo Senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Maria disse: “Minha alma exalta ao Senhor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'e o meu espírito muito se alegrou em Deus, meu Salvador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Pois Ele olhou para minha humilde condição de serva. A partir de agora, todas as gerações me chamarão bem-aventurada,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'porque o Poderoso fez grandes coisas por mim, e Seu nome é Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'Sua misericórdia estende-se de geração em geração sobre aqueles que O temem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Ele demonstrou força com seu braço, dispersou aqueles que eram orgulhosos nos pensamentos dos seus corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Derrubou os príncipes dos seus tronos e exaltou as pessoas humildes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Encheu de bens os famintos e despediu os ricos sem dar nada a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Ajudou a Israel, seu servo, em lembrança da Sua misericórdia');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, '- como Ele disse aos nossos pais - em favor de Abraão e sua descendência para sempre!”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Maria permaneceu com Isabel cerca de três meses e depois voltou para sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Quando chegou a hora de Isabel dar à luz seu bebê, ela teve um menino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Seus vizinhos e parentes ouviram que o Senhor multiplicou Sua misericórdia para com ela e se alegraram com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Então, aconteceu que, no oitavo dia, eles vieram para circuncidar o bebê. Eles queriam chamá-lo de Zacarias, como seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Mas sua mãe tomou a palavra e disse: “Não, ele se chamará João”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Disseram a ela: “Não há ninguém entre vossos parentes que é chamado por esse nome”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Eles gesticularam ao pai para descobrir como queria que ele fosse chamado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Seu pai pediu uma pequena tábua e escreveu: “Seu nome é João”. Todos ficaram admirados com isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Imediatamente, sua boca se abriu, sua língua se soltou, e ele começou a falar, louvando a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Então veio temor sobre todos os que viviam ao seu redor, e tudo o que aconteceu espalhou-se por toda a área das colinas da Judeia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Todos aqueles que ouviram isso, ficaram pasmos em seus corações, dizendo: “O que virá a ser esse menino?”. Pois a mão do Senhor estava sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Seu pai, Zacarias, estava cheio do Espírito Santo e profetizou, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '“Bendito seja o Senhor, o Deus de Israel, porque visitou e libertou o Seu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'Ele levantou para nós um chifre de salvação na casa de Davi, seu servo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'como prometera há muito tempo, através de Seus santos profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Ele nos trará salvação de nossos inimigos e da mão de todos os que nos odeiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Ele fará isso para mostrar a Sua misericórdia para com os nossos pais e lembrar-Se da Sua santa aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'Essa aliança é o juramento que Ele fez a Abraão, nosso pai,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'para nos libertar das mãos dos nossos inimigos e para que possamos servi-Lo sem medo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'em santidade e justiça, perante Ele, todos os nossos dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Sim, e tu, menino, serás chamado profeta do Altíssimo, porque tu irás à frente do Senhor, para preparar as pessoas para a Sua vinda,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'e fazer conhecida a salvação ao Seu povo através do perdão dos seus pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Isso acontecerá por causa da terna misericórdia do nosso Deus, por meio da qual a Aurora do alto virá até nós,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'para brilhar sobre aqueles que estão em trevas e na sombra da morte; Ele fará isso para guiar nossos passos no caminho da paz”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Então o menino cresceu e se fortaleceu em espírito. Ele viveu no deserto, até que apareceu publicamente ao povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Naqueles dias, o Imperador César Augusto enviou um decreto ordenando que houvesse um censo de todas as pessoas que viviam no mundo habitado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Isto foi feito, pela primeira vez, quando Quirino era o governador da Síria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Então, todos foram à sua cidade natal para serem registrados no censo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'José também partiu da cidade de Nazaré, na Galileia, para Belém, na Judeia, conhecida como cidade de Davi, pois ele era descendente do Rei Davi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'José foi com sua noiva Maria para se registrarem. Ela estava grávida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Aconteceu que, chegando em Belém, era o momento de Maria ter o Bebê.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Então ela deu à luz o seu filho, seu Primogênito, e ela O envolveu em panos. Depois, ela O colocou em uma manjedoura, pois não havia lugar para eles na hospedaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Naquela mesma região alguns pastores estavam no campo, cuidando de suas ovelhas à noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Um anjo do Senhor apareceu para eles e a glória do Senhor brilhava em torno deles; e todos ficaram tomados de grande temor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Então, o anjo lhes disse: \"Não temais, pois vos trago boas novas de grande alegria para todo o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Hoje, na cidade de Davi, vos nasceu o Salvador. Ele é Cristo, o Senhor!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Ireis reconhecê-Lo através deste sinal: Ele estará envolvido em panos e deitado em uma manjedoura\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'De repente, uma grande quantidade de anjos, vindos do céu, apareceu e se juntou ao outro anjo louvando a Deus e dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '“Glória a Deus nas alturas e que haja paz na terra entre o povo o qual Deus quer bem”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Após os anjos voltarem ao céu os pastores disseram entre si: “Vamos imediatamente para Belém ver esta coisa maravilhosa que aconteceu e o Senhor nos permitiu saber”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Foram apressadamente e lá encontraram José e Maria em um estábulo. E viram o Bebê deitado na manjedoura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Após verem isso, eles contaram às pessoas o que foi dito a eles sobre o Bebê.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Todos os que se encontraram com os pastores ficaram maravilhados com o que ouviam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Mas, Maria guardava tudo o que havia ouvido e conservava isso em seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Os pastores retornaram glorificando e louvando a Deus, pois tudo o que ouviram e viram era exatamente como o anjo lhes dissera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'No oitavo dia, era chegado o tempo de circuncidar o Bebê. Eles puseram-lhe o nome Jesus, pois foi assim que o anjo O chamou, antes que Ele fosse concebido no ventre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Quando o número de dias da purificação deles se passaram, de acordo com a Lei de Moisés, José e Maria levaram o Bebê até o templo, em Jerusalém, para apresentá-Lo ao Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'Pois estava escrito na Lei do Senhor: “Todo menino nascido primogênito deve ser santificado ao Senhor”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'De acordo com a Lei do Senhor, eles também deveriam ofertar “duas rolinhas ou dois pombinhos” como sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Eis que havia em Jerusalém um homem chamado Simeão. Ele era justo e piedoso. Ele estava esperando a consolação de Israel e o Espírito Santo estava sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'O Espírito Santo revelou a ele que não morreria antes que visse o Cristo prometido por Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Guiado pelo Espírito, Simeão entrou no templo. José e Maria trouxeram o Bebê, Jesus, para cumprir os costumes requeridos na Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'Simeão recebeu Jesus em Seus braços e louvou a Deus dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '“Senhor, permita agora que teu servo vá em paz, pois se cumpriu a Tua promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Pois meus olhos viram a Tua salvação,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'a qual Tu preparaste diante de todos os povos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Luz para revelação aos gentios, e para glória do Teu povo de Israel”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Os pais do Bebê estavam maravilhados com as coisas que eram ditas a respeito Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Simeão os abençoou e disse a Maria, Sua mãe: “Eis que este Bebê está destinado tanto para ruína como para levantamento de muitos em Israel e para ser alvo de contradição');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(também uma espada traspassará a tua própria alma), de modo que os pensamentos de muitos corações sejam revelados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Uma profetisa chamada Ana também estava lá. Ela era filha de Fanuel, da tribo de Aser. Ela era idosa, e viveu com seu marido por sete anos desde a sua virgindade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'e depois tornou-se viúva e assim permaneceu por oitenta e quatro anos. Ela nunca deixou o templo, adorando a Deus continuamente com jejum e oração, noite e dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Naquele mesmo momento, ela começou a agradecer a Deus e falou sobre o menino a todos que estavam esperando pela redenção de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Quando eles terminaram de fazer tudo o que deviam de acordo com a Lei do Senhor, eles retornaram à Galileia, para sua própria cidade, Nazaré.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'E o Menino crescia em estatura, tornando-se forte, enchendo-Se de sabedoria, e a graça de Deus estava sobre Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Seus pais iam todos os anos a Jerusalém, para a Festa da Páscoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Quando Jesus completou doze anos, eles foram para a festa, como era de costume.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'Terminados os dias de celebração, ao regressarem, permaneceu o menino Jesus em Jerusalém e Seus pais não O souberam,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'pois pensaram que estava na caravana que viajava com eles. Após um dia inteiro de jornada, eles começaram a procurá-Lo entre os familiares e amigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'Quando eles não O encontraram, eles voltaram para Jerusalém e começaram a procurá-Lo por lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Após três dias, eles O encontraram no templo, sentado entre os mestres, ouvindo-os com atenção e fazendo perguntas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Todos os que O ouviam ficavam maravilhados com Seu entendimento e com Suas respostas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Quando eles viram Jesus, ficaram atônitos. Então Sua mãe disse-Lle: “Por que fizeste assim conosco? Eis que Teu pai e eu estivemos aflitos procurando por Ti”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'E Jesus respondeu: “Por que vós estáveis procurando por Mim? Vós não sabíeis que Eu devo estar na casa do Meu Pai?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Mas eles não entenderam o que Jesus queria dizer com essas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Então Jesus voltou com Seus pais para Nazaré, e era submisso a eles e Sua mãe guardava todas essas coisas em Seu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Mas Jesus continuava a crescer em sabedoria, estatura e graça para com Deus e as pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'No décimo quinto ano do reinado de Tibério César, enquanto Pôncio Pilatos era governador da Judeia, e Herodes, era tetrarca da Galileia, e seu irmão Filipe, era tetrarca da região de Itureia, e Traconites e Lisânias, tetrarca de Abilene,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'durante o tempo dos sumos sacerdotes Anás e Caifás, a palavra de Deus veio a João, filho de Zacarias, no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Ele viajou por toda a região em derredor do Jordão, pregando o batismo do arrependimento, para o perdão dos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Como está escrito no livro das palavras do profeta Isaías: “Voz do que clama no deserto: \'Preparai o caminho do Senhor, endireitai as Suas veredas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Todo vale será enchido, toda montanha e colina serão abaixadas, as estradas tortuosas serão endireitadas, e os caminhos acidentados serão feitos planos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'e todos verão a salvação de Deus\'”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Então João disse para a grande multidão que vinha para ser batizada por ele: “Vós sois raça de víboras! Quem vos alertou para fugir da ira que está chegando?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Portanto produzi frutos dignos de arrependimento e não comeceis a dizer entre vós: \'Nós temos Abraão por nosso pai!\', porque eu vos digo que Deus pode suscitar filhos a Abraão até mesmo destas pedras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'O machado já está posto junto à raiz das árvores. Pois toda árvore que não produz bom fruto é cortada e lançada no fogo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'E as multidões perguntavam-lhe, dizendo: “O que devemos fazer então?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Ele respondeu, dizendo: “Se alguém tem duas túnicas, dê uma delas àquele que não tem nenhuma e o que tem alimentos, faça o mesmo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Então alguns coletores de impostos, que também vieram para ser batizados, perguntaram: “Mestre, o que devemos fazer?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'E João disse-lhes: “Não coleteis mais dinheiro do que vos foi ordenado”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Alguns soldados também lhe perguntaram, dizendo: “E quanto a nós? O que devemos fazer?” E Ele respondeu: “Não tomeis dinheiro das pessoas à força, nem acuseis alguém falsamente. Contentai-vos com o vosso salário”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Como o povo estava avidamente esperando a chegada do Cristo, todos estavam imaginando em seus corações que João poderia ser o Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'João respondeu-lhes, dizendo: “Quanto a mim, eu vos batizo com água, mas virá Aquele que é mais poderoso do que eu e eu não sou digno nem de desatar as amarras de Suas sandálias. Ele vos batizará com o Espírito Santo e com fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Ele tem em Sua mão uma pá para limpar cuidadosamente a Sua eira e para ajuntar o trigo em Seu celeiro. Mas Ele queimará a palha com fogo que nunca pode apagar.”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Com muitas outras advertências, João pregava as boas novas ao povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'E repreendeu Herodes, o tetrarca, por ter se casado com a mulher do seu irmão, Herodias, por muitas outras coisas más que ele havia feito,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'e ainda acrescentou a todos elas, o de prender João na prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Sucedeu então que enquanto as pessoas eram batizadas por João, Jesus também foi batizado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'e enquanto Ele orava o céu se abriu; e o Espírito Santo desceu até Ele em forma corpórea, como uma pomba. E ouviu-se uma voz do céu: “Tu és o meu Filho amado, em Ti me comprazo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Quando Jesus começou o Seu ministério, Ele tinha trinta anos. Ele era filho de José (como se pensava), filho de Eli,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'filho de Matate, filho de Levi, filho de Melqui, filho de Janai, filho de José,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'filho de Matatias, filho de Amós, filho de Naum, filho de Esli, filho de Nagai,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'filho de Maate, filho de Matatias, filho de Semei, filho de Joseque, filho de Jodá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'filho de Joanã, filho de Resa, filho de Zorobabel, filho de Salatiel, filho de Neri,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'filho de Melqui, filho de Adi, filho de Cosã, filho de Elmodã, filho de Er,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'filho de Josué, filho de Eliézer, filho de Jorim, filho Matate, filho de Levi,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'filho de Simeão, filho de Judá, filho de José, filho de Jonã, filho de Eliaquim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'filho de Meleá, filho de Mená, filho de Matatá, filho de Natã, filho de Davi,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'filho de Jessé, filho de Obede, filho de Boaz, filho de Salá, filho de Nasom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'filho de Aminadabe, filho de Admim, filho de Arni, filho de Esrom, filho de Farés, filho de Judá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'filho de Jacó, filho de Isaque, filho de Abraão, filho de Terá, filho de Naor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'filho de Seruque, filho de Ragaú, filho de Faleque, filho de Eber, filho de Salá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'filho de Cainã, filho de Arfaxade, filho de Sem, filho de Noé, filho de Lameque,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'filho de Matusalém, filho de Enoque, filho de Jarede, filho de Maleleel, filho de Cainã,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'filho de Enos, filho de Sete, filho de Adão, filho de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Então Jesus, cheio do Espírito Santo, retornou do rio Jordão e foi guiado pelo Espírito ao deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'Por quarenta dias, Ele foi tentado pelo diabo. Durante esses dias, Jesus não comeu nada e no final Ele teve fome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'O diabo disse-Lhe: “Se Tu és o Filho de Deus, ordene que esta pedra se transforme em pão”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'E Jesus respondeu: “Está escrito, \'nem só de pão viverá o homem\'”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Então o diabo O levou até um lugar alto, mostrou-Lhe todos os reinos do mundo');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'e disse: “Eu Te darei autoridade para dominar sobre todos estes reinos, com todo o seu esplendor. Pois a mim foram dados, e eu posso dá-los a quem eu quiser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Portanto, se Te prostrares diante de mim e me adorares, tudo isto será Teu”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Mas Jesus respondeu, dizendo: “Está escrito: \'adorarás somente o Senhor teu Deus e somente a Ele prestarás culto\'”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Em seguida, o diabo levou Jesus a Jerusalém, colocou-O no ponto mais alto do templo, e disse: “Se Tu és o Filho de Deus, se jogue daqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Pois está escrito: \'Ele dará ordem aos Seus anjos para cuidar de Ti e protegê-Lo.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'E também disse: \'Eles vão Te segurar com as suas mãos para que os Teus pés não tropecem em nenhuma pedra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Jesus respondeu dizendo: “está escrito, \'não tentarás o Senhor teu Deus\'”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'E, tendo esgotado toda sorte de tentação, o diabo afastou-se Dele até o tempo oportuno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Então Jesus retornou para a Galiléia, pelo poder do Espírito, e notícias sobre Ele se espalhavam por toda a região circunvizinha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'E ensinava nas sinagogas, e todas as pessoas O glorificavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Ele veio a Nazaré a cidade onde cresceu. Como de costume, Ele entrou na sinagoga, no dia de sábado, e levantou-Se para ler as Escrituras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'E foi-Lhe entregue o rolo do profeta Isaías, e, desenrolando-o, encontrou o lugar em que estava escrito:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '“o Espírito do Senhor está sobre Mim, pois Ele Me ungiu para pregar boas novas aos pobres. Ele Me enviou para proclamar liberdade aos cativos e restaurar a vista dos cegos, para libertar os oprimidos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'e proclamar o ano favorável do Senhor”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Então Ele fechou o rolo, devolveu ao assistente da sinagoga e Se sentou. Todos na sinagoga estavam com os olhos fixos Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Ele começou falando-lhes: “hoje se cumpriu a Escritura que acabais de ouvir”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Cada um testemunhou o que Ele disse, e todos eles estavam maravilhados com as palavras graciosas que saíam de Sua boca. Eles diziam: “não é este o filho de José?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Jesus disse-lhes: “certamente Me direis este provérbio: \'médico, cura a ti mesmo. Faz em tua terra tudo o que ouvimos que fizeste em Cafarnaum\'”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'E Ele disse: “asseguro-vos que nenhum profeta é bem recebido em sua própria terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Mas em verdade vos digo que havia muitas viúvas em Israel na época de Elias, quando por três anos e meio não choveu, e houve grande fome sobre toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Mas Elias não foi enviado a nenhuma delas, somente a uma viúva que vivia em Sarepta, perto da cidade de Sidom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'No tempo do profeta Eliseu, também havia muitos leprosos em Israel, mas somente um foi curado, Naamã, o sírio”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Todos na sinagoga se enfureceram quando ouviram essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'Eles se levantaram, O expulsaram para fora da cidade e O conduziram para o pico do monte sobre o qual a cidade deles estava edificada, a fim de lançá-Lo abaixo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Mas Ele caminhou entre eles e seguiu o Seu caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Então Ele desceu a Cafarnaum, uma cidade na Galiléia. Aos sábados Ele estava ensinando as pessoas na sinagoga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'Elas ficavam atônitas com o ensino Dele, pois falava-lhes com autoridade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Naqueles dias, na sinagoga, havia um homem que era controlado pelo espírito de um demônio imundo. Ele gritava fortemente:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, '“O que temos contigo, Jesus de Nazaré? Tu vieste para nos destruir? Eu sei quem Tu és, o Santo de Deus!”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Jesus repreendeu o demônio, dizendo: “Cala-te e sai dele!”. O demônio arremessou o homem no meio deles e saiu sem causar-lhe nenhum dano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'E o povo ficou espantado e, uns com os outros, conversavam: “Que palavras são essas? Com poder e autoridade Ele ordena aos espíritos imundos e eles saem”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'E notícias sobre Ele começaram a se espalhar em todos os lugares da região.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Então Jesus deixou a sinagoga e foi até a casa de Simão. A sogra de Simão estava sofrendo com uma febre muito alta, e eles suplicavam-Lhe em favor dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Jesus se inclinou sobre ela e repreendeu a febre, e essa a deixou. No mesmo momento, ela levantou-se e começou a servi-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Quando o Sol estava se pondo, as pessoas trouxeram a Jesus todos os que estavam enfermos, com vários tipos de doenças. Jesus, impondo as mãos sobre cada um, os curava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'E demônios também saíram de muitos deles, gritando e dizendo: “Tu és o Filho de Deus!”. E Jesus repreendia os demônios, não os deixando falar, porque eles sabiam que Ele era o Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Quando o dia raiou, Jesus saiu para um lugar deserto para orar. E as multidões o procuravam e vieram até o lugar onde Ele estava. E tentaram impedi-Lo de ir embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Mas Jesus lhes disse: “Eu tenho que pregar as boas novas do Reino de Deus para muitas outras cidades, pois é por essa razão que Eu fui enviado”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Então Ele continuou pregando nas sinagogas em toda a província da Judeia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'E aconteceu que, certo dia, a multidão se comprimia ao redor de Jesus para ouvir a palavra de Deus, e Ele estava em pé junto ao lago de Genesaré.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Ele viu dois barcos à beira do lago, os pescadores haviam desembarcado e lavavam as suas redes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Então Ele subiu em um dos barcos, que era de Simão, e pediu-lhe para afastar um pouco o barco da praia. Jesus assentou-se e, do barco, ensinava às multidões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Quando terminou de ensinar, Jesus disse a Simão: “eva o barco às águas profundas e lançai as vossas redes”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'E Simão respondeu: “Mestre, trabalhamos a noite inteira e não pescamos nada, mas por causa da Tua palavra baixarei as redes”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Depois de fazerem isso, eles pegaram uma grande quantidade de peixes, e as redes começaram a se rasgar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Então eles acenaram aos seus companheiros no outro barco para virem ajudá-los. Eles encheram tanto os dois barcos que chegaram a ponto de quase afundarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Quando Simão Pedro viu isso, ele se prostrou aos pés de Jesus, dizendo: “afasta-Te de mim, porque sou um pecador, Senhor”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Pois ele e todos os que estavam consigo ficaram assombrados com a pesca que haviam feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Semelhantemente, também, Tiago e João, filhos de Zebedeu, que eram sócios de Simão. Então Jesus disse a Simão: “Não temas, pois a partir de agora tu serás pescador de homens”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Quando eles trouxeram os barcos para a praia, deixaram tudo e seguiram a Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Aconteceu que, enquanto Ele estava em uma das cidades, havia um homem cheio de lepra. Quando ele viu Jesus, prostrou-se, tocando o rosto no solo, e implorou-lhe, dizendo: “Senhor, se esta é a Tua vontade, podes purificar-me.”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'E Jesus estendeu as suas mãos e o tocou, dizendo: “Esta é a minha vontade. Sê purificado!” E imediatamente a lepra o deixou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Ele o instruiu para não dizer a ninguém, mas falou-lhe: “Segue teu caminho, mostra-te ao sacerdote e oferece um sacrifício por tua purificação, de acordo com o que Moisés ordenou, para testemunhar-lhes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Porém, notícias sobre Ele espalharam-se ainda mais, e multidões de pessoas vinham para ouvir Jesus ensinar e para serem curadas de suas doenças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'E com frequência Ele se retirava para um lugar solitário e orava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Aconteceu que, certo dia, Jesus estava ensinando, e havia fariseus e mestres da Lei sentados perto Dele. Eles vieram de diversas aldeias das regiões da Judeia e da Galileia e também da cidade de Jerusalém. E o poder do Senhor estava com Ele para curar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Então alguns homens vieram carregando em um leito um homem que era paralítico. Eles procuravam uma maneira de trazê-lo para dentro do local, a fim de deitá-lo em frente a Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Mas, por causa da multidão, eles não conseguiram. Então subiram ao telhado e, por entre as telhas, desceram o homem em seu leito, no meio das pessoas, exatamente na frente de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Vendo-lhes a fé, Jesus disse: “Homem, os teus pecados estão perdoados”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Os escribas e fariseus começaram a questionar, dizendo: “Quem é este para dizer essas blasfêmias? Somente Deus pode perdoar pecados”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Mas Jesus, percebendo o que eles estavam pensando, respondeu e disse-lhes: “Por que estais questionando isso em vossos corações?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'O que é mais fácil dizer: \'Os teus pecados estão perdoados.\' ou \'Levanta-te e anda?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Porém, para que saibais que o Filho do Homem tem autoridade na terra para perdoar pecados, eu te digo: \'Levanta-te, pega o teu leito e vai para a tua casa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Imediatamente ele se levantou perante eles, pegou o leito em que vivia deitado e foi para a sua casa glorificando a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Todos ficaram maravilhados, glorificavam a Deus e, cheios de temor, diziam: “Hoje nós vimos coisas extraordinárias”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Depois disso, Jesus saiu de lá e viu um coletor de impostos chamado Levi assentado no local de coleta de impostos. Então Jesus lhe disse: “Segue-Me\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Levi deixou tudo, levantou-se e O seguiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Então Levi preparou um grande banquete para Jesus em sua casa. Muitos coletores de impostos e outras pessoas estavam reclinados à mesa, comendo com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'E os fariseus e escribas se queixavam aos discípulos de Jesus, dizendo: “Por que vós comeis e bebeis com coletores de impostos e outros pecadores?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Respondeu-lhes Jesus: “Aqueles que têm saúde não precisam de médico, somente os doentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Eu não vim para chamar os justos, mas para chamar os pecadores ao arrependimento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Eles Lhe disseram: “Os discípulos de João estão sempre jejuando e orando, os discípulos dos fariseus também. Porém os teus discípulos bebem e comem”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Jesus disse-lhes: “Pode alguém fazer os convidados de um casamento jejuarem enquanto o noivo está com eles?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Mas chegarão dias em que o noivo lhes será tirado, e naqueles dias eles jejuarão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Então Jesus contou-lhes uma parábola: “Ninguém tira remendo de uma roupa nova para consertar uma roupa velha. Pois, se fizer isso, a roupa nova ficará rasgada, e o remendo não combinará com a roupa velha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Ninguém põe vinho novo em odres velhos. Se assim o fizer, o vinho novo romperá os odres e se derramará, e os odres serão destruídos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Mas o vinho novo deve ser colocado em odres novos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Ninguém, após tomar vinho velho, deseja tomar o vinho novo, pois diz: “O velho é que é bom!”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'E aconteceu que em um dia de Sábado, Jesus estava atravessando campos de cereais e Seus discípulos iam colhendo espigas, debulhando com as mãos e comendo os grãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Então alguns dos fariseus disseram: “Por que vós estais fazendo algo que não é lícito no dia de Sábado?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Jesus respondendo, disse-lhes: “Nunca lestes o que Davi fez quando ele e os homens que estavam com ele tiveram fome?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Ele entrou na casa de Deus, pegou o pão da proposição, comeu e também deu aos que estavam com ele. E os sacerdotes eram os únicos que tinham permissão para comer este pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'E Jesus disse-lhes: “O Filho do Homem é Senhor do Sábado”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'E aconteceu que, em outro Sábado, Jesus foi até a sinagoga e ensinava as pessoas. E estava ali um homem com a mão direita atrofiada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'E os escribas e fariseus observavam Jesus de perto, para ver se Ele iria curar alguém no dia de Sábado, pois procuravam um motivo para acusá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Mas Jesus, sabendo o que eles estavam pensando, disse ao homem da mão atrofiada: “Levanta-te e fica aqui no meio de todos”. Então o homem se levantou e permaneceu em pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Então Jesus disse-lhes: “Eu vos pergunto: No Sábado é permitido fazer o bem ou fazer o mal? Salvar uma vida ou destruí-la?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Então Ele olhou ao redor de todos eles e disse ao homem: “Estende a tua mão\". Ele fez isto, e sua mão foi restaurada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Mas eles ficaram cheios de fúria, e discutiam entre si sobre o que eles poderiam fazer a Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Aconteceu naqueles dias, que Jesus foi para uma montanha orar. Durante toda a noite, Ele continuou orando a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Quando o dia amanheceu, Ele chamou os Seus discípulos, escolheu doze deles, os quais Ele também chamou de apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Os nomes desses apóstolos eram: Simão, a quem Ele chamou de Pedro, e seu irmão André; Tiago; João; Filipe; Bartolomeu;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Mateus; Tomé; Tiago, filho de Alfeu; Simão, que era chamado Zelote;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Judas, filho de Tiago; e Judas Iscariotes, que tornou-se o traidor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Então Jesus desceu com eles da montanha e permaneceram em um lugar plano, onde havia uma grande multidão de Seus discípulos, e também muitas pessoas da Judeia e Jerusalém, e do litoral de Tiro e Sidom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'Eles tinham vindo para ouvi-Lo e serem curados de suas enfermidades. Pessoas que eram atormentadas por espíritos imundos também eram curadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'E toda a multidão tentava tocar Jesus, porque dEle saía poder, e Ele curava todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Então erguendo os olhos para os Seus discípulos, disse-lhes: “Benditos sois vós, os pobres, pois vosso é o Reino de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Benditos vós que agora tendes fome, pois sereis saciados. Benditos vós que agora chorais, pois rireis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Benditos sereis quando as pessoas vos odiarem e vos excluírem, e quando vos insultarem e rejeitarem o vosso nome como mau, por causa do Filho do Homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Alegrai-vos naquele dia e pulai de alegria, certamente vós tereis uma grande recompensa no céu, pois os antepassados deles trataram os profetas da mesma forma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Mas, ai de vós que sois ricos! Pois já recebestes o vosso conforto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Ai de vós, que estais saciados agora! Pois vós tereis fome. Ai de vós, que estais sorrindo agora. Pois vós estareis enlutados e chorareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Ai de vós, quando todos vos bendisserem! Pois os antepassados deles trataram os falsos profetas da mesma forma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Eu porém vos digo a vós que me ouvis: amai os vossos inimigos e fazei o bem aos que vos odeiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Bendizei aqueles que vos amaldiçoam e orai por aqueles que vos caluniam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Se alguém te der um tapa na face, ofereça a ele também o outro lado. Se alguém tomar a tua capa, não recuse a ele a tua túnica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Se alguém te pedir algo, dê a ele. Se alguém tomar algo que te pertença, não peça-lhe que devolva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Assim como quereis que vos façam, fazei o mesmo a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Se amais somente aqueles que vos amam, que recompensa tereis? Pois até mesmo os pecadores amam os que os amam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Se vós fizerdes o bem somente àqueles que vos fazem o bem, que recompensa tereis? Pois até mesmo os pecadores fazem isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Se vós emprestais somente àqueles que vós sabeis que devolverão, que mérito tereis? Até mesmo pecadores emprestam aos pecadores e esperam que eles devolvam a mesma quantia emprestada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Mas, amai os vossos inimigos, fazei-lhes o bem e emprestai sem nunca esperar que vos devolvam, e grande será vossa recompensa. Sereis filhos do Altíssimo, pois Ele é bondoso para com os ingratos e maus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Sede misericordiosos, assim como o vosso Pai é misericordioso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Não julgueis, e não sereis julgados. Não condeneis, e não sereis condenados. Perdoai, e sereis perdoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Dai aos outros e vos será dado. Recebereis uma medida generosa, calcada, recalcada, sacudida e transbordante. Pois, com a medida que medirdes, sereis medidos de volta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Então Ele também contou-lhes uma parábola: “Pode um cego guiar outro cego? Se ele o fizer, não cairão ambos em um buraco?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Um discípulo não é maior que o seu mestre, mas quando estiver completamente treinado será como o seu mestre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'E porque vês o cisco que está no olho do teu irmão, mas não percebes a trave que está no teu próprio olho?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Como podes dizer ao teu irmão: \'Irmão, deixa-me tirar o cisco que está no teu olho\', quando tu mesmo não vês a trave que está no teu próprio olho? Hipócrita! Primeiro tira a trave do teu olho, então verás claramente para poder tirar o cisco que está no olho do teu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Não há árvore boa que produza mau fruto, nem árvore ruim que produza bom fruto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Pois cada árvore é conhecida pelo fruto que produz. Ninguém pode colher figos de espinheiros, nem uvas de sarça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'O homem bom, do bom tesouro do seu coração tira o que é bom, mas o mau, da maldade do seu coração traz para fora o que é mau; porque a boca fala daquilo de que está cheio o coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'E porque Me chamais: \'Senhor, Senhor\' e não obedeceis às coisas que digo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Toda pessoa que vem a Mim e ouve minhas palavras e as obedecem, Eu direi como ele é:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, '\'ele é como um homem que, ao construir a sua casa, cavou fundo no solo e a alicerçou sobre a rocha. Quando a tempestade veio, as águas do rio bateram com ímpeto contra a casa, mas ela não se abalou, pois foi bem construída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Mas aquele que ouve as minhas palavras e não as obedece, é como um homem que construiu a sua casa sobre a terra, sem alicerce. Quando as águas do rio bateram com ímpeto contra a casa, ela imediatamente desabou, e a sua ruína foi completa\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Quando Jesus terminou de transmitir aos ouvidos do povo todas essas palavras, entrou em Cafarnaum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Um servo, de um centurião, muito querido por ele, estava muito doente e prestes a morrer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'E tendo ouvido falar sobre Jesus, o centurião enviou até Ele alguns anciãos dos judeus pedindo que Ele viesse e salvasse seu servo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Quando eles chegaram até Jesus, pediram-Lhe insistentemente: “Ele é digno de que lhe faças isso,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'pois ama nossa nação, e é quem construiu a sinagoga para nós”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Então Jesus seguiu em Seu caminho com eles. Estando não muito longe da casa, o centurião enviou os seus amigos para dizer-Lhe: “Senhor, não te incomodes, pois não sou digno de que entres em minha casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Por essa razão não me considero digno de ir ao Teu encontro; dize porém apenas uma palavra e meu servo será curado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Pois também estou sob autoridade, e tenho soldados sob minhas ordens. Eu digo a este: “Ide” e ele vai; e digo a outro “Vinde” e ele vem; Eu digo ao meu servo: “Fazei isto” e ele o faz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Quando Jesus ouviu isso, Ele ficou admirado, e virando-se para a multidão que O seguia, disse: “Eu vos digo que nem mesmo em Israel encontrei alguém com tamanha fé”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Então aqueles que foram enviados a Ele retornaram para a casa e encontraram o servo saudável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Depois disso, aconteceu que Jesus estava viajando para uma cidade chamada Naim. Os Seus discípulos iam com Ele, juntamente com uma grande multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Quando aproximou-se do portão da cidade, um homem morto estava sendo carregado, o único filho de sua mãe. Ela era uma viúva, e uma multidão numerosa da cidade estava com ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Quando o Senhor a viu, Ele se compadeceu dela, e disse-lhe: “Não chores!”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Então Ele chegou perto, tocou a armação de madeira que levava o corpo, e aqueles que a carregavam pararam, e Ele disse: “Jovem, Eu te digo, levanta-te”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'O homem que estava morto se levantou e começou a falar. Então Jesus o entregou para sua mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'E sobreveio temor sobre todos e eles glorificavam a Deus dizendo: “Um grande profeta surgiu entre nós” e “Deus tem olhado para o Seu povo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Essas notícias sobre Jesus se espalharam por toda a Judeia e por todas as regiões vizinhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Os discípulos de João contaram todas estas coisas para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Então João chamou dois de seus discípulos e os enviou até o Senhor para dizer: “Tu és o que haveria de vir ou devemos esperar por outro?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Quando eles encontraram Jesus, disseram: “João Batista nos enviou a Ti para perguntarmos: \'Tu és o que estava para vir ou devemos esperar por outro?\'”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'Naquela mesma hora Ele curou muitas pessoas de doenças, de aflições, de espíritos malignos e, a muitos cegos deu visão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Jesus respondeu-lhes, dizendo: “Ide e relatai a João tudo o que tendes visto e ouvido. Pessoas cegas estão recebendo a visão, paralíticos estão andando, leprosos estão sendo purificados, surdos estão ouvindo, mortos estão sendo trazidos de volta à vida e aos necessitados estão sendo anunciadas as boas novas”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'Bendito aquele que não deixar de acreditar em Mim por causa das minhas ações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Quando os mensageiros de João foram embora, Jesus começou a falar para a multidão sobre ele. “O que fostes ver no deserto? Um caniço balançado pelo vento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'O que fostes ver? Um homem vestido em roupas finas? Eis que pessoas que vestem roupas esplendorosas e têm uma vida de luxo estão em palácios reais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Mas o que fostes ver? Um profeta? Sim, Eu vos digo, e mais do que profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Este é aquele sobre o qual está escrito: \'Eis que estou enviando Meu mensageiro diante de Tua face, o qual irá preparar Teu caminho diante de Ti\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Eu vos digo que entre os nascidos de mulher, não há ninguém maior do que João, mas aquele que é menor no Reino de Deus, é maior do que ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Quando todas as pessoas ouviram isso, inclusive os coletores de impostos, todos declararam que Deus é justo, sendo então, batizados com o batismo de João.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Mas os fariseus e os mestres da lei judaica rejeitaram o conselho de Deus para si mesmos, não sendo batizados por ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, '“A quem, pois, compararei as pessoas desta geração? A quem elas se assemelham?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'São como crianças brincando na praça que sentam e chamam umas às outras e dizem: \'Nós vos tocamos flauta, mas não dançastes. Nós cantamos um cântico fúnebre e não chorastes’.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'João Batista veio, não comendo pão e nem bebendo vinho, e vós dissestes: \'Ele tem demônio\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Veio o Filho do Homem, comendo e bebendo, e vós dissestes: \'Eis um homem glutão e bebedor de vinho, amigo de cobradores de impostos e pecadores!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Mas a sabedoria é justificada por todos os seus filhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Então, um certo fariseu estava pedindo que Jesus comesse com ele. Então Jesus entrou na casa do fariseu e reclinou-se à mesa para comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Havia naquela cidade uma certa mulher que era pecadora. Ao descobrir que Ele estava à mesa na casa do fariseu, ela levou um vaso de alabastro com perfume.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'Então, ela se colocou atrás Dele, junto aos Seus pés e pranteou. E começou a molhar os Seus pés com suas lágrimas e enxugá-los com seu cabelo, beijando Seus pés e os ungindo com perfume.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Quando o fariseu que havia convidado Jesus viu isso, ele pensou consigo mesmo: “Se este homem fosse profeta, saberia quem e que tipo de mulher está tocando nele, pois ela é uma pecadora”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Então Jesus respondeu-lhe, dizendo: “Simão, eu tenho algo para lhe dizer”. E Simão disse: “Fala, Mestre!”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Jesus disse: “Havia dois devedores a certo credor. Um devia quinhentos denários e o outro devia cinquenta denários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Como eles não tinham dinheiro para pagar a dívida, o credor perdoou os dois. Qual deles o amará mais?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simão respondeu: “Eu suponho que aquele a quem mais foi perdoado”. Disse-lhe Jesus: “Julgaste corretamente”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Jesus virou-se para a mulher e disse a Simão: “Vês esta mulher? Eu entrei em tua casa e tu não Me ofereceste água para lavar os Meus pés, mas esta mulher molhou os Meus pés com suas lágrimas e os enxugou com seus cabelos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Tu não Me deste um beijo, mas ela, desde que cheguei aqui, não para de beijar os Meus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Não ungistes a Minha cabeça com óleo, mas ela tem ungido Meus pés com perfume.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Por isso, te digo que os seus muitos pecados têm sido perdoados - porque ela muito amou. Mas aquele que pouco é perdoado, pouco ama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Então Ele disse-lhe: “Os teus pecados estão perdoados”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Aqueles que estavam sentados à mesa começaram a dizer entre si. “Quem é este que até perdoa pecados?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Então Jesus disse à mulher: “A tua fé te salvou. Vai em paz”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'E aconteceu que, depois disso, Jesus começou a andar por diferentes cidades e vilas, pregando e proclamando as boas novas do reino de Deus. E os doze foram com Ele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'assim como algumas mulheres que foram curadas de espíritos malignos e doenças. Eram elas: Maria, chamada Madalena, da qual sete demônios foram expulsos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Joana, mulher de Cuza, administrador de Herodes, Suzana e muitas outras mulheres que lhes traziam provisão com seus próprios recursos materiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'E reunindo-se uma grande multidão, incluindo pessoas que vinham de outras cidades para encontrá-Lo, Jesus lhes falou por meio de uma parábola:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '“Um semeador saiu para semear algumas sementes. Enquanto ele semeava, algumas sementes caíram à beira do caminho, elas foram pisoteadas, e os pássaros do céu comeram todas elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Outras sementes caíram em solo rochoso e assim que elas cresceram, secaram por falta de umidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Ainda outras sementes caíram entre plantas espinhosas e elas cresceram juntamente com os espinhos, e eles as sufocaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Mas algumas sementes caíram em solo bom, e cresceram saudáveis, e produziram uma colheita cem vezes maior”. Após Jesus dizer estas coisas, Ele exclamou em alta voz: “Aquele que tem ouvidos para ouvir, ouça”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Então os discípulos perguntaram a Ele o que esta parábola queria dizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Jesus disse-lhes: “Vós recebestes o privilégio de entender os mistérios do reino de Deus, mas os demais serão ensinados apenas por parábolas, desta forma \'embora vendo, eles não possam enxergar, e ouvindo não entendam\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Este é o significado da parábola: a semente é a Palavra de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'As sementes que caíram à beira do caminho são aqueles que ouvem, mas o diabo vem e arranca a Palavra de seus corações para que não creiam, e assim, não sejam salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'As sementes que caíram no solo rochoso são aqueles que ouvem a Palavra, recebem-na com alegria, mas não criam raízes. Eles acreditam por um tempo e em tempo de provação se desviam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'As sementes que caíram entre os espinhos são como pessoas que ouviram a Palavra, mas a medida que seguem os seus caminhos foram sufocadas pelos cuidados, riquezas e prazeres desta vida, e então não produzem frutos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Mas as sementes que caíram em solo bom são como pessoas que, com sinceridade e bom coração, ouvem a Palavra, agarram-na com firmeza e produzem frutos com perseverança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'E ninguém acende uma lamparina e a cobre com um vaso ou a coloca embaixo de uma cama. Ao contrário, a coloca em cima de uma mesa e, assim, todos que entrarem podem ver a luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Pois tudo o que está escondido será revelado, e tudo o que é secreto será conhecido e trazido à luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Então escutai cuidadosamente, pois para aquele que tem, mais lhe será dado, e aquele que não tem, até o que ele pensa ter lhe será tirado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Então a mãe e os irmãos de Jesus vieram até Ele, mas não podiam se aproximar por causa da multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'E disseram-lhe: “Tua mãe e teus irmãos estão do lado de fora esperando para te ver”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Mas Jesus lhes disse: “Minha mãe e meus irmãos são aqueles que ouvem a Palavra de Deus e a praticam”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Aconteceu que em um daqueles dias, Jesus e os Seus discípulos entraram em um barco, e Jesus disse-lhes: “Vamos para o outro lado do lago”. Então eles zarparam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Mas, enquanto eles navegavam, Jesus dormiu e uma tempestade de ventos fortes atingiu o lago e o barco começou a se encher de água, e eles estavam em grave perigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Os discípulos de Jesus foram até Ele e o acordaram dizendo: “Mestre, Mestre, estamos prestes à morrer!” Ele acordou, repreendeu a tempestade e a fúria das águas, elas cessaram e houve calmaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Então Ele lhes disse: “Onde está a vossa fé?” Possuídos de temor e admiração, diziam uns aos outros: “Quem é Este, que comanda os ventos e a água, e estes Lhe obedecem?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'E eles navegaram para a região dos gerasenos, que fica no outro lado do lago da Galileia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Quando Jesus pisou em terra, um certo homem da cidade foi ao encontro dEle, e este homem tinha demônios. Há muito tempo ele não vestia roupas e não vivia em casa, mas sim nos sepulcros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Quando viu Jesus, ele gritou e se prostrou diante Dele. E em alta voz disse: “O que tenho contigo, Jesus, Filho do Deus Altíssimo? Eu te imploro, que não me atormentes”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Pois Jesus tinha ordenado ao espírito imundo que saísse do homem que, por muitas vezes, tinha se apoderado dele. Embora ficasse preso por correntes e grilhões, e sob vigilância de guardas, ele quebrava as correntes e era levado ao deserto pelo demônio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Então Jesus perguntou a ele: “Qual é o seu nome?” E ele disse: “Legião”, porque muitos demônios haviam entrado nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Eles imploravam para que Jesus não os mandasse para o abismo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Uma grande manada de porcos estava ali, se alimentando na colina, e os demônios lhe imploraram para entrarem nos porcos. Ele lhes permitiu que fizessem isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Então os demônios saíram do homem e entraram nos porcos, e a manada correu e se lançou despenhadeiro abaixo para dentro do lago e se afogaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Quando os homens que estavam cuidando dos porcos viram o que aconteceu, eles fugiram e relataram isso na cidade e nos campos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'As pessoas que ouviram sobre isso foram ver o que aconteceu e, quando se aproximaram de Jesus, elas viram o homem do qual os demônios saíram. O homem estava vestido, em perfeito juízo, sentado aos pés de Jesus, à vista disso ficaram atemorizados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Aqueles que viram o que aconteceu, contaram a outros como o homem que era controlado por demônios foi salvo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Todas as pessoas da região dos gerasenos e aos arredores pediram que Jesus se retirasse do meio deles, pois eles ficaram com muito medo. Então Jesus entrou no barco e retornou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'O homem do qual os demônios haviam saído suplicou que Jesus o deixasse ir com ele, mas Jesus o mandou embora, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '“Volta para a tua casa e conta as coisas que Deus fez por ti”. O homem seguiu seu caminho, proclamando por toda a cidade as coisas que Jesus havia feito por ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Quando Jesus retornou, a multidão o recebeu com alegria, pois eles estavam esperando por Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Lá havia um homem chamado Jairo, que era um dos líderes da sinagoga. Jairo se prostrou aos pés de Jesus e o implorou que Ele fosse até a sua casa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'pois sua única filha, de doze anos, estava morrendo. Mas enquanto Jesus ia, as multidões O espremiam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Uma mulher que há doze anos sofria de fluxo de sangue estava na multidão. Ela já havia gastado todo o seu dinheiro com médicos, mas nenhum deles conseguira curá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Ela veio por trás de Jesus, tocou a borda de seu manto e imediatamente seu sangramento parou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Jesus disse: “Quem me tocou?” Quando todos negaram, Pedro disse: “Mestre, as multidões de pessoas estão te espremendo e te apertando”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Mas Jesus disse: “Alguém me tocou, pois eu sei que de Mim saiu poder”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Quando a mulher viu que não poderia se esconder do que fez, ela veio tremendo, se prostrou aos pés de Jesus e declarou na presença de todos o motivo de ter tocado Nele e como ela fora curada imediatamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Então Jesus disse: “Filha, a tua fé te curou. Vá em paz”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Enquanto Jesus ainda falava, alguém veio da casa do líder da sinagoga, dizendo: “Não incomode o Mestre. A tua filha está morta”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Mas quando Jesus ouviu isso, disse a Jairo: “Não temas. Apenas acredite e ela será salva”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Então quando Jesus chegou na casa, não permitiu que ninguém entrasse com Ele, exceto Pedro, João e Tiago, bem como o pai e a mãe da menina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Todas as pessoas estavam lamentando e chorando por ela, mas Ele disse: “Não choreis. Ela não está morta, está adormecida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'E eles riram Dele com desdém, sabendo que ela estava morta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Mas Ele segurou a mão da menina e clamou dizendo: \"Menina, levanta-te\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'O espírito dela retornou e ela levantou no mesmo momento. E Ele ordenou que dessem algo para ela comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Seus pais estavam espantados, mas Ele ordenou que não contassem a ninguém o que aconteceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Jesus convocou os doze e os deu poder e autoridade sobre todos os demônios e para curar doenças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Ele os enviou para pregar o Reino de Deus e curar os doentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Ele disse-lhes: “Não leveis nada para a viagem, nem cajado, bolsa, pão, dinheiro, nem mesmo uma túnica extra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Qualquer casa em que entrardes, permanecei ali até retirardes do lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Quando não vos receberem, ao sair daquela cidade, sacudi a poeira de vossos pés em testemunho contra eles”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Eles então partiram pelas vilas, proclamando as boas novas e curando as pessoas por todos os lugares.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Herodes, o tetrarca, ouviu sobre tudo o que estava acontecendo e ficou perplexo, pois uns diziam que João Batista havia ressuscitado dos mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'Alguns diziam que Elias havia aparecido e outros que um dos profetas antigos havia voltado à vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Herodes, porém, disse: “A João eu mandei que fosse decapitado, então quem pode ser este sobre o qual ouço tais coisas?” E Herodes tentou encontrar alguma maneira de ver Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Quando os doze apóstolos enviados por Jesus retornaram, eles contaram-Lhe tudo que haviam feito. Então Jesus os levou consigo para uma cidade chamada Betsaida,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'mas as multidões ouviram sobre isso e O seguiram. Ele acolheu a todos, falou sobre o Reino de Deus e curou os que necessitavam ser curados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Quando estava entardecendo os doze vieram até Ele e disseram: “Despede a multidão, dessa forma eles poderão ir até vilas aos arredores e interior para encontrar abrigo e comida, pois o lugar que estamos é isolado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Mas Ele lhes disse: “Dai-lhes algo para comer”. Eles disseram: “Não temos mais que cinco pães e dois peixes, a não ser que fôssemos comprar comida para todo esse povo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, '(Havia cerca de cinco mil homens lá.) Então Ele disse aos Seus discípulos: \"Fazei-os sentar em grupos de cerca de cinquenta pessoas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Então eles assim fizeram e todas as pessoas assentaram-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Ele pegou os cinco pães, os dois peixes e olhando para o céu os abençoou, partiu-os em pedaços e os entregou aos discípulos para que eles distribuíssem à multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Todos comeram, ficaram satisfeitos e encheram doze cestos com a comida que sobrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'E aconteceu que Jesus estava orando em particular e seus discípulos estavam com Ele. Então Ele os questionou: “Quem as multidões dizem que Eu sou?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'E eles responderam: “Uns dizem que tu és João Batista, alguns dizem que és Elias e outros dizem que tu és um dos profetas antigos que voltou à vida”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'E disse-lhes: \"Mas quem dizeis que Eu sou?\" Respondendo Pedro disse: \"O Cristo de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Mas alertando-os, Jesus os instruiu que a ninguém falassem isso,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'dizendo-lhes: \"É necessário que o Filho do Homem sofra muitas coisas, seja rejeitado pelos anciãos, pelos chefes dos sacerdotes, pelos escribas, seja morto e seja ressuscitado no terceiro dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Se alguém quer vir após Mim, negue a si mesmo, tome a sua cruz diariamente e siga-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Aquele que deseja salvar a sua vida irá perdê-la, mas aquele que perder a sua vida por minha causa, irá salvá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Pois que benefício há para uma pessoa se ela ganhar o mundo todo, mas perder-se ou arruinar-se a si mesmo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Aquele que se envergonha de Mim e das minhas palavras, o Filho do Homem se envergonhará dele quando vier em Sua glória, na glória do Pai e dos santos anjos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Verdadeiramente eu vos digo, há alguns de vós que estais aqui que não passarão pela morte até que vejam o reino de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'E aconteceu que, oito dias após dizer essas palavras, Jesus levou consigo Pedro, João e Tiago e subiu ao monte para orar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Enquanto Ele estava orando, a aparência do seu rosto mudou, suas roupas se tornaram brancas e resplandecentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'E eis que dois homens estavam falando com Ele, Moisés e Elias,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'os quais apareceram em glorioso esplendor. Eles falavam sobre a partida Dele que estava prestes a se cumprir em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Pedro e os que estavam com Ele estavam dominados pelo sono, mas quando despertaram, viram a glória de Jesus e os dois homens que estavam com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Quando estes iam se afastando de Jesus, disse-Lhe Pedro: “Mestre, é bom estarmos aqui. Façamos três tendas, uma para Ti, uma para Moisés e outra para Elias\", porém ele não sabia o que dizia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Enquanto ele estava dizendo estas coisas, uma nuvem veio e os envolveu com sua sombra, eles ficaram aterrorizados ao entrarem na nuvem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Uma voz saiu da nuvem, dizendo: “Este é o Meu Filho, O escolhido; a Ele ouvi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Quando a voz parou, Jesus estava sozinho. Eles ficaram em silêncio e naqueles dias não disseram nada a ninguém sobre o que tinham visto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'E aconteceu que, no dia seguinte, uma grande multidão O encontrou quando eles desceram do monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Um homem da multidão clamou dizendo: “Mestre, eu Te imploro que olhes para o meu filho, pois ele é o único que tenho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'E eis que um espírito se apodera dele, que de repente grita, convulsiona e até espumar pela boca. O espírito dificilmente sai dele, machucando ele muito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Eu supliquei a Seus discípulos para que o expulsasse, mas eles não o puderam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Jesus respondeu-lhes, dizendo: \"Ó geração incrédula e perversa, até quando estarei convosco e vos suportarei? Traze o teu filho aqui”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Enquanto o menino estava vindo, o demônio o lançou ao chão e o convulsionou. Mas Jesus repreendeu o espírito imundo, curou o menino e o entregou para o seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Todos ficaram maravilhados com a grandeza de Deus. Mas enquanto todos ainda estavam admirados com tudo o que Jesus fez, Ele disse aos Seus discípulos:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, '“Ponde em vossos ouvidos estas palavras: o Filho do Homem será entregue nas mãos de homens”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Mas eles não entenderam o significado dessas palavras, isto foi-lhes encoberto, para que não entendessem. E estavam com medo de perguntá-Lo acerca dessa declaração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Então os discípulos começaram a discutir entre si sobre qual deles seria o maior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Mas Jesus sabendo o que eles estavam pensando em seus corações, pegou uma criança e a colocou ao seu lado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'e disse-lhes: “Se alguém receber esta criança em Meu nome, ele também Me recebe, e se alguém Me recebe, ele também recebe Aquele que Me enviou. Pois aquele que for o menor dentre vós, esse que é grande\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'João lhe disse: “Mestre, nós vimos alguém expulsando demônios em Seu nome e o proibimos, porque ele não Te segue conosco”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Mas Jesus disse a ele: “Não o impeçais, pois quem não é contra vós é a favor de vós”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'E aconteceu que, estando para se completar os dias de Sua ascensão, Ele resolutamente decidiu ir para Jerusalém');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'e enviou mensageiros à sua frente. Eles entraram em uma vila samaritana para preparar Sua chegada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Mas as pessoas de lá não O receberam, porque a Sua face estava direcionada para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Então quando Seus discípulos Tiago e João viram isso, eles disseram: “Senhor, queres que mandemos descer fogo do céu e os destruir?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Mas Jesus voltou-se para eles e os repreendeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Então eles foram para outra vila.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Enquanto iam pelo caminho, alguém Lhe falou: “Eu Te seguirei para onde quer que fores”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Jesus disse-lhe: “As raposas têm suas tocas e os pássaros do céu seus ninhos, mas o Filho do homem não tem onde reclinar a cabeça”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Então Ele disse a outra pessoa: “Segue-me”. Mas ele respondeu: “Senhor, permita-me primeiro sepultar o meu pai”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Mas Ele lhe disse: “Deixa que os mortos sepultem seus próprios mortos, tu, porém, vai e proclama em todo o lugar o reino de Deus”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Outra pessoa também disse: “Eu vou te seguir, Senhor, mas me permita primeiro despedir-me dos de minha casa”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Mas Jesus disse-lhe: “Ninguém que, tendo posto a mão no arado e fica olhando para trás, é apto para o Reino de Deus”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Depois disso, o Senhor designou outros setenta e os enviou, de dois em dois, à Sua frente a todas as cidades e lugares aonde Ele pretendia ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'E dizia-lhes: “A colheita é grande, mas os trabalhadores são poucos. Por isso rogai ao Senhor da colheita, para que Ele envie trabalhadores para a Sua colheita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Ide! Eis que Eu vos envio como cordeiros no meio de lobos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Não leveis nenhum saco de dinheiro, nem bagagem de viagem, nem sandálias e não cumprimenteis a ninguém pelo caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Em qualquer casa que entrardes, dizei primeiro: 1\'Que a paz esteja nesta casa\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Se ali houver um filho da paz, a vossa paz repousará sobre ele, mas, se não houver, ela voltará sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Permanecei na mesma casa, comendo e bebendo do que eles tiverem, porque o trabalhador merece receber o seu salário. Não fiqueis mudando de casa em casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Em qualquer cidade que entrardes, e vos receberem, comei do que puserem diante de vós');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'e curai os enfermos que lá estiverem. Dizei-lhes: \'O Reino de Deus é chegado a vós\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Mas, em qualquer cidade em que entrardes, e não vos receberem, saí para as ruas e dizei:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, '\'Até mesmo a poeira de vossa cidade que se agarrou a nossos pés, sacudimos contra vós! Mas sabei disto, que o Reino de Deus está próximo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Eu vos digo que, no dia do julgamento, haverá mais tolerância para Sodoma do que para aquela cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Ai de ti, Corazim! Ai de ti, Betsaida! Porque, se os milagres que foram feitos em vós tivessem sido feitos em Tiro e Sidom, há muito tempo que eles teriam se arrependido e se assentado sobre cinzas, em panos de saco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Contudo, haverá mais tolerância para Tiro e Sidom no juízo do que para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Tu, Cafarnaum, tu achas que serás elevada até o céu? Do contrário, tu serás levada para baixo, ao Hades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Os que vos ouvem, ouvem a Mim; e quem lhes rejeita, a Mim me rejeita; e os que Me rejeitam também rejeitam aquele que Me enviou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Os setenta (e dois) voltaram com alegria, dizendo: \"Senhor, até os demônios se submeteram ao Teu nome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Jesus lhes disse: “Eu via Satanás caindo do céu como um relâmpago.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Eu vos dei autoridade para pisar serpentes e escorpiões, e sobre todo o poder do inimigo, e nada irá de maneira alguma lhe causar dano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'No entanto, não vos alegreis no fato de os espíritos se submeterem a vós, mas regozijai-vos ainda mais por seus nomes estarem gravados nos céus”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'Naquele momento, Ele exultou no Espírito Santo, dizendo: “Eu te louvo, ó Pai, Senhor do céu e da terra, porque Tu ocultaste essas coisas dos que são sábios e cultos, mas as revelaste àqueles que são ignorantes como pequenas crianças. Sim, ó Pai, porque assim foi agradável à Tua vista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Todas as coisas Me foram confiadas pelo Meu Pai, e ninguém conhece quem é o Filho senão o Pai, e ninguém conhece quem é o Pai senão o Filho e aqueles a quem o Filho quiser revelar”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'E, voltando-se para os discípulos, Ele lhes disse em particular: “Bem-aventurados são aqueles que veem as coisas que vedes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Pois Eu vos digo que muitos profetas e reis desejaram ver as coisas que vedes, mas não puderam vê-las; ouvir as coisas que ouvis, e não ouviram”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'E eis que certo mestre da Lei Judaica levantou-se para testá-Lo, dizendo: “Mestre, o que devo fazer para herdar a vida eterna?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Jesus disse-lhe: “O que está escrito na Lei? Como é que lês?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Ele, então, respondeu: “Amarás ao Senhor teu Deus com todo o teu coração, com toda a tua alma, com toda a tua força, e com todo o teu entendimento, e ao teu próximo como a ti mesmo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Jesus disse-lhe: “Respondeste corretamente. Faze isso e viverás”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Mas o mestre, querendo justificar-se, perguntou a Jesus: “E quem é o meu próximo?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Em resposta, disse Jesus: “Certo homem descia de Jerusalém para Jericó, ele caiu nas mãos de ladrões que sacaram seus pertences, bateram nele e o deixaram quase morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'E por acaso um sacerdote estava descendo por aquele caminho e, quando o viu, passou pelo outro lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Semelhantemente um levita, quando chegou até o lugar e o viu, também passou pelo outro lado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Mas um samaritano que ia de viagem chegou perto dele e, vendo-o, encheu-se de compaixão');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'e, aproximando-se dele, enfaixou suas feridas, derramando azeite e vinho sobre elas. Ele o colocou sobre o seu próprio animal, levou-o para uma hospedaria e cuidou dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'No dia seguinte, tirou dois denários, deu-os ao hospedeiro e disse: ‘Cuida dele, e qualquer despesa extra que tiveres, quando eu voltar, eu te reembolsarei’.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Qual dos três, em tua opinião, foi o próximo daquele que caiu nas mãos dos ladrões?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'O mestre da Lei disse: “Aquele que usou de misericórdia para com ele”. Jesus lhe disse: “Vai e faça o mesmo.”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Enquanto Jesus e seus discípulos viajavam, eles entraram numa vila, e uma certa mulher chamada Marta os recebeu em sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Ela tinha uma irmã chamada Maria, a qual ficou sentada aos pés do Senhor e ouviu a Sua Palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Marta, estava extremamente ocupada preparando a refeição para servir. Ela veio até Jesus, e disse: “Senhor, não Te importas que minha irmã me deixou servindo sozinha? Dize-lhe, portanto, que me ajude”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Mas o Senhor respondeu, e disse-lhe: “Marta, Marta, estás ansiosa sobre muitas coisas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'mas só uma coisa é necessária. Maria escolheu o que era bem melhor, e essa parte não lhe será tomada”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'E aconteceu que, estando Jesus em certo lugar orando, e ao terminar um dos Seus discípulos Lhe disse: “Senhor, ensina-nos a orar, assim como João ensinou a seus discípulos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Disse-lhes Jesus: “Quando orardes, dizei: \'Pai, santificado seja o Teu Nome. Venha o Teu reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Dá-nos o pão que diariamente precisamos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'perdoa os nossos pecados, assim como nós perdoamos aos nossos devedores. Livra-nos da tentação\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Disse-lhes Jesus: “Quem dentre vós, se tiver um amigo e indo a meia noite até ele, dizendo: \'Amigo, empresta-me três pães,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'pois um amigo meu acabou de chegar de viagem e eu não tenho nada para lhe oferecer\';');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'e, o que está dentro lhe responda: \'Não me importunes, pois a porta já está fechada e meus filhos e eu estamos na cama. Eu não posso me levantar e dá-los a ti\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Eu lhes digo, mesmo que ele não se levante para dar-lhe os pães por serem amigos, ainda assim ele se levantará por causa da sua importuna persistência, e lhe dará todos os pães que forem necessários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Eu também vos digo: pedi e vos será dado, buscai e encontrareis, batei e vos será aberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Pois todo o que pede, recebe; o que busca, encontra; e quem bate, lhe será aberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Qual pai dentre vós, se o filho pedir um peixe, no lugar do peixe lhe dará uma serpente?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Ou, se ele pedir um ovo, lhe dará um escorpião?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Portanto, se vós, que sois maus, sabeis dar coisas boas aos vossos filhos, quanto mais o vosso Pai do céu dará o Espírito Santo aos que O pedirem?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Em outro momento, Jesus estava expulsando um demônio que era mudo. Quando o demônio saiu, o mudo falou. A multidão ficou perplexa!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Mas algumas pessoas disseram: “É por Belzebu, o príncipe dos demônios, que Ele expulsa demônios”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Outros O testavam e buscavam Dele um sinal do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Mas Jesus, conhecendo os pensamentos deles, disse-lhes: “Todo reino dividido contra si mesmo é arruinado; e cai toda casa dividida contra si mesma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Se Satanás contra si mesmo estiver dividido, como o seu reino subsistirá? Pois vós dizeis que Eu expulso demônios por Belzebu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Se Eu expulso demônios por Belzebu, por quem então os expulsam vossos seguidores? Por causa disso, eles serão os vossos juízes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Mas, se é pelo dedo de Deus que Eu expulso os demônios, então o Reino de Deus chegou até vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Quando um homem forte, que está totalmente armado, guarda sua própria casa, seus bens estão seguros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Mas quando um homem mais forte o derrota, tira-lhe a armadura e distribui os seus bens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Aquele que não está comigo está contra mim, e aquele que comigo não ajunta, espalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Quando um espírito maligno sai de uma pessoa, vaga por lugares áridos e procura repouso. Não o encontrando, diz: \'Eu voltarei para a minha casa, de onde vim\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Tendo voltado, encontra a casa limpa e organizada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Logo, ele vai e leva consigo outros sete espíritos ainda piores, e todos eles habitam ali. Então, a última condição daquela pessoa, torna-se pior do que a primeira”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'E aconteceu que, dizendo Ele essas coisas, uma certa mulher no meio da multidão levantou a voz e Lhe disse: “Bendito é o ventre que Te gerou e os seios que Te amamentaram.”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Mas Ele disse: “Antes, benditos são aqueles que ouvem a Palavra de Deus e a guarda”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Enquanto a multidão se aglomerava, Ele começou a dizer: “Esta geração é uma geração perversa. Ela busca um sinal, mas nenhum sinal lhe será dado, exceto o sinal de Jonas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Pois assim como Jonas se tornou um sinal para os Ninivitas, assim também o Filho do Homem será um sinal para esta geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'A Rainha do Sul se levantará, no julgamento, junto com os homens desta geração e os condenará, pois ela veio dos confins da terra para ouvir a sabedoria de Salomão. Eis que alguém maior do que Salomão está aqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Os homens de Nínive se levantarão, no julgamento, com as pessoas desta geração e os condenarão, pois eles se arrependeram diante da pregação de Jonas. E eis aqui alguém maior do que Jonas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Ninguém, ao acender uma lâmpada, coloca-a dentro de um lugar escondido, ou debaixo de um cesto, mas sobre o candelabro, para que aqueles que entram possam ver a luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Teu olho é a lâmpada do corpo. Quando o teu olho é bom, todo o teu corpo fica iluminado. Mas quando o teu olho é mau, todo o teu corpo fica cheio de trevas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Portanto, cuide para que a luz que há em ti não seja trevas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Se, pois, todo o teu corpo for cheio de luz, sem parte alguma nas trevas, então todo o teu corpo será como uma lâmpada, quando o seu brilho te ilumina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Quando Ele terminou de falar, um fariseu O convidou para comer com Ele em sua casa, então Jesus foi e tomou lugar à mesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'O fariseu ficou admirado por Ele não ter Se lavado antes da refeição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Mas o Senhor lhe disse: “Vós, fariseus, limpais o exterior dos copos e vasilhas, mas o vosso interior está cheio de ganância e maldade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Homens insensatos! Por acaso aquele que fez o exterior não fez também o interior?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Dai aos pobres o que está dentro de vós, e tudo vos ficará limpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Mas ai de vós, fariseus, que entregueis o dízimo da hortelã e da arruda e das demais verduras, mas negligenciais a justiça e o amor de Deus. É necessário agir com justiça e amar a Deus, sem negligenciar as outras coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Ai de vós fariseus pois amais os primeiros lugares nas sinagogas e os respeitosos cumprimentos nas praças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Ai de vós, pois sois como sepulturas disfarçadas, e pessoas caminham sobre elas, sem perceber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'E um certo mestre da lei Lhe disse: “Mestre, o que dizes também nos insulta”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Jesus disse: “Ai de vós também, mestres da lei! Pois sobrecarregais os homens com cargas difíceis de suportar, mas não quereis tocá-las, nem mesmo com um de vossos dedos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Ai de vós, pois edificais túmulos para os profetas que vossos ancestrais mataram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Assim, concordais com os feitos de vossos ancestrais, e deles sois testemunhas; porque eles, por um lado, mataram os profetas, e vós edificais os túmulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Também por essa razão, a sabedoria de Deus disse: \'Eu lhes enviarei profetas e apóstolos, a alguns eles perseguirão e matarão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'Então esta geração será responsabilizada por todo o sangue dos profetas, derramado desde a fundação do mundo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'desde Abel até o sangue de Zacarias, que foi morto entre o altar e o santuário. Sim, eu vos digo, que tudo isso será requerido desta geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Ai de vós, mestres da lei, pois tomastes para vós a chave do conhecimento; vós mesmos não entrastes e ainda impedis os que estão entrando\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Depois que Jesus saiu dali, os escribas e fariseus começaram a hostilizá-Lo terrivelmente e interrogá-Lo a respeito de muitas coisas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'tramando a fim de apanhá-Lo em Suas próprias palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Enquanto isso, milhares de pessoas estavam reunidas ali, ao ponto de estarem até pisando umas nas outras. Ele começou a dizer, primeiro aos seus discípulos: “Cuidado com o fermento dos fariseus, que é a hipocrisia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Pois não há nada oculto que não venha a ser revelado e nada escondido que não venha a ser conhecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Então o que vós tiverdes dito às escuras será ouvido à luz e o que vós tiverdes falado aos ouvidos no interior das casas será proclamado de cima das casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Mas Eu vos digo, meus amigos, não temais aqueles que matam o corpo e que depois disso nada mais podem fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Mas Eu vos alertarei sobre quem deveis temer. Temei Aquele que, depois de ter matado, tem autoridade para lançar no inferno. Sim, eu vos digo, a Ele temei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Não são dois pardais vendidos por duas moedinhas? Ainda assim nenhum deles é esquecido diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Até mesmo os cabelos da vossa cabeça estão contados. Não temais. Vós sois mais valiosos que muitos pardais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Eu vos digo que todo aquele que Me confessar diante dos homens, o Filho do Homem também o confessará diante dos anjos de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'mas aquele que Me negar diante dos homens, será negado diante dos anjos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Aquele que falar uma palavra contra o Filho do Homem, isso lhe será perdoado, mas aquele que blasfemar contra o Espírito Santo, isso não lhe será perdoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Quando vos levarem diante das sinagogas, dos chefes e das autoridades, não vos preocupeis como falar em sua defesa ou o que ireis dizer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'pois o Espírito Santo vos ensinará naquela hora o que deveis dizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Então alguém da multidão Lhe disse: “Mestre, dize a meu irmão que divida a herança comigo.”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Jesus respondeu-lhe: “Homem, quem Me fez juiz ou mediador sobre vós?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Depois disse a multidão: “Cuidai para que vos guardeis de todos os desejos gananciosos, pois a vida de alguém não consiste na abundância de seus bens.”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Então Jesus contou-lhes uma parábola: “O campo de um homem rico produziu abundantemente');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'e ele pensou consigo mesmo: \'Eu não tenho espaço para armazenar toda a minha colheita. O que farei?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Ele disse: \'Isso é o que farei, derrubarei meus celeiros e construirei outros maiores para armazenar todos os meus grãos e outros bens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Direi a minha alma: \'Alma, tens muitos bens armazenados para muitos anos. Descansa tranquila, come, bebe e alegra-te.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Mas Deus disse a ele: \'Louco! Esta noite te pedirão a tua alma e o que tens preparado, para quem será?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Assim é alguém que armazena tesouros para si e não é rico para com Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Jesus disse aos seus discípulos: “Portanto Eu vos digo que não vos preocupeis com vossas vidas, quanto ao que haveis de comer; ou com os vossos corpos, quanto ao que haveis de vestir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Pois a vida é mais do que comida e o corpo mais do que vestimentas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Considerai os corvos. Eles não semeiam nem colhem. Eles não têm despensa nem celeiro, mas Deus os alimenta. Quanto mais valeis vós do que as aves!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'E qual de vós que, por estar ansioso, pode acrescentar um côvado à sua vida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Se então vós não sois capazes de fazer nem mesmo as mínimas coisas, por que vos preocupais com as demais?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Considerai os lírios e como eles crescem. Eles não trabalham nem fiam. Contudo eu vos digo que nem mesmo Salomão, em toda a sua glória, se vestiu como um deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Se assim Deus veste a erva do campo que hoje existe e amanhã é lançada no forno, muito mais vestirá a vós, ó homens de pouca fé!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Não busqueis o que comer ou o que beber, não fiqueis ansiosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Pois todas as nações do mundo buscam essas coisas e seu Pai sabe que vós precisais delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Antes buscai o Seu Reino e essas coisas vos serão acrescentadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Não temas, pequeno rebanho, pois é do agrado do Pai dar-vos o Reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Vendei vossos bens e deem aos pobres. Fazei para si bolsas que não envelhecem, tesouros inesgotáveis nos Céus, onde os ladrões não se aproximam e nem traça destrói.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Pois onde está o vosso tesouro, ali estará também o vosso coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Deixai vossas vestes presas por seus cintos, em prontidão para servir e mantenham suas lâmpadas acesas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Sede semelhantes a pessoas esperando seu mestre retornar da festa de casamento, para que, quando ele chegar e bater, eles abram a porta imediatamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Bem-aventurados aqueles servos que forem encontrados vigiando quando o senhor vier. Verdadeiramente eu vos digo que ele prenderá suas longas vestes em seu cinto, os fará sentar para uma refeição, então virá e os servirá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Se o senhor vier na segunda vigília da noite, ou até mesmo na terceira e os achar prontos, bem aventurados serão aqueles servos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Sabei também que: se o senhor da casa soubesse a hora em que o ladrão viria, ele não permitiria que sua casa fosse arrombada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Estai vós também preparados, pois não sabeis a hora em que o Filho do Homem virá”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Pedro disse: “Senhor, estás a contar esta parábola somente para nós, ou também a todos?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'O Senhor disse: “Quem é o administrador fiel e sábio, a quem seu senhor confiará seus criados para lhes dar suas porções de comida no tempo certo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Bem-aventurado aquele servo a quem o seu senhor encontrar fazendo isto quando ele vier.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Verdadeiramente eu vos digo que a ele confiará todos os seus bens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Mas se aquele servo diz em seu coração: \'Meu senhor demora para voltar\' e começar a bater nos servos e servas, a comer, a beber, e a embriagar-se;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'o senhor daquele servo virá em um dia em que ele não espera, em uma hora que ele não sabe, o castigará e o porá em um lugar com os incrédulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Aquele servo que, sabendo da vontade do seu senhor, não tiver se preparado ou feito de acordo com sua vontade, será açoitado com muitos golpes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Mas aquele que não sabia e tiver feito coisas dignas de castigo, será açoitado com poucos golpes. A todo pois que muito for dado, muito lhe será exigido, e aquele a quem muito for confiado, muito mais lhe será pedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Eu vim lançar fogo sobre a terra e como Eu queria que já estivesse aceso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Mas Eu tenho um batismo com o qual hei de ser batizado e como estou angustiado até que ele seja cumprido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Vós achais que eu vim trazer paz à terra? Eu digo que não, pois vim trazer divisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'A partir de agora haverá cinco em uma casa divididos: três pessoas contra duas e duas contra três.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Eles estarão divididos: Pai contra filho e filho contra pai, mãe contra filha e filha contra mãe, sogra contra nora e nora contra sogra”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Jesus também dizia às multidões: “Quando vedes uma nuvem vindo do oeste, imediatamente vós dizeis: \'Uma chuva está vindo\' e assim acontece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'E quando o vento sul está soprando, dizeis: \'Haverá um calor abrasador\', e acontece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Hipócritas, vós sabeis discernir os sinais da terra e do céu, entretanto vós não sabeis discernir o que está acontecendo no tempo presente?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Por que não julgais o que é justo para vós mesmos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Quando fores com o teu adversário diante do magistrado, esforça-te para resolver o problema com ele no caminho, para que ele não te arraste ao juiz, e o juiz te entregue nas mãos do carcereiro e o carcereiro te jogue na prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Eu te digo que de modo algum sairás dali enquanto não pagares até o último centavo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Naquela ocasião algumas pessoas contaram a Jesus sobre os galileus, cujo sangue Pilatos havia misturado com os seus próprios sacrifícios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Disse-lhes Jesus: “Vós pensais que esses galileus são mais pecadores do que eram todos os outros galileus porque sofreram desta maneira?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Eu vos digo que não. Mas se não vos arrependerdes, todos vós perecereis de igual maneira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Ou aqueles dezoito sobre os quais caiu a torre de Siloé e os matou, pensais vós que eles eram mais culpados que os outros homens de Jerusalém?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Eu vos digo que não. Mas se não vos arrependerdes, todos vós também perecereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'E Jesus disse essa parábola: “Certo homem tinha uma figueira plantada em sua vinha. E vindo procurar nela fruto, não encontrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Então disse ao homem que trabalhava na vinha: \'Vede, há três anos eu venho procurar frutos nesta figueira e não encontro. Corta-a! Por que deixá-la desgastar o solo?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Este lhe respondeu: “Deixa-a ainda este ano, para que eu escave ao redor dela e a adube.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Se ela der fruto no próximo ano, está bem. Caso contrário, corta-a!”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Ora, Jesus estava ensinando em uma das sinagogas, durante um sábado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Eis que se encontrava ali uma mulher que há dezoito anos tinha um espírito de enfermidade; ela estava completamente encurvada, e não podia ficar de pé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Vendo-a Jesus, chamou-a e disse: “Mulher, estás livre da tua enfermidade”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Ele impôs as mãos sobre ela, e imediatamente ela se endireitou e dava glórias a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Mas, o chefe da sinagoga ficou indignado por Jesus ter curado num dia de Sábado. Então o chefe disse à multidão que ali estava: “Há seis dias em que se deve trabalhar. Vinde, pois, e sejais curados nesses dias, e não no Sábado”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'O Senhor lhe respondeu dizendo: “Hipócritas! Quem de vós não solta da manjedoura o jumento ou o boi e o leva para beber água no Sábado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Então, esta filha de Abraão, a quem Satanás aprisionou por dezoito anos, não convinha ter suas amarras desatadas no dia de Sábado?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Quando Ele disse essas coisas, todos os que se opuseram a Ele ficaram envergonhados, mas a multidão inteira se regozijava de alegria com todos os gloriosos feitos que Ele realizava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Então, disse-lhes Jesus: “A que se assemelha o Reino de Deus e a que o compararei?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Ele é como uma semente de mostarda que um homem pegou e lançou na sua horta; e ela cresceu e se tornou uma grande árvore, e as aves do céu construíram ninhos em seus ramos”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'E novamente disse-lhes Jesus: “A que pode ser comparado o Reino de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Ele é como o fermento que uma mulher tomou e misturou com três medidas de farinha até que tudo ficasse fermentado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Jesus visitava e ensinava em cada cidade e vila no caminho para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Alguém lhe perguntou: “Senhor, são poucos os que serão salvos?\". Então disse-lhes Jesus:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, '“Esforçai-vos para entrar pela porta estreita, pois vos digo que muitos procurarão entrar e não poderão”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Uma vez que o dono da casa se levantar e fechar a porta, então vós ficareis de fora batendo na porta e dizendo: \'Senhor, Senhor, deixa-nos entrar!\'. E Ele vos dirá: \'Eu não vos conheço e não sei de onde sois\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Então direis: \'Comíamos e bebíamos contigo e Tu nos ensinavas nas ruas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Mas Ele responderá: \'Digo-vos que não sei de onde sois. Afastai-vos de mim, vós que praticais a injustiça!\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'E haverá choro e ranger de dentes quando virdes Abraão, Isaque e Jacó e todos os profetas no Reino de Deus, mas vós lançados fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Eles virão do leste e do oeste, do norte e do sul, e sentarão à mesa no Reino de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'E eis que há últimos que serão os primeiros e primeiros que serão últimos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Pouco tempo depois, alguns fariseus vieram até Ele e disseram: \"Vai embora daqui porque Herodes quer te matar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Jesus disse: \"Ide dizer àquela raposa: \'Eis que expulso demônios e realizo curas hoje e amanhã, e no terceiro dia terei consumado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Porém é necessário que eu prossiga hoje, amanhã, e no dia seguinte, pois não convém que um profeta pereça fora de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jerusalém, Jerusalém, que matas os profetas e apedrejas aqueles que te foram enviados. Quantas vezes eu desejei ajuntar teus filhos assim como uma galinha ajunta seus pintinhos debaixo de suas asas, mas tu não o quiseste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Eis que a vossa casa ficará abandonada. Eu vos digo que não me vereis até o momento em que direis: \"Bendito é aquele que vem em nome do Senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'E aconteceu que num sábado, quando Ele entrou na casa de um dos líderes dos fariseus para comer pão, eles o estavam observando com atenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Eis que havia diante Dele um homem que sofria de edema.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Jesus perguntou aos mestres da lei judaica e aos fariseus: \"É permitido curar no sábado, ou não?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Mas eles se mantiveram em silêncio. Então Jesus tomou-o, curou-o e o mandou ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'E disse-lhes: \"Qual de vós, se o seu filho ou seu boi cair em um poço, não irá imediatamente retirá-lo de lá, mesmo num dia de sábado?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Diante disso, eles nada puderam responder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Quando Jesus observou como aqueles que haviam sido convidados para uma festa escolhiam os assentos de honra, contou-lhes uma parábola, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '\"Quando fores convidado para uma festa de casamento, não te assentes no lugar de honra, pois alguém mais honrado que tu pode ter sido convidado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'Para que não aconteça que, quando a pessoa que convidou a ti e a ele, venha a te dizer: \'Dê o lugar a este\'. E então, envergonhado, tu terás de assentar-te no último lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Pelo contrário, quando fores convidado, vai e assenta-te no último lugar, para que, quando aquele que te convidou vier, te diga: \'Amigo, ocupa um lugar mais elevado\'. Então serás honrado na presença de todos os convidados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Pois todo aquele que se exalta será humilhado, e todo aquele que se humilha será exaltado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Jesus também disse ao homem que o convidou: \"Quando ofereceres um jantar ou uma ceia, não convides teus amigos, nem teus irmãos, nem teus parentes, nem teus vizinhos ricos, de tal forma que eles também te convidem e te retribuam do mesmo modo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Pelo contrário, quando ofereceres uma festa, convida os pobres, os aleijados, os paralíticos e os cegos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'e serás abençoado, porque eles não terão como te retribuir. Tu serás retribuído no dia da ressurreição dos justos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Ao ouvir isso, um dos que estavam com Jesus à mesa, disse-lhe: \"Bem-aventurado é aquele que comer pão no Reino de Deus!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Jesus, porém, respondeu-lhe: \"Certo homem preparou uma grande ceia e convidou a muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'À hora da ceia, ele enviou seu servo para dizer àqueles que haviam sido convidados: \'Vinde, pois tudo já está pronto\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Mas todos, sem exceção, começaram a se desculpar. O primeiro disse-lhe: \'Comprei um campo e preciso vê-lo. Por favor, me desculpe\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Outro disse: \'Comprei cinco juntas de boi, e vou experimentá-las. Por favor, me desculpe\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Ainda outro disse: \'Casei-me, por isso não posso ir\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'O servo voltou e anunciou todas essas coisas ao seu senhor. Então o senhor da casa, indignado, disse ao seu servo: \'Sai depressa pelas ruas e becos da cidade, traz até aqui os pobres, os paralíticos, os cegos e os aleijados e faze-os entrar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'O servo disse: \'Senhor, o que me mandou fazer foi feito, e ainda há lugar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'O senhor disse ao seu servo: \'Vai pelas estradas e vielas e obriga as pessoas a entrarem, para que a minha casa fique cheia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Eu te digo que nenhum daqueles que foram convidados provará minha ceia\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Grandes multidões O acompanhavam. E Jesus voltando-se, disse-lhes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '“Se alguém vem a Mim e não odeia seu próprio pai, mãe, esposa, filhos, irmãos e irmãs e até mesmo a sua própria vida, não pode ser Meu discípulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Quem não carrega a sua própria cruz e Me segue não pode ser meu discípulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Pois qual de vós, querendo construir uma torre, primeiro não se assenta para calcular os custos e ver se tem o que precisa para completá-la?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Para não acontecer que, tendo colocado o alicerce e não sendo capaz de concluir, todos aqueles que virem a situação comecem a caçoar dele, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, '\'Este homem começou a construir e não foi capaz de terminar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Ou qual é o rei que, partindo para combater outro rei, não senta primeiro para se aconselhar sobre se é capaz de, com dez mil homens, lutar contra o outro rei que vem contra ele com vinte mil homens?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'E, se não for capaz, enquanto o outro exército estiver ainda distante, ele envia uma delegação para pedir condições de paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Assim, qualquer que entre vós não renuncia tudo quanto tem não pode ser Meu discípulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'O sal é bom, mas, se o sal perder o sabor, como se poderá restaurar-lhe o sabor?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Não presta nem para o solo nem para adubo. É jogado fora. Aquele que tem ouvidos para ouvir, ouça”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'E todos os cobradores de impostos e outros pecadores se aproximavam para ouvir Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Os fariseus e os escribas murmuravam entre si, dizendo: “Este homem acolhe os pecadores e até come com eles”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Então Jesus contou a seguinte parábola:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '“Qual de vós que, possuindo cem ovelhas e em seguida perdendo uma delas, não deixa as noventa e nove no deserto e não vai atrás da perdida até que a encontre?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'E, quando a encontra, a coloca sobre os ombros e regozija.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'E quando ele chega em casa, convida os amigos e vizinhos, dizendo-lhes: \'Regozijai-vos comigo, porque achei a minha ovelha perdida\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Digo-vos que, de igual maneira, haverá grande alegria no céu por um pecador que se arrepende, mais do que por noventa e nove justos que não necessitam de arrependimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Ou qual é a mulher que, tendo dez moedas de prata, se vier a perder uma delas, não acende uma lâmpada, varre a casa e busca diligentemente até que a encontre?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'E quando ela a encontra, reúne as amigas e vizinhas, dizendo: \'Regozijai-vos comigo, porque achei a moeda que eu perdi\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Da mesma maneira, eu vos digo, há júbilo na presença dos anjos de Deus por um só pecador que se arrepende”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Então Jesus disse: “Um homem tinha dois filhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'o mais novo deles disse ao pai: \'Pai, dá-me a parte dos bens que é minha por herança\'. Assim, ele repartiu seu patrimônio entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Não muitos dias depois, o filho mais novo ajuntou tudo o que tinha, viajou para uma terra distante e ali desperdiçou seus bens comprando o que não precisava e gastando seu dinheiro com extravagâncias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'E, quando gastou tudo, houve uma grande fome naquele país, e ele começou a passar necessidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Ele começou a trabalhar para um dos cidadãos daquele país, que o enviou para seus campos, a fim de cuidar dos porcos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'E desejava comer as alfarrobas que os porcos comiam, pois ninguém dava comida para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Mas ele caiu em si e disse: \'Quantos empregados de meu pai têm mais que suficiente para comer, e eu aqui morrendo de fome!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Irei ao meu pai e lhe direi: Pai, pequei contra o céu e contra ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'Não sou digno de ser chamado teu filho, trata-me como um dos teus empregados\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Então o jovem partiu e foi ao seu pai. Enquanto ainda estava distante, o pai o avistou e, cheio de compaixão, correu em direção a ele, o abraçou e o beijou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'E o filho disse: \'Pai, pequei contra o Céu e contra ti, não sou digno de ser chamado teu filho\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Então o pai disse aos seus empregados: \'Ide depressa e trazei a melhor túnica e cobri-o, colocai um anel em seu dedo e sandálias nos seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Trazei também o novilho gordo e matai-o; comamos e celebremos uma festa!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Pois meu filho estava morto e agora vivo está. Estava perdido e foi encontrado\'. E todos celebraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Enquanto isso o seu filho mais velho trabalhava no campo. Ao aproximar-se da casa, escutou barulho de música e dança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Ele chamou um empregado e perguntou o que estava acontecendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'O empregado respondeu: \'Seu irmão regressou para casa e, por esse motivo, seu pai matou o novilho mais gordo, porque ele retornou saudável e em segurança\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'O filho mais velho ficou irado e não quis entrar. Então seu pai saiu e implorou para que ele entrasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Mas o filho lhe respondeu, dizendo: \'Eis que todos esses anos trabalhei para ti como um escravo e nunca quebrei nenhuma de tuas regras; mesmo assim, o senhor nunca me deu um cabrito para eu fazer uma festa com meus amigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Mas, quando o teu filho, que gastou todos os teus bens com prostitutas, regressou, o senhor matou para ele o novilho mais gordo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Mas o pai respondeu-lhe: \'Filho, tu sempre estás comigo e tudo o que é meu é teu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Mas nós tínhamos que festejar e nos alegrar, porque teu irmão estava morto e agora está vivo, estava perdido e foi encontrado\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Jesus também disse aos seus discípulos: \"Havia um certo homem rico o qual tinha um administrador, esse foi denunciado de desperdiçar os bens dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Então o homem rico o chamou e disse: \'O que é isso que ouço falar a teu respeito? Presta contas da tua administração, pois tu não podes ser mais administrador\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'O administrador disse consigo mesmo: \'O que farei, já que o meu senhor está me tirando do trabalho de administrador? Eu não tenho forças para cavar e tenho vergonha de pedir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Sei o que farei para que, quando eu for removido da administração, as pessoas venham me receber em suas casas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Então o administrador chamou cada um dos devedores do seu senhor e perguntou ao primeiro: \'Quanto deves ao meu senhor?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Ele disse: \'Cem batos de óleo de oliva\'. E o administrador lhe disse: \'Toma a tua conta, senta-te depressa e escreve que deves cinquenta\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Então o administrador disse ao outro: \'E tu quanto deves?\'. E este lhe respondeu: \'Cem coros de trigo\'. Ele lhe disse: \'Toma a tua conta e escreve oitenta\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'O senhor elogiou o administrador corrupto, porque ele agiu com astúcia. Pois os filhos deste mundo são mais astutos para com seu próprio povo do que os filhos da luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Eu vos digo: \'Fazei amigos para si mesmos por meio de riquezas injustas, para que quando elas acabarem, eles vos recebam nas moradas eternas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Quem é fiel no pouco também é fiel no muito, e quem é injusto no pouco também é injusto no muito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Sendo assim, se não fostes fiel usando as riquezas desse mundo, quem irá confiar a ti as verdadeiras riquezas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Se não fostes fiel com o dinheiro de outras pessoas, quem vos dará o vosso?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Nenhum servo pode servir a dois senhores, ou ele odiará um e amará o outro, ou ele se apegará a um e desprezará o outro. Não podeis servir a Deus e as riquezas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Quando os fariseus, que eram amantes do dinheiro, ouviam essas coisas, ridicularizavam-no.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Mas Ele disse: “Vós vos justificais uns perante os outros, mas Deus conhece vossos corações. O que é exaltado entre os homens é detestável diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'A Lei e os profetas vigoraram até a chegada de João. Desde então, o evangelho do Reino de Deus é pregado, e todos se esforçam para entrar nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Porém é mais fácil passar o céu e a terra do que um só acento de uma letra da Lei ser invalidada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Aquele que repudiar sua mulher e casar-se com outra comete adultério, e quem se casa com a repudiada comete adultério.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'E havia um homem rico, que se vestia de púrpura e linho fino e desfrutava diariamente de sua grande riqueza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Um pobre chamado Lázaro, estava jogado à sua porta, cheio de feridas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Ele desejava comer do que caía da mesa do homem rico e até os cães vinham lamber suas feridas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Aconteceu que o pobre morreu e foi levado pelos anjos para o seio de Abraão. O rico também morreu, foi sepultado');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'e no Hades, sendo atormentado, ele ergueu os olhos e de longe viu Abraão e Lázaro reclinado no seio dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Então ele clamou, dizendo: \'Pai Abraão, tem compaixão de mim, manda Lázaro molhar a ponta de seu dedo e com água resfrescar minha língua, porque estou aflito nesta chama\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Porém Abraão disse: \'Filho, lembra-te que, enquanto estavas vivo, tu recebestes as coisas boas, por outro lado Lázaro recebeu as coisas más. Mas agora Lázaro está consolado aqui, enquanto tu estás em agonia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Além do mais, um grande abismo foi colocado, para que aqueles que queiram cruzar daqui para o teu lado não consigam, e ninguém será capaz de cruzar daí para o nosso lado\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'O homem rico disse: \'Eu te imploro pai Abraão, que o senhor o envie à casa de meu pai,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'pois eu tenho cinco irmãos e quero que eles sejam avisados sobre este lugar de tormento, pois eu temo que eles terminem aqui\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Mas Abraão disse: \'Eles tem Moisés e os Profetas, deixa que eles os ouçam\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'E o homem rico respondeu: \'Não pai Abraão, mas se alguém dentre os mortos for até eles, arrepender-se-ão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Disse Abraão: \'Se eles não ouvem a Moisés e aos Profetas, tão pouco serão persuadidos por alguém que ressuscite dos mortos\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Jesus disse aos Seus discípulos: \"É inevitável que escândalos venham, mas ai daquele por meio do qual essas coisas acontecem!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Melhor seria se uma pedra de moinho fosse amarrada no seu pescoço, e ele lançado ao mar, do que fazer tropeçar a um desses pequeninos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Ficai atentos. Se o teu irmão pecar, repreende-o; se ele se arrepender, perdoa-lhe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'Se ele pecar sete vezes contra ti no mesmo dia e se sete vezes retornar dizendo: \'Estou arrependido\', perdoa-lhe!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Os apóstolos disseram ao Senhor: \"Aumenta em nós fé!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'O Senhor respondeu: \"Se tivésseis fé como um grão de mostarda, diríeis a esta amoreira: \'Arranca-te pela raiz e planta-te no mar\' e ela vos obedeceria!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'E quem dentre vós, tendo um servo que trabalha a terra ou guarda os animais, lhe dirá quando ele voltar do campo: \'Vem logo e senta-te para comer\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Ao contrário, não lhe dirá: \'Prepara-me a refeição, apronta-te, ponha um cinto em torno das tuas vestes e serve-me, até que eu tenha comido e bebido, e depois comerás e beberás\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Será que ele deve agradecer ao servo porque este fez o que lhe foi ordenado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Assim também vós quando fizerdes tudo o que vos foi ordenado, dizei: \'Somos servos inúteis, fizemos apenas o que devíamos fazer\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'A caminho de Jerusalém, Jesus passava pela divisa entre Samaria e a Galileia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Entrando em uma certa aldeia, saíram-lhe ao encontro dez homens leprosos. Eles pararam distante Dele');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'e gritaram, dizendo: \"Jesus, Mestre, tem misericórdia de nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Ao vê-los, disse-lhes: \"Ide e mostrai-vos aos sacerdotes\". E aconteceu que no caminho ficaram limpos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Um deles, vendo que fora curado, voltou, glorificando a Deus em alta voz,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'e prostrou-se aos pés de Jesus, dando-Lhe graças. Este era um samaritano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Então Jesus perguntou: \"Não foram dez os curados? Onde estão os nove?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Não houve outro que voltasse para dar glória a Deus, exceto este estrangeiro?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'E disse-lhe: \"Levanta-te, vai, a tua fé te salvou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Certa vez, quando os fariseus perguntaram quando o Reino de Deus viria, Jesus respondeu-lhes: \"A vinda do Reino de Deus não é algo que possa ser observado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Nem dirão: \'Está aqui!\' ou: \'Está ali!\', porque o Reino de Deus está entre vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Jesus disse aos discípulos: \"Virão dias em que desejareis ver um dos dias do Filho do Homem, e não o vereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'E eles vos dirão: \'Está aqui! Está ali! \'Não saiais, nem os sigais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Pois como o relâmpago brilha fortemente de uma extremidade a outra do céu, assim também será o Filho do Homem no Seu dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Mas primeiro Ele tem que sofrer muitas coisas e ser rejeitado por esta geração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Assim como aconteceu nos dias de Noé, também acontecerá nos dias do Filho do Homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Comiam, bebiam, casavam e davam-se em casamento, até o dia em que Noé entrou na arca, e veio o dilúvio e destruiu a todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Do mesmo modo como aconteceu nos dias de Ló: comiam, bebiam, compravam, vendiam, plantavam, construíam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'Mas, no dia em que Ló saiu de Sodoma, choveu fogo e enxofre do céu e destruiu a todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Assim será no dia em que o Filho do Homem for revelado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Naquele dia, quem estiver no terraço e tiver os seus bens em casa, não desça para buscá-los. E aquele que estiver no campo não volte atrás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Lembrai-vos da mulher de Ló.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Quem procura ganhar a sua vida irá perdê-la, mas quem perder a sua vida irá salvá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Digo-vos, naquela noite dois estarão numa cama, um será levado e outro será deixado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Duas mulheres estarão moendo grãos juntas, uma será levada e a outra será deixada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, '.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'E Lhe perguntaram: \"Onde, Senhor?\". Respondeu-lhes: \"Onde há um corpo, ali os abutres também se ajuntarão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Então Jesus contou uma parábola sobre como eles deveriam sempre orar e nunca desanimar:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, '\"Havia numa cidade um juiz que não temia a Deus nem respeitava as pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'E havia, na mesma cidade, uma viúva que constantemente vinha ter com ele, dizendo: \'Faze-me justiça contra o meu adversário\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Por muito tempo, ele não estava disposto a ajudá-la, mas depois disse a si mesmo: \'Embora eu não tema a Deus nem respeite os homens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'por causa dessa viúva que me aborrece, vou tratar de fazer justiça, de modo que ela pare de me incomodar\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Então disse o Senhor: \"Escutai o que diz o juiz injusto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Não fará Deus justiça aos Seus escolhidos, que clamam a Ele dia e noite, mesmo que demore em ajudá-los?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Digo-vos que Ele rapidamente lhes fará justiça. Contudo, quando o Filho do homem vier, encontrará fé sobre a terra?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Então Jesus contou a seguinte parábola para alguns que, convencidos de serem justos, desprezavam os outros:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '\"Dois homens subiram ao templo para orar, um era fariseu e o outro era um cobrador de impostos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'O fariseu, posto em pé, consigo mesmo estas coisas orava: \'Deus, eu Te agradeço porque não sou como os demais homens, ladrões, injustos, adúlteros e nem como este cobrador de impostos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Jejuo duas vezes por semana e dou dízimo de tudo quanto ganho\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Mas o cobrador de impostos, de pé, a distância, sem ousar levantar os olhos ao céu, batia em seu peito, dizendo: \'Deus, tem misericórdia de mim, pecador\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Digo-vos que este homem retornou para sua casa justificado e o outro não, pois todo aquele que se exalta será humilhadom e todo aquele que se humilha será exaltado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'As pessoas também traziam-Lhe criancinhas, para que Ele as tocasse, mas quando os discípulos viram isso, as repreenderam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Mas Jesus chamou-as dizendo: \"Deixai vir a Mim as criancinhas, não as impeçais. Porque delas é o reino de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Em verdade vos digo, aquele que não receber o reino de Deus como uma criança, de maneira alguma entrará nele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Certo homem de posição perguntou-Lhe: \"Bom Mestre, o que devo fazer para herdar a vida eterna?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'E Jesus respondeu a ele: \"Por que me chamas bom? Ninguém é bom, a não ser um, que é Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Tu sabes os mandamentos: não cometas adultério, não mates, não roubes, não dês falso testemunho, honra teu pai e tua mãe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'E ele disse: \"Tudo isso tenho obedecido desde a minha juventude\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'E Jesus ouvindo isso disse-lhe: “Uma coisa ainda te falta: vende tudo o que tens, distribui aos pobres e terás tesouro nos céus; depois, vem e segue-me\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Mas, ouvindo estas coisas, o homem ficou muito triste, pois era extremamente rico.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Então, ao ver a tristeza do homem, Jesus disse: \"Como é difícil para os que têm riquezas entrar no reino de Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Pois é mais fácil um camelo passar pelo fundo de uma agulha do que um rico entrar no reino de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Os que ouviram isso perguntaram: \"Então, quem pode ser salvo?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Jesus respondeu: \"As coisas que são impossíveis para as pessoas são possíveis para Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'E Pedro disse: \"Nós deixamos tudo o que tínhamos e O seguimos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Então Jesus lhes disse: \"Em verdade vos digo que não há ninguém que tenha deixado casa, esposa, irmãos, pais ou filhos por causa do reino de Deus');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'que não receberá muito mais nesse tempo e, no mundo vindouro, a vida eterna\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'E tomando consigo os doze, lhes disse: \"Estamos subindo a Jerusalém e então se cumprirão todas as coisas que foram escritas pelos profetas acerca do Filho do Homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Pois Ele será entregue aos gentios e será zombado e insultado e cuspirão nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'Depois de açoitá-Lo, irão matá-Lo e ao terceiro dia Ele ressuscitará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Eles não entenderam nada dessas coisas, essa palavra lhes era obscura e não compreendiam o que fora dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Aconteceu que, quando Jesus se aproximava de Jericó, havia um cego sentado à beira do caminho, pedindo esmola.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Ouvindo ele uma multidão passar, perguntou o que estava acontecendo');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'e anunciaram-lhe que Jesus de Nazaré estava passando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Então o cego clamou, dizendo: \"Jesus, filho de Davi, tem misericórdia de mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Os que iam caminhando à frente o repreendiam para que se calasse. Mas ele gritava ainda mais: \"Filho de Davi, tem misericórdia de mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Jesus parou e ordenou que trouxessem o homem até Ele. Então, quando o cego se aproximou, Jesus perguntou-lhe:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, '\"O que queres que Eu te faça?\" Ele disse: \"Senhor, que eu torne a ver\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'E Jesus lhe disse: \"Torna a ver. A tua fé te salvou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Imediatamente ele recuperou a visão e O seguiu glorificando a Deus. Vendo isso a multidão também louvou a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Jesus entrou em Jericó e atravessava a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Eis que ali havia um homem chamado Zaqueu, que era chefe dos cobradores de impostos e era rico.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Ele tentava ver quem era Jesus, mas não conseguia vê-Lo por cima da multidão, pois era de baixa estatura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Então, Zaqueu correu à frente do povo e subiu num sicômoro para ver Jesus, pois Ele estava prestes a passar por ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Quando Jesus chegou àquele lugar, olhou para cima e disse-lhe: “Zaqueu, desce depressa porque hoje tenho que ficar em tua casa”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Então, ele desceu rapidamente e O recebeu cheio de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Quando as pessoas viram isso, indignaram-se, dizendo: “Ele foi visitar um homem pecador”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Zaqueu se levantou e disse ao Senhor: \"Olha, Senhor, a metade dos meus bens eu darei aos pobres e se defraudei alguém em qualquer coisa, eu lhe restituirei quatro vezes mais”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Jesus lhe disse: “Hoje a salvação chegou a esta casa, porque ele também é filho de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Pois o Filho do Homem veio para buscar e salvar os que estão perdidos”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Enquanto eles ouviam essas coisas, Jesus continuou a falar. Contou-lhes uma parábola, por estar se aproximando de Jerusalém e porque as pessoas pensavam que o Reino de Deus apareceria imediatamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Ele disse: \"Um certo homem nobre partiu para uma terra distante a fim de tomar posse de um reino e voltar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Ele chamou dez de seus servos, e deu-lhes dez minas e disse: \'Negociai até eu voltar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Mas seus concidadãos o odiaram e enviaram uma delegação atrás dele dizendo: \'Não queremos que este homem reine sobre nós\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Após ter sido coroado rei, retornou e ordenou que chamassem os servos a quem havia dado o dinheiro, para saber qual lucro haviam tido nos negócios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'O primeiro veio diante dele dizendo: \'Senhor, tua mina rendeu mais dez minas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Respondeu-lhe: \'Muito bem, servo bom. Porque fostes fiel no pouco, tu terás autoridade sobre dez cidades\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'O segundo veio dizendo: \'Senhor, tua mina rendeu cinco minas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'E o nobre lhe disse: \'Tu terás autoridade sobre cinco cidades\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'E veio outro dizendo: \'Senhor, eis aqui tua mina que mantive em segurança embrulhada num lenço,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'pois eu estava com medo de ti porque és um homem severo. Tu tiras o que não depositaste, colhes o que não semeaste\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'O nobre lhe disse: \'Por tuas próprias palavras te julgarei, servo mau. Sabias que sou um homem severo, que tiro o que não depositei e colho o que não semeei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Por que não colocaste o meu dinheiro no banco? Assim, no meu retorno, o receberia com juros.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'E disse aos que estavam ali: \'Tirai dele a mina e dai-a ao que tem dez minas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'Eles lhe disseram: \'Senhor, ele já tem dez minas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Eu vos digo: \'Ao que tem, mais lhe será dado, mas ao que não tem, até o que tem lhe será tirado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Quanto a esses inimigos meus, que não queriam que eu reinasse sobre eles, trazei-os aqui e degolai-os diante de mim\'”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'E tendo dito essas coisas, seguiu viagem adiante deles, subindo a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Aconteceu que, quando Ele chegou perto de Betfagé e de Betânia, junto ao monte que é chamado das Oliveiras, enviou dois dos discípulos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'dizendo: “Ide ao próximo povoado. Assim que entrardes, encontrareis um jumentinho amarrado sobre o qual ninguém jamais montou. Desatai-o e trazei-o a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Se alguém perguntar: \'Por que o desatais?\' Dizei: \'O Senhor necessita dele\'”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Os que foram enviados encontraram o jumentinho assim como Jesus lhes havia dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Enquanto o desatavam, o dono lhes disse: “Por que estais desatando o jumentinho?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Eles responderam: “O Senhor necessita dele.”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Eles o trouxeram a Jesus, colocaram seus mantos sobre o jumento e puseram Jesus sobre ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'À medida em que avançava, as pessoas estendiam seus mantos pelo caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'E quando se aproximavam da descida do Monte das Oliveiras, toda a multidão de discípulos começou a se alegrar e a louvar a Deus em alta voz pelos atos poderosos que tinha visto,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'dizendo: “Bendito é o Rei que vem em nome do Senhor. Paz no céu e glória nas alturas!”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Alguns dos fariseus em meio à multidão disseram-lhe: “Mestre, repreende os teus discípulos”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Jesus respondeu, dizendo: “Digo-vos, se estes se calarem, as pedras clamarão!”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Quando Jesus se aproximou da cidade, vendo-a, chorou por ela, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, '“Se hoje conhecesses aquilo que te traz a paz! Mas agora estas coisas estão ocultas aos teus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Porque sobre ti virão dias em que teus inimigos construirão trincheiras em teus arredores, te cercarão, te pressionarão por todos os lados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'E arrasarão a ti, aos teus filhos dentro de ti. Não deixarão pedra sobre pedra porque não reconheceste o tempo em que foste visitada”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'E entrando Jesus no templo, começou a expulsar os que vendiam,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'dizendo-lhes: “Está escrito: \'A minha casa será casa de oração\', mas fizestes dela um covil de ladrões”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Jesus ensinava diariamente no templo. Mas os chefes dos sacerdotes, os escribas e os líderes do povo procuravam matá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'Não encontravam, porém, uma maneira de fazê-lo, porque todo o povo O ouvia fascinado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Aconteceu que, certo dia, Jesus ensinava o povo no templo e pregava o evangelho; chegaram os chefes dos sacerdotes e os escribas, juntamente com os anciãos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'e Lhe perguntaram: “Dize-nos, com que autoridade Tu fazes estas coisas? E quem Te deu esta autoridade?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Ele lhes respondeu: \"Eu também vos farei uma pergunta: Dizei-Me');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'o batismo de João era do céu ou dos homens?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Eles discutiam entre si, dizendo: \"Se respondermos: \'do céu,\' Ele dirá: \'por que vós não crestes nele?\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Mas se dissermos: \'dos homens,\' todo o povo nos apedrejará, pois está convencido de que João Batista era profeta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Então eles responderam que não sabiam de onde era.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'E Jesus lhes disse: \"Nem eu vos direi com que autoridade faço estas coisas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Jesus começou a contar ao povo esta parábola: “certo homem plantou uma vinha, arrendou-a a uns vinicultores e ausentou-se do país por muito tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'No devido tempo, ele enviou um servo aos vinicultores, para que lhe dessem do fruto da vinha. Mas eles o espancaram e o mandaram de volta de mãos vazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Então enviou outro servo e a esse também espancaram, humilharam e o mandaram de volta de mãos vazias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Ele ainda enviou um terceiro, mas eles também o machucaram e o expulsaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Então o dono da vinha disse: \'Que farei? Enviarei meu filho amado. Talvez a ele respeitarão\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Mas quando os vinicultores o viram, discutiram entre si, dizendo: \'Este é o herdeiro. Vamos matá-lo, para que a herança seja nossa\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Eles o expulsaram da vinha e o mataram. Que lhes fará, então, o dono da vinha?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Ele virá e destruirá esses vinicultores e dará a vinha a outros”. Quando ouviram isso, disseram: \"Que isso não aconteça!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Mas Jesus fitando-os, disse: “O que quer dizer isto que está escrito: \'A pedra que os construtores rejeitaram tornou-se a pedra angular\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Todo aquele que cair sobre esta pedra ficará em pedaços; aquele sobre quem ela cair será reduzido a pó”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Naquela mesma hora, os escribas e os principais sacerdotes procuravam uma maneira de prendê-Lo, pois perceberam que a parábola que Ele havia contado era contra eles. Mas temiam o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'E observando-O cuidadosamente, enviaram espiões, que se fingiam de justos, para ver se o apanhavam em alguma de Suas palavras, e assim entregá-Lo à jurisdição e à autoridade do governador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Então eles O interrogaram, dizendo: “Mestre, sabemos que falas e ensinas corretamente, e não És influenciado pela aparência da pessoa, mas ensinas o caminho de Deus segundo a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Nos é lícito pagar impostos a César ou não?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Mas Jesus compreendeu a astúcia deles e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, '\"Mostrai-me um denário. De quem é esta imagem e inscrição nele?” E eles responderam: \"De César\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Disse-lhes Jesus: “Então dai a César o que é de César e a Deus o que é de Deus”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'E não puderam apanhá-Lo em palavra alguma diante do povo, mas admirados com Sua resposta, calaram-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Aproximando-se alguns dos saduceus, que dizem que não há ressurreição,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'perguntaram-Lhe dizendo: “Mestre, Moisés nos deixou escrito que, se o irmão de alguém morrer, sendo casado e não tendo filhos, ele deve tomar por esposa a viúva e suscitar descendência ao seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Havia sete irmãos. O primeiro casou-se e morreu sem filhos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'o segundo também');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'e depois o terceiro se casou com a viúva, e todos os sete, e também não deixaram filhos, e morreram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Por fim, a mulher também morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Então, na ressurreição, de qual deles ela será esposa? Pois todos os sete a tiveram por esposa”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'E disse-lhes Jesus: “Os filhos deste mundo se casam e se dão em casamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Mas os que são julgados dignos de alcançar aquela era e obter a ressurreição dentre os mortos não se casarão e nem se darão em casamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Eles nem podem morrer mais, pois são iguais aos anjos e são filhos de Deus, sendo filhos da ressurreição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Pois os mortos ressuscitarão, como também Moisés revelou no local da sarça ardente, onde ele chama o Senhor Deus de Abraão, o Deus de Isaque e o Deus de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Deus não é Deus de mortos, mas de vivos, pois para Ele todos vivem”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Alguns dos escribas disseram: “Mestre, respondeste bem”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Já não ousavam fazer-Lhe mais perguntas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Mas perguntou-lhes Jesus: “Como podem dizer que o Cristo é filho de Davi?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Pois o próprio Davi diz no livro de Salmos: \'O Senhor disse ao meu Senhor: Assenta-te à minha direita,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'até que eu ponha teus inimigos por estrado dos teus pés\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Se Davi chama Cristo de \'Senhor\', como é que Ele pode ser seu filho?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'E como todo o povo o ouvia, Ele disse aos Seus discípulos:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '“Cuidado com os escribas, que gostam de andar com túnicas, amam as saudações nas praças, os principais assentos nas sinagogas e os primeiros lugares nos banquetes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'que devoram as casas das viúvas, com pretexto de longas orações. Esses receberão uma condenação mais severa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Jesus levantou os olhos e viu os ricos que lançavam suas ofertas no gazofilácio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'E viu certa viúva pobre lançando ali duas pequenas moedas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Então, disse: “Em verdade vos digo que esta viúva pobre deu mais do que todos eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Pois todos eles deram ofertas do que lhes sobrava. Mas esta viúva, da sua pobreza, deu tudo o que tinha para viver”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'E alguns falavam acerca do templo, como ele era adornado com lindas pedras e de ofertas provenientes de votos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Então Jesus disse: “Quanto a estas coisas que vedes, dias virão em que não ficará pedra sobre pedra que não seja derrubada”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Eles então Lhe perguntaram: \"Mestre, quando acontecerão essas coisas? E qual será o sinal quando essas coisas estiverem para acontecer?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Jesus respondeu: \"Tende cuidado para não serdes enganados, pois muitos virão em Meu nome, dizendo: \'Eu sou ele\' e \'O tempo está próximo\'. Não os sigais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Quando ouvirdes de guerras e revoluções, não vos assusteis, pois é necessário que primeiro aconteçam essas coisas, mas o fim não virá imediatamente”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Então Ele disse: \"Nação se levantará contra nação, reino contra reino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'Ocorrerão grandes terremotos e, em vários lugares, fomes e pestes. Ocorrerão eventos terríveis e grandes sinais vindos do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Mas, antes de tudo isso, lançarão as mãos sobre vós e vos perseguirão, e sereis entregues às sinagogas e prisões e também sereis conduzidos à presença de reis e governadores por causa do Meu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Isso resultará em oportunidades para vosso testemunho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Portanto resolvei em vossos corações de não preparardes antecipadamente vossa defesa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'pois Eu vos darei as palavras e a sabedoria, às quais nenhum dos vossos adversários poderá resistir ou contradizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'E sereis entregues também por pais, irmãos, parentes e amigos, e eles matarão alguns de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'E sereis odiados por todos por causa de Meu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Mas nem um só fio de cabelo da vossa cabeça perecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Na vossa perseverança, ganhareis as vossas almas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Quando virdes os exércitos cercarem Jerusalém, então sabei que sua desolação se aproxima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Então os que estiverem na Judéia fujam para os montes, e os que estiverem no meio da cidade saiam, e os que estiverem nos campos não entrem nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Porque estes são dias de vingança, em cumprimento de tudo que foi escrito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Ai daquelas que estiverem grávidas e das que estiverem amamentando naqueles dias! Pois haverá grande aflição sobre a terra e ira contra este povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'E morrerão a fio de espada e serão levados cativos para todas as nações, e Jerusalém será pisada pelos gentios, até que os tempos deles sejam cumpridos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'E haverá sinais no sol, na lua e nas estrelas. Sobre a terra, haverá angústia entre as nações, desesperadas pelo bramido e a agitação do mar e das ondas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Haverá homens desmaiando de medo, na expectativa das coisas que sobrevirão ao mundo. Pois os poderes dos céus serão abalados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Então eles verão o Filho do Homem vir numa nuvem, com poder e grande glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Mas, quando essas coisas começarem a acontecer, levantai e erguei as vossas cabeças, porque vossa redenção se aproxima”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'E Jesus contou-lhes uma parábola: “Vede a figueira e as demais árvores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Quando elas dão brotos, por vós mesmos, sabeis que o verão já se aproxima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Assim também vós, quando virdes essas coisas acontecendo, sabei que o reino de Deus está próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Verdadeiramente eu vos digo, não passará esta geração até que todas essas coisas aconteçam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'O céu e a terra passarão, mas as Minhas palavras jamais passarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'E tende cuidado de vós mesmos, para que vossos corações não estejam sobrecarregados com as consequências das orgias, da embriaguez e das preocupações da vida. Para que aquele dia não venha sobre vós repentinamente, como armadilha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Pois ele virá sobre todo ser vivente sobre a face da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Mas estai em alerta por todo o tempo, orando para terdes a força suficiente para escapar de todas essas coisas que acontecerão, e permanecerdes na presença do Filho do Homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'E, durante os dias, Ele estava ensinando no templo e à noite saía e pernoitava no monte que é chamado \'das Oliveiras\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Todas as pessoas vinham de manhã cedo ao templo para ouvi-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Aconteceu que a festa dos Pães Sem Fermento, que se chamava Páscoa, aproximava-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Os principais sacerdotes e os escribas discutiam como eles poderiam levar Jesus à morte, pois eles temiam o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Satanás entrou em Judas Iscariotes, um dos doze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'E Judas foi discutir com os principais sacerdotes e os oficiais do templo sobre como ele poderia lhes entregar Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Eles se alegraram e combinaram em lhe dar dinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Ele consentiu e buscava uma oportunidade para entregá-Lo, longe da multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Chegado o dia da festa dos Pães Sem Fermento, em que o cordeiro pascal deveria ser sacrificado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Jesus enviou Pedro e João, dizendo: \"Ide e preparai para nós a ceia da Páscoa, para que possamos comê-la\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Eles Lhe perguntaram: \"Onde Tu queres que preparemos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Ele lhes respondeu: \"Eis que, quando entrardes na cidade, um homem carregando um cântaro de água se encontrará convosco. Segui-o até a casa em que ele entrar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'E dizei ao dono da casa: \'O Mestre te diz: Onde está a sala em que Eu irei comer a Páscoa com Meus discípulos?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Ele lhes mostrará uma grande sala mobiliada no andar de cima. Fazei os preparativos lá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Então eles foram e encontraram tudo como Ele lhes dissera. E prepararam a ceia pascal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Quando a hora veio, Ele sentou-se com os apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Então lhes disse: \"Eu desejei grandemente comer convosco esta Páscoa antes que Eu sofra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Pois Eu lhes digo: \'Eu não a comerei de novo, até que ela se cumpra no Reino de Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Então, Jesus tomou um cálice e, tendo dado graças, disse: \"Tomai-o e compartilhai-o entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Pois Eu vos digo que não beberei do fruto da videira de novo, até que o Reino de Deus venha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Então Ele tomou o pão e, havendo dado graças, o partiu e lhes entregou, dizendo: \"Este é o Meu corpo, que é entregue por vós. Fazei isto em memória de Mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Da mesma forma, após cear, Ele tomou o cálice, dizendo: \"Este cálice é a nova aliança no Meu sangue, que é derramado por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Mas eis que a mão daquele que está Me traindo está comigo à mesa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Pois o Filho do Homem, de fato, faz como tem sido determinado. Mas ai do homem por quem Ele é traído!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'E eles começaram a perguntar entre si qual deles seria que faria isto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Então levantou-se também uma contenda entre eles sobre quem seria considerado o maior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Ele lhes disse: \"Os reis dos gentios têm domínio sobre eles, e aqueles que têm autoridade sobre eles são chamados benfeitores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Mas isso não deve ser assim entre vós. Ao invés disso, aquele que é maior entre vós seja como o mais jovem. E aquele que é o mais importante seja como o que serve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Pois qual é o maior, aquele que está sentado à mesa, ou aquele que serve? Não é aquele que está sentado à mesa? Porém, Eu estou no meio de vós como o que serve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Mas vós sois aqueles que têm permanecido comigo em Minhas provações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'Eu lhes confiei um Reino, assim como Meu Pai o confiou a Mim,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'para que possais comer e beber à Minha mesa, no Meu Reino. E vos senteis sobre tronos julgando as doze tribos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Simão, Simão, fica atento, Satanás pediu para tê-los, para peneirá-los como trigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Mas Eu roguei por ti, para que tua fé não falhe. E quando te converteres, fortalece teus irmãos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Pedro Lhe disse: \"Senhor, eu estou pronto para ir contigo tanto para a prisão quanto para a morte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Jesus respondeu: \"Eu te digo, Pedro, o galo não cantará neste dia, antes que, por três vezes, tenhas negado que me conheces\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Então Jesus lhes disse: \"Quando Eu vos enviei sem sacola, bolsa de provisões ou calçados, sentistes falta de algo?\" E eles responderam: \"Nada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Então Ele lhes disse: \"Porém agora aquele que tiver uma sacola leve-a e também uma bolsa de provisões. Aquele que não tiver espada venda sua capa e compre uma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Pois Eu lhes digo que tudo que está escrito sobre Mim deve se cumprir: \'E ele foi considerado como um malfeitor\'. Pois, tudo o que foi predito sobre Mim está se cumprindo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Então, eles disseram: \"Senhor, eis aqui duas espadas\". E Ele lhes disse: \"É o suficiente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Após a ceia, Jesus saiu para o Monte das Oliveiras, como Ele costumava fazer, e Seus discípulos O seguiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Quando eles chegaram, Ele lhes disse: \"Orai para que não entreis em tentação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Ele se afastou deles cerca de um arremesso de pedra e, ajoelhando-se, orou');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'dizendo: \"Pai, se Tu queres, afasta de Mim este cálice. Entretanto não seja feita a Minha vontade, mas a Tua\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Então, apareceu-Lhe um anjo do céu, fortalecendo-O.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Estando em agonia, Ele orava ainda mais intensamente, e Seu suor tornou-se em grandes gotas como que de sangue caindo sobre o chão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Então, levantando-Se de Sua oração, Ele veio até os discípulos e os encontrou dormindo, por causa da tristeza deles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'e perguntou-lhes: \"Por que estais dormindo? Levantai e orai, para que não entreis em tentação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Enquanto Ele ainda falava, eis que uma multidão chegava com Judas, um dos doze, que vinha à frente e se aproximou de Jesus para beijá-Lo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'mas Jesus lhe disse: \"Judas, tu estás traindo o Filho do Homem com um beijo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Quando aqueles que estavam ao redor de Jesus viram o que estava acontecendo, disseram: \"Senhor, devemos feri-los a espada?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Então um deles feriu o servo do sumo sacerdote e cortou fora sua orelha direita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'E Jesus disse: \"Basta, deixai-os\". E Ele tocou-lhe a orelha e o curou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Jesus disse aos principais sacerdotes, oficiais do templo e anciãos que vieram contra Ele: \"Viestes como contra um ladrão, com espadas e pedaços de pau?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Enquanto Eu estive diariamente convosco no templo, não pusestes as vossas mãos sobre Mim. Mas esta é a vossa hora e do domínio das trevas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Prendendo-O, levaram-No e trouxeram-No à casa do sumo sacerdote. Mas Pedro, a distância, seguiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Mais tarde, eles acenderam um fogo no meio do pátio e sentaram juntos. Pedro sentou-se no meio deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Certa criada o viu quando ele se sentava próximo à luz do fogo, olhou diretamente para ele e disse: \"Este homem também estava com Ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Mas Pedro negou, dizendo: \"Mulher, eu não O conheço\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Após um tempo, outra pessoa o viu e disse: \"Tu também és um deles\". Mas Pedro lhe disse: \"Homem, eu não sou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Após cerca de uma hora, insistiu outro dizendo: \"Verdadeiramente este homem também estava com Ele, pois Ele é galileu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Mas Pedro disse: \"Homem, eu não sei do que estás falando\". E imediatamente, enquanto ele falava, o galo cantou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'O Senhor se voltou e olhou para Pedro. E Pedro lembrou-se da palavra do Senhor, quando lhe disse: \"Hoje, antes que o galo cante, tu me negarás três vezes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Saindo, Pedro chorou amargamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Então os homens que detinham Jesus zombavam Dele e batiam Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'Após vendarem Seus olhos, perguntavam, dizendo: \"Profetiza! Quem foi o que te bateu?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Eles blasfemavam falando muitas outras coisas contra Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Tão logo o dia amanheceu, os anciãos do povo reuniram-se, ambos os principais sacerdotes e os escribas. Eles O levaram ao Conselho dos judeus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'dizendo: \"Se Tu és o Cristo, diga-nos\". Porém Ele respondeu: \"Se Eu vos disser, não acreditareis;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'se Eu vos perguntar, não respondereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Mas, de agora em diante, o Filho do Homem estará assentado à direita do poder de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Todos eles disseram: \"Então, Tu és o Filho de Deus?\". E Jesus lhes respondeu: \"Vós dizeis que Eu Sou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Eles disseram: \"Por que nós ainda precisamos de testemunhas? Pois nós mesmos ouvimos de Sua própria boca\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Então, todos os líderes dos judeus se levantaram contra Ele e O trouxeram a Pilatos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'E começaram a acusar-Lo dizendo: “Encontramos este homem pervertendo a nossa nação, proibindo pagar os impostos a César, declarando que Ele mesmo é o Cristo, um rei”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Pilatos perguntou-Lhe: “Tu és o Rei dos Judeus?”. E Jesus lhe respondeu: “Tu o dizes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'E disse Pilatos aos chefes dos sacerdotes e às multidões: “Não encontro nenhum crime neste homem”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Mas eles insistiam, dizendo: “Ele agita o povo, ensinando por toda Judeia, começando desde a Galileia até aqui”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Então Pilatos ouviu isso e perguntou se aquele homem era galileu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Quando descobriu que Ele estava sob a autoridade de Herodes, enviou-O a este, que também estava em Jerusalém naqueles dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Quando Herodes viu Jesus, alegrou-se muito, porque, havia muito tempo, desejava vê-Lo. Ele ouvira falar sobre Jesus e desejava ver algum milagre realizado por Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Herodes interrogava Jesus com muitas palavras, porém Este não lhe respondia nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Os chefes dos sacerdotes e os escribas se levantaram, acusando-O severamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Herodes, com os seus soldados trataram-No com despreso e zombaram Dele, vestindo-O com uma túnica elegante e, em seguida, enviaram Jesus de volta a Pilatos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Pilatos e Herodes tornaram-se amigos um do outro naquele mesmo dia. Antes disso eram inimigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Pilatos, então, convocou os chefes dos sacerdotes, as autoridades do povo e a multidão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'e disse-lhes: “Vós me trouxestes este homem como alguém que está levando o povo a se rebelar, mas vejam: eu, tendo-O interrogado diante de vós, não encontrei culpa alguma neste homem a respeito das coisas sobre as quais vós O acusastes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Nem mesmo Herodes, porque O enviou de volta. Vejam que Ele nada tem feito digno de morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Eu, portanto, irei castigá-Lo e soltá-Lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, '.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Mas eles gritaram todos juntos, dizendo: “Fora daqui com este homem e solta-nos Barrabás!”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Barrabás era um homem que estava preso por causa de uma rebelião na cidade e também por assassinato.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Outra vez falou Pilatos, desejando soltar a Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Mas eles gritaram, dizendo: “Crucifica-O, crucifica-O”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'E disse-lhes pela terceira vez: “Por quê? Que mal fez este homem? Eu não encontrei nada Nele que mereça a pena de morte. Logo, após castigá-Lo, eu vou liberá-Lo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Mas eles gritaram insistentemente, pedindo que Ele fosse crucificado. E o clamor da multidão convenceu Pilatos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Então, Pilatos decidiu conceder a exigência deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Ele soltou aquele que pediram, o qual havia sido colocado na prisão por motim e assassinato. Porém, entregou Jesus à vontade deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Enquanto O levavam dali, pegaram um tal de Simão, da cidade de Cirene, que vinha do campo, e puseram a cruz sobre ele para carregá-la, seguindo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Uma grande multidão do povo e de mulheres que lamentavam e pranteavam por Ele O seguia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Mas voltando-se para elas, Jesus disse: “Filhas de Jerusalém, não choreis por Mim; chorai antes por vós mesmas e por vossos filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Eis que virão os dias em que dirão: \'Bem-aventuradas as estéreis e os ventres que não geraram, e os seios que não amamentaram\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Então, começarão a dizer aos montes: \'Caí sobre nós\', e às colinas: \'Cobri-nos\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Porque, se eles fazem isso quando a árvore ainda está verde, o que acontecerá quando ela estiver seca?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Outros homens, dois criminosos, foram levados com Jesus para serem mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Quando chegaram ao lugar chamado \"Caveira\", ali O crucificaram, bem como aos criminosos, um à Sua direita e outro à Sua esquerda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Jesus disse: “Pai, perdoa-lhes, eles não sabem o que fazem\". E lançaram sortes, dividindo as Suas vestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'O povo ficou observando enquanto as autoridades também O ridicularizavam, dizendo: \"Ele salvou outros, deixe que salve a Si mesmo, se Ele é o Cristo, O escolhido de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Os soldados também zombavam Dele, oferecendo-Lhe vinagre,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'dizendo: “Se Tu és o Rei dos judeus, salva-Te\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Havia também uma inscrição sobre Ele: “ESTE É O REI DOS JUDEUS\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Um dos criminosos que foi crucificado, insultou-O dizendo: “Não és Tu o Cristo? Salva-Te a Ti mesmo e a nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Mas o outro lhe respondeu e, repreendendo-o, disse: “Não temes a Deus, tu que estás sob a mesma condenação?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Nós, de fato, estamos aqui justamente, pois estamos recebendo o que merecemos por nossos atos. Mas este homem não cometeu mal algum\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'E acrescentou: “Jesus, lembra-Te de mim, quando entrares no Teu reino”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Disse-lhe Jesus: “Em verdade te digo, ainda hoje tu estarás comigo no paraíso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Já era mais ou menos a hora sexta, e houve trevas sobre toda a terra até à hora nona,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'pois o sol deixou de brilhar e a cortina do templo foi rasgada ao meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'E, clamando em alta voz, Jesus disse: “Pai, em Tuas mãos entrego o Meu espírito”. Dito isso, Ele morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Quando o centurião viu o que acontecera, deu glória a Deus, dizendo: “Certamente este homem era justo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Quando todas as multidões vieram para ver o acontecimento, após o que viram, voltaram batendo no peito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Mas todos os conhecidos de Jesus, e as mulheres que O haviam seguido desde a Galileia permaneceram de longe, observando essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Eis que havia um membro do Conselho dos judeus chamado José, homem bom e justo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'de Arimatéia, uma cidade judia. Ele esperava pelo Reino de Deus (ele não havia concordado com a decisão e a ação do Conselho).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Esse homem, indo até Pilatos, pediu-lhe o corpo de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Ele O desceu, envolveu-O em um lençol de linho fino e O colocou em um túmulo escavado na pedra, onde ninguém havia sido colocado antes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Era o Dia da Preparação, e o Sábado estava para começar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'As mulheres que andavam com Ele desde a Galileia viram o túmulo e como Seu corpo fora colocado ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Elas voltaram e prepararam essências e perfumes. Então, no sábado repousaram conforme o mandamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Mas, no primeiro dia da semana, alta madrugada, elas foram ao túmulo, levando as especiarias que haviam preparado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Elas encontraram a pedra do sepulcro removida;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'mas, ao entrarem, não encontraram o corpo do Senhor Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'E sucedeu que elas estavam perplexas sobre o ocorrido. Então, dois homens apareceram junto a elas com vestes resplandescentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'As mulheres ficaram cheias de medo e, voltando o rosto para o chão, eles disseram para as mulheres: “Por que buscais entre os mortos Aquele que vive?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Ele não está aqui, ressuscitou! Lembrai-vos de como Ele falou a vós, quando ainda estava na Galileia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'dizendo que o Filho do Homem devia ser entregue nas mãos de homens pecadores e crucificado e, ao terceiro dia, ressuscitar”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'As mulheres se lembraram das palavras Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'E, voltando do túmulo, contaram todas essas coisas aos onze e a todos os demais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Maria Madalena, Joana e Maria, mãe de Tiago, e as outras que estavam com elas relataram essas coisas aos apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Mas os apóstolos não acreditaram nas mulheres, essas palavras lhes pareciam como um delírio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Pedro, contudo, se levantou e correu para o túmulo. Curvando-se e olhando para dentro, viu apenas os lençóis de linho. Voltou para casa maravilhado com o que havia acontecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Naquele mesmo dia, dois deles estavam indo para uma aldeia chamada Emaús, a sessenta estádios de distância de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'E iam conversando sobre todas as coisas que haviam ocorrido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Aconteceu que, enquanto eles discutiam e conversavam, o próprio Jesus se aproximou e começou a caminhar com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Mas seus olhos estavam impedidos de reconhecê-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Perguntou-lhes Jesus: \"Sobre o que conversais pelo caminho?\". E pararam entristecidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Um deles, chamado Cléopas respondeu: \"És tu o único peregrino que não sabes as coisas que aconteceram em Jerusalém nesses dias?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Ele lhes disse: “Quais coisas?”. Eles responderam: “As que dizem respeito a Jesus de Nazaré, O qual foi um profeta poderoso em obras e palavras, diante de Deus e de todo o povo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'e de como os chefes dos sacerdotes e as nossas autoridades O entregaram para ser condenado à morte e O crucificaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Nós esperávamos que fosse Ele quem libertaria Israel. No entanto, apesar disso, hoje é o terceiro dia desde que essas coisas aconteceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'É verdade que algumas mulheres do nosso meio nos surpreenderam, tendo ido de madrugada ao sepulcro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'E não encontrando o corpo de Jesus, voltaram dizendo que tiveram uma visão de anjos, os quais disseram que Ele vive.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Alguns dos que estavam conosco foram ao túmulo e confirmaram o que as mulheres haviam dito; mas não O viram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Jesus, então, lhes disse: “Ó homens insensatos e tardios de coração para crer em tudo o que os profetas disseram!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Não era necessário que o Cristo sofresse essas coisas e entrasse em Sua glória?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Então, começando por Moisés e percorrendo todos os profetas, interpretou-lhes, em todas as Escrituras, o que dizia a respeito de Si próprio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Quando se aproximaram da aldeia, para onde se dirigiam, Jesus fez como quem seguiria adiante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Mas eles insistiram com Ele, dizendo: “Fica conosco, porque já é tarde e o dia está quase terminando\". E entrou para ficar com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'E, uma vez à mesa com eles, tomou o pão, abençoou-o, partiu-o e deu-o a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Então, seus olhos foram abertos, eles O reconheceram, e Ele desapareceu da vista deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Eles disseram uns aos outros: “Não estava queimando o nosso coração, enquanto Ele nos falava durante o caminho e nos explicava as Escrituras?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Naquela mesma hora, levantaram-se e voltaram para Jerusalém. Eles encontraram os onze reunidos e os que estavam com eles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'que disseram: “Verdadeiramente o Senhor ressuscitou e apareceu a Simão”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Então, contaram as coisas que aconteceram no caminho e como Jesus foi reconhecido por eles no partir do pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Enquanto ainda falavam essas coisas, Jesus apareceu no meio deles e lhes disse: “A paz esteja convosco!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'E ficaram assustados e com medo, pensando estar vendo um espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Mas Jesus disse: “Por que estais perturbados? Por que surgem dúvidas em vossos corações?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Vede Minhas mãos e Meus pés, sou Eu mesmo! Tocai-Me e vede. Um espírito não tem carne nem ossos como vós vedes que Eu tenho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Tendo dito isso, mostrou-lhes as mãos e os pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'E, como eles ainda não podiam acreditar, por causa da alegria e estando maravilhados, Jesus disse-lhes: “Vós tendes alguma coisa para comer?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Deram-Lhe um pedaço de peixe assado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Jesus tomou-o e comeu-o diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Ele lhes disse: “Quando ainda estava convosco, vos dizia: era necessário que se cumprisse tudo o que estava escrito acerca de Mim na Lei de Moisés, nos Profetas e nos Salmos”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Então, lhes abriu o entendimento para que pudessem compreender as Escrituras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'E lhes disse: “Assim está escrito que o Cristo haveria de sofrer e ressuscitar dentre os mortos ao terceiro dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'E que, em Seu Nome, fossem pregados o arrependimento e o perdão dos pecados a todas as nações, começando por Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Vós sois testemunhas dessas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Eis que Eu envio a promessa de Meu Pai sobre vós; mas esperai na cidade até que sejais revestidos do poder do alto”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Então, Jesus os conduziu para fora até perto de Betânia. E, erguendo Suas mãos, os abençoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Aconteceu que, enquanto Ele os abençoava, afastou-se e foi elevado ao céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Então, eles O adoraram e voltaram para Jerusalém com grande alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'Eles estavam continuamente no templo, bendizendo a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'No princípio Aquele que é a Palavra já existia; e a Palavra estava com Deus; e a Palavra era Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Ele estava desde o princípio com Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Todas as coisas foram feitas por intermédio Dele, e sem Ele nada do que foi feito se fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'Nele estava a vida, e a vida era a luz dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'A luz brilha nas trevas, e as trevas não prevaleceram contra ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Houve um homem enviado por Deus cujo nome era João.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Ele veio como testemunha para testificar a respeito da Luz, para que todos cressem por meio dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Ele não era a Luz, mas veio a fim de testificar da Luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Era a verdadeira Luz, que ilumina todo homem, que estava chegando ao mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Ele estava no mundo, e o mundo foi feito por Ele, mas o mundo não O conheceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Veio para o que era Seu, e os Seus não O receberam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Mas a todos que O receberam, os quais creram no Seu nome, deu-lhes o poder de se tornarem filhos de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'os quais não nasceram do sangue, nem da vontade da carne, nem da vontade de homem, mas de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'E a Palavra tornou-Se carne e habitou entre nós, e vimos a Sua glória, como a glória do Unigênito do Pai, cheio de graça e de verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'João testifica Dele e clama, dizendo: \"Este é Aquele de quem eu disse: \'O que vem depois de mim é superior a mim, pois era antes de mim’”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Porque da Sua plenitude todos recebemos graça sobre graça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Pois a Lei foi dada por meio de Moisés, mas a graça e a verdade vieram por meio de Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Ninguém jamais viu a Deus. O único que, sendo Deus, estava junto ao seio do Pai, foi quem O revelou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'E este é o testemunho de João, quando os judeus lhe enviaram de Jerusalém sacerdotes e levitas a fim de interrogá-lo: \"Quem és tu?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Ele afirmou claramente e não negou, mas confessou: \"Eu não sou o Cristo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Então lhe perguntaram: \"Quem és tu, então? Tu és Elias?\". Ele respondeu: \"Não sou\". Eles disseram: \"Tu és o profeta?\". Ele respondeu: \"Não\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Então lhe disseram: \"Diga-nos quem és, para que demos resposta àqueles que nos enviaram. O que dizes de ti mesmo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Ele disse: \"Eu sou a voz daquele que clama no deserto: \'Endireitai o caminho do Senhor\', como o profeta Isaías disse\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'E aqueles que foram enviados eram dos fariseus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'E lhe perguntaram: \"Então, por que batizas, se não és o Cristo, nem Elias e nem o profeta?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'João lhes respondeu: \"Eu batizo com água; porém, no meio de vós, está Alguém que não conheceis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Esse é o que vem depois de mim, de Quem eu não sou digno de desatar as correias de Suas sandálias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Essas coisas aconteceram em Betânia, no outro lado do Jordão, onde João estava batizando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'No dia seguinte, João viu Jesus aproximando-Se dele, e disse: \"Eis o Cordeiro de Deus que tira o pecado do mundo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Foi a respeito Dele que eu disse: \'Aquele que vem depois de mim é superior a mim, pois existia antes de mim\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Eu não O conhecia, mas, para que Ele fosse revelado a Israel, eu vinha batizando com água\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'João testemunhou: \"Eu vi o Espírito descendo do céu como pomba, e permaneceu sobre Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Eu não O conhecia; porém, Aquele que me enviou a batizar com água, disse-me: \'Aquele sobre Quem vires o Espírito descer e permanecer sobre Ele, Este é o que batiza com o Espírito Santo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Eu vi e testemunhei que Esse é o Filho de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'No dia seguinte, João estava lá novamente com dois de seus discípulos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'e, ao ver Jesus passando, disse: \"Eis o Cordeiro de Deus!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Os dois discípulos ouviram o que João disse, e passaram a seguir Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Jesus voltou-Se, viu que eles O seguiam, e disse-lhes: \"O que quereis?\". Eles responderam: \"Rabi (que quer dizer \'mestre\'), onde moras?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Ele diz-lhes: \"Vinde e vereis\". Foram, pois, e viram onde Jesus morava; e permaneceram com Ele naquele dia, pois já se aproximava da hora décima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'André, irmão de Simão Pedro, era um dos que ouviram João falar e seguiram a Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Ele encontrou primeiro seu próprio irmão, Simão, e lhe disse: \"Encontramos o Messias\" (que traduzido significa \'Cristo\').');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Ele o levou a Jesus. Olhando para ele, Jesus lhe disse: \"Tu és Simão, filho de João. Serás chamado Cefas (que quer dizer \'Pedro\')\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'No dia seguinte, quando Jesus foi para a Galileia, encontrou Filipe e lhe disse: \"Segue-Me\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Filipe era de Betsaida, a cidade de André e Pedro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Filipe encontrou Natanael e disse-lhe: \"Aquele sobre O qual a Lei de Moisés e os profetas escreveram, nós O encontramos: Jesus, Filho de José, de Nazaré\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Natanael perguntou: \"Pode vir alguma coisa boa de Nazaré?\". Filipe respondeu: \"Vem e vê\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jesus viu Natanael se aproximando, e disse a seu respeito: \"Eis aí um israelita em quem não há desonestidade!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Natanael Lhe perguntou: \"De onde me conheces?\". Jesus respondeu: \"Antes que Filipe te chamasse, Eu te vi, quando estavas debaixo da figueira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Natanael respondeu: \"Rabi, Tu és o Filho de Deus! Tu és o Rei de Israel!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Então Jesus lhe disse: \"Porque te disse que havia te visto debaixo da figueira, crês? Tu verás coisas maiores do que essa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Em verdade, em verdade vos digo que vós vereis os céus abertos, e os anjos de Deus subindo e descendo sobre o Filho do Homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'No terceiro dia, houve um casamento em Caná da Galileia, e a mãe de Jesus estava presente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Jesus e Seus discípulos também foram convidados para o casamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'E, tendo acabado o vinho, a mãe de Jesus Lhe disse: \"Eles não têm vinho.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Jesus respondeu: \"Por que vens a Mim, mulher? O meu tempo ainda não chegou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Sua mãe disse aos servos: \"Fazei o que Ele vos disser\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Havia ali seis vasilhas de pedra usadas para a purificação dos judeus, cada uma armazenava entre oitenta e cento e vinte litros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jesus lhes diz: \"Enchei as vasilhas com água\". Eles as encheram até a borda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Então, Ele disse aos servos: \"Tirai um pouco e levai ao chefe de cerimônia\". Assim o fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Quando o chefe de cerimônia provou a água transformada em vinho, ele não sabia de onde vinha (mas os servos que haviam tirado a água sabiam). Ele chamou o noivo');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'e disse-lhe: \"Todos oferecem primeiro o vinho bom, e em seguida o vinho inferior, quando os convidados estiverem bêbados. Tu guardaste o vinho bom até agora\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Este primeiro sinal, Jesus fez em Caná da Galileia, manifestando Sua glória, e Seus discípulos creram Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Depois disso, Jesus, Sua mãe, Seus irmãos e Seus discípulos desceram para Cafarnaum e permaneceram por alguns dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'A Páscoa dos judeus estava próxima, então Jesus subiu a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Ele encontrou no templo aqueles que vendiam bois, ovelhas, pombas e os cambistas ali sentados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Jesus fez um chicote de cordas, e expulsou todos para fora do templo, incluindo as ovelhas, os bois; espalhou o dinheiro dos cambistas pelo chão, e virou as suas mesas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Ele disse aos que vendiam pombas: \"Tirai estas coisas daqui, e não façais da casa de Meu Pai um mercado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Seus discípulos lembraram o que está escrito: \"O zelo da Tua casa me consumirá”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Logo, as autoridades dos judeus Lhe responderam: \"Que sinal nos mostrarás visto que fazes estas coisas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jesus respondeu: \"Destruí este templo, e em três dias o reconstruirei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Disseram, então, os judeus: \"Este templo levou quarenta e seis anos para ser construído, e Tu irás levantá-lo em três dias?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Entretanto, Ele falava do templo do Seu corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Tempos depois, quando Ele ressuscitou dos mortos, Seus discípulos lembraram-se do que Ele havia dito, e acreditaram nas Escrituras e nas palavras ditas por Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Quando Ele estava em Jerusalém, durante a celebração da Páscoa, muitos acreditaram em Seu nome, pois viram os sinais miraculosos que Ele realizava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Entretanto, Jesus não confiava neles, pois conhecia a todos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'e não precisava de ninguém para testificar sobre o homem; pois Ele mesmo conhecia o que havia no homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Havia um fariseu cujo nome era Nicodemos, um líder dos judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Ele veio até Jesus durante a noite e disse-Lhe: \"Rabi, sabemos que és um mestre vindo de Deus, porque ninguém pode fazer estes sinais, a menos que Deus esteja com ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jesus respondeu: \"Em verdade, em verdade te digo: se um o homem não nascer de novo, ele não pode ver o reino de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nicodemos disse-Lhe: \"Como pode um homem nascer sendo já velho? Ele pode entrar uma segunda vez no ventre de sua mãe e nascer de novo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jesus respondeu: \"Em verdade, em verdade, te digo: quem não nascer da água e do Espírito não pode entrar no reino de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Aquele que é nascido da carne é carne, o que é nascido do Espírito é espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Não te admires de eu te dizer: ‘Necessário vos é nascer de novo’.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'O vento sopra onde quer, e ouves o seu som, mas não sabes de onde vem e nem para onde vai. Assim é todo aquele que é nascido do Espírito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nicodemos respondeu-Lhe dizendo: \"Como pode ser isso?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jesus lhe respondeu: \"Tu, que és mestre em Israel, não entendes estas coisas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Em verdade, em verdade, te digo: Nós falamos daquilo que sabemos, e testificamos do que temos visto; ainda assim vós não aceitais nosso testemunho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Se vos falei sobre coisas terrenas e não acreditastes, como acreditareis se vos contar sobre as coisas celestiais?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Ninguém jamais subiu ao céu, exceto Aquele que desceu do céu, o Filho do Homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Assim como Moisés levantou a serpente no deserto, o Filho do Homem deverá ser levantado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'para que todos que creiam Nele tenham vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Porque Deus amou o mundo de tal maneira que deu o Seu Filho Unigênito, para que todo aquele que Nele crê não pereça, mas tenha a vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Pois Deus não enviou o Seu filho ao mundo para condenar o mundo, mas para que o mundo fosse salvo por meio Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Aquele que Nele crê não será condenado. O que não crê já está condenado, porque não crê no Nome do Unigênito Filho de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Este é o julgamento: que a Luz veio ao mundo, e os homens amaram mais as trevas que a Luz, porque suas obras eram perversas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Pois todo aquele que pratica o mal odeia a luz, e não vem para a luz para que suas obras não sejam expostas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Entretanto, aquele que pratica a verdade vem para a luz, a fim de que se veja claramente que suas ações foram feitas em Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Depois disso, Jesus e Seus discípulos foram para a região da Judeia, onde passou algum tempo com eles, e ali batizava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'João também estava batizando em Enom, próximo a Salim, porque havia ali muita água, e as pessoas vinham até ele e eram batizadas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'pois João ainda não havia sido lançado na prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'E surgiu uma disputa entre alguns discípulos de João e um judeu sobre a cerimônia da purificação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Eles foram até João e disseram-lhe: \"Rabi, O que estava contigo do outro lado do Jordão, sobre Quem tu testemunhaste, eis que Ele está batizando, e todos estão indo até Ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'João respondeu: \"Ninguém pode receber nada, a não ser que lhe seja dado dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Vós mesmos sois testemunhas de que eu disse: \'Eu não sou o Cristo\', mas disse: \'Sou enviado adiante Dele\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'A noiva pertence ao noivo, mas o amigo do noivo, que está presente e o ouve, alegra-se muito por causa da voz do noivo. Assim, pois, minha alegria é completa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'É necessário que Ele cresça e eu diminua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Aquele que vem do alto está acima de todos; o que vem da terra é da terra, e fala de coisas terrenas. Aquele que vem dos céus está acima de todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Ele testifica daquilo que ouviu e viu, mas ninguém aceita o Seu testemunho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Aquele que aceita o Seu testemunho confirma que Deus é verdadeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Pois Aquele que é enviado de Deus fala as palavras de Deus. Pois Seu Espírito é dado sem medida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'O Pai ama o Filho e entregou todas as coisas na Sua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Aquele que crê no Filho tem a vida eterna, mas aquele que desobedece ao Filho não verá a vida, mas sobre ele permanece a ira de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'E quando Jesus soube que os fariseus tinham ouvido que Ele estava fazendo e batizando mais discípulos que João');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(embora Jesus mesmo não batizasse, mas os Seus discípulos),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'deixou a Judeia e retornou para a Galileia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Era necessário que Ele passasse por Samaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Então, veio a uma cidade de Samaria, chamada Sicar, perto das terras que Jacó havia dado a seu filho José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Havia ali o poço de Jacó. Jesus estava cansado da viagem, e sentou-Se próximo ao poço. Era por volta da hora sexta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Uma mulher samaritana veio tirar água, e Jesus lhe disse: \"Dá-Me de beber\";');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'pois Seus discípulos haviam ido à cidade comprar comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Então, a mulher samaritana disse-Lhe: \"Como Tu, sendo judeu, pedes a mim, que sou mulher samaritana, algo para beber?\"; pois os judeus e os samaritanos não se davam bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jesus respondeu: \"Se tu conhecesses o dom de Deus, e quem é O que te diz: \'Dá-me de beber\', tu é que Lhe pedirias, e Ele te daria a água viva\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'A mulher Lhe respondeu: \"Senhor, Tu não tens um balde, e o poço é bem fundo; de onde tirarias essa água viva?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Por acaso és Tu maior que o nosso pai Jacó, que nos deu o poço do qual ele mesmo bebeu com seus filhos e seu gado?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jesus respondeu: \"Qualquer que beber desta água terá sede novamente;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'mas qualquer que beber desta água que Eu lhe der, nunca mais terá sede. Pelo contrário, a água que Eu lhe der se tornará nele uma fonte de água que jorra para a vida eterna\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'A mulher Lhe disse: \"Senhor, dá-me dessa água, para que eu não tenha mais sede, e não tenha que vir aqui tirar”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Jesus disse-lhe: \"Vai, chama teu marido e volta aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'A mulher Lhe respondeu: \"Não tenho marido\". Jesus, então, disse-lhe: \"Disseste bem: \'Eu não tenho marido\',');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'pois já tiveste cinco, e o que tens agora não é teu! Nisto falaste a verdade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Disse-Lhe a mulher: \"Senhor, vejo que és profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Nossos pais adoravam neste monte, mas vós dizeis que Jerusalém é o lugar onde se deve adorar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Jesus lhe respondeu: \"Mulher, crê em Mim, que é chegado o tempo em que nem neste monte, nem em Jerusalém, adorareis o Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Vós adorais o que não conheceis; nós adoramos o que conhecemos, pois a salvação vem dos judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Entretanto, está chegando a hora, e já chegou, em que os verdadeiros adoradores adorarão o Pai em espírito e em verdade, porque são esses os adoradores que o Pai tem procurado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Deus é Espírito, e aqueles que O adoram devem adorá-Lo em espírito e em verdade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Disse-Lhe a mulher: \"Eu sei que o Messias está vindo, Aquele que é chamado \'Cristo\'. Quando Ele vier, explicará tudo para nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Disse-lhe Jesus: \"Eu Sou, O que fala contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'E naquele momento os Seus discípulos chegaram e ficaram admirados porque Ele falava com uma mulher; porém, nenhum deles Lhe perguntou: \"O que procuras?\" ou \"Por que falas com ela?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Então a mulher deixou o seu pote, voltou para a cidade, e disse às pessoas:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '\"Vinde, vede o homem que me contou todas as coisas que fiz. Não seria Este o Cristo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Eles deixaram a cidade e vieram até Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Enquanto isso, os discípulos estavam pedindo: \"Rabi, come\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Mas Ele lhes disse: \"Tenho uma comida para comer que vós não conheceis.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Os discípulos perguntavam um ao outro: \"Será que alguém Lhe trouxe algo para comer?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jesus lhes disse: \"Minha comida é fazer a vontade Daquele que Me enviou, e completar a Sua obra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Vós não dizeis: ‘Faltam ainda quatro meses para a colheita?’. Eu, porém, vos digo: levantai os olhos e vede os campos, pois já estão prontos para a colheita!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Aquele que está colhendo recebe seu salário e ajunta fruto para a vida eterna, para que se alegrem juntos o que semeia e o que colhe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Assim, o ditado é verdadeiro: ‘Um semeia e o outro colhe’.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Eu vos enviei para colher onde não trabalhastes; outros têm trabalhado, e vós tendes entrado no trabalho deles\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Muitos dos samaritanos daquela cidade acreditaram Nele por causa do testemunho daquela mulher: \"Ele me contou tudo que eu havia feito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Então, quando os samaritanos vieram até Ele, imploraram-Lhe que ficasse com eles, e Ele ficou ali dois dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'E muitos mais creram por causa da palavra Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'Eles diziam à mulher: \"Nós cremos, não por causa das suas palavras apenas, mas porque O ouvimos por nós mesmos, e agora sabemos que Este é realmente o Salvador do mundo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Depois daqueles dias, partiu para a Galileia;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'porque o próprio Jesus havia declarado que um profeta não tem honra na sua própria terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Quando Ele chegou à Galileia, os galileus O receberam. Eles tinham visto todas as coisas que Ele havia feito em Jerusalém na festa, pois eles também tinham ido à festa da Páscoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Veio novamente para Caná da Galileia, onde havia transformado água em vinho. Havia certo oficial do rei, cujo filho estava doente em Cafarnaum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Quando ele ouviu que Jesus havia deixado a Judeia e retornado para a Galileia, foi até Ele e implorou que descesse e curasse seu filho que estava à beira da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Jesus, então, disse-lhe: \"Se não virdes sinais e maravilhas, vós não crereis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'O oficial respondeu: \"Senhor, desce comigo antes que meu filho morra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Jesus lhe disse: \"Vai, teu filho vive\". O homem creu na palavra que Jesus havia dito, e foi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Enquanto ele estava descendo, seus servos o encontraram, dizendo que o seu filho estava vivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Então perguntou-lhes quando foi que ele tinha melhorado; e responderam: \"Ontem à noite, à sétima hora, a febre o deixou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'O pai reconheceu que aquela era a hora em que Jesus lhe havia dito: \"O teu filho vive\"; então ele e toda sua família creram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Este foi o segundo milagre que Jesus fez quando veio da Judeia para a Galileia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Depois disso, houve uma festa dos judeus, e Jesus subiu a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Existe em Jerusalém um tanque, perto da Porta das Ovelhas, que em aramaico se chama Betesda, e tem cinco entradas cobertas em volta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Um grande número de pessoas doentes, cegos, mancos e paralíticos, costumava ficar por ali nas portas');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, '');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Certo homem, que estava enfermo havia trinta e oito anos, estava ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Vendo-o deitado e sabendo que estava ali por muito tempo, Jesus lhe perguntou: \"Queres ser curado?”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'O homem enfermo respondeu: \"Senhor, eu não tenho ninguém para me colocar no tanque, quando a água é agitada. Enquanto estou indo, outro passa à minha frente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jesus lhe disse: Levanta-te, pega a tua maca, e anda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Imediatamente, o homem ficou são, pegou sua maca e andou. Aquele dia era um sábado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Então, os judeus disseram ao homem que havia sido curado: \"É sábado, e não te é permitido carregar a tua maca.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'O homem respondeu: \"Aquele que me curou disse: \'Pega a tua maca, e anda\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Perguntaram-lhe: \"Quem te disse: \'Pega a tua maca e anda?\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Entretanto, o homem curado não sabia quem o curara, pois Jesus tinha se retirado secretamente por haver uma grande multidão ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Mais tarde, Jesus encontrou o homem no templo, e lhe disse: \"Eis que ficaste saudável! Não peques mais, para que algo pior não te aconteça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'O homem se retirou e foi relatar aos judeus que Jesus é que o havia feito saudável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Então, os líderes dos judeus perseguiam Jesus, porque Ele estava fazendo estas coisas no sábado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Disse-lhes Jesus: \"Meu Pai trabalha até agora, e Eu trabalho também\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Por esta razão, os judeus ainda mais queriam matá-Lo, não apenas por quebrar o sábado, mas por chamar Deus de Seu próprio Pai, fazendo-Se igual a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Jesus lhes respondeu: \"Em verdade, em verdade, vos digo que o Filho não pode fazer nada por Si mesmo, apenas o que vê o Pai fazendo; pois o que o Pai faz, o Filho também faz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Porque o Pai ama o Filho, e mostra-Lhe tudo o que Ele mesmo faz, e mostrará coisas maiores que essas, e vós ficareis admirados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Pois, assim como o Pai ressuscita os mortos e lhes dá vida, o Filho também dá vida a quem Ele quiser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Portanto, o Pai a ninguém julga, mas Ele concedeu todo o julgamento ao Filho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'para que todos honrem o Filho, tal como honram o Pai. E aquele que não honra o Filho, não honra o Pai que O enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Em verdade, em verdade, vos digo, que aquele que ouve as Minhas palavras e crê Naquele que Me enviou tem a vida eterna e não será condenado, mas passou da morte para a vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Em verdade, em verdade, vos digo que virá o tempo, e já chegou, em que os mortos ouvirão a voz do Filho de Deus, e os que a ouvirem, viverão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Pois, assim como o Pai tem a vida em Si mesmo, da mesma maneira, Ele concedeu ao Filho ter a vida em Si mesmo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'e o Pai deu ao Filho autoridade para exercer julgamento, porque Ele é o Filho do Homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Não vos admireis com isso, pois está chegando o tempo em que aqueles que estiverem nos túmulos ouvirão a Sua voz e sairão:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'os que fizeram o bem, para a ressurreição da vida, e os que fizeram o mal, para a ressurreição do julgamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Eu não posso fazer nada por Mim mesmo. Como ouço, julgo, e o Meu julgamento é justo porque não estou procurando fazer a Minha vontade, mas a vontade Daquele que Me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Se, sozinho, Eu der testemunho de Mim mesmo, o Meu testemunho não é verdadeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Existe um Outro que testifica acerca de Mim, e Eu sei que o Seu testemunho sobre Mim é verdadeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Vós enviastes mensageiros a João, e ele testificou a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Entretanto, o testemunho que Eu recebo não vem do homem. Eu digo estas coisas a fim de que vós sejais salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'João era uma lâmpada que ardia e iluminava e, por um pouco de tempo, vos alegrastes com sua luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Contudo, o testemunho que tenho é maior do que o de João, pois as obras que o Pai Me deu para realizar, as mesmas obras que faço, testificam de Mim que o Pai me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'O próprio Pai, que Me enviou, testificou a Meu respeito. Vós nunca ouvistes Sua voz, nem vistes Sua forma;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'e nem tendes a Sua palavra em vós, pois não credes Naquele que Ele enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Examinais as Escrituras porque acreditais ter nelas a vida eterna, e essas mesmas Escrituras testemunham a Meu respeito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'mas não quereis vir a Mim para terdes vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Eu não recebo glória de homens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'mas sei que não tendes em vosso interior o amor de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Eu vim em Nome de Meu Pai, e não Me recebestes; se outro qualquer vier em seu próprio nome, vós o recebereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Como podeis crer, vós que recebeis glória uns dos outros, mas não buscais a glória que vem do único Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Não penseis que Eu mesmo vos acusarei perante o Pai. Aquele que vos acusa é Moisés, em quem pondes a vossa esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Se tivésseis crido em Moisés, creríeis em Mim, porque ele testemunhou a Meu respeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Porém, se não crestes no que ele escreveu, como crereis em Minhas palavras?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Após estas coisas, Jesus foi para o outro lado do mar da Galileia, também chamado o mar de Tiberíades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Uma grande multidão O estava seguindo, porque eles viam os sinais que Jesus fazia naqueles que estavam doentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Jesus subiu a encosta da montanha e lá sentou-Se com Seus discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'A Páscoa, a festa dos judeus, estava próxima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Quando Jesus olhou e viu uma grande multidão vindo em Sua direção, disse a Filipe: “Onde iremos comprar pão para estes comerem?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Jesus disse isso para experimentar Filipe, porque Ele sabia o que estava prestes a fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Respondeu-Lhe Filipe: \"Duzentos denários em pão não seriam suficientes para que cada um recebesse ao menos um pouco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Um dos discípulos, André, irmão de Simão Pedro, disse a Jesus:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '\"Há aqui um menino que tem cinco pães de cevada e dois peixes; mas o que é isto para tantos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Jesus respondeu: “Fazei o povo assentar-se\". Havia muita grama naquele lugar. Então os homens se assentaram, em número de uns cinco mil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Então, Jesus tomou os pães e, depois de dar graças, deu-os aos que estavam sentados. De igual modo, Ele o fez com os peixes, tanto quanto queriam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Quando o povo se satisfez, Jesus disse a Seus discípulos: \"Recolhei os pedaços que restaram para que nada seja desperdiçado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Então, os discípulos ajuntaram e encheram doze cestas com os pedaços dos cinco pães de cevada, deixados por aqueles que haviam comido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Quando as pessoas viram este sinal que Jesus fez, disseram: “Este é verdadeiramente O profeta que devia vir ao mundo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Quando Jesus percebeu que eles estavam prestes a vir e agarrá-lo à força para fazê-Lo rei, retirou-Se sozinho novamente para o monte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Quando a noite chegou, Seus discípulos desceram ao lago.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'E, tendo entrado em um barco, foram pelo mar rumo a Cafarnaum. Já estava escuro nessa hora, e Jesus ainda não havia vindo encontrá-los.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'E, por causa de um forte vento que soprava, o mar estava ficando agitado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Então, quando os discípulos tinham remado por volta de vinte e cinco ou trinta estádios, viram Jesus caminhando sobre o mar, vindo para perto do barco, e ficaram com medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Mas Jesus lhes disse: “Sou Eu! Não temais\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Então, eles prontamente O receberam no barco, e imediatamente o barco chegou ao seu destino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'No dia seguinte, a multidão que estava do outro lado do mar viu que não havia nenhum outro barco lá, exceto um, e que Jesus não tinha entrado nele com Seus discípulos, mas que Seus discípulos tinham ido sozinhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Contudo, havia alguns barcos que vieram de Tiberíades perto do lugar onde eles comeram o pão depois do Senhor ter dado graças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Quando a multidão descobriu que nem Jesus nem Seus discípulos estavam lá, entraram nos barcos e foram a Cafarnaum procurando por Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'E encontrando-O no outro lado do Lago, disseram-Lhe: \"Rabi, quando chegaste aqui?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jesus lhes respondeu, dizendo: \"Em verdade, em verdade, vós Me procurais, não porque vistes sinais, mas porque comestes dos pães e vos saciastes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Trabalhai não pela comida que perece, mas pela comida que permanece para a vida eterna, a qual o Filho do Homem vos dará, porque Deus, o Pai, O selou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Então, eles disseram a Jesus: \"O que devemos fazer para realizar as obras de Deus?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jesus respondeu: \"Esta é a obra de Deus: que creiais Naquele que Ele enviou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Então, eles Lhe disseram: \"Que sinal operas, para que vejamos e creiamos em Ti? O que fazes?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Nossos pais comeram do maná no deserto, como está escrito: \'Ele deu-lhes para comer o pão dos céus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Então, Jesus lhes respondeu: \"Em verdade, em verdade, vos digo que não foi Moisés que vos deu o pão do céu, mas é o Meu Pai que vos dá o verdadeiro Pão de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Porque o Pão de Deus é o que desce do céu e dá vida ao mundo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Então eles disseram a Jesus: \"Senhor, dá-nos sempre desse Pão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jesus lhes disse: “Eu sou o Pão da Vida, aquele que vem a Mim não terá fome, e aquele que crê em Mim jamais terá sede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Mas, de fato, Eu vos disse que Me vistes, e ainda assim não crestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Todo aquele que o Pai Me dá virá a Mim, e o que vem a Mim, Eu nunca o lançarei fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Porque vim do céu, não para fazer Minha própria vontade, mas a vontade Daquele que Me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'E esta é a vontade Daquele que Me enviou, que Eu não perca nenhum de todos os que Ele Me deu, mas os ressuscite no último dia”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Porque esta é a vontade do Meu Pai, que todo o que vê o Filho e Nele crê, tenha a vida eterna; e Eu o ressuscitarei no último dia”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Então, os judeus murmuravam a respeito Dele porque disse: \"Eu sou o Pão que desceu do céu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'Eles diziam: \"Não é Este Jesus, o Filho de José, cujo pai e mãe conhecemos? Como, pois, Ele diz: \'Eu desci do céu\'?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jesus respondeu-lhes: \"Não murmureis entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Nenhum homem pode vir a Mim, a menos que o Pai que Me enviou o traga, e Eu o ressuscitarei no último dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Está escrito nos profetas: \'Todos eles serão ensinados por Deus. Todos que têm ouvido e aprendido do Pai vêm a Mim’.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Não que alguém tenha visto o Pai, exceto Aquele que vem de Deus; Este viu o Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Em verdade, em verdade, vos digo que aquele que crê tem a vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Eu sou o Pão da Vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Vossos pais comeram o maná no deserto, e morreram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Este é o Pão que desce do céu, para que aquele que comer Dele não morra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Eu sou o Pão Vivo que desceu do céu. Se alguém comer deste Pão, viverá para sempre. O pão que Eu darei é a Minha carne para a vida do mundo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Os judeus ficaram irados entre si, e começaram a perguntar, dizendo: \"Como Este pode nos dar a Sua carne a comer?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jesus, então, disse-lhes: \"Em verdade, em verdade, vos digo que se não comerdes a carne do Filho do Homem, e beberdes o Seu sangue, não tendes vida em vós mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Quem come a Minha carne e bebe o Meu sangue tem vida eterna, e Eu o ressuscitarei no último dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Porque Minha carne é verdadeira comida, e Meu sangue é verdadeira bebida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Aquele que come Minha carne e bebe Meu sangue permanece em Mim, e Eu nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Assim como o Pai que vive Me enviou, e assim como Eu vivo por causa do Pai, aquele que de Mim se alimenta também por Mim viverá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Este é o Pão que desceu do céu, não como aquele que vossos pais comeram, e morreram. Aquele que comer este Pão viverá para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Jesus disse essas coisas na sinagoga, enquanto ensinava em Cafarnaum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Então, muitos dos Seus discípulos, quando ouviram isto, disseram: \"Dura é esta palavra; quem pode ouvi-la?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Mas Jesus, sabendo por Si mesmo que Seus discípulos estavam murmurando sobre isso, disse-lhes: \"Isto vos escandaliza?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'E se virdes o Filho do Homem subindo para onde Ele estava antes?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'É o Espírito que dá vida. A carne não produz nada. As palavras que Eu vos tenho dito são espírito e vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Ainda há alguns de vós que não creem\". Porque Jesus sabia desde o início quem eram os que não criam e quem O havia de trair.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Ele disse: \"É por isso que vos disse que ninguém pode vir a Mim, a menos que isso lhe seja concedido pelo Pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Depois disso, muitos dos Seus discípulos voltaram, e não mais andaram com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Jesus, então, disse aos doze: \"Vós não quereis também retirar-vos?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Simão Pedro Lhe respondeu: “Senhor, para quem iremos? Tu tens as palavras de vida eterna,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'e nós cremos e viemos a saber que és o Santo de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jesus respondeu: \"Eu não vos escolhi a vós, os doze? Contudo, um de vós é um diabo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Ele falava de Judas, o Filho de Simão Iscariotes, porque seria ele, um dos Doze, quem haveria de traí-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Após estas coisas, Jesus viajou pela Galileia, pois não queria andar pela Judeia, porque os judeus desejavam matá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'A festa judaica dos Tabernáculos estava próxima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Disseram-Lhe, então, seus irmãos: \"Deixa este lugar, e vai para a Judeia, assim os Teus discípulos poderão ver as coisas que Tu fazes;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'porque ninguém faz nada em segredo quando quer ser conhecido publicamente. Se fazes essas coisas, mostra-Te para o mundo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Pois nem mesmo os Seus irmãos acreditavam Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Então, disse-lhes Jesus: \"O Meu tempo ainda não chegou, mas o vosso tempo sempre está presente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'O mundo não pode vos odiar, mas odeia a Mim, porque Eu testifico que suas obras são más.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Subi vós à festa. Eu não subo porque o Meu tempo ainda não está cumprido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Após dizer-lhes essas coisas, Ele permaneceu na Galileia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Contudo, após Seus irmãos subirem para a festa, Ele também subiu; não publicamente, mas em secreto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Os judeus estavam procurando-O na festa, dizendo: \"Onde Ele está?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Na multidão, havia várias opiniões sobre Ele. Alguns diziam: \"Ele é um bom homem\"; outros diziam: \"Não; Ele engana as multidões\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Mesmo assim, ninguém falava abertamente sobre Ele, por medo dos judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Quando a festa estava na metade, Jesus subiu ao templo e começou a ensinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Então, os judeus ficaram admirados, e diziam: \"Como este homem sabe tanto sem nunca ter sido instruído?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jesus respondeu-lhes: \"O Meu ensino não é Meu, mas Daquele que Me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Se alguém deseja realizar a Sua vontade, saberá sobre os Seus ensinos, se isso vem de Deus, ou se Eu falo de Mim mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Aquele que fala de si próprio procura sua glória, mas o que busca a glória daquele que o enviou, esse é verdadeiro, e não há injustiça nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Não foi Moisés que vos deu a Lei? Contudo, nenhum de vós a pratica. Por que procurais matar-Me?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'A multidão respondeu: \"Tens um demônio. Quem procura matar-Te?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jesus respondeu e disse-lhes: \"Eu realizei uma só obra, e todos vós estais admirados com isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Moisés vos deu a circuncisão — não que isto tenha vindo de Moisés, mas dos patriarcas —, e no sábado circuncidais um homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Se um homem é circuncidado no sábado, para que a Lei de Moisés não seja quebrada, por que estais enraivecidos por Eu ter curado um homem por completo no sábado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Não julgueis de acordo com a aparência, mas julgai corretamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Alguns de Jerusalém diziam: \"Não é Este a quem eles procuram matar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'E eis que Ele fala abertamente, e nada Lhe dizem. Será que as autoridades reconheceram que Este é realmente o Cristo?”');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Sabemos de onde Ele é, mas quando o Cristo vier, ninguém saberá de onde Ele é\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Então, Jesus levantou a voz no templo, ensinando e dizendo: \"Vós Me conheceis e sabeis de onde sou; não venho de Mim mesmo, mas Aquele que Me enviou é verdadeiro, e vós não O conheceis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Eu O conheço porque venho Dele e Ele Me enviou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Então, eles procuravam prendê-Lo, mas ninguém Lhe pôs a mão porque a hora Dele não havia chegado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Todavia, muitos da multidão criam Nele. Eles diziam: \"Quando o Cristo vier, fará Ele mais sinais que Este homem tem feito?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Os fariseus ouviram a multidão sussurrar essas coisas sobre Jesus, e os principais sacerdotes e os fariseus enviaram oficiais para prendê-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Então, Jesus lhes disse: \"Ainda estou convosco por um curto período de tempo, e então vou para Aquele que Me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Vós Me buscareis, mas não Me encontrareis; e para onde vou, não podeis ir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Por esta razão, os judeus falavam entre si: \"Para onde Este homem irá, que não seremos capazes de encontrá-Lo? Ele irá para a dispersão entre os gregos, para ensiná-los?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'O que significa esta palavra que Ele falou: \'Vós Me buscareis e não Me encontrareis; para onde vou, não podeis ir\'?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'Chegando o último dia, o grande dia da festa, Jesus levantou-Se e em alta voz disse-lhes: \"Se alguém tem sede, venha a Mim e beba.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Aquele que crê em Mim, como diz a Escritura, do seu interior fluirão rios de água viva\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Ele disse isso sobre o Espírito que haviam de receber os que Nele cressem; o Espírito ainda não havia sido entregue, porque Jesus ainda não tinha sido glorificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Alguns da multidão, quando ouviram essas palavras, disseram: \"Este certamente é o Profeta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Outros disseram: \"Este é o Cristo\". Mas alguns disseram: \"Poderia o Cristo vir da Galileia?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'A Escritura não diz que o Cristo virá da descendência de Davi, e de Belém, do povoado de onde era Davi?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Então, iniciou-se uma divisão entre a multidão por causa Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Alguns dentre eles queriam prendê-Lo, porém ninguém Lhe pôs a mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Então, os oficiais vieram até os principais sacerdotes e fariseus, e estes lhes perguntaram: \"Por que não O trouxestes?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Os oficiais responderam: \"Ninguém jamais falou como Ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Por isso, os fariseus responderam-lhes: \"Vós também fostes enganados?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Alguém de entre as autoridades ou algum dos fariseus acreditaram Nele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Mas a multidão, que não conhece a Lei, é maldita\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Nicodemos, um dos fariseus que havia-se encontrado com Jesus anteriormente, disse-lhes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '\"As nossas leis julgam um homem sem primeiro ouvi-lo ou saber o que ele faz?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Eles responderam: \"És também galileu? Procura e vê que nenhum profeta surge da Galileia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, '[Então, retornaram todos para suas casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Jesus seguiu para o Monte das Oliveiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'De manhã cedo, foi novamente ao templo, e todo o povo veio até Ele; Ele se assentou e começou a ensiná-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Os escribas e fariseus trouxeram uma mulher apanhada em adultério; colocando-a no meio de todos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'e disseram-Lhe: \"Mestre, esta mulher foi apanhada em flagrante cometendo adultério.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'A Lei de Moisés nos ordena que tais mulheres sejam apedrejadas; Tu, portanto, que dizes?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Eles diziam isso para prová-Lo, para que tivessem algo para acusá-Lo, mas Jesus, inclinando-Se, começou a escrever no chão com o dedo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Como insistissem na pergunta, Ele levantou-Se e disse-lhes: \"Aquele que não tiver pecado, seja o primeiro a lhe atirar uma pedra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Então, inclinou-Se novamente e voltou a escrever no chão com Seu dedo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Quando ouviram isso, saíram um por um, começando pelos mais velhos; e Jesus foi deixado sozinho com a mulher ficando no meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Jesus Se levantou e disse-lhe: \"Mulher, onde estão os teus acusadores? Nenhum te condenou?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Ela respondeu: \"Nenhum, Senhor\". Jesus disse: \"Nem Eu te condeno. Vai e, a partir de agora, não peques mais.”]');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Novamente Jesus lhes falou: \"Eu sou a luz do mundo. Aquele que Me segue não andará em trevas, mas terá a luz da vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Os fariseus Lhe disseram: \"Tu dás testemunho de Ti mesmo; o Teu testemunho não é verdadeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jesus respondeu-lhes: \"Ainda que Eu dê testemunho de Mim mesmo, Meu testemunho é verdadeiro. Eu sei de onde vim e para onde vou, mas vós não sabeis de onde venho e nem para onde vou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Vós julgais segundo a carne, Eu a ninguém julgo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'E se Eu julgo, Meu julgamento é verdadeiro, porque não estou sozinho, mas Eu estou com o Pai que Me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'E na vossa Lei está escrito que o testemunho de dois homens é verdadeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Eu dou testemunho de Mim mesmo, e o Pai que Me enviou dá testemunho de Mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Eles disseram: \"Onde está o Teu Pai?\" Jesus respondeu-lhes: \"Vós não conheceis a Mim, nem a Meu Pai; se Me conhecêsseis, saberíeis quem é o Meu Pai”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Ele disse essas palavras perto da caixa das ofertas, quando ensinava no templo, e ninguém O prendeu porque Sua hora ainda não havia chegado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'E lhes disse outra vez: \"Vou embora, e Me procurareis, mas morrereis em vosso pecado. Para onde vou não podeis ir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'E os judeus diziam: \"Será que vai-Se matar? Pois diz: ‘Para onde vou, vós não podeis ir’”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'E dizia-lhes: \"Vós sois daqui de baixo, Eu sou lá de cima. Vós sois deste mundo, Eu não sou deste mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Por isso Eu vos disse que morrereis nos vossos pecados. Pois se não crerdes que EU SOU, morrereis nos vossos pecados”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Diziam-Lhe então: \"Quem és Tu?\". Jesus lhes respondeu: \"O que Eu tenho lhes dito desde o princípio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Tenho muitas coisas para falar e para julgar a vosso respeito. Entretanto, Aquele que Me enviou é verdadeiro, e as coisas que Dele ouvi, essas coisas digo ao mundo”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Eles não entenderam que Ele falava do Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Jesus lhes disse, portanto: \"Quando tiverdes levantado o Filho do Homem, então sabereis que EU SOU, e que nada faço por Mim mesmo; mas falo como o Pai Me ensinou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'E Aquele que Me enviou está Comigo, e Ele não Me deixa sozinho, pois Eu sempre faço as coisas que Lhe agrada\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Enquanto Jesus dizia essas coisas, muitos creram Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Jesus disse aos judeus que creram Nele: \"Se vós permanecerdes na Minha palavra, sereis verdadeiramente Meus discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'E conhecereis a Verdade, e a Verdade vos libertará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Eles responderam: \"Somos descendentes de Abraão, e nunca fomos escravos de ninguém, como podes Tu dizer: \'Sereis libertos\'?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jesus lhes respondeu: \"Em verdade, em verdade, vos digo que quem comete pecado é escravo do pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'O escravo não permanece na casa para sempre, mas o filho permanece para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Portanto, se o Filho vos libertar, verdadeiramente sereis livres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Eu sei que sois descendentes de Abraão; vós procurais Me matar porque as Minhas palavras não encontram lugar em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Eu falo o que vi de Meu Pai, e vós fazeis o que ouvistes de vosso pai”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Eles responderam: \"Nosso pai é Abraão\". Jesus lhes disse: \"Se fôsseis filhos de Abraão, faríeis as obras de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Contudo vós procurais matar-Me, que tenho lhes contado a verdade que ouvi de Deus; mas Abraão não fez isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Vós fazeis as obras de vosso pai\". Eles disseram: \"Nós não nascemos de imoralidade sexual; nós temos um Pai, Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jesus disse: \"Se Deus fosse vosso Pai, vós Me amaríeis, pois venho de Deus, e aqui estou; porque não vim por Mim mesmo, mas Ele Me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Por que vós não entendeis as Minhas palavras? É porque sois incapazes de compreender Minha palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Vós sois de vosso pai, o diabo, e vós quereis satisfazer vosso pai. Ele foi homicida desde o princípio, e não permaneceu na verdade, porque a verdade não estava nele. Quando ele fala uma mentira, fala o que vem de sua natureza, porque é mentiroso e pai da mentira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Mas, porque Eu falo a verdade, vós não credes em Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Quem dentre vós pode acusar-Me de algum pecado? Se digo a verdade, por que não credes em Mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Aquele que é de Deus ouve as Suas palavras; por isso vós não ouvis, porque não sois de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Os judeus responderam-Lhe: \"Acaso não temos razão ao dizermos que Tu és samaritano e que tens demônio?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jesus lhes respondeu: \"Eu não tenho demônio; mas Eu honro o Meu Pai, e vós Me desonrais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Eu não busco Minha própria glória; há quem a procure e julgue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Em verdade, em verdade, vos digo que, se alguém guarda a Minha palavra, jamais verá a morte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Os judeus disseram-lhe: \"Agora sabemos que tens demônio. Abraão e os profetas morreram, mas Tu dizes: \'Se alguém guardar a Minha palavra, nunca verá a morte\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Acaso, Tu és maior que nosso pai Abraão que morreu? Os profetas também morreram. Quem pretendes ser?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jesus lhes respondeu: \"Se Eu glorificasse a Mim mesmo, Minha glória não seria nada; é o Meu Pai Quem Me glorifica, Aquele que vós dizeis ser vosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Vós não O conheceis, mas Eu O conheço. Se Eu dissesse que Eu não O conheço, seria mentiroso como vós. Entretanto, Eu O conheço, e guardo a Sua palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Seu pai Abraão se regozijou ao ver o Meu dia; ele viu e se alegrou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Os judeus disseram: \"Tu não tens nem cinquenta anos de idade, e viste Abraão?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jesus lhes respondeu: \"Em verdade, em verdade, vos digo que antes que Abraão existisse, EU SOU\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Então, pegaram pedras para apedrejá-Lo, mas Jesus escondeu-Se e saiu do templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Enquanto Jesus passava, viu um homem cego de nascença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Seus discípulos perguntaram-Lhe: \"Rabi, quem pecou para que esse homem nascesse cego? Ele ou seus pais?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jesus respondeu: \"Nem ele nem seus pais pecaram, mas foi para que as obras do Senhor fossem reveladas nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Devemos fazer a obra Daquele que Me enviou, enquanto ainda é dia. A noite está chegando, quando ninguém pode trabalhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Enquanto Eu estou no mundo, Eu sou a Luz do mundo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Depois que Jesus disse essas coisas, cuspiu no chão, fez uma lama com sua saliva, e ungiu os olhos do homem com essa lama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'Jesus lhe disse: \"Vai, lava-te no tanque de Siloé (que é traduzido como \'enviado\')\". Então o homem foi, lavou-se e voltou vendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Então, os vizinhos daquele homem que o viram anteriormente como pedinte diziam: \"Não é este aquele que costumava sentar e mendigar?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Alguns diziam: \"É ele\". Outros diziam: \"Não, mas se parece com ele\". Porém, ele dizia: \"Sou eu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Eles lhe disseram: \"Mas, como teus olhos foram abertos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Ele respondeu: \"O homem chamado Jesus fez uma lama e ungiu meus olhos; então, me disse: \'Vai e lava-te no Siloé\'. Então eu fui, lavei-me e passei a enxergar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Eles lhe disseram: \"Onde está Ele?\". Ele respondeu: \"Eu não sei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Trouxeram o homem que era cego para os fariseus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Aquele dia era sábado, quando Jesus fez a lama e abriu seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Mais uma vez os fariseus lhe perguntaram como havia recuperado a visão: \"Ele colocou uma lama em meus olhos, eu os lavei, e agora posso ver\", disse o homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Alguns dos fariseus disseram: \"Esse homem não vem de Deus, pois, não guarda o sábado\". Outros diziam: \"Como alguém pode fazer tais sinais sendo pecador?\". E houve uma divisão entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Então, perguntaram ao cego novamente: \"O que dizes tu Daquele que te abriu os olhos?\". O cego disse: \"Ele é profeta\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Nesse momento, os judeus ainda não acreditavam que ele havia sido cego e tinha recebido a visão até que chamaram os pais do homem que havia passado a enxergar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'Eles perguntaram a seus pais: \"É esse o vosso filho que nasceu cego? Como pode ele agora enxergar?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Seus pais então responderam-lhes: \"Nós sabemos que esse é nosso filho, e que nasceu cego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Como ele agora enxerga nós não sabemos. Perguntai a ele. Ele é adulto e pode responder por si\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Seus pais disseram isso porque eles tinham medo dos judeus, pois estes haviam concordado que qualquer um que confessasse a Jesus como Cristo deveria ser expulso da sinagoga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Por causa disso seus pais disseram: \"Ele é adulto; pergunte a ele.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Pela segunda vez, eles chamaram o homem que havia sido cego e disseram-lhe: \"Dá glória a Deus! Nós sabemos que Esse Homem é pecador\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Então aquele homem respondeu: \"Se Ele é pecador ou não, eu não sei. Uma coisa eu sei: eu era cego e agora vejo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Então, disseram-lhe: \"O que Ele fez por ti? Como Ele te abriu os olhos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Ele respondeu: \"Eu já vos disse, e vós não me ouvistes! Por que querem ouvir de novo? Por acaso também quereis fazer-vos Seus discípulos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Eles o insultaram e disseram: \"Tu és discípulo Dele; nós porém somos discípulos de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Sabemos que Deus falou a Moisés, mas Esse Homem não sabemos de onde vem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'O homem respondeu-lhes, dizendo: \"Ora, isso é surpreendente! Vós não sabeis de onde Ele é, e ainda assim Ele abriu os meus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Nós sabemos que Deus não escuta a pecadores, mas se alguém O adora e faz a Sua vontade, Deus o escuta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Desde o início do mundo, nunca se ouviu que alguém tenha aberto os olhos de um homem nascido cego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Se Esse Homem não fosse enviado por Deus, Ele não poderia fazer coisa alguma\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Eles responderam e disseram-lhe: \"Nasceste em pecado, e agora estás nos ensinando?\". Então, eles o expulsaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jesus ouviu que eles o haviam expulsado da sinagoga. Ele o encontrou e disse-lhe: \"Crês no Filho do Homem?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Ele respondeu dizendo: \"Quem é esse, Senhor, para que eu creia Nele?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jesus disse-lhe: \"Já O tens visto, e é O que fala contigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'O homem disse: \"Senhor, eu creio\". Então, adorou-O.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Jesus disse: \"Foi para julgamento que Eu vim a esse mundo, para que aqueles que não veem vejam, e aqueles que veem fiquem cegos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Alguns dos fariseus que estavam lá, O ouviram dizer essas coisas, e perguntaram-Lhe: \"Nós também somos cegos?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jesus lhes disse: \"Se fôsseis cegos não teríeis pecado. Porém, como dizeis: \'Nós vemos\', então vosso pecado permanece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Em verdade, em verdade, vos digo que aquele que não entra pelo portão do aprisco, mas vem por outro caminho, esse é ladrão e assaltante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Aquele que entra pelo portão é o pastor das ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Para ele, o porteiro abre; as ovelhas ouvem sua voz, ele chama suas ovelhas pelo nome, e as conduz para fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Depois de ter feito sair todas as que lhe pertencem, vai adiante delas, e as ovelhas o seguem, pois conhecem sua voz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Elas não seguirão o desconhecido; mas, ao invés disso, irão evitá-lo, pois não conhecem a voz de estranhos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Jesus lhes contava essas parábolas, mas eles não compreendiam o que lhes dizia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Então, disse-lhes novamente: \"Em verdade, em verdade, vos digo: Eu sou a porta das ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Todos os que vieram antes de Mim são ladrões e assaltantes, mas as ovelhas não lhes ouviram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Eu sou a Porta. Se alguém entrar por Mim, será salvo; entrará, sairá e achará pastagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'O ladrão não vem senão para roubar, matar e destruir. Eu vim para que tenham vida, e a tenham em abundância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Eu sou o Bom Pastor. O bom pastor dá sua vida pelas ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Aquele que é mercenário e, não, pastor, a quem as ovelhas não pertencem, quando vê o lobo se aproximar, abandona-as e foge. E o lobo as arrebata e as dispersa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Ele foge, porque é mercenário e não se importa com as ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Eu sou o Bom Pastor, e conheço as Minhas ovelhas, e elas Me conhecem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'O Pai Me conhece, Eu conheço o Pai, e dou a Minha vida pelas ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Tenho outras ovelhas que não são deste aprisco. A estas, devo também trazê-las, e elas ouvirão a Minha voz, para que haja um só rebanho e um só Pastor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Por isso, o Pai Me ama: Eu dou Minha vida para reavê-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Ninguém a tira de Mim, mas Eu mesmo a dou. Tenho autoridade para dá-la e para tomá-la de volta. Recebi esse mandamento do Pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Surgiu uma nova divisão entre os judeus por causa dessas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Muitos deles diziam: \"Ele tem demônio, e é louco. Por que O escutais?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Outros diziam: \"Essas declarações não são de alguém possuído por demônio. Pode um demônio abrir os olhos de um cego?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Era, então, a festa da Dedicação, em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Era inverno, e Jesus andava pelo templo, no Pórtico de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Então, um dos judeus aproximou-se Dele e Lhe disse: \"Até quando nos deixarás em suspense? Se Tu és o Cristo, dize-nos francamente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jesus respondeu: \"Já lhes disse, mas vós não credes. As obras que Eu realizo em nome de Meu Pai dão testemunho de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Vós não credes em Mim porque não sois Minhas ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'As Minhas ovelhas ouvem a Minha voz; Eu as conheço, e elas Me seguem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'Eu lhes dou vida eterna; jamais perecerão, e ninguém as tomará de Minha mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Meu Pai, que as deu a Mim, é maior do que todos, e ninguém poderá tomá-las de Sua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Eu e o Pai somos Um\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Então, os judeus começaram a pegar em pedras novamente, a fim de apedrejá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jesus disse: \"Tenho-lhes apresentado muitas boas obras da parte do Pai. Por qual delas vós Me apedrejais?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Responderam-Lhe os judeus: \"Não é por causa das boas obras, mas pela blasfêmia, porque Tu, sendo homem, Te fazes Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jesus lhes respondeu: \"Não está escrito na vossa Lei: \'Eu disse: Vós sois deuses?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Se Ele chamou de deuses àqueles a quem a Palavra de Deus veio — e a Escritura não pode ser anulada —,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'vós dizeis sobre Aquele a quem Deus santificou e enviou: \'Estás blasfemando\', porque Eu disse: \'Sou o Filho de Deus\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Se Eu não faço as obras de Meu Pai, não creiais em Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Porém, se as faço, ainda que não creiais em Mim, crede nas obras, a fim de que saibais e reconheceis que o Pai está em Mim, e Eu Nele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Tentaram outra vez prendê-Lo, mas Ele se escapou de suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Jesus dirigiu-Se novamente para além do Jordão, para o local onde João batizava, e permaneceu lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Muitas pessoas vinham até Ele, e diziam: \"João, na verdade, não fez nenhum sinal, mas todas as coisas que ele dizia sobre este homem são verdade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Muitos ali creram em Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Certo homem chamado Lázaro estava doente. Ele era de Betânia, povoado de Maria e de sua irmã Marta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Essa era a mesma Maria que havia ungido o Senhor com mirra e secado Seus pés com os cabelos, cujo irmão Lázaro estava doente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'As irmãs mandaram uma mensagem a Jesus, que dizia: \"Senhor, aquele a quem amas está doente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Quando Jesus ouviu isso, respondeu: \"Essa doença não é para a morte, mas é para a glória de Deus, para que o Filho de Deus seja glorificado por meio dela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Jesus amava a Marta, a sua irmã e a Lázaro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Quando ouviu falar que Lázaro estava doente, permaneceu mais dois dias no local onde estava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Depois disso, disse aos discípulos: \"Vamos outra vez para a Judeia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Os discípulos Lhe disseram: \"Rabi, os judeus há pouco queriam apedrejar-Te, e mesmo assim queres voltar para lá?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jesus respondeu: \"O dia não tem doze horas? Se alguém anda de dia, não tropeça, pois vê a luz do dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Entretanto, se ele anda à noite, tropeça, porque não há luz nele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Jesus disse essas coisas e, após dizer isso, disse-lhes: \"Nosso amigo Lázaro dormiu, mas Eu irei lá para acordá-lo de seu sono\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Os discípulos disseram-Lhe: \"Senhor, se ele dorme, irá melhorar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Jesus falava da morte de Lázaro, mas eles pensavam que Jesus estava falando do repouso do sono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Então, Jesus lhes disse claramente: \"Lázaro está morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Por vossa causa, alegro-Me por não ter estado lá, para que creiais. Mas vamos até ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Então, Tomé, chamado Dídimo, disse aos outros discípulos: \"Vamos também para morrermos com Jesus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Quando Jesus chegou, Ele descobriu que Lázaro já estava no sepulcro havia quatro dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Betânia era perto de Jerusalém, mais ou menos quinze estádios de distância.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Muitos judeus tinham vindo consolar Marta e Maria, por causa de seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Então Marta, quando soube que Jesus estava vindo, foi até Ele, mas Maria permaneceu em casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Marta, então, disse a Jesus: \"Senhor, se estivesses aqui, meu irmão não teria morrido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Mesmo agora, eu sei que qualquer coisa que pedires a Deus, Ele Te dará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Jesus respondeu a ela: \"Teu irmão ressuscitará\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marta disse: \"Eu sei que ele ressuscitará na ressurreição no último dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jesus lhe disse: \"Eu sou a ressurreição e a vida, aquele que crê em Mim, mesmo que morra, viverá,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'e aquele que vive e crê em Mim nunca morrerá. Crês nisso?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Ela Lhe disse: \"Sim, Senhor, eu creio que Tu és o Cristo, o Filho de Deus, que devia vir ao mundo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Ao dizer isso, ela se retirou e chamou Maria à parte, dizendo: \"O Mestre está aqui, e está chamando a ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Quando Maria ouviu isso, levantou-se depressa e foi ao Seu encontro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Jesus ainda não havia chegado no povoado, mas ainda estava no local onde Marta O encontrara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Os judeus que a estavam consolando, ao notarem que Maria se levantou apressadamente e partiu, seguiram-na, pois supunham que ela iria ao sepulcro para ali chorar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Maria, então, ao chegar onde Jesus estava, vendo-O, ajoelhou-se aos Seus pés dizendo: \"Senhor, se estivesses aqui, meu irmão não teria morrido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Ao vê-la chorar assim, como também os judeus que a acompanhavam, Jesus ficou intensamente comovido em espírito. E, sob o impulso de profunda emoção,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'disse-lhes: \"Onde o pusestes?\". Eles responderam: \"Senhor, vem e vê\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jesus chorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Alguns judeus disseram entre eles: \"Vede como Ele amava Lázaro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Já outros disseram: \"Não poderia este Homem, que deu vista ao cego, fazer que também este homem não morresse?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Então Jesus, profundamente comovido, foi até o sepulcro. Era uma caverna com uma grande pedra posta na entrada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jesus disse: \"Tirai a pedra!\". Marta, irmã de Lázaro, o que havia morrido, disse a Jesus: \"Senhor, ele já está em decomposição, pois está morto há quatro dias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Jesus lhe respondeu: Eu não te disse que se creres, verás a glória de Deus?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Então, removeram a pedra. Jesus olhou para os céus e disse: \"Pai, agradeço por teres-Me ouvido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Eu sei que sempre Me ouves, mas é por causa da multidão que está em pé à minha volta que Eu disse isso, para que creiam que Me enviaste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Depois de dizer essas coisas, Jesus exclamou em alta voz: \"Lázaro, vem para fora!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'O morto saiu com as mãos e os pés enfaixados, e o rosto coberto por um pano. Jesus ordenou-lhes: \"Desamarrai-o e deixai-o ir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Então, muitos dos judeus que vieram visitar Maria, e viram o que Jesus fez, creram Nele;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'mas alguns deles foram até os fariseus, e contaram-lhes as coisas que Jesus havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Então, os principais sacerdotes e os fariseus reuniram no Sinédrio, e disseram: \"Que faremos? Esse Homem está fazendo muitos sinais milagrosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Se O deixarmos assim, muitos crerão Nele; então, os romanos virão e nos tirarão o nosso lugar e a nossa nação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Entretanto, um deles, chamado Caifás, que naquele ano era o sumo sacerdote, tomou a palavra e disse-lhes: \"Vós não sabeis de nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'Não estais levando em conta o fato de que é melhor para vós que um homem morra pelo povo, do que perecer a toda uma nação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Ele não havia dito aquilo dele mesmo, mas, por ser o sumo sacerdote naquele ano, profetizou que Jesus morreria pela nação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'E não somente pela nação, mas também pelos filhos de Deus, que estão espalhados, para os reunir em um só povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Então, daquele dia em diante, resolveram planejar como matar Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Jesus não andava mais em público entre os judeus, mas retirou-Se para o interior, em uma região próxima do deserto, em um povoado chamado Efraim, onde Ele ficou com os Seus discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'A Páscoa dos judeus estava próxima, e muitos foram daquele lugar para Jerusalém, a fim de se purificarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Então, eles procuravam Jesus, e diziam uns aos outros no templo: \"Que vos parece? Será que Ele não virá à festa?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Os chefes dos sacerdotes e os fariseus haviam ordenado que, se alguém soubesse onde Jesus estava, que O denunciasse, para que eles O prendessem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Seis dias antes da Páscoa, Jesus veio a Betânia, onde estava Lázaro, o qual Ele havia ressuscitado dentre os mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Então, ali fizeram com Ele um jantar, e Marta servia, e Lázaro era um dos que sentaram à mesa com Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Então, Maria pegou uma libra de perfume feito de puro nardo, muito precioso, ungiu os pés de Jesus com isso, e enxugou-Lhe os pés com seus cabelos; a casa encheu-se com a fragrância do perfume.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Judas Iscariotes, um de Seus discípulos, aquele que O havia de trair, disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '\"Por que este perfume não foi vendido por trezentos denários, e dado aos pobres?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Ora, ele disse isso, não por causa do cuidado com os pobres, mas porque era ladrão; ele era encarregado da bolsa do dinheiro, e roubava o que ali se lançava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Jesus disse: \"Deixai-a, ela guardou isto para o dia do meu sepultamento”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Os pobres vós sempre tereis convosco, mas nem sempre tereis a Mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'E uma grande multidão de judeus soube que Jesus estava lá, e veio, não apenas por causa de Jesus, mas também para ver Lázaro, a quem Jesus havia ressuscitado dentre os mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Os principais sacerdotes conspiraram juntos para também levar Lázaro à morte;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'porque foi por causa dele que muitos dos judeus se afastaram e creram em Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'No dia seguinte, uma grande multidão veio para a festa. Quando eles ouviram que Jesus vinha para Jerusalém,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'trouxeram ramos de palmeiras, e saíram ao Seu encontro para saudá-Lo, gritando: \"Hosana! Bendito o que vem em Nome do Senhor, o Rei de Israel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Jesus encontrou um jumentinho, e montou nele, como está escrito:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '\"Não tenhas medo, filha de Sião; eis que teu Rei está vindo, sentado em um jumentinho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Seus discípulos não entenderam essas coisas a princípio, mas, quando Jesus foi glorificado, então se lembraram de que essas coisas estavam escritas sobre Ele, e que assim fizeram a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Então, a multidão que estivera com Jesus quando Ele chamou Lázaro para fora do sepulcro e o ressuscitou dentre os mortos, deu testemunho para outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Foi também por esta razão que a multidão saiu para conhecê-Lo, porque ouviram que Ele havia feito este sinal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Portanto, os fariseus disseram entre si: \"Vede, vós não podeis fazer nada; eis que o mundo tem ido atrás Dele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Entre os que subiram para adorar na festa, estavam alguns gregos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Esses foram para Filipe, que era de Betsaida na Galileia, e perguntaram-lhe dizendo: \"Senhor, nós desejamos ver Jesus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Filipe foi e falou a André; André foi com Filipe, e falaram a Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Jesus lhes respondeu, dizendo: \"Chegou a hora do Filho do homem ser glorificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Em verdade, em verdade, vos digo que, se o grão de trigo que cai na terra não morrer, ele permanece só, mas, se ele morrer, produzirá muito fruto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Quem ama sua vida a perderá; mas quem odeia sua vida neste mundo a conservará para vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Se alguém quiser Me servir, siga-Me, e onde Eu estiver, lá Meu servo também estará. Se alguém Me serve, Meu Pai o honrará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Agora, minha alma está angustiada. E o que direi? \'Pai, salva-Me desta hora’?’ Mas por isso vim, para esta hora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Pai, glorifica o Teu nome\". Então, uma voz saiu do céu, e disse: \"Já O glorifiquei e novamente O glorificarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Quando a multidão, que ali estava, ouviu isso, disse que foi um trovão. Outros disseram: \"Um anjo Lhe falou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jesus respondeu e disse: \"Essa voz não veio por Minha causa, mas por vossa causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Agora é o julgamento deste mundo, e o príncipe deste mundo será expulso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'E quando Eu for levantado da terra, atrairei todos a Mim mesmo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Ele disse isso para referir-Se ao tipo de morte do qual morreria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'A multidão Lhe respondeu: \"Nós temos ouvido da Lei que o Cristo permanece para sempre. Como Tu dizes: \'O Filho do Homem será levantado?\'. Quem é Este Filho do Homem?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Disse-lhes, então, Jesus: \"Ainda por um pouco mais de tempo a Luz estará entre vós. Caminhai enquanto tendes luz, para que as trevas não vos surpreendam. Quem caminha na escuridão não sabe para onde vai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, '\"Enquanto tendes luz, crede na luz, para que vos torneis filhos da luz\". Jesus disse essas coisas e então partiu, e ocultou-Se deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Embora Jesus tivesse feito muitos sinais diante deles, eles ainda não creram Nele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'para que se cumprisse a palavra do profeta Isaías, que diz: \"Senhor, quem creu em nossa pregação? E a quem foi revelado o braço do Senhor?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Por essa razão, eles não podiam crer, pois Isaías também disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '\"Cegou-lhes os olhos, e endureceu-lhes o coração; para que não vejam com os olhos, nem entendam com o coração, e se convertam, e Eu os cure\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Isaías disse isso porque viu a Sua glória, e falou a respeito Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Apesar de tudo, muitos dos líderes acreditaram em Jesus; mas por causa dos fariseus, eles não admitiram isso, para não serem banidos da sinagoga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Eles amavam a glória que vinha das pessoas mais do que a glória que vem de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Jesus clamou e disse: \"Quem crê em Mim, crê não somente em Mim, mas também Naquele que Me enviou,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'e o que Me vê, vê Aquele que Me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Eu vim como luz ao mundo, de modo que todo aquele que crê em Mim não permaneça na escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Se alguém ouve Minhas palavras, mas não as guarda, Eu não o julgo, pois vim, não para julgar o mundo, mas para salvar o mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Quem Me rejeita e não recebe Minhas palavras, já tem quem o julgue: a Palavra que Eu preguei, essa o julgará no último dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Pois Eu não falei por Mim mesmo; ao contrário, o Pai que Me enviou, ordenou-Me o que dizer e o que falar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Eu sei que Seu mandamento é vida eterna; portanto, o que Eu digo é aquilo que o Pai Me mandou dizer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Ora, antes da festa da Páscoa, sabendo Jesus que Sua hora havia chegado para que passasse deste mundo para o Pai, tendo amado os Seus que estavam no mundo, amou-os até o fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'E durante a Ceia, o diabo já havia posto no coração de Judas Iscariotes, filho de Simão, que traísse Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Jesus sabia que o Pai havia dado todas as coisas em Suas mãos, e que Ele viera de Deus, e estava regressando para Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Ele levantou-Se da ceia e tirou o manto. Então, pegou uma toalha e envolveu-a em Sua cintura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Em seguida, Ele derramou água em uma bacia, e começou a lavar os pés dos discípulos, e enxugá-los com a toalha que Ele pusera ao redor da cintura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Ele aproximou-Se de Simão Pedro, que Lhe disse: \"Senhor, Tu lavarás meus pés?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jesus respondeu e disse-lhe: \"O que Eu faço, tu não entendes agora, mas entenderás depois\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Pedro Lhe disse: \"Tu nunca lavarás meus pés\". Jesus respondeu-lhe: \"Se eu não te lavar, tu não terás parte Comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Simão Pedro Lhe disse: \"Senhor, não laves somente os meus pés, mas também minhas mãos e minha cabeça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jesus lhe disse: \"Quem já se banhou, não necessita lavar senão os seus pés, e está inteiramente limpo. Vós estais limpos, mas nem todos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Pois Jesus sabia quem O trairia. Foi por isso que disse: \"Nem todos vós estais limpos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Depois que Jesus lavou os pés deles, tomou o manto, voltou à mesa, e perguntou-lhes: \"Vós entendeis o que vos fiz?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vós me chamais \'Mestre\' e \'Senhor,\' e fazeis bem, porque Eu o sou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Se Eu então, o Senhor e Mestre, lavei os vossos pés, vós também deveis lavar os pés uns dos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Pois Eu vos dei o exemplo, de modo que vós também deveis fazer como fiz convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Em verdade, em verdade, vos digo: o servo não é maior do que seu mestre; nem o enviado é maior do que quem o enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Se sabeis essas coisas, benditos sois se as praticardes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Eu não estou falando sobre todos vós, pois sei aqueles a quem Eu escolhi; mas Eu digo isto para que as Escrituras se cumpram: \'Aquele que comia do Meu pão, levantou contra Mim seu calcanhar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Digo-vos isto agora, antes que aconteça, para que quando acontecer, creiais que Eu Sou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Em verdade, em verdade, vos digo: quem receber Aquele a quem Eu enviar, recebe a Mim; e quem Me receber, recebe Aquele que Me enviou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Havendo dito isso, Jesus perturbou-Se em espírito, e testificou dizendo: \"Em verdade, em verdade, vos digo que um de vós Me trairá\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Os discípulos olharam uns aos outros, imaginando de quem Ele falava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Um dos discípulos, a quem Jesus amava, estava reclinado sobre o peito de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Simão Pedro fez-lhe sinal pedindo: \"Pergunta-Lhe de quem Ele está falando\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Então aquele discípulo, reclinando-se sobre o peito de Jesus, perguntou-Lhe: \"Senhor, quem é?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Então, Jesus respondeu: \"É aquele a quem Eu der o pedaço de pão molhado\". E, tendo molhado o pedaço de pão, deu-o a Judas, filho de Simão Iscariotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'E após comer o pão, Satanás entrou nele. Jesus então disse-lhe: \"O que estás para fazer, faze-o depressa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Ninguém na mesa sabia a razão pela qual Jesus disse isso para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Sendo Judas o encarregado da bolsa do dinheiro, alguns pensavam que Jesus quis dizer-lhe: \"Compra o que nós precisamos para a festa\", ou que ele deveria dar alguma coisa aos pobres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Depois que Judas recebeu o pão, saiu imediatamente; e era noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Quando Judas saiu, Jesus disse: \"Agora o Filho do Homem foi glorificado, e Deus foi glorificado Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Deus O glorificará em Si mesmo, e logo O glorificará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Filhinhos, Eu estou convosco ainda que por pouco tempo. Vós Me procurareis, e como Eu disse aos Judeus: \'Para onde vou, vós não podeis ir.\' Agora Eu digo isto para vós também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Um novo mandamento vos dou, que vós ameis uns aos outros; como Eu vos amei, então vós também deveis amar uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Nisto todos saberão que vós sois Meus discípulos: se vos amardes uns aos outros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simão Pedro Lhe disse: \"Senhor, para onde vais?\". Jesus lhe respondeu: \"Para onde vou não podes seguir-Me agora, mas tu me seguirás depois\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Pedro disse-Lhe: \"Senhor, por que eu não posso Te seguir agora mesmo? Eu entregarei a minha vida por Ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jesus respondeu-lhe: \"Darás a vida por mim? Em verdade, em verdade, te digo que o galo não cantará antes que tu Me negues três vezes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Não se perturbe o vosso coração. Credes em Deus; crede também em Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Na casa de Meu Pai há muitas moradas; se não fosse assim, Eu vos teria dito, pois vou preparar-vos um lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'E, se Eu for e vos preparar lugar, virei outra vez, e vos receberei para Mim mesmo, para que onde Eu estiver, estejais vós também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Vós sabeis o caminho para onde vou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Tomé disse a Jesus: \"Senhor, não sabemos para onde vais. Como podemos saber o caminho?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Jesus lhe disse: \"Eu sou o Caminho, a Verdade, e a Vida; ninguém vem ao Pai senão por Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Se vós tivésseis Me conhecido, teríeis conhecido também a Meu Pai; de agora em diante vós O conheceis e O tendes visto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Filipe disse a Jesus: \"Senhor, mostra-nos o Pai, e isso será suficiente para nós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jesus disse-lhe: \"Estou há tanto tempo convosco, e ainda não Me conheces, Filipe? Quem vê a Mim, vê o Pai; como podes Me dizer: ‘Mostra-nos o Pai’?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Não crês que Eu estou no Pai, e que o Pai está em Mim? As palavras que Eu vos digo, não as digo por Minha própria autoridade; em vez disso, é o Pai que vive em Mim faz as Suas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Crede em Mim, que estou no Pai, e o Pai está em Mim; ou crede ao menos por causa das mesmas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Em verdade, em verdade, vos digo, que aquele que crê em Mim, também fará as obras que Eu faço, e as fará maiores do que Eu faço, porque Eu vou para o Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Tudo quanto pedirdes em Meu nome, Eu o farei, para que o Pai seja glorificado no Filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Se Me pedirdes qualquer coisa em Meu nome, Eu o farei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Se Me amardes, guardareis os Meus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Eu rogarei ao Pai, e Ele vos dará outro Consolador, a fim de que esteja para sempre convosco,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'o Espírito da verdade, O qual o mundo não pode receber, porque não O vê nem O conhece. Vós, no entanto, O conheceis, pois Ele habita convosco, e estará em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Eu não vos deixarei sozinhos; Eu voltarei para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Dentro de pouco de tempo, o mundo não Me verá mais, mas vós Me vereis. Porque Eu vivo, vós também vivereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'Naquele dia, vós sabereis que Eu estou em Meu Pai, e que vós estais em Mim, e Eu em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Aquele que tem os Meus mandamentos e os guarda, esse é o que Me ama; e aquele que Me ama será amado por Meu Pai, e Eu o amarei e Me manifestarei a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Judas (não o Iscariotes) perguntou a Jesus: \"Senhor, por que Te manifestarás a nós, e não ao mundo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jesus lhe respondeu: \"Se alguém Me ama, guardará a Minha palavra. Meu Pai o amará, e viremos a ele e faremos nele morada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Quem não Me ama, não guarda as Minhas palavras. A palavra que ouvis não é Minha, mas do Pai que Me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Essas coisas vos tenho dito enquanto ainda estou convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Contudo o Consolador, o Espírito Santo, a Quem o Pai enviará em Meu nome, Ele vos ensinará todas as coisas e vos lembrará de tudo o que Eu vos falei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Deixo-vos a paz, a Minha paz vos dou. Eu não a dou como o mundo a dá. Não se perturbe vosso coração, nem tenha medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Ouvistes o que Eu vos disse: \'Irei e voltarei para vós\'. Se Me amásseis ficaríeis alegres, porque Eu vou para o Pai; pois o Pai é maior do que Eu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Eu vos digo isso agora, antes que aconteça, para que, quando acontecer, creiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Já não falarei convosco, pois o príncipe deste mundo está chegando, e ele não tem poder sobre Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Mas, para que o mundo saiba que Eu amo o Pai, faço aquilo que o Pai Me mandou. Levantai-vos, vamos deixar este lugar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '\"Eu sou a videira verdadeira, e meu Pai é o agricultor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Todo o ramo que está em Mim e não produz fruto, Ele o corta; e todo ramo que produz fruto, Ele o limpa, para que produza mais fruto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Já estais limpos pela palavra que Eu vos tenho falado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Permanecei em Mim, e Eu em vós. Como o ramo não pode dar fruto por si mesmo se não permanecer na videira, assim também não podeis vós, se não permanecerdes em Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Eu sou a videira, vós, os ramos. Aquele que permanece em Mim e Eu nele, esse dá muito fruto, pois sem Mim nada podeis fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Se alguém não permanecer em Mim, é lançado fora como um ramo, e seca; e esses ramos são recolhidos, jogados ao fogo e queimados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Se permanecerdes em Mim, e Minhas palavras permanecerem em vós, pedireis o que quiserdes, e vos será concedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Meu Pai é glorificado nisto: em que deis muito fruto; e assim provais ser Meus discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Como o Pai Me amou, assim Eu também vos amei. Permanecei no Meu amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Se guardardes os Meus mandamentos, permanecereis no Meu amor; do mesmo modo que Eu tenho permanecido nos mandamentos de Meu Pai e no Seu amor permaneço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Eu vos tenho dito essas coisas para que a Minha alegria esteja em vós, e a vossa alegria seja plena.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Este é Meu mandamento: que vos ameis uns aos outros como Eu vos amei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Ninguém tem maior amor do que aquele que dá a sua vida pelos seus amigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Vós sois Meus amigos se fizerdes o que Eu vos ordeno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Já não vos chamo de servos, porque o servo não sabe o que o Seu Senhor faz. Eu vos tenho chamado de amigos, pois vos revelei tudo quanto ouvi de Meu Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Não fostes vós que Me escolhestes; mas Eu vos escolhi e vos designei para que vades e deis fruto, e que o vosso fruto permaneça, a fim de que o Pai vos conceda tudo quanto pedirdes em Meu Nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Isto vos ordeno: amai-vos uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Se o mundo vos odeia, sabei que, antes de vós, ele odiou a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Se fôsseis do mundo, o mundo vos amaria como se pertencêsseis a ele; mas, porque vós não sois do mundo, e Eu escolhi tirar-vos do mundo, por esta razão o mundo vos odeia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Lembrai-vos da Palavra que Eu vos disse: \'O servo não é maior que o Seu Senhor\'. Se perseguiram a Mim, também perseguirão a vós; se obedeceram à Minha Palavra, obedecerão também à vossa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Eles farão todas essas coisas por causa do Meu Nome, pois não conhecem Aquele que Me enviou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Se Eu não tivesse vindo e não tivesse lhes falado, não teriam pecado; mas agora não têm desculpa para os pecados deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Aquele que Me odeia, também odeia a Meu Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Se Eu não tivesse feito entre eles essas obras que nenhum outro fez, não teriam pecado. Mas agora viram e odiaram tanto a Mim como a Meu Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Isso acontece para que a palavra que está escrita na Lei deles se cumprisse: \'Odiaram a Mim sem motivo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Quando vier o Consolador, que Eu vos enviarei da parte do Pai, o Espírito da Verdade, que procede do Pai, Esse dará testemunho de Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'E vós também testemunhareis, porque tendes estado Comigo desde o princípio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Eu vos disse essas coisas para não tropeçardes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Eles vos expulsarão das sinagogas. De fato, está chegando a hora em que todo aquele que vos matar pensará que oferece um culto a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Eles farão isso porque não conhecem nem o Pai, nem a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Eu vos disse essas coisas para que, quando a hora chegar, vos lembreis de como Eu vos falei a respeito delas. Eu não vos disse isso no princípio porque Eu estava convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Contudo, agora Eu vou para Aquele que Me enviou; e ainda nenhum de vós Me perguntais: \'Para onde vais?\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Mas porque Eu vos disse essas coisas, a tristeza encheu o vosso coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Contudo, Eu vos digo a verdade: é melhor para vós que Eu vá; pois se Eu não for, o Consolador não virá a vós; mas se Eu for, O enviarei a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Quando o Consolador vier, convencerá o mundo a respeito do pecado, da justiça e do juízo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Do pecado, porque eles não creram em Mim;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'da justiça, porque Eu vou para o Pai, e vós não Me vereis mais;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'e do juízo, porque o príncipe deste mundo já está julgado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Ainda tenho muitas coisas para vos dizer; mas não as entenderíeis agora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Contudo, quando Ele, o Espírito da Verdade, vier, Ele vos guiará em toda a verdade; pois não falará de Si mesmo; mas Ele dirá tudo o que ouvir, e vos anunciará as coisas que estão por vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Ele Me glorificará, porque receberá do que é Meu, e vos anunciará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Tudo quanto o Pai tem é Meu; por isso, Eu disse que o Espírito receberá do que é Meu, e vos anunciará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Dentro de um pouco de tempo, vós não Me vereis; e depois de um pouco mais de tempo, de novo Me vereis”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Então, alguns dos Seus discípulos disseram uns aos outros: \"O que é isto que Ele nos diz: \'Um pouco de tempo e vós não Me vereis\', e ainda, \'Um pouco mais de tempo, e de novo Me vereis,\' e, \'Porque Eu vou para o Pai\'?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Por isso, disseram: \"O que é isto que Ele diz: \'Um pouco de tempo\'? Nós não sabemos do que Ele está falando\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jesus viu que queriam interrogá-Lo, e lhes disse: \"Perguntais entre vós a respeito disso que Eu vos disse: \'Dentro de um pouco de tempo, vós não Me vereis; e depois um pouco de mais de tempo, de novo Me vereis\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Em verdade, em verdade, vos digo, vós chorareis e lamentareis, mas o mundo se alegrará; vós ficareis tristes, mas a vossa tristeza se transformará em alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Uma mulher fica triste quando tem dores de parto porque seu tempo de dar à luz chegou; mas depois que ela deu à luz, não se lembra mais das suas dores, por causa da alegria de ter nascido um bebê no mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Assim, também vós tendes tristeza agora, mas Eu vos verei novamente; e o vosso coração se alegrará, e ninguém poderá tirar vossa alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Naquele dia, vós não Me perguntareis nada. Em verdade, em verdade, vos digo, se pedirdes qualquer coisa ao Pai em Meu nome, Ele vos dará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Até agora não Me pedistes nada em Meu nome; pedi e recebereis, para que a vossa alegria seja completa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Eu vos disse essas coisas por meio de comparações; mas está chegando a hora em que não falarei mais por comparações, mas claramente anunciarei sobre o Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Naquele dia, vós pedireis em Meu nome, e Eu não vos digo que rogarei ao Pai por vós;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'pois o próprio Pai vos ama, porque tendes Me amado e crido que Eu vim do Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Eu vim do Pai para o mundo; novamente, Eu deixo o mundo e vou para o Pai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Seus discípulos disseram: \"Eis que agora falas claramente; e não usas comparações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Agora sabemos que Tu conheces todas as coisas, e que não precisas que ninguém Te faça perguntas. Por causa disso, cremos que vieste de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jesus lhes respondeu: \"Agora, credes?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Eis que vem a hora, e de fato já chegou, em que vós sereis espalhados cada um para vossas próprias casas, e Me deixareis sozinho. Mas não estou sozinho, porque o Pai está comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Eu vos disse essas coisas para que tenhais paz em Mim. No mundo tereis aflições, mas tende coragem; Eu venci o mundo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Depois de dizer essas coisas, Jesus levantou os olhos aos céus e disse: \"Pai, chegou a hora. Glorifica Teu Filho para que o Filho Te glorifique,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'assim como Tu Lhe deste autoridade sobre toda carne, para que também Ele dê vida eterna a todos quanto Lhe deste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'A vida eterna é esta: que eles conheçam a Ti, o único Deus verdadeiro, e a Jesus Cristo, Aquele que Tu enviaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Eu Te glorifiquei na terra, completando a obra que Me deste para fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Agora, Pai, glorifica-Me junto a Ti com a glória que Eu tinha Contigo antes do mundo ser criado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Manifestei o Teu Nome aos homens que do mundo Me deste. Eles eram Teus; e Tu os deste a Mim, e eles guardaram a Tua Palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Agora, sabem que todas as coisas que me deste vêm de Ti;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'porque as palavras que Tu me deste, Eu lhes dei. Eles as receberam e verdadeiramente souberam que vim de Ti, e creram que Tu Me enviaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Eu oro por eles; não oro pelo mundo, mas por aqueles que Tu Me deste, pois eles são Teus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'Tudo que é Meu é Teu, e tudo que é Teu é Meu; e sou glorificado neles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Eu não estou mais no mundo, mas eles estão no mundo, e Eu vou para Ti. Pai Santo, guarda-os no Teu Nome que Tu Me deste, para que eles sejam um, assim como Nós somos Um.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Enquanto Eu estava com eles, Eu os guardei em Teu Nome que Me deste; Eu os guardei e nenhum deles se perdeu, exceto o filho da perdição, para que as Escrituras se cumprissem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Agora, vou para Ti; mas digo essas coisas no mundo, para que tenham minha alegria completa neles mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Eu lhes dei a Minha Palavra; e o mundo os odiou porque eles não são do mundo, assim como Eu não sou do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Eu não oro para que os tires do mundo, mas para que os guardes do maligno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Eles não são do mundo, assim como Eu não sou do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Santifica-os na verdade; a Tua Palavra é a Verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Assim como Tu Me enviaste ao mundo, também Eu os enviei ao mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Por causa deles, Eu Me santifico, para que eles mesmos também sejam santificados na Verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Oro não somente por esses, mas também por aqueles que crerão em Mim por meio da palavra deles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'para que eles sejam um, assim como Tu, Pai, estás em Mim, e Eu em Ti. Eu oro para que eles estejam em Nós, a fim de que o mundo creia que Tu Me enviaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'A glória que Tu Me deste, Eu lhes dei, para que eles sejam um, assim como Nós somos Um;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Eu neles, e Tu em Mim, para que eles sejam conduzidos à completa unidade; a fim de que o mundo saiba que Tu Me enviaste, e os amaste, assim como amaste a Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Pai, quero que aqueles que Tu Me deste estejam também Comigo onde Eu estiver para que eles vejam a Minha glória, aquela que Tu Me deste, pois Tu Me amaste desde antes da fundação do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Pai justo, o mundo não Te conheceu, mas Eu Te conheço; e estes sabem que Tu Me enviaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Eu fiz Teu Nome conhecido a eles, e Eu o farei conhecido para que o amor com que Tu Me amaste esteja neles, e Eu neles esteja\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Após Jesus ter dito essas palavras, foi com Seus discípulos para o outro lado do ribeiro de Cedrom, onde havia um jardim em que Ele entrou com Seus discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'E Judas, o que iria traí-Lo, também conhecia o lugar, pois Jesus sempre ia lá com os Seus discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Judas trouxe consigo um destacamento de soldados, e alguns oficiais dos principais sacerdotes e os fariseus; e chegaram lá com lanternas, tochas e armas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Então Jesus, sabendo todas as coisas que iriam acontecer Consigo, adiantou-Se e lhes perguntou: \"A quem procurais?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Eles Lhe responderam: \"Jesus, o Nazareno\". Jesus lhes disse: \"Sou Eu\". Judas, o traidor, estava também em pé com os soldados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Então, quando Ele lhes disse: \"Sou Eu\", eles recuaram e caíram por terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Novamente, perguntou-lhes: \"A quem procurais?\". Outra vez, disseram: \"Jesus, o Nazareno\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jesus respondeu: \"Eu vos disse que Eu Sou; então, se vós Me procurais, deixai estes outros irem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Para que se cumprisse a Palavra que dissera: \"Não perdi nenhum dos que Me deste\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'E Simão Pedro, que tinha uma espada, desembainhou-a e golpeou o servo do sumo sacerdote cortando-lhe a orelha direita. O nome do servo era Malco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Então, Jesus disse a Pedro: \"Põe a espada de volta na bainha. Por acaso, não beberei do cálice que o Pai Me deu\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Então, o destacamento de soldados, o capitão e os oficiais dos judeus agarraram Jesus, e O amarraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'Eles O levaram primeiro a Anás, pois ele era sogro de Caifás, sumo sacerdote naquele ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Era Caifás o que havia aconselhado aos judeus que era propício que um homem deveria morrer pelo povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Simão Pedro seguiu a Jesus, e assim também o outro discípulo. Aquele discípulo era conhecido do sumo sacerdote, e entrou com Jesus no pátio do sumo sacerdote;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Mas Pedro ficou em pé do lado de fora da porta. Então, o outro discípulo, que era conhecido do sumo sacerdote, saiu e falou com a serva que estava guardando a porta, e levou Pedro para dentro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'A serva que guardava a porta disse a Pedro: \"Tu também não és um dos discípulos deste Homem?\". Ele disse: \"Não sou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Os servos e os oficiais estavam ali; eles haviam feito uma fogueira, pois estava frio, e estavam aquecendo-se. Pedro também estava em pé ali, aquecendo-se com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Então, o sumo sacerdote perguntou a Jesus sobre Seus discípulos e Seus ensinos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jesus lhe respondeu: \"Eu tenho falado abertamente ao mundo; Eu estava sempre ensinando nas sinagogas e no templo onde os judeus se reúnem. Nada falei em segredo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Por que me interrogas? Pergunta àqueles que ouviram o que Eu disse. Essas pessoas sabem o que Eu disse\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Quando Jesus disse isso, um dos oficiais que estava lá deu uma bofetada em Jesus, e disse: \"É desta maneira que Tu respondes ao sumo sacerdote?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jesus lhe respondeu: \"Se Eu falei mal, dá testemunho do mal. Porém, se falei bem, por que me bates?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Então, Anás O enviou amarrado para Caifás, o sumo sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Simão Pedro estava em pé aquecendo-se, e perguntaram-lhe: \"Tu não és também um dos Seus discípulos?\". Ele negou e disse: \"Não sou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Um dos servos do sumo sacerdote, que era parente do homem que Pedro havia cortado a orelha, disse: \"Eu não te vi no jardim com Ele?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Pedro negou outra vez, e imediatamente o galo cantou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Depois, levaram Jesus da presença de Caifás para o palácio do governador. Era de manhã, e não entraram no palácio para não serem contaminados, e poderem comer a Páscoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Então, Pilatos saiu para recebê-los, e lhes disse: \"Que acusação trazeis vós contra este Homem?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Eles responderam: \"Se este Homem não fosse malfeitor, não O entregaríamos a Ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Portanto, Pilatos disse-lhes: \"Levai-O vós mesmos, e julgai-O segundo a vossa lei\". Disseram-lhe os judeus: \"Não nos é permitido levar nenhum homem à morte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Isto disseram para que se cumprisse a Palavra que Jesus havia dito, indicando o modo pelo qual morreria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Então, Pilatos entrou no palácio novamente, chamou Jesus e Lhe disse: \"Tu és o Rei dos judeus?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jesus respondeu: \"Tu dizes isso por ti mesmo, ou outros te disseram a Meu respeito?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilatos respondeu: \"Por acaso eu sou judeu? Teu próprio povo e os principais dos sacerdotes Te entregaram a mim. O que fizeste?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jesus respondeu: \"Meu reino não é deste mundo. Se o Meu reino fosse deste mundo, meus servos lutariam para que Eu não fosse entregue aos judeus. Mas o Meu reino não é daqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Pilatos Lhe disse: \"Então, Tu és um rei?\". Jesus respondeu: \"Tu dizes que sou rei. Para isto nasci e vim ao mundo, a fim de dar testemunho da verdade. Todo aquele que é da verdade ouve a Minha voz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilatos Lhe disse: \"O que é a verdade?\". Tendo dito isto, saiu novamente aos judeus, e disse-lhes: \"Não encontrei crime algum neste homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Mas vós tendes o costume de que eu liberte para vós um homem na Páscoa. Então, quereis vós que eu liberte o Rei dos judeus?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Então eles gritaram, dizendo: \"Não esse homem, mas Barrabás\". Barrabás era um criminoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Então, Pilatos tomou Jesus e mandou chicoteá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Os soldados teceram uma coroa de espinhos, colocaram-na sobre Sua cabeça e O vestiram em um manto púrpura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'Vieram a Ele e disseram: \"Saudações, Rei dos judeus!\". E O esmurraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Pilatos, então, saiu novamente e disse ao povo: \"Vede, eu O estou trazendo para que saibais que não encontrei nenhuma culpa Nele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Jesus saiu e estava vestindo um manto púrpura e a coroa. Pilatos lhes disse: \"Vede, aqui está o Homem!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'E quando os principais sacerdotes e os oficiais viram Jesus, gritaram dizendo: \"Crucifica-O, crucifica-O!\". Pilatos lhes disse: \"Levai-O vós mesmos, e crucificai-O. Eu, porém, não encontrei culpa Nele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Os judeus responderam a Pilatos: \"Nós temos uma lei, e pela Lei Ele deve morrer, porque Ele fez de Si mesmo Filho de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Quando Pilatos ouviu essa afirmação, ele ficou ainda mais amedrontado;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'e entrou no palácio novamente, e disse a Jesus: \"De onde Tu vens?\". Entretanto, Jesus não deu nenhuma resposta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Pilatos então Lhe disse: \"Tu não me respondes? Não sabes que tenho poder para libertar-Te e poder para crucificar-Te?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jesus respondeu: \"Tu não terias nenhum poder contra Mim, se não te fosse dado do alto. Por isso, quem Me entregou a ti tem pecado maior\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Por causa disso, Pilatos tentou libertá-Lo, mas os judeus gritaram dizendo: \"Se tu libertares este homem, não és amigo de César. Todo aquele que se fizer rei fala contra César\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Quando Pilatos ouviu essas palavras, trouxe Jesus para fora, e sentou-se na cadeira de julgamento, em um lugar chamado Pavimento de Pedra, e em hebraico, Gabatá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Ora, era o dia da preparação da Páscoa, por volta da hora sexta. Pilatos disse aos judeus: \"Vede, aqui está vosso Rei!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Eles gritaram: \"Fora, fora; crucifica-O!\". Pilatos lhes disse: \"Devo crucificar vosso Rei?\". Os principais sacerdotes responderam: \"Não temos Rei, senão César\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Então, Pilatos lhes entregou Jesus para ser crucificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Levaram Jesus para fora, e Ele saiu carregando a cruz para o lugar chamado Caveira, o qual em hebraico é chamado Gólgota.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Lá O crucificaram e, com Ele, outros dois homens, um de cada lado, e Jesus no meio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Pilatos escreveu um letreiro, colocou-o na cruz, e estava escrito: \"JESUS DE NAZARÉ, REI DOS JUDEUS\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Muitos judeus leram essa inscrição, porque o lugar que Jesus foi crucificado era perto da cidade; e a inscrição estava em hebraico, latim e grego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Então, os principais sacerdotes dos judeus disseram a Pilatos: \"Não escreva: \'O Rei dos Judeus’, mas: ‘Este homem disse: \"Eu sou Rei dos Judeus\"’\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilatos respondeu: \"O que escrevi, escrevi\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Quando os soldados crucificaram Jesus, tiraram Suas vestes e as dividiram em quatro partes, uma para cada soldado; e também a túnica que não tinha costura, tecida por inteiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Então, disseram um ao outro: \"Não vamos rasgá-la; mas lançaremos sortes para decidir de quem será\". Isso aconteceu para que as Escrituras se cumprissem: \"Eles dividiram Minhas roupas entre si, e por Minhas roupas lançaram sortes\". Os soldados fizeram essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'E, ao lado da Cruz de Jesus, estavam, de pé, a Sua mãe, a irmã de Sua mãe, Maria, a esposa de Clopas, e Maria Madalena.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Quando Jesus viu Sua mãe e, próximo a ela, o discípulo que Ele amava, disse a Sua mãe: \"Mulher, eis aí teu filho!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Então, disse ao discípulo: \"Eis aí tua mãe!\". Daquela hora em diante, o discípulo levou-a para sua própria casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Depois disso, Jesus, sabendo que todas as coisas estavam consumadas, a fim de que se cumprissem as Escrituras, disse: \"Estou com sede\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Havia ali uma vasilha cheia de vinagre; então puseram uma esponja ensopada de vinagre em uma vara de hissopo, e a ergueram até Sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Quando Jesus tomou o vinagre, disse: \"Está consumado\". Ele inclinou a cabeça e entregou Seu espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Por ser o dia da preparação, para que os corpos não permanecessem nas cruzes durante o sábado (pois, este sábado era um dia importante), os judeus pediram a Pilatos que as pernas dos homens executados fossem quebradas, e que seus corpos fossem retirados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Então, os soldados vieram e quebraram as pernas do primeiro e do segundo homem que haviam sido crucificados com Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Quando se aproximaram de Jesus, viram que já estava morto; por isso não quebraram Suas pernas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Todavia, um dos soldados perfurou o Seu lado com uma lança, e imediatamente saiu sangue e água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Aquele que viu isto dá testemunho, e seu testemunho é verdadeiro. Ele sabe que diz a verdade, para que também creiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Essas coisas aconteceram para que se cumprissem as Escrituras: \"Nenhum de Seus ossos será quebrado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'E outra parte da Escritura diz: \"Olharão para Aquele a Quem traspassaram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Depois dessas coisas, José de Arimateia, que era discípulo de Jesus, embora secretamente, por medo dos Judeus, pediu a Pilatos que lhe permitisse levar o corpo de Jesus. Pilatos deu-lhe permissão. Então, José veio e levou embora o corpo Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Também veio Nicodemos, aquele que havia-se encontrado com Jesus à noite. Ele trouxe uma mistura de mirra e aloés, cerca de cem libras em peso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Então, levaram o corpo de Jesus, e o envolveram em roupas de linho com os aromas, como era costume dos judeus para enterrar os corpos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'No lugar onde foi crucificado havia um jardim; e no jardim havia uma tumba nova na qual nenhuma pessoa havia sido sepultada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Porque era o dia da preparação para os judeus, e porque a tumba estava perto, puseram Jesus nela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'No primeiro dia da semana, enquanto ainda era escuro, Maria Madalena foi ao sepulcro e viu que a pedra havia sido removida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Então, ela correu ao encontro de Simão Pedro e do outro discípulo, a quem Jesus amava, e disse-lhes: \"Retiraram o Senhor do sepulcro, e nós não sabemos onde O puseram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Então Pedro e o outro discípulo saíram e foram ao sepulcro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Os dois corriam juntos; e o outro discípulo correu mais do que Pedro, e chegou ao sepulcro primeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Abaixando-se, viu as roupas de linho deixadas lá, mas não entrou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Então, chegou Simão Pedro depois dele, e foi para dentro do sepulcro, e viu os lençóis de linho deixados ali,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'e o lenço que estava em Sua cabeça, o qual não foi deixado com os lençóis de linho, mas enrolado em um lugar à parte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Então, o outro discípulo, o que chegou primeiro, também entrou no sepulcro; ele viu e creu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Pois, até aquele momento, eles não compreendiam o que a Escritura dizia, que Jesus devia ressuscitar dentre os mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Então, os discípulos voltaram novamente para casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Contudo, Maria permaneceu fora do sepulcro chorando. Enquanto chorava, parou e olhou dentro do sepulcro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'e viu dois anjos de branco sentados, onde o corpo de Jesus repousara, um à cabeça e outro aos pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Eles lhe falaram: \"Mulher, por que choras?\". Ela lhes respondeu: \"Porque levaram meu Senhor, e eu não sei onde O puseram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Quando ela falou isso, olhou em volta e viu Jesus parado ali; mas ela não sabia que Ele era Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Jesus lhe disse: \"Mulher, por que choras? A quem procuras?\". Ela pensou que Ele era o jardineiro, então ela Lhe falou: \"Senhor, se Tu O tiraste daqui, fala-me onde O colocaste, e eu O levarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Jesus lhe disse: \"Maria!\". Ela, virando-se, disse para Ele em aramaico: \"Raboni!\" (que quer dizer: \"Mestre\").');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Jesus lhe disse: \"Não me segures, porque eu ainda não subi para o Pai. Mas vá para meus irmãos, e diga-lhes que Eu subirei para Meu Pai e vosso Pai, e Meu Deus e vosso Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Maria Madalena foi, e disse aos discípulos: \"Vi o Senhor!\", e contou as coisas que Ele lhe dissera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Sendo, pois, tarde, naquele primeiro dia da semana, estando os discípulos reunidos com as portas trancadas, por medo dos judeus, Jesus veio e colocou-Se no meio deles, e disse-lhes: \"Paz seja convosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Depois de dizer isso, mostrou-lhes as mãos e o lado. E quando os discípulos viram o Senhor, alegraram-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Em seguida, Jesus lhes disse outra vez: \"Paz seja convosco. Como o Pai Me enviou, Eu também vos envio\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Quando Jesus disse isso, soprou neles e disse-lhes: \"Recebei o Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Se perdoardes os pecados de alguém, serão perdoados; se os retiverdes, serão retidos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Tomé, um dos doze, chamado Dídimo, não estava com eles quando Jesus veio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Os outros discípulos depois disseram-lhe: \"Vimos o Senhor\". Ele lhes disse: \"Se eu não vir em Suas mãos as marcas dos pregos, e colocar meu dedo dentro das marcas dos pregos, e minha mão no Seu lado, eu não crerei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Oito dias depois, os discípulos estavam outra vez ali reunidos, e Tomé estava com eles. Estando as portas trancadas, Jesus colocou-Se no meio deles, e disse-lhes: \"Paz seja convosco\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Então, Ele disse para Tomé: \"Põe aqui os teus dedos, e vê as Minhas mãos; estende aqui a tua mão, e a coloca no Meu lado; não sejas incrédulo, mas crê\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Tomé respondeu e disse-Lhe: \"Meu Senhor e meu Deus!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Jesus disse-lhe: \"Porque Me viste, tu creste? Benditos são aqueles que não viram e creram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Na verdade, Jesus realizou, na presença de Seus discípulos, muitos outros sinais, os quais não foram escritos neste livro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Estes, porém, foram escritos para que creiais que Jesus é o Cristo, o Filho de Deus, e para que, crendo, tenhais vida em Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Depois dessas coisas, Jesus apareceu novamente aos discípulos no mar de Tiberíades. Assim foi que Ele apareceu:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Simão Pedro estava junto com Tomé, chamado Dídimo, Natanael de Caná da Galileia, os filhos de Zebedeu, e outros dois discípulos de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Simão Pedro lhes disse: \"Vou pescar\". E lhe disseram: \"Nós também iremos contigo\". Eles foram e entraram no barco; mas naquela noite nada apanharam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Ao amanhecer, Jesus estava na praia, mas os discípulos não sabiam que era Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Então, Jesus lhes disse: \"Jovens, tendes algo para comer?\". Eles Lhe responderam: \"Não\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'E disse-lhes: \"Lançai vossa rede do lado direito do barco, e achareis\". E eles lançaram a rede, quase não conseguiam puxá-la por causa da quantidade de peixes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Então, o discípulo que Jesus amava disse a Pedro: \"É o Senhor!\". Quando Simão Pedro ouviu que era o Senhor, vestiu sua roupa, pois estava nu, e lançou-se ao mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'E os outros discípulos vieram no barco (pois não estavam longe da terra, nem duzentos côvados de distância), puxando a rede cheia de peixes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Quando desembarcaram, viram ali pão e peixe sobre brasas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Disse-lhes Jesus: \"Trazei alguns dos peixes que acabastes de pegar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simão Pedro subiu ao barco e puxou a rede, cheia de cento e cinquenta e três grandes peixes; apesar de serem muitos, a rede não se rompeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Disse-lhes Jesus: \"Vinde e comei\". Nenhum dos discípulos ousou perguntar-Lhe: \"Quem és Tu?\", sabendo que Ele era o Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Jesus aproximou-Se, pegou o pão e lhes deu; e fez da mesma maneira com o peixe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Esta foi a terceira vez que Jesus apareceu aos discípulos depois de ter ressuscitado dos mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Depois de terem comido, Jesus disse a Simão Pedro: \"Simão, filho de João, tu Me amas mais que estes?\". Pedro respondeu-Lhe: \"Sim, Senhor; Tu sabes que eu Te amo\". Jesus disse-lhe: \"Apascenta Meus cordeiros\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Tornou a perguntar-lhe pela segunda vez: \"Simão, filho de João, tu Me amas?\". Pedro respondeu-Lhe: \"Sim, Senhor; Tu sabes que eu Te amo\". Jesus disse para ele: \"Pastoreia Minhas ovelhas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Ele lhe disse uma terceira vez: \"Simão, filho de João, tu Me amas?\". Pedro entristeceu-se porque Jesus lhe havia perguntado pela terceira vez: \"Tu Me amas?\". Ele disse-Lhe: \"Senhor, Tu sabes todas as coisas; Tu sabes que Te amo\". Jesus disse-lhe: \"Alimenta Minhas ovelhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Em verdade, em verdade, te digo que quando eras jovem, tu te vestias e andavas como desejavas; mas quando envelheceres, estenderás tuas mãos e outro te vestirá, e te levará onde tu não desejas ir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Jesus disse isso para indicar com que tipo de morte Pedro glorificaria a Deus. Depois de falar isso, Ele disse a Pedro: \"Segue-Me\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Pedro virou-se e viu o discípulo a quem Jesus amava acompanhando-lhes, aquele que também havia-se reclinado sobre o peito de Jesus na ceia e perguntado: \"Senhor, quem é aquele que Te trairá?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Pedro, ao vê-lo, disse a Jesus: \"Senhor, e quanto a este?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Jesus lhe respondeu: \"Se Eu quiser que ele permaneça até Eu voltar, que te importa? Quanto a ti, Segue-Me\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Então, espalhou-se esta notícia entre os irmãos, de que aquele discípulo não morreria. Todavia, Jesus não disse a Pedro que o outro discípulo não morreria, mas afirmou: \"Se Eu quiser que ele permaneça até Eu voltar, que te importa?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Este é o discípulo que dá testemunho sobre essas coisas, e que as escreveu, e nós sabemos que seu testemunho é verdadeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Existem também muitas outras coisas que Jesus fez. Se cada uma delas fosse escrita, suponho que nem mesmo o mundo poderia conter os livros que seriam escritos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Eu escrevi o primeiro livro, Teófilo, contando tudo o que Jesus começou a fazer e a ensinar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'até o dia em que foi elevado aos céus. Isso aconteceu depois que Ele deu ordens, por meio do Espírito Santo, aos apóstolos que Ele escolheu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Após ter sofrido, Ele apresentou a Si mesmo vivo para eles, com muitas provas incontestáveis. Por quarenta dias, Ele apareceu a eles, e falou-lhes acerca do Reino de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Quando Ele estava reunido com eles, ordenou-lhes que não deixassem Jerusalém, mas que esperassem pela promessa do Pai, a qual, Ele disse: \"Vós ouvistes de Mim');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'que João batizou com água, todavia, dentro de poucos dias, vós sereis batizados com o Espírito Santo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Quando eles estavam reunidos lhe perguntaram: \"Senhor, é este o tempo em que restaurarás o Reino a Israel?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Ele lhes disse: \"Não vos compete saber tempos ou épocas as quais o Pai determinou por Sua própria autoridade;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'mas recebereis poder, ao descer sobre vós o Espírito Santo, e sereis minhas testemunhas, tanto em Jerusalém, como em toda a Judéia e Samaria, e até aos confins da terra.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Depois de dizer essas coisas, o Senhor Jesus foi levado às alturas enquanto eles olhavam, e uma nuvem O escondeu de seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Eles ainda estavam olhando para o céu, enquanto Jesus subia, e de repente, dois homens vestidos de branco apareceram ao lado deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Eles disseram: \"Homens galileus, por que estais aqui olhando para o céu? Este Jesus que dentre vós foi elevado aos céus, voltará da mesma maneira como o vistes subir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Então eles voltaram para Jerusalém do Monte das Oliveiras que fica perto de Jerusalém, à distância da caminhada de um sábado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Quando eles chegaram, foram para o quarto no andar superior, onde estavam hospedados. Eram eles Pedro; João; Tiago; André; Filipe; Tomé; Bartolomeu; Mateus; Tiago, filho de Alfeu; Simão, o Zelote; e Judas, filho de Tiago.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Todos estes perseveravam unânimes em oração, juntamente com as mulheres, com Maria, a mãe de Jesus, e com os irmãos Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Naqueles dias, Pedro se pôs em pé no meio dos irmãos, cerca de cento e vinte pessoas, e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '\"Irmãos, era necessário que se cumprisse a Escritura, aquilo que o Espírito Santo falou anteriormente pela boca de Davi, a respeito de Judas, que foi o guia dos que prenderam Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Pois ele foi um de nós e teve parte neste ministério.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, '(Este homem comprou um campo com o lucro da sua impiedade, então, precipitou-se de cabeça, seu corpo se partiu ao meio e seus órgãos foram derramados para fora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Isso se tornou conhecido por todos aqueles que habitam em Jerusalém, tanto que o campo foi chamado na própria língua deles \"Aceldama\", que significa \"Campo de Sangue\".)');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, '\"Pois está escrito no livro dos Salmos: \'Deixe seu campo ficar abandonado e não permita que pessoa alguma viva ali\' e \'Deixe que outro ocupe sua posição de liderança\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'É necessário, portanto que, dentre os homens que tenham nos acompanhado durante todo o tempo em que o Senhor Jesus esteve entre nós,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'começando pelo batismo de João até o dia em que Ele foi elevado às alturas, um destes se torne conosco testemunha da Sua ressurreição\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Eles sugeriram dois: José, chamado Barsabás, por sobrenome Justo, e Matias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Eles, orando, disseram: \"Tu, Senhor, conheces o coração de todas as pessoas, então, revela-nos qual destes dois é aquele que Tu tens escolhido');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'para ocupar o lugar neste ministério e apostolado, do qual Judas se desviou para ir para seu próprio lugar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'E lançaram sortes entre eles; e a sorte caiu sobre Matias e ele foi contado entre os onze apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Quando o dia de Pentecostes chegou, estavam todos reunidos no mesmo lugar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'de repente, veio do céu um som como de um vento impetuoso e encheu toda a casa onde estavam assentados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'E apareceram línguas como de fogo que foram distribuídas entre eles; e elas pousaram sobre cada um deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Todos ficaram cheios do Espírito Santo e começaram a falar em outras línguas, conforme o Espírito lhes concedia que falassem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Estavam morando em Jerusalém judeus piedosos de todas as nações debaixo dos céus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'quando esse som foi ouvido, a multidão se ajuntou e ficou confusa, porque cada um os ouvia falar na sua própria língua.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Eles estavam espantados, admiravam-se dizendo: \"Na verdade, não são Galileus todos estes que estão falando?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Como é que os ouvimos falar cada um em nossa própria língua materna?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Somos partos, medos e elamitas, e aqueles que vivem na Mesopotâmia, na Judeia e na Capadócia, no Ponto e na Ásia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'na Frígia e na Panfília, no Egito e em partes da Líbia perto de Cirene, e visitantes de Roma,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'judeus e prosélitos, cretenses e árabes, todos nós os ouvimos falar em nossas línguas das poderosas obras de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Todos eles estavam espantados e perplexos, e diziam uns aos outros: \"O que isso quer dizer?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Mas outros zombavam dizendo: \"Eles estão cheios de vinho novo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Mas Pedro levantou-se com os onze, ergueu sua voz, e disse-lhes: \"Homens da Judeia e todos os que habitam em Jerusalém, seja isto conhecido a vós e escutai as minhas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Estes homens não estão bêbados, como pensais, pois é apenas a terceira hora do dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Mas isto é o que foi dito pelo profeta Joel:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '\'Nos últimos dias,\' diz Deus: \'Derramarei do meu Espírito sobre toda a carne: vossos filhos e vosas filhas profetizarão, vossos jovens terão visões e vossos velhos sonharão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'E também sobre os meus servos e sobre as minhas servas derramarei do Meu Espírito, e eles profetizarão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Mostrarei maravilhas em cima no céu, e sinais embaixo na terra: sangue, fogo e vapor de fumaça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'O sol se transformará em trevas e a lua em sangue antes que venha o grande e glorioso dia do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'E acontecerá que todo aquele que invocar o nome do Senhor será salvo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Homens de Israel, escutai estas palavras: Jesus de Nazaré, homem aprovado por Deus diante de vós com milagres, prodígios e sinais que Deus fez por meio Dele entre vós, como sabeis;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'por causa do plano determinado e da presciência de Deus, Ele foi entregue, e vós, pelas mãos de homens sem lei, o crucificastes e o matastes;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'a quem Deus ressuscitou, rompendo os grilhões da morte, porque não era possível que Ele fosse detido por ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Pois, a respeito dele, diz Davi: \'Eu via sempre o Senhor diante de mim, pois Ele está à minha direita para que eu não seja abalado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Portanto, meu coração se alegrou e minha língua se regozijou, até mesmo minha carne há de repousar em esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Pois não abandonarás minha alma no Hades, nem permitirás que o Teu Santo sofra corrupção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Tu me revelaste os caminhos da vida; Tu me encherás de alegria na Tua presença\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Irmãos, eu posso vos falar seguramente a respeito do patriarca Davi, ele tanto morreu quanto foi enterrado, e sua tumba está entre nós até hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Portanto ele era um profeta, e sabia que Deus havia lhe prometido com juramento, que colocaria um de seus descendentes no seu trono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'Ele previu isso e falou acerca da ressurreição de Cristo: \'Ele não foi abandonado no Hades, nem sua carne sofreu corrupção\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Este Jesus, a quem Deus ressuscitou, do qual todos nós somos testemunhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Assim, tendo sido elevado à direita de Deus, recebeu do Pai a promessa do Espírito Santo, o qual foi derramado e agora vós vedes e ouvis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Porque Davi não subiu aos céus, mas ele diz: \"O Senhor disse ao meu Senhor: \'Assenta-Te à minha direita,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'até que Eu faça dos Teus inimigos estrado para os Teus pés\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Portanto, que toda a casa de Israel certamente saiba: Este Jesus, a quem vós crucificastes, Deus o fez Senhor e Cristo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Quando ouviram isso, seus corações ficaram angustiados e disseram a Pedro e aos outros apóstolos: \"Irmãos, que devemos fazer?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'E Pedro lhes disse: \"Arrependei-vos e cada um de vós seja batizado em nome de Jesus Cristo, para perdão dos vossos pecados e recebereis o dom do Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Pois, a promessa é para vós, para vossos filhos e para todos os que estão longe, para todos quanto o Senhor nosso Deus chamar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Com muitas outras palavras Ele testificava e os exortava, dizendo: \"Salvai-vos desta geração perversa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Então, os que receberam a sua palavra, foram batizados, e naquele dia foram acrescentadas cerca de três mil almas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Eles perseveravam na doutrina dos apóstolos e na comunhão, no partir do pão e nas orações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Em cada alma havia temor, e muitas maravilhas e sinais eram feitos por meio dos apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Todos os que criam estavam unidos e tinham tudo em comum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'Vendiam suas propriedades e bens, e os repartiam com todos, conforme a necessidade de cada um.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Então, diariamente, continuavam num só propósito no templo, partiam o pão de casa em casa, comiam juntos com alegria e singeleza de coração;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'louvavam a Deus e tinham o favor de todo o povo. E o Senhor acrescentava dia após dia os que iam sendo salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Pedro e João estavam subindo para a oração no templo, na hora nona.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Certo homem, aleijado de nascença, era carregado todos os dias e deixado na porta do templo chamada Formosa, assim ele poderia pedir esmolas aos que entravam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Quando viu Pedro e João prestes a entrarem no templo, pediu-lhes esmolas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Pedro, fixando seus olhos nele, juntamente com João, disse: \"Olha para nós.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'O homem aleijado olhou para eles, esperando receber algo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Entretanto, Pedro disse: \"Não tenho nem prata nem ouro, mas o que eu tenho, isso te dou. Em nome de Jesus Cristo de Nazaré, anda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Pedro, tomando-o pela mão direita, levantou-o; e imediatamente seus pés e os ossos dos seus tornozelos receberam forças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Então num salto, o homem aleijado pôs-se de pé e começou a andar; e entrou com Pedro e João no templo, andando, saltando e louvando a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Todas as pessoas o viram andando e louvando a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Eles perceberam que este era o homem que se sentava para receber esmolas na porta Formosa do templo; e ficaram cheios de admiração e maravilhados por causa do que lhe aconteceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Apegando-se ele a Pedro e a João, todas as pessoas correram para junto deles, imensamente maravilhadas, no chamado Pórtico de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Quando Pedro viu isso, questionou-lhes: \"Vós, homens de Israel, por que vos maravilhais? Por que fixais vossos olhos sobre nós, como se nós o tivéssemos feito andar por nosso próprio poder e piedade?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'O Deus de Abraão, de Isaque e de Jacó, o Deus de nossos pais, glorificou a seu servo Jesus. Ele é aquele a quem vós entregastes e rejeitastes diante da face de Pilatos, quando este havia decidido libertá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Vós rejeitastes o Santo e Justo, e pediram ao invés disso, que um assassino fosse vos dado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Vós matastes o Autor da Vida, a quem Deus ressuscitou dos mortos, e somos testemunhas disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'E agora, este homem, o qual vós vedes e conheceis, tem sido fortalecido pela fé em Seu nome. A fé que vem por meio de Jesus, tem dado a este homem saúde perfeita, na presença de todos vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Irmãos, sei que agistes por ignorância, como também vossos governantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Contudo, as coisas que Deus profetizou pela boca de todos os profetas, que Seu Cristo deveria sofrer, Ele agora cumpriu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Arrependei-vos, portanto, e convertei-vos, para que vossos pecados sejam perdoados, e assim, possam vir tempos de refrigério na presença do Senhor;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'e Ele possa enviar o Cristo que vos foi previamente designado, Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Ele é Aquele a quem os céus devem receber até o tempo da restauração de todas as coisas, acerca de quem Deus falou, há muito tempo atrás, pela boca dos seus santos profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Verdadeiramente disse Moisés: \'O Senhor Deus levantará um profeta como eu dentre vossos irmãos. Deveis ouvi-Lo em tudo o que vos disser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Acontecerá que, todo aquele que não ouvir esse Profeta, será completamente destruído dentre o povo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'E todos os profetas, desde Samuel e os que o sucederam, falaram e anunciaram sobre esses dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Vós sois os filhos dos profetas e da Aliança que Deus fez com vossos pais, conforme disse para Abraão: \'Da tua semente todas as famílias da terra serão abençoadas\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Após Deus ter ressuscitado o seu Servo, primeiro O enviou a vós para vos abençoar, desviando cada um de vós das vossas maldades\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Enquanto Pedro e João falavam às pessoas, os sacerdotes, o capitão do templo e os saduceus, aproximaram-se deles');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'profundamente irados, porque Pedro e João ensinavam as pessoas sobre Jesus, e proclamavam a Sua ressureição dentre os mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Então, os prenderam e os colocaram em prisões até o dia seguinte, pois já era tarde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Contudo, muitas das pessoas que ouviram a mensagem creram; aproximadamente cinco mil homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Aconteceu que, no dia seguinte, seus governantes, anciãos e escribas se reuniram em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'Anás, o principal sacerdote, Caifás, João, Alexandre, e todos que eram da linhagem do sumo sacerdote.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Quando colocaram Pedro e João no meio deles, perguntaram: \"Por qual poder ou no nome de quem fizestes isso?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Então, Pedro, cheio do Espírito Santo, disse-lhes: \"Vós, governantes do povo, e anciãos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'se nós, neste dia, estamos sendo questionados em relação a uma boa obra feita para um homem doente, e do modo como foi curado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Seja isto conhecido por todos vós e por todo o povo de Israel, que no nome de Jesus Cristo de Nazaré, a quem vós crucificastes e a quem Deus ressuscitou dos mortos, é por meio Dele que esse homem está curado diante de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Jesus Cristo é a pedra que vós, como construtores, desprezastes, mas que foi feita pedra angular.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Não há salvação em nenhum outro; porque não há nenhum outro nome debaixo do céu, dado entre os homens, por meio do qual devamos ser salvos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Quando viram a intrepidez de Pedro e João e perceberam que eles eram simples homens iletrados, ficaram surpresos; perceberam que Pedro e João haviam convivido com Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'E, vendo estar com eles o homem que fora curado, nada tinham que dizer ao contrário.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Mas, depois que ordenaram os apóstolos a sairem da reunião do Conselho, conversaram entre si,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'dizendo: \"O que nós deveríamos fazer a estes homens? Porque é verídico que um incrível milagre que foi feito através deles, é conhecido por todos os que vivem em Jerusalém, e nós não podemos negar isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Mas, para que isso não seja propagado entre as pessoas, vamos alertá-los para não mais falarem a ninguém neste nome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Eles chamaram Pedro e João e ordenaram-lhes que não falassem, de nenhuma maneira, nem ensinassem, no nome de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Mas Pedro e João responderam dizendo: \"Julgais se é justo, perante Deus, obedecer a vós ao invés de obedecer a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Porque nós não podemos nos calar acerca das coisas que temos visto e ouvido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'E, ameaçando ainda mais a Pedro e João, os deixaram ir. Eles foram incapazes de achar qualquer justificativa para puní-los, porque todo o povo glorificava a Deus pelo que acontecera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'O homem que fora curado tinha mais de quarenta anos de idade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Depois de soltos, Pedro e João foram para seu próprio povo e relataram tudo o que os principais sacerdotes e os anciãos lhes tinham dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Quando ouviram isso, levantaram suas vozes juntos a Deus e disseram: \"Senhor, Tu que fizestes os céus, a terra, o mar, e tudo o que neles há;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Tu que, pelo Espírito Santo, pela boca do nosso pai Davi, Seu servo, disseste: \'Por que as nações dos gentios se iram, e os povos imaginam coisas vãs?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Os reis da terra se ajuntaram, e os governantes se reuniram contra o Senhor e contra O Seu Ungido\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'De fato, ambos, Herodes e Pôncio Pilatos, junto com os gentios e o povo de Israel, reunidos nesta cidade contra Teu Santo Servo, Jesus, a quem Tu ungistes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Eles reuniram-se para fazer tudo o que a Tua mão e o Teu desígnio decidiram antecipadamente que se havia de fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Agora, Senhor, olha para as suas ameaças e concede aos Teus servos falarem as Tuas palavras com toda ousadia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'Enquanto estendes a Tua mão para curar, e para que se façam sinais e maravilhas pelo nome do Teu Santo Servo Jesus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Quando terminaram de orar, o lugar em que eles estavam reunidos foi sacudido, e todos ficaram cheios do Espírito Santo, e anunciavam a Palavra de Deus com ousadia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Da multidão dos que creram era um só o coração e a alma, ninguém dizia que suas posses eram realmente suas; ao invés disso, tinham todas as coisas em comum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Com grande poder, os apóstolos proclamavam seus testemunhos acerca da ressureição do Senhor Jesus, e imensa graça estava sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Não havia ninguém entre eles que precisasse de algo, porque todos que possuíam propriedades ou casas, vendiam-nas e traziam o valor do que fora vendido');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'e depositavam-no aos pés dos apóstolos. E a distribuição era feita a cada um, de acordo com o que cada um necessitava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'José, um levita, originário de Chipre, a quem foi dado o nome de Barnabé pelos apóstolos, isto é, filho da consolação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Tendo uma propriedade, vendeu-a e trouxe o dinheiro e colocou-o aos pés dos apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Certo homem chamado Ananias, com Safira, sua mulher, vendeu uma propriedade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'e ficou com parte do dinheiro da venda (sua mulher também sabia disso). Ele levou a outra parte e colocou aos pés dos apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'No entanto, Pedro perguntou-lhe: \"Ananias, por que Satanás encheu o teu coração para que mentisses ao Espírito Santo e ficasses com uma parte do valor da propriedade?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Enquanto permanecia sem ser vendida, não era somente tua? E depois de ser vendida, não estava sob teu controle? Como tu pensaste essas coisas no teu coração? Vós não mentistes aos homens, mas a Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Ao ouvir essas palavras, Ananias caiu e expirou. Grande temor sobreveio a todos os que ouviram isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'E levantando-se os moços, cobriram-no, carregaram-no para fora e sepultaram-no.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Após cerca de três horas, entrou também sua mulher, não sabendo o que tinha acontecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Pedro disse para ela: \"Conte-me se tu vendeste aquela propriedade por tal quantia?\". Ela lhe respondeu: \"Sim, vendi por essa quantia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Então, Pedro lhe disse: \"Por que entraste em acordo para tentar o Espírito do Senhor? Veja, os que sepultaram o teu marido estão na porta, eles também te levarão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Imediatamente ela caiu aos pés dele e expirou, e os moços vieram e acharam-na morta; levaram-na para fora e sepultaram-na junto ao seu marido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'E um grande temor tomou conta de toda a congregação e de todos aqueles que ouviram essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Muitos sinais e maravilhas estavam acontecendo entre o povo pelas mãos dos apóstolos. E eles estavam reunidos no Pórtico de Salomão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Embora o povo os estimasse muito, ninguém mais tinha coragem de juntar-se a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'E crescia cada vez mais a multidão de crentes no Senhor, tanto homens como mulheres,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'de maneira que até mesmo os doentes eram levados para as ruas e colocados em leitos e macas, afim de que, quando Pedro passasse, ao menos a sua sombra se projetasse sobre alguns deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Também vinham juntos em grande número de pessoas das cidades ao redor de Jerusalém, levando doentes e atormentados por espíritos impuros, e todos eram curados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Então o sumo sacerdote se levantou, e todos os que estavam com ele, (isto é, a seita dos saduceus) e tomados de inveja');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'prenderam os apóstolos, colocando-os na prisão pública.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Durante a noite, o anjo do Senhor abriu as portas da cadeia, tirou-os para fora e disse-lhes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '\"Ide, apresentai-vos no templo e anunciai para as pessoas todas as palavras dessa vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Após ouvirem isso, entraram no templo ao alvorecer do dia e começaram a ensinar. Porém, chegando o sumo sacerdote e os que estavam com ele, convocaram o Conselho, com todos os líderes religiosos de Israel e enviaram guardas a prisão para trazer os apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Os guardas foram até lá, contudo, não os encontraram na prisão, retornaram e reportaram:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, '\"Encontramos a prisão trancada com toda segurança, e os guardas em pé juntos às portas, todavia, quando as abrimos, não encontramos ninguém\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Quando o capitão da guarda do templo e os principais sacerdotes ouviram essas palavras, ficaram muito perplexos concernente ao que havia acontecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Então chegou alguém e os avisou: \"Os homens que colocastes na prisão estão no templo ensinado as pessoas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Então o capitão foi com os oficiais e os trouxeram sem violência, pois temiam que o povo os apedrejasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'E, depois de trazê-los, os apresentaram ao conselho. O sumo sacerdote os interrogou,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'dizendo: \"Ordenamos expressamente que não ensinásseis nesse nome, ainda sim, enchestes Jerusalém com o vosso ensino e quereis lançar sobre nós o sangue desse homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Entretanto, Pedro e os apóstolos responderam: \"Devemos obedecer a Deus mais do que aos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'O Deus de nossos pais ressuscitou a Jesus, a quem vós matastes, suspendendo-o num madeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Deus O exaltou à sua mão direita para ser Príncipe e Salvador, para dar o arrependimento a Israel e a remissão dos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Somos testemunhas dessas coisas, e assim é o Espírito Santo, que Deus tem dado para aqueles que O obedecem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Quando ouviram isso, os membros do conselho enfureceram-se e quiseram matar os apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Mas um fariseu chamado Gamaliel, doutor da lei, respeitado por todas as pessoas, levantou-se e ordenou que os apóstolos fossem levados para fora por um momento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Em seguida disse-lhes: \"Homens de Israel, prestai muita atenção com o que estais para fazer com esses homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Há algum tempo atrás, Teudas se levantou dizendo ser alguém, e um número de homens, cerca de quatrocentos, ajuntou-se a ele. Ele foi morto, e todos os que o seguiram foram dispersos e reduzidos a nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Após isso, Judas da Galiléia, levantou-se nos dias do censo, e muitos o seguiram. Ele também pereceu, e todos aqueles que lhe obedeciam foram dispersos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Digo-vos, afastai-vos desses homens e deixai-os, porque se esse plano ou obra é de homens, perecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Todavia, se é de Deus, vós não podereis destruí-los, para que não sejais, porventura, achados lutando contra Deus\". E assim, eles foram convencidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Em seguida, chamando os apóstolos, os açoitaram, ordenando-lhes que não falassem no nome de Jesus, e os permitiram ir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Eles deixaram o conselho regozijando-se por terem sido considerados dignos de sofrer afronta pelo Nome de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'Depois disso, todos os dias, no templo e de casa em casa, continuamente ensinavam e pregavam a Jesus, o Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Naqueles dias, enquanto o número dos discípulos se multiplicavam, iniciou-se uma queixa dos gregos contra os hebreus, porque as suas viúvas estavam sendo esquecidas na distribuição diária dos alimentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Os doze, chamaram a comunidade dos discípulos e disseram-lhes: \"Não é certo para nós deixar-mos a Palavra de Deus para servirmos às mesas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Portanto, irmãos, escolhei sete homens dentre vós de boa reputação, cheios do Espírito e de sabedoria, os quais serão encarregados deste serviço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Quanto a nós, nos dedicaremos à oração e ao ministério da palavra\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'O discurso agradou a toda multidão. Então eles escolheram Estêvão, homem cheio de fé e do Espírito Santo, Filipe, Prócoro, Nicanor, Timão, Pármenas, e Nicolau, prosélito de Antioquia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'E apresentaram-se perante os apóstolos, que oraram e depois impuseram suas mãos sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Assim, a Palavra de Deus se espalhou; e o número dos discípulos se multiplicaram em Jerusalém e um grande número de sacerdotes tornaram-se obedientes à fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'E Estêvão, cheio de graça e poder, fazia prodígios e grandes sinais entre o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'E levantaram alguns que eram da sinagoga dos libertos e dos cirineus e dos alexandrinos, e dos que eram da Cilícia e da Ásia. Essas pessoas disputavam com Estêvão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Entretanto, não foram capazes de resistir contra a sabedoria e o Espírito com que ele falava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Então subornaram alguns homens para dizer: \"Ouvimos Estêvão proferir blasfêmias contra Moisés e contra Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Incitando o povo, os anciãos, e os escribas; e, investindo contra ele, o levaram para o conselho dos judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Trouxeram falsas testemunhas que disseram: \"Este homem não cessa de proferir palavras contra o santo lugar e contra a lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Porque o ouvimos dizer que esse Jesus de Nazaré destruirá esse lugar e mudará os costumes que Moisés nos deu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Então todos os que estavam sentados no Sinédrio fixaram seus olhos nele e viram a sua face, que parecia um rosto de um anjo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'O sumo sacerdote perguntou: \"Essas coisas são verdade?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Estêvão disse: \"Irmãos e pais, ouçam-me: O Deus da glória apareceu ao nosso Pai Abraão quando ele estava na Mesopotâmia, antes dele viver em Harã.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'E disse-lhe: \"Deixa tua terra e teus parentes, e vá para a terra que Eu te mostrarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Abraão deixou então a terra dos caldeus para habitar em Harã. De lá, após a morte de seu pai, Deus o fez passar para esta terra que vós habitais agora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Ele não lhe deu nenhuma herança, nem sequer onde pôr o pé, mas prometeu que lhe daria a terra como posse e à sua descendência, embora Abraão ainda não tivesse filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Deus falou com ele dessa maneira: Porque seus descendentes viveriam por um tempo numa terra estrangeira, onde seriam escravizados e maltratados por quatrocentos anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Disse Deus: \"Eu julgarei a nação na qual eles serão escravos. E, depois disso, virão e me adorarão nesse lugar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Então, lhe deu a aliança da circuncisão, e assim Abraão tornou-se o pai de Isaque e o circuncidou no oitavo dia. Isaque foi o pai de Jacó, e Jacó o pai dos doze patriarcas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Os patriarcas foram motivados por ciúmes contra José e o venderam para o Egito, mas Deus estava com ele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'e livrou-o de todos os seus sofrimentos, dando-lhe favor e sabedoria na presença do Faraó, rei do Egito. Faraó o fez governador do Egito e de toda a sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Sobreveio, porém, fome em todo o Egito e Canaã, houve grande sofrimento e nossos pais não encontravam comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Quando Jacó ouviu que no Egito havia grãos, enviou pela primeira vez, os nossos antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Na segunda vez, José fez-se reconhecer por seus irmãos, e a sua origem foi revelada ao Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'José enviou seus irmãos de volta para dizer a Jacó, seu pai, que viesse ao Egito, juntamente com toda a sua parantela, isto é, setenta e cinco pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Assim, Jacó desceu para o Egito, ali morreu ele e também nossos antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Foram transportados para Siquém e enterrados no túmulo que Abraão havia comprado por certa soma em dinheiro, dos filhos de Hamor em Siquém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Aproximava-se o tempo do cumprimento da promessa que Deus havia feito a Abraão; o povo havia crescido e se multiplicado no Egito,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'até que levantou-se ali outro rei, que não sabia nada a respeito de José.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Esse mesmo rei enganou nosso povo e maltratou nossos antepassados, obrigando-os a lançarem fora seus bebês, para que não sobrevivessem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Por esse tempo, Moisés nasceu. Ele era formoso diante de Deus, e foi amamentado por três meses na casa de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Quando foi lançado para fora, a filha do Faraó o adotou e o criou como um filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Moisés foi educado em toda a sabedoria dos egípcios; e era poderoso em suas palavras e obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Mas quando tinha cerca de quarenta anos, veio em seu coração o desejo de visitar seus irmãos, os filhos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Vendo um israelita sendo maltratado, Moisés o defendeu e o vingou contra o seu opressor, matando o egípcio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Pensava que seus irmãos compreenderiam que Deus ia libertá-los por sua mão, mas eles não compreenderam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'No dia seguinte, aproximou-se de alguns israelistas enquanto brigavam e tentou reconciliá-los, dizendo: \"Homens, vós sois irmãos; por que vos maltratais?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Porém, o que estava maltratando seu vizinho o empurrou, dizendo: \"Quem te fez chefe e juiz sobre nós?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Tu queres matar-me como mataste o egípcio ontem?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Depois de ouvir isso, Moisés fugiu. Tornou-se estrangeiro na terra de Midiã, onde gerou dois filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Decorridos quarenta anos, apareceu-lhe um anjo no deserto do Monte Sinai, numa sarça em chamas de fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Quando Moisés viu o fogo, ficou maravilhado com a visão e, aproximando para observar, ouviu-se a voz do Senhor, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '\"Eu sou o Deus dos seus pais, de Abraão, de Isaque e de Jacó\". Moisés tremeu e não se atreveu a olhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'O Senhor disse-lhe: \"Tire as suas sandálias, pois o lugar onde estás é uma terra santa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Eu certamente tenho visto o sofrimento do meu povo que está no Egito. Tenho ouvido o gemido deles e descerei para libertá-los; vem agora e Eu te enviarei ao Egito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'A esse Moisés, a quem havia rejeitado dizendo: \"Quem te fez chefe e juiz?\" -a este enviou Deus como chefe e libertador pela mão do anjo que lhe aparecera na sarça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Moisés tirou-os do Egito depois de fazer milagres e sinais no Mar Vermelho e no deserto, durante quarenta anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Este é o mesmo Moisés que disse ao povo de Israel: \"Deus levantará um profeta para vós do meio dos seus irmãos, um profeta como eu.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Este é o que esteve na congregação no deserto, com o anjo que lhe falava no monte Sinai, e com nossos antepassados, o qual recebeu palavras de vida para nos transmitir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Esse é o homem que nossos pais recusaram obedecer; antes o rejeitaram, e voltaram seus corações para o Egito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'Naquele tempo disseram a Arão: \"Faça-nos deuses que nos guiarão. Quanto a Moisés, que nos tirou da terra do Egito, nós não sabemos o que aconteceu com ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Naqueles dias fizeram um bezerro e ofereceram sacrifício ao ídolo, alegrando-se com as obras das suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Mas Deus se afastou e os abandonou ao culto das hostes do céu, como está escrito no livro dos profetas: \"Porventura me oferecestes vítimas e sacrifícios por quarenta anos no deserto, ó casa de Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Vós aceitastes o tabernáculo de Moloque e a estrela do deus Refã, e as imagens que fizestes para adorá-las: e Eu vos levarei para longe, para a Babilônia.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Nossos antepassados tinham o tabernáculo do testemunho no deserto, assim como Deus ordenara quando ele falou a Moisés, que deveria fazê-lo de acordo com o modelo que tinha visto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Essa é a tenda que nossos antepassados, naquele tempo, levaram para a terra com Josué. Isso aconteceu quando tomaram posse das nações que Deus expulsou de diante da presença de nossos antepassados. Foi assim até os dias de Davi,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'que achou graça aos olhos de Deus; ele pediu para encontrar um lugar de habitação para o Deus de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Mas Salomão construiu a casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Contudo, o Altíssimo não habita em casas feitas por mãos humanas, assim como diz o profeta:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '\"Os céus são o Meu trono, e a terra é o estrado para os Meus pés. Que tipo de casa podeis construir para mim, diz o Senhor; ou qual é o lugar do Meu descanso?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Não fez minha mão todas essas coisas?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Vós, pessoas obstinadas e incircuncisas de coração e ouvidos, sempre resistis ao Espírito Santo; vós agis assim como vossos antepassados agiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Quais dos profetas seus antepassados não perseguiram? Eles mataram os profetas que apareceram antes da vinda do Justo; e vos tornastes traidores e assassinos também deste;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'vós, pessoas que recebestes a Lei por ministério de anjos, mas não a guardastes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Então, quando os membros do conselho ouviram essas coisas, enfureceram-se no coração e rangeram seus dentes contra Estêvão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Mas ele, estando cheio do Espírito Santo, olhou atentamente para o céu e viu a glória de Deus, e Jesus, em pé, à direita de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'Estêvão disse: \"Olhem, vejo os céus abertos, e o Filho do Homem em pé à mão direita de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Porém, os membros do conselho gritaram em alta voz, taparam seus ouvidos e juntos precipitaram-se contra ele;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'o lançaram fora da cidade e apedrejaram; as testemunhas deixaram suas capas aos pés de um jovem chamado Saulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Enquanto apedrejavam Estêvão, ele invocando o Senhor dizia: \"Senhor Jesus, recebe o meu espírito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Ele ajoelhou-se e gritou em alta voz: \"Senhor, não considere-os culpados deste pecado\". Tendo dito isso, caiu adormecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Saulo consentiu com sua morte. Então ali naquele dia iniciou-se uma grande perseguição contra a igreja que estava em Jerusalém; e os cristãos estavam todos espalhados pelas regiões da Judéia e Samaria, exceto os apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Homens devotos enterraram Estêvão e houve grande lamentação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Mas Saulo perseguia intensamente a igreja; e entrando de casa em casa, arrastava para fora homens e mulheres, e os levavam para a prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Entretanto os cristãos que tinham sido dispersos, pregavam a palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Filipe desceu à cidade de Samaria e proclamou-lhes o Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Enquando as multidões ouviram e viram os sinais que Filipe fazia, prestavam atenção ao que ele dizia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Pois, os espíritos imundos saiam de muitas pessoas enquanto gritavam em alta voz; e muitos paralíticos e coxos foram curados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'E houve muita alegria naquela cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Mas havia um certo homem na cidade chamado Simão, que desde cedo praticava feitiçaria para surpreender as pessoas de Samaria, enquanto afirmavam que ele era uma pessoa importante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Todos os samaritanos, desde o menor até o maior, prestavam atenção nele; eles diziam: \"Este homem é aquele que é chamado de o grande poder de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Estes o escutavam porque os tinha surpreendido por um longo tempo com suas artes mágicas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Quando, porém, acreditaram que Filipe proclamava o evangelho do Reino de Deus e do nome de Jesus Cristo, foram batizados tanto homens quanto mulheres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Simão também creu e após ter sido batizado, permaneceu com Filipe. Quando viu sinais e prodígios sendo realizados ficou maravilhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Ouvindo os apóstolos que estavam em Jerusalém, que Samaria tinha recebido a palavra de Deus, enviaram-lhes Pedro e João.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Os quais, tendo descido, oraram por eles, para que pudessem receber o Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Até aquele momento, o Espírito Santo não havia descido sobre nenhum deles; eles apenas tinham sido batizados no nome do Senhor Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Então Pedro e João impuseram-lhes as mãos, e eles receberam o Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Quando Simão viu que o Espírito Santo fora dado por meio da imposição das mãos dos apóstolos, ofereceu-lhes dinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Ele disse: Dai-me este poder também, para que aquele sobre quem eu colocar minhas mãos, receba o Espírito Santo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Mas Pedro lhe disse: \"Que sua prata pereça contigo, porque tu pensastes em obter o dom de Deus com dinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Tu não tens parte ou porção neste ministério, pois teu coração não é reto para com Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Portanto, arrependa-te dessa tua maldade, e ore ao Senhor para que talvez possa perdoá-lo pela intenção do teu coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Pois vejo que estás no veneno da amargura e em laços de pecado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Simão respondeu e disse: \"Ore ao Senhor por mim, para que nada do que haveis dito possa acontecer comigo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Tendo eles, pois, testificado e falado a palavra do Senhor, Pedro e João retornaram para Jerusalém, anunciando o evangelho em muitas aldeias dos samaritanos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Então, um anjo do Senhor falou a Filipe e disse: \"Levanta-te e vai em direção ao sul pela estrada que desce de Jerusalém para Gaza\". (Essa estrada está em um deserto.)');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Ele se levantou e foi. E viu um homem da Etiópia, um eunuco administrador de Candace, rainha dos etíopes, o qual era encarregado de todo seu tesouro, tinha vindo a Jerusalém para adorar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'Estava voltando e, sentado em sua carruagem, começou a ler o profeta Isaías.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'O Espírito disse a Filipe: \"Vá e fique perto dessa carruagem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Então, Filipe correu até ele e o ouviu lendo o profeta Isaías, e disse: \"Entendes o que estais lendo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'O etíope respondeu: \"Como posso, a menos que alguém me guie?\" Ele implorou a Filipe que subisse na carruagem e com ele se assentasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'A passagem da Escritura que o etíope estava lendo era esta: \"Ele foi levado como uma ovelha para o matadouro, e, como um cordeiro diante do seu tosqueador, ficou em silêncio e não abriu a sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'Na Sua humilhação foi retirado a justiça; quem contará à Sua geração? Porque Sua vida é tirada da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Então, o eunuco perguntou a Filipe e disse: \"Peço-lhe, sobre quem o profeta está falando? De si mesmo, ou de outra pessoa?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Filipe começou a falar e, utilizando essa passagem da Escritura, pregou as boas novas de Jesus para ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Enquanto eles seguiam pela estrada, chegaram a um lugar onde havia água e o eunuco disse: \"Olhe, há água aqui; o que me impede de ser batizado?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, '--');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Então, o etíope ordenou a carruagem que parasse, e ambos desceram à água, e Filipe o batizou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Quando saíram da água, o Espírito do Senhor arrebatou a Filipe, o eunuco não mais o viu, e seguiu seu caminho com alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Mas Filipe se achou em Azoto e, pregava o evangelho em todas as cidades, até que chegou a Cesareia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Porém, Saulo, respirando ainda ameaças e morte contra os discípulos do Senhor, foi até ao sumo sacerdote,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'e pediu-lhe cartas para as sinagogas de Damasco, a fim de que, caso encontrasse alguém que pertencia ao Caminho, os levasse presos para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Enquanto estava viajando, ao aproximar-se de Damasco, de repente uma luz do céu brilhou ao seu redor;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'e, caindo ao chão, ouviu uma voz que lhe dizia: \"Saulo, Saulo, por que me persegues?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Saulo respondeu: \"Quem és Tu, Senhor?\" O Senhor disse: \"Eu sou Jesus, a quem tu persegues;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'mas levanta-te e entra na cidade, e te dirão o que deves fazer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Os homens que viajavam com Saulo ficaram sem palavras, ouvindo a voz, porém, não vendo ninguém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Saulo levantou-se do chão e, quando abriu os olhos, não podia ver nada. Então, levaram-no pela mão e o trouxeram para Damasco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Por três dias ficou sem ver, não comeu e nem bebeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Havia um discípulo em Damasco chamado Ananias. Disse-lhe o Senhor numa visão: \"Ananias!\" E ele disse: \"Eis-me aqui, Senhor\"!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'O Senhor lhe ordenou: \"Levanta-te, e vai à rua que se chama Direita, e na casa de Judas pergunta por um homem chamado Saulo, um homem de Tarso; pois ele está orando;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'e, numa visão, viu um homem chamado Ananias vindo e impondo as mãos sobre ele, para que recuperasse a vista\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Ananias porém, respondeu: \"Senhor, de muitos tenho ouvido a respeito desse homem, quantos males tem feito aos Teus santos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Ele tem autorização pelo sumo sacerdote de prender a todos os que invocam o Teu nome.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Porém, o Senhor lhe disse: \"Vai, porque esse é para Mim um vaso escolhido para levar Meu Nome perante os gentios e os reis, e os filhos de Israel;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'pois Eu lhe mostrarei o quanto deve sofrer por causa do Meu Nome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Então Ananias foi e, entrando na casa, colocou sobre ele as mãos, dizendo: \"Irmão Saulo, o Senhor Jesus, que te apareceu na estrada por onde vinhas, enviou-me, para que recuperes a vista e sejas cheio do Espírito Santo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Imediatamente, algo como escamas caíram-lhe dos olhos, e tornou a ver; levantou-se e foi batizado;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'comeu e foi fortalecido. E permaneceu com os discípulos em Damasco por vários dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'Logo proclamou Jesus nas sinagogas, dizendo que Ele é o Filho de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Todos os que o ouviam estavam maravilhados e diziam: \"Não é esse o homem que assolou aqueles em Jerusalém que invocavam este Nome? E veio aqui para trazê-los presos ao sumo sacerdote?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Contudo, Saulo, fortalecendo-se, pregava e confundia os judeus que viviam em Damasco, provando que Jesus é o Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Depois de muitos dias, os judeus planejaram matá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Mas o plano deles tornou-se conhecido por Saulo. Eles vigiavam os portões dia e noite a fim de matá-lo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'mas os seus discípulos tomaram-no de noite e o desceram num grande cesto pelo muro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Quando chegou a Jerusalém, Saulo procurou juntar-se aos discípulos, mas todos estavam com medo dele, não acreditando que era um discípulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Mas Barnabé, tomando-o consigo, levou-o aos apóstolos; e contou-lhes como ele havia visto o Senhor na estrada, e que Este lhe falara, e como em Damasco pregara corajosamente em nome de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Estava com eles em Jerusalém, entrando e saindo, falando corajosamente em nome do Senhor Jesus');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'e debatia com os helenistas; mas eles continuaram tentando matá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Quando os irmãos souberam disso, trouxeram-no para Cesareia e enviaram-no para Tarso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Assim, as igrejas em toda a Judeia, Galileia e Samaria, tinham paz e eram edificadas, caminhando no temor do Senhor e no consolo do Espírito Santo; cresciam em número.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Então, sucedeu que Pedro, caminhando por toda a região, desceu também ao povo de Deus que vivia na cidade de Lida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Encontrou ali certo homem chamado Eneias, que esteve acamado por oito anos, pois era paralítico.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Pedro disse-lhe: \"Eneias, Jesus Cristo te cura. Levanta e arruma a tua cama\". E de imediato se levantou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Então, todos os que viviam em Lida e em Sarona, vendo o homem, converteram-se ao Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Havia em Jope uma certa discípula chamada Tabita, que traduzido é \"Dorcas\". Essa mulher era cheia de boas obras e de atos misericordiosos que fazia aos pobres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Aconteceu naqueles dias que ela adoeceu e morreu. Quando eles a lavaram, deitaram-na num aposento superior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Como Lida era perto de Jope, e os discípulos ouviram que Pedro estava lá, enviaram dois homens, pedindo-lhe: \"Venha até nós sem demora\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Pedro levantou-se e foi com eles. Quando chegou, levaram-no ao aposento superior. Todas as viúvas estavam perto dele chorando, mostrando-lhe as roupas e vestimentas que Dorcas fizera enquanto estava com elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Pedro mandou sair todos do quarto, ajoelhou-se e orou. E, voltando-se para o corpo, disse: \"Tabita, levanta\". Ela abriu os olhos e, vendo a Pedro, sentou-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Pedro, dando-lhe a mão, levantou-a, e, chamando os cristãos e as viúvas, apresentou-a viva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Esse fato tornou-se conhecido por toda Jope, e muitas pessoas creram no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Pedro ficou em Jope por muitos dias, com um homem chamado Simão, um curtidor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Havia certo homem na cidade de Cesareia chamado Cornélio, um centurião da corte Italiana.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Homem devoto que adorava a Deus com toda sua casa, dava muitas esmolas ao povo e continuamente orava a Deus por todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Por volta da hora nona do dia, viu claramente em uma visão um anjo de Deus que se dirigia para ele. O anjo disse-lhe: \"Cornélio!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Cornélio, fixando os olhos no anjo, estava muito assustado e disse: \"O que é isso, Senhor?\" O anjo disse-lhe: \"Tuas orações e tuas esmolas aos pobres têm subido como memorial na presença de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Portanto envie homens à cidade de Jope para trazer um homem cujo nome é Simão, também chamado Pedro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Ele está com um curtidor chamado Simão, cuja casa fica junto ao mar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Quando o anjo que lhe falava se afastou, Cornélio chamou dois dos seus servos e um soldado piedoso, daqueles que estavam ao seu serviço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'Cornélio disse a todos o que acontecera e os enviou a Jope.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'No dia seguinte, por volta da hora sexta, conforme eles estavam em sua jornada, aproximando-se da cidade, Pedro subiu ao terraço para orar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Então, tendo fome, quis comer, mas enquanto as pessoas preparavam a comida, sobreveio-lhe um arrebatamento de sentidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'E viu o céu aberto e um objeto que descia como um grande lençol atado pelas quatro pontas, sendo baixado para a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Nele havia todos os tipos de animais quadrúpedes e coisas que rastejavam sobre a terra, e pássaros do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Uma voz lhe falou: \"Levanta-te, Pedro! Mata e come\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Porém Pedro disse: \"Não, Senhor, pois jamais comi nada que seja profano e imundo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Novamente, a voz veio a ele, pela segunda vez: \"O que Deus purificou não o chame de impuro.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Isso aconteceu três vezes, e o objeto imediatamente foi recolhido para o céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Enquanto Pedro estava muito confuso acerca do que poderia significar a visão que tivera, avistou os homens enviados por Cornélio que perguntavam sobre sua casa, os quais pararam à porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'Chamando-o, perguntaram se Simão, chamado de Pedro, estava lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Enquanto Pedro ainda pensava na visão, o Espírito disse-lhe: \"Vê três homens que estão procurando por ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Levanta, desce e vai com eles. Não tenhas medo de ir, porque Eu os enviei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Então Pedro desceu e disse aos homens: \"Sou eu a quem procurais. Por que vieste?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Então disseram: \"Um centurião chamado Cornélio, homem justo que adora a Deus e que tem bom testemunho de toda a nação judaica, foi instruído divinamente por um santo anjo de Deus, que disse para que te chamasse a sua casa e ouvisse as tuas palavras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Então Pedro os convidou para entrar e ficar com ele. Na manhã seguinte, levantou-se e foi com eles, e alguns dos irmãos de Jope o acompanharam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'No dia seguinte, chegaram a Cesareia. Cornélio estava esperando por eles, tendo reunido seus parentes e amigos íntimos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Quando Pedro entrou, Cornélio saiu-lhe ao encontro e inclinou-se aos seus pés e o adorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Porém Pedro o ergueu, dizendo: \"Levanta-te, pois eu também sou homem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Enquanto Pedro falava, entrou e encontrou muitas pessoas reunidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'E disse-lhes: \"Vós bem sabeis que não é permitido para um homem judeu ajuntar-se ou visitar alguém de outra nação. Porém Deus me mostrou que não devo chamar nenhum homem de profano ou imundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Por isso vim sem objeção, tendo sido chamado. Pergunto-vos, portanto, por que me chamastes?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Cornélio disse: \"Há quatro dias, nessa mesma hora, estava eu orando na hora nona, na minha casa, e vi diante de mim um homem com roupas resplandecentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'Ele disse: \"Cornélio, tua oração tem sido ouvida, e as tuas esmolas aos pobres lembradas diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Então envia alguém a Jope e chama Simão, cujo nome também é Pedro. Ele está na casa de um curtidor chamado Simão, junto ao mar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Por isso te mandei logo chamar e tu fizeste bem em vir. Agora, pois, aqui estamos todos reunidos na presença de Deus para ouvirmos o que o Senhor te mandou dizer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Então, abrindo a boca, Pedro disse: \"Verdadeiramente percebo que Deus não faz acepção de pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'No entanto, em cada nação, qualquer que O tema e faça o que é justo lhe é aceitável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Vós conheceis a mensagem que foi enviada para o povo de Israel, anunciando-lhe as boas novas da paz por meio de Jesus Cristo, que é o Senhor de todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Vós sabeis dos acontecimentos que ocorreram por toda a Judeia, começando na Galileia, depois do batismo que João anunciou;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'os acontecimentos acerca de Jesus de Nazaré, como Deus O ungiu com o Espírito Santo e poder. Ele andou fazendo o bem e curando a todos os oprimidos pelo diabo, pois Deus era com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Nós somos testemunhas de tudo o que Ele fez, tanto na Judeia como em Jerusalém - esse Jesus a quem eles mataram, pendurando-O num madeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Mas Deus O ressuscitou ao terceiro dia e fez que se manifestasse,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'não para todas as pessoas, mas às testemunhas que foram escolhidas de antemão por Deus: a nós mesmos, os que comemos e bebemos com Ele após sua ressurreição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Ele nos ordenou que pregássemos ao povo e testificássemos que Ele é quem foi escolhido por Deus Juiz de vivos e de mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Todos os profetas dão testemunho Dele, de maneira que todo aquele que Nele crê receberá perdão de pecados através do Seu Nome\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Enquanto Pedro ainda dizia essas coisas, o Espirito Santo desceu sobre todos aqueles que estavam ouvindo sua mensagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Todos os cristãos circuncidados que vieram com Pedro ficaram maravilhados, porque o dom do Espírito Santo também foi derramado sobre os gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Pois ouviram esses gentios falarem em línguas e adorar a Deus. Então Pedro respondeu:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, '\"Pode alguém recusar água a estas pessoas para que não sejam batizadas, estas que receberam o Espírito Santo assim como nós?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'E ele ordenou que fossem batizados no nome de Jesus Cristo. Então eles pediram-no para ficar com eles por alguns dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Os apóstolos e os irmãos que estavam na Judeia ouviram que os gentios também haviam recebido a Palavra de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Quando Pedro subiu a Jerusalém, os que eram da circuncisão criticaram-no');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'e disseram: \"Tu te associaste com homens incircuncisos e comeste com eles!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Pedro, porém, começou a explicar-lhes o assunto detalhadamente e disse:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '\"Estava eu orando na cidade de Jope e tive uma visão de um objeto descendo, como um grande lençol baixado do céu, pendurado pelas quatro pontas, vindo para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Contemplei e pensei acerca disso; vi os quadrúpedes da terra, bestas selvagens, animais rastejantes e pássaros do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Então ouvi uma voz que me dizia: \"Levanta, Pedro! Mata e come!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Eu disse: \"De forma alguma, Senhor, pois nada profano ou imundo jamais entrou em minha boca\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Porém a voz respondeu uma segunda vez do céu: \"Não chames imundo o que Deus purificou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Aconteceu isso três vezes, e todas as coisas foram levadas de volta para o céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Naquele momento, três homens enviados a mim de Cesareia, pararam em frente à casa onde estávamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'O Espírito ordenou-me ir com eles, e não fazer distinção a respeito deles. Estes seis irmãos foram comigo, e entramos na casa do homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Ele nos falou como tinha visto o anjo em pé, na sua casa, dizendo: \"Envia homens a Jope, e manda buscar Simão, também chamado Pedro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Ele vos falará a mensagem pela qual serás salvo - tu e todos os teus familiares\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Logo que comecei a lhes falar, o Espírito Santo veio sobre eles, assim como sobre nós, no início.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Lembrei-me das Palavras do Senhor, que disse: \"João de fato batizou com água; mas vós sereis batizados com o Espírito Santo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Portanto, se Deus lhes deu o mesmo dom como concedera também a nós, quando acreditamos no Senhor Jesus Cristo, quem sou eu, para que me opusesse a Deus?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Quando ouviram estas coisas, nada falaram em resposta, mas oraram a Deus e disseram: \"Então Deus também concedeu aos gentios arrependimento para a vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Portanto os crentes que foram espalhados por causa da persguição que começou com a morte de Estêvão dispersaram-se para a Fenícia, Chipre e Antioquia, mas falaram a mensagem sobre Jesus somente aos judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Mas alguns deles, homens de Chipre e Cirene, os quais, entrando na Antioquia, falaram aos gregos, anunciando-lhes as boas novas sobre o Senhor Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'E a mão do Senhor estava com eles, e um grande número creu e se converteu ao Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Notícias sobre eles chegaram até os ouvidos da igreja em Jerusalém, e eles enviaram Barnabé até Antioquia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Quando ele veio e viu o dom de Deus, alegrou-se; e encorajou a todos para permanecerem no Senhor com firmeza de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Pois ele era um bom homem, cheio do Espírito Santo e de fé, e muitas pessoas se uniram ao Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Então Barnabé foi para Tarso, procurando por Saulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Quando o encontrou, levou-o para Antioquia. Sucedeu que, por um ano inteiro, eles congregaram juntos com a igreja e ensinaram muitas pessoas. Os discípulos foram chamados de \"cristãos\" pela primeira vez, em Antioquia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'Naqueles dias, alguns profetas desceram de Jerusalém para Antioquia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Um deles, chamado Ágabo, levantou-se e indicou pelo Espírito que haveria uma grande fome em todo o mundo, o que ocorreu nos dias de Cláudio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Então os discípulos, conforme a capacidade de cada um, decidiram enviar ajuda aos irmãos na Judeia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Eles fizeram isso e enviaram dinheiro para os presbíteros pela mão de Barnabé e Saulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Porém, naquele tempo, o rei Herodes prendeu alguns da igreja para os maltratar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'e matou Tiago, o irmão de João à espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Depois de ter visto que isso agradou aos judeus, prosseguiu para prender também Pedro. Isso ocorreu durante os dias dos Pães sem Fermento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Após deter Pedro, colocou-o na prisão e pôs quatro grupos de quatro soldados para vigiá-lo, pretendendo trazê-lo para o povo após a Páscoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Então Pedro foi mantido numa prisão, porém a igreja orava a Deus por ele fervorosamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Naquela noite, quando Herodes estava para apresentá-lo, Pedro estava dormindo entre dois soldados, preso com duas correntes, e, à frente da porta, guardas estavam vigiando a prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Então um anjo do Senhor repentinamente lhe apareceu, e uma luz resplandeceu na cela. O anjo tocou no lado de Pedro, acordou-o e disse: \"Levanta rapidamente\". Então suas correntes caíram de suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'O anjo disse-lhe: \"Coloca tua roupa e calça tuas sandálias\". Pedro fez isso. O anjo disse a ele: \"Coloca tua capa e segue-me\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Pedro seguiu o anjo e saiu. Ele não sabia se o que o anjo fizera era real. Ele pensou que estava tendo uma visão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Depois de passar pela primeira e pela segunda guarda, chegaram ao portão de ferro que dava para a cidade, o qual se abriu sozinho para eles. Saindo, desceram uma rua, e o anjo imediatamente o deixou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Quando Pedro caiu em si, disse: \"Verdadeiramente, agora sei que o Senhor enviou seu anjo e me livrou da mão de Herodes e de toda a expectativa do povo judeu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Após ter entendido isso, foi para casa de Maria, mãe de João, cujo sobrenome era Marcos, onde muitos cristãos estavam reunidos e oravam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Quando bateu à porta, uma serva chamada Rode saiu para atender.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Ao reconhecer a voz de Pedro, transbordou de alegria e esqueceu de abrir a porta. Em vez disso, correndo para a sala, informou que Pedro estava em pé, à porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Então eles lhe disseram: \"Tu estás louca\". Porém ela insistia. Eles disseram: \"É o anjo dele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Mas Pedro continuou batendo e, quando abriram a porta, viram-no e ficaram maravilhados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Acenando-lhes com a mão para que ficassem em silêncio, contou-lhes como o Senhor o retirara da prisão. Ele disse: \"Informai essas coisas a Tiago e aos irmãos.\" Então saiu e foi para outro lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Quando o dia clareou, havia muita agitação entre os soldados a respeito do que havia acontecido a Pedro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Depois de Herodes ter procurado por ele, não podendo encontrá-lo, interrogou os guardas e ordenou que fossem executados. Então Herodes desceu da Judeia para a Cesareia e passou algum tempo ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Herodes estava furioso com os habitantes de Tiro e Sidom, os quais foram juntos até ele, e persuadiram Blasto, o assistente do rei, para ajudá-los. Então pediram paz, porque a terra deles recebia comida do país do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Num determinado dia, Herodes vestiu trajes reais, sentou-se no trono e fez um discurso para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'As pessoas gritaram: \"Voz de Deus, e não de homem!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Imediatamente um anjo do Senhor o feriu, porque não deu glória a Deus, e, comido por vermes, morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Contudo a palavra de Deus crescia e se multiplicava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnabé e Saulo retornaram de Jerusalém após terem completado sua missão, levando consigo João, cujo sobrenome era Marcos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Havia alguns mestres e profetas na igreja em Antioquia. Eram Barnabé, Simeão, chamado Níger, Lúcio de Cirene, Manaém, o irmão adotivo do governante Herodes, e Saulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Enquanto adoravam ao Senhor e jejuavam, o Espírito Santo disse: \"Separai-Me Barnabé e Saulo para a obra que os tenho chamado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Após jejuarem, orarem e imporem as suas mãos sobre esses homens, eles os enviaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Então, Barnabé e Saulo obedeceram ao Espírito Santo, e desceram a Selêucia; dali navegaram para a ilha de Chipre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Quando estavam na cidade de Salamina, proclamavam a palavra de Deus nas sinagogas dos judeus. Tinham também João Marcos como seu assistente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Após atravessarem toda a ilha de Pafos, encontraram um certo mago, um falso profeta judeu cujo nome era Barjesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'O qual estava com o procônsul Sérgio Paulo, que era um homem inteligente. Este mandou chamar Barnabé e Saulo, porque queria ouvir a Palavra de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Porém, Elimas, \"o mago\" (essa é a tradução do seu nome), opunha-se a eles; ele tentava desviar o procônsul da fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Mas Saulo, também chamado Paulo, cheio do Espírito Santo, olhou nos seus olhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'e disse: \"Tu, filho do diabo, estás cheio de todo tipo de engano e maldade. Tu és inimigo de todo tipo de justiça. Será que nunca cessarás de perverter os retos caminhos do Senhor?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Agora, a mão do Senhor está contra ti, e ficarás cego. Tu não verás o sol por algum tempo\". Imediatamente, névoa e escuridão caíram sobre Elimas; e, andando, pedia às pessoas para guiá-lo pela mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Depois que o procônsul viu o que aconteceu, creu, porque ficou maravilhado com o ensino acerca do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Então, Paulo e seus amigos navegaram de Pafos e chegaram a Perge, na Panfília. Contudo, João os deixou e retornou para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Paulo e seus amigos viajaram de Perge, e chegaram a Antioquia da Pisídia. Ali, foram à sinagoga, no dia de sábado, e sentaram-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Após a leitura da Lei e dos Profetas, os líderes da sinagoga mandaram-lhes uma mensagem dizendo: \"Irmãos, se tendes alguma mensagem de encorajamento para o povo, falai\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Assim, Paulo levantou-se e, pedindo silêncio com a mão, disse: \"Homens de Israel e vós que honrais a Deus, ouvi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'O Deus deste povo, Israel, escolheu nossos ancestrais, e fez o povo numeroso quando eles estavam na terra do Egito e com braço poderoso os tirou de lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Por cerca de quarenta anos, Ele os sustentou no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Depois de ter destruído as sete nações da terra de Canaã, Ele deu ao nosso povo essa terra por herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Tudo isso levou mais de quatrocentos e cinquenta anos. Depois de todas essas coisas, Deus lhes deu juízes até o profeta Samuel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Então o povo pediu um rei e, por quarenta anos, Deus lhes deu Saul, filho de Quis, homem da tribo de Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Com o passar do tempo, Deus o retirou do reinado e deu-lhes Davi como rei. Sobre Davi, Deus disse: \'Achei Davi, filho de Jessé, para ser um homem segundo o meu coração; ele fará tudo o que Eu desejo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Da descendência desse homem, Deus trouxe a Israel o Salvador, Jesus, conforme prometeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Antes de Sua vinda, João anunciou o batismo de arrependimento para todo o povo de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Quando João estava finalizando sua carreira, disse: \'Quem vós pensais que eu sou? Eu não sou Quem pensais. Mas Ele virá após mim, Aquele cujas sandálias dos pés não sou digno de desatar\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Irmãos, filhos da descendência de Abraão e aqueles dentre vós que adorais a Deus, foi a nós que a mensagem desta salvação foi enviada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Pois os que vivem em Jerusalém e suas autoridades, não O conheceram de fato, nem compreenderam a mensagem dos profetas que se leem todos os sábados; mas, eles cumpriram as palavras dos profetas condenando Jesus à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Mesmo que não tenham encontrado nenhuma razão para a morte Dele, pediram a Pilatos para matá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Quando completaram todas as coisas que foram escritas sobre Ele, tiraram-No do madeiro e colocaram-No numa sepultura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Todavia, Deus O ressuscitou dentre os mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Ele foi visto por muitos dias por aqueles que vieram com Ele da Galileia para Jerusalém; essas pessoas são agora Suas testemunhas para o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Então, trazemos para vós boas notícias sobre as promessas feitas aos nossos antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Deus fez essas promessas para nós, seus filhos, de que Ele ressuscitou Jesus dentre os mortos. Isso também é o que foi escrito no salmo segundo: \'Tu és o Meu Filho, hoje Te gerei’.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Também pelo fato de O ter ressuscitado dentre os mortos, para que Seu corpo não se corrompa, Ele falou assim: \'Te darei as santas e fiéis bênçãos de Davi\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Por essa razão, Ele também disse em outro salmo: \'Tu não permitirás que o Teu Santo veja corrupção\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Portanto, depois que Davi serviu na sua própria geração aos desígnios de Deus, ele adormeceu, foi sepultado junto a seus pais e viu a corrupção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Mas Ele, a quem Deus ressuscitou, não viu a corrupção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Então, seja isto conhecido por vós, irmãos, que através Desse Homem é anunciado a vós o perdão dos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'Por meio Dele, todo aquele que crê é justificado de todas as coisas das quais não pudestes ser justificados pela lei de Moisés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Logo, tende cuidado para que as coisas que os profetas disseram não vos aconteçam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '\'Vede, ó desprezadores, admirai-vos e perecei; porque estou fazendo uma obra em vossos dias na qual vós não crereis, mesmo se alguém vos anunciasse\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Enquanto Paulo e Barnabé estavam saindo, o povo gentiu lhes rogava que no sábado seguinte falassem mais a respeito dessas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Quando a reunião da sinagoga terminou, muitos judeus e devotos prosélitos seguiram Paulo e Barnabé, os quais, falando-lhes, os exortavam a perseverar na graça de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'No sábado seguinte, quase toda a cidade estava reunida para ouvir a Palavra do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Quando os judeus viram as multidões, se encheram de inveja e contradiziam as coisas ditas por Paulo e o insultavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Entretanto, Paulo e Barnabé, falando ousadamente, disseram-lhes: \"Era necessário que a Palavra de Deus fosse proclamada primeiramente a vós. Visto que a rejeitais e não vos considerais dignos da vida eterna, vede, voltaremo-nos para os gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Porque assim o Senhor nos ordenou, dizendo: \'Eu tenho vos colocado como luz para os gentios, a fim de que possais levar salvação até aos confins da terra\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Quando ouviram isso, os gentios se alegraram e louvaram a Palavra do Senhor. E creram, todos quanto foram designados para a vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'A Palavra do Senhor foi espalhada por toda aquela região.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Todavia, os judeus exortaram mulheres importantes e devotas, assim como os homens que eram líderes na cidade. Eles instigaram uma perseguição contra Paulo e Barnabé e os lançaram fora das fronteiras de sua cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Mas Paulo e Barnabé sacudiram a poeira dos seus pés contra eles. Em seguida, partiram para a cidade de Icônio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'E os discípulos estavam cheios de alegria e do Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Aconteceu em Icônio que Paulo e Barnabé entraram juntos na sinagoga dos judeus, e falaram de tal maneira que uma grande multidão de judeus e gregos acreditou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Mas os judeus que eram desobedientes, agitaram as mentes dos gentios e incitaram-os contra os irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Assim, eles permaneceram lá por um longo tempo, falando ousadamente no Senhor, enquanto Ele dava evidência sobre a mensagem da Sua graça, concedendo que sinais e maravilhas fossem realizados por meio de Paulo e Barnabé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Porém, a maioria da cidade estava dividida: algumas pessoas com os judeus e outras, com os apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Gentios e judeus decidiram com seus chefes, recorrer à violência e apedrejar os apóstolos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'ao saberem disso, eles fugiram para as cidades de Licaônia, Listra e Derbe, e a região ao redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'Lá também anunciaram o Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Em Listra encontrava-se um certo homem sentado, sem força nos pés, aleijado desde nascença, que nunca havia andado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Esse homem ouviu Paulo falando. Paulo fixou seus olhos nele e viu que ele tinha fé para ser curado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Então, Paulo lhe disse em alta voz: \"Levanta-te e firma teus pés\". Assim o homem pulou e começou a andar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Quando a multidão viu o que Paulo havia feito, levantaram suas vozes dizendo no dialeto da licaônia: \"Os deuses vieram até nós em forma de homens\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Eles chamaram Barnabé de Zeus e Paulo de Hermes, porque era ele quem falava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'O sacerdote de Zeus, cujo templo ficava em frente à cidade, trouxe touros e grinaldas aos portões; ele e as multidões queriam oferecer-lhes sacrifícios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Mas, quando os apóstolos Barnabé e Paulo, ouviram isto, rasgaram suas roupas e foram rapidamente para o meio da multidão, clamando');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'e dizendo: \"Homens, por que fazeis essas coisas?\" Nós também somos seres humanos iguais a vós. Trazemos boas novas para que vos afasteis dessas coisas inúteis, e vos volteis para o Deus vivo que criou os céus, a terra, o mar e todas as coisas que neles há.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Nos tempos antigos, Ele permitiu que todas as nações andassem em seus próprios caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Contudo Ele não deixou a Si mesmo sem testemunho, fazendo o bem, vos deu as chuvas do céu e estações frutíferas, enchendo vossos corações com comida e alegria\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Mesmo com essas palavras, Paulo e Barnabé com muita dificuldade conseguiram impedir que as multidões lhes oferecessem sacrifícios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Porém, alguns judeus de Antioquia e Icônio vieram e persuadiram as multidões. Eles apedrejaram Paulo e arrastaram-no para fora da cidade, pensando que estava morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Estando ainda os discípulos ao seu redor, ele se levantou e entrou na cidade. No dia seguinte, partiu com Barnabé para Derbe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Após terem pregado o Evangelho naquela cidade e feito muitos discípulos, retornaram para Listra, Icônio e Antioquia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Continuaram fortalecendo as mentes dos discípulos e os encorajando a perseverar na fé. Eles lhes disseram que é por meio de muitos sofrimentos que entraríamos no Reino de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'E designando-lhes presbíteros em cada igreja, tendo orado e jejuado, os confiaram ao Senhor, no qual haviam crido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Então, passando pela Pisídia, chegaram a Panfília.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'E, anunciado a Palavra em Perge, desceram à Atália.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Dali, navegaram para Antioquia, onde havia sido comissionados à graça de Deus para a obra que acabavam de completar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Quando chegaram em Antioquia e reuniram a igreja, relataram todas as coisas que Deus havia feito por meio deles, e como abrira a porta de fé aos gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Eles permaneceram por um longo tempo com os discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Certos homens desceram da Judéia e ensinavam aos irmãos dizendo: \"A menos que sejais circuncidados segundo o costume de Moisés, não sereis salvos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Tendo Paulo e Barnabé uma grande dissensão e debate com eles, os irmãos decidiram que Paulo, Barnabé e alguns outros deveriam subir a Jerusalém, para levar essa questão aos apóstolos e presbíteros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Por causa disso, sendo enviados pela igreja, passando pela Fenícia e Samaria, anunciaram a conversão dos gentios e trouxeram grande alegria a todos os irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Quando chegaram a Jerusalém, foram recebidos pela igreja, pelos apóstolos e pelos presbíteros e reportaram-lhes todas as coisas que Deus havia feito por meio deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Entretanto, alguns homens do grupo dos fariseus que creram se levantaram e disseram: \"É necessário que eles sejam circuncidados e que sejam ordenados a obedecer a lei de Moisés\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Os apóstolos e presbíteros se reuniram para tratar esse assunto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Depois de muito debater, Pedro se levantou e disse-lhes: \"Irmãos, vós sabeis que há algum tempo atrás, Deus fez uma escolha entre vós, que através da minha boca os gentios ouviriam a palavra do Evangelho, e creriam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Deus, que conhece o coração, testemunhou a favor deles, dando-lhes o Espírito Santo, assim como a nós;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'e não fez distinção entre nós e eles, purificando-lhes o coração pela fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Então, por que tentais a Deus, impondo aos discípulos um fardo que nem nós e nem vossos pais puderam suportar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Cremos, entretanto, que seremos salvos pela graça do Senhor Jesus, assim como eles foram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Toda a multidão ficou em silêncio enquanto eles ouviam Barnabé e Paulo falar dos sinais e maravilhas que Deus tinha operado entre os gentios através deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Depois que terminaram de falar, Tiago respondeu, dizendo: \"Irmãos, ouvi-me\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simão relatou como Deus primeiro ajudou graciosamente os gentios, a fim de tomar dentre eles um povo para o Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'As palavras dos profetas concordam com isso, como está escrito:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '\"Depois dessas coisas, Eu voltarei e reconstruirei a tenda de Davi, que foi destruída. Eu novamente levantarei e restaurarei as suas ruínas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'para que o restante dos homens busque ao Senhor, incluindo todos os gentios chamados pelo Meu Nome\",');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'diz o Senhor, que tem feito essas coisas conhecidas desde a antiguidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Portanto, minha decisão é que não devemos perturbar os gentios que se voltam para Deus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'mas lhes escrever para se guardarem da contaminação dos ídolos, da fornicação, de comer animais estrangulados e do sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Porque, desde muitas gerações, Moisés tem sido pregado todos os sábados, nas sinagogas de todas as cidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Então, pareceu bem aos apóstolos e aos presbíteros, com toda a igreja, escolher Judas, chamado Barsabás, e Silas, que eram líderes da igreja, e os enviar para Antioquia, com Paulo e Barnabé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Assim escreveram: \"Os apóstolos, presbíteros e irmãos, aos irmãos gentios em Antioquia, Síria e Cilícia, saudações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Ouvimos que certos homens, aos quais não havíamos dado nenhuma ordem, se desviaram de nós, e têm-vos perturbado com palavras, confundindo vossas almas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Pareceu-nos bem, tendo chegado a uma decisão, escolher homens e enviá-los até vós juntamente com nossos amados Barnabé e Paulo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'homens que têm arriscado suas vidas pelo Nome de nosso Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Enviamos, portanto, Judas e Silas, que também contarão as mesmas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Pois pareceu bem ao Espírito Santo e a nós não colocar sobre vós fardos maiores do que estas coisas necessárias:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'que se mantenham distantes de coisas sacrificadas aos ídolos, sangue, animais estrangulados e imoralidade sexual. Se vos guardardes dessas coisas, tudo estará bem com vós. Adeus!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Então eles, depois de dispensados, desceram à Antioquia e, reunindo a multidão, entregaram a carta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Quando eles a leram, alegraram-se muito por causa do encorajamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Judas e Silas, também profetas, encorajaram e fortaleceram os irmãos com muitas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Após terem passado algum tempo ali, foram enviados em paz de volta aos irmãos que os havia enviado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Porém, Paulo e Barnabé ficaram em Antioquia junto com muitos outros, onde ensinavam e pregavam a palavra do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Após alguns dias, Paulo disse a Barnabé: \"Vamos retornar agora para visitar os irmãos em cada cidade onde proclamamos a Palavra do Senhor e vejamos como estão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnabé também queria levar João, chamado Marcos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'mas Paulo não achou bom o levar, pois, desde a Panfília, havia se afastado deles e não os seguira na obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Então, surgiu tamanha divergência que se separaram um do outro, e Barnabé tomou consigo Marcos e navegou para Chipre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Contudo, Paulo escolheu a Silas e partiu, após ter sido confiado pelos irmãos à graça do Senhor;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'e passou pela Síria e Cilícia, fortalecendo as igrejas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Paulo também foi para Derbe e Listra; e havia ali um certo discípulo chamado Timóteo, filho de uma mulher judia cristã; seu pai era grego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'E os irmãos que estavam em Listra e Icônio davam bom testemunho dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Paulo queria que ele o acompanhasse; então, tomou-o e o circuncidou por causa dos judeus que estavam naqueles lugares, pois todos sabiam que seu pai era grego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Enquanto seguiam seu caminho pelas cidades, davam às igrejas ordenanças para que obedecessem, as quais foram escritas pelos apóstolos e presbíteros de Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Assim, as igrejas eram fortalecidas na fé e cresciam em número dia após dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Paulo e seus companheiros percorreram as regiões de Frígia e Galácia, uma vez que foram impedidos pelo Espírito Santo de pregar a Palavra na Ásia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Quando se aproximaram de Mísia, tentaram adentrar em Bitínia, mas o Espírito de Jesus os impediu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Então passando pela Mísia, desceram à cidade de Trôade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Durante a noite, Paulo teve uma visão: um homem da Macedônia estava em pé, chamando-o e dizendo: \"Vem para a Macedônia e ajuda-nos!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Assim que Paulo teve a visão, imediatamente partimos para a Macedônia, concluindo que Deus tinha nos chamado para pregar-lhes o Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Portanto, partindo de Trôade, navegamos direto para Samotrácia e, no dia seguinte, para Neápolis;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'de lá, seguimos para Filipos, cidade da Macedônia, a mais importante do distrito e uma colônia romana e ali ficamos por vários dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'No dia de sábado, fomos para fora dos portões junto ao rio, onde pensamos ser um lugar de oração. Nós nos sentamos e falamos às mulheres que vieram juntas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Certa mulher chamada Lídia, vendedora de púrpura, da cidade de Tiatira, que adorava a Deus, nos ouviu. O Senhor abriu o seu coração para prestar atenção às coisas que Paulo dizia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Após ter sido batizada, ela e toda a sua casa, insistiu dizendo: \"Se vós julgais que sou fiel ao Senhor, entrai em minha casa e ficai ali\". E persuadiu-nos a isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Aconteceu que, conforme íamos ao lugar de oração, uma certa jovem, que tinha um espírito de adivinhação, nos encontrou. Ela dava grande lucro ao seus patrões através da adivinhação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Essa mulher seguia a Paulo e a nós e gritava dizendo: \"Estes homens são servos do Deus Altíssimo. Eles vos proclamam o caminho da salvação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Ela fez isto por muitos dias. Mas Paulo, ficando demasiadamente aborrecido por ela, voltou-se e disse ao espírito: \"Eu te ordeno, no Nome de Jesus, saia dela\". E o espírito saiu imediatamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Quando os patrões da mulher viram que a esperança dos seus ganhos tinha ido embora, amarraram Paulo e Silas e os levaram para dentro do mercado, diante das autoridades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Quando lhes trouxeram para os oficiais do governo, disseram: \"Estes homens são judeus e estão causando vários problemas na nossa cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'Eles estão ensinando costumes que não são permitidos aos romanos receber ou observar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Então, toda a multidão se levantou contra Paulo e Silas; e os magistrados, rasgando-lhes as roupas, ordenaram que fossem açoitados com varas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Após tê-los açoitado várias vezes, jogaram-nos na prisão e ordenaram ao carcereiro que os mantivessem seguros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Depois de receber essa ordem, o carcereiro os lançou na prisão interior e prendeu seus pés no tronco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Por volta da meia noite, Paulo e Silas oravam e cantavam hinos a Deus, e os outros prisioneiros os ouviam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Repentinamente, houve um grande terremoto, e os alicerces da prisão foram abalados; e imediatamente todas as portas foram abertas, e as correntes de todos foram soltas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'O carcereiro despertou do sono, e viu abertas as portas da prisão; tomou sua espada, e estava prestes a se matar, porque pensou que os prisioneiros tinham escapado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Mas Paulo gritou em alta voz, dizendo: \"Não te mates, porque estamos todos aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'O carcereiro pediu luzes; apressadamente entrou e, tremendo de medo, prostrou-se diante de Paulo e Silas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'e os levou para fora e disse: \"Senhores, o que eu devo fazer para ser salvo?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Eles disseram: \"Crê no Senhor Jesus e serás salvo, tu e a tua casa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Pregaram a Palavra do Senhor para ele, juntos com todos em sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Então o carcereiro os tomou naquela mesma hora da noite, lavou suas feridas, e ele e toda a sua casa foram imediatamente batizados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Ele levou Paulo e Silas para dentro de sua casa e pôs comida diante deles; e alegrou-se grandemente com toda a sua casa, porque ele creu em Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Quando amanheceu, os magistrados ordenaram aos guardas dizendo: \"Deixa aqueles homens irem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'O carcereiro mencionou as palavras a Paulo, dizendo: \"Os magistrados me ordenaram para deixar-vos ir; portanto, saí e ide em paz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Porém, Paulo lhes disse: \"Sendo nós cidadãos romanos, publicamente nos açoitaram, sem sermos condenados, e nos lançaram na prisão; e agora querem nos soltar em segredo? De forma alguma! Que eles mesmos venham e nos tirem daqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Os guardas reportaram essas palavras para os magistrados; e eles ficaram temerosos quando ouviram que Paulo e Silas eram romanos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'Os magistrados vieram e se desculparam com eles e, quando os tiraram da prisão, pediram para que Paulo e Silas deixassem a cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Então, Paulo e Silas saíram da prisão e foram à casa de Lídia. Quando viram os irmãos, eles os encorajaram e assim partiram da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Tendo percorrido as cidades de Anfípolis e Apolônia, chegaram a Tessalônica, onde havia uma sinagoga dos judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Paulo, como era de seu costume, foi até lá e, por três sábados, debateu com eles acerca das Escrituras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Abrindo as Escrituras, explicava que era necessário que o Cristo sofresse e ressuscitasse dentre os mortos. E dizia: \"Esse Jesus que vos proclamo é o Cristo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Alguns dos judeus foram persuadidos e se juntaram a Paulo e Silas, incluindo uma grande quantidade de devotos gregos, e muitas das mulheres influentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Entretanto os judeus incrédulos, movidos por ciúmes, tomando homens ímpios do mercado, juntaram a multidão e tumultuaram a cidade. Assaltando a casa de Jasom, queriam trazer Paulo e Silas até o povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Porém, não os tendo encontrado, arrastaram Jasom e alguns outros irmãos perante as autoridades da cidade, e exclamavam: \"Esses homens, que têm virado o mundo de cabeça para baixo, chegaram também aqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Esses, a quem Jasom tem recebido, procedem contra os decretos de César e dizem que existe outro Rei, Jesus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Quando a multidão e as autoridades da cidade ouviram essas coisas, ficaram perturbados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Após receberem fiança de Jasom e dos outros, eles os libertaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Naquela noite, os irmãos enviaram Paulo e Silas para Bereia. Chegando lá, foram à sinagoga dos judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Em Bereia, as pessoas eram mais nobres que as de Tessalônica, pois receberam a Palavra com toda disposição de mente, diariamente examinando as Escrituras, para ver se de fato as coisas eram assim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Por isso muitos deles creram, incluindo algumas mulheres gregas influentes e muitos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Todavia, quando os judeus de Tessalônica descobriram que Paulo estava proclamando a Palavra de Deus em Bereia, foram até lá para incitar e acirrar as multidões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Imediatamente, os irmãos enviaram Paulo para o litoral, mas Silas e Timóteo permaneceram ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Aqueles que guiavam Paulo levaram-no até a cidade de Atenas e regressaram, trazendo dele instruções para que Silas e Timóteo fossem até ele o mais rápido possível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Enquanto Paulo esperava por eles em Atenas, seu espírito se indignou quando viu a cidade cheia de ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Então debatia na sinagoga com os judeus e com aqueles que adoravam a Deus, e também com os que ele encontrava todos os dias no mercado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Contudo alguns dos filósofos epicureus e estoicos, também debatendo com ele, diziam: \"O que esse tagarela está tentando dizer?\". Outros diziam: \"Parece ser um pregador de deuses estranhos\", porque ele anunciava sobre Jesus e a ressureição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Tomaram a Paulo e o levaram até o Areópago, dizendo: \"Podemos saber sobre esse novo ensino que tu tens falado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Pois tu trazes algo estranho aos nossos ouvidos. Portanto queremos saber o que essas coisas significam\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, '(Todos os atenienses e estrangeiros que ali viviam não gastavam seu tempo com nada além de contar ou ouvir sobre novidades).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Então Paulo ficou de pé no meio do Areópago e disse: \"Homens atenienses, vejo que sois muito religiosos em todas as maneiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Pois, passando eu e observando os objetos de vossa adoração, encontrei um altar com a seguinte inscrição: \"AO DEUS DESCONHECIDO\". Pois bem, Aquele que adorais sem saber quem é, a Este vos anuncio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'O Deus que criou o mundo e tudo o que nele há, Senhor do céu e da terra, não habita em templos construídos por mãos de homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Tampouco é servido por mãos de homens, como se precisasse de coisa alguma, visto que Ele mesmo dá às pessoas vida, respiração e todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'E de um só homem Ele criou toda a raça humana que habita na face da terra, tendo-lhes determinado os tempos e o limite da sua habitação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Portanto eles deveriam buscar a Deus e, tateando, talvez pudessem encontrá-Lo e descobri-Lo, embora Ele não esteja longe de cada um de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Pois Nele vivemos, nos movemos e existimos, como alguns dos vossos poetas disseram: \'Somos também geração Dele\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Sendo nós geração de Deus, não devemos pensar que a divindade é semelhante ao ouro, prata ou pedra — imagens criadas pela arte e imaginação do homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Assim sendo, Deus não levou em conta os tempos de ignorância, mas agora ordena que todos os homens, em todos os lugares, arrependam-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Pois determinou um dia em que julgará o mundo em justiça por meio do Homem que Ele escolheu. Deus deu prova desse Homem a todos, ressuscitando-O dentre os mortos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Quando os homens de Atenas ouviram sobre a ressureição dos mortos, alguns zombaram de Paulo, mas outros diziam: \"Nós te ouviremos novamente sobre esse assunto\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Depois disso, Paulo os deixou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Alguns homens, porém, juntaram-se a ele, e creram, incluindo Dionísio, membro do Conselho do Areópago, e uma mulher chamada Dâmaris, e com eles ainda outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Depois dessas coisas, Paulo deixou Atenas e foi para Corinto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Encontrou ali certo judeu chamado Áquila, natural do Ponto, que recentemente tinha vindo da Itália com sua esposa Priscila, pois Cláudio havia ordenado que todos os judeus deixassem Roma. Paulo foi até eles');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'e, porque tinham o mesmo ofício, Paulo ficou e trabalhou com eles, porque faziam tendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Paulo debatia na sinagoga todo sábado, persuadiando tanto judeus como gregos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Contudo, quando Silas e Timóteo desceram da Macedônia, Paulo foi impulsionado pelo Espírito para testificar aos judeus que Jesus era o Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Quando os judeus se opuseram a ele e o insultaram, Paulo sacudiu suas vestes e disse-lhes: \"Que o vosso sangue esteja sobre vossas próprias cabeças; eu sou inocente. De agora em diante, irei para os gentios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Saindo dali, foi para a casa de Tito Justo, um homem que adorava a Deus. Sua casa era próxima da sinagoga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Crispo, o chefe da sinagoga, e toda sua casa creu no Senhor. Muitos dos coríntios que ouviram Paulo também creram e foram batizados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'O Senhor disse a Paulo durante a noite numa visão: \"Não tenhas medo, mas fales e não te cales.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Pois estou contigo, e ninguém te atacará, pois tenho muitos nesta cidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Paulo morou ali por um ano e seis meses, ensinando a Palavra de Deus entre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Porém, quando Gálio se tornou governador da Acaia, os judeus juntaram-se contra Paulo e o levaram ao tribunal;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'e disseram: \"Este homem persuade as pessoas a adorar a Deus, contrariando a lei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Quando Paulo estava prestes a falar, Gálio disse aos judeus: \"De fato, judeus, se houvesse algum crime ou problema grave, seria razoável tratar convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Mas como são questões de palavras e nomes e da vossa própria lei, resolvei isso vós mesmos, não quero ser juiz nestas questões!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Gálio mandou que saíssem do tribunal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Contudo, pegaram Sóstenes, o chefe da sinagoga, à força, e o espancaram diante do tribunal. Entretanto, Gálio não se importou com o que fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Depois de passar alguns dias ali, Paulo deixou os irmãos e navegou para Síria, com Priscila e Áquila. Antes de deixar o porto, em Cencreia, ele raspou a cabeça porque havia feito um voto de nazireu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Quando chegaram a Éfeso, Paulo deixou Priscila e Áquila ali; porém, ele mesmo foi para a sinagoga e debatia com os judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Quando pediram a Paulo que ficasse mais tempo, ele negou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Mas, despedindo-se deles, disse: \"Voltarei para vós se esta for a vontade de Deus\". Então partiu de Éfeso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Quando Paulo desembarcou em Cesareia, subiu a Jerusalém, e, saudando a igreja, desceu para Antioquia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Após passar algum tempo ali, partiu e passou pelas regiões da Galácia e da Frígia, e encorajou todos os discípulos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Havia certo judeu chamado Apolo, nascido em Alexandria, que veio a Éfeso. Ele era eloquente e poderoso nas Escrituras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Apolo foi instruído nos ensinos do Senhor. Sendo fervoroso de espírito, falava e ensinava acuradamente as coisas concernentes a Jesus; porém, ele conhecia apenas o batismo de João.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Apolo começou a falar ousadamente na sinagoga. Entretanto, quando Priscila e Áquila o ouviram, levaram-no consigo e lhe explicaram o caminho de Deus com mais exatidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Querendo passar pela Acaia, os irmãos o encorajaram e escreveram aos discípulos na Acaia que o recebessem. Quando ele chegou, ajudou imensamente aqueles que haviam crido pela graça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Apolo publicamente vencia os judeus com seu poder e habilidade, mostrando pelas Escrituras que Jesus era o Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Enquanto Apolo estava em Corinto, Paulo passou pelas regiões altas e veio para a cidade de Éfeso e encontrou alguns discípulos ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Paulo perguntou-lhes: \"Recebestes o Espírito Santo quando crestes?\". Eles responderam: \"Não, não recebemos. Nem fomos informados de que existe um Espírito Santo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Paulo disse: \"Em que batismo fostes batizados, então?\". Eles responderam: \"No batismo de João.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Paulo disse: \"João batizou com batismo de arrependimento, dizendo às pessoas que deveriam crer Naquele que viria após ele, isto é, em Jesus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Quando ouviram isso, foram batizados no Nome do Senhor Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Então, Paulo lhes impôs as mãos, e o Espírito Santo veio sobre eles, e falaram em outras línguas e profetizaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Ao todo, foram cerca de doze homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Paulo foi à sinagoga e falou fervorosamente durante três meses. Ele liderava discussões e persudia as pessoas acerca das coisas concernentes ao reino de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'No entanto alguns judeus endurecidos e desobedientes começaram a falar mal do caminho de Cristo diante da multidão. Paulo os deixou e guiou seus discípulos para longe deles. Ele começou a falar todos os dias na escola de Tirano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Isso continuou por dois anos, e assim todos os que viviam na Ásia ouviram a Palavra do Senhor, tanto judeus como gregos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Deus estava fazendo obras poderosas pelas mãos de Paulo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'e até mesmo os doentes eram curados, e os espíritos malignos saíam deles, quando pegavam lenços e aventais do corpo de Paulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Porém havia judeus exorcistas viajando por aquela área, os quais usavam o nome de Jesus sobre aqueles possuídos de espíritos malignos, dizendo: \"Eu vos expulso no nome de Jesus, a quem Paulo prega\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Aqueles que fizeram isso eram os sete filhos de Ceva, principal dos sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Entretanto o espírito maligno respondeu: \"Conheço Jesus e sei quem é Paulo, mas vós, quem sois?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'O homem que estava possuído pelo espírito maligno saltou sobre os exorcistas e, subjulgando-os, espancou-os, de maneira que eles fugiram da casa, nus e feridos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Isso se tornou conhecido de todos, tanto judeus como gregos que viviam em Éfeso. Temor caiu sobre todos eles, e o Nome de Jesus estava sendo glorificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Muitos dos cristãos vinham, confessavam e admitiam suas obras más.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Muitos dos que praticavam artes mágicas juntavam seus livros e os traziam para queimar diante de todos. E, ao contarem o valor dos livros, chegaram à quantia de cinquenta mil peças de prata.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Assim a Palavra do Senhor crescia poderosamente de várias maneiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Quando Paulo terminou seu trabalho em Éfeso, decidiu em espírito ir a Jerusalém, porém planejava antes ver os cristãos nas regiões da Macedônia e da Acaia. Disse Paulo: \"Depois de ir a Jerusalém, irei também a Roma\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Ele enviou dois de seus colaboradores, Timóteo e Erasto, à Macedônia. Entretanto Paulo permaneceu na cidade de Éfeso, na província da Ásia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Naquele mesmo tempo, levantou-se um grande alvoroço em Éfeso acerca do Caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Certo ourives de prata chamado Demétrio, que fazia nichos de Diana, dava muito lucro para os artifíces.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Então, reunindo os artifíces do mesmo tipo de serviço, disse: \"Senhores, vós bem sabeis que obtemos muito lucro deste negócio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'E bem vedes e ouvis que não somente em Éfeso, mas praticamente por toda a Ásia, esse Paulo tem persuadido e afastado muitas pessoas. Ele está dizendo que não há deuses feitos por mãos humanas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Não há somente o perigo de nossa profissão ficar desacreditada, mas até mesmo o templo da nossa grande deusa Diana poderá vir a ser estimado como nada. Assim ela perderia sua grandeza, aquela a quem toda a Ásia e o mundo adoram\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Quando ouviram isso, enfureceram-se e gritaram, dizendo: \"Grande é a Diana dos Efésios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Toda a cidade encheu-se de confusão, e todas as pessoas correram juntas para o teatro. Eles arrastaram os companheiros de Paulo, Gaio e Aristarco, que vieram da Macedônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Paulo queria entrar no meio do povo, porém os discípulos não permitiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Também alguns dos oficiais da província da Ásia, que eram seus amigos, enviaram-lhe uma mensagem rogando que não entrasse no teatro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Alguns clamavam de uma maneira, outros de outra, pois a multidão estava confusa. Muitos deles não sabiam nem porque estavam reunidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Os judeus tiraram Alexandre para fora da multidão, trazendo-o diante das pessoas. Alexandre, acenando com a mão, queria dar uma explicação ao povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Entretanto, quando perceberam que ele era judeu, gritaram em alta voz por cerca de duas horas: \"Grande é a Diana dos Éfesios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Então o escrivão da cidade, aquietando a multidão, disse: \"Homens de Éfeso, qual é o homem que não sabe que a cidade dos efésios é a guardiã do templo da grande Diana e da sua imagem que caiu do céu?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Vendo, então, que essas coisas são inegáveis, convém que vos aquieteis e nada façais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Pois trouxestes esses homens a esta corte, os quais não são ladrões do templo, nem blasfemam contra nossa deusa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Portanto, se Demétrio e os artifíces que estão com ele têm alguma acusação contra alguém, há cortes e magistrados. Que acusem uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Contudo, se demandais qualquer coisa concernente a outros assuntos, deverá ser averiguada em assembleia legítima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Na verdade, até corremos perigo de sermos acusados deste tumulto. Não há causa para esta desordem, a qual não poderemos explicar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'Após ter dito isso, ele desfez a assembleia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Cessado o tumulto, Paulo chamou os discípulos, e encorajou-os; então, despediu-se deles e partiu para a Macedônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Passando ele por aquelas regiões, encorajava bastante os cristãos dessas áreas; e chegou à Grécia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Depois de passar três meses ali, alguns judeus conspiraram contra ele no momento em que estava prestes a embarcar para a Síria; então, ele decidiu voltar pela Macedônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Acompanhando-o até a Ásia estavam: Sópatro, filho de Pirro de Bereia; Aristarco e Secundo, ambos de Tessalônica; Gaio de Derbe; Timóteo; além de Tíquico e Trófimo da Ásia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Contudo, esses homens foram antes e nos esperaram em Trôade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Navegamos de Filipos após a Festa dos Pães sem Fermento, e, cinco dias depois, nos reunimos com eles em Trôade. Ali ficamos por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'No primeiro dia da semana, quando estávamos reunidos para partir o pão, Paulo falou ao povo, ele pretendia partir no dia seguinte, então, continuou pregando até meia noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Havia muitas candeias no aposento superior, onde estávamos reunidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Assentado numa janela estava um jovem chamado Êutico que caiu num sono profundo. Conforme Paulo estendeu o discurso, esse jovem, ainda dormindo, caiu do terceiro andar, e, quando o levantaram, estava morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Entretanto, Paulo desceu, inclinou-se sobre o rapaz, abraçou-o e disse: \"Não vos pertubeis, pois ele está vivo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'E, subindo, partindo o pão, comeu e falou-lhes por muito tempo, até o amanhecer e partiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'E levaram de volta o rapaz vivo, o que muito os confortou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Nós mesmos fomos à frente de Paulo, de navio, e navegamos até Assôs, onde receberíamos Paulo à bordo; assim como ele mesmo havia determinado, pois planejara ir por terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Quando o encontramos em Assôs, recebemos-lo a bordo e fomos para Mitilene.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Então, navegamos dali e, no dia seguinte, chegamos ao lado oposto da ilha de Quios. No outro dia, chegamos à ilha de Samos, e um dia depois chegamos a cidade de Mileto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Paulo havia decidido não aportar em Éfeso, a fim de não desperdiçar muito tempo na Ásia, pois estava apressado para chegar em Jerusalém no dia de Pentecostes, se de alguma maneira lhe fosse possível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'De Mileto, ele enviou homens a Éfeso, e mandou chamar os presbíteros da igreja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Quando chegaram, ele lhes disse: \"Vós mesmos sabeis, desde o primeiro dia que pisei na Ásia, como sempre passei meu tempo convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Segui servindo ao Senhor com toda a humildade e com lágrimas, e em sofrimentos que me aconteceram por causa das conspirações dos judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Vós sabeis que não deixei de pregar-vos nada que não fosse proveitoso, como vos ensinei em público e também de casa em casa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'testificando tanto a judeus como a gregos sobre o arrependimento diante de Deus e a fé em nosso Senhor Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'E agora, compelido pelo Espírito, vou para Jerusalém, sem saber as coisas que me acontecerão ali,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'exceto o que o Espírito Santo me testifica que, em toda cidade, prisões e sofrimentos me esperam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Contudo, não considero minha vida preciosa para mim mesmo, se eu puder tão somente terminar a corrida e o ministério que recebi do Senhor Jesus, para dar testemunho do Evangelho da graça de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'E agora sei que nenhum de vós, dentre os quais passei pregando o Reino, jamais vereis minha face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Portanto, hoje vos testifico que sou inocente do sangue de qualquer homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Pois não vos deixei de declarar todo o conselho de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Portanto, cuidai de vós mesmos e de todo o rebanho sobre o qual o Espírito Santo vos fez bispos, para pastoreardes a igreja do Senhor, a qual Ele comprou com Seu próprio sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Sei que após a minha partida, lobos ferozes entrarão no meio de vós, e não pouparão o rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'E sei que mesmo dentre vós, alguns homens se levantarão e perverterão a verdade, a fim de afastar os discípulos e atraí-los para si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Portanto, vigiai, lembrando-vos que durante três anos não parei de instruir e advertir cada um de vós com lágrimas dia e noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Agora, encomendo-vos a Deus e à Palavra da Sua graça, que é capaz de vos edificar e dar-vos heranças entre todos que estão sendo santificados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Não cobicei prata, nem ouro ou roupas de homem algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Vós sabeis que estas mãos serviram às minhas necessidades e às necessidades daqueles que estavam comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Em todas as coisas, dei-vos exemplo de como ajudar os fracos trabalhando, e como deveis lembrar das palavras do Senhor Jesus, palavras que Ele mesmo disse: \"Mais bem-aventurado é dar do que receber\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Depois de ter falado, ajoelhou-se e orou com todos eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Todos choraram muito e, abraçando Paulo, o beijaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Eles estavam tristes principalmente por causa do que ele lhes dissera, que nunca mais veriam sua face novamente. Então o acompanharam até ao navio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Depois que nos separamos deles, navegamos em uma rota direta à cidade de Cós e, no dia seguinte a Rodes, e depois para a cidade de Pátara.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Encontrando um navio partindo para a Fenícia, embarcamos nele e seguimos viagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Avistando a ilha de Chipre, deixando-a à esquerda, navegamos para a Síria e aportamos na cidade de Tiro, pois o navio seria descarregado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Após ter encontrado os discípulos, permanecemos com eles por sete dias. Os discípulos, através do Espírito, disseram a Paulo que não subisse a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Depois de completarmos os dias, deixamos aquele lugar e seguimos viagem. Todos eles nos acompanharam em nosso caminho para fora da cidade juntamente com suas esposas e filhos. Então ajoelhamos na praia, oramos e nos despedimos uns dos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Embarcamos no navio e eles retornaram para suas casas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Concluída a nossa viagem de Tiro, chegamos a Ptolemaida; e, havendo saudado os irmãos, passamos um dia com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'No dia seguinte, partimos e fomos para Cesareia. Entramos na casa de Filipe, o evangelista, que era um dos sete, e permanecemos com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Esse homem tinha quatro filhas virgens que profetizavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Ficamos ali por alguns dias e aconteceu que um homem veio da Judeia, um certo profeta, chamado Ágabo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Ele veio até nós, tomou o cinto de Paulo, amarrou os próprios pés e mãos, e disse: \"Isso diz o Espírito Santo: \'Dessa forma os judeus em Jerusalém amarrarão o homem que possui este cinto, e o entregarão nas mãos dos gentios\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Quando ouvimos essas coisas, tanto nós como as pessoas que viviam naquele lugar, imploramos para que Paulo não subisse a Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Porém, Paulo respondeu: \"O que fazeis chorando e partindo meu coração? Estou pronto não apenas para ser amarrado, mas também para morrer em Jerusalém pelo nome do Senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'E como não persuadimos a Paulo, paramos de falar e simplesmente dissemos: \"Seja feita a vontade do Senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Depois destes dias, recolhemos nossa bagagem e fomos para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'E juntamente conosco alguns dos discípulos de Cesareia. Levando consigo um homem chamado Mnasom, natural de Chipre, um discípulo antigo, com quem ficaríamos hospedados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'E chegando nós a Jerusalém, os irmãos nos acolheram alegremente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'No dia seguinte, Paulo partiu conosco para encontrar Tiago e todos os presbíteros que estavam ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'E, depois de cumprimentá-los, relatou uma a uma as coisas que Deus havia feito entre os gentios por meio de seu ministério.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Quando ouviram isso, louvaram ao Senhor e disseram-lhe: \"Tu vês, irmão, quantos milhares entre os judeus têm crido e todos estão determinados a guardar a Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Eles foram informados a seu respeito: que tens ensinado a todos os judeus que vivem entre os gentios a abandonar Moisés, a não circuncidar seus filhos e a não seguir os costumes antigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'O que devemos fazer? Eles certamente ouvirão que chegaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Faze como te dizemos agora: temos aqui quatro homens que fizeram um voto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Toma esses homens, purifica a ti mesmo com eles e paga suas despesas, para que raspem a cabeça. Assim todos saberão que, o que foi dito a seu respeito, é falso e que és também um guardador da lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Porém, a respeito dos gentios que creram, escrevemos e instruímos para que se abstenham do sacrifício a ídolos, do sangue, daquilo que é estrangulado e da imoralidade sexual\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Então Paulo tomou consigo esses homens, e no dia seguinte purificou-se com eles; foi ao templo, anunciando os dias da purificação, até que a oferta fosse feita por cada um deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Quando os sete dias estavam quase terminando, alguns judeus da Ásia viram Paulo no templo, e incitaram toda a multidão e puseram as mãos nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Eles estavam gritando: \"Homens de Israel, ajudem-nos. Esse homem tem ensinado a todos, em toda a parte, sobre coisas que vão contra a Lei e esse lugar. Também trouxe gregos para o templo e profanou esse santo lugar\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Porque haviam anteriormente visto Trófimo de Éfeso com ele na cidade e pensaram que Paulo o introduzira no templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Toda a cidade estava agitada e as pessoas correram juntas para agarrar a Paulo. Eles o arrastaram para fora do templo, e as portas imediatamente foram fechadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Enquanto tentavam matá-lo, essas notícias rapidamente chegaram ao comandante da guarda, de que Jerusalém estava toda em confusão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Imediatamente ele tomou soldados e centuriões e correu até a multidão. Quando as pessoas viram o comandante e os soldados, pararam de espancar Paulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Então ele aproximou-se, agarrou Paulo e ordenou que ele fosse preso com duas correntes. Perguntou quem ele era e o que havia feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Alguns na multidão gritavam uma coisa e outros, outra. Como o comandante não conseguia discernir coisa alguma por causa do barulho, ordenou que Paulo fosse levado para a fortaleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Quando chegaram às escadas, ele foi carregado pelos soldados por causa da violência da multidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Pois a multidão o seguia gritando: \"Mata-o!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Conforme Paulo estava para ser levado até a fortaleza, ele perguntou ao comandante: \"Posso dizer-lhe uma coisa?\"Ele respondeu: \"Falas grego?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Não és tu aquele egípcio que há um tempo atrás liderou uma rebelião e levou quatro mil assassinos ao deserto?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Paulo disse: \"Sou judeu, da cidade de Tarso, na Cilícia. Sou cidadão de uma cidade importante. Peço-te que me permitas falar ao povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Quando o comandante lhe deu permissão, Paulo levantou-se dos degraus e acenou ao povo com a mão. E quando houve um grande silêncio, falou-lhes na língua hebraica, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '\"Irmãos e pais, ouvi a minha defesa, que vos apresentarei agora\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Quando a multidão ouviu Paulo lhes falar na língua hebraica, ficaram em absoluto silêncio. E ele falou:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, '\"Sou judeu, nascido em Tarso da Cilícia, mas educado nessa cidade aos pés de Gamaliel. Fui instruído exatamente de acordo com a lei dos nossos antepassados. Sou zeloso para com Deus, assim como hoje todos vós sois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Persegui esse Caminho até a morte; prendendo ambos, homens e mulheres, e os lancei na prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'O sumo sacerdote e todos os anciãos também podem dar testemunho de que recebi cartas deles direcionadas aos irmãos em Damasco, a fim de viajar para lá. Eu devia trazer acorrentados para Jerusalém todos desse Caminho que ali estivessem, para que fossem punidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Aconteceu que, enquanto eu viajava, chegando próximo a Damasco, por volta do meio-dia, de repente, uma forte luz do céu começou a brilhar ao meu redor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Caí no chão e ouvi uma voz que me dizia: \'Saulo, Saulo, por que Me persegues\'?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Respondi: \'Quem és Tu, Senhor\'? Ele me disse: \'Eu sou Jesus de Nazaré, a quem tu persegues\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Aqueles que estavam comigo viram a luz, mas não entenderam a voz do que falou comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Eu disse: \'O que devo fazer Senhor\'? O Senhor me disse: \'Levanta-te, e vai a Damasco; ali te será dito o que deves fazer\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Eu não podia ver por causa do brilho daquela luz, então fui para Damasco, sendo guiado pelas mãos dos que estavam comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Ali encontrei um homem chamado Ananias, varão devoto de acordo com a Lei e de bom testemunho por todos os judeus que lá viviam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Ele veio até mim, parou em minha frente, e disse: \'Irmão Saulo, volta a enxergar\'. Naquela mesma hora eu o vi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Então ele disse: \'O Deus de nossos antepassados te escolheu para conhecer a Sua vontade, para ver O Justo, e para ouvir a voz que vem da Sua própria boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Porque serás Sua testemunha para todos os homens sobre o que tens visto e ouvido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'E agora o que estás esperando? Levanta-te, batiza-te e lava teus pecados, invocando o nome Dele\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Após ter retornado de Jerusalém, enquanto orava no templo, tive uma visão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'Eu O vi dizer a mim: \'Apressa-te e deixa Jerusalém, porque não aceitarão teu testemunho a Meu respeito\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Eu respondi: \'Senhor, eles mesmos sabem que prendi e açoitei em cada sinagoga aqueles que criam em Ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Quando o sangue de Estêvão, Tua testemunha, foi derramado, eu também estava presente, consentindo e guardando as vestes dos que o matavam\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Porém, Ele me disse: \'Vai, porque Te enviarei para longe aos gentios\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'As pessoas permitiram-lhe falar até esse ponto e, então, gritaram dizendo: \"Tira da terra tal indivíduo, porque não convém que ele viva\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Quando gritavam, jogavam suas roupas e poeira para o ar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'o chefe da guarda ordenou que Paulo fosse levado à fortaleza, ordenando que fosse interrogado sob açoites, para que soubesse o porquê de gritarem com ele dessa maneira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Quando eles o amarraram no tronco, Paulo disse ao centurião que estava presente: \"Será que tendes o direito de açoitar um cidadão romano sem ser condenado?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Quando o centurião ouviu isso, foi ao capitão chefe, e disse: \"O que estás para fazer? Pois esse homem é um cidadão romano\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'O capitão chefe veio e disse-lhe: \"Dize-me, és tu cidadão romano?\" Paulo disse: \"Sim!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'O capitão chefe respondeu: \"Com uma grande quantia de dinheiro, adquiri a cidadania\". Porém, Paulo disse: \"Eu nasci cidadão romano\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Então, os homens que estavam para interrogá-lo, imediatamente o soltaram. O capitão chefe também teve medo, quando ouviu que Paulo era cidadão romano, pois o tinha amarrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'No dia seguinte, o capitão chefe queria saber a verdade acerca das acusações dos judeus contra Paulo. Então, desataram suas amarras e ordenaram que os principais sacerdotes e todo o conselho dos judeus se reunissem. Assim, trazendo Paulo, apresentou-o diante deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Paulo olhou diretamente para os membros do conselho dos judeus e disse: \"Irmãos, tenho vivido diante de Deus com consciência pura até este dia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'O sumo sacerdote Ananias ordenou àqueles que estavam próximos a Paulo para que o ferissem na boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Então Paulo disse-lhe: \"Deus te ferirá, parede branqueada! Tu estás aí sentado para me julgar conforme a lei, mas ordena que me firam contra a lei?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Os que ali estavam disseram: \"Como tu insultas o sumo sacerdote de Deus\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Paulo disse: \"Eu não sabia, irmãos, que ele era o sumo sacerdote. Porque está escrito: \'Não falarás mal de uma autoridade do teu povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Quando Paulo viu que parte do conselho era de saduceus e outra parte era de fariseus, falou alto no conselho: \"Irmãos, eu sou um fariseu, filho de fariseus. E eu estou sendo julgado porque espero confiantemente a ressurreição dos mortos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Quando ele disse isso, iniciou-se uma discussão entre os fariseus e os saduceus, e a assembleia dividiu-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Porque os saduceus dizem que não há ressurreição, nem anjos, nem espíritos, enquanto os fariseus aceitam todas essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Assim ocorreu um grande alvoroço, e alguns dos escribas pertencentes aos fariseus levantaram-se e argumentaram, dizendo: \"Não encontramos nenhum mal neste homem. Quem sabe se foi um espírito ou um anjo que falou com ele\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Havendo uma grande discussão, o comandante temia que Paulo fosse despedaçado por eles. Então ordenou aos soldados que descessem e retirassem Paulo à força de entre os membros do conselho e o trouxessem para a fortaleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Na noite seguinte, o Senhor esteve ao seu lado e disse: \"Sê corajoso, pois como testemunhaste de mim em Jerusalém, assim também é necessário que testemunhes em Roma\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Ao amanhecer, alguns judeus juraram e, sob pena de uma maldição sobre si mesmos, disseram que não comeriam nem beberiam qualquer coisa até que matassem Paulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Eram mais de quarenta os que fizeram essa conspiração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Eles foram aos principais sacerdotes e aos anciãos e disseram-lhes: \"Juramos, sob pena de maldição, não comermos nada até que tenhamos matado Paulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Agora, portanto, informai ao comandante juntamente com o consellho para que vos traga Paulo, como se fôsseis investigar o caso dele com mais precisão. Quanto a nós, estamos preparados para matá-lo antes que ele chegue aqui\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Mas o sobrinho de Paulo, ouvindo que eles estavam armando uma cilada, entrou na fortaleza e informou a Paulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Paulo chamou um dos centuriões e disse: \"Leva este jovem ao comandante, porque ele tem algo para contar-lhe\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Então o centurião tomou o jovem e o levou ao comandante e disse: \"Paulo, o prisioneiro, chamou-me até ele, e pediu-me para trazer-lhe este jovem. Ele tem algo para dizer-te\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'O comandante o levou pela mão a um local privado e perguntou-lhe: \"O que tens para comunicar-me\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'O jovem disse: \"Os judeus combinaram solicitar-te que leves Paulo amanhã, ao conselho, como se fosses interrogá-lo com mais precisão sobre o seu caso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Porém não lhes dê ouvidos, pois há mais de quarenta homens emboscados para matá-lo. Eles juraram, sob pena de maldição sobre si mesmos, que não comeriam e nem beberiam até que o tenham matado. Mesmo agora, já estão de prontidão, aguardando pelo seu consentimento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Então o comandante deixou o jovem sair, após instruí-lo: \"Não contes a ninguém que você me disse essas coisas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Então ele chamou dois dos centuriões e disse: \"Deixai de prontidão, desde a hora terceira da noite, duzentos soldados de infantaria, setenta de cavalaria e duzentos lanceiros, para irem até Cesareia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Ele também ordenou-lhes para preparar montarias para que Paulo pudesse viajar e ser conduzido em segurança ao governador Félix.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Assim ele escreveu uma carta:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '\"Cláudio Lísias ao excelentíssimo governador Félix. Saudações!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Este homem foi preso pelos judeus e estava prestes a ser morto por eles, quando cheguei com soldados e o resgatei, ao descobrir que ele era cidadão romano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Querendo saber por que eles o acusavam, então o levei perante o conselho deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Descobri que ele estava sendo acusado de questões relativas as suas próprias leis, mas não havia acusações contra ele que merecesse morte ou prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Também descobri que havia uma conspiração contra este homem. Assim enviei-o imediatamente para ti e instruí os seus acusadores a apresentarem as acusações na tua presença. Saudações\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Então os soldados obedeceram as suas ordens: eles apanharam Paulo e o levaram durante a noite para Antipátride.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'No dia seguinte, os soldados de cavalaria foram com Paulo e os demais soldados retornaram à fortaleza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Quando os cavaleiros chegaram à Cesareia e entregaram a carta ao governador, também apresentaram-lhe Paulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Quando o governador leu a carta, perguntou de qual província Paulo era. Quando ouviu que ele era da Cilícia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'disse-lhe: \"Ouvir-te-ei quando os teus acusadores chegarem aqui\". Então ele ordenou que Paulo fosse mantido no Palácio de Herodes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Cinco dias depois, Ananias o sumo sacerdote, alguns presbíteros e um advogado chamado Tértulo desceram até Cesareia. Esses homens trouxeram acusações contra Paulo ao governador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Quando Paulo estava diante do governador, Tértulo começou a acusá-lo dizendo: \"Governador, por tua causa temos grande paz, e por tua providência trazes boas reformas para nossa nação;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'assim, com toda gratidão reconhecemos tudo o que tu fazes, ó excelentíssimo Félix.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Entretanto, para que não mais te detenha, peço-te que brevemente ouça-me com bondade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Pois verificamos ser este homem uma peste e alguém que leva judeus de todo mundo a se rebelarem. Ele é um líder da seita nazarena,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'e até tentou profanar o templo; então, nós o prendemos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, '');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Quando perguntares a Paulo sobre todas estas questões, tu, também, serás capaz de descobrir aquilo de que o acusamos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Juntos, os judeus também acusaram Paulo, e disseram que essas coisas eram verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Todavia, quando o governador acenou para Paulo falar, ele respondeu: \"Entendo que por muitos anos tu tens sido o juiz desta nação, e estou muito feliz em me explicar para ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Tu estás apto a verificar que, não faz mais de doze dias que subi para adorar em Jerusalém;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'e quando eles me encontraram no templo, não discuti com ninguém, e não agitei a multidão, nem nas sinagogas e nem nas cidade;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'e eles não podem provar a ti as acusações que agora fazem contra mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Mas isso admito a ti, que, de acordo com o caminho que eles chamam de seita, neste mesmo caminho eu sirvo ao Deus de nossos antepassados. Sou fiel a tudo o que está na lei e nos escritos dos profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Tenho a mesma esperança em Deus, como estes homens também esperam por isso, a ressureição vindoura dos mortos, tanto dos justos como dos injustos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'e nisso, procuro ter uma consciência inculpável diante de Deus e dos homens em tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Depois de muitos anos venho trazer ajuda à minha nação e ofertas em dinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Quando fiz isso, certos judeus da Ásia me acharam na cerimônia de purificação no templo, não com uma multidão ou um tumulto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Esses homens deveriam estar diante de ti neste momento, para dizer o que têm contra mim, caso tivessem algo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Ou então, esses mesmos homens deveriam dizer o que acharam de errado em mim, quando estive diante do conselho dos judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'A não ser que seja sobre isso que eu disse quando estava diante deles: \'Por causa da ressureição dos mortos que eu estou sendo julgado hoje por vós\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Félix, porém, estava bem informado acerca do Caminho, e assim adiou a audiência. Ele disse: \"Quando o comandante Lísias voltar de Jerusalém decidirei o teu caso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Então ele ordenou que o centurião prendesse a Paulo, mas com brandura e que não impedisse seus amigos de ajudá-lo ou visitá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Após alguns dias, Félix retornou com sua esposa Drusila, judia, e mandou trazer a Paulo e o ouvia acerca da fé em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Porém quando Paulo argumentou com ele sobre justiça, domínio próprio, e o julgamento vindouro, Félix ficou com medo e respondeu: \"Por agora, vai-te. Mas quando eu tiver oportunidade, mais tarde, te chamarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Ao mesmo tempo, ele esperava que Paulo lhe desse algum dinheiro, por isso mandava chamá-lo com mais frequência e conversava com ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Contudo, quando dois anos se passaram, Pórcio Festo, tornou-se o governador depois de Félix, e querendo agradar os judeus, manteve Paulo na prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Festo entrou na província e depois de três dias foi de Cesareia para Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'O sumo sacerdote e os judeus proeminentes trouxeram acusações a Festo contra Paulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'E solicitavam-lhe por um favor concernente a Paulo, que pudesse chamá-lo para Jerusalém, e assim eles poderiam matá-lo no caminho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Porém, Festo respondeu que Paulo era prisioneiro em Cesareia, e que ele mesmo partiria em breve para lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, '\"Portanto, aqueles que pudessem, deveriam ir conosco. Se houver algo errado com esse homem, devem acusá-lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Depois de permanecer com eles não mais de oito ou dez dias, desceu para Cesareia. No dia seguinte, ele tomou lugar no tribunal e ordenou que trouxessem a Paulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Quando ele chegou, os judeus de Jerusalém ficaram ao redor dele e trouxeram sérias acusações às quais eles não podiam provar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Paulo se defendeu dizendo: \"Nada fiz de errado contra a lei dos judeus, contra o templo, ou contra César\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Festo, porém, queria ganhar o favor dos judeus, e respondeu a Paulo: \"Queres ir a Jerusalém para ser ali julgado por mim a respeito destas coisas\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Paulo disse: \"Estou agora diante do tribunal de César, onde devo ser julgado. Não fiz mal algum aos judeus, como o sabes muito bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Entretanto, se fiz algo de errado, ou se cometi algo que mereça pena de morte, não recuso morrer. Mas, se nada há na acusação deles, ninguém poderá entregar-me a eles. Apelo para César\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Então Festo consultou o seu conselho, e respondeu: \"Tu apelastes para César, para César irás\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Depois de alguns dias, o rei Agripa e Berenice chegaram em Cesareia para uma visita oficial a Festo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Após ficar muitos dias ali, Festo apresentou o caso de Paulo ao rei: \"Um certo homem foi deixado aqui por Félix como prisioneiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Quando estive em Jerusalém, o sumo sacerdote e os anciãos dos judeus trouxeram acusações contra esse homem, e pediram a sua condenação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Eu lhes disse que não é costume romano entregar um homem à morte sem que o acusado tenha presentes os seus acusadores e possa defender-se das acusações que lhe fazem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Portanto quando eles vieram aqui, eu não esperei, e no dia seguinte, assentei-me no tribunal e ordenei que o trouxessem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Quando os seus acusadores se levantaram para o acusar, não encontrei nenhuma acusação séria entre as que trouxeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Ao contrário, tinham alguns pontos de divergência entre eles acerca da sua própria religião e sobre um certo Jesus que estava morto, a quem Paulo afirma estar vivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Fiquei confuso sobre como investigar tal assunto, e perguntei se ele estaria disposto a ir para Jerusalém, para alí ser julgado sobre essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Mas, quando Paulo apelou para ser mantido sob a guarda do imperador, ordenei que ficasse sob custódia, até que eu o enviasse a César\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Agripa disse a Festo: \"Também gostaria de ouvi-lo\". Disse Festo: \"Amanhã o ouvirás\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Então, no dia seguinte, Agripa e Berenice vieram com grande pompa e entraram na sala de audiências com os oficiais militares e os homens mais influentes da cidade. Festo deu o comando e Paulo foi trazido a eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Festo disse: \"Rei Agripa, e todos os teus homens que estão aqui conosco, vedes este homem de quem toda a multidão de judeus tanto em Jerusalém como aqui tem me consultado, clamando que ele não deveria mais viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Mas verifiquei que ele nada fez que fosse digno de morte; porém, como ele apelou para o imperador, decidi enviá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Pois não tenho nada definido para escrever ao imperador a respeito dele. Por isso, eu o trouxe especificamente a ti, ó rei Agripa, a fim de que eu possa ter algo para escrever sobre o caso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Porque não me parece justo enviar um prisioneiro sem especificar as acusações contra ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'A seguir, Agripa disse a Paulo: \"Tu podes falar por ti mesmo\". Paulo, então, estendeu a mão e fez sua defesa:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '\"Eu me considero feliz, Rei Agripa, por poder responder hoje, perante ti, todas as acusações dos judeus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'especialmente porque és profundo conhecedor de todas as tradições e questões dos judeus. Então eu peço que me ouças pacientemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Verdadeiramente, todos os judeus sabem como eu vivi desde a minha juventude em minha nação e em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Eles me conhecem desde o início, e deveriam admitir que eu vivia como um fariseu, um grupo bem severo em nossa religião.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Agora estou aqui, para ser julgado porque espero pela promessa que Deus fez a nossos pais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'Por essa razão, nossas doze tribos perseverantemente servem a Deus noite e dia, e esperamos alcançá-la. E é por causa dessa esperança que os judeus me acusam, rei Agripa!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Por que julgais que seja inacreditável que Deus ressuscite os mortos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Durante um tempo, pensava comigo mesmo que devia fazer muitas coisas contra o Nome de Jesus de Nazaré.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Fiz isso em Jerusalém. Prendi muitos dos santos na prisão pela autoridade que tinha dos chefes dos sacerdotes para assim o fazer; e quando eles eram mortos, também dava o meu voto contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Frequentemente, eu os punia em todas as sinagogas, e tentava fazer com que blasfemassem. Estava enfurecido contra ele e os perseguia até em cidades estrangeiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Enquanto fazia isso, fui para Damasco debaixo da autoridade e da ordem dos chefes dos sacerdotes;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'e, no caminho, ao meio-dia, ó rei, eu vi uma luz que veio do céu, brilhando mais que o sol, resplandecendo em torno de mim e dos demais que viajavam comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Quando caímos em terra, ouvi uma voz na língua dos hebreus, falando comigo, que dizia: \'Saulo, Saulo, por que me persegues? Resistir ao aguilhão vai ser difícil!\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Perguntei: \'Quem és Tu, Senhor?\' E o Senhor respondeu: \'Sou Jesus, a quem tu persegues.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Agora, levanta-te e fica de pé; porque foi para esse propósito que Eu apareci para ti, para fazer-te servo e testemunha das coisas que já sabes sobre mim e das coisas que Eu irei te mostrar mais tarde.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Te livrarei desse povo e dos gentios, a quem te envio,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'para abrir os olhos deles, desviá-los das trevas para a luz e do poder de Satanás para Deus, a fim de que recebam de Deus o perdão dos pecados e a herança que Eu dou àqueles que santifiquei pela fé em Mim\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Portanto, Rei Agripa, não desobedeci à visão celestial;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'ao contrário, preguei para que todos arrependessem, voltassem para Deus, praticando boas obras de arrependimento; primeiro, para os de Damasco, depois os de Jerusalém e toda a região da Judeia, e também para os gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Por causa disso, os judeus me prenderam no templo e tentaram matar-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Deus tem me ajudado até esse dia. Então eu me levanto e testifico, tanto às pessoas simples quanto às importantes, do que os profetas e Moisés disseram que iria acontecer, nada além;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'que Cristo deveria sofrer e seria o primeiro a ressuscitar dos mortos e proclamar luz para o povo judeu e para os gentios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Quando Paulo completou sua defesa, Festo disse em voz alta: \"Ele, está louco; seu grande conhecimento te faz insano\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Mas Paulo disse: \"Não estou louco, ó excelentíssimo Festo, mas com coragem digo palavras de verdade, em perfeito juízo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Pois o rei conhece todas essas coisas; por isso, eu lhe falo livremente, porque estou convencido que nada lhe está oculto; pois nada disso aconteceu em segredo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Crês nos profetas, Rei Agripa? Sei que crês\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Agripa disse a Paulo: \"Por pouco me persuades a fazer-me cristão\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Paulo disse: \"Oro a Deus que por pouco ou por muito, não apenas tu, mas também todos os que hoje me ouvem sejam como eu, porém sem estas correntes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Então, o rei se levantou e, com ele, o governador e Berenice, e todos os que estavam assentados com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'Quando deixaram o salão, disseram uns aos outros: \"Esse homem não fez nada digno de morte ou prisão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Agripa disse a Festo: \"Esse homem poderia ter sido solto se não tivesse apelado a César\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Quando foi decidido que navegaríamos para a Itália, entregaram Paulo e alguns outros prisioneiros a um centurião chamado Júlio, do Regimento Augustino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Nós embarcamos em um navio de Adramítio, que estava prestes a navegar junto à costa da Ásia. Então, fomos para o mar; Aristarco que era de Tessalônica, cidade da Macedônia, vinha conosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'No dia seguinte, desembarcamos na cidade de Sidom, onde Júlio tratou Paulo de modo gentil e permitiu-lhe ir até seus amigos, a fim de receber cuidados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Partindo dali, fomos para o mar e navegamos em volta da ilha de Chipre, que nos abrigou do vento, porque esse estava contra nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'A seguir, navegamos através das águas perto da Cilícia e Panfília, e fomos a Mirra, uma cidade da Lícia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Lá, o centurião encontrou um navio de Alexandria, que ia para a Itália, no qual nos embarcou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Navegamos vagarosamente por muitos dias, e finalmente chegamos, com dificuldade, próximo a Cnido. Contudo, o vento não nos permitiu seguir o caminho; então, navegamos pelo lado de Creta protegido contra os ventos, oposto a Salmona.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'Navegamos pela costa com dificuldade, até que chegamos a um certo lugar chamado Bons Portos, que é perto da cidade de Laseia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Tínhamos gasto muito tempo, já havia passado o tempo do jejum dos judeus, e também se tornou perigoso navegar. Então, Paulo os alertou,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'e disse: \"Homens, eu vejo que a viagem que estamos prestes a fazer será danosa e com muita perda, não apenas da mercadoria e do navio, mas também de nossas vidas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Porém, o centurião prestou mais atenção ao mestre e ao proprietário do navio, do que às coisas que foram ditas por Paulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Não sendo o porto propício para se passar o inverno, a maioria dos marinheiros aconselhou que partissem dali, se, por algum meio, conseguíssemos chegar a cidade de Fenice, para ali passar o inverno. Fenice é um porto em Creta, voltado para o nordeste e sudeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Quando o vento do sul começou a soprar gentilmente, os marinheiros pensaram que tinham o que precisavam; então, eles ergueram a âncora e navegaram próximo a Creta, perto da costa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Mas, depois de um curto período, um vento forte de tempestade chamado Euroaquilão começou a nos golpear, vindo da ilha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Quando o navio foi apanhado em cheio, e não podia enfrentar o vento, nós nos deixamos ser levados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Passamos por um lado protegido de uma pequena ilha chamada Cauda; e com dificuldade pudemos segurar o bote salva-vidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Quando eles levantaram o bote, usaram as suas cordas para amarrá-lo no casco do navio. Eles temiam que pudéssemos ir em direção aos bancos de areia de Sirte; então, abandonaram a âncora, e deixaram-se ser conduzidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Nós estávamos muito abatidos por causa da tempestade; então, no dia seguinte, os navegadores começaram a jogar a carga para fora do navio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'No terceiro dia, os marinheiros também lançaram ao mar com as próprias mãos, o equipamento do navio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Depois de o sol e as estrelas não brilharem sobre nós por vários dias, e de ainda ser castigado por grande tempestade, qualquer esperança de que pudéssemos ser salvos foi abandonada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Estando eles há muito tempo sem comer, Paulo se levantou entre os marinheiros e disse: \"Homens, devieis ter me ouvido, e não partir de Creta a fim de evitar este dano e perda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'E agora, eu vos incentivo a tomarem coragem, porque não haverá nenhuma perda de vidas entre vós, mas apenas a perda do navio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Porque na noite passada, um anjo de Deus, a quem eu pertenço, e também adoro, se colocou ao meu lado');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'e disse: \'Não temas, Paulo. Tu deves te encontrar com César, e Deus te concede a vida de todos os que estão viajando contigo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Portanto, homens, tomem coragem! Porque confio em Deus que acontecerá assim como Ele me falou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Mas nós devemos naufragar em alguma ilha\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Quando a décima quarta noite veio, enquanto estávamos sendo levados por este caminho, que era o mar Adriático, por volta da meia noite, os navegadores pensaram que estavam se aproximando de alguma terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Eles fizeram sondagens e encontraram vinte braças; depois de um breve momento, fizeram mais sondagens e encontraram quinze braças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Estavam com medo de bater nas rochas; então, baixaram quatro âncoras da popa, e oraram para que a manhã viesse logo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Os marinheiros procuravam uma maneira de abandonar o navio, e abaixaram o bote ao mar, sob pretexto de lançar as âncoras da proa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Mas, Paulo disse ao centurião e aos soldados: \"A menos que estes homens continuem no navio, não podereis salvar-vos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Então os soldados cortaram as cordas do bote e deixaram-no ir embora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Quando amanheceu, Paulo alertou a todos para que comessem. Ele disse: \"Este é o décimo quarto dia que vós esperais, e não comestes nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Então eu vos peço que comais, porque isto é para que sobrevivais; e nenhum cabelo de vossa cabeça será perdido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Quando ele disse isso, tomou o pão e agradeceu a Deus à vista de todos eles; então, partiu-o e começou a comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Assim, eles foram todos encorajados e também comeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Nós éramos duzentas e setenta e seis pessoas no navio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Quando eles comeram o suficiente, fizeram com que o navio ficasse mais leve jogando o trigo ao mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Quando amanheceu, eles não reconheceram a terra, mas viram uma baía com uma praia, e discutiram se levariam o navio até lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Então, cortaram as âncoras e as deixaram no mar. Na mesma hora, desataram as cordas dos lemes e levantaram a vela principal ao vento; e, então, se dirigiram para a praia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Mas eles foram para um lugar onde duas correntes se encontravam, e o navio foi em direção à praia. A proa do navio encalhou ali e permaneceu imóvel, mas a popa começou a quebrar por causa da violência das ondas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'O plano dos soldados era matar os prisioneiros para que nenhum deles pudesse nadar e fugir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Mas o centurião quis salvar Paulo, então ele impediu o plano deles; e ordenou àqueles que podiam nadar que pulassem do navio primeiro e chegassem a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'Então, o resto dos homens deveria segui-los, alguns em tábuas, e outros em algumas coisas do navio. Desta forma, todos nós chegamos seguros a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'E, tendo sido salvos, soubemos que aquela ilha se chamava Malta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'As pessoas nativas nos trataram com gentileza incomum; elas acenderam uma fogueira e nos convidaram por causa da constante chuva e frio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Mas quando Paulo apanhava alguns gravetos para colocá-los no fogo, uma víbora saiu por causa do calor e prendeu-se à sua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Quando os nativos viram o animal preso na sua mão, disseram uns aos outros: \"Este homem certamente é um assassino que escapou do mar, e a Justiça não lhe permitiu viver\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Então ele sacudiu o animal no fogo e não sofreu nenhum mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Eles estavam esperando que ele viesse a inchar com a febre ou cair morto no chão. Mas, depois de o observarem por algum tempo e, vendo que não tinha nada usual, eles mudaram de ideia e passaram a dizer que ele era um deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Em um lugar próximo dali, havia terras que pertenciam ao homem principal da ilha, cujo nome era Públio. Ele nos recebeu gentilmente e nos hospedou por três dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'E aconteceu que o pai de Públio tinha sido acometido de febre e disenteria. Quando Paulo foi até ele, orou com imposição de mãos e o curou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Depois que isso aconteceu, as demais pessoas da ilha que estavam doentes vinham também e eram curadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'As pessoas também nos distinguiram com muitas honras. Quando estávamos nos preparando para navegar, eles nos supriram com o que precisávamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Depois de três meses, embarcamos em um navio de Alexandria que havia invernado na ilha, cuja insígnia trazia os deuses gêmeos, Castor e Pólux.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Depois, desembarcamos em Siracusa e ficamos ali por três dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'De lá, navegamos e chegamos a cidade de Régio. Depois de um dia, soprando o vento sul, no segundo dia, chegamos a cidade de Putéoli.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Lá, encontramos alguns irmãos e fomos convidados a estar com eles por sete dias. Assim, chegamos até Roma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'De lá, os irmãos, depois de ouvirem sobre nós, vieram nos encontrar no mercado de Ápio e nas Três Vendas. Quando Paulo viu os irmãos, agradeceu a Deus, e foi encorajado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Quando entramos em Roma, Paulo recebeu autorização para morar sozinho, acompanhado por um soldado que o guardava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Então, passados três dias, chamou para si alguns homens que eram líderes entre os judeus. Quando eles vieram, disse-lhes: \"Irmãos, embora eu nada tenha feito de errado contra o povo ou os costumes de nossos antepassados, fui enviado como prisioneiro de Jerusalém até as mãos dos romanos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Depois de terem me interrogado, quiseram me soltar, porque não havia em mim razão para pena de morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Mas, quando os judeus se opuseram a isso, fui forçado a apelar para César, embora eu não tenha acusação alguma contra minha nação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Por isso, convidei-vos para vos ver e conversar, pois é por causa da esperança de Israel que estou preso a estas correntes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Então, eles lhe disseram: \"Nem recebemos cartas da Judeia a teu respeito; nem veio aqui irmão algum que relatasse ou dissesse algum mal de ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Mas nós queremos ouvir de ti o que pensas sobre essa seita, porque sabemos que se tem falado contra ela por toda parte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Como eles haviam marcado um dia para estar com Paulo, mais pessoas foram vê-lo em sua casa. Ele lhes apresentou a questão e testificou sobre o Reino de Deus. E tentou persuadi-los a respeito de Jesus, tanto pela lei de Moisés, como pelos profetas, desde a manhã até o anoitecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Alguns foram convencidos pelo que ele dizia, enquanto outros não creram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Como não concordaram entre si, eles se retiraram depois que Paulo falou estas palavras: \"O Espírito Santo falou bem, por intermédio do profeta Isaías para seus antepassados');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'quando disse: \'Vai a este povo e dize: Ouvindo, ouvireis, e de maneira nenhuma entendereis; e vendo, vereis, e de maneira nenhuma percebereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Porque o coração deste povo se endureceu, e com os ouvidos ouviram sem dar atenção e fecharam os olhos; de outra forma, eles poderiam ver com olhos, ouvir com os ouvidos, entender com o coração e se converter, e Eu os curaria\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Portanto, vós devíeis saber que essa salvação de Deus tem sido enviada aos gentios, e eles ouvirão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, '');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Paulo viveu por dois anos inteiros na casa que havia alugado, e ele recebia todos os que vinham a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Ele pregava o Reino de Deus e ensinava a respeito do Senhor Jesus Cristo com toda a ousadia, sem impedimento algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paulo, servo de Jesus Cristo, chamado para ser apóstolo, separado para o Evangelho de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'o qual Ele prometeu previamente por intermédio dos Seus profetas nas Escrituras Sagradas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'a respeito de Seu Filho, que veio da descendência de Davi segundo a carne,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'pela ressurreição dos mortos, Ele foi declarado o poderoso Filho de Deus pelo Espírito de santidade, Jesus Cristo, nosso Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Através Dele, nós temos recebido graça e apostolado para obediência da fé entre todas as nações, por causa do Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Entre essas nações, vós também sois chamados para pertencer a Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'A todos vós, amados de Deus que estais em Roma, e que fostes chamados para serdes santos: graça e paz, da parte de Deus, nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Primeiro, agradeço ao meu Deus, mediante Jesus Cristo, por todos vós, porque a vossa fé é proclamada em todo o mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Pois Deus, a Quem sirvo em meu espírito no Evangelho do Seu Filho, é minha testemunha de como continuamente faço menção de vós');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'em minhas orações, pedindo que, de alguma forma, segundo a vontade de Deus, eu possa visitar-vos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Porque desejo ver-vos, para compartilhar convosco algum dom espiritual, para serdes fortalecidos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'isto é, para serdes mutuamente encorajados, através da fé de cada um, a vossa e a minha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'E não quero, irmãos, que ignoreis que muitas vezes me propus a ir visitar-vos (mas até agora fui impedido), a fim de conseguir entre vós algum fruto, como também entre os demais gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Eu sou devedor tanto a gregos como a estrangeiros, tanto a sábios como a ignorantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Por isso, quanto a mim, estou pronto para proclamar o evangelho também a vós que estais em Roma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Porque eu não me envergonho do Evangelho, pois ele é o poder de Deus para a salvação de todo aquele que crê, primeiro para o judeu depois para o grego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Porque Nele a justiça de Deus é revelada, de fé em fé, como está escrito: \"O justo viverá pela fé\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Porque a ira de Deus é revelada do céu contra toda impiedade e injustiça daqueles que impedem a verdade por meio da injustiça,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'pois o que é conhecido sobre Deus está visível para eles, pois Deus lhes tem manifestado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Porque os Seus atributos invisíveis, principalmente Seu eterno poder e Sua natureza divina, têm sido claramente manifestos desde a criação do mundo, através das coisas criadas. Por isso, eles são indesculpáveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Pois, embora conhecessem sobre Deus, não O glorificaram como Deus, nem Lhe deram graças. Em vez disso, se tornaram tolos em seus pensamentos, e seus corações insensatos ficaram obscurecidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Afirmando serem sábios, tornaram-se tolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'Eles trocaram a glória do Deus imperecível por uma imagem com semelhança de homem perecível, bem como de aves, quadrúpedes e de répteis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Portanto, Deus os entregou às paixões dos seus corações para impureza sexual, para desonrarem seus corpos entre si,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'pois trocaram a verdade de Deus pela mentira, adorando e servindo à criatura em lugar do Criador, o qual é bendito eternamente. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Por esse motivo, Deus os entregou a paixões vergonhosas, pois, tanto suas mulheres trocaram as suas relações íntimas por outras que são contrárias à natureza,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'como também os homens deixaram as suas relações naturais com mulher e se arderam em desejo sexual uns com os outros, homem com homem, praticando o que é indecente, recebendo em si mesmos a punição devida de sua perversão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'E por haverem desprezado o conhecimento de Deus, o próprio Deus os entregou a uma mente reprovada, para praticarem coisas que não lhes são próprias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Estão cheios de toda sorte de injustiça, perversidade, cobiça e malícia; cheios de inveja, homicídio, discórdias, fraudes e más intenções;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'são fofoqueiros, caluniadores, inimigos de Deus, violentos, arrogantes, orgulhosos, inventores de coisas ruins, desobedientes ao pais,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'sem juízo, desleais, sem afeto e sem compaixão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Eles conhecem a sentença de Deus, de que aqueles que praticam tais coisas são merecedores de morte; mas não somente as fazem, mas também aprovam os que as praticam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Então estás indesculpável tu, que julgas; pois, naquilo que julgas o outro, te condenas a ti mesmo. Porque tu, que julgas, praticas as mesmas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Mas nós sabemos que o julgamento de Deus é de acordo com a verdade contra os que praticam tais coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Mas considere isto: se tu, que julgas os que praticam tais coisas, ainda assim fazes as mesmas, como escaparás do julgamento de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Ou desprezas as riquezas da Sua bondade, da sua tolerância e da sua paciência, não sabendo que a Sua bondade é para te conduzir ao arrependimento?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Mas é pela dureza e falta de arrependimento do teu coração que estás acumulando sobre ti mesmo ira no dia da ira, o dia da revelação do justo juízo de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Ele retribuirá a cada pessoa a mesma medida das suas ações:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'aos que, perseverando em boas obras, buscam glória, honra e incorruptibilidade, Ele dará vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Mas virão ira e furor aos que são egoístas, que desobedecem a verdade, mas obedecem à injustiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Deus trará tribulação e sofrimento a toda alma humana que praticou o mal, primeiro ao judeu e também ao grego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Mas glória, honra e paz virão a todos os que praticam o bem, tanto ao judeu quanto ao grego.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Pois não há parcialidade com Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'porque todos os que pecaram sem Lei também sem Lei perecerão, e todos os que pecaram sob a Lei pela Lei serão julgados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Pois não são os ouvintes da Lei que são justos diante de Deus, mas os praticantes da Lei serão justificados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Porque, quando os gentios, que não têm a Lei, fazem pela natureza as coisas da Lei, eles são a Lei para si mesmos, embora não tendo a Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Eles mostram que as ações requeridas pela Lei estão escritas em seus corações. Suas consciências também testemunham isso com eles, e os seus próprios pensamentos tanto os acusam quanto os defendem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'Isso acontecerá no dia em que Deus irá julgar os segredos de todas as pessoas, de acordo com o meu evangelho, através de Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Mas, se tu te chamas judeu e descansas na Lei, e te glorias em Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'e conheces a Sua vontade, e aprovas o que é excelente, porque foste instruído pela Lei,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'e se estás convencido que tu és um guia dos cegos, uma luz àqueles que estão nas trevas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'um instrutor de ignorantes, um mestre de néscios, e que tens na Lei a forma de conhecimento e de verdade, então como isso afeta a tua maneira de viver?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Tu que ensinas outros, não ensinas a ti mesmo? Tu que pregas para não roubar, roubas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Tu que dizes para não cometer adultério, adulteras? Tu que detestas ídolos, roubas templos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Tu que te glorias na Lei, desonras a Deus pela transgressão da Lei?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Pois como está escrito: \"O Nome de Deus é desonrado no meio dos gentios por causa de vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Pois a circuncisão, de fato, te beneficia, se obedeceres a Lei; mas, se transgrides a Lei, tua circuncisão se torna incircuncisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Se, então, um incircunciso guardar os princípios da Lei, a sua incircuncisão não será considerada circuncisão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'E o naturalmente incircunciso, se guardar a Lei, não condenará a ti, que, apesar das Escrituras e da circuncisão, és transgressor da Lei!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Pois não é judeu quem o é somente por fora; nem é circunciso o que é apenas no exterior da carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Mas é judeu quem o é internamente, e circuncisão é a do coração no Espírito, não segundo a letra. O louvor de tal pessoa não vem dos homens, mas de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Então, que vantagem têm os judeus? E qual o benefício da circuncisão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'É enorme, em todos os sentidos. Primeiramente, aos judeus foi confiada a revelação de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'E, se alguns judeus foram infiéis, irá a sua infidelidade tornar a fidelidade de Deus inválida?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'De forma nenhuma. Ao invés disso, que Deus seja verdadeiro, e todo homem seja mentiroso. Como está escrito: \"Para que sejas visto como justo em tuas palavras, e que prevaleças quando vieres a julgamento\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Mas, se nossa injustiça manifesta a justiça de Deus, o que podemos falar? Podemos dizer que Deus é injusto por trazer Sua ira sobre nós? (Falo de acordo com a lógica humana.)');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'De forma nenhuma! Pois, então, como Deus julgaria o mundo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Mas, se a verdade de Deus, através de minha mentira, traz mais louvor para Ele, porque ainda sou julgado como um pecador?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'E por que não dizemos, como erroneamente alguns afirmam que falamos: \"Façamos o mal, para que o bem venha\"? A condenação deles é justa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'E então? Estamos desculpando a nós mesmos? Absolutamente não. Pois já demonstramos que tanto judeus quanto gregos, todos estão sob pecado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'como está escrito: \"Não há um justo, nem um sequer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Não há quem entenda. Não há quem busque a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Todos se desviaram, todos juntos se tornaram inúteis. Não há quem faça o bem, nem um sequer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'A garganta deles é um sepulcro aberto. Suas palavras enganam. Há veneno de cobras sob seus lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Suas bocas estão cheias de maldição e amargura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Seus pés se apressam para derramar sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Destruição e sofrimento estão em seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'Eles não conheceram o caminho da paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Não há temor a Deus diante de seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Agora, sabemos que tudo o que a Lei diz é dito aos que estão sob a Lei, para que toda boca possa ser calada e todo o mundo torne-se sujeito ao julgamento de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Porque ninguém será justificado pelas obras da Lei diante Dele. Pois pela Lei vem a consciência do pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Mas agora, sem Lei, a justiça de Deus se manifestou testemunhada pela Lei e pelos profetas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'isto é, a justiça de Deus, pela fé em Jesus Cristo, para todos os que acreditam. Pois não há distinção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Porque todos pecaram e estão destituídos da Glória de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'sendo justificados gratuitamente pela sua graça através da redenção que há em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Pois Deus ofereceu Jesus Cristo como propiciação pelo Seu sangue, por meio da fé. Ele ofereceu Cristo como uma prova da Sua justiça e, em Sua paciência, deixou de punir os pecados cometidos anteriormente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'Isso ocorreu como demonstração da Sua justiça no tempo presente, para que Ele seja justo e o justificador de qualquer um que tem fé em Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Onde está o orgulho? Foi excluído. Em qual base? Obras? Não, mas baseado na fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Nós concluímos, portanto, que uma pessoa é justificada pela fé sem as obras da Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Ou Deus é apenas Deus dos judeus? Ele não é também Deus dos gentios? Sim, dos gentios também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Se, de fato, Deus é um, Ele justificará a circuncisão pela fé, e a incircuncisão pela fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Nós, então, anulamos a lei através da fé? De modo nenhum! Pelo contrário, nós a confirmamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Então, o que diremos que Abraão, nosso antepassado segundo a carne, encontrou?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Pois, se Abraão foi justificado pelas obras, ele teria razão para se gloriar, mas não diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'O que as Escrituras dizem? \"Abraão acreditou em Deus, e isso foi lhe atribuído como justiça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Ora, para o que trabalha, o salário não lhe é pago como um presente, mas como uma dívida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Porém, ao que não trabalha, mas, em vez disso, acredita Naquele que justifica o ímpio, a sua fé lhe é atribuída como justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Davi também proclama bênçãos ao homem a quem Deus atribui justiça independentemente de obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Ele disse: \"Felizes são aqueles cujas iniquidades foram perdoadas, e cujos pecados foram cobertos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Feliz é o homem a quem o Senhor não atribui pecado.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Assim, essa bênção foi proclamada somente aos da circuncisão, ou também aos da incircuncisão? Pois nós falamos: \"A fé foi atribuída a Abraão como justiça.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Então, como ela lhe foi atribuída? Quando Abraão estava na circuncisão ou na incircuncisão? Não foi na circuncisão, e sim na incircuncisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Abraão recebeu o sinal da circuncisão, o qual era um selo da justiça da fé que ele já possuía quando estava na incircuncisão. O resultado desse sinal foi que ele se tornou pai daqueles que acreditam, mesmo que não sejam circuncidados. Isso significa que a justiça lhes foi atribuída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'E também significa que Abraão se tornou pai da circuncisão, não apenas dos que foram circuncidados, mas, da mesma forma, dos que seguem os passos de fé de nosso pai Abraão antes que ele fosse circuncidado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Porque não foi através da Lei que a promessa foi dada a Abraão e aos seus descendentes, a promessa de que eles seriam herdeiros do mundo. Em vez disso, ela foi dada pela justiça da fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Pois, se os que vivem pela Lei são herdeiros, a fé se torna vazia e a promessa, nula.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Porque a Lei traz ira, mas, onde não há lei, não há desobediência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Por essa razão, isso é pela fé, para que a promessa seja baseada na graça, e seja garantida para todos os descendentes de Abraão. E esses descendentes incluem não somente aqueles que conhecem a Lei, mas também aqueles que são da fé de Abraão. Pois ele é o pai de todos nós,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'como está escrito: \"Eu te constituí pai de muitas nações\". Abraão estava na presença Daquele em Quem confiou, ou seja, Deus, o qual dá vida aos mortos e chama as coisas que não existem à existência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Apesar de todas as circunstâncias ao seu redor, Abraão confiadamente entregou seu futuro a Deus, e então se tornou o pai de muitas nações, conforme o que foi dito: \"Assim serão teus descendentes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Ele não foi fraco na fé. Abraão entendeu que seu próprio corpo era incapaz de ter filhos, porque tinha cerca de 100 anos de idade. Ele também reconheceu que o ventre de Sara já não podia gerar filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Mas, por causa da promessa de Deus, Abraão não permaneceu na incredulidade. Em vez disso, foi fortalecido na fé, e deu glórias a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Ele estava totalmente convencido de que Deus era capaz de cumprir o que prometera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Portanto, isso também foi atribuído a ele como justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Não foi apenas para o benefício dele que está escrito que Deus lhe atribuiu justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Mas também foi escrito para nosso benefício, porque Deus nos considerará justos, nós, os que cremos Naquele que ressuscitou Jesus, nosso Senhor, dentre os mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Aquele que foi entregue por nossas transgressões e foi ressuscitado para a nossa justificação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Portanto, justificados pela fé, temos paz com Deus por intermédio do nosso Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Através Dele, também temos acesso, pela fé, a esta graça na qual estamos firmes. Alegramo-nos na esperança que Deus nos dá para o futuro, a esperança de que participaremos da glória de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Não somente isso, mas também nos regozijamos em nossos sofrimentos, sabendo que o sofrimento produz perseverança;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'a perseverança produz aprovação; e a aprovação produz esperança para o futuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'A esperança não desaponta, porque o amor de Deus tem sido derramado em nossos corações por intermédio do Espírito Santo, que nos foi dado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Pois, quando ainda éramos fracos, Cristo morreu pelos ímpios no tempo certo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Porque dificilmente alguém morreria por um justo; isto é, talvez alguém até ouse morrer por uma boa pessoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Mas Deus prova Seu próprio amor por nós, porque Cristo morreu por nós, enquanto ainda éramos pecadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Muito mais agora, que somos justificados por Seu sangue, seremos salvos por Ele da ira de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Pois, se nós, enquanto éramos inimigos, fomos reconciliados com Deus através da morte de Seu Filho, muito mais depois de termos sido reconciliados, seremos salvos por Sua vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Não somente isso, mas também nos regozijamos em Deus através do nosso Senhor Jesus Cristo, por meio de Quem agora recebemos essa reconciliação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Portanto, como o pecado entrou no mundo através de um homem, da mesma forma a morte entrou através do pecado. E a morte se espalhou para todas as pessoas, porque todos pecaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Pois até a Lei, o pecado estava no mundo, mas o pecado não é levado em conta quando não há Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'No entanto, a morte reinou de Adão até Moisés, mesmo sobre aqueles que não pecaram de modo semelhante à desobediência de Adão, que é um modelo Daquele que estava por vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Mas, mesmo assim, o dom gratuito não é como a transgressão. Pois, se todos morreram pela transgressão de um, muito mais a graça de Deus e a dádiva pela graça de um único homem, Jesus Cristo, abundaram para muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Porque o dom não é como a consequência do pecado de um homem. Pois, por um lado, o julgamento da condenação veio por causa da transgressão de um só homem; mas, por outro lado, o dom gratuito veio depois de muitas transgressões, para justificação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Pois, se a morte reinou através de um pela transgressão de um só, muito mais aqueles que recebem a abundância da graça e do dom da justiça reinarão em vida através de um só, Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Então, assim como todas as pessoas foram condenadas por uma transgressão, também por um ato de justiça veio a justificação da vida a todas as pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Pois, como pela desobediência de um só homem, muitos foram feitos pecadores, da mesma forma, através da obediência de um, muitos serão feitos justos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Mas a Lei entrou para que a transgressão abundasse. Entretanto, onde o pecado abundou, a graça abundou ainda mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'Isso aconteceu para que, da mesma forma que o pecado reinou na morte, assim também a graça possa reinar, por meio da justiça, para a vida eterna através de Jesus Cristo, nosso Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Então, o que diremos? Devemos continuar no pecado para que a graça possa abundar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Nunca! Nós que morremos para o pecado, como podemos ainda viver nele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Não sabeis que, assim como fomos batizados em Cristo Jesus, também fomos batizados em Sua morte?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Portanto, fomos sepultados com Ele através do batismo na morte. Isso aconteceu para que, como Cristo foi ressuscitado dentre os mortos pela glória do Pai, assim nós também possamos andar em novidade de vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Porque, se temos nos tornado unidos com Ele na semelhança da Sua morte, também estaremos unidos, com Sua ressurreição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Nós sabemos isto: que nosso velho homem foi crucificado com Ele, para que o corpo do pecado seja destruído. Isso aconteceu a fim de não sermos mais escravizados pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Aquele que morreu é declarado justo em relação ao pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Mas, se tivermos morrido com Cristo, acreditamos que também viveremos com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Sabemos que Cristo foi ressuscitado dentre os mortos e que não está mais morto. A morte não tem mais domínio sobre Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Pois, quanto a ter morrido pelo pecado, Ele morreu de uma vez por todas. Contudo a vida que Ele vive, vive para Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Da mesma maneira, considerai-vos também mortos em vós mesmos para o pecado, mas vivos para Deus em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Portanto, não deixeis o pecado reinar em vosso corpo mortal, de forma que obedeçais a suas paixões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Não apresenteis as partes do vosso corpo ao pecado, para serem instrumentos usados para injustiça. Mas apresentai-vos a Deus como mortos que agora estão vivendo. E apresentai as partes do vosso corpo a Deus como instrumentos a serem usados para justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Não permitais que o pecado vos domine, porque não estais debaixo da Lei, mas debaixo da graça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'E então? Devemos pecar porque não estamos debaixo da Lei, mas debaixo da graça? Nunca!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Não sabeis que a quem vós mesmos vos apresentais como servos é a quem sois obedientes e a quem deveis obedecer? A verdade é esta: ou sois servos do pecado que leva à morte, ou servos da obediência que leva à justificação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Mas graças a Deus! Pois fostes servos do pecado, no entanto tendes obedecido de coração ao padrão de doutrina que vos foi dado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Tendes sido libertos do pecado e feitos escravos da justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Falo como homem, por causa da fraqueza da vossa carne. Pois, como apresentastes as partes do vosso corpo como escravos para a impureza e para o mal, da mesma forma, agora, apresentai-as como escravos da justiça para santificação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Visto que, quando éreis escravos do pecado, estáveis livres da justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Naquele tempo, que fruto, então, tivestes das coisas das quais agora estais envergonhados? Porque o fim dessas coisas é a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Mas agora, que fostes libertos do pecado e feitos escravos de Deus, tendes o vosso fruto para santificação, e o resultado é a vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Pois o salário do pecado é a morte, mas o dom gratuito de Deus é a vida eterna em Cristo Jesus, nosso Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Ou não sabeis, irmãos, que a lei controla o homem enquanto ele vive? Pois falo a pessoas que conhecem a lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Pois, pela lei, a mulher casada está ligada ao seu marido enquanto ele viver; mas se seu marido morrer, ela estará livre da lei do casamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Então, se ela unir-se com outro homem enquanto seu marido estiver vivo, ela será chamada de adúltera. Porém, se seu marido morrer, ela estará livre da lei, de modo que não será adúltera se se casar com outro homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Portanto, meus irmãos, vós também fostes mortos para a lei, mediante o corpo de Cristo, de modo que pudésseis pertencer a outro, isto é, Àquele que foi ressuscitado dentre os mortos, a fim de produzirmos frutos para Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Pois quando estávamos na carne, as paixões pecaminosas, despertadas pela lei, operavam em nossos membros para produzir fruto para a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Todavia, agora estamos livres da lei. Morremos para aquilo a que estávamos presos, para então servir na novidade do Espírito, e não na velhice da letra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'O que diremos então? É a lei em si pecado? De modo algum. No entanto, eu jamais conheceria o pecado se não fosse através da lei. Por que eu não conheceria a cobiça se a lei não dissesse: \"Não cobiçarás\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Mas o pecado, aproveitando-se da oportunidade dada pelo mandamento, trouxe todo tipo de cobiça em mim. Pois sem a lei, o pecado está morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Antes eu vivia sem a lei, mas quando o mandamento veio o pecado reviveu e eu morri.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'O mandamento, que era para trazer vida, tornou-se em morte para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Pois o pecado, aproveitando-se da oportunidade através do mandamento, enganou-me. E através do mandamento, matou-me.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Portanto, a lei é santa, e o mandamento é santo, justo e bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Portanto, o que era bom tornou-se morte para mim? De modo algum. Mas o pecado, para que se mostrasse como pecado por meio do que é bom, produziu em mim a morte. Isso, para que através do mandamento o pecado se revelasse pecaminoso, além da medida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Porque sabemos que a lei é espiritual, mas eu sou carnal, vendido como escravo ao pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Por que o que eu faço, realmente não entendo. Pois o que quero fazer, eu não faço; e o que odeio, eu faço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Mas se faço o que não quero, concordo com a lei, que a lei é boa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Mas agora não sou mais eu quem faz isto, mas o pecado que habita em mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Pois sei que em mim, isto é, na minha carne, não habita coisa boa, pois o desejo para o bem está em mim, mas eu não consigo fazê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Pois o bem que quero fazer, não faço, mas o mal que não quero, este faço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Portanto, se faço o que não quero fazer, então não sou mais eu que estou agindo, mas o pecado que vive em mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Percebo, então, em mim, a lei de querer fazer o que é bom, mas realmente o mal está presente em mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Pois, com o homem interior, me regozijo na lei de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Todavia, vejo uma lei diferente nos membros do meu corpo, que lutam contra uma nova lei em minha mente. Isso me faz prisioneiro da lei do pecado que está nos membros do meu corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Sou um homem miserável! Quem me livrará deste corpo de morte?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Graças a Deus por Jesus Cristo nosso Senhor! Assim, pois, eu sirvo a lei de Deus com minha mente, contudo, com a carne eu sirvo o princípio do pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Portanto, não há agora nenhuma condenação para aqueles que estão em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Porque a lei do Espírito da vida em Cristo Jesus me libertou da lei do pecado e da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Pois o que a lei era incapaz de fazer, porque era fraca através da carne, Deus o fez. Ele enviou o seu próprio Filho em semelhança da carne pecaminosa, a fim de ser uma oferta para o pecado, e Ele condenou o pecado na carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'Ele fez isso para que a exigência da lei fosse cumprida em nós que andamos, não de acordo com a carne, mas segundo o Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Aqueles que vivem de acordo com a carne prestam atenção nas coisas da carne, mas aqueles que vivem segundo o Espírito, nas coisas do Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Pois a mentalidade da carne é morte, mas a mentalidade do Espírito é vida e paz;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'porque a mentalidade da carne é hostil em relação a Deus, pois não é sujeita à lei de Deus, nem é capaz de ser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Aqueles que estão na carne não podem agradar a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Contudo, não estais na carne, mas no Espírito, se é que o Espírito de Deus vive em vós. Mas se alguém não tem o Espírito de Cristo, não pertence a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Se Cristo está em vós, o corpo está morto em relação ao pecado, mas o Espírito está vivo em relação à justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Se o Espírito Daquele que ressuscitou Jesus dos mortos vive em vós, Ele que ressuscitou Cristo dos mortos dará também vida aos vossos corpos mortais através do Seu Espírito, que vive em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Então, irmãos, somos devedores não à carne, para viver de acordo com a carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Pois, se viverdes de acordo com a carne, morrereis; mas, se pelo Espírito matardes as ações do corpo, vivereis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Pois aqueles que são guiados pelo Espírito de Deus, esses são filhos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Porque não recebestes o espírito de escravidão novamente para temor, mas recebestes o espírito de adoção, pelo qual clamamos: \"Abba, Pai!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'O próprio Espírito testemunha com o nosso espírito que somos filhos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Se somos filhos, somos também herdeiros, herdeiros de Deus, e coerdeiros com Cristo, se de fato sofremos com Ele para que também sejamos glorificados com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Porque considero que os sofrimentos deste tempo presente não são dignos de serem comparados com a glória que nos será revelada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Pois a ardente expectativa da criação aguarda a revelação dos filhos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Porque a criação foi sujeita à futilidade, não por sua própria vontade, mas pela vontade daquele que a sujeitou, na esperança');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'de que a própria criação seja liberta da escravidão da corrupção para a liberdade da glória dos filhos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Pois sabemos que toda a criação geme e sente dores de parto ainda hoje.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Não somente ela, mas também nós, que temos os primeiros frutos do Espírito - inclusive nós mesmos gememos por dentro, esperando pela nossa adoção, a redenção do nosso corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Pois na esperança fomos salvos. Mas o que esperamos que aconteça, ainda não se viu, pois como se espera o que já se vê?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Mas se esperamos o que não vemos, com paciência esperamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Do mesmo modo, o Espírito também ajuda em nossas fraquezas. Pois não sabemos como orar, mas o próprio Espírito intercede por nós com gemidos inexprimíveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Ele, que examina os corações, conhece a mente do Espírito, porque Ele intercede em favor dos santos, de acordo com a vontade de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Sabemos que todas as coisas cooperam para o bem daqueles que amam a Deus, dos que são chamados de acordo com o Seu propósito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Porque, aos que previamente conheceu, Ele também predestinou para serem conforme a imagem de Seu Filho, para que Ele seja o primogênito dentre muitos irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Aos que predestinou, a estes também chamou. Aos que chamou, a estes, Ele também justificou. Aos que justificou, a estes também glorificou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'O que então devemos dizer sobre essas coisas? Se Deus é por nós, quem será contra nós?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Ele, que não poupou Seu próprio Filho, mas O entregou em favor de todos nós, como não nos dará também com Ele todas essas coisas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Quem trará alguma acusação contra os eleitos de Deus? É Deus quem os justifica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Quem os condenará? Cristo é quem morreu por nós, e, mais que isso, também ressuscitou. Ele está à direita de Deus, o qual também intercede por nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Quem nos separará do amor de Cristo? Tribulação, angústia, perseguição, fome, nudez, perigo ou espada?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Como está escrito: \"Por causa de Ti, somos mortos todo o dia. Fomos considerados como ovelhas para o matadouro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Em todas essas coisas, somos mais que vencedores através Daquele que nos amou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Pois estou convencido de que nem morte, nem vida, nem anjos, nem principados, nem coisas presentes, nem coisas futuras, nem poderes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'nem altura, nem profundidade, nem nenhuma outra coisa criada será capaz de nos separar do amor de Deus, que está em Cristo Jesus nosso Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Eu digo a verdade em Cristo; eu não minto. Minha consciência dá testemunho comigo, no Espírito Santo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'de que tenho uma grande tristeza e incessante dor no meu coração;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'pois eu desejaria que eu mesmo fosse maldito e separado de Cristo por amor dos meus irmãos, que são meus compatriotas segundo a carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Eles são israelitas. Pertence-lhes a adoção, a glória, as alianças, a entrega da Lei, a adoração a Deus, e as promessas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Deles são os patriarcas, de quem Cristo descendeu, segundo a carne, o qual é Deus sobre todos, seja Ele bendito eternamente. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Mas não é que a palavra de Deus tenha falhado. Pois nem todos os de Israel pertencem a Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Como também nem todos os descendentes de Abraão são verdadeiramente seus filhos. Mas, \"Através de Isaque, será chamada a tua descendência\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Isto é, os filhos da carne não são os filhos de Deus. Mas os filhos da promessa são considerados como descendência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Pois esta é a palavra da promessa: \"Neste tempo Eu virei, e será dado um filho a Sara\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'E não somente isto, mas também depois que Rebeca concebeu de nosso pai Isaque');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'E os filhos ainda não tinham nascido, nem tinham feito algo bom ou mau (para que o propósito de Deus de acordo com Sua escolha permanecesse, não por obras, mas por causa Daquele que chama),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'isto fora dito a ela: \"O mais velho servirá o mais novo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Assim está escrito: \"Eu amei Jacó, mas odiei Esaú\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Que diremos, então? Há injustiça da parte de Deus? Nunca!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Pois Ele falou a Moisés: \"Eu terei misericórdia de quem Eu quiser ter misericórdia, e terei compaixão de quem Eu quiser ter compaixão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Portanto, isso não depende de quem quer, nem de quem corre, mas de Deus, que tem misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Pois a Escritura diz a Faraó: \"Para isso mesmo te levantei, para que Eu possa demonstrar em ti Meu poder, e para que Meu Nome possa ser proclamado em toda a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Logo, Ele tem misericórdia de quem Ele quer, e endurece a quem quer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Então, tu me dirás: \"Por que Ele ainda culpa alguém? Pois quem resistiu a Sua vontade?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Pelo contrário, homem, quem és tu que respondes contra Deus? Que poderá dizer o barro para aquele que o moldou: \"Por que Tu me fizeste assim?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Não tem o oleiro o direito sobre o barro para fazer da mesma massa um vaso para uso especial, e outro vaso para uso comum?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'E se Deus, querendo mostrar Sua ira e fazer conhecido o Seu poder, suportou com muita paciência os vasos da ira, preparados para a destruição?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'e se Ele fizesse conhecida a riqueza da Sua glória em vasos de misericórdia, que para a glória Ele preparou anteriormente,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'os quais somos nós, a quem também chamou, não somente dentre os judeus, mas também dentre os gentios?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Como Ele falou também a Oseias: \"Eu chamarei Meu povo aquele que não era Meu povo, e amada, aquela que não era amada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'E será que, no lugar onde foi falado para eles: \'Vós não sois meu povo\', lá eles serão chamados: \'Filhos do Deus vivo\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Isaías clamou a respeito de Israel: \"Ainda que o número dos filhos de Israel seja como a areia do mar, haverá um remanescente que será salvo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'pois o Senhor executará Sua palavra por toda a terra, breve e completamente.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'E, como Isaías antes falou: \"Se o Senhor dos Exércitos não nos tivesse deixado descendência, teríamos nos tornado como Sodoma e seríamos como Gomorra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Que diremos, então? Que os gentios, que não estavam buscando justiça, alcançaram justiça, a justiça pela fé;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'mas Israel, que buscou a lei da justiça, não a alcançou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Por que não? Porque eles não buscaram isso por fé, mas por obras. Eles tropeçaram na pedra de tropeço,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'como está escrito: \"Eis que Eu coloco em Sião uma pedra de tropeço, uma rocha de escândalo. Quem nela crer não será envergonhado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Irmãos, o desejo do meu coração e meu pedido a Deus em favor deles é que sejam salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Pois dou testemunho de que eles têm zelo por Deus, mas não de acordo com o conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Pois, desconhecendo a justiça de Deus, buscando estabelecer a sua própria justiça, não se submeteram à justiça de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Pois Cristo é o cumprimento da lei para justiça de todo aquele que crê.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Porque Moisés escreve sobre a justiça que vem da lei: \"O homem que pratica a justiça que provém da lei viverá por essa justiça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Mas a justiça que vem da fé diz: \"Não digas em teu coração: \'Quem subirá ao céu?\' (isto é, para trazer Cristo para baixo);');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'ou: \'Quem descerá até o abismo?\' (isto é, para levantar Cristo dentre os mortos)\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Mas o que diz? \"A Palavra está próxima de ti, na tua boca e no teu coração\". Esta é a palavra de fé que nós proclamamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Pois, se com tua boca confessares Jesus como Senhor, e creres no teu coração que Deus O ressuscitou dentre os mortos, serás salvo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Porque com o coração se crê para justiça, e com a boca se confessa para a salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Pois a Escritura diz: \"Todo o que Nele crê não será envergonhado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Pois não há distinção entre judeu e grego; porque o mesmo Senhor é Senhor de todos, sendo rico para com todos que O invocam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Porque todo o que invocar o Nome do Senhor será salvo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Como poderão invocar Aquele em Quem não creram? E como poderão crer Naquele de Quem não ouviram falar? E como poderão ouvir se não há quem pregue?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'E como poderão pregar, se não forem enviados? — Como está escrito: \"Quão belos são os pés daqueles que anunciam as boas novas!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Mas nem todos eles deram ouvidos ao Evangelho. Pois Isaías diz: \"Senhor, quem acreditou na nossa mensagem?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Pois a fé vem pelo ouvir, e ouvir a Palavra de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Mas eu pergunto: eles não ouviram? Sim, certamente. \"O som deles se propagou sobre toda a terra, e suas palavras até os confins do mundo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Além disso, pergunto: Israel não sabia? Primeiro, Moisés diz: \"Eu vos provocarei ciúmes pelos que não são uma nação; por meio de uma nação sem entendimento, Eu vos provocarei à ira\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'E Isaías ousou dizer: \"Eu fui achado por aqueles que não Me procuravam. Manifestei-Me aos que não perguntavam por Mim.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Quanto a Israel, Ele diz: \"Todo o dia Eu estendi as Minhas mãos para um povo desobediente e rebelde\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Eu pergunto então: Deus rejeitou Seu povo? De modo algum. Pois eu também sou um israelita, um descendente de Abraão, da tribo de Benjamim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Deus não rejeitou Seu povo, a quem de antemão conheceu. Não sabeis o que a Escritura diz sobre Elias, como ele suplicou ao Senhor contra Israel?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '\"Senhor, eles mataram Teus profetas, quebraram Teus altares, e só eu fiquei, e eles buscam tirar minha vida\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Mas, o que Deus lhe respondeu? \"Eu reservei para Mim mesmo sete mil homens que não dobraram os joelhos a Baal\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Assim também, neste tempo presente, há um remanescente, por causa da eleição da graça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Mas, se é pela graça, já não é mais pelas obras. Caso contrário, a graça não seria graça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'E então? As coisas que Israel procura, isso não alcançou, mas os eleitos as alcançaram, e os demais foram endurecidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'Exatamente como está escrito: \"Deus lhes deu um espírito de entorpecimento, olhos para que não vejam, e ouvidos para que não ouçam, até o dia de hoje\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Então Davi diz: \"Que sua mesa se torne uma rede e uma armadilha, uma pedra de tropeço e uma retaliação para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Que seus olhos sejam escurecidos para que não vejam, e as suas costas encurvadas para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Pergunto, então: eles tropeçaram para cair? De maneira alguma. Em vez disso, por seu fracasso, veio a salvação para os gentios, a fim de provocar-lhes ciúmes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Agora, se o fracasso deles é a riqueza do mundo, e a sua perda é a riqueza dos gentios, quanto maior será sua plenitude?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Mas agora falo a vós, gentios, uma vez que sou um apóstolo para os gentios, glorifico o meu ministério.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Talvez eu provocarei ciúmes àqueles que são da minha própria carne, e, talvez, alguns sejam salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Pois, se a rejeição deles é a reconciliação do mundo, o que será a sua aceitação, senão vida dentre os mortos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Se os primeiros frutos são santos, a massa também é; se a raiz é santa, os ramos também são.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Mas, se alguns dos ramos foram quebrados, e tu, um ramo de oliveira silvestre, foste enxertado entre eles, e te tornaste participante com eles da rica raiz da oliveira,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'não te glories contra os ramos. Mas, se te gloriares, sabe que não és tu que sustenta a raiz, mas a raiz que te sustenta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Tu então dirás: \"Os ramos foram quebrados para que eu fosse enxertado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Verdade! Por causa da incredulidade deles, eles foram quebrados, mas tu permaneces por tua fé. Não penses muito de ti mesmo, mas teme.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Porque, se Deus não poupou os ramos naturais, também não te poupará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Observa, então, a bondade e a severidade de Deus. Por um lado, a severidade veio sobre os judeus que caíram; mas por outro lado, a bondade de Deus veio sobre ti, se permaneceres em Sua bondade. Caso contrário, tu também serás cortado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'E eles também, se não permanecerem na sua incredulidade, serão enxertados de volta. Pois Deus é capaz de enxertá-los novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Porque, se foste cortado da oliveira silvestre por natureza e, contrariamente à natureza, foste enxertado na boa oliveira, quanto mais os judeus, que são ramos naturais, serão enxertados de volta em sua própria oliveira?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Porque, irmãos, eu não quero que fiqueis sem saber deste mistério, a fim de que não sejais sábios em vosso próprio pensamento. Este mistério é que ocorreu um endurecimento parcial a Israel, até que chegue a plenitude dos gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'Assim, todo o Israel será salvo, como está escrito: \"Virá de Sião o Libertador. Ele removerá a impiedade de Jacó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'E esta será a Minha aliança com eles, quando Eu retirar os seus pecados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Quanto ao Evangelho, eles são odiados por vossa causa; todavia, quanto à escolha de Deus, eles são amados por causa dos antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Pois os dons e o chamado de Deus são imutáveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Pois, antigamente, fostes desobedientes a Deus; mas, agora, recebestes misericórdia por causa da desobediência deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Do mesmo modo, esses judeus agora têm sido desobedientes. O resultado foi que, através da misericórdia mostrada a vós, eles também podem receber misericórdia agora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Pois Deus encerrou todos dentro da desobediência, a fim de que Ele tenha misericórdia de todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'Ó profundidade da riqueza, da sabedoria e do conhecimento de Deus! Quão insondáveis são os Seus juízos, e os Seus caminhos incompreensíveis!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Pois quem conheceu a mente do Senhor? Ou quem se tornou Seu conselheiro?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Ou quem primeiro Lhe deu alguma coisa, para que Deus lhe retribua?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Pois Dele, por Ele e para Ele são todas as coisas. A Ele seja a glória para sempre. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Portanto, irmãos, eu insisto que, pelas misericórdias de Deus, apresenteis vossos corpos como sacrifício vivo, santo e agradável a Deus, que é o vosso culto racional.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Não vos conformeis com este mundo, mas transformai-vos pela renovação da vossa mente para que conheçais qual é a boa, agradável e perfeita vontade de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Porque, pela graça que me foi dada, eu vos digo que cada um de vós não deve pensar de si mesmo muito mais do que deveria; mas sim, pense sabiamente, segundo a medida da fé que Deus repartiu a cada um.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Pois nós temos muitos membros em um corpo, mas nem todos os membros têm a mesma função.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Assim também nós, que somos muitos, formamos um só corpo em Cristo e, individualmente, somos membros uns dos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Nós temos diferentes dons de acordo com a graça que nos foi dada. Se o dom de alguém é profecia, que seja conforme a proporção da fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Se o dom é serviço, que sirva. Se o dom é ensinar, que ensine.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Se o dom é encorajamento, que encoraje. Se o dom é contribuir, que contribua generosamente. Se o dom é liderar, que lidere com zelo. Se o dom é misericórdia, que exerça misericórdia com alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Que o amor seja sem hipocrisia. Odiai o mal; apegai-vos ao que é bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Quanto ao amor fraternal, sede afetuosos uns para com os outros. Quanto à honra, respeitai-vos uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Quanto ao zelo, não sejais descuidados. Sede fervorosos no espírito, servindo ao Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Alegrai-vos na esperança que tendes no futuro. Sede pacientes nas tribulações. Orai constantemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Compartilhai as necessidades dos santos e sede hospitaleiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Abençoai os que vos perseguem; abençoai e não amaldiçoeis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Alegrai-vos com os que se alegram; chorai com os que choram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Tende o mesmo sentimento uns para com os outros. Não penseis de maneira orgulhosa, mas aceitai as pessoas humildes. Não sejais sábios aos vossos próprios olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'A ninguém pagueis mal por mal. Fazei o que é bom à vista de todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Se for possível, no que depender de vós, tende paz com todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Amados, não vos vingueis a vós mesmos, mas dai lugar à ira de Deus. Porque está escrito: \"\'A vingança pertence a Mim; Eu retribuirei\'. diz o Senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, '\"Mas se o teu inimigo tiver fome, dá-lhe de comer. Se ele tiver sede, dá-lhe de beber. Porque se fizeres isso, tu amontoarás brasas de fogo sobre a cabeça dele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Não te deixes vencer pelo mal, mas vence o mal com o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Que toda pessoa seja obediente às autoridades superiores, porque não há autoridade, a menos que esta venha de Deus; e as que existem foram designadas por Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Portanto, aquele que resiste à autoridade se opõe à ordem de Deus; e aqueles que se opõem a ela receberão julgamento sobre si mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Pois os governantes não são um terror para as boas obras, mas para as más obras. Não queres ter medo da autoridade? Faze o que é bom, e terás sua aprovação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Porque ela é uma serva de Deus para o teu bem. Mas, se fizeres o que é mal, teme, porque ela não carrega espada sem razão; pois é uma serva de Deus, uma vingadora para ira contra aquele que pratica o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Portanto, deves obedecer, não apenas por causa da ira, mas também por causa da consciência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Por isso, pagas tributos também. Porque as autoridades são servas de Deus, que se dedicam a todas essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Paga a todos o que lhes é devido: a quem tributo, tributo; a quem imposto, imposto; a quem temor, temor; a quem honra, honra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Não devas a ninguém coisa alguma, exceto o amor uns pelos outros. Porque aquele que ama seu próximo tem cumprido a lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Os mandamentos: \"Não cometerás adultério\", \"Não matarás\", \"Não roubarás\", \"Não cobiçarás\", e se há qualquer outro mandamento também, tudo é resumido na seguinte ordem: \"Amarás o teu próximo como a ti mesmo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'O amor não causa dano ao seu próximo. Portanto, o amor é o cumprimento da lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Por causa disso, tu conheces o tempo, que já é hora de despertardes do sono. Pois agora nossa salvação está mais próxima do que quando cremos no princípio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'A noite está avançada, e o dia vem se aproximando. Vamos, portanto, deixar as obras das trevas, e nos vestir das armas da luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Vamos andar de maneira digna, como em pleno dia; não em orgias ou bebedeiras; não em imoralidade sexual ou depravação; não em contendas ou invejas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Mas revesti-vos do Senhor Jesus Cristo, e não alimenteis a carne, nos seus desejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Recebei aquele que é fraco na fé, mas sem julgar opiniões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Uma pessoa possui fé para comer qualquer coisa; outra, que é fraca, come apenas vegetais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Aquele que come de tudo não despreze aquele que não come; e aquele que não come de tudo não julgue o que come, pois Deus o recebeu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Quem és tu, que julgas um servo alheio? Diante de seu próprio mestre ele fica de pé ou cai. Mas ele ficará de pé, pois o Senhor é poderoso para firmá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Uma pessoa considera um dia mais importante que outro; outra considera os dias iguais. Deixemos que cada pessoa esteja convicta em sua própria mente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Aquele que observa o dia, observa-o para o Senhor; e aquele que come, come para o Senhor, pois dá graças a Deus. Quem não come, por causa do Senhor não come, e também dá graças a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Porque nenhum de nós vive para si, e ninguém morre para si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Pois se vivemos, vivemos para o Senhor, e se morremos, morremos para o Senhor. Logo, vivendo ou morrendo, somos do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Porque, para este propósito, Cristo morreu e reviveu, para que possa ser Senhor tanto dos mortos quanto dos vivos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Mas tu, por que julgas teu irmão? E tu, por que desprezas teu irmão? Pois todos estaremos diante do tribunal de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Pois está escrito: \"Tão certo como Eu vivo,\" diz o Senhor, \"a Mim todo joelho se dobrará, e toda língua dará louvores a Deus.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Assim, cada um de nós dará contas de si mesmo a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Portanto não julguemos mais uns aos outros; mas, ao invés disso, seja do vosso propósito que ninguém coloque um obstáculo ou armadilha diante de seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Eu sei e estou certo no Senhor Jesus de que nada por si mesmo é impuro, exceto para aquele que considera qualquer coisa impura; para ele é impuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Se, por causa de comida, teu irmão é entristecido, não estás mais caminhando no amor. Não destruas com tua comida aquele por quem Cristo morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Então, não permitais que aquilo que considerais bom seja difamado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Pois o reino de Deus não é sobre comida e bebida, mas sobre justiça, paz e a alegria no Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Pois aquele que serve a Cristo desse modo é aceito por Deus, e aprovado pelas pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Então, busquemos as coisas da paz e as que edificam um ao outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Não destruas o trabalho de Deus por causa de comida. Todas as coisas de fato são limpas, mas é errado para a pessoa que come causar tropeço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'É melhor não comer carne, nem beber vinho, nem qualquer coisa que faça teu irmão tropeçar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Guarda entre ti e Deus o que crês a respeito disso. Abençoado é aquele que não se condena naquilo que aprova.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Aquele que duvida é condenado se comer, porque não é segundo a fé; e o que não provém da fé é pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Agora nós, que somos fortes, devemos suportar as fraquezas dos fracos e não devemos agradar a nós mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Que cada um de nós agrade ao seu vizinho, pois isso é bom para a edificação dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Pois também Cristo não agradou a Si mesmo; mas, como está escrito: \"Os insultos daqueles que te insultaram caíram sobre mim.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Pois o que foi escrito anteriormente foi escrito para a nossa instrução, com o objetivo de que, através da paciência e do encorajamento das Escrituras, possamos ter confiança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Que o Deus da paciência e do encorajamento vos conceda permanecer com a mesma mente, uns para com os outros, de acordo com Cristo Jesus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'para que possais adorar a uma só voz o Deus e Pai de nosso Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Portanto acolhei uns aos outros, como Cristo também vos acolheu, para a glória de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Pois digo que Cristo foi feito um ministro da circuncisão em favor da verdade de Deus, para confirmar as promessas dadas aos patriarcas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'e para os gentios glorificarem a Deus pela Sua misericórdia. Assim como está escrito: \"Então confessarei a Ti no meio dos gentios, e cantarei louvores ao Teu Nome.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'E de novo diz: \"Alegrai-vos, gentios, com os povos Dele.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'E novamente diz: \"Louvai ao Senhor, todos vós, gentios; louvai-O, todos os povos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'E ainda Isaías diz: \"Brotará a raiz de Jessé, e o que Se levanta para governar sobre os gentios. Nele, os gentios confiarão.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Agora, que o Deus da esperança vos encha com toda a alegria e paz no que credes, para que possais transbordar de esperança pelo poder do Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Eu mesmo também estou convencido de que vós, meus irmãos, também estais cheios de bondade e de todo conhecimento. Estou convencido de que sois capazes também de exortar uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Porém vos escrevi mais ousadamente sobre algumas coisas com o objetivo de lembrar-vos novamente, por causa do dom que foi me dado por Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'para ser um servo de Cristo Jesus enviado aos gentios, para me oferecer como um sacerdote do Evangelho de Deus. Devo fazer isso, então, para que a oferta dos gentios possa tornar-se aceitável, santificada pelo Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Tenho, então, orgulho em Cristo Jesus nas coisas pertinentes a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Assim, não ousarei falar nada, exceto o que Cristo realizou por meu intermédio para a obediência dos gentios, por palavras e por obras,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'pelo poder de sinais e maravilhas, pelo poder do Espírito Santo; de forma que, de Jerusalém e arredores até o Ilírico, eu tenha anunciado completamente o Evangelho de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'Desse modo, meu desejo tem sido de proclamar o Evangelho, mas não onde Cristo já foi anunciado, para que eu possa construir não em cima de fundação alheia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Assim, como está escrito: \"Aqueles a quem não foi anunciado O verão, e aqueles que não escutaram entenderão.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Por isso, também fui impedido muitas vezes de ir até vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Mas agora, já não tendo mais nenhum lugar nessas regiões e tendo ansiado por tantos anos visitar-vos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'então, quando eu for para a Espanha, espero ver-vos de passagem e ser encaminhado por vós, depois de aproveitar de vossa companhia por um tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Mas agora, estou indo para Jerusalém para servir os santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Pois a Macedônia e a Acaia tiveram prazer em fazer uma certa contribuição para os pobres dentre os santos em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Decidiram assim porque, de fato, eles são devedores; pois, se os gentios compartilharam das coisas espirituais com eles, devem também servir-los nas coisas materiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Então, quando eu tiver completado essa tarefa, e tiver certeza de que eles receberam essa oferta, passando por vós, irei à Espanha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Eu sei que, quando for até vós, irei na plenitude das bênçãos de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'E a vós, irmãos, peço, pelo nosso Senhor Jesus Cristo, e pelo amor do Espírito, que luteis juntamente comigo nas vossas orações a Deus por mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'Ore para que eu possa ser resgatado daqueles que são desobedientes na Judeia, e que meu serviço por Jerusalém seja aceitável aos santos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'para que possa ir até vós em alegria, pela vontade de Deus, e que possa, juntamente convosco, achar descanso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Que a paz de Deus esteja com todos vós. Amém!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Eu vos recomendo nossa irmã Febe, serva da igreja que está em Cencreia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'para que possais recebê-la no Senhor, de uma maneira digna dos santos, e que a ajudeis em qualquer coisa que ela possa precisar de vós. Pois ela mesma tornou-se uma ajudante de muitos, inclusive de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Cumprimentai Priscila e Áquila, meus companheiros de trabalho em Jesus Cristo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'que por minha vida arriscaram suas próprias vidas. Eu os agradeço, e não apenas eu, mas também todas as igrejas dos gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Cumprimentai a igreja que está na casa deles. Cumprimentai meu amado Epêneto, o primeiro fruto da Ásia para Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Cumprimentai Maria, que trabalhou arduamente por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Cumprimentai Andrônico e Júnias, meus parentes e companheiros de prisão, que são proeminentes entre os apóstolos, que também estavam em Cristo antes de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Cumprimentai Amplíato, meu amado no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Cumprimentai Urbano, nosso companheiro de trabalho em Cristo, e meu amado Estáquis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Cumprimentai Apeles, o aprovado em Cristo. Cumprimentai aqueles que são da família de Aristóbulo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Cumprimentai meu parente Herodião. Cumprimentai aqueles da família de Narciso, que estão no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Cumprimentai Trifena e Trifosa, que trabalham arduamente no Senhor. Cumprimentai a amada Pérside, que trabalhou muito no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Cumprimentai Rufo, escolhido pelo Senhor, e a mãe dele e minha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Cumprimentai Asíncrito, Flegonte, Hermes, Pátrobas, Hermas e os irmãos que estão com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Cumprimentai Filólogo e Júlia, Nereu e sua irmã, Olimpas e todos os santos que estão com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Cumprimentai-vos uns aos outros com um beijo santo. Todas as igrejas de Cristo vos cumprimentam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Agora, insisto convosco, irmãos, que penseis sobre aqueles que estão causando divisões e tropeços, que vão além do ensinamento que aprendestes. Afastai-vos deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Pois pessoas como essas não servem ao nosso Senhor Jesus Cristo, mas a seus próprios ventres. Com suas palavras doces e bajulantes, eles enganam os corações dos inocentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Pois vosso exemplo de obediência alcança a todos. Eu me alegro, portanto, em vós, mas quero que sejais sábios em relação ao bem, e puros em relação ao mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'O Deus da paz em breve esmagará Satanás debaixo dos vossos pés. Que a graça de nosso Senhor Jesus Cristo esteja convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Timóteo, meu companheiro de trabalho, cumprimenta-vos; bem como meus parentes Lúcio, Jasão e Sosípatro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Eu, Tércio, que escrevo esta carta, cumprimento-vos no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Gaio, hospedeiro para mim e para toda igreja, vos cumprimenta. Erasto, o tesoureiro da cidade, e também o irmão Quarto, cumprimentam-vos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, '');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Agora, Àquele que é capaz de fazer-vos ficar de pé, de acordo com o meu Evangelho e com a pregação de Jesus Cristo, segundo a revelação do mistério guardado em segredo desde há muito tempo atrás,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'mas que agora foi revelado, e tornou-se conhecido a todas as nações pelas Escrituras proféticas, segundo o mandamento do Deus eterno, para a obediência da fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Ao único e sábio Deus, por meio de Jesus Cristo, seja glória para sempre. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paulo, chamado por Jesus Cristo para ser um apóstolo pela vontade de Deus, e Sóstenes nosso irmão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'para a igreja de Deus em Corinto, àqueles que foram santificados em Jesus Cristo, chamados para ser um povo santo. Nós também escrevemos para todos os chamados no nome do nosso Senhor Jesus Cristo em todo lugar, Senhor deles e nosso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Que graça e paz sejam convosco da parte de Deus nosso Pai e do Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Sempre dou graças ao meu Deus por vós, por causa da graça de Deus que Jesus Cristo vos deu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Ele vos tem feito ricos em tudo, em toda a palavra e com todo o conhecimento,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'assim como o testemunho de Cristo foi confirmado como verdade entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'De modo que não vos falta nenhum dom espiritual, enquanto ansiosamente esperais pela revelação de nosso Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Ele também vos fortalecerá para o final, para serdes irrepreensíveis no dia do nosso Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Deus é fiel, o qual vos chamou na comunhão de Seu filho, Jesus Cristo, nosso Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Agora rogo-vos irmãos em nome de nosso Senhor Jesus Cristo, que vivais em harmonia uns com os outros, e que não haja divisões entre vós. Rogo-vos que estejais unidos com o mesmo pensamento e pelo mesmo propósito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Pois ficou claro para mim, meus irmãos, pelo que me disse a família de Cloé, que há divisões entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Refiro-me ao que cada um de vós diz: \"Eu sou de Paulo\", ou \"Eu sou de Apolo\", ou \"Eu sou de Cefas\", ou \"Eu sou de Cristo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Está Cristo dividido? Foi Paulo crucificado por vós? Fostes batizados em nome de Paulo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Agradeço a Deus por não ter batizado nenhum de vós, exceto Crispo e Gaio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Para que ninguém diga que fostes batizados em meu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Também batizei a casa de Estéfanas. Além destes, eu não sei se batizei algum outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Porque Cristo não me enviou para batizar, mas para pregar o evangelho. Não com palavras de sabedoria humana, para que a cruz de Cristo não seja anulada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Pois a mensagem sobre a cruz é loucura para aqueles que estão se perdendo. Mas entre aqueles que Deus está salvando, é o poder de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Pois está escrito: \"Destruirei a sabedoria dos sábios e frustrarei a inteligência dos instruídos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Onde está o sábio? Onde está o estudioso? Onde está o argumentador deste mundo? Deus não tornou a sabedoria do mundo em loucura?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Visto que o mundo, em sua sabedoria, não conheceu a Deus, aprouve a Deus através da loucura da pregação salvar aqueles que creem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Porque os judeus pedem por milagres e os gregos buscam sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Mas nós pregamos a Cristo crucificado, escândalo para os judeus e loucura para os gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Mas para aqueles a quem Deus chamou, tanto judeus quanto gregos, nós pregamos a Cristo, poder e sabedoria de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Porque a loucura de Deus é mais sábia do que os homens, e a fraqueza de Deus é mais forte do que os homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Olhai para o vosso chamado, irmãos. Não muitos de vós ereis sábios segundo os padrões humanos, nem muitos ereis poderosos, nem muitos ereis de nobre nascimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Mas Deus escolheu as coisas loucas do mundo para envergonhar os sábios; e escolheu o que é fraco no mundo para envergonhar o que é forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Deus escolheu o que é humilde e desprezado no mundo, e escolheu as coisas que são consideradas como nada, para reduzir a nada as coisas que são tidas como valiosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Ele fez isso para que ninguém tivesse motivo de se gloriar diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Mas vós estais em Cristo Jesus por causa do que Deus fez. Ele se tornou para nós sabedoria de Deus, justiça, santificação e redenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Por isso as escrituras dizem: \"Aquele que se gloria, glorie-se no Senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Quando eu vim a vós, irmãos, não vim com eloquência de discurso ou sabedoria, como se tivesse proclamado os mistérios ocultos sobre Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Pois decidi não saber nada quando eu estava entre vós, exceto Jesus Cristo, e Ele crucificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'E eu estava convosco em fraqueza, em medo e em muito tremor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'E minha palavra e a minha proclamação não foram com palavras persuasivas de sabedoria. Em vez disso, foram com demonstração do Espírito e de poder,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'de forma que a vossa fé não esteja na sabedoria humana, mas no poder de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Agora, nós falamos com sabedoria entre os maduros, mas não a sabedoria deste mundo, ou a dos governantes desta era, que estão decaindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Mas falamos com a sabedoria de Deus em verdades ocultas, a sabedoria oculta, a qual Deus predestinou antes das eras para nossa glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Nenhum dos governantes desta era conheceu essa sabedoria, pois se a tivessem conhecido naquele tempo, eles não teriam crucificado o Senhor da glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Mas como está escrito: \"As coisas que nenhum olho viu, nenhum ouvido ouviu, nenhuma mente imaginou, são as coisas que Deus preparou para aqueles que o amam\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Estas são as coisas que Deus revelou para nós através do Espírito. Pois o Espírito examina tudo, até as coisas profundas de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Pois quem conhece os pensamentos de uma pessoa a não ser o espírito da pessoa que nele está? Assim também, ninguém conhece as coisas profundas de Deus a não ser o Espírito de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Mas nós não recebemos o espírito do mundo, e sim o Espírito que é de Deus, para que possamos conhecer as coisas livremente dadas a nós por Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Nós falamos sobre essas coisas em palavras que a sabedoria do homem não pode ensinar, mas que o Espírito nos ensina. O Espírito interpreta palavras espirituais com sabedoria espiritual.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Quem não é espiritual não recebe as coisas que pertencem ao Espírito de Deus, pois são loucura para ele. E não pode conhecê-las porque são discernidas espiritualmente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Quem é espiritual julga todas as coisas, mas ele não está sujeito ao julgamento de outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, '\"Pois quem pode conhecer a mente do Senhor, que possa instruí-Lo?\" Mas nós temos a mente de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Irmãos, eu não vos pude falar como a pessoas espirituais, mas como a pessoas carnais, como a crianças em Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Eu vos alimentei com leite, não com alimento sólido, porque não estáveis prontos. E, mesmo agora, não estais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Pois vós continuais carnais. Porque, se existe ciúme e contenda entre vós, não estais vivendo de acordo com a carne e andando por padrões humanos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Porque, quando alguém diz: \"Eu sigo Paulo,\" e outro diz: \"Eu sigo Apolo\", não estais vós vivendo segundo o homem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Quem então é Apolo? E quem é Paulo? Servos por meio dos quais acreditastes, conforme a tarefa que o Senhor deu a cada um.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Eu plantei, Apolo regou, mas Deus deu o crescimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Então, nem o que planta, nem o que rega são nada. Mas é Deus quem dá o crescimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Agora, o que planta e o que rega são um, e cada um receberá sua recompensa de acordo com seu próprio trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Porque somos cooperadores de Deus. Vós sois jardim e edifício de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'De acordo com a graça de Deus que me foi dada como um sábio construtor, eu lancei a fundação, e outro constrói sobre ela. Mas que cada homem cuide da maneira como constrói sobre ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Porque não se pode lançar outra fundação senão a que já foi lançada, que é Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Agora, se alguém constrói sobre a fundação com ouro, prata, pedras preciosas, madeira, feno ou palha,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'sua obra será revelada, pois a luz do dia irá revelar. Porque será revelada no fogo; o fogo testará a qualidade do que cada um fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Se a obra de alguém permanecer, este receberá recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Mas, se a obra de alguém for queimada, sofrerá perda. Este será salvo, mas como que escapando pelo fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Não sabeis que sois templo de Deus e que o Espírito de Deus vive em vós?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Se alguém destrói o templo de Deus, Deus o destruirá. Porque o templo de Deus, que sois vós, é santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Que ninguém engane a si mesmo. Se alguém entre vós pensa que é sábio neste tempo, que se torne um \"tolo\", para que ele possa se tornar sábio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Porque a sabedoria deste mundo é tolice para Deus. Pois está escrito: \"Ele apanha o sábio em sua astúcia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'E novamente: \"O Senhor sabe que o pensamento dos sábios é fútil\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Então não mais se orgulhem nas pessoas! Porque todas as coisas são vossas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'seja Paulo, ou Apolo, ou Cefas, ou o mundo, ou a vida, ou a morte, ou coisas do presente, ou coisas do futuro. Tudo é vosso');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'e vós sois de Cristo, e Cristo é de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'É assim que uma pessoa deveria nos considerar, como servos de Cristo e administradores dos mistérios de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Nesse sentido, é um requisito para os administradores que sejam dignos de confiança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Mas para mim é insignificante que eu seja julgado por vós ou por qualquer tribunal humano. Pois, nem a mim mesmo julgo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Eu não estou consciente de nenhuma acusação sendo feita contra mim; mas isso não significa que eu seja inocente. É o Senhor quem me julga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Portanto, não julgueis qualquer coisa antes do tempo, antes que venha o Senhor. Ele trará à luz as coisas ocultas da escuridão, e revelará os propósitos do coração. Então, cada um receberá o seu louvor da parte de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Agora, irmãos, eu apliquei estes princípios a mim mesmo e a Apolo por causa de vós, para que aprendais conosco: \"Não vades além do que está escrito\"; assim, ninguém fica se orgulhando a favor de um e desprezando ao outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Pois, quem vê alguma diferença entre vós e os outros? O que tendes que não recebestes gratuitamente? Se o recebestes gratuitamente, por que vos gloriais como se não tivesseis recebido?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Vós já tendes tudo o que poderíeis querer! Já vos tornastes ricos! Começastes a reinar independente de nós! De fato, eu desejo que reinásseis, então poderíamos reinar convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Pois penso que Deus expôs a nós, os apóstolos, em último lugar, e como homens sentenciados à morte. Nós temos nos tornado um espetáculo ao mundo, aos anjos e aos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Nós somos loucos por causa de Cristo, mas vós sois sábios em Cristo. Nós somos fracos, mas vós sois fortes. Vós sois considerados em honra, mas nós somos considerados em desonra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Até a presente hora, estamos famintos e sedentos, estamos miseravelmente vestidos, somos brutalmente espancados, e não temos casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'Trabalhamos duro, com as próprias mãos. Quando somos ofendidos, nós bendizemos. Quando somos perseguidos, nós aguentamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Quando somos caluniados, nós falamos com bondade. Nós nos tornamos, e ainda somos considerados, o lixo do mundo e imundícia de todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Eu não escrevo essas coisas para vos envergonhar, mas para corrigir-vos como meus filhos amados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Pois, mesmo que tenhais dez mil instrutores em Cristo, não tendes muitos pais. Pois, eu me tornei vosso pai em Cristo Jesus através do Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Assim, insisto que sejais meus imitadores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Por isso, vos envio Timóteo, meu amado e fiel filho no Senhor. Ele vos lembrará os meus caminhos em Cristo, assim como ensino em todo lugar e em cada igreja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Alguns de vós vos tornastes arrogantes, agindo como se eu não estivesse para ir visitar-vos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Mas logo irei a vós, se o Senhor quiser. Então conhecerei não meramente o discurso desses que são tão arrogantes, mas verei o poder deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Pois o reino de Deus não consiste em palavra, mas em poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'O que quereis? Irei a vós com uma vara ou com amor e espírito de gentileza?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Nós ouvimos a notícia de que há imoralidade sexual entre vós, um tipo de imoralidade que nem mesmo é permitida entre os gentios. A notícia é que um de vós está dormindo com a esposa de seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Sois tão arrogantes! Em vez disso, não deveríeis vos lamentar? Quem fez isso deve ser removido de entre vós!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Pois, apesar de eu estar ausente em corpo, mas ainda presente em espírito, já julguei aquele que fez isso, como se eu estivesse aí.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Quando vos reunirdes no Nome de nosso Senhor Jesus, e meu espírito estando aí também no poder de nosso Senhor Jesus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'entregai esse homem a Satanás para a destruição da carne, assim então seu espírito poderá ser salvo no dia do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'O vosso orgulho não é bom. Não sabeis que um pouco de fermento leveda toda a massa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Purificai-vos do velho fermento para que sejais uma nova massa, assim como sois agora, pães não levedados. Pois Cristo, nosso Cordeiro Pascal, foi sacrificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Assim, celebremos a festa, não com fermento velho, o fermento do mau comportamento e da maldade, mas com o pão não levedado da sinceridade e da verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Eu vos escrevi com minha letra para não vos associardes com pessoas sexualmente imorais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'De maneira nenhuma me refiro às pessoas imorais deste mundo, ou aos gananciosos, aos trapaceiros ou aos idólatras, uma vez que para estar longe deles precisaríeis sair do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Mas agora estou vos escrevendo para não vos associardes a ninguém que é chamado de irmão, mas que está vivendo em imoralidade sexual, ou que é ganancioso, ou é um idólatra, ou é caluniador, ou é um beberrão ou um trapaceiro. Nem mesmo comais uma refeição com tal pessoa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Pois, como posso estar envolvido com o julgamento daqueles que são de fora da igreja? Em vez disso, não julgais aqueles que estão dentro da igreja?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Mas Deus julga aqueles que estão fora: \"Remova a pessoa má de entre vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Quando um de vós tem uma disputa contra outro irmão, como se atreve a ir ao tribunal perante os juízes incrédulos e não perante os santos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Vós não sabeis que os santos julgarão o mundo? E, se vós julgareis o mundo, não sois capazes de resolver questões de pouca importância?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Não sabeis que julgaremos os anjos? Quanto mais as coisas pertencentes a esta vida!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Portanto, se vós tendes que fazer julgamentos sobre coisas normais da vida, por que colocais tais casos diante daqueles que não têm aceitação na igreja?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Eu falo isso para vossa vergonha. Não há alguém entre vós sábio o suficiente para resolver a disputa entre irmãos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'No entanto, um crente vai para o tribunal contra outro crente, e isso é colocado diante de um juiz incrédulo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'O fato de existir disputas judiciais entre cristãos já é uma derrota para vós. Porque não sofreis o mal? Porque não permitis a vós mesmos serdes traídos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Mas vós tendes feito o mal e traído uns aos outros, sendo estes vossos próprios irmãos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Não sabeis vós que os injustos não herdarão o Reino de Deus? Não vos enganeis: os sexualmente imorais, os idólatras, os adúlteros, os efeminados, e os homens que mantêm relação sexual com outros homens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'os ladrões, os gulosos, os bêbados, os difamadores e os roubadores, nenhum deles herdará o reino de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Tais fostes alguns de vós. Mas vós fostes lavados, santificados e justificados com Deus no nome do Senhor Jesus Cristo e pelo Espírito de nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, '\"Todas as coisas são lícitas para mim\", mas nem tudo me convém. \"Todas as coisas são legítimas para mim\", mas eu não serei dominado por nenhuma delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, '\"Os alimentos são para o estômago, e o estômago é para os alimentos\", mas Deus destruirá a ambos. O corpo não é para imoralidade sexual, porém para o Senhor, e o Senhor para o corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Deus ressuscitou o Senhor e também nos ressuscitará pelo Seu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Vós não sabeis que vossos corpos são membros de Cristo? Porventura tomaria os membros de Cristo e os associaria a uma prostituta? Claro que não!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Não sabeis que quem se une a uma prostituta torna-se um corpo com ela? Como diz a escritura: \"Os dois se tornarão uma só carne.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Todavia, quem se une ao Senhor torna-se um espírito com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Fugi da imoralidade sexual! Qualquer outro pecado que uma pessoa comete é fora do corpo, mas a pessoa sexualmente imoral peca contra seu próprio corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Não sabeis que vossos corpos são templo do Espírito Santo, que mora em vós, os quais recebestes da parte de Deus, e que não sois de vós mesmos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Pois, fostes comprados por um preço. Portanto, glorificai a Deus em vossos corpos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Com relação às coisas que escrevestes: \"É bom para o homem não tocar em mulher\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Mas, por causa dos atos imorais e das tentações, cada homem deve ter a sua própria esposa, e cada mulher deve ter o seu próprio marido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'O marido deve dar para a esposa os seus direitos conjugais; e, do mesmo modo, a esposa para com o marido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Não é a esposa que tem autoridade sobre seu próprio corpo, e sim, o marido. Da mesma forma, não é o marido que tem autoridade sobre seu próprio corpo, mas a esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Não vos priveis um ao outro, exceto quando houver concordância mútua e por um período de tempo específico, para que possam se dedicar à oração. Então, depois disso, uni-vos novamente. Assim, Satanás não vos tentará por causa da falta de controle.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Porém eu vos digo estas coisas como concessão e não como uma ordem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Eu gostaria que todos fôsseis como eu; todavia cada um tem seu próprio dom de Deus, um de um tipo e outro de outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Digo aos não casados e às viúvas que é bom que permaneçam sem se casar assim como eu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Mas, se eles não podem exercer autocontrole, devem se casar. Pois é melhor que se casem do que arderem em paixão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Agora para os casados dou esta ordem, não eu, mas o Senhor: \"a esposa não deve se separar de seu marido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Mas se ela se separar do seu marido, deverá permanecer sem se casar, ou que se reconcilie com ele. Assim como \"o marido não deve se separar da sua esposa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Mas, para os demais, digo eu, não o Senhor, que se algum irmão tem uma esposa descrente e se ela está contente de viver com ele, ele não deve se separar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Se uma mulher tem um marido descrente e ele está contente em viver com ela, ela não deve se separar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Pois o marido descrente é santificado por causa da sua esposa, e a mulher descrente é santificada porque o seu marido é crente. Caso contrário, os seus filhos poderiam ser impuros, quando na realidade são santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Mas, se o companheiro não cristão partir, deixa-o ir. Nesses casos, o irmão ou a irmã não estão presos aos seus votos. Deus nos chamou para viver em paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Pois, como sabes, mulher, se vais salvar o teu marido? Ou como sabes, homem, se vais salvar tua esposa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Somente viva cada um a vida que o Senhor lhe designou e para a qual lhe chamou. Esta é a minha ordenança em todas as igrejas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Era alguém circuncidado quando foi chamado a crer? Ele não deve tentar esconder a marca da circuncisão. Era alguém incircunciso quando Deus o chamou à fé? Ele não deve ser circuncidado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Por isso, nem a circuncisão nem a incircuncisão importam. O que importa é obedecer as ordens de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Cada um permaneça no chamado em que estava quando Deus o chamou para crer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Eras tu um escravo quando Deus te chamou? Não te preocupes com isso. Mas se te tornares livre, fazes bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Para alguém que é chamado pelo Senhor como escravo, este é um homem livre para o Senhor. Do mesmo modo, aquele que é livre quando foi chamado a crer, é escravo de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Vós fostes comprados por um preço, não vos torneis escravos dos homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Irmãos, assim como cada um de nós éramos quando fomos chamados a crer, vamos permanecer assim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Agora, em relação àqueles que nunca foram casados, eu não tenho uma ordem do Senhor. Todavia dou minha opinião como alguém que, pela misericórdia do Senhor, é confiável.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Portanto eu penso que, por causa das angústias presentes, é bom para um homem permanecer como ele está.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Tu estás comprometido com uma mulher? Não tentes te livrar dela. Estás livre de uma esposa? Não procures uma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'Mas se casares, não cometes um pecado. E se uma mulher solteira se casa, ela não comete pecado. Já aquele que se casa terá muitos tipos de problemas enquanto viver, e eu gostaria de te poupar disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'Mas, isto eu digo irmãos: o tempo é curto. De agora em diante, deixai aqueles que têm esposas viverem como se não as tivessem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'Aqueles que choram como se não chorassem; os que se alegram, como se não se alegrassem; e os que compram, como se não tivessem posse de coisa alguma;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'e os que negociam com o mundo, como se não negociassem; porque a presente forma deste mundo está chegando ao fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Eu gostaria que vós ficásseis livres de preocupações. O homem não casado está preocupado com as coisas do Senhor, em como agradar a Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Mas o homem casado está preocupado com coisas do mundo, em como agradar sua esposa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Ele está dividido. Assim também, a mulher não casada ou a virgem está preocupada com as coisas do Senhor, em como ser santa no corpo e no espírito. Mas a mulher casada está preocupada com as coisas do mundo, em como agradar seu marido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Eu digo isto para o vosso próprio benefício, e não para vos pressionar, mas o correto é que possais ser dedicados ao Senhor sem nenhuma distração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Mas se alguém pensa que não está tratando sua noiva virgem com respeito, e se ela está passando da idade de se casar, e se tiver que ser assim, faça o que quiser. Ele não peca; que se casem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Mas se ele está firme em seu coração e não está sob pressão, mas controla suas próprias vontades, e se decidiu em seu próprio coração fazer isso, manter sua própria noiva virgem, fará bem');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Então, aquele que casa com sua noiva virgem faz bem, e o que escolhe não casar, faz ainda melhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Uma mulher está ligada ao seu marido enquanto ele viver. Mas, se o marido dela morrer, ela está livre para casar com quem ela desejar, mas somente no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Ainda em meu julgamento, ela seria mais feliz vivendo como está. E penso que também tenho o Espírito de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Agora, sobre comida sacrificada aos ídolos, sabemos que \"todos temos conhecimento\". O conhecimento ensoberbece, mas o amor edifica.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Se alguém pensa que sabe algo, essa pessoa ainda não sabe como deveria saber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Mas se alguém ama a Deus, essa pessoa é conhecida por Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Então, sobre comida sacrificada aos ídolos, sabemos que \"um ídolo neste mundo não é nada\", e \"que não existe Deus a não ser o Deus único\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Pois existem os chamados deuses, seja no céu ou na terra, assim como há vários \"deuses\" e muitos \"senhores\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Para nós, contudo, \"existe apenas um Deus, o Pai, de quem são todas as coisas, e para quem vivemos, e um Senhor Jesus Cristo, por meio de quem todas as coisas existem, e por meio do qual existimos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Contudo nem todos possuem esse conhecimento. Ao contrário, alguns anteriormente praticaram adoração a ídolos, e eles comem esse alimento como sendo algo sacrificado a um ídolo. Assim, a consciência deles está corrompida porque ela é fraca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Mas não é a comida que nos apresentará diante de Deus. Nós não somos piores se não comemos, nem melhores se comemos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Mas cuidai para que a vossa liberdade não se torne um motivo para fazer tropeçar quem seja fraco na fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Se alguém vir a vós, que tendes conhecimento, comendo uma refeição em um templo de ídolos, não estará sua fraca consciência encorajada a comer o que é oferecido a ídolos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Então, por causa do vosso entendimento sobre a verdadeira natureza dos ídolos, o mais fraco, o irmão pelo qual Cristo morreu, é destruído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Desse modo, quando pecais contra vossos irmãos, ferindo-lhes a fraca consciência, pecais contra Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Portanto, se o alimento faz meu irmão tropeçar, eu não comerei carne novamente, para não fazer meu irmão cair.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Não sou livre? Não sou um apóstolo? Eu não vi a Jesus nosso Senhor? Vós não sois meu trabalho no Senhor?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Se não sou um apóstolo para outros, ao menos o sou para vós, porque sois a prova do meu apostolado no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Esta é a minha defesa para aqueles que me examinam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Não temos nós o direito de comer e beber?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Não temos nós o direito de levar conosco uma esposa que seja crente, assim como fazem os demais apóstolos, e os irmãos do Senhor e Cefas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Ou é apenas Barnabé e eu que devemos trabalhar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Quem serve como um soldado às suas próprias custas? Quem planta uma vinha e não come de seus frutos? Ou quem cuida de um rebanho e não bebe de seu leite?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Digo isto baseado em autoridade humana? Não diz isso também a Lei?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Porque está escrito na Lei de Moisés: \"Não atarás a boca do boi quando ele estiver pisando os grãos\". É com os bois realmente que Deus Se importa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Não está Ele falando sobre nós? Foi escrito para nós, porque quem ara a terra, deve arar com esperança, e o que debulha, deve debulhar com a confiança de compartilhar da colheita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Se semeamos coisas espirituais entre vós, seria demais colhermos coisas materiais de vós?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Se outros exercem esse direito por meio de vós, não teríamos nós ainda mais? Não obstante, nós não reivindicamos esse direito, mas suportamos tudo ao invés de sermos um obstáculo para o Evangelho de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Vós não sabeis que aqueles que servem no templo, recebem sua comida do templo? E aqueles que servem no altar repartem o que é oferecido no altar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Do mesmo modo, o Senhor ordenou àqueles que proclamam o Evangelho que vivam do Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Mas eu não reivindiquei nenhum desses direitos. E não escrevo isso para que algo seja feito por mim. Eu preferiria morrer a que alguém me retirasse esse orgulho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Pois, se eu prego o Evangelho, não tenho razão para vanglória, porque tenho obrigação de fazer isso. E ai de mim se não pregar o Evangelho!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Porque, se de boa vontade eu faço isso, tenho uma recompensa; mas se não de boa vontade, ainda tenho uma responsabilidade que me foi confiada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Qual então é a minha recompensa? Que quando eu pregue, eu possa oferecer o Evangelho sem custo, e então não faço uso de meu direito no Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Porque mesmo eu sendo livre de tudo, tornei-me um servo de todos, a fim de que eu pudesse ganhar mais pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Para os judeus, eu me tornei como um judeu, a fim de ganhar judeus. Àqueles sujeitos à Lei, me tornei como alguém sujeito à lei, a fim de ganhá-los pela Lei..');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Para os que estão sem lei, me tornei como sem lei, embora não estivesse sem a Lei de Deus, e sim sob a Lei de Cristo. Eu fiz isto para ganhar aqueles sem lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Para os fracos eu me tornei fraco, com o propósito de ganhar os fracos. Eu me tornei todas as coisas para todas as pessoas, para que possa, por todos os meios, salvar alguns.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'E eu faço todas as coisas por causa do Evangelho, de modo a participar das suas bênçãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Não sabeis que em uma corrida todos correm a corrida, mas apenas um recebe o prêmio? Então, correi para ganhar o prêmio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Um atleta exercita autocontrole em todo seu treinamento. Eles fazem isso para receber uma coroa que é perecível, mas nós corremos para que possamos receber uma coroa imperecível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Portanto, não corro sem propósito, nem luto golpeando o ar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'mas subjugo meu corpo e o faço um escravo, para que, após ter pregado para outros, eu mesmo não seja desqualificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Quero que saibais, irmãos, que os nossos pais estiveram todos debaixo da nuvem, e todos atravessaram o mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'Todos foram batizados por Moisés na nuvem e no mar,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'e todos comeram a mesma comida espiritual,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'e todos beberam a mesma bebida espiritual. Pois eles beberam de uma rocha espiritual que os acompanhava, e essa rocha era Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Entretanto, Deus não se agradou da maioria deles, e seus cadáveres foram esparramados pelo deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Estas coisas são exemplos para nós, para que não desejemos fazer coisas más como eles fizeram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Não sejais idólatras, como alguns deles foram. Como está escrito: \"As pessoas se sentaram para comer e beber, e se levantaram para se divertir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Não vamos cometer imoralidade sexual, como muitos deles fizeram, visto que, por causa disso, vinte e três mil pessoas morreram em um dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Nem coloquemos Cristo à prova, como muitos deles fizeram, e foram destruídos por serpentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Também não murmureis, como muitos deles fizeram, e foram destruídos por um anjo da morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Ora, estas coisas aconteceram a eles como exemplo para nós. Elas foram escritas para nossa instrução - para nós, sobre os quais o fim dos tempos tem vindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Portanto, qualquer um que pensa que está em pé tenha cuidado para que não caia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Nenhuma tentação nos sobreveio que não seja comum a toda humanidade. Mas Deus é fiel. Ele não deixará que sejais tentados além de vossas capacidades, mas com a tentação Ele também providenciará a forma de escape, para que possais suportá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Portanto, meus amados, fuji da idolatria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Eu vos falo como a pessoas sensatas; assim, podeis julgar o que eu digo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'O cálice da bênção que nós abençoamos, não é o compartilhar do sangue de Cristo? O pão que nós partimos, não é o compartilhar do corpo de Cristo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Porque há um só pão, nós que somos muitos somos um corpo. Todos nós participamos juntos de um só pão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Olhai para o povo de Israel: não são aqueles que comem os sacrifícios participantes do altar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'O que estou dizendo então? Que um ídolo é alguma coisa? Ou que aquela comida sacrificada para um ídolo é alguma coisa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Mas eu digo que as coisas que os pagãos gentios sacrificam, eles oferecem estas coisas para demônios e não para Deus. Não quero que sejais participantes com demônios!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Vós não podeis beber o cálice do Senhor e o cálice dos demônios. Não podeis ter associação com a mesa do Senhor e a mesa dos demônios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Ou vamos provocar o ciúme do Senhor? Nós seríamos mais fortes que Ele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, '\"Todas as coisas são lícitas\", mas nem todas são benéficas. \"Todas as coisas são lícitas\", mas nem todas edificam as pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Ninguém deve procurar seu próprio bem. Em vez disso, cada um deve procurar o bem do seu próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Podeis comer qualquer coisa vendida no mercado, sem questões de consciência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Pois, a terra e a sua plenitude são de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Se um não crente vos convidar para comer um alimento, e desejardes ir, comei tudo o que estiver preparado diante de vós, nada perguntando por questões de consciência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Mas se alguém disser: \"Esta comida foi de um sacrifício pagão,\" não a comais. Isto é por causa daquele que vos informou, e por causa da consciência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Eu não digo da vossa própria consciência, mas a consciência da outra pessoa. Pois, por que minha liberdade deve ser julgada pela consciência do outro?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Se eu partilho do alimento com gratidão, por que sou insultado por causa daquilo que dou graças?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Portanto, quer comais ou bebais, ou façais qualquer outra coisa, fazei tudo para a glória de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Não vos torneis motivo de tropeço a judeus ou a gregos, ou à igreja de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Assim como eu tento agradar a todos em todas as coisas, não procurando meu benefício, mas o de muitos, para que eles possam ser salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Sede meus imitadores, assim como sou de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Agora, eu vos louvo porque vos lembrais de mim em tudo, e vos agarrastes às tradições exatamente como as entreguei a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Agora, quero que entendais que Cristo é a cabeça de todo homem, que o homem é a cabeça da mulher, e que Deus é a cabeça de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Qualquer homem que ora ou profetiza com sua cabeça coberta desonra sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Mas qualquer mulher que ora ou profetiza com sua cabeça descoberta desonra sua cabeça; pois é da mesma forma como se sua cabeça estivesse rapada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Pois, se uma mulher não cobrir sua cabeça, ela deve cortar seu cabelo curto. Se é vergonhoso para a mulher ter seu cabelo cortado ou rapar sua cabeça, que ela cubra sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Pois um homem não deve ter sua cabeça coberta, já que ele é a imagem e glória de Deus. Mas a mulher é a glória do homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Pois, o homem não foi feito da mulher, mas a mulher foi feita do homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Pois também o homem não foi criado para a mulher; mas a mulher para o homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Por isso, a mulher deve ter um símbolo de autoridade na sua cabeça, por causa dos anjos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Entretanto, no Senhor, a mulher não é independente do homem, nem é o homem independente da mulher.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Pois, assim como a mulher vem do homem, da mesma forma o homem vem da mulher. E todas as coisas vêm de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Julgai por vós mesmos: é adequado para uma mulher orar a Deus com sua cabeça descoberta?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'A natureza por si mesma não vos ensina que, se um homem tem cabelo longo, é uma vergonha para ele?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'A natureza não vos ensina que se uma mulher tiver cabelos compridos, isto é a sua glória? Pois seu cabelo lhe foi dado em lugar do véu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Mas, se alguém quer causar contendas sobre isto, nós não temos tal prática, nem as igrejas de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Nas seguintes instruções, porém, eu não vos louvo, porque quando vos juntais, não é para melhor, mas para pior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Assim, em primeiro lugar, eu ouvi que quando vos reunis na igreja, há divisões entre vós, e em parte acredito nisto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Pois é preciso que haja facções entre vós, de tal forma que aqueles que são aprovados possam ser vistos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Pois, quando vos reunis, não é a ceia do Senhor que comeis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Quando comeis, cada um come sua própria comida antes que os outros façam a sua refeição. Um está faminto, e outro fica bêbado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Não tendes casas onde comer e beber? Vós ignorais a igreja de Deus e humilhais aqueles que nada têm? O que devo dizer-vos? Eu deveria vos parabenizar? Eu não vos parabenizo por isto!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Porque eu recebi do Senhor o que também vos passei, que o Senhor Jesus, na noite em que Ele foi traído, tomou o pão;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'depois de ter dado graças, Ele o partiu e disse: \"Este é o Meu corpo, que é para vós; fazei isto em memória de Mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Da mesma forma, após a ceia, Ele pegou o cálice e disse: \"Este cálice é a Nova Aliança do Meu sangue. Fazei isto, sempre que beberdes, em memória de Mim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Pois, toda vez que comerdes este pão e beberdes este cálice, proclamais a morte do Senhor, até que Ele venha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'De sorte que, aquele que comer do pão ou beber do cálice do Senhor de maneira indigna será culpado do corpo e do sangue do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Que a pessoa examine-se a si mesmo primeiro, e assim coma do pão e beba do cálice.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Pois aquele que come e bebe sem discernimento do corpo, come e bebe julgamento para si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Por isso há entre vós muitos fracos e doentes, e alguns que já morreram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Mas se examinássemos a nós mesmos, não seríamos julgados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Quando, porém, somos julgados pelo Senhor, somos disciplinados, para que não sejamos condenados juntamente com o mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Portanto, meus irmãos, quando vos juntardes para comer, aguardai uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Se alguém está faminto, que coma em casa, de tal forma que quando vos juntardes não seja para julgamento. E sobre as outras coisas que vós escrevestes, darei instruções quando eu chegar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Sobre os dons espirituais, irmãos, eu não quero que sejais desinformados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Vós sabeis que quando éreis pagãos, éreis levados por ídolos mudos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Portanto quero que saibais que ninguém que fala pelo Espírito de Deus pode dizer: \"Jesus é maldito\". E ninguém pode dizer: \"Jesus é Senhor\", senão pelo Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Agora, há diferentes tipos de dons, mas o mesmo Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'E há diferentes tipos de ministérios, mas o mesmo Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'E há diferentes tipos de trabalhos, mas é o mesmo Deus quem os faz possível em todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'A cada um é dada uma manifestação visível do Espírito para o benefício de todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Pois a um é dada pelo Espírito a palavra de sabedoria, e a outro a palavra de conhecimento pelo mesmo Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'A outro é dado fé pelo mesmo Espírito, e a outro, dons de cura pelo mesmo Espírito,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'e a outro, dons de poder, e a outro, profecia, a outro, a habilidade de discernir espíritos, e a outro, vários tipos de línguas, e a outro, a interpretação de línguas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Mas o mesmo Espírito trabalha em todos, dando os dons a cada um individualmente, como Ele quiser.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Pois, como o corpo é um e tem muitos membros e todos são membros do mesmo corpo, assim é com Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Pois, em um só Espírito, todos fomos batizados em um só corpo: sejam judeus, sejam gregos; sejam presos, sejam livres; e todos foram feitos para beber de um único Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Porque o corpo não é um único membro, mas muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Se os pés dizem: \"Como eu não sou mão, eu não sou parte do corpo\", eles não deixam de ser parte do corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'E se o ouvido disser: \"Porque eu não sou olho, eu não sou parte do corpo\", ele não deixa de ser parte do corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Se todo o corpo fosse olho, onde estaria a audição? Se todo o corpo fosse ouvido, onde estaria o olfato?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Mas Deus arranjou cada parte do corpo como Ele designou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'E, se eles fossem todos o mesmo membro, onde estaria o corpo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Portanto há muitos membros, mas só um corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'O olho não pode dizer à mão: \"eu não preciso de ti\", nem a cabeça aos pés: \"eu não preciso de vós\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Mas os membros do corpo que parecem ser mais fracos são essenciais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'E as partes do corpo que nós pensamos ser menos honrosas, nós damos a elas maior honra, e os nossos membros indecorosos ganham mais dignidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Agora nossos membros apresentáveis não têm necessidade de serem tratados com dignidade, pois eles já têm isso. Porém Deus coordenou todos os membros juntos, e Ele deu mais honra àqueles que têm falta dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Ele fez isso assim para que não haja divisão no corpo, mas para que os membros cuidem uns dos outros com a mesma afeição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'E, quando um membro sofre, todos os membros sofrem juntamente. Ou, quando um membro é honrado, todos os membros alegram-se juntamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Portanto vós sois parte do corpo de Cristo e individualmente membros Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'E Deus designou à igreja primeiro apóstolos, em segundo profetas, em terceiro mestres, depois operadores de milagres, depois dons de cura, aqueles que proveem socorros, aqueles que fazem trabalhos administrativos, e aqueles que têm vários dons de línguas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Somos todos apóstolos? Somos todos profetas? Somos todos mestres? Todos operamos milagres?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Todos têm dons de cura? Todos falam em línguas? Todos interpretam línguas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Procurai zelosamente os melhores dons. E eu vos mostrarei um caminho mais excelente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Mesmo que eu falasse as línguas dos homens e dos anjos, se eu não tivesse amor, seria como um sino que soa ou um címbalo que retine.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Mesmo que eu tivesse o dom de profecia e entendesse todas as verdades escondidas e todo o conhecimento e tivesse toda a fé para remover montanhas, se não tivesse amor, eu não seria nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'E se eu desse tudo o que possuo para alimentar os pobres e se eu desse o meu corpo para ser queimado, mas não tivesse amor, de nada adiantaria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'O amor é paciente e bondoso. O amor não inveja, nem se orgulha; não é arrogante,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'nem rude; não busca os próprios interesses; não se ira facilmente; não leva em conta o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Não se alegra com a injustiça, mas se alegra com a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'O amor tudo sofre, tudo crê, tudo espera e tudo suporta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'O amor jamais acaba. Havendo profecias, elas passarão; havendo línguas, elas cessarão; havendo conhecimento, este passará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Pois nós conhecemos em parte e em parte profetizamos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'mas, quando o que é perfeito vier, aquilo que é em parte passará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Quando eu era uma criança, eu falava como criança, pensava como criança, julgava como criança. Quando me tornei um adulto, deixei as coisas de criança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Por agora, vemos como em espelho, sem clareza, mas depois veremos face a face. Agora eu conheço em parte, mas então conhecerei completamente assim como fui completamente conhecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Agora permanecem estes três: a fé, a esperança e o amor, mas o maior deles é o amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Segui o amor e desejai intensamente os dons espirituais, especialmente o de profetizar;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'porque aquele que fala em uma língua não fala a pessoas, mas a Deus. Pois ninguém o entende, porque ele fala mistérios no Espírito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'mas aquele que profetiza fala a pessoas para as edificar, encorajar e confortar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Aquele que fala em língua edifica a si mesmo, mas o que profetiza edifica a igreja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Gostaria que todos vós falasseis em línguas; porém, muito mais que isso, gostaria que todos profetizásseis. Aquele que profetiza é maior do que o que fala em línguas (a menos que alguém interprete, para que a igreja seja edificada).');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Entretanto, irmãos, se eu chegar a vós falando em línguas, que beneficio vos trarei? Nenhum! A não ser que vos fale com revelação, conhecimento, profecia ou ensino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Se instrumentos sem vida que produzem sons, como a flauta ou a harpa, não produzem diferentes tons, como alguém saberá qual melodia a harpa ou a flauta estão tocando?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Porque se a trombeta tocar um som incerto, como alguém saberá quando é o tempo de se preparar para a batalha?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Assim é convosco: se pronunciardes discurso que é ininteligível, como alguém entenderá o que dizeis? Vós falareis, e ninguém vos entenderá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Sem dúvida, existem muitas línguas diferentes no mundo, e nenhuma é sem sentido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Todavia, se eu não souber o significado de uma língua, serei um estrangeiro para quem fala, e ele será um estrangeiro para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Do mesmo modo, convosco: já que estais desejosos pelas manifestações do Espírito, sede zelosos para abundar na edificação da igreja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Então, o que fala em uma língua deve orar para que a possa interpretar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Porque se eu oro em línguas, meu espírito ora, mas minha mente está infrutífera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'O que devo fazer? Orarei com meu espírito, mas também com minha mente. Cantarei com meu espírito, e também com minha mente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'De outro modo, se louvais a Deus com o espírito, como a outra pessoa dirá \"Amém\" quando estiveres dando graça, se ele não souber o que tu estás dizendo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Vós certamente dais graças muito bem, mas a outra pessoa não é edificada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Eu agradeço a Deus por falar em línguas mais que todos vós,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'mas na igreja eu preferiria falar cinco palavras com meu entendimento a fim de instruir a outros, a falar dez mil palavras em línguas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Irmãos, não sejais crianças em vosso pensar. Particularmente, quanto ao mal, sede como criancinhas; mas em vosso pensar, sede maduros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Na Lei está escrito: \"Por homens de outras línguas e pelos lábios estrangeiros Eu falarei a este povo. Mesmo assim, não Me ouvirão\", diz o Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Portanto, línguas são um sinal, não para os cristãos, mas para os não cristãos; mas profecia é um sinal, não para os não cristãos, mas para os cristãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Se, portanto, toda a igreja se juntar e todos falarem em línguas, e os de fora e os não cristãos chegarem, não diriam eles que vós estais loucos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Mas se todos vós estiverdes profetizando e um não cristão ou alguém de fora chegar, ele seria convencido de tudo o que ouviu, e seria julgado por tudo o que foi dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'Os segredos do seu coração seriam revelados; como resultado, ele se prostraria com seu rosto em terra, adoraria a Deus, e declararia que Deus está realmente entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Então, como é, irmãos? Quando vos reunis, cada um tenha um salmo, um ensinamento, uma revelação, uma língua ou uma interpretação. Fazei tudo para a edificação da igreja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Se alguém fala em uma língua, que sejam dois ou no máximo três, e um de cada vez, então alguém deve interpretar o que é dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Contudo, se não há ninguém para interpretar, que cada um permaneça em silêncio na igreja. Deixe que ele fale sozinho consigo mesmo e com Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Que dois ou três profetas falem, e que os outros ouçam com discernimento o que é dito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Mas, se uma revelação for dada a quem está sentado no culto, que fique em silêncio o que estava falando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Porque cada um de vós pode profetizar, um por um, para que cada um aprenda, e todos sejam encorajados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Porque os espíritos dos profetas estão sob o controle dos profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Porque Deus não é Deus de confusão, mas de paz. Esta é a ordenança em todas as igrejas dos santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'As mulheres devem ficar em silêncio nas igrejas, porque não lhes é permitido falar. Ao invés disso, devem estar submissas, como também diz a Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Se há alguma coisa que elas desejem aprender, que elas perguntem para seus maridos em casa. Porque é vergonhoso para a mulher falar na igreja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Veio de vós a palavra de Deus? Vós sois os únicos que fostes alcançados?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Se alguém pensa ser um profeta ou espiritual, deveria reconhecer que as coisas que vos escrevi são mandamentos do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Mas se alguém não reconhece isso, que não seja reconhecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Então, irmãos, desejai intensamente profetizar, e não proibais ninguém de falar em línguas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Mas que todas as coisas sejam feitas decentemente e em ordem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Lembro-vos irmãos, do Evangelho que vos proclamei, que recebestes, e no qual permanecestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'É por este Evangelho que sois salvos, desde que segureis firmemente a palavra que preguei, a menos que tenhais crido em vão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Pois vos entreguei em primeiro lugar o que também recebi: que Cristo morreu por nossos pecados, segundo as Escrituras;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'e que Ele foi sepultado e ressuscitado ao terceiro dia, segundo as Escrituras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'E apareceu a Cefas, depois aos Doze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Em seguida, apareceu a mais de quinhentos irmãos de uma vez, os quais, a maioria ainda vive, mas alguns já dormiram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Depois apareceu a Tiago e, mais tarde, a todos os apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Por último, Ele apareceu a mim, como a uma criança nascida fora do tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Pois eu sou o menor dos apóstolos, indigno de ser chamado apóstolo porque persegui a igreja de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Mas, pela graça de Deus, sou o que sou, e sua graça em mim não foi em vão. Em vez disso, trabalhei muito mais do que todos eles, ainda que não tenha sido eu, mas a graça de Deus que está comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Portanto, se fui eu ou eles, assim pregamos, e vós acreditastes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Ora, se Cristo é proclamado como ressurreto da morte, como podem alguns de vós dizer que não há ressurreição da morte?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Mas, se não há ressurreição da morte, então nem mesmo Cristo ressuscitou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'E se Cristo não ressuscitou, então nossa pregação é em vão, e vossa fé também é em vão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'E fomos consideradas falsas testemunhas sobre Deus, porque testificamos contra Deus, dizendo que Ele ressuscitou a Cristo, quando Ele não o fez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Pois se os mortos não são ressuscitados, nem mesmo Cristo foi ressuscitado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'E se Cristo não foi ressuscitado, vossa fé é em vão, e ainda estais em vossos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Então, aqueles que morreram em Cristo também pereceram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Se somente nesta vida temos confiança para o futuro em Cristo, somos as mais miseráveis de todas as pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Mas agora, Cristo foi ressuscitado dentre os mortos, sendo o primeiro fruto daqueles que morreram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Visto que a morte veio por um homem, por um homem também veio a ressurreição dos mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Pois, como em Adão todos morrem, assim também em Cristo todos serão vivificados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Mas, cada um, em sua própria vez: Cristo, o primeiro dos frutos, depois os que pertencem a Cristo, em Sua vinda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Então será o fim, quando Cristo entregar o reino a Deus, o Pai, e abolir todo o principado e toda autoridade e poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Pois Ele deve reinar até ter posto todos os seus inimigos debaixo de Seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'O último inimigo a ser destruído é a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Porque \"Ele pôs todas as coisas debaixo de Seus pés\". Mas, quando se diz: \"Ele pôs todas as coisas\", está claro que isso não inclui Aquele que sujeitou a Ele todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Quando todas as coisas estiverem sujeitas a Ele, então o Filho Se sujeitará Àquele que todas as coisas Lhe sujeitou, para que Deus, o Pai, possa ser tudo em todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'De outro modo, o que farão aqueles que se batizam pelos mortos? Se os mortos não ressuscitam de modo algum, por que se batizam por causa deles?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'E por que estamos em perigo a todo o tempo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Enfrento a morte todos os dias. Isto é uma certeza de que falo com orgulho a vós, o qual tenho em Cristo Jesus, nosso Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'O que eu ganho se, por motivos humanos, lutei com animais ferozes em Éfeso, se os mortos não são ressuscitados? \"Comamos e bebamos, pois amanhã morreremos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Não sejais enganados: \"Más companhias corrompem os bons costumes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Tornai-vos sóbrios! Vivei justamente! Não pequeis. Pois, alguns de vós não têm conhecimento de Deus. Digo isto para vossa vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Mas alguém dirá: \"Como os mortos são ressuscitados? E com que tipo de corpo eles virão?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Vós sois tão ignorantes! O que vós semeais não crescerá a menos que morra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'E o que semeais não é o corpo que há de ser, mas uma simples semente, que se tornará trigo ou outra planta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Mas Deus dará um corpo conforme Ele escolher, a cada semente dá seu corpo apropriado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Nem toda carne é a mesma, mas uma é a carne dos homens, outra é a carne dos animais, outra a dos pássaros e outra a dos peixes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Há também corpos celestiais e terrestres. Mas a glória do corpo celestial é um tipo, e a glória do terrestre é outra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Há uma glória do sol, outra glória da lua e outra glória das estrelas, pois uma estrela difere da outra em glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Assim também é a ressurreição dos mortos: o que é semeado é perecível, e o que ressuscita é imperecível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'O que é semeado em desonra é ressuscitado em glória. O que é semeado em fraqueza é ressuscitado em poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'O que é semeado num corpo natural é ressuscitado num corpo espiritual. Se há um corpo natural, também há um corpo espiritual.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Assim, também está escrito: \"O primeiro homem, Adão, foi feito alma vivente\"; o último Adão tornou-se espírito vivificante.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Todavia, o espiritual não veio primeiro; mas o natural, e depois o espiritual.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'O primeiro homem é da terra, feito do pó; o segundo homem é do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'À semelhança do homem feito do pó, assim também são aqueles feitos do pó; e, à semelhança do homem do céu, assim também são aqueles que são do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Assim como carregamos a imagem do homem do pó, também carregaremos a imagem do homem do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Digo-vos isto, irmãos, que carne e sangue não podem herdar o reino de Deus, nem o perecível herdar o imperecível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Eis um mistério que vos digo: nem todos morreremos, mas todos seremos transformados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'Nós seremos transformados em um instante, em um piscar de olhos, na última trombeta. Pois, a trombeta soará, e os mortos serão ressuscitados imperecíveis, e nós seremos transformados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Porque este corpo perecível deve se revestir do imperecível, e este corpo mortal deve-se revestir de imortalidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Mas, quando este corpo perecível se revestir do que é imperecível, e este corpo mortal se revestir do que é imortal, então virá o que está escrito: \"Tragada foi a morte pela vitória\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, '\"Morte, onde está a tua vitória?\". \"Morte, onde está o teu aguilhão?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'O aguilhão da morte é o pecado, e o poder do pecado é a lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Mas graças a Deus, que nos dá a vitória através do nosso Senhor Jesus Cristo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Portanto, meus queridos irmãos, sede firmes e inabaláveis. Sempre abundantes na obra do Senhor, porque sabeis que o vosso trabalho no Senhor não é em vão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Agora, quanto à coleta para os santos, como ordenei às igrejas da Galácia, assim fazei também.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'No primeiro dia da semana, cada um de vós separe o que puder e armazene, para que não haja coleta quando eu for.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'E quando eu chegar, aquele que vós aprovardes, eu o enviarei com cartas para entregar vossas ofertas em Jerusalém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'E se for apropriado que eu também vá, eles irão comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Mas eu irei até vós quando passar pela Macedônia, pois passarei pela Macedônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Talvez eu possa ficar convosco ou passar o inverno, para que possais ajudar em minha jornada, aonde quer que eu vá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Porque eu não desejo vos ver agora por um tempo curto, pois espero passar algum tempo convosco, se o Senhor permitir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Mas eu ficarei em Éfeso até o Pentecostes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'porque se abriu para mim uma porta grande e eficaz, e há muitos adversários.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'E, quando Timóteo chegar, cuidai para que ele esteja convosco sem medo, porque ele está fazendo a obra do Senhor, assim como eu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Portanto, que ninguém o despreze. Mas encaminhai-o em paz para que venha a mim, pois o espero com os irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Quanto ao nosso irmão Apolo, eu fortemente o encorajei a ir vos visitar com os irmãos, mas de modo algum ele quis ir agora. Contudo, ele irá quando tiver oportunidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Vigiai, ficai firmes na fé, sede corajosos, sede fortes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Tudo o que fizerdes fazei com amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Vós sabeis que os da casa de Estéfanas são os primeiros convertidos em Acaia e que se dedicaram ao serviço dos santos. Agora eu vos rogo, irmãos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'que sejais submissos a essas pessoas e a cada um que trabalha e coopera conosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'E eu me alegro com a vinda de Estéfanas, Fortunato e Acaico. Eles supriram a vossa ausência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Porque eles revigoraram meu espírito e o vosso. Então, reconhecei pessoas como essas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'As igrejas da Ásia vos saúdam. Áquila e Priscila intensamente vos saúdam no Senhor, com a igreja que está na casa deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Todos os irmãos vos saúdam. Saudai uns aos outros com beijo santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Eu, Paulo, escrevo isto com minhas próprias mãos:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Se alguém não ama o Senhor, seja maldito. Ora vem, SenhorJesus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Que a graça do Senhor Jesus seja convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Meu amor seja com todos vós em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paulo, apóstolo de Cristo Jesus pela vontade de Deus, e nosso irmão Timóteo, à igreja de Deus que está em Corinto e a todos os santos em toda a região da Acaia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Que a graça seja convosco, e a paz de Deus, nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Que o Deus e Pai de nosso Senhor Jesus Cristo seja louvado; Ele é o Pai das misericórdias e Deus de toda consolação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Deus nos consola em toda nossa aflição, para que possamos consolar os que estão em qualquer aflição, consolamos a outros com a mesma consolação que temos recebido de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Pois, assim como os sofrimentos de Cristo são abundantes por nossa causa, assim também nosso consolo é abundante por meio de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Mas, se somos afligidos, é para o vosso consolo e salvação; e, se somos consolados, é para vosso consolo. Esse conforto é eficaz quando vós compartilhais com paciência os mesmos sofrimentos que nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'E nossa confiança em vós é certa, sabemos que assim como vós compartilhais os sofrimentos, também compartilhais o consolo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Porque não queremos, irmãos, que sejais ignorantes acerca das tribulações que tivemos na Ásia. Fomos completamente sobrecarregados além do que podíamos suportar, tanto que não tínhamos mais esperança de viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'De fato, tínhamos a sentença de morte em nós. Contudo, isso era para que não colocássemos nossa confiança em nós mesmos, mas em Deus, que ressuscita os mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Ele nos resgatou de um perigo tão mortal, e nos resgatará novamente. Nós colocamos nossa confiança Nele, de que nos libertará novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Ele nos libertará enquanto vós nos auxiliais através de vossas orações. Então, muitos agradecerão pelo favor gracioso nos dado através das orações de muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Nós nos orgulhamos disto: o testemunho da nossa consciência. Pois é por motivos puros e sinceros, da parte de Deus, que procedemos no mundo, especialmente convosco, não com sabedoria terrena, mas pela graça de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Não vos escrevemos qualquer coisa que não podeis ler ou entender. Espero que nos entendais completamente,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'como já nos entendestes em parte. Então, no dia de nosso Senhor Jesus, seremos a razão do vosso orgulho, assim como vós sereis do nosso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Porque eu estava confiante disto, eu queria vir até vós primeiro, para receberdes o benefício de duas visitas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'Eu planejava vos visitar quando fosse à Macedônia, e depois iria novamente visitar-vos quando eu voltasse de lá, e então ser encaminhado por vós à Judeia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Quando eu planejava isso, por acaso hesitava? Por acaso, planejo coisas de acordo com padrões humanos, de modo que digo: \"sim, sim\" e \"não, não\", ao mesmo tempo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Mas assim como Deus é fiel, nós não dizemos ao mesmo tempo \"sim\" e \"não\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Pois, o Filho de Deus, Jesus Cristo, a quem Silvano, Timóteo e eu proclamamos entre vós, não é \"sim\" e \"não\"; mas é sempre \"sim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Pois todas as promessas de Deus são \"sim\" Nele. Então, também através Dele, nós dizemos \"amém\" para a glória de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'É Deus quem nos confirma convosco em Cristo, e Ele nos comissionou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Ele pôs Seu selo em nós e em nossos corações, e concedeu-nos o Espírito como um penhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Eu tomo Deus como minha testemunha de que a razão pela qual não estive em Corinto foi para poupar-vos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Não porque tentamos controlar a vossa fé, mas porque trabalhamos convosco para vossa alegria, enquanto, pela fé, permaneceis firmes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Decidi por mim mesmo que não viria até vós novamente em circunstâncias dolorosas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Se vos causei dor, quem poderia me animar senão aquele que foi entristecido por mim?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Escrevi dessa forma para que, quando vos visitasse, eu não fosse entristecido pelos que deveriam me fazer regozijar. Eu confio que minha alegria é a mesma que a de todos vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Pois vos escrevi em grande aflição, com angústia de coração, e com muitas lágrimas. Eu não queria vos causar dor; em vez disso, queria que Conhecêsseis a profundidade do amor que tenho por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Se alguém causou dor, não causou apenas a mim, mas em certa medida, a todos vós, para não ser tão severo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'A punição dessa pessoa pela maioria é suficiente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Agora, ao invés da punição, deveis perdoá-lo e confortá-lo, para que ele não seja sobrecarregado de tanta tristeza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Então, encorajo-vos a afirmar publicamente o vosso amor por ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Esse foi o motivo por que escrevi, para que eu pudesse vos examinar e entender se sois obedientes em tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Se perdoais a alguém, também perdoo essa pessoa. O que perdoei, se é que perdoei alguma coisa, está perdoado por vossa causa na presença de Cristo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'para que Satanás não nos engane. Pois nós não somos ignorantes de seus planos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Uma porta me foi aberta pelo Senhor quando fui à cidade de Trôade para pregar o Evangelho de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Ainda assim, não tive paz de espírito, porque não encontrei meu irmão Tito. Então eu os deixei e voltei à Macedônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Mas, graças sejam dadas a Deus, que em Cristo sempre nos conduz em triunfo. Por meio de nós, Ele espalha o doce aroma do Seu conhecimento em todo lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Pois nós somos para Deus o doce perfume de Cristo, tanto entre aqueles que são salvos como entre aqueles que estão perecendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Para os que estão perecendo, é um aroma de morte para a morte. Para os que estão sendo salvos, é um aroma de vida para a vida. Quem é digno dessas coisas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Pois nós não somos como tantas pessoas que vendem a palavra de Deus pelo lucro. Ao invés disso, com motivos puros, falamos em Cristo, como enviados de Deus, à vista de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Começamos a nos gloriar novamente? Não precisamos de cartas de recomendações para vós ou de vós, como alguns, precisamos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Vós mesmos sois a nossa carta de recomendação, escrita em nossos corações, conhecida e lida por todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'E mostrais ser uma carta de Cristo, entregue por nós, escrita não com tinta, mas pelo Espírito do Deus vivo. Não escrita em tábuas de pedra, mas em tábuas de corações humanos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'E essa é a confiança que temos em Deus por intermédio de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Não somos competentes, por nós mesmos, para afirmarmos que qualquer coisa vem de nós, pelo contrário, nossa competência vem de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'Foi Ele que nos capacitou para sermos servos da nova aliança, não da letra, mas do Espírito; pois a letra mata, mas o Espírito dá vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Ora, o ministério da morte, com letras gravadas em pedras, veio com tanta glória que o povo de Israel não podia olhar diretamente no rosto de Moisés, por causa da glória de seu rosto, a qual estava perdendo seu brilho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Quão mais glorioso será o ministério do Espírito?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Se o ministério da condenação possuía glória, quanto mais é abundante o ministério da justificação em glória!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'De fato, aquilo que uma vez foi feito glorioso, nesse aspecto, deixou de ser, por causa da glória que o excede.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Pois, se aquilo que estava perdendo o brilho tinha glória, muito mais glória terá o que é permanente!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Já que temos tal confiança, agimos com toda ousadia;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'não como Moisés, que colocou um véu sobre seu rosto, para que o povo de Israel não pudesse perceber o fim da glória que estava perdendo o brilho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Mas suas mentes estavam fechadas, pois, ainda hoje, o mesmo véu permanece na leitura da antiga aliança. Esse véu se mantém porque, apenas em Cristo, é removido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Mesmo hoje, sempre que Moisés é lido, um véu é colocado sobre seus corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Porém, quando uma pessoa se volta para o Senhor, o véu é removido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Pois o Senhor é o Espírito e, onde o Espírito do Senhor está, há liberdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Todos nós, com o rosto desvendado, vemos a glória do Senhor. E estamos sendo transformados, de glória em glória, na mesma imagem gloriosa, como da parte do Senhor, que é o Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Dessa forma, por termos este ministério, e conforme a misericórdia que recebemos, não nos desanimamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Pelo contrário, renunciamos aos caminhos vergonhosos e ocultos. Não vivemos pela astúcia, e não falsificamos a Palavra de Deus. Ao apresentar a verdade, nos recomendamos à consciência de todo homem, à vista de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Mas, se o nosso Evangelho está encoberto, está encoberto apenas para aqueles que estão perecendo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'No caso deles, o deus deste mundo cegou suas mentes incrédulas, e, por isso, não conseguem ver a luz do Evangelho da glória de Cristo, que é a imagem de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Pois não anunciamos a nós mesmos, mas a Cristo Jesus como Senhor, e a nós mesmos como vossos servos, por causa de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Porque foi Deus quem disse: \"A luz brilhará das trevas\". Ele brilhou em nossos corações para iluminar o conhecimento da glória de Deus na face de Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Porém, temos este tesouro em vasos de barro, para que fique claro que o supremo poder pertence a Deus, e não a nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Somos afligidos de todas as maneiras, mas não derrotados; perplexos, mas não desesperados;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'perseguidos, mas não abandonados; abatidos, mas não destruídos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Carregamos sempre no corpo a morte de Jesus, para que a Sua vida também seja mostrada em nosso corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Nós, que vivemos, somos sempre entregues à morte por causa de Jesus, para que a vida de Jesus seja mostrada em nosso corpo humano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'De modo que a morte opera em nós, mas a vida em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Mas nós temos o mesmo espírito de fé, de acordo com o que está escrito: \"Eu cri e, por isso, falei.\" Nós também cremos e, por isso, também falamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Sabemos que Aquele que ressuscitou o Senhor Jesus também nos ressuscitará com Jesus, e nos trará convosco à Sua presença.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Todas as coisas são por vossa causa, para que, mediante a graça abundante a muitos, as ações de graças excedam para a glória de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Então, não nos desanimamos. Mesmo que externamente sejamos consumidos, internamente somos renovados dia a dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Pois esta leve e momentânea aflição nos prepara para um eterno peso de glória que excede toda medida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Não nos atentamos às coisas que se veem, mas às coisas que não se veem. As coisas que podemos ver são temporárias, mas as coisas que não podemos ver são eternas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Sabemos que, se a moradia terrena em que vivemos for destruída, temos um edifício da parte de Deus, uma casa, feita não por mãos humanas, mas eterna, no céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Neste tabernáculo, gememos, pois aspiramos ser revestidos com nossa habitação celestial.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Temos esse desejo, pois, ao nos vestirmos, não seremos encontrados nus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'De fato, enquanto estamos neste tabernáculo, gememos sobrecarregados. Não queremos ser despidos; pelo contrário, revestidos, para que o mortal seja absorvido pela vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Aquele que nos preparou para isso foi Deus, que nos deu o Espírito como penhor do que está por vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Portanto, sede sempre confiantes. Sabei que, enquanto habitamos neste corpo terreno, estamos ausentes do Senhor;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'pois andamos por fé, não por vista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Por isso, somos confiantes. Preferimos estar ausentes do corpo, e no lar com o Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Assim, quer estejamos em nossa habitação, quer ausentes, fazemos disto nossa meta: agradá-Lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Pois todos nós devemos comparecer diante do tribunal de Cristo, para que cada um receba o que é devido pelas coisas feitas no corpo, quer para o bem, quer para o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Portanto, conhecendo o temor do Senhor, persuadimos as pessoas. O que somos é claramente visto por Deus, e espero que isso também esteja claro para a vossa consciência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Não estamos tentando vos convencer novamente de nossa sinceridade; em vez disso, estamos vos dando uma razão para vos orgulhardes de nós. Dessa forma, vós tereis uma resposta aos que se gloriam nas aparências, mas não no que está no coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Pois se enlouquecemos é para Deus; e se conservamos o juízo é por amor de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Pois, o amor de Cristo nos compele, porque estamos certos disto: que uma pessoa morreu por todas; logo, todas morreram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'E Cristo morreu por todos, para que os que vivem não vivam mais para si mesmos, mas para Aquele que morreu e foi ressuscitado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Por essa razão, de agora em diante, não julgamos ninguém de acordo com padrões humanos, ainda que uma vez tenhamos considerado Cristo dessa maneira. Mas, agora, não julgamos ninguém assim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Portanto, se alguém está em Cristo, é nova criatura; as coisas velhas se passaram. Eis que se tornaram novas!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Todas essas coisas provêm de Deus, que nos reconciliou Consigo mesmo através de Cristo, e nos deu o ministério da reconciliação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Isto é, em Cristo, Deus está reconciliando o mundo Consigo mesmo, não levando em conta as suas transgressões. Ele está nos confiando a mensagem da reconciliação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Então, somos designados como representantes de Cristo, como se Deus vos exortasse através de nós. Por amor de Cristo, nós vos suplicamos: reconciliai-vos com Deus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Ele fez de Cristo, Aquele que nunca pecou, o sacrifício por nossos pecados, para que Nele nos tornássemos a justiça de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'E assim, trabalhando juntos com Ele, nós suplicamos que não recebais a graça de Deus em vão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Porque Ele diz: \"Em tempo oportuno Eu te ouvi, e no dia da salvação te ajudei\". Eis que agora é o tempo favorável; Eis que agora é o dia da salvação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Nós não colocamos uma pedra de tropeço diante de ninguém, porque não desejamos que nosso ministério caia em descrédito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Em vez disso, provamos pelas nossas ações que somos servos de Deus: por grande perseverança em meio a aflições, nas angústias, nas privações,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'nos açoites, nas prisões, nos motins, no trabalho duro, nas noites sem sono, na fome;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'pela pureza, pelo conhecimento, pela paciência, pela gentileza, pelo Espírito Santo e pelo amor sem fingimento,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'pela palavra da verdade e pelo poder de Deus; pelas armas da justiça da mão direita e da esquerda,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'na honra e na desonra, na calúnia e no louvor; tidos como enganadores, mas somos verdadeiros;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'como desconhecidos, mas somos bem conhecidos; como que morrendo, e eis que ainda vivemos! Como punidos por nossas ações, mas não como condenados à morte;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'como entristecidos, mas sempre nos regozijando; como pobres, mas enriquecendo a muitos; como não tendo nada, mas possuindo tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Falamos a vós toda a verdade, Coríntios, e nosso coração está totalmente aberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Vossos corações não foram fechados por nós, mas estão fechados por vossos próprios sentimentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Agora, em uma retribuição justa, falo como a crianças: abri totalmente os vossos corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Não estejais sob jugo desigual com incrédulos, pois que associação tem a justiça com a iniquidade? Ou que comunhão a luz tem com as trevas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Que acordo Cristo pode ter com Belial? Ou o que um crente tem em comum com um incrédulo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'E que acordo há entre o templo de Deus e os ídolos? Porque nós somos o templo do Deus vivo, como Deus disse: \"Eu habitarei entre eles e andarei entre eles. Eu serei o Seu Deus, e eles serão o Meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Portanto, Saí do meio deles, e sede separados, diz o Senhor. E não toqueis em coisa impura, e Eu vos acolherei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'Eu vos serei um Pai, e vós sereis meus filhos e filhas\", diz o Senhor Todo-Poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Amados, já que temos essas promessas, purifiquemo-nos de tudo o que nos faz impuros em nosso corpo e espírito. Busquemos a santidade no temor de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Acolhei-nos em vosso coração. Nós não fizemos mal ou causamos danos a ninguém e não tiramos vantagem de ninguém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Não digo isso para vos condenar, porque eu já disse que estais em nossos corações, para juntos morrermos e juntos vivermos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Tenho grande confiança em vós, e estou orgulhoso de vós. Estou repleto de consolação e transbordo de alegria, mesmo em toda a nossa aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Quando viemos à Macedônia, nossos corpos não tiveram descanso; em vez disso, fomos atribulados de todos os modos: conflitos no exterior e temores no interior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Mas Deus, que conforta o desanimado, confortou-nos com a chegada de Tito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'E não só por sua chegada que Deus nos confortou, mas também pelo conforto que ele recebeu de vós. Ele nos contou da vossa grande afeição, vosso pesar e vossa profunda preocupação por mim; por isso me alegrei ainda mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Mesmo que minha carta tenha vos entristecido, não me arrependo dela, embora eu tenha me arrependido quando eu vi que ela vos deixou tristes, ainda que só por um momento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Agora eu me alegro, não porque tenhais sofrido, mas porque vossa tristeza vos levou ao arrependimento. Vós experimentastes uma tristeza segundo Deus, então não sofrestes perda nenhuma por nossa causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Porque a tristeza divina traz arrependimento que alcança salvação sem remorso; a tristeza do mundo, entretanto, traz morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Vede quão grande determinação essa tristeza segundo Deus produziu em vós. Quão grande era a vossa determinação para provar vossa inocência. Quão grande era vossa indignação, temor, vontade, zelo, e desejo de ver a justiça sendo feita! Em tudo provastes ser inocentes nesse assunto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Embora eu tenha vos escrito, não escrevi por causa do malfeitor, nem por quem sofreu o mal, mas para que a vossa sinceridade para conosco fosse conhecida por vós perante Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Por causa disso, somos encorajados. Além do nosso próprio conforto, nós nos alegramos ainda mais pela alegria de Tito, porque seu espírito foi renovado por todos vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Pois me orgulhei de vós diante dele e não fui envergonhado; pelo contrário, assim como tudo o que vos dissemos era verdade, nosso orgulho de vós diante de Tito provou-se verdadeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'A afeição dele por vós é ainda maior, à medida que ele se lembra da obediência de todos vós e de como o recebestes com temor e tremor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Eu me alegro porque tenho completa confiança em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Queremos que saibais, irmãos, sobre a graça de Deus dada às igrejas da Macedônia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Durante muitas aflições, a abundância da alegria e a profunda pobreza deles produziram neles grande riqueza de generosidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Porque dou testemunho de que deram muito mais do que podiam, e até além de suas posses. E, de livre vontade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'pediram-nos com muita insistência o privilégio de participar desse serviço aos santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Isto não aconteceu como esperávamos; em vez disso, primeiramente eles se entregaram ao Senhor, e depois a nós, pela vontade de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Então, rogamos a Tito, que já havia começado essa tarefa, que completasse esse ato de generosidade entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Ora, vós sois abundantes em tudo: na fé, na palavra, no conhecimento, em todo o zelo e no vosso amor por nós. Assim, certificai-vos de que também sejais abundantes nesse trabalho generoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Digo isso não como uma ordem, mas para provar a sinceridade do vosso amor, ao compará-lo com o zelo de outras pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Pois vós conheceis a graça do nosso Senhor Jesus Cristo, que, embora fosse rico, para o vosso bem Ele Se tornou pobre, para que, por meio de Sua pobreza vós vos tornásseis ricos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Quanto a isso, darei um conselho que vos ajudará. Um ano atrás, vós não somente começastes a fazer algo, mas desejastes fazê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Agora, completai-o. Assim como havia empenho e desejo de fazê-lo antes, que vós também completeis, tanto quanto possais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Porque estais empenhados em fazer essa obra, isso é bom e aceitável. Mas deve ser baseada no que cada pessoa tem, não no que ele não tem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Porque essa tarefa não é para que outros sejam aliviados e vós sobrecarregados; mas deve haver igualdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'A vossa abundância no tempo presente suprirá o que eles precisam. Para que a abundância deles também possa suprir a vossa necessidade, de forma que haja igualdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Como está escrito: \"Aquele que tinha muito não teve nada sobrando; e, aquele que tinha pouco, nada faltando\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Mas graças a Deus, que colocou no coração de Tito o mesmo sincero cuidado e zelo que tenho por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Pois ele não apenas aceitou nosso apelo, mas, sendo muito zeloso sobre isso, foi até vós de espontânea vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Com ele, enviamos o irmão que é elogiado entre todas as igrejas por seu trabalho na proclamação do Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'Não somente isso, mas ele também foi indicado pelas igrejas para viajar conosco e cumprir esse nosso ato de generosidade, para honrar ao Senhor e demonstrar nosso empenho em ajudar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Queremos evitar a possibilidade de alguém reclamar acerca da nossa generosidade, a qual estamos ministrando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Nós tomamos o cuidado de fazer o que é honroso, não apenas diante do Senhor, mas também diante das pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'E com eles também enviamos outro irmão. Nós o temos testado frequentemente, e encontramos nele entusiasmo para muitas tarefas. Agora, ele é ainda mais cuidadoso e zeloso por causa da grande confiança que tem em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Quanto a Tito, ele é meu parceiro e companheiro de trabalho em vosso benefício. A respeito de nossos irmãos, eles são enviados pelas igrejas, e são uma honra para Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Então, mostrai-lhes o vosso amor, e mostrai às igrejas a razão pela qual nos orgulhamos de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'No que diz respeito ao ministério para os santos, não me é necessário vos escrever.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Conheço vosso desejo e dele me orgulhei diante do povo da Macedônia. Eu lhes disse que a Acaia estava se preparando desde o ano passado. Vosso zelo motivou a maioria deles à ação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Enviei os irmãos para que nosso orgulho acerca de vós não fosse fútil e para que estivésseis prontos, como eu disse que estaríeis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'De outro modo, caso alguns macedônios fossem comigo e vos encontrassem despreparados, nós, para não dizer vós, seríamos envergonhados por termos tanta confiança em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Então eu pensei que era necessário convencer os irmãos a irem até vós e fazerem preparativos de antemão para a doação que prometestes. Isso é, para que ela esteja pronta como bênção e não como obrigação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'A questão é esta: aquele que semeia pouco também colherá pouco, e aquele que semeia com o propósito de abençoar também colherá uma bênção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Que cada um dê como planejou em seu coração. Não por tristeza ou por constrangimento, pois Deus ama quem dá com alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'E Deus é capaz de fazer toda bênção multiplicar para vós, para que sempre, em todas as coisas, tenhais tudo o que precisais, para que assim possais multiplicar toda boa obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Como está escrito: \"Distribuiu suas riquezas e as deu aos pobres; Sua justiça permanece para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Aquele que dá semente ao semeador e pão para alimento também suprirá e multiplicará vossa semente para semeadura e aumentará a colheita da vossa justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Vós sereis enriquecidos de todos os modos para que sejais generosos, e isso resultará em ações de graças a Deus através de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Porque a realização desse serviço não atende somente às necessidades dos santos, mas também se multiplica em muitas ações de graças a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Pois ao serdes testados e aprovados por esse serviço, também glorificareis a Deus pela obediência de vossa confissão do evangelho de Cristo e pela generosidade de vossa doação a eles e a todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'E eles anseiam e oram por vós, por causa da extraordinária graça de Deus que está sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Graças a Deus pelo Seu dom inexprimível!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Eu, Paulo, rogo-vos, pela humildade e gentileza de Cristo, eu que sou manso na vossa presença, mas ousado convosco quando ausente,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'peço-vos que, quando estiver presente convosco, não precise ser ousado e autoconfiante. Mas penso que terei que ser ousado quando me opuser aos que supõem que nós estamos vivendo conforme a carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Mesmo que andemos na carne, não militamos de acordo com a carne;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'porque as armas com que lutamos não são carnais, mas têm poder divino para destruir fortalezas, e aniquilam argumentos enganosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Nós também destruímos qualquer coisa altiva que se levanta contra o conhecimento de Deus, e levamos cativo todo pensamento à obediência de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'E estamos nos preparando para punir todo ato de desobediência, tão logo a vossa obediência esteja completa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Vede o que está claramente na frente de vós. Se alguém está convencido que é de Cristo, lembre a si mesmo de que, da mesma forma que é de Cristo, assim também nós somos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Mesmo que eu me orgulhe um pouco mais da nossa autoridade, a qual o Senhor deu para vos edificar e não para vos destruir, não me envergonharei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Eu não quero que pareça que estou vos aterrorizando com minhas cartas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Porque alguns dizem: \"As cartas dele são sérias e poderosas; mas fisicamente ele é fraco, e seu discurso não é digno de ser ouvido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Tal pessoa deve entender que o que somos nas palavras de nossas cartas, quando estamos ausentes, é o que seremos em ações quando estivermos aí.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Não chegaremos ao ponto de nos classificar ou nos comparar com os que louvam a si mesmos mas, quando se medem e se comparam um com o outro, não têm entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Nós, entretanto, não nos gloriaremos além dos limites; mas o faremos somente nos limites que Deus nos designou, os quais vos alcançam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Porque não nos excedemos quando vos alcançamos, e fomos os primeiros a vos alcançar com o Evangelho de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Nós não nos gloriamos demasiadamente nos trabalhos alheios; pelo contrário, esperamos que, enquanto a vossa fé cresce, nossa área de trabalho se expanda, dentro dos nossos limites de atuação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Esperamos por isto, para que possamos pregar o Evangelho mesmo em regiões além da vossa. Não nos gloriaremos do trabalho feito na área de outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, '\"Mas aquele que se gloria, glorie-se no Senhor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Porque não é o que recomenda a si mesmo que é aprovado, mas aquele a quem o Senhor recomenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Quisera eu que pudésseis me suportar em algumas tolices, e, de fato, vós me suportais!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Porque tenho zelo de vós, um zelo que vem de Deus, pois vos prometi em casamento para apresentar-vos como uma virgem pura a um esposo, que é Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Mas temo que, como a serpente enganou Eva com sua astúcia, vossos pensamentos sejam de alguma forma desviados de uma sincera e pura devoção a Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Porque, se alguém vem e proclama outro Jesus diferente daquele que pregamos, ou se recebeis um espírito diferente do que recebestes, ou um evangelho diferente do que aceitastes, a essas coisas tolerais muito bem!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Porque penso que não sou nem um pouco inferior àqueles ditos \"superapóstolos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Mas, mesmo que eu não seja treinado em fazer discursos, sou treinado em conhecimento. Em tudo e de todas as maneiras, fizemos isso conhecido a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Acaso pequei, humilhando a mim mesmo para que fôsseis exaltados? Porque gratuitamente vos preguei o evangelho de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Eu despojei outras igrejas, aceitando salário delas, para que pudesse vos servir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Quando estava convosco e passava necessidade, não fui um peso a ninguém. Porque os irmãos que vieram da Macedônia providenciaram o que eu precisava. Em tudo evitei ser um peso para vós, e continuarei a evitar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Pela verdade de Cristo que está em mim, essa glória não me será tirada nas regiões da Acaia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'E por quê? Porque eu não amo vocês? Deus sabe que eu amo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Mas o que faço continuarei fazendo, para remover o pretexto daqueles que querem se gloriar: de que fazem o mesmo trabalho que nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Pois tais pessoas são falsos apóstolos e obreiros enganadores, disfarçando-se de apóstolos de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'E isso não é surpresa, pois até mesmo Satanás se disfarça de anjo de luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Não é grande surpresa que os seus servos também se disfarcem de servos da justiça. O destino deles será o merecido por seus atos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Digo novamente: Ninguém pense que sou tolo. Mas se vós pensais que sou, recebei-me como um tolo e assim poderei me gloriar um pouco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'O que estou dizendo não é da parte do Senhor, mas falo como um tolo, na confiança de me gloriar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Já que muitos se gloriam segundo a carne, também eu me gloriarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Porque vós de boa vontade tolerais os tolos, já que vós mesmos sois sábios!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Pois vós tolerais que alguém vos escravize, vos consuma, tire vantagem de vós, exalte-se sobre vós, ou vos esbofeteie na face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Para a nossa vergonha, digo que fomos fracos. Mesmo que alguém se glorie, falo como um tolo, também eu me gloriarei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Eles são hebreus? Eu também sou. Eles são israelitas? Eu também sou. Eles são descendentes de Abraão? Eu também sou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Eles são servos de Cristo? (Falo como louco) eu sou mais. Já trabalhei muito mais, já estive em mais prisões, sofri açoites além da medida e passei por muitos perigos de morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Dos judeus recebi cinco vezes os \"quarenta açoites menos um\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Três vezes fui espancado com varas. Uma vez fui apedrejado. Três vezes naufraguei. Passei uma noite e um dia em mar aberto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Estive em frequentes jornadas, em perigos de rios, de ladrões; em perigos vindos do meu próprio povo e dos gentios; em perigos na cidade, no deserto, no mar; e em perigo de falsos irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'Eu tenho estado em trabalhos difíceis e em fadigas, passando muitas noites sem dormir, com fome e com sede, frequentemente em jejum, com frio e em nudez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'E, além de tudo isso, há sobre mim a pressão diária da minha preocupação por todas as igrejas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Se alguém enfraquece, eu não me enfraqueço? Se alguém é levado a tropeçar, eu não fico indignado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Se devo me gloriar, eu me gloriarei na minha fraqueza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'O Deus e Pai do Senhor Jesus, Aquele que é louvado para sempre, sabe que não estou mentindo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'Em Damasco, o governador sob a autoridade do rei Aretas vigiava a cidade para me prender.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'Mas me desceram em um cesto através de uma janela no muro, e escapei de suas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Devo me gloriar, mas nada é ganho com isso. Então, passarei às visões e revelações do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Conheço um homem em Cristo, o qual, catorze anos atrás, foi arrebatado ao terceiro céu — se no corpo ou fora do corpo, eu não sei; Deus o sabe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'E sei que tal homem — se no corpo, ou fora do corpo, eu não sei; Deus o sabe —');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'foi arrebatado ao paraíso, e ouviu coisas muito sagradas para alguém dizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Por tal homem eu me gloriarei; mas por mim, não me gloriarei, exceto das minhas fraquezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Se quisesse gloriar-me, não seria louco, pois estaria falando a verdade; mas não me gloriarei, para que ninguém pense de mim mais do que é visto em mim ou do que ouve de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Também não me gloriarei por causa de tão extraordinária revelação. Portanto, para que não me orgulhasse demais, me foi dado um espinho na carne, um mensageiro de Satanás para me atormentar, para que eu não me exalte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Três vezes implorei ao Senhor sobre isso, para que Ele pudesse tirá-lo de mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'E Ele disse: \"A minha graça te basta; pois o poder se aperfeiçoa na fraqueza\". Portanto, prefiro me orgulhar da minha fraqueza, para que o poder de Cristo habite em mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Por isso, estou contente nas fraquezas, nos insultos, nos problemas, nas perseguições e nos desastres, por causa de Cristo. Pois, quando sou fraco, então sou forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Tornei-me louco! Vós me forçastes a isso, pois eu deveria ser louvado por vós. Pois, em nada fui inferior aos chamados superapóstolos, embora eu não seja nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'As verdadeiras marcas de um apóstolo foram realizados entre vós com toda paciência, sinais, maravilhas e milagres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Então, como fostes vós menos importantes do que o resto das igrejas, exceto que eu não fui um fardo para vós? Perdoai-me por este erro!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Vede! Estou pronto para voltar a vós pela terceira vez. Não vos serei um fardo; pois não quero o que é vosso, quero a vós outros. Pois os filhos não devem acumular bens para os pais, mas os pais acumular para os filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Alegremente gastarei o que tenho e me deixarei ser gasto por vossas almas. Se vos amo mais, serei menos amado?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Dessa forma, não vos sobrecarreguei; mas, já que sou tão astuto, vos prendi com engano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Por acaso vos explorei através de alguém que enviei?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Eu convenci Tito a ir até vós, e mandei outro irmão com ele. Por acaso Tito vos explorou? Nós não andamos no mesmo espírito? Não demos os mesmos passos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Pensais que, todo este tempo estávamos nos defendendo perante vós? Diante de Deus, estávamos dizendo todas essas coisas para a vossa edificação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Pois temo que, quando eu vier, não vos encontre como gostaria, e que não me encontreis como gostaríeis. Temo que haja brigas, invejas, ódio, ambição egoísta, calúnias, falatórios, arrogância e desordem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Temo que, quando voltar, meu Deus me humilhe diante de vós, e talvez eu me lamente por muitos daqueles que pecaram anteriormente, e não se arrependeram da impureza, da imoralidade sexual e da lascívia que praticaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Esta é a terceira vez que eu irei até vós. \"Toda acusação deve ser resolvida pela palavra de duas ou três testemunhas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Eu já falei para aqueles que pecaram anteriormente e para todos os demais, quando estive convosco pela segunda vez, e digo de novo: quando voltar novamente, não vos pouparei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Eu vos digo isso porque estais procurando evidências de que Cristo está falando através de mim. Ele não é fraco para convosco. Ao contrário, Ele é poderoso em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Pois Ele foi crucificado em fraqueza, mas está vivo pelo poder de Deus. Pois nós também somos fracos Nele, mas viveremos com Ele pelo poder de Deus entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Examinai a vós mesmos para saberdes se estais na fé. Provai a vós mesmos. Não percebeis que Jesus Cristo está em vós? A não ser que já estais reprovados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'E eu estou confiante de que reconhecereis que não somos reprovados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Oramos a Deus para que não façais mal algum. Não oro para que pareçamos aprovados. Em vez disso, oro para que façais o que é certo, embora pareça que fomos reprovados no teste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Pois não podemos fazer coisa alguma contra a verdade, mas apenas em favor da verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Pois nos alegramos quando estamos fracos e vós estais fortes. Nós também oramos para que sejais aperfeiçoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Escrevo essas coisas enquanto estou distante de vós, para que, quando eu estiver convosco, não precise vos tratar com rigor no uso da minha autoridade, a qual o Senhor me deu, para que eu possa vos edificar, e não vos destruir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Finalmente, irmãos, alegrai-vos! Trabalhai para serdes aperfeiçoados, sedes encorajados, concordai uns com os outros, vivei em paz. E o Deus de amor e paz estará convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Saudai-vos uns aos outros com um beijo santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Todos os santos vos saúdam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'Que a graça do Senhor Jesus Cristo, o amor de Deus, e a comunhão do Espírito Santo sejam com todos vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paulo, um apóstolo — não um apóstolo da parte de homens, nem por homem algum, mas por Jesus Cristo e por Deus, o Pai, que O ressuscitou dos mortos —,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'e todos os irmãos comigo, às igrejas da Galácia:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Graça e paz a vós, da parte de Deus Pai e do nosso Senhor Jesus Cristo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'que se entregou por nossos pecados para nos libertar desta presente era maligna, de acordo com a vontade de nosso Deus e Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'A Ele seja a glória para sempre e sempre. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Estou surpreso de que vós estejais mudando tão rapidamente para um Evangelho diferente, afastando-vos Daquele que vos chamou pela graça de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Não há outro evangelho, mas existem algumas pessoas que vos causam problemas, e querem distorcer o Evangelho de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Mas, mesmo se nós, ou um anjo vindo do céu vier a proclamar-vos um evangelho diferente daquele que proclamamos a vós, que seja amaldiçoado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Como dissemos antes, agora eu digo novamente: se alguém vos proclama um evangelho diferente daquele que vós aceitastes, que seja amaldiçoado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Porventura, eu agora quero a aprovação dos homens ou de Deus? Ou estou procurando agradar homens? Se estou tentando ainda agradar aos homens, eu não sou servo de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Porque eu desejo que saibais, irmãos, que o Evangelho que proclamei não é de origem humana.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Eu não o recebi de homem, nem me ensinaram, mas, ao invés disto, ele foi-me revelado por meio de Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Ouvistes falar sobre minha antiga vida no judaísmo, como eu perseguia violentamente a igreja de Deus, e a devastava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'Eu progredi no judaísmo mais do que muitos judeus da minha idade, sendo muito mais zeloso na tradição dos meus antepassados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Mas, quando Deus, que Se agradou em me escolher desde o ventre da minha mãe, me chamou pela Sua graça');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'para revelar Seu Filho em mim, para proclamá-Lo entre os Gentios, eu não consultei nem carne nem sangue,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'nem subi a Jerusalém àqueles que eram apóstolos antes de mim, mas, ao invés disto, fui à Arábia e então retornei a Damasco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Então, três anos depois, subi a Jerusalém para visitar Cefas, e fiquei com ele por quinze dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Mas eu não vi nenhum dos outros apóstolos, exceto Tiago, o irmão do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'No que vos escrevo, asseguro, diante de Deus, que eu não estou mentindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Depois, eu fui às regiões da Síria e da Cilícia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Eu ainda não era conhecido pessoalmente pelas igrejas da Judeia que estavam em Cristo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'mas eles apenas ouviam: \"Aquele que antes nos perseguia agora está proclamando a fé que ele procurava destruir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'E eles glorificavam a Deus por minha causa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Então, depois de catorze anos, eu fui de novo para Jerusalém com Barnabé, levando Tito também comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Eu fui por causa de uma revelação e expliquei-lhes o evangelho que estou proclamando entre os gentios. Eu falei particularmente para aqueles que pareciam ter mais influência, para ter certeza de que eu não corra, ou tenha corrido em vão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Mas nem mesmo Tito que estava comigo, o qual era grego, foi forçado a ser circuncidado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Esta questão surgiu por causa dos falsos irmãos que vieram em secreto para espionar a liberdade que temos em Cristo Jesus. Eles desejavam reduzir-nos à escravidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Mas nós não nos rendemos em submissão a eles nem mesmo por um momento, para que a verdade do evangelho continue imutável para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Mas aqueles que disseram que eram líderes não contribuíram em nada comigo. Não importa para mim a posição que eles tinham. Deus não julga pela aparência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Ao contrário, eles viram que me foi confiada a proclamação do evangelho aos que são incircuncisos, assim como Pedro estava para proclamar o evangelho aos que são circuncidados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, 'pois Deus, que trabalhou em Pedro para o apostolado aos que são circuncidados, também trabalhou em mim para os gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'Quando Tiago, Cefas e João, que eram reconhecidos como aqueles que eram colunas da igreja, compreenderam a graça que me tinha sido dada, eles estenderam a mão direita da fraternidade a Barnabé e a mim. Eles fizeram isso para que nós pudéssemos ir aos gentios, e para que eles fossem aos que eram circuncidados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Eles também queriam que nos lembrássemos dos pobres. O que eu também estava ansioso para fazê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Porém, quando Cefas veio para Antioquia, eu lhe resisti fortemente, pois ele estava errado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Antes que viessem certos homens da parte de Tiago, Cefas comia juntamente com os gentios. Mas, quando esses homens vieram, ele se retirou e manteve-se distante dos gentios, pois ele temia os que exigiam a circuncisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Também os outros judeus juntaram-se a Cefas nessa hipocrisia. O resultado foi que até Barnabé se deixou levar pela hipocrisia deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Mas, quando eu vi que eles não estavam seguindo a verdade do evangelho, eu falei para Cefas diante de todos: \"Se vós sois judeus, mas estais vivendo à maneira dos gentios e não como os judeus, como podeis forçá-los a viver como judeus?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Nós, que somos judeus por nascimento e não \"pecadores gentios\",');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'sabemos que ninguém é justificado pela obra da Lei mas pela fé em Cristo Jesus. Nós viemos à fé em Cristo para que possamos ser justificados pela fé Nele e não pelas obras da Lei. Porque pelas obras da Lei nenhuma carne será justificada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Mas, se quando buscamos ser justificados em Cristo, fomos também nós mesmos achados pecadores, assim Cristo se tornaria um ministro do pecado? Certo que não!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Pois, se eu reconstruo aquelas coisas que eu já destruí, eu me faço um transgressor da Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Eu, pois, mediante a Lei, morri para a Lei, para que eu possa viver para Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Eu fui crucificado com Cristo, assim não vivo mais eu, mas Cristo vive em mim. A vida que agora vivo na carne eu vivo pela fé no Filho de Deus, que me amou e deu a sua vida por mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Não posso negar a graça de Deus, pois se a justificação existisse através da Lei, então Cristo morreu inutilmente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'Gálatas insensatos, quem foi que vos enfeitiçou? Não foi a crucificação de Jesus Cristo vividamente representada diante de vossos olhos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Eu só quero saber isto de vós: recebestes o Espírito pelas obras da lei ou por acreditardes no que ouvistes?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Sois vós assim tão tolos? Começastes no Espírito para agora simplesmente terminardes na carne?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Sofrestes tantas coisas por nada? Seria de fato isso em vão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Aquele que dá o Espírito a vós, e opera poderosas obras entre vós, faz isso pelas obras da Lei ou pelo ouvir com fé?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Como Abraão \"creu em Deus e isto lhe foi creditado como justiça\",');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'sabei, da mesma forma, que aqueles que acreditam são filhos de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'A Escritura, prevendo que Deus justificaria os gentios pela fé, de antemão proclamou esta boa nova para Abraão, dizendo: \"Em ti, todas as nações serão abençoadas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Assim, os que são da fé são abençoados juntamente com Abraão, o homem de fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Pois todos os que confiam nas obras da Lei estão debaixo de uma maldição, pois está escrito: \"Maldito é todo o que não permanece na prática de todas as coisas escritas no livro da Lei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Agora está claro que Deus não justifica ninguém pela Lei, pois \"O justo viverá pela fé\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'A Lei não é de fé, mas, em vez disso, \"Aquele que faz as obras da Lei viverá por elas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Cristo nos redimiu da maldição da Lei, tornando-se maldição por nós, pois está escrito: \"Maldito é todo aquele que é pendurado no madeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'A fim de que a bênção de Abraão possa vir aos gentios em Cristo Jesus, de forma que, pela fé possamos receber a promessa do Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Irmãos, falarei como homem. Mesmo em um testamento humano, ninguém o anula nem lhe acrescenta algo, uma vez que é estabelecido pela lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Agora, as promessas foram ditas a Abraão e ao seu descendente. Não é dito \"aos descendentes\", referindo-se a muitos; mas, em vez disso, a apenas um, \"ao seu descendente\", que é Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Agora, o que digo é isto: a Lei, vinda quatrocentos e trinta anos depois, não deixa de lado o Testamento previamente estabelecido por Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Pois se a herança vem pela Lei, então não vem mais pela promessa. Todavia, Deus deu a herança a Abraão por uma promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Qual é, então, o propósito da Lei? Ela foi acrescentada por causa das transgressões, até que o descendente de Abraão viesse àqueles para quem a promessa tinha sido feita. A Lei foi promulgada por meio de anjos por um mediador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Mas, um mediador implica em mais de uma pessoa; porém, Deus é um.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Então, é a Lei contra as promessas de Deus? De jeito nenhum! Pois se tivesse sido dada uma lei capaz de dar vida, a justiça certamente teria vindo pela Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Mas a Escritura aprisionou todas as coisas debaixo do pecado. Deus assim o fez a fim de que a promessa da salvação pela fé em Jesus Cristo fosse dada aos que creem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Mas, antes que a fé em Cristo viesse, nós estávamos aprisionados e confinados debaixo da Lei, até a revelação da fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Então a Lei se tornou nossa tutora, até que Cristo viesse, para que pudéssemos ser justificados pela fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Agora que a fé veio, nós não mais estamos sob um tutor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Pois vós sois todos filhos de Deus, pela fé em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Todos vós que fostes batizados em Cristo vos revestistes de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Não há judeu nem grego, nem escravo nem livre, nem homem nem mulher; pois vós sois todos um em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Se vós sois de Cristo, então, sois descendentes de Abraão, herdeiros de acordo com a promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Estou dizendo que o herdeiro, enquanto for uma criança, não é diferente de um escravo, embora seja o dono de toda a propriedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Entretanto, ele está sujeito a tutores e curadores até o tempo determinado pelo seu pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Assim também nós, quando éramos crianças, éramos mantidos escravizados pelos princípios elementares do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Mas, quando chegou o tempo exato, Deus enviou Seu Filho, nascido de mulher, nascido sob a Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Ele fez isso para resgatar os que estavam sob a Lei, a fim de que recebêssemos a adoção como filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'E porque vós sois filhos, Deus enviou o Espírito de Seu Filho em nossos corações, que clama \"Aba, Pai!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'De modo que você já não é mais um escravo, mas um filho. Se és um filho, então és também herdeiro através de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Mas, naquele momento, quando vós não conhecíeis a Deus, fostes feitos para serdes escravos dos que por natureza não eram deuses de modo algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Mas, agora que conheceis a Deus, ou melhor, agora que vós sois conhecidos por Deus, por que estais voltando aos fracos e miseráveis princípios elementares? Quereis ser escravos novamente?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Vós guardais dias e luas novas, estações e anos!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Eu temo por vós que, de algum modo, eu tenha trabalhado em vão para convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Eu vos imploro, irmãos, tornem-se como eu, porque eu também me tornei como vós. Vós não me fizestes mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Mas vós sabeis que foi por uma enfermidade física que eu vos anunciei o evangelho pela primeira vez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'Apesar de a minha condição física ter-vos colocado em prova, vós não me desprezastes ou rejeitastes. Ao invés disso, recebestes a mim como a um anjo de Deus, como se eu fosse o próprio Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Onde, então, está a vossa alegria? Pois eu vos testifico que, se possível, vós teríeis arrancado vossos próprios olhos para dá-los a mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Então, tornei-me vosso inimigo por vos dizer a verdade?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Eles zelosamente vos procuram, mas não para o bem. Eles querem separar-vos de mim para que os sigam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'É sempre bom serdes zelosos por bons propósitos e não apenas quando eu estou presente entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Meus filhinhos, estou sofrendo dores de parto por vós novamente, até Cristo ser formado em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Eu gostaria de estar presente convosco agora e mudar meu tom, porque eu estou perplexo sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Dizei-me vós, que desejais estar debaixo da Lei: não ouvistes o que a Lei diz?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Porque está escrito que Abraão teve dois filhos, um da mulher escrava e outro da livre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Contudo o da escrava nasceu segundo a carne, mas o filho da outra nasceu mediante a promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Essas coisas podem ser interpretadas alegoricamente, pois essas duas mulheres são como duas alianças. Uma delas é a do Monte Sinai. Ela dá à luz crianças que são escravas. Essa é Agar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Então, Agar representa o Monte Sinai na Arábia. E ela simboliza a atual Jerusalém, pois ela está em escravidão com seus filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Mas a Jerusalém que está acima é livre, e ela é nossa mãe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Porque está escrito: \"Regozija-te, ó estéril, que não dás à luz. Clama e exulta de alegria tu, que não sofres as dores de parto. Porque os filhos da mulher abandonada são mais numerosos do que os da que tem marido\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Agora vós, irmãos, assim como Isaque, sois filhos da promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Naquele tempo, o que nasceu de acordo com a carne perseguiu o que nasceu de acordo com o Espírito. Assim também é agora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'O que as Escrituras dizem? \"Lança fora a escrava e seu filho. Porque o filho da escrava não compartilhará da herança com o filho da mulher livre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Assim sendo, irmãos, nós não somos filhos da mulher escrava, mas da mulher livre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Portanto, foi para a liberdade que Cristo nos libertou. Entretanto, permanecei firmes, e não vos coloqueis novamente debaixo do jugo da escravidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Vede, eu, Paulo vos digo que se vos deixardes circuncidar, Cristo nada vos beneficiará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Outra vez eu testifico a cada homem que se deixa circuncidar, que ele se torna obrigado a obedecer toda a Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Vós estais separados de Cristo, vós que desejais ser justificados pela Lei; vós não mais experimentais graça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Pois, através do Espírito, pela fé, nós esperamos ansiosamente pela esperança da justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Em Cristo Jesus nem circuncisão nem incircuncisão significam coisa alguma, mas somente a fé trabalhando através do amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Vós estáveis correndo bem. Quem vos impediu de obedecer a verdade?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Essa persuasão não vem Daquele que vos chama.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Um pouco de fermento faz toda a massa crescer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Eu confio no Senhor que vós não tereis outra visão. Aquele que vos está perturbando será punido, quem quer que seja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Irmãos, se eu ainda proclamo a circuncisão, por que ainda sou perseguido? Neste caso o escândalo da cruz foi removido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'E para todos que estão vos perturbando, eu que gostaria que eles se castrassem!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Porque vós, irmãos, fostes chamados para a liberdade; contudo não useis vossa liberdade como uma oportunidade para a natureza pecaminosa, em vez disso, servi-vos uns aos outros por amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Pois toda a Lei é cumprida em um mandamento: \"Amareis ao teu próximo como a ti mesmo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Entretanto se vós mordeis e devorais uns aos outros, cuidai para que não sejais consumidos uns pelos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Contudo eu vos digo, andai pelo Espírito e não satisfareis os desejos da natureza pecaminosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Pois os desejos da natureza pecaminosa são contra o Espírito, e os desejos do Espírito são contra a natureza pecaminosa, porque estes estão em conflito um com o outro. O fim é para que vós não façais as coisas que desejais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Mas, se sois guiados pelo Espírito, não estais debaixo da Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Agora, as obras da natureza pecaminosa são evidentes: imoralidade sexual, impureza, lascívia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'idolatria, feitiçaria, hostilidade, briga, ciúme, ira, rivalidade, dissensões, divisão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'inveja, embriaguez, orgia, e como essas coisas. Eu vos advirto, como o fiz anteriormente, que todos aqueles que praticam essas coisas não herdarão o Reino de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Mas o fruto do Espírito é amor, alegria, paz, paciência, benignidade, bondade, fé,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'gentileza, domínio próprio; contra essas coisas não há Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Aqueles que pertencem a Cristo Jesus crucificaram a natureza pecaminosa com suas paixões e desejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Se nós vivemos pelo Espírito, vamos também andar pelo Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Não nos tornemos orgulhosos, provocando uns aos outros, ou invejando uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Irmãos, se um homem for pego em alguma transgressão, vós que sois espirituais deveis restaurar esta pessoa com espírito de gentileza; e cuidai de vós mesmos, para que também não venhais a ser tentados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Carregai os fardos uns dos outros, e assim cumprireis a lei de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Pois se alguém pensa ser alguma coisa, quando não é nada, engana-se a si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Cada um deve examinar sua própria conduta; então, terá algo apenas em si mesmo para se orgulhar, sem se comparar com qualquer outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Pois cada um vai carregar sua própria carga.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Aquele a quem é ensinada a Palavra precisa compartilhar todas as coisas boas com quem o instrui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Não vos enganeis, de Deus não se zomba. Tudo aquilo que o homem plantar é o que ele também colherá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Pois aquele que planta para sua própria natureza pecaminosa, colherá destruição; mas aquele que planta para o Espírito, colherá vida eterna do Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Nós não devemos nos cansar de fazer o bem, pois no tempo certo vamos alcançar a colheita, se não desistirmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Assim, enquanto temos oportunidade, façamos o bem a todos, especialmente para aqueles da família da fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Vede com que letras grandes eu vos escrevo com minha própria mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Aqueles que querem causar uma boa impressão na carne vos obrigam a ser circuncidados, somente para que eles não venham a ser perseguidos pela cruz de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Pois nem aqueles que se circuncidam cumprem a Lei; mas eles querem que sejais circuncidados para terem motivo de orgulho na vossa carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Que nunca aconteça de eu me orgulhar, exceto da cruz de nosso Senhor Jesus Cristo, por meio do qual o mundo está crucificado para mim, e eu para o mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Pois nem a circuncisão, nem a incircuncisão, é alguma coisa, mas o ser uma nova criação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'E a todos que vivem de acordo com este padrão, que a paz e a misericórdia sejam sobre eles, e sobre o Israel de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Que, de agora em diante, ninguém me cause perturbações, pois carrego as marcas de Jesus em meu corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Que a graça do nosso Senhor Jesus Cristo seja com o vosso espírito, irmãos. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paulo, apóstolo de Cristo Jesus, pela vontade de Deus, aos santos de Deus em Éfeso, e que são fiéis em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Graça a vós, e paz que vem de Deus nosso Pai e do Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Que o Deus e Pai de nosso Senhor Jesus Cristo seja louvado, que nos abençoou com toda bênção espiritual nos lugares celestiais em Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Antes da criação do mundo, Deus nos escolheu em Cristo para que sejamos santos e inculpáveis aos Seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Deus nos predestinou para adoção como filhos, por meio de Jesus Cristo, conforme a bondade da Sua vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Nossa adoção resulta no louvor da Sua graça gloriosa, que Ele livremente nos deu no Amado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'Em Jesus Cristo, nós temos redenção pelo Seu sangue, e o perdão de pecados, conforme as riquezas da Sua graça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Ele derramou abundantemente Sua graça sobre nós em toda sabedoria e entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Deus fez com que conhecêssemos o propósito oculto da Sua vontade, de acordo com o que Lhe agradava, e que demonstrou em Cristo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'com vistas a um plano para a plenitude do tempo, de modo a fazer convergir todas as coisas, tanto no céu como na terra, sob uma cabeça, Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Em Cristo, fomos nomeados herdeiros, e escolhidos antecipadamente, de acordo com o plano Daquele que faz todas as coisas pelo desígnio de Sua vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Deus nos fez herdeiros para que fôssemos os primeiros a ter confiante esperança em Cristo, de modo que pudéssemos existir para o louvor de Sua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'Em Cristo, também ouvistes a palavra da verdade, o Evangelho da vossa salvação, e crestes Nele, e fostes selados com o Espírito Santo que havia sido prometido,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'o qual é a garantia de nossa herança, até que tenhamos a posse completa dela, para o louvor da Sua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Por causa disso, desde quando ouvi sobre a vossa fé no Senhor Jesus, e sobre o vosso amor por todo o povo santo de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'não parei de agradecer a Deus por vós e de mencionar-vos em minhas orações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Eu oro para que o Deus de nosso Senhor Jesus Cristo, o Pai da glória, vos dê um espírito de sabedoria e de revelação no Seu conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Oro para que os olhos do vosso coração sejam iluminados, para saberdes qual é a confiante esperança para a qual Ele vos chamou, e as riquezas da gloriosa herança Dele entre todo o povo santo de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'Em minhas orações, peço que conheçais a imensurável grandeza do Seu poder, que está em nós que cremos, conforme a obra de Sua grande força.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Esse é o mesmo poder que Deus operou em Cristo quando ressuscitou-O dos mortos e O fez sentar-Se à Sua direita nos lugares celestiais,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'muito acima de todo governo, autoridade, poder, domínio e todo nome que é pronunciado. Cristo não governará apenas nesta era, mas também na que há de vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Deus sujeitou tudo debaixo dos pés de Cristo, e O entregou à Igreja como cabeça sobre todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'A Igreja é o Seu corpo, a plenitude Daquele que preenche tudo em todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'E quanto a vós, estáveis mortos em vossas transgressões e pecados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'nos quais antes andastes, de acordo com os caminhos deste mundo, segundo o governante das autoridades do ar. Esse é o espírito daquele que está operando nos filhos da desobediência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Todos nós estivemos antes entre esses incrédulos, e agíamos segundo os maus desejos de nossa carne, fazendo a vontade da carne e da mente. Éramos por natureza filhos da ira como os demais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Mas Deus é rico em misericórdia, por causa de Seu grande amor com que Ele nos amou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'Enquanto estávamos mortos em transgressões, Ele nos trouxe à vida juntamente com Cristo. É pela graça que vós fostes salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Deus nos ressuscitou com Ele e nos fez sentar juntamente nos lugares celestiais em Cristo Jesus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'para que, nos tempos vindouros, Ele pudesse mostrar-nos as imensuráveis riquezas da Sua graça pela Sua bondade em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Porque pela graça sois salvos, por meio da fé, e isso não vem de vós; é dom de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Não é por obras, para que ninguém se glorie.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Porque nós somos feitura de Deus, criados em Cristo Jesus para fazer boas obras, as quais Deus planejou há muito tempo para nós, para que andássemos nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Portanto lembrai-vos, gentios na carne, chamados \"incircuncisão\" por aqueles que foram circuncidados na carne por mãos humanas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'que naquele tempo vós estáveis separados de Cristo. Éreis estrangeiros ao povo de Israel e alheios às alianças da promessa, não tendo esperança acerca do futuro e sem Deus no mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Mas agora, em Cristo Jesus, vós, que antes estáveis longe de Deus, fostes trazidos para perto Dele pelo sangue de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Porque Ele é a nossa paz. Ele fez de ambos um só. Pela Sua carne Ele destruiu o muro de inimizade que nos separava.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Isto é, Ele aboliu a lei de mandamentos e regulamentos para que pudesse criar um novo homem Nele, estabelecendo a paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'Cristo reconciliou ambos os povos com Deus em um só corpo por meio da cruz, matando a inimizade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Jesus veio e proclamou paz para vós que estáveis longe e paz para aqueles que estavam perto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Pois, por meio de Jesus, ambos temos acesso ao Pai em um Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Então agora, vós, gentios, não sois mais estrangeiros e forasteiros. Ao invés disso, sois concidadãos com o santo povo de Deus, sois membros da família de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Fostes edificados sobre o fundamento dos apóstolos e dos profetas, sendo o próprio Cristo Jesus a pedra angular.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'Nele, todo o edifício se encaixa e cresce como um templo no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'É Nele que também estais sendo edificados juntos como uma morada para Deus no Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Por causa disso eu, Paulo, sou prisioneiro de Cristo Jesus por vós, gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Suponho que ouvistes sobre a tarefa que me foi dada, de levar a graça de Deus para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Escrevo segundo a revelação que me foi manifestada. Esta é a verdade oculta sobre a qual eu escrevi um pouco em outra carta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Quando lerdes sobre isto, sereis capazes de entender o meu discernimento desta verdade oculta sobre Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Em outras gerações, esta verdade não foi manifestada aos filhos dos homens, mas agora ela tem sido revelada pelo Espírito aos Seus consagrados apóstolos e profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Esta verdade oculta é que os gentios também são herdeiros e membros do corpo. Eles são co-participantes na promessa em Cristo Jesus, por meio do Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Por isso, tornei-me um servo desse Evangelho pelo dom da graça de Deus, que foi dada a mim por obra do Seu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Deus me deu esse dom, embora eu seja o menor de todos os santos, para que eu proclamasse aos gentios o Evangelho das insondáveis riquezas de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'O dom de Deus para mim é iluminar a todos sobre o Seu mistério que foi oculto ao longo dos séculos no passado por Deus, Criador de todas as coisas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'de modo que, agora, pela igreja, os principados e potestades nos lugares celestiais venham a conhecer a multiforme sabedoria de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Isso aconteceu segundo o eterno propósito que Ele cumpriu em Cristo Jesus, nosso Senhor,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'pelo qual nós temos ousadia e acesso com confiança, por causa da nossa fé Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Portanto eu vos peço que não fiqueis desencorajados pelos meus sofrimentos por vós, os quais são a vossa glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Por essa causa, eu dobro os meus joelhos ao Pai,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'do Qual cada família no céu e na terra recebe o nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Oro para que Ele vos conceda, segundo as riquezas da Sua glória, que sejais fortalecidos com poder, pelo Seu Espírito, que está em vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Oro para que Cristo possa viver em vosso coração pela fé, e para que sejais enraizados e alicerçados em Seu amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Oro para que possais entender, junto com todos os crentes, qual é a largura, o comprimento, a altura e a profundidade do amor de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'Oro para que conheçais o amor de Cristo, que excede o conhecimento, e para que sejais preenchidos com toda a plenitude de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Ora, Àquele que é capaz de fazer todas as coisas infinitamente além do que nós pedimos ou pensamos, segundo o Seu poder que opera em nós,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'a Ele seja a glória na igreja e em Cristo Jesus, por todas as gerações, para todo o sempre. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Eu, portanto, como o prisioneiro no Senhor, imploro a vós que andeis de modo digno do chamado que recebestes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'que vivais com grande humildade, mansidão e paciência, aceitando uns aos outros em amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Fazei o melhor de vós para manter a unidade do Espírito no vínculo da paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Existe um corpo e um Espírito, assim como também vós fostes chamados em uma expectativa confiante do vosso chamado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'E existe um Senhor, uma fé, um batismo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'e um Deus e Pai de todos. Ele é sobre todos por meio de todos e em todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Para cada um de nós foi dado um dom de acordo com a medida do dom de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Como dizem as Escrituras: \"Quando Ele subiu às alturas, levou cativo o cativeiro, e deu dons às pessoas”.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Qual é o significado de \"Ele subiu\", senão que Ele também desceu às profundezas da terra?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'A pessoa que desceu é a mesma que também subiu bem acima de todos os céus, para preencher todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Cristo deu alguns para serem apóstolos, profetas, evangelistas, e alguns como pastores e mestres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Ele deu esses ofícios para equipar Seu santo povo para desempenhar Seu serviço, para a edificação do corpo de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Ele continua edificando Seu corpo até que todos nós alcancemos a unidade da fé e o conhecimento do Filho de Deus e até que nos tornemos maduros como aqueles que alcançaram a plena estatura de Cristo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'a fim de não sermos mais como crianças que são jogadas para trás e para adiante pelas ondas, levados por todo vento de ensinamento, pelos truques de pessoas em seus esquemas ardilosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Em vez disso, falando a verdade em amor, nós estamos crescendo em todos caminhos em direção a Ele, que é a cabeça, Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Cristo edifica todo o corpo, o qual está junto e unido pela ajuda de ligamentos; e, quando cada parte trabalha junto, isso faz o corpo crescer e edificar a si mesmo em amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Portanto eu digo e insisto nisto, no Senhor: que não mais vivais como os gentios vivem, na futilidade de suas mentes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Eles estão obscurecidos em seus pensamentos, alienados da vida de Deus pela ignorância que está neles, por causa da dureza de seus corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Eles não sentem vergonha, tendo se entregado à sensualidade, e eles estão continuamente praticando todo tipo de impureza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Mas não é assim que aprendestes a respeito de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Suponho que ouvistes sobre Ele, e que fostes ensinados Nele, como a verdade está em Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Vós aprendestes a vos despir do que pertence a vossa maneira antiga de viver, despirdes do velho homem. Este é o velho homem que é corrupto por causa destes desejos enganosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Vós fostes ensinados a renovardes no espírito da vossa mente,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'e revestirdes do novo homem que é criado na imagem de Deus, em verdadeira justiça e santidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Portanto deixai a mentira e falai a verdade para com seu vizinho, porque nós somos membros uns dos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Irai-vos mas não pequeis. Não permitais que o sol se ponha sobre a vossa ira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Não deis oportunidade para o diabo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Aquele que roubava não roube mais; deve trabalhar, fazendo coisas úteis com as suas mãos, de modo que possa compartilhar com todos que estão em necessidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Não permita que alguma palavra imunda saia da vossa boca, fale apenas palavras que sejam úteis para edificar outros, conforme a necessidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'E não ofendais o Espírito Santo de Deus, pelo qual fostes selados para o dia da redenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Deveis afastar toda amargura, cólera, raiva, gritaria e insultos, juntamente com todo tipo de mal;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'e sede bondosos uns para com os outros, compassivos, perdoando uns aos outros, assim como Deus em Cristo vos perdoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Portanto tornai-vos imitadores de Deus, como Seus filhos amados,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'e andai em amor, como Cristo nos amou e a Si mesmo se entregou por nós, como uma oferta e sacrifício de aroma agradável a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Não deve existir entre vós nem sequer menção de imoralidade sexual ou qualquer impureza, ou cobiça, como é apropriado aos santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Nem devem ser mencionadas obscenidades, conversas tolas ou gracejos imorais, que são impróprias, em vez disso deve haver ações de graça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Pois estejais certos de que nenhuma pessoa sexualmente imoral, impura, cobiçosa, que é idólatra, tem qualquer herança no Reino de Cristo e de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Não deixeis ninguém vos enganar com palavras vazias. Por causa dessas coisas, a ira de Deus vem sobre os filhos da desobediência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Portanto não sejais participantes com eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Pois antes vós fostes trevas, mas agora sois luz no Senhor. Então andai como filhos da luz,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(pois o fruto da luz consiste em toda bondade, justiça e verdade),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'procurando sempre saber o que é agradável ao Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Não tenhais nenhuma participação com as obras infrutíferas das trevas, mas reprovai-as,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'pois as coisas feitas por eles em segredo são muito vergonhosas até de serem mencionadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Todas as coisas, quando expostas pela luz, se tornam visíveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Pois tudo o que se torna visível é luz. Por isso que se diz: \"Desperta, ó tu que dormes, levanta-te dentre mortos, e Cristo brilhará em ti\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Portanto sede cuidadosos em como andais, não como insensatos, mas como sábios,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'remindo o tempo, porque os dias são maus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Não sejais loucos, mas entendei qual é a vontade do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'E não vos embriagueis com vinho, pois isso leva à ruína. Em vez disso, sede cheios do Espírito Santo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'falando uns com os outros com salmos, hinos e cânticos espirituais; cantando e louvando com todo o vosso coração ao Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Sempre dando graças por todas as coisas ao nosso Deus e Pai, em nome de nosso Senhor Jesus Cristo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'sujeitando-vos uns aos outros no temor de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Esposas, sujeitai-vos aos vossos maridos como ao Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Pois o marido é cabeça da esposa, como também Cristo é cabeça da Igreja, sendo Ele o Salvador do corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Mas, assim como a igreja está sujeita a Cristo, então também as esposas devem ser sujeitas ao seus maridos em tudo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Maridos, amai vossas esposas como Cristo amou a Igreja e a Si mesmo se entregou por ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Ele o fez para que pudesse torná-la santa, tendo-a purificado por meio da lavagem de água pela palavra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'de modo que pudesse apresentar para Ele mesmo uma Igreja gloriosa, sem manchas nem rugas nem coisa semelhante, mas santa e irrepreensível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Da mesma forma, os maridos devem amar suas próprias esposas como a seus próprios corpos. Aquele que ama sua esposa ama a si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Pois ninguém jamais odiou o próprio corpo. Em vez disso, alimenta e cuida dele como Cristo também cuida da igreja,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'porque somos membros do Seu corpo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, '\"Por essa razão, o homem deixará seu pai e sua mãe e se unirá com sua esposa, e os dois se tornarão uma só carne\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Esse é um grande mistério, mas eu estou falando sobre Cristo e a Igreja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Entretanto cada um de vós também deve amar sua própria esposa como a si mesmo, e a esposa deve respeitar seu marido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Filhos, obedecei a vossos pais no Senhor, pois isso é correto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '\"Honra teu pai e tua mãe\" — este é o primeiro mandamento com promessa —,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '\"para que te vá bem, e tenhas vida longa na terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'E vós, pais, não provoqueis vossos filhos à ira. Em vez disso, criai-os na disciplina e instrução do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Escravos, sede obedientes aos vossos senhores terrenos com temor e tremor, na honestidade do vosso coração. Sede obedientes a eles, assim como a Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Sede obedientes não apenas quando vossos senhores estiverem vigiando, de modo a agradá-los. Ao invés disso, sede obedientes como escravos de Cristo, o qual, de coração, fez a vontade de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Servi com todo o vosso coração, como ao Senhor, e não a pessoas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'porque nós sabemos que, para qualquer boa obra que cada pessoa fizer, receberá uma recompensa do Senhor, seja ele escravo ou livre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'E vós, senhores, fazei as mesmas coisas para vossos escravos, sem ameaças. Sabendo que Aquele que é o Senhor deles e vosso está nos céus, e que não há favoritismo da parte Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Finalmente, sede fortes no Senhor e na força do Seu poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Revesti-vos de toda a armadura de Deus, para que possais suportar os planos traiçoeiros do diabo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Porque nossa luta não é contra carne e sangue, mas contra os principados, contra as potestades, contra os que dominam o maligno reino das trevas, contra os espíritos malignos em lugares celestiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Por isso, revesti-vos de toda a armadura de Deus, para serdes capazes de resistir no tempo mau e, havendo feito tudo, permanecer firmes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Portanto, ficai firmes, após terdes colocado o cinto da verdade e a couraça da justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'Calçai os pés com a prontidão para proclamar o Evangelho da paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Em todas as circunstâncias, tomai o escudo da fé, pelo qual sereis capazes de apagar todos os dardos inflamados do maligno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'E colocai o capacete da salvação e a espada do Espírito, que é a Palavra de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Com toda oração e súplica, orai a todo tempo, no Espírito, para que estejais sempre vigiando, com toda perseverança e oração por todos os santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'E orai também por mim, para que a mensagem possa me ser dada quando eu abrir a minha boca. Orai para que, com ousadia, eu possa fazer conhecida a verdade oculta do Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'É pelo Evangelho que eu sou um embaixador em cadeias, de modo que, na prisão, eu possa falar corajosamente, como devo falar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Tíquico, meu amado irmão e fiel servo no Senhor, vos fará tudo conhecido, para que também saibais o que estou fazendo e como estou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Eu o enviei para vós com este propósito, para que saibais a nosso respeito, e para que ele conforte o vosso coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Que a paz esteja com os irmãos, e o amor com fé da parte de Deus, o Pai e do Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Que a graça esteja com todos aqueles que amam nosso Senhor Jesus Cristo com um amor que nunca morre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paulo e Timóteo, servos de Jesus Cristo, a todos os santos em Cristo Jesus que estão em Filipos, com os bispos e diáconos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Graça a vós, e paz de Deus, nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Agradeço ao meu Deus, todas as vezes que lembro de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Sempre, em todas as minhas orações por vós, é com alegria que oro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Dou graças por vossa participação no Evangelho, desde o primeiro dia até agora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Estou confiante disto: Aquele que começou a boa obra em vós a completará até o dia de Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'É justo sentir-me assim a respeito de todos vós, pois vos tenho em meu coração. Todos vós tendes sido meus parceiros na graça, tanto em minhas prisões quanto na defesa e confirmação do Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Pois Deus é minha testemunha de como tenho anseio por todos vós, com a compaixão de Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'E isto oro: que o vosso amor cresça mais e mais no conhecimento e completo entendimento;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'para que aproveis as coisas que são excelentes, de maneira que sejais sinceros e irrepreensíveis no dia de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Oro também para que sejais cheios do fruto de justiça, que vem por meio de Jesus Cristo, para a glória e louvor de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Agora, quero que saibais, irmãos, que as coisas que me aconteceram serviram muito para o progresso do Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Como resultado, minhas prisões em Cristo tornaram-se conhecidas por toda a guarda do palácio, e por todos os outros;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'e a maioria dos irmãos tornaram-se, no Senhor, mais confiantes devido ao meu aprisionamento, para ousar falar a Palavra de Deus sem medo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Alguns, efetivamente, proclamam a Cristo por inveja e contenda, e outros, porém, o fazem com boa intenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Aqueles que proclamam a Cristo por amor, sabem que fui posto aqui em defesa do Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Outros proclamam a Cristo por ambição egoísta e, não, com sinceridade, pensando que me afligem enquanto estou aprisionado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Mas, que importa? De qualquer maneira, seja por pretexto ou em verdade, Cristo é anunciado, e nisto eu me regozijo. Sim, e eu me alegrarei,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'pois sei que isso resultará em minha salvação, por meio das vossas orações e pela provisão do Espírito de Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'De acordo com a minha intensa expectativa e convicta esperança de que em nada serei envergonhado, e ainda com toda ousadia, como sempre, Cristo será exaltado em meu corpo, seja pela vida ou pela morte;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'porque para mim o viver é Cristo e o morrer é lucro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Mas, se o viver no corpo significa fruto para o meu trabalho, qual devo escolher? Eu não sei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Pois sou pressionado por ambos os lados. Meu desejo é partir e estar com Cristo, o que é muito melhor;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'no entanto, permanecer no corpo é mais necessário, por causa de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Estando confiante disto, sei que permanecerei e continuarei com todos vós, para vosso progresso e alegria na fé;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'para que, por minha causa, cresçam os motivos de vos gloriardes em Cristo, quando eu vier novamente até vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Acima de tudo, vivei de maneira digna do Evangelho de Cristo, para que, indo ver-vos ou estando distante, possa ouvir a vosso respeito que estais firmes, em um só espírito, com uma só alma, lutando juntos pela fé do Evangelho;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'e em nada sendo intimidados pelos vossos inimigos. Isto é para eles um sinal de sua própria destruição; mas, para vós, um sinal da salvação, vinda de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Porque para vós tem sido concedida a graça de não somente crer em Cristo, mas também sofrer por causa Dele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'tendo o mesmo combate que vistes em mim e que agora ouvis que está em mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Se há algum encorajamento em Cristo, algum consolo em seu amor, alguma comunhão no Espírito, algumas ternas misericórdias e compaixões,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'tornai minha alegria completa por um mesmo pensamento, tendo o mesmo amor, sendo unidos em espírito e tendo o mesmo propósito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Não façais nada por egoísmo ou vanglória, mas sim com humildade considerai os outros melhores que vós mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Não presteis atenção apenas nas vossas próprias necessidades, mas também nas dos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Tende em vós os mesmos sentimentos que houve em Cristo Jesus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'o qual existindo em forma de Deus, não considerou o ser igual a Deus como algo a que devia apegar-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Ao invés disso, Ele a Si mesmo se esvaziou, assumiu a forma de um servo, tornando-se em semelhança de homem, foi reconhecido em figura humana,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'a Si mesmo se humilhou, tornando-Se obediente até à morte e morte de cruz!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Portanto também Deus O exaltou sobremaneira e Lhe deu um nome que está acima de todo nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Para que ao nome de Jesus todo joelho se dobre, nos céus, na terra e debaixo da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'E para que toda língua confesse que Jesus Cristo é o Senhor, para a glória de Deus Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Então meus amados, como vós sempre obedecestes não somente na minha presença, mas muito mais agora na minha ausência, desenvolvei a vossa salvação com temor e tremor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Pois é Deus quem atua em vós tanto o querer quanto o realizar, segundo o Seu agrado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Fazei todas as coisas sem reclamações nem discussões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'Agi deste modo para que vos torneis irrepreensíveis e sinceros filhos de Deus sem culpa. E também para que brilheis como luz no mundo, no meio de uma geração desonesta e depravada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Guardando firmemente a Palavra da vida para que eu tenha razão de me gloriar no dia de Cristo, pois eu saberei que não corri e nem trabalhei em vão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Mas mesmo que eu seja derramado como uma oferta de sacrifício e serviço da vossa fé, eu me alegro com todos vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'E da mesma maneira também alegrai-vos e regozijai-vos comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Espero no Senhor Jesus, mandar-vos Timóteo em breve, para que eu também seja encorajado quando receber notícias acerca de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Pois não tenho ninguém de igual sentimento que, como ele, sinceramente cuide dos vossos interesses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Porque todos eles buscam seus próprios interesses, não as coisas de Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Mas vós conheceis o seu caráter provado, porque como uma criança serve ao seu pai, assim ele serviu comigo no Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Portanto espero enviá-lo assim que eu souber o que acontecerá comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Mas estou confiante no Senhor que também eu mesmo irei em breve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Todavia eu penso ser necessário enviar-vos de volta Epafrodito. Ele é meu irmão, cooperador e companheiro de lutas, vosso mensageiro e auxiliador em minhas necessidades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Pois ele estava muito angustiado e ansioso por estar convosco, porque ouvistes que ele estava enfermo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Realmente ele estava tão doente que quase morreu. Porém Deus teve misericórdia dele, e não apenas dele, mas também de mim, para que eu não tivesse tristeza sobre tristeza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Portanto o enviarei o mais rápido possível, para que quando o virdes de novo certamente vos alegrareis e eu estarei livre de preocupação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Recebam no Senhor a Epafrodito com toda alegria e honrai pessoas como ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Pois foi por causa do trabalho de Cristo que ele quase morreu, arriscando sua vida para me servir e suprir o que vós não podíeis fazer por mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Finalmente, meus irmãos, regozijai-vos no Senhor. Para mim, escrever-vos novamente as mesmas coisas não é enfadonho. Estas coisas vos manterão seguros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Cuidado com os cães; cuidado com os maus obreiros; cuidado com a mutilação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Pois nós somos a circuncisão, isto é, nós que adoramos pelo Espírito de Deus nos gloriamos em Cristo Jesus, e não confiamos na carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Mesmo assim, eu próprio poderia confiar na carne. Se alguém pensa que tem confiança na carne, eu poderia ter ainda mais:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'fui circuncidado ao oitavo dia, sou do povo de Israel, da tribo de Benjamim, hebreu de hebreus; no que diz respeito à Lei, um fariseu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Por zelo, persegui a igreja. No que diz respeito à justiça da Lei, eu fui irrepreensível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Mas as coisas que pareciam contar para o meu lucro, eu as considerei como perda por causa de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'De fato, agora eu considero tudo como perda por causa da excelência do conhecimento de Cristo Jesus, meu Senhor. Por Ele eu descartei todas as coisas. Eu as considero como esterco, para ganhar a Cristo');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'e ser achado Nele, não tendo a minha própria justiça vinda da Lei. Em vez disso, eu tenho a justiça que é pela fé em Cristo, justiça que provém de Deus baseada na fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Por isso, agora quero conhecê-Lo, conhecer o poder da Sua ressurreição e a comunhão dos Seus sofrimentos. Eu quero ser transformado na semelhança da Sua morte,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'para, de alguma forma, alcançar a ressurreição dos mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Não que eu já tenha recebido essas coisas ou que tenha me tornado perfeito. Mas eu prossigo para alcançá-lo, pois para isso fui alcançado por Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Irmãos, eu não penso que eu mesmo já o tenha alcançado, mas uma coisa faço: esqueço o que ficou para trás e esforço-me para o que está à frente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Prossigo para o alvo, para ganhar o prêmio do chamado celestial de Deus em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Todos nós, os que somos maduros, pensemos dessa maneira. E, se pensais diferentemente sobre qualquer coisa, Deus também vos revelará isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Contudo mantenhamo-nos firmes no que tivermos alcançado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Irmãos, sede meus imitadores. Observai de perto aqueles que andam conforme o exemplo que vistes em nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Pois há muitos dos quais que eu já vos falei e agora repito com lágrimas, que são inimigos da cruz de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'O destino deles é a destruição. Porque o deus deles é o estômago, e a glória que eles têm é para sua vergonha, visto que eles pensam em coisas terrenas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Mas a nossa pátria está nos céus, de onde também aguardamos o Salvador, o Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Ele transformará nossos corpos humilhados em corpos semelhantes ao Seu corpo glorioso, pelo Seu poder de controlar todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Portanto, meus amados irmãos, os quais muito estimo, minha alegria e coroa, desta forma permanecei firmes no Senhor, amados amigos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Suplico a Evódia e a Síntique que tenham o mesmo pensamento no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Na verdade, rogo também a ti, meu fiel companheiro de jugo: ajude essas mulheres, porque elas trabalharam comigo propagando o evangelho juntamente com Clemente e os demais dos meus companheiros de trabalho, cujos nomes estão no livro da vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Alegrai-vos sempre no Senhor; outra vez direi: Alegrai-vos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Seja conhecida diante de todas as pessoas a vossa bondade. Perto está o Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Não estejais ansiosos por coisa alguma. Antes, em tudo sejam os vossos pedidos conhecidos diante de Deus, por orações e súplicas, com ações de graças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'E a paz de Deus, que excede todo o entendimento, guardará os vossos corações e os vossos pensamentos em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Finalmente irmãos, tudo o que for verdadeiro, tudo o que for honrável, tudo o que for justo, tudo o que for puro, tudo o que for amável, tudo o que for bom, se há alguma excelência, se há algo para ser louvado, nessas coisas pensai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'As coisas que aprendestes, recebestes, ouvistes e vistes em mim, estas fazei, e o Deus da paz estará convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Alegro-me grandemente no Senhor, porque agora finalmente renovastes o vosso cuidado por mim, embora anteriormente estivestes pensando em mim, não houve oportunidade para que vós me ajudásseis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Não digo isto por estar em necessidade. Pois aprendi a estar contente em todas as circunstâncias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Sei o que é estar pobre, e também sei o que é ter abundância. De todas as formas e em todas as coisas, aprendi o segredo de como estar em fartura ou em escassez, em abundância ou em necessidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Posso todas as coisas Naquele que me fortalece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Contudo fizestes bem em compartilhar comigo em minhas dificuldades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Vós, Filipenses, sabeis que no começo do evangelho, quando saí da Macedônia, nenhuma igreja me deu suporte na questão de dar e receber, exceto vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Até enquanto eu estava em Tessalônica, vós enviaste ajuda para as minhas necessidades mais de uma vez.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Não que eu busque as ofertas, mas sim o fruto que é acrescentado para vosso crédito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Tenho recebido todas as coisas, e as tenho em abundância. Estou satisfeito. Recebi de Epafrodito as coisas enviadas por vós. Elas são um aroma doce e suave, um sacrifício aceitável e agradável a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Meu Deus suprirá todas as vossas necessidades de acordo com as Suas riquezas em glória em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Agora para o nosso Deus e Pai seja a glória pelos séculos dos séculos. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Saudai todos os crentes em Cristo Jesus. Os irmãos que estão comigo vos saúdam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Todos os crentes vos saúdam, especialmente aqueles da casa de César.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'A graça do Senhor Jesus Cristo seja com o vosso espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paulo, apóstolo de Jesus Cristo, de acordo com a vontade de Deus, e Timóteo, nosso irmão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'para os santos e fiéis irmãos em Cristo que estão em Colossos. Graça a vós, e paz da parte de Deus nosso Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Damos graças a Deus, Pai do nosso Senhor Jesus Cristo, e sempre oramos por vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Nós ouvimos da vossa fé em Cristo Jesus e do amor que tendes para com todos os santos de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'por causa da esperança reservada para vós nos céus. Vós primeiro ouvistes sobre esta esperança na Palavra da verdade, o Evangelho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'que chegou a vós. E que também está produzindo fruto e crescendo em todo o mundo, tal como também em vós, desde o dia que o ouvistes e conhecestes a graça de Deus na verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Este é o Evangelho que aprendestes com Epafras, nosso amado conservo e companheiro, o qual é um fiel ministro de Cristo, em nosso favor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Ele nos relatou do vosso amor no Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Por esta razão, também nós, desde o dia em que o ouvimos, não cessamos de orar e suplicar para que sejais cheios do conhecimento da sua vontade, em toda sabedoria e entendimento espiritual.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Nós oramos para que andeis dignamente no Senhor, para o seu inteiro agrado, frutificando em toda boa obra e crescendo no conhecimento de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Oramos para que sejais fortalecidos com todo o poder, segundo a força da sua glória, em toda perseverança e paciência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Oramos para que deis graças ao Pai com alegria, que vos capacitou para receber uma parte da herança dos santos na luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Ele nos resgatou do poder das trevas e nos transportou para o Reino do Seu Filho amado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'Em quem temos redenção, isto é, o perdão dos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Ele é a imagem do Deus invisível, o primogênito de toda criação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Pois, Nele, todas as coisas foram criadas, quer nos céus e sobre a terra, as visíveis e as invisíveis; quer tronos ou domínios, ou governos ou autoridades, todas as coisas foram criadas por Ele e para Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Ele é antes de todas as coisas, e todas as coisas Nele subsistem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Ele é a cabeça do corpo, que é a igreja. Ele é o princípio, o primogênito dentre os mortos; assim, Ele tem o primeiro lugar em todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Porquanto, agradou a Deus que toda Sua plenitude, Nele, habitasse,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'e que havendo feito a paz pelo sangue da sua cruz, por meio dele, reconciliasse consigo mesmo todas as coisas, quer sobre a terra, quer nos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'E vós também, outrora, éreis estranhos a Deus e Seus inimigos em vossas mentes e por vossas más obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Mas, agora, vos reconciliou no corpo da sua carne, mediante a Sua morte, para vos apresentar santos, inculpáveis e irrepreensíveis perante Ele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'se continuardes na fé, alicerçados e firmes, não sendo removidos da esperança do Evangelho que ouvistes, que foi proclamado em toda a criação debaixo dos céus. O Evangelho do qual eu, Paulo, me tornei ministro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Agora, me alegro em meus sofrimentos por vós, e completo, na minha carne, o que está faltando das aflições de Cristo a favor do Seu corpo, que é a igreja.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Esta é a igreja da qual sou ministro, segundo a responsabilidade que recebi de Deus, que me foi confiada em favor de vós, para cumprir a Palavra de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Este é o mistério oculto desde os séculos e gerações, mas agora foi manisfestado aos seus santos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'para quem Deus quis fazer conhecidas as riquezas da Sua glória do mistério entre os gentios, isto é, Cristo em vós, a esperança da glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Este é o Cristo que nós proclamamos. Nós admoestamos a todos, os ensinando em toda sabedoria; para que possamos apresentá-los completos em Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Por isso, eu me esforço e luto, de acordo com a Sua força que opera em mim com poder.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Quero que saibais quão grande é a luta que tenho enfrentado por vós, pelos de Laodiceia e por todos quantos não me conhecem pessoalmente,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'para que vossos corações sejam encorajados pela comunhão, em amor, e pelas riquezas da plenitude do entendimento e conhecimento do mistério de Deus, que é Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'Nele estão escondidos todos os tesouros da sabedoria e do entendimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Digo-vos isso para que nenhum de vós seja iludido com palavras persuasivas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'E, apesar de eu não estar convosco em carne, embora esteja em espírito, alegro-me em ver a ordem e a firmeza da vossa fé em Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Assim como recebestes Cristo, o Senhor, andai Nele');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'e Nele estai firmemente plantados e edificados; estabelecidos na fé, tal como fostes instruídos, e abundantes em ações de graças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Cuidai para que ninguém vos escravize com filosofias e vãs sutilezas, de acordo com a tradição dos homens, conforme os rudimentos do mundo, e não segundo Cristo;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'porque Nele habita, corporalmente, toda a plenitude da natureza de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'E Nele, que é o Cabeça de todo poder e autoridade, fostes levados à plenitude.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'Por meio Dele, fostes também circuncidados, não com a circuncisão feita por mãos humanas na remoção do corpo carnal, mas por meio da circuncisão de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Vós fostes sepultados com Ele no batismo e Nele fostes ressuscitados pela fé no poder de Deus, que O ressuscitou dentre os mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Quando estáveis mortos nas vossas transgressões e na incircuncisão da vossa carne, deu-vos vida, juntamente com Ele, perdoando todos os nossos delitos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Ele cancelou todos os escritos de débito contra nós em Seus mandamentos. Ele removeu tudo isso, cravando-os na cruz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Ele desarmou os governos e as autoridades, e os expôs em público, vencendo-os na cruz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Portanto, ninguém vos julgue pelo comer ou beber, ou por causa do dia de festa ou da lua nova ou pelos sábados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Tudo isso é uma sombra das coisas futuras, mas a realidade é Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Que ninguém vos desqualifique, fingindo humildade e adoração dos anjos. Tais pessoas baseiam-se em visões, inchadas pela arrogância de sua mente carnal,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'e não se apoiam na Cabeça. É da cabeça que todo o corpo, através de suas junções e ligamentos, é mantido coeso, recebe sustento e cresce com o crescimento dado por Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Visto que morrestes juntamente com Cristo para os elementos do mundo, por que viveis como submissos às crenças deste mundo, tais como:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '\"Não pegues, não proves, não toques\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Todos esses preceitos e ensinamentos humanos estão fadados ao desaparecimento pelo uso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Essas regras têm uma aparência de sabedoria, com falsa devoção, falsa humildade e severidade para com o corpo; mas não têm qualquer valor no combate aos desejos da carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Se então Deus vos ressuscitou com Cristo, procurai as coisas que são do alto, onde Cristo está assentado à direita de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Pensai nas coisas que são do alto, não nas que são terrenas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'porque já morrestes e vossa vida está escondida com Cristo em Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Quando Cristo, que é vossa vida, for revelado, então, vós também sereis revelados com Ele em glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Portanto, mortificai os desejos pecaminosos da natureza terrena: imoralidade sexual, impureza, paixões, maus desejos e a ganância, que é idolatria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'É por causa dessas coisas que a ira de Deus vem sobre os filhos da desobediência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'E foi nestas coisas que uma vez andastes no passado, quando vivíeis nelas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Mas agora deveis vos despir de todas estas coisas: ira, raiva, más intenções, insultos e palavras obscenas dos vossos lábios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Não mintais uns aos outros, porque já vos despistes do velho homem e suas práticas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'e vos revestistes do novo homem, o qual é renovado para o pleno conhecimento, segundo a imagem Daquele que o criou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Sendo assim, não há grego nem judeu, circuncisão ou incircuncisão, nem bárbaro nem cita, nem escravo nem livre, mas Cristo é tudo e está em todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Portanto, revesti-vos pois, como eleitos de Deus, santos e amados, de profundos sentimentos de misericórdia, bondade, humildade, mansidão e paciência.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Suportai-vos uns aos outros, sede graciosos uns para com os outros. Se alguém tem algo contra outrem, perdoai da mesma forma que o Senhor vos perdoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Sobre todas estas coisas, está o amor, que é o vínculo da perfeição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Que a paz de Cristo governe os vossos corações. Foi nesta paz que vós fostes chamados em um só corpo; e sede agradecidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Que a palavra de Cristo habite em vós ricamente. Com toda sabedoria, ensinai e admoestai-vos uns aos outros com salmos, hinos e cânticos espirituais. Cantai com gratidão a Deus em vossos corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Qualquer coisa que façais em palavras ou ações, fazei tudo em nome do Senhor Jesus, dando graças a Deus Pai por meio Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Esposas, sede submissas aos vossos maridos, como convém no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Maridos, amai vossas esposas e não as trateis com amargura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Filhos, obedecei aos vossos pais em todas as coisas, porque isso é agradável ao Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Pais, não irriteis os vossos filhos, para que eles não sejam desencorajados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Escravos, obedecei aos vossos senhores em todas as coisas, não somente quando eles estão olhando para os bajular, mas com um coração sincero, que teme ao Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'O que quer que façais, fazei-o de todo coração como para o Senhor e não para homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Sabendo que recebereis do Senhor a recompensa da vossa herança. É ao Senhor Jesus a quem servis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Pois qualquer um que praticar injustiça receberá a penalidade pela injustiça que fez, e não há parcialidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Senhores, dai aos escravos o que é correto e justo, sabendo que também tendes um Senhor no céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Continuai firmes em oração, vigiando com ação de graças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Orai, ao mesmo tempo, também por nós, para que Deus nos abra a porta da Palavra, a fim de falarmos do mistério de Cristo, pelo qual estou preso;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'e orai para que eu possa falar claramente, que é como devo fazer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Andai com sabedoria diante daqueles que são de fora; usai o tempo sabiamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Sejam vossas palavras sempre agradáveis, temperadas com sal, para que saibais como deveis responder a cada um.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Tíquico vos fará conhecer todas as coisas a meu respeito. Ele é um irmão amado, um ministro fiel, e um cooperador no serviço do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Eu o enviei especificamente para que vós possais saber sobre nossa situação e, também, que ele possa consolar vossos corações,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'junto com Onésimo, irmão amado e fiel. Eles vos farão conhecer tudo o que está sendo feito aqui.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Aristarco, meu companheiro de prisão, vos cumprimenta, bem como Marcos, primo de Barnabé (de quem recebestes instruções; se ele vier a vós, recebei-o),');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'e Jesus, que é também chamado de Justo. Apenas estes da circuncisão são meus cooperadores de trabalho pelo Reino de Deus. Eles têm sido um consolo para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Epafras, servo de Cristo Jesus e vosso conterrâneo, vos cumprimenta, sempre lutando por vós em oração, para que vos torneis completos, cheios de toda vontade de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Pois sou testemunha de que ele trabalha duro por vós, pelos de Laodiceia e pelos de Hierápolis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Lucas, o médico amado, e Demas, vos cumprimentam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Cumprimentai os irmãos de Laodiceia, e Ninfa e a igreja que está em sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Quando esta carta for lida perante vós, que também seja lida na igreja dos laodicenses, e certificai de ler, também, a carta de Laodiceia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Dizei a Arquipo: \"Atenta para o ministério que tens recebido no Senhor, para que o completes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Estas saudações são de meu próprio punho, Paulo. Lembrai das minhas algemas. A graça seja convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paulo, Silvano e Timóteo à igreja de Tessalônica em Deus Pai, e no Senhor Jesus Cristo. Graça e paz a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Nós sempre agradecemos a Deus por todos vós, mencionando-vos em nossas orações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Lembramos-nos sem cessar, diante de nosso Deus e Pai, da obra da vossa fé, do trabalho do vosso amor e da perseverança da vossa esperança em nosso Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Irmãos amados por Deus, nós sabemos que Ele vos escolheu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'porque o nosso Evangelho não chegou até vós somente em palavra, mas também em poder no Espírito Santo e com toda convicção. Assim, sabeis qual tipo de homens éramos quando estávamos no meio de vós, agindo para o vosso bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Vós vos tornastes nossos imitadores e do Senhor, recebendo a Palavra com alegria do Espírito Santo, apesar de grande tribulação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Por isso vos tornastes exemplos para todos os crentes da Macedônia e Acaia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Por meio de vós, a Palavra do Senhor tem sido espalhada, não somente na Macedônia e Acaia. Mas, em cada lugar, a vossa fé em Deus tem sido divulgada. Por isso não precisamos dizer nada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Eles próprios relatam qual tipo de acolhimento nós tivemos convosco e como vos convertestes a Deus, deixando os ídolos para servir ao Deus vivo e verdadeiro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'esperando por Seu Filho, vindo dos céus, que ressurgiu da morte. Esse é Jesus, que nos livra da ira vindoura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Vós mesmos sabeis, irmãos, que a nossa visita a vós não foi em vão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Sabeis que sofremos e fomos tratados de forma vergonhosa em Filipos. Mesmo assim tivemos confiança em nosso Deus para compartilhar o Seu Evangelho convosco, mesmo em meio a grandes dificuldades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Pois nossa exortação não procede de erro, nem de impureza, nem de engano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Mas, assim como fomos aprovados por Deus para que o Evangelho nos fosse confiado, assim falamos, não para agradar a homens, mas para agradar a Deus. Ele é Aquele que examina nossos corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Portanto nunca usamos palavras para bajulação, como sabeis, nem com intenção gananciosa. Deus é testemunha disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Não buscamos glória de homens, nem de vós nem de outros. Como apóstolos de Cristo, poderíamos ter exigido privilégios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Em vez disso, fomos gentis entre vós, como uma mãe acalentando seus próprios filhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Do mesmo modo, devido ao grande afeto por vós, estávamos contentes por compartilhar convosco não só o Evangelho de Deus, mas também as nossas próprias vidas. Pois vos tornastes muito queridos para nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Irmãos, sem dúvida vos lembrais de nosso trabalho e fadiga. Trabalhamos dia e noite para que não fôssemos como um fardo para nenhum de vós. Durante aquele tempo, vos pregávamos o Evangelho de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vós sois testemunhas, assim como Deus, de como nos comportamos de forma santa, justa e irrepreensível para convosco, que credes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Do mesmo modo, sabeis que tratamos cada um de vós como um pai trata seus filhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'exortando-vos, encorajando-vos e insistindo para viverdes de maneira digna de Deus, que vos chama para o Seu reino e glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Por isso nós também agradecemos a Deus constantemente. Pois, quando recebestes de nós a Palavra que ouvistes, não a aceitastes como palavra de homem, mas como ela realmente é, a Palavra de Deus. Essa é a Palavra que também age em vós, que credes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Porque vós, irmãos, vos tornastes imitadores das igrejas de Deus que estão na Judéia, em Cristo Jesus. Pois também sofrestes as mesmas coisas de seus conterrâneos, assim como eles sofreram dos Judeus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Foram os Judeus que mataram tanto o Senhor Jesus quanto os profetas. Foram eles que nos expulsaram. Eles não agradam a Deus e são inimigos de todos os homens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'e nos proíbem de falar aos gentios para a salvação deles. Desse modo, só aumentam seus pecados. A ira veio sobre eles de forma definitiva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Nós, irmãos, separados de vós por um breve período, em presença, não em coração, estamos nos esforçando e com grande desejo de ver-vos novamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Porque queremos visitar-vos. Eu, Paulo, tentei visitar-vos mais de uma vez, mas Satanás nos impediu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Pois, quando nosso Senhor Jesus voltar, quem será nossa esperança, alegria e coroa de glória diante Dele? Por acaso não sois vós assim como os outros?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Pois vós sois nossa glória e alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Portanto, quando nós já não podíamos mais suportar, pensamos que seria bom ficarmos sozinhos em Atenas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'Nós enviamos Timóteo, nosso irmão e ministro de Deus no Evangelho de Cristo, para vos fortalecer e confortar em relação à vossa fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Nós fizemos isso com o desejo de que ninguém fosse abalado por essas tribulações. Pois vós sabeis que foi para isso que fomos destinados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Verdadeiramente, quando estávamos convosco, predissemos que haveríamos de sofrer aflição, e isso aconteceu, como vós sabeis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Por essa razão, quando eu não podia mais suportar, eu o enviei para poder saber acerca da vossa fé, pois talvez o tentador, de alguma maneira, houvesse vos tentado e nosso trabalho tivesse sido em vão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Mas Timóteo retornou a nós e trouxe boas notícias da vossa fé e amor. Conforme ele nos disse, vós sempre tendes boas lembranças de nós e desejais nos ver, assim como também nós desejamos ver a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Por causa disso, irmãos, nós fomos confortados por causa da vossa fé, em toda a nossa angústia e aflição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Pois nós agora vivemos, se vós permanecerdes firmes no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Pois quantas graças podemos dar a Deus por vós, por toda alegria que nós temos diante de Deus por vossa causa?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Noite e dia nós oramos arduamente para ver vossas faces e prover aquilo que falta à vossa fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Que o próprio Deus, nosso Pai, e nosso Senhor Jesus, direcionem nosso caminho até vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'E que o Senhor vos faça crescer e abundar no amor uns para com os outros e para com todos as pessoas, assim como nós também fazemos para convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Que Ele fortaleça os vossos corações, a fim de que sejam irrepreensíveis em santidade diante do nosso Deus e Pai, na vinda do nosso Senhor Jesus com todos os Seus santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Finalmente, irmãos, nós vos pedimos e exortamos no Senhor Jesus que, assim como recebestes nossas instruções sobre como deveis andar e satisfazer a Deus, também neste caminho andai, para que façais ainda mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Pois sabeis quais instruções vos demos através do Senhor Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Esta é a vontade de Deus: a vossa santificação, que vos afasteis da imoralidade sexual,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'que cada um de vós saiba controlar seu próprio corpo de forma santa e honrosa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'não conduzidos por paixão lasciva, como os gentios que não conhecem a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'E que ninguém desrespeite ou lese a seu irmão nessa questão. Porque o Senhor é o vingador em todas essas coisas, como vos avisamos e testificamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Porque Deus não nos chamou para a impureza, mas para a santidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Portanto, quem rejeita isso não rejeita a pessoas, mas a Deus, que vos deu o Seu Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'A respeito do amor fraternal, não necessitais que ninguém vos escreva, pois vós mesmos sois ensinados por Deus a amar uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'De fato, fazeis isto com todos os irmãos que estão em toda Macedônia. Entretanto, nós vos exortamos, irmãos, a fazer isso ainda mais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'Também vos exortamos a buscar viver pacificamente, cuidar das vossas coisas, e trabalhar com vossas mãos, como vos ordenamos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'assim, andareis corretamente diante daqueles que são de fora, e não necessitareis de coisa nenhuma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Irmãos, não queremos que ignoreis acerca daqueles que dormem, para que não vos entristeçais como os demais que não têm esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Porque, se acreditamos que Jesus morreu e ressuscitou, também Deus trará com Jesus aqueles que dormiram Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Pois isto vos falamos pela Palavra do Senhor, que nós que estamos vivos, esperando a vinda do Senhor, com certeza não precederemos aqueles que dormem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Porque o próprio Senhor descerá do céu com grande brado, com a voz do arcanjo, e com a trombeta de Deus, e os mortos em Cristo ressuscitarão primeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Depois, nós, os que estivermos vivos, os que permanecermos, seremos arrebatados juntamente com eles nas nuvens, para nos reunir com o Senhor nos ares. Desse modo, estaremos sempre com o Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Portanto, consolai uns aos outros com estas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'A respeito do tempo e das estações, irmãos, não precisais que algo vos seja escrito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Sabeis perfeitamente que o dia do Senhor virá como um ladrão de noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Quando disserem: \"Paz e segurança\", a destruição repentina lhes sobrevirá. Será como dores de parto à mulher grávida, e eles não terão como escapar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Mas vós, irmãos, não estais na escuridão de modo que aquele dia vos alcance como um ladrão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Vós sois todos filhos da luz e filhos do dia. Nós não somos filhos da noite ou da escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Logo, não durmamos como os outros fazem, mas continuemos a vigiar, e estejamos sóbrios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Porque os que dormem, dormem de noite, e aqueles que se embriagam, embriagam-se de noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Mas, como somos filhos do dia, fiquemos sóbrios. Coloquemos a couraça da fé e do amor, e a esperança da salvação futura como nosso capacete.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Porque Deus não nos destinou para a ira, mas para obtermos a salvação, por meio de nosso Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Ele que morreu por nós, para que, independentemente de estarmos acordados ou dormindo, possamos viver juntos com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Portanto, confortemos e edifiquemos uns aos outros como vós já fazeis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Nós vos pedimos, irmãos, que reconheçais aqueles que trabalham entre vós, que cuidam de vós no Senhor, e que vos admoestam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Também pedimos que os considereis em alta estima, em amor, por causa do trabalho deles. Vivei em paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Nós vos exortamos, irmãos, a advertir os indisciplinados, encorajar os desencorajados, auxiliar os fracos, e ser pacientes para com todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Cuidai para que ninguém retribua o mal com o mal, mas esforçai-vos pelo bem uns dos outros e de todos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Alegrai-vos sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Orai sem cessar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Em tudo, dai graças. Pois essa é a vontade de Deus, em Cristo Jesus, para convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Não apagueis o Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Não desprezeis as profecias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Examinai todas as coisas; retende o que é bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Afastai-vos de toda forma de mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Que o próprio Deus da paz vos santifique completamente. Que todo seu espírito, alma e corpo sejam preservados irrepreensíveis para a vinda do nosso Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Quem vos chamou é Fiel, e Ele também o fará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Irmãos, orai também por nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Cumprimentai todos os irmãos com um beijo santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Eu lhes suplico, pelo Senhor, que esta carta seja lida para todos os irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Que a graça de nosso Senhor Jesus Cristo esteja convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paulo, Silvano e Timóteo, à igreja dos tessalonicenses, em Deus, nosso Pai, e no Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Graça e a paz, da parte de Deus, nosso Pai, e do Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Devemos dar sempre graças a Deus por vós, irmãos. Pois é apropriado, porque vossa fé está crescendo muito, e o amor de cada um de vós transborda uns para com os outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Desse modo, nós mesmos nos orgulhamos de vós, dentre as igrejas de Deus, pela vossa paciência e fé, em todas as perseguições e aflições que tendes suportado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Isso é um sinal do justo julgamento de Deus. O resultado é que sereis considerados dignos do reino de Deus, pelo qual sofreis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'É justo que Deus retribua com aflição aos que vos afligem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'e vos dê alívio, a vós que fostes afligidos conosco. Ele assim o fará na revelação de nosso Senhor Jesus, vindo do céu com os anjos de Seu poder;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'em chama de fogo, Ele punirá aqueles que não conhecem a Deus, e aos que não respondem ao Evangelho de nosso Senhor Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Eles sofrerão a punição da destruição eterna, longe da presença do Senhor e da glória do Seu poder,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'naquele dia, quando Ele vier para ser glorificado no Seu povo e maravilhado por todos aqueles que creram. Pois o nosso testemunho foi crido entre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Por causa disso, também oramos continuamente por vós, para que nosso Deus vos considere dignos do vosso chamado, e cumpra todo propósito de bondade e obra de fé com poder,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'para que o nome do nosso Senhor Jesus seja glorificado em vós, e vós Nele, pela graça de nosso Deus e Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Irmãos, a respeito da vinda do Senhor Jesus Cristo e da nossa reunião com Ele, pedimos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'que não vos perturbeis ou inquieteis facilmente, quer seja por espírito, por palavra ou por alguma carta que pareça ter sido enviada por nós, como se o Dia do Senhor já tenha chegado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Ninguém vos engane de modo algum. Porque isso não acontecerá até que venha a apostasia e o homem da iniquidade seja revelado, o filho da destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'Esse é o que exalta a si mesmo e se opõe contra tudo que é chamado Deus ou que é adorado. Como resultado, ele assenta-se no templo de Deus e apresenta a si mesmo como Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Vós não lembrais de que, quando estive convosco, eu vos falei essas coisas?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Agora vós sabeis o que o detém, portanto ele será revelado apenas no tempo certo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Como o mistério da injustiça já está atuando, é necessário apenas que seja retirado do caminho aquele que o detém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Então o ímpio será revelado, a quem o Senhor Jesus destruirá com o sopro da Sua boca. O Senhor o eliminará pela manifestação da Sua vinda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'A vinda do ímpio será devido à ação de Satanás com todo poder, sinais, e falsas maravilhas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'e com todo o engano de injustiça para aqueles que estão perecendo, porque eles não receberam o amor da verdade a fim de serem salvos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Por esta razão Deus está enviando-lhes a atuação do engano para que creiam na mentira');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'e sejam todos julgados, aqueles que não acreditaram na verdade, mas tiveram prazer na injustiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Mas nós devemos sempre dar graças a Deus por vós, irmãos amados pelo Senhor, porque Deus vos escolheu como primeiros frutos para salvação na santificação do Espírito e fé na verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'Porque Ele vos chamou através do nosso Evangelho para obter a glória do nosso Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Portanto, irmãos, permanecei firmes e agarrai-vos às tradições que vos foram ensinadas, quer pela palavra quer por nossas cartas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Agora, pois, o próprio Senhor Jesus Cristo, e Deus, nosso Pai, que nos amou e nos deu eterno consolo e boa esperança para o futuro através da graça,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'confortem e estabeleçam vossos corações em toda boa ação e palavra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Portanto, irmãos, orai por nós para que a Palavra do Senhor possa se espalhar rapidamente e seja glorificada, do mesmo modo que é convosco,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'e para que sejamos livres de pessoas perversas e más, pois nem todos tem fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Mas o Senhor é fiel e vos fortalecerá e guardará do maligno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Nós temos confiança no Senhor a respeito de vós, de que fazeis e continuareis a fazer o que vos ordenamos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Que o Senhor possa conduzir os vossos corações ao amor de Deus e para a perseverança de Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Portanto irmãos, vos ordenamos em nome do nosso Senhor Jesus Cristo, que eviteis aqueles irmãos que vivem ociosos e não de acordo com as tradições que recebestes de nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Pois vós mesmos sabeis que deveis nos imitar. Nós não nos comportamos de maneira indisciplinada entre vós,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'e não comemos a comida de ninguém sem pagar. Pelo contrário, em esforço e dificuldade trabalhamos noite e dia, para que não nos tornássemos pesados para nenhum de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Não é porque não temos autoridade, mas porque devemos servir de exemplo para vós, para que, assim, vós possais nos imitar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Quando estávamos convosco, vos ordenamos isto: \"Se alguém não quer trabalhar, este não deve comer\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Pois ouvimos que alguns andam desocupados entre vós; eles não trabalham, mas, ao contrário, são intrometidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Portanto lhes ordenamos e exortamos em nosso Senhor Jesus Cristo que, com sossego, possam trabalhar e comer sua própria comida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Porém vós, irmãos, não desanimeis de fazer o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Se alguém não obedece nossa palavra nesta carta, marque-o e não vos associeis a ele, a fim de que, dessa maneira, ele possa ser envergonhado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Não o considereis como inimigo, mas exortai-o como irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Que o próprio Senhor da paz vos dê a paz em todo tempo e de todas as formas. Que o Senhor seja com todos vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Essa é minha saudação, Paulo e escrevo com minha própria mão, o qual é o sinal em todas as minhas cartas. É assim que escrevo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Que a graça de nosso Senhor Jesus Cristo seja com todos vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paulo, apóstolo de Cristo Jesus de acordo com a ordem de Deus, nosso Salvador, e de Cristo Jesus, nossa esperança,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'a Timóteo, um verdadeiro filho na fé: graça, misericórdia e paz de Deus Pai e de Cristo Jesus, nosso Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Como eu te roguei, quando partia para Macedônia, permanece em Éfeso para que tu possas advertir certas pessoas de que não ensinem uma doutrina diferente,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'nem prestem atenção a histórias e genealogias sem fim, que causam discussões em vez de ajudarem o plano de Deus, que é pela fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Mas o objetivo dessa advertência é o amor que procede de um coração puro, de uma boa consciência e de uma fé sincera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Algumas pessoas têm se enganado e se desviado disso com conversas tolas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'querendo ser mestres da lei, mas sem entender o que dizem, nem o que insistentemente afirmam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Mas nós sabemos que a lei é boa se usada de forma legítima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'E sabemos isto: a lei não é feita para o justo, mas para os rebeldes e sem lei, para os incrédulos e pecadores, para os que são ímpios e profanos, para os que matam os próprios pais e mães, para os assassinos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'para as pessoas sexualmente imorais, para os homossexuais, para os traficantes de escravos, para os mentirosos, para as falsas testemunhas e para tudo o que é contra a sã doutrina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Essa doutrina está de acordo com o Evangelho glorioso do Deus bendito, que me foi confiado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Eu agradeço a Cristo Jesus, nosso Senhor, que me fortaleceu, pois me considerou fiel e me colocou nesta obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Eu era um homem blasfemo, perseguidor e violento, mas recebi misericórdia, porque agia ignorantemente na minha incredulidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Mas a graça do nosso Senhor transbordou com a fé e o amor que há em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Esta mensagem é confiável e digna de toda aceitação: Cristo Jesus veio ao mundo para salvar os pecadores, e eu sou o pior deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Mas, por essa razão, eu recebi misericórdia, de forma que em mim, o pior dos pecadores, Cristo Jesus pudesse demonstrar toda paciência. Ele fez isso como um exemplo para aqueles que haveriam de crer Nele para a vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Assim, ao Rei eterno, imortal e invisível, o único Deus, sejam a honra e a glória para sempre e sempre. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Eu te entrego essa instrução, Timóteo, meu filho, em concordância com as profecias feitas a teu respeito, para que te empenhes no bom combate.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Faze isso para que tu tenhas fé e uma boa consciência. Algumas pessoas as têm rejeitado e naufragaram na fé,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'entre elas estão Himeneu e Alexandre, os quais entreguei a Satanás para que eles aprendam a não blasfemar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Portanto antes de tudo, exorto que sejam feitos pedidos, orações, intercessões e ações de graças em favor de todas as pessoas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'pelos reis e por todos os que exercem autoridade, para que possamos viver uma vida tranquila e serena, em toda piedade e dignidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Isso é bom e aceitável perante Deus nosso Salvador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Ele deseja que todas as pessoas sejam salvas e cheguem ao pleno conhecimento da verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Pois há um só Deus, e há um só mediador entre Deus e o homem, Jesus Cristo homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'O qual Se entregou em resgate por todos, para servir de testemunho no tempo oportuno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Digo a verdade, não minto, para esse propósito, fui constituído mensageiro e apóstolo, mestre dos gentios na fé e na verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Desejo, portanto, que os homens orem em todo lugar, levantando mãos santas sem ira ou contenda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Do mesmo modo, quero que as mulheres se vistam com roupas decentes, com modéstia e com discrição. Elas não devem usar cabelos com tranças, nem com ouro ou pérolas, ou vestidos custosos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Mas, ao contrário, que se vistam de boas obras, com aquilo que é apropriado às mulheres que professam piedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'A mulher deve aprender em silêncio e com toda a submissão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Pois não permito que a mulher ensine, nem que exerça autoridade sobre o homem, mas que esteja em silêncio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Porque Adão foi criado primeiro e Eva depois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'E Adão não foi enganado, mas a mulher que foi completamente enganada e caiu em transgressão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'No entanto ela será salva ao gerar filhos, desde que permaneça na fé, no amor e na santificação com sabedoria no seu pensar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Esta afirmação é digna de confiança: se alguém deseja ser um bispo, deseja um bom trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Portanto o bispo deve ser irrepreensível, marido de uma só mulher, moderado, sensível, respeitável, hospitaleiro, apto para ensinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Não deve ser dado ao vinho, nem briguento, ao invés disso, gentil e pacífico. Não deve ser apegado ao dinheiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Deve governar bem o seu próprio lar, e seus filhos devem obedecê-lhe com todo o respeito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'Pois se um homem não sabe como governar bem o seu próprio lar, como cuidará da igreja de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Ele não deve ser um novo convertido, para que não se torne orgulhoso e caia em condenação como o diabo caiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Também deve ter uma boa reputação com os de fora, a fim de não cair em desgraça e na armadilha do diabo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Os diáconos, igualmente, devem ser respeitáveis, de uma só palavra. Não devem beber muito vinho, nem serem avarentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Devem manter o mistério da fé com uma consciência limpa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Eles também devem ser aprovados primeiro e, só então, devem servir porque são irrepreensíveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'As mulheres, do mesmo modo, devem ser respeitáveis. Não devem ser caluniadoras, mas moderadas e fiéis em todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Os diáconos devem ser maridos de uma só mulher e governar bem os seus filhos e a sua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Pois aqueles que servem bem, alcançam para si mesmos uma boa reputação e uma grande confiança na fé que está em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Escrevo-te essas coisas esperando ir visitar-te em breve,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'mas, se me atrasar, saberás como proceder na casa de Deus, que é a igreja do Deus vivo, coluna e suporte da verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Não se pode negar que é grande o mistério da piedade: \"Ele foi manifestado na carne, justificado pelo Espírito, visto por anjos, proclamado entre as nações, crido no mundo e exaltado na glória\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'O Espírito fala claramente que nos últimos tempos algumas pessoas abandonarão a fé e darão atenção aos espíritos enganadores e aos ensinamentos de demônios,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'por causa da mentira e da hipocrisia dos que tem a própria consciência cauterizada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Eles proíbem o casamento e ordenam a abstinência de alimentos que Deus criou para partilhar com ação de graças entre os fiéis e os que conhecem a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Pois todas as coisas criadas por Deus são boas. Nada que recebemos com ações de graças deve ser rejeitado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'porque é consagrado pela palavra de Deus e pela oração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Se colocares essas coisas perante os irmãos, serás um bom servo de Jesus Cristo, porque és alimentado pelas palavras da fé e pelo bom ensino que tens seguido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Mas rejeita os mitos tolos e profanos, típicos de velhas caducas. Em vez disso, exercita-te na piedade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'pois o exercício físico tem pouca utilidade, mas a piedade é útil para todas as coisas e contém a promessa para a vida presente e futura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Essa mensagem é confiável e digna de toda aceitação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Pois é por isso que nos esforçamos e trabalhamos muito, porque temos confiança no Deus vivo, que é o Salvador de todas as pessoas, mas especialmente dos que creem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Proclama e ensina essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Não deixes ninguém desprezar a tua juventude, em vez disso, sê um exemplo aos que creem, na fala, no amor, na fidelidade e na pureza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Até eu voltar, atenta para a leitura, para a exortação e para o ensino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Não negligencies o dom que há em ti, que te foi dado através de profecia, com a imposição de mãos dos anciãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Cuida dessas coisas, permanece nelas, para que o teu progresso seja evidente a todas as pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Cuida de ti mesmo e do ensino. Continua nessas coisas porque fazendo isso salvarás a ti mesmo e a quem te ouve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Não repreendas um homem idoso, mas exorta-o como se ele fosse um pai. Exorta os homens mais novos como se fossem irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Exorta as mulheres idosas como a mães, e as mais jovens como a irmãs, com toda pureza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Honra as viúvas, verdadeiramente viúvas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'mas, se uma viúva tiver filhos ou netos, deixa que eles primeiramente aprendam a mostrar honra nos seus próprios lares. Deixa que retribuam aos seus pais, pois isto é agradável a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'No entanto, uma verdadeira viúva é a que está totalmente sozinha. Ela põe sua confiança em Deus e persevera nos pedidos e nas orações noite e dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'No entanto, a mulher que vive para os prazeres está morta, mesmo que ainda esteja viva.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Prega essas coisas para que possam ser irrepreensíveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Mas, se alguém não cuida dos seus próprios parentes, especialmente os do seu próprio lar, tem negado a fé e é pior do que um descrente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Que uma viúva seja relacionada como viúva quando tiver pelo menos sessenta anos de idade, e tenha sido esposa de um só marido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Ela deve ser conhecida por boas obras, seja pelo fato de ter cuidado dos filhos, ter sido hospitaleira para com estranhos, ter lavado os pés dos santos, ter aliviado os aflitos, ou ter-se dedicado a toda boa obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Mas, quanto às viúvas mais jovens, recuse relacioná-las na lista; pois, quando se entregam aos desejos sensuais contra Cristo, querem casar-se.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Dessa maneira, tornam-se culpáveis por anularem o seu compromisso anterior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Elas também se acostumaram a ficar ociosas, andando de casa em casa. Não apenas ficam ociosas, mas também tornam-se fofoqueiras e intrometidas, falando coisas que não devem ser faladas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Portanto, quero que as mais jovens se casem para gerar filhos e administrar a casa; assim não darão ao adversário oportunidade para acusá-las de fazerem o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Pois algumas já se desviaram, seguindo a Satanás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Se alguma mulher crente tiver viúvas em sua família, que ela as ajude, para que a igreja não seja sobrecarregada e possa auxiliar as verdadeiras viúvas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Os presbíteros que lideram bem devem ser considerados dignos de dupla honra, especialmente aqueles que trabalham com a palavra e com o ensino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Pois a Escritura diz: \"Tu não deves amordaçar o boi enquanto ele esmaga os grãos\", e \"O trabalhador é digno do seu salário\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Não recebas acusação contra um presbítero, a menos que haja duas ou três testemunhas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Corrige os pecadores à vista de todos para que os demais sejam tementes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Rogo-te solenemente diante de Deus, em Cristo Jesus, e de Seus anjos escolhidos, que tu guardes essas instruções sem discriminação, e que não faças nada com favoritismo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Não imponhas as mãos precipitadamente sobre alguém, nem compartilhe dos pecados de outra pessoa, conserva-te puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Tu não deves tomar apenas água, em vez disso, acrescenta um pouco de vinho para o teu estômago e as tuas frequentes doenças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Os pecados de algumas pessoas são abertamente conhecidos e conduzem-nas ao julgamento, mas alguns pecados manifestam-se depois.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Da mesma forma, as boas obras são abertamente conhecidas, enquanto que as outras não podem ser escondidas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Todos os que estão debaixo do jugo da escravidão devem considerar seus próprios senhores dignos de toda honra, para que o nome de Deus e os ensinos não sejam blasfemados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Os escravos que têm senhores cristãos não devem desrespeitá-los, por serem irmãos. Pelo contrário, devem servi-los ainda mais, visto que os senhores que recebem o seu serviço são crentes e amados. Ensina e declara essas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Se alguém ensina algo diferente e não aceita nossa fiel instrução, ou seja, as palavras do nosso Senhor Jesus Cristo, e não aceita o ensino que conduz à piedade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'tal pessoa é orgulhosa e não sabe de nada. Em vez disso, está enferma com controvérsias e discussões acerca de palavras. Essas palavras resultam em inveja, brigas, insultos, suspeitas malignas e');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'em constante conflito entre pessoas com mentes corrompidas, que se desviam da verdade e pensam que a piedade é um meio de se tornarem ricos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Mas grande lucro é a piedade com contentamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Porque não trouxemos nada para este mundo, nem somos capazes de levar coisa alguma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Em vez disso, estejamos satisfeitos com o alimento e com as vestes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Agora, os que querem se tornar ricos caem em tentação, em uma cilada. Caem em muitas paixões insensatas e nocivas, e em qualquer coisa que faz as pessoas afundarem em ruína e em destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Porque o amor ao dinheiro é a raiz de todos os tipos de males. Algumas pessoas que desejam isso têm se desviado da fé e se atormentado com muito sofrimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Mas tu, homem de Deus, foge dessas coisas. Persegue a justiça, a piedade, a fidelidade, o amor, a paciência e a mansidão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Combate o bom combate da fé. Toma posse da vida eterna para a qual foste chamado e da qual testificaste perante muitas testemunhas, conforme o que é bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Perante Deus, que dá vida a todas as coisas, e perante Cristo Jesus, que falou a verdade a Pôncio Pilatos, exorto-te');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'que guardes o mandamento de forma perfeita e irrepreensível, até a vinda do nosso Senhor Jesus Cristo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'a qual, no tempo certo, revelará o Bendito, o único Poderoso, o Rei que reina e o Senhor que governa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Somente Ele é imortal e habita na luz inacessível. Nenhum homem O vê ou é capaz de vê-Lo. A Ele seja a honra e o eterno poder. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Fala aos ricos deste mundo para não serem orgulhosos e não terem esperança nas riquezas, pois são incertas. Em vez disso, devem esperar em Deus, que nos oferece todas as verdadeiras riquezas para desfrutarmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Fala a eles para fazerem o bem, serem ricos em boas obras, generosos e dispostos a compartilhar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Desse modo, eles guardarão para si mesmos tesouros, que são o bom fundamento para o que está por vir, de forma que tomem posse da verdadeira vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'Timóteo, protege o que te foi dado. Evita as conversas tolas e as discussões contraditórias que são chamadas falsamente de conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Alguns proclamam essas coisas e por isso se desviam da fé. Que a graça seja convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paulo, apóstolo de Cristo Jesus pela vontade de Deus, de acordo com a promessa da vida que está em Cristo Jesus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'para Timóteo, filho amado: graça, misericórdia e paz de Deus o Pai e Cristo Jesus, nosso Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Eu agradeço a Deus, a quem eu sirvo desde meus antepassados com consciência limpa, porque lembro-me constantemente de ti nas minhas orações, noite e dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Recordando-me de tuas lágrimas desejo muito ver-te, para encher-me de alegria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Lembro-me de tua fé genuína, que habitou primeiro na tua avó Loide e em tua mãe Eunice. E eu estou convencido de que essa fé também habita em ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Por essa razão, exorto-te que reacendas o dom de Deus, que está em ti pela imposição das minhas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Pois Deus não nos deu espírito de medo, mas de poder, de amor e de disciplina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Então não te envergonhes do testemunho do nosso Senhor, nem de mim, Paulo, seu prisioneiro. Em vez disso, compartilha comigo o sofrimento pelo evangelho, de acordo com o poder de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Ele nos salvou e nos convocou com um chamado santo, não de acordo com nossas obras, mas de acordo com Seu próprio plano e graça, que Ele nos deu em Cristo Jesus, antes dos tempos terem começado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Mas agora a salvação de Deus foi revelada através do aparecimento do nosso Salvador Cristo Jesus, que destruiu a morte e trouxe à luz a vida sem fim, por meio do evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Por causa disso, eu fui constituído pregador, apóstolo, e mestre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Por essa razão eu também sofro essas coisas. Mas eu não estou envergonhado; pois eu conheço Aquele em quem eu tenho crido, e eu estou certo de que é poderoso para guardar o que eu confiei a Ele até aquele dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Mantenha o padrão de palavras saudáveis que de mim escutaste, com a fé e o amor que estão em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'O bom depósito que Deus confiou a ti, guarda pelo Espírito Santo, que vive em nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Tu sabes que todos os que vivem na Ásia me abandonaram; nesse grupo estão Fígelo e Hermógenes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Que o senhor conceda misericórdia para a família de Onesíforo, pois muitas vezes ele me animou, e não teve vergonha da minha prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Em vez disso, quando eu estava em Roma, ele me procurou de modo diligente, e me achou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'O Senhor permita que ele ache misericórdia da parte Dele naquele dia. E tu sabes muito bem de quantas formas ele me ajudou em Éfeso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Tu, portanto, filho meu, sê fortalecido na graça que há em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'E o que ouviste de mim, diante de muitas testemunhas, confia-o a pessoas fiéis e também capazes para ensinar a outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Sofre comigo, como um bom soldado de Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Nenhum soldado, enquanto serve se compromete com afazeres dessa vida, pois deseja agradar o seu superior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Da mesma maneira, se alguém compete como um atleta, ele não é coroado se não competir segundo as regras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'É necessário que o agricultor que trabalha arduamente seja o primeiro a receber sua porção da colheita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Compreende o que estou dizendo, pois o Senhor te dará entendimento em todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Lembra-te de Jesus Cristo, da descendência de Davi, ressurreto dentre os mortos, segundo a minha mensagem do Evangelho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'pela qual eu sofro ao ponto de ser algemado como um criminoso. Mas a palavra de Deus não está algemada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Portanto eu suporto todas as coisas por aqueles que são eleitos, para que eles também obtenham a salvação que está em Cristo Jesus, com glória eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Confiável é esta palavra: \"Se morremos com Ele, também viveremos com Ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Se perseveramos, também reinaremos com Ele. Se O negarmos, Ele também nos negará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Se somos infiéis, Ele permanece fiel, pois não pode negar a Si mesmo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Relembra-lhes continuamente dessas coisas. Adverte-os diante de Deus que não discutam sobre palavras, porque nisso nada há de proveitoso e sim destruição para os que ouvem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Procura apresentar-te a Deus aprovado como obreiro que não tem de que se envergonhar, que maneja bem a Palavra da Verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Evita conversas profanas, as quais levam cada vez mais para a impiedade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'As palavras dos que assim agem se alastram como câncer. Entre eles estão Himeneu e Fileto,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'homens que se desviaram da verdade. Eles dizem que a ressurreição já aconteceu e perturbam a fé de alguns.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Todavia, o firme fundamento de Deus permanece tendo este selo: \"O Senhor conhece os que são Seus\", e, \"Todo aquele que pronuncia o nome do Senhor deve apartar-se da injustiça\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'Em um lar rico não há somente vasos de ouro e de prata, mas também de madeira e de barro; alguns para uso honroso, outros para uso desonroso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Assim, pois, se alguém a si mesmo se purificar destes erros será vaso para honra, consagrado, útil ao Mestre, e preparado para toda boa obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Fuja das paixões da mocidade. Segue a justiça, a fé, o amor e a paz com os que invocam o Senhor de coração puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Mas rejeita as questões tolas e ignorantes. Sabes que delas geram contendas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'O servo do Senhor não deve contender. Em vez disso ele deve ser gentil para com todos, apto para ensinar, e paciente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Ele deve corrigir com mansidão aqueles que se opõem a ele. Talvez Deus lhes dê arrependimento para o conhecimento da verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'Eles podem se tornar sóbrios novamente e escapar das armadilhas do diabo, tendo sido capturados por ele para a sua vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Mas saibas isto: nos últimos dias haverá tempos difíceis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Pois os homens serão egoístas, avarentos, orgulhosos, soberbos, blasfemadores, desobedientes aos pais, ingratos, profanos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'sem afeto natural, implacáveis, caluniadores, sem domínio próprio, violentos, inimigos do bem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'traidores, teimosos, arrogantes, mais amigos dos prazeres do que amigos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Tendo aparência de piedade, mas negando o seu poder. Afasta-te desses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Pois alguns deles são homens que entram em lares e capturam mulheres tolas, que estão cheias de pecado e que são guiadas por vários desejos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Essas mulheres estão sempre aprendendo, mas nunca são capazes de chegar ao conhecimento da verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Do mesmo modo que Janes e Jambres resistiram a Moisés, assim também esses falsos mestres resistem à verdade; são homens de mente corrompida, reprovados quanto à fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Mas eles não irão muito longe, pois a tolice deles será óbvia para todos, igual à tolice desses dois homens.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Mas tu tens seguido os meus ensinamentos, conduta, propósito, fé, longanimidade, amor, paciência,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'perseguições, sofrimentos, e o que aconteceu comigo em Antioquia, Icônio e Listra. Suportei perseguições, e o Senhor me resgatou, tirando-me de todas elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Aliás, todos os que querem viver de maneira piedosa em Cristo Jesus serão perseguidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Mas impostores e pessoas más se tornarão ainda piores, enganando e sendo enganados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Tu, porém, permanece naquilo que aprendeste e aceitaste com fé; pois sabes de quem o aprendeste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'Desde a infância conheces as Sagradas Escrituras, que são capazes de fazer-te sábio para salvação pela fé que está em Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Toda a Escritura é inspirada por Deus e proveitosa para ensino, para repreensão, para correção, e para instruir na justiça;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'de modo que o homem de Deus possa ser competente e capacitado para toda boa obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Diante de Deus e de Jesus Cristo, que julgará os vivos e os mortos, e por causa de Sua manifestação e de Seu reino, eu te dou esta ordem solene:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Prega a Palavra, insiste, quando isso for conveniente e quando não for. Reprova, repreende, exorta com toda paciência e ensino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Pois o tempo chegará em que as pessoas não suportarão a sã doutrina. Em vez disso, elas ajuntarão para si mestres conforme suas próprias cobiças. Isso será tão agradável aos seus ouvidos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'que se afastarão da verdade e se voltarão para os mitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Tu, porém, sê sóbrio em todas as coisas, sofre as aflições, faz o trabalho de um evangelista, cumpre o teu ministério.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Pois eu já estou sendo derramado como uma oferta. O tempo da minha partida chegou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Combati o bom combate, terminei a corrida, guardei a fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'A coroa de justiça me foi reservada, aquela que o Senhor, o justo Juiz, me dará naquele dia; e não só para mim, mas também para todos aqueles que amam a Sua vinda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Faz o teu melhor para vires a mim rapidamente,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'pois Demas me abandonou. Tendo ele amado este presente mundo, partiu para Tessalônica. Crescente foi para Galácia, e Tito foi para Dalmácia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Somente Lucas está comigo. Busca Marcos e traze-o contigo, pois ele me é útil na obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Enviei Tíquico para Éfeso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Quando vieres, traz a capa que deixei em Trôade com Carpo, e também os livros, especialmente os pergaminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexandre, aquele que trabalha com metais, fez muitos males contra mim. O Senhor irá retribuí-lo de acordo com suas ações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Tu também deves proteger-te dele, porque ele resistiu fortemente às nossas palavras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'Na minha primeira defesa, ninguém permaneceu comigo, mas todos me abandonaram. Que isso não seja considerado contra eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Mas o Senhor permaneceu do meu lado e me fortaleceu, para que a proclamação fosse totalmente cumprida por mim, e para que todos os gentios pudessem ouvi-la. E eu fui resgatado da boca do leão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'O Senhor me libertará de toda ação maligna e me salvará para o Seu reino celestial. A Ele seja a glória para todo o sempre. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Cumprimenta Prisca, Áquila e a casa de Onesíforo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erasto ficou em Corinto, mas eu deixei Trófimo doente em Mileto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Faz o teu melhor para vir antes do inverno. Êubulo te saúda, também o fazem Pudente, Lino, Cláudia, e todos os irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Que o Senhor esteja com o teu espírito. A graça esteja convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paulo, servo de Deus e apóstolo de Jesus Cristo, segundo a fé dos eleitos de Deus e o conhecimento da verdade segundo a piedade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'na confiança da vida eterna que o Deus, que não mente, prometeu antes dos tempos eternos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'E, em tempos devidos, Ele revelou a Sua Palavra, por meio da proclamação da mensagem, da qual fui incumbido, conforme a ordem de Deus, nosso Salvador,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'a Tito, um verdadeiro filho segundo nossa fé em comum. Graça e paz de Deus Pai, e Cristo Jesus nosso Salvador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Deixei-te com um propósito em Creta, para que pusesses em ordem as coisas pendentes, e constituísses presbíteros em cada cidade, assim como te ordenei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'O presbítero precisa ser irrepreensível, marido de uma só mulher, com filhos crentes, que não sejam acusados de ser perversos nem insubordinados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'É necessário que o bispo, como administrador de Deus, seja irrepreensível. Ele não deve ser arrogante, nem se irar facilmente, nem beber muito vinho, nem ser violento, e nem ser ganancioso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Em vez disso, ele deve ser disposto a hospedar pessoas, ser bondoso, ser prudente, justo e santo, e que tenha domínio próprio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Ele deve ser apegado ao ensino da Palavra, para que seja apto para encorajar fielmente na doutrina autêntica e também para refutar aqueles que a contradizem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Pois existem muitos insubordinados, especialmente os da circuncisão, que enganam e guiam as pessoas na direção errada, cujas palavras são inúteis;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Os quais é necessário silenciar. Eles ensinam aquilo que não deveriam ensinar, para obter benefício desonroso, destruindo famílias inteiras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Disse um profeta dentre eles: \"Cretenses são sempre mentirosos, animais ruins e perigosos, ventres preguiçosos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Esta afirmação é verdadeira, por isso corrija-os severamente para que eles possam ser sadios na fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Não dê atenção aos mitos judaicos, nem aos mandamentos de homens que se afastam da verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Para aqueles que são puros, tudo é puro, mas para aqueles que são impuros e descrentes, nada é puro, porque até a mente e a consciência deles estão contaminadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Eles professam conhecer a Deus, mas O negam com suas ações. Eles são detestáveis e desobedientes e provam ser desqualificados para qualquer boa obra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Tu, porém, fala o que está de acordo com a sã doutrina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Os homens mais velhos devem ser moderados, respeitáveis, sensatos, sadios na fé, no amor e na perseverança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'As mulheres mais velhas, da mesma forma, devem viver de maneira reverente, não serem caluniadoras, nem escravas do vinho. Que elas ensinem o que é bom,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'a fim de encorajar as mulheres mais jovens a serem equilibradas em seu pensar, a amarem os seus próprios maridos e seus filhos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'a serem sensatas, puras, boas donas de casa e sujeitas ao marido, a fim de que a palavra de Deus não seja blasfemada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Do mesmo modo, exorta os mais jovens a serem sensatos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'Em todas as coisas, apresenta-te como modelo de boas obras; ao ensinar, mostra pureza e dignidade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'use palavras sadias e irrepreensíveis, para que seja envergonhado todo aquele que tentar se opor a ti, não tendo nada de mal a dizer sobre nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Os escravos sejam em tudo obedientes aos seus senhores, satisfazendo-lhes em tudo, e não sejam respondões;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'não roubem, mas mostrem que são bons e fiéis, a fim de honrarem, em tudo, a doutrina de Deus, nosso Salvador.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Pois a graça de Deus manifestou-se para a salvação de todos os homens,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'e nos ensina a abandonarmos a impiedade e as paixões mundanas, a vivermos de maneira justa e piedosa no presente século,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'aguardando a bendita esperança e o aparecimento da glória do nosso grande Deus e Salvador, Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'O qual Se deu a Si mesmo por nós, a fim de pagar o preço para nos libertar da iniquidade e nos tornar puros para Si mesmo, um povo exclusivamente Seu, zeloso de boas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Ensina essas coisas, exorta e repreende com toda a autoridade. E que ninguém te despreze.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Lembra a eles que se submetam aos governantes e autoridades e os obedecem, para estarem prontos para toda boa obra;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'não injurieis a ninguém, evitai discutir, mostrai benevolência e humildade para com todas as pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Pois nós também, outrora, éramos sem juízo e desobedientes; éramos desgarrados e escravizados por várias paixões e prazeres; nós vivíamos na maldade e na inveja. Éramos detestáveis e rancorosos uns para com os outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Mas quando a bondade de Deus, nosso Salvador, e Seu amor para com a humanidade apareceu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Ele nos salvou, lavando-nos mediante o novo nascimento, e renovando-nos pelo Espírito Santo, não pelas obras que havíamos feito em justiça, mas de acordo com a Sua misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Deus ricamente derramou o Espírito Santo sobre nós, mediante o nosso Salvador Jesus Cristo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'de modo que, justificados pela Sua graça, nos tornemos herdeiros da esperança da vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Fiel é a Palavra. Quero que fales confiantemente sobre essas coisas, de modo que aqueles que confiam em Deus possam pensar seriamente em praticar boas obras. Essas coisas são boas e proveitosas para todas as pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Mas, evita debates tolos, genealogias, contendas e debates sobre a lei. Essas coisas são sem valor e sem proveito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Rejeita qualquer um que esteja causando divisões entre vós, depois de uma ou duas advertências,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'e sabe que tal pessoa desviou-se do caminho certo e está pecando e condenando a si mesma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Quando eu te enviar Artemas ou Tíquico, apressa-te, e vem até mim em Nicópolis, onde decidi passar o inverno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Apressa-te e envia Zenas, o jurista, e Apolo, com todas as coisas que eles precisam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Nosso povo deve aprender a se comprometer com as boas obras para atender às necessidades urgentes, de modo que não sejam infrutíferos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Todos aqueles que estão comigo te saúdam. Saúda tu aqueles que nos amam na fé. Graça seja com todos vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paulo, prisioneiro de Cristo Jesus, e o irmão Timóteo, para Filemom, nosso amado amigo e cooperador de trabalho,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'e à nossa irmã Áfia, a Arquipo, nosso soldado companheiro, e à igreja que se reúne em tua casa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Graça e paz de Deus, nosso Pai, e do Senhor Jesus Cristo, a todos vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Sempre agradeço ao meu Deus, lembrando-me de ti em minhas orações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Tenho ouvido do amor e da fé que tens no Senhor Jesus e todos os santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Eu oro para que o compartilhar da tua fé seja efetivo para o conhecimento de todo bem que há em nós para com Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Por causa do teu amor, irmão, tenho tido muita alegria e consolo, porque o coração dos santos, por teu intermédio, tem sido reanimado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Por isso, embora eu tenha toda a liberdade em Cristo para ordenar o que deves fazer,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'em nome do amor prefiro solicitar; eu, Paulo, um homem velho e, agora, prisioneiro por causa de Cristo Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Eu peço a ti em favor de meu filho Onésimo, a quem gerei enquanto estava na cadeia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Pois ele, antes, foi inútil para ti; mas, agora, é útil, tanto para ti quanto para mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Eu o envio de volta a ti, ele que é meu próprio coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Eu preferiria mantê-lo comigo, para que ele pudesse ajudar-me, em teu lugar, enquanto sou prisioneiro por causa do Evangelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Entretanto, não quis fazer nada sem o teu consentimento, para que a tua bondade não fosse por obrigação, mas de livre vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Talvez por isso ele tenha sido separado de ti por um momento, para que o tivesses de volta definitivamente,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'não como um escravo; mas, melhor que um escravo, um amado irmão, especialmente de mim e, mais ainda, de ti, tanto na carne quanto no Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Então, se tu me consideras companheiro, recebe-o como a mim mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Se ele te prejudicou ou deve algo a ti, coloca isso em minha conta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Eu, Paulo, escrevo isto com minha própria mão: eu te pagarei, sem mencionar que me deves até a ti mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Sim, irmão, que eu receba de ti esse favor, pelo Senhor. Reconforta o meu coração em Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Confiado em tua obediência, estou escrevendo a ti, sabendo que farás ainda mais do que estou pedindo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Ao mesmo tempo, prepara um quarto de hóspedes para mim, pois espero que, por meio de vossas orações, eu vos seja restituído.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Saúda-te Epafras, meu companheiro de prisão em Cristo Jesus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'e também Marcos, Aristarco, Demas e Lucas, meus cooperadores de trabalho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'A graça de nosso Senhor Jesus Cristo seja com o vosso espírito. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Há muito tempo, Deus falou aos nossos antepassados por meio de profetas, por muitas vezes e de várias formas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Mas, nestes últimos dias, Ele nos falou por meio do Filho, a quem constituiu como herdeiro de todas as coisas e por intermédio de quem também criou o universo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Ele é o resplendor da glória de Deus, a verdadeira expressão de Sua essência. Ele tudo sustenta pela palavra do Seu poder. Depois de ter realizado a purificação dos pecados, Ele sentou-se no Céu à direita da Majestade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'tornou-se tão superior aos anjos que herdou um nome mais excelente do que o deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'De fato, para qual dos anjos disse Deus: \"Tu és meu filho; Eu hoje te gerei\"? E, ainda: \"Eu lhe serei Pai, e Ele me será Filho\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Porém, quando Deus enviou ao mundo Seu Primogênito, Ele diz: \"Todos os anjos de Deus devem adorá-Lo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Ainda em relação aos anjos, Deus declara: \"É Ele quem faz de Seus anjos ventos e de Seus ministros chamas de fogo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Mas, em relação ao Filho, diz: \"Teu trono, Deus, permanece para todo o sempre; e o cetro de Teu Reino é o cetro de justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Amaste a justiça e odiaste a injustiça; portanto, Deus, o Teu Deus, Te ungiu com o óleo de alegria, mais que a Teus companheiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'No princípio, ó Senhor, Tu estabeleceste a fundação da terra; os céus são obras de Tuas mãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Eles perecerão, mas Tu permaneces. Eles se gastarão como roupas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Tu os enrolarás como um manto e como roupas os mudarás. Mas Tu és o mesmo, e Teus anos não terão fim\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Mas para quais dos anjos Deus, porventura, em algum momento, disse: \"Senta-te à minha direita, até que eu faça de teus inimigos um estrado para os teus pés\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Não são todos os anjos espíritos ministradores enviados para cuidar daqueles que herdarão a salvação?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Portanto, devemos prestar mais atenção ao que nós temos ouvido, para que de maneira alguma nos apartemos disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Pois, se a palavra falada pelos anjos se tornou firme, e toda transgressão e desobediência recebeu justa punição,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'como escaparemos se negligenciarmos tão grande salvação? Salvação esta que tendo sido anunciada inicialmente pelo Senhor, foi depois confirmada a nós pelos que a ouviram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Testemunhando Deus juntamente com eles, por meio de sinais, maravilhas e vários milagres e ainda por dons do Espírito Santo, distribuídos de acordo com a Sua vontade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Pois não foi a anjos que Deus sujeitou o mundo vindouro, do qual estamos falando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Mas, em certo lugar, alguém testemunhou, dizendo: \"O que é o homem, para que dele Te lembres? Ou o filho do homem, para que o visites?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Tu o fizeste um pouco menor que os anjos, de glória e de honra o coroaste.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Todas as coisas sujeitaste debaixo dos seus pés\". Pois ao sujeitar todas as coisas a ele, nada deixou que não lhe fosse sujeito. Porém, agora, ainda não vemos todas as coisas sujeitas a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Contudo, temos visto Aquele que se fez um pouco menor que os anjos, Jesus, por causa do sofrimento da morte, foi coroado de glória e de honra, para que, pela graça de Deus, provasse a morte por todo homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Porque convinha a Deus, para quem e por meio de quem todas as coisas existem, conduzindo muitos filhos à glória, aperfeiçoasse o Autor da salvação deles, por meio de sofrimentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Pois, tanto o que santifica quanto os que são santificados, todos vêm de uma só fonte, Deus. Por essa razão, Aquele que os santifica não Se envergonha de lhes chamar irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Ele diz: \"Proclamarei o Teu nome para os meus irmãos; cantarei a Teu respeito no meio da congregação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'E de novo Ele diz: \"Nele confiarei\". E novamente: \"Veja, aqui estou Eu e os filhos que Deus Me deu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Portanto, visto que os filhos de Deus compartilham carne e sangue, Jesus também compartilhou a mesma coisa, ou seja, por meio da morte Ele destruiu aquele que tem o poder da morte, isto é, o diabo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'E, assim, Ele libertou todos aqueles que, por medo da morte, estavam sujeitos à escravidão por toda a vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Pois, certamente, não está preocupado em socorrer aos anjos, mas Ele socorre a descendência de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Portanto, foi necessário que Ele fosse como Seus irmãos em todos os sentidos, para que se tornasse o Sumo Sacerdote misericordioso e fiel das coisas de Deus e, assim, fazer propiciação pelos pecados do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Como Jesus sofreu, tendo sido tentado, Ele é capaz de ajudar aqueles que também estão sendo tentados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Por isso, irmãos santos, companheiros de vocação celestial, considerai o Apóstolo e Sumo Sacerdote de nossa confissão, Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Ele foi fiel a Deus que O constituiu, assim como também Moisés foi fiel em toda a casa de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Pois Jesus foi considerado digno de maior glória do que Moisés, porque aquele que constrói a casa tem maior honra do que a própria casa em si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Pois toda casa é construída por alguém, mas o construtor de tudo é Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Por um lado, Moisés foi fiel como servo em toda a casa de Deus, para dar testemunho a respeito das coisas que seriam ditas no futuro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Por outro lado, Cristo, sendo Filho, está acima da casa de Deus, que somos nós, se mantivermos firmes a ousadia e exaltação da nossa esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Portanto, é como diz o Espírito Santo: \"Hoje, se a voz Dele ouvirdes,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'não endureçais os vossos corações como na rebelião, no tempo de provações no deserto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Isso aconteceu quando vossos pais se rebelaram, testando-Me; e quando, durante quarenta anos, eles viram os Meus feitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Mas Eu fiquei irado com aquela geração. Eu disse: \'Eles têm sido guiados por seus próprios corações, e não têm conhecido os Meus caminhos.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Assim é que Eu jurei na Minha ira: \'eles jamais entrarão no Meu descanso\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Sede cuidadosos, irmãos, para que não haja em vosso meio coração perverso de incredulidade, um coração que se afasta do Deus vivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Mas encorajai-vos mutuamente cada dia, e também no dia chamado \"hoje\", para que ninguém entre vós seja endurecido pelo engano do pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Pois nos tornamos participantes de Cristo se guardarmos firmes até o fim a confiança que tivemos Nele desde o início.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Sobre isso se diz: \"Hoje, se ouvirdes a Sua voz, não endureçais os vossos corações, como foi na rebelião\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Pois quem foram os que tendo ouvido a Deus, se rebelaram? Não foram todos os que saíram do Egito por intermédio de Moisés?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'E com quais Deus Se irritou por quarenta anos? Não foram com os que pecaram, cujos cadáveres caíram no deserto?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'E a quem Ele jurou que não entraria no Seu descanso, senão aos que Lhe desobedeceram?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Vemos pois, que eles não puderam entrar no Seu descanso, por causa da incredulidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Portanto, sejamos cautelosos para que nenhum de vós pareça ter falhado em alcançar a promessa, deixada para vós, de entrar no descanso de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Pois, recebemos as boas novas assim como eles, mas a mensagem não beneficia aqueles que a ouviram sem nela depositar a sua fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Porque nós, os que cremos, somos aqueles que entraremos neste descanso, assim como foi dito: \"Conforme jurei em minha ira, eles jamais entrarão no Meu descanso\". Embora, as Suas obras estivessem concluídas desde a fundação do mundo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'pois Ele disse, em algum lugar, a respeito do sétimo dia: \"Deus descansou no sétimo dia de todas as Suas obras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Novamente, disse: \"Eles não entrarão no Meu descanso\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Entretanto, como o descanso de Deus ainda está reservado para alguns entrarem, e uma vez que muitos Israelitas que ouviram as boas novas a respeito do Seu descanso não entraram por causa da desobediência, Deus novamente reservou um dia específico, chamado \"Hoje\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Ele estabeleceu esse dia quando falou por meio de Davi, como já havia dito anteriormente: \"Hoje, se ouvirdes a Sua voz, não endureçais o vosso coração\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Pois, se Josué tivesse lhes dado descanso, Deus não vos teria falado acerca de outro dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Por isso, ainda existe um descanso sabático para o povo de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Porque aqueles que entram no descanso de Deus, descansam de suas obras, assim como Deus descansou das Suas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Portanto, esforçai-vos para entrar nesse descanso, a fim de que ninguém caia no mesmo tipo de desobediência que eles caíram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Porque a Palavra de Deus é viva e poderosa, mais afiada do que uma espada de dois gumes, a qual penetra até a divisão da alma e do espírito, das juntas e medulas, apta para discernir as intenções e pensamentos do coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Nenhuma criatura está escondida diante de Seus olhos. Ao contrário, tudo está revelado e exposto diante dos olhos Daquele a quem deveremos prestar contas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Tendo, então, um grande Sumo Sacerdote que atravessou os céus, Jesus, o filho de Deus, apeguemo-nos firmemente à nossa confissão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Pois, nós não temos um sumo sacerdote que não se compadeça de nossas fraquezas, mas, Aquele que foi tentado assim como nós, exceto pelo fato de Ele não ter pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Aproximemo-nos com ousadia ao trono da graça, para recebermos misericórdia e encontrarmos graça para ajudar-nos em tempo de necessidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Pois todo sumo sacerdote, escolhido dentre o povo, é nomeado para agir em favor do povo nas coisas concernentes a Deus, para oferecer tanto ofertas quanto sacrifícios pelos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Ele é capaz de tratar com brandura os ignorantes e os que erram, pois ele também está cercado de fraquezas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Por causa disso, ele também precisa oferecer sacrifícios pelos seus próprios pecados, assim como o faz pelos pecados do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'E nenhum homem toma essa honra para si mesmo, mas é chamado por Deus, tal como Arão foi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Assim, Cristo também não honrou a Si mesmo, fazendo-Se sumo sacerdote, mas Aquele que Lhe disse: \"Tu és Meu Filho; hoje Eu Te gerei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Conforme também está escrito: \"Tu és Sacerdote para sempre segundo a ordem de Melquisedeque\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Durante os dias de Sua carne, Ele ofereceu orações e súplicas, clamando com lágrimas Àquele que era capaz de salvá-Lo da morte. Por causa da Sua piedade, Ele foi ouvido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Embora fosse Filho, aprendeu a obediência pelas coisas que sofreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Tendo sido aperfeiçoado, tornou-se fonte da salvação eterna para todos que O obedecem,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'sendo designado por Deus como Sumo Sacerdote segundo a ordem de Melquisedeque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Acerca disso, temos muito a dizer, mas é difícil de explicar porque sois lentos para ouvir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Embora a esta altura vós já deveríeis ser mestres, ainda é necessário que alguém vos ensine os princípios básicos da Palavra de Deus. Vós necessitais de leite, não de alimento sólido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Pois todo aquele que bebe apenas leite é inexperiente na palavra da justiça porque é um bebê.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Por outro lado, a comida sólida é para adultos, aqueles que, pela prática, têm o entendimento treinado para discernir o bem e o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Então, deixando o que primeiramente aprendemos acerca da Palavra de Cristo, devemos prosseguir para maturidade. Não lançando, outra vez, o fundamento do arrependimento das obras mortas e da fé em Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'nem o fundamento do ensino sobre batismos, imposição de mãos, a ressurreição dos mortos e o juízo eterno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Nós também faremos essas coisas, se Deus permitir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Por isso, é impossível para aqueles que uma vez foram iluminados, que provaram do dom celestial, se tornaram participantes do Espírito Santo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'provaram da boa palavra de Deus, dos poderes dos tempos vindouros');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'e que depois caíram; é impossível restaurá-los novamente para o arrependimento. Isto porque crucificaram para si mesmos, outra vez, o próprio Filho de Deus, fazendo Dele um objeto de vergonha pública.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Porque a terra que absorve a chuva que cai e que produz colheita útil para aqueles que nela trabalham, recebe a bênção de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Mas, se produz espinhos e abrolhos, é inútil e está perto de ser amaldiçoada. Seu fim é ser queimada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Mas nós estamos convencidos de coisas melhores acerca de vós, amados, coisas concernentes à salvação, ainda que falemos dessa forma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Pois Deus não é injusto para esquecer o vosso trabalho e o amor que vós demonstrastes pelo Seu nome, no qual vós servistes aos santos e continuastes a fazê-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'E desejamos grandemente que cada um de vós mostreis o mesmo zelo até o fim, com completa certeza da esperança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Não vos torneis preguiçosos, mas imitadores dos que, por meio da fé e paciência, herdam as promessas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Porque quando Deus fez a Sua promessa para Abraão, por não ter ninguém maior do que Ele por quem jurar, jurou por Si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Ele disse: \"Eu certamente te abençoarei e te multiplicarei grandemente\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Dessa forma, Abraão obteve o que lhe foi prometido após ter esperado pacientemente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Pois as pessoas juram por alguém maior do que elas, e em todas as suas disputas, os seus juramentos são uma confirmação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Quando Deus decidiu mostrar, mais claramente, para os herdeiros da promessa a qualidade imutável do seu propósito, Ele o garantiu com um juramento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Ele o fez por meio de duas coisas imutáveis, nas quais é impossível que Deus minta; para que nós, que saímos em busca de refúgio, pudéssemos ter forte encorajamento para apegar-nos firmemente na esperança que nos foi proposta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'A qual temos como âncora segura e firme de nossas almas e que penetra além do véu,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'onde Jesus, como nosso precursor, entrou em nosso lugar, tornando-se Sumo Sacerdote para sempre, segundo a ordem de Melquisedeque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Este Melquisedeque, rei de Salém, é de fato sacerdote do Deus Altíssimo. Ele encontrou-se com Abraão quando este retornava da matança dos reis, e o abençoou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Foi a ele que Abraão deu o dízimo de tudo. Seu nome \"Melquisedeque\" significa \"Rei de Justiça\" e também \"Rei de Salém\", ou seja, \"Rei de Paz\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Ele não tem pai, nem mãe, nem genealogia, sem princípio de dias nem fim de vida. Feito semelhante ao Filho de Deus, ele permanece sacerdote para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Vede quão grande era esse homem visto que o patriarca Abraão lhe deu o dízimo dos melhores despojos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Por um lado, os descendentes de Levi que recebem o sacerdócio, têm um mandamento segundo a Lei para recolherem os dízimos do povo, isto é, de seus irmãos, que também descendem de Abraão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Mas, por outro, Melquisedeque, que não era descendente de Levi, recebeu dízimos de Abraão e o abençoou, o qual tinha as promessas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Não há como negar que o inferior é abençoado pelo superior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Neste caso, são homens mortais que recolhem os dízimos; ao passo que Melquisedeque, que recebeu o dízimo de Abraão, afirma-se que vive.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'E, de certa forma, até Levi, que recebeu dízimos, também pagou dízimos através de Abraão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'pois ele ainda não havia sido gerado, quando Abraão se encontrou com Melquisedeque.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Portanto se a perfeição fora alcançada pelo sacerdócio levítico (pois nele se apoia a lei dada ao povo), que necessidade haveria de outro sacerdote segundo a ordem de Melquisedeque, e não segundo a ordem de Arão?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Pois quando o sacerdócio é alterado, a lei também precisa ser alterada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Ora, Aquele a quem aqui se refere o texto pertence a outra tribo, da qual nenhum homem jamais serviu no altar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'É conhecido que o nosso Senhor é descendente de Judá, tribo a respeito da qual Moisés nada diz quando se trata de sacerdotes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'E isto fica mais evidente se, à semelhança de Melquisedeque, se constitui um outro sacerdote;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'não foi segundo a lei de descendência carnal que Ele se tornou um sacerdote, mas, em vez disso, conforme o poder de uma vida indestrutível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Pois a Escritura testifica a respeito Dele: \"Tu és Sacerdote para sempre, segundo a ordem de Melquisedeque\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Portanto o antigo mandamento está anulado porque era fraco e sem proveito;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'de fato, a Lei nada aperfeiçoou. No entanto, uma melhor esperança foi introduzida, pela qual nos aproximamos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'E isso não aconteceu sem que houvesse um juramento. Por um lado, aqueles recebiam o sacerdócio sem prestar juramento;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'por outro, Este, Jesus, tornou-se Sacerdote com juramento Daquele que disse: \"O Senhor jurou e não voltará atrás: \'Tu és Sacerdote para sempre\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Neste sentido, Jesus se tornou a garantia de uma aliança superior.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Ora, aqueles se tornam sacerdotes em maior número, mas são impedidos pela morte de continuar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Entretanto, porque Jesus vive para sempre, o Seu sacerdócio é permanente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Por isso, Ele também pode salvar completamente aqueles que, por meio Dele, se chegam a Deus; vivendo sempre para interceder por eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Pois tal Sumo Sacerdote nos convinha: santo, imaculado, inocente, puro, separado dos pecadores, e que foi exaltado acima dos céus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Diferentemente dos outros sumos sacerdotes, Ele não precisa oferecer sacrifícios diários, primeiro por seus próprios pecados, e depois pelos pecados do povo. Ele já fez isso uma vez por todas, quando a si mesmo se ofereceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'A Lei estabeleceu como sumos sacerdotes homens sujeitos à fraquezas; mas, a palavra do juramento, que veio após a Lei, elegeu o Filho, perfeito para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'O essencial do que estamos dizendo é que temos um Sumo Sacerdote, que Se assentou à destra do trono da Majestade nos céus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Ele é um servo do Santo Lugar e do verdadeiro tabernáculo, que o Senhor construiu, não o homem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Pois todo sumo sacerdote é constituído para oferecer tanto dádivas como sacrifícios. Por esse motivo, era necessário que ele tivesse algo para oferecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Se Cristo estivesse na terra, Ele não seria sacerdote, uma vez que existem aqueles que oferecem as dádivas de acordo com a Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'O serviço que prestam é cópia e sombra das coisas celestiais, da mesma forma que Moisés foi avisado por Deus, quando ele estava para construir o tabernáculo: \"Vê que faças tudo conforme o modelo que te foi mostrado no monte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Mas, agora, Cristo obteve um ministério superior, porque Ele é o Mediador de uma aliança melhor, a qual foi estabelecida sobre promessas melhores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Pois, se a primeira aliança não tivesse defeito, não seria necessário buscar uma segunda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Pois quando Deus repreendeu o Seu povo, disse: \"Eis que virão dias\", diz o Senhor, \"em que Eu farei uma nova aliança com a casa de Israel e com a casa de Judá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Ela não será igual à aliança que Eu fiz com seus ancestrais, nos dias em que os peguei pela mão, para guiá-los para fora da terra do Egito. Porque eles não permaneceram na Minha aliança, e Eu não dei mais atenção a eles\", diz o Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, '\"Pois esta é a aliança que farei com a casa de Israel, após aqueles dias\", diz o Senhor. \"Colocarei a Minha Lei em suas mentes e também a escreverei em seus corações. Serei o seu Deus e eles serão o Meu povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Não mais ensinará cada um ao seu vizinho e cada um ao seu irmão, dizendo: \'Conhece ao Senhor\'; porque todos Me conhecerão, do menor ao maior deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Pois, mostrarei misericórdia para com os seus atos de injustiça e não Me lembrarei mais dos seus pecados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Ao dizer \"nova,\" Ele tornou a primeira aliança ultrapassada; e o que está ultrapassado está prestes a desaparecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Ora, a primeira aliança tinha preceitos para o culto e o seu santuário terrestre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Pois um tabernáculo foi preparado, cuja parte anterior, onde estavam o candelabro, a mesa e os pães consagrados, era chamado de Santo Lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'E, por trás da segunda cortina, havia outra sala, chamada de Santo dos Santos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'que tinha um altar de ouro para o incenso e a arca da aliança, completamente coberta de ouro. Dentro dela havia um jarro de ouro contendo o maná, a vara de Arão que floresceu e as tábuas da aliança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Acima da arca, querubins da glória cobrindo o propiciatório. Dessas coisas, não podemos, agora, falar em detalhes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Depois dessas coisas terem sido preparadas, os sacerdotes regularmente entram na sala anterior do tabernáculo, a fim de ministrarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Porém, na segunda sala, somente o Sumo Sacerdote entra, uma vez por ano, e não sem sangue, que ele oferece por si mesmo e pelos pecados de ignorância do povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'O Espírito Santo quis mostrar que o caminho do Santíssimo Lugar não poderia ser revelado, enquanto o primeiro tabernáculo permanecesse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Essa é uma ilustração para o tempo presente. Ambos, as ofertas e os sacrifícios que agora estão sendo oferecidos, não são capazes de aperfeiçoar a consciência de quem cultua;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'os quais são apenas de ordenanças da carne, relativas a comida, a bebida e a diversas lavagens cerimoniais, até que a nova ordenança pudesse ser colocada no lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Mas Cristo veio como Sumo Sacerdote dos bens futuros, mediante o maior e mais perfeito tabernáculo, não feito por mãos humanas, isto é, não deste mundo criado,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'nem mediante sangue de cabrito e novilhos, mas pelo sangue de Cristo, que entrou no Santos dos Santos, uma vez por todas, tendo obtido nossa eterna redenção.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Porque, se o sangue de cabritos e de touros e a aspersão das cinzas de uma novilha sobre aqueles que estão impuros os separam para Deus, tornando seus corpos puros,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'muito mais o sangue de Cristo, que, pelo Espírito eterno, ofereceu a Si mesmo sem defeito para Deus, limpará nossa consciência de obras mortas para servirmos ao Deus vivo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Por essa razão, Ele é Mediador de uma nova aliança, por meio de Sua morte, para remir os pecados daqueles debaixo da primeira aliança, para que os chamados possam receber a promessa da herança eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Pois, onde existe um testamento, é necessário provar a morte do testador;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'porque um testamento só é válido mediante a morte, sendo sem validade enquanto o testador viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Portanto, nem mesmo a primeira aliança foi estabelecida sem sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Pois quando Moisés tinha dado todo o mandamento da Lei para todas as pessoas, ele pegou o sangue de novilhos e de cabritos, com água, lã vermelha e hissopo, e aspergiu sobre o próprio livro e sobre todo o povo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'dizendo: \"Este é o sangue da aliança, a qual Deus vos ordenou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Da mesma maneira, ele aspergiu com sangue o tabernáculo e todas as vasilhas usadas no culto sacerdotal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'E, de acordo com a Lei, quase todas as coisas são purificadas com sangue; e, sem derramamento de sangue, não há remissão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Era necessário, portanto, que as figuras das coisas que estão no céu fossem purificadas com o sacrifício desses animais; porém, as coisas celestiais, em si mesmas, devem ser purificadas com um sacrifício muito melhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Porque Cristo não entrou num santuário feito por mãos, o qual é uma cópia do verdadeiro; mas, sim, no próprio céu, onde agora comparece na presença de Deus por nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Ele não entrou lá para Se oferecer muitas vezes, como o faz um sumo sacerdote, que entra no Santo dos Santos, ano após ano, com o sangue alheio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Se assim fosse, então seria necessário que Ele sofresse muitas vezes desde a fundação do mundo. Mas agora, somente uma vez, ao se cumprirem os tempos, é que Ele foi revelado para remover o pecado por meio de Seu próprio sacrifício.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Assim como toda pessoa está destinada a morrer uma só vez, e depois disso vem o juízo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'também Cristo, o qual foi oferecido uma só vez para tirar os pecados de muitos, aparecerá uma segunda vez, sem pecado, para a salvação daqueles que por Ele esperam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Pois a Lei é apenas uma sombra dos bens futuros, não as formas reais dessas coisas em si. Ela nunca pode tornar perfeitos os que se aproximam de Deus, através dos mesmos sacrifícios que os sacerdotes oferecem continuamente ano após ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Do contrário, aqueles sacrifícios não teriam deixado de serem oferecidos? Nesse caso, se tivessem sido limpos de uma vez por todas, os que prestam culto não teriam mais consciência do pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Mas, com aqueles sacrifícios, há uma lembrança dos pecados ano após ano.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Pois é impossível que o sangue de touros e de cabritos tire os pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Por isso, quando Cristo entrou no mundo, disse: \"Não desejaste sacrifícios e ofertas, mas um corpo que preparaste para Mim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Não tiveste prazer com holocaustos nem com sacrifícios pelos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Então eu disse: \"Eis aqui estou, ó Deus, para fazer a Tua vontade, como está escrito nos pergaminhos a Meu respeito\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Primeiro Ele disse: \"Tu não desejaste nem sacrifícios, nem ofertas, nem holocaustos, nem sacrifícios pelos pecados. Nem tiveste prazer neles\". Esses são os sacrifícios oferecidos de acordo com a Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Então Ele disse: \"Eis aqui estou para fazer a Tua vontade\". Ele remove a primeira prática a fim de estabelecer a segunda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'E, por essa vontade, temos sido santificados através da oferta do corpo de Jesus Cristo de uma vez por todas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Por um lado, todo sacerdote permanece, dia após dia, ministrando, sempre oferecendo os mesmos sacrifícios, embora eles nunca possam tirar os pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Por outro lado, Cristo ofereceu um sacrifício pelos pecados para sempre, e assentou-se à direita de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'E então espera até que seus inimigos sejam postos por estrado dos Seus pés.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'De fato, por uma única oferta, Ele aperfeiçoou, para sempre, aqueles que estão sendo santificados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'E o Espírito Santo também nos dá testemunho, após ter dito:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Esta é a aliança que farei com eles depois daqueles dias\", diz o Senhor. \"Colocarei as Minhas leis em seus corações e as increverei em sua mente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Não lembrarei mais dos seus pecados e de suas iniquidades\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'E se há perdão para isso, já não há necessidade de qualquer sacrifício pelo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Portanto, irmãos, temos confiança para entrar no Santíssimo Lugar pelo sangue de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Esse é o novo e vivo caminho que Ele abriu para nós através do véu, isto é, pela Sua carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'E, porque temos um Grande Sacerdote sobre a casa de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'aproximemo-nos com um verdadeiro coração, em plena certeza de fé, tendo os nossos corações sido purificados de uma má consciência e os nossos corpos lavados com água pura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Também seguremos firmemente a confissão da nossa esperança, sem vacilar, porque Deus, que prometeu, é fiel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Consideremos uns aos outros para nos motivarmos ao amor e às boas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Não deixemos de congregar-nos, como alguns têm feito. Em vez disso, encorajemos uns aos outros quanto mais vedes que o dia está próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Porque se nós pecarmos deliberadamente depois de termos recebido o conhecimento da verdade, já não existe mais um sacrifício pelos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Em vez disso, há apenas uma terrível expectativa de juízo e um fogo ardente que consumirá os inimigos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Qualquer um que rejeita a Lei de Moisés, diante da confirmação de duas ou três testemunhas, morre sem misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Que punição mais severa merece aquele que tenha pisado o Filho de Deus, alguém que tratou o sangue da aliança como impuro, o sangue pelo qual ele foi santificado, e insultou o Espírito da graça?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Nós conhecemos Aquele que disse: \"A vingança pertence a Mim, Eu a retribuirei\". E novamente: \"O Senhor julgará o Seu povo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'É uma coisa terrível cair nas mãos do Deus vivo!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Mas lembrai-vos dos dias anteriores, depois que fostes iluminados, como suportastes uma grande luta no sofrimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Fostes expostos publicamente, ridicularizados por insultos e perseguições, e fostes participantes com aqueles que assim foram tratados com tal sofrimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Pois tivestes compaixão daqueles que eram prisioneiros e aceitastes com alegria a tomada de vossas posses, sabendo que possuís um patrimônio melhor e permanente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Então, não lanceis fora a vossa confiança, na qual tendes uma grande recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Pois precisais de paciência para que, depois de terdes feito a Sua vontade, possais receber o que Deus vos tem prometido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, '\"Pois, em muito pouco tempo, Aquele que está vindo virá e não tardará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'O Meu justo viverá pela fé. Caso ele volte atrás, Eu não terei prazer nele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Mas nós não somos daqueles que voltam atrás, para destruição, mas daqueles que têm fé para preservar nossa alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Agora, a fé é a certeza sobre as coisas que se esperam. É a prova sobre fatos que não se veem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Pois, pela fé, os antepassados obtiveram bom testemunho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Pela fé, entendemos que o universo foi criado pela palavra de Deus, de modo que o visível não foi feito do que se vê.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Foi pela fé que Abel ofereceu a Deus um sacrifício melhor do que Caim, através do qual foi aprovado como justo, e Deus testemunhou sobre ele por causa das suas ofertas. E pela fé Abel ainda fala, embora esteja morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Foi pela fé que Enoque foi trasladado de maneira que não viu a morte. \"Ele não foi achado, porquanto Deus o tomou\". Pois, antes de ser trasladado, obteve testemunho de ter agradado a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Sem fé é impossível agradar a Deus. Por isso, é necessário que aquele que se aproxima de Deus acredite que Ele existe e que recompensa os que O buscam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Foi pela fé que Noé, sendo instruído por Deus sobre coisas que ainda não se viam, com reverência a Deus, construiu a arca para salvar sua casa. Fazendo isso, condenou o mundo e se tornou herdeiro da justiça que vem por meio da fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Foi pela fé que Abraão, quando foi chamado, obedeceu e saiu para um lugar o qual iria receber como herança. Ele saiu, sem saber para onde estava indo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Foi pela fé que peregrinou na terra da promessa como um estrangeiro. Ele viveu em tendas com Isaque e Jacó, co-herdeiros da mesma promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Isso porque ele estava olhando para a cidade que tem fundamentos, cujo arquiteto e construtor é Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Foi pela fé que Sara, embora sendo estéril, recebeu o poder de conceber. Isso aconteceu ainda que já estivesse em idade avançada, pois considerou fiel Aquele que lhe fez a promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Portanto, desse homem, que estava amortecido, nasceu tão numerosa multidão, quanto as estrelas do céu e incontáveis como os grãos de areia da praia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Todos esses morreram na fé sem receber as promessas, vendo-as, saudando-as de longe e confessando que eram estrangeiros e peregrinos na terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Para aqueles que dizem tais coisas, fica claro que estão buscando uma pátria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Se tivessem lembrado da terra que deixaram, teriam tempo para voltar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Mas eles desejaram uma pátria melhor, isto é, a celestial. Portanto, Deus não está envergonhado de ser chamado Deus deles, pois preparou-lhes uma cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Foi pela fé que Abraão, quando foi testado, ofereceu Isaque, seu primogênito, aquele sobre o qual recebeu a promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'Foi para ele que isto foi dito: \"Em Isaque serão chamados os teus descendentes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Abraão considerou que Deus era poderoso para o levantar dentre os mortos e, figuradamente, o recebeu de volta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Foi pela fé que Isaque abençoou a Jacó e a Esaú acerca de coisas por vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Foi pela fé que Jacó, quando estava morrendo, abençoou cada um dos filhos de José e, inclinado sobre a ponta do seu bordão, adorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Foi pela fé que José, quando estava próximo do seu fim, falou do êxodo dos filhos de Israel do Egito e deu ordens acerca de seus ossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Foi pela fé que Moisés, quando nasceu, foi escondido, por três meses, pelos seus pais, porque viram que o menino era formoso. Eles não temeram ao decreto do rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Foi pela fé que Moisés, após ter crescido, recusou-se a ser chamado filho da filha de Faraó.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Mas ele escolheu sofrer com o povo de Deus, ao invés de aproveitar os prazeres do pecado por algum tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Ele considerou que a desonra de Cristo era uma riqueza maior do que os tesouros do Egito, porque tinha fixado os seus olhos na recompensa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Foi pela fé que Moisés deixou o Egito. Ele não temeu a ira do rei, pois suportou como quem vê aquele que é invisível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Foi pela fé que ele celebrou a Páscoa e a aspersão do sangue, para que o destruidor dos primogênitos não lhes tocasse.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Foi pela fé que eles atravessaram pelo mar vermelho como em terra seca. Quando os Egípcios tentaram fazer isso, foram engolidos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Foi pela fé que as muralhas de Jericó caíram, após terem sido rodeadas por sete dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Foi pela fé que Raabe, a prostituta, não pereceu com os desobedientes, porquanto recebeu os espias com paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'E o que mais posso dizer? Me faltará tempo para falar sobre Gideão, Baraque, Sansão, Jefté, Davi, Samuel e os profetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Os quais, pela fé, conquistaram reinos, praticaram justiça e receberam promessas. Fecharam a boca de leões,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'extinguiram o poder do fogo, escaparam do fio da espada, foram fortalecidos nas fraquezas, tornaram-se poderosos na guerra e puseram em fuga exércitos estrangeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Mulheres receberam os seus mortos de volta pela ressurreição. Outros foram torturados, não aceitando o livramento para que obtivessem uma melhor ressurreição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Outros experimentaram zombarias e açoites, e até mesmo algemas e prisões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Foram apedrejados, serrados ao meio e mortos a fio da espada. Andaram cobertos com peles de ovelhas e cabras, necessitados, afligidos e maltratados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'O mundo não era digno deles. Eles andaram errantes pelo deserto, montanhas, cavernas e buracos da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Embora todos estes obtivessem bom testemunho por causa da sua fé, não receberam a promessa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Pois Deus planejou algo melhor para nós, para que conosco fossem aperfeiçoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Portanto, uma vez que estamos rodeados por uma tão grande nuvem de testemunhas, rejeitemos todo o peso e o pecado que facilmente nos assedia. Corramos pacientemente a corrida que está diante de nós');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'e fixemos os olhos em Jesus, o Autor e Consumador da nossa fé. Em troca da alegria que Lhe estava proposta, suportou a cruz, desprezou a vergonha e se assentou à direita do trono de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Considerai, pois, Aquele que suportou tal oposição dos pecadores contra Si, para que vós não vos canseis e desanimeis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Vós ainda não resististes até ao sangue na luta contra o pecado;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'e vós esquecestes a exortação, a qual vos foi dirigida como a filhos: \"Meu Filho, não desprezes a correção do Senhor, nem desanimes quando estiveres sendo corrigido por Ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Porque o Senhor corrige a quem ama e açoita a todo o filho a quem Ele acolhe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Suportai o sofrimento como forma de correção; Deus vos trata como filhos, pois qual é o filho a quem o pai não corrige?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Mas, se estais sem correção, da qual todos são participantes, então vós sois filhos ilegítimos e não filhos Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Além disso, tínhamos pais segundo a carne, que nos corrigiam e nós os respeitávamos. Não deveríamos mais ainda obedecer ao nosso Pai espiritual e assim viver?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Por um lado, nossos pais nos corrigiam por alguns dias como lhes parecia certo. Mas, por outro lado, Deus nos corrige para o nosso bem, para que possamos participar da Sua santidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Toda correção, no momento, não parece motivo de alegria, mas de tristeza. No entanto, mais tarde, produz fruto pacífico de justiça, para aqueles que têm sido por ela exercitados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Portanto, fortalecei as vossas mãos cansadas e os joelhos fracos;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'fazei caminhos retos para os pés, para que todo aquele que é manco não se desvie, pelo contrário, seja curado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Segui a paz com todos e a santificação, sem a qual ninguém verá o Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Cuidado para que ninguém tenha falta da graça de Deus, e que nenhuma raiz de amargura, crescendo, vos perturbe a ponto de contaminar a muitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Cuidai para que não haja algum imoral ou profano como Esaú, o qual, por uma refeição, vendeu o seu direito de primogenitura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Porque sabeis que posteriormente, querendo ele herdar a bênção, foi rejeitado porque não encontrou lugar de arrependimento, embora com lágrimas o tivesse buscado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Porque não chegastes a um monte que possais tocar, a uma montanha de fogo ardente, à escuridão, às trevas e à tempestade;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'não chegastes ao som de trombeta, nem a uma voz que fala palavras, cujos ouvintes suplicaram que nenhuma outra palavra lhes fosse falada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Pois não suportavam o que lhes era ordenado: \"Até um animal, se tocar o monte, será apedrejado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Tão terrível era aquela visão, que Moisés disse: \"Estou aterrorizado e trêmulo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Mas chegastes ao Monte Sião, à cidade do Deus vivo, à Jerusalém celestial e às dezenas de milhares de anjos em celebração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Viestes à igreja dos primogênitos arrolados nos céus; a Deus, o Juiz de todos; aos espíritos dos justos que foram aperfeiçoados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'Viestes a Jesus, o Mediador da nova aliança, e ao sangue da aspersão, que fala melhor do que o sangue de Abel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Vede que não recuseis Aquele que vos está falando. Pois, se as pessoas que rejeitaram Quem na terra os advertia não escaparam, nós certamente não escaparemos, se nos desviarmos Daquele que nos está advertindo dos céus;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Aquele, cuja voz abalou a terra. Mas agora Ele prometeu e disse: \"Ainda, uma vez mais, hei de abalar não só a terra, mas também o céu\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Estas palavras: \"Ainda uma vez mais\" indicam a remoção dessas coisas abaladas, ou seja, as coisas criadas, para que permaneçam as que não podem ser abaladas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Por isso, tendo recebido um reino que não pode ser abalado, retenhamos essa graça e desta forma sirvamos a Deus de modo agradável, com reverência e temor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Pois o nosso Deus é um fogo consumidor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Que o amor fraterno continue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Não vos esqueçais da hospitalidade para com os estrangeiros, pois, fazendo isto, alguns hospedaram anjos sem saber.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Lembrai-vos daqueles que estão presos, como se estivésseis presos com eles. Lembrai-vos dos que são maltratados, como se vós mesmos fôsseis maltratados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Que o casamento seja respeitado por todos e que o leito conjugal seja puro, porque Deus julgará os sexualmente imorais e os adúlteros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Seja a vossa conduta livre do amor ao dinheiro. Contentai-vos com as coisas que tendes, porque Deus mesmo disse: \"Nunca te deixarei, nem jamais te abandonarei\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'De modo que, sendo confiantes, diremos: \"O Senhor é o meu ajudador, eu não temerei. O que poderá me fazer o homem?\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Considerai vossos líderes, aqueles que vos falaram sobre a Palavra de Deus, e observai o resultado da conduta deles. Imitai a fé que tiveram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jesus Cristo é o mesmo ontem, hoje e eternamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Não vos deixeis levar por várias doutrinas estranhas. Porque é bom que o coração seja fortalecido pela graça, não por regras sobre alimentos, as quais não ajudam aqueles que vivem por elas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Temos um altar, do qual aqueles que servem no tabernáculo não têm direito de comer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Pois o sangue dos animais sacrificados pelos pecados é trazido pelo sumo sacerdote ao Santo Lugar, enquanto os seus corpos são queimados fora do acampamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Por isso, a fim de santificar o povo através do Seu próprio sangue, Jesus também sofreu fora dos portões da cidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Portanto, saiamos ao Seu encontro fora do acampamento, suportando a Sua vergonha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Porque nós não temos uma cidade permanente aqui. Pelo contrário, buscamos a cidade que virá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Então, através Dele, ofereçamos constantemente sacrifícios de louvor a Deus, que é fruto dos lábios que confessam o Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'E não nos esqueçamos de fazer o bem e de ajudar uns aos outros, pois esse é o sacrifício que agrada muito a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Obedecei a vossos líderes e sede-lhes submissos, porque eles cuidam das vossas almas, como aqueles que prestarão contas. Obedecei aos vossos líderes para que façam isso com alegria e não lamentando, pois vos será inútil.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Orai por nós, pois estamos convencidos de que temos uma consciência limpa, desejando viver corretamente em todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Eu vos encorajo ainda mais a agirdes assim, de modo que eu possa retornar a vós mais cedo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Que o Deus da paz, o qual, através do sangue da aliança eterna, trouxe dentre os mortos o grande Pastor das ovelhas, nosso Senhor Jesus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'vos aperfeiçoe em todas as coisas boas para cumprirdes a Sua vontade. Que Ele trabalhe em nós aquilo que é agradável diante Dele, através de Jesus Cristo, a quem seja a glória para sempre. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Irmãos, eu vos exorto a suportar essa palavra de encorajamento que brevemente vos escrevi.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Sabei que o nosso irmão Timóteo foi liberto, com o qual eu vos vereis, se ele vier logo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Saudai todos os vossos líderes e todos os santos. Os da Itália vos saúdam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Que a graça esteja com todos vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Tiago, servo de Deus e do Senhor Jesus Cristo, às doze tribos da dispersão, saudações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Meus irmãos, considerai motivo de grande alegria o passardes por várias provações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Sabei que a prova da vossa fé produz perseverança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Deixai a perseverança completar a sua obra, para que vos torneis plenamente desenvolvidos e completos, de modo que não vos falte coisa alguma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Mas, se algum de vós necessita de sabedoria, que peça a Deus, pois Ele dá generosamente sem censurar quem pede; e Ele lhe concederá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Mas que peça com fé, sem duvidar, porque aquele que duvida é como uma onda no mar, dirigida pelo vento e lançada de um lado para outro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Essa pessoa, pois, não deve pensar que receberá algo do Senhor;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'uma pessoa assim é vacilante, instável em todos os seus caminhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'O irmão pobre deve gloriar-se na sua exaltação,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'mas o homem rico deve gloriar-se na sua humilhação, porque ele perecerá como a flor do campo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Porque o sol nasce com calor abrasador e seca a grama. A flor cai, e a sua beleza perece. Da mesma maneira, o rico desaparecerá durante sua jornada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Feliz é o homem que suporta a provação, porque, depois de ser aprovado, ele receberá a coroa da vida, que foi prometida àqueles que amam a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Ninguém, quando tentado, deve dizer \"Sou tentado por Deus\", porque Deus não é tentado pelo mal, e Ele mesmo a ninguém tenta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Mas cada pessoa é tentada pelo seu próprio desejo, que a atrai e a arrasta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Então, depois que o desejo concebe, dá à luz o pecado. E, depois que o pecado atinge a maturidade, dá à luz a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Meus amados irmãos, não sejais enganados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Toda boa dádiva e todo dom perfeito vem do alto. Descendo do Pai das luzes. Nele não há mudança ou sombra de variação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Deus escolheu dar-nos vida pela palavra da verdade, para que fôssemos como os primeiros frutos dentre tudo o que Ele criou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Meus amados irmãos, vós sabeis isto: todo homem deve ser pronto para ouvir, tardio para falar, e tardio para se irar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Porque a ira do homem não opera a justiça de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Portanto livrai-vos de toda imundície pecaminosa e abundância do mal. Recebei em humildade a palavra implantada, que é capaz de salvar vossas almas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Sede praticantes da palavra, não apenas ouvintes, enganando a vós mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Porque, se alguém é um ouvinte da palavra e não é um praticante, ele é semelhante a alguém que olha o seu rosto natural em um espelho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Ele olha o próprio rosto, vai embora, e logo se esquece de como ele era.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Mas aquele que cuidadosamente atenta para a perfeita lei da liberdade, e continua fazendo isso, não sendo apenas um ouvinte que se esquece, esse homem será abençoado no que fizer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Se alguém se considera religioso, mas não controla sua língua, ele engana seu coração, e sua religião é sem valor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'A religião pura e imaculada diante de nosso Deus e Pai é esta: ajudar órfãos e viúvas em suas aflições, e manter-se incontaminado do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Meus irmãos, não tenhais a fé de nosso Senhor Jesus Cristo, o Senhor da glória, com favoritismo em relação a algumas pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Imaginai que alguém entre em vossa reunião usando anéis de ouro e roupas finas, e que também entre um homem pobre com roupas sujas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Se atentardes para a pessoa que usa roupas finas e disserdes: \"Por favor, senta-te aqui num ótimo lugar\", e disserdes ao homem pobre: \"Fica por ali\", ou: \"Senta-te aos meus pés\",');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'não estareis julgando entre vós mesmos? Não vos tornastes juízes com pensamentos malignos?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Ouvi, meus amados irmãos: não escolheu Deus os pobres do mundo para serem ricos na fé e herdeiros do reino que Ele prometeu aos que O amam?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Mas, tendes desonrado o pobre! Não é o rico que vos oprime? E não é ele que vos arrasta ao tribunal?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Não é o rico que blasfema o bom Nome ao qual vós pertenceis?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Contudo, se cumpris a Lei real, segundo a Escritura: \"Amarás o teu próximo como a ti mesmo\", fazeis bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Mas, se favoreceis certas pessoas, estais cometendo pecado, estais condenados pela Lei como transgressores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Pois qualquer um que obedece toda a Lei, mas tropeça em um único ponto, torna-se culpado de quebrar toda a Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Porque o mesmo que disse: \"Não cometerás adultério\", também disse: \"Não matarás\". Se não cometes adultério, mas cometes assassinato, então te tornas transgressor da Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Então, falai e procedei como aqueles que serão julgados pela lei da liberdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Pois o julgamento vem sem misericórdia para aqueles que não demostraram misericórdia. A misericórdia triunfa sobre o julgamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Que proveito há, meus irmãos, se alguém diz que tem fé, mas não tem obras? Pode tal fé salvá-lo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Imaginai que um irmão ou irmã precisa de roupa, e não tem comida para o dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'Se algum de vós lhe disser: \"Ide em paz, aquecei-vos e alimentai-vos bem\", sem lhes dar as coisas necessárias para o corpo, que proveito há?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Do mesmo modo, a fé por si só, se não tiver obras, é morta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Mas alguém poderá dizer: \"Tu tens fé, e eu tenho obras\". Mostra-me tua fé sem obras, e eu te mostrarei minha fé pelas minhas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Tu crês que há um único Deus; fazes bem! Mas até os demônios creem nisso, e eles tremem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Tu queres mesmo saber, homem insensato, que a fé sem obras é inútil?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Não foi Abraão, nosso pai, justificado pelas obras, quando ofereceu seu filho Isaque sobre o altar?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Vês que a fé operou junto com suas obras, e que, pelas obras, sua fé foi plenamente desenvolvida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'Cumpriu-se a Escritura, que diz: \"Abraão creu em Deus, e isso lhe foi imputado como justiça\"; e ele foi chamado amigo de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vês que pelas obras um homem é justificado, e não somente pela fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Também, da mesma maneira, não foi a prostituta Raabe justificada por obras, quando recebeu os mensageiros, e os enviou por outro caminho?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Pois, assim como o corpo separado do espírito é morto, da mesma forma a fé separada das obras é morta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Meus irmãos, poucas pessoas deveriam ser mestres. Sabemos que nós receberemos julgamento mais severo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Porque todos nós tropeçamos de muitas maneiras. Se alguém não tropeça nas palavras, é um homem plenamente desenvolvido, capaz de controlar até mesmo seu corpo inteiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Se colocamos freios nas bocas de cavalos para que nos obedeçam, podemos também dirigir-lhes o corpo todo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Observai também que navios, embora sejam tão grandes e dirigidos por ventos fortes, são conduzidos por um pequeno leme para onde quer que o piloto queira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Da mesma forma, a língua é uma pequena parte do corpo, mas se gloria de grandes coisas. Observai também como uma grande floresta é incendiada por uma pequena faísca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'A língua é também um fogo, um mundo de pecaminosidade entre as partes do nosso corpo, que mancha todo o corpo e incendeia o curso da vida. A própria língua é incendiada pelo inferno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Pois todo tipo de animal selvagem, ave, réptil e criaturas do mar são domesticáveis, e têm sido domesticados pela humanidade;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'mas, quanto à língua, ninguém entre os homens é capaz de domá-la. Ela é um mal incontrolável, cheio de veneno mortal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Com a língua, louvamos nosso Senhor e Pai, e com ela amaldiçoamos o homem, que foi feito à semelhança de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Da mesma boca procedem bênção e maldição. Meus irmãos, essas coisas não devem acontecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Pode uma fonte jorrar ao mesmo tempo água doce e amarga?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Meus irmãos, pode uma figueira produzir azeitonas? Ou uma videira produzir figos? Da mesma forma, a fonte de água salgada não pode produzir água doce.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Quem entre vós é sábio e entendido? Que essa pessoa demonstre um bom procedimento pelas suas obras na humildade que vem da sabedoria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Mas, se tendes inveja amargurada e ambição no vosso coração, não vos glorieis nem mintais contra a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Essa não é a sabedoria que desce do alto; em vez disso, é terrena, demoníaca, não espiritual.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Porque onde existe inveja e ambição, há confusão e todo tipo de prática má.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Mas a sabedoria que vem do alto é primeiramente pura, depois pacífica, gentil, compreensiva, cheia de misericórdia e de bons frutos, imparcial e sincera.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'E o fruto da justiça é semeado em paz, entre aqueles que promovem a paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'De onde surgem contendas e disputas entre vós? Não vêm elas dos vossos desejos que lutam entre vossos membros?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Desejais e nada tendes, matais e invejais e nada sois capazes de obter, lutais e contendeis. Não tendes, porque não pedis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Pedis e não recebeis porque pedis mal, com o fim de usardes isso para vossos prazeres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Adúlteros! Não sabeis vós que a amizade com o mundo é inimizade contra Deus? Portanto quem quiser ser amigo do mundo torna-se inimigo de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Ou pensais que a Escritura diz em vão: \"Com ciúmes, Deus anseia pelo Espírito que Ele fez habitar em nós?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Mas Deus dá maior graça, por isso diz a Escritura: \"Deus resiste aos orgulhosos, mas dá graça aos humildes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Portanto sujeitai-vos a Deus, resisti ao diabo, e ele fugirá de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Achegai-vos a Deus, e Ele se achegará a vós. Limpai vossas mãos, pecadores, e purificai vossos corações, vós que sois vacilantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Entristecei-vos, lamentai, e chorai! Que o vosso riso se transforme em lamento, e a vossa alegria, em tristeza.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Humilhai-vos diante do Senhor, e Ele vos exaltará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Não faleis mal uns dos outros. A pessoa que fala mal de um irmão, ou que julga seu irmão fala contra a Lei e julga a Lei. Se julgas a Lei, não és praticante da Lei, mas juiz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Somente um é legislador e juiz. Ele é Aquele que é capaz de salvar e destruir. Quem és tu, que julgas teu próximo?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Ouvi, agora, vós que dizeis: \"Hoje ou amanhã nós iremos para esta cidade, ficaremos lá um ano, negociaremos e obteremos lucro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Quem sabe o que acontecerá amanhã? E o que é a vossa vida? Pois vós sois como a névoa que aparece por pouco tempo e então desaparece.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Ao invés disso, devíeis dizer: \"Se o Senhor quiser, viveremos e faremos isto ou aquilo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Mas agora vos orgulhais dos vossos planos arrogantes. Todo orgulho como esse é maligno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Portanto aquele que sabe fazer o bem e não o faz está pecando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Vinde agora, vós que sois ricos, chorai e lamentai por causa das misérias que virão sobre vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Vossas riquezas apodreceram e vossas roupas foram comidas pela traça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Vosso ouro e vossa prata se corroeram, e essa corrosão será testemunha contra vós. Ela devorará vossa carne como fogo. Guardastes o vosso tesouro para os últimos dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Vede, o pagamento dos trabalhadores está clamando, o pagamento que retivestes daqueles que colheram em vossos campos. Os clamores dos ceifeiros chegaram aos ouvidos do Senhor dos Exércitos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Vivestes luxuosamente sobre a terra, satisfazendo os vossos prazeres. Engordastes os vossos corações para o dia da matança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Condenastes e matastes o justo; ele não vos resistiu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Portanto sede pacientes, irmãos, até a vinda do Senhor. Vede, o agricultor espera a valiosa colheita da terra. Ele espera pacientemente por isso, até que a terra receba as primeiras e as últimas chuvas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Sede também pacientes. Fortalecei os vossos corações, porque a vinda do Senhor está próxima.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Não vos queixeis uns contra os outros, irmãos, para que não sejais julgados. Vede, o juiz está à porta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Tomai como exemplo, irmãos, o sofrimento e a paciência dos profetas, os quais falaram no nome do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Vede, consideramos felizes aqueles que perseveram. Ouvistes da perseverança de Jó, e conheceis o propósito do Senhor, quão compassivo e misericordioso Ele é.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Sobretudo, meus irmãos, não jureis, nem pelo céu nem pela terra, nem por qualquer outro voto. Em vez disso, que o vosso \"Sim\" signifique \"Sim\", e que o vosso \"Não\" signifique \"Não\", assim não caireis em juízo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Está alguém entre vós sofrendo? Que ore. Está alguém alegre? Que cante louvores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Está alguém entre vós doente? Que chame os presbíteros da igreja, e que orem sobre ele, ungindo-o com óleo em nome do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'E a oração da fé vai curar o doente, e o Senhor o levantará. Se ele cometeu pecados, Deus o perdoará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Portanto confessai vossos pecados uns aos outros e orai uns pelos outros para serdes curados. A oração do justo é poderosa e eficaz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elias foi um homem assim como nós. Ele orou fervorosamente para que não chovesse, e não choveu sobre a terra por três anos e seis meses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'E novamente Elias orou, e o céu deu chuva, e a terra produziu o seu fruto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Meus irmãos, se algum de vós se desvia da verdade, e alguém o traz de volta,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'sabei que a pessoa que resgata um pecador do seu caminho errado o salvará da morte, e cobrirá multidão de pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Pedro, apóstolo de Jesus Cristo, aos eleitos, estrangeiros dispersos em Ponto, Galácia, Capadócia, Ásia e Bitínia,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'escolhidos de acordo com a presciência de Deus Pai, pela santificação do Espírito Santo, para a obediência a Jesus Cristo, e para a aspersão de Seu sangue. Que a graça esteja convosco e a vossa paz seja multiplicada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo. Que na Sua grande misericórdia, nos deu um novo nascimento para a esperança viva por meio da ressurreição de Jesus Cristo dentre os mortos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'para uma herança que não perecerá, não se contaminará e nem desvanecerá. Ela está reservada no céu para vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Pelo poder de Deus vós estais protegidos mediante a fé para a salvação que está pronta para ser revelada nos últimos tempos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Alegrai-vos nisso, embora agora seja necessário que vos sintais afligidos em várias provações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Para que a vossa fé mais preciosa que o ouro, seja aprovada, como o ouro que perece é provado pelo fogo. Isso ocorre para que a vossa fé resulte em louvor, glória, e honra na revelação de Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Embora não O tendo visto, O amais. Vós não O vedes agora, mas vós credes Nele e estais muito alegres com um gozo inexprimível e glorioso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Vós estais agora alcançando o resultado da vossa fé, a salvação de vossas almas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Os profetas procuraram e diligentemente buscaram esta salvação, os quais profetizaram acerca da graça que seria vossa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Eles buscavam saber o tempo e as circunstâncias mais oportunas, indicadas pelo Espírito de Cristo, que neles estava, ao testemunhar de antemão sobre os sofrimentos de Cristo e as glórias que viriam depois Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Aos quais foi revelado que eles não estavam servindo a si mesmos, mas a vós, quando falavam das coisas que agora estão sendo anunciadas por aqueles que pregaram o Evangelho, pelo Espírito Santo enviado do céu, coisas que até mesmo os anjos desejam conhecer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Então, preparai vossa mente para agir. Sejais sóbrios no vosso entendimento. Tende completa confiança na graça que se vos trará na revelação de Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Como filhos obedientes, não vos conformeis com os desejos que vós seguíeis quando não tínheis conhecimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Mas, como Aquele que vos chamou é santo, vós, também, sede santos em toda a vossa maneira de viver.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Porque está escrito, \"Sede santos porque Eu sou santo.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'E se vós chamais de \"Pai\" aquele que julga com imparcialidade de acordo com a obra de cada pessoa, andai em reverência durante a vossa peregrinação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Vós sabeis que não foi com prata nem ouro, coisas corruptíveis, que fostes redimidos da vossa vã maneira de viver que aprendestes de vossos pais,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'mas, com o precioso sangue de Cristo, como de um cordeiro sem defeito e sem mancha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Cristo foi escolhido antes da fundação do mundo, mas agora nestes últimos tempos, Ele tem se revelado a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Por meio Dele vós credes em Deus, a Quem Deus ressuscitou dos mortos e a Quem Ele deu glória de forma que vossa fé e confiança estejam em Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Vós purificastes vossas almas pela obediência à verdade com o propósito de sincero amor fraternal, então, amai uns aos outros com sinceridade de coração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Vós nascestes de novo, não de semente corruptível, mas de semente incorruptível, por meio da viva e permanente Palavra de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Porque \"toda carne é como a erva, e toda sua glória é como a flor da erva. A erva seca e a flor cai;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Mas a Palavra do Senhor permanece para sempre\". Esta é a Palavra do Evangelho que a vós foi proclamada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Portanto, rejeitai todo mal, todo engano, hipocrisia, inveja e calúnia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Como recém nascidos, desejai o puro leite espiritual, de modo que vós possais crescer na salvação por meio Dele,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'se é que tendes provado que o Senhor é bom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Achegai-vos a Ele que é a pedra viva, que por um lado foi rejeitada pelas pessoas, porém escolhida como preciosa por Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Vós, também sois como pedras vivas, usadas para construção da casa espiritual, a fim de serdes um sacerdócio santo que oferece sacrifícios espirituais aceitáveis a Deus por meio de Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Está escrito: \"Eis que coloco em Sião uma Pedra de Esquina, principal, escolhida e preciosa. Quem quer que creia Nela não será envergonhado\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'A honra então é para vós, os que credes. Mas: \"a Pedra que foi rejeitada pelos construtores, Esta se tornou a pedra angular\",');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'e: \"Pedra de tropeço e rocha de ofensa\". Eles tropeçam, desobedecendo à Palavra, porque para isso foram também destinados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Mas vós sois raça escolhida, sacerdócio real, nação santa, povo que pertence a Deus, para que anuncieis as virtudes Daquele que vos chamou das trevas para Sua maravilhosa luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Vós, que outrora não éreis povo, mas, agora vós sois o povo de Deus. Vós, que não recebestes misericórdia, mas agora vós tendes recebido misericórdia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Amados, eu vos exorto como a estrangeiros e peregrinos a vos absterdes dos desejos carnais, que fazem guerra contra a alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Tende um bom comportamento entre os gentios; assim, se eles vos difamam como se fôsseis malfeitores, ao verem as vossas boas obras, glorifiquem a Deus no dia da Sua visitação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Sujeitai-vos a toda autoridade humana por amor do Senhor, seja ao rei, como soberano,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'ou aos governadores que são enviados para punir os malfeitores e para louvar aqueles que fazem o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Pois tal é a vontade de Deus, que fazendo o bem silencieis a fala ignorante das pessoas tolas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Como povo livre, não useis vossa liberdade como um pretexto para a maldade, mas, sede como servos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Honrai todas as pessoas. Amai os irmãos. Temei a Deus. Honrai ao rei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Servos, sede submissos aos vossos senhores, com todo respeito, não apenas aos senhores bons e gentis, mas também àqueles que são perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Pois é louvável se alguém suporta a dor de um sofrimento injusto por causa da sua consciência para com Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Portanto, que glória há se suportais a devida punição por um pecado cometido? Mas, se, fazendo o bem, sofreis, isto é louvável diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Para isto é que fostes chamados, porque Cristo também sofreu por vós, deixando um exemplo para seguirdes Seus passos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Ele não cometeu pecado, nem foi encontrado qualquer engano em Sua boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Quando foi injuriado, não revidou; quando sofreu, não ameaçou, mas Se entregou a Si mesmo Àquele que julga justamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Sobre o madeiro Ele carregou os nossos pecados em Seu próprio corpo, a fim de que morrêssemos para o pecado, e assim vivêssemos para a justiça. Por Suas feridas fomos sarados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Pois todos vós éreis como ovelhas desgarradas, mas agora retornastes ao Pastor e Guardião de vossas almas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Desta maneira, vós, esposas, deveis ser submissas aos vossos maridos, para que também, se alguns deles são desobedientes à Palavra, sejam alcançados sem palavra, por meio da vossa conduta,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'observando o vosso comportamento puro e respeitoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Que o vosso enfeite não seja o exterior, como cabelos trançados, joias de ouro ou roupas luxuosas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'mas, ao invés disso, esteja o interior do vosso coração revestido com um adorno incorruptível, que é um espírito gentil e manso, o qual é precioso diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Pois no passado, as santas mulheres enfeitavam-se dessa maneira. Elas tinham confiança em Deus e eram submissas a seus maridos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Do mesmo modo que Sara obedeceu a Abraão e o chamou de senhor, dela vos tornastes filhas, praticando o bem e não temendo perturbação alguma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Da mesma maneira, vós, maridos, deveis viver com vossas esposas, entendendo que a mulher é o vaso mais frágil, honrando-as como co-herdeiras do dom da vida, para que não sejam interrompidas vossas orações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Finalmente, todos vós, tende a mesma forma de pensar, mostrando compaixão, amor fraternal, sendo misericordiosos e humildes;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'não pagueis mal por mal ou insulto por insulto; mas, pelo contrário, abençoai, porque para isso fostes chamados, a fim de receberdes a bênção como herança.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Aquele que quer amar a vida e ver dias bons deve refrear a sua língua do mal e seus lábios de falar enganosamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Afastai-vos do mal e fazei o bem. Procurai a paz e empenhai-vos por alcançá-la.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Os olhos do Senhor contemplam os justos e Seus ouvidos ouvem seus pedidos; mas o rosto do Senhor é contra os que fazem o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Quem vos prejudicará, se fordes zelosos do bem?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Porém, se sofrerdes por causa da justiça, sereis bem-aventurados. Não temais suas ameaças, nem fiqueis alarmados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Antes, santificai a Cristo, como Senhor, em vossos corações, sempre prontos para responder a todos os que vos perguntarem a razão da vossa confiança em Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Fazei isto com mansidão e respeito, tendo boa consciência, a fim de que as pessoas que caluniam e insultam a vossa boa conduta em Cristo, fiquem envergonhadas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'pois é melhor sofrer fazendo o bem, se esta for a vontade de Deus, do que fazendo o mal.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Porque Cristo também sofreu, pelos pecados, uma única vez. Aquele que é justo sofreu pelos injustos, para vos levar a Deus. Ele foi morto na carne, mas ressuscitou no Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Pelo Espírito foi e proclamou aos espíritos em prisão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'que foram desobedientes, quando a longanimidade de Deus aguardava, nos dias de Noé, enquanto se construía a arca, na qual poucas, isto é, oito pessoas foram salvas por meio das águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Isso, prefigurando o batismo, agora também vos salva, não pela remoção da impureza da carne, mas pela promessa de uma boa consciência para com Deus, pela ressurreição de Jesus Cristo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'que subiu ao céu e está à direita de Deus, a Quem devem se submeter anjos, autoridades e poderes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Portanto uma vez que Cristo sofreu na carne, armai-vos com a mesma convicção: aquele que sofreu na carne deixou o pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'Consequentemente, tal pessoa, pelo resto de seus dias na carne, não mais viverá para os desejos dos homens, mas para a vontade de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Porque basta o tempo que passastes praticando o que os gentios queriam fazer: sensualidade, paixão, bebedeiras, banquetes, orgias, e idolatrias abomináveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Eles acham estranho que não vos junteis a eles ao mesmo excesso de devassidão, por isso, eles falam mal de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Mas disto eles prestarão contas Àquele que está pronto para julgar os vivos e os mortos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Para este propósito, o Evangelho foi também pregado para os mortos, para que, embora julgados segundo os homens quando na carne, vivam no Espírito, segundo Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'O fim de todas as coisas está próximo. Portanto sede sensatos e sóbrios em vossos pensamentos por causa das vossas orações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Antes de todas as coisas, tende amor fervoroso uns pelos outros, porque o amor cobre uma multidão de pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Sede hospitaleiros uns para com os outros, sem murmuração.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Conforme o dom que cada um de vós recebeu, usai-o para servir uns aos outros, como bons administradores da multiforme graça de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Se alguém fala, fale como quem transmite a Palavra de Deus; se alguém serve, sirva com a força que Deus lhe dá; assim, em todas as coisas, Deus seja glorificado por meio de Jesus Cristo, a quem pertence a glória e o poder pelos séculos dos séculos. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Amados, não estranheis a provação que vem como fogo para testá-los, como se alguma coisa estranha estivesse acontecendo a vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Pelo contrário, por mais que experimenteis os sofrimentos de Cristo, alegrai-vos, para que também vos alegreis e exulteis na revelação de Sua Glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Se sois insultados por causa do nome de Cristo, vós sois abençoados, porque sobre vós está repousando o Espírito da glória, o Espírito de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Todavia, que ninguém sofra como assassino, ladrão, malfeitor, ou como quem se intromete em negócios alheios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Mas se alguém sofrer como um cristão, não se envergonhe, porém glorifique a Deus por ter esse nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Porque é o tempo de começar o juizo a partir da casa de Deus. E se isso começa conosco, qual será o fim daqueles que não obedecem o Evangelho de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'E se \"é com dificuldades que o justo é salvo, em que situação ficará o ímpio pecador?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Portanto aqueles que sofrem de acordo com a vontade de Deus, confiem suas almas ao fiel Criador, praticando o bem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Exorto os presbíteros entre vós, eu, também um presbítero e testemunha dos sofrimentos de Cristo e participante da glória que será revelada:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Cuidai do rebanho de Deus que está entre vós. Apascentai-o, não por dever, mas voluntariamente, de acordo com a vontade de Deus; não por ganância, mas de bom grado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Não atueis como dominadores sobre as pessoas que estão sob o vosso cuidado, mas sede exemplo para o rebanho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Quando o Supremo Pastor for revelado, recebereis uma gloriosa coroa incorruptível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Da mesma forma, vós, jovens, submetei-vos aos mais velhos. Todos vós, revesti-vos com humildade e sirvais uns aos outros, porque Deus resiste aos soberbos, mas dá graça aos humildes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Portanto humilhai-vos debaixo da poderosa mão de Deus; assim, Ele vos exaltará no tempo certo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Lançai toda a vossa ansiedade sobre Ele, porque Ele tem cuidado de vós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Sede sóbrios e vigilantes. Vosso adversário, o diabo, como um leão que ruge, ronda, procurando alguém para devorar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Resisti-lhe, firmes na fé, sabendo que vossos irmãos que estão no mundo estão passando pelos mesmos sofrimentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Depois de sofrerdes por um pouco de tempo, o Deus de toda a graça, que vos chamou para Sua eterna glória em Cristo, vos aperfeiçoará, vos firmará e vos fortalecerá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'A Ele seja o domínio para sempre e sempre. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Por meio de Silvano, que considero como fiel irmão, eu vos escrevi brevemente, exortando-vos e testificando que isto é a verdadeira graça de Deus, na qual estais firmes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'A comunidade dos eleitos que está em Babilônia vos saúda, assim como meu filho Marcos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Saudai-vos uns aos outros com beijo de santo amor. Paz seja com todos vós que estais em Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simão Pedro, servo e apóstolo de Jesus Cristo, àqueles que receberam a mesma preciosa fé como nós recebemos, fé na justiça do nosso Deus e Salvador Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Que a graça e a paz vos sejam multiplicadas no conhecimento de Deus e de Jesus nosso Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'De fato, todas as coisas concernentes à vida e à piedade nos foram dadas pelo poder divino, mediante o conhecimento de Deus, que nos chamou por Sua própria glória e virtude.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Por meio das quais, Ele nos deu grandes e preciosas promessas, para que vos torneis participantes da natureza divina, bem como escapeis da corrupção que está no mundo por causa dos desejos perversos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Por essa razão, esforçai-vos por acrescentar à vossa fé a virtude; à virtude, o conhecimento;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'ao conhecimento, o domínio próprio; ao domínio próprio, a perseverança; e à perseverança, a piedade;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'e à piedade, a fraternidade; e à fraternidade, o amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Se essas coisas existirem e aumentarem em vós, farão com que não sejais improdutivos e infrutíferos no conhecimento de nosso Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Mas, em quem essas coisas não estão presentes, é cego, vendo apenas o que está perto. Ele esqueceu da purificação dos seus pecados de outrora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Portanto, irmãos, esforçai-vos para fazer firme o vosso chamado e eleição. Se fizerdes essas coisas, não tropeçareis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Deste modo, o acesso ao Reino eterno de nosso Senhor e Salvador Jesus Cristo vos será ricamente concedido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Por isso, estarei sempre pronto para relembrar-vos dessas coisas, embora vós as conheçais, e estais firmes na presente verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Considero correto para mim despertá-los e lembrá-los sobre estas coisas, enquanto estou neste tabernáculo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Porque eu sei que em breve deixarei meu tabernáculo, como nosso Senhor Jesus Cristo me revelou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Me esforçarei para que sempre vos lembreis destas coisas depois da minha partida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Porque nós não seguimos fábulas engenhosamente inventadas quando vos falamos sobre o poder e a vinda do nosso Senhor Jesus Cristo, mas fomos testemunhas oculares da Sua majestade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Pois, Ele recebeu de Deus Pai, honra e glória, quando uma voz vinda da Sua suprema glória disse: \"Este é meu Filho amado, em quem me comprazo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Nós ouvimos essa voz que veio do céu, enquanto estávamos com Ele no monte santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Nós temos firme esta palavra profética, para qual vós fazeis bem em atender. Isto é, como uma lâmpada brilhando colocada na escuridão até o amanhecer e a estrela da manhã se levante em vossos corações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Sabendo primeiramente isto, que nenhuma profecia da Escritura vem de interpretação própria.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Porque nenhuma profecia jamais veio da vontade do homem, mas por homens impelidos pelo Espírito Santo que falaram da parte de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Assim como falsos profetas surgiram entre o povo, falsos mestres também surgirão entre vós. Eles sorrateiramente trarão consigo heresias destruidoras e negarão o Senhor que os resgatou, trazendo rápida destruição sobre si mesmos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Muitos seguirão suas vidas de libertinagem e, por meio deles, o caminho da verdade será difamado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Movidos por avareza, eles vos explorarão com palavras enganosas. A condenação contra eles não vai demorar muito e a sua destruição não tarda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Pois, Deus não poupou os anjos que pecaram, mas, os lançou fora ao Tártaro, para serem mantidos em correntes de escuridão até o julgamento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Também não poupou o mundo antigo, mas preservou Noé, que era um mensageiro da justiça, com outros sete, quando trouxe um dilúvio sobre o mundo dos ímpios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Deus também reduziu as cidades de Sodoma e Gomorra a cinzas e as condenou à destruição, como um exemplo do que vai acontecer aos ímpios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Mas, resgatou o justo Ló, que era constantemente atribulado pelo comportamento de homens devassos e sem lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Pois esse homem justo, que vivia entre eles, dia após dia, era atormentado em sua alma justa pelo que via e ouvia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Portanto, o Senhor sabe como resgatar os homens piedosos das provações, bem como prender os homens injustos para punição no dia do juízo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Isso é especialmente verdadeiro para aqueles que continuam nos corruptos desejos carnais e desprezam a autoridade. Eles são atrevidos e orgulhosos, não tendo receio de blasfemar contra os seres celestiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Os anjos, embora sejam mais fortes e poderosos, não proferem juízo infamatório contra os ímpios diante do Senhor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Mas esses, como animais irracionais, são destinados por natureza à prisão e à destruição. Eles não conhecem o que insultam e em sua corrupção serão destruídos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'e receberão a recompensa pelas suas transgressões. Eles consideram que a imoralidade em pleno dia é um prazer; são como nódoas e manchas, e deleitam-se em seus enganos enquanto se banqueteiam convosco.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Eles têm olhos cheios de adultério, nunca se satisfazem com o pecado, seduzem ao erro almas vulneráveis e têm seus corações exercitados na avareza; são filhos da maldição!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Eles abandonaram o caminho correto, se extraviaram e seguiram o caminho de Balaão, filho de Beor, que amou a recompensa injusta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Mas, ele recebeu a repreensão por sua própria transgressão; um mudo animal de carga, falando com voz humana, refreou a loucura do profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Esses tais são como fontes sem água, como nuvens levadas por um temporal. Densas trevas estão reservadas para eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Falam com vã arrogância, atraem pessoas por meio da imoralidade da carne e seduzem os que tentam escapar daqueles que vivem no erro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Prometem-lhes liberdade, mas eles mesmos são escravos da corrupção, pois cada um é escravo daquele que o domina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Portanto, aqueles que fugiram das corrupções do mundo por meio do conhecimento do Senhor e Salvador Jesus Cristo e, então, retornam àquelas corrupções novamente, o último estado deles é pior do que o primeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Seria melhor para eles não terem conhecido o caminho da justiça, do que, conhecê-lo e darem as costas ao santo mandamento que lhes fora entregue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Este provérbio é verdadeiro para eles: \"Um cão retorna ao seu próprio vômito; e \"Uma porca lavada volta a rolar na lama\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Amados, esta é a segunda carta que vos escrevo, em ambas procuro despertar com lembranças a vossa mente sincera,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'para vos lembrardes das palavras previamente faladas pelos santos profetas, e do mandamento do Senhor e Salvador ensinado por vossos apóstolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Saibam que, primeiramente virão os zombadores nos últimos dias, zombando de vós, andando de acordo com os seus próprios desejos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'e dizendo: \"Onde está a promessa da vinda Dele? Pois desde que os antepassados morreram, todas as coisas permanecem como desde o princípio da criação\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Eles propositalmente esquecem que há muito tempo, houve céus e terra, a qual surgiu da água e através da água pela Palavra de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'e que mediante a Palavra Dele, o mundo daquele tempo foi destruído sendo inundado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Pela a mesma Palavra, os céus e a terra foram reservados para o fogo, sendo guardados para o dia do juízo e destruição das pessoas ímpias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Amados, não ignoreis que um dia para o Senhor é como mil anos, e mil anos como um dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'O Senhor não demora em cumprir o que prometeu, como julgam alguns; ao contrário, Ele é paciente para convosco, não desejando que ninguém pereça, mas que todos cheguem ao arrependimento.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'No entanto, o dia do Senhor virá como um ladrão. Os céus desaparecerão com grande estrondo. Os elementos serão dissolvidos pelo fogo, a terra e as obras sobre ela serão reveladas..');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Uma vez que, dessa forma, todas essas coisas serão destruídas que tipo de pessoas deveis ser? Vós deveis viver de maneira santa e piedosa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'esperando e apressando a vinda do dia de Deus, quando os céus serão destruídos pelo fogo e os elementos se derreterão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Contudo, conforme Ele prometeu, esperamos novos céus e nova terra, nos quais habita a justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Portanto, amados, esperando estas coisas, empenhai-vos para serdes encontrados por Ele, imaculados, sem culpa e em paz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'E considerai a paciência do nosso Senhor para a salvação, assim como nosso amado irmão Paulo vos escreveu, de acordo com a sabedoria que foi dada a ele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Paulo fala destas coisas em todas as suas cartas, nas quais há certas coisas difíceis de entender, as quais homens sem instrução e sem firmeza distorcem, como também fazem com as demais Escrituras, para a própria destruição deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Portanto, amados, uma vez sabendo essas coisas, guardai-vos para que não sejais arrastados pelo erro de pessoas sem lei e percais a vossa própria firmeza;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'mas, crescei na graça e conhecimento do nosso Senhor e Salvador Jesus Cristo. A Ele seja a glória, agora e para sempre. Amém!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'O que era desde o princípio, o que nós ouvimos, o que vimos com nossos olhos, o que contemplamos e o que nossas mãos apalparam, trata-se da Palavra da vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'Pois a vida foi manifestada, e nós a vimos, e dela testemunhamos. Declaramos a vós a vida eterna, que estava com o Pai e foi manifestada a nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'O que temos visto e ouvido declaramos também a vós, para que também tenhais comunhão conosco, e a nossa comunhão é com Deus e com Seu Filho, Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'E estas coisas que vos escrevemos são para que a nossa alegria seja completa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Esta é a Mensagem que ouvimos Dele e anunciamos a vós: Deus é luz, e Nele não há trevas nenhumas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Se dizemos que temos comunhão com Ele e andamos nas trevas, nós mentimos e não praticamos a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Mas se andamos na luz como Ele está na luz, temos comunhão uns com os outros e o sangue de Jesus, Seu Filho, nos limpa de todo pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Se dizemos que não temos pecado, enganamos a nós mesmos e a verdade não está em nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Mas, se confessarmos nossos pecados, Ele é Fiel e Justo para perdoar nossos pecados e nos purificar de toda injustiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Se dissermos que não temos cometido pecado, nós O fazemos mentiroso e a Sua palavra não está em nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Meus filhinhos, eu vos escrevo estas coisas para que não pequeis. Mas, se alguém pecar, temos um Advogado junto ao Pai, Jesus Cristo, o Justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Ele é a propiciação pelos nossos pecados, e não apenas pelos nossos, mas também pelos de todo o mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Nós sabemos que O conhecemos, se guardarmos Seus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Aquele que diz: \"Eu conheço a Deus\", mas não guarda Seus mandamentos, é um mentiroso, e a verdade não está nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Mas o que guarda Sua Palavra, verdadeiramente o amor de Deus tem sido aperfeiçoado nessa pessoa. Por meio disso, sabemos que estamos Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Aquele que diz que permanece em Deus, deve também andar como Jesus Cristo andou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Amados, não vos escrevo um novo mandamento, mas um mandamento antigo que tivestes desde o início. O mandamento antigo é a Palavra que ouvistes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'No entanto, vos escrevo um novo mandamento, que é verdadeiro em Cristo e em vós, porque a escuridão está passando, e a verdadeira luz já está brilhando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Aquele que diz que está na luz e odeia seu irmão, ainda está na escuridão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Aquele que ama seu irmão permanece na luz, e nele não há ocasião para tropeço.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Mas aquele que odeia seu irmão está na escuridão e nela anda; ele não sabe para onde está indo, porque a escuridão cegou seus olhos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Filhinhos, eu vos escrevo porque vossos pecados são perdoados por causa do Seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Pais, eu vos escrevo porque tendes conhecido Aquele que é desde o princípio. Jovens, eu vos escrevo porque tendes vencido o maligno. Filhinhos, eu vos escrevi porque tendes conhecido o Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Pais, eu vos escrevi porque tendes conhecido Aquele que é desde o princípio. Jovens, eu vos escrevi porque sois fortes, e a palavra de Deus permanece em vós, e tendes vencido o maligno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Não ameis o mundo, nem as coisas que nele estão. Se alguém ama o mundo, o amor do Pai não está nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Porque tudo que está no mundo, o desejo da carne, o desejo dos olhos, e a soberba da vida, não é do Pai mas é do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'O mundo e seus desejos passam. Mas aquele que faz a vontade de Deus permanece para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Filhinhos, esta é a última hora. Como ouvistes que o anticristo vem, agora mesmo muitos anticristos têm surgido, pelo que sabemos que esta é a última hora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Eles saíram de nosso meio, mas não eram dos nossos. Porque, se fossem dos nossos, teriam continuado conosco, mas eles saíram, o que mostra não serem dos nossos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Mas tendes unção que vem do Santo, e todos sabeis a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Vos escrevi não porque ignorais a verdade, mas porque a conheceis e porque nenhuma mentira procede da verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Quem é o mentiroso senão aquele que nega que Jesus é o Cristo? Eis o anticristo, o que nega o Pai e o Filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Todo aquele que nega o Filho, não tem o Pai. Aquele que reconhece o Filho tem também o Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Quanto a vós, cuidai para que permaneça em vós o que ouvistes desde o princípio. Se permanecer em vós aquilo que ouvistes desde o princípio, também permanecereis no Filho e no Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'E esta é a promessa que Ele nos fez: a vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Essas coisas vos escrevi a respeito daqueles que vos querem desviar da verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'E, quanto a vós, a unção que Dele recebestes permanece em vós, e não tendes necessidade de que alguém vos ensine. Mas, como Sua unção vos ensina a respeito de todas as coisas, e é verdade e não é uma mentira, assim como ela vos ensinou, permanecei Nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'E agora, filhinhos, permanecei Nele para que, quando Ele se manifestar, tenhamos plena confiança e não sejamos envergonhados perante Ele em Sua vinda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Se sabeis que Ele é Justo, sabeis que todo aquele que pratica a justiça é nascido Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Vede que tipo de amor o Pai nos concedeu, para que fôssemos chamados filhos de Deus. Por esta razão, o mundo não nos conhece, porque não O conheceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Amados, agora somos filhos de Deus, mas ainda não foi revelado o que iremos ser. Porém sabemos que, quando Cristo aparecer, nós seremos como Ele, porque O veremos como Ele é.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'E todo aquele que Nele tem essa esperança purifique-se como Ele é Puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Todo aquele que comete pecado transgride a Lei, pois o pecado é a transgressão da Lei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Também sabeis que Cristo foi revelado com o propósito de tirar os pecados. E Nele não há pecado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Ninguém que permanece Nele continua pecando; qualquer que continua pecando não O viu nem O conheceu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Queridos filhos, não deixeis que ninguém vos desvie. Aquele que pratica a justiça é justo, como Cristo é Justo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Aquele que pratica o pecado é do diabo, porque o diabo peca desde o princípio. Por esta razão, o Filho de Deus foi revelado, para que Ele possa destruir as obras do diabo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Aquele que é nascido de Deus não pratica o pecado, pois a semente de Deus permanece nele. E ele não pode continuar no pecado, porque ele é nascido de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Nisto os filhos de Deus e os filhos do diabo são revelados, quem não pratica a justiça não é de Deus, nem aquele que não ama seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Porque esta é a mensagem que tendes ouvido desde o princípio: que devemos amar uns aos outros,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'não como Caim, que era do maligno e matou seu irmão. E por que o matou? Porque suas obras eram más, e as de seu irmão eram justas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Não vos admireis, meus irmãos, se o mundo vos odeia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Nós sabemos que passamos da morte para a vida, porque amamos os irmãos. Aquele que não ama permanece na morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Aquele que odeia seu irmão é assassino, e sabeis que nenhum assassino tem vida eterna permanente em si mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Por isso nós conhecemos o amor, porque Cristo deu a Sua vida por nós. Nós também devemos dar as nossas vidas pelos nossos irmãos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Mas qualquer que tiver bens materiais e, vendo seu irmão com necessidades, fechar o seu coração para ele, como permanecerá nele o amor de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Meus queridos filhos, não amemos só de palavra nem de língua, mas em ações e em verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Por isso sabemos que somos da verdade e asseguramos nossos corações diante Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Porque, se nossos corações nos condenam, Deus é maior que nosso coração e sabe todas as coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Amados, se nossos corações não nos condenarem, temos confiança diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'E tudo o que pedimos nós recebemos Dele, porque guardamos os Seus mandamentos e fazemos as coisas que Lhe agradam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'E este é o Seu mandamento: que creiamos no nome do Seu Filho, Jesus Cristo, e nos amemos uns aos outros, assim como Ele nos ordenou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Aquele que guarda os mandamentos permanece em Deus, e Deus permanece nele. E, por isso, nós sabemos que Ele permanece em nós, pelo Espírito que Ele nos deu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Amados, não creiais em qualquer espírito, mas provai os espíritos para ver se eles vêm de Deus, porque muitos falsos profetas têm saído pelo mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Por meio disto reconheceis o Espírito de Deus: todo espírito que confessa que Jesus Cristo veio em carne é de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'e todo espírito que não confessa a Jesus não é de Deus, mas é o espírito do anticristo, o qual tendes ouvido que vem, e agora já está no mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Queridos filhos, vós sois de Deus, e já os tendes vencido, porque Aquele que está em vós é maior do que o que está no mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Aqueles espíritos são do mundo, portanto o que eles dizem é do mundo, e o mundo os ouve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Nós somos da parte de Deus. Aquele que conhece a Deus nos ouve, quem não é de Deus não nos ouve. Assim é que conhecemos o Espírito da verdade e o espírito do erro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Amados, amemos uns aos outros, porque o amor é de Deus, e todo aquele que ama é nascido de Deus e conhece a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Aquele que não ama não conhece a Deus, porque Deus é amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Nisto o amor de Deus se manifestou entre nós: em haver Deus enviado Seu Filho Unigênito ao mundo, para vivermos por meio Dele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'E nisto está o amor: não fomos nós que amamos a Deus, mas Ele que nos amou, e enviou Seu Filho como propiciação pelos nossos pecados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Amados, se Deus nos amou assim, nós também devemos amar uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Ninguém jamais viu a Deus. Se nós amarmos uns aos outros, Deus permanece em nós, e Seu amor é aperfeiçoado em nós.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Nisto nós sabemos que permanecemos Nele e Ele em nós, porque Ele tem nos dado do Seu Espírito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'E nós temos visto e testemunhado que o Pai enviou Seu Filho como Salvador do mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Qualquer um que confesse que Jesus é o Filho de Deus, Deus permanece nele, e ele em Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'E nós conhecemos e cremos no amor que Deus tem por nós. Deus é amor, e quem permanece em amor permanece em Deus, e Deus nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'E esse amor tem sido aperfeiçoado em nós, para que tenhamos confiança no dia do julgamento, porque qual Ele é assim também somos nós neste mundo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'No amor não há medo, pelo contrário, o perfeito amor lança fora o medo, porque o medo envolve punição, e quem tem medo não foi aperfeiçoado no amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Nós amamos porque Deus nos amou primeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Se alguém diz: \"Eu amo a Deus\", mas odeia seu irmão, ele é mentiroso, pois aquele que não ama seu irmão, a quem vê, não pode amar a Deus, a quem não vê.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'E nós temos este mandamento da parte Dele, que aquele que ama a Deus deve amar também seu irmão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Aquele que crê que Jesus é o Cristo é nascido de Deus. E todo aquele que ama quem O gerou, ama também quem Dele é nascido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Nós sabemos que amamos os filhos de Deus por meio disto: quando amamos a Deus e cumprimos os Seus mandamentos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Porque isto é o amor a Deus: que guardemos os Seus mandamentos. E os Seus mandamentos não são penosos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'porque todo aquele que é nascido de Deus vence o mundo. E esta é a vitória que vence o mundo: a nossa fé.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Quem é que vence o mundo, senão o que crê que Jesus é o Filho de Deus?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Este é Aquele que veio pela água e pelo sangue, Jesus Cristo. Ele veio não somente pela água, mas pela água e pelo sangue. E quem testifica é o Espírito. Porque o Espírito é a verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Porque são três os que testificam:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'o Espírito, a água e o sangue. Estes três concordam entre si.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Se nós recebemos o testemunho dos homens, o testemunho de Deus é maior. Porque este é o testemunho de Deus, que Ele deu acerca de Seu Filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Aquele que crê no Filho de Deus tem em si mesmo esse testemunho. Aquele que não crê em Deus O faz mentiroso, porque não tem crido no testemunho que Deus tem dado em relação ao seu Filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'E o testemunho é este: que Deus nos deu a vida eterna, e esta vida está no Seu Filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Quem tem o Filho tem a vida. Quem não tem o Filho de Deus não tem a vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Essas coisas vos tenho escrito para que saibais que tendes a vida eterna, vós que credes no nome do Filho de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Esta é a confiança que temos diante Dele: se pedirmos qualquer coisa segundo a Sua vontade, Ele nos ouve.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'E, se sabemos que Ele nos ouve, quanto ao que Lhe pedimos, sabemos que temos o que Lhe pedimos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Se alguém vir seu irmão cometendo pecado que não seja para a morte, ele deve orar, e Deus lhe dará vida. Refiro-me àqueles cujo pecado não é para morte. Existe pecado para a morte; não é a respeito deste que digo que ore.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Toda injustiça é pecado, mas existe pecado que não é para a morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Sabemos que todo aquele que é nascido de Deus não peca continuamente. Mas Aquele que foi gerado de Deus guarda essa pessoa, e o maligno não lhe toca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Sabemos que somos de Deus, e que o mundo inteiro jaz no maligno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Mas sabemos que o Filho de Deus veio e nos tem dado entendimento, para conhecermos O verdadeiro e que estamos Nele, que é a Verdade, em Seu Filho, Jesus Cristo. Este é o verdadeiro Deus e a vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Filhinhos, guardai-vos dos ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'O presbítero à senhora eleita e a seus filhos, a quem amo na verdade, e não somente eu, mas também todos aqueles que conhecem a verdade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'por causa da verdade que permanece em nós e que estará conosco eternamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Graça, misericórdia e paz da parte de Deus Pai e de Jesus Cristo, o Filho de Deus, serão conosco em verdade e amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Eu tenho grande alegria por ter encontrado alguns dos teus filhos andando na verdade, assim como nós recebemos este mandamento do Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'E agora peço-te, senhora, não como se eu escrevesse um novo mandamento, mas o mesmo que tivemos desde o início: que nos amássemos uns aos outros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'E isto é o amor: que nós vivamos de acordo com Seus mandamentos. Este é o mandamento, como vós ouvistes desde o princípio, e vós deveis andar nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Pois muitos enganadores saíram pelo mundo e estes não confessam que Jesus Cristo veio em carne. Este é o enganador e o anticristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Acautelai-vos para não perderdes as coisas pelas quais todos nós trabalhamos, mas para que possais receber a recompensa completa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Qualquer um que avança e não permanece no ensino de Cristo, não tem Deus. Aquele que permanece no ensino, tem os dois: o Pai e o Filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Se alguém vem a vós e não traz este ensino, não o recebais em vossa casa e nem o cumprimenteis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Pois aquele que o cumprimenta participa de suas obras más.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Tenho muitas coisas para vos escrever, porém não desejei fazê-lo com papel e tinta. Mas tenho esperança de ir a vós e falar-vos face a face, para que a nossa alegria seja completa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Os filhos de tua irmã eleita enviam saudações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'O presbítero ao amado Gaio, a quem eu amo em verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Amado, oro para que prosperes em todas as coisas, e tua saúde esteja tão próspera quanto a tua alma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Pois alegrei-me muito quando vieram irmãos e testemunharam da tua verdade, de como andas na verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Eu não tenho alegria maior do que esta: ouvir que meus filhos andam na verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Amado, tu praticas a fidelidade sempre que trabalhas a favor dos irmãos, mesmo quando são estrangeiros,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'os quais têm dado testemunho do teu amor perante a igreja. Farás bem, enviando-os para a sua viagem de modo digno de Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'pois foi por causa do Nome que eles saíram, sem nada receber dos gentios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Devemos, então, acolher os irmãos para que sejamos cooperadores da verdade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Eu escrevi algo para a congregação, mas Diótrefes, que ama ser o primeiro entre eles, não nos recebe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Por isso, se eu vier, recordarei das obras que ele pratica, pois ele propaga palavras más contra nós. E, não satisfeito com essas ações, o próprio Diótrefes não recebe os irmãos, e ainda proíbe aqueles que desejam fazê-lo, lançando-os fora da congregação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Amado, não imites o mal, mas o bem. Aquele que pratica o bem é de Deus; aquele que pratica o mal não viu a Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Quanto a Demétrio, este recebe bom testemunho de todos, até da própria verdade. Nós também damos testemunho, e tu sabes que nosso testemunho é verdadeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Eu tinha muitas coisas para te escrever, porém não desejo fazê-lo com pena e tinta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Mas espero te ver em breve, e falaremos face a face.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Paz seja contigo. Os amigos te saúdam. Saúdam os amigos, nome por nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, servo de Jesus Cristo e irmão de Tiago, aos que foram chamados, amados em Deus, o Pai, e guardados por Jesus Cristo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'que a misericórdia, a paz e o amor vos sejam multiplicados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Amados, enquanto eu me esforçava para vos escrever sobre a salvação que nos é comum, tive que me corresponder convosco para exortar-vos a batalhardes para permanecerdes na fé que, de uma vez por todas, foi dada aos santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Pois certos homens se introduziram secretamente com dissimulação. Esses são homens cuja condenação estava escrita há muito tempo; homens ímpios, que perverteram a graça do nosso Deus em imoralidade sexual e rejeitaram nosso único Mestre e Senhor, Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Agora tenho que lembrar-vos, embora uma vez soubestes de tudo isso, que o Senhor salvou um povo, tirando-o da terra do Egito, mas depois Ele destruiu aqueles que não creram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'E, quanto aos anjos que não mantiveram sua própria posição de autoridade, mas abandonaram seu lugar de habitação, Deus os tem mantido em algemas eternas na escuridão para o julgamento do grande Dia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'De modo semelhante, Sodoma, Gomorra e as cidades ao redor delas, que se prostituíram e perseguiram desejos contra a natureza, foram postas para exemplo, sofrendo a punição do fogo eterno.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Semelhantemente, esses homens contaminam seus corpos em seus sonhos, rejeitam a autoridade e blasfemam contra os seres celestiais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Mas, mesmo o arcanjo Miguel, quando se opôs ao diabo disputando o corpo de Moisés, não ousou falar contra ele palavras de condenação ou insulto, ao invés disso, afirmou: \"Que o Senhor te repreenda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Porém esses homens insultam aquilo que não entendem. E aquilo que eles compreendem por instinto, como animais irracionais, nessas coisas são destruídos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Ai deles! Pois têm andado pelos caminhos de Caim, têm se lançado no erro de Balaão por ganância e perecido na rebelião de Coré.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Esses homens são como rochas ocultas em seus banquetes de amor. Eles festejam sem escrúpulos, apascentando a si mesmos; são nuvens sem água, carregadas pelo vento; árvores de outono sem frutos, duas vezes mortas, arrancadas pelas raízes;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'ondas violentas do mar, espumando sua própria vergonha; estrelas errantes, para as quais a escuridão das trevas tem sido reservada para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'E, sobre esses homens, Enoque, o sétimo da linhagem de Adão, previu, dizendo: \"Olhem, o Senhor está vindo com dez mil de Seus santos');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'para executar julgamento sobre todas as pessoas e para convencer todo ímpio de todo seu trabalho de impiedade, que eles têm cometido de maneira ímpia, e de todas as duras coisas que os ímpios pecadores têm profetizado contra Ele\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Esses homens são murmuradores, queixosos, lançam-se em seus desejos pecaminosos, são escandalosos, orgulhosos, adulam certas pessoas com o intuito de ganhar vantagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'No entanto, vós, amados, lembrai-vos das palavras que foram ditas no passado pelos apóstolos do nosso Senhor Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Eles vos disseram: \"Nos últimos tempos, haverá escarnecedores que andarão segundo seus próprios desejos ímpios\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Esses homens são os que causarão divisões; são mundanos e não possuem o Espírito Santo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Porém vós, amados, edificando-vos na vossa santíssima fé e orando no Espírito Santo,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'guardai -vos no amor de Deus, esperando pela misericórdia do nosso Senhor Jesus Cristo para vida eterna.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Tende compaixão dos que estão em dúvida;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'e a outros salvai arrebatando-os do fogo; e, para com outros, tende misericórdia com temor, detestando até a roupa manchada pela carne.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Então, Àquele que é capaz de manter-vos fora do tropeço e de colocar-vos atrás da presença de Sua glória sem mácula, em excessiva alegria;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'ao único Deus nosso Salvador, através de Jesus Cristo nosso Senhor, seja a glória, majestade, domínio e autoridade, antes de todos os tempos, agora e para sempre. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Esta é a revelação de Jesus Cristo, a qual Deus Lhe deu para mostrar a Seus servos o que deve ocorrer em breve. Ele a fez conhecida ao enviar Seu anjo a Seu servo João.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'João testificou de tudo o que viu sobre a palavra de Deus e o testemunho dado sobre Jesus Cristo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Bem-aventurado é aquele que lê e aqueles que ouvem as palavras desta profecia e obedecem ao que está escrito nelas, porque o tempo está próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'João, às sete igrejas na Ásia: Que a graça seja convosco e a paz Daquele que é, e que era, e que há de vir, e dos sete Espíritos que estão diante do Seu trono,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'e de Jesus Cristo, que é a Testemunha Fiel, o Primogênito dentre os mortos, e o Soberano dos reis da terra. Àquele que nos ama e nos libertou de nossos pecados por Seu sangue,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'e fez de nós um reino, sacerdotes para Seu Deus e Pai, a Ele seja a glória e o poder para sempre e sempre. Amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Eis que Ele está vindo com as nuvens e todo olho O verá, incluindo aqueles que O traspassaram. E todas as tribos da Terra se lamentarão sobre Ele. Sim, amém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, '\"Eu sou o Alfa e o Ômega,\" diz o Senhor Deus, \"Aquele que é, e que era, e que há de vir, o Todo-Poderoso.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Eu, João, vosso irmão, aquele que compartilha convosco nos sofrimentos e no reino, paciente na perseverança em Jesus, estava na ilha chamada Patmos, por causa da palavra de Deus e do testemunho de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Eu estava no Espírito, no dia do Senhor. Atrás de mim, eu ouvi uma grande voz como uma trombeta');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'que dizia: \"Escreve em um livro o que vês, e envia-o às sete igrejas: Éfeso, Esmirna, Pérgamo, Tiatira, Sardes, Filadélfia e Laodiceia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Virei-me para ver de quem era a voz que estava falando comigo e, quando me virei, vi sete candeeiros de ouro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'No meio dos candeeiros, havia um como o Filho do Homem que vestia um longo manto, que Lhe chegava aos pés, e um cinto de ouro ao redor de Seu peito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Sua cabeça e cabelo eram brancos como a lã e tão brancos como a neve; e Seus olhos, como chamas de fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Seus pés, como de bronze polido, bronze esse que foi refinado na fornalha; e Sua voz, como o som de muitas águas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Na Sua mão direita, Ele tinha sete estrelas e, saindo de Sua boca, havia uma espada afiada de dois gumes. Sua face era brilhante como o Sol no seu mais forte brilho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Quando O vi, caí aos Seus pés como um homem morto. Ele colocou Sua mão direita sobre mim e disse: \"Não tenhas medo. Eu sou o Primeiro e o Último,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'Aquele que vive. Estive morto, mas eis que Eu vivo para sempre! E tenho as chaves da morte e do Hades.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Portanto escreve o que tens visto, o que é agora, e o que acontecerá depois disso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Quanto ao mistério sobre as sete estrelas que viste em Minha mão direita e os sete candeeiros de ouro, as sete estrelas são os anjos das sete igrejas, e os sete candeeiros são as sete igrejas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Ao anjo da igreja em Éfeso escreve: \'Estas são as palavras Daquele que sustenta as sete estrelas em Sua mão direita e que anda entre os sete candeeiros de ouro:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Eu conheço o que tens feito, o teu trabalho árduo e a tua perseverança com paciência. Sei que não podes tolerar homens maus e que puseste à prova aqueles que afirmam por si mesmos serem apóstolos, mas não o são, e os achaste falsos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Eu sei que tens perseverado com paciência, tens passado por muitas provações por causa do Meu nome e não tens desfalecido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Porém tenho contra ti que deixaste o teu primeiro amor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Portanto lembra-te de onde caíste, arrepende-te e pratica as primeiras obras. A não ser que te arrependas, virei a ti e removerei o teu candeeiro do seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Tens, contudo, que odeias as obras dos Nicolaítas, as quais Eu também odeio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Quem tem ouvidos ouça o que o Espírito diz às igrejas. Ao que vencer, Eu lhe darei o direito de comer da Árvore da Vida, que está no Paraíso de Deus\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, '\"Ao anjo da igreja em Esmirna escreve: \'Estas são as palavras Daquele que é o primeiro e o último, que morreu e tornou a viver:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Eu conheço tuas aflições e tua pobreza (mas tu és rico) e a blasfêmia daqueles que se dizem judeus, mas não são. Eles são sinagoga de Satanás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Não temas o que estás prestes a sofrer. Eis que o diabo está para lançar alguns de vós na prisão, para serdes provados, e sofrereis por dez dias. Sê fiel até à morte, e Eu te darei a coroa da vida\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Quem tem ouvidos ouça o que o Espírito diz às igrejas. Aquele que vencer não sofrerá o dano da segunda morte\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, '\"Ao anjo da igreja em Pérgamo escreve: \'Estas são as palavras Daquele que tem a espada afiada de dois gumes:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Eu sei onde tu habitas, que é onde está o trono de Satanás. Ainda assim, tu permaneces fiel ao Meu nome. Sei que tu não negaste a tua fé em Mim, mesmo nos dias de Antipas, minha fiel testemunha, que foi morto entre vós, onde Satanás habita.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Porém tenho algumas coisas contra ti: Alguns que seguem firmemente as doutrinas de Balaão, que ensinou Balaque a armar uma cilada diante dos filhos de Israel, para que eles comessem coisas sacrificadas a ídolos e cometessem imoralidade sexual.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Do mesmo modo, tens alguns que seguem firmemente os ensinos dos Nicolaítas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Portanto, arrepende-te! Caso contrário, Eu virei a ti sem demora e contra eles farei guerra, com a espada da minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Quem tem ouvidos ouça o que o Espírito diz às igrejas. Àquele que vencer Eu darei do maná escondido e lhe darei uma pedra branca com um novo nome escrito nela, um nome que ninguém conhece, exceto aquele que a recebe\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, '\"Ao anjo da igreja em Tiatira escreve: \'Estas são as palavras do Filho de Deus, que tem olhos como chama de fogo e os pés como bronze polido:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Eu sei o que tens feito, o teu amor, a tua fé, o teu serviço e a tua perseverança. E conheço os teus últimos feitos que são mais numerosos do que os primeiros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Porém tenho isto contra ti: Toleras a mulher Jezabel, a que se diz profetiza. Pelos seus ensinos, seduz meus servos a cometerem imoralidade sexual e a comerem alimentos sacrificados aos ídolos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'E dei-lhe tempo para que se arrependesse, mas ela não quer se arrepender de sua imoralidade.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Eis que Eu a lançarei em um leito de enfermidade, bem como em grande aflição os que cometeram adultério com ela, a menos que se arrependam das suas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Matarei seus filhos, e todas as igrejas saberão que Eu Sou Aquele que sonda os pensamentos e os corações. Darei a cada um conforme as suas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Aos demais em Tiatira, a todos os que não seguem o ensino dela e não conhecem as chamadas coisas profundas de Satanás, Eu vos digo: \'Não lançarei sobre vós mais nenhum fardo\'.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Porém deveis permanecer firmes até que Eu venha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Àquele que vencer e guardar as minhas obras até o fim Eu lhe darei autoridade sobre as nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'Ele as governará com cetro de ferro e, como vasos de barro, as quebrará em pedaços.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'Assim como Eu tenho recebido autoridade de meu Pai, Eu também lhes darei a estrela da manhã.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Aquele que tem ouvidos ouça o que o Espírito diz às igrejas\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, '\"Ao anjo da igreja em Sardes escreve: \'Estas são as palavras Daquele que tem os sete Espíritos de Deus e as sete estrelas: Conheço as tuas obras: passas por vivo e estás morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Sê vigilante e confirma o restante que estava para morrer, porque não tenho achado as tuas obras íntegras diante do meu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Portanto lembra-te do que tens recebido e ouvido; obedece e arrepende-te. E, se não vigiares, Eu virei como um ladrão, e tu não saberás a que horas virei contra ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Mas há alguns nomes em Sardes que não sujaram suas vestes. Eles andarão comigo vestidos de branco, pois são dignos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Aquele que vencer será vestido de vestes brancas e jamais apagarei seu nome do Livro da Vida. Eu confessarei seu nome diante de Meu Pai e diante dos Seus anjos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Quem tem ouvidos ouça o que o Espírito diz às igrejas\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, '\"Ao anjo da igreja em Filadélfia escreve: \'Estas são as palavras Daquele que é Santo e Verdadeiro. Ele tem as chaves de Davi, O que abre e ninguém fecha, e O que fecha e ninguém pode abrir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Eu sei o que tu tens feito. Vê que Eu tenho posto diante de ti uma porta aberta que ninguém pode fechar. Sei que tens pouca força. Mesmo assim, tens obedecido a Minha palavra e não tens negado o Meu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Eis que farei aos que pertencem à sinagoga de Satanás, aqueles que se dizem judeus e não são, mas mentem, farei que venham e se curvem diante dos teus pés e saberão que Eu te amei.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Uma vez que tens obedecido à minha ordem de suportar pacientemente, também te guardarei da hora da provação que virá sobre todo o mundo, para testar aqueles que vivem sobre a Terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Venho sem demora, conserva o que tens para que ninguém tome tua coroa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Àquele que vencer, Eu o farei uma coluna no templo de meu Deus e ele nunca sairá dali. Escreverei nele o nome do Meu Deus, o nome da cidade do Meu Deus (a nova Jerusalém, que descerá do céu, da parte do Meu Deus) e Meu novo nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Quem tem ouvidos ouça o que o Espírito diz às igrejas\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, '\"Ao anjo da igreja em Laodiceia escreve: \'Assim diz o Amém, a testemunha verdadeira e fiel, o princípio da criação de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Conheço tuas obras: não és nem frio nem quente; quem dera fosses frio ou quente!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Assim porque tu és morno, nem quente nem frio, Eu te vomitarei da minha boca.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Porque dizes: \'Sou rico, tenho muitos bens e não necessito de coisa alguma\'. E não sabes que és infeliz, miserável, pobre, cego e nu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Aconselho-te que de Mim compres ouro refinado no fogo para que te enriqueças, vestes brancas para que não seja exposta a vergonha da tua nudez, e colírio para ungires os teus olhos, a fim de que vejas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Corrijo e repreendo os que amo. Portanto, sê zeloso e arrepende-te.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Eis que estou à porta e bato. Se alguém ouvir Minha voz e abrir a porta, Eu entrarei em sua casa, cearei com ele e ele Comigo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Àquele que vencer darei o direito de sentar-se Comigo em Meu trono, assim como Eu também venci e sentei-Me com Meu Pai, em Seu trono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Quem tem ouvidos ouça o que o Espírito diz às igrejas\'\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Depois dessas coisas, eu olhei e vi que havia uma porta aberta no céu. A primeira voz que ouvi, como voz de trombeta falando comigo, disse: \"Sobe aqui e te mostrarei o que deve acontecer depois dessas coisas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Imediatamente, eu estava no Espírito e vi que havia um trono posto no céu, com alguém sentado nele.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'O que estava sentado era semelhante à pedra de jaspe e sardônio. Ao redor do trono, havia um arco-íris semelhante à esmeralda.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Ao redor do trono, havia vinte e quatro tronos e, sentados neles, havia vinte e quatro anciãos. Eles vestiam roupas brancas e tinham coroas de ouro em suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Do trono saíam relâmpagos, estrondos e barulhos de trovão. E, diante dele, sete lâmpadas queimando, que são os sete Espíritos de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'E, diante do trono, havia um mar como de vidro semelhante ao cristal. No meio e ao redor do trono, havia quatro seres viventes, cheios de olhos tanto na frente como atrás.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'O primeiro ser vivente era como um leão; o segundo ser vivente, como um bezerro; o terceiro ser vivente tinha a face como a de um homem; e o quarto ser vivente era como uma águia voando.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Os quatro seres viventes tinham seis asas e eram cheios de olhos em cima e embaixo. De dia e de noite, eles não paravam de dizer: \"Santo, Santo, Santo é o Senhor Deus Todo-Poderoso, o que era, e que é, e o que há de vir\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'E sempre que os seres viventes davam glória, honra e gratidão ao que estava sentado no trono, ao que vive por toda eternidade,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'os vinte e quatro anciãos prostravam-se diante do que estava sentado no trono. Eles adoravam ao que vive para todo sempre e lançavam suas coroas diante do trono, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, '\"Digno és, nosso Senhor e nosso Deus, de receber a glória e a honra e o poder. Por Ti todas as coisas foram criadas e, por Tua vontade, existiram e foram criadas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Então vi, na mão direita Daquele que estava sentado no trono, um rolo escrito por dentro e por fora. Este estava selado com sete selos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Vi um anjo poderoso proclamando em alta voz: \"Quem é digno de abrir o rolo e de romper os seus selos?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Ninguém no céu, nem na terra, nem debaixo da terra, estava apto para abrir ou ler o rolo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Eu chorava amargamente porque ninguém foi encontrado digno de abrir nem de ler o rolo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Mas um dos anciãos me disse: \"Não chores. Eis que o Leão da Tribo de Judá, a Raiz de Davi, venceu para abrir o rolo e seus sete selos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Vi um Cordeiro em pé, entre o trono e os quatro seres viventes e entre os anciãos. O Cordeiro parecia ter sido morto. Ele tinha sete chifres e sete olhos. Estes são os espíritos de Deus enviados sobre toda a terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Ele veio e tomou o rolo da mão direita Daquele que estava sentado no trono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Quando o Cordeiro tomou o rolo, os quatro seres viventes e os vinte e quatro anciãos prostraram-se diante Dele. Cada um deles tinha uma harpa e uma taça de ouro cheia de incenso, que são as orações dos santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Eles cantavam uma nova canção: \"Tu és digno de tomar o rolo e de abrir os seus selos, porque foste morto e, com o Teu sangue, compraste para Deus pessoas de toda tribo, língua, povo e nação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Tu os constituíste reino e sacerdotes para servirem o nosso Deus, e eles reinarão sobre a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Então olhei e ouvi o som de muitos anjos, ao redor do trono, dos seres viventes e dos anciãos, cujo número total era de milhares de milhares e de milhões de milhões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Eles falavam em alta voz: \"Digno é o Cordeiro que foi morto de receber poder, riqueza, sabedoria, força, honra, glória e louvor\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Ouvi toda criatura que estava no céu, na terra, debaixo da terra e no mar - tudo o que neles há - dizendo: \"Àquele que está sentado no trono e ao Cordeiro seja o louvor, a honra, a glória e o poder para reinar para sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Os quatro seres viventes disseram: \"Amém!\" E os anciãos prostraram-se e O adoraram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'E vi quando o Cordeiro abriu um dos sete selos, e ouvi um dos quatro seres viventes dizendo com voz que soava como de trovão: \"Vem!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'E vi, e eis um cavalo branco, seu cavaleiro segurava um arco, e a ele foi dada uma coroa. E saiu como um vencedor para vencer.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Quando o Cordeiro abriu o segundo selo, ouvi o segundo ser vivente dizendo: \"Vem!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'E saiu outro cavalo, vermelho, e ao seu cavaleiro foi dada permissão para tirar a paz da terra, para que os homens se matassem uns aos outros, e lhe foi dada uma grande espada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Quando o Cordeiro abriu o terceiro selo, ouvi o terceiro ser vivente dizendo: \"Vem!\" E vi, e eis um cavalo preto e o seu cavaleiro com uma balança em sua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Ouvi o que parecia ser uma voz no meio dos quatro seres viventes, dizendo: \"Uma medida de trigo por um denário, e três medidas de cevada por um denário; e não danifiques o azeite e o vinho\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Quando o Cordeiro abriu o quarto selo, ouvi a voz do quarto ser vivente dizendo: \"Vem!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'E vi, e eis um cavalo amarelo, e o seu cavaleiro foi chamado de Morte, e o Hades o seguia. A eles foi dada autoridade sobre um quarto da terra para matar com espada, com fome, com mortandade, e com os animais selvagens da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Quando o Cordeiro abriu o quinto selo, eu vi debaixo do altar as almas daqueles que foram mortos por causa da Palavra de Deus e do testemunho que tinham.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Eles gritaram em alta voz: \"Até quando, Soberano, santo e verdadeiro, deixarás de julgar aqueles que vivem na terra, e de vingar nosso sangue?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Então, a cada um foi dada uma veste branca, e a eles foi dito que deveriam descansar por mais um pouco de tempo, até que se completasse o número dos seus conservos e seus irmãos que seriam mortos como eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'E vi quando o Cordeiro abriu o sexto selo, e houve um grande terremoto. O sol se tornou escuro como vestes de luto, e a lua se tornou toda como sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'E as estrelas do céu caíram na terra, como a figueira deixa cair seus figos verdes quando sacudida por um vento forte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'O céu foi recolhido como um pergaminho que estava sendo enrolado, e todos os montes e ilhas foram movidos do seu lugar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Então os reis da terra, os grandes, os generais, os ricos, os poderosos, todo escravo e livre esconderam-se nas cavernas e nas pedras dos montes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'E dizem aos montes e às pedras: \"Caí sobre nós! Escondei-nos da face Daquele que está sentado no trono, e da ira do Cordeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Pois o grande dia da ira Deles é chegado, e quem poderá permanecer de pé?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Depois disso, vi quatro anjos em pé nos quatro cantos da terra, retendo os quatro ventos da terra para que o vento não soprasse sobre a terra, nem sobre o mar, nem contra árvore alguma.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'E vi outro anjo subindo do lado do nascente do sol, tendo o selo do Deus vivo. E clamou com alta voz aos quatro anjos que tinham recebido autoridade para danificar a terra e o mar, dizendo:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, '\"Não danifiqueis a terra, nem o mar, nem as árvores até selarmos as testas dos servos do nosso Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Eu escutei o número daqueles que foram selados, que era cento e quarenta e quatro mil, de todas as tribos dos filhos de Israel:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'da tribo de Judá doze mil foram selados; da tribo de Rúben, doze mil; da tribo de Gade, doze mil;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'da tribo de Aser, doze mil; da tribo de Naftali, doze mil; da tribo de Manassés, doze mil;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'da tribo de Simeão, doze mil; da tribo de Levi, doze mil; da tribo de Issacar, doze mil;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'da tribo de Zebulom, doze mil; da tribo de José, doze mil; da tribo de Benjamim doze mil foram selados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Depois dessas coisas, eis que vi uma grande multidão que ninguém podia contar de todas as nações, tribos, povos e línguas, de pé, diante do trono e diante do Cordeiro, usando vestes brancas, com folhas de palmeiras nas suas mãos,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'e clamavam em alta voz, dizendo: \"A salvação pertence ao nosso Deus, que está sentado no trono, e ao Cordeiro!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Todos os anjos estavam de pé, em volta do trono, dos anciãos e dos quatro seres viventes, e se prostraram sobre seus rostos diante do trono, e adoraram a Deus');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'dizendo: \"Amém! O louvor, a glória, a sabedoria, a ação de graças, a honra, o poder e a força pertencem ao nosso Deus, pelos séculos dos séculos! Amém\"!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'E um dos anciãos tomou a palavra, dizendo-me: \"Estes, usando vestes brancas, quem são e de onde vieram?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'E eu lhe disse: \"Meu senhor, tu sabes\". E ele me disse: \"Estes são os que vieram da grande tribulação e lavaram suas vestes e as tornaram brancas no sangue do Cordeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Por isso estão diante do trono de Deus e O servem dia e noite no Seu templo. O que está sentado no trono estenderá Sua tenda sobre eles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Não terão mais fome, nem terão mais sede, nem jamais cairá sobre eles o sol, nem calor algum.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Pois o Cordeiro no meio do trono será o pastor deles, e Ele irá guiá-los às fontes de águas da vida, e Deus enxugará toda lágrima de seus olhos.\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'E, quando o Cordeiro abriu o sétimo selo, houve um silêncio no céu, por cerca de meia hora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Então vi os sete anjos que estão em pé diante de Deus, e lhes foram dadas sete trombetas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'E outro anjo veio segurando um incensário de ouro e ficou em pé junto ao altar. Muito incenso foi-lhe dado para que oferecesse com as orações de todos os santos, sobre o altar dourado diante do trono.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'E da mão do anjo subiu, diante de Deus, a fumaça do incenso juntamente com as orações dos santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'O anjo tomou depois o incensário e o encheu com fogo do altar e o jogou na terra; e houve trovões, clamores, relâmpagos e um terremoto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'E os sete anjos que tinham as sete trombetas prepararam-se para tocá-las.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'O primeiro anjo tocou a sua trombeta, e houve na terra granizo e fogo misturados com sangue: uma terça parte da terra foi queimada, a terça parte das árvores foi queimada, e toda erva verde foi queimada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'O segundo anjo tocou a trombeta, e algo como uma grande montanha ardendo em chamas foi lançado ao mar. E a terça parte do mar se tornou sangue,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'e a terça parte dos seres vivos no mar morreu, e a terça parte das embarcações foi destruída.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'E o terceiro anjo tocou a trombeta, e uma grande estrela caiu do céu, queimando como uma tocha, sobre uma terça parte dos rios e das fontes de água.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'O nome da estrela é Absinto. A terça parte das águas se tornou em absinto, e muitas pessoas morreram por causa das águas que se tornaram amargas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'O quarto anjo tocou a sua trombeta, e a terça parte do sol foi ferida, bem como a terça parte da lua e a terça parte das estrelas. Assim a terça parte deles se tornou escura; a terça parte, tanto do dia como da noite, não brilharam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'E vi e ouvi uma águia voando no meio do céu, clamando em alta voz: \"Ai, ai, ai daqueles que habitam na terra, por causa dos toques restantes de trombeta que ainda estão para ser soados pelos três anjos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Então o quinto anjo tocou a trombeta, e vi uma estrela do céu que havia caído na terra. E foi-lhe dada a chave do poço do abismo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'E abriu o poço do abismo, e subiu fumaça do poço como a fumaça de uma grande fornalha e, com a fumaça do poço, escureceu-se o sol e o ar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'E da fumaça saíram gafanhotos para a terra, e foi-lhes dado poder como o que têm os escorpiões da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'A eles foi ordenado que não danificassem a erva, nem qualquer coisa verde ou árvore, mas somente as pessoas que não tivessem na testa o sinal de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'E não lhes foi permitido matar essas pessoas, mas atormentá-las durante cinco meses. Seu tormento seria como o de uma picada de escorpião quando fere alguém.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Naqueles dias, as pessoas buscarão a morte e não a encontrarão e desejarão a morte, mas a morte fugirá delas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'O aspecto dos gafanhotos era semelhante ao de cavalos preparados para a guerra. Em cima de suas cabeças, havia algo como que coroas de ouro, e os seus rostos pareciam com rostos de pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'E eles tinham cabelos como cabelos de mulheres, e seus dentes eram como dentes de leões;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'tinham couraças como armaduras de ferro, e o som de suas asas era como o som de muitas carruagens que correm para a batalha.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Tinham caudas com ferrões como de escorpiões. Em suas caudas havia poder para causar dano às pessoas por cinco meses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'E tinham como rei sobre eles o anjo do abismo, cujo nome em hebraico era Abadom e, em grego, era Apoliom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'O primeiro ai passou; e eis que depois disso vêm ainda dois ais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'O sexto anjo tocou a trombeta, e ouvi uma voz vinda das quatro pontas do altar de ouro que se encontra diante de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'A voz disse ao sexto anjo que segurava a trombeta: \"Liberte os quatro anjos que estão atados junto ao grande rio Eufrates\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Os quatro anjos que estavam preparados para a hora, o dia, o mês e o ano, foram soltos para matar um terço dos seres humanos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'O número de cavaleiros do exército era de duzentos milhões. Eu ouvi seu número.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Assim, nessa visão, os cavalos e os cavaleiros tinham couraças vermelhas como fogo, azuis como jacinto e amarelas como enxofre. As cabeças dos cavalos eram como cabeças de leão e, de suas bocas saía fogo, fumaça e enxofre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'A terça parte da população foi morta por estas três pragas: o fogo, a fumaça e o enxofre que saíram da boca deles,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'pois o poder dos cavalos estava nas suas bocas e nas suas caudas, porquanto as suas caudas eram como de serpentes; e tinham cabeças com as quais causavam dano ao povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Os demais seres humanos, aqueles que não foram mortos por essas pragas, não se arrependeram das obras de suas mãos, nem deixaram de adorar os demônios e os ídolos de ouro, de prata, de bronze, de pedra e de madeira, que não podem ver, nem ouvir e nem andar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'E não se arrependeram de seus homicidios, nem de suas feitiçarias, nem de suas imoralidades e nem de seus furtos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Então eu vi outro anjo poderoso descendo do céu. Ele estava envolto em uma nuvem, e tinha um arco-íris sobre a sua cabeça. Sua face era como o sol e seus pés como pilares de fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Ele tinha em sua mão um pequeno rolo que estava aberto, e pôs seu pé direito sobre o mar e seu pé esquerdo sobre a terra,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'E bradou em alta voz como um rugido de leão. E, quando ele bradou, os sete trovões falaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Logo que falaram os sete trovões, eu estava prestes a escrever, mas ouvi uma voz do céu, dizendo: \"Guarda em segredo as coisas que os sete trovões falaram, e não as escrevas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Depois disso, o anjo que vi sobre o mar e sobre a terra ergueu sua mão direita ao céu');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'e jurou por Aquele que vive para todo o sempre, o qual criou o céu e tudo o que nele há, a terra e tudo o que nela há, o mar e tudo que nele existe: \"Já não haverá mais demora,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'mas, no dia em que o sétimo anjo estiver prestes a tocar sua trombeta, então o mistério de Deus será cumprido, como anunciou aos seus servos, os profetas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'E a voz que ouvi do céu falou novamente comigo, dizendo: \"Vai, toma o livro que se acha aberto na mão do anjo que está em pé sobre o mar e sobre a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Então fui até o anjo, dizendo-lhe para dar-me o livrinho. Ele me disse: \"Toma-o e come-o; e ele será amargo ao teu estômago, mas em tua boca será tão doce quanto mel\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Tomei o livrinho da mão do anjo e o comi. Era tão doce quanto o mel em minha boca; mas, depois de comê-lo, meu estômago ficou amargo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Então me disseram: \"É necessário que profetizes novamente a muitos povos, nações, línguas e reis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Deram-me um caniço para usar como uma vara de medir. Disseram-me: \"Levanta-te e mede o templo de Deus, o altar e os que nele adoram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Entretanto não meças o pátio externo do templo, pois ele foi dado aos gentios. Eles pisarão a cidade santa por quarenta e dois meses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Eu darei às minhas duas testemunhas autoridade para profetizar, vestidas de saco, por mil duzentos e sessenta dias\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Essas testemunhas são as duas oliveiras e os dois candeiros que estão diante do Senhor da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Se alguém tenta lhes causar dano, fogo sairá de suas bocas, devorando os seus inimigos. Qualquer um que desejar lhes causar dano deverá ser morto dessa maneira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Essas testemunhas têm autoridade para fechar o céu, para que não chova durante o tempo em que elas profetizarem. Elas têm poder para transformar as águas em sangue, e também para ferir a terra com toda sorte de pragas, quantas vezes desejarem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Quando elas concluírem seu testemunho, a besta que sobe do abismo e das profundezas guerreará contra elas. Ela as conquistará e as matará.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Seus corpos ficarão estendidos nas ruas da grande cidade (a qual é chamada simbolicamente de Sodoma e Egito), onde o Senhor delas foi crucificado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Por três dias e meio, pessoas de cada povo, tribo, língua e nação olharão para seus corpos, e não permitirão que sejam sepultados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Os que vivem sobre a terra se alegram por causa delas, e celebram e também enviarão presentes uns aos outros, porque esses dois profetas atormentavam os habitantes da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Após três dias e meio, um fôlego de vida vindo da parte de Deus entrou neles, e eles ficaram de pé. Grande temor caiu sobre todos os que presenciavam isso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Então ouviram uma forte voz, vinda do céu, e disse-lhes: \"Vinde para cá!\" Então, eles subiram para o céu numa nuvem, enquanto seus inimigos os contemplavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Naquele momento, ocorreu um grande terremoto, e a décima parte da cidade foi destruída. Sete mil pessoas morreram no terremoto, e os que sobreviveram ficaram aterrorizados e deram glórias ao Deus do céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'O segundo ai passou. Veja! O terceiro ai vem rapidamente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'O sétimo anjo soou sua trombeta e altas vozes falaram no céu, dizendo: \"O reino deste mundo tornou-se o Reino do nosso Senhor e do Seu Cristo. Ele reinará para sempre e sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Então os vinte e quatro anciãos que estão sentados em seus tronos, na presença de Deus, prostaram-se no chão, com suas faces abaixadas, e adoraram a Deus,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'dizendo: \"Graças Te damos, Senhor Deus, Todo Poderoso, Aquele que era e que é, porque tomaste Teu grande poder e começaste a reinar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'As nações se enfureceram, mas veio Tua ira. O tempo chegou para que os mortos sejam julgados e para que Tu recompenses Teus servos, os profetas, os santos e todos aqueles que temem o Teu nome, tanto os menores quanto os poderosos. O tempo chegou para que Tu destruas todos os que têm destruído a terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Então o templo de Deus, que está no céu, foi aberto e a arca de Sua aliança foi vista dentro do templo. Houve relâmpagos, estrondos, trovões, um terremoto e uma grande chuva de granizo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Um grande sinal foi visto no céu: uma mulher vestida com o sol e com a lua debaixo dos seus pés e uma coroa de doze estrelas na sua cabeça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Ela estava grávida e gritava com as dores do parto, na angústia para dar à luz.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'E outro sinal foi visto no céu: Eis que havia um grande dragão vermelho que tinha sete cabeças e dez chifres, e havia sete coroas nas suas cabeças.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Sua cauda arrastava um terço das estrelas no céu, lançando-as sobre a terra. O dragão ficou diante da mulher que estava para dar à luz, para que, quando ela desse à luz, ele devorasse seu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Ela deu à luz um filho, um menino que governará todas as nações com um cetro de ferro. Seu filho foi arrebatado para junto de Deus e de Seu trono,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'e a mulher fugiu para o deserto, onde Deus havia preparado um lugar para ela, para que ela pudesse ser sustentada por mil duzentos e sessenta dias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Houve então guerra no céu. Miguel e seus anjos lutaram contra o dragão; e o dragão e seus anjos revidaram.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Mas o dragão não foi forte o suficiente para vencer. Então não havia mais lugar no céu para ele e seus anjos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'O grande dragão, aquela antiga serpente chamada diabo ou Satanás, que engana o mundo inteiro, foi expulso para a terra, junto com seus anjos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Então ouvi uma voz alta no céu: \"Agora veio a salvação, o poder, o reino do nosso Deus e a autoridade do Seu Cristo. Pois o acusador de nossos irmãos foi expulso, aquele que os acusava diante do nosso Deus dia e noite.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Eles o venceram por causa do sangue do Cordeiro e pela palavra do testemunho deles, pois eles não amaram suas vidas até à morte.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Portanto alegrai-vos, ó céus, e todos os que neles habitam. Mas ai da terra e do mar, pois o diabo desceu até vós. Ele está coberto de grande furor, pois ele sabe que tem pouco tempo\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Quando o dragão percebeu que havia sido lançado para a terra, ele perseguiu a mulher que havia dado à luz o menino.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Mas à mulher foram dadas as asas de uma grande águia, para que pudesse voar ao lugar preparado para ela no deserto, onde seria sustentada por um tempo, tempos, e metade de um tempo, fora da presença da serpente.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'A serpente derramou água para fora de sua boca como um rio, para que pudesse causar um alagamento e arrastar a mulher de lá.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Mas a terra ajudou a mulher, abrindo sua boca e engolindo o rio que o dragão havia derramado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Então o dragão ficou enfurecido com a mulher e foi guerrear contra o restante dos descendentes dela, aqueles que obedecem os mandamentos de Deus e mantêm o testemunho de Jesus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 18, 'Então o dragão se pôs em pé na areia do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Então vi, saindo do mar, uma besta que tinha dez chifres e sete cabeças. Nos seus chifres, dez coroas, e, em cada cabeça, um nome de blasfêmia.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'A besta que vi era como leopardo, mas tinha pés como os de urso, e sua boca era como de leão. O dragão deu-lhe o seu poder, seu trono e sua grande autoridade para governar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Uma das cabeças da besta parecia ter sofrido um ferimento mortal, mas a ferida foi curada. E toda a terra maravilhou-se e seguiu a besta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'E adoraram o dragão, pois havia dado autoridade à besta. E adorou a besta, dizendo: \"Quem é semelhante à besta?\" e \"Quem pode lutar contra ela?\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Foi dada à besta uma boca que poderia falar palavras orgulhosas e blasfêmias. Foi-lhe permitido exercer autoridade por quarenta e dois meses.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'E abriu a sua boca para falar blasfêmias contra Deus: contra o Seu nome, contra o lugar em que Ele vive e contra aqueles que habitam no céu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Foi permitido à besta guerrear contra os santos e conquistá-los. E foi-lhe dada autoridade sobre toda tribo, povo, língua e nação.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Adoraram-na todos os que habitam sobre a terra, cujos nomes não estão escritos no Livro da Vida que pertence ao Cordeiro, o qual foi morto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Se alguém tem ouvidos, ouça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Se alguém for levado ao cativeiro, ao cativeiro irá. Se alguém for morto à espada, com espada será morto. Eis aqui um chamado à perseverança e à fé para os santos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Então vi outra besta saindo da terra, a qual tinha dois chifres como um cordeiro, e falava como um dragão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Exercia toda a autoridade da primeira besta na sua presença e fazia com que a terra e seus habitantes adorassem a primeira besta, cuja ferida mortal havia sido curada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'E realizava poderosos milagres, chegando a fazer descer fogo do céu à terra, diante das pessoas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Por causa dos sinais que lhe foram permitido fazer, ela enganava os que viviam na terra, dizendo-lhes para fazer uma imagem em honra à besta que havia sido ferida pela espada, mas que voltou à vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Foi-lhe dada permissão para dar fôlego à imagem da besta, para que a imagem pudesse falar e causar a morte a todos os que não adorassem a besta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Ela forçou a todos, pequenos e grandes, ricos e pobres, livres e escravos, a receber uma marca na mão direita ou na testa,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'para que ninguém possa comprar ou vender, exceto aquele que tenha tal marca, que é o número do nome dela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Aqui há sabedoria. Aquele que tem entendimento calcule o número da besta, pois é o número do ser humano, e o seu número é seiscentos e sessenta e seis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'E olhei e vi o Cordeiro em pé sobre o Monte Sião. Com Ele estavam os cento e quarenta e quatro mil, que tinham escritos em suas testas o nome Dele e do Seu Pai.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Ouvi uma voz do céu, um som como o barulho de muitas águas e como de um grande trovão. E a voz que eu ouvi era também como harpistas tocando suas harpas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'Eles cantavam um novo cântico diante do trono, diante dos quatros seres viventes e dos anciãos. Ninguém podia aprender o cântico, exceto os cento e quarenta e quatro mil que foram comprados da terra.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Estes são os que não se contaminaram com mulheres, porque se mantiveram sexualmente puros. São estes que seguem o Cordeiro por onde Ele for. Estes foram comprados dentre a humanidade como primícias para Deus e para o Cordeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'Mentira alguma foi encontrada em suas bocas; eles são irrepreensíveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Eu vi outro anjo voando no meio do céu, que tinha a mensagem eterna, boas novas para proclamar aos que vivem sobre a terra, a toda nação, tribo, língua e povo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Ele proclamava em alta voz: \"Temei a Deus e dai-Lhe glória, pois a hora do Seu juízo chegou. Adorai Aquele que fez o céu, a terra, o mar e as fontes das águas\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Um segundo anjo o seguiu, dizendo: \"Caiu, caiu a grande Babilônia, que persuadiu todas as nações a beberem o vinho da sua paixão imoral\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Seguiu-os ainda um terceiro anjo, falando em alta voz: \"Se alguém adorar a besta e a sua imagem, e receber a marca na testa ou na mão,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'também beberá o vinho do furor de Deus, que foi derramado sem mistura no cálice da Sua ira. E será ainda atormentado com fogo e enxofre diante dos Seus santos anjos e diante do Cordeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'A fumaça do seu tormento sobe para todo o sempre; e não têm descanso, nem de dia e nem de noite, os que adoram a besta e a sua imagem, e todos os que recebem a marca do seu nome.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Aqui está a perseverança dos santos, daqueles que obedecem os mandamentos de Deus e a fé em Jesus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Eu ouvi a voz do céu dizer: \"Escreve: \'Abençoados são os que morrem no Senhor\". \"Sim\", diz o Espírito: \"que eles descansem dos seus trabalhos, pois as suas obras os seguirão\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Olhei, e havia uma nuvem branca e, assentado sobre a nuvem, um semelhante a filho de homem. Ele tinha uma coroa de ouro em sua cabeça e uma foice afiada em sua mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Então outro anjo saiu do templo clamando em alta voz ao que estava assentado sobre a nuvem: \"Pega a tua foice e começa a colheita, pois o seu tempo chegou, a safra da terra está madura para a ceifa\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Então aquele que estava sentado nas nuvens passou sua foice pela terra, e a terra foi ceifada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Outro anjo saiu do templo no céu, trazendo também uma foice afiada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'E saiu do altar outro anjo que tem autoridade sobre o fogo, e clamando em alta voz ao que tinha uma foice afiada: \"Pega a sua foice afiada e colhe os cachos da vinha da terra, pois as suas uvas estão maduras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'E o anjo passou a foice pela terra e colheu as uvas da ceifa e lançou-as no grande lagar da ira de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'O lagar foi pisado fora da cidade e dele saiu sangue até à altura dos freios dos cavalos, numa extensão de mil e seissentos estádios.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Então vi no ceu outro sinal grande e maravilhoso. Havia sete anjos com sete pragas, que são as últimas, pois com elas a ira de Deus estará consumada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Vi algo como um mar de vidro misturado com fogo. Em pé, junto ao mar, estavam aqueles que venceram a besta e a sua imagem, e o número do seu nome. Eles seguravam harpas que lhes foram dadas por Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Eles cantavam o cântico de Moisés, o servo de Deus, e o cântico do Cordeiro: \"Grandes e maravilhosas são as Tuas obras, Senhor Deus, Todo Poderoso. Justos e verdadeiros são os Teus caminhos, Rei das nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Quem não Te temerá, Senhor, e quem não glorificará o Teu nome? Pois somente Tu és santo. Todas as nações virão e adorarão diante de Ti, pois os Teus atos de justiça foram revelados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Depois dessas coisas olhei, e abriu-se no céu o templo da tenda do testemunho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Saíram do santo lugar sete anjos com as setes pragas, vestidos com linho puro e brilhante e com faixas douradas ao redor do peito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Um dos quatro seres viventes deu aos sete anjos sete taças douradas cheias da ira de Deus, que vive para sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'E o templo se encheu da fumaça da glória de Deus e do Seu poder. Ninguém podia entrar nele até que as sete pragas dos sete anjos fossem consumadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'E ouvi uma alta voz vinda do templo, dizendo aos sete anjos: \"Ide e derramai na terra as sete taças da ira de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'O primeiro anjo foi e derramou a sua taça sobre a terra, e úlceras malignas e perniciosas vieram sobre as pessoas que tinham a marca da besta, aquelas que adoravam a sua imagem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'O segundo anjo derramou a sua taça no mar, que se tornou em sangue, como de um morto, e todo ser vivente que havia no mar morreu.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'O terceiro anjo derramou a sua taça nos rios e nas fontes de águas, e se tornaram em sangue.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Ouvi o anjo das águas dizer: \"Tu és Justo, Aquele que é e que era, o Santo, pois julgaste estas coisas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Pois eles derramaram o sangue dos santos e dos profetas, e Tu lhes deste sangue para beber, como eles merecem\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Eu escutei o altar responder: \"Sim, Senhor Deus Todo-Poderoso, os Teus julgamentos são verdadeiros e justos\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'O quarto anjo derramou a sua taça sobre o sol, e foi-lhe dada permissão para queimar os homens com fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Eles foram queimados pelo terrível calor, e blasfemaram o nome de Deus, que tem poder sobre essas pragas, e não se arrependeram para Lhe darem glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'O quinto anjo derramou a sua taça sobre o trono da besta, e escuridão cobriu o seu reino, e os homens mordiam a própria língua por causa da dor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'Eles blasfemaram contra o Deus do céu por causa das suas úlceras, e não se arrependeram pelo que haviam feito.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'O sexto anjo derramou a sua taça no grande rio, o Eufrates, e sua água secou para preparar o caminho para os reis que vêm do lado do nascimento do sol.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Vi três espíritos imundos que pareciam rãs, saindo da boca do dragão, da boca da besta e da boca do falso profeta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Pois eles são espíritos de demônios que fazem sinais miraculosos. Eles vão ao encontro dos reis de todo o mundo, a fim de ajuntá-los para a batalha do grande dia do Deus Todo-Poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '(\"Eis que venho como um ladrão! Abençoado é aquele que permanece vigiando, mantendo suas vestes consigo, para que não saia nu e vejam sua vergonha\".)');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Eles se reuniram no lugar que é chamado em hebraico de Armagedom.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'O sétimo anjo derramou a sua taça no ar. E então uma voz alta saiu do templo e do trono dizendo: \"Está feito!\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Houve relâmpagos, estrondos, trovões, e um terrível terremoto; um terremoto maior do que qualquer um que já tenha ocorrido desde que os homens estão na terra, quão grande foi esse terremoto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'A grande cidade partiu-se em três, e as cidades das nações caíram. Então Deus lembrou-Se da grande Babilônia e deu-lhe o cálice cheio do vinho feito da sua ira furiosa.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Todas as ilhas desapareceram e as montanhas não eram mais encontradas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Grandes pedras de granizo, pesando cerca de um talento, caíram do céu sobre os homens, e eles amaldiçoaram a Deus pela praga de granizo, pois ela foi terrível.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Um dos sete anjos que têm as sete taças veio e falou comigo: \"Vem, eu te mostrarei o juízo da grande prostituta que está sentada sobre muitas águas,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'com quem os reis da terra se prostituíram e, com o vinho da sua imoralidade sexual, os habitantes ficaram bêbados\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'O anjo me levou no espírito ao deserto, e vi uma mulher sentada sobre uma besta vermelha escarlate cheia de nomes de blasfêmias. A besta tinha sete cabeças e dez chifres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'A mulher estava vestida de púrpura e vermelho escarlate, e adornada com ouro, pedras preciosas e pérolas; estava segurando em sua mão um cálice dourado cheio de abominações e impurezas da sua imoralidade sexual.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'Sobre sua testa estava escrito um nome, um mistério: \"A GRANDE BABILÔNIA, A MÃE DAS PROSTITUTAS E DAS ABOMINAÇÕES DA TERRA\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'E vi que a mulher estava embriagada com o sangue dos santos e com o sangue dos mártires por Jesus. Quando eu a vi, eu fiquei grandemente admirado.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Mas o anjo me disse: \"Por que estás admirado? Eu vou te explicar o mistério da mulher e da besta que a carrega, a besta que tem sete cabeças e dez chifres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'A besta que viste, não existe mais, mas está para vir das profundezas do abismo e caminha para a destruição. E aqueles que vivem sobre a terra, cujos nomes não estão escritos no Livro da Vida desde a fundação do mundo, ficarão estupefatos quando eles virem a besta que existiu, não existe agora, mas está para vir.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Aqui é necessário uma mente que tem sabedoria. As sete cabeças são sete montes sobre os quais a mulher está sentada.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Elas são também sete reis. Cinco reis caíram, um existe, e outro ainda não chegou; quando ele vier, ele precisa permanecer por pouco tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'A besta que existiu, mas não existe agora, é ela o oitavo rei, e também um dos sete reis, e caminha para a destruição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Os dez chifres que você viu são dez reis que ainda não receberam um reino, mas eles receberão autoridade como reis, juntamente com a besta, por uma hora.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Eles têm um só pensamento e darão seu poder e autoridade para a besta.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Farão guerra contra o Cordeiro, mas o Cordeiro os vencerá porque Ele é o Senhor dos senhores e Rei dos reis, e com Ele estão os chamados, os escolhidos, os fiéis\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'E o anjo disse-me: \"As águas que tu viste, onde a prostituta está sentada, são povos, multidões, nações e línguas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Os dez chifres que viste e a besta odiarão a prostituta e a deixarão desolada e nua. Eles devorarão a sua carne e a queimarão completamente com fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Pois Deus colocou em seus corações o realizar Seu propósito, fazendo-os concordar em entregar à besta seu poder de governar até que as palavras de Deus sejam cumpridas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'A mulher que viste é a grande cidade que governa sobre os reis da terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Depois dessas coisas, vi outro anjo, descendo do céu, que tinha grande autoridade, e a terra foi iluminada com sua glória.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Ele clamou com uma grande voz, dizendo: \"Caiu! Caiu a grande Babilônia! Ela se tornou morada de demônios, esconderijo para todos os espíritos impuros e aves detestáveis.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Porque todas as nações têm bebido o vinho da sua paixão imoral. Os reis da terra cometeram imoralidades com ela. Os mercadores da terra se enriqueceram pelo poder da sua imoralidade\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Ouvi outra voz do céu, que dizia: \"Saí dela, povo meu, para que não sejais participantes dos seus pecados, e para que não incorrais nas sua pragas;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'porque os seus pecados se empilharam até o céu, e Deus se lembrou de suas ações maléficas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Retribuam-lhe como ela retribuiu aos outros, e paguem-lhe segundo suas obras; no copo que ela misturou, misture em dobro a quantidade para ela.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Como ela glorificou a si mesma e viveu na luxúria, dai-lhe em igual medida tortura e sofrimento. Pois ela diz em seu coração: \'Estou sentada como uma rainha, não sou viúva e nunca verei lamentações.\'');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Portanto, em um único dia, suas pragas virão: morte, lamentações e fome. Ela será queimada pelo fogo, pois o Senhor Deus é poderoso e Ele é o juiz dela\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Os reis da terra que cometeram com ela imoralidades e fez o que eles queriam com ela chorarão e se lamentarão sobre ela quando virem a fumaça do seu incêndio.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Eles permanecerão distantes, com medo do seu tormento, dizendo: \"Ai! Ai! A grande cidade Babilônia, a poderosa! Pois em uma única hora sua punição chegou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Os mercadores da terra choram e pranteiam por ela, já que ninguém compra mais suas mercadorias:');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'mercadorias de ouro, prata, pedras preciosas, pérolas, linho fino, púrpura, seda, escarlata, e todos os tipos de madeiras aromáticas, todo objeto de marfim, de madeira muito preciosa, de bronze, de ferro e de mármore,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'canela, pimenta, mirra e incenso, vinho, óleo, farinha fina, trigo, gado e ovelhas, cavalos e charretes, escravos e até almas humanas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'O fruto que tanto cobiçavas com todo teu poder foi embora de ti. Todo o seu luxo e esplendor desapareceram; nunca serão encontrados.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Os mercadores desses bens, que se tornaram ricos por meio dela, permanecerão distantes por medo do seu tormento, chorando e lamentando alto.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'Eles dirão: \"Ai! Ai! A grande cidade que foi vestida de linho fino, de púrpura e escarlata, e adornada com ouro, pedras preciosas e pérolas!\"');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, '\"Porque, em uma única hora, toda riqueza foi devastada\". Todo piloto, todo marinheiro, e todos os que navegam e trabalham no mar, permaneceram distantes.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'Eles clamaram assim que viram a fumaça do seu incêndio. Disseram: \"Que cidade é igual à grandiosa cidade\"?');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Eles jogaram poeira em suas cabeças e clamaram, chorando e lamentando: \"Ai! Ai da grande cidade, onde todos os que tinham seus navios no mar, tornaram-se ricos por meio dela, pois, em uma única hora, ela foi destruída\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, '\"Alegrai-vos sobre ela, ó céus, vós santos, apóstolos e profetas, pois Deus julgou a vossa causa quanto a ela\"!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Um poderoso anjo pegou uma pedra do tamanho de uma grande pedra de moinho e jogou no mar, dizendo: \"Dessa maneira, Babilônia, a grande cidade, será derrubada com violência e não será vista jamais.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'O som de harpas, músicos, tocadores de flauta, e os que tocam trompete não serão mais ouvidos em ti. Nenhum artesão de qualquer tipo será encontrado em ti. Nenhum som de moinho jamais será ouvido em ti.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'A luz da lâmpada não mais brilhará em ti. A voz do noivo e da noiva não será jamais ouvida em ti, pois teus mercadores foram os príncipes da terra e todas as nações foram enganadas pelas tuas feitiçarias.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Nela foi encontrado sangue de profetas e santos e de todos os que foram mortos na terra\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Depois destas coisas, ouvi no céu como uma forte voz de uma grande multidão, dizendo: \"Louvai a Yahweh! Salvação, glória e poder pertencem ao nosso Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Seus julgamentos são verdadeiros e justos, pois julgou a grande prostituta que corrompeu a terra com a sua imoralidade sexual. Ele tomou vingança pelo sangue dos seus servos, o qual ela mesma derramou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Pela segunda vez, disseram: \"Louvai a Yahweh! A fumaça dela sobe para sempre e sempre\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Os vinte e quatro anciãos e os quatro seres viventes se prostraram e adoraram a Deus, que estava sentado no trono, dizendo: \"Amém. Louvai a Yahweh\"!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Então saiu uma voz do trono, dizendo: \"Louvai ao nosso Deus todos os seus servos, vós que O temeis, tanto pequenos como grandes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Então ouvi uma voz como de uma grande e numerosa multidão, como o rugido de muitas águas e como a voz de fortes trovões, dizendo: \"Louvai a Yahweh! Porque o Senhor, o Deus Todo-Poderoso, reina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Alegremo-nos, exultemos e demos-lhe a glória, porque são chegadas as bodas do Cordeiro, e sua noiva já se preparou\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Foi permitido que ela vestisse de linho fino, puro e resplandecente\" (o linho fino são os atos justos dos santos.)');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'O anjo me disse: \"Escreva isto: Bem aventurados aqueles que são convidados para as bodas do Cordeiro\". E também disse: \"São estas as verdadeiras palavras de Deus\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Prostrei-me ante os seus pés para adorá-lo, porém ele me disse: \"Não faças isso! Eu sou um servo com você e seus irmãos que mantêm o testemunho de Jesus. Adora a Deus, pois o testemunho de Jesus é o espírito da profecia\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Então vi o céu aberto e olhei, e havia um cavalo branco cujo cavaleiro é chamado de Fiel e Verdadeiro. Ele julga e guerreia com justiça.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Seus olhos são como chamas de fogo e, na sua cabeça, há muitos diademas e um nome escrito que ninguém conhece a não ser Ele mesmo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Ele está vestido com um manto tingido de sangue, e seu nome se chama Palavra de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Os exércitos do céu seguiam-no em cavalos brancos, vestidos em linho fino, branco e puro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'De sua boca sai uma espada afiada com a qual Ele fere as nações. Ele as governará com vara de ferro e pisará o lagar da fúria da ira do Deus Todo-Poderoso.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Ele tem um nome escrito no seu manto e na sua coxa: Rei dos reis e Senhor dos senhores.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Vi um anjo em pé, no Sol, que clamava a todas as aves do céu em alta voz dizendo: \"Venham, reúnam-se para a grande ceia de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Venham e comam a carne de reis, a carne de comandantes, a carne de homens poderosos, a carne de cavalos e seus cavaleiros e a carne de todos os homens, quer livres quer escravos, tanto pequenos como grandes\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Vi a besta e os reis da terra com os seus exércitos. Eles estavam se preparando para guerrear contra Aquele que estava montado no cavalo e contra o seu exército.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'A besta foi capturada e, com ela, o falso profeta que realizava os sinais na presença dela. Com esses sinais ele enganou os que receberam a marca da besta e os que adoravam sua imagem. Os dois foram jogados vivos no lago que arde com enxofre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Os demais foram mortos pela espada que saía da boca Daquele que montava no cavalo. Todas as aves se fartaram com a carne de seus cadáveres.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Então vi um anjo descer do céu. Ele tinha a chave do abismo e uma grande corrente na mão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Ele prendeu o dragão, a antiga serpente, a qual é o diabo ou Satanás, e o amarrou por mil anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'Ele o lançou no abismo, fechou-o e pôs um selo sobre ele, para que não mais enganasse as nações até que os mil anos se completassem. Depois disso, ele será solto por um pouco tempo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Então vi tronos, nos quais estavam assentados os que tinham recebido autoridade para julgar. Eu também vi as almas dos que tinham sido decapitados por causa do testemunho de Jesus e da palavra de Deus. Eles não haviam adorado a besta ou sua imagem e se recusaram a receber a marca na testa ou na mão. Eles reviveram e reinaram com Cristo por mil anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Os outros mortos não reviveram até que se completassem os mil anos. Essa é a primeira ressureição.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Bem-aventurado e santo é aquele que faz parte da primeira ressureição! Sobre estes a segunda morte não tem poder. Eles serão sacerdotes de Deus e de Cristo e reinarão com Ele por mil anos.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Quando os mil anos chegarem ao fim, Satanás será solto da sua prisão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'Ele sairá para enganar as nações que estão nos quatro cantos da terra - Gogue e Magogue - a fim de ajuntá-las para a batalha, cujo número será como a areia do mar.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Subiram sobre a ampla superfície da terra e cercaram o acampamento dos santos, a amada cidade. Mas fogo desceu do céu e as devorou.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'O diabo, que os enganava, foi lançado no lago de fogo e enxofre, onde a besta e o falso profeta foram lançados. Eles serão atormentados dia e noite, para sempre e sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Em seguida, vi um grande trono branco e Aquele que estava sentado sobre ele. A terra e o céu fugiram da Sua presença e não havia lugar para irem.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Eu vi os mortos, grandes e pequenos, em pé diante do trono e os livros foram abertos. Então outro livro foi aberto, o Livro da Vida. Os mortos foram julgados segundo o que estava registrado nos livros, segundo as suas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'O mar entregou os mortos que nele havia. A morte e o Hades entregaram também os mortos que neles havia, e os mortos foram julgados segundo as suas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'A morte e o Hades foram jogados no lago de fogo. Esta é a segunda morte, o lago de fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Se o nome de alguém não foi achado escrito no Livro da Vida, esse foi jogado no lago de fogo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Então vi novo céu e nova terra, pois o primeiro céu e a primeira terra passaram, e o mar já não existe.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Eu vi a cidade santa, a nova Jerusalém, que descia do céu de Deus, preparada como uma noiva enfeitada para seu noivo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Ouvi uma grande voz do trono, dizendo: \"Eis a morada de Deus com os homens, e Ele viverá com eles. Eles serão Seu povo, e o próprio Deus estará com eles e será Seu Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Ele enxugará toda lágrima dos seus olhos, e não haverá mais morte, nem luto, nem choro, nem dor, porque já as primeiras coisas são passadas.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Aquele que estava assentado no trono disse: \"Eis que Eu fiz tudo novo\". Ele disse: \"Escreve, porque estas palavras são fiéis e verdadeiras\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Ele me disse: \"Estas coisas estão feitas! Eu sou o Alfa e o Ômega, o Princípio e o Fim. Ao que tem sede darei, sem custo, da fonte da água da vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'O que conquistar herdará essas coisas, e Eu serei seu Deus, e ele será Meu filho.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Mas quanto aos covardes, aos incrédulos, aos detestáveis, aos assassinos, aos sexualmente imoral, aos feiticeiros, aos idólatras, e a todos os mentirosos, o lugar deles será no lago que arde com fogo e enxofre. Essa é a segunda morte\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Um dos sete anjos veio a mim, o que tinha as sete taças cheias das sete últimas pragas, e disse: \"Vem aqui. Eu te mostrarei a noiva, a esposa do Cordeiro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Então me levou, em espírito, para uma grande e alta montanha, e mostrou-me a cidade santa, Jerusalém, que descia do céu de Deus.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Jerusalém tinha a glória de Deus, e brilhava como uma joia muito preciosa, como uma pedra de jaspe cristalina.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Lá havia um grande e alto muro com doze portões, com doze anjos nos portões, nos quais estavam escritos os nomes das doze tribos dos filhos de Israel.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'A leste, havia três portões; ao norte, três; ao sul, três; e a oeste, três portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'A muralha da cidade tinha doze fundamentos, e nela estava o nome dos doze apóstolos do Cordeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'O que falava comigo tinha uma vara de medir, de ouro, para medir a cidade, suas portas e seus muros.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'A cidade era quadrangular, seu comprimento era igual a sua largura. Mediu a cidade com a vara e a cidade tinha doze mil estádios de comprimento e o mesmo de largura e de altura.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Ele também mediu os muros: cento e quarenta e quatro côvados, segundo a medida humana, que era também a medida que os anjos usavam.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'O muro é de jaspe, e a cidade de ouro puro, semelhante ao vidro límpido.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Os fundamentos do muro estão adornados com todo tipo de pedras preciosas. O primeiro é de jaspe; o segundo, de safira; o terceiro, de calcedônia; o quarto, de esmeralda;');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'o quinto, de sardônica; o sexto, de sárdio; o sétimo, de crisólito; o oitavo, de berilo; o nono, de topázio; o décimo, de crisópraso; o décimo primeiro, de jacinto; o décimo segundo, de ametista.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Os doze portões são doze pérolas, e cada portão é feito de uma única pérola. As ruas da cidade são de ouro puro, transparente como vidro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Eu não vi nenhum templo na cidade, porque o Senhor Deus Poderoso e o Cordeiro são o seu templo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'A cidade não precisa do sol ou da lua para iluminá-la, porque a glória de Deus a iluminava, e a sua lâmpada é o Cordeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'As nações andarão na sua luz. Os reis da terra trarão para ela seu resplendor.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Os portões não se fecharão de dia, e não haverá noite ali.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'Eles trarão para ela a glória e a honra das nações,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'e não entrará nela coisa alguma que contamine, e cometa abominação e mentira, mas apenas aqueles cujos nomes estão escritos no Livro da Vida do Cordeiro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Então o anjo me mostrou o rio da água da vida, transparente como cristal, que fluía do trono de Deus e do Cordeiro,');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'no meio da rua da cidade. Em cada margem do rio, está a árvore da vida, que produz doze frutos, dando seu fruto de mês em mês. As folhas da árvore são para a cura das nações.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Ali jamais haverá maldição. O trono de Deus e do Cordeiro estará na cidade e os Seus servos O servirão.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'Eles verão Sua face e o Nome de Deus estará na testa deles.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Não haverá mais noite, e eles não precisarão da luz da lâmpada e nem da luz do sol, porque o Senhor Deus brilhará sobre eles, e reinarão para sempre e sempre.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'O anjo me disse: \"Estas palavras são fiéis e verdadeiras. O Senhor Deus dos espíritos dos profetas mandou Seu anjo para mostrar aos Seus servos o que deve acontecer em breve\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, '\"Olha! Eis que venho sem demora! Bem-aventurado é o que obedece às palavras da profecia deste livro\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Eu, João, sou o que ouviu e viu essas coisas. Quando ouvi e vi isso, prostrei-me aos pés do anjo que me mostrou essas coisas, para adorá-lo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Ele me disse: \"Não faças isso! Eu estou ao serviço de Deus como tu e como os teus irmãos, os profetas, e daqueles que obedecem às palavras deste livro. Adora a Deus\"!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Ele me disse: \"Não seles as palavras da profecia deste livro, porque o tempo está próximo.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Aquele que é injusto continue fazendo injustiça. Aquele que é impuro continue na impureza. Aquele que é justo continue fazendo o que é justo. Aquele que é santo, seja santificado ainda\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, '\"Olhe! Eis que venho sem demora. Minha recompensa está Comigo para retribuir a cada um segundo as suas obras.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Eu sou o Alfa e o Ômega, o Primeiro e o Último, o Começo e o Fim.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Bem-aventurados os que lavam suas vestes para que tenham o direito de comer da árvore da vida e entrar na cidade através dos portões.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Ficarão de fora os cães, os feiticeiros, os sexualmente imorais, os assassinos, os idólatras e todos os que amam e praticam a mentira.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Eu, Jesus, mandei Meu anjo para vos testemunhar essas coisas em favor das igrejas. Eu sou a raiz e a descendência de Davi, a brilhante Estrela da Manhã\".');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'O Espírito e a Noiva dizem: \"Vem\"! Aquele que ouve diga: \"Vem\"! Todo aquele que tem sede venha, e todo o que desejar, receba gratuitamente da água da vida.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Eu testemunho a todos os que ouvem as palavras da profecia deste livro: Se alguém acrescentar algo, Deus acrescentará a ele as pragas escritas neste livro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'Se alguém tirar as palavras da profecia deste livro, Deus tirará a sua parte da árvore da vida e da cidade santa, as quais estão escritas neste livro.');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Aquele que testemunha estas coisas diz: \"Sim! Eis que venho sem demora\". Amém! Vem, Senhor Jesus!');
INSERT INTO `PorNVA_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Que a graça do Senhor Jesus esteja com todos. Amém.');
